INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (1, 1, 'Which of the following is a natural number: -3, 0, 4, or 1/2?', 'text', 1, 'Natural numbers start at 1.', '{"why":"Natural numbers are positive counting numbers beginning with 1.","sol":"Step 1: Natural numbers are 1, 2, 3, 4, ...\nStep 2: -3 is negative.\nStep 3: 0 is not included in this classification.\nStep 4: 1/2 is a fraction.\nStep 5: 4 belongs to the natural numbers.","steps":["Step 1: Natural numbers are 1, 2, 3, 4, ...","Step 2: -3 is negative.","Step 3: 0 is not included in this classification.","Step 4: 1/2 is a fraction.","Step 5: 4 belongs to the natural numbers."],"options":[],"conceptId":"math_numbers_number_systems","skillId":"math_numbers","subskillId":"math_numbers_q1","subject":"math","chapter":"numbers","topic":"Number Systems"}', 0),
  (2, 1, 'Is 0 a natural number, whole number, or integer?', 'text', 1, 'Remember which sets include zero.', '{"why":"Whole numbers include 0, and integers include negative numbers, zero, and positive numbers.","sol":"Step 1: 0 is not a natural number in this classification.\nStep 2: Whole numbers include 0.\nStep 3: Integers also include 0.","steps":["Step 1: 0 is not a natural number in this classification.","Step 2: Whole numbers include 0.","Step 3: Integers also include 0."],"options":[],"conceptId":"math_numbers_number_systems","skillId":"math_numbers","subskillId":"math_numbers_q2","subject":"math","chapter":"numbers","topic":"Number Systems"}', 1),
  (3, 1, 'Which type of number is -8?', 'text', 1, 'Look at its sign.', '{"why":"-8 belongs to the set of integers because integers include negative whole-number values.","sol":"Step 1: -8 is less than zero.\nStep 2: Negative numbers are not natural or whole numbers.\nStep 3: Negative whole-number values belong to the integers.","steps":["Step 1: -8 is less than zero.","Step 2: Negative numbers are not natural or whole numbers.","Step 3: Negative whole-number values belong to the integers."],"options":[],"conceptId":"math_numbers_number_systems","skillId":"math_numbers","subskillId":"math_numbers_q3","subject":"math","chapter":"numbers","topic":"Number Systems"}', 2),
  (4, 1, 'Which is greater: -3 or -7?', 'text', 1, 'Think about their positions on the number line.', '{"why":"-3 is closer to zero and is therefore greater than -7.","sol":"Step 1: Locate -3 and -7 on the number line.\nStep 2: -3 is to the right of -7.\nStep 3: A number farther right is greater.","steps":["Step 1: Locate -3 and -7 on the number line.","Step 2: -3 is to the right of -7.","Step 3: A number farther right is greater."],"options":[],"conceptId":"math_numbers_number_systems","skillId":"math_numbers","subskillId":"math_numbers_q4","subject":"math","chapter":"numbers","topic":"Number Systems"}', 3),
  (5, 1, 'Arrange these integers from smallest to largest: 3, -2, 0, -5, 1.', 'text', 1, 'Start with the most negative number.', '{"why":"Numbers increase as we move from left to right on the number line.","sol":"Step 1: The smallest number is -5.\nStep 2: Next is -2.\nStep 3: Then comes 0.\nStep 4: Then 1.\nStep 5: Finally, 3.","steps":["Step 1: The smallest number is -5.","Step 2: Next is -2.","Step 3: Then comes 0.","Step 4: Then 1.","Step 5: Finally, 3."],"options":[],"conceptId":"math_numbers_number_systems","skillId":"math_numbers","subskillId":"math_numbers_q5","subject":"math","chapter":"numbers","topic":"Number Systems"}', 4),
  (6, 1, 'Calculate: -6 + 4', 'text', 1, 'Start at -6 and move 4 units to the right.', '{"why":"Adding 4 to -6 moves four units toward zero, giving -2.","sol":"Step 1: Start with -6.\nStep 2: Add 4.\nStep 3: -6 + 4 = -2.","steps":["Step 1: Start with -6.","Step 2: Add 4.","Step 3: -6 + 4 = -2."],"options":[],"conceptId":"math_numbers_number_systems","skillId":"math_numbers","subskillId":"math_numbers_q6","subject":"math","chapter":"numbers","topic":"Number Systems"}', 5),
  (7, 1, 'Calculate: 5 - 9', 'text', 1, 'Subtracting a larger number from a smaller number gives a negative result.', '{"why":"5 is 4 less than 9, so 5 - 9 = -4.","sol":"Step 1: Start with 5.\nStep 2: Subtract 9.\nStep 3: 5 - 9 = -4.","steps":["Step 1: Start with 5.","Step 2: Subtract 9.","Step 3: 5 - 9 = -4."],"options":[],"conceptId":"math_numbers_number_systems","skillId":"math_numbers","subskillId":"math_numbers_q7","subject":"math","chapter":"numbers","topic":"Number Systems"}', 6),
  (8, 1, 'Calculate: -4 × -3', 'text', 1, 'Look at the signs.', '{"why":"Two negative signs produce a positive result, and 4 × 3 = 12.","sol":"Step 1: The numbers have the same sign.\nStep 2: Negative × Negative gives Positive.\nStep 3: 4 × 3 = 12.","steps":["Step 1: The numbers have the same sign.","Step 2: Negative × Negative gives Positive.","Step 3: 4 × 3 = 12."],"options":[],"conceptId":"math_numbers_number_systems","skillId":"math_numbers","subskillId":"math_numbers_q8","subject":"math","chapter":"numbers","topic":"Number Systems"}', 7),
  (9, 1, 'Calculate: -20 ÷ 5', 'text', 1, 'Look at the signs before dividing.', '{"why":"Different signs give a negative result, and 20 ÷ 5 = 4.","sol":"Step 1: Negative ÷ Positive gives Negative.\nStep 2: 20 ÷ 5 = 4.\nStep 3: Therefore, -20 ÷ 5 = -4.","steps":["Step 1: Negative ÷ Positive gives Negative.","Step 2: 20 ÷ 5 = 4.","Step 3: Therefore, -20 ÷ 5 = -4."],"options":[],"conceptId":"math_numbers_number_systems","skillId":"math_numbers","subskillId":"math_numbers_q9","subject":"math","chapter":"numbers","topic":"Number Systems"}', 8),
  (10, 1, 'Which statement is correct?', 'text', 1, 'Think about how the number sets are contained.', '{"why":"The natural-number set is contained inside the whole-number set, which is contained inside the integers.","sol":"Step 1: Natural numbers are contained in whole numbers.\nStep 2: Whole numbers are contained in integers.\nStep 3: Therefore, Natural Numbers ⊂ Whole Numbers ⊂ Integers.","steps":["Step 1: Natural numbers are contained in whole numbers.","Step 2: Whole numbers are contained in integers.","Step 3: Therefore, Natural Numbers ⊂ Whole Numbers ⊂ Integers."],"options":[],"conceptId":"math_numbers_number_systems","skillId":"math_numbers","subskillId":"math_numbers_q10","subject":"math","chapter":"numbers","topic":"Number Systems"}', 9),
  (11, 2, 'Solve: 6 + 2 × 3', 'text', 1, 'Multiplication comes before addition.', '{"why":"Multiplication has priority over addition, so 2 × 3 is calculated first.","sol":"Step 1: Identify multiplication and addition.\nStep 2: Calculate 2 × 3 = 6.\nStep 3: Calculate 6 + 6 = 12.","steps":["Step 1: Identify multiplication and addition.","Step 2: Calculate 2 × 3 = 6.","Step 3: Calculate 6 + 6 = 12."],"options":[],"conceptId":"math_numbers_bodmas_order_of_operations","skillId":"math_numbers","subskillId":"math_numbers_q1","subject":"math","chapter":"numbers","topic":"BODMAS / Order of Operations"}', 0),
  (12, 2, 'Solve: 20 - 12 ÷ 3', 'text', 1, 'Division comes before subtraction.', '{"why":"Division is performed before subtraction.","sol":"Step 1: Calculate 12 ÷ 3 = 4.\nStep 2: Calculate 20 - 4 = 16.","steps":["Step 1: Calculate 12 ÷ 3 = 4.","Step 2: Calculate 20 - 4 = 16."],"options":[],"conceptId":"math_numbers_bodmas_order_of_operations","skillId":"math_numbers","subskillId":"math_numbers_q2","subject":"math","chapter":"numbers","topic":"BODMAS / Order of Operations"}', 1),
  (13, 2, 'Solve: (7 + 5) × 2', 'text', 1, 'Start with the brackets.', '{"why":"Brackets are calculated before multiplication.","sol":"Step 1: Calculate 7 + 5 = 12.\nStep 2: Calculate 12 × 2 = 24.","steps":["Step 1: Calculate 7 + 5 = 12.","Step 2: Calculate 12 × 2 = 24."],"options":[],"conceptId":"math_numbers_bodmas_order_of_operations","skillId":"math_numbers","subskillId":"math_numbers_q3","subject":"math","chapter":"numbers","topic":"BODMAS / Order of Operations"}', 2),
  (14, 2, 'Solve: 3 + 2²', 'text', 1, 'Calculate the order before addition.', '{"why":"Orders such as powers are calculated before addition.","sol":"Step 1: Calculate 2² = 4.\nStep 2: Calculate 3 + 4 = 7.","steps":["Step 1: Calculate 2² = 4.","Step 2: Calculate 3 + 4 = 7."],"options":[],"conceptId":"math_numbers_bodmas_order_of_operations","skillId":"math_numbers","subskillId":"math_numbers_q4","subject":"math","chapter":"numbers","topic":"BODMAS / Order of Operations"}', 3),
  (15, 2, 'Solve: 24 ÷ 3 × 2', 'text', 1, 'Division and multiplication have equal priority. Work left to right.', '{"why":"Division and multiplication have equal priority, so they are evaluated from left to right.","sol":"Step 1: Start from the left: 24 ÷ 3 = 8.\nStep 2: Continue left to right: 8 × 2 = 16.","steps":["Step 1: Start from the left: 24 ÷ 3 = 8.","Step 2: Continue left to right: 8 × 2 = 16."],"options":[],"conceptId":"math_numbers_bodmas_order_of_operations","skillId":"math_numbers","subskillId":"math_numbers_q5","subject":"math","chapter":"numbers","topic":"BODMAS / Order of Operations"}', 4),
  (16, 2, 'Solve: 15 - 6 + 2', 'text', 1, 'Addition and subtraction have equal priority.', '{"why":"Addition and subtraction have equal priority, so they are evaluated from left to right.","sol":"Step 1: Start from the left: 15 - 6 = 9.\nStep 2: Continue left to right: 9 + 2 = 11.","steps":["Step 1: Start from the left: 15 - 6 = 9.","Step 2: Continue left to right: 9 + 2 = 11."],"options":[],"conceptId":"math_numbers_bodmas_order_of_operations","skillId":"math_numbers","subskillId":"math_numbers_q6","subject":"math","chapter":"numbers","topic":"BODMAS / Order of Operations"}', 5),
  (17, 2, 'Solve: 8 + 2 × (5 - 3)²', 'text', 1, 'Follow the order: brackets, orders, multiplication, addition.', '{"why":"The expression follows BODMAS: brackets, orders, multiplication, then addition.","sol":"Step 1: (5 - 3) = 2.\nStep 2: 2² = 4.\nStep 3: 2 × 4 = 8.\nStep 4: 8 + 8 = 16.","steps":["Step 1: (5 - 3) = 2.","Step 2: 2² = 4.","Step 3: 2 × 4 = 8.","Step 4: 8 + 8 = 16."],"options":[],"conceptId":"math_numbers_bodmas_order_of_operations","skillId":"math_numbers","subskillId":"math_numbers_q7","subject":"math","chapter":"numbers","topic":"BODMAS / Order of Operations"}', 6),
  (18, 2, 'Solve: 2 × [3 + (4 - 1)]', 'text', 1, 'Solve the innermost brackets first.', '{"why":"Nested brackets are solved from the innermost bracket outward.","sol":"Step 1: 4 - 1 = 3.\nStep 2: 3 + 3 = 6.\nStep 3: 2 × 6 = 12.","steps":["Step 1: 4 - 1 = 3.","Step 2: 3 + 3 = 6.","Step 3: 2 × 6 = 12."],"options":[],"conceptId":"math_numbers_bodmas_order_of_operations","skillId":"math_numbers","subskillId":"math_numbers_q8","subject":"math","chapter":"numbers","topic":"BODMAS / Order of Operations"}', 7),
  (19, 2, 'A student solves 10 + 4 × 2 as (10 + 4) × 2. What did the student do wrong?', 'text', 1, 'Check which operation should be performed first.', '{"why":"The multiplication must be performed before the addition, so the correct answer is 18.","sol":"Step 1: Multiplication has priority over addition.\nStep 2: Calculate 4 × 2 = 8.\nStep 3: Calculate 10 + 8 = 18.","steps":["Step 1: Multiplication has priority over addition.","Step 2: Calculate 4 × 2 = 8.","Step 3: Calculate 10 + 8 = 18."],"options":[],"conceptId":"math_numbers_bodmas_order_of_operations","skillId":"math_numbers","subskillId":"math_numbers_q9","subject":"math","chapter":"numbers","topic":"BODMAS / Order of Operations"}', 8),
  (20, 2, 'Solve: 18 ÷ 3 × 2', 'text', 1, 'Do not automatically multiply first.', '{"why":"Division and multiplication have equal priority and are evaluated from left to right.","sol":"Step 1: Division and multiplication have equal priority.\nStep 2: Work from left to right: 18 ÷ 3 = 6.\nStep 3: 6 × 2 = 12.","steps":["Step 1: Division and multiplication have equal priority.","Step 2: Work from left to right: 18 ÷ 3 = 6.","Step 3: 6 × 2 = 12."],"options":[],"conceptId":"math_numbers_bodmas_order_of_operations","skillId":"math_numbers","subskillId":"math_numbers_q10","subject":"math","chapter":"numbers","topic":"BODMAS / Order of Operations"}', 9),
  (21, 3, 'Is 4,572 divisible by 3?', 'text', 1, 'Sum the digits', '{"why":"A number is divisible by 3 if the sum of its digits is divisible by 3 (4 + 5 + 7 + 2 = 18 = 3 × 6).","sol":"Step 1: Compute sum of digits: 4 + 5 + 7 + 2 = 18\nStep 2: Check if 18 is divisible by 3: 18 ÷ 3 = 6 (no remainder)\nStep 3: Conclude: 4,572 is divisible by 3","steps":["Step 1: Compute sum of digits: 4 + 5 + 7 + 2 = 18","Step 2: Check if 18 is divisible by 3: 18 ÷ 3 = 6 (no remainder)","Step 3: Conclude: 4,572 is divisible by 3"],"options":[],"conceptId":"math_numbers_divisibility_rules","skillId":"math_numbers","subskillId":"math_numbers_q1","subject":"math","chapter":"numbers","topic":"Divisibility Rules"}', 0),
  (22, 3, 'Determine if 3,524 is divisible by 4.', 'text', 1, 'Check last two digits', '{"why":"A number is divisible by 4 if the number formed by its last two digits is divisible by 4 (24 ÷ 4 = 6).","sol":"Step 1: Identify the last two digits: 24\nStep 2: Check if 24 is divisible by 4: 24 ÷ 4 = 6\nStep 3: Conclude: 3,524 is divisible by 4","steps":["Step 1: Identify the last two digits: 24","Step 2: Check if 24 is divisible by 4: 24 ÷ 4 = 6","Step 3: Conclude: 3,524 is divisible by 4"],"options":[],"conceptId":"math_numbers_divisibility_rules","skillId":"math_numbers","subskillId":"math_numbers_q2","subject":"math","chapter":"numbers","topic":"Divisibility Rules"}', 1),
  (23, 3, 'Is 1,236 divisible by 6?', 'text', 1, 'Check divisibility by both 2 and 3', '{"why":"Divisibility by 6 requires the number to be even and the sum of its digits to be a multiple of 3.","sol":"Step 1: Check divisibility by 2: last digit is 6 (even) → divisible by 2\nStep 2: Check divisibility by 3: 1 + 2 + 3 + 6 = 12, and 12 ÷ 3 = 4 → divisible by 3\nStep 3: Conclude: Since divisible by both 2 and 3, it is divisible by 6","steps":["Step 1: Check divisibility by 2: last digit is 6 (even) → divisible by 2","Step 2: Check divisibility by 3: 1 + 2 + 3 + 6 = 12, and 12 ÷ 3 = 4 → divisible by 3","Step 3: Conclude: Since divisible by both 2 and 3, it is divisible by 6"],"options":[],"conceptId":"math_numbers_divisibility_rules","skillId":"math_numbers","subskillId":"math_numbers_q3","subject":"math","chapter":"numbers","topic":"Divisibility Rules"}', 2),
  (24, 3, 'Find the smallest single digit x such that 5,3x2 is divisible by 9.', 'text', 1, 'Sum of digits must be a multiple of 9', '{"why":"Sum of digits is 5 + 3 + x + 2 = 10 + x. The smallest single digit making this divisible by 9 is x = 8 (sum = 18).","sol":"Step 1: Calculate sum of known digits: 5 + 3 + 2 = 10\nStep 2: Set equation: 10 + x = 18 (next multiple of 9)\nStep 3: Solve for x: x = 18 - 10 = 8","steps":["Step 1: Calculate sum of known digits: 5 + 3 + 2 = 10","Step 2: Set equation: 10 + x = 18 (next multiple of 9)","Step 3: Solve for x: x = 18 - 10 = 8"],"options":[],"conceptId":"math_numbers_divisibility_rules","skillId":"math_numbers","subskillId":"math_numbers_q4","subject":"math","chapter":"numbers","topic":"Divisibility Rules"}', 3),
  (25, 4, 'Calculate 17 mod 5.', 'text', 1, 'Find remainder when 17 is divided by 5', '{"why":"17 divided by 5 yields quotient 3 with remainder 2.","sol":"Step 1: Divide 17 by 5: 17 = 5 × 3 + 2\nStep 2: Identify quotient (3) and remainder (2)\nStep 3: Conclude: 17 mod 5 = 2","steps":["Step 1: Divide 17 by 5: 17 = 5 × 3 + 2","Step 2: Identify quotient (3) and remainder (2)","Step 3: Conclude: 17 mod 5 = 2"],"options":[],"conceptId":"math_numbers_modular_arithmetic","skillId":"math_numbers","subskillId":"math_numbers_q1","subject":"math","chapter":"numbers","topic":"Modular Arithmetic"}', 0),
  (26, 4, 'Evaluate (14 + 23) mod 6.', 'text', 1, 'Add then take modulo, or take modulo first', '{"why":"14 + 23 = 37. 37 = 6 × 6 + 1, so 37 mod 6 = 1.","sol":"Step 1: 14 mod 6 = 2, and 23 mod 6 = 5\nStep 2: Add remainders: 2 + 5 = 7\nStep 3: Reduce modulo 6: 7 mod 6 = 1","steps":["Step 1: 14 mod 6 = 2, and 23 mod 6 = 5","Step 2: Add remainders: 2 + 5 = 7","Step 3: Reduce modulo 6: 7 mod 6 = 1"],"options":[],"conceptId":"math_numbers_modular_arithmetic","skillId":"math_numbers","subskillId":"math_numbers_q2","subject":"math","chapter":"numbers","topic":"Modular Arithmetic"}', 1),
  (27, 4, 'Find (7 × 8) mod 5.', 'text', 1, 'Multiply then divide by 5', '{"why":"56 divided by 5 gives remainder 1.","sol":"Step 1: Compute product: 7 × 8 = 56\nStep 2: Divide 56 by 5: 56 = 5 × 11 + 1\nStep 3: Conclude: 56 mod 5 = 1","steps":["Step 1: Compute product: 7 × 8 = 56","Step 2: Divide 56 by 5: 56 = 5 × 11 + 1","Step 3: Conclude: 56 mod 5 = 1"],"options":[],"conceptId":"math_numbers_modular_arithmetic","skillId":"math_numbers","subskillId":"math_numbers_q3","subject":"math","chapter":"numbers","topic":"Modular Arithmetic"}', 2),
  (28, 4, 'Find 3^4 mod 7.', 'text', 1, 'Compute powers step by step', '{"why":"3^4 = 81. 81 = 7 × 11 + 4, so 81 mod 7 = 4.","sol":"Step 1: 3^2 = 9 ≡ 2 (mod 7)\nStep 2: 3^4 = (3^2)^2 ≡ 2^2 (mod 7)\nStep 3: 2^2 = 4 (mod 7)","steps":["Step 1: 3^2 = 9 ≡ 2 (mod 7)","Step 2: 3^4 = (3^2)^2 ≡ 2^2 (mod 7)","Step 3: 2^2 = 4 (mod 7)"],"options":[],"conceptId":"math_numbers_modular_arithmetic","skillId":"math_numbers","subskillId":"math_numbers_q4","subject":"math","chapter":"numbers","topic":"Modular Arithmetic"}', 3),
  (29, 5, 'What is the only even prime number?', 'text', 1, 'Smallest prime', '{"why":"2 is the smallest prime and the only even prime number, because any larger even number is divisible by 2.","sol":"Step 1: Check even numbers: 2, 4, 6, 8...\nStep 2: 2 has only divisors 1 and 2 → prime\nStep 3: Any even number > 2 is divisible by 2 → composite. ∴ 2 is the only even prime","steps":["Step 1: Check even numbers: 2, 4, 6, 8...","Step 2: 2 has only divisors 1 and 2 → prime","Step 3: Any even number > 2 is divisible by 2 → composite. ∴ 2 is the only even prime"],"options":[],"conceptId":"math_numbers_prime_numbers","skillId":"math_numbers","subskillId":"math_numbers_q1","subject":"math","chapter":"numbers","topic":"Prime Numbers"}', 0),
  (30, 5, 'Find the prime factorization of 60.', 'text', 1, 'Break into prime factors', '{"why":"60 = 4 × 15 = (2 × 2) × (3 × 5) = 2² × 3 × 5.","sol":"Step 1: 60 = 2 × 30\nStep 2: 30 = 2 × 15\nStep 3: 15 = 3 × 5\nStep 4: Combine prime factors: 2 × 2 × 3 × 5 = 2² × 3 × 5","steps":["Step 1: 60 = 2 × 30","Step 2: 30 = 2 × 15","Step 3: 15 = 3 × 5","Step 4: Combine prime factors: 2 × 2 × 3 × 5 = 2² × 3 × 5"],"options":[],"conceptId":"math_numbers_prime_numbers","skillId":"math_numbers","subskillId":"math_numbers_q2","subject":"math","chapter":"numbers","topic":"Prime Numbers"}', 1),
  (31, 5, 'Is 29 a prime or composite number?', 'text', 1, 'Check divisibility by primes ≤ √29 ≈ 5.38 (2, 3, 5)', '{"why":"29 has no divisors other than 1 and itself, making it prime.","sol":"Step 1: Check primes up to √29: 2, 3, 5\nStep 2: 29 is not divisible by 2 (odd), 3 (2+9=11), or 5 (ends in 9)\nStep 3: Conclude: 29 has no divisors other than 1 and 29 → Prime","steps":["Step 1: Check primes up to √29: 2, 3, 5","Step 2: 29 is not divisible by 2 (odd), 3 (2+9=11), or 5 (ends in 9)","Step 3: Conclude: 29 has no divisors other than 1 and 29 → Prime"],"options":[],"conceptId":"math_numbers_prime_numbers","skillId":"math_numbers","subskillId":"math_numbers_q3","subject":"math","chapter":"numbers","topic":"Prime Numbers"}', 2),
  (32, 5, 'Find the greatest common divisor (GCD) of 24 and 36 using prime factorization.', 'text', 1, 'Take lowest power of common prime factors', '{"why":"GCD(24, 36) = 2² × 3 = 12.","sol":"Step 1: Prime factorize: 24 = 2³ × 3¹, 36 = 2² × 3²\nStep 2: Identify common prime factors: 2 and 3\nStep 3: Take minimum powers: 2² × 3¹ = 4 × 3 = 12","steps":["Step 1: Prime factorize: 24 = 2³ × 3¹, 36 = 2² × 3²","Step 2: Identify common prime factors: 2 and 3","Step 3: Take minimum powers: 2² × 3¹ = 4 × 3 = 12"],"options":[],"conceptId":"math_numbers_prime_numbers","skillId":"math_numbers","subskillId":"math_numbers_q4","subject":"math","chapter":"numbers","topic":"Prime Numbers"}', 3),
  (33, 6, 'Solve the linear congruence: 2x ≡ 6 (mod 8) for 0 ≤ x < 8.', 'text', 1, 'Check integers 0 through 7 or divide by gcd', '{"why":"2(3) = 6 ≡ 6 (mod 8) and 2(7) = 14 ≡ 6 (mod 8).","sol":"Step 1: Note gcd(2, 8) = 2. Since 2 divides 6, there are 2 incongruent solutions\nStep 2: Divide congruence by 2: x ≡ 3 (mod 4)\nStep 3: Find values in range 0 ≤ x < 8: x = 3 and x = 3 + 4 = 7","steps":["Step 1: Note gcd(2, 8) = 2. Since 2 divides 6, there are 2 incongruent solutions","Step 2: Divide congruence by 2: x ≡ 3 (mod 4)","Step 3: Find values in range 0 ≤ x < 8: x = 3 and x = 3 + 4 = 7"],"options":[],"conceptId":"math_numbers_congruence_relations","skillId":"math_numbers","subskillId":"math_numbers_q1","subject":"math","chapter":"numbers","topic":"Congruence Relations"}', 0),
  (34, 6, 'Is 38 ≡ 14 (mod 8)?', 'text', 1, 'Check if (38 - 14) is divisible by 8', '{"why":"38 - 14 = 24, which is a multiple of 8 (8 × 3 = 24).","sol":"Step 1: Calculate difference: 38 - 14 = 24\nStep 2: Check divisibility by 8: 24 ÷ 8 = 3 (exact integer)\nStep 3: Conclude: 38 ≡ 14 (mod 8) is True","steps":["Step 1: Calculate difference: 38 - 14 = 24","Step 2: Check divisibility by 8: 24 ÷ 8 = 3 (exact integer)","Step 3: Conclude: 38 ≡ 14 (mod 8) is True"],"options":[],"conceptId":"math_numbers_congruence_relations","skillId":"math_numbers","subskillId":"math_numbers_q2","subject":"math","chapter":"numbers","topic":"Congruence Relations"}', 1),
  (35, 6, 'Find the modular inverse of 3 modulo 7.', 'text', 1, 'Find integer x such that 3x ≡ 1 (mod 7)', '{"why":"3 × 5 = 15 ≡ 1 (mod 7), so 5 is the modular multiplicative inverse of 3 modulo 7.","sol":"Step 1: Test multiples of 3 modulo 7: 3(1)=3, 3(2)=6, 3(3)=9 ≡ 2, 3(4)=12\nStep 2: 12 mod 7 = 5; next test 3(5) = 15\nStep 3: 15 mod 7 = 1 (since 15 = 2 × 7 + 1). ∴ inverse is 5","steps":["Step 1: Test multiples of 3 modulo 7: 3(1)=3, 3(2)=6, 3(3)=9 ≡ 2, 3(4)=12","Step 2: 12 mod 7 = 5; next test 3(5) = 15","Step 3: 15 mod 7 = 1 (since 15 = 2 × 7 + 1). ∴ inverse is 5"],"options":[],"conceptId":"math_numbers_congruence_relations","skillId":"math_numbers","subskillId":"math_numbers_q3","subject":"math","chapter":"numbers","topic":"Congruence Relations"}', 2),
  (36, 7, 'A boy walks 600 m from home to school. What is the distance travelled?', 'text', 1, 'Distance tells how far the boy travelled.', '{"why":"Distance is the total length of the path travelled.","sol":"Step 1: The boy travels from home to school.\nStep 2: The given length is 600 m.\nStep 3: Therefore, the distance travelled is 600 m.","steps":["Step 1: The boy travels from home to school.","Step 2: The given length is 600 m.","Step 3: Therefore, the distance travelled is 600 m."],"options":[],"conceptId":"math_linear_motion_distance","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Distance"}', 0),
  (37, 7, 'A runner travels 400 m and then another 300 m. Find the total distance.', 'text', 1, 'Add both sections of the path.', '{"why":"Both sections form part of the total path travelled.","sol":"Step 1: First section = 400 m.\nStep 2: Second section = 300 m.\nStep 3: Total distance = 400 + 300.\nStep 4: Total distance = 700 m.","steps":["Step 1: First section = 400 m.","Step 2: Second section = 300 m.","Step 3: Total distance = 400 + 300.","Step 4: Total distance = 700 m."],"options":[],"conceptId":"math_linear_motion_distance","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Distance"}', 1),
  (38, 7, 'A cyclist travels 5 km, then 2 km, then 3 km. Find the total distance.', 'text', 1, 'Add every section travelled.', '{"why":"Total distance is the sum of all parts of the path.","sol":"Step 1: First section = 5 km.\nStep 2: Second section = 2 km.\nStep 3: Third section = 3 km.\nStep 4: Total distance = 5 + 2 + 3 = 10 km.","steps":["Step 1: First section = 5 km.","Step 2: Second section = 2 km.","Step 3: Third section = 3 km.","Step 4: Total distance = 5 + 2 + 3 = 10 km."],"options":[],"conceptId":"math_linear_motion_distance","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Distance"}', 2),
  (39, 7, 'What does distance measure in a motion problem?', 'text', 1, 'Think about how far the object travels.', '{"why":"Distance measures how far an object travels, without considering direction.","sol":"Step 1: An object follows a path when it moves.\nStep 2: Distance measures the length of that path.\nStep 3: Therefore, distance tells how far the object travelled.","steps":["Step 1: An object follows a path when it moves.","Step 2: Distance measures the length of that path.","Step 3: Therefore, distance tells how far the object travelled."],"options":[],"conceptId":"math_linear_motion_distance","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Distance"}', 3),
  (40, 8, 'A car moves 60 km east from A to B. What is its displacement?', 'text', 1, 'State both the size and direction of the change in position.', '{"why":"Displacement describes the change in position together with direction.","sol":"Step 1: The car starts at A.\nStep 2: It finishes 60 km east of A.\nStep 3: Therefore, its displacement is 60 km east.","steps":["Step 1: The car starts at A.","Step 2: It finishes 60 km east of A.","Step 3: Therefore, its displacement is 60 km east."],"options":[],"conceptId":"math_linear_motion_displacement","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Displacement"}', 0),
  (41, 8, 'A cyclist moves 5 km west from P to Q. What is the displacement?', 'text', 1, 'The direction of movement is west.', '{"why":"Displacement must include the direction of the change in position.","sol":"Step 1: The cyclist starts at P.\nStep 2: The cyclist finishes 5 km west of P.\nStep 3: Therefore, displacement = 5 km west.","steps":["Step 1: The cyclist starts at P.","Step 2: The cyclist finishes 5 km west of P.","Step 3: Therefore, displacement = 5 km west."],"options":[],"conceptId":"math_linear_motion_displacement","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Displacement"}', 1),
  (42, 8, 'A runner completes a 400 m lap and finishes exactly where they started. Find the displacement.', 'text', 1, 'Compare the starting position with the final position.', '{"why":"There is no change in position when the object finishes where it started.","sol":"Step 1: The runner starts at one point.\nStep 2: After one complete lap, the runner returns to that same point.\nStep 3: The starting and final positions are identical.\nStep 4: Therefore, displacement = 0 m.","steps":["Step 1: The runner starts at one point.","Step 2: After one complete lap, the runner returns to that same point.","Step 3: The starting and final positions are identical.","Step 4: Therefore, displacement = 0 m."],"options":[],"conceptId":"math_linear_motion_displacement","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Displacement"}', 2),
  (43, 8, 'A person moves 2 km north. State the displacement.', 'text', 1, 'Include both magnitude and direction.', '{"why":"Displacement requires both magnitude and direction.","sol":"Step 1: The person changes position by 2 km.\nStep 2: The direction is north.\nStep 3: Therefore, displacement = 2 km north.","steps":["Step 1: The person changes position by 2 km.","Step 2: The direction is north.","Step 3: Therefore, displacement = 2 km north."],"options":[],"conceptId":"math_linear_motion_displacement","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Displacement"}', 3),
  (44, 9, 'A car travels 70 km east in a straight line. State its distance and displacement.', 'text', 1, 'The car moves in one direction only.', '{"why":"For straight movement in one direction, distance equals the magnitude of displacement.","sol":"Step 1: The total path travelled is 70 km.\nStep 2: The final position is 70 km east of the start.\nStep 3: Distance = 70 km.\nStep 4: Displacement = 70 km east.","steps":["Step 1: The total path travelled is 70 km.","Step 2: The final position is 70 km east of the start.","Step 3: Distance = 70 km.","Step 4: Displacement = 70 km east."],"options":[],"conceptId":"math_linear_motion_distance_and_displacement_compared","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Distance and Displacement Compared"}', 0),
  (45, 9, 'A student walks 3 km north and then 3 km south. Find the distance and displacement.', 'text', 1, 'Calculate the whole path first, then compare start and finish.', '{"why":"The student travels 6 km but finishes at the starting position.","sol":"Step 1: Distance = 3 + 3 = 6 km.\nStep 2: The student returns to the starting position.\nStep 3: Therefore, displacement = 0 km.","steps":["Step 1: Distance = 3 + 3 = 6 km.","Step 2: The student returns to the starting position.","Step 3: Therefore, displacement = 0 km."],"options":[],"conceptId":"math_linear_motion_distance_and_displacement_compared","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Distance and Displacement Compared"}', 1),
  (46, 9, 'A cyclist travels 4 km east and then 1 km east. Find the distance and displacement.', 'text', 1, 'Both parts are in the same direction.', '{"why":"Both movements increase the cyclist''s position in the same direction.","sol":"Step 1: Distance = 4 + 1 = 5 km.\nStep 2: The cyclist finishes 5 km east of the start.\nStep 3: Displacement = 5 km east.","steps":["Step 1: Distance = 4 + 1 = 5 km.","Step 2: The cyclist finishes 5 km east of the start.","Step 3: Displacement = 5 km east."],"options":[],"conceptId":"math_linear_motion_distance_and_displacement_compared","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Distance and Displacement Compared"}', 2),
  (47, 9, 'Can displacement be zero while distance is greater than zero?', 'text', 1, 'Think about an object returning to its starting point.', '{"why":"Returning to the starting position makes displacement zero even though a distance was travelled.","sol":"Step 1: An object can move away from its starting point.\nStep 2: It can then return to the same starting point.\nStep 3: The distance travelled is greater than zero.\nStep 4: The starting and final positions are the same, so displacement is zero.","steps":["Step 1: An object can move away from its starting point.","Step 2: It can then return to the same starting point.","Step 3: The distance travelled is greater than zero.","Step 4: The starting and final positions are the same, so displacement is zero."],"options":[],"conceptId":"math_linear_motion_distance_and_displacement_compared","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Distance and Displacement Compared"}', 3),
  (48, 10, 'A car travels 180 km in 3 hours. Find its speed.', 'text', 1, 'Use speed = distance ÷ time.', '{"why":"Speed tells us the distance covered per unit of time.","sol":"Step 1: Distance = 180 km.\nStep 2: Time = 3 h.\nStep 3: Speed = 180 ÷ 3.\nStep 4: Speed = 60 km/h.","steps":["Step 1: Distance = 180 km.","Step 2: Time = 3 h.","Step 3: Speed = 180 ÷ 3.","Step 4: Speed = 60 km/h."],"options":[],"conceptId":"math_linear_motion_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Speed"}', 0),
  (49, 10, 'A cyclist travels 100 km in 5 hours. Find the speed.', 'text', 1, 'Divide the distance by the time.', '{"why":"Dividing distance by time gives the rate at which distance is covered.","sol":"Step 1: Distance = 100 km.\nStep 2: Time = 5 h.\nStep 3: Speed = 100 ÷ 5.\nStep 4: Speed = 20 km/h.","steps":["Step 1: Distance = 100 km.","Step 2: Time = 5 h.","Step 3: Speed = 100 ÷ 5.","Step 4: Speed = 20 km/h."],"options":[],"conceptId":"math_linear_motion_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Speed"}', 1),
  (50, 10, 'A bus travels 360 km in 6 hours. Find its speed.', 'text', 1, 'Substitute distance and time into s = d/t.', '{"why":"Speed is the distance travelled for each hour of the journey.","sol":"Step 1: Distance = 360 km.\nStep 2: Time = 6 h.\nStep 3: Speed = 360 ÷ 6.\nStep 4: Speed = 60 km/h.","steps":["Step 1: Distance = 360 km.","Step 2: Time = 6 h.","Step 3: Speed = 360 ÷ 6.","Step 4: Speed = 60 km/h."],"options":[],"conceptId":"math_linear_motion_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Speed"}', 2),
  (51, 10, 'A runner covers 20 km in 2 hours. Find the runner''s speed.', 'text', 1, 'Divide 20 km by 2 hours.', '{"why":"Speed is calculated by dividing distance by time.","sol":"Step 1: Distance = 20 km.\nStep 2: Time = 2 h.\nStep 3: Speed = 20 ÷ 2.\nStep 4: Speed = 10 km/h.","steps":["Step 1: Distance = 20 km.","Step 2: Time = 2 h.","Step 3: Speed = 20 ÷ 2.","Step 4: Speed = 10 km/h."],"options":[],"conceptId":"math_linear_motion_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Speed"}', 3),
  (52, 11, 'A car travels 50 km in 1 hour and 70 km in 2 hours. Find its average speed.', 'text', 1, 'Find total distance and total time first.', '{"why":"Average speed uses the total distance and total time for the whole journey.","sol":"Step 1: Total distance = 50 + 70 = 120 km.\nStep 2: Total time = 1 + 2 = 3 h.\nStep 3: Average speed = 120 ÷ 3.\nStep 4: Average speed = 40 km/h.","steps":["Step 1: Total distance = 50 + 70 = 120 km.","Step 2: Total time = 1 + 2 = 3 h.","Step 3: Average speed = 120 ÷ 3.","Step 4: Average speed = 40 km/h."],"options":[],"conceptId":"math_linear_motion_average_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Average Speed"}', 0),
  (53, 11, 'A cyclist travels 40 km in 2 hours and 20 km in 1 hour. Find the average speed.', 'text', 1, 'Add the distances and add the times.', '{"why":"Average speed is total distance divided by total time.","sol":"Step 1: Total distance = 40 + 20 = 60 km.\nStep 2: Total time = 2 + 1 = 3 h.\nStep 3: Average speed = 60 ÷ 3.\nStep 4: Average speed = 20 km/h.","steps":["Step 1: Total distance = 40 + 20 = 60 km.","Step 2: Total time = 2 + 1 = 3 h.","Step 3: Average speed = 60 ÷ 3.","Step 4: Average speed = 20 km/h."],"options":[],"conceptId":"math_linear_motion_average_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Average Speed"}', 1),
  (54, 11, 'A bus travels 100 km to a town in 2 hours and returns 100 km in 3 hours. Find its average speed.', 'text', 1, 'The total distance is 200 km and the total time is 5 hours.', '{"why":"The whole journey must be considered when calculating average speed.","sol":"Step 1: Total distance = 100 + 100 = 200 km.\nStep 2: Total time = 2 + 3 = 5 h.\nStep 3: Average speed = 200 ÷ 5.\nStep 4: Average speed = 40 km/h.","steps":["Step 1: Total distance = 100 + 100 = 200 km.","Step 2: Total time = 2 + 3 = 5 h.","Step 3: Average speed = 200 ÷ 5.","Step 4: Average speed = 40 km/h."],"options":[],"conceptId":"math_linear_motion_average_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Average Speed"}', 2),
  (55, 11, 'A journey covers 90 km in 3 hours. What is the average speed?', 'text', 1, 'For one constant journey, divide distance by time.', '{"why":"Average speed is total distance divided by total time.","sol":"Step 1: Total distance = 90 km.\nStep 2: Total time = 3 h.\nStep 3: Average speed = 90 ÷ 3.\nStep 4: Average speed = 30 km/h.","steps":["Step 1: Total distance = 90 km.","Step 2: Total time = 3 h.","Step 3: Average speed = 90 ÷ 3.","Step 4: Average speed = 30 km/h."],"options":[],"conceptId":"math_linear_motion_average_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Average Speed"}', 3),
  (56, 12, 'A car travels at 70 km/h east. State its velocity.', 'text', 1, 'Velocity includes speed and direction.', '{"why":"Velocity requires both magnitude and direction.","sol":"Step 1: Speed = 70 km/h.\nStep 2: Direction = east.\nStep 3: Therefore, velocity = 70 km/h east.","steps":["Step 1: Speed = 70 km/h.","Step 2: Direction = east.","Step 3: Therefore, velocity = 70 km/h east."],"options":[],"conceptId":"math_linear_motion_velocity","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Velocity"}', 0),
  (57, 12, 'A train moves at 90 km/h south. State its velocity.', 'text', 1, 'Include the direction south.', '{"why":"The direction distinguishes velocity from speed.","sol":"Step 1: Speed = 90 km/h.\nStep 2: Direction = south.\nStep 3: Therefore, velocity = 90 km/h south.","steps":["Step 1: Speed = 90 km/h.","Step 2: Direction = south.","Step 3: Therefore, velocity = 90 km/h south."],"options":[],"conceptId":"math_linear_motion_velocity","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Velocity"}', 1),
  (58, 12, 'Is 40 km/h a complete statement of velocity?', 'text', 1, 'Ask whether a direction has been given.', '{"why":"A velocity must specify direction.","sol":"Step 1: 40 km/h gives the magnitude of motion.\nStep 2: No direction is specified.\nStep 3: Therefore, it describes speed, not a complete velocity.","steps":["Step 1: 40 km/h gives the magnitude of motion.","Step 2: No direction is specified.","Step 3: Therefore, it describes speed, not a complete velocity."],"options":[],"conceptId":"math_linear_motion_velocity","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Velocity"}', 2),
  (59, 12, 'A cyclist moves at 30 km/h west. What is the speed and what is the velocity?', 'text', 1, 'Speed has no direction; velocity includes direction.', '{"why":"Velocity is speed together with direction.","sol":"Step 1: The speed is 30 km/h.\nStep 2: The direction is west.\nStep 3: Therefore, velocity is 30 km/h west.","steps":["Step 1: The speed is 30 km/h.","Step 2: The direction is west.","Step 3: Therefore, velocity is 30 km/h west."],"options":[],"conceptId":"math_linear_motion_velocity","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Velocity"}', 3),
  (60, 13, 'A car moves 100 km east in 2 hours. Find its average velocity.', 'text', 1, 'Use displacement ÷ time.', '{"why":"Average velocity uses displacement divided by total time.","sol":"Step 1: Displacement = 100 km east.\nStep 2: Time = 2 h.\nStep 3: Average velocity = 100 ÷ 2.\nStep 4: Average velocity = 50 km/h east.","steps":["Step 1: Displacement = 100 km east.","Step 2: Time = 2 h.","Step 3: Average velocity = 100 ÷ 2.","Step 4: Average velocity = 50 km/h east."],"options":[],"conceptId":"math_linear_motion_average_velocity","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Average Velocity"}', 0),
  (61, 13, 'A runner returns to the starting point after 3 hours. What is the average velocity?', 'text', 1, 'The displacement is zero.', '{"why":"Returning to the starting point gives zero displacement.","sol":"Step 1: The runner finishes at the starting position.\nStep 2: Displacement = 0 km.\nStep 3: Average velocity = 0 ÷ 3.\nStep 4: Average velocity = 0 km/h.","steps":["Step 1: The runner finishes at the starting position.","Step 2: Displacement = 0 km.","Step 3: Average velocity = 0 ÷ 3.","Step 4: Average velocity = 0 km/h."],"options":[],"conceptId":"math_linear_motion_average_velocity","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Average Velocity"}', 1),
  (62, 13, 'A cyclist travels 60 km west in 3 hours. Find the average velocity.', 'text', 1, 'Include the direction west.', '{"why":"Average velocity includes the direction of displacement.","sol":"Step 1: Displacement = 60 km west.\nStep 2: Time = 3 h.\nStep 3: Average velocity = 60 ÷ 3.\nStep 4: Average velocity = 20 km/h west.","steps":["Step 1: Displacement = 60 km west.","Step 2: Time = 3 h.","Step 3: Average velocity = 60 ÷ 3.","Step 4: Average velocity = 20 km/h west."],"options":[],"conceptId":"math_linear_motion_average_velocity","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Average Velocity"}', 2),
  (63, 13, 'What quantity is used to calculate average velocity: distance or displacement?', 'text', 1, 'Velocity describes a change in position.', '{"why":"Average velocity is total displacement divided by total time.","sol":"Step 1: Velocity includes direction.\nStep 2: Displacement includes direction.\nStep 3: Therefore, average velocity uses displacement.","steps":["Step 1: Velocity includes direction.","Step 2: Displacement includes direction.","Step 3: Therefore, average velocity uses displacement."],"options":[],"conceptId":"math_linear_motion_average_velocity","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Average Velocity"}', 3),
  (64, 14, 'A car changes velocity from 10 m/s to 30 m/s in 5 s. Find its acceleration.', 'text', 1, 'Use a = (v - u)/t.', '{"why":"Acceleration measures the change in velocity per unit time.","sol":"Step 1: u = 10 m/s.\nStep 2: v = 30 m/s.\nStep 3: Change in velocity = 30 - 10 = 20 m/s.\nStep 4: Acceleration = 20 ÷ 5 = 4 m/s².","steps":["Step 1: u = 10 m/s.","Step 2: v = 30 m/s.","Step 3: Change in velocity = 30 - 10 = 20 m/s.","Step 4: Acceleration = 20 ÷ 5 = 4 m/s²."],"options":[],"conceptId":"math_linear_motion_acceleration","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Acceleration"}', 0),
  (65, 14, 'A bicycle changes velocity from 4 m/s to 16 m/s in 6 s. Find its acceleration.', 'text', 1, 'Subtract the initial velocity from the final velocity first.', '{"why":"Acceleration is the change in velocity divided by time.","sol":"Step 1: u = 4 m/s.\nStep 2: v = 16 m/s.\nStep 3: Change in velocity = 16 - 4 = 12 m/s.\nStep 4: Acceleration = 12 ÷ 6 = 2 m/s².","steps":["Step 1: u = 4 m/s.","Step 2: v = 16 m/s.","Step 3: Change in velocity = 16 - 4 = 12 m/s.","Step 4: Acceleration = 12 ÷ 6 = 2 m/s²."],"options":[],"conceptId":"math_linear_motion_acceleration","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Acceleration"}', 1),
  (66, 14, 'A car changes velocity from 20 m/s to 8 m/s in 4 s. Find its acceleration.', 'text', 1, 'Final velocity minus initial velocity gives a negative change.', '{"why":"The negative acceleration shows that velocity is decreasing in the chosen direction.","sol":"Step 1: u = 20 m/s.\nStep 2: v = 8 m/s.\nStep 3: Change in velocity = 8 - 20 = -12 m/s.\nStep 4: Acceleration = -12 ÷ 4 = -3 m/s².","steps":["Step 1: u = 20 m/s.","Step 2: v = 8 m/s.","Step 3: Change in velocity = 8 - 20 = -12 m/s.","Step 4: Acceleration = -12 ÷ 4 = -3 m/s²."],"options":[],"conceptId":"math_linear_motion_acceleration","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Acceleration"}', 2),
  (67, 14, 'What does acceleration measure?', 'text', 1, 'Think about what happens to velocity as time passes.', '{"why":"Acceleration tells us how quickly velocity changes with time.","sol":"Step 1: Velocity can change during motion.\nStep 2: Acceleration measures how quickly that velocity changes.\nStep 3: Therefore, acceleration is change in velocity per unit time.","steps":["Step 1: Velocity can change during motion.","Step 2: Acceleration measures how quickly that velocity changes.","Step 3: Therefore, acceleration is change in velocity per unit time."],"options":[],"conceptId":"math_linear_motion_acceleration","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Acceleration"}', 3),
  (68, 15, 'A car slows from 30 m/s to 20 m/s in 5 s. Find its acceleration.', 'text', 1, 'Use final velocity minus initial velocity.', '{"why":"The negative acceleration represents a decrease in velocity.","sol":"Step 1: u = 30 m/s.\nStep 2: v = 20 m/s.\nStep 3: Change = 20 - 30 = -10 m/s.\nStep 4: Acceleration = -10 ÷ 5 = -2 m/s².","steps":["Step 1: u = 30 m/s.","Step 2: v = 20 m/s.","Step 3: Change = 20 - 30 = -10 m/s.","Step 4: Acceleration = -10 ÷ 5 = -2 m/s²."],"options":[],"conceptId":"math_linear_motion_deceleration","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Deceleration"}', 0),
  (69, 15, 'A bus slows from 40 m/s to 16 m/s in 6 s. Find its acceleration.', 'text', 1, 'Subtract 40 from 16, then divide by 6.', '{"why":"Velocity decreases by 24 m/s during the 6 seconds.","sol":"Step 1: u = 40 m/s.\nStep 2: v = 16 m/s.\nStep 3: Change = 16 - 40 = -24 m/s.\nStep 4: Acceleration = -24 ÷ 6 = -4 m/s².","steps":["Step 1: u = 40 m/s.","Step 2: v = 16 m/s.","Step 3: Change = 16 - 40 = -24 m/s.","Step 4: Acceleration = -24 ÷ 6 = -4 m/s²."],"options":[],"conceptId":"math_linear_motion_deceleration","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Deceleration"}', 1),
  (70, 15, 'A motorcycle slows from 18 m/s to 6 m/s in 3 s. Find its acceleration.', 'text', 1, 'A decrease in velocity produces a negative change.', '{"why":"The negative sign indicates that the velocity is decreasing.","sol":"Step 1: u = 18 m/s.\nStep 2: v = 6 m/s.\nStep 3: Change = 6 - 18 = -12 m/s.\nStep 4: Acceleration = -12 ÷ 3 = -4 m/s².","steps":["Step 1: u = 18 m/s.","Step 2: v = 6 m/s.","Step 3: Change = 6 - 18 = -12 m/s.","Step 4: Acceleration = -12 ÷ 3 = -4 m/s²."],"options":[],"conceptId":"math_linear_motion_deceleration","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Deceleration"}', 2),
  (71, 15, 'What does a negative acceleration mean in these examples?', 'text', 1, 'Look at what happened to the velocity.', '{"why":"A negative change in velocity produces negative acceleration in the chosen direction.","sol":"Step 1: The final velocity is smaller than the initial velocity.\nStep 2: Therefore, v - u is negative.\nStep 3: The negative acceleration represents a decrease in velocity in the chosen direction.","steps":["Step 1: The final velocity is smaller than the initial velocity.","Step 2: Therefore, v - u is negative.","Step 3: The negative acceleration represents a decrease in velocity in the chosen direction."],"options":[],"conceptId":"math_linear_motion_deceleration","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Deceleration"}', 3),
  (72, 16, 'A point on a distance-time graph is (3 h, 150 km). What distance has been travelled?', 'text', 1, 'Distance is read from the vertical coordinate.', '{"why":"Distance is represented on the vertical axis.","sol":"Step 1: The point is (3 h, 150 km).\nStep 2: The second coordinate represents distance.\nStep 3: Therefore, distance = 150 km.","steps":["Step 1: The point is (3 h, 150 km).","Step 2: The second coordinate represents distance.","Step 3: Therefore, distance = 150 km."],"options":[],"conceptId":"math_linear_motion_reading_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Reading a Distance-Time Graph"}', 0),
  (73, 16, 'A point on a distance-time graph is (4 h, 200 km). What time does it represent?', 'text', 1, 'Time is represented on the horizontal axis.', '{"why":"Time is represented on the horizontal axis.","sol":"Step 1: The point is (4 h, 200 km).\nStep 2: The first coordinate represents time.\nStep 3: Therefore, time = 4 h.","steps":["Step 1: The point is (4 h, 200 km).","Step 2: The first coordinate represents time.","Step 3: Therefore, time = 4 h."],"options":[],"conceptId":"math_linear_motion_reading_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Reading a Distance-Time Graph"}', 1),
  (74, 16, 'At 6 hours, a graph shows a distance of 360 km. State the point on the graph.', 'text', 1, 'Write the point as (time, distance).', '{"why":"The horizontal coordinate is time and the vertical coordinate is distance.","sol":"Step 1: Time = 6 h.\nStep 2: Distance = 360 km.\nStep 3: A point is written as (time, distance).\nStep 4: Therefore, the point is (6 h, 360 km).","steps":["Step 1: Time = 6 h.","Step 2: Distance = 360 km.","Step 3: A point is written as (time, distance).","Step 4: Therefore, the point is (6 h, 360 km)."],"options":[],"conceptId":"math_linear_motion_reading_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Reading a Distance-Time Graph"}', 2),
  (75, 16, 'Which quantity belongs on the horizontal axis of a distance-time graph?', 'text', 1, 'Think about which quantity is allowed to pass as the motion happens.', '{"why":"A distance-time graph shows how distance changes with time.","sol":"Step 1: Time passes during motion.\nStep 2: Distance changes as time passes.\nStep 3: Therefore, time is placed on the horizontal axis.","steps":["Step 1: Time passes during motion.","Step 2: Distance changes as time passes.","Step 3: Therefore, time is placed on the horizontal axis."],"options":[],"conceptId":"math_linear_motion_reading_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Reading a Distance-Time Graph"}', 3),
  (76, 17, 'A distance-time graph goes from (0 h, 0 km) to (4 h, 200 km). Find its gradient.', 'text', 1, 'Gradient = change in distance ÷ change in time.', '{"why":"The gradient of a distance-time graph represents speed.","sol":"Step 1: Change in distance = 200 - 0 = 200 km.\nStep 2: Change in time = 4 - 0 = 4 h.\nStep 3: Gradient = 200 ÷ 4.\nStep 4: Gradient = 50 km/h.","steps":["Step 1: Change in distance = 200 - 0 = 200 km.","Step 2: Change in time = 4 - 0 = 4 h.","Step 3: Gradient = 200 ÷ 4.","Step 4: Gradient = 50 km/h."],"options":[],"conceptId":"math_linear_motion_gradient_of_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Gradient of a Distance-Time Graph"}', 0),
  (77, 17, 'A graph passes through (2 h, 40 km) and (5 h, 160 km). Find the gradient.', 'text', 1, 'Subtract corresponding coordinates first.', '{"why":"Gradient is change in distance divided by change in time.","sol":"Step 1: Change in distance = 160 - 40 = 120 km.\nStep 2: Change in time = 5 - 2 = 3 h.\nStep 3: Gradient = 120 ÷ 3.\nStep 4: Gradient = 40 km/h.","steps":["Step 1: Change in distance = 160 - 40 = 120 km.","Step 2: Change in time = 5 - 2 = 3 h.","Step 3: Gradient = 120 ÷ 3.","Step 4: Gradient = 40 km/h."],"options":[],"conceptId":"math_linear_motion_gradient_of_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Gradient of a Distance-Time Graph"}', 1),
  (78, 17, 'A distance-time graph has a gradient of 60 km/h. What does this tell you about the object''s speed?', 'text', 1, 'The gradient represents speed.', '{"why":"Gradient on a distance-time graph gives speed.","sol":"Step 1: For a distance-time graph, gradient represents speed.\nStep 2: The gradient is 60 km/h.\nStep 3: Therefore, the object''s speed is 60 km/h.","steps":["Step 1: For a distance-time graph, gradient represents speed.","Step 2: The gradient is 60 km/h.","Step 3: Therefore, the object''s speed is 60 km/h."],"options":[],"conceptId":"math_linear_motion_gradient_of_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Gradient of a Distance-Time Graph"}', 2),
  (79, 17, 'Which object is faster: one with a distance-time gradient of 30 km/h or one with 50 km/h?', 'text', 1, 'A larger gradient means greater speed.', '{"why":"A greater gradient represents a greater speed.","sol":"Step 1: First object''s speed = 30 km/h.\nStep 2: Second object''s speed = 50 km/h.\nStep 3: 50 km/h is greater than 30 km/h.\nStep 4: Therefore, the second object is faster.","steps":["Step 1: First object''s speed = 30 km/h.","Step 2: Second object''s speed = 50 km/h.","Step 3: 50 km/h is greater than 30 km/h.","Step 4: Therefore, the second object is faster."],"options":[],"conceptId":"math_linear_motion_gradient_of_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Gradient of a Distance-Time Graph"}', 3),
  (80, 18, 'A distance-time graph is horizontal from 2 h to 5 h. What is happening?', 'text', 1, 'A horizontal line means distance is not changing.', '{"why":"A horizontal distance-time graph means there is no change in distance.","sol":"Step 1: The distance remains constant.\nStep 2: Time continues to pass.\nStep 3: Therefore, the object is stationary.","steps":["Step 1: The distance remains constant.","Step 2: Time continues to pass.","Step 3: Therefore, the object is stationary."],"options":[],"conceptId":"math_linear_motion_interpreting_a_horizontal_section_of_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Interpreting a Horizontal Section of a Distance-Time Graph"}', 0),
  (81, 18, 'An object is stationary from 4 h to 6 h. How long is it stationary?', 'text', 1, 'Subtract the starting time from the ending time.', '{"why":"The length of a stationary period is the difference between the two times.","sol":"Step 1: Starting time = 4 h.\nStep 2: Ending time = 6 h.\nStep 3: Time = 6 - 4 = 2 h.","steps":["Step 1: Starting time = 4 h.","Step 2: Ending time = 6 h.","Step 3: Time = 6 - 4 = 2 h."],"options":[],"conceptId":"math_linear_motion_interpreting_a_horizontal_section_of_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Interpreting a Horizontal Section of a Distance-Time Graph"}', 1),
  (82, 18, 'A horizontal section runs from 1.5 h to 2.5 h. How long is the stationary period?', 'text', 1, 'Calculate 2.5 - 1.5.', '{"why":"The object remains at the same distance for the one-hour interval.","sol":"Step 1: Starting time = 1.5 h.\nStep 2: Ending time = 2.5 h.\nStep 3: Time = 2.5 - 1.5 = 1 h.","steps":["Step 1: Starting time = 1.5 h.","Step 2: Ending time = 2.5 h.","Step 3: Time = 2.5 - 1.5 = 1 h."],"options":[],"conceptId":"math_linear_motion_interpreting_a_horizontal_section_of_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Interpreting a Horizontal Section of a Distance-Time Graph"}', 2),
  (83, 18, 'What does a horizontal line on a distance-time graph tell us about speed?', 'text', 1, 'If distance is not changing, what is the rate of change of distance?', '{"why":"No change in distance over time means zero speed.","sol":"Step 1: Speed is change in distance divided by time.\nStep 2: A horizontal line means change in distance is zero.\nStep 3: Therefore, speed is zero.","steps":["Step 1: Speed is change in distance divided by time.","Step 2: A horizontal line means change in distance is zero.","Step 3: Therefore, speed is zero."],"options":[],"conceptId":"math_linear_motion_interpreting_a_horizontal_section_of_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Interpreting a Horizontal Section of a Distance-Time Graph"}', 3),
  (84, 19, 'A car travels at 70 km/h for 3 hours. Find the distance.', 'text', 1, 'Use d = st.', '{"why":"Distance is found by multiplying speed by time.","sol":"Step 1: Speed = 70 km/h.\nStep 2: Time = 3 h.\nStep 3: Distance = 70 × 3.\nStep 4: Distance = 210 km.","steps":["Step 1: Speed = 70 km/h.","Step 2: Time = 3 h.","Step 3: Distance = 70 × 3.","Step 4: Distance = 210 km."],"options":[],"conceptId":"math_linear_motion_distance_speed_time_relationship","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Distance-Speed-Time Relationship"}', 0),
  (85, 19, 'A cyclist travels at 20 km/h for 5 hours. Find the distance.', 'text', 1, 'Multiply 20 by 5.', '{"why":"The cyclist covers 20 km in each hour for 5 hours.","sol":"Step 1: Speed = 20 km/h.\nStep 2: Time = 5 h.\nStep 3: Distance = 20 × 5.\nStep 4: Distance = 100 km.","steps":["Step 1: Speed = 20 km/h.","Step 2: Time = 5 h.","Step 3: Distance = 20 × 5.","Step 4: Distance = 100 km."],"options":[],"conceptId":"math_linear_motion_distance_speed_time_relationship","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Distance-Speed-Time Relationship"}', 1),
  (86, 19, 'A bus travels at 90 km/h for 2.5 hours. Find the distance.', 'text', 1, 'Use d = st.', '{"why":"Multiplying the rate by the time gives the total distance.","sol":"Step 1: Speed = 90 km/h.\nStep 2: Time = 2.5 h.\nStep 3: Distance = 90 × 2.5.\nStep 4: Distance = 225 km.","steps":["Step 1: Speed = 90 km/h.","Step 2: Time = 2.5 h.","Step 3: Distance = 90 × 2.5.","Step 4: Distance = 225 km."],"options":[],"conceptId":"math_linear_motion_distance_speed_time_relationship","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Distance-Speed-Time Relationship"}', 2),
  (87, 19, 'Which formula gives distance when speed and time are known?', 'text', 1, 'Think about multiplying the rate by the amount of time.', '{"why":"Distance equals speed multiplied by time.","sol":"Step 1: Speed tells us distance covered per unit of time.\nStep 2: Multiplying speed by time gives the total distance.\nStep 3: Therefore, d = st.","steps":["Step 1: Speed tells us distance covered per unit of time.","Step 2: Multiplying speed by time gives the total distance.","Step 3: Therefore, d = st."],"options":[],"conceptId":"math_linear_motion_distance_speed_time_relationship","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Distance-Speed-Time Relationship"}', 3),
  (88, 20, 'A car travels 300 km at 75 km/h. Find the time taken.', 'text', 1, 'Use t = d/s.', '{"why":"Time is found by dividing distance by speed.","sol":"Step 1: Distance = 300 km.\nStep 2: Speed = 75 km/h.\nStep 3: Time = 300 ÷ 75.\nStep 4: Time = 4 hours.","steps":["Step 1: Distance = 300 km.","Step 2: Speed = 75 km/h.","Step 3: Time = 300 ÷ 75.","Step 4: Time = 4 hours."],"options":[],"conceptId":"math_linear_motion_finding_time_from_distance_and_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Time from Distance and Speed"}', 0),
  (89, 20, 'A cyclist travels 120 km at 40 km/h. Find the time.', 'text', 1, 'Divide 120 by 40.', '{"why":"The time is the distance divided by the distance covered per hour.","sol":"Step 1: Distance = 120 km.\nStep 2: Speed = 40 km/h.\nStep 3: Time = 120 ÷ 40.\nStep 4: Time = 3 hours.","steps":["Step 1: Distance = 120 km.","Step 2: Speed = 40 km/h.","Step 3: Time = 120 ÷ 40.","Step 4: Time = 3 hours."],"options":[],"conceptId":"math_linear_motion_finding_time_from_distance_and_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Time from Distance and Speed"}', 1),
  (90, 20, 'A train travels 360 km at 90 km/h. Find the time.', 'text', 1, 'Use time = distance ÷ speed.', '{"why":"Dividing distance by speed gives the time taken.","sol":"Step 1: Distance = 360 km.\nStep 2: Speed = 90 km/h.\nStep 3: Time = 360 ÷ 90.\nStep 4: Time = 4 hours.","steps":["Step 1: Distance = 360 km.","Step 2: Speed = 90 km/h.","Step 3: Time = 360 ÷ 90.","Step 4: Time = 4 hours."],"options":[],"conceptId":"math_linear_motion_finding_time_from_distance_and_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Time from Distance and Speed"}', 2),
  (91, 20, 'Which formula should you use to find time when distance and speed are known?', 'text', 1, 'Rearrange d = st so that time is alone.', '{"why":"Rearranging the distance-speed-time relationship gives time.","sol":"Step 1: Start with d = st.\nStep 2: Divide both sides by s.\nStep 3: This gives t = d/s.","steps":["Step 1: Start with d = st.","Step 2: Divide both sides by s.","Step 3: This gives t = d/s."],"options":[],"conceptId":"math_linear_motion_finding_time_from_distance_and_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Finding Time from Distance and Speed"}', 3),
  (92, 21, 'A car travels 300 km in 5 hours. Find its speed.', 'text', 1, 'Use s = d/t.', '{"why":"Speed is distance divided by time.","sol":"Step 1: Distance = 300 km.\nStep 2: Time = 5 h.\nStep 3: Speed = 300 ÷ 5.\nStep 4: Speed = 60 km/h.","steps":["Step 1: Distance = 300 km.","Step 2: Time = 5 h.","Step 3: Speed = 300 ÷ 5.","Step 4: Speed = 60 km/h."],"options":[],"conceptId":"math_linear_motion_finding_speed_from_distance_and_time","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Speed from Distance and Time"}', 0),
  (93, 21, 'A runner covers 24 km in 2 hours. Find the speed.', 'text', 1, 'Divide distance by time.', '{"why":"The speed tells how much distance is covered per hour.","sol":"Step 1: Distance = 24 km.\nStep 2: Time = 2 h.\nStep 3: Speed = 24 ÷ 2.\nStep 4: Speed = 12 km/h.","steps":["Step 1: Distance = 24 km.","Step 2: Time = 2 h.","Step 3: Speed = 24 ÷ 2.","Step 4: Speed = 12 km/h."],"options":[],"conceptId":"math_linear_motion_finding_speed_from_distance_and_time","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Speed from Distance and Time"}', 1),
  (94, 21, 'A bus travels 280 km in 4 hours. Find its speed.', 'text', 1, 'Use speed = distance ÷ time.', '{"why":"Dividing the total distance by total time gives speed.","sol":"Step 1: Distance = 280 km.\nStep 2: Time = 4 h.\nStep 3: Speed = 280 ÷ 4.\nStep 4: Speed = 70 km/h.","steps":["Step 1: Distance = 280 km.","Step 2: Time = 4 h.","Step 3: Speed = 280 ÷ 4.","Step 4: Speed = 70 km/h."],"options":[],"conceptId":"math_linear_motion_finding_speed_from_distance_and_time","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Speed from Distance and Time"}', 2),
  (95, 21, 'A cyclist travels 90 km in 1.5 hours. Find the speed.', 'text', 1, 'Divide 90 by 1.5.', '{"why":"Speed is the distance travelled per unit of time.","sol":"Step 1: Distance = 90 km.\nStep 2: Time = 1.5 h.\nStep 3: Speed = 90 ÷ 1.5.\nStep 4: Speed = 60 km/h.","steps":["Step 1: Distance = 90 km.","Step 2: Time = 1.5 h.","Step 3: Speed = 90 ÷ 1.5.","Step 4: Speed = 60 km/h."],"options":[],"conceptId":"math_linear_motion_finding_speed_from_distance_and_time","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Finding Speed from Distance and Time"}', 3),
  (96, 22, 'A car travels at 80 km/h while another car travels at 55 km/h in the same direction. Find their relative speed.', 'text', 1, 'For objects moving in the same direction, subtract the smaller speed from the larger speed.', '{"why":"The faster car gains on the slower car at the difference between their speeds.","sol":"Step 1: Relative speed = 80 − 55\nStep 2: Relative speed = 25 km/h","steps":["Step 1: Relative speed = 80 − 55","Step 2: Relative speed = 25 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_the_same_direction","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Relative Speed in the Same Direction"}', 0),
  (97, 22, 'A bus travels at 72 km/h and a truck travels at 60 km/h in the same direction. Find the relative speed.', 'text', 1, 'Subtract the two speeds.', '{"why":"The distance between the two vehicles changes at 12 km/h.","sol":"Step 1: Relative speed = 72 − 60\nStep 2: Relative speed = 12 km/h","steps":["Step 1: Relative speed = 72 − 60","Step 2: Relative speed = 12 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_the_same_direction","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Relative Speed in the Same Direction"}', 1),
  (98, 22, 'Two cyclists travel in the same direction at 30 km/h and 22 km/h. Find the relative speed.', 'text', 1, 'Same direction means subtraction.', '{"why":"The faster cyclist gains 8 km on the slower cyclist every hour.","sol":"Step 1: Relative speed = 30 − 22\nStep 2: Relative speed = 8 km/h","steps":["Step 1: Relative speed = 30 − 22","Step 2: Relative speed = 8 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_the_same_direction","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Relative Speed in the Same Direction"}', 2),
  (99, 22, 'A car travels at 90 km/h while a bus travels at 60 km/h in the same direction. Find their relative speed.', 'text', 1, 'Subtract the smaller speed from the larger speed.', '{"why":"The car gains on the bus at 30 km/h.","sol":"Step 1: Relative speed = 90 − 60\nStep 2: Relative speed = 30 km/h","steps":["Step 1: Relative speed = 90 − 60","Step 2: Relative speed = 30 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_the_same_direction","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Relative Speed in the Same Direction"}', 3),
  (100, 22, 'Two cyclists travel in the same direction at 28 km/h and 20 km/h. Find their relative speed.', 'text', 1, 'Same direction means subtract.', '{"why":"The faster cyclist reduces the separation by 8 km every hour.","sol":"Step 1: Relative speed = 28 − 20\nStep 2: Relative speed = 8 km/h","steps":["Step 1: Relative speed = 28 − 20","Step 2: Relative speed = 8 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_the_same_direction","skillId":"math_linear_motion","subskillId":"math_linear_motion_q5","subject":"math","chapter":"linear_motion","topic":"Relative Speed in the Same Direction"}', 4),
  (101, 22, 'A truck moves at 55 km/h and a car moves at 75 km/h in the same direction. Find the relative speed.', 'text', 1, 'Subtract 55 from 75.', '{"why":"The car gains on the truck at 20 km/h.","sol":"Step 1: Relative speed = 75 − 55\nStep 2: Relative speed = 20 km/h","steps":["Step 1: Relative speed = 75 − 55","Step 2: Relative speed = 20 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_the_same_direction","skillId":"math_linear_motion","subskillId":"math_linear_motion_q6","subject":"math","chapter":"linear_motion","topic":"Relative Speed in the Same Direction"}', 5),
  (102, 23, 'Two cars travel towards each other at 70 km/h and 50 km/h. Find their relative speed.', 'text', 1, 'Opposite directions mean the speeds are added.', '{"why":"Both cars reduce the distance between them, so their speeds add.","sol":"Step 1: Relative speed = 70 + 50\nStep 2: Relative speed = 120 km/h","steps":["Step 1: Relative speed = 70 + 50","Step 2: Relative speed = 120 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_opposite_directions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Relative Speed in Opposite Directions"}', 0),
  (103, 23, 'Two cyclists move towards each other at 25 km/h and 15 km/h. Find their relative speed.', 'text', 1, 'Add the two speeds.', '{"why":"The cyclists are approaching each other from opposite directions.","sol":"Step 1: Relative speed = 25 + 15\nStep 2: Relative speed = 40 km/h","steps":["Step 1: Relative speed = 25 + 15","Step 2: Relative speed = 40 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_opposite_directions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Relative Speed in Opposite Directions"}', 1),
  (104, 23, 'A train travels east at 90 km/h while another train travels west at 80 km/h. Find their relative speed.', 'text', 1, 'They are moving towards each other.', '{"why":"Their speeds combine because the trains are moving towards each other.","sol":"Step 1: Relative speed = 90 + 80\nStep 2: Relative speed = 170 km/h","steps":["Step 1: Relative speed = 90 + 80","Step 2: Relative speed = 170 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_opposite_directions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Relative Speed in Opposite Directions"}', 2),
  (105, 23, 'Two cars move towards each other at 70 km/h and 50 km/h. Find their relative speed.', 'text', 1, 'Opposite directions mean add the speeds.', '{"why":"Both cars reduce the distance between them.","sol":"Step 1: Relative speed = 70 + 50\nStep 2: Relative speed = 120 km/h","steps":["Step 1: Relative speed = 70 + 50","Step 2: Relative speed = 120 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_opposite_directions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Relative Speed in Opposite Directions"}', 3),
  (106, 23, 'Two cyclists approach each other at 20 km/h and 30 km/h. Find their relative speed.', 'text', 1, 'They are moving towards each other.', '{"why":"Their speeds combine because they move in opposite directions.","sol":"Step 1: Relative speed = 20 + 30\nStep 2: Relative speed = 50 km/h","steps":["Step 1: Relative speed = 20 + 30","Step 2: Relative speed = 50 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_opposite_directions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q5","subject":"math","chapter":"linear_motion","topic":"Relative Speed in Opposite Directions"}', 4),
  (107, 23, 'A bus and a car approach each other at 45 km/h and 75 km/h. Find their relative speed.', 'text', 1, 'Add the two speeds.', '{"why":"The distance between them decreases at the sum of their speeds.","sol":"Step 1: Relative speed = 45 + 75\nStep 2: Relative speed = 120 km/h","steps":["Step 1: Relative speed = 45 + 75","Step 2: Relative speed = 120 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_opposite_directions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q6","subject":"math","chapter":"linear_motion","topic":"Relative Speed in Opposite Directions"}', 5),
  (108, 24, 'Two cars travel in the same direction at 90 km/h and 70 km/h. How much does the distance between them change in 3 hours?', 'text', 1, 'First find relative speed, then multiply by time.', '{"why":"The faster car gains 20 km every hour, so in 3 hours it gains 60 km.","sol":"Step 1: Relative speed = 90 − 70 = 20 km/h\nStep 2: Change in distance = 20 × 3\nStep 3: Change in distance = 60 km","steps":["Step 1: Relative speed = 90 − 70 = 20 km/h","Step 2: Change in distance = 20 × 3","Step 3: Change in distance = 60 km"],"options":[],"conceptId":"math_linear_motion_finding_distance_between_moving_objects","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Distance Between Moving Objects"}', 0),
  (109, 24, 'Two vehicles move towards each other at 60 km/h and 40 km/h. How much distance do they close in 2 hours?', 'text', 1, 'Find the relative speed first.', '{"why":"The vehicles approach each other at a combined rate of 100 km/h.","sol":"Step 1: Relative speed = 60 + 40 = 100 km/h\nStep 2: Change in distance = 100 × 2\nStep 3: Change in distance = 200 km","steps":["Step 1: Relative speed = 60 + 40 = 100 km/h","Step 2: Change in distance = 100 × 2","Step 3: Change in distance = 200 km"],"options":[],"conceptId":"math_linear_motion_finding_distance_between_moving_objects","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Distance Between Moving Objects"}', 1),
  (110, 24, 'A bus travels at 75 km/h and a car ahead travels at 55 km/h. How much distance does the bus gain in 5 hours?', 'text', 1, 'Subtract their speeds before multiplying by time.', '{"why":"The bus gains 20 km every hour on the car.","sol":"Step 1: Relative speed = 75 − 55 = 20 km/h\nStep 2: Distance gained = 20 × 5\nStep 3: Distance gained = 100 km","steps":["Step 1: Relative speed = 75 − 55 = 20 km/h","Step 2: Distance gained = 20 × 5","Step 3: Distance gained = 100 km"],"options":[],"conceptId":"math_linear_motion_finding_distance_between_moving_objects","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Distance Between Moving Objects"}', 2),
  (111, 25, 'Two cars move in the same direction at 90 km/h and 60 km/h. How much does the faster car gain in 4 hours?', 'text', 1, 'First find the relative speed.', '{"why":"The faster car gains 30 km every hour.","sol":"Step 1: Relative speed = 90 − 60 = 30 km/h\nStep 2: Gain = 30 × 4\nStep 3: Gain = 120 km","steps":["Step 1: Relative speed = 90 − 60 = 30 km/h","Step 2: Gain = 30 × 4","Step 3: Gain = 120 km"],"options":[],"conceptId":"math_linear_motion_finding_separation_using_relative_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Separation Using Relative Speed"}', 0),
  (112, 25, 'Two vehicles approach each other at 50 km/h and 40 km/h. How much does their separation decrease in 3 hours?', 'text', 1, 'Add their speeds first.', '{"why":"Their combined motion closes the gap at 90 km/h.","sol":"Step 1: Relative speed = 50 + 40 = 90 km/h\nStep 2: Decrease = 90 × 3\nStep 3: Decrease = 270 km","steps":["Step 1: Relative speed = 50 + 40 = 90 km/h","Step 2: Decrease = 90 × 3","Step 3: Decrease = 270 km"],"options":[],"conceptId":"math_linear_motion_finding_separation_using_relative_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Separation Using Relative Speed"}', 1),
  (113, 25, 'A bus travels at 70 km/h while a car travels at 100 km/h in the same direction. Find the distance gained by the car in 5 hours.', 'text', 1, 'Relative speed = 100 − 70.', '{"why":"The car gains 30 km on the bus every hour.","sol":"Step 1: Relative speed = 100 − 70 = 30 km/h\nStep 2: Gain = 30 × 5\nStep 3: Gain = 150 km","steps":["Step 1: Relative speed = 100 − 70 = 30 km/h","Step 2: Gain = 30 × 5","Step 3: Gain = 150 km"],"options":[],"conceptId":"math_linear_motion_finding_separation_using_relative_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Separation Using Relative Speed"}', 2),
  (114, 26, 'A car travels at 50 km/h for 4 hours. Find the distance travelled.', 'text', 1, 'Use d = st.', '{"why":"Distance is obtained by multiplying speed by time.","sol":"Step 1: d = 50 × 4\nStep 2: d = 200 km","steps":["Step 1: d = 50 × 4","Step 2: d = 200 km"],"options":[],"conceptId":"math_linear_motion_translating_motion_words_into_an_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Translating Motion Words into an Equation"}', 0),
  (115, 26, 'A cyclist travels at 24 km/h for 2.5 hours. Find the distance travelled.', 'text', 1, 'Multiply 24 by 2.5.', '{"why":"The cyclist covers 24 km in each hour.","sol":"Step 1: d = 24 × 2.5\nStep 2: d = 60 km","steps":["Step 1: d = 24 × 2.5","Step 2: d = 60 km"],"options":[],"conceptId":"math_linear_motion_translating_motion_words_into_an_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Translating Motion Words into an Equation"}', 1),
  (116, 26, 'A train travels at 90 km/h for 2 hours. Find the distance travelled.', 'text', 1, 'Use distance = speed × time.', '{"why":"The train covers 90 km each hour for 2 hours.","sol":"Step 1: d = 90 × 2\nStep 2: d = 180 km","steps":["Step 1: d = 90 × 2","Step 2: d = 180 km"],"options":[],"conceptId":"math_linear_motion_translating_motion_words_into_an_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Translating Motion Words into an Equation"}', 2),
  (117, 26, 'A vehicle travels at 70 km/h for 3 hours. Find the distance.', 'text', 1, 'Distance = speed × time.', '{"why":"The vehicle covers 70 km each hour for 3 hours.","sol":"Step 1: d = st\nStep 2: d = 70 × 3\nStep 3: d = 210 km","steps":["Step 1: d = st","Step 2: d = 70 × 3","Step 3: d = 210 km"],"options":[],"conceptId":"math_linear_motion_translating_motion_words_into_an_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Translating Motion Words into an Equation"}', 3),
  (118, 26, 'A cyclist covers 120 km in 4 hours. Find the speed.', 'text', 1, 'Speed = distance ÷ time.', '{"why":"Speed tells us how much distance is covered in one hour.","sol":"Step 1: s = d/t\nStep 2: s = 120/4\nStep 3: s = 30 km/h","steps":["Step 1: s = d/t","Step 2: s = 120/4","Step 3: s = 30 km/h"],"options":[],"conceptId":"math_linear_motion_translating_motion_words_into_an_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q5","subject":"math","chapter":"linear_motion","topic":"Translating Motion Words into an Equation"}', 4),
  (119, 26, 'A bus travels at 60 km/h and covers 300 km. Find the time.', 'text', 1, 'Time = distance ÷ speed.', '{"why":"Dividing total distance by the speed gives the travel time.","sol":"Step 1: t = d/s\nStep 2: t = 300/60\nStep 3: t = 5 hours","steps":["Step 1: t = d/s","Step 2: t = 300/60","Step 3: t = 5 hours"],"options":[],"conceptId":"math_linear_motion_translating_motion_words_into_an_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q6","subject":"math","chapter":"linear_motion","topic":"Translating Motion Words into an Equation"}', 5),
  (120, 27, 'A car travels 300 km at 75 km/h. Find the time taken.', 'text', 1, 'Use t = d/s.', '{"why":"Time is found by dividing distance by speed.","sol":"Step 1: t = 300 / 75\nStep 2: t = 4 hours","steps":["Step 1: t = 300 / 75","Step 2: t = 4 hours"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_time_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Time in a Motion Problem"}', 0),
  (121, 27, 'A bus travels 180 km at 60 km/h. Find the time taken.', 'text', 1, 'Divide the distance by the speed.', '{"why":"At 60 km/h, the bus needs 3 hours to cover 180 km.","sol":"Step 1: t = 180 / 60\nStep 2: t = 3 hours","steps":["Step 1: t = 180 / 60","Step 2: t = 3 hours"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_time_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Time in a Motion Problem"}', 1),
  (122, 27, 'A cyclist travels 100 km at 20 km/h. Find the time taken.', 'text', 1, 'Use t = d/s.', '{"why":"The cyclist covers 20 km each hour.","sol":"Step 1: t = 100 / 20\nStep 2: t = 5 hours","steps":["Step 1: t = 100 / 20","Step 2: t = 5 hours"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_time_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Time in a Motion Problem"}', 2),
  (123, 27, 'A car travels 360 km at 90 km/h. Find the time taken.', 'text', 1, 'Use t = d/s.', '{"why":"At 90 km/h, the car covers 90 km in each hour.","sol":"Step 1: t = 360/90\nStep 2: t = 4 hours","steps":["Step 1: t = 360/90","Step 2: t = 4 hours"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_time_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Time in a Motion Problem"}', 3),
  (124, 27, 'A bus travels 420 km at 70 km/h. Find the travel time.', 'text', 1, 'Divide distance by speed.', '{"why":"Six groups of 70 km make 420 km.","sol":"Step 1: t = 420/70\nStep 2: t = 6 hours","steps":["Step 1: t = 420/70","Step 2: t = 6 hours"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_time_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q5","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Time in a Motion Problem"}', 4),
  (125, 27, 'A cyclist travels 150 km at 25 km/h. Find the time.', 'text', 1, 'Use t = 150/25.', '{"why":"The cyclist needs six hours to cover 150 km at 25 km/h.","sol":"Step 1: t = 150/25\nStep 2: t = 6 hours","steps":["Step 1: t = 150/25","Step 2: t = 6 hours"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_time_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q6","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Time in a Motion Problem"}', 5),
  (126, 28, 'A car travels 360 km in 6 hours. Find its speed.', 'text', 1, 'Use s = d/t.', '{"why":"Speed is distance divided by time.","sol":"Step 1: s = 360 / 6\nStep 2: s = 60 km/h","steps":["Step 1: s = 360 / 6","Step 2: s = 60 km/h"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_speed_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Speed in a Motion Problem"}', 0),
  (127, 28, 'A bus covers 240 km in 4 hours. Find its speed.', 'text', 1, 'Divide distance by time.', '{"why":"The bus covers 60 km during each hour.","sol":"Step 1: s = 240 / 4\nStep 2: s = 60 km/h","steps":["Step 1: s = 240 / 4","Step 2: s = 60 km/h"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_speed_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Speed in a Motion Problem"}', 1),
  (128, 28, 'A cyclist covers 75 km in 3 hours. Find the speed.', 'text', 1, 'Use s = d/t.', '{"why":"The cyclist covers 25 km in each hour.","sol":"Step 1: s = 75 / 3\nStep 2: s = 25 km/h","steps":["Step 1: s = 75 / 3","Step 2: s = 25 km/h"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_speed_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Speed in a Motion Problem"}', 2),
  (129, 29, 'A car travels at 80 km/h for 6 hours. Find the distance.', 'text', 1, 'Multiply speed by time.', '{"why":"The car covers 80 km each hour for 6 hours.","sol":"Step 1: d = 80 × 6\nStep 2: d = 480 km","steps":["Step 1: d = 80 × 6","Step 2: d = 480 km"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_distance_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Distance in a Motion Problem"}', 0),
  (130, 29, 'A cyclist travels at 30 km/h for 2.5 hours. Find the distance.', 'text', 1, 'Use d = st.', '{"why":"The cyclist covers 30 km per hour, so 2.5 hours gives 75 km.","sol":"Step 1: d = 30 × 2.5\nStep 2: d = 75 km","steps":["Step 1: d = 30 × 2.5","Step 2: d = 75 km"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_distance_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Distance in a Motion Problem"}', 1),
  (131, 29, 'A train travels at 90 km/h for 1.5 hours. Find the distance.', 'text', 1, 'Multiply 90 by 1.5.', '{"why":"The train covers 90 km in the first hour and another 45 km in half an hour.","sol":"Step 1: d = 90 × 1.5\nStep 2: d = 135 km","steps":["Step 1: d = 90 × 1.5","Step 2: d = 135 km"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_distance_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Distance in a Motion Problem"}', 2),
  (132, 30, 'Two cars are 200 km apart and travel towards each other at 60 km/h and 40 km/h. Find their meeting time.', 'text', 1, 'Add their speeds first.', '{"why":"Their combined approach speed is 100 km/h.","sol":"Step 1: Relative speed = 60 + 40 = 100 km/h\nStep 2: Time = 200 / 100\nStep 3: Time = 2 hours","steps":["Step 1: Relative speed = 60 + 40 = 100 km/h","Step 2: Time = 200 / 100","Step 3: Time = 2 hours"],"options":[],"conceptId":"math_linear_motion_finding_meeting_time","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Meeting Time"}', 0),
  (133, 30, 'Two cyclists are 150 km apart and move towards each other at 40 km/h and 35 km/h. Find when they meet.', 'text', 1, 'Use time = distance ÷ relative speed.', '{"why":"Together they close 75 km of separation each hour.","sol":"Step 1: Relative speed = 40 + 35 = 75 km/h\nStep 2: Time = 150 / 75\nStep 3: Time = 2 hours","steps":["Step 1: Relative speed = 40 + 35 = 75 km/h","Step 2: Time = 150 / 75","Step 3: Time = 2 hours"],"options":[],"conceptId":"math_linear_motion_finding_meeting_time","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Meeting Time"}', 1),
  (134, 30, 'Two buses are 300 km apart and travel towards each other at 70 km/h and 80 km/h. Find the meeting time.', 'text', 1, 'Add 70 and 80.', '{"why":"Their combined speed towards each other is 150 km/h.","sol":"Step 1: Relative speed = 70 + 80 = 150 km/h\nStep 2: Time = 300 / 150\nStep 3: Time = 2 hours","steps":["Step 1: Relative speed = 70 + 80 = 150 km/h","Step 2: Time = 300 / 150","Step 3: Time = 2 hours"],"options":[],"conceptId":"math_linear_motion_finding_meeting_time","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Meeting Time"}', 2),
  (135, 31, 'Two cars are 180 km apart and travel towards each other at 60 km/h and 30 km/h. Find the distance travelled by the 60 km/h car before they meet.', 'text', 1, 'First find the meeting time.', '{"why":"The faster car travels at 60 km/h for the 2 hours before meeting.","sol":"Step 1: Relative speed = 60 + 30 = 90 km/h\nStep 2: Meeting time = 180 / 90 = 2 h\nStep 3: Distance = 60 × 2\nStep 4: Distance = 120 km","steps":["Step 1: Relative speed = 60 + 30 = 90 km/h","Step 2: Meeting time = 180 / 90 = 2 h","Step 3: Distance = 60 × 2","Step 4: Distance = 120 km"],"options":[],"conceptId":"math_linear_motion_finding_the_meeting_point","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding the Meeting Point"}', 0),
  (136, 31, 'Two cyclists are 120 km apart and travel towards each other at 40 km/h and 20 km/h. Find the distance travelled by the slower cyclist before meeting.', 'text', 1, 'Find the meeting time, then use d = st.', '{"why":"The slower cyclist travels for the same 2 hours at 20 km/h.","sol":"Step 1: Relative speed = 40 + 20 = 60 km/h\nStep 2: Meeting time = 120 / 60 = 2 h\nStep 3: Distance = 20 × 2\nStep 4: Distance = 40 km","steps":["Step 1: Relative speed = 40 + 20 = 60 km/h","Step 2: Meeting time = 120 / 60 = 2 h","Step 3: Distance = 20 × 2","Step 4: Distance = 40 km"],"options":[],"conceptId":"math_linear_motion_finding_the_meeting_point","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding the Meeting Point"}', 1),
  (137, 31, 'Two buses are 300 km apart and travel towards each other at 75 km/h and 50 km/h. Find the distance travelled by the 75 km/h bus before they meet.', 'text', 1, 'Find time first.', '{"why":"The faster bus travels 75 km/h for 2.4 hours.","sol":"Step 1: Relative speed = 75 + 50 = 125 km/h\nStep 2: Meeting time = 300 / 125 = 2.4 h\nStep 3: Distance = 75 × 2.4\nStep 4: Distance = 180 km","steps":["Step 1: Relative speed = 75 + 50 = 125 km/h","Step 2: Meeting time = 300 / 125 = 2.4 h","Step 3: Distance = 75 × 2.4","Step 4: Distance = 180 km"],"options":[],"conceptId":"math_linear_motion_finding_the_meeting_point","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding the Meeting Point"}', 2),
  (138, 31, 'Two cars meet after 3 hours. The first car travels at 50 km/h. How far has it travelled to the meeting point?', 'text', 1, 'Use distance = speed × time.', '{"why":"The first car travels 50 km every hour for 3 hours.","sol":"Step 1: d = 50 × 3\nStep 2: d = 150 km","steps":["Step 1: d = 50 × 3","Step 2: d = 150 km"],"options":[],"conceptId":"math_linear_motion_finding_the_meeting_point","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Finding the Meeting Point"}', 3),
  (139, 31, 'Two cyclists meet after 2 hours. The first cyclist travels at 35 km/h. Find the distance from the first cyclist''s starting point to the meeting point.', 'text', 1, 'Multiply 35 by 2.', '{"why":"The cyclist covers 35 km each hour for two hours.","sol":"Step 1: d = 35 × 2\nStep 2: d = 70 km","steps":["Step 1: d = 35 × 2","Step 2: d = 70 km"],"options":[],"conceptId":"math_linear_motion_finding_the_meeting_point","skillId":"math_linear_motion","subskillId":"math_linear_motion_q5","subject":"math","chapter":"linear_motion","topic":"Finding the Meeting Point"}', 4),
  (140, 31, 'Two buses meet after 4 hours. The first bus travels at 60 km/h. Find its distance to the meeting point.', 'text', 1, 'Use d = st.', '{"why":"The first bus covers 240 km before reaching the meeting point.","sol":"Step 1: d = 60 × 4\nStep 2: d = 240 km","steps":["Step 1: d = 60 × 4","Step 2: d = 240 km"],"options":[],"conceptId":"math_linear_motion_finding_the_meeting_point","skillId":"math_linear_motion","subskillId":"math_linear_motion_q6","subject":"math","chapter":"linear_motion","topic":"Finding the Meeting Point"}', 5),
  (141, 32, 'A car travelling at 90 km/h is 30 km behind a bus travelling at 60 km/h. Find the time needed to catch the bus.', 'text', 1, 'Subtract the speeds, then divide the gap by the relative speed.', '{"why":"The car closes the 30 km gap at 30 km/h.","sol":"Step 1: Relative speed = 90 − 60 = 30 km/h\nStep 2: Time = 30 / 30\nStep 3: Time = 1 hour","steps":["Step 1: Relative speed = 90 − 60 = 30 km/h","Step 2: Time = 30 / 30","Step 3: Time = 1 hour"],"options":[],"conceptId":"math_linear_motion_overtaking_a_slower_object","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Overtaking a Slower Object"}', 0),
  (142, 32, 'A cyclist travelling at 25 km/h is 20 km behind another cyclist travelling at 15 km/h. Find the catching time.', 'text', 1, 'Relative speed = 25 − 15.', '{"why":"The faster cyclist gains 10 km every hour.","sol":"Step 1: Relative speed = 25 − 15 = 10 km/h\nStep 2: Time = 20 / 10\nStep 3: Time = 2 hours","steps":["Step 1: Relative speed = 25 − 15 = 10 km/h","Step 2: Time = 20 / 10","Step 3: Time = 2 hours"],"options":[],"conceptId":"math_linear_motion_overtaking_a_slower_object","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Overtaking a Slower Object"}', 1),
  (143, 32, 'A motorcycle travelling at 100 km/h is 45 km behind a car travelling at 85 km/h. Find the time needed to catch it.', 'text', 1, 'Find the relative speed first.', '{"why":"The motorcycle closes the gap at 15 km/h.","sol":"Step 1: Relative speed = 100 − 85 = 15 km/h\nStep 2: Time = 45 / 15\nStep 3: Time = 3 hours","steps":["Step 1: Relative speed = 100 − 85 = 15 km/h","Step 2: Time = 45 / 15","Step 3: Time = 3 hours"],"options":[],"conceptId":"math_linear_motion_overtaking_a_slower_object","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Overtaking a Slower Object"}', 2),
  (144, 33, 'Two cars are 240 km apart and travel towards each other at 70 km/h and 50 km/h. Find the meeting time.', 'text', 1, 'Relative speed = 70 + 50.', '{"why":"Together the cars close 120 km of separation every hour.","sol":"Step 1: Relative speed = 70 + 50 = 120 km/h\nStep 2: Time = 240/120\nStep 3: Time = 2 hours","steps":["Step 1: Relative speed = 70 + 50 = 120 km/h","Step 2: Time = 240/120","Step 3: Time = 2 hours"],"options":[],"conceptId":"math_linear_motion_finding_meeting_time_from_opposite_directions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Meeting Time from Opposite Directions"}', 0),
  (145, 33, 'Two cyclists are 150 km apart and travel towards each other at 25 km/h and 50 km/h. Find when they meet.', 'text', 1, 'Add the speeds.', '{"why":"Their combined closing speed is 75 km/h.","sol":"Step 1: Relative speed = 25 + 50 = 75 km/h\nStep 2: Time = 150/75\nStep 3: Time = 2 hours","steps":["Step 1: Relative speed = 25 + 50 = 75 km/h","Step 2: Time = 150/75","Step 3: Time = 2 hours"],"options":[],"conceptId":"math_linear_motion_finding_meeting_time_from_opposite_directions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Meeting Time from Opposite Directions"}', 1),
  (146, 33, 'Two buses are 360 km apart and travel towards each other at 80 km/h and 40 km/h. Find the meeting time.', 'text', 1, 'Use time = separation ÷ relative speed.', '{"why":"At a combined speed of 120 km/h, 360 km is covered in 3 hours.","sol":"Step 1: Relative speed = 80 + 40 = 120 km/h\nStep 2: Time = 360/120\nStep 3: Time = 3 hours","steps":["Step 1: Relative speed = 80 + 40 = 120 km/h","Step 2: Time = 360/120","Step 3: Time = 3 hours"],"options":[],"conceptId":"math_linear_motion_finding_meeting_time_from_opposite_directions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Meeting Time from Opposite Directions"}', 2),
  (147, 34, 'A car is 60 km behind a bus. The car travels at 90 km/h and the bus at 60 km/h. Find the overtaking time.', 'text', 1, 'Relative speed = 90 − 60.', '{"why":"The car closes the 60 km gap at 30 km/h.","sol":"Step 1: Relative speed = 90 − 60 = 30 km/h\nStep 2: Time = 60/30\nStep 3: Time = 2 hours","steps":["Step 1: Relative speed = 90 − 60 = 30 km/h","Step 2: Time = 60/30","Step 3: Time = 2 hours"],"options":[],"conceptId":"math_linear_motion_finding_overtaking_time","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Overtaking Time"}', 0),
  (148, 34, 'A cyclist is 20 km behind another cyclist. Their speeds are 30 km/h and 25 km/h. Find the time to catch up.', 'text', 1, 'Subtract the speeds first.', '{"why":"The faster cyclist gains 5 km every hour.","sol":"Step 1: Relative speed = 30 − 25 = 5 km/h\nStep 2: Time = 20/5\nStep 3: Time = 4 hours","steps":["Step 1: Relative speed = 30 − 25 = 5 km/h","Step 2: Time = 20/5","Step 3: Time = 4 hours"],"options":[],"conceptId":"math_linear_motion_finding_overtaking_time","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Overtaking Time"}', 1),
  (149, 34, 'A car is 45 km behind a truck. The car travels at 75 km/h and the truck at 60 km/h. Find the overtaking time.', 'text', 1, 'Use time = separation ÷ relative speed.', '{"why":"The car closes the 45 km gap at 15 km/h.","sol":"Step 1: Relative speed = 75 − 60 = 15 km/h\nStep 2: Time = 45/15\nStep 3: Time = 3 hours","steps":["Step 1: Relative speed = 75 − 60 = 15 km/h","Step 2: Time = 45/15","Step 3: Time = 3 hours"],"options":[],"conceptId":"math_linear_motion_finding_overtaking_time","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Overtaking Time"}', 2),
  (150, 35, 'Convert 5 km to metres.', 'text', 1, 'Multiply by 1000.', '{"why":"Each kilometre contains 1000 metres.","sol":"Step 1: 5 × 1000 = 5000\nStep 2: Therefore, 5 km = 5000 m","steps":["Step 1: 5 × 1000 = 5000","Step 2: Therefore, 5 km = 5000 m"],"options":[],"conceptId":"math_linear_motion_converting_kilometres_to_metres","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Converting Kilometres to Metres"}', 0),
  (151, 35, 'Convert 2.4 km to metres.', 'text', 1, 'Multiply 2.4 by 1000.', '{"why":"Kilometres are changed to metres by multiplying by 1000.","sol":"Step 1: 2.4 × 1000 = 2400\nStep 2: Therefore, 2.4 km = 2400 m","steps":["Step 1: 2.4 × 1000 = 2400","Step 2: Therefore, 2.4 km = 2400 m"],"options":[],"conceptId":"math_linear_motion_converting_kilometres_to_metres","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Converting Kilometres to Metres"}', 1),
  (152, 35, 'Convert 0.35 km to metres.', 'text', 1, 'Multiply by 1000.', '{"why":"0.35 of a kilometre is 350 metres.","sol":"Step 1: 0.35 × 1000 = 350\nStep 2: Therefore, 0.35 km = 350 m","steps":["Step 1: 0.35 × 1000 = 350","Step 2: Therefore, 0.35 km = 350 m"],"options":[],"conceptId":"math_linear_motion_converting_kilometres_to_metres","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Converting Kilometres to Metres"}', 2),
  (153, 35, 'Convert 5 km to metres.', 'text', 1, 'Multiply by 1000.', '{"why":"One kilometre contains 1000 metres.","sol":"Step 1: 5 × 1000\nStep 2: 5000 m","steps":["Step 1: 5 × 1000","Step 2: 5000 m"],"options":[],"conceptId":"math_linear_motion_converting_kilometres_to_metres","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Converting Kilometres to Metres"}', 3),
  (154, 35, 'Convert 2.4 km to metres.', 'text', 1, 'Multiply 2.4 by 1000.', '{"why":"Kilometres are converted to metres by multiplying by 1000.","sol":"Step 1: 2.4 × 1000\nStep 2: 2400 m","steps":["Step 1: 2.4 × 1000","Step 2: 2400 m"],"options":[],"conceptId":"math_linear_motion_converting_kilometres_to_metres","skillId":"math_linear_motion","subskillId":"math_linear_motion_q5","subject":"math","chapter":"linear_motion","topic":"Converting Kilometres to Metres"}', 4),
  (155, 35, 'Convert 0.35 km to metres.', 'text', 1, 'Multiply by 1000.', '{"why":"0.35 kilometres contains 350 metres.","sol":"Step 1: 0.35 × 1000\nStep 2: 350 m","steps":["Step 1: 0.35 × 1000","Step 2: 350 m"],"options":[],"conceptId":"math_linear_motion_converting_kilometres_to_metres","skillId":"math_linear_motion","subskillId":"math_linear_motion_q6","subject":"math","chapter":"linear_motion","topic":"Converting Kilometres to Metres"}', 5),
  (156, 36, 'Convert 6 minutes to seconds.', 'text', 1, '1 minute = 60 seconds.', '{"why":"Each minute contains 60 seconds.","sol":"Step 1: 6 × 60 = 360\nStep 2: Therefore, 6 minutes = 360 seconds","steps":["Step 1: 6 × 60 = 360","Step 2: Therefore, 6 minutes = 360 seconds"],"options":[],"conceptId":"math_linear_motion_converting_minutes_and_seconds","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Converting Minutes and Seconds"}', 0),
  (157, 36, 'Convert 4.5 minutes to seconds.', 'text', 1, 'Multiply 4.5 by 60.', '{"why":"The conversion factor from minutes to seconds is 60.","sol":"Step 1: 4.5 × 60 = 270\nStep 2: Therefore, 4.5 minutes = 270 seconds","steps":["Step 1: 4.5 × 60 = 270","Step 2: Therefore, 4.5 minutes = 270 seconds"],"options":[],"conceptId":"math_linear_motion_converting_minutes_and_seconds","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Converting Minutes and Seconds"}', 1),
  (158, 36, 'Convert 3 hours to minutes.', 'text', 1, '1 hour = 60 minutes.', '{"why":"Each hour contains 60 minutes.","sol":"Step 1: 3 × 60 = 180\nStep 2: Therefore, 3 hours = 180 minutes","steps":["Step 1: 3 × 60 = 180","Step 2: Therefore, 3 hours = 180 minutes"],"options":[],"conceptId":"math_linear_motion_converting_minutes_and_seconds","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Converting Minutes and Seconds"}', 2),
  (159, 37, 'Convert 18 km/h to m/s.', 'text', 1, 'Multiply by 5/18.', '{"why":"The conversion factor from km/h to m/s is 5/18.","sol":"Step 1: 18 × 5/18\nStep 2: 18 ÷ 18 = 1\nStep 3: 1 × 5 = 5 m/s","steps":["Step 1: 18 × 5/18","Step 2: 18 ÷ 18 = 1","Step 3: 1 × 5 = 5 m/s"],"options":[],"conceptId":"math_linear_motion_converting_speed_between_km_h_and_m_s","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Converting Speed Between km/h and m/s"}', 0),
  (160, 37, 'Convert 90 km/h to m/s.', 'text', 1, 'Use 5/18.', '{"why":"90 km/h is equivalent to 25 metres per second.","sol":"Step 1: 90 × 5/18\nStep 2: 90 ÷ 18 = 5\nStep 3: 5 × 5 = 25 m/s","steps":["Step 1: 90 × 5/18","Step 2: 90 ÷ 18 = 5","Step 3: 5 × 5 = 25 m/s"],"options":[],"conceptId":"math_linear_motion_converting_speed_between_km_h_and_m_s","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Converting Speed Between km/h and m/s"}', 1),
  (161, 37, 'Convert 108 km/h to m/s.', 'text', 1, 'Multiply 108 by 5/18.', '{"why":"The unit conversion gives 30 metres per second.","sol":"Step 1: 108 × 5/18\nStep 2: 108 ÷ 18 = 6\nStep 3: 6 × 5 = 30 m/s","steps":["Step 1: 108 × 5/18","Step 2: 108 ÷ 18 = 6","Step 3: 6 × 5 = 30 m/s"],"options":[],"conceptId":"math_linear_motion_converting_speed_between_km_h_and_m_s","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Converting Speed Between km/h and m/s"}', 2),
  (162, 38, 'Convert 5 m/s to km/h.', 'text', 1, 'Multiply by 18/5.', '{"why":"The conversion factor from m/s to km/h is 18/5.","sol":"Step 1: 5 × 18/5\nStep 2: 5 ÷ 5 = 1\nStep 3: 1 × 18 = 18 km/h","steps":["Step 1: 5 × 18/5","Step 2: 5 ÷ 5 = 1","Step 3: 1 × 18 = 18 km/h"],"options":[],"conceptId":"math_linear_motion_converting_m_s_to_km_h","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Converting m/s to km/h"}', 0),
  (163, 38, 'Convert 15 m/s to km/h.', 'text', 1, 'Use 18/5.', '{"why":"15 metres per second is equivalent to 54 kilometres per hour.","sol":"Step 1: 15 × 18/5\nStep 2: 15 ÷ 5 = 3\nStep 3: 3 × 18 = 54 km/h","steps":["Step 1: 15 × 18/5","Step 2: 15 ÷ 5 = 3","Step 3: 3 × 18 = 54 km/h"],"options":[],"conceptId":"math_linear_motion_converting_m_s_to_km_h","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Converting m/s to km/h"}', 1),
  (164, 38, 'Convert 30 m/s to km/h.', 'text', 1, 'Multiply 30 by 18/5.', '{"why":"The converted speed is 108 kilometres per hour.","sol":"Step 1: 30 × 18/5\nStep 2: 30 ÷ 5 = 6\nStep 3: 6 × 18 = 108 km/h","steps":["Step 1: 30 × 18/5","Step 2: 30 ÷ 5 = 6","Step 3: 6 × 18 = 108 km/h"],"options":[],"conceptId":"math_linear_motion_converting_m_s_to_km_h","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Converting m/s to km/h"}', 2),
  (165, 39, 'Convert 20 minutes to hours.', 'text', 1, 'Divide 20 by 60.', '{"why":"An hour contains 60 minutes, so minutes are divided by 60.","sol":"Step 1: 20/60 = 1/3\nStep 2: 1/3 hour ≈ 0.333 hour","steps":["Step 1: 20/60 = 1/3","Step 2: 1/3 hour ≈ 0.333 hour"],"options":[],"conceptId":"math_linear_motion_converting_minutes_to_hours","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Converting Minutes to Hours"}', 0),
  (166, 39, 'Convert 30 minutes to hours.', 'text', 1, 'Divide by 60.', '{"why":"Thirty minutes is half of one hour.","sol":"Step 1: 30/60\nStep 2: 0.5 hours","steps":["Step 1: 30/60","Step 2: 0.5 hours"],"options":[],"conceptId":"math_linear_motion_converting_minutes_to_hours","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Converting Minutes to Hours"}', 1),
  (167, 39, 'Convert 120 minutes to hours.', 'text', 1, 'Divide 120 by 60.', '{"why":"Two groups of 60 minutes make 120 minutes.","sol":"Step 1: 120/60\nStep 2: 2 hours","steps":["Step 1: 120/60","Step 2: 2 hours"],"options":[],"conceptId":"math_linear_motion_converting_minutes_to_hours","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Converting Minutes to Hours"}', 2),
  (168, 40, 'Convert 10 m/s to km/h.', 'text', 1, 'Multiply by 3.6.', '{"why":"Every 1 m/s is equivalent to 3.6 km/h.","sol":"Step 1: 10 × 3.6\nStep 2: 36 km/h","steps":["Step 1: 10 × 3.6","Step 2: 36 km/h"],"options":[],"conceptId":"math_linear_motion_converting_metres_per_second_to_kilometres_per_hour","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Converting Metres per Second to Kilometres per Hour"}', 0),
  (169, 40, 'Convert 15 m/s to km/h.', 'text', 1, 'Use km/h = m/s × 3.6.', '{"why":"Multiplying by 3.6 converts the speed into kilometres per hour.","sol":"Step 1: 15 × 3.6\nStep 2: 54 km/h","steps":["Step 1: 15 × 3.6","Step 2: 54 km/h"],"options":[],"conceptId":"math_linear_motion_converting_metres_per_second_to_kilometres_per_hour","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Converting Metres per Second to Kilometres per Hour"}', 1),
  (170, 40, 'Convert 25 m/s to km/h.', 'text', 1, 'Multiply 25 by 3.6.', '{"why":"25 m/s is equivalent to 90 km/h.","sol":"Step 1: 25 × 3.6\nStep 2: 90 km/h","steps":["Step 1: 25 × 3.6","Step 2: 90 km/h"],"options":[],"conceptId":"math_linear_motion_converting_metres_per_second_to_kilometres_per_hour","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Converting Metres per Second to Kilometres per Hour"}', 2),
  (171, 41, 'A car travels at 60 km/h for 2 hours and then at 40 km/h for 1 hour. Find the distance travelled in each stage.', 'text', 1, 'Calculate each stage separately.', '{"why":"Each stage has its own speed and time.","sol":"Step 1: Stage 1: 60 × 2 = 120 km\nStep 2: Stage 2: 40 × 1 = 40 km","steps":["Step 1: Stage 1: 60 × 2 = 120 km","Step 2: Stage 2: 40 × 1 = 40 km"],"options":[],"conceptId":"math_linear_motion_representing_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Representing a Multi-Stage Journey"}', 0),
  (172, 41, 'A cyclist travels at 25 km/h for 2 hours and then at 20 km/h for 3 hours. Find the distance in each stage.', 'text', 1, 'Use d = st for each stage.', '{"why":"The distance for each stage is calculated from that stage''s speed and time.","sol":"Step 1: Stage 1: 25 × 2 = 50 km\nStep 2: Stage 2: 20 × 3 = 60 km","steps":["Step 1: Stage 1: 25 × 2 = 50 km","Step 2: Stage 2: 20 × 3 = 60 km"],"options":[],"conceptId":"math_linear_motion_representing_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Representing a Multi-Stage Journey"}', 1),
  (173, 41, 'A bus travels at 70 km/h for 1.5 hours and then at 50 km/h for 2 hours. Find the distance in each stage.', 'text', 1, 'Treat the two stages separately.', '{"why":"The speed changes after the first stage, so each stage must be calculated separately.","sol":"Step 1: Stage 1: 70 × 1.5 = 105 km\nStep 2: Stage 2: 50 × 2 = 100 km","steps":["Step 1: Stage 1: 70 × 1.5 = 105 km","Step 2: Stage 2: 50 × 2 = 100 km"],"options":[],"conceptId":"math_linear_motion_representing_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Representing a Multi-Stage Journey"}', 2),
  (174, 41, 'A vehicle travels 120 km and then 80 km. Find the total distance.', 'text', 1, 'Add the distances of the two stages.', '{"why":"Total distance is the sum of the distances travelled in all stages.","sol":"Step 1: Stage 1 = 120 km\nStep 2: Stage 2 = 80 km\nStep 3: Total = 120 + 80\nStep 4: Total = 200 km","steps":["Step 1: Stage 1 = 120 km","Step 2: Stage 2 = 80 km","Step 3: Total = 120 + 80","Step 4: Total = 200 km"],"options":[],"conceptId":"math_linear_motion_representing_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Representing a Multi-Stage Journey"}', 3),
  (175, 41, 'A journey takes 3 hours in the first stage and 2 hours in the second stage. Find the total time.', 'text', 1, 'Add the stage times.', '{"why":"The journey takes both stages consecutively.","sol":"Step 1: Stage 1 = 3 h\nStep 2: Stage 2 = 2 h\nStep 3: Total = 3 + 2\nStep 4: Total = 5 h","steps":["Step 1: Stage 1 = 3 h","Step 2: Stage 2 = 2 h","Step 3: Total = 3 + 2","Step 4: Total = 5 h"],"options":[],"conceptId":"math_linear_motion_representing_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q5","subject":"math","chapter":"linear_motion","topic":"Representing a Multi-Stage Journey"}', 4),
  (176, 41, 'A cyclist travels 50 km and then another 25 km. Find the total distance.', 'text', 1, 'Add the two distances.', '{"why":"Both stages contribute to the total distance.","sol":"Step 1: Total distance = 50 + 25\nStep 2: Total distance = 75 km","steps":["Step 1: Total distance = 50 + 25","Step 2: Total distance = 75 km"],"options":[],"conceptId":"math_linear_motion_representing_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q6","subject":"math","chapter":"linear_motion","topic":"Representing a Multi-Stage Journey"}', 5),
  (177, 42, 'A car travels at 50 km/h for 2 hours and then at 70 km/h for 1 hour. Find the total distance.', 'text', 1, 'Find each stage distance, then add them.', '{"why":"The total journey distance is the sum of the distances in both stages.","sol":"Step 1: Stage 1 = 50 × 2 = 100 km\nStep 2: Stage 2 = 70 × 1 = 70 km\nStep 3: Total distance = 100 + 70 = 170 km","steps":["Step 1: Stage 1 = 50 × 2 = 100 km","Step 2: Stage 2 = 70 × 1 = 70 km","Step 3: Total distance = 100 + 70 = 170 km"],"options":[],"conceptId":"math_linear_motion_finding_total_distance_in_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Total Distance in a Multi-Stage Journey"}', 0),
  (178, 42, 'A cyclist travels at 30 km/h for 2 hours and then at 20 km/h for 3 hours. Find the total distance.', 'text', 1, 'Calculate both stage distances.', '{"why":"Both stage distances are added to obtain the complete journey distance.","sol":"Step 1: Stage 1 = 30 × 2 = 60 km\nStep 2: Stage 2 = 20 × 3 = 60 km\nStep 3: Total distance = 60 + 60 = 120 km","steps":["Step 1: Stage 1 = 30 × 2 = 60 km","Step 2: Stage 2 = 20 × 3 = 60 km","Step 3: Total distance = 60 + 60 = 120 km"],"options":[],"conceptId":"math_linear_motion_finding_total_distance_in_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Total Distance in a Multi-Stage Journey"}', 1),
  (179, 42, 'A bus travels at 80 km/h for 1.5 hours and then at 60 km/h for 2 hours. Find the total distance.', 'text', 1, 'Use d = st for each stage.', '{"why":"The total distance is the sum of both stage distances.","sol":"Step 1: Stage 1 = 80 × 1.5 = 120 km\nStep 2: Stage 2 = 60 × 2 = 120 km\nStep 3: Total distance = 120 + 120 = 240 km","steps":["Step 1: Stage 1 = 80 × 1.5 = 120 km","Step 2: Stage 2 = 60 × 2 = 120 km","Step 3: Total distance = 120 + 120 = 240 km"],"options":[],"conceptId":"math_linear_motion_finding_total_distance_in_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Total Distance in a Multi-Stage Journey"}', 2),
  (180, 43, 'A car travels 180 km at 60 km/h and then 100 km at 50 km/h. Find the total time.', 'text', 1, 'Find the time for each stage using t = d/s.', '{"why":"The total travelling time is the sum of the times for both stages.","sol":"Step 1: Stage 1 = 180 / 60 = 3 h\nStep 2: Stage 2 = 100 / 50 = 2 h\nStep 3: Total time = 3 + 2 = 5 h","steps":["Step 1: Stage 1 = 180 / 60 = 3 h","Step 2: Stage 2 = 100 / 50 = 2 h","Step 3: Total time = 3 + 2 = 5 h"],"options":[],"conceptId":"math_linear_motion_finding_total_time_in_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Total Time in a Multi-Stage Journey"}', 0),
  (181, 43, 'A cyclist travels 90 km at 30 km/h and then 40 km at 20 km/h. Find the total time.', 'text', 1, 'Calculate each stage time.', '{"why":"Both stage times must be included in the total journey time.","sol":"Step 1: Stage 1 = 90 / 30 = 3 h\nStep 2: Stage 2 = 40 / 20 = 2 h\nStep 3: Total time = 3 + 2 = 5 h","steps":["Step 1: Stage 1 = 90 / 30 = 3 h","Step 2: Stage 2 = 40 / 20 = 2 h","Step 3: Total time = 3 + 2 = 5 h"],"options":[],"conceptId":"math_linear_motion_finding_total_time_in_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Total Time in a Multi-Stage Journey"}', 1),
  (182, 43, 'A bus travels 240 km at 80 km/h and then 150 km at 50 km/h. Find the total time.', 'text', 1, 'Use t = d/s for each stage.', '{"why":"The complete journey takes the sum of the two stage times.","sol":"Step 1: Stage 1 = 240 / 80 = 3 h\nStep 2: Stage 2 = 150 / 50 = 3 h\nStep 3: Total time = 3 + 3 = 6 h","steps":["Step 1: Stage 1 = 240 / 80 = 3 h","Step 2: Stage 2 = 150 / 50 = 3 h","Step 3: Total time = 3 + 3 = 6 h"],"options":[],"conceptId":"math_linear_motion_finding_total_time_in_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Total Time in a Multi-Stage Journey"}', 2),
  (183, 43, 'A car travels 100 km at 50 km/h and then 120 km at 60 km/h. Find the total travel time.', 'text', 1, 'Find each stage time first.', '{"why":"The total journey time is the sum of the times spent on both stages.","sol":"Step 1: Stage 1 time = 100/50 = 2 h\nStep 2: Stage 2 time = 120/60 = 2 h\nStep 3: Total time = 2 + 2 = 4 h","steps":["Step 1: Stage 1 time = 100/50 = 2 h","Step 2: Stage 2 time = 120/60 = 2 h","Step 3: Total time = 2 + 2 = 4 h"],"options":[],"conceptId":"math_linear_motion_finding_total_time_in_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Finding Total Time in a Multi-Stage Journey"}', 3),
  (184, 43, 'A bus travels 150 km at 50 km/h and then 180 km at 60 km/h. Find the total time.', 'text', 1, 'Calculate t₁ and t₂ separately.', '{"why":"Both stages occur one after another, so their times are added.","sol":"Step 1: Stage 1 = 150/50 = 3 h\nStep 2: Stage 2 = 180/60 = 3 h\nStep 3: Total = 3 + 3 = 6 h","steps":["Step 1: Stage 1 = 150/50 = 3 h","Step 2: Stage 2 = 180/60 = 3 h","Step 3: Total = 3 + 3 = 6 h"],"options":[],"conceptId":"math_linear_motion_finding_total_time_in_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q5","subject":"math","chapter":"linear_motion","topic":"Finding Total Time in a Multi-Stage Journey"}', 4),
  (185, 43, 'A cyclist travels 60 km at 30 km/h and then 45 km at 15 km/h. Find the total travel time.', 'text', 1, 'Use time = distance ÷ speed for each stage.', '{"why":"The complete journey takes the sum of the two stage times.","sol":"Step 1: Stage 1 = 60/30 = 2 h\nStep 2: Stage 2 = 45/15 = 3 h\nStep 3: Total = 2 + 3 = 5 h","steps":["Step 1: Stage 1 = 60/30 = 2 h","Step 2: Stage 2 = 45/15 = 3 h","Step 3: Total = 2 + 3 = 5 h"],"options":[],"conceptId":"math_linear_motion_finding_total_time_in_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q6","subject":"math","chapter":"linear_motion","topic":"Finding Total Time in a Multi-Stage Journey"}', 5),
  (186, 44, 'A car travels 150 km at 50 km/h. Find the time for this stage.', 'text', 1, 'Use t = d/s.', '{"why":"The time for a stage is its distance divided by its speed.","sol":"Step 1: t = 150/50\nStep 2: t = 3 hours","steps":["Step 1: t = 150/50","Step 2: t = 3 hours"],"options":[],"conceptId":"math_linear_motion_finding_time_for_each_stage","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Time for Each Stage"}', 0),
  (187, 44, 'A bus travels 200 km at 80 km/h. Find the time taken.', 'text', 1, 'Divide 200 by 80.', '{"why":"At 80 km/h, 200 km requires 2.5 hours.","sol":"Step 1: t = 200/80\nStep 2: t = 2.5 hours","steps":["Step 1: t = 200/80","Step 2: t = 2.5 hours"],"options":[],"conceptId":"math_linear_motion_finding_time_for_each_stage","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Time for Each Stage"}', 1),
  (188, 44, 'A cyclist travels 90 km at 30 km/h. Find the time.', 'text', 1, 'Use t = 90/30.', '{"why":"The cyclist covers 30 km every hour.","sol":"Step 1: t = 90/30\nStep 2: t = 3 hours","steps":["Step 1: t = 90/30","Step 2: t = 3 hours"],"options":[],"conceptId":"math_linear_motion_finding_time_for_each_stage","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Time for Each Stage"}', 2),
  (189, 45, 'An object is at position +7. Describe its position relative to the origin.', 'text', 1, 'A positive position lies to the right of zero.', '{"why":"Positive positions are measured to the right of zero.","sol":"Step 1: The position is +7.\nStep 2: The positive sign means the object is to the right of the origin.\nStep 3: Its distance from the origin is 7 units.","steps":["Step 1: The position is +7.","Step 2: The positive sign means the object is to the right of the origin.","Step 3: Its distance from the origin is 7 units."],"options":[],"conceptId":"math_linear_motion_representing_position_on_a_number_line","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Representing Position on a Number Line"}', 0),
  (190, 45, 'An object is at position −5. Describe its position relative to the origin.', 'text', 1, 'A negative position lies to the left of zero.', '{"why":"Negative positions are measured to the left of zero.","sol":"Step 1: The position is −5.\nStep 2: The negative sign means the object is to the left of the origin.\nStep 3: Its distance from the origin is 5 units.","steps":["Step 1: The position is −5.","Step 2: The negative sign means the object is to the left of the origin.","Step 3: Its distance from the origin is 5 units."],"options":[],"conceptId":"math_linear_motion_representing_position_on_a_number_line","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Representing Position on a Number Line"}', 1),
  (191, 45, 'Which position is farther to the right: −4 or +2?', 'text', 1, 'Look at their positions on the number line.', '{"why":"Numbers increase as we move from left to right on a number line.","sol":"Step 1: −4 lies to the left of zero.\nStep 2: +2 lies to the right of zero.\nStep 3: Therefore +2 is farther to the right.","steps":["Step 1: −4 lies to the left of zero.","Step 2: +2 lies to the right of zero.","Step 3: Therefore +2 is farther to the right."],"options":[],"conceptId":"math_linear_motion_representing_position_on_a_number_line","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Representing Position on a Number Line"}', 2),
  (192, 46, 'An object moves from position +3 to position +10. Find its displacement.', 'text', 1, 'Use final position − initial position.', '{"why":"The object moved 7 units in the positive direction.","sol":"Step 1: Displacement = 10 − 3\nStep 2: Displacement = +7 units","steps":["Step 1: Displacement = 10 − 3","Step 2: Displacement = +7 units"],"options":[],"conceptId":"math_linear_motion_finding_displacement_from_two_positions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Displacement from Two Positions"}', 0),
  (193, 46, 'An object moves from position +9 to position +4. Find its displacement.', 'text', 1, 'Subtract the initial position from the final position.', '{"why":"The negative displacement shows movement in the negative direction.","sol":"Step 1: Displacement = 4 − 9\nStep 2: Displacement = −5 units","steps":["Step 1: Displacement = 4 − 9","Step 2: Displacement = −5 units"],"options":[],"conceptId":"math_linear_motion_finding_displacement_from_two_positions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Displacement from Two Positions"}', 1),
  (194, 46, 'An object moves from position −6 to position +3. Find its displacement.', 'text', 1, 'Be careful with the negative initial position.', '{"why":"Moving from −6 to +3 requires a positive change of 9 units.","sol":"Step 1: Displacement = 3 − (−6)\nStep 2: Displacement = 3 + 6\nStep 3: Displacement = +9 units","steps":["Step 1: Displacement = 3 − (−6)","Step 2: Displacement = 3 + 6","Step 3: Displacement = +9 units"],"options":[],"conceptId":"math_linear_motion_finding_displacement_from_two_positions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Displacement from Two Positions"}', 2),
  (195, 47, 'An object moves from position +1 to +8. Find the distance travelled.', 'text', 1, 'Find the change in position and take its absolute value.', '{"why":"The object covers 7 units between the two positions.","sol":"Step 1: Change = 8 − 1 = 7\nStep 2: Distance = |7| = 7 units","steps":["Step 1: Change = 8 − 1 = 7","Step 2: Distance = |7| = 7 units"],"options":[],"conceptId":"math_linear_motion_finding_distance_travelled_from_positions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Distance Travelled from Positions"}', 0),
  (196, 47, 'An object moves from +10 to +4. Find the distance travelled.', 'text', 1, 'Distance cannot be negative.', '{"why":"The negative sign describes direction, but distance measures only the amount travelled.","sol":"Step 1: Change = 4 − 10 = −6\nStep 2: Distance = |−6|\nStep 3: Distance = 6 units","steps":["Step 1: Change = 4 − 10 = −6","Step 2: Distance = |−6|","Step 3: Distance = 6 units"],"options":[],"conceptId":"math_linear_motion_finding_distance_travelled_from_positions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Distance Travelled from Positions"}', 1),
  (197, 47, 'An object moves from −3 to +7. Find the distance travelled.', 'text', 1, 'Subtract the initial position from the final position.', '{"why":"The object moves through 10 units between −3 and +7.","sol":"Step 1: Change = 7 − (−3)\nStep 2: Change = 10\nStep 3: Distance = 10 units","steps":["Step 1: Change = 7 − (−3)","Step 2: Change = 10","Step 3: Distance = 10 units"],"options":[],"conceptId":"math_linear_motion_finding_distance_travelled_from_positions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Distance Travelled from Positions"}', 2),
  (198, 48, 'An object starts at position 8 m and moves at 2 m/s. Write its position equation.', 'text', 1, 'Use x = x₀ + st.', '{"why":"The object begins at 8 m and gains 2 m of position every second.","sol":"Step 1: x₀ = 8\nStep 2: s = 2\nStep 3: x = 8 + 2t","steps":["Step 1: x₀ = 8","Step 2: s = 2","Step 3: x = 8 + 2t"],"options":[],"conceptId":"math_linear_motion_writing_a_position_equation_for_constant_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Writing a Position Equation for Constant Speed"}', 0),
  (199, 48, 'An object starts at position 15 m and moves at 5 m/s. Write its position equation.', 'text', 1, 'Substitute the initial position and speed.', '{"why":"The initial position is 15 m and the position increases by 5 m each second.","sol":"Step 1: x₀ = 15\nStep 2: s = 5\nStep 3: x = 15 + 5t","steps":["Step 1: x₀ = 15","Step 2: s = 5","Step 3: x = 15 + 5t"],"options":[],"conceptId":"math_linear_motion_writing_a_position_equation_for_constant_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Writing a Position Equation for Constant Speed"}', 1),
  (200, 48, 'An object starts at 10 m and moves at 6 m/s. Find its position after 4 seconds.', 'text', 1, 'First write x = 10 + 6t, then substitute t = 4.', '{"why":"In 4 seconds the object travels 24 m from its starting position of 10 m.","sol":"Step 1: x = 10 + 6t\nStep 2: x = 10 + 6(4)\nStep 3: x = 10 + 24\nStep 4: x = 34 m","steps":["Step 1: x = 10 + 6t","Step 2: x = 10 + 6(4)","Step 3: x = 10 + 24","Step 4: x = 34 m"],"options":[],"conceptId":"math_linear_motion_writing_a_position_equation_for_constant_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Writing a Position Equation for Constant Speed"}', 2),
  (201, 49, 'Given x = 4 + 5t, find x when t = 3.', 'text', 1, 'Replace t with 3.', '{"why":"Substituting t = 3 gives the position at 3 units of time.","sol":"Step 1: x = 4 + 5(3)\nStep 2: x = 4 + 15\nStep 3: x = 19","steps":["Step 1: x = 4 + 5(3)","Step 2: x = 4 + 15","Step 3: x = 19"],"options":[],"conceptId":"math_linear_motion_finding_position_from_a_linear_motion_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Position from a Linear Motion Equation"}', 0),
  (202, 49, 'Given x = 8 + 2t, find x when t = 6.', 'text', 1, 'Substitute t = 6.', '{"why":"The equation gives the position directly once the time is known.","sol":"Step 1: x = 8 + 2(6)\nStep 2: x = 8 + 12\nStep 3: x = 20","steps":["Step 1: x = 8 + 2(6)","Step 2: x = 8 + 12","Step 3: x = 20"],"options":[],"conceptId":"math_linear_motion_finding_position_from_a_linear_motion_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Position from a Linear Motion Equation"}', 1),
  (203, 49, 'Given x = 15 + 7t, find x when t = 2.', 'text', 1, 'Replace t by 2.', '{"why":"At t = 2, the position is obtained by substituting 2 into the equation.","sol":"Step 1: x = 15 + 7(2)\nStep 2: x = 15 + 14\nStep 3: x = 29","steps":["Step 1: x = 15 + 7(2)","Step 2: x = 15 + 14","Step 3: x = 29"],"options":[],"conceptId":"math_linear_motion_finding_position_from_a_linear_motion_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Position from a Linear Motion Equation"}', 2),
  (204, 50, 'Given x = 4 + 2t, find t when x = 14.', 'text', 1, 'Substitute x = 14 and solve the linear equation.', '{"why":"Solving the position equation gives the time at which the object reaches position 14.","sol":"Step 1: 14 = 4 + 2t\nStep 2: 10 = 2t\nStep 3: t = 5","steps":["Step 1: 14 = 4 + 2t","Step 2: 10 = 2t","Step 3: t = 5"],"options":[],"conceptId":"math_linear_motion_finding_time_from_a_position_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Time from a Position Equation"}', 0),
  (205, 50, 'Given x = 7 + 3t, find t when x = 22.', 'text', 1, 'Subtract 7 first.', '{"why":"The unknown time is found by solving the linear equation.","sol":"Step 1: 22 = 7 + 3t\nStep 2: 15 = 3t\nStep 3: t = 5","steps":["Step 1: 22 = 7 + 3t","Step 2: 15 = 3t","Step 3: t = 5"],"options":[],"conceptId":"math_linear_motion_finding_time_from_a_position_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Time from a Position Equation"}', 1),
  (206, 50, 'Given x = 12 + 4t, find t when x = 32.', 'text', 1, 'Subtract 12, then divide by 4.', '{"why":"The equation tells us the position at every time, so we can solve it backwards for time.","sol":"Step 1: 32 = 12 + 4t\nStep 2: 20 = 4t\nStep 3: t = 5","steps":["Step 1: 32 = 12 + 4t","Step 2: 20 = 4t","Step 3: t = 5"],"options":[],"conceptId":"math_linear_motion_finding_time_from_a_position_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Time from a Position Equation"}', 2),
  (207, 51, 'A person walks 5 km away from home and 5 km back. Find the total distance.', 'text', 1, 'Add the outward and return distances.', '{"why":"Both the outward and return parts contribute to total distance.","sol":"Step 1: Total distance = 5 + 5\nStep 2: Total distance = 10 km","steps":["Step 1: Total distance = 5 + 5","Step 2: Total distance = 10 km"],"options":[],"conceptId":"math_linear_motion_distance_in_a_return_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Distance in a Return Journey"}', 0),
  (208, 51, 'A cyclist travels 8 km from A to B and then 3 km back towards A. Find the total distance travelled.', 'text', 1, 'Add both parts.', '{"why":"Distance counts every part of the path travelled.","sol":"Step 1: Outward distance = 8 km\nStep 2: Return distance = 3 km\nStep 3: Total distance = 8 + 3 = 11 km","steps":["Step 1: Outward distance = 8 km","Step 2: Return distance = 3 km","Step 3: Total distance = 8 + 3 = 11 km"],"options":[],"conceptId":"math_linear_motion_distance_in_a_return_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Distance in a Return Journey"}', 1),
  (209, 51, 'A car travels 20 km east and then 12 km west. Find the total distance travelled.', 'text', 1, 'Direction does not make distance negative.', '{"why":"Total distance is the complete length of the path.","sol":"Step 1: First distance = 20 km\nStep 2: Second distance = 12 km\nStep 3: Total distance = 20 + 12\nStep 4: Total distance = 32 km","steps":["Step 1: First distance = 20 km","Step 2: Second distance = 12 km","Step 3: Total distance = 20 + 12","Step 4: Total distance = 32 km"],"options":[],"conceptId":"math_linear_motion_distance_in_a_return_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Distance in a Return Journey"}', 2),
  (210, 52, 'A person walks 7 km east and then 7 km west. Find the displacement.', 'text', 1, 'The person finishes at the starting point.', '{"why":"The final position is the same as the initial position.","sol":"Step 1: Initial position = 0\nStep 2: Final position = 0\nStep 3: Displacement = 0 − 0 = 0 km","steps":["Step 1: Initial position = 0","Step 2: Final position = 0","Step 3: Displacement = 0 − 0 = 0 km"],"options":[],"conceptId":"math_linear_motion_displacement_in_a_return_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Displacement in a Return Journey"}', 0),
  (211, 52, 'A cyclist travels 12 km east and then 5 km west. Find the displacement.', 'text', 1, 'Take east as positive.', '{"why":"The cyclist finishes 7 km east of the starting point.","sol":"Step 1: Final position = 12 − 5\nStep 2: Final position = +7 km\nStep 3: Displacement = +7 km","steps":["Step 1: Final position = 12 − 5","Step 2: Final position = +7 km","Step 3: Displacement = +7 km"],"options":[],"conceptId":"math_linear_motion_displacement_in_a_return_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Displacement in a Return Journey"}', 1),
  (212, 52, 'A car travels 15 km west and then 10 km east. Find its displacement.', 'text', 1, 'Take east as positive, so west is negative.', '{"why":"The car finishes 5 km west of its starting point.","sol":"Step 1: First movement = −15 km\nStep 2: Second movement = +10 km\nStep 3: Final position = −15 + 10 = −5 km\nStep 4: Displacement = −5 km","steps":["Step 1: First movement = −15 km","Step 2: Second movement = +10 km","Step 3: Final position = −15 + 10 = −5 km","Step 4: Displacement = −5 km"],"options":[],"conceptId":"math_linear_motion_displacement_in_a_return_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Displacement in a Return Journey"}', 2),
  (213, 53, 'An object starts at 0 m, moves 10 m east and then 4 m west. Find its final position.', 'text', 1, 'Take east as positive.', '{"why":"The object finishes 6 m east of its starting point.","sol":"Step 1: Final position = 0 + 10 − 4\nStep 2: Final position = +6 m","steps":["Step 1: Final position = 0 + 10 − 4","Step 2: Final position = +6 m"],"options":[],"conceptId":"math_linear_motion_finding_the_final_position_after_several_movements","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding the Final Position After Several Movements"}', 0),
  (214, 53, 'An object starts at 8 m, moves 5 m west and then 2 m east. Find its final position.', 'text', 1, 'West is negative and east is positive.', '{"why":"The two movements change the starting position of 8 m.","sol":"Step 1: Final position = 8 − 5 + 2\nStep 2: Final position = 5 m","steps":["Step 1: Final position = 8 − 5 + 2","Step 2: Final position = 5 m"],"options":[],"conceptId":"math_linear_motion_finding_the_final_position_after_several_movements","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding the Final Position After Several Movements"}', 1),
  (215, 53, 'An object starts at −4 m, moves 9 m east and then 3 m west. Find its final position.', 'text', 1, 'Add +9 and −3 to the initial position.', '{"why":"The signed movements take the object from −4 m to +2 m.","sol":"Step 1: Final position = −4 + 9 − 3\nStep 2: Final position = +2 m","steps":["Step 1: Final position = −4 + 9 − 3","Step 2: Final position = +2 m"],"options":[],"conceptId":"math_linear_motion_finding_the_final_position_after_several_movements","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding the Final Position After Several Movements"}', 2),
  (216, 54, 'A bus starts at 8:00 a.m. and a car starts at 10:00 a.m. If t is the number of hours after 8:00 a.m., express the car''s travel time.', 'text', 1, 'The car starts 2 hours after the reference time.', '{"why":"The car has been travelling for two fewer hours than the elapsed time measured from 8:00 a.m.","sol":"Step 1: The delay is 2 hours.\nStep 2: Elapsed time = t.\nStep 3: Car travel time = t − 2.","steps":["Step 1: The delay is 2 hours.","Step 2: Elapsed time = t.","Step 3: Car travel time = t − 2."],"options":[],"conceptId":"math_linear_motion_representing_a_delayed_start","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Representing a Delayed Start"}', 0),
  (217, 54, 'A cyclist starts at 7:00 a.m. and another starts at 8:00 a.m. If t is measured from 7:00 a.m., express the second cyclist''s travel time.', 'text', 1, 'The second cyclist starts 1 hour later.', '{"why":"The second cyclist loses one hour of travel time because of the delayed start.","sol":"Step 1: Delay = 1 hour\nStep 2: Elapsed time = t\nStep 3: Travel time = t − 1","steps":["Step 1: Delay = 1 hour","Step 2: Elapsed time = t","Step 3: Travel time = t − 1"],"options":[],"conceptId":"math_linear_motion_representing_a_delayed_start","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Representing a Delayed Start"}', 1),
  (218, 54, 'A vehicle starts at 6:00 a.m. and another starts at 6:30 a.m. If t is measured from 6:00 a.m., express the second vehicle''s travel time.', 'text', 1, 'Convert 30 minutes to hours.', '{"why":"The second vehicle begins half an hour after the first.","sol":"Step 1: 30 minutes = 0.5 hours\nStep 2: Delay = 0.5 hours\nStep 3: Travel time = t − 0.5","steps":["Step 1: 30 minutes = 0.5 hours","Step 2: Delay = 0.5 hours","Step 3: Travel time = t − 0.5"],"options":[],"conceptId":"math_linear_motion_representing_a_delayed_start","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Representing a Delayed Start"}', 2),
  (219, 55, 'A car starts 2 hours after a bus and travels at 70 km/h. If t is measured from the bus''s starting time, write the car''s distance equation.', 'text', 1, 'The car travels for t − 2 hours.', '{"why":"The car''s actual travel time is t − 2 because it starts two hours late.","sol":"Step 1: Car travel time = t − 2\nStep 2: Distance = speed × time\nStep 3: Distance = 70(t − 2)","steps":["Step 1: Car travel time = t − 2","Step 2: Distance = speed × time","Step 3: Distance = 70(t − 2)"],"options":[],"conceptId":"math_linear_motion_finding_distance_after_a_delayed_start","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Distance After a Delayed Start"}', 0),
  (220, 55, 'A cyclist starts 1 hour after another cyclist and travels at 30 km/h. Write its distance equation using t as time from the first cyclist''s start.', 'text', 1, 'Subtract the 1-hour delay from t.', '{"why":"The cyclist travels for one hour less than the elapsed time t.","sol":"Step 1: Travel time = t − 1\nStep 2: Distance = 30(t − 1)","steps":["Step 1: Travel time = t − 1","Step 2: Distance = 30(t − 1)"],"options":[],"conceptId":"math_linear_motion_finding_distance_after_a_delayed_start","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Distance After a Delayed Start"}', 1),
  (221, 55, 'A bus starts 0.5 hours after a car and travels at 60 km/h. Write its distance equation.', 'text', 1, 'The delay is half an hour.', '{"why":"The bus has only travelled for t − 0.5 hours.","sol":"Step 1: Travel time = t − 0.5\nStep 2: Distance = 60(t − 0.5)","steps":["Step 1: Travel time = t − 0.5","Step 2: Distance = 60(t − 0.5)"],"options":[],"conceptId":"math_linear_motion_finding_distance_after_a_delayed_start","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Distance After a Delayed Start"}', 2),
  (222, 56, 'A bus leaves at 8:00 a.m. at 40 km/h. A car leaves at 10:00 a.m. at 60 km/h. How many hours after 8:00 a.m. does the car catch the bus?', 'text', 1, 'Set 40t equal to 60(t − 2).', '{"why":"At the catching point both vehicles have travelled the same distance from the starting point.","sol":"Step 1: Bus distance = 40t\nStep 2: Car distance = 60(t − 2)\nStep 3: 40t = 60(t − 2)\nStep 4: 40t = 60t − 120\nStep 5: 120 = 20t\nStep 6: t = 6 hours","steps":["Step 1: Bus distance = 40t","Step 2: Car distance = 60(t − 2)","Step 3: 40t = 60(t − 2)","Step 4: 40t = 60t − 120","Step 5: 120 = 20t","Step 6: t = 6 hours"],"options":[],"conceptId":"math_linear_motion_finding_when_a_delayed_object_catches_up","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding When a Delayed Object Catches Up"}', 0),
  (223, 56, 'A cyclist leaves at 7:00 a.m. at 20 km/h. Another leaves at 9:00 a.m. at 30 km/h. Find the catching time measured from 7:00 a.m.', 'text', 1, 'Use 20t = 30(t − 2).', '{"why":"The second cyclist makes up the initial two-hour disadvantage because they travel faster.","sol":"Step 1: 20t = 30(t − 2)\nStep 2: 20t = 30t − 60\nStep 3: 60 = 10t\nStep 4: t = 6 hours","steps":["Step 1: 20t = 30(t − 2)","Step 2: 20t = 30t − 60","Step 3: 60 = 10t","Step 4: t = 6 hours"],"options":[],"conceptId":"math_linear_motion_finding_when_a_delayed_object_catches_up","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding When a Delayed Object Catches Up"}', 1),
  (224, 56, 'A truck leaves at 6:00 a.m. at 50 km/h. A car leaves at 8:00 a.m. at 75 km/h. Find when the car catches the truck, measured from 6:00 a.m.', 'text', 1, 'Set 50t = 75(t − 2).', '{"why":"Equal distances indicate the exact moment the car catches the truck.","sol":"Step 1: 50t = 75(t − 2)\nStep 2: 50t = 75t − 150\nStep 3: 150 = 25t\nStep 4: t = 6 hours","steps":["Step 1: 50t = 75(t − 2)","Step 2: 50t = 75t − 150","Step 3: 150 = 25t","Step 4: t = 6 hours"],"options":[],"conceptId":"math_linear_motion_finding_when_a_delayed_object_catches_up","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding When a Delayed Object Catches Up"}', 2),
  (225, 57, 'A car travels at 80 km/h for t hours and covers 240 km. Find t.', 'text', 1, 'Use 240 = 80t.', '{"why":"The unknown time is obtained by dividing distance by speed.","sol":"Step 1: 240 = 80t\nStep 2: t = 240/80\nStep 3: t = 3 hours","steps":["Step 1: 240 = 80t","Step 2: t = 240/80","Step 3: t = 3 hours"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_distance_algebraically","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Distance Algebraically"}', 0),
  (226, 57, 'A cyclist travels at x km/h for 5 hours and covers 125 km. Find x.', 'text', 1, 'Use 125 = 5x.', '{"why":"The unknown speed is distance divided by time.","sol":"Step 1: 125 = 5x\nStep 2: x = 125/5\nStep 3: x = 25 km/h","steps":["Step 1: 125 = 5x","Step 2: x = 125/5","Step 3: x = 25 km/h"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_distance_algebraically","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Distance Algebraically"}', 1),
  (227, 57, 'A bus travels at 60 km/h for t hours and covers 300 km. Find t.', 'text', 1, 'Form the equation 300 = 60t.', '{"why":"The equation follows directly from distance = speed × time.","sol":"Step 1: 300 = 60t\nStep 2: t = 300/60\nStep 3: t = 5 hours","steps":["Step 1: 300 = 60t","Step 2: t = 300/60","Step 3: t = 5 hours"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_distance_algebraically","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Distance Algebraically"}', 2),
  (228, 58, 'A car covers 180 km at 60 km/h while a bus covers the same distance at 45 km/h. Find the difference in their travel times.', 'text', 1, 'Find each time using t = d/s.', '{"why":"The slower bus requires one extra hour to cover the same distance.","sol":"Step 1: Car time = 180/60 = 3 h\nStep 2: Bus time = 180/45 = 4 h\nStep 3: Difference = 4 − 3 = 1 h","steps":["Step 1: Car time = 180/60 = 3 h","Step 2: Bus time = 180/45 = 4 h","Step 3: Difference = 4 − 3 = 1 h"],"options":[],"conceptId":"math_linear_motion_using_algebra_to_compare_two_travel_times","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Using Algebra to Compare Two Travel Times"}', 0),
  (229, 58, 'A cyclist covers 120 km at 30 km/h while another covers it at 40 km/h. Find the difference in time.', 'text', 1, 'Calculate both times.', '{"why":"The lower speed results in a longer travel time.","sol":"Step 1: First time = 120/30 = 4 h\nStep 2: Second time = 120/40 = 3 h\nStep 3: Difference = 4 − 3 = 1 h","steps":["Step 1: First time = 120/30 = 4 h","Step 2: Second time = 120/40 = 3 h","Step 3: Difference = 4 − 3 = 1 h"],"options":[],"conceptId":"math_linear_motion_using_algebra_to_compare_two_travel_times","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Using Algebra to Compare Two Travel Times"}', 1),
  (230, 58, 'A train covers 300 km at 75 km/h while another covers the same distance at 60 km/h. Find the difference in travel time.', 'text', 1, 'Use distance divided by speed for each train.', '{"why":"The second train takes one additional hour to cover the same distance.","sol":"Step 1: First time = 300/75 = 4 h\nStep 2: Second time = 300/60 = 5 h\nStep 3: Difference = 5 − 4 = 1 h","steps":["Step 1: First time = 300/75 = 4 h","Step 2: Second time = 300/60 = 5 h","Step 3: Difference = 5 − 4 = 1 h"],"options":[],"conceptId":"math_linear_motion_using_algebra_to_compare_two_travel_times","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Using Algebra to Compare Two Travel Times"}', 2),
  (231, 59, 'A 150 km journey takes 3 hours for one car and 5 hours for another. Find both speeds.', 'text', 1, 'Use speed = distance ÷ time for each car.', '{"why":"Each speed is found by dividing the common distance by that vehicle''s travel time.","sol":"Step 1: First speed = 150/3 = 50 km/h\nStep 2: Second speed = 150/5 = 30 km/h","steps":["Step 1: First speed = 150/3 = 50 km/h","Step 2: Second speed = 150/5 = 30 km/h"],"options":[],"conceptId":"math_linear_motion_finding_speed_from_a_time_difference","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Speed from a Time Difference"}', 0),
  (232, 59, 'A 200 km journey takes 4 hours for one vehicle and 5 hours for another. Find both speeds.', 'text', 1, 'Calculate each speed separately.', '{"why":"The same distance divided by different times gives different speeds.","sol":"Step 1: First speed = 200/4 = 50 km/h\nStep 2: Second speed = 200/5 = 40 km/h","steps":["Step 1: First speed = 200/4 = 50 km/h","Step 2: Second speed = 200/5 = 40 km/h"],"options":[],"conceptId":"math_linear_motion_finding_speed_from_a_time_difference","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Speed from a Time Difference"}', 1),
  (233, 59, 'A 360 km journey takes 6 hours for one vehicle and 9 hours for another. Find both speeds.', 'text', 1, 'Use s = d/t.', '{"why":"Speed is distance divided by the time taken.","sol":"Step 1: First speed = 360/6 = 60 km/h\nStep 2: Second speed = 360/9 = 40 km/h","steps":["Step 1: First speed = 360/6 = 60 km/h","Step 2: Second speed = 360/9 = 40 km/h"],"options":[],"conceptId":"math_linear_motion_finding_speed_from_a_time_difference","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Speed from a Time Difference"}', 2),
  (234, 60, 'A car travels at 70 km/h for 4 hours. Find the distance travelled.', 'text', 1, 'Use d = st.', '{"why":"Distance is found by multiplying speed by time.","sol":"Step 1: d = st\nStep 2: d = 70 × 4\nStep 3: d = 280 km","steps":["Step 1: d = st","Step 2: d = 70 × 4","Step 3: d = 280 km"],"options":[],"conceptId":"math_linear_motion_using_distance_time_relationships","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Using Distance-Time Relationships"}', 0),
  (235, 60, 'A runner moves at 8 m/s for 25 seconds. Find the distance travelled.', 'text', 1, 'Multiply speed by time.', '{"why":"The runner covers 8 metres every second for 25 seconds.","sol":"Step 1: d = st\nStep 2: d = 8 × 25\nStep 3: d = 200 m","steps":["Step 1: d = st","Step 2: d = 8 × 25","Step 3: d = 200 m"],"options":[],"conceptId":"math_linear_motion_using_distance_time_relationships","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Using Distance-Time Relationships"}', 1),
  (236, 60, 'A vehicle travels 360 km at 90 km/h. Find the time taken.', 'text', 1, 'Rearrange d = st to make t the subject.', '{"why":"Time is distance divided by speed.","sol":"Step 1: 360 = 90t\nStep 2: t = 360 ÷ 90\nStep 3: t = 4 hours","steps":["Step 1: 360 = 90t","Step 2: t = 360 ÷ 90","Step 3: t = 4 hours"],"options":[],"conceptId":"math_linear_motion_using_distance_time_relationships","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Using Distance-Time Relationships"}', 2),
  (237, 61, 'A car travels 300 km in 5 hours. Find its speed.', 'text', 1, 'Speed = distance ÷ time.', '{"why":"Speed measures how much distance is covered in each unit of time.","sol":"Step 1: s = d/t\nStep 2: s = 300 ÷ 5\nStep 3: s = 60 km/h","steps":["Step 1: s = d/t","Step 2: s = 300 ÷ 5","Step 3: s = 60 km/h"],"options":[],"conceptId":"math_linear_motion_using_speed_time_relationships","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Using Speed-Time Relationships"}', 0),
  (238, 61, 'A cyclist covers 180 m in 30 seconds. Find the speed.', 'text', 1, 'Divide distance by time.', '{"why":"The cyclist covers 6 metres during each second.","sol":"Step 1: s = d/t\nStep 2: s = 180 ÷ 30\nStep 3: s = 6 m/s","steps":["Step 1: s = d/t","Step 2: s = 180 ÷ 30","Step 3: s = 6 m/s"],"options":[],"conceptId":"math_linear_motion_using_speed_time_relationships","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Using Speed-Time Relationships"}', 1),
  (239, 61, 'A train travels 450 km in 6 hours. Find its average speed.', 'text', 1, 'Average speed = total distance ÷ total time.', '{"why":"Average speed uses the total distance and the total time.","sol":"Step 1: Average speed = 450 ÷ 6\nStep 2: Average speed = 75 km/h","steps":["Step 1: Average speed = 450 ÷ 6","Step 2: Average speed = 75 km/h"],"options":[],"conceptId":"math_linear_motion_using_speed_time_relationships","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Using Speed-Time Relationships"}', 2),
  (240, 62, 'A distance-time graph passes through (2 s, 8 m) and (6 s, 28 m). Find the speed.', 'text', 1, 'Find change in distance and divide by change in time.', '{"why":"The gradient of a distance-time graph represents speed.","sol":"Step 1: Change in distance = 28 − 8 = 20 m\nStep 2: Change in time = 6 − 2 = 4 s\nStep 3: Speed = 20 ÷ 4\nStep 4: Speed = 5 m/s","steps":["Step 1: Change in distance = 28 − 8 = 20 m","Step 2: Change in time = 6 − 2 = 4 s","Step 3: Speed = 20 ÷ 4","Step 4: Speed = 5 m/s"],"options":[],"conceptId":"math_linear_motion_finding_speed_from_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Speed from a Distance-Time Graph"}', 0),
  (241, 62, 'A graph passes through (0 s, 0 m) and (10 s, 60 m). Find the speed.', 'text', 1, 'Use gradient = change in distance ÷ change in time.', '{"why":"The graph''s gradient gives the speed.","sol":"Step 1: Change in distance = 60 m\nStep 2: Change in time = 10 s\nStep 3: Speed = 60 ÷ 10\nStep 4: Speed = 6 m/s","steps":["Step 1: Change in distance = 60 m","Step 2: Change in time = 10 s","Step 3: Speed = 60 ÷ 10","Step 4: Speed = 6 m/s"],"options":[],"conceptId":"math_linear_motion_finding_speed_from_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Speed from a Distance-Time Graph"}', 1),
  (242, 62, 'A distance-time graph passes through (4 s, 12 m) and (9 s, 32 m). Find the speed.', 'text', 1, 'Subtract the coordinates first.', '{"why":"Speed is the gradient of the distance-time graph.","sol":"Step 1: Change in distance = 32 − 12 = 20 m\nStep 2: Change in time = 9 − 4 = 5 s\nStep 3: Speed = 20 ÷ 5\nStep 4: Speed = 4 m/s","steps":["Step 1: Change in distance = 32 − 12 = 20 m","Step 2: Change in time = 9 − 4 = 5 s","Step 3: Speed = 20 ÷ 5","Step 4: Speed = 4 m/s"],"options":[],"conceptId":"math_linear_motion_finding_speed_from_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Speed from a Distance-Time Graph"}', 2),
  (243, 63, 'A car travels 80 km in 2 hours and then 120 km in 3 hours. Find its average speed.', 'text', 1, 'Add the distances and add the times before dividing.', '{"why":"Average speed is based on total distance divided by total time.","sol":"Step 1: Total distance = 80 + 120 = 200 km\nStep 2: Total time = 2 + 3 = 5 hours\nStep 3: Average speed = 200 ÷ 5\nStep 4: Average speed = 40 km/h","steps":["Step 1: Total distance = 80 + 120 = 200 km","Step 2: Total time = 2 + 3 = 5 hours","Step 3: Average speed = 200 ÷ 5","Step 4: Average speed = 40 km/h"],"options":[],"conceptId":"math_linear_motion_average_speed_for_different_parts_of_a_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Average Speed for Different Parts of a Journey"}', 0),
  (244, 63, 'A cyclist travels 40 km in 2 hours and 30 km in 1 hour. Find the average speed.', 'text', 1, 'Do not average 20 km/h and 30 km/h directly.', '{"why":"The two parts take different amounts of time, so the total distance and total time must be used.","sol":"Step 1: Total distance = 40 + 30 = 70 km\nStep 2: Total time = 2 + 1 = 3 hours\nStep 3: Average speed = 70 ÷ 3\nStep 4: Average speed ≈ 23.33 km/h","steps":["Step 1: Total distance = 40 + 30 = 70 km","Step 2: Total time = 2 + 1 = 3 hours","Step 3: Average speed = 70 ÷ 3","Step 4: Average speed ≈ 23.33 km/h"],"options":[],"conceptId":"math_linear_motion_average_speed_for_different_parts_of_a_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Average Speed for Different Parts of a Journey"}', 1),
  (245, 63, 'A vehicle travels 150 km in 3 hours and 100 km in 2 hours. Find the average speed.', 'text', 1, 'Find total distance and total time.', '{"why":"Average speed measures the entire journey rather than treating each section separately.","sol":"Step 1: Total distance = 150 + 100 = 250 km\nStep 2: Total time = 3 + 2 = 5 hours\nStep 3: Average speed = 250 ÷ 5\nStep 4: Average speed = 50 km/h","steps":["Step 1: Total distance = 150 + 100 = 250 km","Step 2: Total time = 3 + 2 = 5 hours","Step 3: Average speed = 250 ÷ 5","Step 4: Average speed = 50 km/h"],"options":[],"conceptId":"math_linear_motion_average_speed_for_different_parts_of_a_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Average Speed for Different Parts of a Journey"}', 2),
  (246, 64, 'A vehicle travels at 70 km/h for 4 hours. Find the distance travelled.', 'text', 1, 'Identify speed and time, then use d = st.', '{"why":"Distance is obtained by multiplying speed by time.","sol":"Step 1: d = st\nStep 2: d = 70 × 4\nStep 3: d = 280 km","steps":["Step 1: d = st","Step 2: d = 70 × 4","Step 3: d = 280 km"],"options":[],"conceptId":"math_linear_motion_solving_a_complete_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Solving a Complete Motion Problem"}', 0),
  (247, 64, 'A bus travels 360 km in 6 hours. Find its average speed.', 'text', 1, 'Use speed = distance ÷ time.', '{"why":"Average speed is total distance divided by total time.","sol":"Step 1: s = d/t\nStep 2: s = 360 ÷ 6\nStep 3: s = 60 km/h","steps":["Step 1: s = d/t","Step 2: s = 360 ÷ 6","Step 3: s = 60 km/h"],"options":[],"conceptId":"math_linear_motion_solving_a_complete_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Solving a Complete Motion Problem"}', 1),
  (248, 64, 'A car travels 120 km at 60 km/h and then 180 km at 90 km/h. Find the total time.', 'text', 1, 'Find the time for each section separately, then add them.', '{"why":"The journey has two stages, so their individual times must be added.","sol":"Step 1: First section: t = 120 ÷ 60 = 2 hours\nStep 2: Second section: t = 180 ÷ 90 = 2 hours\nStep 3: Total time = 2 + 2\nStep 4: Total time = 4 hours","steps":["Step 1: First section: t = 120 ÷ 60 = 2 hours","Step 2: Second section: t = 180 ÷ 90 = 2 hours","Step 3: Total time = 2 + 2","Step 4: Total time = 4 hours"],"options":[],"conceptId":"math_linear_motion_solving_a_complete_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Solving a Complete Motion Problem"}', 2),
  (249, 65, 'Evaluate 3x + 5 when x = 2', 'text', 1, 'substitute first', '{"why":"Substitution must be done before simplifying","sol":"Step 1: Replace x with 2 → 3(2) + 5\nStep 2: Multiply → 6 + 5\nStep 3: = 11","steps":["Step 1: Replace x with 2 → 3(2) + 5","Step 2: Multiply → 6 + 5","Step 3: = 11"],"options":[],"conceptId":"math_algebra_algebraic_expressions","skillId":"math_algebra","subskillId":"math_algebra_q1","subject":"math","chapter":"algebra","topic":"Algebraic expressions"}', 0),
  (250, 65, 'Simplify 2x + 3x', 'text', 1, 'like terms', '{"why":"Only like terms can be combined","sol":"Step 1: 2x + 3x\nStep 2: (2 + 3)x\nStep 3: = 5x","steps":["Step 1: 2x + 3x","Step 2: (2 + 3)x","Step 3: = 5x"],"options":[],"conceptId":"math_algebra_algebraic_expressions","skillId":"math_algebra","subskillId":"math_algebra_q2","subject":"math","chapter":"algebra","topic":"Algebraic expressions"}', 1);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (251, 65, 'Identify: 4y + 7', 'text', 1, 'expression parts', '{"why":"It has variables and constants but no equation","sol":"Step 1: Contains variable y\nStep 2: Contains constant 7\nStep 3: No equals sign","steps":["Step 1: Contains variable y","Step 2: Contains constant 7","Step 3: No equals sign"],"options":[],"conceptId":"math_algebra_algebraic_expressions","skillId":"math_algebra","subskillId":"math_algebra_q3","subject":"math","chapter":"algebra","topic":"Algebraic expressions"}', 2),
  (252, 65, 'Translate: ‘5 less than a number x’', 'text', 1, 'subtract 5', '{"why":"Word phrases convert into algebraic expressions","sol":"Step 1: number x → x\nStep 2: 5 less → −5\nStep 3: x − 5","steps":["Step 1: number x → x","Step 2: 5 less → −5","Step 3: x − 5"],"options":[],"conceptId":"math_algebra_algebraic_expressions","skillId":"math_algebra","subskillId":"math_algebra_q4","subject":"math","chapter":"algebra","topic":"Algebraic expressions"}', 3),
  (253, 66, 'Simplify 3x + 4x + 2', 'text', 1, 'group like terms', '{"why":"Only like terms can be combined","sol":"Step 1: 3x + 4x = 7x\nStep 2: +2 remains unchanged\nStep 3: 7x + 2","steps":["Step 1: 3x + 4x = 7x","Step 2: +2 remains unchanged","Step 3: 7x + 2"],"options":[],"conceptId":"math_algebra_simplifying_expressions","skillId":"math_algebra","subskillId":"math_algebra_q1","subject":"math","chapter":"algebra","topic":"Simplifying expressions"}', 0),
  (254, 66, 'Simplify 6a - 2a', 'text', 1, 'subtract coefficients', '{"why":"Same variable means combine coefficients","sol":"Step 1: 6a − 2a\nStep 2: (6 − 2)a = 4a","steps":["Step 1: 6a − 2a","Step 2: (6 − 2)a = 4a"],"options":[],"conceptId":"math_algebra_simplifying_expressions","skillId":"math_algebra","subskillId":"math_algebra_q2","subject":"math","chapter":"algebra","topic":"Simplifying expressions"}', 1),
  (255, 66, 'Simplify 2x + 3y + 5x', 'text', 1, 'group x terms', '{"why":"Like terms grouped together","sol":"Step 1: (2x + 5x) + 3y\nStep 2: 7x + 3y","steps":["Step 1: (2x + 5x) + 3y","Step 2: 7x + 3y"],"options":[],"conceptId":"math_algebra_simplifying_expressions","skillId":"math_algebra","subskillId":"math_algebra_q3","subject":"math","chapter":"algebra","topic":"Simplifying expressions"}', 2),
  (256, 66, 'Simplify x + 2x + y + 3y', 'text', 1, 'group both variables', '{"why":"Combine each variable separately","sol":"Step 1: (x + 2x) + (y + 3y)\nStep 2: 3x + 4y","steps":["Step 1: (x + 2x) + (y + 3y)","Step 2: 3x + 4y"],"options":[],"conceptId":"math_algebra_simplifying_expressions","skillId":"math_algebra","subskillId":"math_algebra_q4","subject":"math","chapter":"algebra","topic":"Simplifying expressions"}', 3),
  (257, 67, 'Solve x + 5 = 12', 'text', 1, 'inverse operation', '{"why":"Maintain balance by doing same operation on both sides","sol":"Step 1: Subtract 5 from both sides\nStep 2: x = 12 − 5\nStep 3: x = 7","steps":["Step 1: Subtract 5 from both sides","Step 2: x = 12 − 5","Step 3: x = 7"],"options":[],"conceptId":"math_algebra_linear_equations","skillId":"math_algebra","subskillId":"math_algebra_q1","subject":"math","chapter":"algebra","topic":"Linear equations"}', 0),
  (258, 67, 'Solve 2x = 10', 'text', 1, 'divide both sides', '{"why":"Inverse of multiplication is division","sol":"Step 1: Divide both sides by 2\nStep 2: x = 5","steps":["Step 1: Divide both sides by 2","Step 2: x = 5"],"options":[],"conceptId":"math_algebra_linear_equations","skillId":"math_algebra","subskillId":"math_algebra_q2","subject":"math","chapter":"algebra","topic":"Linear equations"}', 1),
  (259, 67, 'Solve 3x + 2 = 11', 'text', 1, 'remove constant first', '{"why":"Isolate variable step by step","sol":"Step 1: 3x = 11 − 2\nStep 2: 3x = 9\nStep 3: x = 3","steps":["Step 1: 3x = 11 − 2","Step 2: 3x = 9","Step 3: x = 3"],"options":[],"conceptId":"math_algebra_linear_equations","skillId":"math_algebra","subskillId":"math_algebra_q3","subject":"math","chapter":"algebra","topic":"Linear equations"}', 2),
  (260, 67, 'Solve 4x − 6 = 10', 'text', 1, 'add 6 first', '{"why":"Move constants using inverse operations","sol":"Step 1: 4x = 10 + 6\nStep 2: 4x = 16\nStep 3: x = 4","steps":["Step 1: 4x = 10 + 6","Step 2: 4x = 16","Step 3: x = 4"],"options":[],"conceptId":"math_algebra_linear_equations","skillId":"math_algebra","subskillId":"math_algebra_q4","subject":"math","chapter":"algebra","topic":"Linear equations"}', 3),
  (261, 68, 'If x = 3, find x + 4', 'text', 1, 'replace x first', '{"why":"Substitution replaces variables with numbers","sol":"Step 1: Substitute x = 3\nStep 2: 3 + 4\nStep 3: = 7","steps":["Step 1: Substitute x = 3","Step 2: 3 + 4","Step 3: = 7"],"options":[],"conceptId":"math_algebra_substitution","skillId":"math_algebra","subskillId":"math_algebra_q1","subject":"math","chapter":"algebra","topic":"Substitution"}', 0),
  (262, 68, 'If x = 2, find 2x + 1', 'text', 1, 'multiply first', '{"why":"Follow multiplication before addition","sol":"Step 1: Substitute → 2(2) + 1\nStep 2: Multiply → 4 + 1\nStep 3: = 5","steps":["Step 1: Substitute → 2(2) + 1","Step 2: Multiply → 4 + 1","Step 3: = 5"],"options":[],"conceptId":"math_algebra_substitution","skillId":"math_algebra","subskillId":"math_algebra_q2","subject":"math","chapter":"algebra","topic":"Substitution"}', 1),
  (263, 68, 'If x = 4, y = 3, find x + y', 'text', 1, 'replace both variables', '{"why":"Both variables must be replaced","sol":"Step 1: Substitute → 4 + 3\nStep 2: Simplify\nStep 3: = 7","steps":["Step 1: Substitute → 4 + 3","Step 2: Simplify","Step 3: = 7"],"options":[],"conceptId":"math_algebra_substitution","skillId":"math_algebra","subskillId":"math_algebra_q3","subject":"math","chapter":"algebra","topic":"Substitution"}', 2),
  (264, 68, 'If x = 5, find 3x − 2', 'text', 1, 'multiply then subtract', '{"why":"Substitution followed by order of operations","sol":"Step 1: 3 × 5 = 15\nStep 2: 15 − 2\nStep 3: = 13","steps":["Step 1: 3 × 5 = 15","Step 2: 15 − 2","Step 3: = 13"],"options":[],"conceptId":"math_algebra_substitution","skillId":"math_algebra","subskillId":"math_algebra_q4","subject":"math","chapter":"algebra","topic":"Substitution"}', 3),
  (265, 69, 'Expand 2(x + 3)', 'text', 1, 'multiply each term', '{"why":"Distributive law multiplies each term inside bracket","sol":"Step 1: 2 × x = 2x\nStep 2: 2 × 3 = 6\nStep 3: Combine → 2x + 6","steps":["Step 1: 2 × x = 2x","Step 2: 2 × 3 = 6","Step 3: Combine → 2x + 6"],"options":[],"conceptId":"math_algebra_expanding_brackets","skillId":"math_algebra","subskillId":"math_algebra_q1","subject":"math","chapter":"algebra","topic":"Expanding brackets"}', 0),
  (266, 69, 'Expand 3(a + 2)', 'text', 1, 'distribute 3', '{"why":"Each term inside bracket must be multiplied","sol":"Step 1: 3 × a = 3a\nStep 2: 3 × 2 = 6\nStep 3: 3a + 6","steps":["Step 1: 3 × a = 3a","Step 2: 3 × 2 = 6","Step 3: 3a + 6"],"options":[],"conceptId":"math_algebra_expanding_brackets","skillId":"math_algebra","subskillId":"math_algebra_q2","subject":"math","chapter":"algebra","topic":"Expanding brackets"}', 1),
  (267, 69, 'Expand 4(x + 1)', 'text', 1, 'multiply each term', '{"why":"Distributive property applies to all terms","sol":"Step 1: 4 × x = 4x\nStep 2: 4 × 1 = 4\nStep 3: 4x + 4","steps":["Step 1: 4 × x = 4x","Step 2: 4 × 1 = 4","Step 3: 4x + 4"],"options":[],"conceptId":"math_algebra_expanding_brackets","skillId":"math_algebra","subskillId":"math_algebra_q3","subject":"math","chapter":"algebra","topic":"Expanding brackets"}', 2),
  (268, 69, 'What is the distributive law?', 'text', 1, 'a(b + c)', '{"why":"It ensures correct expansion of brackets","sol":"Step 1: Multiply outside term\nStep 2: Multiply each inside term\nStep 3: Combine results","steps":["Step 1: Multiply outside term","Step 2: Multiply each inside term","Step 3: Combine results"],"options":[],"conceptId":"math_algebra_expanding_brackets","skillId":"math_algebra","subskillId":"math_algebra_q4","subject":"math","chapter":"algebra","topic":"Expanding brackets"}', 3),
  (269, 70, 'Classify an angle of 24°.', 'text', 1, 'Compare it with 90°.', '{"why":"An acute angle is greater than 0° but less than 90°.","sol":"Step 1: 24° is less than 90°.\nStep 2: An angle between 0° and 90° is acute.","steps":["Step 1: 24° is less than 90°.","Step 2: An angle between 0° and 90° is acute."],"options":[],"conceptId":"math_geometry_classifying_angles","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Classifying Angles"}', 0),
  (270, 70, 'Classify an angle of 112°.', 'text', 1, 'Is it between 90° and 180°?', '{"why":"An obtuse angle is larger than a right angle but smaller than a straight angle.","sol":"Step 1: 90° < 112° < 180°.\nStep 2: An angle between 90° and 180° is obtuse.","steps":["Step 1: 90° < 112° < 180°.","Step 2: An angle between 90° and 180° is obtuse."],"options":[],"conceptId":"math_geometry_classifying_angles","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Classifying Angles"}', 1),
  (271, 70, 'An angle measures exactly 90°. What type is it?', 'text', 1, 'Think of a quarter-turn.', '{"why":"A right angle measures exactly 90°.","sol":"Step 1: The angle measures exactly 90°.\nStep 2: Therefore, it is a right angle.","steps":["Step 1: The angle measures exactly 90°.","Step 2: Therefore, it is a right angle."],"options":[],"conceptId":"math_geometry_classifying_angles","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Classifying Angles"}', 2),
  (272, 70, 'Can an angle of 180° be acute?', 'text', 1, 'An acute angle must be smaller than 90°.', '{"why":"Angle classification depends on the measured size.","sol":"Step 1: An acute angle is less than 90°.\nStep 2: 180° is a straight angle.\nStep 3: Therefore, it cannot be acute.","steps":["Step 1: An acute angle is less than 90°.","Step 2: 180° is a straight angle.","Step 3: Therefore, it cannot be acute."],"options":[],"conceptId":"math_geometry_classifying_angles","skillId":"math_geometry","subskillId":"math_geometry_q4","subject":"math","chapter":"geometry","topic":"Classifying Angles"}', 3),
  (273, 71, 'Two adjacent angles on a straight line are 127° and x°. Find x.', 'text', 1, 'Their sum is 180°.', '{"why":"Angles forming a straight line total 180°.","sol":"Step 1: 127° + x = 180°\nStep 2: x = 180° - 127°\nStep 3: x = 53°.","steps":["Step 1: 127° + x = 180°","Step 2: x = 180° - 127°","Step 3: x = 53°."],"options":[],"conceptId":"math_geometry_angles_on_a_straight_line","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Angles on a Straight Line"}', 0),
  (274, 71, 'Angles 2x° and 70° lie on a straight line. Find x.', 'text', 1, 'Write 2x + 70 = 180.', '{"why":"Use the straight-line angle sum to form an equation.","sol":"Step 1: 2x + 70 = 180\nStep 2: 2x = 110\nStep 3: x = 110 / 2\nStep 4: x = 55.","steps":["Step 1: 2x + 70 = 180","Step 2: 2x = 110","Step 3: x = 110 / 2","Step 4: x = 55."],"options":[],"conceptId":"math_geometry_angles_on_a_straight_line","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Angles on a Straight Line"}', 1),
  (275, 71, 'Three angles on a straight line are 42°, 91° and x°. Find x.', 'text', 1, 'Add the known angles, then subtract from 180°.', '{"why":"All adjacent angles forming the straight angle sum to 180°.","sol":"Step 1: 42° + 91° = 133°\nStep 2: 133° + x = 180°\nStep 3: x = 180° - 133°\nStep 4: x = 47°.","steps":["Step 1: 42° + 91° = 133°","Step 2: 133° + x = 180°","Step 3: x = 180° - 133°","Step 4: x = 47°."],"options":[],"conceptId":"math_geometry_angles_on_a_straight_line","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Angles on a Straight Line"}', 2),
  (276, 72, 'Angles around a point are 75°, 125° and x°. Find x.', 'text', 1, 'A complete turn is 360°.', '{"why":"Angles around a point make one complete turn of 360°.","sol":"Step 1: 75° + 125° = 200°\nStep 2: x = 360° - 200°\nStep 3: x = 160°.","steps":["Step 1: 75° + 125° = 200°","Step 2: x = 360° - 200°","Step 3: x = 160°."],"options":[],"conceptId":"math_geometry_angles_around_a_point","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Angles Around a Point"}', 0),
  (277, 72, 'Five equal angles meet at a point. Find each angle.', 'text', 1, 'Divide 360° equally among five angles.', '{"why":"Equal angles share the complete turn equally.","sol":"Step 1: Total angle = 360°\nStep 2: Each angle = 360° / 5\nStep 3: Each angle = 72°.","steps":["Step 1: Total angle = 360°","Step 2: Each angle = 360° / 5","Step 3: Each angle = 72°."],"options":[],"conceptId":"math_geometry_angles_around_a_point","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Angles Around a Point"}', 1),
  (278, 72, 'Angles x°, 2x°, 3x° and 60° meet at a point. Find x.', 'text', 1, 'Their sum is 360°.', '{"why":"Use the 360° total to form an equation.","sol":"Step 1: x + 2x + 3x + 60 = 360\nStep 2: 6x + 60 = 360\nStep 3: 6x = 300\nStep 4: x = 50.","steps":["Step 1: x + 2x + 3x + 60 = 360","Step 2: 6x + 60 = 360","Step 3: 6x = 300","Step 4: x = 50."],"options":[],"conceptId":"math_geometry_angles_around_a_point","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Angles Around a Point"}', 2),
  (279, 73, 'Two straight lines cross. One angle is 83°. Find the vertically opposite angle.', 'text', 1, 'Opposite angles formed by intersecting lines are equal.', '{"why":"Vertically opposite angles are equal.","sol":"Step 1: The given angle is 83°.\nStep 2: The opposite angle equals it.\nStep 3: Answer = 83°.","steps":["Step 1: The given angle is 83°.","Step 2: The opposite angle equals it.","Step 3: Answer = 83°."],"options":[],"conceptId":"math_geometry_vertically_opposite_angles","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Vertically Opposite Angles"}', 0),
  (280, 73, 'Opposite angles are (5x - 8)° and 72°. Find x.', 'text', 1, 'Set the two angle expressions equal.', '{"why":"Equal vertically opposite angles give an equation.","sol":"Step 1: 5x - 8 = 72\nStep 2: 5x = 80\nStep 3: x = 16.","steps":["Step 1: 5x - 8 = 72","Step 2: 5x = 80","Step 3: x = 16."],"options":[],"conceptId":"math_geometry_vertically_opposite_angles","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Vertically Opposite Angles"}', 1),
  (281, 73, 'An angle at an intersection is 121°. Find the smaller adjacent angle.', 'text', 1, 'Adjacent angles on a straight line total 180°.', '{"why":"The adjacent angle and 121° form a straight angle.","sol":"Step 1: Adjacent angle = 180° - 121°\nStep 2: Adjacent angle = 59°.","steps":["Step 1: Adjacent angle = 180° - 121°","Step 2: Adjacent angle = 59°."],"options":[],"conceptId":"math_geometry_vertically_opposite_angles","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Vertically Opposite Angles"}', 2),
  (282, 74, 'Two parallel lines are crossed by a transversal. A corresponding angle is 74°. Find its partner.', 'text', 1, 'Corresponding angles are equal for parallel lines.', '{"why":"Corresponding angles are equal when the lines are parallel.","sol":"Step 1: The lines are parallel.\nStep 2: Corresponding angles are equal.\nStep 3: The required angle is 74°.","steps":["Step 1: The lines are parallel.","Step 2: Corresponding angles are equal.","Step 3: The required angle is 74°."],"options":[],"conceptId":"math_geometry_parallel_lines_and_a_transversal","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Parallel Lines and a Transversal"}', 0),
  (283, 74, 'One alternate interior angle is 126°. Find the other alternate interior angle.', 'text', 1, 'Alternate interior angles are equal.', '{"why":"The alternate interior angle rule applies to parallel lines.","sol":"Step 1: The lines are parallel.\nStep 2: Alternate interior angles are equal.\nStep 3: The required angle is 126°.","steps":["Step 1: The lines are parallel.","Step 2: Alternate interior angles are equal.","Step 3: The required angle is 126°."],"options":[],"conceptId":"math_geometry_parallel_lines_and_a_transversal","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Parallel Lines and a Transversal"}', 1),
  (284, 74, 'Co-interior angles are (2x + 10)° and 110°. Find x.', 'text', 1, 'Co-interior angles add up to 180°.', '{"why":"Co-interior angles on parallel lines are supplementary.","sol":"Step 1: 2x + 10 + 110 = 180\nStep 2: 2x + 120 = 180\nStep 3: 2x = 60\nStep 4: x = 30.","steps":["Step 1: 2x + 10 + 110 = 180","Step 2: 2x + 120 = 180","Step 3: 2x = 60","Step 4: x = 30."],"options":[],"conceptId":"math_geometry_parallel_lines_and_a_transversal","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Parallel Lines and a Transversal"}', 2),
  (285, 74, 'A co-interior angle is 97°. Find the other angle.', 'text', 1, 'Subtract 97° from 180°.', '{"why":"The two co-interior angles add up to 180°.","sol":"Step 1: Other angle = 180° - 97°\nStep 2: Other angle = 83°.","steps":["Step 1: Other angle = 180° - 97°","Step 2: Other angle = 83°."],"options":[],"conceptId":"math_geometry_parallel_lines_and_a_transversal","skillId":"math_geometry","subskillId":"math_geometry_q4","subject":"math","chapter":"geometry","topic":"Parallel Lines and a Transversal"}', 3),
  (286, 75, 'A triangle has angles 45°, 65° and x°. Find x.', 'text', 1, 'Add 45° and 65°, then subtract their sum from 180°.', '{"why":"The missing angle is the difference between 180° and the sum of the two known angles.","sol":"Step 1: The interior angles of a triangle add up to 180°.\nStep 2: 45° + 65° + x = 180°.\nStep 3: 110° + x = 180°.\nStep 4: x = 180° - 110° = 70°.","steps":["Step 1: The interior angles of a triangle add up to 180°.","Step 2: 45° + 65° + x = 180°.","Step 3: 110° + x = 180°.","Step 4: x = 180° - 110° = 70°."],"options":[],"conceptId":"math_geometry_triangle_angle_sum","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Triangle Angle Sum"}', 0),
  (287, 75, 'Two angles of a triangle are 28° and 92°. Calculate the third angle.', 'text', 1, 'Find 28° + 92° first.', '{"why":"The three interior angles must total exactly 180°.","sol":"Step 1: Add the known angles: 28° + 92° = 120°.\nStep 2: Subtract their sum from 180°.\nStep 3: x = 180° - 120° = 60°.","steps":["Step 1: Add the known angles: 28° + 92° = 120°.","Step 2: Subtract their sum from 180°.","Step 3: x = 180° - 120° = 60°."],"options":[],"conceptId":"math_geometry_triangle_angle_sum","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Triangle Angle Sum"}', 1),
  (288, 75, 'The angles of a triangle are x°, 2x° and 30°. Find x.', 'text', 1, 'Form the equation x + 2x + 30 = 180.', '{"why":"The equation represents all three angles. Substituting x = 50° gives 50°, 100° and 30°, which total 180°.","sol":"Step 1: Write the angle-sum equation: x + 2x + 30 = 180.\nStep 2: Collect like terms: 3x + 30 = 180.\nStep 3: Subtract 30: 3x = 150.\nStep 4: Divide by 3: x = 50°.","steps":["Step 1: Write the angle-sum equation: x + 2x + 30 = 180.","Step 2: Collect like terms: 3x + 30 = 180.","Step 3: Subtract 30: 3x = 150.","Step 4: Divide by 3: x = 50°."],"options":[],"conceptId":"math_geometry_triangle_angle_sum","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Triangle Angle Sum"}', 2),
  (289, 76, 'An isosceles triangle has a top angle of 36°. Find each base angle.', 'text', 1, 'Subtract 36° from 180°, then divide the result by 2.', '{"why":"The base angles are equal and together they must total 144°.","sol":"Step 1: The two base angles share the remaining angle sum.\nStep 2: 180° - 36° = 144°.\nStep 3: 144° ÷ 2 = 72°.\nStep 4: Each base angle is 72°.","steps":["Step 1: The two base angles share the remaining angle sum.","Step 2: 180° - 36° = 144°.","Step 3: 144° ÷ 2 = 72°.","Step 4: Each base angle is 72°."],"options":[],"conceptId":"math_geometry_isosceles_triangle_base_angles","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Isosceles Triangle Base Angles"}', 0),
  (290, 76, 'Each base angle of an isosceles triangle is 48°. Find its top angle.', 'text', 1, 'Add the base angles before subtracting from 180°.', '{"why":"The top angle is the remaining part of the triangle''s 180° angle sum.","sol":"Step 1: Add the base angles: 48° + 48° = 96°.\nStep 2: Subtract from 180°: 180° - 96° = 84°.","steps":["Step 1: Add the base angles: 48° + 48° = 96°.","Step 2: Subtract from 180°: 180° - 96° = 84°."],"options":[],"conceptId":"math_geometry_isosceles_triangle_base_angles","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Isosceles Triangle Base Angles"}', 1),
  (291, 76, 'An isosceles triangle has angles x°, x° and 4x°. Find x.', 'text', 1, 'Write x + x + 4x = 180.', '{"why":"The two equal base angles are both 30°, while the third angle is four times x.","sol":"Step 1: Combine the angles: x + x + 4x = 180.\nStep 2: Simplify: 6x = 180.\nStep 3: Divide by 6: x = 30°.\nStep 4: The angles are 30°, 30° and 120°.","steps":["Step 1: Combine the angles: x + x + 4x = 180.","Step 2: Simplify: 6x = 180.","Step 3: Divide by 6: x = 30°.","Step 4: The angles are 30°, 30° and 120°."],"options":[],"conceptId":"math_geometry_isosceles_triangle_base_angles","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Isosceles Triangle Base Angles"}', 2),
  (292, 77, 'The two opposite interior angles of a triangle are 38° and 72°. Find the exterior angle.', 'text', 1, 'Add the two opposite interior angles.', '{"why":"An exterior angle equals the sum of the two opposite interior angles.","sol":"Step 1: Use the exterior angle rule.\nStep 2: Exterior angle = 38° + 72°.\nStep 3: Exterior angle = 110°.","steps":["Step 1: Use the exterior angle rule.","Step 2: Exterior angle = 38° + 72°.","Step 3: Exterior angle = 110°."],"options":[],"conceptId":"math_geometry_exterior_angle_of_a_triangle","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Exterior Angle of a Triangle"}', 0),
  (293, 77, 'An exterior angle is 132°. One opposite interior angle is 57°. Find the other opposite interior angle.', 'text', 1, 'Subtract 57° from 132°.', '{"why":"The two opposite interior angles together equal the exterior angle.","sol":"Step 1: Let the missing angle be x.\nStep 2: 132° = 57° + x.\nStep 3: x = 132° - 57°.\nStep 4: x = 75°.","steps":["Step 1: Let the missing angle be x.","Step 2: 132° = 57° + x.","Step 3: x = 132° - 57°.","Step 4: x = 75°."],"options":[],"conceptId":"math_geometry_exterior_angle_of_a_triangle","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Exterior Angle of a Triangle"}', 1),
  (294, 77, 'An exterior angle of a triangle is 118°. Calculate the interior angle next to it.', 'text', 1, 'The two adjacent angles on a straight line add up to 180°.', '{"why":"The adjacent interior and exterior angles form a straight line, so they add up to 180°.","sol":"Step 1: Let the adjacent interior angle be x.\nStep 2: x + 118° = 180°.\nStep 3: x = 180° - 118°.\nStep 4: x = 62°.","steps":["Step 1: Let the adjacent interior angle be x.","Step 2: x + 118° = 180°.","Step 3: x = 180° - 118°.","Step 4: x = 62°."],"options":[],"conceptId":"math_geometry_exterior_angle_of_a_triangle","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Exterior Angle of a Triangle"}', 2),
  (295, 78, 'A triangle has sides 9 cm, 9 cm and 9 cm. Classify it by its sides.', 'text', 1, 'Check whether all three lengths are equal.', '{"why":"An equilateral triangle has three equal sides.","sol":"Step 1: Compare the three side lengths.\nStep 2: All three sides are 9 cm.\nStep 3: Therefore, the triangle is equilateral.","steps":["Step 1: Compare the three side lengths.","Step 2: All three sides are 9 cm.","Step 3: Therefore, the triangle is equilateral."],"options":[],"conceptId":"math_geometry_classifying_triangles_by_sides","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Classifying Triangles by Sides"}', 0),
  (296, 78, 'A triangle has sides 8 cm, 8 cm and 5 cm. Classify it by its sides.', 'text', 1, 'Count how many sides have the same length.', '{"why":"An isosceles triangle has two equal sides.","sol":"Step 1: Two sides are 8 cm.\nStep 2: The third side is 5 cm.\nStep 3: Exactly two sides are equal, so it is isosceles.","steps":["Step 1: Two sides are 8 cm.","Step 2: The third side is 5 cm.","Step 3: Exactly two sides are equal, so it is isosceles."],"options":[],"conceptId":"math_geometry_classifying_triangles_by_sides","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Classifying Triangles by Sides"}', 1),
  (297, 78, 'A learner says a triangle with sides 3 cm, 4 cm and 8 cm is scalene. Is the learner correct?', 'text', 1, 'Before classifying, check whether the lengths can form a triangle.', '{"why":"Having three different lengths is not enough. The sum of the two shorter sides must be greater than the longest side.","sol":"Step 1: Add the two shorter sides: 3 + 4 = 7.\nStep 2: Compare this sum with the longest side, 8.\nStep 3: Since 7 is not greater than 8, the triangle inequality fails.\nStep 4: These lengths cannot form a triangle, so classifying them as a scalene triangle is incorrect.","steps":["Step 1: Add the two shorter sides: 3 + 4 = 7.","Step 2: Compare this sum with the longest side, 8.","Step 3: Since 7 is not greater than 8, the triangle inequality fails.","Step 4: These lengths cannot form a triangle, so classifying them as a scalene triangle is incorrect."],"options":[],"conceptId":"math_geometry_classifying_triangles_by_sides","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Classifying Triangles by Sides"}', 2),
  (298, 79, 'A right-angled triangle has shorter sides of 9 cm and 12 cm. Find the hypotenuse.', 'text', 1, 'Use c² = 9² + 12².', '{"why":"The hypotenuse is found by adding the squares of the two shorter sides and then taking the square root.","sol":"Step 1: c² = 9² + 12².\nStep 2: c² = 81 + 144.\nStep 3: c² = 225.\nStep 4: c = √225.\nStep 5: c = 15 cm.","steps":["Step 1: c² = 9² + 12².","Step 2: c² = 81 + 144.","Step 3: c² = 225.","Step 4: c = √225.","Step 5: c = 15 cm."],"options":[],"conceptId":"math_geometry_pythagoras_theorem","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Pythagoras'' Theorem"}', 0),
  (299, 79, 'A right-angled triangle has a hypotenuse of 17 m and one shorter side of 8 m. Find the other shorter side.', 'text', 1, 'Use b² = c² - a².', '{"why":"When finding a shorter side, subtract the square of the known shorter side from the square of the hypotenuse.","sol":"Step 1: 17² = 8² + b².\nStep 2: 289 = 64 + b².\nStep 3: 289 - 64 = b².\nStep 4: 225 = b².\nStep 5: b = √225.\nStep 6: b = 15 m.","steps":["Step 1: 17² = 8² + b².","Step 2: 289 = 64 + b².","Step 3: 289 - 64 = b².","Step 4: 225 = b².","Step 5: b = √225.","Step 6: b = 15 m."],"options":[],"conceptId":"math_geometry_pythagoras_theorem","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Pythagoras'' Theorem"}', 1),
  (300, 79, 'A learner uses 10² = 6² - 8² to find the hypotenuse of a triangle with shorter sides 6 cm and 8 cm. Identify the error and find the correct hypotenuse.', 'text', 1, 'When finding the hypotenuse, the two shorter-side squares are added.', '{"why":"The learner subtracted the squares. To find the hypotenuse, the squares of the two shorter sides must be added.","sol":"Step 1: The hypotenuse is found using c² = a² + b².\nStep 2: c² = 6² + 8².\nStep 3: c² = 36 + 64.\nStep 4: c² = 100.\nStep 5: c = √100.\nStep 6: c = 10 cm.","steps":["Step 1: The hypotenuse is found using c² = a² + b².","Step 2: c² = 6² + 8².","Step 3: c² = 36 + 64.","Step 4: c² = 100.","Step 5: c = √100.","Step 6: c = 10 cm."],"options":[],"conceptId":"math_geometry_pythagoras_theorem","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Pythagoras'' Theorem"}', 2),
  (301, 79, 'The sides of a triangle are 7 cm, 24 cm and 25 cm. The triangle is right-angled. Verify Pythagoras'' theorem.', 'text', 1, 'The longest side is the hypotenuse.', '{"why":"The square of the hypotenuse equals the sum of the squares of the two shorter sides.","sol":"Step 1: The hypotenuse is 25 cm.\nStep 2: 25² = 625.\nStep 3: 7² + 24² = 49 + 576.\nStep 4: 7² + 24² = 625.\nStep 5: Therefore, 25² = 7² + 24².","steps":["Step 1: The hypotenuse is 25 cm.","Step 2: 25² = 625.","Step 3: 7² + 24² = 49 + 576.","Step 4: 7² + 24² = 625.","Step 5: Therefore, 25² = 7² + 24²."],"options":[],"conceptId":"math_geometry_pythagoras_theorem","skillId":"math_geometry","subskillId":"math_geometry_q4","subject":"math","chapter":"geometry","topic":"Pythagoras'' Theorem"}', 3),
  (302, 80, 'Three angles of a quadrilateral are 70°, 110° and 95°. Find the fourth angle.', 'text', 1, 'Add the three known angles and subtract from 360°.', '{"why":"The four interior angles of a quadrilateral total 360°.","sol":"Step 1: Add the known angles: 70° + 110° + 95° = 275°.\nStep 2: Subtract from 360°: 360° - 275° = 85°.","steps":["Step 1: Add the known angles: 70° + 110° + 95° = 275°.","Step 2: Subtract from 360°: 360° - 275° = 85°."],"options":[],"conceptId":"math_geometry_quadrilateral_interior_angle_sum","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Quadrilateral Interior Angle Sum"}', 0),
  (303, 80, 'A quadrilateral has angles 90°, 90°, 90° and x°. Find x.', 'text', 1, 'Three right angles total 270°.', '{"why":"The missing angle must complete the quadrilateral''s 360° total.","sol":"Step 1: Add the known angles: 90° + 90° + 90° = 270°.\nStep 2: Subtract from 360°: x = 360° - 270°.\nStep 3: Therefore, x = 90°.","steps":["Step 1: Add the known angles: 90° + 90° + 90° = 270°.","Step 2: Subtract from 360°: x = 360° - 270°.","Step 3: Therefore, x = 90°."],"options":[],"conceptId":"math_geometry_quadrilateral_interior_angle_sum","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Quadrilateral Interior Angle Sum"}', 1),
  (304, 80, 'The angles of a quadrilateral are x°, 2x°, 3x° and 60°. Find x.', 'text', 1, 'Form the equation x + 2x + 3x + 60 = 360.', '{"why":"The four angles must total 360°. Substitution gives 50°, 100°, 150° and 60°, which total 360°.","sol":"Step 1: Add the angles: x + 2x + 3x + 60 = 360.\nStep 2: Collect like terms: 6x + 60 = 360.\nStep 3: Subtract 60: 6x = 300.\nStep 4: Divide by 6: x = 50°.","steps":["Step 1: Add the angles: x + 2x + 3x + 60 = 360.","Step 2: Collect like terms: 6x + 60 = 360.","Step 3: Subtract 60: 6x = 300.","Step 4: Divide by 6: x = 50°."],"options":[],"conceptId":"math_geometry_quadrilateral_interior_angle_sum","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Quadrilateral Interior Angle Sum"}', 2),
  (305, 81, 'A parallelogram has AB = 14 cm. If CD is opposite AB, find CD.', 'text', 1, 'Opposite sides of a parallelogram are equal.', '{"why":"Opposite sides of a parallelogram have equal lengths.","sol":"Step 1: AB and CD are opposite sides.\nStep 2: Therefore, AB = CD.\nStep 3: CD = 14 cm.","steps":["Step 1: AB and CD are opposite sides.","Step 2: Therefore, AB = CD.","Step 3: CD = 14 cm."],"options":[],"conceptId":"math_geometry_parallelogram_opposite_sides_are_equal","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Parallelogram: Opposite Sides Are Equal"}', 0),
  (306, 81, 'Opposite sides of a parallelogram are (4x - 3) cm and 21 cm. Find x.', 'text', 1, 'Set 4x - 3 equal to 21.', '{"why":"The two expressions describe opposite sides, which must have equal lengths.","sol":"Step 1: Set the opposite sides equal: 4x - 3 = 21.\nStep 2: Add 3 to both sides: 4x = 24.\nStep 3: Divide both sides by 4: x = 6.","steps":["Step 1: Set the opposite sides equal: 4x - 3 = 21.","Step 2: Add 3 to both sides: 4x = 24.","Step 3: Divide both sides by 4: x = 6."],"options":[],"conceptId":"math_geometry_parallelogram_opposite_sides_are_equal","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Parallelogram: Opposite Sides Are Equal"}', 1),
  (307, 81, 'A parallelogram has adjacent sides of 11 cm and 7 cm. A learner says every side must be 11 cm. Explain the error and calculate the perimeter.', 'text', 1, 'Only opposite sides must be equal. Add all four sides.', '{"why":"A parallelogram has equal opposite sides, not necessarily four equal sides.","sol":"Step 1: The side lengths are 11 cm, 7 cm, 11 cm and 7 cm.\nStep 2: The sides of length 11 cm are opposite each other.\nStep 3: The sides of length 7 cm are also opposite each other.\nStep 4: Perimeter = 11 + 7 + 11 + 7 = 36 cm.","steps":["Step 1: The side lengths are 11 cm, 7 cm, 11 cm and 7 cm.","Step 2: The sides of length 11 cm are opposite each other.","Step 3: The sides of length 7 cm are also opposite each other.","Step 4: Perimeter = 11 + 7 + 11 + 7 = 36 cm."],"options":[],"conceptId":"math_geometry_parallelogram_opposite_sides_are_equal","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Parallelogram: Opposite Sides Are Equal"}', 2),
  (308, 82, 'One angle of a parallelogram is 112°. Find its opposite angle.', 'text', 1, 'Opposite angles are equal.', '{"why":"Opposite angles of a parallelogram have equal measures.","sol":"Step 1: Identify the angle opposite 112°.\nStep 2: Opposite angles are equal.\nStep 3: The missing angle is 112°.","steps":["Step 1: Identify the angle opposite 112°.","Step 2: Opposite angles are equal.","Step 3: The missing angle is 112°."],"options":[],"conceptId":"math_geometry_parallelogram_opposite_angles_are_equal","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Parallelogram: Opposite Angles Are Equal"}', 0),
  (309, 82, 'Opposite angles are (5x - 20)° and 80°. Find x.', 'text', 1, 'Set 5x - 20 equal to 80.', '{"why":"The angles are opposite, so their expressions must have equal values.","sol":"Step 1: Write 5x - 20 = 80.\nStep 2: Add 20 to both sides: 5x = 100.\nStep 3: Divide by 5: x = 20.","steps":["Step 1: Write 5x - 20 = 80.","Step 2: Add 20 to both sides: 5x = 100.","Step 3: Divide by 5: x = 20."],"options":[],"conceptId":"math_geometry_parallelogram_opposite_angles_are_equal","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Parallelogram: Opposite Angles Are Equal"}', 1),
  (310, 82, 'A parallelogram has one angle of 64°. Find the other three angles.', 'text', 1, 'The opposite angle equals 64°. Each adjacent angle is 180° - 64°.', '{"why":"Opposite angles are equal, while adjacent angles are supplementary.","sol":"Step 1: The opposite angle is 64°.\nStep 2: Calculate each adjacent angle: 180° - 64° = 116°.\nStep 3: The four angles are 64°, 116°, 64° and 116°.","steps":["Step 1: The opposite angle is 64°.","Step 2: Calculate each adjacent angle: 180° - 64° = 116°.","Step 3: The four angles are 64°, 116°, 64° and 116°."],"options":[],"conceptId":"math_geometry_parallelogram_opposite_angles_are_equal","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Parallelogram: Opposite Angles Are Equal"}', 2),
  (311, 83, 'One angle of a parallelogram is 83°. Find an adjacent angle.', 'text', 1, 'Subtract 83° from 180°.', '{"why":"The adjacent angle must complete the 180° total.","sol":"Step 1: Adjacent angles add to 180°.\nStep 2: 83° + x = 180°.\nStep 3: x = 180° - 83° = 97°.","steps":["Step 1: Adjacent angles add to 180°.","Step 2: 83° + x = 180°.","Step 3: x = 180° - 83° = 97°."],"options":[],"conceptId":"math_geometry_parallelogram_adjacent_angles","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Parallelogram: Adjacent Angles"}', 0),
  (312, 83, 'Adjacent angles are (4x + 5)° and 95°. Find x.', 'text', 1, 'Their sum is 180°.', '{"why":"Adjacent angles in a parallelogram are supplementary.","sol":"Step 1: Write 4x + 5 + 95 = 180.\nStep 2: Simplify: 4x + 100 = 180.\nStep 3: Subtract 100: 4x = 80.\nStep 4: Divide by 4: x = 20.","steps":["Step 1: Write 4x + 5 + 95 = 180.","Step 2: Simplify: 4x + 100 = 180.","Step 3: Subtract 100: 4x = 80.","Step 4: Divide by 4: x = 20."],"options":[],"conceptId":"math_geometry_parallelogram_adjacent_angles","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Parallelogram: Adjacent Angles"}', 1),
  (313, 83, 'Two adjacent angles of a parallelogram are in the ratio 4:5. Find both angles.', 'text', 1, 'Represent the angles as 4x and 5x and use their 180° sum.', '{"why":"The ratio gives the relative sizes, and the supplementary-angle rule supplies their total.","sol":"Step 1: Let the angles be 4x and 5x.\nStep 2: 4x + 5x = 180.\nStep 3: 9x = 180, so x = 20.\nStep 4: The angles are 4(20) = 80° and 5(20) = 100°.","steps":["Step 1: Let the angles be 4x and 5x.","Step 2: 4x + 5x = 180.","Step 3: 9x = 180, so x = 20.","Step 4: The angles are 4(20) = 80° and 5(20) = 100°."],"options":[],"conceptId":"math_geometry_parallelogram_adjacent_angles","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Parallelogram: Adjacent Angles"}', 2),
  (314, 84, 'A circle has radius 7 cm. Calculate its diameter.', 'text', 1, 'Multiply the radius by 2.', '{"why":"A diameter consists of two radii placed end to end through the centre.","sol":"Step 1: Diameter = 2 × radius.\nStep 2: Diameter = 2 × 7.\nStep 3: Diameter = 14 cm.","steps":["Step 1: Diameter = 2 × radius.","Step 2: Diameter = 2 × 7.","Step 3: Diameter = 14 cm."],"options":[],"conceptId":"math_geometry_circle_radius_and_diameter","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Circle: Radius and Diameter"}', 0),
  (315, 84, 'The diameter of a circle is 26 cm. Find its radius.', 'text', 1, 'Divide the diameter by 2.', '{"why":"The radius is half the diameter.","sol":"Step 1: Radius = diameter ÷ 2.\nStep 2: Radius = 26 ÷ 2.\nStep 3: Radius = 13 cm.","steps":["Step 1: Radius = diameter ÷ 2.","Step 2: Radius = 26 ÷ 2.","Step 3: Radius = 13 cm."],"options":[],"conceptId":"math_geometry_circle_radius_and_diameter","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Circle: Radius and Diameter"}', 1),
  (316, 84, 'A learner says a circle with radius 8 cm has diameter 8 cm. Identify the error and give the correct diameter.', 'text', 1, 'The learner has treated the radius and diameter as the same length.', '{"why":"The diameter passes through the centre and spans two radii.","sol":"Step 1: The radius is 8 cm.\nStep 2: Diameter = 2 × radius.\nStep 3: Diameter = 2 × 8 = 16 cm.\nStep 4: The learner forgot that the diameter is twice the radius.","steps":["Step 1: The radius is 8 cm.","Step 2: Diameter = 2 × radius.","Step 3: Diameter = 2 × 8 = 16 cm.","Step 4: The learner forgot that the diameter is twice the radius."],"options":[],"conceptId":"math_geometry_circle_radius_and_diameter","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Circle: Radius and Diameter"}', 2),
  (317, 85, 'A circle has radius 5 cm. Find its circumference in terms of π.', 'text', 1, 'Use C = 2πr.', '{"why":"The radius formula multiplies the radius by 2π.","sol":"Step 1: Use C = 2πr.\nStep 2: Substitute r = 5.\nStep 3: C = 2 × π × 5 = 10π cm.","steps":["Step 1: Use C = 2πr.","Step 2: Substitute r = 5.","Step 3: C = 2 × π × 5 = 10π cm."],"options":[],"conceptId":"math_geometry_circumference_of_a_circle","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Circumference of a Circle"}', 0),
  (318, 85, 'A circle has diameter 14 m. Find its circumference in terms of π.', 'text', 1, 'Use C = πd because the diameter is given.', '{"why":"The circumference equals π multiplied by the diameter.","sol":"Step 1: Use C = πd.\nStep 2: Substitute d = 14.\nStep 3: C = 14π m.","steps":["Step 1: Use C = πd.","Step 2: Substitute d = 14.","Step 3: C = 14π m."],"options":[],"conceptId":"math_geometry_circumference_of_a_circle","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Circumference of a Circle"}', 1),
  (319, 85, 'A learner calculates the circumference of a circle with radius 4 cm as 16π cm². Identify the error and give the correct answer.', 'text', 1, 'Check both the formula and the unit.', '{"why":"The learner used an incorrect calculation and a square unit. Circumference is a one-dimensional length.","sol":"Step 1: Use C = 2πr.\nStep 2: Substitute r = 4: C = 2 × π × 4.\nStep 3: C = 8π cm.\nStep 4: Circumference is a length, so the unit is cm, not cm².","steps":["Step 1: Use C = 2πr.","Step 2: Substitute r = 4: C = 2 × π × 4.","Step 3: C = 8π cm.","Step 4: Circumference is a length, so the unit is cm, not cm²."],"options":[],"conceptId":"math_geometry_circumference_of_a_circle","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Circumference of a Circle"}', 2),
  (320, 86, 'A circle has a radius of 6 cm. Find its area. Use π = 3.142.', 'text', 1, 'Use A = πr² and remember to square the radius.', '{"why":"The area of a circle is found by multiplying π by the square of its radius.","sol":"Step 1: A = πr².\nStep 2: A = 3.142 × 6².\nStep 3: 6² = 36.\nStep 4: A = 3.142 × 36.\nStep 5: A = 113.112 cm².","steps":["Step 1: A = πr².","Step 2: A = 3.142 × 6².","Step 3: 6² = 36.","Step 4: A = 3.142 × 36.","Step 5: A = 113.112 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_circle","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Area of a Circle"}', 0),
  (321, 86, 'A circle has a diameter of 14 cm. Find its area. Use π = 22/7.', 'text', 1, 'Find the radius first.', '{"why":"The area formula requires the radius, so the diameter must first be divided by 2.","sol":"Step 1: Radius = diameter ÷ 2.\nStep 2: r = 14 ÷ 2 = 7 cm.\nStep 3: A = πr².\nStep 4: A = 22/7 × 7².\nStep 5: A = 22/7 × 49.\nStep 6: A = 154 cm².","steps":["Step 1: Radius = diameter ÷ 2.","Step 2: r = 14 ÷ 2 = 7 cm.","Step 3: A = πr².","Step 4: A = 22/7 × 7².","Step 5: A = 22/7 × 49.","Step 6: A = 154 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_circle","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Area of a Circle"}', 1),
  (322, 86, 'A circle has a radius of 8 m. Find its area using π = 3.142.', 'text', 1, 'Square 8 before multiplying by π.', '{"why":"The radius is squared before multiplying by π.","sol":"Step 1: A = πr².\nStep 2: A = 3.142 × 8².\nStep 3: 8² = 64.\nStep 4: A = 3.142 × 64.\nStep 5: A = 201.088 m².","steps":["Step 1: A = πr².","Step 2: A = 3.142 × 8².","Step 3: 8² = 64.","Step 4: A = 3.142 × 64.","Step 5: A = 201.088 m²."],"options":[],"conceptId":"math_geometry_area_of_a_circle","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Area of a Circle"}', 2),
  (323, 86, 'A learner says that the area of a circle with radius 5 cm is 31.42 cm². Identify the error and calculate the correct area using π = 3.142.', 'text', 1, 'Check whether the radius was squared.', '{"why":"The learner multiplied π by 5 instead of multiplying π by 5².","sol":"Step 1: A = πr².\nStep 2: A = 3.142 × 5².\nStep 3: 5² = 25.\nStep 4: A = 3.142 × 25.\nStep 5: A = 78.55 cm².","steps":["Step 1: A = πr².","Step 2: A = 3.142 × 5².","Step 3: 5² = 25.","Step 4: A = 3.142 × 25.","Step 5: A = 78.55 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_circle","skillId":"math_geometry","subskillId":"math_geometry_q4","subject":"math","chapter":"geometry","topic":"Area of a Circle"}', 3),
  (324, 87, 'A rectangle has length 12 cm and width 5 cm. Find its perimeter.', 'text', 1, 'Use P = 2(l + w).', '{"why":"The formula adds the length and width and doubles their sum to include all four sides.","sol":"Step 1: Write P = 2(l + w).\nStep 2: Substitute: P = 2(12 + 5).\nStep 3: P = 2 × 17 = 34 cm.","steps":["Step 1: Write P = 2(l + w).","Step 2: Substitute: P = 2(12 + 5).","Step 3: P = 2 × 17 = 34 cm."],"options":[],"conceptId":"math_geometry_perimeter_of_a_rectangle","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Perimeter of a Rectangle"}', 0),
  (325, 87, 'A rectangle has perimeter 40 m and length 13 m. Find its width.', 'text', 1, 'Start with 40 = 2(13 + w).', '{"why":"Half the perimeter equals one length plus one width.","sol":"Step 1: 40 = 2(13 + w).\nStep 2: Divide by 2: 20 = 13 + w.\nStep 3: Subtract 13: w = 7 m.","steps":["Step 1: 40 = 2(13 + w).","Step 2: Divide by 2: 20 = 13 + w.","Step 3: Subtract 13: w = 7 m."],"options":[],"conceptId":"math_geometry_perimeter_of_a_rectangle","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Perimeter of a Rectangle"}', 1),
  (326, 87, 'A learner calculates the perimeter of a 7 cm by 4 cm rectangle as 28 cm. Explain the mistake and give the correct perimeter.', 'text', 1, 'Check whether the learner multiplied the dimensions instead of adding all four sides.', '{"why":"Perimeter adds boundary lengths; multiplying length by width calculates area.","sol":"Step 1: Multiplying 7 × 4 gives 28, which is the area in cm².\nStep 2: Perimeter = 2(7 + 4).\nStep 3: Perimeter = 2 × 11 = 22 cm.","steps":["Step 1: Multiplying 7 × 4 gives 28, which is the area in cm².","Step 2: Perimeter = 2(7 + 4).","Step 3: Perimeter = 2 × 11 = 22 cm."],"options":[],"conceptId":"math_geometry_perimeter_of_a_rectangle","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Perimeter of a Rectangle"}', 2),
  (327, 88, 'A square has sides of 11 cm. Find its perimeter.', 'text', 1, 'Multiply one side by 4.', '{"why":"A square has four equal sides.","sol":"Step 1: P = 4s.\nStep 2: P = 4 × 11.\nStep 3: P = 44 cm.","steps":["Step 1: P = 4s.","Step 2: P = 4 × 11.","Step 3: P = 44 cm."],"options":[],"conceptId":"math_geometry_perimeter_of_a_square","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Perimeter of a Square"}', 0),
  (328, 88, 'The perimeter of a square is 52 m. Find the length of one side.', 'text', 1, 'Divide the perimeter by 4.', '{"why":"The total perimeter is shared equally among the four sides.","sol":"Step 1: P = 4s.\nStep 2: 52 = 4s.\nStep 3: s = 52 ÷ 4 = 13 m.","steps":["Step 1: P = 4s.","Step 2: 52 = 4s.","Step 3: s = 52 ÷ 4 = 13 m."],"options":[],"conceptId":"math_geometry_perimeter_of_a_square","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Perimeter of a Square"}', 1),
  (329, 88, 'A learner says a square with side 8 cm has perimeter 64 cm. Identify the error and calculate the correct perimeter.', 'text', 1, 'Compare 4 × side with side × side.', '{"why":"Perimeter uses four times the side length; squaring the side gives area.","sol":"Step 1: The learner calculated 8 × 8 = 64, which is the area in cm².\nStep 2: Perimeter = 4 × 8.\nStep 3: Perimeter = 32 cm.","steps":["Step 1: The learner calculated 8 × 8 = 64, which is the area in cm².","Step 2: Perimeter = 4 × 8.","Step 3: Perimeter = 32 cm."],"options":[],"conceptId":"math_geometry_perimeter_of_a_square","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Perimeter of a Square"}', 2),
  (330, 89, 'A triangle has sides 6 cm, 8 cm and 11 cm. Find its perimeter.', 'text', 1, 'Add all three side lengths.', '{"why":"The perimeter is the total distance around the triangle.","sol":"Step 1: P = 6 + 8 + 11.\nStep 2: P = 25 cm.","steps":["Step 1: P = 6 + 8 + 11.","Step 2: P = 25 cm."],"options":[],"conceptId":"math_geometry_perimeter_of_a_triangle","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Perimeter of a Triangle"}', 0),
  (331, 89, 'A triangle has perimeter 31 cm. Two sides measure 9 cm and 13 cm. Find the third side.', 'text', 1, 'Subtract the two known sides from the perimeter.', '{"why":"The missing side is the total perimeter minus the two known sides.","sol":"Step 1: Let the missing side be x.\nStep 2: 9 + 13 + x = 31.\nStep 3: 22 + x = 31.\nStep 4: x = 9 cm.","steps":["Step 1: Let the missing side be x.","Step 2: 9 + 13 + x = 31.","Step 3: 22 + x = 31.","Step 4: x = 9 cm."],"options":[],"conceptId":"math_geometry_perimeter_of_a_triangle","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Perimeter of a Triangle"}', 1),
  (332, 89, 'An equilateral triangle has perimeter 57 cm. A learner says each side is 19 cm². Correct the answer and explain the unit.', 'text', 1, 'Divide by 3, and remember that side length is a distance.', '{"why":"Dividing the perimeter by three gives one side, which is a length.","sol":"Step 1: All three sides are equal.\nStep 2: Side length = 57 ÷ 3 = 19.\nStep 3: The correct side length is 19 cm, not 19 cm².\nStep 4: Centimetres measure length; square centimetres measure area.","steps":["Step 1: All three sides are equal.","Step 2: Side length = 57 ÷ 3 = 19.","Step 3: The correct side length is 19 cm, not 19 cm².","Step 4: Centimetres measure length; square centimetres measure area."],"options":[],"conceptId":"math_geometry_perimeter_of_a_triangle","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Perimeter of a Triangle"}', 2),
  (333, 90, 'A rectangle is 13 m long and 4 m wide. Find its area.', 'text', 1, 'Multiply length by width.', '{"why":"The rectangle''s surface is measured by multiplying its length by its width.","sol":"Step 1: A = l × w.\nStep 2: A = 13 × 4.\nStep 3: A = 52 m².","steps":["Step 1: A = l × w.","Step 2: A = 13 × 4.","Step 3: A = 52 m²."],"options":[],"conceptId":"math_geometry_area_of_a_rectangle","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Area of a Rectangle"}', 0),
  (334, 90, 'A rectangle has area 96 cm² and width 8 cm. Find its length.', 'text', 1, 'Divide the area by the width.', '{"why":"Dividing area by one dimension gives the other dimension.","sol":"Step 1: A = l × w.\nStep 2: 96 = l × 8.\nStep 3: l = 96 ÷ 8.\nStep 4: l = 12 cm.","steps":["Step 1: A = l × w.","Step 2: 96 = l × 8.","Step 3: l = 96 ÷ 8.","Step 4: l = 12 cm."],"options":[],"conceptId":"math_geometry_area_of_a_rectangle","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Area of a Rectangle"}', 1),
  (335, 90, 'A learner finds the area of a rectangle measuring 10 cm by 6 cm as 32 cm². Identify the likely mistake and calculate the correct area.', 'text', 1, 'Check whether the learner added the dimensions.', '{"why":"The area formula is length multiplied by width, not their sum.","sol":"Step 1: Adding the dimensions gives 10 + 6 = 16, not 32.\nStep 2: Area must be calculated by multiplication.\nStep 3: A = 10 × 6.\nStep 4: A = 60 cm².","steps":["Step 1: Adding the dimensions gives 10 + 6 = 16, not 32.","Step 2: Area must be calculated by multiplication.","Step 3: A = 10 × 6.","Step 4: A = 60 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_rectangle","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Area of a Rectangle"}', 2),
  (336, 91, 'A square has side length 12 cm. Find its area.', 'text', 1, 'Multiply 12 by 12.', '{"why":"The area of a square is its side length multiplied by itself.","sol":"Step 1: A = s².\nStep 2: A = 12 × 12.\nStep 3: A = 144 cm².","steps":["Step 1: A = s².","Step 2: A = 12 × 12.","Step 3: A = 144 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_square","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Area of a Square"}', 0),
  (337, 91, 'A square has area 121 cm². Find its side length.', 'text', 1, 'Find the positive square root of 121.', '{"why":"The side length is the positive number whose square equals the area.","sol":"Step 1: A = s².\nStep 2: 121 = s².\nStep 3: s = √121 = 11 cm.","steps":["Step 1: A = s².","Step 2: 121 = s².","Step 3: s = √121 = 11 cm."],"options":[],"conceptId":"math_geometry_area_of_a_square","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Area of a Square"}', 1),
  (338, 91, 'A learner says a square with side 9 m has area 36 m² because 4 × 9 = 36. Explain the error and calculate the correct area.', 'text', 1, 'The learner used the perimeter calculation instead of the area formula.', '{"why":"Area squares the side length; multiplying by four calculates the perimeter.","sol":"Step 1: 4 × 9 calculates the perimeter, which is 36 m.\nStep 2: Area = side × side.\nStep 3: Area = 9 × 9 = 81 m².","steps":["Step 1: 4 × 9 calculates the perimeter, which is 36 m.","Step 2: Area = side × side.","Step 3: Area = 9 × 9 = 81 m²."],"options":[],"conceptId":"math_geometry_area_of_a_square","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Area of a Square"}', 2),
  (339, 92, 'A triangle has base 14 cm and perpendicular height 8 cm. Find its area.', 'text', 1, 'Multiply 14 by 8, then divide by 2.', '{"why":"The triangle occupies half the area of a rectangle with the same base and perpendicular height.","sol":"Step 1: A = ½ × b × h.\nStep 2: A = ½ × 14 × 8.\nStep 3: A = ½ × 112 = 56 cm².","steps":["Step 1: A = ½ × b × h.","Step 2: A = ½ × 14 × 8.","Step 3: A = ½ × 112 = 56 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_triangle","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Area of a Triangle"}', 0),
  (340, 92, 'A triangle has area 54 m² and base 12 m. Find its perpendicular height.', 'text', 1, 'Start with 54 = ½ × 12 × h.', '{"why":"Rearranging the area formula gives height = 2 × area ÷ base.","sol":"Step 1: 54 = ½ × 12 × h.\nStep 2: Simplify: 54 = 6h.\nStep 3: Divide by 6: h = 9 m.","steps":["Step 1: 54 = ½ × 12 × h.","Step 2: Simplify: 54 = 6h.","Step 3: Divide by 6: h = 9 m."],"options":[],"conceptId":"math_geometry_area_of_a_triangle","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Area of a Triangle"}', 1),
  (341, 92, 'A learner calculates the area of a triangle with base 9 cm and perpendicular height 4 cm as 36 cm². Identify the error and calculate the correct area.', 'text', 1, 'The learner multiplied base by height but forgot to take half.', '{"why":"The area formula includes the factor ½.","sol":"Step 1: Multiply base by height: 9 × 4 = 36.\nStep 2: Take half: 36 ÷ 2 = 18.\nStep 3: The correct area is 18 cm².","steps":["Step 1: Multiply base by height: 9 × 4 = 36.","Step 2: Take half: 36 ÷ 2 = 18.","Step 3: The correct area is 18 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_triangle","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Area of a Triangle"}', 2),
  (342, 93, 'A parallelogram has a base of 15 cm and a perpendicular height of 6 cm. Find its area.', 'text', 1, 'Use A = base × perpendicular height.', '{"why":"The area of a parallelogram is found by multiplying its base by its perpendicular height.","sol":"Step 1: A = b × h.\nStep 2: A = 15 × 6.\nStep 3: A = 90 cm².","steps":["Step 1: A = b × h.","Step 2: A = 15 × 6.","Step 3: A = 90 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_parallelogram","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Area of a Parallelogram"}', 0),
  (343, 93, 'A parallelogram has an area of 72 m² and a base of 9 m. Find its perpendicular height.', 'text', 1, 'Start with 72 = 9 × h.', '{"why":"When the area and base are known, divide the area by the base to find the perpendicular height.","sol":"Step 1: A = b × h.\nStep 2: 72 = 9 × h.\nStep 3: h = 72 ÷ 9.\nStep 4: h = 8 m.","steps":["Step 1: A = b × h.","Step 2: 72 = 9 × h.","Step 3: h = 72 ÷ 9.","Step 4: h = 8 m."],"options":[],"conceptId":"math_geometry_area_of_a_parallelogram","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Area of a Parallelogram"}', 1),
  (344, 93, 'A parallelogram has an area of 120 cm² and a perpendicular height of 8 cm. Find its base.', 'text', 1, 'Start with 120 = b × 8.', '{"why":"When the area and perpendicular height are known, divide the area by the height to find the base.","sol":"Step 1: A = b × h.\nStep 2: 120 = b × 8.\nStep 3: b = 120 ÷ 8.\nStep 4: b = 15 cm.","steps":["Step 1: A = b × h.","Step 2: 120 = b × 8.","Step 3: b = 120 ÷ 8.","Step 4: b = 15 cm."],"options":[],"conceptId":"math_geometry_area_of_a_parallelogram","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Area of a Parallelogram"}', 2),
  (345, 93, 'A learner uses the sloping side of a parallelogram as its height. Explain why this can give the wrong area.', 'text', 1, 'Think about what the word perpendicular means.', '{"why":"The formula A = base × height requires the perpendicular height, not simply any side length.","sol":"Step 1: The height must meet the base at 90°.\nStep 2: A sloping side may not meet the base at 90°.\nStep 3: Therefore, the sloping side cannot automatically be used as the height.\nStep 4: The perpendicular height must be used.","steps":["Step 1: The height must meet the base at 90°.","Step 2: A sloping side may not meet the base at 90°.","Step 3: Therefore, the sloping side cannot automatically be used as the height.","Step 4: The perpendicular height must be used."],"options":[],"conceptId":"math_geometry_area_of_a_parallelogram","skillId":"math_geometry","subskillId":"math_geometry_q4","subject":"math","chapter":"geometry","topic":"Area of a Parallelogram"}', 3),
  (346, 94, 'A trapezium has parallel sides of 7 cm and 13 cm and a perpendicular height of 6 cm. Find its area.', 'text', 1, 'Add the two parallel sides first, then multiply by half the height.', '{"why":"The area is half the sum of the two parallel sides multiplied by the perpendicular height.","sol":"Step 1: A = ½ × (a + b) × h.\nStep 2: A = ½ × (7 + 13) × 6.\nStep 3: A = ½ × 20 × 6.\nStep 4: A = 10 × 6.\nStep 5: A = 60 cm².","steps":["Step 1: A = ½ × (a + b) × h.","Step 2: A = ½ × (7 + 13) × 6.","Step 3: A = ½ × 20 × 6.","Step 4: A = 10 × 6.","Step 5: A = 60 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_trapezium","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Area of a Trapezium"}', 0),
  (347, 94, 'A trapezium has parallel sides of 12 m and 18 m and an area of 150 m². Find its perpendicular height.', 'text', 1, 'Substitute into 150 = ½ × (12 + 18) × h.', '{"why":"After adding the parallel sides and taking half, divide the area by that value to find the height.","sol":"Step 1: 150 = ½ × (12 + 18) × h.\nStep 2: 150 = ½ × 30 × h.\nStep 3: 150 = 15h.\nStep 4: h = 150 ÷ 15.\nStep 5: h = 10 m.","steps":["Step 1: 150 = ½ × (12 + 18) × h.","Step 2: 150 = ½ × 30 × h.","Step 3: 150 = 15h.","Step 4: h = 150 ÷ 15.","Step 5: h = 10 m."],"options":[],"conceptId":"math_geometry_area_of_a_trapezium","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Area of a Trapezium"}', 1),
  (348, 94, 'A trapezium has parallel sides of 9 cm and 15 cm and a perpendicular height of 8 cm. A learner calculates its area as 192 cm². Identify the error and find the correct area.', 'text', 1, 'Check whether the learner added the parallel sides and then multiplied by the height without taking half.', '{"why":"The learner forgot the factor ½. Without taking half, the result is twice the correct area.","sol":"Step 1: A = ½ × (9 + 15) × 8.\nStep 2: A = ½ × 24 × 8.\nStep 3: A = 12 × 8.\nStep 4: A = 96 cm².","steps":["Step 1: A = ½ × (9 + 15) × 8.","Step 2: A = ½ × 24 × 8.","Step 3: A = 12 × 8.","Step 4: A = 96 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_trapezium","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Area of a Trapezium"}', 2),
  (349, 94, 'A trapezium has parallel sides of 10 cm and 20 cm and a perpendicular height of 7 cm. Find its area.', 'text', 1, 'Use A = ½ × (a + b) × h.', '{"why":"The average of the parallel sides is 15 cm, and 15 × 7 gives the area.","sol":"Step 1: A = ½ × (10 + 20) × 7.\nStep 2: A = ½ × 30 × 7.\nStep 3: A = 15 × 7.\nStep 4: A = 105 cm².","steps":["Step 1: A = ½ × (10 + 20) × 7.","Step 2: A = ½ × 30 × 7.","Step 3: A = 15 × 7.","Step 4: A = 105 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_trapezium","skillId":"math_geometry","subskillId":"math_geometry_q4","subject":"math","chapter":"geometry","topic":"Area of a Trapezium"}', 3),
  (350, 95, 'Find the sum of the interior angles of an octagon.', 'text', 1, 'An octagon has 8 sides. Use (n − 2) × 180°.', '{"why":"An octagon can be divided into 6 triangles, and each triangle has an angle sum of 180°.","sol":"Step 1: n = 8.\nStep 2: Sum = (8 − 2) × 180°.\nStep 3: Sum = 6 × 180°.\nStep 4: Sum = 1080°.","steps":["Step 1: n = 8.","Step 2: Sum = (8 − 2) × 180°.","Step 3: Sum = 6 × 180°.","Step 4: Sum = 1080°."],"options":[],"conceptId":"math_geometry_interior_angle_sum_of_polygons","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Interior Angle Sum of Polygons"}', 0),
  (351, 95, 'A polygon has 10 sides. Find the sum of its interior angles.', 'text', 1, 'Substitute n = 10 into (n − 2) × 180°.', '{"why":"A 10-sided polygon can be divided into 8 triangles.","sol":"Step 1: n = 10.\nStep 2: Sum = (10 − 2) × 180°.\nStep 3: Sum = 8 × 180°.\nStep 4: Sum = 1440°.","steps":["Step 1: n = 10.","Step 2: Sum = (10 − 2) × 180°.","Step 3: Sum = 8 × 180°.","Step 4: Sum = 1440°."],"options":[],"conceptId":"math_geometry_interior_angle_sum_of_polygons","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Interior Angle Sum of Polygons"}', 1),
  (352, 95, 'A polygon has an interior angle sum of 1260°. How many sides does it have?', 'text', 1, 'Start with 1260 = (n − 2) × 180.', '{"why":"A polygon with 9 sides has 7 triangles, giving an interior angle sum of 7 × 180° = 1260°.","sol":"Step 1: 1260 = (n − 2) × 180.\nStep 2: 1260 ÷ 180 = n − 2.\nStep 3: 7 = n − 2.\nStep 4: n = 9.","steps":["Step 1: 1260 = (n − 2) × 180.","Step 2: 1260 ÷ 180 = n − 2.","Step 3: 7 = n − 2.","Step 4: n = 9."],"options":[],"conceptId":"math_geometry_interior_angle_sum_of_polygons","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Interior Angle Sum of Polygons"}', 2),
  (353, 95, 'A learner says that the interior angle sum of a hexagon is 1080°. Identify the error and find the correct answer.', 'text', 1, 'Check the number of triangles formed using n − 2.', '{"why":"The learner did not use the correct number of triangles. A hexagon forms 4 triangles, not 6.","sol":"Step 1: A hexagon has 6 sides.\nStep 2: Number of triangles = 6 − 2 = 4.\nStep 3: Interior angle sum = 4 × 180°.\nStep 4: Interior angle sum = 720°.","steps":["Step 1: A hexagon has 6 sides.","Step 2: Number of triangles = 6 − 2 = 4.","Step 3: Interior angle sum = 4 × 180°.","Step 4: Interior angle sum = 720°."],"options":[],"conceptId":"math_geometry_interior_angle_sum_of_polygons","skillId":"math_geometry","subskillId":"math_geometry_q4","subject":"math","chapter":"geometry","topic":"Interior Angle Sum of Polygons"}', 3),
  (354, 96, 'The exterior angles of a polygon are 90°, 80°, 70° and 60°. Find the fifth exterior angle.', 'text', 1, 'All exterior angles together add to 360°.', '{"why":"The exterior angles of a polygon make one complete turn, which is 360°.","sol":"Step 1: Total exterior angle sum = 360°.\nStep 2: 90° + 80° + 70° + 60° = 300°.\nStep 3: Missing angle = 360° − 300°.\nStep 4: Missing angle = 60°.","steps":["Step 1: Total exterior angle sum = 360°.","Step 2: 90° + 80° + 70° + 60° = 300°.","Step 3: Missing angle = 360° − 300°.","Step 4: Missing angle = 60°."],"options":[],"conceptId":"math_geometry_exterior_angles_of_a_polygon","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Exterior Angles of a Polygon"}', 0),
  (355, 96, 'Find each exterior angle of a regular pentagon.', 'text', 1, 'Divide 360° by the number of sides.', '{"why":"A regular polygon has equal exterior angles, and together they total 360°.","sol":"Step 1: A pentagon has 5 sides.\nStep 2: Each exterior angle = 360° ÷ 5.\nStep 3: Each exterior angle = 72°.","steps":["Step 1: A pentagon has 5 sides.","Step 2: Each exterior angle = 360° ÷ 5.","Step 3: Each exterior angle = 72°."],"options":[],"conceptId":"math_geometry_exterior_angles_of_a_polygon","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Exterior Angles of a Polygon"}', 1),
  (356, 96, 'Each exterior angle of a regular polygon is 30°. How many sides does the polygon have?', 'text', 1, 'Use n = 360° ÷ exterior angle.', '{"why":"There are 360° in one complete turn, so 30° exterior angles require 12 equal turns.","sol":"Step 1: n = 360° ÷ 30°.\nStep 2: n = 12.","steps":["Step 1: n = 360° ÷ 30°.","Step 2: n = 12."],"options":[],"conceptId":"math_geometry_exterior_angles_of_a_polygon","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Exterior Angles of a Polygon"}', 2),
  (357, 96, 'A regular polygon has an interior angle of 135°. Find each exterior angle.', 'text', 1, 'Interior angle + exterior angle = 180°.', '{"why":"The interior and exterior angles at the same vertex form a straight line.","sol":"Step 1: Interior angle + exterior angle = 180°.\nStep 2: 135° + exterior angle = 180°.\nStep 3: Exterior angle = 180° − 135°.\nStep 4: Exterior angle = 45°.","steps":["Step 1: Interior angle + exterior angle = 180°.","Step 2: 135° + exterior angle = 180°.","Step 3: Exterior angle = 180° − 135°.","Step 4: Exterior angle = 45°."],"options":[],"conceptId":"math_geometry_exterior_angles_of_a_polygon","skillId":"math_geometry","subskillId":"math_geometry_q4","subject":"math","chapter":"geometry","topic":"Exterior Angles of a Polygon"}', 3),
  (358, 96, 'A learner says that each exterior angle of a regular hexagon is 30°. Identify the error and find the correct angle.', 'text', 1, 'A hexagon has 6 equal exterior angles whose total is 360°.', '{"why":"The sum of the exterior angles is 360°, not 180°.","sol":"Step 1: A hexagon has 6 sides.\nStep 2: Each exterior angle = 360° ÷ 6.\nStep 3: Each exterior angle = 60°.\nStep 4: The learner used 180° ÷ 6 instead of 360° ÷ 6.","steps":["Step 1: A hexagon has 6 sides.","Step 2: Each exterior angle = 360° ÷ 6.","Step 3: Each exterior angle = 60°.","Step 4: The learner used 180° ÷ 6 instead of 360° ÷ 6."],"options":[],"conceptId":"math_geometry_exterior_angles_of_a_polygon","skillId":"math_geometry","subskillId":"math_geometry_q5","subject":"math","chapter":"geometry","topic":"Exterior Angles of a Polygon"}', 4),
  (359, 97, 'A farmer must choose how much land to use for maize and beans while trying to obtain the greatest profit. What mathematical method can be used?', 'text', 1, 'Think about choosing quantities while working under a restriction.', '{"why":"Linear programming is used to find the best choice while satisfying restrictions.","sol":"Step 1: The farmer must choose quantities for two crops.\nStep 2: The available land is limited.\nStep 3: There is a goal of obtaining the greatest profit.\nStep 4: Therefore, this is a linear programming situation.","steps":["Step 1: The farmer must choose quantities for two crops.","Step 2: The available land is limited.","Step 3: There is a goal of obtaining the greatest profit.","Step 4: Therefore, this is a linear programming situation."],"options":[],"conceptId":"math_linear_programming_meaning_of_linear_programming","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Meaning of Linear Programming"}', 0),
  (360, 97, 'A business has limited money and must choose how many of two products to buy. What makes this a linear programming situation?', 'text', 1, 'Identify the choice, restriction and goal.', '{"why":"These are the basic ingredients of a linear programming problem.","sol":"Step 1: The business chooses quantities of the products.\nStep 2: The money available is limited.\nStep 3: The business wants the best possible choice.\nStep 4: Therefore, the situation can be handled using linear programming.","steps":["Step 1: The business chooses quantities of the products.","Step 2: The money available is limited.","Step 3: The business wants the best possible choice.","Step 4: Therefore, the situation can be handled using linear programming."],"options":[],"conceptId":"math_linear_programming_meaning_of_linear_programming","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Meaning of Linear Programming"}', 1),
  (361, 97, 'Does linear programming require the use of a computer?', 'text', 1, 'Look at what the word programming means in this topic.', '{"why":"Linear programming is a mathematical optimisation method, not computer programming.","sol":"Step 1: The word programming in linear programming means planning.\nStep 2: It does not refer to writing computer code.\nStep 3: Therefore, a computer is not required to define the method.","steps":["Step 1: The word programming in linear programming means planning.","Step 2: It does not refer to writing computer code.","Step 3: Therefore, a computer is not required to define the method."],"options":[],"conceptId":"math_linear_programming_meaning_of_linear_programming","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Meaning of Linear Programming"}', 2),
  (362, 98, 'A farmer grows maize and beans. Let x represent hectares of maize and y represent hectares of beans. Which are the decision variables?', 'text', 1, 'Look for the quantities whose values must be decided.', '{"why":"Decision variables represent the quantities that must be chosen.","sol":"Step 1: x represents hectares of maize.\nStep 2: y represents hectares of beans.\nStep 3: Both quantities must be decided.\nStep 4: Therefore, x and y are the decision variables.","steps":["Step 1: x represents hectares of maize.","Step 2: y represents hectares of beans.","Step 3: Both quantities must be decided.","Step 4: Therefore, x and y are the decision variables."],"options":[],"conceptId":"math_linear_programming_decision_variables","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Decision Variables"}', 0),
  (363, 98, 'A shop sells shoes and shirts. Choose suitable decision variables.', 'text', 1, 'Use x and y to represent the two quantities.', '{"why":"The variables must clearly identify the quantities being decided.","sol":"Step 1: Let x represent the number of shoes.\nStep 2: Let y represent the number of shirts.\nStep 3: These are the quantities the shop must decide.","steps":["Step 1: Let x represent the number of shoes.","Step 2: Let y represent the number of shirts.","Step 3: These are the quantities the shop must decide."],"options":[],"conceptId":"math_linear_programming_decision_variables","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Decision Variables"}', 1),
  (364, 98, 'Why should we state what x represents before solving a linear programming problem?', 'text', 1, 'Think about what x = 20 would mean without a definition.', '{"why":"A numerical answer is useful only when we know what quantity it represents.","sol":"Step 1: The letter x alone has no specific meaning.\nStep 2: We need to know what quantity x represents.\nStep 3: This allows us to interpret the final answer correctly.","steps":["Step 1: The letter x alone has no specific meaning.","Step 2: We need to know what quantity x represents.","Step 3: This allows us to interpret the final answer correctly."],"options":[],"conceptId":"math_linear_programming_decision_variables","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Decision Variables"}', 2),
  (365, 99, 'A farmer has at most 15 hectares for two crops. If x and y are the hectares used for the two crops, write the land constraint.', 'text', 1, 'At most means the total cannot exceed 15.', '{"why":"The inequality represents the limited amount of land.","sol":"Step 1: The total land used is x + y.\nStep 2: The available land is 15 hectares.\nStep 3: The total cannot be greater than 15.\nStep 4: Therefore, x + y ≤ 15.","steps":["Step 1: The total land used is x + y.","Step 2: The available land is 15 hectares.","Step 3: The total cannot be greater than 15.","Step 4: Therefore, x + y ≤ 15."],"options":[],"conceptId":"math_linear_programming_understanding_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Understanding Constraints"}', 0),
  (366, 99, 'A factory can make at most 80 products of two types in one day. If x and y are the quantities, write the constraint.', 'text', 1, 'At most 80 means not more than 80.', '{"why":"The total number of products cannot be greater than 80.","sol":"Step 1: Total production is x + y.\nStep 2: Production cannot exceed 80.\nStep 3: Therefore, x + y ≤ 80.","steps":["Step 1: Total production is x + y.","Step 2: Production cannot exceed 80.","Step 3: Therefore, x + y ≤ 80."],"options":[],"conceptId":"math_linear_programming_understanding_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Understanding Constraints"}', 1),
  (367, 99, 'In a constraint, what does the restriction actually do?', 'text', 1, 'Think about allowed and forbidden choices.', '{"why":"Constraints describe the conditions that every acceptable solution must satisfy.","sol":"Step 1: Without a constraint, many values might be possible.\nStep 2: The constraint removes values that violate the condition.\nStep 3: The remaining values are the allowed choices.","steps":["Step 1: Without a constraint, many values might be possible.","Step 2: The constraint removes values that violate the condition.","Step 3: The remaining values are the allowed choices."],"options":[],"conceptId":"math_linear_programming_understanding_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Understanding Constraints"}', 2),
  (368, 100, 'A farmer has at most 40 hectares for two crops. If x and y are the hectares used, write the constraint.', 'text', 1, 'At most means not greater than.', '{"why":"At most 40 means the total is less than or equal to 40.","sol":"Step 1: The total land is x + y.\nStep 2: The maximum available is 40 hectares.\nStep 3: Therefore the total cannot exceed 40.\nStep 4: So x + y ≤ 40.","steps":["Step 1: The total land is x + y.","Step 2: The maximum available is 40 hectares.","Step 3: Therefore the total cannot exceed 40.","Step 4: So x + y ≤ 40."],"options":[],"conceptId":"math_linear_programming_writing_a_constraint_from_a_statement","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Writing a Constraint from a Statement"}', 0),
  (369, 100, 'A school must have at least 300 learners in two programmes. If x and y are the numbers of learners, write the constraint.', 'text', 1, 'At least means not below.', '{"why":"At least 300 means the total must be greater than or equal to 300.","sol":"Step 1: The total number of learners is x + y.\nStep 2: The minimum required is 300.\nStep 3: Therefore the total must be 300 or more.\nStep 4: So x + y ≥ 300.","steps":["Step 1: The total number of learners is x + y.","Step 2: The minimum required is 300.","Step 3: Therefore the total must be 300 or more.","Step 4: So x + y ≥ 300."],"options":[],"conceptId":"math_linear_programming_writing_a_constraint_from_a_statement","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Writing a Constraint from a Statement"}', 1),
  (370, 100, 'A factory has no more than 120 kg of material. If x and y are the amounts used for two products, write the constraint.', 'text', 1, 'No more than means the same idea as at most.', '{"why":"No more than means less than or equal to.","sol":"Step 1: Total material used is x + y.\nStep 2: The available amount is 120 kg.\nStep 3: The amount used cannot exceed 120 kg.\nStep 4: Therefore x + y ≤ 120.","steps":["Step 1: Total material used is x + y.","Step 2: The available amount is 120 kg.","Step 3: The amount used cannot exceed 120 kg.","Step 4: Therefore x + y ≤ 120."],"options":[],"conceptId":"math_linear_programming_writing_a_constraint_from_a_statement","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Writing a Constraint from a Statement"}', 2),
  (371, 101, 'Does x = 6 satisfy x ≤ 10?', 'text', 1, 'Compare 6 with 10.', '{"why":"6 is less than 10.","sol":"Step 1: Substitute x = 6.\nStep 2: We get 6 ≤ 10.\nStep 3: This statement is true.\nStep 4: Therefore x = 6 satisfies the inequality.","steps":["Step 1: Substitute x = 6.","Step 2: We get 6 ≤ 10.","Step 3: This statement is true.","Step 4: Therefore x = 6 satisfies the inequality."],"options":[],"conceptId":"math_linear_programming_meaning_of_less_than_or_equal_to","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Meaning of Less Than or Equal To"}', 0),
  (372, 101, 'Does x = 10 satisfy x ≤ 10?', 'text', 1, 'Remember that ≤ includes equality.', '{"why":"The symbol ≤ allows the value to equal 10.","sol":"Step 1: Substitute x = 10.\nStep 2: We get 10 ≤ 10.\nStep 3: Equality is allowed by ≤.\nStep 4: Therefore x = 10 satisfies the inequality.","steps":["Step 1: Substitute x = 10.","Step 2: We get 10 ≤ 10.","Step 3: Equality is allowed by ≤.","Step 4: Therefore x = 10 satisfies the inequality."],"options":[],"conceptId":"math_linear_programming_meaning_of_less_than_or_equal_to","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Meaning of Less Than or Equal To"}', 1),
  (373, 101, 'Does x = 11 satisfy x ≤ 10?', 'text', 1, 'Is 11 less than or equal to 10?', '{"why":"11 is greater than 10.","sol":"Step 1: Substitute x = 11.\nStep 2: We get 11 ≤ 10.\nStep 3: This is false.\nStep 4: Therefore x = 11 does not satisfy the inequality.","steps":["Step 1: Substitute x = 11.","Step 2: We get 11 ≤ 10.","Step 3: This is false.","Step 4: Therefore x = 11 does not satisfy the inequality."],"options":[],"conceptId":"math_linear_programming_meaning_of_less_than_or_equal_to","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Meaning of Less Than or Equal To"}', 2),
  (374, 102, 'Does x = 30 satisfy x ≥ 20?', 'text', 1, 'Is 30 greater than or equal to 20?', '{"why":"30 is greater than 20.","sol":"Step 1: Substitute x = 30.\nStep 2: We get 30 ≥ 20.\nStep 3: This is true.\nStep 4: Therefore x = 30 satisfies the inequality.","steps":["Step 1: Substitute x = 30.","Step 2: We get 30 ≥ 20.","Step 3: This is true.","Step 4: Therefore x = 30 satisfies the inequality."],"options":[],"conceptId":"math_linear_programming_meaning_of_greater_than_or_equal_to","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Meaning of Greater Than or Equal To"}', 0),
  (375, 102, 'Does x = 20 satisfy x ≥ 20?', 'text', 1, 'Does ≥ include equality?', '{"why":"The symbol ≥ includes equality.","sol":"Step 1: Substitute x = 20.\nStep 2: We get 20 ≥ 20.\nStep 3: Equality is allowed.\nStep 4: Therefore x = 20 satisfies the inequality.","steps":["Step 1: Substitute x = 20.","Step 2: We get 20 ≥ 20.","Step 3: Equality is allowed.","Step 4: Therefore x = 20 satisfies the inequality."],"options":[],"conceptId":"math_linear_programming_meaning_of_greater_than_or_equal_to","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Meaning of Greater Than or Equal To"}', 1),
  (376, 102, 'Does x = 18 satisfy x ≥ 20?', 'text', 1, 'Compare 18 and 20.', '{"why":"18 is less than 20.","sol":"Step 1: Substitute x = 18.\nStep 2: We get 18 ≥ 20.\nStep 3: This is false.\nStep 4: Therefore x = 18 does not satisfy the inequality.","steps":["Step 1: Substitute x = 18.","Step 2: We get 18 ≥ 20.","Step 3: This is false.","Step 4: Therefore x = 18 does not satisfy the inequality."],"options":[],"conceptId":"math_linear_programming_meaning_of_greater_than_or_equal_to","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Meaning of Greater Than or Equal To"}', 2),
  (377, 103, 'If x represents the number of desks produced, write its non-negativity constraint.', 'text', 1, 'The number of desks cannot be negative.', '{"why":"The quantity represented by x cannot be negative.","sol":"Step 1: x represents a quantity.\nStep 2: A quantity of desks cannot be below zero.\nStep 3: Therefore x must be at least zero.","steps":["Step 1: x represents a quantity.","Step 2: A quantity of desks cannot be below zero.","Step 3: Therefore x must be at least zero."],"options":[],"conceptId":"math_linear_programming_non_negativity_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Non-Negativity Constraints"}', 0),
  (378, 103, 'If y represents kilograms of flour used, can y = -5 satisfy the non-negativity constraint?', 'text', 1, 'Check whether -5 is greater than or equal to zero.', '{"why":"A negative quantity does not satisfy the non-negativity constraint.","sol":"Step 1: The constraint is y ≥ 0.\nStep 2: Substitute y = -5.\nStep 3: We get -5 ≥ 0.\nStep 4: This is false.","steps":["Step 1: The constraint is y ≥ 0.","Step 2: Substitute y = -5.","Step 3: We get -5 ≥ 0.","Step 4: This is false."],"options":[],"conceptId":"math_linear_programming_non_negativity_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Non-Negativity Constraints"}', 1),
  (379, 103, 'Does x = 0 satisfy x ≥ 0?', 'text', 1, 'The symbol ≥ includes equality.', '{"why":"Non-negativity allows zero.","sol":"Step 1: Substitute x = 0.\nStep 2: We get 0 ≥ 0.\nStep 3: Equality is allowed.\nStep 4: Therefore x = 0 is allowed.","steps":["Step 1: Substitute x = 0.","Step 2: We get 0 ≥ 0.","Step 3: Equality is allowed.","Step 4: Therefore x = 0 is allowed."],"options":[],"conceptId":"math_linear_programming_non_negativity_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Non-Negativity Constraints"}', 2),
  (380, 104, 'A farmer has at most 25 hectares for two crops. What is the constraint if x and y are the hectares used?', 'text', 1, 'Identify the condition that limits the total land.', '{"why":"The 25 hectares limit the total amount of land that can be used.","sol":"Step 1: The total land used is x + y.\nStep 2: The farmer has at most 25 hectares.\nStep 3: The total cannot exceed 25.\nStep 4: Therefore x + y ≤ 25.","steps":["Step 1: The total land used is x + y.","Step 2: The farmer has at most 25 hectares.","Step 3: The total cannot exceed 25.","Step 4: Therefore x + y ≤ 25."],"options":[],"conceptId":"math_linear_programming_identifying_constraints_in_a_word_problem","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Identifying Constraints in a Word Problem"}', 0),
  (381, 104, 'A factory has no more than 90 hours available. If x and y are hours used for two activities, write the constraint.', 'text', 1, 'No more than means the total cannot exceed the available amount.', '{"why":"The available time places a maximum on the total time used.","sol":"Step 1: Total time used is x + y.\nStep 2: The maximum available time is 90 hours.\nStep 3: Therefore x + y ≤ 90.","steps":["Step 1: Total time used is x + y.","Step 2: The maximum available time is 90 hours.","Step 3: Therefore x + y ≤ 90."],"options":[],"conceptId":"math_linear_programming_identifying_constraints_in_a_word_problem","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Identifying Constraints in a Word Problem"}', 1),
  (382, 104, 'A school requires at least 400 learners in two programmes. If x and y are the numbers of learners, write the constraint.', 'text', 1, 'At least means the total must reach or exceed the number.', '{"why":"The school requires a minimum total of 400 learners.","sol":"Step 1: Total learners are x + y.\nStep 2: The minimum required is 400.\nStep 3: Therefore the total must be at least 400.\nStep 4: So x + y ≥ 400.","steps":["Step 1: Total learners are x + y.","Step 2: The minimum required is 400.","Step 3: Therefore the total must be at least 400.","Step 4: So x + y ≥ 400."],"options":[],"conceptId":"math_linear_programming_identifying_constraints_in_a_word_problem","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Identifying Constraints in a Word Problem"}', 2),
  (383, 105, 'A farmer has at most 30 hectares. Is x + y ≥ 30 the correct constraint?', 'text', 1, 'Try a value greater than 30.', '{"why":"At most means the total cannot exceed 30.","sol":"Step 1: At most 30 means values greater than 30 must not be allowed.\nStep 2: But x + y ≥ 30 allows 40, 50, and other larger values.\nStep 3: Therefore it does not represent the condition.\nStep 4: The correct inequality is x + y ≤ 30.","steps":["Step 1: At most 30 means values greater than 30 must not be allowed.","Step 2: But x + y ≥ 30 allows 40, 50, and other larger values.","Step 3: Therefore it does not represent the condition.","Step 4: The correct inequality is x + y ≤ 30."],"options":[],"conceptId":"math_linear_programming_checking_whether_an_inequality_matches_a_condition","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Checking Whether an Inequality Matches a Condition"}', 0),
  (384, 105, 'A school needs at least 200 learners. Is x + y ≥ 200 correct?', 'text', 1, 'Check whether the inequality allows 200 and values above 200.', '{"why":"Greater than or equal to represents at least.","sol":"Step 1: At least 200 means 200 is allowed.\nStep 2: Values greater than 200 must also be allowed.\nStep 3: x + y ≥ 200 allows exactly these values.\nStep 4: Therefore it is correct.","steps":["Step 1: At least 200 means 200 is allowed.","Step 2: Values greater than 200 must also be allowed.","Step 3: x + y ≥ 200 allows exactly these values.","Step 4: Therefore it is correct."],"options":[],"conceptId":"math_linear_programming_checking_whether_an_inequality_matches_a_condition","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Checking Whether an Inequality Matches a Condition"}', 1),
  (385, 105, 'A factory has no more than 70 kg of material. Does x + y ≤ 70 represent this condition?', 'text', 1, 'Check values below, equal to, and above 70.', '{"why":"Less than or equal to represents no more than.","sol":"Step 1: Values below 70 are allowed.\nStep 2: 70 itself is allowed.\nStep 3: Values above 70 are not allowed.\nStep 4: That exactly matches no more than 70.","steps":["Step 1: Values below 70 are allowed.","Step 2: 70 itself is allowed.","Step 3: Values above 70 are not allowed.","Step 4: That exactly matches no more than 70."],"options":[],"conceptId":"math_linear_programming_checking_whether_an_inequality_matches_a_condition","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Checking Whether an Inequality Matches a Condition"}', 2),
  (386, 106, 'A farmer uses x hectares for maize and y hectares for beans. There are at most 50 hectares available. Write the complete basic set of constraints.', 'text', 1, 'Include the land restriction and non-negativity.', '{"why":"All three conditions are required for an acceptable choice.","sol":"Step 1: The total land is x + y.\nStep 2: At most 50 hectares gives x + y ≤ 50.\nStep 3: Land cannot be negative, so x ≥ 0.\nStep 4: Land cannot be negative, so y ≥ 0.","steps":["Step 1: The total land is x + y.","Step 2: At most 50 hectares gives x + y ≤ 50.","Step 3: Land cannot be negative, so x ≥ 0.","Step 4: Land cannot be negative, so y ≥ 0."],"options":[],"conceptId":"math_linear_programming_writing_the_complete_set_of_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Writing the Complete Set of Constraints"}', 0),
  (387, 106, 'A factory produces x units of A and y units of B. It can produce at most 120 units. Write the complete basic constraints.', 'text', 1, 'Do not forget the meaning of the quantities.', '{"why":"The production limit and non-negativity together define the basic restrictions.","sol":"Step 1: Total production is x + y.\nStep 2: At most 120 gives x + y ≤ 120.\nStep 3: Production cannot be negative.\nStep 4: Therefore x ≥ 0 and y ≥ 0.","steps":["Step 1: Total production is x + y.","Step 2: At most 120 gives x + y ≤ 120.","Step 3: Production cannot be negative.","Step 4: Therefore x ≥ 0 and y ≥ 0."],"options":[],"conceptId":"math_linear_programming_writing_the_complete_set_of_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Writing the Complete Set of Constraints"}', 1),
  (388, 106, 'A school requires at least 600 learners in two programmes. Let x and y be the numbers of learners. Write the complete basic set of constraints.', 'text', 1, 'Translate at least first, then add non-negativity.', '{"why":"The complete set must contain the total requirement and the non-negativity restrictions.","sol":"Step 1: The total number of learners is x + y.\nStep 2: At least 600 gives x + y ≥ 600.\nStep 3: Numbers of learners cannot be negative.\nStep 4: Therefore x ≥ 0 and y ≥ 0.","steps":["Step 1: The total number of learners is x + y.","Step 2: At least 600 gives x + y ≥ 600.","Step 3: Numbers of learners cannot be negative.","Step 4: Therefore x ≥ 0 and y ≥ 0."],"options":[],"conceptId":"math_linear_programming_writing_the_complete_set_of_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Writing the Complete Set of Constraints"}', 2),
  (389, 107, 'Find the boundary equation for x + y ≤ 8.', 'text', 1, 'Replace ≤ with =.', '{"why":"The boundary contains the points where the inequality reaches its limit.","sol":"Step 1: Start with x + y ≤ 8.\nStep 2: The boundary occurs at the limit.\nStep 3: Replace ≤ with =.\nStep 4: Therefore x + y = 8.","steps":["Step 1: Start with x + y ≤ 8.","Step 2: The boundary occurs at the limit.","Step 3: Replace ≤ with =.","Step 4: Therefore x + y = 8."],"options":[],"conceptId":"math_linear_programming_turning_an_inequality_into_a_boundary_equation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Turning an Inequality into a Boundary Equation"}', 0),
  (390, 107, 'Find the boundary equation for 2x + 3y ≥ 12.', 'text', 1, 'Only change the inequality symbol to =.', '{"why":"The equality gives the line separating the two regions.","sol":"Step 1: Start with 2x + 3y ≥ 12.\nStep 2: Replace ≥ with =.\nStep 3: Therefore 2x + 3y = 12.","steps":["Step 1: Start with 2x + 3y ≥ 12.","Step 2: Replace ≥ with =.","Step 3: Therefore 2x + 3y = 12."],"options":[],"conceptId":"math_linear_programming_turning_an_inequality_into_a_boundary_equation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Turning an Inequality into a Boundary Equation"}', 1),
  (391, 107, 'What is the boundary equation of 4x + y ≤ 20?', 'text', 1, 'Replace ≤ with =.', '{"why":"The boundary is formed where the inequality becomes an equality.","sol":"Step 1: Start with 4x + y ≤ 20.\nStep 2: Replace ≤ by =.\nStep 3: The boundary is 4x + y = 20.","steps":["Step 1: Start with 4x + y ≤ 20.","Step 2: Replace ≤ by =.","Step 3: The boundary is 4x + y = 20."],"options":[],"conceptId":"math_linear_programming_turning_an_inequality_into_a_boundary_equation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Turning an Inequality into a Boundary Equation"}', 2),
  (392, 108, 'Find the x-intercept of x + y = 7.', 'text', 1, 'Set y = 0.', '{"why":"The x-axis has y = 0.","sol":"Step 1: Set y = 0.\nStep 2: x + 0 = 7.\nStep 3: Therefore x = 7.\nStep 4: The point is (7, 0).","steps":["Step 1: Set y = 0.","Step 2: x + 0 = 7.","Step 3: Therefore x = 7.","Step 4: The point is (7, 0)."],"options":[],"conceptId":"math_linear_programming_finding_the_x_intercept","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Finding the x-Intercept"}', 0),
  (393, 108, 'Find the x-intercept of 2x + y = 10.', 'text', 1, 'Put y = 0.', '{"why":"Setting y = 0 gives the point where the line crosses the x-axis.","sol":"Step 1: Set y = 0.\nStep 2: 2x + 0 = 10.\nStep 3: 2x = 10.\nStep 4: x = 5.\nStep 5: Therefore the point is (5, 0).","steps":["Step 1: Set y = 0.","Step 2: 2x + 0 = 10.","Step 3: 2x = 10.","Step 4: x = 5.","Step 5: Therefore the point is (5, 0)."],"options":[],"conceptId":"math_linear_programming_finding_the_x_intercept","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Finding the x-Intercept"}', 1),
  (394, 108, 'Find the x-intercept of 4x + 2y = 20.', 'text', 1, 'Set y = 0 and solve for x.', '{"why":"The x-intercept always has y-coordinate zero.","sol":"Step 1: Set y = 0.\nStep 2: 4x + 2(0) = 20.\nStep 3: 4x = 20.\nStep 4: x = 5.\nStep 5: Therefore the x-intercept is (5, 0).","steps":["Step 1: Set y = 0.","Step 2: 4x + 2(0) = 20.","Step 3: 4x = 20.","Step 4: x = 5.","Step 5: Therefore the x-intercept is (5, 0)."],"options":[],"conceptId":"math_linear_programming_finding_the_x_intercept","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Finding the x-Intercept"}', 2),
  (395, 109, 'Find the y-intercept of x + y = 8.', 'text', 1, 'Set x = 0.', '{"why":"The y-axis has x = 0.","sol":"Step 1: Set x = 0.\nStep 2: 0 + y = 8.\nStep 3: Therefore y = 8.\nStep 4: The point is (0, 8).","steps":["Step 1: Set x = 0.","Step 2: 0 + y = 8.","Step 3: Therefore y = 8.","Step 4: The point is (0, 8)."],"options":[],"conceptId":"math_linear_programming_finding_the_y_intercept","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Finding the y-Intercept"}', 0),
  (396, 109, 'Find the y-intercept of 2x + y = 14.', 'text', 1, 'Put x = 0.', '{"why":"Setting x = 0 gives the point where the line crosses the y-axis.","sol":"Step 1: Set x = 0.\nStep 2: 2(0) + y = 14.\nStep 3: Therefore y = 14.\nStep 4: The point is (0, 14).","steps":["Step 1: Set x = 0.","Step 2: 2(0) + y = 14.","Step 3: Therefore y = 14.","Step 4: The point is (0, 14)."],"options":[],"conceptId":"math_linear_programming_finding_the_y_intercept","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Finding the y-Intercept"}', 1),
  (397, 109, 'Find the y-intercept of 4x + 2y = 20.', 'text', 1, 'Set x = 0 and solve for y.', '{"why":"The y-intercept always has x-coordinate zero.","sol":"Step 1: Set x = 0.\nStep 2: 4(0) + 2y = 20.\nStep 3: 2y = 20.\nStep 4: y = 10.\nStep 5: Therefore the y-intercept is (0, 10).","steps":["Step 1: Set x = 0.","Step 2: 4(0) + 2y = 20.","Step 3: 2y = 20.","Step 4: y = 10.","Step 5: Therefore the y-intercept is (0, 10)."],"options":[],"conceptId":"math_linear_programming_finding_the_y_intercept","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Finding the y-Intercept"}', 2),
  (398, 110, 'Draw the boundary line x + y = 6. Which two intercepts should you plot?', 'text', 1, 'Find the x-intercept and y-intercept.', '{"why":"These two points lie on the boundary line and are easy to obtain.","sol":"Step 1: For the x-intercept, set y = 0.\nStep 2: Then x = 6, giving (6,0).\nStep 3: For the y-intercept, set x = 0.\nStep 4: Then y = 6, giving (0,6).","steps":["Step 1: For the x-intercept, set y = 0.","Step 2: Then x = 6, giving (6,0).","Step 3: For the y-intercept, set x = 0.","Step 4: Then y = 6, giving (0,6)."],"options":[],"conceptId":"math_linear_programming_drawing_a_boundary_line_from_its_intercepts","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Drawing a Boundary Line from Its Intercepts"}', 0),
  (399, 110, 'Find the two intercepts needed to draw 2x + y = 10.', 'text', 1, 'Set y = 0 for the x-intercept and x = 0 for the y-intercept.', '{"why":"The line is determined by these two intercepts.","sol":"Step 1: Set y = 0: 2x = 10, so x = 5.\nStep 2: The x-intercept is (5,0).\nStep 3: Set x = 0: y = 10.\nStep 4: The y-intercept is (0,10).","steps":["Step 1: Set y = 0: 2x = 10, so x = 5.","Step 2: The x-intercept is (5,0).","Step 3: Set x = 0: y = 10.","Step 4: The y-intercept is (0,10)."],"options":[],"conceptId":"math_linear_programming_drawing_a_boundary_line_from_its_intercepts","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Drawing a Boundary Line from Its Intercepts"}', 1),
  (400, 110, 'Find the two intercepts of 3x + y = 12.', 'text', 1, 'Use y = 0 and then x = 0.', '{"why":"The two intercepts provide the two points needed to draw the boundary.","sol":"Step 1: Set y = 0: 3x = 12, so x = 4.\nStep 2: The x-intercept is (4,0).\nStep 3: Set x = 0: y = 12.\nStep 4: The y-intercept is (0,12).","steps":["Step 1: Set y = 0: 3x = 12, so x = 4.","Step 2: The x-intercept is (4,0).","Step 3: Set x = 0: y = 12.","Step 4: The y-intercept is (0,12)."],"options":[],"conceptId":"math_linear_programming_drawing_a_boundary_line_from_its_intercepts","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Drawing a Boundary Line from Its Intercepts"}', 2),
  (401, 111, 'Should the boundary of x + y ≤ 10 be solid or broken?', 'text', 1, 'Does ≤ include equality?', '{"why":"≤ includes equality.","sol":"Step 1: The inequality is ≤.\nStep 2: Equality is included.\nStep 3: Therefore points on the boundary are included.\nStep 4: Use a solid line.","steps":["Step 1: The inequality is ≤.","Step 2: Equality is included.","Step 3: Therefore points on the boundary are included.","Step 4: Use a solid line."],"options":[],"conceptId":"math_linear_programming_solid_and_broken_boundary_lines","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Solid and Broken Boundary Lines"}', 0),
  (402, 111, 'Should the boundary of 2x + y ≥ 8 be solid or broken?', 'text', 1, 'Check whether ≥ includes equality.', '{"why":"≥ includes equality.","sol":"Step 1: The inequality is ≥.\nStep 2: Equality is included.\nStep 3: Therefore the boundary belongs to the solution.\nStep 4: Use a solid line.","steps":["Step 1: The inequality is ≥.","Step 2: Equality is included.","Step 3: Therefore the boundary belongs to the solution.","Step 4: Use a solid line."],"options":[],"conceptId":"math_linear_programming_solid_and_broken_boundary_lines","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Solid and Broken Boundary Lines"}', 1),
  (403, 111, 'Should the boundary of x + y > 5 be solid or broken?', 'text', 1, 'Is equality included in >?', '{"why":"> excludes equality.","sol":"Step 1: The inequality is >.\nStep 2: Equality is not included.\nStep 3: Therefore the boundary itself is excluded.\nStep 4: Use a broken line.","steps":["Step 1: The inequality is >.","Step 2: Equality is not included.","Step 3: Therefore the boundary itself is excluded.","Step 4: Use a broken line."],"options":[],"conceptId":"math_linear_programming_solid_and_broken_boundary_lines","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Solid and Broken Boundary Lines"}', 2),
  (404, 112, 'Does (0,0) satisfy x + y ≤ 12?', 'text', 1, 'Substitute x = 0 and y = 0.', '{"why":"The point makes the inequality true.","sol":"Step 1: 0 + 0 ≤ 12.\nStep 2: 0 ≤ 12 is true.\nStep 3: Therefore (0,0) satisfies the inequality.","steps":["Step 1: 0 + 0 ≤ 12.","Step 2: 0 ≤ 12 is true.","Step 3: Therefore (0,0) satisfies the inequality."],"options":[],"conceptId":"math_linear_programming_testing_a_point_in_an_inequality","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Testing a Point in an Inequality"}', 0),
  (405, 112, 'Does (0,0) satisfy 2x + y ≥ 10?', 'text', 1, 'Substitute both coordinates.', '{"why":"The inequality becomes false at (0,0).","sol":"Step 1: 2(0) + 0 ≥ 10.\nStep 2: 0 ≥ 10 is false.\nStep 3: Therefore (0,0) does not satisfy the inequality.","steps":["Step 1: 2(0) + 0 ≥ 10.","Step 2: 0 ≥ 10 is false.","Step 3: Therefore (0,0) does not satisfy the inequality."],"options":[],"conceptId":"math_linear_programming_testing_a_point_in_an_inequality","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Testing a Point in an Inequality"}', 1),
  (406, 112, 'Does (2,4) satisfy x + y ≤ 8?', 'text', 1, 'Calculate 2 + 4 first.', '{"why":"The point makes the inequality true.","sol":"Step 1: Substitute x = 2 and y = 4.\nStep 2: 2 + 4 ≤ 8.\nStep 3: 6 ≤ 8 is true.\nStep 4: Therefore (2,4) satisfies the inequality.","steps":["Step 1: Substitute x = 2 and y = 4.","Step 2: 2 + 4 ≤ 8.","Step 3: 6 ≤ 8 is true.","Step 4: Therefore (2,4) satisfies the inequality."],"options":[],"conceptId":"math_linear_programming_testing_a_point_in_an_inequality","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Testing a Point in an Inequality"}', 2),
  (407, 113, 'For x + y ≤ 6, does the region containing (0,0) satisfy the inequality?', 'text', 1, 'Test (0,0).', '{"why":"The test point satisfies the inequality.","sol":"Step 1: Substitute (0,0).\nStep 2: 0 + 0 ≤ 6.\nStep 3: 0 ≤ 6 is true.\nStep 4: Therefore the region containing (0,0) is the solution region.","steps":["Step 1: Substitute (0,0).","Step 2: 0 + 0 ≤ 6.","Step 3: 0 ≤ 6 is true.","Step 4: Therefore the region containing (0,0) is the solution region."],"options":[],"conceptId":"math_linear_programming_shading_the_region_for","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Shading the Region for ≤"}', 0),
  (408, 113, 'For 2x + y ≤ 10, should the side containing (0,0) be shaded?', 'text', 1, 'Substitute (0,0).', '{"why":"The test point makes the inequality true.","sol":"Step 1: 2(0) + 0 ≤ 10.\nStep 2: 0 ≤ 10 is true.\nStep 3: Therefore (0,0) is in the solution region.\nStep 4: Shade the side containing (0,0).","steps":["Step 1: 2(0) + 0 ≤ 10.","Step 2: 0 ≤ 10 is true.","Step 3: Therefore (0,0) is in the solution region.","Step 4: Shade the side containing (0,0)."],"options":[],"conceptId":"math_linear_programming_shading_the_region_for","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Shading the Region for ≤"}', 1),
  (409, 113, 'Why is testing a point safer than simply memorising ''shade below the line''?', 'text', 1, 'Think about lines with different slopes and rearrangements.', '{"why":"Testing a point works regardless of the orientation of the boundary line.","sol":"Step 1: Different inequalities can have different line arrangements.\nStep 2: The words above and below can become misleading.\nStep 3: A test point directly checks whether a region satisfies the original inequality.\nStep 4: Therefore testing is more reliable.","steps":["Step 1: Different inequalities can have different line arrangements.","Step 2: The words above and below can become misleading.","Step 3: A test point directly checks whether a region satisfies the original inequality.","Step 4: Therefore testing is more reliable."],"options":[],"conceptId":"math_linear_programming_shading_the_region_for","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Shading the Region for ≤"}', 2),
  (410, 114, 'For x + y ≥ 8, does (0,0) lie in the solution region?', 'text', 1, 'Test the point.', '{"why":"The point does not satisfy the inequality.","sol":"Step 1: 0 + 0 ≥ 8.\nStep 2: 0 ≥ 8 is false.\nStep 3: Therefore (0,0) is not in the solution region.","steps":["Step 1: 0 + 0 ≥ 8.","Step 2: 0 ≥ 8 is false.","Step 3: Therefore (0,0) is not in the solution region."],"options":[],"conceptId":"math_linear_programming_shading_the_region_for","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Shading the Region for ≥"}', 0),
  (411, 114, 'For 2x + y ≥ 10, is the region containing (0,0) the solution region?', 'text', 1, 'Substitute (0,0).', '{"why":"The test point fails the inequality.","sol":"Step 1: 2(0) + 0 ≥ 10.\nStep 2: 0 ≥ 10 is false.\nStep 3: Therefore the region containing (0,0) is not the solution region.","steps":["Step 1: 2(0) + 0 ≥ 10.","Step 2: 0 ≥ 10 is false.","Step 3: Therefore the region containing (0,0) is not the solution region."],"options":[],"conceptId":"math_linear_programming_shading_the_region_for","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Shading the Region for ≥"}', 1),
  (412, 114, 'For x + y ≥ 6, does (4,3) belong to the solution region?', 'text', 1, 'Calculate 4 + 3.', '{"why":"The coordinates make the inequality true.","sol":"Step 1: 4 + 3 ≥ 6.\nStep 2: 7 ≥ 6 is true.\nStep 3: Therefore (4,3) belongs to the solution region.","steps":["Step 1: 4 + 3 ≥ 6.","Step 2: 7 ≥ 6 is true.","Step 3: Therefore (4,3) belongs to the solution region."],"options":[],"conceptId":"math_linear_programming_shading_the_region_for","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Shading the Region for ≥"}', 2),
  (413, 115, 'Find the two intercepts of 2x + 3y = 12.', 'text', 1, 'Set y = 0, then set x = 0.', '{"why":"The coefficients determine the intercepts.","sol":"Step 1: For the x-intercept, y = 0.\nStep 2: 2x = 12, so x = 6.\nStep 3: Therefore the x-intercept is (6,0).\nStep 4: For the y-intercept, x = 0.\nStep 5: 3y = 12, so y = 4.\nStep 6: Therefore the y-intercept is (0,4).","steps":["Step 1: For the x-intercept, y = 0.","Step 2: 2x = 12, so x = 6.","Step 3: Therefore the x-intercept is (6,0).","Step 4: For the y-intercept, x = 0.","Step 5: 3y = 12, so y = 4.","Step 6: Therefore the y-intercept is (0,4)."],"options":[],"conceptId":"math_linear_programming_graphing_an_inequality_with_different_coefficients","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Graphing an Inequality with Different Coefficients"}', 0),
  (414, 115, 'Find the x-intercept of 5x + 2y = 20.', 'text', 1, 'Set y = 0.', '{"why":"The x-axis has y = 0.","sol":"Step 1: Set y = 0.\nStep 2: 5x = 20.\nStep 3: x = 4.\nStep 4: Therefore the x-intercept is (4,0).","steps":["Step 1: Set y = 0.","Step 2: 5x = 20.","Step 3: x = 4.","Step 4: Therefore the x-intercept is (4,0)."],"options":[],"conceptId":"math_linear_programming_graphing_an_inequality_with_different_coefficients","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Graphing an Inequality with Different Coefficients"}', 1),
  (415, 115, 'Find the y-intercept of 3x + 4y = 24.', 'text', 1, 'Set x = 0.', '{"why":"The y-axis has x = 0.","sol":"Step 1: Set x = 0.\nStep 2: 4y = 24.\nStep 3: y = 6.\nStep 4: Therefore the y-intercept is (0,6).","steps":["Step 1: Set x = 0.","Step 2: 4y = 24.","Step 3: y = 6.","Step 4: Therefore the y-intercept is (0,6)."],"options":[],"conceptId":"math_linear_programming_graphing_an_inequality_with_different_coefficients","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Graphing an Inequality with Different Coefficients"}', 2),
  (416, 116, 'A point must satisfy x + y ≤ 10 and x ≥ 2. Does (1,4) satisfy both?', 'text', 1, 'Test the point in each inequality separately.', '{"why":"A feasible point must satisfy every constraint.","sol":"Step 1: First: 1 + 4 ≤ 10, which is true.\nStep 2: Second: 1 ≥ 2, which is false.\nStep 3: Because one condition fails, the point is not in the common region.","steps":["Step 1: First: 1 + 4 ≤ 10, which is true.","Step 2: Second: 1 ≥ 2, which is false.","Step 3: Because one condition fails, the point is not in the common region."],"options":[],"conceptId":"math_linear_programming_graphing_two_inequalities_together","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Graphing Two Inequalities Together"}', 0),
  (417, 116, 'Does (3,4) satisfy x + y ≤ 10 and x ≥ 2?', 'text', 1, 'Check both inequalities.', '{"why":"The point lies in the overlap of the two solution regions.","sol":"Step 1: 3 + 4 ≤ 10 gives 7 ≤ 10, true.\nStep 2: 3 ≥ 2 is also true.\nStep 3: Therefore the point satisfies both constraints.","steps":["Step 1: 3 + 4 ≤ 10 gives 7 ≤ 10, true.","Step 2: 3 ≥ 2 is also true.","Step 3: Therefore the point satisfies both constraints."],"options":[],"conceptId":"math_linear_programming_graphing_two_inequalities_together","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Graphing Two Inequalities Together"}', 1),
  (418, 116, 'Why do we need the overlap when graphing two inequalities?', 'text', 1, 'Think about what ''satisfying both'' means.', '{"why":"The intersection of the regions represents choices that obey every constraint.","sol":"Step 1: Each inequality imposes a separate condition.\nStep 2: A valid point must obey the first condition.\nStep 3: It must also obey the second condition.\nStep 4: Therefore only the common region is acceptable.","steps":["Step 1: Each inequality imposes a separate condition.","Step 2: A valid point must obey the first condition.","Step 3: It must also obey the second condition.","Step 4: Therefore only the common region is acceptable."],"options":[],"conceptId":"math_linear_programming_graphing_two_inequalities_together","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Graphing Two Inequalities Together"}', 2),
  (419, 117, 'What is a feasible region?', 'text', 1, 'Think about all the constraints together.', '{"why":"Feasibility means that a choice obeys all restrictions.","sol":"Step 1: Each constraint limits the possible choices.\nStep 2: A feasible point must satisfy every constraint.\nStep 3: The collection of all such points forms the feasible region.","steps":["Step 1: Each constraint limits the possible choices.","Step 2: A feasible point must satisfy every constraint.","Step 3: The collection of all such points forms the feasible region."],"options":[],"conceptId":"math_linear_programming_meaning_of_the_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Meaning of the Feasible Region"}', 0),
  (420, 117, 'Does the point (3,4) satisfy x + y ≤ 10, x ≥ 0 and y ≥ 0?', 'text', 1, 'Check all three conditions.', '{"why":"A point is feasible when every constraint is satisfied.","sol":"Step 1: 3 + 4 ≤ 10 gives 7 ≤ 10, true.\nStep 2: 3 ≥ 0 is true.\nStep 3: 4 ≥ 0 is true.\nStep 4: Therefore the point satisfies every constraint.","steps":["Step 1: 3 + 4 ≤ 10 gives 7 ≤ 10, true.","Step 2: 3 ≥ 0 is true.","Step 3: 4 ≥ 0 is true.","Step 4: Therefore the point satisfies every constraint."],"options":[],"conceptId":"math_linear_programming_meaning_of_the_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Meaning of the Feasible Region"}', 1),
  (421, 117, 'A point satisfies two constraints but violates a third. Is it feasible?', 'text', 1, 'Feasible means all conditions must hold.', '{"why":"One violated constraint is enough to make a point infeasible.","sol":"Step 1: Every constraint must be satisfied.\nStep 2: The point violates one constraint.\nStep 3: Therefore it is not feasible.","steps":["Step 1: Every constraint must be satisfied.","Step 2: The point violates one constraint.","Step 3: Therefore it is not feasible."],"options":[],"conceptId":"math_linear_programming_meaning_of_the_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Meaning of the Feasible Region"}', 2),
  (422, 118, 'If two inequalities are graphed, what part of the graph is feasible?', 'text', 1, 'Think about what both inequalities require.', '{"why":"The feasible region must satisfy all constraints.","sol":"Step 1: Each inequality creates a solution region.\nStep 2: A feasible point must satisfy both.\nStep 3: Therefore the overlapping part is feasible.","steps":["Step 1: Each inequality creates a solution region.","Step 2: A feasible point must satisfy both.","Step 3: Therefore the overlapping part is feasible."],"options":[],"conceptId":"math_linear_programming_identifying_the_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Identifying the Feasible Region"}', 0),
  (423, 118, 'If x ≥ 0 and y ≥ 0 are constraints, which part of the coordinate plane can contain feasible points?', 'text', 1, 'Think about the signs of x and y.', '{"why":"Both coordinates must be zero or positive.","sol":"Step 1: x ≥ 0 means x cannot be negative.\nStep 2: y ≥ 0 means y cannot be negative.\nStep 3: Therefore both coordinates must be non-negative.\nStep 4: This is the first quadrant together with its axes.","steps":["Step 1: x ≥ 0 means x cannot be negative.","Step 2: y ≥ 0 means y cannot be negative.","Step 3: Therefore both coordinates must be non-negative.","Step 4: This is the first quadrant together with its axes."],"options":[],"conceptId":"math_linear_programming_identifying_the_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Identifying the Feasible Region"}', 1),
  (424, 118, 'A point lies in the region satisfying the first constraint but outside the region satisfying the second. Is it feasible?', 'text', 1, 'Does it satisfy every condition?', '{"why":"Feasibility requires all constraints to be satisfied.","sol":"Step 1: The point satisfies the first condition.\nStep 2: It violates the second condition.\nStep 3: Therefore it does not satisfy all constraints.","steps":["Step 1: The point satisfies the first condition.","Step 2: It violates the second condition.","Step 3: Therefore it does not satisfy all constraints."],"options":[],"conceptId":"math_linear_programming_identifying_the_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Identifying the Feasible Region"}', 2),
  (425, 119, 'Is (2,6) feasible for x + y ≤ 10, x ≥ 0 and y ≥ 0?', 'text', 1, 'Check all three conditions.', '{"why":"The point satisfies every constraint.","sol":"Step 1: 2 + 6 ≤ 10 gives 8 ≤ 10, true.\nStep 2: 2 ≥ 0 is true.\nStep 3: 6 ≥ 0 is true.\nStep 4: All constraints are satisfied.","steps":["Step 1: 2 + 6 ≤ 10 gives 8 ≤ 10, true.","Step 2: 2 ≥ 0 is true.","Step 3: 6 ≥ 0 is true.","Step 4: All constraints are satisfied."],"options":[],"conceptId":"math_linear_programming_checking_whether_a_point_is_feasible","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Checking Whether a Point Is Feasible"}', 0),
  (426, 119, 'Is (1,5) feasible for x + y ≤ 10 and x ≥ 2?', 'text', 1, 'One constraint may fail.', '{"why":"The point violates x ≥ 2.","sol":"Step 1: 1 + 5 ≤ 10 gives 6 ≤ 10, true.\nStep 2: But 1 ≥ 2 is false.\nStep 3: Therefore the point is not feasible.","steps":["Step 1: 1 + 5 ≤ 10 gives 6 ≤ 10, true.","Step 2: But 1 ≥ 2 is false.","Step 3: Therefore the point is not feasible."],"options":[],"conceptId":"math_linear_programming_checking_whether_a_point_is_feasible","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Checking Whether a Point Is Feasible"}', 1),
  (427, 119, 'Is (5,4) feasible for 2x + y ≤ 12, x ≥ 0 and y ≥ 0?', 'text', 1, 'Start with 2x + y.', '{"why":"The point violates the first constraint.","sol":"Step 1: 2(5) + 4 = 14.\nStep 2: 14 ≤ 12 is false.\nStep 3: Therefore the point is not feasible.","steps":["Step 1: 2(5) + 4 = 14.","Step 2: 14 ≤ 12 is false.","Step 3: Therefore the point is not feasible."],"options":[],"conceptId":"math_linear_programming_checking_whether_a_point_is_feasible","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Checking Whether a Point Is Feasible"}', 2),
  (428, 120, 'For x + y ≤ 8, x ≥ 0 and y ≥ 0, which side of x + y = 8 contains the feasible region?', 'text', 1, 'Test the origin.', '{"why":"The origin satisfies the inequality and the non-negativity constraints.","sol":"Step 1: Substitute (0,0).\nStep 2: 0 + 0 ≤ 8 is true.\nStep 3: Therefore the side containing (0,0) satisfies the inequality.\nStep 4: Because x and y must also be non-negative, only the first-quadrant portion is feasible.","steps":["Step 1: Substitute (0,0).","Step 2: 0 + 0 ≤ 8 is true.","Step 3: Therefore the side containing (0,0) satisfies the inequality.","Step 4: Because x and y must also be non-negative, only the first-quadrant portion is feasible."],"options":[],"conceptId":"math_linear_programming_constructing_a_feasible_region_from_three_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Constructing a Feasible Region from Three Constraints"}', 0),
  (429, 120, 'For 2x + y ≤ 10, x ≥ 0 and y ≥ 0, find the boundary intercepts.', 'text', 1, 'Set y = 0 and then x = 0.', '{"why":"These are the axis points of the boundary.","sol":"Step 1: Set y = 0: 2x = 10, so x = 5.\nStep 2: The x-intercept is (5,0).\nStep 3: Set x = 0: y = 10.\nStep 4: The y-intercept is (0,10).","steps":["Step 1: Set y = 0: 2x = 10, so x = 5.","Step 2: The x-intercept is (5,0).","Step 3: Set x = 0: y = 10.","Step 4: The y-intercept is (0,10)."],"options":[],"conceptId":"math_linear_programming_constructing_a_feasible_region_from_three_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Constructing a Feasible Region from Three Constraints"}', 1),
  (430, 120, 'What must be true of every point inside the feasible region?', 'text', 1, 'Think about the definition of feasible.', '{"why":"The feasible region is the common solution to all constraints.","sol":"Step 1: A feasible point is an allowed choice.\nStep 2: Every restriction must be satisfied.\nStep 3: Therefore every point in the feasible region satisfies every constraint.","steps":["Step 1: A feasible point is an allowed choice.","Step 2: Every restriction must be satisfied.","Step 3: Therefore every point in the feasible region satisfies every constraint."],"options":[],"conceptId":"math_linear_programming_constructing_a_feasible_region_from_three_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Constructing a Feasible Region from Three Constraints"}', 2),
  (431, 121, 'If x represents shirts and y represents trousers, what does the point (6,4) represent?', 'text', 1, 'Read the x-coordinate first and the y-coordinate second.', '{"why":"Coordinates give the values of the decision variables.","sol":"Step 1: The x-coordinate is 6.\nStep 2: x represents shirts.\nStep 3: The y-coordinate is 4.\nStep 4: y represents trousers.","steps":["Step 1: The x-coordinate is 6.","Step 2: x represents shirts.","Step 3: The y-coordinate is 4.","Step 4: y represents trousers."],"options":[],"conceptId":"math_linear_programming_reading_a_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Reading a Feasible Region"}', 0),
  (432, 121, 'If x represents hectares of maize and y represents hectares of beans, what does (3,7) mean?', 'text', 1, 'Match each coordinate to its variable.', '{"why":"The coordinates describe the chosen quantities.","sol":"Step 1: x = 3, so maize uses 3 hectares.\nStep 2: y = 7, so beans use 7 hectares.","steps":["Step 1: x = 3, so maize uses 3 hectares.","Step 2: y = 7, so beans use 7 hectares."],"options":[],"conceptId":"math_linear_programming_reading_a_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Reading a Feasible Region"}', 1),
  (433, 121, 'If a point lies inside the feasible region, what does that tell us about the corresponding choice?', 'text', 1, 'Think about what feasible means.', '{"why":"The feasible region represents allowed combinations of the decision variables.","sol":"Step 1: Every point in the feasible region satisfies every constraint.\nStep 2: Therefore the corresponding choice obeys all restrictions.","steps":["Step 1: Every point in the feasible region satisfies every constraint.","Step 2: Therefore the corresponding choice obeys all restrictions."],"options":[],"conceptId":"math_linear_programming_reading_a_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Reading a Feasible Region"}', 2),
  (434, 122, 'What does x + y = 50 represent if x and y are quantities of two products?', 'text', 1, 'Look at the equality.', '{"why":"The boundary equation represents the limiting value itself.","sol":"Step 1: x + y gives the total quantity.\nStep 2: The equality says the total is exactly 50.\nStep 3: Therefore the boundary represents combinations whose total is 50.","steps":["Step 1: x + y gives the total quantity.","Step 2: The equality says the total is exactly 50.","Step 3: Therefore the boundary represents combinations whose total is 50."],"options":[],"conceptId":"math_linear_programming_interpreting_the_boundary_and_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Interpreting the Boundary and Feasible Region"}', 0),
  (435, 122, 'For x + y ≤ 100, is (40,50) within the allowed region?', 'text', 1, 'Add the coordinates.', '{"why":"The total is below the maximum of 100.","sol":"Step 1: 40 + 50 = 90.\nStep 2: 90 ≤ 100 is true.\nStep 3: Therefore the point satisfies the constraint.","steps":["Step 1: 40 + 50 = 90.","Step 2: 90 ≤ 100 is true.","Step 3: Therefore the point satisfies the constraint."],"options":[],"conceptId":"math_linear_programming_interpreting_the_boundary_and_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Interpreting the Boundary and Feasible Region"}', 1),
  (436, 122, 'For x + y ≤ 100, is (70,40) allowed?', 'text', 1, 'Calculate the total first.', '{"why":"The total exceeds the maximum allowed value.","sol":"Step 1: 70 + 40 = 110.\nStep 2: 110 ≤ 100 is false.\nStep 3: Therefore the point is outside the allowed region.","steps":["Step 1: 70 + 40 = 110.","Step 2: 110 ≤ 100 is false.","Step 3: Therefore the point is outside the allowed region."],"options":[],"conceptId":"math_linear_programming_interpreting_the_boundary_and_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Interpreting the Boundary and Feasible Region"}', 2),
  (437, 123, 'Find where 2x + y = 8 meets the x-axis.', 'text', 1, 'Set y = 0.', '{"why":"Every point on the x-axis has y = 0.","sol":"Step 1: Set y = 0.\nStep 2: 2x = 8.\nStep 3: x = 4.\nStep 4: Therefore the point is (4,0).","steps":["Step 1: Set y = 0.","Step 2: 2x = 8.","Step 3: x = 4.","Step 4: Therefore the point is (4,0)."],"options":[],"conceptId":"math_linear_programming_finding_a_corner_point_on_an_axis","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Finding a Corner Point on an Axis"}', 0),
  (438, 123, 'Find where 2x + y = 8 meets the y-axis.', 'text', 1, 'Set x = 0.', '{"why":"Every point on the y-axis has x = 0.","sol":"Step 1: Set x = 0.\nStep 2: y = 8.\nStep 3: Therefore the point is (0,8).","steps":["Step 1: Set x = 0.","Step 2: y = 8.","Step 3: Therefore the point is (0,8)."],"options":[],"conceptId":"math_linear_programming_finding_a_corner_point_on_an_axis","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Finding a Corner Point on an Axis"}', 1),
  (439, 123, 'Find the x-axis point on 3x + y = 15.', 'text', 1, 'Set y = 0.', '{"why":"Setting y to zero gives the x-axis intersection.","sol":"Step 1: Set y = 0.\nStep 2: 3x = 15.\nStep 3: x = 5.\nStep 4: Therefore the point is (5,0).","steps":["Step 1: Set y = 0.","Step 2: 3x = 15.","Step 3: x = 5.","Step 4: Therefore the point is (5,0)."],"options":[],"conceptId":"math_linear_programming_finding_a_corner_point_on_an_axis","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Finding a Corner Point on an Axis"}', 2),
  (440, 124, 'Find the intersection of x + y = 6 and x + 2y = 10.', 'text', 1, 'Subtract the first equation from the second.', '{"why":"The point satisfies both boundary equations.","sol":"Step 1: (x + 2y) - (x + y) = 10 - 6.\nStep 2: y = 4.\nStep 3: Substitute into x + y = 6.\nStep 4: x + 4 = 6.\nStep 5: x = 2.\nStep 6: Therefore the intersection is (2,4).","steps":["Step 1: (x + 2y) - (x + y) = 10 - 6.","Step 2: y = 4.","Step 3: Substitute into x + y = 6.","Step 4: x + 4 = 6.","Step 5: x = 2.","Step 6: Therefore the intersection is (2,4)."],"options":[],"conceptId":"math_linear_programming_finding_the_intersection_of_two_boundary_lines","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Finding the Intersection of Two Boundary Lines"}', 0),
  (441, 124, 'Find the intersection of 2x + y = 9 and x + y = 6.', 'text', 1, 'Subtract the second equation from the first.', '{"why":"The point lies on both boundary lines.","sol":"Step 1: (2x + y) - (x + y) = 9 - 6.\nStep 2: x = 3.\nStep 3: Substitute into x + y = 6.\nStep 4: 3 + y = 6.\nStep 5: y = 3.","steps":["Step 1: (2x + y) - (x + y) = 9 - 6.","Step 2: x = 3.","Step 3: Substitute into x + y = 6.","Step 4: 3 + y = 6.","Step 5: y = 3."],"options":[],"conceptId":"math_linear_programming_finding_the_intersection_of_two_boundary_lines","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Finding the Intersection of Two Boundary Lines"}', 1),
  (442, 124, 'Why must an intersection point still be checked against the other constraints?', 'text', 1, 'A point can lie on two boundaries but violate another restriction.', '{"why":"A feasible corner must satisfy every constraint, not just the two equations that produced it.","sol":"Step 1: The intersection satisfies the two equations used to find it.\nStep 2: A linear programming problem may have additional constraints.\nStep 3: The point must satisfy those as well.\nStep 4: Therefore the intersection is only a candidate until checked.","steps":["Step 1: The intersection satisfies the two equations used to find it.","Step 2: A linear programming problem may have additional constraints.","Step 3: The point must satisfy those as well.","Step 4: Therefore the intersection is only a candidate until checked."],"options":[],"conceptId":"math_linear_programming_finding_the_intersection_of_two_boundary_lines","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Finding the Intersection of Two Boundary Lines"}', 2),
  (443, 125, 'Is (6,4) feasible for x + y ≤ 10, x + 2y ≤ 14, x ≥ 0 and y ≥ 0?', 'text', 1, 'Test every condition.', '{"why":"The point satisfies every constraint.","sol":"Step 1: 6 + 4 = 10, so the first condition is true.\nStep 2: 6 + 2(4) = 14, so the second condition is true.\nStep 3: 6 ≥ 0 is true.\nStep 4: 4 ≥ 0 is true.\nStep 5: Therefore the point is feasible.","steps":["Step 1: 6 + 4 = 10, so the first condition is true.","Step 2: 6 + 2(4) = 14, so the second condition is true.","Step 3: 6 ≥ 0 is true.","Step 4: 4 ≥ 0 is true.","Step 5: Therefore the point is feasible."],"options":[],"conceptId":"math_linear_programming_checking_an_intersection_against_all_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Checking an Intersection Against All Constraints"}', 0),
  (444, 125, 'Is (4,5) feasible for x + y ≤ 10 and x ≥ 5?', 'text', 1, 'One constraint fails.', '{"why":"A single violated constraint makes the point infeasible.","sol":"Step 1: 4 + 5 = 9, so x + y ≤ 10 is true.\nStep 2: But 4 ≥ 5 is false.\nStep 3: Therefore the point is not feasible.","steps":["Step 1: 4 + 5 = 9, so x + y ≤ 10 is true.","Step 2: But 4 ≥ 5 is false.","Step 3: Therefore the point is not feasible."],"options":[],"conceptId":"math_linear_programming_checking_an_intersection_against_all_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Checking an Intersection Against All Constraints"}', 1),
  (445, 125, 'Can (-2,4) be a feasible point when x ≥ 0 is a constraint?', 'text', 1, 'Check the x-coordinate.', '{"why":"The point violates the non-negativity constraint.","sol":"Step 1: The x-coordinate is -2.\nStep 2: The constraint requires x ≥ 0.\nStep 3: -2 ≥ 0 is false.\nStep 4: Therefore the point cannot be feasible.","steps":["Step 1: The x-coordinate is -2.","Step 2: The constraint requires x ≥ 0.","Step 3: -2 ≥ 0 is false.","Step 4: Therefore the point cannot be feasible."],"options":[],"conceptId":"math_linear_programming_checking_an_intersection_against_all_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Checking an Intersection Against All Constraints"}', 2),
  (446, 126, 'Find the three corner points for x + y ≤ 6, x ≥ 0 and y ≥ 0.', 'text', 1, 'Find the two intercepts and include the origin.', '{"why":"The boundary and the coordinate axes form the triangular feasible region.","sol":"Step 1: x-intercept: set y = 0, giving x = 6 → (6,0).\nStep 2: y-intercept: set x = 0, giving y = 6 → (0,6).\nStep 3: The axes meet at (0,0).\nStep 4: Therefore the corners are (0,0), (6,0), and (0,6).","steps":["Step 1: x-intercept: set y = 0, giving x = 6 → (6,0).","Step 2: y-intercept: set x = 0, giving y = 6 → (0,6).","Step 3: The axes meet at (0,0).","Step 4: Therefore the corners are (0,0), (6,0), and (0,6)."],"options":[],"conceptId":"math_linear_programming_finding_corner_points_from_axes_and_boundary_lines","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Finding Corner Points from Axes and Boundary Lines"}', 0),
  (447, 126, 'Find the axis corner points for 2x + y ≤ 12, x ≥ 0 and y ≥ 0.', 'text', 1, 'Find both intercepts.', '{"why":"These are the points where the boundary and axes meet.","sol":"Step 1: Set y = 0: 2x = 12, so x = 6 → (6,0).\nStep 2: Set x = 0: y = 12 → (0,12).\nStep 3: The origin is also a corner.","steps":["Step 1: Set y = 0: 2x = 12, so x = 6 → (6,0).","Step 2: Set x = 0: y = 12 → (0,12).","Step 3: The origin is also a corner."],"options":[],"conceptId":"math_linear_programming_finding_corner_points_from_axes_and_boundary_lines","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Finding Corner Points from Axes and Boundary Lines"}', 1),
  (448, 126, 'Why is (0,0) often a corner point when x ≥ 0 and y ≥ 0?', 'text', 1, 'Where do the x-axis and y-axis meet?', '{"why":"The non-negativity constraints make the axes boundaries of the feasible region.","sol":"Step 1: x ≥ 0 restricts the graph to the non-negative x side.\nStep 2: y ≥ 0 restricts it to the non-negative y side.\nStep 3: The two axes meet at (0,0).\nStep 4: Therefore the origin can form a corner of the feasible region.","steps":["Step 1: x ≥ 0 restricts the graph to the non-negative x side.","Step 2: y ≥ 0 restricts it to the non-negative y side.","Step 3: The two axes meet at (0,0).","Step 4: Therefore the origin can form a corner of the feasible region."],"options":[],"conceptId":"math_linear_programming_finding_corner_points_from_axes_and_boundary_lines","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Finding Corner Points from Axes and Boundary Lines"}', 2),
  (449, 127, 'A product gives KSh 400 profit per unit of x and KSh 300 profit per unit of y. What is the objective function?', 'text', 1, 'Multiply each profit per unit by the number of units.', '{"why":"The objective function represents the total profit.","sol":"Step 1: Profit from x units = 400x.\nStep 2: Profit from y units = 300y.\nStep 3: Add the two amounts.\nStep 4: Therefore P = 400x + 300y.","steps":["Step 1: Profit from x units = 400x.","Step 2: Profit from y units = 300y.","Step 3: Add the two amounts.","Step 4: Therefore P = 400x + 300y."],"options":[],"conceptId":"math_linear_programming_meaning_of_an_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Meaning of an Objective Function"}', 0),
  (450, 127, 'A company spends KSh 200 on each unit of x and KSh 500 on each unit of y. Write the total cost.', 'text', 1, 'Cost = cost per unit × number of units.', '{"why":"The expression represents the total cost.","sol":"Step 1: Cost of x units = 200x.\nStep 2: Cost of y units = 500y.\nStep 3: Add them.\nStep 4: C = 200x + 500y.","steps":["Step 1: Cost of x units = 200x.","Step 2: Cost of y units = 500y.","Step 3: Add them.","Step 4: C = 200x + 500y."],"options":[],"conceptId":"math_linear_programming_meaning_of_an_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Meaning of an Objective Function"}', 1),
  (451, 127, 'If P = 700x + 400y represents profit, and the aim is to obtain the greatest profit, what should be done to P?', 'text', 1, 'The greatest value is the maximum.', '{"why":"The objective is to make profit as large as possible.","sol":"Step 1: P represents profit.\nStep 2: The aim is to obtain the greatest profit.\nStep 3: Therefore P must be maximized.","steps":["Step 1: P represents profit.","Step 2: The aim is to obtain the greatest profit.","Step 3: Therefore P must be maximized."],"options":[],"conceptId":"math_linear_programming_meaning_of_an_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Meaning of an Objective Function"}', 2),
  (452, 128, 'A company wants to obtain the greatest profit. What is the objective?', 'text', 1, 'What quantity is being made greatest?', '{"why":"Profit is the quantity the company wants to maximize.","sol":"Step 1: Read the phrase ''greatest profit''.\nStep 2: The quantity being considered is profit.\nStep 3: Therefore the objective is profit.","steps":["Step 1: Read the phrase ''greatest profit''.","Step 2: The quantity being considered is profit.","Step 3: Therefore the objective is profit."],"options":[],"conceptId":"math_linear_programming_identifying_the_objective_in_a_word_problem","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Identifying the Objective in a Word Problem"}', 0),
  (453, 128, 'A manufacturer wants to spend the least amount of money. What is the objective?', 'text', 1, 'What quantity should be as small as possible?', '{"why":"The problem is trying to minimize the cost.","sol":"Step 1: The phrase ''least amount of money'' refers to expenditure or cost.\nStep 2: The amount must be made as small as possible.\nStep 3: Therefore the objective is cost.","steps":["Step 1: The phrase ''least amount of money'' refers to expenditure or cost.","Step 2: The amount must be made as small as possible.","Step 3: Therefore the objective is cost."],"options":[],"conceptId":"math_linear_programming_identifying_the_objective_in_a_word_problem","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Identifying the Objective in a Word Problem"}', 1),
  (454, 128, 'A business wants the highest possible sales income. What is the objective?', 'text', 1, 'Sales income is another name for revenue.', '{"why":"Revenue is the quantity being made as large as possible.","sol":"Step 1: Sales income means revenue.\nStep 2: The word ''highest'' means maximum.\nStep 3: Therefore the objective is to maximize revenue.","steps":["Step 1: Sales income means revenue.","Step 2: The word ''highest'' means maximum.","Step 3: Therefore the objective is to maximize revenue."],"options":[],"conceptId":"math_linear_programming_identifying_the_objective_in_a_word_problem","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Identifying the Objective in a Word Problem"}', 2),
  (455, 129, 'A pen gives KSh 20 profit and a book gives KSh 50 profit. If x pens and y books are sold, form the profit function.', 'text', 1, 'Multiply each unit profit by its quantity.', '{"why":"Total profit is the sum of the profits from both products.","sol":"Step 1: Pen profit = 20x.\nStep 2: Book profit = 50y.\nStep 3: Add the two profits.\nStep 4: P = 20x + 50y.","steps":["Step 1: Pen profit = 20x.","Step 2: Book profit = 50y.","Step 3: Add the two profits.","Step 4: P = 20x + 50y."],"options":[],"conceptId":"math_linear_programming_forming_a_profit_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Forming a Profit Objective Function"}', 0),
  (456, 129, 'A farmer earns KSh 900 per bag of maize and KSh 700 per bag of beans. Form the profit function.', 'text', 1, 'Let x be maize and y be beans.', '{"why":"Each coefficient represents the profit from one unit.","sol":"Step 1: Maize profit = 900x.\nStep 2: Bean profit = 700y.\nStep 3: Add the two.\nStep 4: P = 900x + 700y.","steps":["Step 1: Maize profit = 900x.","Step 2: Bean profit = 700y.","Step 3: Add the two.","Step 4: P = 900x + 700y."],"options":[],"conceptId":"math_linear_programming_forming_a_profit_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Forming a Profit Objective Function"}', 1),
  (457, 129, 'A shop earns KSh 150 on each shirt and KSh 250 on each jacket. Form the profit function.', 'text', 1, 'Use x for shirts and y for jackets.', '{"why":"The function adds the profit contributed by each product.","sol":"Step 1: Shirt profit = 150x.\nStep 2: Jacket profit = 250y.\nStep 3: Total profit = 150x + 250y.","steps":["Step 1: Shirt profit = 150x.","Step 2: Jacket profit = 250y.","Step 3: Total profit = 150x + 250y."],"options":[],"conceptId":"math_linear_programming_forming_a_profit_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Forming a Profit Objective Function"}', 2),
  (458, 130, 'A material costs KSh 400 per unit and another costs KSh 600 per unit. Form the total cost function.', 'text', 1, 'Let x and y be the quantities.', '{"why":"The total cost is the sum of the two individual costs.","sol":"Step 1: First material costs 400x.\nStep 2: Second material costs 600y.\nStep 3: Add them.\nStep 4: C = 400x + 600y.","steps":["Step 1: First material costs 400x.","Step 2: Second material costs 600y.","Step 3: Add them.","Step 4: C = 400x + 600y."],"options":[],"conceptId":"math_linear_programming_forming_a_cost_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Forming a Cost Objective Function"}', 0),
  (459, 130, 'Pens cost KSh 15 each and books cost KSh 80 each. Form the total cost function.', 'text', 1, 'Let x be pens and y be books.', '{"why":"Each coefficient is the cost of one unit.","sol":"Step 1: Pen cost = 15x.\nStep 2: Book cost = 80y.\nStep 3: Total cost = 15x + 80y.","steps":["Step 1: Pen cost = 15x.","Step 2: Book cost = 80y.","Step 3: Total cost = 15x + 80y."],"options":[],"conceptId":"math_linear_programming_forming_a_cost_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Forming a Cost Objective Function"}', 1),
  (460, 130, 'A company wants to spend the least possible amount and its cost function is C = 700x + 500y. What is the objective?', 'text', 1, 'Least means minimum.', '{"why":"The objective is to make the total cost as small as possible.","sol":"Step 1: C represents total cost.\nStep 2: The problem asks for the least cost.\nStep 3: Therefore C must be minimized.","steps":["Step 1: C represents total cost.","Step 2: The problem asks for the least cost.","Step 3: Therefore C must be minimized."],"options":[],"conceptId":"math_linear_programming_forming_a_cost_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Forming a Cost Objective Function"}', 2),
  (461, 131, 'A product sells for KSh 500 per unit and another sells for KSh 800 per unit. Form the revenue function.', 'text', 1, 'Revenue = selling price × quantity.', '{"why":"Revenue comes from multiplying selling price by the number sold.","sol":"Step 1: Revenue from the first product = 500x.\nStep 2: Revenue from the second product = 800y.\nStep 3: Add them.\nStep 4: R = 500x + 800y.","steps":["Step 1: Revenue from the first product = 500x.","Step 2: Revenue from the second product = 800y.","Step 3: Add them.","Step 4: R = 500x + 800y."],"options":[],"conceptId":"math_linear_programming_forming_a_revenue_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Forming a Revenue Objective Function"}', 0),
  (462, 131, 'A farmer sells maize at KSh 3,500 per bag and beans at KSh 4,000 per bag. Form the revenue function.', 'text', 1, 'Use x for maize and y for beans.', '{"why":"The coefficients are the selling prices per unit.","sol":"Step 1: Maize revenue = 3500x.\nStep 2: Bean revenue = 4000y.\nStep 3: Add the revenues.\nStep 4: R = 3500x + 4000y.","steps":["Step 1: Maize revenue = 3500x.","Step 2: Bean revenue = 4000y.","Step 3: Add the revenues.","Step 4: R = 3500x + 4000y."],"options":[],"conceptId":"math_linear_programming_forming_a_revenue_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Forming a Revenue Objective Function"}', 1),
  (463, 131, 'If R = 120x + 200y represents revenue and the aim is to get the highest revenue, what should be done?', 'text', 1, 'Highest means maximum.', '{"why":"The objective is to make revenue as large as possible.","sol":"Step 1: R represents revenue.\nStep 2: The aim is the highest revenue.\nStep 3: Therefore R should be maximized.","steps":["Step 1: R represents revenue.","Step 2: The aim is the highest revenue.","Step 3: Therefore R should be maximized."],"options":[],"conceptId":"math_linear_programming_forming_a_revenue_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Forming a Revenue Objective Function"}', 2),
  (464, 132, 'A product gives KSh 900 profit per unit. If x units are produced, what expression represents the profit?', 'text', 1, 'Multiply 900 by x.', '{"why":"The per-unit profit becomes the coefficient of x.","sol":"Step 1: Profit per unit = 900.\nStep 2: Number of units = x.\nStep 3: Total profit = 900 × x.\nStep 4: Therefore profit = 900x.","steps":["Step 1: Profit per unit = 900.","Step 2: Number of units = x.","Step 3: Total profit = 900 × x.","Step 4: Therefore profit = 900x."],"options":[],"conceptId":"math_linear_programming_translating_per_unit_wording_into_coefficients","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Translating Per-Unit Wording into Coefficients"}', 0),
  (465, 132, 'A chair costs KSh 700 each. If y chairs are bought, write the cost.', 'text', 1, 'Cost = 700 × number of chairs.', '{"why":"The number 700 tells us the cost of each chair.","sol":"Step 1: Cost per chair = 700.\nStep 2: Number of chairs = y.\nStep 3: Total cost = 700 × y.\nStep 4: Therefore cost = 700y.","steps":["Step 1: Cost per chair = 700.","Step 2: Number of chairs = y.","Step 3: Total cost = 700 × y.","Step 4: Therefore cost = 700y."],"options":[],"conceptId":"math_linear_programming_translating_per_unit_wording_into_coefficients","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Translating Per-Unit Wording into Coefficients"}', 1),
  (466, 132, 'A shirt gives KSh 250 profit each and a trouser gives KSh 400 profit each. Let x be shirts and y be trousers. Form the profit function.', 'text', 1, 'Use 250 with x and 400 with y.', '{"why":"Each per-unit profit becomes the coefficient of its corresponding variable.","sol":"Step 1: Shirt profit = 250x.\nStep 2: Trouser profit = 400y.\nStep 3: Add them.\nStep 4: P = 250x + 400y.","steps":["Step 1: Shirt profit = 250x.","Step 2: Trouser profit = 400y.","Step 3: Add them.","Step 4: P = 250x + 400y."],"options":[],"conceptId":"math_linear_programming_translating_per_unit_wording_into_coefficients","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Translating Per-Unit Wording into Coefficients"}', 2),
  (467, 133, 'Find P = 400x + 200y at (3, 5).', 'text', 1, 'Use x = 3 and y = 5.', '{"why":"The coordinates replace x and y in the objective function.","sol":"Step 1: P = 400(3) + 200(5).\nStep 2: P = 1200 + 1000.\nStep 3: P = 2200.","steps":["Step 1: P = 400(3) + 200(5).","Step 2: P = 1200 + 1000.","Step 3: P = 2200."],"options":[],"conceptId":"math_linear_programming_evaluating_an_objective_function_at_a_point","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Evaluating an Objective Function at a Point"}', 0),
  (468, 133, 'Find C = 300x + 600y at (2, 4).', 'text', 1, 'Substitute x = 2 and y = 4.', '{"why":"The point tells us the values of x and y.","sol":"Step 1: C = 300(2) + 600(4).\nStep 2: C = 600 + 2400.\nStep 3: C = 3000.","steps":["Step 1: C = 300(2) + 600(4).","Step 2: C = 600 + 2400.","Step 3: C = 3000."],"options":[],"conceptId":"math_linear_programming_evaluating_an_objective_function_at_a_point","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Evaluating an Objective Function at a Point"}', 1),
  (469, 133, 'Find R = 800x + 500y at (4, 3).', 'text', 1, 'Replace x by 4 and y by 3.', '{"why":"Evaluating the objective means calculating its value at the given point.","sol":"Step 1: R = 800(4) + 500(3).\nStep 2: R = 3200 + 1500.\nStep 3: R = 4700.","steps":["Step 1: R = 800(4) + 500(3).","Step 2: R = 3200 + 1500.","Step 3: R = 4700."],"options":[],"conceptId":"math_linear_programming_evaluating_an_objective_function_at_a_point","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Evaluating an Objective Function at a Point"}', 2),
  (470, 134, 'P = 400x + 300y. Which point gives the greater profit: (2,3) or (4,1)?', 'text', 1, 'Calculate P at both points.', '{"why":"The second point produces the greater objective value.","sol":"Step 1: At (2,3): P = 400(2) + 300(3) = 800 + 900 = 1700.\nStep 2: At (4,1): P = 400(4) + 300(1) = 1600 + 300 = 1900.\nStep 3: Compare 1700 and 1900.\nStep 4: 1900 is greater.","steps":["Step 1: At (2,3): P = 400(2) + 300(3) = 800 + 900 = 1700.","Step 2: At (4,1): P = 400(4) + 300(1) = 1600 + 300 = 1900.","Step 3: Compare 1700 and 1900.","Step 4: 1900 is greater."],"options":[],"conceptId":"math_linear_programming_comparing_objective_values_at_two_points","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Comparing Objective Values at Two Points"}', 0),
  (471, 134, 'C = 500x + 200y. Which point gives the lower cost: (2,4) or (5,1)?', 'text', 1, 'Calculate both costs.', '{"why":"The first point gives the smaller cost.","sol":"Step 1: At (2,4): C = 500(2) + 200(4) = 1000 + 800 = 1800.\nStep 2: At (5,1): C = 500(5) + 200(1) = 2500 + 200 = 2700.\nStep 3: Compare 1800 and 2700.\nStep 4: 1800 is lower.","steps":["Step 1: At (2,4): C = 500(2) + 200(4) = 1000 + 800 = 1800.","Step 2: At (5,1): C = 500(5) + 200(1) = 2500 + 200 = 2700.","Step 3: Compare 1800 and 2700.","Step 4: 1800 is lower."],"options":[],"conceptId":"math_linear_programming_comparing_objective_values_at_two_points","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Comparing Objective Values at Two Points"}', 1),
  (472, 134, 'R = 300x + 400y. Compare (3,2) and (1,5).', 'text', 1, 'Evaluate R at each point.', '{"why":"The objective value at (1,5) is larger.","sol":"Step 1: At (3,2): R = 300(3) + 400(2) = 900 + 800 = 1700.\nStep 2: At (1,5): R = 300(1) + 400(5) = 300 + 2000 = 2300.\nStep 3: 2300 is greater than 1700.","steps":["Step 1: At (3,2): R = 300(3) + 400(2) = 900 + 800 = 1700.","Step 2: At (1,5): R = 300(1) + 400(5) = 300 + 2000 = 2300.","Step 3: 2300 is greater than 1700."],"options":[],"conceptId":"math_linear_programming_comparing_objective_values_at_two_points","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Comparing Objective Values at Two Points"}', 2),
  (473, 135, 'What does maximise P mean?', 'text', 1, 'Think about the word maximum.', '{"why":"Maximisation always seeks the largest objective value.","sol":"Step 1: Maximum means greatest.\nStep 2: P is the objective function.\nStep 3: Therefore maximise P means find the greatest possible value of P.","steps":["Step 1: Maximum means greatest.","Step 2: P is the objective function.","Step 3: Therefore maximise P means find the greatest possible value of P."],"options":[],"conceptId":"math_linear_programming_meaning_of_maximisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Meaning of Maximisation"}', 0),
  (474, 135, 'P = 400x + 200y. If two feasible points give P = 1800 and P = 2200, which value is preferred when maximising P?', 'text', 1, 'Choose the larger value.', '{"why":"Maximisation chooses the greater objective value.","sol":"Step 1: The values are 1800 and 2200.\nStep 2: 2200 is greater than 1800.\nStep 3: Therefore 2200 is preferred.","steps":["Step 1: The values are 1800 and 2200.","Step 2: 2200 is greater than 1800.","Step 3: Therefore 2200 is preferred."],"options":[],"conceptId":"math_linear_programming_meaning_of_maximisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Meaning of Maximisation"}', 1),
  (475, 135, 'A farmer wants maximum profit. If one feasible production plan gives KSh 8,000 and another gives KSh 9,500, which plan is better?', 'text', 1, 'Maximum profit means greater profit.', '{"why":"The objective is to obtain the greatest profit.","sol":"Step 1: Compare KSh 8,000 and KSh 9,500.\nStep 2: KSh 9,500 is greater.\nStep 3: Therefore the plan producing KSh 9,500 is better.","steps":["Step 1: Compare KSh 8,000 and KSh 9,500.","Step 2: KSh 9,500 is greater.","Step 3: Therefore the plan producing KSh 9,500 is better."],"options":[],"conceptId":"math_linear_programming_meaning_of_maximisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Meaning of Maximisation"}', 2),
  (476, 136, 'What does minimise C mean?', 'text', 1, 'Think about the word minimum.', '{"why":"Minimisation seeks the lowest objective value.","sol":"Step 1: Minimum means smallest.\nStep 2: C is the objective function.\nStep 3: Therefore minimise C means find the smallest possible value of C.","steps":["Step 1: Minimum means smallest.","Step 2: C is the objective function.","Step 3: Therefore minimise C means find the smallest possible value of C."],"options":[],"conceptId":"math_linear_programming_meaning_of_minimisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Meaning of Minimisation"}', 0),
  (477, 136, 'A company wants minimum cost. Two feasible plans cost KSh 3,500 and KSh 4,200. Which is preferred?', 'text', 1, 'Choose the lower cost.', '{"why":"Minimum cost means choosing the smaller cost.","sol":"Step 1: Compare 3500 and 4200.\nStep 2: 3500 is smaller.\nStep 3: Therefore the KSh 3,500 plan is preferred.","steps":["Step 1: Compare 3500 and 4200.","Step 2: 3500 is smaller.","Step 3: Therefore the KSh 3,500 plan is preferred."],"options":[],"conceptId":"math_linear_programming_meaning_of_minimisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Meaning of Minimisation"}', 1),
  (478, 136, 'Three feasible solutions give costs of KSh 7,000, KSh 5,500 and KSh 6,200. What is the minimum cost?', 'text', 1, 'Find the smallest number.', '{"why":"The minimum is the smallest objective value.","sol":"Step 1: Compare 7000, 5500 and 6200.\nStep 2: 5500 is the smallest.\nStep 3: Therefore the minimum cost is KSh 5,500.","steps":["Step 1: Compare 7000, 5500 and 6200.","Step 2: 5500 is the smallest.","Step 3: Therefore the minimum cost is KSh 5,500."],"options":[],"conceptId":"math_linear_programming_meaning_of_minimisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Meaning of Minimisation"}', 2),
  (479, 137, 'Three feasible plans give profits of KSh 4,000, KSh 6,000 and KSh 5,000. Which is optimal when profit is maximized?', 'text', 1, 'Choose the greatest profit.', '{"why":"Maximum profit requires the greatest feasible profit.","sol":"Step 1: Compare 4000, 6000 and 5000.\nStep 2: 6000 is the greatest.\nStep 3: Therefore the plan giving KSh 6,000 is optimal.","steps":["Step 1: Compare 4000, 6000 and 5000.","Step 2: 6000 is the greatest.","Step 3: Therefore the plan giving KSh 6,000 is optimal."],"options":[],"conceptId":"math_linear_programming_meaning_of_an_optimal_solution","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Meaning of an Optimal Solution"}', 0),
  (480, 137, 'Three feasible plans cost KSh 8,000, KSh 6,500 and KSh 7,200. Which is optimal when cost is minimized?', 'text', 1, 'Choose the smallest cost.', '{"why":"Minimum cost requires the smallest feasible cost.","sol":"Step 1: Compare 8000, 6500 and 7200.\nStep 2: 6500 is the smallest.\nStep 3: Therefore the KSh 6,500 plan is optimal.","steps":["Step 1: Compare 8000, 6500 and 7200.","Step 2: 6500 is the smallest.","Step 3: Therefore the KSh 6,500 plan is optimal."],"options":[],"conceptId":"math_linear_programming_meaning_of_an_optimal_solution","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Meaning of an Optimal Solution"}', 1),
  (481, 137, 'If two feasible points give objective values 3,200 and 3,800, which is optimal when maximizing?', 'text', 1, 'Maximum means greatest.', '{"why":"The greater objective value is preferred during maximisation.","sol":"Step 1: Compare 3200 and 3800.\nStep 2: 3800 is greater.\nStep 3: Therefore the point giving 3800 is optimal.","steps":["Step 1: Compare 3200 and 3800.","Step 2: 3800 is greater.","Step 3: Therefore the point giving 3800 is optimal."],"options":[],"conceptId":"math_linear_programming_meaning_of_an_optimal_solution","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Meaning of an Optimal Solution"}', 2),
  (482, 138, 'Why do we test corner points in a linear programming problem?', 'text', 1, 'Think about where the optimum occurs for a linear objective.', '{"why":"The corner-point method allows us to find the optimum without checking every feasible point.","sol":"Step 1: The feasible region contains many possible points.\nStep 2: The objective function is linear.\nStep 3: When an optimum exists, its best value occurs at a corner point.\nStep 4: Therefore we test the corner points.","steps":["Step 1: The feasible region contains many possible points.","Step 2: The objective function is linear.","Step 3: When an optimum exists, its best value occurs at a corner point.","Step 4: Therefore we test the corner points."],"options":[],"conceptId":"math_linear_programming_why_corner_points_are_tested","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Why Corner Points Are Tested"}', 0),
  (483, 138, 'A feasible region has four corner points. Should a point outside the region be tested as a possible optimum?', 'text', 1, 'First ask whether the point is feasible.', '{"why":"Only feasible points can be considered as solutions.","sol":"Step 1: An optimum must satisfy all constraints.\nStep 2: A point outside the feasible region violates at least one constraint.\nStep 3: Therefore it cannot be an allowed solution.","steps":["Step 1: An optimum must satisfy all constraints.","Step 2: A point outside the feasible region violates at least one constraint.","Step 3: Therefore it cannot be an allowed solution."],"options":[],"conceptId":"math_linear_programming_why_corner_points_are_tested","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Why Corner Points Are Tested"}', 1),
  (484, 138, 'A feasible region has corners A, B, C and D. What points should normally be tested for the optimum?', 'text', 1, 'Use the corner-point method.', '{"why":"The corner points are the candidates for the optimum.","sol":"Step 1: The feasible region has four corner points.\nStep 2: The objective should be evaluated at those corners.\nStep 3: Therefore test A, B, C and D.","steps":["Step 1: The feasible region has four corner points.","Step 2: The objective should be evaluated at those corners.","Step 3: Therefore test A, B, C and D."],"options":[],"conceptId":"math_linear_programming_why_corner_points_are_tested","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Why Corner Points Are Tested"}', 2),
  (485, 139, 'P = 300x + 200y. Find P at (4,2).', 'text', 1, 'Substitute x = 4 and y = 2.', '{"why":"The coordinates are substituted into the objective function.","sol":"Step 1: P = 300(4) + 200(2).\nStep 2: P = 1200 + 400.\nStep 3: P = 1600.","steps":["Step 1: P = 300(4) + 200(2).","Step 2: P = 1200 + 400.","Step 3: P = 1600."],"options":[],"conceptId":"math_linear_programming_evaluating_the_objective_at_every_corner_point","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Evaluating the Objective at Every Corner Point"}', 0),
  (486, 139, 'C = 500x + 100y. Find C at (3,5).', 'text', 1, 'Use x = 3 and y = 5.', '{"why":"Evaluating a corner means calculating the objective value at that point.","sol":"Step 1: C = 500(3) + 100(5).\nStep 2: C = 1500 + 500.\nStep 3: C = 2000.","steps":["Step 1: C = 500(3) + 100(5).","Step 2: C = 1500 + 500.","Step 3: C = 2000."],"options":[],"conceptId":"math_linear_programming_evaluating_the_objective_at_every_corner_point","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Evaluating the Objective at Every Corner Point"}', 1),
  (487, 139, 'P = 600x + 400y. Find P at (2,3).', 'text', 1, 'Replace x by 2 and y by 3.', '{"why":"The point gives the values of x and y used in the objective.","sol":"Step 1: P = 600(2) + 400(3).\nStep 2: P = 1200 + 1200.\nStep 3: P = 2400.","steps":["Step 1: P = 600(2) + 400(3).","Step 2: P = 1200 + 1200.","Step 3: P = 2400."],"options":[],"conceptId":"math_linear_programming_evaluating_the_objective_at_every_corner_point","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Evaluating the Objective at Every Corner Point"}', 2),
  (488, 140, 'The objective values at four corners are 900, 1400, 1800 and 1200. What is the maximum?', 'text', 1, 'Choose the greatest number.', '{"why":"Maximum means greatest.","sol":"Step 1: Compare 900, 1400, 1800 and 1200.\nStep 2: 1800 is the greatest.\nStep 3: Therefore the maximum is 1800.","steps":["Step 1: Compare 900, 1400, 1800 and 1200.","Step 2: 1800 is the greatest.","Step 3: Therefore the maximum is 1800."],"options":[],"conceptId":"math_linear_programming_finding_the_maximum_from_corner_values","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Finding the Maximum from Corner Values"}', 0),
  (489, 140, 'A profit function gives 2,100, 2,700 and 2,400 at three feasible corners. Which gives maximum profit?', 'text', 1, 'Choose the largest profit.', '{"why":"The greatest profit is the maximum.","sol":"Step 1: Compare 2100, 2700 and 2400.\nStep 2: 2700 is greatest.\nStep 3: Therefore the second corner gives maximum profit.","steps":["Step 1: Compare 2100, 2700 and 2400.","Step 2: 2700 is greatest.","Step 3: Therefore the second corner gives maximum profit."],"options":[],"conceptId":"math_linear_programming_finding_the_maximum_from_corner_values","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Finding the Maximum from Corner Values"}', 1),
  (490, 140, 'The corner values of P are 3,000, 2,500, 3,800 and 3,200. Which value is the maximum?', 'text', 1, 'Find the largest value.', '{"why":"Maximization selects the greatest objective value.","sol":"Step 1: Compare all four values.\nStep 2: 3800 is the greatest.\nStep 3: Therefore the maximum value is 3800.","steps":["Step 1: Compare all four values.","Step 2: 3800 is the greatest.","Step 3: Therefore the maximum value is 3800."],"options":[],"conceptId":"math_linear_programming_finding_the_maximum_from_corner_values","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Finding the Maximum from Corner Values"}', 2),
  (491, 141, 'The objective values at four corners are 2,000, 1,500, 1,800 and 2,200. What is the minimum?', 'text', 1, 'Choose the smallest value.', '{"why":"Minimum means smallest.","sol":"Step 1: Compare 2000, 1500, 1800 and 2200.\nStep 2: 1500 is the smallest.\nStep 3: Therefore the minimum is 1500.","steps":["Step 1: Compare 2000, 1500, 1800 and 2200.","Step 2: 1500 is the smallest.","Step 3: Therefore the minimum is 1500."],"options":[],"conceptId":"math_linear_programming_finding_the_minimum_from_corner_values","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Finding the Minimum from Corner Values"}', 0),
  (492, 141, 'Three feasible points give costs of KSh 4,000, KSh 3,200 and KSh 3,700. Which gives minimum cost?', 'text', 1, 'Choose the lowest cost.', '{"why":"Minimum cost means choosing the smallest feasible cost.","sol":"Step 1: Compare 4000, 3200 and 3700.\nStep 2: 3200 is the smallest.\nStep 3: Therefore the second point gives minimum cost.","steps":["Step 1: Compare 4000, 3200 and 3700.","Step 2: 3200 is the smallest.","Step 3: Therefore the second point gives minimum cost."],"options":[],"conceptId":"math_linear_programming_finding_the_minimum_from_corner_values","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Finding the Minimum from Corner Values"}', 1),
  (493, 141, 'The corner values of C are 700, 900, 650 and 800. Which is the minimum?', 'text', 1, 'Find the smallest number.', '{"why":"Minimization selects the smallest objective value.","sol":"Step 1: Compare all four values.\nStep 2: 650 is the smallest.\nStep 3: Therefore the minimum is 650.","steps":["Step 1: Compare all four values.","Step 2: 650 is the smallest.","Step 3: Therefore the minimum is 650."],"options":[],"conceptId":"math_linear_programming_finding_the_minimum_from_corner_values","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Finding the Minimum from Corner Values"}', 2),
  (494, 142, 'A maximum objective value of 5,000 occurs at (4,3). What is the optimal point?', 'text', 1, 'The optimal point is the point where the maximum occurs.', '{"why":"The optimal point identifies the variable values producing the best result.","sol":"Step 1: The maximum value is 5000.\nStep 2: It occurs at (4,3).\nStep 3: Therefore the optimal point is (4,3).","steps":["Step 1: The maximum value is 5000.","Step 2: It occurs at (4,3).","Step 3: Therefore the optimal point is (4,3)."],"options":[],"conceptId":"math_linear_programming_finding_the_optimal_point_and_optimal_value","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Finding the Optimal Point and Optimal Value"}', 0),
  (495, 142, 'A minimum cost of KSh 2,400 occurs at (2,5). What is the minimum cost?', 'text', 1, 'The optimal value is the value of the objective.', '{"why":"The optimal value is the minimum value of the objective function.","sol":"Step 1: The problem states that the minimum cost is 2400.\nStep 2: Therefore the optimal value is KSh 2,400.","steps":["Step 1: The problem states that the minimum cost is 2400.","Step 2: Therefore the optimal value is KSh 2,400."],"options":[],"conceptId":"math_linear_programming_finding_the_optimal_point_and_optimal_value","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Finding the Optimal Point and Optimal Value"}', 1),
  (496, 142, 'Maximum profit is KSh 8,000 at (5,2). State both the optimal point and optimal value.', 'text', 1, 'Give both pieces of information.', '{"why":"A complete optimisation answer identifies both the quantities and the resulting objective value.","sol":"Step 1: The point is (5,2).\nStep 2: The maximum profit is KSh 8,000.\nStep 3: Therefore report both.","steps":["Step 1: The point is (5,2).","Step 2: The maximum profit is KSh 8,000.","Step 3: Therefore report both."],"options":[],"conceptId":"math_linear_programming_finding_the_optimal_point_and_optimal_value","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Finding the Optimal Point and Optimal Value"}', 2),
  (497, 143, 'P = 400x + 300y. The corner points are (0,0), (5,0), (3,4), (0,4). Which point gives the maximum P?', 'text', 1, 'Evaluate P at all four points.', '{"why":"The point (3,4) gives the greatest objective value.","sol":"Step 1: At (0,0): P = 0.\nStep 2: At (5,0): P = 400(5) = 2000.\nStep 3: At (3,4): P = 400(3) + 300(4) = 1200 + 1200 = 2400.\nStep 4: At (0,4): P = 1200.\nStep 5: The greatest value is 2400.","steps":["Step 1: At (0,0): P = 0.","Step 2: At (5,0): P = 400(5) = 2000.","Step 3: At (3,4): P = 400(3) + 300(4) = 1200 + 1200 = 2400.","Step 4: At (0,4): P = 1200.","Step 5: The greatest value is 2400."],"options":[],"conceptId":"math_linear_programming_complete_corner_point_maximisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Complete Corner-Point Maximisation"}', 0),
  (498, 143, 'P = 600x + 200y. The corners are (0,0), (4,0), (3,2), (0,3). Find the maximum P.', 'text', 1, 'Calculate P at every corner.', '{"why":"The corner (4,0) gives the greatest objective value.","sol":"Step 1: At (0,0): P = 0.\nStep 2: At (4,0): P = 600(4) = 2400.\nStep 3: At (3,2): P = 600(3) + 200(2) = 1800 + 400 = 2200.\nStep 4: At (0,3): P = 600.\nStep 5: The greatest value is 2400.","steps":["Step 1: At (0,0): P = 0.","Step 2: At (4,0): P = 600(4) = 2400.","Step 3: At (3,2): P = 600(3) + 200(2) = 1800 + 400 = 2200.","Step 4: At (0,3): P = 600.","Step 5: The greatest value is 2400."],"options":[],"conceptId":"math_linear_programming_complete_corner_point_maximisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Complete Corner-Point Maximisation"}', 1),
  (499, 143, 'P = 300x + 500y. The corners are (0,0), (6,0), (4,3), (0,5). Find the optimal point and maximum P.', 'text', 1, 'Evaluate P at all four corners.', '{"why":"The optimal point is the feasible corner producing the greatest objective value.","sol":"Step 1: At (0,0): P = 0.\nStep 2: At (6,0): P = 300(6) = 1800.\nStep 3: At (4,3): P = 300(4) + 500(3) = 1200 + 1500 = 2700.\nStep 4: At (0,5): P = 500(5) = 2500.\nStep 5: The greatest value is 2700.\nStep 6: Therefore the optimal point is (4,3).","steps":["Step 1: At (0,0): P = 0.","Step 2: At (6,0): P = 300(6) = 1800.","Step 3: At (4,3): P = 300(4) + 500(3) = 1200 + 1500 = 2700.","Step 4: At (0,5): P = 500(5) = 2500.","Step 5: The greatest value is 2700.","Step 6: Therefore the optimal point is (4,3)."],"options":[],"conceptId":"math_linear_programming_complete_corner_point_maximisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Complete Corner-Point Maximisation"}', 2),
  (500, 144, 'C = 300x + 200y. The corner points are (1,1), (4,1), (3,3), (1,4). Find the minimum cost.', 'text', 1, 'Evaluate C at every corner and choose the smallest.', '{"why":"The point (1,1) produces the smallest feasible cost.","sol":"Step 1: At (1,1): C = 300 + 200 = 500.\nStep 2: At (4,1): C = 1200 + 200 = 1400.\nStep 3: At (3,3): C = 900 + 600 = 1500.\nStep 4: At (1,4): C = 300 + 800 = 1100.\nStep 5: The smallest value is 500.","steps":["Step 1: At (1,1): C = 300 + 200 = 500.","Step 2: At (4,1): C = 1200 + 200 = 1400.","Step 3: At (3,3): C = 900 + 600 = 1500.","Step 4: At (1,4): C = 300 + 800 = 1100.","Step 5: The smallest value is 500."],"options":[],"conceptId":"math_linear_programming_complete_corner_point_minimisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Complete Corner-Point Minimisation"}', 0);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (501, 144, 'C = 500x + 400y. The corners are (1,2), (4,2), (3,5). Which gives the minimum?', 'text', 1, 'Calculate all three costs.', '{"why":"The first point gives the smallest objective value.","sol":"Step 1: At (1,2): C = 500 + 800 = 1300.\nStep 2: At (4,2): C = 2000 + 800 = 2800.\nStep 3: At (3,5): C = 1500 + 2000 = 3500.\nStep 4: The smallest value is 1300.","steps":["Step 1: At (1,2): C = 500 + 800 = 1300.","Step 2: At (4,2): C = 2000 + 800 = 2800.","Step 3: At (3,5): C = 1500 + 2000 = 3500.","Step 4: The smallest value is 1300."],"options":[],"conceptId":"math_linear_programming_complete_corner_point_minimisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Complete Corner-Point Minimisation"}', 1),
  (502, 144, 'C = 200x + 600y. The corners are (2,1), (5,1), (4,3), (2,4). Find the optimal point and minimum C.', 'text', 1, 'Evaluate C at each corner.', '{"why":"The optimal point is the feasible corner with the smallest objective value.","sol":"Step 1: At (2,1): C = 200(2) + 600(1) = 400 + 600 = 1000.\nStep 2: At (5,1): C = 1000 + 600 = 1600.\nStep 3: At (4,3): C = 800 + 1800 = 2600.\nStep 4: At (2,4): C = 400 + 2400 = 2800.\nStep 5: The smallest value is 1000.","steps":["Step 1: At (2,1): C = 200(2) + 600(1) = 400 + 600 = 1000.","Step 2: At (5,1): C = 1000 + 600 = 1600.","Step 3: At (4,3): C = 800 + 1800 = 2600.","Step 4: At (2,4): C = 400 + 2400 = 2800.","Step 5: The smallest value is 1000."],"options":[],"conceptId":"math_linear_programming_complete_corner_point_minimisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Complete Corner-Point Minimisation"}', 2),
  (503, 145, 'A feasible region has corners (0,0), (5,0), (3,4), (0,6). P = 300x + 400y. Find the maximum P.', 'text', 1, 'Evaluate P at all four corners.', '{"why":"The corner (3,4) produces the greatest objective value.","sol":"Step 1: At (0,0): P = 0.\nStep 2: At (5,0): P = 300(5) = 1500.\nStep 3: At (3,4): P = 300(3) + 400(4) = 900 + 1600 = 2500.\nStep 4: At (0,6): P = 400(6) = 2400.\nStep 5: The greatest value is 2500.","steps":["Step 1: At (0,0): P = 0.","Step 2: At (5,0): P = 300(5) = 1500.","Step 3: At (3,4): P = 300(3) + 400(4) = 900 + 1600 = 2500.","Step 4: At (0,6): P = 400(6) = 2400.","Step 5: The greatest value is 2500."],"options":[],"conceptId":"math_linear_programming_complete_linear_programming_solution","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Complete Linear Programming Solution"}', 0),
  (504, 145, 'A feasible region has corners (1,1), (5,1), (4,3), (1,4). C = 200x + 300y. Find the minimum C.', 'text', 1, 'Evaluate C at each corner.', '{"why":"The point (1,1) gives the smallest feasible cost.","sol":"Step 1: At (1,1): C = 200 + 300 = 500.\nStep 2: At (5,1): C = 1000 + 300 = 1300.\nStep 3: At (4,3): C = 800 + 900 = 1700.\nStep 4: At (1,4): C = 200 + 1200 = 1400.\nStep 5: The smallest value is 500.","steps":["Step 1: At (1,1): C = 200 + 300 = 500.","Step 2: At (5,1): C = 1000 + 300 = 1300.","Step 3: At (4,3): C = 800 + 900 = 1700.","Step 4: At (1,4): C = 200 + 1200 = 1400.","Step 5: The smallest value is 500."],"options":[],"conceptId":"math_linear_programming_complete_linear_programming_solution","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Complete Linear Programming Solution"}', 1),
  (505, 145, 'Why must you check every relevant corner point before declaring the maximum or minimum?', 'text', 1, 'Could an unchecked corner have a better value?', '{"why":"Checking every relevant corner prevents us from missing the best feasible solution.","sol":"Step 1: Each corner is a candidate for the optimum.\nStep 2: An unchecked corner could have a greater value when maximizing.\nStep 3: It could also have a smaller value when minimizing.\nStep 4: Therefore all relevant corner points must be evaluated.","steps":["Step 1: Each corner is a candidate for the optimum.","Step 2: An unchecked corner could have a greater value when maximizing.","Step 3: It could also have a smaller value when minimizing.","Step 4: Therefore all relevant corner points must be evaluated."],"options":[],"conceptId":"math_linear_programming_complete_linear_programming_solution","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Complete Linear Programming Solution"}', 2),
  (506, 146, 'A shop sells shirts and trousers. Let x represent shirts and y represent trousers. What does x represent?', 'text', 1, 'Read the variable definition.', '{"why":"A decision variable must have a clearly defined meaning.","sol":"Step 1: The problem defines x as the number of shirts.\nStep 2: Therefore x represents the number of shirts.","steps":["Step 1: The problem defines x as the number of shirts.","Step 2: Therefore x represents the number of shirts."],"options":[],"conceptId":"math_linear_programming_defining_decision_variables","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Defining Decision Variables"}', 0),
  (507, 146, 'A farmer produces maize and beans. Define x as maize and y as beans.', 'text', 1, 'State exactly what each variable counts.', '{"why":"Clear variable definitions make the later mathematical model understandable.","sol":"Step 1: Let x represent the number of bags of maize.\nStep 2: Let y represent the number of bags of beans.","steps":["Step 1: Let x represent the number of bags of maize.","Step 2: Let y represent the number of bags of beans."],"options":[],"conceptId":"math_linear_programming_defining_decision_variables","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Defining Decision Variables"}', 1),
  (508, 146, 'A factory makes tables and chairs. What could x and y represent?', 'text', 1, 'Use the two products as the two variables.', '{"why":"The variables represent the quantities the factory chooses to produce.","sol":"Step 1: Let x represent the number of tables.\nStep 2: Let y represent the number of chairs.","steps":["Step 1: Let x represent the number of tables.","Step 2: Let y represent the number of chairs."],"options":[],"conceptId":"math_linear_programming_defining_decision_variables","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Defining Decision Variables"}', 2),
  (509, 147, 'A farmer can plant at most 40 acres. If x is the number of acres planted, write the inequality.', 'text', 1, 'At most means no more than.', '{"why":"At most means the quantity cannot exceed the stated limit.","sol":"Step 1: The maximum allowed is 40.\nStep 2: The planted area can be 40 or less.\nStep 3: Therefore x ≤ 40.","steps":["Step 1: The maximum allowed is 40.","Step 2: The planted area can be 40 or less.","Step 3: Therefore x ≤ 40."],"options":[],"conceptId":"math_linear_programming_translating_at_most_into_an_inequality","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Translating ''At Most'' into an Inequality"}', 0),
  (510, 147, 'A truck can carry at most 500 kg. If x kg is loaded, write the inequality.', 'text', 1, 'Can the load be greater than 500 kg?', '{"why":"The load must not exceed 500 kg.","sol":"Step 1: The maximum load is 500 kg.\nStep 2: The load may be less than or equal to 500 kg.\nStep 3: Therefore x ≤ 500.","steps":["Step 1: The maximum load is 500 kg.","Step 2: The load may be less than or equal to 500 kg.","Step 3: Therefore x ≤ 500."],"options":[],"conceptId":"math_linear_programming_translating_at_most_into_an_inequality","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Translating ''At Most'' into an Inequality"}', 1),
  (511, 147, 'A school has at most 60 computers. If x and y are two types of computers, write the total constraint.', 'text', 1, 'Add the two quantities.', '{"why":"The total is limited to 60 or fewer.","sol":"Step 1: The total number of computers is x + y.\nStep 2: The total cannot exceed 60.\nStep 3: Therefore x + y ≤ 60.","steps":["Step 1: The total number of computers is x + y.","Step 2: The total cannot exceed 60.","Step 3: Therefore x + y ≤ 60."],"options":[],"conceptId":"math_linear_programming_translating_at_most_into_an_inequality","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Translating ''At Most'' into an Inequality"}', 2),
  (512, 148, 'A factory must produce at least 50 units. If x is the number produced, write the inequality.', 'text', 1, 'At least means no less than.', '{"why":"At least means the quantity must not fall below the stated amount.","sol":"Step 1: The required minimum is 50.\nStep 2: The number produced can be 50 or more.\nStep 3: Therefore x ≥ 50.","steps":["Step 1: The required minimum is 50.","Step 2: The number produced can be 50 or more.","Step 3: Therefore x ≥ 50."],"options":[],"conceptId":"math_linear_programming_translating_at_least_into_an_inequality","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Translating ''At Least'' into an Inequality"}', 0),
  (513, 148, 'A farmer must produce at least 100 bags of maize and beans combined. If x and y are the quantities, write the inequality.', 'text', 1, 'Add the two quantities.', '{"why":"The combined production must be 100 or greater.","sol":"Step 1: Total production = x + y.\nStep 2: The total must be at least 100.\nStep 3: Therefore x + y ≥ 100.","steps":["Step 1: Total production = x + y.","Step 2: The total must be at least 100.","Step 3: Therefore x + y ≥ 100."],"options":[],"conceptId":"math_linear_programming_translating_at_least_into_an_inequality","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Translating ''At Least'' into an Inequality"}', 1),
  (514, 148, 'A school requires at least 20 computers. If x represents the number of computers, write the inequality.', 'text', 1, 'The number cannot be below 20.', '{"why":"At least describes a lower limit.","sol":"Step 1: Minimum required = 20.\nStep 2: The number may be 20 or more.\nStep 3: Therefore x ≥ 20.","steps":["Step 1: Minimum required = 20.","Step 2: The number may be 20 or more.","Step 3: Therefore x ≥ 20."],"options":[],"conceptId":"math_linear_programming_translating_at_least_into_an_inequality","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Translating ''At Least'' into an Inequality"}', 2),
  (515, 149, 'A table uses 4 hours and a chair uses 2 hours. There are at most 40 hours available. Form the constraint.', 'text', 1, 'Total time used must not exceed 40.', '{"why":"The total machine time cannot exceed the available 40 hours.","sol":"Step 1: Tables use 4x hours.\nStep 2: Chairs use 2y hours.\nStep 3: Total = 4x + 2y.\nStep 4: At most 40 means ≤ 40.\nStep 5: Therefore 4x + 2y ≤ 40.","steps":["Step 1: Tables use 4x hours.","Step 2: Chairs use 2y hours.","Step 3: Total = 4x + 2y.","Step 4: At most 40 means ≤ 40.","Step 5: Therefore 4x + 2y ≤ 40."],"options":[],"conceptId":"math_linear_programming_translating_a_resource_limit_into_a_constraint","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Translating a Resource Limit into a Constraint"}', 0),
  (516, 149, 'A product A uses 3 kg and product B uses 5 kg. There are 90 kg available. Form the constraint.', 'text', 1, 'Multiply each material use by its quantity.', '{"why":"The total material used must not exceed the available material.","sol":"Step 1: A uses 3x kg.\nStep 2: B uses 5y kg.\nStep 3: Total = 3x + 5y.\nStep 4: The total cannot exceed 90 kg.\nStep 5: Therefore 3x + 5y ≤ 90.","steps":["Step 1: A uses 3x kg.","Step 2: B uses 5y kg.","Step 3: Total = 3x + 5y.","Step 4: The total cannot exceed 90 kg.","Step 5: Therefore 3x + 5y ≤ 90."],"options":[],"conceptId":"math_linear_programming_translating_a_resource_limit_into_a_constraint","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Translating a Resource Limit into a Constraint"}', 1),
  (517, 149, 'Product A costs KSh 100 and product B costs KSh 250. The budget is KSh 5,000. Form the constraint.', 'text', 1, 'Total cost must not exceed the budget.', '{"why":"Production spending cannot exceed the available budget.","sol":"Step 1: Cost of A = 100x.\nStep 2: Cost of B = 250y.\nStep 3: Total cost = 100x + 250y.\nStep 4: The budget is 5000.\nStep 5: Therefore 100x + 250y ≤ 5000.","steps":["Step 1: Cost of A = 100x.","Step 2: Cost of B = 250y.","Step 3: Total cost = 100x + 250y.","Step 4: The budget is 5000.","Step 5: Therefore 100x + 250y ≤ 5000."],"options":[],"conceptId":"math_linear_programming_translating_a_resource_limit_into_a_constraint","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Translating a Resource Limit into a Constraint"}', 2),
  (518, 150, 'A factory must produce at least 30 items. If x is the number produced, write the constraint.', 'text', 1, 'At least means ≥.', '{"why":"The production requirement gives a lower limit.","sol":"Step 1: The minimum is 30.\nStep 2: Production must be 30 or greater.\nStep 3: Therefore x ≥ 30.","steps":["Step 1: The minimum is 30.","Step 2: Production must be 30 or greater.","Step 3: Therefore x ≥ 30."],"options":[],"conceptId":"math_linear_programming_translating_a_production_requirement_into_a_constraint","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Translating a Production Requirement into a Constraint"}', 0),
  (519, 150, 'A factory can produce at most 80 items. If x and y are two products, write the constraint.', 'text', 1, 'At most means ≤.', '{"why":"The total production cannot exceed 80.","sol":"Step 1: Total production = x + y.\nStep 2: The maximum allowed is 80.\nStep 3: Therefore x + y ≤ 80.","steps":["Step 1: Total production = x + y.","Step 2: The maximum allowed is 80.","Step 3: Therefore x + y ≤ 80."],"options":[],"conceptId":"math_linear_programming_translating_a_production_requirement_into_a_constraint","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Translating a Production Requirement into a Constraint"}', 1),
  (520, 150, 'A company must produce at least 100 units of two products combined. Write the constraint.', 'text', 1, 'Add the quantities first.', '{"why":"The company must reach a minimum total production of 100.","sol":"Step 1: Let x and y be the quantities.\nStep 2: Combined production = x + y.\nStep 3: At least 100 means ≥ 100.\nStep 4: Therefore x + y ≥ 100.","steps":["Step 1: Let x and y be the quantities.","Step 2: Combined production = x + y.","Step 3: At least 100 means ≥ 100.","Step 4: Therefore x + y ≥ 100."],"options":[],"conceptId":"math_linear_programming_translating_a_production_requirement_into_a_constraint","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Translating a Production Requirement into a Constraint"}', 2),
  (521, 151, 'If x represents the number of tables produced, what condition must x satisfy?', 'text', 1, 'Can the number of tables be negative?', '{"why":"A quantity being counted cannot be negative.","sol":"Step 1: The number of tables cannot be negative.\nStep 2: Therefore x must be zero or positive.\nStep 3: So x ≥ 0.","steps":["Step 1: The number of tables cannot be negative.","Step 2: Therefore x must be zero or positive.","Step 3: So x ≥ 0."],"options":[],"conceptId":"math_linear_programming_translating_non_negativity_conditions","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Translating Non-Negativity Conditions"}', 0),
  (522, 151, 'If x represents shirts and y represents trousers, write the non-negativity constraints.', 'text', 1, 'Write one condition for each variable.', '{"why":"Both decision variables represent quantities.","sol":"Step 1: The number of shirts cannot be negative: x ≥ 0.\nStep 2: The number of trousers cannot be negative: y ≥ 0.","steps":["Step 1: The number of shirts cannot be negative: x ≥ 0.","Step 2: The number of trousers cannot be negative: y ≥ 0."],"options":[],"conceptId":"math_linear_programming_translating_non_negativity_conditions","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Translating Non-Negativity Conditions"}', 1),
  (523, 151, 'Why is x ≥ 0 normally included in a production model?', 'text', 1, 'Think about what x represents.', '{"why":"Non-negativity keeps the mathematical model consistent with the meaning of the variables.","sol":"Step 1: x represents a quantity such as products produced.\nStep 2: A negative quantity has no physical meaning here.\nStep 3: Therefore x must be zero or positive.","steps":["Step 1: x represents a quantity such as products produced.","Step 2: A negative quantity has no physical meaning here.","Step 3: Therefore x must be zero or positive."],"options":[],"conceptId":"math_linear_programming_translating_non_negativity_conditions","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Translating Non-Negativity Conditions"}', 2),
  (524, 152, 'A table gives KSh 600 profit and a chair gives KSh 400 profit. Let x be tables and y be chairs. Form the profit function.', 'text', 1, 'Multiply each unit profit by its quantity.', '{"why":"Each unit profit becomes the coefficient of its variable.","sol":"Step 1: Table profit = 600x.\nStep 2: Chair profit = 400y.\nStep 3: Total profit = 600x + 400y.","steps":["Step 1: Table profit = 600x.","Step 2: Chair profit = 400y.","Step 3: Total profit = 600x + 400y."],"options":[],"conceptId":"math_linear_programming_translating_profit_wording_into_an_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Translating Profit Wording into an Objective Function"}', 0),
  (525, 152, 'A farmer earns KSh 1,200 per maize bag and KSh 900 per bean bag. Form the objective function for maximum profit.', 'text', 1, 'Let x be maize and y be beans.', '{"why":"The function represents total profit and the aim is to make it as large as possible.","sol":"Step 1: Maize profit = 1200x.\nStep 2: Bean profit = 900y.\nStep 3: Total profit = 1200x + 900y.\nStep 4: The word maximum means this function is maximized.","steps":["Step 1: Maize profit = 1200x.","Step 2: Bean profit = 900y.","Step 3: Total profit = 1200x + 900y.","Step 4: The word maximum means this function is maximized."],"options":[],"conceptId":"math_linear_programming_translating_profit_wording_into_an_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Translating Profit Wording into an Objective Function"}', 1),
  (526, 152, 'A bakery earns KSh 30 per loaf and KSh 80 per cake. Write the objective for maximum profit.', 'text', 1, 'Use x for loaves and y for cakes.', '{"why":"The objective function adds the profit from both products.","sol":"Step 1: Loaf profit = 30x.\nStep 2: Cake profit = 80y.\nStep 3: Total profit = 30x + 80y.\nStep 4: Maximum profit means maximize P.","steps":["Step 1: Loaf profit = 30x.","Step 2: Cake profit = 80y.","Step 3: Total profit = 30x + 80y.","Step 4: Maximum profit means maximize P."],"options":[],"conceptId":"math_linear_programming_translating_profit_wording_into_an_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Translating Profit Wording into an Objective Function"}', 2),
  (527, 153, 'Material A costs KSh 200 per unit and B costs KSh 400 per unit. Form the cost function.', 'text', 1, 'Multiply each cost per unit by its quantity.', '{"why":"The total cost is the sum of the two individual costs.","sol":"Step 1: A costs 200x.\nStep 2: B costs 400y.\nStep 3: Total cost = 200x + 400y.","steps":["Step 1: A costs 200x.","Step 2: B costs 400y.","Step 3: Total cost = 200x + 400y."],"options":[],"conceptId":"math_linear_programming_translating_cost_wording_into_an_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Translating Cost Wording into an Objective Function"}', 0),
  (528, 153, 'A company wants the lowest cost. If C = 500x + 300y, what is the objective?', 'text', 1, 'Lowest means minimum.', '{"why":"Minimum cost means finding the smallest possible value of C.","sol":"Step 1: C represents total cost.\nStep 2: The company wants the lowest cost.\nStep 3: Therefore C must be minimized.","steps":["Step 1: C represents total cost.","Step 2: The company wants the lowest cost.","Step 3: Therefore C must be minimized."],"options":[],"conceptId":"math_linear_programming_translating_cost_wording_into_an_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Translating Cost Wording into an Objective Function"}', 1),
  (529, 153, 'A notebook costs KSh 40 and a textbook KSh 200. If x notebooks and y textbooks are bought, write the objective for minimum cost.', 'text', 1, 'First form total cost.', '{"why":"The objective combines the cost of both types of items.","sol":"Step 1: Notebook cost = 40x.\nStep 2: Textbook cost = 200y.\nStep 3: Total cost = 40x + 200y.\nStep 4: Minimum cost means minimize C.","steps":["Step 1: Notebook cost = 40x.","Step 2: Textbook cost = 200y.","Step 3: Total cost = 40x + 200y.","Step 4: Minimum cost means minimize C."],"options":[],"conceptId":"math_linear_programming_translating_cost_wording_into_an_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Translating Cost Wording into an Objective Function"}', 2),
  (530, 154, 'A factory makes tables and chairs. Let x be tables and y be chairs. Each table uses 2 hours and each chair 3 hours. There are at most 30 hours. Write the resource constraint.', 'text', 1, 'Total hours must not exceed 30.', '{"why":"The constraint represents the limited labour time.","sol":"Step 1: Tables use 2x hours.\nStep 2: Chairs use 3y hours.\nStep 3: Total = 2x + 3y.\nStep 4: At most 30 means ≤ 30.\nStep 5: Therefore 2x + 3y ≤ 30.","steps":["Step 1: Tables use 2x hours.","Step 2: Chairs use 3y hours.","Step 3: Total = 2x + 3y.","Step 4: At most 30 means ≤ 30.","Step 5: Therefore 2x + 3y ≤ 30."],"options":[],"conceptId":"math_linear_programming_building_a_complete_linear_programming_model","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Building a Complete Linear Programming Model"}', 0),
  (531, 154, 'A business earns KSh 400 per table and KSh 600 per chair. Write the profit objective.', 'text', 1, 'Multiply each profit by its quantity.', '{"why":"The objective represents total profit.","sol":"Step 1: Table profit = 400x.\nStep 2: Chair profit = 600y.\nStep 3: Total profit = 400x + 600y.\nStep 4: For maximum profit, maximize this expression.","steps":["Step 1: Table profit = 400x.","Step 2: Chair profit = 600y.","Step 3: Total profit = 400x + 600y.","Step 4: For maximum profit, maximize this expression."],"options":[],"conceptId":"math_linear_programming_building_a_complete_linear_programming_model","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Building a Complete Linear Programming Model"}', 1),
  (532, 154, 'Why are x ≥ 0 and y ≥ 0 included in the model?', 'text', 1, 'Think about what x and y represent.', '{"why":"Non-negativity connects the mathematical variables to their real meaning.","sol":"Step 1: x and y represent numbers of products.\nStep 2: Product quantities cannot be negative.\nStep 3: Therefore x and y must be non-negative.","steps":["Step 1: x and y represent numbers of products.","Step 2: Product quantities cannot be negative.","Step 3: Therefore x and y must be non-negative."],"options":[],"conceptId":"math_linear_programming_building_a_complete_linear_programming_model","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Building a Complete Linear Programming Model"}', 2),
  (533, 155, 'A farm has at most 50 acres. Maize uses 2 acres per bag and beans use 1 acre per bag. Form the land constraint.', 'text', 1, 'Total land used must not exceed 50.', '{"why":"The inequality represents the limited amount of land.","sol":"Step 1: Maize uses 2x acres.\nStep 2: Beans use y acres.\nStep 3: Total = 2x + y.\nStep 4: At most 50 means ≤ 50.\nStep 5: Therefore 2x + y ≤ 50.","steps":["Step 1: Maize uses 2x acres.","Step 2: Beans use y acres.","Step 3: Total = 2x + y.","Step 4: At most 50 means ≤ 50.","Step 5: Therefore 2x + y ≤ 50."],"options":[],"conceptId":"math_linear_programming_translating_a_full_word_problem_into_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Translating a Full Word Problem into Constraints"}', 0),
  (534, 155, 'A farmer must produce at least 20 bags of maize and beans combined. Form the production constraint.', 'text', 1, 'Add the two quantities.', '{"why":"The farmer must reach a minimum combined production.","sol":"Step 1: Total bags = x + y.\nStep 2: At least 20 means ≥ 20.\nStep 3: Therefore x + y ≥ 20.","steps":["Step 1: Total bags = x + y.","Step 2: At least 20 means ≥ 20.","Step 3: Therefore x + y ≥ 20."],"options":[],"conceptId":"math_linear_programming_translating_a_full_word_problem_into_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Translating a Full Word Problem into Constraints"}', 1),
  (535, 155, 'If x and y represent numbers of bags, what non-negativity conditions are required?', 'text', 1, 'Can a bag quantity be negative?', '{"why":"The variables represent quantities of physical products.","sol":"Step 1: The number of maize bags cannot be negative.\nStep 2: The number of bean bags cannot be negative.\nStep 3: Therefore x ≥ 0 and y ≥ 0.","steps":["Step 1: The number of maize bags cannot be negative.","Step 2: The number of bean bags cannot be negative.","Step 3: Therefore x ≥ 0 and y ≥ 0."],"options":[],"conceptId":"math_linear_programming_translating_a_full_word_problem_into_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Translating a Full Word Problem into Constraints"}', 2),
  (536, 156, 'Check whether (5,10) satisfies 2x + y ≤ 25.', 'text', 1, 'Substitute x = 5 and y = 10.', '{"why":"The point makes the inequality true.","sol":"Step 1: 2(5) + 10 ≤ 25.\nStep 2: 10 + 10 ≤ 25.\nStep 3: 20 ≤ 25.\nStep 4: The statement is true.","steps":["Step 1: 2(5) + 10 ≤ 25.","Step 2: 10 + 10 ≤ 25.","Step 3: 20 ≤ 25.","Step 4: The statement is true."],"options":[],"conceptId":"math_linear_programming_checking_whether_a_proposed_production_plan_is_feasible","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Checking Whether a Proposed Production Plan Is Feasible"}', 0),
  (537, 156, 'Check whether (10,8) satisfies x + y ≥ 20.', 'text', 1, 'Add the two coordinates.', '{"why":"The point fails the minimum-production constraint.","sol":"Step 1: 10 + 8 ≥ 20.\nStep 2: 18 ≥ 20.\nStep 3: This is false.","steps":["Step 1: 10 + 8 ≥ 20.","Step 2: 18 ≥ 20.","Step 3: This is false."],"options":[],"conceptId":"math_linear_programming_checking_whether_a_proposed_production_plan_is_feasible","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Checking Whether a Proposed Production Plan Is Feasible"}', 1),
  (538, 156, 'A point satisfies three constraints but fails one constraint. Is it feasible?', 'text', 1, 'Feasible means satisfying all restrictions.', '{"why":"One violated constraint is enough to make a point infeasible.","sol":"Step 1: A feasible point must satisfy every constraint.\nStep 2: The point fails one constraint.\nStep 3: Therefore it is not feasible.","steps":["Step 1: A feasible point must satisfy every constraint.","Step 2: The point fails one constraint.","Step 3: Therefore it is not feasible."],"options":[],"conceptId":"math_linear_programming_checking_whether_a_proposed_production_plan_is_feasible","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Checking Whether a Proposed Production Plan Is Feasible"}', 2),
  (539, 157, 'In the bakery problem, what does x represent?', 'text', 1, 'Look at the variable definition.', '{"why":"Every later equation depends on this variable meaning.","sol":"Step 1: x was defined as the number of loaves.\nStep 2: Therefore x represents the number of loaves.","steps":["Step 1: x was defined as the number of loaves.","Step 2: Therefore x represents the number of loaves."],"options":[],"conceptId":"math_linear_programming_building_a_linear_programming_model_from_a_complete_problem","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Building a Linear Programming Model from a Complete Problem"}', 0),
  (540, 157, 'In the bakery problem, what inequality represents the labour limit?', 'text', 1, 'Bread uses 2 hours and cakes use 3 hours.', '{"why":"The inequality represents the limited labour resource.","sol":"Step 1: Bread uses 2x hours.\nStep 2: Cakes use 3y hours.\nStep 3: Total = 2x + 3y.\nStep 4: At most 60 means ≤ 60.\nStep 5: Therefore 2x + 3y ≤ 60.","steps":["Step 1: Bread uses 2x hours.","Step 2: Cakes use 3y hours.","Step 3: Total = 2x + 3y.","Step 4: At most 60 means ≤ 60.","Step 5: Therefore 2x + 3y ≤ 60."],"options":[],"conceptId":"math_linear_programming_building_a_linear_programming_model_from_a_complete_problem","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Building a Linear Programming Model from a Complete Problem"}', 1),
  (541, 157, 'What is the complete objective function for the bakery?', 'text', 1, 'Use the profit per loaf and profit per cake.', '{"why":"The objective combines the profit contributions from both products.","sol":"Step 1: Bread profit = 40x.\nStep 2: Cake profit = 100y.\nStep 3: Total profit = 40x + 100y.\nStep 4: The aim is maximum profit.","steps":["Step 1: Bread profit = 40x.","Step 2: Cake profit = 100y.","Step 3: Total profit = 40x + 100y.","Step 4: The aim is maximum profit."],"options":[],"conceptId":"math_linear_programming_building_a_linear_programming_model_from_a_complete_problem","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Building a Linear Programming Model from a Complete Problem"}', 2),
  (542, 158, 'In the fraction 7/12, what is the numerator?', 'text', 1, 'Look at the top number.', '{"why":"The numerator is the number written above the fraction bar.","sol":"Step 1: Identify the top number.\nStep 2: The top number is 7.","steps":["Step 1: Identify the top number.","Step 2: The top number is 7."],"options":[],"conceptId":"math_fractions_understanding_fractions","skillId":"math_fractions","subskillId":"math_fractions_q1","subject":"math","chapter":"fractions","topic":"Understanding Fractions"}', 0),
  (543, 158, 'In the fraction 7/12, what is the denominator?', 'text', 1, 'Look at the bottom number.', '{"why":"The denominator is the number written below the fraction bar.","sol":"Step 1: Identify the bottom number.\nStep 2: The bottom number is 12.","steps":["Step 1: Identify the bottom number.","Step 2: The bottom number is 12."],"options":[],"conceptId":"math_fractions_understanding_fractions","skillId":"math_fractions","subskillId":"math_fractions_q2","subject":"math","chapter":"fractions","topic":"Understanding Fractions"}', 1),
  (544, 158, 'Is 5/8 a proper or improper fraction?', 'text', 1, 'Compare numerator and denominator.', '{"why":"A proper fraction has a numerator smaller than its denominator.","sol":"Step 1: Numerator = 5.\nStep 2: Denominator = 8.\nStep 3: 5 is smaller than 8.","steps":["Step 1: Numerator = 5.","Step 2: Denominator = 8.","Step 3: 5 is smaller than 8."],"options":[],"conceptId":"math_fractions_understanding_fractions","skillId":"math_fractions","subskillId":"math_fractions_q3","subject":"math","chapter":"fractions","topic":"Understanding Fractions"}', 2),
  (545, 158, 'Convert 2 3/4 to an improper fraction.', 'text', 1, 'Multiply the whole number by the denominator first.', '{"why":"A mixed number is converted by multiplying the whole number by the denominator and adding the numerator.","sol":"Step 1: 2 × 4 = 8.\nStep 2: 8 + 3 = 11.\nStep 3: Keep denominator 4.\nStep 4: The result is 11/4.","steps":["Step 1: 2 × 4 = 8.","Step 2: 8 + 3 = 11.","Step 3: Keep denominator 4.","Step 4: The result is 11/4."],"options":[],"conceptId":"math_fractions_understanding_fractions","skillId":"math_fractions","subskillId":"math_fractions_q4","subject":"math","chapter":"fractions","topic":"Understanding Fractions"}', 3),
  (546, 159, 'Find an equivalent fraction to 3/4 with denominator 20.', 'text', 1, '4 must become 20.', '{"why":"Both numerator and denominator must be multiplied by the same factor.","sol":"Step 1: 4 × 5 = 20.\nStep 2: Multiply the numerator by 5.\nStep 3: 3 × 5 = 15.","steps":["Step 1: 4 × 5 = 20.","Step 2: Multiply the numerator by 5.","Step 3: 3 × 5 = 15."],"options":[],"conceptId":"math_fractions_equivalent_fractions_and_simplifying","skillId":"math_fractions","subskillId":"math_fractions_q1","subject":"math","chapter":"fractions","topic":"Equivalent Fractions and Simplifying"}', 0),
  (547, 159, 'Simplify 12/18.', 'text', 1, 'Find a common factor of 12 and 18.', '{"why":"Dividing numerator and denominator by their greatest common factor gives simplest form.","sol":"Step 1: The greatest common factor is 6.\nStep 2: 12 ÷ 6 = 2.\nStep 3: 18 ÷ 6 = 3.","steps":["Step 1: The greatest common factor is 6.","Step 2: 12 ÷ 6 = 2.","Step 3: 18 ÷ 6 = 3."],"options":[],"conceptId":"math_fractions_equivalent_fractions_and_simplifying","skillId":"math_fractions","subskillId":"math_fractions_q2","subject":"math","chapter":"fractions","topic":"Equivalent Fractions and Simplifying"}', 1),
  (548, 159, 'Are 2/3 and 8/12 equivalent?', 'text', 1, 'Simplify 8/12.', '{"why":"Equivalent fractions represent the same value.","sol":"Step 1: Divide 8 and 12 by 4.\nStep 2: 8/12 = 2/3.\nStep 3: Therefore the fractions have the same value.","steps":["Step 1: Divide 8 and 12 by 4.","Step 2: 8/12 = 2/3.","Step 3: Therefore the fractions have the same value."],"options":[],"conceptId":"math_fractions_equivalent_fractions_and_simplifying","skillId":"math_fractions","subskillId":"math_fractions_q3","subject":"math","chapter":"fractions","topic":"Equivalent Fractions and Simplifying"}', 2),
  (549, 160, 'Which is greater: 5/9 or 2/9?', 'text', 1, 'The denominators are already equal.', '{"why":"With equal positive denominators, the larger numerator gives the larger fraction.","sol":"Step 1: Both denominators are 9.\nStep 2: Compare numerators 5 and 2.\nStep 3: 5 > 2.","steps":["Step 1: Both denominators are 9.","Step 2: Compare numerators 5 and 2.","Step 3: 5 > 2."],"options":[],"conceptId":"math_fractions_comparing_fractions","skillId":"math_fractions","subskillId":"math_fractions_q1","subject":"math","chapter":"fractions","topic":"Comparing Fractions"}', 0),
  (550, 160, 'Which is greater: 1/3 or 1/7?', 'text', 1, 'The numerators are equal.', '{"why":"For positive fractions with the same numerator, the smaller denominator gives the larger value.","sol":"Step 1: Both numerators are 1.\nStep 2: Compare denominators.\nStep 3: A third is larger than a seventh.","steps":["Step 1: Both numerators are 1.","Step 2: Compare denominators.","Step 3: A third is larger than a seventh."],"options":[],"conceptId":"math_fractions_comparing_fractions","skillId":"math_fractions","subskillId":"math_fractions_q2","subject":"math","chapter":"fractions","topic":"Comparing Fractions"}', 1),
  (551, 160, 'Which is greater: 3/4 or 5/8?', 'text', 1, 'Use a common denominator.', '{"why":"Converting to a common denominator makes comparison direct.","sol":"Step 1: Convert 3/4 to eighths.\nStep 2: 3/4 = 6/8.\nStep 3: Compare 6/8 and 5/8.\nStep 4: 6/8 is greater.","steps":["Step 1: Convert 3/4 to eighths.","Step 2: 3/4 = 6/8.","Step 3: Compare 6/8 and 5/8.","Step 4: 6/8 is greater."],"options":[],"conceptId":"math_fractions_comparing_fractions","skillId":"math_fractions","subskillId":"math_fractions_q3","subject":"math","chapter":"fractions","topic":"Comparing Fractions"}', 2),
  (552, 160, 'Which is greater: 4/7 or 5/9?', 'text', 1, 'Cross-multiply.', '{"why":"Cross-products can be compared when determining which of two positive fractions is larger.","sol":"Step 1: 4 × 9 = 36.\nStep 2: 5 × 7 = 35.\nStep 3: 36 > 35.","steps":["Step 1: 4 × 9 = 36.","Step 2: 5 × 7 = 35.","Step 3: 36 > 35."],"options":[],"conceptId":"math_fractions_comparing_fractions","skillId":"math_fractions","subskillId":"math_fractions_q4","subject":"math","chapter":"fractions","topic":"Comparing Fractions"}', 3),
  (553, 161, 'Calculate 2/5 + 1/5.', 'text', 1, 'The denominators are already equal.', '{"why":"When denominators are equal, add only the numerators.","sol":"Step 1: Add numerators: 2 + 1 = 3.\nStep 2: Keep denominator 5.\nStep 3: Result = 3/5.","steps":["Step 1: Add numerators: 2 + 1 = 3.","Step 2: Keep denominator 5.","Step 3: Result = 3/5."],"options":[],"conceptId":"math_fractions_adding_and_subtracting_fractions","skillId":"math_fractions","subskillId":"math_fractions_q1","subject":"math","chapter":"fractions","topic":"Adding and Subtracting Fractions"}', 0),
  (554, 161, 'Calculate 1/2 + 1/4.', 'text', 1, 'Change 1/2 into quarters.', '{"why":"A common denominator is required before adding fractions.","sol":"Step 1: LCM of 2 and 4 = 4.\nStep 2: 1/2 = 2/4.\nStep 3: 2/4 + 1/4 = 3/4.","steps":["Step 1: LCM of 2 and 4 = 4.","Step 2: 1/2 = 2/4.","Step 3: 2/4 + 1/4 = 3/4."],"options":[],"conceptId":"math_fractions_adding_and_subtracting_fractions","skillId":"math_fractions","subskillId":"math_fractions_q2","subject":"math","chapter":"fractions","topic":"Adding and Subtracting Fractions"}', 1),
  (555, 161, 'Calculate 5/6 - 1/3.', 'text', 1, 'Convert 1/3 to sixths.', '{"why":"The fractions are first expressed with the same denominator.","sol":"Step 1: 1/3 = 2/6.\nStep 2: 5/6 - 2/6 = 3/6.\nStep 3: Simplify 3/6 to 1/2.","steps":["Step 1: 1/3 = 2/6.","Step 2: 5/6 - 2/6 = 3/6.","Step 3: Simplify 3/6 to 1/2."],"options":[],"conceptId":"math_fractions_adding_and_subtracting_fractions","skillId":"math_fractions","subskillId":"math_fractions_q3","subject":"math","chapter":"fractions","topic":"Adding and Subtracting Fractions"}', 2),
  (556, 161, 'Calculate 2/3 + 3/4.', 'text', 1, 'Use 12 as the common denominator.', '{"why":"The LCM of 3 and 4 is 12.","sol":"Step 1: 2/3 = 8/12.\nStep 2: 3/4 = 9/12.\nStep 3: 8/12 + 9/12 = 17/12.","steps":["Step 1: 2/3 = 8/12.","Step 2: 3/4 = 9/12.","Step 3: 8/12 + 9/12 = 17/12."],"options":[],"conceptId":"math_fractions_adding_and_subtracting_fractions","skillId":"math_fractions","subskillId":"math_fractions_q4","subject":"math","chapter":"fractions","topic":"Adding and Subtracting Fractions"}', 3),
  (557, 162, 'Calculate 3/5 × 2/7.', 'text', 1, 'Multiply straight across.', '{"why":"Fractions are multiplied by multiplying corresponding numerators and denominators.","sol":"Step 1: 3 × 2 = 6.\nStep 2: 5 × 7 = 35.\nStep 3: Write the result as 6/35.","steps":["Step 1: 3 × 2 = 6.","Step 2: 5 × 7 = 35.","Step 3: Write the result as 6/35."],"options":[],"conceptId":"math_fractions_multiplying_fractions","skillId":"math_fractions","subskillId":"math_fractions_q1","subject":"math","chapter":"fractions","topic":"Multiplying Fractions"}', 0),
  (558, 162, 'Calculate 2/3 × 3/4.', 'text', 1, 'Multiply and simplify.', '{"why":"The resulting fraction must be simplified.","sol":"Step 1: 2 × 3 = 6.\nStep 2: 3 × 4 = 12.\nStep 3: 6/12 = 1/2.","steps":["Step 1: 2 × 3 = 6.","Step 2: 3 × 4 = 12.","Step 3: 6/12 = 1/2."],"options":[],"conceptId":"math_fractions_multiplying_fractions","skillId":"math_fractions","subskillId":"math_fractions_q2","subject":"math","chapter":"fractions","topic":"Multiplying Fractions"}', 1),
  (559, 162, 'Calculate 4/9 × 3/8.', 'text', 1, 'Cancel common factors first.', '{"why":"Common factors can be cancelled before multiplication.","sol":"Step 1: Cancel 4 with 8 to get 1 and 2.\nStep 2: Cancel 3 with 9 to get 1 and 3.\nStep 3: Multiply 1/3 × 1/2.\nStep 4: Result = 1/6.","steps":["Step 1: Cancel 4 with 8 to get 1 and 2.","Step 2: Cancel 3 with 9 to get 1 and 3.","Step 3: Multiply 1/3 × 1/2.","Step 4: Result = 1/6."],"options":[],"conceptId":"math_fractions_multiplying_fractions","skillId":"math_fractions","subskillId":"math_fractions_q3","subject":"math","chapter":"fractions","topic":"Multiplying Fractions"}', 2),
  (560, 163, 'Calculate 3/4 ÷ 1/2.', 'text', 1, 'Flip the second fraction.', '{"why":"Dividing by a fraction is equivalent to multiplying by its reciprocal.","sol":"Step 1: Keep 3/4.\nStep 2: Change ÷ to ×.\nStep 3: Flip 1/2 to 2/1.\nStep 4: 3/4 × 2/1 = 6/4 = 3/2.","steps":["Step 1: Keep 3/4.","Step 2: Change ÷ to ×.","Step 3: Flip 1/2 to 2/1.","Step 4: 3/4 × 2/1 = 6/4 = 3/2."],"options":[],"conceptId":"math_fractions_dividing_fractions","skillId":"math_fractions","subskillId":"math_fractions_q1","subject":"math","chapter":"fractions","topic":"Dividing Fractions"}', 0),
  (561, 163, 'Calculate 5/6 ÷ 1/3.', 'text', 1, 'The reciprocal of 1/3 is 3.', '{"why":"The second fraction is replaced by its reciprocal.","sol":"Step 1: 5/6 ÷ 1/3 = 5/6 × 3/1.\nStep 2: Multiply to get 15/6.\nStep 3: Simplify to 5/2.","steps":["Step 1: 5/6 ÷ 1/3 = 5/6 × 3/1.","Step 2: Multiply to get 15/6.","Step 3: Simplify to 5/2."],"options":[],"conceptId":"math_fractions_dividing_fractions","skillId":"math_fractions","subskillId":"math_fractions_q2","subject":"math","chapter":"fractions","topic":"Dividing Fractions"}', 1),
  (562, 163, 'Calculate 2/5 ÷ 2/5.', 'text', 1, 'A non-zero number divided by itself equals 1.', '{"why":"Any non-zero number divided by itself equals 1.","sol":"Step 1: Flip the second fraction: 5/2.\nStep 2: 2/5 × 5/2.\nStep 3: Cancel common factors.\nStep 4: Result = 1.","steps":["Step 1: Flip the second fraction: 5/2.","Step 2: 2/5 × 5/2.","Step 3: Cancel common factors.","Step 4: Result = 1."],"options":[],"conceptId":"math_fractions_dividing_fractions","skillId":"math_fractions","subskillId":"math_fractions_q3","subject":"math","chapter":"fractions","topic":"Dividing Fractions"}', 2),
  (563, 164, 'Convert 0.6 to a fraction in simplest form.', 'text', 1, 'Write it over 10.', '{"why":"One decimal place represents tenths.","sol":"Step 1: 0.6 = 6/10.\nStep 2: Divide numerator and denominator by 2.\nStep 3: 6/10 = 3/5.","steps":["Step 1: 0.6 = 6/10.","Step 2: Divide numerator and denominator by 2.","Step 3: 6/10 = 3/5."],"options":[],"conceptId":"math_fractions_decimals_and_fractions","skillId":"math_fractions","subskillId":"math_fractions_q1","subject":"math","chapter":"fractions","topic":"Decimals and Fractions"}', 0),
  (564, 164, 'Convert 0.75 to a fraction in simplest form.', 'text', 1, 'Write it over 100.', '{"why":"Two decimal places represent hundredths.","sol":"Step 1: 0.75 = 75/100.\nStep 2: Divide numerator and denominator by 25.\nStep 3: 75/100 = 3/4.","steps":["Step 1: 0.75 = 75/100.","Step 2: Divide numerator and denominator by 25.","Step 3: 75/100 = 3/4."],"options":[],"conceptId":"math_fractions_decimals_and_fractions","skillId":"math_fractions","subskillId":"math_fractions_q2","subject":"math","chapter":"fractions","topic":"Decimals and Fractions"}', 1),
  (565, 164, 'Convert 5/8 to a decimal.', 'text', 1, 'Divide 5 by 8.', '{"why":"A fraction can be converted to a decimal by dividing numerator by denominator.","sol":"Step 1: 5 ÷ 8.\nStep 2: 5/8 = 0.625.","steps":["Step 1: 5 ÷ 8.","Step 2: 5/8 = 0.625."],"options":[],"conceptId":"math_fractions_decimals_and_fractions","skillId":"math_fractions","subskillId":"math_fractions_q3","subject":"math","chapter":"fractions","topic":"Decimals and Fractions"}', 2),
  (566, 164, 'Convert 7/10 to a decimal.', 'text', 1, 'The denominator is already 10.', '{"why":"A denominator of 10 corresponds directly to one decimal place.","sol":"Step 1: 7/10 represents seven tenths.\nStep 2: Seven tenths is written as 0.7.","steps":["Step 1: 7/10 represents seven tenths.","Step 2: Seven tenths is written as 0.7."],"options":[],"conceptId":"math_fractions_decimals_and_fractions","skillId":"math_fractions","subskillId":"math_fractions_q4","subject":"math","chapter":"fractions","topic":"Decimals and Fractions"}', 3),
  (567, 165, 'Convert 0.666... to a fraction.', 'text', 1, 'Let x = 0.666... and multiply by 10.', '{"why":"Multiplication by 10 shifts a single repeating digit, allowing subtraction to eliminate the repetition.","sol":"Step 1: x = 0.666...\nStep 2: 10x = 6.666...\nStep 3: 10x − x = 6.\nStep 4: 9x = 6.\nStep 5: x = 6/9 = 2/3.","steps":["Step 1: x = 0.666...","Step 2: 10x = 6.666...","Step 3: 10x − x = 6.","Step 4: 9x = 6.","Step 5: x = 6/9 = 2/3."],"options":[],"conceptId":"math_fractions_recurring_decimals","skillId":"math_fractions","subskillId":"math_fractions_q1","subject":"math","chapter":"fractions","topic":"Recurring Decimals"}', 0),
  (568, 165, 'Convert 0.444... to a fraction.', 'text', 1, 'Use x = 0.444... and multiply by 10.', '{"why":"A single repeating digit is eliminated by subtracting x from 10x.","sol":"Step 1: x = 0.444...\nStep 2: 10x = 4.444...\nStep 3: 10x − x = 4.\nStep 4: 9x = 4.\nStep 5: x = 4/9.","steps":["Step 1: x = 0.444...","Step 2: 10x = 4.444...","Step 3: 10x − x = 4.","Step 4: 9x = 4.","Step 5: x = 4/9."],"options":[],"conceptId":"math_fractions_recurring_decimals","skillId":"math_fractions","subskillId":"math_fractions_q2","subject":"math","chapter":"fractions","topic":"Recurring Decimals"}', 1),
  (569, 165, 'Convert 0.121212... to a fraction.', 'text', 1, 'Two digits repeat, so use 100.', '{"why":"A two-digit repeating block requires multiplication by 100 to align the repeating parts.","sol":"Step 1: x = 0.121212...\nStep 2: 100x = 12.121212...\nStep 3: 100x − x = 12.\nStep 4: 99x = 12.\nStep 5: x = 12/99 = 4/33.","steps":["Step 1: x = 0.121212...","Step 2: 100x = 12.121212...","Step 3: 100x − x = 12.","Step 4: 99x = 12.","Step 5: x = 12/99 = 4/33."],"options":[],"conceptId":"math_fractions_recurring_decimals","skillId":"math_fractions","subskillId":"math_fractions_q3","subject":"math","chapter":"fractions","topic":"Recurring Decimals"}', 2),
  (570, 165, 'Convert 0.090909... to a fraction.', 'text', 1, 'The repeating block is 09.', '{"why":"The repeating block has two digits, so multiplying by 100 aligns the repeating portions.","sol":"Step 1: x = 0.090909...\nStep 2: 100x = 9.090909...\nStep 3: 100x − x = 9.\nStep 4: 99x = 9.\nStep 5: x = 9/99 = 1/11.","steps":["Step 1: x = 0.090909...","Step 2: 100x = 9.090909...","Step 3: 100x − x = 9.","Step 4: 99x = 9.","Step 5: x = 9/99 = 1/11."],"options":[],"conceptId":"math_fractions_recurring_decimals","skillId":"math_fractions","subskillId":"math_fractions_q4","subject":"math","chapter":"fractions","topic":"Recurring Decimals"}', 3),
  (571, 166, 'Find the area of a rectangle with length 8 cm and width 3 cm.', 'text', 1, 'Use A = l × w.', '{"why":"The area of a rectangle is found by multiplying its length by its width.","sol":"Step 1: Write the formula: A = l × w.\nStep 2: Substitute l = 8 and w = 3.\nStep 3: A = 8 × 3.\nStep 4: A = 24.","steps":["Step 1: Write the formula: A = l × w.","Step 2: Substitute l = 8 and w = 3.","Step 3: A = 8 × 3.","Step 4: A = 24."],"options":[],"conceptId":"math_measurement_area_of_rectangles_and_squares","skillId":"math_measurement","subskillId":"math_measurement_q1","subject":"math","chapter":"measurement","topic":"Area of Rectangles and Squares"}', 0),
  (572, 166, 'Find the area of a square with side 7 cm.', 'text', 1, 'A = side².', '{"why":"All sides of a square are equal, so its area is side × side.","sol":"Step 1: A = side × side.\nStep 2: A = 7 × 7.\nStep 3: A = 49.","steps":["Step 1: A = side × side.","Step 2: A = 7 × 7.","Step 3: A = 49."],"options":[],"conceptId":"math_measurement_area_of_rectangles_and_squares","skillId":"math_measurement","subskillId":"math_measurement_q2","subject":"math","chapter":"measurement","topic":"Area of Rectangles and Squares"}', 1),
  (573, 166, 'A rectangle has area 45 cm² and width 5 cm. Find its length.', 'text', 1, 'Length = area ÷ width.', '{"why":"The missing length is found by rearranging A = l × w.","sol":"Step 1: A = l × w.\nStep 2: 45 = l × 5.\nStep 3: Divide both sides by 5.\nStep 4: l = 9.","steps":["Step 1: A = l × w.","Step 2: 45 = l × 5.","Step 3: Divide both sides by 5.","Step 4: l = 9."],"options":[],"conceptId":"math_measurement_area_of_rectangles_and_squares","skillId":"math_measurement","subskillId":"math_measurement_q3","subject":"math","chapter":"measurement","topic":"Area of Rectangles and Squares"}', 2),
  (574, 166, 'A rectangle has length 9 cm and width 5 cm. What is its area?', 'text', 1, 'Multiply 9 by 5.', '{"why":"Area measures the two-dimensional space inside the rectangle.","sol":"Step 1: A = 9 × 5.\nStep 2: A = 45.","steps":["Step 1: A = 9 × 5.","Step 2: A = 45."],"options":[],"conceptId":"math_measurement_area_of_rectangles_and_squares","skillId":"math_measurement","subskillId":"math_measurement_q4","subject":"math","chapter":"measurement","topic":"Area of Rectangles and Squares"}', 3),
  (575, 166, 'Which formula gives the area of a rectangle?', 'text', 1, 'Think about its two dimensions.', '{"why":"Rectangle area is length multiplied by width.","sol":"Step 1: A rectangle has length and width.\nStep 2: Multiply the two dimensions.\nStep 3: A = l × w.","steps":["Step 1: A rectangle has length and width.","Step 2: Multiply the two dimensions.","Step 3: A = l × w."],"options":[],"conceptId":"math_measurement_area_of_rectangles_and_squares","skillId":"math_measurement","subskillId":"math_measurement_q5","subject":"math","chapter":"measurement","topic":"Area of Rectangles and Squares"}', 4),
  (576, 167, 'Find the area of a triangle with base 12 cm and height 4 cm.', 'text', 1, 'Use A = 1/2 × b × h.', '{"why":"Triangle area is half the product of its base and perpendicular height.","sol":"Step 1: A = 1/2 × 12 × 4.\nStep 2: 12 ÷ 2 = 6.\nStep 3: 6 × 4 = 24.","steps":["Step 1: A = 1/2 × 12 × 4.","Step 2: 12 ÷ 2 = 6.","Step 3: 6 × 4 = 24."],"options":[],"conceptId":"math_measurement_area_of_triangles","skillId":"math_measurement","subskillId":"math_measurement_q1","subject":"math","chapter":"measurement","topic":"Area of Triangles"}', 0),
  (577, 167, 'A triangle has base 14 cm and height 6 cm. Find its area.', 'text', 1, 'Multiply the base and height, then divide by 2.', '{"why":"The factor 1/2 is required because a triangle occupies half the corresponding base-height rectangle.","sol":"Step 1: A = 1/2 × 14 × 6.\nStep 2: 14 × 6 = 84.\nStep 3: 84 ÷ 2 = 42.","steps":["Step 1: A = 1/2 × 14 × 6.","Step 2: 14 × 6 = 84.","Step 3: 84 ÷ 2 = 42."],"options":[],"conceptId":"math_measurement_area_of_triangles","skillId":"math_measurement","subskillId":"math_measurement_q2","subject":"math","chapter":"measurement","topic":"Area of Triangles"}', 1),
  (578, 167, 'A triangle has area 40 cm² and base 10 cm. Find its perpendicular height.', 'text', 1, 'h = 2A ÷ b.', '{"why":"Rearranging A = 1/2bh gives h = 2A ÷ b.","sol":"Step 1: h = 2A ÷ b.\nStep 2: h = (2 × 40) ÷ 10.\nStep 3: h = 80 ÷ 10.\nStep 4: h = 8.","steps":["Step 1: h = 2A ÷ b.","Step 2: h = (2 × 40) ÷ 10.","Step 3: h = 80 ÷ 10.","Step 4: h = 8."],"options":[],"conceptId":"math_measurement_area_of_triangles","skillId":"math_measurement","subskillId":"math_measurement_q3","subject":"math","chapter":"measurement","topic":"Area of Triangles"}', 2),
  (579, 167, 'A triangle has area 24 cm² and height 6 cm. Find its base.', 'text', 1, 'b = 2A ÷ h.', '{"why":"The formula can be rearranged to find an unknown base.","sol":"Step 1: b = 2A ÷ h.\nStep 2: b = (2 × 24) ÷ 6.\nStep 3: b = 48 ÷ 6.\nStep 4: b = 8.","steps":["Step 1: b = 2A ÷ h.","Step 2: b = (2 × 24) ÷ 6.","Step 3: b = 48 ÷ 6.","Step 4: b = 8."],"options":[],"conceptId":"math_measurement_area_of_triangles","skillId":"math_measurement","subskillId":"math_measurement_q4","subject":"math","chapter":"measurement","topic":"Area of Triangles"}', 3),
  (580, 168, 'Find the volume of a cuboid measuring 8 cm × 3 cm × 2 cm.', 'text', 1, 'Multiply all three dimensions.', '{"why":"Cuboid volume is the product of its three dimensions.","sol":"Step 1: V = l × w × h.\nStep 2: V = 8 × 3 × 2.\nStep 3: V = 48.","steps":["Step 1: V = l × w × h.","Step 2: V = 8 × 3 × 2.","Step 3: V = 48."],"options":[],"conceptId":"math_measurement_volume_of_cubes_and_cuboids","skillId":"math_measurement","subskillId":"math_measurement_q1","subject":"math","chapter":"measurement","topic":"Volume of Cubes and Cuboids"}', 0),
  (581, 168, 'Find the volume of a cube with side 5 cm.', 'text', 1, 'V = s³.', '{"why":"A cube has three equal dimensions, so its volume is side cubed.","sol":"Step 1: V = 5 × 5 × 5.\nStep 2: 5 × 5 = 25.\nStep 3: 25 × 5 = 125.","steps":["Step 1: V = 5 × 5 × 5.","Step 2: 5 × 5 = 25.","Step 3: 25 × 5 = 125."],"options":[],"conceptId":"math_measurement_volume_of_cubes_and_cuboids","skillId":"math_measurement","subskillId":"math_measurement_q2","subject":"math","chapter":"measurement","topic":"Volume of Cubes and Cuboids"}', 1),
  (582, 168, 'A cuboid has volume 60 cm³, length 5 cm and width 3 cm. Find its height.', 'text', 1, 'h = V ÷ (lw).', '{"why":"Rearranging V = lwh gives h = V ÷ (lw).","sol":"Step 1: h = V ÷ (lw).\nStep 2: h = 60 ÷ (5 × 3).\nStep 3: h = 60 ÷ 15.\nStep 4: h = 4.","steps":["Step 1: h = V ÷ (lw).","Step 2: h = 60 ÷ (5 × 3).","Step 3: h = 60 ÷ 15.","Step 4: h = 4."],"options":[],"conceptId":"math_measurement_volume_of_cubes_and_cuboids","skillId":"math_measurement","subskillId":"math_measurement_q3","subject":"math","chapter":"measurement","topic":"Volume of Cubes and Cuboids"}', 2),
  (583, 168, 'Which formula gives the volume of a cuboid?', 'text', 1, 'A cuboid has three dimensions.', '{"why":"Volume of a cuboid is the product of its length, width and height.","sol":"Step 1: Identify the three dimensions.\nStep 2: Multiply length, width and height.","steps":["Step 1: Identify the three dimensions.","Step 2: Multiply length, width and height."],"options":[],"conceptId":"math_measurement_volume_of_cubes_and_cuboids","skillId":"math_measurement","subskillId":"math_measurement_q4","subject":"math","chapter":"measurement","topic":"Volume of Cubes and Cuboids"}', 3),
  (584, 169, 'Find the surface area of a cube with side 5 cm.', 'text', 1, 'Use SA = 6s².', '{"why":"A cube has six equal square faces.","sol":"Step 1: SA = 6 × 5².\nStep 2: 5² = 25.\nStep 3: 6 × 25 = 150.","steps":["Step 1: SA = 6 × 5².","Step 2: 5² = 25.","Step 3: 6 × 25 = 150."],"options":[],"conceptId":"math_measurement_surface_area_of_cubes_and_cuboids","skillId":"math_measurement","subskillId":"math_measurement_q1","subject":"math","chapter":"measurement","topic":"Surface Area of Cubes and Cuboids"}', 0),
  (585, 169, 'Find the surface area of a cube with side 3 cm.', 'text', 1, 'Square the side, then multiply by 6.', '{"why":"The six faces of the cube each have area 9 cm².","sol":"Step 1: 3² = 9.\nStep 2: 6 × 9 = 54.","steps":["Step 1: 3² = 9.","Step 2: 6 × 9 = 54."],"options":[],"conceptId":"math_measurement_surface_area_of_cubes_and_cuboids","skillId":"math_measurement","subskillId":"math_measurement_q2","subject":"math","chapter":"measurement","topic":"Surface Area of Cubes and Cuboids"}', 1),
  (586, 169, 'Find the surface area of a cuboid with length 4 cm, width 3 cm and height 2 cm.', 'text', 1, 'Use SA = 2(lw + lh + wh).', '{"why":"The three different face areas each occur twice.","sol":"Step 1: lw = 4 × 3 = 12.\nStep 2: lh = 4 × 2 = 8.\nStep 3: wh = 3 × 2 = 6.\nStep 4: Add: 12 + 8 + 6 = 26.\nStep 5: Multiply by 2: 2 × 26 = 52.","steps":["Step 1: lw = 4 × 3 = 12.","Step 2: lh = 4 × 2 = 8.","Step 3: wh = 3 × 2 = 6.","Step 4: Add: 12 + 8 + 6 = 26.","Step 5: Multiply by 2: 2 × 26 = 52."],"options":[],"conceptId":"math_measurement_surface_area_of_cubes_and_cuboids","skillId":"math_measurement","subskillId":"math_measurement_q3","subject":"math","chapter":"measurement","topic":"Surface Area of Cubes and Cuboids"}', 2),
  (587, 169, 'Which formula gives the surface area of a cuboid?', 'text', 1, 'There are three pairs of equal faces.', '{"why":"A cuboid has two faces of each of its three different dimensions.","sol":"Step 1: Identify the three face areas: lw, lh and wh.\nStep 2: Add them.\nStep 3: Multiply by 2.","steps":["Step 1: Identify the three face areas: lw, lh and wh.","Step 2: Add them.","Step 3: Multiply by 2."],"options":[],"conceptId":"math_measurement_surface_area_of_cubes_and_cuboids","skillId":"math_measurement","subskillId":"math_measurement_q4","subject":"math","chapter":"measurement","topic":"Surface Area of Cubes and Cuboids"}', 3),
  (588, 170, 'What unit should be used for the area of a rectangle measured in centimetres?', 'text', 1, 'Area uses squared units.', '{"why":"Area measures two dimensions, so its units are squared.","sol":"Step 1: The quantity is area.\nStep 2: Area uses square units.\nStep 3: Therefore the unit is cm².","steps":["Step 1: The quantity is area.","Step 2: Area uses square units.","Step 3: Therefore the unit is cm²."],"options":[],"conceptId":"math_measurement_measurement_units_and_dimensions","skillId":"math_measurement","subskillId":"math_measurement_q1","subject":"math","chapter":"measurement","topic":"Measurement Units and Dimensions"}', 0),
  (589, 170, 'What unit should be used for the volume of a cuboid measured in centimetres?', 'text', 1, 'Volume uses three dimensions.', '{"why":"Volume measures three dimensions, so its units are cubed.","sol":"Step 1: The quantity is volume.\nStep 2: Volume uses cubic units.\nStep 3: Therefore the unit is cm³.","steps":["Step 1: The quantity is volume.","Step 2: Volume uses cubic units.","Step 3: Therefore the unit is cm³."],"options":[],"conceptId":"math_measurement_measurement_units_and_dimensions","skillId":"math_measurement","subskillId":"math_measurement_q2","subject":"math","chapter":"measurement","topic":"Measurement Units and Dimensions"}', 1),
  (590, 170, 'Convert 1 m² to cm².', 'text', 1, '1 m = 100 cm, then square the conversion factor.', '{"why":"Area conversion factors must be squared.","sol":"Step 1: 1 m = 100 cm.\nStep 2: Square both sides.\nStep 3: 1 m² = 100² cm².\nStep 4: 100² = 10,000.","steps":["Step 1: 1 m = 100 cm.","Step 2: Square both sides.","Step 3: 1 m² = 100² cm².","Step 4: 100² = 10,000."],"options":[],"conceptId":"math_measurement_measurement_units_and_dimensions","skillId":"math_measurement","subskillId":"math_measurement_q3","subject":"math","chapter":"measurement","topic":"Measurement Units and Dimensions"}', 2),
  (591, 170, 'Convert 1 m³ to cm³.', 'text', 1, '1 m = 100 cm, then cube the conversion factor.', '{"why":"Volume conversion factors must be cubed.","sol":"Step 1: 1 m = 100 cm.\nStep 2: Cube both sides.\nStep 3: 1 m³ = 100³ cm³.\nStep 4: 100³ = 1,000,000.","steps":["Step 1: 1 m = 100 cm.","Step 2: Cube both sides.","Step 3: 1 m³ = 100³ cm³.","Step 4: 100³ = 1,000,000."],"options":[],"conceptId":"math_measurement_measurement_units_and_dimensions","skillId":"math_measurement","subskillId":"math_measurement_q4","subject":"math","chapter":"measurement","topic":"Measurement Units and Dimensions"}', 3),
  (592, 170, 'Which is larger: 1 m² or 100 cm²?', 'text', 1, 'Convert 1 m² into cm².', '{"why":"Squared units require the length conversion factor to be squared.","sol":"Step 1: 1 m² = 10,000 cm².\nStep 2: Compare 10,000 cm² and 100 cm².\nStep 3: 10,000 cm² is larger.","steps":["Step 1: 1 m² = 10,000 cm².","Step 2: Compare 10,000 cm² and 100 cm².","Step 3: 10,000 cm² is larger."],"options":[],"conceptId":"math_measurement_measurement_units_and_dimensions","skillId":"math_measurement","subskillId":"math_measurement_q5","subject":"math","chapter":"measurement","topic":"Measurement Units and Dimensions"}', 4),
  (593, 171, 'Find the distance between points (2,3) and (6,7)', 'text', 1, 'distance formula', '{"why":"Distance between two points is found using Euclidean formula","sol":"Step 1: Use d = √((x₂ − x₁)² + (y₂ − y₁)²)\nStep 2: Substitute values (6−2) and (7−3)\nStep 3: Compute 4² and 4²\nStep 4: Add results\nStep 5: Take square root","steps":["Step 1: Use d = √((x₂ − x₁)² + (y₂ − y₁)²)","Step 2: Substitute values (6−2) and (7−3)","Step 3: Compute 4² and 4²","Step 4: Add results","Step 5: Take square root"],"options":[],"conceptId":"math_graphs_coordinate_plane_basics","skillId":"math_graphs","subskillId":"math_graphs_q1","subject":"math","chapter":"graphs","topic":"Coordinate plane basics"}', 0),
  (594, 171, 'Find midpoint of (2,4) and (8,10)', 'text', 1, 'midpoint formula', '{"why":"Midpoint is average of coordinates","sol":"Step 1: Use M = ((x₁ + x₂)/2, (y₁ + y₂)/2)\nStep 2: Substitute values\nStep 3: Compute x-coordinate\nStep 4: Compute y-coordinate\nStep 5: Form midpoint","steps":["Step 1: Use M = ((x₁ + x₂)/2, (y₁ + y₂)/2)","Step 2: Substitute values","Step 3: Compute x-coordinate","Step 4: Compute y-coordinate","Step 5: Form midpoint"],"options":[],"conceptId":"math_graphs_coordinate_plane_basics","skillId":"math_graphs","subskillId":"math_graphs_q2","subject":"math","chapter":"graphs","topic":"Coordinate plane basics"}', 1),
  (595, 171, 'Determine the coordinates after moving from (3,5) by +4 in x and −2 in y', 'text', 1, 'translation', '{"why":"Translation shifts points by vector addition","sol":"Step 1: Start at (3,5)\nStep 2: Add 4 to x-coordinate\nStep 3: Subtract 2 from y-coordinate\nStep 4: Write new coordinates","steps":["Step 1: Start at (3,5)","Step 2: Add 4 to x-coordinate","Step 3: Subtract 2 from y-coordinate","Step 4: Write new coordinates"],"options":[],"conceptId":"math_graphs_coordinate_plane_basics","skillId":"math_graphs","subskillId":"math_graphs_q3","subject":"math","chapter":"graphs","topic":"Coordinate plane basics"}', 2),
  (596, 171, 'Find slope between points (1,2) and (5,10)', 'text', 1, 'rise over run', '{"why":"Slope measures rate of change between two points","sol":"Step 1: Use m = (y₂ − y₁)/(x₂ − x₁)\nStep 2: Substitute values\nStep 3: Compute numerator 8\nStep 4: Compute denominator 4\nStep 5: Simplify fraction","steps":["Step 1: Use m = (y₂ − y₁)/(x₂ − x₁)","Step 2: Substitute values","Step 3: Compute numerator 8","Step 4: Compute denominator 4","Step 5: Simplify fraction"],"options":[],"conceptId":"math_graphs_coordinate_plane_basics","skillId":"math_graphs","subskillId":"math_graphs_q4","subject":"math","chapter":"graphs","topic":"Coordinate plane basics"}', 3),
  (597, 171, 'Find equation of line passing through (0,0) with slope 3', 'text', 1, 'y = mx + c', '{"why":"Line equation is determined by slope and intercept","sol":"Step 1: Use y = mx + c\nStep 2: Substitute m = 3\nStep 3: Use point (0,0) to find c\nStep 4: Solve for c\nStep 5: Write final equation","steps":["Step 1: Use y = mx + c","Step 2: Substitute m = 3","Step 3: Use point (0,0) to find c","Step 4: Solve for c","Step 5: Write final equation"],"options":[],"conceptId":"math_graphs_coordinate_plane_basics","skillId":"math_graphs","subskillId":"math_graphs_q5","subject":"math","chapter":"graphs","topic":"Coordinate plane basics"}', 4),
  (598, 172, 'Locate the point (3, -2) on a coordinate plane and describe its movement from origin', 'text', 1, 'x then y movement', '{"why":"Coordinates represent horizontal (x) and vertical (y) displacement from origin","sol":"Step 1: Start at origin (0,0)\nStep 2: Move +3 units along x-axis\nStep 3: Move −2 units along y-axis\nStep 4: Mark final position on plane","steps":["Step 1: Start at origin (0,0)","Step 2: Move +3 units along x-axis","Step 3: Move −2 units along y-axis","Step 4: Mark final position on plane"],"options":[],"conceptId":"math_graphs_plotting_points","skillId":"math_graphs","subskillId":"math_graphs_q1","subject":"math","chapter":"graphs","topic":"Plotting points"}', 0),
  (599, 172, 'Find coordinates after moving 5 units right and 4 units up from origin', 'text', 1, 'directional movement', '{"why":"Positive x and y values place the point in the first quadrant","sol":"Step 1: Start at (0,0)\nStep 2: Move +5 along x-axis\nStep 3: Move +4 along y-axis\nStep 4: Plot final point","steps":["Step 1: Start at (0,0)","Step 2: Move +5 along x-axis","Step 3: Move +4 along y-axis","Step 4: Plot final point"],"options":[],"conceptId":"math_graphs_plotting_points","skillId":"math_graphs","subskillId":"math_graphs_q2","subject":"math","chapter":"graphs","topic":"Plotting points"}', 1),
  (600, 172, 'Determine location of point (0, -6) on coordinate plane', 'text', 1, 'axis identification', '{"why":"x = 0 means the point lies directly on the y-axis","sol":"Step 1: Check x = 0\nStep 2: Move only along y-axis\nStep 3: Locate negative direction\nStep 4: Identify axis position","steps":["Step 1: Check x = 0","Step 2: Move only along y-axis","Step 3: Locate negative direction","Step 4: Identify axis position"],"options":[],"conceptId":"math_graphs_plotting_points","skillId":"math_graphs","subskillId":"math_graphs_q3","subject":"math","chapter":"graphs","topic":"Plotting points"}', 2),
  (601, 172, 'Determine location of point (4, 0) on coordinate plane', 'text', 1, 'axis rule', '{"why":"y = 0 means the point lies on the x-axis","sol":"Step 1: Check y = 0\nStep 2: Move only along x-axis\nStep 3: Locate positive direction\nStep 4: Identify axis position","steps":["Step 1: Check y = 0","Step 2: Move only along x-axis","Step 3: Locate positive direction","Step 4: Identify axis position"],"options":[],"conceptId":"math_graphs_plotting_points","skillId":"math_graphs","subskillId":"math_graphs_q4","subject":"math","chapter":"graphs","topic":"Plotting points"}', 3),
  (602, 172, 'Identify the reference starting point for all coordinate plotting', 'text', 1, 'origin concept', '{"why":"All coordinates are measured from the origin","sol":"Step 1: Locate intersection of axes\nStep 2: Identify x = 0 and y = 0\nStep 3: Mark central reference point","steps":["Step 1: Locate intersection of axes","Step 2: Identify x = 0 and y = 0","Step 3: Mark central reference point"],"options":[],"conceptId":"math_graphs_plotting_points","skillId":"math_graphs","subskillId":"math_graphs_q5","subject":"math","chapter":"graphs","topic":"Plotting points"}', 4),
  (603, 173, 'Plot a line graph for points (1,2), (2,3), (3,5)', 'text', 1, 'coordinate plotting', '{"why":"Increasing y-values show upward trend","sol":"Step 1: Draw x-axis and y-axis\nStep 2: Plot (1,2), (2,3), (3,5)\nStep 3: Check correct positions on plane\nStep 4: Join points in order with straight lines","steps":["Step 1: Draw x-axis and y-axis","Step 2: Plot (1,2), (2,3), (3,5)","Step 3: Check correct positions on plane","Step 4: Join points in order with straight lines"],"options":[],"conceptId":"math_graphs_line_graphs","skillId":"math_graphs","subskillId":"math_graphs_q1","subject":"math","chapter":"graphs","topic":"Line graphs"}', 0),
  (604, 173, 'Identify change when graph goes from (1,5) to (3,5)', 'text', 1, 'constant value', '{"why":"Equal y-values form a horizontal line","sol":"Step 1: Compare y-values at both points\nStep 2: 5 and 5 are equal\nStep 3: Determine slope behavior\nStep 4: Classify trend","steps":["Step 1: Compare y-values at both points","Step 2: 5 and 5 are equal","Step 3: Determine slope behavior","Step 4: Classify trend"],"options":[],"conceptId":"math_graphs_line_graphs","skillId":"math_graphs","subskillId":"math_graphs_q2","subject":"math","chapter":"graphs","topic":"Line graphs"}', 1),
  (605, 173, 'Determine trend of points (1,4), (2,3), (3,2)', 'text', 1, 'decreasing pattern', '{"why":"Y-values reduce as x increases","sol":"Step 1: Observe y-values\nStep 2: 4 → 3 → 2\nStep 3: Check direction of change\nStep 4: Classify graph behavior","steps":["Step 1: Observe y-values","Step 2: 4 → 3 → 2","Step 3: Check direction of change","Step 4: Classify graph behavior"],"options":[],"conceptId":"math_graphs_line_graphs","skillId":"math_graphs","subskillId":"math_graphs_q3","subject":"math","chapter":"graphs","topic":"Line graphs"}', 2),
  (606, 173, 'Find slope between points (1,1) and (4,7)', 'text', 1, 'rise over run', '{"why":"Slope measures rate of change in a line graph","sol":"Step 1: Use m = (y₂ − y₁)/(x₂ − x₁)\nStep 2: Substitute values\nStep 3: Compute 7 − 1 = 6\nStep 4: Compute 4 − 1 = 3\nStep 5: Simplify fraction","steps":["Step 1: Use m = (y₂ − y₁)/(x₂ − x₁)","Step 2: Substitute values","Step 3: Compute 7 − 1 = 6","Step 4: Compute 4 − 1 = 3","Step 5: Simplify fraction"],"options":[],"conceptId":"math_graphs_line_graphs","skillId":"math_graphs","subskillId":"math_graphs_q4","subject":"math","chapter":"graphs","topic":"Line graphs"}', 3),
  (607, 173, 'Find missing point pattern if graph is linear: (1,2), (2,?), (3,6)', 'text', 1, 'linear pattern', '{"why":"Linear graphs have constant rate of change","sol":"Step 1: Observe change from 1 to 3 in x\nStep 2: Observe change from 2 to 6 in y\nStep 3: Determine pattern increase\nStep 4: Find middle value","steps":["Step 1: Observe change from 1 to 3 in x","Step 2: Observe change from 2 to 6 in y","Step 3: Determine pattern increase","Step 4: Find middle value"],"options":[],"conceptId":"math_graphs_line_graphs","skillId":"math_graphs","subskillId":"math_graphs_q5","subject":"math","chapter":"graphs","topic":"Line graphs"}', 4),
  (608, 174, 'Find gradient when rise = 12 and run = 3', 'text', 1, 'm = rise ÷ run', '{"why":"Gradient measures vertical change per unit horizontal change","sol":"Step 1: Write m = rise ÷ run\nStep 2: Substitute m = 12 ÷ 3\nStep 3: Compute division\nStep 4: Simplify result","steps":["Step 1: Write m = rise ÷ run","Step 2: Substitute m = 12 ÷ 3","Step 3: Compute division","Step 4: Simplify result"],"options":[],"conceptId":"math_graphs_gradient","skillId":"math_graphs","subskillId":"math_graphs_q1","subject":"math","chapter":"graphs","topic":"Gradient"}', 0),
  (609, 174, 'Find gradient between points (2,5) and (6,1)', 'text', 1, 'use coordinate formula', '{"why":"Gradient is found using change in y over change in x","sol":"Step 1: Use m = (y₂ − y₁)/(x₂ − x₁)\nStep 2: Substitute values (1 − 5)/(6 − 2)\nStep 3: Compute numerator −4\nStep 4: Compute denominator 4\nStep 5: Simplify fraction","steps":["Step 1: Use m = (y₂ − y₁)/(x₂ − x₁)","Step 2: Substitute values (1 − 5)/(6 − 2)","Step 3: Compute numerator −4","Step 4: Compute denominator 4","Step 5: Simplify fraction"],"options":[],"conceptId":"math_graphs_gradient","skillId":"math_graphs","subskillId":"math_graphs_q2","subject":"math","chapter":"graphs","topic":"Gradient"}', 1),
  (610, 174, 'Interpret gradient m = -3 in a line', 'text', 1, 'direction', '{"why":"Negative gradient shows downward movement from left to right","sol":"Step 1: Identify sign of gradient\nStep 2: m < 0 indicates negative slope\nStep 3: For each 1 step right, y decreases by 3\nStep 4: Describe direction","steps":["Step 1: Identify sign of gradient","Step 2: m < 0 indicates negative slope","Step 3: For each 1 step right, y decreases by 3","Step 4: Describe direction"],"options":[],"conceptId":"math_graphs_gradient","skillId":"math_graphs","subskillId":"math_graphs_q3","subject":"math","chapter":"graphs","topic":"Gradient"}', 2),
  (611, 174, 'Interpret gradient m = 0', 'text', 1, 'flat line', '{"why":"Zero gradient means constant y-value across x","sol":"Step 1: Check gradient value\nStep 2: m = 0 means no vertical change\nStep 3: y-value remains constant\nStep 4: Describe graph","steps":["Step 1: Check gradient value","Step 2: m = 0 means no vertical change","Step 3: y-value remains constant","Step 4: Describe graph"],"options":[],"conceptId":"math_graphs_gradient","skillId":"math_graphs","subskillId":"math_graphs_q4","subject":"math","chapter":"graphs","topic":"Gradient"}', 3),
  (612, 175, 'Why are graphs important?', 'text', 1, 'show data visually', '{"why":"Graphs convert numerical data into visual form, making patterns and trends easier to understand","sol":"Step 1: Identify key concept: Define the required principles for Applications of graphs.\nStep 2: Apply governing rule: Graphs convert numerical data into visual form, making patterns and trends easier to understand\nStep 3: State the final conclusion: data visualization","steps":["Step 1: Identify key concept: Define the required principles for Applications of graphs.","Step 2: Apply governing rule: Graphs convert numerical data into visual form, making patterns and trends easier to understand","Step 3: State the final conclusion: data visualization"],"options":[],"conceptId":"math_graphs_applications_of_graphs","skillId":"math_graphs","subskillId":"math_graphs_q1","subject":"math","chapter":"graphs","topic":"Applications of graphs"}', 0),
  (613, 175, 'What do graphs help us identify?', 'text', 1, 'look at shape of graph', '{"why":"Graphs show how data changes over time or categories, revealing hidden patterns","sol":"Step 1: Identify key concept: Define the required principles for Applications of graphs.\nStep 2: Apply governing rule: Graphs show how data changes over time or categories, revealing hidden patterns\nStep 3: State the final conclusion: patterns and trends","steps":["Step 1: Identify key concept: Define the required principles for Applications of graphs.","Step 2: Apply governing rule: Graphs show how data changes over time or categories, revealing hidden patterns","Step 3: State the final conclusion: patterns and trends"],"options":[],"conceptId":"math_graphs_applications_of_graphs","skillId":"math_graphs","subskillId":"math_graphs_q2","subject":"math","chapter":"graphs","topic":"Applications of graphs"}', 1),
  (614, 175, 'Give one real-life use of graphs', 'text', 1, 'daily applications', '{"why":"Graphs are widely used to analyze weather, sales, population, and scientific data","sol":"Step 1: Identify key concept: Define the required principles for Applications of graphs.\nStep 2: Apply governing rule: Graphs are widely used to analyze weather, sales, population, and scientific data\nStep 3: State the final conclusion: weather forecasting or business analysis","steps":["Step 1: Identify key concept: Define the required principles for Applications of graphs.","Step 2: Apply governing rule: Graphs are widely used to analyze weather, sales, population, and scientific data","Step 3: State the final conclusion: weather forecasting or business analysis"],"options":[],"conceptId":"math_graphs_applications_of_graphs","skillId":"math_graphs","subskillId":"math_graphs_q3","subject":"math","chapter":"graphs","topic":"Applications of graphs"}', 2),
  (615, 176, 'Simplify the ratio 24:36', 'text', 1, 'HCF method', '{"why":"Ratios are simplified by dividing both terms by their highest common factor","sol":"Step 1: Find HCF of 24 and 36\nStep 2: HCF = 12\nStep 3: Divide both terms by 12\nStep 4: 24 ÷ 12 and 36 ÷ 12\nStep 5: Write simplified ratio","steps":["Step 1: Find HCF of 24 and 36","Step 2: HCF = 12","Step 3: Divide both terms by 12","Step 4: 24 ÷ 12 and 36 ÷ 12","Step 5: Write simplified ratio"],"options":[],"conceptId":"math_ratio_ratio_basics","skillId":"math_ratio","subskillId":"math_ratio_q1","subject":"math","chapter":"ratio","topic":"Ratio basics"}', 0),
  (616, 176, 'Divide 60 in the ratio 2:3', 'text', 1, 'total parts method', '{"why":"Total is split according to ratio parts","sol":"Step 1: Add ratio parts 2 + 3 = 5\nStep 2: Divide 60 by 5\nStep 3: One part = 12\nStep 4: Multiply 2 × 12 and 3 × 12\nStep 5: Find each share","steps":["Step 1: Add ratio parts 2 + 3 = 5","Step 2: Divide 60 by 5","Step 3: One part = 12","Step 4: Multiply 2 × 12 and 3 × 12","Step 5: Find each share"],"options":[],"conceptId":"math_ratio_ratio_basics","skillId":"math_ratio","subskillId":"math_ratio_q2","subject":"math","chapter":"ratio","topic":"Ratio basics"}', 1),
  (617, 176, 'Find ratio of 45 to 15 in simplest form', 'text', 1, 'divide both terms', '{"why":"Simplification reduces ratio to smallest whole numbers","sol":"Step 1: Write ratio 45:15\nStep 2: Find HCF = 15\nStep 3: Divide both terms by 15\nStep 4: Simplify result","steps":["Step 1: Write ratio 45:15","Step 2: Find HCF = 15","Step 3: Divide both terms by 15","Step 4: Simplify result"],"options":[],"conceptId":"math_ratio_ratio_basics","skillId":"math_ratio","subskillId":"math_ratio_q3","subject":"math","chapter":"ratio","topic":"Ratio basics"}', 2),
  (618, 176, 'Check if ratios 4:6 and 2:3 are equivalent', 'text', 1, 'compare simplified forms', '{"why":"Equivalent ratios reduce to the same simplest form","sol":"Step 1: Simplify 4:6\nStep 2: Divide both by 2 → 2:3\nStep 3: Compare with 2:3\nStep 4: Conclude equivalence","steps":["Step 1: Simplify 4:6","Step 2: Divide both by 2 → 2:3","Step 3: Compare with 2:3","Step 4: Conclude equivalence"],"options":[],"conceptId":"math_ratio_ratio_basics","skillId":"math_ratio","subskillId":"math_ratio_q4","subject":"math","chapter":"ratio","topic":"Ratio basics"}', 3),
  (619, 177, 'Divide 120 in the ratio 3:2', 'text', 1, 'total parts method', '{"why":"Total is distributed proportionally using ratio parts","sol":"Step 1: Add ratio parts 3 + 2 = 5\nStep 2: Divide 120 by 5\nStep 3: One part = 24\nStep 4: Multiply 3 × 24\nStep 5: Multiply 2 × 24\nStep 6: Write final split","steps":["Step 1: Add ratio parts 3 + 2 = 5","Step 2: Divide 120 by 5","Step 3: One part = 24","Step 4: Multiply 3 × 24","Step 5: Multiply 2 × 24","Step 6: Write final split"],"options":[],"conceptId":"math_ratio_dividing_in_ratio","skillId":"math_ratio","subskillId":"math_ratio_q1","subject":"math","chapter":"ratio","topic":"Dividing in ratio"}', 0),
  (620, 177, 'Divide 250 in the ratio 5:3', 'text', 1, 'part value method', '{"why":"Each share is proportional to its ratio weight","sol":"Step 1: Add ratio parts 5 + 3 = 8\nStep 2: Divide 250 by 8\nStep 3: One part = 31.25\nStep 4: Multiply 5 × 31.25\nStep 5: Multiply 3 × 31.25\nStep 6: Write final values","steps":["Step 1: Add ratio parts 5 + 3 = 8","Step 2: Divide 250 by 8","Step 3: One part = 31.25","Step 4: Multiply 5 × 31.25","Step 5: Multiply 3 × 31.25","Step 6: Write final values"],"options":[],"conceptId":"math_ratio_dividing_in_ratio","skillId":"math_ratio","subskillId":"math_ratio_q2","subject":"math","chapter":"ratio","topic":"Dividing in ratio"}', 1),
  (621, 177, 'Check if 40:60 simplifies correctly to 2:3', 'text', 1, 'simplification check', '{"why":"Both ratios represent the same proportional relationship","sol":"Step 1: Write ratio 40:60\nStep 2: Find HCF = 20\nStep 3: Divide both terms by 20\nStep 4: Get simplified form\nStep 5: Compare with 2:3","steps":["Step 1: Write ratio 40:60","Step 2: Find HCF = 20","Step 3: Divide both terms by 20","Step 4: Get simplified form","Step 5: Compare with 2:3"],"options":[],"conceptId":"math_ratio_dividing_in_ratio","skillId":"math_ratio","subskillId":"math_ratio_q3","subject":"math","chapter":"ratio","topic":"Dividing in ratio"}', 2),
  (622, 177, 'Find value of one part if 84 is divided in ratio 2:5', 'text', 1, 'total parts method', '{"why":"Each unit of ratio is found by dividing total by sum of parts","sol":"Step 1: Add ratio parts 2 + 5 = 7\nStep 2: Divide 84 by 7\nStep 3: One part = 12\nStep 4: Use part value for distribution","steps":["Step 1: Add ratio parts 2 + 5 = 7","Step 2: Divide 84 by 7","Step 3: One part = 12","Step 4: Use part value for distribution"],"options":[],"conceptId":"math_ratio_dividing_in_ratio","skillId":"math_ratio","subskillId":"math_ratio_q4","subject":"math","chapter":"ratio","topic":"Dividing in ratio"}', 3),
  (623, 178, 'Solve for x: 6:9 = x:27', 'text', 1, 'cross multiplication', '{"why":"Cross multiplication removes ratios and forms a solvable equation","sol":"Step 1: Write proportion 6/9 = x/27\nStep 2: Cross multiply → 6 × 27 = 9x\nStep 3: Compute 162 = 9x\nStep 4: Divide both sides by 9\nStep 5: Solve for x","steps":["Step 1: Write proportion 6/9 = x/27","Step 2: Cross multiply → 6 × 27 = 9x","Step 3: Compute 162 = 9x","Step 4: Divide both sides by 9","Step 5: Solve for x"],"options":[],"conceptId":"math_ratio_proportion","skillId":"math_ratio","subskillId":"math_ratio_q1","subject":"math","chapter":"ratio","topic":"Proportion"}', 0),
  (624, 178, 'Solve for x: 8:12 = 20:x', 'text', 1, 'diagonal multiplication', '{"why":"Proportions are solved by equating cross products","sol":"Step 1: Write 8/12 = 20/x\nStep 2: Cross multiply → 8x = 240\nStep 3: Divide both sides by 8\nStep 4: Solve for x","steps":["Step 1: Write 8/12 = 20/x","Step 2: Cross multiply → 8x = 240","Step 3: Divide both sides by 8","Step 4: Solve for x"],"options":[],"conceptId":"math_ratio_proportion","skillId":"math_ratio","subskillId":"math_ratio_q2","subject":"math","chapter":"ratio","topic":"Proportion"}', 1),
  (625, 178, 'Check if 3:5 and 12:20 form a proportion', 'text', 1, 'simplify ratio', '{"why":"Equivalent ratios form a valid proportion","sol":"Step 1: Simplify 12:20 by dividing by 4\nStep 2: Get 3:5\nStep 3: Compare both ratios\nStep 4: Confirm equality","steps":["Step 1: Simplify 12:20 by dividing by 4","Step 2: Get 3:5","Step 3: Compare both ratios","Step 4: Confirm equality"],"options":[],"conceptId":"math_ratio_proportion","skillId":"math_ratio","subskillId":"math_ratio_q3","subject":"math","chapter":"ratio","topic":"Proportion"}', 2),
  (626, 178, 'What is the value of x in 7/ x = 14/28', 'text', 1, 'cross multiply', '{"why":"Cross multiplication converts proportion into linear equation","sol":"Step 1: Cross multiply → 7 × 28 = 14x\nStep 2: Compute 196 = 14x\nStep 3: Divide both sides by 14\nStep 4: Solve for x","steps":["Step 1: Cross multiply → 7 × 28 = 14x","Step 2: Compute 196 = 14x","Step 3: Divide both sides by 14","Step 4: Solve for x"],"options":[],"conceptId":"math_ratio_proportion","skillId":"math_ratio","subskillId":"math_ratio_q4","subject":"math","chapter":"ratio","topic":"Proportion"}', 3),
  (627, 179, 'If 6 notebooks cost 90, find the cost of 1 notebook', 'text', 1, 'unit rate', '{"why":"Unit cost is found by dividing total cost by number of items","sol":"Step 1: Write total cost = 90 and quantity = 6\nStep 2: Compute 90 ÷ 6\nStep 3: Find cost per notebook\nStep 4: State unit price","steps":["Step 1: Write total cost = 90 and quantity = 6","Step 2: Compute 90 ÷ 6","Step 3: Find cost per notebook","Step 4: State unit price"],"options":[],"conceptId":"math_ratio_direct_proportion","skillId":"math_ratio","subskillId":"math_ratio_q1","subject":"math","chapter":"ratio","topic":"Direct proportion"}', 0),
  (628, 179, 'Find k if y = kx, when y = 36 and x = 9', 'text', 1, 'constant of proportionality', '{"why":"k represents constant ratio between y and x","sol":"Step 1: Write y = kx\nStep 2: Substitute 36 = k × 9\nStep 3: Divide both sides by 9\nStep 4: Solve for k","steps":["Step 1: Write y = kx","Step 2: Substitute 36 = k × 9","Step 3: Divide both sides by 9","Step 4: Solve for k"],"options":[],"conceptId":"math_ratio_direct_proportion","skillId":"math_ratio","subskillId":"math_ratio_q2","subject":"math","chapter":"ratio","topic":"Direct proportion"}', 1),
  (629, 179, 'If y = 5x, find y when x = 7', 'text', 1, 'substitution', '{"why":"Direct proportion uses substitution into linear equation","sol":"Step 1: Write equation y = 5x\nStep 2: Substitute x = 7\nStep 3: Multiply 5 × 7\nStep 4: Compute y value","steps":["Step 1: Write equation y = 5x","Step 2: Substitute x = 7","Step 3: Multiply 5 × 7","Step 4: Compute y value"],"options":[],"conceptId":"math_ratio_direct_proportion","skillId":"math_ratio","subskillId":"math_ratio_q3","subject":"math","chapter":"ratio","topic":"Direct proportion"}', 2),
  (630, 179, 'If x doubles in y = 3x, what happens to y when x changes from 4 to 8?', 'text', 1, 'scaling', '{"why":"In direct proportion, scaling x scales y by same factor","sol":"Step 1: Compute y when x = 4 → y = 3 × 4\nStep 2: Compute y when x = 8 → y = 3 × 8\nStep 3: Compare both results\nStep 4: Identify relationship","steps":["Step 1: Compute y when x = 4 → y = 3 × 4","Step 2: Compute y when x = 8 → y = 3 × 8","Step 3: Compare both results","Step 4: Identify relationship"],"options":[],"conceptId":"math_ratio_direct_proportion","skillId":"math_ratio","subskillId":"math_ratio_q4","subject":"math","chapter":"ratio","topic":"Direct proportion"}', 3),
  (631, 180, 'If y is inversely proportional to x and x = 6, y = 12, find k in x × y = k', 'text', 1, 'constant of inverse proportion', '{"why":"In inverse proportion, the product of x and y stays constant","sol":"Step 1: Write k = x × y\nStep 2: Substitute values k = 6 × 12\nStep 3: Multiply to find k","steps":["Step 1: Write k = x × y","Step 2: Substitute values k = 6 × 12","Step 3: Multiply to find k"],"options":[],"conceptId":"math_ratio_inverse_proportion","skillId":"math_ratio","subskillId":"math_ratio_q1","subject":"math","chapter":"ratio","topic":"Inverse proportion"}', 0),
  (632, 180, 'If x = 9 and y = 8 in an inverse proportion, find k', 'text', 1, 'multiply values', '{"why":"Inverse proportion means x × y remains constant","sol":"Step 1: Write k = x × y\nStep 2: Substitute k = 9 × 8\nStep 3: Compute product","steps":["Step 1: Write k = x × y","Step 2: Substitute k = 9 × 8","Step 3: Compute product"],"options":[],"conceptId":"math_ratio_inverse_proportion","skillId":"math_ratio","subskillId":"math_ratio_q2","subject":"math","chapter":"ratio","topic":"Inverse proportion"}', 1),
  (633, 180, 'If y is inversely proportional to x and x = 3, y = 20, find k', 'text', 1, 'constant product rule', '{"why":"The product of variables remains unchanged in inverse proportion","sol":"Step 1: Use k = x × y\nStep 2: Substitute 3 × 20\nStep 3: Calculate k","steps":["Step 1: Use k = x × y","Step 2: Substitute 3 × 20","Step 3: Calculate k"],"options":[],"conceptId":"math_ratio_inverse_proportion","skillId":"math_ratio","subskillId":"math_ratio_q3","subject":"math","chapter":"ratio","topic":"Inverse proportion"}', 2),
  (634, 180, 'If x = 5 and y = 14 in inverse proportion, determine k', 'text', 1, 'multiply', '{"why":"Inverse proportion keeps product of variables constant","sol":"Step 1: Write formula k = x × y\nStep 2: Substitute values 5 × 14\nStep 3: Compute result","steps":["Step 1: Write formula k = x × y","Step 2: Substitute values 5 × 14","Step 3: Compute result"],"options":[],"conceptId":"math_ratio_inverse_proportion","skillId":"math_ratio","subskillId":"math_ratio_q4","subject":"math","chapter":"ratio","topic":"Inverse proportion"}', 3),
  (635, 180, 'If y is inversely proportional to x and x = 2, y = 30, find k', 'text', 1, 'constant product', '{"why":"Inverse proportion is defined by a constant product relationship","sol":"Step 1: Write k = x × y\nStep 2: Substitute 2 × 30\nStep 3: Multiply to get k","steps":["Step 1: Write k = x × y","Step 2: Substitute 2 × 30","Step 3: Multiply to get k"],"options":[],"conceptId":"math_ratio_inverse_proportion","skillId":"math_ratio","subskillId":"math_ratio_q5","subject":"math","chapter":"ratio","topic":"Inverse proportion"}', 4),
  (636, 181, 'A teacher records the marks 34, 47, 51 and 63 for four learners. What do these recorded values represent?', 'text', 1, 'Think about what recorded observations are called.', '{"why":"The marks are recorded information, so they form a data set.","sol":"Step 1: The numbers are recorded observations.\nStep 2: A collection of recorded observations is called data.","steps":["Step 1: The numbers are recorded observations.","Step 2: A collection of recorded observations is called data."],"options":[],"conceptId":"math_statistics_meaning_of_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Meaning of Data"}', 0),
  (637, 181, 'A class records the favourite fruits of its learners as mango, banana, orange and mango. Are these observations data?', 'text', 1, 'Data does not have to be numerical.', '{"why":"Data can be numerical or non-numerical.","sol":"Step 1: The fruit names are recorded observations.\nStep 2: Recorded observations are data even when they are words rather than numbers.","steps":["Step 1: The fruit names are recorded observations.","Step 2: Recorded observations are data even when they are words rather than numbers."],"options":[],"conceptId":"math_statistics_meaning_of_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Meaning of Data"}', 1),
  (638, 181, 'A learner writes 12, 15, 9 and 20 after counting the books read by four learners. What are these values?', 'text', 1, 'They are recorded observations.', '{"why":"The numbers are recorded information collected for a purpose.","sol":"Step 1: The learner has recorded four observations.\nStep 2: Those observations form a data set.","steps":["Step 1: The learner has recorded four observations.","Step 2: Those observations form a data set."],"options":[],"conceptId":"math_statistics_meaning_of_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Meaning of Data"}', 2),
  (639, 182, 'A teacher calculates the average mark of a class from the recorded test scores. Is the teacher using data or statistics?', 'text', 1, 'The marks are data. What is being done to the marks?', '{"why":"The teacher is performing a statistical operation on collected data.","sol":"Step 1: The recorded marks are data.\nStep 2: Calculating an average is analysing the data.\nStep 3: Analysing data is part of statistics.","steps":["Step 1: The recorded marks are data.","Step 2: Calculating an average is analysing the data.","Step 3: Analysing data is part of statistics."],"options":[],"conceptId":"math_statistics_meaning_of_statistics","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Meaning of Statistics"}', 0),
  (640, 182, 'A school records the ages of 100 learners. Are the recorded ages themselves statistics?', 'text', 1, 'Separate the information collected from what we do with it.', '{"why":"The recorded ages are the raw information being used in statistics.","sol":"Step 1: The ages are recorded observations.\nStep 2: Recorded observations are data.\nStep 3: They become part of statistical work when they are organised, analysed or interpreted.","steps":["Step 1: The ages are recorded observations.","Step 2: Recorded observations are data.","Step 3: They become part of statistical work when they are organised, analysed or interpreted."],"options":[],"conceptId":"math_statistics_meaning_of_statistics","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Meaning of Statistics"}', 1),
  (641, 182, 'A learner draws a graph from a table of collected marks. Is this part of statistics?', 'text', 1, 'Think about representing data.', '{"why":"Representing data is one of the main activities in statistics.","sol":"Step 1: The marks are data.\nStep 2: The learner is representing the data graphically.\nStep 3: Representation of data is part of statistics.","steps":["Step 1: The marks are data.","Step 2: The learner is representing the data graphically.","Step 3: Representation of data is part of statistics."],"options":[],"conceptId":"math_statistics_meaning_of_statistics","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Meaning of Statistics"}', 2),
  (642, 183, 'A learner asks 20 classmates how much money they spend on lunch each day and records their answers. Is this primary or secondary data?', 'text', 1, 'Who collected the information?', '{"why":"It was collected directly by the investigator.","sol":"Step 1: The learner directly asked the classmates.\nStep 2: The learner collected the information for the investigation.\nStep 3: Therefore, the data is primary data.","steps":["Step 1: The learner directly asked the classmates.","Step 2: The learner collected the information for the investigation.","Step 3: Therefore, the data is primary data."],"options":[],"conceptId":"math_statistics_primary_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Primary Data"}', 0),
  (643, 183, 'A teacher measures the heights of learners in her class for a school investigation. What type of data is collected?', 'text', 1, 'The teacher is collecting the measurements directly.', '{"why":"The measurements come directly from the original investigation.","sol":"Step 1: The teacher measures the learners herself.\nStep 2: The measurements are collected directly.\nStep 3: Therefore, they are primary data.","steps":["Step 1: The teacher measures the learners herself.","Step 2: The measurements are collected directly.","Step 3: Therefore, they are primary data."],"options":[],"conceptId":"math_statistics_primary_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Primary Data"}', 1),
  (644, 183, 'A researcher interviews 50 farmers and records their answers. Is the information primary data?', 'text', 1, 'Look at who obtained the information.', '{"why":"The researcher collected the information directly.","sol":"Step 1: The researcher directly interviews the farmers.\nStep 2: The researcher obtains the information firsthand.\nStep 3: Therefore, the information is primary data.","steps":["Step 1: The researcher directly interviews the farmers.","Step 2: The researcher obtains the information firsthand.","Step 3: Therefore, the information is primary data."],"options":[],"conceptId":"math_statistics_primary_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Primary Data"}', 2),
  (645, 184, 'A student uses population figures from a published government report. Is this primary or secondary data?', 'text', 1, 'Did the student collect the population figures herself?', '{"why":"The information was collected previously by another source.","sol":"Step 1: The figures had already been collected and published.\nStep 2: The student is using existing information.\nStep 3: Therefore, the data is secondary data.","steps":["Step 1: The figures had already been collected and published.","Step 2: The student is using existing information.","Step 3: Therefore, the data is secondary data."],"options":[],"conceptId":"math_statistics_secondary_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Secondary Data"}', 0),
  (646, 184, 'A researcher uses rainfall records collected by another organisation five years earlier. What type of data is this?', 'text', 1, 'The researcher did not originally collect the measurements.', '{"why":"The researcher is using previously collected information.","sol":"Step 1: The rainfall measurements already existed.\nStep 2: Another organisation collected them.\nStep 3: Therefore, they are secondary data for the researcher.","steps":["Step 1: The rainfall measurements already existed.","Step 2: Another organisation collected them.","Step 3: Therefore, they are secondary data for the researcher."],"options":[],"conceptId":"math_statistics_secondary_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Secondary Data"}', 1),
  (647, 184, 'A learner measures today''s temperature herself and records it. Is this secondary data?', 'text', 1, 'Who collected the measurement?', '{"why":"The learner collected the measurement directly.","sol":"Step 1: The learner directly measures the temperature.\nStep 2: The measurement is collected firsthand.\nStep 3: Therefore, it is primary data, not secondary data.","steps":["Step 1: The learner directly measures the temperature.","Step 2: The measurement is collected firsthand.","Step 3: Therefore, it is primary data, not secondary data."],"options":[],"conceptId":"math_statistics_secondary_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Secondary Data"}', 2),
  (648, 185, 'A school records the favourite subjects of learners as Mathematics, English, Biology and Physics. What type of data is this?', 'text', 1, 'Are the values measurements or categories?', '{"why":"The observations describe categories rather than numerical measurements.","sol":"Step 1: The values are names of subjects.\nStep 2: Subject names are categories.\nStep 3: Therefore, the data is qualitative.","steps":["Step 1: The values are names of subjects.","Step 2: Subject names are categories.","Step 3: Therefore, the data is qualitative."],"options":[],"conceptId":"math_statistics_qualitative_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Qualitative Data"}', 0),
  (649, 185, 'A survey records eye colours as brown, black and blue. Is this qualitative data?', 'text', 1, 'Eye colour is a category.', '{"why":"Eye colour describes a category or quality.","sol":"Step 1: The observations identify types of eye colour.\nStep 2: These are categories.\nStep 3: Therefore, the data is qualitative.","steps":["Step 1: The observations identify types of eye colour.","Step 2: These are categories.","Step 3: Therefore, the data is qualitative."],"options":[],"conceptId":"math_statistics_qualitative_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Qualitative Data"}', 1),
  (650, 185, 'A survey records transport methods as bus, walking, bicycle and motorcycle. What type of data is this?', 'text', 1, 'Look at what the observations represent.', '{"why":"The observations are categories describing types of transport.","sol":"Step 1: Each response identifies a transport category.\nStep 2: The responses are not measurements.\nStep 3: Therefore, the data is qualitative.","steps":["Step 1: Each response identifies a transport category.","Step 2: The responses are not measurements.","Step 3: Therefore, the data is qualitative."],"options":[],"conceptId":"math_statistics_qualitative_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Qualitative Data"}', 2),
  (651, 186, 'A teacher records the marks 45, 56, 72 and 81. What type of data are the marks?', 'text', 1, 'The observations are numerical.', '{"why":"The marks are numerical values.","sol":"Step 1: The observations are numbers.\nStep 2: They represent measured or counted quantities.\nStep 3: Therefore, the data is quantitative.","steps":["Step 1: The observations are numbers.","Step 2: They represent measured or counted quantities.","Step 3: Therefore, the data is quantitative."],"options":[],"conceptId":"math_statistics_quantitative_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Quantitative Data"}', 0),
  (652, 186, 'A survey records the number of siblings for five learners as 0, 2, 1, 3 and 4. What type of data is this?', 'text', 1, 'The numbers are counts.', '{"why":"The observations are numerical counts.","sol":"Step 1: Each value counts the number of siblings.\nStep 2: Counts are numerical data.\nStep 3: Therefore, the data is quantitative.","steps":["Step 1: Each value counts the number of siblings.","Step 2: Counts are numerical data.","Step 3: Therefore, the data is quantitative."],"options":[],"conceptId":"math_statistics_quantitative_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Quantitative Data"}', 1),
  (653, 186, 'A teacher records the heights of learners in centimetres. Is this quantitative data?', 'text', 1, 'Height is measured using numbers.', '{"why":"Height is a numerical measurement.","sol":"Step 1: Height is measured numerically.\nStep 2: The measurements are expressed in centimetres.\nStep 3: Therefore, the data is quantitative.","steps":["Step 1: Height is measured numerically.","Step 2: The measurements are expressed in centimetres.","Step 3: Therefore, the data is quantitative."],"options":[],"conceptId":"math_statistics_quantitative_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Quantitative Data"}', 2),
  (654, 187, 'The number of books owned by learners is recorded. Is this discrete or continuous data?', 'text', 1, 'Are books counted or measured?', '{"why":"The number of books is obtained by counting separate objects.","sol":"Step 1: Books are counted.\nStep 2: A learner can have 4 books or 5 books, but not 4.5 books as a count of complete books.\nStep 3: Therefore, the data is discrete.","steps":["Step 1: Books are counted.","Step 2: A learner can have 4 books or 5 books, but not 4.5 books as a count of complete books.","Step 3: Therefore, the data is discrete."],"options":[],"conceptId":"math_statistics_discrete_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Discrete Data"}', 0),
  (655, 187, 'A school records the number of learners in each class. What type of quantitative data is this?', 'text', 1, 'Learners are counted.', '{"why":"The number of learners is a count.","sol":"Step 1: The school counts the learners.\nStep 2: The values are separate whole-number counts.\nStep 3: Therefore, the data is discrete.","steps":["Step 1: The school counts the learners.","Step 2: The values are separate whole-number counts.","Step 3: Therefore, the data is discrete."],"options":[],"conceptId":"math_statistics_discrete_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Discrete Data"}', 1),
  (656, 187, 'A team records the number of goals scored in each match. Is the number of goals discrete?', 'text', 1, 'Can goals be counted?', '{"why":"The number of goals is a count of separate events.","sol":"Step 1: Goals occur as separate events.\nStep 2: The number of goals is counted.\nStep 3: Therefore, the data is discrete.","steps":["Step 1: Goals occur as separate events.","Step 2: The number of goals is counted.","Step 3: Therefore, the data is discrete."],"options":[],"conceptId":"math_statistics_discrete_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Discrete Data"}', 2),
  (657, 188, 'The heights of learners are measured in centimetres. Is height discrete or continuous?', 'text', 1, 'Height is measured, not counted.', '{"why":"Height can take measured values within a range.","sol":"Step 1: Height is obtained by measurement.\nStep 2: A height such as 160 cm can be measured more precisely as 160.4 cm.\nStep 3: Therefore, height is continuous data.","steps":["Step 1: Height is obtained by measurement.","Step 2: A height such as 160 cm can be measured more precisely as 160.4 cm.","Step 3: Therefore, height is continuous data."],"options":[],"conceptId":"math_statistics_continuous_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Continuous Data"}', 0),
  (658, 188, 'The time taken by runners to complete a race is recorded. Is time discrete or continuous?', 'text', 1, 'Can time have values between two whole numbers?', '{"why":"Time can take many possible values within an interval.","sol":"Step 1: Time is measured.\nStep 2: A runner can take 12.1 seconds, 12.15 seconds, 12.153 seconds, and so on.\nStep 3: Therefore, time is continuous.","steps":["Step 1: Time is measured.","Step 2: A runner can take 12.1 seconds, 12.15 seconds, 12.153 seconds, and so on.","Step 3: Therefore, time is continuous."],"options":[],"conceptId":"math_statistics_continuous_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Continuous Data"}', 1),
  (659, 188, 'The mass of bags of maize is measured. What type of data is the mass?', 'text', 1, 'Mass is measured using units such as kilograms.', '{"why":"Mass can take measured values between whole numbers.","sol":"Step 1: Mass is obtained by measurement.\nStep 2: It can have decimal values such as 49.5 kg.\nStep 3: Therefore, mass is continuous data.","steps":["Step 1: Mass is obtained by measurement.","Step 2: It can have decimal values such as 49.5 kg.","Step 3: Therefore, mass is continuous data."],"options":[],"conceptId":"math_statistics_continuous_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Continuous Data"}', 2),
  (660, 189, 'A school wants to study the heights of all 800 learners in the school. What is the population?', 'text', 1, 'Identify the complete group being studied.', '{"why":"The population is the complete group that the investigation is about.","sol":"Step 1: The investigation concerns all learners in the school.\nStep 2: There are 800 learners.\nStep 3: Therefore, all 800 learners form the population.","steps":["Step 1: The investigation concerns all learners in the school.","Step 2: There are 800 learners.","Step 3: Therefore, all 800 learners form the population."],"options":[],"conceptId":"math_statistics_population","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Population"}', 0),
  (661, 189, 'A factory wants to study all 2,000 bottles produced on Monday. What is the population?', 'text', 1, 'Look for the entire group under investigation.', '{"why":"The population is the complete set of objects being studied.","sol":"Step 1: The investigation concerns bottles produced on Monday.\nStep 2: There were 2,000 such bottles.\nStep 3: Therefore, all 2,000 bottles form the population.","steps":["Step 1: The investigation concerns bottles produced on Monday.","Step 2: There were 2,000 such bottles.","Step 3: Therefore, all 2,000 bottles form the population."],"options":[],"conceptId":"math_statistics_population","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Population"}', 1),
  (662, 189, 'A researcher wants to study all Form 2 learners in a school. Are five selected Form 2 learners the population?', 'text', 1, 'Compare five learners with the complete group.', '{"why":"The population is the entire group being studied, not just part of it.","sol":"Step 1: The investigation concerns all Form 2 learners.\nStep 2: Five learners are only part of the complete group.\nStep 3: Therefore, the five learners are not the population.","steps":["Step 1: The investigation concerns all Form 2 learners.","Step 2: Five learners are only part of the complete group.","Step 3: Therefore, the five learners are not the population."],"options":[],"conceptId":"math_statistics_population","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Population"}', 2),
  (663, 190, 'A school has 1,200 learners and a researcher selects 120 learners for a study. What is the sample?', 'text', 1, 'The sample is the selected part.', '{"why":"A sample is the selected part of the population.","sol":"Step 1: The population contains all 1,200 learners.\nStep 2: The researcher selected 120 learners.\nStep 3: Therefore, the 120 selected learners form the sample.","steps":["Step 1: The population contains all 1,200 learners.","Step 2: The researcher selected 120 learners.","Step 3: Therefore, the 120 selected learners form the sample."],"options":[],"conceptId":"math_statistics_sample","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Sample"}', 0),
  (664, 190, 'A factory produces 4,000 items and an inspector checks 100 of them. What is the population?', 'text', 1, 'The population is the complete group.', '{"why":"The population is the complete group under investigation.","sol":"Step 1: All 4,000 items were produced.\nStep 2: Only 100 were selected for inspection.\nStep 3: Therefore, the population is all 4,000 items.","steps":["Step 1: All 4,000 items were produced.","Step 2: Only 100 were selected for inspection.","Step 3: Therefore, the population is all 4,000 items."],"options":[],"conceptId":"math_statistics_sample","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Sample"}', 1),
  (665, 190, 'A researcher wants to study 2,000 students but selects 200 students for the investigation. Which group is the sample?', 'text', 1, 'Which group was actually selected?', '{"why":"The sample is the selected subset of the population.","sol":"Step 1: The 2,000 students form the complete population.\nStep 2: The researcher selected 200 students.\nStep 3: Therefore, the 200 selected students form the sample.","steps":["Step 1: The 2,000 students form the complete population.","Step 2: The researcher selected 200 students.","Step 3: Therefore, the 200 selected students form the sample."],"options":[],"conceptId":"math_statistics_sample","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Sample"}', 2),
  (666, 191, 'A teacher asks learners which subjects they like most. What is the source of the data?', 'text', 1, 'Who provides the information?', '{"why":"The source is the person or record from which the information comes.","sol":"Step 1: The teacher asks the learners.\nStep 2: The learners provide the answers.\nStep 3: Therefore, the learners are the source of the data.","steps":["Step 1: The teacher asks the learners.","Step 2: The learners provide the answers.","Step 3: Therefore, the learners are the source of the data."],"options":[],"conceptId":"math_statistics_sources_of_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Sources of Data"}', 0),
  (667, 191, 'A researcher uses a school''s admission records to find the number of learners enrolled. What is the source?', 'text', 1, 'Where did the information come from?', '{"why":"The records contain the information being used.","sol":"Step 1: The researcher did not create the original records.\nStep 2: The information comes from the school''s admission records.\nStep 3: Therefore, the records are the source.","steps":["Step 1: The researcher did not create the original records.","Step 2: The information comes from the school''s admission records.","Step 3: Therefore, the records are the source."],"options":[],"conceptId":"math_statistics_sources_of_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Sources of Data"}', 1),
  (668, 191, 'A researcher measures the heights of learners. Are the measuring instruments the main source of the data?', 'text', 1, 'The instrument measures, but whose height is being recorded?', '{"why":"The instrument is a collection tool; the source is the group from which the information originates.","sol":"Step 1: The instrument is used to obtain the measurements.\nStep 2: The measurements describe the learners.\nStep 3: Therefore, the learners are the source, while the instrument is a tool for collecting the data.","steps":["Step 1: The instrument is used to obtain the measurements.","Step 2: The measurements describe the learners.","Step 3: Therefore, the learners are the source, while the instrument is a tool for collecting the data."],"options":[],"conceptId":"math_statistics_sources_of_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Sources of Data"}', 2),
  (669, 192, 'A researcher gives 100 learners a form containing questions and collects their completed answers. Which method is being used?', 'text', 1, 'Think about a written set of questions.', '{"why":"A questionnaire collects information through a set of questions.","sol":"Step 1: The learners are given questions to answer.\nStep 2: Their answers are collected using a form.\nStep 3: Therefore, the method is a questionnaire.","steps":["Step 1: The learners are given questions to answer.","Step 2: Their answers are collected using a form.","Step 3: Therefore, the method is a questionnaire."],"options":[],"conceptId":"math_statistics_methods_of_collecting_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Methods of Collecting Data"}', 0),
  (670, 192, 'A researcher watches vehicles passing a road and records their numbers. Which method is being used?', 'text', 1, 'The researcher is watching and recording.', '{"why":"The information is obtained by watching and recording events.","sol":"Step 1: The researcher does not ask the drivers questions.\nStep 2: The researcher watches what happens.\nStep 3: Therefore, the method is observation.","steps":["Step 1: The researcher does not ask the drivers questions.","Step 2: The researcher watches what happens.","Step 3: Therefore, the method is observation."],"options":[],"conceptId":"math_statistics_methods_of_collecting_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Methods of Collecting Data"}', 1),
  (671, 192, 'A teacher uses a measuring tape to record the heights of learners. Which method is used?', 'text', 1, 'What is the teacher doing to obtain the values?', '{"why":"The values are obtained by directly measuring a characteristic.","sol":"Step 1: The teacher uses an instrument.\nStep 2: The teacher obtains numerical values by measuring height.\nStep 3: Therefore, the method is measurement.","steps":["Step 1: The teacher uses an instrument.","Step 2: The teacher obtains numerical values by measuring height.","Step 3: Therefore, the method is measurement."],"options":[],"conceptId":"math_statistics_methods_of_collecting_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Methods of Collecting Data"}', 2),
  (672, 193, 'A value occurs 8 times. How many tally marks should be recorded?', 'text', 1, 'Separate the 8 observations into groups of five.', '{"why":"Tally marks record each occurrence, with groups of five making counting easier.","sol":"Step 1: The first five observations make one group of five.\nStep 2: There are 3 observations remaining.\nStep 3: Therefore, the tally represents 5 + 3 = 8.","steps":["Step 1: The first five observations make one group of five.","Step 2: There are 3 observations remaining.","Step 3: Therefore, the tally represents 5 + 3 = 8."],"options":[],"conceptId":"math_statistics_tally_marks","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Tally Marks"}', 0),
  (673, 193, 'A value has tally marks representing 5 + 5 + 2 observations. What is its frequency?', 'text', 1, 'Add the groups.', '{"why":"The frequency is the total number represented by all the tally groups.","sol":"Step 1: The first group represents 5.\nStep 2: The second group represents 5.\nStep 3: The remaining marks represent 2.\nStep 4: 5 + 5 + 2 = 12.","steps":["Step 1: The first group represents 5.","Step 2: The second group represents 5.","Step 3: The remaining marks represent 2.","Step 4: 5 + 5 + 2 = 12."],"options":[],"conceptId":"math_statistics_tally_marks","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Tally Marks"}', 1),
  (674, 193, 'A tally shows one group of five and four additional marks. What frequency does it represent?', 'text', 1, 'A complete tally group represents 5.', '{"why":"The tally represents nine occurrences.","sol":"Step 1: One complete group = 5.\nStep 2: Four additional marks = 4.\nStep 3: 5 + 4 = 9.","steps":["Step 1: One complete group = 5.","Step 2: Four additional marks = 4.","Step 3: 5 + 4 = 9."],"options":[],"conceptId":"math_statistics_tally_marks","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Tally Marks"}', 2),
  (675, 194, 'Find the frequency of 7 in the data: 3, 7, 5, 7, 2, 7, 4.', 'text', 1, 'Count how many times 7 appears.', '{"why":"Frequency is the number of times a value occurs.","sol":"Step 1: Read through the data.\nStep 2: The value 7 appears in the second position.\nStep 3: It appears again in the fourth position.\nStep 4: It appears again in the sixth position.\nStep 5: Therefore, it appears 3 times.","steps":["Step 1: Read through the data.","Step 2: The value 7 appears in the second position.","Step 3: It appears again in the fourth position.","Step 4: It appears again in the sixth position.","Step 5: Therefore, it appears 3 times."],"options":[],"conceptId":"math_statistics_frequency","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Frequency"}', 0),
  (676, 194, 'Find the frequency of 4 in: 4, 2, 5, 4, 6, 4, 1, 4.', 'text', 1, 'Count every occurrence of 4.', '{"why":"The value 4 occurs four times.","sol":"Step 1: 4 appears first.\nStep 2: 4 appears again in the fourth position.\nStep 3: 4 appears again in the sixth position.\nStep 4: 4 appears again in the eighth position.\nStep 5: Therefore, the frequency is 4.","steps":["Step 1: 4 appears first.","Step 2: 4 appears again in the fourth position.","Step 3: 4 appears again in the sixth position.","Step 4: 4 appears again in the eighth position.","Step 5: Therefore, the frequency is 4."],"options":[],"conceptId":"math_statistics_frequency","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Frequency"}', 1),
  (677, 194, 'In the data 2, 2, 3, 4, 2, 5, 6, 2, what is the frequency of 2?', 'text', 1, 'Count all the 2s.', '{"why":"The value 2 occurs four times.","sol":"Step 1: There is a 2 in the first position.\nStep 2: There is a 2 in the second position.\nStep 3: There is a 2 in the fifth position.\nStep 4: There is a 2 in the eighth position.\nStep 5: Therefore, the frequency is 4.","steps":["Step 1: There is a 2 in the first position.","Step 2: There is a 2 in the second position.","Step 3: There is a 2 in the fifth position.","Step 4: There is a 2 in the eighth position.","Step 5: Therefore, the frequency is 4."],"options":[],"conceptId":"math_statistics_frequency","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Frequency"}', 2),
  (678, 195, 'For the data 1, 2, 1, 3, 2, 1, identify the frequency of 1.', 'text', 1, 'Count the number of times 1 occurs.', '{"why":"The frequency tells us how many observations have the value 1.","sol":"Step 1: The value 1 occurs first.\nStep 2: It occurs again in the third position.\nStep 3: It occurs again in the sixth position.\nStep 4: Therefore, its frequency is 3.","steps":["Step 1: The value 1 occurs first.","Step 2: It occurs again in the third position.","Step 3: It occurs again in the sixth position.","Step 4: Therefore, its frequency is 3."],"options":[],"conceptId":"math_statistics_frequency_distribution_table","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Frequency Distribution Table"}', 0),
  (679, 195, 'For the data 2, 4, 2, 5, 4, 2, what is the frequency of 4?', 'text', 1, 'Count the 4s.', '{"why":"The value 4 appears twice.","sol":"Step 1: 4 occurs in the second position.\nStep 2: 4 occurs again in the fifth position.\nStep 3: Therefore, the frequency of 4 is 2.","steps":["Step 1: 4 occurs in the second position.","Step 2: 4 occurs again in the fifth position.","Step 3: Therefore, the frequency of 4 is 2."],"options":[],"conceptId":"math_statistics_frequency_distribution_table","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Frequency Distribution Table"}', 1),
  (680, 195, 'A frequency table has frequencies 3, 5, 2 and 4. How many observations are represented altogether?', 'text', 1, 'Add all frequencies.', '{"why":"The sum of all frequencies gives the total number of observations.","sol":"Step 1: Frequency 1 = 3.\nStep 2: Frequency 2 = 5.\nStep 3: Frequency 3 = 2.\nStep 4: Frequency 4 = 4.\nStep 5: 3 + 5 + 2 + 4 = 14.","steps":["Step 1: Frequency 1 = 3.","Step 2: Frequency 2 = 5.","Step 3: Frequency 3 = 2.","Step 4: Frequency 4 = 4.","Step 5: 3 + 5 + 2 + 4 = 14."],"options":[],"conceptId":"math_statistics_frequency_distribution_table","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Frequency Distribution Table"}', 2),
  (681, 196, 'Construct the frequencies for the data: 1, 2, 1, 3, 2, 1.', 'text', 1, 'List 1, 2 and 3, then count each.', '{"why":"Each frequency is obtained by counting that value in the original data.","sol":"Step 1: Value 1 occurs 3 times.\nStep 2: Value 2 occurs 2 times.\nStep 3: Value 3 occurs 1 time.\nStep 4: Therefore, the frequencies are 3, 2 and 1 respectively.","steps":["Step 1: Value 1 occurs 3 times.","Step 2: Value 2 occurs 2 times.","Step 3: Value 3 occurs 1 time.","Step 4: Therefore, the frequencies are 3, 2 and 1 respectively."],"options":[],"conceptId":"math_statistics_constructing_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Constructing an Ungrouped Frequency Table"}', 0),
  (682, 196, 'Construct the frequency table for 2, 4, 2, 3, 4, 2, 3, 4.', 'text', 1, 'The different values are 2, 3 and 4.', '{"why":"The frequency table summarises how often each distinct value occurs.","sol":"Step 1: 2 occurs 3 times.\nStep 2: 3 occurs 2 times.\nStep 3: 4 occurs 3 times.\nStep 4: The frequencies total 3 + 2 + 3 = 8, matching the 8 observations.","steps":["Step 1: 2 occurs 3 times.","Step 2: 3 occurs 2 times.","Step 3: 4 occurs 3 times.","Step 4: The frequencies total 3 + 2 + 3 = 8, matching the 8 observations."],"options":[],"conceptId":"math_statistics_constructing_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Constructing an Ungrouped Frequency Table"}', 1),
  (683, 196, 'A data set is 5, 6, 5, 7, 6, 5. What is the frequency of each value?', 'text', 1, 'Count each distinct value.', '{"why":"Each frequency comes directly from counting the original observations.","sol":"Step 1: 5 occurs 3 times.\nStep 2: 6 occurs 2 times.\nStep 3: 7 occurs 1 time.","steps":["Step 1: 5 occurs 3 times.","Step 2: 6 occurs 2 times.","Step 3: 7 occurs 1 time."],"options":[],"conceptId":"math_statistics_constructing_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Constructing an Ungrouped Frequency Table"}', 2),
  (684, 197, 'A frequency table shows that the value 4 has frequency 6. What does this mean?', 'text', 1, 'Frequency tells how many times the value occurs.', '{"why":"Frequency tells the number of observations having that value.","sol":"Step 1: The value is 4.\nStep 2: Its frequency is 6.\nStep 3: Therefore, 4 occurs six times.","steps":["Step 1: The value is 4.","Step 2: Its frequency is 6.","Step 3: Therefore, 4 occurs six times."],"options":[],"conceptId":"math_statistics_reading_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Reading an Ungrouped Frequency Table"}', 0),
  (685, 197, 'A table shows that the number of books 2 has frequency 8. How many learners have 2 books?', 'text', 1, 'The frequency tells you the number of learners.', '{"why":"The frequency tells how many observations have the value 2.","sol":"Step 1: The value 2 represents the number of books.\nStep 2: Its frequency is 8.\nStep 3: Therefore, 8 learners have 2 books.","steps":["Step 1: The value 2 represents the number of books.","Step 2: Its frequency is 8.","Step 3: Therefore, 8 learners have 2 books."],"options":[],"conceptId":"math_statistics_reading_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Reading an Ungrouped Frequency Table"}', 1),
  (686, 197, 'A value has frequency 12. Does this mean the value itself is 12?', 'text', 1, 'Separate value from frequency.', '{"why":"A frequency of 12 does not change the value; it tells how often the value occurs.","sol":"Step 1: The value identifies the observation.\nStep 2: The frequency tells how many times it occurs.\nStep 3: Therefore, a frequency of 12 means the observation occurs 12 times.","steps":["Step 1: The value identifies the observation.","Step 2: The frequency tells how many times it occurs.","Step 3: Therefore, a frequency of 12 means the observation occurs 12 times."],"options":[],"conceptId":"math_statistics_reading_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Reading an Ungrouped Frequency Table"}', 2),
  (687, 198, 'Find the total frequency: 4, 5, 3 and 8.', 'text', 1, 'Add all the frequencies.', '{"why":"The total frequency is the sum of all frequencies.","sol":"Step 1: 4 + 5 = 9.\nStep 2: 9 + 3 = 12.\nStep 3: 12 + 8 = 20.","steps":["Step 1: 4 + 5 = 9.","Step 2: 9 + 3 = 12.","Step 3: 12 + 8 = 20."],"options":[],"conceptId":"math_statistics_total_frequency","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Total Frequency"}', 0),
  (688, 198, 'A frequency table has frequencies 2, 7, 6 and 5. How many observations are represented?', 'text', 1, 'The total number of observations equals the total frequency.', '{"why":"Adding all frequencies gives the total number of observations.","sol":"Step 1: 2 + 7 = 9.\nStep 2: 9 + 6 = 15.\nStep 3: 15 + 5 = 20.","steps":["Step 1: 2 + 7 = 9.","Step 2: 9 + 6 = 15.","Step 3: 15 + 5 = 20."],"options":[],"conceptId":"math_statistics_total_frequency","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Total Frequency"}', 1),
  (689, 198, 'A raw data set contains 25 observations. A frequency table made from it has frequencies 5, 8, 4 and 7. Is the table complete?', 'text', 1, 'Compare the total frequency with 25.', '{"why":"A complete frequency table should have total frequency equal to the number of original observations.","sol":"Step 1: 5 + 8 + 4 + 7 = 24.\nStep 2: The original data contains 25 observations.\nStep 3: The frequency total is only 24.\nStep 4: Therefore, one observation is missing from the table.","steps":["Step 1: 5 + 8 + 4 + 7 = 24.","Step 2: The original data contains 25 observations.","Step 3: The frequency total is only 24.","Step 4: Therefore, one observation is missing from the table."],"options":[],"conceptId":"math_statistics_total_frequency","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Total Frequency"}', 2),
  (690, 199, 'A data set has 20 observations. A frequency table has frequencies 6, 8 and 6. Does the total-frequency check pass?', 'text', 1, 'Add the three frequencies.', '{"why":"The total frequency equals the number of original observations.","sol":"Step 1: 6 + 8 + 6 = 20.\nStep 2: The original data contains 20 observations.\nStep 3: The totals agree.","steps":["Step 1: 6 + 8 + 6 = 20.","Step 2: The original data contains 20 observations.","Step 3: The totals agree."],"options":[],"conceptId":"math_statistics_checking_a_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Checking a Frequency Table"}', 0),
  (691, 199, 'A data set contains 30 observations. A table has frequencies 9, 8 and 11. Is the table consistent with the total number of observations?', 'text', 1, 'Add 9, 8 and 11.', '{"why":"The frequencies do not add to the original total of 30.","sol":"Step 1: 9 + 8 = 17.\nStep 2: 17 + 11 = 28.\nStep 3: The table represents 28 observations, not 30.","steps":["Step 1: 9 + 8 = 17.","Step 2: 17 + 11 = 28.","Step 3: The table represents 28 observations, not 30."],"options":[],"conceptId":"math_statistics_checking_a_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Checking a Frequency Table"}', 1),
  (692, 199, 'A frequency table represents 18 observations and its frequencies are 5, 4, 6 and 3. What should you conclude?', 'text', 1, 'Check the sum.', '{"why":"The frequencies account for all 18 observations.","sol":"Step 1: 5 + 4 = 9.\nStep 2: 9 + 6 = 15.\nStep 3: 15 + 3 = 18.\nStep 4: The total agrees with the original number of observations.","steps":["Step 1: 5 + 4 = 9.","Step 2: 9 + 6 = 15.","Step 3: 15 + 3 = 18.","Step 4: The total agrees with the original number of observations."],"options":[],"conceptId":"math_statistics_checking_a_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Checking a Frequency Table"}', 2),
  (693, 200, 'A table represents 20 observations. Two frequencies are 6 and 9. Find the missing frequency.', 'text', 1, 'Subtract the known frequencies from the total.', '{"why":"All frequencies together must equal the total number of observations.","sol":"Step 1: Add the known frequencies: 6 + 9 = 15.\nStep 2: The total number of observations is 20.\nStep 3: Missing frequency = 20 - 15.\nStep 4: Therefore, the missing frequency is 5.","steps":["Step 1: Add the known frequencies: 6 + 9 = 15.","Step 2: The total number of observations is 20.","Step 3: Missing frequency = 20 - 15.","Step 4: Therefore, the missing frequency is 5."],"options":[],"conceptId":"math_statistics_finding_a_missing_frequency","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Finding a Missing Frequency"}', 0),
  (694, 200, 'A frequency table represents 30 observations. The known frequencies are 8, 7 and x. Find x.', 'text', 1, 'First find the total of the known frequencies.', '{"why":"The missing frequency must account for all observations not represented by the known frequencies.","sol":"Step 1: 8 + 7 = 15.\nStep 2: The table must contain 30 observations altogether.\nStep 3: x = 30 - 15.\nStep 4: Therefore, x = 15.","steps":["Step 1: 8 + 7 = 15.","Step 2: The table must contain 30 observations altogether.","Step 3: x = 30 - 15.","Step 4: Therefore, x = 15."],"options":[],"conceptId":"math_statistics_finding_a_missing_frequency","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Finding a Missing Frequency"}', 1),
  (695, 200, 'A table has a total frequency of 40. The known frequencies are 12, 9, 7 and x. Find x.', 'text', 1, 'Add the known frequencies first.', '{"why":"The missing frequency is whatever remains after accounting for the known frequencies.","sol":"Step 1: 12 + 9 + 7 = 28.\nStep 2: The total frequency is 40.\nStep 3: x = 40 - 28.\nStep 4: Therefore, x = 12.","steps":["Step 1: 12 + 9 + 7 = 28.","Step 2: The total frequency is 40.","Step 3: x = 40 - 28.","Step 4: Therefore, x = 12."],"options":[],"conceptId":"math_statistics_finding_a_missing_frequency","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Finding a Missing Frequency"}', 2),
  (696, 201, 'A teacher records learners'' ages using the intervals 10–12, 13–15 and 16–18. Is this grouped data?', 'text', 1, 'Are individual ages being listed separately?', '{"why":"Grouped data places observations into classes or intervals.","sol":"Step 1: The ages have been placed into intervals.\nStep 2: The intervals represent groups of possible values.\nStep 3: Therefore, the data is grouped data.","steps":["Step 1: The ages have been placed into intervals.","Step 2: The intervals represent groups of possible values.","Step 3: Therefore, the data is grouped data."],"options":[],"conceptId":"math_statistics_meaning_of_grouped_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Meaning of Grouped Data"}', 0),
  (697, 201, 'Which is grouped data: 12, 13, 14, 15 or 10–12, 13–15?', 'text', 1, 'Look for intervals.', '{"why":"Grouped data organises observations into intervals.","sol":"Step 1: 12, 13, 14, 15 are individual observations.\nStep 2: 10–12 and 13–15 are intervals.\nStep 3: Therefore, 10–12, 13–15 represents grouped data.","steps":["Step 1: 12, 13, 14, 15 are individual observations.","Step 2: 10–12 and 13–15 are intervals.","Step 3: Therefore, 10–12, 13–15 represents grouped data."],"options":[],"conceptId":"math_statistics_meaning_of_grouped_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Meaning of Grouped Data"}', 1),
  (698, 201, 'Why might 500 measurements be grouped into intervals?', 'text', 1, 'Think about making a large data set easier to read.', '{"why":"Grouping makes a large data set easier to handle.","sol":"Step 1: Listing 500 individual measurements can be difficult to read.\nStep 2: Grouping them into intervals summarises the data.\nStep 3: Therefore, grouping makes a large data set easier to organise and interpret.","steps":["Step 1: Listing 500 individual measurements can be difficult to read.","Step 2: Grouping them into intervals summarises the data.","Step 3: Therefore, grouping makes a large data set easier to organise and interpret."],"options":[],"conceptId":"math_statistics_meaning_of_grouped_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Meaning of Grouped Data"}', 2),
  (699, 202, 'Which of the following is a class interval: 17 or 15–19?', 'text', 1, 'A class interval represents a range.', '{"why":"A class interval contains a range of values.","sol":"Step 1: 17 represents one value.\nStep 2: 15–19 represents a range of values.\nStep 3: Therefore, 15–19 is the class interval.","steps":["Step 1: 17 represents one value.","Step 2: 15–19 represents a range of values.","Step 3: Therefore, 15–19 is the class interval."],"options":[],"conceptId":"math_statistics_class_interval","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Class Interval"}', 0),
  (700, 202, 'Which whole-number values are included in the class interval 20–24?', 'text', 1, 'Start at 20 and continue to 24.', '{"why":"The interval includes every whole-number value from 20 to 24.","sol":"Step 1: Start with 20.\nStep 2: Then 21, 22 and 23.\nStep 3: Finally 24.\nStep 4: Therefore, the values are 20, 21, 22, 23 and 24.","steps":["Step 1: Start with 20.","Step 2: Then 21, 22 and 23.","Step 3: Finally 24.","Step 4: Therefore, the values are 20, 21, 22, 23 and 24."],"options":[],"conceptId":"math_statistics_class_interval","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Class Interval"}', 1),
  (701, 202, 'In a table, the class intervals are 5–9, 10–14 and 15–19. Which interval contains the value 13?', 'text', 1, 'Check where 13 falls.', '{"why":"13 lies within the limits 10 and 14.","sol":"Step 1: 13 is greater than or equal to 10.\nStep 2: 13 is less than or equal to 14.\nStep 3: Therefore, 13 belongs to the interval 10–14.","steps":["Step 1: 13 is greater than or equal to 10.","Step 2: 13 is less than or equal to 14.","Step 3: Therefore, 13 belongs to the interval 10–14."],"options":[],"conceptId":"math_statistics_class_interval","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Class Interval"}', 2),
  (702, 203, 'Find the lower and upper class limits of 30–39.', 'text', 1, 'Look at the first and last values.', '{"why":"The class limits are the smallest and largest stated values.","sol":"Step 1: The first value is 30.\nStep 2: The last value is 39.\nStep 3: Therefore, lower limit = 30 and upper limit = 39.","steps":["Step 1: The first value is 30.","Step 2: The last value is 39.","Step 3: Therefore, lower limit = 30 and upper limit = 39."],"options":[],"conceptId":"math_statistics_class_limits","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Class Limits"}', 0),
  (703, 203, 'What is the upper class limit of 50–59?', 'text', 1, 'Look at the last value in the interval.', '{"why":"The upper limit is the largest stated value in the class.","sol":"Step 1: The interval starts at 50.\nStep 2: It ends at 59.\nStep 3: Therefore, the upper class limit is 59.","steps":["Step 1: The interval starts at 50.","Step 2: It ends at 59.","Step 3: Therefore, the upper class limit is 59."],"options":[],"conceptId":"math_statistics_class_limits","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Class Limits"}', 1),
  (704, 203, 'What is the lower class limit of 70–79?', 'text', 1, 'Look at the first value.', '{"why":"The lower limit is the smallest stated value in the class.","sol":"Step 1: The interval begins at 70.\nStep 2: Therefore, the lower class limit is 70.","steps":["Step 1: The interval begins at 70.","Step 2: Therefore, the lower class limit is 70."],"options":[],"conceptId":"math_statistics_class_limits","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Class Limits"}', 2),
  (705, 204, 'Find the class width of 5–9.', 'text', 1, 'Use upper limit − lower limit + 1.', '{"why":"The interval contains the five values 5, 6, 7, 8 and 9.","sol":"Step 1: Upper limit = 9.\nStep 2: Lower limit = 5.\nStep 3: 9 − 5 + 1 = 5.","steps":["Step 1: Upper limit = 9.","Step 2: Lower limit = 5.","Step 3: 9 − 5 + 1 = 5."],"options":[],"conceptId":"math_statistics_class_width","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Class Width"}', 0),
  (706, 204, 'Find the class width of 20–29.', 'text', 1, 'Subtract the lower limit from the upper limit, then add 1.', '{"why":"There are ten whole-number values from 20 through 29.","sol":"Step 1: 29 − 20 = 9.\nStep 2: 9 + 1 = 10.\nStep 3: Therefore, the class width is 10.","steps":["Step 1: 29 − 20 = 9.","Step 2: 9 + 1 = 10.","Step 3: Therefore, the class width is 10."],"options":[],"conceptId":"math_statistics_class_width","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Class Width"}', 1),
  (707, 204, 'A class interval is 50–54. What is its width?', 'text', 1, 'Count the whole-number values or use the formula.', '{"why":"The interval contains 50, 51, 52, 53 and 54.","sol":"Step 1: 54 − 50 + 1 = 5.\nStep 2: Therefore, the class width is 5.","steps":["Step 1: 54 − 50 + 1 = 5.","Step 2: Therefore, the class width is 5."],"options":[],"conceptId":"math_statistics_class_width","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Class Width"}', 2),
  (708, 205, 'Do the intervals 10–19 and 20–29 overlap?', 'text', 1, 'Check whether they share any whole-number values.', '{"why":"The intervals are separate, so each whole-number observation has one class.","sol":"Step 1: The first interval ends at 19.\nStep 2: The second begins at 20.\nStep 3: They share no values.","steps":["Step 1: The first interval ends at 19.","Step 2: The second begins at 20.","Step 3: They share no values."],"options":[],"conceptId":"math_statistics_non_overlapping_class_intervals","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Non-Overlapping Class Intervals"}', 0),
  (709, 205, 'Why is 10–20 and 20–30 a poor choice for whole-number classes?', 'text', 1, 'Think about the value 20.', '{"why":"An observation should not have two possible classes.","sol":"Step 1: 20 is included in 10–20.\nStep 2: 20 is also included in 20–30.\nStep 3: Therefore, the value 20 has two possible classes.","steps":["Step 1: 20 is included in 10–20.","Step 2: 20 is also included in 20–30.","Step 3: Therefore, the value 20 has two possible classes."],"options":[],"conceptId":"math_statistics_non_overlapping_class_intervals","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Non-Overlapping Class Intervals"}', 1),
  (710, 205, 'Which set is better for whole-number data: 30–39, 40–49 or 30–40, 40–50?', 'text', 1, 'Look for an overlapping boundary.', '{"why":"The classes do not overlap.","sol":"Step 1: 30–39 and 40–49 do not share a value.\nStep 2: 30–40 and 40–50 both contain 40.\nStep 3: Therefore, 30–39 and 40–49 is the better set.","steps":["Step 1: 30–39 and 40–49 do not share a value.","Step 2: 30–40 and 40–50 both contain 40.","Step 3: Therefore, 30–39 and 40–49 is the better set."],"options":[],"conceptId":"math_statistics_non_overlapping_class_intervals","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Non-Overlapping Class Intervals"}', 2),
  (711, 206, 'Find the boundary between the classes 20–29 and 30–39.', 'text', 1, 'Find the midpoint between 29 and 30.', '{"why":"29.5 is halfway between 29 and 30 and forms the common boundary.","sol":"Step 1: The upper limit of the first class is 29.\nStep 2: The lower limit of the next class is 30.\nStep 3: Find their midpoint: (29 + 30) ÷ 2.\nStep 4: 59 ÷ 2 = 29.5.","steps":["Step 1: The upper limit of the first class is 29.","Step 2: The lower limit of the next class is 30.","Step 3: Find their midpoint: (29 + 30) ÷ 2.","Step 4: 59 ÷ 2 = 29.5."],"options":[],"conceptId":"math_statistics_class_boundaries","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Class Boundaries"}', 0),
  (712, 206, 'What are the boundaries of the class 40–49?', 'text', 1, 'Move 0.5 below 40 and 0.5 above 49.', '{"why":"The boundaries extend halfway to the neighbouring whole-number values.","sol":"Step 1: The lower boundary is 40 − 0.5 = 39.5.\nStep 2: The upper boundary is 49 + 0.5 = 49.5.","steps":["Step 1: The lower boundary is 40 − 0.5 = 39.5.","Step 2: The upper boundary is 49 + 0.5 = 49.5."],"options":[],"conceptId":"math_statistics_class_boundaries","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Class Boundaries"}', 1),
  (713, 206, 'What is the difference between the class limit 29 and the boundary 29.5?', 'text', 1, 'One is an included whole-number value; the other separates classes.', '{"why":"Limits describe the stated values in a class, while boundaries separate continuous classes.","sol":"Step 1: 29 is the upper class limit of a whole-number class.\nStep 2: 29.5 is the boundary between that class and the next class.\nStep 3: Therefore, they have different roles.","steps":["Step 1: 29 is the upper class limit of a whole-number class.","Step 2: 29.5 is the boundary between that class and the next class.","Step 3: Therefore, they have different roles."],"options":[],"conceptId":"math_statistics_class_boundaries","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Class Boundaries"}', 2),
  (714, 207, 'The data ranges from 14 to 46. Using a class width of 10, which set of intervals can cover all the data?', 'text', 1, 'Start at a convenient value below 14.', '{"why":"These intervals cover the entire data range without overlapping.","sol":"Step 1: Start with 10–19.\nStep 2: Continue with 20–29.\nStep 3: Continue with 30–39.\nStep 4: Continue with 40–49.\nStep 5: The smallest value 14 and largest value 46 are both covered.","steps":["Step 1: Start with 10–19.","Step 2: Continue with 20–29.","Step 3: Continue with 30–39.","Step 4: Continue with 40–49.","Step 5: The smallest value 14 and largest value 46 are both covered."],"options":[],"conceptId":"math_statistics_constructing_class_intervals","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Constructing Class Intervals"}', 0),
  (715, 207, 'The data ranges from 31 to 68. Give class intervals of width 10 that cover the data.', 'text', 1, 'Start with an interval containing 31.', '{"why":"The intervals cover every value from 31 through 68.","sol":"Step 1: 31 belongs to 30–39.\nStep 2: Continue with 40–49.\nStep 3: Then 50–59.\nStep 4: Then 60–69.\nStep 5: The largest value 68 is included.","steps":["Step 1: 31 belongs to 30–39.","Step 2: Continue with 40–49.","Step 3: Then 50–59.","Step 4: Then 60–69.","Step 5: The largest value 68 is included."],"options":[],"conceptId":"math_statistics_constructing_class_intervals","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Constructing Class Intervals"}', 1),
  (716, 207, 'Why would 10–19, 20–29 and 30–39 be unsuitable for data containing the value 45?', 'text', 1, 'Check whether 45 belongs to any class.', '{"why":"Class intervals must cover every observation in the data set.","sol":"Step 1: 45 is greater than 39.\nStep 2: The last class ends at 39.\nStep 3: Therefore, 45 is not covered.\nStep 4: Another class must be added.","steps":["Step 1: 45 is greater than 39.","Step 2: The last class ends at 39.","Step 3: Therefore, 45 is not covered.","Step 4: Another class must be added."],"options":[],"conceptId":"math_statistics_constructing_class_intervals","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Constructing Class Intervals"}', 2),
  (717, 208, 'Find the midpoint of 10–19.', 'text', 1, 'Add the limits and divide by 2.', '{"why":"The midpoint is halfway between the two class limits.","sol":"Step 1: 10 + 19 = 29.\nStep 2: 29 ÷ 2 = 14.5.","steps":["Step 1: 10 + 19 = 29.","Step 2: 29 ÷ 2 = 14.5."],"options":[],"conceptId":"math_statistics_class_midpoint","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Class Midpoint"}', 0),
  (718, 208, 'Find the midpoint of 30–39.', 'text', 1, 'Use (lower limit + upper limit) ÷ 2.', '{"why":"34.5 is exactly halfway between 30 and 39.","sol":"Step 1: 30 + 39 = 69.\nStep 2: 69 ÷ 2 = 34.5.","steps":["Step 1: 30 + 39 = 69.","Step 2: 69 ÷ 2 = 34.5."],"options":[],"conceptId":"math_statistics_class_midpoint","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Class Midpoint"}', 1),
  (719, 208, 'Find the midpoint of 50–59.', 'text', 1, 'Add 50 and 59, then divide by 2.', '{"why":"The midpoint is the centre of the class interval.","sol":"Step 1: 50 + 59 = 109.\nStep 2: 109 ÷ 2 = 54.5.","steps":["Step 1: 50 + 59 = 109.","Step 2: 109 ÷ 2 = 54.5."],"options":[],"conceptId":"math_statistics_class_midpoint","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Class Midpoint"}', 2),
  (720, 209, 'The frequencies are 3, 5 and 4. Find the cumulative frequencies.', 'text', 1, 'Keep adding each new frequency to the previous total.', '{"why":"Each cumulative frequency includes all frequencies up to that point.","sol":"Step 1: First cumulative frequency = 3.\nStep 2: Second = 3 + 5 = 8.\nStep 3: Third = 8 + 4 = 12.","steps":["Step 1: First cumulative frequency = 3.","Step 2: Second = 3 + 5 = 8.","Step 3: Third = 8 + 4 = 12."],"options":[],"conceptId":"math_statistics_cumulative_frequency","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Cumulative Frequency"}', 0),
  (721, 209, 'A frequency is 6 and the previous cumulative frequency is 9. What is the new cumulative frequency?', 'text', 1, 'Add the new frequency to the previous total.', '{"why":"Cumulative frequency is obtained by adding the current frequency to the previous running total.","sol":"Step 1: Previous cumulative frequency = 9.\nStep 2: New frequency = 6.\nStep 3: 9 + 6 = 15.","steps":["Step 1: Previous cumulative frequency = 9.","Step 2: New frequency = 6.","Step 3: 9 + 6 = 15."],"options":[],"conceptId":"math_statistics_cumulative_frequency","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Cumulative Frequency"}', 1),
  (722, 209, 'A table has frequencies 2, 4, 7 and 3. What is the final cumulative frequency?', 'text', 1, 'The final cumulative frequency equals the total frequency.', '{"why":"The final cumulative frequency represents all observations in the table.","sol":"Step 1: 2 + 4 = 6.\nStep 2: 6 + 7 = 13.\nStep 3: 13 + 3 = 16.","steps":["Step 1: 2 + 4 = 6.","Step 2: 6 + 7 = 13.","Step 3: 13 + 3 = 16."],"options":[],"conceptId":"math_statistics_cumulative_frequency","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Cumulative Frequency"}', 2),
  (723, 210, 'A table shows that the cumulative frequency at value 4 is 11. What does 11 mean?', 'text', 1, 'Think ''up to and including''.', '{"why":"Cumulative frequency is the running total up to that value.","sol":"Step 1: Cumulative frequency includes all frequencies before this value.\nStep 2: It also includes the frequency at value 4.\nStep 3: Therefore, 11 observations have values up to and including 4.","steps":["Step 1: Cumulative frequency includes all frequencies before this value.","Step 2: It also includes the frequency at value 4.","Step 3: Therefore, 11 observations have values up to and including 4."],"options":[],"conceptId":"math_statistics_reading_cumulative_frequency","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Reading Cumulative Frequency"}', 0),
  (724, 210, 'The cumulative frequency at 20 is 18. What does this tell you?', 'text', 1, 'Translate the cumulative frequency into words.', '{"why":"Cumulative frequency represents the number of observations accumulated so far.","sol":"Step 1: The cumulative frequency is 18.\nStep 2: It counts all observations up to and including 20.\nStep 3: Therefore, 18 observations have values up to and including 20.","steps":["Step 1: The cumulative frequency is 18.","Step 2: It counts all observations up to and including 20.","Step 3: Therefore, 18 observations have values up to and including 20."],"options":[],"conceptId":"math_statistics_reading_cumulative_frequency","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Reading Cumulative Frequency"}', 1),
  (725, 210, 'A table has cumulative frequencies 4, 9, 15 and 20. What is the total number of observations?', 'text', 1, 'Look at the final cumulative frequency.', '{"why":"The final cumulative frequency equals the total frequency.","sol":"Step 1: The final cumulative frequency includes every observation.\nStep 2: The final value is 20.\nStep 3: Therefore, there are 20 observations altogether.","steps":["Step 1: The final cumulative frequency includes every observation.","Step 2: The final value is 20.","Step 3: Therefore, there are 20 observations altogether."],"options":[],"conceptId":"math_statistics_reading_cumulative_frequency","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Reading Cumulative Frequency"}', 2),
  (726, 211, 'Find the mean of 4, 6 and 8.', 'text', 1, 'Add the three values, then divide by 3.', '{"why":"The mean is the total shared equally among the three observations.","sol":"Step 1: 4 + 6 + 8 = 18.\nStep 2: There are 3 values.\nStep 3: Mean = 18 ÷ 3.\nStep 4: Mean = 6.","steps":["Step 1: 4 + 6 + 8 = 18.","Step 2: There are 3 values.","Step 3: Mean = 18 ÷ 3.","Step 4: Mean = 6."],"options":[],"conceptId":"math_statistics_31_meaning_of_the_mean","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"31. Meaning of the Mean"}', 0),
  (727, 211, 'Find the mean of 5, 7, 9 and 11.', 'text', 1, 'Find the total first.', '{"why":"The total of 32 is shared equally among 4 observations.","sol":"Step 1: 5 + 7 + 9 + 11 = 32.\nStep 2: There are 4 values.\nStep 3: Mean = 32 ÷ 4.\nStep 4: Mean = 8.","steps":["Step 1: 5 + 7 + 9 + 11 = 32.","Step 2: There are 4 values.","Step 3: Mean = 32 ÷ 4.","Step 4: Mean = 8."],"options":[],"conceptId":"math_statistics_31_meaning_of_the_mean","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"31. Meaning of the Mean"}', 1),
  (728, 211, 'Find the mean of 2, 6, 8, 9 and 10.', 'text', 1, 'Add all five values and divide by 5.', '{"why":"The mean represents the equal share of the total 35 among 5 observations.","sol":"Step 1: 2 + 6 + 8 + 9 + 10 = 35.\nStep 2: There are 5 values.\nStep 3: Mean = 35 ÷ 5.\nStep 4: Mean = 7.","steps":["Step 1: 2 + 6 + 8 + 9 + 10 = 35.","Step 2: There are 5 values.","Step 3: Mean = 35 ÷ 5.","Step 4: Mean = 7."],"options":[],"conceptId":"math_statistics_31_meaning_of_the_mean","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"31. Meaning of the Mean"}', 2),
  (729, 212, 'Find the mean of 8, 10, 12 and 14.', 'text', 1, 'There are 4 values.', '{"why":"The mean is the total divided by the number of observations.","sol":"Step 1: 8 + 10 + 12 + 14 = 44.\nStep 2: There are 4 observations.\nStep 3: Mean = 44 ÷ 4.\nStep 4: Mean = 11.","steps":["Step 1: 8 + 10 + 12 + 14 = 44.","Step 2: There are 4 observations.","Step 3: Mean = 44 ÷ 4.","Step 4: Mean = 11."],"options":[],"conceptId":"math_statistics_32_finding_mean_from_raw_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"32. Finding Mean from Raw Data"}', 0),
  (730, 212, 'Find the mean of 5, 7, 12, 16 and 20.', 'text', 1, 'Add all five values before dividing by 5.', '{"why":"The five values have a total of 60, so each would receive 12 if the total were shared equally.","sol":"Step 1: 5 + 7 + 12 + 16 + 20 = 60.\nStep 2: There are 5 observations.\nStep 3: Mean = 60 ÷ 5.\nStep 4: Mean = 12.","steps":["Step 1: 5 + 7 + 12 + 16 + 20 = 60.","Step 2: There are 5 observations.","Step 3: Mean = 60 ÷ 5.","Step 4: Mean = 12."],"options":[],"conceptId":"math_statistics_32_finding_mean_from_raw_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"32. Finding Mean from Raw Data"}', 1),
  (731, 212, 'The numbers of books read by four learners are 3, 5, 6 and 10. Find the mean.', 'text', 1, 'The number of observations is 4.', '{"why":"The total of 24 books is shared equally among 4 learners.","sol":"Step 1: 3 + 5 + 6 + 10 = 24.\nStep 2: There are 4 learners.\nStep 3: Mean = 24 ÷ 4.\nStep 4: Mean = 6.","steps":["Step 1: 3 + 5 + 6 + 10 = 24.","Step 2: There are 4 learners.","Step 3: Mean = 24 ÷ 4.","Step 4: Mean = 6."],"options":[],"conceptId":"math_statistics_32_finding_mean_from_raw_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"32. Finding Mean from Raw Data"}', 2),
  (732, 213, 'The total of 5 observations is 40. Find the mean.', 'text', 1, 'Divide the total by 5.', '{"why":"The total 40 is divided into 5 equal shares.","sol":"Step 1: Total = 40.\nStep 2: Number of observations = 5.\nStep 3: Mean = 40 ÷ 5.\nStep 4: Mean = 8.","steps":["Step 1: Total = 40.","Step 2: Number of observations = 5.","Step 3: Mean = 40 ÷ 5.","Step 4: Mean = 8."],"options":[],"conceptId":"math_statistics_33_why_we_divide_by_the_number_of_values","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"33. Why We Divide by the Number of Values"}', 0),
  (733, 213, 'The total of 8 values is 64. Find the mean.', 'text', 1, 'Use total ÷ number of observations.', '{"why":"There are 8 observations, so the total is divided into 8 equal shares.","sol":"Step 1: Total = 64.\nStep 2: Number of observations = 8.\nStep 3: Mean = 64 ÷ 8.\nStep 4: Mean = 8.","steps":["Step 1: Total = 64.","Step 2: Number of observations = 8.","Step 3: Mean = 64 ÷ 8.","Step 4: Mean = 8."],"options":[],"conceptId":"math_statistics_33_why_we_divide_by_the_number_of_values","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"33. Why We Divide by the Number of Values"}', 1),
  (734, 213, 'A learner has four test scores with a total of 70. What is the mean score?', 'text', 1, 'There are 4 test scores.', '{"why":"The total score is shared equally across the four tests.","sol":"Step 1: Total score = 70.\nStep 2: Number of scores = 4.\nStep 3: Mean = 70 ÷ 4.\nStep 4: Mean = 17.5.","steps":["Step 1: Total score = 70.","Step 2: Number of scores = 4.","Step 3: Mean = 70 ÷ 4.","Step 4: Mean = 17.5."],"options":[],"conceptId":"math_statistics_33_why_we_divide_by_the_number_of_values","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"33. Why We Divide by the Number of Values"}', 2),
  (735, 214, 'Find the mean from this table: x = 2, 4 and f = 2, 1 respectively.', 'text', 1, 'The data is 2, 2, 4.', '{"why":"Frequency tells us how many times each value contributes to the total.","sol":"Step 1: The value 2 occurs twice: 2 + 2 = 4.\nStep 2: The value 4 occurs once: 4.\nStep 3: Total = 4 + 4 = 8.\nStep 4: Total frequency = 2 + 1 = 3.\nStep 5: Mean = 8 ÷ 3 = 2.67 approximately.","steps":["Step 1: The value 2 occurs twice: 2 + 2 = 4.","Step 2: The value 4 occurs once: 4.","Step 3: Total = 4 + 4 = 8.","Step 4: Total frequency = 2 + 1 = 3.","Step 5: Mean = 8 ÷ 3 = 2.67 approximately."],"options":[],"conceptId":"math_statistics_34_mean_from_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"34. Mean from an Ungrouped Frequency Table"}', 0),
  (736, 214, 'Find the mean when x = 3, 5 and f = 2, 3 respectively.', 'text', 1, 'Expand the frequencies first.', '{"why":"There are five observations altogether, so the total is divided by five.","sol":"Step 1: 3 occurs twice: 3 + 3 = 6.\nStep 2: 5 occurs three times: 5 + 5 + 5 = 15.\nStep 3: Total = 21.\nStep 4: Total frequency = 2 + 3 = 5.\nStep 5: Mean = 21 ÷ 5 = 4.2.","steps":["Step 1: 3 occurs twice: 3 + 3 = 6.","Step 2: 5 occurs three times: 5 + 5 + 5 = 15.","Step 3: Total = 21.","Step 4: Total frequency = 2 + 3 = 5.","Step 5: Mean = 21 ÷ 5 = 4.2."],"options":[],"conceptId":"math_statistics_34_mean_from_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"34. Mean from an Ungrouped Frequency Table"}', 1),
  (737, 214, 'Find the mean when x = 4, 6 and f = 1, 4 respectively.', 'text', 1, 'The value 6 occurs four times.', '{"why":"The frequency determines how many observations are represented by each value.","sol":"Step 1: 4 occurs once: 4.\nStep 2: 6 occurs four times: 6 + 6 + 6 + 6 = 24.\nStep 3: Total = 4 + 24 = 28.\nStep 4: Total frequency = 1 + 4 = 5.\nStep 5: Mean = 28 ÷ 5 = 5.6.","steps":["Step 1: 4 occurs once: 4.","Step 2: 6 occurs four times: 6 + 6 + 6 + 6 = 24.","Step 3: Total = 4 + 24 = 28.","Step 4: Total frequency = 1 + 4 = 5.","Step 5: Mean = 28 ÷ 5 = 5.6."],"options":[],"conceptId":"math_statistics_34_mean_from_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"34. Mean from an Ungrouped Frequency Table"}', 2),
  (738, 215, 'Find fx when x = 6 and f = 4.', 'text', 1, 'Use fx = f × x.', '{"why":"Four observations of 6 contribute 24 altogether.","sol":"Step 1: f = 4.\nStep 2: x = 6.\nStep 3: fx = 4 × 6.\nStep 4: fx = 24.","steps":["Step 1: f = 4.","Step 2: x = 6.","Step 3: fx = 4 × 6.","Step 4: fx = 24."],"options":[],"conceptId":"math_statistics_35_understanding_fx","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"35. Understanding fx"}', 0),
  (739, 215, 'Find fx when x = 9 and f = 5.', 'text', 1, 'Multiply 9 by 5.', '{"why":"Five occurrences of 9 have a combined total of 45.","sol":"Step 1: f = 5.\nStep 2: x = 9.\nStep 3: fx = 5 × 9.\nStep 4: fx = 45.","steps":["Step 1: f = 5.","Step 2: x = 9.","Step 3: fx = 5 × 9.","Step 4: fx = 45."],"options":[],"conceptId":"math_statistics_35_understanding_fx","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"35. Understanding fx"}', 1),
  (740, 215, 'For x = 4, 7 and f = 3, 2 respectively, find the two fx values.', 'text', 1, 'Multiply each x by its corresponding frequency.', '{"why":"Each value must be multiplied by its own frequency.","sol":"Step 1: For x = 4 and f = 3: fx = 3 × 4 = 12.\nStep 2: For x = 7 and f = 2: fx = 2 × 7 = 14.","steps":["Step 1: For x = 4 and f = 3: fx = 3 × 4 = 12.","Step 2: For x = 7 and f = 2: fx = 2 × 7 = 14."],"options":[],"conceptId":"math_statistics_35_understanding_fx","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"35. Understanding fx"}', 2),
  (741, 216, 'Find the mean from x = 2, 4 and f = 3, 2 respectively.', 'text', 1, 'Calculate fx first.', '{"why":"The formula divides the total represented value by the total number of observations.","sol":"Step 1: For x = 2: fx = 2 × 3 = 6.\nStep 2: For x = 4: fx = 4 × 2 = 8.\nStep 3: Σfx = 6 + 8 = 14.\nStep 4: Σf = 3 + 2 = 5.\nStep 5: Mean = 14 ÷ 5 = 2.8.","steps":["Step 1: For x = 2: fx = 2 × 3 = 6.","Step 2: For x = 4: fx = 4 × 2 = 8.","Step 3: Σfx = 6 + 8 = 14.","Step 4: Σf = 3 + 2 = 5.","Step 5: Mean = 14 ÷ 5 = 2.8."],"options":[],"conceptId":"math_statistics_36_finding_mean_using_fx_f","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"36. Finding Mean Using Σfx ÷ Σf"}', 0),
  (742, 216, 'Find the mean from x = 5, 10, 15 and f = 2, 3, 1 respectively.', 'text', 1, 'Find all three fx values.', '{"why":"The total represented value is 55 and there are 6 observations.","sol":"Step 1: 5 × 2 = 10.\nStep 2: 10 × 3 = 30.\nStep 3: 15 × 1 = 15.\nStep 4: Σfx = 10 + 30 + 15 = 55.\nStep 5: Σf = 2 + 3 + 1 = 6.\nStep 6: Mean = 55 ÷ 6 = 9.17 approximately.","steps":["Step 1: 5 × 2 = 10.","Step 2: 10 × 3 = 30.","Step 3: 15 × 1 = 15.","Step 4: Σfx = 10 + 30 + 15 = 55.","Step 5: Σf = 2 + 3 + 1 = 6.","Step 6: Mean = 55 ÷ 6 = 9.17 approximately."],"options":[],"conceptId":"math_statistics_36_finding_mean_using_fx_f","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"36. Finding Mean Using Σfx ÷ Σf"}', 1),
  (743, 216, 'Find the mean from x = 4, 8 and f = 5, 5 respectively.', 'text', 1, 'The total frequency is 10.', '{"why":"There are 10 observations whose combined value is 60.","sol":"Step 1: 4 × 5 = 20.\nStep 2: 8 × 5 = 40.\nStep 3: Σfx = 20 + 40 = 60.\nStep 4: Σf = 5 + 5 = 10.\nStep 5: Mean = 60 ÷ 10 = 6.","steps":["Step 1: 4 × 5 = 20.","Step 2: 8 × 5 = 40.","Step 3: Σfx = 20 + 40 = 60.","Step 4: Σf = 5 + 5 = 10.","Step 5: Mean = 60 ÷ 10 = 6."],"options":[],"conceptId":"math_statistics_36_finding_mean_using_fx_f","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"36. Finding Mean Using Σfx ÷ Σf"}', 2),
  (744, 217, 'Find the estimated mean for classes 0–9 and 10–19 with frequencies 2 and 3 respectively.', 'text', 1, 'First find the two midpoints.', '{"why":"Each class is represented by its midpoint because the individual observations inside the class are unknown.","sol":"Step 1: Midpoint of 0–9 = (0 + 9) ÷ 2 = 4.5.\nStep 2: Midpoint of 10–19 = (10 + 19) ÷ 2 = 14.5.\nStep 3: fx values are 4.5 × 2 = 9 and 14.5 × 3 = 43.5.\nStep 4: Σfx = 52.5.\nStep 5: Σf = 5.\nStep 6: Mean = 52.5 ÷ 5 = 10.5.","steps":["Step 1: Midpoint of 0–9 = (0 + 9) ÷ 2 = 4.5.","Step 2: Midpoint of 10–19 = (10 + 19) ÷ 2 = 14.5.","Step 3: fx values are 4.5 × 2 = 9 and 14.5 × 3 = 43.5.","Step 4: Σfx = 52.5.","Step 5: Σf = 5.","Step 6: Mean = 52.5 ÷ 5 = 10.5."],"options":[],"conceptId":"math_statistics_37_finding_mean_from_a_grouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"37. Finding Mean from a Grouped Frequency Table"}', 0),
  (745, 217, 'Find the estimated mean for classes 10–19, 20–29 with frequencies 2 and 4 respectively.', 'text', 1, 'Use midpoints 14.5 and 24.5.', '{"why":"The midpoint represents each class when calculating the estimated grouped mean.","sol":"Step 1: Midpoint of 10–19 = 14.5.\nStep 2: Midpoint of 20–29 = 24.5.\nStep 3: 14.5 × 2 = 29.\nStep 4: 24.5 × 4 = 98.\nStep 5: Σfx = 127.\nStep 6: Σf = 6.\nStep 7: Mean = 127 ÷ 6 = 21.17 approximately.","steps":["Step 1: Midpoint of 10–19 = 14.5.","Step 2: Midpoint of 20–29 = 24.5.","Step 3: 14.5 × 2 = 29.","Step 4: 24.5 × 4 = 98.","Step 5: Σfx = 127.","Step 6: Σf = 6.","Step 7: Mean = 127 ÷ 6 = 21.17 approximately."],"options":[],"conceptId":"math_statistics_37_finding_mean_from_a_grouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"37. Finding Mean from a Grouped Frequency Table"}', 1),
  (746, 217, 'Find the estimated mean for classes 20–29, 30–39 with frequencies 3 and 2 respectively.', 'text', 1, 'Find the midpoint of each class first.', '{"why":"The grouped mean is calculated from the representative midpoint of each class.","sol":"Step 1: Midpoint of 20–29 = 24.5.\nStep 2: Midpoint of 30–39 = 34.5.\nStep 3: 24.5 × 3 = 73.5.\nStep 4: 34.5 × 2 = 69.\nStep 5: Σfx = 142.5.\nStep 6: Σf = 5.\nStep 7: Mean = 142.5 ÷ 5 = 28.5.","steps":["Step 1: Midpoint of 20–29 = 24.5.","Step 2: Midpoint of 30–39 = 34.5.","Step 3: 24.5 × 3 = 73.5.","Step 4: 34.5 × 2 = 69.","Step 5: Σfx = 142.5.","Step 6: Σf = 5.","Step 7: Mean = 142.5 ÷ 5 = 28.5."],"options":[],"conceptId":"math_statistics_37_finding_mean_from_a_grouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"37. Finding Mean from a Grouped Frequency Table"}', 2),
  (747, 218, 'Find the midpoint of the class 5–14.', 'text', 1, 'Add the two class limits and divide by 2.', '{"why":"The midpoint is the central value between the two class limits.","sol":"Step 1: Lower limit = 5.\nStep 2: Upper limit = 14.\nStep 3: Midpoint = (5 + 14) ÷ 2.\nStep 4: Midpoint = 19 ÷ 2 = 9.5.","steps":["Step 1: Lower limit = 5.","Step 2: Upper limit = 14.","Step 3: Midpoint = (5 + 14) ÷ 2.","Step 4: Midpoint = 19 ÷ 2 = 9.5."],"options":[],"conceptId":"math_statistics_38_why_midpoints_are_used_for_grouped_mean","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"38. Why Midpoints Are Used for Grouped Mean"}', 0),
  (748, 218, 'Find the midpoint of 40–49.', 'text', 1, 'Use (lower limit + upper limit) ÷ 2.', '{"why":"44.5 is halfway between 40 and 49.","sol":"Step 1: 40 + 49 = 89.\nStep 2: 89 ÷ 2 = 44.5.\nStep 3: Therefore the midpoint is 44.5.","steps":["Step 1: 40 + 49 = 89.","Step 2: 89 ÷ 2 = 44.5.","Step 3: Therefore the midpoint is 44.5."],"options":[],"conceptId":"math_statistics_38_why_midpoints_are_used_for_grouped_mean","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"38. Why Midpoints Are Used for Grouped Mean"}', 1),
  (749, 218, 'Why is 24.5 used as the midpoint of the class 20–29?', 'text', 1, 'Calculate the midpoint.', '{"why":"24.5 is halfway between the lower and upper class limits.","sol":"Step 1: Lower limit = 20.\nStep 2: Upper limit = 29.\nStep 3: Midpoint = (20 + 29) ÷ 2.\nStep 4: Midpoint = 49 ÷ 2 = 24.5.","steps":["Step 1: Lower limit = 20.","Step 2: Upper limit = 29.","Step 3: Midpoint = (20 + 29) ÷ 2.","Step 4: Midpoint = 49 ÷ 2 = 24.5."],"options":[],"conceptId":"math_statistics_38_why_midpoints_are_used_for_grouped_mean","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"38. Why Midpoints Are Used for Grouped Mean"}', 2),
  (750, 219, 'The mean of 5, 7 and x is 9. Find x.', 'text', 1, 'Required total = 9 × 3.', '{"why":"The three values must have a total of 27 for their mean to be 9.","sol":"Step 1: Required total = 9 × 3 = 27.\nStep 2: Known total = 5 + 7 = 12.\nStep 3: x = 27 − 12.\nStep 4: x = 15.\nStep 5: Check: (5 + 7 + 15) ÷ 3 = 27 ÷ 3 = 9.","steps":["Step 1: Required total = 9 × 3 = 27.","Step 2: Known total = 5 + 7 = 12.","Step 3: x = 27 − 12.","Step 4: x = 15.","Step 5: Check: (5 + 7 + 15) ÷ 3 = 27 ÷ 3 = 9."],"options":[],"conceptId":"math_statistics_39_finding_a_missing_value_from_a_known_mean","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"39. Finding a Missing Value from a Known Mean"}', 0);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (751, 219, 'The mean of four numbers is 10. Three numbers are 6, 11 and 8. Find the fourth number.', 'text', 1, 'First find the required total.', '{"why":"A mean of 10 for four values requires a total of 40.","sol":"Step 1: Required total = 10 × 4 = 40.\nStep 2: Known total = 6 + 11 + 8 = 25.\nStep 3: Missing value = 40 − 25.\nStep 4: Missing value = 15.","steps":["Step 1: Required total = 10 × 4 = 40.","Step 2: Known total = 6 + 11 + 8 = 25.","Step 3: Missing value = 40 − 25.","Step 4: Missing value = 15."],"options":[],"conceptId":"math_statistics_39_finding_a_missing_value_from_a_known_mean","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"39. Finding a Missing Value from a Known Mean"}', 1),
  (752, 219, 'The mean of six numbers is 14. Five numbers are 10, 12, 15, 16 and 13. Find the missing number.', 'text', 1, 'Required total = 14 × 6.', '{"why":"The six values must total 84 to have a mean of 14.","sol":"Step 1: Required total = 14 × 6 = 84.\nStep 2: Known total = 10 + 12 + 15 + 16 + 13 = 66.\nStep 3: Missing value = 84 − 66.\nStep 4: Missing value = 18.","steps":["Step 1: Required total = 14 × 6 = 84.","Step 2: Known total = 10 + 12 + 15 + 16 + 13 = 66.","Step 3: Missing value = 84 − 66.","Step 4: Missing value = 18."],"options":[],"conceptId":"math_statistics_39_finding_a_missing_value_from_a_known_mean","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"39. Finding a Missing Value from a Known Mean"}', 2),
  (753, 220, 'A table has x = 2 with frequency 1 and x = 6 with frequency f. The mean is 4. Find f.', 'text', 1, 'Use 4 = (2 + 6f) ÷ (1 + f).', '{"why":"The missing frequency must make the weighted mean equal to 4.","sol":"Step 1: 4 = (2 + 6f) ÷ (1 + f).\nStep 2: 4(1 + f) = 2 + 6f.\nStep 3: 4 + 4f = 2 + 6f.\nStep 4: 2 = 2f.\nStep 5: f = 1.","steps":["Step 1: 4 = (2 + 6f) ÷ (1 + f).","Step 2: 4(1 + f) = 2 + 6f.","Step 3: 4 + 4f = 2 + 6f.","Step 4: 2 = 2f.","Step 5: f = 1."],"options":[],"conceptId":"math_statistics_40_finding_a_missing_frequency_from_a_known_mean","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"40. Finding a Missing Frequency from a Known Mean"}', 0),
  (754, 220, 'A table has x = 3 with frequency 2 and x = 7 with frequency f. The mean is 5. Find f.', 'text', 1, 'Write the weighted mean equation first.', '{"why":"A frequency of 2 makes the weighted mean equal to 5.","sol":"Step 1: Σfx = 3 × 2 + 7f = 6 + 7f.\nStep 2: Σf = 2 + f.\nStep 3: 5 = (6 + 7f) ÷ (2 + f).\nStep 4: 5(2 + f) = 6 + 7f.\nStep 5: 10 + 5f = 6 + 7f.\nStep 6: 4 = 2f.\nStep 7: f = 2.","steps":["Step 1: Σfx = 3 × 2 + 7f = 6 + 7f.","Step 2: Σf = 2 + f.","Step 3: 5 = (6 + 7f) ÷ (2 + f).","Step 4: 5(2 + f) = 6 + 7f.","Step 5: 10 + 5f = 6 + 7f.","Step 6: 4 = 2f.","Step 7: f = 2."],"options":[],"conceptId":"math_statistics_40_finding_a_missing_frequency_from_a_known_mean","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"40. Finding a Missing Frequency from a Known Mean"}', 1),
  (755, 220, 'A table has x = 2 with frequency 3 and x = 8 with frequency f. The mean is 5. Find f.', 'text', 1, 'Use Σfx = 6 + 8f and Σf = 3 + f.', '{"why":"Three occurrences of 8 together with three occurrences of 2 produce a mean of 5.","sol":"Step 1: 5 = (6 + 8f) ÷ (3 + f).\nStep 2: 5(3 + f) = 6 + 8f.\nStep 3: 15 + 5f = 6 + 8f.\nStep 4: 9 = 3f.\nStep 5: f = 3.","steps":["Step 1: 5 = (6 + 8f) ÷ (3 + f).","Step 2: 5(3 + f) = 6 + 8f.","Step 3: 15 + 5f = 6 + 8f.","Step 4: 9 = 3f.","Step 5: f = 3."],"options":[],"conceptId":"math_statistics_40_finding_a_missing_frequency_from_a_known_mean","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"40. Finding a Missing Frequency from a Known Mean"}', 2),
  (756, 221, 'Find the median of 4, 9, 2, 7 and 5.', 'text', 1, 'Arrange the values first.', '{"why":"The median is the middle value after ordering the data.","sol":"Step 1: Arrange the data: 2, 4, 5, 7, 9.\nStep 2: There are 5 values.\nStep 3: The middle value is 5.\nStep 4: Median = 5.","steps":["Step 1: Arrange the data: 2, 4, 5, 7, 9.","Step 2: There are 5 values.","Step 3: The middle value is 5.","Step 4: Median = 5."],"options":[],"conceptId":"math_statistics_41_meaning_of_the_median","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"41. Meaning of the Median"}', 0),
  (757, 221, 'Find the median of 11, 3, 8, 5 and 9.', 'text', 1, 'Put the values from smallest to largest.', '{"why":"The third value is the middle of five ordered observations.","sol":"Step 1: Ordered data: 3, 5, 8, 9, 11.\nStep 2: There are 5 values.\nStep 3: The middle value is 8.\nStep 4: Median = 8.","steps":["Step 1: Ordered data: 3, 5, 8, 9, 11.","Step 2: There are 5 values.","Step 3: The middle value is 8.","Step 4: Median = 8."],"options":[],"conceptId":"math_statistics_41_meaning_of_the_median","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"41. Meaning of the Median"}', 1),
  (758, 221, 'Find the median of 2, 7, 4, 10, 6, 9 and 5.', 'text', 1, 'There are 7 observations, so look for the fourth value after ordering.', '{"why":"Six has three observations below it and three above it.","sol":"Step 1: Ordered data: 2, 4, 5, 6, 7, 9, 10.\nStep 2: There are 7 values.\nStep 3: The fourth value is 6.\nStep 4: Median = 6.","steps":["Step 1: Ordered data: 2, 4, 5, 6, 7, 9, 10.","Step 2: There are 7 values.","Step 3: The fourth value is 6.","Step 4: Median = 6."],"options":[],"conceptId":"math_statistics_41_meaning_of_the_median","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"41. Meaning of the Median"}', 2),
  (759, 222, 'A dataset has 5 observations. What is the median position?', 'text', 1, 'Use (n + 1) ÷ 2.', '{"why":"For five ordered observations, the third observation has two values on each side.","sol":"Step 1: n = 5.\nStep 2: Median position = (5 + 1) ÷ 2.\nStep 3: Median position = 3.\nStep 4: Therefore the median is at the 3rd position.","steps":["Step 1: n = 5.","Step 2: Median position = (5 + 1) ÷ 2.","Step 3: Median position = 3.","Step 4: Therefore the median is at the 3rd position."],"options":[],"conceptId":"math_statistics_42_median_of_an_odd_sized_dataset","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"42. Median of an Odd-Sized Dataset"}', 0),
  (760, 222, 'Find the median of 8, 2, 10, 5 and 6.', 'text', 1, 'There are 5 observations, so use the 3rd position.', '{"why":"The median is the value occupying the third position in five ordered observations.","sol":"Step 1: n = 5.\nStep 2: Median position = (5 + 1) ÷ 2 = 3rd.\nStep 3: Ordered data: 2, 5, 6, 8, 10.\nStep 4: The 3rd value is 6.\nStep 5: Median = 6.","steps":["Step 1: n = 5.","Step 2: Median position = (5 + 1) ÷ 2 = 3rd.","Step 3: Ordered data: 2, 5, 6, 8, 10.","Step 4: The 3rd value is 6.","Step 5: Median = 6."],"options":[],"conceptId":"math_statistics_42_median_of_an_odd_sized_dataset","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"42. Median of an Odd-Sized Dataset"}', 1),
  (761, 222, 'Find the median of 12, 4, 8, 15, 6, 10 and 2.', 'text', 1, 'There are 7 observations, so the median is at the 4th position.', '{"why":"Eight has three ordered observations below it and three above it.","sol":"Step 1: n = 7.\nStep 2: Median position = (7 + 1) ÷ 2 = 4th.\nStep 3: Ordered data: 2, 4, 6, 8, 10, 12, 15.\nStep 4: The 4th value is 8.\nStep 5: Median = 8.","steps":["Step 1: n = 7.","Step 2: Median position = (7 + 1) ÷ 2 = 4th.","Step 3: Ordered data: 2, 4, 6, 8, 10, 12, 15.","Step 4: The 4th value is 8.","Step 5: Median = 8."],"options":[],"conceptId":"math_statistics_42_median_of_an_odd_sized_dataset","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"42. Median of an Odd-Sized Dataset"}', 2),
  (762, 223, 'Find the median of 2, 4, 6 and 8.', 'text', 1, 'The two middle values are 4 and 6.', '{"why":"With four observations, the median is the average of the 2nd and 3rd values.","sol":"Step 1: The data is already ordered.\nStep 2: The two middle values are 4 and 6.\nStep 3: Median = (4 + 6) ÷ 2.\nStep 4: Median = 5.","steps":["Step 1: The data is already ordered.","Step 2: The two middle values are 4 and 6.","Step 3: Median = (4 + 6) ÷ 2.","Step 4: Median = 5."],"options":[],"conceptId":"math_statistics_43_median_of_an_even_sized_dataset","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"43. Median of an Even-Sized Dataset"}', 0),
  (763, 223, 'Find the median of 3, 10, 7, 5, 2 and 8.', 'text', 1, 'Order the six values first.', '{"why":"The two central observations are 5 and 7, so their average is the median.","sol":"Step 1: Ordered data: 2, 3, 5, 7, 8, 10.\nStep 2: The two middle values are 5 and 7.\nStep 3: Median = (5 + 7) ÷ 2.\nStep 4: Median = 6.","steps":["Step 1: Ordered data: 2, 3, 5, 7, 8, 10.","Step 2: The two middle values are 5 and 7.","Step 3: Median = (5 + 7) ÷ 2.","Step 4: Median = 6."],"options":[],"conceptId":"math_statistics_43_median_of_an_even_sized_dataset","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"43. Median of an Even-Sized Dataset"}', 1),
  (764, 223, 'Find the median of 4, 12, 8, 20, 10 and 6.', 'text', 1, 'There are six observations.', '{"why":"For an even-sized dataset, the median lies halfway between the two middle values.","sol":"Step 1: Ordered data: 4, 6, 8, 10, 12, 20.\nStep 2: The two middle values are 8 and 10.\nStep 3: Median = (8 + 10) ÷ 2.\nStep 4: Median = 9.","steps":["Step 1: Ordered data: 4, 6, 8, 10, 12, 20.","Step 2: The two middle values are 8 and 10.","Step 3: Median = (8 + 10) ÷ 2.","Step 4: Median = 9."],"options":[],"conceptId":"math_statistics_43_median_of_an_even_sized_dataset","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"43. Median of an Even-Sized Dataset"}', 2),
  (765, 224, 'Find the median from x = 2, 4, 6 with frequencies 2, 3, 2 respectively.', 'text', 1, 'There are 7 observations. Find the 4th position.', '{"why":"The fourth ordered observation is represented by the value 4.","sol":"Step 1: Total frequency = 2 + 3 + 2 = 7.\nStep 2: Median position = (7 + 1) ÷ 2 = 4th.\nStep 3: Cumulative frequencies are 2, 5, 7.\nStep 4: The 4th observation lies at x = 4.\nStep 5: Median = 4.","steps":["Step 1: Total frequency = 2 + 3 + 2 = 7.","Step 2: Median position = (7 + 1) ÷ 2 = 4th.","Step 3: Cumulative frequencies are 2, 5, 7.","Step 4: The 4th observation lies at x = 4.","Step 5: Median = 4."],"options":[],"conceptId":"math_statistics_44_median_from_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"44. Median from an Ungrouped Frequency Table"}', 0),
  (766, 224, 'Find the median from x = 1, 3, 5 with frequencies 2, 4, 2 respectively.', 'text', 1, 'There are 8 observations, so inspect positions 4 and 5.', '{"why":"Both middle observations fall among the four occurrences of 3.","sol":"Step 1: Total frequency = 2 + 4 + 2 = 8.\nStep 2: Middle positions are 4th and 5th.\nStep 3: Cumulative frequency at x = 1 is 2.\nStep 4: Cumulative frequency at x = 3 is 6.\nStep 5: Therefore both the 4th and 5th observations are 3.\nStep 6: Median = 3.","steps":["Step 1: Total frequency = 2 + 4 + 2 = 8.","Step 2: Middle positions are 4th and 5th.","Step 3: Cumulative frequency at x = 1 is 2.","Step 4: Cumulative frequency at x = 3 is 6.","Step 5: Therefore both the 4th and 5th observations are 3.","Step 6: Median = 3."],"options":[],"conceptId":"math_statistics_44_median_from_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"44. Median from an Ungrouped Frequency Table"}', 1),
  (767, 224, 'Find the median from x = 10, 20, 30, 40 with frequencies 1, 2, 4, 2 respectively.', 'text', 1, 'There are 9 observations, so find the 5th position.', '{"why":"The cumulative frequency reaches 7 at 30, so the fifth observation is 30.","sol":"Step 1: Total frequency = 1 + 2 + 4 + 2 = 9.\nStep 2: Median position = (9 + 1) ÷ 2 = 5th.\nStep 3: Cumulative frequencies are 1, 3, 7, 9.\nStep 4: The 5th observation falls at x = 30.\nStep 5: Median = 30.","steps":["Step 1: Total frequency = 1 + 2 + 4 + 2 = 9.","Step 2: Median position = (9 + 1) ÷ 2 = 5th.","Step 3: Cumulative frequencies are 1, 3, 7, 9.","Step 4: The 5th observation falls at x = 30.","Step 5: Median = 30."],"options":[],"conceptId":"math_statistics_44_median_from_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"44. Median from an Ungrouped Frequency Table"}', 2),
  (768, 225, 'There are 7 observations. What is the median position?', 'text', 1, 'Use (n + 1) ÷ 2.', '{"why":"Seven ordered observations have one central position: the fourth.","sol":"Step 1: n = 7.\nStep 2: (7 + 1) ÷ 2 = 4.\nStep 3: The median is at the 4th position.","steps":["Step 1: n = 7.","Step 2: (7 + 1) ÷ 2 = 4.","Step 3: The median is at the 4th position."],"options":[],"conceptId":"math_statistics_45_finding_the_median_position","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"45. Finding the Median Position"}', 0),
  (769, 225, 'There are 10 observations. What are the two median positions?', 'text', 1, 'Find n ÷ 2, then add 1.', '{"why":"An even-sized dataset has two central observations.","sol":"Step 1: n ÷ 2 = 10 ÷ 2 = 5.\nStep 2: The first middle position is 5th.\nStep 3: The second middle position is 6th.\nStep 4: Therefore the middle positions are 5th and 6th.","steps":["Step 1: n ÷ 2 = 10 ÷ 2 = 5.","Step 2: The first middle position is 5th.","Step 3: The second middle position is 6th.","Step 4: Therefore the middle positions are 5th and 6th."],"options":[],"conceptId":"math_statistics_45_finding_the_median_position","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"45. Finding the Median Position"}', 1),
  (770, 225, 'There are 14 observations. What are the two middle positions?', 'text', 1, '14 ÷ 2 gives the first middle position.', '{"why":"The median for an even dataset lies between the two central positions.","sol":"Step 1: 14 ÷ 2 = 7.\nStep 2: First middle position = 7th.\nStep 3: Second middle position = 8th.\nStep 4: Therefore the middle positions are 7th and 8th.","steps":["Step 1: 14 ÷ 2 = 7.","Step 2: First middle position = 7th.","Step 3: Second middle position = 8th.","Step 4: Therefore the middle positions are 7th and 8th."],"options":[],"conceptId":"math_statistics_45_finding_the_median_position","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"45. Finding the Median Position"}', 2),
  (771, 226, 'Find the median class for classes 0–9, 10–19 and 20–29 with frequencies 3, 5 and 2.', 'text', 1, 'Find the total frequency and the middle position.', '{"why":"The middle observations fall inside the 10–19 class.","sol":"Step 1: Total frequency = 3 + 5 + 2 = 10.\nStep 2: Middle positions are 5th and 6th.\nStep 3: Cumulative frequencies are 3, 8, 10.\nStep 4: Both the 5th and 6th observations lie in 10–19.\nStep 5: Median class = 10–19.","steps":["Step 1: Total frequency = 3 + 5 + 2 = 10.","Step 2: Middle positions are 5th and 6th.","Step 3: Cumulative frequencies are 3, 8, 10.","Step 4: Both the 5th and 6th observations lie in 10–19.","Step 5: Median class = 10–19."],"options":[],"conceptId":"math_statistics_46_median_of_grouped_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"46. Median of Grouped Data"}', 0),
  (772, 226, 'Find the median class for classes 10–19, 20–29 and 30–39 with frequencies 2, 4 and 5.', 'text', 1, 'There are 11 observations.', '{"why":"The sixth observation is the last observation represented by the 20–29 class.","sol":"Step 1: Total frequency = 2 + 4 + 5 = 11.\nStep 2: Median position = (11 + 1) ÷ 2 = 6th.\nStep 3: Cumulative frequencies are 2, 6, 11.\nStep 4: The 6th observation is in the 20–29 class.\nStep 5: Median class = 20–29.","steps":["Step 1: Total frequency = 2 + 4 + 5 = 11.","Step 2: Median position = (11 + 1) ÷ 2 = 6th.","Step 3: Cumulative frequencies are 2, 6, 11.","Step 4: The 6th observation is in the 20–29 class.","Step 5: Median class = 20–29."],"options":[],"conceptId":"math_statistics_46_median_of_grouped_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"46. Median of Grouped Data"}', 1),
  (773, 226, 'Find the median class for classes 0–9, 10–19, 20–29 and 30–39 with frequencies 1, 3, 6 and 2.', 'text', 1, 'There are 12 observations, so inspect positions 6 and 7.', '{"why":"The cumulative frequency reaches 10 in the 20–29 class, containing both middle observations.","sol":"Step 1: Total frequency = 1 + 3 + 6 + 2 = 12.\nStep 2: Middle positions are 6th and 7th.\nStep 3: Cumulative frequencies are 1, 4, 10, 12.\nStep 4: Both the 6th and 7th observations lie in 20–29.\nStep 5: Median class = 20–29.","steps":["Step 1: Total frequency = 1 + 3 + 6 + 2 = 12.","Step 2: Middle positions are 6th and 7th.","Step 3: Cumulative frequencies are 1, 4, 10, 12.","Step 4: Both the 6th and 7th observations lie in 20–29.","Step 5: Median class = 20–29."],"options":[],"conceptId":"math_statistics_46_median_of_grouped_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"46. Median of Grouped Data"}', 2),
  (774, 227, 'Cumulative frequencies are 3, 8, 14 and 20. If the median position is 10th, which class contains the median?', 'text', 1, 'Find the first cumulative frequency that is at least 10.', '{"why":"The third class contains observations 9 through 14.","sol":"Step 1: The cumulative frequencies are 3, 8, 14 and 20.\nStep 2: The 10th observation is beyond 8.\nStep 3: The next cumulative frequency is 14.\nStep 4: Therefore the median is in the third class.","steps":["Step 1: The cumulative frequencies are 3, 8, 14 and 20.","Step 2: The 10th observation is beyond 8.","Step 3: The next cumulative frequency is 14.","Step 4: Therefore the median is in the third class."],"options":[],"conceptId":"math_statistics_47_identifying_the_median_class","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"47. Identifying the Median Class"}', 0),
  (775, 227, 'A grouped table has cumulative frequencies 4, 9, 15 and 21. If the median position is 8th, which class is the median class?', 'text', 1, 'Locate 8 using the cumulative frequencies.', '{"why":"The second class contains observations 5 through 9.","sol":"Step 1: The first cumulative frequency is 4, which is below 8.\nStep 2: The second cumulative frequency is 9, which reaches 8.\nStep 3: Therefore the median lies in the second class.","steps":["Step 1: The first cumulative frequency is 4, which is below 8.","Step 2: The second cumulative frequency is 9, which reaches 8.","Step 3: Therefore the median lies in the second class."],"options":[],"conceptId":"math_statistics_47_identifying_the_median_class","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"47. Identifying the Median Class"}', 1),
  (776, 227, 'Cumulative frequencies are 2, 7, 13 and 18. If the middle positions are 9th and 10th, which class contains both?', 'text', 1, 'Find where positions 9 and 10 fall.', '{"why":"The third class contains observations 8 through 13.","sol":"Step 1: The first two cumulative frequencies are 2 and 7.\nStep 2: The third cumulative frequency is 13.\nStep 3: Therefore positions 9 and 10 lie in the third class.\nStep 4: Median class = third class.","steps":["Step 1: The first two cumulative frequencies are 2 and 7.","Step 2: The third cumulative frequency is 13.","Step 3: Therefore positions 9 and 10 lie in the third class.","Step 4: Median class = third class."],"options":[],"conceptId":"math_statistics_47_identifying_the_median_class","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"47. Identifying the Median Class"}', 2),
  (777, 228, 'The values 5, 10 and 15 have frequencies 3, 2 and 4. Find the median.', 'text', 1, 'There are 9 observations, so find the 5th observation.', '{"why":"The cumulative frequency reaches 5 at the value 10.","sol":"Step 1: Total frequency = 3 + 2 + 4 = 9.\nStep 2: Median position = (9 + 1) ÷ 2 = 5th.\nStep 3: Cumulative frequencies are 3, 5, 9.\nStep 4: The 5th observation is 10.\nStep 5: Median = 10.","steps":["Step 1: Total frequency = 3 + 2 + 4 = 9.","Step 2: Median position = (9 + 1) ÷ 2 = 5th.","Step 3: Cumulative frequencies are 3, 5, 9.","Step 4: The 5th observation is 10.","Step 5: Median = 10."],"options":[],"conceptId":"math_statistics_48_using_cumulative_frequency_to_locate_the_median","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"48. Using Cumulative Frequency to Locate the Median"}', 0),
  (778, 228, 'The values 2, 4 and 6 have frequencies 2, 3 and 5. Find the median.', 'text', 1, 'There are 10 observations. Find the 5th and 6th positions.', '{"why":"The two middle observations are 4 and 6.","sol":"Step 1: Total frequency = 10.\nStep 2: Middle positions are 5th and 6th.\nStep 3: The cumulative frequencies are 2, 5, 10.\nStep 4: The 5th observation is 4.\nStep 5: The 6th observation is 6.\nStep 6: Median = (4 + 6) ÷ 2 = 5.","steps":["Step 1: Total frequency = 10.","Step 2: Middle positions are 5th and 6th.","Step 3: The cumulative frequencies are 2, 5, 10.","Step 4: The 5th observation is 4.","Step 5: The 6th observation is 6.","Step 6: Median = (4 + 6) ÷ 2 = 5."],"options":[],"conceptId":"math_statistics_48_using_cumulative_frequency_to_locate_the_median","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"48. Using Cumulative Frequency to Locate the Median"}', 1),
  (779, 228, 'The values 10, 20 and 30 have frequencies 2, 5 and 1. Find the median.', 'text', 1, 'There are 8 observations.', '{"why":"Both middle observations are among the five occurrences of 20.","sol":"Step 1: Total frequency = 8.\nStep 2: Middle positions are 4th and 5th.\nStep 3: The cumulative frequency at 20 is 7.\nStep 4: Therefore both positions 4 and 5 correspond to 20.\nStep 5: Median = 20.","steps":["Step 1: Total frequency = 8.","Step 2: Middle positions are 4th and 5th.","Step 3: The cumulative frequency at 20 is 7.","Step 4: Therefore both positions 4 and 5 correspond to 20.","Step 5: Median = 20."],"options":[],"conceptId":"math_statistics_48_using_cumulative_frequency_to_locate_the_median","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"48. Using Cumulative Frequency to Locate the Median"}', 2),
  (780, 229, 'For the data 2, 4, 6, 8, 10, find the mean and median.', 'text', 1, 'Calculate the mean and identify the middle value.', '{"why":"The dataset is balanced around 6, so both measures give the same value.","sol":"Step 1: Mean = (2 + 4 + 6 + 8 + 10) ÷ 5.\nStep 2: Mean = 30 ÷ 5 = 6.\nStep 3: The middle value is 6.\nStep 4: Median = 6.","steps":["Step 1: Mean = (2 + 4 + 6 + 8 + 10) ÷ 5.","Step 2: Mean = 30 ÷ 5 = 6.","Step 3: The middle value is 6.","Step 4: Median = 6."],"options":[],"conceptId":"math_statistics_49_comparing_median_and_mean","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"49. Comparing Median and Mean"}', 0),
  (781, 229, 'For the data 2, 3, 4, 5, 26, find the mean and median.', 'text', 1, 'The data is already ordered.', '{"why":"The extreme value 26 raises the mean, while the median remains the middle value.","sol":"Step 1: Mean = (2 + 3 + 4 + 5 + 26) ÷ 5.\nStep 2: Mean = 40 ÷ 5 = 8.\nStep 3: The middle value is 4.\nStep 4: Median = 4.","steps":["Step 1: Mean = (2 + 3 + 4 + 5 + 26) ÷ 5.","Step 2: Mean = 40 ÷ 5 = 8.","Step 3: The middle value is 4.","Step 4: Median = 4."],"options":[],"conceptId":"math_statistics_49_comparing_median_and_mean","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"49. Comparing Median and Mean"}', 1),
  (782, 229, 'Which measure is more affected by the value 100 in the data 5, 6, 7, 8, 100: mean or median?', 'text', 1, 'Calculate both or consider how each is found.', '{"why":"The mean uses every numerical value, so an extreme value can strongly affect it.","sol":"Step 1: Mean = 25.2.\nStep 2: Median = 7.\nStep 3: The mean changed substantially because 100 contributes directly to the total.\nStep 4: The median remains the middle position.","steps":["Step 1: Mean = 25.2.","Step 2: Median = 7.","Step 3: The mean changed substantially because 100 contributes directly to the total.","Step 4: The median remains the middle position."],"options":[],"conceptId":"math_statistics_49_comparing_median_and_mean","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"49. Comparing Median and Mean"}', 2),
  (783, 230, 'For the data 4, 5, 6, 7 and 8, which measure gives a good description of the centre: mean or median?', 'text', 1, 'Check whether there is an extreme value.', '{"why":"The data is balanced and contains no extreme observation.","sol":"Step 1: There is no unusually large or small value.\nStep 2: Mean = (4 + 5 + 6 + 7 + 8) ÷ 5 = 6.\nStep 3: Median = 6.\nStep 4: Both describe the centre well.","steps":["Step 1: There is no unusually large or small value.","Step 2: Mean = (4 + 5 + 6 + 7 + 8) ÷ 5 = 6.","Step 3: Median = 6.","Step 4: Both describe the centre well."],"options":[],"conceptId":"math_statistics_50_choosing_between_mean_and_median","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"50. Choosing Between Mean and Median"}', 0),
  (784, 230, 'For the data 3, 4, 5, 6 and 50, which measure better represents the centre of most observations?', 'text', 1, 'Calculate the mean and compare it with the median.', '{"why":"The extreme value 50 pulls the mean upward.","sol":"Step 1: Mean = (3 + 4 + 5 + 6 + 50) ÷ 5.\nStep 2: Mean = 68 ÷ 5 = 13.6.\nStep 3: Median = 5.\nStep 4: Most observations are between 3 and 6.\nStep 5: The median is closer to the centre of most observations.","steps":["Step 1: Mean = (3 + 4 + 5 + 6 + 50) ÷ 5.","Step 2: Mean = 68 ÷ 5 = 13.6.","Step 3: Median = 5.","Step 4: Most observations are between 3 and 6.","Step 5: The median is closer to the centre of most observations."],"options":[],"conceptId":"math_statistics_50_choosing_between_mean_and_median","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"50. Choosing Between Mean and Median"}', 1),
  (785, 230, 'A dataset contains one extremely large value compared with all the others. Which measure is generally less affected by that extreme value?', 'text', 1, 'Think about whether the measure uses every value or only position.', '{"why":"The median is based on position rather than adding every value.","sol":"Step 1: The mean uses every value in its calculation.\nStep 2: An extremely large value therefore changes the total.\nStep 3: The median depends on the middle position.\nStep 4: Therefore the median is generally less affected.","steps":["Step 1: The mean uses every value in its calculation.","Step 2: An extremely large value therefore changes the total.","Step 3: The median depends on the middle position.","Step 4: Therefore the median is generally less affected."],"options":[],"conceptId":"math_statistics_50_choosing_between_mean_and_median","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"50. Choosing Between Mean and Median"}', 2),
  (786, 231, 'Find the mode of 2, 3, 3, 5 and 7.', 'text', 1, 'Count how many times each value occurs.', '{"why":"The mode is the value occurring most frequently.","sol":"Step 1: 2 occurs once.\nStep 2: 3 occurs twice.\nStep 3: 5 occurs once.\nStep 4: 7 occurs once.\nStep 5: The highest frequency is 2 for the value 3.","steps":["Step 1: 2 occurs once.","Step 2: 3 occurs twice.","Step 3: 5 occurs once.","Step 4: 7 occurs once.","Step 5: The highest frequency is 2 for the value 3."],"options":[],"conceptId":"math_statistics_51_meaning_of_the_mode","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"51. Meaning of the Mode"}', 0),
  (787, 231, 'Find the mode of 4, 6, 6, 8, 9, 6.', 'text', 1, 'Which value appears most often?', '{"why":"Six has the highest frequency.","sol":"Step 1: 4 occurs once.\nStep 2: 6 occurs three times.\nStep 3: 8 occurs once.\nStep 4: 9 occurs once.\nStep 5: Therefore the mode is 6.","steps":["Step 1: 4 occurs once.","Step 2: 6 occurs three times.","Step 3: 8 occurs once.","Step 4: 9 occurs once.","Step 5: Therefore the mode is 6."],"options":[],"conceptId":"math_statistics_51_meaning_of_the_mode","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"51. Meaning of the Mode"}', 1),
  (788, 231, 'Find the mode of 5, 5, 7, 8, 9, 5, 10.', 'text', 1, 'Count the occurrences of 5.', '{"why":"Five occurs more often than every other value.","sol":"Step 1: 5 occurs three times.\nStep 2: 7 occurs once.\nStep 3: 8 occurs once.\nStep 4: 9 occurs once.\nStep 5: 10 occurs once.\nStep 6: Therefore the mode is 5.","steps":["Step 1: 5 occurs three times.","Step 2: 7 occurs once.","Step 3: 8 occurs once.","Step 4: 9 occurs once.","Step 5: 10 occurs once.","Step 6: Therefore the mode is 5."],"options":[],"conceptId":"math_statistics_51_meaning_of_the_mode","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"51. Meaning of the Mode"}', 2),
  (789, 232, 'Find the mode of 3, 5, 3, 7, 3 and 9.', 'text', 1, 'Count each value.', '{"why":"Three occurs more frequently than every other value.","sol":"Step 1: 3 occurs three times.\nStep 2: 5 occurs once.\nStep 3: 7 occurs once.\nStep 4: 9 occurs once.\nStep 5: Therefore the mode is 3.","steps":["Step 1: 3 occurs three times.","Step 2: 5 occurs once.","Step 3: 7 occurs once.","Step 4: 9 occurs once.","Step 5: Therefore the mode is 3."],"options":[],"conceptId":"math_statistics_52_finding_mode_from_raw_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"52. Finding Mode from Raw Data"}', 0),
  (790, 232, 'Find the mode of 2, 4, 4, 6, 4, 8 and 9.', 'text', 1, 'Find the value with the highest frequency.', '{"why":"Four has the highest frequency of three.","sol":"Step 1: 2 occurs once.\nStep 2: 4 occurs three times.\nStep 3: 6 occurs once.\nStep 4: 8 occurs once.\nStep 5: 9 occurs once.\nStep 6: Therefore the mode is 4.","steps":["Step 1: 2 occurs once.","Step 2: 4 occurs three times.","Step 3: 6 occurs once.","Step 4: 8 occurs once.","Step 5: 9 occurs once.","Step 6: Therefore the mode is 4."],"options":[],"conceptId":"math_statistics_52_finding_mode_from_raw_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"52. Finding Mode from Raw Data"}', 1),
  (791, 232, 'Find the mode of 2, 2, 3, 3, 5, 7.', 'text', 1, 'Check whether one value occurs more often than the others.', '{"why":"Both 2 and 3 occur twice, which is the highest frequency.","sol":"Step 1: 2 occurs twice.\nStep 2: 3 occurs twice.\nStep 3: 5 occurs once.\nStep 4: 7 occurs once.\nStep 5: The highest frequency is 2.\nStep 6: Therefore the dataset has two modes: 2 and 3.","steps":["Step 1: 2 occurs twice.","Step 2: 3 occurs twice.","Step 3: 5 occurs once.","Step 4: 7 occurs once.","Step 5: The highest frequency is 2.","Step 6: Therefore the dataset has two modes: 2 and 3."],"options":[],"conceptId":"math_statistics_52_finding_mode_from_raw_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"52. Finding Mode from Raw Data"}', 2),
  (792, 233, 'Find the mode from x = 2, 4, 6 with frequencies 3, 7, 2 respectively.', 'text', 1, 'Find the largest frequency.', '{"why":"The value 4 occurs seven times, more than any other value.","sol":"Step 1: The frequencies are 3, 7 and 2.\nStep 2: The largest frequency is 7.\nStep 3: Frequency 7 belongs to x = 4.\nStep 4: Mode = 4.","steps":["Step 1: The frequencies are 3, 7 and 2.","Step 2: The largest frequency is 7.","Step 3: Frequency 7 belongs to x = 4.","Step 4: Mode = 4."],"options":[],"conceptId":"math_statistics_53_mode_from_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"53. Mode from an Ungrouped Frequency Table"}', 0),
  (793, 233, 'Find the mode from x = 5, 10, 15 with frequencies 2, 6, 4 respectively.', 'text', 1, 'The mode corresponds to the highest frequency.', '{"why":"Ten has the highest frequency.","sol":"Step 1: The frequencies are 2, 6 and 4.\nStep 2: The largest frequency is 6.\nStep 3: Frequency 6 belongs to x = 10.\nStep 4: Mode = 10.","steps":["Step 1: The frequencies are 2, 6 and 4.","Step 2: The largest frequency is 6.","Step 3: Frequency 6 belongs to x = 10.","Step 4: Mode = 10."],"options":[],"conceptId":"math_statistics_53_mode_from_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"53. Mode from an Ungrouped Frequency Table"}', 1),
  (794, 233, 'Find the mode from x = 1, 2, 3, 4 with frequencies 3, 5, 5, 2.', 'text', 1, 'There are two equal highest frequencies.', '{"why":"Both values occur with the highest frequency.","sol":"Step 1: The largest frequency is 5.\nStep 2: x = 2 has frequency 5.\nStep 3: x = 3 also has frequency 5.\nStep 4: Therefore the modes are 2 and 3.","steps":["Step 1: The largest frequency is 5.","Step 2: x = 2 has frequency 5.","Step 3: x = 3 also has frequency 5.","Step 4: Therefore the modes are 2 and 3."],"options":[],"conceptId":"math_statistics_53_mode_from_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"53. Mode from an Ungrouped Frequency Table"}', 2),
  (795, 234, 'Find the modal class for classes 0–9, 10–19 and 20–29 with frequencies 4, 9 and 6.', 'text', 1, 'Find the class with the largest frequency.', '{"why":"The modal class is the class with the highest frequency.","sol":"Step 1: The frequencies are 4, 9 and 6.\nStep 2: The largest frequency is 9.\nStep 3: Frequency 9 belongs to 10–19.\nStep 4: Modal class = 10–19.","steps":["Step 1: The frequencies are 4, 9 and 6.","Step 2: The largest frequency is 9.","Step 3: Frequency 9 belongs to 10–19.","Step 4: Modal class = 10–19."],"options":[],"conceptId":"math_statistics_54_identifying_the_modal_class","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"54. Identifying the Modal Class"}', 0),
  (796, 234, 'Find the modal class for classes 10–14, 15–19, 20–24 and 25–29 with frequencies 3, 5, 8 and 4.', 'text', 1, 'Look for frequency 8.', '{"why":"The 20–24 class contains the greatest number of observations.","sol":"Step 1: The largest frequency is 8.\nStep 2: Frequency 8 belongs to class 20–24.\nStep 3: Modal class = 20–24.","steps":["Step 1: The largest frequency is 8.","Step 2: Frequency 8 belongs to class 20–24.","Step 3: Modal class = 20–24."],"options":[],"conceptId":"math_statistics_54_identifying_the_modal_class","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"54. Identifying the Modal Class"}', 1),
  (797, 234, 'Classes 0–9, 10–19, 20–29 and 30–39 have frequencies 5, 7, 7 and 3. Identify the modal classes.', 'text', 1, 'Check which classes share the highest frequency.', '{"why":"Both classes have the highest frequency.","sol":"Step 1: The highest frequency is 7.\nStep 2: 10–19 has frequency 7.\nStep 3: 20–29 also has frequency 7.\nStep 4: Therefore both are modal classes.","steps":["Step 1: The highest frequency is 7.","Step 2: 10–19 has frequency 7.","Step 3: 20–29 also has frequency 7.","Step 4: Therefore both are modal classes."],"options":[],"conceptId":"math_statistics_54_identifying_the_modal_class","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"54. Identifying the Modal Class"}', 2),
  (798, 235, 'Find the mean, median and mode of 2, 3, 3, 4 and 8.', 'text', 1, 'Calculate each measure separately.', '{"why":"Each measure uses a different method to describe the dataset.","sol":"Step 1: Mean = (2 + 3 + 3 + 4 + 8) ÷ 5 = 20 ÷ 5 = 4.\nStep 2: The middle value is 3, so median = 3.\nStep 3: The value 3 occurs twice, so mode = 3.","steps":["Step 1: Mean = (2 + 3 + 3 + 4 + 8) ÷ 5 = 20 ÷ 5 = 4.","Step 2: The middle value is 3, so median = 3.","Step 3: The value 3 occurs twice, so mode = 3."],"options":[],"conceptId":"math_statistics_55_comparing_mean_median_and_mode","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"55. Comparing Mean, Median and Mode"}', 0),
  (799, 235, 'Find the mean, median and mode of 4, 5, 5, 5 and 6.', 'text', 1, 'Notice that 5 occurs most frequently.', '{"why":"All three measures happen to give the same value.","sol":"Step 1: Mean = (4 + 5 + 5 + 5 + 6) ÷ 5 = 25 ÷ 5 = 5.\nStep 2: Median = 5.\nStep 3: Mode = 5 because 5 occurs three times.","steps":["Step 1: Mean = (4 + 5 + 5 + 5 + 6) ÷ 5 = 25 ÷ 5 = 5.","Step 2: Median = 5.","Step 3: Mode = 5 because 5 occurs three times."],"options":[],"conceptId":"math_statistics_55_comparing_mean_median_and_mode","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"55. Comparing Mean, Median and Mode"}', 1),
  (800, 235, 'Find the mean, median and mode of 1, 2, 2, 3 and 12.', 'text', 1, 'The data is already ordered.', '{"why":"The extreme value 12 affects the mean but does not change the middle position or most frequent value.","sol":"Step 1: Mean = (1 + 2 + 2 + 3 + 12) ÷ 5 = 20 ÷ 5 = 4.\nStep 2: Median = 2.\nStep 3: Mode = 2 because it occurs twice.","steps":["Step 1: Mean = (1 + 2 + 2 + 3 + 12) ÷ 5 = 20 ÷ 5 = 4.","Step 2: Median = 2.","Step 3: Mode = 2 because it occurs twice."],"options":[],"conceptId":"math_statistics_55_comparing_mean_median_and_mode","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"55. Comparing Mean, Median and Mode"}', 2),
  (801, 236, 'Find the range of 2, 5, 7, 9 and 11.', 'text', 1, 'Subtract the smallest value from the largest.', '{"why":"Range measures the distance between the largest and smallest values.","sol":"Step 1: Largest value = 11.\nStep 2: Smallest value = 2.\nStep 3: Range = 11 − 2.\nStep 4: Range = 9.","steps":["Step 1: Largest value = 11.","Step 2: Smallest value = 2.","Step 3: Range = 11 − 2.","Step 4: Range = 9."],"options":[],"conceptId":"math_statistics_56_meaning_of_range","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"56. Meaning of Range"}', 0),
  (802, 236, 'Find the range of 15, 8, 20, 12 and 5.', 'text', 1, 'Identify 20 and 5 first.', '{"why":"The largest value is 15 units above the smallest value.","sol":"Step 1: Largest value = 20.\nStep 2: Smallest value = 5.\nStep 3: Range = 20 − 5.\nStep 4: Range = 15.","steps":["Step 1: Largest value = 20.","Step 2: Smallest value = 5.","Step 3: Range = 20 − 5.","Step 4: Range = 15."],"options":[],"conceptId":"math_statistics_56_meaning_of_range","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"56. Meaning of Range"}', 1),
  (803, 236, 'Find the range of 7, 7, 7, 7.', 'text', 1, 'The largest and smallest values are the same.', '{"why":"There is no spread because every observation has the same value.","sol":"Step 1: Largest value = 7.\nStep 2: Smallest value = 7.\nStep 3: Range = 7 − 7.\nStep 4: Range = 0.","steps":["Step 1: Largest value = 7.","Step 2: Smallest value = 7.","Step 3: Range = 7 − 7.","Step 4: Range = 0."],"options":[],"conceptId":"math_statistics_56_meaning_of_range","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"56. Meaning of Range"}', 2),
  (804, 237, 'Find the range of 4, 10, 7, 15 and 6.', 'text', 1, 'Largest minus smallest.', '{"why":"The range is the distance from the smallest observation to the largest.","sol":"Step 1: Largest = 15.\nStep 2: Smallest = 4.\nStep 3: Range = 15 − 4.\nStep 4: Range = 11.","steps":["Step 1: Largest = 15.","Step 2: Smallest = 4.","Step 3: Range = 15 − 4.","Step 4: Range = 11."],"options":[],"conceptId":"math_statistics_57_finding_range_from_raw_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"57. Finding Range from Raw Data"}', 0),
  (805, 237, 'Find the range of 22, 8, 31, 14 and 5.', 'text', 1, 'Find 31 and 5.', '{"why":"The largest and smallest values determine the range.","sol":"Step 1: Largest = 31.\nStep 2: Smallest = 5.\nStep 3: Range = 31 − 5.\nStep 4: Range = 26.","steps":["Step 1: Largest = 31.","Step 2: Smallest = 5.","Step 3: Range = 31 − 5.","Step 4: Range = 26."],"options":[],"conceptId":"math_statistics_57_finding_range_from_raw_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"57. Finding Range from Raw Data"}', 1),
  (806, 237, 'Find the range of −5, 2, 4, −1 and 8.', 'text', 1, 'The smallest value is negative.', '{"why":"Subtracting a negative value increases the distance between the extremes.","sol":"Step 1: Largest = 8.\nStep 2: Smallest = −5.\nStep 3: Range = 8 − (−5).\nStep 4: Range = 8 + 5.\nStep 5: Range = 13.","steps":["Step 1: Largest = 8.","Step 2: Smallest = −5.","Step 3: Range = 8 − (−5).","Step 4: Range = 8 + 5.","Step 5: Range = 13."],"options":[],"conceptId":"math_statistics_57_finding_range_from_raw_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"57. Finding Range from Raw Data"}', 2),
  (807, 238, 'Find the range from x = 2, 5, 8 with frequencies 4, 3, 2.', 'text', 1, 'Ignore the frequencies when calculating the range.', '{"why":"Range depends on the smallest and largest values, not their frequencies.","sol":"Step 1: Smallest value = 2.\nStep 2: Largest value = 8.\nStep 3: Range = 8 − 2.\nStep 4: Range = 6.","steps":["Step 1: Smallest value = 2.","Step 2: Largest value = 8.","Step 3: Range = 8 − 2.","Step 4: Range = 6."],"options":[],"conceptId":"math_statistics_58_finding_range_from_a_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"58. Finding Range from a Frequency Table"}', 0),
  (808, 238, 'Find the range from x = 10, 20, 35, 40 with frequencies 2, 4, 3, 1.', 'text', 1, 'Use 10 and 40.', '{"why":"The extreme values are 10 and 40.","sol":"Step 1: Smallest value = 10.\nStep 2: Largest value = 40.\nStep 3: Range = 40 − 10.\nStep 4: Range = 30.","steps":["Step 1: Smallest value = 10.","Step 2: Largest value = 40.","Step 3: Range = 40 − 10.","Step 4: Range = 30."],"options":[],"conceptId":"math_statistics_58_finding_range_from_a_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"58. Finding Range from a Frequency Table"}', 1),
  (809, 238, 'Find the range from x = −2, 4 and 9 with frequencies 3, 5 and 2.', 'text', 1, 'Subtract the negative smallest value.', '{"why":"The distance from −2 to 9 is 11.","sol":"Step 1: Largest = 9.\nStep 2: Smallest = −2.\nStep 3: Range = 9 − (−2).\nStep 4: Range = 11.","steps":["Step 1: Largest = 9.","Step 2: Smallest = −2.","Step 3: Range = 9 − (−2).","Step 4: Range = 11."],"options":[],"conceptId":"math_statistics_58_finding_range_from_a_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"58. Finding Range from a Frequency Table"}', 2),
  (810, 239, 'Dataset A is 2, 5, 7, 10. Dataset B is 1, 4, 8, 15. Which has the greater range?', 'text', 1, 'Calculate both ranges.', '{"why":"Dataset B has a larger distance between its smallest and largest values.","sol":"Step 1: Range A = 10 − 2 = 8.\nStep 2: Range B = 15 − 1 = 14.\nStep 3: 14 is greater than 8.\nStep 4: Therefore Dataset B has the greater range.","steps":["Step 1: Range A = 10 − 2 = 8.","Step 2: Range B = 15 − 1 = 14.","Step 3: 14 is greater than 8.","Step 4: Therefore Dataset B has the greater range."],"options":[],"conceptId":"math_statistics_59_comparing_two_data_sets_using_range","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"59. Comparing Two Data Sets Using Range"}', 0),
  (811, 239, 'Dataset A has smallest value 10 and largest value 25. Dataset B has smallest value 5 and largest value 18. Which has the smaller range?', 'text', 1, 'Find both ranges.', '{"why":"Dataset B''s extreme values are 13 units apart.","sol":"Step 1: Range A = 25 − 10 = 15.\nStep 2: Range B = 18 − 5 = 13.\nStep 3: 13 is smaller than 15.\nStep 4: Therefore Dataset B has the smaller range.","steps":["Step 1: Range A = 25 − 10 = 15.","Step 2: Range B = 18 − 5 = 13.","Step 3: 13 is smaller than 15.","Step 4: Therefore Dataset B has the smaller range."],"options":[],"conceptId":"math_statistics_59_comparing_two_data_sets_using_range","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"59. Comparing Two Data Sets Using Range"}', 1),
  (812, 239, 'Dataset A has range 7. Dataset B has range 12. Which dataset has greater spread according to the range?', 'text', 1, 'Compare 7 and 12.', '{"why":"A larger range indicates a larger distance between the extreme values.","sol":"Step 1: Range A = 7.\nStep 2: Range B = 12.\nStep 3: 12 is greater than 7.\nStep 4: Therefore Dataset B has greater spread.","steps":["Step 1: Range A = 7.","Step 2: Range B = 12.","Step 3: 12 is greater than 7.","Step 4: Therefore Dataset B has greater spread."],"options":[],"conceptId":"math_statistics_59_comparing_two_data_sets_using_range","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"59. Comparing Two Data Sets Using Range"}', 2),
  (813, 240, 'The data is 3, 5, 7, 9. A value of 20 is added. What is the new range?', 'text', 1, '20 becomes the new largest value.', '{"why":"The new value 20 becomes the largest observation.","sol":"Step 1: New largest value = 20.\nStep 2: Smallest value = 3.\nStep 3: New range = 20 − 3.\nStep 4: New range = 17.","steps":["Step 1: New largest value = 20.","Step 2: Smallest value = 3.","Step 3: New range = 20 − 3.","Step 4: New range = 17."],"options":[],"conceptId":"math_statistics_60_effect_of_an_extreme_value_on_range","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"60. Effect of an Extreme Value on Range"}', 0),
  (814, 240, 'The data is 4, 8, 10, 12. A value of 6 is added. What is the new range?', 'text', 1, 'Does 6 become the smallest or largest value?', '{"why":"Adding a value inside the existing extremes does not change the range.","sol":"Step 1: Original smallest = 4.\nStep 2: Original largest = 12.\nStep 3: The new value 6 lies between 4 and 12.\nStep 4: New range = 12 − 4 = 8.","steps":["Step 1: Original smallest = 4.","Step 2: Original largest = 12.","Step 3: The new value 6 lies between 4 and 12.","Step 4: New range = 12 − 4 = 8."],"options":[],"conceptId":"math_statistics_60_effect_of_an_extreme_value_on_range","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"60. Effect of an Extreme Value on Range"}', 1),
  (815, 240, 'The data is 10, 12, 15, 18. A value of 2 is added. What is the new range?', 'text', 1, '2 becomes the new smallest value.', '{"why":"The new value 2 extends the lower extreme of the dataset.","sol":"Step 1: New smallest value = 2.\nStep 2: Largest value = 18.\nStep 3: New range = 18 − 2.\nStep 4: New range = 16.","steps":["Step 1: New smallest value = 2.","Step 2: Largest value = 18.","Step 3: New range = 18 − 2.","Step 4: New range = 16."],"options":[],"conceptId":"math_statistics_60_effect_of_an_extreme_value_on_range","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"60. Effect of an Extreme Value on Range"}', 2),
  (816, 241, 'A bar graph shows 12 learners chose Biology. What does the height of the Biology bar represent?', 'text', 1, 'Read the value represented by the Biology bar.', '{"why":"The height of a bar represents the frequency or quantity for that category.","sol":"Step 1: Find the Biology category.\nStep 2: Read the height of its bar.\nStep 3: The height represents the number of learners.\nStep 4: The value is 12.","steps":["Step 1: Find the Biology category.","Step 2: Read the height of its bar.","Step 3: The height represents the number of learners.","Step 4: The value is 12."],"options":[],"conceptId":"math_statistics_reading_a_bar_graph","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Reading a Bar Graph"}', 0),
  (817, 241, 'A bar graph shows 25 books for Monday and 18 books for Tuesday. How many more books were recorded on Monday?', 'text', 1, 'Subtract Tuesday''s value from Monday''s value.', '{"why":"The difference between the two bar heights is 7.","sol":"Step 1: Monday = 25.\nStep 2: Tuesday = 18.\nStep 3: Difference = 25 − 18.\nStep 4: 25 − 18 = 7.","steps":["Step 1: Monday = 25.","Step 2: Tuesday = 18.","Step 3: Difference = 25 − 18.","Step 4: 25 − 18 = 7."],"options":[],"conceptId":"math_statistics_reading_a_bar_graph","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Reading a Bar Graph"}', 1),
  (818, 241, 'The bars for A, B and C have heights 9, 14 and 11 respectively. Which category has the greatest frequency?', 'text', 1, 'Find the greatest bar height.', '{"why":"The tallest bar represents the greatest frequency.","sol":"Step 1: A = 9.\nStep 2: B = 14.\nStep 3: C = 11.\nStep 4: The greatest value is 14.\nStep 5: Therefore B has the greatest frequency.","steps":["Step 1: A = 9.","Step 2: B = 14.","Step 3: C = 11.","Step 4: The greatest value is 14.","Step 5: Therefore B has the greatest frequency."],"options":[],"conceptId":"math_statistics_reading_a_bar_graph","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Reading a Bar Graph"}', 2),
  (819, 242, 'A table contains A = 5, B = 10 and C = 15. What should be the height of the bar for B?', 'text', 1, 'The bar height equals the frequency.', '{"why":"Each bar must reach the frequency of its category.","sol":"Step 1: Find the value for B.\nStep 2: B has a frequency of 10.\nStep 3: Therefore the B bar must reach 10.","steps":["Step 1: Find the value for B.","Step 2: B has a frequency of 10.","Step 3: Therefore the B bar must reach 10."],"options":[],"conceptId":"math_statistics_constructing_a_bar_graph","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Constructing a Bar Graph"}', 0),
  (820, 242, 'A dataset has frequencies 10, 20, 30 and 40. Give a suitable simple vertical scale.', 'text', 1, 'The largest value is 40.', '{"why":"The scale covers all values using equal intervals.","sol":"Step 1: Find the largest value: 40.\nStep 2: Use equal intervals on the vertical axis.\nStep 3: A suitable scale is 0, 10, 20, 30, 40.","steps":["Step 1: Find the largest value: 40.","Step 2: Use equal intervals on the vertical axis.","Step 3: A suitable scale is 0, 10, 20, 30, 40."],"options":[],"conceptId":"math_statistics_constructing_a_bar_graph","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Constructing a Bar Graph"}', 1),
  (821, 242, 'A category has frequency 18. If the vertical scale is marked every 5 units, where should its bar end?', 'text', 1, 'The bar must represent exactly 18.', '{"why":"The bar height must represent the actual frequency, even when it lies between scale marks.","sol":"Step 1: The scale has marks at 15 and 20.\nStep 2: 18 lies between 15 and 20.\nStep 3: Draw the bar to the level representing 18.","steps":["Step 1: The scale has marks at 15 and 20.","Step 2: 18 lies between 15 and 20.","Step 3: Draw the bar to the level representing 18."],"options":[],"conceptId":"math_statistics_constructing_a_bar_graph","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Constructing a Bar Graph"}', 2),
  (822, 243, 'A histogram has a bar of height 12 for the class 30–39. What does 12 represent?', 'text', 1, 'The vertical axis represents frequency.', '{"why":"Histogram bar height represents the frequency of the class.","sol":"Step 1: Find the class 30–39.\nStep 2: Its bar has height 12.\nStep 3: The height represents frequency.\nStep 4: Therefore 12 observations are in the class.","steps":["Step 1: Find the class 30–39.","Step 2: Its bar has height 12.","Step 3: The height represents frequency.","Step 4: Therefore 12 observations are in the class."],"options":[],"conceptId":"math_statistics_reading_a_histogram","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Reading a Histogram"}', 0),
  (823, 243, 'The frequencies of three histogram classes are 4, 11 and 7. Which class has the tallest bar?', 'text', 1, 'Find the greatest frequency.', '{"why":"The greatest frequency produces the tallest bar.","sol":"Step 1: Compare 4, 11 and 7.\nStep 2: The greatest frequency is 11.\nStep 3: Therefore the class with frequency 11 has the tallest bar.","steps":["Step 1: Compare 4, 11 and 7.","Step 2: The greatest frequency is 11.","Step 3: Therefore the class with frequency 11 has the tallest bar."],"options":[],"conceptId":"math_statistics_reading_a_histogram","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Reading a Histogram"}', 1),
  (824, 243, 'A histogram shows 6 observations in the class 40–49. How many observations belong to this class?', 'text', 1, 'Read the frequency from the bar.', '{"why":"Frequency tells how many observations belong to a class.","sol":"Step 1: Locate the class 40–49.\nStep 2: Its frequency is 6.\nStep 3: Therefore there are 6 observations in the class.","steps":["Step 1: Locate the class 40–49.","Step 2: Its frequency is 6.","Step 3: Therefore there are 6 observations in the class."],"options":[],"conceptId":"math_statistics_reading_a_histogram","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Reading a Histogram"}', 2),
  (825, 244, 'A grouped table has classes 0–9, 10–19 and 20–29 with frequencies 3, 6 and 5. What are the heights of the three histogram bars?', 'text', 1, 'Bar height equals frequency.', '{"why":"Each histogram bar reaches its class frequency.","sol":"Step 1: 0–9 has frequency 3.\nStep 2: 10–19 has frequency 6.\nStep 3: 20–29 has frequency 5.\nStep 4: Therefore the bar heights are 3, 6 and 5.","steps":["Step 1: 0–9 has frequency 3.","Step 2: 10–19 has frequency 6.","Step 3: 20–29 has frequency 5.","Step 4: Therefore the bar heights are 3, 6 and 5."],"options":[],"conceptId":"math_statistics_constructing_a_histogram","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Constructing a Histogram"}', 0),
  (826, 244, 'What boundary comes immediately between the classes 20–29 and 30–39?', 'text', 1, 'Find the midpoint between 29 and 30.', '{"why":"Class boundaries remove the gap between consecutive whole-number class limits.","sol":"Step 1: The upper limit of the first class is 29.\nStep 2: The lower limit of the next class is 30.\nStep 3: The boundary is halfway between them.\nStep 4: 29.5 is the boundary.","steps":["Step 1: The upper limit of the first class is 29.","Step 2: The lower limit of the next class is 30.","Step 3: The boundary is halfway between them.","Step 4: 29.5 is the boundary."],"options":[],"conceptId":"math_statistics_constructing_a_histogram","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Constructing a Histogram"}', 1),
  (827, 244, 'A histogram has frequencies 5, 9 and 7. Which bar should be tallest?', 'text', 1, 'Find the greatest frequency.', '{"why":"The largest frequency gives the tallest histogram bar.","sol":"Step 1: Compare 5, 9 and 7.\nStep 2: The greatest value is 9.\nStep 3: Therefore the bar with frequency 9 is tallest.","steps":["Step 1: Compare 5, 9 and 7.","Step 2: The greatest value is 9.","Step 3: Therefore the bar with frequency 9 is tallest."],"options":[],"conceptId":"math_statistics_constructing_a_histogram","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Constructing a Histogram"}', 2),
  (828, 245, 'A graph shows the number of learners choosing Mathematics, English and Biology. Should it be a bar graph or histogram?', 'text', 1, 'Are the values categories or numerical intervals?', '{"why":"Bar graphs represent separate categories.","sol":"Step 1: Mathematics, English and Biology are categories.\nStep 2: They are not numerical class intervals.\nStep 3: Therefore a bar graph is appropriate.","steps":["Step 1: Mathematics, English and Biology are categories.","Step 2: They are not numerical class intervals.","Step 3: Therefore a bar graph is appropriate."],"options":[],"conceptId":"math_statistics_bar_graph_versus_histogram","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Bar Graph versus Histogram"}', 0),
  (829, 245, 'Marks are grouped into 0–9, 10–19 and 20–29. Which graph is appropriate?', 'text', 1, 'These are numerical intervals.', '{"why":"Histograms represent grouped numerical data.","sol":"Step 1: The data are marks.\nStep 2: The marks have been grouped into numerical intervals.\nStep 3: Therefore a histogram is appropriate.","steps":["Step 1: The data are marks.","Step 2: The marks have been grouped into numerical intervals.","Step 3: Therefore a histogram is appropriate."],"options":[],"conceptId":"math_statistics_bar_graph_versus_histogram","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Bar Graph versus Histogram"}', 1),
  (830, 245, 'Why do histogram bars touch while bar graph bars normally have spaces?', 'text', 1, 'Think about what the horizontal axis represents.', '{"why":"The touching bars show that the numerical intervals are continuous or consecutive.","sol":"Step 1: Bar graphs represent separate categories.\nStep 2: Histograms represent consecutive numerical intervals.\nStep 3: Consecutive intervals join one another.\nStep 4: Therefore histogram bars touch.","steps":["Step 1: Bar graphs represent separate categories.","Step 2: Histograms represent consecutive numerical intervals.","Step 3: Consecutive intervals join one another.","Step 4: Therefore histogram bars touch."],"options":[],"conceptId":"math_statistics_bar_graph_versus_histogram","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Bar Graph versus Histogram"}', 2),
  (831, 246, 'A point on a frequency polygon is (25, 8). What is its frequency?', 'text', 1, 'The second coordinate represents frequency.', '{"why":"The vertical coordinate of a frequency polygon point represents frequency.","sol":"Step 1: The point is (25, 8).\nStep 2: The first coordinate is the midpoint.\nStep 3: The second coordinate is the frequency.\nStep 4: Therefore frequency = 8.","steps":["Step 1: The point is (25, 8).","Step 2: The first coordinate is the midpoint.","Step 3: The second coordinate is the frequency.","Step 4: Therefore frequency = 8."],"options":[],"conceptId":"math_statistics_reading_a_frequency_polygon","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Reading a Frequency Polygon"}', 0),
  (832, 246, 'A frequency polygon has points with frequencies 3, 9 and 5. Which point is highest?', 'text', 1, 'The largest frequency gives the highest point.', '{"why":"Higher frequency is represented by a higher point.","sol":"Step 1: Compare 3, 9 and 5.\nStep 2: The largest value is 9.\nStep 3: Therefore the point with frequency 9 is highest.","steps":["Step 1: Compare 3, 9 and 5.","Step 2: The largest value is 9.","Step 3: Therefore the point with frequency 9 is highest."],"options":[],"conceptId":"math_statistics_reading_a_frequency_polygon","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Reading a Frequency Polygon"}', 1),
  (833, 246, 'A point is plotted at (14.5, 6). What does 14.5 represent?', 'text', 1, 'Look at the first coordinate.', '{"why":"Frequency polygons plot frequency against class midpoint.","sol":"Step 1: The point is (14.5, 6).\nStep 2: The first coordinate gives the horizontal position.\nStep 3: In a frequency polygon this represents the class midpoint.\nStep 4: Therefore 14.5 is the class midpoint.","steps":["Step 1: The point is (14.5, 6).","Step 2: The first coordinate gives the horizontal position.","Step 3: In a frequency polygon this represents the class midpoint.","Step 4: Therefore 14.5 is the class midpoint."],"options":[],"conceptId":"math_statistics_reading_a_frequency_polygon","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Reading a Frequency Polygon"}', 2),
  (834, 247, 'Find the midpoint of the class 10–19.', 'text', 1, 'Use (lower limit + upper limit) ÷ 2.', '{"why":"The midpoint is the average of the two class limits.","sol":"Step 1: Lower limit = 10.\nStep 2: Upper limit = 19.\nStep 3: Midpoint = (10 + 19) ÷ 2.\nStep 4: Midpoint = 29 ÷ 2 = 14.5.","steps":["Step 1: Lower limit = 10.","Step 2: Upper limit = 19.","Step 3: Midpoint = (10 + 19) ÷ 2.","Step 4: Midpoint = 29 ÷ 2 = 14.5."],"options":[],"conceptId":"math_statistics_constructing_a_frequency_polygon","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Constructing a Frequency Polygon"}', 0),
  (835, 247, 'A class has midpoint 24.5 and frequency 6. What point should be plotted?', 'text', 1, 'Use (midpoint, frequency).', '{"why":"Frequency polygons plot class midpoint against frequency.","sol":"Step 1: Horizontal coordinate = midpoint = 24.5.\nStep 2: Vertical coordinate = frequency = 6.\nStep 3: Therefore the point is (24.5, 6).","steps":["Step 1: Horizontal coordinate = midpoint = 24.5.","Step 2: Vertical coordinate = frequency = 6.","Step 3: Therefore the point is (24.5, 6)."],"options":[],"conceptId":"math_statistics_constructing_a_frequency_polygon","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Constructing a Frequency Polygon"}', 1),
  (836, 247, 'For the class 30–39 with frequency 9, what point is plotted?', 'text', 1, 'First find the midpoint.', '{"why":"The midpoint becomes the x-coordinate and frequency becomes the y-coordinate.","sol":"Step 1: Midpoint = (30 + 39) ÷ 2.\nStep 2: Midpoint = 69 ÷ 2.\nStep 3: Midpoint = 34.5.\nStep 4: Frequency = 9.\nStep 5: Therefore the point is (34.5, 9).","steps":["Step 1: Midpoint = (30 + 39) ÷ 2.","Step 2: Midpoint = 69 ÷ 2.","Step 3: Midpoint = 34.5.","Step 4: Frequency = 9.","Step 5: Therefore the point is (34.5, 9)."],"options":[],"conceptId":"math_statistics_constructing_a_frequency_polygon","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Constructing a Frequency Polygon"}', 2),
  (837, 248, 'A frequency polygon has frequencies 4, 9 and 6. Which class has the greatest frequency?', 'text', 1, 'Find the largest frequency.', '{"why":"The highest point represents the greatest frequency.","sol":"Step 1: Compare 4, 9 and 6.\nStep 2: The largest is 9.\nStep 3: Therefore the class represented by frequency 9 has the greatest frequency.","steps":["Step 1: Compare 4, 9 and 6.","Step 2: The largest is 9.","Step 3: Therefore the class represented by frequency 9 has the greatest frequency."],"options":[],"conceptId":"math_statistics_interpreting_a_frequency_polygon","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Interpreting a Frequency Polygon"}', 0),
  (838, 248, 'Two consecutive classes have frequencies 10 and 7. How many fewer observations are in the second class?', 'text', 1, 'Subtract the smaller frequency from the larger one.', '{"why":"The second class contains 3 fewer observations.","sol":"Step 1: First class = 10.\nStep 2: Second class = 7.\nStep 3: Difference = 10 − 7.\nStep 4: Difference = 3.","steps":["Step 1: First class = 10.","Step 2: Second class = 7.","Step 3: Difference = 10 − 7.","Step 4: Difference = 3."],"options":[],"conceptId":"math_statistics_interpreting_a_frequency_polygon","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Interpreting a Frequency Polygon"}', 1),
  (839, 248, 'A frequency polygon reaches its highest point at midpoint 44.5. What does this tell you?', 'text', 1, 'Think about what the highest point means.', '{"why":"The highest point of a frequency polygon corresponds to the greatest frequency.","sol":"Step 1: The highest point represents the greatest frequency.\nStep 2: Its midpoint is 44.5.\nStep 3: Therefore the class centred at 44.5 has the greatest frequency.","steps":["Step 1: The highest point represents the greatest frequency.","Step 2: Its midpoint is 44.5.","Step 3: Therefore the class centred at 44.5 has the greatest frequency."],"options":[],"conceptId":"math_statistics_interpreting_a_frequency_polygon","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Interpreting a Frequency Polygon"}', 2),
  (840, 249, 'Representation A has frequencies 4, 7, 6. Representation B also has 4, 7, 6. Do they agree?', 'text', 1, 'Compare corresponding frequencies.', '{"why":"The two representations contain the same frequencies for every class.","sol":"Step 1: First frequency: 4 = 4.\nStep 2: Second frequency: 7 = 7.\nStep 3: Third frequency: 6 = 6.\nStep 4: All corresponding frequencies agree.","steps":["Step 1: First frequency: 4 = 4.","Step 2: Second frequency: 7 = 7.","Step 3: Third frequency: 6 = 6.","Step 4: All corresponding frequencies agree."],"options":[],"conceptId":"math_statistics_comparing_two_data_representations","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Comparing Two Data Representations"}', 0),
  (841, 249, 'One representation gives a frequency of 9 while another gives 6 for the same class. What is the difference?', 'text', 1, 'Subtract 6 from 9.', '{"why":"The representations disagree by 3 observations for that class.","sol":"Step 1: First frequency = 9.\nStep 2: Second frequency = 6.\nStep 3: Difference = 9 − 6.\nStep 4: Difference = 3.","steps":["Step 1: First frequency = 9.","Step 2: Second frequency = 6.","Step 3: Difference = 9 − 6.","Step 4: Difference = 3."],"options":[],"conceptId":"math_statistics_comparing_two_data_representations","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Comparing Two Data Representations"}', 1),
  (842, 249, 'Why should corresponding class frequencies be compared when checking two graphs?', 'text', 1, 'Think about what a graph is representing.', '{"why":"Matching corresponding frequencies verifies that the representations agree.","sol":"Step 1: Each graph represents frequencies for particular classes.\nStep 2: The same class must have the same frequency if the graphs represent the same data.\nStep 3: Therefore corresponding classes must be compared.","steps":["Step 1: Each graph represents frequencies for particular classes.","Step 2: The same class must have the same frequency if the graphs represent the same data.","Step 3: Therefore corresponding classes must be compared."],"options":[],"conceptId":"math_statistics_comparing_two_data_representations","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Comparing Two Data Representations"}', 2),
  (843, 250, 'A school wants to compare the number of learners in four houses. Which representation is appropriate?', 'text', 1, 'The houses are separate categories.', '{"why":"Bar graphs are appropriate for comparing separate categories.","sol":"Step 1: The data are grouped by house.\nStep 2: Each house is a separate category.\nStep 3: A bar graph is suitable for separate categories.","steps":["Step 1: The data are grouped by house.","Step 2: Each house is a separate category.","Step 3: A bar graph is suitable for separate categories."],"options":[],"conceptId":"math_statistics_choosing_the_appropriate_data_representation","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Choosing the Appropriate Data Representation"}', 0),
  (844, 250, 'Marks are grouped as 0–9, 10–19, 20–29 and 30–39. Which representation is appropriate?', 'text', 1, 'These are numerical class intervals.', '{"why":"Histograms represent grouped numerical intervals.","sol":"Step 1: The data are marks.\nStep 2: They are grouped into numerical intervals.\nStep 3: A histogram is suitable for grouped numerical data.","steps":["Step 1: The data are marks.","Step 2: They are grouped into numerical intervals.","Step 3: A histogram is suitable for grouped numerical data."],"options":[],"conceptId":"math_statistics_choosing_the_appropriate_data_representation","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Choosing the Appropriate Data Representation"}', 1),
  (845, 250, 'A teacher wants to show frequencies plotted against class midpoints and joined by straight lines. Which representation should be used?', 'text', 1, 'This description defines one particular graph.', '{"why":"A frequency polygon plots frequency against class midpoint and joins the points.","sol":"Step 1: The horizontal values are class midpoints.\nStep 2: The vertical values are frequencies.\nStep 3: The points are joined by straight lines.\nStep 4: This is a frequency polygon.","steps":["Step 1: The horizontal values are class midpoints.","Step 2: The vertical values are frequencies.","Step 3: The points are joined by straight lines.","Step 4: This is a frequency polygon."],"options":[],"conceptId":"math_statistics_choosing_the_appropriate_data_representation","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Choosing the Appropriate Data Representation"}', 2),
  (846, 251, 'A coin is tossed once. Is this a probability experiment?', 'text', 1, 'Ask whether the possible outcomes are known but the actual result is unknown.', '{"why":"A probability experiment has known possible outcomes but an uncertain actual outcome.","sol":"Step 1: The possible outcomes are Head and Tail.\nStep 2: The actual result is not known before the coin is tossed.\nStep 3: Therefore, it is a probability experiment.","steps":["Step 1: The possible outcomes are Head and Tail.","Step 2: The actual result is not known before the coin is tossed.","Step 3: Therefore, it is a probability experiment."],"options":[],"conceptId":"math_probability_probability_experiment","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Probability Experiment"}', 0),
  (847, 251, 'A six-sided die is rolled once. Is this a probability experiment?', 'text', 1, 'List what can happen before deciding.', '{"why":"The possible outcomes are known, but the actual outcome cannot be predicted with certainty.","sol":"Step 1: The possible outcomes are 1, 2, 3, 4, 5 and 6.\nStep 2: The number that will appear is not known before the roll.\nStep 3: Therefore, it is a probability experiment.","steps":["Step 1: The possible outcomes are 1, 2, 3, 4, 5 and 6.","Step 2: The number that will appear is not known before the roll.","Step 3: Therefore, it is a probability experiment."],"options":[],"conceptId":"math_probability_probability_experiment","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Probability Experiment"}', 1),
  (848, 251, 'A bag contains red and green balls. One ball is drawn without looking. Explain why this is a probability experiment.', 'text', 1, 'Think about what is known and what is unknown.', '{"why":"Probability experiments involve uncertainty about which known possible outcome will occur.","sol":"Step 1: The possible outcomes include red and green.\nStep 2: The colour of the ball is not known before the draw.\nStep 3: Therefore, the draw is a probability experiment.","steps":["Step 1: The possible outcomes include red and green.","Step 2: The colour of the ball is not known before the draw.","Step 3: Therefore, the draw is a probability experiment."],"options":[],"conceptId":"math_probability_probability_experiment","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Probability Experiment"}', 2),
  (849, 252, 'A coin is tossed once. List all possible outcomes.', 'text', 1, 'A coin has two possible results.', '{"why":"These are the two possible results of one coin toss.","sol":"Step 1: A coin can land on Head.\nStep 2: A coin can land on Tail.\nStep 3: Therefore the outcomes are {H, T}.","steps":["Step 1: A coin can land on Head.","Step 2: A coin can land on Tail.","Step 3: Therefore the outcomes are {H, T}."],"options":[],"conceptId":"math_probability_outcomes_of_an_experiment","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Outcomes of an Experiment"}', 0),
  (850, 252, 'A standard die is rolled once. List all possible outcomes.', 'text', 1, 'A standard die has six numbered faces.', '{"why":"Each face of the die represents one possible outcome.","sol":"Step 1: The die can show 1.\nStep 2: It can show 2, 3, 4, 5 or 6.\nStep 3: Therefore the outcomes are {1, 2, 3, 4, 5, 6}.","steps":["Step 1: The die can show 1.","Step 2: It can show 2, 3, 4, 5 or 6.","Step 3: Therefore the outcomes are {1, 2, 3, 4, 5, 6}."],"options":[],"conceptId":"math_probability_outcomes_of_an_experiment","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Outcomes of an Experiment"}', 1),
  (851, 252, 'A bag contains red, blue and yellow balls. One ball is selected. What are the possible colour outcomes?', 'text', 1, 'Record colours, not individual balls.', '{"why":"The question asks for possible colour outcomes.","sol":"Step 1: A red ball may be selected.\nStep 2: A blue ball may be selected.\nStep 3: A yellow ball may be selected.\nStep 4: Therefore the outcomes are {Red, Blue, Yellow}.","steps":["Step 1: A red ball may be selected.","Step 2: A blue ball may be selected.","Step 3: A yellow ball may be selected.","Step 4: Therefore the outcomes are {Red, Blue, Yellow}."],"options":[],"conceptId":"math_probability_outcomes_of_an_experiment","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Outcomes of an Experiment"}', 2),
  (852, 253, 'A coin is tossed 8 times and gives H, T, H, H, T, H, T, H. How many Heads occurred?', 'text', 1, 'Count every H.', '{"why":"Frequency tells us how many times an outcome occurred.","sol":"Step 1: The Heads are in positions 1, 3, 4, 6 and 8.\nStep 2: There are 5 Heads.\nStep 3: Therefore, the frequency of Heads is 5.","steps":["Step 1: The Heads are in positions 1, 3, 4, 6 and 8.","Step 2: There are 5 Heads.","Step 3: Therefore, the frequency of Heads is 5."],"options":[],"conceptId":"math_probability_recording_experimental_results","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Recording Experimental Results"}', 0),
  (853, 253, 'A die is rolled 10 times. The number 4 appears 3 times. What is the frequency of 4?', 'text', 1, 'Frequency means the number of times an outcome occurs.', '{"why":"The frequency of an outcome is simply how many times it occurred.","sol":"Step 1: The number 4 occurred 3 times.\nStep 2: Therefore, its frequency is 3.","steps":["Step 1: The number 4 occurred 3 times.","Step 2: Therefore, its frequency is 3."],"options":[],"conceptId":"math_probability_recording_experimental_results","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Recording Experimental Results"}', 1),
  (854, 253, 'A coin is tossed 20 times. Heads occur 11 times. How many Tails occurred?', 'text', 1, 'Every trial gives either Head or Tail.', '{"why":"The Head and Tail frequencies must add to the total number of tosses.","sol":"Step 1: Total tosses = 20.\nStep 2: Heads = 11.\nStep 3: Tails = 20 − 11.\nStep 4: Tails = 9.","steps":["Step 1: Total tosses = 20.","Step 2: Heads = 11.","Step 3: Tails = 20 − 11.","Step 4: Tails = 9."],"options":[],"conceptId":"math_probability_recording_experimental_results","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Recording Experimental Results"}', 2),
  (855, 254, 'A coin is tossed 50 times and Heads occur 27 times. Find the experimental probability of Heads.', 'text', 1, 'Use frequency of Heads ÷ total tosses.', '{"why":"Experimental probability uses the observed frequency divided by the total number of trials.","sol":"Step 1: Heads occurred 27 times.\nStep 2: Total tosses = 50.\nStep 3: P(Head) = 27 ÷ 50.\nStep 4: P(Head) = 27/50.","steps":["Step 1: Heads occurred 27 times.","Step 2: Total tosses = 50.","Step 3: P(Head) = 27 ÷ 50.","Step 4: P(Head) = 27/50."],"options":[],"conceptId":"math_probability_calculating_experimental_probability","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Calculating Experimental Probability"}', 0),
  (856, 254, 'A die is rolled 40 times and the number 3 appears 7 times. Find the experimental probability of rolling 3.', 'text', 1, 'Divide 7 by 40.', '{"why":"The observed frequency of 3 is 7 out of 40 rolls.","sol":"Step 1: Frequency of 3 = 7.\nStep 2: Total trials = 40.\nStep 3: P(3) = 7 ÷ 40.\nStep 4: P(3) = 7/40.","steps":["Step 1: Frequency of 3 = 7.","Step 2: Total trials = 40.","Step 3: P(3) = 7 ÷ 40.","Step 4: P(3) = 7/40."],"options":[],"conceptId":"math_probability_calculating_experimental_probability","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Calculating Experimental Probability"}', 1),
  (857, 254, 'A spinner is spun 25 times and lands on blue 10 times. Find the experimental probability of blue.', 'text', 1, 'Observed blue outcomes ÷ total spins.', '{"why":"The experiment produced 10 blue results in 25 trials.","sol":"Step 1: Blue occurred 10 times.\nStep 2: Total spins = 25.\nStep 3: P(Blue) = 10 ÷ 25.\nStep 4: P(Blue) = 2/5.","steps":["Step 1: Blue occurred 10 times.","Step 2: Total spins = 25.","Step 3: P(Blue) = 10 ÷ 25.","Step 4: P(Blue) = 2/5."],"options":[],"conceptId":"math_probability_calculating_experimental_probability","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Calculating Experimental Probability"}', 2),
  (858, 255, 'A fair coin has a theoretical probability of 1/2 of getting Head. In 10 tosses, Head occurs 7 times. Find the experimental probability.', 'text', 1, 'Use observed Heads ÷ total tosses.', '{"why":"Experimental probability is calculated from the actual results of the experiment.","sol":"Step 1: Heads occurred 7 times.\nStep 2: Total tosses = 10.\nStep 3: Experimental probability = 7 ÷ 10.\nStep 4: Experimental probability = 7/10.","steps":["Step 1: Heads occurred 7 times.","Step 2: Total tosses = 10.","Step 3: Experimental probability = 7 ÷ 10.","Step 4: Experimental probability = 7/10."],"options":[],"conceptId":"math_probability_comparing_experimental_and_theoretical_probability","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Comparing Experimental and Theoretical Probability"}', 0),
  (859, 255, 'A fair die has a theoretical probability of 1/6 of rolling a 6. In 60 rolls, 12 sixes occur. Find the experimental probability.', 'text', 1, 'Divide the number of sixes by the number of rolls.', '{"why":"The experimental probability comes from the observed frequency, not the theoretical value.","sol":"Step 1: Six occurred 12 times.\nStep 2: Total rolls = 60.\nStep 3: Experimental probability = 12 ÷ 60.\nStep 4: Experimental probability = 1/5.","steps":["Step 1: Six occurred 12 times.","Step 2: Total rolls = 60.","Step 3: Experimental probability = 12 ÷ 60.","Step 4: Experimental probability = 1/5."],"options":[],"conceptId":"math_probability_comparing_experimental_and_theoretical_probability","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Comparing Experimental and Theoretical Probability"}', 1),
  (860, 255, 'A fair coin is tossed 100 times and gives 49 Heads. Is the experimental probability close to the theoretical probability of 1/2?', 'text', 1, 'Calculate the experimental probability first.', '{"why":"A large number of trials often produces an experimental probability close to the theoretical probability.","sol":"Step 1: Experimental probability = 49 ÷ 100.\nStep 2: Experimental probability = 0.49.\nStep 3: Theoretical probability = 0.50.\nStep 4: The difference is 0.01.\nStep 5: Therefore, the experimental probability is close to the theoretical probability.","steps":["Step 1: Experimental probability = 49 ÷ 100.","Step 2: Experimental probability = 0.49.","Step 3: Theoretical probability = 0.50.","Step 4: The difference is 0.01.","Step 5: Therefore, the experimental probability is close to the theoretical probability."],"options":[],"conceptId":"math_probability_comparing_experimental_and_theoretical_probability","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Comparing Experimental and Theoretical Probability"}', 2),
  (861, 256, 'A coin is tossed once. Write the probability space.', 'text', 1, 'Think of every result that can occur when one coin is tossed.', '{"why":"A single coin toss has exactly two possible outcomes: Head and Tail.","sol":"Step 1: A coin can land showing a Head or a Tail.\nStep 2: Write both possible outcomes.\nStep 3: Therefore S = {H, T}.","steps":["Step 1: A coin can land showing a Head or a Tail.","Step 2: Write both possible outcomes.","Step 3: Therefore S = {H, T}."],"options":[],"conceptId":"math_probability_complete_probability_space","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Complete Probability Space"}', 0),
  (862, 256, 'A standard die is rolled once. Write the probability space.', 'text', 1, 'A standard die has six numbered faces.', '{"why":"Any one of the six faces can appear when the die is rolled.","sol":"Step 1: The smallest number on the die is 1.\nStep 2: The numbers continue through 2, 3, 4 and 5.\nStep 3: The largest number is 6.\nStep 4: Therefore S = {1, 2, 3, 4, 5, 6}.","steps":["Step 1: The smallest number on the die is 1.","Step 2: The numbers continue through 2, 3, 4 and 5.","Step 3: The largest number is 6.","Step 4: Therefore S = {1, 2, 3, 4, 5, 6}."],"options":[],"conceptId":"math_probability_complete_probability_space","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Complete Probability Space"}', 1),
  (863, 256, 'A card is chosen from cards labelled A, B, C and D. Write the probability space.', 'text', 1, 'List every label that can be selected.', '{"why":"The probability space contains every possible result of selecting one card.","sol":"Step 1: The possible cards are A, B, C and D.\nStep 2: Each one is a possible result of the experiment.\nStep 3: Therefore S = {A, B, C, D}.","steps":["Step 1: The possible cards are A, B, C and D.","Step 2: Each one is a possible result of the experiment.","Step 3: Therefore S = {A, B, C, D}."],"options":[],"conceptId":"math_probability_complete_probability_space","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Complete Probability Space"}', 2),
  (864, 257, 'A spinner has four equal sections labelled 1, 2, 3 and 4. List all possible outcomes.', 'text', 1, 'Every label on the spinner can be obtained.', '{"why":"Every labelled section is a possible outcome.","sol":"Step 1: The spinner contains section 1.\nStep 2: It also contains sections 2, 3 and 4.\nStep 3: Any of these sections can be selected.\nStep 4: Therefore S = {1, 2, 3, 4}.","steps":["Step 1: The spinner contains section 1.","Step 2: It also contains sections 2, 3 and 4.","Step 3: Any of these sections can be selected.","Step 4: Therefore S = {1, 2, 3, 4}."],"options":[],"conceptId":"math_probability_listing_outcomes_of_a_single_experiment","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Listing Outcomes of a Single Experiment"}', 0),
  (865, 257, 'One letter is selected from {M, N, P}. List the probability space.', 'text', 1, 'The selected letter can be M, N or P.', '{"why":"These are all the choices available in the experiment.","sol":"Step 1: M is a possible result.\nStep 2: N is a possible result.\nStep 3: P is a possible result.\nStep 4: Therefore S = {M, N, P}.","steps":["Step 1: M is a possible result.","Step 2: N is a possible result.","Step 3: P is a possible result.","Step 4: Therefore S = {M, N, P}."],"options":[],"conceptId":"math_probability_listing_outcomes_of_a_single_experiment","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Listing Outcomes of a Single Experiment"}', 1),
  (866, 257, 'A die is rolled once. A student writes {1, 2, 3, 4, 5}. Is this a complete probability space?', 'text', 1, 'Check whether every possible die result has been included.', '{"why":"A complete probability space for one die must include 6.","sol":"Step 1: A standard die can produce 1, 2, 3, 4, 5 or 6.\nStep 2: The student''s list does not contain 6.\nStep 3: Therefore one possible outcome is missing.\nStep 4: The list is not complete.","steps":["Step 1: A standard die can produce 1, 2, 3, 4, 5 or 6.","Step 2: The student''s list does not contain 6.","Step 3: Therefore one possible outcome is missing.","Step 4: The list is not complete."],"options":[],"conceptId":"math_probability_listing_outcomes_of_a_single_experiment","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Listing Outcomes of a Single Experiment"}', 2),
  (867, 258, 'A coin is tossed twice. Write the complete probability space.', 'text', 1, 'Start with H on the first toss, then T on the first toss.', '{"why":"Each of the two tosses can be H or T, producing four ordered outcomes.","sol":"Step 1: If the first toss is H, the second toss can be H or T: HH, HT.\nStep 2: If the first toss is T, the second toss can be H or T: TH, TT.\nStep 3: Combine all four outcomes.\nStep 4: Therefore S = {HH, HT, TH, TT}.","steps":["Step 1: If the first toss is H, the second toss can be H or T: HH, HT.","Step 2: If the first toss is T, the second toss can be H or T: TH, TT.","Step 3: Combine all four outcomes.","Step 4: Therefore S = {HH, HT, TH, TT}."],"options":[],"conceptId":"math_probability_probability_space_for_two_coin_tosses","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Probability Space for Two Coin Tosses"}', 0),
  (868, 258, 'A student says that HH and TT are the only possible outcomes when a coin is tossed twice. What is wrong?', 'text', 1, 'Consider what happens when the two tosses are different.', '{"why":"Two tosses can have different results, not only matching results.","sol":"Step 1: The first toss can be H and the second T, giving HT.\nStep 2: The first toss can also be T and the second H, giving TH.\nStep 3: Therefore HT and TH are also possible.\nStep 4: The student''s list is incomplete.","steps":["Step 1: The first toss can be H and the second T, giving HT.","Step 2: The first toss can also be T and the second H, giving TH.","Step 3: Therefore HT and TH are also possible.","Step 4: The student''s list is incomplete."],"options":[],"conceptId":"math_probability_probability_space_for_two_coin_tosses","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Probability Space for Two Coin Tosses"}', 1),
  (869, 258, 'Explain why HT and TH are different outcomes.', 'text', 1, 'Look at the order of the two tosses.', '{"why":"An outcome of a repeated experiment records what happened at each stage.","sol":"Step 1: HT means H occurs first and T occurs second.\nStep 2: TH means T occurs first and H occurs second.\nStep 3: The order of the results is different.\nStep 4: Therefore they represent different outcomes.","steps":["Step 1: HT means H occurs first and T occurs second.","Step 2: TH means T occurs first and H occurs second.","Step 3: The order of the results is different.","Step 4: Therefore they represent different outcomes."],"options":[],"conceptId":"math_probability_probability_space_for_two_coin_tosses","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Probability Space for Two Coin Tosses"}', 2),
  (870, 259, 'A die is rolled and then a coin is tossed. List all possible outcomes.', 'text', 1, 'For every die result, attach H and T.', '{"why":"Each of the 6 die results can be followed by either H or T.","sol":"Step 1: The die can give 1, 2, 3, 4, 5 or 6.\nStep 2: For each die result, the coin can give H or T.\nStep 3: Therefore the outcomes are 1H, 1T, 2H, 2T, 3H, 3T, 4H, 4T, 5H, 5T, 6H, 6T.\nStep 4: There are 12 outcomes.","steps":["Step 1: The die can give 1, 2, 3, 4, 5 or 6.","Step 2: For each die result, the coin can give H or T.","Step 3: Therefore the outcomes are 1H, 1T, 2H, 2T, 3H, 3T, 4H, 4T, 5H, 5T, 6H, 6T.","Step 4: There are 12 outcomes."],"options":[],"conceptId":"math_probability_systematically_listing_two_stage_outcomes","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Systematically Listing Two-Stage Outcomes"}', 0),
  (871, 259, 'A spinner has A or B. A coin is then tossed. List all possible outcomes.', 'text', 1, 'Start with A, then start with B.', '{"why":"Every first-stage outcome must be paired with every possible second-stage outcome.","sol":"Step 1: If the spinner gives A, the coin can give H or T: AH, AT.\nStep 2: If the spinner gives B, the coin can give H or T: BH, BT.\nStep 3: Therefore S = {AH, AT, BH, BT}.","steps":["Step 1: If the spinner gives A, the coin can give H or T: AH, AT.","Step 2: If the spinner gives B, the coin can give H or T: BH, BT.","Step 3: Therefore S = {AH, AT, BH, BT}."],"options":[],"conceptId":"math_probability_systematically_listing_two_stage_outcomes","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Systematically Listing Two-Stage Outcomes"}', 1),
  (872, 259, 'A two-stage experiment has first-stage outcomes P and Q, and second-stage outcomes 1, 2 and 3. List all possible outcomes.', 'text', 1, 'Pair P with all three numbers, then Q with all three numbers.', '{"why":"There are 2 choices at the first stage and 3 choices at the second stage, giving 6 combinations.","sol":"Step 1: Starting with P gives P1, P2 and P3.\nStep 2: Starting with Q gives Q1, Q2 and Q3.\nStep 3: Combine the outcomes.\nStep 4: Therefore S = {P1, P2, P3, Q1, Q2, Q3}.","steps":["Step 1: Starting with P gives P1, P2 and P3.","Step 2: Starting with Q gives Q1, Q2 and Q3.","Step 3: Combine the outcomes.","Step 4: Therefore S = {P1, P2, P3, Q1, Q2, Q3}."],"options":[],"conceptId":"math_probability_systematically_listing_two_stage_outcomes","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Systematically Listing Two-Stage Outcomes"}', 2),
  (873, 260, 'A fair die is rolled. Find the probability of getting 5.', 'text', 1, 'First write the complete probability space.', '{"why":"One of the six equally likely die outcomes is 5.","sol":"Step 1: The probability space is {1, 2, 3, 4, 5, 6}.\nStep 2: Only 5 is favourable, so there is 1 favourable outcome.\nStep 3: There are 6 possible outcomes in total.\nStep 4: Therefore P(5) = 1/6.","steps":["Step 1: The probability space is {1, 2, 3, 4, 5, 6}.","Step 2: Only 5 is favourable, so there is 1 favourable outcome.","Step 3: There are 6 possible outcomes in total.","Step 4: Therefore P(5) = 1/6."],"options":[],"conceptId":"math_probability_theoretical_probability_from_a_probability_space","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Theoretical Probability from a Probability Space"}', 0),
  (874, 260, 'A fair die is rolled. Find the probability of getting an odd number.', 'text', 1, 'Identify the odd outcomes in {1, 2, 3, 4, 5, 6}.', '{"why":"Three of the six equally likely die outcomes are odd.","sol":"Step 1: The odd outcomes are 1, 3 and 5.\nStep 2: There are 3 favourable outcomes.\nStep 3: There are 6 total outcomes.\nStep 4: Therefore P(odd) = 3/6.\nStep 5: Simplify 3/6 by dividing by 3.\nStep 6: P(odd) = 1/2.","steps":["Step 1: The odd outcomes are 1, 3 and 5.","Step 2: There are 3 favourable outcomes.","Step 3: There are 6 total outcomes.","Step 4: Therefore P(odd) = 3/6.","Step 5: Simplify 3/6 by dividing by 3.","Step 6: P(odd) = 1/2."],"options":[],"conceptId":"math_probability_theoretical_probability_from_a_probability_space","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Theoretical Probability from a Probability Space"}', 1),
  (875, 260, 'A fair coin is tossed twice. Find the probability of getting exactly two tails.', 'text', 1, 'Use the probability space for two coin tosses.', '{"why":"TT is the only outcome containing two tails.","sol":"Step 1: The probability space is {HH, HT, TH, TT}.\nStep 2: Exactly two tails occurs only in TT.\nStep 3: There is 1 favourable outcome.\nStep 4: There are 4 total outcomes.\nStep 5: Therefore P(two tails) = 1/4.","steps":["Step 1: The probability space is {HH, HT, TH, TT}.","Step 2: Exactly two tails occurs only in TT.","Step 3: There is 1 favourable outcome.","Step 4: There are 4 total outcomes.","Step 5: Therefore P(two tails) = 1/4."],"options":[],"conceptId":"math_probability_theoretical_probability_from_a_probability_space","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Theoretical Probability from a Probability Space"}', 2),
  (876, 261, 'A standard die is rolled. What is the probability of getting 9?', 'text', 1, 'Check whether 9 is one of the possible die outcomes.', '{"why":"A standard die cannot produce 9.","sol":"Step 1: The possible outcomes are 1, 2, 3, 4, 5 and 6.\nStep 2: 9 is not a possible outcome.\nStep 3: Therefore there are 0 favourable outcomes.\nStep 4: P(9) = 0/6 = 0.","steps":["Step 1: The possible outcomes are 1, 2, 3, 4, 5 and 6.","Step 2: 9 is not a possible outcome.","Step 3: Therefore there are 0 favourable outcomes.","Step 4: P(9) = 0/6 = 0."],"options":[],"conceptId":"math_probability_impossible_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Impossible Events"}', 0),
  (877, 261, 'A bag contains only red and blue balls. One ball is selected. What is the probability of selecting a green ball?', 'text', 1, 'Is green one of the possible colours in the bag?', '{"why":"There is no green ball available to be selected.","sol":"Step 1: The only possible colours are red and blue.\nStep 2: Green is not in the bag.\nStep 3: Therefore selecting green is impossible.\nStep 4: The probability is 0.","steps":["Step 1: The only possible colours are red and blue.","Step 2: Green is not in the bag.","Step 3: Therefore selecting green is impossible.","Step 4: The probability is 0."],"options":[],"conceptId":"math_probability_impossible_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Impossible Events"}', 1),
  (878, 261, 'A coin is tossed once. What is the probability of getting both Head and Tail?', 'text', 1, 'A single toss produces only one result.', '{"why":"One coin toss gives one outcome, not two outcomes at the same time.","sol":"Step 1: The possible outcomes are H and T.\nStep 2: One toss cannot produce H and T simultaneously.\nStep 3: Therefore the event is impossible.\nStep 4: Its probability is 0.","steps":["Step 1: The possible outcomes are H and T.","Step 2: One toss cannot produce H and T simultaneously.","Step 3: Therefore the event is impossible.","Step 4: Its probability is 0."],"options":[],"conceptId":"math_probability_impossible_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Impossible Events"}', 2),
  (879, 262, 'A standard die is rolled. Find the probability of getting a number less than 7.', 'text', 1, 'Check every possible result of the die.', '{"why":"Every possible result of a standard die is less than 7.","sol":"Step 1: The outcomes are 1, 2, 3, 4, 5 and 6.\nStep 2: Every one of these numbers is less than 7.\nStep 3: Therefore there are 6 favourable outcomes out of 6.\nStep 4: P(number less than 7) = 6/6 = 1.","steps":["Step 1: The outcomes are 1, 2, 3, 4, 5 and 6.","Step 2: Every one of these numbers is less than 7.","Step 3: Therefore there are 6 favourable outcomes out of 6.","Step 4: P(number less than 7) = 6/6 = 1."],"options":[],"conceptId":"math_probability_certain_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Certain Events"}', 0),
  (880, 262, 'A coin is tossed once. What is the probability of getting either Head or Tail?', 'text', 1, 'These are the only two possible outcomes.', '{"why":"A coin must show either Head or Tail when tossed.","sol":"Step 1: The probability space is {H, T}.\nStep 2: Both possible outcomes satisfy the event.\nStep 3: Therefore there are 2 favourable outcomes out of 2.\nStep 4: P(event) = 2/2 = 1.","steps":["Step 1: The probability space is {H, T}.","Step 2: Both possible outcomes satisfy the event.","Step 3: Therefore there are 2 favourable outcomes out of 2.","Step 4: P(event) = 2/2 = 1."],"options":[],"conceptId":"math_probability_certain_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Certain Events"}', 1),
  (881, 262, 'Cards labelled 2, 4 and 6 are placed in a bag. One card is selected. Find the probability of selecting an even number.', 'text', 1, 'Check each card.', '{"why":"Every available card contains an even number.","sol":"Step 1: The possible outcomes are 2, 4 and 6.\nStep 2: All three numbers are even.\nStep 3: Therefore there are 3 favourable outcomes out of 3.\nStep 4: P(even) = 3/3 = 1.","steps":["Step 1: The possible outcomes are 2, 4 and 6.","Step 2: All three numbers are even.","Step 3: Therefore there are 3 favourable outcomes out of 3.","Step 4: P(even) = 3/3 = 1."],"options":[],"conceptId":"math_probability_certain_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Certain Events"}', 2),
  (882, 263, 'Which of the following can be a probability: 0, 0.4, 1 or 1.3?', 'text', 1, 'A probability must lie from 0 to 1 inclusive.', '{"why":"Valid probabilities satisfy 0 ≤ P(E) ≤ 1.","sol":"Step 1: 0 is allowed because an impossible event has probability 0.\nStep 2: 0.4 is between 0 and 1.\nStep 3: 1 is allowed because a certain event has probability 1.\nStep 4: 1.3 is greater than 1 and therefore cannot be a probability.","steps":["Step 1: 0 is allowed because an impossible event has probability 0.","Step 2: 0.4 is between 0 and 1.","Step 3: 1 is allowed because a certain event has probability 1.","Step 4: 1.3 is greater than 1 and therefore cannot be a probability."],"options":[],"conceptId":"math_probability_probability_between_0_and_1","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Probability Between 0 and 1"}', 0),
  (883, 263, 'Can 1.2 be the probability of an event? Explain.', 'text', 1, 'Compare 1.2 with the upper limit of probability.', '{"why":"A probability cannot be greater than 1.","sol":"Step 1: The greatest possible probability is 1.\nStep 2: 1.2 is greater than 1.\nStep 3: Therefore 1.2 cannot represent a probability.","steps":["Step 1: The greatest possible probability is 1.","Step 2: 1.2 is greater than 1.","Step 3: Therefore 1.2 cannot represent a probability."],"options":[],"conceptId":"math_probability_probability_between_0_and_1","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Probability Between 0 and 1"}', 1),
  (884, 263, 'Can -0.3 be the probability of an event? Explain.', 'text', 1, 'Compare -0.3 with the lower limit of probability.', '{"why":"A probability cannot be negative.","sol":"Step 1: The smallest possible probability is 0.\nStep 2: -0.3 is less than 0.\nStep 3: Therefore -0.3 cannot represent a probability.","steps":["Step 1: The smallest possible probability is 0.","Step 2: -0.3 is less than 0.","Step 3: Therefore -0.3 cannot represent a probability."],"options":[],"conceptId":"math_probability_probability_between_0_and_1","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Probability Between 0 and 1"}', 2),
  (885, 264, 'What does a probability of 0 mean?', 'text', 1, 'Think about whether the event can happen.', '{"why":"Probability 0 represents an event that cannot occur.","sol":"Step 1: A probability of 0 is the lowest possible probability.\nStep 2: An event with probability 0 cannot happen.\nStep 3: Therefore the event is impossible.","steps":["Step 1: A probability of 0 is the lowest possible probability.","Step 2: An event with probability 0 cannot happen.","Step 3: Therefore the event is impossible."],"options":[],"conceptId":"math_probability_interpreting_probability_values","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Interpreting Probability Values"}', 0),
  (886, 264, 'What does a probability of 1 mean?', 'text', 1, 'Think about the highest possible probability.', '{"why":"Probability 1 represents an event that must occur.","sol":"Step 1: A probability of 1 is the highest possible probability.\nStep 2: An event with probability 1 must happen.\nStep 3: Therefore the event is certain.","steps":["Step 1: A probability of 1 is the highest possible probability.","Step 2: An event with probability 1 must happen.","Step 3: Therefore the event is certain."],"options":[],"conceptId":"math_probability_interpreting_probability_values","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Interpreting Probability Values"}', 1),
  (887, 264, 'Which event is more certain: Event A with probability 0.2 or Event B with probability 0.8?', 'text', 1, 'Compare the two values.', '{"why":"A larger probability represents a greater likelihood of the event occurring.","sol":"Step 1: Event A has probability 0.2.\nStep 2: Event B has probability 0.8.\nStep 3: 0.8 is closer to 1 than 0.2.\nStep 4: Therefore Event B is more likely to occur.","steps":["Step 1: Event A has probability 0.2.","Step 2: Event B has probability 0.8.","Step 3: 0.8 is closer to 1 than 0.2.","Step 4: Therefore Event B is more likely to occur."],"options":[],"conceptId":"math_probability_interpreting_probability_values","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Interpreting Probability Values"}', 2),
  (888, 265, 'Is 0.65 a valid probability?', 'text', 1, 'Check whether 0.65 lies between 0 and 1.', '{"why":"0.65 lies within the probability range from 0 to 1.","sol":"Step 1: 0.65 is greater than 0.\nStep 2: 0.65 is less than 1.\nStep 3: Therefore 0 ≤ 0.65 ≤ 1.\nStep 4: So 0.65 is a valid probability.","steps":["Step 1: 0.65 is greater than 0.","Step 2: 0.65 is less than 1.","Step 3: Therefore 0 ≤ 0.65 ≤ 1.","Step 4: So 0.65 is a valid probability."],"options":[],"conceptId":"math_probability_checking_whether_a_probability_is_valid","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Checking Whether a Probability Is Valid"}', 0),
  (889, 265, 'Is -1/3 a valid probability?', 'text', 1, 'A probability cannot be less than 0.', '{"why":"Probabilities cannot be negative.","sol":"Step 1: -1/3 is less than 0.\nStep 2: Therefore it violates the lower limit.\nStep 3: So -1/3 cannot be a probability.","steps":["Step 1: -1/3 is less than 0.","Step 2: Therefore it violates the lower limit.","Step 3: So -1/3 cannot be a probability."],"options":[],"conceptId":"math_probability_checking_whether_a_probability_is_valid","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Checking Whether a Probability Is Valid"}', 1),
  (890, 265, 'Is 7/6 a valid probability?', 'text', 1, 'Compare 7/6 with 1.', '{"why":"The value is greater than the maximum possible probability, 1.","sol":"Step 1: 7/6 is greater than 6/6.\nStep 2: 6/6 = 1.\nStep 3: Therefore 7/6 > 1.\nStep 4: A probability cannot be greater than 1.\nStep 5: So 7/6 is not a valid probability.","steps":["Step 1: 7/6 is greater than 6/6.","Step 2: 6/6 = 1.","Step 3: Therefore 7/6 > 1.","Step 4: A probability cannot be greater than 1.","Step 5: So 7/6 is not a valid probability."],"options":[],"conceptId":"math_probability_checking_whether_a_probability_is_valid","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Checking Whether a Probability Is Valid"}', 2),
  (891, 266, 'A coin is tossed once. Are getting Head and getting Tail mutually exclusive?', 'text', 1, 'Can one toss produce both results at the same time?', '{"why":"Head and Tail cannot occur together in one coin toss.","sol":"Step 1: One coin toss produces one result.\nStep 2: The result can be Head or Tail.\nStep 3: It cannot be Head and Tail at the same time.\nStep 4: Therefore the events are mutually exclusive.","steps":["Step 1: One coin toss produces one result.","Step 2: The result can be Head or Tail.","Step 3: It cannot be Head and Tail at the same time.","Step 4: Therefore the events are mutually exclusive."],"options":[],"conceptId":"math_probability_meaning_of_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Meaning of Mutually Exclusive Events"}', 0),
  (892, 266, 'A die is rolled once. Are getting 2 and getting 6 mutually exclusive?', 'text', 1, 'Can one roll have both 2 and 6 as its result?', '{"why":"A single die roll cannot produce two different numbers.","sol":"Step 1: One die roll produces one number.\nStep 2: The result cannot be both 2 and 6.\nStep 3: Therefore the two events cannot occur together.\nStep 4: They are mutually exclusive.","steps":["Step 1: One die roll produces one number.","Step 2: The result cannot be both 2 and 6.","Step 3: Therefore the two events cannot occur together.","Step 4: They are mutually exclusive."],"options":[],"conceptId":"math_probability_meaning_of_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Meaning of Mutually Exclusive Events"}', 1),
  (893, 266, 'One card is selected. Are selecting a red card and selecting a blue card mutually exclusive?', 'text', 1, 'Only one card is selected.', '{"why":"One selected card cannot belong to two different colours at the same time.","sol":"Step 1: Only one card is selected.\nStep 2: That card cannot be red and blue at the same time.\nStep 3: Therefore the two events cannot happen together.\nStep 4: They are mutually exclusive.","steps":["Step 1: Only one card is selected.","Step 2: That card cannot be red and blue at the same time.","Step 3: Therefore the two events cannot happen together.","Step 4: They are mutually exclusive."],"options":[],"conceptId":"math_probability_meaning_of_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Meaning of Mutually Exclusive Events"}', 2),
  (894, 267, 'A die is rolled once. Event A is getting {1, 2, 3}. Event B is getting {4, 5, 6}. Are they mutually exclusive?', 'text', 1, 'Look for a number appearing in both sets.', '{"why":"The two events have no outcome in common.","sol":"Step 1: Event A contains 1, 2 and 3.\nStep 2: Event B contains 4, 5 and 6.\nStep 3: There is no common outcome.\nStep 4: Therefore the events are mutually exclusive.","steps":["Step 1: Event A contains 1, 2 and 3.","Step 2: Event B contains 4, 5 and 6.","Step 3: There is no common outcome.","Step 4: Therefore the events are mutually exclusive."],"options":[],"conceptId":"math_probability_identifying_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Identifying Mutually Exclusive Events"}', 0),
  (895, 267, 'A die is rolled once. Event A is getting {2, 4, 6}. Event B is getting {1, 2, 3}. Are they mutually exclusive?', 'text', 1, 'Check whether the two sets have a common number.', '{"why":"The events share the outcome 2.","sol":"Step 1: Event A contains 2, 4 and 6.\nStep 2: Event B contains 1, 2 and 3.\nStep 3: The number 2 appears in both events.\nStep 4: Therefore both events can occur when the die shows 2.\nStep 5: They are not mutually exclusive.","steps":["Step 1: Event A contains 2, 4 and 6.","Step 2: Event B contains 1, 2 and 3.","Step 3: The number 2 appears in both events.","Step 4: Therefore both events can occur when the die shows 2.","Step 5: They are not mutually exclusive."],"options":[],"conceptId":"math_probability_identifying_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Identifying Mutually Exclusive Events"}', 1),
  (896, 267, 'A die is rolled once. Event A is getting a number less than 3. Event B is getting a number greater than 4. Are they mutually exclusive?', 'text', 1, 'Write the outcomes belonging to each event.', '{"why":"No die result can be both less than 3 and greater than 4.","sol":"Step 1: Numbers less than 3 are {1, 2}.\nStep 2: Numbers greater than 4 are {5, 6}.\nStep 3: There is no common outcome.\nStep 4: Therefore the events are mutually exclusive.","steps":["Step 1: Numbers less than 3 are {1, 2}.","Step 2: Numbers greater than 4 are {5, 6}.","Step 3: There is no common outcome.","Step 4: Therefore the events are mutually exclusive."],"options":[],"conceptId":"math_probability_identifying_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Identifying Mutually Exclusive Events"}', 2),
  (897, 268, 'Given S = {1, 2, 3, 4, 5, 6}, A = {1, 2} and B = {3, 4}, determine whether A and B are mutually exclusive.', 'text', 1, 'Look for a common outcome.', '{"why":"The two events do not share any possible outcome.","sol":"Step 1: Event A contains 1 and 2.\nStep 2: Event B contains 3 and 4.\nStep 3: There is no outcome common to both events.\nStep 4: Therefore A and B are mutually exclusive.","steps":["Step 1: Event A contains 1 and 2.","Step 2: Event B contains 3 and 4.","Step 3: There is no outcome common to both events.","Step 4: Therefore A and B are mutually exclusive."],"options":[],"conceptId":"math_probability_mutually_exclusive_events_from_a_probability_space","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Mutually Exclusive Events from a Probability Space"}', 0),
  (898, 268, 'Given S = {1, 2, 3, 4, 5, 6}, A = {2, 4} and B = {1, 3, 5}, determine whether A and B are mutually exclusive.', 'text', 1, 'Compare the two sets.', '{"why":"The events have no common outcome.","sol":"Step 1: A contains 2 and 4.\nStep 2: B contains 1, 3 and 5.\nStep 3: There is no number common to both.\nStep 4: Therefore A and B are mutually exclusive.","steps":["Step 1: A contains 2 and 4.","Step 2: B contains 1, 3 and 5.","Step 3: There is no number common to both.","Step 4: Therefore A and B are mutually exclusive."],"options":[],"conceptId":"math_probability_mutually_exclusive_events_from_a_probability_space","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Mutually Exclusive Events from a Probability Space"}', 1),
  (899, 268, 'Given S = {1, 2, 3, 4, 5, 6}, A = {2, 3} and B = {3, 5}, determine whether A and B are mutually exclusive.', 'text', 1, 'Check the number 3.', '{"why":"The events share the outcome 3.","sol":"Step 1: Event A contains 2 and 3.\nStep 2: Event B contains 3 and 5.\nStep 3: The outcome 3 belongs to both events.\nStep 4: Therefore both events can occur when the outcome is 3.\nStep 5: They are not mutually exclusive.","steps":["Step 1: Event A contains 2 and 3.","Step 2: Event B contains 3 and 5.","Step 3: The outcome 3 belongs to both events.","Step 4: Therefore both events can occur when the outcome is 3.","Step 5: They are not mutually exclusive."],"options":[],"conceptId":"math_probability_mutually_exclusive_events_from_a_probability_space","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Mutually Exclusive Events from a Probability Space"}', 2),
  (900, 269, 'A die is rolled once. A is getting an odd number and B is getting an even number. Are A and B mutually exclusive?', 'text', 1, 'Can one number be both odd and even?', '{"why":"A number cannot be both odd and even.","sol":"Step 1: The possible results are 1, 2, 3, 4, 5 and 6.\nStep 2: Odd results are 1, 3 and 5.\nStep 3: Even results are 2, 4 and 6.\nStep 4: No result is both odd and even.\nStep 5: Therefore A and B are mutually exclusive.","steps":["Step 1: The possible results are 1, 2, 3, 4, 5 and 6.","Step 2: Odd results are 1, 3 and 5.","Step 3: Even results are 2, 4 and 6.","Step 4: No result is both odd and even.","Step 5: Therefore A and B are mutually exclusive."],"options":[],"conceptId":"math_probability_mutually_exclusive_events_in_an_experiment","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Mutually Exclusive Events in an Experiment"}', 0),
  (901, 269, 'A die is rolled once. A is getting 1 and B is getting an even number. Are A and B mutually exclusive?', 'text', 1, 'Is 1 an even number?', '{"why":"Getting 1 cannot occur at the same time as getting an even number.","sol":"Step 1: Event A happens only when the result is 1.\nStep 2: Event B happens when the result is 2, 4 or 6.\nStep 3: The result 1 is not even.\nStep 4: Therefore no result can make both events happen.\nStep 5: They are mutually exclusive.","steps":["Step 1: Event A happens only when the result is 1.","Step 2: Event B happens when the result is 2, 4 or 6.","Step 3: The result 1 is not even.","Step 4: Therefore no result can make both events happen.","Step 5: They are mutually exclusive."],"options":[],"conceptId":"math_probability_mutually_exclusive_events_in_an_experiment","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Mutually Exclusive Events in an Experiment"}', 1),
  (902, 269, 'A die is rolled once. A is getting an even number and B is getting a number greater than 3. Are A and B mutually exclusive?', 'text', 1, 'Try the outcome 4.', '{"why":"The outcome 4 belongs to both events.","sol":"Step 1: 4 is an even number.\nStep 2: 4 is also greater than 3.\nStep 3: Therefore outcome 4 makes both A and B happen.\nStep 4: So the events can happen together.\nStep 5: They are not mutually exclusive.","steps":["Step 1: 4 is an even number.","Step 2: 4 is also greater than 3.","Step 3: Therefore outcome 4 makes both A and B happen.","Step 4: So the events can happen together.","Step 5: They are not mutually exclusive."],"options":[],"conceptId":"math_probability_mutually_exclusive_events_in_an_experiment","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Mutually Exclusive Events in an Experiment"}', 2),
  (903, 270, 'A = {1, 2} and B = {4, 5}. Are the events mutually exclusive?', 'text', 1, 'Check whether A and B have a common outcome.', '{"why":"The two events cannot occur from the same outcome.","sol":"Step 1: A contains 1 and 2.\nStep 2: B contains 4 and 5.\nStep 3: There is no common outcome.\nStep 4: Therefore the events are mutually exclusive.","steps":["Step 1: A contains 1 and 2.","Step 2: B contains 4 and 5.","Step 3: There is no common outcome.","Step 4: Therefore the events are mutually exclusive."],"options":[],"conceptId":"math_probability_testing_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Testing Mutually Exclusive Events"}', 0),
  (904, 270, 'A = {2, 3, 4} and B = {4, 5, 6}. Are the events mutually exclusive?', 'text', 1, 'Look carefully at both sets.', '{"why":"The events share outcome 4.","sol":"Step 1: A contains 2, 3 and 4.\nStep 2: B contains 4, 5 and 6.\nStep 3: The outcome 4 appears in both sets.\nStep 4: Therefore both events can occur for the same outcome.\nStep 5: They are not mutually exclusive.","steps":["Step 1: A contains 2, 3 and 4.","Step 2: B contains 4, 5 and 6.","Step 3: The outcome 4 appears in both sets.","Step 4: Therefore both events can occur for the same outcome.","Step 5: They are not mutually exclusive."],"options":[],"conceptId":"math_probability_testing_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Testing Mutually Exclusive Events"}', 1),
  (905, 270, 'A = {1, 3, 5} and B = {2, 4, 6}. Are the events mutually exclusive?', 'text', 1, 'Compare every outcome in A with the outcomes in B.', '{"why":"The two events have no common outcome.","sol":"Step 1: A contains 1, 3 and 5.\nStep 2: B contains 2, 4 and 6.\nStep 3: No outcome appears in both sets.\nStep 4: Therefore the events are mutually exclusive.","steps":["Step 1: A contains 1, 3 and 5.","Step 2: B contains 2, 4 and 6.","Step 3: No outcome appears in both sets.","Step 4: Therefore the events are mutually exclusive."],"options":[],"conceptId":"math_probability_testing_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Testing Mutually Exclusive Events"}', 2),
  (906, 271, 'A fair coin is tossed twice. If the first toss is Head, does this change the probability of Head on the second toss?', 'text', 1, 'The first toss does not change the coin.', '{"why":"The two coin tosses are independent.","sol":"Step 1: A fair coin has P(Head) = 1/2.\nStep 2: The first toss produces Head.\nStep 3: The second toss is still a toss of the same fair coin.\nStep 4: Therefore P(Head on the second toss) remains 1/2.\nStep 5: The first result did not affect the second probability.","steps":["Step 1: A fair coin has P(Head) = 1/2.","Step 2: The first toss produces Head.","Step 3: The second toss is still a toss of the same fair coin.","Step 4: Therefore P(Head on the second toss) remains 1/2.","Step 5: The first result did not affect the second probability."],"options":[],"conceptId":"math_probability_meaning_of_independent_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Meaning of Independent Events"}', 0),
  (907, 271, 'A die is rolled twice. The first roll is 4. Does this change the probability of getting 6 on the second roll?', 'text', 1, 'Ask whether the first roll changes the die.', '{"why":"The first die roll does not affect the second roll.","sol":"Step 1: A standard die has six possible results.\nStep 2: The first roll gives 4.\nStep 3: The die still has all six faces for the second roll.\nStep 4: Therefore P(6 on the second roll) is still 1/6.","steps":["Step 1: A standard die has six possible results.","Step 2: The first roll gives 4.","Step 3: The die still has all six faces for the second roll.","Step 4: Therefore P(6 on the second roll) is still 1/6."],"options":[],"conceptId":"math_probability_meaning_of_independent_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Meaning of Independent Events"}', 1),
  (908, 271, 'A coin is tossed and then a die is rolled. Does getting Head on the coin change the probability of getting 5 on the die?', 'text', 1, 'Does the coin result change the die?', '{"why":"The two experiments do not affect each other''s probabilities.","sol":"Step 1: Getting Head is an outcome of the coin experiment.\nStep 2: The die still has six possible outcomes.\nStep 3: Therefore the probability of 5 on the die remains 1/6.\nStep 4: The coin result does not affect the die.","steps":["Step 1: Getting Head is an outcome of the coin experiment.","Step 2: The die still has six possible outcomes.","Step 3: Therefore the probability of 5 on the die remains 1/6.","Step 4: The coin result does not affect the die."],"options":[],"conceptId":"math_probability_meaning_of_independent_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Meaning of Independent Events"}', 2),
  (909, 272, 'A coin is tossed twice. Are getting Head on the first toss and Head on the second toss independent events?', 'text', 1, 'Does the first toss change the second toss?', '{"why":"The result of the first toss does not affect the second toss.","sol":"Step 1: The first toss does not change the coin.\nStep 2: The second toss still has P(Head) = 1/2.\nStep 3: Therefore knowing the first result does not change the second probability.\nStep 4: The events are independent.","steps":["Step 1: The first toss does not change the coin.","Step 2: The second toss still has P(Head) = 1/2.","Step 3: Therefore knowing the first result does not change the second probability.","Step 4: The events are independent."],"options":[],"conceptId":"math_probability_recognising_independent_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Recognising Independent Events"}', 0),
  (910, 272, 'A die is rolled twice. Are getting 3 first and 6 second independent events?', 'text', 1, 'Does rolling 3 remove anything from the die?', '{"why":"One die roll does not affect a later die roll.","sol":"Step 1: The first roll gives 3.\nStep 2: The die still has all six faces for the second roll.\nStep 3: The probability of 6 remains 1/6.\nStep 4: Therefore the events are independent.","steps":["Step 1: The first roll gives 3.","Step 2: The die still has all six faces for the second roll.","Step 3: The probability of 6 remains 1/6.","Step 4: Therefore the events are independent."],"options":[],"conceptId":"math_probability_recognising_independent_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Recognising Independent Events"}', 1),
  (911, 272, 'A bag contains 3 red balls and 2 blue balls. One ball is selected and kept outside the bag. Is the colour of the second selection independent of the first selection?', 'text', 1, 'Does removing the first ball change the contents of the bag?', '{"why":"Removing the first ball changes the composition of the bag.","sol":"Step 1: There are initially 5 balls.\nStep 2: The first ball is not returned.\nStep 3: Therefore only 4 balls remain.\nStep 4: The numbers of red and blue balls remaining depend on the first colour selected.\nStep 5: Therefore the second probability can change.\nStep 6: The selections are not independent.","steps":["Step 1: There are initially 5 balls.","Step 2: The first ball is not returned.","Step 3: Therefore only 4 balls remain.","Step 4: The numbers of red and blue balls remaining depend on the first colour selected.","Step 5: Therefore the second probability can change.","Step 6: The selections are not independent."],"options":[],"conceptId":"math_probability_recognising_independent_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Recognising Independent Events"}', 2),
  (912, 273, 'A bag contains 4 red balls and 1 blue ball. A ball is selected, replaced, and another ball is selected. What is the probability of red on the second selection?', 'text', 1, 'The first ball is returned before the second selection.', '{"why":"Replacement restores the original contents of the bag.","sol":"Step 1: There are 4 red and 1 blue ball initially.\nStep 2: The first ball is replaced.\nStep 3: Therefore the bag still has 4 red and 1 blue ball.\nStep 4: Total balls = 4 + 1 = 5.\nStep 5: P(Red on second selection) = 4/5.","steps":["Step 1: There are 4 red and 1 blue ball initially.","Step 2: The first ball is replaced.","Step 3: Therefore the bag still has 4 red and 1 blue ball.","Step 4: Total balls = 4 + 1 = 5.","Step 5: P(Red on second selection) = 4/5."],"options":[],"conceptId":"math_probability_independence_with_replacement","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Independence With Replacement"}', 0),
  (913, 273, 'A bag contains 2 green balls and 3 yellow balls. A green ball is selected and replaced. What is the probability of yellow on the second selection?', 'text', 1, 'The green ball is returned before the second selection.', '{"why":"Replacing the first ball leaves the second selection with the original probabilities.","sol":"Step 1: Initially there are 2 green and 3 yellow balls.\nStep 2: The green ball is replaced.\nStep 3: The bag therefore still contains 2 green and 3 yellow balls.\nStep 4: Total balls = 5.\nStep 5: P(Yellow) = 3/5.","steps":["Step 1: Initially there are 2 green and 3 yellow balls.","Step 2: The green ball is replaced.","Step 3: The bag therefore still contains 2 green and 3 yellow balls.","Step 4: Total balls = 5.","Step 5: P(Yellow) = 3/5."],"options":[],"conceptId":"math_probability_independence_with_replacement","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Independence With Replacement"}', 1),
  (914, 273, 'A bag contains 5 red balls and 5 blue balls. A ball is selected and replaced. Does the first selection change the probability of red on the second selection?', 'text', 1, 'Compare the bag before and after replacement.', '{"why":"Replacement restores exactly the original collection.","sol":"Step 1: Initially there are 5 red and 5 blue balls.\nStep 2: The selected ball is returned.\nStep 3: The bag again contains 5 red and 5 blue balls.\nStep 4: Therefore P(Red on the second selection) remains 5/10 = 1/2.\nStep 5: The first selection does not change the second probability.","steps":["Step 1: Initially there are 5 red and 5 blue balls.","Step 2: The selected ball is returned.","Step 3: The bag again contains 5 red and 5 blue balls.","Step 4: Therefore P(Red on the second selection) remains 5/10 = 1/2.","Step 5: The first selection does not change the second probability."],"options":[],"conceptId":"math_probability_independence_with_replacement","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Independence With Replacement"}', 2),
  (915, 274, 'A bag contains 4 red balls and 2 blue balls. A red ball is selected and not replaced. What is the probability of red on the second selection?', 'text', 1, 'Remove one red ball before calculating the second probability.', '{"why":"Removing the first red ball changes both the number of red balls and the total number of balls.","sol":"Step 1: Initially there are 4 red and 2 blue balls.\nStep 2: One red ball is removed.\nStep 3: Red balls remaining = 4 - 1 = 3.\nStep 4: Total balls remaining = 6 - 1 = 5.\nStep 5: Therefore P(Red on second selection) = 3/5.","steps":["Step 1: Initially there are 4 red and 2 blue balls.","Step 2: One red ball is removed.","Step 3: Red balls remaining = 4 - 1 = 3.","Step 4: Total balls remaining = 6 - 1 = 5.","Step 5: Therefore P(Red on second selection) = 3/5."],"options":[],"conceptId":"math_probability_independence_without_replacement","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Independence Without Replacement"}', 0),
  (916, 274, 'A bag contains 3 green balls and 2 yellow balls. A yellow ball is selected and not replaced. What is the probability of green on the second selection?', 'text', 1, 'Removing a yellow ball leaves all the green balls in the bag.', '{"why":"The total number of balls changes after the first ball is removed.","sol":"Step 1: Initially there are 3 green and 2 yellow balls.\nStep 2: One yellow ball is removed.\nStep 3: Green balls remaining = 3.\nStep 4: Total balls remaining = 5 - 1 = 4.\nStep 5: Therefore P(Green on second selection) = 3/4.","steps":["Step 1: Initially there are 3 green and 2 yellow balls.","Step 2: One yellow ball is removed.","Step 3: Green balls remaining = 3.","Step 4: Total balls remaining = 5 - 1 = 4.","Step 5: Therefore P(Green on second selection) = 3/4."],"options":[],"conceptId":"math_probability_independence_without_replacement","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Independence Without Replacement"}', 1),
  (917, 274, 'A bag contains 5 red and 1 blue ball. A red ball is selected and not replaced. Was the probability of selecting red changed?', 'text', 1, 'Compare the original and second-selection probabilities.', '{"why":"Removing a red ball changes the composition of the bag.","sol":"Step 1: Initially P(Red) = 5/6.\nStep 2: After one red is removed, 4 red balls remain.\nStep 3: There are now 5 balls in total.\nStep 4: The second probability is 4/5.\nStep 5: Since 5/6 is different from 4/5, the probability changed.","steps":["Step 1: Initially P(Red) = 5/6.","Step 2: After one red is removed, 4 red balls remain.","Step 3: There are now 5 balls in total.","Step 4: The second probability is 4/5.","Step 5: Since 5/6 is different from 4/5, the probability changed."],"options":[],"conceptId":"math_probability_independence_without_replacement","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Independence Without Replacement"}', 2),
  (918, 275, 'A fair die is rolled twice. Are the two rolls independent or dependent?', 'text', 1, 'Does the first roll change the die?', '{"why":"The first roll does not affect the second roll.","sol":"Step 1: The first roll produces one number.\nStep 2: Nothing is removed from or added to the die.\nStep 3: The die still has the same six possible outcomes.\nStep 4: Therefore the second probability is unchanged.\nStep 5: The rolls are independent.","steps":["Step 1: The first roll produces one number.","Step 2: Nothing is removed from or added to the die.","Step 3: The die still has the same six possible outcomes.","Step 4: Therefore the second probability is unchanged.","Step 5: The rolls are independent."],"options":[],"conceptId":"math_probability_distinguishing_independent_and_dependent_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Distinguishing Independent and Dependent Events"}', 0),
  (919, 275, 'A ball is selected from a bag and kept outside. A second ball is selected. Are the two selections independent or dependent?', 'text', 1, 'Does removing the first ball change the bag?', '{"why":"The first selection changes the contents available for the second selection.","sol":"Step 1: The first ball is removed from the bag.\nStep 2: The contents of the bag therefore change.\nStep 3: The probability of the second selection can change.\nStep 4: Therefore the selections are dependent.","steps":["Step 1: The first ball is removed from the bag.","Step 2: The contents of the bag therefore change.","Step 3: The probability of the second selection can change.","Step 4: Therefore the selections are dependent."],"options":[],"conceptId":"math_probability_distinguishing_independent_and_dependent_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Distinguishing Independent and Dependent Events"}', 1),
  (920, 275, 'A ball is selected from a bag, returned to the bag, and the bag is mixed. A second ball is selected. Are the selections independent or dependent?', 'text', 1, 'Compare the contents before the first and second selections.', '{"why":"Replacement restores the original conditions before the second selection.","sol":"Step 1: The first ball is selected.\nStep 2: It is returned to the bag.\nStep 3: The original collection is restored.\nStep 4: Therefore the probabilities for the second selection remain unchanged.\nStep 5: The selections are independent.","steps":["Step 1: The first ball is selected.","Step 2: It is returned to the bag.","Step 3: The original collection is restored.","Step 4: Therefore the probabilities for the second selection remain unchanged.","Step 5: The selections are independent."],"options":[],"conceptId":"math_probability_distinguishing_independent_and_dependent_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Distinguishing Independent and Dependent Events"}', 2),
  (921, 276, 'A fair die is rolled. Find the probability of getting 1 or 4.', 'text', 1, 'Getting 1 and getting 4 are mutually exclusive.', '{"why":"There are two separate favourable outcomes, 1 and 4, out of six.","sol":"Step 1: P(1) = 1/6.\nStep 2: P(4) = 1/6.\nStep 3: The two events are mutually exclusive.\nStep 4: Therefore P(1 or 4) = 1/6 + 1/6.\nStep 5: P(1 or 4) = 2/6 = 1/3.","steps":["Step 1: P(1) = 1/6.","Step 2: P(4) = 1/6.","Step 3: The two events are mutually exclusive.","Step 4: Therefore P(1 or 4) = 1/6 + 1/6.","Step 5: P(1 or 4) = 2/6 = 1/3."],"options":[],"conceptId":"math_probability_adding_probabilities_of_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Adding Probabilities of Mutually Exclusive Events"}', 0),
  (922, 276, 'A fair die is rolled. Find the probability of getting 3 or 6.', 'text', 1, 'Find each probability, then add them.', '{"why":"Getting 3 and getting 6 are mutually exclusive outcomes.","sol":"Step 1: P(3) = 1/6.\nStep 2: P(6) = 1/6.\nStep 3: The events cannot occur together in one roll.\nStep 4: Therefore P(3 or 6) = 1/6 + 1/6.\nStep 5: P(3 or 6) = 2/6 = 1/3.","steps":["Step 1: P(3) = 1/6.","Step 2: P(6) = 1/6.","Step 3: The events cannot occur together in one roll.","Step 4: Therefore P(3 or 6) = 1/6 + 1/6.","Step 5: P(3 or 6) = 2/6 = 1/3."],"options":[],"conceptId":"math_probability_adding_probabilities_of_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Adding Probabilities of Mutually Exclusive Events"}', 1),
  (923, 276, 'A fair die is rolled. Find the probability of getting an odd number or an even number.', 'text', 1, 'Odd and even outcomes together cover all six die results.', '{"why":"Every possible die result is either odd or even.","sol":"Step 1: P(Odd) = 3/6 = 1/2.\nStep 2: P(Even) = 3/6 = 1/2.\nStep 3: Odd and even are mutually exclusive.\nStep 4: Therefore P(Odd or Even) = 1/2 + 1/2.\nStep 5: P(Odd or Even) = 1.","steps":["Step 1: P(Odd) = 3/6 = 1/2.","Step 2: P(Even) = 3/6 = 1/2.","Step 3: Odd and even are mutually exclusive.","Step 4: Therefore P(Odd or Even) = 1/2 + 1/2.","Step 5: P(Odd or Even) = 1."],"options":[],"conceptId":"math_probability_adding_probabilities_of_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Adding Probabilities of Mutually Exclusive Events"}', 2),
  (924, 277, 'A fair die is rolled. Event A is {1, 2}. Event B is {5}. Find P(A or B).', 'text', 1, 'Count the favourable outcomes in both events.', '{"why":"There are three favourable outcomes: 1, 2 and 5.","sol":"Step 1: A has two favourable outcomes: 1 and 2.\nStep 2: B has one favourable outcome: 5.\nStep 3: The events are mutually exclusive.\nStep 4: Therefore P(A) = 2/6 and P(B) = 1/6.\nStep 5: P(A or B) = 2/6 + 1/6.\nStep 6: P(A or B) = 3/6 = 1/2.","steps":["Step 1: A has two favourable outcomes: 1 and 2.","Step 2: B has one favourable outcome: 5.","Step 3: The events are mutually exclusive.","Step 4: Therefore P(A) = 2/6 and P(B) = 1/6.","Step 5: P(A or B) = 2/6 + 1/6.","Step 6: P(A or B) = 3/6 = 1/2."],"options":[],"conceptId":"math_probability_the_addition_law_from_a_probability_space","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"The Addition Law from a Probability Space"}', 0),
  (925, 277, 'A fair die is rolled. Event A is {1, 3, 5}. Event B is {2}. Find P(A or B).', 'text', 1, 'The two events have no common outcome.', '{"why":"The favourable outcomes are 1, 3, 5 and 2, giving four out of six.","sol":"Step 1: A has 3 favourable outcomes.\nStep 2: Therefore P(A) = 3/6 = 1/2.\nStep 3: B has 1 favourable outcome.\nStep 4: Therefore P(B) = 1/6.\nStep 5: P(A or B) = 1/2 + 1/6.\nStep 6: 1/2 = 3/6.\nStep 7: Therefore P(A or B) = 3/6 + 1/6 = 4/6 = 2/3.","steps":["Step 1: A has 3 favourable outcomes.","Step 2: Therefore P(A) = 3/6 = 1/2.","Step 3: B has 1 favourable outcome.","Step 4: Therefore P(B) = 1/6.","Step 5: P(A or B) = 1/2 + 1/6.","Step 6: 1/2 = 3/6.","Step 7: Therefore P(A or B) = 3/6 + 1/6 = 4/6 = 2/3."],"options":[],"conceptId":"math_probability_the_addition_law_from_a_probability_space","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"The Addition Law from a Probability Space"}', 1),
  (926, 277, 'A fair die is rolled. Event A is {1, 2, 3}. Event B is {5, 6}. Find P(A or B).', 'text', 1, 'Add the probabilities because there is no overlap.', '{"why":"Five of the six possible die outcomes belong to A or B.","sol":"Step 1: P(A) = 3/6 = 1/2.\nStep 2: P(B) = 2/6 = 1/3.\nStep 3: A and B are mutually exclusive.\nStep 4: Therefore P(A or B) = 1/2 + 1/3.\nStep 5: 1/2 = 3/6 and 1/3 = 2/6.\nStep 6: Therefore P(A or B) = 5/6.","steps":["Step 1: P(A) = 3/6 = 1/2.","Step 2: P(B) = 2/6 = 1/3.","Step 3: A and B are mutually exclusive.","Step 4: Therefore P(A or B) = 1/2 + 1/3.","Step 5: 1/2 = 3/6 and 1/3 = 2/6.","Step 6: Therefore P(A or B) = 5/6."],"options":[],"conceptId":"math_probability_the_addition_law_from_a_probability_space","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"The Addition Law from a Probability Space"}', 2),
  (927, 278, 'A fair coin is tossed twice. Find the probability of getting Head on both tosses.', 'text', 1, 'The two tosses are independent.', '{"why":"Both independent events must occur, so their probabilities are multiplied.","sol":"Step 1: P(Head on first toss) = 1/2.\nStep 2: P(Head on second toss) = 1/2.\nStep 3: The tosses are independent.\nStep 4: Therefore P(H and H) = 1/2 × 1/2.\nStep 5: P(H and H) = 1/4.","steps":["Step 1: P(Head on first toss) = 1/2.","Step 2: P(Head on second toss) = 1/2.","Step 3: The tosses are independent.","Step 4: Therefore P(H and H) = 1/2 × 1/2.","Step 5: P(H and H) = 1/4."],"options":[],"conceptId":"math_probability_multiplying_probabilities_of_independent_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Multiplying Probabilities of Independent Events"}', 0),
  (928, 278, 'A fair die is rolled twice. Find the probability of getting 3 on both rolls.', 'text', 1, 'Each roll has probability 1/6 of giving 3.', '{"why":"The probability of each independent 3 must occur, so the probabilities are multiplied.","sol":"Step 1: P(3 on first roll) = 1/6.\nStep 2: P(3 on second roll) = 1/6.\nStep 3: The two rolls are independent.\nStep 4: Therefore P(3 and 3) = 1/6 × 1/6.\nStep 5: P(3 and 3) = 1/36.","steps":["Step 1: P(3 on first roll) = 1/6.","Step 2: P(3 on second roll) = 1/6.","Step 3: The two rolls are independent.","Step 4: Therefore P(3 and 3) = 1/6 × 1/6.","Step 5: P(3 and 3) = 1/36."],"options":[],"conceptId":"math_probability_multiplying_probabilities_of_independent_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Multiplying Probabilities of Independent Events"}', 1),
  (929, 278, 'A fair coin is tossed and a fair die is rolled. Find the probability of getting Tail and 2.', 'text', 1, 'Find each probability separately, then multiply.', '{"why":"The two independent events must both occur.","sol":"Step 1: P(Tail) = 1/2.\nStep 2: P(2) = 1/6.\nStep 3: The coin toss and die roll are independent.\nStep 4: Therefore P(Tail and 2) = 1/2 × 1/6.\nStep 5: P(Tail and 2) = 1/12.","steps":["Step 1: P(Tail) = 1/2.","Step 2: P(2) = 1/6.","Step 3: The coin toss and die roll are independent.","Step 4: Therefore P(Tail and 2) = 1/2 × 1/6.","Step 5: P(Tail and 2) = 1/12."],"options":[],"conceptId":"math_probability_multiplying_probabilities_of_independent_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Multiplying Probabilities of Independent Events"}', 2),
  (930, 279, 'A fair coin is tossed twice. Find the probability of getting Tail on both tosses.', 'text', 1, 'Each Tail has probability 1/2 and the tosses are independent.', '{"why":"Both independent Tail events must occur.","sol":"Step 1: P(Tail on first toss) = 1/2.\nStep 2: P(Tail on second toss) = 1/2.\nStep 3: The tosses are independent.\nStep 4: Therefore P(T and T) = 1/2 × 1/2.\nStep 5: P(T and T) = 1/4.","steps":["Step 1: P(Tail on first toss) = 1/2.","Step 2: P(Tail on second toss) = 1/2.","Step 3: The tosses are independent.","Step 4: Therefore P(T and T) = 1/2 × 1/2.","Step 5: P(T and T) = 1/4."],"options":[],"conceptId":"math_probability_multiplication_law_with_independent_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Multiplication Law with Independent Events"}', 0),
  (931, 279, 'A fair die is rolled twice. Find the probability of getting an odd number on both rolls.', 'text', 1, 'There are 3 odd numbers out of 6 on each roll.', '{"why":"The probability of an odd result is 1/2 on each independent roll.","sol":"Step 1: Odd outcomes are 1, 3 and 5.\nStep 2: Therefore P(Odd) = 3/6 = 1/2.\nStep 3: The same probability applies to the second roll.\nStep 4: The rolls are independent.\nStep 5: Therefore P(Odd and Odd) = 1/2 × 1/2 = 1/4.","steps":["Step 1: Odd outcomes are 1, 3 and 5.","Step 2: Therefore P(Odd) = 3/6 = 1/2.","Step 3: The same probability applies to the second roll.","Step 4: The rolls are independent.","Step 5: Therefore P(Odd and Odd) = 1/2 × 1/2 = 1/4."],"options":[],"conceptId":"math_probability_multiplication_law_with_independent_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Multiplication Law with Independent Events"}', 1),
  (932, 279, 'A fair coin is tossed and a fair die is rolled. Find the probability of Tail and an even number.', 'text', 1, 'P(Tail) = 1/2 and P(Even) = 3/6.', '{"why":"The independent probabilities are multiplied.","sol":"Step 1: P(Tail) = 1/2.\nStep 2: The even die outcomes are 2, 4 and 6.\nStep 3: Therefore P(Even) = 3/6 = 1/2.\nStep 4: The coin and die experiments are independent.\nStep 5: Therefore P(Tail and Even) = 1/2 × 1/2.\nStep 6: The answer is 1/4.","steps":["Step 1: P(Tail) = 1/2.","Step 2: The even die outcomes are 2, 4 and 6.","Step 3: Therefore P(Even) = 3/6 = 1/2.","Step 4: The coin and die experiments are independent.","Step 5: Therefore P(Tail and Even) = 1/2 × 1/2.","Step 6: The answer is 1/4."],"options":[],"conceptId":"math_probability_multiplication_law_with_independent_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Multiplication Law with Independent Events"}', 2),
  (933, 280, 'A fair die is rolled. Find the probability of getting 1 or 3. Should you add or multiply?', 'text', 1, 'Can 1 and 3 occur on the same roll?', '{"why":"The events are mutually exclusive.","sol":"Step 1: A single die roll gives one number.\nStep 2: It cannot give both 1 and 3.\nStep 3: Therefore the events are mutually exclusive.\nStep 4: For mutually exclusive events asking for ''or'', we add.\nStep 5: P(1 or 3) = 1/6 + 1/6 = 1/3.","steps":["Step 1: A single die roll gives one number.","Step 2: It cannot give both 1 and 3.","Step 3: Therefore the events are mutually exclusive.","Step 4: For mutually exclusive events asking for ''or'', we add.","Step 5: P(1 or 3) = 1/6 + 1/6 = 1/3."],"options":[],"conceptId":"math_probability_choosing_addition_or_multiplication","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Choosing Addition or Multiplication"}', 0),
  (934, 280, 'A fair coin is tossed twice. Find the probability of getting Head on both tosses. Should you add or multiply?', 'text', 1, 'Both events must happen, and the tosses are independent.', '{"why":"Both independent events must occur.","sol":"Step 1: We need Head on the first toss and Head on the second toss.\nStep 2: The two tosses are independent.\nStep 3: For independent events asking for both events, we multiply.\nStep 4: P(H and H) = 1/2 × 1/2 = 1/4.","steps":["Step 1: We need Head on the first toss and Head on the second toss.","Step 2: The two tosses are independent.","Step 3: For independent events asking for both events, we multiply.","Step 4: P(H and H) = 1/2 × 1/2 = 1/4."],"options":[],"conceptId":"math_probability_choosing_addition_or_multiplication","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Choosing Addition or Multiplication"}', 1),
  (935, 280, 'A fair die is rolled twice. Find the probability of getting 6 on both rolls. Should you add or multiply?', 'text', 1, 'Both rolls must produce 6.', '{"why":"The two independent events must both happen.","sol":"Step 1: P(6 on the first roll) = 1/6.\nStep 2: P(6 on the second roll) = 1/6.\nStep 3: The two rolls are independent.\nStep 4: Therefore we multiply.\nStep 5: P(6 and 6) = 1/6 × 1/6 = 1/36.","steps":["Step 1: P(6 on the first roll) = 1/6.","Step 2: P(6 on the second roll) = 1/6.","Step 3: The two rolls are independent.","Step 4: Therefore we multiply.","Step 5: P(6 and 6) = 1/6 × 1/6 = 1/36."],"options":[],"conceptId":"math_probability_choosing_addition_or_multiplication","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Choosing Addition or Multiplication"}', 2),
  (936, 281, 'A coin is tossed twice. How many complete paths are possible?', 'text', 1, 'List HH, HT, TH and TT.', '{"why":"A complete path contains the result of both tosses.","sol":"Step 1: The first toss has 2 possible results: H or T.\nStep 2: Each first result can be followed by H or T.\nStep 3: The complete paths are HH, HT, TH and TT.\nStep 4: Therefore there are 4 complete paths.","steps":["Step 1: The first toss has 2 possible results: H or T.","Step 2: Each first result can be followed by H or T.","Step 3: The complete paths are HH, HT, TH and TT.","Step 4: Therefore there are 4 complete paths."],"options":[],"conceptId":"math_probability_reading_a_probability_tree_diagram","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Reading a Probability Tree Diagram"}', 0),
  (937, 281, 'A die is rolled twice. How many complete paths are possible?', 'text', 1, 'There are 6 choices at each stage.', '{"why":"Every first-roll result can be paired with every second-roll result.","sol":"Step 1: The first roll has 6 possible results.\nStep 2: For each first result, the second roll has 6 possible results.\nStep 3: Number of complete paths = 6 × 6.\nStep 4: 6 × 6 = 36.","steps":["Step 1: The first roll has 6 possible results.","Step 2: For each first result, the second roll has 6 possible results.","Step 3: Number of complete paths = 6 × 6.","Step 4: 6 × 6 = 36."],"options":[],"conceptId":"math_probability_reading_a_probability_tree_diagram","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Reading a Probability Tree Diagram"}', 1),
  (938, 281, 'For two coin tosses, is HT a branch or a complete path?', 'text', 1, 'HT contains results from both stages.', '{"why":"A complete path contains an outcome from every stage.","sol":"Step 1: The first letter H gives the first-stage result.\nStep 2: The second letter T gives the second-stage result.\nStep 3: Therefore HT describes the entire experiment.","steps":["Step 1: The first letter H gives the first-stage result.","Step 2: The second letter T gives the second-stage result.","Step 3: Therefore HT describes the entire experiment."],"options":[],"conceptId":"math_probability_reading_a_probability_tree_diagram","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Reading a Probability Tree Diagram"}', 2),
  (939, 282, 'A coin is tossed twice. How many branches leave the first stage?', 'text', 1, 'What can one coin toss produce?', '{"why":"The first toss has exactly two possible outcomes.","sol":"Step 1: One coin toss can produce Head or Tail.\nStep 2: Therefore the first stage has two possible results.\nStep 3: Each possible result needs one branch.","steps":["Step 1: One coin toss can produce Head or Tail.","Step 2: Therefore the first stage has two possible results.","Step 3: Each possible result needs one branch."],"options":[],"conceptId":"math_probability_building_a_two_stage_probability_tree","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Building a Two-Stage Probability Tree"}', 0),
  (940, 282, 'A die is rolled and then a coin is tossed. How many complete paths are possible?', 'text', 1, 'Multiply the number of choices at each stage.', '{"why":"Every one of the 6 die outcomes can be paired with either H or T.","sol":"Step 1: The die has 6 possible results.\nStep 2: The coin has 2 possible results.\nStep 3: Each die result can be followed by either coin result.\nStep 4: 6 × 2 = 12.","steps":["Step 1: The die has 6 possible results.","Step 2: The coin has 2 possible results.","Step 3: Each die result can be followed by either coin result.","Step 4: 6 × 2 = 12."],"options":[],"conceptId":"math_probability_building_a_two_stage_probability_tree","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Building a Two-Stage Probability Tree"}', 1),
  (941, 282, 'A spinner has R, B and G and is spun twice. List all paths beginning with B.', 'text', 1, 'After B, the second result can still be R, B or G.', '{"why":"Each possible second-stage result creates one path from B.","sol":"Step 1: The first result is fixed as B.\nStep 2: The second result can be R, B or G.\nStep 3: Therefore the paths are BR, BB and BG.","steps":["Step 1: The first result is fixed as B.","Step 2: The second result can be R, B or G.","Step 3: Therefore the paths are BR, BB and BG."],"options":[],"conceptId":"math_probability_building_a_two_stage_probability_tree","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Building a Two-Stage Probability Tree"}', 2),
  (942, 283, 'A fair die is rolled. What probability should be written on the branch for getting 4?', 'text', 1, 'There are 6 equally likely die outcomes.', '{"why":"One of the six equally likely outcomes is 4.","sol":"Step 1: A fair die has 6 equally likely outcomes.\nStep 2: Only one outcome is 4.\nStep 3: Therefore P(4) = 1/6.","steps":["Step 1: A fair die has 6 equally likely outcomes.","Step 2: Only one outcome is 4.","Step 3: Therefore P(4) = 1/6."],"options":[],"conceptId":"math_probability_probabilities_on_tree_branches","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Probabilities on Tree Branches"}', 0),
  (943, 283, 'A bag has 4 red balls and 6 blue balls. Find P(R).', 'text', 1, 'First find the total number of balls.', '{"why":"Probability equals favourable outcomes divided by total outcomes.","sol":"Step 1: Total balls = 4 + 6 = 10.\nStep 2: There are 4 red balls.\nStep 3: P(R) = 4/10.\nStep 4: Simplify 4/10 to 2/5.","steps":["Step 1: Total balls = 4 + 6 = 10.","Step 2: There are 4 red balls.","Step 3: P(R) = 4/10.","Step 4: Simplify 4/10 to 2/5."],"options":[],"conceptId":"math_probability_probabilities_on_tree_branches","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Probabilities on Tree Branches"}', 1),
  (944, 283, 'A box has 2 green, 3 yellow and 5 blue counters. Check the branch probabilities.', 'text', 1, 'Calculate each probability and add them.', '{"why":"All possible first-stage outcomes must account for the whole probability.","sol":"Step 1: Total = 2 + 3 + 5 = 10.\nStep 2: P(G) = 2/10, P(Y) = 3/10, P(B) = 5/10.\nStep 3: Add them: 2/10 + 3/10 + 5/10.\nStep 4: The result is 10/10 = 1.","steps":["Step 1: Total = 2 + 3 + 5 = 10.","Step 2: P(G) = 2/10, P(Y) = 3/10, P(B) = 5/10.","Step 3: Add them: 2/10 + 3/10 + 5/10.","Step 4: The result is 10/10 = 1."],"options":[],"conceptId":"math_probability_probabilities_on_tree_branches","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Probabilities on Tree Branches"}', 2),
  (945, 284, 'A fair coin is tossed twice. Find P(HH).', 'text', 1, 'Follow H on the first stage and H on the second stage.', '{"why":"Both heads must occur along the same complete path.","sol":"Step 1: P(H on first toss) = 1/2.\nStep 2: P(H on second toss) = 1/2.\nStep 3: Multiply along the path.\nStep 4: P(HH) = 1/2 × 1/2 = 1/4.","steps":["Step 1: P(H on first toss) = 1/2.","Step 2: P(H on second toss) = 1/2.","Step 3: Multiply along the path.","Step 4: P(HH) = 1/2 × 1/2 = 1/4."],"options":[],"conceptId":"math_probability_probability_along_a_complete_path","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Probability Along a Complete Path"}', 0),
  (946, 284, 'A fair coin is tossed twice. Find P(HT).', 'text', 1, 'Multiply the probability of H by the probability of T.', '{"why":"HT is one complete path through the two-stage experiment.","sol":"Step 1: P(H) = 1/2.\nStep 2: P(T) = 1/2.\nStep 3: P(HT) = 1/2 × 1/2.\nStep 4: P(HT) = 1/4.","steps":["Step 1: P(H) = 1/2.","Step 2: P(T) = 1/2.","Step 3: P(HT) = 1/2 × 1/2.","Step 4: P(HT) = 1/4."],"options":[],"conceptId":"math_probability_probability_along_a_complete_path","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Probability Along a Complete Path"}', 1),
  (947, 284, 'A fair die is rolled and then a fair coin is tossed. Find P(6H).', 'text', 1, 'P(6) = 1/6 and P(H) = 1/2.', '{"why":"The path requires both a 6 and then a Head.","sol":"Step 1: P(6) = 1/6.\nStep 2: P(H) = 1/2.\nStep 3: Multiply along the complete path.\nStep 4: P(6H) = 1/6 × 1/2 = 1/12.","steps":["Step 1: P(6) = 1/6.","Step 2: P(H) = 1/2.","Step 3: Multiply along the complete path.","Step 4: P(6H) = 1/6 × 1/2 = 1/12."],"options":[],"conceptId":"math_probability_probability_along_a_complete_path","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Probability Along a Complete Path"}', 2),
  (948, 285, 'A bag has 3 red and 2 blue balls. A ball is replaced after the first draw. Find P(RR).', 'text', 1, 'Replacement means there are still 3 red out of 5.', '{"why":"Replacement restores the original contents before the second draw.","sol":"Step 1: First P(R) = 3/5.\nStep 2: The red ball is replaced, so the bag returns to 3 red and 2 blue.\nStep 3: Second P(R) = 3/5.\nStep 4: P(RR) = 3/5 × 3/5 = 9/25.","steps":["Step 1: First P(R) = 3/5.","Step 2: The red ball is replaced, so the bag returns to 3 red and 2 blue.","Step 3: Second P(R) = 3/5.","Step 4: P(RR) = 3/5 × 3/5 = 9/25."],"options":[],"conceptId":"math_probability_tree_diagrams_with_replacement","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Tree Diagrams With Replacement"}', 0),
  (949, 285, 'Using the same bag with replacement, find P(RB).', 'text', 1, 'Both stages have the original probabilities.', '{"why":"The replacement means 2 blue balls are still available for the second draw.","sol":"Step 1: First P(R) = 3/5.\nStep 2: The ball is replaced.\nStep 3: Second P(B) = 2/5.\nStep 4: P(RB) = 3/5 × 2/5 = 6/25.","steps":["Step 1: First P(R) = 3/5.","Step 2: The ball is replaced.","Step 3: Second P(B) = 2/5.","Step 4: P(RB) = 3/5 × 2/5 = 6/25."],"options":[],"conceptId":"math_probability_tree_diagrams_with_replacement","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Tree Diagrams With Replacement"}', 1),
  (950, 285, 'With replacement, what is P(BB) for a bag with 3 red and 2 blue balls?', 'text', 1, 'P(B) is 2/5 on both stages.', '{"why":"The number of blue balls returns to 2 before the second selection.","sol":"Step 1: First P(B) = 2/5.\nStep 2: The selected blue ball is replaced.\nStep 3: Second P(B) = 2/5.\nStep 4: P(BB) = 2/5 × 2/5 = 4/25.","steps":["Step 1: First P(B) = 2/5.","Step 2: The selected blue ball is replaced.","Step 3: Second P(B) = 2/5.","Step 4: P(BB) = 2/5 × 2/5 = 4/25."],"options":[],"conceptId":"math_probability_tree_diagrams_with_replacement","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Tree Diagrams With Replacement"}', 2),
  (951, 286, 'A bag has 3 red and 2 blue balls. A red ball is removed without replacement. What is P(R) on the second draw?', 'text', 1, 'One red has already been removed.', '{"why":"Without replacement, the first red is no longer available.","sol":"Step 1: Initially there are 3 red and 2 blue, giving 5 balls.\nStep 2: One red is removed.\nStep 3: Red remaining = 3 − 1 = 2.\nStep 4: Total remaining = 5 − 1 = 4.\nStep 5: Therefore P(R) = 2/4 = 1/2.","steps":["Step 1: Initially there are 3 red and 2 blue, giving 5 balls.","Step 2: One red is removed.","Step 3: Red remaining = 3 − 1 = 2.","Step 4: Total remaining = 5 − 1 = 4.","Step 5: Therefore P(R) = 2/4 = 1/2."],"options":[],"conceptId":"math_probability_tree_diagrams_without_replacement","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Tree Diagrams Without Replacement"}', 0),
  (952, 286, 'A bag has 3 red and 2 blue balls. Find P(RR) without replacement.', 'text', 1, 'Use 3/5 first, then 2/4.', '{"why":"The number of red balls falls from 3 to 2 after the first red is removed.","sol":"Step 1: First P(R) = 3/5.\nStep 2: After removing red, 2 red remain out of 4 balls.\nStep 3: Second P(R) = 2/4.\nStep 4: P(RR) = 3/5 × 2/4.\nStep 5: P(RR) = 6/20 = 3/10.","steps":["Step 1: First P(R) = 3/5.","Step 2: After removing red, 2 red remain out of 4 balls.","Step 3: Second P(R) = 2/4.","Step 4: P(RR) = 3/5 × 2/4.","Step 5: P(RR) = 6/20 = 3/10."],"options":[],"conceptId":"math_probability_tree_diagrams_without_replacement","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Tree Diagrams Without Replacement"}', 1),
  (953, 286, 'A bag has 3 red and 2 blue balls. Find P(BB) without replacement.', 'text', 1, 'After removing the first blue, only 1 blue remains.', '{"why":"Without replacement, one blue ball disappears after the first blue selection.","sol":"Step 1: First P(B) = 2/5.\nStep 2: After removing blue, 1 blue remains out of 4 balls.\nStep 3: Second P(B) = 1/4.\nStep 4: P(BB) = 2/5 × 1/4.\nStep 5: P(BB) = 2/20 = 1/10.","steps":["Step 1: First P(B) = 2/5.","Step 2: After removing blue, 1 blue remains out of 4 balls.","Step 3: Second P(B) = 1/4.","Step 4: P(BB) = 2/5 × 1/4.","Step 5: P(BB) = 2/20 = 1/10."],"options":[],"conceptId":"math_probability_tree_diagrams_without_replacement","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Tree Diagrams Without Replacement"}', 2),
  (954, 287, 'How many rows are in A = [[4,7,2],[1,5,9]]?', 'text', 1, 'Count the horizontal lines, not the individual numbers.', '{"why":"Each horizontal line of entries forms one row.","sol":"Step 1: The first row is [4,7,2].\nStep 2: The second row is [1,5,9].\nStep 3: There are 2 horizontal rows.","steps":["Step 1: The first row is [4,7,2].","Step 2: The second row is [1,5,9].","Step 3: There are 2 horizontal rows."],"options":[],"conceptId":"math_matrices_introduction_to_matrices","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Introduction to Matrices"}', 0),
  (955, 287, 'How many columns are in B = [[3,8],[1,6],[5,9]]?', 'text', 1, 'Count the vertical positions from left to right.', '{"why":"Entries directly above and below one another occupy the same column.","sol":"Step 1: The first column contains 3, 1 and 5.\nStep 2: The second column contains 8, 6 and 9.\nStep 3: There are 2 vertical columns.","steps":["Step 1: The first column contains 3, 1 and 5.","Step 2: The second column contains 8, 6 and 9.","Step 3: There are 2 vertical columns."],"options":[],"conceptId":"math_matrices_introduction_to_matrices","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Introduction to Matrices"}', 1),
  (956, 287, 'A = [[2,4,6,8],[1,3,5,7]]. State the number of rows and columns.', 'text', 1, 'Count horizontal lines first, then entries across a row.', '{"why":"Rows are counted horizontally and columns vertically.","sol":"Step 1: There are 2 horizontal lines, so there are 2 rows.\nStep 2: Each row has 4 entries.\nStep 3: The matrix therefore has 4 columns.","steps":["Step 1: There are 2 horizontal lines, so there are 2 rows.","Step 2: Each row has 4 entries.","Step 3: The matrix therefore has 4 columns."],"options":[],"conceptId":"math_matrices_introduction_to_matrices","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Introduction to Matrices"}', 2),
  (957, 287, 'Which is a row: [2,5,8] or [[2],[5],[8]]?', 'text', 1, 'A row is arranged horizontally.', '{"why":"A row is a horizontal arrangement of entries.","sol":"Step 1: [2,5,8] places the entries side by side.\nStep 2: The entries in [[2],[5],[8]] are arranged vertically.\nStep 3: Therefore [2,5,8] is a row.","steps":["Step 1: [2,5,8] places the entries side by side.","Step 2: The entries in [[2],[5],[8]] are arranged vertically.","Step 3: Therefore [2,5,8] is a row."],"options":[],"conceptId":"math_matrices_introduction_to_matrices","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Introduction to Matrices"}', 3),
  (958, 288, 'Find the order of A = [[4,7,2],[1,5,9]].', 'text', 1, 'Count the rows first and the columns second.', '{"why":"The order of a matrix is written as rows × columns.","sol":"Step 1: There are 2 horizontal rows.\nStep 2: There are 3 entries across each row, so there are 3 columns.\nStep 3: Write rows first: 2 × 3.","steps":["Step 1: There are 2 horizontal rows.","Step 2: There are 3 entries across each row, so there are 3 columns.","Step 3: Write rows first: 2 × 3."],"options":[],"conceptId":"math_matrices_order_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Order of a Matrix"}', 0),
  (959, 288, 'Find the order of B = [[1,2],[3,4],[5,6],[7,8]].', 'text', 1, 'Count the horizontal lines before the vertical positions.', '{"why":"The first number in the order always gives the number of rows.","sol":"Step 1: There are 4 horizontal rows.\nStep 2: There are 2 columns.\nStep 3: Write the row count first: 4 × 2.","steps":["Step 1: There are 4 horizontal rows.","Step 2: There are 2 columns.","Step 3: Write the row count first: 4 × 2."],"options":[],"conceptId":"math_matrices_order_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Order of a Matrix"}', 1),
  (960, 288, 'A matrix has 5 rows and 3 columns. State its order.', 'text', 1, 'Do not reverse the two numbers.', '{"why":"Rows are written first and columns second.","sol":"Step 1: Rows = 5.\nStep 2: Columns = 3.\nStep 3: Order = 5 × 3.","steps":["Step 1: Rows = 5.","Step 2: Columns = 3.","Step 3: Order = 5 × 3."],"options":[],"conceptId":"math_matrices_order_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Order of a Matrix"}', 2),
  (961, 288, 'How many entries are in a matrix of order 4 × 3?', 'text', 1, 'Each of the 4 rows contains 3 entries.', '{"why":"The total number of entries is the number of rows multiplied by the number of columns.","sol":"Step 1: There are 4 rows.\nStep 2: Each row contains 3 entries.\nStep 3: Total entries = 3 + 3 + 3 + 3 = 12.\nStep 4: Equivalently, 4 × 3 = 12.","steps":["Step 1: There are 4 rows.","Step 2: Each row contains 3 entries.","Step 3: Total entries = 3 + 3 + 3 + 3 = 12.","Step 4: Equivalently, 4 × 3 = 12."],"options":[],"conceptId":"math_matrices_order_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Order of a Matrix"}', 3),
  (962, 289, 'Given A = [[4,7,2],[9,5,6],[1,8,3]], find a₂₃.', 'text', 1, 'Select row 2 first, then the third entry in that row.', '{"why":"The subscripts mean row 2, column 3.","sol":"Step 1: Row 2 is [9,5,6].\nStep 2: The first entry is 9, the second is 5 and the third is 6.\nStep 3: Therefore a₂₃ = 6.","steps":["Step 1: Row 2 is [9,5,6].","Step 2: The first entry is 9, the second is 5 and the third is 6.","Step 3: Therefore a₂₃ = 6."],"options":[],"conceptId":"math_matrices_elements_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Elements of a Matrix"}', 0),
  (963, 289, 'Given A = [[4,7,2],[9,5,6],[1,8,3]], find a₃₁.', 'text', 1, 'Go to the third row and choose its first entry.', '{"why":"The first subscript identifies row 3; the second identifies column 1.","sol":"Step 1: Row 3 is [1,8,3].\nStep 2: Column 1 is the first entry in that row.\nStep 3: The first entry is 1.","steps":["Step 1: Row 3 is [1,8,3].","Step 2: Column 1 is the first entry in that row.","Step 3: The first entry is 1."],"options":[],"conceptId":"math_matrices_elements_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Elements of a Matrix"}', 1),
  (964, 289, 'Given A = [[4,7,2],[9,5,6],[1,8,3]], find a₁₂.', 'text', 1, 'Select row 1 and then count to column 2.', '{"why":"a₁₂ refers to the entry in row 1, column 2.","sol":"Step 1: Row 1 is [4,7,2].\nStep 2: The second entry in row 1 is 7.\nStep 3: Therefore a₁₂ = 7.","steps":["Step 1: Row 1 is [4,7,2].","Step 2: The second entry in row 1 is 7.","Step 3: Therefore a₁₂ = 7."],"options":[],"conceptId":"math_matrices_elements_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Elements of a Matrix"}', 2),
  (965, 289, 'Given B = [[2,-1,5],[4,3,7]], find b₁₂.', 'text', 1, 'Do not drop the negative sign from an entry.', '{"why":"The element is -1, and its negative sign is part of its value.","sol":"Step 1: Row 1 is [2,-1,5].\nStep 2: Column 2 selects the second entry.\nStep 3: The second entry is -1.","steps":["Step 1: Row 1 is [2,-1,5].","Step 2: Column 2 selects the second entry.","Step 3: The second entry is -1."],"options":[],"conceptId":"math_matrices_elements_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Elements of a Matrix"}', 3),
  (966, 290, 'What type of matrix is A = [[3,5,7]]?', 'text', 1, 'Count the rows in the entire matrix.', '{"why":"A row matrix has exactly one row.","sol":"Step 1: The entries 3, 5 and 7 are on one horizontal line.\nStep 2: There is exactly 1 row.\nStep 3: Therefore A is a row matrix.","steps":["Step 1: The entries 3, 5 and 7 are on one horizontal line.","Step 2: There is exactly 1 row.","Step 3: Therefore A is a row matrix."],"options":[],"conceptId":"math_matrices_row_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Row Matrix"}', 0),
  (967, 290, 'Find the order of B = [[2,-4,6,8]].', 'text', 1, 'Count rows first and entries across second.', '{"why":"The order is the number of rows followed by the number of columns.","sol":"Step 1: There is 1 horizontal row.\nStep 2: There are 4 entries across the row.\nStep 3: Order = 1 × 4.","steps":["Step 1: There is 1 horizontal row.","Step 2: There are 4 entries across the row.","Step 3: Order = 1 × 4."],"options":[],"conceptId":"math_matrices_row_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Row Matrix"}', 1),
  (968, 290, 'Is C = [[1,2],[3,4]] a row matrix?', 'text', 1, 'A row matrix must have exactly one row.', '{"why":"A matrix with two rows does not meet the definition of a row matrix.","sol":"Step 1: The first horizontal line is [1,2].\nStep 2: The second horizontal line is [3,4].\nStep 3: There are 2 rows, not 1.\nStep 4: Therefore C is not a row matrix.","steps":["Step 1: The first horizontal line is [1,2].","Step 2: The second horizontal line is [3,4].","Step 3: There are 2 rows, not 1.","Step 4: Therefore C is not a row matrix."],"options":[],"conceptId":"math_matrices_row_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Row Matrix"}', 2),
  (969, 290, 'Write a row matrix containing 6, -3 and 10.', 'text', 1, 'Place all three entries on one horizontal line.', '{"why":"All entries are arranged in one horizontal row.","sol":"Step 1: A row matrix has one row.\nStep 2: Place 6, -3 and 10 side by side.\nStep 3: The resulting matrix is [6,-3,10].","steps":["Step 1: A row matrix has one row.","Step 2: Place 6, -3 and 10 side by side.","Step 3: The resulting matrix is [6,-3,10]."],"options":[],"conceptId":"math_matrices_row_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Row Matrix"}', 3),
  (970, 291, 'What type of matrix is A = [[3],[5],[7]]?', 'text', 1, 'Count the vertical columns.', '{"why":"A column matrix has exactly one column.","sol":"Step 1: The entries 3, 5 and 7 are arranged vertically.\nStep 2: There is exactly 1 column.\nStep 3: Therefore A is a column matrix.","steps":["Step 1: The entries 3, 5 and 7 are arranged vertically.","Step 2: There is exactly 1 column.","Step 3: Therefore A is a column matrix."],"options":[],"conceptId":"math_matrices_column_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Column Matrix"}', 0),
  (971, 291, 'Find the order of B = [[2],[-4],[6],[8]].', 'text', 1, 'Count the horizontal rows first.', '{"why":"The order records rows first and columns second.","sol":"Step 1: There are 4 horizontal positions, so there are 4 rows.\nStep 2: There is only 1 vertical column.\nStep 3: Order = 4 × 1.","steps":["Step 1: There are 4 horizontal positions, so there are 4 rows.","Step 2: There is only 1 vertical column.","Step 3: Order = 4 × 1."],"options":[],"conceptId":"math_matrices_column_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Column Matrix"}', 1),
  (972, 291, 'Is C = [[1,2],[3,4],[5,6]] a column matrix?', 'text', 1, 'Count the columns, not the rows.', '{"why":"C has two columns, so it is not a column matrix.","sol":"Step 1: The first column contains 1, 3 and 5.\nStep 2: The second column contains 2, 4 and 6.\nStep 3: There are 2 columns.\nStep 4: A column matrix must have exactly 1 column.","steps":["Step 1: The first column contains 1, 3 and 5.","Step 2: The second column contains 2, 4 and 6.","Step 3: There are 2 columns.","Step 4: A column matrix must have exactly 1 column."],"options":[],"conceptId":"math_matrices_column_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Column Matrix"}', 2),
  (973, 291, 'Write a column matrix containing 7, -1 and 5 in that order.', 'text', 1, 'Put each entry on a new line, keeping the given order.', '{"why":"The entries are arranged vertically in one column.","sol":"Step 1: Place 7 in the first row.\nStep 2: Place -1 in the second row.\nStep 3: Place 5 in the third row.\nStep 4: Use one vertical column.","steps":["Step 1: Place 7 in the first row.","Step 2: Place -1 in the second row.","Step 3: Place 5 in the third row.","Step 4: Use one vertical column."],"options":[],"conceptId":"math_matrices_column_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Column Matrix"}', 3),
  (974, 292, 'Determine whether A = [[4,7],[2,5]] is a square matrix.', 'text', 1, 'Compare the number of rows with the number of columns.', '{"why":"A square matrix has an equal number of rows and columns.","sol":"Step 1: A has 2 rows.\nStep 2: A has 2 columns.\nStep 3: Since the number of rows equals the number of columns, A is square.","steps":["Step 1: A has 2 rows.","Step 2: A has 2 columns.","Step 3: Since the number of rows equals the number of columns, A is square."],"options":[],"conceptId":"math_matrices_square_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Square Matrix"}', 0),
  (975, 292, 'Determine whether B = [[3,8,1],[5,2,7]] is a square matrix.', 'text', 1, 'Count both dimensions.', '{"why":"The matrix has 2 rows but 3 columns.","sol":"Step 1: B has 2 rows.\nStep 2: B has 3 columns.\nStep 3: 2 is not equal to 3.\nStep 4: Therefore B is not square.","steps":["Step 1: B has 2 rows.","Step 2: B has 3 columns.","Step 3: 2 is not equal to 3.","Step 4: Therefore B is not square."],"options":[],"conceptId":"math_matrices_square_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Square Matrix"}', 1),
  (976, 292, 'A matrix has order 4 × 4. Is it a square matrix?', 'text', 1, 'For a square matrix, the two dimensions must be equal.', '{"why":"A 4 × 4 matrix has the same number of rows and columns.","sol":"Step 1: The matrix has 4 rows.\nStep 2: The matrix has 4 columns.\nStep 3: 4 equals 4.\nStep 4: Therefore the matrix is square.","steps":["Step 1: The matrix has 4 rows.","Step 2: The matrix has 4 columns.","Step 3: 4 equals 4.","Step 4: Therefore the matrix is square."],"options":[],"conceptId":"math_matrices_square_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Square Matrix"}', 2),
  (977, 292, 'A student says [[1,2,3],[4,5,6]] is square because it contains 6 numbers arranged evenly. Is the student correct?', 'text', 1, 'The number of entries is not the test for being square.', '{"why":"Being square depends on equal rows and columns, not on the total number of entries.","sol":"Step 1: The matrix has 2 rows.\nStep 2: It has 3 columns.\nStep 3: A square matrix requires the number of rows to equal the number of columns.\nStep 4: 2 is not equal to 3.\nStep 5: Therefore the student is incorrect.","steps":["Step 1: The matrix has 2 rows.","Step 2: It has 3 columns.","Step 3: A square matrix requires the number of rows to equal the number of columns.","Step 4: 2 is not equal to 3.","Step 5: Therefore the student is incorrect."],"options":[],"conceptId":"math_matrices_square_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Square Matrix"}', 3),
  (978, 293, 'Is [[0,0],[0,0]] a zero matrix?', 'text', 1, 'Check every entry.', '{"why":"Every element of the matrix is zero.","sol":"Step 1: The first row contains only zeros.\nStep 2: The second row contains only zeros.\nStep 3: Every element is zero.\nStep 4: Therefore it is a zero matrix.","steps":["Step 1: The first row contains only zeros.","Step 2: The second row contains only zeros.","Step 3: Every element is zero.","Step 4: Therefore it is a zero matrix."],"options":[],"conceptId":"math_matrices_zero_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Zero Matrix"}', 0),
  (979, 293, 'Is [[0,0,0],[0,0,0]] a zero matrix?', 'text', 1, 'The matrix does not have to be square.', '{"why":"A zero matrix can be rectangular; all that matters is that every entry is zero.","sol":"Step 1: There are 2 rows and 3 columns.\nStep 2: Every entry is zero.\nStep 3: The dimensions do not affect whether it is a zero matrix.\nStep 4: Therefore it is a zero matrix.","steps":["Step 1: There are 2 rows and 3 columns.","Step 2: Every entry is zero.","Step 3: The dimensions do not affect whether it is a zero matrix.","Step 4: Therefore it is a zero matrix."],"options":[],"conceptId":"math_matrices_zero_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Zero Matrix"}', 1),
  (980, 293, 'Is [[0,0],[0,4]] a zero matrix?', 'text', 1, 'Look carefully at every entry.', '{"why":"A single non-zero element means the matrix is not a zero matrix.","sol":"Step 1: Three entries are zero.\nStep 2: The bottom-right entry is 4.\nStep 3: 4 is not zero.\nStep 4: Therefore not every entry is zero.","steps":["Step 1: Three entries are zero.","Step 2: The bottom-right entry is 4.","Step 3: 4 is not zero.","Step 4: Therefore not every entry is zero."],"options":[],"conceptId":"math_matrices_zero_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Zero Matrix"}', 2),
  (981, 293, 'Write a zero matrix of order 2 × 3.', 'text', 1, 'Use 2 rows, 3 columns, and put zero in every position.', '{"why":"It has the required dimensions and every element is zero.","sol":"Step 1: Create 2 horizontal rows.\nStep 2: Put 3 entries in each row.\nStep 3: Make every entry zero.\nStep 4: The matrix is [[0,0,0],[0,0,0]].","steps":["Step 1: Create 2 horizontal rows.","Step 2: Put 3 entries in each row.","Step 3: Make every entry zero.","Step 4: The matrix is [[0,0,0],[0,0,0]]."],"options":[],"conceptId":"math_matrices_zero_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Zero Matrix"}', 3),
  (982, 294, 'Is [[4,0,0],[0,7,0],[0,0,9]] a diagonal matrix?', 'text', 1, 'Check the entries outside the main diagonal.', '{"why":"Every off-diagonal entry is zero.","sol":"Step 1: The main diagonal is 4, 7, 9.\nStep 2: Every entry outside that diagonal is zero.\nStep 3: Therefore the matrix satisfies the definition of a diagonal matrix.","steps":["Step 1: The main diagonal is 4, 7, 9.","Step 2: Every entry outside that diagonal is zero.","Step 3: Therefore the matrix satisfies the definition of a diagonal matrix."],"options":[],"conceptId":"math_matrices_diagonal_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Diagonal Matrix"}', 0),
  (983, 294, 'Is [[3,0,0],[0,4,2],[0,0,7]] diagonal?', 'text', 1, 'Look at row 2, column 3.', '{"why":"The off-diagonal entry 2 violates the definition.","sol":"Step 1: The main diagonal is 3, 4, 7.\nStep 2: The entry in row 2, column 3 is 2.\nStep 3: That entry is outside the main diagonal.\nStep 4: A diagonal matrix requires it to be zero.\nStep 5: Therefore the matrix is not diagonal.","steps":["Step 1: The main diagonal is 3, 4, 7.","Step 2: The entry in row 2, column 3 is 2.","Step 3: That entry is outside the main diagonal.","Step 4: A diagonal matrix requires it to be zero.","Step 5: Therefore the matrix is not diagonal."],"options":[],"conceptId":"math_matrices_diagonal_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Diagonal Matrix"}', 1),
  (984, 294, 'Is [[5,0],[0,0]] a diagonal matrix?', 'text', 1, 'A zero is allowed on the main diagonal.', '{"why":"Diagonal entries may be zero; only off-diagonal entries must be zero.","sol":"Step 1: The main diagonal contains 5 and 0.\nStep 2: The only entry outside the main diagonal is 0.\nStep 3: Therefore all off-diagonal entries are zero.\nStep 4: The matrix is diagonal.","steps":["Step 1: The main diagonal contains 5 and 0.","Step 2: The only entry outside the main diagonal is 0.","Step 3: Therefore all off-diagonal entries are zero.","Step 4: The matrix is diagonal."],"options":[],"conceptId":"math_matrices_diagonal_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Diagonal Matrix"}', 2),
  (985, 294, 'A student says [[0,0],[0,0]] cannot be diagonal because the diagonal entries are zero. Is the student correct?', 'text', 1, 'The definition places the restriction on entries outside the diagonal.', '{"why":"A zero matrix is also a diagonal matrix because all of its off-diagonal entries are zero.","sol":"Step 1: The main diagonal contains 0 and 0.\nStep 2: Both entries outside the main diagonal are also zero.\nStep 3: There is no requirement that diagonal entries be non-zero.\nStep 4: Therefore the matrix is diagonal.","steps":["Step 1: The main diagonal contains 0 and 0.","Step 2: Both entries outside the main diagonal are also zero.","Step 3: There is no requirement that diagonal entries be non-zero.","Step 4: Therefore the matrix is diagonal."],"options":[],"conceptId":"math_matrices_diagonal_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Diagonal Matrix"}', 3),
  (986, 295, 'Is [[1,0],[0,1]] an identity matrix?', 'text', 1, 'Check the diagonal and the entries outside it.', '{"why":"It satisfies both identity-matrix conditions.","sol":"Step 1: The matrix is square: 2 rows and 2 columns.\nStep 2: The main diagonal contains 1 and 1.\nStep 3: The off-diagonal entries are both 0.\nStep 4: Therefore it is I₂.","steps":["Step 1: The matrix is square: 2 rows and 2 columns.","Step 2: The main diagonal contains 1 and 1.","Step 3: The off-diagonal entries are both 0.","Step 4: Therefore it is I₂."],"options":[],"conceptId":"math_matrices_identity_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Identity Matrix"}', 0),
  (987, 295, 'Is [[1,0],[0,2]] an identity matrix?', 'text', 1, 'Check every entry on the main diagonal.', '{"why":"The diagonal must contain only 1s.","sol":"Step 1: The main diagonal contains 1 and 2.\nStep 2: An identity matrix requires every diagonal entry to be 1.\nStep 3: The second diagonal entry is 2.\nStep 4: Therefore it is not an identity matrix.","steps":["Step 1: The main diagonal contains 1 and 2.","Step 2: An identity matrix requires every diagonal entry to be 1.","Step 3: The second diagonal entry is 2.","Step 4: Therefore it is not an identity matrix."],"options":[],"conceptId":"math_matrices_identity_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Identity Matrix"}', 1),
  (988, 295, 'Is [[1,0],[1,1]] an identity matrix?', 'text', 1, 'The diagonal is correct, but check outside the diagonal.', '{"why":"Every off-diagonal entry must be zero.","sol":"Step 1: The main diagonal contains 1 and 1.\nStep 2: The bottom-left entry is outside the main diagonal.\nStep 3: That entry is 1, but it must be 0.\nStep 4: Therefore the matrix is not an identity matrix.","steps":["Step 1: The main diagonal contains 1 and 1.","Step 2: The bottom-left entry is outside the main diagonal.","Step 3: That entry is 1, but it must be 0.","Step 4: Therefore the matrix is not an identity matrix."],"options":[],"conceptId":"math_matrices_identity_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Identity Matrix"}', 2),
  (989, 295, 'Which matrix is I₃: A = [[1,0,0],[0,1,0],[0,0,1]] or B = [[1,0,0],[0,2,0],[0,0,1]]?', 'text', 1, 'The diagonal of an identity matrix must contain only 1s.', '{"why":"A has 1s on the entire main diagonal and zeros everywhere else.","sol":"Step 1: For A, the main diagonal is 1, 1, 1 and all other entries are zero.\nStep 2: For B, the main diagonal is 1, 2, 1.\nStep 3: The 2 in B violates the identity-matrix condition.\nStep 4: Therefore A is I₃.","steps":["Step 1: For A, the main diagonal is 1, 1, 1 and all other entries are zero.","Step 2: For B, the main diagonal is 1, 2, 1.","Step 3: The 2 in B violates the identity-matrix condition.","Step 4: Therefore A is I₃."],"options":[],"conceptId":"math_matrices_identity_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Identity Matrix"}', 3),
  (990, 296, 'Are A = [[2,5],[7,9]] and B = [[2,5],[7,9]] equal?', 'text', 1, 'First compare their orders, then compare corresponding entries.', '{"why":"The matrices have the same order and all corresponding elements are equal.","sol":"Step 1: Both matrices have order 2 × 2.\nStep 2: Compare 2 with 2: equal.\nStep 3: Compare 5 with 5: equal.\nStep 4: Compare 7 with 7: equal.\nStep 5: Compare 9 with 9: equal.\nStep 6: All corresponding elements are equal.","steps":["Step 1: Both matrices have order 2 × 2.","Step 2: Compare 2 with 2: equal.","Step 3: Compare 5 with 5: equal.","Step 4: Compare 7 with 7: equal.","Step 5: Compare 9 with 9: equal.","Step 6: All corresponding elements are equal."],"options":[],"conceptId":"math_matrices_equality_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Equality of Matrices"}', 0),
  (991, 296, 'Are A = [[2,5],[7,9]] and B = [[2,5],[7,4]] equal?', 'text', 1, 'Look for even one corresponding pair that is different.', '{"why":"All corresponding elements must be equal; one mismatch makes the matrices unequal.","sol":"Step 1: Both matrices have order 2 × 2.\nStep 2: The first three corresponding entries agree.\nStep 3: Compare the bottom-right entries: 9 and 4.\nStep 4: Since 9 is not equal to 4, the matrices are not equal.","steps":["Step 1: Both matrices have order 2 × 2.","Step 2: The first three corresponding entries agree.","Step 3: Compare the bottom-right entries: 9 and 4.","Step 4: Since 9 is not equal to 4, the matrices are not equal."],"options":[],"conceptId":"math_matrices_equality_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Equality of Matrices"}', 1),
  (992, 296, 'If [[x,4],[2,9]] = [[7,4],[2,9]], find x.', 'text', 1, 'Equal matrices have equal corresponding elements.', '{"why":"Corresponding elements of equal matrices must have the same value.","sol":"Step 1: Compare the top-left entries.\nStep 2: The first matrix has x there.\nStep 3: The second matrix has 7 there.\nStep 4: Therefore x = 7.\nStep 5: The remaining corresponding entries already agree.","steps":["Step 1: Compare the top-left entries.","Step 2: The first matrix has x there.","Step 3: The second matrix has 7 there.","Step 4: Therefore x = 7.","Step 5: The remaining corresponding entries already agree."],"options":[],"conceptId":"math_matrices_equality_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Equality of Matrices"}', 2),
  (993, 296, 'Can a 2 × 3 matrix be equal to a 3 × 2 matrix?', 'text', 1, 'Compare the orders before looking at the entries.', '{"why":"Equal matrices must have exactly the same number of rows and columns.","sol":"Step 1: The first matrix has order 2 × 3.\nStep 2: The second matrix has order 3 × 2.\nStep 3: Their orders are different.\nStep 4: Matrices with different orders cannot be equal.","steps":["Step 1: The first matrix has order 2 × 3.","Step 2: The second matrix has order 3 × 2.","Step 3: Their orders are different.","Step 4: Matrices with different orders cannot be equal."],"options":[],"conceptId":"math_matrices_equality_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Equality of Matrices"}', 3),
  (994, 296, 'A student says [[1,2],[3,4]] and [[2,1],[4,3]] are equal because they contain the same four numbers. Is the student correct?', 'text', 1, 'Equality depends on corresponding positions, not merely the numbers present.', '{"why":"The same numbers must also occur in the same corresponding positions.","sol":"Step 1: Both matrices have order 2 × 2.\nStep 2: Compare the top-left entries: 1 and 2.\nStep 3: They are different.\nStep 4: Therefore the matrices are not equal.","steps":["Step 1: Both matrices have order 2 × 2.","Step 2: Compare the top-left entries: 1 and 2.","Step 3: They are different.","Step 4: Therefore the matrices are not equal."],"options":[],"conceptId":"math_matrices_equality_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q5","subject":"math","chapter":"matrices","topic":"Equality of Matrices"}', 4),
  (995, 297, 'Find [[2,5],[7,3]] + [[4,1],[6,8]].', 'text', 1, 'Add entries occupying the same position.', '{"why":"Matrix addition is performed element-by-element at corresponding positions.","sol":"Step 1: Top-left: 2 + 4 = 6.\nStep 2: Top-right: 5 + 1 = 6.\nStep 3: Bottom-left: 7 + 6 = 13.\nStep 4: Bottom-right: 3 + 8 = 11.\nStep 5: Place each result in its original position.","steps":["Step 1: Top-left: 2 + 4 = 6.","Step 2: Top-right: 5 + 1 = 6.","Step 3: Bottom-left: 7 + 6 = 13.","Step 4: Bottom-right: 3 + 8 = 11.","Step 5: Place each result in its original position."],"options":[],"conceptId":"math_matrices_matrix_addition","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Matrix Addition"}', 0),
  (996, 297, 'Find [[5,-3],[4,6]] + [[-2,7],[8,-1]].', 'text', 1, 'Treat each negative number as part of the calculation.', '{"why":"Corresponding elements are added, including their signs.","sol":"Step 1: 5 + (-2) = 3.\nStep 2: -3 + 7 = 4.\nStep 3: 4 + 8 = 12.\nStep 4: 6 + (-1) = 5.\nStep 5: Therefore the result is [[3,4],[12,5]].","steps":["Step 1: 5 + (-2) = 3.","Step 2: -3 + 7 = 4.","Step 3: 4 + 8 = 12.","Step 4: 6 + (-1) = 5.","Step 5: Therefore the result is [[3,4],[12,5]]."],"options":[],"conceptId":"math_matrices_matrix_addition","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Matrix Addition"}', 1),
  (997, 297, 'Can a 2 × 3 matrix be added to a 3 × 2 matrix?', 'text', 1, 'Matrix addition requires the same order.', '{"why":"Matrices must have the same order before they can be added.","sol":"Step 1: The first matrix has order 2 × 3.\nStep 2: The second has order 3 × 2.\nStep 3: Their orders are different.\nStep 4: Therefore corresponding positions cannot be matched.","steps":["Step 1: The first matrix has order 2 × 3.","Step 2: The second has order 3 × 2.","Step 3: Their orders are different.","Step 4: Therefore corresponding positions cannot be matched."],"options":[],"conceptId":"math_matrices_matrix_addition","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Matrix Addition"}', 2),
  (998, 297, 'A student calculates [[1,2],[3,4]] + [[5,6],[7,8]] as [[6,8],[10,12]]. Explain whether the answer is correct.', 'text', 1, 'Check each corresponding position.', '{"why":"Every corresponding pair has been added correctly and placed in the correct position.","sol":"Step 1: Top-left: 1 + 5 = 6.\nStep 2: Top-right: 2 + 6 = 8.\nStep 3: Bottom-left: 3 + 7 = 10.\nStep 4: Bottom-right: 4 + 8 = 12.\nStep 5: Every entry is correct.","steps":["Step 1: Top-left: 1 + 5 = 6.","Step 2: Top-right: 2 + 6 = 8.","Step 3: Bottom-left: 3 + 7 = 10.","Step 4: Bottom-right: 4 + 8 = 12.","Step 5: Every entry is correct."],"options":[],"conceptId":"math_matrices_matrix_addition","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Matrix Addition"}', 3),
  (999, 298, 'Find [[9,7],[6,5]] - [[4,2],[1,3]].', 'text', 1, 'Subtract the second matrix from the first at each corresponding position.', '{"why":"Matrix subtraction is performed position by position.","sol":"Step 1: 9 - 4 = 5.\nStep 2: 7 - 2 = 5.\nStep 3: 6 - 1 = 5.\nStep 4: 5 - 3 = 2.\nStep 5: Therefore the result is [[5,5],[5,2]].","steps":["Step 1: 9 - 4 = 5.","Step 2: 7 - 2 = 5.","Step 3: 6 - 1 = 5.","Step 4: 5 - 3 = 2.","Step 5: Therefore the result is [[5,5],[5,2]]."],"options":[],"conceptId":"math_matrices_matrix_subtraction","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Matrix Subtraction"}', 0),
  (1000, 298, 'Find [[4,-2],[3,8]] - [[7,-5],[1,4]].', 'text', 1, 'Pay special attention to -2 - (-5).', '{"why":"Subtracting a negative number is equivalent to adding its positive value.","sol":"Step 1: 4 - 7 = -3.\nStep 2: -2 - (-5) = -2 + 5 = 3.\nStep 3: 3 - 1 = 2.\nStep 4: 8 - 4 = 4.","steps":["Step 1: 4 - 7 = -3.","Step 2: -2 - (-5) = -2 + 5 = 3.","Step 3: 3 - 1 = 2.","Step 4: 8 - 4 = 4."],"options":[],"conceptId":"math_matrices_matrix_subtraction","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Matrix Subtraction"}', 1);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (1001, 298, 'Given A = [[8,5],[6,4]] and B = [[3,2],[1,7]], find A - B.', 'text', 1, 'The first matrix always supplies the number being subtracted from.', '{"why":"A - B means corresponding elements of B are subtracted from corresponding elements of A.","sol":"Step 1: 8 - 3 = 5.\nStep 2: 5 - 2 = 3.\nStep 3: 6 - 1 = 5.\nStep 4: 4 - 7 = -3.","steps":["Step 1: 8 - 3 = 5.","Step 2: 5 - 2 = 3.","Step 3: 6 - 1 = 5.","Step 4: 4 - 7 = -3."],"options":[],"conceptId":"math_matrices_matrix_subtraction","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Matrix Subtraction"}', 2),
  (1002, 298, 'Can a 2 × 2 matrix be subtracted from a 2 × 3 matrix?', 'text', 1, 'Compare their orders.', '{"why":"Both matrices must have the same order.","sol":"Step 1: The first matrix has 2 rows and 2 columns.\nStep 2: The second has 2 rows and 3 columns.\nStep 3: Their orders are different.\nStep 4: Therefore subtraction is not defined.","steps":["Step 1: The first matrix has 2 rows and 2 columns.","Step 2: The second has 2 rows and 3 columns.","Step 3: Their orders are different.","Step 4: Therefore subtraction is not defined."],"options":[],"conceptId":"math_matrices_matrix_subtraction","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Matrix Subtraction"}', 3),
  (1003, 299, 'Find 3[[2,4],[3,5]].', 'text', 1, 'Multiply every entry by 3.', '{"why":"A scalar multiplies every element of the matrix.","sol":"Step 1: 3 × 2 = 6.\nStep 2: 3 × 4 = 12.\nStep 3: 3 × 3 = 9.\nStep 4: 3 × 5 = 15.\nStep 5: Keep the results in their original positions.","steps":["Step 1: 3 × 2 = 6.","Step 2: 3 × 4 = 12.","Step 3: 3 × 3 = 9.","Step 4: 3 × 5 = 15.","Step 5: Keep the results in their original positions."],"options":[],"conceptId":"math_matrices_scalar_multiplication","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Scalar Multiplication"}', 0),
  (1004, 299, 'Find -2[[3,-4],[5,1]].', 'text', 1, 'Apply -2 separately to each entry.', '{"why":"The negative scalar changes the sign of positive entries and must also be applied to negative entries.","sol":"Step 1: -2 × 3 = -6.\nStep 2: -2 × (-4) = 8.\nStep 3: -2 × 5 = -10.\nStep 4: -2 × 1 = -2.","steps":["Step 1: -2 × 3 = -6.","Step 2: -2 × (-4) = 8.","Step 3: -2 × 5 = -10.","Step 4: -2 × 1 = -2."],"options":[],"conceptId":"math_matrices_scalar_multiplication","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Scalar Multiplication"}', 1),
  (1005, 299, 'If A is a 2 × 3 matrix, what is the order of 5A?', 'text', 1, 'Scalar multiplication changes values, not dimensions.', '{"why":"Scalar multiplication does not change the order of a matrix.","sol":"Step 1: A has 2 rows and 3 columns.\nStep 2: Multiplying each entry by 5 does not create or remove entries.\nStep 3: Therefore 5A still has 2 rows and 3 columns.","steps":["Step 1: A has 2 rows and 3 columns.","Step 2: Multiplying each entry by 5 does not create or remove entries.","Step 3: Therefore 5A still has 2 rows and 3 columns."],"options":[],"conceptId":"math_matrices_scalar_multiplication","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Scalar Multiplication"}', 2),
  (1006, 299, 'Find 0[[7,-2],[4,9]].', 'text', 1, 'Every number multiplied by zero becomes zero.', '{"why":"Multiplying every element by zero produces the zero matrix.","sol":"Step 1: 0 × 7 = 0.\nStep 2: 0 × (-2) = 0.\nStep 3: 0 × 4 = 0.\nStep 4: 0 × 9 = 0.\nStep 5: Therefore every element becomes zero.","steps":["Step 1: 0 × 7 = 0.","Step 2: 0 × (-2) = 0.","Step 3: 0 × 4 = 0.","Step 4: 0 × 9 = 0.","Step 5: Therefore every element becomes zero."],"options":[],"conceptId":"math_matrices_scalar_multiplication","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Scalar Multiplication"}', 3),
  (1007, 300, 'Find AB where A = [[2,3],[1,5]] and B = [[4,1],[2,3]].', 'text', 1, 'For each answer entry, use a row from A and a column from B.', '{"why":"Each result entry comes from the dot product of a row of A with a column of B.","sol":"Step 1: Top-left: (2×4) + (3×2) = 8 + 6 = 14.\nStep 2: Top-right: (2×1) + (3×3) = 2 + 9 = 11.\nStep 3: Bottom-left: (1×4) + (5×2) = 4 + 10 = 14.\nStep 4: Bottom-right: (1×1) + (5×3) = 1 + 15 = 16.\nStep 5: Therefore AB = [[14,11],[14,16]].","steps":["Step 1: Top-left: (2×4) + (3×2) = 8 + 6 = 14.","Step 2: Top-right: (2×1) + (3×3) = 2 + 9 = 11.","Step 3: Bottom-left: (1×4) + (5×2) = 4 + 10 = 14.","Step 4: Bottom-right: (1×1) + (5×3) = 1 + 15 = 16.","Step 5: Therefore AB = [[14,11],[14,16]]."],"options":[],"conceptId":"math_matrices_matrix_multiplication","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Matrix Multiplication"}', 0),
  (1008, 300, 'Can a 2 × 3 matrix be multiplied by a 2 × 2 matrix?', 'text', 1, 'Compare the columns of the first matrix with the rows of the second.', '{"why":"For AB to exist, the number of columns in A must equal the number of rows in B.","sol":"Step 1: The first matrix has 3 columns.\nStep 2: The second matrix has 2 rows.\nStep 3: The inner dimensions are 3 and 2.\nStep 4: Since 3 is not equal to 2, multiplication is not possible.","steps":["Step 1: The first matrix has 3 columns.","Step 2: The second matrix has 2 rows.","Step 3: The inner dimensions are 3 and 2.","Step 4: Since 3 is not equal to 2, multiplication is not possible."],"options":[],"conceptId":"math_matrices_matrix_multiplication","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Matrix Multiplication"}', 1),
  (1009, 300, 'Find the top-left entry of AB if A = [[1,2,3],[4,5,6]] and B = [[2,1],[0,3],[1,2]].', 'text', 1, 'Use row 1 of A and column 1 of B.', '{"why":"The top-left entry is the dot product of the first row of A and first column of B.","sol":"Step 1: Row 1 of A is [1,2,3].\nStep 2: Column 1 of B is [2,0,1].\nStep 3: Multiply corresponding values: (1×2), (2×0), (3×1).\nStep 4: Add: 2 + 0 + 3 = 5.","steps":["Step 1: Row 1 of A is [1,2,3].","Step 2: Column 1 of B is [2,0,1].","Step 3: Multiply corresponding values: (1×2), (2×0), (3×1).","Step 4: Add: 2 + 0 + 3 = 5."],"options":[],"conceptId":"math_matrices_matrix_multiplication","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Matrix Multiplication"}', 2),
  (1010, 300, 'A student calculates the top-left entry of [[2,3],[1,5]] × [[4,1],[2,3]] as 2 × 4 = 8. What is wrong?', 'text', 1, 'One product is not enough.', '{"why":"Matrix multiplication requires multiplying all corresponding row-column pairs and adding the products.","sol":"Step 1: The top-left entry requires row 1 of the first matrix and column 1 of the second.\nStep 2: Those values are [2,3] and [4,2].\nStep 3: Calculate both products: 2×4 = 8 and 3×2 = 6.\nStep 4: Add the products: 8 + 6 = 14.\nStep 5: Therefore 8 is incomplete.","steps":["Step 1: The top-left entry requires row 1 of the first matrix and column 1 of the second.","Step 2: Those values are [2,3] and [4,2].","Step 3: Calculate both products: 2×4 = 8 and 3×2 = 6.","Step 4: Add the products: 8 + 6 = 14.","Step 5: Therefore 8 is incomplete."],"options":[],"conceptId":"math_matrices_matrix_multiplication","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Matrix Multiplication"}', 3),
  (1011, 301, 'Find the transpose of A = [2 5 7; 1 4 6].', 'text', 1, 'Turn the first row into the first column and the second row into the second column.', '{"why":"Each row of the original matrix becomes the corresponding column of its transpose.","sol":"Step 1: The first row is 2, 5, 7.\nStep 2: Write 2, 5, 7 vertically as the first column.\nStep 3: The second row is 1, 4, 6.\nStep 4: Write 1, 4, 6 vertically as the second column.\nStep 5: Therefore Aᵀ = [2 1; 5 4; 7 6].","steps":["Step 1: The first row is 2, 5, 7.","Step 2: Write 2, 5, 7 vertically as the first column.","Step 3: The second row is 1, 4, 6.","Step 4: Write 1, 4, 6 vertically as the second column.","Step 5: Therefore Aᵀ = [2 1; 5 4; 7 6]."],"options":[],"conceptId":"math_matrices_transpose_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Transpose of a Matrix"}', 0),
  (1012, 301, 'Find the transpose of B = [3 8; 5 1; 7 4].', 'text', 1, 'There are three rows, so each of the three rows becomes a column.', '{"why":"The transpose changes the orientation of every row from horizontal to vertical.","sol":"Step 1: Row 1 is 3, 8, so it becomes column 1.\nStep 2: Row 2 is 5, 1, so it becomes column 2.\nStep 3: Row 3 is 7, 4, so it becomes column 3.\nStep 4: Therefore Bᵀ = [3 5 7; 8 1 4].","steps":["Step 1: Row 1 is 3, 8, so it becomes column 1.","Step 2: Row 2 is 5, 1, so it becomes column 2.","Step 3: Row 3 is 7, 4, so it becomes column 3.","Step 4: Therefore Bᵀ = [3 5 7; 8 1 4]."],"options":[],"conceptId":"math_matrices_transpose_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Transpose of a Matrix"}', 1),
  (1013, 301, 'Find the transpose of C = [-2 4; 6 -5].', 'text', 1, 'Do not change the negative signs. Only move the entries.', '{"why":"Transposition changes positions, not values or signs.","sol":"Step 1: The first row is -2, 4.\nStep 2: It becomes the first column: -2, 4.\nStep 3: The second row is 6, -5.\nStep 4: It becomes the second column: 6, -5.\nStep 5: Therefore Cᵀ = [-2 6; 4 -5].","steps":["Step 1: The first row is -2, 4.","Step 2: It becomes the first column: -2, 4.","Step 3: The second row is 6, -5.","Step 4: It becomes the second column: 6, -5.","Step 5: Therefore Cᵀ = [-2 6; 4 -5]."],"options":[],"conceptId":"math_matrices_transpose_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Transpose of a Matrix"}', 2),
  (1014, 301, 'Find the transpose of D = [1 2 3; 4 5 6; 7 8 9].', 'text', 1, 'Move row 1 to column 1, row 2 to column 2, and row 3 to column 3.', '{"why":"Every row becomes the corresponding column.","sol":"Step 1: Row 1, 1 2 3, becomes column 1.\nStep 2: Row 2, 4 5 6, becomes column 2.\nStep 3: Row 3, 7 8 9, becomes column 3.\nStep 4: Therefore Dᵀ = [1 4 7; 2 5 8; 3 6 9].","steps":["Step 1: Row 1, 1 2 3, becomes column 1.","Step 2: Row 2, 4 5 6, becomes column 2.","Step 3: Row 3, 7 8 9, becomes column 3.","Step 4: Therefore Dᵀ = [1 4 7; 2 5 8; 3 6 9]."],"options":[],"conceptId":"math_matrices_transpose_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Transpose of a Matrix"}', 3),
  (1015, 301, 'A = [4 7; 2 9]. Which matrix is Aᵀ?', 'text', 1, 'The 4 stays in the top-left position. The 7 and 2 exchange their positions.', '{"why":"Transposition swaps the row and column position of each entry.","sol":"Step 1: The first row 4, 7 becomes the first column.\nStep 2: The second row 2, 9 becomes the second column.\nStep 3: So the transpose is [4 2; 7 9].","steps":["Step 1: The first row 4, 7 becomes the first column.","Step 2: The second row 2, 9 becomes the second column.","Step 3: So the transpose is [4 2; 7 9]."],"options":[],"conceptId":"math_matrices_transpose_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q5","subject":"math","chapter":"matrices","topic":"Transpose of a Matrix"}', 4),
  (1016, 302, 'Find A + B if A = [2 5; 7 1] and B = [4 3; 6 8].', 'text', 1, 'Add entries occupying the same positions.', '{"why":"Matrix addition is performed entry-by-entry using corresponding positions.","sol":"Step 1: Top-left: 2 + 4 = 6.\nStep 2: Top-right: 5 + 3 = 8.\nStep 3: Bottom-left: 7 + 6 = 13.\nStep 4: Bottom-right: 1 + 8 = 9.\nStep 5: Therefore A + B = [6 8; 13 9].","steps":["Step 1: Top-left: 2 + 4 = 6.","Step 2: Top-right: 5 + 3 = 8.","Step 3: Bottom-left: 7 + 6 = 13.","Step 4: Bottom-right: 1 + 8 = 9.","Step 5: Therefore A + B = [6 8; 13 9]."],"options":[],"conceptId":"math_matrices_addition_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Addition of Matrices"}', 0),
  (1017, 302, 'Find P + Q if P = [6 -3; -2 5] and Q = [-4 7; 8 -1].', 'text', 1, 'Remember that adding a negative number is ordinary integer addition.', '{"why":"Each corresponding pair of entries is added independently.","sol":"Step 1: 6 + (-4) = 2.\nStep 2: -3 + 7 = 4.\nStep 3: -2 + 8 = 6.\nStep 4: 5 + (-1) = 4.\nStep 5: Therefore P + Q = [2 4; 6 4].","steps":["Step 1: 6 + (-4) = 2.","Step 2: -3 + 7 = 4.","Step 3: -2 + 8 = 6.","Step 4: 5 + (-1) = 4.","Step 5: Therefore P + Q = [2 4; 6 4]."],"options":[],"conceptId":"math_matrices_addition_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Addition of Matrices"}', 1),
  (1018, 302, 'Can [1 2; 3 4] be added to [5 6 7; 8 9 10]?', 'text', 1, 'Compare the sizes of the two matrices.', '{"why":"Two matrices must have the same size before matrix addition is possible.","sol":"Step 1: The first matrix has 2 rows and 2 columns.\nStep 2: The second matrix has 2 rows and 3 columns.\nStep 3: Their sizes are different.\nStep 4: Therefore corresponding positions cannot be matched throughout.\nStep 5: The matrices cannot be added.","steps":["Step 1: The first matrix has 2 rows and 2 columns.","Step 2: The second matrix has 2 rows and 3 columns.","Step 3: Their sizes are different.","Step 4: Therefore corresponding positions cannot be matched throughout.","Step 5: The matrices cannot be added."],"options":[],"conceptId":"math_matrices_addition_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Addition of Matrices"}', 2),
  (1019, 302, 'Find X + Y if X = [1 4 7; 2 5 8] and Y = [3 2 1; 6 4 2].', 'text', 1, 'Add each position separately.', '{"why":"Corresponding entries are added while their positions remain unchanged.","sol":"Step 1: 1 + 3 = 4.\nStep 2: 4 + 2 = 6.\nStep 3: 7 + 1 = 8.\nStep 4: 2 + 6 = 8.\nStep 5: 5 + 4 = 9.\nStep 6: 8 + 2 = 10.\nStep 7: Therefore X + Y = [4 6 8; 8 9 10].","steps":["Step 1: 1 + 3 = 4.","Step 2: 4 + 2 = 6.","Step 3: 7 + 1 = 8.","Step 4: 2 + 6 = 8.","Step 5: 5 + 4 = 9.","Step 6: 8 + 2 = 10.","Step 7: Therefore X + Y = [4 6 8; 8 9 10]."],"options":[],"conceptId":"math_matrices_addition_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Addition of Matrices"}', 3),
  (1020, 303, 'Find A - B if A = [9 7; 5 3] and B = [4 2; 1 6].', 'text', 1, 'Subtract corresponding entries: A entry minus B entry.', '{"why":"Matrix subtraction is performed position by position.","sol":"Step 1: 9 - 4 = 5.\nStep 2: 7 - 2 = 5.\nStep 3: 5 - 1 = 4.\nStep 4: 3 - 6 = -3.\nStep 5: Therefore A - B = [5 5; 4 -3].","steps":["Step 1: 9 - 4 = 5.","Step 2: 7 - 2 = 5.","Step 3: 5 - 1 = 4.","Step 4: 3 - 6 = -3.","Step 5: Therefore A - B = [5 5; 4 -3]."],"options":[],"conceptId":"math_matrices_subtraction_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Subtraction of Matrices"}', 0),
  (1021, 303, 'Find P - Q if P = [6 -2; -4 7] and Q = [-3 5; 2 -1].', 'text', 1, 'Be especially careful when subtracting negative numbers.', '{"why":"The subtraction follows the order P minus Q at every corresponding position.","sol":"Step 1: 6 - (-3) = 9.\nStep 2: -2 - 5 = -7.\nStep 3: -4 - 2 = -6.\nStep 4: 7 - (-1) = 8.\nStep 5: Therefore P - Q = [9 -7; -6 8].","steps":["Step 1: 6 - (-3) = 9.","Step 2: -2 - 5 = -7.","Step 3: -4 - 2 = -6.","Step 4: 7 - (-1) = 8.","Step 5: Therefore P - Q = [9 -7; -6 8]."],"options":[],"conceptId":"math_matrices_subtraction_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Subtraction of Matrices"}', 1),
  (1022, 303, 'Using A = [8 5; 3 1] and B = [2 4; 6 7], find A - B.', 'text', 1, 'Keep A first throughout the calculation.', '{"why":"Changing the order of subtraction changes the signs of the corresponding differences.","sol":"Step 1: 8 - 2 = 6.\nStep 2: 5 - 4 = 1.\nStep 3: 3 - 6 = -3.\nStep 4: 1 - 7 = -6.\nStep 5: Therefore A - B = [6 1; -3 -6].","steps":["Step 1: 8 - 2 = 6.","Step 2: 5 - 4 = 1.","Step 3: 3 - 6 = -3.","Step 4: 1 - 7 = -6.","Step 5: Therefore A - B = [6 1; -3 -6]."],"options":[],"conceptId":"math_matrices_subtraction_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Subtraction of Matrices"}', 2),
  (1023, 303, 'Can a 2 × 2 matrix be subtracted from a 2 × 3 matrix?', 'text', 1, 'Check whether the two matrices have the same size.', '{"why":"Matrices must have the same size for subtraction.","sol":"Step 1: The first matrix has 2 rows and 2 columns.\nStep 2: The second matrix has 2 rows and 3 columns.\nStep 3: Their sizes are different.\nStep 4: Therefore matrix subtraction is not defined.","steps":["Step 1: The first matrix has 2 rows and 2 columns.","Step 2: The second matrix has 2 rows and 3 columns.","Step 3: Their sizes are different.","Step 4: Therefore matrix subtraction is not defined."],"options":[],"conceptId":"math_matrices_subtraction_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Subtraction of Matrices"}', 3),
  (1024, 304, 'Find 3A if A = [2 4; 5 1].', 'text', 1, 'Multiply every entry by 3.', '{"why":"Scalar multiplication applies the scalar to every entry of the matrix.","sol":"Step 1: 3 × 2 = 6.\nStep 2: 3 × 4 = 12.\nStep 3: 3 × 5 = 15.\nStep 4: 3 × 1 = 3.\nStep 5: Therefore 3A = [6 12; 15 3].","steps":["Step 1: 3 × 2 = 6.","Step 2: 3 × 4 = 12.","Step 3: 3 × 5 = 15.","Step 4: 3 × 1 = 3.","Step 5: Therefore 3A = [6 12; 15 3]."],"options":[],"conceptId":"math_matrices_scalar_multiplication_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Scalar Multiplication of a Matrix"}', 0),
  (1025, 304, 'Find -2B if B = [3 -4; -5 2].', 'text', 1, 'Multiply each entry by -2 and carefully handle the signs.', '{"why":"The negative scalar changes the sign of each non-zero entry according to multiplication rules.","sol":"Step 1: -2 × 3 = -6.\nStep 2: -2 × (-4) = 8.\nStep 3: -2 × (-5) = 10.\nStep 4: -2 × 2 = -4.\nStep 5: Therefore -2B = [-6 8; 10 -4].","steps":["Step 1: -2 × 3 = -6.","Step 2: -2 × (-4) = 8.","Step 3: -2 × (-5) = 10.","Step 4: -2 × 2 = -4.","Step 5: Therefore -2B = [-6 8; 10 -4]."],"options":[],"conceptId":"math_matrices_scalar_multiplication_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Scalar Multiplication of a Matrix"}', 1),
  (1026, 304, 'Find 1/2 C if C = [6 10; 4 8].', 'text', 1, 'Half of each entry is the same as multiplying each entry by 1/2.', '{"why":"A scalar multiplies every entry independently.","sol":"Step 1: Half of 6 is 3.\nStep 2: Half of 10 is 5.\nStep 3: Half of 4 is 2.\nStep 4: Half of 8 is 4.\nStep 5: Therefore 1/2 C = [3 5; 2 4].","steps":["Step 1: Half of 6 is 3.","Step 2: Half of 10 is 5.","Step 3: Half of 4 is 2.","Step 4: Half of 8 is 4.","Step 5: Therefore 1/2 C = [3 5; 2 4]."],"options":[],"conceptId":"math_matrices_scalar_multiplication_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Scalar Multiplication of a Matrix"}', 2),
  (1027, 304, 'Find 4D if D = [1 -2 3; 0 5 -1].', 'text', 1, 'There are six entries, so all six must be multiplied by 4.', '{"why":"Every entry receives the same scalar multiplication.","sol":"Step 1: 4 × 1 = 4.\nStep 2: 4 × (-2) = -8.\nStep 3: 4 × 3 = 12.\nStep 4: 4 × 0 = 0.\nStep 5: 4 × 5 = 20.\nStep 6: 4 × (-1) = -4.\nStep 7: Therefore 4D = [4 -8 12; 0 20 -4].","steps":["Step 1: 4 × 1 = 4.","Step 2: 4 × (-2) = -8.","Step 3: 4 × 3 = 12.","Step 4: 4 × 0 = 0.","Step 5: 4 × 5 = 20.","Step 6: 4 × (-1) = -4.","Step 7: Therefore 4D = [4 -8 12; 0 20 -4]."],"options":[],"conceptId":"math_matrices_scalar_multiplication_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Scalar Multiplication of a Matrix"}', 3),
  (1028, 305, 'Find AB if A = [2 3; 1 4] and B = [5 2; 6 1].', 'text', 1, 'For each answer position, use a row from A and a column from B.', '{"why":"Each entry is formed by multiplying corresponding entries of one row and one column, then adding the products.","sol":"Step 1: Top-left: (2 × 5) + (3 × 6) = 10 + 18 = 28.\nStep 2: Top-right: (2 × 2) + (3 × 1) = 4 + 3 = 7.\nStep 3: Bottom-left: (1 × 5) + (4 × 6) = 5 + 24 = 29.\nStep 4: Bottom-right: (1 × 2) + (4 × 1) = 2 + 4 = 6.\nStep 5: Therefore AB = [28 7; 29 6].","steps":["Step 1: Top-left: (2 × 5) + (3 × 6) = 10 + 18 = 28.","Step 2: Top-right: (2 × 2) + (3 × 1) = 4 + 3 = 7.","Step 3: Bottom-left: (1 × 5) + (4 × 6) = 5 + 24 = 29.","Step 4: Bottom-right: (1 × 2) + (4 × 1) = 2 + 4 = 6.","Step 5: Therefore AB = [28 7; 29 6]."],"options":[],"conceptId":"math_matrices_multiplication_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Multiplication of Matrices"}', 0),
  (1029, 305, 'Find the top-left entry of AB if A = [4 1; 2 3] and B = [7 5; 6 8].', 'text', 1, 'Use row 1 of A and column 1 of B.', '{"why":"A matrix product entry is obtained from a row-column multiplication.","sol":"Step 1: Row 1 of A is [4 1].\nStep 2: Column 1 of B is [7; 6].\nStep 3: Multiply: 4 × 7 = 28 and 1 × 6 = 6.\nStep 4: Add: 28 + 6 = 34.\nStep 5: Therefore the top-left entry is 34.","steps":["Step 1: Row 1 of A is [4 1].","Step 2: Column 1 of B is [7; 6].","Step 3: Multiply: 4 × 7 = 28 and 1 × 6 = 6.","Step 4: Add: 28 + 6 = 34.","Step 5: Therefore the top-left entry is 34."],"options":[],"conceptId":"math_matrices_multiplication_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Multiplication of Matrices"}', 1),
  (1030, 305, 'Find AB if A = [3 2; 1 4] and B = [5; 6].', 'text', 1, 'There is only one column in B, so each row of A produces one answer.', '{"why":"Each row of A is combined with the single column of B.","sol":"Step 1: First row: (3 × 5) + (2 × 6) = 15 + 12 = 27.\nStep 2: Second row: (1 × 5) + (4 × 6) = 5 + 24 = 29.\nStep 3: Therefore AB = [27; 29].","steps":["Step 1: First row: (3 × 5) + (2 × 6) = 15 + 12 = 27.","Step 2: Second row: (1 × 5) + (4 × 6) = 5 + 24 = 29.","Step 3: Therefore AB = [27; 29]."],"options":[],"conceptId":"math_matrices_multiplication_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Multiplication of Matrices"}', 2),
  (1031, 305, 'Can A = [1 2 3; 4 5 6] be multiplied by B = [7 8; 9 10] in the order AB?', 'text', 1, 'Compare the number of columns in A with the number of rows in B.', '{"why":"Matrix multiplication requires the number of columns of the first matrix to equal the number of rows of the second matrix.","sol":"Step 1: A has 3 columns.\nStep 2: B has 2 rows.\nStep 3: For AB to exist, these two numbers must be equal.\nStep 4: Since 3 is not equal to 2, AB cannot be formed.","steps":["Step 1: A has 3 columns.","Step 2: B has 2 rows.","Step 3: For AB to exist, these two numbers must be equal.","Step 4: Since 3 is not equal to 2, AB cannot be formed."],"options":[],"conceptId":"math_matrices_multiplication_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Multiplication of Matrices"}', 3),
  (1032, 306, 'Find the determinant of A = [3 2; 5 4].', 'text', 1, 'Use ad - bc.', '{"why":"For a 2 × 2 matrix [a b; c d], the determinant is ad - bc.","sol":"Step 1: Multiply the main diagonal: 3 × 4 = 12.\nStep 2: Multiply the other diagonal: 2 × 5 = 10.\nStep 3: Subtract: 12 - 10 = 2.\nStep 4: Therefore det(A) = 2.","steps":["Step 1: Multiply the main diagonal: 3 × 4 = 12.","Step 2: Multiply the other diagonal: 2 × 5 = 10.","Step 3: Subtract: 12 - 10 = 2.","Step 4: Therefore det(A) = 2."],"options":[],"conceptId":"math_matrices_determinant_of_a_2_2_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Determinant of a 2 × 2 Matrix"}', 0),
  (1033, 306, 'Find the determinant of B = [2 7; 5 3].', 'text', 1, 'Calculate 2 × 3 first, then subtract 7 × 5.', '{"why":"The determinant uses the difference between the two diagonal products.","sol":"Step 1: 2 × 3 = 6.\nStep 2: 7 × 5 = 35.\nStep 3: 6 - 35 = -29.\nStep 4: Therefore det(B) = -29.","steps":["Step 1: 2 × 3 = 6.","Step 2: 7 × 5 = 35.","Step 3: 6 - 35 = -29.","Step 4: Therefore det(B) = -29."],"options":[],"conceptId":"math_matrices_determinant_of_a_2_2_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Determinant of a 2 × 2 Matrix"}', 1),
  (1034, 306, 'Find the determinant of C = [-2 4; 3 -5].', 'text', 1, 'Be careful with the two negative entries.', '{"why":"The negative signs are handled during ordinary multiplication before the final subtraction.","sol":"Step 1: (-2) × (-5) = 10.\nStep 2: 4 × 3 = 12.\nStep 3: 10 - 12 = -2.\nStep 4: Therefore det(C) = -2.","steps":["Step 1: (-2) × (-5) = 10.","Step 2: 4 × 3 = 12.","Step 3: 10 - 12 = -2.","Step 4: Therefore det(C) = -2."],"options":[],"conceptId":"math_matrices_determinant_of_a_2_2_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Determinant of a 2 × 2 Matrix"}', 2),
  (1035, 306, 'Find the determinant of D = [2 4; 1 2].', 'text', 1, 'Multiply the two diagonal pairs and subtract.', '{"why":"The two diagonal products are equal, so their difference is zero.","sol":"Step 1: 2 × 2 = 4.\nStep 2: 4 × 1 = 4.\nStep 3: 4 - 4 = 0.\nStep 4: Therefore det(D) = 0.","steps":["Step 1: 2 × 2 = 4.","Step 2: 4 × 1 = 4.","Step 3: 4 - 4 = 0.","Step 4: Therefore det(D) = 0."],"options":[],"conceptId":"math_matrices_determinant_of_a_2_2_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Determinant of a 2 × 2 Matrix"}', 3),
  (1036, 306, 'Which calculation gives the determinant of [5 2; 3 4]?', 'text', 1, 'Identify a, b, c and d before applying ad - bc.', '{"why":"The determinant is ad - bc, so the second diagonal product must be subtracted.","sol":"Step 1: a = 5, b = 2, c = 3, d = 4.\nStep 2: ad = 5 × 4 = 20.\nStep 3: bc = 2 × 3 = 6.\nStep 4: Therefore det(A) = 20 - 6 = 14.","steps":["Step 1: a = 5, b = 2, c = 3, d = 4.","Step 2: ad = 5 × 4 = 20.","Step 3: bc = 2 × 3 = 6.","Step 4: Therefore det(A) = 20 - 6 = 14."],"options":[],"conceptId":"math_matrices_determinant_of_a_2_2_matrix","skillId":"math_matrices","subskillId":"math_matrices_q5","subject":"math","chapter":"matrices","topic":"Determinant of a 2 × 2 Matrix"}', 4),
  (1037, 307, 'Find the determinant of A = [1 2 3; 0 4 5; 1 0 6].', 'text', 1, 'Expand along the first row using the signs +, -, +.', '{"why":"The determinant is obtained by expanding along the first row and calculating each 2 × 2 minor.","sol":"Step 1: First minor: (4 × 6) - (5 × 0) = 24.\nStep 2: First contribution: 1 × 24 = 24.\nStep 3: Second minor: (0 × 6) - (5 × 1) = -5.\nStep 4: Second contribution: -2 × (-5) = 10.\nStep 5: Third minor: (0 × 0) - (4 × 1) = -4.\nStep 6: Third contribution: 3 × (-4) = -12.\nStep 7: det(A) = 24 + 10 - 12 = 22.","steps":["Step 1: First minor: (4 × 6) - (5 × 0) = 24.","Step 2: First contribution: 1 × 24 = 24.","Step 3: Second minor: (0 × 6) - (5 × 1) = -5.","Step 4: Second contribution: -2 × (-5) = 10.","Step 5: Third minor: (0 × 0) - (4 × 1) = -4.","Step 6: Third contribution: 3 × (-4) = -12.","Step 7: det(A) = 24 + 10 - 12 = 22."],"options":[],"conceptId":"math_matrices_determinant_of_a_3_3_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Determinant of a 3 × 3 Matrix"}', 0),
  (1038, 307, 'Find the determinant of B = [2 0 1; 3 4 5; 1 2 6].', 'text', 1, 'The middle first-row entry is zero, so its entire contribution is zero.', '{"why":"Each first-row entry is combined with the determinant of the 2 × 2 matrix left after removing its row and column.","sol":"Step 1: First minor: (4 × 6) - (5 × 2) = 14.\nStep 2: First contribution: 2 × 14 = 28.\nStep 3: Second contribution: 0.\nStep 4: Third minor: (3 × 2) - (4 × 1) = 2.\nStep 5: Third contribution: 1 × 2 = 2.\nStep 6: det(B) = 28 + 0 + 2 = 30.","steps":["Step 1: First minor: (4 × 6) - (5 × 2) = 14.","Step 2: First contribution: 2 × 14 = 28.","Step 3: Second contribution: 0.","Step 4: Third minor: (3 × 2) - (4 × 1) = 2.","Step 5: Third contribution: 1 × 2 = 2.","Step 6: det(B) = 28 + 0 + 2 = 30."],"options":[],"conceptId":"math_matrices_determinant_of_a_3_3_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Determinant of a 3 × 3 Matrix"}', 1),
  (1039, 307, 'Find the determinant of C = [1 2 0; 3 4 5; 6 7 8].', 'text', 1, 'Use +, -, + across the first row.', '{"why":"The signs in the first-row expansion are positive, negative, positive.","sol":"Step 1: First contribution: 1[(4 × 8) - (5 × 7)] = -3.\nStep 2: Second contribution: -2[(3 × 8) - (5 × 6)] = -2(-6) = 12.\nStep 3: Third contribution is zero.\nStep 4: det(C) = -3 + 12 = 9.","steps":["Step 1: First contribution: 1[(4 × 8) - (5 × 7)] = -3.","Step 2: Second contribution: -2[(3 × 8) - (5 × 6)] = -2(-6) = 12.","Step 3: Third contribution is zero.","Step 4: det(C) = -3 + 12 = 9."],"options":[],"conceptId":"math_matrices_determinant_of_a_3_3_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Determinant of a 3 × 3 Matrix"}', 2),
  (1040, 308, 'Determine whether A = [2 4; 1 2] is singular or non-singular.', 'text', 1, 'Find the determinant first.', '{"why":"A square matrix is singular when its determinant is zero.","sol":"Step 1: det(A) = (2 × 2) - (4 × 1).\nStep 2: det(A) = 4 - 4 = 0.\nStep 3: A determinant of zero means the matrix is singular.","steps":["Step 1: det(A) = (2 × 2) - (4 × 1).","Step 2: det(A) = 4 - 4 = 0.","Step 3: A determinant of zero means the matrix is singular."],"options":[],"conceptId":"math_matrices_singular_and_non_singular_matrices","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Singular and Non-Singular Matrices"}', 0),
  (1041, 308, 'Determine whether B = [3 2; 5 4] is singular or non-singular.', 'text', 1, 'Calculate 3 × 4 - 2 × 5.', '{"why":"A non-zero determinant means the matrix is non-singular.","sol":"Step 1: det(B) = (3 × 4) - (2 × 5).\nStep 2: det(B) = 12 - 10 = 2.\nStep 3: 2 is not zero.\nStep 4: Therefore B is non-singular.","steps":["Step 1: det(B) = (3 × 4) - (2 × 5).","Step 2: det(B) = 12 - 10 = 2.","Step 3: 2 is not zero.","Step 4: Therefore B is non-singular."],"options":[],"conceptId":"math_matrices_singular_and_non_singular_matrices","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Singular and Non-Singular Matrices"}', 1),
  (1042, 308, 'Find x if [x 2; 3 6] is singular.', 'text', 1, 'Set the determinant equal to zero.', '{"why":"Singularity requires the determinant to equal zero.","sol":"Step 1: det(A) = (x × 6) - (2 × 3).\nStep 2: 6x - 6 = 0.\nStep 3: 6x = 6.\nStep 4: x = 1.","steps":["Step 1: det(A) = (x × 6) - (2 × 3).","Step 2: 6x - 6 = 0.","Step 3: 6x = 6.","Step 4: x = 1."],"options":[],"conceptId":"math_matrices_singular_and_non_singular_matrices","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Singular and Non-Singular Matrices"}', 2),
  (1043, 308, 'Find x if [x 1; 2 3] is singular.', 'text', 1, 'Set 3x - 2 equal to zero.', '{"why":"The value of x must make the determinant equal to zero.","sol":"Step 1: det(A) = 3x - 2.\nStep 2: 3x - 2 = 0.\nStep 3: 3x = 2.\nStep 4: x = 2/3.","steps":["Step 1: det(A) = 3x - 2.","Step 2: 3x - 2 = 0.","Step 3: 3x = 2.","Step 4: x = 2/3."],"options":[],"conceptId":"math_matrices_singular_and_non_singular_matrices","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Singular and Non-Singular Matrices"}', 3),
  (1044, 309, 'Find the inverse of A = [3 2; 1 4].', 'text', 1, 'First calculate the determinant.', '{"why":"The inverse of a 2 × 2 matrix follows the fixed inverse formula.","sol":"Step 1: det(A) = 3 × 4 - 2 × 1 = 10.\nStep 2: Swap 3 and 4.\nStep 3: Change 2 to -2 and 1 to -1.\nStep 4: Multiply the resulting matrix by 1/10.\nStep 5: A⁻¹ = [2/5 -1/5; -1/10 3/10].","steps":["Step 1: det(A) = 3 × 4 - 2 × 1 = 10.","Step 2: Swap 3 and 4.","Step 3: Change 2 to -2 and 1 to -1.","Step 4: Multiply the resulting matrix by 1/10.","Step 5: A⁻¹ = [2/5 -1/5; -1/10 3/10]."],"options":[],"conceptId":"math_matrices_inverse_of_a_2_2_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Inverse of a 2 × 2 Matrix"}', 0),
  (1045, 309, 'Find the inverse of B = [2 1; 5 3].', 'text', 1, 'The determinant is 1.', '{"why":"The determinant is 1, so the reciprocal factor is also 1.","sol":"Step 1: det(B) = 2 × 3 - 1 × 5 = 1.\nStep 2: Swap 2 and 3.\nStep 3: Change 1 to -1 and 5 to -5.\nStep 4: Multiply by 1/1.\nStep 5: B⁻¹ = [3 -1; -5 2].","steps":["Step 1: det(B) = 2 × 3 - 1 × 5 = 1.","Step 2: Swap 2 and 3.","Step 3: Change 1 to -1 and 5 to -5.","Step 4: Multiply by 1/1.","Step 5: B⁻¹ = [3 -1; -5 2]."],"options":[],"conceptId":"math_matrices_inverse_of_a_2_2_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Inverse of a 2 × 2 Matrix"}', 1),
  (1046, 309, 'Does C = [2 4; 1 2] have an inverse?', 'text', 1, 'Calculate its determinant.', '{"why":"A 2 × 2 matrix cannot have an inverse when its determinant is zero.","sol":"Step 1: det(C) = 2 × 2 - 4 × 1.\nStep 2: det(C) = 0.\nStep 3: An inverse requires a non-zero determinant.\nStep 4: Therefore C has no inverse.","steps":["Step 1: det(C) = 2 × 2 - 4 × 1.","Step 2: det(C) = 0.","Step 3: An inverse requires a non-zero determinant.","Step 4: Therefore C has no inverse."],"options":[],"conceptId":"math_matrices_inverse_of_a_2_2_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Inverse of a 2 × 2 Matrix"}', 2),
  (1047, 309, 'Find the inverse of D = [4 1; 2 1].', 'text', 1, 'The determinant is 2.', '{"why":"The inverse is obtained by rearranging the entries and multiplying by the reciprocal of the determinant.","sol":"Step 1: det(D) = 4 × 1 - 1 × 2 = 2.\nStep 2: Swap 4 and 1.\nStep 3: Change 1 to -1 and 2 to -2.\nStep 4: Multiply by 1/2.\nStep 5: D⁻¹ = [1/2 -1/2; -1 2].","steps":["Step 1: det(D) = 4 × 1 - 1 × 2 = 2.","Step 2: Swap 4 and 1.","Step 3: Change 1 to -1 and 2 to -2.","Step 4: Multiply by 1/2.","Step 5: D⁻¹ = [1/2 -1/2; -1 2]."],"options":[],"conceptId":"math_matrices_inverse_of_a_2_2_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Inverse of a 2 × 2 Matrix"}', 3),
  (1048, 310, 'Find X if X + [2 3; 4 5] = [7 9; 10 12].', 'text', 1, 'Subtract the known matrix from both sides.', '{"why":"Subtracting the known matrix isolates X.","sol":"Step 1: 7 - 2 = 5.\nStep 2: 9 - 3 = 6.\nStep 3: 10 - 4 = 6.\nStep 4: 12 - 5 = 7.\nStep 5: Therefore X = [5 6; 6 7].","steps":["Step 1: 7 - 2 = 5.","Step 2: 9 - 3 = 6.","Step 3: 10 - 4 = 6.","Step 4: 12 - 5 = 7.","Step 5: Therefore X = [5 6; 6 7]."],"options":[],"conceptId":"math_matrices_solving_matrix_equations","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Solving Matrix Equations"}', 0),
  (1049, 310, 'Find X if 3X = [12 15; 9 18].', 'text', 1, 'Divide every entry by 3.', '{"why":"The scalar 3 affects every entry, so every entry is divided by 3 to isolate X.","sol":"Step 1: 12 ÷ 3 = 4.\nStep 2: 15 ÷ 3 = 5.\nStep 3: 9 ÷ 3 = 3.\nStep 4: 18 ÷ 3 = 6.\nStep 5: Therefore X = [4 5; 3 6].","steps":["Step 1: 12 ÷ 3 = 4.","Step 2: 15 ÷ 3 = 5.","Step 3: 9 ÷ 3 = 3.","Step 4: 18 ÷ 3 = 6.","Step 5: Therefore X = [4 5; 3 6]."],"options":[],"conceptId":"math_matrices_solving_matrix_equations","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Solving Matrix Equations"}', 1),
  (1050, 310, 'Find X if X - [3 1; 2 4] = [5 7; 8 6].', 'text', 1, 'Add the known matrix to both sides.', '{"why":"Adding the subtracted matrix reverses the subtraction and isolates X.","sol":"Step 1: 5 + 3 = 8.\nStep 2: 7 + 1 = 8.\nStep 3: 8 + 2 = 10.\nStep 4: 6 + 4 = 10.\nStep 5: Therefore X = [8 8; 10 10].","steps":["Step 1: 5 + 3 = 8.","Step 2: 7 + 1 = 8.","Step 3: 8 + 2 = 10.","Step 4: 6 + 4 = 10.","Step 5: Therefore X = [8 8; 10 10]."],"options":[],"conceptId":"math_matrices_solving_matrix_equations","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Solving Matrix Equations"}', 2),
  (1051, 310, 'Find x and y if [x 4; 7 y] + [3 2; 1 5] = [8 6; 8 12].', 'text', 1, 'Use the top-left position to find x and the bottom-right position to find y.', '{"why":"Each unknown is determined by comparing the corresponding entries.","sol":"Step 1: Top-left: x + 3 = 8.\nStep 2: Therefore x = 5.\nStep 3: Bottom-right: y + 5 = 12.\nStep 4: Therefore y = 7.","steps":["Step 1: Top-left: x + 3 = 8.","Step 2: Therefore x = 5.","Step 3: Bottom-right: y + 5 = 12.","Step 4: Therefore y = 7."],"options":[],"conceptId":"math_matrices_solving_matrix_equations","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Solving Matrix Equations"}', 3),
  (1052, 311, 'Find the vector AB if A(2,3) and B(7,5).', 'text', 1, 'Final point minus starting point.', '{"why":"The vector from A to B is found by subtracting the coordinates of A from the coordinates of B.","sol":"Step 1: Starting point A = (2,3)\nStep 2: Final point B = (7,5)\nStep 3: Subtract x-coordinates: 7 - 2 = 5\nStep 4: Subtract y-coordinates: 5 - 3 = 2\nStep 5: Therefore AB = (5,2)","steps":["Step 1: Starting point A = (2,3)","Step 2: Final point B = (7,5)","Step 3: Subtract x-coordinates: 7 - 2 = 5","Step 4: Subtract y-coordinates: 5 - 3 = 2","Step 5: Therefore AB = (5,2)"],"options":[],"conceptId":"math_vectors_vector_from_one_point_to_another","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Vector From One Point to Another"}', 0),
  (1053, 311, 'Find the vector PQ if P(-3,4) and Q(2,-1).', 'text', 1, 'Subtract P from Q.', '{"why":"Vector PQ describes the movement from P to Q.","sol":"Step 1: Starting point P = (-3,4)\nStep 2: Final point Q = (2,-1)\nStep 3: x-component: 2 - (-3) = 5\nStep 4: y-component: -1 - 4 = -5\nStep 5: Therefore PQ = (5,-5)","steps":["Step 1: Starting point P = (-3,4)","Step 2: Final point Q = (2,-1)","Step 3: x-component: 2 - (-3) = 5","Step 4: y-component: -1 - 4 = -5","Step 5: Therefore PQ = (5,-5)"],"options":[],"conceptId":"math_vectors_vector_from_one_point_to_another","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Vector From One Point to Another"}', 1),
  (1054, 311, 'Find the vector CD if C(6,-2) and D(1,4).', 'text', 1, 'Use final point minus starting point.', '{"why":"Subtracting the starting coordinates from the final coordinates gives the vector.","sol":"Step 1: Starting point C = (6,-2)\nStep 2: Final point D = (1,4)\nStep 3: x-component: 1 - 6 = -5\nStep 4: y-component: 4 - (-2) = 6\nStep 5: Therefore CD = (-5,6)","steps":["Step 1: Starting point C = (6,-2)","Step 2: Final point D = (1,4)","Step 3: x-component: 1 - 6 = -5","Step 4: y-component: 4 - (-2) = 6","Step 5: Therefore CD = (-5,6)"],"options":[],"conceptId":"math_vectors_vector_from_one_point_to_another","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Vector From One Point to Another"}', 2),
  (1055, 311, 'If A(2,3) and B(7,5), find BA.', 'text', 1, 'BA moves from B back to A.', '{"why":"Reversing the direction of a vector changes the signs of both components.","sol":"Step 1: Starting point B = (7,5)\nStep 2: Final point A = (2,3)\nStep 3: x-component: 2 - 7 = -5\nStep 4: y-component: 3 - 5 = -2\nStep 5: Therefore BA = (-5,-2)","steps":["Step 1: Starting point B = (7,5)","Step 2: Final point A = (2,3)","Step 3: x-component: 2 - 7 = -5","Step 4: y-component: 3 - 5 = -2","Step 5: Therefore BA = (-5,-2)"],"options":[],"conceptId":"math_vectors_vector_from_one_point_to_another","skillId":"math_vectors","subskillId":"math_vectors_q4","subject":"math","chapter":"vectors","topic":"Vector From One Point to Another"}', 3),
  (1056, 311, 'If AB = (4,-3), what is BA?', 'text', 1, 'The reverse vector is the negative of the original.', '{"why":"BA = -AB, so reversing a vector changes the signs of both components.","sol":"Step 1: AB = (4,-3)\nStep 2: Reverse the direction\nStep 3: Change both signs\nStep 4: BA = (-4,3)","steps":["Step 1: AB = (4,-3)","Step 2: Reverse the direction","Step 3: Change both signs","Step 4: BA = (-4,3)"],"options":[],"conceptId":"math_vectors_vector_from_one_point_to_another","skillId":"math_vectors","subskillId":"math_vectors_q5","subject":"math","chapter":"vectors","topic":"Vector From One Point to Another"}', 4),
  (1057, 311, 'A point A is (1,2). A vector AB is (5,3). Find the coordinates of B.', 'text', 1, 'Move from A by the vector AB.', '{"why":"The vector tells us how far and in which direction to move from A to reach B.","sol":"Step 1: Start at A = (1,2)\nStep 2: Add the x-component: 1 + 5 = 6\nStep 3: Add the y-component: 2 + 3 = 5\nStep 4: Therefore B = (6,5)","steps":["Step 1: Start at A = (1,2)","Step 2: Add the x-component: 1 + 5 = 6","Step 3: Add the y-component: 2 + 3 = 5","Step 4: Therefore B = (6,5)"],"options":[],"conceptId":"math_vectors_vector_from_one_point_to_another","skillId":"math_vectors","subskillId":"math_vectors_q6","subject":"math","chapter":"vectors","topic":"Vector From One Point to Another"}', 5),
  (1058, 312, 'In the directed line segment A → B, which point is the starting point?', 'text', 1, 'Follow the direction of the arrow.', '{"why":"The starting point is where the vector begins before following the arrow.","sol":"Step 1: The arrow points from A toward B.\nStep 2: Therefore the vector begins at A.\nStep 3: A is the starting point.","steps":["Step 1: The arrow points from A toward B.","Step 2: Therefore the vector begins at A.","Step 3: A is the starting point."],"options":[],"conceptId":"math_vectors_a_vector_as_a_directed_line_segment","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"A Vector as a Directed Line Segment"}', 0),
  (1059, 312, 'In P ← Q, which point is the starting point?', 'text', 1, 'The arrow points toward P.', '{"why":"The arrowhead shows the direction of movement, so the vector starts at Q.","sol":"Step 1: The arrowhead points toward P.\nStep 2: Therefore the vector is moving from Q toward P.\nStep 3: The vector starts at Q.","steps":["Step 1: The arrowhead points toward P.","Step 2: Therefore the vector is moving from Q toward P.","Step 3: The vector starts at Q."],"options":[],"conceptId":"math_vectors_a_vector_as_a_directed_line_segment","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"A Vector as a Directed Line Segment"}', 1),
  (1060, 312, 'Two directed line segments have equal lengths but point in opposite directions. Are they the same vector?', 'text', 1, 'A vector needs both magnitude and direction.', '{"why":"Equal magnitude alone is not enough; vectors must also have the same direction.","sol":"Step 1: Equal lengths mean equal magnitudes.\nStep 2: However, the directions are opposite.\nStep 3: Therefore the vectors are not the same.","steps":["Step 1: Equal lengths mean equal magnitudes.","Step 2: However, the directions are opposite.","Step 3: Therefore the vectors are not the same."],"options":[],"conceptId":"math_vectors_a_vector_as_a_directed_line_segment","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"A Vector as a Directed Line Segment"}', 2),
  (1061, 313, 'A vector moves from A to B. Write its vector notation.', 'text', 1, 'Write the starting point first.', '{"why":"The notation ⃗AB represents movement from A to B.","sol":"Step 1: The vector starts at A.\nStep 2: It ends at B.\nStep 3: Write the starting point first and ending point second.","steps":["Step 1: The vector starts at A.","Step 2: It ends at B.","Step 3: Write the starting point first and ending point second."],"options":[],"conceptId":"math_vectors_vector_notation","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Vector Notation"}', 0),
  (1062, 313, 'A vector moves from X to Y. Which notation represents it: ⃗XY or ⃗YX?', 'text', 1, 'The first letter must be the starting point.', '{"why":"The order of the letters records the direction.","sol":"Step 1: The vector starts at X.\nStep 2: The vector ends at Y.\nStep 3: Therefore X must come first.","steps":["Step 1: The vector starts at X.","Step 2: The vector ends at Y.","Step 3: Therefore X must come first."],"options":[],"conceptId":"math_vectors_vector_notation","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Vector Notation"}', 1),
  (1063, 313, 'What does ⃗PQ mean?', 'text', 1, 'Read the letters from left to right.', '{"why":"Two-point vector notation records the starting point followed by the ending point.","sol":"Step 1: The first letter is P.\nStep 2: The second letter is Q.\nStep 3: Therefore the vector starts at P and ends at Q.","steps":["Step 1: The first letter is P.","Step 2: The second letter is Q.","Step 3: Therefore the vector starts at P and ends at Q."],"options":[],"conceptId":"math_vectors_vector_notation","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Vector Notation"}', 2),
  (1064, 314, 'A vector starts at P and ends at Q. Name it.', 'text', 1, 'Put the starting point first.', '{"why":"A vector is named by writing its initial point followed by its terminal point.","sol":"Step 1: Starting point = P.\nStep 2: Ending point = Q.\nStep 3: Therefore the vector is ⃗PQ.","steps":["Step 1: Starting point = P.","Step 2: Ending point = Q.","Step 3: Therefore the vector is ⃗PQ."],"options":[],"conceptId":"math_vectors_naming_a_vector_from_its_initial_and_terminal_points","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Naming a Vector from Its Initial and Terminal Points"}', 0),
  (1065, 314, 'A vector starts at X and ends at Y. A student writes ⃗YX. Is this correct?', 'text', 1, 'Compare the order with the actual direction.', '{"why":"⃗YX represents movement from Y to X, which is the opposite direction.","sol":"Step 1: The vector starts at X.\nStep 2: The vector ends at Y.\nStep 3: The correct order is X then Y.\nStep 4: Therefore ⃗XY is correct, not ⃗YX.","steps":["Step 1: The vector starts at X.","Step 2: The vector ends at Y.","Step 3: The correct order is X then Y.","Step 4: Therefore ⃗XY is correct, not ⃗YX."],"options":[],"conceptId":"math_vectors_naming_a_vector_from_its_initial_and_terminal_points","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Naming a Vector from Its Initial and Terminal Points"}', 1),
  (1066, 314, 'In the directed segment B ← A, what is the vector name?', 'text', 1, 'The arrow points toward B.', '{"why":"The arrow determines the direction, not the position of the letters on the page.","sol":"Step 1: The arrowhead is at B.\nStep 2: Therefore the vector moves from A to B.\nStep 3: Write A first and B second.","steps":["Step 1: The arrowhead is at B.","Step 2: Therefore the vector moves from A to B.","Step 3: Write A first and B second."],"options":[],"conceptId":"math_vectors_naming_a_vector_from_its_initial_and_terminal_points","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Naming a Vector from Its Initial and Terminal Points"}', 2),
  (1067, 315, 'Vector A has magnitude 10 N east. Vector B has magnitude 10 N east. Are they equivalent?', 'text', 1, 'Check both magnitude and direction.', '{"why":"Equivalent vectors have the same magnitude and the same direction.","sol":"Step 1: Vector A has magnitude 10 N.\nStep 2: Vector B has magnitude 10 N.\nStep 3: Both point east.\nStep 4: Therefore they have the same magnitude and direction.","steps":["Step 1: Vector A has magnitude 10 N.","Step 2: Vector B has magnitude 10 N.","Step 3: Both point east.","Step 4: Therefore they have the same magnitude and direction."],"options":[],"conceptId":"math_vectors_equivalent_vectors","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Equivalent Vectors"}', 0),
  (1068, 315, 'Vector A has magnitude 6 m north. Vector B has magnitude 6 m south. Are they equivalent?', 'text', 1, 'Their magnitudes are equal. What about their directions?', '{"why":"Equal magnitude is not enough; equivalent vectors must also have the same direction.","sol":"Step 1: Both vectors have magnitude 6 m.\nStep 2: A points north.\nStep 3: B points south.\nStep 4: The directions are opposite.\nStep 5: Therefore they are not equivalent.","steps":["Step 1: Both vectors have magnitude 6 m.","Step 2: A points north.","Step 3: B points south.","Step 4: The directions are opposite.","Step 5: Therefore they are not equivalent."],"options":[],"conceptId":"math_vectors_equivalent_vectors","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Equivalent Vectors"}', 1),
  (1069, 315, 'Two vectors have the same magnitude and direction but are drawn at different positions on a page. Can they still be equivalent?', 'text', 1, 'Does the starting position form part of the definition of an equivalent vector?', '{"why":"Equivalent vectors can be drawn in different positions as long as magnitude and direction are unchanged.","sol":"Step 1: Compare their magnitudes.\nStep 2: They are the same.\nStep 3: Compare their directions.\nStep 4: They are also the same.\nStep 5: Their positions are different, but position does not prevent equivalence.","steps":["Step 1: Compare their magnitudes.","Step 2: They are the same.","Step 3: Compare their directions.","Step 4: They are also the same.","Step 5: Their positions are different, but position does not prevent equivalence."],"options":[],"conceptId":"math_vectors_equivalent_vectors","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Equivalent Vectors"}', 2),
  (1070, 316, 'A vector is 12 m east. What is its opposite vector?', 'text', 1, 'Keep the magnitude and reverse the direction.', '{"why":"Opposite vectors have the same magnitude but opposite directions.","sol":"Step 1: The original magnitude is 12 m.\nStep 2: Keep the magnitude at 12 m.\nStep 3: The opposite of east is west.\nStep 4: Therefore the opposite vector is 12 m west.","steps":["Step 1: The original magnitude is 12 m.","Step 2: Keep the magnitude at 12 m.","Step 3: The opposite of east is west.","Step 4: Therefore the opposite vector is 12 m west."],"options":[],"conceptId":"math_vectors_opposite_vectors","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Opposite Vectors"}', 0),
  (1071, 316, 'If ⃗a = 8 N upward, what is -⃗a?', 'text', 1, 'The negative sign reverses the direction.', '{"why":"A negative vector has the same magnitude but points in the opposite direction.","sol":"Step 1: The magnitude of ⃗a is 8 N.\nStep 2: Keep the magnitude as 8 N.\nStep 3: Reverse upward to downward.\nStep 4: Therefore -⃗a = 8 N downward.","steps":["Step 1: The magnitude of ⃗a is 8 N.","Step 2: Keep the magnitude as 8 N.","Step 3: Reverse upward to downward.","Step 4: Therefore -⃗a = 8 N downward."],"options":[],"conceptId":"math_vectors_opposite_vectors","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Opposite Vectors"}', 1),
  (1072, 316, 'If ⃗AB represents movement from A to B, which vector represents the opposite direction?', 'text', 1, 'Reverse the starting and ending points.', '{"why":"Reversing the direction changes the vector from ⃗AB to ⃗BA.","sol":"Step 1: ⃗AB means movement from A to B.\nStep 2: The opposite movement must be from B to A.\nStep 3: Therefore the opposite vector is ⃗BA.","steps":["Step 1: ⃗AB means movement from A to B.","Step 2: The opposite movement must be from B to A.","Step 3: Therefore the opposite vector is ⃗BA."],"options":[],"conceptId":"math_vectors_opposite_vectors","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Opposite Vectors"}', 2),
  (1073, 317, 'Which of the following is a scalar quantity: mass, force, displacement, or velocity?', 'text', 1, 'Ask whether the quantity requires a direction.', '{"why":"A scalar quantity is completely described by its magnitude without direction.","sol":"Step 1: Mass tells us how much matter an object contains.\nStep 2: Mass does not require a direction.\nStep 3: Therefore, mass is the scalar quantity.","steps":["Step 1: Mass tells us how much matter an object contains.","Step 2: Mass does not require a direction.","Step 3: Therefore, mass is the scalar quantity."],"options":[],"conceptId":"math_vectors_scalar_quantities","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Scalar Quantities"}', 0),
  (1074, 317, 'A student spends 30 minutes studying. Is the 30 minutes a scalar quantity?', 'text', 1, 'Does time require a direction?', '{"why":"Time has magnitude but does not require direction.","sol":"Step 1: The quantity being described is time.\nStep 2: The student studied for 30 minutes.\nStep 3: No direction is required to describe the time.\nStep 4: Therefore, time is scalar.","steps":["Step 1: The quantity being described is time.","Step 2: The student studied for 30 minutes.","Step 3: No direction is required to describe the time.","Step 4: Therefore, time is scalar."],"options":[],"conceptId":"math_vectors_scalar_quantities","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Scalar Quantities"}', 1),
  (1075, 317, 'A bottle contains 2 litres of water. Is volume a scalar quantity?', 'text', 1, 'Does volume need a direction?', '{"why":"Volume is described by its amount only.","sol":"Step 1: The quantity is volume.\nStep 2: The amount of water is 2 litres.\nStep 3: A direction is not needed to describe the volume.\nStep 4: Therefore, volume is scalar.","steps":["Step 1: The quantity is volume.","Step 2: The amount of water is 2 litres.","Step 3: A direction is not needed to describe the volume.","Step 4: Therefore, volume is scalar."],"options":[],"conceptId":"math_vectors_scalar_quantities","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Scalar Quantities"}', 2),
  (1076, 318, 'A person walks 12 m east. What is the magnitude and what is the direction?', 'text', 1, 'The number gives magnitude; the word describing the way gives direction.', '{"why":"A vector is described using both magnitude and direction.","sol":"Step 1: The distance given is 12 m.\nStep 2: Therefore the magnitude is 12 m.\nStep 3: The direction given is east.","steps":["Step 1: The distance given is 12 m.","Step 2: Therefore the magnitude is 12 m.","Step 3: The direction given is east."],"options":[],"conceptId":"math_vectors_vector_quantities","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Vector Quantities"}', 0),
  (1077, 318, 'A force of 20 N acts downward. What is its magnitude?', 'text', 1, 'Ignore the direction for this question.', '{"why":"Magnitude tells us the size or amount of the vector quantity.","sol":"Step 1: The force is given as 20 N downward.\nStep 2: The numerical size of the force is 20 N.\nStep 3: Therefore its magnitude is 20 N.","steps":["Step 1: The force is given as 20 N downward.","Step 2: The numerical size of the force is 20 N.","Step 3: Therefore its magnitude is 20 N."],"options":[],"conceptId":"math_vectors_vector_quantities","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Vector Quantities"}', 1),
  (1078, 318, 'A displacement is 8 km west. What information identifies its direction?', 'text', 1, 'Look for the word that tells which way the movement occurred.', '{"why":"Direction tells us which way the vector points.","sol":"Step 1: The displacement is given as 8 km west.\nStep 2: 8 km gives the magnitude.\nStep 3: West gives the direction.","steps":["Step 1: The displacement is given as 8 km west.","Step 2: 8 km gives the magnitude.","Step 3: West gives the direction."],"options":[],"conceptId":"math_vectors_vector_quantities","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Vector Quantities"}', 2),
  (1079, 319, 'Classify mass as scalar or vector.', 'text', 1, 'Does mass need a direction?', '{"why":"Mass has magnitude only and does not require direction.","sol":"Step 1: Mass tells us the amount of matter in an object.\nStep 2: A direction is not needed.\nStep 3: Therefore mass is scalar.","steps":["Step 1: Mass tells us the amount of matter in an object.","Step 2: A direction is not needed.","Step 3: Therefore mass is scalar."],"options":[],"conceptId":"math_vectors_scalar_vs_vector_quantities","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Scalar vs Vector Quantities"}', 0),
  (1080, 319, 'Classify displacement as scalar or vector.', 'text', 1, 'Does displacement need direction?', '{"why":"Displacement requires both magnitude and direction.","sol":"Step 1: Displacement describes a change in position.\nStep 2: The change in position must have a size and a direction.\nStep 3: Therefore displacement is vector.","steps":["Step 1: Displacement describes a change in position.","Step 2: The change in position must have a size and a direction.","Step 3: Therefore displacement is vector."],"options":[],"conceptId":"math_vectors_scalar_vs_vector_quantities","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Scalar vs Vector Quantities"}', 1),
  (1081, 319, 'A runner''s speed is 12 m/s. Is speed scalar or vector?', 'text', 1, 'Does speed itself tell you which direction the runner is moving?', '{"why":"Speed gives magnitude of motion without direction.","sol":"Step 1: Speed tells how fast the runner is moving.\nStep 2: The value 12 m/s does not specify a direction.\nStep 3: Therefore speed is scalar.","steps":["Step 1: Speed tells how fast the runner is moving.","Step 2: The value 12 m/s does not specify a direction.","Step 3: Therefore speed is scalar."],"options":[],"conceptId":"math_vectors_scalar_vs_vector_quantities","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Scalar vs Vector Quantities"}', 2),
  (1082, 320, 'A force of 25 N acts upward. What is its magnitude?', 'text', 1, 'The direction is not needed to find magnitude.', '{"why":"Magnitude is the size of the vector quantity.","sol":"Step 1: The force is given as 25 N upward.\nStep 2: 25 N gives the size of the force.\nStep 3: Upward gives the direction.\nStep 4: Therefore the magnitude is 25 N.","steps":["Step 1: The force is given as 25 N upward.","Step 2: 25 N gives the size of the force.","Step 3: Upward gives the direction.","Step 4: Therefore the magnitude is 25 N."],"options":[],"conceptId":"math_vectors_magnitude_of_a_vector","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Magnitude of a Vector"}', 0),
  (1083, 320, 'A displacement is 14 km west. What is its magnitude?', 'text', 1, 'Separate the amount from the direction.', '{"why":"The numerical size of the displacement is its magnitude.","sol":"Step 1: 14 km gives the amount of displacement.\nStep 2: West gives the direction.\nStep 3: Therefore the magnitude is 14 km.","steps":["Step 1: 14 km gives the amount of displacement.","Step 2: West gives the direction.","Step 3: Therefore the magnitude is 14 km."],"options":[],"conceptId":"math_vectors_magnitude_of_a_vector","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Magnitude of a Vector"}', 1),
  (1084, 320, 'A velocity is 30 m/s south. What is its magnitude?', 'text', 1, 'South describes direction.', '{"why":"Magnitude is the size of a vector, while south is its direction.","sol":"Step 1: The velocity is 30 m/s south.\nStep 2: 30 m/s gives the numerical size.\nStep 3: South gives direction.\nStep 4: Therefore the magnitude is 30 m/s.","steps":["Step 1: The velocity is 30 m/s south.","Step 2: 30 m/s gives the numerical size.","Step 3: South gives direction.","Step 4: Therefore the magnitude is 30 m/s."],"options":[],"conceptId":"math_vectors_magnitude_of_a_vector","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Magnitude of a Vector"}', 2),
  (1085, 321, 'A displacement is 18 m east. What is its direction?', 'text', 1, 'Look for the word that tells which way the displacement points.', '{"why":"The direction is the part of the vector description that tells which way it points.","sol":"Step 1: The displacement is written as 18 m east.\nStep 2: 18 m is the magnitude.\nStep 3: East tells us the direction.","steps":["Step 1: The displacement is written as 18 m east.","Step 2: 18 m is the magnitude.","Step 3: East tells us the direction."],"options":[],"conceptId":"math_vectors_direction_of_a_vector","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Direction of a Vector"}', 0),
  (1086, 321, 'A force of 50 N acts downward. What is the direction of the force?', 'text', 1, '50 N tells you the size. Which word tells you the way?', '{"why":"Direction describes the way in which the vector acts.","sol":"Step 1: 50 N gives the magnitude.\nStep 2: Downward tells us which way the force acts.\nStep 3: Therefore the direction is downward.","steps":["Step 1: 50 N gives the magnitude.","Step 2: Downward tells us which way the force acts.","Step 3: Therefore the direction is downward."],"options":[],"conceptId":"math_vectors_direction_of_a_vector","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Direction of a Vector"}', 1),
  (1087, 321, 'Two vectors have magnitudes of 12 m. One points east and the other points west. Do they have the same direction?', 'text', 1, 'Compare east and west.', '{"why":"Vectors with the same magnitude can still have different directions.","sol":"Step 1: The first vector points east.\nStep 2: The second vector points west.\nStep 3: East and west are opposite directions.\nStep 4: Therefore their directions are not the same.","steps":["Step 1: The first vector points east.","Step 2: The second vector points west.","Step 3: East and west are opposite directions.","Step 4: Therefore their directions are not the same."],"options":[],"conceptId":"math_vectors_direction_of_a_vector","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Direction of a Vector"}', 2),
  (1088, 322, 'What does the column vector (3, 5) represent?', 'text', 1, 'Read the top number first, then the bottom number.', '{"why":"The top component gives horizontal movement and the bottom component gives vertical movement.","sol":"Step 1: The top number is 3, so move 3 units right.\nStep 2: The bottom number is 5, so move 5 units up.\nStep 3: Therefore the vector represents 3 units right and 5 units up.","steps":["Step 1: The top number is 3, so move 3 units right.","Step 2: The bottom number is 5, so move 5 units up.","Step 3: Therefore the vector represents 3 units right and 5 units up."],"options":[],"conceptId":"math_vectors_column_vector_notation","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Column Vector Notation"}', 0),
  (1089, 322, 'What movement is represented by the column vector (-2, 4)?', 'text', 1, 'A negative horizontal component means left.', '{"why":"The negative sign reverses the horizontal direction.","sol":"Step 1: The top number is -2.\nStep 2: Therefore move 2 units left.\nStep 3: The bottom number is 4.\nStep 4: Therefore move 4 units up.","steps":["Step 1: The top number is -2.","Step 2: Therefore move 2 units left.","Step 3: The bottom number is 4.","Step 4: Therefore move 4 units up."],"options":[],"conceptId":"math_vectors_column_vector_notation","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Column Vector Notation"}', 1),
  (1090, 322, 'What movement is represented by the column vector (7, -3)?', 'text', 1, 'The negative bottom component means downward movement.', '{"why":"The top component controls horizontal movement and the bottom component controls vertical movement.","sol":"Step 1: The top number is 7, so move 7 units right.\nStep 2: The bottom number is -3, so move 3 units down.","steps":["Step 1: The top number is 7, so move 7 units right.","Step 2: The bottom number is -3, so move 3 units down."],"options":[],"conceptId":"math_vectors_column_vector_notation","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Column Vector Notation"}', 2),
  (1091, 323, 'Interpret the column vector (-6, -4).', 'text', 1, 'Look at the sign of each component.', '{"why":"Negative horizontal means left and negative vertical means down.","sol":"Step 1: The horizontal component is -6, so move 6 units left.\nStep 2: The vertical component is -4, so move 4 units down.","steps":["Step 1: The horizontal component is -6, so move 6 units left.","Step 2: The vertical component is -4, so move 4 units down."],"options":[],"conceptId":"math_vectors_reading_a_column_vector_as_movement","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Reading a Column Vector as Movement"}', 0),
  (1092, 323, 'Write the column vector for 8 units right and 3 units down.', 'text', 1, 'Right is positive and down is negative.', '{"why":"Horizontal movement is written first, followed by vertical movement.","sol":"Step 1: Horizontal movement = 8 units right, so the first component is +8.\nStep 2: Vertical movement = 3 units down, so the second component is -3.\nStep 3: Therefore the column vector is (8, -3).","steps":["Step 1: Horizontal movement = 8 units right, so the first component is +8.","Step 2: Vertical movement = 3 units down, so the second component is -3.","Step 3: Therefore the column vector is (8, -3)."],"options":[],"conceptId":"math_vectors_reading_a_column_vector_as_movement","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Reading a Column Vector as Movement"}', 1),
  (1093, 323, 'Write the column vector for 5 units left and 2 units up.', 'text', 1, 'Left is negative; up is positive.', '{"why":"The signs record the directions of the two components.","sol":"Step 1: Horizontal movement = 5 units left, so the first component is -5.\nStep 2: Vertical movement = 2 units up, so the second component is +2.\nStep 3: Therefore the vector is (-5, 2).","steps":["Step 1: Horizontal movement = 5 units left, so the first component is -5.","Step 2: Vertical movement = 2 units up, so the second component is +2.","Step 3: Therefore the vector is (-5, 2)."],"options":[],"conceptId":"math_vectors_reading_a_column_vector_as_movement","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Reading a Column Vector as Movement"}', 2),
  (1094, 324, 'What is the horizontal component of (6, -2)?', 'text', 1, 'The horizontal component is always the top entry.', '{"why":"The first component of a two-dimensional column vector represents horizontal movement.","sol":"Step 1: A column vector is written with horizontal movement first.\nStep 2: The top entry is 6.\nStep 3: Therefore the horizontal component is 6.","steps":["Step 1: A column vector is written with horizontal movement first.","Step 2: The top entry is 6.","Step 3: Therefore the horizontal component is 6."],"options":[],"conceptId":"math_vectors_horizontal_and_vertical_components","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Horizontal and Vertical Components"}', 0),
  (1095, 324, 'What is the vertical component of (-3, 8)?', 'text', 1, 'The vertical component is the bottom entry.', '{"why":"The second component represents vertical movement.","sol":"Step 1: The bottom entry represents vertical movement.\nStep 2: The bottom entry is 8.\nStep 3: Therefore the vertical component is 8.","steps":["Step 1: The bottom entry represents vertical movement.","Step 2: The bottom entry is 8.","Step 3: Therefore the vertical component is 8."],"options":[],"conceptId":"math_vectors_horizontal_and_vertical_components","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Horizontal and Vertical Components"}', 1),
  (1096, 324, 'A vector has horizontal component -7 and vertical component -5. Write it as a column vector.', 'text', 1, 'Put horizontal first and vertical second.', '{"why":"Column-vector notation places the horizontal component above the vertical component.","sol":"Step 1: Horizontal component = -7.\nStep 2: Vertical component = -5.\nStep 3: Place -7 on top and -5 underneath.","steps":["Step 1: Horizontal component = -7.","Step 2: Vertical component = -5.","Step 3: Place -7 on top and -5 underneath."],"options":[],"conceptId":"math_vectors_horizontal_and_vertical_components","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Horizontal and Vertical Components"}', 2),
  (1097, 325, 'A vector moves 8 units right and 5 units up. Write its column vector.', 'text', 1, 'Both directions are positive.', '{"why":"The geometric movement is converted directly into horizontal and vertical components.","sol":"Step 1: Right gives horizontal component +8.\nStep 2: Up gives vertical component +5.\nStep 3: Put horizontal first and vertical second.","steps":["Step 1: Right gives horizontal component +8.","Step 2: Up gives vertical component +5.","Step 3: Put horizontal first and vertical second."],"options":[],"conceptId":"math_vectors_representing_a_geometric_vector_as_a_column_vector","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Representing a Geometric Vector as a Column Vector"}', 0),
  (1098, 325, 'A vector moves 4 units left and 6 units down. Write its column vector.', 'text', 1, 'Both left and down have negative signs.', '{"why":"Left and down represent negative movement on the coordinate plane.","sol":"Step 1: Left gives horizontal component -4.\nStep 2: Down gives vertical component -6.\nStep 3: Therefore the column vector is (-4, -6).","steps":["Step 1: Left gives horizontal component -4.","Step 2: Down gives vertical component -6.","Step 3: Therefore the column vector is (-4, -6)."],"options":[],"conceptId":"math_vectors_representing_a_geometric_vector_as_a_column_vector","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Representing a Geometric Vector as a Column Vector"}', 1),
  (1099, 325, 'A vector moves 9 units right and 3 units down. Write its column vector.', 'text', 1, 'Right is positive; down is negative.', '{"why":"The signs record the direction of each component.","sol":"Step 1: Horizontal component = +9.\nStep 2: Vertical component = -3.\nStep 3: Therefore the vector is (9, -3).","steps":["Step 1: Horizontal component = +9.","Step 2: Vertical component = -3.","Step 3: Therefore the vector is (9, -3)."],"options":[],"conceptId":"math_vectors_representing_a_geometric_vector_as_a_column_vector","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Representing a Geometric Vector as a Column Vector"}', 2),
  (1100, 326, 'Find the column vector from A(2, 1) to B(7, 4).', 'text', 1, 'Calculate B − A, coordinate by coordinate.', '{"why":"The vector records the change from the starting point to the destination.","sol":"Step 1: Horizontal change = 7 - 2 = 5.\nStep 2: Vertical change = 4 - 1 = 3.\nStep 3: Therefore the vector is (5, 3).","steps":["Step 1: Horizontal change = 7 - 2 = 5.","Step 2: Vertical change = 4 - 1 = 3.","Step 3: Therefore the vector is (5, 3)."],"options":[],"conceptId":"math_vectors_finding_the_column_vector_between_two_points","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Finding the Column Vector Between Two Points"}', 0),
  (1101, 326, 'Find the column vector from P(6, 5) to Q(2, 1).', 'text', 1, 'Use final coordinate minus starting coordinate.', '{"why":"Negative components show that the movement is left and down.","sol":"Step 1: Horizontal change = 2 - 6 = -4.\nStep 2: Vertical change = 1 - 5 = -4.\nStep 3: Therefore the vector is (-4, -4).","steps":["Step 1: Horizontal change = 2 - 6 = -4.","Step 2: Vertical change = 1 - 5 = -4.","Step 3: Therefore the vector is (-4, -4)."],"options":[],"conceptId":"math_vectors_finding_the_column_vector_between_two_points","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Finding the Column Vector Between Two Points"}', 1),
  (1102, 326, 'Find the column vector from C(-3, 2) to D(4, -1).', 'text', 1, 'Subtract C''s coordinates from D''s coordinates.', '{"why":"The vector describes the exact horizontal and vertical changes needed to move from C to D.","sol":"Step 1: Horizontal change = 4 - (-3) = 7.\nStep 2: Vertical change = -1 - 2 = -3.\nStep 3: Therefore the vector is (7, -3).","steps":["Step 1: Horizontal change = 4 - (-3) = 7.","Step 2: Vertical change = -1 - 2 = -3.","Step 3: Therefore the vector is (7, -3)."],"options":[],"conceptId":"math_vectors_finding_the_column_vector_between_two_points","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Finding the Column Vector Between Two Points"}', 2),
  (1103, 327, 'What is the position vector of point A called if A is any point on a Cartesian plane?', 'text', 1, 'A position vector starts at the origin.', '{"why":"A position vector of A is the vector drawn from the origin O to A.","sol":"Step 1: The origin is O.\nStep 2: The position vector must start at O.\nStep 3: It ends at A.\nStep 4: Therefore the position vector is OA.","steps":["Step 1: The origin is O.","Step 2: The position vector must start at O.","Step 3: It ends at A.","Step 4: Therefore the position vector is OA."],"options":[],"conceptId":"math_vectors_meaning_of_a_position_vector","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Meaning of a Position Vector"}', 0),
  (1104, 327, 'Point B is at (-2, 4). Which vector represents its position vector?', 'text', 1, 'Start at O and finish at B.', '{"why":"The position vector of a point always runs from the origin to that point.","sol":"Step 1: The starting point is the origin O.\nStep 2: The ending point is B.\nStep 3: Therefore the position vector is OB.","steps":["Step 1: The starting point is the origin O.","Step 2: The ending point is B.","Step 3: Therefore the position vector is OB."],"options":[],"conceptId":"math_vectors_meaning_of_a_position_vector","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Meaning of a Position Vector"}', 1),
  (1105, 327, 'Point C is at (5, -3). Explain what OC represents.', 'text', 1, 'Think about where the vector starts and finishes.', '{"why":"A position vector describes the location of its endpoint relative to the origin.","sol":"Step 1: OC starts at the origin O.\nStep 2: It finishes at point C.\nStep 3: Therefore it describes the position of C relative to the origin.","steps":["Step 1: OC starts at the origin O.","Step 2: It finishes at point C.","Step 3: Therefore it describes the position of C relative to the origin."],"options":[],"conceptId":"math_vectors_meaning_of_a_position_vector","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Meaning of a Position Vector"}', 2),
  (1106, 328, 'A = (6, 4). Find OA.', 'text', 1, 'Use the coordinates directly.', '{"why":"The coordinates of A are the components of its position vector.","sol":"Step 1: A = (6, 4).\nStep 2: The x-coordinate is 6.\nStep 3: The y-coordinate is 4.\nStep 4: Therefore OA = (6, 4).","steps":["Step 1: A = (6, 4).","Step 2: The x-coordinate is 6.","Step 3: The y-coordinate is 4.","Step 4: Therefore OA = (6, 4)."],"options":[],"conceptId":"math_vectors_finding_a_position_vector_from_coordinates","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Finding a Position Vector from Coordinates"}', 0),
  (1107, 328, 'B = (-5, 3). Find OB.', 'text', 1, 'Keep the negative sign.', '{"why":"The x-coordinate -5 means the vector moves 5 units to the left.","sol":"Step 1: B = (-5, 3).\nStep 2: The horizontal component is -5.\nStep 3: The vertical component is 3.\nStep 4: Therefore OB = (-5, 3).","steps":["Step 1: B = (-5, 3).","Step 2: The horizontal component is -5.","Step 3: The vertical component is 3.","Step 4: Therefore OB = (-5, 3)."],"options":[],"conceptId":"math_vectors_finding_a_position_vector_from_coordinates","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Finding a Position Vector from Coordinates"}', 1),
  (1108, 328, 'C = (2, -7). Find OC.', 'text', 1, 'The negative number is the vertical component.', '{"why":"The coordinates directly give the horizontal and vertical components of the position vector.","sol":"Step 1: C = (2, -7).\nStep 2: The horizontal component is 2.\nStep 3: The vertical component is -7.\nStep 4: Therefore OC = (2, -7).","steps":["Step 1: C = (2, -7).","Step 2: The horizontal component is 2.","Step 3: The vertical component is -7.","Step 4: Therefore OC = (2, -7)."],"options":[],"conceptId":"math_vectors_finding_a_position_vector_from_coordinates","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Finding a Position Vector from Coordinates"}', 2),
  (1109, 329, 'OA = (5, 8). Find the coordinates of A.', 'text', 1, 'The two components become the two coordinates.', '{"why":"The components of a position vector give the coordinates of its endpoint.","sol":"Step 1: The first component is 5, so x = 5.\nStep 2: The second component is 8, so y = 8.\nStep 3: Therefore A = (5, 8).","steps":["Step 1: The first component is 5, so x = 5.","Step 2: The second component is 8, so y = 8.","Step 3: Therefore A = (5, 8)."],"options":[],"conceptId":"math_vectors_finding_coordinates_from_a_position_vector","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Finding Coordinates from a Position Vector"}', 0),
  (1110, 329, 'OB = (-3, 7). Find the coordinates of B.', 'text', 1, 'Keep the negative x-coordinate.', '{"why":"The negative first component means B lies to the left of the origin.","sol":"Step 1: The first component is -3.\nStep 2: The second component is 7.\nStep 3: Therefore B = (-3, 7).","steps":["Step 1: The first component is -3.","Step 2: The second component is 7.","Step 3: Therefore B = (-3, 7)."],"options":[],"conceptId":"math_vectors_finding_coordinates_from_a_position_vector","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Finding Coordinates from a Position Vector"}', 1),
  (1111, 329, 'OC = (-4, -2). Find the coordinates of C.', 'text', 1, 'Both components are negative.', '{"why":"Both negative components are retained because they describe C''s position relative to the origin.","sol":"Step 1: The first component is -4.\nStep 2: The second component is -2.\nStep 3: Therefore C = (-4, -2).","steps":["Step 1: The first component is -4.","Step 2: The second component is -2.","Step 3: Therefore C = (-4, -2)."],"options":[],"conceptId":"math_vectors_finding_coordinates_from_a_position_vector","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Finding Coordinates from a Position Vector"}', 2),
  (1112, 330, 'A = (1, 4) and B = (6, 9). Find AB.', 'text', 1, 'Use AB = OB - OA.', '{"why":"The vector from A to B is found by subtracting A''s position vector from B''s.","sol":"Step 1: OA = (1, 4).\nStep 2: OB = (6, 9).\nStep 3: AB = OB - OA.\nStep 4: AB = (6, 9) - (1, 4).\nStep 5: Horizontal: 6 - 1 = 5.\nStep 6: Vertical: 9 - 4 = 5.\nStep 7: Therefore AB = (5, 5).","steps":["Step 1: OA = (1, 4).","Step 2: OB = (6, 9).","Step 3: AB = OB - OA.","Step 4: AB = (6, 9) - (1, 4).","Step 5: Horizontal: 6 - 1 = 5.","Step 6: Vertical: 9 - 4 = 5.","Step 7: Therefore AB = (5, 5)."],"options":[],"conceptId":"math_vectors_finding_a_vector_between_two_points_using_position_vectors","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Finding a Vector Between Two Points Using Position Vectors"}', 0),
  (1113, 330, 'A = (-2, 5) and B = (4, 1). Find AB.', 'text', 1, 'Subtract (-2, 5) from (4, 1).', '{"why":"The positive horizontal component means right, while the negative vertical component means down.","sol":"Step 1: OA = (-2, 5).\nStep 2: OB = (4, 1).\nStep 3: AB = OB - OA.\nStep 4: AB = (4, 1) - (-2, 5).\nStep 5: Horizontal: 4 - (-2) = 6.\nStep 6: Vertical: 1 - 5 = -4.\nStep 7: Therefore AB = (6, -4).","steps":["Step 1: OA = (-2, 5).","Step 2: OB = (4, 1).","Step 3: AB = OB - OA.","Step 4: AB = (4, 1) - (-2, 5).","Step 5: Horizontal: 4 - (-2) = 6.","Step 6: Vertical: 1 - 5 = -4.","Step 7: Therefore AB = (6, -4)."],"options":[],"conceptId":"math_vectors_finding_a_vector_between_two_points_using_position_vectors","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Finding a Vector Between Two Points Using Position Vectors"}', 1),
  (1114, 330, 'A = (5, -1) and B = (-2, 3). Find AB.', 'text', 1, 'Destination minus starting point.', '{"why":"The vector moves 7 units left and 4 units up from A to B.","sol":"Step 1: OA = (5, -1).\nStep 2: OB = (-2, 3).\nStep 3: AB = OB - OA.\nStep 4: AB = (-2, 3) - (5, -1).\nStep 5: Horizontal: -2 - 5 = -7.\nStep 6: Vertical: 3 - (-1) = 4.\nStep 7: Therefore AB = (-7, 4).","steps":["Step 1: OA = (5, -1).","Step 2: OB = (-2, 3).","Step 3: AB = OB - OA.","Step 4: AB = (-2, 3) - (5, -1).","Step 5: Horizontal: -2 - 5 = -7.","Step 6: Vertical: 3 - (-1) = 4.","Step 7: Therefore AB = (-7, 4)."],"options":[],"conceptId":"math_vectors_finding_a_vector_between_two_points_using_position_vectors","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Finding a Vector Between Two Points Using Position Vectors"}', 2),
  (1115, 331, 'A = (1, 2) and AB = (3, 4). Find B.', 'text', 1, 'Use OB = OA + AB.', '{"why":"Starting at A and moving by AB gives the position of B.","sol":"Step 1: OA = (1, 2).\nStep 2: AB = (3, 4).\nStep 3: OB = OA + AB.\nStep 4: OB = (1, 2) + (3, 4).\nStep 5: Horizontal: 1 + 3 = 4.\nStep 6: Vertical: 2 + 4 = 6.\nStep 7: Therefore B = (4, 6).","steps":["Step 1: OA = (1, 2).","Step 2: AB = (3, 4).","Step 3: OB = OA + AB.","Step 4: OB = (1, 2) + (3, 4).","Step 5: Horizontal: 1 + 3 = 4.","Step 6: Vertical: 2 + 4 = 6.","Step 7: Therefore B = (4, 6)."],"options":[],"conceptId":"math_vectors_finding_an_unknown_point_using_a_vector_and_a_position_vector","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Finding an Unknown Point Using a Vector and a Position Vector"}', 0),
  (1116, 331, 'A = (-2, 5) and AB = (6, -3). Find B.', 'text', 1, 'Add the components of OA and AB.', '{"why":"The movement AB is applied to the starting position A.","sol":"Step 1: OA = (-2, 5).\nStep 2: AB = (6, -3).\nStep 3: OB = OA + AB.\nStep 4: OB = (-2, 5) + (6, -3).\nStep 5: Horizontal: -2 + 6 = 4.\nStep 6: Vertical: 5 + (-3) = 2.\nStep 7: Therefore B = (4, 2).","steps":["Step 1: OA = (-2, 5).","Step 2: AB = (6, -3).","Step 3: OB = OA + AB.","Step 4: OB = (-2, 5) + (6, -3).","Step 5: Horizontal: -2 + 6 = 4.","Step 6: Vertical: 5 + (-3) = 2.","Step 7: Therefore B = (4, 2)."],"options":[],"conceptId":"math_vectors_finding_an_unknown_point_using_a_vector_and_a_position_vector","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Finding an Unknown Point Using a Vector and a Position Vector"}', 1),
  (1117, 331, 'A = (8, -4) and AB = (-5, 7). Find B.', 'text', 1, 'Remember that adding a negative number means moving in the opposite direction.', '{"why":"Starting at (8, -4), moving 5 units left and 7 units up reaches (3, 3).","sol":"Step 1: OA = (8, -4).\nStep 2: AB = (-5, 7).\nStep 3: OB = OA + AB.\nStep 4: OB = (8, -4) + (-5, 7).\nStep 5: Horizontal: 8 + (-5) = 3.\nStep 6: Vertical: -4 + 7 = 3.\nStep 7: Therefore B = (3, 3).","steps":["Step 1: OA = (8, -4).","Step 2: AB = (-5, 7).","Step 3: OB = OA + AB.","Step 4: OB = (8, -4) + (-5, 7).","Step 5: Horizontal: 8 + (-5) = 3.","Step 6: Vertical: -4 + 7 = 3.","Step 7: Therefore B = (3, 3)."],"options":[],"conceptId":"math_vectors_finding_an_unknown_point_using_a_vector_and_a_position_vector","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Finding an Unknown Point Using a Vector and a Position Vector"}', 2),
  (1118, 332, 'A vector represents 4 units to the right and another represents 3 units to the right. What is their resultant movement?', 'text', 1, 'Both movements are in the same direction.', '{"why":"Two movements in the same direction combine by adding their magnitudes.","sol":"Step 1: The first movement is 4 units right.\nStep 2: The second movement is 3 units right.\nStep 3: Add the two movements: 4 + 3 = 7.\nStep 4: Therefore the resultant movement is 7 units right.","steps":["Step 1: The first movement is 4 units right.","Step 2: The second movement is 3 units right.","Step 3: Add the two movements: 4 + 3 = 7.","Step 4: Therefore the resultant movement is 7 units right."],"options":[],"conceptId":"math_vectors_meaning_of_vector_addition","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Meaning of Vector Addition"}', 0),
  (1119, 332, 'A vector represents 5 units upward and another represents 6 units upward. Find the resultant movement.', 'text', 1, 'Both vectors point upward.', '{"why":"The movements have the same direction, so their magnitudes are added.","sol":"Step 1: First movement = 5 units up.\nStep 2: Second movement = 6 units up.\nStep 3: Add them: 5 + 6 = 11.\nStep 4: Therefore the resultant movement is 11 units upward.","steps":["Step 1: First movement = 5 units up.","Step 2: Second movement = 6 units up.","Step 3: Add them: 5 + 6 = 11.","Step 4: Therefore the resultant movement is 11 units upward."],"options":[],"conceptId":"math_vectors_meaning_of_vector_addition","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Meaning of Vector Addition"}', 1),
  (1120, 332, 'A movement of 3 units right is followed by a movement of 4 units up. Are the two movements added by simply calculating 3 + 4 = 7 units in one direction?', 'text', 1, 'The two movements are in different directions.', '{"why":"Vectors have direction, so movements in different directions cannot be treated like ordinary scalar quantities.","sol":"Step 1: The first movement is horizontal.\nStep 2: The second movement is vertical.\nStep 3: They therefore affect different components of the movement.\nStep 4: The resultant must preserve both the horizontal and vertical parts.","steps":["Step 1: The first movement is horizontal.","Step 2: The second movement is vertical.","Step 3: They therefore affect different components of the movement.","Step 4: The resultant must preserve both the horizontal and vertical parts."],"options":[],"conceptId":"math_vectors_meaning_of_vector_addition","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Meaning of Vector Addition"}', 2),
  (1121, 333, 'Vector a is 5 units right and vector b is 2 units right. Find a + b.', 'text', 1, 'Join the vectors head-to-tail.', '{"why":"The two vectors point in the same direction, so their movements combine directly.","sol":"Step 1: a moves 5 units right.\nStep 2: b moves 2 units right.\nStep 3: The total movement is 5 + 2 = 7 units right.\nStep 4: Therefore a + b = 7 units right.","steps":["Step 1: a moves 5 units right.","Step 2: b moves 2 units right.","Step 3: The total movement is 5 + 2 = 7 units right.","Step 4: Therefore a + b = 7 units right."],"options":[],"conceptId":"math_vectors_geometric_addition_of_vectors","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Geometric Addition of Vectors"}', 0),
  (1122, 333, 'Vector a is 3 units up and vector b is 4 units up. Find a + b.', 'text', 1, 'Add the two upward movements.', '{"why":"The two vectors have the same direction.","sol":"Step 1: a moves 3 units up.\nStep 2: b moves 4 units up.\nStep 3: Total upward movement = 3 + 4 = 7.\nStep 4: Therefore a + b = 7 units up.","steps":["Step 1: a moves 3 units up.","Step 2: b moves 4 units up.","Step 3: Total upward movement = 3 + 4 = 7.","Step 4: Therefore a + b = 7 units up."],"options":[],"conceptId":"math_vectors_geometric_addition_of_vectors","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Geometric Addition of Vectors"}', 1),
  (1123, 333, 'Vector a is 6 units right and vector b is 2 units up. Describe the resultant a + b.', 'text', 1, 'Keep both movements.', '{"why":"The resultant contains the combined horizontal and vertical movements.","sol":"Step 1: a contributes 6 units horizontally.\nStep 2: b contributes 2 units vertically.\nStep 3: Therefore the resultant has horizontal component 6.\nStep 4: The resultant has vertical component 2.\nStep 5: So a + b = (6, 2).","steps":["Step 1: a contributes 6 units horizontally.","Step 2: b contributes 2 units vertically.","Step 3: Therefore the resultant has horizontal component 6.","Step 4: The resultant has vertical component 2.","Step 5: So a + b = (6, 2)."],"options":[],"conceptId":"math_vectors_geometric_addition_of_vectors","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Geometric Addition of Vectors"}', 2),
  (1124, 334, 'Add (2, 4) and (3, 5).', 'text', 1, 'Add horizontal components together and vertical components together.', '{"why":"Corresponding vector components are added separately.","sol":"Step 1: Horizontal: 2 + 3 = 5.\nStep 2: Vertical: 4 + 5 = 9.\nStep 3: Therefore the resultant is (5, 9).","steps":["Step 1: Horizontal: 2 + 3 = 5.","Step 2: Vertical: 4 + 5 = 9.","Step 3: Therefore the resultant is (5, 9)."],"options":[],"conceptId":"math_vectors_column_vector_addition","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Column Vector Addition"}', 0),
  (1125, 334, 'Add (-3, 5) and (7, 2).', 'text', 1, 'Be careful with the negative first component.', '{"why":"The horizontal components combine to give 4 and the vertical components combine to give 7.","sol":"Step 1: Horizontal: -3 + 7 = 4.\nStep 2: Vertical: 5 + 2 = 7.\nStep 3: Therefore the resultant is (4, 7).","steps":["Step 1: Horizontal: -3 + 7 = 4.","Step 2: Vertical: 5 + 2 = 7.","Step 3: Therefore the resultant is (4, 7)."],"options":[],"conceptId":"math_vectors_column_vector_addition","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Column Vector Addition"}', 1),
  (1126, 334, 'Add (8, -4) and (-3, 6).', 'text', 1, 'Treat -4 and -3 as signed numbers.', '{"why":"Vector components are ordinary signed numbers, so normal integer addition applies to each component.","sol":"Step 1: Horizontal: 8 + (-3) = 5.\nStep 2: Vertical: -4 + 6 = 2.\nStep 3: Therefore the resultant is (5, 2).","steps":["Step 1: Horizontal: 8 + (-3) = 5.","Step 2: Vertical: -4 + 6 = 2.","Step 3: Therefore the resultant is (5, 2)."],"options":[],"conceptId":"math_vectors_column_vector_addition","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Column Vector Addition"}', 2),
  (1127, 335, 'Find the resultant of (4, 2) and (3, 5).', 'text', 1, 'Add the two vectors component by component.', '{"why":"The resultant contains the total horizontal and vertical movement.","sol":"Step 1: Horizontal: 4 + 3 = 7.\nStep 2: Vertical: 2 + 5 = 7.\nStep 3: Therefore the resultant is (7, 7).","steps":["Step 1: Horizontal: 4 + 3 = 7.","Step 2: Vertical: 2 + 5 = 7.","Step 3: Therefore the resultant is (7, 7)."],"options":[],"conceptId":"math_vectors_finding_a_resultant_vector","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Finding a Resultant Vector"}', 0),
  (1128, 335, 'Find the resultant of (-5, 3) and (2, 4).', 'text', 1, 'Keep the negative sign on the first horizontal component.', '{"why":"The total horizontal movement is 3 units left and the total vertical movement is 7 units up.","sol":"Step 1: Horizontal: -5 + 2 = -3.\nStep 2: Vertical: 3 + 4 = 7.\nStep 3: Therefore the resultant is (-3, 7).","steps":["Step 1: Horizontal: -5 + 2 = -3.","Step 2: Vertical: 3 + 4 = 7.","Step 3: Therefore the resultant is (-3, 7)."],"options":[],"conceptId":"math_vectors_finding_a_resultant_vector","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Finding a Resultant Vector"}', 1),
  (1129, 335, 'Find the resultant of (1, 2), (3, -1), and (-2, 5).', 'text', 1, 'You can combine the vectors one pair at a time.', '{"why":"Adding the three vectors gives a total movement of 2 units horizontally and 6 units vertically.","sol":"Step 1: First add (1, 2) and (3, -1).\nStep 2: (1, 2) + (3, -1) = (4, 1).\nStep 3: Now add (-2, 5).\nStep 4: (4, 1) + (-2, 5) = (2, 6).\nStep 5: Therefore the resultant is (2, 6).","steps":["Step 1: First add (1, 2) and (3, -1).","Step 2: (1, 2) + (3, -1) = (4, 1).","Step 3: Now add (-2, 5).","Step 4: (4, 1) + (-2, 5) = (2, 6).","Step 5: Therefore the resultant is (2, 6)."],"options":[],"conceptId":"math_vectors_finding_a_resultant_vector","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Finding a Resultant Vector"}', 2),
  (1130, 336, 'AB = (4, 2) and BC = (3, 5). Find AC.', 'text', 1, 'To go from A to C, follow A to B and then B to C.', '{"why":"The route from A to C consists of the movement A to B followed by B to C.","sol":"Step 1: AC = AB + BC.\nStep 2: AC = (4, 2) + (3, 5).\nStep 3: Horizontal: 4 + 3 = 7.\nStep 4: Vertical: 2 + 5 = 7.\nStep 5: Therefore AC = (7, 7).","steps":["Step 1: AC = AB + BC.","Step 2: AC = (4, 2) + (3, 5).","Step 3: Horizontal: 4 + 3 = 7.","Step 4: Vertical: 2 + 5 = 7.","Step 5: Therefore AC = (7, 7)."],"options":[],"conceptId":"math_vectors_vector_addition_in_geometrical_problems","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Vector Addition in Geometrical Problems"}', 0),
  (1131, 336, 'AB = (-2, 4) and BC = (5, -1). Find AC.', 'text', 1, 'Add the two consecutive vectors.', '{"why":"The resultant combines both movements along the route from A to C.","sol":"Step 1: AC = AB + BC.\nStep 2: AC = (-2, 4) + (5, -1).\nStep 3: Horizontal: -2 + 5 = 3.\nStep 4: Vertical: 4 + (-1) = 3.\nStep 5: Therefore AC = (3, 3).","steps":["Step 1: AC = AB + BC.","Step 2: AC = (-2, 4) + (5, -1).","Step 3: Horizontal: -2 + 5 = 3.","Step 4: Vertical: 4 + (-1) = 3.","Step 5: Therefore AC = (3, 3)."],"options":[],"conceptId":"math_vectors_vector_addition_in_geometrical_problems","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Vector Addition in Geometrical Problems"}', 1),
  (1132, 336, 'In triangle ABC, AB = (6, -2) and BC = (-3, 7). Find AC.', 'text', 1, 'Travel from A to B and then from B to C.', '{"why":"Adding consecutive vectors gives the direct resultant from the first point to the final point.","sol":"Step 1: AC = AB + BC.\nStep 2: AC = (6, -2) + (-3, 7).\nStep 3: Horizontal: 6 + (-3) = 3.\nStep 4: Vertical: -2 + 7 = 5.\nStep 5: Therefore AC = (3, 5).","steps":["Step 1: AC = AB + BC.","Step 2: AC = (6, -2) + (-3, 7).","Step 3: Horizontal: 6 + (-3) = 3.","Step 4: Vertical: -2 + 7 = 5.","Step 5: Therefore AC = (3, 5)."],"options":[],"conceptId":"math_vectors_vector_addition_in_geometrical_problems","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Vector Addition in Geometrical Problems"}', 2),
  (1133, 337, 'A vector is 9 units right and another is 4 units right. Find the difference.', 'text', 1, 'Subtract the second movement from the first.', '{"why":"Subtracting the smaller rightward movement from the larger one leaves 5 units right.","sol":"Step 1: First movement = 9 units right.\nStep 2: Second movement = 4 units right.\nStep 3: 9 - 4 = 5.\nStep 4: Therefore the difference is 5 units right.","steps":["Step 1: First movement = 9 units right.","Step 2: Second movement = 4 units right.","Step 3: 9 - 4 = 5.","Step 4: Therefore the difference is 5 units right."],"options":[],"conceptId":"math_vectors_meaning_of_vector_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Meaning of Vector Subtraction"}', 0),
  (1134, 337, 'A vector is 10 units upward and another is 6 units upward. Find the difference.', 'text', 1, 'Both movements are vertical.', '{"why":"The vertical movement is reduced by 6 units.","sol":"Step 1: First movement = 10 units up.\nStep 2: Second movement = 6 units up.\nStep 3: 10 - 6 = 4.\nStep 4: Therefore the difference is 4 units upward.","steps":["Step 1: First movement = 10 units up.","Step 2: Second movement = 6 units up.","Step 3: 10 - 6 = 4.","Step 4: Therefore the difference is 4 units upward."],"options":[],"conceptId":"math_vectors_meaning_of_vector_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Meaning of Vector Subtraction"}', 1),
  (1135, 337, 'Find (8, 6) - (3, 2).', 'text', 1, 'Subtract corresponding components.', '{"why":"Vector subtraction acts separately on the horizontal and vertical components.","sol":"Step 1: Horizontal: 8 - 3 = 5.\nStep 2: Vertical: 6 - 2 = 4.\nStep 3: Therefore the difference is (5, 4).","steps":["Step 1: Horizontal: 8 - 3 = 5.","Step 2: Vertical: 6 - 2 = 4.","Step 3: Therefore the difference is (5, 4)."],"options":[],"conceptId":"math_vectors_meaning_of_vector_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Meaning of Vector Subtraction"}', 2),
  (1136, 338, 'Find the negative of (5, 3).', 'text', 1, 'Change the sign of both components.', '{"why":"Changing both signs reverses both horizontal and vertical directions.","sol":"Step 1: The vector is (5, 3).\nStep 2: Change 5 to -5.\nStep 3: Change 3 to -3.\nStep 4: Therefore the negative vector is (-5, -3).","steps":["Step 1: The vector is (5, 3).","Step 2: Change 5 to -5.","Step 3: Change 3 to -3.","Step 4: Therefore the negative vector is (-5, -3)."],"options":[],"conceptId":"math_vectors_negative_vectors","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Negative Vectors"}', 0),
  (1137, 338, 'Find the negative of (-4, 7).', 'text', 1, 'Both signs must change.', '{"why":"The negative vector points in the exact opposite direction.","sol":"Step 1: -4 becomes 4.\nStep 2: 7 becomes -7.\nStep 3: Therefore the negative vector is (4, -7).","steps":["Step 1: -4 becomes 4.","Step 2: 7 becomes -7.","Step 3: Therefore the negative vector is (4, -7)."],"options":[],"conceptId":"math_vectors_negative_vectors","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Negative Vectors"}', 1),
  (1138, 338, 'If a = (2, -6), find -a.', 'text', 1, 'Reverse the sign of each component.', '{"why":"Both components change sign when a vector is reversed.","sol":"Step 1: a = (2, -6).\nStep 2: 2 becomes -2.\nStep 3: -6 becomes 6.\nStep 4: Therefore -a = (-2, 6).","steps":["Step 1: a = (2, -6).","Step 2: 2 becomes -2.","Step 3: -6 becomes 6.","Step 4: Therefore -a = (-2, 6)."],"options":[],"conceptId":"math_vectors_negative_vectors","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Negative Vectors"}', 2),
  (1139, 339, 'a = (7, 4) and b = (2, 1). Find a - b using the negative of b.', 'text', 1, 'First find -b.', '{"why":"Subtracting b is equivalent to adding the vector pointing opposite to b.","sol":"Step 1: b = (2, 1).\nStep 2: -b = (-2, -1).\nStep 3: a - b = a + (-b).\nStep 4: (7, 4) + (-2, -1) = (5, 3).\nStep 5: Therefore a - b = (5, 3).","steps":["Step 1: b = (2, 1).","Step 2: -b = (-2, -1).","Step 3: a - b = a + (-b).","Step 4: (7, 4) + (-2, -1) = (5, 3).","Step 5: Therefore a - b = (5, 3)."],"options":[],"conceptId":"math_vectors_geometric_vector_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Geometric Vector Subtraction"}', 0),
  (1140, 339, 'a = (6, 2) and b = (-3, 4). Find a - b.', 'text', 1, 'Reverse both components of b first.', '{"why":"The negative of (-3, 4) is (3, -4), which is then added to a.","sol":"Step 1: b = (-3, 4).\nStep 2: -b = (3, -4).\nStep 3: a - b = a + (-b).\nStep 4: (6, 2) + (3, -4) = (9, -2).\nStep 5: Therefore a - b = (9, -2).","steps":["Step 1: b = (-3, 4).","Step 2: -b = (3, -4).","Step 3: a - b = a + (-b).","Step 4: (6, 2) + (3, -4) = (9, -2).","Step 5: Therefore a - b = (9, -2)."],"options":[],"conceptId":"math_vectors_geometric_vector_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Geometric Vector Subtraction"}', 1),
  (1141, 339, 'a = (-4, 5) and b = (2, -3). Find a - b.', 'text', 1, 'Change the signs of b before adding.', '{"why":"Subtracting b means adding its opposite vector.","sol":"Step 1: b = (2, -3).\nStep 2: -b = (-2, 3).\nStep 3: a - b = a + (-b).\nStep 4: (-4, 5) + (-2, 3) = (-6, 8).\nStep 5: Therefore a - b = (-6, 8).","steps":["Step 1: b = (2, -3).","Step 2: -b = (-2, 3).","Step 3: a - b = a + (-b).","Step 4: (-4, 5) + (-2, 3) = (-6, 8).","Step 5: Therefore a - b = (-6, 8)."],"options":[],"conceptId":"math_vectors_geometric_vector_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Geometric Vector Subtraction"}', 2),
  (1142, 340, 'Find (9, 7) - (4, 3).', 'text', 1, 'Subtract corresponding components.', '{"why":"Each component is subtracted from the corresponding component.","sol":"Step 1: Horizontal: 9 - 4 = 5.\nStep 2: Vertical: 7 - 3 = 4.\nStep 3: Therefore the answer is (5, 4).","steps":["Step 1: Horizontal: 9 - 4 = 5.","Step 2: Vertical: 7 - 3 = 4.","Step 3: Therefore the answer is (5, 4)."],"options":[],"conceptId":"math_vectors_column_vector_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Column Vector Subtraction"}', 0),
  (1143, 340, 'Find (5, 2) - (-3, 4).', 'text', 1, 'Remember that subtracting a negative number becomes addition.', '{"why":"5 - (-3) becomes 5 + 3, while the vertical component remains 2 - 4.","sol":"Step 1: Horizontal: 5 - (-3) = 8.\nStep 2: Vertical: 2 - 4 = -2.\nStep 3: Therefore the answer is (8, -2).","steps":["Step 1: Horizontal: 5 - (-3) = 8.","Step 2: Vertical: 2 - 4 = -2.","Step 3: Therefore the answer is (8, -2)."],"options":[],"conceptId":"math_vectors_column_vector_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Column Vector Subtraction"}', 1),
  (1144, 340, 'Find (-6, 3) - (2, -5).', 'text', 1, 'Work on each component separately.', '{"why":"Subtracting -5 from 3 gives 8.","sol":"Step 1: Horizontal: -6 - 2 = -8.\nStep 2: Vertical: 3 - (-5) = 8.\nStep 3: Therefore the answer is (-8, 8).","steps":["Step 1: Horizontal: -6 - 2 = -8.","Step 2: Vertical: 3 - (-5) = 8.","Step 3: Therefore the answer is (-8, 8)."],"options":[],"conceptId":"math_vectors_column_vector_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Column Vector Subtraction"}', 2),
  (1145, 341, 'a = (7, 5) and b = (2, 1). Find a - b.', 'text', 1, 'Start with a.', '{"why":"The requested order is a minus b.","sol":"Step 1: a - b = (7, 5) - (2, 1).\nStep 2: Horizontal: 7 - 2 = 5.\nStep 3: Vertical: 5 - 1 = 4.\nStep 4: Therefore a - b = (5, 4).","steps":["Step 1: a - b = (7, 5) - (2, 1).","Step 2: Horizontal: 7 - 2 = 5.","Step 3: Vertical: 5 - 1 = 4.","Step 4: Therefore a - b = (5, 4)."],"options":[],"conceptId":"math_vectors_finding_the_difference_between_two_vectors","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Finding the Difference Between Two Vectors"}', 0),
  (1146, 341, 'a = (-4, 6) and b = (3, 2). Find a - b.', 'text', 1, 'Subtract the components of b from the corresponding components of a.', '{"why":"The negative horizontal component results from -4 - 3.","sol":"Step 1: a - b = (-4, 6) - (3, 2).\nStep 2: Horizontal: -4 - 3 = -7.\nStep 3: Vertical: 6 - 2 = 4.\nStep 4: Therefore a - b = (-7, 4).","steps":["Step 1: a - b = (-4, 6) - (3, 2).","Step 2: Horizontal: -4 - 3 = -7.","Step 3: Vertical: 6 - 2 = 4.","Step 4: Therefore a - b = (-7, 4)."],"options":[],"conceptId":"math_vectors_finding_the_difference_between_two_vectors","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Finding the Difference Between Two Vectors"}', 1),
  (1147, 341, 'a = (6, -2) and b = (-3, 5). Find a - b.', 'text', 1, 'Be especially careful with the two negative numbers.', '{"why":"Subtracting the negative horizontal component gives 9, while the vertical components give -7.","sol":"Step 1: a - b = (6, -2) - (-3, 5).\nStep 2: Horizontal: 6 - (-3) = 9.\nStep 3: Vertical: -2 - 5 = -7.\nStep 4: Therefore a - b = (9, -7).","steps":["Step 1: a - b = (6, -2) - (-3, 5).","Step 2: Horizontal: 6 - (-3) = 9.","Step 3: Vertical: -2 - 5 = -7.","Step 4: Therefore a - b = (9, -7)."],"options":[],"conceptId":"math_vectors_finding_the_difference_between_two_vectors","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Finding the Difference Between Two Vectors"}', 2),
  (1148, 342, 'Given a = (5, 2), find 3a.', 'text', 1, 'Multiply both components by 3.', '{"why":"A scalar multiplies every component of the vector.","sol":"Step 1: Start with a = (5, 2).\nStep 2: Multiply each component by 3: 3a = (3 × 5, 3 × 2).\nStep 3: Calculate: 3a = (15, 6).","steps":["Step 1: Start with a = (5, 2).","Step 2: Multiply each component by 3: 3a = (3 × 5, 3 × 2).","Step 3: Calculate: 3a = (15, 6)."],"options":[],"conceptId":"math_vectors_meaning_of_scalar_multiplication","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Meaning of Scalar Multiplication"}', 0),
  (1149, 342, 'Given b = (-4, 3), find 2b.', 'text', 1, 'Multiply -4 and 3 separately by 2.', '{"why":"Both components are multiplied by the scalar.","sol":"Step 1: Start with b = (-4, 3).\nStep 2: 2b = (2 × -4, 2 × 3).\nStep 3: Therefore 2b = (-8, 6).","steps":["Step 1: Start with b = (-4, 3).","Step 2: 2b = (2 × -4, 2 × 3).","Step 3: Therefore 2b = (-8, 6)."],"options":[],"conceptId":"math_vectors_meaning_of_scalar_multiplication","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Meaning of Scalar Multiplication"}', 1),
  (1150, 342, 'Given c = (6, -5), find 4c.', 'text', 1, 'Multiply 6 and -5 by 4.', '{"why":"Scalar multiplication applies to every component.","sol":"Step 1: 4c = (4 × 6, 4 × -5).\nStep 2: 4 × 6 = 24.\nStep 3: 4 × -5 = -20.\nStep 4: Therefore 4c = (24, -20).","steps":["Step 1: 4c = (4 × 6, 4 × -5).","Step 2: 4 × 6 = 24.","Step 3: 4 × -5 = -20.","Step 4: Therefore 4c = (24, -20)."],"options":[],"conceptId":"math_vectors_meaning_of_scalar_multiplication","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Meaning of Scalar Multiplication"}', 2),
  (1151, 343, 'Is (10, 15) a scalar multiple of (2, 3)?', 'text', 1, 'Divide corresponding components.', '{"why":"Both components are multiplied by the same scalar, 5.","sol":"Step 1: 10 ÷ 2 = 5.\nStep 2: 15 ÷ 3 = 5.\nStep 3: The same scalar is obtained.\nStep 4: Therefore (10, 15) = 5(2, 3).","steps":["Step 1: 10 ÷ 2 = 5.","Step 2: 15 ÷ 3 = 5.","Step 3: The same scalar is obtained.","Step 4: Therefore (10, 15) = 5(2, 3)."],"options":[],"conceptId":"math_vectors_recognising_a_scalar_multiple","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Recognising a Scalar Multiple"}', 0),
  (1152, 343, 'Is (-8, 12) a scalar multiple of (-2, 3)?', 'text', 1, 'Find the multiplier from each component.', '{"why":"Both components have the same scalar multiplier.","sol":"Step 1: -8 ÷ -2 = 4.\nStep 2: 12 ÷ 3 = 4.\nStep 3: The same multiplier is obtained.\nStep 4: Therefore (-8, 12) = 4(-2, 3).","steps":["Step 1: -8 ÷ -2 = 4.","Step 2: 12 ÷ 3 = 4.","Step 3: The same multiplier is obtained.","Step 4: Therefore (-8, 12) = 4(-2, 3)."],"options":[],"conceptId":"math_vectors_recognising_a_scalar_multiple","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Recognising a Scalar Multiple"}', 1),
  (1153, 343, 'Is (12, 15) a scalar multiple of (3, 4)?', 'text', 1, 'Compare 12 ÷ 3 with 15 ÷ 4.', '{"why":"A scalar multiple requires one common multiplier.","sol":"Step 1: 12 ÷ 3 = 4.\nStep 2: 15 ÷ 4 = 3.75.\nStep 3: The multipliers are different.\nStep 4: Therefore (12, 15) is not a scalar multiple of (3, 4).","steps":["Step 1: 12 ÷ 3 = 4.","Step 2: 15 ÷ 4 = 3.75.","Step 3: The multipliers are different.","Step 4: Therefore (12, 15) is not a scalar multiple of (3, 4)."],"options":[],"conceptId":"math_vectors_recognising_a_scalar_multiple","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Recognising a Scalar Multiple"}', 2),
  (1154, 344, 'Simplify 4a + 3a.', 'text', 1, 'Both terms contain a.', '{"why":"Like vector terms can be combined by adding their scalar coefficients.","sol":"Step 1: The terms are like terms because both contain a.\nStep 2: Add the coefficients: 4 + 3 = 7.\nStep 3: Therefore 4a + 3a = 7a.","steps":["Step 1: The terms are like terms because both contain a.","Step 2: Add the coefficients: 4 + 3 = 7.","Step 3: Therefore 4a + 3a = 7a."],"options":[],"conceptId":"math_vectors_adding_like_vector_terms","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Adding Like Vector Terms"}', 0),
  (1155, 344, 'Simplify 8b + 5b.', 'text', 1, 'Add 8 and 5.', '{"why":"The vector b remains while its coefficients are added.","sol":"Step 1: Both terms contain b.\nStep 2: 8 + 5 = 13.\nStep 3: Therefore 8b + 5b = 13b.","steps":["Step 1: Both terms contain b.","Step 2: 8 + 5 = 13.","Step 3: Therefore 8b + 5b = 13b."],"options":[],"conceptId":"math_vectors_adding_like_vector_terms","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Adding Like Vector Terms"}', 1),
  (1156, 344, 'Simplify 2c + 9c.', 'text', 1, 'Treat c as the common vector.', '{"why":"Like vector terms are combined by adding their coefficients.","sol":"Step 1: Both terms contain c.\nStep 2: 2 + 9 = 11.\nStep 3: Therefore 2c + 9c = 11c.","steps":["Step 1: Both terms contain c.","Step 2: 2 + 9 = 11.","Step 3: Therefore 2c + 9c = 11c."],"options":[],"conceptId":"math_vectors_adding_like_vector_terms","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Adding Like Vector Terms"}', 2),
  (1157, 345, 'Find the magnitude of a = (6, 8).', 'text', 1, 'Use |a| = √(x² + y²).', '{"why":"The magnitude is the hypotenuse formed by the two components.","sol":"Step 1: |a| = √(6² + 8²).\nStep 2: |a| = √(36 + 64).\nStep 3: |a| = √100.\nStep 4: |a| = 10.","steps":["Step 1: |a| = √(6² + 8²).","Step 2: |a| = √(36 + 64).","Step 3: |a| = √100.","Step 4: |a| = 10."],"options":[],"conceptId":"math_vectors_magnitude_from_a_column_vector","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Magnitude from a Column Vector"}', 0),
  (1158, 345, 'Find the magnitude of b = (-5, 12).', 'text', 1, 'Remember that (-5)² is positive.', '{"why":"Squaring the negative component makes its contribution positive.","sol":"Step 1: |b| = √((-5)² + 12²).\nStep 2: |b| = √(25 + 144).\nStep 3: |b| = √169.\nStep 4: |b| = 13.","steps":["Step 1: |b| = √((-5)² + 12²).","Step 2: |b| = √(25 + 144).","Step 3: |b| = √169.","Step 4: |b| = 13."],"options":[],"conceptId":"math_vectors_magnitude_from_a_column_vector","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Magnitude from a Column Vector"}', 1),
  (1159, 345, 'Find the magnitude of c = (8, 15).', 'text', 1, 'Square both components, add, then take the square root.', '{"why":"The vector length is obtained from Pythagoras'' theorem.","sol":"Step 1: |c| = √(8² + 15²).\nStep 2: |c| = √(64 + 225).\nStep 3: |c| = √289.\nStep 4: |c| = 17.","steps":["Step 1: |c| = √(8² + 15²).","Step 2: |c| = √(64 + 225).","Step 3: |c| = √289.","Step 4: |c| = 17."],"options":[],"conceptId":"math_vectors_magnitude_from_a_column_vector","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Magnitude from a Column Vector"}', 2),
  (1160, 346, 'Find gradient of curve using dy/dx at a point', 'text', 1, 'differentiate then substitute', '{"why":"Gradient of a curve is found using differentiation at a specific point","sol":"Step 1: Start with function y = f(x)\nStep 2: Differentiate to find dy/dx\nStep 3: Substitute the given x-value\nStep 4: Compute gradient at that point","steps":["Step 1: Start with function y = f(x)","Step 2: Differentiate to find dy/dx","Step 3: Substitute the given x-value","Step 4: Compute gradient at that point"],"options":[],"conceptId":"math_calculus_gradient_of_a_curve","skillId":"math_calculus","subskillId":"math_calculus_q1","subject":"math","chapter":"calculus","topic":"Gradient of a Curve"}', 0),
  (1161, 346, 'Find dy/dx for y = x² and evaluate at x = 3', 'text', 1, 'power rule', '{"why":"Derivative gives slope of tangent at a point","sol":"Step 1: Differentiate y = x² → dy/dx = 2x\nStep 2: Substitute x = 3\nStep 3: Compute 2 × 3\nStep 4: Get final gradient","steps":["Step 1: Differentiate y = x² → dy/dx = 2x","Step 2: Substitute x = 3","Step 3: Compute 2 × 3","Step 4: Get final gradient"],"options":[],"conceptId":"math_calculus_gradient_of_a_curve","skillId":"math_calculus","subskillId":"math_calculus_q2","subject":"math","chapter":"calculus","topic":"Gradient of a Curve"}', 1),
  (1162, 346, 'Find gradient of y = 2x + 3', 'text', 1, 'linear function rule', '{"why":"In linear equations, gradient is the coefficient of x","sol":"Step 1: Identify equation y = mx + c\nStep 2: Recognize coefficient of x\nStep 3: Extract m value\nStep 4: State gradient","steps":["Step 1: Identify equation y = mx + c","Step 2: Recognize coefficient of x","Step 3: Extract m value","Step 4: State gradient"],"options":[],"conceptId":"math_calculus_gradient_of_a_curve","skillId":"math_calculus","subskillId":"math_calculus_q3","subject":"math","chapter":"calculus","topic":"Gradient of a Curve"}', 2),
  (1163, 346, 'Find dy/dx of y = 3x² at x = 2', 'text', 1, 'power rule', '{"why":"Derivative gives instantaneous rate of change","sol":"Step 1: Differentiate y = 3x² → dy/dx = 6x\nStep 2: Substitute x = 2\nStep 3: Multiply 6 × 2\nStep 4: Compute gradient","steps":["Step 1: Differentiate y = 3x² → dy/dx = 6x","Step 2: Substitute x = 2","Step 3: Multiply 6 × 2","Step 4: Compute gradient"],"options":[],"conceptId":"math_calculus_gradient_of_a_curve","skillId":"math_calculus","subskillId":"math_calculus_q4","subject":"math","chapter":"calculus","topic":"Gradient of a Curve"}', 3),
  (1164, 347, 'Find rate of change of y with respect to x for y = 3x² at x = 2', 'text', 1, 'differentiate then substitute', '{"why":"Rate of change is found using differentiation and substitution","sol":"Step 1: Start with y = 3x²\nStep 2: Differentiate → dy/dx = 6x\nStep 3: Substitute x = 2\nStep 4: Compute 6 × 2\nStep 5: Final value of rate of change","steps":["Step 1: Start with y = 3x²","Step 2: Differentiate → dy/dx = 6x","Step 3: Substitute x = 2","Step 4: Compute 6 × 2","Step 5: Final value of rate of change"],"options":[],"conceptId":"math_calculus_rate_of_change","skillId":"math_calculus","subskillId":"math_calculus_q1","subject":"math","chapter":"calculus","topic":"Rate of Change"}', 0),
  (1165, 347, 'Find dy/dx for y = 5x at any point', 'text', 1, 'linear rule', '{"why":"Linear functions have constant rate of change equal to slope","sol":"Step 1: Identify y = mx form\nStep 2: Differentiate → dy/dx = 5\nStep 3: Note constant slope\nStep 4: State rate of change","steps":["Step 1: Identify y = mx form","Step 2: Differentiate → dy/dx = 5","Step 3: Note constant slope","Step 4: State rate of change"],"options":[],"conceptId":"math_calculus_rate_of_change","skillId":"math_calculus","subskillId":"math_calculus_q2","subject":"math","chapter":"calculus","topic":"Rate of Change"}', 1),
  (1166, 347, 'A car travels distance s = 4t². Find speed at t = 3', 'text', 1, 'differentiate distance', '{"why":"Speed is rate of change of distance with respect to time","sol":"Step 1: Start with s = 4t²\nStep 2: Differentiate → ds/dt = 8t\nStep 3: Substitute t = 3\nStep 4: Compute 8 × 3\nStep 5: Final speed value","steps":["Step 1: Start with s = 4t²","Step 2: Differentiate → ds/dt = 8t","Step 3: Substitute t = 3","Step 4: Compute 8 × 3","Step 5: Final speed value"],"options":[],"conceptId":"math_calculus_rate_of_change","skillId":"math_calculus","subskillId":"math_calculus_q3","subject":"math","chapter":"calculus","topic":"Rate of Change"}', 2),
  (1167, 347, 'Find rate of change of y = x³ at x = 1', 'text', 1, 'power rule', '{"why":"Derivative gives instantaneous rate of change","sol":"Step 1: Differentiate y = x³ → dy/dx = 3x²\nStep 2: Substitute x = 1\nStep 3: Compute 3 × 1²\nStep 4: Final value","steps":["Step 1: Differentiate y = x³ → dy/dx = 3x²","Step 2: Substitute x = 1","Step 3: Compute 3 × 1²","Step 4: Final value"],"options":[],"conceptId":"math_calculus_rate_of_change","skillId":"math_calculus","subskillId":"math_calculus_q4","subject":"math","chapter":"calculus","topic":"Rate of Change"}', 3),
  (1168, 348, 'Find turning point and determine maximum/minimum for y = -x² + 6x - 5', 'text', 1, 'differentiate and classify', '{"why":"Negative x² means the parabola opens downward, giving a maximum","sol":"Step 1: Differentiate y = -x² + 6x - 5 → dy/dx = -2x + 6\nStep 2: Set dy/dx = 0 → -2x + 6 = 0\nStep 3: Solve → 2x = 6\nStep 4: x = 3\nStep 5: Since coefficient of x² is negative, curve opens downward\nStep 6: Therefore turning point is a maximum","steps":["Step 1: Differentiate y = -x² + 6x - 5 → dy/dx = -2x + 6","Step 2: Set dy/dx = 0 → -2x + 6 = 0","Step 3: Solve → 2x = 6","Step 4: x = 3","Step 5: Since coefficient of x² is negative, curve opens downward","Step 6: Therefore turning point is a maximum"],"options":[],"conceptId":"math_calculus_maxima_and_minima","skillId":"math_calculus","subskillId":"math_calculus_q1","subject":"math","chapter":"calculus","topic":"Maxima and Minima"}', 0),
  (1169, 348, 'Find maximum point of y = -2x² + 8x + 1', 'text', 1, 'dy/dx = 0', '{"why":"Vertex gives highest value because parabola opens downward","sol":"Step 1: Differentiate → dy/dx = -4x + 8\nStep 2: Set dy/dx = 0 → -4x + 8 = 0\nStep 3: Solve → 4x = 8\nStep 4: x = 2\nStep 5: Substitute into original function → y = -2(2²) + 8(2) + 1\nStep 6: y = -8 + 16 + 1 = 9","steps":["Step 1: Differentiate → dy/dx = -4x + 8","Step 2: Set dy/dx = 0 → -4x + 8 = 0","Step 3: Solve → 4x = 8","Step 4: x = 2","Step 5: Substitute into original function → y = -2(2²) + 8(2) + 1","Step 6: y = -8 + 16 + 1 = 9"],"options":[],"conceptId":"math_calculus_maxima_and_minima","skillId":"math_calculus","subskillId":"math_calculus_q2","subject":"math","chapter":"calculus","topic":"Maxima and Minima"}', 1),
  (1170, 348, 'Find minimum point of y = x² + 8x + 12', 'text', 1, 'complete or differentiate', '{"why":"Positive x² means parabola opens upward giving a minimum","sol":"Step 1: Differentiate → dy/dx = 2x + 8\nStep 2: Set dy/dx = 0 → 2x + 8 = 0\nStep 3: Solve → 2x = -8\nStep 4: x = -4\nStep 5: Substitute into function → y = (-4)² + 8(-4) + 12\nStep 6: y = 16 - 32 + 12 = -4","steps":["Step 1: Differentiate → dy/dx = 2x + 8","Step 2: Set dy/dx = 0 → 2x + 8 = 0","Step 3: Solve → 2x = -8","Step 4: x = -4","Step 5: Substitute into function → y = (-4)² + 8(-4) + 12","Step 6: y = 16 - 32 + 12 = -4"],"options":[],"conceptId":"math_calculus_maxima_and_minima","skillId":"math_calculus","subskillId":"math_calculus_q3","subject":"math","chapter":"calculus","topic":"Maxima and Minima"}', 2),
  (1171, 348, 'Find stationary point of y = x² - 10x + 25 and classify it', 'text', 1, 'perfect square form', '{"why":"Perfect square quadratic always has a minimum vertex","sol":"Step 1: Differentiate → dy/dx = 2x - 10\nStep 2: Set dy/dx = 0 → 2x - 10 = 0\nStep 3: Solve → 2x = 10\nStep 4: x = 5\nStep 5: Substitute → y = 25 - 50 + 25 = 0\nStep 6: Since coefficient of x² is positive, it is a minimum","steps":["Step 1: Differentiate → dy/dx = 2x - 10","Step 2: Set dy/dx = 0 → 2x - 10 = 0","Step 3: Solve → 2x = 10","Step 4: x = 5","Step 5: Substitute → y = 25 - 50 + 25 = 0","Step 6: Since coefficient of x² is positive, it is a minimum"],"options":[],"conceptId":"math_calculus_maxima_and_minima","skillId":"math_calculus","subskillId":"math_calculus_q4","subject":"math","chapter":"calculus","topic":"Maxima and Minima"}', 3),
  (1172, 348, 'Find maximum value of y = 3x - x²', 'text', 1, 'rearrange quadratic', '{"why":"Negative x² ensures a maximum at vertex","sol":"Step 1: Rewrite y = -x² + 3x\nStep 2: Differentiate → dy/dx = -2x + 3\nStep 3: Set dy/dx = 0 → -2x + 3 = 0\nStep 4: Solve → 2x = 3\nStep 5: x = 3/2\nStep 6: Substitute → y = 3(3/2) - (3/2)²\nStep 7: y = 9/2 - 9/4 = 9/4","steps":["Step 1: Rewrite y = -x² + 3x","Step 2: Differentiate → dy/dx = -2x + 3","Step 3: Set dy/dx = 0 → -2x + 3 = 0","Step 4: Solve → 2x = 3","Step 5: x = 3/2","Step 6: Substitute → y = 3(3/2) - (3/2)²","Step 7: y = 9/2 - 9/4 = 9/4"],"options":[],"conceptId":"math_calculus_maxima_and_minima","skillId":"math_calculus","subskillId":"math_calculus_q5","subject":"math","chapter":"calculus","topic":"Maxima and Minima"}', 4),
  (1173, 349, 'Find slope of tangent to y = x² at x = 4', 'text', 1, 'differentiate and substitute', '{"why":"Derivative gives slope of tangent at a point","sol":"Step 1: Differentiate y = x² → dy/dx = 2x\nStep 2: Substitute x = 4\nStep 3: Compute 2 × 4\nStep 4: Final slope value","steps":["Step 1: Differentiate y = x² → dy/dx = 2x","Step 2: Substitute x = 4","Step 3: Compute 2 × 4","Step 4: Final slope value"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q1","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 0),
  (1174, 349, 'If tangent slope is 3, what is slope of normal?', 'text', 1, 'negative reciprocal', '{"why":"Perpendicular lines have slopes that multiply to -1","sol":"Step 1: Identify tangent slope m = 3\nStep 2: Use formula slope(normal) = -1/m\nStep 3: Compute -1/3\nStep 4: Final result","steps":["Step 1: Identify tangent slope m = 3","Step 2: Use formula slope(normal) = -1/m","Step 3: Compute -1/3","Step 4: Final result"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q2","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 1),
  (1175, 349, 'Find equation of tangent to y = x² at (2, 4)', 'text', 1, 'point-slope form', '{"why":"Tangent is a straight line touching the curve at a point","sol":"Step 1: Differentiate to find slope at x = 2\nStep 2: dy/dx = 2x → slope = 4\nStep 3: Use point (2, 4) and slope 4\nStep 4: Equation: y - 4 = 4(x - 2)\nStep 5: Simplify → y = 4x - 4","steps":["Step 1: Differentiate to find slope at x = 2","Step 2: dy/dx = 2x → slope = 4","Step 3: Use point (2, 4) and slope 4","Step 4: Equation: y - 4 = 4(x - 2)","Step 5: Simplify → y = 4x - 4"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q3","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 2),
  (1176, 349, 'Find equation of tangent slope for y = x² at x = 2', 'text', 1, 'differentiate then substitute', '{"why":"Tangent slope is found using derivative at a point","sol":"Step 1: Differentiate y = x² → dy/dx = 2x\nStep 2: Substitute x = 2\nStep 3: Compute 2 × 2\nStep 4: Tangent slope = 4","steps":["Step 1: Differentiate y = x² → dy/dx = 2x","Step 2: Substitute x = 2","Step 3: Compute 2 × 2","Step 4: Tangent slope = 4"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q4","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 3),
  (1177, 349, 'Find equation of normal slope if tangent slope is 3', 'text', 1, 'negative reciprocal', '{"why":"Normal is perpendicular to tangent, so slopes multiply to -1","sol":"Step 1: Identify tangent slope m = 3\nStep 2: Apply normal formula = -1/m\nStep 3: Substitute values → -1/3\nStep 4: Simplify result","steps":["Step 1: Identify tangent slope m = 3","Step 2: Apply normal formula = -1/m","Step 3: Substitute values → -1/3","Step 4: Simplify result"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q5","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 4),
  (1178, 349, 'Find slope of tangent for y = 3x² + 2x at x = 1', 'text', 1, 'differentiate first', '{"why":"Derivative gives slope of tangent at a point","sol":"Step 1: Differentiate y → dy/dx = 6x + 2\nStep 2: Substitute x = 1\nStep 3: Compute 6(1) + 2\nStep 4: Final slope = 8","steps":["Step 1: Differentiate y → dy/dx = 6x + 2","Step 2: Substitute x = 1","Step 3: Compute 6(1) + 2","Step 4: Final slope = 8"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q6","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 5),
  (1179, 349, 'Find normal slope if tangent slope is -5', 'text', 1, 'negative reciprocal rule', '{"why":"Normal is perpendicular so slope is negative reciprocal","sol":"Step 1: Tangent slope m = -5\nStep 2: Apply formula -1/m\nStep 3: Compute -1 / (-5)\nStep 4: Simplify result","steps":["Step 1: Tangent slope m = -5","Step 2: Apply formula -1/m","Step 3: Compute -1 / (-5)","Step 4: Simplify result"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q7","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 6),
  (1180, 349, 'Find equation of tangent to y = x² at point (2, 4)', 'text', 1, 'first find slope, then use point-slope form', '{"why":"Tangent is a line touching curve at a point; its slope is the derivative value at that point","sol":"Step 1: Differentiate y = x² → dy/dx = 2x\nStep 2: Substitute x = 2 → slope m = 4\nStep 3: Use point (2, 4) in y - y₁ = m(x - x₁)\nStep 4: Equation becomes y - 4 = 4(x - 2)\nStep 5: Simplify → y = 4x - 4","steps":["Step 1: Differentiate y = x² → dy/dx = 2x","Step 2: Substitute x = 2 → slope m = 4","Step 3: Use point (2, 4) in y - y₁ = m(x - x₁)","Step 4: Equation becomes y - 4 = 4(x - 2)","Step 5: Simplify → y = 4x - 4"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q8","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 7),
  (1181, 349, 'Find equation of normal to y = x² at (2, 4)', 'text', 1, 'use perpendicular slope', '{"why":"Normal is perpendicular to tangent at the same point, hence negative reciprocal slope","sol":"Step 1: Slope of tangent at x = 2 is m = 4\nStep 2: Normal slope is perpendicular → -1/4\nStep 3: Use point (2, 4) in y - y₁ = m(x - x₁)\nStep 4: Equation: y - 4 = -1/4(x - 2)\nStep 5: Simplify to standard form","steps":["Step 1: Slope of tangent at x = 2 is m = 4","Step 2: Normal slope is perpendicular → -1/4","Step 3: Use point (2, 4) in y - y₁ = m(x - x₁)","Step 4: Equation: y - 4 = -1/4(x - 2)","Step 5: Simplify to standard form"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q9","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 8),
  (1182, 349, 'Find x-intercept of tangent to y = x² at x = 3', 'text', 1, 'first find tangent equation', '{"why":"The tangent line has a specific slope and passes through the point, allowing its intercepts to be calculated","sol":"Step 1: Differentiate y = x² → dy/dx = 2x\nStep 2: At x = 3, slope m = 2(3) = 6\nStep 3: Point is (3, 3²) = (3, 9)\nStep 4: Tangent equation: y - 9 = 6(x - 3)\nStep 5: Set y = 0 to find x-intercept → -9 = 6x - 18\nStep 6: Solve for x → x = 9/6 = 3/2","steps":["Step 1: Differentiate y = x² → dy/dx = 2x","Step 2: At x = 3, slope m = 2(3) = 6","Step 3: Point is (3, 3²) = (3, 9)","Step 4: Tangent equation: y - 9 = 6(x - 3)","Step 5: Set y = 0 to find x-intercept → -9 = 6x - 18","Step 6: Solve for x → x = 9/6 = 3/2"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q10","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 9),
  (1183, 349, 'At what x-value is tangent to y = x² parallel to line y = 4x + 1?', 'text', 1, 'slopes must be equal', '{"why":"Parallel lines have equal slopes, so we equate tangent slope to line slope and solve for x","sol":"Step 1: Slope of given line is 4\nStep 2: Slope of tangent is derivative dy/dx = 2x\nStep 3: Set slopes equal → 2x = 4\nStep 4: Solve for x → x = 2","steps":["Step 1: Slope of given line is 4","Step 2: Slope of tangent is derivative dy/dx = 2x","Step 3: Set slopes equal → 2x = 4","Step 4: Solve for x → x = 2"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q11","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 10),
  (1184, 349, 'Find the perpendicular distance from origin (0, 0) to tangent of y = x² at x = 4', 'text', 1, 'find tangent equation first', '{"why":"Perpendicular distance formula is used to find distance from origin to the calculated tangent line","sol":"Step 1: At x = 4, slope m = 2(4) = 8\nStep 2: Point is (4, 4²) = (4, 16)\nStep 3: Tangent equation: y - 16 = 8(x - 4) → 8x - y - 16 = 0\nStep 4: Use distance formula from point (x₀, y₀) to line Ax + By + C = 0: distance = |Ax₀ + By₀ + C| / sqrt(A² + B²)\nStep 5: For origin (0, 0) and line 8x - y - 16 = 0 → distance = |-16| / sqrt(8² + (-1)²)\nStep 6: Simplify → distance = 16 / sqrt(65)","steps":["Step 1: At x = 4, slope m = 2(4) = 8","Step 2: Point is (4, 4²) = (4, 16)","Step 3: Tangent equation: y - 16 = 8(x - 4) → 8x - y - 16 = 0","Step 4: Use distance formula from point (x₀, y₀) to line Ax + By + C = 0: distance = |Ax₀ + By₀ + C| / sqrt(A² + B²)","Step 5: For origin (0, 0) and line 8x - y - 16 = 0 → distance = |-16| / sqrt(8² + (-1)²)","Step 6: Simplify → distance = 16 / sqrt(65)"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q12","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 11),
  (1185, 350, 'Why is differentiation important?', 'text', 1, 'rate of change', '{"why":"It quantifies how one variable changes with respect to another","sol":"Step 1: Identify key concept: Define the required principles for Applications of Differentiation.\nStep 2: Apply governing rule: It quantifies how one variable changes with respect to another\nStep 3: State the final conclusion: measures change","steps":["Step 1: Identify key concept: Define the required principles for Applications of Differentiation.","Step 2: Apply governing rule: It quantifies how one variable changes with respect to another","Step 3: State the final conclusion: measures change"],"options":[],"conceptId":"math_calculus_applications_of_differentiation","skillId":"math_calculus","subskillId":"math_calculus_q1","subject":"math","chapter":"calculus","topic":"Applications of Differentiation"}', 0),
  (1186, 350, 'Give real-life use', 'text', 1, 'motion or business', '{"why":"Used in physics for velocity and in economics for maximizing profit","sol":"Step 1: Identify key concept: Define the required principles for Applications of Differentiation.\nStep 2: Apply governing rule: Used in physics for velocity and in economics for maximizing profit\nStep 3: State the final conclusion: speed or profit optimization","steps":["Step 1: Identify key concept: Define the required principles for Applications of Differentiation.","Step 2: Apply governing rule: Used in physics for velocity and in economics for maximizing profit","Step 3: State the final conclusion: speed or profit optimization"],"options":[],"conceptId":"math_calculus_applications_of_differentiation","skillId":"math_calculus","subskillId":"math_calculus_q2","subject":"math","chapter":"calculus","topic":"Applications of Differentiation"}', 1),
  (1187, 350, 'What does f''(x) represent?', 'text', 1, 'derivative meaning', '{"why":"It represents instantaneous rate of change of a function","sol":"Step 1: Identify key concept: Define the required principles for Applications of Differentiation.\nStep 2: Apply governing rule: It represents instantaneous rate of change of a function\nStep 3: State the final conclusion: rate of change or slope","steps":["Step 1: Identify key concept: Define the required principles for Applications of Differentiation.","Step 2: Apply governing rule: It represents instantaneous rate of change of a function","Step 3: State the final conclusion: rate of change or slope"],"options":[],"conceptId":"math_calculus_applications_of_differentiation","skillId":"math_calculus","subskillId":"math_calculus_q3","subject":"math","chapter":"calculus","topic":"Applications of Differentiation"}', 2),
  (1188, 351, 'Evaluate ∫ x dx', 'text', 1, 'power rule integration', '{"why":"Integration is reverse of differentiation using power rule","sol":"Step 1: Increase power of x by 1 → x¹ becomes x²\nStep 2: Divide by new power → x² / 2\nStep 3: Add constant of integration C\nStep 4: Final expression","steps":["Step 1: Increase power of x by 1 → x¹ becomes x²","Step 2: Divide by new power → x² / 2","Step 3: Add constant of integration C","Step 4: Final expression"],"options":[],"conceptId":"math_calculus_area_under_a_curve","skillId":"math_calculus","subskillId":"math_calculus_q1","subject":"math","chapter":"calculus","topic":"Area Under a Curve"}', 0),
  (1189, 351, 'Evaluate ∫ x² dx', 'text', 1, 'increase power', '{"why":"Power rule: add 1 to exponent then divide","sol":"Step 1: Increase exponent → x² becomes x³\nStep 2: Divide by new exponent → x³ / 3\nStep 3: Add constant C\nStep 4: Write final result","steps":["Step 1: Increase exponent → x² becomes x³","Step 2: Divide by new exponent → x³ / 3","Step 3: Add constant C","Step 4: Write final result"],"options":[],"conceptId":"math_calculus_area_under_a_curve","skillId":"math_calculus","subskillId":"math_calculus_q2","subject":"math","chapter":"calculus","topic":"Area Under a Curve"}', 1),
  (1190, 351, 'Evaluate definite integral ∫ from 0 to 2 of x dx', 'text', 1, 'area under curve', '{"why":"Definite integrals give net area under curve","sol":"Step 1: Find integral of x → x²/2\nStep 2: Substitute upper limit 2 → (2²)/2 = 4/2 = 2\nStep 3: Substitute lower limit 0 → 0²/2 = 0\nStep 4: Subtract upper - lower → 2 - 0\nStep 5: Final answer","steps":["Step 1: Find integral of x → x²/2","Step 2: Substitute upper limit 2 → (2²)/2 = 4/2 = 2","Step 3: Substitute lower limit 0 → 0²/2 = 0","Step 4: Subtract upper - lower → 2 - 0","Step 5: Final answer"],"options":[],"conceptId":"math_calculus_area_under_a_curve","skillId":"math_calculus","subskillId":"math_calculus_q3","subject":"math","chapter":"calculus","topic":"Area Under a Curve"}', 2),
  (1191, 351, 'Evaluate ∫ 3x² dx', 'text', 1, 'constant multiple rule', '{"why":"Constant multiples remain unchanged in integration","sol":"Step 1: Keep constant 3 outside\nStep 2: Integrate x² → x³/3\nStep 3: Multiply → 3 × (x³/3)\nStep 4: Simplify expression\nStep 5: Add +C","steps":["Step 1: Keep constant 3 outside","Step 2: Integrate x² → x³/3","Step 3: Multiply → 3 × (x³/3)","Step 4: Simplify expression","Step 5: Add +C"],"options":[],"conceptId":"math_calculus_area_under_a_curve","skillId":"math_calculus","subskillId":"math_calculus_q4","subject":"math","chapter":"calculus","topic":"Area Under a Curve"}', 3),
  (1192, 352, 'Evaluate ∫ x dx', 'text', 1, 'power rule integration', '{"why":"Integration is reverse of differentiation using power rule","sol":"Step 1: Increase power of x by 1 → x¹ becomes x²\nStep 2: Divide by new power → x² / 2\nStep 3: Add constant of integration C\nStep 4: Final expression","steps":["Step 1: Increase power of x by 1 → x¹ becomes x²","Step 2: Divide by new power → x² / 2","Step 3: Add constant of integration C","Step 4: Final expression"],"options":[],"conceptId":"math_calculus_indefinite_integrals","skillId":"math_calculus","subskillId":"math_calculus_q1","subject":"math","chapter":"calculus","topic":"Indefinite Integrals"}', 0),
  (1193, 352, 'Evaluate ∫ x² dx', 'text', 1, 'increase power', '{"why":"Power rule: add 1 to exponent then divide","sol":"Step 1: Increase exponent → x² becomes x³\nStep 2: Divide by new exponent → x³ / 3\nStep 3: Add constant C\nStep 4: Write final result","steps":["Step 1: Increase exponent → x² becomes x³","Step 2: Divide by new exponent → x³ / 3","Step 3: Add constant C","Step 4: Write final result"],"options":[],"conceptId":"math_calculus_indefinite_integrals","skillId":"math_calculus","subskillId":"math_calculus_q2","subject":"math","chapter":"calculus","topic":"Indefinite Integrals"}', 1),
  (1194, 352, 'Evaluate definite integral ∫ from 0 to 2 of x dx', 'text', 1, 'area under curve', '{"why":"Definite integrals give net area under curve","sol":"Step 1: Find integral of x → x²/2\nStep 2: Substitute upper limit 2 → (2²)/2 = 4/2 = 2\nStep 3: Substitute lower limit 0 → 0²/2 = 0\nStep 4: Subtract upper - lower → 2 - 0\nStep 5: Final answer","steps":["Step 1: Find integral of x → x²/2","Step 2: Substitute upper limit 2 → (2²)/2 = 4/2 = 2","Step 3: Substitute lower limit 0 → 0²/2 = 0","Step 4: Subtract upper - lower → 2 - 0","Step 5: Final answer"],"options":[],"conceptId":"math_calculus_indefinite_integrals","skillId":"math_calculus","subskillId":"math_calculus_q3","subject":"math","chapter":"calculus","topic":"Indefinite Integrals"}', 2),
  (1195, 352, 'Evaluate ∫ 3x² dx', 'text', 1, 'constant multiple rule', '{"why":"Constant multiples remain unchanged in integration","sol":"Step 1: Keep constant 3 outside\nStep 2: Integrate x² → x³/3\nStep 3: Multiply → 3 × (x³/3)\nStep 4: Simplify expression\nStep 5: Add +C","steps":["Step 1: Keep constant 3 outside","Step 2: Integrate x² → x³/3","Step 3: Multiply → 3 × (x³/3)","Step 4: Simplify expression","Step 5: Add +C"],"options":[],"conceptId":"math_calculus_indefinite_integrals","skillId":"math_calculus","subskillId":"math_calculus_q4","subject":"math","chapter":"calculus","topic":"Indefinite Integrals"}', 3),
  (1196, 352, 'Why does integration represent area under a curve?', 'text', 1, 'limit of rectangles', '{"why":"Integration is the limit of summing thin rectangles","sol":"Step 1: Divide area under curve into small rectangles\nStep 2: Approximate each rectangle’s area\nStep 3: Increase number of rectangles\nStep 4: Make width approach zero\nStep 5: Sum becomes exact area","steps":["Step 1: Divide area under curve into small rectangles","Step 2: Approximate each rectangle’s area","Step 3: Increase number of rectangles","Step 4: Make width approach zero","Step 5: Sum becomes exact area"],"options":[],"conceptId":"math_calculus_indefinite_integrals","skillId":"math_calculus","subskillId":"math_calculus_q5","subject":"math","chapter":"calculus","topic":"Indefinite Integrals"}', 4),
  (1197, 353, 'Evaluate definite integral ∫ from 1 to 2 of x dx', 'text', 1, 'definite integral with limits', '{"why":"Definite integrals calculate net area under a curve between two points","sol":"Step 1: Find antiderivative of x → x²/2\nStep 2: Substitute upper limit 2 → (2²)/2 = 4/2 = 2\nStep 3: Substitute lower limit 1 → (1²)/2 = 1/2\nStep 4: Subtract upper limit value from lower limit value\nStep 5: Result = 2 - 1/2 = 3/2","steps":["Step 1: Find antiderivative of x → x²/2","Step 2: Substitute upper limit 2 → (2²)/2 = 4/2 = 2","Step 3: Substitute lower limit 1 → (1²)/2 = 1/2","Step 4: Subtract upper limit value from lower limit value","Step 5: Result = 2 - 1/2 = 3/2"],"options":[],"conceptId":"math_calculus_definite_integrals","skillId":"math_calculus","subskillId":"math_calculus_q1","subject":"math","chapter":"calculus","topic":"Definite Integrals"}', 0),
  (1198, 353, 'Find area under y = x² from 0 to 3', 'text', 1, 'use definite integral', '{"why":"Definite integral of a function over an interval gives the area under that curve","sol":"Step 1: Set up integral ∫ from 0 to 3 of x² dx\nStep 2: Integrate x² → x³/3\nStep 3: Apply limits → (3³/3) - (0³/3)\nStep 4: Simplify → 27/3 - 0\nStep 5: Final area = 9","steps":["Step 1: Set up integral ∫ from 0 to 3 of x² dx","Step 2: Integrate x² → x³/3","Step 3: Apply limits → (3³/3) - (0³/3)","Step 4: Simplify → 27/3 - 0","Step 5: Final area = 9"],"options":[],"conceptId":"math_calculus_definite_integrals","skillId":"math_calculus","subskillId":"math_calculus_q2","subject":"math","chapter":"calculus","topic":"Definite Integrals"}', 1),
  (1199, 353, 'Evaluate ∫ from 0 to 1 of (2x + 1) dx', 'text', 1, 'integrate term by term', '{"why":"Integrate each term separately and evaluate over the given interval","sol":"Step 1: Integrate 2x → x²\nStep 2: Integrate 1 → x\nStep 3: Combine → x² + x\nStep 4: Apply limits [0, 1] → (1² + 1) - (0² + 0)\nStep 5: Result = 2 - 0 = 2","steps":["Step 1: Integrate 2x → x²","Step 2: Integrate 1 → x","Step 3: Combine → x² + x","Step 4: Apply limits [0, 1] → (1² + 1) - (0² + 0)","Step 5: Result = 2 - 0 = 2"],"options":[],"conceptId":"math_calculus_definite_integrals","skillId":"math_calculus","subskillId":"math_calculus_q3","subject":"math","chapter":"calculus","topic":"Definite Integrals"}', 2),
  (1200, 353, 'What is difference between ∫ x dx and ∫₀¹ x dx?', 'text', 1, 'limits vs no limits', '{"why":"Limits define the interval and produce a single value instead of a function","sol":"Step 1: ∫ x dx has no limits\nStep 2: Result is family of functions → x²/2 + C\nStep 3: ∫₀¹ x dx has limits\nStep 4: Result is numerical value → 1/2\nStep 5: Compare both results","steps":["Step 1: ∫ x dx has no limits","Step 2: Result is family of functions → x²/2 + C","Step 3: ∫₀¹ x dx has limits","Step 4: Result is numerical value → 1/2","Step 5: Compare both results"],"options":[],"conceptId":"math_calculus_definite_integrals","skillId":"math_calculus","subskillId":"math_calculus_q4","subject":"math","chapter":"calculus","topic":"Definite Integrals"}', 3),
  (1201, 354, 'Find ∫ (2x) dx and verify relationship with differentiation', 'text', 1, 'reverse of derivative', '{"why":"Integration reverses differentiation","sol":"Step 1: Recognize 2x as derivative of x²\nStep 2: Apply integration rule → increase power of x\nStep 3: ∫ 2x dx = x² + C\nStep 4: Differentiate result → d/dx(x² + C)\nStep 5: Get 2x (original function)","steps":["Step 1: Recognize 2x as derivative of x²","Step 2: Apply integration rule → increase power of x","Step 3: ∫ 2x dx = x² + C","Step 4: Differentiate result → d/dx(x² + C)","Step 5: Get 2x (original function)"],"options":[],"conceptId":"math_calculus_integration_as_reverse_of_differentiation","skillId":"math_calculus","subskillId":"math_calculus_q1","subject":"math","chapter":"calculus","topic":"Integration as Reverse of Differentiation"}', 0),
  (1202, 354, 'Find function if ∫ f(x) dx = x³/3 + C', 'text', 1, 'differentiate result', '{"why":"Differentiation reverses integration","sol":"Step 1: Differentiate both sides\nStep 2: d/dx (x³/3 + C)\nStep 3: Apply power rule → (3x²)/3\nStep 4: Simplify result\nStep 5: Get f(x)","steps":["Step 1: Differentiate both sides","Step 2: d/dx (x³/3 + C)","Step 3: Apply power rule → (3x²)/3","Step 4: Simplify result","Step 5: Get f(x)"],"options":[],"conceptId":"math_calculus_integration_as_reverse_of_differentiation","skillId":"math_calculus","subskillId":"math_calculus_q2","subject":"math","chapter":"calculus","topic":"Integration as Reverse of Differentiation"}', 1),
  (1203, 354, 'Show that integration adds a constant using ∫ 0 dx', 'text', 1, 'constant rule', '{"why":"Derivative removes constants, integration restores them","sol":"Step 1: Integrate 0 → ∫ 0 dx\nStep 2: Result is constant C\nStep 3: Differentiate C\nStep 4: d/dx(C) = 0\nStep 5: Confirm relationship","steps":["Step 1: Integrate 0 → ∫ 0 dx","Step 2: Result is constant C","Step 3: Differentiate C","Step 4: d/dx(C) = 0","Step 5: Confirm relationship"],"options":[],"conceptId":"math_calculus_integration_as_reverse_of_differentiation","skillId":"math_calculus","subskillId":"math_calculus_q3","subject":"math","chapter":"calculus","topic":"Integration as Reverse of Differentiation"}', 2),
  (1204, 354, 'If d/dx (x² + 5) = 2x, find integral of 2x', 'text', 1, 'inverse process', '{"why":"Integration reconstructs original function up to a constant","sol":"Step 1: Recognize 2x as derivative of x²\nStep 2: Integrate 2x → x²\nStep 3: Add constant C\nStep 4: Final expression","steps":["Step 1: Recognize 2x as derivative of x²","Step 2: Integrate 2x → x²","Step 3: Add constant C","Step 4: Final expression"],"options":[],"conceptId":"math_calculus_integration_as_reverse_of_differentiation","skillId":"math_calculus","subskillId":"math_calculus_q4","subject":"math","chapter":"calculus","topic":"Integration as Reverse of Differentiation"}', 3),
  (1205, 355, 'Find ∫ (2x) dx and verify relationship with differentiation', 'text', 1, 'reverse of derivative', '{"why":"Integration reverses differentiation","sol":"Step 1: Recognize 2x as derivative of x²\nStep 2: Apply integration rule → increase power of x\nStep 3: ∫ 2x dx = x² + C\nStep 4: Differentiate result → d/dx(x² + C)\nStep 5: Get 2x (original function)","steps":["Step 1: Recognize 2x as derivative of x²","Step 2: Apply integration rule → increase power of x","Step 3: ∫ 2x dx = x² + C","Step 4: Differentiate result → d/dx(x² + C)","Step 5: Get 2x (original function)"],"options":[],"conceptId":"math_calculus_applications_of_integration","skillId":"math_calculus","subskillId":"math_calculus_q1","subject":"math","chapter":"calculus","topic":"Applications of Integration"}', 0),
  (1206, 355, 'Find function if ∫ f(x) dx = x³/3 + C', 'text', 1, 'differentiate result', '{"why":"Differentiation reverses integration","sol":"Step 1: Differentiate both sides\nStep 2: d/dx (x³/3 + C)\nStep 3: Apply power rule → (3x²)/3\nStep 4: Simplify result\nStep 5: Get f(x)","steps":["Step 1: Differentiate both sides","Step 2: d/dx (x³/3 + C)","Step 3: Apply power rule → (3x²)/3","Step 4: Simplify result","Step 5: Get f(x)"],"options":[],"conceptId":"math_calculus_applications_of_integration","skillId":"math_calculus","subskillId":"math_calculus_q2","subject":"math","chapter":"calculus","topic":"Applications of Integration"}', 1),
  (1207, 355, 'Show that integration adds a constant using ∫ 0 dx', 'text', 1, 'constant rule', '{"why":"Derivative removes constants, integration restores them","sol":"Step 1: Integrate 0 → ∫ 0 dx\nStep 2: Result is constant C\nStep 3: Differentiate C\nStep 4: d/dx(C) = 0\nStep 5: Confirm relationship","steps":["Step 1: Integrate 0 → ∫ 0 dx","Step 2: Result is constant C","Step 3: Differentiate C","Step 4: d/dx(C) = 0","Step 5: Confirm relationship"],"options":[],"conceptId":"math_calculus_applications_of_integration","skillId":"math_calculus","subskillId":"math_calculus_q3","subject":"math","chapter":"calculus","topic":"Applications of Integration"}', 2),
  (1208, 355, 'If d/dx (x² + 5) = 2x, find integral of 2x', 'text', 1, 'inverse process', '{"why":"Integration reconstructs original function up to a constant","sol":"Step 1: Recognize 2x as derivative of x²\nStep 2: Integrate 2x → x²\nStep 3: Add constant C\nStep 4: Final expression","steps":["Step 1: Recognize 2x as derivative of x²","Step 2: Integrate 2x → x²","Step 3: Add constant C","Step 4: Final expression"],"options":[],"conceptId":"math_calculus_applications_of_integration","skillId":"math_calculus","subskillId":"math_calculus_q4","subject":"math","chapter":"calculus","topic":"Applications of Integration"}', 3),
  (1209, 356, 'What is a force?', 'text', 1, 'Think of an interaction involving a push or pull.', '{"why":"Forces can change motion or deform objects.","sol":"Step 1: Identify key concept: Define the required principles for Meaning of Force.\nStep 2: Apply governing rule: Forces can change motion or deform objects.\nStep 3: State the final conclusion: A force is a push or pull arising from an interaction between objects.","steps":["Step 1: Identify key concept: Define the required principles for Meaning of Force.","Step 2: Apply governing rule: Forces can change motion or deform objects.","Step 3: State the final conclusion: A force is a push or pull arising from an interaction between objects."],"options":[],"conceptId":"physics_force_meaning_of_force","skillId":"physics_force","subskillId":"physics_force_q1","subject":"physics","chapter":"force","topic":"Meaning of Force"}', 0),
  (1210, 356, 'State three possible effects of a force.', 'text', 1, 'Consider speed, direction and shape.', '{"why":"These are distinct effects; a force need not produce all of them.","sol":"Step 1: Identify key concept: Define the required principles for Meaning of Force.\nStep 2: Apply governing rule: These are distinct effects; a force need not produce all of them.\nStep 3: State the final conclusion: A force can change speed, change direction, or change an object''s shape.","steps":["Step 1: Identify key concept: Define the required principles for Meaning of Force.","Step 2: Apply governing rule: These are distinct effects; a force need not produce all of them.","Step 3: State the final conclusion: A force can change speed, change direction, or change an object''s shape."],"options":[],"conceptId":"physics_force_meaning_of_force","skillId":"physics_force","subskillId":"physics_force_q2","subject":"physics","chapter":"force","topic":"Meaning of Force"}', 1),
  (1211, 356, 'What is the SI unit of force?', 'text', 1, 'It is named after a scientist.', '{"why":"Force is measured in newtons, not kilograms.","sol":"Step 1: Identify key concept: Define the required principles for Meaning of Force.\nStep 2: Apply governing rule: Force is measured in newtons, not kilograms.\nStep 3: State the final conclusion: The newton (N).","steps":["Step 1: Identify key concept: Define the required principles for Meaning of Force.","Step 2: Apply governing rule: Force is measured in newtons, not kilograms.","Step 3: State the final conclusion: The newton (N)."],"options":[],"conceptId":"physics_force_meaning_of_force","skillId":"physics_force","subskillId":"physics_force_q3","subject":"physics","chapter":"force","topic":"Meaning of Force"}', 2),
  (1212, 356, 'Why is force described as a vector quantity?', 'text', 1, 'What two pieces of information describe a force?', '{"why":"Equal forces in opposite directions have different vector directions.","sol":"Step 1: Identify key concept: Define the required principles for Meaning of Force.\nStep 2: Apply governing rule: Equal forces in opposite directions have different vector directions.\nStep 3: State the final conclusion: Because force has both magnitude and direction.","steps":["Step 1: Identify key concept: Define the required principles for Meaning of Force.","Step 2: Apply governing rule: Equal forces in opposite directions have different vector directions.","Step 3: State the final conclusion: Because force has both magnitude and direction."],"options":[],"conceptId":"physics_force_meaning_of_force","skillId":"physics_force","subskillId":"physics_force_q4","subject":"physics","chapter":"force","topic":"Meaning of Force"}', 3),
  (1213, 356, 'A student pushes a heavy wall, but it does not move. Does this prove that no force was applied?', 'text', 1, 'Separate the presence of a force from the resulting motion.', '{"why":"A force can act without producing motion when the overall conditions prevent movement.","sol":"Step 1: Identify key concept: Define the required principles for Meaning of Force.\nStep 2: Apply governing rule: A force can act without producing motion when the overall conditions prevent movement.\nStep 3: State the final conclusion: No. The student applies a force, but the wall does not move because the forces and constraints prevent a change in its motion.","steps":["Step 1: Identify key concept: Define the required principles for Meaning of Force.","Step 2: Apply governing rule: A force can act without producing motion when the overall conditions prevent movement.","Step 3: State the final conclusion: No. The student applies a force, but the wall does not move because the forces and constraints prevent a change in its motion."],"options":[],"conceptId":"physics_force_meaning_of_force","skillId":"physics_force","subskillId":"physics_force_q5","subject":"physics","chapter":"force","topic":"Meaning of Force"}', 4),
  (1214, 357, 'What force pulls an unsupported object toward Earth?', 'text', 1, 'It acts because Earth and the object have mass.', '{"why":"Earth''s gravity attracts the object toward Earth''s centre.","sol":"Step 1: Identify key concept: Define the required principles for Types of Forces.\nStep 2: Apply governing rule: Earth''s gravity attracts the object toward Earth''s centre.\nStep 3: State the final conclusion: Gravitational force.","steps":["Step 1: Identify key concept: Define the required principles for Types of Forces.","Step 2: Apply governing rule: Earth''s gravity attracts the object toward Earth''s centre.","Step 3: State the final conclusion: Gravitational force."],"options":[],"conceptId":"physics_force_types_of_forces","skillId":"physics_force","subskillId":"physics_force_q1","subject":"physics","chapter":"force","topic":"Types of Forces"}', 0),
  (1215, 357, 'What force is transmitted through a taut rope supporting a hanging bucket?', 'text', 1, 'It is a pulling force in the rope.', '{"why":"A taut rope transmits tension along its length.","sol":"Step 1: Identify key concept: Define the required principles for Types of Forces.\nStep 2: Apply governing rule: A taut rope transmits tension along its length.\nStep 3: State the final conclusion: Tension.","steps":["Step 1: Identify key concept: Define the required principles for Types of Forces.","Step 2: Apply governing rule: A taut rope transmits tension along its length.","Step 3: State the final conclusion: Tension."],"options":[],"conceptId":"physics_force_types_of_forces","skillId":"physics_force","subskillId":"physics_force_q2","subject":"physics","chapter":"force","topic":"Types of Forces"}', 1),
  (1216, 357, 'Name the force exerted perpendicular to a table by a book resting on it.', 'text', 1, 'It is the table''s supporting contact force.', '{"why":"The normal force acts perpendicular to the contact surface.","sol":"Step 1: Identify key concept: Define the required principles for Types of Forces.\nStep 2: Apply governing rule: The normal force acts perpendicular to the contact surface.\nStep 3: State the final conclusion: Normal contact force.","steps":["Step 1: Identify key concept: Define the required principles for Types of Forces.","Step 2: Apply governing rule: The normal force acts perpendicular to the contact surface.","Step 3: State the final conclusion: Normal contact force."],"options":[],"conceptId":"physics_force_types_of_forces","skillId":"physics_force","subskillId":"physics_force_q3","subject":"physics","chapter":"force","topic":"Types of Forces"}', 2),
  (1217, 357, 'Which two forces commonly oppose a moving bicycle through contact with surfaces and movement through air?', 'text', 1, 'One acts between surfaces; the other is exerted by air.', '{"why":"Both can oppose the bicycle''s motion relative to its surroundings.","sol":"Step 1: Identify key concept: Define the required principles for Types of Forces.\nStep 2: Apply governing rule: Both can oppose the bicycle''s motion relative to its surroundings.\nStep 3: State the final conclusion: Friction and air resistance.","steps":["Step 1: Identify key concept: Define the required principles for Types of Forces.","Step 2: Apply governing rule: Both can oppose the bicycle''s motion relative to its surroundings.","Step 3: State the final conclusion: Friction and air resistance."],"options":[],"conceptId":"physics_force_types_of_forces","skillId":"physics_force","subskillId":"physics_force_q4","subject":"physics","chapter":"force","topic":"Types of Forces"}', 3),
  (1218, 357, 'A magnet attracts an iron nail without touching it. What type of force is responsible?', 'text', 1, 'Identify the interaction produced by the magnet.', '{"why":"Magnetic forces can act across a gap.","sol":"Step 1: Identify key concept: Define the required principles for Types of Forces.\nStep 2: Apply governing rule: Magnetic forces can act across a gap.\nStep 3: State the final conclusion: Magnetic force.","steps":["Step 1: Identify key concept: Define the required principles for Types of Forces.","Step 2: Apply governing rule: Magnetic forces can act across a gap.","Step 3: State the final conclusion: Magnetic force."],"options":[],"conceptId":"physics_force_types_of_forces","skillId":"physics_force","subskillId":"physics_force_q5","subject":"physics","chapter":"force","topic":"Types of Forces"}', 4),
  (1219, 357, 'Which force pulls a dropped stone towards Earth?', 'text', 1, 'Identify the force caused by Earth''s mass.', '{"why":"Earth attracts the stone through gravity, whether the stone is falling or resting.","sol":"Step 1: Identify key concept: Define the required principles for Types of Forces.\nStep 2: Apply governing rule: Earth attracts the stone through gravity, whether the stone is falling or resting.\nStep 3: State the final conclusion: Gravitational force","steps":["Step 1: Identify key concept: Define the required principles for Types of Forces.","Step 2: Apply governing rule: Earth attracts the stone through gravity, whether the stone is falling or resting.","Step 3: State the final conclusion: Gravitational force"],"options":[],"conceptId":"physics_force_types_of_forces","skillId":"physics_force","subskillId":"physics_force_q6","subject":"physics","chapter":"force","topic":"Types of Forces"}', 5),
  (1220, 357, 'A bucket is suspended by a taut rope. What force does the rope exert on the bucket?', 'text', 1, 'A taut rope pulls along its length.', '{"why":"Tension is the pulling force transmitted through a taut rope or string.","sol":"Step 1: Identify key concept: Define the required principles for Types of Forces.\nStep 2: Apply governing rule: Tension is the pulling force transmitted through a taut rope or string.\nStep 3: State the final conclusion: Tension","steps":["Step 1: Identify key concept: Define the required principles for Types of Forces.","Step 2: Apply governing rule: Tension is the pulling force transmitted through a taut rope or string.","Step 3: State the final conclusion: Tension"],"options":[],"conceptId":"physics_force_types_of_forces","skillId":"physics_force","subskillId":"physics_force_q7","subject":"physics","chapter":"force","topic":"Types of Forces"}', 6),
  (1221, 357, 'A box slides across a rough floor. Which force opposes its sliding?', 'text', 1, 'Consider the interaction between the touching surfaces.', '{"why":"Friction acts between surfaces and opposes relative sliding or attempted sliding.","sol":"Step 1: Identify key concept: Define the required principles for Types of Forces.\nStep 2: Apply governing rule: Friction acts between surfaces and opposes relative sliding or attempted sliding.\nStep 3: State the final conclusion: Friction","steps":["Step 1: Identify key concept: Define the required principles for Types of Forces.","Step 2: Apply governing rule: Friction acts between surfaces and opposes relative sliding or attempted sliding.","Step 3: State the final conclusion: Friction"],"options":[],"conceptId":"physics_force_types_of_forces","skillId":"physics_force","subskillId":"physics_force_q8","subject":"physics","chapter":"force","topic":"Types of Forces"}', 7),
  (1222, 357, 'What upward force does water exert on an object immersed in it?', 'text', 1, 'This force helps objects float.', '{"why":"Upthrust is the upward force exerted by a fluid on an immersed object.","sol":"Step 1: Identify key concept: Define the required principles for Types of Forces.\nStep 2: Apply governing rule: Upthrust is the upward force exerted by a fluid on an immersed object.\nStep 3: State the final conclusion: Upthrust","steps":["Step 1: Identify key concept: Define the required principles for Types of Forces.","Step 2: Apply governing rule: Upthrust is the upward force exerted by a fluid on an immersed object.","Step 3: State the final conclusion: Upthrust"],"options":[],"conceptId":"physics_force_types_of_forces","skillId":"physics_force","subskillId":"physics_force_q9","subject":"physics","chapter":"force","topic":"Types of Forces"}', 8),
  (1223, 357, 'A charged ruler attracts small pieces of paper. Which type of force is involved?', 'text', 1, 'Think about electric charge.', '{"why":"Charged objects can exert electrostatic forces on other charged or polarised objects.","sol":"Step 1: Identify key concept: Define the required principles for Types of Forces.\nStep 2: Apply governing rule: Charged objects can exert electrostatic forces on other charged or polarised objects.\nStep 3: State the final conclusion: Electrostatic force","steps":["Step 1: Identify key concept: Define the required principles for Types of Forces.","Step 2: Apply governing rule: Charged objects can exert electrostatic forces on other charged or polarised objects.","Step 3: State the final conclusion: Electrostatic force"],"options":[],"conceptId":"physics_force_types_of_forces","skillId":"physics_force","subskillId":"physics_force_q10","subject":"physics","chapter":"force","topic":"Types of Forces"}', 9),
  (1224, 358, 'Classify gravitational force as contact or non-contact.', 'text', 1, 'Does gravity require the objects to touch?', '{"why":"Gravity acts between objects with mass even when separated.","sol":"Step 1: Identify key concept: Define the required principles for Contact and Non-contact Forces.\nStep 2: Apply governing rule: Gravity acts between objects with mass even when separated.\nStep 3: State the final conclusion: Non-contact force.","steps":["Step 1: Identify key concept: Define the required principles for Contact and Non-contact Forces.","Step 2: Apply governing rule: Gravity acts between objects with mass even when separated.","Step 3: State the final conclusion: Non-contact force."],"options":[],"conceptId":"physics_force_contact_and_non_contact_forces","skillId":"physics_force","subskillId":"physics_force_q1","subject":"physics","chapter":"force","topic":"Contact and Non-contact Forces"}', 0),
  (1225, 358, 'A table supports a book resting on it. Is the table''s normal force a contact or non-contact force?', 'text', 1, 'Consider whether the table touches the book.', '{"why":"The supporting force is exerted through direct contact.","sol":"Step 1: Identify key concept: Define the required principles for Contact and Non-contact Forces.\nStep 2: Apply governing rule: The supporting force is exerted through direct contact.\nStep 3: State the final conclusion: Contact force.","steps":["Step 1: Identify key concept: Define the required principles for Contact and Non-contact Forces.","Step 2: Apply governing rule: The supporting force is exerted through direct contact.","Step 3: State the final conclusion: Contact force."],"options":[],"conceptId":"physics_force_contact_and_non_contact_forces","skillId":"physics_force","subskillId":"physics_force_q2","subject":"physics","chapter":"force","topic":"Contact and Non-contact Forces"}', 1),
  (1226, 358, 'A magnet attracts an iron nail across a small gap. Classify the force.', 'text', 1, 'The nail and magnet are not touching.', '{"why":"Magnetic interactions can act across a gap.","sol":"Step 1: Identify key concept: Define the required principles for Contact and Non-contact Forces.\nStep 2: Apply governing rule: Magnetic interactions can act across a gap.\nStep 3: State the final conclusion: Non-contact magnetic force.","steps":["Step 1: Identify key concept: Define the required principles for Contact and Non-contact Forces.","Step 2: Apply governing rule: Magnetic interactions can act across a gap.","Step 3: State the final conclusion: Non-contact magnetic force."],"options":[],"conceptId":"physics_force_contact_and_non_contact_forces","skillId":"physics_force","subskillId":"physics_force_q3","subject":"physics","chapter":"force","topic":"Contact and Non-contact Forces"}', 2),
  (1227, 358, 'Why is air resistance classified as a contact force?', 'text', 1, 'Think about the interaction between air particles and the object.', '{"why":"The force arises from interactions between the air and the object.","sol":"Step 1: Identify key concept: Define the required principles for Contact and Non-contact Forces.\nStep 2: Apply governing rule: The force arises from interactions between the air and the object.\nStep 3: State the final conclusion: Air particles interact with the object''s surface.","steps":["Step 1: Identify key concept: Define the required principles for Contact and Non-contact Forces.","Step 2: Apply governing rule: The force arises from interactions between the air and the object.","Step 3: State the final conclusion: Air particles interact with the object''s surface."],"options":[],"conceptId":"physics_force_contact_and_non_contact_forces","skillId":"physics_force","subskillId":"physics_force_q4","subject":"physics","chapter":"force","topic":"Contact and Non-contact Forces"}', 3),
  (1228, 358, 'A charged ruler attracts a nearby charged object without touching it. Which category describes the electrostatic force?', 'text', 1, 'Focus on whether direct contact is required.', '{"why":"Electrostatic forces can act between separated charged objects.","sol":"Step 1: Identify key concept: Define the required principles for Contact and Non-contact Forces.\nStep 2: Apply governing rule: Electrostatic forces can act between separated charged objects.\nStep 3: State the final conclusion: Non-contact force.","steps":["Step 1: Identify key concept: Define the required principles for Contact and Non-contact Forces.","Step 2: Apply governing rule: Electrostatic forces can act between separated charged objects.","Step 3: State the final conclusion: Non-contact force."],"options":[],"conceptId":"physics_force_contact_and_non_contact_forces","skillId":"physics_force","subskillId":"physics_force_q5","subject":"physics","chapter":"force","topic":"Contact and Non-contact Forces"}', 4),
  (1229, 358, 'Classify the gravitational force between Earth and a satellite orbiting Earth.', 'text', 1, 'Does the satellite need to touch Earth?', '{"why":"Gravity acts across the space between Earth and the satellite.","sol":"Step 1: Identify key concept: Define the required principles for Contact and Non-contact Forces.\nStep 2: Apply governing rule: Gravity acts across the space between Earth and the satellite.\nStep 3: State the final conclusion: Non-contact force","steps":["Step 1: Identify key concept: Define the required principles for Contact and Non-contact Forces.","Step 2: Apply governing rule: Gravity acts across the space between Earth and the satellite.","Step 3: State the final conclusion: Non-contact force"],"options":[],"conceptId":"physics_force_contact_and_non_contact_forces","skillId":"physics_force","subskillId":"physics_force_q6","subject":"physics","chapter":"force","topic":"Contact and Non-contact Forces"}', 5),
  (1230, 358, 'A student pushes a desk with a hand. Is the applied force a contact or non-contact force?', 'text', 1, 'Check whether the hand touches the desk.', '{"why":"The hand must touch the desk to exert this push.","sol":"Step 1: Identify key concept: Define the required principles for Contact and Non-contact Forces.\nStep 2: Apply governing rule: The hand must touch the desk to exert this push.\nStep 3: State the final conclusion: Contact force","steps":["Step 1: Identify key concept: Define the required principles for Contact and Non-contact Forces.","Step 2: Apply governing rule: The hand must touch the desk to exert this push.","Step 3: State the final conclusion: Contact force"],"options":[],"conceptId":"physics_force_contact_and_non_contact_forces","skillId":"physics_force","subskillId":"physics_force_q7","subject":"physics","chapter":"force","topic":"Contact and Non-contact Forces"}', 6),
  (1231, 358, 'Is magnetic attraction between two separated magnets a contact force?', 'text', 1, 'The magnets can attract before touching.', '{"why":"Magnetic forces can act across a gap.","sol":"Step 1: Identify key concept: Define the required principles for Contact and Non-contact Forces.\nStep 2: Apply governing rule: Magnetic forces can act across a gap.\nStep 3: State the final conclusion: No. It is a non-contact force.","steps":["Step 1: Identify key concept: Define the required principles for Contact and Non-contact Forces.","Step 2: Apply governing rule: Magnetic forces can act across a gap.","Step 3: State the final conclusion: No. It is a non-contact force."],"options":[],"conceptId":"physics_force_contact_and_non_contact_forces","skillId":"physics_force","subskillId":"physics_force_q8","subject":"physics","chapter":"force","topic":"Contact and Non-contact Forces"}', 7),
  (1232, 358, 'Classify air resistance acting on a moving car.', 'text', 1, 'Consider the interaction between the car and air particles.', '{"why":"Air particles interact with the car''s surface, producing drag.","sol":"Step 1: Identify key concept: Define the required principles for Contact and Non-contact Forces.\nStep 2: Apply governing rule: Air particles interact with the car''s surface, producing drag.\nStep 3: State the final conclusion: Contact force","steps":["Step 1: Identify key concept: Define the required principles for Contact and Non-contact Forces.","Step 2: Apply governing rule: Air particles interact with the car''s surface, producing drag.","Step 3: State the final conclusion: Contact force"],"options":[],"conceptId":"physics_force_contact_and_non_contact_forces","skillId":"physics_force","subskillId":"physics_force_q9","subject":"physics","chapter":"force","topic":"Contact and Non-contact Forces"}', 8),
  (1233, 358, 'A book rests on a table. Is the table''s normal reaction a contact or non-contact force?', 'text', 1, 'The force comes from the supporting surface.', '{"why":"The normal reaction is exerted by the table where it contacts the book.","sol":"Step 1: Identify key concept: Define the required principles for Contact and Non-contact Forces.\nStep 2: Apply governing rule: The normal reaction is exerted by the table where it contacts the book.\nStep 3: State the final conclusion: Contact force","steps":["Step 1: Identify key concept: Define the required principles for Contact and Non-contact Forces.","Step 2: Apply governing rule: The normal reaction is exerted by the table where it contacts the book.","Step 3: State the final conclusion: Contact force"],"options":[],"conceptId":"physics_force_contact_and_non_contact_forces","skillId":"physics_force","subskillId":"physics_force_q10","subject":"physics","chapter":"force","topic":"Contact and Non-contact Forces"}', 9),
  (1234, 359, 'A stationary ball is kicked and starts moving. What effect of force is demonstrated?', 'text', 1, 'Compare the ball''s state before and after the kick.', '{"why":"The force changes the ball from rest to motion.","sol":"Step 1: Identify key concept: Define the required principles for Effects of Force.\nStep 2: Apply governing rule: The force changes the ball from rest to motion.\nStep 3: State the final conclusion: The force starts the ball moving.","steps":["Step 1: Identify key concept: Define the required principles for Effects of Force.","Step 2: Apply governing rule: The force changes the ball from rest to motion.","Step 3: State the final conclusion: The force starts the ball moving."],"options":[],"conceptId":"physics_force_effects_of_force","skillId":"physics_force","subskillId":"physics_force_q1","subject":"physics","chapter":"force","topic":"Effects of Force"}', 0),
  (1235, 359, 'A moving car slows when its brakes are applied. What effect does the braking force produce?', 'text', 1, 'Compare the car''s initial and final speeds.', '{"why":"A net force opposing the motion reduces the car''s speed.","sol":"Step 1: Identify key concept: Define the required principles for Effects of Force.\nStep 2: Apply governing rule: A net force opposing the motion reduces the car''s speed.\nStep 3: State the final conclusion: It decreases the car''s speed.","steps":["Step 1: Identify key concept: Define the required principles for Effects of Force.","Step 2: Apply governing rule: A net force opposing the motion reduces the car''s speed.","Step 3: State the final conclusion: It decreases the car''s speed."],"options":[],"conceptId":"physics_force_effects_of_force","skillId":"physics_force","subskillId":"physics_force_q2","subject":"physics","chapter":"force","topic":"Effects of Force"}', 1),
  (1236, 359, 'Can a force change direction without changing speed?', 'text', 1, 'Think about motion along a circular path.', '{"why":"Velocity includes direction, so a directional change is a change in motion.","sol":"Step 1: Identify key concept: Define the required principles for Effects of Force.\nStep 2: Apply governing rule: Velocity includes direction, so a directional change is a change in motion.\nStep 3: State the final conclusion: Yes. A force can change the direction while the speed remains constant.","steps":["Step 1: Identify key concept: Define the required principles for Effects of Force.","Step 2: Apply governing rule: Velocity includes direction, so a directional change is a change in motion.","Step 3: State the final conclusion: Yes. A force can change the direction while the speed remains constant."],"options":[],"conceptId":"physics_force_effects_of_force","skillId":"physics_force","subskillId":"physics_force_q3","subject":"physics","chapter":"force","topic":"Effects of Force"}', 2),
  (1237, 359, 'A spring returns to its original length after a load is removed. What type of deformation occurred?', 'text', 1, 'The original shape is recovered.', '{"why":"Elastic deformation is recoverable when the elastic limit has not been exceeded.","sol":"Step 1: Identify key concept: Define the required principles for Effects of Force.\nStep 2: Apply governing rule: Elastic deformation is recoverable when the elastic limit has not been exceeded.\nStep 3: State the final conclusion: Elastic deformation.","steps":["Step 1: Identify key concept: Define the required principles for Effects of Force.","Step 2: Apply governing rule: Elastic deformation is recoverable when the elastic limit has not been exceeded.","Step 3: State the final conclusion: Elastic deformation."],"options":[],"conceptId":"physics_force_effects_of_force","skillId":"physics_force","subskillId":"physics_force_q4","subject":"physics","chapter":"force","topic":"Effects of Force"}', 3),
  (1238, 359, 'A force is removed from a bent metal strip, but it remains bent. What type of deformation is demonstrated?', 'text', 1, 'The shape does not return to its original state.', '{"why":"Plastic deformation leaves a permanent change in shape.","sol":"Step 1: Identify key concept: Define the required principles for Effects of Force.\nStep 2: Apply governing rule: Plastic deformation leaves a permanent change in shape.\nStep 3: State the final conclusion: Plastic deformation.","steps":["Step 1: Identify key concept: Define the required principles for Effects of Force.","Step 2: Apply governing rule: Plastic deformation leaves a permanent change in shape.","Step 3: State the final conclusion: Plastic deformation."],"options":[],"conceptId":"physics_force_effects_of_force","skillId":"physics_force","subskillId":"physics_force_q5","subject":"physics","chapter":"force","topic":"Effects of Force"}', 4),
  (1239, 359, 'A stationary football begins moving after being kicked. What effect of force is demonstrated?', 'text', 1, 'Compare the ball''s motion before and after the kick.', '{"why":"The applied force changes the ball from rest to motion.","sol":"Step 1: Identify key concept: Define the required principles for Effects of Force.\nStep 2: Apply governing rule: The applied force changes the ball from rest to motion.\nStep 3: State the final conclusion: The force starts the ball moving.","steps":["Step 1: Identify key concept: Define the required principles for Effects of Force.","Step 2: Apply governing rule: The applied force changes the ball from rest to motion.","Step 3: State the final conclusion: The force starts the ball moving."],"options":[],"conceptId":"physics_force_effects_of_force","skillId":"physics_force","subskillId":"physics_force_q6","subject":"physics","chapter":"force","topic":"Effects of Force"}', 5),
  (1240, 359, 'A moving bicycle slows down when its brakes are applied. What change does the force produce?', 'text', 1, 'Look at the change in speed.', '{"why":"The braking force opposes the bicycle''s motion.","sol":"Step 1: Identify key concept: Define the required principles for Effects of Force.\nStep 2: Apply governing rule: The braking force opposes the bicycle''s motion.\nStep 3: State the final conclusion: It reduces the bicycle''s speed.","steps":["Step 1: Identify key concept: Define the required principles for Effects of Force.","Step 2: Apply governing rule: The braking force opposes the bicycle''s motion.","Step 3: State the final conclusion: It reduces the bicycle''s speed."],"options":[],"conceptId":"physics_force_effects_of_force","skillId":"physics_force","subskillId":"physics_force_q7","subject":"physics","chapter":"force","topic":"Effects of Force"}', 6),
  (1241, 359, 'A tennis ball changes direction after being hit by a racket. Which effect of force is shown?', 'text', 1, 'The ball was already moving.', '{"why":"A force can alter the direction of motion, even if the object was already moving.","sol":"Step 1: Identify key concept: Define the required principles for Effects of Force.\nStep 2: Apply governing rule: A force can alter the direction of motion, even if the object was already moving.\nStep 3: State the final conclusion: A change in direction","steps":["Step 1: Identify key concept: Define the required principles for Effects of Force.","Step 2: Apply governing rule: A force can alter the direction of motion, even if the object was already moving.","Step 3: State the final conclusion: A change in direction"],"options":[],"conceptId":"physics_force_effects_of_force","skillId":"physics_force","subskillId":"physics_force_q8","subject":"physics","chapter":"force","topic":"Effects of Force"}', 7),
  (1242, 359, 'A spring becomes longer when a load is attached. What effect of force is shown?', 'text', 1, 'Consider the spring''s shape and length.', '{"why":"The load exerts a force that stretches the spring.","sol":"Step 1: Identify key concept: Define the required principles for Effects of Force.\nStep 2: Apply governing rule: The load exerts a force that stretches the spring.\nStep 3: State the final conclusion: Deformation or change in length","steps":["Step 1: Identify key concept: Define the required principles for Effects of Force.","Step 2: Apply governing rule: The load exerts a force that stretches the spring.","Step 3: State the final conclusion: Deformation or change in length"],"options":[],"conceptId":"physics_force_effects_of_force","skillId":"physics_force","subskillId":"physics_force_q9","subject":"physics","chapter":"force","topic":"Effects of Force"}', 8),
  (1243, 359, 'A book rests motionless on a table. Does this prove that no forces act on it?', 'text', 1, 'Consider gravity and the table''s support.', '{"why":"The forces can balance, so the book remains at rest.","sol":"Step 1: Identify key concept: Define the required principles for Effects of Force.\nStep 2: Apply governing rule: The forces can balance, so the book remains at rest.\nStep 3: State the final conclusion: No. Gravity acts downward and the table''s normal reaction acts upward.","steps":["Step 1: Identify key concept: Define the required principles for Effects of Force.","Step 2: Apply governing rule: The forces can balance, so the book remains at rest.","Step 3: State the final conclusion: No. Gravity acts downward and the table''s normal reaction acts upward."],"options":[],"conceptId":"physics_force_effects_of_force","skillId":"physics_force","subskillId":"physics_force_q10","subject":"physics","chapter":"force","topic":"Effects of Force"}', 9),
  (1244, 360, 'Two forces of 7 N and 5 N act to the right. Find the resultant force.', 'text', 1, 'Forces in the same direction add.', '{"why":"Same-direction forces reinforce each other.","sol":"Step 1: Add the forces: 7 + 5 = 12 N.\nStep 2: Keep the common direction.","steps":["Step 1: Add the forces: 7 + 5 = 12 N.","Step 2: Keep the common direction."],"options":[],"conceptId":"physics_force_resultant_force","skillId":"physics_force","subskillId":"physics_force_q1","subject":"physics","chapter":"force","topic":"Resultant Force"}', 0),
  (1245, 360, 'A box experiences 20 N to the left and 13 N to the right. Find the resultant force.', 'text', 1, 'Subtract the smaller magnitude from the larger.', '{"why":"The resultant follows the direction of the larger opposing force.","sol":"Step 1: Calculate 20 − 13 = 7 N.\nStep 2: The larger force is leftward.","steps":["Step 1: Calculate 20 − 13 = 7 N.","Step 2: The larger force is leftward."],"options":[],"conceptId":"physics_force_resultant_force","skillId":"physics_force","subskillId":"physics_force_q2","subject":"physics","chapter":"force","topic":"Resultant Force"}', 1),
  (1246, 360, 'Two equal forces of 9 N act in opposite directions along the same line. Find the resultant.', 'text', 1, 'Subtract the equal magnitudes.', '{"why":"The forces cancel because they are equal and opposite.","sol":"Step 1: Identify key concept: Define the required principles for Resultant Force.\nStep 2: Apply governing rule: The forces cancel because they are equal and opposite.\nStep 3: State the final conclusion: 0 N.","steps":["Step 1: Identify key concept: Define the required principles for Resultant Force.","Step 2: Apply governing rule: The forces cancel because they are equal and opposite.","Step 3: State the final conclusion: 0 N."],"options":[],"conceptId":"physics_force_resultant_force","skillId":"physics_force","subskillId":"physics_force_q3","subject":"physics","chapter":"force","topic":"Resultant Force"}', 2),
  (1247, 360, 'Forces of 14 N right, 6 N left and 3 N left act on an object. Find the resultant.', 'text', 1, 'Add the forces in each direction first.', '{"why":"Combining forces by direction avoids sign errors.","sol":"Step 1: Leftward total = 6 + 3 = 9 N.\nStep 2: Difference = 14 − 9 = 5 N.\nStep 3: The larger total is rightward.","steps":["Step 1: Leftward total = 6 + 3 = 9 N.","Step 2: Difference = 14 − 9 = 5 N.","Step 3: The larger total is rightward."],"options":[],"conceptId":"physics_force_resultant_force","skillId":"physics_force","subskillId":"physics_force_q4","subject":"physics","chapter":"force","topic":"Resultant Force"}', 3),
  (1248, 360, 'A learner says the resultant of 4 N right and 10 N left is 14 N left. Identify the error and correct the answer.', 'text', 1, 'Opposite forces do not add their magnitudes.', '{"why":"Opposing forces partially cancel rather than reinforce.","sol":"Step 1: Subtract: 10 − 4 = 6 N.\nStep 2: Choose the direction of the larger force: left.","steps":["Step 1: Subtract: 10 − 4 = 6 N.","Step 2: Choose the direction of the larger force: left."],"options":[],"conceptId":"physics_force_resultant_force","skillId":"physics_force","subskillId":"physics_force_q5","subject":"physics","chapter":"force","topic":"Resultant Force"}', 4),
  (1249, 360, 'Two forces of 7 N and 11 N act to the right. Find the resultant force.', 'text', 1, 'Forces in the same direction add.', '{"why":"Forces acting along the same line in the same direction add.","sol":"Step 1: Identify both forces as rightward.\nStep 2: Add: 7 + 11 = 18.\nStep 3: Include the direction and unit.","steps":["Step 1: Identify both forces as rightward.","Step 2: Add: 7 + 11 = 18.","Step 3: Include the direction and unit."],"options":[],"conceptId":"physics_force_resultant_force","skillId":"physics_force","subskillId":"physics_force_q6","subject":"physics","chapter":"force","topic":"Resultant Force"}', 5),
  (1250, 360, 'A box experiences 20 N to the right and 6 N to the left. Find the resultant force.', 'text', 1, 'Subtract the smaller opposing force from the larger.', '{"why":"Opposing forces subtract, and the resultant points in the direction of the larger force.","sol":"Step 1: Calculate 20 − 6 = 14 N.\nStep 2: The 20 N force is larger.\nStep 3: The resultant acts to the right.","steps":["Step 1: Calculate 20 − 6 = 14 N.","Step 2: The 20 N force is larger.","Step 3: The resultant acts to the right."],"options":[],"conceptId":"physics_force_resultant_force","skillId":"physics_force","subskillId":"physics_force_q7","subject":"physics","chapter":"force","topic":"Resultant Force"}', 6);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (1251, 360, 'Forces of 15 N left and 15 N right act on an object. What is the resultant force?', 'text', 1, 'Equal forces in opposite directions cancel.', '{"why":"The forces cancel because they have equal magnitudes and opposite directions.","sol":"Step 1: Identify key concept: Define the required principles for Resultant Force.\nStep 2: Apply governing rule: The forces cancel because they have equal magnitudes and opposite directions.\nStep 3: State the final conclusion: 0 N","steps":["Step 1: Identify key concept: Define the required principles for Resultant Force.","Step 2: Apply governing rule: The forces cancel because they have equal magnitudes and opposite directions.","Step 3: State the final conclusion: 0 N"],"options":[],"conceptId":"physics_force_resultant_force","skillId":"physics_force","subskillId":"physics_force_q8","subject":"physics","chapter":"force","topic":"Resultant Force"}', 7),
  (1252, 360, 'A cart is pulled with 30 N east and 12 N west. Find the resultant force.', 'text', 1, 'Subtract and keep the direction of the stronger force.', '{"why":"The eastward pull is greater by 18 N.","sol":"Step 1: 30 − 12 = 18 N.\nStep 2: East is the direction of the larger force.","steps":["Step 1: 30 − 12 = 18 N.","Step 2: East is the direction of the larger force."],"options":[],"conceptId":"physics_force_resultant_force","skillId":"physics_force","subskillId":"physics_force_q9","subject":"physics","chapter":"force","topic":"Resultant Force"}', 8),
  (1253, 360, 'A student pushes a box with 9 N right while another pushes it with 14 N left. Find the resultant force.', 'text', 1, 'The leftward force is larger.', '{"why":"The resultant points in the direction of the larger opposing force.","sol":"Step 1: 14 − 9 = 5 N.\nStep 2: The larger force acts left.","steps":["Step 1: 14 − 9 = 5 N.","Step 2: The larger force acts left."],"options":[],"conceptId":"physics_force_resultant_force","skillId":"physics_force","subskillId":"physics_force_q10","subject":"physics","chapter":"force","topic":"Resultant Force"}', 9),
  (1254, 361, 'An object experiences 12 N upward and 12 N downward. Are these forces balanced?', 'text', 1, 'Calculate the resultant.', '{"why":"Equal and opposite forces cancel.","sol":"Step 1: Identify key concept: Define the required principles for Balanced and Unbalanced Forces.\nStep 2: Apply governing rule: Equal and opposite forces cancel.\nStep 3: State the final conclusion: Yes. The resultant is 0 N.","steps":["Step 1: Identify key concept: Define the required principles for Balanced and Unbalanced Forces.","Step 2: Apply governing rule: Equal and opposite forces cancel.","Step 3: State the final conclusion: Yes. The resultant is 0 N."],"options":[],"conceptId":"physics_force_balanced_and_unbalanced_forces","skillId":"physics_force","subskillId":"physics_force_q1","subject":"physics","chapter":"force","topic":"Balanced and Unbalanced Forces"}', 0),
  (1255, 361, 'A trolley experiences 25 N right and 9 N left. Are the forces balanced?', 'text', 1, 'Find the difference between opposing forces.', '{"why":"A non-zero resultant means the velocity changes.","sol":"Step 1: 25 − 9 = 16 N.\nStep 2: The resultant is not zero.","steps":["Step 1: 25 − 9 = 16 N.","Step 2: The resultant is not zero."],"options":[],"conceptId":"physics_force_balanced_and_unbalanced_forces","skillId":"physics_force","subskillId":"physics_force_q2","subject":"physics","chapter":"force","topic":"Balanced and Unbalanced Forces"}', 1),
  (1256, 361, 'A car moves straight at constant speed. What is the resultant force on it?', 'text', 1, 'Its velocity is unchanged.', '{"why":"Constant velocity means zero acceleration and therefore zero resultant force.","sol":"Step 1: Identify key concept: Define the required principles for Balanced and Unbalanced Forces.\nStep 2: Apply governing rule: Constant velocity means zero acceleration and therefore zero resultant force.\nStep 3: State the final conclusion: The resultant force is zero.","steps":["Step 1: Identify key concept: Define the required principles for Balanced and Unbalanced Forces.","Step 2: Apply governing rule: Constant velocity means zero acceleration and therefore zero resultant force.","Step 3: State the final conclusion: The resultant force is zero."],"options":[],"conceptId":"physics_force_balanced_and_unbalanced_forces","skillId":"physics_force","subskillId":"physics_force_q3","subject":"physics","chapter":"force","topic":"Balanced and Unbalanced Forces"}', 2),
  (1257, 361, 'A stationary box has balanced forces acting on it. Does this mean that no forces act on the box?', 'text', 1, 'Consider gravity and the floor''s supporting force.', '{"why":"Balanced forces are present but their vector sum is zero.","sol":"Step 1: Identify key concept: Define the required principles for Balanced and Unbalanced Forces.\nStep 2: Apply governing rule: Balanced forces are present but their vector sum is zero.\nStep 3: State the final conclusion: No. Forces can act and cancel, giving a zero resultant.","steps":["Step 1: Identify key concept: Define the required principles for Balanced and Unbalanced Forces.","Step 2: Apply governing rule: Balanced forces are present but their vector sum is zero.","Step 3: State the final conclusion: No. Forces can act and cancel, giving a zero resultant."],"options":[],"conceptId":"physics_force_balanced_and_unbalanced_forces","skillId":"physics_force","subskillId":"physics_force_q4","subject":"physics","chapter":"force","topic":"Balanced and Unbalanced Forces"}', 3),
  (1258, 361, 'An object moves right but experiences a non-zero resultant force to the left. What happens to its velocity?', 'text', 1, 'A force opposite to the motion changes the motion.', '{"why":"The direction of acceleration is the direction of the resultant force, not necessarily the direction of travel.","sol":"Step 1: Identify key concept: Define the required principles for Balanced and Unbalanced Forces.\nStep 2: Apply governing rule: The direction of acceleration is the direction of the resultant force, not necessarily the direction of travel.\nStep 3: State the final conclusion: Its acceleration is to the left, so its rightward velocity decreases initially.","steps":["Step 1: Identify key concept: Define the required principles for Balanced and Unbalanced Forces.","Step 2: Apply governing rule: The direction of acceleration is the direction of the resultant force, not necessarily the direction of travel.","Step 3: State the final conclusion: Its acceleration is to the left, so its rightward velocity decreases initially."],"options":[],"conceptId":"physics_force_balanced_and_unbalanced_forces","skillId":"physics_force","subskillId":"physics_force_q5","subject":"physics","chapter":"force","topic":"Balanced and Unbalanced Forces"}', 4),
  (1259, 361, 'A stationary object has a 12 N upward force and a 12 N downward force. Are the forces balanced?', 'text', 1, 'Calculate the resultant.', '{"why":"Equal and opposite forces cancel.","sol":"Step 1: Identify key concept: Define the required principles for Balanced and Unbalanced Forces.\nStep 2: Apply governing rule: Equal and opposite forces cancel.\nStep 3: State the final conclusion: Yes. The resultant force is 0 N.","steps":["Step 1: Identify key concept: Define the required principles for Balanced and Unbalanced Forces.","Step 2: Apply governing rule: Equal and opposite forces cancel.","Step 3: State the final conclusion: Yes. The resultant force is 0 N."],"options":[],"conceptId":"physics_force_balanced_and_unbalanced_forces","skillId":"physics_force","subskillId":"physics_force_q6","subject":"physics","chapter":"force","topic":"Balanced and Unbalanced Forces"}', 5),
  (1260, 361, 'A car moves in a straight line at constant velocity. What is its resultant force?', 'text', 1, 'Constant velocity means no change in velocity.', '{"why":"Zero acceleration corresponds to zero resultant force.","sol":"Step 1: Identify key concept: Define the required principles for Balanced and Unbalanced Forces.\nStep 2: Apply governing rule: Zero acceleration corresponds to zero resultant force.\nStep 3: State the final conclusion: 0 N","steps":["Step 1: Identify key concept: Define the required principles for Balanced and Unbalanced Forces.","Step 2: Apply governing rule: Zero acceleration corresponds to zero resultant force.","Step 3: State the final conclusion: 0 N"],"options":[],"conceptId":"physics_force_balanced_and_unbalanced_forces","skillId":"physics_force","subskillId":"physics_force_q7","subject":"physics","chapter":"force","topic":"Balanced and Unbalanced Forces"}', 6),
  (1261, 361, 'A box experiences 18 N right and 7 N left. Are the forces balanced?', 'text', 1, 'Calculate the net force.', '{"why":"A non-zero resultant means the forces are unbalanced.","sol":"Step 1: 18 − 7 = 11 N.\nStep 2: The resultant is not zero.","steps":["Step 1: 18 − 7 = 11 N.","Step 2: The resultant is not zero."],"options":[],"conceptId":"physics_force_balanced_and_unbalanced_forces","skillId":"physics_force","subskillId":"physics_force_q8","subject":"physics","chapter":"force","topic":"Balanced and Unbalanced Forces"}', 7),
  (1262, 361, 'Can an object move while the forces on it are balanced?', 'text', 1, 'Think about constant velocity.', '{"why":"Balanced forces prevent acceleration, not motion itself.","sol":"Step 1: Identify key concept: Define the required principles for Balanced and Unbalanced Forces.\nStep 2: Apply governing rule: Balanced forces prevent acceleration, not motion itself.\nStep 3: State the final conclusion: Yes. It can move at constant velocity.","steps":["Step 1: Identify key concept: Define the required principles for Balanced and Unbalanced Forces.","Step 2: Apply governing rule: Balanced forces prevent acceleration, not motion itself.","Step 3: State the final conclusion: Yes. It can move at constant velocity."],"options":[],"conceptId":"physics_force_balanced_and_unbalanced_forces","skillId":"physics_force","subskillId":"physics_force_q9","subject":"physics","chapter":"force","topic":"Balanced and Unbalanced Forces"}', 8),
  (1263, 361, 'A moving ball changes direction after being struck. Were its forces balanced during the change?', 'text', 1, 'A change in velocity means acceleration.', '{"why":"Changing direction is a change in velocity and therefore requires acceleration.","sol":"Step 1: Identify key concept: Define the required principles for Balanced and Unbalanced Forces.\nStep 2: Apply governing rule: Changing direction is a change in velocity and therefore requires acceleration.\nStep 3: State the final conclusion: No. The resultant force was non-zero during the change.","steps":["Step 1: Identify key concept: Define the required principles for Balanced and Unbalanced Forces.","Step 2: Apply governing rule: Changing direction is a change in velocity and therefore requires acceleration.","Step 3: State the final conclusion: No. The resultant force was non-zero during the change."],"options":[],"conceptId":"physics_force_balanced_and_unbalanced_forces","skillId":"physics_force","subskillId":"physics_force_q10","subject":"physics","chapter":"force","topic":"Balanced and Unbalanced Forces"}', 9),
  (1264, 362, 'What is the weight of an object?', 'text', 1, 'Think about the force that attracts the object towards Earth.', '{"why":"Weight is a force, not the amount of matter in an object.","sol":"Step 1: Identify the force caused by gravitational attraction.\nStep 2: This force acts on the object because of gravity.","steps":["Step 1: Identify the force caused by gravitational attraction.","Step 2: This force acts on the object because of gravity."],"options":[],"conceptId":"physics_force_meaning_of_weight","skillId":"physics_force","subskillId":"physics_force_q1","subject":"physics","chapter":"force","topic":"Meaning of Weight"}', 0),
  (1265, 362, 'What is the SI unit of weight?', 'text', 1, 'Weight is a force. Recall the SI unit of force.', '{"why":"The kilogram measures mass, while the newton measures force.","sol":"Step 1: Recognise that weight is a force.\nStep 2: The SI unit of force is the newton.","steps":["Step 1: Recognise that weight is a force.","Step 2: The SI unit of force is the newton."],"options":[],"conceptId":"physics_force_meaning_of_weight","skillId":"physics_force","subskillId":"physics_force_q2","subject":"physics","chapter":"force","topic":"Meaning of Weight"}', 1),
  (1266, 362, 'Near Earth''s surface, in which direction does the weight of a freely held object act?', 'text', 1, 'Consider the direction of Earth''s gravitational attraction.', '{"why":"Weight follows the direction of the local gravitational field.","sol":"Step 1: Earth attracts the object gravitationally.\nStep 2: The force acts towards Earth''s centre.","steps":["Step 1: Earth attracts the object gravitationally.","Step 2: The force acts towards Earth''s centre."],"options":[],"conceptId":"physics_force_meaning_of_weight","skillId":"physics_force","subskillId":"physics_force_q3","subject":"physics","chapter":"force","topic":"Meaning of Weight"}', 2),
  (1267, 362, 'A learner states that weight is measured in kilograms. What is wrong with this statement?', 'text', 1, 'Separate the units of mass and force.', '{"why":"The statement confuses two different physical quantities.","sol":"Step 1: Kilograms measure mass.\nStep 2: Weight is a force.\nStep 3: Force is measured in newtons.","steps":["Step 1: Kilograms measure mass.","Step 2: Weight is a force.","Step 3: Force is measured in newtons."],"options":[],"conceptId":"physics_force_meaning_of_weight","skillId":"physics_force","subskillId":"physics_force_q4","subject":"physics","chapter":"force","topic":"Meaning of Weight"}', 3),
  (1268, 363, 'A parcel has a mass of 8 kg. What physical quantity is measured in kilograms?', 'text', 1, 'Kilograms are used for the amount of matter in an object.', '{"why":"Weight is a force and is measured in newtons.","sol":"Step 1: Identify the unit kg.\nStep 2: Kilograms measure mass.","steps":["Step 1: Identify the unit kg.","Step 2: Kilograms measure mass."],"options":[],"conceptId":"physics_force_mass_and_weight","skillId":"physics_force","subskillId":"physics_force_q1","subject":"physics","chapter":"force","topic":"Mass and Weight"}', 0),
  (1269, 363, 'A spring balance calibrated in newtons reads 45 N for a hanging object. What quantity does it measure?', 'text', 1, 'Newtons are units of force.', '{"why":"The unit identifies the reading as a force rather than a mass.","sol":"Step 1: Recognise that N means newtons.\nStep 2: Newtons measure force.\nStep 3: The gravitational force on the object is its weight.","steps":["Step 1: Recognise that N means newtons.","Step 2: Newtons measure force.","Step 3: The gravitational force on the object is its weight."],"options":[],"conceptId":"physics_force_mass_and_weight","skillId":"physics_force","subskillId":"physics_force_q2","subject":"physics","chapter":"force","topic":"Mass and Weight"}', 1),
  (1270, 363, 'An astronaut takes a 12 kg object from Earth to the Moon. What is its mass on the Moon?', 'text', 1, 'Does changing location change the amount of matter?', '{"why":"It is the weight, not the mass, that changes with gravitational field strength.","sol":"Step 1: The object''s mass on Earth is 12 kg.\nStep 2: Its amount of matter does not change during the journey.","steps":["Step 1: The object''s mass on Earth is 12 kg.","Step 2: Its amount of matter does not change during the journey."],"options":[],"conceptId":"physics_force_mass_and_weight","skillId":"physics_force","subskillId":"physics_force_q3","subject":"physics","chapter":"force","topic":"Mass and Weight"}', 2),
  (1271, 363, 'Which quantity can change when the same object is taken from Earth to the Moon: mass or weight?', 'text', 1, 'Compare amount of matter with gravitational force.', '{"why":"The object''s mass remains constant, but the gravitational force on it becomes smaller.","sol":"Step 1: Mass measures the amount of matter and remains constant.\nStep 2: Weight depends on gravitational field strength.\nStep 3: The Moon''s gravitational field is weaker than Earth''s.","steps":["Step 1: Mass measures the amount of matter and remains constant.","Step 2: Weight depends on gravitational field strength.","Step 3: The Moon''s gravitational field is weaker than Earth''s."],"options":[],"conceptId":"physics_force_mass_and_weight","skillId":"physics_force","subskillId":"physics_force_q4","subject":"physics","chapter":"force","topic":"Mass and Weight"}', 3),
  (1272, 364, 'Calculate the weight of a 7 kg object where g = 10 N/kg.', 'text', 1, 'Use W = mg.', '{"why":"Multiplying 7 kg by 10 N/kg gives 70 N.","sol":"Step 1: W = mg.\nStep 2: Substitute m = 7 kg and g = 10 N/kg.\nStep 3: W = 7 × 10 = 70 N.","steps":["Step 1: W = mg.","Step 2: Substitute m = 7 kg and g = 10 N/kg.","Step 3: W = 7 × 10 = 70 N."],"options":[],"conceptId":"physics_force_calculating_weight","skillId":"physics_force","subskillId":"physics_force_q1","subject":"physics","chapter":"force","topic":"Calculating Weight"}', 0),
  (1273, 364, 'A 4 kg object is in a gravitational field of 9.8 N/kg. Calculate its weight.', 'text', 1, 'Multiply 4 by 9.8.', '{"why":"The calculation uses the field strength provided in the question.","sol":"Step 1: W = mg.\nStep 2: W = 4 × 9.8.\nStep 3: W = 39.2 N.","steps":["Step 1: W = mg.","Step 2: W = 4 × 9.8.","Step 3: W = 39.2 N."],"options":[],"conceptId":"physics_force_calculating_weight","skillId":"physics_force","subskillId":"physics_force_q2","subject":"physics","chapter":"force","topic":"Calculating Weight"}', 1),
  (1274, 364, 'An object has a mass of 15 kg. Calculate its weight where g = 10 N/kg.', 'text', 1, 'Substitute the mass and field strength into W = mg.', '{"why":"Weight is calculated by multiplying mass by gravitational field strength.","sol":"Step 1: W = mg.\nStep 2: W = 15 × 10.\nStep 3: W = 150 N.","steps":["Step 1: W = mg.","Step 2: W = 15 × 10.","Step 3: W = 150 N."],"options":[],"conceptId":"physics_force_calculating_weight","skillId":"physics_force","subskillId":"physics_force_q3","subject":"physics","chapter":"force","topic":"Calculating Weight"}', 2),
  (1275, 364, 'A learner calculates the weight of a 2 kg object in a 10 N/kg field as 20 kg. What is the correct answer?', 'text', 1, 'The numerical answer is 2 × 10, but check the unit of force.', '{"why":"The learner used the correct multiplication but confused the unit of mass with the unit of force.","sol":"Step 1: W = mg.\nStep 2: W = 2 × 10 = 20.\nStep 3: Weight is measured in newtons.","steps":["Step 1: W = mg.","Step 2: W = 2 × 10 = 20.","Step 3: Weight is measured in newtons."],"options":[],"conceptId":"physics_force_calculating_weight","skillId":"physics_force","subskillId":"physics_force_q4","subject":"physics","chapter":"force","topic":"Calculating Weight"}', 3),
  (1276, 365, 'An object weighs 90 N where g = 10 N/kg. Find its mass.', 'text', 1, 'Use m = W/g.', '{"why":"Rearranging W = mg requires dividing both sides by g.","sol":"Step 1: m = W/g.\nStep 2: m = 90/10.\nStep 3: m = 9 kg.","steps":["Step 1: m = W/g.","Step 2: m = 90/10.","Step 3: m = 9 kg."],"options":[],"conceptId":"physics_force_calculating_mass_from_weight","skillId":"physics_force","subskillId":"physics_force_q1","subject":"physics","chapter":"force","topic":"Calculating Mass from Weight"}', 0),
  (1277, 365, 'A stone weighs 19.6 N where g = 9.8 N/kg. Calculate its mass.', 'text', 1, 'Divide 19.6 N by 9.8 N/kg.', '{"why":"The units N divided by N/kg reduce to kg.","sol":"Step 1: m = W/g.\nStep 2: m = 19.6/9.8.\nStep 3: m = 2 kg.","steps":["Step 1: m = W/g.","Step 2: m = 19.6/9.8.","Step 3: m = 2 kg."],"options":[],"conceptId":"physics_force_calculating_mass_from_weight","skillId":"physics_force","subskillId":"physics_force_q2","subject":"physics","chapter":"force","topic":"Calculating Mass from Weight"}', 1),
  (1278, 365, 'An object weighs 150 N in a field of 10 N/kg. What is its mass?', 'text', 1, 'Make mass the subject of W = mg.', '{"why":"Dividing the weight by the field strength gives mass.","sol":"Step 1: m = W/g.\nStep 2: m = 150/10.\nStep 3: m = 15 kg.","steps":["Step 1: m = W/g.","Step 2: m = 150/10.","Step 3: m = 15 kg."],"options":[],"conceptId":"physics_force_calculating_mass_from_weight","skillId":"physics_force","subskillId":"physics_force_q3","subject":"physics","chapter":"force","topic":"Calculating Mass from Weight"}', 2),
  (1279, 365, 'Which formula correctly calculates mass from weight and gravitational field strength?', 'text', 1, 'Start with W = mg and isolate m.', '{"why":"Multiplication by g would not isolate mass from W = mg.","sol":"Step 1: Start with W = mg.\nStep 2: Divide both sides by g.\nStep 3: Obtain m = W/g.","steps":["Step 1: Start with W = mg.","Step 2: Divide both sides by g.","Step 3: Obtain m = W/g."],"options":[],"conceptId":"physics_force_calculating_mass_from_weight","skillId":"physics_force","subskillId":"physics_force_q4","subject":"physics","chapter":"force","topic":"Calculating Mass from Weight"}', 3),
  (1280, 366, 'A 4 kg object is in a gravitational field of 3 N/kg. Calculate its weight.', 'text', 1, 'Use W = mg.', '{"why":"The weight depends on the field strength at the object''s location.","sol":"Step 1: W = mg.\nStep 2: W = 4 × 3.\nStep 3: W = 12 N.","steps":["Step 1: W = mg.","Step 2: W = 4 × 3.","Step 3: W = 12 N."],"options":[],"conceptId":"physics_force_weight_in_different_gravitational_fields","skillId":"physics_force","subskillId":"physics_force_q1","subject":"physics","chapter":"force","topic":"Weight in Different Gravitational Fields"}', 0),
  (1281, 366, 'An object has a mass of 5 kg. Calculate its weight where g = 8 N/kg.', 'text', 1, 'Multiply mass by field strength.', '{"why":"The calculation uses the local field strength, not automatically Earth''s usual value.","sol":"Step 1: W = mg.\nStep 2: W = 5 × 8.\nStep 3: W = 40 N.","steps":["Step 1: W = mg.","Step 2: W = 5 × 8.","Step 3: W = 40 N."],"options":[],"conceptId":"physics_force_weight_in_different_gravitational_fields","skillId":"physics_force","subskillId":"physics_force_q2","subject":"physics","chapter":"force","topic":"Weight in Different Gravitational Fields"}', 1),
  (1282, 366, 'An object weighs 70 N where g = 10 N/kg. What is its weight where g = 2 N/kg?', 'text', 1, 'First find its mass, which does not change.', '{"why":"Weight changes in proportion to field strength when mass stays constant.","sol":"Step 1: Find mass: m = W/g = 70/10 = 7 kg.\nStep 2: Use the new field strength: W = mg.\nStep 3: W = 7 × 2 = 14 N.","steps":["Step 1: Find mass: m = W/g = 70/10 = 7 kg.","Step 2: Use the new field strength: W = mg.","Step 3: W = 7 × 2 = 14 N."],"options":[],"conceptId":"physics_force_weight_in_different_gravitational_fields","skillId":"physics_force","subskillId":"physics_force_q3","subject":"physics","chapter":"force","topic":"Weight in Different Gravitational Fields"}', 2),
  (1283, 366, 'An object is moved to a location where gravitational field strength is half its original value. What happens to its weight?', 'text', 1, 'Use W = mg and keep the mass constant.', '{"why":"Only g changes in W = mg, so W changes by the same factor.","sol":"Step 1: The mass remains unchanged.\nStep 2: Weight is directly proportional to field strength.\nStep 3: Halving field strength halves weight.","steps":["Step 1: The mass remains unchanged.","Step 2: Weight is directly proportional to field strength.","Step 3: Halving field strength halves weight."],"options":[],"conceptId":"physics_force_weight_in_different_gravitational_fields","skillId":"physics_force","subskillId":"physics_force_q4","subject":"physics","chapter":"force","topic":"Weight in Different Gravitational Fields"}', 3),
  (1284, 367, 'A block slides to the right across a rough horizontal floor. Which way does friction act on the block?', 'mcq', 1, 'Friction opposes the sliding motion.', '{"why":"Friction opposes relative sliding or the tendency to slide between contacting surfaces.","sol":"Step 1: The block''s sliding direction is to the right.\nStep 2: Friction acts opposite to that sliding.\nStep 3: Therefore, friction acts to the left.","steps":["Step 1: The block''s sliding direction is to the right.","Step 2: Friction acts opposite to that sliding.","Step 3: Therefore, friction acts to the left."],"options":[{"text":"To the right","is_correct":false},{"text":"To the left","is_correct":true},{"text":"Vertically upward","is_correct":false},{"text":"Vertically downward","is_correct":false}],"conceptId":"physics_force_meaning_and_direction_of_friction","skillId":"physics_force","subskillId":"physics_force_q1","subject":"physics","chapter":"force","topic":"Meaning and Direction of Friction"}', 0),
  (1285, 367, 'A box is pulled to the left and slides left. What is the direction of friction?', 'mcq', 1, 'Identify the direction of sliding before choosing the friction direction.', '{"why":"The direction of friction is opposite to the direction of sliding in this situation.","sol":"Step 1: The box slides to the left.\nStep 2: Friction opposes the sliding.\nStep 3: Therefore, friction acts to the right.","steps":["Step 1: The box slides to the left.","Step 2: Friction opposes the sliding.","Step 3: Therefore, friction acts to the right."],"options":[{"text":"Left","is_correct":false},{"text":"Right","is_correct":true},{"text":"Upward","is_correct":false},{"text":"Downward","is_correct":false}],"conceptId":"physics_force_meaning_and_direction_of_friction","skillId":"physics_force","subskillId":"physics_force_q2","subject":"physics","chapter":"force","topic":"Meaning and Direction of Friction"}', 1),
  (1286, 367, 'A stationary box is pushed right but remains at rest. If the push is the only applied horizontal force, which way does static friction act?', 'mcq', 1, 'The box tends to move in the direction of the push.', '{"why":"Static friction can act even when surfaces are not sliding, provided there is a tendency for relative motion.","sol":"Step 1: The push tends to move the box right.\nStep 2: Static friction opposes this tendency.\nStep 3: Static friction acts left, balancing the push while the box remains at rest.","steps":["Step 1: The push tends to move the box right.","Step 2: Static friction opposes this tendency.","Step 3: Static friction acts left, balancing the push while the box remains at rest."],"options":[{"text":"Right","is_correct":false},{"text":"Left","is_correct":true},{"text":"Upward","is_correct":false},{"text":"It must be zero","is_correct":false}],"conceptId":"physics_force_meaning_and_direction_of_friction","skillId":"physics_force","subskillId":"physics_force_q3","subject":"physics","chapter":"force","topic":"Meaning and Direction of Friction"}', 2),
  (1287, 367, 'Which statement best describes friction?', 'mcq', 1, 'Think about what friction resists at the contact between two surfaces.', '{"why":"Friction can act on stationary or moving objects; its direction depends on the relative motion or its tendency.","sol":"Step 1: Friction is a contact force.\nStep 2: It opposes relative sliding or impending sliding.\nStep 3: It can act on a stationary object when motion is being resisted.","steps":["Step 1: Friction is a contact force.","Step 2: It opposes relative sliding or impending sliding.","Step 3: It can act on a stationary object when motion is being resisted."],"options":[{"text":"It always acts vertically downward.","is_correct":false},{"text":"It always acts in the direction of motion.","is_correct":false},{"text":"It opposes relative sliding or the tendency to slide between surfaces.","is_correct":true},{"text":"It acts only when an object is moving.","is_correct":false}],"conceptId":"physics_force_meaning_and_direction_of_friction","skillId":"physics_force","subskillId":"physics_force_q4","subject":"physics","chapter":"force","topic":"Meaning and Direction of Friction"}', 3),
  (1288, 368, 'A stationary box is pushed with 8 N to the right and remains at rest. What is the friction force?', 'mcq', 1, 'A stationary box has zero resultant horizontal force.', '{"why":"Static friction adjusts to balance the applied force while the object remains at rest, up to its maximum value.","sol":"Step 1: The applied horizontal force is 8 N right.\nStep 2: Since the box remains at rest, friction must balance this force.\nStep 3: Friction is 8 N left.","steps":["Step 1: The applied horizontal force is 8 N right.","Step 2: Since the box remains at rest, friction must balance this force.","Step 3: Friction is 8 N left."],"options":[{"text":"0 N","is_correct":false},{"text":"4 N to the left","is_correct":false},{"text":"8 N to the left","is_correct":true},{"text":"8 N to the right","is_correct":false}],"conceptId":"physics_force_static_and_sliding_friction","skillId":"physics_force","subskillId":"physics_force_q1","subject":"physics","chapter":"force","topic":"Static and Sliding Friction"}', 0),
  (1289, 368, 'Which type of friction acts when a book slides across a table?', 'mcq', 1, 'The book and table are moving relative to each other.', '{"why":"Sliding friction acts between surfaces that are sliding relative to one another.","sol":"Step 1: The book slides over the table.\nStep 2: The surfaces move relative to each other.\nStep 3: Therefore, sliding friction acts.","steps":["Step 1: The book slides over the table.","Step 2: The surfaces move relative to each other.","Step 3: Therefore, sliding friction acts."],"options":[{"text":"Static friction","is_correct":false},{"text":"Sliding friction","is_correct":true},{"text":"Magnetic force","is_correct":false},{"text":"Upthrust","is_correct":false}],"conceptId":"physics_force_static_and_sliding_friction","skillId":"physics_force","subskillId":"physics_force_q2","subject":"physics","chapter":"force","topic":"Static and Sliding Friction"}', 1),
  (1290, 368, 'A box remains stationary while the horizontal push increases from 3 N to 5 N. What happens to static friction, assuming the box still does not slip?', 'mcq', 1, 'For an object at rest, the horizontal forces must balance.', '{"why":"Static friction adjusts to the applied force until the maximum available static friction is reached.","sol":"Step 1: The new push is 5 N.\nStep 2: The box remains at rest, so the resultant horizontal force is zero.\nStep 3: Static friction becomes 5 N opposite to the push.","steps":["Step 1: The new push is 5 N.","Step 2: The box remains at rest, so the resultant horizontal force is zero.","Step 3: Static friction becomes 5 N opposite to the push."],"options":[{"text":"It remains at 3 N.","is_correct":false},{"text":"It becomes 5 N in the opposite direction.","is_correct":true},{"text":"It becomes zero.","is_correct":false},{"text":"It acts in the direction of the push.","is_correct":false}],"conceptId":"physics_force_static_and_sliding_friction","skillId":"physics_force","subskillId":"physics_force_q3","subject":"physics","chapter":"force","topic":"Static and Sliding Friction"}', 2),
  (1291, 368, 'Which statement is generally true for many ordinary dry surfaces?', 'mcq', 1, 'Consider why it can take more force to start moving a box than to keep it sliding.', '{"why":"This is a common pattern, not a universal rule for every material and condition.","sol":"Step 1: A stationary object may resist the start of sliding.\nStep 2: Once sliding begins, the friction force is often smaller.\nStep 3: Thus, maximum static friction is often greater than sliding friction.","steps":["Step 1: A stationary object may resist the start of sliding.","Step 2: Once sliding begins, the friction force is often smaller.","Step 3: Thus, maximum static friction is often greater than sliding friction."],"options":[{"text":"Sliding friction is always greater than maximum static friction.","is_correct":false},{"text":"Static friction never acts on a stationary object.","is_correct":false},{"text":"Maximum static friction is often greater than sliding friction.","is_correct":true},{"text":"Both types of friction always have the same magnitude.","is_correct":false}],"conceptId":"physics_force_static_and_sliding_friction","skillId":"physics_force","subskillId":"physics_force_q4","subject":"physics","chapter":"force","topic":"Static and Sliding Friction"}', 3),
  (1292, 369, 'A 20 N force acts right while friction acts left with a force of 7 N. What is the resultant horizontal force?', 'mcq', 1, 'Opposing forces are subtracted.', '{"why":"The resultant of opposite forces points in the direction of the larger force and has their difference as its magnitude.","sol":"Step 1: Take right as the positive direction.\nStep 2: Resultant = 20 N − 7 N = 13 N.\nStep 3: The larger force acts right, so the resultant is 13 N right.","steps":["Step 1: Take right as the positive direction.","Step 2: Resultant = 20 N − 7 N = 13 N.","Step 3: The larger force acts right, so the resultant is 13 N right."],"options":[{"text":"27 N right","is_correct":false},{"text":"13 N right","is_correct":true},{"text":"13 N left","is_correct":false},{"text":"7 N right","is_correct":false}],"conceptId":"physics_force_resultant_force_with_friction","skillId":"physics_force","subskillId":"physics_force_q1","subject":"physics","chapter":"force","topic":"Resultant Force with Friction"}', 0),
  (1293, 369, 'A box experiences 15 N right and 15 N left. What is the resultant force?', 'mcq', 1, 'Equal and opposite forces cancel.', '{"why":"Equal forces in opposite directions produce zero resultant force.","sol":"Step 1: The forces have equal magnitudes.\nStep 2: They act in opposite directions.\nStep 3: Resultant = 15 N − 15 N = 0 N.","steps":["Step 1: The forces have equal magnitudes.","Step 2: They act in opposite directions.","Step 3: Resultant = 15 N − 15 N = 0 N."],"options":[{"text":"30 N right","is_correct":false},{"text":"15 N left","is_correct":false},{"text":"0 N","is_correct":true},{"text":"15 N right","is_correct":false}],"conceptId":"physics_force_resultant_force_with_friction","skillId":"physics_force","subskillId":"physics_force_q2","subject":"physics","chapter":"force","topic":"Resultant Force with Friction"}', 1),
  (1294, 369, 'A 9 N force acts right and a 14 N force acts left. What is the resultant?', 'mcq', 1, 'Subtract the smaller force from the larger.', '{"why":"The resultant points in the direction of the larger force.","sol":"Step 1: The larger force is 14 N left.\nStep 2: Resultant magnitude = 14 − 9 = 5 N.\nStep 3: The resultant points left.","steps":["Step 1: The larger force is 14 N left.","Step 2: Resultant magnitude = 14 − 9 = 5 N.","Step 3: The resultant points left."],"options":[{"text":"5 N right","is_correct":false},{"text":"23 N left","is_correct":false},{"text":"5 N left","is_correct":true},{"text":"14 N right","is_correct":false}],"conceptId":"physics_force_resultant_force_with_friction","skillId":"physics_force","subskillId":"physics_force_q3","subject":"physics","chapter":"force","topic":"Resultant Force with Friction"}', 2),
  (1295, 369, 'A trolley moves at constant velocity in a straight line. What is its resultant force?', 'mcq', 1, 'Constant velocity means constant speed and direction.', '{"why":"An object can keep moving at constant velocity when its resultant force is zero.","sol":"Step 1: Constant velocity means there is no acceleration.\nStep 2: Newton''s laws connect zero acceleration with zero resultant force.\nStep 3: Therefore, the resultant force is zero.","steps":["Step 1: Constant velocity means there is no acceleration.","Step 2: Newton''s laws connect zero acceleration with zero resultant force.","Step 3: Therefore, the resultant force is zero."],"options":[{"text":"Always forward","is_correct":false},{"text":"Zero","is_correct":true},{"text":"Always backward","is_correct":false},{"text":"Equal to its weight","is_correct":false}],"conceptId":"physics_force_resultant_force_with_friction","skillId":"physics_force","subskillId":"physics_force_q4","subject":"physics","chapter":"force","topic":"Resultant Force with Friction"}', 3),
  (1296, 370, 'A trolley moves in a straight line at constant velocity. What is its resultant force?', 'mcq', 1, 'Ask whether its velocity is changing.', '{"why":"A non-zero resultant force is needed to change velocity, not to maintain constant velocity.","sol":"Step 1: The velocity is constant.\nStep 2: Therefore, acceleration is zero.\nStep 3: From Newton''s first law, the resultant force is zero.","steps":["Step 1: The velocity is constant.","Step 2: Therefore, acceleration is zero.","Step 3: From Newton''s first law, the resultant force is zero."],"options":[{"text":"Zero","is_correct":true},{"text":"Equal to its mass","is_correct":false},{"text":"Always forward","is_correct":false},{"text":"Always backward","is_correct":false}],"conceptId":"physics_force_newton_s_first_law_and_inertia","skillId":"physics_force","subskillId":"physics_force_q1","subject":"physics","chapter":"force","topic":"Newton''s First Law and Inertia"}', 0),
  (1297, 370, 'What is inertia?', 'mcq', 1, 'Think about an object''s resistance to starting, stopping, or changing direction.', '{"why":"Objects with greater mass have greater inertia.","sol":"Step 1: Inertia describes resistance to changes in motion.\nStep 2: It is a property of matter.\nStep 3: Mass is a measure of inertia.","steps":["Step 1: Inertia describes resistance to changes in motion.","Step 2: It is a property of matter.","Step 3: Mass is a measure of inertia."],"options":[{"text":"The force that pulls objects downward","is_correct":false},{"text":"The tendency to resist a change in motion","is_correct":true},{"text":"The distance travelled per second","is_correct":false},{"text":"The energy stored in an object","is_correct":false}],"conceptId":"physics_force_newton_s_first_law_and_inertia","skillId":"physics_force","subskillId":"physics_force_q2","subject":"physics","chapter":"force","topic":"Newton''s First Law and Inertia"}', 1),
  (1298, 370, 'Two stationary trolleys have different masses. Which has greater inertia?', 'mcq', 1, 'Compare their masses.', '{"why":"Mass measures an object''s inertia.","sol":"Step 1: Inertia depends on mass.\nStep 2: The heavier trolley has greater mass.\nStep 3: Therefore, it has greater inertia.","steps":["Step 1: Inertia depends on mass.","Step 2: The heavier trolley has greater mass.","Step 3: Therefore, it has greater inertia."],"options":[{"text":"The lighter trolley","is_correct":false},{"text":"The heavier trolley","is_correct":true},{"text":"Both always have equal inertia","is_correct":false},{"text":"The trolley with the greater speed","is_correct":false}],"conceptId":"physics_force_newton_s_first_law_and_inertia","skillId":"physics_force","subskillId":"physics_force_q3","subject":"physics","chapter":"force","topic":"Newton''s First Law and Inertia"}', 2),
  (1299, 370, 'A book rests on a table. Its weight is balanced by the table''s upward support force. What is the resultant vertical force?', 'mcq', 1, 'Equal forces in opposite directions cancel.', '{"why":"Balanced vertical forces mean the book has no vertical acceleration.","sol":"Step 1: Weight acts downward.\nStep 2: The support force acts upward with equal magnitude.\nStep 3: The resultant vertical force is zero.","steps":["Step 1: Weight acts downward.","Step 2: The support force acts upward with equal magnitude.","Step 3: The resultant vertical force is zero."],"options":[{"text":"Its weight downward","is_correct":false},{"text":"The support force upward","is_correct":false},{"text":"Zero","is_correct":true},{"text":"Twice its weight","is_correct":false}],"conceptId":"physics_force_newton_s_first_law_and_inertia","skillId":"physics_force","subskillId":"physics_force_q4","subject":"physics","chapter":"force","topic":"Newton''s First Law and Inertia"}', 3),
  (1300, 371, 'A 4 kg object accelerates at 3 m/s². What is the resultant force?', 'mcq', 1, 'Use F = ma.', '{"why":"Newton''s second law states that resultant force equals mass multiplied by acceleration.","sol":"Step 1: Formula: F = ma.\nStep 2: Substitute m = 4 kg and a = 3 m/s².\nStep 3: F = 4 × 3 = 12 N.","steps":["Step 1: Formula: F = ma.","Step 2: Substitute m = 4 kg and a = 3 m/s².","Step 3: F = 4 × 3 = 12 N."],"options":[{"text":"7 N","is_correct":false},{"text":"1.33 N","is_correct":false},{"text":"12 N","is_correct":true},{"text":"24 N","is_correct":false}],"conceptId":"physics_force_newton_s_second_law_force_mass_and_acceleration","skillId":"physics_force","subskillId":"physics_force_q1","subject":"physics","chapter":"force","topic":"Newton''s Second Law: Force, Mass and Acceleration"}', 0),
  (1301, 371, 'A resultant force of 20 N acts on a 5 kg trolley. Calculate its acceleration.', 'mcq', 1, 'Rearrange F = ma to make acceleration the subject.', '{"why":"Acceleration equals resultant force divided by mass.","sol":"Step 1: F = ma.\nStep 2: a = F/m.\nStep 3: a = 20/5 = 4 m/s².","steps":["Step 1: F = ma.","Step 2: a = F/m.","Step 3: a = 20/5 = 4 m/s²."],"options":[{"text":"4 m/s²","is_correct":true},{"text":"100 m/s²","is_correct":false},{"text":"25 m/s²","is_correct":false},{"text":"0.25 m/s²","is_correct":false}],"conceptId":"physics_force_newton_s_second_law_force_mass_and_acceleration","skillId":"physics_force","subskillId":"physics_force_q2","subject":"physics","chapter":"force","topic":"Newton''s Second Law: Force, Mass and Acceleration"}', 1),
  (1302, 371, 'A resultant force of 18 N produces an acceleration of 6 m/s². What is the mass?', 'mcq', 1, 'Rearrange F = ma to find mass.', '{"why":"Mass equals resultant force divided by acceleration.","sol":"Step 1: F = ma.\nStep 2: m = F/a.\nStep 3: m = 18/6 = 3 kg.","steps":["Step 1: F = ma.","Step 2: m = F/a.","Step 3: m = 18/6 = 3 kg."],"options":[{"text":"108 kg","is_correct":false},{"text":"24 kg","is_correct":false},{"text":"3 kg","is_correct":true},{"text":"12 kg","is_correct":false}],"conceptId":"physics_force_newton_s_second_law_force_mass_and_acceleration","skillId":"physics_force","subskillId":"physics_force_q3","subject":"physics","chapter":"force","topic":"Newton''s Second Law: Force, Mass and Acceleration"}', 2),
  (1303, 371, 'The same resultant force acts on two objects. Object A has mass 2 kg and object B has mass 4 kg. How do their accelerations compare?', 'mcq', 1, 'For a fixed force, acceleration is inversely proportional to mass.', '{"why":"For the same resultant force, doubling the mass halves the acceleration.","sol":"Step 1: Newton''s second law gives a = F/m.\nStep 2: Object B has twice the mass of object A.\nStep 3: Therefore, object B has half the acceleration of object A.","steps":["Step 1: Newton''s second law gives a = F/m.","Step 2: Object B has twice the mass of object A.","Step 3: Therefore, object B has half the acceleration of object A."],"options":[{"text":"A''s acceleration is twice B''s.","is_correct":true},{"text":"B''s acceleration is twice A''s.","is_correct":false},{"text":"Their accelerations are equal.","is_correct":false},{"text":"Both accelerations must be zero.","is_correct":false}],"conceptId":"physics_force_newton_s_second_law_force_mass_and_acceleration","skillId":"physics_force","subskillId":"physics_force_q4","subject":"physics","chapter":"force","topic":"Newton''s Second Law: Force, Mass and Acceleration"}', 3),
  (1304, 372, 'A stone moves around a circle at constant speed. Why is its velocity changing?', 'mcq', 1, 'Velocity includes both speed and direction.', '{"why":"Velocity is a vector quantity, so a change in direction is a change in velocity.","sol":"Step 1: The stone''s speed remains constant.\nStep 2: Its direction changes as it moves around the circle.\nStep 3: Therefore, its velocity changes.","steps":["Step 1: The stone''s speed remains constant.","Step 2: Its direction changes as it moves around the circle.","Step 3: Therefore, its velocity changes."],"options":[{"text":"Its mass changes.","is_correct":false},{"text":"Its direction changes continuously.","is_correct":true},{"text":"Its speed must increase.","is_correct":false},{"text":"Gravity disappears.","is_correct":false}],"conceptId":"physics_force_meaning_of_circular_motion","skillId":"physics_force","subskillId":"physics_force_q1","subject":"physics","chapter":"force","topic":"Meaning of Circular Motion"}', 0),
  (1305, 372, 'A car moves around a circular track at constant speed. Is it accelerating?', 'mcq', 1, 'Acceleration means a change in velocity, not only a change in speed.', '{"why":"An object can accelerate while maintaining constant speed if its direction changes.","sol":"Step 1: The car''s direction changes around the track.\nStep 2: Its velocity therefore changes.\nStep 3: A change in velocity means acceleration.","steps":["Step 1: The car''s direction changes around the track.","Step 2: Its velocity therefore changes.","Step 3: A change in velocity means acceleration."],"options":[{"text":"No, because its speed is constant.","is_correct":false},{"text":"Yes, because its direction changes.","is_correct":true},{"text":"No, because its mass is constant.","is_correct":false},{"text":"Only if its engine produces more power.","is_correct":false}],"conceptId":"physics_force_meaning_of_circular_motion","skillId":"physics_force","subskillId":"physics_force_q2","subject":"physics","chapter":"force","topic":"Meaning of Circular Motion"}', 1),
  (1306, 372, 'Which object has zero acceleration, assuming its speed and direction remain unchanged?', 'mcq', 1, 'Look for motion with no change in speed or direction.', '{"why":"Acceleration is the rate of change of velocity.","sol":"Step 1: Constant velocity means speed and direction are unchanged.\nStep 2: There is no change in velocity.\nStep 3: Therefore, acceleration is zero.","steps":["Step 1: Constant velocity means speed and direction are unchanged.","Step 2: There is no change in velocity.","Step 3: Therefore, acceleration is zero."],"options":[{"text":"A car turning around a bend","is_correct":false},{"text":"A stone moving in a circle","is_correct":false},{"text":"A trolley moving straight at constant velocity","is_correct":true},{"text":"A car speeding up on a straight road","is_correct":false}],"conceptId":"physics_force_meaning_of_circular_motion","skillId":"physics_force","subskillId":"physics_force_q3","subject":"physics","chapter":"force","topic":"Meaning of Circular Motion"}', 2),
  (1307, 373, 'An object moves at 4 m/s in a circle of radius 8 m. What is its centripetal acceleration?', 'mcq', 1, 'Use a = v²/r.', '{"why":"Centripetal acceleration is the square of speed divided by the radius.","sol":"Step 1: Formula: a = v²/r.\nStep 2: Substitute: a = 4²/8.\nStep 3: a = 16/8 = 2 m/s².","steps":["Step 1: Formula: a = v²/r.","Step 2: Substitute: a = 4²/8.","Step 3: a = 16/8 = 2 m/s²."],"options":[{"text":"0.5 m/s²","is_correct":false},{"text":"2 m/s²","is_correct":true},{"text":"4 m/s²","is_correct":false},{"text":"32 m/s²","is_correct":false}],"conceptId":"physics_force_centripetal_acceleration","skillId":"physics_force","subskillId":"physics_force_q1","subject":"physics","chapter":"force","topic":"Centripetal Acceleration"}', 0),
  (1308, 373, 'An object moves at 6 m/s in a circle of radius 3 m. Calculate its centripetal acceleration.', 'mcq', 1, 'Square 6 before dividing by 3.', '{"why":"The speed must be squared before dividing by the radius.","sol":"Step 1: a = v²/r.\nStep 2: a = 6²/3.\nStep 3: a = 36/3 = 12 m/s².","steps":["Step 1: a = v²/r.","Step 2: a = 6²/3.","Step 3: a = 36/3 = 12 m/s²."],"options":[{"text":"2 m/s²","is_correct":false},{"text":"12 m/s²","is_correct":true},{"text":"18 m/s²","is_correct":false},{"text":"36 m/s²","is_correct":false}],"conceptId":"physics_force_centripetal_acceleration","skillId":"physics_force","subskillId":"physics_force_q2","subject":"physics","chapter":"force","topic":"Centripetal Acceleration"}', 1),
  (1309, 373, 'An object moves at 5 m/s in a circle of radius 10 m. What is its centripetal acceleration?', 'mcq', 1, 'Substitute the speed and radius into a = v²/r.', '{"why":"Centripetal acceleration depends on the square of speed and inversely on radius.","sol":"Step 1: a = v²/r.\nStep 2: a = 5²/10.\nStep 3: a = 25/10 = 2.5 m/s².","steps":["Step 1: a = v²/r.","Step 2: a = 5²/10.","Step 3: a = 25/10 = 2.5 m/s²."],"options":[{"text":"0.5 m/s²","is_correct":false},{"text":"2.5 m/s²","is_correct":true},{"text":"5 m/s²","is_correct":false},{"text":"25 m/s²","is_correct":false}],"conceptId":"physics_force_centripetal_acceleration","skillId":"physics_force","subskillId":"physics_force_q3","subject":"physics","chapter":"force","topic":"Centripetal Acceleration"}', 2),
  (1310, 373, 'If the speed of an object doubles while the radius stays constant, what happens to its centripetal acceleration?', 'mcq', 1, 'The formula contains v², not just v.', '{"why":"Centripetal acceleration is proportional to the square of speed when radius is fixed.","sol":"Step 1: Initial acceleration: a = v²/r.\nStep 2: New speed: 2v.\nStep 3: New acceleration: (2v)²/r = 4v²/r.","steps":["Step 1: Initial acceleration: a = v²/r.","Step 2: New speed: 2v.","Step 3: New acceleration: (2v)²/r = 4v²/r."],"options":[{"text":"It doubles.","is_correct":false},{"text":"It becomes half.","is_correct":false},{"text":"It becomes four times as large.","is_correct":true},{"text":"It remains unchanged.","is_correct":false}],"conceptId":"physics_force_centripetal_acceleration","skillId":"physics_force","subskillId":"physics_force_q4","subject":"physics","chapter":"force","topic":"Centripetal Acceleration"}', 3),
  (1311, 374, 'A 2 kg object moves at 3 m/s in a circle of radius 6 m. What centripetal force is required?', 'mcq', 1, 'Use F = mv²/r.', '{"why":"The inward resultant force required for circular motion is mv²/r.","sol":"Step 1: F = mv²/r.\nStep 2: F = (2 × 3²)/6.\nStep 3: F = 18/6 = 3 N towards the centre.","steps":["Step 1: F = mv²/r.","Step 2: F = (2 × 3²)/6.","Step 3: F = 18/6 = 3 N towards the centre."],"options":[{"text":"1 N","is_correct":false},{"text":"3 N","is_correct":true},{"text":"6 N","is_correct":false},{"text":"18 N","is_correct":false}],"conceptId":"physics_force_centripetal_force","skillId":"physics_force","subskillId":"physics_force_q1","subject":"physics","chapter":"force","topic":"Centripetal Force"}', 0),
  (1312, 374, 'A 4 kg object moves at 5 m/s in a circle of radius 10 m. Find the centripetal force.', 'mcq', 1, 'Square the speed, multiply by mass, then divide by radius.', '{"why":"The centripetal force depends on mass, the square of speed, and radius.","sol":"Step 1: F = mv²/r.\nStep 2: F = (4 × 25)/10.\nStep 3: F = 100/10 = 10 N towards the centre.","steps":["Step 1: F = mv²/r.","Step 2: F = (4 × 25)/10.","Step 3: F = 100/10 = 10 N towards the centre."],"options":[{"text":"2 N","is_correct":false},{"text":"10 N","is_correct":true},{"text":"20 N","is_correct":false},{"text":"100 N","is_correct":false}],"conceptId":"physics_force_centripetal_force","skillId":"physics_force","subskillId":"physics_force_q2","subject":"physics","chapter":"force","topic":"Centripetal Force"}', 1),
  (1313, 374, 'A stone moves in a horizontal circle on a string. In the idealised model, which force supplies the inward force?', 'mcq', 1, 'Identify the physical force directed along the string towards the centre.', '{"why":"Centripetal force is the role of the inward resultant force, not an additional type of force.","sol":"Step 1: Circular motion requires an inward resultant force.\nStep 2: The string pulls the stone towards the centre.\nStep 3: Tension supplies the inward force in this model.","steps":["Step 1: Circular motion requires an inward resultant force.","Step 2: The string pulls the stone towards the centre.","Step 3: Tension supplies the inward force in this model."],"options":[{"text":"Tension in the string","is_correct":true},{"text":"The stone''s mass","is_correct":false},{"text":"The stone''s speed","is_correct":false},{"text":"Centrifugal force from a second string","is_correct":false}],"conceptId":"physics_force_centripetal_force","skillId":"physics_force","subskillId":"physics_force_q3","subject":"physics","chapter":"force","topic":"Centripetal Force"}', 2),
  (1314, 374, 'Which statement about centripetal force is correct?', 'mcq', 1, 'The force supplying it depends on the physical situation.', '{"why":"Tension, friction, gravity or contact forces can supply the inward resultant force in different situations.","sol":"Step 1: Circular motion requires an inward resultant force.\nStep 2: Different physical forces can provide this force.\nStep 3: Therefore, centripetal force describes the inward resultant force.","steps":["Step 1: Circular motion requires an inward resultant force.","Step 2: Different physical forces can provide this force.","Step 3: Therefore, centripetal force describes the inward resultant force."],"options":[{"text":"It is always supplied by gravity.","is_correct":false},{"text":"It is always supplied by friction.","is_correct":false},{"text":"It is the inward resultant force required for circular motion.","is_correct":true},{"text":"It always acts away from the centre.","is_correct":false}],"conceptId":"physics_force_centripetal_force","skillId":"physics_force","subskillId":"physics_force_q4","subject":"physics","chapter":"force","topic":"Centripetal Force"}', 3),
  (1315, 375, 'A car requires 100 N of centripetal force. If its speed doubles and the radius stays constant, what force is required?', 'mcq', 1, 'Centripetal force is proportional to the square of speed.', '{"why":"With constant mass and radius, F is proportional to v².","sol":"Step 1: Initial force is 100 N.\nStep 2: Doubling speed multiplies force by 2² = 4.\nStep 3: New force = 4 × 100 = 400 N.","steps":["Step 1: Initial force is 100 N.","Step 2: Doubling speed multiplies force by 2² = 4.","Step 3: New force = 4 × 100 = 400 N."],"options":[{"text":"200 N","is_correct":false},{"text":"300 N","is_correct":false},{"text":"400 N","is_correct":true},{"text":"50 N","is_correct":false}],"conceptId":"physics_force_effect_of_speed_and_radius_on_centripetal_force","skillId":"physics_force","subskillId":"physics_force_q1","subject":"physics","chapter":"force","topic":"Effect of Speed and Radius on Centripetal Force"}', 0),
  (1316, 375, 'A body requires 60 N of centripetal force. If its radius doubles while mass and speed remain constant, what is the new force?', 'mcq', 1, 'Force is inversely proportional to radius.', '{"why":"For constant mass and speed, F = mv²/r, so increasing radius decreases the required force.","sol":"Step 1: The radius doubles.\nStep 2: For constant mass and speed, doubling radius halves the force.\nStep 3: New force = 60/2 = 30 N.","steps":["Step 1: The radius doubles.","Step 2: For constant mass and speed, doubling radius halves the force.","Step 3: New force = 60/2 = 30 N."],"options":[{"text":"120 N","is_correct":false},{"text":"60 N","is_correct":false},{"text":"30 N","is_correct":true},{"text":"15 N","is_correct":false}],"conceptId":"physics_force_effect_of_speed_and_radius_on_centripetal_force","skillId":"physics_force","subskillId":"physics_force_q2","subject":"physics","chapter":"force","topic":"Effect of Speed and Radius on Centripetal Force"}', 1),
  (1317, 375, 'A body requires 8 N of centripetal force. If its speed triples while mass and radius stay constant, what force is required?', 'mcq', 1, 'Tripling speed multiplies the force by 3².', '{"why":"Centripetal force depends on the square of speed.","sol":"Step 1: The speed becomes three times its original value.\nStep 2: The required force becomes 3² = 9 times as large.\nStep 3: New force = 9 × 8 = 72 N.","steps":["Step 1: The speed becomes three times its original value.","Step 2: The required force becomes 3² = 9 times as large.","Step 3: New force = 9 × 8 = 72 N."],"options":[{"text":"24 N","is_correct":false},{"text":"36 N","is_correct":false},{"text":"72 N","is_correct":true},{"text":"8 N","is_correct":false}],"conceptId":"physics_force_effect_of_speed_and_radius_on_centripetal_force","skillId":"physics_force","subskillId":"physics_force_q3","subject":"physics","chapter":"force","topic":"Effect of Speed and Radius on Centripetal Force"}', 2),
  (1318, 375, 'Which change reduces the required centripetal force if mass remains constant?', 'mcq', 1, 'Use F = mv²/r and change one quantity at a time.', '{"why":"Centripetal force is inversely proportional to radius when mass and speed are constant.","sol":"Step 1: Force increases when speed increases.\nStep 2: Force increases when radius decreases.\nStep 3: Increasing radius while keeping speed fixed reduces force.","steps":["Step 1: Force increases when speed increases.","Step 2: Force increases when radius decreases.","Step 3: Increasing radius while keeping speed fixed reduces force."],"options":[{"text":"Doubling speed and keeping radius fixed","is_correct":false},{"text":"Halving radius and keeping speed fixed","is_correct":false},{"text":"Doubling radius and keeping speed fixed","is_correct":true},{"text":"Tripling speed and keeping radius fixed","is_correct":false}],"conceptId":"physics_force_effect_of_speed_and_radius_on_centripetal_force","skillId":"physics_force","subskillId":"physics_force_q4","subject":"physics","chapter":"force","topic":"Effect of Speed and Radius on Centripetal Force"}', 3),
  (1319, 376, 'Calculate the weight of a 5 kg object where g = 10 N/kg.', 'mcq', 1, 'Use W = mg.', '{"why":"Weight is mass multiplied by gravitational field strength.","sol":"Step 1: W = mg.\nStep 2: Substitute m = 5 kg and g = 10 N/kg.\nStep 3: W = 5 × 10 = 50 N.","steps":["Step 1: W = mg.","Step 2: Substitute m = 5 kg and g = 10 N/kg.","Step 3: W = 5 × 10 = 50 N."],"options":[{"text":"0.5 N","is_correct":false},{"text":"5 N","is_correct":false},{"text":"50 N","is_correct":true},{"text":"500 N","is_correct":false}],"conceptId":"physics_force_gravitation_and_gravitational_force","skillId":"physics_force","subskillId":"physics_force_q1","subject":"physics","chapter":"force","topic":"Gravitation and Gravitational Force"}', 0),
  (1320, 376, 'Two objects are in the same gravitational field. Object A has mass 2 kg and object B has mass 6 kg. How do their weights compare?', 'mcq', 1, 'Weight is proportional to mass when gravitational field strength is the same.', '{"why":"At the same location, weight is directly proportional to mass.","sol":"Step 1: W = mg.\nStep 2: Both objects have the same g.\nStep 3: Since 6 kg is three times 2 kg, B''s weight is three times A''s.","steps":["Step 1: W = mg.","Step 2: Both objects have the same g.","Step 3: Since 6 kg is three times 2 kg, B''s weight is three times A''s."],"options":[{"text":"A has three times B''s weight.","is_correct":false},{"text":"B has three times A''s weight.","is_correct":true},{"text":"Their weights must be equal.","is_correct":false},{"text":"Both have zero weight.","is_correct":false}],"conceptId":"physics_force_gravitation_and_gravitational_force","skillId":"physics_force","subskillId":"physics_force_q2","subject":"physics","chapter":"force","topic":"Gravitation and Gravitational Force"}', 1),
  (1321, 376, 'An object has mass 4 kg in a gravitational field of 2 N/kg. What is its weight?', 'mcq', 1, 'Multiply mass by gravitational field strength.', '{"why":"The weight of an object depends on its mass and the local gravitational field strength.","sol":"Step 1: W = mg.\nStep 2: W = 4 × 2.\nStep 3: W = 8 N.","steps":["Step 1: W = mg.","Step 2: W = 4 × 2.","Step 3: W = 8 N."],"options":[{"text":"2 N","is_correct":false},{"text":"6 N","is_correct":false},{"text":"8 N","is_correct":true},{"text":"16 N","is_correct":false}],"conceptId":"physics_force_gravitation_and_gravitational_force","skillId":"physics_force","subskillId":"physics_force_q3","subject":"physics","chapter":"force","topic":"Gravitation and Gravitational Force"}', 2),
  (1322, 376, 'Which statement about mass and weight is correct?', 'mcq', 1, 'Compare the units and the formula W = mg.', '{"why":"Mass is an intrinsic property of an object, while weight depends on the gravitational field.","sol":"Step 1: Mass is measured in kilograms.\nStep 2: Weight is a force measured in newtons.\nStep 3: Changing g changes W when mass stays constant.","steps":["Step 1: Mass is measured in kilograms.","Step 2: Weight is a force measured in newtons.","Step 3: Changing g changes W when mass stays constant."],"options":[{"text":"Mass is measured in newtons.","is_correct":false},{"text":"Weight is measured in kilograms.","is_correct":false},{"text":"Mass remains the same when gravitational field strength changes, but weight changes.","is_correct":true},{"text":"Mass and weight always have the same numerical value.","is_correct":false}],"conceptId":"physics_force_gravitation_and_gravitational_force","skillId":"physics_force","subskillId":"physics_force_q4","subject":"physics","chapter":"force","topic":"Gravitation and Gravitational Force"}', 3),
  (1323, 377, 'What must change for an object to be moving relative to a chosen reference?', 'text', 1, 'Compare its location at different times.', '{"why":"Motion is defined by change in position relative to a reference.","sol":"Step 1: Identify key concept: Define the required principles for Describing Position and Motion.\nStep 2: Apply governing rule: Motion is defined by change in position relative to a reference.\nStep 3: State the final conclusion: Its position relative to that reference must change over time.","steps":["Step 1: Identify key concept: Define the required principles for Describing Position and Motion.","Step 2: Apply governing rule: Motion is defined by change in position relative to a reference.","Step 3: State the final conclusion: Its position relative to that reference must change over time."],"options":[],"conceptId":"physics_motion_describing_position_and_motion","skillId":"physics_motion","subskillId":"physics_motion_q1","subject":"physics","chapter":"motion","topic":"Describing Position and Motion"}', 0),
  (1324, 377, 'East is positive and a lamp is 6 m west of the origin. What is its position?', 'text', 1, 'West is opposite to the positive direction.', '{"why":"A signed position is negative on the side opposite the chosen positive direction.","sol":"Step 1: Identify key concept: Define the required principles for Describing Position and Motion.\nStep 2: Apply governing rule: A signed position is negative on the side opposite the chosen positive direction.\nStep 3: State the final conclusion: −6 m.","steps":["Step 1: Identify key concept: Define the required principles for Describing Position and Motion.","Step 2: Apply governing rule: A signed position is negative on the side opposite the chosen positive direction.","Step 3: State the final conclusion: −6 m."],"options":[],"conceptId":"physics_motion_describing_position_and_motion","skillId":"physics_motion","subskillId":"physics_motion_q2","subject":"physics","chapter":"motion","topic":"Describing Position and Motion"}', 1),
  (1325, 377, 'A passenger sits still in a moving bus. Is the passenger moving?', 'text', 1, 'Specify the reference frame.', '{"why":"Motion depends on the reference used.","sol":"Step 1: Identify key concept: Define the required principles for Describing Position and Motion.\nStep 2: Apply governing rule: Motion depends on the reference used.\nStep 3: State the final conclusion: The passenger is at rest relative to the bus but moving relative to the road.","steps":["Step 1: Identify key concept: Define the required principles for Describing Position and Motion.","Step 2: Apply governing rule: Motion depends on the reference used.","Step 3: State the final conclusion: The passenger is at rest relative to the bus but moving relative to the road."],"options":[],"conceptId":"physics_motion_describing_position_and_motion","skillId":"physics_motion","subskillId":"physics_motion_q3","subject":"physics","chapter":"motion","topic":"Describing Position and Motion"}', 2),
  (1326, 377, 'What is a reference point used for when describing motion?', 'text', 1, 'It provides a basis for comparing location.', '{"why":"Without a reference, a location or motion description may be ambiguous.","sol":"Step 1: Identify key concept: Define the required principles for Describing Position and Motion.\nStep 2: Apply governing rule: Without a reference, a location or motion description may be ambiguous.\nStep 3: State the final conclusion: It provides a fixed or specified location against which an object''s position and changes in position are described.","steps":["Step 1: Identify key concept: Define the required principles for Describing Position and Motion.","Step 2: Apply governing rule: Without a reference, a location or motion description may be ambiguous.","Step 3: State the final conclusion: It provides a fixed or specified location against which an object''s position and changes in position are described."],"options":[],"conceptId":"physics_motion_describing_position_and_motion","skillId":"physics_motion","subskillId":"physics_motion_q4","subject":"physics","chapter":"motion","topic":"Describing Position and Motion"}', 3),
  (1327, 377, 'A stationary object remains 3 m north of a post throughout an observation. Is it moving relative to the post?', 'text', 1, 'Its position does not change.', '{"why":"Its position relative to the chosen reference remains constant.","sol":"Step 1: Identify key concept: Define the required principles for Describing Position and Motion.\nStep 2: Apply governing rule: Its position relative to the chosen reference remains constant.\nStep 3: State the final conclusion: No. It is at rest relative to the post.","steps":["Step 1: Identify key concept: Define the required principles for Describing Position and Motion.","Step 2: Apply governing rule: Its position relative to the chosen reference remains constant.","Step 3: State the final conclusion: No. It is at rest relative to the post."],"options":[],"conceptId":"physics_motion_describing_position_and_motion","skillId":"physics_motion","subskillId":"physics_motion_q5","subject":"physics","chapter":"motion","topic":"Describing Position and Motion"}', 4),
  (1328, 377, 'A passenger sits still on a bus travelling along a road. Is the passenger moving relative to the bus?', 'text', 1, 'Use the bus as the reference point.', '{"why":"The passenger''s position relative to the bus does not change.","sol":"Step 1: Identify key concept: Define the required principles for Describing Position and Motion.\nStep 2: Apply governing rule: The passenger''s position relative to the bus does not change.\nStep 3: State the final conclusion: No. The passenger is at rest relative to the bus.","steps":["Step 1: Identify key concept: Define the required principles for Describing Position and Motion.","Step 2: Apply governing rule: The passenger''s position relative to the bus does not change.","Step 3: State the final conclusion: No. The passenger is at rest relative to the bus."],"options":[],"conceptId":"physics_motion_describing_position_and_motion","skillId":"physics_motion","subskillId":"physics_motion_q6","subject":"physics","chapter":"motion","topic":"Describing Position and Motion"}', 5),
  (1329, 377, 'The same passenger is observed by someone standing beside the road. Is the passenger moving relative to that observer?', 'text', 1, 'Use the roadside observer as the reference point.', '{"why":"The passenger''s position relative to the roadside observer changes.","sol":"Step 1: Identify key concept: Define the required principles for Describing Position and Motion.\nStep 2: Apply governing rule: The passenger''s position relative to the roadside observer changes.\nStep 3: State the final conclusion: Yes. The passenger moves with the bus relative to the road.","steps":["Step 1: Identify key concept: Define the required principles for Describing Position and Motion.","Step 2: Apply governing rule: The passenger''s position relative to the roadside observer changes.","Step 3: State the final conclusion: Yes. The passenger moves with the bus relative to the road."],"options":[],"conceptId":"physics_motion_describing_position_and_motion","skillId":"physics_motion","subskillId":"physics_motion_q7","subject":"physics","chapter":"motion","topic":"Describing Position and Motion"}', 6),
  (1330, 377, 'What is a reference point used for when describing motion?', 'text', 1, 'It provides the location against which position is compared.', '{"why":"Motion is identified by changes in position relative to a reference.","sol":"Step 1: Identify key concept: Define the required principles for Describing Position and Motion.\nStep 2: Apply governing rule: Motion is identified by changes in position relative to a reference.\nStep 3: State the final conclusion: It provides a fixed location or observer against which an object''s position is compared.","steps":["Step 1: Identify key concept: Define the required principles for Describing Position and Motion.","Step 2: Apply governing rule: Motion is identified by changes in position relative to a reference.","Step 3: State the final conclusion: It provides a fixed location or observer against which an object''s position is compared."],"options":[],"conceptId":"physics_motion_describing_position_and_motion","skillId":"physics_motion","subskillId":"physics_motion_q8","subject":"physics","chapter":"motion","topic":"Describing Position and Motion"}', 7),
  (1331, 377, 'A car remains in the same parking space for ten minutes. Is it moving relative to the parking space?', 'text', 1, 'Check whether its position changes relative to that space.', '{"why":"Its position relative to the chosen reference remains unchanged.","sol":"Step 1: Identify key concept: Define the required principles for Describing Position and Motion.\nStep 2: Apply governing rule: Its position relative to the chosen reference remains unchanged.\nStep 3: State the final conclusion: No. It is at rest relative to the parking space.","steps":["Step 1: Identify key concept: Define the required principles for Describing Position and Motion.","Step 2: Apply governing rule: Its position relative to the chosen reference remains unchanged.","Step 3: State the final conclusion: No. It is at rest relative to the parking space."],"options":[],"conceptId":"physics_motion_describing_position_and_motion","skillId":"physics_motion","subskillId":"physics_motion_q9","subject":"physics","chapter":"motion","topic":"Describing Position and Motion"}', 8),
  (1332, 377, 'Why can one object be described as at rest by one observer and moving by another?', 'text', 1, 'Observers can use different reference points.', '{"why":"An object''s position may stay constant relative to one reference while changing relative to another.","sol":"Step 1: Identify key concept: Define the required principles for Describing Position and Motion.\nStep 2: Apply governing rule: An object''s position may stay constant relative to one reference while changing relative to another.\nStep 3: State the final conclusion: Because motion depends on the reference point used.","steps":["Step 1: Identify key concept: Define the required principles for Describing Position and Motion.","Step 2: Apply governing rule: An object''s position may stay constant relative to one reference while changing relative to another.","Step 3: State the final conclusion: Because motion depends on the reference point used."],"options":[],"conceptId":"physics_motion_describing_position_and_motion","skillId":"physics_motion","subskillId":"physics_motion_q10","subject":"physics","chapter":"motion","topic":"Describing Position and Motion"}', 9),
  (1333, 378, 'A person walks 10 m forward and 10 m back to the starting point. Find distance and displacement.', 'text', 1, 'Add path lengths, then compare the initial and final positions.', '{"why":"Distance counts the whole path, while displacement measures net change in position.","sol":"Step 1: Distance = 10 + 10 = 20 m.\nStep 2: The person returns to the starting point.\nStep 3: Displacement = 0 m.","steps":["Step 1: Distance = 10 + 10 = 20 m.","Step 2: The person returns to the starting point.","Step 3: Displacement = 0 m."],"options":[],"conceptId":"physics_motion_distance_and_displacement","skillId":"physics_motion","subskillId":"physics_motion_q1","subject":"physics","chapter":"motion","topic":"Distance and Displacement"}', 0),
  (1334, 378, 'A car travels 30 m east and then 40 m east. Find distance and displacement.', 'text', 1, 'Both movements have the same direction.', '{"why":"With straight-line movement in one direction, distance equals the magnitude of displacement.","sol":"Step 1: Distance = 30 + 40 = 70 m.\nStep 2: Net displacement = 70 m east.","steps":["Step 1: Distance = 30 + 40 = 70 m.","Step 2: Net displacement = 70 m east."],"options":[],"conceptId":"physics_motion_distance_and_displacement","skillId":"physics_motion","subskillId":"physics_motion_q2","subject":"physics","chapter":"motion","topic":"Distance and Displacement"}', 1),
  (1335, 378, 'A person walks 15 m north and then 5 m south. Find distance and displacement.', 'text', 1, 'Add for distance; subtract opposing movements for displacement.', '{"why":"Displacement represents the net change in position.","sol":"Step 1: Distance = 15 + 5 = 20 m.\nStep 2: Net movement = 15 − 5 = 10 m.\nStep 3: The remaining displacement is northward.","steps":["Step 1: Distance = 15 + 5 = 20 m.","Step 2: Net movement = 15 − 5 = 10 m.","Step 3: The remaining displacement is northward."],"options":[],"conceptId":"physics_motion_distance_and_displacement","skillId":"physics_motion","subskillId":"physics_motion_q3","subject":"physics","chapter":"motion","topic":"Distance and Displacement"}', 2),
  (1336, 378, 'A car travels 100 m east and then 100 m west. Find distance and displacement.', 'text', 1, 'Check whether the final position matches the starting position.', '{"why":"Equal opposite movements cancel the displacement, not the distance.","sol":"Step 1: Distance = 100 + 100 = 200 m.\nStep 2: The car returns to its starting point.\nStep 3: Displacement = 0 m.","steps":["Step 1: Distance = 100 + 100 = 200 m.","Step 2: The car returns to its starting point.","Step 3: Displacement = 0 m."],"options":[],"conceptId":"physics_motion_distance_and_displacement","skillId":"physics_motion","subskillId":"physics_motion_q4","subject":"physics","chapter":"motion","topic":"Distance and Displacement"}', 3),
  (1337, 378, 'A person walks 8 m east and then 6 m west. What is the displacement?', 'text', 1, 'Subtract the smaller opposite movement and retain the direction of the larger movement.', '{"why":"Displacement depends on the net change in position and its direction.","sol":"Step 1: Net magnitude = 8 − 6 = 2 m.\nStep 2: The larger movement was eastward.","steps":["Step 1: Net magnitude = 8 − 6 = 2 m.","Step 2: The larger movement was eastward."],"options":[],"conceptId":"physics_motion_distance_and_displacement","skillId":"physics_motion","subskillId":"physics_motion_q5","subject":"physics","chapter":"motion","topic":"Distance and Displacement"}', 4),
  (1338, 378, 'A person walks 10 m forward and 10 m back to the starting point. Find the distance and displacement.', 'text', 1, 'Add path lengths for distance; compare the start and finish for displacement.', '{"why":"Returning to the start gives zero displacement but does not erase the distance travelled.","sol":"Step 1: Distance = 10 + 10 = 20 m.\nStep 2: The final position equals the initial position.\nStep 3: Displacement = 0 m.","steps":["Step 1: Distance = 10 + 10 = 20 m.","Step 2: The final position equals the initial position.","Step 3: Displacement = 0 m."],"options":[],"conceptId":"physics_motion_distance_and_displacement","skillId":"physics_motion","subskillId":"physics_motion_q6","subject":"physics","chapter":"motion","topic":"Distance and Displacement"}', 5),
  (1339, 378, 'A car moves 30 m east and then 40 m east. Find its distance and displacement.', 'text', 1, 'Both segments are in the same direction.', '{"why":"When motion is in one direction along a straight line, distance equals the magnitude of displacement.","sol":"Step 1: Distance = 30 + 40 = 70 m.\nStep 2: Net movement = 70 m east.","steps":["Step 1: Distance = 30 + 40 = 70 m.","Step 2: Net movement = 70 m east."],"options":[],"conceptId":"physics_motion_distance_and_displacement","skillId":"physics_motion","subskillId":"physics_motion_q7","subject":"physics","chapter":"motion","topic":"Distance and Displacement"}', 6),
  (1340, 378, 'A learner walks 15 m north and then 5 m south. Find distance and displacement.', 'text', 1, 'Add for distance; subtract opposing movements for displacement.', '{"why":"The learner finishes 10 m north of the starting point.","sol":"Step 1: Distance = 15 + 5 = 20 m.\nStep 2: Net movement = 15 − 5 = 10 m.\nStep 3: The larger movement was north.","steps":["Step 1: Distance = 15 + 5 = 20 m.","Step 2: Net movement = 15 − 5 = 10 m.","Step 3: The larger movement was north."],"options":[],"conceptId":"physics_motion_distance_and_displacement","skillId":"physics_motion","subskillId":"physics_motion_q8","subject":"physics","chapter":"motion","topic":"Distance and Displacement"}', 7),
  (1341, 378, 'A runner completes a 200 m lap and finishes at the exact starting point. What is the displacement?', 'text', 1, 'Compare final and initial positions.', '{"why":"Displacement is zero because the final position is the same as the initial position.","sol":"Step 1: Identify key concept: Define the required principles for Distance and Displacement.\nStep 2: Apply governing rule: Displacement is zero because the final position is the same as the initial position.\nStep 3: State the final conclusion: 0 m","steps":["Step 1: Identify key concept: Define the required principles for Distance and Displacement.","Step 2: Apply governing rule: Displacement is zero because the final position is the same as the initial position.","Step 3: State the final conclusion: 0 m"],"options":[],"conceptId":"physics_motion_distance_and_displacement","skillId":"physics_motion","subskillId":"physics_motion_q9","subject":"physics","chapter":"motion","topic":"Distance and Displacement"}', 8),
  (1342, 378, 'A person walks 8 m east and then 6 m west. Find the displacement.', 'text', 1, 'Take east as positive.', '{"why":"The net movement is 2 m east of the starting point.","sol":"Step 1: Eastward movement = +8 m.\nStep 2: Westward movement = −6 m.\nStep 3: Displacement = +8 − 6 = +2 m.","steps":["Step 1: Eastward movement = +8 m.","Step 2: Westward movement = −6 m.","Step 3: Displacement = +8 − 6 = +2 m."],"options":[],"conceptId":"physics_motion_distance_and_displacement","skillId":"physics_motion","subskillId":"physics_motion_q10","subject":"physics","chapter":"motion","topic":"Distance and Displacement"}', 9),
  (1343, 379, 'A cyclist travels 150 m in 30 s. Calculate the average speed.', 'text', 1, 'Average speed = distance ÷ time.', '{"why":"Average speed is the total distance divided by the total elapsed time.","sol":"Step 1: Substitute d = 150 m and t = 30 s.\nStep 2: v = 150 ÷ 30 = 5 m/s.","steps":["Step 1: Substitute d = 150 m and t = 30 s.","Step 2: v = 150 ÷ 30 = 5 m/s."],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q1","subject":"physics","chapter":"motion","topic":"Speed"}', 0),
  (1344, 379, 'A vehicle travels at 8 m/s for 12 s. How far does it travel?', 'text', 1, 'Rearrange the speed formula.', '{"why":"Multiplying speed by time gives distance for the stated average speed.","sol":"Step 1: d = 8 × 12.\nStep 2: d = 96 m.","steps":["Step 1: d = 8 × 12.","Step 2: d = 96 m."],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q2","subject":"physics","chapter":"motion","topic":"Speed"}', 1),
  (1345, 379, 'A student covers 200 m in 50 s. A learner calculates 50 ÷ 200 = 0.25 m/s. Identify the error and calculate the correct speed.', 'text', 1, 'Divide distance by time, not time by distance.', '{"why":"The speed formula requires distance divided by time.","sol":"Step 1: Use v = d / t.\nStep 2: v = 200 ÷ 50 = 4 m/s.","steps":["Step 1: Use v = d / t.","Step 2: v = 200 ÷ 50 = 4 m/s."],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q3","subject":"physics","chapter":"motion","topic":"Speed"}', 2),
  (1346, 379, 'A runner travels 100 m in 20 s, rests for 10 s, and then travels another 100 m in 20 s. Calculate the average speed for the whole journey.', 'text', 1, 'Include the rest period in elapsed time.', '{"why":"Average speed includes the full elapsed time, including the stop.","sol":"Step 1: Total distance = 100 + 100 = 200 m.\nStep 2: Total time = 20 + 10 + 20 = 50 s.\nStep 3: Average speed = 200 ÷ 50 = 4 m/s.","steps":["Step 1: Total distance = 100 + 100 = 200 m.","Step 2: Total time = 20 + 10 + 20 = 50 s.","Step 3: Average speed = 200 ÷ 50 = 4 m/s."],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q4","subject":"physics","chapter":"motion","topic":"Speed"}', 3),
  (1347, 379, 'Convert 72 km/h to m/s.', 'text', 1, 'Multiply km/h by 5/18.', '{"why":"The conversion factor from km/h to m/s is 5/18.","sol":"Step 1: 72 × 5/18 = 4 × 5.\nStep 2: The result is 20 m/s.","steps":["Step 1: 72 × 5/18 = 4 × 5.","Step 2: The result is 20 m/s."],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q5","subject":"physics","chapter":"motion","topic":"Speed"}', 4),
  (1348, 379, 'A cyclist travels 150 m in 30 s. Calculate the average speed.', 'text', 1, 'Average speed = distance ÷ time.', '{"why":"Dividing distance by time gives the distance covered per second.","sol":"Step 1: Distance = 150 m.\nStep 2: Time = 30 s.\nStep 3: Speed = 150 ÷ 30 = 5 m/s.","steps":["Step 1: Distance = 150 m.","Step 2: Time = 30 s.","Step 3: Speed = 150 ÷ 30 = 5 m/s."],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q6","subject":"physics","chapter":"motion","topic":"Speed"}', 5),
  (1349, 379, 'A vehicle travels at 12 m/s for 10 s. How far does it travel?', 'text', 1, 'Rearrange speed = distance ÷ time.', '{"why":"Distance equals speed multiplied by elapsed time for the stated constant speed.","sol":"Step 1: Speed = 12 m/s.\nStep 2: Time = 10 s.\nStep 3: Distance = 12 × 10 = 120 m.","steps":["Step 1: Speed = 12 m/s.","Step 2: Time = 10 s.","Step 3: Distance = 12 × 10 = 120 m."],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q7","subject":"physics","chapter":"motion","topic":"Speed"}', 6),
  (1350, 379, 'Convert 36 km/h to m/s.', 'text', 1, 'Divide km/h by 3.6.', '{"why":"One kilometre per hour is equivalent to 1/3.6 metres per second.","sol":"Step 1: 36 ÷ 3.6 = 10.\nStep 2: Write the unit m/s.","steps":["Step 1: 36 ÷ 3.6 = 10.","Step 2: Write the unit m/s."],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q8","subject":"physics","chapter":"motion","topic":"Speed"}', 7),
  (1351, 379, 'A student walks 600 m in 5 minutes. Calculate the average speed in m/s.', 'text', 1, 'Convert minutes to seconds first.', '{"why":"Using seconds gives speed in metres per second.","sol":"Step 1: Time = 5 × 60 = 300 s.\nStep 2: Speed = 600 ÷ 300 = 2 m/s.","steps":["Step 1: Time = 5 × 60 = 300 s.","Step 2: Speed = 600 ÷ 300 = 2 m/s."],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q9","subject":"physics","chapter":"motion","topic":"Speed"}', 8),
  (1352, 379, 'A journey covers 100 m in 20 s, then 100 m in 40 s. Find the average speed for the whole journey.', 'text', 1, 'Use total distance divided by total time.', '{"why":"Average speed for a whole journey must use the total distance and total time.","sol":"Step 1: Total distance = 100 + 100 = 200 m.\nStep 2: Total time = 20 + 40 = 60 s.\nStep 3: Average speed = 200 ÷ 60 ≈ 3.33 m/s.","steps":["Step 1: Total distance = 100 + 100 = 200 m.","Step 2: Total time = 20 + 40 = 60 s.","Step 3: Average speed = 200 ÷ 60 ≈ 3.33 m/s."],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q10","subject":"physics","chapter":"motion","topic":"Speed"}', 9),
  (1353, 379, 'A runner covers 200 m in 25 s. Find speed.', 'text', 1, 'Use speed = distance ÷ time', '{"why":"Speed is the rate of covering distance per unit time.","sol":"Step 1: Identify values → s = 200 m, t = 25 s\nStep 2: Substitute → v = 200 ÷ 25\nStep 3: Calculate → v = 8 m/s","steps":["Step 1: Identify values → s = 200 m, t = 25 s","Step 2: Substitute → v = 200 ÷ 25","Step 3: Calculate → v = 8 m/s"],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q11","subject":"physics","chapter":"motion","topic":"Speed"}', 10),
  (1354, 379, 'A car travels 360 km in 6 hours. Find speed.', 'text', 1, 'distance ÷ time', '{"why":"Speed in km/h is calculated using total distance divided by total time.","sol":"Step 1: s = 360 km, t = 6 h\nStep 2: v = 360 ÷ 6\nStep 3: v = 60 km/h","steps":["Step 1: s = 360 km, t = 6 h","Step 2: v = 360 ÷ 6","Step 3: v = 60 km/h"],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q12","subject":"physics","chapter":"motion","topic":"Speed"}', 11),
  (1355, 379, 'A body moves 500 m in 50 s. Find speed.', 'text', 1, 'v = s / t', '{"why":"Speed measures how fast distance is covered.","sol":"Step 1: s = 500 m, t = 50 s\nStep 2: v = 500 ÷ 50\nStep 3: v = 10 m/s","steps":["Step 1: s = 500 m, t = 50 s","Step 2: v = 500 ÷ 50","Step 3: v = 10 m/s"],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q13","subject":"physics","chapter":"motion","topic":"Speed"}', 12),
  (1356, 379, 'A cyclist moves 120 km in 4 hours. Find speed.', 'text', 1, 'distance ÷ time', '{"why":"Speed is distance divided by time.","sol":"Step 1: s = 120 km, t = 4 h\nStep 2: v = 120 ÷ 4\nStep 3: v = 30 km/h","steps":["Step 1: s = 120 km, t = 4 h","Step 2: v = 120 ÷ 4","Step 3: v = 30 km/h"],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q14","subject":"physics","chapter":"motion","topic":"Speed"}', 13),
  (1357, 379, 'A car travels 75 m in 5 s. Find speed.', 'text', 1, 'v = s / t', '{"why":"Speed is proportional to distance and inversely proportional to time.","sol":"Step 1: s = 75 m, t = 5 s\nStep 2: v = 75 ÷ 5\nStep 3: v = 15 m/s","steps":["Step 1: s = 75 m, t = 5 s","Step 2: v = 75 ÷ 5","Step 3: v = 15 m/s"],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q15","subject":"physics","chapter":"motion","topic":"Speed"}', 14),
  (1358, 379, 'A train covers 900 m in 30 s. Find speed.', 'text', 1, 'distance ÷ time', '{"why":"Speed measures how quickly distance is covered.","sol":"Step 1: s = 900 m, t = 30 s\nStep 2: v = 900 ÷ 30\nStep 3: v = 30 m/s","steps":["Step 1: s = 900 m, t = 30 s","Step 2: v = 900 ÷ 30","Step 3: v = 30 m/s"],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q16","subject":"physics","chapter":"motion","topic":"Speed"}', 15),
  (1359, 379, 'A car covers 1.2 km in 60 s. Find speed in m/s.', 'text', 1, 'convert km to m first', '{"why":"Always convert distance into SI units before calculating speed.","sol":"Step 1: Convert 1.2 km → 1200 m\nStep 2: t = 60 s\nStep 3: v = 1200 ÷ 60\nStep 4: v = 20 m/s","steps":["Step 1: Convert 1.2 km → 1200 m","Step 2: t = 60 s","Step 3: v = 1200 ÷ 60","Step 4: v = 20 m/s"],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q17","subject":"physics","chapter":"motion","topic":"Speed"}', 16),
  (1360, 380, 'A cyclist has a displacement of 90 m east over 15 s. Calculate average velocity.', 'text', 1, 'Average velocity = displacement ÷ elapsed time.', '{"why":"Average velocity uses displacement and elapsed time.","sol":"Step 1: v = 90 ÷ 15 = 6 m/s.\nStep 2: Include the displacement direction.","steps":["Step 1: v = 90 ÷ 15 = 6 m/s.","Step 2: Include the displacement direction."],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q1","subject":"physics","chapter":"motion","topic":"Velocity"}', 0),
  (1361, 380, 'A person walks 25 m east and then 10 m west in 7 s. Take east as positive. Calculate average velocity.', 'text', 1, 'Calculate net displacement first.', '{"why":"Opposite movements subtract when calculating net displacement.","sol":"Step 1: Displacement = +25 − 10 = +15 m.\nStep 2: Average velocity = 15 ÷ 7 ≈ 2.14 m/s.\nStep 3: The positive sign means east.","steps":["Step 1: Displacement = +25 − 10 = +15 m.","Step 2: Average velocity = 15 ÷ 7 ≈ 2.14 m/s.","Step 3: The positive sign means east."],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q2","subject":"physics","chapter":"motion","topic":"Velocity"}', 1),
  (1362, 380, 'A runner returns to the starting point after 50 s. What is the runner''s average velocity for the complete journey?', 'text', 1, 'Compare initial and final positions.', '{"why":"Average velocity is zero when total displacement is zero, even if distance travelled is not zero.","sol":"Step 1: Displacement = 0 m.\nStep 2: Average velocity = 0 ÷ 50 = 0 m/s.","steps":["Step 1: Displacement = 0 m.","Step 2: Average velocity = 0 ÷ 50 = 0 m/s."],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q3","subject":"physics","chapter":"motion","topic":"Velocity"}', 2),
  (1363, 380, 'A car travels at 12 m/s east while another travels at 12 m/s west. Do they have the same velocity?', 'text', 1, 'Velocity includes direction.', '{"why":"Equal speed alone does not establish equal velocity.","sol":"Step 1: Identify key concept: Define the required principles for Velocity.\nStep 2: Apply governing rule: Equal speed alone does not establish equal velocity.\nStep 3: State the final conclusion: No. Their speeds are equal, but their velocities have opposite directions.","steps":["Step 1: Identify key concept: Define the required principles for Velocity.","Step 2: Apply governing rule: Equal speed alone does not establish equal velocity.","Step 3: State the final conclusion: No. Their speeds are equal, but their velocities have opposite directions."],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q4","subject":"physics","chapter":"motion","topic":"Velocity"}', 3),
  (1364, 380, 'A learner calculates average velocity by dividing total distance by elapsed time. What is the error?', 'text', 1, 'Identify which quantity belongs in the velocity formula.', '{"why":"Using total distance calculates average speed instead.","sol":"Step 1: Identify key concept: Define the required principles for Velocity.\nStep 2: Apply governing rule: Using total distance calculates average speed instead.\nStep 3: State the final conclusion: Average velocity must be calculated using displacement divided by elapsed time, not total distance.","steps":["Step 1: Identify key concept: Define the required principles for Velocity.","Step 2: Apply governing rule: Using total distance calculates average speed instead.","Step 3: State the final conclusion: Average velocity must be calculated using displacement divided by elapsed time, not total distance."],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q5","subject":"physics","chapter":"motion","topic":"Velocity"}', 4),
  (1365, 380, 'A student moves 80 m north in 20 s. Calculate average velocity.', 'text', 1, 'Use displacement ÷ time and include direction.', '{"why":"Velocity is displacement per unit time and includes direction.","sol":"Step 1: Displacement = 80 m north.\nStep 2: Time = 20 s.\nStep 3: Average velocity = 80 ÷ 20 = 4 m/s north.","steps":["Step 1: Displacement = 80 m north.","Step 2: Time = 20 s.","Step 3: Average velocity = 80 ÷ 20 = 4 m/s north."],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q6","subject":"physics","chapter":"motion","topic":"Velocity"}', 5),
  (1366, 380, 'Take east as positive. An object moves 30 m west in 6 s. Find its average velocity.', 'text', 1, 'Westward displacement is negative under this convention.', '{"why":"The negative sign indicates movement opposite to the chosen positive direction.","sol":"Step 1: Displacement = −30 m.\nStep 2: Time = 6 s.\nStep 3: Velocity = −30 ÷ 6 = −5 m/s.","steps":["Step 1: Displacement = −30 m.","Step 2: Time = 6 s.","Step 3: Velocity = −30 ÷ 6 = −5 m/s."],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q7","subject":"physics","chapter":"motion","topic":"Velocity"}', 6),
  (1367, 380, 'A runner completes a lap and returns to the starting point in 50 s. Find the average velocity.', 'text', 1, 'What is the total displacement?', '{"why":"Average velocity depends on net displacement, which is zero for a completed lap.","sol":"Step 1: Final position equals initial position.\nStep 2: Displacement = 0 m.\nStep 3: Average velocity = 0 ÷ 50 = 0 m/s.","steps":["Step 1: Final position equals initial position.","Step 2: Displacement = 0 m.","Step 3: Average velocity = 0 ÷ 50 = 0 m/s."],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q8","subject":"physics","chapter":"motion","topic":"Velocity"}', 7),
  (1368, 380, 'What is the main difference between speed and velocity?', 'text', 1, 'Consider whether direction is included.', '{"why":"Velocity contains directional information that speed does not.","sol":"Step 1: Identify key concept: Define the required principles for Velocity.\nStep 2: Apply governing rule: Velocity contains directional information that speed does not.\nStep 3: State the final conclusion: Speed is a scalar based on distance; velocity is a vector based on displacement and includes direction.","steps":["Step 1: Identify key concept: Define the required principles for Velocity.","Step 2: Apply governing rule: Velocity contains directional information that speed does not.","Step 3: State the final conclusion: Speed is a scalar based on distance; velocity is a vector based on displacement and includes direction."],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q9","subject":"physics","chapter":"motion","topic":"Velocity"}', 8),
  (1369, 380, 'An object has an average velocity of 3 m/s east for 4 s. Find its displacement.', 'text', 1, 'Displacement = average velocity × time.', '{"why":"Multiplying average velocity by elapsed time gives the net displacement.","sol":"Step 1: Velocity = 3 m/s east.\nStep 2: Time = 4 s.\nStep 3: Displacement = 3 × 4 = 12 m east.","steps":["Step 1: Velocity = 3 m/s east.","Step 2: Time = 4 s.","Step 3: Displacement = 3 × 4 = 12 m east."],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q10","subject":"physics","chapter":"motion","topic":"Velocity"}', 9),
  (1370, 380, 'A car travels 150 m in 5 s. Find its velocity.', 'text', 1, 'Use v = distance ÷ time', '{"why":"Velocity is the rate of change of displacement with time.","sol":"Step 1: Identify values → s = 150 m, t = 5 s\nStep 2: Substitute into formula → v = 150 ÷ 5\nStep 3: Calculate → v = 30 m/s","steps":["Step 1: Identify values → s = 150 m, t = 5 s","Step 2: Substitute into formula → v = 150 ÷ 5","Step 3: Calculate → v = 30 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q11","subject":"physics","chapter":"motion","topic":"Velocity"}', 10),
  (1371, 380, 'A runner covers 100 m in 20 s. Find velocity.', 'text', 1, 'Use v = s / t', '{"why":"Velocity tells how fast and in what direction an object moves.","sol":"Step 1: s = 100 m, t = 20 s\nStep 2: v = 100 ÷ 20\nStep 3: v = 5 m/s","steps":["Step 1: s = 100 m, t = 20 s","Step 2: v = 100 ÷ 20","Step 3: v = 5 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q12","subject":"physics","chapter":"motion","topic":"Velocity"}', 11),
  (1372, 380, 'A body moves with velocity 12 m/s for 8 s. Find distance covered.', 'text', 1, 'Use s = v × t', '{"why":"Distance is product of velocity and time when motion is uniform.","sol":"Step 1: v = 12 m/s, t = 8 s\nStep 2: s = 12 × 8\nStep 3: s = 96 m","steps":["Step 1: v = 12 m/s, t = 8 s","Step 2: s = 12 × 8","Step 3: s = 96 m"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q13","subject":"physics","chapter":"motion","topic":"Velocity"}', 12),
  (1373, 380, 'A train moves 300 m in 10 s. Find velocity.', 'text', 1, 'v = s / t', '{"why":"Velocity depends on displacement per time.","sol":"Step 1: s = 300 m, t = 10 s\nStep 2: v = 300 ÷ 10\nStep 3: v = 30 m/s","steps":["Step 1: s = 300 m, t = 10 s","Step 2: v = 300 ÷ 10","Step 3: v = 30 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q14","subject":"physics","chapter":"motion","topic":"Velocity"}', 13),
  (1374, 380, 'A car covers 240 m in 12 s. Find velocity.', 'text', 1, 'v = s / t', '{"why":"Velocity shows rate of motion.","sol":"Step 1: s = 240 m, t = 12 s\nStep 2: v = 240 ÷ 12\nStep 3: v = 20 m/s","steps":["Step 1: s = 240 m, t = 12 s","Step 2: v = 240 ÷ 12","Step 3: v = 20 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q15","subject":"physics","chapter":"motion","topic":"Velocity"}', 14),
  (1375, 380, 'A cyclist moves 60 m in 6 s. Find velocity.', 'text', 1, 'v = s / t', '{"why":"Velocity is constant motion over time.","sol":"Step 1: s = 60 m, t = 6 s\nStep 2: v = 60 ÷ 6\nStep 3: v = 10 m/s","steps":["Step 1: s = 60 m, t = 6 s","Step 2: v = 60 ÷ 6","Step 3: v = 10 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q16","subject":"physics","chapter":"motion","topic":"Velocity"}', 15),
  (1376, 380, 'A body travels 500 m in 25 s. Find velocity.', 'text', 1, 'v = s / t', '{"why":"Velocity is displacement per time.","sol":"Step 1: s = 500 m, t = 25 s\nStep 2: v = 500 ÷ 25\nStep 3: v = 20 m/s","steps":["Step 1: s = 500 m, t = 25 s","Step 2: v = 500 ÷ 25","Step 3: v = 20 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q17","subject":"physics","chapter":"motion","topic":"Velocity"}', 16),
  (1377, 380, 'A car moves at 15 m/s for 10 s. Find distance.', 'text', 1, 's = vt', '{"why":"Distance is product of velocity and time.","sol":"Step 1: v = 15 m/s, t = 10 s\nStep 2: s = 15 × 10\nStep 3: s = 150 m","steps":["Step 1: v = 15 m/s, t = 10 s","Step 2: s = 15 × 10","Step 3: s = 150 m"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q18","subject":"physics","chapter":"motion","topic":"Velocity"}', 17),
  (1378, 380, 'A runner moves 200 m in 40 s. Find velocity.', 'text', 1, 'v = s / t', '{"why":"Velocity measures how fast distance is covered.","sol":"Step 1: s = 200 m, t = 40 s\nStep 2: v = 200 ÷ 40\nStep 3: v = 5 m/s","steps":["Step 1: s = 200 m, t = 40 s","Step 2: v = 200 ÷ 40","Step 3: v = 5 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q19","subject":"physics","chapter":"motion","topic":"Velocity"}', 18),
  (1379, 380, 'A vehicle covers 360 m in 18 s. Find velocity.', 'text', 1, 'v = s / t', '{"why":"Velocity is displacement per time.","sol":"Step 1: s = 360 m, t = 18 s\nStep 2: v = 360 ÷ 18\nStep 3: v = 20 m/s","steps":["Step 1: s = 360 m, t = 18 s","Step 2: v = 360 ÷ 18","Step 3: v = 20 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q20","subject":"physics","chapter":"motion","topic":"Velocity"}', 19),
  (1380, 381, 'A car''s velocity changes from 4 m/s to 16 m/s in 3 s. Calculate its average acceleration.', 'text', 1, 'Subtract initial velocity from final velocity, then divide by time.', '{"why":"The velocity increases by 12 m/s over 3 seconds.","sol":"Step 1: u = 4 m/s and v = 16 m/s.\nStep 2: Change in velocity = 16 − 4 = 12 m/s.\nStep 3: Acceleration = 12 ÷ 3 = 4 m/s².","steps":["Step 1: u = 4 m/s and v = 16 m/s.","Step 2: Change in velocity = 16 − 4 = 12 m/s.","Step 3: Acceleration = 12 ÷ 3 = 4 m/s²."],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q1","subject":"physics","chapter":"motion","topic":"Acceleration"}', 0),
  (1381, 381, 'A bicycle slows from 12 m/s to 6 m/s in 2 s. Take its original direction as positive. Calculate acceleration.', 'text', 1, 'Final velocity is less than initial velocity.', '{"why":"The negative acceleration points opposite to the chosen positive direction.","sol":"Step 1: Change in velocity = 6 − 12 = −6 m/s.\nStep 2: Acceleration = −6 ÷ 2 = −3 m/s².","steps":["Step 1: Change in velocity = 6 − 12 = −6 m/s.","Step 2: Acceleration = −6 ÷ 2 = −3 m/s²."],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q2","subject":"physics","chapter":"motion","topic":"Acceleration"}', 1),
  (1382, 381, 'An object moves at a constant velocity of 7 m/s for 5 s. What is its acceleration?', 'text', 1, 'Constant velocity means no change in velocity.', '{"why":"Acceleration is zero when velocity does not change.","sol":"Step 1: Change in velocity = 7 − 7 = 0 m/s.\nStep 2: Acceleration = 0 ÷ 5 = 0 m/s².","steps":["Step 1: Change in velocity = 7 − 7 = 0 m/s.","Step 2: Acceleration = 0 ÷ 5 = 0 m/s²."],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q3","subject":"physics","chapter":"motion","topic":"Acceleration"}', 2),
  (1383, 381, 'A vehicle starts from rest and reaches 10 m/s in 5 s. Find its average acceleration.', 'text', 1, 'Starting from rest means initial velocity is zero.', '{"why":"The velocity increases by 10 m/s over 5 seconds.","sol":"Step 1: u = 0 m/s and v = 10 m/s.\nStep 2: Change in velocity = 10 − 0 = 10 m/s.\nStep 3: Acceleration = 10 ÷ 5 = 2 m/s².","steps":["Step 1: u = 0 m/s and v = 10 m/s.","Step 2: Change in velocity = 10 − 0 = 10 m/s.","Step 3: Acceleration = 10 ÷ 5 = 2 m/s²."],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q4","subject":"physics","chapter":"motion","topic":"Acceleration"}', 3),
  (1384, 381, 'Can an object have negative acceleration while moving in the negative direction and speeding up?', 'text', 1, 'Compare the direction of velocity with the direction of acceleration.', '{"why":"Acceleration''s sign indicates its direction, not by itself whether speed increases or decreases.","sol":"Step 1: Identify key concept: Define the required principles for Acceleration.\nStep 2: Apply governing rule: Acceleration''s sign indicates its direction, not by itself whether speed increases or decreases.\nStep 3: State the final conclusion: Yes. If velocity and acceleration are both negative, the object speeds up in the negative direction.","steps":["Step 1: Identify key concept: Define the required principles for Acceleration.","Step 2: Apply governing rule: Acceleration''s sign indicates its direction, not by itself whether speed increases or decreases.","Step 3: State the final conclusion: Yes. If velocity and acceleration are both negative, the object speeds up in the negative direction."],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q5","subject":"physics","chapter":"motion","topic":"Acceleration"}', 4),
  (1385, 381, 'A car speeds up from 0 m/s to 20 m/s in 5 s. Find acceleration.', 'text', 1, 'Use a = (v - u) / t', '{"why":"Acceleration measures change in velocity per unit time.","sol":"Step 1: Identify values → u = 0 m/s, v = 20 m/s, t = 5 s\nStep 2: Substitute into formula → a = (20 - 0) / 5\nStep 3: Calculate → a = 4 m/s²","steps":["Step 1: Identify values → u = 0 m/s, v = 20 m/s, t = 5 s","Step 2: Substitute into formula → a = (20 - 0) / 5","Step 3: Calculate → a = 4 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q6","subject":"physics","chapter":"motion","topic":"Acceleration"}', 5),
  (1386, 381, 'A car slows from 30 m/s to 10 m/s in 5 s. Find acceleration.', 'text', 1, 'Use a = (v - u) / t', '{"why":"Negative acceleration means the object is slowing down.","sol":"Step 1: u = 30 m/s, v = 10 m/s, t = 5 s\nStep 2: a = (10 - 30) / 5\nStep 3: a = -20 / 5\nStep 4: a = -4 m/s²","steps":["Step 1: u = 30 m/s, v = 10 m/s, t = 5 s","Step 2: a = (10 - 30) / 5","Step 3: a = -20 / 5","Step 4: a = -4 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q7","subject":"physics","chapter":"motion","topic":"Acceleration"}', 6),
  (1387, 381, 'A bike increases speed from 5 m/s to 25 m/s in 10 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"The bike is speeding up uniformly.","sol":"Step 1: u = 5, v = 25, t = 10\nStep 2: a = (25 - 5) / 10\nStep 3: a = 20 / 10\nStep 4: a = 2 m/s²","steps":["Step 1: u = 5, v = 25, t = 10","Step 2: a = (25 - 5) / 10","Step 3: a = 20 / 10","Step 4: a = 2 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q8","subject":"physics","chapter":"motion","topic":"Acceleration"}', 7),
  (1388, 381, 'A train slows from 40 m/s to 20 m/s in 8 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"The train is decelerating.","sol":"Step 1: u = 40, v = 20, t = 8\nStep 2: a = (20 - 40) / 8\nStep 3: a = -20 / 8\nStep 4: a = -2.5 m/s²","steps":["Step 1: u = 40, v = 20, t = 8","Step 2: a = (20 - 40) / 8","Step 3: a = -20 / 8","Step 4: a = -2.5 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q9","subject":"physics","chapter":"motion","topic":"Acceleration"}', 8),
  (1389, 381, 'A car accelerates from 10 m/s to 30 m/s in 4 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Speed increases steadily over time.","sol":"Step 1: u = 10, v = 30, t = 4\nStep 2: a = (30 - 10) / 4\nStep 3: a = 20 / 4\nStep 4: a = 5 m/s²","steps":["Step 1: u = 10, v = 30, t = 4","Step 2: a = (30 - 10) / 4","Step 3: a = 20 / 4","Step 4: a = 5 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q10","subject":"physics","chapter":"motion","topic":"Acceleration"}', 9),
  (1390, 381, 'A body slows from 50 m/s to 10 m/s in 8 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Large negative acceleration shows rapid slowing.","sol":"Step 1: u = 50, v = 10, t = 8\nStep 2: a = (10 - 50) / 8\nStep 3: a = -40 / 8\nStep 4: a = -5 m/s²","steps":["Step 1: u = 50, v = 10, t = 8","Step 2: a = (10 - 50) / 8","Step 3: a = -40 / 8","Step 4: a = -5 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q11","subject":"physics","chapter":"motion","topic":"Acceleration"}', 10),
  (1391, 381, 'A motorcycle increases speed from 12 m/s to 24 m/s in 6 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Acceleration is constant during motion.","sol":"Step 1: u = 12, v = 24, t = 6\nStep 2: a = (24 - 12) / 6\nStep 3: a = 12 / 6\nStep 4: a = 2 m/s²","steps":["Step 1: u = 12, v = 24, t = 6","Step 2: a = (24 - 12) / 6","Step 3: a = 12 / 6","Step 4: a = 2 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q12","subject":"physics","chapter":"motion","topic":"Acceleration"}', 11),
  (1392, 381, 'A bus slows from 60 m/s to 30 m/s in 10 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Bus is decelerating uniformly.","sol":"Step 1: u = 60, v = 30, t = 10\nStep 2: a = (30 - 60) / 10\nStep 3: a = -30 / 10\nStep 4: a = -3 m/s²","steps":["Step 1: u = 60, v = 30, t = 10","Step 2: a = (30 - 60) / 10","Step 3: a = -30 / 10","Step 4: a = -3 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q13","subject":"physics","chapter":"motion","topic":"Acceleration"}', 12),
  (1393, 381, 'A car increases speed from 8 m/s to 32 m/s in 12 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Speed increases steadily.","sol":"Step 1: u = 8, v = 32, t = 12\nStep 2: a = (32 - 8) / 12\nStep 3: a = 24 / 12\nStep 4: a = 2 m/s²","steps":["Step 1: u = 8, v = 32, t = 12","Step 2: a = (32 - 8) / 12","Step 3: a = 24 / 12","Step 4: a = 2 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q14","subject":"physics","chapter":"motion","topic":"Acceleration"}', 13),
  (1394, 381, 'A train slows from 70 m/s to 40 m/s in 15 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Train slows down steadily.","sol":"Step 1: u = 70, v = 40, t = 15\nStep 2: a = (40 - 70) / 15\nStep 3: a = -30 / 15\nStep 4: a = -2 m/s²","steps":["Step 1: u = 70, v = 40, t = 15","Step 2: a = (40 - 70) / 15","Step 3: a = -30 / 15","Step 4: a = -2 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q15","subject":"physics","chapter":"motion","topic":"Acceleration"}', 14),
  (1395, 381, 'A car goes from 15 m/s to 45 m/s in 6 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Car gains speed quickly.","sol":"Step 1: u = 15, v = 45, t = 6\nStep 2: a = (45 - 15) / 6\nStep 3: a = 30 / 6\nStep 4: a = 5 m/s²","steps":["Step 1: u = 15, v = 45, t = 6","Step 2: a = (45 - 15) / 6","Step 3: a = 30 / 6","Step 4: a = 5 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q16","subject":"physics","chapter":"motion","topic":"Acceleration"}', 15),
  (1396, 381, 'A vehicle slows from 25 m/s to 5 m/s in 5 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Vehicle is slowing down steadily.","sol":"Step 1: u = 25, v = 5, t = 5\nStep 2: a = (5 - 25) / 5\nStep 3: a = -20 / 5\nStep 4: a = -4 m/s²","steps":["Step 1: u = 25, v = 5, t = 5","Step 2: a = (5 - 25) / 5","Step 3: a = -20 / 5","Step 4: a = -4 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q17","subject":"physics","chapter":"motion","topic":"Acceleration"}', 16),
  (1397, 382, 'A body starts from rest and accelerates at 2 m/s² for 6 s. Find final velocity.', 'text', 1, 'Use v = u + at', '{"why":"Acceleration increases velocity over time from rest.","sol":"Step 1: Identify values → u = 0 m/s, a = 2 m/s², t = 6 s\nStep 2: Substitute → v = 0 + (2 × 6)\nStep 3: Multiply → v = 12 m/s","steps":["Step 1: Identify values → u = 0 m/s, a = 2 m/s², t = 6 s","Step 2: Substitute → v = 0 + (2 × 6)","Step 3: Multiply → v = 12 m/s"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q1","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 0),
  (1398, 382, 'A car moves with u = 5 m/s, a = 3 m/s², t = 4 s. Find final velocity.', 'text', 1, 'Use v = u + at', '{"why":"Acceleration adds to initial velocity over time.","sol":"Step 1: Identify values → u = 5, a = 3, t = 4\nStep 2: Multiply → a × t = 12\nStep 3: Add → v = 5 + 12 = 17 m/s","steps":["Step 1: Identify values → u = 5, a = 3, t = 4","Step 2: Multiply → a × t = 12","Step 3: Add → v = 5 + 12 = 17 m/s"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q2","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 1),
  (1399, 382, 'A body has u = 20 m/s, a = -2 m/s², t = 5 s. Find final velocity.', 'text', 1, 'Negative acceleration means deceleration', '{"why":"Negative acceleration reduces velocity over time.","sol":"Step 1: u = 20, a = -2, t = 5\nStep 2: Multiply → -2 × 5 = -10\nStep 3: v = 20 - 10 = 10 m/s","steps":["Step 1: u = 20, a = -2, t = 5","Step 2: Multiply → -2 × 5 = -10","Step 3: v = 20 - 10 = 10 m/s"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q3","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 2),
  (1400, 382, 'A body has u = 0 m/s, a = 4 m/s², t = 3 s. Find displacement.', 'text', 1, 'Use s = ut + 1/2 at²', '{"why":"Displacement increases as object accelerates from rest.","sol":"Step 1: u = 0, a = 4, t = 3\nStep 2: ut = 0\nStep 3: t² = 9\nStep 4: s = 1/2 × 4 × 9\nStep 5: s = 2 × 9 = 18 m","steps":["Step 1: u = 0, a = 4, t = 3","Step 2: ut = 0","Step 3: t² = 9","Step 4: s = 1/2 × 4 × 9","Step 5: s = 2 × 9 = 18 m"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q4","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 3),
  (1401, 382, 'A body moves with u = 8 m/s, a = 2 m/s², t = 5 s. Find displacement.', 'text', 1, 'Use s = ut + 1/2 at²', '{"why":"Displacement is total distance covered under acceleration.","sol":"Step 1: ut = 8 × 5 = 40\nStep 2: t² = 25\nStep 3: 1/2 × 2 × 25 = 25\nStep 4: s = 40 + 25 = 65 m","steps":["Step 1: ut = 8 × 5 = 40","Step 2: t² = 25","Step 3: 1/2 × 2 × 25 = 25","Step 4: s = 40 + 25 = 65 m"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q5","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 4),
  (1402, 382, 'A body has u = 10 m/s, v = 30 m/s, a = 4 m/s². Find time.', 'text', 1, 'Use v = u + at', '{"why":"Time is found from change in velocity divided by acceleration.","sol":"Step 1: v = 30, u = 10, a = 4\nStep 2: v - u = 20\nStep 3: t = 20 / 4\nStep 4: t = 5 s","steps":["Step 1: v = 30, u = 10, a = 4","Step 2: v - u = 20","Step 3: t = 20 / 4","Step 4: t = 5 s"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q6","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 5),
  (1403, 382, 'A body has u = 4 m/s, v = 20 m/s, s = 24 m. Find acceleration.', 'text', 1, 'Use v² = u² + 2as', '{"why":"This equation links velocity change with displacement and acceleration.","sol":"Step 1: 20² = 400\nStep 2: 4² = 16\nStep 3: 400 = 16 + 2a(24)\nStep 4: 400 - 16 = 384\nStep 5: 384 = 48a\nStep 6: a = 8 m/s²","steps":["Step 1: 20² = 400","Step 2: 4² = 16","Step 3: 400 = 16 + 2a(24)","Step 4: 400 - 16 = 384","Step 5: 384 = 48a","Step 6: a = 8 m/s²"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q7","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 6),
  (1404, 382, 'A body has u = 15 m/s, v = 5 m/s, s = 20 m. Find acceleration.', 'text', 1, 'Use v² = u² + 2as', '{"why":"Negative acceleration means the object is slowing down.","sol":"Step 1: 5² = 25\nStep 2: 15² = 225\nStep 3: 25 = 225 + 2a(20)\nStep 4: 25 - 225 = 40a\nStep 5: -200 = 40a\nStep 6: a = -5 m/s²","steps":["Step 1: 5² = 25","Step 2: 15² = 225","Step 3: 25 = 225 + 2a(20)","Step 4: 25 - 225 = 40a","Step 5: -200 = 40a","Step 6: a = -5 m/s²"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q8","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 7),
  (1405, 382, 'A body starts from rest and travels 50 m in 5 s. Find acceleration.', 'text', 1, 'Use s = ut + 1/2 at²', '{"why":"Used when initial velocity is zero.","sol":"Step 1: u = 0, s = 50, t = 5\nStep 2: s = 1/2 a t²\nStep 3: 50 = 1/2 a × 25\nStep 4: 50 = 12.5a\nStep 5: a = 4 m/s²","steps":["Step 1: u = 0, s = 50, t = 5","Step 2: s = 1/2 a t²","Step 3: 50 = 1/2 a × 25","Step 4: 50 = 12.5a","Step 5: a = 4 m/s²"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q9","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 8),
  (1406, 382, 'A body has u = 6 m/s, a = 2 m/s², t = 8 s. Find final velocity.', 'text', 1, 'Use v = u + at', '{"why":"Final velocity depends on initial velocity plus acceleration effect.","sol":"Step 1: a × t = 16\nStep 2: v = 6 + 16\nStep 3: v = 22 m/s","steps":["Step 1: a × t = 16","Step 2: v = 6 + 16","Step 3: v = 22 m/s"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q10","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 9),
  (1407, 382, 'A car starts from rest and accelerates at 3 m/s² for 5 s. Find final velocity.', 'text', 1, 'Use v = u + at', '{"why":"Acceleration increases velocity over time, so final velocity depends on initial velocity plus change due to acceleration.","sol":"Step 1: Identify values → u = 0 m/s, a = 3 m/s², t = 5 s\nStep 2: Substitute into formula → v = 0 + (3 × 5)\nStep 3: Multiply → v = 15 m/s","steps":["Step 1: Identify values → u = 0 m/s, a = 3 m/s², t = 5 s","Step 2: Substitute into formula → v = 0 + (3 × 5)","Step 3: Multiply → v = 15 m/s"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q11","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 10),
  (1408, 382, 'A body moves with u = 10 m/s, a = 2 m/s², t = 4 s. Find displacement.', 'text', 1, 'Use s = ut + 1/2 at²', '{"why":"Displacement under acceleration includes both initial motion and extra distance due to speeding up.","sol":"Step 1: Identify values → u = 10 m/s, a = 2 m/s², t = 4 s\nStep 2: Calculate first term → ut = 10 × 4 = 40\nStep 3: Calculate second term → 1/2 × 2 × 4²\nStep 4: Square time → 4² = 16\nStep 5: Multiply → 1/2 × 2 × 16 = 16\nStep 6: Add both terms → 40 + 16 = 56 m","steps":["Step 1: Identify values → u = 10 m/s, a = 2 m/s², t = 4 s","Step 2: Calculate first term → ut = 10 × 4 = 40","Step 3: Calculate second term → 1/2 × 2 × 4²","Step 4: Square time → 4² = 16","Step 5: Multiply → 1/2 × 2 × 16 = 16","Step 6: Add both terms → 40 + 16 = 56 m"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q12","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 11),
  (1409, 382, 'When do we use v² = u² + 2as?', 'text', 1, 'no time given', '{"why":"This equation is used when you need to relate velocity, acceleration, and displacement without involving time.","sol":"Step 1: Identify key concept: Define the required principles for Equations of Motion.\nStep 2: Apply governing rule: This equation is used when you need to relate velocity, acceleration, and displacement without involving time.\nStep 3: State the final conclusion: When time is not given in the problem.","steps":["Step 1: Identify key concept: Define the required principles for Equations of Motion.","Step 2: Apply governing rule: This equation is used when you need to relate velocity, acceleration, and displacement without involving time.","Step 3: State the final conclusion: When time is not given in the problem."],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q13","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 12),
  (1410, 383, 'A runner has an initial velocity of 5 m/s and accelerates uniformly at 2 m/s² for 4 s. What is the final velocity?', 'text', 1, 'Use the initial velocity, acceleration and time.', '{"why":"Uniform acceleration changes velocity by at = 2 × 4 = 8 m/s.","sol":"Step 1: Write u = 5 m/s, a = 2 m/s² and t = 4 s.\nStep 2: Substitute into v = u + at.\nStep 3: v = 5 + (2 × 4) = 13 m/s.","steps":["Step 1: Write u = 5 m/s, a = 2 m/s² and t = 4 s.","Step 2: Substitute into v = u + at.","Step 3: v = 5 + (2 × 4) = 13 m/s."],"options":[],"conceptId":"physics_equations_of_linear_motion_solving_motion_problems","skillId":"physics_equations_of_linear_motion","subskillId":"physics_equations_of_linear_motion_q1","subject":"physics","chapter":"equations_of_linear_motion","topic":"Solving Motion Problems"}', 0),
  (1411, 383, 'A bicycle starts from rest and accelerates uniformly at 2 m/s² for 5 s. Calculate its displacement.', 'text', 1, 'Since it starts from rest, u = 0. Use an equation involving u, a and t.', '{"why":"The displacement from rest under constant acceleration is half the acceleration multiplied by time squared.","sol":"Step 1: u = 0 m/s, a = 2 m/s², t = 5 s.\nStep 2: s = (0 × 5) + ½ × 2 × 5².\nStep 3: s = 25 m.","steps":["Step 1: u = 0 m/s, a = 2 m/s², t = 5 s.","Step 2: s = (0 × 5) + ½ × 2 × 5².","Step 3: s = 25 m."],"options":[],"conceptId":"physics_equations_of_linear_motion_solving_motion_problems","skillId":"physics_equations_of_linear_motion","subskillId":"physics_equations_of_linear_motion_q2","subject":"physics","chapter":"equations_of_linear_motion","topic":"Solving Motion Problems"}', 1),
  (1412, 383, 'A vehicle travels at 54 km/h for 20 s at constant speed. How far does it travel?', 'text', 1, 'Convert km/h to m/s by dividing by 3.6.', '{"why":"At constant speed, distance equals speed multiplied by elapsed time.","sol":"Step 1: Convert 54 km/h: 54 ÷ 3.6 = 15 m/s.\nStep 2: Distance = 15 × 20.\nStep 3: Distance = 300 m.","steps":["Step 1: Convert 54 km/h: 54 ÷ 3.6 = 15 m/s.","Step 2: Distance = 15 × 20.","Step 3: Distance = 300 m."],"options":[],"conceptId":"physics_equations_of_linear_motion_solving_motion_problems","skillId":"physics_equations_of_linear_motion","subskillId":"physics_equations_of_linear_motion_q3","subject":"physics","chapter":"equations_of_linear_motion","topic":"Solving Motion Problems"}', 2),
  (1413, 383, 'A car slows uniformly from 20 m/s to 8 m/s in 4 s. Calculate its acceleration.', 'text', 1, 'Acceleration is the change in velocity divided by time.', '{"why":"Velocity decreases by 12 m/s over 4 seconds, giving an acceleration of -3 m/s².","sol":"Step 1: u = 20 m/s, v = 8 m/s, t = 4 s.\nStep 2: a = (8 - 20) ÷ 4.\nStep 3: a = -12 ÷ 4 = -3 m/s².","steps":["Step 1: u = 20 m/s, v = 8 m/s, t = 4 s.","Step 2: a = (8 - 20) ÷ 4.","Step 3: a = -12 ÷ 4 = -3 m/s²."],"options":[],"conceptId":"physics_equations_of_linear_motion_solving_motion_problems","skillId":"physics_equations_of_linear_motion","subskillId":"physics_equations_of_linear_motion_q4","subject":"physics","chapter":"equations_of_linear_motion","topic":"Solving Motion Problems"}', 3),
  (1414, 383, 'A body starts from rest and accelerates uniformly at 4 m/s² until its velocity reaches 12 m/s. Find its displacement during this interval.', 'text', 1, 'Time is not given. Choose an equation that does not contain time.', '{"why":"The equation v² = u² + 2as links velocity, acceleration and displacement without requiring time.","sol":"Step 1: u = 0 m/s, v = 12 m/s and a = 4 m/s².\nStep 2: 12² = 0² + 2 × 4 × s.\nStep 3: 144 = 8s.\nStep 4: s = 18 m.","steps":["Step 1: u = 0 m/s, v = 12 m/s and a = 4 m/s².","Step 2: 12² = 0² + 2 × 4 × s.","Step 3: 144 = 8s.","Step 4: s = 18 m."],"options":[],"conceptId":"physics_equations_of_linear_motion_solving_motion_problems","skillId":"physics_equations_of_linear_motion","subskillId":"physics_equations_of_linear_motion_q5","subject":"physics","chapter":"equations_of_linear_motion","topic":"Solving Motion Problems"}', 4),
  (1415, 384, 'A train moves at a constant speed of 20 m/s for 15 s. Find the distance travelled.', 'text', 1, 'Multiply speed by time.', '{"why":"At constant speed, the distance travelled equals speed multiplied by time.","sol":"Step 1: Speed = 20 m/s and time = 15 s.\nStep 2: Distance = 20 × 15.\nStep 3: Distance = 300 m.","steps":["Step 1: Speed = 20 m/s and time = 15 s.","Step 2: Distance = 20 × 15.","Step 3: Distance = 300 m."],"options":[],"conceptId":"physics_equations_of_linear_motion_uniform_motion","skillId":"physics_equations_of_linear_motion","subskillId":"physics_equations_of_linear_motion_q1","subject":"physics","chapter":"equations_of_linear_motion","topic":"Uniform Motion"}', 0),
  (1416, 384, 'A cyclist covers 450 m at a constant speed of 5 m/s. Calculate the time taken.', 'text', 1, 'Rearrange distance = speed × time to make time the subject.', '{"why":"The time taken is the distance divided by the constant speed.","sol":"Step 1: Distance = 450 m and speed = 5 m/s.\nStep 2: Time = 450 ÷ 5.\nStep 3: Time = 90 s.","steps":["Step 1: Distance = 450 m and speed = 5 m/s.","Step 2: Time = 450 ÷ 5.","Step 3: Time = 90 s."],"options":[],"conceptId":"physics_equations_of_linear_motion_uniform_motion","skillId":"physics_equations_of_linear_motion","subskillId":"physics_equations_of_linear_motion_q2","subject":"physics","chapter":"equations_of_linear_motion","topic":"Uniform Motion"}', 1),
  (1417, 384, 'An object moves at a constant velocity of −4 m/s for 7 s. What is its displacement?', 'text', 1, 'Keep the negative sign when multiplying velocity by time.', '{"why":"Constant velocity multiplied by time gives signed displacement.","sol":"Step 1: Velocity = −4 m/s and time = 7 s.\nStep 2: Displacement = −4 × 7.\nStep 3: Displacement = −28 m.","steps":["Step 1: Velocity = −4 m/s and time = 7 s.","Step 2: Displacement = −4 × 7.","Step 3: Displacement = −28 m."],"options":[],"conceptId":"physics_equations_of_linear_motion_uniform_motion","skillId":"physics_equations_of_linear_motion","subskillId":"physics_equations_of_linear_motion_q3","subject":"physics","chapter":"equations_of_linear_motion","topic":"Uniform Motion"}', 2),
  (1418, 384, 'Which condition must remain unchanged for an object to have uniform velocity?', 'text', 1, 'Velocity describes both how fast and in which direction an object moves.', '{"why":"A change in either speed or direction changes velocity.","sol":"Step 1: Velocity includes speed and direction.\nStep 2: Uniform velocity means velocity remains constant.\nStep 3: Therefore, both speed and direction must remain unchanged.","steps":["Step 1: Velocity includes speed and direction.","Step 2: Uniform velocity means velocity remains constant.","Step 3: Therefore, both speed and direction must remain unchanged."],"options":[],"conceptId":"physics_equations_of_linear_motion_uniform_motion","skillId":"physics_equations_of_linear_motion","subskillId":"physics_equations_of_linear_motion_q4","subject":"physics","chapter":"equations_of_linear_motion","topic":"Uniform Motion"}', 3),
  (1419, 384, 'A vehicle moves at a constant speed of 72 km/h for 25 s. Find the distance travelled in metres.', 'text', 1, 'Convert the speed to m/s before multiplying by time.', '{"why":"Convert the speed to compatible units before applying distance = speed × time.","sol":"Step 1: Convert speed: 72 ÷ 3.6 = 20 m/s.\nStep 2: Distance = 20 × 25.\nStep 3: Distance = 500 m.","steps":["Step 1: Convert speed: 72 ÷ 3.6 = 20 m/s.","Step 2: Distance = 20 × 25.","Step 3: Distance = 500 m."],"options":[],"conceptId":"physics_equations_of_linear_motion_uniform_motion","skillId":"physics_equations_of_linear_motion","subskillId":"physics_equations_of_linear_motion_q5","subject":"physics","chapter":"equations_of_linear_motion","topic":"Uniform Motion"}', 4),
  (1420, 385, 'A car increases its velocity from 4 m/s to 16 m/s in 3 s. Calculate its uniform acceleration.', 'text', 1, 'Subtract initial velocity from final velocity, then divide by time.', '{"why":"Acceleration measures the change in velocity per second.","sol":"Step 1: u = 4 m/s, v = 16 m/s and t = 3 s.\nStep 2: a = (16 − 4) ÷ 3.\nStep 3: a = 12 ÷ 3 = +4 m/s².","steps":["Step 1: u = 4 m/s, v = 16 m/s and t = 3 s.","Step 2: a = (16 − 4) ÷ 3.","Step 3: a = 12 ÷ 3 = +4 m/s²."],"options":[],"conceptId":"physics_equations_of_linear_motion_uniform_acceleration","skillId":"physics_equations_of_linear_motion","subskillId":"physics_equations_of_linear_motion_q1","subject":"physics","chapter":"equations_of_linear_motion","topic":"Uniform Acceleration"}', 0),
  (1421, 385, 'A bus slows uniformly from 25 m/s to 10 m/s in 5 s. Find its acceleration.', 'text', 1, 'Final velocity is smaller than initial velocity, so the result will be negative if forward is positive.', '{"why":"The velocity changes by −15 m/s over 5 seconds.","sol":"Step 1: u = 25 m/s, v = 10 m/s and t = 5 s.\nStep 2: a = (10 − 25) ÷ 5.\nStep 3: a = −15 ÷ 5 = −3 m/s².","steps":["Step 1: u = 25 m/s, v = 10 m/s and t = 5 s.","Step 2: a = (10 − 25) ÷ 5.","Step 3: a = −15 ÷ 5 = −3 m/s²."],"options":[],"conceptId":"physics_equations_of_linear_motion_uniform_acceleration","skillId":"physics_equations_of_linear_motion","subskillId":"physics_equations_of_linear_motion_q2","subject":"physics","chapter":"equations_of_linear_motion","topic":"Uniform Acceleration"}', 1),
  (1422, 385, 'A body starts at 2 m/s and accelerates uniformly at 3 m/s² for 4 s. Find its final velocity.', 'text', 1, 'Use the equation that connects initial velocity, acceleration, time and final velocity.', '{"why":"The velocity change is at = 3 × 4 = 12 m/s.","sol":"Step 1: u = 2 m/s, a = 3 m/s² and t = 4 s.\nStep 2: v = 2 + (3 × 4).\nStep 3: v = 14 m/s.","steps":["Step 1: u = 2 m/s, a = 3 m/s² and t = 4 s.","Step 2: v = 2 + (3 × 4).","Step 3: v = 14 m/s."],"options":[],"conceptId":"physics_equations_of_linear_motion_uniform_acceleration","skillId":"physics_equations_of_linear_motion","subskillId":"physics_equations_of_linear_motion_q3","subject":"physics","chapter":"equations_of_linear_motion","topic":"Uniform Acceleration"}', 2),
  (1423, 385, 'An object moves at −12 m/s with an acceleration of +3 m/s² for 2 s. What is its final velocity?', 'text', 1, 'Use signed values in v = u + at.', '{"why":"Positive acceleration makes the negative velocity less negative during this interval.","sol":"Step 1: u = −12 m/s, a = +3 m/s² and t = 2 s.\nStep 2: v = −12 + (3 × 2).\nStep 3: v = −12 + 6 = −6 m/s.","steps":["Step 1: u = −12 m/s, a = +3 m/s² and t = 2 s.","Step 2: v = −12 + (3 × 2).","Step 3: v = −12 + 6 = −6 m/s."],"options":[],"conceptId":"physics_equations_of_linear_motion_uniform_acceleration","skillId":"physics_equations_of_linear_motion","subskillId":"physics_equations_of_linear_motion_q4","subject":"physics","chapter":"equations_of_linear_motion","topic":"Uniform Acceleration"}', 3),
  (1424, 385, 'What condition must be satisfied before using the standard equations of linear motion involving u, v, a, s and t?', 'text', 1, 'These equations assume a particular behaviour of acceleration.', '{"why":"The standard SUVAT equations are derived for motion with constant acceleration.","sol":"Step 1: The equations relate initial velocity, final velocity, displacement, time and acceleration.\nStep 2: Their standard form assumes acceleration is constant.\nStep 3: The quantities must also use consistent units and signed directions.","steps":["Step 1: The equations relate initial velocity, final velocity, displacement, time and acceleration.","Step 2: Their standard form assumes acceleration is constant.","Step 3: The quantities must also use consistent units and signed directions."],"options":[],"conceptId":"physics_equations_of_linear_motion_uniform_acceleration","skillId":"physics_equations_of_linear_motion","subskillId":"physics_equations_of_linear_motion_q5","subject":"physics","chapter":"equations_of_linear_motion","topic":"Uniform Acceleration"}', 4),
  (1425, 386, 'A body has u = 6 m/s, a = 2 m/s² and t = 5 s. Which equation directly finds its final velocity?', 'text', 1, 'Choose the equation containing u, a and t but not displacement.', '{"why":"This equation directly connects initial velocity, acceleration, elapsed time and final velocity.","sol":"Step 1: Known quantities are u, a and t.\nStep 2: The required quantity is v.\nStep 3: Use v = u + at.","steps":["Step 1: Known quantities are u, a and t.","Step 2: The required quantity is v.","Step 3: Use v = u + at."],"options":[],"conceptId":"physics_equations_of_linear_motion_selecting_the_correct_motion_equation","skillId":"physics_equations_of_linear_motion","subskillId":"physics_equations_of_linear_motion_q1","subject":"physics","chapter":"equations_of_linear_motion","topic":"Selecting the Correct Motion Equation"}', 0),
  (1426, 386, 'A vehicle has u = 3 m/s, v = 15 m/s and a = 3 m/s². Which equation finds displacement without first calculating time?', 'text', 1, 'Choose an equation containing u, v, a and s but no t.', '{"why":"The equation links velocity, acceleration and displacement directly.","sol":"Step 1: Known quantities are u, v and a.\nStep 2: Time is not supplied and need not be found.\nStep 3: Use v² = u² + 2as.","steps":["Step 1: Known quantities are u, v and a.","Step 2: Time is not supplied and need not be found.","Step 3: Use v² = u² + 2as."],"options":[],"conceptId":"physics_equations_of_linear_motion_selecting_the_correct_motion_equation","skillId":"physics_equations_of_linear_motion","subskillId":"physics_equations_of_linear_motion_q2","subject":"physics","chapter":"equations_of_linear_motion","topic":"Selecting the Correct Motion Equation"}', 1),
  (1427, 386, 'A body has u = 4 m/s, a = 2 m/s² and t = 3 s. Which equation directly finds displacement?', 'text', 1, 'Look for the equation containing initial velocity, acceleration and time.', '{"why":"This equation calculates displacement from initial velocity, constant acceleration and time.","sol":"Step 1: Known quantities are u, a and t.\nStep 2: The required quantity is displacement s.\nStep 3: Choose s = ut + ½at².","steps":["Step 1: Known quantities are u, a and t.","Step 2: The required quantity is displacement s.","Step 3: Choose s = ut + ½at²."],"options":[],"conceptId":"physics_equations_of_linear_motion_selecting_the_correct_motion_equation","skillId":"physics_equations_of_linear_motion","subskillId":"physics_equations_of_linear_motion_q3","subject":"physics","chapter":"equations_of_linear_motion","topic":"Selecting the Correct Motion Equation"}', 2),
  (1428, 386, 'A vehicle has u = 8 m/s, v = 20 m/s and t = 4 s. Which equation directly finds displacement?', 'text', 1, 'The initial velocity, final velocity and time are all known.', '{"why":"For constant acceleration, average velocity equals half the sum of the initial and final velocities.","sol":"Step 1: Known quantities are u, v and t.\nStep 2: The required quantity is s.\nStep 3: Choose s = ½(u + v)t.","steps":["Step 1: Known quantities are u, v and t.","Step 2: The required quantity is s.","Step 3: Choose s = ½(u + v)t."],"options":[],"conceptId":"physics_equations_of_linear_motion_selecting_the_correct_motion_equation","skillId":"physics_equations_of_linear_motion","subskillId":"physics_equations_of_linear_motion_q4","subject":"physics","chapter":"equations_of_linear_motion","topic":"Selecting the Correct Motion Equation"}', 3),
  (1429, 386, 'A body has final velocity v = 10 m/s, acceleration a = 2 m/s² and time t = 3 s. Which equation finds displacement without needing initial velocity?', 'text', 1, 'Choose the equation involving final velocity, acceleration, time and displacement.', '{"why":"This form calculates displacement using final velocity, constant acceleration and elapsed time.","sol":"Step 1: Known quantities are v, a and t.\nStep 2: Initial velocity u is not supplied.\nStep 3: Use s = vt − ½at².","steps":["Step 1: Known quantities are v, a and t.","Step 2: Initial velocity u is not supplied.","Step 3: Use s = vt − ½at²."],"options":[],"conceptId":"physics_equations_of_linear_motion_selecting_the_correct_motion_equation","skillId":"physics_equations_of_linear_motion","subskillId":"physics_equations_of_linear_motion_q5","subject":"physics","chapter":"equations_of_linear_motion","topic":"Selecting the Correct Motion Equation"}', 4),
  (1430, 387, 'A stone is released from rest and falls freely for 4 s. Take g = 10 m/s² and downward as positive. What is its final velocity?', 'text', 1, 'Use v = u + at. The stone starts from rest.', '{"why":"Gravity changes the velocity by 10 m/s each second when air resistance is ignored.","sol":"Step 1: u = 0 m/s, a = +10 m/s², t = 4 s.\nStep 2: v = 0 + (10 × 4).\nStep 3: v = +40 m/s.","steps":["Step 1: u = 0 m/s, a = +10 m/s², t = 4 s.","Step 2: v = 0 + (10 × 4).","Step 3: v = +40 m/s."],"options":[],"conceptId":"physics_equations_of_linear_motion_free_fall","skillId":"physics_equations_of_linear_motion","subskillId":"physics_equations_of_linear_motion_q1","subject":"physics","chapter":"equations_of_linear_motion","topic":"Free Fall"}', 0),
  (1431, 387, 'A ball is dropped from rest and falls for 3 s. Take g = 10 m/s². How far does it fall?', 'text', 1, 'Use the displacement equation with initial velocity zero.', '{"why":"For an object released from rest, the distance fallen under constant gravity is ½gt².","sol":"Step 1: u = 0, a = 10 m/s², t = 3 s.\nStep 2: s = 0 + ½ × 10 × 3².\nStep 3: s = 5 × 9 = 45 m.","steps":["Step 1: u = 0, a = 10 m/s², t = 3 s.","Step 2: s = 0 + ½ × 10 × 3².","Step 3: s = 5 × 9 = 45 m."],"options":[],"conceptId":"physics_equations_of_linear_motion_free_fall","skillId":"physics_equations_of_linear_motion","subskillId":"physics_equations_of_linear_motion_q2","subject":"physics","chapter":"equations_of_linear_motion","topic":"Free Fall"}', 1),
  (1432, 387, 'A ball is thrown vertically upward at 30 m/s. Take upward as positive and g = 10 m/s². How long does it take to reach the highest point?', 'text', 1, 'At the highest point, the instantaneous vertical velocity is zero.', '{"why":"Gravity acts downward throughout the flight, slowing the upward motion until the velocity is momentarily zero.","sol":"Step 1: u = +30 m/s, v = 0 m/s and a = −10 m/s².\nStep 2: 0 = 30 − 10t.\nStep 3: 10t = 30, so t = 3 s.","steps":["Step 1: u = +30 m/s, v = 0 m/s and a = −10 m/s².","Step 2: 0 = 30 − 10t.","Step 3: 10t = 30, so t = 3 s."],"options":[],"conceptId":"physics_equations_of_linear_motion_free_fall","skillId":"physics_equations_of_linear_motion","subskillId":"physics_equations_of_linear_motion_q3","subject":"physics","chapter":"equations_of_linear_motion","topic":"Free Fall"}', 2),
  (1433, 387, 'Ignoring air resistance, what is the acceleration of a freely falling object near Earth''s surface when g = 9.8 m/s²?', 'text', 1, 'Free fall means gravity is the only force acting.', '{"why":"In free fall, gravitational acceleration is the same for all objects at the same location when air resistance is negligible.","sol":"Step 1: Gravity produces acceleration g near Earth''s surface.\nStep 2: The magnitude is 9.8 m/s².\nStep 3: Its direction is downward.","steps":["Step 1: Gravity produces acceleration g near Earth''s surface.","Step 2: The magnitude is 9.8 m/s².","Step 3: Its direction is downward."],"options":[],"conceptId":"physics_equations_of_linear_motion_free_fall","skillId":"physics_equations_of_linear_motion","subskillId":"physics_equations_of_linear_motion_q4","subject":"physics","chapter":"equations_of_linear_motion","topic":"Free Fall"}', 3),
  (1434, 387, 'At the highest point of a ball thrown vertically upward, what are its instantaneous velocity and acceleration, taking upward as positive and ignoring air resistance?', 'text', 1, 'Separate the momentary velocity from the continuing effect of gravity.', '{"why":"The velocity is momentarily zero at the turning point, but gravity continues to accelerate the ball downward.","sol":"Step 1: At the highest point, the ball momentarily stops moving upward.\nStep 2: Its instantaneous velocity is 0 m/s.\nStep 3: Gravity still acts downward, so acceleration is −g.","steps":["Step 1: At the highest point, the ball momentarily stops moving upward.","Step 2: Its instantaneous velocity is 0 m/s.","Step 3: Gravity still acts downward, so acceleration is −g."],"options":[],"conceptId":"physics_equations_of_linear_motion_free_fall","skillId":"physics_equations_of_linear_motion","subskillId":"physics_equations_of_linear_motion_q5","subject":"physics","chapter":"equations_of_linear_motion","topic":"Free Fall"}', 4),
  (1435, 388, 'A distance–time graph rises from 0 m at 0 s to 24 m at 6 s in a straight line. What is the speed?', 'text', 1, 'Calculate the gradient by dividing the change in distance by the change in time.', '{"why":"The gradient of a distance–time graph represents speed.","sol":"Step 1: Change in distance = 24 − 0 = 24 m.\nStep 2: Change in time = 6 − 0 = 6 s.\nStep 3: Speed = 24 ÷ 6 = 4 m/s.","steps":["Step 1: Change in distance = 24 − 0 = 24 m.","Step 2: Change in time = 6 − 0 = 6 s.","Step 3: Speed = 24 ÷ 6 = 4 m/s."],"options":[],"conceptId":"physics_motion_graphs_distance_time_graphs","skillId":"physics_motion_graphs","subskillId":"physics_motion_graphs_q1","subject":"physics","chapter":"motion_graphs","topic":"Distance–Time Graphs"}', 0),
  (1436, 388, 'A distance–time graph is horizontal at 15 m from 2 s to 7 s. What is the speed during this interval?', 'text', 1, 'The distance does not change. Find the change in distance first.', '{"why":"The horizontal line shows that the distance reading stays the same as time passes.","sol":"Step 1: Change in distance = 15 − 15 = 0 m.\nStep 2: Change in time = 7 − 2 = 5 s.\nStep 3: Speed = 0 ÷ 5 = 0 m/s.","steps":["Step 1: Change in distance = 15 − 15 = 0 m.","Step 2: Change in time = 7 − 2 = 5 s.","Step 3: Speed = 0 ÷ 5 = 0 m/s."],"options":[],"conceptId":"physics_motion_graphs_distance_time_graphs","skillId":"physics_motion_graphs","subskillId":"physics_motion_graphs_q2","subject":"physics","chapter":"motion_graphs","topic":"Distance–Time Graphs"}', 1),
  (1437, 388, 'A straight distance–time graph passes through (2 s, 8 m) and (5 s, 20 m). Find the speed.', 'text', 1, 'Use differences between the two points, not just one point.', '{"why":"The gradient is the change in vertical value divided by the change in horizontal value.","sol":"Step 1: Change in distance = 20 − 8 = 12 m.\nStep 2: Change in time = 5 − 2 = 3 s.\nStep 3: Speed = 12 ÷ 3 = 4 m/s.","steps":["Step 1: Change in distance = 20 − 8 = 12 m.","Step 2: Change in time = 5 − 2 = 3 s.","Step 3: Speed = 12 ÷ 3 = 4 m/s."],"options":[],"conceptId":"physics_motion_graphs_distance_time_graphs","skillId":"physics_motion_graphs","subskillId":"physics_motion_graphs_q3","subject":"physics","chapter":"motion_graphs","topic":"Distance–Time Graphs"}', 2),
  (1438, 388, 'Two straight distance–time lines start at the origin. Line A reaches 10 m at 5 s. Line B reaches 18 m at 6 s. Which object is faster?', 'text', 1, 'Calculate each line''s gradient.', '{"why":"Speed depends on both distance travelled and the time taken.","sol":"Step 1: Speed A = 10 ÷ 5 = 2 m/s.\nStep 2: Speed B = 18 ÷ 6 = 3 m/s.\nStep 3: Since 3 m/s is greater than 2 m/s, B is faster.","steps":["Step 1: Speed A = 10 ÷ 5 = 2 m/s.","Step 2: Speed B = 18 ÷ 6 = 3 m/s.","Step 3: Since 3 m/s is greater than 2 m/s, B is faster."],"options":[],"conceptId":"physics_motion_graphs_distance_time_graphs","skillId":"physics_motion_graphs","subskillId":"physics_motion_graphs_q4","subject":"physics","chapter":"motion_graphs","topic":"Distance–Time Graphs"}', 3),
  (1439, 388, 'A distance–time graph rises in a straight line from 5 m at 2 s to 17 m at 6 s. What is the speed?', 'text', 1, 'Subtract the starting values from the ending values.', '{"why":"For a graph section, speed is the change in distance divided by the elapsed time.","sol":"Step 1: Change in distance = 17 − 5 = 12 m.\nStep 2: Change in time = 6 − 2 = 4 s.\nStep 3: Speed = 12 ÷ 4 = 3 m/s.","steps":["Step 1: Change in distance = 17 − 5 = 12 m.","Step 2: Change in time = 6 − 2 = 4 s.","Step 3: Speed = 12 ÷ 4 = 3 m/s."],"options":[],"conceptId":"physics_motion_graphs_distance_time_graphs","skillId":"physics_motion_graphs","subskillId":"physics_motion_graphs_q5","subject":"physics","chapter":"motion_graphs","topic":"Distance–Time Graphs"}', 4),
  (1440, 389, 'Displacement changes from 0 m at 0 s to 15 m at 5 s along a straight line. What is the velocity?', 'text', 1, 'Calculate the gradient of the displacement–time graph.', '{"why":"Velocity is the gradient of a displacement–time graph.","sol":"Step 1: Change in displacement = 15 − 0 = 15 m.\nStep 2: Change in time = 5 − 0 = 5 s.\nStep 3: Velocity = 15 ÷ 5 = +3 m/s.","steps":["Step 1: Change in displacement = 15 − 0 = 15 m.","Step 2: Change in time = 5 − 0 = 5 s.","Step 3: Velocity = 15 ÷ 5 = +3 m/s."],"options":[],"conceptId":"physics_motion_graphs_displacement_time_graphs","skillId":"physics_motion_graphs","subskillId":"physics_motion_graphs_q1","subject":"physics","chapter":"motion_graphs","topic":"Displacement–Time Graphs"}', 0),
  (1441, 389, 'An object''s displacement changes from +10 m at 2 s to +2 m at 6 s. Calculate its average velocity.', 'text', 1, 'The change in displacement may be negative.', '{"why":"The displacement decreases by 8 m over 4 s, so the average velocity is negative.","sol":"Step 1: Change in displacement = 2 − 10 = −8 m.\nStep 2: Change in time = 6 − 2 = 4 s.\nStep 3: Average velocity = −8 ÷ 4 = −2 m/s.","steps":["Step 1: Change in displacement = 2 − 10 = −8 m.","Step 2: Change in time = 6 − 2 = 4 s.","Step 3: Average velocity = −8 ÷ 4 = −2 m/s."],"options":[],"conceptId":"physics_motion_graphs_displacement_time_graphs","skillId":"physics_motion_graphs","subskillId":"physics_motion_graphs_q2","subject":"physics","chapter":"motion_graphs","topic":"Displacement–Time Graphs"}', 1),
  (1442, 389, 'A displacement–time graph is horizontal at −6 m between 4 s and 9 s. What is the velocity?', 'text', 1, 'Calculate the change in displacement.', '{"why":"The graph is horizontal, so its gradient and the velocity are zero.","sol":"Step 1: Change in displacement = −6 − (−6) = 0 m.\nStep 2: Change in time = 9 − 4 = 5 s.\nStep 3: Velocity = 0 ÷ 5 = 0 m/s.","steps":["Step 1: Change in displacement = −6 − (−6) = 0 m.","Step 2: Change in time = 9 − 4 = 5 s.","Step 3: Velocity = 0 ÷ 5 = 0 m/s."],"options":[],"conceptId":"physics_motion_graphs_displacement_time_graphs","skillId":"physics_motion_graphs","subskillId":"physics_motion_graphs_q3","subject":"physics","chapter":"motion_graphs","topic":"Displacement–Time Graphs"}', 2),
  (1443, 389, 'Which graph feature indicates constant negative velocity on a displacement–time graph?', 'text', 1, 'Constant velocity requires a constant gradient; negative velocity requires a negative gradient.', '{"why":"A straight line gives constant velocity, and its negative gradient gives the direction.","sol":"Step 1: A straight line has a constant gradient.\nStep 2: A line sloping downward as time increases has a negative gradient.\nStep 3: Therefore, a straight downward-sloping line indicates constant negative velocity.","steps":["Step 1: A straight line has a constant gradient.","Step 2: A line sloping downward as time increases has a negative gradient.","Step 3: Therefore, a straight downward-sloping line indicates constant negative velocity."],"options":[],"conceptId":"physics_motion_graphs_displacement_time_graphs","skillId":"physics_motion_graphs","subskillId":"physics_motion_graphs_q4","subject":"physics","chapter":"motion_graphs","topic":"Displacement–Time Graphs"}', 3),
  (1444, 389, 'A displacement–time graph passes through (1 s, −2 m) and (5 s, +10 m) on a straight section. Find the velocity.', 'text', 1, 'Subtract the initial displacement, including its sign, from the final displacement.', '{"why":"The displacement increases by 12 m in 4 s, giving a positive velocity of 3 m/s.","sol":"Step 1: Change in displacement = 10 − (−2) = 12 m.\nStep 2: Change in time = 5 − 1 = 4 s.\nStep 3: Velocity = 12 ÷ 4 = +3 m/s.","steps":["Step 1: Change in displacement = 10 − (−2) = 12 m.","Step 2: Change in time = 5 − 1 = 4 s.","Step 3: Velocity = 12 ÷ 4 = +3 m/s."],"options":[],"conceptId":"physics_motion_graphs_displacement_time_graphs","skillId":"physics_motion_graphs","subskillId":"physics_motion_graphs_q5","subject":"physics","chapter":"motion_graphs","topic":"Displacement–Time Graphs"}', 4),
  (1445, 390, 'A vehicle travels at a constant speed of 7 m/s for 6 s. Find the distance represented by the area under its speed–time graph.', 'text', 1, 'The area is a rectangle.', '{"why":"The area under a speed–time graph gives the distance travelled.","sol":"Step 1: Rectangle height = 7 m/s.\nStep 2: Rectangle base = 6 s.\nStep 3: Distance = 7 × 6 = 42 m.","steps":["Step 1: Rectangle height = 7 m/s.","Step 2: Rectangle base = 6 s.","Step 3: Distance = 7 × 6 = 42 m."],"options":[],"conceptId":"physics_motion_graphs_speed_time_graphs","skillId":"physics_motion_graphs","subskillId":"physics_motion_graphs_q1","subject":"physics","chapter":"motion_graphs","topic":"Speed–Time Graphs"}', 0),
  (1446, 390, 'A body accelerates uniformly from 0 m/s to 10 m/s in 4 s. Calculate the distance travelled.', 'text', 1, 'The area under the graph is triangular.', '{"why":"The triangular area represents the accumulated distance as speed rises from zero.","sol":"Step 1: Base = 4 s and height = 10 m/s.\nStep 2: Distance = ½ × 4 × 10.\nStep 3: Distance = 20 m.","steps":["Step 1: Base = 4 s and height = 10 m/s.","Step 2: Distance = ½ × 4 × 10.","Step 3: Distance = 20 m."],"options":[],"conceptId":"physics_motion_graphs_speed_time_graphs","skillId":"physics_motion_graphs","subskillId":"physics_motion_graphs_q2","subject":"physics","chapter":"motion_graphs","topic":"Speed–Time Graphs"}', 1),
  (1447, 390, 'Speed increases from 4 m/s to 16 m/s over 3 s. Find the gradient of the speed–time graph.', 'text', 1, 'Gradient is the change in speed divided by the elapsed time.', '{"why":"The graph gradient measures how quickly speed changes.","sol":"Step 1: Change in speed = 16 − 4 = 12 m/s.\nStep 2: Elapsed time = 3 s.\nStep 3: Gradient = 12 ÷ 3 = 4 m/s².","steps":["Step 1: Change in speed = 16 − 4 = 12 m/s.","Step 2: Elapsed time = 3 s.","Step 3: Gradient = 12 ÷ 3 = 4 m/s²."],"options":[],"conceptId":"physics_motion_graphs_speed_time_graphs","skillId":"physics_motion_graphs","subskillId":"physics_motion_graphs_q3","subject":"physics","chapter":"motion_graphs","topic":"Speed–Time Graphs"}', 2),
  (1448, 390, 'A speed–time graph is horizontal at 5 m/s from 2 s to 8 s. How far does the object travel during this interval?', 'text', 1, 'Use the width of this interval, not the total time shown on the clock.', '{"why":"A horizontal speed–time line means constant speed, not zero speed.","sol":"Step 1: Elapsed time = 8 − 2 = 6 s.\nStep 2: Distance = 5 × 6.\nStep 3: Distance = 30 m.","steps":["Step 1: Elapsed time = 8 − 2 = 6 s.","Step 2: Distance = 5 × 6.","Step 3: Distance = 30 m."],"options":[],"conceptId":"physics_motion_graphs_speed_time_graphs","skillId":"physics_motion_graphs","subskillId":"physics_motion_graphs_q4","subject":"physics","chapter":"motion_graphs","topic":"Speed–Time Graphs"}', 3),
  (1449, 390, 'A body slows uniformly from 12 m/s to 0 m/s over 6 s. What distance does it travel before stopping?', 'text', 1, 'The area under the graph is a triangle with base 6 s and height 12 m/s.', '{"why":"The triangular area gives the total distance travelled while slowing uniformly.","sol":"Step 1: Base = 6 s and height = 12 m/s.\nStep 2: Distance = ½ × 6 × 12.\nStep 3: Distance = 36 m.","steps":["Step 1: Base = 6 s and height = 12 m/s.","Step 2: Distance = ½ × 6 × 12.","Step 3: Distance = 36 m."],"options":[],"conceptId":"physics_motion_graphs_speed_time_graphs","skillId":"physics_motion_graphs","subskillId":"physics_motion_graphs_q5","subject":"physics","chapter":"motion_graphs","topic":"Speed–Time Graphs"}', 4),
  (1450, 391, 'Velocity increases from 3 m/s to 15 m/s in 4 s. Calculate the acceleration.', 'text', 1, 'Find the change in velocity and divide by time.', '{"why":"Acceleration is the gradient of a velocity–time graph.","sol":"Step 1: Change in velocity = 15 − 3 = 12 m/s.\nStep 2: Time = 4 s.\nStep 3: Acceleration = 12 ÷ 4 = +3 m/s².","steps":["Step 1: Change in velocity = 15 − 3 = 12 m/s.","Step 2: Time = 4 s.","Step 3: Acceleration = 12 ÷ 4 = +3 m/s²."],"options":[],"conceptId":"physics_motion_graphs_velocity_time_graphs","skillId":"physics_motion_graphs","subskillId":"physics_motion_graphs_q1","subject":"physics","chapter":"motion_graphs","topic":"Velocity–Time Graphs"}', 0),
  (1451, 391, 'A body has a constant velocity of −6 m/s for 5 s. Calculate its displacement.', 'text', 1, 'Multiply velocity by time and preserve the sign.', '{"why":"The signed area below the time axis represents negative displacement.","sol":"Step 1: Velocity = −6 m/s and time = 5 s.\nStep 2: Displacement = −6 × 5.\nStep 3: Displacement = −30 m.","steps":["Step 1: Velocity = −6 m/s and time = 5 s.","Step 2: Displacement = −6 × 5.","Step 3: Displacement = −30 m."],"options":[],"conceptId":"physics_motion_graphs_velocity_time_graphs","skillId":"physics_motion_graphs","subskillId":"physics_motion_graphs_q2","subject":"physics","chapter":"motion_graphs","topic":"Velocity–Time Graphs"}', 1),
  (1452, 391, 'Velocity increases uniformly from 0 to 12 m/s in 6 s. Find the displacement.', 'text', 1, 'Calculate the triangular area under the velocity–time graph.', '{"why":"The signed area under a velocity–time graph gives displacement.","sol":"Step 1: Base = 6 s and height = 12 m/s.\nStep 2: Displacement = ½ × 6 × 12.\nStep 3: Displacement = +36 m.","steps":["Step 1: Base = 6 s and height = 12 m/s.","Step 2: Displacement = ½ × 6 × 12.","Step 3: Displacement = +36 m."],"options":[],"conceptId":"physics_motion_graphs_velocity_time_graphs","skillId":"physics_motion_graphs","subskillId":"physics_motion_graphs_q3","subject":"physics","chapter":"motion_graphs","topic":"Velocity–Time Graphs"}', 2),
  (1453, 391, 'An object moves at +5 m/s for 4 s, then at −2 m/s for 3 s. What is its total displacement?', 'text', 1, 'Calculate each interval''s signed displacement, then add them.', '{"why":"Displacement includes direction, so the second interval contributes a negative value.","sol":"Step 1: First interval: +5 × 4 = +20 m.\nStep 2: Second interval: −2 × 3 = −6 m.\nStep 3: Total displacement = 20 − 6 = +14 m.","steps":["Step 1: First interval: +5 × 4 = +20 m.","Step 2: Second interval: −2 × 3 = −6 m.","Step 3: Total displacement = 20 − 6 = +14 m."],"options":[],"conceptId":"physics_motion_graphs_velocity_time_graphs","skillId":"physics_motion_graphs","subskillId":"physics_motion_graphs_q4","subject":"physics","chapter":"motion_graphs","topic":"Velocity–Time Graphs"}', 3),
  (1454, 391, 'A velocity–time graph is horizontal at +7 m/s from 1 s to 5 s. What is the acceleration during this interval?', 'text', 1, 'A horizontal line has zero gradient.', '{"why":"Constant velocity means zero acceleration, even when the object is moving.","sol":"Step 1: Initial velocity = +7 m/s.\nStep 2: Final velocity = +7 m/s.\nStep 3: Acceleration = (7 − 7) ÷ (5 − 1) = 0 m/s².","steps":["Step 1: Initial velocity = +7 m/s.","Step 2: Final velocity = +7 m/s.","Step 3: Acceleration = (7 − 7) ÷ (5 − 1) = 0 m/s²."],"options":[],"conceptId":"physics_motion_graphs_velocity_time_graphs","skillId":"physics_motion_graphs","subskillId":"physics_motion_graphs_q5","subject":"physics","chapter":"motion_graphs","topic":"Velocity–Time Graphs"}', 4),
  (1455, 392, 'A distance–time graph rises from 0 m to 18 m during the first 6 s, then stays horizontal from 6 s to 9 s. How long is the object stationary?', 'text', 1, 'Find the duration of the horizontal section.', '{"why":"The object is stationary for the duration of the horizontal section.","sol":"Step 1: The horizontal section starts at 6 s.\nStep 2: It ends at 9 s.\nStep 3: Duration = 9 − 6 = 3 s.","steps":["Step 1: The horizontal section starts at 6 s.","Step 2: It ends at 9 s.","Step 3: Duration = 9 − 6 = 3 s."],"options":[],"conceptId":"physics_motion_graphs_interpreting_motion_graphs","skillId":"physics_motion_graphs","subskillId":"physics_motion_graphs_q1","subject":"physics","chapter":"motion_graphs","topic":"Interpreting Motion Graphs"}', 0),
  (1456, 392, 'A velocity–time graph shows +3 m/s for 4 s, followed by −3 m/s for 2 s. Find the total displacement.', 'text', 1, 'Treat each interval''s area as signed.', '{"why":"Total displacement is the algebraic sum of the signed areas under the velocity–time graph.","sol":"Step 1: First displacement = +3 × 4 = +12 m.\nStep 2: Second displacement = −3 × 2 = −6 m.\nStep 3: Total displacement = 12 − 6 = +6 m.","steps":["Step 1: First displacement = +3 × 4 = +12 m.","Step 2: Second displacement = −3 × 2 = −6 m.","Step 3: Total displacement = 12 − 6 = +6 m."],"options":[],"conceptId":"physics_motion_graphs_interpreting_motion_graphs","skillId":"physics_motion_graphs","subskillId":"physics_motion_graphs_q2","subject":"physics","chapter":"motion_graphs","topic":"Interpreting Motion Graphs"}', 1),
  (1457, 392, 'Which quantity is found from the gradient of a velocity–time graph?', 'text', 1, 'Think about what change in velocity per unit time measures.', '{"why":"Acceleration is the gradient of a velocity–time graph.","sol":"Step 1: The gradient is change in vertical value divided by change in horizontal value.\nStep 2: For a velocity–time graph, this is change in velocity divided by time.\nStep 3: That quantity is acceleration.","steps":["Step 1: The gradient is change in vertical value divided by change in horizontal value.","Step 2: For a velocity–time graph, this is change in velocity divided by time.","Step 3: That quantity is acceleration."],"options":[],"conceptId":"physics_motion_graphs_interpreting_motion_graphs","skillId":"physics_motion_graphs","subskillId":"physics_motion_graphs_q3","subject":"physics","chapter":"motion_graphs","topic":"Interpreting Motion Graphs"}', 2),
  (1458, 392, 'A speed–time graph shows a constant speed of 8 m/s for 5 s. Which calculation gives the distance travelled?', 'text', 1, 'Use the area of the rectangle under the speed–time graph.', '{"why":"For a speed–time graph, the area under the graph represents distance travelled.","sol":"Step 1: The graph section forms a rectangle.\nStep 2: Area = 8 × 5.\nStep 3: Distance = 40 m.","steps":["Step 1: The graph section forms a rectangle.","Step 2: Area = 8 × 5.","Step 3: Distance = 40 m."],"options":[],"conceptId":"physics_motion_graphs_interpreting_motion_graphs","skillId":"physics_motion_graphs","subskillId":"physics_motion_graphs_q4","subject":"physics","chapter":"motion_graphs","topic":"Interpreting Motion Graphs"}', 3),
  (1459, 392, 'A displacement–time graph slopes downward in a straight line as time increases. What does this indicate?', 'text', 1, 'The gradient is constant and negative.', '{"why":"The slope of a displacement–time graph gives velocity; a straight negative slope gives constant negative velocity.","sol":"Step 1: A straight line indicates a constant gradient.\nStep 2: A downward slope means the gradient is negative.\nStep 3: The gradient represents velocity.","steps":["Step 1: A straight line indicates a constant gradient.","Step 2: A downward slope means the gradient is negative.","Step 3: The gradient represents velocity."],"options":[],"conceptId":"physics_motion_graphs_interpreting_motion_graphs","skillId":"physics_motion_graphs","subskillId":"physics_motion_graphs_q5","subject":"physics","chapter":"motion_graphs","topic":"Interpreting Motion Graphs"}', 4),
  (1460, 393, 'A box is pushed rightward with 12 N while friction acts leftward with 12 N. What is the resultant horizontal force?', 'text', 1, 'Opposing forces are subtracted.', '{"why":"Equal forces in opposite directions balance, giving zero resultant force.","sol":"Step 1: Rightward force = 12 N.\nStep 2: Leftward force = 12 N.\nStep 3: Resultant force = 12 − 12 = 0 N.","steps":["Step 1: Rightward force = 12 N.","Step 2: Leftward force = 12 N.","Step 3: Resultant force = 12 − 12 = 0 N."],"options":[],"conceptId":"physics_newtons_laws_of_motion_newton_s_first_law","skillId":"physics_newtons_laws_of_motion","subskillId":"physics_newtons_laws_of_motion_q1","subject":"physics","chapter":"newtons_laws_of_motion","topic":"Newton’s First Law"}', 0),
  (1461, 393, 'A spacecraft is travelling through deep space with negligible external forces. What happens to its velocity if the resultant force remains zero?', 'text', 1, 'Apply Newton''s first law to an object already moving.', '{"why":"Newton''s first law says that zero resultant force means zero acceleration.","sol":"Step 1: The spacecraft is already moving.\nStep 2: The resultant force is zero.\nStep 3: Its velocity remains constant in magnitude and direction.","steps":["Step 1: The spacecraft is already moving.","Step 2: The resultant force is zero.","Step 3: Its velocity remains constant in magnitude and direction."],"options":[],"conceptId":"physics_newtons_laws_of_motion_newton_s_first_law","skillId":"physics_newtons_laws_of_motion","subskillId":"physics_newtons_laws_of_motion_q2","subject":"physics","chapter":"newtons_laws_of_motion","topic":"Newton’s First Law"}', 1),
  (1462, 393, 'A book rests on a table. Does this prove that no forces act on the book?', 'text', 1, 'Consider the book''s weight and the upward support force.', '{"why":"Rest can occur when all forces balance to give zero resultant force.","sol":"Step 1: Gravity pulls the book downward.\nStep 2: The table exerts an upward support force.\nStep 3: The forces balance, so the resultant force is zero.","steps":["Step 1: Gravity pulls the book downward.","Step 2: The table exerts an upward support force.","Step 3: The forces balance, so the resultant force is zero."],"options":[],"conceptId":"physics_newtons_laws_of_motion_newton_s_first_law","skillId":"physics_newtons_laws_of_motion","subskillId":"physics_newtons_laws_of_motion_q3","subject":"physics","chapter":"newtons_laws_of_motion","topic":"Newton’s First Law"}', 2),
  (1463, 393, 'Why does a passenger tend to move forward when a moving bus stops suddenly?', 'text', 1, 'Think about the tendency of a body to maintain its existing motion.', '{"why":"Inertia is the tendency of an object to resist changes in its state of motion.","sol":"Step 1: Before braking, the passenger is moving with the bus.\nStep 2: The bus slows quickly.\nStep 3: The passenger''s body tends to maintain its previous motion until another force changes it.","steps":["Step 1: Before braking, the passenger is moving with the bus.","Step 2: The bus slows quickly.","Step 3: The passenger''s body tends to maintain its previous motion until another force changes it."],"options":[],"conceptId":"physics_newtons_laws_of_motion_newton_s_first_law","skillId":"physics_newtons_laws_of_motion","subskillId":"physics_newtons_laws_of_motion_q4","subject":"physics","chapter":"newtons_laws_of_motion","topic":"Newton’s First Law"}', 3),
  (1464, 393, 'An object moves in a straight line at constant velocity. What is its acceleration?', 'text', 1, 'Acceleration measures change in velocity per unit time.', '{"why":"With no change in velocity, acceleration is zero.","sol":"Step 1: The velocity does not change.\nStep 2: Change in velocity is zero.\nStep 3: Acceleration is therefore zero.","steps":["Step 1: The velocity does not change.","Step 2: Change in velocity is zero.","Step 3: Acceleration is therefore zero."],"options":[],"conceptId":"physics_newtons_laws_of_motion_newton_s_first_law","skillId":"physics_newtons_laws_of_motion","subskillId":"physics_newtons_laws_of_motion_q5","subject":"physics","chapter":"newtons_laws_of_motion","topic":"Newton’s First Law"}', 4),
  (1465, 394, 'A 6 kg object accelerates at 2 m/s². Find the resultant force.', 'text', 1, 'Multiply mass by acceleration.', '{"why":"Newton''s second law gives resultant force as mass multiplied by acceleration.","sol":"Step 1: m = 6 kg and a = 2 m/s².\nStep 2: F = 6 × 2.\nStep 3: F = 12 N.","steps":["Step 1: m = 6 kg and a = 2 m/s².","Step 2: F = 6 × 2.","Step 3: F = 12 N."],"options":[],"conceptId":"physics_newtons_laws_of_motion_newton_s_second_law","skillId":"physics_newtons_laws_of_motion","subskillId":"physics_newtons_laws_of_motion_q1","subject":"physics","chapter":"newtons_laws_of_motion","topic":"Newton’s Second Law"}', 0),
  (1466, 394, 'A resultant force of 35 N acts on a 7 kg trolley. Calculate its acceleration.', 'text', 1, 'Rearrange F = ma to make acceleration the subject.', '{"why":"Acceleration is the resultant force divided by mass.","sol":"Step 1: F = 35 N and m = 7 kg.\nStep 2: a = 35 ÷ 7.\nStep 3: a = 5 m/s².","steps":["Step 1: F = 35 N and m = 7 kg.","Step 2: a = 35 ÷ 7.","Step 3: a = 5 m/s²."],"options":[],"conceptId":"physics_newtons_laws_of_motion_newton_s_second_law","skillId":"physics_newtons_laws_of_motion","subskillId":"physics_newtons_laws_of_motion_q2","subject":"physics","chapter":"newtons_laws_of_motion","topic":"Newton’s Second Law"}', 1),
  (1467, 394, 'A force of 24 N produces an acceleration of 3 m/s². Find the mass of the object.', 'text', 1, 'Rearrange F = ma to find mass.', '{"why":"Mass equals resultant force divided by acceleration.","sol":"Step 1: F = 24 N and a = 3 m/s².\nStep 2: m = 24 ÷ 3.\nStep 3: m = 8 kg.","steps":["Step 1: F = 24 N and a = 3 m/s².","Step 2: m = 24 ÷ 3.","Step 3: m = 8 kg."],"options":[],"conceptId":"physics_newtons_laws_of_motion_newton_s_second_law","skillId":"physics_newtons_laws_of_motion","subskillId":"physics_newtons_laws_of_motion_q3","subject":"physics","chapter":"newtons_laws_of_motion","topic":"Newton’s Second Law"}', 2),
  (1468, 394, 'Two objects have the same mass. Object A experiences a resultant force of 10 N and object B experiences 30 N. How do their accelerations compare?', 'text', 1, 'Use a = F/m and keep the mass the same for both objects.', '{"why":"For constant mass, tripling the resultant force triples the acceleration.","sol":"Step 1: For the same mass, acceleration is directly proportional to resultant force.\nStep 2: Object B experiences three times the force.\nStep 3: Object B therefore has three times the acceleration of object A.","steps":["Step 1: For the same mass, acceleration is directly proportional to resultant force.","Step 2: Object B experiences three times the force.","Step 3: Object B therefore has three times the acceleration of object A."],"options":[],"conceptId":"physics_newtons_laws_of_motion_newton_s_second_law","skillId":"physics_newtons_laws_of_motion","subskillId":"physics_newtons_laws_of_motion_q4","subject":"physics","chapter":"newtons_laws_of_motion","topic":"Newton’s Second Law"}', 3),
  (1469, 394, 'A 2,000 g object accelerates at 4 m/s². What is the resultant force?', 'text', 1, 'Convert the mass from grams to kilograms first.', '{"why":"2,000 g equals 2 kg, so the resultant force is 8 N.","sol":"Step 1: Convert 2,000 g to 2 kg.\nStep 2: F = 2 × 4.\nStep 3: F = 8 N.","steps":["Step 1: Convert 2,000 g to 2 kg.","Step 2: F = 2 × 4.","Step 3: F = 8 N."],"options":[],"conceptId":"physics_newtons_laws_of_motion_newton_s_second_law","skillId":"physics_newtons_laws_of_motion","subskillId":"physics_newtons_laws_of_motion_q5","subject":"physics","chapter":"newtons_laws_of_motion","topic":"Newton’s Second Law"}', 4),
  (1470, 395, 'A person pushes a wall with a force of 80 N. What force does the wall exert on the person?', 'text', 1, 'Apply Newton''s third law: equal magnitude, opposite direction, different objects.', '{"why":"The forces in a third-law pair are equal in magnitude and opposite in direction.","sol":"Step 1: The person exerts 80 N on the wall.\nStep 2: The wall exerts an equal force on the person.\nStep 3: The force on the person acts in the opposite direction.","steps":["Step 1: The person exerts 80 N on the wall.","Step 2: The wall exerts an equal force on the person.","Step 3: The force on the person acts in the opposite direction."],"options":[],"conceptId":"physics_newtons_laws_of_motion_newton_s_third_law","skillId":"physics_newtons_laws_of_motion","subskillId":"physics_newtons_laws_of_motion_q1","subject":"physics","chapter":"newtons_laws_of_motion","topic":"Newton’s Third Law"}', 0),
  (1471, 395, 'When a swimmer pushes water backward, what force helps the swimmer move forward?', 'text', 1, 'Identify the force exerted by the water on the swimmer.', '{"why":"The water''s reaction force pushes the swimmer forward.","sol":"Step 1: The swimmer pushes the water backward.\nStep 2: The water exerts an equal and opposite force on the swimmer.\nStep 3: That force acts forward.","steps":["Step 1: The swimmer pushes the water backward.","Step 2: The water exerts an equal and opposite force on the swimmer.","Step 3: That force acts forward."],"options":[],"conceptId":"physics_newtons_laws_of_motion_newton_s_third_law","skillId":"physics_newtons_laws_of_motion","subskillId":"physics_newtons_laws_of_motion_q2","subject":"physics","chapter":"newtons_laws_of_motion","topic":"Newton’s Third Law"}', 1),
  (1472, 395, 'Why do the action and reaction forces in Newton''s third law not cancel each other on one object?', 'text', 1, 'Ask which object each force acts on.', '{"why":"Third-law forces are equal and opposite but act on different bodies.","sol":"Step 1: The action force acts on one object.\nStep 2: The reaction force acts on the other object.\nStep 3: They cannot be added together as forces acting on the same object.","steps":["Step 1: The action force acts on one object.","Step 2: The reaction force acts on the other object.","Step 3: They cannot be added together as forces acting on the same object."],"options":[],"conceptId":"physics_newtons_laws_of_motion_newton_s_third_law","skillId":"physics_newtons_laws_of_motion","subskillId":"physics_newtons_laws_of_motion_q3","subject":"physics","chapter":"newtons_laws_of_motion","topic":"Newton’s Third Law"}', 2),
  (1473, 395, 'A book presses downward on a table with a force of 15 N. What is the Newton''s third-law partner of this force?', 'text', 1, 'The partner must act on the other object in the interaction.', '{"why":"The reaction to the book''s force on the table is the table''s force on the book.","sol":"Step 1: The book exerts a downward force on the table.\nStep 2: The table exerts an equal force on the book.\nStep 3: That force is upward and has magnitude 15 N.","steps":["Step 1: The book exerts a downward force on the table.","Step 2: The table exerts an equal force on the book.","Step 3: That force is upward and has magnitude 15 N."],"options":[],"conceptId":"physics_newtons_laws_of_motion_newton_s_third_law","skillId":"physics_newtons_laws_of_motion","subskillId":"physics_newtons_laws_of_motion_q4","subject":"physics","chapter":"newtons_laws_of_motion","topic":"Newton’s Third Law"}', 3),
  (1474, 395, 'A small boat pushes water backward with a force of 200 N. The water pushes the boat forward with what magnitude of force?', 'text', 1, 'Newton''s third law says the forces in the pair have equal magnitudes.', '{"why":"The water''s force on the boat equals the boat''s force on the water in magnitude.","sol":"Step 1: The boat exerts 200 N on the water.\nStep 2: The water exerts an equal force on the boat.\nStep 3: The force on the boat is forward.","steps":["Step 1: The boat exerts 200 N on the water.","Step 2: The water exerts an equal force on the boat.","Step 3: The force on the boat is forward."],"options":[],"conceptId":"physics_newtons_laws_of_motion_newton_s_third_law","skillId":"physics_newtons_laws_of_motion","subskillId":"physics_newtons_laws_of_motion_q5","subject":"physics","chapter":"newtons_laws_of_motion","topic":"Newton’s Third Law"}', 4),
  (1475, 396, 'Which object has greater inertia: a 3 kg object or a 12 kg object?', 'text', 1, 'Inertia increases with mass.', '{"why":"Mass measures an object''s resistance to changes in motion.","sol":"Step 1: Compare the masses: 3 kg and 12 kg.\nStep 2: The 12 kg object has greater mass.\nStep 3: Therefore, it has greater inertia.","steps":["Step 1: Compare the masses: 3 kg and 12 kg.","Step 2: The 12 kg object has greater mass.","Step 3: Therefore, it has greater inertia."],"options":[],"conceptId":"physics_newtons_laws_of_motion_mass_and_inertia","skillId":"physics_newtons_laws_of_motion","subskillId":"physics_newtons_laws_of_motion_q1","subject":"physics","chapter":"newtons_laws_of_motion","topic":"Mass and Inertia"}', 0),
  (1476, 396, 'A resultant force of 20 N acts on a 4 kg object. What is its acceleration?', 'text', 1, 'Use Newton''s second law.', '{"why":"Acceleration equals resultant force divided by mass.","sol":"Step 1: F = 20 N and m = 4 kg.\nStep 2: a = 20 ÷ 4.\nStep 3: a = 5 m/s².","steps":["Step 1: F = 20 N and m = 4 kg.","Step 2: a = 20 ÷ 4.","Step 3: a = 5 m/s²."],"options":[],"conceptId":"physics_newtons_laws_of_motion_mass_and_inertia","skillId":"physics_newtons_laws_of_motion","subskillId":"physics_newtons_laws_of_motion_q2","subject":"physics","chapter":"newtons_laws_of_motion","topic":"Mass and Inertia"}', 1),
  (1477, 396, 'Two objects experience the same resultant force. Object A has a mass of 2 kg and Object B has a mass of 6 kg. How does their acceleration compare?', 'text', 1, 'Acceleration is inversely proportional to mass when force is the same.', '{"why":"For the same force, acceleration decreases as mass increases.","sol":"Step 1: Both objects have the same resultant force F.\nStep 2: Object B has three times the mass of Object A.\nStep 3: Object B''s acceleration is one-third of Object A''s acceleration.","steps":["Step 1: Both objects have the same resultant force F.","Step 2: Object B has three times the mass of Object A.","Step 3: Object B''s acceleration is one-third of Object A''s acceleration."],"options":[],"conceptId":"physics_newtons_laws_of_motion_mass_and_inertia","skillId":"physics_newtons_laws_of_motion","subskillId":"physics_newtons_laws_of_motion_q3","subject":"physics","chapter":"newtons_laws_of_motion","topic":"Mass and Inertia"}', 2),
  (1478, 396, 'What is inertia?', 'text', 1, 'Think of how an object responds when its motion is about to change.', '{"why":"Inertia describes an object''s resistance to a change in velocity.","sol":"Step 1: Objects tend to maintain their state of rest or uniform straight-line motion.\nStep 2: This resistance to a change in motion is called inertia.","steps":["Step 1: Objects tend to maintain their state of rest or uniform straight-line motion.","Step 2: This resistance to a change in motion is called inertia."],"options":[],"conceptId":"physics_newtons_laws_of_motion_mass_and_inertia","skillId":"physics_newtons_laws_of_motion","subskillId":"physics_newtons_laws_of_motion_q4","subject":"physics","chapter":"newtons_laws_of_motion","topic":"Mass and Inertia"}', 3),
  (1479, 396, 'An object''s mass is 5 kg on Earth. Ignoring any loss of material, what is its mass on the Moon?', 'text', 1, 'Distinguish mass from the gravitational force called weight.', '{"why":"Mass does not depend on the local gravitational field.","sol":"Step 1: Mass is a property of the object''s matter.\nStep 2: Moving to the Moon changes the gravitational field strength, not the object''s mass.\nStep 3: The mass remains 5 kg.","steps":["Step 1: Mass is a property of the object''s matter.","Step 2: Moving to the Moon changes the gravitational field strength, not the object''s mass.","Step 3: The mass remains 5 kg."],"options":[],"conceptId":"physics_newtons_laws_of_motion_mass_and_inertia","skillId":"physics_newtons_laws_of_motion","subskillId":"physics_newtons_laws_of_motion_q5","subject":"physics","chapter":"newtons_laws_of_motion","topic":"Mass and Inertia"}', 4),
  (1480, 397, 'A 4 kg trolley experiences a 28 N force to the right and a 12 N force to the left. Find its acceleration.', 'text', 1, 'Calculate the resultant force before using F = ma.', '{"why":"The opposing forces give a resultant of 16 N, which accelerates the 4 kg trolley at 4 m/s².","sol":"Step 1: Resultant force = 28 − 12 = 16 N to the right.\nStep 2: a = 16 ÷ 4.\nStep 3: a = 4 m/s² to the right.","steps":["Step 1: Resultant force = 28 − 12 = 16 N to the right.","Step 2: a = 16 ÷ 4.","Step 3: a = 4 m/s² to the right."],"options":[],"conceptId":"physics_newtons_laws_of_motion_force_mass_and_acceleration_calculations","skillId":"physics_newtons_laws_of_motion","subskillId":"physics_newtons_laws_of_motion_q1","subject":"physics","chapter":"newtons_laws_of_motion","topic":"Force, Mass and Acceleration Calculations"}', 0),
  (1481, 397, 'A 6 kg box is pushed rightward with 18 N while friction acts leftward with 18 N. What is its acceleration?', 'text', 1, 'Find the net force first.', '{"why":"The forces cancel, so the horizontal resultant force is zero.","sol":"Step 1: Resultant force = 18 − 18 = 0 N.\nStep 2: a = 0 ÷ 6.\nStep 3: a = 0 m/s².","steps":["Step 1: Resultant force = 18 − 18 = 0 N.","Step 2: a = 0 ÷ 6.","Step 3: a = 0 m/s²."],"options":[],"conceptId":"physics_newtons_laws_of_motion_force_mass_and_acceleration_calculations","skillId":"physics_newtons_laws_of_motion","subskillId":"physics_newtons_laws_of_motion_q2","subject":"physics","chapter":"newtons_laws_of_motion","topic":"Force, Mass and Acceleration Calculations"}', 1),
  (1482, 397, 'A 3 kg object accelerates at 5 m/s². Friction opposes the motion with a force of 4 N. What applied force is required in the direction of motion?', 'text', 1, 'Find the required resultant force first, then account for friction.', '{"why":"The applied force must overcome friction and still provide a 15 N resultant force.","sol":"Step 1: Required resultant force = ma = 3 × 5 = 15 N.\nStep 2: Let the applied force be F.\nStep 3: F − 4 = 15, so F = 19 N.","steps":["Step 1: Required resultant force = ma = 3 × 5 = 15 N.","Step 2: Let the applied force be F.","Step 3: F − 4 = 15, so F = 19 N."],"options":[],"conceptId":"physics_newtons_laws_of_motion_force_mass_and_acceleration_calculations","skillId":"physics_newtons_laws_of_motion","subskillId":"physics_newtons_laws_of_motion_q3","subject":"physics","chapter":"newtons_laws_of_motion","topic":"Force, Mass and Acceleration Calculations"}', 2),
  (1483, 397, 'A 2,500 g object experiences a resultant force of 10 N. Calculate its acceleration.', 'text', 1, 'Convert the mass to kilograms before using Newton''s second law.', '{"why":"Acceleration is resultant force divided by mass in kilograms.","sol":"Step 1: 2,500 g = 2.5 kg.\nStep 2: a = 10 ÷ 2.5.\nStep 3: a = 4 m/s².","steps":["Step 1: 2,500 g = 2.5 kg.","Step 2: a = 10 ÷ 2.5.","Step 3: a = 4 m/s²."],"options":[],"conceptId":"physics_newtons_laws_of_motion_force_mass_and_acceleration_calculations","skillId":"physics_newtons_laws_of_motion","subskillId":"physics_newtons_laws_of_motion_q4","subject":"physics","chapter":"newtons_laws_of_motion","topic":"Force, Mass and Acceleration Calculations"}', 3),
  (1484, 397, 'A 5 kg object accelerates at 2 m/s² to the left. Taking left as the positive direction, what is the resultant force?', 'text', 1, 'The acceleration is in the positive direction under the convention given.', '{"why":"The chosen sign convention defines left as positive, so the resultant force is positive and leftward.","sol":"Step 1: m = 5 kg and a = +2 m/s².\nStep 2: F = 5 × 2.\nStep 3: F = +10 N in the chosen positive direction, which is left.","steps":["Step 1: m = 5 kg and a = +2 m/s².","Step 2: F = 5 × 2.","Step 3: F = +10 N in the chosen positive direction, which is left."],"options":[],"conceptId":"physics_newtons_laws_of_motion_force_mass_and_acceleration_calculations","skillId":"physics_newtons_laws_of_motion","subskillId":"physics_newtons_laws_of_motion_q5","subject":"physics","chapter":"newtons_laws_of_motion","topic":"Force, Mass and Acceleration Calculations"}', 4),
  (1485, 398, 'Find the weight of a 7 kg object where g = 10 N/kg.', 'text', 1, 'Multiply mass by gravitational field strength.', '{"why":"Weight equals mass multiplied by gravitational field strength.","sol":"Step 1: m = 7 kg and g = 10 N/kg.\nStep 2: W = 7 × 10.\nStep 3: W = 70 N.","steps":["Step 1: m = 7 kg and g = 10 N/kg.","Step 2: W = 7 × 10.","Step 3: W = 70 N."],"options":[],"conceptId":"physics_mass_weight_and_density_mass_and_weight","skillId":"physics_mass_weight_and_density","subskillId":"physics_mass_weight_and_density_q1","subject":"physics","chapter":"mass_weight_and_density","topic":"Mass and Weight"}', 0),
  (1486, 398, 'An object weighs 250 N where g = 10 N/kg. What is its mass?', 'text', 1, 'Rearrange W = mg to make m the subject.', '{"why":"Mass is the weight divided by gravitational field strength.","sol":"Step 1: W = 250 N and g = 10 N/kg.\nStep 2: m = 250 ÷ 10.\nStep 3: m = 25 kg.","steps":["Step 1: W = 250 N and g = 10 N/kg.","Step 2: m = 250 ÷ 10.","Step 3: m = 25 kg."],"options":[],"conceptId":"physics_mass_weight_and_density_mass_and_weight","skillId":"physics_mass_weight_and_density","subskillId":"physics_mass_weight_and_density_q2","subject":"physics","chapter":"mass_weight_and_density","topic":"Mass and Weight"}', 1),
  (1487, 398, 'An astronaut has a mass of 80 kg on Earth. What is the astronaut''s mass on the Moon, assuming no material is lost or gained?', 'text', 1, 'Mass is independent of local gravitational field strength.', '{"why":"Mass remains constant when the object moves to a different gravitational field.","sol":"Step 1: Mass measures the object''s matter and inertia.\nStep 2: The location changes gravitational field strength, not mass.\nStep 3: The astronaut''s mass remains 80 kg.","steps":["Step 1: Mass measures the object''s matter and inertia.","Step 2: The location changes gravitational field strength, not mass.","Step 3: The astronaut''s mass remains 80 kg."],"options":[],"conceptId":"physics_mass_weight_and_density_mass_and_weight","skillId":"physics_mass_weight_and_density","subskillId":"physics_mass_weight_and_density_q3","subject":"physics","chapter":"mass_weight_and_density","topic":"Mass and Weight"}', 2),
  (1488, 398, 'Calculate the weight of a 12 kg object where g = 9.8 N/kg.', 'text', 1, 'Use the gravitational field strength given in the question.', '{"why":"Weight is the product of mass and gravitational field strength.","sol":"Step 1: m = 12 kg and g = 9.8 N/kg.\nStep 2: W = 12 × 9.8.\nStep 3: W = 117.6 N.","steps":["Step 1: m = 12 kg and g = 9.8 N/kg.","Step 2: W = 12 × 9.8.","Step 3: W = 117.6 N."],"options":[],"conceptId":"physics_mass_weight_and_density_mass_and_weight","skillId":"physics_mass_weight_and_density","subskillId":"physics_mass_weight_and_density_q4","subject":"physics","chapter":"mass_weight_and_density","topic":"Mass and Weight"}', 3),
  (1489, 398, 'Which quantity is measured in newtons: mass or weight?', 'text', 1, 'One is a gravitational force; the other is measured in kilograms.', '{"why":"Weight is a force, while mass is measured in kilograms.","sol":"Step 1: Mass is measured in kilograms.\nStep 2: Weight is a gravitational force.\nStep 3: Force is measured in newtons.","steps":["Step 1: Mass is measured in kilograms.","Step 2: Weight is a gravitational force.","Step 3: Force is measured in newtons."],"options":[],"conceptId":"physics_mass_weight_and_density_mass_and_weight","skillId":"physics_mass_weight_and_density","subskillId":"physics_mass_weight_and_density_q5","subject":"physics","chapter":"mass_weight_and_density","topic":"Mass and Weight"}', 4),
  (1490, 399, 'An object has a mass of 4 kg and a weight of 39.2 N. Find the gravitational field strength.', 'text', 1, 'Divide weight by mass.', '{"why":"Gravitational field strength is the weight per unit mass.","sol":"Step 1: W = 39.2 N and m = 4 kg.\nStep 2: g = 39.2 ÷ 4.\nStep 3: g = 9.8 N/kg.","steps":["Step 1: W = 39.2 N and m = 4 kg.","Step 2: g = 39.2 ÷ 4.","Step 3: g = 9.8 N/kg."],"options":[],"conceptId":"physics_mass_weight_and_density_gravitational_field_strength","skillId":"physics_mass_weight_and_density","subskillId":"physics_mass_weight_and_density_q1","subject":"physics","chapter":"mass_weight_and_density","topic":"Gravitational Field Strength"}', 0),
  (1491, 399, 'Find the weight of a 15 kg object in a gravitational field of 4 N/kg.', 'text', 1, 'Use the relationship between weight, mass and field strength.', '{"why":"Weight is mass multiplied by gravitational field strength.","sol":"Step 1: m = 15 kg and g = 4 N/kg.\nStep 2: W = 15 × 4.\nStep 3: W = 60 N.","steps":["Step 1: m = 15 kg and g = 4 N/kg.","Step 2: W = 15 × 4.","Step 3: W = 60 N."],"options":[],"conceptId":"physics_mass_weight_and_density_gravitational_field_strength","skillId":"physics_mass_weight_and_density","subskillId":"physics_mass_weight_and_density_q2","subject":"physics","chapter":"mass_weight_and_density","topic":"Gravitational Field Strength"}', 1),
  (1492, 399, 'An object weighs 36 N in a field where g = 6 N/kg. Find its mass.', 'text', 1, 'Rearrange W = mg.', '{"why":"Mass equals weight divided by gravitational field strength.","sol":"Step 1: W = 36 N and g = 6 N/kg.\nStep 2: m = 36 ÷ 6.\nStep 3: m = 6 kg.","steps":["Step 1: W = 36 N and g = 6 N/kg.","Step 2: m = 36 ÷ 6.","Step 3: m = 6 kg."],"options":[],"conceptId":"physics_mass_weight_and_density_gravitational_field_strength","skillId":"physics_mass_weight_and_density","subskillId":"physics_mass_weight_and_density_q3","subject":"physics","chapter":"mass_weight_and_density","topic":"Gravitational Field Strength"}', 2),
  (1493, 399, 'Why does the weight of an object change when it is moved from Earth to the Moon, while its mass remains unchanged?', 'text', 1, 'Compare the meaning of mass with the meaning of weight.', '{"why":"Changing the gravitational field changes the gravitational force on the object without changing its mass.","sol":"Step 1: Mass is a measure of matter and inertia.\nStep 2: Weight is gravitational force, W = mg.\nStep 3: The Moon has a different gravitational field strength, so weight changes but mass does not.","steps":["Step 1: Mass is a measure of matter and inertia.","Step 2: Weight is gravitational force, W = mg.","Step 3: The Moon has a different gravitational field strength, so weight changes but mass does not."],"options":[],"conceptId":"physics_mass_weight_and_density_gravitational_field_strength","skillId":"physics_mass_weight_and_density","subskillId":"physics_mass_weight_and_density_q4","subject":"physics","chapter":"mass_weight_and_density","topic":"Gravitational Field Strength"}', 3),
  (1494, 399, 'An object has a mass of 2 kg and a weight of 19.6 N. What is its gravitational field strength?', 'text', 1, 'Calculate weight per unit mass.', '{"why":"The gravitational field strength is found by dividing weight by mass.","sol":"Step 1: W = 19.6 N and m = 2 kg.\nStep 2: g = 19.6 ÷ 2.\nStep 3: g = 9.8 N/kg.","steps":["Step 1: W = 19.6 N and m = 2 kg.","Step 2: g = 19.6 ÷ 2.","Step 3: g = 9.8 N/kg."],"options":[],"conceptId":"physics_mass_weight_and_density_gravitational_field_strength","skillId":"physics_mass_weight_and_density","subskillId":"physics_mass_weight_and_density_q5","subject":"physics","chapter":"mass_weight_and_density","topic":"Gravitational Field Strength"}', 4),
  (1495, 400, 'Calculate the weight of a 9 kg object where g = 10 N/kg.', 'text', 1, 'Multiply mass by gravitational field strength.', '{"why":"Weight equals mass multiplied by gravitational field strength.","sol":"Step 1: m = 9 kg and g = 10 N/kg.\nStep 2: W = 9 × 10.\nStep 3: W = 90 N.","steps":["Step 1: m = 9 kg and g = 10 N/kg.","Step 2: W = 9 × 10.","Step 3: W = 90 N."],"options":[],"conceptId":"physics_mass_weight_and_density_calculating_weight","skillId":"physics_mass_weight_and_density","subskillId":"physics_mass_weight_and_density_q1","subject":"physics","chapter":"mass_weight_and_density","topic":"Calculating Weight"}', 0),
  (1496, 400, 'A 2.5 kg object is on Earth where g = 9.8 N/kg. Find its weight.', 'text', 1, 'Use the exact field strength given.', '{"why":"Multiplying 2.5 kg by 9.8 N/kg gives 24.5 N.","sol":"Step 1: m = 2.5 kg and g = 9.8 N/kg.\nStep 2: W = 2.5 × 9.8.\nStep 3: W = 24.5 N.","steps":["Step 1: m = 2.5 kg and g = 9.8 N/kg.","Step 2: W = 2.5 × 9.8.","Step 3: W = 24.5 N."],"options":[],"conceptId":"physics_mass_weight_and_density_calculating_weight","skillId":"physics_mass_weight_and_density","subskillId":"physics_mass_weight_and_density_q2","subject":"physics","chapter":"mass_weight_and_density","topic":"Calculating Weight"}', 1),
  (1497, 400, 'A parcel has a mass of 600 g. Calculate its weight where g = 10 N/kg.', 'text', 1, 'Convert grams to kilograms before multiplying.', '{"why":"A mass of 600 g is 0.6 kg, which weighs 6 N at 10 N/kg.","sol":"Step 1: Convert 600 g to kilograms: 600 ÷ 1,000 = 0.6 kg.\nStep 2: W = 0.6 × 10.\nStep 3: W = 6 N.","steps":["Step 1: Convert 600 g to kilograms: 600 ÷ 1,000 = 0.6 kg.","Step 2: W = 0.6 × 10.","Step 3: W = 6 N."],"options":[],"conceptId":"physics_mass_weight_and_density_calculating_weight","skillId":"physics_mass_weight_and_density","subskillId":"physics_mass_weight_and_density_q3","subject":"physics","chapter":"mass_weight_and_density","topic":"Calculating Weight"}', 2),
  (1498, 400, 'An object weighs 147 N where g = 9.8 N/kg. What is its mass?', 'text', 1, 'Rearrange W = mg to find m.', '{"why":"Mass is obtained by dividing weight by gravitational field strength.","sol":"Step 1: W = 147 N and g = 9.8 N/kg.\nStep 2: m = 147 ÷ 9.8.\nStep 3: m = 15 kg.","steps":["Step 1: W = 147 N and g = 9.8 N/kg.","Step 2: m = 147 ÷ 9.8.","Step 3: m = 15 kg."],"options":[],"conceptId":"physics_mass_weight_and_density_calculating_weight","skillId":"physics_mass_weight_and_density","subskillId":"physics_mass_weight_and_density_q4","subject":"physics","chapter":"mass_weight_and_density","topic":"Calculating Weight"}', 3),
  (1499, 400, 'A 4 kg object is moved from a location where g = 10 N/kg to one where g = 2 N/kg. What is its weight at the second location?', 'text', 1, 'Use the gravitational field strength at the second location.', '{"why":"Weight depends on the local gravitational field strength.","sol":"Step 1: Mass = 4 kg.\nStep 2: Second-location field strength = 2 N/kg.\nStep 3: W = 4 × 2 = 8 N.","steps":["Step 1: Mass = 4 kg.","Step 2: Second-location field strength = 2 N/kg.","Step 3: W = 4 × 2 = 8 N."],"options":[],"conceptId":"physics_mass_weight_and_density_calculating_weight","skillId":"physics_mass_weight_and_density","subskillId":"physics_mass_weight_and_density_q5","subject":"physics","chapter":"mass_weight_and_density","topic":"Calculating Weight"}', 4),
  (1500, 401, 'A substance has a mass of 240 kg and a volume of 0.08 m³. Calculate its density.', 'text', 1, 'Divide mass by volume.', '{"why":"Density is the mass contained in each unit of volume.","sol":"Step 1: m = 240 kg and V = 0.08 m³.\nStep 2: ρ = 240 ÷ 0.08.\nStep 3: ρ = 3,000 kg/m³.","steps":["Step 1: m = 240 kg and V = 0.08 m³.","Step 2: ρ = 240 ÷ 0.08.","Step 3: ρ = 3,000 kg/m³."],"options":[],"conceptId":"physics_mass_weight_and_density_density","skillId":"physics_mass_weight_and_density","subskillId":"physics_mass_weight_and_density_q1","subject":"physics","chapter":"mass_weight_and_density","topic":"Density"}', 0);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (1501, 401, 'A sample has a mass of 150 g and a volume of 50 cm³. What is its density?', 'text', 1, 'Keep the mass and volume units consistent.', '{"why":"Dividing grams by cubic centimetres gives density in g/cm³.","sol":"Step 1: Mass = 150 g and volume = 50 cm³.\nStep 2: Density = 150 ÷ 50.\nStep 3: Density = 3 g/cm³.","steps":["Step 1: Mass = 150 g and volume = 50 cm³.","Step 2: Density = 150 ÷ 50.","Step 3: Density = 3 g/cm³."],"options":[],"conceptId":"physics_mass_weight_and_density_density","skillId":"physics_mass_weight_and_density","subskillId":"physics_mass_weight_and_density_q2","subject":"physics","chapter":"mass_weight_and_density","topic":"Density"}', 1),
  (1502, 401, 'An object has a density of 8 kg/m³ and a volume of 3 m³. Find its mass.', 'text', 1, 'Rearrange ρ = m/V to make mass the subject.', '{"why":"Mass is the product of density and volume.","sol":"Step 1: ρ = 8 kg/m³ and V = 3 m³.\nStep 2: m = 8 × 3.\nStep 3: m = 24 kg.","steps":["Step 1: ρ = 8 kg/m³ and V = 3 m³.","Step 2: m = 8 × 3.","Step 3: m = 24 kg."],"options":[],"conceptId":"physics_mass_weight_and_density_density","skillId":"physics_mass_weight_and_density","subskillId":"physics_mass_weight_and_density_q3","subject":"physics","chapter":"mass_weight_and_density","topic":"Density"}', 2),
  (1503, 401, 'Two blocks have equal volumes. Block A has a mass of 4 kg and Block B has a mass of 7 kg. Which block has the greater density?', 'text', 1, 'Density is mass divided by volume. The volumes are equal.', '{"why":"With equal volumes, density increases with mass.","sol":"Step 1: Both blocks have the same volume.\nStep 2: Block B has the greater mass.\nStep 3: For equal volume, the block with greater mass has greater density.","steps":["Step 1: Both blocks have the same volume.","Step 2: Block B has the greater mass.","Step 3: For equal volume, the block with greater mass has greater density."],"options":[],"conceptId":"physics_mass_weight_and_density_density","skillId":"physics_mass_weight_and_density","subskillId":"physics_mass_weight_and_density_q4","subject":"physics","chapter":"mass_weight_and_density","topic":"Density"}', 3),
  (1504, 401, 'A material has a mass of 2 kg and a volume of 0.0005 m³. Calculate its density.', 'text', 1, 'Divide the mass by the volume, keeping track of the decimal places.', '{"why":"Dividing by 0.0005 gives 4,000 kg/m³.","sol":"Step 1: m = 2 kg and V = 0.0005 m³.\nStep 2: ρ = 2 ÷ 0.0005.\nStep 3: ρ = 4,000 kg/m³.","steps":["Step 1: m = 2 kg and V = 0.0005 m³.","Step 2: ρ = 2 ÷ 0.0005.","Step 3: ρ = 4,000 kg/m³."],"options":[],"conceptId":"physics_mass_weight_and_density_density","skillId":"physics_mass_weight_and_density","subskillId":"physics_mass_weight_and_density_q5","subject":"physics","chapter":"mass_weight_and_density","topic":"Density"}', 4),
  (1505, 402, 'A stone has a mass of 240 g and a volume of 80 cm³. Calculate its density.', 'text', 1, 'Density = mass ÷ volume.', '{"why":"Density measures mass per unit volume.","sol":"Step 1: Write the formula: ρ = m/V.\nStep 2: Substitute: ρ = 240/80.\nStep 3: Divide: ρ = 3 g/cm³.","steps":["Step 1: Write the formula: ρ = m/V.","Step 2: Substitute: ρ = 240/80.","Step 3: Divide: ρ = 3 g/cm³."],"options":[],"conceptId":"physics_mass_weight_and_density_calculating_density","skillId":"physics_mass_weight_and_density","subskillId":"physics_mass_weight_and_density_q1","subject":"physics","chapter":"mass_weight_and_density","topic":"Calculating Density"}', 0),
  (1506, 402, 'A material has a density of 4 g/cm³ and a volume of 15 cm³. Find its mass.', 'text', 1, 'Rearrange density = mass ÷ volume to make mass the subject.', '{"why":"Mass equals density multiplied by volume.","sol":"Step 1: Start with ρ = m/V.\nStep 2: Multiply both sides by V: m = ρV.\nStep 3: Substitute: m = 4 × 15 = 60 g.","steps":["Step 1: Start with ρ = m/V.","Step 2: Multiply both sides by V: m = ρV.","Step 3: Substitute: m = 4 × 15 = 60 g."],"options":[],"conceptId":"physics_mass_weight_and_density_calculating_density","skillId":"physics_mass_weight_and_density","subskillId":"physics_mass_weight_and_density_q2","subject":"physics","chapter":"mass_weight_and_density","topic":"Calculating Density"}', 1),
  (1507, 402, 'An object has a mass of 12 kg and a density of 3000 kg/m³. Calculate its volume.', 'text', 1, 'Volume = mass ÷ density.', '{"why":"Volume is obtained by dividing mass by density.","sol":"Step 1: Write V = m/ρ.\nStep 2: Substitute: V = 12/3000.\nStep 3: Calculate: V = 0.004 m³.","steps":["Step 1: Write V = m/ρ.","Step 2: Substitute: V = 12/3000.","Step 3: Calculate: V = 0.004 m³."],"options":[],"conceptId":"physics_mass_weight_and_density_calculating_density","skillId":"physics_mass_weight_and_density","subskillId":"physics_mass_weight_and_density_q3","subject":"physics","chapter":"mass_weight_and_density","topic":"Calculating Density"}', 2),
  (1508, 402, 'Convert 2.5 g/cm³ into kg/m³.', 'text', 1, 'Multiply a density in g/cm³ by 1000 to convert it to kg/m³.', '{"why":"The conversion factor between these density units is 1000.","sol":"Step 1: Write the conversion factor: 1 g/cm³ = 1000 kg/m³.\nStep 2: Multiply 2.5 by 1000.\nStep 3: The density is 2500 kg/m³.","steps":["Step 1: Write the conversion factor: 1 g/cm³ = 1000 kg/m³.","Step 2: Multiply 2.5 by 1000.","Step 3: The density is 2500 kg/m³."],"options":[],"conceptId":"physics_mass_weight_and_density_calculating_density","skillId":"physics_mass_weight_and_density","subskillId":"physics_mass_weight_and_density_q4","subject":"physics","chapter":"mass_weight_and_density","topic":"Calculating Density"}', 3),
  (1509, 402, 'A liquid has a mass of 900 g and a volume of 1.5 cm³. Calculate its density.', 'text', 1, 'Use mass divided by volume and retain the units.', '{"why":"The stated values give a density of 600 g/cm³. Always check that the supplied measurements are realistic.","sol":"Step 1: Write ρ = m/V.\nStep 2: Substitute: ρ = 900/1.5.\nStep 3: Calculate: ρ = 600 g/cm³.","steps":["Step 1: Write ρ = m/V.","Step 2: Substitute: ρ = 900/1.5.","Step 3: Calculate: ρ = 600 g/cm³."],"options":[],"conceptId":"physics_mass_weight_and_density_calculating_density","skillId":"physics_mass_weight_and_density","subskillId":"physics_mass_weight_and_density_q5","subject":"physics","chapter":"mass_weight_and_density","topic":"Calculating Density"}', 4),
  (1510, 403, 'A liquid has a density of 700 kg/m³. Calculate its relative density.', 'text', 1, 'Divide by the density of water, 1000 kg/m³.', '{"why":"Relative density compares a substance with water.","sol":"Step 1: Write RD = density of liquid ÷ density of water.\nStep 2: Substitute: RD = 700/1000.\nStep 3: Calculate: RD = 0.7.","steps":["Step 1: Write RD = density of liquid ÷ density of water.","Step 2: Substitute: RD = 700/1000.","Step 3: Calculate: RD = 0.7."],"options":[],"conceptId":"physics_mass_weight_and_density_relative_density","skillId":"physics_mass_weight_and_density","subskillId":"physics_mass_weight_and_density_q1","subject":"physics","chapter":"mass_weight_and_density","topic":"Relative Density"}', 0),
  (1511, 403, 'A solid has a density of 3.2 g/cm³. Find its relative density.', 'text', 1, 'Use water''s density as 1 g/cm³.', '{"why":"The densities are already expressed in the same unit.","sol":"Step 1: Write RD = 3.2 ÷ 1.\nStep 2: Calculate the ratio.\nStep 3: Relative density = 3.2.","steps":["Step 1: Write RD = 3.2 ÷ 1.","Step 2: Calculate the ratio.","Step 3: Relative density = 3.2."],"options":[],"conceptId":"physics_mass_weight_and_density_relative_density","skillId":"physics_mass_weight_and_density","subskillId":"physics_mass_weight_and_density_q2","subject":"physics","chapter":"mass_weight_and_density","topic":"Relative Density"}', 1),
  (1512, 403, 'A substance has a relative density of 0.6. What is its density in kg/m³?', 'text', 1, 'Density of substance = relative density × density of water.', '{"why":"Multiplying relative density by water''s density gives the substance''s density.","sol":"Step 1: Write ρs = RD × ρw.\nStep 2: Substitute: ρs = 0.6 × 1000.\nStep 3: Calculate: ρs = 600 kg/m³.","steps":["Step 1: Write ρs = RD × ρw.","Step 2: Substitute: ρs = 0.6 × 1000.","Step 3: Calculate: ρs = 600 kg/m³."],"options":[],"conceptId":"physics_mass_weight_and_density_relative_density","skillId":"physics_mass_weight_and_density","subskillId":"physics_mass_weight_and_density_q3","subject":"physics","chapter":"mass_weight_and_density","topic":"Relative Density"}', 2),
  (1513, 403, 'A substance has a density of 1200 kg/m³. Is its relative density greater than or less than 1?', 'text', 1, 'Compare 1200 kg/m³ with water''s 1000 kg/m³.', '{"why":"The substance is 1.2 times as dense as water.","sol":"Step 1: Compare the densities: 1200 is greater than 1000.\nStep 2: Calculate RD = 1200/1000.\nStep 3: RD = 1.2, which is greater than 1.","steps":["Step 1: Compare the densities: 1200 is greater than 1000.","Step 2: Calculate RD = 1200/1000.","Step 3: RD = 1.2, which is greater than 1."],"options":[],"conceptId":"physics_mass_weight_and_density_relative_density","skillId":"physics_mass_weight_and_density","subskillId":"physics_mass_weight_and_density_q4","subject":"physics","chapter":"mass_weight_and_density","topic":"Relative Density"}', 3),
  (1514, 403, 'Oil has a density of 0.8 g/cm³. Calculate its relative density using water''s density of 1 g/cm³.', 'text', 1, 'Divide the oil''s density by water''s density.', '{"why":"The oil is less dense than water, so its relative density is below 1.","sol":"Step 1: Write RD = 0.8/1.\nStep 2: Divide 0.8 by 1.\nStep 3: Relative density = 0.8.","steps":["Step 1: Write RD = 0.8/1.","Step 2: Divide 0.8 by 1.","Step 3: Relative density = 0.8."],"options":[],"conceptId":"physics_mass_weight_and_density_relative_density","skillId":"physics_mass_weight_and_density","subskillId":"physics_mass_weight_and_density_q5","subject":"physics","chapter":"mass_weight_and_density","topic":"Relative Density"}', 4),
  (1515, 404, 'What is the main role of friction between two surfaces that are sliding relative to each other?', 'text', 1, 'Think about how friction affects the sliding.', '{"why":"Friction is a contact force that resists relative sliding.","sol":"Step 1: Identify the relative sliding between the surfaces.\nStep 2: Friction acts to oppose that relative sliding.","steps":["Step 1: Identify the relative sliding between the surfaces.","Step 2: Friction acts to oppose that relative sliding."],"options":[],"conceptId":"physics_friction_and_resistance_causes_of_friction","skillId":"physics_friction_and_resistance","subskillId":"physics_friction_and_resistance_q1","subject":"physics","chapter":"friction_and_resistance","topic":"Causes of Friction"}', 0),
  (1516, 404, 'Why can tiny irregularities on two surfaces contribute to friction?', 'text', 1, 'Consider what happens when the surfaces are pressed together.', '{"why":"Microscopic surface structure contributes to resistance between contacting materials.","sol":"Step 1: Surfaces have microscopic irregularities.\nStep 2: These irregularities can interlock or resist movement.\nStep 3: Sliding then requires a force to overcome that resistance.","steps":["Step 1: Surfaces have microscopic irregularities.","Step 2: These irregularities can interlock or resist movement.","Step 3: Sliding then requires a force to overcome that resistance."],"options":[],"conceptId":"physics_friction_and_resistance_causes_of_friction","skillId":"physics_friction_and_resistance","subskillId":"physics_friction_and_resistance_q2","subject":"physics","chapter":"friction_and_resistance","topic":"Causes of Friction"}', 1),
  (1517, 404, 'A person presses two contacting surfaces together more strongly. What commonly happens to the friction between them?', 'text', 1, 'Think about how strongly the surfaces are pressed together.', '{"why":"The normal contact force often affects the frictional force.","sol":"Step 1: The pressing force increases.\nStep 2: The contact interactions usually become stronger.\nStep 3: The frictional force that can be supported commonly increases.","steps":["Step 1: The pressing force increases.","Step 2: The contact interactions usually become stronger.","Step 3: The frictional force that can be supported commonly increases."],"options":[],"conceptId":"physics_friction_and_resistance_causes_of_friction","skillId":"physics_friction_and_resistance","subskillId":"physics_friction_and_resistance_q3","subject":"physics","chapter":"friction_and_resistance","topic":"Causes of Friction"}', 2),
  (1518, 404, 'Can two surfaces that look smooth still produce friction?', 'text', 1, 'Think about the microscopic scale.', '{"why":"Friction can occur even between polished surfaces.","sol":"Step 1: Visible smoothness does not mean perfectly flat surfaces.\nStep 2: Microscopic irregularities and adhesion can still resist sliding.\nStep 3: Therefore, friction can still occur.","steps":["Step 1: Visible smoothness does not mean perfectly flat surfaces.","Step 2: Microscopic irregularities and adhesion can still resist sliding.","Step 3: Therefore, friction can still occur."],"options":[],"conceptId":"physics_friction_and_resistance_causes_of_friction","skillId":"physics_friction_and_resistance","subskillId":"physics_friction_and_resistance_q4","subject":"physics","chapter":"friction_and_resistance","topic":"Causes of Friction"}', 3),
  (1519, 404, 'A person walks forward without slipping. In which direction can friction from the ground act on the person''s foot during the push-off?', 'text', 1, 'Friction opposes slipping, not necessarily the person''s overall motion.', '{"why":"Friction opposes relative slipping at the foot-ground contact; it can propel a walker forward.","sol":"Step 1: The foot pushes backward against the ground.\nStep 2: The ground exerts a forward frictional force on the foot if it does not slip backward.\nStep 3: That forward force helps propel the person.","steps":["Step 1: The foot pushes backward against the ground.","Step 2: The ground exerts a forward frictional force on the foot if it does not slip backward.","Step 3: That forward force helps propel the person."],"options":[],"conceptId":"physics_friction_and_resistance_causes_of_friction","skillId":"physics_friction_and_resistance","subskillId":"physics_friction_and_resistance_q5","subject":"physics","chapter":"friction_and_resistance","topic":"Causes of Friction"}', 4),
  (1520, 405, 'A sliding box slows down on a rough floor when no forward force balances friction. What effect of friction explains this?', 'text', 1, 'Consider the direction of friction relative to the sliding.', '{"why":"Friction can reduce the kinetic energy of a moving object.","sol":"Step 1: The box is sliding across the floor.\nStep 2: Friction acts opposite to the relative sliding.\nStep 3: The unbalanced force reduces the box''s speed.","steps":["Step 1: The box is sliding across the floor.","Step 2: Friction acts opposite to the relative sliding.","Step 3: The unbalanced force reduces the box''s speed."],"options":[],"conceptId":"physics_friction_and_resistance_effects_of_friction","skillId":"physics_friction_and_resistance","subskillId":"physics_friction_and_resistance_q1","subject":"physics","chapter":"friction_and_resistance","topic":"Effects of Friction"}', 0),
  (1521, 405, 'Why do your hands become warmer when you rub them together?', 'text', 1, 'Think about energy transfer during friction.', '{"why":"Friction transfers energy into the internal energy of the contacting surfaces.","sol":"Step 1: The hands move against each other.\nStep 2: Friction acts at the contacting surfaces.\nStep 3: Some mechanical energy becomes internal energy, warming the hands.","steps":["Step 1: The hands move against each other.","Step 2: Friction acts at the contacting surfaces.","Step 3: Some mechanical energy becomes internal energy, warming the hands."],"options":[],"conceptId":"physics_friction_and_resistance_effects_of_friction","skillId":"physics_friction_and_resistance","subskillId":"physics_friction_and_resistance_q2","subject":"physics","chapter":"friction_and_resistance","topic":"Effects of Friction"}', 1),
  (1522, 405, 'What can happen to shoe soles after repeated use on rough ground?', 'text', 1, 'Consider the effect of repeated rubbing.', '{"why":"Friction can gradually damage or remove material from contacting surfaces.","sol":"Step 1: The soles repeatedly contact the ground.\nStep 2: Friction acts during movement.\nStep 3: The material gradually wears away.","steps":["Step 1: The soles repeatedly contact the ground.","Step 2: Friction acts during movement.","Step 3: The material gradually wears away."],"options":[],"conceptId":"physics_friction_and_resistance_effects_of_friction","skillId":"physics_friction_and_resistance","subskillId":"physics_friction_and_resistance_q3","subject":"physics","chapter":"friction_and_resistance","topic":"Effects of Friction"}', 2),
  (1523, 405, 'Why is friction between tyres and the road important when a vehicle brakes?', 'text', 1, 'Consider how the tyre interacts with the road surface.', '{"why":"Tyre-road friction is important for effective braking and control.","sol":"Step 1: The tyre must interact with the road without excessive slipping.\nStep 2: Friction allows the road to exert a braking force on the tyre.\nStep 3: That force helps reduce the vehicle''s speed.","steps":["Step 1: The tyre must interact with the road without excessive slipping.","Step 2: Friction allows the road to exert a braking force on the tyre.","Step 3: That force helps reduce the vehicle''s speed."],"options":[],"conceptId":"physics_friction_and_resistance_effects_of_friction","skillId":"physics_friction_and_resistance","subskillId":"physics_friction_and_resistance_q4","subject":"physics","chapter":"friction_and_resistance","topic":"Effects of Friction"}', 3),
  (1524, 405, 'Name two unwanted effects of friction in moving machinery.', 'text', 1, 'Think about temperature and the condition of machine parts.', '{"why":"Friction can waste useful mechanical energy and wear machine components.","sol":"Step 1: Friction can transfer mechanical energy into internal energy.\nStep 2: It can also wear contacting surfaces.\nStep 3: Therefore, heating and wear are two unwanted effects.","steps":["Step 1: Friction can transfer mechanical energy into internal energy.","Step 2: It can also wear contacting surfaces.","Step 3: Therefore, heating and wear are two unwanted effects."],"options":[],"conceptId":"physics_friction_and_resistance_effects_of_friction","skillId":"physics_friction_and_resistance","subskillId":"physics_friction_and_resistance_q5","subject":"physics","chapter":"friction_and_resistance","topic":"Effects of Friction"}', 4),
  (1525, 406, 'Why is friction between shoes and the ground an advantage when walking?', 'text', 1, 'Think about what would happen if your feet slipped backward.', '{"why":"Foot-ground friction is important for safe walking.","sol":"Step 1: Walking requires the feet to push against the ground.\nStep 2: Friction helps prevent unwanted slipping.\nStep 3: The ground can exert a useful force on the feet.","steps":["Step 1: Walking requires the feet to push against the ground.","Step 2: Friction helps prevent unwanted slipping.","Step 3: The ground can exert a useful force on the feet."],"options":[],"conceptId":"physics_friction_and_resistance_advantages_and_disadvantages_of_friction","skillId":"physics_friction_and_resistance","subskillId":"physics_friction_and_resistance_q1","subject":"physics","chapter":"friction_and_resistance","topic":"Advantages and Disadvantages of Friction"}', 0),
  (1526, 406, 'Give one disadvantage of friction in a machine.', 'text', 1, 'Think about energy and machine parts.', '{"why":"Unwanted friction can waste energy and damage components.","sol":"Step 1: Moving machine parts can rub against one another.\nStep 2: Friction can cause heating or wear.\nStep 3: Either is a disadvantage when unwanted.","steps":["Step 1: Moving machine parts can rub against one another.","Step 2: Friction can cause heating or wear.","Step 3: Either is a disadvantage when unwanted."],"options":[],"conceptId":"physics_friction_and_resistance_advantages_and_disadvantages_of_friction","skillId":"physics_friction_and_resistance","subskillId":"physics_friction_and_resistance_q2","subject":"physics","chapter":"friction_and_resistance","topic":"Advantages and Disadvantages of Friction"}', 1),
  (1527, 406, 'Why is friction useful in a bicycle''s braking system?', 'text', 1, 'What does the braking system need to do to the bicycle''s motion?', '{"why":"Friction provides the force needed for effective braking.","sol":"Step 1: The brake pad contacts the braking surface.\nStep 2: Friction opposes the relative motion at the braking contact.\nStep 3: Energy is transferred and the bicycle slows down.","steps":["Step 1: The brake pad contacts the braking surface.","Step 2: Friction opposes the relative motion at the braking contact.","Step 3: Energy is transferred and the bicycle slows down."],"options":[],"conceptId":"physics_friction_and_resistance_advantages_and_disadvantages_of_friction","skillId":"physics_friction_and_resistance","subskillId":"physics_friction_and_resistance_q3","subject":"physics","chapter":"friction_and_resistance","topic":"Advantages and Disadvantages of Friction"}', 2),
  (1528, 406, 'A machine wastes energy because its moving parts rub together. Is friction acting as an advantage or a disadvantage in this situation?', 'text', 1, 'Focus on whether the friction helps the intended task.', '{"why":"Unwanted friction reduces the useful output of a machine.","sol":"Step 1: The machine is losing useful mechanical energy.\nStep 2: The rubbing is unwanted.\nStep 3: Therefore, friction is a disadvantage in this situation.","steps":["Step 1: The machine is losing useful mechanical energy.","Step 2: The rubbing is unwanted.","Step 3: Therefore, friction is a disadvantage in this situation."],"options":[],"conceptId":"physics_friction_and_resistance_advantages_and_disadvantages_of_friction","skillId":"physics_friction_and_resistance","subskillId":"physics_friction_and_resistance_q4","subject":"physics","chapter":"friction_and_resistance","topic":"Advantages and Disadvantages of Friction"}', 3),
  (1529, 406, 'Why can friction be both an advantage and a disadvantage?', 'text', 1, 'Compare walking with rubbing machine parts.', '{"why":"Friction''s usefulness depends on the context.","sol":"Step 1: Friction provides useful grip for walking and braking.\nStep 2: It can also cause wear, heating and energy loss in machinery.\nStep 3: Its value depends on whether the effect is useful or unwanted.","steps":["Step 1: Friction provides useful grip for walking and braking.","Step 2: It can also cause wear, heating and energy loss in machinery.","Step 3: Its value depends on whether the effect is useful or unwanted."],"options":[],"conceptId":"physics_friction_and_resistance_advantages_and_disadvantages_of_friction","skillId":"physics_friction_and_resistance","subskillId":"physics_friction_and_resistance_q5","subject":"physics","chapter":"friction_and_resistance","topic":"Advantages and Disadvantages of Friction"}', 4),
  (1530, 407, 'Why is oil applied between moving parts of a machine?', 'text', 1, 'Think about direct rubbing between the surfaces.', '{"why":"Lubricants reduce friction by separating surfaces and changing their contact conditions.","sol":"Step 1: Moving parts can rub against one another.\nStep 2: Oil forms a lubricating layer between the surfaces.\nStep 3: This reduces direct rubbing and unwanted friction.","steps":["Step 1: Moving parts can rub against one another.","Step 2: Oil forms a lubricating layer between the surfaces.","Step 3: This reduces direct rubbing and unwanted friction."],"options":[],"conceptId":"physics_friction_and_resistance_reducing_and_increasing_friction","skillId":"physics_friction_and_resistance","subskillId":"physics_friction_and_resistance_q1","subject":"physics","chapter":"friction_and_resistance","topic":"Reducing and Increasing Friction"}', 0),
  (1531, 407, 'How can ball bearings reduce resistance in a rotating wheel?', 'text', 1, 'Compare rolling with sliding.', '{"why":"Rolling elements reduce friction in many rotating mechanisms.","sol":"Step 1: Without suitable bearings, surfaces may slide against each other.\nStep 2: Ball bearings allow rolling at the bearing contact.\nStep 3: Rolling often reduces resistance compared with sliding.","steps":["Step 1: Without suitable bearings, surfaces may slide against each other.","Step 2: Ball bearings allow rolling at the bearing contact.","Step 3: Rolling often reduces resistance compared with sliding."],"options":[],"conceptId":"physics_friction_and_resistance_reducing_and_increasing_friction","skillId":"physics_friction_and_resistance","subskillId":"physics_friction_and_resistance_q2","subject":"physics","chapter":"friction_and_resistance","topic":"Reducing and Increasing Friction"}', 1),
  (1532, 407, 'Which feature of a tyre can help maintain grip and channel water away on a wet road?', 'text', 1, 'Look at the patterned surface of the tyre.', '{"why":"Tread patterns help tyres interact with road surfaces, especially in wet conditions.","sol":"Step 1: Tyres have patterned grooves.\nStep 2: The grooves help manage water at the contact area.\nStep 3: Suitable tread design can help maintain grip in wet conditions.","steps":["Step 1: Tyres have patterned grooves.","Step 2: The grooves help manage water at the contact area.","Step 3: Suitable tread design can help maintain grip in wet conditions."],"options":[],"conceptId":"physics_friction_and_resistance_reducing_and_increasing_friction","skillId":"physics_friction_and_resistance","subskillId":"physics_friction_and_resistance_q3","subject":"physics","chapter":"friction_and_resistance","topic":"Reducing and Increasing Friction"}', 2),
  (1533, 407, 'Why are streamlined shapes used for objects moving quickly through air?', 'text', 1, 'Air is a fluid that resists movement through it.', '{"why":"Streamlining reduces the resistance from moving through a fluid.","sol":"Step 1: An object moving through air experiences air resistance.\nStep 2: A suitable streamlined shape reduces the disturbance and drag.\nStep 3: Less force may be needed to maintain its motion at a given speed.","steps":["Step 1: An object moving through air experiences air resistance.","Step 2: A suitable streamlined shape reduces the disturbance and drag.","Step 3: Less force may be needed to maintain its motion at a given speed."],"options":[],"conceptId":"physics_friction_and_resistance_reducing_and_increasing_friction","skillId":"physics_friction_and_resistance","subskillId":"physics_friction_and_resistance_q4","subject":"physics","chapter":"friction_and_resistance","topic":"Reducing and Increasing Friction"}', 3),
  (1534, 407, 'A person needs more grip when walking on a slippery surface. Should the contact be made more slippery or more grippy?', 'text', 1, 'The goal is to prevent unwanted slipping.', '{"why":"Increasing useful friction helps prevent unwanted slipping.","sol":"Step 1: Identify the goal: prevent slipping.\nStep 2: Preventing slipping requires sufficient friction.\nStep 3: A suitable high-grip sole or surface can help increase traction.","steps":["Step 1: Identify the goal: prevent slipping.","Step 2: Preventing slipping requires sufficient friction.","Step 3: A suitable high-grip sole or surface can help increase traction."],"options":[],"conceptId":"physics_friction_and_resistance_reducing_and_increasing_friction","skillId":"physics_friction_and_resistance","subskillId":"physics_friction_and_resistance_q5","subject":"physics","chapter":"friction_and_resistance","topic":"Reducing and Increasing Friction"}', 4),
  (1535, 408, 'In which direction does air resistance act on an object moving downward through still air?', 'text', 1, 'Drag opposes motion relative to the air.', '{"why":"Drag acts opposite to motion relative to the surrounding fluid.","sol":"Step 1: The object moves downward relative to the air.\nStep 2: Air resistance opposes that motion.\nStep 3: Therefore, the drag force acts upward.","steps":["Step 1: The object moves downward relative to the air.","Step 2: Air resistance opposes that motion.","Step 3: Therefore, the drag force acts upward."],"options":[],"conceptId":"physics_friction_and_resistance_air_resistance_and_terminal_velocity","skillId":"physics_friction_and_resistance","subskillId":"physics_friction_and_resistance_q1","subject":"physics","chapter":"friction_and_resistance","topic":"Air Resistance and Terminal Velocity"}', 0),
  (1536, 408, 'A falling object has weight 30 N downward and air resistance 10 N upward. Ignore buoyancy. Calculate the resultant force.', 'text', 1, 'Subtract the upward force from the downward force.', '{"why":"The forces are opposite, so subtract their magnitudes.","sol":"Step 1: Weight acts downward: 30 N.\nStep 2: Air resistance acts upward: 10 N.\nStep 3: Resultant force = 30 − 10 = 20 N downward.","steps":["Step 1: Weight acts downward: 30 N.","Step 2: Air resistance acts upward: 10 N.","Step 3: Resultant force = 30 − 10 = 20 N downward."],"options":[],"conceptId":"physics_friction_and_resistance_air_resistance_and_terminal_velocity","skillId":"physics_friction_and_resistance","subskillId":"physics_friction_and_resistance_q2","subject":"physics","chapter":"friction_and_resistance","topic":"Air Resistance and Terminal Velocity"}', 1),
  (1537, 408, 'A falling object reaches terminal velocity. What is its acceleration?', 'text', 1, 'At terminal velocity, the resultant force is zero.', '{"why":"Balanced forces produce zero acceleration.","sol":"Step 1: The object''s weight is balanced by the upward forces.\nStep 2: The resultant force is zero.\nStep 3: By Newton''s second law, acceleration is zero.","steps":["Step 1: The object''s weight is balanced by the upward forces.","Step 2: The resultant force is zero.","Step 3: By Newton''s second law, acceleration is zero."],"options":[],"conceptId":"physics_friction_and_resistance_air_resistance_and_terminal_velocity","skillId":"physics_friction_and_resistance","subskillId":"physics_friction_and_resistance_q3","subject":"physics","chapter":"friction_and_resistance","topic":"Air Resistance and Terminal Velocity"}', 2),
  (1538, 408, 'Why does air resistance on a falling object commonly increase as it speeds up?', 'text', 1, 'Think about how fast the object moves relative to the air.', '{"why":"Increasing drag reduces the resultant force and can lead to terminal velocity.","sol":"Step 1: The object''s speed through the air increases.\nStep 2: The interaction with the surrounding air becomes stronger.\nStep 3: Drag commonly increases with speed.","steps":["Step 1: The object''s speed through the air increases.","Step 2: The interaction with the surrounding air becomes stronger.","Step 3: Drag commonly increases with speed."],"options":[],"conceptId":"physics_friction_and_resistance_air_resistance_and_terminal_velocity","skillId":"physics_friction_and_resistance","subskillId":"physics_friction_and_resistance_q4","subject":"physics","chapter":"friction_and_resistance","topic":"Air Resistance and Terminal Velocity"}', 3),
  (1539, 408, 'Why does opening a parachute reduce a falling person''s speed?', 'text', 1, 'Consider what happens to the area interacting with the air.', '{"why":"A parachute increases drag, reducing the speed of descent.","sol":"Step 1: The parachute opens and greatly increases the area exposed to airflow.\nStep 2: Air resistance increases sharply.\nStep 3: The upward drag can exceed weight temporarily, causing the person to slow down.","steps":["Step 1: The parachute opens and greatly increases the area exposed to airflow.","Step 2: Air resistance increases sharply.","Step 3: The upward drag can exceed weight temporarily, causing the person to slow down."],"options":[],"conceptId":"physics_friction_and_resistance_air_resistance_and_terminal_velocity","skillId":"physics_friction_and_resistance","subskillId":"physics_friction_and_resistance_q5","subject":"physics","chapter":"friction_and_resistance","topic":"Air Resistance and Terminal Velocity"}', 4),
  (1540, 409, 'A spring returns to its original length after a small load is removed. What type of deformation has it undergone?', 'text', 1, 'Think about whether the spring recovers its original shape.', '{"why":"An elastic material returns to its original shape when the deforming force is removed within the elastic range.","sol":"Step 1: The spring changes length while loaded.\nStep 2: The load is removed.\nStep 3: The spring returns to its original length, showing elastic deformation.","steps":["Step 1: The spring changes length while loaded.","Step 2: The load is removed.","Step 3: The spring returns to its original length, showing elastic deformation."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_elasticity_and_plasticity","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q1","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Elasticity and Plasticity"}', 0),
  (1541, 409, 'A piece of metal remains bent after the force that bent it is removed. What type of deformation has occurred?', 'text', 1, 'Check whether the original shape returns.', '{"why":"Plastic deformation is not fully reversed when the force is removed.","sol":"Step 1: The metal is bent by a force.\nStep 2: The force is removed.\nStep 3: The metal remains bent, indicating permanent deformation.","steps":["Step 1: The metal is bent by a force.","Step 2: The force is removed.","Step 3: The metal remains bent, indicating permanent deformation."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_elasticity_and_plasticity","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q2","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Elasticity and Plasticity"}', 1),
  (1542, 409, 'Does elasticity mean a material must be soft?', 'text', 1, 'Focus on recovery, not how much force is needed to deform the material.', '{"why":"Elasticity and stiffness are different mechanical properties.","sol":"Step 1: Elasticity describes whether a material recovers its original shape.\nStep 2: Softness describes how easily a material may be deformed.\nStep 3: These properties are not the same.","steps":["Step 1: Elasticity describes whether a material recovers its original shape.","Step 2: Softness describes how easily a material may be deformed.","Step 3: These properties are not the same."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_elasticity_and_plasticity","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q3","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Elasticity and Plasticity"}', 2),
  (1543, 409, 'What may happen to a spring if it is stretched beyond its elastic limit?', 'text', 1, 'Consider whether it can recover its original length.', '{"why":"Beyond the elastic limit, permanent deformation may occur.","sol":"Step 1: The spring is stretched too far.\nStep 2: Its deformation may no longer be fully reversible.\nStep 3: It may remain permanently extended or become damaged.","steps":["Step 1: The spring is stretched too far.","Step 2: Its deformation may no longer be fully reversible.","Step 3: It may remain permanently extended or become damaged."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_elasticity_and_plasticity","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q4","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Elasticity and Plasticity"}', 3),
  (1544, 409, 'A material is stretched and remains longer after the load is removed. Is the remaining extension elastic or plastic?', 'text', 1, 'Focus on what remains after unloading.', '{"why":"Plastic deformation is the part of deformation that remains after unloading.","sol":"Step 1: The load is removed.\nStep 2: The material does not fully recover its original length.\nStep 3: The remaining deformation is plastic.","steps":["Step 1: The load is removed.","Step 2: The material does not fully recover its original length.","Step 3: The remaining deformation is plastic."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_elasticity_and_plasticity","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q5","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Elasticity and Plasticity"}', 4),
  (1545, 410, 'A spring has a spring constant of 100 N/m and is extended by 0.08 m. Calculate the applied force.', 'text', 1, 'Use F = ke.', '{"why":"Within the elastic range, force equals spring constant multiplied by extension.","sol":"Step 1: Write F = ke.\nStep 2: Substitute F = 100 × 0.08.\nStep 3: Calculate F = 8 N.","steps":["Step 1: Write F = ke.","Step 2: Substitute F = 100 × 0.08.","Step 3: Calculate F = 8 N."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_hooke_s_law","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q1","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Hooke''s Law"}', 0),
  (1546, 410, 'A spring extends by 0.04 m when a force of 20 N is applied. Calculate its spring constant.', 'text', 1, 'Rearrange F = ke to make k the subject.', '{"why":"The spring constant measures force required per unit extension.","sol":"Step 1: Write k = F/e.\nStep 2: Substitute k = 20/0.04.\nStep 3: Calculate k = 500 N/m.","steps":["Step 1: Write k = F/e.","Step 2: Substitute k = 20/0.04.","Step 3: Calculate k = 500 N/m."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_hooke_s_law","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q2","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Hooke''s Law"}', 1),
  (1547, 410, 'A spring has a spring constant of 250 N/m. What extension results from a force of 5 N?', 'text', 1, 'Use e = F/k.', '{"why":"Extension equals force divided by spring constant.","sol":"Step 1: Write e = F/k.\nStep 2: Substitute e = 5/250.\nStep 3: Calculate e = 0.02 m.","steps":["Step 1: Write e = F/k.","Step 2: Substitute e = 5/250.","Step 3: Calculate e = 0.02 m."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_hooke_s_law","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q3","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Hooke''s Law"}', 2),
  (1548, 410, 'A spring extends by 3 cm under a force of 6 N. Calculate its spring constant in N/m.', 'text', 1, 'Convert 3 cm to metres before calculating k = F/e.', '{"why":"Consistent SI units are needed for the spring constant in N/m.","sol":"Step 1: Convert 3 cm to 0.03 m.\nStep 2: Write k = F/e = 6/0.03.\nStep 3: Calculate k = 200 N/m.","steps":["Step 1: Convert 3 cm to 0.03 m.","Step 2: Write k = F/e = 6/0.03.","Step 3: Calculate k = 200 N/m."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_hooke_s_law","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q4","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Hooke''s Law"}', 3),
  (1549, 410, 'A spring''s extension doubles while it remains within the range where Hooke''s law applies. What happens to the applied force?', 'text', 1, 'Force and extension are directly proportional under Hooke''s law.', '{"why":"For a constant spring constant, force is directly proportional to extension.","sol":"Step 1: The spring constant remains unchanged.\nStep 2: Hooke''s law states F = ke.\nStep 3: Doubling extension doubles the force.","steps":["Step 1: The spring constant remains unchanged.","Step 2: Hooke''s law states F = ke.","Step 3: Doubling extension doubles the force."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_hooke_s_law","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q5","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Hooke''s Law"}', 4),
  (1550, 410, 'State Hooke''s law.', 'text', 1, 'Describe the relationship between applied force and extension.', '{"why":"Hooke''s law applies only while the force-extension relationship remains proportional.","sol":"Step 1: Identify the two quantities: force and extension.\nStep 2: State their relationship.\nStep 3: Include the condition under which it holds.","steps":["Step 1: Identify the two quantities: force and extension.","Step 2: State their relationship.","Step 3: Include the condition under which it holds."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_hooke_s_law","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q6","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Hooke''s Law"}', 5),
  (1551, 410, 'A spring has a spring constant of 100 N/m. Find the force required to extend it by 0.03 m within its proportional range.', 'text', 1, 'Use F = kx.', '{"why":"F = 100 N/m × 0.03 m = 3 N.","sol":"Step 1: F = 100 × 0.03.\nStep 2: F = 3 N.","steps":["Step 1: F = 100 × 0.03.","Step 2: F = 3 N."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_hooke_s_law","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q7","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Hooke''s Law"}', 6),
  (1552, 410, 'A force of 12 N produces an extension of 0.06 m. Calculate the spring constant.', 'text', 1, 'Rearrange F = kx to make k the subject.', '{"why":"12 ÷ 0.06 = 200 N/m.","sol":"Step 1: k = 12/0.06.\nStep 2: k = 200 N/m.","steps":["Step 1: k = 12/0.06.","Step 2: k = 200 N/m."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_hooke_s_law","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q8","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Hooke''s Law"}', 7),
  (1553, 410, 'A spring extends by 0.02 m under a force of 4 N. Assuming Hooke''s law applies, what extension would a force of 10 N produce?', 'text', 1, 'Extension is proportional to force, so compare the force ratio.', '{"why":"The force increases by a factor of 2.5, so the extension also increases by that factor.","sol":"Step 1: Force ratio = 10/4 = 2.5.\nStep 2: New extension = 0.02 × 2.5.\nStep 3: New extension = 0.05 m.","steps":["Step 1: Force ratio = 10/4 = 2.5.","Step 2: New extension = 0.02 × 2.5.","Step 3: New extension = 0.05 m."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_hooke_s_law","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q9","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Hooke''s Law"}', 8),
  (1554, 410, 'What happens to the direct proportional relationship in Hooke''s law when the limit of proportionality is exceeded?', 'text', 1, 'Consider whether a graph of force against extension remains a straight line through the origin.', '{"why":"The material may continue to extend, but force and extension no longer follow Hooke''s law.","sol":"Step 1: Hooke''s law requires direct proportionality.\nStep 2: Beyond the limit of proportionality, that relationship no longer holds.\nStep 3: Extension is no longer directly proportional to force.","steps":["Step 1: Hooke''s law requires direct proportionality.","Step 2: Beyond the limit of proportionality, that relationship no longer holds.","Step 3: Extension is no longer directly proportional to force."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_hooke_s_law","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q10","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Hooke''s Law"}', 9),
  (1555, 411, 'A force of 200 N acts on a cross-sectional area of 0.004 m². Calculate the stress.', 'text', 1, 'Stress = force ÷ cross-sectional area.', '{"why":"Stress is force per unit cross-sectional area.","sol":"Step 1: Write stress = F/A.\nStep 2: Substitute stress = 200/0.004.\nStep 3: Calculate stress = 50,000 Pa.","steps":["Step 1: Write stress = F/A.","Step 2: Substitute stress = 200/0.004.","Step 3: Calculate stress = 50,000 Pa."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_stress_and_strain","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q1","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Stress and Strain"}', 0),
  (1556, 411, 'A wire of original length 1.5 m extends by 0.003 m. Calculate the tensile strain.', 'text', 1, 'Divide extension by original length.', '{"why":"Strain measures extension relative to the original length.","sol":"Step 1: Write strain = extension/original length.\nStep 2: Substitute strain = 0.003/1.5.\nStep 3: Calculate strain = 0.002.","steps":["Step 1: Write strain = extension/original length.","Step 2: Substitute strain = 0.003/1.5.","Step 3: Calculate strain = 0.002."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_stress_and_strain","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q2","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Stress and Strain"}', 1),
  (1557, 411, 'A wire has an original length of 2 m and a tensile strain of 0.005. Calculate its extension.', 'text', 1, 'Extension = strain × original length.', '{"why":"Multiplying strain by original length gives the extension.","sol":"Step 1: Rearrange strain = extension/original length.\nStep 2: Extension = strain × original length.\nStep 3: Extension = 0.005 × 2 = 0.01 m.","steps":["Step 1: Rearrange strain = extension/original length.","Step 2: Extension = strain × original length.","Step 3: Extension = 0.005 × 2 = 0.01 m."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_stress_and_strain","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q3","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Stress and Strain"}', 2),
  (1558, 411, 'A force of 60 N produces a stress of 30,000 Pa in a wire. Calculate the cross-sectional area.', 'text', 1, 'Rearrange stress = force ÷ area.', '{"why":"Area is found by dividing force by stress.","sol":"Step 1: Write stress = F/A.\nStep 2: Rearrange: A = F/stress.\nStep 3: Substitute A = 60/30,000 = 0.002 m².","steps":["Step 1: Write stress = F/A.","Step 2: Rearrange: A = F/stress.","Step 3: Substitute A = 60/30,000 = 0.002 m²."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_stress_and_strain","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q4","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Stress and Strain"}', 3),
  (1559, 411, 'A wire''s original length is 4 m and its extension is 0.02 m. Calculate the strain.', 'text', 1, 'Use extension divided by original length.', '{"why":"Strain is the fractional change in length.","sol":"Step 1: Write strain = extension/original length.\nStep 2: Substitute strain = 0.02/4.\nStep 3: Calculate strain = 0.005.","steps":["Step 1: Write strain = extension/original length.","Step 2: Substitute strain = 0.02/4.","Step 3: Calculate strain = 0.005."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_stress_and_strain","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q5","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Stress and Strain"}', 4),
  (1560, 412, 'A material has stress 6 × 10⁷ Pa and strain 0.003. Calculate Young''s modulus.', 'text', 1, 'Young''s modulus = stress ÷ strain.', '{"why":"Young''s modulus is the ratio of stress to strain.","sol":"Step 1: Write E = stress/strain.\nStep 2: Substitute E = (6 × 10⁷)/0.003.\nStep 3: Calculate E = 2 × 10¹⁰ Pa.","steps":["Step 1: Write E = stress/strain.","Step 2: Substitute E = (6 × 10⁷)/0.003.","Step 3: Calculate E = 2 × 10¹⁰ Pa."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_young_s_modulus","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q1","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Young''s Modulus"}', 0),
  (1561, 412, 'A material has Young''s modulus 2 × 10¹¹ Pa and strain 0.002. Calculate the stress.', 'text', 1, 'Rearrange E = stress ÷ strain.', '{"why":"Stress equals Young''s modulus multiplied by strain.","sol":"Step 1: Write stress = E × strain.\nStep 2: Substitute stress = (2 × 10¹¹) × 0.002.\nStep 3: Calculate stress = 4 × 10⁸ Pa.","steps":["Step 1: Write stress = E × strain.","Step 2: Substitute stress = (2 × 10¹¹) × 0.002.","Step 3: Calculate stress = 4 × 10⁸ Pa."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_young_s_modulus","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q2","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Young''s Modulus"}', 1),
  (1562, 412, 'Two materials experience the same tensile stress. Material A has a greater Young''s modulus than material B. Which has the smaller strain in the linear elastic range?', 'text', 1, 'For a fixed stress, strain = stress ÷ Young''s modulus.', '{"why":"For a fixed stress, strain decreases as Young''s modulus increases.","sol":"Step 1: Both materials experience the same stress.\nStep 2: Strain is stress divided by Young''s modulus.\nStep 3: The larger modulus gives the smaller strain, so material A has smaller strain.","steps":["Step 1: Both materials experience the same stress.","Step 2: Strain is stress divided by Young''s modulus.","Step 3: The larger modulus gives the smaller strain, so material A has smaller strain."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_young_s_modulus","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q3","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Young''s Modulus"}', 2),
  (1563, 412, 'A wire has stress 1.5 × 10⁸ Pa and Young''s modulus 5 × 10¹⁰ Pa. Calculate the strain.', 'text', 1, 'Strain = stress ÷ Young''s modulus.', '{"why":"Strain is dimensionless and equals stress divided by Young''s modulus in the linear elastic range.","sol":"Step 1: Write strain = stress/E.\nStep 2: Substitute (1.5 × 10⁸)/(5 × 10¹⁰).\nStep 3: Calculate strain = 0.003.","steps":["Step 1: Write strain = stress/E.","Step 2: Substitute (1.5 × 10⁸)/(5 × 10¹⁰).","Step 3: Calculate strain = 0.003."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_young_s_modulus","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q4","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Young''s Modulus"}', 3),
  (1564, 412, 'What does a high Young''s modulus indicate about a material in the linear elastic range?', 'text', 1, 'Compare how much two materials deform under the same stress.', '{"why":"Young''s modulus measures the elastic stiffness of a material.","sol":"Step 1: Young''s modulus is stress divided by strain.\nStep 2: A larger modulus means less strain for a given stress.\nStep 3: Therefore, the material is stiffer under those conditions.","steps":["Step 1: Young''s modulus is stress divided by strain.","Step 2: A larger modulus means less strain for a given stress.","Step 3: Therefore, the material is stiffer under those conditions."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_young_s_modulus","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q5","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Young''s Modulus"}', 4),
  (1565, 412, 'A material has stress of 2 × 10⁶ Pa and strain of 0.001. Calculate Young''s modulus.', 'text', 1, 'Divide stress by strain.', '{"why":"2 × 10⁶ ÷ 0.001 = 2 × 10⁹ Pa.","sol":"Step 1: E = (2 × 10⁶)/0.001.\nStep 2: E = 2 × 10⁹ Pa.","steps":["Step 1: E = (2 × 10⁶)/0.001.","Step 2: E = 2 × 10⁹ Pa."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_young_s_modulus","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q6","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Young''s Modulus"}', 5),
  (1566, 412, 'A material has Young''s modulus 5 × 10⁹ Pa and strain 0.002. Calculate the stress.', 'text', 1, 'Rearrange E = stress ÷ strain.', '{"why":"Stress = 5 × 10⁹ Pa × 0.002 = 1 × 10⁷ Pa.","sol":"Step 1: Stress = 5 × 10⁹ × 0.002.\nStep 2: Stress = 1 × 10⁷ Pa.","steps":["Step 1: Stress = 5 × 10⁹ × 0.002.","Step 2: Stress = 1 × 10⁷ Pa."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_young_s_modulus","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q7","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Young''s Modulus"}', 6),
  (1567, 412, 'A material has stress of 9 × 10⁶ Pa and Young''s modulus of 3 × 10⁹ Pa. Find the strain.', 'text', 1, 'Rearrange E = stress ÷ strain.', '{"why":"9 × 10⁶ ÷ 3 × 10⁹ = 0.003.","sol":"Step 1: Strain = (9 × 10⁶)/(3 × 10⁹).\nStep 2: Strain = 3 × 10⁻³.\nStep 3: Strain = 0.003.","steps":["Step 1: Strain = (9 × 10⁶)/(3 × 10⁹).","Step 2: Strain = 3 × 10⁻³.","Step 3: Strain = 0.003."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_young_s_modulus","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q8","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Young''s Modulus"}', 7),
  (1568, 412, 'Material A has Young''s modulus 2 × 10¹¹ Pa, while material B has 7 × 10¹⁰ Pa. Which is stiffer in the proportional region?', 'text', 1, 'Compare their Young''s moduli.', '{"why":"A larger Young''s modulus means more stress is needed to produce the same strain.","sol":"Step 1: A has E = 2 × 10¹¹ Pa.\nStep 2: B has E = 7 × 10¹⁰ Pa.\nStep 3: A has the greater Young''s modulus.","steps":["Step 1: A has E = 2 × 10¹¹ Pa.","Step 2: B has E = 7 × 10¹⁰ Pa.","Step 3: A has the greater Young''s modulus."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_young_s_modulus","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q9","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Young''s Modulus"}', 8),
  (1569, 412, 'Why is Young''s modulus calculated only in the range where stress is directly proportional to strain?', 'text', 1, 'Consider the meaning of a constant ratio.', '{"why":"A constant stress-to-strain ratio defines the linear elastic behaviour used to determine Young''s modulus.","sol":"Step 1: Young''s modulus is stress divided by strain.\nStep 2: In the proportional region, the ratio is constant.\nStep 3: Outside that region, the ratio may change with the applied load.","steps":["Step 1: Young''s modulus is stress divided by strain.","Step 2: In the proportional region, the ratio is constant.","Step 3: Outside that region, the ratio may change with the applied load."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_young_s_modulus","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q10","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Young''s Modulus"}', 9),
  (1570, 413, 'What is elasticity?', 'text', 1, 'Consider what happens after a deforming force is removed.', '{"why":"An elastic material recovers its original shape when the deforming force is removed, provided its elastic limit has not been exceeded.","sol":"Step 1: A force changes an object''s shape or dimensions.\nStep 2: The force is removed.\nStep 3: An elastic material returns to its original shape and dimensions within its elastic range.","steps":["Step 1: A force changes an object''s shape or dimensions.","Step 2: The force is removed.","Step 3: An elastic material returns to its original shape and dimensions within its elastic range."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_elasticity","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q1","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Elasticity"}', 0),
  (1571, 413, 'A spring is stretched slightly and returns to its original length when released. What property does it demonstrate?', 'text', 1, 'It recovers its original length.', '{"why":"Returning to the original length after removing the force demonstrates elastic behaviour.","sol":"Step 1: The spring is deformed by a force.\nStep 2: The force is removed.\nStep 3: The spring returns to its original length.","steps":["Step 1: The spring is deformed by a force.","Step 2: The force is removed.","Step 3: The spring returns to its original length."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_elasticity","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q2","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Elasticity"}', 1),
  (1572, 413, 'Does an elastic material have to be rigid and incapable of changing shape?', 'text', 1, 'Distinguish temporary deformation from permanent deformation.', '{"why":"Elasticity describes recovery after deformation, not resistance to all deformation.","sol":"Step 1: A force can deform an elastic material.\nStep 2: The material can recover after the force is removed.\nStep 3: Therefore, elasticity does not mean rigidity.","steps":["Step 1: A force can deform an elastic material.","Step 2: The material can recover after the force is removed.","Step 3: Therefore, elasticity does not mean rigidity."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_elasticity","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q3","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Elasticity"}', 2),
  (1573, 413, 'A metal wire is stretched beyond its elastic limit and remains longer after the load is removed. Has it shown complete elastic recovery?', 'text', 1, 'Compare its final length with its original length.', '{"why":"Beyond the elastic limit, a material may not recover its original dimensions.","sol":"Step 1: The load is removed.\nStep 2: The wire remains longer than before.\nStep 3: It has undergone permanent deformation.","steps":["Step 1: The load is removed.","Step 2: The wire remains longer than before.","Step 3: It has undergone permanent deformation."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_elasticity","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q4","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Elasticity"}', 3),
  (1574, 413, 'A student says, ''A material is elastic because it can be stretched.'' What important part of the definition is missing?', 'text', 1, 'Think about what happens after stretching stops.', '{"why":"The defining feature of elasticity is recovery after the deforming force is removed.","sol":"Step 1: Stretching is a form of deformation.\nStep 2: Elasticity requires recovery after the force is removed.\nStep 3: The material must return to its original dimensions within its elastic range.","steps":["Step 1: Stretching is a form of deformation.","Step 2: Elasticity requires recovery after the force is removed.","Step 3: The material must return to its original dimensions within its elastic range."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_elasticity","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q5","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Elasticity"}', 4),
  (1575, 414, 'A spring''s original length is 8 cm and its stretched length is 13 cm. Find its extension.', 'text', 1, 'Subtract the original length from the stretched length.', '{"why":"13 cm − 8 cm = 5 cm.","sol":"Step 1: Extension = 13 − 8.\nStep 2: Extension = 5 cm.","steps":["Step 1: Extension = 13 − 8.","Step 2: Extension = 5 cm."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_extension_and_compression","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q1","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Extension and Compression"}', 0),
  (1576, 414, 'A wire increases in length from 1.20 m to 1.27 m. Calculate its extension.', 'text', 1, 'Subtract 1.20 m from 1.27 m.', '{"why":"The increase in length is 0.07 m.","sol":"Step 1: Extension = 1.27 − 1.20.\nStep 2: Extension = 0.07 m.","steps":["Step 1: Extension = 1.27 − 1.20.","Step 2: Extension = 0.07 m."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_extension_and_compression","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q2","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Extension and Compression"}', 1),
  (1577, 414, 'A spring has an original length of 0.25 m and an extension of 0.08 m. Find its stretched length.', 'text', 1, 'Rearrange the extension formula.', '{"why":"0.25 m + 0.08 m = 0.33 m.","sol":"Step 1: Stretched length = 0.25 + 0.08.\nStep 2: Stretched length = 0.33 m.","steps":["Step 1: Stretched length = 0.25 + 0.08.","Step 2: Stretched length = 0.33 m."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_extension_and_compression","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q3","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Extension and Compression"}', 2),
  (1578, 414, 'A compressed object decreases in length from 20 cm to 16 cm. By how much has its length decreased?', 'text', 1, 'Subtract the final length from the original length.', '{"why":"The object is 4 cm shorter than it was originally.","sol":"Step 1: Decrease = 20 − 16.\nStep 2: Decrease = 4 cm.","steps":["Step 1: Decrease = 20 − 16.","Step 2: Decrease = 4 cm."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_extension_and_compression","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q4","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Extension and Compression"}', 3),
  (1579, 414, 'A spring stretches by 6 cm. Express this extension in metres.', 'text', 1, 'Multiply centimetres by 0.01 to convert to metres.', '{"why":"6 × 0.01 = 0.06 m.","sol":"Step 1: 6 cm = 6 × 0.01 m.\nStep 2: Extension = 0.06 m.","steps":["Step 1: 6 cm = 6 × 0.01 m.","Step 2: Extension = 0.06 m."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_extension_and_compression","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q5","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Extension and Compression"}', 4),
  (1580, 415, 'A spring extends by 0.04 m when a force of 8 N is applied. Calculate its spring constant.', 'text', 1, 'Divide force by extension.', '{"why":"The spring constant is 200 N/m.","sol":"Step 1: k = 8/0.04.\nStep 2: k = 200 N/m.","steps":["Step 1: k = 8/0.04.","Step 2: k = 200 N/m."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_spring_constant","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q1","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Spring Constant"}', 0),
  (1581, 415, 'A spring has k = 500 N/m. What force produces an extension of 0.02 m?', 'text', 1, 'Multiply spring constant by extension.', '{"why":"F = 500 N/m × 0.02 m = 10 N.","sol":"Step 1: F = 500 × 0.02.\nStep 2: F = 10 N.","steps":["Step 1: F = 500 × 0.02.","Step 2: F = 10 N."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_spring_constant","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q2","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Spring Constant"}', 1),
  (1582, 415, 'Spring A has a spring constant of 100 N/m and spring B has 300 N/m. Which is stiffer?', 'text', 1, 'A stiffer spring has a larger spring constant.', '{"why":"Spring B requires more force for the same extension.","sol":"Step 1: Compare kA = 100 N/m with kB = 300 N/m.\nStep 2: 300 N/m is larger.\nStep 3: Spring B is stiffer.","steps":["Step 1: Compare kA = 100 N/m with kB = 300 N/m.","Step 2: 300 N/m is larger.","Step 3: Spring B is stiffer."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_spring_constant","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q3","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Spring Constant"}', 2),
  (1583, 415, 'A spring with k = 250 N/m is stretched by 0.08 m. Find the applied force, assuming Hooke''s law applies.', 'text', 1, 'Use F = kx.', '{"why":"The force is 20 N.","sol":"Step 1: F = 250 × 0.08.\nStep 2: F = 20 N.","steps":["Step 1: F = 250 × 0.08.","Step 2: F = 20 N."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_spring_constant","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q4","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Spring Constant"}', 3),
  (1584, 415, 'A force of 6 N extends a spring by 3 cm. Calculate its spring constant in N/m.', 'text', 1, 'Convert 3 cm to 0.03 m before dividing.', '{"why":"k = 6 N ÷ 0.03 m = 200 N/m.","sol":"Step 1: Convert 3 cm = 0.03 m.\nStep 2: k = 6/0.03.\nStep 3: k = 200 N/m.","steps":["Step 1: Convert 3 cm = 0.03 m.","Step 2: k = 6/0.03.","Step 3: k = 200 N/m."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_spring_constant","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q5","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Spring Constant"}', 4),
  (1585, 416, 'On a graph with force on the vertical axis and extension on the horizontal axis, what does the gradient represent for a Hookean spring?', 'text', 1, 'Gradient is vertical change divided by horizontal change.', '{"why":"The gradient of a force-against-extension graph is k for a spring obeying Hooke''s law.","sol":"Step 1: Vertical axis represents force.\nStep 2: Horizontal axis represents extension.\nStep 3: Gradient is force divided by extension, which equals k.","steps":["Step 1: Vertical axis represents force.","Step 2: Horizontal axis represents extension.","Step 3: Gradient is force divided by extension, which equals k."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_force_extension_graphs","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q1","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Force–Extension Graphs"}', 0),
  (1586, 416, 'A force–extension graph passes through the origin and is a straight line. What does this show about the spring over the measured range?', 'text', 1, 'Think about direct proportionality.', '{"why":"A straight line through the origin indicates a constant force-to-extension ratio.","sol":"Step 1: A straight line through the origin indicates proportionality.\nStep 2: Force is directly proportional to extension.\nStep 3: The spring obeys Hooke''s law over that range.","steps":["Step 1: A straight line through the origin indicates proportionality.","Step 2: Force is directly proportional to extension.","Step 3: The spring obeys Hooke''s law over that range."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_force_extension_graphs","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q2","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Force–Extension Graphs"}', 1),
  (1587, 416, 'On a force–extension graph, force changes from 4 N to 12 N while extension changes from 0.02 m to 0.06 m. Calculate the gradient.', 'text', 1, 'Use changes in force and extension, not just one endpoint.', '{"why":"The gradient is 8 N divided by 0.04 m, giving 200 N/m.","sol":"Step 1: ΔF = 12 − 4 = 8 N.\nStep 2: Δx = 0.06 − 0.02 = 0.04 m.\nStep 3: Gradient = 8/0.04 = 200 N/m.","steps":["Step 1: ΔF = 12 − 4 = 8 N.","Step 2: Δx = 0.06 − 0.02 = 0.04 m.","Step 3: Gradient = 8/0.04 = 200 N/m."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_force_extension_graphs","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q3","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Force–Extension Graphs"}', 2),
  (1588, 416, 'Two force–extension graphs are straight lines through the origin. Spring A has a steeper gradient than spring B. Which spring has the larger spring constant?', 'text', 1, 'For force on the vertical axis, gradient equals k.', '{"why":"A larger gradient means a larger spring constant and a stiffer spring.","sol":"Step 1: The gradient of each graph equals its spring constant.\nStep 2: A''s gradient is steeper.\nStep 3: Spring A has the larger k.","steps":["Step 1: The gradient of each graph equals its spring constant.","Step 2: A''s gradient is steeper.","Step 3: Spring A has the larger k."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_force_extension_graphs","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q4","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Force–Extension Graphs"}', 3),
  (1589, 416, 'A graph has extension on the vertical axis and force on the horizontal axis. What does its gradient represent?', 'text', 1, 'Reverse the usual axis arrangement.', '{"why":"Changing the axes reverses the ratio, so the gradient becomes 1/k.","sol":"Step 1: Vertical axis is extension.\nStep 2: Horizontal axis is force.\nStep 3: Gradient = extension/force = 1/k for a Hookean spring.","steps":["Step 1: Vertical axis is extension.","Step 2: Horizontal axis is force.","Step 3: Gradient = extension/force = 1/k for a Hookean spring."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_force_extension_graphs","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q5","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Force–Extension Graphs"}', 4),
  (1590, 417, 'What is the limit of proportionality?', 'text', 1, 'It marks the end of the direct force–extension relationship.', '{"why":"The limit of proportionality marks the end of Hooke''s law behaviour.","sol":"Step 1: Before the limit, force is proportional to extension.\nStep 2: At and beyond the limit, that proportional relationship ceases to hold.","steps":["Step 1: Before the limit, force is proportional to extension.","Step 2: At and beyond the limit, that proportional relationship ceases to hold."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_limit_of_proportionality","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q1","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Limit of Proportionality"}', 0),
  (1591, 417, 'A spring''s force–extension graph stops being a straight line. What does this indicate about Hooke''s law?', 'text', 1, 'Hooke''s law predicts direct proportionality.', '{"why":"A curved force–extension graph indicates that the force-to-extension ratio is no longer constant.","sol":"Step 1: A straight line through the origin represents proportionality.\nStep 2: The graph curves away from that line.\nStep 3: Force is no longer directly proportional to extension.","steps":["Step 1: A straight line through the origin represents proportionality.","Step 2: The graph curves away from that line.","Step 3: Force is no longer directly proportional to extension."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_limit_of_proportionality","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q2","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Limit of Proportionality"}', 1),
  (1592, 417, 'Is the limit of proportionality necessarily the same as the elastic limit?', 'text', 1, 'One concerns proportionality; the other concerns recovery.', '{"why":"A material may stop obeying Hooke''s law before it loses the ability to recover fully.","sol":"Step 1: The limit of proportionality concerns the force–extension relationship.\nStep 2: The elastic limit concerns whether original dimensions are recovered.\nStep 3: These describe different properties.","steps":["Step 1: The limit of proportionality concerns the force–extension relationship.","Step 2: The elastic limit concerns whether original dimensions are recovered.","Step 3: These describe different properties."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_limit_of_proportionality","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q3","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Limit of Proportionality"}', 2),
  (1593, 417, 'A material is stretched beyond its limit of proportionality but returns to its original length when unloaded. Is this possible?', 'text', 1, 'Consider whether non-proportional behaviour always causes permanent deformation.', '{"why":"The loss of direct proportionality does not by itself mean the material has been permanently deformed.","sol":"Step 1: Beyond the limit of proportionality, force and extension are no longer proportional.\nStep 2: The material may still be within its elastic limit.\nStep 3: It can therefore recover when unloaded.","steps":["Step 1: Beyond the limit of proportionality, force and extension are no longer proportional.","Step 2: The material may still be within its elastic limit.","Step 3: It can therefore recover when unloaded."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_limit_of_proportionality","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q4","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Limit of Proportionality"}', 3),
  (1594, 417, 'What does a straight-line force–extension graph through the origin indicate before the limit of proportionality?', 'text', 1, 'Identify the relationship between force and extension.', '{"why":"A constant gradient through the origin shows direct proportionality.","sol":"Step 1: The gradient is constant.\nStep 2: The ratio of force to extension is constant.\nStep 3: Force is directly proportional to extension.","steps":["Step 1: The gradient is constant.","Step 2: The ratio of force to extension is constant.","Step 3: Force is directly proportional to extension."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_limit_of_proportionality","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q5","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Limit of Proportionality"}', 4),
  (1595, 418, 'What is elastic deformation?', 'text', 1, 'Consider what happens when the force is removed.', '{"why":"Elastic deformation is recoverable deformation.","sol":"Step 1: The force changes the object''s dimensions.\nStep 2: The force is removed.\nStep 3: The object returns to its original dimensions.","steps":["Step 1: The force changes the object''s dimensions.","Step 2: The force is removed.","Step 3: The object returns to its original dimensions."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_elastic_and_plastic_deformation","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q1","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Elastic and Plastic Deformation"}', 0),
  (1596, 418, 'What is plastic deformation?', 'text', 1, 'Check whether the object fully recovers after unloading.', '{"why":"Plastic deformation is not fully recovered after the load is removed.","sol":"Step 1: A force changes the object''s dimensions.\nStep 2: The force is removed.\nStep 3: Some deformation remains.","steps":["Step 1: A force changes the object''s dimensions.","Step 2: The force is removed.","Step 3: Some deformation remains."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_elastic_and_plastic_deformation","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q2","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Elastic and Plastic Deformation"}', 1),
  (1597, 418, 'A wire is stretched and remains longer after the load is removed. What kind of deformation has occurred?', 'text', 1, 'The wire has not returned to its original length.', '{"why":"The remaining increase in length indicates plastic deformation.","sol":"Step 1: The load is removed.\nStep 2: The wire remains longer.\nStep 3: The deformation is permanent.","steps":["Step 1: The load is removed.","Step 2: The wire remains longer.","Step 3: The deformation is permanent."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_elastic_and_plastic_deformation","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q3","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Elastic and Plastic Deformation"}', 2),
  (1598, 418, 'A spring returns to its original length after a small load is removed. What kind of deformation did it undergo?', 'text', 1, 'The spring fully recovered.', '{"why":"The spring fully recovered its original length.","sol":"Step 1: The spring was stretched.\nStep 2: The load was removed.\nStep 3: The spring returned to its original length.","steps":["Step 1: The spring was stretched.","Step 2: The load was removed.","Step 3: The spring returned to its original length."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_elastic_and_plastic_deformation","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q4","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Elastic and Plastic Deformation"}', 3),
  (1599, 418, 'A metal object is permanently bent but remains in one piece. Which statement is correct?', 'text', 1, 'Distinguish permanent shape change from breaking.', '{"why":"Permanent deformation and fracture are different forms of material behaviour.","sol":"Step 1: The object has not returned to its original shape.\nStep 2: The change remains after the force is removed.\nStep 3: The object has undergone plastic deformation but has not necessarily fractured.","steps":["Step 1: The object has not returned to its original shape.","Step 2: The change remains after the force is removed.","Step 3: The object has undergone plastic deformation but has not necessarily fractured."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_elastic_and_plastic_deformation","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q5","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Elastic and Plastic Deformation"}', 4),
  (1600, 419, 'A force of 100 N acts on a cross-sectional area of 0.005 m². Calculate the stress.', 'text', 1, 'Divide force by cross-sectional area.', '{"why":"Stress = 100 N ÷ 0.005 m² = 20,000 Pa.","sol":"Step 1: σ = 100/0.005.\nStep 2: σ = 20,000 Pa.","steps":["Step 1: σ = 100/0.005.","Step 2: σ = 20,000 Pa."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_stress","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q1","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Stress"}', 0),
  (1601, 419, 'A wire experiences a stress of 50,000 Pa across an area of 0.002 m². Calculate the force.', 'text', 1, 'Rearrange stress = force ÷ area.', '{"why":"F = 50,000 Pa × 0.002 m² = 100 N.","sol":"Step 1: F = 50,000 × 0.002.\nStep 2: F = 100 N.","steps":["Step 1: F = 50,000 × 0.002.","Step 2: F = 100 N."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_stress","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q2","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Stress"}', 1),
  (1602, 419, 'A force of 300 N produces a stress of 150,000 Pa. Find the cross-sectional area.', 'text', 1, 'Rearrange σ = F/A to make A the subject.', '{"why":"A = 300 N ÷ 150,000 Pa = 0.002 m².","sol":"Step 1: A = 300/150,000.\nStep 2: A = 0.002 m².","steps":["Step 1: A = 300/150,000.","Step 2: A = 0.002 m²."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_stress","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q3","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Stress"}', 2),
  (1603, 419, 'The same tensile force acts on two wires. Wire A has half the cross-sectional area of wire B. How does stress in A compare with stress in B?', 'text', 1, 'Stress is inversely proportional to area for a constant force.', '{"why":"The same force concentrated over half the area produces twice the stress.","sol":"Step 1: The force is the same in both wires.\nStep 2: Wire A has half the area.\nStep 3: Its stress is twice the stress in wire B.","steps":["Step 1: The force is the same in both wires.","Step 2: Wire A has half the area.","Step 3: Its stress is twice the stress in wire B."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_stress","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q4","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Stress"}', 3),
  (1604, 419, 'A tensile force of 2,000 N acts on a wire of cross-sectional area 4 × 10⁻⁴ m². Calculate the stress.', 'text', 1, 'Divide 2,000 by 0.0004.', '{"why":"2,000 ÷ 0.0004 = 5,000,000 Pa.","sol":"Step 1: σ = 2,000/(4 × 10⁻⁴).\nStep 2: σ = 5,000,000 Pa.\nStep 3: σ = 5 × 10⁶ Pa.","steps":["Step 1: σ = 2,000/(4 × 10⁻⁴).","Step 2: σ = 5,000,000 Pa.","Step 3: σ = 5 × 10⁶ Pa."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_stress","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q5","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Stress"}', 4),
  (1605, 420, 'A wire of original length 2 m extends by 0.01 m. Calculate its strain.', 'text', 1, 'Divide extension by original length.', '{"why":"Strain = 0.01 m ÷ 2 m = 0.005.","sol":"Step 1: ε = 0.01/2.\nStep 2: ε = 0.005.","steps":["Step 1: ε = 0.01/2.","Step 2: ε = 0.005."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_strain","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q1","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Strain"}', 0),
  (1606, 420, 'A wire is 0.5 m long and has a strain of 0.004. Find its extension.', 'text', 1, 'Rearrange strain = extension ÷ original length.', '{"why":"x = 0.004 × 0.5 m = 0.002 m.","sol":"Step 1: x = 0.004 × 0.5.\nStep 2: x = 0.002 m.","steps":["Step 1: x = 0.004 × 0.5.","Step 2: x = 0.002 m."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_strain","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q2","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Strain"}', 1),
  (1607, 420, 'A wire of original length 4 m extends by 2 cm. Calculate the strain.', 'text', 1, 'Convert 2 cm to metres before dividing.', '{"why":"Strain = 0.02 m ÷ 4 m = 0.005.","sol":"Step 1: 2 cm = 0.02 m.\nStep 2: ε = 0.02/4.\nStep 3: ε = 0.005.","steps":["Step 1: 2 cm = 0.02 m.","Step 2: ε = 0.02/4.","Step 3: ε = 0.005."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_strain","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q3","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Strain"}', 2),
  (1608, 420, 'A 1.5 m wire extends by 0.003 m. Find its strain.', 'text', 1, 'Calculate 0.003 divided by 1.5.', '{"why":"Strain is the ratio 0.003/1.5 = 0.002.","sol":"Step 1: ε = 0.003/1.5.\nStep 2: ε = 0.002.","steps":["Step 1: ε = 0.003/1.5.","Step 2: ε = 0.002."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_strain","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q4","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Strain"}', 3),
  (1609, 420, 'Why does strain have no unit?', 'text', 1, 'Look at the units in the strain formula.', '{"why":"Dividing one length by another length produces a dimensionless ratio.","sol":"Step 1: Strain = extension/original length.\nStep 2: Both quantities are lengths.\nStep 3: Their units cancel when divided.","steps":["Step 1: Strain = extension/original length.","Step 2: Both quantities are lengths.","Step 3: Their units cancel when divided."],"options":[],"conceptId":"physics_mechanical_properties_of_materials_strain","skillId":"physics_mechanical_properties_of_materials","subskillId":"physics_mechanical_properties_of_materials_q5","subject":"physics","chapter":"mechanical_properties_of_materials","topic":"Strain"}', 4),
  (1610, 421, 'A force of 15 N acts perpendicularly 0.4 m from a pivot. Calculate its moment.', 'text', 1, 'Moment = force × perpendicular distance.', '{"why":"The moment measures the turning effect of the force about the pivot.","sol":"Step 1: Write M = Fd.\nStep 2: Substitute M = 15 × 0.4.\nStep 3: Calculate M = 6 N m.","steps":["Step 1: Write M = Fd.","Step 2: Substitute M = 15 × 0.4.","Step 3: Calculate M = 6 N m."],"options":[],"conceptId":"physics_moments_and_equilibrium_moment_of_a_force","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q1","subject":"physics","chapter":"moments_and_equilibrium","topic":"Moment of a Force"}', 0),
  (1611, 421, 'A force of 40 N produces a moment of 20 N m. Find the perpendicular distance from the pivot.', 'text', 1, 'Distance = moment ÷ force.', '{"why":"Rearranging the moment formula gives the perpendicular distance.","sol":"Step 1: Start with M = Fd.\nStep 2: Rearrange to d = M/F.\nStep 3: Substitute d = 20/40 = 0.5 m.","steps":["Step 1: Start with M = Fd.","Step 2: Rearrange to d = M/F.","Step 3: Substitute d = 20/40 = 0.5 m."],"options":[],"conceptId":"physics_moments_and_equilibrium_moment_of_a_force","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q2","subject":"physics","chapter":"moments_and_equilibrium","topic":"Moment of a Force"}', 1),
  (1612, 421, 'A 25 N force acts perpendicularly 0.8 m from a pivot. Calculate the moment.', 'text', 1, 'Multiply the force by the perpendicular distance.', '{"why":"A larger force or lever arm produces a greater moment.","sol":"Step 1: Write M = Fd.\nStep 2: Substitute M = 25 × 0.8.\nStep 3: Calculate M = 20 N m.","steps":["Step 1: Write M = Fd.","Step 2: Substitute M = 25 × 0.8.","Step 3: Calculate M = 20 N m."],"options":[],"conceptId":"physics_moments_and_equilibrium_moment_of_a_force","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q3","subject":"physics","chapter":"moments_and_equilibrium","topic":"Moment of a Force"}', 2),
  (1613, 421, 'A moment of 18 N m acts at a perpendicular distance of 0.6 m. Calculate the force.', 'text', 1, 'Force = moment ÷ distance.', '{"why":"The force is found by dividing the moment by the perpendicular distance.","sol":"Step 1: Write F = M/d.\nStep 2: Substitute F = 18/0.6.\nStep 3: Calculate F = 30 N.","steps":["Step 1: Write F = M/d.","Step 2: Substitute F = 18/0.6.","Step 3: Calculate F = 30 N."],"options":[],"conceptId":"physics_moments_and_equilibrium_moment_of_a_force","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q4","subject":"physics","chapter":"moments_and_equilibrium","topic":"Moment of a Force"}', 3),
  (1614, 421, 'Two equal perpendicular forces act separately on the same pivot. Force A acts 0.2 m away and force B acts 0.5 m away. Which produces the larger moment?', 'text', 1, 'The forces are equal, so compare their perpendicular distances.', '{"why":"Moment depends on force and perpendicular distance.","sol":"Step 1: The forces have equal magnitude.\nStep 2: Moment is proportional to perpendicular distance for a fixed force.\nStep 3: Force B acts farther from the pivot and produces the larger moment.","steps":["Step 1: The forces have equal magnitude.","Step 2: Moment is proportional to perpendicular distance for a fixed force.","Step 3: Force B acts farther from the pivot and produces the larger moment."],"options":[],"conceptId":"physics_moments_and_equilibrium_moment_of_a_force","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q5","subject":"physics","chapter":"moments_and_equilibrium","topic":"Moment of a Force"}', 4),
  (1615, 422, 'A horizontal seesaw has a pivot at its centre. A downward force acts on its left end. Which way does the seesaw tend to turn?', 'text', 1, 'Imagine the left end moving downward and the right end moving upward.', '{"why":"A downward force on the left side of a central pivot produces an anticlockwise moment.","sol":"Step 1: The pivot is at the centre.\nStep 2: The left end is pushed downward.\nStep 3: The seesaw tends to turn anticlockwise.","steps":["Step 1: The pivot is at the centre.","Step 2: The left end is pushed downward.","Step 3: The seesaw tends to turn anticlockwise."],"options":[],"conceptId":"physics_moments_and_equilibrium_clockwise_and_anticlockwise_moments","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q1","subject":"physics","chapter":"moments_and_equilibrium","topic":"Clockwise and Anticlockwise Moments"}', 0),
  (1616, 422, 'A downward force acts on the right end of a horizontal lever whose pivot is at the centre. What is its turning direction?', 'text', 1, 'Imagine the right end moving down and the left end moving up.', '{"why":"The position and direction of the force determine the turning sense.","sol":"Step 1: The force acts to the right of the pivot.\nStep 2: It pushes the right end downward.\nStep 3: The lever tends to turn clockwise.","steps":["Step 1: The force acts to the right of the pivot.","Step 2: It pushes the right end downward.","Step 3: The lever tends to turn clockwise."],"options":[],"conceptId":"physics_moments_and_equilibrium_clockwise_and_anticlockwise_moments","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q2","subject":"physics","chapter":"moments_and_equilibrium","topic":"Clockwise and Anticlockwise Moments"}', 1),
  (1617, 422, 'A force produces a clockwise moment about a pivot. If the force direction is reversed at the same point, what happens to the turning direction?', 'text', 1, 'Reversing the force reverses its turning tendency.', '{"why":"Reversing a force at the same lever arm reverses its turning effect.","sol":"Step 1: The point of application stays the same.\nStep 2: The force direction is reversed.\nStep 3: The moment''s turning direction reverses.","steps":["Step 1: The point of application stays the same.","Step 2: The force direction is reversed.","Step 3: The moment''s turning direction reverses."],"options":[],"conceptId":"physics_moments_and_equilibrium_clockwise_and_anticlockwise_moments","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q3","subject":"physics","chapter":"moments_and_equilibrium","topic":"Clockwise and Anticlockwise Moments"}', 2),
  (1618, 422, 'What acts as the pivot axis of an ordinary hinged door?', 'text', 1, 'Identify the line about which the door rotates.', '{"why":"A door rotates about its hinges.","sol":"Step 1: The door rotates when it opens or closes.\nStep 2: Its rotation occurs about the hinge line.\nStep 3: Therefore, the hinge line is the pivot axis.","steps":["Step 1: The door rotates when it opens or closes.","Step 2: Its rotation occurs about the hinge line.","Step 3: Therefore, the hinge line is the pivot axis."],"options":[],"conceptId":"physics_moments_and_equilibrium_clockwise_and_anticlockwise_moments","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q4","subject":"physics","chapter":"moments_and_equilibrium","topic":"Clockwise and Anticlockwise Moments"}', 3),
  (1619, 422, 'Why is a force''s position relative to the pivot important when determining its moment?', 'text', 1, 'Consider the perpendicular distance in M = Fd.', '{"why":"The moment depends on the force''s lever arm about the pivot.","sol":"Step 1: Moment depends on force and perpendicular distance.\nStep 2: Changing the position can change that distance.\nStep 3: Therefore, the same force can produce different moments at different positions.","steps":["Step 1: Moment depends on force and perpendicular distance.","Step 2: Changing the position can change that distance.","Step 3: Therefore, the same force can produce different moments at different positions."],"options":[],"conceptId":"physics_moments_and_equilibrium_clockwise_and_anticlockwise_moments","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q5","subject":"physics","chapter":"moments_and_equilibrium","topic":"Clockwise and Anticlockwise Moments"}', 4),
  (1620, 423, 'A clockwise moment of 18 N m acts on a balanced lever. What must the total anticlockwise moment be?', 'text', 1, 'Apply the principle of moments.', '{"why":"For rotational equilibrium, total clockwise moment equals total anticlockwise moment.","sol":"Step 1: A balanced lever is in rotational equilibrium.\nStep 2: Clockwise and anticlockwise moments are equal.\nStep 3: The anticlockwise moment must be 18 N m.","steps":["Step 1: A balanced lever is in rotational equilibrium.","Step 2: Clockwise and anticlockwise moments are equal.","Step 3: The anticlockwise moment must be 18 N m."],"options":[],"conceptId":"physics_moments_and_equilibrium_principle_of_moments","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q1","subject":"physics","chapter":"moments_and_equilibrium","topic":"Principle of Moments"}', 0),
  (1621, 423, 'A 10 N force acts 0.4 m from a pivot. What force at 0.2 m on the opposite side balances the moments?', 'text', 1, 'Calculate the first moment, then divide it by the second distance.', '{"why":"A shorter lever arm needs a greater force to produce the same moment.","sol":"Step 1: First moment = 10 × 0.4 = 4 N m.\nStep 2: For balance, F₂ × 0.2 = 4.\nStep 3: F₂ = 4/0.2 = 20 N.","steps":["Step 1: First moment = 10 × 0.4 = 4 N m.","Step 2: For balance, F₂ × 0.2 = 4.","Step 3: F₂ = 4/0.2 = 20 N."],"options":[],"conceptId":"physics_moments_and_equilibrium_principle_of_moments","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q2","subject":"physics","chapter":"moments_and_equilibrium","topic":"Principle of Moments"}', 1),
  (1622, 423, 'The clockwise moment is 25 N m and the anticlockwise moment is 17 N m. Find the resultant moment.', 'text', 1, 'Subtract the smaller opposing moment from the larger.', '{"why":"Opposing moments subtract when finding the resultant turning effect.","sol":"Step 1: Clockwise moment = 25 N m.\nStep 2: Anticlockwise moment = 17 N m.\nStep 3: Resultant = 25 − 17 = 8 N m clockwise.","steps":["Step 1: Clockwise moment = 25 N m.","Step 2: Anticlockwise moment = 17 N m.","Step 3: Resultant = 25 − 17 = 8 N m clockwise."],"options":[],"conceptId":"physics_moments_and_equilibrium_principle_of_moments","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q3","subject":"physics","chapter":"moments_and_equilibrium","topic":"Principle of Moments"}', 2),
  (1623, 423, 'A 30 N force acts 0.6 m from a pivot. Calculate the moment that an opposing force must produce to balance it.', 'text', 1, 'Find the moment first, then use the principle of moments.', '{"why":"The principle of moments requires equal opposing moments for rotational equilibrium.","sol":"Step 1: Calculate the moment: 30 × 0.6 = 18 N m.\nStep 2: A balanced lever needs an equal opposing moment.\nStep 3: The opposing moment must be 18 N m.","steps":["Step 1: Calculate the moment: 30 × 0.6 = 18 N m.","Step 2: A balanced lever needs an equal opposing moment.","Step 3: The opposing moment must be 18 N m."],"options":[],"conceptId":"physics_moments_and_equilibrium_principle_of_moments","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q4","subject":"physics","chapter":"moments_and_equilibrium","topic":"Principle of Moments"}', 3),
  (1624, 423, 'A lever has equal clockwise and anticlockwise moments. What is its resultant moment?', 'text', 1, 'Opposing moments cancel when their magnitudes are equal.', '{"why":"Equal opposing moments cancel.","sol":"Step 1: Identify the two moments as opposite in turning direction.\nStep 2: Their magnitudes are equal.\nStep 3: Subtracting one from the other gives zero.","steps":["Step 1: Identify the two moments as opposite in turning direction.","Step 2: Their magnitudes are equal.","Step 3: Subtracting one from the other gives zero."],"options":[],"conceptId":"physics_moments_and_equilibrium_principle_of_moments","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q5","subject":"physics","chapter":"moments_and_equilibrium","topic":"Principle of Moments"}', 4),
  (1625, 424, 'Where is the centre of gravity of a uniform ruler in a uniform gravitational field?', 'text', 1, 'A uniform ruler has its mass evenly distributed along its length.', '{"why":"A uniform ruler''s centre of gravity lies at its geometric centre.","sol":"Step 1: The ruler is uniform along its length.\nStep 2: Its mass is symmetrically distributed.\nStep 3: The centre of gravity is at the midpoint.","steps":["Step 1: The ruler is uniform along its length.","Step 2: Its mass is symmetrically distributed.","Step 3: The centre of gravity is at the midpoint."],"options":[],"conceptId":"physics_moments_and_equilibrium_centre_of_gravity","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q1","subject":"physics","chapter":"moments_and_equilibrium","topic":"Centre of Gravity"}', 0),
  (1626, 424, 'What instrument can be used to mark the vertical line when locating the centre of gravity of a suspended irregular lamina?', 'text', 1, 'It indicates the vertical direction using a hanging weight.', '{"why":"A plumb line identifies the vertical direction through the suspension point.","sol":"Step 1: Suspend the lamina freely.\nStep 2: Hang a weighted string beside it.\nStep 3: The string identifies the vertical line.","steps":["Step 1: Suspend the lamina freely.","Step 2: Hang a weighted string beside it.","Step 3: The string identifies the vertical line."],"options":[],"conceptId":"physics_moments_and_equilibrium_centre_of_gravity","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q2","subject":"physics","chapter":"moments_and_equilibrium","topic":"Centre of Gravity"}', 1),
  (1627, 424, 'What happens to an object''s centre of gravity when a substantial mass is added to one side?', 'text', 1, 'Think about where the mass distribution becomes greater.', '{"why":"The centre of gravity depends on the distribution of weight.","sol":"Step 1: The added mass changes the object''s mass distribution.\nStep 2: The combined centre of gravity shifts toward the added mass.\nStep 3: The exact shift depends on the positions and masses involved.","steps":["Step 1: The added mass changes the object''s mass distribution.","Step 2: The combined centre of gravity shifts toward the added mass.","Step 3: The exact shift depends on the positions and masses involved."],"options":[],"conceptId":"physics_moments_and_equilibrium_centre_of_gravity","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q3","subject":"physics","chapter":"moments_and_equilibrium","topic":"Centre of Gravity"}', 2),
  (1628, 424, 'Must the centre of gravity always lie inside the material of an object?', 'text', 1, 'Consider a ring or a hollow frame.', '{"why":"The centre of gravity is a reference point for the body''s weight, not necessarily a point made of material.","sol":"Step 1: The centre of gravity is a point describing the resultant weight.\nStep 2: A ring can have a symmetric mass distribution around an empty centre.\nStep 3: Its centre of gravity can lie in the empty space.","steps":["Step 1: The centre of gravity is a point describing the resultant weight.","Step 2: A ring can have a symmetric mass distribution around an empty centre.","Step 3: Its centre of gravity can lie in the empty space."],"options":[],"conceptId":"physics_moments_and_equilibrium_centre_of_gravity","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q4","subject":"physics","chapter":"moments_and_equilibrium","topic":"Centre of Gravity"}', 3),
  (1629, 424, 'Why is the centre of gravity important when considering whether an object will topple?', 'text', 1, 'Consider the vertical line through the centre of gravity and the object''s base.', '{"why":"Stability depends partly on the centre of gravity''s position relative to the base of support.","sol":"Step 1: The object''s weight acts through its centre of gravity.\nStep 2: If the vertical line through that point falls outside the base of support, the weight can produce a toppling moment.\nStep 3: Therefore, the centre of gravity''s position affects stability.","steps":["Step 1: The object''s weight acts through its centre of gravity.","Step 2: If the vertical line through that point falls outside the base of support, the weight can produce a toppling moment.","Step 3: Therefore, the centre of gravity''s position affects stability."],"options":[],"conceptId":"physics_moments_and_equilibrium_centre_of_gravity","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q5","subject":"physics","chapter":"moments_and_equilibrium","topic":"Centre of Gravity"}', 4),
  (1630, 425, 'Which is generally more stable: an otherwise similar object with a low centre of gravity or one with a high centre of gravity?', 'text', 1, 'Consider how far the object must tilt before its weight produces a toppling moment.', '{"why":"A low centre of gravity generally increases stability.","sol":"Step 1: A lower centre of gravity generally requires a larger tilt before its vertical line leaves the base.\nStep 2: This makes toppling less likely under comparable conditions.\nStep 3: Therefore, the lower-centre-of-gravity object is generally more stable.","steps":["Step 1: A lower centre of gravity generally requires a larger tilt before its vertical line leaves the base.","Step 2: This makes toppling less likely under comparable conditions.","Step 3: Therefore, the lower-centre-of-gravity object is generally more stable."],"options":[],"conceptId":"physics_moments_and_equilibrium_stability_of_objects","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q1","subject":"physics","chapter":"moments_and_equilibrium","topic":"Stability of Objects"}', 0),
  (1631, 425, 'How does widening an object''s base of support generally affect its stability?', 'text', 1, 'A wider base allows a larger range of tilt before the weight''s line of action leaves it.', '{"why":"A wider base increases the range over which the weight can act within the support area.","sol":"Step 1: The base of support becomes wider.\nStep 2: The vertical line through the centre of gravity can remain within the base through a greater range of tilt.\nStep 3: The object is generally more resistant to toppling.","steps":["Step 1: The base of support becomes wider.","Step 2: The vertical line through the centre of gravity can remain within the base through a greater range of tilt.","Step 3: The object is generally more resistant to toppling."],"options":[],"conceptId":"physics_moments_and_equilibrium_stability_of_objects","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q2","subject":"physics","chapter":"moments_and_equilibrium","topic":"Stability of Objects"}', 1),
  (1632, 425, 'What can happen when the vertical line through an object''s centre of gravity falls outside its base of support?', 'text', 1, 'Consider the turning effect of the object''s weight.', '{"why":"A weight line outside the base can create a turning effect that causes toppling.","sol":"Step 1: The weight acts vertically through the centre of gravity.\nStep 2: Its line of action lies outside the support base.\nStep 3: The weight can create a toppling moment.","steps":["Step 1: The weight acts vertically through the centre of gravity.","Step 2: Its line of action lies outside the support base.","Step 3: The weight can create a toppling moment."],"options":[],"conceptId":"physics_moments_and_equilibrium_stability_of_objects","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q3","subject":"physics","chapter":"moments_and_equilibrium","topic":"Stability of Objects"}', 2),
  (1633, 425, 'Why can carrying a heavy load close to the ground improve stability?', 'text', 1, 'Consider the position of the combined centre of gravity.', '{"why":"Lowering the centre of gravity generally makes toppling less likely.","sol":"Step 1: The load contributes to the combined centre of gravity.\nStep 2: Placing it lower tends to lower the combined centre of gravity.\nStep 3: A lower centre of gravity generally improves stability.","steps":["Step 1: The load contributes to the combined centre of gravity.","Step 2: Placing it lower tends to lower the combined centre of gravity.","Step 3: A lower centre of gravity generally improves stability."],"options":[],"conceptId":"physics_moments_and_equilibrium_stability_of_objects","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q4","subject":"physics","chapter":"moments_and_equilibrium","topic":"Stability of Objects"}', 3),
  (1634, 425, 'Does a low centre of gravity guarantee that an object can never topple?', 'text', 1, 'Consider other factors affecting stability.', '{"why":"A low centre of gravity helps but does not eliminate all possible toppling.","sol":"Step 1: A low centre of gravity generally improves stability.\nStep 2: However, a narrow base or a large external force can still cause toppling.\nStep 3: Therefore, it is not an absolute guarantee.","steps":["Step 1: A low centre of gravity generally improves stability.","Step 2: However, a narrow base or a large external force can still cause toppling.","Step 3: Therefore, it is not an absolute guarantee."],"options":[],"conceptId":"physics_moments_and_equilibrium_stability_of_objects","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q5","subject":"physics","chapter":"moments_and_equilibrium","topic":"Stability of Objects"}', 4),
  (1635, 426, 'A 30 N force acts 2 m from a pivot. What distance from the pivot must a 20 N force act at to balance it?', 'text', 1, 'Equate the two moments.', '{"why":"The smaller force needs a longer distance to produce the same moment.","sol":"Step 1: 30 × 2 = 20 × d\nStep 2: 60 = 20d\nStep 3: d = 3 m","steps":["Step 1: 30 × 2 = 20 × d","Step 2: 60 = 20d","Step 3: d = 3 m"],"options":[],"conceptId":"physics_moments_and_equilibrium_calculating_an_unknown_distance_using_moments","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q1","subject":"physics","chapter":"moments_and_equilibrium","topic":"Calculating an Unknown Distance Using Moments"}', 0),
  (1636, 426, 'A 50 N force acts 0.4 m from a pivot. Find the distance at which a 10 N force must act to balance it.', 'text', 1, 'Use force × distance on each side.', '{"why":"Both moments must equal 20 N m.","sol":"Step 1: 50 × 0.4 = 10 × d\nStep 2: 20 = 10d\nStep 3: d = 2 m","steps":["Step 1: 50 × 0.4 = 10 × d","Step 2: 20 = 10d","Step 3: d = 2 m"],"options":[],"conceptId":"physics_moments_and_equilibrium_calculating_an_unknown_distance_using_moments","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q2","subject":"physics","chapter":"moments_and_equilibrium","topic":"Calculating an Unknown Distance Using Moments"}', 1),
  (1637, 426, 'A 12 N force acts 0.5 m from a pivot. A 6 N force balances it on the opposite side. Find the distance of the 6 N force.', 'text', 1, 'Calculate the first moment, then divide by 6 N.', '{"why":"The 6 N force must produce a moment of 6 N m.","sol":"Step 1: Moment = 12 × 0.5 = 6 N m\nStep 2: 6 × d = 6\nStep 3: d = 1 m","steps":["Step 1: Moment = 12 × 0.5 = 6 N m","Step 2: 6 × d = 6","Step 3: d = 1 m"],"options":[],"conceptId":"physics_moments_and_equilibrium_calculating_an_unknown_distance_using_moments","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q3","subject":"physics","chapter":"moments_and_equilibrium","topic":"Calculating an Unknown Distance Using Moments"}', 2),
  (1638, 426, 'A 25 N force acts 0.8 m from a pivot. A balancing force of 10 N acts on the opposite side. Calculate its distance.', 'text', 1, 'Set the moments equal.', '{"why":"The balancing force must produce a moment of 20 N m.","sol":"Step 1: 25 × 0.8 = 10 × d\nStep 2: 20 = 10d\nStep 3: d = 2 m","steps":["Step 1: 25 × 0.8 = 10 × d","Step 2: 20 = 10d","Step 3: d = 2 m"],"options":[],"conceptId":"physics_moments_and_equilibrium_calculating_an_unknown_distance_using_moments","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q4","subject":"physics","chapter":"moments_and_equilibrium","topic":"Calculating an Unknown Distance Using Moments"}', 3),
  (1639, 426, 'A learner divides 40 N by 0.5 m to calculate the moment. What should the learner do instead?', 'text', 1, 'Recall the moment formula.', '{"why":"Moment is the product of force and perpendicular distance.","sol":"Step 1: Moment = force × perpendicular distance.\nStep 2: Moment = 40 × 0.5 = 20 N m.","steps":["Step 1: Moment = force × perpendicular distance.","Step 2: Moment = 40 × 0.5 = 20 N m."],"options":[],"conceptId":"physics_moments_and_equilibrium_calculating_an_unknown_distance_using_moments","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q5","subject":"physics","chapter":"moments_and_equilibrium","topic":"Calculating an Unknown Distance Using Moments"}', 4),
  (1640, 427, 'A 40 N load acts 0.5 m from a pivot. The effort acts 2 m away. Find the effort needed for balance.', 'text', 1, 'Equate the moments.', '{"why":"The effort''s longer arm means less force is needed.","sol":"Step 1: 40 × 0.5 = F × 2\nStep 2: 20 = 2F\nStep 3: F = 10 N","steps":["Step 1: 40 × 0.5 = F × 2","Step 2: 20 = 2F","Step 3: F = 10 N"],"options":[],"conceptId":"physics_moments_and_equilibrium_finding_an_unknown_force_using_moments","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q1","subject":"physics","chapter":"moments_and_equilibrium","topic":"Finding an Unknown Force Using Moments"}', 0),
  (1641, 427, 'A 100 N load acts 0.3 m from a pivot. An effort acts 1.5 m from the pivot. Calculate the balancing effort.', 'text', 1, 'Load × load arm = effort × effort arm.', '{"why":"Both moments equal 30 N m.","sol":"Step 1: 100 × 0.3 = F × 1.5\nStep 2: 30 = 1.5F\nStep 3: F = 20 N","steps":["Step 1: 100 × 0.3 = F × 1.5","Step 2: 30 = 1.5F","Step 3: F = 20 N"],"options":[],"conceptId":"physics_moments_and_equilibrium_finding_an_unknown_force_using_moments","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q2","subject":"physics","chapter":"moments_and_equilibrium","topic":"Finding an Unknown Force Using Moments"}', 1),
  (1642, 427, 'A 25 N force acts 0.8 m from a pivot. A balancing force acts 0.4 m away on the opposite side. Find the force.', 'text', 1, 'Find the moment first.', '{"why":"A shorter arm requires a greater force to produce the same moment.","sol":"Step 1: 25 × 0.8 = F × 0.4\nStep 2: 20 = 0.4F\nStep 3: F = 50 N","steps":["Step 1: 25 × 0.8 = F × 0.4","Step 2: 20 = 0.4F","Step 3: F = 50 N"],"options":[],"conceptId":"physics_moments_and_equilibrium_finding_an_unknown_force_using_moments","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q3","subject":"physics","chapter":"moments_and_equilibrium","topic":"Finding an Unknown Force Using Moments"}', 2),
  (1643, 427, 'A 15 N effort acts 2 m from a pivot. A load acts 0.5 m from the pivot. Find the load for equilibrium.', 'text', 1, 'Equate effort moment and load moment.', '{"why":"The effort produces a moment of 30 N m, which the load must match.","sol":"Step 1: 15 × 2 = L × 0.5\nStep 2: 30 = 0.5L\nStep 3: L = 60 N","steps":["Step 1: 15 × 2 = L × 0.5","Step 2: 30 = 0.5L","Step 3: L = 60 N"],"options":[],"conceptId":"physics_moments_and_equilibrium_finding_an_unknown_force_using_moments","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q4","subject":"physics","chapter":"moments_and_equilibrium","topic":"Finding an Unknown Force Using Moments"}', 3),
  (1644, 427, 'A learner calculates the balancing force by dividing the load by the effort-arm distance without using the load moment. What is missing?', 'text', 1, 'Both sides of the pivot must be considered.', '{"why":"The balancing force depends on both the load and its distance from the pivot.","sol":"Step 1: Calculate the load moment: load × load arm.\nStep 2: Equate it to effort × effort arm.\nStep 3: Rearrange to find the unknown effort.","steps":["Step 1: Calculate the load moment: load × load arm.","Step 2: Equate it to effort × effort arm.","Step 3: Rearrange to find the unknown effort."],"options":[],"conceptId":"physics_moments_and_equilibrium_finding_an_unknown_force_using_moments","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q5","subject":"physics","chapter":"moments_and_equilibrium","topic":"Finding an Unknown Force Using Moments"}', 4),
  (1645, 428, 'Two forces produce clockwise moments of 12 N m and 8 N m. What total anticlockwise moment is required for equilibrium?', 'text', 1, 'The totals must balance.', '{"why":"Equilibrium requires equal total clockwise and anticlockwise moments.","sol":"Step 1: Total clockwise moment = 12 + 8 = 20 N m.\nStep 2: Required anticlockwise moment = 20 N m.","steps":["Step 1: Total clockwise moment = 12 + 8 = 20 N m.","Step 2: Required anticlockwise moment = 20 N m."],"options":[],"conceptId":"physics_moments_and_equilibrium_moments_from_several_forces","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q1","subject":"physics","chapter":"moments_and_equilibrium","topic":"Moments from Several Forces"}', 0),
  (1646, 428, 'Clockwise moments total 45 N m. Two anticlockwise moments are 15 N m and 10 N m. What additional anticlockwise moment is needed?', 'text', 1, 'Add known moments, then find the difference.', '{"why":"The anticlockwise total must reach 45 N m.","sol":"Step 1: Known anticlockwise total = 15 + 10 = 25 N m.\nStep 2: Additional moment = 45 − 25 = 20 N m.","steps":["Step 1: Known anticlockwise total = 15 + 10 = 25 N m.","Step 2: Additional moment = 45 − 25 = 20 N m."],"options":[],"conceptId":"physics_moments_and_equilibrium_moments_from_several_forces","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q2","subject":"physics","chapter":"moments_and_equilibrium","topic":"Moments from Several Forces"}', 1),
  (1647, 428, 'A 10 N force and a 15 N force act clockwise at perpendicular distances of 2 m and 1 m. Calculate the total clockwise moment.', 'text', 1, 'Calculate each moment separately.', '{"why":"Moments acting in the same rotational direction are added.","sol":"Step 1: First moment = 10 × 2 = 20 N m.\nStep 2: Second moment = 15 × 1 = 15 N m.\nStep 3: Total = 35 N m clockwise.","steps":["Step 1: First moment = 10 × 2 = 20 N m.","Step 2: Second moment = 15 × 1 = 15 N m.","Step 3: Total = 35 N m clockwise."],"options":[],"conceptId":"physics_moments_and_equilibrium_moments_from_several_forces","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q3","subject":"physics","chapter":"moments_and_equilibrium","topic":"Moments from Several Forces"}', 2),
  (1648, 428, 'The clockwise moment is 30 N m and the anticlockwise moment is 18 N m. What is the net moment?', 'text', 1, 'Subtract the smaller total from the larger.', '{"why":"The resultant turning effect follows the larger moment.","sol":"Step 1: Net moment = 30 − 18 = 12 N m.\nStep 2: The clockwise moment is larger.","steps":["Step 1: Net moment = 30 − 18 = 12 N m.","Step 2: The clockwise moment is larger."],"options":[],"conceptId":"physics_moments_and_equilibrium_moments_from_several_forces","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q4","subject":"physics","chapter":"moments_and_equilibrium","topic":"Moments from Several Forces"}', 3),
  (1649, 428, 'Why should all moments be calculated about the same pivot when checking equilibrium?', 'text', 1, 'The moment depends on distance from the pivot.', '{"why":"The principle compares moments about one common pivot.","sol":"Step 1: Moment depends on perpendicular distance from the chosen pivot.\nStep 2: Using different pivots would mix different distances and turning effects.","steps":["Step 1: Moment depends on perpendicular distance from the chosen pivot.","Step 2: Using different pivots would mix different distances and turning effects."],"options":[],"conceptId":"physics_moments_and_equilibrium_moments_from_several_forces","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q5","subject":"physics","chapter":"moments_and_equilibrium","topic":"Moments from Several Forces"}', 4),
  (1650, 429, 'What two conditions must be satisfied for static equilibrium?', 'text', 1, 'Consider translation and rotation.', '{"why":"Both linear and rotational acceleration must be zero.","sol":"Step 1: Resultant force = 0.\nStep 2: Resultant moment = 0.","steps":["Step 1: Resultant force = 0.","Step 2: Resultant moment = 0."],"options":[],"conceptId":"physics_moments_and_equilibrium_equilibrium_of_a_beam","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q1","subject":"physics","chapter":"moments_and_equilibrium","topic":"Equilibrium of a Beam"}', 0),
  (1651, 429, 'A beam has clockwise moments of 16 N m and anticlockwise moments of 16 N m. Find the net moment.', 'text', 1, 'Subtract the opposing totals.', '{"why":"The clockwise and anticlockwise moments cancel.","sol":"Step 1: Net moment = 16 − 16\nStep 2: Net moment = 0 N m","steps":["Step 1: Net moment = 16 − 16","Step 2: Net moment = 0 N m"],"options":[],"conceptId":"physics_moments_and_equilibrium_equilibrium_of_a_beam","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q2","subject":"physics","chapter":"moments_and_equilibrium","topic":"Equilibrium of a Beam"}', 1),
  (1652, 429, 'A beam has zero resultant moment, but a non-zero resultant force. Is it in static equilibrium?', 'text', 1, 'Check both equilibrium conditions.', '{"why":"Static equilibrium requires both zero resultant force and zero resultant moment.","sol":"Step 1: The moment condition is satisfied.\nStep 2: The force condition is not satisfied.\nStep 3: Therefore, static equilibrium is not satisfied.","steps":["Step 1: The moment condition is satisfied.","Step 2: The force condition is not satisfied.","Step 3: Therefore, static equilibrium is not satisfied."],"options":[],"conceptId":"physics_moments_and_equilibrium_equilibrium_of_a_beam","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q3","subject":"physics","chapter":"moments_and_equilibrium","topic":"Equilibrium of a Beam"}', 2),
  (1653, 429, 'A stationary beam has balanced forces but unequal clockwise and anticlockwise moments. What does this tell you?', 'text', 1, 'Consider whether it can remain rotationally balanced.', '{"why":"Unequal moments create a resultant turning effect.","sol":"Step 1: The resultant force is zero.\nStep 2: The resultant moment is not zero.\nStep 3: The beam is not in rotational equilibrium.","steps":["Step 1: The resultant force is zero.","Step 2: The resultant moment is not zero.","Step 3: The beam is not in rotational equilibrium."],"options":[],"conceptId":"physics_moments_and_equilibrium_equilibrium_of_a_beam","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q4","subject":"physics","chapter":"moments_and_equilibrium","topic":"Equilibrium of a Beam"}', 3),
  (1654, 429, 'A learner checks only the forces when deciding whether a beam is in equilibrium. What else must be checked?', 'text', 1, 'A beam can rotate as well as move.', '{"why":"Balanced forces alone do not guarantee rotational equilibrium.","sol":"Step 1: Calculate total clockwise moments.\nStep 2: Calculate total anticlockwise moments.\nStep 3: Confirm that the totals are equal.","steps":["Step 1: Calculate total clockwise moments.","Step 2: Calculate total anticlockwise moments.","Step 3: Confirm that the totals are equal."],"options":[],"conceptId":"physics_moments_and_equilibrium_equilibrium_of_a_beam","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q5","subject":"physics","chapter":"moments_and_equilibrium","topic":"Equilibrium of a Beam"}', 4),
  (1655, 430, 'Define the centre of gravity.', 'text', 1, 'Consider the resultant gravitational force.', '{"why":"The centre of gravity represents the overall effect of gravity on the object.","sol":"Step 1: Gravity acts on every part of an object.\nStep 2: The combined effect can be represented as acting through one point.","steps":["Step 1: Gravity acts on every part of an object.","Step 2: The combined effect can be represented as acting through one point."],"options":[],"conceptId":"physics_moments_and_equilibrium_centre_of_gravity_and_balance","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q1","subject":"physics","chapter":"moments_and_equilibrium","topic":"Centre of Gravity and Balance"}', 0),
  (1656, 430, 'Where is the centre of gravity of a uniform metre rule usually located?', 'text', 1, 'Consider its uniform mass distribution.', '{"why":"For a uniform rule, the centre of gravity lies at its geometric centre.","sol":"Step 1: The rule has uniform mass distribution.\nStep 2: Its centre of gravity is at the midpoint.\nStep 3: The midpoint is the 50 cm mark.","steps":["Step 1: The rule has uniform mass distribution.","Step 2: Its centre of gravity is at the midpoint.","Step 3: The midpoint is the 50 cm mark."],"options":[],"conceptId":"physics_moments_and_equilibrium_centre_of_gravity_and_balance","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q2","subject":"physics","chapter":"moments_and_equilibrium","topic":"Centre of Gravity and Balance"}', 1),
  (1657, 430, 'Why might the centre of gravity of an irregular object not be at its geometric centre?', 'text', 1, 'Consider how its mass is distributed.', '{"why":"The centre of gravity depends on mass distribution, not simply shape.","sol":"Step 1: The object may have uneven mass distribution.\nStep 2: The resultant gravitational force depends on that distribution.","steps":["Step 1: The object may have uneven mass distribution.","Step 2: The resultant gravitational force depends on that distribution."],"options":[],"conceptId":"physics_moments_and_equilibrium_centre_of_gravity_and_balance","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q3","subject":"physics","chapter":"moments_and_equilibrium","topic":"Centre of Gravity and Balance"}', 2),
  (1658, 430, 'What force acts through an object''s centre of gravity?', 'text', 1, 'Think of the object''s total gravitational effect.', '{"why":"Weight acts through the centre of gravity.","sol":"Step 1: Gravity acts on the object''s parts.\nStep 2: The resultant gravitational force is represented as acting through the centre of gravity.","steps":["Step 1: Gravity acts on the object''s parts.","Step 2: The resultant gravitational force is represented as acting through the centre of gravity."],"options":[],"conceptId":"physics_moments_and_equilibrium_centre_of_gravity_and_balance","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q4","subject":"physics","chapter":"moments_and_equilibrium","topic":"Centre of Gravity and Balance"}', 3),
  (1659, 430, 'A learner says every object has its centre of gravity exactly at its geometric centre. Is this correct?', 'text', 1, 'Compare a uniform block with an irregular object.', '{"why":"The centre of gravity depends on the distribution of mass.","sol":"Step 1: A uniform, symmetrical object may have its centre of gravity at its geometric centre.\nStep 2: Uneven mass distribution can shift the centre of gravity.","steps":["Step 1: A uniform, symmetrical object may have its centre of gravity at its geometric centre.","Step 2: Uneven mass distribution can shift the centre of gravity."],"options":[],"conceptId":"physics_moments_and_equilibrium_centre_of_gravity_and_balance","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q5","subject":"physics","chapter":"moments_and_equilibrium","topic":"Centre of Gravity and Balance"}', 4),
  (1660, 431, 'What is the line of action of an object''s weight?', 'text', 1, 'It passes through the centre of gravity.', '{"why":"The line of action shows the direction and path along which weight acts.","sol":"Step 1: Weight acts vertically downward.\nStep 2: Its line of action is the vertical line through the centre of gravity.","steps":["Step 1: Weight acts vertically downward.","Step 2: Its line of action is the vertical line through the centre of gravity."],"options":[],"conceptId":"physics_moments_and_equilibrium_the_line_of_action_of_weight","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q1","subject":"physics","chapter":"moments_and_equilibrium","topic":"The Line of Action of Weight"}', 0),
  (1661, 431, 'For a resting object to be stable, where should the vertical line through its centre of gravity fall?', 'text', 1, 'Consider the base of support.', '{"why":"This prevents the object''s weight from producing a toppling moment about the edge.","sol":"Step 1: Identify the object''s supporting base.\nStep 2: Check where the vertical line through the centre of gravity meets the ground.\nStep 3: For stability, it should fall within the base.","steps":["Step 1: Identify the object''s supporting base.","Step 2: Check where the vertical line through the centre of gravity meets the ground.","Step 3: For stability, it should fall within the base."],"options":[],"conceptId":"physics_moments_and_equilibrium_the_line_of_action_of_weight","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q2","subject":"physics","chapter":"moments_and_equilibrium","topic":"The Line of Action of Weight"}', 1),
  (1662, 431, 'A block tilts until its centre-of-gravity line falls outside its base. What is likely to happen?', 'text', 1, 'Consider the turning effect of weight.', '{"why":"The weight now produces a turning effect that increases the tilt.","sol":"Step 1: The weight''s line of action lies outside the base.\nStep 2: Weight creates a turning effect about the base edge.\nStep 3: The block tends to topple.","steps":["Step 1: The weight''s line of action lies outside the base.","Step 2: Weight creates a turning effect about the base edge.","Step 3: The block tends to topple."],"options":[],"conceptId":"physics_moments_and_equilibrium_the_line_of_action_of_weight","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q3","subject":"physics","chapter":"moments_and_equilibrium","topic":"The Line of Action of Weight"}', 2),
  (1663, 431, 'Does a low centre of gravity alone guarantee stability if the support base is extremely narrow?', 'text', 1, 'Consider both height and base width.', '{"why":"Stability depends on both the centre of gravity and the base of support.","sol":"Step 1: A low centre of gravity generally helps stability.\nStep 2: The support base also matters.\nStep 3: A narrow base can still make an object easy to topple.","steps":["Step 1: A low centre of gravity generally helps stability.","Step 2: The support base also matters.","Step 3: A narrow base can still make an object easy to topple."],"options":[],"conceptId":"physics_moments_and_equilibrium_the_line_of_action_of_weight","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q4","subject":"physics","chapter":"moments_and_equilibrium","topic":"The Line of Action of Weight"}', 3),
  (1664, 431, 'A learner checks only the height of an object''s centre of gravity to decide whether it will topple. What else must be checked?', 'text', 1, 'Look at the support under the object.', '{"why":"The base determines whether the line of action of weight supports or topples the object.","sol":"Step 1: Locate the base of support.\nStep 2: Check whether the vertical line through the centre of gravity remains within it.","steps":["Step 1: Locate the base of support.","Step 2: Check whether the vertical line through the centre of gravity remains within it."],"options":[],"conceptId":"physics_moments_and_equilibrium_the_line_of_action_of_weight","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q5","subject":"physics","chapter":"moments_and_equilibrium","topic":"The Line of Action of Weight"}', 4),
  (1665, 432, 'State two ways of increasing an object''s stability.', 'text', 1, 'Consider its centre of gravity and base.', '{"why":"Both changes make toppling less likely.","sol":"Step 1: Lower the centre of gravity.\nStep 2: Increase the width of the base of support.","steps":["Step 1: Lower the centre of gravity.","Step 2: Increase the width of the base of support."],"options":[],"conceptId":"physics_moments_and_equilibrium_increasing_the_stability_of_an_object","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q1","subject":"physics","chapter":"moments_and_equilibrium","topic":"Increasing the Stability of an Object"}', 0),
  (1666, 432, 'Why does widening an object''s base generally increase stability?', 'text', 1, 'Consider how far the centre-of-gravity line can move before reaching an edge.', '{"why":"A wider base increases the range over which the object can remain supported.","sol":"Step 1: A wider base provides a larger support area.\nStep 2: The centre-of-gravity line can move farther before leaving the base.","steps":["Step 1: A wider base provides a larger support area.","Step 2: The centre-of-gravity line can move farther before leaving the base."],"options":[],"conceptId":"physics_moments_and_equilibrium_increasing_the_stability_of_an_object","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q2","subject":"physics","chapter":"moments_and_equilibrium","topic":"Increasing the Stability of an Object"}', 1),
  (1667, 432, 'Why are heavy objects often placed low in a vehicle?', 'text', 1, 'Consider the centre of gravity.', '{"why":"A lower centre of gravity helps keep the weight''s line of action within the support base.","sol":"Step 1: Placing mass low lowers the vehicle''s centre of gravity.\nStep 2: A lower centre of gravity generally improves stability.","steps":["Step 1: Placing mass low lowers the vehicle''s centre of gravity.","Step 2: A lower centre of gravity generally improves stability."],"options":[],"conceptId":"physics_moments_and_equilibrium_increasing_the_stability_of_an_object","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q3","subject":"physics","chapter":"moments_and_equilibrium","topic":"Increasing the Stability of an Object"}', 2),
  (1668, 432, 'Two objects have the same base width. One has a lower centre of gravity. Which is generally more stable?', 'text', 1, 'Compare how the centre-of-gravity line shifts when tilted.', '{"why":"A lower centre of gravity generally increases resistance to toppling.","sol":"Step 1: The lower centre of gravity shifts less horizontally for a small tilt.\nStep 2: Its line of action is less likely to leave the base.","steps":["Step 1: The lower centre of gravity shifts less horizontally for a small tilt.","Step 2: Its line of action is less likely to leave the base."],"options":[],"conceptId":"physics_moments_and_equilibrium_increasing_the_stability_of_an_object","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q4","subject":"physics","chapter":"moments_and_equilibrium","topic":"Increasing the Stability of an Object"}', 3),
  (1669, 432, 'A learner wants to improve a narrow-based model''s stability but cannot change its height. What useful change could they make?', 'text', 1, 'Consider the support base.', '{"why":"A wider base improves stability even if the height stays the same.","sol":"Step 1: Keep the height unchanged.\nStep 2: Increase the width of the supporting base.","steps":["Step 1: Keep the height unchanged.","Step 2: Increase the width of the supporting base."],"options":[],"conceptId":"physics_moments_and_equilibrium_increasing_the_stability_of_an_object","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q5","subject":"physics","chapter":"moments_and_equilibrium","topic":"Increasing the Stability of an Object"}', 4),
  (1670, 433, 'What condition signals that an object is at the limiting point of toppling?', 'text', 1, 'Check the line of action of its weight.', '{"why":"Beyond this point, the weight produces a toppling moment.","sol":"Step 1: Locate the base edge about which it may rotate.\nStep 2: At the limiting condition, the vertical line through the centre of gravity reaches that edge.","steps":["Step 1: Locate the base edge about which it may rotate.","Step 2: At the limiting condition, the vertical line through the centre of gravity reaches that edge."],"options":[],"conceptId":"physics_moments_and_equilibrium_toppling_and_the_turning_effect_of_weight","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q1","subject":"physics","chapter":"moments_and_equilibrium","topic":"Toppling and the Turning Effect of Weight"}', 0),
  (1671, 433, 'What causes the weight of an object to produce a toppling moment?', 'text', 1, 'Consider where the line of action falls relative to the base.', '{"why":"A non-zero perpendicular distance from the pivoting edge creates a moment.","sol":"Step 1: The centre-of-gravity line falls outside the base.\nStep 2: The weight then has a perpendicular distance from the pivoting edge.\nStep 3: Weight produces a moment about that edge.","steps":["Step 1: The centre-of-gravity line falls outside the base.","Step 2: The weight then has a perpendicular distance from the pivoting edge.","Step 3: Weight produces a moment about that edge."],"options":[],"conceptId":"physics_moments_and_equilibrium_toppling_and_the_turning_effect_of_weight","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q2","subject":"physics","chapter":"moments_and_equilibrium","topic":"Toppling and the Turning Effect of Weight"}', 1),
  (1672, 433, 'Is sliding the same as toppling?', 'text', 1, 'Compare translation with rotation.', '{"why":"Sliding and toppling are different types of motion.","sol":"Step 1: Sliding is movement along the surface.\nStep 2: Toppling is rotation about an edge or contact point.","steps":["Step 1: Sliding is movement along the surface.","Step 2: Toppling is rotation about an edge or contact point."],"options":[],"conceptId":"physics_moments_and_equilibrium_toppling_and_the_turning_effect_of_weight","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q3","subject":"physics","chapter":"moments_and_equilibrium","topic":"Toppling and the Turning Effect of Weight"}', 2),
  (1673, 433, 'A box is tilted, but its weight''s line of action remains within its base. What does this suggest?', 'text', 1, 'The weight has not yet created a toppling moment about the base edge in the stated way.', '{"why":"Toppling occurs when the line of action moves beyond the supporting base.","sol":"Step 1: The line of action remains within the support base.\nStep 2: The weight does not yet produce the toppling moment described for the line outside the base.","steps":["Step 1: The line of action remains within the support base.","Step 2: The weight does not yet produce the toppling moment described for the line outside the base."],"options":[],"conceptId":"physics_moments_and_equilibrium_toppling_and_the_turning_effect_of_weight","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q4","subject":"physics","chapter":"moments_and_equilibrium","topic":"Toppling and the Turning Effect of Weight"}', 3),
  (1674, 433, 'A learner says an object topples because its centre of gravity physically moves outside the object. Correct the statement.', 'text', 1, 'The important comparison is with the base of support.', '{"why":"The object''s support geometry, not whether its centre of gravity lies outside its body, determines the toppling condition.","sol":"Step 1: The centre of gravity need not leave the object''s material shape.\nStep 2: Its vertical line of action must move outside the base of support for the toppling condition described.","steps":["Step 1: The centre of gravity need not leave the object''s material shape.","Step 2: Its vertical line of action must move outside the base of support for the toppling condition described."],"options":[],"conceptId":"physics_moments_and_equilibrium_toppling_and_the_turning_effect_of_weight","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q5","subject":"physics","chapter":"moments_and_equilibrium","topic":"Toppling and the Turning Effect of Weight"}', 4),
  (1675, 434, 'A force of 25 N acts perpendicularly at the end of a spanner 0.2 m long. Calculate the moment about the nut.', 'text', 1, 'Multiply force by perpendicular distance.', '{"why":"The force acts perpendicularly at a distance of 0.2 m from the pivot.","sol":"Step 1: Moment = 25 × 0.2\nStep 2: Moment = 5 N m","steps":["Step 1: Moment = 25 × 0.2","Step 2: Moment = 5 N m"],"options":[],"conceptId":"physics_moments_and_equilibrium_applying_moments_to_everyday_tools","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q1","subject":"physics","chapter":"moments_and_equilibrium","topic":"Applying Moments to Everyday Tools"}', 0),
  (1676, 434, 'A 30 N force acts at a perpendicular distance of 0.4 m from a door hinge. Calculate its moment about the hinge.', 'text', 1, 'Use moment = force × distance.', '{"why":"The hinge is the pivot and the given distance is perpendicular.","sol":"Step 1: Moment = 30 × 0.4\nStep 2: Moment = 12 N m","steps":["Step 1: Moment = 30 × 0.4","Step 2: Moment = 12 N m"],"options":[],"conceptId":"physics_moments_and_equilibrium_applying_moments_to_everyday_tools","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q2","subject":"physics","chapter":"moments_and_equilibrium","topic":"Applying Moments to Everyday Tools"}', 1),
  (1677, 434, 'Why is a longer spanner usually more effective at loosening a tight nut?', 'text', 1, 'Assume the applied force is unchanged.', '{"why":"Increasing the moment arm increases the turning effect.","sol":"Step 1: A longer spanner increases the perpendicular distance from the pivot.\nStep 2: Moment = force × distance.\nStep 3: The turning effect increases.","steps":["Step 1: A longer spanner increases the perpendicular distance from the pivot.","Step 2: Moment = force × distance.","Step 3: The turning effect increases."],"options":[],"conceptId":"physics_moments_and_equilibrium_applying_moments_to_everyday_tools","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q3","subject":"physics","chapter":"moments_and_equilibrium","topic":"Applying Moments to Everyday Tools"}', 2),
  (1678, 434, 'A 50 N force produces a moment of 15 N m. Find the perpendicular distance from the pivot.', 'text', 1, 'Distance = moment/force.', '{"why":"Rearranging moment = force × distance gives distance = moment/force.","sol":"Step 1: d = 15/50\nStep 2: d = 0.3 m","steps":["Step 1: d = 15/50","Step 2: d = 0.3 m"],"options":[],"conceptId":"physics_moments_and_equilibrium_applying_moments_to_everyday_tools","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q4","subject":"physics","chapter":"moments_and_equilibrium","topic":"Applying Moments to Everyday Tools"}', 3),
  (1679, 434, 'A learner uses the length of a handle as the moment arm even though the force acts at an angle. What distance should be used?', 'text', 1, 'Moments depend on the perpendicular distance.', '{"why":"The perpendicular distance, not necessarily the handle''s full length, determines the moment.","sol":"Step 1: Identify the force''s line of action.\nStep 2: Measure the perpendicular distance from the pivot to that line.","steps":["Step 1: Identify the force''s line of action.","Step 2: Measure the perpendicular distance from the pivot to that line."],"options":[],"conceptId":"physics_moments_and_equilibrium_applying_moments_to_everyday_tools","skillId":"physics_moments_and_equilibrium","subskillId":"physics_moments_and_equilibrium_q5","subject":"physics","chapter":"moments_and_equilibrium","topic":"Applying Moments to Everyday Tools"}', 4),
  (1680, 435, 'A 12 N force moves a box 4 m in the direction of the force. Calculate the work done.', 'text', 1, 'Work = force × distance moved in the force''s direction.', '{"why":"Work done equals force multiplied by displacement in the force''s direction.","sol":"Step 1: Write W = Fs.\nStep 2: Substitute W = 12 × 4.\nStep 3: Calculate W = 48 J.","steps":["Step 1: Write W = Fs.","Step 2: Substitute W = 12 × 4.","Step 3: Calculate W = 48 J."],"options":[],"conceptId":"physics_work_energy_power_work_done_by_a_force","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q1","subject":"physics","chapter":"work_energy_power","topic":"Work Done by a Force"}', 0),
  (1681, 435, 'A force of 80 N moves an object 0.5 m in the force''s direction. Find the work done.', 'text', 1, 'Multiply 80 by 0.5.', '{"why":"Work is measured in joules.","sol":"Step 1: Write W = Fs.\nStep 2: Substitute W = 80 × 0.5.\nStep 3: Calculate W = 40 J.","steps":["Step 1: Write W = Fs.","Step 2: Substitute W = 80 × 0.5.","Step 3: Calculate W = 40 J."],"options":[],"conceptId":"physics_work_energy_power_work_done_by_a_force","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q2","subject":"physics","chapter":"work_energy_power","topic":"Work Done by a Force"}', 1),
  (1682, 435, 'A force of 25 N does 100 J of work while moving an object in the force''s direction. Find the distance moved.', 'text', 1, 'Distance = work ÷ force.', '{"why":"Rearranging W = Fs gives the displacement for a constant force along the displacement.","sol":"Step 1: Start with W = Fs.\nStep 2: Rearrange to s = W/F.\nStep 3: Substitute s = 100/25 = 4 m.","steps":["Step 1: Start with W = Fs.","Step 2: Rearrange to s = W/F.","Step 3: Substitute s = 100/25 = 4 m."],"options":[],"conceptId":"physics_work_energy_power_work_done_by_a_force","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q3","subject":"physics","chapter":"work_energy_power","topic":"Work Done by a Force"}', 2),
  (1683, 435, 'A person holds a bag stationary for 20 seconds. What is the mechanical work done by the person''s supporting force on the bag?', 'text', 1, 'Check whether the bag has any displacement.', '{"why":"No displacement means zero mechanical work by the supporting force on the bag.","sol":"Step 1: The supporting force acts upward.\nStep 2: The bag remains stationary, so its displacement is zero.\nStep 3: Work done on the bag by that force is zero.","steps":["Step 1: The supporting force acts upward.","Step 2: The bag remains stationary, so its displacement is zero.","Step 3: Work done on the bag by that force is zero."],"options":[],"conceptId":"physics_work_energy_power_work_done_by_a_force","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q4","subject":"physics","chapter":"work_energy_power","topic":"Work Done by a Force"}', 3),
  (1684, 435, 'A 15 N force moves an object 2 m in the same direction as the force. Calculate the work done.', 'text', 1, 'Use W = Fs.', '{"why":"Work done is the product of force and displacement along the force''s direction.","sol":"Step 1: Write W = Fs.\nStep 2: Substitute W = 15 × 2.\nStep 3: Calculate W = 30 J.","steps":["Step 1: Write W = Fs.","Step 2: Substitute W = 15 × 2.","Step 3: Calculate W = 30 J."],"options":[],"conceptId":"physics_work_energy_power_work_done_by_a_force","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q5","subject":"physics","chapter":"work_energy_power","topic":"Work Done by a Force"}', 4),
  (1685, 436, 'A 3 kg object is lifted 4 m vertically. Take g = 10 N/kg. Calculate its gain in gravitational potential energy.', 'text', 1, 'Use ΔEp = mgΔh.', '{"why":"Lifting the object increases its gravitational potential energy.","sol":"Step 1: Write ΔEp = mgΔh.\nStep 2: Substitute ΔEp = 3 × 10 × 4.\nStep 3: Calculate ΔEp = 120 J.","steps":["Step 1: Write ΔEp = mgΔh.","Step 2: Substitute ΔEp = 3 × 10 × 4.","Step 3: Calculate ΔEp = 120 J."],"options":[],"conceptId":"physics_work_energy_power_gravitational_potential_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q1","subject":"physics","chapter":"work_energy_power","topic":"Gravitational Potential Energy"}', 0),
  (1686, 436, 'A 6 kg object gains 300 J of gravitational potential energy. Take g = 10 N/kg. How far vertically is it lifted?', 'text', 1, 'Rearrange ΔEp = mgΔh.', '{"why":"Height change equals energy change divided by mass times gravitational field strength.","sol":"Step 1: Write Δh = ΔEp/(mg).\nStep 2: Substitute Δh = 300/(6 × 10).\nStep 3: Calculate Δh = 5 m.","steps":["Step 1: Write Δh = ΔEp/(mg).","Step 2: Substitute Δh = 300/(6 × 10).","Step 3: Calculate Δh = 5 m."],"options":[],"conceptId":"physics_work_energy_power_gravitational_potential_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q2","subject":"physics","chapter":"work_energy_power","topic":"Gravitational Potential Energy"}', 1),
  (1687, 436, 'Calculate the gain in gravitational potential energy of a 2.5 kg object lifted 2 m where g = 10 N/kg.', 'text', 1, 'Multiply mass, gravitational field strength and vertical height change.', '{"why":"The object''s potential energy increases by 50 J.","sol":"Step 1: Write ΔEp = mgΔh.\nStep 2: Substitute ΔEp = 2.5 × 10 × 2.\nStep 3: Calculate ΔEp = 50 J.","steps":["Step 1: Write ΔEp = mgΔh.","Step 2: Substitute ΔEp = 2.5 × 10 × 2.","Step 3: Calculate ΔEp = 50 J."],"options":[],"conceptId":"physics_work_energy_power_gravitational_potential_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q3","subject":"physics","chapter":"work_energy_power","topic":"Gravitational Potential Energy"}', 2),
  (1688, 436, 'An object of mass 4 kg is raised by 3 m. Take g = 9.8 N/kg. Calculate the increase in gravitational potential energy.', 'text', 1, 'Use ΔEp = mgΔh with g = 9.8 N/kg.', '{"why":"Use the gravitational field strength supplied in the question.","sol":"Step 1: Write ΔEp = mgΔh.\nStep 2: Substitute ΔEp = 4 × 9.8 × 3.\nStep 3: Calculate ΔEp = 117.6 J.","steps":["Step 1: Write ΔEp = mgΔh.","Step 2: Substitute ΔEp = 4 × 9.8 × 3.","Step 3: Calculate ΔEp = 117.6 J."],"options":[],"conceptId":"physics_work_energy_power_gravitational_potential_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q4","subject":"physics","chapter":"work_energy_power","topic":"Gravitational Potential Energy"}', 3),
  (1689, 436, 'Which measurement is required in ΔEp = mgΔh: the total distance along the path or the vertical height change?', 'text', 1, 'Gravitational potential energy depends on how much higher or lower the object ends up.', '{"why":"Near Earth''s surface, gravitational potential energy change depends on vertical height change.","sol":"Step 1: Identify the energy change being calculated.\nStep 2: Gravitational potential energy depends on vertical position.\nStep 3: Use the vertical height change.","steps":["Step 1: Identify the energy change being calculated.","Step 2: Gravitational potential energy depends on vertical position.","Step 3: Use the vertical height change."],"options":[],"conceptId":"physics_work_energy_power_gravitational_potential_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q5","subject":"physics","chapter":"work_energy_power","topic":"Gravitational Potential Energy"}', 4),
  (1690, 437, 'Calculate the kinetic energy of a 2 kg object moving at 4 m/s.', 'text', 1, 'Use KE = 1/2 × m × v².', '{"why":"KE = 1/2 × 2 × 16 = 16 J.","sol":"Step 1: Write KE = 1/2 × m × v².\nStep 2: Substitute m = 2 and v = 4.\nStep 3: KE = 1/2 × 2 × 4² = 16 J.","steps":["Step 1: Write KE = 1/2 × m × v².","Step 2: Substitute m = 2 and v = 4.","Step 3: KE = 1/2 × 2 × 4² = 16 J."],"options":[],"conceptId":"physics_work_energy_power_kinetic_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q1","subject":"physics","chapter":"work_energy_power","topic":"Kinetic Energy"}', 0),
  (1691, 437, 'A 5 kg object moves at 2 m/s. Find its kinetic energy.', 'text', 1, 'Square 2, then multiply by half of 5.', '{"why":"KE = 1/2 × 5 × 4 = 10 J.","sol":"Step 1: KE = 1/2 × 5 × 2².\nStep 2: 2² = 4.\nStep 3: KE = 2.5 × 4 = 10 J.","steps":["Step 1: KE = 1/2 × 5 × 2².","Step 2: 2² = 4.","Step 3: KE = 2.5 × 4 = 10 J."],"options":[],"conceptId":"physics_work_energy_power_kinetic_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q2","subject":"physics","chapter":"work_energy_power","topic":"Kinetic Energy"}', 1),
  (1692, 437, 'A 3 kg object has a speed of 6 m/s. Calculate its kinetic energy.', 'text', 1, 'Calculate 6² first.', '{"why":"The squared speed is 36, giving KE = 54 J.","sol":"Step 1: KE = 1/2 × 3 × 6².\nStep 2: 6² = 36.\nStep 3: KE = 1.5 × 36 = 54 J.","steps":["Step 1: KE = 1/2 × 3 × 6².","Step 2: 6² = 36.","Step 3: KE = 1.5 × 36 = 54 J."],"options":[],"conceptId":"physics_work_energy_power_kinetic_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q3","subject":"physics","chapter":"work_energy_power","topic":"Kinetic Energy"}', 2),
  (1693, 437, 'An object of mass 4 kg moves at 5 m/s. What is its kinetic energy?', 'text', 1, 'Half the mass is 2 kg; multiply this by 5².', '{"why":"KE = 2 × 25 = 50 J.","sol":"Step 1: KE = 1/2 × 4 × 5².\nStep 2: 5² = 25.\nStep 3: KE = 2 × 25 = 50 J.","steps":["Step 1: KE = 1/2 × 4 × 5².","Step 2: 5² = 25.","Step 3: KE = 2 × 25 = 50 J."],"options":[],"conceptId":"physics_work_energy_power_kinetic_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q4","subject":"physics","chapter":"work_energy_power","topic":"Kinetic Energy"}', 3),
  (1694, 437, 'A moving object''s speed doubles while its mass remains constant. By what factor does its kinetic energy change?', 'text', 1, 'Compare v² with (2v)².', '{"why":"Kinetic energy depends on the square of speed.","sol":"Step 1: Original dependence is v².\nStep 2: New dependence is (2v)² = 4v².\nStep 3: The kinetic energy becomes four times the original.","steps":["Step 1: Original dependence is v².","Step 2: New dependence is (2v)² = 4v².","Step 3: The kinetic energy becomes four times the original."],"options":[],"conceptId":"physics_work_energy_power_kinetic_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q5","subject":"physics","chapter":"work_energy_power","topic":"Kinetic Energy"}', 4),
  (1695, 438, 'State the principle of conservation of energy.', 'text', 1, 'Think about whether energy can be created or destroyed.', '{"why":"Energy may change form or move to the surroundings, but it is conserved.","sol":"Step 1: Identify what happens to total energy.\nStep 2: Distinguish transformation from destruction.","steps":["Step 1: Identify what happens to total energy.","Step 2: Distinguish transformation from destruction."],"options":[],"conceptId":"physics_work_energy_power_conservation_of_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q1","subject":"physics","chapter":"work_energy_power","topic":"Conservation of Energy"}', 0),
  (1696, 438, 'Describe the main energy transformation when an object falls freely, ignoring air resistance.', 'text', 1, 'Compare energy at the top and during the fall.', '{"why":"The energy changes form as the object loses height.","sol":"Step 1: At the top, gravitational potential energy is present.\nStep 2: As the object falls, potential energy decreases.\nStep 3: Kinetic energy increases.","steps":["Step 1: At the top, gravitational potential energy is present.","Step 2: As the object falls, potential energy decreases.","Step 3: Kinetic energy increases."],"options":[],"conceptId":"physics_work_energy_power_conservation_of_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q2","subject":"physics","chapter":"work_energy_power","topic":"Conservation of Energy"}', 1),
  (1697, 438, 'A moving object slows down because of friction. Where does some of its kinetic energy go?', 'text', 1, 'Consider the surfaces in contact.', '{"why":"Friction transfers mechanical energy into other forms.","sol":"Step 1: Friction opposes motion.\nStep 2: Mechanical energy is transferred to the objects and surroundings.\nStep 3: The energy commonly increases thermal energy and may produce sound.","steps":["Step 1: Friction opposes motion.","Step 2: Mechanical energy is transferred to the objects and surroundings.","Step 3: The energy commonly increases thermal energy and may produce sound."],"options":[],"conceptId":"physics_work_energy_power_conservation_of_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q3","subject":"physics","chapter":"work_energy_power","topic":"Conservation of Energy"}', 2),
  (1698, 438, 'In an ideal falling-object system with no air resistance, what happens to the total of gravitational potential energy and kinetic energy?', 'text', 1, 'Add the two forms of mechanical energy.', '{"why":"Energy changes form, while the total mechanical energy stays constant under the stated conditions.","sol":"Step 1: Potential energy decreases.\nStep 2: Kinetic energy increases by the same amount.\nStep 3: Their sum remains constant.","steps":["Step 1: Potential energy decreases.","Step 2: Kinetic energy increases by the same amount.","Step 3: Their sum remains constant."],"options":[],"conceptId":"physics_work_energy_power_conservation_of_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q4","subject":"physics","chapter":"work_energy_power","topic":"Conservation of Energy"}', 3),
  (1699, 438, 'A machine receives 100 J of energy and transfers 30 J to its surroundings as heat. How much useful energy remains in the output?', 'text', 1, 'Subtract the energy transferred away from the useful output.', '{"why":"The energy balance is 100 J = 70 J + 30 J.","sol":"Step 1: Input energy = 100 J.\nStep 2: Energy transferred to surroundings = 30 J.\nStep 3: Useful output = 100 − 30 = 70 J.","steps":["Step 1: Input energy = 100 J.","Step 2: Energy transferred to surroundings = 30 J.","Step 3: Useful output = 100 − 30 = 70 J."],"options":[],"conceptId":"physics_work_energy_power_conservation_of_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q5","subject":"physics","chapter":"work_energy_power","topic":"Conservation of Energy"}', 4),
  (1700, 439, 'A machine does 200 J of work in 10 s. Calculate its power.', 'text', 1, 'Divide work done by time.', '{"why":"P = 200 J ÷ 10 s = 20 W.","sol":"Step 1: P = 200/10.\nStep 2: P = 20 W.","steps":["Step 1: P = 200/10.","Step 2: P = 20 W."],"options":[],"conceptId":"physics_work_energy_power_power","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q1","subject":"physics","chapter":"work_energy_power","topic":"Power"}', 0),
  (1701, 439, 'A motor transfers 900 J of energy in 30 s. Find its power.', 'text', 1, 'Use energy transferred divided by time.', '{"why":"P = 900 J ÷ 30 s = 30 W.","sol":"Step 1: P = 900/30.\nStep 2: P = 30 W.","steps":["Step 1: P = 900/30.","Step 2: P = 30 W."],"options":[],"conceptId":"physics_work_energy_power_power","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q2","subject":"physics","chapter":"work_energy_power","topic":"Power"}', 1),
  (1702, 439, 'A device has a power output of 50 W for 4 s. How much energy does it transfer?', 'text', 1, 'Rearrange P = E/t to make E the subject.', '{"why":"E = 50 J/s × 4 s = 200 J.","sol":"Step 1: E = P × t.\nStep 2: E = 50 × 4.\nStep 3: E = 200 J.","steps":["Step 1: E = P × t.","Step 2: E = 50 × 4.","Step 3: E = 200 J."],"options":[],"conceptId":"physics_work_energy_power_power","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q3","subject":"physics","chapter":"work_energy_power","topic":"Power"}', 2),
  (1703, 439, 'Two students each do 600 J of work. One takes 10 s and the other takes 20 s. Find each student''s power.', 'text', 1, 'Calculate 600 divided by each student''s time.', '{"why":"Power depends on both the work done and the time taken.","sol":"Step 1: First student: 600/10 = 60 W.\nStep 2: Second student: 600/20 = 30 W.","steps":["Step 1: First student: 600/10 = 60 W.","Step 2: Second student: 600/20 = 30 W."],"options":[],"conceptId":"physics_work_energy_power_power","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q4","subject":"physics","chapter":"work_energy_power","topic":"Power"}', 3),
  (1704, 439, 'A pump transfers 2,400 J in 2 minutes. Calculate its average power in watts.', 'text', 1, 'Convert 2 minutes into seconds first.', '{"why":"P = 2400 J ÷ 120 s = 20 W.","sol":"Step 1: Convert time: 2 × 60 = 120 s.\nStep 2: P = 2400/120.\nStep 3: P = 20 W.","steps":["Step 1: Convert time: 2 × 60 = 120 s.","Step 2: P = 2400/120.","Step 3: P = 20 W."],"options":[],"conceptId":"physics_work_energy_power_power","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q5","subject":"physics","chapter":"work_energy_power","topic":"Power"}', 4),
  (1705, 440, 'A device receives 400 J and produces 300 J of useful energy. Calculate its efficiency.', 'text', 1, 'Divide useful output by total input, then multiply by 100%.', '{"why":"300 J out of 400 J is 75%.","sol":"Step 1: Efficiency = (300/400) × 100%.\nStep 2: Efficiency = 0.75 × 100%.\nStep 3: Efficiency = 75%.","steps":["Step 1: Efficiency = (300/400) × 100%.","Step 2: Efficiency = 0.75 × 100%.","Step 3: Efficiency = 75%."],"options":[],"conceptId":"physics_work_energy_power_efficiency","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q1","subject":"physics","chapter":"work_energy_power","topic":"Efficiency"}', 0),
  (1706, 440, 'A machine receives 800 J and transfers 600 J usefully. Find the efficiency.', 'text', 1, 'Calculate 600 ÷ 800 × 100%.', '{"why":"The decimal ratio 0.75 corresponds to 75%.","sol":"Step 1: Efficiency = (600/800) × 100%.\nStep 2: Efficiency = 75%.","steps":["Step 1: Efficiency = (600/800) × 100%.","Step 2: Efficiency = 75%."],"options":[],"conceptId":"physics_work_energy_power_efficiency","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q2","subject":"physics","chapter":"work_energy_power","topic":"Efficiency"}', 1),
  (1707, 440, 'A motor receives 1,000 W of input power and gives 700 W of useful output power. Calculate its efficiency.', 'text', 1, 'Use output power divided by input power.', '{"why":"The useful output is 70% of the input power.","sol":"Step 1: Efficiency = (700/1000) × 100%.\nStep 2: Efficiency = 70%.","steps":["Step 1: Efficiency = (700/1000) × 100%.","Step 2: Efficiency = 70%."],"options":[],"conceptId":"physics_work_energy_power_efficiency","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q3","subject":"physics","chapter":"work_energy_power","topic":"Efficiency"}', 2),
  (1708, 440, 'A device is 80% efficient and receives 250 J of energy. Calculate its useful output energy.', 'text', 1, 'Convert 80% to 0.80 and multiply by the input.', '{"why":"80% of 250 J is 200 J.","sol":"Step 1: Convert 80% to 0.80.\nStep 2: Useful output = 0.80 × 250.\nStep 3: Useful output = 200 J.","steps":["Step 1: Convert 80% to 0.80.","Step 2: Useful output = 0.80 × 250.","Step 3: Useful output = 200 J."],"options":[],"conceptId":"physics_work_energy_power_efficiency","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q4","subject":"physics","chapter":"work_energy_power","topic":"Efficiency"}', 3),
  (1709, 440, 'A machine receives 500 J but gives 350 J of useful output. How much energy is transferred in other forms?', 'text', 1, 'Subtract useful output energy from input energy.', '{"why":"The input energy is accounted for as 350 J useful output and 150 J transferred in other forms.","sol":"Step 1: Other transfers = 500 − 350.\nStep 2: Other transfers = 150 J.","steps":["Step 1: Other transfers = 500 − 350.","Step 2: Other transfers = 150 J."],"options":[],"conceptId":"physics_work_energy_power_efficiency","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q5","subject":"physics","chapter":"work_energy_power","topic":"Efficiency"}', 4),
  (1710, 441, 'A force of 10 N moves a box 3 m in the direction of the force. How much work is done by the force?', 'mcq', 1, 'Use W = Fd.', '{"why":"Work done by a constant force acting in the direction of displacement is force multiplied by displacement.","sol":"Step 1: Write W = Fd.\nStep 2: Substitute F = 10 N and d = 3 m.\nStep 3: W = 10 × 3 = 30 J.","steps":["Step 1: Write W = Fd.","Step 2: Substitute F = 10 N and d = 3 m.","Step 3: W = 10 × 3 = 30 J."],"options":[{"text":"13 J","is_correct":false},{"text":"30 J","is_correct":true},{"text":"3.3 J","is_correct":false},{"text":"300 J","is_correct":false}],"conceptId":"physics_work_energy_power_meaning_of_work","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q1","subject":"physics","chapter":"work_energy_power","topic":"Meaning of Work"}', 0),
  (1711, 441, 'A student pulls a trolley with a force of 15 N through 4 m in the force''s direction. Calculate the work done.', 'mcq', 1, 'Multiply the force by the displacement.', '{"why":"The force and displacement are in the same direction, so W = Fd applies directly.","sol":"Step 1: W = Fd.\nStep 2: W = 15 × 4.\nStep 3: W = 60 J.","steps":["Step 1: W = Fd.","Step 2: W = 15 × 4.","Step 3: W = 60 J."],"options":[{"text":"19 J","is_correct":false},{"text":"3.75 J","is_correct":false},{"text":"60 J","is_correct":true},{"text":"45 J","is_correct":false}],"conceptId":"physics_work_energy_power_meaning_of_work","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q2","subject":"physics","chapter":"work_energy_power","topic":"Meaning of Work"}', 1),
  (1712, 441, 'A 6 N force moves an object 5 m in its direction. What is the work done?', 'mcq', 1, 'Use the product of force and displacement.', '{"why":"Work done is measured in joules and equals force multiplied by displacement in this situation.","sol":"Step 1: W = Fd.\nStep 2: W = 6 × 5.\nStep 3: W = 30 J.","steps":["Step 1: W = Fd.","Step 2: W = 6 × 5.","Step 3: W = 30 J."],"options":[{"text":"11 J","is_correct":false},{"text":"1.2 J","is_correct":false},{"text":"30 J","is_correct":true},{"text":"25 J","is_correct":false}],"conceptId":"physics_work_energy_power_meaning_of_work","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q3","subject":"physics","chapter":"work_energy_power","topic":"Meaning of Work"}', 2),
  (1713, 441, 'Which is the SI unit of work?', 'mcq', 1, 'Work is force multiplied by displacement.', '{"why":"The SI unit of work is the joule (J).","sol":"Step 1: The unit of force is the newton.\nStep 2: The unit of displacement is the metre.\nStep 3: One newton metre is one joule.","steps":["Step 1: The unit of force is the newton.","Step 2: The unit of displacement is the metre.","Step 3: One newton metre is one joule."],"options":[{"text":"Newton","is_correct":false},{"text":"Watt","is_correct":false},{"text":"Joule","is_correct":true},{"text":"Metre per second","is_correct":false}],"conceptId":"physics_work_energy_power_meaning_of_work","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q4","subject":"physics","chapter":"work_energy_power","topic":"Meaning of Work"}', 3),
  (1714, 442, 'A force does 80 J of work while moving an object 4 m in its direction. Find the force.', 'mcq', 1, 'Rearrange W = Fd to make F the subject.', '{"why":"Force equals work divided by displacement when the force acts along the displacement.","sol":"Step 1: W = Fd.\nStep 2: F = W/d.\nStep 3: F = 80/4 = 20 N.","steps":["Step 1: W = Fd.","Step 2: F = W/d.","Step 3: F = 80/4 = 20 N."],"options":[{"text":"20 N","is_correct":true},{"text":"320 N","is_correct":false},{"text":"76 N","is_correct":false},{"text":"16 N","is_correct":false}],"conceptId":"physics_work_energy_power_calculating_force_or_displacement_from_work","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q1","subject":"physics","chapter":"work_energy_power","topic":"Calculating Force or Displacement from Work"}', 0),
  (1715, 442, 'A 12 N force does 72 J of work in its direction. What displacement does it cause?', 'mcq', 1, 'Use d = W/F.', '{"why":"Displacement equals work divided by force in this situation.","sol":"Step 1: W = Fd.\nStep 2: d = W/F.\nStep 3: d = 72/12 = 6 m.","steps":["Step 1: W = Fd.","Step 2: d = W/F.","Step 3: d = 72/12 = 6 m."],"options":[{"text":"6 m","is_correct":true},{"text":"60 m","is_correct":false},{"text":"84 m","is_correct":false},{"text":"0.17 m","is_correct":false}],"conceptId":"physics_work_energy_power_calculating_force_or_displacement_from_work","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q2","subject":"physics","chapter":"work_energy_power","topic":"Calculating Force or Displacement from Work"}', 1),
  (1716, 442, 'A force does 150 J of work while moving an object 5 m in its direction. Calculate the force.', 'mcq', 1, 'Divide the work done by the displacement.', '{"why":"Rearranging W = Fd gives F = W/d.","sol":"Step 1: F = W/d.\nStep 2: F = 150/5.\nStep 3: F = 30 N.","steps":["Step 1: F = W/d.","Step 2: F = 150/5.","Step 3: F = 30 N."],"options":[{"text":"30 N","is_correct":true},{"text":"750 N","is_correct":false},{"text":"145 N","is_correct":false},{"text":"25 N","is_correct":false}],"conceptId":"physics_work_energy_power_calculating_force_or_displacement_from_work","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q3","subject":"physics","chapter":"work_energy_power","topic":"Calculating Force or Displacement from Work"}', 2),
  (1717, 442, 'A force of 10 N does 50 J of work in its direction. How far does the object move?', 'mcq', 1, 'Divide work by force.', '{"why":"The displacement is the work done divided by the force.","sol":"Step 1: d = W/F.\nStep 2: d = 50/10.\nStep 3: d = 5 m.","steps":["Step 1: d = W/F.","Step 2: d = 50/10.","Step 3: d = 5 m."],"options":[{"text":"5 m","is_correct":true},{"text":"40 m","is_correct":false},{"text":"500 m","is_correct":false},{"text":"0.2 m","is_correct":false}],"conceptId":"physics_work_energy_power_calculating_force_or_displacement_from_work","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q4","subject":"physics","chapter":"work_energy_power","topic":"Calculating Force or Displacement from Work"}', 3),
  (1718, 443, 'A student pushes a wall with 100 N, but the wall does not move. What work does the push do on the wall?', 'mcq', 1, 'Work depends on displacement as well as force.', '{"why":"A force does no mechanical work on an object if that object has no displacement.","sol":"Step 1: The wall does not move, so displacement is zero.\nStep 2: W = Fd.\nStep 3: W = 100 × 0 = 0 J.","steps":["Step 1: The wall does not move, so displacement is zero.","Step 2: W = Fd.","Step 3: W = 100 × 0 = 0 J."],"options":[{"text":"100 J","is_correct":false},{"text":"0 J","is_correct":true},{"text":"10,000 J","is_correct":false},{"text":"Cannot be zero because force acts","is_correct":false}],"conceptId":"physics_work_energy_power_when_work_done_is_zero","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q1","subject":"physics","chapter":"work_energy_power","topic":"When Work Done Is Zero"}', 0),
  (1719, 443, 'A student carries a bag horizontally at constant height. What work does the upward supporting force do during the horizontal movement?', 'mcq', 1, 'Compare the direction of the force with the direction of displacement.', '{"why":"A force perpendicular to displacement does zero work.","sol":"Step 1: The support force acts vertically upward.\nStep 2: The displacement is horizontal.\nStep 3: The force is perpendicular to the displacement, so its work is zero.","steps":["Step 1: The support force acts vertically upward.","Step 2: The displacement is horizontal.","Step 3: The force is perpendicular to the displacement, so its work is zero."],"options":[{"text":"Positive work","is_correct":false},{"text":"Negative work","is_correct":false},{"text":"Zero work","is_correct":true},{"text":"Work equal to the bag''s weight","is_correct":false}],"conceptId":"physics_work_energy_power_when_work_done_is_zero","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q2","subject":"physics","chapter":"work_energy_power","topic":"When Work Done Is Zero"}', 1),
  (1720, 443, 'Gravity acts downward with a force of 10 N while a book is lifted upward by 2 m. What work does gravity do?', 'mcq', 1, 'The gravitational force acts opposite to the upward displacement.', '{"why":"Work done by a force opposing the displacement is negative.","sol":"Step 1: The magnitude of the work is 10 × 2 = 20 J.\nStep 2: Gravity acts opposite to the displacement.\nStep 3: Work done by gravity = −20 J.","steps":["Step 1: The magnitude of the work is 10 × 2 = 20 J.","Step 2: Gravity acts opposite to the displacement.","Step 3: Work done by gravity = −20 J."],"options":[{"text":"20 J","is_correct":false},{"text":"-20 J","is_correct":true},{"text":"5 J","is_correct":false},{"text":"0 J","is_correct":false}],"conceptId":"physics_work_energy_power_when_work_done_is_zero","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q3","subject":"physics","chapter":"work_energy_power","topic":"When Work Done Is Zero"}', 2),
  (1721, 443, 'When does a force do zero work because of the angle between force and displacement?', 'mcq', 1, 'A perpendicular force has no component along the displacement.', '{"why":"For a constant force, W = Fd cos θ; at 90 degrees, cos θ = 0.","sol":"Step 1: Work depends on the component of force along displacement.\nStep 2: A perpendicular force has zero component in that direction.\nStep 3: Therefore, its work is zero.","steps":["Step 1: Work depends on the component of force along displacement.","Step 2: A perpendicular force has zero component in that direction.","Step 3: Therefore, its work is zero."],"options":[{"text":"When the force is in the same direction as displacement","is_correct":false},{"text":"When the force is opposite to displacement","is_correct":false},{"text":"When the force is perpendicular to displacement","is_correct":true},{"text":"Whenever the force is large","is_correct":false}],"conceptId":"physics_work_energy_power_when_work_done_is_zero","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q4","subject":"physics","chapter":"work_energy_power","topic":"When Work Done Is Zero"}', 3),
  (1722, 444, 'A person uses a lever to lift a stone. What is the stone called in machine terminology?', 'mcq', 1, 'Identify the object or resistance being moved.', '{"why":"The load is the resistance or object the machine is intended to move.","sol":"Step 1: The stone is the object being moved.\nStep 2: The applied force is the effort.\nStep 3: Therefore, the stone is the load.","steps":["Step 1: The stone is the object being moved.","Step 2: The applied force is the effort.","Step 3: Therefore, the stone is the load."],"options":[{"text":"Effort","is_correct":false},{"text":"Fulcrum","is_correct":false},{"text":"Load","is_correct":true},{"text":"Velocity ratio","is_correct":false}],"conceptId":"physics_work_energy_power_purpose_and_parts_of_simple_machines","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q1","subject":"physics","chapter":"work_energy_power","topic":"Purpose and Parts of Simple Machines"}', 0),
  (1723, 444, 'What is the fulcrum of a lever?', 'mcq', 1, 'Think of the fixed turning point of a seesaw.', '{"why":"The fulcrum is the pivot of a lever.","sol":"Step 1: A lever turns around a pivot.\nStep 2: That pivot is called the fulcrum.\nStep 3: Therefore, the fulcrum is the lever''s turning point.","steps":["Step 1: A lever turns around a pivot.","Step 2: That pivot is called the fulcrum.","Step 3: Therefore, the fulcrum is the lever''s turning point."],"options":[{"text":"The object being lifted","is_correct":false},{"text":"The force applied by a person","is_correct":false},{"text":"The pivot about which the lever turns","is_correct":true},{"text":"The distance the load moves","is_correct":false}],"conceptId":"physics_work_energy_power_purpose_and_parts_of_simple_machines","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q2","subject":"physics","chapter":"work_energy_power","topic":"Purpose and Parts of Simple Machines"}', 1),
  (1724, 444, 'A worker uses a ramp to push a load into a truck. What is the main mechanical advantage of the ramp in an ideal case?', 'mcq', 1, 'Compare a long ramp with lifting the load vertically.', '{"why":"An ideal machine trades force for distance rather than creating energy.","sol":"Step 1: The ramp increases the distance over which the load is raised.\nStep 2: A smaller force can act over that greater distance.\nStep 3: The ideal work required remains the same.","steps":["Step 1: The ramp increases the distance over which the load is raised.","Step 2: A smaller force can act over that greater distance.","Step 3: The ideal work required remains the same."],"options":[{"text":"It eliminates the need for work.","is_correct":false},{"text":"It reduces the effort by increasing the distance over which it acts.","is_correct":true},{"text":"It creates additional energy.","is_correct":false},{"text":"It makes the load''s mass disappear.","is_correct":false}],"conceptId":"physics_work_energy_power_purpose_and_parts_of_simple_machines","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q3","subject":"physics","chapter":"work_energy_power","topic":"Purpose and Parts of Simple Machines"}', 2),
  (1725, 444, 'Which statement about machines is correct?', 'mcq', 1, 'Consider what a lever, pulley or ramp changes.', '{"why":"Machines make tasks easier through force and distance trade-offs or changes in force direction.","sol":"Step 1: Machines can alter how a force is applied.\nStep 2: They can change force magnitude, direction or distance.\nStep 3: They cannot create energy, and real machines have losses.","steps":["Step 1: Machines can alter how a force is applied.","Step 2: They can change force magnitude, direction or distance.","Step 3: They cannot create energy, and real machines have losses."],"options":[{"text":"Machines create energy.","is_correct":false},{"text":"Machines always reduce both force and distance.","is_correct":false},{"text":"Machines can change the magnitude or direction of a force.","is_correct":true},{"text":"Machines have no energy losses in real life.","is_correct":false}],"conceptId":"physics_work_energy_power_purpose_and_parts_of_simple_machines","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q4","subject":"physics","chapter":"work_energy_power","topic":"Purpose and Parts of Simple Machines"}', 3),
  (1726, 445, 'A machine lifts a load of 200 N using an effort of 50 N. What is its mechanical advantage?', 'mcq', 1, 'Use M.A. = Load/Effort.', '{"why":"Mechanical advantage is the ratio of load force to effort force.","sol":"Step 1: M.A. = Load/Effort.\nStep 2: M.A. = 200/50.\nStep 3: M.A. = 4.","steps":["Step 1: M.A. = Load/Effort.","Step 2: M.A. = 200/50.","Step 3: M.A. = 4."],"options":[{"text":"0.25","is_correct":false},{"text":"4","is_correct":true},{"text":"150","is_correct":false},{"text":"250","is_correct":false}],"conceptId":"physics_work_energy_power_mechanical_advantage","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q1","subject":"physics","chapter":"work_energy_power","topic":"Mechanical Advantage"}', 0),
  (1727, 445, 'A machine has a mechanical advantage of 5 and lifts a load of 300 N. Find the effort.', 'mcq', 1, 'Rearrange M.A. = Load/Effort.', '{"why":"Effort equals load divided by mechanical advantage.","sol":"Step 1: Effort = Load/M.A.\nStep 2: Effort = 300/5.\nStep 3: Effort = 60 N.","steps":["Step 1: Effort = Load/M.A.","Step 2: Effort = 300/5.","Step 3: Effort = 60 N."],"options":[{"text":"1,500 N","is_correct":false},{"text":"305 N","is_correct":false},{"text":"60 N","is_correct":true},{"text":"295 N","is_correct":false}],"conceptId":"physics_work_energy_power_mechanical_advantage","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q2","subject":"physics","chapter":"work_energy_power","topic":"Mechanical Advantage"}', 1),
  (1728, 445, 'A machine has a mechanical advantage of 3 and an effort of 40 N. What load does it lift?', 'mcq', 1, 'Load = M.A. × Effort.', '{"why":"Multiplying mechanical advantage by effort gives the load force.","sol":"Step 1: Load = M.A. × Effort.\nStep 2: Load = 3 × 40.\nStep 3: Load = 120 N.","steps":["Step 1: Load = M.A. × Effort.","Step 2: Load = 3 × 40.","Step 3: Load = 120 N."],"options":[{"text":"13.3 N","is_correct":false},{"text":"43 N","is_correct":false},{"text":"120 N","is_correct":true},{"text":"1,200 N","is_correct":false}],"conceptId":"physics_work_energy_power_mechanical_advantage","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q3","subject":"physics","chapter":"work_energy_power","topic":"Mechanical Advantage"}', 2),
  (1729, 445, 'A machine has a mechanical advantage of 0.5. What does this mean?', 'mcq', 1, 'M.A. = Load/Effort.', '{"why":"Mechanical advantage compares forces; it is not the same quantity as efficiency.","sol":"Step 1: Mechanical advantage equals load divided by effort.\nStep 2: A value of 0.5 means load/effort = 0.5.\nStep 3: Therefore, the load force is half the effort force.","steps":["Step 1: Mechanical advantage equals load divided by effort.","Step 2: A value of 0.5 means load/effort = 0.5.","Step 3: Therefore, the load force is half the effort force."],"options":[{"text":"The load force is half the effort force.","is_correct":true},{"text":"The load force is twice the effort force.","is_correct":false},{"text":"The machine creates half its energy.","is_correct":false},{"text":"The machine has an efficiency of exactly 50%.","is_correct":false}],"conceptId":"physics_work_energy_power_mechanical_advantage","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q4","subject":"physics","chapter":"work_energy_power","topic":"Mechanical Advantage"}', 3),
  (1730, 446, 'A machine does 100 J of work in 1 s. What is its average power?', 'mcq', 1, 'Use P = W/t.', '{"why":"Average power is work done divided by the time taken.","sol":"Step 1: P = W/t.\nStep 2: P = 100/1.\nStep 3: P = 100 W.","steps":["Step 1: P = W/t.","Step 2: P = 100/1.","Step 3: P = 100 W."],"options":[{"text":"1 W","is_correct":false},{"text":"10 W","is_correct":false},{"text":"100 W","is_correct":true},{"text":"100 J","is_correct":false}],"conceptId":"physics_work_energy_power_meaning_and_unit_of_power","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q1","subject":"physics","chapter":"work_energy_power","topic":"Meaning and Unit of Power"}', 0),
  (1731, 446, 'A motor transfers 600 J of energy in 3 s. Calculate its average power.', 'mcq', 1, 'Divide the energy transferred by the time.', '{"why":"One watt is one joule per second.","sol":"Step 1: P = W/t.\nStep 2: P = 600/3.\nStep 3: P = 200 W.","steps":["Step 1: P = W/t.","Step 2: P = 600/3.","Step 3: P = 200 W."],"options":[{"text":"200 W","is_correct":true},{"text":"1,800 W","is_correct":false},{"text":"603 W","is_correct":false},{"text":"20 W","is_correct":false}],"conceptId":"physics_work_energy_power_meaning_and_unit_of_power","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q2","subject":"physics","chapter":"work_energy_power","topic":"Meaning and Unit of Power"}', 1),
  (1732, 446, 'Two machines each do 400 J of work. Machine A takes 2 s and machine B takes 4 s. Which has greater average power?', 'mcq', 1, 'Calculate power separately using P = W/t.', '{"why":"For equal work, less time means greater average power.","sol":"Step 1: Machine A: P = 400/2 = 200 W.\nStep 2: Machine B: P = 400/4 = 100 W.\nStep 3: Machine A has the greater average power.","steps":["Step 1: Machine A: P = 400/2 = 200 W.","Step 2: Machine B: P = 400/4 = 100 W.","Step 3: Machine A has the greater average power."],"options":[{"text":"Machine A, with 200 W","is_correct":true},{"text":"Machine B, with 200 W","is_correct":false},{"text":"Both, with 100 W","is_correct":false},{"text":"Both, with 400 W","is_correct":false}],"conceptId":"physics_work_energy_power_meaning_and_unit_of_power","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q3","subject":"physics","chapter":"work_energy_power","topic":"Meaning and Unit of Power"}', 2),
  (1733, 446, 'What is one watt equal to?', 'mcq', 1, 'Use the definition of power.', '{"why":"The watt is the SI unit of power.","sol":"Step 1: Power is work done per unit time.\nStep 2: Work is measured in joules and time in seconds.\nStep 3: Therefore, 1 W = 1 J/s.","steps":["Step 1: Power is work done per unit time.","Step 2: Work is measured in joules and time in seconds.","Step 3: Therefore, 1 W = 1 J/s."],"options":[{"text":"One newton per metre","is_correct":false},{"text":"One joule per second","is_correct":true},{"text":"One joule per metre","is_correct":false},{"text":"One kilogram per second","is_correct":false}],"conceptId":"physics_work_energy_power_meaning_and_unit_of_power","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q4","subject":"physics","chapter":"work_energy_power","topic":"Meaning and Unit of Power"}', 3),
  (1734, 447, 'A worker does 1,200 J of work in 6 s. Find the average power.', 'mcq', 1, 'Divide work by time.', '{"why":"Average power equals work done divided by time taken.","sol":"Step 1: P = W/t.\nStep 2: P = 1,200/6.\nStep 3: P = 200 W.","steps":["Step 1: P = W/t.","Step 2: P = 1,200/6.","Step 3: P = 200 W."],"options":[{"text":"200 W","is_correct":true},{"text":"7,200 W","is_correct":false},{"text":"1,206 W","is_correct":false},{"text":"20 W","is_correct":false}],"conceptId":"physics_work_energy_power_calculating_power_from_work_and_time","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q1","subject":"physics","chapter":"work_energy_power","topic":"Calculating Power from Work and Time"}', 0),
  (1735, 447, 'A pump does 9,000 J of work in 30 s. Calculate its average power.', 'mcq', 1, 'Use P = W/t.', '{"why":"Dividing joules by seconds gives watts.","sol":"Step 1: P = W/t.\nStep 2: P = 9,000/30.\nStep 3: P = 300 W.","steps":["Step 1: P = W/t.","Step 2: P = 9,000/30.","Step 3: P = 300 W."],"options":[{"text":"300 W","is_correct":true},{"text":"270,000 W","is_correct":false},{"text":"9,030 W","is_correct":false},{"text":"30 W","is_correct":false}],"conceptId":"physics_work_energy_power_calculating_power_from_work_and_time","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q2","subject":"physics","chapter":"work_energy_power","topic":"Calculating Power from Work and Time"}', 1),
  (1736, 447, 'A machine does 12,000 J of work in 2 minutes. What is its average power?', 'mcq', 1, 'Convert 2 minutes to seconds before using P = W/t.', '{"why":"Time must be in seconds when work is in joules and power is required in watts.","sol":"Step 1: 2 minutes = 120 seconds.\nStep 2: P = 12,000/120.\nStep 3: P = 100 W.","steps":["Step 1: 2 minutes = 120 seconds.","Step 2: P = 12,000/120.","Step 3: P = 100 W."],"options":[{"text":"6,000 W","is_correct":false},{"text":"100 W","is_correct":true},{"text":"200 W","is_correct":false},{"text":"12,000 W","is_correct":false}],"conceptId":"physics_work_energy_power_calculating_power_from_work_and_time","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q3","subject":"physics","chapter":"work_energy_power","topic":"Calculating Power from Work and Time"}', 2),
  (1737, 447, 'A machine does 2,400 J of work in 8 s. What is its average power?', 'mcq', 1, 'Use the ratio of work to time.', '{"why":"Average power is calculated by dividing the work done by the time taken.","sol":"Step 1: P = W/t.\nStep 2: P = 2,400/8.\nStep 3: P = 300 W.","steps":["Step 1: P = W/t.","Step 2: P = 2,400/8.","Step 3: P = 300 W."],"options":[{"text":"300 W","is_correct":true},{"text":"19,200 W","is_correct":false},{"text":"2,408 W","is_correct":false},{"text":"30 W","is_correct":false}],"conceptId":"physics_work_energy_power_calculating_power_from_work_and_time","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q4","subject":"physics","chapter":"work_energy_power","topic":"Calculating Power from Work and Time"}', 3),
  (1738, 448, 'A motor operates at 250 W for 8 s. How much work does it do at that average power?', 'mcq', 1, 'Use W = Pt.', '{"why":"Work equals average power multiplied by the time interval.","sol":"Step 1: W = Pt.\nStep 2: W = 250 × 8.\nStep 3: W = 2,000 J.","steps":["Step 1: W = Pt.","Step 2: W = 250 × 8.","Step 3: W = 2,000 J."],"options":[{"text":"31.25 J","is_correct":false},{"text":"258 J","is_correct":false},{"text":"2,000 J","is_correct":true},{"text":"2,500 J","is_correct":false}],"conceptId":"physics_work_energy_power_calculating_work_or_time_from_power","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q1","subject":"physics","chapter":"work_energy_power","topic":"Calculating Work or Time from Power"}', 0),
  (1739, 448, 'A machine does 3,600 J of work at an average power of 600 W. Find the time taken.', 'mcq', 1, 'Rearrange P = W/t to make t the subject.', '{"why":"Time equals work divided by average power.","sol":"Step 1: t = W/P.\nStep 2: t = 3,600/600.\nStep 3: t = 6 s.","steps":["Step 1: t = W/P.","Step 2: t = 3,600/600.","Step 3: t = 6 s."],"options":[{"text":"6 s","is_correct":true},{"text":"2,160,000 s","is_correct":false},{"text":"3,000 s","is_correct":false},{"text":"600 s","is_correct":false}],"conceptId":"physics_work_energy_power_calculating_work_or_time_from_power","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q2","subject":"physics","chapter":"work_energy_power","topic":"Calculating Work or Time from Power"}', 1),
  (1740, 448, 'A motor operates at 400 W for 15 s. How much work is done at that average power?', 'mcq', 1, 'Multiply power by time.', '{"why":"A watt is one joule per second, so multiplying watts by seconds gives joules.","sol":"Step 1: W = Pt.\nStep 2: W = 400 × 15.\nStep 3: W = 6,000 J.","steps":["Step 1: W = Pt.","Step 2: W = 400 × 15.","Step 3: W = 6,000 J."],"options":[{"text":"415 J","is_correct":false},{"text":"6,000 J","is_correct":true},{"text":"26.7 J","is_correct":false},{"text":"400 J","is_correct":false}],"conceptId":"physics_work_energy_power_calculating_work_or_time_from_power","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q3","subject":"physics","chapter":"work_energy_power","topic":"Calculating Work or Time from Power"}', 2),
  (1741, 448, 'A machine does 1,500 J of work at an average power of 300 W. How long does it take?', 'mcq', 1, 'Use t = W/P.', '{"why":"Dividing work in joules by power in watts gives time in seconds.","sol":"Step 1: t = W/P.\nStep 2: t = 1,500/300.\nStep 3: t = 5 s.","steps":["Step 1: t = W/P.","Step 2: t = 1,500/300.","Step 3: t = 5 s."],"options":[{"text":"5 s","is_correct":true},{"text":"4,500 s","is_correct":false},{"text":"1,800 s","is_correct":false},{"text":"0.2 s","is_correct":false}],"conceptId":"physics_work_energy_power_calculating_work_or_time_from_power","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q4","subject":"physics","chapter":"work_energy_power","topic":"Calculating Work or Time from Power"}', 3),
  (1742, 449, 'Machine A does 600 J in 3 s. Machine B does 600 J in 6 s. Which has greater average power?', 'mcq', 1, 'Calculate P = W/t for both machines.', '{"why":"For the same work, completing it in less time requires greater average power.","sol":"Step 1: P(A) = 600/3 = 200 W.\nStep 2: P(B) = 600/6 = 100 W.\nStep 3: Machine A has greater average power.","steps":["Step 1: P(A) = 600/3 = 200 W.","Step 2: P(B) = 600/6 = 100 W.","Step 3: Machine A has greater average power."],"options":[{"text":"Machine A, at 200 W","is_correct":true},{"text":"Machine B, at 200 W","is_correct":false},{"text":"Both, at 100 W","is_correct":false},{"text":"Both, at 600 W","is_correct":false}],"conceptId":"physics_work_energy_power_comparing_power","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q1","subject":"physics","chapter":"work_energy_power","topic":"Comparing Power"}', 0),
  (1743, 449, 'Machine A does 900 J in 3 s. Machine B does 1,500 J in the same 3 s. Which has greater average power?', 'mcq', 1, 'The times are equal, so compare work done per second.', '{"why":"For the same time interval, greater work means greater average power.","sol":"Step 1: P(A) = 900/3 = 300 W.\nStep 2: P(B) = 1,500/3 = 500 W.\nStep 3: Machine B has greater average power.","steps":["Step 1: P(A) = 900/3 = 300 W.","Step 2: P(B) = 1,500/3 = 500 W.","Step 3: Machine B has greater average power."],"options":[{"text":"Machine A, at 300 W","is_correct":false},{"text":"Machine B, at 500 W","is_correct":true},{"text":"Both, at 400 W","is_correct":false},{"text":"Machine A, at 900 W","is_correct":false}],"conceptId":"physics_work_energy_power_comparing_power","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q2","subject":"physics","chapter":"work_energy_power","topic":"Comparing Power"}', 1),
  (1744, 449, 'Worker A does 2,400 J in 12 s. Worker B does 1,800 J in 6 s. Who has greater average power?', 'mcq', 1, 'Calculate each worker''s work per second.', '{"why":"Power measures the rate of doing work, not the total amount of work alone.","sol":"Step 1: P(A) = 2,400/12 = 200 W.\nStep 2: P(B) = 1,800/6 = 300 W.\nStep 3: Worker B has greater average power.","steps":["Step 1: P(A) = 2,400/12 = 200 W.","Step 2: P(B) = 1,800/6 = 300 W.","Step 3: Worker B has greater average power."],"options":[{"text":"Worker A, at 200 W","is_correct":false},{"text":"Worker B, at 300 W","is_correct":true},{"text":"Worker A, at 2,400 W","is_correct":false},{"text":"Both have equal power","is_correct":false}],"conceptId":"physics_work_energy_power_comparing_power","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q3","subject":"physics","chapter":"work_energy_power","topic":"Comparing Power"}', 2),
  (1745, 449, 'Two machines do the same work. Machine A takes 10 s and machine B takes 5 s. How do their average powers compare?', 'mcq', 1, 'For equal work, power is inversely proportional to time.', '{"why":"For fixed work, P = W/t, so halving the time doubles average power.","sol":"Step 1: Both machines do equal work.\nStep 2: Machine B takes half the time of A.\nStep 3: Therefore, B''s average power is twice A''s.","steps":["Step 1: Both machines do equal work.","Step 2: Machine B takes half the time of A.","Step 3: Therefore, B''s average power is twice A''s."],"options":[{"text":"A has twice B''s power.","is_correct":false},{"text":"B has twice A''s power.","is_correct":true},{"text":"Their powers are equal.","is_correct":false},{"text":"B has half A''s power.","is_correct":false}],"conceptId":"physics_work_energy_power_comparing_power","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q4","subject":"physics","chapter":"work_energy_power","topic":"Comparing Power"}', 3),
  (1746, 450, 'A vehicle experiences a driving force of 500 N while moving at 10 m/s. Calculate the power delivered by that force.', 'mcq', 1, 'Use P = Fv.', '{"why":"When force acts in the direction of motion, power equals force multiplied by speed.","sol":"Step 1: P = Fv.\nStep 2: P = 500 × 10.\nStep 3: P = 5,000 W.","steps":["Step 1: P = Fv.","Step 2: P = 500 × 10.","Step 3: P = 5,000 W."],"options":[{"text":"50 W","is_correct":false},{"text":"500 W","is_correct":false},{"text":"5,000 W","is_correct":true},{"text":"50,000 W","is_correct":false}],"conceptId":"physics_work_energy_power_power_force_and_speed","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q1","subject":"physics","chapter":"work_energy_power","topic":"Power, Force and Speed"}', 0),
  (1747, 450, 'A motor supplies a force of 200 N in the direction of motion at 15 m/s. What power does the force deliver?', 'mcq', 1, 'Multiply force by speed.', '{"why":"Power delivered by a force along the direction of motion is force multiplied by speed.","sol":"Step 1: P = Fv.\nStep 2: P = 200 × 15.\nStep 3: P = 3,000 W.","steps":["Step 1: P = Fv.","Step 2: P = 200 × 15.","Step 3: P = 3,000 W."],"options":[{"text":"215 W","is_correct":false},{"text":"3,000 W","is_correct":true},{"text":"750 W","is_correct":false},{"text":"30,000 W","is_correct":false}],"conceptId":"physics_work_energy_power_power_force_and_speed","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q2","subject":"physics","chapter":"work_energy_power","topic":"Power, Force and Speed"}', 1),
  (1748, 450, 'A motor delivers 6,000 W to an object moving at 12 m/s. If the force is along the motion, what is the force?', 'mcq', 1, 'Rearrange P = Fv to make F the subject.', '{"why":"Force equals power divided by speed when force acts along the direction of motion.","sol":"Step 1: F = P/v.\nStep 2: F = 6,000/12.\nStep 3: F = 500 N.","steps":["Step 1: F = P/v.","Step 2: F = 6,000/12.","Step 3: F = 500 N."],"options":[{"text":"72,000 N","is_correct":false},{"text":"500 N","is_correct":true},{"text":"6,012 N","is_correct":false},{"text":"50 N","is_correct":false}],"conceptId":"physics_work_energy_power_power_force_and_speed","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q3","subject":"physics","chapter":"work_energy_power","topic":"Power, Force and Speed"}', 2),
  (1749, 450, 'A vehicle moves at constant speed while its driving force in the direction of motion doubles. What happens to the power delivered by that force?', 'mcq', 1, 'Use P = Fv and keep speed constant.', '{"why":"At constant speed, power delivered by a force is directly proportional to that force.","sol":"Step 1: Power is P = Fv.\nStep 2: Speed remains constant.\nStep 3: Doubling F therefore doubles P.","steps":["Step 1: Power is P = Fv.","Step 2: Speed remains constant.","Step 3: Doubling F therefore doubles P."],"options":[{"text":"It halves.","is_correct":false},{"text":"It doubles.","is_correct":true},{"text":"It becomes zero.","is_correct":false},{"text":"It remains unchanged.","is_correct":false}],"conceptId":"physics_work_energy_power_power_force_and_speed","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q4","subject":"physics","chapter":"work_energy_power","topic":"Power, Force and Speed"}', 3),
  (1750, 451, 'What is kinetic energy?', 'mcq', 1, 'Think about what a moving object possesses.', '{"why":"Kinetic energy is the energy an object has because it is moving.","sol":"Step 1: Kinetic energy is associated with motion.\nStep 2: A moving object possesses kinetic energy.","steps":["Step 1: Kinetic energy is associated with motion.","Step 2: A moving object possesses kinetic energy."],"options":[{"text":"Energy due to an object''s motion","is_correct":false},{"text":"Energy stored only in a battery","is_correct":false},{"text":"Energy due only to an object''s height","is_correct":false},{"text":"The force acting on an object","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_work_energy_power_meaning_of_kinetic_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q1","subject":"physics","chapter":"work_energy_power","topic":"Meaning of Kinetic Energy"}', 0);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (1751, 451, 'A 5 kg object is at rest. What is its kinetic energy?', 'mcq', 1, 'At rest, the speed is zero.', '{"why":"An object at rest has zero kinetic energy.","sol":"Step 1: Use KE = ½mv².\nStep 2: Substitute m = 5 kg and v = 0 m/s.\nStep 3: KE = ½ × 5 × 0² = 0 J.","steps":["Step 1: Use KE = ½mv².","Step 2: Substitute m = 5 kg and v = 0 m/s.","Step 3: KE = ½ × 5 × 0² = 0 J."],"options":[{"text":"5 J","is_correct":false},{"text":"2.5 J","is_correct":false},{"text":"0 J","is_correct":false},{"text":"25 J","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_work_energy_power_meaning_of_kinetic_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q2","subject":"physics","chapter":"work_energy_power","topic":"Meaning of Kinetic Energy"}', 1),
  (1752, 451, 'Which quantity is squared in KE = ½mv²?', 'mcq', 1, 'Look at the small 2 in the formula.', '{"why":"Speed is squared when calculating kinetic energy.","sol":"Step 1: The formula is KE = ½mv².\nStep 2: The exponent 2 is attached to v, which represents speed.","steps":["Step 1: The formula is KE = ½mv².","Step 2: The exponent 2 is attached to v, which represents speed."],"options":[{"text":"Mass","is_correct":false},{"text":"Speed","is_correct":false},{"text":"Kinetic energy","is_correct":false},{"text":"Time","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_work_energy_power_meaning_of_kinetic_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q3","subject":"physics","chapter":"work_energy_power","topic":"Meaning of Kinetic Energy"}', 2),
  (1753, 451, 'Which unit is used for kinetic energy?', 'mcq', 1, 'Choose the SI unit of energy.', '{"why":"The joule (J) is the SI unit of energy.","sol":"Step 1: Energy is measured in joules.\nStep 2: Therefore, kinetic energy is measured in J.","steps":["Step 1: Energy is measured in joules.","Step 2: Therefore, kinetic energy is measured in J."],"options":[{"text":"Newton","is_correct":false},{"text":"Watt","is_correct":false},{"text":"Kilogram","is_correct":false},{"text":"Joule","is_correct":false},{"text":"3","is_correct":true}],"conceptId":"physics_work_energy_power_meaning_of_kinetic_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q4","subject":"physics","chapter":"work_energy_power","topic":"Meaning of Kinetic Energy"}', 3),
  (1754, 452, 'Calculate the kinetic energy of a 2 kg object moving at 5 m/s.', 'mcq', 1, 'Square 5 before multiplying.', '{"why":"The kinetic energy is 25 J.","sol":"Step 1: KE = ½mv².\nStep 2: KE = ½ × 2 × 5².\nStep 3: KE = 1 × 25 = 25 J.","steps":["Step 1: KE = ½mv².","Step 2: KE = ½ × 2 × 5².","Step 3: KE = 1 × 25 = 25 J."],"options":[{"text":"10 J","is_correct":false},{"text":"25 J","is_correct":false},{"text":"50 J","is_correct":false},{"text":"100 J","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_work_energy_power_calculating_kinetic_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q1","subject":"physics","chapter":"work_energy_power","topic":"Calculating Kinetic Energy"}', 0),
  (1755, 452, 'A 4 kg object moves at 3 m/s. Find its kinetic energy.', 'mcq', 1, 'First calculate 3².', '{"why":"Squaring the speed gives 9, so the kinetic energy is 18 J.","sol":"Step 1: KE = ½ × 4 × 3².\nStep 2: KE = 2 × 9.\nStep 3: KE = 18 J.","steps":["Step 1: KE = ½ × 4 × 3².","Step 2: KE = 2 × 9.","Step 3: KE = 18 J."],"options":[{"text":"12 J","is_correct":false},{"text":"18 J","is_correct":false},{"text":"24 J","is_correct":false},{"text":"36 J","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_work_energy_power_calculating_kinetic_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q2","subject":"physics","chapter":"work_energy_power","topic":"Calculating Kinetic Energy"}', 1),
  (1756, 452, 'A 10 kg object moves at 2 m/s. What is its kinetic energy?', 'mcq', 1, 'Use half of the mass multiplied by the squared speed.', '{"why":"The kinetic energy is 20 J.","sol":"Step 1: KE = ½ × 10 × 2².\nStep 2: KE = 5 × 4.\nStep 3: KE = 20 J.","steps":["Step 1: KE = ½ × 10 × 2².","Step 2: KE = 5 × 4.","Step 3: KE = 20 J."],"options":[{"text":"20 J","is_correct":false},{"text":"40 J","is_correct":false},{"text":"10 J","is_correct":false},{"text":"5 J","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_work_energy_power_calculating_kinetic_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q3","subject":"physics","chapter":"work_energy_power","topic":"Calculating Kinetic Energy"}', 2),
  (1757, 452, 'A 3 kg object moves at 6 m/s. Calculate its kinetic energy.', 'mcq', 1, '6² = 36.', '{"why":"The kinetic energy is 54 J.","sol":"Step 1: KE = ½ × 3 × 6².\nStep 2: KE = 1.5 × 36.\nStep 3: KE = 54 J.","steps":["Step 1: KE = ½ × 3 × 6².","Step 2: KE = 1.5 × 36.","Step 3: KE = 54 J."],"options":[{"text":"18 J","is_correct":false},{"text":"36 J","is_correct":false},{"text":"54 J","is_correct":false},{"text":"108 J","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_work_energy_power_calculating_kinetic_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q4","subject":"physics","chapter":"work_energy_power","topic":"Calculating Kinetic Energy"}', 3),
  (1758, 453, 'An object''s mass doubles while its speed stays constant. What happens to its kinetic energy?', 'mcq', 1, 'Kinetic energy is directly proportional to mass when speed is constant.', '{"why":"Doubling mass doubles kinetic energy if speed is unchanged.","sol":"Step 1: KE = ½mv².\nStep 2: With v constant, doubling m doubles KE.","steps":["Step 1: KE = ½mv².","Step 2: With v constant, doubling m doubles KE."],"options":[{"text":"It halves","is_correct":false},{"text":"It doubles","is_correct":false},{"text":"It becomes four times greater","is_correct":false},{"text":"It remains unchanged","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_work_energy_power_mass_and_speed_in_kinetic_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q1","subject":"physics","chapter":"work_energy_power","topic":"Mass and Speed in Kinetic Energy"}', 0),
  (1759, 453, 'A car''s speed doubles while its mass remains constant. Its kinetic energy becomes:', 'mcq', 1, 'Square the speed factor.', '{"why":"Kinetic energy depends on the square of speed.","sol":"Step 1: The speed factor is 2.\nStep 2: The kinetic energy factor is 2² = 4.","steps":["Step 1: The speed factor is 2.","Step 2: The kinetic energy factor is 2² = 4."],"options":[{"text":"Twice as great","is_correct":false},{"text":"Three times as great","is_correct":false},{"text":"Four times as great","is_correct":false},{"text":"Half as great","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_work_energy_power_mass_and_speed_in_kinetic_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q2","subject":"physics","chapter":"work_energy_power","topic":"Mass and Speed in Kinetic Energy"}', 1),
  (1760, 453, 'An object''s speed triples. By what factor does its kinetic energy increase if its mass is unchanged?', 'mcq', 1, 'Calculate 3².', '{"why":"Tripling speed makes kinetic energy nine times greater.","sol":"Step 1: The speed factor is 3.\nStep 2: The kinetic energy factor is 3² = 9.","steps":["Step 1: The speed factor is 3.","Step 2: The kinetic energy factor is 3² = 9."],"options":[{"text":"3","is_correct":false},{"text":"6","is_correct":false},{"text":"9","is_correct":false},{"text":"12","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_work_energy_power_mass_and_speed_in_kinetic_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q3","subject":"physics","chapter":"work_energy_power","topic":"Mass and Speed in Kinetic Energy"}', 2),
  (1761, 453, 'An object''s speed is halved. What fraction of its original kinetic energy remains?', 'mcq', 1, 'Square the speed factor ½.', '{"why":"Halving speed leaves one-quarter of the original kinetic energy.","sol":"Step 1: The speed factor is ½.\nStep 2: The kinetic energy factor is (½)² = ¼.","steps":["Step 1: The speed factor is ½.","Step 2: The kinetic energy factor is (½)² = ¼."],"options":[{"text":"One-half","is_correct":false},{"text":"One-quarter","is_correct":false},{"text":"One-third","is_correct":false},{"text":"One-eighth","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_work_energy_power_mass_and_speed_in_kinetic_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q4","subject":"physics","chapter":"work_energy_power","topic":"Mass and Speed in Kinetic Energy"}', 3),
  (1762, 454, 'What is gravitational potential energy?', 'mcq', 1, 'Think about an object raised above the ground.', '{"why":"GPE is associated with position in a gravitational field.","sol":"Step 1: An elevated object can store energy because of its position.\nStep 2: This is gravitational potential energy.","steps":["Step 1: An elevated object can store energy because of its position.","Step 2: This is gravitational potential energy."],"options":[{"text":"Energy due to position in a gravitational field","is_correct":false},{"text":"Energy due only to motion","is_correct":false},{"text":"The rate of doing work","is_correct":false},{"text":"The force opposing motion","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_work_energy_power_meaning_of_gravitational_potential_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q1","subject":"physics","chapter":"work_energy_power","topic":"Meaning of Gravitational Potential Energy"}', 0),
  (1763, 454, 'Which formula is used to calculate gravitational potential energy near Earth''s surface?', 'mcq', 1, 'It uses mass, gravitational field strength and height.', '{"why":"GPE = mgh is the school-level formula for gravitational potential energy near Earth''s surface.","sol":"Step 1: Identify m, g and h.\nStep 2: Use GPE = mgh.","steps":["Step 1: Identify m, g and h.","Step 2: Use GPE = mgh."],"options":[{"text":"GPE = ½mv²","is_correct":false},{"text":"GPE = mgh","is_correct":false},{"text":"GPE = F/A","is_correct":false},{"text":"GPE = W/t","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_work_energy_power_meaning_of_gravitational_potential_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q2","subject":"physics","chapter":"work_energy_power","topic":"Meaning of Gravitational Potential Energy"}', 1),
  (1764, 454, 'In GPE = mgh, what does h represent?', 'mcq', 1, 'It is measured vertically in metres.', '{"why":"The height used in the formula is vertical height.","sol":"Step 1: The symbol h represents height.\nStep 2: Use the vertical height relative to the reference level.","steps":["Step 1: The symbol h represents height.","Step 2: Use the vertical height relative to the reference level."],"options":[{"text":"Horizontal distance travelled","is_correct":false},{"text":"Height above the chosen reference level","is_correct":false},{"text":"Time taken","is_correct":false},{"text":"Speed","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_work_energy_power_meaning_of_gravitational_potential_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q3","subject":"physics","chapter":"work_energy_power","topic":"Meaning of Gravitational Potential Energy"}', 2),
  (1765, 454, 'Two equal masses are held above the same floor. Which has greater GPE?', 'mcq', 1, 'Compare their heights above the same reference level.', '{"why":"For equal masses in the same gravitational field, the higher object has more GPE relative to the same reference level.","sol":"Step 1: The masses and gravitational field strength are the same.\nStep 2: GPE = mgh, so the greater height gives greater GPE.","steps":["Step 1: The masses and gravitational field strength are the same.","Step 2: GPE = mgh, so the greater height gives greater GPE."],"options":[{"text":"The lower object","is_correct":false},{"text":"The higher object","is_correct":false},{"text":"Both always have zero GPE","is_correct":false},{"text":"Neither can have GPE","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_work_energy_power_meaning_of_gravitational_potential_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q4","subject":"physics","chapter":"work_energy_power","topic":"Meaning of Gravitational Potential Energy"}', 3),
  (1766, 455, 'Calculate the GPE of a 3 kg object raised 4 m. Take g = 10 N/kg.', 'mcq', 1, 'Multiply mass × g × height.', '{"why":"The gravitational potential energy is 120 J.","sol":"Step 1: GPE = mgh.\nStep 2: GPE = 3 × 10 × 4.\nStep 3: GPE = 120 J.","steps":["Step 1: GPE = mgh.","Step 2: GPE = 3 × 10 × 4.","Step 3: GPE = 120 J."],"options":[{"text":"12 J","is_correct":false},{"text":"30 J","is_correct":false},{"text":"120 J","is_correct":false},{"text":"240 J","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_work_energy_power_calculating_gravitational_potential_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q1","subject":"physics","chapter":"work_energy_power","topic":"Calculating Gravitational Potential Energy"}', 0),
  (1767, 455, 'A 5 kg object is 2 m above the ground. Take g = 10 N/kg. Find its GPE.', 'mcq', 1, 'Use GPE = mgh.', '{"why":"The object''s GPE relative to the ground is 100 J.","sol":"Step 1: GPE = 5 × 10 × 2.\nStep 2: GPE = 100 J.","steps":["Step 1: GPE = 5 × 10 × 2.","Step 2: GPE = 100 J."],"options":[{"text":"25 J","is_correct":false},{"text":"50 J","is_correct":false},{"text":"100 J","is_correct":false},{"text":"200 J","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_work_energy_power_calculating_gravitational_potential_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q2","subject":"physics","chapter":"work_energy_power","topic":"Calculating Gravitational Potential Energy"}', 1),
  (1768, 455, 'Calculate the GPE of a 2 kg object at a height of 6 m where g = 10 N/kg.', 'mcq', 1, 'Substitute all three values into mgh.', '{"why":"The gravitational potential energy is 120 J.","sol":"Step 1: GPE = 2 × 10 × 6.\nStep 2: GPE = 120 J.","steps":["Step 1: GPE = 2 × 10 × 6.","Step 2: GPE = 120 J."],"options":[{"text":"12 J","is_correct":false},{"text":"60 J","is_correct":false},{"text":"120 J","is_correct":false},{"text":"180 J","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_work_energy_power_calculating_gravitational_potential_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q3","subject":"physics","chapter":"work_energy_power","topic":"Calculating Gravitational Potential Energy"}', 2),
  (1769, 455, 'A 4 kg object is raised 5 m. If g = 10 N/kg, what is its gain in GPE?', 'mcq', 1, 'The gain in GPE is mgh for a vertical rise of 5 m.', '{"why":"The object''s gravitational potential energy increases by 200 J.","sol":"Step 1: Gain in GPE = mgh.\nStep 2: Gain in GPE = 4 × 10 × 5.\nStep 3: Gain in GPE = 200 J.","steps":["Step 1: Gain in GPE = mgh.","Step 2: Gain in GPE = 4 × 10 × 5.","Step 3: Gain in GPE = 200 J."],"options":[{"text":"20 J","is_correct":false},{"text":"100 J","is_correct":false},{"text":"200 J","is_correct":false},{"text":"400 J","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_work_energy_power_calculating_gravitational_potential_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q4","subject":"physics","chapter":"work_energy_power","topic":"Calculating Gravitational Potential Energy"}', 3),
  (1770, 456, 'Which statement expresses the principle of conservation of energy?', 'mcq', 1, 'Think about what happens to energy when its form changes.', '{"why":"Energy is not created or destroyed; it is transferred or transformed.","sol":"Step 1: Energy can change form or move between objects.\nStep 2: The total energy is conserved when all forms are accounted for.","steps":["Step 1: Energy can change form or move between objects.","Step 2: The total energy is conserved when all forms are accounted for."],"options":[{"text":"Energy is destroyed whenever an object stops moving","is_correct":false},{"text":"Energy can be created whenever work is done","is_correct":false},{"text":"Energy cannot be created or destroyed, only transferred or transformed","is_correct":false},{"text":"Only kinetic energy is conserved in every situation","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_work_energy_power_principle_of_conservation_of_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q1","subject":"physics","chapter":"work_energy_power","topic":"Principle of Conservation of Energy"}', 0),
  (1771, 456, 'A moving bicycle slows down because of friction. What happens to most of its lost kinetic energy?', 'mcq', 1, 'Consider the warming of surfaces during friction.', '{"why":"Friction transfers energy into thermal energy; it does not destroy energy.","sol":"Step 1: Friction opposes the bicycle''s motion.\nStep 2: Kinetic energy decreases and is transferred mainly into thermal energy and the surroundings.","steps":["Step 1: Friction opposes the bicycle''s motion.","Step 2: Kinetic energy decreases and is transferred mainly into thermal energy and the surroundings."],"options":[{"text":"It disappears","is_correct":false},{"text":"It is transferred mainly into thermal energy","is_correct":false},{"text":"It becomes mass","is_correct":false},{"text":"It is destroyed by friction","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_work_energy_power_principle_of_conservation_of_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q2","subject":"physics","chapter":"work_energy_power","topic":"Principle of Conservation of Energy"}', 1),
  (1772, 456, 'A device receives 200 J of energy. A total of 200 J is transferred to its surroundings in different forms. What does this show?', 'mcq', 1, 'Compare the total energy supplied with the total transferred out.', '{"why":"The total energy supplied equals the total energy transferred out.","sol":"Step 1: Energy supplied = 200 J.\nStep 2: Energy transferred out = 200 J.\nStep 3: The totals are equal.","steps":["Step 1: Energy supplied = 200 J.","Step 2: Energy transferred out = 200 J.","Step 3: The totals are equal."],"options":[{"text":"Energy has been created","is_correct":false},{"text":"Energy has been destroyed","is_correct":false},{"text":"Energy has been conserved","is_correct":false},{"text":"The device has no energy transfers","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_work_energy_power_principle_of_conservation_of_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q3","subject":"physics","chapter":"work_energy_power","topic":"Principle of Conservation of Energy"}', 2),
  (1773, 456, 'When air resistance is ignored, what happens to the total mechanical energy of a falling object?', 'mcq', 1, 'Mechanical energy includes kinetic and gravitational potential energy.', '{"why":"Without energy losses to air resistance, total mechanical energy remains constant.","sol":"Step 1: GPE decreases as the object falls.\nStep 2: KE increases by the corresponding amount.\nStep 3: Their sum remains constant when air resistance is ignored.","steps":["Step 1: GPE decreases as the object falls.","Step 2: KE increases by the corresponding amount.","Step 3: Their sum remains constant when air resistance is ignored."],"options":[{"text":"It continually increases","is_correct":false},{"text":"It continually decreases","is_correct":false},{"text":"It remains constant","is_correct":false},{"text":"It becomes zero halfway down","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_work_energy_power_principle_of_conservation_of_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q4","subject":"physics","chapter":"work_energy_power","topic":"Principle of Conservation of Energy"}', 3),
  (1774, 457, 'Electrical energy changes into light and thermal energy in a lamp. What is this process?', 'mcq', 1, 'The energy changes from one form into other forms.', '{"why":"The lamp transforms electrical energy into light and thermal energy.","sol":"Step 1: The lamp receives electrical energy.\nStep 2: It produces light and thermal energy.\nStep 3: A change of energy form is a transformation.","steps":["Step 1: The lamp receives electrical energy.","Step 2: It produces light and thermal energy.","Step 3: A change of energy form is a transformation."],"options":[{"text":"Energy transformation","is_correct":false},{"text":"Energy destruction","is_correct":false},{"text":"Energy creation","is_correct":false},{"text":"No energy change","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_work_energy_power_energy_transfer_and_transformation","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q1","subject":"physics","chapter":"work_energy_power","topic":"Energy Transfer and Transformation"}', 0),
  (1775, 457, 'Thermal energy moves from hot tea into a cooler spoon. What is this?', 'mcq', 1, 'The energy moves between objects.', '{"why":"Energy moving from one object to another is an energy transfer.","sol":"Step 1: The tea is hotter than the spoon.\nStep 2: Thermal energy moves from the tea into the spoon.","steps":["Step 1: The tea is hotter than the spoon.","Step 2: Thermal energy moves from the tea into the spoon."],"options":[{"text":"Energy creation","is_correct":false},{"text":"Energy transfer","is_correct":false},{"text":"Energy destruction","is_correct":false},{"text":"A change into nuclear energy","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_work_energy_power_energy_transfer_and_transformation","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q2","subject":"physics","chapter":"work_energy_power","topic":"Energy Transfer and Transformation"}', 1),
  (1776, 457, 'Which energy transformation occurs when a battery powers a simple electric motor?', 'mcq', 1, 'Follow the energy from the battery through the motor.', '{"why":"A battery-powered motor transforms chemical energy into electrical energy and then mainly into mechanical energy, with some losses.","sol":"Step 1: The battery stores chemical energy.\nStep 2: The circuit transfers energy electrically.\nStep 3: The motor produces movement, giving mechanical energy.","steps":["Step 1: The battery stores chemical energy.","Step 2: The circuit transfers energy electrically.","Step 3: The motor produces movement, giving mechanical energy."],"options":[{"text":"Kinetic to gravitational potential only","is_correct":false},{"text":"Chemical to electrical to mechanical energy","is_correct":false},{"text":"Thermal to nuclear energy","is_correct":false},{"text":"Sound to chemical energy only","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_work_energy_power_energy_transfer_and_transformation","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q3","subject":"physics","chapter":"work_energy_power","topic":"Energy Transfer and Transformation"}', 2),
  (1777, 457, 'As a stone falls freely with air resistance ignored, which transformation occurs?', 'mcq', 1, 'The stone loses height and gains speed.', '{"why":"The falling stone transforms gravitational potential energy into kinetic energy.","sol":"Step 1: The stone''s gravitational potential energy decreases.\nStep 2: Its kinetic energy increases.","steps":["Step 1: The stone''s gravitational potential energy decreases.","Step 2: Its kinetic energy increases."],"options":[{"text":"Kinetic energy to chemical energy","is_correct":false},{"text":"Thermal energy to electrical energy","is_correct":false},{"text":"Gravitational potential energy to kinetic energy","is_correct":false},{"text":"Sound energy to gravitational potential energy","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_work_energy_power_energy_transfer_and_transformation","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q4","subject":"physics","chapter":"work_energy_power","topic":"Energy Transfer and Transformation"}', 3),
  (1778, 458, 'A stone falls from rest, with air resistance ignored. What happens to its GPE and KE?', 'mcq', 1, 'The stone loses height and gains speed.', '{"why":"As the stone falls, GPE is transformed into KE.","sol":"Step 1: Decreasing height means decreasing GPE.\nStep 2: Increasing speed means increasing KE.","steps":["Step 1: Decreasing height means decreasing GPE.","Step 2: Increasing speed means increasing KE."],"options":[{"text":"Both decrease","is_correct":false},{"text":"GPE decreases and KE increases","is_correct":false},{"text":"GPE increases and KE decreases","is_correct":false},{"text":"Both remain zero","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_work_energy_power_energy_changes_during_falling","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q1","subject":"physics","chapter":"work_energy_power","topic":"Energy Changes During Falling"}', 0),
  (1779, 458, 'A ball is released from rest. What is its kinetic energy at the instant it is released?', 'mcq', 1, 'Use KE = ½mv² and consider the initial speed.', '{"why":"At the instant of release from rest, the ball''s kinetic energy is zero.","sol":"Step 1: The ball is released from rest, so v = 0.\nStep 2: KE = ½m × 0² = 0 J.","steps":["Step 1: The ball is released from rest, so v = 0.","Step 2: KE = ½m × 0² = 0 J."],"options":[{"text":"Zero","is_correct":false},{"text":"Equal to its mass","is_correct":false},{"text":"Always 10 J","is_correct":false},{"text":"Equal to its height","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_work_energy_power_energy_changes_during_falling","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q2","subject":"physics","chapter":"work_energy_power","topic":"Energy Changes During Falling"}', 1),
  (1780, 458, 'A falling object experiences significant air resistance. What happens to some of the gravitational potential energy it loses?', 'mcq', 1, 'Air resistance opposes motion and causes energy transfers.', '{"why":"With air resistance, not all lost GPE becomes kinetic energy.","sol":"Step 1: Air resistance acts against the object''s motion.\nStep 2: Some mechanical energy is transferred to the surroundings.","steps":["Step 1: Air resistance acts against the object''s motion.","Step 2: Some mechanical energy is transferred to the surroundings."],"options":[{"text":"It is destroyed","is_correct":false},{"text":"It becomes mass","is_correct":false},{"text":"It is transferred to the surroundings, mainly as thermal energy","is_correct":false},{"text":"It all remains as gravitational potential energy","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_work_energy_power_energy_changes_during_falling","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q3","subject":"physics","chapter":"work_energy_power","topic":"Energy Changes During Falling"}', 2),
  (1781, 458, 'Ignoring air resistance, which statement is correct as a ball falls?', 'mcq', 1, 'Consider the sum of GPE and KE.', '{"why":"The total mechanical energy remains constant in this ideal situation.","sol":"Step 1: GPE decreases as the ball loses height.\nStep 2: KE increases as it gains speed.\nStep 3: Their sum remains constant when air resistance is ignored.","steps":["Step 1: GPE decreases as the ball loses height.","Step 2: KE increases as it gains speed.","Step 3: Their sum remains constant when air resistance is ignored."],"options":[{"text":"Its total mechanical energy remains constant","is_correct":false},{"text":"Its GPE increases continuously","is_correct":false},{"text":"Its KE must remain zero","is_correct":false},{"text":"Energy is destroyed at every point","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_work_energy_power_energy_changes_during_falling","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q4","subject":"physics","chapter":"work_energy_power","topic":"Energy Changes During Falling"}', 3),
  (1782, 459, 'An object falls from rest through 5 m. Take g = 10 m/s² and ignore air resistance. What is its final speed?', 'mcq', 1, 'Use v = √(2gh).', '{"why":"The final speed is 10 m/s.","sol":"Step 1: v = √(2 × 10 × 5).\nStep 2: v = √100.\nStep 3: v = 10 m/s.","steps":["Step 1: v = √(2 × 10 × 5).","Step 2: v = √100.","Step 3: v = 10 m/s."],"options":[{"text":"5 m/s","is_correct":false},{"text":"10 m/s","is_correct":false},{"text":"25 m/s","is_correct":false},{"text":"50 m/s","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_work_energy_power_calculating_speed_from_lost_gravitational_potential_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q1","subject":"physics","chapter":"work_energy_power","topic":"Calculating Speed from Lost Gravitational Potential Energy"}', 0),
  (1783, 459, 'A stone falls from rest through 20 m. Take g = 10 m/s² and ignore air resistance. Find its final speed.', 'mcq', 1, 'Substitute the height into v = √(2gh).', '{"why":"The final speed is 20 m/s.","sol":"Step 1: v = √(2 × 10 × 20).\nStep 2: v = √400.\nStep 3: v = 20 m/s.","steps":["Step 1: v = √(2 × 10 × 20).","Step 2: v = √400.","Step 3: v = 20 m/s."],"options":[{"text":"10 m/s","is_correct":false},{"text":"15 m/s","is_correct":false},{"text":"20 m/s","is_correct":false},{"text":"40 m/s","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_work_energy_power_calculating_speed_from_lost_gravitational_potential_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q2","subject":"physics","chapter":"work_energy_power","topic":"Calculating Speed from Lost Gravitational Potential Energy"}', 1),
  (1784, 459, 'A ball falls from rest through 1.8 m. Take g = 10 m/s² and ignore air resistance. What is its final speed?', 'mcq', 1, 'Calculate √(2 × 10 × 1.8).', '{"why":"The final speed is 6 m/s.","sol":"Step 1: v = √(2gh).\nStep 2: v = √36.\nStep 3: v = 6 m/s.","steps":["Step 1: v = √(2gh).","Step 2: v = √36.","Step 3: v = 6 m/s."],"options":[{"text":"3 m/s","is_correct":false},{"text":"6 m/s","is_correct":false},{"text":"9 m/s","is_correct":false},{"text":"18 m/s","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_work_energy_power_calculating_speed_from_lost_gravitational_potential_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q3","subject":"physics","chapter":"work_energy_power","topic":"Calculating Speed from Lost Gravitational Potential Energy"}', 2),
  (1785, 459, 'Why does the mass cancel when deriving v = √(2gh) from mgh = ½mv²?', 'mcq', 1, 'Look at the factor m on each side of the equation.', '{"why":"Mass cancels because it appears as a common factor on both sides.","sol":"Step 1: Start with mgh = ½mv².\nStep 2: Divide both sides by the same non-zero mass.\nStep 3: This gives gh = ½v², so v = √(2gh).","steps":["Step 1: Start with mgh = ½mv².","Step 2: Divide both sides by the same non-zero mass.","Step 3: This gives gh = ½v², so v = √(2gh)."],"options":[{"text":"Mass is always zero during falling","is_correct":false},{"text":"The same non-zero mass appears on both sides","is_correct":false},{"text":"Gravity does not act on mass","is_correct":false},{"text":"Kinetic energy does not depend on mass","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_work_energy_power_calculating_speed_from_lost_gravitational_potential_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q4","subject":"physics","chapter":"work_energy_power","topic":"Calculating Speed from Lost Gravitational Potential Energy"}', 3),
  (1786, 460, 'An electric lamp produces light for illumination. Which output is useful for that purpose?', 'mcq', 1, 'Identify the lamp''s intended purpose.', '{"why":"Light is the useful energy output for a lamp intended to illuminate a room.","sol":"Step 1: The lamp is intended to provide illumination.\nStep 2: Light energy provides that illumination.","steps":["Step 1: The lamp is intended to provide illumination.","Step 2: Light energy provides that illumination."],"options":[{"text":"All thermal energy escaping into the room","is_correct":false},{"text":"Light energy","is_correct":false},{"text":"Sound from a loose component","is_correct":false},{"text":"Energy transferred to unwanted heating","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_work_energy_power_useful_and_wasted_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q1","subject":"physics","chapter":"work_energy_power","topic":"Useful and Wasted Energy"}', 0),
  (1787, 460, 'A device receives 200 J and produces 50 J of useful energy. Calculate its efficiency.', 'mcq', 1, 'Efficiency = useful output ÷ total input × 100%.', '{"why":"The device converts 25% of its input energy into useful output.","sol":"Step 1: Efficiency = (50 ÷ 200) × 100%.\nStep 2: Efficiency = 0.25 × 100%.\nStep 3: Efficiency = 25%.","steps":["Step 1: Efficiency = (50 ÷ 200) × 100%.","Step 2: Efficiency = 0.25 × 100%.","Step 3: Efficiency = 25%."],"options":[{"text":"25%","is_correct":false},{"text":"50%","is_correct":false},{"text":"75%","is_correct":false},{"text":"150%","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_work_energy_power_useful_and_wasted_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q2","subject":"physics","chapter":"work_energy_power","topic":"Useful and Wasted Energy"}', 1),
  (1788, 460, 'A motor receives 400 J and provides 280 J of useful energy. How much energy is wasted, assuming these are the only output categories?', 'mcq', 1, 'Subtract the useful output from the total input.', '{"why":"The wasted energy is 120 J.","sol":"Step 1: Wasted energy = total input − useful output.\nStep 2: Wasted energy = 400 J − 280 J.\nStep 3: Wasted energy = 120 J.","steps":["Step 1: Wasted energy = total input − useful output.","Step 2: Wasted energy = 400 J − 280 J.","Step 3: Wasted energy = 120 J."],"options":[{"text":"120 J","is_correct":false},{"text":"280 J","is_correct":false},{"text":"400 J","is_correct":false},{"text":"680 J","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_work_energy_power_useful_and_wasted_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q3","subject":"physics","chapter":"work_energy_power","topic":"Useful and Wasted Energy"}', 2),
  (1789, 460, 'Why is energy described as wasted when it is transferred into unwanted heating?', 'mcq', 1, 'Consider whether the energy is still present but less useful.', '{"why":"Wasted energy still exists, but it is transferred into forms or places that are less useful.","sol":"Step 1: Energy is conserved.\nStep 2: Some energy is transferred to the surroundings as thermal energy.\nStep 3: That energy may not help the device achieve its intended purpose.","steps":["Step 1: Energy is conserved.","Step 2: Some energy is transferred to the surroundings as thermal energy.","Step 3: That energy may not help the device achieve its intended purpose."],"options":[{"text":"It has been destroyed","is_correct":false},{"text":"It no longer exists","is_correct":false},{"text":"It is less useful for the device''s intended purpose","is_correct":false},{"text":"It has become negative energy","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_work_energy_power_useful_and_wasted_energy","skillId":"physics_work_energy_power","subskillId":"physics_work_energy_power_q4","subject":"physics","chapter":"work_energy_power","topic":"Useful and Wasted Energy"}', 3),
  (1790, 461, 'What is the main purpose of a simple machine?', 'text', 1, 'Consider how a machine changes the force or its direction.', '{"why":"Simple machines alter how force is applied to perform a task.","sol":"Step 1: Identify the task a machine helps perform.\nStep 2: Consider force magnitude, direction, and distance.","steps":["Step 1: Identify the task a machine helps perform.","Step 2: Consider force magnitude, direction, and distance."],"options":[],"conceptId":"physics_simple_machines_simple_machines","skillId":"physics_simple_machines","subskillId":"physics_simple_machines_q1","subject":"physics","chapter":"simple_machines","topic":"Simple Machines"}', 0),
  (1791, 461, 'Which simple machine is commonly used as a ramp to move a load to a higher level?', 'text', 1, 'It is a flat surface set at an angle.', '{"why":"An inclined plane can reduce the force needed by increasing the distance over which it acts.","sol":"Step 1: Identify the surface that slopes upward.\nStep 2: Match it to the simple machine.","steps":["Step 1: Identify the surface that slopes upward.","Step 2: Match it to the simple machine."],"options":[],"conceptId":"physics_simple_machines_simple_machines","skillId":"physics_simple_machines","subskillId":"physics_simple_machines_q2","subject":"physics","chapter":"simple_machines","topic":"Simple Machines"}', 1),
  (1792, 461, 'A fixed pulley is used to lift a bucket. What is one important advantage of the pulley?', 'text', 1, 'Think about the direction of the effort.', '{"why":"A single fixed pulley mainly changes the direction of the force.","sol":"Step 1: The load moves upward.\nStep 2: The person can pull downward.\nStep 3: The pulley changes the direction of the applied force.","steps":["Step 1: The load moves upward.","Step 2: The person can pull downward.","Step 3: The pulley changes the direction of the applied force."],"options":[],"conceptId":"physics_simple_machines_simple_machines","skillId":"physics_simple_machines","subskillId":"physics_simple_machines_q3","subject":"physics","chapter":"simple_machines","topic":"Simple Machines"}', 2),
  (1793, 461, 'In an ideal machine, the input work is 120 J. What is the output work?', 'text', 1, 'There are no energy losses in an ideal machine.', '{"why":"Without losses, the work supplied equals the work delivered.","sol":"Step 1: Ideal machines have 100% efficiency.\nStep 2: Output work equals input work.\nStep 3: Output work = 120 J.","steps":["Step 1: Ideal machines have 100% efficiency.","Step 2: Output work equals input work.","Step 3: Output work = 120 J."],"options":[],"conceptId":"physics_simple_machines_simple_machines","skillId":"physics_simple_machines","subskillId":"physics_simple_machines_q4","subject":"physics","chapter":"simple_machines","topic":"Simple Machines"}', 3),
  (1794, 461, 'Why is the input work usually greater than the useful output work in a real machine?', 'text', 1, 'Consider friction between moving surfaces.', '{"why":"A real machine cannot convert all input energy into useful output work.","sol":"Step 1: Friction acts during motion.\nStep 2: Some energy is transferred to the surroundings.\nStep 3: Less input energy remains as useful output work.","steps":["Step 1: Friction acts during motion.","Step 2: Some energy is transferred to the surroundings.","Step 3: Less input energy remains as useful output work."],"options":[],"conceptId":"physics_simple_machines_simple_machines","skillId":"physics_simple_machines","subskillId":"physics_simple_machines_q5","subject":"physics","chapter":"simple_machines","topic":"Simple Machines"}', 4),
  (1795, 462, 'A machine lifts a load of 400 N with an effort of 100 N. Find its mechanical advantage.', 'text', 1, 'Divide the load by the effort.', '{"why":"400 N divided by 100 N gives a mechanical advantage of 4.","sol":"Step 1: MA = 400/100.\nStep 2: MA = 4.","steps":["Step 1: MA = 400/100.","Step 2: MA = 4."],"options":[],"conceptId":"physics_simple_machines_mechanical_advantage","skillId":"physics_simple_machines","subskillId":"physics_simple_machines_q1","subject":"physics","chapter":"simple_machines","topic":"Mechanical Advantage"}', 0),
  (1796, 462, 'A lever lifts 900 N using an effort of 300 N. Calculate its mechanical advantage.', 'text', 1, 'Use MA = load ÷ effort.', '{"why":"The force units cancel, so MA = 3 without a unit.","sol":"Step 1: MA = 900/300.\nStep 2: MA = 3.","steps":["Step 1: MA = 900/300.","Step 2: MA = 3."],"options":[],"conceptId":"physics_simple_machines_mechanical_advantage","skillId":"physics_simple_machines","subskillId":"physics_simple_machines_q2","subject":"physics","chapter":"simple_machines","topic":"Mechanical Advantage"}', 1),
  (1797, 462, 'A machine has a mechanical advantage of 5 and an effort of 40 N. Find the load.', 'text', 1, 'Rearrange MA = load ÷ effort.', '{"why":"A mechanical advantage of 5 means the load is five times the effort.","sol":"Step 1: Load = 5 × 40 N.\nStep 2: Load = 200 N.","steps":["Step 1: Load = 5 × 40 N.","Step 2: Load = 200 N."],"options":[],"conceptId":"physics_simple_machines_mechanical_advantage","skillId":"physics_simple_machines","subskillId":"physics_simple_machines_q3","subject":"physics","chapter":"simple_machines","topic":"Mechanical Advantage"}', 2),
  (1798, 462, 'A machine lifts a load of 720 N and has a mechanical advantage of 6. Calculate the effort.', 'text', 1, 'Rearrange the formula to make effort the subject.', '{"why":"Effort = load divided by mechanical advantage.","sol":"Step 1: Effort = 720/6.\nStep 2: Effort = 120 N.","steps":["Step 1: Effort = 720/6.","Step 2: Effort = 120 N."],"options":[],"conceptId":"physics_simple_machines_mechanical_advantage","skillId":"physics_simple_machines","subskillId":"physics_simple_machines_q4","subject":"physics","chapter":"simple_machines","topic":"Mechanical Advantage"}', 3),
  (1799, 462, 'A machine uses an effort of 80 N to move a load of 80 N. Find its mechanical advantage.', 'text', 1, 'Divide 80 by 80.', '{"why":"MA = 1 means the load force equals the effort force.","sol":"Step 1: MA = 80/80.\nStep 2: MA = 1.","steps":["Step 1: MA = 80/80.","Step 2: MA = 1."],"options":[],"conceptId":"physics_simple_machines_mechanical_advantage","skillId":"physics_simple_machines","subskillId":"physics_simple_machines_q5","subject":"physics","chapter":"simple_machines","topic":"Mechanical Advantage"}', 4),
  (1800, 463, 'The effort moves 3 m while the load moves 1 m. Find the velocity ratio.', 'text', 1, 'Divide the effort distance by the load distance.', '{"why":"The effort moves three times as far as the load.","sol":"Step 1: VR = 3/1.\nStep 2: VR = 3.","steps":["Step 1: VR = 3/1.","Step 2: VR = 3."],"options":[],"conceptId":"physics_simple_machines_velocity_ratio","skillId":"physics_simple_machines","subskillId":"physics_simple_machines_q1","subject":"physics","chapter":"simple_machines","topic":"Velocity Ratio"}', 0),
  (1801, 463, 'In a machine, the effort moves 4 m and the load moves 0.8 m. Calculate VR.', 'text', 1, 'Calculate 4 ÷ 0.8.', '{"why":"4 divided by 0.8 equals 5.","sol":"Step 1: VR = 4/0.8.\nStep 2: VR = 5.","steps":["Step 1: VR = 4/0.8.","Step 2: VR = 5."],"options":[],"conceptId":"physics_simple_machines_velocity_ratio","skillId":"physics_simple_machines","subskillId":"physics_simple_machines_q2","subject":"physics","chapter":"simple_machines","topic":"Velocity Ratio"}', 1),
  (1802, 463, 'A machine has a velocity ratio of 6. The load moves 0.5 m. How far does the effort move?', 'text', 1, 'Effort distance = VR × load distance.', '{"why":"6 × 0.5 m = 3 m.","sol":"Step 1: Effort distance = 6 × 0.5 m.\nStep 2: Effort distance = 3 m.","steps":["Step 1: Effort distance = 6 × 0.5 m.","Step 2: Effort distance = 3 m."],"options":[],"conceptId":"physics_simple_machines_velocity_ratio","skillId":"physics_simple_machines","subskillId":"physics_simple_machines_q3","subject":"physics","chapter":"simple_machines","topic":"Velocity Ratio"}', 2),
  (1803, 463, 'The effort moves 2.4 m and the load moves 0.6 m. Find the velocity ratio.', 'text', 1, 'Divide 2.4 by 0.6.', '{"why":"The effort moves four times as far as the load.","sol":"Step 1: VR = 2.4/0.6.\nStep 2: VR = 4.","steps":["Step 1: VR = 2.4/0.6.","Step 2: VR = 4."],"options":[],"conceptId":"physics_simple_machines_velocity_ratio","skillId":"physics_simple_machines","subskillId":"physics_simple_machines_q4","subject":"physics","chapter":"simple_machines","topic":"Velocity Ratio"}', 3),
  (1804, 463, 'A machine has VR = 8. If the effort moves 4 m, how far does the load move?', 'text', 1, 'Load distance = effort distance ÷ VR.', '{"why":"4 m divided by 8 gives a load distance of 0.5 m.","sol":"Step 1: Load distance = 4/8.\nStep 2: Load distance = 0.5 m.","steps":["Step 1: Load distance = 4/8.","Step 2: Load distance = 0.5 m."],"options":[],"conceptId":"physics_simple_machines_velocity_ratio","skillId":"physics_simple_machines","subskillId":"physics_simple_machines_q5","subject":"physics","chapter":"simple_machines","topic":"Velocity Ratio"}', 4),
  (1805, 464, 'Which quantity compares load force with effort force?', 'text', 1, 'One ratio uses forces, not distances.', '{"why":"Mechanical advantage compares the forces.","sol":"Step 1: Identify the ratio defined as load divided by effort.","steps":["Step 1: Identify the ratio defined as load divided by effort."],"options":[],"conceptId":"physics_simple_machines_mechanical_advantage_and_velocity_ratio","skillId":"physics_simple_machines","subskillId":"physics_simple_machines_q1","subject":"physics","chapter":"simple_machines","topic":"Mechanical Advantage and Velocity Ratio"}', 0),
  (1806, 464, 'Which quantity compares the distance moved by effort with the distance moved by load?', 'text', 1, 'This ratio is based on movement distances.', '{"why":"Velocity ratio compares distances moved.","sol":"Step 1: Identify the ratio defined using two distances.","steps":["Step 1: Identify the ratio defined using two distances."],"options":[],"conceptId":"physics_simple_machines_mechanical_advantage_and_velocity_ratio","skillId":"physics_simple_machines","subskillId":"physics_simple_machines_q2","subject":"physics","chapter":"simple_machines","topic":"Mechanical Advantage and Velocity Ratio"}', 1),
  (1807, 464, 'An ideal machine has VR = 4. What is its mechanical advantage?', 'text', 1, 'In an ideal machine, the two ratios are equal.', '{"why":"Ideal machines have no energy losses, so MA equals VR.","sol":"Step 1: VR = 4.\nStep 2: For an ideal machine, MA = VR.\nStep 3: MA = 4.","steps":["Step 1: VR = 4.","Step 2: For an ideal machine, MA = VR.","Step 3: MA = 4."],"options":[],"conceptId":"physics_simple_machines_mechanical_advantage_and_velocity_ratio","skillId":"physics_simple_machines","subskillId":"physics_simple_machines_q3","subject":"physics","chapter":"simple_machines","topic":"Mechanical Advantage and Velocity Ratio"}', 2),
  (1808, 464, 'A real machine has MA = 2 and VR = 4. Which ratio is greater?', 'text', 1, 'Compare the numerical values 2 and 4.', '{"why":"The two ratios describe different things, and real-machine losses typically make MA smaller than VR.","sol":"Step 1: MA = 2.\nStep 2: VR = 4.\nStep 3: VR is greater than MA.","steps":["Step 1: MA = 2.","Step 2: VR = 4.","Step 3: VR is greater than MA."],"options":[],"conceptId":"physics_simple_machines_mechanical_advantage_and_velocity_ratio","skillId":"physics_simple_machines","subskillId":"physics_simple_machines_q4","subject":"physics","chapter":"simple_machines","topic":"Mechanical Advantage and Velocity Ratio"}', 3),
  (1809, 464, 'A machine has a load of 300 N, an effort of 100 N, an effort distance of 2 m and a load distance of 0.5 m. Calculate MA and VR.', 'text', 1, 'Calculate each ratio separately using its own formula.', '{"why":"MA uses forces, while VR uses distances.","sol":"Step 1: MA = 300/100 = 3.\nStep 2: VR = 2/0.5 = 4.","steps":["Step 1: MA = 300/100 = 3.","Step 2: VR = 2/0.5 = 4."],"options":[],"conceptId":"physics_simple_machines_mechanical_advantage_and_velocity_ratio","skillId":"physics_simple_machines","subskillId":"physics_simple_machines_q5","subject":"physics","chapter":"simple_machines","topic":"Mechanical Advantage and Velocity Ratio"}', 4),
  (1810, 465, 'A machine has MA = 2 and VR = 4. Calculate its efficiency.', 'text', 1, 'Divide MA by VR and multiply by 100%.', '{"why":"2 divided by 4 is 0.5, equivalent to 50%.","sol":"Step 1: Efficiency = (2/4) × 100%.\nStep 2: Efficiency = 50%.","steps":["Step 1: Efficiency = (2/4) × 100%.","Step 2: Efficiency = 50%."],"options":[],"conceptId":"physics_simple_machines_efficiency_of_machines","skillId":"physics_simple_machines","subskillId":"physics_simple_machines_q1","subject":"physics","chapter":"simple_machines","topic":"Efficiency of Machines"}', 0),
  (1811, 465, 'A machine has MA = 4 and VR = 5. Find its efficiency.', 'text', 1, 'Calculate 4 ÷ 5 × 100%.', '{"why":"The ratio 0.8 is equal to 80%.","sol":"Step 1: Efficiency = (4/5) × 100%.\nStep 2: Efficiency = 80%.","steps":["Step 1: Efficiency = (4/5) × 100%.","Step 2: Efficiency = 80%."],"options":[],"conceptId":"physics_simple_machines_efficiency_of_machines","skillId":"physics_simple_machines","subskillId":"physics_simple_machines_q2","subject":"physics","chapter":"simple_machines","topic":"Efficiency of Machines"}', 1),
  (1812, 465, 'A machine has MA = 3 and an efficiency of 60%. Calculate its velocity ratio.', 'text', 1, 'Rearrange efficiency = MA/VR × 100%.', '{"why":"VR = 300/60 = 5.","sol":"Step 1: 60 = (3/VR) × 100.\nStep 2: VR = 3 × 100/60.\nStep 3: VR = 5.","steps":["Step 1: 60 = (3/VR) × 100.","Step 2: VR = 3 × 100/60.","Step 3: VR = 5."],"options":[],"conceptId":"physics_simple_machines_efficiency_of_machines","skillId":"physics_simple_machines","subskillId":"physics_simple_machines_q3","subject":"physics","chapter":"simple_machines","topic":"Efficiency of Machines"}', 2),
  (1813, 465, 'A machine has VR = 8 and efficiency = 75%. Calculate its mechanical advantage.', 'text', 1, 'Rearrange efficiency = MA/VR × 100%.', '{"why":"MA = 0.75 × 8 = 6.","sol":"Step 1: MA = (75 × 8)/100.\nStep 2: MA = 600/100.\nStep 3: MA = 6.","steps":["Step 1: MA = (75 × 8)/100.","Step 2: MA = 600/100.","Step 3: MA = 6."],"options":[],"conceptId":"physics_simple_machines_efficiency_of_machines","skillId":"physics_simple_machines","subskillId":"physics_simple_machines_q4","subject":"physics","chapter":"simple_machines","topic":"Efficiency of Machines"}', 3),
  (1814, 465, 'Why is a real machine usually less than 100% efficient?', 'text', 1, 'Think about friction and energy transferred to the surroundings.', '{"why":"Efficiency measures useful output, not the total amount of energy accounted for.","sol":"Step 1: A machine receives input energy.\nStep 2: Friction and other effects transfer some energy into less useful forms.\nStep 3: Useful output is therefore less than input.","steps":["Step 1: A machine receives input energy.","Step 2: Friction and other effects transfer some energy into less useful forms.","Step 3: Useful output is therefore less than input."],"options":[],"conceptId":"physics_simple_machines_efficiency_of_machines","skillId":"physics_simple_machines","subskillId":"physics_simple_machines_q5","subject":"physics","chapter":"simple_machines","topic":"Efficiency of Machines"}', 4),
  (1815, 466, 'An effort of 40 N moves 5 m. Calculate the work input.', 'text', 1, 'Multiply effort by the distance it moves.', '{"why":"40 N × 5 m = 200 J.","sol":"Step 1: Work input = 40 × 5.\nStep 2: Work input = 200 J.","steps":["Step 1: Work input = 40 × 5.","Step 2: Work input = 200 J."],"options":[],"conceptId":"physics_simple_machines_work_input_and_work_output","skillId":"physics_simple_machines","subskillId":"physics_simple_machines_q1","subject":"physics","chapter":"simple_machines","topic":"Work Input and Work Output"}', 0),
  (1816, 466, 'A load of 300 N rises through 0.4 m. Calculate the useful work output.', 'text', 1, 'Multiply the load force by the distance the load moves.', '{"why":"300 N × 0.4 m = 120 J.","sol":"Step 1: Work output = 300 × 0.4.\nStep 2: Work output = 120 J.","steps":["Step 1: Work output = 300 × 0.4.","Step 2: Work output = 120 J."],"options":[],"conceptId":"physics_simple_machines_work_input_and_work_output","skillId":"physics_simple_machines","subskillId":"physics_simple_machines_q2","subject":"physics","chapter":"simple_machines","topic":"Work Input and Work Output"}', 1),
  (1817, 466, 'A machine receives 500 J of work input and delivers 350 J of useful output work. How much work is not delivered as useful output?', 'text', 1, 'Subtract useful output from input.', '{"why":"500 J − 350 J = 150 J.","sol":"Step 1: Difference = 500 − 350.\nStep 2: Difference = 150 J.","steps":["Step 1: Difference = 500 − 350.","Step 2: Difference = 150 J."],"options":[],"conceptId":"physics_simple_machines_work_input_and_work_output","skillId":"physics_simple_machines","subskillId":"physics_simple_machines_q3","subject":"physics","chapter":"simple_machines","topic":"Work Input and Work Output"}', 2),
  (1818, 466, 'An ideal machine receives 250 J of work input. Calculate its work output.', 'text', 1, 'An ideal machine has no energy losses.', '{"why":"An ideal machine transfers all its input work into useful output work.","sol":"Step 1: For an ideal machine, input work equals output work.\nStep 2: Output work = 250 J.","steps":["Step 1: For an ideal machine, input work equals output work.","Step 2: Output work = 250 J."],"options":[],"conceptId":"physics_simple_machines_work_input_and_work_output","skillId":"physics_simple_machines","subskillId":"physics_simple_machines_q4","subject":"physics","chapter":"simple_machines","topic":"Work Input and Work Output"}', 3),
  (1819, 466, 'A machine has an effort of 60 N moving 4 m and lifts a load of 160 N by 1 m. Calculate the input work, output work and efficiency.', 'text', 1, 'Calculate both work values, then divide output by input and multiply by 100%.', '{"why":"Efficiency = 160 ÷ 240 × 100% ≈ 66.7%.","sol":"Step 1: Input work = 60 × 4 = 240 J.\nStep 2: Output work = 160 × 1 = 160 J.\nStep 3: Efficiency = (160/240) × 100% ≈ 66.7%.","steps":["Step 1: Input work = 60 × 4 = 240 J.","Step 2: Output work = 160 × 1 = 160 J.","Step 3: Efficiency = (160/240) × 100% ≈ 66.7%."],"options":[],"conceptId":"physics_simple_machines_work_input_and_work_output","skillId":"physics_simple_machines","subskillId":"physics_simple_machines_q5","subject":"physics","chapter":"simple_machines","topic":"Work Input and Work Output"}', 4),
  (1820, 467, 'A perpendicular force of 60 N acts on an area of 3 m². Calculate the pressure.', 'text', 1, 'Pressure = force ÷ area.', '{"why":"Pressure is force per unit area.","sol":"Step 1: Write P = F/A.\nStep 2: Substitute P = 60/3.\nStep 3: Calculate P = 20 Pa.","steps":["Step 1: Write P = F/A.","Step 2: Substitute P = 60/3.","Step 3: Calculate P = 20 Pa."],"options":[],"conceptId":"physics_pressure_pressure_in_solids","skillId":"physics_pressure","subskillId":"physics_pressure_q1","subject":"physics","chapter":"pressure","topic":"Pressure in Solids"}', 0),
  (1821, 467, 'A force of 120 N acts over an area of 0.4 m². Find the pressure.', 'text', 1, 'Divide 120 by 0.4.', '{"why":"A force spread over 0.4 m² produces a pressure of 300 Pa.","sol":"Step 1: Write P = F/A.\nStep 2: Substitute P = 120/0.4.\nStep 3: Calculate P = 300 Pa.","steps":["Step 1: Write P = F/A.","Step 2: Substitute P = 120/0.4.","Step 3: Calculate P = 300 Pa."],"options":[],"conceptId":"physics_pressure_pressure_in_solids","skillId":"physics_pressure","subskillId":"physics_pressure_q2","subject":"physics","chapter":"pressure","topic":"Pressure in Solids"}', 1),
  (1822, 467, 'A pressure of 500 Pa acts over an area of 0.2 m². Calculate the perpendicular force.', 'text', 1, 'Rearrange P = F/A to make F the subject.', '{"why":"Force equals pressure multiplied by area.","sol":"Step 1: Start with P = F/A.\nStep 2: Multiply both sides by A: F = PA.\nStep 3: Substitute F = 500 × 0.2 = 100 N.","steps":["Step 1: Start with P = F/A.","Step 2: Multiply both sides by A: F = PA.","Step 3: Substitute F = 500 × 0.2 = 100 N."],"options":[],"conceptId":"physics_pressure_pressure_in_solids","skillId":"physics_pressure","subskillId":"physics_pressure_q3","subject":"physics","chapter":"pressure","topic":"Pressure in Solids"}', 2),
  (1823, 467, 'The same force acts on two surfaces. Surface A has area 0.1 m² and surface B has area 0.5 m². Which surface experiences greater pressure?', 'text', 1, 'For the same force, compare the areas.', '{"why":"Pressure is inversely proportional to area when the force is fixed.","sol":"Step 1: Use P = F/A.\nStep 2: The force is the same for both surfaces.\nStep 3: The smaller area produces the greater pressure, so surface A has greater pressure.","steps":["Step 1: Use P = F/A.","Step 2: The force is the same for both surfaces.","Step 3: The smaller area produces the greater pressure, so surface A has greater pressure."],"options":[],"conceptId":"physics_pressure_pressure_in_solids","skillId":"physics_pressure","subskillId":"physics_pressure_q4","subject":"physics","chapter":"pressure","topic":"Pressure in Solids"}', 3),
  (1824, 467, 'Convert an area of 200 cm² into m² before using it in a pressure calculation.', 'text', 1, '1 m² = 10,000 cm².', '{"why":"Pressure in pascals uses area in square metres.","sol":"Step 1: Use 1 m² = 10,000 cm².\nStep 2: Calculate 200 ÷ 10,000.\nStep 3: Area = 0.02 m².","steps":["Step 1: Use 1 m² = 10,000 cm².","Step 2: Calculate 200 ÷ 10,000.","Step 3: Area = 0.02 m²."],"options":[],"conceptId":"physics_pressure_pressure_in_solids","skillId":"physics_pressure","subskillId":"physics_pressure_q5","subject":"physics","chapter":"pressure","topic":"Pressure in Solids"}', 4),
  (1825, 467, 'Why does a sharp knife cut more easily than a blunt knife when the same force is applied?', 'text', 1, 'Compare the contact areas of the two edges.', '{"why":"A smaller area concentrates the applied force.","sol":"Step 1: A sharp edge has a smaller contact area.\nStep 2: Pressure equals force divided by area.\nStep 3: The smaller area produces greater pressure.","steps":["Step 1: A sharp edge has a smaller contact area.","Step 2: Pressure equals force divided by area.","Step 3: The smaller area produces greater pressure."],"options":[],"conceptId":"physics_pressure_pressure_in_solids","skillId":"physics_pressure","subskillId":"physics_pressure_q6","subject":"physics","chapter":"pressure","topic":"Pressure in Solids"}', 5),
  (1826, 467, 'A force of 500 N acts on a contact area of 0.25 m². Calculate the pressure.', 'text', 1, 'Divide 500 by 0.25.', '{"why":"500 N ÷ 0.25 m² = 2,000 Pa.","sol":"Step 1: P = 500/0.25.\nStep 2: P = 2,000 Pa.","steps":["Step 1: P = 500/0.25.","Step 2: P = 2,000 Pa."],"options":[],"conceptId":"physics_pressure_pressure_in_solids","skillId":"physics_pressure","subskillId":"physics_pressure_q7","subject":"physics","chapter":"pressure","topic":"Pressure in Solids"}', 6),
  (1827, 467, 'A 600 N object rests on a horizontal floor over an area of 2 m². Find the pressure it exerts.', 'text', 1, 'Use the object''s weight as the perpendicular force.', '{"why":"Pressure = 600 N ÷ 2 m² = 300 Pa.","sol":"Step 1: P = 600/2.\nStep 2: P = 300 Pa.","steps":["Step 1: P = 600/2.","Step 2: P = 300 Pa."],"options":[],"conceptId":"physics_pressure_pressure_in_solids","skillId":"physics_pressure","subskillId":"physics_pressure_q8","subject":"physics","chapter":"pressure","topic":"Pressure in Solids"}', 7),
  (1828, 467, 'A person stands on one foot rather than two. If the person''s weight stays constant and the contact area halves, what happens to the pressure?', 'text', 1, 'Use the inverse relationship between pressure and area.', '{"why":"The same weight acting on half the area produces twice the pressure.","sol":"Step 1: The weight remains constant.\nStep 2: The contact area becomes half.\nStep 3: Pressure doubles.","steps":["Step 1: The weight remains constant.","Step 2: The contact area becomes half.","Step 3: Pressure doubles."],"options":[],"conceptId":"physics_pressure_pressure_in_solids","skillId":"physics_pressure","subskillId":"physics_pressure_q9","subject":"physics","chapter":"pressure","topic":"Pressure in Solids"}', 8),
  (1829, 467, 'Why are building foundations made wide?', 'text', 1, 'Consider the pressure exerted on the ground.', '{"why":"Pressure decreases when area increases while force remains constant.","sol":"Step 1: The building has a downward load.\nStep 2: A wider foundation increases contact area.\nStep 3: The pressure on the ground decreases for the same load.","steps":["Step 1: The building has a downward load.","Step 2: A wider foundation increases contact area.","Step 3: The pressure on the ground decreases for the same load."],"options":[],"conceptId":"physics_pressure_pressure_in_solids","skillId":"physics_pressure","subskillId":"physics_pressure_q10","subject":"physics","chapter":"pressure","topic":"Pressure in Solids"}', 9),
  (1830, 468, 'Calculate the gauge pressure 3 m below the surface of water. Take ρ = 1000 kg/m³ and g = 10 N/kg.', 'text', 1, 'Use p = ρgh.', '{"why":"Gauge pressure increases with depth in a liquid of uniform density.","sol":"Step 1: Write p = ρgh.\nStep 2: Substitute p = 1000 × 10 × 3.\nStep 3: Calculate p = 30,000 Pa.","steps":["Step 1: Write p = ρgh.","Step 2: Substitute p = 1000 × 10 × 3.","Step 3: Calculate p = 30,000 Pa."],"options":[],"conceptId":"physics_pressure_pressure_in_liquids","skillId":"physics_pressure","subskillId":"physics_pressure_q1","subject":"physics","chapter":"pressure","topic":"Pressure in Liquids"}', 0),
  (1831, 468, 'A point is 2 m below the surface of a liquid of density 800 kg/m³. Take g = 10 N/kg. Calculate the gauge pressure.', 'text', 1, 'Multiply density, gravitational field strength and depth.', '{"why":"The pressure depends on the actual liquid density.","sol":"Step 1: Write p = ρgh.\nStep 2: Substitute p = 800 × 10 × 2.\nStep 3: Calculate p = 16,000 Pa.","steps":["Step 1: Write p = ρgh.","Step 2: Substitute p = 800 × 10 × 2.","Step 3: Calculate p = 16,000 Pa."],"options":[],"conceptId":"physics_pressure_pressure_in_liquids","skillId":"physics_pressure","subskillId":"physics_pressure_q2","subject":"physics","chapter":"pressure","topic":"Pressure in Liquids"}', 1),
  (1832, 468, 'Water produces a gauge pressure of 20,000 Pa at a certain depth. If g = 10 N/kg and water density is 1000 kg/m³, find the depth.', 'text', 1, 'Rearrange p = ρgh to make h the subject.', '{"why":"Depth can be found by dividing gauge pressure by density times gravitational field strength.","sol":"Step 1: Start with p = ρgh.\nStep 2: Rearrange: h = p/(ρg).\nStep 3: Substitute: h = 20,000/(1000 × 10) = 2 m.","steps":["Step 1: Start with p = ρgh.","Step 2: Rearrange: h = p/(ρg).","Step 3: Substitute: h = 20,000/(1000 × 10) = 2 m."],"options":[],"conceptId":"physics_pressure_pressure_in_liquids","skillId":"physics_pressure","subskillId":"physics_pressure_q3","subject":"physics","chapter":"pressure","topic":"Pressure in Liquids"}', 2),
  (1833, 468, 'At the same depth, which produces greater gauge pressure: a liquid of density 1200 kg/m³ or one of density 900 kg/m³?', 'text', 1, 'In p = ρgh, depth and g are the same for both liquids.', '{"why":"A denser liquid produces greater pressure at the same depth.","sol":"Step 1: Compare the densities: 1200 kg/m³ is greater than 900 kg/m³.\nStep 2: The depth and g are unchanged.\nStep 3: The liquid with density 1200 kg/m³ produces greater gauge pressure.","steps":["Step 1: Compare the densities: 1200 kg/m³ is greater than 900 kg/m³.","Step 2: The depth and g are unchanged.","Step 3: The liquid with density 1200 kg/m³ produces greater gauge pressure."],"options":[],"conceptId":"physics_pressure_pressure_in_liquids","skillId":"physics_pressure","subskillId":"physics_pressure_q4","subject":"physics","chapter":"pressure","topic":"Pressure in Liquids"}', 3),
  (1834, 468, 'Why is the gauge pressure at the bottom of a deep tank greater than near the surface?', 'text', 1, 'Consider the weight of liquid above each point.', '{"why":"Liquid pressure depends on density, gravitational field strength and depth.","sol":"Step 1: There is more liquid above the deeper point.\nStep 2: The weight of that liquid produces greater pressure.\nStep 3: Therefore, gauge pressure increases with depth.","steps":["Step 1: There is more liquid above the deeper point.","Step 2: The weight of that liquid produces greater pressure.","Step 3: Therefore, gauge pressure increases with depth."],"options":[],"conceptId":"physics_pressure_pressure_in_liquids","skillId":"physics_pressure","subskillId":"physics_pressure_q5","subject":"physics","chapter":"pressure","topic":"Pressure in Liquids"}', 4),
  (1835, 468, 'Calculate the liquid pressure at a depth of 3 m in water of density 1,000 kg/m³. Take g = 10 N/kg.', 'text', 1, 'Substitute density, gravitational field strength and depth into p = ρgh.', '{"why":"Liquid pressure = 1,000 × 10 × 3 = 30,000 Pa.","sol":"Step 1: p = 1,000 × 10 × 3.\nStep 2: p = 30,000 Pa.","steps":["Step 1: p = 1,000 × 10 × 3.","Step 2: p = 30,000 Pa."],"options":[],"conceptId":"physics_pressure_pressure_in_liquids","skillId":"physics_pressure","subskillId":"physics_pressure_q6","subject":"physics","chapter":"pressure","topic":"Pressure in Liquids"}', 5),
  (1836, 468, 'A liquid has density 800 kg/m³. Find the pressure at 2 m depth using g = 10 N/kg.', 'text', 1, 'Use p = ρgh.', '{"why":"p = 800 × 10 × 2 = 16,000 Pa.","sol":"Step 1: p = 800 × 10 × 2.\nStep 2: p = 16,000 Pa.","steps":["Step 1: p = 800 × 10 × 2.","Step 2: p = 16,000 Pa."],"options":[],"conceptId":"physics_pressure_pressure_in_liquids","skillId":"physics_pressure","subskillId":"physics_pressure_q7","subject":"physics","chapter":"pressure","topic":"Pressure in Liquids"}', 6),
  (1837, 468, 'Water pressure due to the liquid alone is 40,000 Pa. Find the depth, taking water density as 1,000 kg/m³ and g = 10 N/kg.', 'text', 1, 'Rearrange p = ρgh to make h the subject.', '{"why":"h = 40,000 ÷ 10,000 = 4 m.","sol":"Step 1: h = 40,000/(1,000 × 10).\nStep 2: h = 4 m.","steps":["Step 1: h = 40,000/(1,000 × 10).","Step 2: h = 4 m."],"options":[],"conceptId":"physics_pressure_pressure_in_liquids","skillId":"physics_pressure","subskillId":"physics_pressure_q8","subject":"physics","chapter":"pressure","topic":"Pressure in Liquids"}', 7),
  (1838, 468, 'At a depth of 1.5 m in water, calculate the liquid pressure using ρ = 1,000 kg/m³ and g = 10 N/kg.', 'text', 1, 'Multiply 1,000 by 10 and then by 1.5.', '{"why":"p = 15,000 Pa.","sol":"Step 1: p = 1,000 × 10 × 1.5.\nStep 2: p = 15,000 Pa.","steps":["Step 1: p = 1,000 × 10 × 1.5.","Step 2: p = 15,000 Pa."],"options":[],"conceptId":"physics_pressure_pressure_in_liquids","skillId":"physics_pressure","subskillId":"physics_pressure_q9","subject":"physics","chapter":"pressure","topic":"Pressure in Liquids"}', 8),
  (1839, 468, 'At the same depth, compare the liquid pressure in water of density 1,000 kg/m³ and oil of density 800 kg/m³.', 'text', 1, 'Pressure is proportional to density when depth and g are constant.', '{"why":"The denser liquid produces greater pressure at the same depth.","sol":"Step 1: Both liquids have the same depth.\nStep 2: Water has density 1,000 kg/m³; oil has density 800 kg/m³.\nStep 3: Water pressure is 1,000/800 = 1.25 times the oil pressure.","steps":["Step 1: Both liquids have the same depth.","Step 2: Water has density 1,000 kg/m³; oil has density 800 kg/m³.","Step 3: Water pressure is 1,000/800 = 1.25 times the oil pressure."],"options":[],"conceptId":"physics_pressure_pressure_in_liquids","skillId":"physics_pressure","subskillId":"physics_pressure_q10","subject":"physics","chapter":"pressure","topic":"Pressure in Liquids"}', 9),
  (1840, 468, 'In which direction does liquid pressure act?', 'text', 1, 'Consider the bottom and sides of a container.', '{"why":"Liquids exert pressure on every surface in contact with them.","sol":"Step 1: A liquid presses on the bottom.\nStep 2: It also presses on the sides.\nStep 3: Pressure acts in all directions.","steps":["Step 1: A liquid presses on the bottom.","Step 2: It also presses on the sides.","Step 3: Pressure acts in all directions."],"options":[],"conceptId":"physics_pressure_pressure_in_liquids","skillId":"physics_pressure","subskillId":"physics_pressure_q11","subject":"physics","chapter":"pressure","topic":"Pressure in Liquids"}', 10),
  (1841, 468, 'At which point is the pressure greater: 20 cm or 80 cm below the surface of the same stationary liquid?', 'text', 1, 'Compare the depths.', '{"why":"The deeper point supports a taller column of liquid.","sol":"Step 1: 80 cm is deeper than 20 cm.\nStep 2: Greater depth means greater liquid pressure.","steps":["Step 1: 80 cm is deeper than 20 cm.","Step 2: Greater depth means greater liquid pressure."],"options":[],"conceptId":"physics_pressure_pressure_in_liquids","skillId":"physics_pressure","subskillId":"physics_pressure_q12","subject":"physics","chapter":"pressure","topic":"Pressure in Liquids"}', 11),
  (1842, 468, 'Two points are at the same depth in the same stationary liquid. How do their pressures compare?', 'text', 1, 'Depth and liquid density are equal.', '{"why":"At the same depth, liquid pressure is the same under these conditions.","sol":"Step 1: Both points have the same depth.\nStep 2: They are in the same liquid.\nStep 3: Their liquid pressures are equal.","steps":["Step 1: Both points have the same depth.","Step 2: They are in the same liquid.","Step 3: Their liquid pressures are equal."],"options":[],"conceptId":"physics_pressure_pressure_in_liquids","skillId":"physics_pressure","subskillId":"physics_pressure_q13","subject":"physics","chapter":"pressure","topic":"Pressure in Liquids"}', 12),
  (1843, 468, 'Does a wider container automatically produce greater pressure at the same depth?', 'text', 1, 'Think about what determines liquid pressure.', '{"why":"For the same liquid and depth, container width does not change the pressure.","sol":"Step 1: Liquid pressure depends on density, gravity and depth.\nStep 2: Container width is not in the pressure equation.","steps":["Step 1: Liquid pressure depends on density, gravity and depth.","Step 2: Container width is not in the pressure equation."],"options":[],"conceptId":"physics_pressure_pressure_in_liquids","skillId":"physics_pressure","subskillId":"physics_pressure_q14","subject":"physics","chapter":"pressure","topic":"Pressure in Liquids"}', 13),
  (1844, 468, 'Why does water usually emerge farther from a lower hole in a water-filled tank?', 'text', 1, 'Compare the pressure at the two holes.', '{"why":"The increasing pressure with depth pushes water out more strongly.","sol":"Step 1: The lower hole is at greater depth.\nStep 2: Pressure is greater there.\nStep 3: Water therefore emerges with a greater driving pressure.","steps":["Step 1: The lower hole is at greater depth.","Step 2: Pressure is greater there.","Step 3: Water therefore emerges with a greater driving pressure."],"options":[],"conceptId":"physics_pressure_pressure_in_liquids","skillId":"physics_pressure","subskillId":"physics_pressure_q15","subject":"physics","chapter":"pressure","topic":"Pressure in Liquids"}', 14),
  (1845, 469, 'What is atmospheric pressure?', 'text', 1, 'Think about the air surrounding Earth and the pressure it exerts.', '{"why":"Atmospheric pressure is exerted by the air surrounding Earth.","sol":"Step 1: Air surrounds Earth and has mass.\nStep 2: Air molecules interact with surfaces, and the atmosphere has weight under gravity.\nStep 3: The resulting pressure is called atmospheric pressure.","steps":["Step 1: Air surrounds Earth and has mass.","Step 2: Air molecules interact with surfaces, and the atmosphere has weight under gravity.","Step 3: The resulting pressure is called atmospheric pressure."],"options":[],"conceptId":"physics_pressure_atmospheric_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q1","subject":"physics","chapter":"pressure","topic":"Atmospheric Pressure"}', 0),
  (1846, 469, 'Why can liquid rise through a drinking straw when a person sucks air from it?', 'text', 1, 'Compare the pressure inside the straw with the atmospheric pressure on the drink.', '{"why":"Liquids move in response to pressure differences.","sol":"Step 1: Sucking lowers the pressure inside the straw.\nStep 2: Atmospheric pressure acts on the liquid surface in the cup.\nStep 3: The pressure difference pushes liquid up the straw.","steps":["Step 1: Sucking lowers the pressure inside the straw.","Step 2: Atmospheric pressure acts on the liquid surface in the cup.","Step 3: The pressure difference pushes liquid up the straw."],"options":[],"conceptId":"physics_pressure_atmospheric_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q2","subject":"physics","chapter":"pressure","topic":"Atmospheric Pressure"}', 1),
  (1847, 469, 'What generally happens to atmospheric pressure as altitude increases?', 'text', 1, 'Think about how much air lies above a high location.', '{"why":"There is generally less air above a location at higher altitude.","sol":"Step 1: At higher altitude, less atmosphere lies above the location.\nStep 2: The air column generally contributes less pressure.\nStep 3: Atmospheric pressure generally decreases.","steps":["Step 1: At higher altitude, less atmosphere lies above the location.","Step 2: The air column generally contributes less pressure.","Step 3: Atmospheric pressure generally decreases."],"options":[],"conceptId":"physics_pressure_atmospheric_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q3","subject":"physics","chapter":"pressure","topic":"Atmospheric Pressure"}', 2),
  (1848, 469, 'Which instrument is used to measure atmospheric pressure?', 'text', 1, 'It is used in weather observations.', '{"why":"Barometers are used to measure atmospheric pressure.","sol":"Step 1: Identify the physical quantity: atmospheric pressure.\nStep 2: The instrument designed to measure it is a barometer.","steps":["Step 1: Identify the physical quantity: atmospheric pressure.","Step 2: The instrument designed to measure it is a barometer."],"options":[],"conceptId":"physics_pressure_atmospheric_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q4","subject":"physics","chapter":"pressure","topic":"Atmospheric Pressure"}', 3),
  (1849, 469, 'Why can atmospheric pressure hold a properly sealed suction cup against a smooth surface?', 'text', 1, 'Compare the pressure outside the cup with the pressure beneath it.', '{"why":"A pressure difference can produce a net force holding the cup in place.","sol":"Step 1: The seal allows pressure beneath the cup to be lower than outside pressure.\nStep 2: Atmospheric pressure acts on the outside of the cup.\nStep 3: The pressure difference presses the cup against the surface.","steps":["Step 1: The seal allows pressure beneath the cup to be lower than outside pressure.","Step 2: Atmospheric pressure acts on the outside of the cup.","Step 3: The pressure difference presses the cup against the surface."],"options":[],"conceptId":"physics_pressure_atmospheric_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q5","subject":"physics","chapter":"pressure","topic":"Atmospheric Pressure"}', 4),
  (1850, 469, 'What is atmospheric pressure?', 'text', 1, 'Think about the air surrounding Earth.', '{"why":"Air exerts pressure because it is a gas with mass and moving particles.","sol":"Step 1: Air has mass and exerts pressure.\nStep 2: The atmosphere exerts pressure on surfaces and objects.","steps":["Step 1: Air has mass and exerts pressure.","Step 2: The atmosphere exerts pressure on surfaces and objects."],"options":[],"conceptId":"physics_pressure_atmospheric_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q6","subject":"physics","chapter":"pressure","topic":"Atmospheric Pressure"}', 5),
  (1851, 469, 'What is the approximate standard atmospheric pressure near sea level?', 'text', 1, 'Recall the standard value in pascals.', '{"why":"Standard atmospheric pressure is approximately 1.013 × 10⁵ Pa.","sol":"Step 1: Standard atmospheric pressure is about 101,325 Pa.\nStep 2: It is often rounded to 101,000 Pa.","steps":["Step 1: Standard atmospheric pressure is about 101,325 Pa.","Step 2: It is often rounded to 101,000 Pa."],"options":[],"conceptId":"physics_pressure_atmospheric_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q7","subject":"physics","chapter":"pressure","topic":"Atmospheric Pressure"}', 6),
  (1852, 469, 'Why does atmospheric pressure generally decrease as altitude increases?', 'text', 1, 'Compare how much air lies above points at different heights.', '{"why":"Atmospheric pressure generally falls with height because the overlying air column becomes smaller.","sol":"Step 1: At greater altitude, less atmosphere lies above the point.\nStep 2: The weight of the overlying air is smaller.\nStep 3: Atmospheric pressure generally decreases.","steps":["Step 1: At greater altitude, less atmosphere lies above the point.","Step 2: The weight of the overlying air is smaller.","Step 3: Atmospheric pressure generally decreases."],"options":[],"conceptId":"physics_pressure_atmospheric_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q8","subject":"physics","chapter":"pressure","topic":"Atmospheric Pressure"}', 7),
  (1853, 469, 'How does a drinking straw allow liquid to rise into the mouth?', 'text', 1, 'Think about pressure inside the straw and pressure on the drink''s surface.', '{"why":"The pressure difference between the liquid surface and the straw drives the liquid upward.","sol":"Step 1: Sucking lowers pressure inside the straw.\nStep 2: Atmospheric pressure acts on the liquid surface in the cup.\nStep 3: The pressure difference pushes liquid up the straw.","steps":["Step 1: Sucking lowers pressure inside the straw.","Step 2: Atmospheric pressure acts on the liquid surface in the cup.","Step 3: The pressure difference pushes liquid up the straw."],"options":[],"conceptId":"physics_pressure_atmospheric_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q9","subject":"physics","chapter":"pressure","topic":"Atmospheric Pressure"}', 8),
  (1854, 469, 'Which instrument is used to measure atmospheric pressure?', 'text', 1, 'It is commonly used in weather observations.', '{"why":"A barometer measures atmospheric pressure.","sol":"Step 1: Identify the instrument for measuring atmospheric pressure.","steps":["Step 1: Identify the instrument for measuring atmospheric pressure."],"options":[],"conceptId":"physics_pressure_atmospheric_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q10","subject":"physics","chapter":"pressure","topic":"Atmospheric Pressure"}', 9),
  (1855, 469, 'What causes atmospheric pressure?', 'text', 1, 'Think about the air above Earth''s surface.', '{"why":"Both the atmosphere''s weight and molecular collisions contribute to atmospheric pressure.","sol":"Step 1: Air has mass.\nStep 2: The atmosphere has weight due to gravity.\nStep 3: Air molecules also collide with surfaces.","steps":["Step 1: Air has mass.","Step 2: The atmosphere has weight due to gravity.","Step 3: Air molecules also collide with surfaces."],"options":[],"conceptId":"physics_pressure_atmospheric_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q11","subject":"physics","chapter":"pressure","topic":"Atmospheric Pressure"}', 10),
  (1856, 469, 'What is the approximate standard atmospheric pressure near sea level?', 'text', 1, 'Give the commonly used value in pascals.', '{"why":"This is the standard reference value near sea level.","sol":"Step 1: Standard atmospheric pressure is approximately 101,325 Pa.\nStep 2: It is often rounded to 101,000 Pa.","steps":["Step 1: Standard atmospheric pressure is approximately 101,325 Pa.","Step 2: It is often rounded to 101,000 Pa."],"options":[],"conceptId":"physics_pressure_atmospheric_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q12","subject":"physics","chapter":"pressure","topic":"Atmospheric Pressure"}', 11),
  (1857, 469, 'How does atmospheric pressure generally change as altitude increases?', 'text', 1, 'There is less air above you at higher altitude.', '{"why":"The overlying air column becomes smaller with increasing altitude.","sol":"Step 1: At higher altitude, less atmosphere lies above a location.\nStep 2: The weight of the air column is lower.\nStep 3: Atmospheric pressure generally decreases.","steps":["Step 1: At higher altitude, less atmosphere lies above a location.","Step 2: The weight of the air column is lower.","Step 3: Atmospheric pressure generally decreases."],"options":[],"conceptId":"physics_pressure_atmospheric_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q13","subject":"physics","chapter":"pressure","topic":"Atmospheric Pressure"}', 12),
  (1858, 469, 'Why can a drinking straw draw liquid upwards when a person sucks on it?', 'text', 1, 'Sucking changes the pressure inside the straw.', '{"why":"The pressure difference, rather than a pulling force exerted by the mouth on the liquid, moves it up.","sol":"Step 1: Sucking lowers the pressure inside the straw.\nStep 2: Atmospheric pressure acts on the liquid surface.\nStep 3: The pressure difference pushes liquid up the straw.","steps":["Step 1: Sucking lowers the pressure inside the straw.","Step 2: Atmospheric pressure acts on the liquid surface.","Step 3: The pressure difference pushes liquid up the straw."],"options":[],"conceptId":"physics_pressure_atmospheric_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q14","subject":"physics","chapter":"pressure","topic":"Atmospheric Pressure"}', 13),
  (1859, 469, 'Does atmospheric pressure act only downwards?', 'text', 1, 'Air surrounds objects.', '{"why":"Atmospheric pressure is not limited to a downward direction.","sol":"Step 1: Air surrounds objects on all sides.\nStep 2: Its pressure acts in all directions.","steps":["Step 1: Air surrounds objects on all sides.","Step 2: Its pressure acts in all directions."],"options":[],"conceptId":"physics_pressure_atmospheric_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q15","subject":"physics","chapter":"pressure","topic":"Atmospheric Pressure"}', 14),
  (1860, 470, 'A tank has two small holes, one near the surface and one much lower down. Why does water generally emerge faster from the lower hole?', 'text', 1, 'Compare the pressure at the two depths.', '{"why":"Liquid pressure depends on depth, density and gravitational field strength.","sol":"Step 1: The lower hole is at a greater depth.\nStep 2: Greater depth gives greater gauge pressure in the water.\nStep 3: The larger pressure difference can make the water emerge faster.","steps":["Step 1: The lower hole is at a greater depth.","Step 2: Greater depth gives greater gauge pressure in the water.","Step 3: The larger pressure difference can make the water emerge faster."],"options":[],"conceptId":"physics_pressure_applications_of_liquid_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q1","subject":"physics","chapter":"pressure","topic":"Applications of Liquid Pressure"}', 0),
  (1861, 470, 'Why is a dam wall often thicker at the bottom than at the top?', 'text', 1, 'Think about the pressure exerted by deeper water.', '{"why":"A dam must withstand the increasing pressure with depth.","sol":"Step 1: Water pressure increases with depth.\nStep 2: The lower part of the wall experiences greater water pressure.\nStep 3: A thicker base helps the dam withstand the resulting forces.","steps":["Step 1: Water pressure increases with depth.","Step 2: The lower part of the wall experiences greater water pressure.","Step 3: A thicker base helps the dam withstand the resulting forces."],"options":[],"conceptId":"physics_pressure_applications_of_liquid_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q2","subject":"physics","chapter":"pressure","topic":"Applications of Liquid Pressure"}', 1),
  (1862, 470, 'A diver moves from 2 m depth to 5 m depth in the same water. Does the gauge pressure increase or decrease?', 'text', 1, 'Compare the two depths in p = ρgh.', '{"why":"Liquid pressure increases with depth.","sol":"Step 1: The liquid density and gravitational field strength remain the same.\nStep 2: Depth increases from 2 m to 5 m.\nStep 3: Gauge pressure therefore increases.","steps":["Step 1: The liquid density and gravitational field strength remain the same.","Step 2: Depth increases from 2 m to 5 m.","Step 3: Gauge pressure therefore increases."],"options":[],"conceptId":"physics_pressure_applications_of_liquid_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q3","subject":"physics","chapter":"pressure","topic":"Applications of Liquid Pressure"}', 2),
  (1863, 470, 'Does liquid pressure at a fixed depth in a uniform liquid depend directly on the shape of the container?', 'text', 1, 'Use the variables in the liquid-pressure formula.', '{"why":"Pressure at a point in a stationary liquid depends on depth, density and g.","sol":"Step 1: The formula includes density, gravitational field strength and depth.\nStep 2: Container shape is not one of these variables.\nStep 3: Therefore, pressure at the same depth is independent of container shape under the same conditions.","steps":["Step 1: The formula includes density, gravitational field strength and depth.","Step 2: Container shape is not one of these variables.","Step 3: Therefore, pressure at the same depth is independent of container shape under the same conditions."],"options":[],"conceptId":"physics_pressure_applications_of_liquid_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q4","subject":"physics","chapter":"pressure","topic":"Applications of Liquid Pressure"}', 3),
  (1864, 470, 'A uniform liquid has density 1000 kg/m³. Taking g = 10 N/kg, calculate the gauge pressure at 4 m depth.', 'text', 1, 'Substitute the density, gravitational field strength and depth into p = ρgh.', '{"why":"The gauge pressure is 40,000 Pa at the stated depth.","sol":"Step 1: Write p = ρgh.\nStep 2: Substitute p = 1000 × 10 × 4.\nStep 3: Calculate p = 40,000 Pa.","steps":["Step 1: Write p = ρgh.","Step 2: Substitute p = 1000 × 10 × 4.","Step 3: Calculate p = 40,000 Pa."],"options":[],"conceptId":"physics_pressure_applications_of_liquid_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q5","subject":"physics","chapter":"pressure","topic":"Applications of Liquid Pressure"}', 4),
  (1865, 471, 'In which directions does a stationary liquid exert pressure at a point?', 'text', 1, 'Pressure is not restricted to the direction of gravity.', '{"why":"Liquid pressure acts in all directions.","sol":"Step 1: A liquid presses on surfaces around it.\nStep 2: At a point in a stationary liquid, pressure acts with equal magnitude in every direction.\nStep 3: Therefore, it is not only downward.","steps":["Step 1: A liquid presses on surfaces around it.","Step 2: At a point in a stationary liquid, pressure acts with equal magnitude in every direction.","Step 3: Therefore, it is not only downward."],"options":[],"conceptId":"physics_pressure_pressure_acts_in_all_directions","skillId":"physics_pressure","subskillId":"physics_pressure_q1","subject":"physics","chapter":"pressure","topic":"Pressure Acts in All Directions"}', 0),
  (1866, 471, 'Why does water flow sideways from a hole in the side of a filled tank?', 'text', 1, 'Consider the force exerted by the water on the tank wall.', '{"why":"A liquid exerts pressure on the sides of its container.","sol":"Step 1: The water exerts pressure on the side wall.\nStep 2: At the hole, the wall no longer blocks the water.\nStep 3: The water can flow outward through the opening.","steps":["Step 1: The water exerts pressure on the side wall.","Step 2: At the hole, the wall no longer blocks the water.","Step 3: The water can flow outward through the opening."],"options":[],"conceptId":"physics_pressure_pressure_acts_in_all_directions","skillId":"physics_pressure","subskillId":"physics_pressure_q2","subject":"physics","chapter":"pressure","topic":"Pressure Acts in All Directions"}', 1),
  (1867, 471, 'At a point in a stationary liquid, how does pressure magnitude compare in different directions?', 'text', 1, 'Use the property of pressure in a fluid at rest.', '{"why":"Pressure in a fluid at rest is equal in every direction at a given point.","sol":"Step 1: Consider a single point in the stationary liquid.\nStep 2: Pressure at that point is isotropic.\nStep 3: Its magnitude is equal in every direction.","steps":["Step 1: Consider a single point in the stationary liquid.","Step 2: Pressure at that point is isotropic.","Step 3: Its magnitude is equal in every direction."],"options":[],"conceptId":"physics_pressure_pressure_acts_in_all_directions","skillId":"physics_pressure","subskillId":"physics_pressure_q3","subject":"physics","chapter":"pressure","topic":"Pressure Acts in All Directions"}', 2),
  (1868, 471, 'What is the direction of the pressure force exerted by a fluid on a flat wall?', 'text', 1, 'Think about the angle between the force and the surface.', '{"why":"Pressure produces a normal force on the surface.","sol":"Step 1: Fluid pressure acts normally on a surface.\nStep 2: Normal means perpendicular.\nStep 3: Therefore, the pressure force is perpendicular to the wall.","steps":["Step 1: Fluid pressure acts normally on a surface.","Step 2: Normal means perpendicular.","Step 3: Therefore, the pressure force is perpendicular to the wall."],"options":[],"conceptId":"physics_pressure_pressure_acts_in_all_directions","skillId":"physics_pressure","subskillId":"physics_pressure_q4","subject":"physics","chapter":"pressure","topic":"Pressure Acts in All Directions"}', 3),
  (1869, 471, 'The bottom of a submerged object is deeper than its top. Why can the water exert a greater pressure on the bottom?', 'text', 1, 'Compare the depths of the two surfaces.', '{"why":"Pressure is equal in all directions at a point, but its magnitude changes with depth.","sol":"Step 1: The bottom is at greater depth.\nStep 2: Liquid pressure increases with depth.\nStep 3: The pressure at the bottom is therefore greater.","steps":["Step 1: The bottom is at greater depth.","Step 2: Liquid pressure increases with depth.","Step 3: The pressure at the bottom is therefore greater."],"options":[],"conceptId":"physics_pressure_pressure_acts_in_all_directions","skillId":"physics_pressure","subskillId":"physics_pressure_q5","subject":"physics","chapter":"pressure","topic":"Pressure Acts in All Directions"}', 4),
  (1870, 472, 'What causes gas pressure inside a sealed container?', 'text', 1, 'Think about how moving gas particles interact with the container walls.', '{"why":"Randomly moving particles collide with the walls and exert pressure.","sol":"Step 1: Gas particles move randomly.\nStep 2: They collide with the container walls.\nStep 3: The collisions exert forces on the walls, producing pressure.","steps":["Step 1: Gas particles move randomly.","Step 2: They collide with the container walls.","Step 3: The collisions exert forces on the walls, producing pressure."],"options":[],"conceptId":"physics_pressure_pressure_in_gases","skillId":"physics_pressure","subskillId":"physics_pressure_q1","subject":"physics","chapter":"pressure","topic":"Pressure in Gases"}', 0),
  (1871, 472, 'A fixed amount of gas is compressed at constant temperature. What happens to its pressure?', 'text', 1, 'The gas occupies a smaller volume while temperature stays constant.', '{"why":"For a fixed amount of gas at constant temperature, pressure increases as volume decreases.","sol":"Step 1: The gas volume decreases.\nStep 2: The particles have less space in which to move.\nStep 3: Collisions with the container walls become more frequent, so pressure increases.","steps":["Step 1: The gas volume decreases.","Step 2: The particles have less space in which to move.","Step 3: Collisions with the container walls become more frequent, so pressure increases."],"options":[],"conceptId":"physics_pressure_pressure_in_gases","skillId":"physics_pressure","subskillId":"physics_pressure_q2","subject":"physics","chapter":"pressure","topic":"Pressure in Gases"}', 1),
  (1872, 472, 'A sealed rigid container of gas is heated. What happens to the gas pressure?', 'text', 1, 'The volume cannot increase, but the particles gain kinetic energy.', '{"why":"Heating a gas in a rigid container increases its pressure.","sol":"Step 1: Heating increases the particles'' average kinetic energy.\nStep 2: The particles collide with the walls more forcefully.\nStep 3: With the volume fixed, the pressure increases.","steps":["Step 1: Heating increases the particles'' average kinetic energy.","Step 2: The particles collide with the walls more forcefully.","Step 3: With the volume fixed, the pressure increases."],"options":[],"conceptId":"physics_pressure_pressure_in_gases","skillId":"physics_pressure","subskillId":"physics_pressure_q3","subject":"physics","chapter":"pressure","topic":"Pressure in Gases"}', 2),
  (1873, 472, 'Why does gas pressure act on the walls in different directions?', 'text', 1, 'Consider the directions in which gas particles move.', '{"why":"Random particle motion produces pressure in all directions.","sol":"Step 1: Gas particles move randomly in many directions.\nStep 2: They collide with different parts of the container walls.\nStep 3: These collisions produce pressure in all directions.","steps":["Step 1: Gas particles move randomly in many directions.","Step 2: They collide with different parts of the container walls.","Step 3: These collisions produce pressure in all directions."],"options":[],"conceptId":"physics_pressure_pressure_in_gases","skillId":"physics_pressure","subskillId":"physics_pressure_q4","subject":"physics","chapter":"pressure","topic":"Pressure in Gases"}', 3),
  (1874, 472, 'What happens to the pressure of a fixed amount of gas if its volume decreases while temperature remains constant?', 'text', 1, 'Use the inverse pressure-volume relationship.', '{"why":"A smaller volume leads to more frequent wall collisions under the stated conditions.","sol":"Step 1: Temperature and amount of gas remain constant.\nStep 2: Volume decreases.\nStep 3: Pressure increases.","steps":["Step 1: Temperature and amount of gas remain constant.","Step 2: Volume decreases.","Step 3: Pressure increases."],"options":[],"conceptId":"physics_pressure_pressure_in_gases","skillId":"physics_pressure","subskillId":"physics_pressure_q5","subject":"physics","chapter":"pressure","topic":"Pressure in Gases"}', 4),
  (1875, 472, 'What causes the pressure exerted by a gas on the walls of its container?', 'text', 1, 'Think about what moving particles do when they hit a wall.', '{"why":"The impacts of gas particles on the walls produce gas pressure.","sol":"Step 1: Gas particles move randomly.\nStep 2: They collide with the container walls.\nStep 3: Their collisions exert force on the walls.","steps":["Step 1: Gas particles move randomly.","Step 2: They collide with the container walls.","Step 3: Their collisions exert force on the walls."],"options":[],"conceptId":"physics_pressure_pressure_in_gases","skillId":"physics_pressure","subskillId":"physics_pressure_q6","subject":"physics","chapter":"pressure","topic":"Pressure in Gases"}', 5),
  (1876, 472, 'What generally happens to the pressure of a fixed amount of gas when it is heated in a sealed rigid container?', 'text', 1, 'The container volume stays constant while particle temperature rises.', '{"why":"At constant volume, increasing gas temperature increases pressure.","sol":"Step 1: Heating increases the particles'' average kinetic energy.\nStep 2: Particles move faster on average.\nStep 3: Collisions transfer momentum more strongly, increasing pressure.","steps":["Step 1: Heating increases the particles'' average kinetic energy.","Step 2: Particles move faster on average.","Step 3: Collisions transfer momentum more strongly, increasing pressure."],"options":[],"conceptId":"physics_pressure_pressure_in_gases","skillId":"physics_pressure","subskillId":"physics_pressure_q7","subject":"physics","chapter":"pressure","topic":"Pressure in Gases"}', 6),
  (1877, 472, 'What happens to gas pressure when a fixed amount of gas is compressed at constant temperature?', 'text', 1, 'The gas occupies a smaller volume.', '{"why":"Compressing a gas at constant temperature raises its pressure.","sol":"Step 1: The gas volume decreases.\nStep 2: Particles collide with the walls more frequently per unit area.\nStep 3: Pressure increases.","steps":["Step 1: The gas volume decreases.","Step 2: Particles collide with the walls more frequently per unit area.","Step 3: Pressure increases."],"options":[],"conceptId":"physics_pressure_pressure_in_gases","skillId":"physics_pressure","subskillId":"physics_pressure_q8","subject":"physics","chapter":"pressure","topic":"Pressure in Gases"}', 7),
  (1878, 472, 'Why does gas pressure act in all directions?', 'text', 1, 'Consider the random motion of gas particles.', '{"why":"Random particle motion produces pressure on every wall of the container.","sol":"Step 1: Particles move randomly in different directions.\nStep 2: They collide with walls of different orientations.\nStep 3: The collisions exert pressure in all directions.","steps":["Step 1: Particles move randomly in different directions.","Step 2: They collide with walls of different orientations.","Step 3: The collisions exert pressure in all directions."],"options":[],"conceptId":"physics_pressure_pressure_in_gases","skillId":"physics_pressure","subskillId":"physics_pressure_q9","subject":"physics","chapter":"pressure","topic":"Pressure in Gases"}', 8),
  (1879, 472, 'A sealed rigid container holds gas at constant volume. If the gas is cooled, what generally happens to its pressure?', 'text', 1, 'Cooling reduces the particles'' average kinetic energy.', '{"why":"At fixed volume, lower gas temperature generally means lower pressure.","sol":"Step 1: Cooling reduces average particle kinetic energy.\nStep 2: Particles move more slowly on average.\nStep 3: Pressure decreases.","steps":["Step 1: Cooling reduces average particle kinetic energy.","Step 2: Particles move more slowly on average.","Step 3: Pressure decreases."],"options":[],"conceptId":"physics_pressure_pressure_in_gases","skillId":"physics_pressure","subskillId":"physics_pressure_q10","subject":"physics","chapter":"pressure","topic":"Pressure in Gases"}', 9),
  (1880, 472, 'What causes a gas to exert pressure on the walls of its container?', 'text', 1, 'Think about moving gas particles.', '{"why":"The force produced by many particle collisions creates gas pressure.","sol":"Step 1: Gas particles move randomly.\nStep 2: They collide with the container walls.\nStep 3: The collisions exert forces on the walls.","steps":["Step 1: Gas particles move randomly.","Step 2: They collide with the container walls.","Step 3: The collisions exert forces on the walls."],"options":[],"conceptId":"physics_pressure_pressure_in_gases","skillId":"physics_pressure","subskillId":"physics_pressure_q11","subject":"physics","chapter":"pressure","topic":"Pressure in Gases"}', 10),
  (1881, 472, 'What generally happens to the pressure of a sealed gas when its volume decreases at approximately constant temperature?', 'text', 1, 'The same gas occupies a smaller space.', '{"why":"Compression of a fixed amount of gas at approximately constant temperature raises its pressure.","sol":"Step 1: The gas is compressed.\nStep 2: Particles collide with the walls more frequently per unit volume.\nStep 3: The pressure generally increases.","steps":["Step 1: The gas is compressed.","Step 2: Particles collide with the walls more frequently per unit volume.","Step 3: The pressure generally increases."],"options":[],"conceptId":"physics_pressure_pressure_in_gases","skillId":"physics_pressure","subskillId":"physics_pressure_q12","subject":"physics","chapter":"pressure","topic":"Pressure in Gases"}', 11),
  (1882, 472, 'Why does gas pressure act on all walls of a closed container?', 'text', 1, 'Consider the directions of particle motion.', '{"why":"Random motion means collisions occur against all surfaces.","sol":"Step 1: Gas particles move randomly in all directions.\nStep 2: They collide with all the container walls.\nStep 3: Pressure is exerted on each wall.","steps":["Step 1: Gas particles move randomly in all directions.","Step 2: They collide with all the container walls.","Step 3: Pressure is exerted on each wall."],"options":[],"conceptId":"physics_pressure_pressure_in_gases","skillId":"physics_pressure","subskillId":"physics_pressure_q13","subject":"physics","chapter":"pressure","topic":"Pressure in Gases"}', 12),
  (1883, 472, 'A learner says gas pressure is caused only by the weight of the gas. What is the more complete explanation?', 'text', 1, 'Think about the microscopic explanation.', '{"why":"The particle-collision model explains pressure in a confined gas.","sol":"Step 1: Gas particles move randomly.\nStep 2: Their collisions with surfaces exert forces.\nStep 3: The resulting force per unit area is gas pressure.","steps":["Step 1: Gas particles move randomly.","Step 2: Their collisions with surfaces exert forces.","Step 3: The resulting force per unit area is gas pressure."],"options":[],"conceptId":"physics_pressure_pressure_in_gases","skillId":"physics_pressure","subskillId":"physics_pressure_q14","subject":"physics","chapter":"pressure","topic":"Pressure in Gases"}', 13),
  (1884, 472, 'Air is compressed in a sealed syringe while its temperature remains approximately constant. Which two quantities change?', 'text', 1, 'Consider the plunger''s movement and the pressure response.', '{"why":"Compressing the gas at approximately constant temperature increases its pressure.","sol":"Step 1: Pushing the plunger inward reduces the gas volume.\nStep 2: The gas pressure increases.","steps":["Step 1: Pushing the plunger inward reduces the gas volume.","Step 2: The gas pressure increases."],"options":[],"conceptId":"physics_pressure_pressure_in_gases","skillId":"physics_pressure","subskillId":"physics_pressure_q15","subject":"physics","chapter":"pressure","topic":"Pressure in Gases"}', 14),
  (1885, 473, 'A gas has volume 400 cm³ at 100 kPa. What is its pressure when compressed to 200 cm³ at constant temperature?', 'text', 1, 'Use P₁V₁ = P₂V₂.', '{"why":"Boyle''s law describes the inverse relationship between pressure and volume.","sol":"Step 1: Write P₁V₁ = P₂V₂.\nStep 2: Substitute: 100 × 400 = P₂ × 200.\nStep 3: P₂ = 40,000/200 = 200 kPa.","steps":["Step 1: Write P₁V₁ = P₂V₂.","Step 2: Substitute: 100 × 400 = P₂ × 200.","Step 3: P₂ = 40,000/200 = 200 kPa."],"options":[],"conceptId":"physics_pressure_pressure_and_volume_of_a_gas","skillId":"physics_pressure","subskillId":"physics_pressure_q1","subject":"physics","chapter":"pressure","topic":"Pressure and Volume of a Gas"}', 0),
  (1886, 473, 'A gas at 120 kPa occupies 500 cm³. Find its volume at 200 kPa if temperature remains constant.', 'text', 1, 'Rearrange P₁V₁ = P₂V₂ to find V₂.', '{"why":"At constant temperature, increasing pressure decreases volume.","sol":"Step 1: Write V₂ = P₁V₁/P₂.\nStep 2: Substitute: V₂ = (120 × 500)/200.\nStep 3: Calculate V₂ = 300 cm³.","steps":["Step 1: Write V₂ = P₁V₁/P₂.","Step 2: Substitute: V₂ = (120 × 500)/200.","Step 3: Calculate V₂ = 300 cm³."],"options":[],"conceptId":"physics_pressure_pressure_and_volume_of_a_gas","skillId":"physics_pressure","subskillId":"physics_pressure_q2","subject":"physics","chapter":"pressure","topic":"Pressure and Volume of a Gas"}', 1),
  (1887, 473, 'A gas occupies 250 cm³ at 80 kPa. Its volume becomes 500 cm³ at constant temperature. Calculate the final pressure.', 'text', 1, 'The volume doubles, so consider the inverse pressure-volume relationship.', '{"why":"Pressure and volume are inversely proportional for a fixed amount of gas at constant temperature.","sol":"Step 1: Write P₂ = P₁V₁/V₂.\nStep 2: Substitute: P₂ = (80 × 250)/500.\nStep 3: Calculate P₂ = 40 kPa.","steps":["Step 1: Write P₂ = P₁V₁/V₂.","Step 2: Substitute: P₂ = (80 × 250)/500.","Step 3: Calculate P₂ = 40 kPa."],"options":[],"conceptId":"physics_pressure_pressure_and_volume_of_a_gas","skillId":"physics_pressure","subskillId":"physics_pressure_q3","subject":"physics","chapter":"pressure","topic":"Pressure and Volume of a Gas"}', 2),
  (1888, 473, 'Which two conditions must remain constant when applying Boyle''s law to a fixed sample of gas?', 'text', 1, 'Boyle''s law describes pressure-volume changes under specified conditions.', '{"why":"Boyle''s law relates pressure and volume at constant temperature for a fixed amount of gas.","sol":"Step 1: The sample''s temperature must remain constant.\nStep 2: The amount of gas must remain fixed.\nStep 3: Under these conditions, P₁V₁ = P₂V₂ applies.","steps":["Step 1: The sample''s temperature must remain constant.","Step 2: The amount of gas must remain fixed.","Step 3: Under these conditions, P₁V₁ = P₂V₂ applies."],"options":[],"conceptId":"physics_pressure_pressure_and_volume_of_a_gas","skillId":"physics_pressure","subskillId":"physics_pressure_q4","subject":"physics","chapter":"pressure","topic":"Pressure and Volume of a Gas"}', 3),
  (1889, 473, 'At constant temperature, the pressure of a fixed amount of gas increases from 50 kPa to 150 kPa. If its initial volume is 900 cm³, calculate its final volume.', 'text', 1, 'Use V₂ = P₁V₁/P₂.', '{"why":"Pressure rises by a factor of three, so volume falls by a factor of three.","sol":"Step 1: Write V₂ = P₁V₁/P₂.\nStep 2: Substitute V₂ = (50 × 900)/150.\nStep 3: Calculate V₂ = 300 cm³.","steps":["Step 1: Write V₂ = P₁V₁/P₂.","Step 2: Substitute V₂ = (50 × 900)/150.","Step 3: Calculate V₂ = 300 cm³."],"options":[],"conceptId":"physics_pressure_pressure_and_volume_of_a_gas","skillId":"physics_pressure","subskillId":"physics_pressure_q5","subject":"physics","chapter":"pressure","topic":"Pressure and Volume of a Gas"}', 4),
  (1890, 474, 'A force of 60 N acts normally on an area of 3 m². Calculate the pressure.', 'text', 1, 'Divide force by area.', '{"why":"Pressure equals 60 N divided by 3 m².","sol":"Step 1: P = 60/3.\nStep 2: P = 20 Pa.","steps":["Step 1: P = 60/3.","Step 2: P = 20 Pa."],"options":[],"conceptId":"physics_pressure_meaning_of_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q1","subject":"physics","chapter":"pressure","topic":"Meaning of Pressure"}', 0),
  (1891, 474, 'A force of 200 N acts on an area of 4 m². Find the pressure.', 'text', 1, 'Use P = F/A.', '{"why":"200 N ÷ 4 m² = 50 Pa.","sol":"Step 1: P = 200/4.\nStep 2: P = 50 Pa.","steps":["Step 1: P = 200/4.","Step 2: P = 50 Pa."],"options":[],"conceptId":"physics_pressure_meaning_of_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q2","subject":"physics","chapter":"pressure","topic":"Meaning of Pressure"}', 1),
  (1892, 474, 'A pressure of 80 Pa acts over an area of 2 m². Calculate the normal force.', 'text', 1, 'Rearrange P = F/A to make F the subject.', '{"why":"F = 80 Pa × 2 m² = 160 N.","sol":"Step 1: F = 80 × 2.\nStep 2: F = 160 N.","steps":["Step 1: F = 80 × 2.","Step 2: F = 160 N."],"options":[],"conceptId":"physics_pressure_meaning_of_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q3","subject":"physics","chapter":"pressure","topic":"Meaning of Pressure"}', 2),
  (1893, 474, 'A force of 150 N produces a pressure of 50 Pa. Find the area.', 'text', 1, 'Rearrange P = F/A.', '{"why":"A = 150 N ÷ 50 Pa = 3 m².","sol":"Step 1: A = 150/50.\nStep 2: A = 3 m².","steps":["Step 1: A = 150/50.","Step 2: A = 3 m²."],"options":[],"conceptId":"physics_pressure_meaning_of_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q4","subject":"physics","chapter":"pressure","topic":"Meaning of Pressure"}', 3),
  (1894, 474, 'The same force acts on two surfaces. Surface X has half the area of surface Y. How does the pressure on X compare with that on Y?', 'text', 1, 'Pressure is inversely proportional to area when force is constant.', '{"why":"Halving the area doubles pressure when force remains constant.","sol":"Step 1: Let the area of Y be A.\nStep 2: The area of X is A/2.\nStep 3: Pressure on X is F/(A/2) = 2F/A.","steps":["Step 1: Let the area of Y be A.","Step 2: The area of X is A/2.","Step 3: Pressure on X is F/(A/2) = 2F/A."],"options":[],"conceptId":"physics_pressure_meaning_of_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q5","subject":"physics","chapter":"pressure","topic":"Meaning of Pressure"}', 4),
  (1895, 475, 'What happens to liquid pressure when depth doubles, while density and g remain constant?', 'text', 1, 'Pressure is directly proportional to depth.', '{"why":"Pressure is directly proportional to depth.","sol":"Step 1: Density remains constant.\nStep 2: g remains constant.\nStep 3: Doubling h doubles p.","steps":["Step 1: Density remains constant.","Step 2: g remains constant.","Step 3: Doubling h doubles p."],"options":[],"conceptId":"physics_pressure_factors_affecting_liquid_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q1","subject":"physics","chapter":"pressure","topic":"Factors Affecting Liquid Pressure"}', 0),
  (1896, 475, 'Two liquids have densities 900 kg/m³ and 1,200 kg/m³. At equal depths, which exerts greater pressure?', 'text', 1, 'Compare their densities.', '{"why":"The denser liquid produces greater pressure at equal depth.","sol":"Step 1: Depth and g are equal.\nStep 2: Pressure is proportional to density.\nStep 3: 1,200 kg/m³ is greater than 900 kg/m³.","steps":["Step 1: Depth and g are equal.","Step 2: Pressure is proportional to density.","Step 3: 1,200 kg/m³ is greater than 900 kg/m³."],"options":[],"conceptId":"physics_pressure_factors_affecting_liquid_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q2","subject":"physics","chapter":"pressure","topic":"Factors Affecting Liquid Pressure"}', 1),
  (1897, 475, 'Does liquid pressure at a given depth in a stationary liquid depend on the shape of the container?', 'text', 1, 'Consider the variables in p = ρgh.', '{"why":"Pressure depends on the height and density of the liquid column, not the container''s shape.","sol":"Step 1: The formula includes density, gravitational field strength and depth.\nStep 2: Container shape is not in the formula.\nStep 3: At equal depth in the same liquid, the pressure is equal.","steps":["Step 1: The formula includes density, gravitational field strength and depth.","Step 2: Container shape is not in the formula.","Step 3: At equal depth in the same liquid, the pressure is equal."],"options":[],"conceptId":"physics_pressure_factors_affecting_liquid_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q3","subject":"physics","chapter":"pressure","topic":"Factors Affecting Liquid Pressure"}', 2),
  (1898, 475, 'A liquid''s density doubles while depth and gravitational field strength remain unchanged. What happens to the liquid pressure?', 'text', 1, 'Pressure is directly proportional to density.', '{"why":"Doubling density doubles liquid pressure at the same depth.","sol":"Step 1: Density becomes 2ρ.\nStep 2: New pressure = 2ρgh.\nStep 3: New pressure is twice the original.","steps":["Step 1: Density becomes 2ρ.","Step 2: New pressure = 2ρgh.","Step 3: New pressure is twice the original."],"options":[],"conceptId":"physics_pressure_factors_affecting_liquid_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q4","subject":"physics","chapter":"pressure","topic":"Factors Affecting Liquid Pressure"}', 3),
  (1899, 475, 'Why is pressure greater near the bottom of a deep pool than near its surface?', 'text', 1, 'Compare the amount of liquid above each point.', '{"why":"Greater depth means a taller column of liquid above the point.","sol":"Step 1: More liquid lies above the deeper point.\nStep 2: The liquid column exerts greater pressure at greater depth.\nStep 3: Therefore, pressure is greater near the bottom.","steps":["Step 1: More liquid lies above the deeper point.","Step 2: The liquid column exerts greater pressure at greater depth.","Step 3: Therefore, pressure is greater near the bottom."],"options":[],"conceptId":"physics_pressure_factors_affecting_liquid_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q5","subject":"physics","chapter":"pressure","topic":"Factors Affecting Liquid Pressure"}', 4),
  (1900, 476, 'The pressure on one side of a surface is 90,000 Pa and on the other side is 70,000 Pa. Find the pressure difference.', 'text', 1, 'Subtract the lower pressure from the higher pressure.', '{"why":"90,000 Pa − 70,000 Pa = 20,000 Pa.","sol":"Step 1: Δp = 90,000 − 70,000.\nStep 2: Δp = 20,000 Pa.","steps":["Step 1: Δp = 90,000 − 70,000.","Step 2: Δp = 20,000 Pa."],"options":[],"conceptId":"physics_pressure_pressure_differences","skillId":"physics_pressure","subskillId":"physics_pressure_q1","subject":"physics","chapter":"pressure","topic":"Pressure Differences"}', 0),
  (1901, 476, 'The pressure is 150,000 Pa inside a container and 100,000 Pa outside. What is the inside-to-outside pressure difference?', 'text', 1, 'Subtract outside pressure from inside pressure.', '{"why":"The pressure inside exceeds the outside pressure by 50,000 Pa.","sol":"Step 1: Δp = 150,000 − 100,000.\nStep 2: Δp = 50,000 Pa.","steps":["Step 1: Δp = 150,000 − 100,000.","Step 2: Δp = 50,000 Pa."],"options":[],"conceptId":"physics_pressure_pressure_differences","skillId":"physics_pressure","subskillId":"physics_pressure_q2","subject":"physics","chapter":"pressure","topic":"Pressure Differences"}', 1),
  (1902, 476, 'Pressure is equal on both sides of a flat surface. What is the net force due to these pressures across the surface?', 'text', 1, 'Equal pressures act in opposite directions across the surface.', '{"why":"Equal opposing pressure effects produce no net force across the surface.","sol":"Step 1: The pressures have equal magnitude.\nStep 2: Their effects across the surface balance.\nStep 3: The net force due to the pressure difference is zero.","steps":["Step 1: The pressures have equal magnitude.","Step 2: Their effects across the surface balance.","Step 3: The net force due to the pressure difference is zero."],"options":[],"conceptId":"physics_pressure_pressure_differences","skillId":"physics_pressure","subskillId":"physics_pressure_q3","subject":"physics","chapter":"pressure","topic":"Pressure Differences"}', 2),
  (1903, 476, 'Why does air flow through an opening from a high-pressure region to a low-pressure region?', 'text', 1, 'Consider the net effect of the pressure forces.', '{"why":"A pressure gradient can drive fluid motion.","sol":"Step 1: Pressure is greater on one side.\nStep 2: The pressure difference creates a net force on the air.\nStep 3: The air tends to move towards the lower-pressure region.","steps":["Step 1: Pressure is greater on one side.","Step 2: The pressure difference creates a net force on the air.","Step 3: The air tends to move towards the lower-pressure region."],"options":[],"conceptId":"physics_pressure_pressure_differences","skillId":"physics_pressure","subskillId":"physics_pressure_q4","subject":"physics","chapter":"pressure","topic":"Pressure Differences"}', 3),
  (1904, 476, 'A pressure difference of 25,000 Pa acts across an area of 0.02 m². Calculate the net force due to this pressure difference.', 'text', 1, 'Rearrange pressure = force ÷ area.', '{"why":"Net force = 25,000 Pa × 0.02 m² = 500 N.","sol":"Step 1: F = 25,000 × 0.02.\nStep 2: F = 500 N.","steps":["Step 1: F = 25,000 × 0.02.","Step 2: F = 500 N."],"options":[],"conceptId":"physics_pressure_pressure_differences","skillId":"physics_pressure","subskillId":"physics_pressure_q5","subject":"physics","chapter":"pressure","topic":"Pressure Differences"}', 4),
  (1905, 477, 'What is upthrust?', 'text', 1, 'It is the force a fluid exerts on an immersed object.', '{"why":"Upthrust is the buoyant force exerted by a fluid.","sol":"Step 1: Identify the force exerted by the surrounding fluid.\nStep 2: State its direction.","steps":["Step 1: Identify the force exerted by the surrounding fluid.","Step 2: State its direction."],"options":[],"conceptId":"physics_pressure_upthrust","skillId":"physics_pressure","subskillId":"physics_pressure_q1","subject":"physics","chapter":"pressure","topic":"Upthrust"}', 0),
  (1906, 477, 'State Archimedes'' principle.', 'text', 1, 'Relate the upthrust to the displaced fluid.', '{"why":"Upthrust depends on the weight of displaced fluid.","sol":"Step 1: Identify the upward force on the immersed object.\nStep 2: Compare it with the weight of the fluid displaced.","steps":["Step 1: Identify the upward force on the immersed object.","Step 2: Compare it with the weight of the fluid displaced."],"options":[],"conceptId":"physics_pressure_upthrust","skillId":"physics_pressure","subskillId":"physics_pressure_q2","subject":"physics","chapter":"pressure","topic":"Upthrust"}', 1),
  (1907, 477, 'An object displaces 2 kg of water. Take g = 10 N/kg. Calculate the upthrust.', 'text', 1, 'Find the weight of the displaced water.', '{"why":"The displaced water weighs 20 N, so the upthrust is 20 N.","sol":"Step 1: Upthrust = 2 × 10.\nStep 2: Upthrust = 20 N.","steps":["Step 1: Upthrust = 2 × 10.","Step 2: Upthrust = 20 N."],"options":[],"conceptId":"physics_pressure_upthrust","skillId":"physics_pressure","subskillId":"physics_pressure_q3","subject":"physics","chapter":"pressure","topic":"Upthrust"}', 2),
  (1908, 477, 'Why is the pressure force on the bottom of an immersed object often greater than the pressure force on its top?', 'text', 1, 'Compare the depths of the object''s top and bottom.', '{"why":"The pressure difference between the lower and upper surfaces produces upthrust.","sol":"Step 1: Liquid pressure increases with depth.\nStep 2: The bottom is deeper than the top.\nStep 3: The upward force on the bottom can exceed the downward force on the top.","steps":["Step 1: Liquid pressure increases with depth.","Step 2: The bottom is deeper than the top.","Step 3: The upward force on the bottom can exceed the downward force on the top."],"options":[],"conceptId":"physics_pressure_upthrust","skillId":"physics_pressure","subskillId":"physics_pressure_q4","subject":"physics","chapter":"pressure","topic":"Upthrust"}', 3),
  (1909, 477, 'An object displaces 0.5 kg of a liquid. Take g = 10 N/kg. What is the upthrust?', 'text', 1, 'Upthrust equals the weight of the displaced liquid.', '{"why":"The weight of 0.5 kg of displaced liquid is 5 N.","sol":"Step 1: U = 0.5 × 10.\nStep 2: U = 5 N.","steps":["Step 1: U = 0.5 × 10.","Step 2: U = 5 N."],"options":[],"conceptId":"physics_pressure_upthrust","skillId":"physics_pressure","subskillId":"physics_pressure_q5","subject":"physics","chapter":"pressure","topic":"Upthrust"}', 4),
  (1910, 478, 'An object weighs 30 N and experiences an upthrust of 20 N. What is the resultant vertical force?', 'text', 1, 'Subtract the upward force from the downward weight.', '{"why":"The downward weight exceeds the upward upthrust by 10 N.","sol":"Step 1: Weight = 30 N downward.\nStep 2: Upthrust = 20 N upward.\nStep 3: Resultant = 30 − 20 = 10 N downward.","steps":["Step 1: Weight = 30 N downward.","Step 2: Upthrust = 20 N upward.","Step 3: Resultant = 30 − 20 = 10 N downward."],"options":[],"conceptId":"physics_pressure_floating_and_sinking","skillId":"physics_pressure","subskillId":"physics_pressure_q1","subject":"physics","chapter":"pressure","topic":"Floating and Sinking"}', 0),
  (1911, 478, 'An object weighs 15 N and experiences an upthrust of 15 N. What is the resultant vertical force?', 'text', 1, 'The two forces are equal and opposite.', '{"why":"Equal opposing forces balance; the object may be at rest or move at constant velocity.","sol":"Step 1: Weight = 15 N downward.\nStep 2: Upthrust = 15 N upward.\nStep 3: Resultant vertical force = 0 N.","steps":["Step 1: Weight = 15 N downward.","Step 2: Upthrust = 15 N upward.","Step 3: Resultant vertical force = 0 N."],"options":[],"conceptId":"physics_pressure_floating_and_sinking","skillId":"physics_pressure","subskillId":"physics_pressure_q2","subject":"physics","chapter":"pressure","topic":"Floating and Sinking"}', 1),
  (1912, 478, 'A floating object is at rest on water. How does its upthrust compare with its weight?', 'text', 1, 'The vertical forces must balance.', '{"why":"A floating object at rest is in vertical equilibrium.","sol":"Step 1: The object is at rest.\nStep 2: Its vertical acceleration is zero.\nStep 3: Upthrust equals weight.","steps":["Step 1: The object is at rest.","Step 2: Its vertical acceleration is zero.","Step 3: Upthrust equals weight."],"options":[],"conceptId":"physics_pressure_floating_and_sinking","skillId":"physics_pressure","subskillId":"physics_pressure_q3","subject":"physics","chapter":"pressure","topic":"Floating and Sinking"}', 2),
  (1913, 478, 'An object has an average density of 700 kg/m³ and is placed in water of density 1,000 kg/m³. Can it float under suitable conditions?', 'text', 1, 'Compare the object''s average density with the fluid density.', '{"why":"An object with lower average density than the fluid can displace enough fluid to support its weight.","sol":"Step 1: Object density = 700 kg/m³.\nStep 2: Water density = 1,000 kg/m³.\nStep 3: The object''s average density is lower than water''s.","steps":["Step 1: Object density = 700 kg/m³.","Step 2: Water density = 1,000 kg/m³.","Step 3: The object''s average density is lower than water''s."],"options":[],"conceptId":"physics_pressure_floating_and_sinking","skillId":"physics_pressure","subskillId":"physics_pressure_q4","subject":"physics","chapter":"pressure","topic":"Floating and Sinking"}', 3),
  (1914, 478, 'An object has a weight of 50 N and an upthrust of 65 N while immersed. What is the resultant force and its direction?', 'text', 1, 'Compare the upward upthrust with the downward weight.', '{"why":"The upthrust exceeds the weight by 15 N.","sol":"Step 1: Upthrust = 65 N upward.\nStep 2: Weight = 50 N downward.\nStep 3: Resultant = 65 − 50 = 15 N upward.","steps":["Step 1: Upthrust = 65 N upward.","Step 2: Weight = 50 N downward.","Step 3: Resultant = 65 − 50 = 15 N upward."],"options":[],"conceptId":"physics_pressure_floating_and_sinking","skillId":"physics_pressure","subskillId":"physics_pressure_q5","subject":"physics","chapter":"pressure","topic":"Floating and Sinking"}', 4),
  (1915, 479, 'Why can a large steel ship float even though steel is denser than water?', 'text', 1, 'Consider the average density of the entire ship, including the air inside its hull.', '{"why":"A ship floats because the upthrust from displaced water can balance its total weight.","sol":"Step 1: The ship has a hollow hull containing air.\nStep 2: Its overall average density can be less than that of water.\nStep 3: It displaces enough water for upthrust to balance its weight.","steps":["Step 1: The ship has a hollow hull containing air.","Step 2: Its overall average density can be less than that of water.","Step 3: It displaces enough water for upthrust to balance its weight."],"options":[],"conceptId":"physics_pressure_applications_of_upthrust","skillId":"physics_pressure","subskillId":"physics_pressure_q1","subject":"physics","chapter":"pressure","topic":"Applications of Upthrust"}', 0),
  (1916, 479, 'A hydrometer is placed in two liquids. In which liquid will it generally float higher: the denser liquid or the less dense liquid?', 'text', 1, 'A denser liquid provides the required upthrust with less displaced volume.', '{"why":"The hydrometer displaces less volume in a denser liquid to balance its weight.","sol":"Step 1: The hydrometer''s weight stays constant.\nStep 2: A denser liquid provides greater upthrust per unit displaced volume.\nStep 3: Less volume needs to be displaced, so the hydrometer floats higher.","steps":["Step 1: The hydrometer''s weight stays constant.","Step 2: A denser liquid provides greater upthrust per unit displaced volume.","Step 3: Less volume needs to be displaced, so the hydrometer floats higher."],"options":[],"conceptId":"physics_pressure_applications_of_upthrust","skillId":"physics_pressure","subskillId":"physics_pressure_q2","subject":"physics","chapter":"pressure","topic":"Applications of Upthrust"}', 1),
  (1917, 479, 'What condition must be met for a balloon to rise in air?', 'text', 1, 'Compare the upward buoyant force with the total downward weight.', '{"why":"The net upward force determines whether the balloon accelerates upward.","sol":"Step 1: Air exerts an upward buoyant force.\nStep 2: The balloon and contents have a total weight.\nStep 3: For upward acceleration, upthrust must exceed total weight.","steps":["Step 1: Air exerts an upward buoyant force.","Step 2: The balloon and contents have a total weight.","Step 3: For upward acceleration, upthrust must exceed total weight."],"options":[],"conceptId":"physics_pressure_applications_of_upthrust","skillId":"physics_pressure","subskillId":"physics_pressure_q3","subject":"physics","chapter":"pressure","topic":"Applications of Upthrust"}', 2),
  (1918, 479, 'A floating boat displaces water weighing 4,000 N. What is the boat''s weight if it is floating at rest?', 'text', 1, 'Use Archimedes'' principle and the balance of forces.', '{"why":"A floating boat at rest has weight equal to the upthrust.","sol":"Step 1: Upthrust equals the weight of displaced water = 4,000 N.\nStep 2: At rest, the boat''s weight equals the upthrust.\nStep 3: Boat weight = 4,000 N.","steps":["Step 1: Upthrust equals the weight of displaced water = 4,000 N.","Step 2: At rest, the boat''s weight equals the upthrust.","Step 3: Boat weight = 4,000 N."],"options":[],"conceptId":"physics_pressure_applications_of_upthrust","skillId":"physics_pressure","subskillId":"physics_pressure_q4","subject":"physics","chapter":"pressure","topic":"Applications of Upthrust"}', 3),
  (1919, 479, 'Why does a hydrometer generally sink deeper in a less dense liquid?', 'text', 1, 'The less dense liquid provides less upthrust per unit volume displaced.', '{"why":"The greater displaced volume compensates for the lower density of the liquid.","sol":"Step 1: The hydrometer''s weight is unchanged.\nStep 2: A less dense liquid provides less upthrust for the same displaced volume.\nStep 3: More liquid volume must be displaced, so the hydrometer sinks deeper.","steps":["Step 1: The hydrometer''s weight is unchanged.","Step 2: A less dense liquid provides less upthrust for the same displaced volume.","Step 3: More liquid volume must be displaced, so the hydrometer sinks deeper."],"options":[],"conceptId":"physics_pressure_applications_of_upthrust","skillId":"physics_pressure","subskillId":"physics_pressure_q5","subject":"physics","chapter":"pressure","topic":"Applications of Upthrust"}', 4),
  (1920, 480, 'What is pressure?', 'text', 1, 'Think of force acting over a surface.', '{"why":"Pressure describes how concentrated a force is over a surface.","sol":"Step 1: Pressure is the normal force per unit area.\nStep 2: Write P = F/A.","steps":["Step 1: Pressure is the normal force per unit area.","Step 2: Write P = F/A."],"options":[],"conceptId":"physics_pressure_pressure_and_force","skillId":"physics_pressure","subskillId":"physics_pressure_q1","subject":"physics","chapter":"pressure","topic":"Pressure and Force"}', 0),
  (1921, 480, 'A force of 40 N acts normally on an area of 2 m². Calculate the pressure.', 'text', 1, 'Divide force by area.', '{"why":"Pressure is force divided by the area over which the force acts.","sol":"Step 1: P = F/A\nStep 2: P = 40/2\nStep 3: P = 20 Pa","steps":["Step 1: P = F/A","Step 2: P = 40/2","Step 3: P = 20 Pa"],"options":[],"conceptId":"physics_pressure_pressure_and_force","skillId":"physics_pressure","subskillId":"physics_pressure_q2","subject":"physics","chapter":"pressure","topic":"Pressure and Force"}', 1),
  (1922, 480, 'What is the SI unit of pressure?', 'text', 1, 'It is equivalent to one newton per square metre.', '{"why":"One pascal equals one newton per square metre.","sol":"Step 1: P = F/A\nStep 2: The SI unit is N/m², called the pascal.","steps":["Step 1: P = F/A","Step 2: The SI unit is N/m², called the pascal."],"options":[],"conceptId":"physics_pressure_pressure_and_force","skillId":"physics_pressure","subskillId":"physics_pressure_q3","subject":"physics","chapter":"pressure","topic":"Pressure and Force"}', 2),
  (1923, 480, 'A student says pressure is measured in newtons. What is the error?', 'text', 1, 'Newtons measure force, not force per unit area.', '{"why":"The newton measures force; the pascal measures pressure.","sol":"Step 1: Force is measured in newtons.\nStep 2: Pressure is force divided by area.\nStep 3: Pressure is measured in pascals.","steps":["Step 1: Force is measured in newtons.","Step 2: Pressure is force divided by area.","Step 3: Pressure is measured in pascals."],"options":[],"conceptId":"physics_pressure_pressure_and_force","skillId":"physics_pressure","subskillId":"physics_pressure_q4","subject":"physics","chapter":"pressure","topic":"Pressure and Force"}', 3),
  (1924, 480, 'A force of 100 N acts normally on an area of 5 m². Calculate the pressure.', 'text', 1, 'Use P = F/A.', '{"why":"Dividing the force by the area gives the pressure.","sol":"Step 1: P = 100/5\nStep 2: P = 20 Pa","steps":["Step 1: P = 100/5","Step 2: P = 20 Pa"],"options":[],"conceptId":"physics_pressure_pressure_and_force","skillId":"physics_pressure","subskillId":"physics_pressure_q5","subject":"physics","chapter":"pressure","topic":"Pressure and Force"}', 4),
  (1925, 481, 'A force of 80 N acts on an area of 4 m². Find the pressure.', 'text', 1, 'Divide the force by the area.', '{"why":"Pressure equals force divided by contact area.","sol":"Step 1: P = F/A\nStep 2: P = 80/4\nStep 3: P = 20 Pa","steps":["Step 1: P = F/A","Step 2: P = 80/4","Step 3: P = 20 Pa"],"options":[],"conceptId":"physics_pressure_calculating_pressure_in_solids","skillId":"physics_pressure","subskillId":"physics_pressure_q1","subject":"physics","chapter":"pressure","topic":"Calculating Pressure in Solids"}', 0),
  (1926, 481, 'The same force acts on two surfaces. Which has greater pressure?', 'text', 1, 'Compare their contact areas.', '{"why":"The same force is concentrated over a smaller area.","sol":"Step 1: Use P = F/A.\nStep 2: When F stays constant, decreasing A increases P.","steps":["Step 1: Use P = F/A.","Step 2: When F stays constant, decreasing A increases P."],"options":[],"conceptId":"physics_pressure_calculating_pressure_in_solids","skillId":"physics_pressure","subskillId":"physics_pressure_q2","subject":"physics","chapter":"pressure","topic":"Calculating Pressure in Solids"}', 1),
  (1927, 481, 'Convert 30 cm² to m².', 'text', 1, '1 m² = 10,000 cm².', '{"why":"Area conversion requires dividing square centimetres by 10,000.","sol":"Step 1: 30 cm² ÷ 10,000\nStep 2: = 0.003 m²","steps":["Step 1: 30 cm² ÷ 10,000","Step 2: = 0.003 m²"],"options":[],"conceptId":"physics_pressure_calculating_pressure_in_solids","skillId":"physics_pressure","subskillId":"physics_pressure_q3","subject":"physics","chapter":"pressure","topic":"Calculating Pressure in Solids"}', 2),
  (1928, 481, 'A force of 200 N acts on 0.05 m². Calculate the pressure.', 'text', 1, 'Use P = F/A.', '{"why":"Dividing by 0.05 is equivalent to multiplying by 20.","sol":"Step 1: P = 200/0.05\nStep 2: P = 4,000 Pa","steps":["Step 1: P = 200/0.05","Step 2: P = 4,000 Pa"],"options":[],"conceptId":"physics_pressure_calculating_pressure_in_solids","skillId":"physics_pressure","subskillId":"physics_pressure_q4","subject":"physics","chapter":"pressure","topic":"Calculating Pressure in Solids"}', 3),
  (1929, 481, 'Why does a sharp knife cut more easily than a blunt knife when the applied force is the same?', 'text', 1, 'Think about the contact area at the edge.', '{"why":"Greater pressure helps the edge penetrate the material.","sol":"Step 1: A sharp edge has a smaller contact area.\nStep 2: The same force acts over that smaller area.\nStep 3: The pressure is therefore greater.","steps":["Step 1: A sharp edge has a smaller contact area.","Step 2: The same force acts over that smaller area.","Step 3: The pressure is therefore greater."],"options":[],"conceptId":"physics_pressure_calculating_pressure_in_solids","skillId":"physics_pressure","subskillId":"physics_pressure_q5","subject":"physics","chapter":"pressure","topic":"Calculating Pressure in Solids"}', 4),
  (1930, 482, 'Name the three factors determining pressure due to a stationary liquid.', 'text', 1, 'Look at the symbols in P = ρgh.', '{"why":"All three quantities appear in P = ρgh.","sol":"Step 1: ρ represents liquid density.\nStep 2: g represents gravitational field strength.\nStep 3: h represents depth.","steps":["Step 1: ρ represents liquid density.","Step 2: g represents gravitational field strength.","Step 3: h represents depth."],"options":[],"conceptId":"physics_pressure_factors_affecting_pressure_in_liquids","skillId":"physics_pressure","subskillId":"physics_pressure_q1","subject":"physics","chapter":"pressure","topic":"Factors Affecting Pressure in Liquids"}', 0),
  (1931, 482, 'What happens to liquid pressure if depth doubles while everything else stays constant?', 'text', 1, 'Pressure is directly proportional to depth.', '{"why":"Pressure is directly proportional to depth.","sol":"Step 1: P = ρgh.\nStep 2: If h doubles, ρgh doubles.","steps":["Step 1: P = ρgh.","Step 2: If h doubles, ρgh doubles."],"options":[],"conceptId":"physics_pressure_factors_affecting_pressure_in_liquids","skillId":"physics_pressure","subskillId":"physics_pressure_q2","subject":"physics","chapter":"pressure","topic":"Factors Affecting Pressure in Liquids"}', 1),
  (1932, 482, 'Two liquids have different densities but the same depth and gravitational field strength. Which produces greater pressure?', 'text', 1, 'Compare their densities.', '{"why":"Pressure is directly proportional to liquid density.","sol":"Step 1: P = ρgh.\nStep 2: With g and h equal, the denser liquid produces greater pressure.","steps":["Step 1: P = ρgh.","Step 2: With g and h equal, the denser liquid produces greater pressure."],"options":[],"conceptId":"physics_pressure_factors_affecting_pressure_in_liquids","skillId":"physics_pressure","subskillId":"physics_pressure_q3","subject":"physics","chapter":"pressure","topic":"Factors Affecting Pressure in Liquids"}', 2),
  (1933, 482, 'If gravitational field strength were halved, what would happen to liquid pressure at the same depth and density?', 'text', 1, 'Treat g as the changing factor in P = ρgh.', '{"why":"Pressure is directly proportional to gravitational field strength.","sol":"Step 1: P = ρgh.\nStep 2: Halving g halves P when ρ and h stay constant.","steps":["Step 1: P = ρgh.","Step 2: Halving g halves P when ρ and h stay constant."],"options":[],"conceptId":"physics_pressure_factors_affecting_pressure_in_liquids","skillId":"physics_pressure","subskillId":"physics_pressure_q4","subject":"physics","chapter":"pressure","topic":"Factors Affecting Pressure in Liquids"}', 3),
  (1934, 482, 'A learner claims that the volume of water alone determines the pressure at the bottom of a tank. Is this correct?', 'text', 1, 'Use the liquid-pressure equation.', '{"why":"Different container shapes can hold different volumes at the same liquid depth.","sol":"Step 1: P = ρgh.\nStep 2: The equation contains density, gravity and depth.\nStep 3: Volume alone does not determine the pressure.","steps":["Step 1: P = ρgh.","Step 2: The equation contains density, gravity and depth.","Step 3: Volume alone does not determine the pressure."],"options":[],"conceptId":"physics_pressure_factors_affecting_pressure_in_liquids","skillId":"physics_pressure","subskillId":"physics_pressure_q5","subject":"physics","chapter":"pressure","topic":"Factors Affecting Pressure in Liquids"}', 4),
  (1935, 483, 'Calculate the pressure 3 m below water. Use ρ = 1,000 kg/m³ and g = 10 N/kg.', 'text', 1, 'Substitute all three values into P = ρgh.', '{"why":"The product of density, gravitational field strength and depth gives pressure.","sol":"Step 1: P = ρgh\nStep 2: P = 1,000 × 10 × 3\nStep 3: P = 30,000 Pa","steps":["Step 1: P = ρgh","Step 2: P = 1,000 × 10 × 3","Step 3: P = 30,000 Pa"],"options":[],"conceptId":"physics_pressure_calculating_pressure_in_liquids","skillId":"physics_pressure","subskillId":"physics_pressure_q1","subject":"physics","chapter":"pressure","topic":"Calculating Pressure in Liquids"}', 0),
  (1936, 483, 'A liquid has density 800 kg/m³. Find the pressure at a depth of 5 m if g = 10 N/kg.', 'text', 1, 'Use the density given, not water''s density.', '{"why":"The calculation uses the actual density of the liquid.","sol":"Step 1: P = ρgh\nStep 2: P = 800 × 10 × 5\nStep 3: P = 40,000 Pa","steps":["Step 1: P = ρgh","Step 2: P = 800 × 10 × 5","Step 3: P = 40,000 Pa"],"options":[],"conceptId":"physics_pressure_calculating_pressure_in_liquids","skillId":"physics_pressure","subskillId":"physics_pressure_q2","subject":"physics","chapter":"pressure","topic":"Calculating Pressure in Liquids"}', 1),
  (1937, 483, 'Convert 60 cm to metres before using the liquid-pressure equation.', 'text', 1, 'Divide centimetres by 100.', '{"why":"The depth must be in metres when using SI units.","sol":"Step 1: 60 ÷ 100 = 0.60 m","steps":["Step 1: 60 ÷ 100 = 0.60 m"],"options":[],"conceptId":"physics_pressure_calculating_pressure_in_liquids","skillId":"physics_pressure","subskillId":"physics_pressure_q3","subject":"physics","chapter":"pressure","topic":"Calculating Pressure in Liquids"}', 2),
  (1938, 483, 'Water has density 1,000 kg/m³. Calculate the pressure at 0.5 m depth using g = 10 N/kg.', 'text', 1, 'Be careful with the decimal depth.', '{"why":"Half a metre produces half the pressure of one metre under the same conditions.","sol":"Step 1: P = 1,000 × 10 × 0.5\nStep 2: P = 5,000 Pa","steps":["Step 1: P = 1,000 × 10 × 0.5","Step 2: P = 5,000 Pa"],"options":[],"conceptId":"physics_pressure_calculating_pressure_in_liquids","skillId":"physics_pressure","subskillId":"physics_pressure_q4","subject":"physics","chapter":"pressure","topic":"Calculating Pressure in Liquids"}', 3),
  (1939, 483, 'A learner calculates liquid pressure using P = ρg/h. What is wrong?', 'text', 1, 'Recall the relationship between pressure and depth.', '{"why":"Liquid pressure increases with depth, so dividing by depth would predict the wrong relationship.","sol":"Step 1: The correct equation is P = ρgh.\nStep 2: Depth multiplies density and gravity; it does not divide them.","steps":["Step 1: The correct equation is P = ρgh.","Step 2: Depth multiplies density and gravity; it does not divide them."],"options":[],"conceptId":"physics_pressure_calculating_pressure_in_liquids","skillId":"physics_pressure","subskillId":"physics_pressure_q5","subject":"physics","chapter":"pressure","topic":"Calculating Pressure in Liquids"}', 4),
  (1940, 484, 'State the principle of pressure transmission in an enclosed fluid.', 'text', 1, 'What happens to an applied pressure change?', '{"why":"This is the principle used in hydraulic devices.","sol":"Step 1: Pressure is applied to the enclosed fluid.\nStep 2: The pressure change is transmitted throughout the fluid.","steps":["Step 1: Pressure is applied to the enclosed fluid.","Step 2: The pressure change is transmitted throughout the fluid."],"options":[],"conceptId":"physics_pressure_transmission_of_pressure_in_fluids","skillId":"physics_pressure","subskillId":"physics_pressure_q1","subject":"physics","chapter":"pressure","topic":"Transmission of Pressure in Fluids"}', 0),
  (1941, 484, 'Why are liquids useful in hydraulic systems?', 'text', 1, 'Consider how much their volume changes under pressure.', '{"why":"This helps the pressure applied at one piston act through the enclosed liquid.","sol":"Step 1: Liquids are difficult to compress.\nStep 2: They can transmit an applied pressure change through the system.","steps":["Step 1: Liquids are difficult to compress.","Step 2: They can transmit an applied pressure change through the system."],"options":[],"conceptId":"physics_pressure_transmission_of_pressure_in_fluids","skillId":"physics_pressure","subskillId":"physics_pressure_q2","subject":"physics","chapter":"pressure","topic":"Transmission of Pressure in Fluids"}', 1),
  (1942, 484, 'A sealed liquid system has an applied pressure change of 500 Pa. What pressure change is transmitted through the fluid under ideal conditions?', 'text', 1, 'Pressure change is transmitted, not multiplied just because it travels.', '{"why":"The pressure change is transmitted throughout the fluid.","sol":"Step 1: The applied pressure change is 500 Pa.\nStep 2: The same pressure change is transmitted through the enclosed fluid.","steps":["Step 1: The applied pressure change is 500 Pa.","Step 2: The same pressure change is transmitted through the enclosed fluid."],"options":[],"conceptId":"physics_pressure_transmission_of_pressure_in_fluids","skillId":"physics_pressure","subskillId":"physics_pressure_q3","subject":"physics","chapter":"pressure","topic":"Transmission of Pressure in Fluids"}', 2),
  (1943, 484, 'Does Pascal''s law mean pressure in a stationary liquid is always the same at every depth?', 'text', 1, 'Think about the effect of gravity.', '{"why":"Pressure transmission does not remove the depth-dependent pressure caused by gravity.","sol":"Step 1: An applied pressure change is transmitted through the fluid.\nStep 2: Hydrostatic pressure still increases with depth.","steps":["Step 1: An applied pressure change is transmitted through the fluid.","Step 2: Hydrostatic pressure still increases with depth."],"options":[],"conceptId":"physics_pressure_transmission_of_pressure_in_fluids","skillId":"physics_pressure","subskillId":"physics_pressure_q4","subject":"physics","chapter":"pressure","topic":"Transmission of Pressure in Fluids"}', 3),
  (1944, 484, 'A force is applied to a piston connected to an enclosed liquid. Why can another piston respond?', 'text', 1, 'What travels through the enclosed fluid?', '{"why":"This is the basis of hydraulic operation.","sol":"Step 1: The first piston creates a pressure change.\nStep 2: The change is transmitted through the liquid.\nStep 3: The fluid exerts pressure on the second piston.","steps":["Step 1: The first piston creates a pressure change.","Step 2: The change is transmitted through the liquid.","Step 3: The fluid exerts pressure on the second piston."],"options":[],"conceptId":"physics_pressure_transmission_of_pressure_in_fluids","skillId":"physics_pressure","subskillId":"physics_pressure_q5","subject":"physics","chapter":"pressure","topic":"Transmission of Pressure in Fluids"}', 4),
  (1945, 485, 'A hydraulic system has piston areas of 0.02 m² and 0.10 m². If the input force is 40 N, calculate the ideal output force.', 'text', 1, 'Use F₂ = F₁ × A₂/A₁.', '{"why":"The output piston has five times the area, so the ideal output force is five times greater.","sol":"Step 1: F₂ = 40 × (0.10/0.02)\nStep 2: F₂ = 40 × 5\nStep 3: F₂ = 200 N","steps":["Step 1: F₂ = 40 × (0.10/0.02)","Step 2: F₂ = 40 × 5","Step 3: F₂ = 200 N"],"options":[],"conceptId":"physics_pressure_hydraulic_machines","skillId":"physics_pressure","subskillId":"physics_pressure_q1","subject":"physics","chapter":"pressure","topic":"Hydraulic Machines"}', 0),
  (1946, 485, 'Why can a hydraulic lift raise a heavy vehicle with a smaller input force?', 'text', 1, 'Compare the piston areas.', '{"why":"Force equals pressure multiplied by area.","sol":"Step 1: The pressure change is transmitted through the liquid.\nStep 2: The output piston has a larger area.\nStep 3: The same pressure acting on a larger area produces a larger force.","steps":["Step 1: The pressure change is transmitted through the liquid.","Step 2: The output piston has a larger area.","Step 3: The same pressure acting on a larger area produces a larger force."],"options":[],"conceptId":"physics_pressure_hydraulic_machines","skillId":"physics_pressure","subskillId":"physics_pressure_q2","subject":"physics","chapter":"pressure","topic":"Hydraulic Machines"}', 1),
  (1947, 485, 'An input force of 20 N acts on a piston of area 0.005 m². Calculate the pressure produced.', 'text', 1, 'Use P = F/A.', '{"why":"The input force divided by the piston area gives the pressure.","sol":"Step 1: P = 20/0.005\nStep 2: P = 4,000 Pa","steps":["Step 1: P = 20/0.005","Step 2: P = 4,000 Pa"],"options":[],"conceptId":"physics_pressure_hydraulic_machines","skillId":"physics_pressure","subskillId":"physics_pressure_q3","subject":"physics","chapter":"pressure","topic":"Hydraulic Machines"}', 2),
  (1948, 485, 'If the input and output piston areas are equal, what is the ideal output force for an input force of 75 N?', 'text', 1, 'Equal areas mean equal force at equal pressure.', '{"why":"With equal piston areas, the ideal forces are equal.","sol":"Step 1: F₂/A₂ = F₁/A₁.\nStep 2: If A₂ = A₁, then F₂ = F₁.\nStep 3: F₂ = 75 N.","steps":["Step 1: F₂/A₂ = F₁/A₁.","Step 2: If A₂ = A₁, then F₂ = F₁.","Step 3: F₂ = 75 N."],"options":[],"conceptId":"physics_pressure_hydraulic_machines","skillId":"physics_pressure","subskillId":"physics_pressure_q4","subject":"physics","chapter":"pressure","topic":"Hydraulic Machines"}', 3),
  (1949, 485, 'Does a hydraulic lift create energy when it multiplies force?', 'text', 1, 'Consider the distance moved by each piston.', '{"why":"The force advantage is balanced by a distance disadvantage in an ideal machine.","sol":"Step 1: The output force can be larger.\nStep 2: The output piston moves a shorter distance in an ideal system.\nStep 3: The system does not create energy.","steps":["Step 1: The output force can be larger.","Step 2: The output piston moves a shorter distance in an ideal system.","Step 3: The system does not create energy."],"options":[],"conceptId":"physics_pressure_hydraulic_machines","skillId":"physics_pressure","subskillId":"physics_pressure_q5","subject":"physics","chapter":"pressure","topic":"Hydraulic Machines"}', 4),
  (1950, 486, 'What does a barometer measure?', 'text', 1, 'It measures pressure from the surrounding air.', '{"why":"Barometers are designed to measure the pressure exerted by the atmosphere.","sol":"Step 1: The atmosphere exerts pressure.\nStep 2: A barometer measures that atmospheric pressure.","steps":["Step 1: The atmosphere exerts pressure.","Step 2: A barometer measures that atmospheric pressure."],"options":[],"conceptId":"physics_pressure_measuring_atmospheric_pressure_with_a_barometer","skillId":"physics_pressure","subskillId":"physics_pressure_q1","subject":"physics","chapter":"pressure","topic":"Measuring Atmospheric Pressure with a Barometer"}', 0),
  (1951, 486, 'Convert a mercury column height of 760 mm into metres.', 'text', 1, '1,000 mm = 1 m.', '{"why":"The height must be in metres when using SI units.","sol":"Step 1: 760 ÷ 1,000 = 0.760 m","steps":["Step 1: 760 ÷ 1,000 = 0.760 m"],"options":[],"conceptId":"physics_pressure_measuring_atmospheric_pressure_with_a_barometer","skillId":"physics_pressure","subskillId":"physics_pressure_q2","subject":"physics","chapter":"pressure","topic":"Measuring Atmospheric Pressure with a Barometer"}', 1),
  (1952, 486, 'Calculate the pressure represented by a 0.5 m column of a liquid with density 1,200 kg/m³. Take g = 10 N/kg.', 'text', 1, 'Use P = ρgh.', '{"why":"The pressure represented by a liquid column is its density multiplied by gravity and height.","sol":"Step 1: P = 1,200 × 10 × 0.5\nStep 2: P = 6,000 Pa","steps":["Step 1: P = 1,200 × 10 × 0.5","Step 2: P = 6,000 Pa"],"options":[],"conceptId":"physics_pressure_measuring_atmospheric_pressure_with_a_barometer","skillId":"physics_pressure","subskillId":"physics_pressure_q3","subject":"physics","chapter":"pressure","topic":"Measuring Atmospheric Pressure with a Barometer"}', 2),
  (1953, 486, 'What happens to the height of a mercury barometer column when atmospheric pressure increases?', 'text', 1, 'Atmospheric pressure supports the column.', '{"why":"A greater pressure can support a taller column of mercury.","sol":"Step 1: Greater atmospheric pressure acts on the reservoir.\nStep 2: It can support a taller mercury column.","steps":["Step 1: Greater atmospheric pressure acts on the reservoir.","Step 2: It can support a taller mercury column."],"options":[],"conceptId":"physics_pressure_measuring_atmospheric_pressure_with_a_barometer","skillId":"physics_pressure","subskillId":"physics_pressure_q4","subject":"physics","chapter":"pressure","topic":"Measuring Atmospheric Pressure with a Barometer"}', 3),
  (1954, 486, 'Why must 760 mm be converted to 0.760 m before substituting into P = ρgh?', 'text', 1, 'Check the SI unit for height.', '{"why":"Using inconsistent units leads to an incorrect numerical result.","sol":"Step 1: The equation uses SI units.\nStep 2: Height should be in metres.\nStep 3: 760 mm equals 0.760 m.","steps":["Step 1: The equation uses SI units.","Step 2: Height should be in metres.","Step 3: 760 mm equals 0.760 m."],"options":[],"conceptId":"physics_pressure_measuring_atmospheric_pressure_with_a_barometer","skillId":"physics_pressure","subskillId":"physics_pressure_q5","subject":"physics","chapter":"pressure","topic":"Measuring Atmospheric Pressure with a Barometer"}', 4),
  (1955, 487, 'What is the purpose of a pressure gauge?', 'text', 1, 'Think about what quantity it indicates.', '{"why":"Pressure gauges are used to monitor gas or liquid pressure.","sol":"Step 1: A gauge responds to pressure in a system.\nStep 2: It indicates the pressure on its scale.","steps":["Step 1: A gauge responds to pressure in a system.","Step 2: It indicates the pressure on its scale."],"options":[],"conceptId":"physics_pressure_pressure_gauges_and_siphons","skillId":"physics_pressure","subskillId":"physics_pressure_q1","subject":"physics","chapter":"pressure","topic":"Pressure Gauges and Siphons"}', 0),
  (1956, 487, 'How does a Bourdon gauge indicate pressure?', 'text', 1, 'Consider what happens to its curved tube.', '{"why":"The tube''s small movement is converted into a readable indication.","sol":"Step 1: Pressure changes the shape of the curved metal tube.\nStep 2: A mechanism transfers this movement to a pointer.\nStep 3: The pointer indicates pressure on a scale.","steps":["Step 1: Pressure changes the shape of the curved metal tube.","Step 2: A mechanism transfers this movement to a pointer.","Step 3: The pointer indicates pressure on a scale."],"options":[],"conceptId":"physics_pressure_pressure_gauges_and_siphons","skillId":"physics_pressure","subskillId":"physics_pressure_q2","subject":"physics","chapter":"pressure","topic":"Pressure Gauges and Siphons"}', 1),
  (1957, 487, 'What is a siphon used for?', 'text', 1, 'It transfers liquid between different levels.', '{"why":"A siphon uses a continuous liquid column and a suitable height difference to maintain flow.","sol":"Step 1: The tube is filled or primed with liquid.\nStep 2: The outlet is placed below the liquid surface in the source.\nStep 3: The arrangement allows liquid to flow to the lower level.","steps":["Step 1: The tube is filled or primed with liquid.","Step 2: The outlet is placed below the liquid surface in the source.","Step 3: The arrangement allows liquid to flow to the lower level."],"options":[],"conceptId":"physics_pressure_pressure_gauges_and_siphons","skillId":"physics_pressure","subskillId":"physics_pressure_q3","subject":"physics","chapter":"pressure","topic":"Pressure Gauges and Siphons"}', 2),
  (1958, 487, 'A student says a pressure gauge and a siphon do the same job. Identify the error.', 'text', 1, 'One measures; the other transfers.', '{"why":"The two devices have different functions.","sol":"Step 1: A pressure gauge measures pressure.\nStep 2: A siphon transfers liquid.","steps":["Step 1: A pressure gauge measures pressure.","Step 2: A siphon transfers liquid."],"options":[],"conceptId":"physics_pressure_pressure_gauges_and_siphons","skillId":"physics_pressure","subskillId":"physics_pressure_q4","subject":"physics","chapter":"pressure","topic":"Pressure Gauges and Siphons"}', 3),
  (1959, 487, 'Why must a conventional siphon tube be primed before it can operate properly?', 'text', 1, 'Think about whether the tube contains a continuous liquid column.', '{"why":"Air gaps can interrupt the ordinary siphon action.","sol":"Step 1: Priming fills the tube with liquid.\nStep 2: This establishes the continuous liquid column needed for the siphon to operate.","steps":["Step 1: Priming fills the tube with liquid.","Step 2: This establishes the continuous liquid column needed for the siphon to operate."],"options":[],"conceptId":"physics_pressure_pressure_gauges_and_siphons","skillId":"physics_pressure","subskillId":"physics_pressure_q5","subject":"physics","chapter":"pressure","topic":"Pressure Gauges and Siphons"}', 4),
  (1960, 488, 'What does a simple U-tube manometer measure?', 'text', 1, 'It compares pressure on the two sides.', '{"why":"A manometer compares the pressure applied to its two sides.","sol":"Step 1: Different pressures can produce different liquid levels.\nStep 2: The level difference indicates the pressure difference.","steps":["Step 1: Different pressures can produce different liquid levels.","Step 2: The level difference indicates the pressure difference."],"options":[],"conceptId":"physics_pressure_the_u_tube_manometer","skillId":"physics_pressure","subskillId":"physics_pressure_q1","subject":"physics","chapter":"pressure","topic":"The U-Tube Manometer"}', 0),
  (1961, 488, 'A mercury manometer has a level difference of 0.20 m. Calculate the pressure difference using ρ = 13,600 kg/m³ and g = 10 N/kg.', 'text', 1, 'Use ΔP = ρgh.', '{"why":"The pressure difference is determined by the density and vertical height difference.","sol":"Step 1: ΔP = 13,600 × 10 × 0.20\nStep 2: ΔP = 27,200 Pa","steps":["Step 1: ΔP = 13,600 × 10 × 0.20","Step 2: ΔP = 27,200 Pa"],"options":[],"conceptId":"physics_pressure_the_u_tube_manometer","skillId":"physics_pressure","subskillId":"physics_pressure_q2","subject":"physics","chapter":"pressure","topic":"The U-Tube Manometer"}', 1),
  (1962, 488, 'A water manometer has a level difference of 0.30 m. Calculate the pressure difference using ρ = 1,000 kg/m³ and g = 10 N/kg.', 'text', 1, 'Convert the given height directly in metres.', '{"why":"The liquid column''s pressure difference is ρgh.","sol":"Step 1: ΔP = 1,000 × 10 × 0.30\nStep 2: ΔP = 3,000 Pa","steps":["Step 1: ΔP = 1,000 × 10 × 0.30","Step 2: ΔP = 3,000 Pa"],"options":[],"conceptId":"physics_pressure_the_u_tube_manometer","skillId":"physics_pressure","subskillId":"physics_pressure_q3","subject":"physics","chapter":"pressure","topic":"The U-Tube Manometer"}', 2),
  (1963, 488, 'Why must the vertical level difference be used instead of the total length of the U-tube?', 'text', 1, 'Pressure depends on vertical depth.', '{"why":"Only the vertical height difference enters the equation ΔP = ρgh.","sol":"Step 1: The liquid''s weight depends on its vertical height.\nStep 2: The tube''s curved length does not determine the hydrostatic pressure difference.","steps":["Step 1: The liquid''s weight depends on its vertical height.","Step 2: The tube''s curved length does not determine the hydrostatic pressure difference."],"options":[],"conceptId":"physics_pressure_the_u_tube_manometer","skillId":"physics_pressure","subskillId":"physics_pressure_q4","subject":"physics","chapter":"pressure","topic":"The U-Tube Manometer"}', 3),
  (1964, 488, 'If the same manometer liquid is used and the height difference doubles, what happens to the pressure difference?', 'text', 1, 'Pressure difference is proportional to h.', '{"why":"Pressure difference is directly proportional to the vertical height difference.","sol":"Step 1: ΔP = ρgh.\nStep 2: If h doubles while ρ and g remain constant, ΔP doubles.","steps":["Step 1: ΔP = ρgh.","Step 2: If h doubles while ρ and g remain constant, ΔP doubles."],"options":[],"conceptId":"physics_pressure_the_u_tube_manometer","skillId":"physics_pressure","subskillId":"physics_pressure_q5","subject":"physics","chapter":"pressure","topic":"The U-Tube Manometer"}', 4),
  (1965, 489, 'In a simple open-ended U-tube manometer, the liquid level is lower on the gas-connected side. Which pressure is greater?', 'text', 1, 'The greater pressure pushes the liquid down on its side.', '{"why":"The gas pushes the manometer liquid down in its arm.","sol":"Step 1: The liquid is pushed down on the gas-connected side.\nStep 2: The gas pressure is greater than atmospheric pressure.","steps":["Step 1: The liquid is pushed down on the gas-connected side.","Step 2: The gas pressure is greater than atmospheric pressure."],"options":[],"conceptId":"physics_pressure_interpreting_manometer_readings","skillId":"physics_pressure","subskillId":"physics_pressure_q1","subject":"physics","chapter":"pressure","topic":"Interpreting Manometer Readings"}', 0),
  (1966, 489, 'A mercury manometer shows a height difference of 0.04 m. Calculate the pressure difference using ρ = 13,600 kg/m³ and g = 10 N/kg.', 'text', 1, 'Use ΔP = ρgh.', '{"why":"The level difference gives the pressure difference.","sol":"Step 1: ΔP = 13,600 × 10 × 0.04\nStep 2: ΔP = 5,440 Pa","steps":["Step 1: ΔP = 13,600 × 10 × 0.04","Step 2: ΔP = 5,440 Pa"],"options":[],"conceptId":"physics_pressure_interpreting_manometer_readings","skillId":"physics_pressure","subskillId":"physics_pressure_q2","subject":"physics","chapter":"pressure","topic":"Interpreting Manometer Readings"}', 1),
  (1967, 489, 'A gas has a gauge pressure of 8,000 Pa. If atmospheric pressure is 100,000 Pa, find its absolute pressure.', 'text', 1, 'Absolute pressure equals atmospheric pressure plus gauge pressure.', '{"why":"Gauge pressure is the amount above atmospheric pressure.","sol":"Step 1: Absolute pressure = 100,000 + 8,000\nStep 2: = 108,000 Pa","steps":["Step 1: Absolute pressure = 100,000 + 8,000","Step 2: = 108,000 Pa"],"options":[],"conceptId":"physics_pressure_interpreting_manometer_readings","skillId":"physics_pressure","subskillId":"physics_pressure_q3","subject":"physics","chapter":"pressure","topic":"Interpreting Manometer Readings"}', 2),
  (1968, 489, 'A gas has an absolute pressure of 95,000 Pa while atmospheric pressure is 100,000 Pa. Calculate its gauge pressure.', 'text', 1, 'Subtract atmospheric pressure from absolute pressure.', '{"why":"A negative gauge pressure means the gas pressure is below atmospheric pressure.","sol":"Step 1: Gauge pressure = absolute pressure − atmospheric pressure\nStep 2: = 95,000 − 100,000\nStep 3: = −5,000 Pa","steps":["Step 1: Gauge pressure = absolute pressure − atmospheric pressure","Step 2: = 95,000 − 100,000","Step 3: = −5,000 Pa"],"options":[],"conceptId":"physics_pressure_interpreting_manometer_readings","skillId":"physics_pressure","subskillId":"physics_pressure_q4","subject":"physics","chapter":"pressure","topic":"Interpreting Manometer Readings"}', 3),
  (1969, 489, 'A learner adds atmospheric pressure to an absolute pressure to find gauge pressure. What is the mistake?', 'text', 1, 'Rearrange the relationship between the three pressures.', '{"why":"Adding atmospheric pressure to absolute pressure counts the atmospheric contribution twice.","sol":"Step 1: Absolute pressure = atmospheric pressure + gauge pressure.\nStep 2: Therefore gauge pressure = absolute pressure − atmospheric pressure.","steps":["Step 1: Absolute pressure = atmospheric pressure + gauge pressure.","Step 2: Therefore gauge pressure = absolute pressure − atmospheric pressure."],"options":[],"conceptId":"physics_pressure_interpreting_manometer_readings","skillId":"physics_pressure","subskillId":"physics_pressure_q5","subject":"physics","chapter":"pressure","topic":"Interpreting Manometer Readings"}', 4),
  (1970, 490, 'What principle allows pressure from the brake pedal to be transmitted through brake fluid?', 'text', 1, 'Recall the behaviour of pressure in an enclosed fluid.', '{"why":"Pressure applied to an enclosed fluid is transmitted throughout the fluid.","sol":"Step 1: The master cylinder increases fluid pressure.\nStep 2: The pressure change is transmitted through the enclosed fluid.","steps":["Step 1: The master cylinder increases fluid pressure.","Step 2: The pressure change is transmitted through the enclosed fluid."],"options":[],"conceptId":"physics_pressure_hydraulic_braking_systems","skillId":"physics_pressure","subskillId":"physics_pressure_q1","subject":"physics","chapter":"pressure","topic":"Hydraulic Braking Systems"}', 0),
  (1971, 490, 'What actually produces the force that slows a vehicle at the brake pads?', 'text', 1, 'Think about the contact between the brake pads and the rotating disc.', '{"why":"Hydraulic pressure operates the brakes, while friction provides the braking effect.","sol":"Step 1: Hydraulic pressure moves the braking components.\nStep 2: The pads press against the rotating disc.\nStep 3: Friction opposes the disc''s motion.","steps":["Step 1: Hydraulic pressure moves the braking components.","Step 2: The pads press against the rotating disc.","Step 3: Friction opposes the disc''s motion."],"options":[],"conceptId":"physics_pressure_hydraulic_braking_systems","skillId":"physics_pressure","subskillId":"physics_pressure_q2","subject":"physics","chapter":"pressure","topic":"Hydraulic Braking Systems"}', 1),
  (1972, 490, 'Why is air in hydraulic brake lines a problem?', 'text', 1, 'Compare the compressibility of air and liquid.', '{"why":"Trapped air makes the hydraulic response less direct.","sol":"Step 1: Air is readily compressed.\nStep 2: Some pedal movement compresses the air instead of efficiently transmitting pressure.","steps":["Step 1: Air is readily compressed.","Step 2: Some pedal movement compresses the air instead of efficiently transmitting pressure."],"options":[],"conceptId":"physics_pressure_hydraulic_braking_systems","skillId":"physics_pressure","subskillId":"physics_pressure_q3","subject":"physics","chapter":"pressure","topic":"Hydraulic Braking Systems"}', 2),
  (1973, 490, 'A brake-fluid system transmits a pressure change of 2,000 Pa to a piston with area 0.01 m². Calculate the force on that piston.', 'text', 1, 'Rearrange P = F/A.', '{"why":"The force on a piston equals the pressure multiplied by its area.","sol":"Step 1: F = PA\nStep 2: F = 2,000 × 0.01\nStep 3: F = 20 N","steps":["Step 1: F = PA","Step 2: F = 2,000 × 0.01","Step 3: F = 20 N"],"options":[],"conceptId":"physics_pressure_hydraulic_braking_systems","skillId":"physics_pressure","subskillId":"physics_pressure_q4","subject":"physics","chapter":"pressure","topic":"Hydraulic Braking Systems"}', 3),
  (1974, 490, 'Why must brake fluid be compatible with the seals in a braking system?', 'text', 1, 'Consider leakage and deterioration.', '{"why":"The braking system needs sound seals to maintain hydraulic pressure.","sol":"Step 1: Incompatible fluid can damage seals.\nStep 2: Damaged seals can allow fluid to leak.\nStep 3: Leaks can compromise braking.","steps":["Step 1: Incompatible fluid can damage seals.","Step 2: Damaged seals can allow fluid to leak.","Step 3: Leaks can compromise braking."],"options":[],"conceptId":"physics_pressure_hydraulic_braking_systems","skillId":"physics_pressure","subskillId":"physics_pressure_q5","subject":"physics","chapter":"pressure","topic":"Hydraulic Braking Systems"}', 4),
  (1975, 491, 'What happens to the air pressure inside the pump chamber when the piston is pushed down?', 'text', 1, 'The chamber volume decreases.', '{"why":"Compressing the air in the chamber raises its pressure.","sol":"Step 1: The piston compresses the air.\nStep 2: The air occupies a smaller volume.\nStep 3: Its pressure increases.","steps":["Step 1: The piston compresses the air.","Step 2: The air occupies a smaller volume.","Step 3: Its pressure increases."],"options":[],"conceptId":"physics_pressure_the_bicycle_pump","skillId":"physics_pressure","subskillId":"physics_pressure_q1","subject":"physics","chapter":"pressure","topic":"The Bicycle Pump"}', 0),
  (1976, 491, 'What is the function of the inlet valve in a bicycle pump?', 'text', 1, 'Consider the air entering the chamber.', '{"why":"The inlet valve permits air intake during the return stroke.","sol":"Step 1: The pump chamber expands as the piston is pulled back.\nStep 2: The inlet valve allows air to enter the chamber.","steps":["Step 1: The pump chamber expands as the piston is pulled back.","Step 2: The inlet valve allows air to enter the chamber."],"options":[],"conceptId":"physics_pressure_the_bicycle_pump","skillId":"physics_pressure","subskillId":"physics_pressure_q2","subject":"physics","chapter":"pressure","topic":"The Bicycle Pump"}', 1),
  (1977, 491, 'Why does the pump''s outlet valve open during the compression stroke?', 'text', 1, 'Compare chamber pressure with tyre pressure.', '{"why":"Air flows from the higher-pressure chamber into the tyre.","sol":"Step 1: Pushing the piston raises chamber pressure.\nStep 2: Air flows into the tyre when the chamber pressure is sufficiently greater than tyre pressure and the valve opens.","steps":["Step 1: Pushing the piston raises chamber pressure.","Step 2: Air flows into the tyre when the chamber pressure is sufficiently greater than tyre pressure and the valve opens."],"options":[],"conceptId":"physics_pressure_the_bicycle_pump","skillId":"physics_pressure","subskillId":"physics_pressure_q3","subject":"physics","chapter":"pressure","topic":"The Bicycle Pump"}', 2),
  (1978, 491, 'A pump compresses air but the outlet valve does not open. Will air enter the tyre?', 'text', 1, 'The air needs a path into the tyre.', '{"why":"The outlet valve must allow air to pass into the tyre.","sol":"Step 1: Compression can raise the chamber pressure.\nStep 2: A closed outlet valve blocks the flow into the tyre.","steps":["Step 1: Compression can raise the chamber pressure.","Step 2: A closed outlet valve blocks the flow into the tyre."],"options":[],"conceptId":"physics_pressure_the_bicycle_pump","skillId":"physics_pressure","subskillId":"physics_pressure_q4","subject":"physics","chapter":"pressure","topic":"The Bicycle Pump"}', 3),
  (1979, 491, 'What is the main function of the valves in a bicycle pump?', 'text', 1, 'Think about preventing air from moving in the wrong direction.', '{"why":"The valves help the pump draw in air and then deliver it to the tyre.","sol":"Step 1: The inlet valve allows air into the chamber.\nStep 2: The outlet valve allows air toward the tyre.\nStep 3: Together they control the direction of flow.","steps":["Step 1: The inlet valve allows air into the chamber.","Step 2: The outlet valve allows air toward the tyre.","Step 3: Together they control the direction of flow."],"options":[],"conceptId":"physics_pressure_the_bicycle_pump","skillId":"physics_pressure","subskillId":"physics_pressure_q5","subject":"physics","chapter":"pressure","topic":"The Bicycle Pump"}', 4),
  (1980, 492, 'Why does liquid enter a syringe when its plunger is pulled back with the nozzle immersed?', 'text', 1, 'Pulling back increases the barrel volume.', '{"why":"Liquid moves because of the pressure difference.","sol":"Step 1: The volume increases.\nStep 2: The pressure inside falls.\nStep 3: The greater outside pressure pushes liquid into the syringe.","steps":["Step 1: The volume increases.","Step 2: The pressure inside falls.","Step 3: The greater outside pressure pushes liquid into the syringe."],"options":[],"conceptId":"physics_pressure_the_syringe","skillId":"physics_pressure","subskillId":"physics_pressure_q1","subject":"physics","chapter":"pressure","topic":"The Syringe"}', 0),
  (1981, 492, 'What happens to the pressure inside a syringe when the plunger is pushed inward and the nozzle is blocked?', 'text', 1, 'The trapped fluid has less space.', '{"why":"Pushing against trapped contents raises the internal pressure.","sol":"Step 1: The plunger reduces the available volume.\nStep 2: The trapped contents resist compression.\nStep 3: The pressure increases.","steps":["Step 1: The plunger reduces the available volume.","Step 2: The trapped contents resist compression.","Step 3: The pressure increases."],"options":[],"conceptId":"physics_pressure_the_syringe","skillId":"physics_pressure","subskillId":"physics_pressure_q2","subject":"physics","chapter":"pressure","topic":"The Syringe"}', 1),
  (1982, 492, 'A syringe has the same pressure inside and outside. What pressure difference is available to drive liquid through its nozzle?', 'text', 1, 'Subtract the two pressures.', '{"why":"Equal pressures provide no pressure difference to drive flow.","sol":"Step 1: Pressure difference = outside pressure − inside pressure.\nStep 2: If the pressures are equal, the difference is zero.","steps":["Step 1: Pressure difference = outside pressure − inside pressure.","Step 2: If the pressures are equal, the difference is zero."],"options":[],"conceptId":"physics_pressure_the_syringe","skillId":"physics_pressure","subskillId":"physics_pressure_q3","subject":"physics","chapter":"pressure","topic":"The Syringe"}', 2),
  (1983, 492, 'Why might a syringe with an airtight, blocked nozzle resist movement when its plunger is pushed?', 'text', 1, 'Consider what happens to the trapped contents.', '{"why":"The trapped contents cannot readily leave the closed syringe.","sol":"Step 1: The blocked nozzle prevents contents from escaping.\nStep 2: Pushing the plunger raises the internal pressure.\nStep 3: That pressure opposes further movement.","steps":["Step 1: The blocked nozzle prevents contents from escaping.","Step 2: Pushing the plunger raises the internal pressure.","Step 3: That pressure opposes further movement."],"options":[],"conceptId":"physics_pressure_the_syringe","skillId":"physics_pressure","subskillId":"physics_pressure_q4","subject":"physics","chapter":"pressure","topic":"The Syringe"}', 3),
  (1984, 492, 'A learner says the plunger pulls liquid directly into the syringe. Improve the explanation.', 'text', 1, 'Explain the pressure change instead.', '{"why":"The pressure difference, rather than a direct pulling action on the liquid, drives the flow.","sol":"Step 1: Pulling the plunger increases the internal volume.\nStep 2: The internal pressure falls.\nStep 3: The greater external pressure pushes liquid into the syringe.","steps":["Step 1: Pulling the plunger increases the internal volume.","Step 2: The internal pressure falls.","Step 3: The greater external pressure pushes liquid into the syringe."],"options":[],"conceptId":"physics_pressure_the_syringe","skillId":"physics_pressure","subskillId":"physics_pressure_q5","subject":"physics","chapter":"pressure","topic":"The Syringe"}', 4),
  (1985, 493, 'What causes liquid to rise through a drinking straw?', 'text', 1, 'Compare the pressure inside the straw with the pressure on the liquid surface.', '{"why":"The higher external pressure pushes liquid into the lower-pressure straw.","sol":"Step 1: Sucking lowers pressure inside the straw.\nStep 2: The pressure on the liquid surface is greater.\nStep 3: The pressure difference pushes liquid upwards.","steps":["Step 1: Sucking lowers pressure inside the straw.","Step 2: The pressure on the liquid surface is greater.","Step 3: The pressure difference pushes liquid upwards."],"options":[],"conceptId":"physics_pressure_the_drinking_straw","skillId":"physics_pressure","subskillId":"physics_pressure_q1","subject":"physics","chapter":"pressure","topic":"The Drinking Straw"}', 0),
  (1986, 493, 'What happens to the pressure inside the straw when a person sucks?', 'text', 1, 'The action lowers the pressure in the mouth and straw.', '{"why":"The lower internal pressure enables the outside pressure to push liquid upwards.","sol":"Step 1: Sucking removes some air from the region.\nStep 2: The pressure inside the straw falls.","steps":["Step 1: Sucking removes some air from the region.","Step 2: The pressure inside the straw falls."],"options":[],"conceptId":"physics_pressure_the_drinking_straw","skillId":"physics_pressure","subskillId":"physics_pressure_q2","subject":"physics","chapter":"pressure","topic":"The Drinking Straw"}', 1),
  (1987, 493, 'Why can a hole in the side of a straw make drinking difficult?', 'text', 1, 'Air can enter through the hole.', '{"why":"A pressure difference is needed to move the liquid upwards.","sol":"Step 1: Air enters through the hole.\nStep 2: The pressure inside the straw may no longer fall sufficiently.\nStep 3: The pressure difference becomes too small to raise liquid effectively.","steps":["Step 1: Air enters through the hole.","Step 2: The pressure inside the straw may no longer fall sufficiently.","Step 3: The pressure difference becomes too small to raise liquid effectively."],"options":[],"conceptId":"physics_pressure_the_drinking_straw","skillId":"physics_pressure","subskillId":"physics_pressure_q3","subject":"physics","chapter":"pressure","topic":"The Drinking Straw"}', 2),
  (1988, 493, 'Does a drinking straw work because atmospheric pressure disappears when you suck?', 'text', 1, 'Atmospheric pressure remains on the liquid surface.', '{"why":"Atmospheric pressure remains present and helps push liquid up the straw.","sol":"Step 1: Atmospheric pressure continues to act on the liquid surface.\nStep 2: Sucking lowers pressure inside the straw.\nStep 3: The difference in pressure moves the liquid.","steps":["Step 1: Atmospheric pressure continues to act on the liquid surface.","Step 2: Sucking lowers pressure inside the straw.","Step 3: The difference in pressure moves the liquid."],"options":[],"conceptId":"physics_pressure_the_drinking_straw","skillId":"physics_pressure","subskillId":"physics_pressure_q4","subject":"physics","chapter":"pressure","topic":"The Drinking Straw"}', 3),
  (1989, 493, 'The pressure on the cup''s liquid surface is 100,000 Pa and pressure inside the straw is 98,000 Pa. What is the pressure difference?', 'text', 1, 'Subtract the smaller pressure from the larger pressure.', '{"why":"The pressure difference is the difference between the two pressures.","sol":"Step 1: ΔP = 100,000 − 98,000\nStep 2: ΔP = 2,000 Pa","steps":["Step 1: ΔP = 100,000 − 98,000","Step 2: ΔP = 2,000 Pa"],"options":[],"conceptId":"physics_pressure_the_drinking_straw","skillId":"physics_pressure","subskillId":"physics_pressure_q5","subject":"physics","chapter":"pressure","topic":"The Drinking Straw"}', 4),
  (1990, 494, 'What is the main purpose of a force pump?', 'text', 1, 'Think about moving liquid under pressure.', '{"why":"A force pump can deliver liquid against a pressure difference.","sol":"Step 1: The piston increases the liquid pressure.\nStep 2: The pressurised liquid is forced into the delivery pipe.","steps":["Step 1: The piston increases the liquid pressure.","Step 2: The pressurised liquid is forced into the delivery pipe."],"options":[],"conceptId":"physics_pressure_the_force_pump","skillId":"physics_pressure","subskillId":"physics_pressure_q1","subject":"physics","chapter":"pressure","topic":"The Force Pump"}', 0),
  (1991, 494, 'What happens to the inlet valve during the delivery stroke in a typical force pump?', 'text', 1, 'The liquid must not flow backwards.', '{"why":"Closing the inlet valve directs the liquid toward the delivery outlet.","sol":"Step 1: The piston pushes liquid forward.\nStep 2: The inlet valve closes to prevent backward flow.","steps":["Step 1: The piston pushes liquid forward.","Step 2: The inlet valve closes to prevent backward flow."],"options":[],"conceptId":"physics_pressure_the_force_pump","skillId":"physics_pressure","subskillId":"physics_pressure_q2","subject":"physics","chapter":"pressure","topic":"The Force Pump"}', 1),
  (1992, 494, 'Why does the outlet valve open during the delivery stroke?', 'text', 1, 'The liquid must have enough pressure to move into the delivery pipe.', '{"why":"The valve permits delivery when the pressure condition is met.","sol":"Step 1: The piston increases the pressure of the liquid.\nStep 2: When the pressure is sufficient, the outlet valve opens.\nStep 3: Liquid enters the delivery pipe.","steps":["Step 1: The piston increases the pressure of the liquid.","Step 2: When the pressure is sufficient, the outlet valve opens.","Step 3: Liquid enters the delivery pipe."],"options":[],"conceptId":"physics_pressure_the_force_pump","skillId":"physics_pressure","subskillId":"physics_pressure_q3","subject":"physics","chapter":"pressure","topic":"The Force Pump"}', 2),
  (1993, 494, 'What would happen if both valves allowed unrestricted flow in both directions?', 'text', 1, 'Think about the intended direction of the liquid.', '{"why":"Valves help direct liquid through the pump in the intended direction.","sol":"Step 1: The liquid could flow backwards during a stroke.\nStep 2: The pump would struggle to maintain one-way delivery.","steps":["Step 1: The liquid could flow backwards during a stroke.","Step 2: The pump would struggle to maintain one-way delivery."],"options":[],"conceptId":"physics_pressure_the_force_pump","skillId":"physics_pressure","subskillId":"physics_pressure_q4","subject":"physics","chapter":"pressure","topic":"The Force Pump"}', 3),
  (1994, 494, 'A pump applies a pressure of 5,000 Pa to a piston of area 0.02 m². Calculate the force on the piston.', 'text', 1, 'Use F = PA.', '{"why":"The force exerted by pressure on a surface equals pressure multiplied by area.","sol":"Step 1: F = 5,000 × 0.02\nStep 2: F = 100 N","steps":["Step 1: F = 5,000 × 0.02","Step 2: F = 100 N"],"options":[],"conceptId":"physics_pressure_the_force_pump","skillId":"physics_pressure","subskillId":"physics_pressure_q5","subject":"physics","chapter":"pressure","topic":"The Force Pump"}', 4),
  (1995, 495, 'What helps push water up the pipe in a conventional lift pump?', 'text', 1, 'Consider the pressure acting on the water surface in the well.', '{"why":"Atmospheric pressure pushes water toward the lower-pressure region in the pump.","sol":"Step 1: The pump reduces pressure above the water.\nStep 2: Atmospheric pressure acts on the water surface.\nStep 3: The pressure difference pushes water up the pipe.","steps":["Step 1: The pump reduces pressure above the water.","Step 2: Atmospheric pressure acts on the water surface.","Step 3: The pressure difference pushes water up the pipe."],"options":[],"conceptId":"physics_pressure_the_lift_pump","skillId":"physics_pressure","subskillId":"physics_pressure_q1","subject":"physics","chapter":"pressure","topic":"The Lift Pump"}', 0),
  (1996, 495, 'Why can a simple suction lift pump not raise water from an unlimited depth?', 'text', 1, 'The pump relies on atmospheric pressure.', '{"why":"The pump cannot create an unlimited pressure difference by suction.","sol":"Step 1: Atmospheric pressure can support only a limited water column.\nStep 2: As the required lift increases, the pressure difference becomes insufficient.\nStep 3: The pump has a maximum practical suction lift.","steps":["Step 1: Atmospheric pressure can support only a limited water column.","Step 2: As the required lift increases, the pressure difference becomes insufficient.","Step 3: The pump has a maximum practical suction lift."],"options":[],"conceptId":"physics_pressure_the_lift_pump","skillId":"physics_pressure","subskillId":"physics_pressure_q2","subject":"physics","chapter":"pressure","topic":"The Lift Pump"}', 1),
  (1997, 495, 'What is the role of valves in a lift pump?', 'text', 1, 'They help water move in the intended direction.', '{"why":"The valve sequence enables repeated strokes to raise water.","sol":"Step 1: The valves open and close during the pump strokes.\nStep 2: They control water flow and reduce backward movement.","steps":["Step 1: The valves open and close during the pump strokes.","Step 2: They control water flow and reduce backward movement."],"options":[],"conceptId":"physics_pressure_the_lift_pump","skillId":"physics_pressure","subskillId":"physics_pressure_q3","subject":"physics","chapter":"pressure","topic":"The Lift Pump"}', 2),
  (1998, 495, 'A student says water rises in a lift pump because the piston directly pulls the water from the well. What is the better explanation?', 'text', 1, 'Use pressure rather than a direct pulling force on the entire water column.', '{"why":"The pressure difference explains the water''s upward movement.","sol":"Step 1: The pump lowers pressure above the water.\nStep 2: Atmospheric pressure acts on the well''s water surface.\nStep 3: The pressure difference pushes water up the pipe.","steps":["Step 1: The pump lowers pressure above the water.","Step 2: Atmospheric pressure acts on the well''s water surface.","Step 3: The pressure difference pushes water up the pipe."],"options":[],"conceptId":"physics_pressure_the_lift_pump","skillId":"physics_pressure","subskillId":"physics_pressure_q4","subject":"physics","chapter":"pressure","topic":"The Lift Pump"}', 3),
  (1999, 495, 'What is the main difference between a simple lift pump and a force pump?', 'text', 1, 'Compare how each moves liquid.', '{"why":"Their operating mechanisms differ in how pressure is used to move liquid.","sol":"Step 1: A simple lift pump relies on atmospheric pressure to push water into a low-pressure region.\nStep 2: A force pump uses a piston to increase liquid pressure and deliver it.","steps":["Step 1: A simple lift pump relies on atmospheric pressure to push water into a low-pressure region.","Step 2: A force pump uses a piston to increase liquid pressure and deliver it."],"options":[],"conceptId":"physics_pressure_the_lift_pump","skillId":"physics_pressure","subskillId":"physics_pressure_q5","subject":"physics","chapter":"pressure","topic":"The Lift Pump"}', 4),
  (2000, 496, 'What is the purpose of an experiment demonstrating atmospheric pressure?', 'text', 1, 'It provides observable evidence of air pressure.', '{"why":"The experiment makes the effects of atmospheric pressure observable.","sol":"Step 1: Air exerts pressure.\nStep 2: A demonstration shows an effect caused by that pressure.","steps":["Step 1: Air exerts pressure.","Step 2: A demonstration shows an effect caused by that pressure."],"options":[],"conceptId":"physics_pressure_demonstrating_atmospheric_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q1","subject":"physics","chapter":"pressure","topic":"Demonstrating Atmospheric Pressure"}', 0);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (2001, 496, 'Why can a card remain beneath an inverted water-filled container under suitable conditions?', 'text', 1, 'Consider pressure outside and inside the container.', '{"why":"The card is not supported by atmospheric pressure alone in every possible setup; sealing and surface effects matter.","sol":"Step 1: The pressure difference acts on the card.\nStep 2: Atmospheric pressure outside can help support it.\nStep 3: A good seal and surface tension also help prevent leakage.","steps":["Step 1: The pressure difference acts on the card.","Step 2: Atmospheric pressure outside can help support it.","Step 3: A good seal and surface tension also help prevent leakage."],"options":[],"conceptId":"physics_pressure_demonstrating_atmospheric_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q2","subject":"physics","chapter":"pressure","topic":"Demonstrating Atmospheric Pressure"}', 1),
  (2002, 496, 'What may happen when the pressure inside a suitable container is greatly reduced while the outside atmospheric pressure remains high?', 'text', 1, 'Compare the forces caused by the two pressures.', '{"why":"The external atmospheric pressure can exceed the container''s ability to resist the net force.","sol":"Step 1: The outside pressure becomes much greater than the inside pressure.\nStep 2: The pressure difference creates a net inward force.\nStep 3: The container may collapse if it is not strong enough.","steps":["Step 1: The outside pressure becomes much greater than the inside pressure.","Step 2: The pressure difference creates a net inward force.","Step 3: The container may collapse if it is not strong enough."],"options":[],"conceptId":"physics_pressure_demonstrating_atmospheric_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q3","subject":"physics","chapter":"pressure","topic":"Demonstrating Atmospheric Pressure"}', 2),
  (2003, 496, 'Why should a demonstration with an inverted water container be performed over a basin?', 'text', 1, 'Think about what could go wrong.', '{"why":"The demonstration may not work perfectly every time.","sol":"Step 1: The seal may fail.\nStep 2: Water may spill.\nStep 3: A basin helps contain the water.","steps":["Step 1: The seal may fail.","Step 2: Water may spill.","Step 3: A basin helps contain the water."],"options":[],"conceptId":"physics_pressure_demonstrating_atmospheric_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q4","subject":"physics","chapter":"pressure","topic":"Demonstrating Atmospheric Pressure"}', 3),
  (2004, 496, 'A learner claims that a suction cup sticks only because the cup pulls the wall toward itself. Explain the role of pressure.', 'text', 1, 'Think about the pressure inside the cup.', '{"why":"A pressure difference is central to suction-cup attachment.","sol":"Step 1: Pressing the cup against a smooth surface reduces the air trapped beneath it.\nStep 2: The pressure outside is greater than the pressure inside.\nStep 3: The pressure difference presses the cup against the surface.","steps":["Step 1: Pressing the cup against a smooth surface reduces the air trapped beneath it.","Step 2: The pressure outside is greater than the pressure inside.","Step 3: The pressure difference presses the cup against the surface."],"options":[],"conceptId":"physics_pressure_demonstrating_atmospheric_pressure","skillId":"physics_pressure","subskillId":"physics_pressure_q5","subject":"physics","chapter":"pressure","topic":"Demonstrating Atmospheric Pressure"}', 4),
  (2005, 497, 'Convert 25°C to kelvin using 273 as the approximation.', 'text', 1, 'Add 273 to the Celsius temperature.', '{"why":"25°C is approximately 298 K.","sol":"Step 1: T = 25 + 273.\nStep 2: T = 298 K.","steps":["Step 1: T = 25 + 273.","Step 2: T = 298 K."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_temperature","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q1","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Temperature"}', 0),
  (2006, 497, 'Convert 310 K to degrees Celsius using 273 as the approximation.', 'text', 1, 'Reverse the conversion by subtracting 273.', '{"why":"310 K is approximately 37°C.","sol":"Step 1: t = 310 − 273.\nStep 2: t = 37°C.","steps":["Step 1: t = 310 − 273.","Step 2: t = 37°C."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_temperature","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q2","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Temperature"}', 1),
  (2007, 497, 'What is the SI unit of thermodynamic temperature?', 'text', 1, 'It is not the degree Celsius.', '{"why":"The kelvin is the SI base unit of thermodynamic temperature.","sol":"Step 1: Identify the SI base unit for temperature.\nStep 2: The unit is the kelvin.","steps":["Step 1: Identify the SI base unit for temperature.","Step 2: The unit is the kelvin."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_temperature","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q3","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Temperature"}', 2),
  (2008, 497, 'Explain the difference between temperature and heat.', 'text', 1, 'One describes a state; the other is energy being transferred.', '{"why":"An object has a temperature; heat describes energy transfer between objects or systems.","sol":"Step 1: Temperature describes how hot or cold something is.\nStep 2: Heat is energy transferred due to a temperature difference.","steps":["Step 1: Temperature describes how hot or cold something is.","Step 2: Heat is energy transferred due to a temperature difference."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_temperature","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q4","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Temperature"}', 3),
  (2009, 497, 'A classroom is at 20°C. Express this temperature in kelvin using the more precise conversion.', 'text', 1, 'Add 273.15.', '{"why":"20°C corresponds to 293.15 K.","sol":"Step 1: T = 20 + 273.15.\nStep 2: T = 293.15 K.","steps":["Step 1: T = 20 + 273.15.","Step 2: T = 293.15 K."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_temperature","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q5","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Temperature"}', 4),
  (2010, 498, 'What is thermal expansion?', 'text', 1, 'Think about what usually happens to a material''s dimensions when heated.', '{"why":"Most materials expand when heated and contract when cooled.","sol":"Step 1: Heating changes particle motion and spacing.\nStep 2: The material''s dimensions generally increase.\nStep 3: This is thermal expansion.","steps":["Step 1: Heating changes particle motion and spacing.","Step 2: The material''s dimensions generally increase.","Step 3: This is thermal expansion."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_thermal_expansion","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q1","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Thermal Expansion"}', 0),
  (2011, 498, 'Why are expansion joints provided in many bridges?', 'text', 1, 'Consider what happens to bridge materials on hot days.', '{"why":"Expansion joints provide space for temperature-related changes in length.","sol":"Step 1: Bridge materials heat up and expand.\nStep 2: Without room for expansion, large stresses can develop.\nStep 3: Joints allow the structure to accommodate dimensional changes.","steps":["Step 1: Bridge materials heat up and expand.","Step 2: Without room for expansion, large stresses can develop.","Step 3: Joints allow the structure to accommodate dimensional changes."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_thermal_expansion","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q2","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Thermal Expansion"}', 1),
  (2012, 498, 'What generally happens to the length of a metal rod when it is cooled?', 'text', 1, 'Cooling is usually the reverse of thermal expansion.', '{"why":"Most solids contract as their temperature decreases.","sol":"Step 1: The rod loses thermal energy.\nStep 2: Its temperature decreases.\nStep 3: Its length generally decreases.","steps":["Step 1: The rod loses thermal energy.","Step 2: Its temperature decreases.","Step 3: Its length generally decreases."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_thermal_expansion","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q3","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Thermal Expansion"}', 2),
  (2013, 498, 'Two rods of equal original length receive the same temperature rise. Must they expand by equal amounts?', 'text', 1, 'Consider whether different materials have identical expansion properties.', '{"why":"The coefficient of expansion varies between materials.","sol":"Step 1: Expansion depends on the material''s properties.\nStep 2: Different materials can have different expansion coefficients.\nStep 3: Their expansions need not be equal.","steps":["Step 1: Expansion depends on the material''s properties.","Step 2: Different materials can have different expansion coefficients.","Step 3: Their expansions need not be equal."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_thermal_expansion","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q4","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Thermal Expansion"}', 3),
  (2014, 498, 'Why can an overhead metal wire sag more on a hot day?', 'text', 1, 'Relate the temperature rise to the wire''s length.', '{"why":"Thermal expansion increases the length of the wire.","sol":"Step 1: The wire becomes warmer.\nStep 2: The wire expands and its length increases.\nStep 3: With its supports fixed, the extra length can increase sag.","steps":["Step 1: The wire becomes warmer.","Step 2: The wire expands and its length increases.","Step 3: With its supports fixed, the extra length can increase sag."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_thermal_expansion","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q5","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Thermal Expansion"}', 4),
  (2015, 499, 'A 3 m rod has a linear expansion coefficient of 1 × 10⁻⁵ K⁻¹. Its temperature rises by 20 K. Calculate its increase in length.', 'text', 1, 'Use ΔL = αL₀ΔT.', '{"why":"Substitution gives a length increase of 6 × 10⁻⁴ m.","sol":"Step 1: ΔL = (1 × 10⁻⁵) × 3 × 20.\nStep 2: ΔL = 0.0006 m.\nStep 3: Convert: 0.0006 m = 0.6 mm.","steps":["Step 1: ΔL = (1 × 10⁻⁵) × 3 × 20.","Step 2: ΔL = 0.0006 m.","Step 3: Convert: 0.0006 m = 0.6 mm."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_linear_expansion_of_solids","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q1","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Linear Expansion of Solids"}', 0),
  (2016, 499, 'A 5 m metal rod expands by 0.002 m when heated by 40 K. Calculate its coefficient of linear expansion.', 'text', 1, 'Rearrange the equation to make α the subject.', '{"why":"The coefficient is 0.002 ÷ 200 = 0.00001 K⁻¹.","sol":"Step 1: α = 0.002/(5 × 40).\nStep 2: α = 0.002/200.\nStep 3: α = 1 × 10⁻⁵ K⁻¹.","steps":["Step 1: α = 0.002/(5 × 40).","Step 2: α = 0.002/200.","Step 3: α = 1 × 10⁻⁵ K⁻¹."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_linear_expansion_of_solids","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q2","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Linear Expansion of Solids"}', 1),
  (2017, 499, 'A rod is 4 m long. Its coefficient of linear expansion is 2 × 10⁻⁵ K⁻¹. Find its length increase for a 25 K temperature rise.', 'text', 1, 'Multiply the coefficient, original length and temperature change.', '{"why":"The rod length increases by 2 mm.","sol":"Step 1: ΔL = (2 × 10⁻⁵) × 4 × 25.\nStep 2: ΔL = 0.002 m.\nStep 3: 0.002 m = 2 mm.","steps":["Step 1: ΔL = (2 × 10⁻⁵) × 4 × 25.","Step 2: ΔL = 0.002 m.","Step 3: 0.002 m = 2 mm."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_linear_expansion_of_solids","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q3","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Linear Expansion of Solids"}', 2),
  (2018, 499, 'A rod''s temperature rises from 15°C to 65°C. What temperature change should be used in the linear expansion equation?', 'text', 1, 'Subtract the initial temperature from the final temperature.', '{"why":"The temperature rises by 50 degrees.","sol":"Step 1: ΔT = 65 − 15.\nStep 2: ΔT = 50°C, equivalent to a 50 K temperature change.","steps":["Step 1: ΔT = 65 − 15.","Step 2: ΔT = 50°C, equivalent to a 50 K temperature change."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_linear_expansion_of_solids","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q4","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Linear Expansion of Solids"}', 3),
  (2019, 499, 'Two rods have equal original lengths and the same temperature rise. Rod A has twice the coefficient of linear expansion of rod B. Compare their length increases.', 'text', 1, 'In ΔL = αL₀ΔT, only α differs.', '{"why":"Expansion is directly proportional to the coefficient when initial length and temperature change are fixed.","sol":"Step 1: Both rods have equal L₀.\nStep 2: Both have equal ΔT.\nStep 3: Rod A has twice α, so it has twice the expansion.","steps":["Step 1: Both rods have equal L₀.","Step 2: Both have equal ΔT.","Step 3: Rod A has twice α, so it has twice the expansion."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_linear_expansion_of_solids","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q5","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Linear Expansion of Solids"}', 4),
  (2020, 500, 'An object absorbs 2,400 J and its temperature rises by 12 K. Calculate its heat capacity.', 'text', 1, 'Divide energy transferred by temperature change.', '{"why":"2,400 J ÷ 12 K = 200 J/K.","sol":"Step 1: C = 2,400/12.\nStep 2: C = 200 J/K.","steps":["Step 1: C = 2,400/12.","Step 2: C = 200 J/K."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_heat_capacity","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q1","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Heat Capacity"}', 0),
  (2021, 500, 'An object has heat capacity 500 J/K. How much energy is required to raise its temperature by 8 K?', 'text', 1, 'Rearrange C = Q/ΔT.', '{"why":"The required energy is 4,000 J.","sol":"Step 1: Q = 500 × 8.\nStep 2: Q = 4,000 J.","steps":["Step 1: Q = 500 × 8.","Step 2: Q = 4,000 J."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_heat_capacity","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q2","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Heat Capacity"}', 1),
  (2022, 500, 'An object receives 9,000 J and has a heat capacity of 300 J/K. Find its temperature rise.', 'text', 1, 'Rearrange the equation to make ΔT the subject.', '{"why":"9,000 J ÷ 300 J/K = 30 K.","sol":"Step 1: ΔT = 9,000/300.\nStep 2: ΔT = 30 K.","steps":["Step 1: ΔT = 9,000/300.","Step 2: ΔT = 30 K."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_heat_capacity","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q3","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Heat Capacity"}', 2),
  (2023, 500, 'Which requires more energy for the same temperature rise: an object with heat capacity 100 J/K or one with heat capacity 400 J/K?', 'text', 1, 'For a fixed temperature rise, energy equals heat capacity multiplied by the rise.', '{"why":"At equal temperature change, energy transferred is proportional to heat capacity.","sol":"Step 1: Both objects have the same ΔT.\nStep 2: The second object''s heat capacity is four times greater.\nStep 3: It needs four times as much energy for that rise.","steps":["Step 1: Both objects have the same ΔT.","Step 2: The second object''s heat capacity is four times greater.","Step 3: It needs four times as much energy for that rise."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_heat_capacity","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q4","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Heat Capacity"}', 3),
  (2024, 500, 'What is the SI unit of heat capacity?', 'text', 1, 'Heat capacity is energy divided by temperature change.', '{"why":"Heat capacity applies to the entire object; specific heat capacity applies per unit mass.","sol":"Step 1: Energy is measured in joules.\nStep 2: Temperature change is measured in kelvin.\nStep 3: The unit is J/K.","steps":["Step 1: Energy is measured in joules.","Step 2: Temperature change is measured in kelvin.","Step 3: The unit is J/K."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_heat_capacity","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q5","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Heat Capacity"}', 4),
  (2025, 501, 'Calculate the energy required to heat 0.5 kg of a substance with specific heat capacity 800 J/(kg·K) by 20 K.', 'text', 1, 'Use Q = mcΔT.', '{"why":"The energy required is 8,000 J.","sol":"Step 1: Q = 0.5 × 800 × 20.\nStep 2: Q = 8,000 J.","steps":["Step 1: Q = 0.5 × 800 × 20.","Step 2: Q = 8,000 J."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_specific_heat_capacity","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q1","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Specific Heat Capacity"}', 0),
  (2026, 501, 'A 2 kg object absorbs 12,000 J and its temperature rises by 10 K. Calculate its specific heat capacity.', 'text', 1, 'Rearrange Q = mcΔT.', '{"why":"12,000 ÷ 20 = 600 J/(kg·K).","sol":"Step 1: c = 12,000/(2 × 10).\nStep 2: c = 12,000/20.\nStep 3: c = 600 J/(kg·K).","steps":["Step 1: c = 12,000/(2 × 10).","Step 2: c = 12,000/20.","Step 3: c = 600 J/(kg·K)."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_specific_heat_capacity","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q2","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Specific Heat Capacity"}', 1),
  (2027, 501, 'How much energy is needed to raise 3 kg of a substance with c = 500 J/(kg·K) by 4 K?', 'text', 1, 'Multiply mass, specific heat capacity and temperature change.', '{"why":"3 × 500 × 4 = 6,000 J.","sol":"Step 1: Q = 3 × 500 × 4.\nStep 2: Q = 6,000 J.","steps":["Step 1: Q = 3 × 500 × 4.","Step 2: Q = 6,000 J."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_specific_heat_capacity","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q3","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Specific Heat Capacity"}', 2),
  (2028, 501, 'A 1.5 kg sample receives 18,000 J. Its specific heat capacity is 600 J/(kg·K). Find its temperature rise.', 'text', 1, 'Rearrange the equation to make ΔT the subject.', '{"why":"18,000 ÷ 900 = 20 K.","sol":"Step 1: ΔT = 18,000/(1.5 × 600).\nStep 2: ΔT = 18,000/900.\nStep 3: ΔT = 20 K.","steps":["Step 1: ΔT = 18,000/(1.5 × 600).","Step 2: ΔT = 18,000/900.","Step 3: ΔT = 20 K."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_specific_heat_capacity","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q4","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Specific Heat Capacity"}', 3),
  (2029, 501, 'Two equal masses receive the same energy. Material A has a lower specific heat capacity than material B. Which has the larger temperature rise, assuming no change of state or energy losses?', 'text', 1, 'Rearrange Q = mcΔT to compare the temperature changes.', '{"why":"A lower specific heat capacity means less energy is needed per kilogram per degree.","sol":"Step 1: Q and m are equal for both materials.\nStep 2: Temperature rise is inversely proportional to c.\nStep 3: Material A has the lower c, so it has the larger temperature rise.","steps":["Step 1: Q and m are equal for both materials.","Step 2: Temperature rise is inversely proportional to c.","Step 3: Material A has the lower c, so it has the larger temperature rise."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_specific_heat_capacity","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q5","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Specific Heat Capacity"}', 4),
  (2030, 502, 'What is conduction?', 'text', 1, 'Energy moves through a material without bulk movement of the material.', '{"why":"Conduction transfers energy through interactions between particles and, in metals, mobile electrons.","sol":"Step 1: Thermal energy passes through a substance.\nStep 2: The substance does not move as a whole from one place to another.\nStep 3: This transfer is conduction.","steps":["Step 1: Thermal energy passes through a substance.","Step 2: The substance does not move as a whole from one place to another.","Step 3: This transfer is conduction."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_heat_transfer_by_conduction","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q1","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Heat Transfer by Conduction"}', 0),
  (2031, 502, 'Why does a metal spoon become hot when one end is left in hot water?', 'text', 1, 'Think about energy travelling through the metal.', '{"why":"Particles and mobile electrons help transfer thermal energy through the metal.","sol":"Step 1: The end in hot water gains thermal energy.\nStep 2: Energy is transferred through the metal by conduction.\nStep 3: The handle becomes warmer.","steps":["Step 1: The end in hot water gains thermal energy.","Step 2: Energy is transferred through the metal by conduction.","Step 3: The handle becomes warmer."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_heat_transfer_by_conduction","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q2","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Heat Transfer by Conduction"}', 1),
  (2032, 502, 'Why are metal cooking pots usually good at transferring heat?', 'text', 1, 'Consider metals'' thermal conductivity.', '{"why":"Metals transfer thermal energy efficiently, in part because of mobile electrons.","sol":"Step 1: Metals generally conduct thermal energy well.\nStep 2: Energy passes through the pot''s metal body.\nStep 3: The contents can then be heated.","steps":["Step 1: Metals generally conduct thermal energy well.","Step 2: Energy passes through the pot''s metal body.","Step 3: The contents can then be heated."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_heat_transfer_by_conduction","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q3","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Heat Transfer by Conduction"}', 2),
  (2033, 502, 'Why is wood often used for the handle of a cooking utensil?', 'text', 1, 'A handle should reduce heat transfer to the user''s hand.', '{"why":"Insulating materials slow the transfer of thermal energy.","sol":"Step 1: Wood is a relatively poor conductor of heat.\nStep 2: It transfers thermal energy more slowly than many metals.\nStep 3: The handle is less likely to become hot quickly.","steps":["Step 1: Wood is a relatively poor conductor of heat.","Step 2: It transfers thermal energy more slowly than many metals.","Step 3: The handle is less likely to become hot quickly."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_heat_transfer_by_conduction","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q4","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Heat Transfer by Conduction"}', 3),
  (2034, 502, 'What additional mechanism makes metals particularly good thermal conductors compared with many non-metallic solids?', 'text', 1, 'Think about charged particles that can move through a metal.', '{"why":"Mobile electrons provide an efficient additional mechanism for energy transfer in metals.","sol":"Step 1: Metals contain mobile electrons.\nStep 2: These electrons carry energy through the material.\nStep 3: They improve thermal conduction.","steps":["Step 1: Metals contain mobile electrons.","Step 2: These electrons carry energy through the material.","Step 3: They improve thermal conduction."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_heat_transfer_by_conduction","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q5","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Heat Transfer by Conduction"}', 4),
  (2035, 503, 'What is convection?', 'text', 1, 'Identify the type of matter that moves to carry energy.', '{"why":"Convection carries energy as warmer and cooler fluid regions move.","sol":"Step 1: A fluid gains thermal energy.\nStep 2: The fluid moves in bulk.\nStep 3: This movement transfers thermal energy.","steps":["Step 1: A fluid gains thermal energy.","Step 2: The fluid moves in bulk.","Step 3: This movement transfers thermal energy."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_heat_transfer_by_convection","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q1","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Heat Transfer by Convection"}', 0),
  (2036, 503, 'Why does warmer water usually rise above cooler water in a heated container?', 'text', 1, 'Consider how heating affects volume and density.', '{"why":"Density differences in a gravitational field drive the circulation.","sol":"Step 1: The water warms and expands.\nStep 2: Its density decreases relative to the cooler water.\nStep 3: The warmer, less dense water rises under gravity.","steps":["Step 1: The water warms and expands.","Step 2: Its density decreases relative to the cooler water.","Step 3: The warmer, less dense water rises under gravity."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_heat_transfer_by_convection","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q2","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Heat Transfer by Convection"}', 1),
  (2037, 503, 'What is a convection current?', 'text', 1, 'Think about a repeated circulation of warmer and cooler fluid.', '{"why":"Convection currents form when density differences cause fluid to circulate.","sol":"Step 1: Warmer fluid rises.\nStep 2: Cooler fluid moves into the space left behind and may sink.\nStep 3: The fluid circulates in a continuing pattern.","steps":["Step 1: Warmer fluid rises.","Step 2: Cooler fluid moves into the space left behind and may sink.","Step 3: The fluid circulates in a continuing pattern."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_heat_transfer_by_convection","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q3","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Heat Transfer by Convection"}', 2),
  (2038, 503, 'Can convection transfer thermal energy through a solid metal rod by bulk movement of the metal?', 'text', 1, 'Convection requires a fluid.', '{"why":"Convection currents occur in liquids and gases, not within a stationary solid.","sol":"Step 1: A metal rod is a solid.\nStep 2: Convection requires bulk movement of a fluid.\nStep 3: Energy travels through the stationary rod mainly by conduction.","steps":["Step 1: A metal rod is a solid.","Step 2: Convection requires bulk movement of a fluid.","Step 3: Energy travels through the stationary rod mainly by conduction."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_heat_transfer_by_convection","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q4","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Heat Transfer by Convection"}', 3),
  (2039, 503, 'In a room heated by a radiator, why can warm air rise and cooler air move towards the radiator?', 'text', 1, 'Apply the density explanation for air.', '{"why":"Density differences drive the movement of air that carries thermal energy.","sol":"Step 1: Air near the radiator warms and expands.\nStep 2: Its density decreases.\nStep 3: It rises while cooler, denser air moves in to replace it.","steps":["Step 1: Air near the radiator warms and expands.","Step 2: Its density decreases.","Step 3: It rises while cooler, denser air moves in to replace it."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_heat_transfer_by_convection","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q5","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Heat Transfer by Convection"}', 4),
  (2040, 504, 'What is thermal radiation?', 'text', 1, 'It transfers energy through electromagnetic waves.', '{"why":"Radiation can transfer energy through a vacuum.","sol":"Step 1: A warm object emits electromagnetic radiation.\nStep 2: The radiation carries energy away from the object.\nStep 3: No material medium is required.","steps":["Step 1: A warm object emits electromagnetic radiation.","Step 2: The radiation carries energy away from the object.","Step 3: No material medium is required."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_heat_transfer_by_radiation","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q1","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Heat Transfer by Radiation"}', 0),
  (2041, 504, 'How does energy from the Sun travel through space to Earth?', 'text', 1, 'Space is nearly a vacuum.', '{"why":"Electromagnetic radiation can travel without a material medium.","sol":"Step 1: There is no continuous material medium between the Sun and Earth.\nStep 2: Electromagnetic waves can travel through a vacuum.\nStep 3: Solar energy reaches Earth by radiation.","steps":["Step 1: There is no continuous material medium between the Sun and Earth.","Step 2: Electromagnetic waves can travel through a vacuum.","Step 3: Solar energy reaches Earth by radiation."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_heat_transfer_by_radiation","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q2","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Heat Transfer by Radiation"}', 1),
  (2042, 504, 'Which generally emits thermal radiation more effectively: a dull black surface or a shiny polished surface at the same temperature?', 'text', 1, 'Consider the emissive properties of surface finishes.', '{"why":"Dull dark surfaces generally have higher emissivity than shiny polished surfaces.","sol":"Step 1: Dull black surfaces are generally good emitters.\nStep 2: Shiny polished surfaces are generally poorer emitters.\nStep 3: The dull black surface emits more effectively.","steps":["Step 1: Dull black surfaces are generally good emitters.","Step 2: Shiny polished surfaces are generally poorer emitters.","Step 3: The dull black surface emits more effectively."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_heat_transfer_by_radiation","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q3","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Heat Transfer by Radiation"}', 2),
  (2043, 504, 'Why are the outer surfaces of many vacuum flasks shiny?', 'text', 1, 'The flask is designed to reduce heat transfer.', '{"why":"Vacuum flasks use several design features to reduce energy transfer by different mechanisms.","sol":"Step 1: Shiny surfaces reflect much thermal radiation.\nStep 2: They are relatively poor absorbers and emitters.\nStep 3: They reduce radiative heat transfer.","steps":["Step 1: Shiny surfaces reflect much thermal radiation.","Step 2: They are relatively poor absorbers and emitters.","Step 3: They reduce radiative heat transfer."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_heat_transfer_by_radiation","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q4","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Heat Transfer by Radiation"}', 3),
  (2044, 504, 'Do objects at room temperature emit thermal radiation?', 'text', 1, 'Consider whether all objects above absolute zero emit radiation.', '{"why":"Radiation is emitted even when an object is not visibly glowing.","sol":"Step 1: Room-temperature objects are above absolute zero.\nStep 2: Objects above absolute zero emit electromagnetic radiation.\nStep 3: Therefore, room-temperature objects emit thermal radiation.","steps":["Step 1: Room-temperature objects are above absolute zero.","Step 2: Objects above absolute zero emit electromagnetic radiation.","Step 3: Therefore, room-temperature objects emit thermal radiation."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_heat_transfer_by_radiation","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q5","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Heat Transfer by Radiation"}', 4),
  (2045, 505, 'A metal spoon becomes hot along its handle when one end is placed in hot tea. Which is the main transfer mechanism along the solid spoon?', 'text', 1, 'The metal does not flow from one end to the other.', '{"why":"Conduction transfers energy through the metal spoon.","sol":"Step 1: The spoon is a solid.\nStep 2: Thermal energy travels through its material.\nStep 3: The mechanism is conduction.","steps":["Step 1: The spoon is a solid.","Step 2: Thermal energy travels through its material.","Step 3: The mechanism is conduction."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_comparing_conduction_convection_and_radiation","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q1","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Comparing Conduction, Convection and Radiation"}', 0),
  (2046, 505, 'Warm water rises and cooler water sinks in a heated container. Which transfer mechanism is involved?', 'text', 1, 'Look for bulk movement of a fluid.', '{"why":"Convection transfers thermal energy through the movement of fluid.","sol":"Step 1: Water is a liquid.\nStep 2: Different-density regions move.\nStep 3: The circulation transfers energy by convection.","steps":["Step 1: Water is a liquid.","Step 2: Different-density regions move.","Step 3: The circulation transfers energy by convection."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_comparing_conduction_convection_and_radiation","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q2","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Comparing Conduction, Convection and Radiation"}', 1),
  (2047, 505, 'Which mechanism allows thermal energy from the Sun to cross the vacuum of space?', 'text', 1, 'Which method does not require a material medium?', '{"why":"Thermal radiation does not require a material medium.","sol":"Step 1: Space is nearly a vacuum.\nStep 2: Radiation travels as electromagnetic waves.\nStep 3: Solar energy reaches Earth by radiation.","steps":["Step 1: Space is nearly a vacuum.","Step 2: Radiation travels as electromagnetic waves.","Step 3: Solar energy reaches Earth by radiation."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_comparing_conduction_convection_and_radiation","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q3","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Comparing Conduction, Convection and Radiation"}', 2),
  (2048, 505, 'A pot of water is heated on a stove. Name the main mechanism transferring energy through the metal base and the mechanism circulating energy through the water.', 'text', 1, 'Distinguish transfer through a solid from movement within a liquid.', '{"why":"Different parts of the same heating system can transfer energy by different mechanisms.","sol":"Step 1: Energy travels through the metal base by conduction.\nStep 2: Water near the base warms and moves.\nStep 3: Energy circulates through the water by convection.","steps":["Step 1: Energy travels through the metal base by conduction.","Step 2: Water near the base warms and moves.","Step 3: Energy circulates through the water by convection."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_comparing_conduction_convection_and_radiation","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q4","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Comparing Conduction, Convection and Radiation"}', 3),
  (2049, 505, 'Which statement correctly distinguishes radiation from conduction and convection?', 'text', 1, 'Focus on whether a material medium is necessary.', '{"why":"A vacuum is not required for radiation, but it can pass through one.","sol":"Step 1: Conduction occurs through matter.\nStep 2: Convection involves bulk movement of a fluid.\nStep 3: Radiation can travel through a vacuum.","steps":["Step 1: Conduction occurs through matter.","Step 2: Convection involves bulk movement of a fluid.","Step 3: Radiation can travel through a vacuum."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_comparing_conduction_convection_and_radiation","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q5","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Comparing Conduction, Convection and Radiation"}', 4),
  (2050, 506, 'What is melting?', 'text', 1, 'Identify the change from a solid.', '{"why":"Melting changes a solid into a liquid.","sol":"Step 1: The substance starts as a solid.\nStep 2: It absorbs energy under suitable conditions.\nStep 3: It changes into a liquid.","steps":["Step 1: The substance starts as a solid.","Step 2: It absorbs energy under suitable conditions.","Step 3: It changes into a liquid."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_change_of_state","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q1","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Change of State"}', 0),
  (2051, 506, 'What is condensation?', 'text', 1, 'Think about water droplets forming from water vapour.', '{"why":"Condensation forms a liquid from a gas.","sol":"Step 1: A substance starts as a gas.\nStep 2: It loses energy under suitable conditions.\nStep 3: It changes into a liquid.","steps":["Step 1: A substance starts as a gas.","Step 2: It loses energy under suitable conditions.","Step 3: It changes into a liquid."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_change_of_state","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q2","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Change of State"}', 1),
  (2052, 506, 'What is the difference between boiling and evaporation?', 'text', 1, 'Consider where the process occurs and the temperature condition.', '{"why":"Evaporation and boiling are different processes by which a liquid becomes a gas.","sol":"Step 1: Evaporation occurs at the surface and can occur below the boiling point.\nStep 2: Boiling occurs throughout the liquid when it reaches its boiling point for the given pressure.","steps":["Step 1: Evaporation occurs at the surface and can occur below the boiling point.","Step 2: Boiling occurs throughout the liquid when it reaches its boiling point for the given pressure."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_change_of_state","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q3","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Change of State"}', 2),
  (2053, 506, 'What is sublimation?', 'text', 1, 'The substance skips the liquid state.', '{"why":"Sublimation bypasses the liquid state.","sol":"Step 1: The substance begins as a solid.\nStep 2: It changes directly into a gas.\nStep 3: This process is sublimation.","steps":["Step 1: The substance begins as a solid.","Step 2: It changes directly into a gas.","Step 3: This process is sublimation."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_change_of_state","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q4","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Change of State"}', 3),
  (2054, 506, 'During the melting of a pure substance at fixed pressure, why can its temperature remain constant even though energy is supplied?', 'text', 1, 'Consider what the supplied energy does during the phase change.', '{"why":"During melting, energy changes the substance''s internal arrangement while temperature remains constant until melting is complete.","sol":"Step 1: The substance is changing state.\nStep 2: The supplied energy changes particle arrangement and separation.\nStep 3: It does not raise the temperature during the phase-change stage.","steps":["Step 1: The substance is changing state.","Step 2: The supplied energy changes particle arrangement and separation.","Step 3: It does not raise the temperature during the phase-change stage."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_change_of_state","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q5","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Change of State"}', 4),
  (2055, 507, 'What is latent heat?', 'text', 1, 'Think about energy transfer during a change of state.', '{"why":"Latent energy changes the state of a substance rather than its temperature during the phase change.","sol":"Step 1: A substance undergoes a change of state.\nStep 2: Energy is transferred to or from it.\nStep 3: During the phase change, its temperature remains constant under the stated conditions.","steps":["Step 1: A substance undergoes a change of state.","Step 2: Energy is transferred to or from it.","Step 3: During the phase change, its temperature remains constant under the stated conditions."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_latent_heat","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q1","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Latent Heat"}', 0),
  (2056, 507, 'Ice melts at its melting point while energy continues to be supplied. Why does its temperature remain constant during melting?', 'text', 1, 'Consider what the energy is doing to the particles.', '{"why":"During melting, energy changes the substance''s internal arrangement.","sol":"Step 1: The ice is changing from solid to liquid.\nStep 2: Energy helps change the particles'' arrangement and overcome attractive forces.\nStep 3: The temperature remains constant until melting is complete, for a pure substance at fixed pressure.","steps":["Step 1: The ice is changing from solid to liquid.","Step 2: Energy helps change the particles'' arrangement and overcome attractive forces.","Step 3: The temperature remains constant until melting is complete, for a pure substance at fixed pressure."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_latent_heat","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q2","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Latent Heat"}', 1),
  (2057, 507, 'What happens to energy when water freezes at its freezing point?', 'text', 1, 'Compare freezing with melting.', '{"why":"During freezing, the substance releases energy associated with the change of state.","sol":"Step 1: Liquid water changes into a solid.\nStep 2: Particles form a more ordered structure.\nStep 3: Energy is released to the surroundings during freezing.","steps":["Step 1: Liquid water changes into a solid.","Step 2: Particles form a more ordered structure.","Step 3: Energy is released to the surroundings during freezing."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_latent_heat","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q3","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Latent Heat"}', 2),
  (2058, 507, 'Explain the difference between sensible heating and latent heating.', 'text', 1, 'Compare what happens to temperature and state.', '{"why":"The two terms distinguish temperature change from energy transfer during a phase change.","sol":"Step 1: Sensible heating changes a substance''s temperature without a change of state.\nStep 2: Latent heating transfers energy during a change of state.\nStep 3: During the phase change, the temperature remains constant under the stated conditions.","steps":["Step 1: Sensible heating changes a substance''s temperature without a change of state.","Step 2: Latent heating transfers energy during a change of state.","Step 3: During the phase change, the temperature remains constant under the stated conditions."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_latent_heat","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q4","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Latent Heat"}', 3),
  (2059, 507, 'A pure substance is boiling at a fixed pressure. What happens to its temperature while liquid and vapour coexist during boiling?', 'text', 1, 'Think about the temperature behaviour during a phase change.', '{"why":"Energy supplied during the phase change is used for vaporisation.","sol":"Step 1: The liquid is changing into gas.\nStep 2: Energy supplied supports vaporisation.\nStep 3: The temperature remains constant during the boiling stage at fixed pressure.","steps":["Step 1: The liquid is changing into gas.","Step 2: Energy supplied supports vaporisation.","Step 3: The temperature remains constant during the boiling stage at fixed pressure."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_latent_heat","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q5","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Latent Heat"}', 4),
  (2060, 508, 'Define specific latent heat.', 'text', 1, 'Include energy, unit mass and no temperature change.', '{"why":"Specific latent heat measures energy per kilogram for a particular change of state.","sol":"Step 1: Consider 1 kg of a substance.\nStep 2: Change its state without changing its temperature.\nStep 3: The required energy is its specific latent heat for that change.","steps":["Step 1: Consider 1 kg of a substance.","Step 2: Change its state without changing its temperature.","Step 3: The required energy is its specific latent heat for that change."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_specific_latent_heat","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q1","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Specific Latent Heat"}', 0),
  (2061, 508, 'Calculate the energy needed to change the state of 2 kg of a substance with specific latent heat 150,000 J/kg.', 'text', 1, 'Use Q = mL.', '{"why":"The energy required is 300,000 J.","sol":"Step 1: Q = 2 × 150,000.\nStep 2: Q = 300,000 J.","steps":["Step 1: Q = 2 × 150,000.","Step 2: Q = 300,000 J."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_specific_latent_heat","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q2","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Specific Latent Heat"}', 1),
  (2062, 508, 'A 0.25 kg sample requires 50,000 J for a change of state. Calculate its specific latent heat.', 'text', 1, 'Rearrange Q = mL to make L the subject.', '{"why":"50,000 ÷ 0.25 = 200,000 J/kg.","sol":"Step 1: L = 50,000/0.25.\nStep 2: L = 200,000 J/kg.","steps":["Step 1: L = 50,000/0.25.","Step 2: L = 200,000 J/kg."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_specific_latent_heat","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q3","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Specific Latent Heat"}', 2),
  (2063, 508, 'A material has specific latent heat 80,000 J/kg. How much energy is required to change the state of 0.75 kg?', 'text', 1, 'Multiply the mass by the specific latent heat.', '{"why":"The energy required is 60,000 J.","sol":"Step 1: Q = 0.75 × 80,000.\nStep 2: Q = 60,000 J.","steps":["Step 1: Q = 0.75 × 80,000.","Step 2: Q = 60,000 J."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_specific_latent_heat","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q4","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Specific Latent Heat"}', 3),
  (2064, 508, 'What is the SI unit of specific latent heat?', 'text', 1, 'Specific latent heat is energy divided by mass.', '{"why":"Specific latent heat measures the energy required per kilogram for a phase change.","sol":"Step 1: Energy is measured in joules.\nStep 2: Mass is measured in kilograms.\nStep 3: The unit is joules per kilogram.","steps":["Step 1: Energy is measured in joules.","Step 2: Mass is measured in kilograms.","Step 3: The unit is joules per kilogram."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_specific_latent_heat","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q5","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Specific Latent Heat"}', 4),
  (2065, 509, 'What does the specific latent heat of fusion describe?', 'text', 1, 'Fusion refers to melting.', '{"why":"Specific latent heat of fusion concerns the solid-to-liquid change of state.","sol":"Step 1: Start with 1 kg of solid at its melting point.\nStep 2: Change it into liquid without a temperature change.\nStep 3: Measure the required energy.","steps":["Step 1: Start with 1 kg of solid at its melting point.","Step 2: Change it into liquid without a temperature change.","Step 3: Measure the required energy."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_specific_latent_heat_of_fusion","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q1","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Specific Latent Heat of Fusion"}', 0),
  (2066, 509, 'Calculate the energy needed to melt 0.5 kg of ice at 0°C. Use Lᶠ = 334,000 J/kg.', 'text', 1, 'The ice is already at its melting point, so use Q = mLᶠ.', '{"why":"Half a kilogram of ice requires 167,000 J to melt at 0°C using the stated value.","sol":"Step 1: Q = 0.5 × 334,000.\nStep 2: Q = 167,000 J.","steps":["Step 1: Q = 0.5 × 334,000.","Step 2: Q = 167,000 J."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_specific_latent_heat_of_fusion","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q2","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Specific Latent Heat of Fusion"}', 1),
  (2067, 509, 'How much ice at 0°C can be melted by 66,800 J? Use Lᶠ = 334,000 J/kg.', 'text', 1, 'Rearrange Q = mLᶠ to make mass the subject.', '{"why":"66,800 ÷ 334,000 = 0.2 kg.","sol":"Step 1: m = 66,800/334,000.\nStep 2: m = 0.2 kg.","steps":["Step 1: m = 66,800/334,000.","Step 2: m = 0.2 kg."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_specific_latent_heat_of_fusion","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q3","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Specific Latent Heat of Fusion"}', 2),
  (2068, 509, 'How much energy is released when 0.3 kg of water freezes at its freezing point? Use Lᶠ = 334,000 J/kg.', 'text', 1, 'The magnitude of the energy per kilogram is the same for freezing and melting.', '{"why":"Freezing releases 100,200 J under the stated conditions.","sol":"Step 1: Q = 0.3 × 334,000.\nStep 2: Q = 100,200 J.\nStep 3: This energy is released to the surroundings.","steps":["Step 1: Q = 0.3 × 334,000.","Step 2: Q = 100,200 J.","Step 3: This energy is released to the surroundings."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_specific_latent_heat_of_fusion","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q4","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Specific Latent Heat of Fusion"}', 3),
  (2069, 509, 'Ice starts at −10°C and must become water at 0°C. Is Q = mLᶠ alone enough to calculate all the energy needed?', 'text', 1, 'Before melting, the ice must reach its melting point.', '{"why":"A complete calculation includes both sensible heating and the latent heat of fusion.","sol":"Step 1: The ice first warms from −10°C to 0°C.\nStep 2: That requires sensible heat, Q₁ = mcΔT.\nStep 3: Melting then requires latent heat, Q₂ = mLᶠ.\nStep 4: Total energy is Q₁ + Q₂.","steps":["Step 1: The ice first warms from −10°C to 0°C.","Step 2: That requires sensible heat, Q₁ = mcΔT.","Step 3: Melting then requires latent heat, Q₂ = mLᶠ.","Step 4: Total energy is Q₁ + Q₂."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_specific_latent_heat_of_fusion","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q5","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Specific Latent Heat of Fusion"}', 4),
  (2070, 510, 'Define specific latent heat of vaporisation.', 'text', 1, 'Think about changing liquid into gas at the boiling point.', '{"why":"Specific latent heat of vaporisation concerns the liquid-to-gas phase change.","sol":"Step 1: Start with 1 kg of liquid at its boiling point.\nStep 2: Change it into gas without changing temperature.\nStep 3: Measure the energy required.","steps":["Step 1: Start with 1 kg of liquid at its boiling point.","Step 2: Change it into gas without changing temperature.","Step 3: Measure the energy required."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_specific_latent_heat_of_vaporisation","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q1","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Specific Latent Heat of Vaporisation"}', 0),
  (2071, 510, 'Calculate the energy required to vaporise 0.2 kg of water at 100°C. Use Lᵥ = 2.26 × 10⁶ J/kg.', 'text', 1, 'Use Q = mLᵥ.', '{"why":"0.2 kg of water requires 452,000 J to vaporise at the stated conditions.","sol":"Step 1: Q = 0.2 × 2.26 × 10⁶.\nStep 2: Q = 0.452 × 10⁶ J.\nStep 3: Q = 452,000 J.","steps":["Step 1: Q = 0.2 × 2.26 × 10⁶.","Step 2: Q = 0.452 × 10⁶ J.","Step 3: Q = 452,000 J."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_specific_latent_heat_of_vaporisation","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q2","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Specific Latent Heat of Vaporisation"}', 1),
  (2072, 510, 'A sample needs 678,000 J to vaporise completely at its boiling point. If Lᵥ = 2.26 × 10⁶ J/kg, calculate its mass.', 'text', 1, 'Divide energy by specific latent heat.', '{"why":"678,000 ÷ 2,260,000 = 0.3 kg.","sol":"Step 1: m = 678,000/(2.26 × 10⁶).\nStep 2: m = 0.3 kg.","steps":["Step 1: m = 678,000/(2.26 × 10⁶).","Step 2: m = 0.3 kg."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_specific_latent_heat_of_vaporisation","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q3","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Specific Latent Heat of Vaporisation"}', 2),
  (2073, 510, 'What energy is released when 0.05 kg of steam condenses at the corresponding saturation temperature? Use Lᵥ = 2.26 × 10⁶ J/kg.', 'text', 1, 'Condensation releases the same magnitude of latent energy per kilogram.', '{"why":"Condensing 0.05 kg of steam releases 113,000 J under the stated conditions.","sol":"Step 1: Q = 0.05 × 2.26 × 10⁶.\nStep 2: Q = 113,000 J.\nStep 3: The energy is released to the surroundings.","steps":["Step 1: Q = 0.05 × 2.26 × 10⁶.","Step 2: Q = 113,000 J.","Step 3: The energy is released to the surroundings."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_specific_latent_heat_of_vaporisation","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q4","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Specific Latent Heat of Vaporisation"}', 3),
  (2074, 510, 'Why can steam at 100°C cause more severe burns than water at 100°C when comparable amounts contact the skin?', 'text', 1, 'Consider the energy released when steam condenses.', '{"why":"Condensation can release substantial latent energy in addition to energy transferred as the steam cools.","sol":"Step 1: Steam can condense on cooler skin.\nStep 2: Condensation releases latent heat.\nStep 3: That additional energy can transfer to the skin.","steps":["Step 1: Steam can condense on cooler skin.","Step 2: Condensation releases latent heat.","Step 3: That additional energy can transfer to the skin."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_specific_latent_heat_of_vaporisation","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q5","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Specific Latent Heat of Vaporisation"}', 4),
  (2075, 511, 'On a heating curve for a pure substance at constant pressure, what does a sloping section generally indicate?', 'text', 1, 'Look for a section where temperature changes.', '{"why":"Sloping sections show temperature changes within a state.","sol":"Step 1: The substance remains in one state during the section.\nStep 2: Energy supplied changes its temperature.\nStep 3: The graph slopes upward.","steps":["Step 1: The substance remains in one state during the section.","Step 2: Energy supplied changes its temperature.","Step 3: The graph slopes upward."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_heating_curves","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q1","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Heating Curves"}', 0),
  (2076, 511, 'What does a flat section of a heating curve represent for a pure substance at constant pressure?', 'text', 1, 'The temperature is not rising despite energy input.', '{"why":"The supplied energy changes the state rather than raising the temperature during the plateau.","sol":"Step 1: Energy continues to be supplied.\nStep 2: The temperature remains constant.\nStep 3: The substance is undergoing a change of state.","steps":["Step 1: Energy continues to be supplied.","Step 2: The temperature remains constant.","Step 3: The substance is undergoing a change of state."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_heating_curves","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q2","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Heating Curves"}', 1),
  (2077, 511, 'Ice at −10°C is heated at normal atmospheric pressure. What is the first change shown on a typical heating curve?', 'text', 1, 'The ice starts below its melting point.', '{"why":"The ice must reach its melting point before melting begins under these conditions.","sol":"Step 1: The sample begins as solid ice at −10°C.\nStep 2: Energy raises the ice''s temperature.\nStep 3: The temperature rises towards 0°C before melting begins.","steps":["Step 1: The sample begins as solid ice at −10°C.","Step 2: Energy raises the ice''s temperature.","Step 3: The temperature rises towards 0°C before melting begins."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_heating_curves","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q3","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Heating Curves"}', 2),
  (2078, 511, 'On a typical heating curve for water at normal atmospheric pressure, what happens after the liquid water has warmed to 100°C and boiling begins?', 'text', 1, 'Consider the boiling plateau.', '{"why":"Energy supplied during boiling provides latent heat of vaporisation.","sol":"Step 1: Water reaches its boiling point.\nStep 2: Liquid changes into steam.\nStep 3: Temperature remains approximately 100°C while boiling continues.","steps":["Step 1: Water reaches its boiling point.","Step 2: Liquid changes into steam.","Step 3: Temperature remains approximately 100°C while boiling continues."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_heating_curves","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q4","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Heating Curves"}', 3),
  (2079, 511, 'Two heating curves show flat sections at the same phase-change temperature, but one plateau lasts longer when both samples receive energy at the same constant rate. What can the longer plateau indicate?', 'text', 1, 'At a constant input rate, a longer time means more energy supplied.', '{"why":"At constant power, plateau duration reflects the energy needed for the phase change.","sol":"Step 1: Energy supplied equals power multiplied by time.\nStep 2: A longer plateau at the same power means more energy is supplied during the phase change.\nStep 3: This can indicate a larger sample mass or a larger total latent-energy requirement.","steps":["Step 1: Energy supplied equals power multiplied by time.","Step 2: A longer plateau at the same power means more energy is supplied during the phase change.","Step 3: This can indicate a larger sample mass or a larger total latent-energy requirement."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_heating_curves","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q5","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Heating Curves"}', 4),
  (2080, 512, 'What does a downward-sloping section of a cooling curve generally show?', 'text', 1, 'Check how temperature changes with time.', '{"why":"Sloping sections indicate a temperature decrease.","sol":"Step 1: The substance is losing energy.\nStep 2: Its temperature falls.\nStep 3: It is cooling within one state.","steps":["Step 1: The substance is losing energy.","Step 2: Its temperature falls.","Step 3: It is cooling within one state."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_cooling_curves","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q1","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Cooling Curves"}', 0),
  (2081, 512, 'Why can a pure substance''s cooling curve become flat while the substance freezes?', 'text', 1, 'Consider the energy released during freezing.', '{"why":"Energy leaves the substance as latent heat during the phase change.","sol":"Step 1: The substance reaches its freezing point.\nStep 2: It releases latent heat as liquid becomes solid.\nStep 3: Its temperature stays constant until freezing is complete under the stated conditions.","steps":["Step 1: The substance reaches its freezing point.","Step 2: It releases latent heat as liquid becomes solid.","Step 3: Its temperature stays constant until freezing is complete under the stated conditions."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_cooling_curves","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q2","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Cooling Curves"}', 1),
  (2082, 512, 'Steam condenses to liquid water at its saturation temperature. Is latent heat absorbed or released by the steam?', 'text', 1, 'Condensation is the reverse of vaporisation.', '{"why":"Condensation releases latent energy.","sol":"Step 1: Gas changes to liquid.\nStep 2: Particles form a more condensed state.\nStep 3: Energy is released to the surroundings.","steps":["Step 1: Gas changes to liquid.","Step 2: Particles form a more condensed state.","Step 3: Energy is released to the surroundings."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_cooling_curves","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q3","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Cooling Curves"}', 2),
  (2083, 512, 'A sample has finished freezing and continues to lose energy. What generally happens to its temperature next?', 'text', 1, 'The phase change is complete.', '{"why":"Once freezing is complete, further cooling reduces the solid''s temperature.","sol":"Step 1: The sample is now entirely solid.\nStep 2: Further energy loss cools the solid.\nStep 3: Its temperature falls.","steps":["Step 1: The sample is now entirely solid.","Step 2: Further energy loss cools the solid.","Step 3: Its temperature falls."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_cooling_curves","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q4","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Cooling Curves"}', 3),
  (2084, 512, 'Two equal masses of the same pure substance freeze under the same pressure. If one releases more total latent energy, what should you check first?', 'text', 1, 'Use the relationship between energy, mass and specific latent heat.', '{"why":"For a given phase change, Q = mL determines the energy released.","sol":"Step 1: For the same substance and phase change, L is the same.\nStep 2: For complete freezing, Q is proportional to m.\nStep 3: Check whether the masses or the amount that actually froze are different.","steps":["Step 1: For the same substance and phase change, L is the same.","Step 2: For complete freezing, Q is proportional to m.","Step 3: Check whether the masses or the amount that actually froze are different."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_cooling_curves","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q5","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Cooling Curves"}', 4),
  (2085, 513, 'What is evaporation?', 'text', 1, 'It occurs at the surface of a liquid.', '{"why":"Evaporation occurs at the surface across a range of temperatures.","sol":"Step 1: Some surface particles gain or already have enough energy.\nStep 2: They escape from the liquid into the gas state.\nStep 3: This is evaporation.","steps":["Step 1: Some surface particles gain or already have enough energy.","Step 2: They escape from the liquid into the gas state.","Step 3: This is evaporation."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_evaporation","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q1","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Evaporation"}', 0),
  (2086, 513, 'Why can evaporation cool the liquid that remains?', 'text', 1, 'What happens to energy when the faster, higher-energy particles escape?', '{"why":"Evaporation can remove energy from the remaining liquid.","sol":"Step 1: Some higher-energy particles escape from the surface.\nStep 2: They carry energy away.\nStep 3: The remaining liquid has lower average particle kinetic energy if energy is not replaced, so its temperature can fall.","steps":["Step 1: Some higher-energy particles escape from the surface.","Step 2: They carry energy away.","Step 3: The remaining liquid has lower average particle kinetic energy if energy is not replaced, so its temperature can fall."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_evaporation","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q2","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Evaporation"}', 1),
  (2087, 513, 'Why can sweat help cool a person on a warm day?', 'text', 1, 'Consider the energy needed for water to evaporate.', '{"why":"The latent heat needed for evaporation can be drawn from the skin.","sol":"Step 1: Sweat is liquid water on the skin.\nStep 2: Evaporation requires energy.\nStep 3: Energy is taken from the skin and nearby surroundings, producing cooling.","steps":["Step 1: Sweat is liquid water on the skin.","Step 2: Evaporation requires energy.","Step 3: Energy is taken from the skin and nearby surroundings, producing cooling."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_evaporation","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q3","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Evaporation"}', 2),
  (2088, 513, 'A puddle dries on a day when the air temperature is below the boiling point of water. How is this possible?', 'text', 1, 'Does evaporation require boiling?', '{"why":"Surface evaporation occurs at temperatures below boiling.","sol":"Step 1: Evaporation occurs at the liquid surface.\nStep 2: Some water molecules escape into the air below the boiling point.\nStep 3: Over time, enough water evaporates for the puddle to dry.","steps":["Step 1: Evaporation occurs at the liquid surface.","Step 2: Some water molecules escape into the air below the boiling point.","Step 3: Over time, enough water evaporates for the puddle to dry."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_evaporation","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q4","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Evaporation"}', 3),
  (2089, 513, 'How does evaporation differ from boiling?', 'text', 1, 'Compare where each process occurs and its temperature condition.', '{"why":"The processes differ in where they occur and the conditions required.","sol":"Step 1: Evaporation occurs at the surface and can occur below the boiling point.\nStep 2: Boiling occurs throughout the liquid at the boiling point for a given pressure.","steps":["Step 1: Evaporation occurs at the surface and can occur below the boiling point.","Step 2: Boiling occurs throughout the liquid at the boiling point for a given pressure."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_evaporation","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q5","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Evaporation"}', 4),
  (2090, 514, 'Why does water generally evaporate faster at a higher temperature?', 'text', 1, 'Consider the energy distribution of liquid particles.', '{"why":"Higher temperature generally increases the rate of evaporation.","sol":"Step 1: Heating increases the particles'' average kinetic energy.\nStep 2: A greater fraction can escape from the surface.\nStep 3: The evaporation rate generally increases.","steps":["Step 1: Heating increases the particles'' average kinetic energy.","Step 2: A greater fraction can escape from the surface.","Step 3: The evaporation rate generally increases."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_factors_affecting_evaporation","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q1","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Factors Affecting Evaporation"}', 0),
  (2091, 514, 'Why does the same amount of water usually evaporate faster from a wide shallow tray than from a narrow deep container?', 'text', 1, 'Compare the exposed liquid surface areas.', '{"why":"A larger exposed surface generally increases evaporation rate.","sol":"Step 1: The tray exposes a larger liquid surface.\nStep 2: More particles can escape at the same time.\nStep 3: The evaporation rate generally increases.","steps":["Step 1: The tray exposes a larger liquid surface.","Step 2: More particles can escape at the same time.","Step 3: The evaporation rate generally increases."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_factors_affecting_evaporation","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q2","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Factors Affecting Evaporation"}', 1),
  (2092, 514, 'How does moving air over a wet surface generally affect evaporation?', 'text', 1, 'Think about what happens to water vapour near the surface.', '{"why":"Air movement often reduces the build-up of vapour immediately above the liquid.","sol":"Step 1: Evaporated water vapour accumulates near a still surface.\nStep 2: Moving air carries some vapour away.\nStep 3: Evaporation can continue more rapidly.","steps":["Step 1: Evaporated water vapour accumulates near a still surface.","Step 2: Moving air carries some vapour away.","Step 3: Evaporation can continue more rapidly."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_factors_affecting_evaporation","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q3","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Factors Affecting Evaporation"}', 2),
  (2093, 514, 'Why do wet clothes often dry more slowly on a humid day?', 'text', 1, 'Compare the amount of water vapour already in the air.', '{"why":"When the surrounding air is humid, it generally accepts additional water vapour less readily.","sol":"Step 1: Humid air already contains a high amount of water vapour relative to its capacity.\nStep 2: The difference that drives evaporation is smaller.\nStep 3: Water generally evaporates more slowly.","steps":["Step 1: Humid air already contains a high amount of water vapour relative to its capacity.","Step 2: The difference that drives evaporation is smaller.","Step 3: Water generally evaporates more slowly."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_factors_affecting_evaporation","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q4","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Factors Affecting Evaporation"}', 3),
  (2094, 514, 'A student wants to test how surface area affects evaporation. Which procedure gives the fairest comparison?', 'text', 1, 'Change only the variable being tested.', '{"why":"Controlling other variables helps isolate the effect of surface area.","sol":"Step 1: Use equal amounts of the same liquid.\nStep 2: Place them in containers with different exposed surface areas.\nStep 3: Keep temperature, airflow and humidity as similar as possible.\nStep 4: Measure the amount evaporated over the same time.","steps":["Step 1: Use equal amounts of the same liquid.","Step 2: Place them in containers with different exposed surface areas.","Step 3: Keep temperature, airflow and humidity as similar as possible.","Step 4: Measure the amount evaporated over the same time."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_factors_affecting_evaporation","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q5","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Factors Affecting Evaporation"}', 4),
  (2095, 515, 'What condition must be met for a liquid to boil?', 'text', 1, 'Compare vapour pressure with the pressure surrounding the liquid.', '{"why":"Boiling involves vapour bubbles forming within the liquid as well as at its surface.","sol":"Step 1: The liquid has a vapour pressure at its current temperature.\nStep 2: Boiling can occur when that vapour pressure reaches the external pressure.\nStep 3: Vapour bubbles can then form throughout the liquid.","steps":["Step 1: The liquid has a vapour pressure at its current temperature.","Step 2: Boiling can occur when that vapour pressure reaches the external pressure.","Step 3: Vapour bubbles can then form throughout the liquid."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_boiling_point_and_pressure","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q1","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Boiling Point and Pressure"}', 0),
  (2096, 515, 'Why does water boil at a temperature below 100°C at high altitude?', 'text', 1, 'Atmospheric pressure is lower at high altitude.', '{"why":"A lower external pressure lowers water''s boiling point.","sol":"Step 1: External atmospheric pressure is lower.\nStep 2: The water''s vapour pressure reaches that lower pressure at a lower temperature.\nStep 3: The boiling point decreases.","steps":["Step 1: External atmospheric pressure is lower.","Step 2: The water''s vapour pressure reaches that lower pressure at a lower temperature.","Step 3: The boiling point decreases."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_boiling_point_and_pressure","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q2","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Boiling Point and Pressure"}', 1),
  (2097, 515, 'Why can food cook at a higher temperature in a pressure cooker?', 'text', 1, 'Consider how the cooker changes the pressure above the water.', '{"why":"The raised boiling point allows a higher cooking temperature.","sol":"Step 1: The cooker increases the pressure inside.\nStep 2: Water''s boiling point rises with pressure.\nStep 3: Water and steam can become hotter than 100°C under suitable conditions.","steps":["Step 1: The cooker increases the pressure inside.","Step 2: Water''s boiling point rises with pressure.","Step 3: Water and steam can become hotter than 100°C under suitable conditions."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_boiling_point_and_pressure","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q3","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Boiling Point and Pressure"}', 2),
  (2098, 515, 'At standard atmospheric pressure, what is the approximate normal boiling point of pure water?', 'text', 1, 'Recall the usual school reference value.', '{"why":"Water''s normal boiling point is approximately 100°C at standard atmospheric pressure.","sol":"Step 1: Identify the standard atmospheric pressure condition.\nStep 2: The normal boiling point of water is approximately 100°C.","steps":["Step 1: Identify the standard atmospheric pressure condition.","Step 2: The normal boiling point of water is approximately 100°C."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_boiling_point_and_pressure","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q4","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Boiling Point and Pressure"}', 3),
  (2099, 515, 'Two identical open containers hold water at the same temperature. One is at a lower external pressure. Which water sample generally has the lower boiling point?', 'text', 1, 'Use the relationship between external pressure and boiling point.', '{"why":"Lower external pressure generally lowers a liquid''s boiling point.","sol":"Step 1: Boiling occurs when vapour pressure reaches external pressure.\nStep 2: The lower-pressure sample reaches that condition at a lower temperature.\nStep 3: Its boiling point is lower.","steps":["Step 1: Boiling occurs when vapour pressure reaches external pressure.","Step 2: The lower-pressure sample reaches that condition at a lower temperature.","Step 3: Its boiling point is lower."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_boiling_point_and_pressure","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q5","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Boiling Point and Pressure"}', 4),
  (2100, 516, 'What is the purpose of thermal insulation?', 'text', 1, 'Think about the rate of energy transfer between an object and its surroundings.', '{"why":"Thermal insulation slows energy transfer.","sol":"Step 1: Thermal energy tends to transfer when there is a temperature difference.\nStep 2: Insulating materials or designs reduce one or more transfer mechanisms.\nStep 3: Energy transfer occurs more slowly.","steps":["Step 1: Thermal energy tends to transfer when there is a temperature difference.","Step 2: Insulating materials or designs reduce one or more transfer mechanisms.","Step 3: Energy transfer occurs more slowly."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_thermal_insulation","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q1","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Thermal Insulation"}', 0),
  (2101, 516, 'Why is trapped air useful in many insulating materials?', 'text', 1, 'Compare still air with a metal conductor.', '{"why":"Insulation works well when it reduces both conduction and fluid movement.","sol":"Step 1: Air is a poor thermal conductor compared with metals.\nStep 2: Small trapped spaces restrict bulk movement of air.\nStep 3: Conduction and convection are reduced.","steps":["Step 1: Air is a poor thermal conductor compared with metals.","Step 2: Small trapped spaces restrict bulk movement of air.","Step 3: Conduction and convection are reduced."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_thermal_insulation","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q2","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Thermal Insulation"}', 1),
  (2102, 516, 'How do shiny surfaces help reduce thermal energy transfer in a vacuum flask?', 'text', 1, 'Consider how they interact with infrared radiation.', '{"why":"Vacuum flasks combine different features to reduce different transfer mechanisms.","sol":"Step 1: Shiny surfaces reflect much incident thermal radiation.\nStep 2: They are relatively poor absorbers and emitters.\nStep 3: Radiative heat transfer is reduced.","steps":["Step 1: Shiny surfaces reflect much incident thermal radiation.","Step 2: They are relatively poor absorbers and emitters.","Step 3: Radiative heat transfer is reduced."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_thermal_insulation","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q3","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Thermal Insulation"}', 2),
  (2103, 516, 'Why does a vacuum between the walls of a vacuum flask reduce heat transfer?', 'text', 1, 'Which transfer mechanisms require matter?', '{"why":"Radiation does not require a material medium, but conduction and convection depend on matter.","sol":"Step 1: A vacuum contains very little matter.\nStep 2: Conduction through the gap is greatly reduced.\nStep 3: Convection cannot occur across the gap without a fluid.","steps":["Step 1: A vacuum contains very little matter.","Step 2: Conduction through the gap is greatly reduced.","Step 3: Convection cannot occur across the gap without a fluid."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_thermal_insulation","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q4","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Thermal Insulation"}', 3),
  (2104, 516, 'A flask keeps hot tea warm for longer. Does this mean the flask produces heat?', 'text', 1, 'Distinguish producing energy from reducing energy loss.', '{"why":"Insulation helps preserve the tea''s thermal energy by reducing the rate of energy transfer.","sol":"Step 1: The tea is hotter than its surroundings.\nStep 2: Thermal energy tends to leave the tea.\nStep 3: The flask slows that transfer.","steps":["Step 1: The tea is hotter than its surroundings.","Step 2: Thermal energy tends to leave the tea.","Step 3: The flask slows that transfer."],"options":[],"conceptId":"physics_temperature_and_thermal_physics_thermal_insulation","skillId":"physics_temperature_and_thermal_physics","subskillId":"physics_temperature_and_thermal_physics_q5","subject":"physics","chapter":"temperature_and_thermal_physics","topic":"Thermal Insulation"}', 4),
  (2105, 517, 'A runner covers 100 m in 20 s. Calculate the average speed.', 'text', 1, 'Speed = distance ÷ time.', '{"why":"The runner covers 5 metres every second on average.","sol":"Step 1: Write speed = distance ÷ time.\nStep 2: Substitute: 100 ÷ 20.\nStep 3: Calculate the result.","steps":["Step 1: Write speed = distance ÷ time.","Step 2: Substitute: 100 ÷ 20.","Step 3: Calculate the result."],"options":[],"conceptId":"physics_force_motion_and_mechanics_motion_calculations","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Motion Calculations"}', 0),
  (2106, 517, 'A car travels at 12 m/s for 15 s. Calculate the distance travelled.', 'text', 1, 'Distance = speed × time.', '{"why":"The car travels 12 metres each second for 15 seconds.","sol":"Step 1: Write distance = speed × time.\nStep 2: Substitute: 12 × 15.\nStep 3: Calculate the distance.","steps":["Step 1: Write distance = speed × time.","Step 2: Substitute: 12 × 15.","Step 3: Calculate the distance."],"options":[],"conceptId":"physics_force_motion_and_mechanics_motion_calculations","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Motion Calculations"}', 1),
  (2107, 517, 'A bus travels 240 m at an average speed of 8 m/s. Calculate the time taken.', 'text', 1, 'Time = distance ÷ speed.', '{"why":"At 8 m/s, the bus covers 240 m in 30 seconds.","sol":"Step 1: Write time = distance ÷ speed.\nStep 2: Substitute: 240 ÷ 8.\nStep 3: Calculate the time.","steps":["Step 1: Write time = distance ÷ speed.","Step 2: Substitute: 240 ÷ 8.","Step 3: Calculate the time."],"options":[],"conceptId":"physics_force_motion_and_mechanics_motion_calculations","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Motion Calculations"}', 2),
  (2108, 517, 'A student walks 600 m in 5 minutes. Calculate the average speed in m/s.', 'text', 1, 'Convert 5 minutes into seconds first.', '{"why":"Using 5 as the time without converting minutes would give the wrong unit and value.","sol":"Step 1: Convert time: 5 × 60 = 300 s.\nStep 2: Speed = 600 ÷ 300.\nStep 3: State the answer in m/s.","steps":["Step 1: Convert time: 5 × 60 = 300 s.","Step 2: Speed = 600 ÷ 300.","Step 3: State the answer in m/s."],"options":[],"conceptId":"physics_force_motion_and_mechanics_motion_calculations","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Motion Calculations"}', 3),
  (2109, 517, 'An object travels at 4 m/s for 2 minutes. Calculate the distance travelled.', 'text', 1, 'Convert minutes into seconds.', '{"why":"Distance is speed multiplied by time in seconds.","sol":"Step 1: Convert time: 2 × 60 = 120 s.\nStep 2: Distance = 4 × 120.\nStep 3: Check the unit is metres.","steps":["Step 1: Convert time: 2 × 60 = 120 s.","Step 2: Distance = 4 × 120.","Step 3: Check the unit is metres."],"options":[],"conceptId":"physics_force_motion_and_mechanics_motion_calculations","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Motion Calculations"}', 4),
  (2110, 518, 'A distance–time graph rises from 0 m at 0 s to 40 m at 8 s. Calculate the speed.', 'text', 1, 'Find the gradient.', '{"why":"The gradient of a distance–time graph gives speed.","sol":"Step 1: Change in distance = 40 m.\nStep 2: Change in time = 8 s.\nStep 3: Speed = 40 ÷ 8.","steps":["Step 1: Change in distance = 40 m.","Step 2: Change in time = 8 s.","Step 3: Speed = 40 ÷ 8."],"options":[],"conceptId":"physics_force_motion_and_mechanics_distance_time_graphs","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Distance–Time Graphs"}', 0),
  (2111, 518, 'What does a horizontal line on a distance–time graph mean?', 'text', 1, 'The distance is not changing.', '{"why":"If distance does not change, the object is not travelling farther from its starting reference.","sol":"Step 1: Read the line across time.\nStep 2: Notice that distance stays constant.\nStep 3: Relate constant distance to motion.","steps":["Step 1: Read the line across time.","Step 2: Notice that distance stays constant.","Step 3: Relate constant distance to motion."],"options":[],"conceptId":"physics_force_motion_and_mechanics_distance_time_graphs","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Distance–Time Graphs"}', 1),
  (2112, 518, 'Two straight rising lines start at the origin. Line A is steeper than line B. Which object is faster?', 'text', 1, 'Compare the gradients.', '{"why":"A larger distance–time gradient means more distance covered per second.","sol":"Step 1: Speed is the graph gradient.\nStep 2: A steeper line has a larger gradient.\nStep 3: Compare the speeds.","steps":["Step 1: Speed is the graph gradient.","Step 2: A steeper line has a larger gradient.","Step 3: Compare the speeds."],"options":[],"conceptId":"physics_force_motion_and_mechanics_distance_time_graphs","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Distance–Time Graphs"}', 2),
  (2113, 518, 'An object moves from 10 m at 2 s to 50 m at 10 s. Calculate its speed during this interval.', 'text', 1, 'Use changes, not just the final readings.', '{"why":"The gradient is calculated from the difference between the two points.","sol":"Step 1: Change in distance = 50 − 10 = 40 m.\nStep 2: Change in time = 10 − 2 = 8 s.\nStep 3: Speed = 40 ÷ 8.","steps":["Step 1: Change in distance = 50 − 10 = 40 m.","Step 2: Change in time = 10 − 2 = 8 s.","Step 3: Speed = 40 ÷ 8."],"options":[],"conceptId":"physics_force_motion_and_mechanics_distance_time_graphs","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Distance–Time Graphs"}', 3),
  (2114, 518, 'Why should you read the graph''s axis scale before finding speed?', 'text', 1, 'Consider what each grid square represents.', '{"why":"Counting squares without checking the scale can produce an incorrect speed.","sol":"Step 1: Identify the values on both axes.\nStep 2: Determine the actual distance and time changes.\nStep 3: Calculate using those values.","steps":["Step 1: Identify the values on both axes.","Step 2: Determine the actual distance and time changes.","Step 3: Calculate using those values."],"options":[],"conceptId":"physics_force_motion_and_mechanics_distance_time_graphs","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Distance–Time Graphs"}', 4),
  (2115, 519, 'Displacement changes from 0 m to 24 m in 6 s. Calculate the velocity.', 'text', 1, 'Velocity = change in displacement ÷ time.', '{"why":"The displacement increases by 4 m each second.","sol":"Step 1: Change in displacement = 24 − 0 = 24 m.\nStep 2: Time interval = 6 s.\nStep 3: Velocity = 24 ÷ 6.","steps":["Step 1: Change in displacement = 24 − 0 = 24 m.","Step 2: Time interval = 6 s.","Step 3: Velocity = 24 ÷ 6."],"options":[],"conceptId":"physics_force_motion_and_mechanics_displacement_time_graphs","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Displacement–Time Graphs"}', 0),
  (2116, 519, 'Displacement changes from 20 m to 5 m in 3 s. Calculate the average velocity.', 'text', 1, 'Subtract the initial displacement from the final displacement.', '{"why":"The negative sign indicates motion in the negative direction.","sol":"Step 1: Change = 5 − 20 = −15 m.\nStep 2: Divide by 3 s.\nStep 3: Keep the negative sign.","steps":["Step 1: Change = 5 − 20 = −15 m.","Step 2: Divide by 3 s.","Step 3: Keep the negative sign."],"options":[],"conceptId":"physics_force_motion_and_mechanics_displacement_time_graphs","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Displacement–Time Graphs"}', 1),
  (2117, 519, 'A displacement–time graph is horizontal for 7 s. What is the velocity during this interval?', 'text', 1, 'The displacement is constant.', '{"why":"No change in displacement means zero velocity.","sol":"Step 1: Change in displacement = 0 m.\nStep 2: Velocity = change in displacement ÷ time.\nStep 3: Calculate 0 ÷ 7.","steps":["Step 1: Change in displacement = 0 m.","Step 2: Velocity = change in displacement ÷ time.","Step 3: Calculate 0 ÷ 7."],"options":[],"conceptId":"physics_force_motion_and_mechanics_displacement_time_graphs","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Displacement–Time Graphs"}', 2),
  (2118, 519, 'A graph''s gradient is −3 m/s. What does the negative sign indicate?', 'text', 1, 'Think about direction, not speed size.', '{"why":"A negative gradient represents negative velocity.","sol":"Step 1: Identify the quantity represented by the gradient.\nStep 2: Interpret the negative sign using the chosen direction.","steps":["Step 1: Identify the quantity represented by the gradient.","Step 2: Interpret the negative sign using the chosen direction."],"options":[],"conceptId":"physics_force_motion_and_mechanics_displacement_time_graphs","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Displacement–Time Graphs"}', 3),
  (2119, 519, 'Displacement changes from −4 m to 8 m in 4 s. Calculate the average velocity.', 'text', 1, 'Calculate final displacement minus initial displacement.', '{"why":"Subtracting a negative initial displacement increases the displacement change.","sol":"Step 1: Change = 8 − (−4) = 12 m.\nStep 2: Divide by 4 s.\nStep 3: State the velocity.","steps":["Step 1: Change = 8 − (−4) = 12 m.","Step 2: Divide by 4 s.","Step 3: State the velocity."],"options":[],"conceptId":"physics_force_motion_and_mechanics_displacement_time_graphs","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Displacement–Time Graphs"}', 4),
  (2120, 520, 'Speed increases from 2 m/s to 14 m/s in 4 s. Calculate the rate of change of speed.', 'text', 1, 'Find the gradient.', '{"why":"The speed increases by 3 m/s each second on average.","sol":"Step 1: Change in speed = 14 − 2 = 12 m/s.\nStep 2: Time = 4 s.\nStep 3: Rate = 12 ÷ 4.","steps":["Step 1: Change in speed = 14 − 2 = 12 m/s.","Step 2: Time = 4 s.","Step 3: Rate = 12 ÷ 4."],"options":[],"conceptId":"physics_force_motion_and_mechanics_speed_time_graphs","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Speed–Time Graphs"}', 0),
  (2121, 520, 'A speed–time graph is horizontal at 8 m/s for 6 s. Calculate the distance travelled.', 'text', 1, 'Use the rectangular area under the graph.', '{"why":"The area under a constant-speed graph is speed multiplied by time.","sol":"Step 1: Distance = speed × time.\nStep 2: Substitute 8 × 6.\nStep 3: State the distance.","steps":["Step 1: Distance = speed × time.","Step 2: Substitute 8 × 6.","Step 3: State the distance."],"options":[],"conceptId":"physics_force_motion_and_mechanics_speed_time_graphs","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Speed–Time Graphs"}', 1),
  (2122, 520, 'Speed rises uniformly from 0 to 12 m/s in 4 s. Calculate the distance travelled.', 'text', 1, 'The area is a triangle.', '{"why":"Distance is the area under the speed–time graph.","sol":"Step 1: Distance = ½ × base × height.\nStep 2: Base = 4 s and height = 12 m/s.\nStep 3: Calculate ½ × 4 × 12.","steps":["Step 1: Distance = ½ × base × height.","Step 2: Base = 4 s and height = 12 m/s.","Step 3: Calculate ½ × 4 × 12."],"options":[],"conceptId":"physics_force_motion_and_mechanics_speed_time_graphs","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Speed–Time Graphs"}', 2),
  (2123, 520, 'Speed falls uniformly from 10 m/s to 4 m/s in 3 s. Calculate the rate of change of speed.', 'text', 1, 'Final speed minus initial speed, divided by time.', '{"why":"The negative rate indicates that the speed is decreasing.","sol":"Step 1: Change = 4 − 10 = −6 m/s.\nStep 2: Divide by 3 s.\nStep 3: Interpret the negative result.","steps":["Step 1: Change = 4 − 10 = −6 m/s.","Step 2: Divide by 3 s.","Step 3: Interpret the negative result."],"options":[],"conceptId":"physics_force_motion_and_mechanics_speed_time_graphs","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Speed–Time Graphs"}', 3),
  (2124, 520, 'What does the area under a speed–time graph represent?', 'text', 1, 'Combine the units of the axes.', '{"why":"Multiplying m/s by s gives metres.","sol":"Step 1: Area uses speed multiplied by time.\nStep 2: The units are (m/s) × s.\nStep 3: Simplify the units.","steps":["Step 1: Area uses speed multiplied by time.","Step 2: The units are (m/s) × s.","Step 3: Simplify the units."],"options":[],"conceptId":"physics_force_motion_and_mechanics_speed_time_graphs","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Speed–Time Graphs"}', 4),
  (2125, 521, 'Velocity changes from 3 m/s to 15 m/s in 4 s. Calculate acceleration.', 'text', 1, 'Acceleration = change in velocity ÷ time.', '{"why":"The velocity increases by 3 m/s each second.","sol":"Step 1: Change = 15 − 3 = 12 m/s.\nStep 2: Divide by 4 s.\nStep 3: State the acceleration.","steps":["Step 1: Change = 15 − 3 = 12 m/s.","Step 2: Divide by 4 s.","Step 3: State the acceleration."],"options":[],"conceptId":"physics_force_motion_and_mechanics_velocity_time_graphs","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Velocity–Time Graphs"}', 0),
  (2126, 521, 'An object moves at a constant velocity of −6 m/s for 5 s. Calculate its displacement.', 'text', 1, 'Displacement = velocity × time.', '{"why":"The negative sign indicates displacement in the negative direction.","sol":"Step 1: Multiply −6 by 5.\nStep 2: Keep the negative sign.\nStep 3: State the displacement.","steps":["Step 1: Multiply −6 by 5.","Step 2: Keep the negative sign.","Step 3: State the displacement."],"options":[],"conceptId":"physics_force_motion_and_mechanics_velocity_time_graphs","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Velocity–Time Graphs"}', 1),
  (2127, 521, 'Velocity decreases from 12 m/s to 0 m/s in 3 s. Calculate acceleration.', 'text', 1, 'Use final velocity minus initial velocity.', '{"why":"The velocity decreases at 4 m/s each second.","sol":"Step 1: Change = 0 − 12 = −12 m/s.\nStep 2: Divide by 3 s.\nStep 3: Interpret the sign.","steps":["Step 1: Change = 0 − 12 = −12 m/s.","Step 2: Divide by 3 s.","Step 3: Interpret the sign."],"options":[],"conceptId":"physics_force_motion_and_mechanics_velocity_time_graphs","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Velocity–Time Graphs"}', 2),
  (2128, 521, 'A velocity–time graph has a horizontal line at 7 m/s. What is the acceleration?', 'text', 1, 'Velocity does not change.', '{"why":"Constant velocity means zero acceleration.","sol":"Step 1: Change in velocity = 0.\nStep 2: Acceleration = change in velocity ÷ time.\nStep 3: Evaluate the ratio.","steps":["Step 1: Change in velocity = 0.","Step 2: Acceleration = change in velocity ÷ time.","Step 3: Evaluate the ratio."],"options":[],"conceptId":"physics_force_motion_and_mechanics_velocity_time_graphs","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Velocity–Time Graphs"}', 3),
  (2129, 521, 'Velocity is −4 m/s for 3 s. What is the displacement?', 'text', 1, 'Use signed velocity.', '{"why":"Signed velocity gives signed displacement.","sol":"Step 1: Displacement = velocity × time.\nStep 2: Calculate −4 × 3.\nStep 3: Include the direction indicated by the sign.","steps":["Step 1: Displacement = velocity × time.","Step 2: Calculate −4 × 3.","Step 3: Include the direction indicated by the sign."],"options":[],"conceptId":"physics_force_motion_and_mechanics_velocity_time_graphs","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Velocity–Time Graphs"}', 4),
  (2130, 522, 'Which quantity is found from the gradient of a velocity–time graph?', 'text', 1, 'A gradient compares change in vertical quantity with change in time.', '{"why":"Acceleration is the rate of change of velocity.","sol":"Step 1: Identify the vertical axis as velocity.\nStep 2: Calculate change in velocity divided by time.\nStep 3: Name the physical quantity.","steps":["Step 1: Identify the vertical axis as velocity.","Step 2: Calculate change in velocity divided by time.","Step 3: Name the physical quantity."],"options":[],"conceptId":"physics_force_motion_and_mechanics_interpreting_motion_graphs","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Interpreting Motion Graphs"}', 0),
  (2131, 522, 'A velocity–time graph stays at 5 m/s for 8 s. Calculate the displacement.', 'text', 1, 'Use the rectangular area.', '{"why":"The constant positive velocity gives a rectangular area of 40 m.","sol":"Step 1: Displacement = velocity × time.\nStep 2: Calculate 5 × 8.\nStep 3: State the result.","steps":["Step 1: Displacement = velocity × time.","Step 2: Calculate 5 × 8.","Step 3: State the result."],"options":[],"conceptId":"physics_force_motion_and_mechanics_interpreting_motion_graphs","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Interpreting Motion Graphs"}', 1),
  (2132, 522, 'A distance–time graph has a steeper gradient during the second interval. What does this tell you?', 'text', 1, 'Relate gradient to speed.', '{"why":"It covers more distance per unit time.","sol":"Step 1: Gradient of distance–time graph gives speed.\nStep 2: Compare the gradients.\nStep 3: Interpret the larger gradient.","steps":["Step 1: Gradient of distance–time graph gives speed.","Step 2: Compare the gradients.","Step 3: Interpret the larger gradient."],"options":[],"conceptId":"physics_force_motion_and_mechanics_interpreting_motion_graphs","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Interpreting Motion Graphs"}', 2),
  (2133, 522, 'A velocity–time graph lies below the time axis. What does this indicate?', 'text', 1, 'Check the sign of velocity.', '{"why":"Negative velocity indicates direction relative to the chosen positive direction.","sol":"Step 1: Read the vertical-axis values.\nStep 2: Notice that velocity is negative.\nStep 3: Relate the sign to direction.","steps":["Step 1: Read the vertical-axis values.","Step 2: Notice that velocity is negative.","Step 3: Relate the sign to direction."],"options":[],"conceptId":"physics_force_motion_and_mechanics_interpreting_motion_graphs","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Interpreting Motion Graphs"}', 3),
  (2134, 522, 'A velocity–time graph rises from 2 m/s to 10 m/s in 4 s. Calculate both acceleration and displacement, assuming uniform acceleration.', 'text', 1, 'Use the gradient for acceleration and the trapezium area for displacement.', '{"why":"The gradient gives acceleration, while the area under the graph gives displacement.","sol":"Step 1: Acceleration = (10 − 2) ÷ 4 = 2 m/s².\nStep 2: Displacement = average velocity × time.\nStep 3: Average velocity = (2 + 10) ÷ 2 = 6 m/s; displacement = 6 × 4.","steps":["Step 1: Acceleration = (10 − 2) ÷ 4 = 2 m/s².","Step 2: Displacement = average velocity × time.","Step 3: Average velocity = (2 + 10) ÷ 2 = 6 m/s; displacement = 6 × 4."],"options":[],"conceptId":"physics_force_motion_and_mechanics_interpreting_motion_graphs","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Interpreting Motion Graphs"}', 4),
  (2135, 523, 'A vehicle travels at a constant 15 m/s for 10 s. Calculate the distance.', 'text', 1, 'Distance = speed × time.', '{"why":"Constant speed allows direct use of distance = speed × time.","sol":"Step 1: Substitute 15 m/s and 10 s.\nStep 2: Calculate 15 × 10.\nStep 3: State the distance.","steps":["Step 1: Substitute 15 m/s and 10 s.","Step 2: Calculate 15 × 10.","Step 3: State the distance."],"options":[],"conceptId":"physics_force_motion_and_mechanics_uniform_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Uniform Motion"}', 0),
  (2136, 523, 'What is the acceleration of an object moving with constant velocity?', 'text', 1, 'Acceleration measures change in velocity.', '{"why":"There is no change in velocity.","sol":"Step 1: Constant velocity does not change.\nStep 2: Change in velocity is zero.\nStep 3: Divide by elapsed time.","steps":["Step 1: Constant velocity does not change.","Step 2: Change in velocity is zero.","Step 3: Divide by elapsed time."],"options":[],"conceptId":"physics_force_motion_and_mechanics_uniform_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Uniform Motion"}', 1),
  (2137, 523, 'An object travels 360 m in 30 s at constant speed. Calculate its speed.', 'text', 1, 'Speed = distance ÷ time.', '{"why":"The object covers 12 metres per second.","sol":"Step 1: Write 360 ÷ 30.\nStep 2: Calculate the quotient.\nStep 3: Include m/s.","steps":["Step 1: Write 360 ÷ 30.","Step 2: Calculate the quotient.","Step 3: Include m/s."],"options":[],"conceptId":"physics_force_motion_and_mechanics_uniform_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Uniform Motion"}', 2),
  (2138, 523, 'What does a straight line with constant gradient on a distance–time graph indicate?', 'text', 1, 'The gradient represents speed.', '{"why":"Equal gradients indicate equal distance covered per unit time.","sol":"Step 1: A constant gradient means the same speed.\nStep 2: The distance increases evenly with time.\nStep 3: Name the motion.","steps":["Step 1: A constant gradient means the same speed.","Step 2: The distance increases evenly with time.","Step 3: Name the motion."],"options":[],"conceptId":"physics_force_motion_and_mechanics_uniform_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Uniform Motion"}', 3),
  (2139, 523, 'A cyclist travels at 6 m/s for 2 minutes. Calculate the distance in metres.', 'text', 1, 'Convert minutes to seconds.', '{"why":"The time must be in seconds when speed is in m/s.","sol":"Step 1: Time = 2 × 60 = 120 s.\nStep 2: Distance = 6 × 120.\nStep 3: State the answer in metres.","steps":["Step 1: Time = 2 × 60 = 120 s.","Step 2: Distance = 6 × 120.","Step 3: State the answer in metres."],"options":[],"conceptId":"physics_force_motion_and_mechanics_uniform_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Uniform Motion"}', 4),
  (2140, 524, 'An object starts at 0 m/s and accelerates at 2 m/s² for 5 s. Find its final velocity.', 'text', 1, 'Use v = u + at.', '{"why":"The velocity increases by 2 m/s each second.","sol":"Step 1: u = 0, a = 2, t = 5.\nStep 2: v = 0 + (2 × 5).\nStep 3: Calculate the final velocity.","steps":["Step 1: u = 0, a = 2, t = 5.","Step 2: v = 0 + (2 × 5).","Step 3: Calculate the final velocity."],"options":[],"conceptId":"physics_force_motion_and_mechanics_uniform_acceleration","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Uniform Acceleration"}', 0),
  (2141, 524, 'A car''s velocity increases from 4 m/s to 16 m/s in 6 s. Find its uniform acceleration.', 'text', 1, 'a = (v − u) ÷ t.', '{"why":"Acceleration is the change in velocity per second.","sol":"Step 1: Change in velocity = 16 − 4 = 12 m/s.\nStep 2: Divide by 6 s.\nStep 3: State the acceleration.","steps":["Step 1: Change in velocity = 16 − 4 = 12 m/s.","Step 2: Divide by 6 s.","Step 3: State the acceleration."],"options":[],"conceptId":"physics_force_motion_and_mechanics_uniform_acceleration","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Uniform Acceleration"}', 1),
  (2142, 524, 'A vehicle moving at 20 m/s slows with acceleration −4 m/s² for 3 s. Find its final velocity.', 'text', 1, 'Keep the negative acceleration.', '{"why":"The negative acceleration reduces the velocity by 12 m/s.","sol":"Step 1: Use v = u + at.\nStep 2: v = 20 + (−4 × 3).\nStep 3: Evaluate the expression.","steps":["Step 1: Use v = u + at.","Step 2: v = 20 + (−4 × 3).","Step 3: Evaluate the expression."],"options":[],"conceptId":"physics_force_motion_and_mechanics_uniform_acceleration","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Uniform Acceleration"}', 2),
  (2143, 524, 'A body starts at 5 m/s and reaches 17 m/s with uniform acceleration of 3 m/s². Find the time taken.', 'text', 1, 'Rearrange v = u + at to find t.', '{"why":"The velocity changes by 12 m/s at 3 m/s each second.","sol":"Step 1: t = (v − u) ÷ a.\nStep 2: t = (17 − 5) ÷ 3.\nStep 3: Calculate the time.","steps":["Step 1: t = (v − u) ÷ a.","Step 2: t = (17 − 5) ÷ 3.","Step 3: Calculate the time."],"options":[],"conceptId":"physics_force_motion_and_mechanics_uniform_acceleration","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Uniform Acceleration"}', 3),
  (2144, 524, 'An object has initial velocity 12 m/s and final velocity 12 m/s after 4 s. Find its average acceleration.', 'text', 1, 'Calculate the change in velocity.', '{"why":"There is no change in velocity over the interval.","sol":"Step 1: Change = 12 − 12 = 0 m/s.\nStep 2: Acceleration = 0 ÷ 4.\nStep 3: State the result.","steps":["Step 1: Change = 12 − 12 = 0 m/s.","Step 2: Acceleration = 0 ÷ 4.","Step 3: State the result."],"options":[],"conceptId":"physics_force_motion_and_mechanics_uniform_acceleration","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Uniform Acceleration"}', 4),
  (2145, 525, 'You know initial velocity, acceleration and time. Which equation directly gives final velocity?', 'text', 1, 'Choose the equation containing u, a, t and v.', '{"why":"This equation relates final velocity to initial velocity, acceleration and time.","sol":"Step 1: List the known quantities.\nStep 2: Identify the unknown as v.\nStep 3: Select the equation that connects them directly.","steps":["Step 1: List the known quantities.","Step 2: Identify the unknown as v.","Step 3: Select the equation that connects them directly."],"options":[],"conceptId":"physics_force_motion_and_mechanics_selecting_the_correct_motion_equation","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Selecting the Correct Motion Equation"}', 0),
  (2146, 525, 'You know u, a and t and need displacement. Which equation is most direct?', 'text', 1, 'Look for an equation with s, u, a and t but not v.', '{"why":"This equation calculates displacement without needing final velocity.","sol":"Step 1: List the known quantities.\nStep 2: Identify displacement as the unknown.\nStep 3: Choose the equation that uses only known values and s.","steps":["Step 1: List the known quantities.","Step 2: Identify displacement as the unknown.","Step 3: Choose the equation that uses only known values and s."],"options":[],"conceptId":"physics_force_motion_and_mechanics_selecting_the_correct_motion_equation","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Selecting the Correct Motion Equation"}', 1),
  (2147, 525, 'You know u, v and a but not time. Which equation can find displacement?', 'text', 1, 'Choose an equation without t.', '{"why":"Rearranging this equation gives s = (v² − u²) ÷ 2a.","sol":"Step 1: List u, v and a.\nStep 2: Exclude equations requiring time.\nStep 3: Select the equation containing s.","steps":["Step 1: List u, v and a.","Step 2: Exclude equations requiring time.","Step 3: Select the equation containing s."],"options":[],"conceptId":"physics_force_motion_and_mechanics_selecting_the_correct_motion_equation","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Selecting the Correct Motion Equation"}', 2),
  (2148, 525, 'A problem gives initial velocity, final velocity and time. Which equation finds displacement directly?', 'text', 1, 'Use average velocity for constant acceleration.', '{"why":"The equation uses average velocity multiplied by elapsed time.","sol":"Step 1: For uniform acceleration, average velocity = (u + v) ÷ 2.\nStep 2: Multiply average velocity by time.\nStep 3: Write the corresponding equation.","steps":["Step 1: For uniform acceleration, average velocity = (u + v) ÷ 2.","Step 2: Multiply average velocity by time.","Step 3: Write the corresponding equation."],"options":[],"conceptId":"physics_force_motion_and_mechanics_selecting_the_correct_motion_equation","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Selecting the Correct Motion Equation"}', 3),
  (2149, 525, 'Why must you check whether acceleration is constant before using these equations?', 'text', 1, 'Consider the assumption behind the equations.', '{"why":"The equations are derived for motion with uniform acceleration.","sol":"Step 1: Identify the motion equations'' condition.\nStep 2: Consider whether acceleration may change.\nStep 3: Explain why the condition matters.","steps":["Step 1: Identify the motion equations'' condition.","Step 2: Consider whether acceleration may change.","Step 3: Explain why the condition matters."],"options":[],"conceptId":"physics_force_motion_and_mechanics_selecting_the_correct_motion_equation","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Selecting the Correct Motion Equation"}', 4),
  (2150, 526, 'A car starts at 3 m/s and accelerates at 2 m/s² for 4 s. Calculate its final velocity.', 'text', 1, 'Use v = u + at.', '{"why":"The velocity increases by 8 m/s from its initial 3 m/s.","sol":"Step 1: u = 3, a = 2, t = 4.\nStep 2: v = 3 + (2 × 4).\nStep 3: Calculate and include units.","steps":["Step 1: u = 3, a = 2, t = 4.","Step 2: v = 3 + (2 × 4).","Step 3: Calculate and include units."],"options":[],"conceptId":"physics_force_motion_and_mechanics_solving_motion_problems","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Solving Motion Problems"}', 0),
  (2151, 526, 'A body starts from rest and accelerates at 3 m/s² for 4 s. Calculate its displacement.', 'text', 1, 'Use s = ut + ½at².', '{"why":"The body starts from rest, so the ut term is zero.","sol":"Step 1: u = 0, a = 3, t = 4.\nStep 2: s = 0 × 4 + ½ × 3 × 4².\nStep 3: Evaluate the expression.","steps":["Step 1: u = 0, a = 3, t = 4.","Step 2: s = 0 × 4 + ½ × 3 × 4².","Step 3: Evaluate the expression."],"options":[],"conceptId":"physics_force_motion_and_mechanics_solving_motion_problems","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Solving Motion Problems"}', 1),
  (2152, 526, 'A vehicle slows from 18 m/s to 6 m/s in 4 s. Calculate its acceleration.', 'text', 1, 'Acceleration = (v − u) ÷ t.', '{"why":"The negative acceleration shows that velocity decreases in the chosen positive direction.","sol":"Step 1: u = 18 m/s and v = 6 m/s.\nStep 2: a = (6 − 18) ÷ 4.\nStep 3: Interpret the sign.","steps":["Step 1: u = 18 m/s and v = 6 m/s.","Step 2: a = (6 − 18) ÷ 4.","Step 3: Interpret the sign."],"options":[],"conceptId":"physics_force_motion_and_mechanics_solving_motion_problems","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Solving Motion Problems"}', 2),
  (2153, 526, 'An object moving at 5 m/s accelerates uniformly at 2 m/s² through a displacement of 12 m. Find its final speed.', 'text', 1, 'Use v² = u² + 2as.', '{"why":"The equation avoids needing to know the time.","sol":"Step 1: v² = 5² + 2 × 2 × 12.\nStep 2: v² = 25 + 48 = 73.\nStep 3: Take the positive square root for final speed.","steps":["Step 1: v² = 5² + 2 × 2 × 12.","Step 2: v² = 25 + 48 = 73.","Step 3: Take the positive square root for final speed."],"options":[],"conceptId":"physics_force_motion_and_mechanics_solving_motion_problems","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Solving Motion Problems"}', 3),
  (2154, 526, 'A student calculates displacement using s = ut + ½at² but substitutes time in minutes while velocity is in m/s. What should be corrected?', 'text', 1, 'Check whether the units are consistent.', '{"why":"Using inconsistent units produces an incorrect displacement.","sol":"Step 1: The velocity is expressed per second.\nStep 2: Convert the time to seconds.\nStep 3: Then substitute into the equation.","steps":["Step 1: The velocity is expressed per second.","Step 2: Convert the time to seconds.","Step 3: Then substitute into the equation."],"options":[],"conceptId":"physics_force_motion_and_mechanics_solving_motion_problems","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Solving Motion Problems"}', 4),
  (2155, 527, 'A stone is released from rest. Taking g = 10 m/s², calculate its speed after 3 s of free fall.', 'text', 1, 'Use v = u + gt with u = 0.', '{"why":"Its speed increases by 10 m/s each second under the stated approximation.","sol":"Step 1: u = 0, g = 10 m/s², t = 3 s.\nStep 2: v = 0 + 10 × 3.\nStep 3: State the speed.","steps":["Step 1: u = 0, g = 10 m/s², t = 3 s.","Step 2: v = 0 + 10 × 3.","Step 3: State the speed."],"options":[],"conceptId":"physics_force_motion_and_mechanics_free_fall","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Free Fall"}', 0),
  (2156, 527, 'An object falls from rest for 2 s. Take g = 10 m/s². Calculate the distance fallen.', 'text', 1, 'Use s = ut + ½gt².', '{"why":"The object starts from rest, so the initial-velocity term is zero.","sol":"Step 1: u = 0 and t = 2 s.\nStep 2: s = ½ × 10 × 2².\nStep 3: Evaluate the expression.","steps":["Step 1: u = 0 and t = 2 s.","Step 2: s = ½ × 10 × 2².","Step 3: Evaluate the expression."],"options":[],"conceptId":"physics_force_motion_and_mechanics_free_fall","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Free Fall"}', 1),
  (2157, 527, 'A ball is thrown vertically upward. If upward is positive, what is its acceleration near Earth''s surface? Take g = 10 m/s².', 'text', 1, 'Gravity acts downward throughout the motion.', '{"why":"Gravity remains downward even while the ball is moving upward.","sol":"Step 1: Identify the positive direction as upward.\nStep 2: Gravity points in the negative direction.\nStep 3: Apply the sign to g.","steps":["Step 1: Identify the positive direction as upward.","Step 2: Gravity points in the negative direction.","Step 3: Apply the sign to g."],"options":[],"conceptId":"physics_force_motion_and_mechanics_free_fall","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Free Fall"}', 2),
  (2158, 527, 'Two objects of different masses fall freely in a vacuum from the same height. Which has the greater gravitational acceleration near Earth?', 'text', 1, 'There is no air resistance in a vacuum.', '{"why":"In a vacuum, objects near Earth accelerate equally under gravity regardless of mass.","sol":"Step 1: Identify the only force as gravity.\nStep 2: Recall free-fall acceleration near Earth.\nStep 3: Compare the accelerations.","steps":["Step 1: Identify the only force as gravity.","Step 2: Recall free-fall acceleration near Earth.","Step 3: Compare the accelerations."],"options":[],"conceptId":"physics_force_motion_and_mechanics_free_fall","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Free Fall"}', 3),
  (2159, 527, 'A stone is released from rest and falls freely for 4 s. Take g = 10 m/s². Calculate its final velocity, taking downward as positive.', 'text', 1, 'Use v = u + gt.', '{"why":"The positive result means the stone is moving downward under the chosen sign convention.","sol":"Step 1: u = 0, g = +10 m/s², t = 4 s.\nStep 2: v = 0 + 10 × 4.\nStep 3: Include the direction.","steps":["Step 1: u = 0, g = +10 m/s², t = 4 s.","Step 2: v = 0 + 10 × 4.","Step 3: Include the direction."],"options":[],"conceptId":"physics_force_motion_and_mechanics_free_fall","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Free Fall"}', 4),
  (2160, 527, 'What is free fall?', 'text', 1, 'Consider which force acts on the object.', '{"why":"Free fall describes motion when gravity is the only acting force.","sol":"Step 1: Free fall occurs when gravity is the only force acting.\nStep 2: Air resistance is neglected in the ideal model.","steps":["Step 1: Free fall occurs when gravity is the only force acting.","Step 2: Air resistance is neglected in the ideal model."],"options":[],"conceptId":"physics_force_motion_and_mechanics_free_fall","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q6","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Free Fall"}', 5),
  (2161, 527, 'A stone is dropped and air resistance is negligible. What happens to its speed as it falls?', 'text', 1, 'Gravity produces downward acceleration.', '{"why":"A freely falling stone accelerates due to gravity.","sol":"Step 1: Gravity accelerates the stone downward.\nStep 2: Its downward speed increases during the fall.","steps":["Step 1: Gravity accelerates the stone downward.","Step 2: Its downward speed increases during the fall."],"options":[],"conceptId":"physics_force_motion_and_mechanics_free_fall","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q7","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Free Fall"}', 6),
  (2162, 527, 'Two objects of different masses are dropped together in a vacuum from the same height. Which reaches the ground first?', 'text', 1, 'There is no air resistance.', '{"why":"Without air resistance, mass does not determine the free-fall acceleration.","sol":"Step 1: Both objects experience gravitational acceleration.\nStep 2: In a vacuum, their accelerations are equal.\nStep 3: They reach the ground together if released together.","steps":["Step 1: Both objects experience gravitational acceleration.","Step 2: In a vacuum, their accelerations are equal.","Step 3: They reach the ground together if released together."],"options":[],"conceptId":"physics_force_motion_and_mechanics_free_fall","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q8","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Free Fall"}', 7),
  (2163, 527, 'Is a parachutist moving downward at constant speed necessarily in free fall?', 'text', 1, 'Consider the force exerted by the air.', '{"why":"A parachutist experiences air resistance, so the motion is not free fall in the strict sense.","sol":"Step 1: Air resistance acts upward.\nStep 2: Gravity acts downward.\nStep 3: Gravity is not the only force acting.","steps":["Step 1: Air resistance acts upward.","Step 2: Gravity acts downward.","Step 3: Gravity is not the only force acting."],"options":[],"conceptId":"physics_force_motion_and_mechanics_free_fall","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q9","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Free Fall"}', 8),
  (2164, 527, 'A ball is released from rest and falls freely. What is its initial speed?', 'text', 1, 'Released from rest means it starts without motion.', '{"why":"An object released from rest has zero initial speed.","sol":"Step 1: The ball is released from rest.\nStep 2: Its initial speed is zero.","steps":["Step 1: The ball is released from rest.","Step 2: Its initial speed is zero."],"options":[],"conceptId":"physics_force_motion_and_mechanics_free_fall","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q10","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Free Fall"}', 9),
  (2165, 528, 'A book rests on a horizontal table. What is the resultant force on it if it remains at rest?', 'text', 1, 'Consider the book''s vertical forces.', '{"why":"The upward reaction balances the downward weight.","sol":"Step 1: The weight acts downward.\nStep 2: The table''s normal reaction acts upward.\nStep 3: At rest without acceleration, these forces balance.","steps":["Step 1: The weight acts downward.","Step 2: The table''s normal reaction acts upward.","Step 3: At rest without acceleration, these forces balance."],"options":[],"conceptId":"physics_force_motion_and_mechanics_newton_s_first_law_of_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Newton''s First Law of Motion"}', 0),
  (2166, 528, 'A trolley moves in a straight line at constant velocity. What is its acceleration?', 'text', 1, 'Velocity is not changing.', '{"why":"Acceleration is the rate of change of velocity.","sol":"Step 1: Identify the velocity as constant.\nStep 2: Find the change in velocity.\nStep 3: Relate the change to acceleration.","steps":["Step 1: Identify the velocity as constant.","Step 2: Find the change in velocity.","Step 3: Relate the change to acceleration."],"options":[],"conceptId":"physics_force_motion_and_mechanics_newton_s_first_law_of_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Newton''s First Law of Motion"}', 1),
  (2167, 528, 'Why does a passenger tend to move forward when a moving bus stops suddenly?', 'text', 1, 'Think about the passenger''s existing motion.', '{"why":"The body resists a change in its state of motion.","sol":"Step 1: Before the stop, the passenger moves with the bus.\nStep 2: The bus slows rapidly.\nStep 3: The passenger''s body tends to maintain its motion.","steps":["Step 1: Before the stop, the passenger moves with the bus.","Step 2: The bus slows rapidly.","Step 3: The passenger''s body tends to maintain its motion."],"options":[],"conceptId":"physics_force_motion_and_mechanics_newton_s_first_law_of_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Newton''s First Law of Motion"}', 2),
  (2168, 528, 'A box is pushed with 20 N to the right and experiences 20 N of friction to the left. What is the resultant horizontal force?', 'text', 1, 'Opposite forces subtract.', '{"why":"The two horizontal forces balance.","sol":"Step 1: Choose right as positive.\nStep 2: Resultant force = 20 − 20.\nStep 3: State the result.","steps":["Step 1: Choose right as positive.","Step 2: Resultant force = 20 − 20.","Step 3: State the result."],"options":[],"conceptId":"physics_force_motion_and_mechanics_newton_s_first_law_of_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Newton''s First Law of Motion"}', 3),
  (2169, 528, 'A spacecraft is moving through deep space with its engines off. If the resultant force is zero, what happens to its velocity?', 'text', 1, 'Apply Newton''s first law.', '{"why":"A continuing resultant force is not required to maintain constant velocity.","sol":"Step 1: The resultant force is zero.\nStep 2: Therefore, acceleration is zero.\nStep 3: Describe the velocity.","steps":["Step 1: The resultant force is zero.","Step 2: Therefore, acceleration is zero.","Step 3: Describe the velocity."],"options":[],"conceptId":"physics_force_motion_and_mechanics_newton_s_first_law_of_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Newton''s First Law of Motion"}', 4),
  (2170, 528, 'State Newton''s first law of motion.', 'text', 1, 'Think about what happens when the resultant force is zero.', '{"why":"The law describes the behaviour of objects when the resultant force is zero.","sol":"Step 1: If the resultant external force is zero, velocity does not change.\nStep 2: An object stays at rest or moves with constant velocity in a straight line.","steps":["Step 1: If the resultant external force is zero, velocity does not change.","Step 2: An object stays at rest or moves with constant velocity in a straight line."],"options":[],"conceptId":"physics_force_motion_and_mechanics_newton_s_first_law_of_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q6","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Newton''s First Law of Motion"}', 5),
  (2171, 528, 'A stationary book has balanced forces acting on it. What is its resultant force?', 'text', 1, 'Balanced forces cancel.', '{"why":"Equal and opposite forces have a zero resultant.","sol":"Step 1: The upward support force balances the downward weight.\nStep 2: The resultant force is zero.","steps":["Step 1: The upward support force balances the downward weight.","Step 2: The resultant force is zero."],"options":[],"conceptId":"physics_force_motion_and_mechanics_newton_s_first_law_of_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q7","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Newton''s First Law of Motion"}', 6),
  (2172, 528, 'A trolley moves in a straight line at constant velocity. What is its resultant force?', 'text', 1, 'Its velocity is not changing.', '{"why":"A non-zero resultant force would cause acceleration.","sol":"Step 1: Constant velocity means zero acceleration.\nStep 2: The resultant force is zero.","steps":["Step 1: Constant velocity means zero acceleration.","Step 2: The resultant force is zero."],"options":[],"conceptId":"physics_force_motion_and_mechanics_newton_s_first_law_of_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q8","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Newton''s First Law of Motion"}', 7),
  (2173, 528, 'Does a moving object always need a resultant force in the direction of motion to keep moving?', 'text', 1, 'Recall the first law.', '{"why":"An object can continue moving at constant velocity without a resultant force.","sol":"Step 1: The first law allows motion at constant velocity with zero resultant force.\nStep 2: A resultant force is needed to change velocity.","steps":["Step 1: The first law allows motion at constant velocity with zero resultant force.","Step 2: A resultant force is needed to change velocity."],"options":[],"conceptId":"physics_force_motion_and_mechanics_newton_s_first_law_of_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q9","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Newton''s First Law of Motion"}', 8),
  (2174, 528, 'A ball slows down while rolling across a rough floor. Why does this not contradict Newton''s first law?', 'text', 1, 'Identify a force that opposes the motion.', '{"why":"The first law applies when the resultant force is zero.","sol":"Step 1: Friction acts opposite the motion.\nStep 2: The forces are not balanced in the direction of motion.\nStep 3: The ball slows down.","steps":["Step 1: Friction acts opposite the motion.","Step 2: The forces are not balanced in the direction of motion.","Step 3: The ball slows down."],"options":[],"conceptId":"physics_force_motion_and_mechanics_newton_s_first_law_of_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q10","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Newton''s First Law of Motion"}', 9),
  (2175, 529, 'A 5 kg object accelerates at 2 m/s². Calculate the resultant force.', 'text', 1, 'Use F = ma.', '{"why":"Force equals mass multiplied by acceleration.","sol":"Step 1: Write F = ma.\nStep 2: Substitute 5 × 2.\nStep 3: Include newtons.","steps":["Step 1: Write F = ma.","Step 2: Substitute 5 × 2.","Step 3: Include newtons."],"options":[],"conceptId":"physics_force_motion_and_mechanics_newton_s_second_law_of_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Newton''s Second Law of Motion"}', 0),
  (2176, 529, 'A resultant force of 24 N acts on a 6 kg object. Calculate its acceleration.', 'text', 1, 'Rearrange F = ma.', '{"why":"Acceleration is resultant force divided by mass.","sol":"Step 1: a = F ÷ m.\nStep 2: a = 24 ÷ 6.\nStep 3: State the acceleration.","steps":["Step 1: a = F ÷ m.","Step 2: a = 24 ÷ 6.","Step 3: State the acceleration."],"options":[],"conceptId":"physics_force_motion_and_mechanics_newton_s_second_law_of_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Newton''s Second Law of Motion"}', 1),
  (2177, 529, 'A 3 kg object accelerates at 5 m/s². Calculate the resultant force.', 'text', 1, 'Multiply mass by acceleration.', '{"why":"The SI units kg·m/s² are equivalent to a newton.","sol":"Step 1: F = ma.\nStep 2: F = 3 × 5.\nStep 3: State the force.","steps":["Step 1: F = ma.","Step 2: F = 3 × 5.","Step 3: State the force."],"options":[],"conceptId":"physics_force_motion_and_mechanics_newton_s_second_law_of_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Newton''s Second Law of Motion"}', 2),
  (2178, 529, 'A 10 kg trolley experiences a resultant force of 15 N. Calculate its acceleration.', 'text', 1, 'Divide the resultant force by mass.', '{"why":"A given force produces less acceleration when the mass is greater.","sol":"Step 1: a = F ÷ m.\nStep 2: a = 15 ÷ 10.\nStep 3: Include m/s².","steps":["Step 1: a = F ÷ m.","Step 2: a = 15 ÷ 10.","Step 3: Include m/s²."],"options":[],"conceptId":"physics_force_motion_and_mechanics_newton_s_second_law_of_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Newton''s Second Law of Motion"}', 3),
  (2179, 529, 'A 2 kg object has zero acceleration. What is its resultant force?', 'text', 1, 'Use F = ma.', '{"why":"Zero acceleration means zero resultant force for this constant-mass object.","sol":"Step 1: Mass = 2 kg and acceleration = 0 m/s².\nStep 2: F = 2 × 0.\nStep 3: State the result.","steps":["Step 1: Mass = 2 kg and acceleration = 0 m/s².","Step 2: F = 2 × 0.","Step 3: State the result."],"options":[],"conceptId":"physics_force_motion_and_mechanics_newton_s_second_law_of_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Newton''s Second Law of Motion"}', 4),
  (2180, 529, 'State the formula relating resultant force, mass and acceleration.', 'text', 1, 'Multiply mass by acceleration.', '{"why":"Newton''s second law relates resultant force to mass and acceleration.","sol":"Step 1: Identify mass m and acceleration a.\nStep 2: Use F = ma.","steps":["Step 1: Identify mass m and acceleration a.","Step 2: Use F = ma."],"options":[],"conceptId":"physics_force_motion_and_mechanics_newton_s_second_law_of_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q6","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Newton''s Second Law of Motion"}', 5),
  (2181, 529, 'A 5 kg object accelerates at 2 m/s². Calculate the resultant force.', 'text', 1, 'Use F = ma.', '{"why":"Multiplying mass by acceleration gives resultant force.","sol":"Step 1: F = 5 × 2\nStep 2: F = 10 N","steps":["Step 1: F = 5 × 2","Step 2: F = 10 N"],"options":[],"conceptId":"physics_force_motion_and_mechanics_newton_s_second_law_of_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q7","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Newton''s Second Law of Motion"}', 6),
  (2182, 529, 'A resultant force of 24 N acts on a 6 kg object. Calculate its acceleration.', 'text', 1, 'Rearrange F = ma to find a.', '{"why":"Acceleration equals resultant force divided by mass.","sol":"Step 1: a = F/m\nStep 2: a = 24/6\nStep 3: a = 4 m/s²","steps":["Step 1: a = F/m","Step 2: a = 24/6","Step 3: a = 4 m/s²"],"options":[],"conceptId":"physics_force_motion_and_mechanics_newton_s_second_law_of_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q8","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Newton''s Second Law of Motion"}', 7),
  (2183, 529, 'A force of 15 N produces an acceleration of 3 m/s². Find the object''s mass.', 'text', 1, 'Rearrange F = ma.', '{"why":"Mass equals resultant force divided by acceleration.","sol":"Step 1: m = F/a\nStep 2: m = 15/3\nStep 3: m = 5 kg","steps":["Step 1: m = F/a","Step 2: m = 15/3","Step 3: m = 5 kg"],"options":[],"conceptId":"physics_force_motion_and_mechanics_newton_s_second_law_of_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q9","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Newton''s Second Law of Motion"}', 8),
  (2184, 529, 'A learner uses the largest individual force in F = ma even though other forces oppose it. What should the learner use?', 'text', 1, 'Find the overall effect of all the forces.', '{"why":"Newton''s second law uses the net force acting on the object.","sol":"Step 1: Determine the direction of each force.\nStep 2: Combine the forces to find the resultant.\nStep 3: Use the resultant force in F = ma.","steps":["Step 1: Determine the direction of each force.","Step 2: Combine the forces to find the resultant.","Step 3: Use the resultant force in F = ma."],"options":[],"conceptId":"physics_force_motion_and_mechanics_newton_s_second_law_of_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q10","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Newton''s Second Law of Motion"}', 9),
  (2185, 530, 'A person pushes a wall with a force of 50 N. What force does the wall exert on the person?', 'text', 1, 'Use Newton''s third law.', '{"why":"The wall and person exert equal and opposite forces on each other.","sol":"Step 1: Identify the force exerted on the wall.\nStep 2: Apply the equal-and-opposite rule.\nStep 3: Identify the force acting on the person.","steps":["Step 1: Identify the force exerted on the wall.","Step 2: Apply the equal-and-opposite rule.","Step 3: Identify the force acting on the person."],"options":[],"conceptId":"physics_force_motion_and_mechanics_newton_s_third_law_of_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Newton''s Third Law of Motion"}', 0),
  (2186, 530, 'A swimmer pushes water backward. In which direction does the water''s force on the swimmer act?', 'text', 1, 'The reaction force opposes the swimmer''s force on the water.', '{"why":"The forward reaction force helps propel the swimmer.","sol":"Step 1: The swimmer exerts a backward force on the water.\nStep 2: The water exerts an opposite force on the swimmer.\nStep 3: State the direction.","steps":["Step 1: The swimmer exerts a backward force on the water.","Step 2: The water exerts an opposite force on the swimmer.","Step 3: State the direction."],"options":[],"conceptId":"physics_force_motion_and_mechanics_newton_s_third_law_of_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Newton''s Third Law of Motion"}', 1),
  (2187, 530, 'Why do action and reaction forces not cancel each other on a single object?', 'text', 1, 'Identify the object on which each force acts.', '{"why":"Forces cancel as a resultant only when they act on the same object.","sol":"Step 1: Identify the first force and its object.\nStep 2: Identify the reaction force and its object.\nStep 3: Compare the objects.","steps":["Step 1: Identify the first force and its object.","Step 2: Identify the reaction force and its object.","Step 3: Compare the objects."],"options":[],"conceptId":"physics_force_motion_and_mechanics_newton_s_third_law_of_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Newton''s Third Law of Motion"}', 2),
  (2188, 530, 'A hammer exerts a force of 100 N on a nail. What is the magnitude of the force exerted by the nail on the hammer?', 'text', 1, 'The force pair has equal magnitude.', '{"why":"The nail exerts an equal-magnitude force on the hammer in the opposite direction.","sol":"Step 1: Identify the hammer''s force on the nail.\nStep 2: Apply Newton''s third law.\nStep 3: Give the reaction force''s magnitude.","steps":["Step 1: Identify the hammer''s force on the nail.","Step 2: Apply Newton''s third law.","Step 3: Give the reaction force''s magnitude."],"options":[],"conceptId":"physics_force_motion_and_mechanics_newton_s_third_law_of_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Newton''s Third Law of Motion"}', 3),
  (2189, 530, 'A book presses down on a table. Which object experiences the reaction force to the book''s downward force on the table?', 'text', 1, 'The reaction must act on the other member of the interaction.', '{"why":"The table pushes upward on the book while the book pushes downward on the table.","sol":"Step 1: Identify the book''s force on the table.\nStep 2: Find the equal and opposite force.\nStep 3: Name the object on which it acts.","steps":["Step 1: Identify the book''s force on the table.","Step 2: Find the equal and opposite force.","Step 3: Name the object on which it acts."],"options":[],"conceptId":"physics_force_motion_and_mechanics_newton_s_third_law_of_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Newton''s Third Law of Motion"}', 4),
  (2190, 530, 'State Newton''s third law of motion.', 'text', 1, 'Consider the forces between two interacting objects.', '{"why":"The forces occur together and act on different objects.","sol":"Step 1: Object A exerts a force on object B.\nStep 2: Object B exerts an equal and opposite force on object A.","steps":["Step 1: Object A exerts a force on object B.","Step 2: Object B exerts an equal and opposite force on object A."],"options":[],"conceptId":"physics_force_motion_and_mechanics_newton_s_third_law_of_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q6","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Newton''s Third Law of Motion"}', 5),
  (2191, 530, 'A swimmer pushes water backward. In which direction does the water exert a force on the swimmer?', 'text', 1, 'The reaction force is opposite to the swimmer''s force on the water.', '{"why":"The forward reaction force helps propel the swimmer.","sol":"Step 1: The swimmer pushes water backward.\nStep 2: The water exerts an opposite force on the swimmer.\nStep 3: The force on the swimmer is forward.","steps":["Step 1: The swimmer pushes water backward.","Step 2: The water exerts an opposite force on the swimmer.","Step 3: The force on the swimmer is forward."],"options":[],"conceptId":"physics_force_motion_and_mechanics_newton_s_third_law_of_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q7","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Newton''s Third Law of Motion"}', 6),
  (2192, 530, 'A person pushes a wall with 40 N. What force does the wall exert on the person?', 'text', 1, 'Use Newton''s third law.', '{"why":"The interaction forces have equal magnitudes and opposite directions.","sol":"Step 1: The person exerts 40 N on the wall.\nStep 2: The wall exerts an equal force in the opposite direction.","steps":["Step 1: The person exerts 40 N on the wall.","Step 2: The wall exerts an equal force in the opposite direction."],"options":[],"conceptId":"physics_force_motion_and_mechanics_newton_s_third_law_of_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q8","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Newton''s Third Law of Motion"}', 7),
  (2193, 530, 'Why do action and reaction forces not cancel on the same object?', 'text', 1, 'Identify where each force acts.', '{"why":"Only forces acting on the same object can cancel in its force balance.","sol":"Step 1: The action force acts on one object.\nStep 2: The reaction force acts on the other object.\nStep 3: They therefore act on different objects.","steps":["Step 1: The action force acts on one object.","Step 2: The reaction force acts on the other object.","Step 3: They therefore act on different objects."],"options":[],"conceptId":"physics_force_motion_and_mechanics_newton_s_third_law_of_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q9","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Newton''s Third Law of Motion"}', 8),
  (2194, 530, 'A learner says a horse cannot pull a cart because the cart pulls the horse backward with an equal force. What is wrong with this reasoning?', 'text', 1, 'Consider the forces acting on the horse and the cart separately.', '{"why":"Newton''s third law does not prevent motion; the system''s external forces determine its acceleration.","sol":"Step 1: The horse pulls the cart.\nStep 2: The cart pulls the horse in the opposite direction.\nStep 3: These forces act on different objects; other external forces determine the motion of the horse-cart system.","steps":["Step 1: The horse pulls the cart.","Step 2: The cart pulls the horse in the opposite direction.","Step 3: These forces act on different objects; other external forces determine the motion of the horse-cart system."],"options":[],"conceptId":"physics_force_motion_and_mechanics_newton_s_third_law_of_motion","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q10","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Newton''s Third Law of Motion"}', 9),
  (2195, 531, 'Which has greater inertia: a 12 kg cart or a 4 kg cart?', 'text', 1, 'Compare their masses.', '{"why":"Greater mass means greater inertia.","sol":"Step 1: Identify the two masses.\nStep 2: Recall that mass measures inertia.\nStep 3: Compare the values.","steps":["Step 1: Identify the two masses.","Step 2: Recall that mass measures inertia.","Step 3: Compare the values."],"options":[],"conceptId":"physics_force_motion_and_mechanics_mass_and_inertia","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Mass and Inertia"}', 0),
  (2196, 531, 'What is the SI unit of mass?', 'text', 1, 'It is not the newton.', '{"why":"The newton is the unit of force, including weight.","sol":"Step 1: Identify mass as a quantity.\nStep 2: Recall its SI unit.\nStep 3: Distinguish it from the unit of weight.","steps":["Step 1: Identify mass as a quantity.","Step 2: Recall its SI unit.","Step 3: Distinguish it from the unit of weight."],"options":[],"conceptId":"physics_force_motion_and_mechanics_mass_and_inertia","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Mass and Inertia"}', 1),
  (2197, 531, 'An object is moved from Earth to the Moon. What happens to its mass?', 'text', 1, 'Mass is different from weight.', '{"why":"Changing location changes gravitational field strength, not the object''s mass.","sol":"Step 1: Recall that mass measures inertia.\nStep 2: Consider whether the object''s amount of matter changes.\nStep 3: Distinguish mass from gravitational force.","steps":["Step 1: Recall that mass measures inertia.","Step 2: Consider whether the object''s amount of matter changes.","Step 3: Distinguish mass from gravitational force."],"options":[],"conceptId":"physics_force_motion_and_mechanics_mass_and_inertia","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Mass and Inertia"}', 2),
  (2198, 531, 'Why is a heavily loaded trolley harder to accelerate than an empty trolley under the same resultant force?', 'text', 1, 'Use F = ma.', '{"why":"For a fixed resultant force, acceleration decreases as mass increases.","sol":"Step 1: The loaded trolley has greater mass.\nStep 2: Rearrange to a = F ÷ m.\nStep 3: Compare acceleration for the same force.","steps":["Step 1: The loaded trolley has greater mass.","Step 2: Rearrange to a = F ÷ m.","Step 3: Compare acceleration for the same force."],"options":[],"conceptId":"physics_force_motion_and_mechanics_mass_and_inertia","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Mass and Inertia"}', 3),
  (2199, 531, 'A 5 kg object is on Earth and then on the Moon. Which quantity changes because gravity is weaker on the Moon: mass or weight?', 'text', 1, 'Weight depends on gravitational field strength.', '{"why":"The gravitational field strength is lower on the Moon, so the object''s weight is lower.","sol":"Step 1: Mass is measured in kilograms and stays constant.\nStep 2: Weight = mass × gravitational field strength.\nStep 3: Identify the changing quantity.","steps":["Step 1: Mass is measured in kilograms and stays constant.","Step 2: Weight = mass × gravitational field strength.","Step 3: Identify the changing quantity."],"options":[],"conceptId":"physics_force_motion_and_mechanics_mass_and_inertia","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Mass and Inertia"}', 4),
  (2200, 531, 'What is inertia?', 'text', 1, 'It describes resistance to a change in motion.', '{"why":"Inertia explains why changing an object''s velocity requires a resultant force.","sol":"Step 1: An object tends to maintain its state of rest or motion.\nStep 2: Resistance to a change in that state is called inertia.","steps":["Step 1: An object tends to maintain its state of rest or motion.","Step 2: Resistance to a change in that state is called inertia."],"options":[],"conceptId":"physics_force_motion_and_mechanics_mass_and_inertia","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q6","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Mass and Inertia"}', 5),
  (2201, 531, 'Which has greater inertia: a 2 kg object or a 10 kg object?', 'text', 1, 'Compare their masses.', '{"why":"The object with greater mass has greater inertia.","sol":"Step 1: Mass measures inertia.\nStep 2: 10 kg is greater than 2 kg.","steps":["Step 1: Mass measures inertia.","Step 2: 10 kg is greater than 2 kg."],"options":[],"conceptId":"physics_force_motion_and_mechanics_mass_and_inertia","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q7","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Mass and Inertia"}', 6),
  (2202, 531, 'A 4 kg object experiences a resultant force of 12 N. Calculate its acceleration.', 'text', 1, 'Use a = F/m.', '{"why":"Acceleration equals resultant force divided by mass.","sol":"Step 1: a = 12/4\nStep 2: a = 3 m/s²","steps":["Step 1: a = 12/4","Step 2: a = 3 m/s²"],"options":[],"conceptId":"physics_force_motion_and_mechanics_mass_and_inertia","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q8","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Mass and Inertia"}', 7),
  (2203, 531, 'Two objects experience the same resultant force. Why does the object with greater mass have a smaller acceleration?', 'text', 1, 'Use Newton''s second law.', '{"why":"Mass measures resistance to acceleration.","sol":"Step 1: a = F/m.\nStep 2: The force is the same for both objects.\nStep 3: A greater mass gives a smaller value of F/m.","steps":["Step 1: a = F/m.","Step 2: The force is the same for both objects.","Step 3: A greater mass gives a smaller value of F/m."],"options":[],"conceptId":"physics_force_motion_and_mechanics_mass_and_inertia","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q9","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Mass and Inertia"}', 8),
  (2204, 531, 'Is inertia a force?', 'text', 1, 'Think about whether inertia is an interaction or a property.', '{"why":"Inertia is a property of matter, not an additional force acting on an object.","sol":"Step 1: Inertia describes an object''s resistance to changes in motion.\nStep 2: It is a property associated with mass, not a separate force.","steps":["Step 1: Inertia describes an object''s resistance to changes in motion.","Step 2: It is a property associated with mass, not a separate force."],"options":[],"conceptId":"physics_force_motion_and_mechanics_mass_and_inertia","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q10","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Mass and Inertia"}', 9),
  (2205, 532, 'A resultant force of 35 N acts on a 7 kg object. Calculate acceleration.', 'text', 1, 'a = F ÷ m.', '{"why":"Acceleration is the resultant force divided by mass.","sol":"Step 1: a = 35 ÷ 7.\nStep 2: Calculate the quotient.\nStep 3: State the unit.","steps":["Step 1: a = 35 ÷ 7.","Step 2: Calculate the quotient.","Step 3: State the unit."],"options":[],"conceptId":"physics_force_motion_and_mechanics_force_mass_and_acceleration_calculations","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Force, Mass and Acceleration Calculations"}', 0),
  (2206, 532, 'An object accelerates at 4 m/s² under a resultant force of 28 N. Calculate its mass.', 'text', 1, 'm = F ÷ a.', '{"why":"Mass is force divided by acceleration.","sol":"Step 1: m = 28 ÷ 4.\nStep 2: Calculate the mass.\nStep 3: Include kilograms.","steps":["Step 1: m = 28 ÷ 4.","Step 2: Calculate the mass.","Step 3: Include kilograms."],"options":[],"conceptId":"physics_force_motion_and_mechanics_force_mass_and_acceleration_calculations","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Force, Mass and Acceleration Calculations"}', 1),
  (2207, 532, 'A 6 kg object accelerates at 1.5 m/s². Find the resultant force.', 'text', 1, 'F = ma.', '{"why":"Force is proportional to mass and acceleration.","sol":"Step 1: F = 6 × 1.5.\nStep 2: Calculate the product.\nStep 3: Include newtons.","steps":["Step 1: F = 6 × 1.5.","Step 2: Calculate the product.","Step 3: Include newtons."],"options":[],"conceptId":"physics_force_motion_and_mechanics_force_mass_and_acceleration_calculations","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Force, Mass and Acceleration Calculations"}', 2),
  (2208, 532, 'A 10 kg object experiences a 50 N force to the right and a 20 N force to the left. Calculate its acceleration.', 'text', 1, 'Find the resultant force first.', '{"why":"Newton''s second law uses the resultant, not the individual 50 N force.","sol":"Step 1: Resultant force = 50 − 20 = 30 N to the right.\nStep 2: a = F ÷ m = 30 ÷ 10.\nStep 3: State the magnitude and direction.","steps":["Step 1: Resultant force = 50 − 20 = 30 N to the right.","Step 2: a = F ÷ m = 30 ÷ 10.","Step 3: State the magnitude and direction."],"options":[],"conceptId":"physics_force_motion_and_mechanics_force_mass_and_acceleration_calculations","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Force, Mass and Acceleration Calculations"}', 3),
  (2209, 532, 'A 4 kg object experiences a resultant force of 0 N. What is its acceleration?', 'text', 1, 'Use a = F ÷ m.', '{"why":"A zero resultant force gives zero acceleration.","sol":"Step 1: a = 0 ÷ 4.\nStep 2: Evaluate the expression.\nStep 3: State the result.","steps":["Step 1: a = 0 ÷ 4.","Step 2: Evaluate the expression.","Step 3: State the result."],"options":[],"conceptId":"physics_force_motion_and_mechanics_force_mass_and_acceleration_calculations","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Force, Mass and Acceleration Calculations"}', 4),
  (2210, 533, 'Calculate the weight of a 5 kg object where g = 10 N/kg.', 'text', 1, 'Use W = mg.', '{"why":"Weight is mass multiplied by gravitational field strength.","sol":"Step 1: W = 5 × 10.\nStep 2: Calculate the product.\nStep 3: State the unit.","steps":["Step 1: W = 5 × 10.","Step 2: Calculate the product.","Step 3: State the unit."],"options":[],"conceptId":"physics_force_motion_and_mechanics_mass_and_weight","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Mass and Weight"}', 0),
  (2211, 533, 'An object has weight 80 N where g = 10 N/kg. Calculate its mass.', 'text', 1, 'Rearrange W = mg.', '{"why":"Mass is weight divided by gravitational field strength.","sol":"Step 1: m = W ÷ g.\nStep 2: m = 80 ÷ 10.\nStep 3: State the mass in kilograms.","steps":["Step 1: m = W ÷ g.","Step 2: m = 80 ÷ 10.","Step 3: State the mass in kilograms."],"options":[],"conceptId":"physics_force_motion_and_mechanics_mass_and_weight","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Mass and Weight"}', 1),
  (2212, 533, 'A 3 kg object is on the Moon, where g = 1.6 N/kg. Calculate its weight.', 'text', 1, 'Use the Moon''s gravitational field strength.', '{"why":"Weight depends on local gravitational field strength.","sol":"Step 1: W = mg.\nStep 2: W = 3 × 1.6.\nStep 3: State the result in newtons.","steps":["Step 1: W = mg.","Step 2: W = 3 × 1.6.","Step 3: State the result in newtons."],"options":[],"conceptId":"physics_force_motion_and_mechanics_mass_and_weight","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Mass and Weight"}', 2),
  (2213, 533, 'An object has a mass of 2 kg on Earth and on the Moon. What is its mass on the Moon?', 'text', 1, 'Mass does not depend on gravitational field strength.', '{"why":"Its mass remains constant when it is moved to another location.","sol":"Step 1: Identify the given mass.\nStep 2: Recall the meaning of mass.\nStep 3: State the mass at the new location.","steps":["Step 1: Identify the given mass.","Step 2: Recall the meaning of mass.","Step 3: State the mass at the new location."],"options":[],"conceptId":"physics_force_motion_and_mechanics_mass_and_weight","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Mass and Weight"}', 3),
  (2214, 533, 'A 10 kg object weighs 98 N. Calculate the gravitational field strength.', 'text', 1, 'g = W ÷ m.', '{"why":"Gravitational field strength is weight per unit mass.","sol":"Step 1: g = 98 ÷ 10.\nStep 2: Calculate the result.\nStep 3: State N/kg.","steps":["Step 1: g = 98 ÷ 10.","Step 2: Calculate the result.","Step 3: State N/kg."],"options":[],"conceptId":"physics_force_motion_and_mechanics_mass_and_weight","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Mass and Weight"}', 4),
  (2215, 534, 'A 5 kg object weighs 50 N. Calculate gravitational field strength.', 'text', 1, 'g = W ÷ m.', '{"why":"Field strength is gravitational force per unit mass.","sol":"Step 1: g = 50 ÷ 5.\nStep 2: Calculate the quotient.\nStep 3: State the unit.","steps":["Step 1: g = 50 ÷ 5.","Step 2: Calculate the quotient.","Step 3: State the unit."],"options":[],"conceptId":"physics_force_motion_and_mechanics_gravitational_field_strength","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Gravitational Field Strength"}', 0),
  (2216, 534, 'A 2 kg object has a weight of 19.6 N. Calculate g.', 'text', 1, 'Divide weight by mass.', '{"why":"The result gives the gravitational force on each kilogram.","sol":"Step 1: g = 19.6 ÷ 2.\nStep 2: Calculate the value.\nStep 3: Include N/kg.","steps":["Step 1: g = 19.6 ÷ 2.","Step 2: Calculate the value.","Step 3: Include N/kg."],"options":[],"conceptId":"physics_force_motion_and_mechanics_gravitational_field_strength","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Gravitational Field Strength"}', 1),
  (2217, 534, 'What does a gravitational field strength of 8 N/kg mean?', 'text', 1, 'Interpret the phrase ''per unit mass''.', '{"why":"Field strength is force per kilogram.","sol":"Step 1: Read N/kg as newtons per kilogram.\nStep 2: Consider a mass of 1 kg.\nStep 3: State the gravitational force on it.","steps":["Step 1: Read N/kg as newtons per kilogram.","Step 2: Consider a mass of 1 kg.","Step 3: State the gravitational force on it."],"options":[],"conceptId":"physics_force_motion_and_mechanics_gravitational_field_strength","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Gravitational Field Strength"}', 2),
  (2218, 534, 'A 10 kg object is in a field of 3 N/kg. Calculate its weight.', 'text', 1, 'W = mg.', '{"why":"Weight is mass multiplied by field strength.","sol":"Step 1: W = 10 × 3.\nStep 2: Calculate the product.\nStep 3: State the force in newtons.","steps":["Step 1: W = 10 × 3.","Step 2: Calculate the product.","Step 3: State the force in newtons."],"options":[],"conceptId":"physics_force_motion_and_mechanics_gravitational_field_strength","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Gravitational Field Strength"}', 3),
  (2219, 534, 'An object''s mass is 6 kg on Earth and on the Moon. Why can its weight differ?', 'text', 1, 'Compare the local values of g.', '{"why":"Weight changes with g even when mass stays constant.","sol":"Step 1: Weight = mg.\nStep 2: The mass remains 6 kg.\nStep 3: The gravitational field strength differs by location.","steps":["Step 1: Weight = mg.","Step 2: The mass remains 6 kg.","Step 3: The gravitational field strength differs by location."],"options":[],"conceptId":"physics_force_motion_and_mechanics_gravitational_field_strength","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Gravitational Field Strength"}', 4),
  (2220, 535, 'Calculate the weight of a 4 kg object where g = 10 N/kg.', 'text', 1, 'Use W = mg.', '{"why":"Weight is the gravitational force on the object.","sol":"Step 1: W = 4 × 10.\nStep 2: Multiply the mass by the field strength.\nStep 3: State the answer in newtons.","steps":["Step 1: W = 4 × 10.","Step 2: Multiply the mass by the field strength.","Step 3: State the answer in newtons."],"options":[],"conceptId":"physics_force_motion_and_mechanics_calculating_weight","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Calculating Weight"}', 0),
  (2221, 535, 'A body has a mass of 12 kg. Calculate its weight where g = 9.8 N/kg.', 'text', 1, 'Multiply mass by 9.8.', '{"why":"The question specifies a gravitational field strength of 9.8 N/kg.","sol":"Step 1: W = mg.\nStep 2: W = 12 × 9.8.\nStep 3: Calculate the product.","steps":["Step 1: W = mg.","Step 2: W = 12 × 9.8.","Step 3: Calculate the product."],"options":[],"conceptId":"physics_force_motion_and_mechanics_calculating_weight","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Calculating Weight"}', 1),
  (2222, 535, 'An object weighs 60 N where g = 10 N/kg. Calculate its mass.', 'text', 1, 'Rearrange W = mg.', '{"why":"Mass is weight divided by gravitational field strength.","sol":"Step 1: m = W ÷ g.\nStep 2: m = 60 ÷ 10.\nStep 3: Include kilograms.","steps":["Step 1: m = W ÷ g.","Step 2: m = 60 ÷ 10.","Step 3: Include kilograms."],"options":[],"conceptId":"physics_force_motion_and_mechanics_calculating_weight","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Calculating Weight"}', 2),
  (2223, 535, 'A 2 kg object is on the Moon, where g = 1.6 N/kg. Calculate its weight.', 'text', 1, 'Use the Moon''s field strength, not Earth''s.', '{"why":"The object''s weight depends on the local gravitational field strength.","sol":"Step 1: W = mg.\nStep 2: W = 2 × 1.6.\nStep 3: State the result in newtons.","steps":["Step 1: W = mg.","Step 2: W = 2 × 1.6.","Step 3: State the result in newtons."],"options":[],"conceptId":"physics_force_motion_and_mechanics_calculating_weight","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Calculating Weight"}', 3),
  (2224, 535, 'A student calculates the weight of a 500 g object using W = 500 × 10. What should be corrected?', 'text', 1, 'The formula requires mass in kilograms.', '{"why":"Using grams directly in W = mg gives an incorrect result.","sol":"Step 1: Convert 500 g to kilograms.\nStep 2: 500 g = 0.5 kg.\nStep 3: Calculate W = 0.5 × 10.","steps":["Step 1: Convert 500 g to kilograms.","Step 2: 500 g = 0.5 kg.","Step 3: Calculate W = 0.5 × 10."],"options":[],"conceptId":"physics_force_motion_and_mechanics_calculating_weight","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Calculating Weight"}', 4),
  (2225, 536, 'A block has mass 300 g and volume 100 cm³. Calculate its density.', 'text', 1, 'Density = mass ÷ volume.', '{"why":"Each cubic centimetre contains 3 g of mass.","sol":"Step 1: Write density = 300 ÷ 100.\nStep 2: Calculate the quotient.\nStep 3: Include g/cm³.","steps":["Step 1: Write density = 300 ÷ 100.","Step 2: Calculate the quotient.","Step 3: Include g/cm³."],"options":[],"conceptId":"physics_force_motion_and_mechanics_density","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Density"}', 0),
  (2226, 536, 'An object has mass 2 kg and volume 0.5 m³. Calculate its density.', 'text', 1, 'Keep the units in kg and m³.', '{"why":"Density is the mass divided by the volume occupied.","sol":"Step 1: Density = mass ÷ volume.\nStep 2: Density = 2 ÷ 0.5.\nStep 3: State kg/m³.","steps":["Step 1: Density = mass ÷ volume.","Step 2: Density = 2 ÷ 0.5.","Step 3: State kg/m³."],"options":[],"conceptId":"physics_force_motion_and_mechanics_density","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Density"}', 1),
  (2227, 536, 'A material has density 8 g/cm³ and volume 5 cm³. Calculate its mass.', 'text', 1, 'Rearrange density = mass ÷ volume.', '{"why":"Mass equals density multiplied by volume.","sol":"Step 1: Mass = density × volume.\nStep 2: Mass = 8 × 5.\nStep 3: Include grams.","steps":["Step 1: Mass = density × volume.","Step 2: Mass = 8 × 5.","Step 3: Include grams."],"options":[],"conceptId":"physics_force_motion_and_mechanics_density","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Density"}', 2),
  (2228, 536, 'A liquid has mass 900 g and density 1.5 g/cm³. Calculate its volume.', 'text', 1, 'Volume = mass ÷ density.', '{"why":"Dividing mass by density gives the volume.","sol":"Step 1: Volume = 900 ÷ 1.5.\nStep 2: Calculate the quotient.\nStep 3: State cm³.","steps":["Step 1: Volume = 900 ÷ 1.5.","Step 2: Calculate the quotient.","Step 3: State cm³."],"options":[],"conceptId":"physics_force_motion_and_mechanics_density","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Density"}', 3),
  (2229, 536, 'Two blocks have equal volumes. Block A has mass 200 g and block B has mass 500 g. Which has greater density?', 'text', 1, 'Compare mass when volume is the same.', '{"why":"For equal volumes, the greater mass corresponds to the greater density.","sol":"Step 1: Density = mass ÷ volume.\nStep 2: Both blocks have the same volume.\nStep 3: The block with greater mass has greater density.","steps":["Step 1: Density = mass ÷ volume.","Step 2: Both blocks have the same volume.","Step 3: The block with greater mass has greater density."],"options":[],"conceptId":"physics_force_motion_and_mechanics_density","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Density"}', 4),
  (2230, 537, 'A stone has mass 240 g and volume 80 cm³. Calculate its density.', 'text', 1, 'Divide mass by volume.', '{"why":"Density is mass per unit volume.","sol":"Step 1: ρ = m/V.\nStep 2: ρ = 240 ÷ 80.\nStep 3: State the unit.","steps":["Step 1: ρ = m/V.","Step 2: ρ = 240 ÷ 80.","Step 3: State the unit."],"options":[],"conceptId":"physics_force_motion_and_mechanics_calculating_density","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Calculating Density"}', 0),
  (2231, 537, 'A cube has side length 2 cm and mass 64 g. Calculate its density.', 'text', 1, 'First calculate the cube''s volume.', '{"why":"The density calculation requires the cube''s full volume, not just one side.","sol":"Step 1: Volume = side³ = 2 × 2 × 2 = 8 cm³.\nStep 2: Density = 64 ÷ 8.\nStep 3: State g/cm³.","steps":["Step 1: Volume = side³ = 2 × 2 × 2 = 8 cm³.","Step 2: Density = 64 ÷ 8.","Step 3: State g/cm³."],"options":[],"conceptId":"physics_force_motion_and_mechanics_calculating_density","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Calculating Density"}', 1),
  (2232, 537, 'A liquid has density 2 g/cm³ and volume 35 cm³. Find its mass.', 'text', 1, 'Mass = density × volume.', '{"why":"Multiplying density by volume gives mass.","sol":"Step 1: m = ρV.\nStep 2: m = 2 × 35.\nStep 3: State the mass.","steps":["Step 1: m = ρV.","Step 2: m = 2 × 35.","Step 3: State the mass."],"options":[],"conceptId":"physics_force_motion_and_mechanics_calculating_density","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Calculating Density"}', 2),
  (2233, 537, 'A solid has mass 150 g and density 3 g/cm³. Calculate its volume.', 'text', 1, 'V = m/ρ.', '{"why":"Volume equals mass divided by density.","sol":"Step 1: V = 150 ÷ 3.\nStep 2: Calculate the quotient.\nStep 3: Include cm³.","steps":["Step 1: V = 150 ÷ 3.","Step 2: Calculate the quotient.","Step 3: Include cm³."],"options":[],"conceptId":"physics_force_motion_and_mechanics_calculating_density","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Calculating Density"}', 3),
  (2234, 537, 'An irregular stone raises the water level in a measuring cylinder from 40 cm³ to 65 cm³. Its mass is 75 g. Calculate its density.', 'text', 1, 'The increase in water volume equals the stone''s volume if it is fully submerged and does not absorb water.', '{"why":"Liquid displacement measures the volume of the submerged irregular solid.","sol":"Step 1: Volume = 65 − 40 = 25 cm³.\nStep 2: Density = 75 ÷ 25.\nStep 3: State the result.","steps":["Step 1: Volume = 65 − 40 = 25 cm³.","Step 2: Density = 75 ÷ 25.","Step 3: State the result."],"options":[],"conceptId":"physics_force_motion_and_mechanics_calculating_density","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Calculating Density"}', 4),
  (2235, 538, 'A liquid has density 2 g/cm³. Calculate its relative density using water density 1 g/cm³.', 'text', 1, 'Divide the substance''s density by water''s density.', '{"why":"Relative density is a ratio and has no unit.","sol":"Step 1: Relative density = 2 ÷ 1.\nStep 2: Calculate the ratio.\nStep 3: Do not attach a unit.","steps":["Step 1: Relative density = 2 ÷ 1.","Step 2: Calculate the ratio.","Step 3: Do not attach a unit."],"options":[],"conceptId":"physics_force_motion_and_mechanics_relative_density","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Relative Density"}', 0),
  (2236, 538, 'A substance has density 800 kg/m³. Take water density as 1000 kg/m³. Find its relative density.', 'text', 1, 'Use the same density units in numerator and denominator.', '{"why":"The substance has 0.8 times the density of water.","sol":"Step 1: Relative density = 800 ÷ 1000.\nStep 2: Calculate the ratio.\nStep 3: State it without a unit.","steps":["Step 1: Relative density = 800 ÷ 1000.","Step 2: Calculate the ratio.","Step 3: State it without a unit."],"options":[],"conceptId":"physics_force_motion_and_mechanics_relative_density","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Relative Density"}', 1),
  (2237, 538, 'A solid has relative density 7 and volume 10 cm³. Take water density as 1 g/cm³. Calculate the solid''s mass.', 'text', 1, 'First convert relative density into density.', '{"why":"Relative density 7 corresponds to a density of 7 g/cm³ under the stated reference.","sol":"Step 1: Density = 7 × 1 = 7 g/cm³.\nStep 2: Mass = density × volume.\nStep 3: Mass = 7 × 10.","steps":["Step 1: Density = 7 × 1 = 7 g/cm³.","Step 2: Mass = density × volume.","Step 3: Mass = 7 × 10."],"options":[],"conceptId":"physics_force_motion_and_mechanics_relative_density","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Relative Density"}', 2),
  (2238, 538, 'A liquid has relative density 0.75. What is its density in kg/m³ if water density is 1000 kg/m³?', 'text', 1, 'Density = relative density × water density.', '{"why":"Relative density gives the ratio of the substance''s density to water''s density.","sol":"Step 1: Density = 0.75 × 1000.\nStep 2: Calculate the product.\nStep 3: State kg/m³.","steps":["Step 1: Density = 0.75 × 1000.","Step 2: Calculate the product.","Step 3: State kg/m³."],"options":[],"conceptId":"physics_force_motion_and_mechanics_relative_density","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Relative Density"}', 3),
  (2239, 538, 'A student writes the relative density of a substance as 1.4 g/cm³. What is wrong?', 'text', 1, 'Check whether a ratio has a unit.', '{"why":"A ratio of compatible density units has no remaining unit.","sol":"Step 1: Relative density is density divided by density.\nStep 2: The units cancel.\nStep 3: Remove the unit.","steps":["Step 1: Relative density is density divided by density.","Step 2: The units cancel.","Step 3: Remove the unit."],"options":[],"conceptId":"physics_force_motion_and_mechanics_relative_density","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Relative Density"}', 4),
  (2240, 539, 'A box slides to the right across a rough floor. In which direction does kinetic friction act?', 'text', 1, 'Friction opposes relative sliding.', '{"why":"Kinetic friction opposes the relative sliding of the surfaces.","sol":"Step 1: Identify the sliding direction.\nStep 2: Apply the opposing-force rule.\nStep 3: State the friction direction.","steps":["Step 1: Identify the sliding direction.","Step 2: Apply the opposing-force rule.","Step 3: State the friction direction."],"options":[],"conceptId":"physics_force_motion_and_mechanics_causes_of_friction","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Causes of Friction"}', 0),
  (2241, 539, 'Why can a rough surface produce greater friction than a smooth surface?', 'text', 1, 'Think about microscopic surface irregularities and contact.', '{"why":"Friction depends partly on the nature of the contacting surfaces.","sol":"Step 1: Surfaces have microscopic features.\nStep 2: These features interact during sliding.\nStep 3: Relate the interactions to resistance.","steps":["Step 1: Surfaces have microscopic features.","Step 2: These features interact during sliding.","Step 3: Relate the interactions to resistance."],"options":[],"conceptId":"physics_force_motion_and_mechanics_causes_of_friction","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Causes of Friction"}', 1),
  (2242, 539, 'A person pushes a stationary heavy box, but it does not move. What type of friction can oppose the attempted motion?', 'text', 1, 'The surfaces have not begun sliding.', '{"why":"Static friction opposes the tendency for surfaces to begin moving relative to one another.","sol":"Step 1: The box remains stationary.\nStep 2: Relative sliding has not started.\nStep 3: Identify the friction involved.","steps":["Step 1: The box remains stationary.","Step 2: Relative sliding has not started.","Step 3: Identify the friction involved."],"options":[],"conceptId":"physics_force_motion_and_mechanics_causes_of_friction","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Causes of Friction"}', 2),
  (2243, 539, 'Why can applying oil to a moving machine part reduce friction?', 'text', 1, 'Consider what the lubricant does between surfaces.', '{"why":"Lubrication reduces resistance and can also limit wear.","sol":"Step 1: Oil forms a lubricating layer.\nStep 2: The layer reduces direct contact between surface irregularities.\nStep 3: Relate this to friction.","steps":["Step 1: Oil forms a lubricating layer.","Step 2: The layer reduces direct contact between surface irregularities.","Step 3: Relate this to friction."],"options":[],"conceptId":"physics_force_motion_and_mechanics_causes_of_friction","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Causes of Friction"}', 3),
  (2244, 539, 'A box is pushed harder against a floor. What generally happens to the maximum static friction if the surfaces remain unchanged?', 'text', 1, 'Consider the normal contact force.', '{"why":"For the same surfaces, maximum static friction is approximately proportional to the normal force.","sol":"Step 1: A harder downward push increases the normal force.\nStep 2: Maximum static friction depends on normal force.\nStep 3: State the general effect.","steps":["Step 1: A harder downward push increases the normal force.","Step 2: Maximum static friction depends on normal force.","Step 3: State the general effect."],"options":[],"conceptId":"physics_force_motion_and_mechanics_causes_of_friction","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Causes of Friction"}', 4),
  (2245, 540, 'Why is friction between shoes and the ground useful when walking?', 'text', 1, 'Think about preventing the foot from slipping.', '{"why":"Friction enables the foot to push against the ground without sliding uncontrollably.","sol":"Step 1: The foot pushes against the ground.\nStep 2: Friction provides grip.\nStep 3: Explain how grip helps walking.","steps":["Step 1: The foot pushes against the ground.","Step 2: Friction provides grip.","Step 3: Explain how grip helps walking."],"options":[],"conceptId":"physics_force_motion_and_mechanics_effects_of_friction","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Effects of Friction"}', 0),
  (2246, 540, 'State one undesirable effect of friction in a machine.', 'text', 1, 'Consider energy transfer and surface contact.', '{"why":"Friction can damage surfaces and transfer mechanical energy into thermal energy.","sol":"Step 1: Identify the moving contacting parts.\nStep 2: Consider what friction transfers or changes.\nStep 3: Give one effect.","steps":["Step 1: Identify the moving contacting parts.","Step 2: Consider what friction transfers or changes.","Step 3: Give one effect."],"options":[],"conceptId":"physics_force_motion_and_mechanics_effects_of_friction","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Effects of Friction"}', 1),
  (2247, 540, 'How does friction help a car stop when its brakes are applied?', 'text', 1, 'The brakes oppose wheel motion.', '{"why":"Braking friction reduces the vehicle''s kinetic energy.","sol":"Step 1: Brakes create frictional forces.\nStep 2: These forces oppose motion.\nStep 3: Kinetic energy is transferred to other forms.","steps":["Step 1: Brakes create frictional forces.","Step 2: These forces oppose motion.","Step 3: Kinetic energy is transferred to other forms."],"options":[],"conceptId":"physics_force_motion_and_mechanics_effects_of_friction","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Effects of Friction"}', 2),
  (2248, 540, 'Why can friction between moving machine parts reduce efficiency?', 'text', 1, 'Not all input energy becomes useful output.', '{"why":"Energy dissipated by friction reduces the fraction available for useful work.","sol":"Step 1: The machine receives energy.\nStep 2: Friction transfers some energy to unwanted heating and sound.\nStep 3: Compare useful output with input.","steps":["Step 1: The machine receives energy.","Step 2: Friction transfers some energy to unwanted heating and sound.","Step 3: Compare useful output with input."],"options":[],"conceptId":"physics_force_motion_and_mechanics_effects_of_friction","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Effects of Friction"}', 3),
  (2249, 540, 'A person cannot walk easily on a very slippery surface. Which useful effect of friction is missing?', 'text', 1, 'Walking requires a force against the ground without slipping.', '{"why":"Without enough friction, the foot slides instead of pushing effectively against the ground.","sol":"Step 1: Identify the lack of grip.\nStep 2: Relate grip to friction.\nStep 3: Explain the difficulty walking.","steps":["Step 1: Identify the lack of grip.","Step 2: Relate grip to friction.","Step 3: Explain the difficulty walking."],"options":[],"conceptId":"physics_force_motion_and_mechanics_effects_of_friction","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Effects of Friction"}', 4),
  (2250, 541, 'Give one advantage of friction when writing with a pencil.', 'text', 1, 'Consider the contact between the pencil and paper.', '{"why":"Contact and friction allow graphite to be deposited on the paper.","sol":"Step 1: The pencil tip contacts the paper.\nStep 2: Friction helps material transfer to the paper.\nStep 3: State the advantage.","steps":["Step 1: The pencil tip contacts the paper.","Step 2: Friction helps material transfer to the paper.","Step 3: State the advantage."],"options":[],"conceptId":"physics_force_motion_and_mechanics_advantages_and_disadvantages_of_friction","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Advantages and Disadvantages of Friction"}', 0);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (2251, 541, 'Give one disadvantage of friction between moving engine parts.', 'text', 1, 'Think about energy loss or surface damage.', '{"why":"Friction can dissipate useful mechanical energy and damage surfaces.","sol":"Step 1: The parts rub against each other.\nStep 2: Friction can produce heat and wear.\nStep 3: State one disadvantage.","steps":["Step 1: The parts rub against each other.","Step 2: Friction can produce heat and wear.","Step 3: State one disadvantage."],"options":[],"conceptId":"physics_force_motion_and_mechanics_advantages_and_disadvantages_of_friction","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Advantages and Disadvantages of Friction"}', 1),
  (2252, 541, 'Why is friction between a vehicle''s tyres and the road an advantage?', 'text', 1, 'Think about starting, steering and stopping.', '{"why":"Without sufficient friction, tyres may slide and control is reduced.","sol":"Step 1: Tyres contact the road.\nStep 2: Friction provides grip.\nStep 3: Explain its effect on vehicle control.","steps":["Step 1: Tyres contact the road.","Step 2: Friction provides grip.","Step 3: Explain its effect on vehicle control."],"options":[],"conceptId":"physics_force_motion_and_mechanics_advantages_and_disadvantages_of_friction","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Advantages and Disadvantages of Friction"}', 2),
  (2253, 541, 'Why is friction between a moving shaft and its bearing often undesirable?', 'text', 1, 'Consider heating and wear.', '{"why":"These effects can damage the machine and reduce efficiency.","sol":"Step 1: The surfaces move relative to each other.\nStep 2: Friction opposes their motion.\nStep 3: Identify the unwanted results.","steps":["Step 1: The surfaces move relative to each other.","Step 2: Friction opposes their motion.","Step 3: Identify the unwanted results."],"options":[],"conceptId":"physics_force_motion_and_mechanics_advantages_and_disadvantages_of_friction","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Advantages and Disadvantages of Friction"}', 3),
  (2254, 541, 'A designer adds a rough grip to a tool handle. Is the intended effect to increase or decrease friction?', 'text', 1, 'The handle should not slip from the user''s hand.', '{"why":"Greater grip helps prevent the handle from slipping.","sol":"Step 1: Identify the need for grip.\nStep 2: Grip depends on friction.\nStep 3: Choose the required change.","steps":["Step 1: Identify the need for grip.","Step 2: Grip depends on friction.","Step 3: Choose the required change."],"options":[],"conceptId":"physics_force_motion_and_mechanics_advantages_and_disadvantages_of_friction","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Advantages and Disadvantages of Friction"}', 4),
  (2255, 542, 'Which method is commonly used to reduce friction between moving engine parts?', 'text', 1, 'Think of a substance placed between the surfaces.', '{"why":"Lubricants reduce direct contact and resistance between moving surfaces.","sol":"Step 1: Identify the contacting moving parts.\nStep 2: Consider a lubricant.\nStep 3: Name a suitable method.","steps":["Step 1: Identify the contacting moving parts.","Step 2: Consider a lubricant.","Step 3: Name a suitable method."],"options":[],"conceptId":"physics_force_motion_and_mechanics_reducing_and_increasing_friction","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Reducing and Increasing Friction"}', 0),
  (2256, 542, 'Why are ball bearings used in wheels?', 'text', 1, 'They change the type of motion between surfaces.', '{"why":"Rolling resistance is generally lower than sliding friction in this application.","sol":"Step 1: Identify the relative motion of the parts.\nStep 2: Ball bearings allow rolling.\nStep 3: Relate rolling to resistance.","steps":["Step 1: Identify the relative motion of the parts.","Step 2: Ball bearings allow rolling.","Step 3: Relate rolling to resistance."],"options":[],"conceptId":"physics_force_motion_and_mechanics_reducing_and_increasing_friction","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Reducing and Increasing Friction"}', 1),
  (2257, 542, 'Why do vehicle tyres have tread patterns?', 'text', 1, 'Consider grip, especially on wet roads.', '{"why":"Tread helps water escape from the contact area and supports traction.","sol":"Step 1: Tyres need road grip.\nStep 2: Tread patterns help channel water and maintain contact.\nStep 3: Explain the intended benefit.","steps":["Step 1: Tyres need road grip.","Step 2: Tread patterns help channel water and maintain contact.","Step 3: Explain the intended benefit."],"options":[],"conceptId":"physics_force_motion_and_mechanics_reducing_and_increasing_friction","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Reducing and Increasing Friction"}', 2),
  (2258, 542, 'A tool handle is too slippery. Suggest one way to increase friction.', 'text', 1, 'Change the surface where the hand grips.', '{"why":"A suitable textured surface can increase grip and reduce slipping.","sol":"Step 1: Identify the need for better grip.\nStep 2: Choose a rougher or higher-grip surface.\nStep 3: Give a practical example.","steps":["Step 1: Identify the need for better grip.","Step 2: Choose a rougher or higher-grip surface.","Step 3: Give a practical example."],"options":[],"conceptId":"physics_force_motion_and_mechanics_reducing_and_increasing_friction","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Reducing and Increasing Friction"}', 3),
  (2259, 542, 'Why is smoothing every surface not always the best way to manage friction?', 'text', 1, 'Some applications require grip.', '{"why":"Reducing friction is useful in machines but can be dangerous where traction is required.","sol":"Step 1: Identify a surface that needs traction.\nStep 2: Consider what happens if friction is too low.\nStep 3: Explain why surface design depends on purpose.","steps":["Step 1: Identify a surface that needs traction.","Step 2: Consider what happens if friction is too low.","Step 3: Explain why surface design depends on purpose."],"options":[],"conceptId":"physics_force_motion_and_mechanics_reducing_and_increasing_friction","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Reducing and Increasing Friction"}', 4),
  (2260, 543, 'A falling object has weight 60 N downward and air resistance 15 N upward. Calculate the resultant force.', 'text', 1, 'Take downward as positive and subtract the opposing forces.', '{"why":"Weight is greater than air resistance, so the resultant force is downward.","sol":"Step 1: Weight = +60 N.\nStep 2: Air resistance = −15 N.\nStep 3: Resultant force = 60 − 15.","steps":["Step 1: Weight = +60 N.","Step 2: Air resistance = −15 N.","Step 3: Resultant force = 60 − 15."],"options":[],"conceptId":"physics_force_motion_and_mechanics_air_resistance_and_terminal_velocity","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Air Resistance and Terminal Velocity"}', 0),
  (2261, 543, 'A falling object reaches terminal velocity. How do weight and air resistance compare?', 'text', 1, 'Terminal velocity means no acceleration.', '{"why":"Balanced forces produce zero resultant force.","sol":"Step 1: At terminal velocity, acceleration is zero.\nStep 2: Resultant force is therefore zero.\nStep 3: Compare the downward and upward forces.","steps":["Step 1: At terminal velocity, acceleration is zero.","Step 2: Resultant force is therefore zero.","Step 3: Compare the downward and upward forces."],"options":[],"conceptId":"physics_force_motion_and_mechanics_air_resistance_and_terminal_velocity","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Air Resistance and Terminal Velocity"}', 1),
  (2262, 543, 'Why does air resistance usually increase as a falling object''s speed increases?', 'text', 1, 'Consider how quickly the object moves through the air.', '{"why":"Air resistance depends on speed and the object''s shape and exposed area.","sol":"Step 1: The object moves faster through the air.\nStep 2: The interaction with air becomes stronger.\nStep 3: Relate this to the resistive force.","steps":["Step 1: The object moves faster through the air.","Step 2: The interaction with air becomes stronger.","Step 3: Relate this to the resistive force."],"options":[],"conceptId":"physics_force_motion_and_mechanics_air_resistance_and_terminal_velocity","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Air Resistance and Terminal Velocity"}', 2),
  (2263, 543, 'A parachutist opens a parachute. Explain why the parachutist slows down initially.', 'text', 1, 'The parachute greatly increases exposed area.', '{"why":"A force opposite the direction of motion reduces speed.","sol":"Step 1: Opening the parachute increases air resistance.\nStep 2: Air resistance becomes greater than weight for a period.\nStep 3: The resultant force acts upward while the parachutist moves downward.","steps":["Step 1: Opening the parachute increases air resistance.","Step 2: Air resistance becomes greater than weight for a period.","Step 3: The resultant force acts upward while the parachutist moves downward."],"options":[],"conceptId":"physics_force_motion_and_mechanics_air_resistance_and_terminal_velocity","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Air Resistance and Terminal Velocity"}', 3),
  (2264, 543, 'A falling object has weight 50 N and air resistance 50 N. If it is already moving downward, what happens to its speed?', 'text', 1, 'Calculate the resultant force first.', '{"why":"Balanced forces mean no acceleration, not necessarily that the object is stationary.","sol":"Step 1: Resultant force = 50 − 50 = 0 N.\nStep 2: Zero resultant force means zero acceleration.\nStep 3: Describe its velocity.","steps":["Step 1: Resultant force = 50 − 50 = 0 N.","Step 2: Zero resultant force means zero acceleration.","Step 3: Describe its velocity."],"options":[],"conceptId":"physics_force_motion_and_mechanics_air_resistance_and_terminal_velocity","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Air Resistance and Terminal Velocity"}', 4),
  (2265, 544, 'What is the approximate acceleration due to gravity near Earth''s surface?', 'text', 1, 'Use the standard school value.', '{"why":"The local gravitational acceleration near Earth''s surface is about 9.8 m/s².","sol":"Step 1: The approximate value is 9.8 m/s².\nStep 2: Some school calculations use 10 m/s².","steps":["Step 1: The approximate value is 9.8 m/s².","Step 2: Some school calculations use 10 m/s²."],"options":[],"conceptId":"physics_force_motion_and_mechanics_acceleration_due_to_gravity","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Acceleration Due to Gravity"}', 0),
  (2266, 544, 'An object starts from rest and falls for 2 s. Find its final speed using g = 10 m/s².', 'text', 1, 'Use v = u + gt.', '{"why":"The speed increases by 10 m/s each second under the stated approximation.","sol":"Step 1: u = 0 m/s, g = 10 m/s², t = 2 s.\nStep 2: v = 0 + 10 × 2.\nStep 3: v = 20 m/s downward.","steps":["Step 1: u = 0 m/s, g = 10 m/s², t = 2 s.","Step 2: v = 0 + 10 × 2.","Step 3: v = 20 m/s downward."],"options":[],"conceptId":"physics_force_motion_and_mechanics_acceleration_due_to_gravity","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Acceleration Due to Gravity"}', 1),
  (2267, 544, 'A falling object''s speed increases from 5 m/s to 25 m/s in 2 s. Calculate its acceleration.', 'text', 1, 'Use a = (v − u)/t.', '{"why":"Acceleration is the change in velocity divided by time.","sol":"Step 1: a = (25 − 5)/2\nStep 2: a = 20/2\nStep 3: a = 10 m/s²","steps":["Step 1: a = (25 − 5)/2","Step 2: a = 20/2","Step 3: a = 10 m/s²"],"options":[],"conceptId":"physics_force_motion_and_mechanics_acceleration_due_to_gravity","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Acceleration Due to Gravity"}', 2),
  (2268, 544, 'Which is the correct unit for acceleration?', 'text', 1, 'Acceleration is the change in velocity per second.', '{"why":"Acceleration measures velocity change per unit time.","sol":"Step 1: Velocity is measured in m/s.\nStep 2: Divide a change in velocity by seconds.\nStep 3: The unit is m/s².","steps":["Step 1: Velocity is measured in m/s.","Step 2: Divide a change in velocity by seconds.","Step 3: The unit is m/s²."],"options":[],"conceptId":"physics_force_motion_and_mechanics_acceleration_due_to_gravity","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Acceleration Due to Gravity"}', 3),
  (2269, 544, 'A learner writes g = 10 m/s. What is wrong?', 'text', 1, 'Check whether g is a speed or an acceleration.', '{"why":"m/s is a velocity unit; m/s² is an acceleration unit.","sol":"Step 1: g represents gravitational acceleration.\nStep 2: Acceleration is measured in m/s², not m/s.","steps":["Step 1: g represents gravitational acceleration.","Step 2: Acceleration is measured in m/s², not m/s."],"options":[],"conceptId":"physics_force_motion_and_mechanics_acceleration_due_to_gravity","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Acceleration Due to Gravity"}', 4),
  (2270, 545, 'A 10 N force acts rightward and a 4 N force acts leftward on a 2 kg object. Find its acceleration.', 'text', 1, 'Find the resultant force before using a = F/m.', '{"why":"Acceleration follows the direction of the resultant force.","sol":"Step 1: Resultant force = 10 − 4 = 6 N rightward.\nStep 2: a = 6/2\nStep 3: a = 3 m/s² rightward.","steps":["Step 1: Resultant force = 10 − 4 = 6 N rightward.","Step 2: a = 6/2","Step 3: a = 3 m/s² rightward."],"options":[],"conceptId":"physics_force_motion_and_mechanics_calculating_acceleration_from_resultant_force","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Calculating Acceleration from Resultant Force"}', 0),
  (2271, 545, 'Two opposite forces of 15 N and 15 N act on a 5 kg object. Find its acceleration.', 'text', 1, 'Equal opposite forces cancel.', '{"why":"A zero resultant force produces zero acceleration.","sol":"Step 1: Resultant force = 15 − 15 = 0 N.\nStep 2: a = F/m = 0/5 = 0 m/s².","steps":["Step 1: Resultant force = 15 − 15 = 0 N.","Step 2: a = F/m = 0/5 = 0 m/s²."],"options":[],"conceptId":"physics_force_motion_and_mechanics_calculating_acceleration_from_resultant_force","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Calculating Acceleration from Resultant Force"}', 1),
  (2272, 545, 'A 3 kg box experiences 18 N east and 6 N west. Calculate its acceleration.', 'text', 1, 'Subtract the opposing forces.', '{"why":"The net force is 12 N eastward.","sol":"Step 1: Resultant force = 18 − 6 = 12 N east.\nStep 2: a = 12/3\nStep 3: a = 4 m/s² east.","steps":["Step 1: Resultant force = 18 − 6 = 12 N east.","Step 2: a = 12/3","Step 3: a = 4 m/s² east."],"options":[],"conceptId":"physics_force_motion_and_mechanics_calculating_acceleration_from_resultant_force","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Calculating Acceleration from Resultant Force"}', 2),
  (2273, 545, 'A 6 kg trolley accelerates at 2 m/s² to the left. What is the resultant force?', 'text', 1, 'Use F = ma and keep the direction.', '{"why":"The resultant force has the same direction as the acceleration.","sol":"Step 1: F = 6 × 2\nStep 2: F = 12 N leftward.","steps":["Step 1: F = 6 × 2","Step 2: F = 12 N leftward."],"options":[],"conceptId":"physics_force_motion_and_mechanics_calculating_acceleration_from_resultant_force","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Calculating Acceleration from Resultant Force"}', 3),
  (2274, 545, 'A 5 kg object is pulled with 30 N to the right while friction is 10 N to the left. A learner calculates acceleration as 30/5. What is the error?', 'text', 1, 'The pulling force is not the resultant force.', '{"why":"All forces must be combined before applying Newton''s second law.","sol":"Step 1: Resultant force = 30 − 10 = 20 N right.\nStep 2: a = 20/5 = 4 m/s² right.","steps":["Step 1: Resultant force = 30 − 10 = 20 N right.","Step 2: a = 20/5 = 4 m/s² right."],"options":[],"conceptId":"physics_force_motion_and_mechanics_calculating_acceleration_from_resultant_force","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Calculating Acceleration from Resultant Force"}', 4),
  (2275, 546, 'A force of 50 N produces an acceleration of 5 m/s². Find the mass.', 'text', 1, 'Use m = F/a.', '{"why":"Mass is resultant force divided by acceleration.","sol":"Step 1: m = 50/5\nStep 2: m = 10 kg","steps":["Step 1: m = 50/5","Step 2: m = 10 kg"],"options":[],"conceptId":"physics_force_motion_and_mechanics_calculating_force_and_mass","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Calculating Force and Mass"}', 0),
  (2276, 546, 'A 7 kg object accelerates at 3 m/s². Calculate the resultant force.', 'text', 1, 'Use F = ma.', '{"why":"Force is the product of mass and acceleration.","sol":"Step 1: F = 7 × 3\nStep 2: F = 21 N","steps":["Step 1: F = 7 × 3","Step 2: F = 21 N"],"options":[],"conceptId":"physics_force_motion_and_mechanics_calculating_force_and_mass","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Calculating Force and Mass"}', 1),
  (2277, 546, 'A resultant force of 48 N acts on a 12 kg object. Find its acceleration.', 'text', 1, 'Use a = F/m.', '{"why":"Acceleration is resultant force divided by mass.","sol":"Step 1: a = 48/12\nStep 2: a = 4 m/s²","steps":["Step 1: a = 48/12","Step 2: a = 4 m/s²"],"options":[],"conceptId":"physics_force_motion_and_mechanics_calculating_force_and_mass","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Calculating Force and Mass"}', 2),
  (2278, 546, 'A 2 kg object accelerates at 6 m/s². What force is acting on it as a resultant?', 'text', 1, 'Multiply mass by acceleration.', '{"why":"The resultant force equals mass multiplied by acceleration.","sol":"Step 1: F = 2 × 6\nStep 2: F = 12 N","steps":["Step 1: F = 2 × 6","Step 2: F = 12 N"],"options":[],"conceptId":"physics_force_motion_and_mechanics_calculating_force_and_mass","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Calculating Force and Mass"}', 3),
  (2279, 546, 'A student calculates mass by multiplying force by acceleration. Correct the method.', 'text', 1, 'Rearrange F = ma to isolate mass.', '{"why":"Dividing by acceleration isolates mass in the equation.","sol":"Step 1: Start with F = ma.\nStep 2: Divide both sides by a.\nStep 3: m = F/a.","steps":["Step 1: Start with F = ma.","Step 2: Divide both sides by a.","Step 3: m = F/a."],"options":[],"conceptId":"physics_force_motion_and_mechanics_calculating_force_and_mass","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Calculating Force and Mass"}', 4),
  (2280, 547, 'A book pushes down on a table. What is the reaction force?', 'text', 1, 'Name the force exerted by the table on the book.', '{"why":"The two contact forces act on different objects.","sol":"Step 1: The book exerts a downward force on the table.\nStep 2: The table exerts an equal upward force on the book.","steps":["Step 1: The book exerts a downward force on the table.","Step 2: The table exerts an equal upward force on the book."],"options":[],"conceptId":"physics_force_motion_and_mechanics_action_reaction_force_pairs","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Action-Reaction Force Pairs"}', 0),
  (2281, 547, 'Are a book''s weight and the table''s upward support force a Newton''s third-law pair?', 'text', 1, 'Check whether both forces act on the same object.', '{"why":"Third-law forces act on different objects.","sol":"Step 1: The book''s weight acts on the book.\nStep 2: The support force also acts on the book.\nStep 3: They are not a third-law pair.","steps":["Step 1: The book''s weight acts on the book.","Step 2: The support force also acts on the book.","Step 3: They are not a third-law pair."],"options":[],"conceptId":"physics_force_motion_and_mechanics_action_reaction_force_pairs","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Action-Reaction Force Pairs"}', 1),
  (2282, 547, 'Earth pulls a falling stone downward. What is the corresponding reaction force?', 'text', 1, 'Reverse the two interacting objects.', '{"why":"Gravitational forces occur between both interacting bodies.","sol":"Step 1: Earth exerts a gravitational force on the stone.\nStep 2: The stone exerts an equal and opposite gravitational force on Earth.","steps":["Step 1: Earth exerts a gravitational force on the stone.","Step 2: The stone exerts an equal and opposite gravitational force on Earth."],"options":[],"conceptId":"physics_force_motion_and_mechanics_action_reaction_force_pairs","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Action-Reaction Force Pairs"}', 2),
  (2283, 547, 'A swimmer pushes water backward with 25 N. State the force exerted by the water on the swimmer.', 'text', 1, 'Equal magnitude, opposite direction.', '{"why":"The reaction force is equal in magnitude and opposite in direction.","sol":"Step 1: The swimmer''s force is 25 N backward on the water.\nStep 2: The water''s reaction is 25 N forward on the swimmer.","steps":["Step 1: The swimmer''s force is 25 N backward on the water.","Step 2: The water''s reaction is 25 N forward on the swimmer."],"options":[],"conceptId":"physics_force_motion_and_mechanics_action_reaction_force_pairs","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Action-Reaction Force Pairs"}', 3),
  (2284, 547, 'Two students say that the action and reaction forces cancel because they are equal and opposite. What question should you ask to check their claim?', 'text', 1, 'Consider the objects on which the forces act.', '{"why":"The objects involved determine whether forces can cancel in a single-object force balance.","sol":"Step 1: Identify the object receiving the first force.\nStep 2: Identify the object receiving the second force.\nStep 3: If the objects differ, the forces do not cancel on one object''s force balance.","steps":["Step 1: Identify the object receiving the first force.","Step 2: Identify the object receiving the second force.","Step 3: If the objects differ, the forces do not cancel on one object''s force balance."],"options":[],"conceptId":"physics_force_motion_and_mechanics_action_reaction_force_pairs","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Action-Reaction Force Pairs"}', 4),
  (2285, 548, 'Why does a passenger tend to move forward when a moving car stops suddenly?', 'text', 1, 'The passenger''s body was moving before the car stopped.', '{"why":"The body resists the sudden change in velocity.","sol":"Step 1: The car decelerates rapidly.\nStep 2: The passenger''s body tends to maintain its previous motion.\nStep 3: The passenger moves forward relative to the car.","steps":["Step 1: The car decelerates rapidly.","Step 2: The passenger''s body tends to maintain its previous motion.","Step 3: The passenger moves forward relative to the car."],"options":[],"conceptId":"physics_force_motion_and_mechanics_inertia_and_safety","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Inertia and Safety"}', 0),
  (2286, 548, 'How does a seat belt help during sudden braking?', 'text', 1, 'It restrains the passenger.', '{"why":"The seat belt reduces the risk of the passenger continuing forward unchecked.","sol":"Step 1: The passenger tends to continue moving forward.\nStep 2: The seat belt exerts a force on the passenger.\nStep 3: That force helps decelerate the passenger with the vehicle.","steps":["Step 1: The passenger tends to continue moving forward.","Step 2: The seat belt exerts a force on the passenger.","Step 3: That force helps decelerate the passenger with the vehicle."],"options":[],"conceptId":"physics_force_motion_and_mechanics_inertia_and_safety","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Inertia and Safety"}', 1),
  (2287, 548, 'Why might a standing passenger lean backward relative to a bus when it accelerates forward?', 'text', 1, 'Consider the passenger''s initial state of rest.', '{"why":"Inertia resists the change in motion as the bus accelerates.","sol":"Step 1: The bus begins moving forward.\nStep 2: The passenger''s body tends to remain at rest.\nStep 3: Relative to the bus, the passenger appears to lean backward.","steps":["Step 1: The bus begins moving forward.","Step 2: The passenger''s body tends to remain at rest.","Step 3: Relative to the bus, the passenger appears to lean backward."],"options":[],"conceptId":"physics_force_motion_and_mechanics_inertia_and_safety","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Inertia and Safety"}', 2),
  (2288, 548, 'Is inertia itself the forward force that moves a passenger during braking?', 'text', 1, 'Inertia is a property, not an interaction force.', '{"why":"Inertia describes the tendency to maintain motion; it is not a force.","sol":"Step 1: Inertia is resistance to a change in motion.\nStep 2: It is not a separate force.\nStep 3: The passenger''s motion changes when external forces act.","steps":["Step 1: Inertia is resistance to a change in motion.","Step 2: It is not a separate force.","Step 3: The passenger''s motion changes when external forces act."],"options":[],"conceptId":"physics_force_motion_and_mechanics_inertia_and_safety","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Inertia and Safety"}', 3),
  (2289, 548, 'Two vehicles travel at the same speed and brake similarly. Why may occupants in the heavier vehicle still need effective restraints?', 'text', 1, 'Consider what happens to moving occupants when the vehicle slows.', '{"why":"Seat belts help restrain occupants during changes in vehicle motion.","sol":"Step 1: Occupants have inertia because they have mass.\nStep 2: When the vehicle decelerates, their bodies tend to continue moving.\nStep 3: Restraints provide forces to slow them safely.","steps":["Step 1: Occupants have inertia because they have mass.","Step 2: When the vehicle decelerates, their bodies tend to continue moving.","Step 3: Restraints provide forces to slow them safely."],"options":[],"conceptId":"physics_force_motion_and_mechanics_inertia_and_safety","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Inertia and Safety"}', 4),
  (2290, 549, 'Two people push a box to the right with forces of 15 N and 25 N. Find the resultant force.', 'text', 1, 'Both forces act in the same direction.', '{"why":"Forces in the same direction add together.","sol":"Step 1: R = 15 + 25\nStep 2: R = 40 N to the right.","steps":["Step 1: R = 15 + 25","Step 2: R = 40 N to the right."],"options":[],"conceptId":"physics_force_motion_and_mechanics_resultant_force_in_the_same_direction","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Resultant Force in the Same Direction"}', 0),
  (2291, 549, 'Two forces of 12 N and 18 N act eastward. Calculate their resultant.', 'text', 1, 'Add the two forces.', '{"why":"Both forces act eastward.","sol":"Step 1: R = 12 + 18\nStep 2: R = 30 N eastward.","steps":["Step 1: R = 12 + 18","Step 2: R = 30 N eastward."],"options":[],"conceptId":"physics_force_motion_and_mechanics_resultant_force_in_the_same_direction","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Resultant Force in the Same Direction"}', 1),
  (2292, 549, 'A 6 kg trolley experiences a resultant force of 24 N eastward. Find its acceleration.', 'text', 1, 'Use a = R/m.', '{"why":"Acceleration equals resultant force divided by mass.","sol":"Step 1: a = 24/6\nStep 2: a = 4 m/s² eastward.","steps":["Step 1: a = 24/6","Step 2: a = 4 m/s² eastward."],"options":[],"conceptId":"physics_force_motion_and_mechanics_resultant_force_in_the_same_direction","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Resultant Force in the Same Direction"}', 2),
  (2293, 549, 'Three forces of 5 N, 7 N and 8 N act in the same direction. Find their resultant.', 'text', 1, 'Add all three magnitudes.', '{"why":"All three forces contribute to the same direction of resultant force.","sol":"Step 1: R = 5 + 7 + 8\nStep 2: R = 20 N.","steps":["Step 1: R = 5 + 7 + 8","Step 2: R = 20 N."],"options":[],"conceptId":"physics_force_motion_and_mechanics_resultant_force_in_the_same_direction","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Resultant Force in the Same Direction"}', 3),
  (2294, 549, 'A learner subtracts two forces of 10 N and 20 N that both act forward. Identify the error.', 'text', 1, 'Check whether the forces oppose one another.', '{"why":"Subtraction is used when forces act in opposite directions.","sol":"Step 1: Both forces act forward.\nStep 2: Forces in the same direction are added.\nStep 3: R = 10 + 20 = 30 N forward.","steps":["Step 1: Both forces act forward.","Step 2: Forces in the same direction are added.","Step 3: R = 10 + 20 = 30 N forward."],"options":[],"conceptId":"physics_force_motion_and_mechanics_resultant_force_in_the_same_direction","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Resultant Force in the Same Direction"}', 4),
  (2295, 550, 'A box is pulled rightward by 40 N and leftward by 15 N. Find the resultant.', 'text', 1, 'Subtract the smaller opposing force.', '{"why":"The larger force acts to the right.","sol":"Step 1: R = 40 − 15\nStep 2: R = 25 N rightward.","steps":["Step 1: R = 40 − 15","Step 2: R = 25 N rightward."],"options":[],"conceptId":"physics_force_motion_and_mechanics_resultant_force_in_opposite_directions","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Resultant Force in Opposite Directions"}', 0),
  (2296, 550, 'A cart experiences 60 N eastward and 60 N westward. Find the resultant.', 'text', 1, 'Equal opposite forces cancel.', '{"why":"Equal forces in opposite directions cancel.","sol":"Step 1: R = 60 − 60\nStep 2: R = 0 N.","steps":["Step 1: R = 60 − 60","Step 2: R = 0 N."],"options":[],"conceptId":"physics_force_motion_and_mechanics_resultant_force_in_opposite_directions","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Resultant Force in Opposite Directions"}', 1),
  (2297, 550, 'A 5 kg object experiences a net force of 15 N northward. Calculate its acceleration.', 'text', 1, 'Use a = R/m.', '{"why":"The acceleration is in the direction of the resultant force.","sol":"Step 1: a = 15/5\nStep 2: a = 3 m/s² northward.","steps":["Step 1: a = 15/5","Step 2: a = 3 m/s² northward."],"options":[],"conceptId":"physics_force_motion_and_mechanics_resultant_force_in_opposite_directions","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Resultant Force in Opposite Directions"}', 2),
  (2298, 550, 'A tug-of-war team pulls with 500 N leftward while the opposing team pulls with 650 N rightward. Find the resultant.', 'text', 1, 'Subtract and follow the larger force.', '{"why":"The rightward force is larger by 150 N.","sol":"Step 1: R = 650 − 500\nStep 2: R = 150 N rightward.","steps":["Step 1: R = 650 − 500","Step 2: R = 150 N rightward."],"options":[],"conceptId":"physics_force_motion_and_mechanics_resultant_force_in_opposite_directions","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Resultant Force in Opposite Directions"}', 3),
  (2299, 550, 'A learner calculates 30 N − 50 N = 20 N rightward when the 50 N force acts rightward and the 30 N force acts leftward. Correct the answer.', 'text', 1, 'The direction must match the larger force.', '{"why":"The magnitude is correct, and the direction follows the 50 N force.","sol":"Step 1: Magnitude = 50 − 30 = 20 N.\nStep 2: The larger force acts rightward.","steps":["Step 1: Magnitude = 50 − 30 = 20 N.","Step 2: The larger force acts rightward."],"options":[],"conceptId":"physics_force_motion_and_mechanics_resultant_force_in_opposite_directions","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Resultant Force in Opposite Directions"}', 4),
  (2300, 551, 'What is the normal reaction force?', 'text', 1, 'It is a contact force from a surface.', '{"why":"The normal reaction is the surface''s perpendicular contact force.","sol":"Step 1: A surface is in contact with an object.\nStep 2: The surface exerts a force perpendicular to itself.","steps":["Step 1: A surface is in contact with an object.","Step 2: The surface exerts a force perpendicular to itself."],"options":[],"conceptId":"physics_force_motion_and_mechanics_the_normal_reaction_force","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"The Normal Reaction Force"}', 0),
  (2301, 551, 'A 3 kg box rests on a horizontal floor. Find its weight using g = 10 N/kg.', 'text', 1, 'Use W = mg.', '{"why":"Weight is mass multiplied by gravitational field strength.","sol":"Step 1: W = 3 × 10\nStep 2: W = 30 N downward.","steps":["Step 1: W = 3 × 10","Step 2: W = 30 N downward."],"options":[],"conceptId":"physics_force_motion_and_mechanics_the_normal_reaction_force","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"The Normal Reaction Force"}', 1),
  (2302, 551, 'A stationary 5 kg box rests on a horizontal floor with no other vertical forces. Find the normal reaction using g = 10 N/kg.', 'text', 1, 'Vertical forces are balanced.', '{"why":"The box has no vertical acceleration, so the vertical forces balance.","sol":"Step 1: Weight = 5 × 10 = 50 N downward.\nStep 2: The normal reaction balances the weight.\nStep 3: Normal reaction = 50 N upward.","steps":["Step 1: Weight = 5 × 10 = 50 N downward.","Step 2: The normal reaction balances the weight.","Step 3: Normal reaction = 50 N upward."],"options":[],"conceptId":"physics_force_motion_and_mechanics_the_normal_reaction_force","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"The Normal Reaction Force"}', 2),
  (2303, 551, 'A book rests on a level table. In which direction does the table''s normal reaction act on the book?', 'text', 1, 'The reaction is perpendicular to the table.', '{"why":"The normal reaction acts perpendicular to the contact surface.","sol":"Step 1: The table is horizontal.\nStep 2: The perpendicular direction is vertical.\nStep 3: The reaction acts upward on the book.","steps":["Step 1: The table is horizontal.","Step 2: The perpendicular direction is vertical.","Step 3: The reaction acts upward on the book."],"options":[],"conceptId":"physics_force_motion_and_mechanics_the_normal_reaction_force","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"The Normal Reaction Force"}', 3),
  (2304, 551, 'A learner claims the normal reaction is always equal to an object''s weight. Is this correct?', 'text', 1, 'Think about a box being pushed downward or an object accelerating vertically.', '{"why":"The normal reaction depends on the full force situation, not weight alone.","sol":"Step 1: Equality applies when the vertical forces balance in the stated simple situation.\nStep 2: Additional vertical forces or vertical acceleration can change the normal reaction.","steps":["Step 1: Equality applies when the vertical forces balance in the stated simple situation.","Step 2: Additional vertical forces or vertical acceleration can change the normal reaction."],"options":[],"conceptId":"physics_force_motion_and_mechanics_the_normal_reaction_force","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"The Normal Reaction Force"}', 4),
  (2305, 552, 'What is tension?', 'text', 1, 'Think of the force transmitted by a taut rope.', '{"why":"Tension acts along the length of the taut connector.","sol":"Step 1: A taut string or rope transmits a pulling force.\nStep 2: This force is called tension.","steps":["Step 1: A taut string or rope transmits a pulling force.","Step 2: This force is called tension."],"options":[],"conceptId":"physics_force_motion_and_mechanics_tension_in_a_string","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Tension in a String"}', 0),
  (2306, 552, 'A 4 kg mass hangs at rest from a string. Calculate the tension using g = 10 N/kg.', 'text', 1, 'The tension balances the weight.', '{"why":"The upward tension balances the downward weight.","sol":"Step 1: Weight = 4 × 10 = 40 N.\nStep 2: The mass is stationary.\nStep 3: Tension = 40 N upward.","steps":["Step 1: Weight = 4 × 10 = 40 N.","Step 2: The mass is stationary.","Step 3: Tension = 40 N upward."],"options":[],"conceptId":"physics_force_motion_and_mechanics_tension_in_a_string","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Tension in a String"}', 1),
  (2307, 552, 'In which direction does a vertical string pull a mass hanging from it?', 'text', 1, 'Tension pulls along the string.', '{"why":"A string can pull but does not push the hanging mass upward.","sol":"Step 1: The string is vertical.\nStep 2: Tension acts along the string.\nStep 3: The string pulls the mass upward.","steps":["Step 1: The string is vertical.","Step 2: Tension acts along the string.","Step 3: The string pulls the mass upward."],"options":[],"conceptId":"physics_force_motion_and_mechanics_tension_in_a_string","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Tension in a String"}', 2),
  (2308, 552, 'A 3 kg mass hangs at rest. Take g = 10 N/kg. What is the resultant force on the mass?', 'text', 1, 'The mass is not accelerating.', '{"why":"The upward and downward forces balance.","sol":"Step 1: Weight = 30 N downward.\nStep 2: Tension = 30 N upward.\nStep 3: Resultant force = 0 N.","steps":["Step 1: Weight = 30 N downward.","Step 2: Tension = 30 N upward.","Step 3: Resultant force = 0 N."],"options":[],"conceptId":"physics_force_motion_and_mechanics_tension_in_a_string","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Tension in a String"}', 3),
  (2309, 552, 'A learner says tension must equal weight whenever an object hangs from a string. What condition is missing?', 'text', 1, 'Compare a stationary mass with an accelerating one.', '{"why":"Tension equals weight only under the appropriate force-balance conditions.","sol":"Step 1: For a stationary hanging mass with no other forces, tension equals weight.\nStep 2: If the mass accelerates, the forces need not balance.","steps":["Step 1: For a stationary hanging mass with no other forces, tension equals weight.","Step 2: If the mass accelerates, the forces need not balance."],"options":[],"conceptId":"physics_force_motion_and_mechanics_tension_in_a_string","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Tension in a String"}', 4),
  (2310, 553, 'What does an arrow represent in a force diagram?', 'text', 1, 'Think about direction and magnitude.', '{"why":"Force diagrams use arrows to represent forces.","sol":"Step 1: The arrow points in the force direction.\nStep 2: Its length can represent magnitude when drawn to scale.","steps":["Step 1: The arrow points in the force direction.","Step 2: Its length can represent magnitude when drawn to scale."],"options":[],"conceptId":"physics_force_motion_and_mechanics_drawing_force_diagrams","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Drawing Force Diagrams"}', 0),
  (2311, 553, 'Which forces act on a book resting on a horizontal table, ignoring other effects?', 'text', 1, 'Consider gravity and the surface.', '{"why":"These are the two main forces acting on the resting book.","sol":"Step 1: Earth exerts weight downward.\nStep 2: The table exerts a normal reaction upward.","steps":["Step 1: Earth exerts weight downward.","Step 2: The table exerts a normal reaction upward."],"options":[],"conceptId":"physics_force_motion_and_mechanics_drawing_force_diagrams","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Drawing Force Diagrams"}', 1),
  (2312, 553, 'A stationary book has weight 12 N. What should the normal reaction arrow represent?', 'text', 1, 'The vertical forces balance.', '{"why":"The book has zero vertical acceleration.","sol":"Step 1: Weight is 12 N downward.\nStep 2: The normal reaction is 12 N upward.\nStep 3: The arrows should be equal in length on a consistent scale.","steps":["Step 1: Weight is 12 N downward.","Step 2: The normal reaction is 12 N upward.","Step 3: The arrows should be equal in length on a consistent scale."],"options":[],"conceptId":"physics_force_motion_and_mechanics_drawing_force_diagrams","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Drawing Force Diagrams"}', 2),
  (2313, 553, 'When drawing a force diagram for a book, should you include the book''s downward force on the table?', 'text', 1, 'The diagram is for the book only.', '{"why":"A force diagram includes forces acting on the chosen object.","sol":"Step 1: The book exerts a force on the table.\nStep 2: That force acts on the table, not on the book.\nStep 3: Do not include it in the book''s force diagram.","steps":["Step 1: The book exerts a force on the table.","Step 2: That force acts on the table, not on the book.","Step 3: Do not include it in the book''s force diagram."],"options":[],"conceptId":"physics_force_motion_and_mechanics_drawing_force_diagrams","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Drawing Force Diagrams"}', 3),
  (2314, 553, 'A box is pulled rightward while friction acts leftward. Which forces should appear in a complete basic force diagram on a level floor?', 'text', 1, 'Include contact, gravitational and applied forces.', '{"why":"The diagram must show all relevant forces acting on the box.","sol":"Step 1: Weight acts downward.\nStep 2: Normal reaction acts upward.\nStep 3: The applied pull acts rightward.\nStep 4: Friction acts leftward.","steps":["Step 1: Weight acts downward.","Step 2: Normal reaction acts upward.","Step 3: The applied pull acts rightward.","Step 4: Friction acts leftward."],"options":[],"conceptId":"physics_force_motion_and_mechanics_drawing_force_diagrams","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Drawing Force Diagrams"}', 4),
  (2315, 554, 'A 60 kg person stands in a stationary elevator. Calculate the scale reading using g = 10 N/kg.', 'text', 1, 'The normal reaction balances the weight.', '{"why":"With no vertical acceleration, the normal reaction equals the person''s weight.","sol":"Step 1: Weight = 60 × 10 = 600 N.\nStep 2: The elevator is stationary.\nStep 3: Scale reading = 600 N.","steps":["Step 1: Weight = 60 × 10 = 600 N.","Step 2: The elevator is stationary.","Step 3: Scale reading = 600 N."],"options":[],"conceptId":"physics_force_motion_and_mechanics_forces_on_an_object_in_an_elevator","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Forces on an Object in an Elevator"}', 0),
  (2316, 554, 'A 50 kg person accelerates upward at 2 m/s². Calculate the normal reaction using g = 10 m/s².', 'text', 1, 'Use R − mg = ma.', '{"why":"The upward resultant force is R − mg = ma.","sol":"Step 1: R = m(g + a)\nStep 2: R = 50(10 + 2)\nStep 3: R = 600 N","steps":["Step 1: R = m(g + a)","Step 2: R = 50(10 + 2)","Step 3: R = 600 N"],"options":[],"conceptId":"physics_force_motion_and_mechanics_forces_on_an_object_in_an_elevator","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Forces on an Object in an Elevator"}', 1),
  (2317, 554, 'A 40 kg person accelerates downward at 2 m/s². Calculate the normal reaction using g = 10 m/s².', 'text', 1, 'For downward acceleration, mg − R = ma.', '{"why":"The downward resultant force is the weight minus the normal reaction.","sol":"Step 1: R = m(g − a)\nStep 2: R = 40(10 − 2)\nStep 3: R = 320 N","steps":["Step 1: R = m(g − a)","Step 2: R = 40(10 − 2)","Step 3: R = 320 N"],"options":[],"conceptId":"physics_force_motion_and_mechanics_forces_on_an_object_in_an_elevator","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Forces on an Object in an Elevator"}', 2),
  (2318, 554, 'An elevator moves upward at constant velocity. How does the scale reading compare with the person''s weight?', 'text', 1, 'Constant velocity means zero acceleration.', '{"why":"The direction of motion does not determine the scale reading; acceleration does.","sol":"Step 1: Acceleration is zero.\nStep 2: The vertical forces balance.\nStep 3: The normal reaction equals weight.","steps":["Step 1: Acceleration is zero.","Step 2: The vertical forces balance.","Step 3: The normal reaction equals weight."],"options":[],"conceptId":"physics_force_motion_and_mechanics_forces_on_an_object_in_an_elevator","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Forces on an Object in an Elevator"}', 3),
  (2319, 554, 'Does a person''s mass increase when an elevator accelerates upward?', 'text', 1, 'Distinguish mass from scale reading.', '{"why":"Apparent weight can change without a change in mass.","sol":"Step 1: Mass is a measure of inertia.\nStep 2: The scale reading changes because the normal reaction changes.\nStep 3: The person''s mass remains the same.","steps":["Step 1: Mass is a measure of inertia.","Step 2: The scale reading changes because the normal reaction changes.","Step 3: The person''s mass remains the same."],"options":[],"conceptId":"physics_force_motion_and_mechanics_forces_on_an_object_in_an_elevator","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Forces on an Object in an Elevator"}', 4),
  (2320, 555, 'A 1,200 kg car decelerates at 2 m/s². Calculate the magnitude of its resultant braking force.', 'text', 1, 'Use F = ma with the deceleration magnitude.', '{"why":"The resultant force magnitude equals mass multiplied by acceleration magnitude.","sol":"Step 1: F = 1,200 × 2\nStep 2: F = 2,400 N","steps":["Step 1: F = 1,200 × 2","Step 2: F = 2,400 N"],"options":[],"conceptId":"physics_force_motion_and_mechanics_braking_force_and_deceleration","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Braking Force and Deceleration"}', 0),
  (2321, 555, 'In which direction does the resultant force act when a car moving forward slows down on a straight, level road?', 'text', 1, 'The force produces acceleration opposite the motion.', '{"why":"The resultant force has the direction of the acceleration.","sol":"Step 1: The car''s velocity is forward.\nStep 2: Its acceleration is backward while slowing down.\nStep 3: The resultant force is backward.","steps":["Step 1: The car''s velocity is forward.","Step 2: Its acceleration is backward while slowing down.","Step 3: The resultant force is backward."],"options":[],"conceptId":"physics_force_motion_and_mechanics_braking_force_and_deceleration","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Braking Force and Deceleration"}', 1),
  (2322, 555, 'A 500 kg cart experiences a resultant force of 1,000 N opposite its motion. Find the acceleration magnitude.', 'text', 1, 'Use a = F/m.', '{"why":"The acceleration magnitude is the force magnitude divided by mass.","sol":"Step 1: a = 1,000/500\nStep 2: a = 2 m/s²","steps":["Step 1: a = 1,000/500","Step 2: a = 2 m/s²"],"options":[],"conceptId":"physics_force_motion_and_mechanics_braking_force_and_deceleration","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Braking Force and Deceleration"}', 2),
  (2323, 555, 'A car is moving forward but its acceleration is backward. Is it speeding up or slowing down?', 'text', 1, 'Compare the directions of velocity and acceleration.', '{"why":"Acceleration opposite the velocity reduces the speed.","sol":"Step 1: Velocity is forward.\nStep 2: Acceleration is backward.\nStep 3: The speed decreases.","steps":["Step 1: Velocity is forward.","Step 2: Acceleration is backward.","Step 3: The speed decreases."],"options":[],"conceptId":"physics_force_motion_and_mechanics_braking_force_and_deceleration","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Braking Force and Deceleration"}', 3),
  (2324, 555, 'A learner says that a car must have a forward resultant force because it is moving forward. What is wrong?', 'text', 1, 'Motion direction and force direction are not always the same.', '{"why":"An object may move forward while accelerating backward.","sol":"Step 1: A moving car can have a backward resultant force while braking.\nStep 2: The resultant force follows acceleration, not necessarily velocity.","steps":["Step 1: A moving car can have a backward resultant force while braking.","Step 2: The resultant force follows acceleration, not necessarily velocity."],"options":[],"conceptId":"physics_force_motion_and_mechanics_braking_force_and_deceleration","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Braking Force and Deceleration"}', 4),
  (2325, 556, 'Define momentum.', 'text', 1, 'Multiply mass by velocity.', '{"why":"Momentum depends on both mass and velocity.","sol":"Step 1: Identify mass m and velocity v.\nStep 2: Use p = mv.","steps":["Step 1: Identify mass m and velocity v.","Step 2: Use p = mv."],"options":[],"conceptId":"physics_force_motion_and_mechanics_force_and_change_in_momentum","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Force and Change in Momentum"}', 0),
  (2326, 556, 'Calculate the momentum of a 4 kg object moving at 5 m/s eastward.', 'text', 1, 'Use p = mv.', '{"why":"Momentum is mass multiplied by velocity.","sol":"Step 1: p = 4 × 5\nStep 2: p = 20 kg m/s eastward.","steps":["Step 1: p = 4 × 5","Step 2: p = 20 kg m/s eastward."],"options":[],"conceptId":"physics_force_motion_and_mechanics_force_and_change_in_momentum","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Force and Change in Momentum"}', 1),
  (2327, 556, 'A 3 kg object moves at 2 m/s westward. Calculate its momentum magnitude.', 'text', 1, 'Multiply mass by speed for the magnitude.', '{"why":"The magnitude is the product of mass and speed.","sol":"Step 1: p = 3 × 2\nStep 2: Momentum magnitude = 6 kg m/s.","steps":["Step 1: p = 3 × 2","Step 2: Momentum magnitude = 6 kg m/s."],"options":[],"conceptId":"physics_force_motion_and_mechanics_force_and_change_in_momentum","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Force and Change in Momentum"}', 2),
  (2328, 556, 'What happens to an object''s momentum if its mass stays constant and its velocity doubles?', 'text', 1, 'Use p = mv.', '{"why":"Momentum is directly proportional to velocity at constant mass.","sol":"Step 1: p = mv.\nStep 2: If v doubles while m stays constant, p doubles.","steps":["Step 1: p = mv.","Step 2: If v doubles while m stays constant, p doubles."],"options":[],"conceptId":"physics_force_motion_and_mechanics_force_and_change_in_momentum","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Force and Change in Momentum"}', 3),
  (2329, 556, 'What is the SI unit of momentum?', 'text', 1, 'Multiply kilograms by metres per second.', '{"why":"Momentum is measured in kilogram metres per second.","sol":"Step 1: p = mv.\nStep 2: Unit = kg × m/s.\nStep 3: Unit = kg m/s.","steps":["Step 1: p = mv.","Step 2: Unit = kg × m/s.","Step 3: Unit = kg m/s."],"options":[],"conceptId":"physics_force_motion_and_mechanics_force_and_change_in_momentum","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Force and Change in Momentum"}', 4),
  (2330, 557, 'Define impulse.', 'text', 1, 'Relate force to the time it acts.', '{"why":"Impulse links the force acting over a time interval to momentum change.","sol":"Step 1: Impulse equals resultant force multiplied by time.\nStep 2: It is also equal to the change in momentum.","steps":["Step 1: Impulse equals resultant force multiplied by time.","Step 2: It is also equal to the change in momentum."],"options":[],"conceptId":"physics_force_motion_and_mechanics_impulse_and_impact_forces","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Impulse and Impact Forces"}', 0),
  (2331, 557, 'A force of 30 N acts for 0.2 s. Calculate the impulse.', 'text', 1, 'Use impulse = F × t.', '{"why":"Impulse is force multiplied by the time interval.","sol":"Step 1: Impulse = 30 × 0.2\nStep 2: Impulse = 6 N s","steps":["Step 1: Impulse = 30 × 0.2","Step 2: Impulse = 6 N s"],"options":[],"conceptId":"physics_force_motion_and_mechanics_impulse_and_impact_forces","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Impulse and Impact Forces"}', 1),
  (2332, 557, 'What is the unit of impulse?', 'text', 1, 'Multiply newtons by seconds.', '{"why":"A newton-second is equivalent to kg m/s.","sol":"Step 1: Impulse = force × time.\nStep 2: Unit = N s.","steps":["Step 1: Impulse = force × time.","Step 2: Unit = N s."],"options":[],"conceptId":"physics_force_motion_and_mechanics_impulse_and_impact_forces","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Impulse and Impact Forces"}', 2),
  (2333, 557, 'Why can an airbag reduce the average force on a passenger during a collision?', 'text', 1, 'For the same momentum change, consider the collision time.', '{"why":"A longer stopping time reduces average force for the same momentum change.","sol":"Step 1: The passenger''s momentum must change.\nStep 2: The airbag increases the time over which that change occurs.\nStep 3: Average force = change in momentum ÷ time, so it is reduced.","steps":["Step 1: The passenger''s momentum must change.","Step 2: The airbag increases the time over which that change occurs.","Step 3: Average force = change in momentum ÷ time, so it is reduced."],"options":[],"conceptId":"physics_force_motion_and_mechanics_impulse_and_impact_forces","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Impulse and Impact Forces"}', 3),
  (2334, 557, 'A ball''s momentum changes by 12 kg m/s in 0.4 s. Calculate the average resultant force magnitude.', 'text', 1, 'Use average force = change in momentum ÷ time.', '{"why":"Average resultant force is the momentum change divided by the time taken.","sol":"Step 1: F = 12/0.4\nStep 2: F = 30 N","steps":["Step 1: F = 12/0.4","Step 2: F = 30 N"],"options":[],"conceptId":"physics_force_motion_and_mechanics_impulse_and_impact_forces","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Impulse and Impact Forces"}', 4),
  (2335, 558, 'State the principle of conservation of momentum.', 'text', 1, 'Consider an isolated system.', '{"why":"Internal interactions do not change the system''s total momentum.","sol":"Step 1: The resultant external force is zero or its impulse is negligible.\nStep 2: Total momentum remains constant.","steps":["Step 1: The resultant external force is zero or its impulse is negligible.","Step 2: Total momentum remains constant."],"options":[],"conceptId":"physics_force_motion_and_mechanics_conservation_of_momentum","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q1","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Conservation of Momentum"}', 0),
  (2336, 558, 'A 2 kg trolley moves at 3 m/s. A second 1 kg trolley is stationary. They stick together. Find their final velocity.', 'text', 1, 'Conserve total momentum.', '{"why":"The combined trolley''s momentum must equal the initial total momentum.","sol":"Step 1: Initial momentum = (2 × 3) + (1 × 0) = 6 kg m/s.\nStep 2: Combined mass = 3 kg.\nStep 3: Final velocity = 6/3 = 2 m/s.","steps":["Step 1: Initial momentum = (2 × 3) + (1 × 0) = 6 kg m/s.","Step 2: Combined mass = 3 kg.","Step 3: Final velocity = 6/3 = 2 m/s."],"options":[],"conceptId":"physics_force_motion_and_mechanics_conservation_of_momentum","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q2","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Conservation of Momentum"}', 1),
  (2337, 558, 'A 1 kg object moves east at 6 m/s. Calculate its initial momentum.', 'text', 1, 'Use p = mv.', '{"why":"Momentum is mass multiplied by velocity.","sol":"Step 1: p = 1 × 6\nStep 2: p = 6 kg m/s eastward.","steps":["Step 1: p = 1 × 6","Step 2: p = 6 kg m/s eastward."],"options":[],"conceptId":"physics_force_motion_and_mechanics_conservation_of_momentum","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q3","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Conservation of Momentum"}', 2),
  (2338, 558, 'Why must directions be considered when applying momentum conservation to objects moving along a line?', 'text', 1, 'Momentum is a vector quantity.', '{"why":"Ignoring direction can give the wrong total momentum.","sol":"Step 1: Momentum has magnitude and direction.\nStep 2: Opposite directions must be assigned opposite signs.\nStep 3: The signed momenta are added to find the total.","steps":["Step 1: Momentum has magnitude and direction.","Step 2: Opposite directions must be assigned opposite signs.","Step 3: The signed momenta are added to find the total."],"options":[],"conceptId":"physics_force_motion_and_mechanics_conservation_of_momentum","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q4","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Conservation of Momentum"}', 3),
  (2339, 558, 'A learner says momentum is always conserved for a single object, even when a strong external force acts. What is wrong?', 'text', 1, 'The conservation principle applies to a system under specific conditions.', '{"why":"Momentum conservation is not an unconditional rule for every object.","sol":"Step 1: An external force can change an object''s momentum.\nStep 2: Momentum conservation applies when the system''s resultant external impulse is zero or negligible.","steps":["Step 1: An external force can change an object''s momentum.","Step 2: Momentum conservation applies when the system''s resultant external impulse is zero or negligible."],"options":[],"conceptId":"physics_force_motion_and_mechanics_conservation_of_momentum","skillId":"physics_force_motion_and_mechanics","subskillId":"physics_force_motion_and_mechanics_q5","subject":"physics","chapter":"force_motion_and_mechanics","topic":"Conservation of Momentum"}', 4),
  (2340, 559, 'Calculate the kinetic energy of a 2 kg object moving at 4 m/s.', 'text', 1, 'Use KE = ½mv².', '{"why":"Kinetic energy depends on mass and the square of speed.","sol":"Step 1: KE = ½ × 2 × 4²\nStep 2: KE = 1 × 16\nStep 3: KE = 16 J","steps":["Step 1: KE = ½ × 2 × 4²","Step 2: KE = 1 × 16","Step 3: KE = 16 J"],"options":[],"conceptId":"physics_work_energy_power_machines_kinetic_energy","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q1","subject":"physics","chapter":"work_energy_power_machines","topic":"Kinetic Energy"}', 0),
  (2341, 559, 'A 5 kg object moves at 2 m/s. Find its kinetic energy.', 'text', 1, 'Square 2 before multiplying.', '{"why":"Half the mass multiplied by speed squared gives kinetic energy.","sol":"Step 1: KE = ½ × 5 × 2²\nStep 2: KE = 2.5 × 4\nStep 3: KE = 10 J","steps":["Step 1: KE = ½ × 5 × 2²","Step 2: KE = 2.5 × 4","Step 3: KE = 10 J"],"options":[],"conceptId":"physics_work_energy_power_machines_kinetic_energy","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q2","subject":"physics","chapter":"work_energy_power_machines","topic":"Kinetic Energy"}', 1),
  (2342, 559, 'A 1,000 kg car moves at 10 m/s. Calculate its kinetic energy.', 'text', 1, 'Substitute the mass and speed into the formula.', '{"why":"The speed must be squared before the multiplication.","sol":"Step 1: KE = ½ × 1000 × 10²\nStep 2: KE = 500 × 100\nStep 3: KE = 50,000 J","steps":["Step 1: KE = ½ × 1000 × 10²","Step 2: KE = 500 × 100","Step 3: KE = 50,000 J"],"options":[],"conceptId":"physics_work_energy_power_machines_kinetic_energy","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q3","subject":"physics","chapter":"work_energy_power_machines","topic":"Kinetic Energy"}', 2),
  (2343, 559, 'What happens to kinetic energy if speed doubles while mass remains constant?', 'text', 1, 'Compare v² with (2v)².', '{"why":"Kinetic energy is proportional to the square of speed.","sol":"Step 1: Original KE is proportional to v².\nStep 2: New KE is proportional to (2v)² = 4v².","steps":["Step 1: Original KE is proportional to v².","Step 2: New KE is proportional to (2v)² = 4v²."],"options":[],"conceptId":"physics_work_energy_power_machines_kinetic_energy","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q4","subject":"physics","chapter":"work_energy_power_machines","topic":"Kinetic Energy"}', 3),
  (2344, 559, 'A learner calculates KE = ½ × 4 × 3 = 6 J for a 4 kg object moving at 3 m/s. Identify the error and give the correct answer.', 'text', 1, 'Check whether the speed was squared.', '{"why":"The formula contains v², not v.","sol":"Step 1: Use KE = ½mv².\nStep 2: KE = ½ × 4 × 3².\nStep 3: KE = 2 × 9 = 18 J.","steps":["Step 1: Use KE = ½mv².","Step 2: KE = ½ × 4 × 3².","Step 3: KE = 2 × 9 = 18 J."],"options":[],"conceptId":"physics_work_energy_power_machines_kinetic_energy","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q5","subject":"physics","chapter":"work_energy_power_machines","topic":"Kinetic Energy"}', 4),
  (2345, 560, 'A spring has k = 100 N/m and is extended by 0.2 m. Calculate its stored elastic energy.', 'text', 1, 'Use E = ½kx².', '{"why":"Elastic energy depends on the square of the extension.","sol":"Step 1: E = ½ × 100 × 0.2²\nStep 2: E = 50 × 0.04\nStep 3: E = 2 J","steps":["Step 1: E = ½ × 100 × 0.2²","Step 2: E = 50 × 0.04","Step 3: E = 2 J"],"options":[],"conceptId":"physics_work_energy_power_machines_elastic_potential_energy","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q1","subject":"physics","chapter":"work_energy_power_machines","topic":"Elastic Potential Energy"}', 0),
  (2346, 560, 'A spring is stretched by 0.05 m by a force of 20 N. Calculate its elastic potential energy, assuming Hooke''s law applies.', 'text', 1, 'Use E = ½Fx.', '{"why":"For a spring obeying Hooke''s law, stored energy is half the final force multiplied by extension.","sol":"Step 1: E = ½ × 20 × 0.05\nStep 2: E = 10 × 0.05\nStep 3: E = 0.5 J","steps":["Step 1: E = ½ × 20 × 0.05","Step 2: E = 10 × 0.05","Step 3: E = 0.5 J"],"options":[],"conceptId":"physics_work_energy_power_machines_elastic_potential_energy","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q2","subject":"physics","chapter":"work_energy_power_machines","topic":"Elastic Potential Energy"}', 1),
  (2347, 560, 'What is the SI unit of elastic potential energy?', 'text', 1, 'Energy has the same SI unit regardless of its form.', '{"why":"All forms of energy are measured in joules.","sol":"Step 1: Elastic potential energy is a form of energy.\nStep 2: The SI unit of energy is the joule.","steps":["Step 1: Elastic potential energy is a form of energy.","Step 2: The SI unit of energy is the joule."],"options":[],"conceptId":"physics_work_energy_power_machines_elastic_potential_energy","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q3","subject":"physics","chapter":"work_energy_power_machines","topic":"Elastic Potential Energy"}', 2),
  (2348, 560, 'If the extension of a Hooke''s-law spring doubles, what happens to its elastic potential energy?', 'text', 1, 'The formula contains x².', '{"why":"Spring energy is proportional to the square of extension.","sol":"Step 1: Original energy is proportional to x².\nStep 2: New energy is proportional to (2x)² = 4x².","steps":["Step 1: Original energy is proportional to x².","Step 2: New energy is proportional to (2x)² = 4x²."],"options":[],"conceptId":"physics_work_energy_power_machines_elastic_potential_energy","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q4","subject":"physics","chapter":"work_energy_power_machines","topic":"Elastic Potential Energy"}', 3),
  (2349, 560, 'A learner uses E = kx to calculate spring energy. What is wrong?', 'text', 1, 'Check the formula and the units.', '{"why":"The expression kx gives force, not stored energy.","sol":"Step 1: kx is the force for a Hooke''s-law spring.\nStep 2: Energy is E = ½kx².\nStep 3: The extension must be squared and the factor ½ included.","steps":["Step 1: kx is the force for a Hooke''s-law spring.","Step 2: Energy is E = ½kx².","Step 3: The extension must be squared and the factor ½ included."],"options":[],"conceptId":"physics_work_energy_power_machines_elastic_potential_energy","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q5","subject":"physics","chapter":"work_energy_power_machines","topic":"Elastic Potential Energy"}', 4),
  (2350, 561, 'State the principle of conservation of energy.', 'text', 1, 'Consider the total energy of a system.', '{"why":"The total energy of an isolated system remains constant.","sol":"Step 1: Energy may change form or be transferred.\nStep 2: Energy is not created or destroyed.\nStep 3: The total energy of an isolated system remains constant.","steps":["Step 1: Energy may change form or be transferred.","Step 2: Energy is not created or destroyed.","Step 3: The total energy of an isolated system remains constant."],"options":[],"conceptId":"physics_work_energy_power_machines_conservation_of_energy","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q1","subject":"physics","chapter":"work_energy_power_machines","topic":"Conservation of Energy"}', 0),
  (2351, 561, 'What happens to a falling object''s gravitational potential energy as it moves downward?', 'text', 1, 'Consider its height above the ground.', '{"why":"Gravitational potential energy decreases as height decreases.","sol":"Step 1: Its height decreases.\nStep 2: Its gravitational potential energy decreases.","steps":["Step 1: Its height decreases.","Step 2: Its gravitational potential energy decreases."],"options":[],"conceptId":"physics_work_energy_power_machines_conservation_of_energy","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q2","subject":"physics","chapter":"work_energy_power_machines","topic":"Conservation of Energy"}', 1),
  (2352, 561, 'A falling object loses 50 J of gravitational potential energy. If air resistance is negligible, how much kinetic energy does it gain?', 'text', 1, 'Mechanical energy is conserved when non-conservative effects are negligible.', '{"why":"The decrease in gravitational potential energy becomes kinetic energy.","sol":"Step 1: Loss in potential energy = gain in kinetic energy.\nStep 2: Kinetic energy gained = 50 J.","steps":["Step 1: Loss in potential energy = gain in kinetic energy.","Step 2: Kinetic energy gained = 50 J."],"options":[],"conceptId":"physics_work_energy_power_machines_conservation_of_energy","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q3","subject":"physics","chapter":"work_energy_power_machines","topic":"Conservation of Energy"}', 2),
  (2353, 561, 'When a bicycle brakes, some of its kinetic energy becomes thermal energy. Has energy been destroyed?', 'text', 1, 'Distinguish mechanical energy from total energy.', '{"why":"Energy changes form rather than being destroyed.","sol":"Step 1: Braking transfers energy to the brakes, tyres and surroundings.\nStep 2: Some energy becomes thermal energy.\nStep 3: Total energy is conserved.","steps":["Step 1: Braking transfers energy to the brakes, tyres and surroundings.","Step 2: Some energy becomes thermal energy.","Step 3: Total energy is conserved."],"options":[],"conceptId":"physics_work_energy_power_machines_conservation_of_energy","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q4","subject":"physics","chapter":"work_energy_power_machines","topic":"Conservation of Energy"}', 3),
  (2354, 561, 'A learner says that a moving object must keep all its kinetic energy when it stops. Correct the statement.', 'text', 1, 'Consider what can happen during stopping.', '{"why":"The object''s kinetic energy can change while total energy remains conserved.","sol":"Step 1: The object''s kinetic energy decreases to zero when it stops.\nStep 2: That energy is transferred to other forms, such as thermal energy and sound.","steps":["Step 1: The object''s kinetic energy decreases to zero when it stops.","Step 2: That energy is transferred to other forms, such as thermal energy and sound."],"options":[],"conceptId":"physics_work_energy_power_machines_conservation_of_energy","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q5","subject":"physics","chapter":"work_energy_power_machines","topic":"Conservation of Energy"}', 4),
  (2355, 562, 'Identify the main energy transformation in an electric motor.', 'text', 1, 'Consider what the motor does.', '{"why":"An electric motor uses electrical energy to produce motion.","sol":"Step 1: The motor receives electrical energy.\nStep 2: Its rotating parts gain kinetic energy.","steps":["Step 1: The motor receives electrical energy.","Step 2: Its rotating parts gain kinetic energy."],"options":[],"conceptId":"physics_work_energy_power_machines_energy_transformations","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q1","subject":"physics","chapter":"work_energy_power_machines","topic":"Energy Transformations"}', 0),
  (2356, 562, 'What energy transformation occurs as a ball falls?', 'text', 1, 'Its height decreases and its speed increases.', '{"why":"The ball gains kinetic energy as it falls.","sol":"Step 1: Gravitational potential energy decreases.\nStep 2: Kinetic energy increases.","steps":["Step 1: Gravitational potential energy decreases.","Step 2: Kinetic energy increases."],"options":[],"conceptId":"physics_work_energy_power_machines_energy_transformations","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q2","subject":"physics","chapter":"work_energy_power_machines","topic":"Energy Transformations"}', 1),
  (2357, 562, 'Name two forms of energy produced by an electric lamp.', 'text', 1, 'One is the intended output.', '{"why":"Not all electrical input becomes useful light.","sol":"Step 1: The lamp produces light.\nStep 2: It also transfers energy as thermal energy.","steps":["Step 1: The lamp produces light.","Step 2: It also transfers energy as thermal energy."],"options":[],"conceptId":"physics_work_energy_power_machines_energy_transformations","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q3","subject":"physics","chapter":"work_energy_power_machines","topic":"Energy Transformations"}', 2),
  (2358, 562, 'Describe the energy transformations in a battery-powered torch.', 'text', 1, 'Start with the energy stored in the battery.', '{"why":"Energy is transferred through the circuit and transformed in the lamp.","sol":"Step 1: Chemical energy in the battery is transferred to electrical energy.\nStep 2: The lamp converts electrical energy into light and thermal energy.","steps":["Step 1: Chemical energy in the battery is transferred to electrical energy.","Step 2: The lamp converts electrical energy into light and thermal energy."],"options":[],"conceptId":"physics_work_energy_power_machines_energy_transformations","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q4","subject":"physics","chapter":"work_energy_power_machines","topic":"Energy Transformations"}', 3),
  (2359, 562, 'A learner claims that a fan converts all its electrical energy into motion. Why is this inaccurate?', 'text', 1, 'Consider sound and heating.', '{"why":"Real devices have other energy outputs besides the useful one.","sol":"Step 1: The blades gain kinetic energy.\nStep 2: The motor also produces sound and thermal energy.\nStep 3: Therefore, not all input energy becomes useful motion.","steps":["Step 1: The blades gain kinetic energy.","Step 2: The motor also produces sound and thermal energy.","Step 3: Therefore, not all input energy becomes useful motion."],"options":[],"conceptId":"physics_work_energy_power_machines_energy_transformations","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q5","subject":"physics","chapter":"work_energy_power_machines","topic":"Energy Transformations"}', 4),
  (2360, 563, 'A machine does 200 J of work in 10 s. Calculate its power.', 'text', 1, 'Use P = W/t.', '{"why":"Power is work done divided by time taken.","sol":"Step 1: P = 200/10\nStep 2: P = 20 W","steps":["Step 1: P = 200/10","Step 2: P = 20 W"],"options":[],"conceptId":"physics_work_energy_power_machines_power","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q1","subject":"physics","chapter":"work_energy_power_machines","topic":"Power"}', 0),
  (2361, 563, 'A motor transfers 1,500 J of energy in 5 s. Find its power.', 'text', 1, 'Use P = E/t.', '{"why":"Power is the rate of energy transfer.","sol":"Step 1: P = 1500/5\nStep 2: P = 300 W","steps":["Step 1: P = 1500/5","Step 2: P = 300 W"],"options":[],"conceptId":"physics_work_energy_power_machines_power","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q2","subject":"physics","chapter":"work_energy_power_machines","topic":"Power"}', 1),
  (2362, 563, 'A worker does 600 J of work in 30 s. Calculate the average power.', 'text', 1, 'Divide work by time.', '{"why":"Average power is total work divided by total time.","sol":"Step 1: P = 600/30\nStep 2: P = 20 W","steps":["Step 1: P = 600/30","Step 2: P = 20 W"],"options":[],"conceptId":"physics_work_energy_power_machines_power","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q3","subject":"physics","chapter":"work_energy_power_machines","topic":"Power"}', 2),
  (2363, 563, 'Two machines do the same amount of work. One takes less time. Which has greater average power?', 'text', 1, 'Compare P = W/t.', '{"why":"For equal work, less time means greater average power.","sol":"Step 1: The work done is equal.\nStep 2: The machine taking less time has the smaller denominator.\nStep 3: Its average power is greater.","steps":["Step 1: The work done is equal.","Step 2: The machine taking less time has the smaller denominator.","Step 3: Its average power is greater."],"options":[],"conceptId":"physics_work_energy_power_machines_power","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q4","subject":"physics","chapter":"work_energy_power_machines","topic":"Power"}', 3),
  (2364, 563, 'A learner calculates power by multiplying work done by time. Correct the method.', 'text', 1, 'Check the units of power.', '{"why":"Multiplying joules by seconds does not give the unit of power.","sol":"Step 1: Power is work divided by time.\nStep 2: Use P = W/t.\nStep 3: The unit is J/s, equivalent to W.","steps":["Step 1: Power is work divided by time.","Step 2: Use P = W/t.","Step 3: The unit is J/s, equivalent to W."],"options":[],"conceptId":"physics_work_energy_power_machines_power","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q5","subject":"physics","chapter":"work_energy_power_machines","topic":"Power"}', 4),
  (2365, 564, 'A machine receives 400 J and produces 300 J of useful output energy. Calculate its efficiency.', 'text', 1, 'Divide useful output by input, then multiply by 100%.', '{"why":"Efficiency is the useful output divided by the input, expressed as a percentage.","sol":"Step 1: Efficiency = (300/400) × 100%\nStep 2: Efficiency = 75%","steps":["Step 1: Efficiency = (300/400) × 100%","Step 2: Efficiency = 75%"],"options":[],"conceptId":"physics_work_energy_power_machines_efficiency","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q1","subject":"physics","chapter":"work_energy_power_machines","topic":"Efficiency"}', 0),
  (2366, 564, 'A machine receives 800 J of input energy and has an efficiency of 50%. Find its useful output energy.', 'text', 1, '50% is 0.5 as a decimal.', '{"why":"Useful output equals efficiency as a fraction multiplied by input energy.","sol":"Step 1: Useful output = 0.5 × 800\nStep 2: Useful output = 400 J","steps":["Step 1: Useful output = 0.5 × 800","Step 2: Useful output = 400 J"],"options":[],"conceptId":"physics_work_energy_power_machines_efficiency","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q2","subject":"physics","chapter":"work_energy_power_machines","topic":"Efficiency"}', 1),
  (2367, 564, 'A machine receives 600 J and provides 450 J of useful output energy. How much energy is transferred to other forms?', 'text', 1, 'Subtract useful output from input.', '{"why":"The difference between input and useful output is transferred to other forms.","sol":"Step 1: Other energy transfers = 600 − 450\nStep 2: Other energy transfers = 150 J","steps":["Step 1: Other energy transfers = 600 − 450","Step 2: Other energy transfers = 150 J"],"options":[],"conceptId":"physics_work_energy_power_machines_efficiency","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q3","subject":"physics","chapter":"work_energy_power_machines","topic":"Efficiency"}', 2),
  (2368, 564, 'Why is the efficiency of a real machine usually below 100%?', 'text', 1, 'Consider friction, heating and sound.', '{"why":"The useful output is smaller than the total input.","sol":"Step 1: Some input energy is transferred into unwanted forms.\nStep 2: Less than all the input becomes the defined useful output.","steps":["Step 1: Some input energy is transferred into unwanted forms.","Step 2: Less than all the input becomes the defined useful output."],"options":[],"conceptId":"physics_work_energy_power_machines_efficiency","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q4","subject":"physics","chapter":"work_energy_power_machines","topic":"Efficiency"}', 3),
  (2369, 564, 'A learner calculates efficiency as input energy divided by useful output energy. Correct the formula.', 'text', 1, 'The ratio must not exceed 100% for an ordinary real machine with a defined useful output.', '{"why":"Reversing the ratio gives the wrong efficiency.","sol":"Step 1: Divide useful output by input.\nStep 2: Multiply by 100%.\nStep 3: Efficiency = (useful output/input) × 100%.","steps":["Step 1: Divide useful output by input.","Step 2: Multiply by 100%.","Step 3: Efficiency = (useful output/input) × 100%."],"options":[],"conceptId":"physics_work_energy_power_machines_efficiency","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q5","subject":"physics","chapter":"work_energy_power_machines","topic":"Efficiency"}', 4),
  (2370, 565, 'A machine lifts a 500 N load using a 100 N effort. Calculate its mechanical advantage.', 'text', 1, 'Use MA = load/effort.', '{"why":"Mechanical advantage is the load divided by the effort.","sol":"Step 1: MA = 500/100\nStep 2: MA = 5","steps":["Step 1: MA = 500/100","Step 2: MA = 5"],"options":[],"conceptId":"physics_work_energy_power_machines_mechanical_advantage","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q1","subject":"physics","chapter":"work_energy_power_machines","topic":"Mechanical Advantage"}', 0),
  (2371, 565, 'A machine has a mechanical advantage of 3 and the effort is 40 N. Calculate the load.', 'text', 1, 'Rearrange MA = load/effort.', '{"why":"Multiply mechanical advantage by effort to find the load.","sol":"Step 1: Load = MA × effort\nStep 2: Load = 3 × 40\nStep 3: Load = 120 N","steps":["Step 1: Load = MA × effort","Step 2: Load = 3 × 40","Step 3: Load = 120 N"],"options":[],"conceptId":"physics_work_energy_power_machines_mechanical_advantage","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q2","subject":"physics","chapter":"work_energy_power_machines","topic":"Mechanical Advantage"}', 1),
  (2372, 565, 'A machine lifts a 900 N load with an effort of 300 N. Find its mechanical advantage.', 'text', 1, 'Divide the load by the effort.', '{"why":"The load is three times the applied effort.","sol":"Step 1: MA = 900/300\nStep 2: MA = 3","steps":["Step 1: MA = 900/300","Step 2: MA = 3"],"options":[],"conceptId":"physics_work_energy_power_machines_mechanical_advantage","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q3","subject":"physics","chapter":"work_energy_power_machines","topic":"Mechanical Advantage"}', 2),
  (2373, 565, 'What is the unit of mechanical advantage?', 'text', 1, 'It is a ratio of two forces measured in the same unit.', '{"why":"Mechanical advantage is dimensionless.","sol":"Step 1: MA = load force/effort force.\nStep 2: The force units cancel.","steps":["Step 1: MA = load force/effort force.","Step 2: The force units cancel."],"options":[],"conceptId":"physics_work_energy_power_machines_mechanical_advantage","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q4","subject":"physics","chapter":"work_energy_power_machines","topic":"Mechanical Advantage"}', 3),
  (2374, 565, 'A learner claims that a machine with MA = 4 must be 100% efficient. Is the claim correct?', 'text', 1, 'Compare force ratio with useful output energy and input energy.', '{"why":"Mechanical advantage alone does not determine efficiency.","sol":"Step 1: MA measures the ratio of load to effort.\nStep 2: Efficiency compares useful output with input.\nStep 3: These are different quantities.","steps":["Step 1: MA measures the ratio of load to effort.","Step 2: Efficiency compares useful output with input.","Step 3: These are different quantities."],"options":[],"conceptId":"physics_work_energy_power_machines_mechanical_advantage","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q5","subject":"physics","chapter":"work_energy_power_machines","topic":"Mechanical Advantage"}', 4),
  (2375, 566, 'The effort moves 3 m and the load moves 1 m. Calculate the velocity ratio.', 'text', 1, 'Use VR = effort distance/load distance.', '{"why":"The effort moves three times the distance of the load.","sol":"Step 1: VR = 3/1\nStep 2: VR = 3","steps":["Step 1: VR = 3/1","Step 2: VR = 3"],"options":[],"conceptId":"physics_work_energy_power_machines_velocity_ratio","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q1","subject":"physics","chapter":"work_energy_power_machines","topic":"Velocity Ratio"}', 0),
  (2376, 566, 'The effort moves 4 m while the load moves 0.8 m. Find the velocity ratio.', 'text', 1, 'Divide 4 by 0.8.', '{"why":"Velocity ratio is the effort distance divided by the load distance.","sol":"Step 1: VR = 4/0.8\nStep 2: VR = 5","steps":["Step 1: VR = 4/0.8","Step 2: VR = 5"],"options":[],"conceptId":"physics_work_energy_power_machines_velocity_ratio","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q2","subject":"physics","chapter":"work_energy_power_machines","topic":"Velocity Ratio"}', 1),
  (2377, 566, 'A machine has VR = 6 and the load moves 0.5 m. How far does the effort move?', 'text', 1, 'Effort distance = VR × load distance.', '{"why":"Rearranging the velocity-ratio formula gives the effort distance.","sol":"Step 1: Effort distance = 6 × 0.5\nStep 2: Effort distance = 3 m","steps":["Step 1: Effort distance = 6 × 0.5","Step 2: Effort distance = 3 m"],"options":[],"conceptId":"physics_work_energy_power_machines_velocity_ratio","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q3","subject":"physics","chapter":"work_energy_power_machines","topic":"Velocity Ratio"}', 2),
  (2378, 566, 'What is the unit of velocity ratio?', 'text', 1, 'Both quantities are distances.', '{"why":"Velocity ratio is a dimensionless ratio.","sol":"Step 1: VR is distance divided by distance.\nStep 2: Metres cancel.","steps":["Step 1: VR is distance divided by distance.","Step 2: Metres cancel."],"options":[],"conceptId":"physics_work_energy_power_machines_velocity_ratio","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q4","subject":"physics","chapter":"work_energy_power_machines","topic":"Velocity Ratio"}', 3),
  (2379, 566, 'A learner uses the load force divided by effort force to calculate velocity ratio. Which quantity have they calculated instead?', 'text', 1, 'Recall the two definitions.', '{"why":"Mechanical advantage compares forces, whereas velocity ratio compares distances.","sol":"Step 1: Load force/effort force is mechanical advantage.\nStep 2: Velocity ratio uses effort distance/load distance.","steps":["Step 1: Load force/effort force is mechanical advantage.","Step 2: Velocity ratio uses effort distance/load distance."],"options":[],"conceptId":"physics_work_energy_power_machines_velocity_ratio","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q5","subject":"physics","chapter":"work_energy_power_machines","topic":"Velocity Ratio"}', 4),
  (2380, 567, 'A machine has MA = 4 and VR = 5. Calculate its efficiency.', 'text', 1, 'Use efficiency = (MA/VR) × 100%.', '{"why":"Mechanical advantage divided by velocity ratio gives efficiency as a fraction.","sol":"Step 1: Efficiency = (4/5) × 100%\nStep 2: Efficiency = 80%","steps":["Step 1: Efficiency = (4/5) × 100%","Step 2: Efficiency = 80%"],"options":[],"conceptId":"physics_work_energy_power_machines_efficiency_of_a_machine_using_ma_and_vr","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q1","subject":"physics","chapter":"work_energy_power_machines","topic":"Efficiency of a Machine Using MA and VR"}', 0),
  (2381, 567, 'A machine has MA = 2 and VR = 4. Find its efficiency.', 'text', 1, 'Divide 2 by 4, then convert to a percentage.', '{"why":"The useful force ratio is half the velocity ratio.","sol":"Step 1: Efficiency = (2/4) × 100%\nStep 2: Efficiency = 50%","steps":["Step 1: Efficiency = (2/4) × 100%","Step 2: Efficiency = 50%"],"options":[],"conceptId":"physics_work_energy_power_machines_efficiency_of_a_machine_using_ma_and_vr","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q2","subject":"physics","chapter":"work_energy_power_machines","topic":"Efficiency of a Machine Using MA and VR"}', 1),
  (2382, 567, 'A machine has an efficiency of 60% and VR = 5. Find its mechanical advantage.', 'text', 1, 'Convert the percentage to a fraction and rearrange.', '{"why":"MA equals efficiency as a fraction multiplied by VR.","sol":"Step 1: 0.60 = MA/5\nStep 2: MA = 0.60 × 5\nStep 3: MA = 3","steps":["Step 1: 0.60 = MA/5","Step 2: MA = 0.60 × 5","Step 3: MA = 3"],"options":[],"conceptId":"physics_work_energy_power_machines_efficiency_of_a_machine_using_ma_and_vr","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q3","subject":"physics","chapter":"work_energy_power_machines","topic":"Efficiency of a Machine Using MA and VR"}', 2),
  (2383, 567, 'A machine has MA = 3 and VR = 3. Calculate its efficiency.', 'text', 1, 'Use the ratio MA/VR.', '{"why":"Equal MA and VR give an efficiency of 100% in the formula.","sol":"Step 1: Efficiency = (3/3) × 100%\nStep 2: Efficiency = 100%","steps":["Step 1: Efficiency = (3/3) × 100%","Step 2: Efficiency = 100%"],"options":[],"conceptId":"physics_work_energy_power_machines_efficiency_of_a_machine_using_ma_and_vr","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q4","subject":"physics","chapter":"work_energy_power_machines","topic":"Efficiency of a Machine Using MA and VR"}', 3),
  (2384, 567, 'A learner calculates efficiency as VR/MA × 100%. What is the correct formula?', 'text', 1, 'The efficiency of an ordinary real machine should not exceed 100%.', '{"why":"Reversing the ratio incorrectly makes efficiency too large when VR exceeds MA.","sol":"Step 1: Use mechanical advantage in the numerator.\nStep 2: Use velocity ratio in the denominator.\nStep 3: Efficiency = (MA/VR) × 100%.","steps":["Step 1: Use mechanical advantage in the numerator.","Step 2: Use velocity ratio in the denominator.","Step 3: Efficiency = (MA/VR) × 100%."],"options":[],"conceptId":"physics_work_energy_power_machines_efficiency_of_a_machine_using_ma_and_vr","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q5","subject":"physics","chapter":"work_energy_power_machines","topic":"Efficiency of a Machine Using MA and VR"}', 4),
  (2385, 568, 'What is the fulcrum of a lever?', 'text', 1, 'It is the point about which the bar turns.', '{"why":"The fulcrum is the turning point of the lever.","sol":"Step 1: A lever turns about a fixed point.\nStep 2: That point is the fulcrum or pivot.","steps":["Step 1: A lever turns about a fixed point.","Step 2: That point is the fulcrum or pivot."],"options":[],"conceptId":"physics_work_energy_power_machines_levers_and_their_turning_effect","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q1","subject":"physics","chapter":"work_energy_power_machines","topic":"Levers and Their Turning Effect"}', 0),
  (2386, 568, 'A 100 N load acts 0.3 m from the pivot. The effort acts 0.6 m from the pivot. Calculate the effort needed for equilibrium.', 'text', 1, 'Effort × effort arm = load × load arm.', '{"why":"The clockwise and anticlockwise moments must balance.","sol":"Step 1: E × 0.6 = 100 × 0.3\nStep 2: E × 0.6 = 30\nStep 3: E = 30/0.6 = 50 N","steps":["Step 1: E × 0.6 = 100 × 0.3","Step 2: E × 0.6 = 30","Step 3: E = 30/0.6 = 50 N"],"options":[],"conceptId":"physics_work_energy_power_machines_levers_and_their_turning_effect","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q2","subject":"physics","chapter":"work_energy_power_machines","topic":"Levers and Their Turning Effect"}', 1),
  (2387, 568, 'A 60 N effort acts 0.5 m from the pivot. What load can it balance at 0.2 m from the pivot?', 'text', 1, 'Equate effort moment and load moment.', '{"why":"A longer effort arm can balance a larger load at a shorter load arm.","sol":"Step 1: 60 × 0.5 = L × 0.2\nStep 2: 30 = 0.2L\nStep 3: L = 150 N","steps":["Step 1: 60 × 0.5 = L × 0.2","Step 2: 30 = 0.2L","Step 3: L = 150 N"],"options":[],"conceptId":"physics_work_energy_power_machines_levers_and_their_turning_effect","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q3","subject":"physics","chapter":"work_energy_power_machines","topic":"Levers and Their Turning Effect"}', 2),
  (2388, 568, 'What is the effort arm of a lever?', 'text', 1, 'Measure from the pivot to the effort''s line of action.', '{"why":"The moment of a force depends on its perpendicular distance from the pivot.","sol":"Step 1: Identify the pivot.\nStep 2: Identify the effort''s line of action.\nStep 3: Measure the perpendicular distance between them.","steps":["Step 1: Identify the pivot.","Step 2: Identify the effort''s line of action.","Step 3: Measure the perpendicular distance between them."],"options":[],"conceptId":"physics_work_energy_power_machines_levers_and_their_turning_effect","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q4","subject":"physics","chapter":"work_energy_power_machines","topic":"Levers and Their Turning Effect"}', 3),
  (2389, 568, 'A learner uses the full length of a slanted lever as the effort arm even though the effort is not perpendicular to it. What should they use?', 'text', 1, 'Moments use perpendicular distance.', '{"why":"The moment is force multiplied by perpendicular distance, not automatically the bar''s length.","sol":"Step 1: Identify the line of action of the effort.\nStep 2: Measure the shortest perpendicular distance from the pivot to that line.","steps":["Step 1: Identify the line of action of the effort.","Step 2: Measure the shortest perpendicular distance from the pivot to that line."],"options":[],"conceptId":"physics_work_energy_power_machines_levers_and_their_turning_effect","skillId":"physics_work_energy_power_machines","subskillId":"physics_work_energy_power_machines_q5","subject":"physics","chapter":"work_energy_power_machines","topic":"Levers and Their Turning Effect"}', 4),
  (2390, 569, 'A disturbance travels along a rope after one end is moved. What is this disturbance an example of?', 'text', 1, 'Think of a disturbance that travels and transfers energy.', '{"why":"A wave is a disturbance that transfers energy from one place to another.","sol":"Step 1: Identify what is travelling along the rope: a disturbance.\nStep 2: A travelling disturbance that transfers energy is called a wave.\nStep 3: Therefore, the disturbance is a wave.","steps":["Step 1: Identify what is travelling along the rope: a disturbance.","Step 2: A travelling disturbance that transfers energy is called a wave.","Step 3: Therefore, the disturbance is a wave."],"options":[],"conceptId":"physics_waves_meaning_of_a_wave","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Meaning of a Wave"}', 0),
  (2391, 569, 'Which statement best describes a wave?', 'mcq', 1, 'Choose the statement about a travelling disturbance and energy.', '{"why":"A wave is a disturbance that transfers energy.","sol":"Step 1: Identify key concept: Define the required principles for Meaning of a Wave.\nStep 2: Apply governing rule: A wave is a disturbance that transfers energy.\nStep 3: State the final conclusion: A disturbance that transfers energy","steps":["Step 1: Identify key concept: Define the required principles for Meaning of a Wave.","Step 2: Apply governing rule: A wave is a disturbance that transfers energy.","Step 3: State the final conclusion: A disturbance that transfers energy"],"options":[{"text":"A disturbance that transfers energy","is_correct":true},{"text":"Matter permanently travelling with the disturbance","is_correct":false},{"text":"An object that must move from one end to the other","is_correct":false},{"text":"A force that always moves particles forward","is_correct":false}],"conceptId":"physics_waves_meaning_of_a_wave","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Meaning of a Wave"}', 1),
  (2392, 569, 'A sound travels from a bell to a listener. What travels from the bell towards the listener?', 'text', 1, 'The sound carries something from the vibrating source.', '{"why":"The sound disturbance travels through the medium and transfers energy to the listener.","sol":"Step 1: Identify key concept: Define the required principles for Meaning of a Wave.\nStep 2: Apply governing rule: The sound disturbance travels through the medium and transfers energy to the listener.\nStep 3: State the final conclusion: A sound wave carrying energy","steps":["Step 1: Identify key concept: Define the required principles for Meaning of a Wave.","Step 2: Apply governing rule: The sound disturbance travels through the medium and transfers energy to the listener.","Step 3: State the final conclusion: A sound wave carrying energy"],"options":[],"conceptId":"physics_waves_meaning_of_a_wave","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Meaning of a Wave"}', 2),
  (2393, 570, 'A water wave passes a floating cork, which bobs up and down. What is transferred across the water by the wave?', 'text', 1, 'Distinguish what travels with the wave from the cork''s local movement.', '{"why":"The wave transfers energy through the water, while the cork bobs as the disturbance passes.","sol":"Step 1: Identify key concept: Define the required principles for Energy Transfer by Waves.\nStep 2: Apply governing rule: The wave transfers energy through the water, while the cork bobs as the disturbance passes.\nStep 3: State the final conclusion: Energy","steps":["Step 1: Identify key concept: Define the required principles for Energy Transfer by Waves.","Step 2: Apply governing rule: The wave transfers energy through the water, while the cork bobs as the disturbance passes.","Step 3: State the final conclusion: Energy"],"options":[],"conceptId":"physics_waves_energy_transfer_by_waves","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Energy Transfer by Waves"}', 0),
  (2394, 570, 'A pulse travels from one end of a rope to the other. What happens to a small ribbon attached halfway along the rope?', 'mcq', 1, 'Think about the ribbon''s motion as the pulse passes.', '{"why":"The rope''s particles move as the pulse passes, but the pulse itself travels along the rope.","sol":"Step 1: Identify key concept: Define the required principles for Energy Transfer by Waves.\nStep 2: Apply governing rule: The rope''s particles move as the pulse passes, but the pulse itself travels along the rope.\nStep 3: State the final conclusion: It moves locally as the pulse passes.","steps":["Step 1: Identify key concept: Define the required principles for Energy Transfer by Waves.","Step 2: Apply governing rule: The rope''s particles move as the pulse passes, but the pulse itself travels along the rope.","Step 3: State the final conclusion: It moves locally as the pulse passes."],"options":[{"text":"It moves locally as the pulse passes.","is_correct":true},{"text":"It travels to the far end with the pulse.","is_correct":false},{"text":"It remains completely motionless.","is_correct":false},{"text":"It disappears when the pulse reaches it.","is_correct":false}],"conceptId":"physics_waves_energy_transfer_by_waves","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Energy Transfer by Waves"}', 1),
  (2395, 570, 'Which statement correctly describes energy transfer by a wave in a material medium?', 'mcq', 1, 'The disturbance travels; particles generally oscillate about equilibrium.', '{"why":"A wave transports energy while particles of the medium generally oscillate about their equilibrium positions.","sol":"Step 1: Identify key concept: Define the required principles for Energy Transfer by Waves.\nStep 2: Apply governing rule: A wave transports energy while particles of the medium generally oscillate about their equilibrium positions.\nStep 3: State the final conclusion: Energy is transferred while particles oscillate locally.","steps":["Step 1: Identify key concept: Define the required principles for Energy Transfer by Waves.","Step 2: Apply governing rule: A wave transports energy while particles of the medium generally oscillate about their equilibrium positions.","Step 3: State the final conclusion: Energy is transferred while particles oscillate locally."],"options":[{"text":"Energy is transferred while particles oscillate locally.","is_correct":true},{"text":"Every particle travels permanently with the wave.","is_correct":false},{"text":"No energy moves from place to place.","is_correct":false},{"text":"The medium must move bodily from source to receiver.","is_correct":false}],"conceptId":"physics_waves_energy_transfer_by_waves","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Energy Transfer by Waves"}', 2),
  (2396, 571, 'A wave travels horizontally along a rope while a point on the rope oscillates vertically. What type of wave is this?', 'text', 1, 'Compare the directions of travel and oscillation.', '{"why":"A transverse wave has oscillations perpendicular to the direction of wave travel.","sol":"Step 1: Identify key concept: Define the required principles for Transverse Waves.\nStep 2: Apply governing rule: A transverse wave has oscillations perpendicular to the direction of wave travel.\nStep 3: State the final conclusion: A transverse wave","steps":["Step 1: Identify key concept: Define the required principles for Transverse Waves.","Step 2: Apply governing rule: A transverse wave has oscillations perpendicular to the direction of wave travel.","Step 3: State the final conclusion: A transverse wave"],"options":[],"conceptId":"physics_waves_transverse_waves","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Transverse Waves"}', 0),
  (2397, 571, 'In a transverse wave, the particles of the medium oscillate:', 'mcq', 1, 'Perpendicular means at right angles.', '{"why":"The defining feature of a transverse wave is perpendicular oscillation.","sol":"Step 1: Identify key concept: Define the required principles for Transverse Waves.\nStep 2: Apply governing rule: The defining feature of a transverse wave is perpendicular oscillation.\nStep 3: State the final conclusion: Perpendicular to the direction of wave travel","steps":["Step 1: Identify key concept: Define the required principles for Transverse Waves.","Step 2: Apply governing rule: The defining feature of a transverse wave is perpendicular oscillation.","Step 3: State the final conclusion: Perpendicular to the direction of wave travel"],"options":[{"text":"Perpendicular to the direction of wave travel","is_correct":true},{"text":"Parallel to the direction of wave travel","is_correct":false},{"text":"Only in the direction of gravity","is_correct":false},{"text":"In the same direction as permanent matter transfer","is_correct":false}],"conceptId":"physics_waves_transverse_waves","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Transverse Waves"}', 1),
  (2398, 571, 'A pulse travels from left to right along a rope. A marked point on the rope moves up and down. Explain why the pulse is transverse.', 'text', 1, 'Name both directions and compare them.', '{"why":"Transverse classification depends on the relationship between the oscillation direction and the direction of wave travel.","sol":"Step 1: Identify key concept: Define the required principles for Transverse Waves.\nStep 2: Apply governing rule: Transverse classification depends on the relationship between the oscillation direction and the direction of wave travel.\nStep 3: State the final conclusion: The rope point oscillates vertically while the pulse travels horizontally, so the directions are perpendicular.","steps":["Step 1: Identify key concept: Define the required principles for Transverse Waves.","Step 2: Apply governing rule: Transverse classification depends on the relationship between the oscillation direction and the direction of wave travel.","Step 3: State the final conclusion: The rope point oscillates vertically while the pulse travels horizontally, so the directions are perpendicular."],"options":[],"conceptId":"physics_waves_transverse_waves","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Transverse Waves"}', 2),
  (2399, 572, 'A disturbance travels along a spring while its coils oscillate back and forth along the same direction. What type of wave is produced?', 'text', 1, 'The oscillation and travel directions are parallel.', '{"why":"A longitudinal wave has particle oscillations parallel to the direction of wave travel.","sol":"Step 1: Identify key concept: Define the required principles for Longitudinal Waves.\nStep 2: Apply governing rule: A longitudinal wave has particle oscillations parallel to the direction of wave travel.\nStep 3: State the final conclusion: A longitudinal wave","steps":["Step 1: Identify key concept: Define the required principles for Longitudinal Waves.","Step 2: Apply governing rule: A longitudinal wave has particle oscillations parallel to the direction of wave travel.","Step 3: State the final conclusion: A longitudinal wave"],"options":[],"conceptId":"physics_waves_longitudinal_waves","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Longitudinal Waves"}', 0),
  (2400, 572, 'In a longitudinal wave, particles of the medium oscillate:', 'mcq', 1, 'Parallel means along the same direction.', '{"why":"Longitudinal waves are identified by parallel particle oscillation.","sol":"Step 1: Identify key concept: Define the required principles for Longitudinal Waves.\nStep 2: Apply governing rule: Longitudinal waves are identified by parallel particle oscillation.\nStep 3: State the final conclusion: Parallel to the direction of wave travel","steps":["Step 1: Identify key concept: Define the required principles for Longitudinal Waves.","Step 2: Apply governing rule: Longitudinal waves are identified by parallel particle oscillation.","Step 3: State the final conclusion: Parallel to the direction of wave travel"],"options":[{"text":"Parallel to the direction of wave travel","is_correct":true},{"text":"Perpendicular to the direction of wave travel","is_correct":false},{"text":"Only upwards","is_correct":false},{"text":"Without any movement","is_correct":false}],"conceptId":"physics_waves_longitudinal_waves","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Longitudinal Waves"}', 1),
  (2401, 572, 'Sound travels through air as a longitudinal wave. What is the relationship between air-particle oscillation and the direction of sound travel?', 'text', 1, 'Compare the two directions.', '{"why":"The air particles vibrate backwards and forwards along the direction in which the sound disturbance travels.","sol":"Step 1: Identify key concept: Define the required principles for Longitudinal Waves.\nStep 2: Apply governing rule: The air particles vibrate backwards and forwards along the direction in which the sound disturbance travels.\nStep 3: State the final conclusion: Air particles oscillate parallel to the direction of sound travel.","steps":["Step 1: Identify key concept: Define the required principles for Longitudinal Waves.","Step 2: Apply governing rule: The air particles vibrate backwards and forwards along the direction in which the sound disturbance travels.","Step 3: State the final conclusion: Air particles oscillate parallel to the direction of sound travel."],"options":[],"conceptId":"physics_waves_longitudinal_waves","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Longitudinal Waves"}', 2),
  (2402, 573, 'As a sound wave passes through air, what do the air particles do?', 'text', 1, 'Think about their motion relative to their undisturbed positions.', '{"why":"Air particles oscillate locally and pass the disturbance to neighbouring particles, allowing sound energy to travel.","sol":"Step 1: Identify key concept: Define the required principles for Particle Motion in a Medium.\nStep 2: Apply governing rule: Air particles oscillate locally and pass the disturbance to neighbouring particles, allowing sound energy to travel.\nStep 3: State the final conclusion: They oscillate back and forth about their equilibrium positions.","steps":["Step 1: Identify key concept: Define the required principles for Particle Motion in a Medium.","Step 2: Apply governing rule: Air particles oscillate locally and pass the disturbance to neighbouring particles, allowing sound energy to travel.","Step 3: State the final conclusion: They oscillate back and forth about their equilibrium positions."],"options":[],"conceptId":"physics_waves_particle_motion_in_a_medium","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Particle Motion in a Medium"}', 0),
  (2403, 573, 'What is an equilibrium position?', 'text', 1, 'It is the particle''s undisturbed position.', '{"why":"The equilibrium position is the particle''s undisturbed position, around which it moves during oscillation.","sol":"Step 1: Identify key concept: Define the required principles for Particle Motion in a Medium.\nStep 2: Apply governing rule: The equilibrium position is the particle''s undisturbed position, around which it moves during oscillation.\nStep 3: State the final conclusion: The position about which a particle oscillates when a wave passes.","steps":["Step 1: Identify key concept: Define the required principles for Particle Motion in a Medium.","Step 2: Apply governing rule: The equilibrium position is the particle''s undisturbed position, around which it moves during oscillation.","Step 3: State the final conclusion: The position about which a particle oscillates when a wave passes."],"options":[],"conceptId":"physics_waves_particle_motion_in_a_medium","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Particle Motion in a Medium"}', 1),
  (2404, 573, 'A pulse travels along a rope, but a marked point on the rope returns close to its original position after the pulse passes. What does this show?', 'text', 1, 'Distinguish the travelling pulse from the motion of one point.', '{"why":"The disturbance travels along the rope, while each point of the rope moves locally as the pulse passes.","sol":"Step 1: Identify key concept: Define the required principles for Particle Motion in a Medium.\nStep 2: Apply governing rule: The disturbance travels along the rope, while each point of the rope moves locally as the pulse passes.\nStep 3: State the final conclusion: The pulse transfers energy along the rope while the marked point moves locally and returns towards its equilibrium position.","steps":["Step 1: Identify key concept: Define the required principles for Particle Motion in a Medium.","Step 2: Apply governing rule: The disturbance travels along the rope, while each point of the rope moves locally as the pulse passes.","Step 3: State the final conclusion: The pulse transfers energy along the rope while the marked point moves locally and returns towards its equilibrium position."],"options":[],"conceptId":"physics_waves_particle_motion_in_a_medium","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Particle Motion in a Medium"}', 2),
  (2405, 574, 'A wave crest is 3 cm above the equilibrium position. What is the amplitude?', 'mcq', 1, 'Measure from the equilibrium position to the crest.', '{"why":"Amplitude is the maximum displacement from equilibrium.","sol":"Step 1: Amplitude is the maximum displacement from equilibrium.\nStep 2: The crest is 3 cm above equilibrium.\nStep 3: Therefore, amplitude = 3 cm.","steps":["Step 1: Amplitude is the maximum displacement from equilibrium.","Step 2: The crest is 3 cm above equilibrium.","Step 3: Therefore, amplitude = 3 cm."],"options":[{"text":"1.5 cm","is_correct":false},{"text":"3 cm","is_correct":true},{"text":"6 cm","is_correct":false},{"text":"9 cm","is_correct":false}],"conceptId":"physics_waves_amplitude","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Amplitude"}', 0),
  (2406, 574, 'The distance from a crest to the adjacent trough is 10 cm. Find the amplitude.', 'mcq', 1, 'The crest-to-trough distance is twice the amplitude.', '{"why":"The crest and trough are on opposite sides of equilibrium.","sol":"Step 1: Crest-to-trough distance = 2A.\nStep 2: 10 = 2A.\nStep 3: A = 10 ÷ 2 = 5 cm.","steps":["Step 1: Crest-to-trough distance = 2A.","Step 2: 10 = 2A.","Step 3: A = 10 ÷ 2 = 5 cm."],"options":[{"text":"5 cm","is_correct":true},{"text":"10 cm","is_correct":false},{"text":"20 cm","is_correct":false},{"text":"2.5 cm","is_correct":false}],"conceptId":"physics_waves_amplitude","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Amplitude"}', 1),
  (2407, 574, 'If the amplitude of a wave increases, what happens to its maximum displacement from equilibrium?', 'mcq', 1, 'Amplitude measures maximum displacement.', '{"why":"Amplitude describes the size of the oscillation, not the distance between successive crests.","sol":"Step 1: Amplitude is the maximum displacement from equilibrium.\nStep 2: A larger amplitude means a greater maximum displacement.","steps":["Step 1: Amplitude is the maximum displacement from equilibrium.","Step 2: A larger amplitude means a greater maximum displacement."],"options":[{"text":"It increases","is_correct":true},{"text":"It decreases","is_correct":false},{"text":"It becomes zero","is_correct":false},{"text":"It must remain unchanged","is_correct":false}],"conceptId":"physics_waves_amplitude","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Amplitude"}', 2),
  (2408, 575, 'The distance between two successive crests is 2.5 m. What is the wavelength?', 'mcq', 1, 'One crest to the next crest is one complete wavelength.', '{"why":"A complete wave cycle repeats from one crest to the next crest.","sol":"Step 1: Identify two successive crests.\nStep 2: The distance between them is one wavelength.\nStep 3: Therefore, λ = 2.5 m.","steps":["Step 1: Identify two successive crests.","Step 2: The distance between them is one wavelength.","Step 3: Therefore, λ = 2.5 m."],"options":[{"text":"1.25 m","is_correct":false},{"text":"2.5 m","is_correct":true},{"text":"5 m","is_correct":false},{"text":"0.4 m","is_correct":false}],"conceptId":"physics_waves_wavelength","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Wavelength"}', 0),
  (2409, 575, 'Four complete wavelengths occupy a distance of 20 m. Find the wavelength.', 'mcq', 1, 'Divide the total distance by the number of complete wavelengths.', '{"why":"Wavelength equals total distance divided by the number of complete wavelengths.","sol":"Step 1: Total distance = 20 m.\nStep 2: Number of wavelengths = 4.\nStep 3: λ = 20 ÷ 4 = 5 m.","steps":["Step 1: Total distance = 20 m.","Step 2: Number of wavelengths = 4.","Step 3: λ = 20 ÷ 4 = 5 m."],"options":[{"text":"80 m","is_correct":false},{"text":"10 m","is_correct":false},{"text":"5 m","is_correct":true},{"text":"4 m","is_correct":false}],"conceptId":"physics_waves_wavelength","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Wavelength"}', 1),
  (2410, 575, 'Which distance represents one wavelength in a longitudinal wave?', 'mcq', 1, 'Look for two successive points in the same phase.', '{"why":"A compression and the adjacent rarefaction are approximately half a wavelength apart.","sol":"Step 1: A wavelength joins successive points in the same phase.\nStep 2: Successive compressions are in the same phase.\nStep 3: Their separation is one wavelength.","steps":["Step 1: A wavelength joins successive points in the same phase.","Step 2: Successive compressions are in the same phase.","Step 3: Their separation is one wavelength."],"options":[{"text":"From one compression to the next compression","is_correct":true},{"text":"From a compression to the nearest rarefaction","is_correct":false},{"text":"The width of one particle","is_correct":false},{"text":"The distance travelled by one particle in one second","is_correct":false}],"conceptId":"physics_waves_wavelength","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Wavelength"}', 2),
  (2411, 576, 'A source makes 30 complete oscillations in 6 seconds. Find its frequency.', 'mcq', 1, 'Frequency = number of oscillations ÷ time.', '{"why":"Frequency is the number of complete oscillations per second.","sol":"Step 1: N = 30 oscillations.\nStep 2: t = 6 s.\nStep 3: f = N/t = 30/6 = 5 Hz.","steps":["Step 1: N = 30 oscillations.","Step 2: t = 6 s.","Step 3: f = N/t = 30/6 = 5 Hz."],"options":[{"text":"5 Hz","is_correct":true},{"text":"24 Hz","is_correct":false},{"text":"36 Hz","is_correct":false},{"text":"180 Hz","is_correct":false}],"conceptId":"physics_waves_frequency","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Frequency"}', 0),
  (2412, 576, 'A wave source has a frequency of 8 Hz. How many complete oscillations occur in 3 seconds?', 'mcq', 1, 'Number of oscillations = frequency × time.', '{"why":"Multiplying frequency by elapsed time gives the total number of complete oscillations.","sol":"Step 1: f = 8 Hz and t = 3 s.\nStep 2: N = ft.\nStep 3: N = 8 × 3 = 24.","steps":["Step 1: f = 8 Hz and t = 3 s.","Step 2: N = ft.","Step 3: N = 8 × 3 = 24."],"options":[{"text":"11","is_correct":false},{"text":"8","is_correct":false},{"text":"24","is_correct":true},{"text":"2.67","is_correct":false}],"conceptId":"physics_waves_frequency","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Frequency"}', 1),
  (2413, 576, 'What is the SI unit of frequency?', 'mcq', 1, 'Frequency measures cycles per second.', '{"why":"Hertz is equivalent to inverse seconds (s⁻¹).","sol":"Step 1: Frequency is measured in hertz.\nStep 2: One hertz is one cycle per second.","steps":["Step 1: Frequency is measured in hertz.","Step 2: One hertz is one cycle per second."],"options":[{"text":"Metre","is_correct":false},{"text":"Second","is_correct":false},{"text":"Hertz","is_correct":true},{"text":"Metre per second","is_correct":false}],"conceptId":"physics_waves_frequency","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Frequency"}', 2),
  (2414, 577, 'A source completes 12 oscillations in 6 seconds. Find its period.', 'mcq', 1, 'Period = total time ÷ number of oscillations.', '{"why":"The period is the time for one complete oscillation.","sol":"Step 1: Total time = 6 s.\nStep 2: Number of oscillations = 12.\nStep 3: T = 6/12 = 0.5 s.","steps":["Step 1: Total time = 6 s.","Step 2: Number of oscillations = 12.","Step 3: T = 6/12 = 0.5 s."],"options":[{"text":"2 s","is_correct":false},{"text":"0.5 s","is_correct":true},{"text":"72 s","is_correct":false},{"text":"6 s","is_correct":false}],"conceptId":"physics_waves_period_of_a_wave","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Period of a Wave"}', 0),
  (2415, 577, 'A wave has a frequency of 25 Hz. Calculate its period.', 'mcq', 1, 'Use T = 1/f.', '{"why":"Period is the reciprocal of frequency.","sol":"Step 1: f = 25 Hz.\nStep 2: T = 1/f.\nStep 3: T = 1/25 = 0.04 s.","steps":["Step 1: f = 25 Hz.","Step 2: T = 1/f.","Step 3: T = 1/25 = 0.04 s."],"options":[{"text":"25 s","is_correct":false},{"text":"0.25 s","is_correct":false},{"text":"0.04 s","is_correct":true},{"text":"2.5 s","is_correct":false}],"conceptId":"physics_waves_period_of_a_wave","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Period of a Wave"}', 1),
  (2416, 577, 'What happens to the period when the frequency increases?', 'mcq', 1, 'Use T = 1/f.', '{"why":"Frequency and period are inversely proportional.","sol":"Step 1: Period is the reciprocal of frequency.\nStep 2: Increasing the denominator makes the reciprocal smaller.\nStep 3: Therefore, the period decreases.","steps":["Step 1: Period is the reciprocal of frequency.","Step 2: Increasing the denominator makes the reciprocal smaller.","Step 3: Therefore, the period decreases."],"options":[{"text":"The period increases","is_correct":false},{"text":"The period decreases","is_correct":true},{"text":"The period stays zero","is_correct":false},{"text":"The period always doubles","is_correct":false}],"conceptId":"physics_waves_period_of_a_wave","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Period of a Wave"}', 2),
  (2417, 578, 'A wave has a frequency of 4 Hz and a wavelength of 3 m. Find its speed.', 'mcq', 1, 'Use v = fλ.', '{"why":"Wave speed equals frequency multiplied by wavelength.","sol":"Step 1: f = 4 Hz and λ = 3 m.\nStep 2: v = fλ.\nStep 3: v = 4 × 3 = 12 m/s.","steps":["Step 1: f = 4 Hz and λ = 3 m.","Step 2: v = fλ.","Step 3: v = 4 × 3 = 12 m/s."],"options":[{"text":"7 m/s","is_correct":false},{"text":"12 m/s","is_correct":true},{"text":"1.33 m/s","is_correct":false},{"text":"24 m/s","is_correct":false}],"conceptId":"physics_waves_wave_speed","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Wave Speed"}', 0),
  (2418, 578, 'A wave travels 45 m in 9 seconds. Find its speed.', 'mcq', 1, 'Speed = distance ÷ time.', '{"why":"Speed is the distance travelled divided by the time taken.","sol":"Step 1: Distance = 45 m.\nStep 2: Time = 9 s.\nStep 3: Speed = 45/9 = 5 m/s.","steps":["Step 1: Distance = 45 m.","Step 2: Time = 9 s.","Step 3: Speed = 45/9 = 5 m/s."],"options":[{"text":"5 m/s","is_correct":true},{"text":"36 m/s","is_correct":false},{"text":"54 m/s","is_correct":false},{"text":"0.2 m/s","is_correct":false}],"conceptId":"physics_waves_wave_speed","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Wave Speed"}', 1),
  (2419, 578, 'A wave travels at 18 m/s and has a frequency of 6 Hz. Find its wavelength.', 'mcq', 1, 'Rearrange v = fλ to make λ the subject.', '{"why":"Wavelength is wave speed divided by frequency.","sol":"Step 1: v = fλ.\nStep 2: λ = v/f.\nStep 3: λ = 18/6 = 3 m.","steps":["Step 1: v = fλ.","Step 2: λ = v/f.","Step 3: λ = 18/6 = 3 m."],"options":[{"text":"108 m","is_correct":false},{"text":"24 m","is_correct":false},{"text":"3 m","is_correct":true},{"text":"12 m","is_correct":false}],"conceptId":"physics_waves_wave_speed","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Wave Speed"}', 2),
  (2420, 579, 'A water wave reaches a wall and returns across the water. What phenomenon has occurred?', 'text', 1, 'The wave has returned after reaching a boundary.', '{"why":"Reflection occurs when a wave returns into the medium after meeting a boundary.","sol":"Step 1: The wave travels towards the wall.\nStep 2: It returns after reaching the boundary.\nStep 3: This behaviour is called reflection.","steps":["Step 1: The wave travels towards the wall.","Step 2: It returns after reaching the boundary.","Step 3: This behaviour is called reflection."],"options":[],"conceptId":"physics_waves_reflection_of_waves","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Reflection of Waves"}', 0),
  (2421, 579, 'A sound wave returns to a listener after striking a cliff. What is the returning sound an example of?', 'mcq', 1, 'The sound has bounced back from a surface.', '{"why":"An echo results from reflected sound reaching the listener.","sol":"Step 1: Identify key concept: Define the required principles for Reflection of Waves.\nStep 2: Apply governing rule: An echo results from reflected sound reaching the listener.\nStep 3: State the final conclusion: Reflection","steps":["Step 1: Identify key concept: Define the required principles for Reflection of Waves.","Step 2: Apply governing rule: An echo results from reflected sound reaching the listener.","Step 3: State the final conclusion: Reflection"],"options":[{"text":"Reflection","is_correct":true},{"text":"Diffraction","is_correct":false},{"text":"Absorption only","is_correct":false},{"text":"Constructive interference only","is_correct":false}],"conceptId":"physics_waves_reflection_of_waves","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Reflection of Waves"}', 1),
  (2422, 579, 'What happens to a wave during reflection?', 'mcq', 1, 'Focus on the direction of the returning disturbance.', '{"why":"Reflection describes a wave returning from a boundary.","sol":"Step 1: Identify key concept: Define the required principles for Reflection of Waves.\nStep 2: Apply governing rule: Reflection describes a wave returning from a boundary.\nStep 3: State the final conclusion: It returns from a boundary.","steps":["Step 1: Identify key concept: Define the required principles for Reflection of Waves.","Step 2: Apply governing rule: Reflection describes a wave returning from a boundary.","Step 3: State the final conclusion: It returns from a boundary."],"options":[{"text":"It returns from a boundary.","is_correct":true},{"text":"It must stop permanently.","is_correct":false},{"text":"It must change into light.","is_correct":false},{"text":"It must pass through the boundary unchanged.","is_correct":false}],"conceptId":"physics_waves_reflection_of_waves","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Reflection of Waves"}', 2),
  (2423, 580, 'A wave strikes a plane reflecting boundary at 40° to the normal. What is its angle of reflection?', 'text', 1, 'The angle of incidence equals the angle of reflection.', '{"why":"The law of reflection states that the angle of incidence equals the angle of reflection.","sol":"Step 1: Angle of incidence i = 40°.\nStep 2: Use i = r.\nStep 3: Therefore, r = 40°.","steps":["Step 1: Angle of incidence i = 40°.","Step 2: Use i = r.","Step 3: Therefore, r = 40°."],"options":[],"conceptId":"physics_waves_direction_of_a_reflected_wave","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Direction of a Reflected Wave"}', 0),
  (2424, 580, 'A light ray makes an angle of 25° with a plane mirror''s surface. What is its angle of incidence?', 'text', 1, 'The normal is at 90° to the surface.', '{"why":"The angle of incidence is measured from the normal, which is perpendicular to the mirror.","sol":"Step 1: The ray makes 25° with the surface.\nStep 2: The normal is perpendicular to the surface.\nStep 3: Angle of incidence = 90° − 25° = 65°.","steps":["Step 1: The ray makes 25° with the surface.","Step 2: The normal is perpendicular to the surface.","Step 3: Angle of incidence = 90° − 25° = 65°."],"options":[],"conceptId":"physics_waves_direction_of_a_reflected_wave","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Direction of a Reflected Wave"}', 1),
  (2425, 580, 'The angle of incidence is 55°. What is the angle between the incident and reflected rays?', 'text', 1, 'The two rays lie on opposite sides of the normal.', '{"why":"For a plane reflecting surface, the angle between the incident and reflected rays is twice the angle of incidence.","sol":"Step 1: The angle of reflection is 55°.\nStep 2: The angle between the two rays is 55° + 55°.\nStep 3: The angle between them is 110°.","steps":["Step 1: The angle of reflection is 55°.","Step 2: The angle between the two rays is 55° + 55°.","Step 3: The angle between them is 110°."],"options":[],"conceptId":"physics_waves_direction_of_a_reflected_wave","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Direction of a Reflected Wave"}', 2),
  (2426, 581, 'Water waves enter a shallow region at an angle, change speed and turn. What phenomenon is demonstrated?', 'text', 1, 'The wave changes direction as its speed changes.', '{"why":"A wave refracts when its speed changes across a boundary and its direction changes.","sol":"Step 1: The waves enter a region with different water depth.\nStep 2: Their speed changes.\nStep 3: Because they enter at an angle, their direction changes.\nStep 4: This is refraction.","steps":["Step 1: The waves enter a region with different water depth.","Step 2: Their speed changes.","Step 3: Because they enter at an angle, their direction changes.","Step 4: This is refraction."],"options":[],"conceptId":"physics_waves_refraction_of_waves","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Refraction of Waves"}', 0),
  (2427, 581, 'A wave enters a new region perpendicular to the boundary. Its speed changes. Must its direction change?', 'mcq', 1, 'Consider a wave entering straight on.', '{"why":"At normal incidence, a wave may change speed without changing direction.","sol":"Step 1: Identify key concept: Define the required principles for Refraction of Waves.\nStep 2: Apply governing rule: At normal incidence, a wave may change speed without changing direction.\nStep 3: State the final conclusion: No, it can continue in the same direction.","steps":["Step 1: Identify key concept: Define the required principles for Refraction of Waves.","Step 2: Apply governing rule: At normal incidence, a wave may change speed without changing direction.","Step 3: State the final conclusion: No, it can continue in the same direction."],"options":[{"text":"Yes, every speed change causes bending.","is_correct":false},{"text":"No, it can continue in the same direction.","is_correct":true},{"text":"Yes, it must reflect completely.","is_correct":false},{"text":"No, its speed cannot change.","is_correct":false}],"conceptId":"physics_waves_refraction_of_waves","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Refraction of Waves"}', 1),
  (2428, 581, 'A periodic wave crosses into another region through a stationary boundary. Which quantity remains unchanged?', 'mcq', 1, 'The source continues producing cycles at the same rate.', '{"why":"The frequency is set by the source and remains unchanged across a stationary boundary; speed and wavelength may change.","sol":"Step 1: Identify key concept: Define the required principles for Refraction of Waves.\nStep 2: Apply governing rule: The frequency is set by the source and remains unchanged across a stationary boundary; speed and wavelength may change.\nStep 3: State the final conclusion: Frequency","steps":["Step 1: Identify key concept: Define the required principles for Refraction of Waves.","Step 2: Apply governing rule: The frequency is set by the source and remains unchanged across a stationary boundary; speed and wavelength may change.","Step 3: State the final conclusion: Frequency"],"options":[{"text":"Frequency","is_correct":true},{"text":"Speed in every medium","is_correct":false},{"text":"Wavelength in every medium","is_correct":false},{"text":"Amplitude in every situation","is_correct":false}],"conceptId":"physics_waves_refraction_of_waves","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Refraction of Waves"}', 2),
  (2429, 582, 'Water waves pass through an opening and spread into the region beyond it. What is this behaviour called?', 'text', 1, 'The wave spreads after passing through an opening.', '{"why":"Diffraction is the spreading of waves through openings and around obstacles.","sol":"Step 1: The waves pass through an opening.\nStep 2: They spread into the region beyond it.\nStep 3: This spreading is diffraction.","steps":["Step 1: The waves pass through an opening.","Step 2: They spread into the region beyond it.","Step 3: This spreading is diffraction."],"options":[],"conceptId":"physics_waves_diffraction_of_waves","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Diffraction of Waves"}', 0),
  (2430, 582, 'Which observation is an example of diffraction?', 'mcq', 1, 'Look for spreading through an opening or around an obstacle.', '{"why":"Sound can diffract through a doorway and spread into the region beyond it.","sol":"Step 1: Identify key concept: Define the required principles for Diffraction of Waves.\nStep 2: Apply governing rule: Sound can diffract through a doorway and spread into the region beyond it.\nStep 3: State the final conclusion: Sound spreading through a doorway","steps":["Step 1: Identify key concept: Define the required principles for Diffraction of Waves.","Step 2: Apply governing rule: Sound can diffract through a doorway and spread into the region beyond it.","Step 3: State the final conclusion: Sound spreading through a doorway"],"options":[{"text":"Sound spreading through a doorway","is_correct":true},{"text":"A wave returning from a wall","is_correct":false},{"text":"A wave changing speed at a boundary without spreading","is_correct":false},{"text":"A wave being produced by a vibrating source","is_correct":false}],"conceptId":"physics_waves_diffraction_of_waves","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Diffraction of Waves"}', 1),
  (2431, 582, 'Does diffraction require a wave to return to the medium it came from?', 'mcq', 1, 'Distinguish spreading from bouncing back.', '{"why":"Diffraction is wave spreading, whereas reflection is the return of a wave from a boundary.","sol":"Step 1: Identify key concept: Define the required principles for Diffraction of Waves.\nStep 2: Apply governing rule: Diffraction is wave spreading, whereas reflection is the return of a wave from a boundary.\nStep 3: State the final conclusion: No, diffraction involves spreading","steps":["Step 1: Identify key concept: Define the required principles for Diffraction of Waves.","Step 2: Apply governing rule: Diffraction is wave spreading, whereas reflection is the return of a wave from a boundary.","Step 3: State the final conclusion: No, diffraction involves spreading"],"options":[{"text":"Yes, always","is_correct":false},{"text":"No, diffraction involves spreading","is_correct":true},{"text":"Yes, only for sound","is_correct":false},{"text":"No, because diffraction destroys the wave","is_correct":false}],"conceptId":"physics_waves_diffraction_of_waves","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Diffraction of Waves"}', 2),
  (2432, 583, 'Water waves have a wavelength of 4 cm and pass through a gap 4 cm wide. What should you expect?', 'text', 1, 'Compare the gap width with the wavelength.', '{"why":"Diffraction is pronounced when the opening width is comparable to the wavelength.","sol":"Step 1: Wavelength = 4 cm.\nStep 2: Gap width = 4 cm.\nStep 3: The gap is comparable to the wavelength.\nStep 4: Diffraction should be noticeable.","steps":["Step 1: Wavelength = 4 cm.","Step 2: Gap width = 4 cm.","Step 3: The gap is comparable to the wavelength.","Step 4: Diffraction should be noticeable."],"options":[],"conceptId":"physics_waves_diffraction_and_gap_size","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Diffraction and Gap Size"}', 0),
  (2433, 583, 'A wave of wavelength 2 cm passes through a gap 40 cm wide. Compared with a gap of 2 cm, how pronounced is diffraction generally?', 'mcq', 1, 'The gap is much wider than the wavelength.', '{"why":"A gap much wider than the wavelength generally produces less noticeable spreading.","sol":"Step 1: Identify key concept: Define the required principles for Diffraction and Gap Size.\nStep 2: Apply governing rule: A gap much wider than the wavelength generally produces less noticeable spreading.\nStep 3: State the final conclusion: Less pronounced","steps":["Step 1: Identify key concept: Define the required principles for Diffraction and Gap Size.","Step 2: Apply governing rule: A gap much wider than the wavelength generally produces less noticeable spreading.","Step 3: State the final conclusion: Less pronounced"],"options":[{"text":"Less pronounced","is_correct":true},{"text":"More pronounced","is_correct":false},{"text":"Always exactly equal","is_correct":false},{"text":"Impossible because waves cannot pass through wide gaps","is_correct":false}],"conceptId":"physics_waves_diffraction_and_gap_size","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Diffraction and Gap Size"}', 1),
  (2434, 583, 'Which gap is most likely to produce pronounced diffraction for waves of wavelength 10 cm?', 'mcq', 1, 'Choose a gap comparable to the wavelength.', '{"why":"Diffraction is most noticeable when gap width is comparable to the wavelength.","sol":"Step 1: Identify key concept: Define the required principles for Diffraction and Gap Size.\nStep 2: Apply governing rule: Diffraction is most noticeable when gap width is comparable to the wavelength.\nStep 3: State the final conclusion: A gap 10 cm wide","steps":["Step 1: Identify key concept: Define the required principles for Diffraction and Gap Size.","Step 2: Apply governing rule: Diffraction is most noticeable when gap width is comparable to the wavelength.","Step 3: State the final conclusion: A gap 10 cm wide"],"options":[{"text":"A gap 10 cm wide","is_correct":true},{"text":"A gap 2 m wide","is_correct":false},{"text":"A gap 5 m wide","is_correct":false},{"text":"A completely closed barrier","is_correct":false}],"conceptId":"physics_waves_diffraction_and_gap_size","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Diffraction and Gap Size"}', 2),
  (2435, 584, 'Two pulses produce upward displacements of 3 cm and 4 cm at the same point. Find the resultant displacement.', 'text', 1, 'Both displacements are in the same direction.', '{"why":"Superposition requires adding the individual displacements algebraically.","sol":"Step 1: Both displacements are upward.\nStep 2: Resultant = 3 + 4.\nStep 3: Resultant displacement = 7 cm upward.","steps":["Step 1: Both displacements are upward.","Step 2: Resultant = 3 + 4.","Step 3: Resultant displacement = 7 cm upward."],"options":[],"conceptId":"physics_waves_superposition_of_waves","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Superposition of Waves"}', 0),
  (2436, 584, 'At a point, one pulse displaces the medium 6 cm upward and another displaces it 2 cm downward. Find the resultant.', 'text', 1, 'Choose upward as positive and downward as negative.', '{"why":"Opposite displacements subtract when their signed values are added.","sol":"Step 1: Upward displacement = +6 cm.\nStep 2: Downward displacement = −2 cm.\nStep 3: Resultant = 6 − 2 = 4 cm upward.","steps":["Step 1: Upward displacement = +6 cm.","Step 2: Downward displacement = −2 cm.","Step 3: Resultant = 6 − 2 = 4 cm upward."],"options":[],"conceptId":"physics_waves_superposition_of_waves","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Superposition of Waves"}', 1),
  (2437, 584, 'What does the principle of superposition describe?', 'mcq', 1, 'Think about the combined effect of overlapping waves.', '{"why":"Superposition states that the resultant displacement is the algebraic sum of individual displacements.","sol":"Step 1: Identify key concept: Define the required principles for Superposition of Waves.\nStep 2: Apply governing rule: Superposition states that the resultant displacement is the algebraic sum of individual displacements.\nStep 3: State the final conclusion: The resultant displacement when waves overlap","steps":["Step 1: Identify key concept: Define the required principles for Superposition of Waves.","Step 2: Apply governing rule: Superposition states that the resultant displacement is the algebraic sum of individual displacements.","Step 3: State the final conclusion: The resultant displacement when waves overlap"],"options":[{"text":"The resultant displacement when waves overlap","is_correct":true},{"text":"The speed of every wave in a vacuum","is_correct":false},{"text":"The return of waves from a boundary","is_correct":false},{"text":"The conversion of every wave into heat","is_correct":false}],"conceptId":"physics_waves_superposition_of_waves","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Superposition of Waves"}', 2),
  (2438, 585, 'Two upward pulses each have a displacement of 2 cm at the same point. Find the resultant displacement.', 'text', 1, 'The displacements reinforce because they point in the same direction.', '{"why":"Constructive overlap increases the resultant displacement when the individual displacements reinforce each other.","sol":"Step 1: First displacement = +2 cm.\nStep 2: Second displacement = +2 cm.\nStep 3: Resultant = 2 + 2 = 4 cm upward.","steps":["Step 1: First displacement = +2 cm.","Step 2: Second displacement = +2 cm.","Step 3: Resultant = 2 + 2 = 4 cm upward."],"options":[],"conceptId":"physics_waves_constructive_interference","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Constructive Interference"}', 0),
  (2439, 585, 'Two equal-amplitude waves meet in phase. What happens at a point of complete constructive interference?', 'mcq', 1, 'Crests align with crests and troughs with troughs.', '{"why":"In-phase waves reinforce each other, producing a larger resultant amplitude.","sol":"Step 1: Identify key concept: Define the required principles for Constructive Interference.\nStep 2: Apply governing rule: In-phase waves reinforce each other, producing a larger resultant amplitude.\nStep 3: State the final conclusion: Their displacements reinforce.","steps":["Step 1: Identify key concept: Define the required principles for Constructive Interference.","Step 2: Apply governing rule: In-phase waves reinforce each other, producing a larger resultant amplitude.","Step 3: State the final conclusion: Their displacements reinforce."],"options":[{"text":"Their displacements reinforce.","is_correct":true},{"text":"Their displacements cancel completely.","is_correct":false},{"text":"Both waves permanently disappear.","is_correct":false},{"text":"The frequency must become zero.","is_correct":false}],"conceptId":"physics_waves_constructive_interference","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Constructive Interference"}', 1),
  (2440, 585, 'Two equal waves each have amplitude 5 cm and meet in phase. What is the resultant amplitude at complete constructive interference?', 'text', 1, 'Add the two amplitudes at complete reinforcement.', '{"why":"Equal-amplitude waves in phase produce a resultant amplitude of twice the individual amplitude at complete constructive interference.","sol":"Step 1: First amplitude = 5 cm.\nStep 2: Second amplitude = 5 cm.\nStep 3: Resultant amplitude = 5 + 5 = 10 cm.","steps":["Step 1: First amplitude = 5 cm.","Step 2: Second amplitude = 5 cm.","Step 3: Resultant amplitude = 5 + 5 = 10 cm."],"options":[],"conceptId":"physics_waves_constructive_interference","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Constructive Interference"}', 2),
  (2441, 586, 'An upward pulse of 5 cm overlaps a downward pulse of 5 cm at the same point. Find the resultant displacement.', 'text', 1, 'The displacements have equal magnitudes and opposite directions.', '{"why":"Equal and opposite displacements produce zero resultant displacement at that point.","sol":"Step 1: Upward displacement = +5 cm.\nStep 2: Downward displacement = −5 cm.\nStep 3: Resultant = 5 − 5 = 0 cm.","steps":["Step 1: Upward displacement = +5 cm.","Step 2: Downward displacement = −5 cm.","Step 3: Resultant = 5 − 5 = 0 cm."],"options":[],"conceptId":"physics_waves_destructive_interference","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Destructive Interference"}', 0),
  (2442, 586, 'A 7 cm upward displacement overlaps a 3 cm downward displacement. Find the resultant.', 'text', 1, 'Subtract the smaller opposite displacement from the larger.', '{"why":"Unequal opposite displacements partially cancel, leaving a non-zero resultant.","sol":"Step 1: Upward displacement = +7 cm.\nStep 2: Downward displacement = −3 cm.\nStep 3: Resultant = 7 − 3 = 4 cm upward.","steps":["Step 1: Upward displacement = +7 cm.","Step 2: Downward displacement = −3 cm.","Step 3: Resultant = 7 − 3 = 4 cm upward."],"options":[],"conceptId":"physics_waves_destructive_interference","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Destructive Interference"}', 1),
  (2443, 586, 'When do two equal-amplitude waves produce complete destructive interference?', 'mcq', 1, 'A crest of one must align with a trough of the other.', '{"why":"Equal-amplitude waves in opposite phase have equal and opposite displacements, so they cancel at points of complete destructive interference.","sol":"Step 1: Identify key concept: Define the required principles for Destructive Interference.\nStep 2: Apply governing rule: Equal-amplitude waves in opposite phase have equal and opposite displacements, so they cancel at points of complete destructive interference.\nStep 3: State the final conclusion: When they arrive in opposite phase","steps":["Step 1: Identify key concept: Define the required principles for Destructive Interference.","Step 2: Apply governing rule: Equal-amplitude waves in opposite phase have equal and opposite displacements, so they cancel at points of complete destructive interference.","Step 3: State the final conclusion: When they arrive in opposite phase"],"options":[{"text":"When they arrive in opposite phase","is_correct":true},{"text":"When both crests arrive together","is_correct":false},{"text":"When both waves have zero frequency","is_correct":false},{"text":"Whenever their wavelengths are different","is_correct":false}],"conceptId":"physics_waves_destructive_interference","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Destructive Interference"}', 2),
  (2444, 587, 'What produces sound?', 'text', 1, 'Think about what the source is doing.', '{"why":"Sound is produced by vibrating objects.","sol":"Step 1: Sound begins with a vibrating source.\nStep 2: The vibration disturbs the surrounding medium.","steps":["Step 1: Sound begins with a vibrating source.","Step 2: The vibration disturbs the surrounding medium."],"options":[],"conceptId":"physics_waves_production_of_sound","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Production of Sound"}', 0),
  (2445, 587, 'A student strikes a tuning fork. What must the tuning fork do to produce sound?', 'text', 1, 'What happens to its prongs after being struck?', '{"why":"The vibrating prongs produce sound.","sol":"Step 1: Striking the fork sets its prongs moving.\nStep 2: The prongs vibrate about their resting positions.","steps":["Step 1: Striking the fork sets its prongs moving.","Step 2: The prongs vibrate about their resting positions."],"options":[],"conceptId":"physics_waves_production_of_sound","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Production of Sound"}', 1),
  (2446, 587, 'A drum is struck, but its skin is prevented from vibrating. What happens to the sound produced by the drum?', 'text', 1, 'Is the source still vibrating?', '{"why":"Sound production depends on vibration of the source.","sol":"Step 1: The drum skin is the vibrating source.\nStep 2: Preventing its vibration prevents it from producing its normal sound.","steps":["Step 1: The drum skin is the vibrating source.","Step 2: Preventing its vibration prevents it from producing its normal sound."],"options":[],"conceptId":"physics_waves_production_of_sound","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Production of Sound"}', 2),
  (2447, 588, 'Why is sound classified as a mechanical wave?', 'text', 1, 'What does sound need in order to travel?', '{"why":"Sound is mechanical because it cannot travel through a vacuum.","sol":"Step 1: A mechanical wave requires a material medium.\nStep 2: Sound travels through particles in that medium.","steps":["Step 1: A mechanical wave requires a material medium.","Step 2: Sound travels through particles in that medium."],"options":[],"conceptId":"physics_waves_sound_as_a_mechanical_wave","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Sound as a Mechanical Wave"}', 0),
  (2448, 588, 'Can sound travel through a perfect vacuum?', 'text', 1, 'Are there particles in a vacuum to transmit the disturbance?', '{"why":"Without a material medium, sound cannot propagate.","sol":"Step 1: Sound is transmitted through vibrating particles.\nStep 2: A perfect vacuum contains no material particles.","steps":["Step 1: Sound is transmitted through vibrating particles.","Step 2: A perfect vacuum contains no material particles."],"options":[],"conceptId":"physics_waves_sound_as_a_mechanical_wave","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Sound as a Mechanical Wave"}', 1),
  (2449, 588, 'When sound travels through air, do the air particles travel all the way from the source to the listener?', 'text', 1, 'Distinguish movement of particles from movement of the wave.', '{"why":"The wave transfers energy; the particles oscillate locally.","sol":"Step 1: Air particles vibrate about their equilibrium positions.\nStep 2: The disturbance and its energy travel through the air.","steps":["Step 1: Air particles vibrate about their equilibrium positions.","Step 2: The disturbance and its energy travel through the air."],"options":[],"conceptId":"physics_waves_sound_as_a_mechanical_wave","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Sound as a Mechanical Wave"}', 2),
  (2450, 589, 'What is a compression in a sound wave?', 'text', 1, 'Consider the spacing between particles.', '{"why":"Compressions have higher particle density and pressure.","sol":"Step 1: Compare the particle spacing with that in undisturbed air.\nStep 2: In a compression, particles are closer together.","steps":["Step 1: Compare the particle spacing with that in undisturbed air.","Step 2: In a compression, particles are closer together."],"options":[],"conceptId":"physics_waves_compressions_in_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Compressions in Sound Waves"}', 0),
  (2451, 589, 'Compared with undisturbed air, what is the pressure in a compression?', 'text', 1, 'Particles are crowded into a smaller region.', '{"why":"A compression is a high-pressure region.","sol":"Step 1: A compression contains particles closer together.\nStep 2: This produces a region of increased pressure.","steps":["Step 1: A compression contains particles closer together.","Step 2: This produces a region of increased pressure."],"options":[],"conceptId":"physics_waves_compressions_in_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Compressions in Sound Waves"}', 1),
  (2452, 589, 'In a longitudinal sound wave, how do the air particles vibrate relative to the direction of wave travel?', 'text', 1, 'The particles move back and forth along which line?', '{"why":"The particle motion is parallel to the direction of propagation.","sol":"Step 1: Sound in air is longitudinal.\nStep 2: Longitudinal particle vibrations are parallel to wave travel.","steps":["Step 1: Sound in air is longitudinal.","Step 2: Longitudinal particle vibrations are parallel to wave travel."],"options":[],"conceptId":"physics_waves_compressions_in_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Compressions in Sound Waves"}', 2),
  (2453, 590, 'What is a rarefaction?', 'text', 1, 'Compare particle spacing with normal spacing.', '{"why":"Rarefactions are the spread-out regions of a longitudinal sound wave.","sol":"Step 1: Examine the spacing between particles.\nStep 2: In a rarefaction, particles are farther apart than normal.","steps":["Step 1: Examine the spacing between particles.","Step 2: In a rarefaction, particles are farther apart than normal."],"options":[],"conceptId":"physics_waves_rarefactions_in_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Rarefactions in Sound Waves"}', 0),
  (2454, 590, 'What is the pressure in a rarefaction compared with the undisturbed medium?', 'text', 1, 'The particles are less crowded.', '{"why":"Rarefactions are low-pressure regions.","sol":"Step 1: A rarefaction has lower particle density.\nStep 2: Its pressure is lower than that of the undisturbed medium.","steps":["Step 1: A rarefaction has lower particle density.","Step 2: Its pressure is lower than that of the undisturbed medium."],"options":[],"conceptId":"physics_waves_rarefactions_in_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Rarefactions in Sound Waves"}', 1),
  (2455, 590, 'What lies between successive compressions in a sound wave?', 'text', 1, 'A sound wave alternates between crowded and spread-out regions.', '{"why":"Compressions and rarefactions alternate along a longitudinal sound wave.","sol":"Step 1: A compression is followed by a spread-out region.\nStep 2: That spread-out region is a rarefaction.","steps":["Step 1: A compression is followed by a spread-out region.","Step 2: That spread-out region is a rarefaction."],"options":[],"conceptId":"physics_waves_rarefactions_in_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Rarefactions in Sound Waves"}', 2),
  (2456, 591, 'How is sound transmitted through air?', 'text', 1, 'Consider how neighbouring air particles interact.', '{"why":"Sound travels through a medium by a propagating disturbance.","sol":"Step 1: The source makes nearby air particles vibrate.\nStep 2: These particles transmit the disturbance to neighbouring particles.","steps":["Step 1: The source makes nearby air particles vibrate.","Step 2: These particles transmit the disturbance to neighbouring particles."],"options":[],"conceptId":"physics_waves_transmission_of_sound_through_a_medium","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Transmission of Sound Through a Medium"}', 0),
  (2457, 591, 'What is transferred from the sound source through the medium?', 'text', 1, 'The particles do not travel all the way to the listener.', '{"why":"Sound transfers energy without transporting the medium as a whole.","sol":"Step 1: Particles vibrate locally.\nStep 2: The wave carries energy through the medium.","steps":["Step 1: Particles vibrate locally.","Step 2: The wave carries energy through the medium."],"options":[],"conceptId":"physics_waves_transmission_of_sound_through_a_medium","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Transmission of Sound Through a Medium"}', 1),
  (2458, 591, 'Why can sound travel through a solid?', 'text', 1, 'Are particles in a solid able to interact with neighbouring particles?', '{"why":"Sound can travel through solids because they provide a material medium.","sol":"Step 1: A solid contains particles close together.\nStep 2: Vibrations can be passed between neighbouring particles.","steps":["Step 1: A solid contains particles close together.","Step 2: Vibrations can be passed between neighbouring particles."],"options":[],"conceptId":"physics_waves_transmission_of_sound_through_a_medium","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Transmission of Sound Through a Medium"}', 2),
  (2459, 592, 'Sound travels 600 m in 2 s. Calculate its speed.', 'text', 1, 'Use speed = distance ÷ time.', '{"why":"Divide the distance travelled by the time taken.","sol":"Step 1: v = d/t\nStep 2: v = 600/2\nStep 3: v = 300 m/s","steps":["Step 1: v = d/t","Step 2: v = 600/2","Step 3: v = 300 m/s"],"options":[],"conceptId":"physics_waves_speed_of_sound","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Speed of Sound"}', 0),
  (2460, 592, 'A sound wave travels at 330 m/s for 4 s. How far does it travel?', 'text', 1, 'Rearrange v = d/t to make distance the subject.', '{"why":"Distance equals speed multiplied by time.","sol":"Step 1: v = d/t\nStep 2: d = vt\nStep 3: d = 330 × 4 = 1320 m","steps":["Step 1: v = d/t","Step 2: d = vt","Step 3: d = 330 × 4 = 1320 m"],"options":[],"conceptId":"physics_waves_speed_of_sound","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Speed of Sound"}', 1),
  (2461, 592, 'A sound wave travels 990 m at 330 m/s. How long does it take?', 'text', 1, 'Time = distance ÷ speed.', '{"why":"Divide the distance by the speed to find the time.","sol":"Step 1: t = d/v\nStep 2: t = 990/330\nStep 3: t = 3 s","steps":["Step 1: t = d/v","Step 2: t = 990/330","Step 3: t = 3 s"],"options":[],"conceptId":"physics_waves_speed_of_sound","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Speed of Sound"}', 2),
  (2462, 593, 'Which sound has the higher pitch: 200 Hz or 600 Hz?', 'text', 1, 'Compare the frequencies.', '{"why":"The sound with the higher frequency has the higher pitch.","sol":"Step 1: Higher frequency means higher pitch.\nStep 2: 600 Hz is greater than 200 Hz.","steps":["Step 1: Higher frequency means higher pitch.","Step 2: 600 Hz is greater than 200 Hz."],"options":[],"conceptId":"physics_waves_pitch_of_sound","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Pitch of Sound"}', 0),
  (2463, 593, 'A sound''s frequency decreases. What happens to its pitch?', 'text', 1, 'Pitch changes with frequency.', '{"why":"Lower frequency produces a lower-pitched sound.","sol":"Step 1: Pitch depends on frequency.\nStep 2: A lower frequency corresponds to a lower pitch.","steps":["Step 1: Pitch depends on frequency.","Step 2: A lower frequency corresponds to a lower pitch."],"options":[],"conceptId":"physics_waves_pitch_of_sound","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Pitch of Sound"}', 1),
  (2464, 593, 'A source makes 400 complete vibrations in 2 seconds. Find its frequency.', 'text', 1, 'Frequency = number of vibrations ÷ time.', '{"why":"Frequency is the number of complete vibrations per second.","sol":"Step 1: f = N/t\nStep 2: f = 400/2\nStep 3: f = 200 Hz","steps":["Step 1: f = N/t","Step 2: f = 400/2","Step 3: f = 200 Hz"],"options":[],"conceptId":"physics_waves_pitch_of_sound","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Pitch of Sound"}', 2),
  (2465, 594, 'Two sounds have the same frequency. One has a greater amplitude. Which is generally louder?', 'text', 1, 'Loudness is associated with amplitude.', '{"why":"Greater amplitude generally corresponds to greater perceived loudness.","sol":"Step 1: Compare the amplitudes.\nStep 2: The sound with greater amplitude is generally louder.","steps":["Step 1: Compare the amplitudes.","Step 2: The sound with greater amplitude is generally louder."],"options":[],"conceptId":"physics_waves_loudness_of_sound","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Loudness of Sound"}', 0),
  (2466, 594, 'What happens to the loudness of a sound when its amplitude becomes smaller, all else being equal?', 'text', 1, 'Compare the size of the vibration.', '{"why":"Lower amplitude generally produces a quieter sound.","sol":"Step 1: Smaller amplitude means a smaller vibration.\nStep 2: The sound is generally heard as quieter.","steps":["Step 1: Smaller amplitude means a smaller vibration.","Step 2: The sound is generally heard as quieter."],"options":[],"conceptId":"physics_waves_loudness_of_sound","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Loudness of Sound"}', 1),
  (2467, 594, 'A sound becomes louder, but its pitch stays the same. Which wave property most directly changed?', 'text', 1, 'Pitch relates to frequency; loudness relates to amplitude.', '{"why":"Amplitude affects loudness, while frequency affects pitch.","sol":"Step 1: Unchanged pitch suggests frequency has stayed the same.\nStep 2: A change in loudness is associated with a change in amplitude.","steps":["Step 1: Unchanged pitch suggests frequency has stayed the same.","Step 2: A change in loudness is associated with a change in amplitude."],"options":[],"conceptId":"physics_waves_loudness_of_sound","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Loudness of Sound"}', 2),
  (2468, 595, 'What causes an echo?', 'text', 1, 'Think about what happens when sound meets a hard surface.', '{"why":"An echo is reflected sound heard again.","sol":"Step 1: Sound reaches a reflecting surface.\nStep 2: The sound is reflected back to the listener.","steps":["Step 1: Sound reaches a reflecting surface.","Step 2: The sound is reflected back to the listener."],"options":[],"conceptId":"physics_waves_echoes_and_reflection_of_sound","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Echoes and Reflection of Sound"}', 0),
  (2469, 595, 'A person hears an echo 1 second after making a sound. If sound travels at 340 m/s, how far away is the reflecting surface?', 'text', 1, 'The sound makes a return journey, so divide vt by 2.', '{"why":"The measured time includes the journey to the surface and back.","sol":"Step 1: Total distance = vt = 340 × 1 = 340 m\nStep 2: Distance to surface = 340/2\nStep 3: Distance = 170 m","steps":["Step 1: Total distance = vt = 340 × 1 = 340 m","Step 2: Distance to surface = 340/2","Step 3: Distance = 170 m"],"options":[],"conceptId":"physics_waves_echoes_and_reflection_of_sound","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Echoes and Reflection of Sound"}', 1),
  (2470, 595, 'Why is the total distance travelled by sound twice the distance to the reflecting surface when an echo returns to the same person?', 'text', 1, 'Count the outward and return journeys.', '{"why":"The echo time measures a round trip, not just the outward journey.","sol":"Step 1: Sound travels from the person to the surface.\nStep 2: It then travels from the surface back to the person.\nStep 3: The two journeys cover the same distance.","steps":["Step 1: Sound travels from the person to the surface.","Step 2: It then travels from the surface back to the person.","Step 3: The two journeys cover the same distance."],"options":[],"conceptId":"physics_waves_echoes_and_reflection_of_sound","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Echoes and Reflection of Sound"}', 2),
  (2471, 596, 'What type of wave is light?', 'text', 1, 'Think of the two words used to classify light in the wave model.', '{"why":"Light is a transverse electromagnetic wave.","sol":"Step 1: Light can travel through a vacuum.\nStep 2: It is classified as an electromagnetic wave.\nStep 3: Its oscillations are transverse.","steps":["Step 1: Light can travel through a vacuum.","Step 2: It is classified as an electromagnetic wave.","Step 3: Its oscillations are transverse."],"options":[],"conceptId":"physics_waves_nature_of_light","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Nature of Light"}', 0),
  (2472, 596, 'Why can light travel through a vacuum?', 'text', 1, 'Does light need material particles to transmit it?', '{"why":"Electromagnetic waves can travel through a vacuum.","sol":"Step 1: A vacuum has no material particles.\nStep 2: Light does not require a material medium.","steps":["Step 1: A vacuum has no material particles.","Step 2: Light does not require a material medium."],"options":[],"conceptId":"physics_waves_nature_of_light","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Nature of Light"}', 1),
  (2473, 596, 'Which can travel through a vacuum: sound or light?', 'text', 1, 'Compare a mechanical wave with an electromagnetic wave.', '{"why":"Sound requires a material medium, but light does not.","sol":"Step 1: Sound is a mechanical wave and requires a medium.\nStep 2: Light is electromagnetic and can travel through a vacuum.","steps":["Step 1: Sound is a mechanical wave and requires a medium.","Step 2: Light is electromagnetic and can travel through a vacuum."],"options":[],"conceptId":"physics_waves_nature_of_light","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Nature of Light"}', 2),
  (2474, 597, 'What is the defining feature of a transverse wave?', 'text', 1, 'Compare the direction of oscillation with the direction of travel.', '{"why":"Perpendicular oscillations define a transverse wave.","sol":"Step 1: Identify the direction the wave travels.\nStep 2: In a transverse wave, oscillations are perpendicular to that direction.","steps":["Step 1: Identify the direction the wave travels.","Step 2: In a transverse wave, oscillations are perpendicular to that direction."],"options":[],"conceptId":"physics_waves_transverse_nature_of_light","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Transverse Nature of Light"}', 0),
  (2475, 597, 'A light wave travels east. What is the relationship between its oscillations and its direction of travel?', 'text', 1, 'Use the defining property of transverse waves.', '{"why":"Light is transverse, so its oscillations are perpendicular to propagation.","sol":"Step 1: The wave travels east.\nStep 2: Its oscillations are at right angles to its direction of travel.","steps":["Step 1: The wave travels east.","Step 2: Its oscillations are at right angles to its direction of travel."],"options":[],"conceptId":"physics_waves_transverse_nature_of_light","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Transverse Nature of Light"}', 1),
  (2476, 597, 'Is light longitudinal or transverse?', 'text', 1, 'Remember the relationship between oscillation and propagation.', '{"why":"Light is a transverse electromagnetic wave.","sol":"Step 1: Light is an electromagnetic wave.\nStep 2: Its oscillations are perpendicular to its direction of propagation.","steps":["Step 1: Light is an electromagnetic wave.","Step 2: Its oscillations are perpendicular to its direction of propagation."],"options":[],"conceptId":"physics_waves_transverse_nature_of_light","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Transverse Nature of Light"}', 2),
  (2477, 598, 'What is the approximate speed of light in a vacuum?', 'text', 1, 'Use the standard value in metres per second.', '{"why":"The speed of light in a vacuum is approximately 3.0 × 10⁸ m/s.","sol":"Step 1: The speed of light in a vacuum is represented by c.\nStep 2: Its approximate value is 300,000,000 m/s.","steps":["Step 1: The speed of light in a vacuum is represented by c.","Step 2: Its approximate value is 300,000,000 m/s."],"options":[],"conceptId":"physics_waves_propagation_of_light_through_a_vacuum","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Propagation of Light Through a Vacuum"}', 0),
  (2478, 598, 'Does light require air to travel from the Sun to Earth?', 'text', 1, 'The space between the Sun and Earth is nearly a vacuum.', '{"why":"Sunlight travels through space without requiring air.","sol":"Step 1: Light is an electromagnetic wave.\nStep 2: Electromagnetic waves do not require a material medium.","steps":["Step 1: Light is an electromagnetic wave.","Step 2: Electromagnetic waves do not require a material medium."],"options":[],"conceptId":"physics_waves_propagation_of_light_through_a_vacuum","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Propagation of Light Through a Vacuum"}', 1),
  (2479, 598, 'In which does light travel faster: a vacuum or ordinary glass?', 'text', 1, 'Compare the standard speed in a vacuum with light''s speed in a material.', '{"why":"Light travels more slowly in glass than in a vacuum.","sol":"Step 1: Light has its maximum speed in a vacuum.\nStep 2: It travels more slowly in ordinary glass.","steps":["Step 1: Light has its maximum speed in a vacuum.","Step 2: It travels more slowly in ordinary glass."],"options":[],"conceptId":"physics_waves_propagation_of_light_through_a_vacuum","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Propagation of Light Through a Vacuum"}', 2),
  (2480, 599, 'What does the wavelength of a light wave measure?', 'text', 1, 'Consider the distance between two successive points in the same phase.', '{"why":"Wavelength is the distance between successive points in the same phase.","sol":"Step 1: Identify two successive crests or equivalent points.\nStep 2: Measure the distance between them.","steps":["Step 1: Identify two successive crests or equivalent points.","Step 2: Measure the distance between them."],"options":[],"conceptId":"physics_waves_wavelength_of_light","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Wavelength of Light"}', 0),
  (2481, 599, 'Convert 500 nm into metres.', 'text', 1, '1 nm = 10^-9 m.', '{"why":"Multiply the nanometre value by 10⁻⁹ to convert it to metres.","sol":"Step 1: 500 nm = 500 × 10^-9 m\nStep 2: Write in standard form.\nStep 3: 500 × 10^-9 = 5.0 × 10^-7 m","steps":["Step 1: 500 nm = 500 × 10^-9 m","Step 2: Write in standard form.","Step 3: 500 × 10^-9 = 5.0 × 10^-7 m"],"options":[],"conceptId":"physics_waves_wavelength_of_light","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Wavelength of Light"}', 1),
  (2482, 599, 'Which symbol commonly represents wavelength?', 'text', 1, 'It is a Greek letter.', '{"why":"Wavelength is represented by lambda, λ.","sol":"Step 1: The standard symbol for wavelength is lambda.\nStep 2: Lambda is written as λ.","steps":["Step 1: The standard symbol for wavelength is lambda.","Step 2: Lambda is written as λ."],"options":[],"conceptId":"physics_waves_wavelength_of_light","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Wavelength of Light"}', 2),
  (2483, 600, 'What does the frequency of light measure?', 'text', 1, 'Count the cycles passing a fixed point in one second.', '{"why":"Frequency measures cycles per second.","sol":"Step 1: Frequency counts complete cycles.\nStep 2: The count is measured per second.","steps":["Step 1: Frequency counts complete cycles.","Step 2: The count is measured per second."],"options":[],"conceptId":"physics_waves_frequency_of_light","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Frequency of Light"}', 0),
  (2484, 600, 'A light wave has a frequency of 4 × 10^14 Hz. How many cycles pass a fixed point in one second?', 'text', 1, 'The unit hertz means cycles per second.', '{"why":"The numerical frequency gives the number of cycles passing each second.","sol":"Step 1: 1 Hz means one cycle per second.\nStep 2: 4 × 10^14 Hz means 4 × 10^14 cycles per second.","steps":["Step 1: 1 Hz means one cycle per second.","Step 2: 4 × 10^14 Hz means 4 × 10^14 cycles per second."],"options":[],"conceptId":"physics_waves_frequency_of_light","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Frequency of Light"}', 1),
  (2485, 600, 'Which visible light has the higher frequency: red or violet?', 'text', 1, 'Think of the order of colours in the visible spectrum.', '{"why":"Violet light has a higher frequency than red light.","sol":"Step 1: Visible light ranges from red through to violet.\nStep 2: Frequency increases towards violet.","steps":["Step 1: Visible light ranges from red through to violet.","Step 2: Frequency increases towards violet."],"options":[],"conceptId":"physics_waves_frequency_of_light","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Frequency of Light"}', 2),
  (2486, 601, 'Light travels in a vacuum at 3.0 × 10^8 m/s and has a frequency of 5.0 × 10^14 Hz. Calculate its wavelength.', 'text', 1, 'Rearrange c = fλ to obtain λ = c/f.', '{"why":"Divide the speed of light by the frequency to obtain wavelength.","sol":"Step 1: λ = c/f\nStep 2: λ = (3.0 × 10^8)/(5.0 × 10^14)\nStep 3: λ = 0.6 × 10^-6 m\nStep 4: λ = 6.0 × 10^-7 m","steps":["Step 1: λ = c/f","Step 2: λ = (3.0 × 10^8)/(5.0 × 10^14)","Step 3: λ = 0.6 × 10^-6 m","Step 4: λ = 6.0 × 10^-7 m"],"options":[],"conceptId":"physics_waves_light_wave_equation","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Light Wave Equation"}', 0),
  (2487, 601, 'A light wave in a vacuum has a wavelength of 4.0 × 10^-7 m. Calculate its frequency. Use c = 3.0 × 10^8 m/s.', 'text', 1, 'Rearrange c = fλ to obtain f = c/λ.', '{"why":"Frequency equals wave speed divided by wavelength.","sol":"Step 1: f = c/λ\nStep 2: f = (3.0 × 10^8)/(4.0 × 10^-7)\nStep 3: f = 0.75 × 10^15 Hz\nStep 4: f = 7.5 × 10^14 Hz","steps":["Step 1: f = c/λ","Step 2: f = (3.0 × 10^8)/(4.0 × 10^-7)","Step 3: f = 0.75 × 10^15 Hz","Step 4: f = 7.5 × 10^14 Hz"],"options":[],"conceptId":"physics_waves_light_wave_equation","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Light Wave Equation"}', 1),
  (2488, 601, 'Light travels from a vacuum into glass. Its frequency remains unchanged while its speed decreases. What happens to its wavelength?', 'text', 1, 'Use v = fλ and keep frequency constant.', '{"why":"The wavelength changes with speed when the frequency remains constant.","sol":"Step 1: v = fλ\nStep 2: Rearrange to λ = v/f.\nStep 3: If speed decreases and frequency stays constant, wavelength decreases.","steps":["Step 1: v = fλ","Step 2: Rearrange to λ = v/f.","Step 3: If speed decreases and frequency stays constant, wavelength decreases."],"options":[],"conceptId":"physics_waves_light_wave_equation","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Light Wave Equation"}', 2),
  (2489, 602, 'Which visible colour has the longest wavelength: red or violet?', 'text', 1, 'Wavelength decreases from red towards violet.', '{"why":"Red light has a longer wavelength than violet light.","sol":"Step 1: Red is at the long-wavelength end of the visible spectrum.\nStep 2: Violet is at the short-wavelength end.","steps":["Step 1: Red is at the long-wavelength end of the visible spectrum.","Step 2: Violet is at the short-wavelength end."],"options":[],"conceptId":"physics_waves_visible_light_spectrum","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Visible Light Spectrum"}', 0),
  (2490, 602, 'Which has the higher frequency: red light or violet light?', 'text', 1, 'Frequency increases from red towards violet.', '{"why":"Violet light has a higher frequency than red light.","sol":"Step 1: Red light has a lower frequency.\nStep 2: Violet light has a higher frequency.","steps":["Step 1: Red light has a lower frequency.","Step 2: Violet light has a higher frequency."],"options":[],"conceptId":"physics_waves_visible_light_spectrum","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Visible Light Spectrum"}', 1),
  (2491, 602, 'Name the part of the electromagnetic spectrum that the human eye can detect.', 'text', 1, 'It includes the colours from red to violet.', '{"why":"Visible light is the electromagnetic radiation detectable by the human eye.","sol":"Step 1: The eye detects a limited range of electromagnetic radiation.\nStep 2: That range is called visible light.","steps":["Step 1: The eye detects a limited range of electromagnetic radiation.","Step 2: That range is called visible light."],"options":[],"conceptId":"physics_waves_visible_light_spectrum","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Visible Light Spectrum"}', 2),
  (2492, 603, 'What is reflection of light?', 'text', 1, 'What happens to light when it strikes a reflecting surface?', '{"why":"Reflection occurs when light returns into the medium from which it came.","sol":"Step 1: Light travels towards a surface.\nStep 2: It bounces back into the original medium.","steps":["Step 1: Light travels towards a surface.","Step 2: It bounces back into the original medium."],"options":[],"conceptId":"physics_waves_reflection_of_light","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Reflection of Light"}', 0),
  (2493, 603, 'What is the incoming ray that strikes a reflecting surface called?', 'text', 1, 'It is the ray before reflection occurs.', '{"why":"The incident ray approaches and strikes the reflecting surface.","sol":"Step 1: Identify the ray travelling towards the surface.\nStep 2: That ray is called the incident ray.","steps":["Step 1: Identify the ray travelling towards the surface.","Step 2: That ray is called the incident ray."],"options":[],"conceptId":"physics_waves_reflection_of_light","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Reflection of Light"}', 1),
  (2494, 603, 'What is the ray that leaves a surface after reflection called?', 'text', 1, 'It is the outgoing ray.', '{"why":"The reflected ray travels away from the reflecting surface.","sol":"Step 1: Light strikes the surface.\nStep 2: The ray that leaves after bouncing back is the reflected ray.","steps":["Step 1: Light strikes the surface.","Step 2: The ray that leaves after bouncing back is the reflected ray."],"options":[],"conceptId":"physics_waves_reflection_of_light","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Reflection of Light"}', 2),
  (2495, 604, 'What is the normal to a reflecting surface?', 'text', 1, 'Think about the angle it makes with the surface.', '{"why":"The normal makes an angle of 90° with the reflecting surface.","sol":"Step 1: The normal is drawn at the point of incidence.\nStep 2: It is perpendicular to the surface.","steps":["Step 1: The normal is drawn at the point of incidence.","Step 2: It is perpendicular to the surface."],"options":[],"conceptId":"physics_waves_the_normal_and_angles_of_reflection","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"The Normal and Angles of Reflection"}', 0),
  (2496, 604, 'A ray makes an angle of 25° with a plane mirror. What is its angle with the normal?', 'text', 1, 'The mirror and normal form a 90° angle.', '{"why":"The angle measured from the normal is complementary to the angle measured from the surface.","sol":"Step 1: Angle with normal = 90° − angle with surface.\nStep 2: Angle with normal = 90° − 25°.\nStep 3: Angle with normal = 65°.","steps":["Step 1: Angle with normal = 90° − angle with surface.","Step 2: Angle with normal = 90° − 25°.","Step 3: Angle with normal = 65°."],"options":[],"conceptId":"physics_waves_the_normal_and_angles_of_reflection","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"The Normal and Angles of Reflection"}', 1),
  (2497, 604, 'A ray makes an angle of 40° with the normal. What is its angle with the mirror surface?', 'text', 1, 'The normal is perpendicular to the mirror.', '{"why":"The angles measured from the normal and the surface add up to 90°.","sol":"Step 1: The total angle between the normal and the surface is 90°.\nStep 2: Angle with surface = 90° − 40°.\nStep 3: Angle with surface = 50°.","steps":["Step 1: The total angle between the normal and the surface is 90°.","Step 2: Angle with surface = 90° − 40°.","Step 3: Angle with surface = 50°."],"options":[],"conceptId":"physics_waves_the_normal_and_angles_of_reflection","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"The Normal and Angles of Reflection"}', 2),
  (2498, 605, 'State the first law of reflection.', 'text', 1, 'Compare the two angles measured from the normal.', '{"why":"For reflection at a surface, i = r.","sol":"Step 1: The angle of incidence is i.\nStep 2: The angle of reflection is r.\nStep 3: The first law states that i = r.","steps":["Step 1: The angle of incidence is i.","Step 2: The angle of reflection is r.","Step 3: The first law states that i = r."],"options":[],"conceptId":"physics_waves_laws_of_reflection","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Laws of Reflection"}', 0),
  (2499, 605, 'The angle of incidence is 48°. Find the angle of reflection.', 'text', 1, 'Use i = r.', '{"why":"The angle of reflection equals the angle of incidence.","sol":"Step 1: i = r\nStep 2: i = 48°\nStep 3: Therefore r = 48°.","steps":["Step 1: i = r","Step 2: i = 48°","Step 3: Therefore r = 48°."],"options":[],"conceptId":"physics_waves_laws_of_reflection","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Laws of Reflection"}', 1),
  (2500, 605, 'Which three lie in the same plane during reflection?', 'text', 1, 'Name the two rays and the reference line.', '{"why":"These three lie in the same plane according to the second law of reflection.","sol":"Step 1: Identify the incident ray.\nStep 2: Identify the reflected ray.\nStep 3: Include the normal at the point of incidence.","steps":["Step 1: Identify the incident ray.","Step 2: Identify the reflected ray.","Step 3: Include the normal at the point of incidence."],"options":[],"conceptId":"physics_waves_laws_of_reflection","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Laws of Reflection"}', 2);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (2501, 606, 'A ray has an angle of incidence of 20°. Find the angle between the incident and reflected rays.', 'text', 1, 'The angle between the rays is twice the angle of incidence.', '{"why":"The incident and reflected rays make equal angles with the normal.","sol":"Step 1: Angle between rays = 2i\nStep 2: = 2 × 20°\nStep 3: = 40°","steps":["Step 1: Angle between rays = 2i","Step 2: = 2 × 20°","Step 3: = 40°"],"options":[],"conceptId":"physics_waves_angle_between_incident_and_reflected_rays","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Angle Between Incident and Reflected Rays"}', 0),
  (2502, 606, 'The angle between the incident and reflected rays is 100°. Find the angle of incidence.', 'text', 1, 'Divide the angle between the rays by 2.', '{"why":"The angle of incidence is half the angle between the two rays.","sol":"Step 1: Angle between rays = 2i\nStep 2: 100° = 2i\nStep 3: i = 100° ÷ 2 = 50°","steps":["Step 1: Angle between rays = 2i","Step 2: 100° = 2i","Step 3: i = 100° ÷ 2 = 50°"],"options":[],"conceptId":"physics_waves_angle_between_incident_and_reflected_rays","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Angle Between Incident and Reflected Rays"}', 1),
  (2503, 606, 'A ray has an angle of incidence of 45°. What is its angle of reflection, and what is the angle between the two rays?', 'text', 1, 'Apply i = r, then add the two angles.', '{"why":"The reflection angle equals the incidence angle, so the angle between the rays is 2i.","sol":"Step 1: Angle of reflection = 45°.\nStep 2: Angle between rays = 45° + 45°.\nStep 3: Angle between rays = 90°.","steps":["Step 1: Angle of reflection = 45°.","Step 2: Angle between rays = 45° + 45°.","Step 3: Angle between rays = 90°."],"options":[],"conceptId":"physics_waves_angle_between_incident_and_reflected_rays","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Angle Between Incident and Reflected Rays"}', 2),
  (2504, 607, 'Why is the image in a plane mirror called virtual?', 'text', 1, 'Do the reflected rays actually meet behind the mirror?', '{"why":"A virtual image is formed where rays appear to originate, rather than where they actually meet.","sol":"Step 1: The reflected rays enter the observer''s eye.\nStep 2: Their backward extensions appear to meet behind the mirror.\nStep 3: The rays do not actually meet at the image position.","steps":["Step 1: The reflected rays enter the observer''s eye.","Step 2: Their backward extensions appear to meet behind the mirror.","Step 3: The rays do not actually meet at the image position."],"options":[],"conceptId":"physics_waves_image_formation_in_a_plane_mirror","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Image Formation in a Plane Mirror"}', 0),
  (2505, 607, 'Where does the image of an object appear in a plane mirror?', 'text', 1, 'Consider the apparent position relative to the mirror.', '{"why":"The image appears behind the reflecting surface.","sol":"Step 1: Light reflects from the mirror into the observer''s eye.\nStep 2: The reflected rays appear to originate from behind the mirror.","steps":["Step 1: Light reflects from the mirror into the observer''s eye.","Step 2: The reflected rays appear to originate from behind the mirror."],"options":[],"conceptId":"physics_waves_image_formation_in_a_plane_mirror","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Image Formation in a Plane Mirror"}', 1),
  (2506, 607, 'Do light rays from an object actually pass through the virtual image behind a plane mirror?', 'text', 1, 'Distinguish a real meeting point from an apparent meeting point.', '{"why":"A virtual image is not formed by the actual meeting of light rays.","sol":"Step 1: The rays reflect towards the observer.\nStep 2: Only their backward extensions meet at the apparent image position.","steps":["Step 1: The rays reflect towards the observer.","Step 2: Only their backward extensions meet at the apparent image position."],"options":[],"conceptId":"physics_waves_image_formation_in_a_plane_mirror","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Image Formation in a Plane Mirror"}', 2),
  (2507, 608, 'An object is 3 m in front of a plane mirror. How far behind the mirror is its image?', 'text', 1, 'Image distance equals object distance for a plane mirror.', '{"why":"The image is the same distance behind the mirror as the object is in front.","sol":"Step 1: Object distance = 3 m.\nStep 2: Image distance = object distance.\nStep 3: Image distance = 3 m.","steps":["Step 1: Object distance = 3 m.","Step 2: Image distance = object distance.","Step 3: Image distance = 3 m."],"options":[],"conceptId":"physics_waves_properties_of_a_plane_mirror_image","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Properties of a Plane-Mirror Image"}', 0),
  (2508, 608, 'An object is 12 cm tall in front of a plane mirror. How tall is its image?', 'text', 1, 'Compare object height and image height.', '{"why":"A plane-mirror image has the same height as the object.","sol":"Step 1: A plane mirror forms an image of the same size as the object.\nStep 2: Image height = 12 cm.","steps":["Step 1: A plane mirror forms an image of the same size as the object.","Step 2: Image height = 12 cm."],"options":[],"conceptId":"physics_waves_properties_of_a_plane_mirror_image","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Properties of a Plane-Mirror Image"}', 1),
  (2509, 608, 'Which description is correct for the image formed by a plane mirror?', 'text', 1, 'Recall whether it is real or virtual, and whether it is upright or inverted.', '{"why":"These are key properties of an image formed by a plane mirror.","sol":"Step 1: The image appears behind the mirror.\nStep 2: It is virtual and upright.\nStep 3: It is the same size as the object.","steps":["Step 1: The image appears behind the mirror.","Step 2: It is virtual and upright.","Step 3: It is the same size as the object."],"options":[],"conceptId":"physics_waves_properties_of_a_plane_mirror_image","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Properties of a Plane-Mirror Image"}', 2),
  (2510, 609, 'What is lateral inversion?', 'text', 1, 'Think about how left and right appear in a plane mirror.', '{"why":"Lateral inversion is the apparent left-right reversal in a plane-mirror image.","sol":"Step 1: Look at the image in the mirror.\nStep 2: The left-right appearance is reversed.","steps":["Step 1: Look at the image in the mirror.","Step 2: The left-right appearance is reversed."],"options":[],"conceptId":"physics_waves_lateral_inversion_in_a_plane_mirror","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Lateral Inversion in a Plane Mirror"}', 0),
  (2511, 609, 'A person raises their right hand while facing a plane mirror. Which hand appears raised in the image?', 'text', 1, 'Apply left-right reversal.', '{"why":"The image appears to raise its left hand.","sol":"Step 1: A plane mirror laterally inverts the image.\nStep 2: The person''s right hand appears as the image''s left hand.","steps":["Step 1: A plane mirror laterally inverts the image.","Step 2: The person''s right hand appears as the image''s left hand."],"options":[],"conceptId":"physics_waves_lateral_inversion_in_a_plane_mirror","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Lateral Inversion in a Plane Mirror"}', 1),
  (2512, 609, 'Does lateral inversion mean that the image in a plane mirror is upside down?', 'text', 1, 'Distinguish left-right reversal from vertical orientation.', '{"why":"Lateral inversion reverses left and right, not the image''s upright orientation.","sol":"Step 1: Lateral inversion concerns the left-right appearance.\nStep 2: A plane-mirror image remains upright.","steps":["Step 1: Lateral inversion concerns the left-right appearance.","Step 2: A plane-mirror image remains upright."],"options":[],"conceptId":"physics_waves_lateral_inversion_in_a_plane_mirror","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Lateral Inversion in a Plane Mirror"}', 2),
  (2513, 610, 'What is refraction of light?', 'text', 1, 'Think about what happens when light crosses into another medium.', '{"why":"Refraction results from a change in light''s speed between media.","sol":"Step 1: Light crosses from one medium into another.\nStep 2: Its speed changes.\nStep 3: If it enters obliquely, its direction changes.","steps":["Step 1: Light crosses from one medium into another.","Step 2: Its speed changes.","Step 3: If it enters obliquely, its direction changes."],"options":[],"conceptId":"physics_waves_refraction_of_light","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Refraction of Light"}', 0),
  (2514, 610, 'What causes light to refract when it passes obliquely from air into glass?', 'text', 1, 'Consider whether light travels at the same speed in both media.', '{"why":"The change in speed causes the ray to change direction at an oblique boundary.","sol":"Step 1: Light travels at different speeds in air and glass.\nStep 2: The change in speed at an oblique boundary changes its direction.","steps":["Step 1: Light travels at different speeds in air and glass.","Step 2: The change in speed at an oblique boundary changes its direction."],"options":[],"conceptId":"physics_waves_refraction_of_light","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Refraction of Light"}', 1),
  (2515, 610, 'Does light always change direction when it enters a different medium?', 'text', 1, 'Consider a ray travelling along the normal.', '{"why":"At normal incidence, speed changes but direction remains unchanged.","sol":"Step 1: Light changes speed when entering a different optical medium.\nStep 2: At normal incidence, it does not bend away from its original direction.","steps":["Step 1: Light changes speed when entering a different optical medium.","Step 2: At normal incidence, it does not bend away from its original direction."],"options":[],"conceptId":"physics_waves_refraction_of_light","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Refraction of Light"}', 2),
  (2516, 611, 'Light enters glass obliquely from air. Towards which does it bend?', 'text', 1, 'Light slows down when it enters glass from air.', '{"why":"Light slows down and bends towards the normal when entering glass obliquely from air.","sol":"Step 1: Light enters a more optically dense medium.\nStep 2: Its speed decreases.\nStep 3: It bends towards the normal.","steps":["Step 1: Light enters a more optically dense medium.","Step 2: Its speed decreases.","Step 3: It bends towards the normal."],"options":[],"conceptId":"physics_waves_refraction_towards_the_normal","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Refraction Towards the Normal"}', 0),
  (2517, 611, 'A ray enters glass from air with an angle of incidence of 40°. Which is more likely to be the refracted angle: 25° or 55°?', 'text', 1, 'The refracted angle is smaller when light bends towards the normal.', '{"why":"A refracted angle of 25° is smaller than the incidence angle of 40°.","sol":"Step 1: Light enters glass from air.\nStep 2: It bends towards the normal.\nStep 3: The refracted angle must be smaller than 40°.","steps":["Step 1: Light enters glass from air.","Step 2: It bends towards the normal.","Step 3: The refracted angle must be smaller than 40°."],"options":[],"conceptId":"physics_waves_refraction_towards_the_normal","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Refraction Towards the Normal"}', 1),
  (2518, 611, 'Light slows down as it enters a new medium obliquely. In the usual air-to-glass case, does it bend towards or away from the normal?', 'text', 1, 'Recall the direction of bending when light enters glass from air.', '{"why":"For oblique incidence from air into glass, light bends towards the normal.","sol":"Step 1: Light slows down in glass.\nStep 2: The ray bends towards the normal.","steps":["Step 1: Light slows down in glass.","Step 2: The ray bends towards the normal."],"options":[],"conceptId":"physics_waves_refraction_towards_the_normal","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Refraction Towards the Normal"}', 2),
  (2519, 612, 'Light passes obliquely from glass into air. Which way does it bend?', 'text', 1, 'Light speeds up when it passes from glass into air.', '{"why":"Light speeds up and bends away from the normal when entering air obliquely from glass.","sol":"Step 1: Light enters a less optically dense medium.\nStep 2: Its speed increases.\nStep 3: It bends away from the normal.","steps":["Step 1: Light enters a less optically dense medium.","Step 2: Its speed increases.","Step 3: It bends away from the normal."],"options":[],"conceptId":"physics_waves_refraction_away_from_the_normal","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Refraction Away from the Normal"}', 0),
  (2520, 612, 'A ray travels from glass into air at an incidence angle of 35°. Which is more likely to be the refracted angle: 20° or 50°?', 'text', 1, 'The ray bends away from the normal.', '{"why":"The refracted angle is greater than the incidence angle in this case.","sol":"Step 1: Light passes from glass into air.\nStep 2: It bends away from the normal.\nStep 3: The refracted angle is greater than 35°.","steps":["Step 1: Light passes from glass into air.","Step 2: It bends away from the normal.","Step 3: The refracted angle is greater than 35°."],"options":[],"conceptId":"physics_waves_refraction_away_from_the_normal","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Refraction Away from the Normal"}', 1),
  (2521, 612, 'When light passes obliquely from glass into air and emerges, what happens to its speed?', 'text', 1, 'Compare light''s speed in glass with its speed in air.', '{"why":"Light travels faster in air than in glass.","sol":"Step 1: Light travels more slowly in glass than in air.\nStep 2: On entering air, its speed increases.","steps":["Step 1: Light travels more slowly in glass than in air.","Step 2: On entering air, its speed increases."],"options":[],"conceptId":"physics_waves_refraction_away_from_the_normal","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Refraction Away from the Normal"}', 2),
  (2522, 613, 'What is the angle of incidence when light strikes a boundary along the normal?', 'text', 1, 'The angle is measured between the ray and the normal.', '{"why":"At normal incidence, the incident ray and normal lie along the same line.","sol":"Step 1: The ray travels in the same direction as the normal.\nStep 2: The angle between them is 0°.","steps":["Step 1: The ray travels in the same direction as the normal.","Step 2: The angle between them is 0°."],"options":[],"conceptId":"physics_waves_refraction_at_normal_incidence","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Refraction at Normal Incidence"}', 0),
  (2523, 613, 'A ray enters glass at normal incidence. What is its angle of refraction?', 'text', 1, 'It continues along the normal.', '{"why":"At normal incidence, the ray continues straight along the normal.","sol":"Step 1: The angle of incidence is 0°.\nStep 2: The ray does not bend away from the normal.\nStep 3: The angle of refraction is 0°.","steps":["Step 1: The angle of incidence is 0°.","Step 2: The ray does not bend away from the normal.","Step 3: The angle of refraction is 0°."],"options":[],"conceptId":"physics_waves_refraction_at_normal_incidence","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Refraction at Normal Incidence"}', 1),
  (2524, 613, 'When light enters glass at normal incidence, does its speed change?', 'text', 1, 'No bending does not necessarily mean no change in speed.', '{"why":"The speed changes at the boundary even though the ray does not bend.","sol":"Step 1: Light travels at different speeds in air and glass.\nStep 2: At normal incidence, it changes speed without changing direction.","steps":["Step 1: Light travels at different speeds in air and glass.","Step 2: At normal incidence, it changes speed without changing direction."],"options":[],"conceptId":"physics_waves_refraction_at_normal_incidence","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Refraction at Normal Incidence"}', 2),
  (2525, 614, 'Write the formula for the absolute refractive index of a medium.', 'text', 1, 'Compare light''s speed in a vacuum with its speed in the medium.', '{"why":"Absolute refractive index equals the speed of light in a vacuum divided by its speed in the medium.","sol":"Step 1: The speed in a vacuum is c.\nStep 2: The speed in the medium is v.\nStep 3: Divide c by v.","steps":["Step 1: The speed in a vacuum is c.","Step 2: The speed in the medium is v.","Step 3: Divide c by v."],"options":[],"conceptId":"physics_waves_refractive_index","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Refractive Index"}', 0),
  (2526, 614, 'Light travels in a material at 2.0 × 10^8 m/s. Calculate its refractive index using c = 3.0 × 10^8 m/s.', 'text', 1, 'Use n = c/v.', '{"why":"Dividing the vacuum speed by the material speed gives 1.5.","sol":"Step 1: n = c/v\nStep 2: n = (3.0 × 10^8)/(2.0 × 10^8)\nStep 3: n = 1.5","steps":["Step 1: n = c/v","Step 2: n = (3.0 × 10^8)/(2.0 × 10^8)","Step 3: n = 1.5"],"options":[],"conceptId":"physics_waves_refractive_index","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Refractive Index"}', 1),
  (2527, 614, 'Light travels more slowly in material A than in material B. Which material has the higher absolute refractive index?', 'text', 1, 'The refractive index is inversely related to speed in the medium.', '{"why":"The material in which light travels more slowly has the higher absolute refractive index.","sol":"Step 1: n = c/v.\nStep 2: The vacuum speed c is constant.\nStep 3: A smaller medium speed v gives a larger refractive index.","steps":["Step 1: n = c/v.","Step 2: The vacuum speed c is constant.","Step 3: A smaller medium speed v gives a larger refractive index."],"options":[],"conceptId":"physics_waves_refractive_index","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Refractive Index"}', 2),
  (2528, 615, 'Write Snell''s law for light passing between two media.', 'text', 1, 'Include both refractive indices and both angles.', '{"why":"Snell''s law relates refractive indices and the sine of the angles.","sol":"Step 1: The first medium has index n₁ and incidence angle i.\nStep 2: The second medium has index n₂ and refraction angle r.\nStep 3: Equate the products of index and sine of angle.","steps":["Step 1: The first medium has index n₁ and incidence angle i.","Step 2: The second medium has index n₂ and refraction angle r.","Step 3: Equate the products of index and sine of angle."],"options":[],"conceptId":"physics_waves_snell_s_law","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Snell''s Law"}', 0),
  (2529, 615, 'Light travels from air into glass. Take n_air = 1.0, i = 30° and r = 20°. Calculate the refractive index of the glass.', 'text', 1, 'Rearrange Snell''s law to n_glass = n_air sin i / sin r.', '{"why":"Using Snell''s law gives a refractive index of approximately 1.46.","sol":"Step 1: n_glass = n_air sin i / sin r\nStep 2: n_glass = sin 30° / sin 20°\nStep 3: n_glass ≈ 0.500 / 0.342\nStep 4: n_glass ≈ 1.46","steps":["Step 1: n_glass = n_air sin i / sin r","Step 2: n_glass = sin 30° / sin 20°","Step 3: n_glass ≈ 0.500 / 0.342","Step 4: n_glass ≈ 1.46"],"options":[],"conceptId":"physics_waves_snell_s_law","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Snell''s Law"}', 1),
  (2530, 615, 'When applying Snell''s law, from which line are the angles of incidence and refraction measured?', 'text', 1, 'Use the line perpendicular to the boundary.', '{"why":"Snell''s law uses angles measured from the normal, not from the surface.","sol":"Step 1: Draw the normal at the point where light meets the boundary.\nStep 2: Measure both angles from that normal.","steps":["Step 1: Draw the normal at the point where light meets the boundary.","Step 2: Measure both angles from that normal."],"options":[],"conceptId":"physics_waves_snell_s_law","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Snell''s Law"}', 2),
  (2531, 616, 'When viewed from above the water, does the bottom of a pool usually appear shallower or deeper than it really is?', 'text', 1, 'Light refracts as it leaves water and enters air.', '{"why":"The apparent depth is less than the real depth when viewed from air near normally.","sol":"Step 1: Light from the pool bottom refracts at the surface.\nStep 2: The bottom appears closer to the surface than its real position.","steps":["Step 1: Light from the pool bottom refracts at the surface.","Step 2: The bottom appears closer to the surface than its real position."],"options":[],"conceptId":"physics_waves_apparent_depth_due_to_refraction","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Apparent Depth Due to Refraction"}', 0),
  (2532, 616, 'A pool''s real depth is 3.0 m and its apparent depth is 2.0 m. Estimate the refractive index of the water.', 'text', 1, 'Use n ≈ real depth ÷ apparent depth.', '{"why":"The approximate refractive index is the real depth divided by the apparent depth.","sol":"Step 1: n ≈ real depth / apparent depth\nStep 2: n ≈ 3.0 / 2.0\nStep 3: n ≈ 1.5","steps":["Step 1: n ≈ real depth / apparent depth","Step 2: n ≈ 3.0 / 2.0","Step 3: n ≈ 1.5"],"options":[],"conceptId":"physics_waves_apparent_depth_due_to_refraction","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Apparent Depth Due to Refraction"}', 1),
  (2533, 616, 'An object underwater appears 1.2 m below the surface. If the refractive index of the water is 1.33, estimate its real depth.', 'text', 1, 'Rearrange n ≈ real depth / apparent depth.', '{"why":"Multiply apparent depth by the refractive index to estimate real depth.","sol":"Step 1: Real depth ≈ n × apparent depth\nStep 2: Real depth ≈ 1.33 × 1.2\nStep 3: Real depth ≈ 1.596 m\nStep 4: To 2 significant figures, real depth ≈ 1.6 m.","steps":["Step 1: Real depth ≈ n × apparent depth","Step 2: Real depth ≈ 1.33 × 1.2","Step 3: Real depth ≈ 1.596 m","Step 4: To 2 significant figures, real depth ≈ 1.6 m."],"options":[],"conceptId":"physics_waves_apparent_depth_due_to_refraction","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Apparent Depth Due to Refraction"}', 2),
  (2534, 617, 'Two waves pass through the same gap. Which generally diffracts more: the wave with wavelength 3 cm or the wave with wavelength 9 cm?', 'text', 1, 'Compare wavelength while keeping the gap unchanged.', '{"why":"For a fixed gap, diffraction is generally more noticeable when wavelength is longer.","sol":"Step 1: The gap width is the same.\nStep 2: The 9 cm wavelength is longer.\nStep 3: The longer wavelength generally produces more noticeable diffraction.","steps":["Step 1: The gap width is the same.","Step 2: The 9 cm wavelength is longer.","Step 3: The longer wavelength generally produces more noticeable diffraction."],"options":[],"conceptId":"physics_waves_effect_of_wavelength_on_diffraction","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Effect of Wavelength on Diffraction"}', 0),
  (2535, 617, 'A wave''s wavelength increases while the gap width stays constant. What generally happens to diffraction?', 'text', 1, 'Consider the ratio of wavelength to gap width.', '{"why":"Increasing wavelength relative to a fixed gap generally increases diffraction.","sol":"Step 1: The gap width does not change.\nStep 2: The wavelength becomes longer relative to the gap.\nStep 3: Diffraction becomes more noticeable.","steps":["Step 1: The gap width does not change.","Step 2: The wavelength becomes longer relative to the gap.","Step 3: Diffraction becomes more noticeable."],"options":[],"conceptId":"physics_waves_effect_of_wavelength_on_diffraction","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Effect of Wavelength on Diffraction"}', 1),
  (2536, 617, 'Why does a wavelength comparable to the gap width produce noticeable diffraction?', 'text', 1, 'Think about how the wavelength compares with the size of the opening.', '{"why":"Diffraction is most noticeable when wavelength and gap width are of similar size.","sol":"Step 1: Diffraction depends on wavelength relative to gap width.\nStep 2: When the two are comparable, spreading is pronounced.","steps":["Step 1: Diffraction depends on wavelength relative to gap width.","Step 2: When the two are comparable, spreading is pronounced."],"options":[],"conceptId":"physics_waves_effect_of_wavelength_on_diffraction","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Effect of Wavelength on Diffraction"}', 2),
  (2537, 618, 'The same waves pass through a narrow gap and a much wider gap. Which usually produces more noticeable diffraction?', 'text', 1, 'Compare each gap width with the wavelength.', '{"why":"Diffraction is generally more noticeable when the gap width is comparable to the wavelength.","sol":"Step 1: The waves have the same wavelength.\nStep 2: The narrow gap is smaller relative to the wavelength.\nStep 3: It generally produces more noticeable spreading.","steps":["Step 1: The waves have the same wavelength.","Step 2: The narrow gap is smaller relative to the wavelength.","Step 3: It generally produces more noticeable spreading."],"options":[],"conceptId":"physics_waves_effect_of_gap_width_on_diffraction","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Effect of Gap Width on Diffraction"}', 0),
  (2538, 618, 'A gap is much wider than the wavelength of the waves passing through it. Is diffraction generally strong or less noticeable?', 'text', 1, 'Compare the gap size with the wavelength.', '{"why":"A gap much wider than the wavelength generally produces less noticeable diffraction.","sol":"Step 1: The gap is much wider than the wavelength.\nStep 2: The wave spreads less noticeably across the opening.","steps":["Step 1: The gap is much wider than the wavelength.","Step 2: The wave spreads less noticeably across the opening."],"options":[],"conceptId":"physics_waves_effect_of_gap_width_on_diffraction","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Effect of Gap Width on Diffraction"}', 1),
  (2539, 618, 'To investigate the effect of gap width on diffraction, what should be kept constant?', 'text', 1, 'Change only the factor being investigated.', '{"why":"Keeping wavelength constant makes it possible to isolate the effect of gap width.","sol":"Step 1: The investigation is testing gap width.\nStep 2: Keep the wavelength and other relevant conditions constant.\nStep 3: Change the gap width and compare the spreading.","steps":["Step 1: The investigation is testing gap width.","Step 2: Keep the wavelength and other relevant conditions constant.","Step 3: Change the gap width and compare the spreading."],"options":[],"conceptId":"physics_waves_effect_of_gap_width_on_diffraction","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Effect of Gap Width on Diffraction"}', 2),
  (2540, 619, 'Why can you hear a person speaking around a corner even when the person is not visible?', 'text', 1, 'Think about the spreading of waves around obstacles.', '{"why":"Sound can diffract around obstacles and reach listeners outside the direct line of sight.","sol":"Step 1: The obstacle blocks a direct path.\nStep 2: Sound waves can spread around obstacles.\nStep 3: Some sound reaches the listener.","steps":["Step 1: The obstacle blocks a direct path.","Step 2: Sound waves can spread around obstacles.","Step 3: Some sound reaches the listener."],"options":[],"conceptId":"physics_waves_diffraction_of_sound_around_obstacles","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Diffraction of Sound Around Obstacles"}', 0),
  (2541, 619, 'Sound passes through a doorway into a room. Which wave behaviour helps sound spread into the room?', 'text', 1, 'The doorway is an opening.', '{"why":"Diffraction allows sound waves to spread after passing through an opening.","sol":"Step 1: Sound reaches the opening.\nStep 2: The waves spread after passing through it.","steps":["Step 1: Sound reaches the opening.","Step 2: The waves spread after passing through it."],"options":[],"conceptId":"physics_waves_diffraction_of_sound_around_obstacles","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Diffraction of Sound Around Obstacles"}', 1),
  (2542, 619, 'Why is diffraction around everyday objects usually more noticeable for sound than for visible light?', 'text', 1, 'Compare the wavelengths of sound and visible light with object sizes.', '{"why":"Diffraction depends on wavelength relative to the size of the opening or obstacle.","sol":"Step 1: Sound generally has much longer wavelengths than visible light.\nStep 2: Visible-light wavelengths are extremely small compared with everyday obstacles.\nStep 3: Sound therefore often diffracts more noticeably around such objects.","steps":["Step 1: Sound generally has much longer wavelengths than visible light.","Step 2: Visible-light wavelengths are extremely small compared with everyday obstacles.","Step 3: Sound therefore often diffracts more noticeably around such objects."],"options":[],"conceptId":"physics_waves_diffraction_of_sound_around_obstacles","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Diffraction of Sound Around Obstacles"}', 2),
  (2543, 620, 'What is a wavefront?', 'text', 1, 'It joins points that are at the same stage of oscillation.', '{"why":"A wavefront represents points with the same phase.","sol":"Step 1: Consider several points on a wave.\nStep 2: Join points that are in the same phase.","steps":["Step 1: Consider several points on a wave.","Step 2: Join points that are in the same phase."],"options":[],"conceptId":"physics_waves_wavefronts_after_diffraction","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Wavefronts After Diffraction"}', 0),
  (2544, 620, 'Straight water-wave fronts pass through a narrow gap. What is the approximate shape of the emerging wavefronts in a two-dimensional diagram?', 'text', 1, 'The waves spread out from the opening.', '{"why":"A narrow opening produces approximately semicircular wavefronts in a two-dimensional representation.","sol":"Step 1: The waves pass through a narrow opening.\nStep 2: Diffraction makes the wavefronts spread out.\nStep 3: They are approximately semicircular.","steps":["Step 1: The waves pass through a narrow opening.","Step 2: Diffraction makes the wavefronts spread out.","Step 3: They are approximately semicircular."],"options":[],"conceptId":"physics_waves_wavefronts_after_diffraction","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Wavefronts After Diffraction"}', 1),
  (2545, 620, 'What happens to straight wavefronts after passing through a narrow opening?', 'text', 1, 'Focus on their direction and shape beyond the opening.', '{"why":"Diffraction causes wavefronts to spread after passing through an opening.","sol":"Step 1: The waves pass through the opening.\nStep 2: Diffraction causes the wavefronts to spread.","steps":["Step 1: The waves pass through the opening.","Step 2: Diffraction causes the wavefronts to spread."],"options":[],"conceptId":"physics_waves_wavefronts_after_diffraction","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Wavefronts After Diffraction"}', 2),
  (2546, 621, 'Source A produces waves at 15 Hz and source B produces waves at 15 Hz. Their phase difference remains constant. Are the sources coherent?', 'text', 1, 'Check both the frequency and phase-difference conditions.', '{"why":"Coherent sources have the same frequency and a constant phase difference.","sol":"Step 1: Both sources produce waves at 15 Hz, so their frequencies are equal.\nStep 2: Their phase difference remains constant.\nStep 3: Both conditions for coherence are satisfied.","steps":["Step 1: Both sources produce waves at 15 Hz, so their frequencies are equal.","Step 2: Their phase difference remains constant.","Step 3: Both conditions for coherence are satisfied."],"options":[],"conceptId":"physics_waves_coherent_sources","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Coherent Sources"}', 0),
  (2547, 621, 'Two sources have the same frequency, but their phase difference changes randomly. Are they coherent?', 'text', 1, 'Equal frequency is only one of the two conditions.', '{"why":"A changing phase difference prevents a stable interference pattern.","sol":"Step 1: The frequencies are equal.\nStep 2: The phase difference is not constant.\nStep 3: Therefore, the two required conditions are not both satisfied.","steps":["Step 1: The frequencies are equal.","Step 2: The phase difference is not constant.","Step 3: Therefore, the two required conditions are not both satisfied."],"options":[],"conceptId":"physics_waves_coherent_sources","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Coherent Sources"}', 1),
  (2548, 621, 'Source A produces waves at 10 Hz and source B at 12 Hz. Can they be coherent?', 'text', 1, 'Compare the frequencies.', '{"why":"Coherent sources must have the same frequency as well as a constant phase difference.","sol":"Step 1: Source A has a frequency of 10 Hz.\nStep 2: Source B has a frequency of 12 Hz.\nStep 3: The frequencies are unequal.","steps":["Step 1: Source A has a frequency of 10 Hz.","Step 2: Source B has a frequency of 12 Hz.","Step 3: The frequencies are unequal."],"options":[],"conceptId":"physics_waves_coherent_sources","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Coherent Sources"}', 2),
  (2549, 622, 'Two waves travel distances of 6 m and 10 m to the same point. Find the path difference.', 'text', 1, 'Subtract the shorter distance from the longer distance.', '{"why":"Path difference is the magnitude of the difference between the two travelled distances.","sol":"Step 1: First distance = 6 m.\nStep 2: Second distance = 10 m.\nStep 3: Path difference = |10 − 6| = 4 m.","steps":["Step 1: First distance = 6 m.","Step 2: Second distance = 10 m.","Step 3: Path difference = |10 − 6| = 4 m."],"options":[],"conceptId":"physics_waves_path_difference","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Path Difference"}', 0),
  (2550, 622, 'Two waves travel 12 m and 12 m to the same point. What is their path difference?', 'text', 1, 'The distances are equal.', '{"why":"Equal travel distances give zero path difference.","sol":"Step 1: First distance = 12 m.\nStep 2: Second distance = 12 m.\nStep 3: Path difference = |12 − 12| = 0 m.","steps":["Step 1: First distance = 12 m.","Step 2: Second distance = 12 m.","Step 3: Path difference = |12 − 12| = 0 m."],"options":[],"conceptId":"physics_waves_path_difference","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Path Difference"}', 1),
  (2551, 622, 'A wave travels 7 m farther than another wave. What is the path difference?', 'text', 1, 'The extra distance travelled is the path difference.', '{"why":"Path difference measures how much farther one wave travels than the other.","sol":"Step 1: The difference between the travel distances is given directly.\nStep 2: Path difference = 7 m.","steps":["Step 1: The difference between the travel distances is given directly.","Step 2: Path difference = 7 m."],"options":[],"conceptId":"physics_waves_path_difference","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Path Difference"}', 2),
  (2552, 623, 'Two in-phase sources produce waves with wavelength 2 m. The path difference at point P is 6 m. Is the interference constructive or destructive?', 'text', 1, 'Divide the path difference by the wavelength.', '{"why":"For in-phase sources, constructive interference occurs when the path difference is a whole-number multiple of the wavelength.","sol":"Step 1: Path difference = 6 m.\nStep 2: Wavelength = 2 m.\nStep 3: 6 ÷ 2 = 3, so the path difference is 3λ.\nStep 4: Three is a whole number, so constructive interference occurs.","steps":["Step 1: Path difference = 6 m.","Step 2: Wavelength = 2 m.","Step 3: 6 ÷ 2 = 3, so the path difference is 3λ.","Step 4: Three is a whole number, so constructive interference occurs."],"options":[],"conceptId":"physics_waves_constructive_interference_condition","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Constructive Interference Condition"}', 0),
  (2553, 623, 'Two in-phase sources produce waves of wavelength 0.4 m. The path difference is 0.8 m. Find the type of interference.', 'text', 1, 'Express 0.8 m in wavelengths.', '{"why":"A path difference of 2λ satisfies the constructive-interference condition.","sol":"Step 1: Path difference = 0.8 m.\nStep 2: Wavelength = 0.4 m.\nStep 3: 0.8 ÷ 0.4 = 2.\nStep 4: The path difference is 2λ, so the interference is constructive.","steps":["Step 1: Path difference = 0.8 m.","Step 2: Wavelength = 0.4 m.","Step 3: 0.8 ÷ 0.4 = 2.","Step 4: The path difference is 2λ, so the interference is constructive."],"options":[],"conceptId":"physics_waves_constructive_interference_condition","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Constructive Interference Condition"}', 1),
  (2554, 623, 'For two in-phase sources, the path difference is 4λ. Does this satisfy the condition for constructive interference?', 'text', 1, 'Check whether the multiplier is a whole number.', '{"why":"Four wavelengths is a whole-number multiple of the wavelength.","sol":"Step 1: The path difference is 4λ.\nStep 2: The multiplier, 4, is a whole number.\nStep 3: Therefore, the constructive-interference condition is satisfied.","steps":["Step 1: The path difference is 4λ.","Step 2: The multiplier, 4, is a whole number.","Step 3: Therefore, the constructive-interference condition is satisfied."],"options":[],"conceptId":"physics_waves_constructive_interference_condition","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Constructive Interference Condition"}', 2),
  (2555, 624, 'Two in-phase sources produce waves with wavelength 2 m. The path difference at point P is 1 m. What type of interference occurs?', 'text', 1, 'Compare 1 m with half the wavelength.', '{"why":"A half-wavelength path difference produces opposite-phase arrival for waves emitted in phase.","sol":"Step 1: Wavelength = 2 m.\nStep 2: Half the wavelength = 2 ÷ 2 = 1 m.\nStep 3: The path difference is ½λ.\nStep 4: Destructive interference occurs.","steps":["Step 1: Wavelength = 2 m.","Step 2: Half the wavelength = 2 ÷ 2 = 1 m.","Step 3: The path difference is ½λ.","Step 4: Destructive interference occurs."],"options":[],"conceptId":"physics_waves_destructive_interference_condition","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Destructive Interference Condition"}', 0),
  (2556, 624, 'The wavelength is 0.8 m and the path difference is 1.2 m. For two in-phase sources, identify the interference.', 'text', 1, 'Divide the path difference by the wavelength.', '{"why":"A path difference of 1½ wavelengths satisfies the destructive-interference condition.","sol":"Step 1: Path difference = 1.2 m.\nStep 2: Wavelength = 0.8 m.\nStep 3: 1.2 ÷ 0.8 = 1.5.\nStep 4: The path difference is 1½λ, so the interference is destructive.","steps":["Step 1: Path difference = 1.2 m.","Step 2: Wavelength = 0.8 m.","Step 3: 1.2 ÷ 0.8 = 1.5.","Step 4: The path difference is 1½λ, so the interference is destructive."],"options":[],"conceptId":"physics_waves_destructive_interference_condition","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Destructive Interference Condition"}', 1),
  (2557, 624, 'Two waves arrive in opposite phase at a point. Each has a displacement magnitude of 4 cm. Find the resultant displacement at that instant.', 'text', 1, 'Opposite displacements have opposite signs.', '{"why":"Equal and opposite displacements cancel completely at that instant.","sol":"Step 1: Take the first displacement as +4 cm.\nStep 2: The opposite displacement is −4 cm.\nStep 3: Resultant displacement = +4 + (−4) = 0 cm.","steps":["Step 1: Take the first displacement as +4 cm.","Step 2: The opposite displacement is −4 cm.","Step 3: Resultant displacement = +4 + (−4) = 0 cm."],"options":[],"conceptId":"physics_waves_destructive_interference_condition","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Destructive Interference Condition"}', 2),
  (2558, 625, 'Two waves of the same frequency travel in opposite directions along a string and superpose. What type of wave pattern can form?', 'text', 1, 'Think of an incoming wave overlapping its reflected wave.', '{"why":"Two suitable waves travelling in opposite directions can form a stationary wave.","sol":"Step 1: The waves have the same frequency.\nStep 2: They travel in opposite directions.\nStep 3: Their superposition can produce a stationary-wave pattern.","steps":["Step 1: The waves have the same frequency.","Step 2: They travel in opposite directions.","Step 3: Their superposition can produce a stationary-wave pattern."],"options":[],"conceptId":"physics_waves_formation_of_stationary_waves","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Formation of Stationary Waves"}', 0),
  (2559, 625, 'A wave travels along a string and reflects from a fixed end. The reflected wave overlaps the incoming wave. What produces the stationary pattern?', 'text', 1, 'The two waves overlap rather than acting separately.', '{"why":"A stationary wave results from the superposition of suitable waves travelling in opposite directions.","sol":"Step 1: The incoming wave travels towards the fixed end.\nStep 2: The reflected wave travels back in the opposite direction.\nStep 3: The waves superpose to produce a stationary pattern.","steps":["Step 1: The incoming wave travels towards the fixed end.","Step 2: The reflected wave travels back in the opposite direction.","Step 3: The waves superpose to produce a stationary pattern."],"options":[],"conceptId":"physics_waves_formation_of_stationary_waves","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Formation of Stationary Waves"}', 1),
  (2560, 625, 'Which has fixed nodes: a progressive wave or a stationary wave?', 'text', 1, 'A node is a position that remains at zero displacement.', '{"why":"Nodes are fixed positions in a stationary-wave pattern.","sol":"Step 1: A progressive wave pattern travels along the medium.\nStep 2: A stationary wave has positions that remain nodes.\nStep 3: Therefore, the stationary wave has fixed nodes.","steps":["Step 1: A progressive wave pattern travels along the medium.","Step 2: A stationary wave has positions that remain nodes.","Step 3: Therefore, the stationary wave has fixed nodes."],"options":[],"conceptId":"physics_waves_formation_of_stationary_waves","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Formation of Stationary Waves"}', 2),
  (2561, 626, 'The distance between adjacent nodes is 0.2 m. Find the wavelength.', 'text', 1, 'The node separation is half a wavelength.', '{"why":"Adjacent nodes are separated by half a wavelength.","sol":"Step 1: Distance between adjacent nodes = λ/2 = 0.2 m.\nStep 2: Multiply both sides by 2.\nStep 3: λ = 2 × 0.2 = 0.4 m.","steps":["Step 1: Distance between adjacent nodes = λ/2 = 0.2 m.","Step 2: Multiply both sides by 2.","Step 3: λ = 2 × 0.2 = 0.4 m."],"options":[],"conceptId":"physics_waves_nodes_in_stationary_waves","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Nodes in Stationary Waves"}', 0),
  (2562, 626, 'A stationary wave has a wavelength of 1.2 m. Find the distance between adjacent nodes.', 'text', 1, 'Divide the wavelength by 2.', '{"why":"The separation of adjacent nodes is half the wavelength.","sol":"Step 1: Wavelength λ = 1.2 m.\nStep 2: Adjacent-node distance = λ/2.\nStep 3: Distance = 1.2 ÷ 2 = 0.6 m.","steps":["Step 1: Wavelength λ = 1.2 m.","Step 2: Adjacent-node distance = λ/2.","Step 3: Distance = 1.2 ÷ 2 = 0.6 m."],"options":[],"conceptId":"physics_waves_nodes_in_stationary_waves","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Nodes in Stationary Waves"}', 1),
  (2563, 626, 'What is the displacement of a node at all times in an ideal stationary wave?', 'text', 1, 'A node is the point where cancellation is complete.', '{"why":"A node always has zero resultant displacement.","sol":"Step 1: At a node, the two wave displacements are equal and opposite.\nStep 2: Their resultant displacement is zero.\nStep 3: This remains true throughout the oscillation.","steps":["Step 1: At a node, the two wave displacements are equal and opposite.","Step 2: Their resultant displacement is zero.","Step 3: This remains true throughout the oscillation."],"options":[],"conceptId":"physics_waves_nodes_in_stationary_waves","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Nodes in Stationary Waves"}', 2),
  (2564, 627, 'A stationary wave has a wavelength of 1.2 m. Find the distance from a node to its nearest antinode.', 'text', 1, 'A node and its nearest antinode are separated by one-quarter of a wavelength.', '{"why":"Use λ/4 because the question asks for the distance between a node and its nearest antinode.","sol":"Step 1: Identify the relationship: d = λ/4.\nStep 2: Substitute λ = 1.2 m.\nStep 3: d = 1.2/4 = 0.3 m.","steps":["Step 1: Identify the relationship: d = λ/4.","Step 2: Substitute λ = 1.2 m.","Step 3: d = 1.2/4 = 0.3 m."],"options":[],"conceptId":"physics_waves_antinodes_in_stationary_waves","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Antinodes in Stationary Waves"}', 0),
  (2565, 627, 'Adjacent antinodes are 0.45 m apart. Calculate the wavelength.', 'text', 1, 'The distance between adjacent antinodes is half the wavelength.', '{"why":"Multiply the given separation by 2 to obtain the full wavelength.","sol":"Step 1: Write d = λ/2.\nStep 2: Rearrange to obtain λ = 2d.\nStep 3: λ = 2 × 0.45 = 0.90 m.","steps":["Step 1: Write d = λ/2.","Step 2: Rearrange to obtain λ = 2d.","Step 3: λ = 2 × 0.45 = 0.90 m."],"options":[],"conceptId":"physics_waves_antinodes_in_stationary_waves","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Antinodes in Stationary Waves"}', 1),
  (2566, 627, 'The distance from a node to its nearest antinode is 0.08 m. Find the wavelength.', 'text', 1, 'Start with d = λ/4 and make λ the subject.', '{"why":"Multiplying the distance by 4 gives the full wavelength.","sol":"Step 1: Write d = λ/4.\nStep 2: Rearrange to obtain λ = 4d.\nStep 3: λ = 4 × 0.08 = 0.32 m.","steps":["Step 1: Write d = λ/4.","Step 2: Rearrange to obtain λ = 4d.","Step 3: λ = 4 × 0.08 = 0.32 m."],"options":[],"conceptId":"physics_waves_antinodes_in_stationary_waves","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Antinodes in Stationary Waves"}', 2),
  (2567, 627, 'Which point on a stationary wave has the greatest oscillation amplitude?', 'text', 1, 'Compare the point with zero amplitude to the point with maximum amplitude.', '{"why":"The defining property of an antinode is its maximum amplitude.","sol":"Step 1: A node has zero oscillation amplitude.\nStep 2: An antinode has maximum oscillation amplitude.\nStep 3: Therefore, the antinode has the greatest amplitude.","steps":["Step 1: A node has zero oscillation amplitude.","Step 2: An antinode has maximum oscillation amplitude.","Step 3: Therefore, the antinode has the greatest amplitude."],"options":[],"conceptId":"physics_waves_antinodes_in_stationary_waves","skillId":"physics_waves","subskillId":"physics_waves_q4","subject":"physics","chapter":"waves","topic":"Antinodes in Stationary Waves"}', 3),
  (2568, 627, 'The wavelength of a stationary wave is 0.8 m. What is the distance between adjacent antinodes?', 'text', 1, 'Adjacent antinodes are separated by half a wavelength, not a quarter.', '{"why":"Using λ/4 here would confuse adjacent antinodes with a node and its nearest antinode.","sol":"Step 1: Identify the relationship: d = λ/2.\nStep 2: Substitute λ = 0.8 m.\nStep 3: d = 0.8/2 = 0.4 m.","steps":["Step 1: Identify the relationship: d = λ/2.","Step 2: Substitute λ = 0.8 m.","Step 3: d = 0.8/2 = 0.4 m."],"options":[],"conceptId":"physics_waves_antinodes_in_stationary_waves","skillId":"physics_waves","subskillId":"physics_waves_q5","subject":"physics","chapter":"waves","topic":"Antinodes in Stationary Waves"}', 4),
  (2569, 628, 'What is the SI unit of electric charge?', 'mcq', 1, 'The symbol for this unit is C.', '{"why":"The coulomb is the SI unit of electric charge.","sol":"Step 1: Electric charge is represented by Q.\nStep 2: Its SI unit is the coulomb (C).","steps":["Step 1: Electric charge is represented by Q.","Step 2: Its SI unit is the coulomb (C)."],"options":[{"text":"Ampere","is_correct":false},{"text":"Volt","is_correct":false},{"text":"Coulomb","is_correct":false},{"text":"Ohm","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_em_meaning_of_electric_charge","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Meaning of Electric Charge"}', 0),
  (2570, 628, 'Which particle carries a negative electric charge?', 'mcq', 1, 'It is the particle that moves through a metal wire.', '{"why":"Electrons carry negative electric charge.","sol":"Step 1: Protons are positively charged.\nStep 2: Electrons are negatively charged.\nStep 3: Neutrons have no net charge.","steps":["Step 1: Protons are positively charged.","Step 2: Electrons are negatively charged.","Step 3: Neutrons have no net charge."],"options":[{"text":"Proton","is_correct":false},{"text":"Electron","is_correct":false},{"text":"Neutron","is_correct":false},{"text":"Nucleus as a whole in every case","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_meaning_of_electric_charge","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Meaning of Electric Charge"}', 1),
  (2571, 628, 'A body gains electrons. What happens to its net charge?', 'mcq', 1, 'Consider the sign of an electron''s charge.', '{"why":"A body that gains electrons becomes more negatively charged.","sol":"Step 1: Each electron carries negative charge.\nStep 2: Gaining electrons adds negative charge.","steps":["Step 1: Each electron carries negative charge.","Step 2: Gaining electrons adds negative charge."],"options":[{"text":"It becomes more positive","is_correct":false},{"text":"It becomes more negative","is_correct":false},{"text":"It must become neutral","is_correct":false},{"text":"Its charge cannot change","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_meaning_of_electric_charge","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Meaning of Electric Charge"}', 2),
  (2572, 628, 'Which symbol represents electric charge in the equation I = Q/t?', 'mcq', 1, 'It is the quantity measured in coulombs.', '{"why":"Q is the symbol for electric charge.","sol":"Step 1: I represents current.\nStep 2: Q represents charge.\nStep 3: t represents time.","steps":["Step 1: I represents current.","Step 2: Q represents charge.","Step 3: t represents time."],"options":[{"text":"I","is_correct":false},{"text":"Q","is_correct":false},{"text":"t","is_correct":false},{"text":"V","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_meaning_of_electric_charge","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Meaning of Electric Charge"}', 3),
  (2573, 629, 'What is electric current?', 'mcq', 1, 'Current tells you how quickly charge passes a point.', '{"why":"Electric current is charge passing a point per unit time.","sol":"Step 1: Current measures charge flow per unit time.\nStep 2: Therefore, it is the rate of flow of electric charge.","steps":["Step 1: Current measures charge flow per unit time.","Step 2: Therefore, it is the rate of flow of electric charge."],"options":[{"text":"The amount of energy stored in a battery","is_correct":false},{"text":"The rate of flow of electric charge","is_correct":false},{"text":"The resistance of a wire","is_correct":false},{"text":"The total charge in every atom","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_meaning_of_electric_current","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Meaning of Electric Current"}', 0),
  (2574, 629, 'A current of 1 A is equivalent to:', 'mcq', 1, 'Use I = Q/t.', '{"why":"One ampere equals one coulomb per second.","sol":"Step 1: I = Q/t.\nStep 2: One ampere means one coulomb divided by one second.","steps":["Step 1: I = Q/t.","Step 2: One ampere means one coulomb divided by one second."],"options":[{"text":"1 C/s","is_correct":false},{"text":"1 J/C","is_correct":false},{"text":"1 C × s","is_correct":false},{"text":"1 V/s","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_em_meaning_of_electric_current","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Meaning of Electric Current"}', 1),
  (2575, 629, 'A current of 4 A flows through a wire. How much charge passes a point in one second?', 'mcq', 1, 'Each ampere represents one coulomb per second.', '{"why":"Four coulombs pass the point each second.","sol":"Step 1: 4 A = 4 C/s.\nStep 2: In 1 s, charge passing = 4 × 1 = 4 C.","steps":["Step 1: 4 A = 4 C/s.","Step 2: In 1 s, charge passing = 4 × 1 = 4 C."],"options":[{"text":"0.25 C","is_correct":false},{"text":"1 C","is_correct":false},{"text":"4 C","is_correct":false},{"text":"8 C","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_em_meaning_of_electric_current","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Meaning of Electric Current"}', 2),
  (2576, 629, 'In a metal wire, electron drift is in which direction relative to conventional current?', 'mcq', 1, 'Remember that electrons have negative charge.', '{"why":"Electron drift is opposite to conventional current in a metal wire.","sol":"Step 1: Conventional current is defined in the direction positive charge would move.\nStep 2: Electrons carry negative charge and drift in the opposite direction.","steps":["Step 1: Conventional current is defined in the direction positive charge would move.","Step 2: Electrons carry negative charge and drift in the opposite direction."],"options":[{"text":"The same direction","is_correct":false},{"text":"The opposite direction","is_correct":false},{"text":"Always perpendicular","is_correct":false},{"text":"Electrons do not move","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_meaning_of_electric_current","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Meaning of Electric Current"}', 3),
  (2577, 630, 'A charge of 20 C passes a point in 5 s. Calculate the current.', 'mcq', 1, 'Use I = Q/t.', '{"why":"The current is 4 A.","sol":"Step 1: I = Q/t.\nStep 2: I = 20/5.\nStep 3: I = 4 A.","steps":["Step 1: I = Q/t.","Step 2: I = 20/5.","Step 3: I = 4 A."],"options":[{"text":"2 A","is_correct":false},{"text":"4 A","is_correct":false},{"text":"5 A","is_correct":false},{"text":"100 A","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_calculating_electric_current","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Calculating Electric Current"}', 0),
  (2578, 630, 'A charge of 36 C passes through a wire in 12 s. What is the current?', 'mcq', 1, 'Divide 36 C by 12 s.', '{"why":"The current is 3 A.","sol":"Step 1: I = Q/t.\nStep 2: I = 36/12.\nStep 3: I = 3 A.","steps":["Step 1: I = Q/t.","Step 2: I = 36/12.","Step 3: I = 3 A."],"options":[{"text":"2 A","is_correct":false},{"text":"3 A","is_correct":false},{"text":"4 A","is_correct":false},{"text":"6 A","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_calculating_electric_current","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Calculating Electric Current"}', 1),
  (2579, 630, 'A charge of 240 C passes a point in 2 minutes. Calculate the current.', 'mcq', 1, 'Convert 2 minutes to seconds first.', '{"why":"The current is 2 A.","sol":"Step 1: 2 minutes = 120 seconds.\nStep 2: I = 240/120.\nStep 3: I = 2 A.","steps":["Step 1: 2 minutes = 120 seconds.","Step 2: I = 240/120.","Step 3: I = 2 A."],"options":[{"text":"1 A","is_correct":false},{"text":"2 A","is_correct":false},{"text":"4 A","is_correct":false},{"text":"120 A","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_calculating_electric_current","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Calculating Electric Current"}', 2),
  (2580, 630, 'A charge of 15 C passes a point in 0.5 s. What is the current?', 'mcq', 1, 'Divide 15 by 0.5.', '{"why":"The current is 30 A.","sol":"Step 1: I = Q/t.\nStep 2: I = 15/0.5.\nStep 3: I = 30 A.","steps":["Step 1: I = Q/t.","Step 2: I = 15/0.5.","Step 3: I = 30 A."],"options":[{"text":"7.5 A","is_correct":false},{"text":"15 A","is_correct":false},{"text":"30 A","is_correct":false},{"text":"45 A","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_em_calculating_electric_current","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Calculating Electric Current"}', 3),
  (2581, 631, 'A current of 3 A flows for 5 s. Calculate the charge transferred.', 'mcq', 1, 'Use Q = It.', '{"why":"The total charge transferred is 15 C.","sol":"Step 1: Q = It.\nStep 2: Q = 3 × 5.\nStep 3: Q = 15 C.","steps":["Step 1: Q = It.","Step 2: Q = 3 × 5.","Step 3: Q = 15 C."],"options":[{"text":"8 C","is_correct":false},{"text":"15 C","is_correct":false},{"text":"1.7 C","is_correct":false},{"text":"30 C","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_calculating_electric_charge","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Calculating Electric Charge"}', 0),
  (2582, 631, 'A current of 0.2 A flows for 30 s. What charge passes the point?', 'mcq', 1, 'Multiply 0.2 by 30.', '{"why":"The charge transferred is 6 C.","sol":"Step 1: Q = It.\nStep 2: Q = 0.2 × 30.\nStep 3: Q = 6 C.","steps":["Step 1: Q = It.","Step 2: Q = 0.2 × 30.","Step 3: Q = 6 C."],"options":[{"text":"0.15 C","is_correct":false},{"text":"6 C","is_correct":false},{"text":"15 C","is_correct":false},{"text":"150 C","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_calculating_electric_charge","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Calculating Electric Charge"}', 1),
  (2583, 631, 'A current of 4 A flows for 2 minutes. Calculate the charge transferred.', 'mcq', 1, 'Convert 2 minutes to 120 seconds.', '{"why":"The charge transferred is 480 C.","sol":"Step 1: t = 2 × 60 = 120 s.\nStep 2: Q = It = 4 × 120.\nStep 3: Q = 480 C.","steps":["Step 1: t = 2 × 60 = 120 s.","Step 2: Q = It = 4 × 120.","Step 3: Q = 480 C."],"options":[{"text":"8 C","is_correct":false},{"text":"120 C","is_correct":false},{"text":"240 C","is_correct":false},{"text":"480 C","is_correct":false},{"text":"3","is_correct":true}],"conceptId":"physics_em_calculating_electric_charge","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Calculating Electric Charge"}', 2),
  (2584, 631, 'A charge of 50 C passes through a conductor carrying 5 A. How long does the transfer take?', 'mcq', 1, 'Rearrange Q = It to make t the subject.', '{"why":"The transfer takes 10 seconds.","sol":"Step 1: Q = It.\nStep 2: t = Q/I.\nStep 3: t = 50/5 = 10 s.","steps":["Step 1: Q = It.","Step 2: t = Q/I.","Step 3: t = 50/5 = 10 s."],"options":[{"text":"5 s","is_correct":false},{"text":"10 s","is_correct":false},{"text":"25 s","is_correct":false},{"text":"250 s","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_calculating_electric_charge","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Calculating Electric Charge"}', 3),
  (2585, 632, 'What does a potential difference of 1 V mean?', 'mcq', 1, 'Use V = E/Q.', '{"why":"A potential difference of 1 V corresponds to 1 J of energy transferred per coulomb.","sol":"Step 1: Potential difference is energy transferred per unit charge.\nStep 2: One volt equals one joule per coulomb.","steps":["Step 1: Potential difference is energy transferred per unit charge.","Step 2: One volt equals one joule per coulomb."],"options":[{"text":"1 C flows every second","is_correct":false},{"text":"1 J of energy is transferred per coulomb","is_correct":false},{"text":"1 Ω of resistance is present","is_correct":false},{"text":"1 A flows through every component","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_meaning_and_calculation_of_potential_difference","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Meaning and Calculation of Potential Difference"}', 0),
  (2586, 632, 'A component transfers 30 J of energy to 5 C of charge. Calculate the potential difference.', 'mcq', 1, 'Use V = E/Q.', '{"why":"The potential difference is 6 V.","sol":"Step 1: V = E/Q.\nStep 2: V = 30/5.\nStep 3: V = 6 V.","steps":["Step 1: V = E/Q.","Step 2: V = 30/5.","Step 3: V = 6 V."],"options":[{"text":"5 V","is_correct":false},{"text":"6 V","is_correct":false},{"text":"25 V","is_correct":false},{"text":"150 V","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_meaning_and_calculation_of_potential_difference","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Meaning and Calculation of Potential Difference"}', 1),
  (2587, 632, 'A charge of 4 C passes through a component with a potential difference of 8 V. Calculate the energy transferred.', 'mcq', 1, 'Rearrange V = E/Q to E = VQ.', '{"why":"The energy transferred is 32 J.","sol":"Step 1: E = VQ.\nStep 2: E = 8 × 4.\nStep 3: E = 32 J.","steps":["Step 1: E = VQ.","Step 2: E = 8 × 4.","Step 3: E = 32 J."],"options":[{"text":"2 J","is_correct":false},{"text":"12 J","is_correct":false},{"text":"32 J","is_correct":false},{"text":"64 J","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_em_meaning_and_calculation_of_potential_difference","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Meaning and Calculation of Potential Difference"}', 2),
  (2588, 632, 'Which quantity describes the rate of flow of electric charge?', 'mcq', 1, 'It is measured in amperes.', '{"why":"Electric current measures the rate of flow of charge.","sol":"Step 1: Current is charge transferred per unit time.\nStep 2: Its SI unit is the ampere.","steps":["Step 1: Current is charge transferred per unit time.","Step 2: Its SI unit is the ampere."],"options":[{"text":"Potential difference","is_correct":false},{"text":"Resistance","is_correct":false},{"text":"Electric current","is_correct":false},{"text":"Energy","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_em_meaning_and_calculation_of_potential_difference","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Meaning and Calculation of Potential Difference"}', 3),
  (2589, 633, 'What is electrical resistance?', 'mcq', 1, 'It describes how much a component opposes current.', '{"why":"Electrical resistance is the opposition a material or component offers to current.","sol":"Step 1: Resistance opposes the flow of electric current.\nStep 2: Its symbol is R.","steps":["Step 1: Resistance opposes the flow of electric current.","Step 2: Its symbol is R."],"options":[{"text":"The rate of flow of charge","is_correct":false},{"text":"The opposition a component offers to current","is_correct":false},{"text":"Energy transferred per coulomb","is_correct":false},{"text":"The total charge in a wire","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_meaning_of_electrical_resistance","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Meaning of Electrical Resistance"}', 0),
  (2590, 633, 'What is the SI unit of resistance?', 'mcq', 1, 'Its symbol is Ω.', '{"why":"The ohm is the SI unit of electrical resistance.","sol":"Step 1: Resistance is represented by R.\nStep 2: Resistance is measured in ohms (Ω).","steps":["Step 1: Resistance is represented by R.","Step 2: Resistance is measured in ohms (Ω)."],"options":[{"text":"Ampere","is_correct":false},{"text":"Volt","is_correct":false},{"text":"Ohm","is_correct":false},{"text":"Coulomb","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_em_meaning_of_electrical_resistance","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Meaning of Electrical Resistance"}', 1),
  (2591, 633, 'Two resistors have the same potential difference across them. Which carries less current if both obey Ohm''s law?', 'mcq', 1, 'Use I = V/R.', '{"why":"At the same potential difference, a larger resistance produces a smaller current for an ohmic component.","sol":"Step 1: The potential difference is the same.\nStep 2: Current equals voltage divided by resistance.\nStep 3: Greater resistance therefore gives smaller current.","steps":["Step 1: The potential difference is the same.","Step 2: Current equals voltage divided by resistance.","Step 3: Greater resistance therefore gives smaller current."],"options":[{"text":"The resistor with greater resistance","is_correct":false},{"text":"The resistor with smaller resistance","is_correct":false},{"text":"Both must carry zero current","is_correct":false},{"text":"Resistance does not affect current","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_em_meaning_of_electrical_resistance","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Meaning of Electrical Resistance"}', 2),
  (2592, 633, 'Which symbol represents electrical resistance?', 'mcq', 1, 'It appears in V = IR.', '{"why":"The symbol for resistance is R.","sol":"Step 1: In V = IR, V is voltage and I is current.\nStep 2: R represents resistance.","steps":["Step 1: In V = IR, V is voltage and I is current.","Step 2: R represents resistance."],"options":[{"text":"Q","is_correct":false},{"text":"R","is_correct":false},{"text":"I","is_correct":false},{"text":"t","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_meaning_of_electrical_resistance","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Meaning of Electrical Resistance"}', 3),
  (2593, 634, 'A resistor has 10 V across it and carries 2 A. Calculate its resistance.', 'mcq', 1, 'Use R = V/I.', '{"why":"The resistance is 5 Ω.","sol":"Step 1: R = V/I.\nStep 2: R = 10/2.\nStep 3: R = 5 Ω.","steps":["Step 1: R = V/I.","Step 2: R = 10/2.","Step 3: R = 5 Ω."],"options":[{"text":"2 Ω","is_correct":false},{"text":"5 Ω","is_correct":false},{"text":"8 Ω","is_correct":false},{"text":"20 Ω","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_calculating_electrical_resistance","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Calculating Electrical Resistance"}', 0),
  (2594, 634, 'A component has a potential difference of 9 V and a current of 0.3 A. Find its resistance.', 'mcq', 1, 'Divide 9 by 0.3.', '{"why":"The resistance is 30 Ω.","sol":"Step 1: R = V/I.\nStep 2: R = 9/0.3.\nStep 3: R = 30 Ω.","steps":["Step 1: R = V/I.","Step 2: R = 9/0.3.","Step 3: R = 30 Ω."],"options":[{"text":"3 Ω","is_correct":false},{"text":"27 Ω","is_correct":false},{"text":"30 Ω","is_correct":false},{"text":"90 Ω","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_em_calculating_electrical_resistance","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Calculating Electrical Resistance"}', 1),
  (2595, 634, 'A resistor carries 4 A when the potential difference is 20 V. What is its resistance?', 'mcq', 1, 'Resistance equals voltage divided by current.', '{"why":"The resistance is 5 Ω.","sol":"Step 1: R = 20/4.\nStep 2: R = 5 Ω.","steps":["Step 1: R = 20/4.","Step 2: R = 5 Ω."],"options":[{"text":"4 Ω","is_correct":false},{"text":"5 Ω","is_correct":false},{"text":"16 Ω","is_correct":false},{"text":"80 Ω","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_calculating_electrical_resistance","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Calculating Electrical Resistance"}', 2),
  (2596, 634, 'A component has 12 V across it and carries 0.5 A. Calculate its resistance.', 'mcq', 1, 'Calculate 12 ÷ 0.5.', '{"why":"The resistance is 24 Ω.","sol":"Step 1: R = V/I.\nStep 2: R = 12/0.5.\nStep 3: R = 24 Ω.","steps":["Step 1: R = V/I.","Step 2: R = 12/0.5.","Step 3: R = 24 Ω."],"options":[{"text":"6 Ω","is_correct":false},{"text":"12 Ω","is_correct":false},{"text":"24 Ω","is_correct":false},{"text":"36 Ω","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_em_calculating_electrical_resistance","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Calculating Electrical Resistance"}', 3),
  (2597, 635, 'A 5 Ω resistor is connected across 15 V. Calculate the current.', 'mcq', 1, 'Use I = V/R.', '{"why":"The current is 3 A.","sol":"Step 1: I = V/R.\nStep 2: I = 15/5.\nStep 3: I = 3 A.","steps":["Step 1: I = V/R.","Step 2: I = 15/5.","Step 3: I = 3 A."],"options":[{"text":"2 A","is_correct":false},{"text":"3 A","is_correct":false},{"text":"5 A","is_correct":false},{"text":"75 A","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_calculating_current_using_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Calculating Current Using Ohm''s Law"}', 0),
  (2598, 635, 'A 40 Ω resistor is connected across 12 V. Find the current.', 'mcq', 1, 'Divide 12 by 40.', '{"why":"The current is 0.3 A.","sol":"Step 1: I = 12/40.\nStep 2: I = 0.3 A.","steps":["Step 1: I = 12/40.","Step 2: I = 0.3 A."],"options":[{"text":"0.3 A","is_correct":false},{"text":"3.3 A","is_correct":false},{"text":"28 A","is_correct":false},{"text":"480 A","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_em_calculating_current_using_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Calculating Current Using Ohm''s Law"}', 1),
  (2599, 635, 'A 3 Ω resistor has a potential difference of 9 V across it. Calculate the current.', 'mcq', 1, 'Current equals voltage divided by resistance.', '{"why":"The current is 3 A.","sol":"Step 1: I = V/R.\nStep 2: I = 9/3.\nStep 3: I = 3 A.","steps":["Step 1: I = V/R.","Step 2: I = 9/3.","Step 3: I = 3 A."],"options":[{"text":"2 A","is_correct":false},{"text":"3 A","is_correct":false},{"text":"6 A","is_correct":false},{"text":"27 A","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_calculating_current_using_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Calculating Current Using Ohm''s Law"}', 2),
  (2600, 635, 'A 12 Ω resistor is connected across 6 V. What current flows through it?', 'mcq', 1, 'Use I = 6/12.', '{"why":"The current is 0.5 A.","sol":"Step 1: I = V/R.\nStep 2: I = 6/12.\nStep 3: I = 0.5 A.","steps":["Step 1: I = V/R.","Step 2: I = 6/12.","Step 3: I = 0.5 A."],"options":[{"text":"0.5 A","is_correct":false},{"text":"2 A","is_correct":false},{"text":"6 A","is_correct":false},{"text":"72 A","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_em_calculating_current_using_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Calculating Current Using Ohm''s Law"}', 3),
  (2601, 636, 'A 6 Ω resistor carries 3 A. Calculate the potential difference.', 'mcq', 1, 'Use V = IR.', '{"why":"The potential difference is 18 V.","sol":"Step 1: V = IR.\nStep 2: V = 3 × 6.\nStep 3: V = 18 V.","steps":["Step 1: V = IR.","Step 2: V = 3 × 6.","Step 3: V = 18 V."],"options":[{"text":"2 V","is_correct":false},{"text":"9 V","is_correct":false},{"text":"18 V","is_correct":false},{"text":"36 V","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_em_calculating_potential_difference_using_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Calculating Potential Difference Using Ohm''s Law"}', 0),
  (2602, 636, 'A 10 Ω resistor carries 0.2 A. What is the potential difference?', 'mcq', 1, 'Multiply 10 by 0.2.', '{"why":"The potential difference is 2 V.","sol":"Step 1: V = IR.\nStep 2: V = 10 × 0.2.\nStep 3: V = 2 V.","steps":["Step 1: V = IR.","Step 2: V = 10 × 0.2.","Step 3: V = 2 V."],"options":[{"text":"0.02 V","is_correct":false},{"text":"2 V","is_correct":false},{"text":"5 V","is_correct":false},{"text":"50 V","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_calculating_potential_difference_using_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Calculating Potential Difference Using Ohm''s Law"}', 1),
  (2603, 636, 'A resistor of 2.5 Ω carries 4 A. Calculate the potential difference.', 'mcq', 1, 'Use V = 4 × 2.5.', '{"why":"The potential difference is 10 V.","sol":"Step 1: V = IR.\nStep 2: V = 4 × 2.5.\nStep 3: V = 10 V.","steps":["Step 1: V = IR.","Step 2: V = 4 × 2.5.","Step 3: V = 10 V."],"options":[{"text":"1.6 V","is_correct":false},{"text":"6.5 V","is_correct":false},{"text":"10 V","is_correct":false},{"text":"16 V","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_em_calculating_potential_difference_using_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Calculating Potential Difference Using Ohm''s Law"}', 2),
  (2604, 636, 'A 20 Ω resistor carries a current of 0.5 A. Find the voltage across it.', 'mcq', 1, 'Multiply current by resistance.', '{"why":"The potential difference is 10 V.","sol":"Step 1: V = IR.\nStep 2: V = 0.5 × 20.\nStep 3: V = 10 V.","steps":["Step 1: V = IR.","Step 2: V = 0.5 × 20.","Step 3: V = 10 V."],"options":[{"text":"10 V","is_correct":false},{"text":"20 V","is_correct":false},{"text":"40 V","is_correct":false},{"text":"100 V","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_em_calculating_potential_difference_using_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Calculating Potential Difference Using Ohm''s Law"}', 3),
  (2605, 637, 'Which condition is required when stating Ohm''s law?', 'mcq', 1, 'Temperature changes can affect resistance.', '{"why":"Ohm''s law is stated for a conductor under constant physical conditions, particularly constant temperature.","sol":"Step 1: Ohm''s law relates current and voltage.\nStep 2: The proportionality holds when temperature and other relevant conditions remain constant.","steps":["Step 1: Ohm''s law relates current and voltage.","Step 2: The proportionality holds when temperature and other relevant conditions remain constant."],"options":[{"text":"The conductor must be at constant temperature","is_correct":false},{"text":"The current must always be zero","is_correct":false},{"text":"The resistance must always be infinite","is_correct":false},{"text":"The conductor must contain no electrons","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_em_ohm_s_law_and_voltage_current_graphs","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Ohm''s Law and Voltage-Current Graphs"}', 0),
  (2606, 637, 'A conductor has a straight-line V-I graph through the origin. What does this indicate under constant conditions?', 'mcq', 1, 'A straight line through the origin shows direct proportionality.', '{"why":"The graph indicates constant resistance under the stated conditions.","sol":"Step 1: A straight line through the origin means V is proportional to I.\nStep 2: Therefore V/I is constant.\nStep 3: Since R = V/I, resistance is constant.","steps":["Step 1: A straight line through the origin means V is proportional to I.","Step 2: Therefore V/I is constant.","Step 3: Since R = V/I, resistance is constant."],"options":[{"text":"Its resistance is constant","is_correct":false},{"text":"Its current is always zero","is_correct":false},{"text":"Its resistance must be zero","is_correct":false},{"text":"Its voltage never changes","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_em_ohm_s_law_and_voltage_current_graphs","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Ohm''s Law and Voltage-Current Graphs"}', 1),
  (2607, 637, 'On a graph with V on the vertical axis and I on the horizontal axis, what does the gradient represent for an ohmic resistor?', 'mcq', 1, 'Gradient = change in V divided by change in I.', '{"why":"The gradient of a V-I graph is resistance.","sol":"Step 1: Gradient = ΔV/ΔI.\nStep 2: For an ohmic resistor, V = IR.\nStep 3: Therefore the gradient equals R.","steps":["Step 1: Gradient = ΔV/ΔI.","Step 2: For an ohmic resistor, V = IR.","Step 3: Therefore the gradient equals R."],"options":[{"text":"Current","is_correct":false},{"text":"Charge","is_correct":false},{"text":"Resistance","is_correct":false},{"text":"Time","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_em_ohm_s_law_and_voltage_current_graphs","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Ohm''s Law and Voltage-Current Graphs"}', 2),
  (2608, 637, 'Two resistors have V-I graph gradients of 3 V/A and 8 V/A. Which has the greater resistance?', 'mcq', 1, 'With voltage vertical and current horizontal, gradient equals resistance.', '{"why":"The resistor with gradient 8 V/A has the greater resistance.","sol":"Step 1: Resistance equals the V-I graph gradient.\nStep 2: The gradients correspond to 3 Ω and 8 Ω.\nStep 3: 8 Ω is greater than 3 Ω.","steps":["Step 1: Resistance equals the V-I graph gradient.","Step 2: The gradients correspond to 3 Ω and 8 Ω.","Step 3: 8 Ω is greater than 3 Ω."],"options":[{"text":"The resistor with gradient 3 V/A","is_correct":false},{"text":"The resistor with gradient 8 V/A","is_correct":false},{"text":"Both must have equal resistance","is_correct":false},{"text":"Neither has resistance","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_ohm_s_law_and_voltage_current_graphs","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Ohm''s Law and Voltage-Current Graphs"}', 3),
  (2609, 638, 'A cell and three resistors are connected one after another in one closed loop. What type of circuit is formed?', 'mcq', 1, 'Look at how many paths the current can take.', '{"why":"A series circuit has one continuous path for current.","sol":"Step 1: The components are connected one after another.\nStep 2: There is only one path through them.\nStep 3: A circuit with one path is a series circuit.","steps":["Step 1: The components are connected one after another.","Step 2: There is only one path through them.","Step 3: A circuit with one path is a series circuit."],"options":[{"text":"Parallel circuit","is_correct":false},{"text":"Series circuit","is_correct":false},{"text":"Open circuit","is_correct":false},{"text":"Short circuit","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_identifying_a_series_circuit","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Identifying a Series Circuit"}', 0),
  (2610, 638, 'How many paths are available for current through components connected in series?', 'mcq', 1, 'Series components share one route.', '{"why":"Current has only one route through a series arrangement.","sol":"Step 1: Identify the connection: series.\nStep 2: A series arrangement has no branching path.\nStep 3: Therefore, there is one path.","steps":["Step 1: Identify the connection: series.","Step 2: A series arrangement has no branching path.","Step 3: Therefore, there is one path."],"options":[{"text":"One","is_correct":false},{"text":"Two","is_correct":false},{"text":"Three","is_correct":false},{"text":"An unlimited number","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_em_identifying_a_series_circuit","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Identifying a Series Circuit"}', 1),
  (2611, 638, 'Two lamps are connected in series. One is removed, leaving a gap. What happens to the other lamp?', 'mcq', 1, 'Can current still complete the circuit?', '{"why":"An open circuit prevents current from flowing around the series loop.","sol":"Step 1: Removing the lamp creates a break.\nStep 2: The only path is now incomplete.\nStep 3: Current stops, so the other lamp goes out.","steps":["Step 1: Removing the lamp creates a break.","Step 2: The only path is now incomplete.","Step 3: Current stops, so the other lamp goes out."],"options":[{"text":"It becomes brighter","is_correct":false},{"text":"It remains unchanged","is_correct":false},{"text":"It goes out","is_correct":false},{"text":"It doubles its brightness","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_em_identifying_a_series_circuit","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Identifying a Series Circuit"}', 2),
  (2612, 638, 'Which feature identifies a series circuit?', 'mcq', 1, 'Focus on the number of current paths.', '{"why":"The single path is the defining feature of a series circuit.","sol":"Step 1: A series circuit connects components one after another.\nStep 2: There is one continuous path.\nStep 3: Therefore, option B identifies a series circuit.","steps":["Step 1: A series circuit connects components one after another.","Step 2: There is one continuous path.","Step 3: Therefore, option B identifies a series circuit."],"options":[{"text":"Each component has its own separate branch","is_correct":false},{"text":"There is one path through the components","is_correct":false},{"text":"There is no source of electrical energy","is_correct":false},{"text":"Current cannot flow in a closed circuit","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_identifying_a_series_circuit","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Identifying a Series Circuit"}', 3),
  (2613, 639, 'A series circuit carries 0.7 A through the first resistor. What current flows through the second resistor?', 'mcq', 1, 'Current is the same through every component in series.', '{"why":"There are no branches in which the current can divide.","sol":"Step 1: The first resistor carries 0.7 A.\nStep 2: Current remains the same along the single path.\nStep 3: The second resistor also carries 0.7 A.","steps":["Step 1: The first resistor carries 0.7 A.","Step 2: Current remains the same along the single path.","Step 3: The second resistor also carries 0.7 A."],"options":[{"text":"0.35 A","is_correct":false},{"text":"0.7 A","is_correct":false},{"text":"1.4 A","is_correct":false},{"text":"7.0 A","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_current_in_a_series_circuit","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Current in a Series Circuit"}', 0),
  (2614, 639, 'An ammeter reads 350 mA in a series circuit. What should an ideal ammeter elsewhere in the same path read?', 'mcq', 1, 'Keep the same current value and unit.', '{"why":"Current does not split in a series circuit.","sol":"Step 1: Current is equal at all points in series.\nStep 2: The first reading is 350 mA.\nStep 3: The second reading is also 350 mA.","steps":["Step 1: Current is equal at all points in series.","Step 2: The first reading is 350 mA.","Step 3: The second reading is also 350 mA."],"options":[{"text":"175 mA","is_correct":false},{"text":"700 mA","is_correct":false},{"text":"350 mA","is_correct":false},{"text":"0 mA","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_em_current_in_a_series_circuit","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Current in a Series Circuit"}', 1),
  (2615, 639, 'Three current readings in a series circuit are 1.2 A, I and 1.2 A. Find I.', 'mcq', 1, 'All readings along a series path are equal.', '{"why":"The unknown current must equal the known readings.","sol":"Step 1: The first reading is 1.2 A.\nStep 2: The current is the same throughout the series path.\nStep 3: Therefore, I = 1.2 A.","steps":["Step 1: The first reading is 1.2 A.","Step 2: The current is the same throughout the series path.","Step 3: Therefore, I = 1.2 A."],"options":[{"text":"0.6 A","is_correct":false},{"text":"1.2 A","is_correct":false},{"text":"2.4 A","is_correct":false},{"text":"3.6 A","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_current_in_a_series_circuit","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Current in a Series Circuit"}', 2),
  (2616, 639, 'Why is current the same through all components in a series circuit?', 'mcq', 1, 'Think about whether charge can divide into different paths.', '{"why":"The single path makes the current equal throughout the series circuit.","sol":"Step 1: A series circuit has one path.\nStep 2: Charge cannot split between branches.\nStep 3: The same rate of charge flow passes through every component.","steps":["Step 1: A series circuit has one path.","Step 2: Charge cannot split between branches.","Step 3: The same rate of charge flow passes through every component."],"options":[{"text":"Every resistor has the same resistance","is_correct":false},{"text":"The supply voltage is zero","is_correct":false},{"text":"There is only one path for charge flow","is_correct":false},{"text":"Each component has its own branch","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_em_current_in_a_series_circuit","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Current in a Series Circuit"}', 3),
  (2617, 640, 'Two series resistors have voltage drops of 4 V and 6 V. What is the supply voltage?', 'mcq', 1, 'Add the voltage drops.', '{"why":"The supply voltage accounts for the energy transferred across all series components.","sol":"Step 1: Supply voltage equals the sum of the drops.\nStep 2: V = 4 + 6.\nStep 3: V = 10 V.","steps":["Step 1: Supply voltage equals the sum of the drops.","Step 2: V = 4 + 6.","Step 3: V = 10 V."],"options":[{"text":"2 V","is_correct":false},{"text":"6 V","is_correct":false},{"text":"10 V","is_correct":false},{"text":"24 V","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_em_potential_difference_in_a_series_circuit","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Potential Difference in a Series Circuit"}', 0),
  (2618, 640, 'A 9 V supply is connected to two series resistors. One has a voltage drop of 3 V. Find the other voltage drop.', 'mcq', 1, 'Subtract the known drop from the supply voltage.', '{"why":"The two voltage drops must add to the 9 V supply.","sol":"Step 1: Supply voltage = first drop + second drop.\nStep 2: 9 = 3 + V₂.\nStep 3: V₂ = 9 − 3 = 6 V.","steps":["Step 1: Supply voltage = first drop + second drop.","Step 2: 9 = 3 + V₂.","Step 3: V₂ = 9 − 3 = 6 V."],"options":[{"text":"3 V","is_correct":false},{"text":"6 V","is_correct":false},{"text":"9 V","is_correct":false},{"text":"12 V","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_potential_difference_in_a_series_circuit","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Potential Difference in a Series Circuit"}', 1),
  (2619, 640, 'Three series components have voltage drops of 1.5 V, 2.5 V and 4 V. Find the supply voltage.', 'mcq', 1, 'Add all three voltage drops.', '{"why":"The supply voltage equals the total of all component voltage drops.","sol":"Step 1: V = 1.5 + 2.5 + 4.\nStep 2: 1.5 + 2.5 = 4.\nStep 3: V = 4 + 4 = 8 V.","steps":["Step 1: V = 1.5 + 2.5 + 4.","Step 2: 1.5 + 2.5 = 4.","Step 3: V = 4 + 4 = 8 V."],"options":[{"text":"4 V","is_correct":false},{"text":"6 V","is_correct":false},{"text":"8 V","is_correct":false},{"text":"10 V","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_em_potential_difference_in_a_series_circuit","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Potential Difference in a Series Circuit"}', 2),
  (2620, 640, 'A series circuit has a 15 V supply. The voltage drops across two components are 5 V and 4 V. What is the voltage drop across the third component?', 'mcq', 1, 'Add the known drops, then subtract their total from 15 V.', '{"why":"All voltage drops in the series circuit must total 15 V.","sol":"Step 1: Known drops: 5 + 4 = 9 V.\nStep 2: Unknown drop = 15 − 9.\nStep 3: Unknown drop = 6 V.","steps":["Step 1: Known drops: 5 + 4 = 9 V.","Step 2: Unknown drop = 15 − 9.","Step 3: Unknown drop = 6 V."],"options":[{"text":"4 V","is_correct":false},{"text":"5 V","is_correct":false},{"text":"6 V","is_correct":false},{"text":"9 V","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_em_potential_difference_in_a_series_circuit","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Potential Difference in a Series Circuit"}', 3),
  (2621, 641, 'Resistors of 3 Ω and 8 Ω are connected in series. Find their total resistance.', 'mcq', 1, 'Add the individual resistances.', '{"why":"Series resistances add directly.","sol":"Step 1: Rₜ = R₁ + R₂.\nStep 2: Rₜ = 3 + 8.\nStep 3: Rₜ = 11 Ω.","steps":["Step 1: Rₜ = R₁ + R₂.","Step 2: Rₜ = 3 + 8.","Step 3: Rₜ = 11 Ω."],"options":[{"text":"5 Ω","is_correct":false},{"text":"11 Ω","is_correct":false},{"text":"24 Ω","is_correct":false},{"text":"2.4 Ω","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_total_resistance_in_a_series_circuit","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Total Resistance in a Series Circuit"}', 0),
  (2622, 641, 'Three resistors of 2 Ω, 7 Ω and 9 Ω are connected in series. Find the total resistance.', 'mcq', 1, 'Add all three resistance values.', '{"why":"The total resistance is the sum of all resistances in series.","sol":"Step 1: Rₜ = 2 + 7 + 9.\nStep 2: 2 + 7 = 9.\nStep 3: Rₜ = 9 + 9 = 18 Ω.","steps":["Step 1: Rₜ = 2 + 7 + 9.","Step 2: 2 + 7 = 9.","Step 3: Rₜ = 9 + 9 = 18 Ω."],"options":[{"text":"9 Ω","is_correct":false},{"text":"14 Ω","is_correct":false},{"text":"18 Ω","is_correct":false},{"text":"126 Ω","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_em_total_resistance_in_a_series_circuit","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Total Resistance in a Series Circuit"}', 1),
  (2623, 641, 'Two series resistors have a total resistance of 20 Ω. One is 12 Ω. Find the other.', 'mcq', 1, 'Subtract the known resistance from the total.', '{"why":"The unknown resistance is the total minus the known resistance.","sol":"Step 1: Rₜ = R₁ + R₂.\nStep 2: 20 = 12 + R₂.\nStep 3: R₂ = 20 − 12 = 8 Ω.","steps":["Step 1: Rₜ = R₁ + R₂.","Step 2: 20 = 12 + R₂.","Step 3: R₂ = 20 − 12 = 8 Ω."],"options":[{"text":"8 Ω","is_correct":false},{"text":"12 Ω","is_correct":false},{"text":"20 Ω","is_correct":false},{"text":"32 Ω","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_em_total_resistance_in_a_series_circuit","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Total Resistance in a Series Circuit"}', 2),
  (2624, 641, 'What happens to total resistance when another positive resistance is added in series?', 'mcq', 1, 'Use the rule Rₜ = R₁ + R₂ + ...', '{"why":"Every additional series resistor increases the combined resistance.","sol":"Step 1: Total resistance is the sum of the resistances.\nStep 2: Adding another positive resistance adds to the sum.\nStep 3: Therefore, total resistance increases.","steps":["Step 1: Total resistance is the sum of the resistances.","Step 2: Adding another positive resistance adds to the sum.","Step 3: Therefore, total resistance increases."],"options":[{"text":"It decreases","is_correct":false},{"text":"It becomes zero","is_correct":false},{"text":"It increases","is_correct":false},{"text":"It always stays the same","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_em_total_resistance_in_a_series_circuit","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Total Resistance in a Series Circuit"}', 3),
  (2625, 642, 'A 12 V supply is connected to 2 Ω and 4 Ω resistors in series. What is the current?', 'mcq', 1, 'Add the resistances, then use I = V/R.', '{"why":"The current is determined by the supply voltage divided by total series resistance.","sol":"Step 1: Total resistance: Rₜ = 2 + 4 = 6 Ω.\nStep 2: Use I = V/Rₜ.\nStep 3: I = 12/6 = 2 A.","steps":["Step 1: Total resistance: Rₜ = 2 + 4 = 6 Ω.","Step 2: Use I = V/Rₜ.","Step 3: I = 12/6 = 2 A."],"options":[{"text":"1 A","is_correct":false},{"text":"2 A","is_correct":false},{"text":"3 A","is_correct":false},{"text":"6 A","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_solving_series_circuit_problems","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Solving Series Circuit Problems"}', 0),
  (2626, 642, 'A 15 V supply is connected to 3 Ω and 2 Ω resistors in series. Find the voltage drop across the 3 Ω resistor.', 'mcq', 1, 'Find current first, then use V = IR.', '{"why":"The voltage drop across a resistor equals the current multiplied by its resistance.","sol":"Step 1: Total resistance: Rₜ = 3 + 2 = 5 Ω.\nStep 2: Current: I = 15/5 = 3 A.\nStep 3: Voltage across 3 Ω: V = 3 × 3 = 9 V.","steps":["Step 1: Total resistance: Rₜ = 3 + 2 = 5 Ω.","Step 2: Current: I = 15/5 = 3 A.","Step 3: Voltage across 3 Ω: V = 3 × 3 = 9 V."],"options":[{"text":"3 V","is_correct":false},{"text":"6 V","is_correct":false},{"text":"9 V","is_correct":false},{"text":"15 V","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_em_solving_series_circuit_problems","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Solving Series Circuit Problems"}', 1),
  (2627, 642, 'A 12 V supply produces a current of 2 A through two series resistors. One resistor is 4 Ω. Find the other resistance.', 'mcq', 1, 'Calculate total resistance using R = V/I, then subtract 4 Ω.', '{"why":"The total series resistance equals the sum of the two resistances.","sol":"Step 1: Total resistance: Rₜ = 12/2 = 6 Ω.\nStep 2: The two resistances add to 6 Ω.\nStep 3: Unknown resistance = 6 − 4 = 2 Ω.","steps":["Step 1: Total resistance: Rₜ = 12/2 = 6 Ω.","Step 2: The two resistances add to 6 Ω.","Step 3: Unknown resistance = 6 − 4 = 2 Ω."],"options":[{"text":"2 Ω","is_correct":false},{"text":"4 Ω","is_correct":false},{"text":"6 Ω","is_correct":false},{"text":"8 Ω","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_em_solving_series_circuit_problems","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Solving Series Circuit Problems"}', 2),
  (2628, 642, 'A 9 V supply is connected to 1 Ω and 2 Ω resistors in series. Which pair gives the correct current and voltage drop across the 2 Ω resistor?', 'mcq', 1, 'Find total resistance first, then current, then use V = IR for the 2 Ω resistor.', '{"why":"The current is 3 A throughout the series circuit, so the 2 Ω resistor has a 6 V voltage drop.","sol":"Step 1: Total resistance: Rₜ = 1 + 2 = 3 Ω.\nStep 2: Current: I = 9/3 = 3 A.\nStep 3: Voltage across 2 Ω: V = 3 × 2 = 6 V.","steps":["Step 1: Total resistance: Rₜ = 1 + 2 = 3 Ω.","Step 2: Current: I = 9/3 = 3 A.","Step 3: Voltage across 2 Ω: V = 3 × 2 = 6 V."],"options":[{"text":"Current 3 A; voltage drop 6 V","is_correct":false},{"text":"Current 9 A; voltage drop 18 V","is_correct":false},{"text":"Current 1 A; voltage drop 2 V","is_correct":false},{"text":"Current 3 A; voltage drop 3 V","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_em_solving_series_circuit_problems","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Solving Series Circuit Problems"}', 3),
  (2629, 643, 'Two lamps are connected on separate branches between the same two junctions. What type of circuit is this?', 'mcq', 1, 'Look for separate paths between junctions.', '{"why":"A parallel arrangement provides separate paths for current.","sol":"Step 1: The lamps are on separate branches.\nStep 2: Each branch connects between the same two junctions.\nStep 3: This is a parallel circuit.","steps":["Step 1: The lamps are on separate branches.","Step 2: Each branch connects between the same two junctions.","Step 3: This is a parallel circuit."],"options":[{"text":"Series circuit","is_correct":false},{"text":"Parallel circuit","is_correct":false},{"text":"Open circuit","is_correct":false},{"text":"Single-component circuit","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_identifying_a_parallel_circuit","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Identifying a Parallel Circuit"}', 0),
  (2630, 643, 'Three resistors are connected on three separate branches in a parallel arrangement. How many resistor branches are there?', 'mcq', 1, 'Each resistor occupies its own branch.', '{"why":"The number of branches containing resistors is three.","sol":"Step 1: Each resistor is on a separate branch.\nStep 2: There are three resistors.\nStep 3: Therefore, there are three resistor branches.","steps":["Step 1: Each resistor is on a separate branch.","Step 2: There are three resistors.","Step 3: Therefore, there are three resistor branches."],"options":[{"text":"One","is_correct":false},{"text":"Two","is_correct":false},{"text":"Three","is_correct":false},{"text":"Six","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_em_identifying_a_parallel_circuit","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Identifying a Parallel Circuit"}', 1),
  (2631, 643, 'One lamp in a parallel circuit is disconnected. The other lamp''s branch is still complete. What happens to the other lamp?', 'mcq', 1, 'Does the other lamp still have a complete path?', '{"why":"Parallel branches provide separate paths for current.","sol":"Step 1: The disconnected lamp breaks its own branch.\nStep 2: The other branch remains complete.\nStep 3: Current can continue through the other lamp.","steps":["Step 1: The disconnected lamp breaks its own branch.","Step 2: The other branch remains complete.","Step 3: Current can continue through the other lamp."],"options":[{"text":"It must go out","is_correct":false},{"text":"It can remain lit","is_correct":false},{"text":"It must have zero voltage","is_correct":false},{"text":"The battery stops supplying energy immediately","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_identifying_a_parallel_circuit","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Identifying a Parallel Circuit"}', 2),
  (2632, 643, 'Which description best identifies a parallel circuit?', 'mcq', 1, 'Think about the connection points and branches.', '{"why":"Parallel components share the same two junctions but occupy separate paths.","sol":"Step 1: A parallel circuit has multiple branches.\nStep 2: The branches connect across the same two junctions.\nStep 3: Therefore, option B is correct.","steps":["Step 1: A parallel circuit has multiple branches.","Step 2: The branches connect across the same two junctions.","Step 3: Therefore, option B is correct."],"options":[{"text":"Every component is connected one after another in one path","is_correct":false},{"text":"Components are connected on separate branches between the same two junctions","is_correct":false},{"text":"There is no complete path for current","is_correct":false},{"text":"All components must have equal resistance","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_identifying_a_parallel_circuit","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Identifying a Parallel Circuit"}', 3),
  (2633, 644, 'Two resistors are connected in parallel across a 12 V supply. What is the potential difference across the first resistor?', 'mcq', 1, 'Every branch is connected across the same supply.', '{"why":"The potential difference across each ideal parallel branch equals the supply voltage.","sol":"Step 1: The first resistor is connected across the supply.\nStep 2: The supply voltage is 12 V.\nStep 3: The branch voltage is 12 V.","steps":["Step 1: The first resistor is connected across the supply.","Step 2: The supply voltage is 12 V.","Step 3: The branch voltage is 12 V."],"options":[{"text":"6 V","is_correct":false},{"text":"12 V","is_correct":false},{"text":"24 V","is_correct":false},{"text":"0 V","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_potential_difference_in_a_parallel_circuit","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Potential Difference in a Parallel Circuit"}', 0),
  (2634, 644, 'Three lamps are connected in parallel across a 9 V battery. What is the voltage across each lamp?', 'mcq', 1, 'The voltage is not shared between parallel branches.', '{"why":"Parallel branches have the same potential difference.","sol":"Step 1: Each lamp is connected across the same two junctions.\nStep 2: Each branch has the supply potential difference.\nStep 3: Each lamp has 9 V across it.","steps":["Step 1: Each lamp is connected across the same two junctions.","Step 2: Each branch has the supply potential difference.","Step 3: Each lamp has 9 V across it."],"options":[{"text":"3 V","is_correct":false},{"text":"6 V","is_correct":false},{"text":"9 V","is_correct":false},{"text":"27 V","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_em_potential_difference_in_a_parallel_circuit","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Potential Difference in a Parallel Circuit"}', 1),
  (2635, 644, 'A branch in an ideal parallel circuit has a potential difference of 5 V. What is the supply voltage?', 'mcq', 1, 'Branch voltage equals supply voltage.', '{"why":"Each parallel branch is connected across the supply.","sol":"Step 1: Vbranch = Vsupply.\nStep 2: The branch voltage is 5 V.\nStep 3: The supply voltage is 5 V.","steps":["Step 1: Vbranch = Vsupply.","Step 2: The branch voltage is 5 V.","Step 3: The supply voltage is 5 V."],"options":[{"text":"2.5 V","is_correct":false},{"text":"5 V","is_correct":false},{"text":"10 V","is_correct":false},{"text":"15 V","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_potential_difference_in_a_parallel_circuit","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Potential Difference in a Parallel Circuit"}', 2),
  (2636, 644, 'Which statement about voltage in a parallel circuit is correct?', 'mcq', 1, 'Each branch connects across the same two junctions.', '{"why":"The same pair of junctions determines the potential difference across each branch.","sol":"Step 1: Both ends of each branch connect to the same pair of junctions.\nStep 2: The potential difference between those junctions is common to all branches.\nStep 3: Therefore, branch voltage is the same.","steps":["Step 1: Both ends of each branch connect to the same pair of junctions.","Step 2: The potential difference between those junctions is common to all branches.","Step 3: Therefore, branch voltage is the same."],"options":[{"text":"It is always zero in every branch","is_correct":false},{"text":"It must be divided equally between branches","is_correct":false},{"text":"The potential difference is the same across each branch","is_correct":false},{"text":"The branch voltages must add to twice the supply voltage","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_em_potential_difference_in_a_parallel_circuit","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Potential Difference in a Parallel Circuit"}', 3),
  (2637, 645, 'Two parallel branches carry 1.2 A and 0.8 A. Find the total current.', 'mcq', 1, 'Add the two branch currents.', '{"why":"The total current equals the sum of the currents in all branches.","sol":"Step 1: Iₜ = I₁ + I₂.\nStep 2: Iₜ = 1.2 + 0.8.\nStep 3: Iₜ = 2.0 A.","steps":["Step 1: Iₜ = I₁ + I₂.","Step 2: Iₜ = 1.2 + 0.8.","Step 3: Iₜ = 2.0 A."],"options":[{"text":"0.4 A","is_correct":false},{"text":"1.0 A","is_correct":false},{"text":"2.0 A","is_correct":false},{"text":"2.4 A","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_em_total_current_in_a_parallel_circuit","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Total Current in a Parallel Circuit"}', 0),
  (2638, 645, 'Three branches carry 0.4 A, 0.6 A and 1.0 A. Find the total current.', 'mcq', 1, 'Add all three currents.', '{"why":"Current entering the branches equals the sum of the branch currents.","sol":"Step 1: Iₜ = 0.4 + 0.6 + 1.0.\nStep 2: 0.4 + 0.6 = 1.0.\nStep 3: Iₜ = 1.0 + 1.0 = 2.0 A.","steps":["Step 1: Iₜ = 0.4 + 0.6 + 1.0.","Step 2: 0.4 + 0.6 = 1.0.","Step 3: Iₜ = 1.0 + 1.0 = 2.0 A."],"options":[{"text":"0.6 A","is_correct":false},{"text":"1.0 A","is_correct":false},{"text":"1.6 A","is_correct":false},{"text":"2.0 A","is_correct":false},{"text":"3","is_correct":true}],"conceptId":"physics_em_total_current_in_a_parallel_circuit","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Total Current in a Parallel Circuit"}', 1),
  (2639, 645, 'The total current in a parallel circuit is 5 A. One branch carries 2 A. Find the current in the other branch.', 'mcq', 1, 'Subtract the known branch current from the total.', '{"why":"The unknown branch current is the total current minus the known branch current.","sol":"Step 1: Iₜ = I₁ + I₂.\nStep 2: 5 = 2 + I₂.\nStep 3: I₂ = 5 − 2 = 3 A.","steps":["Step 1: Iₜ = I₁ + I₂.","Step 2: 5 = 2 + I₂.","Step 3: I₂ = 5 − 2 = 3 A."],"options":[{"text":"2 A","is_correct":false},{"text":"3 A","is_correct":false},{"text":"5 A","is_correct":false},{"text":"7 A","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_total_current_in_a_parallel_circuit","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Total Current in a Parallel Circuit"}', 2),
  (2640, 645, 'Two branches in parallel have currents of 1 A and 4 A. What is the current supplied to the junction before the current divides?', 'mcq', 1, 'The incoming current equals the sum of the outgoing branch currents.', '{"why":"The total incoming current equals the sum of the branch currents.","sol":"Step 1: Use Iₜ = I₁ + I₂.\nStep 2: Iₜ = 1 + 4.\nStep 3: Iₜ = 5 A.","steps":["Step 1: Use Iₜ = I₁ + I₂.","Step 2: Iₜ = 1 + 4.","Step 3: Iₜ = 5 A."],"options":[{"text":"3 A","is_correct":false},{"text":"4 A","is_correct":false},{"text":"5 A","is_correct":false},{"text":"0.25 A","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_em_total_current_in_a_parallel_circuit","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Total Current in a Parallel Circuit"}', 3),
  (2641, 646, 'Two 4 Ω resistors are connected in parallel. Find the equivalent resistance.', 'mcq', 1, 'For two equal resistors in parallel, divide one resistance by two.', '{"why":"Two equal resistors in parallel have half the resistance of either resistor.","sol":"Step 1: The resistors are equal at 4 Ω each.\nStep 2: Rₜ = R/n = 4/2.\nStep 3: Rₜ = 2 Ω.","steps":["Step 1: The resistors are equal at 4 Ω each.","Step 2: Rₜ = R/n = 4/2.","Step 3: Rₜ = 2 Ω."],"options":[{"text":"2 Ω","is_correct":false},{"text":"4 Ω","is_correct":false},{"text":"8 Ω","is_correct":false},{"text":"16 Ω","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_em_equivalent_resistance_in_a_parallel_circuit","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Equivalent Resistance in a Parallel Circuit"}', 0),
  (2642, 646, 'Resistors of 3 Ω and 6 Ω are connected in parallel. Find the equivalent resistance.', 'mcq', 1, 'Use Rₜ = (R₁ × R₂)/(R₁ + R₂).', '{"why":"The equivalent resistance is 2 Ω, less than the smallest individual resistance of 3 Ω.","sol":"Step 1: Rₜ = (3 × 6)/(3 + 6).\nStep 2: Rₜ = 18/9.\nStep 3: Rₜ = 2 Ω.","steps":["Step 1: Rₜ = (3 × 6)/(3 + 6).","Step 2: Rₜ = 18/9.","Step 3: Rₜ = 2 Ω."],"options":[{"text":"2 Ω","is_correct":false},{"text":"3 Ω","is_correct":false},{"text":"4.5 Ω","is_correct":false},{"text":"9 Ω","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_em_equivalent_resistance_in_a_parallel_circuit","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Equivalent Resistance in a Parallel Circuit"}', 1),
  (2643, 646, 'Three 12 Ω resistors are connected in parallel. Find their equivalent resistance.', 'mcq', 1, 'For equal resistors in parallel, divide the resistance by the number of resistors.', '{"why":"Three equal resistors in parallel have an equivalent resistance equal to one-third of a single resistor.","sol":"Step 1: Each resistor has a resistance of 12 Ω.\nStep 2: There are three equal parallel resistors.\nStep 3: Rₜ = 12/3 = 4 Ω.","steps":["Step 1: Each resistor has a resistance of 12 Ω.","Step 2: There are three equal parallel resistors.","Step 3: Rₜ = 12/3 = 4 Ω."],"options":[{"text":"4 Ω","is_correct":false},{"text":"12 Ω","is_correct":false},{"text":"24 Ω","is_correct":false},{"text":"36 Ω","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_em_equivalent_resistance_in_a_parallel_circuit","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Equivalent Resistance in a Parallel Circuit"}', 2),
  (2644, 646, 'Two resistors of 5 Ω and 10 Ω are connected in parallel. Which value is their equivalent resistance?', 'mcq', 1, 'Calculate (5 × 10)/(5 + 10).', '{"why":"The equivalent resistance is less than 5 Ω, the smaller individual resistance.","sol":"Step 1: Rₜ = (5 × 10)/(5 + 10).\nStep 2: Rₜ = 50/15.\nStep 3: Rₜ ≈ 3.33 Ω.","steps":["Step 1: Rₜ = (5 × 10)/(5 + 10).","Step 2: Rₜ = 50/15.","Step 3: Rₜ ≈ 3.33 Ω."],"options":[{"text":"3.33 Ω approximately","is_correct":false},{"text":"5 Ω","is_correct":false},{"text":"7.5 Ω","is_correct":false},{"text":"15 Ω","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_em_equivalent_resistance_in_a_parallel_circuit","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Equivalent Resistance in a Parallel Circuit"}', 3),
  (2645, 647, 'A 12 V supply is connected across 6 Ω and 3 Ω resistors in parallel. What is the total current?', 'mcq', 1, 'Calculate both branch currents using I = V/R, then add them.', '{"why":"The total current equals the sum of the currents in the parallel branches.","sol":"Step 1: The voltage across each branch is 12 V.\nStep 2: Current in 6 Ω branch: I₁ = 12/6 = 2 A.\nStep 3: Current in 3 Ω branch: I₂ = 12/3 = 4 A.\nStep 4: Total current: Iₜ = 2 + 4 = 6 A.","steps":["Step 1: The voltage across each branch is 12 V.","Step 2: Current in 6 Ω branch: I₁ = 12/6 = 2 A.","Step 3: Current in 3 Ω branch: I₂ = 12/3 = 4 A.","Step 4: Total current: Iₜ = 2 + 4 = 6 A."],"options":[{"text":"2 A","is_correct":false},{"text":"4 A","is_correct":false},{"text":"6 A","is_correct":false},{"text":"9 A","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_em_solving_parallel_circuit_problems","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Solving Parallel Circuit Problems"}', 0),
  (2646, 647, 'A 10 V supply is connected across 5 Ω and 10 Ω resistors in parallel. What is the equivalent resistance?', 'mcq', 1, 'Find both branch currents, add them, then use Rₜ = V/Iₜ.', '{"why":"The equivalent resistance is the supply voltage divided by the total current.","sol":"Step 1: I₁ = 10/5 = 2 A.\nStep 2: I₂ = 10/10 = 1 A.\nStep 3: Iₜ = 2 + 1 = 3 A.\nStep 4: Rₜ = 10/3 ≈ 3.33 Ω.","steps":["Step 1: I₁ = 10/5 = 2 A.","Step 2: I₂ = 10/10 = 1 A.","Step 3: Iₜ = 2 + 1 = 3 A.","Step 4: Rₜ = 10/3 ≈ 3.33 Ω."],"options":[{"text":"3.33 Ω approximately","is_correct":false},{"text":"5 Ω","is_correct":false},{"text":"7.5 Ω","is_correct":false},{"text":"15 Ω","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_em_solving_parallel_circuit_problems","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Solving Parallel Circuit Problems"}', 1),
  (2647, 647, 'A 12 V supply feeds two parallel branches. The total current is 5 A, and one branch has a resistance of 4 Ω. Find the resistance of the other branch.', 'mcq', 1, 'Find the known branch current, subtract it from the total, then use R = V/I.', '{"why":"The unknown branch carries 2 A, and its voltage is 12 V, giving a resistance of 6 Ω.","sol":"Step 1: Known branch current: I₁ = 12/4 = 3 A.\nStep 2: Unknown branch current: I₂ = 5 − 3 = 2 A.\nStep 3: Unknown resistance: R₂ = 12/2 = 6 Ω.","steps":["Step 1: Known branch current: I₁ = 12/4 = 3 A.","Step 2: Unknown branch current: I₂ = 5 − 3 = 2 A.","Step 3: Unknown resistance: R₂ = 12/2 = 6 Ω."],"options":[{"text":"3 Ω","is_correct":false},{"text":"4 Ω","is_correct":false},{"text":"6 Ω","is_correct":false},{"text":"12 Ω","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_em_solving_parallel_circuit_problems","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Solving Parallel Circuit Problems"}', 2),
  (2648, 647, 'A 6 V supply is connected across 2 Ω and 6 Ω resistors in parallel. What are the total current and the current through the 6 Ω resistor?', 'mcq', 1, 'Calculate I = V/R for each branch and add the results.', '{"why":"The 6 Ω branch carries 1 A, and the two branch currents add to 4 A.","sol":"Step 1: Current through 2 Ω: I₁ = 6/2 = 3 A.\nStep 2: Current through 6 Ω: I₂ = 6/6 = 1 A.\nStep 3: Total current: Iₜ = 3 + 1 = 4 A.","steps":["Step 1: Current through 2 Ω: I₁ = 6/2 = 3 A.","Step 2: Current through 6 Ω: I₂ = 6/6 = 1 A.","Step 3: Total current: Iₜ = 3 + 1 = 4 A."],"options":[{"text":"Total 4 A; branch current 1 A","is_correct":false},{"text":"Total 3 A; branch current 2 A","is_correct":false},{"text":"Total 1 A; branch current 4 A","is_correct":false},{"text":"Total 6 A; branch current 3 A","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_em_solving_parallel_circuit_problems","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Solving Parallel Circuit Problems"}', 3),
  (2649, 648, 'In which direction do magnetic field lines run outside a bar magnet?', 'mcq', 1, 'Use the conventional direction outside a magnet.', '{"why":"The conventional direction of magnetic field lines outside a bar magnet is north to south.","sol":"Step 1: Identify the north and south poles.\nStep 2: Outside the magnet, field lines leave the north pole.\nStep 3: They enter the south pole.","steps":["Step 1: Identify the north and south poles.","Step 2: Outside the magnet, field lines leave the north pole.","Step 3: They enter the south pole."],"options":[{"text":"South pole to north pole","is_correct":false},{"text":"North pole to south pole","is_correct":false},{"text":"East pole to west pole","is_correct":false},{"text":"In no definite direction","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_magnetic_field_patterns","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Magnetic Field Patterns"}', 0),
  (2650, 648, 'Two regions of a magnetic field are shown. Region A has closely spaced field lines, while Region B has widely spaced lines. Which region has the stronger field?', 'mcq', 1, 'Look at the spacing between the lines.', '{"why":"The relative density of magnetic field lines represents the relative strength of the field.","sol":"Step 1: Closely spaced field lines represent a stronger field.\nStep 2: Region A has closer lines than Region B.\nStep 3: Therefore, Region A has the stronger field.","steps":["Step 1: Closely spaced field lines represent a stronger field.","Step 2: Region A has closer lines than Region B.","Step 3: Therefore, Region A has the stronger field."],"options":[{"text":"Region A","is_correct":false},{"text":"Region B","is_correct":false},{"text":"Both must be zero","is_correct":false},{"text":"The spacing gives no information","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_em_magnetic_field_patterns","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Magnetic Field Patterns"}', 1),
  (2651, 648, 'Why do magnetic field lines never cross?', 'mcq', 1, 'Consider what two crossing arrows would mean at one point.', '{"why":"Crossing field lines would contradict the definition of a unique field direction at a point.","sol":"Step 1: A field line shows the field direction.\nStep 2: Crossing lines would imply two directions at one point.\nStep 3: The field has one direction at that point, so lines cannot cross.","steps":["Step 1: A field line shows the field direction.","Step 2: Crossing lines would imply two directions at one point.","Step 3: The field has one direction at that point, so lines cannot cross."],"options":[{"text":"Magnets cannot attract each other","is_correct":false},{"text":"A magnetic field has only one direction at a given point","is_correct":false},{"text":"Magnetic fields exist only inside magnets","is_correct":false},{"text":"Field lines must always be straight","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_magnetic_field_patterns","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Magnetic Field Patterns"}', 2),
  (2652, 648, 'A small compass is placed in a magnetic field. What does the north-seeking end of its needle indicate?', 'mcq', 1, 'A compass is used to show magnetic direction.', '{"why":"A compass needle aligns with the magnetic field at its location.","sol":"Step 1: The compass needle aligns with the local magnetic field.\nStep 2: Its north-seeking end points along the field direction.\nStep 3: Therefore, it indicates the magnetic field''s direction.","steps":["Step 1: The compass needle aligns with the local magnetic field.","Step 2: Its north-seeking end points along the field direction.","Step 3: Therefore, it indicates the magnetic field''s direction."],"options":[{"text":"The direction of the magnetic field","is_correct":false},{"text":"The mass of the magnet","is_correct":false},{"text":"The electrical resistance of the magnet","is_correct":false},{"text":"The temperature of the surroundings","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_em_magnetic_field_patterns","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Magnetic Field Patterns"}', 3),
  (2653, 649, 'What is the shape of the magnetic field around a long, straight current-carrying wire?', 'mcq', 1, 'Imagine looking at the wire end-on.', '{"why":"The magnetic field around a straight current-carrying conductor forms circular paths centred on the wire.","sol":"Step 1: A current-carrying wire creates a magnetic field.\nStep 2: For a straight wire, the field surrounds it.\nStep 3: The field lines form concentric circles.","steps":["Step 1: A current-carrying wire creates a magnetic field.","Step 2: For a straight wire, the field surrounds it.","Step 3: The field lines form concentric circles."],"options":[{"text":"Straight parallel lines only","is_correct":false},{"text":"Concentric circles around the wire","is_correct":false},{"text":"A single line along the wire","is_correct":false},{"text":"Random curves with no pattern","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_magnetic_field_around_a_current_carrying_wire","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Magnetic Field Around a Current-Carrying Wire"}', 0),
  (2654, 649, 'What happens to the magnetic field strength near a straight wire when its current increases, with distance unchanged?', 'mcq', 1, 'The magnetic effect depends on the current.', '{"why":"For a straight wire, magnetic field strength increases with current when distance is fixed.","sol":"Step 1: The current produces the magnetic field.\nStep 2: Increasing current increases the field strength at the same distance.\nStep 3: Therefore, the field becomes stronger.","steps":["Step 1: The current produces the magnetic field.","Step 2: Increasing current increases the field strength at the same distance.","Step 3: Therefore, the field becomes stronger."],"options":[{"text":"It becomes stronger","is_correct":false},{"text":"It becomes weaker","is_correct":false},{"text":"It always becomes zero","is_correct":false},{"text":"Its direction must reverse","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_em_magnetic_field_around_a_current_carrying_wire","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Magnetic Field Around a Current-Carrying Wire"}', 1),
  (2655, 649, 'The current through a straight wire is reversed. What happens to the direction of the magnetic field?', 'mcq', 1, 'Apply the right-hand grip rule in both current directions.', '{"why":"The direction of the magnetic field around a wire depends on the direction of conventional current.","sol":"Step 1: The field direction depends on current direction.\nStep 2: Reversing the current reverses the direction of the curled fingers.\nStep 3: Therefore, the magnetic field direction reverses.","steps":["Step 1: The field direction depends on current direction.","Step 2: Reversing the current reverses the direction of the curled fingers.","Step 3: Therefore, the magnetic field direction reverses."],"options":[{"text":"It remains unchanged","is_correct":false},{"text":"It reverses","is_correct":false},{"text":"It becomes an electric field only","is_correct":false},{"text":"It permanently disappears","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_magnetic_field_around_a_current_carrying_wire","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Magnetic Field Around a Current-Carrying Wire"}', 2),
  (2656, 649, 'Which rule can be used to determine the direction of the magnetic field around a straight current-carrying wire?', 'mcq', 1, 'Use the hand rule for a current-carrying conductor.', '{"why":"The right-hand grip rule connects current direction with the direction of the magnetic field around the wire.","sol":"Step 1: Point the right thumb in the conventional current direction.\nStep 2: Curl the fingers around the wire.\nStep 3: The curled fingers indicate the field direction.","steps":["Step 1: Point the right thumb in the conventional current direction.","Step 2: Curl the fingers around the wire.","Step 3: The curled fingers indicate the field direction."],"options":[{"text":"The right-hand grip rule","is_correct":false},{"text":"The law of conservation of mass","is_correct":false},{"text":"The principle of moments","is_correct":false},{"text":"The law of reflection","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_em_magnetic_field_around_a_current_carrying_wire","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Magnetic Field Around a Current-Carrying Wire"}', 3),
  (2657, 650, 'What is a solenoid?', 'mcq', 1, 'Think of a wire wound into repeated loops.', '{"why":"A solenoid is a coil of wire that produces a magnetic field when current flows through it.","sol":"Step 1: A solenoid consists of many turns of wire.\nStep 2: The turns form a coil.\nStep 3: Therefore, it is a coil of wire with many turns.","steps":["Step 1: A solenoid consists of many turns of wire.","Step 2: The turns form a coil.","Step 3: Therefore, it is a coil of wire with many turns."],"options":[{"text":"A single straight wire with no current","is_correct":false},{"text":"A coil of wire with many turns","is_correct":false},{"text":"A device that measures mass","is_correct":false},{"text":"A non-magnetic insulating sheet","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_magnetic_field_of_a_solenoid","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Magnetic Field of a Solenoid"}', 0),
  (2658, 650, 'What is the magnetic field like inside a sufficiently long solenoid carrying steady current?', 'mcq', 1, 'Think about the spacing and direction of field lines inside the coil.', '{"why":"The field inside a long solenoid is approximately uniform, away from its ends.","sol":"Step 1: The fields from the turns combine inside the coil.\nStep 2: Inside a sufficiently long solenoid, the field lines are nearly parallel and evenly spaced.\nStep 3: Therefore, the field is approximately uniform.","steps":["Step 1: The fields from the turns combine inside the coil.","Step 2: Inside a sufficiently long solenoid, the field lines are nearly parallel and evenly spaced.","Step 3: Therefore, the field is approximately uniform."],"options":[{"text":"Approximately uniform","is_correct":false},{"text":"Always zero","is_correct":false},{"text":"Randomly directed at every point","is_correct":false},{"text":"Made only of circular lines around each turn","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_em_magnetic_field_of_a_solenoid","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Magnetic Field of a Solenoid"}', 1),
  (2659, 650, 'What happens to the north and south poles of a solenoid when its current is reversed?', 'mcq', 1, 'Reversing the current reverses the magnetic field direction.', '{"why":"The polarity of a current-carrying solenoid depends on the direction of current through its turns.","sol":"Step 1: The solenoid''s poles depend on current direction.\nStep 2: Reversing current reverses the field direction.\nStep 3: The north and south poles exchange positions.","steps":["Step 1: The solenoid''s poles depend on current direction.","Step 2: Reversing current reverses the field direction.","Step 3: The north and south poles exchange positions."],"options":[{"text":"Both poles disappear permanently","is_correct":false},{"text":"The poles exchange positions","is_correct":false},{"text":"The poles stay in the same positions","is_correct":false},{"text":"The coil becomes a resistor only","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_magnetic_field_of_a_solenoid","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Magnetic Field of a Solenoid"}', 2),
  (2660, 650, 'Which feature makes an electromagnet based on a solenoid different from a permanent bar magnet?', 'mcq', 1, 'Consider what produces the solenoid''s magnetic field.', '{"why":"An electromagnet''s field depends on electric current, unlike the field of an ordinary permanent magnet.","sol":"Step 1: Current through the solenoid produces its field.\nStep 2: Stopping the current removes the current-produced field, apart from any residual magnetism in a core.\nStep 3: Therefore, it can be switched off.","steps":["Step 1: Current through the solenoid produces its field.","Step 2: Stopping the current removes the current-produced field, apart from any residual magnetism in a core.","Step 3: Therefore, it can be switched off."],"options":[{"text":"It can be switched off by stopping the current","is_correct":false},{"text":"It can never attract iron","is_correct":false},{"text":"It has no magnetic field when current flows","is_correct":false},{"text":"It has no north or south pole","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_em_magnetic_field_of_a_solenoid","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Magnetic Field of a Solenoid"}', 3),
  (2661, 651, 'Two identical electromagnets differ only in current. Electromagnet A carries 1 A and B carries 2 A. Which is generally stronger?', 'mcq', 1, 'Keep the coil and core unchanged and compare the currents.', '{"why":"With other factors unchanged, increasing current strengthens an electromagnet.","sol":"Step 1: Both electromagnets have the same coil and core.\nStep 2: Electromagnet B carries the larger current.\nStep 3: The larger current generally produces a stronger field.","steps":["Step 1: Both electromagnets have the same coil and core.","Step 2: Electromagnet B carries the larger current.","Step 3: The larger current generally produces a stronger field."],"options":[{"text":"A, because its current is smaller","is_correct":false},{"text":"B, because its current is larger","is_correct":false},{"text":"They must both have zero field","is_correct":false},{"text":"Current has no effect on field strength","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_factors_affecting_electromagnet_strength","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Factors Affecting Electromagnet Strength"}', 0),
  (2662, 651, 'Two coils have the same current and core. Coil A has 50 turns and Coil B has 150 turns over a similar length. Which is generally stronger?', 'mcq', 1, 'Compare the number of turns per unit length.', '{"why":"Increasing the number of turns, with other conditions unchanged, increases the solenoid''s field strength.","sol":"Step 1: Coil B has more turns over a similar length.\nStep 2: More turns per unit length generally strengthen the field.\nStep 3: Therefore, Coil B is generally stronger.","steps":["Step 1: Coil B has more turns over a similar length.","Step 2: More turns per unit length generally strengthen the field.","Step 3: Therefore, Coil B is generally stronger."],"options":[{"text":"Coil A","is_correct":false},{"text":"Coil B","is_correct":false},{"text":"Neither can produce a magnetic field","is_correct":false},{"text":"Both must have identical strength","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_factors_affecting_electromagnet_strength","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Factors Affecting Electromagnet Strength"}', 1),
  (2663, 651, 'Which core is commonly used to strengthen an electromagnet?', 'mcq', 1, 'Choose a material that is easily magnetised.', '{"why":"Soft iron is commonly used because it strengthens the field and can be magnetised and demagnetised readily.","sol":"Step 1: An electromagnet benefits from a magnetic core.\nStep 2: Soft iron is readily magnetised and strengthens the field.\nStep 3: Therefore, soft iron is the suitable choice.","steps":["Step 1: An electromagnet benefits from a magnetic core.","Step 2: Soft iron is readily magnetised and strengthens the field.","Step 3: Therefore, soft iron is the suitable choice."],"options":[{"text":"Wood","is_correct":false},{"text":"Soft iron","is_correct":false},{"text":"Dry paper","is_correct":false},{"text":"Plastic","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_factors_affecting_electromagnet_strength","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Factors Affecting Electromagnet Strength"}', 2),
  (2664, 651, 'A student wants to test how the number of coil turns affects electromagnet strength. Which method is fairest?', 'mcq', 1, 'A fair test changes one independent variable at a time.', '{"why":"Controlling other variables makes it possible to attribute changes in strength to the number of turns.","sol":"Step 1: The factor being investigated is the number of turns.\nStep 2: Other relevant factors should be kept constant.\nStep 3: Keep current and core the same while changing the turns.","steps":["Step 1: The factor being investigated is the number of turns.","Step 2: Other relevant factors should be kept constant.","Step 3: Keep current and core the same while changing the turns."],"options":[{"text":"Change the number of turns and current at the same time","is_correct":false},{"text":"Change the core, current and turns together","is_correct":false},{"text":"Change only the number of turns while keeping the current and core the same","is_correct":false},{"text":"Use a different battery for every trial without measuring current","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_em_factors_affecting_electromagnet_strength","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Factors Affecting Electromagnet Strength"}', 3),
  (2665, 652, 'Why can an electromagnetic crane release a load after lifting it?', 'mcq', 1, 'Think about what produces the electromagnet''s field.', '{"why":"An electromagnet''s magnetic attraction can be controlled by switching its current off.","sol":"Step 1: Current through the coil produces the magnetic field.\nStep 2: The field attracts the metal load.\nStep 3: Switching off the current reduces the field, allowing the load to be released.","steps":["Step 1: Current through the coil produces the magnetic field.","Step 2: The field attracts the metal load.","Step 3: Switching off the current reduces the field, allowing the load to be released."],"options":[{"text":"It changes the steel into plastic","is_correct":false},{"text":"Switching off the current reduces the magnetic field","is_correct":false},{"text":"The steel loses all its mass","is_correct":false},{"text":"The crane reverses gravity","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_applications_of_electromagnets","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Applications of Electromagnets"}', 0),
  (2666, 652, 'What is the main function of the electromagnet in a relay?', 'mcq', 1, 'A relay uses magnetism to control electrical contacts.', '{"why":"A relay uses an electromagnet to control switching in an electrical circuit.","sol":"Step 1: Current flows through the relay coil.\nStep 2: The coil becomes an electromagnet.\nStep 3: It moves an armature that opens or closes contacts.","steps":["Step 1: Current flows through the relay coil.","Step 2: The coil becomes an electromagnet.","Step 3: It moves an armature that opens or closes contacts."],"options":[{"text":"To measure the mass of a conductor","is_correct":false},{"text":"To generate sound without moving parts","is_correct":false},{"text":"To move a switch mechanism using a magnetic force","is_correct":false},{"text":"To make electrical resistance permanently zero","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_em_applications_of_electromagnets","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Applications of Electromagnets"}', 1),
  (2667, 652, 'What causes the hammer in a typical electric bell to strike repeatedly?', 'mcq', 1, 'Trace what happens when the armature moves and the circuit is interrupted.', '{"why":"The repeated energising and releasing of the electromagnet makes the hammer vibrate and strike the bell.","sol":"Step 1: Current energises the electromagnet.\nStep 2: The armature moves and interrupts the current.\nStep 3: The magnet releases the armature, the circuit reconnects, and the cycle repeats.","steps":["Step 1: Current energises the electromagnet.","Step 2: The armature moves and interrupts the current.","Step 3: The magnet releases the armature, the circuit reconnects, and the cycle repeats."],"options":[{"text":"A permanent current-free magnetic field","is_correct":false},{"text":"A repeated make-and-break action in the electromagnet circuit","is_correct":false},{"text":"The complete absence of an armature","is_correct":false},{"text":"The battery changing into a permanent magnet","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_em_applications_of_electromagnets","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Applications of Electromagnets"}', 2),
  (2668, 652, 'Which is a major advantage of an electromagnet over a typical permanent magnet?', 'mcq', 1, 'Consider what happens when current is switched on or off.', '{"why":"Electromagnets are useful in devices that require controllable magnetic attraction.","sol":"Step 1: An electromagnet''s field is produced by current.\nStep 2: Changing or stopping the current changes the magnetic effect.\nStep 3: Therefore, the field can be controlled electrically.","steps":["Step 1: An electromagnet''s field is produced by current.","Step 2: Changing or stopping the current changes the magnetic effect.","Step 3: Therefore, the field can be controlled electrically."],"options":[{"text":"Its magnetic effect can be controlled by switching current","is_correct":false},{"text":"It always attracts every material","is_correct":false},{"text":"It does not need a magnetic field","is_correct":false},{"text":"Its strength can never change","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_em_applications_of_electromagnets","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Applications of Electromagnets"}', 3),
  (2669, 653, 'A block has a mass of 450 g and a volume of 150 cm³. Calculate its density.', 'mcq', 1, 'Density = mass ÷ volume.', '{"why":"Density is the mass divided by the volume occupied.","sol":"Step 1: Write ρ = m/V.\nStep 2: Substitute: ρ = 450/150.\nStep 3: Calculate: ρ = 3 g/cm³.","steps":["Step 1: Write ρ = m/V.","Step 2: Substitute: ρ = 450/150.","Step 3: Calculate: ρ = 3 g/cm³."],"options":[{"text":"2 g/cm³","is_correct":false},{"text":"3 g/cm³","is_correct":false},{"text":"300 g/cm³","is_correct":false},{"text":"600 g/cm³","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_fluids_density","skillId":"physics_fluids","subskillId":"physics_fluids_q1","subject":"physics","chapter":"fluids","topic":"Density"}', 0),
  (2670, 653, 'A liquid has a density of 900 kg/m³ and a volume of 2 m³. Find its mass.', 'mcq', 1, 'Mass = density × volume.', '{"why":"Multiplying density by volume gives mass.","sol":"Step 1: Use m = ρV.\nStep 2: Substitute: m = 900 × 2.\nStep 3: Calculate: m = 1800 kg.","steps":["Step 1: Use m = ρV.","Step 2: Substitute: m = 900 × 2.","Step 3: Calculate: m = 1800 kg."],"options":[{"text":"450 kg","is_correct":false},{"text":"900 kg","is_correct":false},{"text":"1800 kg","is_correct":false},{"text":"2000 kg","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_fluids_density","skillId":"physics_fluids","subskillId":"physics_fluids_q2","subject":"physics","chapter":"fluids","topic":"Density"}', 1),
  (2671, 653, 'An object has a mass of 3 kg and a density of 750 kg/m³. What is its volume?', 'mcq', 1, 'Volume = mass ÷ density.', '{"why":"Dividing mass by density gives the volume.","sol":"Step 1: Use V = m/ρ.\nStep 2: Substitute: V = 3/750.\nStep 3: Calculate: V = 0.004 m³.","steps":["Step 1: Use V = m/ρ.","Step 2: Substitute: V = 3/750.","Step 3: Calculate: V = 0.004 m³."],"options":[{"text":"0.004 m³","is_correct":false},{"text":"0.25 m³","is_correct":false},{"text":"250 m³","is_correct":false},{"text":"2250 m³","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_fluids_density","skillId":"physics_fluids","subskillId":"physics_fluids_q3","subject":"physics","chapter":"fluids","topic":"Density"}', 2),
  (2672, 653, 'A substance has a density of 2.5 g/cm³. Express this density in kg/m³.', 'mcq', 1, 'Multiply the value in g/cm³ by 1000.', '{"why":"The conversion factor from g/cm³ to kg/m³ is 1000.","sol":"Step 1: Use 1 g/cm³ = 1000 kg/m³.\nStep 2: Convert: 2.5 × 1000.\nStep 3: Density = 2500 kg/m³.","steps":["Step 1: Use 1 g/cm³ = 1000 kg/m³.","Step 2: Convert: 2.5 × 1000.","Step 3: Density = 2500 kg/m³."],"options":[{"text":"25 kg/m³","is_correct":false},{"text":"250 kg/m³","is_correct":false},{"text":"2500 kg/m³","is_correct":false},{"text":"25,000 kg/m³","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_fluids_density","skillId":"physics_fluids","subskillId":"physics_fluids_q4","subject":"physics","chapter":"fluids","topic":"Density"}', 3),
  (2673, 654, 'A force of 500 N acts normally on an area of 2 m². Find the pressure.', 'mcq', 1, 'Pressure = force ÷ area.', '{"why":"Pressure is force per unit area.","sol":"Step 1: Use P = F/A.\nStep 2: Substitute: P = 500/2.\nStep 3: Calculate: P = 250 Pa.","steps":["Step 1: Use P = F/A.","Step 2: Substitute: P = 500/2.","Step 3: Calculate: P = 250 Pa."],"options":[{"text":"100 Pa","is_correct":false},{"text":"250 Pa","is_correct":false},{"text":"500 Pa","is_correct":false},{"text":"1000 Pa","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_fluids_pressure","skillId":"physics_fluids","subskillId":"physics_fluids_q1","subject":"physics","chapter":"fluids","topic":"Pressure"}', 0),
  (2674, 654, 'A pressure of 4000 Pa acts over an area of 0.5 m². Calculate the force.', 'mcq', 1, 'Force = pressure × area.', '{"why":"Multiplying pressure by area gives the normal force.","sol":"Step 1: Use F = PA.\nStep 2: Substitute: F = 4000 × 0.5.\nStep 3: Calculate: F = 2000 N.","steps":["Step 1: Use F = PA.","Step 2: Substitute: F = 4000 × 0.5.","Step 3: Calculate: F = 2000 N."],"options":[{"text":"2000 N","is_correct":false},{"text":"8000 N","is_correct":false},{"text":"4000 N","is_correct":false},{"text":"200 N","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_fluids_pressure","skillId":"physics_fluids","subskillId":"physics_fluids_q2","subject":"physics","chapter":"fluids","topic":"Pressure"}', 1),
  (2675, 654, 'A force of 90 N produces a pressure of 300 Pa. What area does the force act on?', 'mcq', 1, 'Area = force ÷ pressure.', '{"why":"Area is found by dividing force by pressure.","sol":"Step 1: Use A = F/P.\nStep 2: Substitute: A = 90/300.\nStep 3: Calculate: A = 0.3 m².","steps":["Step 1: Use A = F/P.","Step 2: Substitute: A = 90/300.","Step 3: Calculate: A = 0.3 m²."],"options":[{"text":"0.03 m²","is_correct":false},{"text":"0.3 m²","is_correct":false},{"text":"3.3 m²","is_correct":false},{"text":"27,000 m²","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_fluids_pressure","skillId":"physics_fluids","subskillId":"physics_fluids_q3","subject":"physics","chapter":"fluids","topic":"Pressure"}', 2),
  (2676, 654, 'A person stands on soft ground. If the person''s weight remains the same but the contact area of the shoes increases, what happens to the pressure on the ground?', 'mcq', 1, 'Use P = F/A and keep F constant.', '{"why":"For a fixed force, pressure is inversely proportional to the contact area.","sol":"Step 1: Pressure equals force divided by area.\nStep 2: The force remains the same.\nStep 3: Increasing the area decreases the pressure.","steps":["Step 1: Pressure equals force divided by area.","Step 2: The force remains the same.","Step 3: Increasing the area decreases the pressure."],"options":[{"text":"Pressure increases","is_correct":false},{"text":"Pressure decreases","is_correct":false},{"text":"Pressure remains infinite","is_correct":false},{"text":"Pressure must double","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_fluids_pressure","skillId":"physics_fluids","subskillId":"physics_fluids_q4","subject":"physics","chapter":"fluids","topic":"Pressure"}', 3),
  (2677, 655, 'Calculate the pressure due to water at a depth of 3 m. Take ρ = 1000 kg/m³ and g = 10 N/kg.', 'mcq', 1, 'Use p = ρgh.', '{"why":"Liquid pressure due to a uniform liquid column equals density multiplied by gravitational field strength and depth.","sol":"Step 1: Use p = ρgh.\nStep 2: Substitute: p = 1000 × 10 × 3.\nStep 3: Calculate: p = 30,000 Pa.","steps":["Step 1: Use p = ρgh.","Step 2: Substitute: p = 1000 × 10 × 3.","Step 3: Calculate: p = 30,000 Pa."],"options":[{"text":"3000 Pa","is_correct":false},{"text":"10,000 Pa","is_correct":false},{"text":"30,000 Pa","is_correct":false},{"text":"300,000 Pa","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_fluids_pressure_in_liquids","skillId":"physics_fluids","subskillId":"physics_fluids_q1","subject":"physics","chapter":"fluids","topic":"Pressure in Liquids"}', 0),
  (2678, 655, 'At a depth of 2 m, the pressure due to water is 20,000 Pa. What is the pressure due to the same water at 4 m depth, assuming the same gravitational field?', 'mcq', 1, 'Pressure is directly proportional to depth.', '{"why":"Liquid pressure increases in direct proportion to depth when density and gravity are unchanged.","sol":"Step 1: The depth doubles from 2 m to 4 m.\nStep 2: For the same liquid and gravity, pressure doubles.\nStep 3: p = 2 × 20,000 = 40,000 Pa.","steps":["Step 1: The depth doubles from 2 m to 4 m.","Step 2: For the same liquid and gravity, pressure doubles.","Step 3: p = 2 × 20,000 = 40,000 Pa."],"options":[{"text":"10,000 Pa","is_correct":false},{"text":"20,000 Pa","is_correct":false},{"text":"40,000 Pa","is_correct":false},{"text":"80,000 Pa","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_fluids_pressure_in_liquids","skillId":"physics_fluids","subskillId":"physics_fluids_q2","subject":"physics","chapter":"fluids","topic":"Pressure in Liquids"}', 1),
  (2679, 655, 'A liquid has density 800 kg/m³. Find the pressure due to the liquid at a depth of 2 m, taking g = 10 N/kg.', 'mcq', 1, 'Substitute the density, gravity and depth into p = ρgh.', '{"why":"The pressure due to the liquid is determined by its density, depth and gravitational field strength.","sol":"Step 1: Use p = ρgh.\nStep 2: Substitute: p = 800 × 10 × 2.\nStep 3: Calculate: p = 16,000 Pa.","steps":["Step 1: Use p = ρgh.","Step 2: Substitute: p = 800 × 10 × 2.","Step 3: Calculate: p = 16,000 Pa."],"options":[{"text":"1600 Pa","is_correct":false},{"text":"8000 Pa","is_correct":false},{"text":"16,000 Pa","is_correct":false},{"text":"32,000 Pa","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_fluids_pressure_in_liquids","skillId":"physics_fluids","subskillId":"physics_fluids_q3","subject":"physics","chapter":"fluids","topic":"Pressure in Liquids"}', 2),
  (2680, 655, 'At the same depth in the same stationary liquid, how does pressure compare at two points?', 'mcq', 1, 'Liquid pressure depends on depth, density and gravity.', '{"why":"In a stationary liquid, pressure at a given depth is independent of the container''s shape.","sol":"Step 1: The points are at the same depth.\nStep 2: They are in the same liquid and gravitational field.\nStep 3: Therefore, the pressure due to the liquid is the same.","steps":["Step 1: The points are at the same depth.","Step 2: They are in the same liquid and gravitational field.","Step 3: Therefore, the pressure due to the liquid is the same."],"options":[{"text":"It is greater at the point closer to the container wall","is_correct":false},{"text":"It is the same at both points","is_correct":false},{"text":"It depends only on the width of the container","is_correct":false},{"text":"It is always zero at the lower point","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_fluids_pressure_in_liquids","skillId":"physics_fluids","subskillId":"physics_fluids_q4","subject":"physics","chapter":"fluids","topic":"Pressure in Liquids"}', 3),
  (2681, 656, 'An object displaces 0.003 m³ of water. Calculate the upthrust, taking water density as 1000 kg/m³ and g = 10 N/kg.', 'mcq', 1, 'Use U = ρVg.', '{"why":"The upthrust equals the weight of the displaced water.","sol":"Step 1: Use U = ρVg.\nStep 2: Substitute: U = 1000 × 0.003 × 10.\nStep 3: Calculate: U = 30 N.","steps":["Step 1: Use U = ρVg.","Step 2: Substitute: U = 1000 × 0.003 × 10.","Step 3: Calculate: U = 30 N."],"options":[{"text":"3 N","is_correct":false},{"text":"30 N","is_correct":false},{"text":"300 N","is_correct":false},{"text":"3000 N","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_fluids_upthrust_and_flotation","skillId":"physics_fluids","subskillId":"physics_fluids_q1","subject":"physics","chapter":"fluids","topic":"Upthrust and Flotation"}', 0),
  (2682, 656, 'An object floats at rest and has a weight of 25 N. What is the upthrust acting on it?', 'mcq', 1, 'For a floating object at rest, upward and downward forces balance.', '{"why":"A floating object at rest is in vertical equilibrium.","sol":"Step 1: The object is stationary and floating.\nStep 2: Its resultant vertical force is zero.\nStep 3: Upthrust must equal weight: 25 N.","steps":["Step 1: The object is stationary and floating.","Step 2: Its resultant vertical force is zero.","Step 3: Upthrust must equal weight: 25 N."],"options":[{"text":"0 N","is_correct":false},{"text":"12.5 N","is_correct":false},{"text":"25 N","is_correct":false},{"text":"50 N","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_fluids_upthrust_and_flotation","skillId":"physics_fluids","subskillId":"physics_fluids_q2","subject":"physics","chapter":"fluids","topic":"Upthrust and Flotation"}', 1),
  (2683, 656, 'An immersed object displaces 0.001 m³ of a liquid with density 800 kg/m³. Calculate the upthrust using g = 10 N/kg.', 'mcq', 1, 'Multiply density, displaced volume and gravitational field strength.', '{"why":"Upthrust is the weight of the displaced liquid.","sol":"Step 1: Use U = ρVg.\nStep 2: Substitute: U = 800 × 0.001 × 10.\nStep 3: Calculate: U = 8 N.","steps":["Step 1: Use U = ρVg.","Step 2: Substitute: U = 800 × 0.001 × 10.","Step 3: Calculate: U = 8 N."],"options":[{"text":"0.8 N","is_correct":false},{"text":"8 N","is_correct":false},{"text":"80 N","is_correct":false},{"text":"8000 N","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_fluids_upthrust_and_flotation","skillId":"physics_fluids","subskillId":"physics_fluids_q3","subject":"physics","chapter":"fluids","topic":"Upthrust and Flotation"}', 2),
  (2684, 656, 'A fully immersed object has a weight of 12 N and an upthrust of 8 N. What happens if these forces remain unchanged?', 'mcq', 1, 'Compare the downward weight with the upward upthrust.', '{"why":"Since weight exceeds upthrust, the resultant force is downward.","sol":"Step 1: Weight acts downwards with 12 N.\nStep 2: Upthrust acts upwards with 8 N.\nStep 3: The resultant force is 12 − 8 = 4 N downwards.","steps":["Step 1: Weight acts downwards with 12 N.","Step 2: Upthrust acts upwards with 8 N.","Step 3: The resultant force is 12 − 8 = 4 N downwards."],"options":[{"text":"It accelerates upwards","is_correct":false},{"text":"It accelerates downwards","is_correct":false},{"text":"It remains in vertical equilibrium","is_correct":false},{"text":"Its weight becomes zero","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_fluids_upthrust_and_flotation","skillId":"physics_fluids","subskillId":"physics_fluids_q4","subject":"physics","chapter":"fluids","topic":"Upthrust and Flotation"}', 3),
  (2685, 657, 'Under the same conditions, honey flows more slowly than water. Which generally has the higher viscosity?', 'mcq', 1, 'The more resistant liquid has the higher viscosity.', '{"why":"Higher viscosity corresponds to greater resistance to flow.","sol":"Step 1: Honey flows less readily than water.\nStep 2: Viscosity measures resistance to flow.\nStep 3: Therefore, honey has the higher viscosity.","steps":["Step 1: Honey flows less readily than water.","Step 2: Viscosity measures resistance to flow.","Step 3: Therefore, honey has the higher viscosity."],"options":[{"text":"Water","is_correct":false},{"text":"Honey","is_correct":false},{"text":"Both must have zero viscosity","is_correct":false},{"text":"Viscosity cannot be compared","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_fluids_viscosity","skillId":"physics_fluids","subskillId":"physics_fluids_q1","subject":"physics","chapter":"fluids","topic":"Viscosity"}', 0),
  (2686, 657, 'Which liquid property makes a fluid flow less readily under comparable conditions?', 'mcq', 1, 'Look for the property that measures resistance to flow.', '{"why":"High viscosity means a fluid resists flow more strongly.","sol":"Step 1: Viscosity measures resistance to flow.\nStep 2: A higher viscosity means greater resistance.\nStep 3: Therefore, higher viscosity makes flow less readily.","steps":["Step 1: Viscosity measures resistance to flow.","Step 2: A higher viscosity means greater resistance.","Step 3: Therefore, higher viscosity makes flow less readily."],"options":[{"text":"Lower viscosity","is_correct":false},{"text":"Higher viscosity","is_correct":false},{"text":"Zero density","is_correct":false},{"text":"Greater transparency","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_fluids_viscosity","skillId":"physics_fluids","subskillId":"physics_fluids_q2","subject":"physics","chapter":"fluids","topic":"Viscosity"}', 1),
  (2687, 657, 'Two liquids are compared under the same conditions. Liquid A flows more readily than Liquid B. Which conclusion is most appropriate?', 'mcq', 1, 'The liquid that flows more readily has less resistance to flow.', '{"why":"Lower viscosity means less resistance to flow.","sol":"Step 1: Liquid A flows more readily.\nStep 2: It therefore offers less resistance to flow in this comparison.\nStep 3: Liquid A has lower viscosity.","steps":["Step 1: Liquid A flows more readily.","Step 2: It therefore offers less resistance to flow in this comparison.","Step 3: Liquid A has lower viscosity."],"options":[{"text":"Liquid A has higher viscosity","is_correct":false},{"text":"Liquid A has lower viscosity","is_correct":false},{"text":"Liquid B has no mass","is_correct":false},{"text":"Both liquids have equal viscosity","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_fluids_viscosity","skillId":"physics_fluids","subskillId":"physics_fluids_q3","subject":"physics","chapter":"fluids","topic":"Viscosity"}', 2),
  (2688, 657, 'Why should two liquids be compared at the same temperature when investigating their viscosities?', 'mcq', 1, 'Think about whether temperature can change how readily a liquid flows.', '{"why":"Controlling temperature helps ensure that observed differences are due to the fluids being compared rather than different test conditions.","sol":"Step 1: Viscosity can change with temperature.\nStep 2: Different temperatures could affect the flow comparison.\nStep 3: Keeping temperature the same makes the comparison fairer.","steps":["Step 1: Viscosity can change with temperature.","Step 2: Different temperatures could affect the flow comparison.","Step 3: Keeping temperature the same makes the comparison fairer."],"options":[{"text":"Temperature can affect viscosity","is_correct":false},{"text":"Temperature always makes all liquids identical","is_correct":false},{"text":"Viscosity depends only on the colour of a liquid","is_correct":false},{"text":"Temperature changes volume into mass","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_fluids_viscosity","skillId":"physics_fluids","subskillId":"physics_fluids_q4","subject":"physics","chapter":"fluids","topic":"Viscosity"}', 3),
  (2689, 658, 'An atom has atomic number 12 and mass number 24. How many neutrons does it contain?', 'mcq', 1, 'Subtract the atomic number from the mass number.', '{"why":"The mass number is the total of protons and neutrons, while the atomic number counts protons.","sol":"Step 1: Neutrons = mass number - atomic number.\nStep 2: Neutrons = 24 - 12.\nStep 3: The atom contains 12 neutrons.","steps":["Step 1: Neutrons = mass number - atomic number.","Step 2: Neutrons = 24 - 12.","Step 3: The atom contains 12 neutrons."],"options":[{"text":"12","is_correct":false},{"text":"24","is_correct":false},{"text":"36","is_correct":false},{"text":"6","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_modern_physics_structure_of_the_atom","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q1","subject":"physics","chapter":"modern_physics","topic":"Structure of the Atom"}', 0),
  (2690, 658, 'A neutral atom contains 17 protons. How many electrons does it contain?', 'mcq', 1, 'A neutral atom has equal numbers of protons and electrons.', '{"why":"Equal positive and negative charges make the atom electrically neutral.","sol":"Step 1: The atom is neutral.\nStep 2: Number of electrons = number of protons.\nStep 3: Electrons = 17.","steps":["Step 1: The atom is neutral.","Step 2: Number of electrons = number of protons.","Step 3: Electrons = 17."],"options":[{"text":"34","is_correct":false},{"text":"17","is_correct":false},{"text":"0","is_correct":false},{"text":"18","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_modern_physics_structure_of_the_atom","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q2","subject":"physics","chapter":"modern_physics","topic":"Structure of the Atom"}', 1),
  (2691, 658, 'What does the mass number of an atom represent?', 'mcq', 1, 'The mass number counts the particles in the nucleus that contribute nearly all the atom''s mass.', '{"why":"Electrons are not included in the mass number.","sol":"Step 1: The nucleus contains protons and neutrons.\nStep 2: Mass number = protons + neutrons.","steps":["Step 1: The nucleus contains protons and neutrons.","Step 2: Mass number = protons + neutrons."],"options":[{"text":"The number of electrons only","is_correct":false},{"text":"The number of neutrons only","is_correct":false},{"text":"The total number of protons and neutrons","is_correct":false},{"text":"The total number of protons and electrons","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_modern_physics_structure_of_the_atom","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q3","subject":"physics","chapter":"modern_physics","topic":"Structure of the Atom"}', 2),
  (2692, 658, 'An atom is represented by ³⁹₁₉K. How many neutrons does its nucleus contain?', 'mcq', 1, 'Use neutrons = A - Z.', '{"why":"The nucleus contains 19 protons and 20 neutrons, giving a mass number of 39.","sol":"Step 1: Mass number A = 39.\nStep 2: Atomic number Z = 19.\nStep 3: Neutrons = 39 - 19 = 20.","steps":["Step 1: Mass number A = 39.","Step 2: Atomic number Z = 19.","Step 3: Neutrons = 39 - 19 = 20."],"options":[{"text":"19","is_correct":false},{"text":"39","is_correct":false},{"text":"58","is_correct":false},{"text":"20","is_correct":false},{"text":"3","is_correct":true}],"conceptId":"physics_modern_physics_structure_of_the_atom","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q4","subject":"physics","chapter":"modern_physics","topic":"Structure of the Atom"}', 3),
  (2693, 659, 'What is radioactivity?', 'mcq', 1, 'Think about what happens inside an unstable nucleus.', '{"why":"Radioactivity originates from changes in unstable atomic nuclei.","sol":"Step 1: Radioactive nuclei are unstable.\nStep 2: They can emit radiation without an external trigger.\nStep 3: The process is spontaneous and random.","steps":["Step 1: Radioactive nuclei are unstable.","Step 2: They can emit radiation without an external trigger.","Step 3: The process is spontaneous and random."],"options":[{"text":"The movement of electrons through a wire","is_correct":false},{"text":"The spontaneous and random emission of radiation from an unstable nucleus","is_correct":false},{"text":"The heating of an atom until it melts","is_correct":false},{"text":"The joining of atoms in a chemical reaction","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_modern_physics_radioactivity_and_radioactive_decay","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q1","subject":"physics","chapter":"modern_physics","topic":"Radioactivity and Radioactive Decay"}', 0),
  (2694, 659, 'A radioactive source has an activity of 60 Bq. What does this indicate?', 'mcq', 1, 'One becquerel represents one nuclear decay per second.', '{"why":"Activity describes the rate of nuclear decay, not the total number of atoms.","sol":"Step 1: Activity is measured in becquerels.\nStep 2: 1 Bq = 1 decay per second.\nStep 3: 60 Bq corresponds to 60 decays per second on average.","steps":["Step 1: Activity is measured in becquerels.","Step 2: 1 Bq = 1 decay per second.","Step 3: 60 Bq corresponds to 60 decays per second on average."],"options":[{"text":"60 atoms are present in the source","is_correct":false},{"text":"60 particles are always inside the nucleus","is_correct":false},{"text":"An average of 60 nuclear decays occur per second","is_correct":false},{"text":"The source lasts for 60 seconds","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_modern_physics_radioactivity_and_radioactive_decay","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q2","subject":"physics","chapter":"modern_physics","topic":"Radioactivity and Radioactive Decay"}', 1),
  (2695, 659, 'A detector records 75 counts per minute. Background radiation contributes 15 counts per minute. What is the net count rate?', 'mcq', 1, 'Subtract the background reading from the total reading.', '{"why":"Subtracting background radiation gives the count rate attributable to the source.","sol":"Step 1: Total count rate = 75 counts/min.\nStep 2: Background count rate = 15 counts/min.\nStep 3: Net count rate = 75 - 15 = 60 counts/min.","steps":["Step 1: Total count rate = 75 counts/min.","Step 2: Background count rate = 15 counts/min.","Step 3: Net count rate = 75 - 15 = 60 counts/min."],"options":[{"text":"90 counts/min","is_correct":false},{"text":"60 counts/min","is_correct":false},{"text":"75 counts/min","is_correct":false},{"text":"5 counts/min","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_modern_physics_radioactivity_and_radioactive_decay","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q3","subject":"physics","chapter":"modern_physics","topic":"Radioactivity and Radioactive Decay"}', 2),
  (2696, 659, 'Which statement about radioactive decay is correct?', 'mcq', 1, 'Consider the meaning of random decay.', '{"why":"Randomness applies to individual nuclei even though large samples follow predictable statistical patterns.","sol":"Step 1: Radioactive decay is random.\nStep 2: Individual decay times cannot be predicted exactly.\nStep 3: The behaviour of a large sample can still be described statistically.","steps":["Step 1: Radioactive decay is random.","Step 2: Individual decay times cannot be predicted exactly.","Step 3: The behaviour of a large sample can still be described statistically."],"options":[{"text":"Every nucleus decays at a precisely predictable time","is_correct":false},{"text":"Radioactive decay always requires heating","is_correct":false},{"text":"Radioactive decay is a change in the electron arrangement only","is_correct":false},{"text":"The exact time at which one unstable nucleus decays cannot be predicted","is_correct":false},{"text":"3","is_correct":true}],"conceptId":"physics_modern_physics_radioactivity_and_radioactive_decay","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q4","subject":"physics","chapter":"modern_physics","topic":"Radioactivity and Radioactive Decay"}', 3),
  (2697, 660, 'Which radiation consists of two protons and two neutrons?', 'mcq', 1, 'It is identical to a helium nucleus.', '{"why":"An alpha particle is a helium nucleus with a charge of +2.","sol":"Step 1: An alpha particle contains two protons.\nStep 2: It also contains two neutrons.\nStep 3: Therefore, it is an alpha particle.","steps":["Step 1: An alpha particle contains two protons.","Step 2: It also contains two neutrons.","Step 3: Therefore, it is an alpha particle."],"options":[{"text":"Alpha","is_correct":false},{"text":"Beta-minus","is_correct":false},{"text":"Gamma","is_correct":false},{"text":"X-rays","is_correct":false},{"text":"0","is_correct":true}],"conceptId":"physics_modern_physics_alpha_beta_and_gamma_radiation","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q1","subject":"physics","chapter":"modern_physics","topic":"Alpha, Beta and Gamma Radiation"}', 0),
  (2698, 660, 'Which type of radiation has the greatest penetrating ability?', 'mcq', 1, 'Which radiation can pass through paper and aluminium and requires substantial shielding to reduce its intensity?', '{"why":"Gamma radiation has high penetrating ability and may require thick lead or concrete to reduce its intensity.","sol":"Step 1: Alpha is stopped by paper or the outer layer of skin.\nStep 2: Beta can be reduced by thin aluminium.\nStep 3: Gamma is the most penetrating of the three.","steps":["Step 1: Alpha is stopped by paper or the outer layer of skin.","Step 2: Beta can be reduced by thin aluminium.","Step 3: Gamma is the most penetrating of the three."],"options":[{"text":"Alpha","is_correct":false},{"text":"Beta","is_correct":false},{"text":"Gamma","is_correct":false},{"text":"All penetrate equally","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_modern_physics_alpha_beta_and_gamma_radiation","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q2","subject":"physics","chapter":"modern_physics","topic":"Alpha, Beta and Gamma Radiation"}', 1),
  (2699, 660, 'Which radiation has the greatest ionising ability?', 'mcq', 1, 'Strong ionisation is associated with alpha particles'' charge and interactions with matter.', '{"why":"Alpha radiation is highly ionising even though it is not very penetrating.","sol":"Step 1: Alpha particles carry a +2 charge.\nStep 2: They produce many ionisations over a short distance.\nStep 3: Alpha has the greatest ionising ability.","steps":["Step 1: Alpha particles carry a +2 charge.","Step 2: They produce many ionisations over a short distance.","Step 3: Alpha has the greatest ionising ability."],"options":[{"text":"Gamma","is_correct":false},{"text":"Beta","is_correct":false},{"text":"Alpha","is_correct":false},{"text":"All have zero ionising ability","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_modern_physics_alpha_beta_and_gamma_radiation","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q3","subject":"physics","chapter":"modern_physics","topic":"Alpha, Beta and Gamma Radiation"}', 2),
  (2700, 660, 'Which type of radiation has no electric charge and is not deflected by an electric field?', 'mcq', 1, 'Look for electromagnetic radiation rather than a charged particle.', '{"why":"Gamma radiation consists of photons, which have no electric charge.","sol":"Step 1: Alpha has a positive charge.\nStep 2: Beta-minus has a negative charge.\nStep 3: Gamma has no charge, so an electric field does not deflect it.","steps":["Step 1: Alpha has a positive charge.","Step 2: Beta-minus has a negative charge.","Step 3: Gamma has no charge, so an electric field does not deflect it."],"options":[{"text":"Alpha","is_correct":false},{"text":"Beta-minus","is_correct":false},{"text":"Both alpha and beta-minus","is_correct":false},{"text":"Gamma","is_correct":false},{"text":"3","is_correct":true}],"conceptId":"physics_modern_physics_alpha_beta_and_gamma_radiation","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q4","subject":"physics","chapter":"modern_physics","topic":"Alpha, Beta and Gamma Radiation"}', 3),
  (2701, 661, 'A sample contains 120 g of a radioactive isotope. Its half-life is 4 hours. How much remains after 8 hours?', 'mcq', 1, 'Eight hours is two half-lives.', '{"why":"The sample halves once during each 4-hour interval.","sol":"Step 1: Number of half-lives = 8 ÷ 4 = 2.\nStep 2: After 4 hours: 120 ÷ 2 = 60 g.\nStep 3: After 8 hours: 60 ÷ 2 = 30 g.","steps":["Step 1: Number of half-lives = 8 ÷ 4 = 2.","Step 2: After 4 hours: 120 ÷ 2 = 60 g.","Step 3: After 8 hours: 60 ÷ 2 = 30 g."],"options":[{"text":"60 g","is_correct":false},{"text":"30 g","is_correct":false},{"text":"15 g","is_correct":false},{"text":"0 g","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_modern_physics_half_life","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q1","subject":"physics","chapter":"modern_physics","topic":"Half-Life"}', 0),
  (2702, 661, 'A source''s activity decreases from 800 Bq to 100 Bq. How many half-lives have elapsed?', 'mcq', 1, 'Keep halving 800 until you reach 100.', '{"why":"Three successive halvings reduce the activity from 800 Bq to 100 Bq.","sol":"Step 1: 800 → 400 is one half-life.\nStep 2: 400 → 200 is two half-lives.\nStep 3: 200 → 100 is three half-lives.","steps":["Step 1: 800 → 400 is one half-life.","Step 2: 400 → 200 is two half-lives.","Step 3: 200 → 100 is three half-lives."],"options":[{"text":"2","is_correct":false},{"text":"3","is_correct":false},{"text":"4","is_correct":false},{"text":"8","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_modern_physics_half_life","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q2","subject":"physics","chapter":"modern_physics","topic":"Half-Life"}', 1),
  (2703, 661, 'A sample has a half-life of 6 days. How long does it take for its activity to fall from 400 Bq to 50 Bq?', 'mcq', 1, 'Count the halvings, then multiply by 6 days.', '{"why":"Three half-lives are needed to reduce the activity to one-eighth of its initial value.","sol":"Step 1: 400 → 200 after one half-life.\nStep 2: 200 → 100 after two half-lives.\nStep 3: 100 → 50 after three half-lives.\nStep 4: Elapsed time = 3 × 6 = 18 days.","steps":["Step 1: 400 → 200 after one half-life.","Step 2: 200 → 100 after two half-lives.","Step 3: 100 → 50 after three half-lives.","Step 4: Elapsed time = 3 × 6 = 18 days."],"options":[{"text":"6 days","is_correct":false},{"text":"12 days","is_correct":false},{"text":"18 days","is_correct":false},{"text":"24 days","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_modern_physics_half_life","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q3","subject":"physics","chapter":"modern_physics","topic":"Half-Life"}', 2),
  (2704, 661, 'A radioactive sample has a half-life of 10 minutes. What fraction remains after 30 minutes?', 'mcq', 1, 'Thirty minutes contains three half-lives.', '{"why":"Each half-life halves the remaining fraction.","sol":"Step 1: Number of half-lives = 30 ÷ 10 = 3.\nStep 2: After one half-life, 1/2 remains.\nStep 3: After two, 1/4 remains.\nStep 4: After three, 1/8 remains.","steps":["Step 1: Number of half-lives = 30 ÷ 10 = 3.","Step 2: After one half-life, 1/2 remains.","Step 3: After two, 1/4 remains.","Step 4: After three, 1/8 remains."],"options":[{"text":"1/2","is_correct":false},{"text":"1/4","is_correct":false},{"text":"1/8","is_correct":false},{"text":"1/16","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_modern_physics_half_life","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q4","subject":"physics","chapter":"modern_physics","topic":"Half-Life"}', 3),
  (2705, 662, 'Which application uses radiation to help treat cancer?', 'mcq', 1, 'Look for a medical treatment that uses carefully controlled radiation.', '{"why":"Radiotherapy is an important medical application of ionising radiation.","sol":"Step 1: Radiotherapy uses radiation in cancer treatment.\nStep 2: The treatment is planned to target cancer cells while limiting harm to healthy tissue.","steps":["Step 1: Radiotherapy uses radiation in cancer treatment.","Step 2: The treatment is planned to target cancer cells while limiting harm to healthy tissue."],"options":[{"text":"Measuring the speed of sound","is_correct":false},{"text":"Radiotherapy","is_correct":false},{"text":"Measuring electrical resistance","is_correct":false},{"text":"Determining the density of ordinary water","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_modern_physics_uses_and_safety_of_radioactivity","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q1","subject":"physics","chapter":"modern_physics","topic":"Uses and Safety of Radioactivity"}', 0),
  (2706, 662, 'Radioactive material is accidentally spilled onto a laboratory bench. What is this called?', 'mcq', 1, 'The radioactive substance itself has been transferred to the bench.', '{"why":"Contamination involves radioactive substances getting onto or into an object or person.","sol":"Step 1: Radioactive material is present on the bench.\nStep 2: Unwanted radioactive material on a surface is contamination.","steps":["Step 1: Radioactive material is present on the bench.","Step 2: Unwanted radioactive material on a surface is contamination."],"options":[{"text":"Irradiation only","is_correct":false},{"text":"Neutralisation","is_correct":false},{"text":"Contamination","is_correct":false},{"text":"Half-life","is_correct":false},{"text":"2","is_correct":true}],"conceptId":"physics_modern_physics_uses_and_safety_of_radioactivity","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q2","subject":"physics","chapter":"modern_physics","topic":"Uses and Safety of Radioactivity"}', 1),
  (2707, 662, 'Which action generally helps reduce radiation exposure?', 'mcq', 1, 'Consider how distance affects exposure.', '{"why":"Time, distance and suitable shielding are basic principles of radiation protection.","sol":"Step 1: Increasing distance generally reduces exposure from a point source.\nStep 2: Reducing time and using appropriate shielding also help.","steps":["Step 1: Increasing distance generally reduces exposure from a point source.","Step 2: Reducing time and using appropriate shielding also help."],"options":[{"text":"Spend longer beside the source","is_correct":false},{"text":"Move closer to the source","is_correct":false},{"text":"Remove all shielding","is_correct":false},{"text":"Increase distance from the source where practical","is_correct":false},{"text":"3","is_correct":true}],"conceptId":"physics_modern_physics_uses_and_safety_of_radioactivity","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q3","subject":"physics","chapter":"modern_physics","topic":"Uses and Safety of Radioactivity"}', 2),
  (2708, 662, 'A sealed radioactive source exposes an object to radiation, but no radioactive material is transferred to the object. What has occurred?', 'mcq', 1, 'The object receives radiation, not radioactive material.', '{"why":"Irradiation does not necessarily make an object radioactive; contamination involves radioactive material being present on or in it.","sol":"Step 1: The object is exposed to radiation.\nStep 2: No radioactive material is deposited on or inside it.\nStep 3: This is irradiation rather than contamination.","steps":["Step 1: The object is exposed to radiation.","Step 2: No radioactive material is deposited on or inside it.","Step 3: This is irradiation rather than contamination."],"options":[{"text":"Contamination","is_correct":false},{"text":"Irradiation","is_correct":false},{"text":"Radioactive decay stops","is_correct":false},{"text":"The object becomes a neutron","is_correct":false},{"text":"1","is_correct":true}],"conceptId":"physics_modern_physics_uses_and_safety_of_radioactivity","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q4","subject":"physics","chapter":"modern_physics","topic":"Uses and Safety of Radioactivity"}', 3),
  (2709, 663, 'What are cathode rays?', 'text', 1, 'Identify the particles moving through the tube.', '{"why":"Cathode rays consist of moving electrons.","sol":"Step 1: Recall the particles emitted in a cathode ray tube.\nStep 2: Identify them as electrons.\nStep 3: Describe them as a moving stream.","steps":["Step 1: Recall the particles emitted in a cathode ray tube.","Step 2: Identify them as electrons.","Step 3: Describe them as a moving stream."],"options":[],"conceptId":"physics_cathode_rays_meaning_of_cathode_rays","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q1","subject":"physics","chapter":"cathode_rays","topic":"Meaning of Cathode Rays"}', 0),
  (2710, 663, 'Are cathode rays streams of electrons or protons?', 'text', 1, 'Focus on the core principle of Meaning of Cathode Rays.', '{"why":"Electrons are the particles emitted to form cathode rays.","sol":"Step 1: Recall the definition of cathode rays.\nStep 2: Identify the particles that form the rays.\nStep 3: Choose electrons rather than protons.","steps":["Step 1: Recall the definition of cathode rays.","Step 2: Identify the particles that form the rays.","Step 3: Choose electrons rather than protons."],"options":[],"conceptId":"physics_cathode_rays_meaning_of_cathode_rays","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q2","subject":"physics","chapter":"cathode_rays","topic":"Meaning of Cathode Rays"}', 1),
  (2711, 663, 'A student describes cathode rays as ordinary light. What is wrong with this description?', 'text', 1, 'Think about the particles that form the rays.', '{"why":"Cathode rays have the particle nature of electrons.","sol":"Step 1: Recall what cathode rays consist of.\nStep 2: Identify electrons as material particles.\nStep 3: Distinguish the electron beam from light.","steps":["Step 1: Recall what cathode rays consist of.","Step 2: Identify electrons as material particles.","Step 3: Distinguish the electron beam from light."],"options":[],"conceptId":"physics_cathode_rays_meaning_of_cathode_rays","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q3","subject":"physics","chapter":"cathode_rays","topic":"Meaning of Cathode Rays"}', 2),
  (2712, 664, 'Why are cathode rays negatively charged?', 'text', 1, 'Think about the charge of an electron.', '{"why":"Each electron carries negative electric charge.","sol":"Step 1: Identify the particles forming cathode rays.\nStep 2: Recall that electrons carry negative charge.\nStep 3: Apply this property to the electron stream.","steps":["Step 1: Identify the particles forming cathode rays.","Step 2: Recall that electrons carry negative charge.","Step 3: Apply this property to the electron stream."],"options":[],"conceptId":"physics_cathode_rays_negative_charge_of_cathode_rays","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q1","subject":"physics","chapter":"cathode_rays","topic":"Negative Charge of Cathode Rays"}', 0),
  (2713, 664, 'State the approximate charge of one electron.', 'text', 1, 'Focus on the core principle of Negative Charge of Cathode Rays.', '{"why":"An electron carries approximately -1.6 × 10⁻¹⁹ coulombs.","sol":"Step 1: Recall the elementary charge magnitude.\nStep 2: Use the negative sign for an electron.\nStep 3: Include the SI unit.","steps":["Step 1: Recall the elementary charge magnitude.","Step 2: Use the negative sign for an electron.","Step 3: Include the SI unit."],"options":[],"conceptId":"physics_cathode_rays_negative_charge_of_cathode_rays","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q2","subject":"physics","chapter":"cathode_rays","topic":"Negative Charge of Cathode Rays"}', 1),
  (2714, 664, 'A beam is positively charged. Why is it not a cathode ray beam?', 'text', 1, 'Focus on the core principle of Negative Charge of Cathode Rays.', '{"why":"The negative charge follows from the identity of the particles.","sol":"Step 1: Recall that cathode rays consist of electrons.\nStep 2: Recall that electrons have negative charge.\nStep 3: Compare the expected charge with the stated positive charge.","steps":["Step 1: Recall that cathode rays consist of electrons.","Step 2: Recall that electrons have negative charge.","Step 3: Compare the expected charge with the stated positive charge."],"options":[],"conceptId":"physics_cathode_rays_negative_charge_of_cathode_rays","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q3","subject":"physics","chapter":"cathode_rays","topic":"Negative Charge of Cathode Rays"}', 2),
  (2715, 665, 'How do cathode rays travel in the absence of deflecting fields?', 'text', 1, 'Focus on the core principle of Straight-Line Travel of Cathode Rays.', '{"why":"Their straight-line travel can be demonstrated by shadow formation.","sol":"Step 1: Recall the observed path of cathode rays.\nStep 2: State the direction of travel.","steps":["Step 1: Recall the observed path of cathode rays.","Step 2: State the direction of travel."],"options":[],"conceptId":"physics_cathode_rays_straight_line_travel_of_cathode_rays","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q1","subject":"physics","chapter":"cathode_rays","topic":"Straight-Line Travel of Cathode Rays"}', 0),
  (2716, 665, 'Why does an opaque object produce a shadow in a cathode ray beam?', 'text', 1, 'Think about the path of the rays and what the object blocks.', '{"why":"The shadow demonstrates that the rays do not simply bend around the object.","sol":"Step 1: Cathode rays travel in straight lines.\nStep 2: The object blocks rays travelling toward the screen.\nStep 3: The region behind the object receives no direct rays.","steps":["Step 1: Cathode rays travel in straight lines.","Step 2: The object blocks rays travelling toward the screen.","Step 3: The region behind the object receives no direct rays."],"options":[],"conceptId":"physics_cathode_rays_straight_line_travel_of_cathode_rays","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q2","subject":"physics","chapter":"cathode_rays","topic":"Straight-Line Travel of Cathode Rays"}', 1),
  (2717, 665, 'Which observation supports the straight-line travel of cathode rays?', 'text', 1, 'Focus on the core principle of Straight-Line Travel of Cathode Rays.', '{"why":"The object blocks the rays travelling directly toward the screen.","sol":"Step 1: Consider placing an object in the beam.\nStep 2: Observe the pattern on a fluorescent screen.\nStep 3: Identify the dark region behind the object.","steps":["Step 1: Consider placing an object in the beam.","Step 2: Observe the pattern on a fluorescent screen.","Step 3: Identify the dark region behind the object."],"options":[],"conceptId":"physics_cathode_rays_straight_line_travel_of_cathode_rays","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q3","subject":"physics","chapter":"cathode_rays","topic":"Straight-Line Travel of Cathode Rays"}', 2),
  (2718, 666, 'What does the movement of a light paddle wheel under cathode ray bombardment demonstrate?', 'text', 1, 'Think about the motion transferred to the wheel.', '{"why":"The electron beam transfers momentum to the paddle wheel.","sol":"Step 1: Observe that the wheel moves.\nStep 2: Recognize that the beam transfers momentum.\nStep 3: Relate this observation to particle behaviour.","steps":["Step 1: Observe that the wheel moves.","Step 2: Recognize that the beam transfers momentum.","Step 3: Relate this observation to particle behaviour."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_as_particles","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q1","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays as Particles"}', 0),
  (2719, 666, 'What is transferred from cathode rays to a paddle wheel when the beam makes it move?', 'text', 1, 'Focus on the core principle of Cathode Rays as Particles.', '{"why":"The interaction transfers momentum from the beam to the wheel.","sol":"Step 1: Identify the moving electron beam.\nStep 2: Identify the wheel''s resulting motion.\nStep 3: Name the physical quantity transferred.","steps":["Step 1: Identify the moving electron beam.","Step 2: Identify the wheel''s resulting motion.","Step 3: Name the physical quantity transferred."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_as_particles","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q2","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays as Particles"}', 1),
  (2720, 666, 'Does a stationary paddle wheel prove that cathode rays are not particles?', 'text', 1, 'Focus on the core principle of Cathode Rays as Particles.', '{"why":"A single experimental result is not sufficient to disprove the particle nature of cathode rays.","sol":"Step 1: Recall that the experiment uses wheel movement as evidence.\nStep 2: Recognize that one unsuccessful observation may have other causes.\nStep 3: Avoid treating the observation as conclusive proof.","steps":["Step 1: Recall that the experiment uses wheel movement as evidence.","Step 2: Recognize that one unsuccessful observation may have other causes.","Step 3: Avoid treating the observation as conclusive proof."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_as_particles","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q3","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays as Particles"}', 2),
  (2721, 667, 'What is the function of the cathode in a cathode ray tube?', 'text', 1, 'Think about the source of the electrons.', '{"why":"Cathode rays are streams of electrons originating from the electron source.","sol":"Step 1: Recall the particles that form cathode rays.\nStep 2: Identify the electrode that supplies these particles.\nStep 3: State the function of the cathode.","steps":["Step 1: Recall the particles that form cathode rays.","Step 2: Identify the electrode that supplies these particles.","Step 3: State the function of the cathode."],"options":[],"conceptId":"physics_cathode_rays_function_of_the_cathode","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q1","subject":"physics","chapter":"cathode_rays","topic":"Function of the Cathode"}', 0),
  (2722, 667, 'What is the electrical polarity of the cathode?', 'text', 1, 'Focus on the core principle of Function of the Cathode.', '{"why":"The cathode is the negative electrode in the discharge tube.","sol":"Step 1: Recall the two types of electrode in the tube.\nStep 2: Identify the cathode''s polarity.","steps":["Step 1: Recall the two types of electrode in the tube.","Step 2: Identify the cathode''s polarity."],"options":[],"conceptId":"physics_cathode_rays_function_of_the_cathode","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q2","subject":"physics","chapter":"cathode_rays","topic":"Function of the Cathode"}', 1),
  (2723, 667, 'A learner states that the cathode supplies protons to produce cathode rays. Correct the statement.', 'text', 1, 'Identify the particles that make up cathode rays.', '{"why":"Cathode rays consist of electrons.","sol":"Step 1: Recall the composition of cathode rays.\nStep 2: Identify the correct particle.\nStep 3: Replace the incorrect particle in the statement.","steps":["Step 1: Recall the composition of cathode rays.","Step 2: Identify the correct particle.","Step 3: Replace the incorrect particle in the statement."],"options":[],"conceptId":"physics_cathode_rays_function_of_the_cathode","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q3","subject":"physics","chapter":"cathode_rays","topic":"Function of the Cathode"}', 2),
  (2724, 668, 'Define electron emission.', 'text', 1, 'Focus on the core principle of Electron Emission in a Discharge Tube.', '{"why":"The emitted electrons can move away from the material and form an electron beam.","sol":"Step 1: Identify the particle involved.\nStep 2: Describe the particle leaving a material.\nStep 3: State the definition.","steps":["Step 1: Identify the particle involved.","Step 2: Describe the particle leaving a material.","Step 3: State the definition."],"options":[],"conceptId":"physics_cathode_rays_electron_emission_in_a_discharge_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q1","subject":"physics","chapter":"cathode_rays","topic":"Electron Emission in a Discharge Tube"}', 0),
  (2725, 668, 'What is thermionic emission?', 'text', 1, 'Think about the effect of heating.', '{"why":"Heating provides electrons with energy to escape from the material.","sol":"Step 1: Identify the energy supplied to the material.\nStep 2: Explain that heating allows electrons to escape.\nStep 3: Name the process.","steps":["Step 1: Identify the energy supplied to the material.","Step 2: Explain that heating allows electrons to escape.","Step 3: Name the process."],"options":[],"conceptId":"physics_cathode_rays_electron_emission_in_a_discharge_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q2","subject":"physics","chapter":"cathode_rays","topic":"Electron Emission in a Discharge Tube"}', 1),
  (2726, 668, 'Why must electrons be emitted before a cathode ray beam can be formed?', 'text', 1, 'Focus on the core principle of Electron Emission in a Discharge Tube.', '{"why":"An electron beam cannot form unless electrons are available to move through the tube.","sol":"Step 1: Recall that cathode rays consist of electrons.\nStep 2: Identify the need for electrons to leave the source.\nStep 3: Explain that the released electrons can then be accelerated.","steps":["Step 1: Recall that cathode rays consist of electrons.","Step 2: Identify the need for electrons to leave the source.","Step 3: Explain that the released electrons can then be accelerated."],"options":[],"conceptId":"physics_cathode_rays_electron_emission_in_a_discharge_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q3","subject":"physics","chapter":"cathode_rays","topic":"Electron Emission in a Discharge Tube"}', 2),
  (2727, 669, 'State the function of the anode in a cathode ray tube.', 'text', 1, 'Consider what the positive electrode does to electrons.', '{"why":"The electric field between the electrodes accelerates negatively charged electrons towards the positive anode.","sol":"Step 1: Identify the polarity of the anode.\nStep 2: Recall the charge of electrons.\nStep 3: Explain the anode''s effect on the electrons.","steps":["Step 1: Identify the polarity of the anode.","Step 2: Recall the charge of electrons.","Step 3: Explain the anode''s effect on the electrons."],"options":[],"conceptId":"physics_cathode_rays_function_of_the_anode","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q1","subject":"physics","chapter":"cathode_rays","topic":"Function of the Anode"}', 0),
  (2728, 669, 'Why are electrons attracted towards the anode?', 'text', 1, 'Focus on the core principle of Function of the Anode.', '{"why":"Opposite electric charges attract.","sol":"Step 1: State the charge of an electron.\nStep 2: State the charge of the anode.\nStep 3: Apply the rule for opposite electric charges.","steps":["Step 1: State the charge of an electron.","Step 2: State the charge of the anode.","Step 3: Apply the rule for opposite electric charges."],"options":[],"conceptId":"physics_cathode_rays_function_of_the_anode","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q2","subject":"physics","chapter":"cathode_rays","topic":"Function of the Anode"}', 1),
  (2729, 669, 'What happens to the kinetic energy gained by electrons when the accelerating potential difference increases?', 'text', 1, 'Consider the energy transferred by the electric field.', '{"why":"For an electron accelerated from rest through a potential difference V, the kinetic energy gained is eV.","sol":"Step 1: Recall that an electric potential difference transfers energy to electrons.\nStep 2: Relate the energy gained to the potential difference.\nStep 3: State the change in kinetic energy.","steps":["Step 1: Recall that an electric potential difference transfers energy to electrons.","Step 2: Relate the energy gained to the potential difference.","Step 3: State the change in kinetic energy."],"options":[],"conceptId":"physics_cathode_rays_function_of_the_anode","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q3","subject":"physics","chapter":"cathode_rays","topic":"Function of the Anode"}', 2),
  (2730, 670, 'An electron starts from rest and passes through an accelerating potential difference of 150 V. Calculate its kinetic energy gained. Use e = 1.6 × 10⁻¹⁹ C.', 'text', 1, 'Use KE = eV.', '{"why":"The kinetic energy gained by an electron accelerated from rest through a potential difference V is eV.","sol":"Step 1: Write KE = eV.\nStep 2: Substitute e = 1.6 × 10⁻¹⁹ C and V = 150 V.\nStep 3: Calculate KE = 1.6 × 10⁻¹⁹ × 150.\nStep 4: State the answer in joules.","steps":["Step 1: Write KE = eV.","Step 2: Substitute e = 1.6 × 10⁻¹⁹ C and V = 150 V.","Step 3: Calculate KE = 1.6 × 10⁻¹⁹ × 150.","Step 4: State the answer in joules."],"options":[],"conceptId":"physics_cathode_rays_acceleration_of_electrons_by_potential_difference","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q1","subject":"physics","chapter":"cathode_rays","topic":"Acceleration of Electrons by Potential Difference"}', 0),
  (2731, 670, 'An electron is accelerated from rest through 250 V. If e = 1.6 × 10⁻¹⁹ C, calculate its kinetic energy gained.', 'text', 1, 'Multiply the magnitude of the electron charge by the potential difference.', '{"why":"A potential difference of 250 V gives an electron an energy gain of 250 electron-volts, equivalent to 4.0 × 10⁻¹⁷ J.","sol":"Step 1: Use KE = eV.\nStep 2: Substitute KE = (1.6 × 10⁻¹⁹) × 250.\nStep 3: Multiply 1.6 by 250.\nStep 4: Express the result in joules.","steps":["Step 1: Use KE = eV.","Step 2: Substitute KE = (1.6 × 10⁻¹⁹) × 250.","Step 3: Multiply 1.6 by 250.","Step 4: Express the result in joules."],"options":[],"conceptId":"physics_cathode_rays_acceleration_of_electrons_by_potential_difference","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q2","subject":"physics","chapter":"cathode_rays","topic":"Acceleration of Electrons by Potential Difference"}', 1),
  (2732, 670, 'An electron starts from rest and gains 3.2 × 10⁻¹⁷ J of kinetic energy. Calculate the potential difference through which it was accelerated. Use e = 1.6 × 10⁻¹⁹ C.', 'text', 1, 'Rearrange KE = eV to make V the subject.', '{"why":"The potential difference is the kinetic energy gained divided by the magnitude of the electron charge.","sol":"Step 1: Write KE = eV.\nStep 2: Rearrange to V = KE/e.\nStep 3: Substitute V = (3.2 × 10⁻¹⁷)/(1.6 × 10⁻¹⁹).\nStep 4: Calculate the ratio.","steps":["Step 1: Write KE = eV.","Step 2: Rearrange to V = KE/e.","Step 3: Substitute V = (3.2 × 10⁻¹⁷)/(1.6 × 10⁻¹⁹).","Step 4: Calculate the ratio."],"options":[],"conceptId":"physics_cathode_rays_acceleration_of_electrons_by_potential_difference","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q3","subject":"physics","chapter":"cathode_rays","topic":"Acceleration of Electrons by Potential Difference"}', 2),
  (2733, 670, 'An electron starts from rest and is accelerated through 100 V. Calculate its speed. Use e = 1.6 × 10⁻¹⁹ C and m = 9.11 × 10⁻³¹ kg.', 'text', 1, 'Use eV = ½mv² and rearrange for v.', '{"why":"The electric potential energy transferred to the electron becomes kinetic energy. This calculation uses the non-relativistic kinetic energy formula.","sol":"Step 1: Write eV = ½mv².\nStep 2: Rearrange to v = √(2eV/m).\nStep 3: Substitute v = √[(2 × 1.6 × 10⁻¹⁹ × 100)/(9.11 × 10⁻³¹)].\nStep 4: Evaluate the square root.","steps":["Step 1: Write eV = ½mv².","Step 2: Rearrange to v = √(2eV/m).","Step 3: Substitute v = √[(2 × 1.6 × 10⁻¹⁹ × 100)/(9.11 × 10⁻³¹)].","Step 4: Evaluate the square root."],"options":[],"conceptId":"physics_cathode_rays_acceleration_of_electrons_by_potential_difference","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q4","subject":"physics","chapter":"cathode_rays","topic":"Acceleration of Electrons by Potential Difference"}', 3),
  (2734, 671, 'What is fluorescence?', 'text', 1, 'Think about the light emitted by a material.', '{"why":"Energy supplied by the incident particles can cause the material to emit visible light.","sol":"Step 1: Consider a suitable material struck by energetic particles.\nStep 2: Identify the energy transfer to the material.\nStep 3: Describe the resulting emission of visible light.","steps":["Step 1: Consider a suitable material struck by energetic particles.","Step 2: Identify the energy transfer to the material.","Step 3: Describe the resulting emission of visible light."],"options":[],"conceptId":"physics_cathode_rays_fluorescence_caused_by_cathode_rays","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q1","subject":"physics","chapter":"cathode_rays","topic":"Fluorescence Caused by Cathode Rays"}', 0),
  (2735, 671, 'Why does a fluorescent screen glow when struck by cathode rays?', 'text', 1, 'Focus on the core principle of Fluorescence Caused by Cathode Rays.', '{"why":"The fluorescent material converts some of the energy deposited by the electron beam into light.","sol":"Step 1: The electrons strike the fluorescent coating.\nStep 2: The electrons transfer energy to the coating.\nStep 3: The coating emits visible light.","steps":["Step 1: The electrons strike the fluorescent coating.","Step 2: The electrons transfer energy to the coating.","Step 3: The coating emits visible light."],"options":[],"conceptId":"physics_cathode_rays_fluorescence_caused_by_cathode_rays","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q2","subject":"physics","chapter":"cathode_rays","topic":"Fluorescence Caused by Cathode Rays"}', 1),
  (2736, 671, 'Name one material that can fluoresce when struck by cathode rays.', 'text', 1, 'Focus on the core principle of Fluorescence Caused by Cathode Rays.', '{"why":"Zinc sulphide is a fluorescent material that can glow when struck by energetic particles.","sol":"Step 1: Recall a material used to demonstrate fluorescence.\nStep 2: State one valid example.","steps":["Step 1: Recall a material used to demonstrate fluorescence.","Step 2: State one valid example."],"options":[],"conceptId":"physics_cathode_rays_fluorescence_caused_by_cathode_rays","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q3","subject":"physics","chapter":"cathode_rays","topic":"Fluorescence Caused by Cathode Rays"}', 2),
  (2737, 672, 'What is the mechanical effect of cathode rays?', 'text', 1, 'Think about what the electron beam can do to an object.', '{"why":"Electrons carry momentum and can transfer it when they interact with matter.","sol":"Step 1: Recall that cathode rays are moving electrons.\nStep 2: Consider their interaction with an object.\nStep 3: Identify the resulting force or motion.","steps":["Step 1: Recall that cathode rays are moving electrons.","Step 2: Consider their interaction with an object.","Step 3: Identify the resulting force or motion."],"options":[],"conceptId":"physics_cathode_rays_mechanical_effect_of_cathode_rays","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q1","subject":"physics","chapter":"cathode_rays","topic":"Mechanical Effect of Cathode Rays"}', 0),
  (2738, 672, 'What does the movement of a paddle wheel under cathode ray bombardment demonstrate?', 'text', 1, 'Focus on the core principle of Mechanical Effect of Cathode Rays.', '{"why":"Moving electrons can transfer momentum to the paddle wheel.","sol":"Step 1: The electron beam strikes the wheel.\nStep 2: Momentum is transferred to the wheel.\nStep 3: The wheel changes its motion.","steps":["Step 1: The electron beam strikes the wheel.","Step 2: Momentum is transferred to the wheel.","Step 3: The wheel changes its motion."],"options":[],"conceptId":"physics_cathode_rays_mechanical_effect_of_cathode_rays","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q2","subject":"physics","chapter":"cathode_rays","topic":"Mechanical Effect of Cathode Rays"}', 1),
  (2739, 672, 'Which physical quantity is transferred when cathode rays push an object?', 'text', 1, 'Focus on the core principle of Mechanical Effect of Cathode Rays.', '{"why":"Momentum is transferred during the interaction between the electrons and the object.","sol":"Step 1: Identify the moving electron beam.\nStep 2: Consider the quantity responsible for the change in the object''s motion.\nStep 3: Name the quantity.","steps":["Step 1: Identify the moving electron beam.","Step 2: Consider the quantity responsible for the change in the object''s motion.","Step 3: Name the quantity."],"options":[],"conceptId":"physics_cathode_rays_mechanical_effect_of_cathode_rays","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q3","subject":"physics","chapter":"cathode_rays","topic":"Mechanical Effect of Cathode Rays"}', 2),
  (2740, 673, 'Why are cathode rays deflected by an electric field?', 'text', 1, 'Recall the charge carried by electrons.', '{"why":"An electric field exerts a force on charged particles.","sol":"Step 1: Identify the particles forming cathode rays.\nStep 2: Recall their negative charge.\nStep 3: Explain how an electric field acts on charged particles.","steps":["Step 1: Identify the particles forming cathode rays.","Step 2: Recall their negative charge.","Step 3: Explain how an electric field acts on charged particles."],"options":[],"conceptId":"physics_cathode_rays_deflection_of_cathode_rays_by_an_electric_field","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q1","subject":"physics","chapter":"cathode_rays","topic":"Deflection of Cathode Rays by an Electric Field"}', 0),
  (2741, 673, 'Towards which plate does a cathode ray beam bend between oppositely charged plates?', 'text', 1, 'Focus on the core principle of Deflection of Cathode Rays by an Electric Field.', '{"why":"The negative electrons are attracted towards the positive plate.","sol":"Step 1: Recall that electrons have negative charge.\nStep 2: Apply the rule that opposite charges attract.\nStep 3: Identify the positive plate.","steps":["Step 1: Recall that electrons have negative charge.","Step 2: Apply the rule that opposite charges attract.","Step 3: Identify the positive plate."],"options":[],"conceptId":"physics_cathode_rays_deflection_of_cathode_rays_by_an_electric_field","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q2","subject":"physics","chapter":"cathode_rays","topic":"Deflection of Cathode Rays by an Electric Field"}', 1),
  (2742, 673, 'The upper plate is positive and the lower plate is negative. In which direction does the cathode ray beam deflect?', 'text', 1, 'Focus on the core principle of Deflection of Cathode Rays by an Electric Field.', '{"why":"The electric force on negatively charged electrons is towards the positive plate.","sol":"Step 1: Identify the positive plate as the upper plate.\nStep 2: Recall that electrons are negatively charged.\nStep 3: Determine the direction of the electric force.","steps":["Step 1: Identify the positive plate as the upper plate.","Step 2: Recall that electrons are negatively charged.","Step 3: Determine the direction of the electric force."],"options":[],"conceptId":"physics_cathode_rays_deflection_of_cathode_rays_by_an_electric_field","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q3","subject":"physics","chapter":"cathode_rays","topic":"Deflection of Cathode Rays by an Electric Field"}', 2),
  (2743, 674, 'Why can a magnetic field deflect cathode rays?', 'text', 1, 'Think about moving charged particles.', '{"why":"Moving charged particles experience a magnetic force when their motion has a component perpendicular to the field.","sol":"Step 1: Identify cathode rays as moving electrons.\nStep 2: Recall that electrons carry charge.\nStep 3: Explain the action of a magnetic field on moving charges.","steps":["Step 1: Identify cathode rays as moving electrons.","Step 2: Recall that electrons carry charge.","Step 3: Explain the action of a magnetic field on moving charges."],"options":[],"conceptId":"physics_cathode_rays_deflection_of_cathode_rays_by_a_magnetic_field","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q1","subject":"physics","chapter":"cathode_rays","topic":"Deflection of Cathode Rays by a Magnetic Field"}', 0),
  (2744, 674, 'What happens to the magnetic deflection when the magnetic field is reversed but the electron beam direction remains unchanged?', 'text', 1, 'Focus on the core principle of Deflection of Cathode Rays by a Magnetic Field.', '{"why":"The magnetic force direction depends on both the velocity and magnetic field directions.","sol":"Step 1: Identify the original magnetic force.\nStep 2: Reverse the magnetic field direction.\nStep 3: Determine how the force direction changes.","steps":["Step 1: Identify the original magnetic force.","Step 2: Reverse the magnetic field direction.","Step 3: Determine how the force direction changes."],"options":[],"conceptId":"physics_cathode_rays_deflection_of_cathode_rays_by_a_magnetic_field","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q2","subject":"physics","chapter":"cathode_rays","topic":"Deflection of Cathode Rays by a Magnetic Field"}', 1),
  (2745, 674, 'An electron moves parallel to a uniform magnetic field. What is the magnetic force on the electron?', 'text', 1, 'Consider the angle between the velocity and the magnetic field.', '{"why":"The magnetic force is qvB sin(theta), which is zero when the velocity is parallel to the magnetic field.","sol":"Step 1: Recall that magnetic force magnitude is proportional to qvB sin(theta).\nStep 2: For parallel motion, theta is zero degrees.\nStep 3: Evaluate sin(0 degrees).","steps":["Step 1: Recall that magnetic force magnitude is proportional to qvB sin(theta).","Step 2: For parallel motion, theta is zero degrees.","Step 3: Evaluate sin(0 degrees)."],"options":[],"conceptId":"physics_cathode_rays_deflection_of_cathode_rays_by_a_magnetic_field","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q3","subject":"physics","chapter":"cathode_rays","topic":"Deflection of Cathode Rays by a Magnetic Field"}', 2),
  (2746, 675, 'Why do cathode rays possess kinetic energy?', 'text', 1, 'Focus on the core principle of Energy and Momentum of Cathode Rays.', '{"why":"Kinetic energy is the energy an object has due to its motion.","sol":"Step 1: Recall that cathode rays consist of electrons.\nStep 2: Identify that the electrons are moving.\nStep 3: Relate motion to kinetic energy.","steps":["Step 1: Recall that cathode rays consist of electrons.","Step 2: Identify that the electrons are moving.","Step 3: Relate motion to kinetic energy."],"options":[],"conceptId":"physics_cathode_rays_energy_and_momentum_of_cathode_rays","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q1","subject":"physics","chapter":"cathode_rays","topic":"Energy and Momentum of Cathode Rays"}', 0),
  (2747, 675, 'An electron of mass 9.11 × 10⁻³¹ kg moves at 2.0 × 10⁶ m/s. Calculate its momentum.', 'text', 1, 'Use p = mv.', '{"why":"Momentum is the product of mass and velocity.","sol":"Step 1: Write p = mv.\nStep 2: Substitute p = (9.11 × 10⁻³¹)(2.0 × 10⁶).\nStep 3: Multiply 9.11 by 2.0.\nStep 4: Combine the powers of ten.","steps":["Step 1: Write p = mv.","Step 2: Substitute p = (9.11 × 10⁻³¹)(2.0 × 10⁶).","Step 3: Multiply 9.11 by 2.0.","Step 4: Combine the powers of ten."],"options":[],"conceptId":"physics_cathode_rays_energy_and_momentum_of_cathode_rays","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q2","subject":"physics","chapter":"cathode_rays","topic":"Energy and Momentum of Cathode Rays"}', 1),
  (2748, 675, 'An electron of mass 9.11 × 10⁻³¹ kg moves at 2.0 × 10⁶ m/s. Calculate its kinetic energy.', 'text', 1, 'Use KE = 1/2 mv².', '{"why":"For a non-relativistic electron, kinetic energy is half its mass multiplied by the square of its speed.","sol":"Step 1: Write KE = 1/2 mv².\nStep 2: Square the speed to obtain 4.0 × 10¹² m²/s².\nStep 3: Substitute the mass and squared speed.\nStep 4: Calculate KE = 1.822 × 10⁻¹⁸ J.","steps":["Step 1: Write KE = 1/2 mv².","Step 2: Square the speed to obtain 4.0 × 10¹² m²/s².","Step 3: Substitute the mass and squared speed.","Step 4: Calculate KE = 1.822 × 10⁻¹⁸ J."],"options":[],"conceptId":"physics_cathode_rays_energy_and_momentum_of_cathode_rays","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q3","subject":"physics","chapter":"cathode_rays","topic":"Energy and Momentum of Cathode Rays"}', 2),
  (2749, 676, 'Which part of a CRT produces the electron beam?', 'text', 1, 'Look for the component that supplies the electrons.', '{"why":"The electron gun produces and directs the electrons.","sol":"Step 1: The CRT needs a beam of electrons.\nStep 2: The electron gun produces this beam.","steps":["Step 1: The CRT needs a beam of electrons.","Step 2: The electron gun produces this beam."],"options":[],"conceptId":"physics_cathode_rays_main_parts_of_a_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q1","subject":"physics","chapter":"cathode_rays","topic":"Main Parts of a Cathode Ray Tube"}', 0),
  (2750, 676, 'Which part of a CRT changes the direction of the electron beam?', 'text', 1, 'This component moves the beam across the screen.', '{"why":"The deflection plates control the direction of the beam.","sol":"Step 1: The beam must be directed to different positions.\nStep 2: The deflection plates change its direction.","steps":["Step 1: The beam must be directed to different positions.","Step 2: The deflection plates change its direction."],"options":[],"conceptId":"physics_cathode_rays_main_parts_of_a_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q2","subject":"physics","chapter":"cathode_rays","topic":"Main Parts of a Cathode Ray Tube"}', 1);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (2751, 676, 'Which part of a CRT produces a visible spot when struck by electrons?', 'text', 1, 'It is the display surface at the end of the tube.', '{"why":"The fluorescent screen makes the position of the electron beam visible.","sol":"Step 1: The electron beam strikes the end of the tube.\nStep 2: The fluorescent screen emits visible light.","steps":["Step 1: The electron beam strikes the end of the tube.","Step 2: The fluorescent screen emits visible light."],"options":[],"conceptId":"physics_cathode_rays_main_parts_of_a_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q3","subject":"physics","chapter":"cathode_rays","topic":"Main Parts of a Cathode Ray Tube"}', 2),
  (2752, 677, 'What is the main function of the electron gun in a CRT?', 'text', 1, 'Think about what must be produced before the beam can be deflected.', '{"why":"The electron gun supplies the beam used by the CRT.","sol":"Step 1: A CRT operates using electrons.\nStep 2: The electron gun produces and directs a beam of electrons.","steps":["Step 1: A CRT operates using electrons.","Step 2: The electron gun produces and directs a beam of electrons."],"options":[],"conceptId":"physics_cathode_rays_function_of_the_electron_gun","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q1","subject":"physics","chapter":"cathode_rays","topic":"Function of the Electron Gun"}', 0),
  (2753, 677, 'Why is the cathode heated in the electron gun?', 'text', 1, 'Heating helps electrons leave the cathode.', '{"why":"Heating the cathode causes thermionic emission.","sol":"Step 1: Electrons are released from the cathode.\nStep 2: Heating supplies energy for their emission.","steps":["Step 1: Electrons are released from the cathode.","Step 2: Heating supplies energy for their emission."],"options":[],"conceptId":"physics_cathode_rays_function_of_the_electron_gun","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q2","subject":"physics","chapter":"cathode_rays","topic":"Function of the Electron Gun"}', 1),
  (2754, 677, 'What is the function of the focusing system in an electron gun?', 'text', 1, 'Consider the shape of the beam.', '{"why":"A narrow beam produces a more clearly defined spot on the screen.","sol":"Step 1: The electrons must form a concentrated beam.\nStep 2: The focusing system reduces the spreading of the beam.","steps":["Step 1: The electrons must form a concentrated beam.","Step 2: The focusing system reduces the spreading of the beam."],"options":[],"conceptId":"physics_cathode_rays_function_of_the_electron_gun","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q3","subject":"physics","chapter":"cathode_rays","topic":"Function of the Electron Gun"}', 2),
  (2755, 678, 'Which CRT plates control the horizontal position of the electron beam?', 'text', 1, 'The X-direction represents horizontal movement.', '{"why":"The X-plates move the beam horizontally.","sol":"Step 1: Horizontal movement corresponds to the X-direction.\nStep 2: The X-deflection plates control this direction.","steps":["Step 1: Horizontal movement corresponds to the X-direction.","Step 2: The X-deflection plates control this direction."],"options":[],"conceptId":"physics_cathode_rays_function_of_the_x_deflection_plates","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q1","subject":"physics","chapter":"cathode_rays","topic":"Function of the X-Deflection Plates"}', 0),
  (2756, 678, 'What happens to the horizontal deflection when the polarity of the X-plates is reversed?', 'text', 1, 'Reversing the polarity reverses the electric field.', '{"why":"The negative charge of the electrons makes the force reverse when the electric field reverses.","sol":"Step 1: The direction of the electric field reverses.\nStep 2: The force on the electrons reverses.\nStep 3: The horizontal deflection changes direction.","steps":["Step 1: The direction of the electric field reverses.","Step 2: The force on the electrons reverses.","Step 3: The horizontal deflection changes direction."],"options":[],"conceptId":"physics_cathode_rays_function_of_the_x_deflection_plates","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q2","subject":"physics","chapter":"cathode_rays","topic":"Function of the X-Deflection Plates"}', 1),
  (2757, 678, 'What is the horizontal deflection caused by the X-plates if no potential difference is applied across them?', 'text', 1, 'Without a potential difference, is there an electric field between the plates?', '{"why":"The X-plates need an electric field to cause horizontal deflection.","sol":"Step 1: No potential difference means no electric field due to the X-plates.\nStep 2: The X-plates therefore exert no horizontal electric force.","steps":["Step 1: No potential difference means no electric field due to the X-plates.","Step 2: The X-plates therefore exert no horizontal electric force."],"options":[],"conceptId":"physics_cathode_rays_function_of_the_x_deflection_plates","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q3","subject":"physics","chapter":"cathode_rays","topic":"Function of the X-Deflection Plates"}', 2),
  (2758, 679, 'Which CRT plates control the vertical position of the electron beam?', 'text', 1, 'The Y-direction represents vertical movement.', '{"why":"The Y-plates move the beam vertically.","sol":"Step 1: Vertical movement is movement up or down.\nStep 2: The Y-deflection plates control this movement.","steps":["Step 1: Vertical movement is movement up or down.","Step 2: The Y-deflection plates control this movement."],"options":[],"conceptId":"physics_cathode_rays_function_of_the_y_deflection_plates","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q1","subject":"physics","chapter":"cathode_rays","topic":"Function of the Y-Deflection Plates"}', 0),
  (2759, 679, 'What happens to the vertical deflection when the polarity of the Y-plates is reversed?', 'text', 1, 'Think about the direction of the electric field and force.', '{"why":"Reversing the electric field reverses the force on the electrons.","sol":"Step 1: Reversing the polarity reverses the electric field.\nStep 2: The force on the negatively charged electrons reverses.\nStep 3: The beam deflects in the opposite vertical direction.","steps":["Step 1: Reversing the polarity reverses the electric field.","Step 2: The force on the negatively charged electrons reverses.","Step 3: The beam deflects in the opposite vertical direction."],"options":[],"conceptId":"physics_cathode_rays_function_of_the_y_deflection_plates","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q2","subject":"physics","chapter":"cathode_rays","topic":"Function of the Y-Deflection Plates"}', 1),
  (2760, 679, 'What is the vertical deflection caused by the Y-plates if no potential difference is applied across them?', 'text', 1, 'Consider whether the plates produce an electric field.', '{"why":"The Y-plates need an electric field to cause vertical deflection.","sol":"Step 1: No potential difference means no electric field due to the Y-plates.\nStep 2: The Y-plates exert no vertical electric force.","steps":["Step 1: No potential difference means no electric field due to the Y-plates.","Step 2: The Y-plates exert no vertical electric force."],"options":[],"conceptId":"physics_cathode_rays_function_of_the_y_deflection_plates","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q3","subject":"physics","chapter":"cathode_rays","topic":"Function of the Y-Deflection Plates"}', 2),
  (2761, 680, 'What is the main function of the fluorescent screen in a CRT?', 'text', 1, 'The electron beam is not directly visible.', '{"why":"The fluorescent screen converts the beam''s point of impact into visible light.","sol":"Step 1: The electron beam strikes the screen.\nStep 2: The screen emits visible light at the point of impact.","steps":["Step 1: The electron beam strikes the screen.","Step 2: The screen emits visible light at the point of impact."],"options":[],"conceptId":"physics_cathode_rays_function_of_the_fluorescent_screen","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q1","subject":"physics","chapter":"cathode_rays","topic":"Function of the Fluorescent Screen"}', 0),
  (2762, 680, 'What does the position of the fluorescent spot indicate?', 'text', 1, 'The spot forms where the beam strikes the screen.', '{"why":"The spot represents the position of the beam on the screen.","sol":"Step 1: The spot is produced at the point of impact.\nStep 2: That point shows where the beam reaches the screen.","steps":["Step 1: The spot is produced at the point of impact.","Step 2: That point shows where the beam reaches the screen."],"options":[],"conceptId":"physics_cathode_rays_function_of_the_fluorescent_screen","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q2","subject":"physics","chapter":"cathode_rays","topic":"Function of the Fluorescent Screen"}', 1),
  (2763, 680, 'What happens to the fluorescent spot when the electron beam is deflected?', 'text', 1, 'The beam reaches a different point after its direction changes.', '{"why":"The visible spot follows the point where the beam hits the screen.","sol":"Step 1: Deflection changes the beam''s direction.\nStep 2: The beam strikes a different position on the screen.","steps":["Step 1: Deflection changes the beam''s direction.","Step 2: The beam strikes a different position on the screen."],"options":[],"conceptId":"physics_cathode_rays_function_of_the_fluorescent_screen","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q3","subject":"physics","chapter":"cathode_rays","topic":"Function of the Fluorescent Screen"}', 2),
  (2764, 681, 'Which sequence correctly describes how a visible spot is formed in a CRT?', 'text', 1, 'Start with electron emission and finish with light from the screen.', '{"why":"The spot appears when the electron beam reaches the fluorescent screen.","sol":"Step 1: The heated cathode emits electrons.\nStep 2: The electron gun forms a beam.\nStep 3: The beam is accelerated and directed.\nStep 4: The beam strikes the fluorescent screen, which emits light.","steps":["Step 1: The heated cathode emits electrons.","Step 2: The electron gun forms a beam.","Step 3: The beam is accelerated and directed.","Step 4: The beam strikes the fluorescent screen, which emits light."],"options":[],"conceptId":"physics_cathode_rays_formation_of_a_visible_spot_on_the_screen","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q1","subject":"physics","chapter":"cathode_rays","topic":"Formation of a Visible Spot on the Screen"}', 0),
  (2765, 681, 'What must happen for the fluorescent screen to produce a visible spot?', 'text', 1, 'Think about what causes the screen to emit light.', '{"why":"The impact causes the screen to emit light at that position.","sol":"Step 1: The screen emits light at the point of impact.\nStep 2: The electron beam must strike the screen.","steps":["Step 1: The screen emits light at the point of impact.","Step 2: The electron beam must strike the screen."],"options":[],"conceptId":"physics_cathode_rays_formation_of_a_visible_spot_on_the_screen","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q2","subject":"physics","chapter":"cathode_rays","topic":"Formation of a Visible Spot on the Screen"}', 1),
  (2766, 681, 'The voltage across the deflection plates is changed and the spot moves. Explain why.', 'text', 1, 'Connect the voltage to the electric field, force and beam direction.', '{"why":"The spot follows the point where the deflected beam strikes the screen.","sol":"Step 1: Changing the voltage changes the electric field.\nStep 2: The field changes the force on the electrons.\nStep 3: The beam follows a different path and strikes a new position.","steps":["Step 1: Changing the voltage changes the electric field.","Step 2: The field changes the force on the electrons.","Step 3: The beam follows a different path and strikes a new position."],"options":[],"conceptId":"physics_cathode_rays_formation_of_a_visible_spot_on_the_screen","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q3","subject":"physics","chapter":"cathode_rays","topic":"Formation of a Visible Spot on the Screen"}', 2),
  (2767, 682, 'Calculate the energy gained by an electron accelerated through a potential difference of 20 V. Take e = 1.6 × 10⁻¹⁹ C.', 'text', 1, 'Use E = eV.', '{"why":"The energy gained is the electron charge multiplied by the potential difference.","sol":"Step 1: E = eV\nStep 2: E = 1.6 × 10⁻¹⁹ × 20\nStep 3: E = 3.2 × 10⁻¹⁸ J","steps":["Step 1: E = eV","Step 2: E = 1.6 × 10⁻¹⁹ × 20","Step 3: E = 3.2 × 10⁻¹⁸ J"],"options":[],"conceptId":"physics_cathode_rays_energy_gained_by_an_electron","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q1","subject":"physics","chapter":"cathode_rays","topic":"Energy Gained by an Electron"}', 0),
  (2768, 682, 'An electron gains 4.8 × 10⁻¹⁷ J of energy. Calculate the potential difference through which it moved.', 'text', 1, 'Rearrange E = eV to make V the subject.', '{"why":"Dividing the energy gained by the electron charge gives the potential difference.","sol":"Step 1: V = E/e\nStep 2: V = (4.8 × 10⁻¹⁷)/(1.6 × 10⁻¹⁹)\nStep 3: V = 300 V","steps":["Step 1: V = E/e","Step 2: V = (4.8 × 10⁻¹⁷)/(1.6 × 10⁻¹⁹)","Step 3: V = 300 V"],"options":[],"conceptId":"physics_cathode_rays_energy_gained_by_an_electron","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q2","subject":"physics","chapter":"cathode_rays","topic":"Energy Gained by an Electron"}', 1),
  (2769, 682, 'An electron is accelerated from rest through 100 V. Assuming all the gained energy becomes kinetic energy, calculate its kinetic energy.', 'text', 1, 'For an electron starting from rest, KE = eV.', '{"why":"The electrical energy gained becomes kinetic energy when the electron starts from rest and energy losses are neglected.","sol":"Step 1: KE = eV\nStep 2: KE = 1.6 × 10⁻¹⁹ × 100\nStep 3: KE = 1.6 × 10⁻¹⁷ J","steps":["Step 1: KE = eV","Step 2: KE = 1.6 × 10⁻¹⁹ × 100","Step 3: KE = 1.6 × 10⁻¹⁷ J"],"options":[],"conceptId":"physics_cathode_rays_energy_gained_by_an_electron","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q3","subject":"physics","chapter":"cathode_rays","topic":"Energy Gained by an Electron"}', 2),
  (2770, 683, 'Convert 10 eV to joules. Take 1 eV = 1.6 × 10⁻¹⁹ J.', 'text', 1, 'Multiply the energy in eV by 1.6 × 10⁻¹⁹.', '{"why":"Electron-volts are converted to joules by multiplying by 1.6 × 10⁻¹⁹.","sol":"Step 1: E = 10 × 1.6 × 10⁻¹⁹\nStep 2: E = 1.6 × 10⁻¹⁸ J","steps":["Step 1: E = 10 × 1.6 × 10⁻¹⁹","Step 2: E = 1.6 × 10⁻¹⁸ J"],"options":[],"conceptId":"physics_cathode_rays_the_electron_volt","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q1","subject":"physics","chapter":"cathode_rays","topic":"The Electron-Volt"}', 0),
  (2771, 683, 'Convert 3.2 × 10⁻¹⁸ J to electron-volts.', 'text', 1, 'Divide the energy in joules by 1.6 × 10⁻¹⁹.', '{"why":"Dividing by the energy equivalent of one electron-volt gives the energy in eV.","sol":"Step 1: E = (3.2 × 10⁻¹⁸)/(1.6 × 10⁻¹⁹)\nStep 2: E = 20 eV","steps":["Step 1: E = (3.2 × 10⁻¹⁸)/(1.6 × 10⁻¹⁹)","Step 2: E = 20 eV"],"options":[],"conceptId":"physics_cathode_rays_the_electron_volt","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q2","subject":"physics","chapter":"cathode_rays","topic":"The Electron-Volt"}', 1),
  (2772, 683, 'An electron gains 400 eV. Calculate this energy in joules.', 'text', 1, 'Use 1 eV = 1.6 × 10⁻¹⁹ J.', '{"why":"Multiplication by the joule equivalent of one eV gives the energy in joules.","sol":"Step 1: E = 400 × 1.6 × 10⁻¹⁹\nStep 2: E = 640 × 10⁻¹⁹ J\nStep 3: E = 6.4 × 10⁻¹⁷ J","steps":["Step 1: E = 400 × 1.6 × 10⁻¹⁹","Step 2: E = 640 × 10⁻¹⁹ J","Step 3: E = 6.4 × 10⁻¹⁷ J"],"options":[],"conceptId":"physics_cathode_rays_the_electron_volt","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q3","subject":"physics","chapter":"cathode_rays","topic":"The Electron-Volt"}', 2),
  (2773, 684, 'An electron has kinetic energy 8.0 × 10⁻¹⁸ J. Calculate its speed. Take its mass as 9.11 × 10⁻³¹ kg.', 'text', 1, 'Use v = √(2KE/m).', '{"why":"The kinetic energy equation can be rearranged to calculate speed.","sol":"Step 1: v = √(2KE/m)\nStep 2: v = √[(2 × 8.0 × 10⁻¹⁸)/(9.11 × 10⁻³¹)]\nStep 3: v ≈ 4.19 × 10⁶ m/s","steps":["Step 1: v = √(2KE/m)","Step 2: v = √[(2 × 8.0 × 10⁻¹⁸)/(9.11 × 10⁻³¹)]","Step 3: v ≈ 4.19 × 10⁶ m/s"],"options":[],"conceptId":"physics_cathode_rays_speed_of_an_accelerated_electron","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q1","subject":"physics","chapter":"cathode_rays","topic":"Speed of an Accelerated Electron"}', 0),
  (2774, 684, 'An electron starts from rest and is accelerated through 50 V. Calculate its kinetic energy in joules.', 'text', 1, 'First use KE = eV.', '{"why":"The electrical energy gained becomes kinetic energy when the electron starts from rest and energy losses are neglected.","sol":"Step 1: KE = eV\nStep 2: KE = 1.6 × 10⁻¹⁹ × 50\nStep 3: KE = 8.0 × 10⁻¹⁸ J","steps":["Step 1: KE = eV","Step 2: KE = 1.6 × 10⁻¹⁹ × 50","Step 3: KE = 8.0 × 10⁻¹⁸ J"],"options":[],"conceptId":"physics_cathode_rays_speed_of_an_accelerated_electron","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q2","subject":"physics","chapter":"cathode_rays","topic":"Speed of an Accelerated Electron"}', 1),
  (2775, 684, 'An electron starts from rest and gains 3.2 × 10⁻¹⁸ J of kinetic energy. Calculate its speed. Take m = 9.11 × 10⁻³¹ kg.', 'text', 1, 'Substitute the kinetic energy and mass into v = √(2KE/m).', '{"why":"The speed follows from the relationship between kinetic energy, mass and speed.","sol":"Step 1: v = √(2KE/m)\nStep 2: v = √[(2 × 3.2 × 10⁻¹⁸)/(9.11 × 10⁻³¹)]\nStep 3: v ≈ 2.65 × 10⁶ m/s","steps":["Step 1: v = √(2KE/m)","Step 2: v = √[(2 × 3.2 × 10⁻¹⁸)/(9.11 × 10⁻³¹)]","Step 3: v ≈ 2.65 × 10⁶ m/s"],"options":[],"conceptId":"physics_cathode_rays_speed_of_an_accelerated_electron","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q3","subject":"physics","chapter":"cathode_rays","topic":"Speed of an Accelerated Electron"}', 2),
  (2776, 685, 'An electron starts from rest and reaches a speed of 3.0 × 10⁶ m/s. Calculate the accelerating potential difference. Take m = 9.11 × 10⁻³¹ kg and e = 1.6 × 10⁻¹⁹ C.', 'text', 1, 'Use V = mv²/(2e).', '{"why":"The electrical energy gained equals the kinetic energy when the electron starts from rest and losses are neglected.","sol":"Step 1: V = mv²/(2e)\nStep 2: V = [(9.11 × 10⁻³¹)(3.0 × 10⁶)²]/(3.2 × 10⁻¹⁹)\nStep 3: V ≈ 25.6 V","steps":["Step 1: V = mv²/(2e)","Step 2: V = [(9.11 × 10⁻³¹)(3.0 × 10⁶)²]/(3.2 × 10⁻¹⁹)","Step 3: V ≈ 25.6 V"],"options":[],"conceptId":"physics_cathode_rays_potential_difference_from_electron_speed","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q1","subject":"physics","chapter":"cathode_rays","topic":"Potential Difference from Electron Speed"}', 0),
  (2777, 685, 'An electron is accelerated from rest through 100 V. Which equation can be used to find its final speed?', 'text', 1, 'Combine KE = eV with KE = ½mv².', '{"why":"Equating electrical energy gained to kinetic energy gives the speed equation.","sol":"Step 1: eV = ½mv²\nStep 2: v² = 2eV/m\nStep 3: v = √(2eV/m)","steps":["Step 1: eV = ½mv²","Step 2: v² = 2eV/m","Step 3: v = √(2eV/m)"],"options":[],"conceptId":"physics_cathode_rays_potential_difference_from_electron_speed","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q2","subject":"physics","chapter":"cathode_rays","topic":"Potential Difference from Electron Speed"}', 1),
  (2778, 685, 'An electron''s speed doubles. By what factor does the potential difference needed to produce that speed change, assuming it starts from rest?', 'text', 1, 'The equation contains v².', '{"why":"The accelerating potential difference is proportional to the square of the final speed.","sol":"Step 1: V = mv²/(2e)\nStep 2: Potential difference is proportional to speed squared.\nStep 3: Doubling speed multiplies v² by 2² = 4.","steps":["Step 1: V = mv²/(2e)","Step 2: Potential difference is proportional to speed squared.","Step 3: Doubling speed multiplies v² by 2² = 4."],"options":[],"conceptId":"physics_cathode_rays_potential_difference_from_electron_speed","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q3","subject":"physics","chapter":"cathode_rays","topic":"Potential Difference from Electron Speed"}', 2),
  (2779, 686, 'What is the main purpose of a cathode-ray oscilloscope?', 'text', 1, 'Think about what it displays on its screen.', '{"why":"The CRO allows changes in an electrical signal to be observed.","sol":"Step 1: The instrument receives an electrical signal.\nStep 2: It displays the signal as a trace.","steps":["Step 1: The instrument receives an electrical signal.","Step 2: It displays the signal as a trace."],"options":[],"conceptId":"physics_cathode_rays_the_cathode_ray_oscilloscope","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q1","subject":"physics","chapter":"cathode_rays","topic":"The Cathode-Ray Oscilloscope"}', 0),
  (2780, 686, 'In normal CRO operation, what does the vertical position of the trace represent?', 'text', 1, 'The input signal controls the vertical deflection.', '{"why":"Vertical deflection is controlled by the input signal.","sol":"Step 1: The input voltage affects the vertical deflection.\nStep 2: The trace position therefore represents the signal voltage.","steps":["Step 1: The input voltage affects the vertical deflection.","Step 2: The trace position therefore represents the signal voltage."],"options":[],"conceptId":"physics_cathode_rays_the_cathode_ray_oscilloscope","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q2","subject":"physics","chapter":"cathode_rays","topic":"The Cathode-Ray Oscilloscope"}', 1),
  (2781, 686, 'What is the function of the time-base voltage in a CRO?', 'text', 1, 'It controls movement along the horizontal direction.', '{"why":"The horizontal sweep allows the signal to be displayed against time.","sol":"Step 1: The signal must be displayed over time.\nStep 2: The time-base voltage sweeps the beam horizontally.","steps":["Step 1: The signal must be displayed over time.","Step 2: The time-base voltage sweeps the beam horizontally."],"options":[],"conceptId":"physics_cathode_rays_the_cathode_ray_oscilloscope","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q3","subject":"physics","chapter":"cathode_rays","topic":"The Cathode-Ray Oscilloscope"}', 2),
  (2782, 687, 'How did an older CRT television form a picture?', 'text', 1, 'Consider how the electron beam moved and how the screen responded.', '{"why":"The beam''s position and intensity controlled the light emitted at different parts of the screen.","sol":"Step 1: The electron beam scanned across the screen.\nStep 2: Its intensity was varied according to the picture signal.\nStep 3: The screen emitted light to form the picture.","steps":["Step 1: The electron beam scanned across the screen.","Step 2: Its intensity was varied according to the picture signal.","Step 3: The screen emitted light to form the picture."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_in_older_television_displays","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q1","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays in Older Television Displays"}', 0),
  (2783, 687, 'Why did the electron beam scan across the screen of a CRT television?', 'text', 1, 'A complete picture contains information at many positions.', '{"why":"Scanning allows the beam to create the picture at different screen positions.","sol":"Step 1: The picture contains details across the screen.\nStep 2: The beam visits different positions to reproduce those details.","steps":["Step 1: The picture contains details across the screen.","Step 2: The beam visits different positions to reproduce those details."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_in_older_television_displays","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q2","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays in Older Television Displays"}', 1),
  (2784, 687, 'What controlled the brightness of a point on an older CRT television screen?', 'text', 1, 'The picture signal changed how strongly the beam struck the screen.', '{"why":"A stronger or weaker beam changes the light emitted at the point of impact.","sol":"Step 1: The picture signal varied the beam''s intensity.\nStep 2: The beam caused the screen to emit light.\nStep 3: The intensity affected the brightness.","steps":["Step 1: The picture signal varied the beam''s intensity.","Step 2: The beam caused the screen to emit light.","Step 3: The intensity affected the brightness."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_in_older_television_displays","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q3","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays in Older Television Displays"}', 2),
  (2785, 688, 'What is photoelectric emission?', 'text', 1, 'Focus on what leaves the material when suitable light falls on it.', '{"why":"Photoelectric emission describes the release of electrons due to incident light.","sol":"Step 1: Light of sufficiently high frequency falls on a material.\nStep 2: Electrons are released from its surface.","steps":["Step 1: Light of sufficiently high frequency falls on a material.","Step 2: Electrons are released from its surface."],"options":[],"conceptId":"physics_photoelectric_emission_meaning_of_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q1","subject":"physics","chapter":"photoelectric_emission","topic":"Meaning of Photoelectric Emission"}', 0),
  (2786, 688, 'Light of sufficiently high frequency falls on a metal, causing electrons to leave its surface. Name the phenomenon.', 'text', 1, 'It is the phenomenon defined by the release of electrons due to light.', '{"why":"The release of electrons from a surface due to suitable incident light is photoelectric emission.","sol":"Step 1: Light strikes the metal.\nStep 2: Electrons leave the metal''s surface.\nStep 3: This process is photoelectric emission.","steps":["Step 1: Light strikes the metal.","Step 2: Electrons leave the metal''s surface.","Step 3: This process is photoelectric emission."],"options":[],"conceptId":"physics_photoelectric_emission_meaning_of_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q2","subject":"physics","chapter":"photoelectric_emission","topic":"Meaning of Photoelectric Emission"}', 1),
  (2787, 688, 'A learner says photoelectric emission means light bouncing off a metal surface. Identify the error.', 'text', 1, 'Distinguish the behaviour of light from the release of electrons.', '{"why":"Reflection concerns light; photoelectric emission concerns electrons released from a surface.","sol":"Step 1: Bouncing light is reflection.\nStep 2: Photoelectric emission involves electrons leaving the material.","steps":["Step 1: Bouncing light is reflection.","Step 2: Photoelectric emission involves electrons leaving the material."],"options":[],"conceptId":"physics_photoelectric_emission_meaning_of_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q3","subject":"physics","chapter":"photoelectric_emission","topic":"Meaning of Photoelectric Emission"}', 2),
  (2788, 689, 'What are photoelectrons?', 'text', 1, 'They are named according to the process that releases them.', '{"why":"Photoelectrons are the electrons released by the photoelectric effect.","sol":"Step 1: Suitable light causes electrons to leave a material.\nStep 2: These emitted electrons are called photoelectrons.","steps":["Step 1: Suitable light causes electrons to leave a material.","Step 2: These emitted electrons are called photoelectrons."],"options":[],"conceptId":"physics_photoelectric_emission_meaning_of_photoelectrons","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q1","subject":"physics","chapter":"photoelectric_emission","topic":"Meaning of Photoelectrons"}', 0),
  (2789, 689, 'What is the electric charge of a photoelectron?', 'text', 1, 'A photoelectron is still an electron.', '{"why":"Emission does not change an electron''s electric charge.","sol":"Step 1: Photoelectrons are electrons.\nStep 2: Electrons carry negative charge.","steps":["Step 1: Photoelectrons are electrons.","Step 2: Electrons carry negative charge."],"options":[],"conceptId":"physics_photoelectric_emission_meaning_of_photoelectrons","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q2","subject":"physics","chapter":"photoelectric_emission","topic":"Meaning of Photoelectrons"}', 1),
  (2790, 689, 'A metal releases electrons when illuminated by suitable light. What are those electrons called?', 'text', 1, 'Use the term for electrons emitted by the photoelectric effect.', '{"why":"The name specifically refers to electrons released during photoelectric emission.","sol":"Step 1: The electrons are emitted due to incident light.\nStep 2: Electrons emitted in this process are photoelectrons.","steps":["Step 1: The electrons are emitted due to incident light.","Step 2: Electrons emitted in this process are photoelectrons."],"options":[],"conceptId":"physics_photoelectric_emission_meaning_of_photoelectrons","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q3","subject":"physics","chapter":"photoelectric_emission","topic":"Meaning of Photoelectrons"}', 2),
  (2791, 690, 'What role does incident light play in photoelectric emission?', 'text', 1, 'Think about the energy needed for electrons to escape the material.', '{"why":"Photoelectric emission occurs when electrons receive sufficient energy from incident light.","sol":"Step 1: Incident light carries energy.\nStep 2: Electrons absorb energy from the light.\nStep 3: If the photon energy is sufficient, electrons can escape.","steps":["Step 1: Incident light carries energy.","Step 2: Electrons absorb energy from the light.","Step 3: If the photon energy is sufficient, electrons can escape."],"options":[],"conceptId":"physics_photoelectric_emission_role_of_incident_light_in_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q1","subject":"physics","chapter":"photoelectric_emission","topic":"Role of Incident Light in Photoelectric Emission"}', 0),
  (2792, 690, 'A material has a threshold frequency of 7.0 × 10¹⁴ Hz. Light of frequency 4.0 × 10¹⁴ Hz falls on it. Does photoelectric emission occur?', 'text', 1, 'Compare the incident frequency with the threshold frequency.', '{"why":"Light below the threshold frequency does not cause photoelectric emission from that material.","sol":"Step 1: Threshold frequency = 7.0 × 10¹⁴ Hz.\nStep 2: Incident frequency = 4.0 × 10¹⁴ Hz.\nStep 3: The incident frequency is below the threshold.","steps":["Step 1: Threshold frequency = 7.0 × 10¹⁴ Hz.","Step 2: Incident frequency = 4.0 × 10¹⁴ Hz.","Step 3: The incident frequency is below the threshold."],"options":[],"conceptId":"physics_photoelectric_emission_role_of_incident_light_in_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q2","subject":"physics","chapter":"photoelectric_emission","topic":"Role of Incident Light in Photoelectric Emission"}', 1),
  (2793, 690, 'Light below a metal''s threshold frequency is made more intense without changing its frequency. Will photoelectric emission begin?', 'text', 1, 'Intensity and frequency are different properties of light.', '{"why":"Photoelectric emission requires sufficient photon energy, which depends on frequency.","sol":"Step 1: The frequency remains below the threshold.\nStep 2: Increasing intensity does not increase the energy of each photon.\nStep 3: The photons remain insufficient to cause emission.","steps":["Step 1: The frequency remains below the threshold.","Step 2: Increasing intensity does not increase the energy of each photon.","Step 3: The photons remain insufficient to cause emission."],"options":[],"conceptId":"physics_photoelectric_emission_role_of_incident_light_in_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q3","subject":"physics","chapter":"photoelectric_emission","topic":"Role of Incident Light in Photoelectric Emission"}', 2),
  (2794, 691, 'What is a photon?', 'text', 1, 'Think of how electromagnetic radiation transfers energy.', '{"why":"A photon is the quantum of electromagnetic radiation.","sol":"Step 1: Electromagnetic radiation transfers energy in discrete packets.\nStep 2: Each packet is called a photon.","steps":["Step 1: Electromagnetic radiation transfers energy in discrete packets.","Step 2: Each packet is called a photon."],"options":[],"conceptId":"physics_photoelectric_emission_meaning_of_a_photon","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q1","subject":"physics","chapter":"photoelectric_emission","topic":"Meaning of a Photon"}', 0),
  (2795, 691, 'What is the electric charge of a photon?', 'text', 1, 'A photon is electrically neutral.', '{"why":"Photons carry no electric charge.","sol":"Step 1: A photon is not a charged particle such as an electron.\nStep 2: Its electric charge is zero.","steps":["Step 1: A photon is not a charged particle such as an electron.","Step 2: Its electric charge is zero."],"options":[],"conceptId":"physics_photoelectric_emission_meaning_of_a_photon","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q2","subject":"physics","chapter":"photoelectric_emission","topic":"Meaning of a Photon"}', 1),
  (2796, 691, 'Which property of electromagnetic radiation determines the energy of an individual photon?', 'text', 1, 'The relevant property appears in E = hf.', '{"why":"Photon energy is directly proportional to the frequency of the radiation.","sol":"Step 1: Photon energy is given by E = hf.\nStep 2: Here, f represents frequency.","steps":["Step 1: Photon energy is given by E = hf.","Step 2: Here, f represents frequency."],"options":[],"conceptId":"physics_photoelectric_emission_meaning_of_a_photon","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q3","subject":"physics","chapter":"photoelectric_emission","topic":"Meaning of a Photon"}', 2),
  (2797, 692, 'State the equation for the energy of a photon.', 'text', 1, 'It relates energy, Planck''s constant and frequency.', '{"why":"Planck''s equation relates photon energy to its frequency.","sol":"Step 1: Photon energy is proportional to frequency.\nStep 2: The relationship is E = hf.","steps":["Step 1: Photon energy is proportional to frequency.","Step 2: The relationship is E = hf."],"options":[],"conceptId":"physics_photoelectric_emission_relationship_between_photon_energy_and_frequency","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q1","subject":"physics","chapter":"photoelectric_emission","topic":"Relationship Between Photon Energy and Frequency"}', 0),
  (2798, 692, 'What happens to the energy of each photon when the frequency of light is doubled?', 'text', 1, 'Use E = hf and keep h constant.', '{"why":"Photon energy is directly proportional to frequency.","sol":"Step 1: E = hf.\nStep 2: Doubling f doubles hf.\nStep 3: Therefore, the photon energy doubles.","steps":["Step 1: E = hf.","Step 2: Doubling f doubles hf.","Step 3: Therefore, the photon energy doubles."],"options":[],"conceptId":"physics_photoelectric_emission_relationship_between_photon_energy_and_frequency","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q2","subject":"physics","chapter":"photoelectric_emission","topic":"Relationship Between Photon Energy and Frequency"}', 1),
  (2799, 692, 'Light A has a frequency of 8.0 × 10¹⁴ Hz, while light B has a frequency of 4.0 × 10¹⁴ Hz. Compare the energy of one photon from each light.', 'text', 1, 'Compare the frequencies before calculating either energy.', '{"why":"The photon energy ratio is equal to the frequency ratio.","sol":"Step 1: The frequency ratio is (8.0 × 10¹⁴)/(4.0 × 10¹⁴) = 2.\nStep 2: Photon energy is proportional to frequency.\nStep 3: Each photon of light A has twice the energy of each photon of light B.","steps":["Step 1: The frequency ratio is (8.0 × 10¹⁴)/(4.0 × 10¹⁴) = 2.","Step 2: Photon energy is proportional to frequency.","Step 3: Each photon of light A has twice the energy of each photon of light B."],"options":[],"conceptId":"physics_photoelectric_emission_relationship_between_photon_energy_and_frequency","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q3","subject":"physics","chapter":"photoelectric_emission","topic":"Relationship Between Photon Energy and Frequency"}', 2),
  (2800, 693, 'Calculate the energy of a photon of frequency 3.0 × 10¹⁴ Hz. Take h = 6.63 × 10⁻³⁴ J s.', 'text', 1, 'Use E = hf and multiply the two values.', '{"why":"Multiplying Planck''s constant by frequency gives photon energy in joules.","sol":"Step 1: E = hf\nStep 2: E = (6.63 × 10⁻³⁴)(3.0 × 10¹⁴)\nStep 3: E = 1.989 × 10⁻¹⁹ J\nStep 4: E ≈ 1.99 × 10⁻¹⁹ J","steps":["Step 1: E = hf","Step 2: E = (6.63 × 10⁻³⁴)(3.0 × 10¹⁴)","Step 3: E = 1.989 × 10⁻¹⁹ J","Step 4: E ≈ 1.99 × 10⁻¹⁹ J"],"options":[],"conceptId":"physics_photoelectric_emission_calculating_the_energy_of_a_photon","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q1","subject":"physics","chapter":"photoelectric_emission","topic":"Calculating the Energy of a Photon"}', 0),
  (2801, 693, 'Calculate the energy of a photon of frequency 7.0 × 10¹⁴ Hz. Take h = 6.63 × 10⁻³⁴ J s.', 'text', 1, 'Substitute the frequency into E = hf.', '{"why":"Photon energy is found by multiplying frequency by Planck''s constant.","sol":"Step 1: E = hf\nStep 2: E = (6.63 × 10⁻³⁴)(7.0 × 10¹⁴)\nStep 3: E = 4.641 × 10⁻¹⁹ J\nStep 4: E ≈ 4.64 × 10⁻¹⁹ J","steps":["Step 1: E = hf","Step 2: E = (6.63 × 10⁻³⁴)(7.0 × 10¹⁴)","Step 3: E = 4.641 × 10⁻¹⁹ J","Step 4: E ≈ 4.64 × 10⁻¹⁹ J"],"options":[],"conceptId":"physics_photoelectric_emission_calculating_the_energy_of_a_photon","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q2","subject":"physics","chapter":"photoelectric_emission","topic":"Calculating the Energy of a Photon"}', 1),
  (2802, 693, 'A photon has a frequency of 5.5 × 10¹⁴ Hz. Calculate its energy using h = 6.63 × 10⁻³⁴ J s.', 'text', 1, 'Use E = hf. Give your final answer in scientific notation.', '{"why":"Correct multiplication and conversion to standard scientific notation give the photon energy.","sol":"Step 1: E = hf\nStep 2: E = (6.63 × 10⁻³⁴)(5.5 × 10¹⁴)\nStep 3: E = 36.465 × 10⁻²⁰ J\nStep 4: E = 3.6465 × 10⁻¹⁹ J\nStep 5: E ≈ 3.65 × 10⁻¹⁹ J","steps":["Step 1: E = hf","Step 2: E = (6.63 × 10⁻³⁴)(5.5 × 10¹⁴)","Step 3: E = 36.465 × 10⁻²⁰ J","Step 4: E = 3.6465 × 10⁻¹⁹ J","Step 5: E ≈ 3.65 × 10⁻¹⁹ J"],"options":[],"conceptId":"physics_photoelectric_emission_calculating_the_energy_of_a_photon","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q3","subject":"physics","chapter":"photoelectric_emission","topic":"Calculating the Energy of a Photon"}', 2),
  (2803, 694, 'A photon has energy 6.63 × 10⁻¹⁹ J. Calculate its frequency. Take h = 6.63 × 10⁻³⁴ J s.', 'text', 1, 'Rearrange E = hf to make f the subject.', '{"why":"Dividing photon energy by Planck''s constant gives frequency.","sol":"Step 1: f = E/h\nStep 2: f = (6.63 × 10⁻¹⁹)/(6.63 × 10⁻³⁴)\nStep 3: f = 1.0 × 10¹⁵ Hz","steps":["Step 1: f = E/h","Step 2: f = (6.63 × 10⁻¹⁹)/(6.63 × 10⁻³⁴)","Step 3: f = 1.0 × 10¹⁵ Hz"],"options":[],"conceptId":"physics_photoelectric_emission_calculating_frequency_from_photon_energy","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q1","subject":"physics","chapter":"photoelectric_emission","topic":"Calculating Frequency from Photon Energy"}', 0),
  (2804, 694, 'A photon has energy 2.652 × 10⁻¹⁹ J. Calculate its frequency using h = 6.63 × 10⁻³⁴ J s.', 'text', 1, 'Use f = E/h.', '{"why":"The photon frequency is its energy divided by Planck''s constant.","sol":"Step 1: f = E/h\nStep 2: f = (2.652 × 10⁻¹⁹)/(6.63 × 10⁻³⁴)\nStep 3: f = 4.0 × 10¹⁴ Hz","steps":["Step 1: f = E/h","Step 2: f = (2.652 × 10⁻¹⁹)/(6.63 × 10⁻³⁴)","Step 3: f = 4.0 × 10¹⁴ Hz"],"options":[],"conceptId":"physics_photoelectric_emission_calculating_frequency_from_photon_energy","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q2","subject":"physics","chapter":"photoelectric_emission","topic":"Calculating Frequency from Photon Energy"}', 1),
  (2805, 694, 'A photon has energy 4.641 × 10⁻¹⁹ J. Calculate its frequency using h = 6.63 × 10⁻³⁴ J s.', 'text', 1, 'Divide the energy by Planck''s constant and keep the power of ten.', '{"why":"Rearranging Planck''s equation allows frequency to be found from photon energy.","sol":"Step 1: f = E/h\nStep 2: f = (4.641 × 10⁻¹⁹)/(6.63 × 10⁻³⁴)\nStep 3: f = 7.0 × 10¹⁴ Hz","steps":["Step 1: f = E/h","Step 2: f = (4.641 × 10⁻¹⁹)/(6.63 × 10⁻³⁴)","Step 3: f = 7.0 × 10¹⁴ Hz"],"options":[],"conceptId":"physics_photoelectric_emission_calculating_frequency_from_photon_energy","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q3","subject":"physics","chapter":"photoelectric_emission","topic":"Calculating Frequency from Photon Energy"}', 2),
  (2806, 695, 'What is the work function of a material?', 'text', 1, 'Think about the minimum energy needed for an electron to escape.', '{"why":"The work function describes the minimum energy needed for electron emission.","sol":"Step 1: An electron is held within the material.\nStep 2: Energy must be supplied for it to escape the surface.\nStep 3: The minimum required energy is the work function.","steps":["Step 1: An electron is held within the material.","Step 2: Energy must be supplied for it to escape the surface.","Step 3: The minimum required energy is the work function."],"options":[],"conceptId":"physics_photoelectric_emission_meaning_of_work_function","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q1","subject":"physics","chapter":"photoelectric_emission","topic":"Meaning of Work Function"}', 0),
  (2807, 695, 'What symbol is commonly used to represent work function?', 'text', 1, 'It is the Greek letter phi.', '{"why":"The symbol φ is used for work function in photoelectric equations.","sol":"Step 1: Work function is represented by a Greek letter.\nStep 2: The symbol is φ.","steps":["Step 1: Work function is represented by a Greek letter.","Step 2: The symbol is φ."],"options":[],"conceptId":"physics_photoelectric_emission_meaning_of_work_function","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q2","subject":"physics","chapter":"photoelectric_emission","topic":"Meaning of Work Function"}', 1),
  (2808, 695, 'A metal has a work function of 3.0 eV. What does this value mean?', 'text', 1, 'Interpret the value as a minimum energy.', '{"why":"The work function specifies the minimum energy required for emission.","sol":"Step 1: The work function is the minimum energy needed for electron emission.\nStep 2: For this metal, that energy is 3.0 eV.","steps":["Step 1: The work function is the minimum energy needed for electron emission.","Step 2: For this metal, that energy is 3.0 eV."],"options":[],"conceptId":"physics_photoelectric_emission_meaning_of_work_function","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q3","subject":"physics","chapter":"photoelectric_emission","topic":"Meaning of Work Function"}', 2),
  (2809, 696, 'A photon has energy 4.0 eV and a metal has a work function of 2.5 eV. Can photoelectric emission occur?', 'text', 1, 'Compare photon energy with the work function.', '{"why":"A photon must have energy at least equal to the work function.","sol":"Step 1: Photon energy = 4.0 eV.\nStep 2: Work function = 2.5 eV.\nStep 3: Since 4.0 eV is greater than 2.5 eV, emission can occur.","steps":["Step 1: Photon energy = 4.0 eV.","Step 2: Work function = 2.5 eV.","Step 3: Since 4.0 eV is greater than 2.5 eV, emission can occur."],"options":[],"conceptId":"physics_photoelectric_emission_photon_energy_and_the_work_function","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q1","subject":"physics","chapter":"photoelectric_emission","topic":"Photon Energy and the Work Function"}', 0),
  (2810, 696, 'A photon has energy 1.8 eV and a material has a work function of 2.2 eV. Will the photon release an electron?', 'text', 1, 'Check whether photon energy reaches the minimum required energy.', '{"why":"The photon energy is below the work function.","sol":"Step 1: Photon energy = 1.8 eV.\nStep 2: Work function = 2.2 eV.\nStep 3: Since 1.8 eV is less than 2.2 eV, emission cannot occur.","steps":["Step 1: Photon energy = 1.8 eV.","Step 2: Work function = 2.2 eV.","Step 3: Since 1.8 eV is less than 2.2 eV, emission cannot occur."],"options":[],"conceptId":"physics_photoelectric_emission_photon_energy_and_the_work_function","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q2","subject":"physics","chapter":"photoelectric_emission","topic":"Photon Energy and the Work Function"}', 1),
  (2811, 696, 'A photon has energy 3.5 eV and the metal''s work function is 3.5 eV. Calculate the maximum kinetic energy of the emitted electron.', 'text', 1, 'Use KEmax = E − φ.', '{"why":"At the threshold energy, all the photon energy is used to overcome the work function.","sol":"Step 1: KEmax = E − φ\nStep 2: KEmax = 3.5 − 3.5\nStep 3: KEmax = 0 eV","steps":["Step 1: KEmax = E − φ","Step 2: KEmax = 3.5 − 3.5","Step 3: KEmax = 0 eV"],"options":[],"conceptId":"physics_photoelectric_emission_photon_energy_and_the_work_function","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q3","subject":"physics","chapter":"photoelectric_emission","topic":"Photon Energy and the Work Function"}', 2),
  (2812, 697, 'A metal has a threshold frequency of 6.0 × 10¹⁴ Hz. Calculate its work function in joules. Take h = 6.63 × 10⁻³⁴ J s.', 'text', 1, 'Use φ = hf₀.', '{"why":"At threshold frequency, photon energy equals the work function.","sol":"Step 1: φ = hf₀\nStep 2: φ = (6.63 × 10⁻³⁴)(6.0 × 10¹⁴)\nStep 3: φ = 3.978 × 10⁻¹⁹ J\nStep 4: φ ≈ 3.98 × 10⁻¹⁹ J","steps":["Step 1: φ = hf₀","Step 2: φ = (6.63 × 10⁻³⁴)(6.0 × 10¹⁴)","Step 3: φ = 3.978 × 10⁻¹⁹ J","Step 4: φ ≈ 3.98 × 10⁻¹⁹ J"],"options":[],"conceptId":"physics_photoelectric_emission_work_function_from_threshold_frequency","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q1","subject":"physics","chapter":"photoelectric_emission","topic":"Work Function from Threshold Frequency"}', 0),
  (2813, 697, 'A metal has a work function of 3.315 × 10⁻¹⁹ J. Calculate its threshold frequency. Take h = 6.63 × 10⁻³⁴ J s.', 'text', 1, 'Rearrange φ = hf₀ to make f₀ the subject.', '{"why":"Dividing work function by Planck''s constant gives threshold frequency.","sol":"Step 1: f₀ = φ/h\nStep 2: f₀ = (3.315 × 10⁻¹⁹)/(6.63 × 10⁻³⁴)\nStep 3: f₀ = 5.0 × 10¹⁴ Hz","steps":["Step 1: f₀ = φ/h","Step 2: f₀ = (3.315 × 10⁻¹⁹)/(6.63 × 10⁻³⁴)","Step 3: f₀ = 5.0 × 10¹⁴ Hz"],"options":[],"conceptId":"physics_photoelectric_emission_work_function_from_threshold_frequency","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q2","subject":"physics","chapter":"photoelectric_emission","topic":"Work Function from Threshold Frequency"}', 1),
  (2814, 697, 'A metal has a work function of 2.0 × 10⁻¹⁹ J. Calculate its threshold frequency. Take h = 6.63 × 10⁻³⁴ J s.', 'text', 1, 'Use f₀ = φ/h.', '{"why":"The threshold frequency is the work function divided by Planck''s constant.","sol":"Step 1: f₀ = φ/h\nStep 2: f₀ = (2.0 × 10⁻¹⁹)/(6.63 × 10⁻³⁴)\nStep 3: f₀ ≈ 3.02 × 10¹⁴ Hz","steps":["Step 1: f₀ = φ/h","Step 2: f₀ = (2.0 × 10⁻¹⁹)/(6.63 × 10⁻³⁴)","Step 3: f₀ ≈ 3.02 × 10¹⁴ Hz"],"options":[],"conceptId":"physics_photoelectric_emission_work_function_from_threshold_frequency","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q3","subject":"physics","chapter":"photoelectric_emission","topic":"Work Function from Threshold Frequency"}', 2),
  (2815, 698, 'What is the threshold frequency of a material?', 'text', 1, 'It is the minimum frequency required for photoelectric emission.', '{"why":"Threshold frequency identifies the lowest incident frequency that can release electrons from a particular material.","sol":"Step 1: Electrons require sufficient energy to escape a material.\nStep 2: Photon energy depends on frequency.\nStep 3: The minimum frequency that permits emission is the threshold frequency.","steps":["Step 1: Electrons require sufficient energy to escape a material.","Step 2: Photon energy depends on frequency.","Step 3: The minimum frequency that permits emission is the threshold frequency."],"options":[],"conceptId":"physics_photoelectric_emission_meaning_of_threshold_frequency","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q1","subject":"physics","chapter":"photoelectric_emission","topic":"Meaning of Threshold Frequency"}', 0),
  (2816, 698, 'A metal has a threshold frequency of 4.0 × 10¹⁴ Hz. What does this value tell you?', 'text', 1, 'Interpret threshold frequency as a minimum.', '{"why":"Light below the threshold frequency cannot supply enough energy per photon for emission.","sol":"Step 1: Threshold frequency = 4.0 × 10¹⁴ Hz.\nStep 2: Incident light must reach or exceed this frequency for emission.","steps":["Step 1: Threshold frequency = 4.0 × 10¹⁴ Hz.","Step 2: Incident light must reach or exceed this frequency for emission."],"options":[],"conceptId":"physics_photoelectric_emission_meaning_of_threshold_frequency","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q2","subject":"physics","chapter":"photoelectric_emission","topic":"Meaning of Threshold Frequency"}', 1),
  (2817, 698, 'Metal A has a greater work function than metal B. Which metal has the greater threshold frequency?', 'text', 1, 'Use φ = hf₀.', '{"why":"Threshold frequency is directly proportional to work function.","sol":"Step 1: φ = hf₀.\nStep 2: Planck''s constant is the same for both metals.\nStep 3: A greater work function requires a greater threshold frequency.","steps":["Step 1: φ = hf₀.","Step 2: Planck''s constant is the same for both metals.","Step 3: A greater work function requires a greater threshold frequency."],"options":[],"conceptId":"physics_photoelectric_emission_meaning_of_threshold_frequency","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q3","subject":"physics","chapter":"photoelectric_emission","topic":"Meaning of Threshold Frequency"}', 2),
  (2818, 699, 'A metal has a threshold frequency of 7.0 × 10¹⁴ Hz. Light of frequency 5.0 × 10¹⁴ Hz falls on it. Will photoelectric emission occur?', 'text', 1, 'Compare the incident frequency with the threshold frequency.', '{"why":"The photons have insufficient energy to release electrons from the metal.","sol":"Step 1: Threshold frequency = 7.0 × 10¹⁴ Hz.\nStep 2: Incident frequency = 5.0 × 10¹⁴ Hz.\nStep 3: The incident frequency is below the threshold.","steps":["Step 1: Threshold frequency = 7.0 × 10¹⁴ Hz.","Step 2: Incident frequency = 5.0 × 10¹⁴ Hz.","Step 3: The incident frequency is below the threshold."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission_below_threshold_frequency","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q1","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission Below Threshold Frequency"}', 0),
  (2819, 699, 'Light below a metal''s threshold frequency is made more intense without changing its frequency. Will photoelectric emission begin?', 'text', 1, 'Ask whether intensity changes the energy of an individual photon.', '{"why":"Increasing intensity increases photon arrival rate, not the energy of each photon.","sol":"Step 1: Photon energy is E = hf.\nStep 2: The frequency has not changed.\nStep 3: Each photon still has insufficient energy to overcome the work function.","steps":["Step 1: Photon energy is E = hf.","Step 2: The frequency has not changed.","Step 3: Each photon still has insufficient energy to overcome the work function."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission_below_threshold_frequency","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q2","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission Below Threshold Frequency"}', 1),
  (2820, 699, 'A metal has a threshold frequency of 5.0 × 10¹⁴ Hz. Which of these frequencies can cause photoelectric emission: 3.0 × 10¹⁴ Hz, 5.0 × 10¹⁴ Hz, or 8.0 × 10¹⁴ Hz?', 'text', 1, 'Emission can occur at or above the threshold frequency.', '{"why":"Photoelectric emission can occur when the incident frequency equals or exceeds the threshold frequency.","sol":"Step 1: 3.0 × 10¹⁴ Hz is below threshold.\nStep 2: 5.0 × 10¹⁴ Hz equals threshold.\nStep 3: 8.0 × 10¹⁴ Hz is above threshold.","steps":["Step 1: 3.0 × 10¹⁴ Hz is below threshold.","Step 2: 5.0 × 10¹⁴ Hz equals threshold.","Step 3: 8.0 × 10¹⁴ Hz is above threshold."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission_below_threshold_frequency","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q3","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission Below Threshold Frequency"}', 2),
  (2821, 700, 'Light above the threshold frequency is made more intense while its frequency stays constant. What happens to the energy of each photon?', 'text', 1, 'Use E = hf.', '{"why":"Photon energy depends on frequency, not intensity.","sol":"Step 1: E = hf.\nStep 2: The frequency f remains constant.\nStep 3: Planck''s constant h also remains constant.","steps":["Step 1: E = hf.","Step 2: The frequency f remains constant.","Step 3: Planck''s constant h also remains constant."],"options":[],"conceptId":"physics_photoelectric_emission_frequency_and_intensity_of_incident_light","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q1","subject":"physics","chapter":"photoelectric_emission","topic":"Frequency and Intensity of Incident Light"}', 0),
  (2822, 700, 'For light above the threshold frequency, what generally happens to photoelectric current when the light intensity is increased?', 'text', 1, 'Consider how many photons arrive each second.', '{"why":"Under otherwise unchanged conditions, a greater photon arrival rate produces a greater rate of electron emission.","sol":"Step 1: Greater intensity means more photons arrive per unit area per second.\nStep 2: The photon energy remains sufficient for emission.\nStep 3: More electrons can be emitted per second.","steps":["Step 1: Greater intensity means more photons arrive per unit area per second.","Step 2: The photon energy remains sufficient for emission.","Step 3: More electrons can be emitted per second."],"options":[],"conceptId":"physics_photoelectric_emission_frequency_and_intensity_of_incident_light","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q2","subject":"physics","chapter":"photoelectric_emission","topic":"Frequency and Intensity of Incident Light"}', 1),
  (2823, 700, 'Two light beams have the same intensity, but beam A has twice the frequency of beam B. How do their individual photon energies compare?', 'text', 1, 'Compare their frequencies using E = hf.', '{"why":"Photon energy is directly proportional to frequency, regardless of the beams having equal intensity.","sol":"Step 1: E = hf.\nStep 2: The frequency of A is twice that of B.\nStep 3: The energy of each photon in A is twice that of each photon in B.","steps":["Step 1: E = hf.","Step 2: The frequency of A is twice that of B.","Step 3: The energy of each photon in A is twice that of each photon in B."],"options":[],"conceptId":"physics_photoelectric_emission_frequency_and_intensity_of_incident_light","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q3","subject":"physics","chapter":"photoelectric_emission","topic":"Frequency and Intensity of Incident Light"}', 2),
  (2824, 701, 'State Einstein''s photoelectric equation.', 'text', 1, 'Equate the energy supplied by a photon to the energy used for emission and the remaining kinetic energy.', '{"why":"The equation expresses conservation of energy during photoelectric emission.","sol":"Step 1: Photon energy = hf.\nStep 2: Energy is used to overcome the work function φ.\nStep 3: The remaining energy is KEmax.\nStep 4: Therefore, hf = φ + KEmax.","steps":["Step 1: Photon energy = hf.","Step 2: Energy is used to overcome the work function φ.","Step 3: The remaining energy is KEmax.","Step 4: Therefore, hf = φ + KEmax."],"options":[],"conceptId":"physics_photoelectric_emission_einstein_s_photoelectric_equation","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q1","subject":"physics","chapter":"photoelectric_emission","topic":"Einstein''s Photoelectric Equation"}', 0),
  (2825, 701, 'A photon has energy 6.0 eV and the material has a work function of 2.5 eV. How much energy remains as the maximum kinetic energy of the emitted electron?', 'text', 1, 'Subtract the work function from the photon energy.', '{"why":"The work function accounts for the minimum energy needed to release the electron; the excess becomes kinetic energy.","sol":"Step 1: KEmax = E − φ\nStep 2: KEmax = 6.0 − 2.5\nStep 3: KEmax = 3.5 eV","steps":["Step 1: KEmax = E − φ","Step 2: KEmax = 6.0 − 2.5","Step 3: KEmax = 3.5 eV"],"options":[],"conceptId":"physics_photoelectric_emission_einstein_s_photoelectric_equation","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q2","subject":"physics","chapter":"photoelectric_emission","topic":"Einstein''s Photoelectric Equation"}', 1),
  (2826, 701, 'At the threshold frequency, the photon energy equals the work function. What is the maximum kinetic energy of the emitted electron?', 'text', 1, 'Use KEmax = hf − φ.', '{"why":"At threshold, no energy remains for kinetic energy in the ideal model.","sol":"Step 1: KEmax = hf − φ\nStep 2: At threshold, hf = φ.\nStep 3: KEmax = φ − φ = 0.","steps":["Step 1: KEmax = hf − φ","Step 2: At threshold, hf = φ.","Step 3: KEmax = φ − φ = 0."],"options":[],"conceptId":"physics_photoelectric_emission_einstein_s_photoelectric_equation","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q3","subject":"physics","chapter":"photoelectric_emission","topic":"Einstein''s Photoelectric Equation"}', 2),
  (2827, 702, 'A photon has energy 5.5 eV and the work function is 2.5 eV. Calculate the maximum kinetic energy of the emitted electron.', 'text', 1, 'Use KEmax = E − φ.', '{"why":"The maximum kinetic energy is the photon energy remaining after overcoming the work function.","sol":"Step 1: KEmax = E − φ\nStep 2: KEmax = 5.5 − 2.5\nStep 3: KEmax = 3.0 eV","steps":["Step 1: KEmax = E − φ","Step 2: KEmax = 5.5 − 2.5","Step 3: KEmax = 3.0 eV"],"options":[],"conceptId":"physics_photoelectric_emission_calculating_maximum_kinetic_energy","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q1","subject":"physics","chapter":"photoelectric_emission","topic":"Calculating Maximum Kinetic Energy"}', 0),
  (2828, 702, 'A photon has energy 7.2 × 10⁻¹⁹ J and a material has a work function of 2.8 × 10⁻¹⁹ J. Calculate the maximum kinetic energy.', 'text', 1, 'Subtract the work function from the photon energy, keeping the powers of ten consistent.', '{"why":"Subtracting the work function from photon energy gives the maximum kinetic energy.","sol":"Step 1: KEmax = E − φ\nStep 2: KEmax = 7.2 × 10⁻¹⁹ − 2.8 × 10⁻¹⁹\nStep 3: KEmax = 4.4 × 10⁻¹⁹ J","steps":["Step 1: KEmax = E − φ","Step 2: KEmax = 7.2 × 10⁻¹⁹ − 2.8 × 10⁻¹⁹","Step 3: KEmax = 4.4 × 10⁻¹⁹ J"],"options":[],"conceptId":"physics_photoelectric_emission_calculating_maximum_kinetic_energy","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q2","subject":"physics","chapter":"photoelectric_emission","topic":"Calculating Maximum Kinetic Energy"}', 1),
  (2829, 702, 'Light has a frequency of 9.0 × 10¹⁴ Hz and falls on a metal with a work function of 4.0 × 10⁻¹⁹ J. Calculate the maximum kinetic energy. Take h = 6.63 × 10⁻³⁴ J s.', 'text', 1, 'First calculate photon energy using E = hf, then subtract the work function.', '{"why":"Photon energy is calculated first, and the work function is then subtracted to obtain the maximum kinetic energy.","sol":"Step 1: E = hf\nStep 2: E = (6.63 × 10⁻³⁴)(9.0 × 10¹⁴)\nStep 3: E = 5.967 × 10⁻¹⁹ J\nStep 4: KEmax = E − φ\nStep 5: KEmax = 5.967 × 10⁻¹⁹ − 4.0 × 10⁻¹⁹\nStep 6: KEmax = 1.967 × 10⁻¹⁹ J\nStep 7: KEmax ≈ 1.97 × 10⁻¹⁹ J","steps":["Step 1: E = hf","Step 2: E = (6.63 × 10⁻³⁴)(9.0 × 10¹⁴)","Step 3: E = 5.967 × 10⁻¹⁹ J","Step 4: KEmax = E − φ","Step 5: KEmax = 5.967 × 10⁻¹⁹ − 4.0 × 10⁻¹⁹","Step 6: KEmax = 1.967 × 10⁻¹⁹ J","Step 7: KEmax ≈ 1.97 × 10⁻¹⁹ J"],"options":[],"conceptId":"physics_photoelectric_emission_calculating_maximum_kinetic_energy","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q3","subject":"physics","chapter":"photoelectric_emission","topic":"Calculating Maximum Kinetic Energy"}', 2),
  (2830, 703, 'A metal has a work function of 2.0 × 10⁻¹⁹ J. Its emitted electrons have maximum kinetic energy 1.315 × 10⁻¹⁹ J. Calculate the incident frequency. Take h = 6.63 × 10⁻³⁴ J s.', 'text', 1, 'Use f = (φ + KEmax)/h.', '{"why":"The photon energy is the sum of the work function and the maximum kinetic energy.","sol":"Step 1: f = (φ + KEmax)/h\nStep 2: f = [(2.0 × 10⁻¹⁹) + (1.315 × 10⁻¹⁹)]/(6.63 × 10⁻³⁴)\nStep 3: f = (3.315 × 10⁻¹⁹)/(6.63 × 10⁻³⁴)\nStep 4: f = 5.0 × 10¹⁴ Hz","steps":["Step 1: f = (φ + KEmax)/h","Step 2: f = [(2.0 × 10⁻¹⁹) + (1.315 × 10⁻¹⁹)]/(6.63 × 10⁻³⁴)","Step 3: f = (3.315 × 10⁻¹⁹)/(6.63 × 10⁻³⁴)","Step 4: f = 5.0 × 10¹⁴ Hz"],"options":[],"conceptId":"physics_photoelectric_emission_photon_frequency_from_maximum_kinetic_energy","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q1","subject":"physics","chapter":"photoelectric_emission","topic":"Photon Frequency from Maximum Kinetic Energy"}', 0),
  (2831, 703, 'A metal has a work function of 3.0 × 10⁻¹⁹ J. The maximum kinetic energy of its photoelectrons is 1.967 × 10⁻¹⁹ J. Calculate the incident frequency. Take h = 6.63 × 10⁻³⁴ J s.', 'text', 1, 'Add the work function and kinetic energy before dividing by Planck''s constant.', '{"why":"Adding the work function and maximum kinetic energy gives the energy of the incident photon.","sol":"Step 1: f = (φ + KEmax)/h\nStep 2: f = [(3.0 × 10⁻¹⁹) + (1.967 × 10⁻¹⁹)]/(6.63 × 10⁻³⁴)\nStep 3: f = (4.967 × 10⁻¹⁹)/(6.63 × 10⁻³⁴)\nStep 4: f ≈ 7.49 × 10¹⁴ Hz","steps":["Step 1: f = (φ + KEmax)/h","Step 2: f = [(3.0 × 10⁻¹⁹) + (1.967 × 10⁻¹⁹)]/(6.63 × 10⁻³⁴)","Step 3: f = (4.967 × 10⁻¹⁹)/(6.63 × 10⁻³⁴)","Step 4: f ≈ 7.49 × 10¹⁴ Hz"],"options":[],"conceptId":"physics_photoelectric_emission_photon_frequency_from_maximum_kinetic_energy","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q2","subject":"physics","chapter":"photoelectric_emission","topic":"Photon Frequency from Maximum Kinetic Energy"}', 1),
  (2832, 703, 'A material has a work function of 2.5 eV and its photoelectrons have maximum kinetic energy 1.5 eV. Calculate the incident frequency. Take 1 eV = 1.6 × 10⁻¹⁹ J and h = 6.63 × 10⁻³⁴ J s.', 'text', 1, 'Add the energies in eV, convert the total to joules, then use f = E/h.', '{"why":"The incident photon energy equals the work function plus the maximum kinetic energy.","sol":"Step 1: Photon energy = φ + KEmax = 2.5 + 1.5 = 4.0 eV\nStep 2: Photon energy = 4.0 × 1.6 × 10⁻¹⁹ = 6.4 × 10⁻¹⁹ J\nStep 3: f = E/h\nStep 4: f = (6.4 × 10⁻¹⁹)/(6.63 × 10⁻³⁴)\nStep 5: f ≈ 9.65 × 10¹⁴ Hz","steps":["Step 1: Photon energy = φ + KEmax = 2.5 + 1.5 = 4.0 eV","Step 2: Photon energy = 4.0 × 1.6 × 10⁻¹⁹ = 6.4 × 10⁻¹⁹ J","Step 3: f = E/h","Step 4: f = (6.4 × 10⁻¹⁹)/(6.63 × 10⁻³⁴)","Step 5: f ≈ 9.65 × 10¹⁴ Hz"],"options":[],"conceptId":"physics_photoelectric_emission_photon_frequency_from_maximum_kinetic_energy","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q3","subject":"physics","chapter":"photoelectric_emission","topic":"Photon Frequency from Maximum Kinetic Energy"}', 2),
  (2833, 710, 'What is chemistry?', 'text', 1, 'Focus on the core principle of Meaning of Chemistry.', '{"why":"The definition covers both substances themselves and the changes that occur when they interact.","sol":"Step 1: Identify what chemistry studies.\nStep 2: Chemistry studies matter, its composition, structure, properties and changes.\nStep 3: State this as the definition.","steps":["Step 1: Identify what chemistry studies.","Step 2: Chemistry studies matter, its composition, structure, properties and changes.","Step 3: State this as the definition."],"options":[],"conceptId":"chemistry_chemistry_foundations_meaning_of_chemistry","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q1","subject":"chemistry","chapter":"chemistry_foundations","topic":"Meaning of Chemistry"}', 0),
  (2834, 710, 'A student burns magnesium in oxygen. Why is this a chemical process?', 'text', 1, 'Focus on the core principle of Meaning of Chemistry.', '{"why":"Formation of a new substance is evidence of a chemical change.","sol":"Step 1: Identify the substances before the reaction: magnesium and oxygen.\nStep 2: Observe that they react.\nStep 3: A new substance, magnesium oxide, is formed.","steps":["Step 1: Identify the substances before the reaction: magnesium and oxygen.","Step 2: Observe that they react.","Step 3: A new substance, magnesium oxide, is formed."],"options":[],"conceptId":"chemistry_chemistry_foundations_meaning_of_chemistry","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q2","subject":"chemistry","chapter":"chemistry_foundations","topic":"Meaning of Chemistry"}', 1),
  (2835, 710, 'State two things studied in chemistry.', 'text', 1, 'Focus on the core principle of Meaning of Chemistry.', '{"why":"Chemistry investigates both the nature of substances and how they change.","sol":"Step 1: Chemistry studies matter.\nStep 2: It also studies the changes and reactions involving matter.","steps":["Step 1: Chemistry studies matter.","Step 2: It also studies the changes and reactions involving matter."],"options":[],"conceptId":"chemistry_chemistry_foundations_meaning_of_chemistry","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q3","subject":"chemistry","chapter":"chemistry_foundations","topic":"Meaning of Chemistry"}', 2),
  (2836, 710, 'A learner says that chemistry only involves mixing chemicals together. Correct the statement.', 'text', 1, 'Think about everything chemistry studies, not only reactions.', '{"why":"Chemical reactions are only one part of chemistry.","sol":"Step 1: Chemistry studies matter.\nStep 2: It studies composition, structure and properties.\nStep 3: It also studies changes and reactions involving matter.","steps":["Step 1: Chemistry studies matter.","Step 2: It studies composition, structure and properties.","Step 3: It also studies changes and reactions involving matter."],"options":[],"conceptId":"chemistry_chemistry_foundations_meaning_of_chemistry","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q4","subject":"chemistry","chapter":"chemistry_foundations","topic":"Meaning of Chemistry"}', 3),
  (2837, 711, 'Why should chemicals never be tasted in the laboratory?', 'text', 1, 'Focus on the core principle of Laboratory Safety Rules.', '{"why":"The appearance of a chemical cannot be used to determine whether it is safe to consume.","sol":"Step 1: Chemicals are not necessarily safe for consumption.\nStep 2: Some chemicals are poisonous or corrosive.\nStep 3: Therefore tasting them could cause serious injury or poisoning.","steps":["Step 1: Chemicals are not necessarily safe for consumption.","Step 2: Some chemicals are poisonous or corrosive.","Step 3: Therefore tasting them could cause serious injury or poisoning."],"options":[],"conceptId":"chemistry_chemistry_foundations_laboratory_safety_rules","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q1","subject":"chemistry","chapter":"chemistry_foundations","topic":"Laboratory Safety Rules"}', 0),
  (2838, 711, 'Why should a student wear safety goggles during practical work?', 'text', 1, 'Focus on the core principle of Laboratory Safety Rules.', '{"why":"The eyes are particularly vulnerable to chemical injury.","sol":"Step 1: Chemicals may splash during experiments.\nStep 2: Splashes can damage the eyes.\nStep 3: Goggles provide protection against such splashes.","steps":["Step 1: Chemicals may splash during experiments.","Step 2: Splashes can damage the eyes.","Step 3: Goggles provide protection against such splashes."],"options":[],"conceptId":"chemistry_chemistry_foundations_laboratory_safety_rules","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q2","subject":"chemistry","chapter":"chemistry_foundations","topic":"Laboratory Safety Rules"}', 1),
  (2839, 711, 'State three laboratory safety rules.', 'text', 1, 'Focus on the core principle of Laboratory Safety Rules.', '{"why":"These rules reduce exposure to hazardous substances and help accidents receive immediate attention.","sol":"Step 1: Recall rules designed to prevent chemical or physical accidents.\nStep 2: Give three distinct rules.","steps":["Step 1: Recall rules designed to prevent chemical or physical accidents.","Step 2: Give three distinct rules."],"options":[],"conceptId":"chemistry_chemistry_foundations_laboratory_safety_rules","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q3","subject":"chemistry","chapter":"chemistry_foundations","topic":"Laboratory Safety Rules"}', 2),
  (2840, 711, 'A student spills a chemical and decides to leave it because nobody was injured. What should the student have done?', 'text', 1, 'Think about the rule concerning spills.', '{"why":"A spill can remain hazardous even when nobody is immediately injured.","sol":"Step 1: Recognise that the chemical spill may still be hazardous.\nStep 2: Leaving it could expose other people to danger.\nStep 3: Report the spill immediately and follow the laboratory''s spill procedure.","steps":["Step 1: Recognise that the chemical spill may still be hazardous.","Step 2: Leaving it could expose other people to danger.","Step 3: Report the spill immediately and follow the laboratory''s spill procedure."],"options":[],"conceptId":"chemistry_chemistry_foundations_laboratory_safety_rules","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q4","subject":"chemistry","chapter":"chemistry_foundations","topic":"Laboratory Safety Rules"}', 3),
  (2841, 712, 'What does a flammable hazard symbol warn a user about?', 'text', 1, 'Focus on the core principle of Chemical Hazard Symbols.', '{"why":"Flammable substances ignite readily when exposed to a suitable source of ignition.","sol":"Step 1: Identify the property represented by the symbol.\nStep 2: Flammable substances can ignite.\nStep 3: State the associated danger.","steps":["Step 1: Identify the property represented by the symbol.","Step 2: Flammable substances can ignite.","Step 3: State the associated danger."],"options":[],"conceptId":"chemistry_chemistry_foundations_chemical_hazard_symbols","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q1","subject":"chemistry","chapter":"chemistry_foundations","topic":"Chemical Hazard Symbols"}', 0),
  (2842, 712, 'What does the corrosive hazard symbol indicate?', 'text', 1, 'Focus on the core principle of Chemical Hazard Symbols.', '{"why":"Corrosive substances can cause serious chemical burns and damage equipment.","sol":"Step 1: Identify the meaning of corrosive.\nStep 2: A corrosive substance can attack materials or living tissue.\nStep 3: State the warning.","steps":["Step 1: Identify the meaning of corrosive.","Step 2: A corrosive substance can attack materials or living tissue.","Step 3: State the warning."],"options":[],"conceptId":"chemistry_chemistry_foundations_chemical_hazard_symbols","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q2","subject":"chemistry","chapter":"chemistry_foundations","topic":"Chemical Hazard Symbols"}', 1),
  (2843, 712, 'Why are hazard symbols placed on chemical containers?', 'text', 1, 'Focus on the core principle of Chemical Hazard Symbols.', '{"why":"Hazard information helps users choose appropriate precautions.","sol":"Step 1: Users need to know potential dangers before handling a chemical.\nStep 2: Symbols provide a quick warning about the nature of the hazard.","steps":["Step 1: Users need to know potential dangers before handling a chemical.","Step 2: Symbols provide a quick warning about the nature of the hazard."],"options":[],"conceptId":"chemistry_chemistry_foundations_chemical_hazard_symbols","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q3","subject":"chemistry","chapter":"chemistry_foundations","topic":"Chemical Hazard Symbols"}', 2),
  (2844, 712, 'A chemical container has a flammable warning. State one important precaution.', 'text', 1, 'Think about what could cause a flammable substance to ignite.', '{"why":"Removing ignition sources reduces the chance of the substance catching fire.","sol":"Step 1: Flammable substances can catch fire.\nStep 2: Flames and other ignition sources can start combustion.\nStep 3: Keep the chemical away from ignition sources.","steps":["Step 1: Flammable substances can catch fire.","Step 2: Flames and other ignition sources can start combustion.","Step 3: Keep the chemical away from ignition sources."],"options":[],"conceptId":"chemistry_chemistry_foundations_chemical_hazard_symbols","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q4","subject":"chemistry","chapter":"chemistry_foundations","topic":"Chemical Hazard Symbols"}', 3),
  (2845, 713, 'Why should a chemical label be read before using the chemical?', 'text', 1, 'Focus on the core principle of Safe Handling of Chemicals.', '{"why":"Correct handling depends on knowing the properties and hazards of the chemical.","sol":"Step 1: The label provides information about the substance.\nStep 2: It may include hazards and handling instructions.\nStep 3: Reading it helps the user select appropriate precautions.","steps":["Step 1: The label provides information about the substance.","Step 2: It may include hazards and handling instructions.","Step 3: Reading it helps the user select appropriate precautions."],"options":[],"conceptId":"chemistry_chemistry_foundations_safe_handling_of_chemicals","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q1","subject":"chemistry","chapter":"chemistry_foundations","topic":"Safe Handling of Chemicals"}', 0),
  (2846, 713, 'How should a student safely detect the smell of a chemical when instructed to do so?', 'text', 1, 'Focus on the core principle of Safe Handling of Chemicals.', '{"why":"Direct inhalation may expose the respiratory system to a high concentration of harmful vapour.","sol":"Step 1: Do not place the nose directly over the container.\nStep 2: Hold the container at a safe distance.\nStep 3: Gently waft vapour towards the nose.","steps":["Step 1: Do not place the nose directly over the container.","Step 2: Hold the container at a safe distance.","Step 3: Gently waft vapour towards the nose."],"options":[],"conceptId":"chemistry_chemistry_foundations_safe_handling_of_chemicals","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q2","subject":"chemistry","chapter":"chemistry_foundations","topic":"Safe Handling of Chemicals"}', 1),
  (2847, 713, 'Why should unused chemicals generally not be returned to their original containers?', 'text', 1, 'Focus on the core principle of Safe Handling of Chemicals.', '{"why":"Contamination of the main stock can make the chemical unsafe or unsuitable for later experiments.","sol":"Step 1: The unused chemical may have become contaminated.\nStep 2: Returning it could contaminate the entire stock.\nStep 3: Therefore unused chemicals should be disposed of according to laboratory instructions.","steps":["Step 1: The unused chemical may have become contaminated.","Step 2: Returning it could contaminate the entire stock.","Step 3: Therefore unused chemicals should be disposed of according to laboratory instructions."],"options":[],"conceptId":"chemistry_chemistry_foundations_safe_handling_of_chemicals","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q3","subject":"chemistry","chapter":"chemistry_foundations","topic":"Safe Handling of Chemicals"}', 2),
  (2848, 713, 'A learner smells a chemical by placing their nose directly above the container. Identify the mistake and give the correct method.', 'text', 1, 'Think about how vapour should reach the nose.', '{"why":"Wafting reduces direct exposure to concentrated vapour.","sol":"Step 1: Directly inhaling from the container is unsafe.\nStep 2: Harmful vapour may enter the respiratory system at high concentration.\nStep 3: The correct method is to waft vapour gently towards the nose when instructed.","steps":["Step 1: Directly inhaling from the container is unsafe.","Step 2: Harmful vapour may enter the respiratory system at high concentration.","Step 3: The correct method is to waft vapour gently towards the nose when instructed."],"options":[],"conceptId":"chemistry_chemistry_foundations_safe_handling_of_chemicals","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q4","subject":"chemistry","chapter":"chemistry_foundations","topic":"Safe Handling of Chemicals"}', 3),
  (2849, 714, 'Which apparatus is used to measure the mass of a substance?', 'text', 1, 'Focus on the core principle of Measuring Apparatus.', '{"why":"A balance measures mass.","sol":"Step 1: Identify the physical quantity: mass.\nStep 2: Select the apparatus designed to measure mass.","steps":["Step 1: Identify the physical quantity: mass.","Step 2: Select the apparatus designed to measure mass."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_apparatus","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q1","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Apparatus"}', 0),
  (2850, 714, 'Which apparatus is used to transfer a fixed accurate volume of liquid?', 'text', 1, 'Focus on the core principle of Measuring Apparatus.', '{"why":"A volumetric pipette is designed to transfer a specified fixed volume accurately.","sol":"Step 1: The volume must be fixed.\nStep 2: The apparatus must be designed for accurate transfer.\nStep 3: Select the pipette.","steps":["Step 1: The volume must be fixed.","Step 2: The apparatus must be designed for accurate transfer.","Step 3: Select the pipette."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_apparatus","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q2","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Apparatus"}', 1),
  (2851, 714, 'Which apparatus is commonly used to measure a variable volume accurately during titration?', 'text', 1, 'Focus on the core principle of Measuring Apparatus.', '{"why":"A burette allows a variable volume of solution to be delivered and measured accurately.","sol":"Step 1: Titration requires controlled delivery of a solution.\nStep 2: The volume delivered must be measured.\nStep 3: A burette is designed for this purpose.","steps":["Step 1: Titration requires controlled delivery of a solution.","Step 2: The volume delivered must be measured.","Step 3: A burette is designed for this purpose."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_apparatus","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q3","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Apparatus"}', 2),
  (2852, 714, 'A student needs to transfer exactly 25.0 cm³ of a solution into a flask. Which apparatus is most appropriate?', 'text', 1, 'The volume is fixed and accuracy is important.', '{"why":"A volumetric pipette is designed to transfer a fixed volume accurately.","sol":"Step 1: The required volume is fixed at 25.0 cm³.\nStep 2: High accuracy is required.\nStep 3: Use a 25.0 cm³ volumetric pipette.","steps":["Step 1: The required volume is fixed at 25.0 cm³.","Step 2: High accuracy is required.","Step 3: Use a 25.0 cm³ volumetric pipette."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_apparatus","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q4","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Apparatus"}', 3),
  (2853, 715, 'What is the function of a Bunsen burner?', 'text', 1, 'Focus on the core principle of Heating Apparatus.', '{"why":"It is a common laboratory source of heat.","sol":"Step 1: Identify the apparatus as a source of heat.\nStep 2: State what it provides.","steps":["Step 1: Identify the apparatus as a source of heat.","Step 2: State what it provides."],"options":[],"conceptId":"chemistry_chemistry_foundations_heating_apparatus","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q1","subject":"chemistry","chapter":"chemistry_foundations","topic":"Heating Apparatus"}', 0),
  (2854, 715, 'What is the function of wire gauze?', 'text', 1, 'Focus on the core principle of Heating Apparatus.', '{"why":"It provides a stable support and reduces direct concentration of heat on one part of the vessel.","sol":"Step 1: Identify its position between the heat source and supported vessel.\nStep 2: It supports the glassware.\nStep 3: It also helps distribute heat.","steps":["Step 1: Identify its position between the heat source and supported vessel.","Step 2: It supports the glassware.","Step 3: It also helps distribute heat."],"options":[],"conceptId":"chemistry_chemistry_foundations_heating_apparatus","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q2","subject":"chemistry","chapter":"chemistry_foundations","topic":"Heating Apparatus"}', 1),
  (2855, 715, 'What is a crucible used for?', 'text', 1, 'Focus on the core principle of Heating Apparatus.', '{"why":"Its material and shape allow it to withstand high temperatures.","sol":"Step 1: A crucible is made to withstand strong heating.\nStep 2: It holds small amounts of solid substances.","steps":["Step 1: A crucible is made to withstand strong heating.","Step 2: It holds small amounts of solid substances."],"options":[],"conceptId":"chemistry_chemistry_foundations_heating_apparatus","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q3","subject":"chemistry","chapter":"chemistry_foundations","topic":"Heating Apparatus"}', 2),
  (2856, 715, 'A student places a glass beaker directly on a Bunsen burner flame. Why might this be unsafe or unsuitable?', 'text', 1, 'Think about how heat reaches the glass.', '{"why":"Even distribution of heat reduces the risk of thermal shock.","sol":"Step 1: Direct heating can concentrate heat on one region.\nStep 2: Uneven heating can cause thermal stress.\nStep 3: The glass may crack or break.\nStep 4: Appropriate support and wire gauze should be used where required.","steps":["Step 1: Direct heating can concentrate heat on one region.","Step 2: Uneven heating can cause thermal stress.","Step 3: The glass may crack or break.","Step 4: Appropriate support and wire gauze should be used where required."],"options":[],"conceptId":"chemistry_chemistry_foundations_heating_apparatus","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q4","subject":"chemistry","chapter":"chemistry_foundations","topic":"Heating Apparatus"}', 3),
  (2857, 716, 'What is the function of filter paper?', 'text', 1, 'Focus on the core principle of Separation Apparatus.', '{"why":"Filtration separates components based mainly on particle size and insolubility.","sol":"Step 1: Filter paper contains very small pores.\nStep 2: Liquid can pass through the pores.\nStep 3: Insoluble solid particles are retained.","steps":["Step 1: Filter paper contains very small pores.","Step 2: Liquid can pass through the pores.","Step 3: Insoluble solid particles are retained."],"options":[],"conceptId":"chemistry_chemistry_foundations_separation_apparatus","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q1","subject":"chemistry","chapter":"chemistry_foundations","topic":"Separation Apparatus"}', 0),
  (2858, 716, 'What is the function of a condenser?', 'text', 1, 'Focus on the core principle of Separation Apparatus.', '{"why":"Condensation is the change from gas to liquid caused by cooling.","sol":"Step 1: During distillation, liquid is heated and forms vapour.\nStep 2: The vapour enters the condenser.\nStep 3: Cooling causes the vapour to condense into liquid.","steps":["Step 1: During distillation, liquid is heated and forms vapour.","Step 2: The vapour enters the condenser.","Step 3: Cooling causes the vapour to condense into liquid."],"options":[],"conceptId":"chemistry_chemistry_foundations_separation_apparatus","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q2","subject":"chemistry","chapter":"chemistry_foundations","topic":"Separation Apparatus"}', 1),
  (2859, 716, 'What is a separating funnel used to separate?', 'text', 1, 'Focus on the core principle of Separation Apparatus.', '{"why":"Immiscible liquids form separate layers that can be drained separately.","sol":"Step 1: Identify the type of mixture.\nStep 2: The liquids must not mix with each other.\nStep 3: The liquids form separate layers because of differences in density.","steps":["Step 1: Identify the type of mixture.","Step 2: The liquids must not mix with each other.","Step 3: The liquids form separate layers because of differences in density."],"options":[],"conceptId":"chemistry_chemistry_foundations_separation_apparatus","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q3","subject":"chemistry","chapter":"chemistry_foundations","topic":"Separation Apparatus"}', 2),
  (2860, 716, 'A mixture contains sand and water. Which apparatus is required for the first separation step?', 'text', 1, 'Sand is an insoluble solid.', '{"why":"The filter paper retains the sand while water passes through.","sol":"Step 1: Sand is insoluble in water.\nStep 2: An insoluble solid can be separated from a liquid by filtration.\nStep 3: Use a filter funnel and filter paper.","steps":["Step 1: Sand is insoluble in water.","Step 2: An insoluble solid can be separated from a liquid by filtration.","Step 3: Use a filter funnel and filter paper."],"options":[],"conceptId":"chemistry_chemistry_foundations_separation_apparatus","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q4","subject":"chemistry","chapter":"chemistry_foundations","topic":"Separation Apparatus"}', 3),
  (2861, 717, 'What is the function of a burette in titration?', 'text', 1, 'Focus on the core principle of Apparatus Used in Titration.', '{"why":"Its graduated scale and tap allow controlled measurement of the volume delivered.","sol":"Step 1: A titration requires a variable volume of solution.\nStep 2: The volume delivered must be measured accurately.\nStep 3: The burette provides controlled delivery and measurement.","steps":["Step 1: A titration requires a variable volume of solution.","Step 2: The volume delivered must be measured accurately.","Step 3: The burette provides controlled delivery and measurement."],"options":[],"conceptId":"chemistry_chemistry_foundations_apparatus_used_in_titration","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q1","subject":"chemistry","chapter":"chemistry_foundations","topic":"Apparatus Used in Titration"}', 0),
  (2862, 717, 'What is the function of a pipette in titration?', 'text', 1, 'Focus on the core principle of Apparatus Used in Titration.', '{"why":"The pipette provides a more accurate fixed volume than an ordinary measuring cylinder.","sol":"Step 1: A known fixed volume of solution is required.\nStep 2: A pipette is designed to transfer a fixed volume accurately.","steps":["Step 1: A known fixed volume of solution is required.","Step 2: A pipette is designed to transfer a fixed volume accurately."],"options":[],"conceptId":"chemistry_chemistry_foundations_apparatus_used_in_titration","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q2","subject":"chemistry","chapter":"chemistry_foundations","topic":"Apparatus Used in Titration"}', 1),
  (2863, 717, 'Why is a conical flask commonly used in titration?', 'text', 1, 'Focus on the core principle of Apparatus Used in Titration.', '{"why":"Its shape is suitable for mixing solutions during addition from the burette.","sol":"Step 1: The flask must contain the solution being titrated.\nStep 2: The contents must be mixed without easily spilling.\nStep 3: The shape allows the solution to be swirled safely.","steps":["Step 1: The flask must contain the solution being titrated.","Step 2: The contents must be mixed without easily spilling.","Step 3: The shape allows the solution to be swirled safely."],"options":[],"conceptId":"chemistry_chemistry_foundations_apparatus_used_in_titration","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q3","subject":"chemistry","chapter":"chemistry_foundations","topic":"Apparatus Used in Titration"}', 2),
  (2864, 717, 'A learner leaves a funnel in the top of the burette while taking a burette reading. Why can this cause a problem?', 'text', 1, 'Think about whether liquid left in the funnel could enter the burette.', '{"why":"The burette reading must represent only the controlled volume delivered through the tap.","sol":"Step 1: Liquid may remain inside the funnel.\nStep 2: That liquid could enter the burette unexpectedly.\nStep 3: This would change the amount of solution delivered and affect the reading.","steps":["Step 1: Liquid may remain inside the funnel.","Step 2: That liquid could enter the burette unexpectedly.","Step 3: This would change the amount of solution delivered and affect the reading."],"options":[],"conceptId":"chemistry_chemistry_foundations_apparatus_used_in_titration","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q4","subject":"chemistry","chapter":"chemistry_foundations","topic":"Apparatus Used in Titration"}', 3),
  (2865, 718, 'A container has a mass of 25.0 g. The container and a chemical together have a mass of 43.5 g. Calculate the mass of the chemical.', 'text', 1, 'Focus on the core principle of Measuring Mass.', '{"why":"The mass of the chemical is the combined mass minus the mass of the empty container.","sol":"Step 1: Write the combined mass: 43.5 g.\nStep 2: Subtract the mass of the empty container: 25.0 g.\nStep 3: 43.5 − 25.0 = 18.5 g.","steps":["Step 1: Write the combined mass: 43.5 g.","Step 2: Subtract the mass of the empty container: 25.0 g.","Step 3: 43.5 − 25.0 = 18.5 g."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_mass","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q1","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Mass"}', 0),
  (2866, 718, 'Convert 2.5 kg to grams.', 'text', 1, 'Focus on the core principle of Measuring Mass.', '{"why":"Each kilogram contains 1000 grams.","sol":"Step 1: 1 kg = 1000 g.\nStep 2: Multiply 2.5 by 1000.\nStep 3: 2.5 × 1000 = 2500 g.","steps":["Step 1: 1 kg = 1000 g.","Step 2: Multiply 2.5 by 1000.","Step 3: 2.5 × 1000 = 2500 g."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_mass","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q2","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Mass"}', 1),
  (2867, 718, 'Convert 750 mg to grams.', 'text', 1, 'Focus on the core principle of Measuring Mass.', '{"why":"Milligrams are smaller than grams, so the numerical value decreases when converting mg to g.","sol":"Step 1: 1 g = 1000 mg.\nStep 2: Divide 750 mg by 1000.\nStep 3: 750 ÷ 1000 = 0.750 g.","steps":["Step 1: 1 g = 1000 mg.","Step 2: Divide 750 mg by 1000.","Step 3: 750 ÷ 1000 = 0.750 g."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_mass","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q3","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Mass"}', 2),
  (2868, 718, 'A student records the mass of a container and chemical as 58.2 g but forgets to subtract the empty container mass of 20.0 g. What error has been made?', 'text', 1, 'The required quantity is the mass of the chemical alone.', '{"why":"The container''s mass must be removed from the combined measurement.","sol":"Step 1: The recorded 58.2 g includes both the container and chemical.\nStep 2: The container has a mass of 20.0 g.\nStep 3: Subtract 20.0 g from 58.2 g.\nStep 4: 58.2 − 20.0 = 38.2 g.","steps":["Step 1: The recorded 58.2 g includes both the container and chemical.","Step 2: The container has a mass of 20.0 g.","Step 3: Subtract 20.0 g from 58.2 g.","Step 4: 58.2 − 20.0 = 38.2 g."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_mass","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q4","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Mass"}', 3),
  (2869, 719, 'Convert 2.5 L to mL.', 'text', 1, 'Focus on the core principle of Measuring Volume.', '{"why":"Each litre contains 1000 millilitres.","sol":"Step 1: 1 L = 1000 mL.\nStep 2: Multiply 2.5 by 1000.\nStep 3: 2.5 × 1000 = 2500 mL.","steps":["Step 1: 1 L = 1000 mL.","Step 2: Multiply 2.5 by 1000.","Step 3: 2.5 × 1000 = 2500 mL."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_volume","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q1","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Volume"}', 0),
  (2870, 719, 'Convert 450 mL to cm³.', 'text', 1, 'Focus on the core principle of Measuring Volume.', '{"why":"A millilitre and a cubic centimetre represent equal volumes.","sol":"Step 1: Use the relationship 1 mL = 1 cm³.\nStep 2: Therefore the numerical value remains unchanged.","steps":["Step 1: Use the relationship 1 mL = 1 cm³.","Step 2: Therefore the numerical value remains unchanged."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_volume","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q2","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Volume"}', 1),
  (2871, 719, 'A measuring cylinder contains 75 mL of water. Express this volume in litres.', 'text', 1, 'Focus on the core principle of Measuring Volume.', '{"why":"To convert millilitres to litres, divide by 1000.","sol":"Step 1: 1 L = 1000 mL.\nStep 2: Divide 75 mL by 1000.\nStep 3: 75 ÷ 1000 = 0.075 L.","steps":["Step 1: 1 L = 1000 mL.","Step 2: Divide 75 mL by 1000.","Step 3: 75 ÷ 1000 = 0.075 L."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_volume","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q3","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Volume"}', 2),
  (2872, 719, 'A learner reads the liquid level from above the measuring cylinder rather than at eye level. Why can this produce an inaccurate result?', 'text', 1, 'Think about the position of the eye relative to the scale.', '{"why":"Viewing the scale from above or below changes the apparent position of the liquid level.","sol":"Step 1: The apparent position of the liquid changes when viewed from an angle.\nStep 2: This causes parallax error.\nStep 3: The eye should be level with the meniscus when taking the reading.","steps":["Step 1: The apparent position of the liquid changes when viewed from an angle.","Step 2: This causes parallax error.","Step 3: The eye should be level with the meniscus when taking the reading."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_volume","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q4","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Volume"}', 3),
  (2873, 720, 'A solution has an initial temperature of 22°C and a final temperature of 35°C. Calculate the temperature change.', 'text', 1, 'Focus on the core principle of Measuring Temperature.', '{"why":"Temperature change is calculated by subtracting the initial temperature from the final temperature.","sol":"Step 1: Write the final temperature: 35°C.\nStep 2: Write the initial temperature: 22°C.\nStep 3: Subtract initial from final: 35 − 22 = 13°C.","steps":["Step 1: Write the final temperature: 35°C.","Step 2: Write the initial temperature: 22°C.","Step 3: Subtract initial from final: 35 − 22 = 13°C."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_temperature","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q1","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Temperature"}', 0),
  (2874, 720, 'A substance cools from 80°C to 45°C. Calculate the decrease in temperature.', 'text', 1, 'Focus on the core principle of Measuring Temperature.', '{"why":"For a cooling process, the decrease is the initial temperature minus the final temperature.","sol":"Step 1: Initial temperature = 80°C.\nStep 2: Final temperature = 45°C.\nStep 3: Calculate the decrease: 80 − 45 = 35°C.","steps":["Step 1: Initial temperature = 80°C.","Step 2: Final temperature = 45°C.","Step 3: Calculate the decrease: 80 − 45 = 35°C."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_temperature","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q2","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Temperature"}', 1),
  (2875, 720, 'Why should a thermometer reading be taken after the temperature has become steady?', 'text', 1, 'Focus on the core principle of Measuring Temperature.', '{"why":"A changing thermometer reading has not yet reached the temperature of the substance.","sol":"Step 1: Immediately after placing a thermometer in a substance, its reading may still be changing.\nStep 2: A changing reading does not represent the stable temperature.\nStep 3: Wait until the reading becomes steady before recording it.","steps":["Step 1: Immediately after placing a thermometer in a substance, its reading may still be changing.","Step 2: A changing reading does not represent the stable temperature.","Step 3: Wait until the reading becomes steady before recording it."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_temperature","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q3","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Temperature"}', 2),
  (2876, 720, 'A student places the thermometer bulb against the bottom of a heated container. Explain why this can give an inaccurate temperature.', 'text', 1, 'Think about what the thermometer is actually touching.', '{"why":"The thermometer should measure the substance itself rather than a potentially hotter or colder part of the apparatus.","sol":"Step 1: The container''s bottom may be hotter than the substance.\nStep 2: The thermometer can therefore measure the temperature of the hot surface rather than the substance.\nStep 3: Keep the sensing part properly immersed without touching the container where appropriate.","steps":["Step 1: The container''s bottom may be hotter than the substance.","Step 2: The thermometer can therefore measure the temperature of the hot surface rather than the substance.","Step 3: Keep the sensing part properly immersed without touching the container where appropriate."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_temperature","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q4","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Temperature"}', 3),
  (2877, 721, 'A scale runs from 0 cm³ to 50 cm³ and has 10 equal divisions. What is the value of each division?', 'text', 1, 'Focus on the core principle of Reading Measuring Instruments.', '{"why":"The value of one division is the total scale range divided by the number of equal divisions.","sol":"Step 1: Find the total change in the scale: 50 − 0 = 50 cm³.\nStep 2: Count the divisions: 10.\nStep 3: Divide 50 by 10.\nStep 4: 50 ÷ 10 = 5 cm³.","steps":["Step 1: Find the total change in the scale: 50 − 0 = 50 cm³.","Step 2: Count the divisions: 10.","Step 3: Divide 50 by 10.","Step 4: 50 ÷ 10 = 5 cm³."],"options":[],"conceptId":"chemistry_chemistry_foundations_reading_measuring_instruments","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q1","subject":"chemistry","chapter":"chemistry_foundations","topic":"Reading Measuring Instruments"}', 0),
  (2878, 721, 'A measuring instrument has markings at 20, 30 and 40. There are five equal intervals between 20 and 30. What is the value of each interval?', 'text', 1, 'Focus on the core principle of Reading Measuring Instruments.', '{"why":"The difference between two labelled marks is divided by the number of equal intervals between them.","sol":"Step 1: Find the difference between 30 and 20: 10.\nStep 2: There are 5 equal intervals.\nStep 3: 10 ÷ 5 = 2.","steps":["Step 1: Find the difference between 30 and 20: 10.","Step 2: There are 5 equal intervals.","Step 3: 10 ÷ 5 = 2."],"options":[],"conceptId":"chemistry_chemistry_foundations_reading_measuring_instruments","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q2","subject":"chemistry","chapter":"chemistry_foundations","topic":"Reading Measuring Instruments"}', 1),
  (2879, 721, 'Why must the unit be included when recording a measurement?', 'text', 1, 'Focus on the core principle of Reading Measuring Instruments.', '{"why":"For example, 25 could mean 25 mL, 25 cm³, 25 g or another unit.","sol":"Step 1: A numerical value alone does not identify the quantity''s unit.\nStep 2: The same number can represent different quantities depending on the unit.\nStep 3: Therefore the numerical value and unit should be recorded together.","steps":["Step 1: A numerical value alone does not identify the quantity''s unit.","Step 2: The same number can represent different quantities depending on the unit.","Step 3: Therefore the numerical value and unit should be recorded together."],"options":[],"conceptId":"chemistry_chemistry_foundations_reading_measuring_instruments","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q3","subject":"chemistry","chapter":"chemistry_foundations","topic":"Reading Measuring Instruments"}', 2),
  (2880, 721, 'A learner reads a liquid level as 26 mL by looking from above the meniscus. The correct eye-level reading is 24 mL. What type of error has occurred?', 'text', 1, 'Think about an incorrect viewing angle.', '{"why":"Parallax occurs when an instrument is viewed from an incorrect angle.","sol":"Step 1: The learner did not place the eye at the correct level.\nStep 2: The apparent position of the meniscus changed.\nStep 3: This is called parallax error.","steps":["Step 1: The learner did not place the eye at the correct level.","Step 2: The apparent position of the meniscus changed.","Step 3: This is called parallax error."],"options":[],"conceptId":"chemistry_chemistry_foundations_reading_measuring_instruments","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q4","subject":"chemistry","chapter":"chemistry_foundations","topic":"Reading Measuring Instruments"}', 3),
  (2881, 722, 'Define matter and state its two essential characteristics.', 'text', 1, 'Give the scientific definition rather than just examples of matter.', '{"why":"Mass and occupied space are both required by the definition. Naming only one characteristic gives an incomplete definition.","sol":"Step 1: Recall the definition of matter.\nStep 2: Identify the two characteristics that every example of matter must have.","steps":["Step 1: Recall the definition of matter.","Step 2: Identify the two characteristics that every example of matter must have."],"options":[],"conceptId":"chemistry_matter_separation_meaning_of_matter","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Meaning of Matter"}', 0),
  (2882, 722, 'A learner claims that air is not matter because it cannot normally be seen. Explain why this claim is incorrect.', 'text', 1, 'Consider the mass of air and what happens when air is enclosed in a balloon.', '{"why":"Matter does not have to be visible. The two defining characteristics are mass and occupied space.","sol":"Step 1: Recognise that visibility is not part of the definition of matter.\nStep 2: Air has mass.\nStep 3: Air occupies space, as demonstrated when it fills and expands a balloon.","steps":["Step 1: Recognise that visibility is not part of the definition of matter.","Step 2: Air has mass.","Step 3: Air occupies space, as demonstrated when it fills and expands a balloon."],"options":[],"conceptId":"chemistry_matter_separation_meaning_of_matter","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Meaning of Matter"}', 1),
  (2883, 722, 'A stone has a mass of 400 g and occupies space. Explain why it is classified as matter.', 'text', 1, 'Apply both parts of the definition.', '{"why":"The stone satisfies both essential characteristics of matter.","sol":"Step 1: The stone has mass: 400 g.\nStep 2: The stone occupies space.\nStep 3: Compare these observations with the definition of matter.","steps":["Step 1: The stone has mass: 400 g.","Step 2: The stone occupies space.","Step 3: Compare these observations with the definition of matter."],"options":[],"conceptId":"chemistry_matter_separation_meaning_of_matter","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Meaning of Matter"}', 2),
  (2884, 722, 'A learner says that light is matter because a bulb produces it. Explain the mistake.', 'text', 1, 'Distinguish the physical object from the energy it emits.', '{"why":"An object does not make everything it produces matter. Light is energy, whereas the bulb is a material object.","sol":"Step 1: Identify the bulb as a physical object with mass and volume.\nStep 2: Identify the light as energy emitted by the bulb.\nStep 3: Apply the definition to the light itself rather than to its source.","steps":["Step 1: Identify the bulb as a physical object with mass and volume.","Step 2: Identify the light as energy emitted by the bulb.","Step 3: Apply the definition to the light itself rather than to its source."],"options":[],"conceptId":"chemistry_matter_separation_meaning_of_matter","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Meaning of Matter"}', 3),
  (2885, 722, 'Explain why mass alone is not the complete scientific definition of matter. Use one example in your answer.', 'text', 1, 'Name the second required characteristic and apply it to a familiar object.', '{"why":"A complete definition must include both mass and occupied space.","sol":"Step 1: State that matter must have mass.\nStep 2: State that matter must also occupy space.\nStep 3: Use an object such as water, a stone or cooking oil to illustrate both characteristics.","steps":["Step 1: State that matter must have mass.","Step 2: State that matter must also occupy space.","Step 3: Use an object such as water, a stone or cooking oil to illustrate both characteristics."],"options":[],"conceptId":"chemistry_matter_separation_meaning_of_matter","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q5","subject":"chemistry","chapter":"matter_separation","topic":"Meaning of Matter"}', 4),
  (2886, 723, 'Define a physical property and explain the feature that distinguishes it from a chemical property.', 'text', 1, 'Focus on whether the substance becomes a different substance.', '{"why":"The key distinction is that observing or measuring a physical property does not require a chemical change.","sol":"Step 1: State that a physical property can be observed or measured.\nStep 2: Explain that the substance''s chemical identity is not changed by observing or measuring it.","steps":["Step 1: State that a physical property can be observed or measured.","Step 2: Explain that the substance''s chemical identity is not changed by observing or measuring it."],"options":[],"conceptId":"chemistry_matter_separation_physical_properties","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Physical Properties"}', 0),
  (2887, 723, 'A sample has a mass of 80 g and a volume of 40 cm³. Calculate its density and give the correct unit.', 'text', 1, 'Density = mass ÷ volume.', '{"why":"Density compares the mass of a sample with its volume. The unit is g/cm³ because mass is measured in grams and volume in cubic centimetres.","sol":"Step 1: Write the formula: density = mass ÷ volume.\nStep 2: Substitute the values: density = 80 g ÷ 40 cm³.\nStep 3: Calculate: 80 ÷ 40 = 2.\nStep 4: Combine the result with the unit: g/cm³.","steps":["Step 1: Write the formula: density = mass ÷ volume.","Step 2: Substitute the values: density = 80 g ÷ 40 cm³.","Step 3: Calculate: 80 ÷ 40 = 2.","Step 4: Combine the result with the unit: g/cm³."],"options":[],"conceptId":"chemistry_matter_separation_physical_properties","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Physical Properties"}', 1),
  (2888, 723, 'A learner records two observations: a substance is yellow and it dissolves in water. Name the two physical properties and explain your choices.', 'text', 1, 'One observation describes appearance; the other describes behaviour in a solvent without necessarily forming a new substance.', '{"why":"Colour describes appearance, while solubility describes how a substance dissolves in a specified solvent.","sol":"Step 1: Identify yellow as a description of colour.\nStep 2: Identify dissolving in water as solubility in water.\nStep 3: Check that neither observation alone establishes a chemical change.","steps":["Step 1: Identify yellow as a description of colour.","Step 2: Identify dissolving in water as solubility in water.","Step 3: Check that neither observation alone establishes a chemical change."],"options":[],"conceptId":"chemistry_matter_separation_physical_properties","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Physical Properties"}', 2),
  (2889, 723, 'Explain why measuring the melting point of a substance is a physical measurement.', 'text', 1, 'Consider what happens to the substance''s chemical identity during melting.', '{"why":"A change in physical state does not necessarily change chemical identity.","sol":"Step 1: Identify melting point as the temperature at which a solid changes to a liquid under specified pressure.\nStep 2: Recognise that melting changes the physical state.\nStep 3: Distinguish a change of state from the formation of a different substance.","steps":["Step 1: Identify melting point as the temperature at which a solid changes to a liquid under specified pressure.","Step 2: Recognise that melting changes the physical state.","Step 3: Distinguish a change of state from the formation of a different substance."],"options":[],"conceptId":"chemistry_matter_separation_physical_properties","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Physical Properties"}', 3),
  (2890, 723, 'Explain the difference between mass and density. Use a sample with a mass of 30 g and a volume of 10 cm³ to illustrate your answer.', 'text', 1, 'Mass is measured directly; density is calculated using both mass and volume.', '{"why":"Mass and density are related but are not the same quantity. Density requires both mass and volume.","sol":"Step 1: Mass tells us how much matter the sample contains.\nStep 2: Density is calculated by dividing mass by volume.\nStep 3: Substitute: density = 30 g ÷ 10 cm³.\nStep 4: Calculate the density and state its unit.","steps":["Step 1: Mass tells us how much matter the sample contains.","Step 2: Density is calculated by dividing mass by volume.","Step 3: Substitute: density = 30 g ÷ 10 cm³.","Step 4: Calculate the density and state its unit."],"options":[],"conceptId":"chemistry_matter_separation_physical_properties","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q5","subject":"chemistry","chapter":"matter_separation","topic":"Physical Properties"}', 4),
  (2891, 724, 'Define a chemical property and explain how it differs from a physical property.', 'text', 1, 'Focus on a substance''s ability to react and form different substances.', '{"why":"The distinction is whether the property concerns chemical reactivity and the formation of different substances.","sol":"Step 1: State that a chemical property describes how a substance can undergo chemical change.\nStep 2: Explain that the change produces one or more different substances.\nStep 3: Contrast this with observing or measuring a physical property without changing chemical identity.","steps":["Step 1: State that a chemical property describes how a substance can undergo chemical change.","Step 2: Explain that the change produces one or more different substances.","Step 3: Contrast this with observing or measuring a physical property without changing chemical identity."],"options":[],"conceptId":"chemistry_matter_separation_chemical_properties","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Chemical Properties"}', 0),
  (2892, 724, 'Flammability is the ability of a substance to burn. Explain why flammability is a chemical property rather than a physical property.', 'text', 1, 'Consider what burning does to the substance.', '{"why":"A visible flame is not the reason for the classification. The reason is the chemical change associated with burning.","sol":"Step 1: Identify flammability as the ability to burn.\nStep 2: Recognise that burning involves a chemical reaction.\nStep 3: Explain that the reaction produces substances different from the original material.","steps":["Step 1: Identify flammability as the ability to burn.","Step 2: Recognise that burning involves a chemical reaction.","Step 3: Explain that the reaction produces substances different from the original material."],"options":[],"conceptId":"chemistry_matter_separation_chemical_properties","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Chemical Properties"}', 1),
  (2893, 724, 'Iron can react with oxygen to form rust. Identify the chemical property and the chemical change, and explain the difference.', 'text', 1, 'One describes iron''s ability; the other describes what actually happens.', '{"why":"A chemical property describes what a substance can do chemically; a chemical change is the process that occurs.","sol":"Step 1: Identify reactivity with oxygen as the property.\nStep 2: Identify the formation of rust as the chemical change.\nStep 3: Explain that the property describes a tendency to react, whereas the change is the actual reaction.","steps":["Step 1: Identify reactivity with oxygen as the property.","Step 2: Identify the formation of rust as the chemical change.","Step 3: Explain that the property describes a tendency to react, whereas the change is the actual reaction."],"options":[],"conceptId":"chemistry_matter_separation_chemical_properties","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Chemical Properties"}', 2),
  (2894, 724, 'A substance has a density of 4 g/cm³ and is flammable. Classify both properties and justify each classification.', 'text', 1, 'Ask whether measuring density changes the substance and whether burning forms different substances.', '{"why":"The two properties are classified by the type of change involved, not by whether they can be described or observed.","sol":"Step 1: Density is measured using mass divided by volume.\nStep 2: Measuring density does not require the substance to become a different substance.\nStep 3: Flammability describes the ability to burn through a chemical reaction.","steps":["Step 1: Density is measured using mass divided by volume.","Step 2: Measuring density does not require the substance to become a different substance.","Step 3: Flammability describes the ability to burn through a chemical reaction."],"options":[],"conceptId":"chemistry_matter_separation_chemical_properties","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Chemical Properties"}', 3),
  (2895, 724, 'A learner observes that a material changes colour and concludes that a chemical reaction must have occurred. Explain why this conclusion is not always justified, and state what the learner should consider.', 'text', 1, 'A visible observation may have more than one explanation.', '{"why":"Observations must be interpreted in context. A possible sign of a reaction is not automatically conclusive proof.","sol":"Step 1: Recognise that a colour change can be evidence of a chemical reaction.\nStep 2: Recognise that appearance can also change for physical reasons, depending on the circumstances.\nStep 3: Consider whether the original substance has formed different substances and look for supporting evidence.","steps":["Step 1: Recognise that a colour change can be evidence of a chemical reaction.","Step 2: Recognise that appearance can also change for physical reasons, depending on the circumstances.","Step 3: Consider whether the original substance has formed different substances and look for supporting evidence."],"options":[],"conceptId":"chemistry_matter_separation_chemical_properties","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q5","subject":"chemistry","chapter":"matter_separation","topic":"Chemical Properties"}', 4),
  (2896, 725, 'Define a solid and state two characteristics that distinguish it as a state of matter.', 'text', 1, 'Consider its shape and the amount of space it occupies.', '{"why":"A solid retains its own shape and occupies a particular volume under ordinary conditions.","sol":"Step 1: State that a solid is a state of matter.\nStep 2: Identify its definite shape.\nStep 3: Identify its definite volume.","steps":["Step 1: State that a solid is a state of matter.","Step 2: Identify its definite shape.","Step 3: Identify its definite volume."],"options":[],"conceptId":"chemistry_matter_separation_solids","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Solids"}', 0),
  (2897, 725, 'Explain why a solid metal block retains its shape when placed in a differently shaped container.', 'text', 1, 'Think about the positions and movement of its particles.', '{"why":"The arrangement and movement of solid particles explain why a solid keeps its own shape.","sol":"Step 1: The particles of a solid occupy relatively fixed positions.\nStep 2: They vibrate but do not freely move past one another.\nStep 3: Therefore, the block does not flow to fit the container.","steps":["Step 1: The particles of a solid occupy relatively fixed positions.","Step 2: They vibrate but do not freely move past one another.","Step 3: Therefore, the block does not flow to fit the container."],"options":[],"conceptId":"chemistry_matter_separation_solids","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Solids"}', 1),
  (2898, 725, 'A learner claims that particles in a solid are motionless. Explain why the claim is incorrect.', 'text', 1, 'Distinguish between moving freely and vibrating in one position.', '{"why":"Fixed positions do not mean zero movement.","sol":"Step 1: Recognise that solid particles occupy relatively fixed positions.\nStep 2: Recall that the particles still possess motion.\nStep 3: Identify this motion as vibration about their positions.","steps":["Step 1: Recognise that solid particles occupy relatively fixed positions.","Step 2: Recall that the particles still possess motion.","Step 3: Identify this motion as vibration about their positions."],"options":[],"conceptId":"chemistry_matter_separation_solids","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Solids"}', 2),
  (2899, 725, 'Explain why most solids are difficult to compress.', 'text', 1, 'Consider how closely the particles are packed.', '{"why":"Compressibility depends partly on how much space between particles can be reduced.","sol":"Step 1: Solid particles are closely packed.\nStep 2: There is little empty space between neighbouring particles.\nStep 3: Applying pressure therefore produces little reduction in volume.","steps":["Step 1: Solid particles are closely packed.","Step 2: There is little empty space between neighbouring particles.","Step 3: Applying pressure therefore produces little reduction in volume."],"options":[],"conceptId":"chemistry_matter_separation_solids","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Solids"}', 3),
  (2900, 725, 'A pile of sand changes shape when poured from a bucket onto the ground. Explain why this does not mean that sand grains are liquid.', 'text', 1, 'Distinguish the shape of a pile from the state of each grain.', '{"why":"The overall shape of a collection of separate solid particles does not determine the state of each particle.","sol":"Step 1: Identify the sand grains as individual solid particles.\nStep 2: Recognise that the grains can move relative to one another as the pile is poured.\nStep 3: Explain that each grain retains its own solid form.","steps":["Step 1: Identify the sand grains as individual solid particles.","Step 2: Recognise that the grains can move relative to one another as the pile is poured.","Step 3: Explain that each grain retains its own solid form."],"options":[],"conceptId":"chemistry_matter_separation_solids","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q5","subject":"chemistry","chapter":"matter_separation","topic":"Solids"}', 4),
  (2901, 726, 'Define a liquid and state how its shape and volume behave under ordinary conditions.', 'text', 1, 'One of these is definite; the other depends on the container.', '{"why":"The particles can move past one another, allowing the liquid to change shape while remaining close together.","sol":"Step 1: Define a liquid as a state of matter.\nStep 2: State that it has a definite volume.\nStep 3: State that it takes the shape of its container.","steps":["Step 1: Define a liquid as a state of matter.","Step 2: State that it has a definite volume.","Step 3: State that it takes the shape of its container."],"options":[],"conceptId":"chemistry_matter_separation_liquids","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Liquids"}', 0),
  (2902, 726, 'A learner transfers 75 cm³ of water into another container. Assuming none is lost, what volume should the water occupy, and why?', 'text', 1, 'Changing containers changes shape, not normally the volume of a fixed amount of liquid.', '{"why":"Transferring the same amount of liquid to a different container changes its shape, not normally its volume.","sol":"Step 1: Start with the original volume of 75 cm³.\nStep 2: Recognise that water is a liquid with a definite volume under ordinary conditions.\nStep 3: Assume no water is lost and conditions remain unchanged.","steps":["Step 1: Start with the original volume of 75 cm³.","Step 2: Recognise that water is a liquid with a definite volume under ordinary conditions.","Step 3: Assume no water is lost and conditions remain unchanged."],"options":[],"conceptId":"chemistry_matter_separation_liquids","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Liquids"}', 1),
  (2903, 726, 'Explain why a liquid can flow but a solid normally retains its own shape.', 'text', 1, 'Compare how the particles move in each state.', '{"why":"The differences in particle movement explain the different macroscopic properties.","sol":"Step 1: Liquid particles can move past one another.\nStep 2: Solid particles vibrate about relatively fixed positions.\nStep 3: Relate the different particle movements to flow and shape.","steps":["Step 1: Liquid particles can move past one another.","Step 2: Solid particles vibrate about relatively fixed positions.","Step 3: Relate the different particle movements to flow and shape."],"options":[],"conceptId":"chemistry_matter_separation_liquids","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Liquids"}', 2),
  (2904, 726, 'A student says that cooking oil has no definite volume because it spreads across the bottom of a container. Correct the statement.', 'text', 1, 'Spreading changes the occupied shape, not necessarily the amount of oil.', '{"why":"The shape of a liquid depends on its container, whereas its volume is approximately constant for a fixed amount under ordinary conditions.","sol":"Step 1: Identify cooking oil as a liquid.\nStep 2: Explain that it spreads to take the shape of the container.\nStep 3: State that a fixed amount of oil retains approximately the same volume under ordinary conditions.","steps":["Step 1: Identify cooking oil as a liquid.","Step 2: Explain that it spreads to take the shape of the container.","Step 3: State that a fixed amount of oil retains approximately the same volume under ordinary conditions."],"options":[],"conceptId":"chemistry_matter_separation_liquids","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Liquids"}', 3),
  (2905, 726, 'State two properties of liquids and explain how the movement and spacing of their particles account for them.', 'text', 1, 'Use flow, shape, volume or compressibility.', '{"why":"Particle movement explains the ability to change shape, while close spacing helps explain why the volume remains approximately constant.","sol":"Step 1: Choose one property, such as the ability to flow.\nStep 2: Relate flow to particles moving past one another.\nStep 3: Choose another property, such as definite volume.\nStep 4: Relate definite volume to particles remaining relatively close together.","steps":["Step 1: Choose one property, such as the ability to flow.","Step 2: Relate flow to particles moving past one another.","Step 3: Choose another property, such as definite volume.","Step 4: Relate definite volume to particles remaining relatively close together."],"options":[],"conceptId":"chemistry_matter_separation_liquids","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q5","subject":"chemistry","chapter":"matter_separation","topic":"Liquids"}', 4),
  (2906, 727, 'Define a gas and state why it has neither a definite shape nor a definite volume.', 'text', 1, 'Consider the spacing and movement of gas particles.', '{"why":"A gas takes the shape and volume of the available space rather than maintaining its own fixed shape and volume.","sol":"Step 1: Define a gas as a state of matter.\nStep 2: Explain that gas particles move freely.\nStep 3: Relate their movement to the shape and volume of the available space.","steps":["Step 1: Define a gas as a state of matter.","Step 2: Explain that gas particles move freely.","Step 3: Relate their movement to the shape and volume of the available space."],"options":[],"conceptId":"chemistry_matter_separation_gases","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Gases"}', 0),
  (2907, 727, 'A gas occupies 800 cm³ and is compressed to 500 cm³. Calculate the decrease in volume.', 'text', 1, 'Subtract the final volume from the initial volume.', '{"why":"The change in volume is found by subtracting the final volume from the initial volume.","sol":"Step 1: Initial volume = 800 cm³.\nStep 2: Final volume = 500 cm³.\nStep 3: Decrease = 800 − 500 = 300 cm³.","steps":["Step 1: Initial volume = 800 cm³.","Step 2: Final volume = 500 cm³.","Step 3: Decrease = 800 − 500 = 300 cm³."],"options":[],"conceptId":"chemistry_matter_separation_gases","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Gases"}', 1),
  (2908, 727, 'Explain why a gas can usually be compressed much more easily than a solid.', 'text', 1, 'Compare the empty space between the particles.', '{"why":"The difference in particle spacing explains the difference in compressibility.","sol":"Step 1: Gas particles are widely separated.\nStep 2: There is substantial space between them.\nStep 3: Pressure can reduce the space occupied by the gas particles.\nStep 4: Solid particles are already closely packed, so there is little space to reduce.","steps":["Step 1: Gas particles are widely separated.","Step 2: There is substantial space between them.","Step 3: Pressure can reduce the space occupied by the gas particles.","Step 4: Solid particles are already closely packed, so there is little space to reduce."],"options":[],"conceptId":"chemistry_matter_separation_gases","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Gases"}', 2),
  (2909, 727, 'A learner releases a small amount of gas into a much larger container. Explain why the gas can occupy the larger available space.', 'text', 1, 'Consider the ability of gas particles to move in different directions.', '{"why":"Gases do not have a fixed volume independent of their surroundings.","sol":"Step 1: Gas particles move freely in different directions.\nStep 2: They spread through the available space.\nStep 3: The larger container provides more space for the gas to occupy.","steps":["Step 1: Gas particles move freely in different directions.","Step 2: They spread through the available space.","Step 3: The larger container provides more space for the gas to occupy."],"options":[],"conceptId":"chemistry_matter_separation_gases","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Gases"}', 3),
  (2910, 727, 'Explain the difference between the volume of a sealed gas container and the definite volume of a liquid in a container.', 'text', 1, 'Ask whether the substance itself would occupy more space if given a larger container.', '{"why":"Gases have no definite volume, whereas liquids have a definite volume but no definite shape.","sol":"Step 1: A gas expands to occupy the available space.\nStep 2: The volume of a gas depends on its container and conditions.\nStep 3: A fixed amount of liquid has a definite volume under ordinary conditions, although its shape depends on the container.","steps":["Step 1: A gas expands to occupy the available space.","Step 2: The volume of a gas depends on its container and conditions.","Step 3: A fixed amount of liquid has a definite volume under ordinary conditions, although its shape depends on the container."],"options":[],"conceptId":"chemistry_matter_separation_gases","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q5","subject":"chemistry","chapter":"matter_separation","topic":"Gases"}', 4),
  (2911, 728, 'Define particle arrangement and describe the arrangement of particles in a typical solid.', 'text', 1, 'Describe both the spacing and the positions of the particles.', '{"why":"The close, relatively fixed arrangement helps a solid retain its shape and volume.","sol":"Step 1: Define particle arrangement as the relative positioning of particles.\nStep 2: State that solid particles are closely packed.\nStep 3: State that they occupy relatively fixed positions.","steps":["Step 1: Define particle arrangement as the relative positioning of particles.","Step 2: State that solid particles are closely packed.","Step 3: State that they occupy relatively fixed positions."],"options":[],"conceptId":"chemistry_matter_separation_particle_arrangement","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Particle Arrangement"}', 0),
  (2912, 728, 'Compare the arrangement of particles in a liquid and a gas.', 'text', 1, 'Focus on the distance between neighbouring particles.', '{"why":"Particle spacing is an important difference between liquids and gases.","sol":"Step 1: Liquid particles are relatively close together.\nStep 2: Gas particles are widely separated.\nStep 3: Explain how this difference distinguishes the two arrangements.","steps":["Step 1: Liquid particles are relatively close together.","Step 2: Gas particles are widely separated.","Step 3: Explain how this difference distinguishes the two arrangements."],"options":[],"conceptId":"chemistry_matter_separation_particle_arrangement","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Particle Arrangement"}', 1),
  (2913, 728, 'A particle diagram contains widely spaced particles distributed throughout a box. Identify the likely state and justify your answer.', 'text', 1, 'Match the spacing shown with the three states of matter.', '{"why":"Gases have much more space between their particles than solids and liquids in the basic particle model.","sol":"Step 1: Observe that the particles are widely spaced.\nStep 2: Observe that they are spread throughout the box.\nStep 3: Compare these features with the arrangement in a gas.","steps":["Step 1: Observe that the particles are widely spaced.","Step 2: Observe that they are spread throughout the box.","Step 3: Compare these features with the arrangement in a gas."],"options":[],"conceptId":"chemistry_matter_separation_particle_arrangement","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Particle Arrangement"}', 2),
  (2914, 728, 'Explain why a typical solid and a liquid can both have closely packed particles but different shapes.', 'text', 1, 'Arrangement is important, but consider whether the particles occupy fixed positions.', '{"why":"Close spacing helps explain volume, while the difference in how positions can change helps explain shape.","sol":"Step 1: Recognise that both states have particles relatively close together.\nStep 2: Solid particles occupy relatively fixed positions.\nStep 3: Liquid particles can move past one another.\nStep 4: Relate this difference to the shape of each state.","steps":["Step 1: Recognise that both states have particles relatively close together.","Step 2: Solid particles occupy relatively fixed positions.","Step 3: Liquid particles can move past one another.","Step 4: Relate this difference to the shape of each state."],"options":[],"conceptId":"chemistry_matter_separation_particle_arrangement","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Particle Arrangement"}', 3),
  (2915, 728, 'A student draws every solid with particles in perfectly regular rows. Explain why this model is too restrictive.', 'text', 1, 'Think about whether all solids have the same internal structure.', '{"why":"A useful particle model shows the general features of a state without incorrectly claiming that every substance has an identical structure.","sol":"Step 1: Recognise that closely packed particles are characteristic of solids.\nStep 2: Recall that many crystalline solids have regular repeating arrangements.\nStep 3: Recognise that other solids can have irregular arrangements while remaining closely packed.","steps":["Step 1: Recognise that closely packed particles are characteristic of solids.","Step 2: Recall that many crystalline solids have regular repeating arrangements.","Step 3: Recognise that other solids can have irregular arrangements while remaining closely packed."],"options":[],"conceptId":"chemistry_matter_separation_particle_arrangement","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q5","subject":"chemistry","chapter":"matter_separation","topic":"Particle Arrangement"}', 4),
  (2916, 729, 'Describe the movement of particles in a solid and explain why a solid can appear motionless.', 'text', 1, 'Think about vibration and relatively fixed positions.', '{"why":"The movement of individual particles can occur without visible movement of the entire object.","sol":"Step 1: State that solid particles occupy relatively fixed positions.\nStep 2: State that they vibrate about those positions.\nStep 3: Distinguish particle motion from movement of the solid as a whole.","steps":["Step 1: State that solid particles occupy relatively fixed positions.","Step 2: State that they vibrate about those positions.","Step 3: Distinguish particle motion from movement of the solid as a whole."],"options":[],"conceptId":"chemistry_matter_separation_particle_movement","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Particle Movement"}', 0),
  (2917, 729, 'Explain how particle movement enables a liquid to flow.', 'text', 1, 'Consider whether liquid particles can change their positions relative to one another.', '{"why":"The particles are not held in the same relatively fixed positions as particles in a solid.","sol":"Step 1: Identify the substance as a liquid.\nStep 2: State that its particles can move past one another.\nStep 3: Explain that this movement allows the liquid to change shape and flow.","steps":["Step 1: Identify the substance as a liquid.","Step 2: State that its particles can move past one another.","Step 3: Explain that this movement allows the liquid to change shape and flow."],"options":[],"conceptId":"chemistry_matter_separation_particle_movement","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Particle Movement"}', 1),
  (2918, 729, 'A smell spreads from one side of a room to the other. Explain how gas particle movement accounts for this observation.', 'text', 1, 'Think about how particles move and spread through available space.', '{"why":"Gas particles can travel through the available space rather than remaining in fixed positions.","sol":"Step 1: Some molecules responsible for the smell enter the air.\nStep 2: Gas particles move freely in different directions.\nStep 3: The molecules spread through the air, a process called diffusion.","steps":["Step 1: Some molecules responsible for the smell enter the air.","Step 2: Gas particles move freely in different directions.","Step 3: The molecules spread through the air, a process called diffusion."],"options":[],"conceptId":"chemistry_matter_separation_particle_movement","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Particle Movement"}', 2),
  (2919, 729, 'Compare particle movement in solids, liquids and gases.', 'text', 1, 'Describe the characteristic movement in each state separately.', '{"why":"The different forms of particle movement help explain the different properties of each state.","sol":"Step 1: For a solid, describe vibration about relatively fixed positions.\nStep 2: For a liquid, describe particles moving past one another.\nStep 3: For a gas, describe free movement in different directions.","steps":["Step 1: For a solid, describe vibration about relatively fixed positions.","Step 2: For a liquid, describe particles moving past one another.","Step 3: For a gas, describe free movement in different directions."],"options":[],"conceptId":"chemistry_matter_separation_particle_movement","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Particle Movement"}', 3),
  (2920, 729, 'Explain the difference between particle arrangement and particle movement, using a solid as an example.', 'text', 1, 'One describes positions; the other describes motion.', '{"why":"A particle model needs both ideas: the positions of particles and the way those particles move.","sol":"Step 1: Define arrangement as the relative positioning of particles.\nStep 2: Define movement as how particles move.\nStep 3: Apply both descriptions to a solid.","steps":["Step 1: Define arrangement as the relative positioning of particles.","Step 2: Define movement as how particles move.","Step 3: Apply both descriptions to a solid."],"options":[],"conceptId":"chemistry_matter_separation_particle_movement","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q5","subject":"chemistry","chapter":"matter_separation","topic":"Particle Movement"}', 4),
  (2921, 730, 'Explain how increasing temperature affects the average kinetic energy and movement of particles in a solid that remains solid.', 'text', 1, 'Focus on the particles'' vibration about their positions.', '{"why":"Heating increases particle motion, but in a solid that remains solid, the characteristic movement is vibration rather than free movement throughout the material.","sol":"Step 1: An increase in temperature generally increases average particle kinetic energy.\nStep 2: Solid particles remain around relatively fixed positions.\nStep 3: Their vibrations become more vigorous.","steps":["Step 1: An increase in temperature generally increases average particle kinetic energy.","Step 2: Solid particles remain around relatively fixed positions.","Step 3: Their vibrations become more vigorous."],"options":[],"conceptId":"chemistry_matter_separation_effect_of_temperature_on_particles","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Effect of Temperature on Particles"}', 0),
  (2922, 730, 'A gas is cooled while remaining gaseous. Describe the expected changes in average kinetic energy and particle speed.', 'text', 1, 'Relate lower temperature to the motion of the particles.', '{"why":"For a gas in thermal equilibrium, lower absolute temperature corresponds to lower average translational kinetic energy.","sol":"Step 1: The temperature decreases.\nStep 2: The average kinetic energy decreases.\nStep 3: The particles move more slowly on average.","steps":["Step 1: The temperature decreases.","Step 2: The average kinetic energy decreases.","Step 3: The particles move more slowly on average."],"options":[],"conceptId":"chemistry_matter_separation_effect_of_temperature_on_particles","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Effect of Temperature on Particles"}', 1),
  (2923, 730, 'Explain why the statement ''every particle has exactly the same kinetic energy at a given temperature'' is incorrect.', 'text', 1, 'Consider the range of speeds particles can have.', '{"why":"An average describes a collection of particles and does not imply that every individual value is identical.","sol":"Step 1: Temperature relates to an average kinetic energy.\nStep 2: Particles in a sample do not all have exactly the same speed at every moment.\nStep 3: Therefore, their individual kinetic energies can differ.","steps":["Step 1: Temperature relates to an average kinetic energy.","Step 2: Particles in a sample do not all have exactly the same speed at every moment.","Step 3: Therefore, their individual kinetic energies can differ."],"options":[],"conceptId":"chemistry_matter_separation_effect_of_temperature_on_particles","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Effect of Temperature on Particles"}', 2),
  (2924, 730, 'An ideal gas is heated from 250 K to 500 K. Calculate the factor by which its average translational kinetic energy changes.', 'text', 1, 'For an ideal gas, average translational kinetic energy is proportional to absolute temperature.', '{"why":"For an ideal gas, average translational kinetic energy is directly proportional to absolute temperature measured in kelvin.","sol":"Step 1: Initial temperature = 250 K.\nStep 2: Final temperature = 500 K.\nStep 3: Temperature ratio = 500 ÷ 250 = 2.\nStep 4: The average translational kinetic energy changes by the same factor.","steps":["Step 1: Initial temperature = 250 K.","Step 2: Final temperature = 500 K.","Step 3: Temperature ratio = 500 ÷ 250 = 2.","Step 4: The average translational kinetic energy changes by the same factor."],"options":[],"conceptId":"chemistry_matter_separation_effect_of_temperature_on_particles","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Effect of Temperature on Particles"}', 3),
  (2925, 730, 'Distinguish between temperature and heating, and explain how heating generally affects the particles of a substance that does not change state.', 'text', 1, 'One is a measure related to the thermal state; the other is energy transfer.', '{"why":"Temperature and heating are related but are not interchangeable terms. The change in particle motion depends on the state of the substance.","sol":"Step 1: Temperature is related to the average kinetic energy of particles.\nStep 2: Heating is energy transfer caused by a temperature difference.\nStep 3: When heating raises the temperature without a change of state, average particle kinetic energy generally increases.\nStep 4: Describe the corresponding movement in the relevant state.","steps":["Step 1: Temperature is related to the average kinetic energy of particles.","Step 2: Heating is energy transfer caused by a temperature difference.","Step 3: When heating raises the temperature without a change of state, average particle kinetic energy generally increases.","Step 4: Describe the corresponding movement in the relevant state."],"options":[],"conceptId":"chemistry_matter_separation_effect_of_temperature_on_particles","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q5","subject":"chemistry","chapter":"matter_separation","topic":"Effect of Temperature on Particles"}', 4),
  (2926, 731, 'Define melting and identify the initial and final states involved.', 'text', 1, 'State the direction of the change.', '{"why":"Melting always describes the direction from solid to liquid.","sol":"Step 1: Identify the initial state as a solid.\nStep 2: Identify the final state as a liquid.\nStep 3: Name the change from solid to liquid.","steps":["Step 1: Identify the initial state as a solid.","Step 2: Identify the final state as a liquid.","Step 3: Name the change from solid to liquid."],"options":[],"conceptId":"chemistry_matter_separation_melting","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Melting"}', 0),
  (2927, 731, 'Pure ice melts at approximately 0°C at standard atmospheric pressure. What is meant by its melting point?', 'text', 1, 'Explain what the temperature represents, not just its numerical value.', '{"why":"A melting point is defined for specified pressure conditions.","sol":"Step 1: Identify ice as solid water.\nStep 2: Identify the temperature at which it changes into liquid water under the stated pressure.\nStep 3: Relate this temperature to the definition of melting point.","steps":["Step 1: Identify ice as solid water.","Step 2: Identify the temperature at which it changes into liquid water under the stated pressure.","Step 3: Relate this temperature to the definition of melting point."],"options":[],"conceptId":"chemistry_matter_separation_melting","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Melting"}', 1),
  (2928, 731, 'A pure crystalline solid is melting at constant pressure. Explain why its temperature remains constant while energy is supplied.', 'text', 1, 'Consider what the energy is being used to do during the change of state.', '{"why":"Energy supplied during the change of state is used for melting rather than raising the temperature.","sol":"Step 1: Recognise that solid and liquid coexist during melting.\nStep 2: The supplied energy helps overcome forces holding the particles in the solid arrangement.\nStep 3: Under equilibrium melting conditions, this energy does not increase the temperature.","steps":["Step 1: Recognise that solid and liquid coexist during melting.","Step 2: The supplied energy helps overcome forces holding the particles in the solid arrangement.","Step 3: Under equilibrium melting conditions, this energy does not increase the temperature."],"options":[],"conceptId":"chemistry_matter_separation_melting","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Melting"}', 2),
  (2929, 731, 'A student says that every solid melts at 0°C. Explain why this statement is incorrect and give an example.', 'text', 1, 'Compare the melting points of different substances.', '{"why":"The melting point is a characteristic of a substance under specified conditions, not a universal temperature for all solids.","sol":"Step 1: Recognise that melting point depends on the substance.\nStep 2: Recall that pure ice melts at approximately 0°C at standard atmospheric pressure.\nStep 3: Compare ice with another substance, such as pure iron, which has a much higher melting point.","steps":["Step 1: Recognise that melting point depends on the substance.","Step 2: Recall that pure ice melts at approximately 0°C at standard atmospheric pressure.","Step 3: Compare ice with another substance, such as pure iron, which has a much higher melting point."],"options":[],"conceptId":"chemistry_matter_separation_melting","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Melting"}', 3),
  (2930, 731, 'Describe what happens to the particles when a solid absorbs energy and melts.', 'text', 1, 'Consider the particles before melting and their ability to move in the liquid.', '{"why":"Melting changes the arrangement and freedom of movement of the particles; it does not mean that the particles disappear.","sol":"Step 1: Before melting, particles vibrate about relatively fixed positions.\nStep 2: As the solid warms, particles generally vibrate more vigorously.\nStep 3: During melting, energy helps overcome forces maintaining the solid arrangement.\nStep 4: In the liquid, particles can move past one another.","steps":["Step 1: Before melting, particles vibrate about relatively fixed positions.","Step 2: As the solid warms, particles generally vibrate more vigorously.","Step 3: During melting, energy helps overcome forces maintaining the solid arrangement.","Step 4: In the liquid, particles can move past one another."],"options":[],"conceptId":"chemistry_matter_separation_melting","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q5","subject":"chemistry","chapter":"matter_separation","topic":"Melting"}', 4),
  (2931, 732, 'Define freezing and state the direction of the change of state.', 'text', 1, 'Identify the starting state and the final state.', '{"why":"Freezing describes the change from liquid to solid.","sol":"Step 1: Identify the starting state as a liquid.\nStep 2: Identify the final state as a solid.\nStep 3: Name the change from liquid to solid.","steps":["Step 1: Identify the starting state as a liquid.","Step 2: Identify the final state as a solid.","Step 3: Name the change from liquid to solid."],"options":[],"conceptId":"chemistry_matter_separation_freezing","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Freezing"}', 0),
  (2932, 732, 'Pure water freezes at approximately 0°C at standard atmospheric pressure. Explain what its freezing point means.', 'text', 1, 'Describe the change that occurs at that temperature.', '{"why":"Freezing point depends on the substance and the pressure conditions.","sol":"Step 1: Identify the substance as pure water.\nStep 2: Identify the liquid-to-solid change.\nStep 3: Include the pressure condition.","steps":["Step 1: Identify the substance as pure water.","Step 2: Identify the liquid-to-solid change.","Step 3: Include the pressure condition."],"options":[],"conceptId":"chemistry_matter_separation_freezing","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Freezing"}', 1),
  (2933, 732, 'Describe how the movement of particles changes as a liquid cools and freezes.', 'text', 1, 'Compare the particles in the liquid with those in the solid.', '{"why":"Cooling reduces average kinetic energy, and freezing produces the solid particle arrangement.","sol":"Step 1: As the liquid cools, its particles generally lose kinetic energy.\nStep 2: The liquid changes into a solid at the freezing point under the stated conditions.\nStep 3: The solid particles occupy relatively fixed positions and vibrate about them.","steps":["Step 1: As the liquid cools, its particles generally lose kinetic energy.","Step 2: The liquid changes into a solid at the freezing point under the stated conditions.","Step 3: The solid particles occupy relatively fixed positions and vibrate about them."],"options":[],"conceptId":"chemistry_matter_separation_freezing","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Freezing"}', 2),
  (2934, 732, 'A pure substance freezes at 65°C. A learner argues that this cannot be its freezing point because water freezes at 0°C. Explain the error.', 'text', 1, 'Does every substance have the same freezing point?', '{"why":"The freezing point is characteristic of a substance under specified conditions; it is not the same for all substances.","sol":"Step 1: Recognise that freezing points vary between substances.\nStep 2: Use 0°C as the approximate freezing point of pure water at standard atmospheric pressure.\nStep 3: Apply the stated measurement to the different substance.","steps":["Step 1: Recognise that freezing points vary between substances.","Step 2: Use 0°C as the approximate freezing point of pure water at standard atmospheric pressure.","Step 3: Apply the stated measurement to the different substance."],"options":[],"conceptId":"chemistry_matter_separation_freezing","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Freezing"}', 3),
  (2935, 732, 'Explain why freezing water is a physical change rather than a chemical change.', 'text', 1, 'Compare the substance before and after freezing.', '{"why":"The state changes, but the chemical identity of the substance remains the same.","sol":"Step 1: Before freezing, the substance is liquid water.\nStep 2: After freezing, the substance is solid ice.\nStep 3: Both liquid water and ice consist of water molecules.\nStep 4: Conclude whether a new chemical substance has formed.","steps":["Step 1: Before freezing, the substance is liquid water.","Step 2: After freezing, the substance is solid ice.","Step 3: Both liquid water and ice consist of water molecules.","Step 4: Conclude whether a new chemical substance has formed."],"options":[],"conceptId":"chemistry_matter_separation_freezing","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q5","subject":"chemistry","chapter":"matter_separation","topic":"Freezing"}', 4),
  (2936, 733, 'Define evaporation and state where it occurs in a liquid.', 'text', 1, 'Identify the particles that escape and the location from which they escape.', '{"why":"Evaporation is a surface process and can occur below the boiling point.","sol":"Step 1: Identify the starting state as a liquid.\nStep 2: Explain that particles escape into the gaseous state.\nStep 3: State that evaporation occurs at the liquid''s surface.","steps":["Step 1: Identify the starting state as a liquid.","Step 2: Explain that particles escape into the gaseous state.","Step 3: State that evaporation occurs at the liquid''s surface."],"options":[],"conceptId":"chemistry_matter_separation_evaporation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Evaporation"}', 0),
  (2937, 733, 'Explain why water can evaporate from a wet floor at room temperature without boiling.', 'text', 1, 'Consider whether a liquid must reach its boiling point before surface particles can escape.', '{"why":"Evaporation depends on surface particles escaping; the entire liquid does not need to reach its boiling point.","sol":"Step 1: Liquid particles have a range of kinetic energies.\nStep 2: Some surface particles have enough energy to escape the liquid.\nStep 3: These particles enter the gaseous state even when the liquid is below its boiling point.","steps":["Step 1: Liquid particles have a range of kinetic energies.","Step 2: Some surface particles have enough energy to escape the liquid.","Step 3: These particles enter the gaseous state even when the liquid is below its boiling point."],"options":[],"conceptId":"chemistry_matter_separation_evaporation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Evaporation"}', 1),
  (2938, 733, 'Equal amounts of water are exposed to the air in two dishes. Dish A has a larger exposed surface area than Dish B. Under otherwise similar conditions, explain which dish is likely to lose water faster.', 'text', 1, 'Consider how many particles are exposed at the liquid surface.', '{"why":"Surface area affects the rate of evaporation when other relevant conditions are kept similar.","sol":"Step 1: Identify Dish A as having the larger exposed surface area.\nStep 2: Recognise that more liquid particles are exposed to the air at the same time.\nStep 3: Relate the larger exposed surface to a higher evaporation rate.","steps":["Step 1: Identify Dish A as having the larger exposed surface area.","Step 2: Recognise that more liquid particles are exposed to the air at the same time.","Step 3: Relate the larger exposed surface to a higher evaporation rate."],"options":[],"conceptId":"chemistry_matter_separation_evaporation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Evaporation"}', 2),
  (2939, 733, 'Explain why increasing the temperature of a liquid generally increases its rate of evaporation.', 'text', 1, 'Relate temperature to particle kinetic energy.', '{"why":"The evaporation rate depends on the number of particles able to overcome the attractive forces holding them in the liquid.","sol":"Step 1: Increasing temperature generally increases average particle kinetic energy.\nStep 2: A greater proportion of surface particles can have enough energy to escape.\nStep 3: More particles can leave the liquid per unit time.","steps":["Step 1: Increasing temperature generally increases average particle kinetic energy.","Step 2: A greater proportion of surface particles can have enough energy to escape.","Step 3: More particles can leave the liquid per unit time."],"options":[],"conceptId":"chemistry_matter_separation_evaporation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Evaporation"}', 3),
  (2940, 733, 'Explain how evaporation can cool the remaining liquid or a person''s skin.', 'text', 1, 'Consider the energy carried away by particles that escape.', '{"why":"Evaporation removes energy from the remaining liquid and can lower its temperature.","sol":"Step 1: Higher-energy particles escape from the liquid surface.\nStep 2: The escaping particles carry energy away.\nStep 3: The remaining liquid or surface loses thermal energy and can cool.","steps":["Step 1: Higher-energy particles escape from the liquid surface.","Step 2: The escaping particles carry energy away.","Step 3: The remaining liquid or surface loses thermal energy and can cool."],"options":[],"conceptId":"chemistry_matter_separation_evaporation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q5","subject":"chemistry","chapter":"matter_separation","topic":"Evaporation"}', 4),
  (2941, 733, 'Describe how a learner can obtain solid salt from a salt solution by evaporation when the water is not needed.', 'text', 1, 'State where the solution is placed and what happens to the water.', '{"why":"The water is the solvent that is removed, while the dissolved salt remains in the dish as a solid.","sol":"Step 1: Pour the salt solution into a suitable evaporating dish.\nStep 2: Heat gently under appropriate laboratory conditions.\nStep 3: Water escapes as vapour.\nStep 4: The remaining solid is salt, provided the water has been removed sufficiently.","steps":["Step 1: Pour the salt solution into a suitable evaporating dish.","Step 2: Heat gently under appropriate laboratory conditions.","Step 3: Water escapes as vapour.","Step 4: The remaining solid is salt, provided the water has been removed sufficiently."],"options":[],"conceptId":"chemistry_matter_separation_evaporation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q6","subject":"chemistry","chapter":"matter_separation","topic":"Evaporation"}', 5),
  (2942, 733, 'A learner heats a salt solution and observes that its volume decreases. Explain why the volume decreases and what may remain if enough water is removed.', 'text', 1, 'Identify the component that escapes as vapour.', '{"why":"Evaporation removes the solvent from the solution.","sol":"Step 1: Heating increases the rate at which water evaporates.\nStep 2: Water leaves the solution as vapour.\nStep 3: As water is removed, less liquid remains.\nStep 4: If enough water is removed, solid salt remains.","steps":["Step 1: Heating increases the rate at which water evaporates.","Step 2: Water leaves the solution as vapour.","Step 3: As water is removed, less liquid remains.","Step 4: If enough water is removed, solid salt remains."],"options":[],"conceptId":"chemistry_matter_separation_evaporation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q7","subject":"chemistry","chapter":"matter_separation","topic":"Evaporation"}', 6),
  (2943, 733, 'Two equal quantities of water are placed in identical conditions, one in a wide dish and the other in a narrow dish. Predict which loses water faster and explain why.', 'text', 1, 'Compare the exposed surface areas.', '{"why":"Surface area is one of the factors that affects the rate of evaporation.","sol":"Step 1: The wide dish exposes more water at the surface.\nStep 2: Evaporation occurs at the liquid surface.\nStep 3: A larger exposed surface generally allows faster evaporation when other conditions are the same.","steps":["Step 1: The wide dish exposes more water at the surface.","Step 2: Evaporation occurs at the liquid surface.","Step 3: A larger exposed surface generally allows faster evaporation when other conditions are the same."],"options":[],"conceptId":"chemistry_matter_separation_evaporation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q8","subject":"chemistry","chapter":"matter_separation","topic":"Evaporation"}', 7),
  (2944, 733, 'A learner wants to recover both the salt and the water from salt solution. Explain why ordinary evaporation in an open dish will not recover both substances.', 'text', 1, 'Consider what happens to the water vapour.', '{"why":"The open-dish method is designed to remove the solvent, not to recover it as a separate liquid.","sol":"Step 1: Evaporation leaves the dissolved salt behind as the water escapes.\nStep 2: In an open dish, the water vapour enters the surrounding air.\nStep 3: The water is therefore not collected in the ordinary evaporation setup.","steps":["Step 1: Evaporation leaves the dissolved salt behind as the water escapes.","Step 2: In an open dish, the water vapour enters the surrounding air.","Step 3: The water is therefore not collected in the ordinary evaporation setup."],"options":[],"conceptId":"chemistry_matter_separation_evaporation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q9","subject":"chemistry","chapter":"matter_separation","topic":"Evaporation"}', 8),
  (2945, 733, 'Explain how increasing the temperature generally affects the rate of evaporation of water.', 'text', 1, 'Think about the energy of the water particles.', '{"why":"Temperature affects how readily liquid particles escape into the gaseous state.","sol":"Step 1: Heating transfers energy to the water particles.\nStep 2: A greater proportion of surface particles can escape into the gaseous state in a given time.\nStep 3: The rate of evaporation generally increases.","steps":["Step 1: Heating transfers energy to the water particles.","Step 2: A greater proportion of surface particles can escape into the gaseous state in a given time.","Step 3: The rate of evaporation generally increases."],"options":[],"conceptId":"chemistry_matter_separation_evaporation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q10","subject":"chemistry","chapter":"matter_separation","topic":"Evaporation"}', 9),
  (2946, 734, 'Define boiling and explain where vaporisation occurs during this process.', 'text', 1, 'Distinguish the formation of bubbles throughout a liquid from surface evaporation.', '{"why":"The formation of vapour bubbles throughout the liquid distinguishes boiling from evaporation at the surface.","sol":"Step 1: Identify boiling as rapid vaporisation of a liquid.\nStep 2: State that vapour bubbles form throughout the liquid.\nStep 3: Include the condition that vapour pressure equals external pressure.","steps":["Step 1: Identify boiling as rapid vaporisation of a liquid.","Step 2: State that vapour bubbles form throughout the liquid.","Step 3: Include the condition that vapour pressure equals external pressure."],"options":[],"conceptId":"chemistry_matter_separation_boiling","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Boiling"}', 0),
  (2947, 734, 'Pure water boils at approximately 100°C at standard atmospheric pressure. Explain what is meant by its boiling point.', 'text', 1, 'Include the pressure condition and the process occurring at that temperature.', '{"why":"Boiling point must be stated with its pressure conditions because external pressure affects the temperature at which boiling occurs.","sol":"Step 1: Identify the liquid as pure water.\nStep 2: State the temperature at which it boils under standard atmospheric pressure.\nStep 3: Describe the formation of vapour throughout the liquid.","steps":["Step 1: Identify the liquid as pure water.","Step 2: State the temperature at which it boils under standard atmospheric pressure.","Step 3: Describe the formation of vapour throughout the liquid."],"options":[],"conceptId":"chemistry_matter_separation_boiling","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Boiling"}', 1),
  (2948, 734, 'A pure liquid is boiling at constant external pressure. Explain why its temperature remains constant while energy continues to be supplied.', 'text', 1, 'Consider the purpose of the energy during vaporisation.', '{"why":"During the change of state, the supplied energy supports vaporisation rather than a temperature increase.","sol":"Step 1: Recognise that the liquid and vapour coexist during boiling.\nStep 2: The supplied energy is used to convert liquid into vapour.\nStep 3: Under equilibrium boiling conditions, the temperature remains constant while both phases coexist.","steps":["Step 1: Recognise that the liquid and vapour coexist during boiling.","Step 2: The supplied energy is used to convert liquid into vapour.","Step 3: Under equilibrium boiling conditions, the temperature remains constant while both phases coexist."],"options":[],"conceptId":"chemistry_matter_separation_boiling","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Boiling"}', 2),
  (2949, 734, 'Explain two differences between boiling and evaporation.', 'text', 1, 'Compare where the process occurs and the conditions required.', '{"why":"Although both processes convert liquid into gas, their locations and conditions differ.","sol":"Step 1: Boiling involves vapour bubbles forming throughout the liquid.\nStep 2: Evaporation occurs at the liquid surface.\nStep 3: Boiling occurs at the boiling point for the external pressure.\nStep 4: Evaporation can occur below the boiling point.","steps":["Step 1: Boiling involves vapour bubbles forming throughout the liquid.","Step 2: Evaporation occurs at the liquid surface.","Step 3: Boiling occurs at the boiling point for the external pressure.","Step 4: Evaporation can occur below the boiling point."],"options":[],"conceptId":"chemistry_matter_separation_boiling","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Boiling"}', 3),
  (2950, 734, 'Water boils at a lower temperature at a high-altitude location than at standard atmospheric pressure. Explain why.', 'text', 1, 'Relate boiling to the external pressure.', '{"why":"The boiling point depends on external pressure, so it is not a fixed temperature independent of surroundings.","sol":"Step 1: Recognise that atmospheric pressure is lower at high altitude.\nStep 2: Boiling occurs when the liquid''s vapour pressure equals the external pressure.\nStep 3: At lower external pressure, this equality is reached at a lower temperature.","steps":["Step 1: Recognise that atmospheric pressure is lower at high altitude.","Step 2: Boiling occurs when the liquid''s vapour pressure equals the external pressure.","Step 3: At lower external pressure, this equality is reached at a lower temperature."],"options":[],"conceptId":"chemistry_matter_separation_boiling","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q5","subject":"chemistry","chapter":"matter_separation","topic":"Boiling"}', 4),
  (2951, 735, 'Define condensation and state the two states of matter involved.', 'text', 1, 'Identify the starting state and the final state.', '{"why":"A gas such as water vapour changes into liquid water. The substance remains the same; only its physical state changes.","sol":"Step 1: Identify the starting state of the substance.\nStep 2: Identify the state formed after the change.","steps":["Step 1: Identify the starting state of the substance.","Step 2: Identify the state formed after the change."],"options":[],"conceptId":"chemistry_matter_separation_condensation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Condensation"}', 0),
  (2952, 735, 'A cold metal can develops water droplets on its outside. Explain where the droplets come from and how they form.', 'text', 1, 'Consider the water vapour in the surrounding air.', '{"why":"This is condensation. The water droplets generally come from the air, not from water leaking through the metal.","sol":"Step 1: Recognise that the air contains water vapour.\nStep 2: Explain that the cold surface allows the vapour to lose thermal energy.\nStep 3: State the change of state that produces the droplets.","steps":["Step 1: Recognise that the air contains water vapour.","Step 2: Explain that the cold surface allows the vapour to lose thermal energy.","Step 3: State the change of state that produces the droplets."],"options":[],"conceptId":"chemistry_matter_separation_condensation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Condensation"}', 1),
  (2953, 735, 'Describe what happens to the average kinetic energy and spacing of particles when a gas condenses into a liquid.', 'text', 1, 'Think about energy loss and the difference between gases and liquids.', '{"why":"The particles become less widely separated. They still move in the liquid, but they are much closer together than in the gas.","sol":"Step 1: State what happens when the gas transfers thermal energy to its surroundings.\nStep 2: Relate the energy change to average particle kinetic energy.\nStep 3: Describe the change in particle spacing.","steps":["Step 1: State what happens when the gas transfers thermal energy to its surroundings.","Step 2: Relate the energy change to average particle kinetic energy.","Step 3: Describe the change in particle spacing."],"options":[],"conceptId":"chemistry_matter_separation_condensation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Condensation"}', 2),
  (2954, 735, 'A student says that droplets on a cold glass are formed because liquid water inside the glass passes through its walls. Explain why condensation is the better explanation for an ordinary intact glass.', 'text', 1, 'Distinguish water already inside the glass from water vapour in the air.', '{"why":"An ordinary intact glass does not allow its contents to pass through its solid walls. Condensation explains the appearance of droplets on the outside.","sol":"Step 1: Identify the water vapour present in the air.\nStep 2: Explain what happens when the vapour encounters the cold outside surface.\nStep 3: Connect the process to the observed liquid droplets.","steps":["Step 1: Identify the water vapour present in the air.","Step 2: Explain what happens when the vapour encounters the cold outside surface.","Step 3: Connect the process to the observed liquid droplets."],"options":[],"conceptId":"chemistry_matter_separation_condensation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Condensation"}', 3),
  (2955, 735, 'Explain why cooling moist air can lead to condensation.', 'text', 1, 'Describe the energy transfer and the resulting state change.', '{"why":"Condensation occurs when the conditions allow the gas to form a liquid. Cooling is important, but the exact conditions also depend on the amount of water vapour and the pressure.","sol":"Step 1: State that moist air contains water vapour.\nStep 2: Explain that cooling involves the vapour losing thermal energy.\nStep 3: State what can happen when suitable conditions for condensation are reached.","steps":["Step 1: State that moist air contains water vapour.","Step 2: Explain that cooling involves the vapour losing thermal energy.","Step 3: State what can happen when suitable conditions for condensation are reached."],"options":[],"conceptId":"chemistry_matter_separation_condensation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q5","subject":"chemistry","chapter":"matter_separation","topic":"Condensation"}', 4),
  (2956, 736, 'Define sublimation and explain what makes it different from a change that passes through the liquid state.', 'text', 1, 'Focus on the starting state and the final state.', '{"why":"The defining feature is the direct solid-to-gas transition. The liquid state is not an intermediate state in the process being described.","sol":"Step 1: Identify the initial state.\nStep 2: Identify the final state.\nStep 3: Explain whether a liquid state occurs between them.","steps":["Step 1: Identify the initial state.","Step 2: Identify the final state.","Step 3: Explain whether a liquid state occurs between them."],"options":[],"conceptId":"chemistry_matter_separation_sublimation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Sublimation"}', 0),
  (2957, 736, 'Solid dry ice becomes smaller at ordinary atmospheric pressure. Explain the state change responsible for this observation.', 'text', 1, 'Recall the identity of dry ice and what happens to it under ordinary atmospheric pressure.', '{"why":"As the solid changes into gas and disperses, the solid piece becomes smaller. The visible mist around dry ice is mainly tiny water droplets from the surrounding air.","sol":"Step 1: Identify dry ice as solid carbon dioxide.\nStep 2: State the state into which it changes.\nStep 3: Explain why the change is sublimation.","steps":["Step 1: Identify dry ice as solid carbon dioxide.","Step 2: State the state into which it changes.","Step 3: Explain why the change is sublimation."],"options":[],"conceptId":"chemistry_matter_separation_sublimation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Sublimation"}', 1),
  (2958, 736, 'When solid iodine is heated in a suitable laboratory setup, purple iodine vapour appears. Explain how this observation can demonstrate sublimation.', 'text', 1, 'Compare the state of iodine before heating with the state of the vapour.', '{"why":"The observed vapour shows that iodine particles have entered the gas state. Heating supplies energy for the state change.","sol":"Step 1: Identify the starting material as solid iodine.\nStep 2: Identify the purple vapour as gaseous iodine.\nStep 3: Explain the significance of the direct state change.","steps":["Step 1: Identify the starting material as solid iodine.","Step 2: Identify the purple vapour as gaseous iodine.","Step 3: Explain the significance of the direct state change."],"options":[],"conceptId":"chemistry_matter_separation_sublimation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Sublimation"}', 2),
  (2959, 736, 'A solid gradually becomes smaller as particles leave it and enter the gas state directly. What process is occurring? Give one suitable example.', 'text', 1, 'The substance begins as a solid and does not become liquid first.', '{"why":"A direct solid-to-gas change is sublimation. A shrinking solid alone is not sufficient proof in every situation; the described direct transfer into gas identifies the process.","sol":"Step 1: Identify the starting state as solid.\nStep 2: Identify the final state as gas.\nStep 3: Name the process and provide an example.","steps":["Step 1: Identify the starting state as solid.","Step 2: Identify the final state as gas.","Step 3: Name the process and provide an example."],"options":[],"conceptId":"chemistry_matter_separation_sublimation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Sublimation"}', 3),
  (2960, 736, 'A student says that sublimation is a chemical reaction because a solid disappears and a gas forms. Explain why this conclusion is incorrect.', 'text', 1, 'Ask whether the substance''s chemical identity has changed.', '{"why":"A change in state does not by itself indicate a chemical reaction. In sublimation, the chemical identity of the substance remains the same.","sol":"Step 1: Identify the change in physical state.\nStep 2: Consider whether a new chemical substance must form.\nStep 3: Classify the process based on the information given.","steps":["Step 1: Identify the change in physical state.","Step 2: Consider whether a new chemical substance must form.","Step 3: Classify the process based on the information given."],"options":[],"conceptId":"chemistry_matter_separation_sublimation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q5","subject":"chemistry","chapter":"matter_separation","topic":"Sublimation"}', 4),
  (2961, 737, 'Define deposition and state the two states of matter involved.', 'text', 1, 'Start with the state of the vapour and identify the state formed.', '{"why":"The defining feature of deposition is the gas-to-solid transition without an intermediate liquid state.","sol":"Step 1: Identify the initial state as gas.\nStep 2: Identify the final state as solid.\nStep 3: State whether a liquid state occurs in between.","steps":["Step 1: Identify the initial state as gas.","Step 2: Identify the final state as solid.","Step 3: State whether a liquid state occurs in between."],"options":[],"conceptId":"chemistry_matter_separation_deposition","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Deposition"}', 0),
  (2962, 737, 'Explain how frost can form on a sufficiently cold surface without liquid water appearing first.', 'text', 1, 'Consider what happens to water vapour in contact with a very cold surface.', '{"why":"Frost can form without liquid water appearing first because the water vapour changes directly into solid ice.","sol":"Step 1: Identify water vapour as water in the gas state.\nStep 2: Explain that the vapour loses thermal energy under suitable conditions.\nStep 3: Describe the direct formation of solid ice crystals.","steps":["Step 1: Identify water vapour as water in the gas state.","Step 2: Explain that the vapour loses thermal energy under suitable conditions.","Step 3: Describe the direct formation of solid ice crystals."],"options":[],"conceptId":"chemistry_matter_separation_deposition","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Deposition"}', 1),
  (2963, 737, 'A gas forms solid crystals on a cold surface. What additional fact would establish that deposition, rather than a process involving a liquid, has occurred?', 'text', 1, 'Focus on whether the substance has passed through the liquid state.', '{"why":"The starting and final states alone do not prove that the change was direct. The absence of an intermediate liquid state identifies deposition.","sol":"Step 1: Identify the initial state as gas.\nStep 2: Identify the final state as solid.\nStep 3: Determine whether a liquid state occurred between the two.","steps":["Step 1: Identify the initial state as gas.","Step 2: Identify the final state as solid.","Step 3: Determine whether a liquid state occurred between the two."],"options":[],"conceptId":"chemistry_matter_separation_deposition","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Deposition"}', 2),
  (2964, 737, 'Describe what happens to the thermal energy and state of a gas during deposition under suitable conditions.', 'text', 1, 'Think about energy transfer from the gas to its surroundings.', '{"why":"The energy loss allows particles to become part of the solid structure without first forming a liquid.","sol":"Step 1: State the direction of thermal energy transfer.\nStep 2: Explain the resulting change in particle energy.\nStep 3: Identify the final state.","steps":["Step 1: State the direction of thermal energy transfer.","Step 2: Explain the resulting change in particle energy.","Step 3: Identify the final state."],"options":[],"conceptId":"chemistry_matter_separation_deposition","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Deposition"}', 3),
  (2965, 737, 'A student observes frost and claims that water must first condense into liquid droplets and then freeze. Explain why this is not always correct.', 'text', 1, 'Consider whether water vapour can become solid ice directly.', '{"why":"Frost can form through deposition when water vapour becomes ice crystals directly. If liquid water forms first and then becomes ice, that describes a different sequence of state changes.","sol":"Step 1: Identify the starting state of the water as vapour.\nStep 2: Explain the direct gas-to-solid change.\nStep 3: Name the process that describes this direct change.","steps":["Step 1: Identify the starting state of the water as vapour.","Step 2: Explain the direct gas-to-solid change.","Step 3: Name the process that describes this direct change."],"options":[],"conceptId":"chemistry_matter_separation_deposition","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q5","subject":"chemistry","chapter":"matter_separation","topic":"Deposition"}', 4),
  (2966, 738, 'Define an element and explain why it cannot be broken down into simpler substances by ordinary chemical methods.', 'text', 1, 'Focus on the type of atom that makes up an element.', '{"why":"Chemical methods can separate or transform substances in appropriate reactions, but they cannot decompose an element into a simpler chemical substance.","sol":"Step 1: State what an element contains.\nStep 2: Explain whether its atoms represent one element or several different elements.\nStep 3: Connect this to the meaning of an element as a basic chemical substance.","steps":["Step 1: State what an element contains.","Step 2: Explain whether its atoms represent one element or several different elements.","Step 3: Connect this to the meaning of an element as a basic chemical substance."],"options":[],"conceptId":"chemistry_matter_separation_elements","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Elements"}', 0),
  (2967, 738, 'Oxygen gas has the formula O₂. Explain why it is an element even though each molecule contains two atoms.', 'text', 1, 'Count the types of atoms, not just the number of atoms.', '{"why":"The number of atoms in a molecule does not determine whether a substance is an element. The types of atoms present do.","sol":"Step 1: Interpret the subscript 2.\nStep 2: Identify the chemical identity of both atoms.\nStep 3: Compare the result with the definition of an element.","steps":["Step 1: Interpret the subscript 2.","Step 2: Identify the chemical identity of both atoms.","Step 3: Compare the result with the definition of an element."],"options":[],"conceptId":"chemistry_matter_separation_elements","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Elements"}', 1),
  (2968, 738, 'State the chemical symbols for hydrogen, oxygen, sodium, and iron.', 'text', 1, 'Recall the standard chemical symbol for each named element.', '{"why":"Chemical symbols provide a standard, concise way to represent elements. The letter capitalisation is part of the correct symbol.","sol":"Step 1: Match hydrogen with its symbol.\nStep 2: Match oxygen with its symbol.\nStep 3: Match sodium and iron with their symbols.","steps":["Step 1: Match hydrogen with its symbol.","Step 2: Match oxygen with its symbol.","Step 3: Match sodium and iron with their symbols."],"options":[],"conceptId":"chemistry_matter_separation_elements","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Elements"}', 2),
  (2969, 738, 'A sample contains only copper atoms. Explain why it is an element, and state the chemical symbol for copper.', 'text', 1, 'Identify the number of types of atoms in the sample.', '{"why":"A sample consisting of only one type of atom meets the definition of an element.","sol":"Step 1: Identify the atom in the sample.\nStep 2: Determine how many types of atoms are present.\nStep 3: Give the chemical symbol and apply the definition.","steps":["Step 1: Identify the atom in the sample.","Step 2: Determine how many types of atoms are present.","Step 3: Give the chemical symbol and apply the definition."],"options":[],"conceptId":"chemistry_matter_separation_elements","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Elements"}', 3),
  (2970, 738, 'Explain the difference between the symbols Co and CO. What does the difference in capitalisation tell you?', 'text', 1, 'Consider the complete symbol for an element and the symbols that can appear in a chemical formula.', '{"why":"Chemical symbols follow strict capitalisation rules. Co represents one element, cobalt, while CO represents a compound containing carbon and oxygen.","sol":"Step 1: Read Co as a two-letter element symbol.\nStep 2: Read CO as two chemical symbols written together.\nStep 3: Explain why capitalisation changes the interpretation.","steps":["Step 1: Read Co as a two-letter element symbol.","Step 2: Read CO as two chemical symbols written together.","Step 3: Explain why capitalisation changes the interpretation."],"options":[],"conceptId":"chemistry_matter_separation_elements","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q5","subject":"chemistry","chapter":"matter_separation","topic":"Elements"}', 4),
  (2971, 739, 'Define a compound and state the two key conditions that distinguish a compound from a substance made of only one element.', 'text', 1, 'Think about the number of elements and how their atoms are joined.', '{"why":"A compound has a definite chemical composition. Merely having different substances together does not mean that a compound has formed.","sol":"Step 1: State that a compound contains different elements.\nStep 2: Explain that the elements are chemically combined.\nStep 3: Mention that their proportions are fixed.","steps":["Step 1: State that a compound contains different elements.","Step 2: Explain that the elements are chemically combined.","Step 3: Mention that their proportions are fixed."],"options":[],"conceptId":"chemistry_matter_separation_compounds","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Compounds"}', 0),
  (2972, 739, 'Water has the formula H₂O. Explain what the formula tells you and why water is not an element.', 'text', 1, 'Identify each chemical symbol and interpret the subscript.', '{"why":"An element contains only one type of atom. Water contains both hydrogen and oxygen atoms chemically combined.","sol":"Step 1: Identify H as hydrogen and O as oxygen.\nStep 2: Interpret the subscript 2 on hydrogen.\nStep 3: Explain why the presence of two different elements makes water a compound.","steps":["Step 1: Identify H as hydrogen and O as oxygen.","Step 2: Interpret the subscript 2 on hydrogen.","Step 3: Explain why the presence of two different elements makes water a compound."],"options":[],"conceptId":"chemistry_matter_separation_compounds","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Compounds"}', 1),
  (2973, 739, 'Carbon dioxide has the formula CO₂. Calculate the ratio of carbon atoms to oxygen atoms in one molecule and explain why it is a compound.', 'text', 1, 'The absence of a subscript after C means one carbon atom.', '{"why":"The formula indicates a definite composition involving two different elements.","sol":"Step 1: Count the carbon atoms.\nStep 2: Count the oxygen atoms using the subscript.\nStep 3: Write the ratio in the order requested.","steps":["Step 1: Count the carbon atoms.","Step 2: Count the oxygen atoms using the subscript.","Step 3: Write the ratio in the order requested."],"options":[],"conceptId":"chemistry_matter_separation_compounds","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Compounds"}', 2),
  (2974, 739, 'Explain why filtration cannot ordinarily separate pure water into hydrogen and oxygen.', 'text', 1, 'Consider whether filtration separates particles by physical properties or breaks chemical bonds.', '{"why":"Filtration is a physical separation method used to separate an insoluble solid from a fluid. It does not ordinarily break the chemical bonds in water.","sol":"Step 1: Identify water as a compound.\nStep 2: Recall that hydrogen and oxygen are chemically bonded in water.\nStep 3: Explain what type of process is needed to decompose the compound.","steps":["Step 1: Identify water as a compound.","Step 2: Recall that hydrogen and oxygen are chemically bonded in water.","Step 3: Explain what type of process is needed to decompose the compound."],"options":[],"conceptId":"chemistry_matter_separation_compounds","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Compounds"}', 3),
  (2975, 739, 'Sodium reacts with chlorine to form sodium chloride. Explain why sodium chloride has properties different from those of its constituent elements.', 'text', 1, 'Consider what happens when elements chemically combine to form a new substance.', '{"why":"Chemical combination produces a compound with a distinct chemical structure and properties; the compound is not simply a physical collection of the original elements.","sol":"Step 1: Identify sodium and chlorine as the starting elements.\nStep 2: Explain that they react chemically to form a compound.\nStep 3: State how the resulting compound differs from the original elements.","steps":["Step 1: Identify sodium and chlorine as the starting elements.","Step 2: Explain that they react chemically to form a compound.","Step 3: State how the resulting compound differs from the original elements."],"options":[],"conceptId":"chemistry_matter_separation_compounds","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q5","subject":"chemistry","chapter":"matter_separation","topic":"Compounds"}', 4),
  (2976, 740, 'Define a mixture and explain why the proportions of its components can vary.', 'text', 1, 'Think about physical combination rather than chemical combination.', '{"why":"Unlike a compound, a mixture does not require a fixed ratio of components. For example, different amounts of salt can be dissolved in different amounts of water.","sol":"Step 1: Define how the components are combined.\nStep 2: Explain whether the components must react chemically.\nStep 3: State why their relative amounts are not fixed by one chemical formula.","steps":["Step 1: Define how the components are combined.","Step 2: Explain whether the components must react chemically.","Step 3: State why their relative amounts are not fixed by one chemical formula."],"options":[],"conceptId":"chemistry_matter_separation_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Mixtures"}', 0),
  (2977, 740, 'Explain why salt water is a mixture rather than a compound.', 'text', 1, 'Identify the two components and consider whether dissolving them creates one new compound.', '{"why":"The salt exists as dissolved ions in water. The physical combination has variable composition rather than the fixed formula of a single compound.","sol":"Step 1: Identify salt and water as the components.\nStep 2: Explain what happens to the salt during dissolving.\nStep 3: State why the resulting composition can vary.","steps":["Step 1: Identify salt and water as the components.","Step 2: Explain what happens to the salt during dissolving.","Step 3: State why the resulting composition can vary."],"options":[],"conceptId":"chemistry_matter_separation_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Mixtures"}', 1),
  (2978, 740, 'Air contains nitrogen, oxygen, and other gases. Explain two reasons why air is classified as a mixture.', 'text', 1, 'Consider the number of substances present and whether the proportions are fixed.', '{"why":"A mixture contains multiple substances physically combined. Its overall composition does not have to follow one fixed chemical formula.","sol":"Step 1: Identify the different gases in air.\nStep 2: Explain that they are present together rather than chemically combined into one compound.\nStep 3: Describe how the proportions of some components can vary.","steps":["Step 1: Identify the different gases in air.","Step 2: Explain that they are present together rather than chemically combined into one compound.","Step 3: Describe how the proportions of some components can vary."],"options":[],"conceptId":"chemistry_matter_separation_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Mixtures"}', 2),
  (2979, 740, 'A student mixes iron filings with sand without heating or causing a chemical reaction. Explain why the result is a mixture and identify a suitable physical separation method.', 'text', 1, 'Consider whether the iron and sand have formed a new compound and whether one component has a special physical property.', '{"why":"Iron is attracted to a magnet under ordinary conditions, while sand is not. Their different magnetic properties allow physical separation.","sol":"Step 1: Identify iron and sand as the components.\nStep 2: Explain why simply mixing them does not form a new compound.\nStep 3: Use the magnetic properties of iron to choose a method.","steps":["Step 1: Identify iron and sand as the components.","Step 2: Explain why simply mixing them does not form a new compound.","Step 3: Use the magnetic properties of iron to choose a method."],"options":[],"conceptId":"chemistry_matter_separation_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Mixtures"}', 3),
  (2980, 740, 'A mixture contains sand and water. Describe a suitable separation method and explain what is collected as the residue and the filtrate.', 'text', 1, 'Choose a method that retains an insoluble solid while allowing liquid through.', '{"why":"Filtration separates an insoluble solid from a liquid using a filter medium that retains the solid particles.","sol":"Step 1: Identify sand as insoluble in water.\nStep 2: Choose filtration.\nStep 3: Name the material retained by the filter and the liquid that passes through.","steps":["Step 1: Identify sand as insoluble in water.","Step 2: Choose filtration.","Step 3: Name the material retained by the filter and the liquid that passes through."],"options":[],"conceptId":"chemistry_matter_separation_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q5","subject":"chemistry","chapter":"matter_separation","topic":"Mixtures"}', 4),
  (2981, 741, 'Define a homogeneous mixture and explain what is meant by uniform composition throughout a sample.', 'text', 1, 'Consider what would be found in equal portions taken from different places.', '{"why":"Uniform composition means that the components are evenly distributed at the scale being considered. The mixture still contains more than one substance.","sol":"Step 1: Define a homogeneous mixture.\nStep 2: Explain how its components are distributed.\nStep 3: Describe what equal portions of the uniform sample contain.","steps":["Step 1: Define a homogeneous mixture.","Step 2: Explain how its components are distributed.","Step 3: Describe what equal portions of the uniform sample contain."],"options":[],"conceptId":"chemistry_matter_separation_homogeneous_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Homogeneous Mixtures"}', 0),
  (2982, 741, 'In a salt solution, identify the solute and the solvent. Explain why the solution is classified as a homogeneous mixture when the salt is fully dissolved and uniformly distributed.', 'text', 1, 'Identify which substance dissolves and which substance does the dissolving.', '{"why":"A solution is a homogeneous mixture. Its components remain present in a uniform physical combination rather than becoming one new compound.","sol":"Step 1: Identify sodium chloride as the substance being dissolved.\nStep 2: Identify water as the dissolving medium.\nStep 3: Explain how the dissolved salt is distributed throughout the solution.","steps":["Step 1: Identify sodium chloride as the substance being dissolved.","Step 2: Identify water as the dissolving medium.","Step 3: Explain how the dissolved salt is distributed throughout the solution."],"options":[],"conceptId":"chemistry_matter_separation_homogeneous_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Homogeneous Mixtures"}', 1),
  (2983, 741, 'A student takes equal volumes of a well-mixed sugar solution from the top and bottom of a container. Explain what should be true about the sugar concentration in the two portions and why.', 'text', 1, 'Use the meaning of uniform composition.', '{"why":"A homogeneous solution has uniform composition throughout the sample when it is properly mixed and remains uniform.","sol":"Step 1: Identify the sample as a well-mixed solution.\nStep 2: Apply the definition of a homogeneous mixture.\nStep 3: Compare the composition of equal portions from different positions.","steps":["Step 1: Identify the sample as a well-mixed solution.","Step 2: Apply the definition of a homogeneous mixture.","Step 3: Compare the composition of equal portions from different positions."],"options":[],"conceptId":"chemistry_matter_separation_homogeneous_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Homogeneous Mixtures"}', 2),
  (2984, 741, 'Water is added to a uniform salt solution and the solution is stirred thoroughly. Explain how the concentration changes and why the resulting solution can still be homogeneous.', 'text', 1, 'Track the amount of dissolved salt and the amount of water.', '{"why":"Homogeneity refers to uniform composition, not to having a particular concentration. A diluted solution can still be uniform.","sol":"Step 1: State that additional water increases the amount of solvent.\nStep 2: Assume no salt is added or removed and explain the effect on concentration.\nStep 3: Explain what thorough mixing does to the distribution of the dissolved salt.","steps":["Step 1: State that additional water increases the amount of solvent.","Step 2: Assume no salt is added or removed and explain the effect on concentration.","Step 3: Explain what thorough mixing does to the distribution of the dissolved salt."],"options":[],"conceptId":"chemistry_matter_separation_homogeneous_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Homogeneous Mixtures"}', 3),
  (2985, 741, 'Explain why well-mixed air can be a homogeneous mixture even though it contains several different gases.', 'text', 1, 'Consider the distribution of the gases, not whether there is more than one gas.', '{"why":"A homogeneous mixture can contain several substances. What matters is that its composition is uniform throughout the sample.","sol":"Step 1: Name at least two gases present in air.\nStep 2: Explain how they are distributed in a well-mixed sample.\nStep 3: Connect the uniform distribution to the definition of a homogeneous mixture.","steps":["Step 1: Name at least two gases present in air.","Step 2: Explain how they are distributed in a well-mixed sample.","Step 3: Connect the uniform distribution to the definition of a homogeneous mixture."],"options":[],"conceptId":"chemistry_matter_separation_homogeneous_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q5","subject":"chemistry","chapter":"matter_separation","topic":"Homogeneous Mixtures"}', 4),
  (2986, 742, 'Define a heterogeneous mixture and explain what is meant by its composition being non-uniform.', 'text', 1, 'Consider whether different portions contain the same proportions of components.', '{"why":"The defining feature is non-uniform composition. The components may be visible, but visible separation is not essential to the definition.","sol":"Step 1: State that a heterogeneous mixture contains more than one substance.\nStep 2: Explain that its composition is not uniform throughout.\nStep 3: Describe how different portions can differ in composition.","steps":["Step 1: State that a heterogeneous mixture contains more than one substance.","Step 2: Explain that its composition is not uniform throughout.","Step 3: Describe how different portions can differ in composition."],"options":[],"conceptId":"chemistry_matter_separation_heterogeneous_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Heterogeneous Mixtures"}', 0),
  (2987, 742, 'A container contains sand and water. Explain why the mixture is heterogeneous even if the sand has settled at the bottom.', 'text', 1, 'Consider the composition of the upper liquid and the material at the bottom.', '{"why":"Settling makes the differences between the portions especially clear. The mixture remains a physical combination of sand and water.","sol":"Step 1: Identify sand and water as the components.\nStep 2: Explain that the sand remains separate from the water.\nStep 3: Compare the composition of the upper and lower portions.","steps":["Step 1: Identify sand and water as the components.","Step 2: Explain that the sand remains separate from the water.","Step 3: Compare the composition of the upper and lower portions."],"options":[],"conceptId":"chemistry_matter_separation_heterogeneous_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Heterogeneous Mixtures"}', 1),
  (2988, 742, 'Oil and water form two layers after standing. Explain what the layers tell you about the composition of the mixture.', 'text', 1, 'Identify the main component in each layer.', '{"why":"A heterogeneous mixture does not have a uniform composition throughout. The separate layers demonstrate this non-uniformity.","sol":"Step 1: Identify oil and water as the two components.\nStep 2: Describe the composition of the two layers.\nStep 3: Connect the different compositions to the definition.","steps":["Step 1: Identify oil and water as the two components.","Step 2: Describe the composition of the two layers.","Step 3: Connect the different compositions to the definition."],"options":[],"conceptId":"chemistry_matter_separation_heterogeneous_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Heterogeneous Mixtures"}', 2),
  (2989, 742, 'A piece of granite contains different mineral grains. Explain why the composition of one region of the rock may differ from that of another region.', 'text', 1, 'Think about the different minerals present in the grains.', '{"why":"The different mineral components are physically present together, and their distribution varies across the rock.","sol":"Step 1: Identify the visible mineral grains.\nStep 2: Explain that different regions may contain different minerals or proportions.\nStep 3: Use the variation in composition to classify the sample.","steps":["Step 1: Identify the visible mineral grains.","Step 2: Explain that different regions may contain different minerals or proportions.","Step 3: Use the variation in composition to classify the sample."],"options":[],"conceptId":"chemistry_matter_separation_heterogeneous_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Heterogeneous Mixtures"}', 3),
  (2990, 742, 'Must every heterogeneous mixture have components that are easily visible to the naked eye? Explain your answer.', 'text', 1, 'Distinguish between the definition of a heterogeneous mixture and one way of observing it.', '{"why":"Visible layers and particles can help identify heterogeneity, but the underlying criterion is variation in composition throughout the sample.","sol":"Step 1: Recall the defining feature of a heterogeneous mixture.\nStep 2: Consider whether composition can vary at a scale smaller than the naked eye can resolve.\nStep 3: State whether visibility is essential.","steps":["Step 1: Recall the defining feature of a heterogeneous mixture.","Step 2: Consider whether composition can vary at a scale smaller than the naked eye can resolve.","Step 3: State whether visibility is essential."],"options":[],"conceptId":"chemistry_matter_separation_heterogeneous_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q5","subject":"chemistry","chapter":"matter_separation","topic":"Heterogeneous Mixtures"}', 4),
  (2991, 743, 'Define a pure substance and explain why a pure substance can be either an element or a compound.', 'text', 1, 'Focus on the number of chemical substances present, not just the number of elements.', '{"why":"Purity means that only one chemical substance is present. It does not mean that the substance must contain only one type of element.","sol":"Step 1: Define a pure substance in terms of its chemical identity and composition.\nStep 2: Describe the composition of an element.\nStep 3: Describe the composition of a compound.","steps":["Step 1: Define a pure substance in terms of its chemical identity and composition.","Step 2: Describe the composition of an element.","Step 3: Describe the composition of a compound."],"options":[],"conceptId":"chemistry_matter_separation_identifying_pure_substances","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Identifying Pure Substances"}', 0),
  (2992, 743, 'A sample contains only H₂O molecules. Explain why it is pure but is not an element.', 'text', 1, 'Ask whether the sample contains one chemical substance and whether its molecules contain one type of atom.', '{"why":"Pure substances include compounds as well as elements. The presence of two different elements in each molecule makes water a compound.","sol":"Step 1: Identify the substance represented by H₂O.\nStep 2: Determine whether another chemical substance is present.\nStep 3: Identify the different elements within each water molecule.","steps":["Step 1: Identify the substance represented by H₂O.","Step 2: Determine whether another chemical substance is present.","Step 3: Identify the different elements within each water molecule."],"options":[],"conceptId":"chemistry_matter_separation_identifying_pure_substances","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Identifying Pure Substances"}', 1),
  (2993, 743, 'A clear, colourless liquid is tested and found to contain dissolved salt. Can its appearance be used to identify it as a pure substance? Explain.', 'text', 1, 'Consider whether a dissolved substance must be visible.', '{"why":"Appearance alone cannot establish purity. A dissolved substance can be distributed throughout a liquid without being visible.","sol":"Step 1: Identify the substances present in the liquid.\nStep 2: Consider whether dissolved salt can be visible.\nStep 3: Use the actual composition rather than appearance to classify the sample.","steps":["Step 1: Identify the substances present in the liquid.","Step 2: Consider whether dissolved salt can be visible.","Step 3: Use the actual composition rather than appearance to classify the sample."],"options":[],"conceptId":"chemistry_matter_separation_identifying_pure_substances","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Identifying Pure Substances"}', 2),
  (2994, 743, 'At the same pressure, a solid sample melts over a broad temperature range. Explain what this may suggest and why the observation is not conclusive by itself.', 'text', 1, 'Compare the usual melting behaviour of a pure crystalline substance with that of many mixtures.', '{"why":"Many mixtures melt over a range of temperatures, while a pure crystalline substance commonly melts over a narrow range at a specified pressure. Experimental conditions and the nature of the material must also be considered.","sol":"Step 1: Describe the melting behaviour observed.\nStep 2: Explain what a broad melting range can suggest.\nStep 3: State why additional evidence is needed.","steps":["Step 1: Describe the melting behaviour observed.","Step 2: Explain what a broad melting range can suggest.","Step 3: State why additional evidence is needed."],"options":[],"conceptId":"chemistry_matter_separation_identifying_pure_substances","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Identifying Pure Substances"}', 3),
  (2995, 743, 'A student says that every pure substance is an element. Use one example to show why this statement is incorrect.', 'text', 1, 'Choose a pure compound and explain its composition.', '{"why":"A pure substance is defined by having one chemical substance present. That substance may be an element or a compound.","sol":"Step 1: State what an element contains.\nStep 2: Identify a pure compound.\nStep 3: Explain why the compound is pure but not an element.","steps":["Step 1: State what an element contains.","Step 2: Identify a pure compound.","Step 3: Explain why the compound is pure but not an element."],"options":[],"conceptId":"chemistry_matter_separation_identifying_pure_substances","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q5","subject":"chemistry","chapter":"matter_separation","topic":"Identifying Pure Substances"}', 4),
  (2996, 744, 'State three pieces of evidence that can help you identify a mixture.', 'text', 1, 'Consider composition, proportions, and physical separation.', '{"why":"These clues support the conclusion that the sample is a physical combination of substances. Not every clue must be available in every investigation.","sol":"Step 1: Identify the number of substances present.\nStep 2: Consider whether the component proportions can vary.\nStep 3: Consider whether suitable physical methods can separate the components.","steps":["Step 1: Identify the number of substances present.","Step 2: Consider whether the component proportions can vary.","Step 3: Consider whether suitable physical methods can separate the components."],"options":[],"conceptId":"chemistry_matter_separation_identifying_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Identifying Mixtures"}', 0),
  (2997, 744, 'Two salt solutions contain different concentrations of salt. Explain why both can be classified as mixtures.', 'text', 1, 'Compare their components and the proportions in which those components are present.', '{"why":"Mixtures do not have a single fixed ratio of components. Changing the relative amounts of salt and water does not automatically create a different compound.","sol":"Step 1: Identify the components in each solution.\nStep 2: Compare the relative amounts of salt and water.\nStep 3: Explain why variable proportions are consistent with a mixture.","steps":["Step 1: Identify the components in each solution.","Step 2: Compare the relative amounts of salt and water.","Step 3: Explain why variable proportions are consistent with a mixture."],"options":[],"conceptId":"chemistry_matter_separation_identifying_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Identifying Mixtures"}', 1),
  (2998, 744, 'Iron filings are mixed with sand. A magnet removes the iron from the sample. Explain why this result supports classifying the original sample as a mixture.', 'text', 1, 'Consider the identities of the materials before and after separation.', '{"why":"The physical separation shows that the components retain their identities and can be separated by exploiting a difference in physical properties.","sol":"Step 1: Identify iron and sand as the original components.\nStep 2: Explain why the magnet attracts the iron.\nStep 3: Describe what the separation demonstrates about the components.","steps":["Step 1: Identify iron and sand as the original components.","Step 2: Explain why the magnet attracts the iron.","Step 3: Describe what the separation demonstrates about the components."],"options":[],"conceptId":"chemistry_matter_separation_identifying_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Identifying Mixtures"}', 2),
  (2999, 744, 'A clear liquid appears to contain only one substance, but testing confirms that it contains water and dissolved salt. Explain why its appearance is not enough to classify it as pure.', 'text', 1, 'Consider what can happen when a substance dissolves completely.', '{"why":"Dissolved components may not be visible. Composition is more reliable than appearance alone when identifying a mixture.","sol":"Step 1: Describe the liquid''s appearance.\nStep 2: Identify the substances established by testing.\nStep 3: Classify the sample using its composition rather than appearance.","steps":["Step 1: Describe the liquid''s appearance.","Step 2: Identify the substances established by testing.","Step 3: Classify the sample using its composition rather than appearance."],"options":[],"conceptId":"chemistry_matter_separation_identifying_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Identifying Mixtures"}', 3),
  (3000, 744, 'Explain why a mixture can be homogeneous or heterogeneous, and state the difference between these two types.', 'text', 1, 'Focus on the uniformity of composition throughout the sample.', '{"why":"The terms homogeneous and heterogeneous describe how the components are distributed, not whether the sample contains only one substance.","sol":"Step 1: Define the uniformity of a homogeneous mixture.\nStep 2: Define the uniformity of a heterogeneous mixture.\nStep 3: Explain why both can still be mixtures.","steps":["Step 1: Define the uniformity of a homogeneous mixture.","Step 2: Define the uniformity of a heterogeneous mixture.","Step 3: Explain why both can still be mixtures."],"options":[],"conceptId":"chemistry_matter_separation_identifying_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q5","subject":"chemistry","chapter":"matter_separation","topic":"Identifying Mixtures"}', 4);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (3001, 745, 'A mixture contains sand and water. It is filtered using filter paper. Identify the residue and the filtrate, and explain why each is found there.', 'text', 1, 'Identify which substance is insoluble and which substance can pass through the filter paper.', '{"why":"Filtration retains suitable insoluble solid particles while the liquid passes through the filter paper.","sol":"Step 1: Sand is insoluble in water.\nStep 2: The sand particles are retained by the filter paper.\nStep 3: Water passes through the paper into the receiving container.","steps":["Step 1: Sand is insoluble in water.","Step 2: The sand particles are retained by the filter paper.","Step 3: Water passes through the paper into the receiving container."],"options":[],"conceptId":"chemistry_matter_separation_filtration","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Filtration"}', 0),
  (3002, 745, 'A learner filters a mixture of chalk powder and water. Describe what happens to the chalk powder and the water.', 'text', 1, 'Think about whether chalk powder dissolves in water.', '{"why":"Filtration separates the insoluble chalk particles from the liquid.","sol":"Step 1: Chalk powder is insoluble in water.\nStep 2: Its particles are retained on the filter paper.\nStep 3: Water passes through the paper into the receiving container.","steps":["Step 1: Chalk powder is insoluble in water.","Step 2: Its particles are retained on the filter paper.","Step 3: Water passes through the paper into the receiving container."],"options":[],"conceptId":"chemistry_matter_separation_filtration","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Filtration"}', 1),
  (3003, 745, 'A learner attempts to separate dissolved salt from salt solution using ordinary filter paper. Explain why the method fails.', 'text', 1, 'Consider what happens to substances after they dissolve.', '{"why":"Filtration separates insoluble solids, not substances dissolved in a liquid.","sol":"Step 1: The salt has dissolved in the water.\nStep 2: The dissolved salt particles pass through ordinary filter paper with the water.\nStep 3: The filter paper therefore does not retain the dissolved salt.","steps":["Step 1: The salt has dissolved in the water.","Step 2: The dissolved salt particles pass through ordinary filter paper with the water.","Step 3: The filter paper therefore does not retain the dissolved salt."],"options":[],"conceptId":"chemistry_matter_separation_filtration","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Filtration"}', 2),
  (3004, 745, 'After filtering a mixture, a learner finds solid material on the filter paper and liquid in the receiving container. Name both products and state how each was formed.', 'text', 1, 'Use the terms residue and filtrate.', '{"why":"These names describe the two products obtained during filtration.","sol":"Step 1: The solid retained on the filter paper is called the residue.\nStep 2: The liquid that passes through the paper is called the filtrate.\nStep 3: The products are identified by where they are collected.","steps":["Step 1: The solid retained on the filter paper is called the residue.","Step 2: The liquid that passes through the paper is called the filtrate.","Step 3: The products are identified by where they are collected."],"options":[],"conceptId":"chemistry_matter_separation_filtration","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Filtration"}', 3),
  (3005, 745, 'A mixture contains water and an insoluble solid. Describe the apparatus arrangement and procedure needed to separate the solid from the water by filtration.', 'text', 1, 'Include the filter paper, funnel and receiving container.', '{"why":"The apparatus supports the filter paper and collects the liquid that passes through it.","sol":"Step 1: Place folded filter paper inside a filter funnel.\nStep 2: Position the funnel over a clean receiving container.\nStep 3: Pour the mixture carefully into the funnel.\nStep 4: Allow the liquid to pass through while the insoluble solid remains on the paper.","steps":["Step 1: Place folded filter paper inside a filter funnel.","Step 2: Position the funnel over a clean receiving container.","Step 3: Pour the mixture carefully into the funnel.","Step 4: Allow the liquid to pass through while the insoluble solid remains on the paper."],"options":[],"conceptId":"chemistry_matter_separation_filtration","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q5","subject":"chemistry","chapter":"matter_separation","topic":"Filtration"}', 4),
  (3006, 746, 'Describe the main steps used to obtain crystals of a soluble solid from its solution by crystallisation.', 'text', 1, 'Include concentration, cooling, crystal collection and drying.', '{"why":"Concentration and cooling can cause dissolved substance to leave the solution as crystals.","sol":"Step 1: Warm the solution if needed to dissolve the solid.\nStep 2: Evaporate some solvent to make the solution concentrated.\nStep 3: Allow the solution to cool so crystals can form.\nStep 4: Separate the crystals from the remaining liquid.\nStep 5: Dry the crystals appropriately.","steps":["Step 1: Warm the solution if needed to dissolve the solid.","Step 2: Evaporate some solvent to make the solution concentrated.","Step 3: Allow the solution to cool so crystals can form.","Step 4: Separate the crystals from the remaining liquid.","Step 5: Dry the crystals appropriately."],"options":[],"conceptId":"chemistry_matter_separation_crystallisation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Crystallisation"}', 0),
  (3007, 746, 'Explain why crystals may form when a hot concentrated solution is allowed to cool.', 'text', 1, 'Consider how the solubility of many solids changes with temperature.', '{"why":"Crystals form when the solution can no longer keep all the substance dissolved under the new conditions.","sol":"Step 1: The solid is dissolved in the hot solution.\nStep 2: As the solution cools, the solubility of many solids decreases.\nStep 3: The solvent can no longer keep as much of the substance dissolved.\nStep 4: Excess dissolved substance forms crystals.","steps":["Step 1: The solid is dissolved in the hot solution.","Step 2: As the solution cools, the solubility of many solids decreases.","Step 3: The solvent can no longer keep as much of the substance dissolved.","Step 4: Excess dissolved substance forms crystals."],"options":[],"conceptId":"chemistry_matter_separation_crystallisation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Crystallisation"}', 1),
  (3008, 746, 'A learner cools a dilute solution and obtains very few crystals. Explain one likely reason and describe an improvement.', 'text', 1, 'Compare the amount of dissolved solid with the amount of solvent.', '{"why":"Crystallisation is more effective when the solution contains enough dissolved substance to form crystals under the cooling conditions.","sol":"Step 1: A dilute solution contains a relatively small amount of dissolved solid.\nStep 2: Cooling may leave most of that solid dissolved.\nStep 3: Carefully evaporating some solvent increases the concentration.\nStep 4: Cooling the concentrated solution may then produce more crystals.","steps":["Step 1: A dilute solution contains a relatively small amount of dissolved solid.","Step 2: Cooling may leave most of that solid dissolved.","Step 3: Carefully evaporating some solvent increases the concentration.","Step 4: Cooling the concentrated solution may then produce more crystals."],"options":[],"conceptId":"chemistry_matter_separation_crystallisation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Crystallisation"}', 2),
  (3009, 746, 'State the difference between crystallisation and evaporating a solution completely to dryness.', 'text', 1, 'Compare the aim of the two processes and how the solid is obtained.', '{"why":"The methods have different aims and do not necessarily produce the solid in the same form.","sol":"Step 1: Crystallisation usually involves concentrating a solution and allowing crystals to form, often by cooling.\nStep 2: Evaporating to dryness aims to remove nearly all the solvent.\nStep 3: Crystallisation aims to obtain crystals, while evaporation to dryness leaves the solid residue.","steps":["Step 1: Crystallisation usually involves concentrating a solution and allowing crystals to form, often by cooling.","Step 2: Evaporating to dryness aims to remove nearly all the solvent.","Step 3: Crystallisation aims to obtain crystals, while evaporation to dryness leaves the solid residue."],"options":[],"conceptId":"chemistry_matter_separation_crystallisation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Crystallisation"}', 3),
  (3010, 746, 'A learner heats a solution strongly until it is completely dry, although the aim is to obtain well-formed crystals. Explain why this may be a poor procedure.', 'text', 1, 'Think about the purpose of cooling and the effect of excessive heating.', '{"why":"The conditions should be chosen to obtain crystals without unnecessarily overheating the substance.","sol":"Step 1: Crystallisation generally uses a concentrated solution that is allowed to cool.\nStep 2: Strong heating until dryness does not provide the same controlled crystal-forming stage.\nStep 3: Some substances may also be damaged by excessive heating.\nStep 4: The learner should concentrate the solution carefully and allow crystals to form during cooling.","steps":["Step 1: Crystallisation generally uses a concentrated solution that is allowed to cool.","Step 2: Strong heating until dryness does not provide the same controlled crystal-forming stage.","Step 3: Some substances may also be damaged by excessive heating.","Step 4: The learner should concentrate the solution carefully and allow crystals to form during cooling."],"options":[],"conceptId":"chemistry_matter_separation_crystallisation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q5","subject":"chemistry","chapter":"matter_separation","topic":"Crystallisation"}', 4),
  (3011, 747, 'Describe how simple distillation can be used to obtain water from salt solution.', 'text', 1, 'Follow the water from the flask to the receiving container.', '{"why":"Simple distillation vaporises the solvent and then condenses it so it can be collected as a liquid.","sol":"Step 1: Place the salt solution in a distillation flask.\nStep 2: Heat the solution so that water vaporises.\nStep 3: Pass the water vapour through a cooled condenser.\nStep 4: The vapour condenses into liquid water.\nStep 5: Collect the liquid in the receiving container.","steps":["Step 1: Place the salt solution in a distillation flask.","Step 2: Heat the solution so that water vaporises.","Step 3: Pass the water vapour through a cooled condenser.","Step 4: The vapour condenses into liquid water.","Step 5: Collect the liquid in the receiving container."],"options":[],"conceptId":"chemistry_matter_separation_simple_distillation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Simple Distillation"}', 0),
  (3012, 747, 'During the simple distillation of salt solution, identify the distillate and explain why solid salt is not normally collected with it.', 'text', 1, 'Compare the behaviour of water and dissolved salt when the solution is heated.', '{"why":"The method separates the volatile liquid from a dissolved solid and collects the liquid after condensation.","sol":"Step 1: Water vaporises from the heated salt solution.\nStep 2: The dissolved salt remains in the flask under normal distillation conditions.\nStep 3: Water vapour enters the condenser and cools.\nStep 4: The condensed water collects in the receiving container.","steps":["Step 1: Water vaporises from the heated salt solution.","Step 2: The dissolved salt remains in the flask under normal distillation conditions.","Step 3: Water vapour enters the condenser and cools.","Step 4: The condensed water collects in the receiving container."],"options":[],"conceptId":"chemistry_matter_separation_simple_distillation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Simple Distillation"}', 1),
  (3013, 747, 'State the function of the condenser in simple distillation and explain what may happen if it is not cooled adequately.', 'text', 1, 'Consider the change from vapour to liquid.', '{"why":"Condensation requires the vapour to lose heat.","sol":"Step 1: The vapour enters the condenser after leaving the heated flask.\nStep 2: The condenser removes heat from the vapour.\nStep 3: The vapour condenses into liquid.\nStep 4: Without adequate cooling, some vapour may fail to condense and less distillate may be collected.","steps":["Step 1: The vapour enters the condenser after leaving the heated flask.","Step 2: The condenser removes heat from the vapour.","Step 3: The vapour condenses into liquid.","Step 4: Without adequate cooling, some vapour may fail to condense and less distillate may be collected."],"options":[],"conceptId":"chemistry_matter_separation_simple_distillation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Simple Distillation"}', 2),
  (3014, 747, 'Explain one important difference between simple distillation and evaporation in an open dish when separating salt solution.', 'text', 1, 'Ask whether the water is collected in each method.', '{"why":"Simple distillation is useful when the solvent must be recovered as well as separated from the dissolved solid.","sol":"Step 1: In open-dish evaporation, water escapes as vapour into the surroundings.\nStep 2: In simple distillation, water vapour is directed into a condenser.\nStep 3: The condenser changes the vapour back into liquid water.\nStep 4: The liquid water is collected as the distillate.","steps":["Step 1: In open-dish evaporation, water escapes as vapour into the surroundings.","Step 2: In simple distillation, water vapour is directed into a condenser.","Step 3: The condenser changes the vapour back into liquid water.","Step 4: The liquid water is collected as the distillate."],"options":[],"conceptId":"chemistry_matter_separation_simple_distillation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Simple Distillation"}', 3),
  (3015, 747, 'Name four main pieces of apparatus used in simple distillation and state the function of each.', 'text', 1, 'Include the flask, heat source, condenser and receiving container.', '{"why":"Each piece of apparatus performs a different stage of the separation and collection process.","sol":"Step 1: The distillation flask holds the solution.\nStep 2: The heat source supplies energy to vaporise the liquid.\nStep 3: The condenser cools the vapour so it becomes liquid.\nStep 4: The receiving container collects the distillate.","steps":["Step 1: The distillation flask holds the solution.","Step 2: The heat source supplies energy to vaporise the liquid.","Step 3: The condenser cools the vapour so it becomes liquid.","Step 4: The receiving container collects the distillate."],"options":[],"conceptId":"chemistry_matter_separation_simple_distillation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q5","subject":"chemistry","chapter":"matter_separation","topic":"Simple Distillation"}', 4),
  (3016, 748, 'Two miscible liquids have boiling points of 78°C and 82°C. Select a suitable distillation method and explain why it is appropriate.', 'text', 1, 'Compare the boiling points and consider the role of a fractionating column.', '{"why":"The fractionating column improves the separation of components with relatively close boiling points.","sol":"Step 1: The liquids are miscible, so they form one liquid mixture.\nStep 2: Their boiling points differ by only 4°C.\nStep 3: A fractionating column allows repeated vaporisation and condensation.\nStep 4: These repeated processes improve separation of the liquids.","steps":["Step 1: The liquids are miscible, so they form one liquid mixture.","Step 2: Their boiling points differ by only 4°C.","Step 3: A fractionating column allows repeated vaporisation and condensation.","Step 4: These repeated processes improve separation of the liquids."],"options":[],"conceptId":"chemistry_matter_separation_fractional_distillation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Fractional Distillation"}', 0),
  (3017, 748, 'A mixture contains two miscible liquids with boiling points of 60°C and 95°C. Identify the more volatile liquid and explain which component is generally enriched in the early vapour.', 'text', 1, 'The lower boiling point generally indicates the more volatile component.', '{"why":"The more volatile component tends to enter the vapour phase more readily.","sol":"Step 1: Compare 60°C and 95°C.\nStep 2: The liquid boiling at 60°C has the lower boiling point.\nStep 3: It is generally more volatile.\nStep 4: The early vapour is generally richer in this component.","steps":["Step 1: Compare 60°C and 95°C.","Step 2: The liquid boiling at 60°C has the lower boiling point.","Step 3: It is generally more volatile.","Step 4: The early vapour is generally richer in this component."],"options":[],"conceptId":"chemistry_matter_separation_fractional_distillation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Fractional Distillation"}', 1),
  (3018, 748, 'Explain two functions of the fractionating column during fractional distillation.', 'text', 1, 'Think about what happens when vapour meets cooler surfaces inside the column.', '{"why":"Repeated equilibrium processes make the vapour reaching the condenser richer in the more volatile component.","sol":"Step 1: The column provides surfaces where rising vapour can condense.\nStep 2: The condensed liquid may vaporise again as it is heated.\nStep 3: Repeated vaporisation and condensation enrich the rising vapour in the more volatile component.","steps":["Step 1: The column provides surfaces where rising vapour can condense.","Step 2: The condensed liquid may vaporise again as it is heated.","Step 3: Repeated vaporisation and condensation enrich the rising vapour in the more volatile component."],"options":[],"conceptId":"chemistry_matter_separation_fractional_distillation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Fractional Distillation"}', 2),
  (3019, 748, 'A learner uses fractional distillation to separate two miscible liquids but collects an impure fraction. Give two possible reasons why the separation may be incomplete.', 'text', 1, 'Consider the boiling points and the operating conditions.', '{"why":"Fractional distillation improves separation but does not guarantee completely pure fractions in every situation.","sol":"Step 1: The liquids may have boiling points that are very close together.\nStep 2: The fractionating column may not provide sufficient effective separation.\nStep 3: The heating rate or collection conditions may also be unsuitable.","steps":["Step 1: The liquids may have boiling points that are very close together.","Step 2: The fractionating column may not provide sufficient effective separation.","Step 3: The heating rate or collection conditions may also be unsuitable."],"options":[],"conceptId":"chemistry_matter_separation_fractional_distillation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Fractional Distillation"}', 3),
  (3020, 748, 'State the functions of the condenser and receiving container in fractional distillation.', 'text', 1, 'Follow the vapour after it leaves the fractionating column.', '{"why":"Condensation makes the separated vapour available for collection as a liquid.","sol":"Step 1: Vapour leaving the column enters the condenser.\nStep 2: The condenser removes heat and turns the vapour into liquid.\nStep 3: The receiving container collects the liquid fraction.","steps":["Step 1: Vapour leaving the column enters the condenser.","Step 2: The condenser removes heat and turns the vapour into liquid.","Step 3: The receiving container collects the liquid fraction."],"options":[],"conceptId":"chemistry_matter_separation_fractional_distillation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q5","subject":"chemistry","chapter":"matter_separation","topic":"Fractional Distillation"}', 4),
  (3021, 749, 'A black ink sample produces four distinct spots during paper chromatography. What can you conclude about the sample, and what can you not conclude with certainty?', 'text', 1, 'Interpret the number of distinct spots without claiming more than the evidence shows.', '{"why":"Chromatography separates detectable components, but some substances may overlap or remain undetected.","sol":"Step 1: Four distinct spots appear on the chromatogram.\nStep 2: Each spot represents a component that behaves differently under the conditions used.\nStep 3: The sample therefore contains at least four detectable components under those conditions.\nStep 4: The result does not necessarily identify every substance or prove that no other components are present.","steps":["Step 1: Four distinct spots appear on the chromatogram.","Step 2: Each spot represents a component that behaves differently under the conditions used.","Step 3: The sample therefore contains at least four detectable components under those conditions.","Step 4: The result does not necessarily identify every substance or prove that no other components are present."],"options":[],"conceptId":"chemistry_matter_separation_chromatography","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Chromatography"}', 0),
  (3022, 749, 'Explain why a pencil baseline is used instead of an ordinary ink baseline in paper chromatography.', 'text', 1, 'Consider whether the baseline material could dissolve in the mobile phase.', '{"why":"The baseline should not introduce additional substances that interfere with the separation.","sol":"Step 1: The solvent travels through the paper.\nStep 2: Ordinary ink may dissolve and separate into its own components.\nStep 3: Those components could form extra spots.\nStep 4: Graphite from a pencil generally does not dissolve in the solvent used.","steps":["Step 1: The solvent travels through the paper.","Step 2: Ordinary ink may dissolve and separate into its own components.","Step 3: Those components could form extra spots.","Step 4: Graphite from a pencil generally does not dissolve in the solvent used."],"options":[],"conceptId":"chemistry_matter_separation_chromatography","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Chromatography"}', 1),
  (3023, 749, 'A learner places the sample spot below the solvent level before starting paper chromatography. Explain why this is incorrect and how to correct it.', 'text', 1, 'Consider where the sample may go if it is submerged.', '{"why":"The solvent should carry the sample through the paper, not wash the starting spot into the reservoir.","sol":"Step 1: The sample spot is submerged in the solvent reservoir.\nStep 2: The sample may dissolve directly into the reservoir.\nStep 3: It may therefore fail to travel up the paper in the intended way.\nStep 4: Raise the paper or lower the solvent until the baseline is above the solvent level.","steps":["Step 1: The sample spot is submerged in the solvent reservoir.","Step 2: The sample may dissolve directly into the reservoir.","Step 3: It may therefore fail to travel up the paper in the intended way.","Step 4: Raise the paper or lower the solvent until the baseline is above the solvent level."],"options":[],"conceptId":"chemistry_matter_separation_chromatography","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Chromatography"}', 2),
  (3024, 749, 'Two samples produce spots at the same position when run under the same chromatography conditions. What does this suggest, and why is it not absolute proof that the substances are identical?', 'text', 1, 'Think about what a matching spot position can show and its limitations.', '{"why":"A chromatogram provides evidence for identification, but matching positions alone do not always prove identity.","sol":"Step 1: The components have travelled similar distances under the same conditions.\nStep 2: This provides evidence that the components may be the same substance.\nStep 3: Different substances can sometimes have similar movement under one set of conditions.\nStep 4: Additional evidence or a different suitable test may be needed for a firm identification.","steps":["Step 1: The components have travelled similar distances under the same conditions.","Step 2: This provides evidence that the components may be the same substance.","Step 3: Different substances can sometimes have similar movement under one set of conditions.","Step 4: Additional evidence or a different suitable test may be needed for a firm identification."],"options":[],"conceptId":"chemistry_matter_separation_chromatography","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Chromatography"}', 3),
  (3025, 749, 'Describe the main steps for separating the components of a soluble dye mixture using paper chromatography.', 'text', 1, 'Include the baseline, sample spot, solvent and final chromatogram.', '{"why":"The components move differently through the stationary paper as the mobile solvent carries them.","sol":"Step 1: Draw a pencil baseline near the bottom of the paper.\nStep 2: Place a small spot of the dye mixture on the baseline.\nStep 3: Place the paper in a suitable solvent with the baseline above the solvent level.\nStep 4: Allow the solvent to rise through the paper and carry the components.\nStep 5: Remove the paper before the solvent reaches the top, mark the solvent front and observe the separated spots.","steps":["Step 1: Draw a pencil baseline near the bottom of the paper.","Step 2: Place a small spot of the dye mixture on the baseline.","Step 3: Place the paper in a suitable solvent with the baseline above the solvent level.","Step 4: Allow the solvent to rise through the paper and carry the components.","Step 5: Remove the paper before the solvent reaches the top, mark the solvent front and observe the separated spots."],"options":[],"conceptId":"chemistry_matter_separation_chromatography","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q5","subject":"chemistry","chapter":"matter_separation","topic":"Chromatography"}', 4),
  (3026, 750, 'Describe how decantation can be used to separate sand from water after the mixture has been left undisturbed.', 'text', 1, 'Explain what must happen to the sand before the liquid is poured away.', '{"why":"Decantation separates the upper liquid from a solid that has settled at the bottom.","sol":"Step 1: Leave the mixture undisturbed so the sand can settle.\nStep 2: Keep the settled sand at the bottom of the container.\nStep 3: Tilt the container carefully.\nStep 4: Pour the water into another container without disturbing the sand.","steps":["Step 1: Leave the mixture undisturbed so the sand can settle.","Step 2: Keep the settled sand at the bottom of the container.","Step 3: Tilt the container carefully.","Step 4: Pour the water into another container without disturbing the sand."],"options":[],"conceptId":"chemistry_matter_separation_decantation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Decantation"}', 0),
  (3027, 750, 'Oil and water form two layers in a container. Explain how decantation may be used to separate them and state one precaution.', 'text', 1, 'Consider the separate layers and how pouring could mix them.', '{"why":"Immiscible liquids form separate layers that can be separated by careful pouring, although a separating funnel may give better control.","sol":"Step 1: Allow the oil and water to form distinct layers.\nStep 2: Identify which layer is to be collected.\nStep 3: Pour the desired layer carefully into another container.\nStep 4: Avoid disturbing the boundary between the layers.","steps":["Step 1: Allow the oil and water to form distinct layers.","Step 2: Identify which layer is to be collected.","Step 3: Pour the desired layer carefully into another container.","Step 4: Avoid disturbing the boundary between the layers."],"options":[],"conceptId":"chemistry_matter_separation_decantation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Decantation"}', 1),
  (3028, 750, 'A learner decants water from settled mud, but the collected water is still cloudy. Explain why the separation was incomplete.', 'text', 1, 'Consider whether all the particles settled before pouring.', '{"why":"Decantation is less effective when solid particles do not settle sufficiently.","sol":"Step 1: Some fine mud particles may remain suspended.\nStep 2: These particles do not all settle during the available time.\nStep 3: The suspended particles are carried into the receiving container with the water.","steps":["Step 1: Some fine mud particles may remain suspended.","Step 2: These particles do not all settle during the available time.","Step 3: The suspended particles are carried into the receiving container with the water."],"options":[],"conceptId":"chemistry_matter_separation_decantation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Decantation"}', 2),
  (3029, 750, 'State one advantage and one limitation of decantation when separating an insoluble solid from a liquid.', 'text', 1, 'Consider simplicity and how much solid may remain in the collected liquid.', '{"why":"Decantation is convenient when settling occurs, but it does not guarantee a particle-free liquid.","sol":"Step 1: Decantation requires relatively simple apparatus.\nStep 2: It can quickly remove much of the liquid above a settled solid.\nStep 3: However, suspended fine particles may be carried into the collected liquid.","steps":["Step 1: Decantation requires relatively simple apparatus.","Step 2: It can quickly remove much of the liquid above a settled solid.","Step 3: However, suspended fine particles may be carried into the collected liquid."],"options":[],"conceptId":"chemistry_matter_separation_decantation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Decantation"}', 3),
  (3030, 750, 'Explain why a mixture of sand and water should be left undisturbed before decantation.', 'text', 1, 'Think about the position of the sand particles.', '{"why":"Settling creates a clearer boundary between the solid and the liquid.","sol":"Step 1: When the mixture is disturbed, sand particles may remain suspended.\nStep 2: When it is left still, the particles can settle under gravity.\nStep 3: The clearer water above the settled sand can then be poured away more easily.","steps":["Step 1: When the mixture is disturbed, sand particles may remain suspended.","Step 2: When it is left still, the particles can settle under gravity.","Step 3: The clearer water above the settled sand can then be poured away more easily."],"options":[],"conceptId":"chemistry_matter_separation_decantation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q5","subject":"chemistry","chapter":"matter_separation","topic":"Decantation"}', 4),
  (3031, 751, 'Describe how a mixture of iron filings and sulfur powder can be separated using a magnet.', 'text', 1, 'Identify which material is attracted to an ordinary magnet.', '{"why":"The method uses the difference in magnetic behaviour between iron and sulfur.","sol":"Step 1: Iron is attracted to the magnet.\nStep 2: Sulfur is not attracted in the same way.\nStep 3: Bring the magnet close to the mixture.\nStep 4: Collect the attracted iron filings and leave the sulfur behind.","steps":["Step 1: Iron is attracted to the magnet.","Step 2: Sulfur is not attracted in the same way.","Step 3: Bring the magnet close to the mixture.","Step 4: Collect the attracted iron filings and leave the sulfur behind."],"options":[],"conceptId":"chemistry_matter_separation_magnetic_separation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Magnetic Separation"}', 0),
  (3032, 751, 'A learner tries to separate iron filings from sand using a magnet. Explain why the method works.', 'text', 1, 'Compare the magnetic behaviour of iron and ordinary sand.', '{"why":"Magnetic separation is effective when one component is magnetic and the other is non-magnetic.","sol":"Step 1: Iron is attracted to an ordinary magnet.\nStep 2: Ordinary sand is not attracted in the same way.\nStep 3: The magnet collects the iron while most of the sand remains behind.","steps":["Step 1: Iron is attracted to an ordinary magnet.","Step 2: Ordinary sand is not attracted in the same way.","Step 3: The magnet collects the iron while most of the sand remains behind."],"options":[],"conceptId":"chemistry_matter_separation_magnetic_separation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Magnetic Separation"}', 1),
  (3033, 751, 'Explain why an ordinary magnet cannot effectively separate sulfur powder from ordinary sand.', 'text', 1, 'Consider whether either component is attracted strongly enough for selective collection.', '{"why":"Magnetic separation requires a useful difference in magnetic behaviour between the components.","sol":"Step 1: Sulfur is not attracted strongly to an ordinary magnet in the way iron is.\nStep 2: Ordinary sand is also not attracted in the same way.\nStep 3: The magnet cannot selectively collect one component from the other.","steps":["Step 1: Sulfur is not attracted strongly to an ordinary magnet in the way iron is.","Step 2: Ordinary sand is also not attracted in the same way.","Step 3: The magnet cannot selectively collect one component from the other."],"options":[],"conceptId":"chemistry_matter_separation_magnetic_separation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Magnetic Separation"}', 2),
  (3034, 751, 'A learner assumes that every metal in a mixture can be removed using a magnet. Explain why this assumption is incorrect and give one example.', 'text', 1, 'Distinguish between being a metal and being attracted to an ordinary magnet.', '{"why":"The method depends on magnetic behaviour, not simply on whether a substance is a metal.","sol":"Step 1: Different metals have different magnetic properties.\nStep 2: An ordinary magnet strongly attracts iron but does not attract all metals in the same way.\nStep 3: Aluminium and copper are examples of metals that are not attracted in the same way as iron.","steps":["Step 1: Different metals have different magnetic properties.","Step 2: An ordinary magnet strongly attracts iron but does not attract all metals in the same way.","Step 3: Aluminium and copper are examples of metals that are not attracted in the same way as iron."],"options":[],"conceptId":"chemistry_matter_separation_magnetic_separation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Magnetic Separation"}', 3),
  (3035, 751, 'Describe one way to make it easier to remove iron filings collected on a magnet after separating them from sand.', 'text', 1, 'Consider using a removable covering around the magnet.', '{"why":"The covering makes it easier to detach the collected iron without changing the separation principle, provided the covering is thin enough.","sol":"Step 1: Place a suitable thin covering, such as paper, around the magnet before collecting the iron.\nStep 2: Bring the covered magnet close to the mixture.\nStep 3: The iron filings are attracted to the magnet through the covering.\nStep 4: Move the magnet away and remove the covering so the filings can be released more easily.","steps":["Step 1: Place a suitable thin covering, such as paper, around the magnet before collecting the iron.","Step 2: Bring the covered magnet close to the mixture.","Step 3: The iron filings are attracted to the magnet through the covering.","Step 4: Move the magnet away and remove the covering so the filings can be released more easily."],"options":[],"conceptId":"chemistry_matter_separation_magnetic_separation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q5","subject":"chemistry","chapter":"matter_separation","topic":"Magnetic Separation"}', 4),
  (3036, 752, 'Name the three main subatomic particles and give the relative charge and location of each.', 'text', 1, 'Focus on the core principle of Structure of the Atom.', '{"why":"The charge and location of each particle help explain atomic mass, electrical neutrality and ion formation.","sol":"Step 1: Identify the positively charged particle: the proton, with relative charge +1.\nStep 2: Identify the neutral particle: the neutron, with relative charge 0.\nStep 3: Identify the negatively charged particle: the electron, with relative charge -1.\nStep 4: State their locations. Protons and neutrons are in the nucleus; electrons occupy energy levels around it.","steps":["Step 1: Identify the positively charged particle: the proton, with relative charge +1.","Step 2: Identify the neutral particle: the neutron, with relative charge 0.","Step 3: Identify the negatively charged particle: the electron, with relative charge -1.","Step 4: State their locations. Protons and neutrons are in the nucleus; electrons occupy energy levels around it."],"options":[],"conceptId":"chemistry_atomic_structure_structure_of_the_atom","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q1","subject":"chemistry","chapter":"atomic_structure","topic":"Structure of the Atom"}', 0),
  (3037, 752, 'An atom contains 8 protons, 8 neutrons and 8 electrons. Calculate its net relative charge.', 'text', 1, 'Focus on the core principle of Structure of the Atom.', '{"why":"Equal numbers of protons and electrons cancel each other''s charges.","sol":"Step 1: Protons contribute 8 x (+1) = +8.\nStep 2: Electrons contribute 8 x (-1) = -8.\nStep 3: Neutrons contribute 8 x 0 = 0.\nStep 4: Net charge = +8 - 8 + 0 = 0.","steps":["Step 1: Protons contribute 8 x (+1) = +8.","Step 2: Electrons contribute 8 x (-1) = -8.","Step 3: Neutrons contribute 8 x 0 = 0.","Step 4: Net charge = +8 - 8 + 0 = 0."],"options":[],"conceptId":"chemistry_atomic_structure_structure_of_the_atom","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q2","subject":"chemistry","chapter":"atomic_structure","topic":"Structure of the Atom"}', 1),
  (3038, 752, 'A particle contains 12 protons and 10 electrons. Calculate its net relative charge and explain the sign.', 'text', 1, 'Focus on the core principle of Structure of the Atom.', '{"why":"The net charge is the total positive charge minus the total negative charge.","sol":"Step 1: Total positive charge = 12 x (+1) = +12.\nStep 2: Total negative charge = 10 x (-1) = -10.\nStep 3: Net charge = +12 + (-10) = +2.\nStep 4: The result is positive because there are two more protons than electrons.","steps":["Step 1: Total positive charge = 12 x (+1) = +12.","Step 2: Total negative charge = 10 x (-1) = -10.","Step 3: Net charge = +12 + (-10) = +2.","Step 4: The result is positive because there are two more protons than electrons."],"options":[],"conceptId":"chemistry_atomic_structure_structure_of_the_atom","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q3","subject":"chemistry","chapter":"atomic_structure","topic":"Structure of the Atom"}', 2),
  (3039, 752, 'A particle contains 15 protons, 16 neutrons and 13 electrons. Calculate its net relative charge.', 'text', 1, 'Multiply the number of protons and electrons by their respective relative charges.', '{"why":"The particle has two more protons than electrons. Neutrons do not contribute to electrical charge.","sol":"Step 1: Positive charge = 15 x (+1) = +15.\nStep 2: Negative charge = 13 x (-1) = -13.\nStep 3: Neutrons contribute zero charge.\nStep 4: Net charge = +15 - 13 = +2.","steps":["Step 1: Positive charge = 15 x (+1) = +15.","Step 2: Negative charge = 13 x (-1) = -13.","Step 3: Neutrons contribute zero charge.","Step 4: Net charge = +15 - 13 = +2."],"options":[],"conceptId":"chemistry_atomic_structure_structure_of_the_atom","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q4","subject":"chemistry","chapter":"atomic_structure","topic":"Structure of the Atom"}', 3),
  (3040, 752, 'An atom has 19 protons and 19 electrons. Explain why it remains neutral even if its number of neutrons changes.', 'text', 1, 'Separate the effect of neutrons on mass from the effect of protons and electrons on charge.', '{"why":"Electrical charge depends on the balance between protons and electrons, not the number of neutrons.","sol":"Step 1: The 19 protons contribute +19.\nStep 2: The 19 electrons contribute -19.\nStep 3: Net charge = +19 - 19 = 0.\nStep 4: Any number of neutrons contributes zero electrical charge.\nStep 5: Changing the neutron number changes the mass number but not the net charge.","steps":["Step 1: The 19 protons contribute +19.","Step 2: The 19 electrons contribute -19.","Step 3: Net charge = +19 - 19 = 0.","Step 4: Any number of neutrons contributes zero electrical charge.","Step 5: Changing the neutron number changes the mass number but not the net charge."],"options":[],"conceptId":"chemistry_atomic_structure_structure_of_the_atom","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q5","subject":"chemistry","chapter":"atomic_structure","topic":"Structure of the Atom"}', 4),
  (3041, 752, 'A learner says that an atom with 11 protons, 12 neutrons and 10 electrons is neutral because it contains neutrons. Evaluate the claim and calculate the correct charge.', 'text', 1, 'Neutrons have no charge. Calculate the total charge of the protons and electrons.', '{"why":"Neutrality requires equal numbers of protons and electrons. Neutrons do not balance electrical charge.","sol":"Step 1: The 11 protons contribute +11.\nStep 2: The 10 electrons contribute -10.\nStep 3: The 12 neutrons contribute zero charge.\nStep 4: Net charge = +11 - 10 = +1.\nStep 5: The claim is incorrect because neutrons cannot cancel the extra positive charge.","steps":["Step 1: The 11 protons contribute +11.","Step 2: The 10 electrons contribute -10.","Step 3: The 12 neutrons contribute zero charge.","Step 4: Net charge = +11 - 10 = +1.","Step 5: The claim is incorrect because neutrons cannot cancel the extra positive charge."],"options":[],"conceptId":"chemistry_atomic_structure_structure_of_the_atom","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q6","subject":"chemistry","chapter":"atomic_structure","topic":"Structure of the Atom"}', 5),
  (3042, 752, 'A particle has a net relative charge of -2 and contains 18 protons. Calculate the number of electrons it contains.', 'text', 1, 'Use net charge = number of protons - number of electrons.', '{"why":"A negative charge means the particle has more electrons than protons.","sol":"Step 1: Let the number of electrons be e.\nStep 2: -2 = 18 - e.\nStep 3: Add e to both sides: e - 2 = 18.\nStep 4: Add 2 to both sides: e = 20.\nStep 5: Check: 18 - 20 = -2.","steps":["Step 1: Let the number of electrons be e.","Step 2: -2 = 18 - e.","Step 3: Add e to both sides: e - 2 = 18.","Step 4: Add 2 to both sides: e = 20.","Step 5: Check: 18 - 20 = -2."],"options":[],"conceptId":"chemistry_atomic_structure_structure_of_the_atom","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q7","subject":"chemistry","chapter":"atomic_structure","topic":"Structure of the Atom"}', 6),
  (3043, 752, 'A particle has 16 protons and a net relative charge of +3. Calculate its number of electrons and explain your answer.', 'text', 1, 'A positive ion has fewer electrons than protons.', '{"why":"Three fewer electrons than protons produce a net relative charge of +3.","sol":"Step 1: Let the number of electrons be e.\nStep 2: +3 = 16 - e.\nStep 3: Rearrange to obtain e = 16 - 3.\nStep 4: Therefore, e = 13.\nStep 5: Check: 16 - 13 = +3.","steps":["Step 1: Let the number of electrons be e.","Step 2: +3 = 16 - e.","Step 3: Rearrange to obtain e = 16 - 3.","Step 4: Therefore, e = 13.","Step 5: Check: 16 - 13 = +3."],"options":[],"conceptId":"chemistry_atomic_structure_structure_of_the_atom","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q8","subject":"chemistry","chapter":"atomic_structure","topic":"Structure of the Atom"}', 7),
  (3044, 752, 'An atom gains one electron but its nucleus remains unchanged. Explain what changes and what remains the same.', 'text', 1, 'Consider the proton number, neutron number, electron number and charge.', '{"why":"Ordinary ion formation involves gaining or losing electrons, not changing the nucleus.","sol":"Step 1: Gaining one electron increases the electron number by one.\nStep 2: The proton number remains unchanged because no nuclear particle has changed.\nStep 3: The neutron number also remains unchanged.\nStep 4: The additional electron adds one unit of negative charge.\nStep 5: If the atom was initially neutral, it now has a net charge of -1.","steps":["Step 1: Gaining one electron increases the electron number by one.","Step 2: The proton number remains unchanged because no nuclear particle has changed.","Step 3: The neutron number also remains unchanged.","Step 4: The additional electron adds one unit of negative charge.","Step 5: If the atom was initially neutral, it now has a net charge of -1."],"options":[],"conceptId":"chemistry_atomic_structure_structure_of_the_atom","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q9","subject":"chemistry","chapter":"atomic_structure","topic":"Structure of the Atom"}', 8),
  (3045, 753, 'Define a proton and state its relative charge, relative mass and location.', 'text', 1, 'Focus on the core principle of Protons.', '{"why":"These properties distinguish protons from neutrons and electrons.","sol":"Step 1: Define a proton as a positively charged subatomic particle.\nStep 2: State its relative charge as +1.\nStep 3: State its approximate relative mass as 1.\nStep 4: State that it is found in the nucleus.","steps":["Step 1: Define a proton as a positively charged subatomic particle.","Step 2: State its relative charge as +1.","Step 3: State its approximate relative mass as 1.","Step 4: State that it is found in the nucleus."],"options":[],"conceptId":"chemistry_atomic_structure_protons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q1","subject":"chemistry","chapter":"atomic_structure","topic":"Protons"}', 0),
  (3046, 753, 'An atom has 12 protons. Determine its atomic number and identify the element.', 'text', 1, 'Focus on the core principle of Protons.', '{"why":"Each element has a unique proton number.","sol":"Step 1: Atomic number equals the number of protons.\nStep 2: Atomic number = 12.\nStep 3: The element with atomic number 12 is magnesium.","steps":["Step 1: Atomic number equals the number of protons.","Step 2: Atomic number = 12.","Step 3: The element with atomic number 12 is magnesium."],"options":[],"conceptId":"chemistry_atomic_structure_protons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q2","subject":"chemistry","chapter":"atomic_structure","topic":"Protons"}', 1),
  (3047, 753, 'Explain why an atom with 8 protons cannot be a carbon atom.', 'text', 1, 'Focus on the core principle of Protons.', '{"why":"Element identity is determined by proton number, not by the total number of particles.","sol":"Step 1: Carbon has atomic number 6.\nStep 2: Therefore, every carbon atom has 6 protons.\nStep 3: An atom with 8 protons has atomic number 8.\nStep 4: Atomic number 8 belongs to oxygen.","steps":["Step 1: Carbon has atomic number 6.","Step 2: Therefore, every carbon atom has 6 protons.","Step 3: An atom with 8 protons has atomic number 8.","Step 4: Atomic number 8 belongs to oxygen."],"options":[],"conceptId":"chemistry_atomic_structure_protons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q3","subject":"chemistry","chapter":"atomic_structure","topic":"Protons"}', 2),
  (3048, 753, 'A neutral atom has 13 protons. Identify the element and calculate its number of electrons.', 'text', 1, 'Use the proton number to identify the element, then apply the rule for a neutral atom.', '{"why":"Atomic number identifies the element, while neutrality determines the electron count.","sol":"Step 1: Atomic number = 13.\nStep 2: Element 13 is aluminium (Al).\nStep 3: A neutral atom has equal numbers of protons and electrons.\nStep 4: Number of electrons = 13.","steps":["Step 1: Atomic number = 13.","Step 2: Element 13 is aluminium (Al).","Step 3: A neutral atom has equal numbers of protons and electrons.","Step 4: Number of electrons = 13."],"options":[],"conceptId":"chemistry_atomic_structure_protons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q4","subject":"chemistry","chapter":"atomic_structure","topic":"Protons"}', 3),
  (3049, 753, 'Particle X has 16 protons and particle Y has 17 protons. Identify both elements and explain why they are different.', 'text', 1, 'Use the periodic table''s atomic numbers.', '{"why":"A one-proton difference changes the atomic number and therefore the element.","sol":"Step 1: Atomic number 16 identifies sulfur (S).\nStep 2: Atomic number 17 identifies chlorine (Cl).\nStep 3: Their proton numbers differ by one.\nStep 4: Different proton numbers mean different elemental identities.","steps":["Step 1: Atomic number 16 identifies sulfur (S).","Step 2: Atomic number 17 identifies chlorine (Cl).","Step 3: Their proton numbers differ by one.","Step 4: Different proton numbers mean different elemental identities."],"options":[],"conceptId":"chemistry_atomic_structure_protons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q5","subject":"chemistry","chapter":"atomic_structure","topic":"Protons"}', 4),
  (3050, 753, 'An atom gains two electrons but retains 11 protons. Identify the element and explain whether its identity changes.', 'text', 1, 'Electrons determine charge; protons determine element identity.', '{"why":"Changing the electron number changes charge, not the identity of the element.","sol":"Step 1: The proton number remains 11.\nStep 2: Atomic number 11 identifies sodium.\nStep 3: Gaining electrons changes the electron number, not the proton number.\nStep 4: The particle remains sodium, although it becomes a negatively charged ion if it gains electrons from a neutral atom.","steps":["Step 1: The proton number remains 11.","Step 2: Atomic number 11 identifies sodium.","Step 3: Gaining electrons changes the electron number, not the proton number.","Step 4: The particle remains sodium, although it becomes a negatively charged ion if it gains electrons from a neutral atom."],"options":[],"conceptId":"chemistry_atomic_structure_protons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q6","subject":"chemistry","chapter":"atomic_structure","topic":"Protons"}', 5),
  (3051, 753, 'A learner claims that an atom with 20 neutrons must be calcium. Explain why the claim is insufficient to identify the element.', 'text', 1, 'Which subatomic particle determines atomic number?', '{"why":"Neutron number alone does not determine elemental identity.","sol":"Step 1: The neutron number contributes to the mass number.\nStep 2: Different elements can contain the same number of neutrons.\nStep 3: The element is identified by its proton number.\nStep 4: Without the proton number, the element cannot be identified uniquely.","steps":["Step 1: The neutron number contributes to the mass number.","Step 2: Different elements can contain the same number of neutrons.","Step 3: The element is identified by its proton number.","Step 4: Without the proton number, the element cannot be identified uniquely."],"options":[],"conceptId":"chemistry_atomic_structure_protons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q7","subject":"chemistry","chapter":"atomic_structure","topic":"Protons"}', 6),
  (3052, 753, 'An ion contains 12 protons and 10 electrons. Identify its element and calculate its charge.', 'text', 1, 'Use protons for the element and protons minus electrons for the charge.', '{"why":"The proton number identifies magnesium, while the two-electron deficit gives the +2 charge.","sol":"Step 1: Atomic number = 12, so the element is magnesium.\nStep 2: Positive charge = +12.\nStep 3: Negative charge = -10.\nStep 4: Net charge = +12 - 10 = +2.","steps":["Step 1: Atomic number = 12, so the element is magnesium.","Step 2: Positive charge = +12.","Step 3: Negative charge = -10.","Step 4: Net charge = +12 - 10 = +2."],"options":[],"conceptId":"chemistry_atomic_structure_protons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q8","subject":"chemistry","chapter":"atomic_structure","topic":"Protons"}', 7),
  (3053, 753, 'An atom has 9 protons and 10 neutrons. It then loses one electron. Explain why it is still the same element and state the new charge if the original atom was neutral.', 'text', 1, 'Separate the change in electron number from the proton number.', '{"why":"Ion formation changes electrons, whereas elemental identity depends on protons.","sol":"Step 1: The atom has 9 protons, so its atomic number is 9.\nStep 2: Element 9 is fluorine.\nStep 3: Losing one electron leaves one fewer electron than proton.\nStep 4: The resulting net charge is +1.\nStep 5: The proton number remains 9, so the element remains fluorine.","steps":["Step 1: The atom has 9 protons, so its atomic number is 9.","Step 2: Element 9 is fluorine.","Step 3: Losing one electron leaves one fewer electron than proton.","Step 4: The resulting net charge is +1.","Step 5: The proton number remains 9, so the element remains fluorine."],"options":[],"conceptId":"chemistry_atomic_structure_protons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q9","subject":"chemistry","chapter":"atomic_structure","topic":"Protons"}', 8),
  (3054, 754, 'Define a neutron and state its relative charge, relative mass and location.', 'text', 1, 'Focus on the core principle of Neutrons.', '{"why":"Neutrons add to atomic mass without contributing to electrical charge.","sol":"Step 1: A neutron is a subatomic particle in the nucleus.\nStep 2: Its relative charge is zero.\nStep 3: Its approximate relative mass is 1.","steps":["Step 1: A neutron is a subatomic particle in the nucleus.","Step 2: Its relative charge is zero.","Step 3: Its approximate relative mass is 1."],"options":[],"conceptId":"chemistry_atomic_structure_neutrons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q1","subject":"chemistry","chapter":"atomic_structure","topic":"Neutrons"}', 0),
  (3055, 754, 'An atom has mass number 23 and atomic number 11. Calculate its neutron number.', 'text', 1, 'Focus on the core principle of Neutrons.', '{"why":"The mass number is the sum of protons and neutrons.","sol":"Step 1: Neutrons = mass number - atomic number.\nStep 2: n = 23 - 11.\nStep 3: n = 12.","steps":["Step 1: Neutrons = mass number - atomic number.","Step 2: n = 23 - 11.","Step 3: n = 12."],"options":[],"conceptId":"chemistry_atomic_structure_neutrons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q2","subject":"chemistry","chapter":"atomic_structure","topic":"Neutrons"}', 1),
  (3056, 754, 'An atom contains 15 protons and 16 neutrons. Calculate its mass number.', 'text', 1, 'Focus on the core principle of Neutrons.', '{"why":"Both protons and neutrons contribute approximately one unit of relative mass.","sol":"Step 1: Mass number = protons + neutrons.\nStep 2: A = 15 + 16.\nStep 3: A = 31.","steps":["Step 1: Mass number = protons + neutrons.","Step 2: A = 15 + 16.","Step 3: A = 31."],"options":[],"conceptId":"chemistry_atomic_structure_neutrons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q3","subject":"chemistry","chapter":"atomic_structure","topic":"Neutrons"}', 2),
  (3057, 754, 'An atom has mass number 40 and atomic number 20. Calculate its number of neutrons and verify the result.', 'text', 1, 'Subtract the atomic number from the mass number.', '{"why":"The answer is correct because the proton and neutron counts add up to the given mass number.","sol":"Step 1: n = A - Z.\nStep 2: n = 40 - 20 = 20.\nStep 3: Check: protons + neutrons = 20 + 20 = 40.","steps":["Step 1: n = A - Z.","Step 2: n = 40 - 20 = 20.","Step 3: Check: protons + neutrons = 20 + 20 = 40."],"options":[],"conceptId":"chemistry_atomic_structure_neutrons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q4","subject":"chemistry","chapter":"atomic_structure","topic":"Neutrons"}', 3),
  (3058, 754, 'An atom contains 17 protons and 18 neutrons. Calculate its mass number and identify the element.', 'text', 1, 'Add the nuclear particles to find mass number; use protons to identify the element.', '{"why":"Mass number uses both nuclear particles, whereas element identity depends only on proton number.","sol":"Step 1: A = 17 + 18 = 35.\nStep 2: Atomic number = 17.\nStep 3: Atomic number 17 is chlorine.","steps":["Step 1: A = 17 + 18 = 35.","Step 2: Atomic number = 17.","Step 3: Atomic number 17 is chlorine."],"options":[],"conceptId":"chemistry_atomic_structure_neutrons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q5","subject":"chemistry","chapter":"atomic_structure","topic":"Neutrons"}', 4),
  (3059, 754, 'An atom has mass number 27 and contains 13 protons. Calculate its neutron number and explain the calculation.', 'text', 1, 'The mass number is the total of protons and neutrons.', '{"why":"Subtracting the known proton number from the total nuclear particle count gives the neutron number.","sol":"Step 1: A = Z + n.\nStep 2: Rearrange: n = A - Z.\nStep 3: n = 27 - 13 = 14.\nStep 4: Check: 13 + 14 = 27.","steps":["Step 1: A = Z + n.","Step 2: Rearrange: n = A - Z.","Step 3: n = 27 - 13 = 14.","Step 4: Check: 13 + 14 = 27."],"options":[],"conceptId":"chemistry_atomic_structure_neutrons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q6","subject":"chemistry","chapter":"atomic_structure","topic":"Neutrons"}', 5),
  (3060, 754, 'An atom contains 12 neutrons and has mass number 23. Calculate its proton number and identify the element.', 'text', 1, 'Rearrange A = Z + n to make Z the subject.', '{"why":"The mass number is divided between protons and neutrons. The proton number identifies the element.","sol":"Step 1: A = Z + n.\nStep 2: Rearrange: Z = A - n.\nStep 3: Z = 23 - 12 = 11.\nStep 4: Atomic number 11 identifies sodium.","steps":["Step 1: A = Z + n.","Step 2: Rearrange: Z = A - n.","Step 3: Z = 23 - 12 = 11.","Step 4: Atomic number 11 identifies sodium."],"options":[],"conceptId":"chemistry_atomic_structure_neutrons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q7","subject":"chemistry","chapter":"atomic_structure","topic":"Neutrons"}', 6),
  (3061, 754, 'Two atoms have the same mass number of 40. Atom A has 18 protons and atom B has 20 protons. Calculate the neutron number of each and explain why their neutron numbers differ.', 'text', 1, 'Calculate n = A - Z separately for each atom.', '{"why":"A fixed mass number does not uniquely determine the proton and neutron numbers.","sol":"Step 1: Atom A: n = 40 - 18 = 22.\nStep 2: Atom B: n = 40 - 20 = 20.\nStep 3: Atom A has 22 neutrons; atom B has 20.\nStep 4: Both have 40 nuclear particles, but the proportions of protons and neutrons differ.","steps":["Step 1: Atom A: n = 40 - 18 = 22.","Step 2: Atom B: n = 40 - 20 = 20.","Step 3: Atom A has 22 neutrons; atom B has 20.","Step 4: Both have 40 nuclear particles, but the proportions of protons and neutrons differ."],"options":[],"conceptId":"chemistry_atomic_structure_neutrons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q8","subject":"chemistry","chapter":"atomic_structure","topic":"Neutrons"}', 7),
  (3062, 754, 'A learner calculates neutrons for an atom with mass number 31 and atomic number 15 as 31 + 15 = 46. Identify the error and provide the correct answer.', 'text', 1, 'Remember that the mass number already includes the protons.', '{"why":"The mass number is already the combined total of protons and neutrons.","sol":"Step 1: Recall A = Z + n.\nStep 2: The learner added the proton number to a total that already includes protons.\nStep 3: Rearrange to n = A - Z.\nStep 4: n = 31 - 15 = 16.\nStep 5: Verify: 15 + 16 = 31.","steps":["Step 1: Recall A = Z + n.","Step 2: The learner added the proton number to a total that already includes protons.","Step 3: Rearrange to n = A - Z.","Step 4: n = 31 - 15 = 16.","Step 5: Verify: 15 + 16 = 31."],"options":[],"conceptId":"chemistry_atomic_structure_neutrons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q9","subject":"chemistry","chapter":"atomic_structure","topic":"Neutrons"}', 8),
  (3063, 755, 'State the relative charge, relative mass and location of an electron.', 'text', 1, 'Focus on the core principle of Electrons.', '{"why":"Electrons carry negative charge and have much less mass than protons and neutrons.","sol":"Step 1: Its relative charge is -1.\nStep 2: Its relative mass is approximately 1/1840.\nStep 3: It occupies energy levels around the nucleus.","steps":["Step 1: Its relative charge is -1.","Step 2: Its relative mass is approximately 1/1840.","Step 3: It occupies energy levels around the nucleus."],"options":[],"conceptId":"chemistry_atomic_structure_electrons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q1","subject":"chemistry","chapter":"atomic_structure","topic":"Electrons"}', 0),
  (3064, 755, 'A neutral atom has atomic number 8. Calculate its number of electrons.', 'text', 1, 'Focus on the core principle of Electrons.', '{"why":"Equal positive and negative charges give a net charge of zero.","sol":"Step 1: Atomic number = number of protons = 8.\nStep 2: Neutrality requires equal numbers of protons and electrons.\nStep 3: Electron number = 8.","steps":["Step 1: Atomic number = number of protons = 8.","Step 2: Neutrality requires equal numbers of protons and electrons.","Step 3: Electron number = 8."],"options":[],"conceptId":"chemistry_atomic_structure_electrons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q2","subject":"chemistry","chapter":"atomic_structure","topic":"Electrons"}', 1),
  (3065, 755, 'A neutral atom loses two electrons. Explain how its electrical charge changes.', 'text', 1, 'Focus on the core principle of Electrons.', '{"why":"Removing negative charges leaves an excess of positive charge.","sol":"Step 1: Initially, the proton and electron numbers are equal.\nStep 2: Losing two electrons removes two units of negative charge.\nStep 3: The proton number remains unchanged.\nStep 4: The resulting net charge is +2.","steps":["Step 1: Initially, the proton and electron numbers are equal.","Step 2: Losing two electrons removes two units of negative charge.","Step 3: The proton number remains unchanged.","Step 4: The resulting net charge is +2."],"options":[],"conceptId":"chemistry_atomic_structure_electrons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q3","subject":"chemistry","chapter":"atomic_structure","topic":"Electrons"}', 2),
  (3066, 755, 'A neutral atom has atomic number 15. It gains three electrons. Calculate its final electron number and net charge.', 'text', 1, 'Begin with 15 electrons, then account for the three gained electrons.', '{"why":"Gaining three electrons creates three more negative charges than positive charges.","sol":"Step 1: Initial electron number = 15.\nStep 2: Final electron number = 15 + 3 = 18.\nStep 3: Proton number remains 15.\nStep 4: Charge = 15 - 18 = -3.","steps":["Step 1: Initial electron number = 15.","Step 2: Final electron number = 15 + 3 = 18.","Step 3: Proton number remains 15.","Step 4: Charge = 15 - 18 = -3."],"options":[],"conceptId":"chemistry_atomic_structure_electrons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q4","subject":"chemistry","chapter":"atomic_structure","topic":"Electrons"}', 3),
  (3067, 755, 'A particle contains 20 protons and 18 electrons. Calculate its charge and state whether it is a cation or an anion.', 'text', 1, 'Calculate protons minus electrons.', '{"why":"The particle has two more protons than electrons.","sol":"Step 1: Positive charge = +20.\nStep 2: Negative charge = -18.\nStep 3: Net charge = 20 - 18 = +2.\nStep 4: A positively charged ion is a cation.","steps":["Step 1: Positive charge = +20.","Step 2: Negative charge = -18.","Step 3: Net charge = 20 - 18 = +2.","Step 4: A positively charged ion is a cation."],"options":[],"conceptId":"chemistry_atomic_structure_electrons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q5","subject":"chemistry","chapter":"atomic_structure","topic":"Electrons"}', 4),
  (3068, 755, 'A particle has 17 protons and a charge of -1. Calculate its electron number.', 'text', 1, 'A charge of -1 means one more electron than proton.', '{"why":"An extra electron gives one unit of negative relative charge.","sol":"Step 1: Proton number = 17.\nStep 2: A -1 charge means the electron number exceeds the proton number by one.\nStep 3: Electrons = 17 + 1 = 18.\nStep 4: Check: 17 - 18 = -1.","steps":["Step 1: Proton number = 17.","Step 2: A -1 charge means the electron number exceeds the proton number by one.","Step 3: Electrons = 17 + 1 = 18.","Step 4: Check: 17 - 18 = -1."],"options":[],"conceptId":"chemistry_atomic_structure_electrons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q6","subject":"chemistry","chapter":"atomic_structure","topic":"Electrons"}', 5),
  (3069, 755, 'A magnesium atom has 12 protons and 12 electrons. It loses two electrons. Calculate its new charge and explain whether its proton number changes.', 'text', 1, 'Electron loss changes charge, not the number of protons.', '{"why":"Ordinary ion formation changes the electron number without changing the nucleus.","sol":"Step 1: New electron number = 12 - 2 = 10.\nStep 2: Proton number remains 12.\nStep 3: Charge = 12 - 10 = +2.\nStep 4: The particle is Mg2+.","steps":["Step 1: New electron number = 12 - 2 = 10.","Step 2: Proton number remains 12.","Step 3: Charge = 12 - 10 = +2.","Step 4: The particle is Mg2+."],"options":[],"conceptId":"chemistry_atomic_structure_electrons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q7","subject":"chemistry","chapter":"atomic_structure","topic":"Electrons"}', 6),
  (3070, 755, 'A learner states that an atom becomes a different element when it loses an electron. Correct the statement using the example of sodium.', 'text', 1, 'Compare sodium''s proton number before and after electron loss.', '{"why":"Element identity depends on proton number, not electron number.","sol":"Step 1: Sodium has atomic number 11 and therefore 11 protons.\nStep 2: A neutral sodium atom has 11 electrons.\nStep 3: Losing one electron leaves 10 electrons.\nStep 4: The proton number remains 11.\nStep 5: The particle remains sodium and forms Na+.","steps":["Step 1: Sodium has atomic number 11 and therefore 11 protons.","Step 2: A neutral sodium atom has 11 electrons.","Step 3: Losing one electron leaves 10 electrons.","Step 4: The proton number remains 11.","Step 5: The particle remains sodium and forms Na+."],"options":[],"conceptId":"chemistry_atomic_structure_electrons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q8","subject":"chemistry","chapter":"atomic_structure","topic":"Electrons"}', 7),
  (3071, 755, 'A particle has 26 electrons and a charge of +3. Calculate its proton number and identify the element.', 'text', 1, 'Charge = protons - electrons. Rearrange to find the proton number.', '{"why":"The positive charge means the proton number exceeds the electron number by three.","sol":"Step 1: Let the proton number be p.\nStep 2: +3 = p - 26.\nStep 3: p = 26 + 3 = 29.\nStep 4: Atomic number 29 identifies copper (Cu).","steps":["Step 1: Let the proton number be p.","Step 2: +3 = p - 26.","Step 3: p = 26 + 3 = 29.","Step 4: Atomic number 29 identifies copper (Cu)."],"options":[],"conceptId":"chemistry_atomic_structure_electrons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q9","subject":"chemistry","chapter":"atomic_structure","topic":"Electrons"}', 8),
  (3072, 756, 'Define atomic number and state the symbol used to represent it.', 'text', 1, 'Focus on the core principle of Atomic Number.', '{"why":"The proton number determines the identity of an element.","sol":"Step 1: Identify atomic number as the number of protons in the nucleus.\nStep 2: State its conventional symbol, Z.","steps":["Step 1: Identify atomic number as the number of protons in the nucleus.","Step 2: State its conventional symbol, Z."],"options":[],"conceptId":"chemistry_atomic_structure_atomic_number","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q1","subject":"chemistry","chapter":"atomic_structure","topic":"Atomic Number"}', 0),
  (3073, 756, 'An element has atomic number 8. State its proton number and identify the element.', 'text', 1, 'Focus on the core principle of Atomic Number.', '{"why":"Each element has a unique atomic number.","sol":"Step 1: Proton number = atomic number = 8.\nStep 2: Element 8 is oxygen.","steps":["Step 1: Proton number = atomic number = 8.","Step 2: Element 8 is oxygen."],"options":[],"conceptId":"chemistry_atomic_structure_atomic_number","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q2","subject":"chemistry","chapter":"atomic_structure","topic":"Atomic Number"}', 1),
  (3074, 756, 'A neutral atom has atomic number 12. Calculate its number of electrons and explain why.', 'text', 1, 'Focus on the core principle of Atomic Number.', '{"why":"The positive and negative charges balance in a neutral atom.","sol":"Step 1: Atomic number 12 means 12 protons.\nStep 2: A neutral atom has equal numbers of protons and electrons.\nStep 3: Electron number = 12.","steps":["Step 1: Atomic number 12 means 12 protons.","Step 2: A neutral atom has equal numbers of protons and electrons.","Step 3: Electron number = 12."],"options":[],"conceptId":"chemistry_atomic_structure_atomic_number","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q3","subject":"chemistry","chapter":"atomic_structure","topic":"Atomic Number"}', 2),
  (3075, 756, 'An atom contains 13 protons and 14 neutrons. Calculate its atomic number and identify the element.', 'text', 1, 'Atomic number is determined by protons, not by adding neutrons.', '{"why":"Neutrons affect mass number, not atomic number.","sol":"Step 1: Count the protons: 13.\nStep 2: Atomic number = 13.\nStep 3: Element 13 is aluminium.","steps":["Step 1: Count the protons: 13.","Step 2: Atomic number = 13.","Step 3: Element 13 is aluminium."],"options":[],"conceptId":"chemistry_atomic_structure_atomic_number","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q4","subject":"chemistry","chapter":"atomic_structure","topic":"Atomic Number"}', 3),
  (3076, 756, 'A particle has atomic number 17 and 18 electrons. Determine its proton number, net charge and elemental identity.', 'text', 1, 'Atomic number gives protons. Charge = protons - electrons.', '{"why":"The extra electron gives chlorine a single negative charge without changing its atomic number.","sol":"Step 1: Proton number = 17.\nStep 2: Element 17 is chlorine.\nStep 3: Charge = 17 - 18 = -1.\nStep 4: The particle is Cl-.","steps":["Step 1: Proton number = 17.","Step 2: Element 17 is chlorine.","Step 3: Charge = 17 - 18 = -1.","Step 4: The particle is Cl-."],"options":[],"conceptId":"chemistry_atomic_structure_atomic_number","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q5","subject":"chemistry","chapter":"atomic_structure","topic":"Atomic Number"}', 4),
  (3077, 756, 'An ion has 10 electrons and a charge of +2. Calculate its proton number and identify the element.', 'text', 1, 'A +2 charge means there are two more protons than electrons.', '{"why":"The positive charge represents a deficit of two electrons relative to protons.","sol":"Step 1: Electron number = 10.\nStep 2: Proton number = electron number + 2.\nStep 3: Proton number = 10 + 2 = 12.\nStep 4: Atomic number 12 identifies magnesium.","steps":["Step 1: Electron number = 10.","Step 2: Proton number = electron number + 2.","Step 3: Proton number = 10 + 2 = 12.","Step 4: Atomic number 12 identifies magnesium."],"options":[],"conceptId":"chemistry_atomic_structure_atomic_number","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q6","subject":"chemistry","chapter":"atomic_structure","topic":"Atomic Number"}', 5),
  (3078, 756, 'Two particles have atomic numbers 11 and 12. Explain why they cannot be isotopes of the same element.', 'text', 1, 'Isotopes must have equal proton numbers.', '{"why":"Isotopes have the same proton number but different neutron numbers.","sol":"Step 1: The first particle has 11 protons.\nStep 2: The second particle has 12 protons.\nStep 3: Their proton numbers differ.\nStep 4: They are different elements, sodium and magnesium.\nStep 5: Therefore, they cannot be isotopes of one another.","steps":["Step 1: The first particle has 11 protons.","Step 2: The second particle has 12 protons.","Step 3: Their proton numbers differ.","Step 4: They are different elements, sodium and magnesium.","Step 5: Therefore, they cannot be isotopes of one another."],"options":[],"conceptId":"chemistry_atomic_structure_atomic_number","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q7","subject":"chemistry","chapter":"atomic_structure","topic":"Atomic Number"}', 6),
  (3079, 756, 'An element has atomic number 16. Its atom gains two electrons. Determine the element, final electron number and charge.', 'text', 1, 'The proton number remains unchanged when electrons are gained.', '{"why":"Gaining electrons changes the charge but not the element''s atomic number.","sol":"Step 1: Atomic number 16 identifies sulfur.\nStep 2: The neutral atom initially has 16 electrons.\nStep 3: After gaining two electrons, it has 16 + 2 = 18 electrons.\nStep 4: Charge = 16 - 18 = -2.","steps":["Step 1: Atomic number 16 identifies sulfur.","Step 2: The neutral atom initially has 16 electrons.","Step 3: After gaining two electrons, it has 16 + 2 = 18 electrons.","Step 4: Charge = 16 - 18 = -2."],"options":[],"conceptId":"chemistry_atomic_structure_atomic_number","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q8","subject":"chemistry","chapter":"atomic_structure","topic":"Atomic Number"}', 7),
  (3080, 756, 'A learner adds the proton and neutron numbers to calculate atomic number. Explain the error using an atom with 11 protons and 12 neutrons.', 'text', 1, 'The sum of protons and neutrons is a different atomic quantity.', '{"why":"Atomic number counts protons alone; mass number counts protons and neutrons.","sol":"Step 1: Atomic number = number of protons = 11.\nStep 2: The learner''s sum, 11 + 12 = 23, is the mass number.\nStep 3: Atomic number and mass number describe different quantities.\nStep 4: The element is sodium because its atomic number is 11.","steps":["Step 1: Atomic number = number of protons = 11.","Step 2: The learner''s sum, 11 + 12 = 23, is the mass number.","Step 3: Atomic number and mass number describe different quantities.","Step 4: The element is sodium because its atomic number is 11."],"options":[],"conceptId":"chemistry_atomic_structure_atomic_number","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q9","subject":"chemistry","chapter":"atomic_structure","topic":"Atomic Number"}', 8),
  (3081, 757, 'Define mass number and write the formula connecting mass number, proton number and neutron number.', 'text', 1, 'Focus on the core principle of Mass Number.', '{"why":"The mass number counts the nucleons in the nucleus.","sol":"Step 1: Mass number is the total number of protons and neutrons in the nucleus.\nStep 2: Let A represent mass number, Z represent proton number and n represent neutron number.\nStep 3: Combine the two nuclear particle counts: A = Z + n.","steps":["Step 1: Mass number is the total number of protons and neutrons in the nucleus.","Step 2: Let A represent mass number, Z represent proton number and n represent neutron number.","Step 3: Combine the two nuclear particle counts: A = Z + n."],"options":[],"conceptId":"chemistry_atomic_structure_mass_number","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q1","subject":"chemistry","chapter":"atomic_structure","topic":"Mass Number"}', 0),
  (3082, 757, 'An atom contains 11 protons and 12 neutrons. Calculate its mass number.', 'text', 1, 'Focus on the core principle of Mass Number.', '{"why":"Adding protons and neutrons gives the mass number.","sol":"Step 1: Use A = Z + n.\nStep 2: Substitute: A = 11 + 12.\nStep 3: Calculate: A = 23.","steps":["Step 1: Use A = Z + n.","Step 2: Substitute: A = 11 + 12.","Step 3: Calculate: A = 23."],"options":[],"conceptId":"chemistry_atomic_structure_mass_number","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q2","subject":"chemistry","chapter":"atomic_structure","topic":"Mass Number"}', 1),
  (3083, 757, 'An atom has mass number 35 and atomic number 17. Calculate its neutron number.', 'text', 1, 'Focus on the core principle of Mass Number.', '{"why":"Subtracting the known proton count from the mass number gives the neutron count.","sol":"Step 1: Neutrons = A - Z.\nStep 2: Substitute: n = 35 - 17.\nStep 3: Calculate: n = 18.\nStep 4: Check: 17 + 18 = 35.","steps":["Step 1: Neutrons = A - Z.","Step 2: Substitute: n = 35 - 17.","Step 3: Calculate: n = 18.","Step 4: Check: 17 + 18 = 35."],"options":[],"conceptId":"chemistry_atomic_structure_mass_number","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q3","subject":"chemistry","chapter":"atomic_structure","topic":"Mass Number"}', 2),
  (3084, 757, 'An atom has mass number 40 and atomic number 20. Calculate its number of protons, neutrons and electrons if the atom is neutral.', 'text', 1, 'Atomic number gives protons; neutrons equal mass number minus atomic number.', '{"why":"The atomic number determines protons, mass number determines the total nuclear particles, and neutrality determines electrons.","sol":"Step 1: Protons = atomic number = 20.\nStep 2: Neutrons = 40 - 20 = 20.\nStep 3: A neutral atom has equal numbers of protons and electrons.\nStep 4: Electrons = 20.\nStep 5: Check: mass number = 20 + 20 = 40.","steps":["Step 1: Protons = atomic number = 20.","Step 2: Neutrons = 40 - 20 = 20.","Step 3: A neutral atom has equal numbers of protons and electrons.","Step 4: Electrons = 20.","Step 5: Check: mass number = 20 + 20 = 40."],"options":[],"conceptId":"chemistry_atomic_structure_mass_number","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q4","subject":"chemistry","chapter":"atomic_structure","topic":"Mass Number"}', 3),
  (3085, 757, 'An atom has 15 protons and a mass number of 31. Calculate its neutron number and identify the element.', 'text', 1, 'Subtract the proton number from the mass number, then use the proton number to identify the element.', '{"why":"The neutron number is calculated from A - Z, while the element is identified by Z.","sol":"Step 1: Z = 15 and A = 31.\nStep 2: Neutrons = 31 - 15 = 16.\nStep 3: Atomic number 15 identifies phosphorus.","steps":["Step 1: Z = 15 and A = 31.","Step 2: Neutrons = 31 - 15 = 16.","Step 3: Atomic number 15 identifies phosphorus."],"options":[],"conceptId":"chemistry_atomic_structure_mass_number","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q5","subject":"chemistry","chapter":"atomic_structure","topic":"Mass Number"}', 4),
  (3086, 757, 'An atom contains 18 neutrons and has mass number 35. Calculate its proton number and identify the element.', 'text', 1, 'Rearrange A = Z + n to make Z the subject.', '{"why":"The mass number is divided between protons and neutrons. The proton number identifies the element.","sol":"Step 1: A = Z + n.\nStep 2: Rearrange: Z = A - n.\nStep 3: Z = 35 - 18 = 17.\nStep 4: Atomic number 17 identifies chlorine.","steps":["Step 1: A = Z + n.","Step 2: Rearrange: Z = A - n.","Step 3: Z = 35 - 18 = 17.","Step 4: Atomic number 17 identifies chlorine."],"options":[],"conceptId":"chemistry_atomic_structure_mass_number","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q6","subject":"chemistry","chapter":"atomic_structure","topic":"Mass Number"}', 5),
  (3087, 757, 'An atom is represented by ²³₁₁Na. Determine its proton number, neutron number and electron number if neutral.', 'text', 1, 'Read the lower number as atomic number and the upper number as mass number.', '{"why":"Nuclear notation provides the atomic number and mass number; neutrality determines the electron count.","sol":"Step 1: Atomic number = 11, so there are 11 protons.\nStep 2: Mass number = 23.\nStep 3: Neutrons = 23 - 11 = 12.\nStep 4: Because the atom is neutral, electrons = 11.","steps":["Step 1: Atomic number = 11, so there are 11 protons.","Step 2: Mass number = 23.","Step 3: Neutrons = 23 - 11 = 12.","Step 4: Because the atom is neutral, electrons = 11."],"options":[],"conceptId":"chemistry_atomic_structure_mass_number","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q7","subject":"chemistry","chapter":"atomic_structure","topic":"Mass Number"}', 6),
  (3088, 757, 'A learner calculates the mass number of an atom with 12 protons, 13 neutrons and 12 electrons as 37. Identify the error and calculate the correct mass number.', 'text', 1, 'Mass number includes only protons and neutrons.', '{"why":"Mass number counts nucleons, not all subatomic particles.","sol":"Step 1: Identify the error: the learner included electrons.\nStep 2: Use A = protons + neutrons.\nStep 3: A = 12 + 13 = 25.\nStep 4: The 12 electrons are excluded from mass number.","steps":["Step 1: Identify the error: the learner included electrons.","Step 2: Use A = protons + neutrons.","Step 3: A = 12 + 13 = 25.","Step 4: The 12 electrons are excluded from mass number."],"options":[],"conceptId":"chemistry_atomic_structure_mass_number","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q8","subject":"chemistry","chapter":"atomic_structure","topic":"Mass Number"}', 7),
  (3089, 757, 'Two particles each have mass number 23. Particle A has 11 protons and particle B has 12 protons. Calculate the neutron number of each and explain whether they are the same element.', 'text', 1, 'Calculate neutrons separately, then compare the proton numbers.', '{"why":"Equal mass numbers do not guarantee equal proton numbers or identical elemental identities.","sol":"Step 1: Particle A: neutrons = 23 - 11 = 12.\nStep 2: Particle B: neutrons = 23 - 12 = 11.\nStep 3: Particle A has atomic number 11, so it is sodium.\nStep 4: Particle B has atomic number 12, so it is magnesium.\nStep 5: They are different elements because their proton numbers differ.","steps":["Step 1: Particle A: neutrons = 23 - 11 = 12.","Step 2: Particle B: neutrons = 23 - 12 = 11.","Step 3: Particle A has atomic number 11, so it is sodium.","Step 4: Particle B has atomic number 12, so it is magnesium.","Step 5: They are different elements because their proton numbers differ."],"options":[],"conceptId":"chemistry_atomic_structure_mass_number","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q9","subject":"chemistry","chapter":"atomic_structure","topic":"Mass Number"}', 8),
  (3090, 758, 'Define electron arrangement and state the maximum number of electrons in the first two shells.', 'text', 1, 'Focus on the core principle of Electron Arrangement.', '{"why":"Electron arrangement describes how electrons are organised around the nucleus.","sol":"Step 1: Electron arrangement describes how electrons are distributed among energy levels.\nStep 2: The first shell holds up to 2 electrons.\nStep 3: The second shell holds up to 8 electrons in the introductory model.","steps":["Step 1: Electron arrangement describes how electrons are distributed among energy levels.","Step 2: The first shell holds up to 2 electrons.","Step 3: The second shell holds up to 8 electrons in the introductory model."],"options":[],"conceptId":"chemistry_atomic_structure_electron_arrangement","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q1","subject":"chemistry","chapter":"atomic_structure","topic":"Electron Arrangement"}', 0),
  (3091, 758, 'Write the electron arrangement of oxygen, atomic number 8.', 'text', 1, 'Focus on the core principle of Electron Arrangement.', '{"why":"The two shell counts add up to the atomic number: 2 + 6 = 8.","sol":"Step 1: A neutral oxygen atom has 8 electrons.\nStep 2: Place 2 electrons in the first shell.\nStep 3: Remaining electrons = 8 - 2 = 6.\nStep 4: The second shell contains 6 electrons.","steps":["Step 1: A neutral oxygen atom has 8 electrons.","Step 2: Place 2 electrons in the first shell.","Step 3: Remaining electrons = 8 - 2 = 6.","Step 4: The second shell contains 6 electrons."],"options":[],"conceptId":"chemistry_atomic_structure_electron_arrangement","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q2","subject":"chemistry","chapter":"atomic_structure","topic":"Electron Arrangement"}', 1),
  (3092, 758, 'A neutral atom has electron arrangement 2,8,1. Calculate its atomic number and identify the element.', 'text', 1, 'Focus on the core principle of Electron Arrangement.', '{"why":"For a neutral atom, total electrons equal total protons.","sol":"Step 1: Add the shell populations: 2 + 8 + 1 = 11.\nStep 2: A neutral atom has 11 protons.\nStep 3: Atomic number 11 identifies sodium.","steps":["Step 1: Add the shell populations: 2 + 8 + 1 = 11.","Step 2: A neutral atom has 11 protons.","Step 3: Atomic number 11 identifies sodium."],"options":[],"conceptId":"chemistry_atomic_structure_electron_arrangement","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q3","subject":"chemistry","chapter":"atomic_structure","topic":"Electron Arrangement"}', 2),
  (3093, 758, 'Write the electron arrangement of magnesium, atomic number 12, and show how you account for every electron.', 'text', 1, 'Fill the first shell with 2, the second with 8, then place the remainder.', '{"why":"Every electron must be accounted for, and the shell total must equal the atomic number.","sol":"Step 1: Magnesium has 12 electrons when neutral.\nStep 2: First shell = 2; remaining = 12 - 2 = 10.\nStep 3: Second shell = 8; remaining = 10 - 8 = 2.\nStep 4: Third shell = 2.\nStep 5: Check: 2 + 8 + 2 = 12.","steps":["Step 1: Magnesium has 12 electrons when neutral.","Step 2: First shell = 2; remaining = 12 - 2 = 10.","Step 3: Second shell = 8; remaining = 10 - 8 = 2.","Step 4: Third shell = 2.","Step 5: Check: 2 + 8 + 2 = 12."],"options":[],"conceptId":"chemistry_atomic_structure_electron_arrangement","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q4","subject":"chemistry","chapter":"atomic_structure","topic":"Electron Arrangement"}', 3),
  (3094, 758, 'An atom has electron arrangement 2,8,8,1. Calculate its total number of electrons and identify the element if it is neutral.', 'text', 1, 'Add the shell populations and use the atomic number.', '{"why":"The shell populations give the electron total, which equals the atomic number for a neutral atom.","sol":"Step 1: Total electrons = 2 + 8 + 8 + 1.\nStep 2: Total electrons = 19.\nStep 3: A neutral atom has atomic number 19.\nStep 4: Element 19 is potassium.","steps":["Step 1: Total electrons = 2 + 8 + 8 + 1.","Step 2: Total electrons = 19.","Step 3: A neutral atom has atomic number 19.","Step 4: Element 19 is potassium."],"options":[],"conceptId":"chemistry_atomic_structure_electron_arrangement","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q5","subject":"chemistry","chapter":"atomic_structure","topic":"Electron Arrangement"}', 4),
  (3095, 758, 'A neutral atom has atomic number 16. Write its electron arrangement and explain how you checked the result.', 'text', 1, 'Distribute 16 electrons using the shell model for the first 20 elements.', '{"why":"The sum of the shell populations must equal the number of electrons.","sol":"Step 1: The atom has 16 electrons.\nStep 2: Place 2 in the first shell, leaving 14.\nStep 3: Place 8 in the second shell, leaving 6.\nStep 4: Place the remaining 6 in the third shell.\nStep 5: Check: 2 + 8 + 6 = 16.","steps":["Step 1: The atom has 16 electrons.","Step 2: Place 2 in the first shell, leaving 14.","Step 3: Place 8 in the second shell, leaving 6.","Step 4: Place the remaining 6 in the third shell.","Step 5: Check: 2 + 8 + 6 = 16."],"options":[],"conceptId":"chemistry_atomic_structure_electron_arrangement","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q6","subject":"chemistry","chapter":"atomic_structure","topic":"Electron Arrangement"}', 5),
  (3096, 758, 'A learner writes the arrangement of an atom with 13 electrons as 2,8,4. Identify the error and correct the arrangement.', 'text', 1, 'Add the learner''s numbers before deciding what is wrong.', '{"why":"The total shell population must equal the actual number of electrons.","sol":"Step 1: The proposed arrangement totals 2 + 8 + 4 = 14.\nStep 2: The atom has only 13 electrons, so the arrangement is incorrect.\nStep 3: Fill the first shell with 2 and the second with 8.\nStep 4: Remaining electrons = 13 - 10 = 3.\nStep 5: Correct arrangement = 2,8,3.","steps":["Step 1: The proposed arrangement totals 2 + 8 + 4 = 14.","Step 2: The atom has only 13 electrons, so the arrangement is incorrect.","Step 3: Fill the first shell with 2 and the second with 8.","Step 4: Remaining electrons = 13 - 10 = 3.","Step 5: Correct arrangement = 2,8,3."],"options":[],"conceptId":"chemistry_atomic_structure_electron_arrangement","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q7","subject":"chemistry","chapter":"atomic_structure","topic":"Electron Arrangement"}', 6),
  (3097, 758, 'A neutral atom has arrangement 2,8,7. Determine its atomic number, identify the element and state how many electrons it needs to gain to reach a full outer shell of eight.', 'text', 1, 'Add all electrons, then compare the outer-shell count with eight.', '{"why":"The outer-shell count helps explain the tendency of chlorine to gain one electron when forming chloride ions.","sol":"Step 1: Total electrons = 2 + 8 + 7 = 17.\nStep 2: Atomic number = 17.\nStep 3: Element 17 is chlorine.\nStep 4: Its outer shell contains 7 electrons.\nStep 5: It needs 8 - 7 = 1 additional electron to complete that shell.","steps":["Step 1: Total electrons = 2 + 8 + 7 = 17.","Step 2: Atomic number = 17.","Step 3: Element 17 is chlorine.","Step 4: Its outer shell contains 7 electrons.","Step 5: It needs 8 - 7 = 1 additional electron to complete that shell."],"options":[],"conceptId":"chemistry_atomic_structure_electron_arrangement","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q8","subject":"chemistry","chapter":"atomic_structure","topic":"Electron Arrangement"}', 7),
  (3098, 758, 'A particle has 12 protons and electron arrangement 2,8. Calculate its electron number and charge, and explain why it is not a neutral magnesium atom.', 'text', 1, 'The arrangement gives electrons; compare that total with the proton number.', '{"why":"A neutral magnesium atom has 12 electrons. Losing two produces the arrangement 2,8 and charge +2.","sol":"Step 1: Electron number = 2 + 8 = 10.\nStep 2: Proton number = 12.\nStep 3: Charge = 12 - 10 = +2.\nStep 4: Atomic number 12 identifies magnesium.\nStep 5: It is Mg2+, not a neutral atom, because it has two fewer electrons than protons.","steps":["Step 1: Electron number = 2 + 8 = 10.","Step 2: Proton number = 12.","Step 3: Charge = 12 - 10 = +2.","Step 4: Atomic number 12 identifies magnesium.","Step 5: It is Mg2+, not a neutral atom, because it has two fewer electrons than protons."],"options":[],"conceptId":"chemistry_atomic_structure_electron_arrangement","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q9","subject":"chemistry","chapter":"atomic_structure","topic":"Electron Arrangement"}', 8),
  (3099, 759, 'Define isotopes and state the two particle counts that distinguish them.', 'text', 1, 'Focus on the core principle of Isotopes.', '{"why":"Proton number establishes the element; neutron number determines which isotope it is.","sol":"Step 1: Isotopes are atoms of the same element.\nStep 2: They have the same proton number.\nStep 3: They have different neutron numbers.\nStep 4: Therefore, they have different mass numbers.","steps":["Step 1: Isotopes are atoms of the same element.","Step 2: They have the same proton number.","Step 3: They have different neutron numbers.","Step 4: Therefore, they have different mass numbers."],"options":[],"conceptId":"chemistry_atomic_structure_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q1","subject":"chemistry","chapter":"atomic_structure","topic":"Isotopes"}', 0),
  (3100, 759, 'Calculate the neutron number of carbon-14. Carbon has atomic number 6.', 'text', 1, 'Focus on the core principle of Isotopes.', '{"why":"The neutron number equals mass number minus atomic number.","sol":"Step 1: Mass number = 14.\nStep 2: Proton number = 6.\nStep 3: Neutrons = 14 - 6 = 8.","steps":["Step 1: Mass number = 14.","Step 2: Proton number = 6.","Step 3: Neutrons = 14 - 6 = 8."],"options":[],"conceptId":"chemistry_atomic_structure_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q2","subject":"chemistry","chapter":"atomic_structure","topic":"Isotopes"}', 1),
  (3101, 759, 'Explain why carbon-12 and carbon-14 are both carbon.', 'text', 1, 'Focus on the core principle of Isotopes.', '{"why":"Element identity depends on proton number, not mass number.","sol":"Step 1: Carbon has atomic number 6.\nStep 2: Both isotopes contain six protons.\nStep 3: Their proton numbers therefore identify both as carbon.\nStep 4: Their neutron numbers differ, producing different mass numbers.","steps":["Step 1: Carbon has atomic number 6.","Step 2: Both isotopes contain six protons.","Step 3: Their proton numbers therefore identify both as carbon.","Step 4: Their neutron numbers differ, producing different mass numbers."],"options":[],"conceptId":"chemistry_atomic_structure_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q3","subject":"chemistry","chapter":"atomic_structure","topic":"Isotopes"}', 2),
  (3102, 759, 'Chlorine has atomic number 17. Calculate the neutron numbers of chlorine-35 and chlorine-37 and explain why they are isotopes.', 'text', 1, 'Use neutrons = mass number - atomic number for each isotope.', '{"why":"They have equal proton numbers and unequal neutron numbers.","sol":"Step 1: Chlorine-35: n = 35 - 17 = 18.\nStep 2: Chlorine-37: n = 37 - 17 = 20.\nStep 3: Both have 17 protons.\nStep 4: Their neutron numbers differ, so their mass numbers differ.\nStep 5: Therefore, they are isotopes of chlorine.","steps":["Step 1: Chlorine-35: n = 35 - 17 = 18.","Step 2: Chlorine-37: n = 37 - 17 = 20.","Step 3: Both have 17 protons.","Step 4: Their neutron numbers differ, so their mass numbers differ.","Step 5: Therefore, they are isotopes of chlorine."],"options":[],"conceptId":"chemistry_atomic_structure_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q4","subject":"chemistry","chapter":"atomic_structure","topic":"Isotopes"}', 3),
  (3103, 759, 'An isotope has mass number 23 and contains 12 neutrons. Calculate its atomic number and identify the element.', 'text', 1, 'Atomic number = mass number - neutron number.', '{"why":"The proton number identifies the element.","sol":"Step 1: A = Z + n.\nStep 2: Z = A - n.\nStep 3: Z = 23 - 12 = 11.\nStep 4: Atomic number 11 identifies sodium.","steps":["Step 1: A = Z + n.","Step 2: Z = A - n.","Step 3: Z = 23 - 12 = 11.","Step 4: Atomic number 11 identifies sodium."],"options":[],"conceptId":"chemistry_atomic_structure_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q5","subject":"chemistry","chapter":"atomic_structure","topic":"Isotopes"}', 4),
  (3104, 759, 'Two atoms have proton numbers of 12. One has 12 neutrons and the other has 13 neutrons. Calculate both mass numbers and identify their relationship.', 'text', 1, 'Add protons and neutrons separately for each atom.', '{"why":"Equal proton numbers identify the same element, while differing neutron numbers identify different isotopes.","sol":"Step 1: Atom A: A = 12 + 12 = 24.\nStep 2: Atom B: A = 12 + 13 = 25.\nStep 3: Atomic number 12 identifies magnesium.\nStep 4: Both have 12 protons but different neutron numbers.\nStep 5: They are magnesium isotopes.","steps":["Step 1: Atom A: A = 12 + 12 = 24.","Step 2: Atom B: A = 12 + 13 = 25.","Step 3: Atomic number 12 identifies magnesium.","Step 4: Both have 12 protons but different neutron numbers.","Step 5: They are magnesium isotopes."],"options":[],"conceptId":"chemistry_atomic_structure_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q6","subject":"chemistry","chapter":"atomic_structure","topic":"Isotopes"}', 5),
  (3105, 759, 'A learner claims that two atoms with the same mass number must be isotopes. Evaluate this claim using one example of two atoms with mass number 40.', 'text', 1, 'Isotopes require equal proton numbers, not just equal mass numbers.', '{"why":"Isotopes must have the same atomic number. Atoms with equal mass numbers but different atomic numbers are called isobars.","sol":"Step 1: Consider an atom with mass number 40 and 18 protons.\nStep 2: Its neutron number is 40 - 18 = 22.\nStep 3: Consider another atom with mass number 40 and 20 protons.\nStep 4: Its neutron number is 40 - 20 = 20.\nStep 5: Their proton numbers differ, so they are different elements, not isotopes.","steps":["Step 1: Consider an atom with mass number 40 and 18 protons.","Step 2: Its neutron number is 40 - 18 = 22.","Step 3: Consider another atom with mass number 40 and 20 protons.","Step 4: Its neutron number is 40 - 20 = 20.","Step 5: Their proton numbers differ, so they are different elements, not isotopes."],"options":[],"conceptId":"chemistry_atomic_structure_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q7","subject":"chemistry","chapter":"atomic_structure","topic":"Isotopes"}', 6),
  (3106, 759, 'Atom X has 9 protons and 10 neutrons. Atom Y has 10 protons and 9 neutrons. Calculate their mass numbers and determine whether they are isotopes.', 'text', 1, 'Calculate each mass number, then compare proton numbers.', '{"why":"Isotopes must belong to the same element.","sol":"Step 1: X: mass number = 9 + 10 = 19.\nStep 2: Y: mass number = 10 + 9 = 19.\nStep 3: X has atomic number 9; Y has atomic number 10.\nStep 4: They are different elements, fluorine and neon.\nStep 5: They are not isotopes, even though both have mass number 19.","steps":["Step 1: X: mass number = 9 + 10 = 19.","Step 2: Y: mass number = 10 + 9 = 19.","Step 3: X has atomic number 9; Y has atomic number 10.","Step 4: They are different elements, fluorine and neon.","Step 5: They are not isotopes, even though both have mass number 19."],"options":[],"conceptId":"chemistry_atomic_structure_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q8","subject":"chemistry","chapter":"atomic_structure","topic":"Isotopes"}', 7),
  (3107, 759, 'An atom has atomic number 16 and mass number 32. Another atom has atomic number 16 and mass number 34. Calculate their neutron numbers and explain which properties remain unchanged.', 'text', 1, 'Calculate both neutron numbers and compare proton counts.', '{"why":"The proton number and element identity remain the same, while neutron number and mass number differ.","sol":"Step 1: First atom: neutrons = 32 - 16 = 16.\nStep 2: Second atom: neutrons = 34 - 16 = 18.\nStep 3: Both contain 16 protons and have atomic number 16.\nStep 4: Both are sulfur atoms.\nStep 5: Their neutron numbers and mass numbers differ.","steps":["Step 1: First atom: neutrons = 32 - 16 = 16.","Step 2: Second atom: neutrons = 34 - 16 = 18.","Step 3: Both contain 16 protons and have atomic number 16.","Step 4: Both are sulfur atoms.","Step 5: Their neutron numbers and mass numbers differ."],"options":[],"conceptId":"chemistry_atomic_structure_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q9","subject":"chemistry","chapter":"atomic_structure","topic":"Isotopes"}', 8),
  (3108, 760, 'State the two conditions that must be satisfied for two atoms to be isotopes.', 'text', 1, 'Focus on the core principle of Identifying Isotopes.', '{"why":"These conditions distinguish isotopes from atoms of different elements.","sol":"Step 1: Their proton numbers must be equal.\nStep 2: Their neutron numbers must be different.\nStep 3: These conditions mean the atoms are the same element but have different mass numbers.","steps":["Step 1: Their proton numbers must be equal.","Step 2: Their neutron numbers must be different.","Step 3: These conditions mean the atoms are the same element but have different mass numbers."],"options":[],"conceptId":"chemistry_atomic_structure_identifying_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q1","subject":"chemistry","chapter":"atomic_structure","topic":"Identifying Isotopes"}', 0),
  (3109, 760, 'Atom X has 8 protons and 8 neutrons. Atom Y has 8 protons and 10 neutrons. Are they isotopes? Explain.', 'text', 1, 'Focus on the core principle of Identifying Isotopes.', '{"why":"They satisfy both conditions for isotopes.","sol":"Step 1: Both have 8 protons.\nStep 2: Their neutron numbers are 8 and 10.\nStep 3: The proton numbers match, while the neutron numbers differ.\nStep 4: Therefore, they are isotopes of oxygen.","steps":["Step 1: Both have 8 protons.","Step 2: Their neutron numbers are 8 and 10.","Step 3: The proton numbers match, while the neutron numbers differ.","Step 4: Therefore, they are isotopes of oxygen."],"options":[],"conceptId":"chemistry_atomic_structure_identifying_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q2","subject":"chemistry","chapter":"atomic_structure","topic":"Identifying Isotopes"}', 1),
  (3110, 760, 'Atom A has 11 protons and 12 neutrons. Atom B has 12 protons and 12 neutrons. Explain whether they are isotopes.', 'text', 1, 'Focus on the core principle of Identifying Isotopes.', '{"why":"Isotopes must have the same proton number.","sol":"Step 1: Atom A has 11 protons.\nStep 2: Atom B has 12 protons.\nStep 3: The proton numbers differ.\nStep 4: Therefore, the atoms are different elements and are not isotopes.","steps":["Step 1: Atom A has 11 protons.","Step 2: Atom B has 12 protons.","Step 3: The proton numbers differ.","Step 4: Therefore, the atoms are different elements and are not isotopes."],"options":[],"conceptId":"chemistry_atomic_structure_identifying_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q3","subject":"chemistry","chapter":"atomic_structure","topic":"Identifying Isotopes"}', 2),
  (3111, 760, 'Determine whether chlorine-35 and chlorine-37 are isotopes. Chlorine has atomic number 17.', 'text', 1, 'Compare the atomic numbers and calculate both neutron numbers.', '{"why":"Their proton numbers match while their neutron numbers differ.","sol":"Step 1: Both atoms have atomic number 17.\nStep 2: Both have 17 protons.\nStep 3: Chlorine-35 has 35 - 17 = 18 neutrons.\nStep 4: Chlorine-37 has 37 - 17 = 20 neutrons.\nStep 5: Same protons and different neutrons mean isotopes.","steps":["Step 1: Both atoms have atomic number 17.","Step 2: Both have 17 protons.","Step 3: Chlorine-35 has 35 - 17 = 18 neutrons.","Step 4: Chlorine-37 has 37 - 17 = 20 neutrons.","Step 5: Same protons and different neutrons mean isotopes."],"options":[],"conceptId":"chemistry_atomic_structure_identifying_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q4","subject":"chemistry","chapter":"atomic_structure","topic":"Identifying Isotopes"}', 3),
  (3112, 760, 'Atom A has 12 protons and 12 neutrons. Atom B has 12 protons and 13 neutrons. Calculate their mass numbers and determine whether they are isotopes.', 'text', 1, 'Add the proton and neutron numbers for each atom.', '{"why":"The same proton number establishes magnesium as the element, and the different neutron numbers establish different isotopes.","sol":"Step 1: A has mass number 12 + 12 = 24.\nStep 2: B has mass number 12 + 13 = 25.\nStep 3: Both have 12 protons.\nStep 4: Their neutron numbers differ.\nStep 5: They are magnesium isotopes.","steps":["Step 1: A has mass number 12 + 12 = 24.","Step 2: B has mass number 12 + 13 = 25.","Step 3: Both have 12 protons.","Step 4: Their neutron numbers differ.","Step 5: They are magnesium isotopes."],"options":[],"conceptId":"chemistry_atomic_structure_identifying_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q5","subject":"chemistry","chapter":"atomic_structure","topic":"Identifying Isotopes"}', 4),
  (3113, 760, 'Atom P has mass number 23 and atomic number 11. Atom Q has mass number 24 and atomic number 12. Determine whether they are isotopes.', 'text', 1, 'The atomic number is the proton number. Compare those values first.', '{"why":"Different proton numbers indicate different elements, regardless of their mass numbers.","sol":"Step 1: P has 11 protons.\nStep 2: Q has 12 protons.\nStep 3: Their proton numbers differ.\nStep 4: P is sodium and Q is magnesium.\nStep 5: They are not isotopes.","steps":["Step 1: P has 11 protons.","Step 2: Q has 12 protons.","Step 3: Their proton numbers differ.","Step 4: P is sodium and Q is magnesium.","Step 5: They are not isotopes."],"options":[],"conceptId":"chemistry_atomic_structure_identifying_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q6","subject":"chemistry","chapter":"atomic_structure","topic":"Identifying Isotopes"}', 5),
  (3114, 760, 'Two particles each have mass number 40. One has 18 protons and the other has 20 protons. Calculate their neutron numbers and explain why they are not isotopes.', 'text', 1, 'Use n = A - Z for both particles.', '{"why":"Equal mass numbers do not establish equal elemental identity.","sol":"Step 1: Particle A has 40 - 18 = 22 neutrons.\nStep 2: Particle B has 40 - 20 = 20 neutrons.\nStep 3: Their proton numbers are 18 and 20.\nStep 4: They are different elements, so they cannot be isotopes.","steps":["Step 1: Particle A has 40 - 18 = 22 neutrons.","Step 2: Particle B has 40 - 20 = 20 neutrons.","Step 3: Their proton numbers are 18 and 20.","Step 4: They are different elements, so they cannot be isotopes."],"options":[],"conceptId":"chemistry_atomic_structure_identifying_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q7","subject":"chemistry","chapter":"atomic_structure","topic":"Identifying Isotopes"}', 6),
  (3115, 760, 'Atom X contains 9 protons and 10 neutrons. Atom Y contains 9 protons and 10 neutrons. Determine whether they are different isotopes and justify your answer.', 'text', 1, 'Compare both proton and neutron numbers, not just one.', '{"why":"Different isotopes of the same element must differ in neutron number.","sol":"Step 1: Both atoms have 9 protons.\nStep 2: Both atoms have 10 neutrons.\nStep 3: Both have mass number 9 + 10 = 19.\nStep 4: Neither the proton number nor neutron number differs.\nStep 5: They represent the same nuclide, not different isotopes.","steps":["Step 1: Both atoms have 9 protons.","Step 2: Both atoms have 10 neutrons.","Step 3: Both have mass number 9 + 10 = 19.","Step 4: Neither the proton number nor neutron number differs.","Step 5: They represent the same nuclide, not different isotopes."],"options":[],"conceptId":"chemistry_atomic_structure_identifying_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q8","subject":"chemistry","chapter":"atomic_structure","topic":"Identifying Isotopes"}', 7),
  (3116, 760, 'A learner says two atoms are isotopes because both have 18 neutrons. Atom A has 17 protons and atom B has 18 protons. Evaluate the claim and identify both elements.', 'text', 1, 'The first test for isotopes is equality of proton number.', '{"why":"Equal neutron numbers are not sufficient. Isotopes must have equal proton numbers.","sol":"Step 1: Atom A has 17 protons, so it is chlorine.\nStep 2: Atom B has 18 protons, so it is argon.\nStep 3: The proton numbers differ.\nStep 4: Therefore, the atoms are different elements, not isotopes.","steps":["Step 1: Atom A has 17 protons, so it is chlorine.","Step 2: Atom B has 18 protons, so it is argon.","Step 3: The proton numbers differ.","Step 4: Therefore, the atoms are different elements, not isotopes."],"options":[],"conceptId":"chemistry_atomic_structure_identifying_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q9","subject":"chemistry","chapter":"atomic_structure","topic":"Identifying Isotopes"}', 8),
  (3117, 761, 'Define a radioisotope and explain how it differs from a stable isotope.', 'text', 1, 'Focus on the core principle of Uses of Isotopes.', '{"why":"Radioactivity results from nuclear instability, not merely from being an isotope.","sol":"Step 1: Isotopes are atoms of the same element with different neutron numbers.\nStep 2: A radioisotope has an unstable nucleus that emits radiation.\nStep 3: A stable isotope does not undergo spontaneous radioactive decay under ordinary conditions.","steps":["Step 1: Isotopes are atoms of the same element with different neutron numbers.","Step 2: A radioisotope has an unstable nucleus that emits radiation.","Step 3: A stable isotope does not undergo spontaneous radioactive decay under ordinary conditions."],"options":[],"conceptId":"chemistry_atomic_structure_uses_of_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q1","subject":"chemistry","chapter":"atomic_structure","topic":"Uses of Isotopes"}', 0),
  (3118, 761, 'Explain how a radioisotope can be used as a medical tracer.', 'text', 1, 'Focus on the core principle of Uses of Isotopes.', '{"why":"The detectable radiation provides information about the tracer''s location or movement.","sol":"Step 1: A suitable radioisotope is introduced for a specific diagnostic purpose under medical supervision.\nStep 2: It follows or participates in a process being investigated.\nStep 3: Radiation emitted by the tracer is detected externally or with suitable equipment.\nStep 4: The measurements provide information about the process or the distribution of the tracer.","steps":["Step 1: A suitable radioisotope is introduced for a specific diagnostic purpose under medical supervision.","Step 2: It follows or participates in a process being investigated.","Step 3: Radiation emitted by the tracer is detected externally or with suitable equipment.","Step 4: The measurements provide information about the process or the distribution of the tracer."],"options":[],"conceptId":"chemistry_atomic_structure_uses_of_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q2","subject":"chemistry","chapter":"atomic_structure","topic":"Uses of Isotopes"}', 1),
  (3119, 761, 'Give one industrial use of radioisotopes and explain the principle behind it.', 'text', 1, 'Focus on the core principle of Uses of Isotopes.', '{"why":"The relationship between radiation intensity and material thickness provides a measurement method.","sol":"Step 1: Identify thickness monitoring as one application.\nStep 2: Radiation passes through a material and some may be absorbed.\nStep 3: The detected radiation intensity changes with material thickness under suitable conditions.\nStep 4: Monitoring the detected intensity allows thickness to be controlled.","steps":["Step 1: Identify thickness monitoring as one application.","Step 2: Radiation passes through a material and some may be absorbed.","Step 3: The detected radiation intensity changes with material thickness under suitable conditions.","Step 4: Monitoring the detected intensity allows thickness to be controlled."],"options":[],"conceptId":"chemistry_atomic_structure_uses_of_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q3","subject":"chemistry","chapter":"atomic_structure","topic":"Uses of Isotopes"}', 2),
  (3120, 761, 'A radioisotope has a half-life of 4 hours. A sample initially contains 160 mg. Calculate the mass remaining after 12 hours.', 'text', 1, 'First calculate how many half-lives have elapsed.', '{"why":"Three half-lives reduce the original mass to one-eighth of its initial value.","sol":"Step 1: Number of half-lives = 12 / 4 = 3.\nStep 2: After 4 hours: 160 / 2 = 80 mg.\nStep 3: After 8 hours: 80 / 2 = 40 mg.\nStep 4: After 12 hours: 40 / 2 = 20 mg.\nStep 5: Check using the formula: 160 x (1/2)^3 = 20 mg.","steps":["Step 1: Number of half-lives = 12 / 4 = 3.","Step 2: After 4 hours: 160 / 2 = 80 mg.","Step 3: After 8 hours: 80 / 2 = 40 mg.","Step 4: After 12 hours: 40 / 2 = 20 mg.","Step 5: Check using the formula: 160 x (1/2)^3 = 20 mg."],"options":[],"conceptId":"chemistry_atomic_structure_uses_of_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q4","subject":"chemistry","chapter":"atomic_structure","topic":"Uses of Isotopes"}', 3),
  (3121, 761, 'A radioactive sample decreases from 200 mg to 25 mg. If its half-life is 6 days, calculate the time elapsed.', 'text', 1, 'Repeatedly halve 200 mg until you reach 25 mg.', '{"why":"Three half-lives are required to reduce the sample from 200 mg to 25 mg.","sol":"Step 1: 200 mg becomes 100 mg after one half-life.\nStep 2: 100 mg becomes 50 mg after two half-lives.\nStep 3: 50 mg becomes 25 mg after three half-lives.\nStep 4: Elapsed time = 3 x 6 = 18 days.","steps":["Step 1: 200 mg becomes 100 mg after one half-life.","Step 2: 100 mg becomes 50 mg after two half-lives.","Step 3: 50 mg becomes 25 mg after three half-lives.","Step 4: Elapsed time = 3 x 6 = 18 days."],"options":[],"conceptId":"chemistry_atomic_structure_uses_of_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q5","subject":"chemistry","chapter":"atomic_structure","topic":"Uses of Isotopes"}', 4),
  (3122, 761, 'Explain how carbon-14 dating can help estimate the age of suitable once-living material.', 'text', 1, 'Consider what happens to carbon exchange after an organism dies.', '{"why":"Radioactive decay provides a measurable relationship between elapsed time and the amount of carbon-14 remaining.","sol":"Step 1: Living organisms exchange carbon with their environment.\nStep 2: Carbon-14 is present in living material in small amounts.\nStep 3: After death, carbon exchange stops.\nStep 4: Carbon-14 decays with time.\nStep 5: Measuring the remaining carbon-14 and applying an appropriate dating method helps estimate the time since death.","steps":["Step 1: Living organisms exchange carbon with their environment.","Step 2: Carbon-14 is present in living material in small amounts.","Step 3: After death, carbon exchange stops.","Step 4: Carbon-14 decays with time.","Step 5: Measuring the remaining carbon-14 and applying an appropriate dating method helps estimate the time since death."],"options":[],"conceptId":"chemistry_atomic_structure_uses_of_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q6","subject":"chemistry","chapter":"atomic_structure","topic":"Uses of Isotopes"}', 5),
  (3123, 761, 'A radioisotope is used to monitor the thickness of a metal sheet. Explain why the detected radiation can provide information about the sheet''s thickness.', 'text', 1, 'Consider absorption of radiation as it passes through material.', '{"why":"Radiation attenuation provides a measurable signal that changes with material thickness.","sol":"Step 1: Radiation from a suitable source is directed toward the sheet.\nStep 2: Some radiation is absorbed or scattered by the material.\nStep 3: The detected intensity depends on the material''s thickness and the measurement arrangement.\nStep 4: A detector measures the transmitted radiation.\nStep 5: The measurements are calibrated to monitor thickness.","steps":["Step 1: Radiation from a suitable source is directed toward the sheet.","Step 2: Some radiation is absorbed or scattered by the material.","Step 3: The detected intensity depends on the material''s thickness and the measurement arrangement.","Step 4: A detector measures the transmitted radiation.","Step 5: The measurements are calibrated to monitor thickness."],"options":[],"conceptId":"chemistry_atomic_structure_uses_of_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q7","subject":"chemistry","chapter":"atomic_structure","topic":"Uses of Isotopes"}', 6),
  (3124, 761, 'State three precautions used to reduce exposure when handling radioactive sources and explain the principle behind each.', 'text', 1, 'Think about exposure time, distance and shielding.', '{"why":"These measures reduce the radiation dose received by a person.","sol":"Step 1: Minimise time near the source to reduce the duration of exposure.\nStep 2: Maximise distance where practical because radiation intensity generally decreases with distance from a point source.\nStep 3: Use suitable shielding to absorb or attenuate the relevant radiation.\nStep 4: Follow the appropriate handling and monitoring procedures.","steps":["Step 1: Minimise time near the source to reduce the duration of exposure.","Step 2: Maximise distance where practical because radiation intensity generally decreases with distance from a point source.","Step 3: Use suitable shielding to absorb or attenuate the relevant radiation.","Step 4: Follow the appropriate handling and monitoring procedures."],"options":[],"conceptId":"chemistry_atomic_structure_uses_of_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q8","subject":"chemistry","chapter":"atomic_structure","topic":"Uses of Isotopes"}', 7),
  (3125, 761, 'A sample contains 64 mg of a radioisotope with a half-life of 2 days. Calculate the mass remaining after 6 days and the percentage of the original sample remaining.', 'text', 1, 'Find the number of half-lives, then calculate the remaining mass and percentage.', '{"why":"Three half-lives leave one-eighth of the original radioactive isotope.","sol":"Step 1: Number of half-lives = 6 / 2 = 3.\nStep 2: After 2 days: 64 / 2 = 32 mg.\nStep 3: After 4 days: 32 / 2 = 16 mg.\nStep 4: After 6 days: 16 / 2 = 8 mg.\nStep 5: Percentage remaining = (8 / 64) x 100% = 12.5%.","steps":["Step 1: Number of half-lives = 6 / 2 = 3.","Step 2: After 2 days: 64 / 2 = 32 mg.","Step 3: After 4 days: 32 / 2 = 16 mg.","Step 4: After 6 days: 16 / 2 = 8 mg.","Step 5: Percentage remaining = (8 / 64) x 100% = 12.5%."],"options":[],"conceptId":"chemistry_atomic_structure_uses_of_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q9","subject":"chemistry","chapter":"atomic_structure","topic":"Uses of Isotopes"}', 8),
  (3126, 762, 'Define an ion and explain how it forms.', 'text', 1, 'Focus on the core principle of Ion Formation.', '{"why":"A difference between the positive proton count and negative electron count produces a net charge.","sol":"Step 1: An ion is a particle with a net electrical charge.\nStep 2: The charge arises when an atom or group of atoms gains or loses electrons.\nStep 3: The change in electron number creates an imbalance between protons and electrons.","steps":["Step 1: An ion is a particle with a net electrical charge.","Step 2: The charge arises when an atom or group of atoms gains or loses electrons.","Step 3: The change in electron number creates an imbalance between protons and electrons."],"options":[],"conceptId":"chemistry_atomic_structure_ion_formation","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q1","subject":"chemistry","chapter":"atomic_structure","topic":"Ion Formation"}', 0),
  (3127, 762, 'Write the equation for sodium forming a positive ion by losing one electron.', 'text', 1, 'Focus on the core principle of Ion Formation.', '{"why":"The lost electron appears on the product side because it leaves the atom.","sol":"Step 1: Sodium begins as a neutral atom, Na.\nStep 2: It loses one electron, e-.\nStep 3: The resulting ion has charge +1.\nStep 4: Write the equation: Na → Na+ + e-.","steps":["Step 1: Sodium begins as a neutral atom, Na.","Step 2: It loses one electron, e-.","Step 3: The resulting ion has charge +1.","Step 4: Write the equation: Na → Na+ + e-."],"options":[],"conceptId":"chemistry_atomic_structure_ion_formation","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q2","subject":"chemistry","chapter":"atomic_structure","topic":"Ion Formation"}', 1),
  (3128, 762, 'Chlorine gains one electron. Explain how its charge changes and write the ion symbol.', 'text', 1, 'Focus on the core principle of Ion Formation.', '{"why":"An extra electron produces one more negative charge than positive charge.","sol":"Step 1: A neutral chlorine atom has equal numbers of protons and electrons.\nStep 2: Gaining one electron adds one unit of negative charge.\nStep 3: The net charge becomes -1.\nStep 4: The ion is written as Cl-.","steps":["Step 1: A neutral chlorine atom has equal numbers of protons and electrons.","Step 2: Gaining one electron adds one unit of negative charge.","Step 3: The net charge becomes -1.","Step 4: The ion is written as Cl-."],"options":[],"conceptId":"chemistry_atomic_structure_ion_formation","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q3","subject":"chemistry","chapter":"atomic_structure","topic":"Ion Formation"}', 2),
  (3129, 762, 'A neutral magnesium atom has 12 protons and 12 electrons. It loses two electrons. Calculate the final electron number and charge, then write the ion symbol.', 'text', 1, 'Subtract the lost electrons from the initial electron count.', '{"why":"Losing two electrons leaves two more protons than electrons.","sol":"Step 1: Initial electrons = 12.\nStep 2: Final electrons = 12 - 2 = 10.\nStep 3: Protons remain 12.\nStep 4: Charge = 12 - 10 = +2.\nStep 5: Write Mg2+.","steps":["Step 1: Initial electrons = 12.","Step 2: Final electrons = 12 - 2 = 10.","Step 3: Protons remain 12.","Step 4: Charge = 12 - 10 = +2.","Step 5: Write Mg2+."],"options":[],"conceptId":"chemistry_atomic_structure_ion_formation","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q4","subject":"chemistry","chapter":"atomic_structure","topic":"Ion Formation"}', 3),
  (3130, 762, 'An oxygen atom gains two electrons. Write the electron-gain equation and calculate the charge of the resulting ion.', 'text', 1, 'Place the gained electrons on the left side of the equation.', '{"why":"Two gained electrons create two excess negative charges.","sol":"Step 1: A neutral oxygen atom has 8 electrons.\nStep 2: Gaining two electrons gives 8 + 2 = 10 electrons.\nStep 3: Proton number remains 8.\nStep 4: Charge = 8 - 10 = -2.\nStep 5: Equation: O + 2e- → O2-.","steps":["Step 1: A neutral oxygen atom has 8 electrons.","Step 2: Gaining two electrons gives 8 + 2 = 10 electrons.","Step 3: Proton number remains 8.","Step 4: Charge = 8 - 10 = -2.","Step 5: Equation: O + 2e- → O2-."],"options":[],"conceptId":"chemistry_atomic_structure_ion_formation","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q5","subject":"chemistry","chapter":"atomic_structure","topic":"Ion Formation"}', 4),
  (3131, 762, 'An aluminium atom has atomic number 13 and loses three electrons. Calculate the number of electrons remaining and explain why the ion has a positive charge.', 'text', 1, 'The proton count remains unchanged when electrons are lost.', '{"why":"Three fewer electrons than protons produce three units of excess positive charge.","sol":"Step 1: Initial electron number = 13.\nStep 2: Final electron number = 13 - 3 = 10.\nStep 3: Proton number remains 13.\nStep 4: Net charge = 13 - 10 = +3.\nStep 5: The ion is Al3+.","steps":["Step 1: Initial electron number = 13.","Step 2: Final electron number = 13 - 3 = 10.","Step 3: Proton number remains 13.","Step 4: Net charge = 13 - 10 = +3.","Step 5: The ion is Al3+."],"options":[],"conceptId":"chemistry_atomic_structure_ion_formation","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q6","subject":"chemistry","chapter":"atomic_structure","topic":"Ion Formation"}', 5),
  (3132, 762, 'A particle has 17 protons and 18 electrons. Identify its element, determine its charge and state whether it is a cation or an anion.', 'text', 1, 'Use proton number to identify the element and compare proton and electron counts.', '{"why":"The proton number identifies chlorine, and the extra electron produces a negative charge.","sol":"Step 1: Proton number 17 identifies chlorine.\nStep 2: Charge = 17 - 18 = -1.\nStep 3: The particle has an excess electron.\nStep 4: A negatively charged ion is an anion.","steps":["Step 1: Proton number 17 identifies chlorine.","Step 2: Charge = 17 - 18 = -1.","Step 3: The particle has an excess electron.","Step 4: A negatively charged ion is an anion."],"options":[],"conceptId":"chemistry_atomic_structure_ion_formation","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q7","subject":"chemistry","chapter":"atomic_structure","topic":"Ion Formation"}', 6),
  (3133, 762, 'A learner says sodium forms Na- when it loses an electron. Explain the mistake and write the correct formation equation.', 'text', 1, 'An electron has negative charge. Consider what remains when it is removed.', '{"why":"Removing negative charge leaves a net positive charge.","sol":"Step 1: A neutral sodium atom has 11 protons and 11 electrons.\nStep 2: Losing one electron leaves 11 protons and 10 electrons.\nStep 3: Charge = 11 - 10 = +1.\nStep 4: The correct ion is Na+.\nStep 5: Correct equation: Na → Na+ + e-.","steps":["Step 1: A neutral sodium atom has 11 protons and 11 electrons.","Step 2: Losing one electron leaves 11 protons and 10 electrons.","Step 3: Charge = 11 - 10 = +1.","Step 4: The correct ion is Na+.","Step 5: Correct equation: Na → Na+ + e-."],"options":[],"conceptId":"chemistry_atomic_structure_ion_formation","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q8","subject":"chemistry","chapter":"atomic_structure","topic":"Ion Formation"}', 7),
  (3134, 762, 'A particle contains 16 protons and 18 electrons. Calculate its charge, identify the element and explain what electron transfer would reverse the charge to +2.', 'text', 1, 'First calculate the present charge. Then determine the electron number required for +2.', '{"why":"Each lost electron increases the net charge by one unit. Changing charge does not change the element''s proton number.","sol":"Step 1: The element has atomic number 16, so it is sulfur.\nStep 2: Current charge = 16 - 18 = -2.\nStep 3: For charge +2, electrons must equal 16 - 2 = 14.\nStep 4: The particle must lose 18 - 14 = 4 electrons.\nStep 5: The resulting particle has 16 protons and 14 electrons, giving charge +2.","steps":["Step 1: The element has atomic number 16, so it is sulfur.","Step 2: Current charge = 16 - 18 = -2.","Step 3: For charge +2, electrons must equal 16 - 2 = 14.","Step 4: The particle must lose 18 - 14 = 4 electrons.","Step 5: The resulting particle has 16 protons and 14 electrons, giving charge +2."],"options":[],"conceptId":"chemistry_atomic_structure_ion_formation","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q9","subject":"chemistry","chapter":"atomic_structure","topic":"Ion Formation"}', 8),
  (3135, 763, 'Write the formula used to calculate the relative charge of an ion from its proton and electron numbers.', 'text', 1, 'Focus on the core principle of Writing Ion Charges.', '{"why":"The formula calculates the excess positive or negative charge.","sol":"Step 1: Each proton contributes +1 relative charge.\nStep 2: Each electron contributes -1 relative charge.\nStep 3: Subtract the electron number from the proton number.","steps":["Step 1: Each proton contributes +1 relative charge.","Step 2: Each electron contributes -1 relative charge.","Step 3: Subtract the electron number from the proton number."],"options":[],"conceptId":"chemistry_atomic_structure_writing_ion_charges","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q1","subject":"chemistry","chapter":"atomic_structure","topic":"Writing Ion Charges"}', 0),
  (3136, 763, 'An ion contains 12 protons and 10 electrons. Calculate its charge and write its symbol.', 'text', 1, 'Focus on the core principle of Writing Ion Charges.', '{"why":"Two more protons than electrons give a charge of +2.","sol":"Step 1: Charge = 12 - 10.\nStep 2: Charge = +2.\nStep 3: Atomic number 12 identifies magnesium.\nStep 4: Write Mg2+.","steps":["Step 1: Charge = 12 - 10.","Step 2: Charge = +2.","Step 3: Atomic number 12 identifies magnesium.","Step 4: Write Mg2+."],"options":[],"conceptId":"chemistry_atomic_structure_writing_ion_charges","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q2","subject":"chemistry","chapter":"atomic_structure","topic":"Writing Ion Charges"}', 1),
  (3137, 763, 'An ion contains 17 protons and 18 electrons. Calculate its charge and write its symbol.', 'text', 1, 'Focus on the core principle of Writing Ion Charges.', '{"why":"One extra electron gives a charge of -1.","sol":"Step 1: Charge = 17 - 18.\nStep 2: Charge = -1.\nStep 3: Atomic number 17 identifies chlorine.\nStep 4: Write Cl-.","steps":["Step 1: Charge = 17 - 18.","Step 2: Charge = -1.","Step 3: Atomic number 17 identifies chlorine.","Step 4: Write Cl-."],"options":[],"conceptId":"chemistry_atomic_structure_writing_ion_charges","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q3","subject":"chemistry","chapter":"atomic_structure","topic":"Writing Ion Charges"}', 2),
  (3138, 763, 'An oxygen atom gains two electrons. Calculate its electron number and write the resulting ion symbol.', 'text', 1, 'Oxygen has atomic number 8.', '{"why":"Two additional electrons give oxygen a charge of -2.","sol":"Step 1: A neutral oxygen atom has 8 electrons.\nStep 2: New electron number = 8 + 2 = 10.\nStep 3: Charge = 8 - 10 = -2.\nStep 4: Write O2-.","steps":["Step 1: A neutral oxygen atom has 8 electrons.","Step 2: New electron number = 8 + 2 = 10.","Step 3: Charge = 8 - 10 = -2.","Step 4: Write O2-."],"options":[],"conceptId":"chemistry_atomic_structure_writing_ion_charges","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q4","subject":"chemistry","chapter":"atomic_structure","topic":"Writing Ion Charges"}', 3),
  (3139, 763, 'An aluminium ion has 13 protons and a charge of +3. Calculate its electron number and verify the charge.', 'text', 1, 'Rearrange charge = protons - electrons.', '{"why":"The ion has three fewer electrons than protons.","sol":"Step 1: +3 = 13 - electrons.\nStep 2: Electrons = 13 - 3 = 10.\nStep 3: Verify: 13 - 10 = +3.","steps":["Step 1: +3 = 13 - electrons.","Step 2: Electrons = 13 - 3 = 10.","Step 3: Verify: 13 - 10 = +3."],"options":[],"conceptId":"chemistry_atomic_structure_writing_ion_charges","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q5","subject":"chemistry","chapter":"atomic_structure","topic":"Writing Ion Charges"}', 4),
  (3140, 763, 'A learner writes the ion of an atom with 11 protons and 10 electrons as Na-. Identify the error and write the correct symbol.', 'text', 1, 'Compare the number of positive and negative charges.', '{"why":"One fewer electron than proton gives a positive charge of +1.","sol":"Step 1: Atomic number 11 identifies sodium.\nStep 2: Charge = 11 - 10 = +1.\nStep 3: The particle has a positive charge, not a negative charge.\nStep 4: The correct symbol is Na+.","steps":["Step 1: Atomic number 11 identifies sodium.","Step 2: Charge = 11 - 10 = +1.","Step 3: The particle has a positive charge, not a negative charge.","Step 4: The correct symbol is Na+."],"options":[],"conceptId":"chemistry_atomic_structure_writing_ion_charges","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q6","subject":"chemistry","chapter":"atomic_structure","topic":"Writing Ion Charges"}', 5),
  (3141, 763, 'A particle has 20 protons and a charge of +2. Calculate its electron number and identify the element.', 'text', 1, 'A +2 charge means there are two fewer electrons than protons.', '{"why":"The proton number identifies calcium, and the +2 charge indicates two electrons have been lost from the neutral atom.","sol":"Step 1: Proton number = 20.\nStep 2: Electron number = 20 - 2 = 18.\nStep 3: Atomic number 20 identifies calcium.\nStep 4: The ion is Ca2+.","steps":["Step 1: Proton number = 20.","Step 2: Electron number = 20 - 2 = 18.","Step 3: Atomic number 20 identifies calcium.","Step 4: The ion is Ca2+."],"options":[],"conceptId":"chemistry_atomic_structure_writing_ion_charges","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q7","subject":"chemistry","chapter":"atomic_structure","topic":"Writing Ion Charges"}', 6),
  (3142, 763, 'An ion has 16 protons and 18 electrons. Calculate its charge and write the symbol. Then explain what would happen to its charge if it lost two electrons.', 'text', 1, 'Calculate the original charge first, then recalculate with 16 electrons.', '{"why":"Each lost electron increases the charge by one unit. Losing two electrons changes -2 to zero.","sol":"Step 1: Original charge = 16 - 18 = -2.\nStep 2: Atomic number 16 identifies sulfur.\nStep 3: The original ion is S2-.\nStep 4: Losing two electrons leaves 16 protons and 16 electrons.\nStep 5: New charge = 16 - 16 = 0.","steps":["Step 1: Original charge = 16 - 18 = -2.","Step 2: Atomic number 16 identifies sulfur.","Step 3: The original ion is S2-.","Step 4: Losing two electrons leaves 16 protons and 16 electrons.","Step 5: New charge = 16 - 16 = 0."],"options":[],"conceptId":"chemistry_atomic_structure_writing_ion_charges","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q8","subject":"chemistry","chapter":"atomic_structure","topic":"Writing Ion Charges"}', 7),
  (3143, 763, 'An ion has charge -3 and contains 18 electrons. Calculate its proton number and identify the element.', 'text', 1, 'Use -3 = protons - 18.', '{"why":"The -3 charge means there are three more electrons than protons.","sol":"Step 1: Let the proton number be p.\nStep 2: -3 = p - 18.\nStep 3: p = 18 - 3 = 15.\nStep 4: Atomic number 15 identifies phosphorus.","steps":["Step 1: Let the proton number be p.","Step 2: -3 = p - 18.","Step 3: p = 18 - 3 = 15.","Step 4: Atomic number 15 identifies phosphorus."],"options":[],"conceptId":"chemistry_atomic_structure_writing_ion_charges","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q9","subject":"chemistry","chapter":"atomic_structure","topic":"Writing Ion Charges"}', 8),
  (3144, 764, 'An element has atomic number 13. Determine the number of protons and electrons in a neutral atom, then identify the element.', 'text', 1, 'Atomic number gives the number of protons. A neutral atom has equal numbers of protons and electrons.', '{"why":"Atomic number uniquely identifies an element because every element has a different number of protons.","sol":"Step 1: Read the atomic number. It is 13.\nStep 2: The number of protons is therefore 13.\nStep 3: The atom is neutral, so its positive proton charge balances its negative electron charge.\nStep 4: The number of electrons must also be 13.\nStep 5: Atomic number 13 identifies aluminium, symbol Al.","steps":["Step 1: Read the atomic number. It is 13.","Step 2: The number of protons is therefore 13.","Step 3: The atom is neutral, so its positive proton charge balances its negative electron charge.","Step 4: The number of electrons must also be 13.","Step 5: Atomic number 13 identifies aluminium, symbol Al."],"options":[],"conceptId":"chemistry_periodic_table_arrangement_of_the_periodic_table","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q1","subject":"chemistry","chapter":"periodic_table","topic":"Arrangement of the Periodic Table"}', 0),
  (3145, 764, 'Explain why the modern periodic table is arranged in increasing atomic number rather than increasing atomic mass.', 'text', 1, 'Think about what uniquely identifies an element.', '{"why":"Isotopes of an element can have different masses but have the same atomic number.","sol":"Step 1: Atomic number is the number of protons in the nucleus.\nStep 2: The number of protons determines the identity of the element.\nStep 3: Atomic mass can vary between isotopes of the same element.\nStep 4: Therefore, atomic number provides the correct basis for the modern periodic order.","steps":["Step 1: Atomic number is the number of protons in the nucleus.","Step 2: The number of protons determines the identity of the element.","Step 3: Atomic mass can vary between isotopes of the same element.","Step 4: Therefore, atomic number provides the correct basis for the modern periodic order."],"options":[],"conceptId":"chemistry_periodic_table_arrangement_of_the_periodic_table","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q2","subject":"chemistry","chapter":"periodic_table","topic":"Arrangement of the Periodic Table"}', 1),
  (3146, 764, 'Identify the element with atomic number 17.', 'text', 1, 'Use the atomic number sequence, not the element''s position by mass.', '{"why":"Chlorine is the element with atomic number 17.","sol":"Step 1: Atomic number 17 means that the atom has 17 protons.\nStep 2: Find element 17 in the periodic sequence.\nStep 3: Element 17 is chlorine.\nStep 4: Its chemical symbol is Cl.","steps":["Step 1: Atomic number 17 means that the atom has 17 protons.","Step 2: Find element 17 in the periodic sequence.","Step 3: Element 17 is chlorine.","Step 4: Its chemical symbol is Cl."],"options":[],"conceptId":"chemistry_periodic_table_arrangement_of_the_periodic_table","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q3","subject":"chemistry","chapter":"periodic_table","topic":"Arrangement of the Periodic Table"}', 2),
  (3147, 764, 'An unknown neutral atom has 12 protons. Identify the element.', 'text', 1, 'For a neutral atom, the proton number equals the electron number. The proton number is the atomic number.', '{"why":"The identity of an element is determined by its atomic number, not by the number of neutrons.","sol":"Step 1: The atom has 12 protons.\nStep 2: Its atomic number is therefore 12.\nStep 3: Atomic number 12 identifies magnesium.","steps":["Step 1: The atom has 12 protons.","Step 2: Its atomic number is therefore 12.","Step 3: Atomic number 12 identifies magnesium."],"options":[],"conceptId":"chemistry_periodic_table_arrangement_of_the_periodic_table","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q4","subject":"chemistry","chapter":"periodic_table","topic":"Arrangement of the Periodic Table"}', 3),
  (3148, 764, 'Explain what a horizontal row in the periodic table is called.', 'text', 1, 'Distinguish horizontal rows from vertical columns.', '{"why":"The period number is related to the number of occupied main electron energy levels for the elements studied here.","sol":"Step 1: Identify the horizontal direction across the table.\nStep 2: Horizontal rows are called periods.","steps":["Step 1: Identify the horizontal direction across the table.","Step 2: Horizontal rows are called periods."],"options":[],"conceptId":"chemistry_periodic_table_arrangement_of_the_periodic_table","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q5","subject":"chemistry","chapter":"periodic_table","topic":"Arrangement of the Periodic Table"}', 4),
  (3149, 764, 'An element has atomic number 8. Identify its chemical symbol.', 'text', 1, 'Find element 8 in the first 20 elements.', '{"why":"Oxygen has eight protons, so its atomic number is 8.","sol":"Step 1: Atomic number 8 identifies oxygen.\nStep 2: The chemical symbol for oxygen is O.","steps":["Step 1: Atomic number 8 identifies oxygen.","Step 2: The chemical symbol for oxygen is O."],"options":[],"conceptId":"chemistry_periodic_table_arrangement_of_the_periodic_table","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q6","subject":"chemistry","chapter":"periodic_table","topic":"Arrangement of the Periodic Table"}', 5),
  (3150, 764, 'Explain what a vertical column in the periodic table is called.', 'text', 1, 'Think of the columns that run from top to bottom.', '{"why":"Elements in the same main group generally have related outer-electron arrangements.","sol":"Step 1: Identify the vertical direction in the table.\nStep 2: Vertical columns are called groups.","steps":["Step 1: Identify the vertical direction in the table.","Step 2: Vertical columns are called groups."],"options":[],"conceptId":"chemistry_periodic_table_arrangement_of_the_periodic_table","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q7","subject":"chemistry","chapter":"periodic_table","topic":"Arrangement of the Periodic Table"}', 6),
  (3151, 764, 'A neutral atom has 15 electrons. Determine its atomic number.', 'text', 1, 'In a neutral atom, the number of electrons equals the number of protons.', '{"why":"A neutral atom has equal numbers of protons and electrons. Atomic number counts protons.","sol":"Step 1: The atom has 15 electrons.\nStep 2: Because it is neutral, it has 15 protons.\nStep 3: Atomic number equals proton number.\nStep 4: Its atomic number is 15.","steps":["Step 1: The atom has 15 electrons.","Step 2: Because it is neutral, it has 15 protons.","Step 3: Atomic number equals proton number.","Step 4: Its atomic number is 15."],"options":[],"conceptId":"chemistry_periodic_table_arrangement_of_the_periodic_table","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q8","subject":"chemistry","chapter":"periodic_table","topic":"Arrangement of the Periodic Table"}', 7),
  (3152, 765, 'An atom has electron arrangement 2,8,1. Determine its group using the older school notation.', 'text', 1, 'Count only the electrons in the outermost occupied energy level.', '{"why":"The atom has one outer electron, which is characteristic of the alkali metals in the main-group elements.","sol":"Step 1: The arrangement is 2,8,1.\nStep 2: The outermost energy level contains one electron.\nStep 3: For this main-group element, one outer electron indicates Group 1.","steps":["Step 1: The arrangement is 2,8,1.","Step 2: The outermost energy level contains one electron.","Step 3: For this main-group element, one outer electron indicates Group 1."],"options":[],"conceptId":"chemistry_periodic_table_groups","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q1","subject":"chemistry","chapter":"periodic_table","topic":"Groups"}', 0),
  (3153, 765, 'Explain why sodium and potassium have similar chemical properties.', 'text', 1, 'Compare the final number in their electron arrangements.', '{"why":"Chemical reactions depend strongly on outer electrons, so related outer-electron arrangements often lead to related chemical properties.","sol":"Step 1: Sodium has the arrangement 2,8,1.\nStep 2: Potassium has the arrangement 2,8,8,1.\nStep 3: Both have one outer electron.\nStep 4: Both can lose this electron to form a +1 ion.\nStep 5: Their related outer-electron arrangements produce similar chemical behaviour.","steps":["Step 1: Sodium has the arrangement 2,8,1.","Step 2: Potassium has the arrangement 2,8,8,1.","Step 3: Both have one outer electron.","Step 4: Both can lose this electron to form a +1 ion.","Step 5: Their related outer-electron arrangements produce similar chemical behaviour."],"options":[],"conceptId":"chemistry_periodic_table_groups","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q2","subject":"chemistry","chapter":"periodic_table","topic":"Groups"}', 1),
  (3154, 765, 'An atom has electron arrangement 2,8,7. Identify its group using the older school notation.', 'text', 1, 'Count the electrons in the final energy level.', '{"why":"Halogens have seven outer electrons and commonly gain one electron to form −1 ions.","sol":"Step 1: The outermost level contains seven electrons.\nStep 2: Seven outer electrons identify Group 7 among the main-group elements in this notation.\nStep 3: Group 7 elements are the halogens.","steps":["Step 1: The outermost level contains seven electrons.","Step 2: Seven outer electrons identify Group 7 among the main-group elements in this notation.","Step 3: Group 7 elements are the halogens."],"options":[],"conceptId":"chemistry_periodic_table_groups","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q3","subject":"chemistry","chapter":"periodic_table","topic":"Groups"}', 2),
  (3155, 765, 'An atom has electron arrangement 2,8,2. Identify its group using the older school notation.', 'text', 1, 'Use the number of outer electrons.', '{"why":"Group 2 elements such as magnesium and calcium have two outer electrons.","sol":"Step 1: The outermost level contains two electrons.\nStep 2: Two outer electrons indicate Group 2 for this main-group element.","steps":["Step 1: The outermost level contains two electrons.","Step 2: Two outer electrons indicate Group 2 for this main-group element."],"options":[],"conceptId":"chemistry_periodic_table_groups","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q4","subject":"chemistry","chapter":"periodic_table","topic":"Groups"}', 3),
  (3156, 765, 'Explain why elements in the same main group tend to have similar chemical properties.', 'text', 1, 'Think about the electrons involved in chemical reactions.', '{"why":"Outer-electron arrangements strongly influence bonding and chemical reactions.","sol":"Step 1: Chemical reactions involve changes in electron arrangements, especially outer electrons.\nStep 2: Elements in the same main group generally have the same number of outer electrons.\nStep 3: They therefore tend to lose, gain or share electrons in related ways.","steps":["Step 1: Chemical reactions involve changes in electron arrangements, especially outer electrons.","Step 2: Elements in the same main group generally have the same number of outer electrons.","Step 3: They therefore tend to lose, gain or share electrons in related ways."],"options":[],"conceptId":"chemistry_periodic_table_groups","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q5","subject":"chemistry","chapter":"periodic_table","topic":"Groups"}', 4),
  (3157, 765, 'An atom has electron arrangement 2,8,6. Identify its group using the older school notation.', 'text', 1, 'Count the electrons in the outermost level, not all the electrons.', '{"why":"Sulfur, with arrangement 2,8,6, belongs to Group 6 under the older school notation.","sol":"Step 1: The outermost level contains six electrons.\nStep 2: For this main-group element, six outer electrons indicate Group 6.","steps":["Step 1: The outermost level contains six electrons.","Step 2: For this main-group element, six outer electrons indicate Group 6."],"options":[],"conceptId":"chemistry_periodic_table_groups","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q6","subject":"chemistry","chapter":"periodic_table","topic":"Groups"}', 5),
  (3158, 765, 'State the modern IUPAC group number for the halogens.', 'text', 1, 'Modern IUPAC groups are numbered from 1 to 18.', '{"why":"Group 17 is the modern numbering for the halogens, often called Group 7 in older school notation.","sol":"Step 1: Halogens include fluorine and chlorine.\nStep 2: In modern IUPAC numbering, their column is Group 17.","steps":["Step 1: Halogens include fluorine and chlorine.","Step 2: In modern IUPAC numbering, their column is Group 17."],"options":[],"conceptId":"chemistry_periodic_table_groups","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q7","subject":"chemistry","chapter":"periodic_table","topic":"Groups"}', 6),
  (3159, 765, 'An element belongs to Group 1 and has one outer electron. What ion charge does it commonly form when it loses that electron?', 'text', 1, 'An electron has a negative charge.', '{"why":"Losing one electron removes one unit of negative charge, leaving a net charge of +1.","sol":"Step 1: The atom begins with equal numbers of protons and electrons.\nStep 2: It loses one negatively charged electron.\nStep 3: It now has one more proton than electrons.\nStep 4: Its net charge is +1.","steps":["Step 1: The atom begins with equal numbers of protons and electrons.","Step 2: It loses one negatively charged electron.","Step 3: It now has one more proton than electrons.","Step 4: Its net charge is +1."],"options":[],"conceptId":"chemistry_periodic_table_groups","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q8","subject":"chemistry","chapter":"periodic_table","topic":"Groups"}', 7),
  (3160, 766, 'Determine the period of an element with electron arrangement 2,8,3.', 'text', 1, 'Count the occupied energy levels, not the electrons.', '{"why":"For the first 20 elements, the number of occupied main energy levels determines the period.","sol":"Step 1: The first number represents the first occupied level.\nStep 2: The second number represents the second occupied level.\nStep 3: The third number represents the third occupied level.\nStep 4: There are three occupied energy levels.\nStep 5: Therefore, the element is in Period 3.","steps":["Step 1: The first number represents the first occupied level.","Step 2: The second number represents the second occupied level.","Step 3: The third number represents the third occupied level.","Step 4: There are three occupied energy levels.","Step 5: Therefore, the element is in Period 3."],"options":[],"conceptId":"chemistry_periodic_table_periods","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q1","subject":"chemistry","chapter":"periodic_table","topic":"Periods"}', 0),
  (3161, 766, 'An element is in Period 2. Explain what this tells you about its electron arrangement.', 'text', 1, 'A period number is related to occupied energy levels.', '{"why":"The period number indicates the number of occupied main energy levels for the elements studied here.","sol":"Step 1: Period 2 means the element has two occupied main energy levels.\nStep 2: Its electrons are therefore distributed across two occupied levels.\nStep 3: For example, carbon has the arrangement 2,4 and oxygen has 2,6.","steps":["Step 1: Period 2 means the element has two occupied main energy levels.","Step 2: Its electrons are therefore distributed across two occupied levels.","Step 3: For example, carbon has the arrangement 2,4 and oxygen has 2,6."],"options":[],"conceptId":"chemistry_periodic_table_periods","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q2","subject":"chemistry","chapter":"periodic_table","topic":"Periods"}', 1),
  (3162, 766, 'Determine the period of an element with electron arrangement 2,8,8,2.', 'text', 1, 'Count how many occupied energy levels are shown.', '{"why":"Calcium has this arrangement and is located in the fourth period.","sol":"Step 1: The arrangement contains four numbers.\nStep 2: Each number represents an occupied energy level.\nStep 3: There are four occupied energy levels.\nStep 4: Therefore, the element belongs to Period 4.","steps":["Step 1: The arrangement contains four numbers.","Step 2: Each number represents an occupied energy level.","Step 3: There are four occupied energy levels.","Step 4: Therefore, the element belongs to Period 4."],"options":[],"conceptId":"chemistry_periodic_table_periods","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q3","subject":"chemistry","chapter":"periodic_table","topic":"Periods"}', 2),
  (3163, 766, 'An element has electron arrangement 2,6. Determine its period.', 'text', 1, 'Count the occupied energy levels.', '{"why":"Oxygen, with arrangement 2,6, is in the second period.","sol":"Step 1: There are two numbers in the arrangement.\nStep 2: Therefore, two energy levels are occupied.\nStep 3: The element belongs to Period 2.","steps":["Step 1: There are two numbers in the arrangement.","Step 2: Therefore, two energy levels are occupied.","Step 3: The element belongs to Period 2."],"options":[],"conceptId":"chemistry_periodic_table_periods","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q4","subject":"chemistry","chapter":"periodic_table","topic":"Periods"}', 3),
  (3164, 766, 'Explain why sodium, with electron arrangement 2,8,1, belongs to Period 3.', 'text', 1, 'The last number is not the period number.', '{"why":"The period depends on the number of occupied levels, not on the number of outer electrons.","sol":"Step 1: Identify the arrangement: 2,8,1.\nStep 2: Count the occupied levels: the first, second and third.\nStep 3: Three levels are occupied.\nStep 4: Therefore, sodium belongs to Period 3.","steps":["Step 1: Identify the arrangement: 2,8,1.","Step 2: Count the occupied levels: the first, second and third.","Step 3: Three levels are occupied.","Step 4: Therefore, sodium belongs to Period 3."],"options":[],"conceptId":"chemistry_periodic_table_periods","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q5","subject":"chemistry","chapter":"periodic_table","topic":"Periods"}', 4),
  (3165, 766, 'An element has three occupied main energy levels. Determine its period.', 'text', 1, 'The period number equals the number of occupied levels for the elements studied here.', '{"why":"Period 3 elements have electrons occupying three main energy levels.","sol":"Step 1: The element has three occupied levels.\nStep 2: The corresponding period number is 3.","steps":["Step 1: The element has three occupied levels.","Step 2: The corresponding period number is 3."],"options":[],"conceptId":"chemistry_periodic_table_periods","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q6","subject":"chemistry","chapter":"periodic_table","topic":"Periods"}', 5),
  (3166, 766, 'An atom has 12 electrons arranged as 2,8,2. Determine its period.', 'text', 1, 'Do not use the total of 12 electrons.', '{"why":"Magnesium has 12 electrons but only three occupied main energy levels.","sol":"Step 1: The arrangement is 2,8,2.\nStep 2: Count the occupied levels, not the electrons.\nStep 3: There are three occupied levels.\nStep 4: The element is in Period 3.","steps":["Step 1: The arrangement is 2,8,2.","Step 2: Count the occupied levels, not the electrons.","Step 3: There are three occupied levels.","Step 4: The element is in Period 3."],"options":[],"conceptId":"chemistry_periodic_table_periods","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q7","subject":"chemistry","chapter":"periodic_table","topic":"Periods"}', 6),
  (3167, 766, 'Explain why magnesium and chlorine are in the same period even though their outer-electron arrangements differ.', 'text', 1, 'Compare the number of occupied levels in 2,8,2 and 2,8,7.', '{"why":"Period membership depends on the number of occupied energy levels, not on the number of outer electrons.","sol":"Step 1: Magnesium has arrangement 2,8,2.\nStep 2: Chlorine has arrangement 2,8,7.\nStep 3: Both arrangements contain three occupied energy levels.\nStep 4: Therefore, both elements belong to Period 3.","steps":["Step 1: Magnesium has arrangement 2,8,2.","Step 2: Chlorine has arrangement 2,8,7.","Step 3: Both arrangements contain three occupied energy levels.","Step 4: Therefore, both elements belong to Period 3."],"options":[],"conceptId":"chemistry_periodic_table_periods","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q8","subject":"chemistry","chapter":"periodic_table","topic":"Periods"}', 7),
  (3168, 767, 'Write the electronic structure of a neutral silicon atom with atomic number 14.', 'text', 1, 'Distribute 14 electrons among the first three shells.', '{"why":"The arrangement distributes all 14 electrons among the occupied shells.","sol":"Step 1: A neutral silicon atom has 14 electrons.\nStep 2: Put 2 electrons in the first shell. Remaining: 14 − 2 = 12.\nStep 3: Put 8 electrons in the second shell. Remaining: 12 − 8 = 4.\nStep 4: Place the remaining 4 electrons in the third shell.\nStep 5: Check the total: 2 + 8 + 4 = 14.","steps":["Step 1: A neutral silicon atom has 14 electrons.","Step 2: Put 2 electrons in the first shell. Remaining: 14 − 2 = 12.","Step 3: Put 8 electrons in the second shell. Remaining: 12 − 8 = 4.","Step 4: Place the remaining 4 electrons in the third shell.","Step 5: Check the total: 2 + 8 + 4 = 14."],"options":[],"conceptId":"chemistry_periodic_table_electronic_structure_and_periodic_position","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q1","subject":"chemistry","chapter":"periodic_table","topic":"Electronic Structure and Periodic Position"}', 0),
  (3169, 767, 'An element has electronic structure 2,8,5. Determine its period.', 'text', 1, 'Count the occupied shells rather than adding their electrons.', '{"why":"The number of occupied main energy levels determines the period for the elements covered by this shell model.","sol":"Step 1: Identify the three entries: 2, 8 and 5.\nStep 2: Each entry represents an occupied shell.\nStep 3: There are three occupied shells.\nStep 4: The element is in Period 3.","steps":["Step 1: Identify the three entries: 2, 8 and 5.","Step 2: Each entry represents an occupied shell.","Step 3: There are three occupied shells.","Step 4: The element is in Period 3."],"options":[],"conceptId":"chemistry_periodic_table_electronic_structure_and_periodic_position","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q2","subject":"chemistry","chapter":"periodic_table","topic":"Electronic Structure and Periodic Position"}', 1),
  (3170, 767, 'An element has electronic structure 2,8,4. Determine its group using the older school notation.', 'text', 1, 'Use the number of electrons in the outermost shell.', '{"why":"Silicon has four outer electrons and is classified in Group 4 under the older school notation.","sol":"Step 1: The outermost shell contains 4 electrons.\nStep 2: This is a main-group element in the first 20 elements.\nStep 3: Four outer electrons correspond to Group 4 in the older school notation.","steps":["Step 1: The outermost shell contains 4 electrons.","Step 2: This is a main-group element in the first 20 elements.","Step 3: Four outer electrons correspond to Group 4 in the older school notation."],"options":[],"conceptId":"chemistry_periodic_table_electronic_structure_and_periodic_position","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q3","subject":"chemistry","chapter":"periodic_table","topic":"Electronic Structure and Periodic Position"}', 2),
  (3171, 767, 'Write the electronic structure of a neutral atom with atomic number 16.', 'text', 1, 'The neutral atom has 16 electrons.', '{"why":"The shell arrangement contains 16 electrons in total.","sol":"Step 1: Total electrons = 16.\nStep 2: The first shell receives 2. Remaining = 14.\nStep 3: The second shell receives 8. Remaining = 6.\nStep 4: Place the remaining 6 electrons in the third shell.","steps":["Step 1: Total electrons = 16.","Step 2: The first shell receives 2. Remaining = 14.","Step 3: The second shell receives 8. Remaining = 6.","Step 4: Place the remaining 6 electrons in the third shell."],"options":[],"conceptId":"chemistry_periodic_table_electronic_structure_and_periodic_position","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q4","subject":"chemistry","chapter":"periodic_table","topic":"Electronic Structure and Periodic Position"}', 3),
  (3172, 767, 'Determine the group of an element with arrangement 2,8,3 using the older school notation.', 'text', 1, 'Count the outermost electrons.', '{"why":"Aluminium has arrangement 2,8,3 and belongs to Group 3 in the older school notation.","sol":"Step 1: The outer shell contains 3 electrons.\nStep 2: For this main-group element, three outer electrons indicate Group 3.","steps":["Step 1: The outer shell contains 3 electrons.","Step 2: For this main-group element, three outer electrons indicate Group 3."],"options":[],"conceptId":"chemistry_periodic_table_electronic_structure_and_periodic_position","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q5","subject":"chemistry","chapter":"periodic_table","topic":"Electronic Structure and Periodic Position"}', 4),
  (3173, 767, 'An atom has arrangement 2,8,7. Determine its period.', 'text', 1, 'Count the occupied shells.', '{"why":"Chlorine has three occupied shells and belongs to Period 3.","sol":"Step 1: The arrangement has three occupied shells.\nStep 2: Three occupied shells indicate Period 3.","steps":["Step 1: The arrangement has three occupied shells.","Step 2: Three occupied shells indicate Period 3."],"options":[],"conceptId":"chemistry_periodic_table_electronic_structure_and_periodic_position","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q6","subject":"chemistry","chapter":"periodic_table","topic":"Electronic Structure and Periodic Position"}', 5),
  (3174, 767, 'A neutral atom has 12 electrons. It forms a 2+ ion. Determine the number of electrons in the ion.', 'text', 1, 'A 2+ ion has lost two electrons.', '{"why":"A positive ionic charge results from losing negatively charged electrons.","sol":"Step 1: The neutral atom has 12 electrons.\nStep 2: A 2+ charge indicates the loss of two electrons.\nStep 3: Calculate 12 − 2 = 10.","steps":["Step 1: The neutral atom has 12 electrons.","Step 2: A 2+ charge indicates the loss of two electrons.","Step 3: Calculate 12 − 2 = 10."],"options":[],"conceptId":"chemistry_periodic_table_electronic_structure_and_periodic_position","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q7","subject":"chemistry","chapter":"periodic_table","topic":"Electronic Structure and Periodic Position"}', 6),
  (3175, 767, 'An ion has electronic structure 2,8 and a charge of 1−. Determine the number of electrons in its neutral atom.', 'text', 1, 'First count the ion''s electrons, then reverse the electron gain.', '{"why":"The ion has one more electron than the neutral atom. Atomic number 9 identifies fluorine.","sol":"Step 1: The ion contains 2 + 8 = 10 electrons.\nStep 2: A 1− charge means it has gained one electron compared with its neutral atom.\nStep 3: The neutral atom therefore had 10 − 1 = 9 electrons.","steps":["Step 1: The ion contains 2 + 8 = 10 electrons.","Step 2: A 1− charge means it has gained one electron compared with its neutral atom.","Step 3: The neutral atom therefore had 10 − 1 = 9 electrons."],"options":[],"conceptId":"chemistry_periodic_table_electronic_structure_and_periodic_position","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q8","subject":"chemistry","chapter":"periodic_table","topic":"Electronic Structure and Periodic Position"}', 7),
  (3176, 768, 'An atom has electronic structure 2,8,1. Explain why it tends to form a +1 ion.', 'text', 1, 'Consider what happens when its one outer electron is lost.', '{"why":"The loss of one electron produces a net positive charge of one.","sol":"Step 1: The atom has one outer electron.\nStep 2: It can lose that electron.\nStep 3: Losing one negative charge leaves one more proton than electrons.\nStep 4: The resulting ion has charge +1.","steps":["Step 1: The atom has one outer electron.","Step 2: It can lose that electron.","Step 3: Losing one negative charge leaves one more proton than electrons.","Step 4: The resulting ion has charge +1."],"options":[],"conceptId":"chemistry_periodic_table_group_1_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q1","subject":"chemistry","chapter":"periodic_table","topic":"Group 1 Elements"}', 0),
  (3177, 768, 'Explain why potassium is more reactive than lithium.', 'text', 1, 'Compare the distance and shielding of the outer electron.', '{"why":"Group 1 reactivity generally increases down the group because the outer electron becomes easier to remove.","sol":"Step 1: Both are Group 1 metals and react by losing one outer electron.\nStep 2: Potassium has more occupied energy levels than lithium.\nStep 3: Its outer electron is farther from the nucleus and more shielded by inner electrons.\nStep 4: The outer electron is easier to remove.\nStep 5: Potassium therefore reacts more readily.","steps":["Step 1: Both are Group 1 metals and react by losing one outer electron.","Step 2: Potassium has more occupied energy levels than lithium.","Step 3: Its outer electron is farther from the nucleus and more shielded by inner electrons.","Step 4: The outer electron is easier to remove.","Step 5: Potassium therefore reacts more readily."],"options":[],"conceptId":"chemistry_periodic_table_group_1_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q2","subject":"chemistry","chapter":"periodic_table","topic":"Group 1 Elements"}', 1),
  (3178, 768, 'Write the balanced symbol equation for sodium reacting with water.', 'text', 1, 'The products are sodium hydroxide and hydrogen gas.', '{"why":"The balanced equation has two sodium atoms, two oxygen atoms and four hydrogen atoms on each side.","sol":"Step 1: Write the correct formulae: Na + H₂O → NaOH + H₂.\nStep 2: Put 2 before Na and NaOH.\nStep 3: Put 2 before H₂O to balance oxygen.\nStep 4: Count atoms to verify the equation.","steps":["Step 1: Write the correct formulae: Na + H₂O → NaOH + H₂.","Step 2: Put 2 before Na and NaOH.","Step 3: Put 2 before H₂O to balance oxygen.","Step 4: Count atoms to verify the equation."],"options":[],"conceptId":"chemistry_periodic_table_group_1_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q3","subject":"chemistry","chapter":"periodic_table","topic":"Group 1 Elements"}', 2),
  (3179, 768, 'Determine the charge of the ion formed when a lithium atom loses one electron.', 'text', 1, 'Losing an electron removes one negative charge.', '{"why":"A Group 1 atom commonly forms a singly charged positive ion.","sol":"Step 1: Lithium loses one electron.\nStep 2: It now has one more proton than electrons.\nStep 3: Its net charge is +1.","steps":["Step 1: Lithium loses one electron.","Step 2: It now has one more proton than electrons.","Step 3: Its net charge is +1."],"options":[],"conceptId":"chemistry_periodic_table_group_1_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q4","subject":"chemistry","chapter":"periodic_table","topic":"Group 1 Elements"}', 3),
  (3180, 768, 'Explain why Group 1 elements have similar chemical properties.', 'text', 1, 'Compare the outer-electron arrangements of lithium and sodium.', '{"why":"Related outer-electron arrangements produce similar chemical behaviour.","sol":"Step 1: Lithium has arrangement 2,1.\nStep 2: Sodium has arrangement 2,8,1.\nStep 3: Both have one outer electron.\nStep 4: Both tend to lose one electron in reactions.","steps":["Step 1: Lithium has arrangement 2,1.","Step 2: Sodium has arrangement 2,8,1.","Step 3: Both have one outer electron.","Step 4: Both tend to lose one electron in reactions."],"options":[],"conceptId":"chemistry_periodic_table_group_1_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q5","subject":"chemistry","chapter":"periodic_table","topic":"Group 1 Elements"}', 4),
  (3181, 768, 'Identify the gas formed when sodium reacts with water.', 'text', 1, 'Use the products in the general Group 1 reaction.', '{"why":"Hydrogen is produced when a Group 1 metal reacts with water.","sol":"Step 1: Sodium reacts with water.\nStep 2: The products are sodium hydroxide and hydrogen.\nStep 3: The gas is hydrogen.","steps":["Step 1: Sodium reacts with water.","Step 2: The products are sodium hydroxide and hydrogen.","Step 3: The gas is hydrogen."],"options":[],"conceptId":"chemistry_periodic_table_group_1_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q6","subject":"chemistry","chapter":"periodic_table","topic":"Group 1 Elements"}', 5),
  (3182, 768, 'Explain why sodium is generally less reactive than potassium.', 'text', 1, 'Focus on how easily the outer electron can be removed.', '{"why":"Reactivity increases down Group 1 as the outer electron becomes easier to remove.","sol":"Step 1: Sodium and potassium both react by losing one outer electron.\nStep 2: Potassium is lower in Group 1 and has more occupied energy levels.\nStep 3: Its outer electron is farther from the nucleus and more shielded.\nStep 4: Potassium loses its outer electron more readily.","steps":["Step 1: Sodium and potassium both react by losing one outer electron.","Step 2: Potassium is lower in Group 1 and has more occupied energy levels.","Step 3: Its outer electron is farther from the nucleus and more shielded.","Step 4: Potassium loses its outer electron more readily."],"options":[],"conceptId":"chemistry_periodic_table_group_1_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q7","subject":"chemistry","chapter":"periodic_table","topic":"Group 1 Elements"}', 6),
  (3183, 768, 'Balance the equation: K + H₂O → KOH + H₂.', 'text', 1, 'Use the same balancing method as for sodium and water.', '{"why":"Both sides contain two potassium atoms, two oxygen atoms and four hydrogen atoms.","sol":"Step 1: Start with K + H₂O → KOH + H₂.\nStep 2: Put 2 before K and KOH.\nStep 3: Put 2 before H₂O to balance oxygen.\nStep 4: Check that potassium, oxygen and hydrogen atoms balance.","steps":["Step 1: Start with K + H₂O → KOH + H₂.","Step 2: Put 2 before K and KOH.","Step 3: Put 2 before H₂O to balance oxygen.","Step 4: Check that potassium, oxygen and hydrogen atoms balance."],"options":[],"conceptId":"chemistry_periodic_table_group_1_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q8","subject":"chemistry","chapter":"periodic_table","topic":"Group 1 Elements"}', 7),
  (3184, 769, 'Write the electronic structure of a neutral calcium atom with atomic number 20.', 'text', 1, 'Distribute 20 electrons across four occupied shells.', '{"why":"The arrangement accounts for all 20 electrons in a neutral calcium atom.","sol":"Step 1: Calcium has 20 electrons.\nStep 2: Place 2 in the first shell. Remaining: 18.\nStep 3: Place 8 in the second shell. Remaining: 10.\nStep 4: Place 8 in the third shell. Remaining: 2.\nStep 5: Place the final 2 in the fourth shell.\nStep 6: Check: 2 + 8 + 8 + 2 = 20.","steps":["Step 1: Calcium has 20 electrons.","Step 2: Place 2 in the first shell. Remaining: 18.","Step 3: Place 8 in the second shell. Remaining: 10.","Step 4: Place 8 in the third shell. Remaining: 2.","Step 5: Place the final 2 in the fourth shell.","Step 6: Check: 2 + 8 + 8 + 2 = 20."],"options":[],"conceptId":"chemistry_periodic_table_group_2_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q1","subject":"chemistry","chapter":"periodic_table","topic":"Group 2 Elements"}', 0),
  (3185, 769, 'Write the ionic equation for a magnesium atom losing two electrons.', 'text', 1, 'Electrons appear on the product side when an atom loses them.', '{"why":"The equation conserves both the number of magnesium atoms and the total electrical charge.","sol":"Step 1: Write Mg as the reactant.\nStep 2: Show the two electrons lost as 2e⁻.\nStep 3: The remaining magnesium ion has charge +2.\nStep 4: Write Mg → Mg²⁺ + 2e⁻.\nStep 5: Check charge: the right side has +2 − 2 = 0.","steps":["Step 1: Write Mg as the reactant.","Step 2: Show the two electrons lost as 2e⁻.","Step 3: The remaining magnesium ion has charge +2.","Step 4: Write Mg → Mg²⁺ + 2e⁻.","Step 5: Check charge: the right side has +2 − 2 = 0."],"options":[],"conceptId":"chemistry_periodic_table_group_2_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q2","subject":"chemistry","chapter":"periodic_table","topic":"Group 2 Elements"}', 1),
  (3186, 769, 'Explain why calcium is more reactive than magnesium in the general Group 2 trend.', 'text', 1, 'Compare their outer electrons and occupied energy levels.', '{"why":"Group 2 reactivity generally increases down the group as electron removal becomes easier.","sol":"Step 1: Both are Group 2 metals and tend to lose two outer electrons.\nStep 2: Calcium is below magnesium and has an additional occupied energy level.\nStep 3: Calcium''s outer electrons are farther from the nucleus and more shielded.\nStep 4: These electrons are generally easier to remove.\nStep 5: Calcium is therefore more reactive.","steps":["Step 1: Both are Group 2 metals and tend to lose two outer electrons.","Step 2: Calcium is below magnesium and has an additional occupied energy level.","Step 3: Calcium''s outer electrons are farther from the nucleus and more shielded.","Step 4: These electrons are generally easier to remove.","Step 5: Calcium is therefore more reactive."],"options":[],"conceptId":"chemistry_periodic_table_group_2_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q3","subject":"chemistry","chapter":"periodic_table","topic":"Group 2 Elements"}', 2),
  (3187, 769, 'Determine the charge of the ion formed when a beryllium atom loses its two outer electrons.', 'text', 1, 'Each electron lost removes one negative charge.', '{"why":"Group 2 metals commonly form ions with a 2+ charge.","sol":"Step 1: Beryllium loses two electrons.\nStep 2: Its positive proton charge now exceeds its electron charge by two.\nStep 3: The resulting ion has charge +2.","steps":["Step 1: Beryllium loses two electrons.","Step 2: Its positive proton charge now exceeds its electron charge by two.","Step 3: The resulting ion has charge +2."],"options":[],"conceptId":"chemistry_periodic_table_group_2_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q4","subject":"chemistry","chapter":"periodic_table","topic":"Group 2 Elements"}', 3),
  (3188, 769, 'Explain why magnesium belongs to Group 2.', 'text', 1, 'Use its electronic structure, 2,8,2.', '{"why":"Two outer electrons are characteristic of Group 2 main-group elements.","sol":"Step 1: Magnesium has arrangement 2,8,2.\nStep 2: Its outermost shell contains two electrons.\nStep 3: This outer-electron arrangement identifies Group 2.","steps":["Step 1: Magnesium has arrangement 2,8,2.","Step 2: Its outermost shell contains two electrons.","Step 3: This outer-electron arrangement identifies Group 2."],"options":[],"conceptId":"chemistry_periodic_table_group_2_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q5","subject":"chemistry","chapter":"periodic_table","topic":"Group 2 Elements"}', 4),
  (3189, 769, 'Identify the gas produced when calcium reacts with water.', 'text', 1, 'The reaction produces calcium hydroxide and a gas.', '{"why":"Group 2 metals such as calcium can react with water to release hydrogen.","sol":"Step 1: Calcium reacts with water.\nStep 2: Calcium hydroxide is formed.\nStep 3: The other product is hydrogen gas.","steps":["Step 1: Calcium reacts with water.","Step 2: Calcium hydroxide is formed.","Step 3: The other product is hydrogen gas."],"options":[],"conceptId":"chemistry_periodic_table_group_2_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q6","subject":"chemistry","chapter":"periodic_table","topic":"Group 2 Elements"}', 5),
  (3190, 769, 'Determine the period of calcium from its electronic structure 2,8,8,2.', 'text', 1, 'Count the occupied energy levels.', '{"why":"The number of occupied main energy levels identifies the period in this shell model.","sol":"Step 1: The arrangement contains four occupied levels.\nStep 2: The period number is 4.","steps":["Step 1: The arrangement contains four occupied levels.","Step 2: The period number is 4."],"options":[],"conceptId":"chemistry_periodic_table_group_2_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q7","subject":"chemistry","chapter":"periodic_table","topic":"Group 2 Elements"}', 6),
  (3191, 769, 'Balance the equation for magnesium burning in oxygen: Mg + O₂ → MgO.', 'text', 1, 'Oxygen occurs as O₂, so the reactants contain two oxygen atoms.', '{"why":"A balanced equation has the same number of each type of atom on both sides.","sol":"Step 1: Write Mg + O₂ → MgO.\nStep 2: Put 2 before MgO to give two oxygen atoms on the product side.\nStep 3: Put 2 before Mg to balance magnesium atoms.\nStep 4: Check that both sides contain two Mg atoms and two O atoms.","steps":["Step 1: Write Mg + O₂ → MgO.","Step 2: Put 2 before MgO to give two oxygen atoms on the product side.","Step 3: Put 2 before Mg to balance magnesium atoms.","Step 4: Check that both sides contain two Mg atoms and two O atoms."],"options":[],"conceptId":"chemistry_periodic_table_group_2_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q8","subject":"chemistry","chapter":"periodic_table","topic":"Group 2 Elements"}', 7),
  (3192, 770, 'Explain why chlorine forms a chloride ion with charge −1.', 'text', 1, 'Compare the number of protons and electrons before and after gaining one electron.', '{"why":"An additional electron contributes one extra negative charge.","sol":"Step 1: A neutral chlorine atom has 17 protons and 17 electrons.\nStep 2: It gains one electron, giving 18 electrons.\nStep 3: There is now one more electron than protons.\nStep 4: The net charge is −1.","steps":["Step 1: A neutral chlorine atom has 17 protons and 17 electrons.","Step 2: It gains one electron, giving 18 electrons.","Step 3: There is now one more electron than protons.","Step 4: The net charge is −1."],"options":[],"conceptId":"chemistry_periodic_table_group_7_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q1","subject":"chemistry","chapter":"periodic_table","topic":"Group 7 Elements"}', 0),
  (3193, 770, 'Explain why chlorine is more reactive than iodine.', 'text', 1, 'Consider their positions in the group and their ability to gain electrons.', '{"why":"Halogen reactivity generally decreases down the group.","sol":"Step 1: Chlorine and iodine are halogens.\nStep 2: Chlorine is higher in the group.\nStep 3: Iodine has more occupied energy levels and greater shielding.\nStep 4: Chlorine generally attracts an incoming electron more effectively.\nStep 5: Chlorine is more reactive.","steps":["Step 1: Chlorine and iodine are halogens.","Step 2: Chlorine is higher in the group.","Step 3: Iodine has more occupied energy levels and greater shielding.","Step 4: Chlorine generally attracts an incoming electron more effectively.","Step 5: Chlorine is more reactive."],"options":[],"conceptId":"chemistry_periodic_table_group_7_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q2","subject":"chemistry","chapter":"periodic_table","topic":"Group 7 Elements"}', 1),
  (3194, 770, 'Write the balanced equation for chlorine displacing bromine from potassium bromide.', 'text', 1, 'Chlorine forms potassium chloride, while bromine is released.', '{"why":"Chlorine displaces bromine because chlorine is more reactive.","sol":"Step 1: Write Cl₂ + KBr → KCl + Br₂.\nStep 2: Balance potassium and chlorine by placing 2 before KBr and KCl.\nStep 3: Check that bromine is balanced as Br₂.\nStep 4: Verify that each side has two K atoms, two Cl atoms and two Br atoms.","steps":["Step 1: Write Cl₂ + KBr → KCl + Br₂.","Step 2: Balance potassium and chlorine by placing 2 before KBr and KCl.","Step 3: Check that bromine is balanced as Br₂.","Step 4: Verify that each side has two K atoms, two Cl atoms and two Br atoms."],"options":[],"conceptId":"chemistry_periodic_table_group_7_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q3","subject":"chemistry","chapter":"periodic_table","topic":"Group 7 Elements"}', 2),
  (3195, 770, 'Write the electronic structure of a chloride ion if a chlorine atom initially has 17 electrons.', 'text', 1, 'A chloride ion has gained one electron.', '{"why":"The chloride ion has 18 electrons after gaining one electron.","sol":"Step 1: Initial electrons = 17.\nStep 2: Gain one electron: 17 + 1 = 18.\nStep 3: Distribute 18 electrons as 2,8,8.","steps":["Step 1: Initial electrons = 17.","Step 2: Gain one electron: 17 + 1 = 18.","Step 3: Distribute 18 electrons as 2,8,8."],"options":[],"conceptId":"chemistry_periodic_table_group_7_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q4","subject":"chemistry","chapter":"periodic_table","topic":"Group 7 Elements"}', 3),
  (3196, 770, 'Determine the charge of the ion formed when a fluorine atom gains one electron.', 'text', 1, 'One gained electron adds one negative charge.', '{"why":"Halogens commonly form singly charged negative ions.","sol":"Step 1: Fluorine gains one electron.\nStep 2: It now has one more electron than protons.\nStep 3: Its charge is −1.","steps":["Step 1: Fluorine gains one electron.","Step 2: It now has one more electron than protons.","Step 3: Its charge is −1."],"options":[],"conceptId":"chemistry_periodic_table_group_7_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q5","subject":"chemistry","chapter":"periodic_table","topic":"Group 7 Elements"}', 4),
  (3197, 770, 'Identify the physical state of bromine at room temperature.', 'text', 1, 'Recall the physical states of the common halogens.', '{"why":"Bromine is a red-brown liquid at room temperature.","sol":"Step 1: Fluorine and chlorine are gases.\nStep 2: Bromine is the halogen in this sequence that is liquid at room temperature.\nStep 3: Therefore, bromine is a liquid.","steps":["Step 1: Fluorine and chlorine are gases.","Step 2: Bromine is the halogen in this sequence that is liquid at room temperature.","Step 3: Therefore, bromine is a liquid."],"options":[],"conceptId":"chemistry_periodic_table_group_7_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q6","subject":"chemistry","chapter":"periodic_table","topic":"Group 7 Elements"}', 5),
  (3198, 770, 'Predict whether bromine can displace chlorine from a solution containing chloride ions.', 'text', 1, 'A displacement reaction requires the free halogen to be more reactive.', '{"why":"A less reactive halogen cannot displace a more reactive halogen from its halide solution.","sol":"Step 1: Bromine is below chlorine in Group 17.\nStep 2: Halogen reactivity decreases down the group.\nStep 3: Bromine is less reactive than chlorine.\nStep 4: Bromine cannot displace chlorine from chloride ions.","steps":["Step 1: Bromine is below chlorine in Group 17.","Step 2: Halogen reactivity decreases down the group.","Step 3: Bromine is less reactive than chlorine.","Step 4: Bromine cannot displace chlorine from chloride ions."],"options":[],"conceptId":"chemistry_periodic_table_group_7_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q7","subject":"chemistry","chapter":"periodic_table","topic":"Group 7 Elements"}', 6),
  (3199, 770, 'Explain why a chlorine atom gains an electron rather than losing one when forming a simple chloride ion.', 'text', 1, 'Compare seven outer electrons with the arrangement after gaining one.', '{"why":"The full outer-shell arrangement helps explain the common −1 ion formed by halogens.","sol":"Step 1: Chlorine has seven outer electrons.\nStep 2: Gaining one electron gives it eight outer electrons.\nStep 3: Its outer shell becomes full in the shell model.\nStep 4: It forms the stable chloride ion, Cl⁻.","steps":["Step 1: Chlorine has seven outer electrons.","Step 2: Gaining one electron gives it eight outer electrons.","Step 3: Its outer shell becomes full in the shell model.","Step 4: It forms the stable chloride ion, Cl⁻."],"options":[],"conceptId":"chemistry_periodic_table_group_7_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q8","subject":"chemistry","chapter":"periodic_table","topic":"Group 7 Elements"}', 7),
  (3200, 771, 'Explain why helium is chemically unreactive.', 'text', 1, 'The first energy level has a different maximum capacity from the later shells.', '{"why":"A full outer shell helps explain the very low reactivity of helium.","sol":"Step 1: Helium has two electrons.\nStep 2: The first energy level holds a maximum of two electrons.\nStep 3: Helium''s only shell is full.\nStep 4: It therefore has little tendency to gain, lose or share electrons in ordinary reactions.","steps":["Step 1: Helium has two electrons.","Step 2: The first energy level holds a maximum of two electrons.","Step 3: Helium''s only shell is full.","Step 4: It therefore has little tendency to gain, lose or share electrons in ordinary reactions."],"options":[],"conceptId":"chemistry_periodic_table_group_0_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q1","subject":"chemistry","chapter":"periodic_table","topic":"Group 0 Elements"}', 0),
  (3201, 771, 'An atom has electronic structure 2,8,8. Identify the element.', 'text', 1, 'Add the electrons to find the atomic number of a neutral atom.', '{"why":"Argon has 18 electrons in a neutral atom and a full outer shell.","sol":"Step 1: Add the electrons: 2 + 8 + 8 = 18.\nStep 2: A neutral atom with 18 electrons has atomic number 18.\nStep 3: Atomic number 18 identifies argon.","steps":["Step 1: Add the electrons: 2 + 8 + 8 = 18.","Step 2: A neutral atom with 18 electrons has atomic number 18.","Step 3: Atomic number 18 identifies argon."],"options":[],"conceptId":"chemistry_periodic_table_group_0_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q2","subject":"chemistry","chapter":"periodic_table","topic":"Group 0 Elements"}', 1),
  (3202, 771, 'Explain why neon rarely forms chemical compounds.', 'text', 1, 'Look at the outer electrons in 2,8.', '{"why":"Its stable electron arrangement makes ordinary electron transfer or sharing unfavourable.","sol":"Step 1: Neon has electronic structure 2,8.\nStep 2: Its outer shell contains eight electrons.\nStep 3: This shell is full.\nStep 4: Neon has little tendency to gain or lose electrons in ordinary chemical reactions.","steps":["Step 1: Neon has electronic structure 2,8.","Step 2: Its outer shell contains eight electrons.","Step 3: This shell is full.","Step 4: Neon has little tendency to gain or lose electrons in ordinary chemical reactions."],"options":[],"conceptId":"chemistry_periodic_table_group_0_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q3","subject":"chemistry","chapter":"periodic_table","topic":"Group 0 Elements"}', 2),
  (3203, 771, 'Write the electronic structure of neon, which has atomic number 10.', 'text', 1, 'Distribute 10 electrons between the first two shells.', '{"why":"Neon has a full first shell and a full second shell.","sol":"Step 1: Neon has 10 electrons.\nStep 2: Put 2 in the first shell.\nStep 3: The remaining 8 go into the second shell.","steps":["Step 1: Neon has 10 electrons.","Step 2: Put 2 in the first shell.","Step 3: The remaining 8 go into the second shell."],"options":[],"conceptId":"chemistry_periodic_table_group_0_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q4","subject":"chemistry","chapter":"periodic_table","topic":"Group 0 Elements"}', 3),
  (3204, 771, 'Explain why helium is placed among the noble gases even though its outer shell contains only two electrons.', 'text', 1, 'Consider the maximum number of electrons the first shell can hold.', '{"why":"A full shell does not always contain eight electrons; the first shell is complete with two.","sol":"Step 1: Helium''s only occupied shell is the first shell.\nStep 2: The first shell holds a maximum of two electrons.\nStep 3: Helium already has both electrons.\nStep 4: Its shell is full, so helium has the characteristic low reactivity of noble gases.","steps":["Step 1: Helium''s only occupied shell is the first shell.","Step 2: The first shell holds a maximum of two electrons.","Step 3: Helium already has both electrons.","Step 4: Its shell is full, so helium has the characteristic low reactivity of noble gases."],"options":[],"conceptId":"chemistry_periodic_table_group_0_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q5","subject":"chemistry","chapter":"periodic_table","topic":"Group 0 Elements"}', 4),
  (3205, 771, 'State the physical state of argon at room temperature.', 'text', 1, 'Recall the physical state shared by the noble gases under ordinary conditions.', '{"why":"Argon exists as a colourless, monatomic gas at room temperature.","sol":"Step 1: Argon is a noble gas.\nStep 2: Noble gases are gases at room temperature.\nStep 3: Argon is therefore a gas.","steps":["Step 1: Argon is a noble gas.","Step 2: Noble gases are gases at room temperature.","Step 3: Argon is therefore a gas."],"options":[],"conceptId":"chemistry_periodic_table_group_0_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q6","subject":"chemistry","chapter":"periodic_table","topic":"Group 0 Elements"}', 5),
  (3206, 771, 'Explain what the term monatomic means.', 'text', 1, 'Break the word into its meaning: mono means one.', '{"why":"Noble gases exist as individual atoms rather than diatomic molecules under ordinary conditions.","sol":"Step 1: Mono means one.\nStep 2: Atomic refers to atoms.\nStep 3: Monatomic particles consist of individual atoms rather than bonded groups of atoms.","steps":["Step 1: Mono means one.","Step 2: Atomic refers to atoms.","Step 3: Monatomic particles consist of individual atoms rather than bonded groups of atoms."],"options":[],"conceptId":"chemistry_periodic_table_group_0_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q7","subject":"chemistry","chapter":"periodic_table","topic":"Group 0 Elements"}', 6),
  (3207, 771, 'Identify the noble gas with atomic number 2.', 'text', 1, 'Use the first element after hydrogen in the atomic-number sequence.', '{"why":"Helium has atomic number 2 and a full first electron shell.","sol":"Step 1: Atomic number 2 means two protons.\nStep 2: Element 2 is helium.\nStep 3: Its symbol is He.","steps":["Step 1: Atomic number 2 means two protons.","Step 2: Element 2 is helium.","Step 3: Its symbol is He."],"options":[],"conceptId":"chemistry_periodic_table_group_0_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q8","subject":"chemistry","chapter":"periodic_table","topic":"Group 0 Elements"}', 7),
  (3208, 772, 'Define metallic bonding and identify the two types of particles involved.', 'text', 1, 'Your definition should include the force, the positive particles and the electrons.', '{"why":"The definition identifies the particles, their opposite charges and the force that holds the metallic structure together.","sol":"Step 1: Metallic bonding is a type of electrostatic attraction.\nStep 2: The positive particles are metal ions.\nStep 3: The negative particles are delocalised electrons.\nStep 4: Combine these ideas into one precise definition.","steps":["Step 1: Metallic bonding is a type of electrostatic attraction.","Step 2: The positive particles are metal ions.","Step 3: The negative particles are delocalised electrons.","Step 4: Combine these ideas into one precise definition."],"options":[],"conceptId":"chemistry_chemical_bonding_metallic_bonding","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Metallic Bonding"}', 0),
  (3209, 772, 'A sodium atom has the electron arrangement 2,8,1. Explain how it contributes to metallic bonding.', 'text', 1, 'Focus on the outer electron and the charge left on the sodium particle.', '{"why":"The outer electron becomes part of the shared electron system, leaving a positive ion in the metallic lattice.","sol":"Step 1: Sodium has one electron in its outermost energy level.\nStep 2: This electron can become delocalised in the metallic structure.\nStep 3: Losing the electron leaves the sodium particle with a net charge of +1.\nStep 4: The resulting Na⁺ ion is attracted to the delocalised electrons.","steps":["Step 1: Sodium has one electron in its outermost energy level.","Step 2: This electron can become delocalised in the metallic structure.","Step 3: Losing the electron leaves the sodium particle with a net charge of +1.","Step 4: The resulting Na⁺ ion is attracted to the delocalised electrons."],"options":[],"conceptId":"chemistry_chemical_bonding_metallic_bonding","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Metallic Bonding"}', 1),
  (3210, 772, 'Explain why the metallic structure contains positive ions rather than only neutral metal atoms.', 'text', 1, 'What happens to the charge of an atom when it loses a negatively charged electron?', '{"why":"Removing negatively charged electrons leaves the remaining particle with more positive charge than negative charge.","sol":"Step 1: An electron carries a negative charge.\nStep 2: When a metal atom loses an electron, it loses negative charge.\nStep 3: The remaining particle has an overall positive charge.\nStep 4: This particle is a positive metal ion.","steps":["Step 1: An electron carries a negative charge.","Step 2: When a metal atom loses an electron, it loses negative charge.","Step 3: The remaining particle has an overall positive charge.","Step 4: This particle is a positive metal ion."],"options":[],"conceptId":"chemistry_chemical_bonding_metallic_bonding","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Metallic Bonding"}', 2),
  (3211, 772, 'A learner says that each positive metal ion is bonded to just one delocalised electron. Explain why this model is incorrect.', 'text', 1, 'Think about whether the delocalised electrons belong to individual ions.', '{"why":"The collective nature of the attraction distinguishes metallic bonding from a model involving individual ion–electron pairs.","sol":"Step 1: Delocalised electrons are not restricted to one particular metal ion.\nStep 2: They can move throughout the metallic structure.\nStep 3: Each ion is attracted to the surrounding delocalised electron system.\nStep 4: Metallic bonding is therefore a collective attraction throughout the structure.","steps":["Step 1: Delocalised electrons are not restricted to one particular metal ion.","Step 2: They can move throughout the metallic structure.","Step 3: Each ion is attracted to the surrounding delocalised electron system.","Step 4: Metallic bonding is therefore a collective attraction throughout the structure."],"options":[],"conceptId":"chemistry_chemical_bonding_metallic_bonding","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Metallic Bonding"}', 3),
  (3212, 772, 'A solid metal contains positive ions and delocalised electrons. Explain what holds its structure together.', 'text', 1, 'Use the charges of the particles to identify the force.', '{"why":"The metallic lattice is stabilised by attraction between its positively charged ions and its negatively charged delocalised electrons.","sol":"Step 1: The metal ions have positive charges.\nStep 2: The delocalised electrons have negative charges.\nStep 3: Opposite electrical charges attract.\nStep 4: This strong electrostatic attraction holds the metallic structure together.","steps":["Step 1: The metal ions have positive charges.","Step 2: The delocalised electrons have negative charges.","Step 3: Opposite electrical charges attract.","Step 4: This strong electrostatic attraction holds the metallic structure together."],"options":[],"conceptId":"chemistry_chemical_bonding_metallic_bonding","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q5","subject":"chemistry","chapter":"chemical_bonding","topic":"Metallic Bonding"}', 4),
  (3213, 773, 'Define a delocalised electron in the context of a metal.', 'text', 1, 'Explain whether it is restricted to one atom.', '{"why":"The ability to move throughout the structure is central to the role of delocalised electrons in metals.","sol":"Step 1: Consider where an ordinary atom''s electrons are associated.\nStep 2: A delocalised electron is not confined to one particular metal atom.\nStep 3: It can move throughout the metallic structure.","steps":["Step 1: Consider where an ordinary atom''s electrons are associated.","Step 2: A delocalised electron is not confined to one particular metal atom.","Step 3: It can move throughout the metallic structure."],"options":[],"conceptId":"chemistry_chemical_bonding_delocalised_electrons_in_metals","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Delocalised Electrons in Metals"}', 0),
  (3214, 773, 'A metal wire is connected to a cell and a lamp lights. Explain the role of delocalised electrons.', 'text', 1, 'Relate mobile electrons to the meaning of electric current.', '{"why":"The mobile electrons act as charge carriers in the metallic conductor.","sol":"Step 1: Electric current is the movement of electric charge.\nStep 2: Delocalised electrons carry negative charge.\nStep 3: The cell establishes a potential difference across the wire.\nStep 4: The electric field causes a net drift of the mobile electrons.\nStep 5: This movement carries current through the wire.","steps":["Step 1: Electric current is the movement of electric charge.","Step 2: Delocalised electrons carry negative charge.","Step 3: The cell establishes a potential difference across the wire.","Step 4: The electric field causes a net drift of the mobile electrons.","Step 5: This movement carries current through the wire."],"options":[],"conceptId":"chemistry_chemical_bonding_delocalised_electrons_in_metals","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Delocalised Electrons in Metals"}', 1),
  (3215, 773, 'Describe the movement of positive metal ions in a solid metal when it conducts electricity.', 'text', 1, 'Distinguish vibrating about fixed positions from flowing through the structure.', '{"why":"Electrical conduction in a solid metal depends on mobile electrons, not on the bulk movement of its positive ions.","sol":"Step 1: Positive metal ions occupy positions in the solid lattice.\nStep 2: They vibrate about their average positions.\nStep 3: They do not normally flow freely through the solid.\nStep 4: Delocalised electrons provide the mobile charge carriers.","steps":["Step 1: Positive metal ions occupy positions in the solid lattice.","Step 2: They vibrate about their average positions.","Step 3: They do not normally flow freely through the solid.","Step 4: Delocalised electrons provide the mobile charge carriers."],"options":[],"conceptId":"chemistry_chemical_bonding_delocalised_electrons_in_metals","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Delocalised Electrons in Metals"}', 2),
  (3216, 773, 'Explain one way delocalised electrons contribute to the thermal conductivity of a metal.', 'text', 1, 'Think about how energy can be transferred from a hotter region to a cooler region.', '{"why":"Mobile electrons contribute significantly to the thermal conductivity of metals, although lattice vibrations also transfer energy.","sol":"Step 1: Thermal energy is transferred from hotter regions to cooler regions.\nStep 2: Delocalised electrons are mobile throughout the metal.\nStep 3: They can carry energy and transfer it through interactions with other electrons and the lattice.\nStep 4: This contributes to efficient heat transfer.","steps":["Step 1: Thermal energy is transferred from hotter regions to cooler regions.","Step 2: Delocalised electrons are mobile throughout the metal.","Step 3: They can carry energy and transfer it through interactions with other electrons and the lattice.","Step 4: This contributes to efficient heat transfer."],"options":[],"conceptId":"chemistry_chemical_bonding_delocalised_electrons_in_metals","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Delocalised Electrons in Metals"}', 3),
  (3217, 773, 'A student claims that delocalised electrons are completely detached from the metal and no longer attracted to its ions. Explain the error.', 'text', 1, 'Distinguish freedom to move from absence of electrostatic attraction.', '{"why":"Electron mobility and electrostatic attraction coexist in metallic bonding.","sol":"Step 1: Delocalised means the electrons are not confined to individual atoms.\nStep 2: It does not mean that the electrons have left the metal.\nStep 3: The electrons remain within the metallic structure.\nStep 4: They remain electrostatically attracted to the positive ions.","steps":["Step 1: Delocalised means the electrons are not confined to individual atoms.","Step 2: It does not mean that the electrons have left the metal.","Step 3: The electrons remain within the metallic structure.","Step 4: They remain electrostatically attracted to the positive ions."],"options":[],"conceptId":"chemistry_chemical_bonding_delocalised_electrons_in_metals","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q5","subject":"chemistry","chapter":"chemical_bonding","topic":"Delocalised Electrons in Metals"}', 4),
  (3218, 774, 'Explain why metals conduct electricity, using the terms delocalised electrons and electric charge.', 'text', 1, 'Describe what happens when a potential difference is applied.', '{"why":"Electrical conductivity depends on the availability of mobile charge carriers.","sol":"Step 1: Metals contain delocalised electrons.\nStep 2: These electrons carry negative electric charge.\nStep 3: A potential difference produces an electric field in the metal.\nStep 4: The electrons acquire a net drift through the structure.\nStep 5: The movement of charge forms an electric current.","steps":["Step 1: Metals contain delocalised electrons.","Step 2: These electrons carry negative electric charge.","Step 3: A potential difference produces an electric field in the metal.","Step 4: The electrons acquire a net drift through the structure.","Step 5: The movement of charge forms an electric current."],"options":[],"conceptId":"chemistry_chemical_bonding_metallic_bonding_and_metal_properties","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Metallic Bonding and Metal Properties"}', 0),
  (3219, 774, 'Define malleability and explain why metallic bonding allows many metals to be hammered into sheets.', 'text', 1, 'Include both the meaning of malleability and the movement of the layers.', '{"why":"The metallic structure can deform without requiring the layers to separate completely.","sol":"Step 1: Malleability is the ability to be hammered or pressed into sheets without breaking.\nStep 2: A force can cause layers of metal ions to shift relative to one another.\nStep 3: Delocalised electrons continue to attract the positive ions.\nStep 4: The metallic structure can change shape while the bonding remains effective.","steps":["Step 1: Malleability is the ability to be hammered or pressed into sheets without breaking.","Step 2: A force can cause layers of metal ions to shift relative to one another.","Step 3: Delocalised electrons continue to attract the positive ions.","Step 4: The metallic structure can change shape while the bonding remains effective."],"options":[],"conceptId":"chemistry_chemical_bonding_metallic_bonding_and_metal_properties","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Metallic Bonding and Metal Properties"}', 1),
  (3220, 774, 'Distinguish between malleability and ductility.', 'text', 1, 'Think about the final shape produced in each case.', '{"why":"The terms describe different forms of permanent deformation.","sol":"Step 1: Malleability describes deformation into sheets by hammering or pressing.\nStep 2: Ductility describes the ability to be drawn into wires.\nStep 3: Both properties involve the ability of a metal to deform without immediately breaking.","steps":["Step 1: Malleability describes deformation into sheets by hammering or pressing.","Step 2: Ductility describes the ability to be drawn into wires.","Step 3: Both properties involve the ability of a metal to deform without immediately breaking."],"options":[],"conceptId":"chemistry_chemical_bonding_metallic_bonding_and_metal_properties","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Metallic Bonding and Metal Properties"}', 2),
  (3221, 774, 'Explain why many metals have high melting points, and state why the claim does not apply equally to every metal.', 'text', 1, 'Connect melting to the metallic structure and compare the strength of bonding in different metals.', '{"why":"The strength of the metallic attraction helps explain melting behaviour, but it does not make all metals have the same or uniformly high melting point.","sol":"Step 1: Metallic bonding involves electrostatic attraction between positive ions and delocalised electrons.\nStep 2: Energy must be supplied to disrupt the metallic structure during melting.\nStep 3: Strong metallic attraction generally requires more energy to overcome.\nStep 4: Different metals have different structures and metallic bond strengths.\nStep 5: Therefore, melting points vary between metals.","steps":["Step 1: Metallic bonding involves electrostatic attraction between positive ions and delocalised electrons.","Step 2: Energy must be supplied to disrupt the metallic structure during melting.","Step 3: Strong metallic attraction generally requires more energy to overcome.","Step 4: Different metals have different structures and metallic bond strengths.","Step 5: Therefore, melting points vary between metals."],"options":[],"conceptId":"chemistry_chemical_bonding_metallic_bonding_and_metal_properties","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Metallic Bonding and Metal Properties"}', 3),
  (3222, 774, 'A student says, “Copper conducts electricity because its positive ions flow from one end of the wire to the other.” Correct the explanation.', 'text', 1, 'Identify which particles are mobile in a solid metallic lattice.', '{"why":"The mobile electrons, not the bulk movement of positive ions, provide electrical conduction in a solid copper wire.","sol":"Step 1: The positive copper ions occupy lattice positions in the solid.\nStep 2: They vibrate about their average positions rather than flowing freely through the wire.\nStep 3: Copper contains mobile delocalised electrons.\nStep 4: These electrons drift through the metal when a potential difference is applied.\nStep 5: Their movement carries electric charge.","steps":["Step 1: The positive copper ions occupy lattice positions in the solid.","Step 2: They vibrate about their average positions rather than flowing freely through the wire.","Step 3: Copper contains mobile delocalised electrons.","Step 4: These electrons drift through the metal when a potential difference is applied.","Step 5: Their movement carries electric charge."],"options":[],"conceptId":"chemistry_chemical_bonding_metallic_bonding_and_metal_properties","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q5","subject":"chemistry","chapter":"chemical_bonding","topic":"Metallic Bonding and Metal Properties"}', 4),
  (3223, 775, 'Sodium has the electron arrangement 2,8,1. Explain why losing one electron can make its arrangement more stable.', 'text', 1, 'Compare the electron arrangement before and after losing the outer electron.', '{"why":"Losing one electron gives sodium a filled outer shell in the simple shell model. Sodium becomes Na⁺ because it then has one more proton than electrons.","sol":"Step 1: Sodium''s original electron arrangement is 2,8,1.\nStep 2: The outermost shell contains one electron.\nStep 3: When sodium loses that electron, the next shell becomes the outermost occupied shell.\nStep 4: The resulting arrangement is 2,8, with a filled outer shell in this introductory model.","steps":["Step 1: Sodium''s original electron arrangement is 2,8,1.","Step 2: The outermost shell contains one electron.","Step 3: When sodium loses that electron, the next shell becomes the outermost occupied shell.","Step 4: The resulting arrangement is 2,8, with a filled outer shell in this introductory model."],"options":[],"conceptId":"chemistry_chemical_bonding_why_atoms_bond","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Why Atoms Bond"}', 0),
  (3224, 775, 'Chlorine has the electron arrangement 2,8,7. How many electrons can it gain to obtain a filled outer shell?', 'text', 1, 'Count how many electrons are needed to increase the outer-shell count from seven to eight.', '{"why":"Gaining one electron gives chlorine the arrangement 2,8,8 and produces a chloride ion, Cl⁻.","sol":"Step 1: Chlorine has seven electrons in its outer shell.\nStep 2: A filled outer shell in this example contains eight electrons.\nStep 3: Calculate 8 − 7 = 1.","steps":["Step 1: Chlorine has seven electrons in its outer shell.","Step 2: A filled outer shell in this example contains eight electrons.","Step 3: Calculate 8 − 7 = 1."],"options":[],"conceptId":"chemistry_chemical_bonding_why_atoms_bond","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Why Atoms Bond"}', 1),
  (3225, 775, 'Explain why sodium and chlorine can form an ionic compound.', 'text', 1, 'Identify the electron donor, the electron acceptor, and the resulting charges.', '{"why":"Ionic bonding is the electrostatic attraction between oppositely charged ions.","sol":"Step 1: Sodium has one outer electron that it can lose.\nStep 2: Chlorine needs one electron to complete its outer shell in the shell model.\nStep 3: Sodium transfers one electron to chlorine.\nStep 4: Sodium becomes Na⁺ and chlorine becomes Cl⁻.\nStep 5: Oppositely charged ions attract.","steps":["Step 1: Sodium has one outer electron that it can lose.","Step 2: Chlorine needs one electron to complete its outer shell in the shell model.","Step 3: Sodium transfers one electron to chlorine.","Step 4: Sodium becomes Na⁺ and chlorine becomes Cl⁻.","Step 5: Oppositely charged ions attract."],"options":[],"conceptId":"chemistry_chemical_bonding_why_atoms_bond","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Why Atoms Bond"}', 2),
  (3226, 775, 'State two types of chemical bonding and describe what holds the particles together in each type.', 'text', 1, 'Choose two from ionic, covalent, and metallic bonding.', '{"why":"Different types of bonding arise from different interactions between electrons, nuclei, atoms, or ions.","sol":"Step 1: For ionic bonding, identify the charges on the ions.\nStep 2: For covalent bonding, identify the shared electron pair and the bonded atoms.\nStep 3: For metallic bonding, identify the positive metal ions and delocalised electrons.","steps":["Step 1: For ionic bonding, identify the charges on the ions.","Step 2: For covalent bonding, identify the shared electron pair and the bonded atoms.","Step 3: For metallic bonding, identify the positive metal ions and delocalised electrons."],"options":[],"conceptId":"chemistry_chemical_bonding_why_atoms_bond","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Why Atoms Bond"}', 3),
  (3227, 775, 'A learner says, ''Atoms bond only because they must have exactly eight outer-shell electrons.'' Explain why this statement is too broad.', 'text', 1, 'Consider the octet model and the idea of energy and stability.', '{"why":"Using the octet rule as an absolute law leads to incorrect explanations for substances that do not follow it.","sol":"Step 1: The octet model explains many common main-group compounds.\nStep 2: Some stable particles do not have exactly eight outer-shell electrons.\nStep 3: Bond formation depends on whether the interactions produce a favourable, lower-energy arrangement.\nStep 4: Therefore, the octet rule is useful but is not universal.","steps":["Step 1: The octet model explains many common main-group compounds.","Step 2: Some stable particles do not have exactly eight outer-shell electrons.","Step 3: Bond formation depends on whether the interactions produce a favourable, lower-energy arrangement.","Step 4: Therefore, the octet rule is useful but is not universal."],"options":[],"conceptId":"chemistry_chemical_bonding_why_atoms_bond","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q5","subject":"chemistry","chapter":"chemical_bonding","topic":"Why Atoms Bond"}', 4),
  (3228, 776, 'Magnesium has the electron arrangement 2,8,2. Determine its common valency in simple ionic compounds.', 'text', 1, 'Count the outer-shell electrons and consider how many magnesium commonly loses.', '{"why":"Magnesium commonly forms a 2+ ion by losing two outer-shell electrons.","sol":"Step 1: Magnesium has two outer-shell electrons.\nStep 2: It commonly loses both electrons.\nStep 3: It forms Mg²⁺, so its combining capacity in this example is 2.","steps":["Step 1: Magnesium has two outer-shell electrons.","Step 2: It commonly loses both electrons.","Step 3: It forms Mg²⁺, so its combining capacity in this example is 2."],"options":[],"conceptId":"chemistry_chemical_bonding_valency","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Valency"}', 0),
  (3229, 776, 'An oxygen atom has six outer-shell electrons. Using the simple shell model, predict its common valency in water.', 'text', 1, 'Work out how many electrons oxygen needs to complete an outer shell.', '{"why":"Oxygen forms two covalent bonds in water, H₂O.","sol":"Step 1: Oxygen has six outer-shell electrons.\nStep 2: It needs two more to reach eight in the simple model.\nStep 3: In water, it forms two covalent bonds, one with each hydrogen atom.","steps":["Step 1: Oxygen has six outer-shell electrons.","Step 2: It needs two more to reach eight in the simple model.","Step 3: In water, it forms two covalent bonds, one with each hydrogen atom."],"options":[],"conceptId":"chemistry_chemical_bonding_valency","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Valency"}', 1),
  (3230, 776, 'Use the ions Mg²⁺ and Cl⁻ to determine the formula of magnesium chloride.', 'text', 1, 'The total positive and negative charges must cancel.', '{"why":"Two chloride ions are needed to balance the charge of one magnesium ion.","sol":"Step 1: One Mg²⁺ ion contributes a charge of +2.\nStep 2: One Cl⁻ ion contributes a charge of −1.\nStep 3: Two chloride ions contribute −2.\nStep 4: The total charge is +2 − 2 = 0.","steps":["Step 1: One Mg²⁺ ion contributes a charge of +2.","Step 2: One Cl⁻ ion contributes a charge of −1.","Step 3: Two chloride ions contribute −2.","Step 4: The total charge is +2 − 2 = 0."],"options":[],"conceptId":"chemistry_chemical_bonding_valency","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Valency"}', 2),
  (3231, 776, 'Aluminium commonly forms Al³⁺ ions. What is its common valency in this ionic example, and how many electrons does a neutral aluminium atom lose to form Al³⁺?', 'text', 1, 'Use the magnitude of the charge and remember that a positive ion forms by losing electrons.', '{"why":"Losing three negatively charged electrons leaves the aluminium ion with three more protons than electrons.","sol":"Step 1: The aluminium ion has a charge of +3.\nStep 2: The magnitude of this charge is 3.\nStep 3: A neutral aluminium atom must lose three electrons to form Al³⁺.","steps":["Step 1: The aluminium ion has a charge of +3.","Step 2: The magnitude of this charge is 3.","Step 3: A neutral aluminium atom must lose three electrons to form Al³⁺."],"options":[],"conceptId":"chemistry_chemical_bonding_valency","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Valency"}', 3),
  (3232, 776, 'Explain why the formula for aluminium oxide is Al₂O₃ when the ions are Al³⁺ and O²⁻.', 'text', 1, 'Find the smallest numbers of each ion that give equal total positive and negative charges.', '{"why":"Two aluminium ions and three oxide ions give a total charge of zero.","sol":"Step 1: Each Al³⁺ ion has charge +3.\nStep 2: Each O²⁻ ion has charge −2.\nStep 3: Two aluminium ions give 2 × (+3) = +6.\nStep 4: Three oxide ions give 3 × (−2) = −6.\nStep 5: The charges cancel, giving a neutral compound.","steps":["Step 1: Each Al³⁺ ion has charge +3.","Step 2: Each O²⁻ ion has charge −2.","Step 3: Two aluminium ions give 2 × (+3) = +6.","Step 4: Three oxide ions give 3 × (−2) = −6.","Step 5: The charges cancel, giving a neutral compound."],"options":[],"conceptId":"chemistry_chemical_bonding_valency","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q5","subject":"chemistry","chapter":"chemical_bonding","topic":"Valency"}', 4),
  (3233, 777, 'Define ionic bonding.', 'text', 1, 'State what is attracting what, and include the charges.', '{"why":"The attraction between opposite charges holds the ions together.","sol":"Step 1: Identify the particles: ions.\nStep 2: Identify the charges: one type is positive and the other negative.\nStep 3: State the force: electrostatic attraction.","steps":["Step 1: Identify the particles: ions.","Step 2: Identify the charges: one type is positive and the other negative.","Step 3: State the force: electrostatic attraction."],"options":[],"conceptId":"chemistry_chemical_bonding_ionic_bonding","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Ionic Bonding"}', 0),
  (3234, 777, 'Sodium transfers one electron to chlorine. Write the ions formed and explain why they attract.', 'text', 1, 'Determine the charge on each atom after electron transfer.', '{"why":"This electrostatic attraction is the ionic bond in sodium chloride.","sol":"Step 1: Sodium loses one electron and forms Na⁺.\nStep 2: Chlorine gains one electron and forms Cl⁻.\nStep 3: Na⁺ has a positive charge and Cl⁻ has a negative charge.\nStep 4: Opposite charges attract.","steps":["Step 1: Sodium loses one electron and forms Na⁺.","Step 2: Chlorine gains one electron and forms Cl⁻.","Step 3: Na⁺ has a positive charge and Cl⁻ has a negative charge.","Step 4: Opposite charges attract."],"options":[],"conceptId":"chemistry_chemical_bonding_ionic_bonding","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Ionic Bonding"}', 1),
  (3235, 777, 'Calcium forms Ca²⁺ and chlorine forms Cl⁻. Calculate the number of chloride ions needed for one calcium ion.', 'text', 1, 'Each chloride ion contributes −1, while calcium contributes +2.', '{"why":"The formula must represent an electrically neutral compound.","sol":"Step 1: One calcium ion has charge +2.\nStep 2: One chloride ion has charge −1.\nStep 3: Two chloride ions give 2 × (−1) = −2.\nStep 4: The total charge is +2 − 2 = 0.","steps":["Step 1: One calcium ion has charge +2.","Step 2: One chloride ion has charge −1.","Step 3: Two chloride ions give 2 × (−1) = −2.","Step 4: The total charge is +2 − 2 = 0."],"options":[],"conceptId":"chemistry_chemical_bonding_ionic_bonding","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Ionic Bonding"}', 2),
  (3236, 777, 'Magnesium forms Mg²⁺ and oxygen forms O²⁻. Determine the simplest formula and show the charge calculation.', 'text', 1, 'Check whether one ion of each type balances the charges.', '{"why":"Equal and opposite charges cancel with one magnesium ion and one oxide ion.","sol":"Step 1: Mg²⁺ contributes +2.\nStep 2: O²⁻ contributes −2.\nStep 3: Add the charges: +2 + (−2) = 0.\nStep 4: The ions combine in a 1:1 ratio.","steps":["Step 1: Mg²⁺ contributes +2.","Step 2: O²⁻ contributes −2.","Step 3: Add the charges: +2 + (−2) = 0.","Step 4: The ions combine in a 1:1 ratio."],"options":[],"conceptId":"chemistry_chemical_bonding_ionic_bonding","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Ionic Bonding"}', 3),
  (3237, 777, 'Explain why solid sodium chloride is described as a giant ionic lattice rather than a collection of separate NaCl molecules.', 'text', 1, 'Think about the arrangement of ions throughout the solid.', '{"why":"The formula NaCl gives the simplest ratio of ions in the lattice, not the identity of an isolated molecule.","sol":"Step 1: Sodium chloride contains Na⁺ and Cl⁻ ions.\nStep 2: The ions form a repeating three-dimensional arrangement.\nStep 3: Each ion is attracted to surrounding ions of the opposite charge.\nStep 4: The electrostatic attraction extends throughout the structure.","steps":["Step 1: Sodium chloride contains Na⁺ and Cl⁻ ions.","Step 2: The ions form a repeating three-dimensional arrangement.","Step 3: Each ion is attracted to surrounding ions of the opposite charge.","Step 4: The electrostatic attraction extends throughout the structure."],"options":[],"conceptId":"chemistry_chemical_bonding_ionic_bonding","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q5","subject":"chemistry","chapter":"chemical_bonding","topic":"Ionic Bonding"}', 4),
  (3238, 778, 'Write the equation for a sodium atom losing one electron to form Na⁺.', 'text', 1, 'An electron lost by the atom appears as a product.', '{"why":"The equation shows that sodium loses one electron and becomes positively charged.","sol":"Step 1: Write the neutral sodium atom: Na.\nStep 2: Write the sodium ion formed: Na⁺.\nStep 3: Add the released electron e⁻ to the products.\nStep 4: Check charge: +1 − 1 = 0.","steps":["Step 1: Write the neutral sodium atom: Na.","Step 2: Write the sodium ion formed: Na⁺.","Step 3: Add the released electron e⁻ to the products.","Step 4: Check charge: +1 − 1 = 0."],"options":[],"conceptId":"chemistry_chemical_bonding_electron_transfer","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Electron Transfer"}', 0),
  (3239, 778, 'Write the equation for an oxygen atom gaining two electrons to form O²⁻.', 'text', 1, 'Electrons gained must appear on the reactant side.', '{"why":"Gaining two electrons gives oxygen two more electrons than protons and produces a 2− ion.","sol":"Step 1: Write the oxygen atom as O.\nStep 2: Place two electrons on the left: 2e⁻.\nStep 3: Write the oxide ion on the right: O²⁻.\nStep 4: Check that the charge is −2 on both sides.","steps":["Step 1: Write the oxygen atom as O.","Step 2: Place two electrons on the left: 2e⁻.","Step 3: Write the oxide ion on the right: O²⁻.","Step 4: Check that the charge is −2 on both sides."],"options":[],"conceptId":"chemistry_chemical_bonding_electron_transfer","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Electron Transfer"}', 1),
  (3240, 778, 'Magnesium loses two electrons. Write its electron-loss equation and state the ion formed.', 'text', 1, 'Show both electrons on the product side.', '{"why":"Losing two negatively charged electrons leaves magnesium with a net charge of +2.","sol":"Step 1: Start with a neutral magnesium atom, Mg.\nStep 2: Show the loss of two electrons.\nStep 3: Write the resulting ion with charge +2.","steps":["Step 1: Start with a neutral magnesium atom, Mg.","Step 2: Show the loss of two electrons.","Step 3: Write the resulting ion with charge +2."],"options":[],"conceptId":"chemistry_chemical_bonding_electron_transfer","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Electron Transfer"}', 2),
  (3241, 778, 'One magnesium atom loses two electrons. Each chlorine atom gains one electron. How many chlorine atoms are required to accept both electrons?', 'text', 1, 'Divide the two electrons released by the one electron accepted per chlorine atom.', '{"why":"The transfer produces one Mg²⁺ ion and two Cl⁻ ions, corresponding to MgCl₂.","sol":"Step 1: Magnesium releases two electrons.\nStep 2: Each chlorine atom accepts one electron.\nStep 3: Two electrons ÷ one electron per chlorine atom = two chlorine atoms.","steps":["Step 1: Magnesium releases two electrons.","Step 2: Each chlorine atom accepts one electron.","Step 3: Two electrons ÷ one electron per chlorine atom = two chlorine atoms."],"options":[],"conceptId":"chemistry_chemical_bonding_electron_transfer","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Electron Transfer"}', 3),
  (3242, 778, 'A neutral atom has 12 protons and 12 electrons. It loses two electrons. Determine its new charge and explain why its proton number stays unchanged.', 'text', 1, 'Count the electrons remaining and compare them with the 12 protons.', '{"why":"An ion forms by gaining or losing electrons. Its element identity remains the same because the number of protons is unchanged.","sol":"Step 1: The atom begins with 12 protons and 12 electrons.\nStep 2: After losing two electrons, it has 10 electrons.\nStep 3: The net charge is 12 positive charges plus 10 negative charges, giving +2.\nStep 4: Ordinary electron transfer changes the electron count, not the number of protons in the nucleus.","steps":["Step 1: The atom begins with 12 protons and 12 electrons.","Step 2: After losing two electrons, it has 10 electrons.","Step 3: The net charge is 12 positive charges plus 10 negative charges, giving +2.","Step 4: Ordinary electron transfer changes the electron count, not the number of protons in the nucleus."],"options":[],"conceptId":"chemistry_chemical_bonding_electron_transfer","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q5","subject":"chemistry","chapter":"chemical_bonding","topic":"Electron Transfer"}', 4),
  (3243, 779, 'An ion has 11 protons and 10 electrons. Calculate its charge and write the charge notation.', 'text', 1, 'Subtract the number of electrons from the number of protons.', '{"why":"One more proton than electron gives a net positive charge of +1.","sol":"Step 1: Number of protons = 11.\nStep 2: Number of electrons = 10.\nStep 3: Charge = 11 − 10 = +1.","steps":["Step 1: Number of protons = 11.","Step 2: Number of electrons = 10.","Step 3: Charge = 11 − 10 = +1."],"options":[],"conceptId":"chemistry_chemical_bonding_formation_of_positive_ions","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Formation of Positive Ions"}', 0),
  (3244, 779, 'Magnesium has atomic number 12. Determine the number of electrons in Mg²⁺.', 'text', 1, 'A neutral atom has electrons equal to its atomic number. A 2+ ion has lost two electrons.', '{"why":"The +2 charge indicates that magnesium has two fewer electrons than protons.","sol":"Step 1: A neutral magnesium atom has 12 electrons.\nStep 2: Mg²⁺ has lost two electrons.\nStep 3: Electrons remaining = 12 − 2 = 10.","steps":["Step 1: A neutral magnesium atom has 12 electrons.","Step 2: Mg²⁺ has lost two electrons.","Step 3: Electrons remaining = 12 − 2 = 10."],"options":[],"conceptId":"chemistry_chemical_bonding_formation_of_positive_ions","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Formation of Positive Ions"}', 1),
  (3245, 779, 'Write the equation for the formation of Al³⁺ from a neutral aluminium atom.', 'text', 1, 'The atom loses three electrons, which appear on the product side.', '{"why":"The equation conserves both the aluminium atom and total charge.","sol":"Step 1: Start with Al.\nStep 2: Write the aluminium ion Al³⁺.\nStep 3: Add three released electrons, 3e⁻.\nStep 4: Check that +3 − 3 = 0.","steps":["Step 1: Start with Al.","Step 2: Write the aluminium ion Al³⁺.","Step 3: Add three released electrons, 3e⁻.","Step 4: Check that +3 − 3 = 0."],"options":[],"conceptId":"chemistry_chemical_bonding_formation_of_positive_ions","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Formation of Positive Ions"}', 2),
  (3246, 779, 'A neutral atom contains 13 protons and 13 electrons. It loses three electrons. State the number of protons, the number of electrons, and the resulting charge.', 'text', 1, 'Only the electron count changes during ordinary ion formation.', '{"why":"Losing three electrons leaves three more protons than electrons, producing a 3+ ion.","sol":"Step 1: The number of protons remains 13.\nStep 2: Electrons remaining = 13 − 3 = 10.\nStep 3: Net charge = 13 − 10 = +3.","steps":["Step 1: The number of protons remains 13.","Step 2: Electrons remaining = 13 − 3 = 10.","Step 3: Net charge = 13 − 10 = +3."],"options":[],"conceptId":"chemistry_chemical_bonding_formation_of_positive_ions","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Formation of Positive Ions"}', 3),
  (3247, 779, 'A learner says that sodium becomes a different element when it forms Na⁺ because it loses an electron. Explain the error.', 'text', 1, 'Recall what determines an element''s identity.', '{"why":"Ion formation changes electrical charge; changing the proton number would change the element.","sol":"Step 1: An element''s identity is determined by its number of protons.\nStep 2: Sodium has 11 protons before ion formation.\nStep 3: Losing an electron changes the electron count, not the proton count.\nStep 4: The particle still has 11 protons and is therefore still sodium.","steps":["Step 1: An element''s identity is determined by its number of protons.","Step 2: Sodium has 11 protons before ion formation.","Step 3: Losing an electron changes the electron count, not the proton count.","Step 4: The particle still has 11 protons and is therefore still sodium."],"options":[],"conceptId":"chemistry_chemical_bonding_formation_of_positive_ions","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q5","subject":"chemistry","chapter":"chemical_bonding","topic":"Formation of Positive Ions"}', 4),
  (3248, 780, 'A particle contains 17 protons and 18 electrons. Calculate its charge and identify the ion if the particle is chlorine.', 'text', 1, 'Subtract the number of electrons from the number of protons.', '{"why":"One extra electron gives the chlorine ion a net charge of −1.","sol":"Step 1: Protons = 17.\nStep 2: Electrons = 18.\nStep 3: Charge = 17 − 18 = −1.\nStep 4: A chlorine ion with charge −1 is written Cl⁻.","steps":["Step 1: Protons = 17.","Step 2: Electrons = 18.","Step 3: Charge = 17 − 18 = −1.","Step 4: A chlorine ion with charge −1 is written Cl⁻."],"options":[],"conceptId":"chemistry_chemical_bonding_formation_of_negative_ions","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Formation of Negative Ions"}', 0),
  (3249, 780, 'Oxygen has atomic number 8. Calculate the number of electrons in O²⁻.', 'text', 1, 'Start with the electron count of a neutral oxygen atom, then account for the 2− charge.', '{"why":"A 2− charge means there are two more electrons than protons.","sol":"Step 1: A neutral oxygen atom has 8 electrons.\nStep 2: O²⁻ has gained two electrons.\nStep 3: Total electrons = 8 + 2 = 10.","steps":["Step 1: A neutral oxygen atom has 8 electrons.","Step 2: O²⁻ has gained two electrons.","Step 3: Total electrons = 8 + 2 = 10."],"options":[],"conceptId":"chemistry_chemical_bonding_formation_of_negative_ions","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Formation of Negative Ions"}', 1),
  (3250, 780, 'Write the equation for the formation of a chloride ion from a chlorine atom.', 'text', 1, 'The gained electron belongs on the reactant side.', '{"why":"Chlorine gains one electron and becomes negatively charged.","sol":"Step 1: Write the chlorine atom as Cl.\nStep 2: Add one electron on the left.\nStep 3: Write Cl⁻ as the product.","steps":["Step 1: Write the chlorine atom as Cl.","Step 2: Add one electron on the left.","Step 3: Write Cl⁻ as the product."],"options":[],"conceptId":"chemistry_chemical_bonding_formation_of_negative_ions","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Formation of Negative Ions"}', 2);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (3251, 780, 'Sulfur has atomic number 16. How many electrons are present in S²⁻?', 'text', 1, 'A neutral sulfur atom has the same number of electrons as its atomic number.', '{"why":"The sulfur nucleus remains unchanged; only the electron count increases.","sol":"Step 1: A neutral sulfur atom has 16 electrons.\nStep 2: The 2− charge means it has gained two electrons.\nStep 3: Total electrons = 16 + 2 = 18.","steps":["Step 1: A neutral sulfur atom has 16 electrons.","Step 2: The 2− charge means it has gained two electrons.","Step 3: Total electrons = 16 + 2 = 18."],"options":[],"conceptId":"chemistry_chemical_bonding_formation_of_negative_ions","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Formation of Negative Ions"}', 3),
  (3252, 780, 'Explain why an oxygen atom remains oxygen after gaining two electrons to form O²⁻.', 'text', 1, 'Recall what determines the identity of an element.', '{"why":"Ordinary ion formation changes the electrical charge, not the element''s proton number.","sol":"Step 1: Oxygen has 8 protons.\nStep 2: Gaining two electrons changes the electron count from 8 to 10.\nStep 3: The number of protons remains 8.\nStep 4: An element is identified by its number of protons.","steps":["Step 1: Oxygen has 8 protons.","Step 2: Gaining two electrons changes the electron count from 8 to 10.","Step 3: The number of protons remains 8.","Step 4: An element is identified by its number of protons."],"options":[],"conceptId":"chemistry_chemical_bonding_formation_of_negative_ions","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q5","subject":"chemistry","chapter":"chemical_bonding","topic":"Formation of Negative Ions"}', 4),
  (3253, 781, 'Sodium forms Na⁺ and oxygen forms O²⁻. Derive the formula of sodium oxide.', 'text', 1, 'Find how many +1 ions are needed to balance one −2 ion.', '{"why":"Two sodium ions balance one oxide ion to make a neutral compound.","sol":"Step 1: Na⁺ has charge +1.\nStep 2: O²⁻ has charge −2.\nStep 3: Two Na⁺ ions give a total charge of +2.\nStep 4: One O²⁻ ion gives −2.\nStep 5: The charges cancel in a 2:1 ratio.","steps":["Step 1: Na⁺ has charge +1.","Step 2: O²⁻ has charge −2.","Step 3: Two Na⁺ ions give a total charge of +2.","Step 4: One O²⁻ ion gives −2.","Step 5: The charges cancel in a 2:1 ratio."],"options":[],"conceptId":"chemistry_chemical_bonding_formation_of_ionic_compounds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Formation of Ionic Compounds"}', 0),
  (3254, 781, 'Calcium forms Ca²⁺ and fluorine forms F⁻. Determine the formula of calcium fluoride.', 'text', 1, 'Each fluoride ion contributes one negative charge.', '{"why":"One calcium ion requires two fluoride ions to balance its charge.","sol":"Step 1: Calcium contributes +2.\nStep 2: Each fluoride ion contributes −1.\nStep 3: Two fluoride ions contribute −2.\nStep 4: The total charge is +2 − 2 = 0.","steps":["Step 1: Calcium contributes +2.","Step 2: Each fluoride ion contributes −1.","Step 3: Two fluoride ions contribute −2.","Step 4: The total charge is +2 − 2 = 0."],"options":[],"conceptId":"chemistry_chemical_bonding_formation_of_ionic_compounds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Formation of Ionic Compounds"}', 1),
  (3255, 781, 'Derive the formula of aluminium oxide using Al³⁺ and O²⁻.', 'text', 1, 'Balance the charges at a total magnitude of six.', '{"why":"The 2:3 ratio balances the +3 and −2 charges.","sol":"Step 1: Two Al³⁺ ions contribute +6.\nStep 2: Three O²⁻ ions contribute −6.\nStep 3: The total charge is zero.\nStep 4: Write the smallest whole-number ratio.","steps":["Step 1: Two Al³⁺ ions contribute +6.","Step 2: Three O²⁻ ions contribute −6.","Step 3: The total charge is zero.","Step 4: Write the smallest whole-number ratio."],"options":[],"conceptId":"chemistry_chemical_bonding_formation_of_ionic_compounds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Formation of Ionic Compounds"}', 2),
  (3256, 781, 'Magnesium forms Mg²⁺ and sulfur forms S²⁻. Derive the simplest formula of magnesium sulfide.', 'text', 1, 'Check whether the two charges cancel in a 1:1 ratio.', '{"why":"The ions have equal and opposite charges, so the simplest ratio is 1:1.","sol":"Step 1: Mg²⁺ contributes +2.\nStep 2: S²⁻ contributes −2.\nStep 3: The total is +2 + (−2) = 0.\nStep 4: One ion of each type is sufficient.","steps":["Step 1: Mg²⁺ contributes +2.","Step 2: S²⁻ contributes −2.","Step 3: The total is +2 + (−2) = 0.","Step 4: One ion of each type is sufficient."],"options":[],"conceptId":"chemistry_chemical_bonding_formation_of_ionic_compounds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Formation of Ionic Compounds"}', 3),
  (3257, 781, 'Explain why MgCl₂ is electrically neutral even though it contains charged ions.', 'text', 1, 'Calculate the total charge contributed by one magnesium ion and two chloride ions.', '{"why":"Individual ions are charged, but the complete ionic compound has equal total positive and negative charges.","sol":"Step 1: One Mg²⁺ ion contributes +2.\nStep 2: Each Cl⁻ ion contributes −1.\nStep 3: Two chloride ions contribute −2.\nStep 4: Total charge = +2 − 2 = 0.","steps":["Step 1: One Mg²⁺ ion contributes +2.","Step 2: Each Cl⁻ ion contributes −1.","Step 3: Two chloride ions contribute −2.","Step 4: Total charge = +2 − 2 = 0."],"options":[],"conceptId":"chemistry_chemical_bonding_formation_of_ionic_compounds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q5","subject":"chemistry","chapter":"chemical_bonding","topic":"Formation of Ionic Compounds"}', 4),
  (3258, 782, 'Explain why solid sodium chloride does not conduct electricity.', 'text', 1, 'Think about whether the charged ions can move through the solid.', '{"why":"Electrical conduction in ionic substances requires mobile charged particles.","sol":"Step 1: Sodium chloride contains charged Na⁺ and Cl⁻ ions.\nStep 2: The ions occupy fixed positions in the solid lattice.\nStep 3: They cannot move freely through the material.\nStep 4: Therefore, they cannot carry electrical current through the solid.","steps":["Step 1: Sodium chloride contains charged Na⁺ and Cl⁻ ions.","Step 2: The ions occupy fixed positions in the solid lattice.","Step 3: They cannot move freely through the material.","Step 4: Therefore, they cannot carry electrical current through the solid."],"options":[],"conceptId":"chemistry_chemical_bonding_properties_of_ionic_compounds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Properties of Ionic Compounds"}', 0),
  (3259, 782, 'Explain why molten sodium chloride conducts electricity.', 'text', 1, 'Compare ion movement in the solid and molten states.', '{"why":"The particles that carry current are the moving ions, not freely moving electrons as in metals.","sol":"Step 1: In the solid, ions are held in fixed positions.\nStep 2: Melting allows the ions to move relative to one another.\nStep 3: The mobile ions carry electrical charge through the liquid.","steps":["Step 1: In the solid, ions are held in fixed positions.","Step 2: Melting allows the ions to move relative to one another.","Step 3: The mobile ions carry electrical charge through the liquid."],"options":[],"conceptId":"chemistry_chemical_bonding_properties_of_ionic_compounds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Properties of Ionic Compounds"}', 1),
  (3260, 782, 'Explain why many ionic compounds have high melting points.', 'text', 1, 'Identify the force between the ions and the energy required during melting.', '{"why":"The energy needed to disrupt the lattice explains the high melting points of many ionic compounds.","sol":"Step 1: Ionic compounds contain a giant lattice of oppositely charged ions.\nStep 2: The ions experience strong electrostatic attractions.\nStep 3: A substantial amount of energy is needed to overcome enough of these attractions for melting.","steps":["Step 1: Ionic compounds contain a giant lattice of oppositely charged ions.","Step 2: The ions experience strong electrostatic attractions.","Step 3: A substantial amount of energy is needed to overcome enough of these attractions for melting."],"options":[],"conceptId":"chemistry_chemical_bonding_properties_of_ionic_compounds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Properties of Ionic Compounds"}', 2),
  (3261, 782, 'A soluble ionic compound dissolves in water and forms mobile ions. Explain why its solution can conduct electricity.', 'text', 1, 'What can the ions do in solution that they cannot do in the solid lattice?', '{"why":"A solution of a soluble ionic compound conducts when enough mobile ions are present.","sol":"Step 1: The compound separates into positive and negative ions in solution.\nStep 2: The ions are free to move through the solution.\nStep 3: Moving charged particles carry electrical current.","steps":["Step 1: The compound separates into positive and negative ions in solution.","Step 2: The ions are free to move through the solution.","Step 3: Moving charged particles carry electrical current."],"options":[],"conceptId":"chemistry_chemical_bonding_properties_of_ionic_compounds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Properties of Ionic Compounds"}', 3),
  (3262, 782, 'Explain why ionic crystals tend to be brittle when a force shifts their layers.', 'text', 1, 'Consider what happens when ions with the same charge become neighbours.', '{"why":"The arrangement of charged ions explains the brittleness of ionic crystals.","sol":"Step 1: The ionic crystal contains alternating positive and negative ions.\nStep 2: A force may shift the layers in the lattice.\nStep 3: The shift can place ions with the same charge next to each other.\nStep 4: Like charges repel, causing the crystal to split.","steps":["Step 1: The ionic crystal contains alternating positive and negative ions.","Step 2: A force may shift the layers in the lattice.","Step 3: The shift can place ions with the same charge next to each other.","Step 4: Like charges repel, causing the crystal to split."],"options":[],"conceptId":"chemistry_chemical_bonding_properties_of_ionic_compounds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q5","subject":"chemistry","chapter":"chemical_bonding","topic":"Properties of Ionic Compounds"}', 4),
  (3263, 783, 'Define a covalent bond.', 'text', 1, 'Include what is shared and how the shared electrons help hold the atoms together.', '{"why":"The shared electrons provide the attractive interaction that holds the bonded atoms together.","sol":"Step 1: Identify the shared particles as electrons.\nStep 2: One pair of electrons is shared in a single covalent bond.\nStep 3: The shared electrons are attracted to both bonded nuclei.","steps":["Step 1: Identify the shared particles as electrons.","Step 2: One pair of electrons is shared in a single covalent bond.","Step 3: The shared electrons are attracted to both bonded nuclei."],"options":[],"conceptId":"chemistry_chemical_bonding_covalent_bonding","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Covalent Bonding"}', 0),
  (3264, 783, 'Explain how two hydrogen atoms form H₂.', 'text', 1, 'Each hydrogen atom begins with one electron.', '{"why":"Sharing gives each hydrogen access to a two-electron first shell in this model.","sol":"Step 1: Each hydrogen atom has one electron.\nStep 2: Each contributes one electron to a shared pair.\nStep 3: The shared pair is attracted to both nuclei.\nStep 4: One single covalent bond forms.","steps":["Step 1: Each hydrogen atom has one electron.","Step 2: Each contributes one electron to a shared pair.","Step 3: The shared pair is attracted to both nuclei.","Step 4: One single covalent bond forms."],"options":[],"conceptId":"chemistry_chemical_bonding_covalent_bonding","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Covalent Bonding"}', 1),
  (3265, 783, 'Explain why a water molecule has two O—H covalent bonds.', 'text', 1, 'Use oxygen''s six outer-shell electrons and hydrogen''s one electron.', '{"why":"The shared pairs help complete the outer-shell arrangements in the simple model.","sol":"Step 1: Oxygen has six outer-shell electrons.\nStep 2: In the simple shell model, oxygen needs two more electrons.\nStep 3: Each hydrogen shares one pair with oxygen.\nStep 4: Two hydrogen atoms therefore form two O—H bonds.","steps":["Step 1: Oxygen has six outer-shell electrons.","Step 2: In the simple shell model, oxygen needs two more electrons.","Step 3: Each hydrogen shares one pair with oxygen.","Step 4: Two hydrogen atoms therefore form two O—H bonds."],"options":[],"conceptId":"chemistry_chemical_bonding_covalent_bonding","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Covalent Bonding"}', 2),
  (3266, 783, 'Chlorine has seven outer-shell electrons. Explain how two chlorine atoms form Cl₂.', 'text', 1, 'Each chlorine atom needs one additional electron in the simple octet model.', '{"why":"The shared pair allows each chlorine atom to be associated with eight outer-shell electrons.","sol":"Step 1: Each chlorine atom has seven outer-shell electrons.\nStep 2: Each atom contributes one electron to a shared pair.\nStep 3: Both atoms share the pair.\nStep 4: One single covalent bond forms.","steps":["Step 1: Each chlorine atom has seven outer-shell electrons.","Step 2: Each atom contributes one electron to a shared pair.","Step 3: Both atoms share the pair.","Step 4: One single covalent bond forms."],"options":[],"conceptId":"chemistry_chemical_bonding_covalent_bonding","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Covalent Bonding"}', 3),
  (3267, 783, 'State one difference between ionic bonding and covalent bonding.', 'text', 1, 'Compare what happens to electrons in the two types of bonding.', '{"why":"The two bonding types differ in how electrons participate and how the bonded particles are held together.","sol":"Step 1: In ionic bonding, electrons are transferred in common introductory examples, producing ions.\nStep 2: The ionic bond is the attraction between oppositely charged ions.\nStep 3: In covalent bonding, atoms share electron pairs.\nStep 4: The shared electrons are attracted to both bonded nuclei.","steps":["Step 1: In ionic bonding, electrons are transferred in common introductory examples, producing ions.","Step 2: The ionic bond is the attraction between oppositely charged ions.","Step 3: In covalent bonding, atoms share electron pairs.","Step 4: The shared electrons are attracted to both bonded nuclei."],"options":[],"conceptId":"chemistry_chemical_bonding_covalent_bonding","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q5","subject":"chemistry","chapter":"chemical_bonding","topic":"Covalent Bonding"}', 4),
  (3268, 784, 'What does one line between two atoms in a displayed covalent formula represent?', 'text', 1, 'Connect the bond line to the number of shared electron pairs.', '{"why":"The line is a shorthand representation for a single covalent bond.","sol":"Step 1: A single bond is represented by one line.\nStep 2: One single bond represents one shared pair.\nStep 3: One electron pair contains two electrons.","steps":["Step 1: A single bond is represented by one line.","Step 2: One single bond represents one shared pair.","Step 3: One electron pair contains two electrons."],"options":[],"conceptId":"chemistry_chemical_bonding_single_covalent_bonds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Single Covalent Bonds"}', 0),
  (3269, 784, 'How many single covalent bonds are present in one molecule of methane, CH₄?', 'text', 1, 'Each of the four hydrogen atoms forms one bond to carbon.', '{"why":"Each hydrogen contributes to one bond with the carbon atom.","sol":"Step 1: Methane contains one carbon atom and four hydrogen atoms.\nStep 2: Each hydrogen forms one C—H single bond.\nStep 3: There are four C—H bonds in total.","steps":["Step 1: Methane contains one carbon atom and four hydrogen atoms.","Step 2: Each hydrogen forms one C—H single bond.","Step 3: There are four C—H bonds in total."],"options":[],"conceptId":"chemistry_chemical_bonding_single_covalent_bonds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Single Covalent Bonds"}', 1),
  (3270, 784, 'How many electrons are shared in the single covalent bond in H₂?', 'text', 1, 'A single bond contains one pair of electrons.', '{"why":"Both hydrogen atoms share the same pair of electrons.","sol":"Step 1: One single covalent bond contains one shared pair.\nStep 2: One pair contains two electrons.","steps":["Step 1: One single covalent bond contains one shared pair.","Step 2: One pair contains two electrons."],"options":[],"conceptId":"chemistry_chemical_bonding_single_covalent_bonds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Single Covalent Bonds"}', 2),
  (3271, 784, 'Ammonia, NH₃, has three N—H single bonds. How many bonding pairs are present, and how many lone pairs remain on nitrogen in the simple electron-pair model?', 'text', 1, 'Count one bonding pair per bond, then account for nitrogen''s five outer-shell electrons.', '{"why":"Bonding pairs are shared between atoms, while the lone pair remains localised on nitrogen in this model.","sol":"Step 1: Three single bonds mean three bonding pairs.\nStep 2: Nitrogen has five outer-shell electrons.\nStep 3: In ammonia, nitrogen shares one electron in each of three bonds.\nStep 4: The remaining two electrons form one lone pair.","steps":["Step 1: Three single bonds mean three bonding pairs.","Step 2: Nitrogen has five outer-shell electrons.","Step 3: In ammonia, nitrogen shares one electron in each of three bonds.","Step 4: The remaining two electrons form one lone pair."],"options":[],"conceptId":"chemistry_chemical_bonding_single_covalent_bonds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Single Covalent Bonds"}', 3),
  (3272, 784, 'A displayed formula contains four single bond lines. How many shared electron pairs and how many bonding electrons do the lines represent in total?', 'text', 1, 'Each line represents one pair containing two electrons.', '{"why":"Each single bond contributes exactly one pair of shared electrons.","sol":"Step 1: There are four single bonds.\nStep 2: Each bond represents one shared pair, so there are four pairs.\nStep 3: Each pair contains two electrons.\nStep 4: Total bonding electrons = 4 × 2 = 8.","steps":["Step 1: There are four single bonds.","Step 2: Each bond represents one shared pair, so there are four pairs.","Step 3: Each pair contains two electrons.","Step 4: Total bonding electrons = 4 × 2 = 8."],"options":[],"conceptId":"chemistry_chemical_bonding_single_covalent_bonds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q5","subject":"chemistry","chapter":"chemical_bonding","topic":"Single Covalent Bonds"}', 4),
  (3273, 785, 'Define a double covalent bond and state how many electrons it contains.', 'text', 1, 'A double bond has two shared pairs.', '{"why":"Each shared pair contains two electrons.","sol":"Step 1: A single pair contains two electrons.\nStep 2: A double bond contains two shared pairs.\nStep 3: Total electrons = 2 × 2 = 4.","steps":["Step 1: A single pair contains two electrons.","Step 2: A double bond contains two shared pairs.","Step 3: Total electrons = 2 × 2 = 4."],"options":[],"conceptId":"chemistry_chemical_bonding_double_covalent_bonds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Double Covalent Bonds"}', 0),
  (3274, 785, 'An oxygen molecule is represented by O=O. How many shared electron pairs are present?', 'text', 1, 'Count the pairs represented by the double bond.', '{"why":"The double bond allows each oxygen atom to share two pairs with the other atom.","sol":"Step 1: The two lines represent a double bond.\nStep 2: A double bond contains two shared pairs.","steps":["Step 1: The two lines represent a double bond.","Step 2: A double bond contains two shared pairs."],"options":[],"conceptId":"chemistry_chemical_bonding_double_covalent_bonds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Double Covalent Bonds"}', 1),
  (3275, 785, 'Carbon dioxide is represented by O=C=O. Determine the number of double bonds and the total number of shared electrons.', 'text', 1, 'There are two C=O connections, and each double bond contains four shared electrons.', '{"why":"The molecule contains two double bonds, each made of two shared electron pairs.","sol":"Step 1: There are two C=O double bonds.\nStep 2: Each double bond contains four shared electrons.\nStep 3: Total shared electrons = 2 × 4 = 8.","steps":["Step 1: There are two C=O double bonds.","Step 2: Each double bond contains four shared electrons.","Step 3: Total shared electrons = 2 × 4 = 8."],"options":[],"conceptId":"chemistry_chemical_bonding_double_covalent_bonds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Double Covalent Bonds"}', 2),
  (3276, 785, 'How many shared electrons are present in three double covalent bonds?', 'text', 1, 'Find the number of electrons in one double bond, then multiply by three.', '{"why":"Each double bond contains two pairs, or four electrons.","sol":"Step 1: One double bond contains four shared electrons.\nStep 2: Three double bonds contain 3 × 4 electrons.\nStep 3: Total = 12 shared electrons.","steps":["Step 1: One double bond contains four shared electrons.","Step 2: Three double bonds contain 3 × 4 electrons.","Step 3: Total = 12 shared electrons."],"options":[],"conceptId":"chemistry_chemical_bonding_double_covalent_bonds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Double Covalent Bonds"}', 3),
  (3277, 785, 'Explain why a double bond is different from a single bond in terms of shared electron pairs.', 'text', 1, 'Compare the number of pairs in each type of bond.', '{"why":"The number of shared electron pairs distinguishes single and double covalent bonds.","sol":"Step 1: A single bond contains one shared pair.\nStep 2: A double bond contains two shared pairs.\nStep 3: Therefore, a double bond has one additional shared pair compared with a single bond.","steps":["Step 1: A single bond contains one shared pair.","Step 2: A double bond contains two shared pairs.","Step 3: Therefore, a double bond has one additional shared pair compared with a single bond."],"options":[],"conceptId":"chemistry_chemical_bonding_double_covalent_bonds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q5","subject":"chemistry","chapter":"chemical_bonding","topic":"Double Covalent Bonds"}', 4),
  (3278, 786, 'Define a triple covalent bond and state the number of shared electrons it contains.', 'text', 1, 'Multiply the three shared pairs by two electrons per pair.', '{"why":"Each shared pair contributes two electrons to the bond.","sol":"Step 1: A triple bond contains three shared pairs.\nStep 2: Each pair contains two electrons.\nStep 3: Total = 3 × 2 = 6 electrons.","steps":["Step 1: A triple bond contains three shared pairs.","Step 2: Each pair contains two electrons.","Step 3: Total = 3 × 2 = 6 electrons."],"options":[],"conceptId":"chemistry_chemical_bonding_triple_covalent_bonds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Triple Covalent Bonds"}', 0),
  (3279, 786, 'Nitrogen is represented by N≡N. How many shared electron pairs are between the nitrogen atoms?', 'text', 1, 'Each line in the triple-bond symbol represents a shared pair in this model.', '{"why":"Three shared pairs form the triple bond between the two nitrogen atoms.","sol":"Step 1: The symbol ≡ represents a triple bond.\nStep 2: A triple bond contains three shared pairs.","steps":["Step 1: The symbol ≡ represents a triple bond.","Step 2: A triple bond contains three shared pairs."],"options":[],"conceptId":"chemistry_chemical_bonding_triple_covalent_bonds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Triple Covalent Bonds"}', 1),
  (3280, 786, 'Calculate the total number of shared electrons in one single bond, one double bond, and one triple bond combined.', 'text', 1, 'Calculate the electron count for each bond type separately.', '{"why":"The total is the sum of the shared electrons in the three bonds.","sol":"Step 1: Single bond: 2 electrons.\nStep 2: Double bond: 4 electrons.\nStep 3: Triple bond: 6 electrons.\nStep 4: Total = 2 + 4 + 6 = 12 electrons.","steps":["Step 1: Single bond: 2 electrons.","Step 2: Double bond: 4 electrons.","Step 3: Triple bond: 6 electrons.","Step 4: Total = 2 + 4 + 6 = 12 electrons."],"options":[],"conceptId":"chemistry_chemical_bonding_triple_covalent_bonds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Triple Covalent Bonds"}', 2),
  (3281, 786, 'Nitrogen has five outer-shell electrons. Explain how sharing three pairs in N₂ helps each nitrogen atom reach an octet in the simple model.', 'text', 1, 'Count the electrons each nitrogen contributes and the shared pairs around it.', '{"why":"Shared electrons count towards the outer-shell arrangement of both bonded atoms.","sol":"Step 1: Each nitrogen atom contributes five outer-shell electrons before bonding.\nStep 2: The atoms share three pairs between them.\nStep 3: For each nitrogen, the three shared pairs count as six electrons around that atom.\nStep 4: The three shared electrons contributed by the other atom, together with the nitrogen''s own bonding contribution and remaining electrons, give each nitrogen an octet in the standard dot-and-cross model.","steps":["Step 1: Each nitrogen atom contributes five outer-shell electrons before bonding.","Step 2: The atoms share three pairs between them.","Step 3: For each nitrogen, the three shared pairs count as six electrons around that atom.","Step 4: The three shared electrons contributed by the other atom, together with the nitrogen''s own bonding contribution and remaining electrons, give each nitrogen an octet in the standard dot-and-cross model."],"options":[],"conceptId":"chemistry_chemical_bonding_triple_covalent_bonds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Triple Covalent Bonds"}', 3),
  (3282, 786, 'State the general trend in bond length and bond strength when comparing single, double, and triple bonds between the same two elements.', 'text', 1, 'Compare how the number of shared pairs changes.', '{"why":"This is a general trend for comparable bonds; actual bond properties depend on the atoms and their chemical environment.","sol":"Step 1: A single bond has one shared pair.\nStep 2: A double bond has two shared pairs.\nStep 3: A triple bond has three shared pairs.\nStep 4: For comparable bonds between the same elements, bond length generally decreases and bond strength generally increases as bond order rises.","steps":["Step 1: A single bond has one shared pair.","Step 2: A double bond has two shared pairs.","Step 3: A triple bond has three shared pairs.","Step 4: For comparable bonds between the same elements, bond length generally decreases and bond strength generally increases as bond order rises."],"options":[],"conceptId":"chemistry_chemical_bonding_triple_covalent_bonds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q5","subject":"chemistry","chapter":"chemical_bonding","topic":"Triple Covalent Bonds"}', 4),
  (3283, 787, 'What do dots and crosses represent in a dot-and-cross diagram?', 'text', 1, 'Think about why two symbols are used for electrons.', '{"why":"The convention helps learners follow electron sharing or transfer.","sol":"Step 1: Both dots and crosses represent electrons.\nStep 2: The symbols distinguish electrons that came from different atoms before bonding.\nStep 3: They do not represent different types of electrons.","steps":["Step 1: Both dots and crosses represent electrons.","Step 2: The symbols distinguish electrons that came from different atoms before bonding.","Step 3: They do not represent different types of electrons."],"options":[],"conceptId":"chemistry_chemical_bonding_dot_and_cross_diagrams","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Dot-and-Cross Diagrams"}', 0),
  (3284, 787, 'Describe the dot-and-cross diagram for H₂ in words.', 'text', 1, 'Each hydrogen contributes one electron to the shared pair.', '{"why":"Each hydrogen contributes one electron to the pair shared by both atoms.","sol":"Step 1: Each hydrogen atom has one electron.\nStep 2: Represent the two electrons using different symbols.\nStep 3: Place one dot and one cross together between the hydrogen atoms.\nStep 4: The pair represents one single covalent bond.","steps":["Step 1: Each hydrogen atom has one electron.","Step 2: Represent the two electrons using different symbols.","Step 3: Place one dot and one cross together between the hydrogen atoms.","Step 4: The pair represents one single covalent bond."],"options":[],"conceptId":"chemistry_chemical_bonding_dot_and_cross_diagrams","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Dot-and-Cross Diagrams"}', 1),
  (3285, 787, 'A chlorine atom has seven outer-shell electrons and gains one electron. How many should be shown around the resulting chloride ion?', 'text', 1, 'Add the gained electron to the original outer-shell count.', '{"why":"The chloride ion has one more electron than a neutral chlorine atom.","sol":"Step 1: Chlorine starts with seven outer-shell electrons.\nStep 2: It gains one electron.\nStep 3: Total = 7 + 1 = 8.","steps":["Step 1: Chlorine starts with seven outer-shell electrons.","Step 2: It gains one electron.","Step 3: Total = 7 + 1 = 8."],"options":[],"conceptId":"chemistry_chemical_bonding_dot_and_cross_diagrams","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Dot-and-Cross Diagrams"}', 2),
  (3286, 787, 'In Cl₂, state the number of shared pairs and the number of lone pairs on each chlorine atom.', 'text', 1, 'Each chlorine contributes one electron to the bond and retains six other outer-shell electrons.', '{"why":"The shared pair forms the bond, while the remaining pairs are not shared between the atoms.","sol":"Step 1: Each chlorine has seven outer-shell electrons.\nStep 2: One electron from each atom forms the shared pair.\nStep 3: Each chlorine has six remaining outer-shell electrons.\nStep 4: Six electrons form three lone pairs.","steps":["Step 1: Each chlorine has seven outer-shell electrons.","Step 2: One electron from each atom forms the shared pair.","Step 3: Each chlorine has six remaining outer-shell electrons.","Step 4: Six electrons form three lone pairs."],"options":[],"conceptId":"chemistry_chemical_bonding_dot_and_cross_diagrams","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Dot-and-Cross Diagrams"}', 3),
  (3287, 787, 'Describe the essential features of a dot-and-cross diagram for sodium chloride after electron transfer.', 'text', 1, 'Include the electron transfer, brackets, ion charges, and chlorine''s outer-shell count.', '{"why":"The diagram must show both the electron transfer and the final charges of the ions.","sol":"Step 1: Show one electron transferred from sodium to chlorine.\nStep 2: Show sodium as a positive ion in square brackets with a + charge.\nStep 3: Show chlorine as a negative ion in square brackets with a − charge.\nStep 4: Show eight outer-shell electrons around the chloride ion, including the transferred electron.","steps":["Step 1: Show one electron transferred from sodium to chlorine.","Step 2: Show sodium as a positive ion in square brackets with a + charge.","Step 3: Show chlorine as a negative ion in square brackets with a − charge.","Step 4: Show eight outer-shell electrons around the chloride ion, including the transferred electron."],"options":[],"conceptId":"chemistry_chemical_bonding_dot_and_cross_diagrams","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q5","subject":"chemistry","chapter":"chemical_bonding","topic":"Dot-and-Cross Diagrams"}', 4),
  (3288, 788, 'Explain why many simple covalent substances have relatively low boiling points.', 'text', 1, 'Identify what is overcome when separate molecules move apart during boiling.', '{"why":"The covalent bonds within the molecules are not normally all broken during boiling.","sol":"Step 1: A simple covalent substance consists of separate molecules.\nStep 2: The molecules attract one another through intermolecular forces.\nStep 3: Boiling requires enough energy to overcome these attractions.\nStep 4: For many small molecules, these attractions are relatively weak.","steps":["Step 1: A simple covalent substance consists of separate molecules.","Step 2: The molecules attract one another through intermolecular forces.","Step 3: Boiling requires enough energy to overcome these attractions.","Step 4: For many small molecules, these attractions are relatively weak."],"options":[],"conceptId":"chemistry_chemical_bonding_properties_of_simple_covalent_substances","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Properties of Simple Covalent Substances"}', 0),
  (3289, 788, 'Explain why many simple molecular substances do not conduct electricity.', 'text', 1, 'Consider whether mobile ions or delocalised electrons are present.', '{"why":"Covalent bonds alone do not provide freely moving ions or electrons throughout a simple molecular substance.","sol":"Step 1: Electrical conduction requires mobile charged particles.\nStep 2: Simple molecular substances generally lack mobile ions.\nStep 3: They also generally lack delocalised electrons that can move through the substance.\nStep 4: Therefore, they usually conduct electricity poorly.","steps":["Step 1: Electrical conduction requires mobile charged particles.","Step 2: Simple molecular substances generally lack mobile ions.","Step 3: They also generally lack delocalised electrons that can move through the substance.","Step 4: Therefore, they usually conduct electricity poorly."],"options":[],"conceptId":"chemistry_chemical_bonding_properties_of_simple_covalent_substances","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Properties of Simple Covalent Substances"}', 1),
  (3290, 788, 'A learner claims that all covalent substances are insoluble in water. Explain why this is incorrect.', 'text', 1, 'Consider whether all molecules have the same interactions with water.', '{"why":"Covalent bonding alone does not determine whether a substance dissolves in water.","sol":"Step 1: Covalent substances have different molecular structures and polarities.\nStep 2: Their interactions with water therefore differ.\nStep 3: Some, such as ammonia, dissolve readily in water.\nStep 4: Others, such as methane, are only very slightly soluble.","steps":["Step 1: Covalent substances have different molecular structures and polarities.","Step 2: Their interactions with water therefore differ.","Step 3: Some, such as ammonia, dissolve readily in water.","Step 4: Others, such as methane, are only very slightly soluble."],"options":[],"conceptId":"chemistry_chemical_bonding_properties_of_simple_covalent_substances","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Properties of Simple Covalent Substances"}', 2),
  (3291, 788, 'Explain why methane and diamond do not have similar melting points even though both contain covalent bonds.', 'text', 1, 'Compare their structures rather than considering only the type of bond.', '{"why":"Structure determines which forces must be overcome during melting.","sol":"Step 1: Methane consists of separate CH₄ molecules.\nStep 2: Its molecules are held together by relatively weak intermolecular attractions.\nStep 3: Diamond has a giant covalent network.\nStep 4: Disrupting diamond requires breaking many strong covalent bonds.","steps":["Step 1: Methane consists of separate CH₄ molecules.","Step 2: Its molecules are held together by relatively weak intermolecular attractions.","Step 3: Diamond has a giant covalent network.","Step 4: Disrupting diamond requires breaking many strong covalent bonds."],"options":[],"conceptId":"chemistry_chemical_bonding_properties_of_simple_covalent_substances","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Properties of Simple Covalent Substances"}', 3),
  (3292, 788, 'A student compares pure water with sodium chloride solution. Explain why the salt solution conducts electricity better.', 'text', 1, 'Focus on the number and movement of ions.', '{"why":"Electrical conductivity depends on the availability of mobile charged particles.","sol":"Step 1: Pure water contains very few ions.\nStep 2: Dissolved sodium chloride separates into Na⁺ and Cl⁻ ions.\nStep 3: These ions can move through the solution.\nStep 4: The mobile ions carry electrical current.","steps":["Step 1: Pure water contains very few ions.","Step 2: Dissolved sodium chloride separates into Na⁺ and Cl⁻ ions.","Step 3: These ions can move through the solution.","Step 4: The mobile ions carry electrical current."],"options":[],"conceptId":"chemistry_chemical_bonding_properties_of_simple_covalent_substances","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q5","subject":"chemistry","chapter":"chemical_bonding","topic":"Properties of Simple Covalent Substances"}', 4),
  (3293, 789, 'Define a giant covalent structure.', 'text', 1, 'Describe the scale and continuity of the bonded atoms.', '{"why":"The extensive network explains many of the physical properties of giant covalent substances.","sol":"Step 1: Identify the particles as atoms.\nStep 2: The atoms are connected by covalent bonds.\nStep 3: The bonds extend through a large continuous network rather than forming only separate small molecules.","steps":["Step 1: Identify the particles as atoms.","Step 2: The atoms are connected by covalent bonds.","Step 3: The bonds extend through a large continuous network rather than forming only separate small molecules."],"options":[],"conceptId":"chemistry_chemical_bonding_giant_covalent_structures","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Giant Covalent Structures"}', 0),
  (3294, 789, 'Explain why diamond has a very high melting point.', 'text', 1, 'Consider how many bonds must be disrupted to melt the structure.', '{"why":"The extensive network requires much more energy to disrupt than the intermolecular attractions in a simple molecular substance.","sol":"Step 1: Diamond has a giant three-dimensional network.\nStep 2: Each carbon atom forms four strong covalent bonds.\nStep 3: Melting requires disrupting many of these bonds.\nStep 4: A large amount of energy is therefore needed.","steps":["Step 1: Diamond has a giant three-dimensional network.","Step 2: Each carbon atom forms four strong covalent bonds.","Step 3: Melting requires disrupting many of these bonds.","Step 4: A large amount of energy is therefore needed."],"options":[],"conceptId":"chemistry_chemical_bonding_giant_covalent_structures","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Giant Covalent Structures"}', 1),
  (3295, 789, 'Explain why graphite conducts electricity.', 'text', 1, 'Count the covalent bonds formed by each carbon atom and consider the remaining outer electron.', '{"why":"Electrical conduction is possible because some electrons are not confined to individual covalent bonds.","sol":"Step 1: Each carbon atom in graphite forms three covalent bonds.\nStep 2: One outer electron per carbon atom is delocalised.\nStep 3: The delocalised electrons can move through the structure.\nStep 4: Moving electrons carry electrical charge.","steps":["Step 1: Each carbon atom in graphite forms three covalent bonds.","Step 2: One outer electron per carbon atom is delocalised.","Step 3: The delocalised electrons can move through the structure.","Step 4: Moving electrons carry electrical charge."],"options":[],"conceptId":"chemistry_chemical_bonding_giant_covalent_structures","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Giant Covalent Structures"}', 2),
  (3296, 789, 'State the number of covalent bonds formed by each carbon atom in diamond and in graphite.', 'text', 1, 'Compare the bonding arrangement in the two carbon structures.', '{"why":"The different bonding arrangements help explain the different properties of the two carbon structures.","sol":"Step 1: In diamond, each carbon atom bonds to four other carbon atoms.\nStep 2: In graphite, each carbon atom bonds to three other carbon atoms.","steps":["Step 1: In diamond, each carbon atom bonds to four other carbon atoms.","Step 2: In graphite, each carbon atom bonds to three other carbon atoms."],"options":[],"conceptId":"chemistry_chemical_bonding_giant_covalent_structures","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Giant Covalent Structures"}', 3),
  (3297, 789, 'Explain the structural difference between silicon dioxide and carbon dioxide.', 'text', 1, 'Decide whether each substance forms a continuous network or separate molecules.', '{"why":"Different structures can result in very different physical properties even when covalent bonds are present in both substances.","sol":"Step 1: Silicon dioxide forms a giant covalent network in the solid.\nStep 2: Carbon dioxide consists of separate CO₂ molecules under ordinary conditions.\nStep 3: SiO₂ gives the ratio of atoms in the network.\nStep 4: CO₂ gives the number of each type of atom in an individual molecule.","steps":["Step 1: Silicon dioxide forms a giant covalent network in the solid.","Step 2: Carbon dioxide consists of separate CO₂ molecules under ordinary conditions.","Step 3: SiO₂ gives the ratio of atoms in the network.","Step 4: CO₂ gives the number of each type of atom in an individual molecule."],"options":[],"conceptId":"chemistry_chemical_bonding_giant_covalent_structures","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q5","subject":"chemistry","chapter":"chemical_bonding","topic":"Giant Covalent Structures"}', 4),
  (3298, 790, 'Explain why diamond is extremely hard.', 'text', 1, 'Describe how many bonds each carbon atom forms and how the bonds extend through the structure.', '{"why":"The explanation links the bonding arrangement directly to resistance to scratching and deformation.","sol":"Step 1: Diamond has a giant three-dimensional covalent structure.\nStep 2: Each carbon atom forms four strong covalent bonds with neighbouring carbon atoms.\nStep 3: The strong bonds extend throughout the structure, so the network cannot be easily deformed.","steps":["Step 1: Diamond has a giant three-dimensional covalent structure.","Step 2: Each carbon atom forms four strong covalent bonds with neighbouring carbon atoms.","Step 3: The strong bonds extend throughout the structure, so the network cannot be easily deformed."],"options":[],"conceptId":"chemistry_chemical_bonding_diamond","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Diamond"}', 0),
  (3299, 790, 'Explain why diamond has a very high melting point.', 'text', 1, 'Consider the energy needed to disrupt the giant covalent network.', '{"why":"The high melting point is explained by the strength and extent of the covalent network.","sol":"Step 1: Diamond contains a giant covalent network rather than separate molecules.\nStep 2: Strong covalent bonds connect the carbon atoms throughout the network.\nStep 3: A large amount of energy is required to disrupt enough of these bonds for the structure to melt.","steps":["Step 1: Diamond contains a giant covalent network rather than separate molecules.","Step 2: Strong covalent bonds connect the carbon atoms throughout the network.","Step 3: A large amount of energy is required to disrupt enough of these bonds for the structure to melt."],"options":[],"conceptId":"chemistry_chemical_bonding_diamond","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Diamond"}', 1),
  (3300, 790, 'Explain why diamond does not conduct electricity.', 'text', 1, 'Account for all four outer-shell electrons of each carbon atom.', '{"why":"Electrical conduction requires mobile charged particles. Diamond lacks freely moving electrons under ordinary conditions.","sol":"Step 1: Each carbon atom has four outer-shell electrons.\nStep 2: All four are used to form covalent bonds with neighbouring carbon atoms.\nStep 3: There are no delocalised electrons available to move through the structure and carry charge.","steps":["Step 1: Each carbon atom has four outer-shell electrons.","Step 2: All four are used to form covalent bonds with neighbouring carbon atoms.","Step 3: There are no delocalised electrons available to move through the structure and carry charge."],"options":[],"conceptId":"chemistry_chemical_bonding_diamond","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Diamond"}', 2),
  (3301, 790, 'A student says, ''Diamond has a high melting point because the forces between its molecules are strong.'' Explain the error in this statement.', 'text', 1, 'Does diamond consist of separate molecules?', '{"why":"Distinguishing a giant covalent structure from a simple molecular substance is essential when explaining melting points.","sol":"Step 1: Diamond is a giant covalent network, not a collection of separate molecules.\nStep 2: Carbon atoms are connected by strong covalent bonds throughout the structure.\nStep 3: Melting requires enough energy to disrupt the giant network; the explanation should not refer to forces between separate diamond molecules.","steps":["Step 1: Diamond is a giant covalent network, not a collection of separate molecules.","Step 2: Carbon atoms are connected by strong covalent bonds throughout the structure.","Step 3: Melting requires enough energy to disrupt the giant network; the explanation should not refer to forces between separate diamond molecules."],"options":[],"conceptId":"chemistry_chemical_bonding_diamond","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Diamond"}', 3),
  (3302, 790, 'Diamond is used in cutting and drilling tools. Explain why its structure makes it suitable for this use.', 'text', 1, 'Relate the structure to resistance to scratching and wear.', '{"why":"A good answer identifies both the property and the structural reason for it.","sol":"Step 1: Each carbon atom is joined to four neighbouring carbon atoms by strong covalent bonds.\nStep 2: These bonds form a rigid three-dimensional network.\nStep 3: The network strongly resists scratching and deformation, making diamond useful for cutting and drilling.","steps":["Step 1: Each carbon atom is joined to four neighbouring carbon atoms by strong covalent bonds.","Step 2: These bonds form a rigid three-dimensional network.","Step 3: The network strongly resists scratching and deformation, making diamond useful for cutting and drilling."],"options":[],"conceptId":"chemistry_chemical_bonding_diamond","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q5","subject":"chemistry","chapter":"chemical_bonding","topic":"Diamond"}', 4),
  (3303, 791, 'Explain why graphite conducts electricity.', 'text', 1, 'Consider how many covalent bonds each carbon atom forms and what happens to its fourth outer-shell electron.', '{"why":"The key idea is the presence of mobile delocalised electrons.","sol":"Step 1: Each carbon atom forms three covalent bonds with neighbouring carbon atoms.\nStep 2: The remaining outer-shell electron contributes to a delocalised electron system.\nStep 3: These electrons can move through the layers and carry electrical charge.","steps":["Step 1: Each carbon atom forms three covalent bonds with neighbouring carbon atoms.","Step 2: The remaining outer-shell electron contributes to a delocalised electron system.","Step 3: These electrons can move through the layers and carry electrical charge."],"options":[],"conceptId":"chemistry_chemical_bonding_graphite","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Graphite"}', 0),
  (3304, 791, 'Explain why graphite is soft and can be used as a lubricant.', 'text', 1, 'Compare the bonding within a layer with the attractions between layers.', '{"why":"The explanation must distinguish strong within-layer covalent bonds from weaker between-layer attractions.","sol":"Step 1: Graphite consists of layers of carbon atoms.\nStep 2: Strong covalent bonds hold the atoms together within each layer.\nStep 3: Relatively weak attractions act between the layers, allowing them to slide over one another.","steps":["Step 1: Graphite consists of layers of carbon atoms.","Step 2: Strong covalent bonds hold the atoms together within each layer.","Step 3: Relatively weak attractions act between the layers, allowing them to slide over one another."],"options":[],"conceptId":"chemistry_chemical_bonding_graphite","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Graphite"}', 1),
  (3305, 791, 'Each carbon atom in graphite forms three covalent bonds. Explain how graphite can still contain delocalised electrons.', 'text', 1, 'Carbon has four outer-shell electrons.', '{"why":"This links carbon''s outer-shell electron arrangement to graphite''s electrical conductivity.","sol":"Step 1: A carbon atom has four outer-shell electrons.\nStep 2: Three electrons are used in forming three covalent bonds with neighbouring carbon atoms.\nStep 3: The remaining electron contributes to the delocalised electron system within the layer.","steps":["Step 1: A carbon atom has four outer-shell electrons.","Step 2: Three electrons are used in forming three covalent bonds with neighbouring carbon atoms.","Step 3: The remaining electron contributes to the delocalised electron system within the layer."],"options":[],"conceptId":"chemistry_chemical_bonding_graphite","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Graphite"}', 2),
  (3306, 791, 'Graphite and diamond are both forms of carbon. Explain why graphite conducts electricity but diamond does not.', 'text', 1, 'Compare the number of covalent bonds formed by each carbon atom.', '{"why":"The two substances have the same element but different bonding arrangements and therefore different electrical properties.","sol":"Step 1: In graphite, each carbon atom forms three covalent bonds, leaving an electron to contribute to a delocalised system.\nStep 2: The delocalised electrons can move and carry charge.\nStep 3: In diamond, each carbon atom forms four covalent bonds, so there are no freely moving electrons under ordinary conditions.","steps":["Step 1: In graphite, each carbon atom forms three covalent bonds, leaving an electron to contribute to a delocalised system.","Step 2: The delocalised electrons can move and carry charge.","Step 3: In diamond, each carbon atom forms four covalent bonds, so there are no freely moving electrons under ordinary conditions."],"options":[],"conceptId":"chemistry_chemical_bonding_graphite","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Graphite"}', 3),
  (3307, 791, 'Explain why graphite has a high melting or sublimation temperature even though its layers can slide over one another.', 'text', 1, 'Distinguish the movement of whole layers from the disruption of the covalent network.', '{"why":"Softness and melting temperature depend on different aspects of graphite''s structure.","sol":"Step 1: The layers can slide because the attractions between them are relatively weak.\nStep 2: Within each layer, carbon atoms are joined by strong covalent bonds.\nStep 3: A large amount of energy is required to disrupt the giant covalent network, giving graphite a very high melting or sublimation temperature.","steps":["Step 1: The layers can slide because the attractions between them are relatively weak.","Step 2: Within each layer, carbon atoms are joined by strong covalent bonds.","Step 3: A large amount of energy is required to disrupt the giant covalent network, giving graphite a very high melting or sublimation temperature."],"options":[],"conceptId":"chemistry_chemical_bonding_graphite","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q5","subject":"chemistry","chapter":"chemical_bonding","topic":"Graphite"}', 4),
  (3308, 792, 'Explain why an ionic compound such as sodium chloride usually has a high melting point.', 'text', 1, 'Identify the particles in the lattice and the force attracting them.', '{"why":"The answer connects the lattice structure and electrostatic attractions to the energy needed for melting.","sol":"Step 1: Sodium chloride contains positive sodium ions and negative chloride ions.\nStep 2: The ions form a giant lattice held together by strong electrostatic attractions between oppositely charged ions.\nStep 3: A large amount of energy is needed to overcome enough of these attractions for the lattice to melt.","steps":["Step 1: Sodium chloride contains positive sodium ions and negative chloride ions.","Step 2: The ions form a giant lattice held together by strong electrostatic attractions between oppositely charged ions.","Step 3: A large amount of energy is needed to overcome enough of these attractions for the lattice to melt."],"options":[],"conceptId":"chemistry_chemical_bonding_ionic_and_covalent_structures","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Ionic and Covalent Structures"}', 0),
  (3309, 792, 'Explain why solid sodium chloride does not normally conduct electricity, but molten sodium chloride does.', 'text', 1, 'Compare whether the ions can move in the solid and molten states.', '{"why":"Electrical conductivity in ionic substances depends on the mobility of the ions, not merely their presence.","sol":"Step 1: In solid sodium chloride, the ions are held in fixed positions in the lattice.\nStep 2: Because the ions cannot move freely, they cannot carry charge through the solid.\nStep 3: When sodium chloride melts, its ions become mobile and can carry electrical charge.","steps":["Step 1: In solid sodium chloride, the ions are held in fixed positions in the lattice.","Step 2: Because the ions cannot move freely, they cannot carry charge through the solid.","Step 3: When sodium chloride melts, its ions become mobile and can carry electrical charge."],"options":[],"conceptId":"chemistry_chemical_bonding_ionic_and_covalent_structures","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Ionic and Covalent Structures"}', 1),
  (3310, 792, 'A simple molecular substance melts at a relatively low temperature. Explain why without claiming that its covalent bonds are weak.', 'text', 1, 'Distinguish the bonds inside each molecule from the attractions between molecules.', '{"why":"This distinction prevents confusing intermolecular forces with covalent bonds.","sol":"Step 1: Atoms within each molecule are joined by covalent bonds.\nStep 2: Separate molecules attract one another through intermolecular forces.\nStep 3: During melting, energy is mainly used to overcome the intermolecular attractions, while the covalent bonds within the molecules generally remain intact.","steps":["Step 1: Atoms within each molecule are joined by covalent bonds.","Step 2: Separate molecules attract one another through intermolecular forces.","Step 3: During melting, energy is mainly used to overcome the intermolecular attractions, while the covalent bonds within the molecules generally remain intact."],"options":[],"conceptId":"chemistry_chemical_bonding_ionic_and_covalent_structures","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Ionic and Covalent Structures"}', 2),
  (3311, 792, 'Diamond and graphite are both giant covalent forms of carbon. Explain why diamond does not conduct electricity while graphite does.', 'text', 1, 'Compare the number of covalent bonds formed by each carbon atom and the availability of mobile electrons.', '{"why":"The electrical properties differ because the two structures use carbon''s outer-shell electrons differently.","sol":"Step 1: In diamond, each carbon atom forms four covalent bonds, using all four outer-shell electrons.\nStep 2: In graphite, each carbon atom forms three covalent bonds.\nStep 3: The remaining electron from each carbon atom contributes to a delocalised system that can carry charge through graphite.","steps":["Step 1: In diamond, each carbon atom forms four covalent bonds, using all four outer-shell electrons.","Step 2: In graphite, each carbon atom forms three covalent bonds.","Step 3: The remaining electron from each carbon atom contributes to a delocalised system that can carry charge through graphite."],"options":[],"conceptId":"chemistry_chemical_bonding_ionic_and_covalent_structures","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Ionic and Covalent Structures"}', 3),
  (3312, 792, 'A student claims, ''All covalent substances have low melting points and cannot conduct electricity.'' Correct the claim using a simple molecular substance, diamond and graphite.', 'text', 1, 'Classify each structure before stating its properties.', '{"why":"The properties of covalent substances depend on whether their structure is simple molecular or giant covalent and on whether mobile charge carriers are present.","sol":"Step 1: Many simple molecular substances have relatively low melting points because melting mainly overcomes intermolecular attractions.\nStep 2: Diamond is a giant covalent structure with a very high melting temperature because its network contains strong covalent bonds.\nStep 3: Diamond does not conduct electricity under ordinary conditions, but graphite conducts because it contains delocalised electrons.","steps":["Step 1: Many simple molecular substances have relatively low melting points because melting mainly overcomes intermolecular attractions.","Step 2: Diamond is a giant covalent structure with a very high melting temperature because its network contains strong covalent bonds.","Step 3: Diamond does not conduct electricity under ordinary conditions, but graphite conducts because it contains delocalised electrons."],"options":[],"conceptId":"chemistry_chemical_bonding_ionic_and_covalent_structures","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q5","subject":"chemistry","chapter":"chemical_bonding","topic":"Ionic and Covalent Structures"}', 4),
  (3313, 793, 'Define valency in your own words.', 'text', 1, 'Think about what valency tells us when atoms combine.', '{"why":"Valency describes how an atom combines with other atoms when forming compounds.","sol":"Step 1: Recall the meaning of combining capacity.\nStep 2: Explain what valency tells us about an atom when it forms a compound.","steps":["Step 1: Recall the meaning of combining capacity.","Step 2: Explain what valency tells us about an atom when it forms a compound."],"options":[],"conceptId":"chemistry_chemical_formulae_valency","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q1","subject":"chemistry","chapter":"chemical_formulae","topic":"Valency"}', 0),
  (3314, 793, 'State the common valencies of sodium, magnesium and aluminium.', 'text', 1, 'Use the common-valency table in the notes.', '{"why":"These are the common valencies used for these elements in the examples on this screen.","sol":"Step 1: Find sodium (Na) in the table.\nStep 2: Find magnesium (Mg) in the table.\nStep 3: Find aluminium (Al) in the table.","steps":["Step 1: Find sodium (Na) in the table.","Step 2: Find magnesium (Mg) in the table.","Step 3: Find aluminium (Al) in the table."],"options":[],"conceptId":"chemistry_chemical_formulae_valency","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q2","subject":"chemistry","chapter":"chemical_formulae","topic":"Valency"}', 1),
  (3315, 793, 'Oxygen has valency 2 while chlorine has valency 1. Which has the greater numerical valency, and by how much?', 'text', 1, 'Subtract the smaller valency from the larger one.', '{"why":"Oxygen''s valency is 2, while chlorine''s is 1.","sol":"Step 1: Write the valencies: oxygen = 2 and chlorine = 1.\nStep 2: Compare 2 and 1.\nStep 3: Calculate 2 - 1 = 1.","steps":["Step 1: Write the valencies: oxygen = 2 and chlorine = 1.","Step 2: Compare 2 and 1.","Step 3: Calculate 2 - 1 = 1."],"options":[],"conceptId":"chemistry_chemical_formulae_valency","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q3","subject":"chemistry","chapter":"chemical_formulae","topic":"Valency"}', 2),
  (3316, 793, 'Element X has valency 2 and element Y has valency 1. Explain why two atoms of Y are needed to match the combining capacity of one atom of X.', 'text', 1, 'Compare the total combining capacity on both sides.', '{"why":"The ratio balances the combining capacities: one X atom and two Y atoms.","sol":"Step 1: One atom of X has combining capacity 2.\nStep 2: One atom of Y has combining capacity 1.\nStep 3: Two atoms of Y provide a total combining capacity of 2.\nStep 4: The capacities therefore match.","steps":["Step 1: One atom of X has combining capacity 2.","Step 2: One atom of Y has combining capacity 1.","Step 3: Two atoms of Y provide a total combining capacity of 2.","Step 4: The capacities therefore match."],"options":[],"conceptId":"chemistry_chemical_formulae_valency","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q4","subject":"chemistry","chapter":"chemical_formulae","topic":"Valency"}', 3),
  (3317, 793, 'An element has a common valency of 3. Explain what the number 3 tells you about its combining capacity.', 'text', 1, 'Interpret the number rather than naming a compound.', '{"why":"Valency describes combining capacity; it is not simply the number of atoms in a formula.","sol":"Step 1: Identify the given valency as 3.\nStep 2: Recall that valency represents combining capacity.\nStep 3: State the meaning of the value in this context.","steps":["Step 1: Identify the given valency as 3.","Step 2: Recall that valency represents combining capacity.","Step 3: State the meaning of the value in this context."],"options":[],"conceptId":"chemistry_chemical_formulae_valency","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q5","subject":"chemistry","chapter":"chemical_formulae","topic":"Valency"}', 4),
  (3318, 794, 'Explain what the formula H2O tells you about the atoms represented in one water molecule.', 'text', 1, 'Read the subscript after H and remember that O has no written subscript.', '{"why":"A missing subscript means 1; the subscript 2 applies only to hydrogen.","sol":"Step 1: Identify H as hydrogen.\nStep 2: The subscript 2 means two hydrogen atoms.\nStep 3: O has no written subscript, so one oxygen atom is represented.","steps":["Step 1: Identify H as hydrogen.","Step 2: The subscript 2 means two hydrogen atoms.","Step 3: O has no written subscript, so one oxygen atom is represented."],"options":[],"conceptId":"chemistry_chemical_formulae_writing_chemical_formulae","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q1","subject":"chemistry","chapter":"chemical_formulae","topic":"Writing Chemical Formulae"}', 0),
  (3319, 794, 'Magnesium has valency 2 and chlorine has valency 1. Use their combining capacities to write the formula.', 'text', 1, 'One magnesium atom needs two chlorine atoms to match its combining capacity.', '{"why":"One Mg and two Cl atoms give matching combining capacities.","sol":"Step 1: Write Mg and Cl.\nStep 2: One Mg has combining capacity 2.\nStep 3: Each Cl has combining capacity 1, so two Cl atoms are needed.\nStep 4: Write the formula without a subscript after Mg.","steps":["Step 1: Write Mg and Cl.","Step 2: One Mg has combining capacity 2.","Step 3: Each Cl has combining capacity 1, so two Cl atoms are needed.","Step 4: Write the formula without a subscript after Mg."],"options":[],"conceptId":"chemistry_chemical_formulae_writing_chemical_formulae","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q2","subject":"chemistry","chapter":"chemical_formulae","topic":"Writing Chemical Formulae"}', 1),
  (3320, 794, 'Aluminium has valency 3 and oxygen has valency 2. Show how the simplest ratio gives Al2O3.', 'text', 1, 'Find the lowest common multiple of 3 and 2.', '{"why":"The total combining capacities are equal at 6, and the ratio 2 : 3 is already in its simplest whole-number form.","sol":"Step 1: The lowest common multiple of 3 and 2 is 6.\nStep 2: Two aluminium atoms give 2 × 3 = 6.\nStep 3: Three oxygen atoms give 3 × 2 = 6.\nStep 4: Write the ratio 2 : 3 as subscripts.","steps":["Step 1: The lowest common multiple of 3 and 2 is 6.","Step 2: Two aluminium atoms give 2 × 3 = 6.","Step 3: Three oxygen atoms give 3 × 2 = 6.","Step 4: Write the ratio 2 : 3 as subscripts."],"options":[],"conceptId":"chemistry_chemical_formulae_writing_chemical_formulae","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q3","subject":"chemistry","chapter":"chemical_formulae","topic":"Writing Chemical Formulae"}', 2),
  (3321, 794, 'Why is a subscript 1 not written in a chemical formula?', 'text', 1, 'Consider how the number of atoms is shown when no subscript appears.', '{"why":"For example, MgCl2 contains one Mg atom and two Cl atoms.","sol":"Step 1: A subscript shows how many atoms of the preceding element are represented.\nStep 2: When there is no subscript, the number is understood to be 1.\nStep 3: Writing a subscript 1 would therefore be unnecessary.","steps":["Step 1: A subscript shows how many atoms of the preceding element are represented.","Step 2: When there is no subscript, the number is understood to be 1.","Step 3: Writing a subscript 1 would therefore be unnecessary."],"options":[],"conceptId":"chemistry_chemical_formulae_writing_chemical_formulae","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q4","subject":"chemistry","chapter":"chemical_formulae","topic":"Writing Chemical Formulae"}', 3),
  (3322, 794, 'An element P has valency 2 and element Q has valency 3. Find the simplest atom ratio P : Q by balancing their combining capacities, then write a symbolic formula using P and Q.', 'text', 1, 'Find the lowest common multiple of 2 and 3.', '{"why":"Three P atoms and two Q atoms balance the combining capacities at 6 each. P and Q are placeholders for this exercise, not actual element symbols.","sol":"Step 1: The lowest common multiple of 2 and 3 is 6.\nStep 2: Three P atoms provide 3 × 2 = 6.\nStep 3: Two Q atoms provide 2 × 3 = 6.\nStep 4: The simplest ratio P : Q is 3 : 2.","steps":["Step 1: The lowest common multiple of 2 and 3 is 6.","Step 2: Three P atoms provide 3 × 2 = 6.","Step 3: Two Q atoms provide 2 × 3 = 6.","Step 4: The simplest ratio P : Q is 3 : 2."],"options":[],"conceptId":"chemistry_chemical_formulae_writing_chemical_formulae","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q5","subject":"chemistry","chapter":"chemical_formulae","topic":"Writing Chemical Formulae"}', 4),
  (3323, 795, 'Explain why the formula of sodium chloride is NaCl when the ions are Na+ and Cl-.', 'text', 1, 'Add the charges for one sodium ion and one chloride ion.', '{"why":"The formula represents the simplest whole-number ratio of ions in a neutral ionic compound.","sol":"Step 1: Sodium ion has charge +1.\nStep 2: Chloride ion has charge -1.\nStep 3: The total is (+1) + (-1) = 0.\nStep 4: The smallest ratio is one sodium ion to one chloride ion.","steps":["Step 1: Sodium ion has charge +1.","Step 2: Chloride ion has charge -1.","Step 3: The total is (+1) + (-1) = 0.","Step 4: The smallest ratio is one sodium ion to one chloride ion."],"options":[],"conceptId":"chemistry_chemical_formulae_formulae_of_ionic_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q1","subject":"chemistry","chapter":"chemical_formulae","topic":"Formulae of Ionic Compounds"}', 0),
  (3324, 795, 'Write the formula of magnesium oxide using Mg2+ and O2-. Explain why the formula is not Mg2O2.', 'text', 1, 'Check whether one ion of each type already balances the charges.', '{"why":"Ionic formulae show the simplest whole-number ratio of ions, not an unnecessarily doubled ratio.","sol":"Step 1: Mg2+ has charge +2.\nStep 2: O2- has charge -2.\nStep 3: One of each gives a total charge of zero.\nStep 4: The ratio 1 : 1 is already the simplest whole-number ratio.","steps":["Step 1: Mg2+ has charge +2.","Step 2: O2- has charge -2.","Step 3: One of each gives a total charge of zero.","Step 4: The ratio 1 : 1 is already the simplest whole-number ratio."],"options":[],"conceptId":"chemistry_chemical_formulae_formulae_of_ionic_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q2","subject":"chemistry","chapter":"chemical_formulae","topic":"Formulae of Ionic Compounds"}', 1),
  (3325, 795, 'Use Al3+ and O2- to derive the formula of aluminium oxide. Show the total positive and negative charges.', 'text', 1, 'Find the smallest common total for charges of 3 and 2.', '{"why":"The formula is neutral and uses the smallest whole-number ratio that balances the charges.","sol":"Step 1: Two Al3+ ions give 2 × (+3) = +6.\nStep 2: Three O2- ions give 3 × (-2) = -6.\nStep 3: The combined charge is +6 - 6 = 0.\nStep 4: Write the ratio of aluminium ions to oxide ions as 2 : 3.","steps":["Step 1: Two Al3+ ions give 2 × (+3) = +6.","Step 2: Three O2- ions give 3 × (-2) = -6.","Step 3: The combined charge is +6 - 6 = 0.","Step 4: Write the ratio of aluminium ions to oxide ions as 2 : 3."],"options":[],"conceptId":"chemistry_chemical_formulae_formulae_of_ionic_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q3","subject":"chemistry","chapter":"chemical_formulae","topic":"Formulae of Ionic Compounds"}', 2),
  (3326, 795, 'An ionic compound contains Ca2+ ions and Cl- ions. Derive its formula and show how you check that it is neutral.', 'text', 1, 'Each chloride ion contributes a charge of -1.', '{"why":"Two chloride ions are needed to balance the +2 charge on one calcium ion.","sol":"Step 1: One Ca2+ ion contributes +2.\nStep 2: Two Cl- ions contribute 2 × (-1) = -2.\nStep 3: The total charge is +2 - 2 = 0.\nStep 4: Write one calcium ion and two chloride ions as CaCl2.","steps":["Step 1: One Ca2+ ion contributes +2.","Step 2: Two Cl- ions contribute 2 × (-1) = -2.","Step 3: The total charge is +2 - 2 = 0.","Step 4: Write one calcium ion and two chloride ions as CaCl2."],"options":[],"conceptId":"chemistry_chemical_formulae_formulae_of_ionic_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q4","subject":"chemistry","chapter":"chemical_formulae","topic":"Formulae of Ionic Compounds"}', 3),
  (3327, 795, 'A student proposes the formula MgCl for a compound made from Mg2+ and Cl-. Identify the error and give the correct formula with a charge check.', 'text', 1, 'Calculate the total charge represented by one Mg2+ and one Cl-.', '{"why":"An ionic compound''s formula must balance the total positive and negative charges.","sol":"Step 1: One Mg2+ ion contributes +2.\nStep 2: One Cl- ion contributes -1.\nStep 3: The proposed combination has a total charge of +1, so it is not neutral.\nStep 4: Two chloride ions contribute -2 and balance one magnesium ion''s +2 charge.","steps":["Step 1: One Mg2+ ion contributes +2.","Step 2: One Cl- ion contributes -1.","Step 3: The proposed combination has a total charge of +1, so it is not neutral.","Step 4: Two chloride ions contribute -2 and balance one magnesium ion''s +2 charge."],"options":[],"conceptId":"chemistry_chemical_formulae_formulae_of_ionic_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q5","subject":"chemistry","chapter":"chemical_formulae","topic":"Formulae of Ionic Compounds"}', 4),
  (3328, 796, 'Explain what the formula H2O tells you about the numbers of hydrogen and oxygen atoms in one molecule.', 'text', 1, 'Read the subscript after H and check whether O has a subscript.', '{"why":"Subscripts show the number of atoms of the element immediately before them; no subscript means one.","sol":"Step 1: H represents hydrogen and has subscript 2.\nStep 2: Therefore, the molecule contains two hydrogen atoms.\nStep 3: O represents oxygen and has no written subscript.\nStep 4: Therefore, the molecule contains one oxygen atom.","steps":["Step 1: H represents hydrogen and has subscript 2.","Step 2: Therefore, the molecule contains two hydrogen atoms.","Step 3: O represents oxygen and has no written subscript.","Step 4: Therefore, the molecule contains one oxygen atom."],"options":[],"conceptId":"chemistry_chemical_formulae_formulae_of_covalent_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q1","subject":"chemistry","chapter":"chemical_formulae","topic":"Formulae of Covalent Compounds"}', 0),
  (3329, 796, 'A molecule has the formula CO2. State the number of carbon atoms, the number of oxygen atoms and the total number of atoms.', 'text', 1, 'Count each element separately before adding the numbers.', '{"why":"The total is found by adding the counts of all atoms represented in the formula.","sol":"Step 1: C has no subscript, so there is one carbon atom.\nStep 2: O has subscript 2, so there are two oxygen atoms.\nStep 3: Add the counts: 1 + 2 = 3.","steps":["Step 1: C has no subscript, so there is one carbon atom.","Step 2: O has subscript 2, so there are two oxygen atoms.","Step 3: Add the counts: 1 + 2 = 3."],"options":[],"conceptId":"chemistry_chemical_formulae_formulae_of_covalent_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q2","subject":"chemistry","chapter":"chemical_formulae","topic":"Formulae of Covalent Compounds"}', 1),
  (3330, 796, 'Write the formula representing a molecule containing one nitrogen atom and three hydrogen atoms.', 'text', 1, 'Use N for nitrogen and H for hydrogen. Remember that a subscript of 1 is omitted.', '{"why":"The formula represents one nitrogen atom and three hydrogen atoms.","sol":"Step 1: Write N for one nitrogen atom.\nStep 2: Write H for hydrogen.\nStep 3: Place subscript 3 after H to show three hydrogen atoms.\nStep 4: Do not add a subscript after N because its count is one.","steps":["Step 1: Write N for one nitrogen atom.","Step 2: Write H for hydrogen.","Step 3: Place subscript 3 after H to show three hydrogen atoms.","Step 4: Do not add a subscript after N because its count is one."],"options":[],"conceptId":"chemistry_chemical_formulae_formulae_of_covalent_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q3","subject":"chemistry","chapter":"chemical_formulae","topic":"Formulae of Covalent Compounds"}', 2),
  (3331, 796, 'A student says that CO2 contains two carbon atoms and one oxygen atom. Identify the mistake and give the correct interpretation.', 'text', 1, 'Check which symbol is immediately before the subscript 2.', '{"why":"A subscript applies to the element symbol immediately before it.","sol":"Step 1: Identify the symbol before the subscript 2.\nStep 2: The subscript follows O, not C.\nStep 3: C has no subscript, so its count is one.\nStep 4: O has subscript 2, so its count is two.","steps":["Step 1: Identify the symbol before the subscript 2.","Step 2: The subscript follows O, not C.","Step 3: C has no subscript, so its count is one.","Step 4: O has subscript 2, so its count is two."],"options":[],"conceptId":"chemistry_chemical_formulae_formulae_of_covalent_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q4","subject":"chemistry","chapter":"chemical_formulae","topic":"Formulae of Covalent Compounds"}', 3),
  (3332, 796, 'A molecule is specified to contain two carbon atoms, four hydrogen atoms and one oxygen atom. Write the formula using the symbols C, H and O, and calculate the total number of atoms.', 'text', 1, 'Write each element symbol with its stated count as a subscript, omitting a subscript of 1.', '{"why":"The formula follows the specified atom counts. This construction exercise does not, by itself, establish the identity or stability of a particular compound.","sol":"Step 1: Two carbon atoms are represented by C2.\nStep 2: Four hydrogen atoms are represented by H4.\nStep 3: One oxygen atom is represented by O, with no subscript.\nStep 4: Combine the symbols in the stated order: C2H4O.\nStep 5: Add the counts: 2 + 4 + 1 = 7.","steps":["Step 1: Two carbon atoms are represented by C2.","Step 2: Four hydrogen atoms are represented by H4.","Step 3: One oxygen atom is represented by O, with no subscript.","Step 4: Combine the symbols in the stated order: C2H4O.","Step 5: Add the counts: 2 + 4 + 1 = 7."],"options":[],"conceptId":"chemistry_chemical_formulae_formulae_of_covalent_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q5","subject":"chemistry","chapter":"chemical_formulae","topic":"Formulae of Covalent Compounds"}', 4),
  (3333, 797, 'Name the ionic compound NaCl and explain how you obtained the name.', 'text', 1, 'Name the positive ion first, followed by the negative ion.', '{"why":"Simple ionic compounds are named by stating the positive ion first and then the negative ion.","sol":"Step 1: Na represents sodium.\nStep 2: Cl represents chlorine, whose negative ion is called chloride.\nStep 3: Write the positive-ion name first.\nStep 4: Follow it with the negative-ion name.","steps":["Step 1: Na represents sodium.","Step 2: Cl represents chlorine, whose negative ion is called chloride.","Step 3: Write the positive-ion name first.","Step 4: Follow it with the negative-ion name."],"options":[],"conceptId":"chemistry_chemical_formulae_naming_ionic_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q1","subject":"chemistry","chapter":"chemical_formulae","topic":"Naming Ionic Compounds"}', 0),
  (3334, 797, 'Name MgO and identify the names of its positive and negative ions.', 'text', 1, 'The negative ion formed from oxygen is called oxide.', '{"why":"The name follows the positive-ion-first rule.","sol":"Step 1: Mg represents magnesium.\nStep 2: O represents oxygen.\nStep 3: The positive ion is magnesium; the negative ion is oxide.\nStep 4: Combine the names in that order.","steps":["Step 1: Mg represents magnesium.","Step 2: O represents oxygen.","Step 3: The positive ion is magnesium; the negative ion is oxide.","Step 4: Combine the names in that order."],"options":[],"conceptId":"chemistry_chemical_formulae_naming_ionic_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q2","subject":"chemistry","chapter":"chemical_formulae","topic":"Naming Ionic Compounds"}', 1),
  (3335, 797, 'Give the correct name for CaCl2. Explain why the subscript 2 does not make the name calcium dichloride.', 'text', 1, 'Distinguish the naming rule for simple ionic compounds from the use of prefixes in covalent compounds.', '{"why":"The subscript describes the ion ratio, but the simple ionic compound is named calcium chloride.","sol":"Step 1: Ca represents calcium.\nStep 2: Cl represents the chloride ion.\nStep 3: The subscript 2 shows two chloride ions for each calcium ion.\nStep 4: Simple ionic compounds are not normally named using covalent prefixes such as di-.","steps":["Step 1: Ca represents calcium.","Step 2: Cl represents the chloride ion.","Step 3: The subscript 2 shows two chloride ions for each calcium ion.","Step 4: Simple ionic compounds are not normally named using covalent prefixes such as di-."],"options":[],"conceptId":"chemistry_chemical_formulae_naming_ionic_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q3","subject":"chemistry","chapter":"chemical_formulae","topic":"Naming Ionic Compounds"}', 2),
  (3336, 797, 'Name Al2O3 and state which part of its name comes from aluminium and which part comes from oxygen.', 'text', 1, 'Use the negative-ion name for oxygen.', '{"why":"The name reflects the positive and negative ions present in the compound.","sol":"Step 1: Al represents aluminium.\nStep 2: O represents oxygen; its negative-ion name is oxide.\nStep 3: Write aluminium first and oxide second.","steps":["Step 1: Al represents aluminium.","Step 2: O represents oxygen; its negative-ion name is oxide.","Step 3: Write aluminium first and oxide second."],"options":[],"conceptId":"chemistry_chemical_formulae_naming_ionic_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q4","subject":"chemistry","chapter":"chemical_formulae","topic":"Naming Ionic Compounds"}', 3),
  (3337, 797, 'A student names NaCl as chlorine sodium. Identify the error and give the correct name with an explanation.', 'text', 1, 'Remember the order in which the ions are named.', '{"why":"The positive ion is named first, and the name of the simple negative ion changes to chloride.","sol":"Step 1: Identify Na as the positive ion.\nStep 2: Identify Cl as the negative ion.\nStep 3: The positive ion must be named first.\nStep 4: Use chloride rather than chlorine for the negative ion''s name.","steps":["Step 1: Identify Na as the positive ion.","Step 2: Identify Cl as the negative ion.","Step 3: The positive ion must be named first.","Step 4: Use chloride rather than chlorine for the negative ion''s name."],"options":[],"conceptId":"chemistry_chemical_formulae_naming_ionic_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q5","subject":"chemistry","chapter":"chemical_formulae","topic":"Naming Ionic Compounds"}', 4),
  (3338, 798, 'Name CO2 and explain how its formula determines the name.', 'text', 1, 'Count the carbon and oxygen atoms separately.', '{"why":"The prefix di- indicates two oxygen atoms, while mono- is omitted for the single first-element atom.","sol":"Step 1: C represents carbon and has no subscript, so there is one carbon atom.\nStep 2: O has subscript 2, so there are two oxygen atoms.\nStep 3: Omit mono- for the first element.\nStep 4: Use di- and oxide for the second element.","steps":["Step 1: C represents carbon and has no subscript, so there is one carbon atom.","Step 2: O has subscript 2, so there are two oxygen atoms.","Step 3: Omit mono- for the first element.","Step 4: Use di- and oxide for the second element."],"options":[],"conceptId":"chemistry_chemical_formulae_naming_covalent_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q1","subject":"chemistry","chapter":"chemical_formulae","topic":"Naming Covalent Compounds"}', 0),
  (3339, 798, 'Explain the difference between the names carbon monoxide and carbon dioxide by referring to their formulae.', 'text', 1, 'Compare CO with CO2.', '{"why":"The prefixes distinguish molecular formulae with different numbers of oxygen atoms.","sol":"Step 1: CO contains one carbon atom and one oxygen atom.\nStep 2: CO2 contains one carbon atom and two oxygen atoms.\nStep 3: The name monoxide indicates one oxygen atom.\nStep 4: The name dioxide indicates two oxygen atoms.","steps":["Step 1: CO contains one carbon atom and one oxygen atom.","Step 2: CO2 contains one carbon atom and two oxygen atoms.","Step 3: The name monoxide indicates one oxygen atom.","Step 4: The name dioxide indicates two oxygen atoms."],"options":[],"conceptId":"chemistry_chemical_formulae_naming_covalent_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q2","subject":"chemistry","chapter":"chemical_formulae","topic":"Naming Covalent Compounds"}', 1),
  (3340, 798, 'Name N2O3 and show how each prefix is selected.', 'text', 1, 'Read the subscript after N and then the subscript after O.', '{"why":"Di- represents two nitrogen atoms, and tri- represents three oxygen atoms.","sol":"Step 1: N2 represents two nitrogen atoms, so use di- with nitrogen.\nStep 2: O3 represents three oxygen atoms, so use tri- with oxide.\nStep 3: Combine the names in the order of the formula.","steps":["Step 1: N2 represents two nitrogen atoms, so use di- with nitrogen.","Step 2: O3 represents three oxygen atoms, so use tri- with oxide.","Step 3: Combine the names in the order of the formula."],"options":[],"conceptId":"chemistry_chemical_formulae_naming_covalent_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q3","subject":"chemistry","chapter":"chemical_formulae","topic":"Naming Covalent Compounds"}', 2),
  (3341, 798, 'Write the molecular formula represented by the name dinitrogen monoxide, then explain the atom counts.', 'text', 1, 'Di- means two; mono- means one.', '{"why":"The prefixes in the name state the number of atoms of each element.","sol":"Step 1: Dinitrogen means two nitrogen atoms, written N2.\nStep 2: Monoxide means one oxygen atom, written O.\nStep 3: Combine the symbols and subscripts.","steps":["Step 1: Dinitrogen means two nitrogen atoms, written N2.","Step 2: Monoxide means one oxygen atom, written O.","Step 3: Combine the symbols and subscripts."],"options":[],"conceptId":"chemistry_chemical_formulae_naming_covalent_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q4","subject":"chemistry","chapter":"chemical_formulae","topic":"Naming Covalent Compounds"}', 3),
  (3342, 798, 'A student calls CO2 carbon monooxide. Identify the naming error and give the correct name.', 'text', 1, 'The formula contains two oxygen atoms, not one.', '{"why":"The prefix must match the number of oxygen atoms shown by the subscript.","sol":"Step 1: Read the subscript after O in CO2.\nStep 2: The subscript 2 indicates two oxygen atoms.\nStep 3: Use di- rather than mono- for the oxygen count.\nStep 4: Name the compound carbon dioxide.","steps":["Step 1: Read the subscript after O in CO2.","Step 2: The subscript 2 indicates two oxygen atoms.","Step 3: Use di- rather than mono- for the oxygen count.","Step 4: Name the compound carbon dioxide."],"options":[],"conceptId":"chemistry_chemical_formulae_naming_covalent_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q5","subject":"chemistry","chapter":"chemical_formulae","topic":"Naming Covalent Compounds"}', 4),
  (3343, 799, 'What does the state symbol (s) mean in NaCl(s)?', 'text', 1, 'Read the state-symbol table.', '{"why":"The formula identifies sodium chloride, and (s) tells you its physical state.","sol":"Step 1: Identify the symbol in brackets: (s).\nStep 2: Recall that (s) represents the solid state.\nStep 3: Apply it to the substance NaCl.","steps":["Step 1: Identify the symbol in brackets: (s).","Step 2: Recall that (s) represents the solid state.","Step 3: Apply it to the substance NaCl."],"options":[],"conceptId":"chemistry_chemical_formulae_state_symbols","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q1","subject":"chemistry","chapter":"chemical_formulae","topic":"State Symbols"}', 0),
  (3344, 799, 'Explain the meaning of H2O(l) and identify what the symbol in brackets tells you.', 'text', 1, 'H2O is water; interpret the letter l.', '{"why":"The state symbol gives the physical state of the substance.","sol":"Step 1: Identify H2O as water.\nStep 2: Read the state symbol (l).\nStep 3: The letter l represents the liquid state.","steps":["Step 1: Identify H2O as water.","Step 2: Read the state symbol (l).","Step 3: The letter l represents the liquid state."],"options":[],"conceptId":"chemistry_chemical_formulae_state_symbols","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q2","subject":"chemistry","chapter":"chemical_formulae","topic":"State Symbols"}', 1),
  (3345, 799, 'What does CO2(g) represent, and what information does (g) add to the formula?', 'text', 1, 'Identify the meaning of g in the state-symbol table.', '{"why":"The state symbol adds the physical-state information that the formula alone does not provide.","sol":"Step 1: CO2 represents carbon dioxide.\nStep 2: The symbol (g) means gas.\nStep 3: Combine the formula and the state information.","steps":["Step 1: CO2 represents carbon dioxide.","Step 2: The symbol (g) means gas.","Step 3: Combine the formula and the state information."],"options":[],"conceptId":"chemistry_chemical_formulae_state_symbols","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q3","subject":"chemistry","chapter":"chemical_formulae","topic":"State Symbols"}', 2),
  (3346, 799, 'Explain the difference between NaCl(l) and NaCl(aq).', 'text', 1, 'Compare the meanings of liquid and aqueous.', '{"why":"Aqueous describes a solution in water; it is not another way of writing liquid.","sol":"Step 1: The symbol (l) means the substance itself is in the liquid state.\nStep 2: The symbol (aq) means the substance is dissolved in water.\nStep 3: State the distinction between the two descriptions.","steps":["Step 1: The symbol (l) means the substance itself is in the liquid state.","Step 2: The symbol (aq) means the substance is dissolved in water.","Step 3: State the distinction between the two descriptions."],"options":[],"conceptId":"chemistry_chemical_formulae_state_symbols","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q4","subject":"chemistry","chapter":"chemical_formulae","topic":"State Symbols"}', 3),
  (3347, 799, 'Write the correct state symbol for each description: solid sodium chloride, carbon dioxide gas, and sodium chloride dissolved in water.', 'text', 1, 'Choose from (s), (g) and (aq).', '{"why":"Each state symbol communicates a different physical-state description.","sol":"Step 1: Solid sodium chloride uses (s): NaCl(s).\nStep 2: Carbon dioxide gas uses (g): CO2(g).\nStep 3: Sodium chloride dissolved in water uses (aq): NaCl(aq).","steps":["Step 1: Solid sodium chloride uses (s): NaCl(s).","Step 2: Carbon dioxide gas uses (g): CO2(g).","Step 3: Sodium chloride dissolved in water uses (aq): NaCl(aq)."],"options":[],"conceptId":"chemistry_chemical_formulae_state_symbols","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q5","subject":"chemistry","chapter":"chemical_formulae","topic":"State Symbols"}', 4),
  (3348, 800, 'Explain what is meant by one mole of a substance.', 'text', 1, 'Focus on the core principle of Meaning of Mole.', '{"why":"The mole gives chemists a practical way to describe extremely large numbers of particles.","sol":"Step 1: Identify the mole as a unit of amount of substance.\nStep 2: Recall that one mole contains a fixed number of specified entities.\nStep 3: State the school approximation for this number: 6.02 × 10²³.\nStep 4: Include the type of entity being counted, such as atoms, molecules or ions.","steps":["Step 1: Identify the mole as a unit of amount of substance.","Step 2: Recall that one mole contains a fixed number of specified entities.","Step 3: State the school approximation for this number: 6.02 × 10²³.","Step 4: Include the type of entity being counted, such as atoms, molecules or ions."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_meaning_of_mole","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q1","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Meaning of Mole"}', 0),
  (3349, 800, 'How many water molecules are present in 1 mol of H₂O?', 'text', 1, 'Focus on the core principle of Meaning of Mole.', '{"why":"The identity of the substance changes the type of particle being counted, not the number of entities in one mole.","sol":"Step 1: Identify the entities as water molecules.\nStep 2: One mole contains 6.02 × 10²³ specified entities.\nStep 3: Apply this number to the water molecules.\nStep 4: The number of water molecules is 6.02 × 10²³.","steps":["Step 1: Identify the entities as water molecules.","Step 2: One mole contains 6.02 × 10²³ specified entities.","Step 3: Apply this number to the water molecules.","Step 4: The number of water molecules is 6.02 × 10²³."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_meaning_of_mole","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q2","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Meaning of Mole"}', 1),
  (3350, 800, 'Explain why 1 mol of carbon atoms and 1 mol of water molecules can have different masses.', 'text', 1, 'Focus on the core principle of Meaning of Mole.', '{"why":"Amount of substance and mass are related quantities, but they are not the same quantity.","sol":"Step 1: Both amounts contain 6.02 × 10²³ specified entities.\nStep 2: A carbon atom has a different mass from a water molecule.\nStep 3: The total mass depends on the mass of each entity and how many entities are present.\nStep 4: Therefore, equal amounts in moles do not necessarily have equal masses.","steps":["Step 1: Both amounts contain 6.02 × 10²³ specified entities.","Step 2: A carbon atom has a different mass from a water molecule.","Step 3: The total mass depends on the mass of each entity and how many entities are present.","Step 4: Therefore, equal amounts in moles do not necessarily have equal masses."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_meaning_of_mole","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q3","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Meaning of Mole"}', 2),
  (3351, 800, 'How many helium atoms are present in 1 mol of helium?', 'text', 1, 'Identify the particle and apply the definition of a mole.', '{"why":"One mole of any specified entity contains the Avogadro constant number of those entities.","sol":"Step 1: Helium is being counted as atoms.\nStep 2: One mole contains 6.02 × 10²³ specified entities.\nStep 3: Therefore, the sample contains 6.02 × 10²³ helium atoms.","steps":["Step 1: Helium is being counted as atoms.","Step 2: One mole contains 6.02 × 10²³ specified entities.","Step 3: Therefore, the sample contains 6.02 × 10²³ helium atoms."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_meaning_of_mole","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q4","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Meaning of Mole"}', 3),
  (3352, 800, 'A sample contains 1 mol of CO₂. How many carbon dioxide molecules does it contain?', 'text', 1, 'The entity specified by CO₂ in this question is a molecule.', '{"why":"The formula identifies the molecule being counted; one mole still represents the same fixed number of molecules.","sol":"Step 1: Identify the entity as a CO₂ molecule.\nStep 2: One mole contains 6.02 × 10²³ specified entities.\nStep 3: Apply the definition to CO₂ molecules.","steps":["Step 1: Identify the entity as a CO₂ molecule.","Step 2: One mole contains 6.02 × 10²³ specified entities.","Step 3: Apply the definition to CO₂ molecules."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_meaning_of_mole","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q5","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Meaning of Mole"}', 4),
  (3353, 800, 'A learner claims that 1 mol of oxygen atoms contains the same number of atoms as 1 mol of O₂ molecules. Is the claim correct? Explain.', 'text', 1, 'Distinguish the number of molecules from the number of atoms inside each molecule.', '{"why":"The number of molecules and the number of atoms are different counts when each molecule contains more than one atom.","sol":"Step 1: One mole of oxygen atoms contains 6.02 × 10²³ oxygen atoms.\nStep 2: One mole of O₂ contains 6.02 × 10²³ O₂ molecules.\nStep 3: Each O₂ molecule contains two oxygen atoms.\nStep 4: Total oxygen atoms in 1 mol O₂ = 2 × 6.02 × 10²³.\nStep 5: This equals 1.204 × 10²⁴ oxygen atoms.","steps":["Step 1: One mole of oxygen atoms contains 6.02 × 10²³ oxygen atoms.","Step 2: One mole of O₂ contains 6.02 × 10²³ O₂ molecules.","Step 3: Each O₂ molecule contains two oxygen atoms.","Step 4: Total oxygen atoms in 1 mol O₂ = 2 × 6.02 × 10²³.","Step 5: This equals 1.204 × 10²⁴ oxygen atoms."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_meaning_of_mole","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q6","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Meaning of Mole"}', 5),
  (3354, 800, 'State the number of sodium ions in 1 mol of Na⁺ ions.', 'text', 1, 'The specified entity is an ion, not a neutral sodium atom.', '{"why":"The electrical charge does not change the number of ions represented by one mole.","sol":"Step 1: Identify the entity as Na⁺ ions.\nStep 2: One mole contains 6.02 × 10²³ specified entities.\nStep 3: Therefore, there are 6.02 × 10²³ sodium ions.","steps":["Step 1: Identify the entity as Na⁺ ions.","Step 2: One mole contains 6.02 × 10²³ specified entities.","Step 3: Therefore, there are 6.02 × 10²³ sodium ions."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_meaning_of_mole","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q7","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Meaning of Mole"}', 6),
  (3355, 800, 'Explain the difference between the mole and the gram.', 'text', 1, 'One measures amount of substance; the other measures mass.', '{"why":"Confusing the two quantities leads to incorrect mole calculations.","sol":"Step 1: The mole measures amount of substance.\nStep 2: The gram is a unit of mass.\nStep 3: The mass of one mole depends on the substance.\nStep 4: Therefore, a mole cannot be treated as a fixed mass of one gram.","steps":["Step 1: The mole measures amount of substance.","Step 2: The gram is a unit of mass.","Step 3: The mass of one mole depends on the substance.","Step 4: Therefore, a mole cannot be treated as a fixed mass of one gram."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_meaning_of_mole","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q8","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Meaning of Mole"}', 7),
  (3356, 800, 'One mole of a substance contains 6.02 × 10²³ molecules. How many molecules would be present in 2 mol of the same substance? Explain your reasoning.', 'text', 1, 'Two moles contain twice the number of molecules in one mole.', '{"why":"The number of specified particles is directly proportional to the amount in moles.","sol":"Step 1: One mole contains 6.02 × 10²³ molecules.\nStep 2: Two moles contain 2 × 6.02 × 10²³ molecules.\nStep 3: Multiply the numerical values: 2 × 6.02 = 12.04.\nStep 4: Write the result in standard form: 1.204 × 10²⁴ molecules.","steps":["Step 1: One mole contains 6.02 × 10²³ molecules.","Step 2: Two moles contain 2 × 6.02 × 10²³ molecules.","Step 3: Multiply the numerical values: 2 × 6.02 = 12.04.","Step 4: Write the result in standard form: 1.204 × 10²⁴ molecules."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_meaning_of_mole","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q9","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Meaning of Mole"}', 8),
  (3357, 801, 'Calculate the number of particles in 2 mol of a substance.', 'text', 1, 'Focus on the core principle of Avogadro Constant.', '{"why":"Two moles contain twice the number of particles in one mole.","sol":"Step 1: Use N = n × Nₐ.\nStep 2: n = 2 mol and Nₐ = 6.02 × 10²³ mol⁻¹.\nStep 3: N = 2 × 6.02 × 10²³.\nStep 4: N = 12.04 × 10²³.\nStep 5: Convert to standard form: N = 1.204 × 10²⁴.","steps":["Step 1: Use N = n × Nₐ.","Step 2: n = 2 mol and Nₐ = 6.02 × 10²³ mol⁻¹.","Step 3: N = 2 × 6.02 × 10²³.","Step 4: N = 12.04 × 10²³.","Step 5: Convert to standard form: N = 1.204 × 10²⁴."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_avogadro_constant","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q1","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Avogadro Constant"}', 0),
  (3358, 801, 'Calculate the number of moles represented by 3.01 × 10²³ molecules.', 'text', 1, 'Focus on the core principle of Avogadro Constant.', '{"why":"3.01 × 10²³ is half of the Avogadro constant number of entities.","sol":"Step 1: Use n = N ÷ Nₐ.\nStep 2: Substitute n = (3.01 × 10²³) ÷ (6.02 × 10²³).\nStep 3: Cancel the equal powers of ten.\nStep 4: n = 3.01 ÷ 6.02 = 0.5 mol.","steps":["Step 1: Use n = N ÷ Nₐ.","Step 2: Substitute n = (3.01 × 10²³) ÷ (6.02 × 10²³).","Step 3: Cancel the equal powers of ten.","Step 4: n = 3.01 ÷ 6.02 = 0.5 mol."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_avogadro_constant","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q2","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Avogadro Constant"}', 1),
  (3359, 801, 'Calculate the number of atoms in 0.25 mol of an element.', 'text', 1, 'Focus on the core principle of Avogadro Constant.', '{"why":"A quarter of a mole contains one-quarter of the Avogadro constant number of atoms.","sol":"Step 1: Use N = n × Nₐ.\nStep 2: N = 0.25 × 6.02 × 10²³.\nStep 3: 0.25 × 6.02 = 1.505.\nStep 4: N = 1.505 × 10²³ atoms.","steps":["Step 1: Use N = n × Nₐ.","Step 2: N = 0.25 × 6.02 × 10²³.","Step 3: 0.25 × 6.02 = 1.505.","Step 4: N = 1.505 × 10²³ atoms."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_avogadro_constant","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q3","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Avogadro Constant"}', 2),
  (3360, 801, 'Calculate the number of molecules in 0.75 mol of oxygen gas, O₂.', 'text', 1, 'Use N = n × Nₐ.', '{"why":"Multiplying the amount in moles by the Avogadro constant gives the number of molecules.","sol":"Step 1: The amount is 0.75 mol.\nStep 2: Use N = 0.75 × 6.02 × 10²³.\nStep 3: Multiply 0.75 × 6.02 = 4.515.\nStep 4: N = 4.515 × 10²³ molecules.","steps":["Step 1: The amount is 0.75 mol.","Step 2: Use N = 0.75 × 6.02 × 10²³.","Step 3: Multiply 0.75 × 6.02 = 4.515.","Step 4: N = 4.515 × 10²³ molecules."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_avogadro_constant","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q4","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Avogadro Constant"}', 3),
  (3361, 801, 'Calculate the amount of substance in 1.505 × 10²⁴ atoms.', 'text', 1, 'Divide the number of atoms by 6.02 × 10²³.', '{"why":"The particle count is 2.5 times the Avogadro constant.","sol":"Step 1: Use n = N ÷ Nₐ.\nStep 2: n = (1.505 × 10²⁴) ÷ (6.02 × 10²³).\nStep 3: Separate the numbers and powers: n = (1.505 ÷ 6.02) × 10.\nStep 4: 1.505 ÷ 6.02 = 0.25.\nStep 5: n = 0.25 × 10 = 2.5 mol.","steps":["Step 1: Use n = N ÷ Nₐ.","Step 2: n = (1.505 × 10²⁴) ÷ (6.02 × 10²³).","Step 3: Separate the numbers and powers: n = (1.505 ÷ 6.02) × 10.","Step 4: 1.505 ÷ 6.02 = 0.25.","Step 5: n = 0.25 × 10 = 2.5 mol."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_avogadro_constant","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q5","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Avogadro Constant"}', 4),
  (3362, 801, 'A sample contains 0.20 mol of sodium ions. Calculate the number of sodium ions present.', 'text', 1, 'The charge does not change the mole-to-particle relationship.', '{"why":"The formula counts the specified ions, irrespective of their charge.","sol":"Step 1: Use N = n × Nₐ.\nStep 2: N = 0.20 × 6.02 × 10²³.\nStep 3: 0.20 × 6.02 = 1.204.\nStep 4: N = 1.204 × 10²³ sodium ions.","steps":["Step 1: Use N = n × Nₐ.","Step 2: N = 0.20 × 6.02 × 10²³.","Step 3: 0.20 × 6.02 = 1.204.","Step 4: N = 1.204 × 10²³ sodium ions."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_avogadro_constant","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q6","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Avogadro Constant"}', 5),
  (3363, 801, 'A sample contains 4.816 × 10²⁴ molecules. Calculate the number of moles.', 'text', 1, 'Use n = N ÷ Nₐ and divide the numerical values carefully.', '{"why":"The sample contains eight times the Avogadro constant number of molecules.","sol":"Step 1: n = (4.816 × 10²⁴) ÷ (6.02 × 10²³).\nStep 2: Separate the powers of ten: n = (4.816 ÷ 6.02) × 10.\nStep 3: 4.816 ÷ 6.02 = 0.8.\nStep 4: n = 0.8 × 10 = 8 mol.","steps":["Step 1: n = (4.816 × 10²⁴) ÷ (6.02 × 10²³).","Step 2: Separate the powers of ten: n = (4.816 ÷ 6.02) × 10.","Step 3: 4.816 ÷ 6.02 = 0.8.","Step 4: n = 0.8 × 10 = 8 mol."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_avogadro_constant","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q7","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Avogadro Constant"}', 6),
  (3364, 801, 'A learner calculates the number of particles in 0.5 mol by dividing 0.5 by 6.02 × 10²³. Identify the error and calculate the correct answer.', 'text', 1, 'Ask whether the question gives moles or particles.', '{"why":"Multiplication converts moles to particles; division converts particles to moles.","sol":"Step 1: The given quantity is moles and the required quantity is particles.\nStep 2: Therefore, multiply by the Avogadro constant instead of dividing.\nStep 3: N = 0.5 × 6.02 × 10²³.\nStep 4: N = 3.01 × 10²³ particles.","steps":["Step 1: The given quantity is moles and the required quantity is particles.","Step 2: Therefore, multiply by the Avogadro constant instead of dividing.","Step 3: N = 0.5 × 6.02 × 10²³.","Step 4: N = 3.01 × 10²³ particles."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_avogadro_constant","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q8","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Avogadro Constant"}', 7),
  (3365, 801, 'A sample contains 1.204 × 10²⁴ molecules of a compound. Explain how you would find its amount in moles, then calculate it.', 'text', 1, 'Use the Avogadro constant as the number of molecules in one mole.', '{"why":"Dividing by the number of molecules in one mole converts the total molecule count into amount of substance.","sol":"Step 1: Write n = N ÷ Nₐ.\nStep 2: Substitute n = (1.204 × 10²⁴) ÷ (6.02 × 10²³).\nStep 3: Separate the powers: n = (1.204 ÷ 6.02) × 10.\nStep 4: 1.204 ÷ 6.02 = 0.2.\nStep 5: n = 0.2 × 10 = 2 mol.","steps":["Step 1: Write n = N ÷ Nₐ.","Step 2: Substitute n = (1.204 × 10²⁴) ÷ (6.02 × 10²³).","Step 3: Separate the powers: n = (1.204 ÷ 6.02) × 10.","Step 4: 1.204 ÷ 6.02 = 0.2.","Step 5: n = 0.2 × 10 = 2 mol."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_avogadro_constant","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q9","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Avogadro Constant"}', 8),
  (3366, 802, 'Define relative atomic mass.', 'text', 1, 'Focus on the core principle of Relative Atomic Mass.', '{"why":"This definition accounts for the naturally occurring isotopes of an element.","sol":"Step 1: Recognise that atomic masses are compared with a standard reference.\nStep 2: The reference is one-twelfth of the mass of a carbon-12 atom.\nStep 3: Relative atomic mass is the weighted mean mass of an element''s atoms compared with this reference.","steps":["Step 1: Recognise that atomic masses are compared with a standard reference.","Step 2: The reference is one-twelfth of the mass of a carbon-12 atom.","Step 3: Relative atomic mass is the weighted mean mass of an element''s atoms compared with this reference."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_relative_atomic_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q1","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Relative Atomic Mass"}', 0),
  (3367, 802, 'State the commonly used relative atomic mass of sodium.', 'text', 1, 'Focus on the core principle of Relative Atomic Mass.', '{"why":"The common school value for sodium is 23 and has no unit.","sol":"Step 1: Identify the element as sodium, Na.\nStep 2: Use the common school periodic-table value.\nStep 3: Aᵣ(Na) = 23.","steps":["Step 1: Identify the element as sodium, Na.","Step 2: Use the common school periodic-table value.","Step 3: Aᵣ(Na) = 23."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_relative_atomic_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q2","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Relative Atomic Mass"}', 1),
  (3368, 802, 'Explain why the relative atomic mass of chlorine is approximately 35.5 rather than exactly 35 or 37.', 'text', 1, 'Focus on the core principle of Relative Atomic Mass.', '{"why":"A weighted average of different isotope masses need not be a whole number.","sol":"Step 1: Natural chlorine contains more than one isotope.\nStep 2: The main isotopes are chlorine-35 and chlorine-37.\nStep 3: The relative atomic mass is a weighted average based on isotope abundances.\nStep 4: The resulting average is approximately 35.5.","steps":["Step 1: Natural chlorine contains more than one isotope.","Step 2: The main isotopes are chlorine-35 and chlorine-37.","Step 3: The relative atomic mass is a weighted average based on isotope abundances.","Step 4: The resulting average is approximately 35.5."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_relative_atomic_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q3","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Relative Atomic Mass"}', 2),
  (3369, 802, 'State the commonly used relative atomic mass of oxygen and explain whether it has a unit.', 'text', 1, 'Relative atomic mass is a comparison of masses.', '{"why":"Relative atomic mass is dimensionless because it compares one mass with another.","sol":"Step 1: The common school value for oxygen is 16.\nStep 2: Relative atomic mass is a ratio of masses.\nStep 3: The units cancel in a ratio.\nStep 4: Therefore, the value is 16 with no unit.","steps":["Step 1: The common school value for oxygen is 16.","Step 2: Relative atomic mass is a ratio of masses.","Step 3: The units cancel in a ratio.","Step 4: Therefore, the value is 16 with no unit."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_relative_atomic_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q4","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Relative Atomic Mass"}', 3),
  (3370, 802, 'Calculate the combined relative mass contribution of the oxygen atoms in CO₂. Use Aᵣ(O) = 16.', 'text', 1, 'Read the subscript after O.', '{"why":"Each atom represented in the formula contributes its relative atomic mass to the total.","sol":"Step 1: CO₂ contains two oxygen atoms.\nStep 2: Each oxygen atom has a relative atomic mass of 16.\nStep 3: Total oxygen contribution = 2 × 16.\nStep 4: Total oxygen contribution = 32.","steps":["Step 1: CO₂ contains two oxygen atoms.","Step 2: Each oxygen atom has a relative atomic mass of 16.","Step 3: Total oxygen contribution = 2 × 16.","Step 4: Total oxygen contribution = 32."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_relative_atomic_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q5","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Relative Atomic Mass"}', 4),
  (3371, 802, 'A learner writes Aᵣ(Cl) = 35.5 g. Explain why the unit is incorrect.', 'text', 1, 'Ask whether relative atomic mass is a measured mass or a ratio.', '{"why":"Grams are used for actual mass, not for a dimensionless relative atomic mass.","sol":"Step 1: Relative atomic mass compares masses with a standard reference.\nStep 2: A ratio of two masses has its units cancelled.\nStep 3: Therefore, relative atomic mass is dimensionless.\nStep 4: The correct notation is Aᵣ(Cl) = 35.5, without g.","steps":["Step 1: Relative atomic mass compares masses with a standard reference.","Step 2: A ratio of two masses has its units cancelled.","Step 3: Therefore, relative atomic mass is dimensionless.","Step 4: The correct notation is Aᵣ(Cl) = 35.5, without g."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_relative_atomic_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q6","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Relative Atomic Mass"}', 5),
  (3372, 802, 'Distinguish between mass number and relative atomic mass.', 'text', 1, 'One refers to a particular atom; the other is a weighted average.', '{"why":"The terms describe different quantities and should not be used interchangeably.","sol":"Step 1: Mass number is the total number of protons and neutrons in one particular atom.\nStep 2: Relative atomic mass is the weighted mean mass of an element''s atoms compared with the carbon-12 reference.\nStep 3: Mass number is a whole number, whereas relative atomic mass may be fractional.","steps":["Step 1: Mass number is the total number of protons and neutrons in one particular atom.","Step 2: Relative atomic mass is the weighted mean mass of an element''s atoms compared with the carbon-12 reference.","Step 3: Mass number is a whole number, whereas relative atomic mass may be fractional."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_relative_atomic_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q7","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Relative Atomic Mass"}', 6),
  (3373, 802, 'Calculate the total relative mass contribution of chlorine in MgCl₂. Use Aᵣ(Cl) = 35.5.', 'text', 1, 'The formula contains two chlorine atoms.', '{"why":"The subscript 2 means that the chlorine contribution must be counted twice.","sol":"Step 1: MgCl₂ contains two chlorine atoms.\nStep 2: Each chlorine atom contributes 35.5.\nStep 3: Chlorine contribution = 2 × 35.5.\nStep 4: Chlorine contribution = 71.","steps":["Step 1: MgCl₂ contains two chlorine atoms.","Step 2: Each chlorine atom contributes 35.5.","Step 3: Chlorine contribution = 2 × 35.5.","Step 4: Chlorine contribution = 71."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_relative_atomic_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q8","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Relative Atomic Mass"}', 7),
  (3374, 802, 'A question gives Aᵣ(Fe) = 56. A learner uses 55.8 instead. Which value should be used, and why?', 'text', 1, 'Follow the data supplied in the question.', '{"why":"Using the stated data avoids inconsistent calculations and answers that differ only because of rounding.","sol":"Step 1: Read the value supplied by the question: 56.\nStep 2: The supplied value may be rounded for the intended calculation.\nStep 3: Use 56 consistently unless the question instructs otherwise.","steps":["Step 1: Read the value supplied by the question: 56.","Step 2: The supplied value may be rounded for the intended calculation.","Step 3: Use 56 consistently unless the question instructs otherwise."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_relative_atomic_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q9","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Relative Atomic Mass"}', 8),
  (3375, 803, 'Calculate the relative formula mass of CO₂. Use C = 12 and O = 16.', 'text', 1, 'Focus on the core principle of Relative Formula Mass.', '{"why":"Each atom contributes its relative atomic mass, multiplied by the number of times it occurs in the formula.","sol":"Step 1: CO₂ contains one carbon atom and two oxygen atoms.\nStep 2: Carbon contribution = 1 × 12 = 12.\nStep 3: Oxygen contribution = 2 × 16 = 32.\nStep 4: Add the contributions: 12 + 32 = 44.","steps":["Step 1: CO₂ contains one carbon atom and two oxygen atoms.","Step 2: Carbon contribution = 1 × 12 = 12.","Step 3: Oxygen contribution = 2 × 16 = 32.","Step 4: Add the contributions: 12 + 32 = 44."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_relative_formula_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q1","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Relative Formula Mass"}', 0),
  (3376, 803, 'Calculate Mᵣ of MgCl₂. Use Mg = 24 and Cl = 35.5.', 'text', 1, 'Focus on the core principle of Relative Formula Mass.', '{"why":"The subscript 2 applies to chlorine, so its relative atomic mass must be counted twice.","sol":"Step 1: The formula contains one Mg atom and two Cl atoms.\nStep 2: Magnesium contribution = 1 × 24 = 24.\nStep 3: Chlorine contribution = 2 × 35.5 = 71.\nStep 4: Add the contributions: 24 + 71 = 95.","steps":["Step 1: The formula contains one Mg atom and two Cl atoms.","Step 2: Magnesium contribution = 1 × 24 = 24.","Step 3: Chlorine contribution = 2 × 35.5 = 71.","Step 4: Add the contributions: 24 + 71 = 95."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_relative_formula_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q2","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Relative Formula Mass"}', 1),
  (3377, 803, 'Calculate Mᵣ of Ca(OH)₂. Use Ca = 40, O = 16 and H = 1.', 'text', 1, 'Focus on the core principle of Relative Formula Mass.', '{"why":"The subscript outside the brackets multiplies both the oxygen and hydrogen counts.","sol":"Step 1: Count atoms: 1 Ca, 2 O and 2 H.\nStep 2: Ca contribution = 40.\nStep 3: O contribution = 2 × 16 = 32.\nStep 4: H contribution = 2 × 1 = 2.\nStep 5: Mᵣ = 40 + 32 + 2 = 74.","steps":["Step 1: Count atoms: 1 Ca, 2 O and 2 H.","Step 2: Ca contribution = 40.","Step 3: O contribution = 2 × 16 = 32.","Step 4: H contribution = 2 × 1 = 2.","Step 5: Mᵣ = 40 + 32 + 2 = 74."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_relative_formula_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q3","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Relative Formula Mass"}', 2),
  (3378, 803, 'Calculate the relative formula mass of Na₂O. Use Na = 23 and O = 16.', 'text', 1, 'There are two sodium atoms and one oxygen atom.', '{"why":"The subscript 2 doubles the sodium contribution.","sol":"Step 1: Na contribution = 2 × 23 = 46.\nStep 2: O contribution = 1 × 16 = 16.\nStep 3: Mᵣ = 46 + 16 = 62.","steps":["Step 1: Na contribution = 2 × 23 = 46.","Step 2: O contribution = 1 × 16 = 16.","Step 3: Mᵣ = 46 + 16 = 62."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_relative_formula_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q4","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Relative Formula Mass"}', 3),
  (3379, 803, 'Calculate Mᵣ of H₂SO₄. Use H = 1, S = 32 and O = 16.', 'text', 1, 'Count two H atoms, one S atom and four O atoms.', '{"why":"The formula contains two hydrogen atoms and four oxygen atoms, so both contributions must be multiplied.","sol":"Step 1: Hydrogen contribution = 2 × 1 = 2.\nStep 2: Sulfur contribution = 1 × 32 = 32.\nStep 3: Oxygen contribution = 4 × 16 = 64.\nStep 4: Add the contributions: 2 + 32 + 64 = 98.","steps":["Step 1: Hydrogen contribution = 2 × 1 = 2.","Step 2: Sulfur contribution = 1 × 32 = 32.","Step 3: Oxygen contribution = 4 × 16 = 64.","Step 4: Add the contributions: 2 + 32 + 64 = 98."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_relative_formula_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q5","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Relative Formula Mass"}', 4),
  (3380, 803, 'Calculate Mᵣ of Al₂O₃. Use Al = 27 and O = 16.', 'text', 1, 'Multiply each relative atomic mass by its subscript.', '{"why":"The total is the sum of the contributions from two aluminium atoms and three oxygen atoms.","sol":"Step 1: Aluminium contribution = 2 × 27 = 54.\nStep 2: Oxygen contribution = 3 × 16 = 48.\nStep 3: Mᵣ = 54 + 48 = 102.","steps":["Step 1: Aluminium contribution = 2 × 27 = 54.","Step 2: Oxygen contribution = 3 × 16 = 48.","Step 3: Mᵣ = 54 + 48 = 102."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_relative_formula_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q6","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Relative Formula Mass"}', 5),
  (3381, 803, 'A learner calculates Mᵣ of Ca(OH)₂ as 40 + 16 + 1 = 57. Identify the error and calculate the correct value. Use Ca = 40, O = 16 and H = 1.', 'text', 1, 'Check what the subscript outside the brackets multiplies.', '{"why":"A subscript outside brackets multiplies every atom inside those brackets.","sol":"Step 1: The formula is Ca(OH)₂, so there are two OH groups.\nStep 2: There are two oxygen atoms: 2 × 16 = 32.\nStep 3: There are two hydrogen atoms: 2 × 1 = 2.\nStep 4: Add calcium: 40 + 32 + 2 = 74.","steps":["Step 1: The formula is Ca(OH)₂, so there are two OH groups.","Step 2: There are two oxygen atoms: 2 × 16 = 32.","Step 3: There are two hydrogen atoms: 2 × 1 = 2.","Step 4: Add calcium: 40 + 32 + 2 = 74."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_relative_formula_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q7","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Relative Formula Mass"}', 6),
  (3382, 803, 'Calculate Mᵣ of (NH₄)₂SO₄. Use N = 14, H = 1, S = 32 and O = 16.', 'text', 1, 'The bracket multiplier gives 2 N atoms and 8 H atoms.', '{"why":"The subscript outside NH₄ multiplies both nitrogen and hydrogen; the sulfate group contributes one sulfur and four oxygen atoms.","sol":"Step 1: Count atoms: 2 N, 8 H, 1 S and 4 O.\nStep 2: Nitrogen contribution = 2 × 14 = 28.\nStep 3: Hydrogen contribution = 8 × 1 = 8.\nStep 4: Sulfur contribution = 1 × 32 = 32.\nStep 5: Oxygen contribution = 4 × 16 = 64.\nStep 6: Mᵣ = 28 + 8 + 32 + 64 = 132.","steps":["Step 1: Count atoms: 2 N, 8 H, 1 S and 4 O.","Step 2: Nitrogen contribution = 2 × 14 = 28.","Step 3: Hydrogen contribution = 8 × 1 = 8.","Step 4: Sulfur contribution = 1 × 32 = 32.","Step 5: Oxygen contribution = 4 × 16 = 64.","Step 6: Mᵣ = 28 + 8 + 32 + 64 = 132."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_relative_formula_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q8","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Relative Formula Mass"}', 7),
  (3383, 803, 'Explain why relative formula mass has no unit, then calculate Mᵣ of NaCl using Na = 23 and Cl = 35.5.', 'text', 1, 'Relative atomic masses have no units, and formula mass is their sum.', '{"why":"A sum of dimensionless relative atomic masses is also dimensionless.","sol":"Step 1: Relative formula mass is calculated from relative atomic masses.\nStep 2: Relative atomic masses are ratios and have no unit.\nStep 3: NaCl contains one Na and one Cl.\nStep 4: Mᵣ = 23 + 35.5 = 58.5.","steps":["Step 1: Relative formula mass is calculated from relative atomic masses.","Step 2: Relative atomic masses are ratios and have no unit.","Step 3: NaCl contains one Na and one Cl.","Step 4: Mᵣ = 23 + 35.5 = 58.5."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_relative_formula_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q9","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Relative Formula Mass"}', 8),
  (3384, 804, 'Calculate the molar mass of CO₂. Use C = 12 and O = 16.', 'text', 1, 'Focus on the core principle of Molar Mass.', '{"why":"The numerical value of molar mass corresponds to the relative formula mass, but molar mass carries the unit g mol⁻¹.","sol":"Step 1: CO₂ contains one C atom and two O atoms.\nStep 2: Mᵣ = 12 + (2 × 16).\nStep 3: Mᵣ = 12 + 32 = 44.\nStep 4: Express the result as molar mass: 44 g mol⁻¹.","steps":["Step 1: CO₂ contains one C atom and two O atoms.","Step 2: Mᵣ = 12 + (2 × 16).","Step 3: Mᵣ = 12 + 32 = 44.","Step 4: Express the result as molar mass: 44 g mol⁻¹."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_molar_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q1","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Molar Mass"}', 0),
  (3385, 804, 'Calculate the molar mass of Na₂CO₃. Use Na = 23, C = 12 and O = 16.', 'text', 1, 'Focus on the core principle of Molar Mass.', '{"why":"Molar mass is found by summing the mass contributions of every atom in the formula and expressing the result per mole.","sol":"Step 1: There are 2 Na, 1 C and 3 O atoms.\nStep 2: Sodium contribution = 2 × 23 = 46.\nStep 3: Carbon contribution = 12.\nStep 4: Oxygen contribution = 3 × 16 = 48.\nStep 5: Total = 46 + 12 + 48 = 106.\nStep 6: Molar mass = 106 g mol⁻¹.","steps":["Step 1: There are 2 Na, 1 C and 3 O atoms.","Step 2: Sodium contribution = 2 × 23 = 46.","Step 3: Carbon contribution = 12.","Step 4: Oxygen contribution = 3 × 16 = 48.","Step 5: Total = 46 + 12 + 48 = 106.","Step 6: Molar mass = 106 g mol⁻¹."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_molar_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q2","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Molar Mass"}', 1),
  (3386, 804, 'A compound has Mᵣ = 58.5. State its molar mass and explain what this value means.', 'text', 1, 'Focus on the core principle of Molar Mass.', '{"why":"Molar mass converts an amount measured in moles into a mass measured in grams.","sol":"Step 1: The relative formula mass is 58.5.\nStep 2: Use the same numerical value for molar mass.\nStep 3: Include the unit g mol⁻¹.\nStep 4: Interpret the result as the mass of one mole.","steps":["Step 1: The relative formula mass is 58.5.","Step 2: Use the same numerical value for molar mass.","Step 3: Include the unit g mol⁻¹.","Step 4: Interpret the result as the mass of one mole."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_molar_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q3","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Molar Mass"}', 2),
  (3387, 804, 'Calculate the molar mass of MgO. Use Mg = 24 and O = 16.', 'text', 1, 'Add the relative atomic masses of one magnesium atom and one oxygen atom.', '{"why":"MgO contains one magnesium atom and one oxygen atom per formula unit.","sol":"Step 1: Mg contribution = 24.\nStep 2: O contribution = 16.\nStep 3: Mᵣ = 24 + 16 = 40.\nStep 4: Molar mass = 40 g mol⁻¹.","steps":["Step 1: Mg contribution = 24.","Step 2: O contribution = 16.","Step 3: Mᵣ = 24 + 16 = 40.","Step 4: Molar mass = 40 g mol⁻¹."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_molar_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q4","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Molar Mass"}', 3),
  (3388, 804, 'Calculate the molar mass of HNO₃. Use H = 1, N = 14 and O = 16.', 'text', 1, 'Count one H, one N and three O atoms.', '{"why":"The three oxygen atoms contribute 48 to the formula-mass total.","sol":"Step 1: H contribution = 1 × 1 = 1.\nStep 2: N contribution = 1 × 14 = 14.\nStep 3: O contribution = 3 × 16 = 48.\nStep 4: Mᵣ = 1 + 14 + 48 = 63.\nStep 5: Molar mass = 63 g mol⁻¹.","steps":["Step 1: H contribution = 1 × 1 = 1.","Step 2: N contribution = 1 × 14 = 14.","Step 3: O contribution = 3 × 16 = 48.","Step 4: Mᵣ = 1 + 14 + 48 = 63.","Step 5: Molar mass = 63 g mol⁻¹."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_molar_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q5","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Molar Mass"}', 4),
  (3389, 804, 'Explain the difference between Mᵣ = 44 and M = 44 g mol⁻¹.', 'text', 1, 'One is dimensionless; the other is mass per amount of substance.', '{"why":"The quantities are related numerically but have different meanings and units.","sol":"Step 1: Mᵣ is relative formula mass and has no unit.\nStep 2: M is molar mass and has the unit g mol⁻¹.\nStep 3: The number 44 indicates the corresponding relative formula mass and molar-mass value.\nStep 4: The molar mass tells us that one mole has a mass of 44 g.","steps":["Step 1: Mᵣ is relative formula mass and has no unit.","Step 2: M is molar mass and has the unit g mol⁻¹.","Step 3: The number 44 indicates the corresponding relative formula mass and molar-mass value.","Step 4: The molar mass tells us that one mole has a mass of 44 g."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_molar_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q6","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Molar Mass"}', 5),
  (3390, 804, 'Calculate the molar mass of Ca(OH)₂. Use Ca = 40, O = 16 and H = 1.', 'text', 1, 'The two outside brackets multiply both O and H.', '{"why":"The bracket multiplier must be applied to both elements inside the brackets.","sol":"Step 1: There is one Ca, two O and two H atoms.\nStep 2: Ca contribution = 40.\nStep 3: O contribution = 2 × 16 = 32.\nStep 4: H contribution = 2 × 1 = 2.\nStep 5: Total = 40 + 32 + 2 = 74.\nStep 6: Molar mass = 74 g mol⁻¹.","steps":["Step 1: There is one Ca, two O and two H atoms.","Step 2: Ca contribution = 40.","Step 3: O contribution = 2 × 16 = 32.","Step 4: H contribution = 2 × 1 = 2.","Step 5: Total = 40 + 32 + 2 = 74.","Step 6: Molar mass = 74 g mol⁻¹."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_molar_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q7","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Molar Mass"}', 6),
  (3391, 804, 'A sample has a molar mass of 18 g mol⁻¹. Explain the mass of 1 mol and the mass of 2 mol of this substance.', 'text', 1, 'Multiply the molar mass by the amount in moles.', '{"why":"Mass increases in direct proportion to the amount of substance when the molar mass remains constant.","sol":"Step 1: One mole has a mass of 18 g.\nStep 2: Two moles have twice the mass of one mole.\nStep 3: Mass = 2 × 18 = 36 g.","steps":["Step 1: One mole has a mass of 18 g.","Step 2: Two moles have twice the mass of one mole.","Step 3: Mass = 2 × 18 = 36 g."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_molar_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q8","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Molar Mass"}', 7),
  (3392, 804, 'A learner states that the molar mass of water is 18 g because its formula mass is 18. Improve the statement so that it is scientifically precise.', 'text', 1, 'Include the amount of substance represented by the molar mass.', '{"why":"The distinction between the relative value, the molar-mass unit and the mass of a particular amount is essential for quantitative chemistry.","sol":"Step 1: The relative formula mass of water is 18 and has no unit.\nStep 2: Its molar mass is 18 g mol⁻¹.\nStep 3: This means one mole of water has a mass of 18 g.","steps":["Step 1: The relative formula mass of water is 18 and has no unit.","Step 2: Its molar mass is 18 g mol⁻¹.","Step 3: This means one mole of water has a mass of 18 g."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_molar_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q9","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Molar Mass"}', 8),
  (3393, 805, 'Calculate the amount of substance in 36 g of water. M(H₂O) = 18 g mol⁻¹.', 'text', 1, 'Focus on the core principle of Calculating Moles from Mass.', '{"why":"The sample has twice the mass of one mole of water.","sol":"Step 1: Use n = m ÷ M.\nStep 2: m = 36 g and M = 18 g mol⁻¹.\nStep 3: n = 36 ÷ 18.\nStep 4: n = 2 mol.","steps":["Step 1: Use n = m ÷ M.","Step 2: m = 36 g and M = 18 g mol⁻¹.","Step 3: n = 36 ÷ 18.","Step 4: n = 2 mol."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_moles_from_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q1","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Moles from Mass"}', 0),
  (3394, 805, 'Calculate the amount of substance in 22 g of CO₂. M(CO₂) = 44 g mol⁻¹.', 'text', 1, 'Focus on the core principle of Calculating Moles from Mass.', '{"why":"22 g is half the molar mass of carbon dioxide.","sol":"Step 1: Use n = m ÷ M.\nStep 2: n = 22 ÷ 44.\nStep 3: n = 0.5 mol.","steps":["Step 1: Use n = m ÷ M.","Step 2: n = 22 ÷ 44.","Step 3: n = 0.5 mol."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_moles_from_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q2","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Moles from Mass"}', 1),
  (3395, 805, 'Calculate the amount of CaCO₃ in 25 g. Its molar mass is 100 g mol⁻¹.', 'text', 1, 'Focus on the core principle of Calculating Moles from Mass.', '{"why":"A mass of 25 g is one-quarter of the mass of one mole of CaCO₃.","sol":"Step 1: Use n = m ÷ M.\nStep 2: Substitute n = 25 ÷ 100.\nStep 3: n = 0.25 mol.","steps":["Step 1: Use n = m ÷ M.","Step 2: Substitute n = 25 ÷ 100.","Step 3: n = 0.25 mol."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_moles_from_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q3","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Moles from Mass"}', 2),
  (3396, 805, 'Calculate the amount of substance in 9 g of water. M(H₂O) = 18 g mol⁻¹.', 'text', 1, 'Divide the mass of the sample by the molar mass.', '{"why":"The sample contains half the mass of one mole of water.","sol":"Step 1: n = m ÷ M.\nStep 2: n = 9 ÷ 18.\nStep 3: n = 0.5 mol.","steps":["Step 1: n = m ÷ M.","Step 2: n = 9 ÷ 18.","Step 3: n = 0.5 mol."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_moles_from_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q4","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Moles from Mass"}', 3),
  (3397, 805, 'Calculate the amount of CO₂ in 5.5 g. M(CO₂) = 44 g mol⁻¹.', 'text', 1, 'Use n = m ÷ M.', '{"why":"5.5 g is one-eighth of 44 g, so it represents one-eighth of a mole.","sol":"Step 1: n = 5.5 ÷ 44.\nStep 2: n = 0.125 mol.","steps":["Step 1: n = 5.5 ÷ 44.","Step 2: n = 0.125 mol."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_moles_from_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q5","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Moles from Mass"}', 4),
  (3398, 805, 'Calculate the amount of NaCl in 11.7 g. Use Na = 23 and Cl = 35.5.', 'text', 1, 'Calculate the molar mass before dividing.', '{"why":"The mass of the sample divided by the molar mass gives the amount in moles.","sol":"Step 1: M(NaCl) = 23 + 35.5 = 58.5 g mol⁻¹.\nStep 2: Use n = m ÷ M.\nStep 3: n = 11.7 ÷ 58.5.\nStep 4: n = 0.20 mol.","steps":["Step 1: M(NaCl) = 23 + 35.5 = 58.5 g mol⁻¹.","Step 2: Use n = m ÷ M.","Step 3: n = 11.7 ÷ 58.5.","Step 4: n = 0.20 mol."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_moles_from_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q6","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Moles from Mass"}', 5),
  (3399, 805, 'A learner calculates the moles in 8 g of oxygen gas, O₂, by dividing 8 by 16 and obtains 0.5 mol. Identify the mistake and calculate the correct answer.', 'text', 1, 'O₂ contains two oxygen atoms per molecule.', '{"why":"The molar mass must match the chemical formula of the substance being measured.","sol":"Step 1: The substance is O₂, not individual oxygen atoms.\nStep 2: M(O₂) = 2 × 16 = 32 g mol⁻¹.\nStep 3: Use n = m ÷ M.\nStep 4: n = 8 ÷ 32 = 0.25 mol.","steps":["Step 1: The substance is O₂, not individual oxygen atoms.","Step 2: M(O₂) = 2 × 16 = 32 g mol⁻¹.","Step 3: Use n = m ÷ M.","Step 4: n = 8 ÷ 32 = 0.25 mol."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_moles_from_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q7","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Moles from Mass"}', 6),
  (3400, 805, 'A sample of CaCO₃ has a mass of 7.5 g. Calculate the amount in moles. Use Ca = 40, C = 12 and O = 16.', 'text', 1, 'First calculate M(CaCO₃).', '{"why":"The sample mass is divided by the molar mass of calcium carbonate.","sol":"Step 1: M(CaCO₃) = 40 + 12 + (3 × 16).\nStep 2: M(CaCO₃) = 100 g mol⁻¹.\nStep 3: Use n = m ÷ M.\nStep 4: n = 7.5 ÷ 100.\nStep 5: n = 0.075 mol.","steps":["Step 1: M(CaCO₃) = 40 + 12 + (3 × 16).","Step 2: M(CaCO₃) = 100 g mol⁻¹.","Step 3: Use n = m ÷ M.","Step 4: n = 7.5 ÷ 100.","Step 5: n = 0.075 mol."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_moles_from_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q8","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Moles from Mass"}', 7),
  (3401, 805, 'A compound has a molar mass of 80 g mol⁻¹. A learner has 200 g of it. Calculate the amount in moles and explain why your answer is reasonable.', 'text', 1, 'Find how many 80 g portions fit into 200 g.', '{"why":"The sample has 2.5 times the mass of one mole, so it contains 2.5 mol.","sol":"Step 1: Use n = m ÷ M.\nStep 2: n = 200 ÷ 80.\nStep 3: n = 2.5 mol.\nStep 4: Check: 2.5 × 80 = 200 g.","steps":["Step 1: Use n = m ÷ M.","Step 2: n = 200 ÷ 80.","Step 3: n = 2.5 mol.","Step 4: Check: 2.5 × 80 = 200 g."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_moles_from_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q9","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Moles from Mass"}', 8),
  (3402, 806, 'Calculate the mass of 3 mol of water. M(H₂O) = 18 g mol⁻¹.', 'text', 1, 'Focus on the core principle of Calculating Mass from Moles.', '{"why":"Three moles have three times the mass of one mole.","sol":"Step 1: Use m = n × M.\nStep 2: n = 3 mol and M = 18 g mol⁻¹.\nStep 3: m = 3 × 18.\nStep 4: m = 54 g.","steps":["Step 1: Use m = n × M.","Step 2: n = 3 mol and M = 18 g mol⁻¹.","Step 3: m = 3 × 18.","Step 4: m = 54 g."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_mass_from_moles","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q1","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Mass from Moles"}', 0),
  (3403, 806, 'Calculate the mass of 0.5 mol of CO₂. M(CO₂) = 44 g mol⁻¹.', 'text', 1, 'Focus on the core principle of Calculating Mass from Moles.', '{"why":"Half a mole has half the mass of one mole.","sol":"Step 1: Use m = n × M.\nStep 2: m = 0.5 × 44.\nStep 3: m = 22 g.","steps":["Step 1: Use m = n × M.","Step 2: m = 0.5 × 44.","Step 3: m = 22 g."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_mass_from_moles","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q2","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Mass from Moles"}', 1),
  (3404, 806, 'Calculate the mass of 2.5 mol of NaCl. M(NaCl) = 58.5 g mol⁻¹.', 'text', 1, 'Focus on the core principle of Calculating Mass from Moles.', '{"why":"The mass equals the number of moles multiplied by the mass of one mole.","sol":"Step 1: Use m = n × M.\nStep 2: m = 2.5 × 58.5.\nStep 3: 58.5 × 2 = 117.\nStep 4: 58.5 × 0.5 = 29.25.\nStep 5: Add: 117 + 29.25 = 146.25 g.","steps":["Step 1: Use m = n × M.","Step 2: m = 2.5 × 58.5.","Step 3: 58.5 × 2 = 117.","Step 4: 58.5 × 0.5 = 29.25.","Step 5: Add: 117 + 29.25 = 146.25 g."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_mass_from_moles","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q3","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Mass from Moles"}', 2),
  (3405, 806, 'Calculate the mass of 0.25 mol of water. M(H₂O) = 18 g mol⁻¹.', 'text', 1, 'Use m = n × M.', '{"why":"A quarter of a mole has one-quarter of the mass of one mole.","sol":"Step 1: m = 0.25 × 18.\nStep 2: m = 4.5 g.","steps":["Step 1: m = 0.25 × 18.","Step 2: m = 4.5 g."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_mass_from_moles","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q4","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Mass from Moles"}', 3),
  (3406, 806, 'Calculate the mass of 0.75 mol of CO₂. M(CO₂) = 44 g mol⁻¹.', 'text', 1, 'Multiply 0.75 by 44.', '{"why":"The mass is three-quarters of the mass of one mole of CO₂.","sol":"Step 1: Use m = n × M.\nStep 2: m = 0.75 × 44.\nStep 3: m = 33 g.","steps":["Step 1: Use m = n × M.","Step 2: m = 0.75 × 44.","Step 3: m = 33 g."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_mass_from_moles","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q5","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Mass from Moles"}', 4),
  (3407, 806, 'Calculate the mass of 0.20 mol of NaOH. Use Na = 23, O = 16 and H = 1.', 'text', 1, 'Find the molar mass of NaOH first.', '{"why":"The correct molar mass is 40 g mol⁻¹, so 0.20 mol has a mass of 8 g.","sol":"Step 1: M(NaOH) = 23 + 16 + 1 = 40 g mol⁻¹.\nStep 2: Use m = n × M.\nStep 3: m = 0.20 × 40.\nStep 4: m = 8 g.","steps":["Step 1: M(NaOH) = 23 + 16 + 1 = 40 g mol⁻¹.","Step 2: Use m = n × M.","Step 3: m = 0.20 × 40.","Step 4: m = 8 g."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_mass_from_moles","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q6","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Mass from Moles"}', 5),
  (3408, 806, 'A learner calculates the mass of 2 mol of oxygen gas as 32 g. Identify the error and find the correct mass. Use O = 16.', 'text', 1, 'Oxygen gas is O₂, which contains two oxygen atoms per molecule.', '{"why":"The given amount is 2 mol, so the molar mass must be multiplied by 2.","sol":"Step 1: Calculate M(O₂) = 2 × 16 = 32 g mol⁻¹.\nStep 2: The value 32 g is the mass of 1 mol, not 2 mol.\nStep 3: Use m = n × M.\nStep 4: m = 2 × 32 = 64 g.","steps":["Step 1: Calculate M(O₂) = 2 × 16 = 32 g mol⁻¹.","Step 2: The value 32 g is the mass of 1 mol, not 2 mol.","Step 3: Use m = n × M.","Step 4: m = 2 × 32 = 64 g."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_mass_from_moles","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q7","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Mass from Moles"}', 6),
  (3409, 806, 'Calculate the mass of 1.25 mol of calcium carbonate. Use Ca = 40, C = 12 and O = 16.', 'text', 1, 'Calculate M(CaCO₃) before multiplying by the amount.', '{"why":"Each mole has a mass of 100 g, so 1.25 mol has a mass of 125 g.","sol":"Step 1: M(CaCO₃) = 40 + 12 + (3 × 16).\nStep 2: M(CaCO₃) = 100 g mol⁻¹.\nStep 3: Use m = n × M.\nStep 4: m = 1.25 × 100.\nStep 5: m = 125 g.","steps":["Step 1: M(CaCO₃) = 40 + 12 + (3 × 16).","Step 2: M(CaCO₃) = 100 g mol⁻¹.","Step 3: Use m = n × M.","Step 4: m = 1.25 × 100.","Step 5: m = 125 g."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_mass_from_moles","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q8","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Mass from Moles"}', 7),
  (3410, 806, 'A laboratory procedure requires 0.40 mol of a substance with molar mass 60 g mol⁻¹. Calculate the mass to measure and show how you can check your answer.', 'text', 1, 'Multiply the required amount by the molar mass.', '{"why":"The calculated mass gives exactly the required 0.40 mol when divided by the molar mass.","sol":"Step 1: Use m = n × M.\nStep 2: m = 0.40 × 60.\nStep 3: m = 24 g.\nStep 4: Check using n = m ÷ M = 24 ÷ 60 = 0.40 mol.","steps":["Step 1: Use m = n × M.","Step 2: m = 0.40 × 60.","Step 3: m = 24 g.","Step 4: Check using n = m ÷ M = 24 ÷ 60 = 0.40 mol."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_mass_from_moles","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q9","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Mass from Moles"}', 8),
  (3411, 807, 'Calculate the number of molecules in 2 mol of CO₂.', 'text', 1, 'Focus on the core principle of Moles and Particles.', '{"why":"Each mole contains 6.02 × 10²³ molecules.","sol":"Step 1: Use N = n × Nₐ.\nStep 2: N = 2 × 6.02 × 10²³.\nStep 3: N = 12.04 × 10²³.\nStep 4: Convert to standard form: 1.204 × 10²⁴ molecules.","steps":["Step 1: Use N = n × Nₐ.","Step 2: N = 2 × 6.02 × 10²³.","Step 3: N = 12.04 × 10²³.","Step 4: Convert to standard form: 1.204 × 10²⁴ molecules."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_moles_and_particles","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q1","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Moles and Particles"}', 0),
  (3412, 807, 'Calculate the number of atoms in 0.1 mol of carbon atoms.', 'text', 1, 'Focus on the core principle of Moles and Particles.', '{"why":"The sample contains one-tenth of a mole, so it has one-tenth of the Avogadro constant number of atoms.","sol":"Step 1: Use N = n × Nₐ.\nStep 2: N = 0.1 × 6.02 × 10²³.\nStep 3: N = 0.602 × 10²³.\nStep 4: Convert to standard form: N = 6.02 × 10²² atoms.","steps":["Step 1: Use N = n × Nₐ.","Step 2: N = 0.1 × 6.02 × 10²³.","Step 3: N = 0.602 × 10²³.","Step 4: Convert to standard form: N = 6.02 × 10²² atoms."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_moles_and_particles","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q2","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Moles and Particles"}', 1),
  (3413, 807, 'Calculate the amount in moles represented by 1.204 × 10²⁴ molecules.', 'text', 1, 'Focus on the core principle of Moles and Particles.', '{"why":"The particle count is twice the Avogadro constant.","sol":"Step 1: Use n = N ÷ Nₐ.\nStep 2: n = (1.204 × 10²⁴) ÷ (6.02 × 10²³).\nStep 3: n = (1.204 ÷ 6.02) × 10.\nStep 4: n = 0.2 × 10 = 2 mol.","steps":["Step 1: Use n = N ÷ Nₐ.","Step 2: n = (1.204 × 10²⁴) ÷ (6.02 × 10²³).","Step 3: n = (1.204 ÷ 6.02) × 10.","Step 4: n = 0.2 × 10 = 2 mol."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_moles_and_particles","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q3","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Moles and Particles"}', 2),
  (3414, 807, 'Calculate the number of molecules in 0.5 mol of oxygen gas, O₂.', 'text', 1, 'Calculate the number of O₂ molecules first.', '{"why":"The mole calculation gives the number of molecules, not the total number of atoms inside them.","sol":"Step 1: Use N = n × Nₐ.\nStep 2: N = 0.5 × 6.02 × 10²³.\nStep 3: N = 3.01 × 10²³ molecules.","steps":["Step 1: Use N = n × Nₐ.","Step 2: N = 0.5 × 6.02 × 10²³.","Step 3: N = 3.01 × 10²³ molecules."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_moles_and_particles","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q4","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Moles and Particles"}', 3),
  (3415, 807, 'Calculate the number of oxygen atoms in 0.5 mol of O₂ molecules.', 'text', 1, 'First find the molecules, then multiply by two atoms per molecule.', '{"why":"Each molecule contains two atoms, so the total atom count is twice the molecule count.","sol":"Step 1: Number of O₂ molecules = 0.5 × 6.02 × 10²³ = 3.01 × 10²³.\nStep 2: Each O₂ molecule contains two oxygen atoms.\nStep 3: Number of atoms = 2 × 3.01 × 10²³.\nStep 4: Number of atoms = 6.02 × 10²³.","steps":["Step 1: Number of O₂ molecules = 0.5 × 6.02 × 10²³ = 3.01 × 10²³.","Step 2: Each O₂ molecule contains two oxygen atoms.","Step 3: Number of atoms = 2 × 3.01 × 10²³.","Step 4: Number of atoms = 6.02 × 10²³."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_moles_and_particles","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q5","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Moles and Particles"}', 4),
  (3416, 807, 'Calculate the number of water molecules in 0.25 mol of H₂O.', 'text', 1, 'Use N = n × Nₐ.', '{"why":"One-quarter of a mole contains one-quarter of the Avogadro constant number of molecules.","sol":"Step 1: N = 0.25 × 6.02 × 10²³.\nStep 2: 0.25 × 6.02 = 1.505.\nStep 3: N = 1.505 × 10²³ molecules.","steps":["Step 1: N = 0.25 × 6.02 × 10²³.","Step 2: 0.25 × 6.02 = 1.505.","Step 3: N = 1.505 × 10²³ molecules."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_moles_and_particles","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q6","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Moles and Particles"}', 5),
  (3417, 807, 'A sample contains 3.01 × 10²³ sodium ions. Calculate the amount of sodium ions in moles.', 'text', 1, 'Divide the number of ions by Avogadro''s constant.', '{"why":"The calculation converts a count of ions into an amount of substance.","sol":"Step 1: n = N ÷ Nₐ.\nStep 2: n = (3.01 × 10²³) ÷ (6.02 × 10²³).\nStep 3: The powers of ten cancel.\nStep 4: n = 3.01 ÷ 6.02 = 0.5 mol.","steps":["Step 1: n = N ÷ Nₐ.","Step 2: n = (3.01 × 10²³) ÷ (6.02 × 10²³).","Step 3: The powers of ten cancel.","Step 4: n = 3.01 ÷ 6.02 = 0.5 mol."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_moles_and_particles","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q7","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Moles and Particles"}', 6),
  (3418, 807, 'How many total atoms are present in 2 mol of water molecules, H₂O?', 'text', 1, 'Each water molecule contains two hydrogen atoms and one oxygen atom.', '{"why":"Each molecule contains three atoms, so the total number of atoms is three times the number of molecules.","sol":"Step 1: Each H₂O molecule contains 3 atoms in total.\nStep 2: Number of water molecules in 2 mol = 2 × 6.02 × 10²³ = 1.204 × 10²⁴.\nStep 3: Total atoms = 3 × 1.204 × 10²⁴.\nStep 4: Total atoms = 3.612 × 10²⁴.","steps":["Step 1: Each H₂O molecule contains 3 atoms in total.","Step 2: Number of water molecules in 2 mol = 2 × 6.02 × 10²³ = 1.204 × 10²⁴.","Step 3: Total atoms = 3 × 1.204 × 10²⁴.","Step 4: Total atoms = 3.612 × 10²⁴."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_moles_and_particles","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q8","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Moles and Particles"}', 7),
  (3419, 807, 'A learner says that 1 mol of O₂ contains 6.02 × 10²³ oxygen atoms. Explain the error and calculate the correct number of oxygen atoms.', 'text', 1, 'The Avogadro constant first counts O₂ molecules; each molecule has two atoms.', '{"why":"A molecular particle can contain more than one atom; the atom count must account for the molecular formula.","sol":"Step 1: One mole of O₂ contains 6.02 × 10²³ O₂ molecules.\nStep 2: Each O₂ molecule contains two oxygen atoms.\nStep 3: Number of oxygen atoms = 2 × 6.02 × 10²³.\nStep 4: Number of oxygen atoms = 1.204 × 10²⁴.","steps":["Step 1: One mole of O₂ contains 6.02 × 10²³ O₂ molecules.","Step 2: Each O₂ molecule contains two oxygen atoms.","Step 3: Number of oxygen atoms = 2 × 6.02 × 10²³.","Step 4: Number of oxygen atoms = 1.204 × 10²⁴."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_moles_and_particles","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q9","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Moles and Particles"}', 8),
  (3420, 808, 'Magnesium burns in oxygen and forms magnesium oxide. Why is this a chemical reaction?', 'text', 1, 'Compare the starting substances with the substance formed.', '{"why":"The formation of a substance with a new chemical composition is the defining feature of a chemical reaction.","sol":"Step 1: Identify magnesium and oxygen as the starting substances.\nStep 2: Identify magnesium oxide as the new substance.\nStep 3: Recognise that magnesium oxide has a different chemical composition from either starting substance.","steps":["Step 1: Identify magnesium and oxygen as the starting substances.","Step 2: Identify magnesium oxide as the new substance.","Step 3: Recognise that magnesium oxide has a different chemical composition from either starting substance."],"options":[],"conceptId":"chemistry_chemical_reactions_chemical_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"Chemical Reactions"}', 0),
  (3421, 808, 'Ice melts to form liquid water. Explain why this is a physical change rather than a chemical reaction.', 'text', 1, 'Check whether the chemical identity of water changes.', '{"why":"A change of state does not change the chemical composition of water.","sol":"Step 1: Identify the substance before melting as H₂O.\nStep 2: Identify the substance after melting as H₂O.\nStep 3: Conclude that only the physical state changes.","steps":["Step 1: Identify the substance before melting as H₂O.","Step 2: Identify the substance after melting as H₂O.","Step 3: Conclude that only the physical state changes."],"options":[],"conceptId":"chemistry_chemical_reactions_chemical_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"Chemical Reactions"}', 1),
  (3422, 808, 'During a chemical reaction, what happens to the atoms in the starting substances?', 'text', 1, 'Think about the difference between rearranging atoms and creating new atoms.', '{"why":"Ordinary chemical reactions change how atoms are bonded, not the identity of the atomic nuclei.","sol":"Step 1: Recognise that atoms are present in the starting substances.\nStep 2: Chemical bonds break and new bonds form.\nStep 3: The atoms rearrange into new combinations while the atoms themselves are conserved.","steps":["Step 1: Recognise that atoms are present in the starting substances.","Step 2: Chemical bonds break and new bonds form.","Step 3: The atoms rearrange into new combinations while the atoms themselves are conserved."],"options":[],"conceptId":"chemistry_chemical_reactions_chemical_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"Chemical Reactions"}', 2),
  (3423, 808, 'A student heats a blue substance. It becomes black, and analysis shows that a new compound has formed. Is this evidence of a chemical reaction? Explain.', 'text', 1, 'Use both the observed colour change and the information about the substance formed.', '{"why":"The colour change supports the conclusion, but the decisive evidence is the formation of a new substance.","sol":"Step 1: Identify the observed colour change.\nStep 2: Use the analysis result to determine whether a new substance formed.\nStep 3: Connect the formation of the new compound to the definition of a chemical reaction.","steps":["Step 1: Identify the observed colour change.","Step 2: Use the analysis result to determine whether a new substance formed.","Step 3: Connect the formation of the new compound to the definition of a chemical reaction."],"options":[],"conceptId":"chemistry_chemical_reactions_chemical_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"Chemical Reactions"}', 3),
  (3424, 808, 'A candle''s wax melts when heated. No new substance is formed during melting. Classify this change.', 'text', 1, 'Ask whether the chemical composition changes.', '{"why":"Melting changes the physical state of the wax without, by itself, producing a new substance.","sol":"Step 1: Identify the change as melting.\nStep 2: Check whether a new substance forms during this step.\nStep 3: Classify a change that alters only physical form as a physical change.","steps":["Step 1: Identify the change as melting.","Step 2: Check whether a new substance forms during this step.","Step 3: Classify a change that alters only physical form as a physical change."],"options":[],"conceptId":"chemistry_chemical_reactions_chemical_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q5","subject":"chemistry","chapter":"chemical_reactions","topic":"Chemical Reactions"}', 4),
  (3425, 808, 'A student sees bubbles when a liquid is heated and concludes that a chemical reaction must have occurred. What is wrong with this conclusion?', 'text', 1, 'Can bubbles form when a liquid changes into a gas?', '{"why":"Evidence such as gas production must be interpreted in context to distinguish a chemical reaction from a physical change.","sol":"Step 1: Recognise that bubbles can form when a liquid boils.\nStep 2: Boiling can occur without forming a new substance.\nStep 3: Conclude that further evidence is needed to establish whether a chemical reaction occurred.","steps":["Step 1: Recognise that bubbles can form when a liquid boils.","Step 2: Boiling can occur without forming a new substance.","Step 3: Conclude that further evidence is needed to establish whether a chemical reaction occurred."],"options":[],"conceptId":"chemistry_chemical_reactions_chemical_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q6","subject":"chemistry","chapter":"chemical_reactions","topic":"Chemical Reactions"}', 5),
  (3426, 808, 'Hydrogen and oxygen react to form water. A student says the atoms disappear and water atoms are created. Correct the student''s explanation.', 'text', 1, 'Think about what is conserved when chemical bonds change.', '{"why":"Chemical reactions involve rearrangement of atoms rather than the creation or destruction of atoms.","sol":"Step 1: Identify hydrogen and oxygen atoms in the reactants.\nStep 2: Recognise that the atoms form new bonds.\nStep 3: Explain that the same atoms are rearranged into water molecules.","steps":["Step 1: Identify hydrogen and oxygen atoms in the reactants.","Step 2: Recognise that the atoms form new bonds.","Step 3: Explain that the same atoms are rearranged into water molecules."],"options":[],"conceptId":"chemistry_chemical_reactions_chemical_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q7","subject":"chemistry","chapter":"chemical_reactions","topic":"Chemical Reactions"}', 6),
  (3427, 808, 'Iron reacts with sulfur to form iron sulfide, which has different properties from iron and sulfur. What does this tell you about the change?', 'text', 1, 'Focus on the identity and properties of the product.', '{"why":"Formation of a new compound indicates a chemical change.","sol":"Step 1: Identify iron and sulfur as the starting substances.\nStep 2: Identify iron sulfide as the product.\nStep 3: Recognise that a compound with a different composition and properties has formed.","steps":["Step 1: Identify iron and sulfur as the starting substances.","Step 2: Identify iron sulfide as the product.","Step 3: Recognise that a compound with a different composition and properties has formed."],"options":[],"conceptId":"chemistry_chemical_reactions_chemical_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q8","subject":"chemistry","chapter":"chemical_reactions","topic":"Chemical Reactions"}', 7),
  (3428, 808, 'A piece of paper is cut into smaller pieces. No new substance forms. Explain why this is not a chemical reaction.', 'text', 1, 'Distinguish a change in size from a change in chemical composition.', '{"why":"A change in physical dimensions alone does not constitute a chemical reaction.","sol":"Step 1: Identify the change as cutting.\nStep 2: Check whether a new substance has formed.\nStep 3: Recognise that the paper''s size and shape change, but its chemical identity does not.","steps":["Step 1: Identify the change as cutting.","Step 2: Check whether a new substance has formed.","Step 3: Recognise that the paper''s size and shape change, but its chemical identity does not."],"options":[],"conceptId":"chemistry_chemical_reactions_chemical_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q9","subject":"chemistry","chapter":"chemical_reactions","topic":"Chemical Reactions"}', 8),
  (3429, 809, 'Identify the reactants in 2H₂ + O₂ → 2H₂O.', 'text', 1, 'Read the substances on the left-hand side of the arrow.', '{"why":"Reactants are the starting substances and are written to the left of the reaction arrow.","sol":"Step 1: Locate the arrow in the equation.\nStep 2: Read the left-hand side: 2H₂ + O₂.\nStep 3: Name the substances represented by H₂ and O₂.","steps":["Step 1: Locate the arrow in the equation.","Step 2: Read the left-hand side: 2H₂ + O₂.","Step 3: Name the substances represented by H₂ and O₂."],"options":[],"conceptId":"chemistry_chemical_reactions_reactants","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"Reactants"}', 0),
  (3430, 809, 'In Fe + S → FeS, which substances are the reactants?', 'text', 1, 'Do not confuse the substance on the right with the starting substances.', '{"why":"Iron and sulfur are on the left of the arrow and combine to form iron sulfide.","sol":"Step 1: Locate the arrow.\nStep 2: Read the left-hand side: Fe + S.\nStep 3: Identify Fe as iron and S as sulfur.","steps":["Step 1: Locate the arrow.","Step 2: Read the left-hand side: Fe + S.","Step 3: Identify Fe as iron and S as sulfur."],"options":[],"conceptId":"chemistry_chemical_reactions_reactants","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"Reactants"}', 1),
  (3431, 809, 'In CaCO₃ → CaO + CO₂, name the reactant and explain how you identified it.', 'text', 1, 'Check how many substances appear to the left of the arrow.', '{"why":"Reactants are identified by their position before the arrow, even when only one reactant is present.","sol":"Step 1: Locate the arrow.\nStep 2: Inspect the left-hand side, which contains CaCO₃.\nStep 3: Identify CaCO₃ as calcium carbonate.","steps":["Step 1: Locate the arrow.","Step 2: Inspect the left-hand side, which contains CaCO₃.","Step 3: Identify CaCO₃ as calcium carbonate."],"options":[],"conceptId":"chemistry_chemical_reactions_reactants","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"Reactants"}', 2),
  (3432, 809, 'A learner writes Mg + O₂ → MgO and identifies MgO as a reactant. Explain the error.', 'text', 1, 'Compare the position of MgO with the position of the arrow.', '{"why":"The position relative to the reaction arrow distinguishes reactants from products.","sol":"Step 1: Locate the arrow in the equation.\nStep 2: Identify Mg and O₂ on the left.\nStep 3: Identify MgO on the right and classify it as the product.","steps":["Step 1: Locate the arrow in the equation.","Step 2: Identify Mg and O₂ on the left.","Step 3: Identify MgO on the right and classify it as the product."],"options":[],"conceptId":"chemistry_chemical_reactions_reactants","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"Reactants"}', 3),
  (3433, 809, 'In 2Mg + O₂ → 2MgO, how many different reactant substances are represented?', 'text', 1, 'Count different chemical formulas on the left, not the coefficients.', '{"why":"The coefficient 2 changes the amount represented, not the identity of magnesium.","sol":"Step 1: Read the left-hand side: 2Mg + O₂.\nStep 2: Identify the formulas Mg and O₂.\nStep 3: Count the different substances, ignoring the coefficient when counting substance types.","steps":["Step 1: Read the left-hand side: 2Mg + O₂.","Step 2: Identify the formulas Mg and O₂.","Step 3: Count the different substances, ignoring the coefficient when counting substance types."],"options":[],"conceptId":"chemistry_chemical_reactions_reactants","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q5","subject":"chemistry","chapter":"chemical_reactions","topic":"Reactants"}', 4),
  (3434, 809, 'In Zn + 2HCl → ZnCl₂ + H₂, a student says hydrogen gas is a reactant because it contains hydrogen. Is the student correct?', 'text', 1, 'Use the position of H₂ in the equation rather than the element''s name.', '{"why":"Reactant or product status depends on the substance''s role and position in the equation, not simply on the element it contains.","sol":"Step 1: Locate the arrow.\nStep 2: Identify Zn and HCl on the left as the reactants.\nStep 3: Find H₂ on the right and identify it as a product.","steps":["Step 1: Locate the arrow.","Step 2: Identify Zn and HCl on the left as the reactants.","Step 3: Find H₂ on the right and identify it as a product."],"options":[],"conceptId":"chemistry_chemical_reactions_reactants","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q6","subject":"chemistry","chapter":"chemical_reactions","topic":"Reactants"}', 5),
  (3435, 809, 'In N₂ + 3H₂ → 2NH₃, identify all reactants and state what the coefficient 3 means.', 'text', 1, 'Separate the names of the substances from the numbers written before their formulas.', '{"why":"Coefficients describe relative amounts, while the chemical formulas identify the reactant substances.","sol":"Step 1: Read the left-hand side: N₂ + 3H₂.\nStep 2: Identify N₂ as nitrogen and H₂ as hydrogen.\nStep 3: Interpret 3H₂ as three hydrogen molecules represented in the balanced equation.","steps":["Step 1: Read the left-hand side: N₂ + 3H₂.","Step 2: Identify N₂ as nitrogen and H₂ as hydrogen.","Step 3: Interpret 3H₂ as three hydrogen molecules represented in the balanced equation."],"options":[],"conceptId":"chemistry_chemical_reactions_reactants","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q7","subject":"chemistry","chapter":"chemical_reactions","topic":"Reactants"}', 6),
  (3436, 809, 'For the equation CaCO₃ → CaO + CO₂, a student lists CaO and CO₂ as the reactants. Correct the answer and explain why.', 'text', 1, 'Trace the arrow from left to right.', '{"why":"Calcium carbonate decomposes to form calcium oxide and carbon dioxide; the arrow separates starting substances from formed substances.","sol":"Step 1: Identify CaCO₃ on the left of the arrow.\nStep 2: Identify CaO and CO₂ on the right of the arrow.\nStep 3: Classify the left-hand substance as the reactant and the right-hand substances as products.","steps":["Step 1: Identify CaCO₃ on the left of the arrow.","Step 2: Identify CaO and CO₂ on the right of the arrow.","Step 3: Classify the left-hand substance as the reactant and the right-hand substances as products."],"options":[],"conceptId":"chemistry_chemical_reactions_reactants","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q8","subject":"chemistry","chapter":"chemical_reactions","topic":"Reactants"}', 7),
  (3437, 809, 'In C + O₂ → CO₂, a student says there is only one reactant because there is one product. Explain why this is incorrect.', 'text', 1, 'Count the substances on the left independently of the number on the right.', '{"why":"The number of reactants does not have to equal the number of products.","sol":"Step 1: Read the left-hand side: C + O₂.\nStep 2: Identify carbon and oxygen as two different reactants.\nStep 3: Read the right-hand side: CO₂, which is one product substance.","steps":["Step 1: Read the left-hand side: C + O₂.","Step 2: Identify carbon and oxygen as two different reactants.","Step 3: Read the right-hand side: CO₂, which is one product substance."],"options":[],"conceptId":"chemistry_chemical_reactions_reactants","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q9","subject":"chemistry","chapter":"chemical_reactions","topic":"Reactants"}', 8),
  (3438, 810, 'Identify the product in 2Mg + O₂ → 2MgO.', 'text', 1, 'Read the right-hand side of the arrow.', '{"why":"Magnesium oxide is formed when magnesium reacts with oxygen, so it is the product.","sol":"Step 1: Locate the reaction arrow.\nStep 2: Read the right-hand side: 2MgO.\nStep 3: Identify MgO as magnesium oxide.","steps":["Step 1: Locate the reaction arrow.","Step 2: Read the right-hand side: 2MgO.","Step 3: Identify MgO as magnesium oxide."],"options":[],"conceptId":"chemistry_chemical_reactions_products","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"Products"}', 0),
  (3439, 810, 'Name all the products in CaCO₃ → CaO + CO₂.', 'text', 1, 'There are two formulas on the right-hand side.', '{"why":"Both substances are formed when calcium carbonate decomposes.","sol":"Step 1: Locate the arrow.\nStep 2: Read the right-hand side: CaO + CO₂.\nStep 3: Name CaO as calcium oxide and CO₂ as carbon dioxide.","steps":["Step 1: Locate the arrow.","Step 2: Read the right-hand side: CaO + CO₂.","Step 3: Name CaO as calcium oxide and CO₂ as carbon dioxide."],"options":[],"conceptId":"chemistry_chemical_reactions_products","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"Products"}', 1),
  (3440, 810, 'In N₂ + 3H₂ → 2NH₃, what is the product, and what does the coefficient 2 indicate?', 'text', 1, 'Separate the identity of the substance from the quantity represented.', '{"why":"The formula identifies the substance, while the coefficient indicates the relative quantity in the balanced equation.","sol":"Step 1: Read the right-hand side: 2NH₃.\nStep 2: Identify NH₃ as ammonia.\nStep 3: Interpret the coefficient 2 as two ammonia molecules.","steps":["Step 1: Read the right-hand side: 2NH₃.","Step 2: Identify NH₃ as ammonia.","Step 3: Interpret the coefficient 2 as two ammonia molecules."],"options":[],"conceptId":"chemistry_chemical_reactions_products","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"Products"}', 2),
  (3441, 810, 'A learner identifies oxygen as the product in 2H₂ + O₂ → 2H₂O. Correct the answer.', 'text', 1, 'Check whether oxygen is to the left or right of the arrow.', '{"why":"Oxygen is on the left-hand side, so it is a reactant in this equation.","sol":"Step 1: Locate the arrow.\nStep 2: Identify H₂ and O₂ on the left as reactants.\nStep 3: Identify H₂O on the right as the product.","steps":["Step 1: Locate the arrow.","Step 2: Identify H₂ and O₂ on the left as reactants.","Step 3: Identify H₂O on the right as the product."],"options":[],"conceptId":"chemistry_chemical_reactions_products","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"Products"}', 3),
  (3442, 810, 'In Zn + 2HCl → ZnCl₂ + H₂, how many different product substances are formed, and what are their names?', 'text', 1, 'Count the different formulas to the right of the arrow.', '{"why":"The two different formulas on the right represent two product substances.","sol":"Step 1: Read the right-hand side: ZnCl₂ + H₂.\nStep 2: Identify ZnCl₂ as zinc chloride.\nStep 3: Identify H₂ as hydrogen gas.","steps":["Step 1: Read the right-hand side: ZnCl₂ + H₂.","Step 2: Identify ZnCl₂ as zinc chloride.","Step 3: Identify H₂ as hydrogen gas."],"options":[],"conceptId":"chemistry_chemical_reactions_products","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q5","subject":"chemistry","chapter":"chemical_reactions","topic":"Products"}', 4),
  (3443, 810, 'A student says that CaO is a reactant in CaCO₃ → CaO + CO₂ because it contains calcium. Explain the mistake.', 'text', 1, 'The position in the equation matters more than the element present.', '{"why":"A substance''s role is determined by its position and role in the reaction, not simply by which elements it contains.","sol":"Step 1: Locate the arrow.\nStep 2: Find CaCO₃ on the left and CaO on the right.\nStep 3: Classify CaCO₃ as the reactant and CaO as a product.","steps":["Step 1: Locate the arrow.","Step 2: Find CaCO₃ on the left and CaO on the right.","Step 3: Classify CaCO₃ as the reactant and CaO as a product."],"options":[],"conceptId":"chemistry_chemical_reactions_products","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q6","subject":"chemistry","chapter":"chemical_reactions","topic":"Products"}', 5),
  (3444, 810, 'In C + O₂ → CO₂, there are two reactants but only one product. Is this possible? Explain.', 'text', 1, 'Consider whether several starting substances can form one new substance.', '{"why":"The number of reactants does not have to equal the number of products.","sol":"Step 1: Identify carbon and oxygen as the two reactants.\nStep 2: Identify carbon dioxide as the single product.\nStep 3: Recognise that the atoms combine to form one type of product substance.","steps":["Step 1: Identify carbon and oxygen as the two reactants.","Step 2: Identify carbon dioxide as the single product.","Step 3: Recognise that the atoms combine to form one type of product substance."],"options":[],"conceptId":"chemistry_chemical_reactions_products","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q7","subject":"chemistry","chapter":"chemical_reactions","topic":"Products"}', 6),
  (3445, 810, 'In 2KClO₃ → 2KCl + 3O₂, identify the products and explain why there are two product substances.', 'text', 1, 'Read both formulas on the right-hand side.', '{"why":"Potassium chlorate decomposes into two different substances under suitable heating conditions.","sol":"Step 1: Locate the arrow.\nStep 2: Identify KCl and O₂ on the right.\nStep 3: Name them potassium chloride and oxygen gas.","steps":["Step 1: Locate the arrow.","Step 2: Identify KCl and O₂ on the right.","Step 3: Name them potassium chloride and oxygen gas."],"options":[],"conceptId":"chemistry_chemical_reactions_products","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q8","subject":"chemistry","chapter":"chemical_reactions","topic":"Products"}', 7),
  (3446, 810, 'A student writes that the product of Fe + S → FeS is sulfur because sulfur appears in the equation. Identify the actual product.', 'text', 1, 'Find the formula on the right-hand side.', '{"why":"Sulfur is a reactant in this equation. Iron sulfide is the new substance formed.","sol":"Step 1: Locate the arrow.\nStep 2: Read the right-hand side: FeS.\nStep 3: Identify FeS as iron sulfide.","steps":["Step 1: Locate the arrow.","Step 2: Read the right-hand side: FeS.","Step 3: Identify FeS as iron sulfide."],"options":[],"conceptId":"chemistry_chemical_reactions_products","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q9","subject":"chemistry","chapter":"chemical_reactions","topic":"Products"}', 8),
  (3447, 811, 'Dilute hydrochloric acid reacts with calcium carbonate. Bubbles form, and the gas turns limewater milky. What evidence supports a chemical reaction?', 'text', 1, 'Use both the observation and the gas test result.', '{"why":"The gas test provides stronger evidence than bubbles alone because boiling can also produce bubbles.","sol":"Step 1: Observe the bubbles, which indicate gas production.\nStep 2: Use the limewater test to identify the gas as carbon dioxide.\nStep 3: Conclude that a new substance has formed.","steps":["Step 1: Observe the bubbles, which indicate gas production.","Step 2: Use the limewater test to identify the gas as carbon dioxide.","Step 3: Conclude that a new substance has formed."],"options":[],"conceptId":"chemistry_chemical_reactions_signs_of_chemical_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"Signs of Chemical Reactions"}', 0),
  (3448, 811, 'Two colourless solutions are mixed, and an insoluble yellow solid forms. Name the sign of a chemical reaction.', 'text', 1, 'What is an insoluble solid formed from solutions called?', '{"why":"A precipitate can indicate that new substances formed when the solutions reacted.","sol":"Step 1: Observe that a solid appears after mixing.\nStep 2: Recognise that the solid is insoluble in the solution.\nStep 3: Name this type of solid a precipitate.","steps":["Step 1: Observe that a solid appears after mixing.","Step 2: Recognise that the solid is insoluble in the solution.","Step 3: Name this type of solid a precipitate."],"options":[],"conceptId":"chemistry_chemical_reactions_signs_of_chemical_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"Signs of Chemical Reactions"}', 1),
  (3449, 811, 'A reaction releases heat, making the surroundings warmer. What type of reaction is indicated by this energy change?', 'text', 1, 'Distinguish releasing heat from absorbing heat.', '{"why":"Exothermic reactions release energy to their surroundings, often causing a temperature rise.","sol":"Step 1: Observe that heat is released.\nStep 2: Recognise that energy passes from the reacting system to the surroundings.\nStep 3: Classify the reaction as exothermic.","steps":["Step 1: Observe that heat is released.","Step 2: Recognise that energy passes from the reacting system to the surroundings.","Step 3: Classify the reaction as exothermic."],"options":[],"conceptId":"chemistry_chemical_reactions_signs_of_chemical_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"Signs of Chemical Reactions"}', 2),
  (3450, 811, 'A liquid is heated and bubbles appear. A student concludes that a chemical reaction has definitely occurred. Why is this conclusion unreliable?', 'text', 1, 'Consider what happens when a liquid reaches its boiling point.', '{"why":"The same observation can result from a physical process or a chemical reaction.","sol":"Step 1: Recognise that bubbles can be formed by boiling.\nStep 2: Boiling is a physical change if the substance remains chemically unchanged.\nStep 3: Conclude that additional evidence is needed to show that a new substance formed.","steps":["Step 1: Recognise that bubbles can be formed by boiling.","Step 2: Boiling is a physical change if the substance remains chemically unchanged.","Step 3: Conclude that additional evidence is needed to show that a new substance formed."],"options":[],"conceptId":"chemistry_chemical_reactions_signs_of_chemical_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"Signs of Chemical Reactions"}', 3),
  (3451, 811, 'A reaction mixture becomes warmer without an external flame heating it. Which sign has been observed, and what does it suggest?', 'text', 1, 'Focus on the temperature of the mixture and its surroundings.', '{"why":"A reaction that releases heat can warm its surroundings, although the full experimental context should be considered.","sol":"Step 1: Identify the rise in temperature.\nStep 2: Consider whether the reaction is releasing energy.\nStep 3: Conclude that the observation is consistent with an exothermic reaction.","steps":["Step 1: Identify the rise in temperature.","Step 2: Consider whether the reaction is releasing energy.","Step 3: Conclude that the observation is consistent with an exothermic reaction."],"options":[],"conceptId":"chemistry_chemical_reactions_signs_of_chemical_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q5","subject":"chemistry","chapter":"chemical_reactions","topic":"Signs of Chemical Reactions"}', 4),
  (3452, 811, 'A white solid appears when two solutions are mixed. Explain why the observation is evidence of a chemical reaction but is not, by itself, complete proof.', 'text', 1, 'Think about the meaning of a precipitate and the need to identify the solid.', '{"why":"Observations suggest explanations; appropriate tests help establish what actually happened.","sol":"Step 1: Observe the appearance of a solid after mixing.\nStep 2: Consider whether an insoluble product has formed.\nStep 3: Recognise that further evidence may be needed to confirm the identity and origin of the solid.","steps":["Step 1: Observe the appearance of a solid after mixing.","Step 2: Consider whether an insoluble product has formed.","Step 3: Recognise that further evidence may be needed to confirm the identity and origin of the solid."],"options":[],"conceptId":"chemistry_chemical_reactions_signs_of_chemical_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q6","subject":"chemistry","chapter":"chemical_reactions","topic":"Signs of Chemical Reactions"}', 5),
  (3453, 811, 'Burning magnesium produces a bright white light and a white powder. Identify two observations that support a chemical reaction.', 'text', 1, 'One observation involves energy, and the other involves a new solid.', '{"why":"The observations support the conclusion that magnesium reacted with oxygen to form a new substance.","sol":"Step 1: Identify the bright white light as an energy-related observation.\nStep 2: Identify the white powder as a product that differs from the original magnesium.\nStep 3: Connect the observations with the formation of magnesium oxide.","steps":["Step 1: Identify the bright white light as an energy-related observation.","Step 2: Identify the white powder as a product that differs from the original magnesium.","Step 3: Connect the observations with the formation of magnesium oxide."],"options":[],"conceptId":"chemistry_chemical_reactions_signs_of_chemical_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q7","subject":"chemistry","chapter":"chemical_reactions","topic":"Signs of Chemical Reactions"}', 6),
  (3454, 811, 'Ice melts and becomes liquid water. Explain why the change in appearance and temperature does not establish that a chemical reaction occurred.', 'text', 1, 'Compare the chemical formula before and after melting.', '{"why":"Changes in appearance or temperature alone are not sufficient to establish a chemical reaction.","sol":"Step 1: Identify ice and liquid water as H₂O.\nStep 2: Recognise that only the physical state changes.\nStep 3: Conclude that no new substance forms.","steps":["Step 1: Identify ice and liquid water as H₂O.","Step 2: Recognise that only the physical state changes.","Step 3: Conclude that no new substance forms."],"options":[],"conceptId":"chemistry_chemical_reactions_signs_of_chemical_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q8","subject":"chemistry","chapter":"chemical_reactions","topic":"Signs of Chemical Reactions"}', 7),
  (3455, 811, 'A student observes effervescence when an acid is added to a carbonate. What additional evidence could help establish the identity of the gas?', 'text', 1, 'Recall the laboratory test for carbon dioxide.', '{"why":"A specific gas test helps identify the substance produced rather than relying on bubbles alone.","sol":"Step 1: Recognise that effervescence suggests gas production.\nStep 2: Pass the gas through limewater.\nStep 3: Look for limewater turning milky as evidence of carbon dioxide.","steps":["Step 1: Recognise that effervescence suggests gas production.","Step 2: Pass the gas through limewater.","Step 3: Look for limewater turning milky as evidence of carbon dioxide."],"options":[],"conceptId":"chemistry_chemical_reactions_signs_of_chemical_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q9","subject":"chemistry","chapter":"chemical_reactions","topic":"Signs of Chemical Reactions"}', 8),
  (3456, 812, '12 g of magnesium reacts completely with 8 g of oxygen to form magnesium oxide. Calculate the mass of magnesium oxide formed.', 'text', 1, 'Add the masses of all reactants.', '{"why":"The total mass of the products equals the total mass of the reactants when all substances are accounted for.","sol":"Step 1: Apply conservation of mass: total reactant mass = total product mass.\nStep 2: Add the reactant masses: 12 g + 8 g = 20 g.\nStep 3: Assign the total mass to the only product, magnesium oxide.","steps":["Step 1: Apply conservation of mass: total reactant mass = total product mass.","Step 2: Add the reactant masses: 12 g + 8 g = 20 g.","Step 3: Assign the total mass to the only product, magnesium oxide."],"options":[],"conceptId":"chemistry_chemical_reactions_conservation_of_mass","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"Conservation of Mass"}', 0),
  (3457, 812, 'A reaction forms 50 g of products. One reactant has a mass of 18 g. Calculate the mass of the second reactant if these are the only reactants.', 'text', 1, 'Subtract the known reactant mass from the total product mass.', '{"why":"The combined mass of the reactants must equal the total mass of the products.","sol":"Step 1: Write 18 g + x = 50 g.\nStep 2: Subtract 18 g from both sides.\nStep 3: Calculate x = 50 g − 18 g = 32 g.","steps":["Step 1: Write 18 g + x = 50 g.","Step 2: Subtract 18 g from both sides.","Step 3: Calculate x = 50 g − 18 g = 32 g."],"options":[],"conceptId":"chemistry_chemical_reactions_conservation_of_mass","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"Conservation of Mass"}', 1),
  (3458, 812, 'A reaction in an open flask produces a gas that escapes. The measured mass of the flask and remaining contents decreases. Has mass been destroyed?', 'text', 1, 'Consider whether all the products are still being weighed.', '{"why":"A balance measures the matter included in the measurement, not matter that has escaped from the container.","sol":"Step 1: Identify the escaping gas as matter produced by the reaction.\nStep 2: Recognise that the gas is no longer included in the measured mass.\nStep 3: Account for the gas to compare the total mass of all reactants and products.","steps":["Step 1: Identify the escaping gas as matter produced by the reaction.","Step 2: Recognise that the gas is no longer included in the measured mass.","Step 3: Account for the gas to compare the total mass of all reactants and products."],"options":[],"conceptId":"chemistry_chemical_reactions_conservation_of_mass","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"Conservation of Mass"}', 2),
  (3459, 812, 'When 7 g of substance A reacts completely with 13 g of substance B, only one product forms. Calculate the product''s mass.', 'text', 1, 'Use the total mass of both reactants.', '{"why":"The mass of the single product equals the combined mass of the reactants.","sol":"Step 1: Add the reactant masses: 7 g + 13 g.\nStep 2: Calculate the total: 20 g.\nStep 3: Since there is one product and all matter is accounted for, its mass is 20 g.","steps":["Step 1: Add the reactant masses: 7 g + 13 g.","Step 2: Calculate the total: 20 g.","Step 3: Since there is one product and all matter is accounted for, its mass is 20 g."],"options":[],"conceptId":"chemistry_chemical_reactions_conservation_of_mass","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"Conservation of Mass"}', 3),
  (3460, 812, 'A student records 24 g of reactants but only 21 g of products in a closed system. Assuming measurement errors are excluded, what should the student investigate?', 'text', 1, 'Mass should be conserved in a properly accounted-for closed system.', '{"why":"A mass difference indicates that the stated measurements or assumptions are incomplete or inconsistent with conservation of mass.","sol":"Step 1: Compare the recorded masses: 24 g and 21 g.\nStep 2: Recognise that they differ by 3 g.\nStep 3: Check whether the reaction or the mass records omitted a substance or whether the system was truly closed.","steps":["Step 1: Compare the recorded masses: 24 g and 21 g.","Step 2: Recognise that they differ by 3 g.","Step 3: Check whether the reaction or the mass records omitted a substance or whether the system was truly closed."],"options":[],"conceptId":"chemistry_chemical_reactions_conservation_of_mass","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q5","subject":"chemistry","chapter":"chemical_reactions","topic":"Conservation of Mass"}', 4),
  (3461, 812, 'A product has a total mass of 42 g. The two reactants have masses of 17 g and x g. Calculate x.', 'text', 1, 'Set the total reactant mass equal to 42 g.', '{"why":"The missing reactant mass is the total mass minus the known reactant mass.","sol":"Step 1: Write 17 g + x = 42 g.\nStep 2: Subtract 17 g from both sides.\nStep 3: Calculate x = 25 g.","steps":["Step 1: Write 17 g + x = 42 g.","Step 2: Subtract 17 g from both sides.","Step 3: Calculate x = 25 g."],"options":[],"conceptId":"chemistry_chemical_reactions_conservation_of_mass","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q6","subject":"chemistry","chapter":"chemical_reactions","topic":"Conservation of Mass"}', 5),
  (3462, 812, 'A student says mass is lost when wood burns because the ash weighs less than the original wood. Explain the error.', 'text', 1, 'What happens to gases and vapours during burning?', '{"why":"The apparent mass loss occurs because the measurement excludes matter that has entered the surrounding air.","sol":"Step 1: Recognise that burning produces gases and vapours as well as solid ash.\nStep 2: Identify that many products escape into the air.\nStep 3: Include all gaseous and solid products when comparing total mass.","steps":["Step 1: Recognise that burning produces gases and vapours as well as solid ash.","Step 2: Identify that many products escape into the air.","Step 3: Include all gaseous and solid products when comparing total mass."],"options":[],"conceptId":"chemistry_chemical_reactions_conservation_of_mass","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q7","subject":"chemistry","chapter":"chemical_reactions","topic":"Conservation of Mass"}', 6),
  (3463, 812, 'In a closed container, 16 g of reactants form two products. One product has a mass of 9 g. Calculate the mass of the second product.', 'text', 1, 'The combined mass of the products must equal 16 g.', '{"why":"The combined mass of both products equals the total reactant mass.","sol":"Step 1: Write 9 g + x = 16 g.\nStep 2: Subtract 9 g from both sides.\nStep 3: Calculate x = 7 g.","steps":["Step 1: Write 9 g + x = 16 g.","Step 2: Subtract 9 g from both sides.","Step 3: Calculate x = 7 g."],"options":[],"conceptId":"chemistry_chemical_reactions_conservation_of_mass","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q8","subject":"chemistry","chapter":"chemical_reactions","topic":"Conservation of Mass"}', 7),
  (3464, 812, 'Why must a gas produced during a reaction be collected or accounted for when checking conservation of mass?', 'text', 1, 'Think about what a balance measures if gas escapes.', '{"why":"A valid conservation-of-mass comparison must include all reactants and products.","sol":"Step 1: Recognise that a gas is matter and has mass.\nStep 2: Understand that escaped gas is not included in the container''s measured mass.\nStep 3: Account for the gas to compare the complete masses before and after the reaction.","steps":["Step 1: Recognise that a gas is matter and has mass.","Step 2: Understand that escaped gas is not included in the container''s measured mass.","Step 3: Account for the gas to compare the complete masses before and after the reaction."],"options":[],"conceptId":"chemistry_chemical_reactions_conservation_of_mass","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q9","subject":"chemistry","chapter":"chemical_reactions","topic":"Conservation of Mass"}', 8),
  (3465, 813, 'Interpret the equation Fe + S → FeS in words.', 'text', 1, 'Name each formula and identify the product.', '{"why":"The equation shows iron and sulfur as reactants and iron sulfide as the product.","sol":"Step 1: Identify Fe as iron.\nStep 2: Identify S as sulfur.\nStep 3: Identify FeS as iron sulfide.","steps":["Step 1: Identify Fe as iron.","Step 2: Identify S as sulfur.","Step 3: Identify FeS as iron sulfide."],"options":[],"conceptId":"chemistry_chemical_reactions_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"Chemical Equations"}', 0),
  (3466, 813, 'In CaCO₃ → CaO + CO₂, name the reactant and both products.', 'text', 1, 'Read the left and right sides separately.', '{"why":"The arrow separates the starting substance from the two substances formed.","sol":"Step 1: Identify CaCO₃ as calcium carbonate on the left.\nStep 2: Identify CaO as calcium oxide on the right.\nStep 3: Identify CO₂ as carbon dioxide on the right.","steps":["Step 1: Identify CaCO₃ as calcium carbonate on the left.","Step 2: Identify CaO as calcium oxide on the right.","Step 3: Identify CO₂ as carbon dioxide on the right."],"options":[],"conceptId":"chemistry_chemical_reactions_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"Chemical Equations"}', 1),
  (3467, 813, 'In 2H₂ + O₂ → 2H₂O, what does the coefficient 2 before H₂O represent?', 'text', 1, 'The coefficient indicates quantity, not a new chemical formula.', '{"why":"A coefficient states how many molecules or formula units are represented.","sol":"Step 1: Identify H₂O as water.\nStep 2: Notice the coefficient 2 immediately before the formula.\nStep 3: Interpret it as two water molecules in the equation.","steps":["Step 1: Identify H₂O as water.","Step 2: Notice the coefficient 2 immediately before the formula.","Step 3: Interpret it as two water molecules in the equation."],"options":[],"conceptId":"chemistry_chemical_reactions_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"Chemical Equations"}', 2),
  (3468, 813, 'A student reads NaOH + HCl → NaCl + H₂O and says that water is a reactant. Correct the interpretation.', 'text', 1, 'Locate H₂O relative to the arrow.', '{"why":"The position of a substance relative to the arrow identifies its role in the written equation.","sol":"Step 1: Identify NaOH and HCl on the left.\nStep 2: Identify NaCl and H₂O on the right.\nStep 3: Classify the substances on the right as products.","steps":["Step 1: Identify NaOH and HCl on the left.","Step 2: Identify NaCl and H₂O on the right.","Step 3: Classify the substances on the right as products."],"options":[],"conceptId":"chemistry_chemical_reactions_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"Chemical Equations"}', 3),
  (3469, 813, 'What does the plus sign mean in C + O₂ → CO₂?', 'text', 1, 'Consider what the sign separates on the left side.', '{"why":"A plus sign separates different substances on the same side of a chemical equation.","sol":"Step 1: Identify C as carbon.\nStep 2: Identify O₂ as oxygen.\nStep 3: Recognise that the plus sign separates the two reactant substances.","steps":["Step 1: Identify C as carbon.","Step 2: Identify O₂ as oxygen.","Step 3: Recognise that the plus sign separates the two reactant substances."],"options":[],"conceptId":"chemistry_chemical_reactions_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q5","subject":"chemistry","chapter":"chemical_reactions","topic":"Chemical Equations"}', 4),
  (3470, 813, 'A student claims that Mg + O₂ → MgO is balanced because magnesium appears on both sides. Identify the problem.', 'text', 1, 'Count atoms of every element on both sides.', '{"why":"Every element must have equal atom counts on both sides of a balanced equation.","sol":"Step 1: Count magnesium atoms: one on each side.\nStep 2: Count oxygen atoms: two on the left and one on the right.\nStep 3: Conclude that the equation is not balanced because oxygen atom counts differ.","steps":["Step 1: Count magnesium atoms: one on each side.","Step 2: Count oxygen atoms: two on the left and one on the right.","Step 3: Conclude that the equation is not balanced because oxygen atom counts differ."],"options":[],"conceptId":"chemistry_chemical_reactions_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q6","subject":"chemistry","chapter":"chemical_reactions","topic":"Chemical Equations"}', 5),
  (3471, 813, 'In 2KClO₃ → 2KCl + 3O₂, identify the reactant and products.', 'text', 1, 'Use the arrow to separate the starting substance from the formed substances.', '{"why":"The left-hand formula represents the starting substance, while the formulas on the right represent products.","sol":"Step 1: Read the left-hand side: KClO₃.\nStep 2: Identify it as potassium chlorate.\nStep 3: Read the right-hand side and identify KCl as potassium chloride and O₂ as oxygen.","steps":["Step 1: Read the left-hand side: KClO₃.","Step 2: Identify it as potassium chlorate.","Step 3: Read the right-hand side and identify KCl as potassium chloride and O₂ as oxygen."],"options":[],"conceptId":"chemistry_chemical_reactions_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q7","subject":"chemistry","chapter":"chemical_reactions","topic":"Chemical Equations"}', 6),
  (3472, 813, 'Explain the difference between 2H₂ and H₂ in a chemical equation.', 'text', 1, 'Distinguish a coefficient from a subscript.', '{"why":"The subscript 2 describes the atoms in each molecule, while the coefficient 2 describes the number of molecules.","sol":"Step 1: Identify H₂ as one hydrogen molecule containing two hydrogen atoms.\nStep 2: Recognise the coefficient 2 before H₂ as a quantity indicator.\nStep 3: Interpret 2H₂ as two hydrogen molecules, containing four hydrogen atoms in total.","steps":["Step 1: Identify H₂ as one hydrogen molecule containing two hydrogen atoms.","Step 2: Recognise the coefficient 2 before H₂ as a quantity indicator.","Step 3: Interpret 2H₂ as two hydrogen molecules, containing four hydrogen atoms in total."],"options":[],"conceptId":"chemistry_chemical_reactions_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q8","subject":"chemistry","chapter":"chemical_reactions","topic":"Chemical Equations"}', 7),
  (3473, 813, 'A chemical equation has three different formulas on the left and one formula on the right. Must it be incorrect? Explain.', 'text', 1, 'Consider whether several reactants can form a single product.', '{"why":"The number of substances on each side does not have to be equal. Atom counts, rather than formula counts, must balance.","sol":"Step 1: Recognise that the left side lists the reactants.\nStep 2: Recognise that the right side lists the products.\nStep 3: Understand that different numbers of reactant and product substances are possible, provided the equation correctly represents the reaction and is balanced.","steps":["Step 1: Recognise that the left side lists the reactants.","Step 2: Recognise that the right side lists the products.","Step 3: Understand that different numbers of reactant and product substances are possible, provided the equation correctly represents the reaction and is balanced."],"options":[],"conceptId":"chemistry_chemical_reactions_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q9","subject":"chemistry","chapter":"chemical_reactions","topic":"Chemical Equations"}', 8),
  (3474, 814, 'Write a balanced chemical equation for magnesium reacting with oxygen to form magnesium oxide.', 'text', 1, 'Write the correct formulae first, then balance the oxygen and magnesium atoms.', '{"why":"The balanced equation has two magnesium atoms and two oxygen atoms on each side.","sol":"Step 1: Write the formulae: Mg, O₂ and MgO.\nStep 2: Start with Mg + O₂ → MgO.\nStep 3: Put 2 before MgO to balance oxygen, then put 2 before Mg to balance magnesium.","steps":["Step 1: Write the formulae: Mg, O₂ and MgO.","Step 2: Start with Mg + O₂ → MgO.","Step 3: Put 2 before MgO to balance oxygen, then put 2 before Mg to balance magnesium."],"options":[],"conceptId":"chemistry_chemical_reactions_writing_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"Writing Chemical Equations"}', 0),
  (3475, 814, 'Write a balanced chemical equation for zinc reacting with hydrochloric acid to form zinc chloride and hydrogen gas.', 'text', 1, 'Zinc chloride is ZnCl₂ and hydrogen gas is H₂.', '{"why":"Both sides contain one zinc atom, two hydrogen atoms and two chlorine atoms.","sol":"Step 1: Write the unbalanced equation: Zn + HCl → ZnCl₂ + H₂.\nStep 2: Balance chlorine by putting 2 before HCl.\nStep 3: Check that hydrogen, zinc and chlorine atoms now balance.","steps":["Step 1: Write the unbalanced equation: Zn + HCl → ZnCl₂ + H₂.","Step 2: Balance chlorine by putting 2 before HCl.","Step 3: Check that hydrogen, zinc and chlorine atoms now balance."],"options":[],"conceptId":"chemistry_chemical_reactions_writing_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"Writing Chemical Equations"}', 1),
  (3476, 814, 'Write the chemical equation for calcium carbonate decomposing into calcium oxide and carbon dioxide. Is it balanced?', 'text', 1, 'Use CaCO₃, CaO and CO₂.', '{"why":"Both sides contain one calcium atom, one carbon atom and three oxygen atoms.","sol":"Step 1: Write calcium carbonate on the left: CaCO₃.\nStep 2: Write calcium oxide and carbon dioxide on the right: CaO + CO₂.\nStep 3: Count calcium, carbon and oxygen atoms on both sides.","steps":["Step 1: Write calcium carbonate on the left: CaCO₃.","Step 2: Write calcium oxide and carbon dioxide on the right: CaO + CO₂.","Step 3: Count calcium, carbon and oxygen atoms on both sides."],"options":[],"conceptId":"chemistry_chemical_reactions_writing_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"Writing Chemical Equations"}', 2),
  (3477, 814, 'A student writes magnesium + oxygen → magnesium oxide as Mg + O → MgO. What is wrong with the formula for elemental oxygen in this reaction?', 'text', 1, 'Recall the usual molecular formula of oxygen gas.', '{"why":"Using O instead of O₂ misrepresents the normal molecular form of oxygen gas.","sol":"Step 1: Identify oxygen gas as the elemental reactant.\nStep 2: Recall that oxygen gas normally exists as O₂ molecules.\nStep 3: Replace O with O₂ and then balance the equation.","steps":["Step 1: Identify oxygen gas as the elemental reactant.","Step 2: Recall that oxygen gas normally exists as O₂ molecules.","Step 3: Replace O with O₂ and then balance the equation."],"options":[],"conceptId":"chemistry_chemical_reactions_writing_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"Writing Chemical Equations"}', 3),
  (3478, 814, 'Write a balanced equation for hydrogen reacting with oxygen to form water.', 'text', 1, 'Use H₂, O₂ and H₂O.', '{"why":"Each side contains four hydrogen atoms and two oxygen atoms.","sol":"Step 1: Write the unbalanced equation: H₂ + O₂ → H₂O.\nStep 2: Put 2 before H₂O to balance oxygen.\nStep 3: Put 2 before H₂ to balance hydrogen.","steps":["Step 1: Write the unbalanced equation: H₂ + O₂ → H₂O.","Step 2: Put 2 before H₂O to balance oxygen.","Step 3: Put 2 before H₂ to balance hydrogen."],"options":[],"conceptId":"chemistry_chemical_reactions_writing_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q5","subject":"chemistry","chapter":"chemical_reactions","topic":"Writing Chemical Equations"}', 4),
  (3479, 814, 'A learner writes Zn + 2HCl → ZnCl + H₂ instead of ZnCl₂ as the zinc chloride formula. Why is this a problem?', 'text', 1, 'Check the correct chemical formula of zinc chloride.', '{"why":"Chemical formulae must correctly represent the composition of substances before an equation can be written accurately.","sol":"Step 1: Recall that zinc chloride has the formula ZnCl₂.\nStep 2: Recognise that ZnCl represents a different atom ratio.\nStep 3: Use ZnCl₂, then balance the full equation.","steps":["Step 1: Recall that zinc chloride has the formula ZnCl₂.","Step 2: Recognise that ZnCl represents a different atom ratio.","Step 3: Use ZnCl₂, then balance the full equation."],"options":[],"conceptId":"chemistry_chemical_reactions_writing_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q6","subject":"chemistry","chapter":"chemical_reactions","topic":"Writing Chemical Equations"}', 5),
  (3480, 814, 'Write the equation for iron reacting with sulfur to form iron sulfide. Use Fe, S and FeS.', 'text', 1, 'Place the starting substances on the left and the product on the right.', '{"why":"There is one iron atom and one sulfur atom on each side, so the equation is balanced.","sol":"Step 1: Identify iron and sulfur as reactants.\nStep 2: Write Fe + S on the left.\nStep 3: Write FeS on the right and check the atom counts.","steps":["Step 1: Identify iron and sulfur as reactants.","Step 2: Write Fe + S on the left.","Step 3: Write FeS on the right and check the atom counts."],"options":[],"conceptId":"chemistry_chemical_reactions_writing_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q7","subject":"chemistry","chapter":"chemical_reactions","topic":"Writing Chemical Equations"}', 6),
  (3481, 814, 'A student balances H₂ + O₂ → H₂O by changing H₂O to H₂O₂. Explain the mistake and give the balanced equation.', 'text', 1, 'Changing a subscript changes the substance itself.', '{"why":"Balancing must preserve the identity of every substance by changing coefficients rather than subscripts.","sol":"Step 1: Recognise that H₂O is water and H₂O₂ is hydrogen peroxide.\nStep 2: Keep the correct product formula H₂O.\nStep 3: Balance with coefficients: 2H₂ + O₂ → 2H₂O.","steps":["Step 1: Recognise that H₂O is water and H₂O₂ is hydrogen peroxide.","Step 2: Keep the correct product formula H₂O.","Step 3: Balance with coefficients: 2H₂ + O₂ → 2H₂O."],"options":[],"conceptId":"chemistry_chemical_reactions_writing_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q8","subject":"chemistry","chapter":"chemical_reactions","topic":"Writing Chemical Equations"}', 7),
  (3482, 814, 'Write a balanced equation for sodium reacting with chlorine to form sodium chloride. Use Na, Cl₂ and NaCl.', 'text', 1, 'Chlorine gas is diatomic, so start with Na + Cl₂ → NaCl.', '{"why":"Both sides contain two sodium atoms and two chlorine atoms.","sol":"Step 1: Write Na + Cl₂ → NaCl.\nStep 2: Put 2 before NaCl to balance chlorine.\nStep 3: Put 2 before Na to balance sodium.","steps":["Step 1: Write Na + Cl₂ → NaCl.","Step 2: Put 2 before NaCl to balance chlorine.","Step 3: Put 2 before Na to balance sodium."],"options":[],"conceptId":"chemistry_chemical_reactions_writing_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q9","subject":"chemistry","chapter":"chemical_reactions","topic":"Writing Chemical Equations"}', 8),
  (3483, 815, 'Interpret 2Mg(s) + O₂(g) → 2MgO(s), including the physical state of each substance.', 'text', 1, 'Translate each bracketed letter into its physical state.', '{"why":"State symbols show the physical states of the reactants and product.","sol":"Step 1: Mg(s) is solid magnesium.\nStep 2: O₂(g) is oxygen gas.\nStep 3: MgO(s) is solid magnesium oxide.","steps":["Step 1: Mg(s) is solid magnesium.","Step 2: O₂(g) is oxygen gas.","Step 3: MgO(s) is solid magnesium oxide."],"options":[],"conceptId":"chemistry_chemical_reactions_state_symbols","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"State Symbols"}', 0),
  (3484, 815, 'In AgNO₃(aq) + NaCl(aq) → AgCl(s) + NaNO₃(aq), which product is the solid?', 'text', 1, 'Look for the product followed by (s).', '{"why":"The state symbol (s) indicates that silver chloride is present as a solid.","sol":"Step 1: Identify the products on the right: AgCl and NaNO₃.\nStep 2: Read the state symbols.\nStep 3: Identify AgCl(s) as solid silver chloride.","steps":["Step 1: Identify the products on the right: AgCl and NaNO₃.","Step 2: Read the state symbols.","Step 3: Identify AgCl(s) as solid silver chloride."],"options":[],"conceptId":"chemistry_chemical_reactions_state_symbols","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"State Symbols"}', 1),
  (3485, 815, 'What is the difference between NaCl(s) and NaCl(aq)?', 'text', 1, 'The chemical formula is the same, but the state symbol changes.', '{"why":"State symbols identify physical state without changing the identity of sodium chloride.","sol":"Step 1: Interpret (s) as solid.\nStep 2: Interpret (aq) as dissolved in water.\nStep 3: Compare the physical forms of sodium chloride.","steps":["Step 1: Interpret (s) as solid.","Step 2: Interpret (aq) as dissolved in water.","Step 3: Compare the physical forms of sodium chloride."],"options":[],"conceptId":"chemistry_chemical_reactions_state_symbols","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"State Symbols"}', 2),
  (3486, 815, 'A student writes H₂O(aq) to represent pure liquid water. Which symbol is more appropriate, and why?', 'text', 1, 'Distinguish pure liquid water from a substance dissolved in water.', '{"why":"The aqueous symbol does not simply mean that a substance is watery or liquid.","sol":"Step 1: Recall that (l) means liquid.\nStep 2: Recall that (aq) means dissolved in water.\nStep 3: Choose the symbol that describes pure liquid water.","steps":["Step 1: Recall that (l) means liquid.","Step 2: Recall that (aq) means dissolved in water.","Step 3: Choose the symbol that describes pure liquid water."],"options":[],"conceptId":"chemistry_chemical_reactions_state_symbols","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"State Symbols"}', 3),
  (3487, 815, 'In CaCO₃(s) → CaO(s) + CO₂(g), identify the state of each substance.', 'text', 1, 'Translate each state symbol separately.', '{"why":"The symbols indicate that the reactant and one product are solids, while carbon dioxide is a gas.","sol":"Step 1: CaCO₃(s) is solid calcium carbonate.\nStep 2: CaO(s) is solid calcium oxide.\nStep 3: CO₂(g) is carbon dioxide gas.","steps":["Step 1: CaCO₃(s) is solid calcium carbonate.","Step 2: CaO(s) is solid calcium oxide.","Step 3: CO₂(g) is carbon dioxide gas."],"options":[],"conceptId":"chemistry_chemical_reactions_state_symbols","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q5","subject":"chemistry","chapter":"chemical_reactions","topic":"State Symbols"}', 4),
  (3488, 815, 'A reaction uses hydrochloric acid dissolved in water. Which state symbol normally indicates this solution?', 'text', 1, 'A dissolved substance in water is not represented by (l) merely because the solution flows.', '{"why":"The aqueous symbol identifies hydrochloric acid dissolved in water.","sol":"Step 1: Identify hydrochloric acid as a substance dissolved in water in the solution.\nStep 2: Recall the meaning of (aq).\nStep 3: Write the formula with the aqueous symbol.","steps":["Step 1: Identify hydrochloric acid as a substance dissolved in water in the solution.","Step 2: Recall the meaning of (aq).","Step 3: Write the formula with the aqueous symbol."],"options":[],"conceptId":"chemistry_chemical_reactions_state_symbols","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q6","subject":"chemistry","chapter":"chemical_reactions","topic":"State Symbols"}', 5),
  (3489, 815, 'A student says (g) means that a substance is dissolved in water. Correct the statement.', 'text', 1, 'Compare gas with aqueous.', '{"why":"The symbols describe different physical conditions and are not interchangeable.","sol":"Step 1: Recall that (g) means gas.\nStep 2: Recall that (aq) means dissolved in water.\nStep 3: Replace the incorrect meaning with the correct definition.","steps":["Step 1: Recall that (g) means gas.","Step 2: Recall that (aq) means dissolved in water.","Step 3: Replace the incorrect meaning with the correct definition."],"options":[],"conceptId":"chemistry_chemical_reactions_state_symbols","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q7","subject":"chemistry","chapter":"chemical_reactions","topic":"State Symbols"}', 6),
  (3490, 815, 'In 2H₂(g) + O₂(g) → 2H₂O(l), why is the product symbol (l) rather than (g) in this equation?', 'text', 1, 'The equation specifies the physical state of the water formed under the stated conditions.', '{"why":"A chemical formula identifies the substance, while the state symbol indicates its physical state.","sol":"Step 1: Identify hydrogen and oxygen as gases.\nStep 2: Read H₂O(l) as liquid water.\nStep 3: Explain that state symbols specify the physical state represented in the equation.","steps":["Step 1: Identify hydrogen and oxygen as gases.","Step 2: Read H₂O(l) as liquid water.","Step 3: Explain that state symbols specify the physical state represented in the equation."],"options":[],"conceptId":"chemistry_chemical_reactions_state_symbols","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q8","subject":"chemistry","chapter":"chemical_reactions","topic":"State Symbols"}', 7),
  (3491, 815, 'Two substances are dissolved in water and react to form an insoluble solid. Which state symbols could represent the reactants and the solid product?', 'text', 1, 'Use one symbol for dissolved substances and another for the solid.', '{"why":"Aqueous reactants can react in solution to produce a solid precipitate.","sol":"Step 1: Represent each dissolved reactant using (aq).\nStep 2: Represent the insoluble solid product using (s).\nStep 3: Combine these symbols with the appropriate formulae in the equation.","steps":["Step 1: Represent each dissolved reactant using (aq).","Step 2: Represent the insoluble solid product using (s).","Step 3: Combine these symbols with the appropriate formulae in the equation."],"options":[],"conceptId":"chemistry_chemical_reactions_state_symbols","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q9","subject":"chemistry","chapter":"chemical_reactions","topic":"State Symbols"}', 8),
  (3492, 816, 'Balance H₂ + O₂ → H₂O.', 'text', 1, 'Balance oxygen first, then recount hydrogen.', '{"why":"Both sides contain 4 hydrogen atoms and 2 oxygen atoms.","sol":"Step 1: Count O: 2 on the left and 1 on the right.\nStep 2: Put 2 before H₂O: H₂ + O₂ → 2H₂O.\nStep 3: There are now 4 H atoms on the right, so put 2 before H₂.","steps":["Step 1: Count O: 2 on the left and 1 on the right.","Step 2: Put 2 before H₂O: H₂ + O₂ → 2H₂O.","Step 3: There are now 4 H atoms on the right, so put 2 before H₂."],"options":[],"conceptId":"chemistry_chemical_reactions_balancing_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"Balancing Chemical Equations"}', 0),
  (3493, 816, 'Balance Mg + O₂ → MgO.', 'text', 1, 'The oxygen molecule contains two oxygen atoms.', '{"why":"The coefficients make the number of magnesium and oxygen atoms equal on both sides.","sol":"Step 1: Put 2 before MgO to balance oxygen.\nStep 2: Put 2 before Mg to balance magnesium.\nStep 3: Check that both sides have 2 Mg atoms and 2 O atoms.","steps":["Step 1: Put 2 before MgO to balance oxygen.","Step 2: Put 2 before Mg to balance magnesium.","Step 3: Check that both sides have 2 Mg atoms and 2 O atoms."],"options":[],"conceptId":"chemistry_chemical_reactions_balancing_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"Balancing Chemical Equations"}', 1),
  (3494, 816, 'Balance N₂ + H₂ → NH₃.', 'text', 1, 'Balance nitrogen first, then hydrogen.', '{"why":"Both sides contain 2 nitrogen atoms and 6 hydrogen atoms.","sol":"Step 1: Put 2 before NH₃ to balance nitrogen.\nStep 2: The right side now has 6 H atoms.\nStep 3: Put 3 before H₂ to give 6 H atoms on the left.","steps":["Step 1: Put 2 before NH₃ to balance nitrogen.","Step 2: The right side now has 6 H atoms.","Step 3: Put 3 before H₂ to give 6 H atoms on the left."],"options":[],"conceptId":"chemistry_chemical_reactions_balancing_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"Balancing Chemical Equations"}', 2),
  (3495, 816, 'A student balances H₂ + Cl₂ → HCl by writing H₂ + Cl₂ → HCl₂. Explain the mistake and give the correct balanced equation.', 'text', 1, 'Do not change the formula of hydrogen chloride.', '{"why":"Balancing changes coefficients, not subscripts. The balanced equation contains 2 hydrogen atoms and 2 chlorine atoms on each side.","sol":"Step 1: Recognise HCl as the formula for hydrogen chloride.\nStep 2: Count 2 H and 2 Cl atoms on the left but only 1 of each on the right.\nStep 3: Put 2 before HCl.","steps":["Step 1: Recognise HCl as the formula for hydrogen chloride.","Step 2: Count 2 H and 2 Cl atoms on the left but only 1 of each on the right.","Step 3: Put 2 before HCl."],"options":[],"conceptId":"chemistry_chemical_reactions_balancing_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"Balancing Chemical Equations"}', 3),
  (3496, 816, 'Balance Fe + O₂ → Fe₂O₃.', 'text', 1, 'Balance oxygen using a common multiple of 2 and 3, then balance iron.', '{"why":"Each side contains 4 iron atoms and 6 oxygen atoms.","sol":"Step 1: Fe₂O₃ contains 3 oxygen atoms; O₂ contains 2.\nStep 2: Use 2Fe₂O₃ to give 6 oxygen atoms, and 3O₂ to give 6 oxygen atoms.\nStep 3: The right side now has 4 iron atoms, so put 4 before Fe.","steps":["Step 1: Fe₂O₃ contains 3 oxygen atoms; O₂ contains 2.","Step 2: Use 2Fe₂O₃ to give 6 oxygen atoms, and 3O₂ to give 6 oxygen atoms.","Step 3: The right side now has 4 iron atoms, so put 4 before Fe."],"options":[],"conceptId":"chemistry_chemical_reactions_balancing_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q5","subject":"chemistry","chapter":"chemical_reactions","topic":"Balancing Chemical Equations"}', 4),
  (3497, 816, 'Balance Na + Cl₂ → NaCl.', 'text', 1, 'Balance the two chlorine atoms before balancing sodium.', '{"why":"Both sides contain 2 sodium atoms and 2 chlorine atoms.","sol":"Step 1: Cl₂ contains 2 chlorine atoms on the left.\nStep 2: Put 2 before NaCl to give 2 chlorine atoms on the right.\nStep 3: Put 2 before Na to balance sodium.","steps":["Step 1: Cl₂ contains 2 chlorine atoms on the left.","Step 2: Put 2 before NaCl to give 2 chlorine atoms on the right.","Step 3: Put 2 before Na to balance sodium."],"options":[],"conceptId":"chemistry_chemical_reactions_balancing_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q6","subject":"chemistry","chapter":"chemical_reactions","topic":"Balancing Chemical Equations"}', 5),
  (3498, 816, 'Balance Al + O₂ → Al₂O₃.', 'text', 1, 'Make the oxygen count a common multiple of 2 and 3.', '{"why":"Both sides contain 4 aluminium atoms and 6 oxygen atoms.","sol":"Step 1: Use 2Al₂O₃ to give 6 oxygen atoms on the right.\nStep 2: Use 3O₂ to give 6 oxygen atoms on the left.\nStep 3: Balance the 4 aluminium atoms on the right with 4Al on the left.","steps":["Step 1: Use 2Al₂O₃ to give 6 oxygen atoms on the right.","Step 2: Use 3O₂ to give 6 oxygen atoms on the left.","Step 3: Balance the 4 aluminium atoms on the right with 4Al on the left."],"options":[],"conceptId":"chemistry_chemical_reactions_balancing_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q7","subject":"chemistry","chapter":"chemical_reactions","topic":"Balancing Chemical Equations"}', 6),
  (3499, 816, 'A learner writes 2H₂ + O₂ → H₂O because the equation has hydrogen on both sides. Identify what remains unbalanced.', 'text', 1, 'Count the hydrogen atoms and oxygen atoms separately.', '{"why":"Each element must have the same number of atoms on both sides, not merely appear on both sides.","sol":"Step 1: Left side: 4 hydrogen atoms and 2 oxygen atoms.\nStep 2: Right side: 2 hydrogen atoms and 1 oxygen atom.\nStep 3: Put 2 before H₂O to balance both elements.","steps":["Step 1: Left side: 4 hydrogen atoms and 2 oxygen atoms.","Step 2: Right side: 2 hydrogen atoms and 1 oxygen atom.","Step 3: Put 2 before H₂O to balance both elements."],"options":[],"conceptId":"chemistry_chemical_reactions_balancing_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q8","subject":"chemistry","chapter":"chemical_reactions","topic":"Balancing Chemical Equations"}', 7),
  (3500, 816, 'Balance KClO₃ → KCl + O₂.', 'text', 1, 'Balance oxygen using 6 oxygen atoms, then balance potassium and chlorine together.', '{"why":"Both sides contain 2 potassium atoms, 2 chlorine atoms and 6 oxygen atoms.","sol":"Step 1: Use 2KClO₃ to give 6 oxygen atoms on the left.\nStep 2: Use 3O₂ to give 6 oxygen atoms on the right.\nStep 3: Put 2 before KCl to balance both potassium and chlorine.","steps":["Step 1: Use 2KClO₃ to give 6 oxygen atoms on the left.","Step 2: Use 3O₂ to give 6 oxygen atoms on the right.","Step 3: Put 2 before KCl to balance both potassium and chlorine."],"options":[],"conceptId":"chemistry_chemical_reactions_balancing_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q9","subject":"chemistry","chapter":"chemical_reactions","topic":"Balancing Chemical Equations"}', 8);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (3501, 817, 'Balance Al + O₂ → Al₂O₃.', 'text', 1, 'Make the oxygen total 6 on both sides before balancing aluminium.', '{"why":"Both sides contain 4 aluminium atoms and 6 oxygen atoms.","sol":"Step 1: Put 2 before Al₂O₃, giving 6 oxygen atoms and 4 aluminium atoms on the right.\nStep 2: Put 3 before O₂ to give 6 oxygen atoms on the left.\nStep 3: Put 4 before Al to balance aluminium.","steps":["Step 1: Put 2 before Al₂O₃, giving 6 oxygen atoms and 4 aluminium atoms on the right.","Step 2: Put 3 before O₂ to give 6 oxygen atoms on the left.","Step 3: Put 4 before Al to balance aluminium."],"options":[],"conceptId":"chemistry_chemical_reactions_balancing_equations_with_multiple_elements","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"Balancing Equations with Multiple Elements"}', 0),
  (3502, 817, 'Balance Ca(OH)₂ + HCl → CaCl₂ + H₂O.', 'text', 1, 'Balance chlorine first, then count all hydrogen and oxygen atoms.', '{"why":"Both sides contain 1 calcium, 2 chlorine, 4 hydrogen and 2 oxygen atoms.","sol":"Step 1: Put 2 before HCl to balance the two chlorine atoms in CaCl₂.\nStep 2: The left side now contains 4 hydrogen atoms and 2 oxygen atoms.\nStep 3: Put 2 before H₂O to balance hydrogen and oxygen.","steps":["Step 1: Put 2 before HCl to balance the two chlorine atoms in CaCl₂.","Step 2: The left side now contains 4 hydrogen atoms and 2 oxygen atoms.","Step 3: Put 2 before H₂O to balance hydrogen and oxygen."],"options":[],"conceptId":"chemistry_chemical_reactions_balancing_equations_with_multiple_elements","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"Balancing Equations with Multiple Elements"}', 1),
  (3503, 817, 'Balance C₃H₈ + O₂ → CO₂ + H₂O.', 'text', 1, 'Balance carbon, then hydrogen, then oxygen.', '{"why":"Both sides contain 3 carbon atoms, 8 hydrogen atoms and 10 oxygen atoms.","sol":"Step 1: Put 3 before CO₂ to balance carbon.\nStep 2: Put 4 before H₂O to balance the 8 hydrogen atoms.\nStep 3: The products contain 10 oxygen atoms, so put 5 before O₂.","steps":["Step 1: Put 3 before CO₂ to balance carbon.","Step 2: Put 4 before H₂O to balance the 8 hydrogen atoms.","Step 3: The products contain 10 oxygen atoms, so put 5 before O₂."],"options":[],"conceptId":"chemistry_chemical_reactions_balancing_equations_with_multiple_elements","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"Balancing Equations with Multiple Elements"}', 2),
  (3504, 817, 'Balance Fe₂O₃ + CO → Fe + CO₂.', 'text', 1, 'Balance iron first, then carbon and oxygen.', '{"why":"Both sides contain 2 iron atoms, 3 carbon atoms and 6 oxygen atoms.","sol":"Step 1: Put 2 before Fe to balance the two iron atoms.\nStep 2: Choose 3CO and 3CO₂ to balance carbon.\nStep 3: Check oxygen: the left has 3 + 3 = 6 atoms; the right has 6.","steps":["Step 1: Put 2 before Fe to balance the two iron atoms.","Step 2: Choose 3CO and 3CO₂ to balance carbon.","Step 3: Check oxygen: the left has 3 + 3 = 6 atoms; the right has 6."],"options":[],"conceptId":"chemistry_chemical_reactions_balancing_equations_with_multiple_elements","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"Balancing Equations with Multiple Elements"}', 3),
  (3505, 817, 'Balance Na₂CO₃ + HCl → NaCl + H₂O + CO₂.', 'text', 1, 'Balance sodium and chlorine together before checking hydrogen.', '{"why":"Both sides contain 2 sodium, 2 chlorine, 2 hydrogen, 1 carbon and 3 oxygen atoms.","sol":"Step 1: Na₂CO₃ contains 2 sodium atoms, so put 2 before NaCl.\nStep 2: Put 2 before HCl to supply 2 chlorine atoms.\nStep 3: Check hydrogen, carbon and oxygen; the remaining coefficients are 1.","steps":["Step 1: Na₂CO₃ contains 2 sodium atoms, so put 2 before NaCl.","Step 2: Put 2 before HCl to supply 2 chlorine atoms.","Step 3: Check hydrogen, carbon and oxygen; the remaining coefficients are 1."],"options":[],"conceptId":"chemistry_chemical_reactions_balancing_equations_with_multiple_elements","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q5","subject":"chemistry","chapter":"chemical_reactions","topic":"Balancing Equations with Multiple Elements"}', 4),
  (3506, 817, 'In Ca(OH)₂, how many oxygen and hydrogen atoms are present in one formula unit?', 'text', 1, 'The subscript 2 outside the brackets applies to both O and H.', '{"why":"A subscript outside brackets multiplies every atom inside the brackets.","sol":"Step 1: Read the bracketed group as OH.\nStep 2: The subscript 2 means there are two OH groups.\nStep 3: Count 2 oxygen atoms and 2 hydrogen atoms.","steps":["Step 1: Read the bracketed group as OH.","Step 2: The subscript 2 means there are two OH groups.","Step 3: Count 2 oxygen atoms and 2 hydrogen atoms."],"options":[],"conceptId":"chemistry_chemical_reactions_balancing_equations_with_multiple_elements","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q6","subject":"chemistry","chapter":"chemical_reactions","topic":"Balancing Equations with Multiple Elements"}', 5),
  (3507, 817, 'Balance KOH + H₂SO₄ → K₂SO₄ + H₂O.', 'text', 1, 'Balance potassium first. Sulfate remains intact on both sides.', '{"why":"Both sides contain 2 potassium, 1 sulfur, 4 hydrogen and 6 oxygen atoms.","sol":"Step 1: K₂SO₄ contains 2 potassium atoms, so put 2 before KOH.\nStep 2: The left side now has 4 hydrogen atoms in total, so put 2 before H₂O.\nStep 3: Check that sulfur and oxygen also balance.","steps":["Step 1: K₂SO₄ contains 2 potassium atoms, so put 2 before KOH.","Step 2: The left side now has 4 hydrogen atoms in total, so put 2 before H₂O.","Step 3: Check that sulfur and oxygen also balance."],"options":[],"conceptId":"chemistry_chemical_reactions_balancing_equations_with_multiple_elements","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q7","subject":"chemistry","chapter":"chemical_reactions","topic":"Balancing Equations with Multiple Elements"}', 6),
  (3508, 817, 'Balance C₂H₆ + O₂ → CO₂ + H₂O using the smallest whole-number coefficients.', 'text', 1, 'Balance carbon and hydrogen first; oxygen may initially give a fraction.', '{"why":"Both sides contain 4 carbon, 12 hydrogen and 14 oxygen atoms, and the coefficients are in the smallest whole-number ratio.","sol":"Step 1: Use 2C₂H₆ to give 4 carbon atoms and 12 hydrogen atoms.\nStep 2: Put 4 before CO₂ and 6 before H₂O.\nStep 3: The products contain 14 oxygen atoms, so put 7 before O₂.","steps":["Step 1: Use 2C₂H₆ to give 4 carbon atoms and 12 hydrogen atoms.","Step 2: Put 4 before CO₂ and 6 before H₂O.","Step 3: The products contain 14 oxygen atoms, so put 7 before O₂."],"options":[],"conceptId":"chemistry_chemical_reactions_balancing_equations_with_multiple_elements","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q8","subject":"chemistry","chapter":"chemical_reactions","topic":"Balancing Equations with Multiple Elements"}', 7),
  (3509, 817, 'A learner balances an equation containing SO₄ on both sides by treating the sulfate group as one unit. When is this shortcut valid?', 'text', 1, 'Compare whether the group remains chemically unchanged on both sides.', '{"why":"Counting an unchanged polyatomic group as a unit simplifies balancing without changing the atom count.","sol":"Step 1: Identify the sulfate group as SO₄.\nStep 2: Check that it appears intact in a formula on each side.\nStep 3: If the group remains unchanged, balance it as a unit; otherwise count the individual atoms.","steps":["Step 1: Identify the sulfate group as SO₄.","Step 2: Check that it appears intact in a formula on each side.","Step 3: If the group remains unchanged, balance it as a unit; otherwise count the individual atoms."],"options":[],"conceptId":"chemistry_chemical_reactions_balancing_equations_with_multiple_elements","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q9","subject":"chemistry","chapter":"chemical_reactions","topic":"Balancing Equations with Multiple Elements"}', 8),
  (3510, 818, 'What is a combination reaction?', 'text', 1, 'Count the reactants and products.', '{"why":"The defining pattern is multiple reactants producing a single product.","sol":"Step 1: Identify the substances that react on the left-hand side.\nStep 2: Identify the substances formed on the right-hand side.\nStep 3: Check whether two or more reactants form one product.","steps":["Step 1: Identify the substances that react on the left-hand side.","Step 2: Identify the substances formed on the right-hand side.","Step 3: Check whether two or more reactants form one product."],"options":[],"conceptId":"chemistry_chemical_reactions_combination_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"Combination Reactions"}', 0),
  (3511, 818, 'Classify the reaction: 2Mg + O₂ → 2MgO.', 'text', 1, 'Count the different substances before and after the arrow.', '{"why":"Magnesium and oxygen combine to form magnesium oxide.","sol":"Step 1: The reactants are magnesium and oxygen.\nStep 2: The only product is magnesium oxide.\nStep 3: Two reactants form one product.","steps":["Step 1: The reactants are magnesium and oxygen.","Step 2: The only product is magnesium oxide.","Step 3: Two reactants form one product."],"options":[],"conceptId":"chemistry_chemical_reactions_combination_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"Combination Reactions"}', 1),
  (3512, 818, 'Complete and balance the combination reaction: CaO + H₂O → ?', 'text', 1, 'Calcium oxide reacts with water to form calcium hydroxide.', '{"why":"The equation is balanced and has two reactants forming one product.","sol":"Step 1: Write the product formula as Ca(OH)₂.\nStep 2: Write the equation: CaO + H₂O → Ca(OH)₂.\nStep 3: Count atoms on both sides: Ca = 1, O = 2 and H = 2.","steps":["Step 1: Write the product formula as Ca(OH)₂.","Step 2: Write the equation: CaO + H₂O → Ca(OH)₂.","Step 3: Count atoms on both sides: Ca = 1, O = 2 and H = 2."],"options":[],"conceptId":"chemistry_chemical_reactions_combination_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"Combination Reactions"}', 2),
  (3513, 818, 'A learner says every reaction involving oxygen is a combination reaction. Is this correct?', 'text', 1, 'Classification depends on the number of reactants and products, not only on oxygen.', '{"why":"The presence of oxygen alone does not determine the reaction type.","sol":"Step 1: Recall that combination reactions form one product from two or more reactants.\nStep 2: Consider a reaction in which a substance reacts with oxygen but produces two different products.\nStep 3: Check whether the defining combination pattern is present.","steps":["Step 1: Recall that combination reactions form one product from two or more reactants.","Step 2: Consider a reaction in which a substance reacts with oxygen but produces two different products.","Step 3: Check whether the defining combination pattern is present."],"options":[],"conceptId":"chemistry_chemical_reactions_combination_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"Combination Reactions"}', 3),
  (3514, 818, 'Classify: Fe + S → FeS.', 'text', 1, 'Compare the number of reactants with the number of products.', '{"why":"The reaction follows the pattern of several reactants forming one product.","sol":"Step 1: Iron and sulphur are two reactants.\nStep 2: Iron(II) sulphide is the single product.\nStep 3: Two reactants form one product.","steps":["Step 1: Iron and sulphur are two reactants.","Step 2: Iron(II) sulphide is the single product.","Step 3: Two reactants form one product."],"options":[],"conceptId":"chemistry_chemical_reactions_combination_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q5","subject":"chemistry","chapter":"chemical_reactions","topic":"Combination Reactions"}', 4),
  (3515, 818, 'Which equation represents a combination reaction?', 'text', 1, 'Look for multiple reactants and one product.', '{"why":"Nitrogen and hydrogen combine to form ammonia as the only product.","sol":"Step 1: Examine the reactants on the left.\nStep 2: Count the products on the right.\nStep 3: Select the equation with two or more reactants and one product.","steps":["Step 1: Examine the reactants on the left.","Step 2: Count the products on the right.","Step 3: Select the equation with two or more reactants and one product."],"options":[],"conceptId":"chemistry_chemical_reactions_combination_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q6","subject":"chemistry","chapter":"chemical_reactions","topic":"Combination Reactions"}', 5),
  (3516, 818, 'A reaction has three reactants and one product. Can it be a combination reaction?', 'text', 1, 'The definition does not restrict the reaction to exactly two reactants.', '{"why":"Combination reactions can involve more than two reactants.","sol":"Step 1: Recall that a combination reaction involves two or more reactants.\nStep 2: Three reactants meet this requirement.\nStep 3: Check that only one product is formed.","steps":["Step 1: Recall that a combination reaction involves two or more reactants.","Step 2: Three reactants meet this requirement.","Step 3: Check that only one product is formed."],"options":[],"conceptId":"chemistry_chemical_reactions_combination_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q7","subject":"chemistry","chapter":"chemical_reactions","topic":"Combination Reactions"}', 6),
  (3517, 818, 'Why is Mg + O₂ → MgO not balanced as written?', 'text', 1, 'Count the oxygen atoms on each side.', '{"why":"A balanced equation has equal numbers of each type of atom on both sides.","sol":"Step 1: The left side contains two oxygen atoms in O₂.\nStep 2: The right side contains one oxygen atom in MgO.\nStep 3: Place 2 before MgO, then 2 before Mg.","steps":["Step 1: The left side contains two oxygen atoms in O₂.","Step 2: The right side contains one oxygen atom in MgO.","Step 3: Place 2 before MgO, then 2 before Mg."],"options":[],"conceptId":"chemistry_chemical_reactions_combination_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q8","subject":"chemistry","chapter":"chemical_reactions","topic":"Combination Reactions"}', 7),
  (3518, 818, 'A student sees two reactants and two products and labels the reaction a combination reaction. What is wrong with the reasoning?', 'text', 1, 'A combination reaction must form one product.', '{"why":"Both the reactant count and the product count matter when classifying the reaction.","sol":"Step 1: Count the reactants.\nStep 2: Count the products.\nStep 3: Compare the pattern with multiple reactants forming a single product.","steps":["Step 1: Count the reactants.","Step 2: Count the products.","Step 3: Compare the pattern with multiple reactants forming a single product."],"options":[],"conceptId":"chemistry_chemical_reactions_combination_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q9","subject":"chemistry","chapter":"chemical_reactions","topic":"Combination Reactions"}', 8),
  (3519, 819, 'What is a decomposition reaction?', 'text', 1, 'Focus on what happens to one starting substance.', '{"why":"Decomposition involves one reactant forming multiple products.","sol":"Step 1: Identify the starting reactant.\nStep 2: Check whether it breaks down.\nStep 3: Count the products formed.","steps":["Step 1: Identify the starting reactant.","Step 2: Check whether it breaks down.","Step 3: Count the products formed."],"options":[],"conceptId":"chemistry_chemical_reactions_decomposition_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"Decomposition Reactions"}', 0),
  (3520, 819, 'Classify: CaCO₃ → CaO + CO₂.', 'text', 1, 'Count the reactants and products.', '{"why":"Calcium carbonate breaks down into two different substances.","sol":"Step 1: Calcium carbonate is the single reactant.\nStep 2: Calcium oxide and carbon dioxide are two products.\nStep 3: One reactant forms two products.","steps":["Step 1: Calcium carbonate is the single reactant.","Step 2: Calcium oxide and carbon dioxide are two products.","Step 3: One reactant forms two products."],"options":[],"conceptId":"chemistry_chemical_reactions_decomposition_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"Decomposition Reactions"}', 1),
  (3521, 819, 'Balance: H₂O → H₂ + O₂.', 'text', 1, 'Balance oxygen first, then hydrogen.', '{"why":"Both sides contain four hydrogen atoms and two oxygen atoms.","sol":"Step 1: Place 2 before H₂O to balance oxygen.\nStep 2: There are now 4 hydrogen atoms on the left.\nStep 3: Place 2 before H₂.","steps":["Step 1: Place 2 before H₂O to balance oxygen.","Step 2: There are now 4 hydrogen atoms on the left.","Step 3: Place 2 before H₂."],"options":[],"conceptId":"chemistry_chemical_reactions_decomposition_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"Decomposition Reactions"}', 2),
  (3522, 819, 'A learner says decomposition means a substance disappears. Explain the mistake.', 'text', 1, 'Think about what happens to the atoms.', '{"why":"Chemical decomposition rearranges atoms rather than destroying them.","sol":"Step 1: A reactant breaks down into new substances.\nStep 2: Its atoms are rearranged into the products.\nStep 3: The atoms are conserved in an ordinary chemical reaction.","steps":["Step 1: A reactant breaks down into new substances.","Step 2: Its atoms are rearranged into the products.","Step 3: The atoms are conserved in an ordinary chemical reaction."],"options":[],"conceptId":"chemistry_chemical_reactions_decomposition_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"Decomposition Reactions"}', 3),
  (3523, 819, 'Classify: 2KClO₃ → 2KCl + 3O₂.', 'text', 1, 'Count the starting substances, not the balancing coefficients.', '{"why":"The reaction follows the pattern of one reactant breaking down into multiple products.","sol":"Step 1: Potassium chlorate is the only reactant substance.\nStep 2: Potassium chloride and oxygen are two product substances.\nStep 3: One reactant produces two products.","steps":["Step 1: Potassium chlorate is the only reactant substance.","Step 2: Potassium chloride and oxygen are two product substances.","Step 3: One reactant produces two products."],"options":[],"conceptId":"chemistry_chemical_reactions_decomposition_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q5","subject":"chemistry","chapter":"chemical_reactions","topic":"Decomposition Reactions"}', 4),
  (3524, 819, 'Which energy source is used to decompose water during electrolysis?', 'text', 1, 'Electrolysis involves a particular form of energy transfer.', '{"why":"An electric current causes water to decompose into hydrogen and oxygen under suitable conditions.","sol":"Step 1: Identify electrolysis as the process involved.\nStep 2: Recall that electrolysis uses an electric current.\nStep 3: The current drives the breakdown of water.","steps":["Step 1: Identify electrolysis as the process involved.","Step 2: Recall that electrolysis uses an electric current.","Step 3: The current drives the breakdown of water."],"options":[],"conceptId":"chemistry_chemical_reactions_decomposition_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q6","subject":"chemistry","chapter":"chemical_reactions","topic":"Decomposition Reactions"}', 5),
  (3525, 819, 'A single reactant forms three products. Can the reaction be classified as decomposition?', 'text', 1, 'The definition says two or more products.', '{"why":"Decomposition is not limited to forming exactly two products.","sol":"Step 1: Identify the one reactant.\nStep 2: Count the three products.\nStep 3: Compare the pattern with the definition of decomposition.","steps":["Step 1: Identify the one reactant.","Step 2: Count the three products.","Step 3: Compare the pattern with the definition of decomposition."],"options":[],"conceptId":"chemistry_chemical_reactions_decomposition_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q7","subject":"chemistry","chapter":"chemical_reactions","topic":"Decomposition Reactions"}', 6),
  (3526, 819, 'Why is CaCO₃ → CaO + CO₂ a decomposition reaction rather than a combination reaction?', 'text', 1, 'Compare the number of starting substances with the number formed.', '{"why":"Combination has the opposite pattern: multiple reactants forming one product.","sol":"Step 1: There is one reactant, CaCO₃.\nStep 2: There are two products, CaO and CO₂.\nStep 3: One reactant forms multiple products.","steps":["Step 1: There is one reactant, CaCO₃.","Step 2: There are two products, CaO and CO₂.","Step 3: One reactant forms multiple products."],"options":[],"conceptId":"chemistry_chemical_reactions_decomposition_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q8","subject":"chemistry","chapter":"chemical_reactions","topic":"Decomposition Reactions"}', 7),
  (3527, 819, 'What is the role of manganese(IV) oxide in the decomposition of potassium chlorate when it is used?', 'text', 1, 'It changes how quickly the reaction happens.', '{"why":"A catalyst helps the reaction proceed faster; it does not change the balanced atom count of the overall equation.","sol":"Step 1: Identify manganese(IV) oxide as a catalyst.\nStep 2: Recall that a catalyst changes the reaction rate.\nStep 3: It is not counted as a reactant in the overall balanced equation.","steps":["Step 1: Identify manganese(IV) oxide as a catalyst.","Step 2: Recall that a catalyst changes the reaction rate.","Step 3: It is not counted as a reactant in the overall balanced equation."],"options":[],"conceptId":"chemistry_chemical_reactions_decomposition_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q9","subject":"chemistry","chapter":"chemical_reactions","topic":"Decomposition Reactions"}', 8),
  (3528, 820, 'What is a displacement reaction?', 'text', 1, 'Compare the reactivity of the free element with the element in the compound.', '{"why":"The ability to replace the less reactive element is the defining feature of displacement.","sol":"Step 1: Identify the free element and the compound.\nStep 2: Compare the reactivity of the free element with the element in the compound.\nStep 3: Determine whether the free element can replace it.","steps":["Step 1: Identify the free element and the compound.","Step 2: Compare the reactivity of the free element with the element in the compound.","Step 3: Determine whether the free element can replace it."],"options":[],"conceptId":"chemistry_chemical_reactions_displacement_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"Displacement Reactions"}', 0),
  (3529, 820, 'Complete the reaction: Zn + CuSO₄ → ?', 'text', 1, 'Zinc is more reactive than copper.', '{"why":"Zinc is more reactive than copper and displaces it from the compound.","sol":"Step 1: Zinc replaces copper in copper(II) sulphate.\nStep 2: The salt formed is zinc sulphate.\nStep 3: Copper is released as an element.","steps":["Step 1: Zinc replaces copper in copper(II) sulphate.","Step 2: The salt formed is zinc sulphate.","Step 3: Copper is released as an element."],"options":[],"conceptId":"chemistry_chemical_reactions_displacement_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"Displacement Reactions"}', 1),
  (3530, 820, 'Will copper displace zinc from zinc sulphate solution? Explain.', 'text', 1, 'Use the reactivity series.', '{"why":"A metal cannot displace a less reactive metal from its compound if the free metal is less reactive.","sol":"Step 1: Identify copper as the free metal.\nStep 2: Compare copper with zinc in the reactivity series.\nStep 3: Copper is less reactive than zinc, so it cannot replace zinc.","steps":["Step 1: Identify copper as the free metal.","Step 2: Compare copper with zinc in the reactivity series.","Step 3: Copper is less reactive than zinc, so it cannot replace zinc."],"options":[],"conceptId":"chemistry_chemical_reactions_displacement_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"Displacement Reactions"}', 2),
  (3531, 820, 'A learner claims that any metal can displace another metal from its salt solution. What is wrong with this claim?', 'text', 1, 'Consider the reactivity series.', '{"why":"The reactivity series determines whether displacement is possible.","sol":"Step 1: Recall that displacement depends on relative reactivity.\nStep 2: A more reactive metal can replace a less reactive metal.\nStep 3: A less reactive metal cannot replace a more reactive metal.","steps":["Step 1: Recall that displacement depends on relative reactivity.","Step 2: A more reactive metal can replace a less reactive metal.","Step 3: A less reactive metal cannot replace a more reactive metal."],"options":[],"conceptId":"chemistry_chemical_reactions_displacement_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"Displacement Reactions"}', 3),
  (3532, 820, 'Predict what happens when magnesium is placed in copper(II) sulphate solution.', 'text', 1, 'Magnesium is above copper in the reactivity series.', '{"why":"Magnesium can displace copper because it is more reactive.","sol":"Step 1: Magnesium is more reactive than copper.\nStep 2: Magnesium replaces copper in copper(II) sulphate.\nStep 3: The products are magnesium sulphate and copper.","steps":["Step 1: Magnesium is more reactive than copper.","Step 2: Magnesium replaces copper in copper(II) sulphate.","Step 3: The products are magnesium sulphate and copper."],"options":[],"conceptId":"chemistry_chemical_reactions_displacement_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q5","subject":"chemistry","chapter":"chemical_reactions","topic":"Displacement Reactions"}', 4),
  (3533, 820, 'Iron is placed in zinc sulphate solution. Will displacement occur?', 'text', 1, 'Compare iron and zinc.', '{"why":"Iron cannot displace the more reactive zinc from zinc sulphate.","sol":"Step 1: Iron is the free metal.\nStep 2: Zinc is above iron in the reactivity series.\nStep 3: Iron is less reactive than zinc and cannot replace it.","steps":["Step 1: Iron is the free metal.","Step 2: Zinc is above iron in the reactivity series.","Step 3: Iron is less reactive than zinc and cannot replace it."],"options":[],"conceptId":"chemistry_chemical_reactions_displacement_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q6","subject":"chemistry","chapter":"chemical_reactions","topic":"Displacement Reactions"}', 5),
  (3534, 820, 'In Zn + CuSO₄ → ZnSO₄ + Cu, which substance is displaced?', 'text', 1, 'Identify the element that was originally part of the compound but becomes free.', '{"why":"Copper is the less reactive element replaced by zinc.","sol":"Step 1: Copper begins in copper(II) sulphate.\nStep 2: Zinc replaces copper in the compound.\nStep 3: Copper is released as a free element.","steps":["Step 1: Copper begins in copper(II) sulphate.","Step 2: Zinc replaces copper in the compound.","Step 3: Copper is released as a free element."],"options":[],"conceptId":"chemistry_chemical_reactions_displacement_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q7","subject":"chemistry","chapter":"chemical_reactions","topic":"Displacement Reactions"}', 6),
  (3535, 820, 'Why can magnesium displace zinc from zinc sulphate, but zinc cannot displace magnesium from magnesium sulphate?', 'text', 1, 'Compare the positions of magnesium and zinc in the reactivity series.', '{"why":"Displacement depends on which element is higher in the reactivity series.","sol":"Step 1: Magnesium is more reactive than zinc.\nStep 2: Magnesium can replace zinc from its compound.\nStep 3: Zinc is less reactive than magnesium and cannot replace it.","steps":["Step 1: Magnesium is more reactive than zinc.","Step 2: Magnesium can replace zinc from its compound.","Step 3: Zinc is less reactive than magnesium and cannot replace it."],"options":[],"conceptId":"chemistry_chemical_reactions_displacement_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q8","subject":"chemistry","chapter":"chemical_reactions","topic":"Displacement Reactions"}', 7),
  (3536, 820, 'A blue copper(II) sulphate solution is placed in contact with iron. The solution becomes pale green and a reddish-brown solid forms. Explain these observations.', 'text', 1, 'Identify the new salt and the metal deposited.', '{"why":"The observations are consistent with Fe + CuSO₄ → FeSO₄ + Cu.","sol":"Step 1: Iron is more reactive than copper.\nStep 2: Iron displaces copper, forming iron(II) sulphate.\nStep 3: The iron(II) sulphate solution is pale green, while the deposited copper is reddish-brown.","steps":["Step 1: Iron is more reactive than copper.","Step 2: Iron displaces copper, forming iron(II) sulphate.","Step 3: The iron(II) sulphate solution is pale green, while the deposited copper is reddish-brown."],"options":[],"conceptId":"chemistry_chemical_reactions_displacement_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q9","subject":"chemistry","chapter":"chemical_reactions","topic":"Displacement Reactions"}', 8),
  (3537, 821, 'What is neutralisation?', 'text', 1, 'Recall the usual products of an acid reacting with a base.', '{"why":"Salt and water are the usual products of the neutralisation reactions studied at this level.","sol":"Step 1: Identify the acid and the base.\nStep 2: Determine the products of their reaction.\nStep 3: Check whether salt and water are formed.","steps":["Step 1: Identify the acid and the base.","Step 2: Determine the products of their reaction.","Step 3: Check whether salt and water are formed."],"options":[],"conceptId":"chemistry_chemical_reactions_neutralisation_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"Neutralisation Reactions"}', 0),
  (3538, 821, 'Complete and balance: HCl + NaOH → ?', 'text', 1, 'Hydrochloric acid forms chloride salts.', '{"why":"Sodium chloride and water are formed, and all atoms are balanced.","sol":"Step 1: Combine sodium with chloride to form sodium chloride, NaCl.\nStep 2: The acid''s hydrogen and the hydroxide''s OH group form water.\nStep 3: Write HCl + NaOH → NaCl + H₂O and count the atoms.","steps":["Step 1: Combine sodium with chloride to form sodium chloride, NaCl.","Step 2: The acid''s hydrogen and the hydroxide''s OH group form water.","Step 3: Write HCl + NaOH → NaCl + H₂O and count the atoms."],"options":[],"conceptId":"chemistry_chemical_reactions_neutralisation_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"Neutralisation Reactions"}', 1),
  (3539, 821, 'Balance: H₂SO₄ + KOH → K₂SO₄ + H₂O.', 'text', 1, 'Balance potassium first.', '{"why":"Both sides contain K = 2, H = 4, S = 1 and O = 6.","sol":"Step 1: K₂SO₄ contains two potassium atoms, so place 2 before KOH.\nStep 2: There are now four hydrogen atoms on the left.\nStep 3: Place 2 before H₂O and check oxygen.","steps":["Step 1: K₂SO₄ contains two potassium atoms, so place 2 before KOH.","Step 2: There are now four hydrogen atoms on the left.","Step 3: Place 2 before H₂O and check oxygen."],"options":[],"conceptId":"chemistry_chemical_reactions_neutralisation_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"Neutralisation Reactions"}', 2),
  (3540, 821, 'A learner says neutralisation always produces only water. What is missing from the answer?', 'text', 1, 'Recall the other main product.', '{"why":"Water is not the only product; the other main product is a salt.","sol":"Step 1: Recall the word equation for neutralisation.\nStep 2: Identify both products formed when an acid reacts with a suitable base.\nStep 3: Include the salt as well as water.","steps":["Step 1: Recall the word equation for neutralisation.","Step 2: Identify both products formed when an acid reacts with a suitable base.","Step 3: Include the salt as well as water."],"options":[],"conceptId":"chemistry_chemical_reactions_neutralisation_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"Neutralisation Reactions"}', 3),
  (3541, 821, 'Which salt forms when hydrochloric acid reacts with sodium hydroxide?', 'text', 1, 'Hydrochloric acid forms chloride salts.', '{"why":"The sodium ion and chloride ion form sodium chloride.","sol":"Step 1: Identify the metal ion from sodium hydroxide: sodium.\nStep 2: Identify the anion from hydrochloric acid: chloride.\nStep 3: Combine them to form sodium chloride.","steps":["Step 1: Identify the metal ion from sodium hydroxide: sodium.","Step 2: Identify the anion from hydrochloric acid: chloride.","Step 3: Combine them to form sodium chloride."],"options":[],"conceptId":"chemistry_chemical_reactions_neutralisation_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q5","subject":"chemistry","chapter":"chemical_reactions","topic":"Neutralisation Reactions"}', 4),
  (3542, 821, 'Complete and balance: 2HCl + MgO → ?', 'text', 1, 'A basic metal oxide reacts with an acid to form a salt and water.', '{"why":"The products are magnesium chloride and water, and the equation is balanced.","sol":"Step 1: The salt contains magnesium and chloride, so it is MgCl₂.\nStep 2: The oxygen in MgO and hydrogen from HCl form H₂O.\nStep 3: Check that the two chlorine atoms, two hydrogen atoms and one oxygen atom are balanced.","steps":["Step 1: The salt contains magnesium and chloride, so it is MgCl₂.","Step 2: The oxygen in MgO and hydrogen from HCl form H₂O.","Step 3: Check that the two chlorine atoms, two hydrogen atoms and one oxygen atom are balanced."],"options":[],"conceptId":"chemistry_chemical_reactions_neutralisation_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q6","subject":"chemistry","chapter":"chemical_reactions","topic":"Neutralisation Reactions"}', 5),
  (3543, 821, 'What happens when hydrogen ions react with hydroxide ions during neutralisation?', 'text', 1, 'Recall the net ionic equation.', '{"why":"The hydrogen and hydroxide ions combine to form water.","sol":"Step 1: Hydrogen ions are represented by H⁺.\nStep 2: Hydroxide ions are represented by OH⁻.\nStep 3: They combine to form water.","steps":["Step 1: Hydrogen ions are represented by H⁺.","Step 2: Hydroxide ions are represented by OH⁻.","Step 3: They combine to form water."],"options":[],"conceptId":"chemistry_chemical_reactions_neutralisation_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q7","subject":"chemistry","chapter":"chemical_reactions","topic":"Neutralisation Reactions"}', 6),
  (3544, 821, 'Which type of salt is formed when nitric acid reacts with potassium hydroxide?', 'text', 1, 'Nitric acid forms nitrate salts.', '{"why":"Nitric acid forms nitrate salts, and potassium supplies the potassium ion.","sol":"Step 1: Identify the metal ion: potassium.\nStep 2: Identify the salt-forming ion from nitric acid: nitrate.\nStep 3: Combine them to name the salt.","steps":["Step 1: Identify the metal ion: potassium.","Step 2: Identify the salt-forming ion from nitric acid: nitrate.","Step 3: Combine them to name the salt."],"options":[],"conceptId":"chemistry_chemical_reactions_neutralisation_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q8","subject":"chemistry","chapter":"chemical_reactions","topic":"Neutralisation Reactions"}', 7),
  (3545, 821, 'A student mixes an acid and an alkali in unequal quantities and assumes the final pH must be exactly 7. Why is this not always correct?', 'text', 1, 'Consider whether either substance remains in excess.', '{"why":"Neutralisation does not guarantee pH 7 in every mixture.","sol":"Step 1: Neutralisation occurs as hydrogen ions react with hydroxide ions.\nStep 2: If the quantities are unequal, one may remain in excess.\nStep 3: The excess acid or alkali can affect the final pH.","steps":["Step 1: Neutralisation occurs as hydrogen ions react with hydroxide ions.","Step 2: If the quantities are unequal, one may remain in excess.","Step 3: The excess acid or alkali can affect the final pH."],"options":[],"conceptId":"chemistry_chemical_reactions_neutralisation_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q9","subject":"chemistry","chapter":"chemical_reactions","topic":"Neutralisation Reactions"}', 8),
  (3546, 822, 'What is combustion?', 'text', 1, 'Think about reaction with oxygen and the transfer of energy.', '{"why":"Combustion is an energy-releasing chemical reaction, commonly involving oxygen.","sol":"Step 1: Identify a substance reacting with an oxidising agent, commonly oxygen.\nStep 2: Consider the energy change during the reaction.\nStep 3: State what happens to energy and, where applicable, light.","steps":["Step 1: Identify a substance reacting with an oxidising agent, commonly oxygen.","Step 2: Consider the energy change during the reaction.","Step 3: State what happens to energy and, where applicable, light."],"options":[],"conceptId":"chemistry_chemical_reactions_combustion_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"Combustion Reactions"}', 0),
  (3547, 822, 'Balance the complete combustion equation for methane: CH₄ + O₂ → CO₂ + H₂O.', 'text', 1, 'Balance carbon, then hydrogen, then oxygen.', '{"why":"Each side contains one carbon, four hydrogen and four oxygen atoms.","sol":"Step 1: Carbon is already balanced.\nStep 2: Place 2 before H₂O to balance four hydrogen atoms.\nStep 3: There are four oxygen atoms in the products, so place 2 before O₂.","steps":["Step 1: Carbon is already balanced.","Step 2: Place 2 before H₂O to balance four hydrogen atoms.","Step 3: There are four oxygen atoms in the products, so place 2 before O₂."],"options":[],"conceptId":"chemistry_chemical_reactions_combustion_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"Combustion Reactions"}', 1),
  (3548, 822, 'What are the products of complete combustion of a hydrocarbon in sufficient oxygen?', 'text', 1, 'A hydrocarbon contains carbon and hydrogen.', '{"why":"With sufficient oxygen, the carbon and hydrogen in a hydrocarbon form carbon dioxide and water.","sol":"Step 1: Carbon is converted to carbon dioxide during complete combustion.\nStep 2: Hydrogen is converted to water.\nStep 3: State both products.","steps":["Step 1: Carbon is converted to carbon dioxide during complete combustion.","Step 2: Hydrogen is converted to water.","Step 3: State both products."],"options":[],"conceptId":"chemistry_chemical_reactions_combustion_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"Combustion Reactions"}', 2),
  (3549, 822, 'Why can incomplete combustion be dangerous even when a flame is visible?', 'text', 1, 'Consider a possible product formed when oxygen is insufficient.', '{"why":"A visible flame does not guarantee complete combustion or safe conditions.","sol":"Step 1: Insufficient oxygen may cause incomplete combustion.\nStep 2: Incomplete combustion can produce carbon monoxide.\nStep 3: Carbon monoxide interferes with oxygen transport in the blood.","steps":["Step 1: Insufficient oxygen may cause incomplete combustion.","Step 2: Incomplete combustion can produce carbon monoxide.","Step 3: Carbon monoxide interferes with oxygen transport in the blood."],"options":[],"conceptId":"chemistry_chemical_reactions_combustion_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"Combustion Reactions"}', 3),
  (3550, 822, 'Balance the complete combustion of ethane: C₂H₆ + O₂ → CO₂ + H₂O.', 'text', 1, 'Balance carbon and hydrogen before oxygen.', '{"why":"Both sides contain C = 4, H = 12 and O = 14.","sol":"Step 1: Use 2C₂H₆ to give 4 carbon atoms and 12 hydrogen atoms.\nStep 2: Place 4 before CO₂ and 6 before H₂O.\nStep 3: The products contain 8 + 6 = 14 oxygen atoms, so place 7 before O₂.","steps":["Step 1: Use 2C₂H₆ to give 4 carbon atoms and 12 hydrogen atoms.","Step 2: Place 4 before CO₂ and 6 before H₂O.","Step 3: The products contain 8 + 6 = 14 oxygen atoms, so place 7 before O₂."],"options":[],"conceptId":"chemistry_chemical_reactions_combustion_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q5","subject":"chemistry","chapter":"chemical_reactions","topic":"Combustion Reactions"}', 4),
  (3551, 822, 'A student says incomplete combustion always produces only carbon monoxide. Why is this incorrect?', 'text', 1, 'Consider another possible carbon-containing product.', '{"why":"The products depend on the fuel and combustion conditions.","sol":"Step 1: Incomplete combustion occurs when oxygen is insufficient.\nStep 2: Carbon monoxide may form.\nStep 3: Solid carbon (soot) may also form, depending on the conditions.","steps":["Step 1: Incomplete combustion occurs when oxygen is insufficient.","Step 2: Carbon monoxide may form.","Step 3: Solid carbon (soot) may also form, depending on the conditions."],"options":[],"conceptId":"chemistry_chemical_reactions_combustion_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q6","subject":"chemistry","chapter":"chemical_reactions","topic":"Combustion Reactions"}', 5),
  (3552, 822, 'Balance: C₃H₈ + O₂ → CO₂ + H₂O.', 'text', 1, 'Three carbon atoms require three carbon dioxide molecules.', '{"why":"Both sides contain three carbon, eight hydrogen and ten oxygen atoms.","sol":"Step 1: Place 3 before CO₂ to balance carbon.\nStep 2: Place 4 before H₂O to balance eight hydrogen atoms.\nStep 3: Count ten oxygen atoms in the products and place 5 before O₂.","steps":["Step 1: Place 3 before CO₂ to balance carbon.","Step 2: Place 4 before H₂O to balance eight hydrogen atoms.","Step 3: Count ten oxygen atoms in the products and place 5 before O₂."],"options":[],"conceptId":"chemistry_chemical_reactions_combustion_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q7","subject":"chemistry","chapter":"chemical_reactions","topic":"Combustion Reactions"}', 6),
  (3553, 822, 'Why is oxygen required for ordinary combustion?', 'text', 1, 'Think of oxygen as a reactant, not merely something that makes a flame visible.', '{"why":"Combustion is a chemical reaction, not simply the presence of a flame.","sol":"Step 1: Ordinary combustion involves a fuel reacting with oxygen.\nStep 2: Oxygen participates in the chemical reaction.\nStep 3: The reaction releases energy as heat and often light.","steps":["Step 1: Ordinary combustion involves a fuel reacting with oxygen.","Step 2: Oxygen participates in the chemical reaction.","Step 3: The reaction releases energy as heat and often light."],"options":[],"conceptId":"chemistry_chemical_reactions_combustion_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q8","subject":"chemistry","chapter":"chemical_reactions","topic":"Combustion Reactions"}', 7),
  (3554, 822, 'A hydrocarbon burns in sufficient oxygen and forms carbon dioxide and water. Is this complete or incomplete combustion? Explain.', 'text', 1, 'Check the oxygen supply and the carbon-containing product.', '{"why":"These are the characteristic products of complete combustion of a hydrocarbon under sufficient oxygen.","sol":"Step 1: The fuel is a hydrocarbon containing carbon and hydrogen.\nStep 2: The oxygen supply is sufficient.\nStep 3: Carbon dioxide and water are the stated products.","steps":["Step 1: The fuel is a hydrocarbon containing carbon and hydrogen.","Step 2: The oxygen supply is sufficient.","Step 3: Carbon dioxide and water are the stated products."],"options":[],"conceptId":"chemistry_chemical_reactions_combustion_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q9","subject":"chemistry","chapter":"chemical_reactions","topic":"Combustion Reactions"}', 8),
  (3555, 823, 'What is a precipitation reaction?', 'text', 1, 'Focus on the formation of an insoluble solid.', '{"why":"The defining feature is the formation of an insoluble solid from solution.","sol":"Step 1: Begin with suitable aqueous solutions.\nStep 2: Identify the products formed when the ions interact.\nStep 3: Check whether an insoluble solid forms.","steps":["Step 1: Begin with suitable aqueous solutions.","Step 2: Identify the products formed when the ions interact.","Step 3: Check whether an insoluble solid forms."],"options":[],"conceptId":"chemistry_chemical_reactions_precipitation_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"Precipitation Reactions"}', 0),
  (3556, 823, 'What precipitate forms when silver nitrate solution reacts with sodium chloride solution?', 'text', 1, 'Silver ions combine with chloride ions.', '{"why":"Ag⁺ and Cl⁻ ions form solid silver chloride.","sol":"Step 1: Identify Ag⁺ from silver nitrate.\nStep 2: Identify Cl⁻ from sodium chloride.\nStep 3: Combine them to form AgCl, which is insoluble in water under these conditions.","steps":["Step 1: Identify Ag⁺ from silver nitrate.","Step 2: Identify Cl⁻ from sodium chloride.","Step 3: Combine them to form AgCl, which is insoluble in water under these conditions."],"options":[],"conceptId":"chemistry_chemical_reactions_precipitation_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"Precipitation Reactions"}', 1),
  (3557, 823, 'Complete and balance: BaCl₂(aq) + Na₂SO₄(aq) → ?', 'text', 1, 'Barium ions combine with sulphate ions.', '{"why":"Barium sulphate is insoluble and forms a precipitate; the equation is balanced.","sol":"Step 1: Form BaSO₄ from Ba²⁺ and SO₄²⁻.\nStep 2: The remaining ions form sodium chloride.\nStep 3: Place 2 before NaCl to balance sodium and chlorine.","steps":["Step 1: Form BaSO₄ from Ba²⁺ and SO₄²⁻.","Step 2: The remaining ions form sodium chloride.","Step 3: Place 2 before NaCl to balance sodium and chlorine."],"options":[],"conceptId":"chemistry_chemical_reactions_precipitation_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"Precipitation Reactions"}', 2),
  (3558, 823, 'A learner says every reaction between two aqueous solutions produces a precipitate. Is this correct?', 'text', 1, 'Consider whether all possible products are insoluble.', '{"why":"Some reactions between aqueous solutions produce only dissolved products.","sol":"Step 1: Mixing solutions brings dissolved ions together.\nStep 2: Some combinations form soluble products that remain dissolved.\nStep 3: A precipitation reaction requires an insoluble solid to form.","steps":["Step 1: Mixing solutions brings dissolved ions together.","Step 2: Some combinations form soluble products that remain dissolved.","Step 3: A precipitation reaction requires an insoluble solid to form."],"options":[],"conceptId":"chemistry_chemical_reactions_precipitation_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"Precipitation Reactions"}', 3),
  (3559, 823, 'In AgNO₃(aq) + NaCl(aq) → AgCl(s) + NaNO₃(aq), identify the precipitate.', 'text', 1, 'Look for the product labelled (s).', '{"why":"Silver chloride is the insoluble solid formed in the reaction.","sol":"Step 1: Read the products on the right-hand side.\nStep 2: Identify the product labelled (s).\nStep 3: Recognise that (s) indicates a solid.","steps":["Step 1: Read the products on the right-hand side.","Step 2: Identify the product labelled (s).","Step 3: Recognise that (s) indicates a solid."],"options":[],"conceptId":"chemistry_chemical_reactions_precipitation_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q5","subject":"chemistry","chapter":"chemical_reactions","topic":"Precipitation Reactions"}', 4),
  (3560, 823, 'Why is the equation Pb(NO₃)₂ + KI → PbI₂ + KNO₃ not balanced as written?', 'text', 1, 'Count the iodide ions and potassium atoms.', '{"why":"The coefficients balance lead, nitrate groups, potassium and iodine.","sol":"Step 1: PbI₂ contains two iodine atoms.\nStep 2: One KI supplies only one iodine atom, so place 2 before KI.\nStep 3: This gives two potassium atoms, so place 2 before KNO₃.","steps":["Step 1: PbI₂ contains two iodine atoms.","Step 2: One KI supplies only one iodine atom, so place 2 before KI.","Step 3: This gives two potassium atoms, so place 2 before KNO₃."],"options":[],"conceptId":"chemistry_chemical_reactions_precipitation_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q6","subject":"chemistry","chapter":"chemical_reactions","topic":"Precipitation Reactions"}', 5),
  (3561, 823, 'What does the state symbol (aq) mean in a precipitation equation?', 'text', 1, 'It describes a substance dissolved in water.', '{"why":"(aq) identifies an aqueous solution, while (s) identifies a solid.","sol":"Step 1: Recognise that the substance is in solution.\nStep 2: Identify the solvent as water.\nStep 3: Distinguish this from (s), which indicates a solid.","steps":["Step 1: Recognise that the substance is in solution.","Step 2: Identify the solvent as water.","Step 3: Distinguish this from (s), which indicates a solid."],"options":[],"conceptId":"chemistry_chemical_reactions_precipitation_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q7","subject":"chemistry","chapter":"chemical_reactions","topic":"Precipitation Reactions"}', 6),
  (3562, 823, 'Write the net ionic equation for forming silver chloride from silver ions and chloride ions.', 'text', 1, 'Leave out ions that do not take part in forming the solid.', '{"why":"The net ionic equation includes only the ions that form the precipitate.","sol":"Step 1: Identify the reacting ions: Ag⁺ and Cl⁻.\nStep 2: Combine one silver ion with one chloride ion.\nStep 3: Show the insoluble product as a solid.","steps":["Step 1: Identify the reacting ions: Ag⁺ and Cl⁻.","Step 2: Combine one silver ion with one chloride ion.","Step 3: Show the insoluble product as a solid."],"options":[],"conceptId":"chemistry_chemical_reactions_precipitation_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q8","subject":"chemistry","chapter":"chemical_reactions","topic":"Precipitation Reactions"}', 7),
  (3563, 823, 'When lead(II) nitrate solution reacts with potassium iodide solution, why is a yellow solid formed?', 'text', 1, 'Identify the insoluble product and its colour.', '{"why":"The insoluble product separates from the solution as a solid.","sol":"Step 1: Lead(II) ions react with iodide ions.\nStep 2: They form lead(II) iodide, PbI₂.\nStep 3: Lead(II) iodide is poorly soluble in water and appears as a yellow solid.","steps":["Step 1: Lead(II) ions react with iodide ions.","Step 2: They form lead(II) iodide, PbI₂.","Step 3: Lead(II) iodide is poorly soluble in water and appears as a yellow solid."],"options":[],"conceptId":"chemistry_chemical_reactions_precipitation_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q9","subject":"chemistry","chapter":"chemical_reactions","topic":"Precipitation Reactions"}', 8),
  (3564, 824, 'Define an acid in terms of the ions it produces in water.', 'text', 1, 'Identify the characteristic positive ion associated with acids.', '{"why":"Hydrogen ions are responsible for the characteristic acidic properties of aqueous solutions.","sol":"Step 1: Recall the school-level definition of an acid.\nStep 2: State the ion produced in aqueous solution.","steps":["Step 1: Recall the school-level definition of an acid.","Step 2: State the ion produced in aqueous solution."],"options":[],"conceptId":"chemistry_acids_bases_salts_properties_of_acids","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Properties of Acids"}', 0),
  (3565, 824, 'A solution turns blue litmus paper red. Explain what this observation indicates.', 'text', 1, 'Recall the characteristic colour change caused by acids.', '{"why":"Acids turn blue litmus paper red. The test indicates acidity but does not, by itself, identify the particular acid.","sol":"Step 1: Identify the original colour of the litmus paper.\nStep 2: Recall the effect of an acid on blue litmus.\nStep 3: Use the observed colour change to classify the solution.","steps":["Step 1: Identify the original colour of the litmus paper.","Step 2: Recall the effect of an acid on blue litmus.","Step 3: Use the observed colour change to classify the solution."],"options":[],"conceptId":"chemistry_acids_bases_salts_properties_of_acids","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Properties of Acids"}', 1),
  (3566, 824, 'A solution has a pH of 4. Classify the solution and justify your answer.', 'text', 1, 'Compare the pH value with 7.', '{"why":"The pH scale distinguishes acidic, neutral and alkaline aqueous solutions.","sol":"Step 1: Recall that a pH below 7 is acidic under the usual school-level classification.\nStep 2: Compare 4 with 7.\nStep 3: State the classification.","steps":["Step 1: Recall that a pH below 7 is acidic under the usual school-level classification.","Step 2: Compare 4 with 7.","Step 3: State the classification."],"options":[],"conceptId":"chemistry_acids_bases_salts_properties_of_acids","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Properties of Acids"}', 2),
  (3567, 824, 'Explain why aqueous hydrochloric acid conducts electricity.', 'text', 1, 'Think about the charged particles present in the solution.', '{"why":"Electrical conduction in the solution depends on the movement of charged particles, not simply on the presence of water.","sol":"Step 1: Identify the ions formed when hydrogen chloride dissolves in water.\nStep 2: Recognise that the ions are mobile in solution.\nStep 3: Explain how moving charged particles carry current.","steps":["Step 1: Identify the ions formed when hydrogen chloride dissolves in water.","Step 2: Recognise that the ions are mobile in solution.","Step 3: Explain how moving charged particles carry current."],"options":[],"conceptId":"chemistry_acids_bases_salts_properties_of_acids","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Properties of Acids"}', 3),
  (3568, 824, 'Give two characteristic properties of an aqueous acid and explain each briefly.', 'text', 1, 'Choose from indicator behaviour, pH and electrical conductivity.', '{"why":"These properties help identify acidic solutions without tasting or directly handling them.","sol":"Step 1: State one characteristic property.\nStep 2: Explain the observation associated with it.\nStep 3: State a second property and explain it.","steps":["Step 1: State one characteristic property.","Step 2: Explain the observation associated with it.","Step 3: State a second property and explain it."],"options":[],"conceptId":"chemistry_acids_bases_salts_properties_of_acids","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q5","subject":"chemistry","chapter":"acids_bases_salts","topic":"Properties of Acids"}', 4),
  (3569, 825, 'State the general word equation for the reaction between a sufficiently reactive metal and a suitable dilute acid.', 'text', 1, 'Name the two products.', '{"why":"Reactive metals can displace hydrogen from suitable dilute acids, forming a salt and hydrogen gas.","sol":"Step 1: Identify the reactants: a reactive metal and a suitable dilute acid.\nStep 2: Recall the salt formed from the metal and acid.\nStep 3: Name the gas produced.","steps":["Step 1: Identify the reactants: a reactive metal and a suitable dilute acid.","Step 2: Recall the salt formed from the metal and acid.","Step 3: Name the gas produced."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_metals","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Metals"}', 0),
  (3570, 825, 'Write and balance the equation for magnesium reacting with dilute hydrochloric acid.', 'text', 1, 'The products are magnesium chloride and hydrogen gas.', '{"why":"There is one magnesium atom, two chlorine atoms and two hydrogen atoms on each side of the balanced equation.","sol":"Step 1: Write the unbalanced equation: Mg + HCl → MgCl2 + H2.\nStep 2: Balance chlorine by placing 2 before HCl.\nStep 3: Check that magnesium, hydrogen and chlorine atoms balance.","steps":["Step 1: Write the unbalanced equation: Mg + HCl → MgCl2 + H2.","Step 2: Balance chlorine by placing 2 before HCl.","Step 3: Check that magnesium, hydrogen and chlorine atoms balance."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_metals","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Metals"}', 1),
  (3571, 825, 'Write the balanced equation for zinc reacting with dilute sulfuric acid.', 'text', 1, 'The salt is zinc sulfate.', '{"why":"One zinc atom, one sulfate group and two hydrogen atoms are present on each side.","sol":"Step 1: Write the reactants: Zn and H2SO4.\nStep 2: Predict zinc sulfate and hydrogen as the products.\nStep 3: Check the atom counts on both sides.","steps":["Step 1: Write the reactants: Zn and H2SO4.","Step 2: Predict zinc sulfate and hydrogen as the products.","Step 3: Check the atom counts on both sides."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_metals","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Metals"}', 2),
  (3572, 825, 'A gas produced when magnesium reacts with dilute hydrochloric acid burns with a squeaky pop. Identify the gas and state the test observation.', 'text', 1, 'Recall the characteristic test for hydrogen.', '{"why":"The squeaky-pop test is the characteristic test for hydrogen gas.","sol":"Step 1: Recall the products of a reactive metal and dilute acid.\nStep 2: Identify the gas that gives the squeaky-pop test.\nStep 3: State the gas and observation.","steps":["Step 1: Recall the products of a reactive metal and dilute acid.","Step 2: Identify the gas that gives the squeaky-pop test.","Step 3: State the gas and observation."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_metals","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Metals"}', 3),
  (3573, 825, 'Explain why copper normally does not produce hydrogen when placed in dilute hydrochloric acid.', 'text', 1, 'Use the reactivity series.', '{"why":"The usual metal-acid reaction requires a metal that is sufficiently reactive to displace hydrogen from the acid.","sol":"Step 1: Recall that a metal must be sufficiently reactive to displace hydrogen from the dilute acid.\nStep 2: Locate copper relative to hydrogen in the reactivity series.\nStep 3: Connect its position to the expected observation.","steps":["Step 1: Recall that a metal must be sufficiently reactive to displace hydrogen from the dilute acid.","Step 2: Locate copper relative to hydrogen in the reactivity series.","Step 3: Connect its position to the expected observation."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_metals","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q5","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Metals"}', 4),
  (3574, 826, 'State the three products formed when an acid reacts with a metal carbonate.', 'text', 1, 'One product is a salt, and the other two are water and a gas.', '{"why":"Carbonates react with acids to release carbon dioxide while forming water and a salt.","sol":"Step 1: Recall the general reaction pattern for acids and carbonates.\nStep 2: Name the salt.\nStep 3: Name the liquid product and the gaseous product.","steps":["Step 1: Recall the general reaction pattern for acids and carbonates.","Step 2: Name the salt.","Step 3: Name the liquid product and the gaseous product."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_carbonates","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Carbonates"}', 0),
  (3575, 826, 'Write and balance the equation for calcium carbonate reacting with hydrochloric acid.', 'text', 1, 'The salt formed is calcium chloride.', '{"why":"The equation is balanced because calcium, carbon, oxygen, hydrogen and chlorine atoms are equal on both sides.","sol":"Step 1: Write the products: calcium chloride, water and carbon dioxide.\nStep 2: Write the unbalanced equation.\nStep 3: Place 2 before HCl and check all atoms.","steps":["Step 1: Write the products: calcium chloride, water and carbon dioxide.","Step 2: Write the unbalanced equation.","Step 3: Place 2 before HCl and check all atoms."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_carbonates","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Carbonates"}', 1),
  (3576, 826, 'Write the balanced equation for sodium carbonate reacting with nitric acid.', 'text', 1, 'The salt formed is sodium nitrate.', '{"why":"The balanced equation conserves the numbers of sodium, nitrogen, hydrogen, carbon and oxygen atoms.","sol":"Step 1: Write sodium nitrate, water and carbon dioxide as the products.\nStep 2: Balance sodium by placing 2 before NaNO3.\nStep 3: Balance nitric acid by placing 2 before HNO3.\nStep 4: Check all atoms.","steps":["Step 1: Write sodium nitrate, water and carbon dioxide as the products.","Step 2: Balance sodium by placing 2 before NaNO3.","Step 3: Balance nitric acid by placing 2 before HNO3.","Step 4: Check all atoms."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_carbonates","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Carbonates"}', 2),
  (3577, 826, 'Carbon dioxide is passed through clear limewater. State the observation and explain why it occurs.', 'text', 1, 'Think about the insoluble substance formed in limewater.', '{"why":"The suspended calcium carbonate makes the limewater appear cloudy or milky.","sol":"Step 1: Recall the test for carbon dioxide.\nStep 2: Identify the product formed when carbon dioxide reacts with limewater.\nStep 3: Relate the product to the observed colour or appearance.","steps":["Step 1: Recall the test for carbon dioxide.","Step 2: Identify the product formed when carbon dioxide reacts with limewater.","Step 3: Relate the product to the observed colour or appearance."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_carbonates","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Carbonates"}', 3),
  (3578, 826, 'A carbonate reacts with an acid and produces bubbles. Explain why the bubbles alone are insufficient to identify the gas.', 'text', 1, 'Separate evidence of gas production from evidence of gas identity.', '{"why":"A gas should be identified using a characteristic test rather than appearance alone.","sol":"Step 1: State what bubbles demonstrate.\nStep 2: Explain why bubbles do not specify the identity of a gas.\nStep 3: Name the appropriate test for the gas expected from an acid-carbonate reaction.","steps":["Step 1: State what bubbles demonstrate.","Step 2: Explain why bubbles do not specify the identity of a gas.","Step 3: Name the appropriate test for the gas expected from an acid-carbonate reaction."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_carbonates","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q5","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Carbonates"}', 4),
  (3579, 827, 'State the products formed when an acid reacts with a hydrogen carbonate.', 'text', 1, 'There are three products.', '{"why":"Acids react with hydrogen carbonates to release carbon dioxide and form water and a salt.","sol":"Step 1: Recall the general reaction pattern.\nStep 2: Name the salt.\nStep 3: Name the two other products.","steps":["Step 1: Recall the general reaction pattern.","Step 2: Name the salt.","Step 3: Name the two other products."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_hydrogen_carbonates","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Hydrogen Carbonates"}', 0),
  (3580, 827, 'Write the balanced equation for sodium hydrogen carbonate reacting with hydrochloric acid.', 'text', 1, 'The salt formed is sodium chloride.', '{"why":"The equation is balanced with a coefficient of 1 for each substance.","sol":"Step 1: Write the products: sodium chloride, water and carbon dioxide.\nStep 2: Write the reactants: NaHCO3 and HCl.\nStep 3: Check each element on both sides.","steps":["Step 1: Write the products: sodium chloride, water and carbon dioxide.","Step 2: Write the reactants: NaHCO3 and HCl.","Step 3: Check each element on both sides."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_hydrogen_carbonates","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Hydrogen Carbonates"}', 1),
  (3581, 827, 'Write the balanced equation for potassium hydrogen carbonate reacting with nitric acid.', 'text', 1, 'The salt formed is potassium nitrate.', '{"why":"Each element has the same total number of atoms on both sides.","sol":"Step 1: Identify potassium nitrate as the salt.\nStep 2: Add water and carbon dioxide as the other products.\nStep 3: Check potassium, hydrogen, carbon, oxygen and nitrogen atoms.","steps":["Step 1: Identify potassium nitrate as the salt.","Step 2: Add water and carbon dioxide as the other products.","Step 3: Check potassium, hydrogen, carbon, oxygen and nitrogen atoms."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_hydrogen_carbonates","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Hydrogen Carbonates"}', 2),
  (3582, 827, 'A student says that sodium hydrogen carbonate reacting with hydrochloric acid produces only sodium chloride and carbon dioxide. Correct the statement.', 'text', 1, 'Check whether the full product pattern includes water.', '{"why":"Water is a product alongside the salt and carbon dioxide.","sol":"Step 1: Recall all the products of an acid-hydrogen carbonate reaction.\nStep 2: Compare the full product list with the student''s list.\nStep 3: State the missing product.","steps":["Step 1: Recall all the products of an acid-hydrogen carbonate reaction.","Step 2: Compare the full product list with the student''s list.","Step 3: State the missing product."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_hydrogen_carbonates","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Hydrogen Carbonates"}', 3),
  (3583, 827, 'Explain how you would test the gas released when potassium hydrogen carbonate reacts with an acid.', 'text', 1, 'Use the standard test for carbon dioxide.', '{"why":"Carbon dioxide reacts with limewater to form insoluble calcium carbonate.","sol":"Step 1: Identify the gas expected from the reaction.\nStep 2: Pass the gas through clear limewater.\nStep 3: State the expected observation.","steps":["Step 1: Identify the gas expected from the reaction.","Step 2: Pass the gas through clear limewater.","Step 3: State the expected observation."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_hydrogen_carbonates","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q5","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Hydrogen Carbonates"}', 4),
  (3584, 828, 'State the general word equation for the reaction between a basic metal oxide and an acid.', 'text', 1, 'This reaction has two main products.', '{"why":"A basic metal oxide neutralises an acid to form a salt and water.","sol":"Step 1: Identify the two reactants.\nStep 2: Recall the salt formed from the metal oxide and acid.\nStep 3: Name the second product.","steps":["Step 1: Identify the two reactants.","Step 2: Recall the salt formed from the metal oxide and acid.","Step 3: Name the second product."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_metal_oxides","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Metal Oxides"}', 0),
  (3585, 828, 'Write the balanced equation for copper(II) oxide reacting with sulfuric acid.', 'text', 1, 'The salt is copper(II) sulfate.', '{"why":"Copper, sulfur, hydrogen and oxygen atoms balance without changing any coefficients.","sol":"Step 1: Write copper(II) sulfate as the salt.\nStep 2: Add water as the second product.\nStep 3: Check the number of atoms on both sides.","steps":["Step 1: Write copper(II) sulfate as the salt.","Step 2: Add water as the second product.","Step 3: Check the number of atoms on both sides."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_metal_oxides","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Metal Oxides"}', 1),
  (3586, 828, 'Write and balance the equation for magnesium oxide reacting with hydrochloric acid.', 'text', 1, 'The salt is magnesium chloride, which contains two chlorine atoms.', '{"why":"The coefficient 2 supplies the two chlorine atoms needed for magnesium chloride and also balances hydrogen.","sol":"Step 1: Write MgO + HCl → MgCl2 + H2O.\nStep 2: Place 2 before HCl to balance chlorine.\nStep 3: Check hydrogen, oxygen, magnesium and chlorine.","steps":["Step 1: Write MgO + HCl → MgCl2 + H2O.","Step 2: Place 2 before HCl to balance chlorine.","Step 3: Check hydrogen, oxygen, magnesium and chlorine."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_metal_oxides","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Metal Oxides"}', 2),
  (3587, 828, 'Zinc oxide reacts with sulfuric acid. Name the salt and write the balanced equation.', 'text', 1, 'Combine the zinc from the oxide with the sulfate from the acid.', '{"why":"Zinc oxide reacting with sulfuric acid forms zinc sulfate and water, with all atoms balanced.","sol":"Step 1: Identify the salt as zinc sulfate.\nStep 2: Add water as the other product.\nStep 3: Check all atoms.","steps":["Step 1: Identify the salt as zinc sulfate.","Step 2: Add water as the other product.","Step 3: Check all atoms."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_metal_oxides","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Metal Oxides"}', 3),
  (3588, 828, 'Explain how the products of an acid-metal oxide reaction differ from those of an acid-carbonate reaction.', 'text', 1, 'Compare the complete product patterns for the two reactions.', '{"why":"Recognising the product patterns helps distinguish the two types of acid reactions.","sol":"Step 1: State the products of an acid reacting with a basic metal oxide.\nStep 2: State the products of an acid reacting with a metal carbonate.\nStep 3: Identify the product that distinguishes the carbonate reaction.","steps":["Step 1: State the products of an acid reacting with a basic metal oxide.","Step 2: State the products of an acid reacting with a metal carbonate.","Step 3: Identify the product that distinguishes the carbonate reaction."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_metal_oxides","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q5","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Metal Oxides"}', 4),
  (3589, 829, 'Define a base using its reaction with an acid.', 'text', 1, 'Focus on what a base does to an acid.', '{"why":"Neutralisation occurs when an acid reacts with a base to form a salt and, for the usual school-level reactions, water.","sol":"Step 1: Recall the defining property of a base.\nStep 2: State what happens when it reacts with an acid.","steps":["Step 1: Recall the defining property of a base.","Step 2: State what happens when it reacts with an acid."],"options":[],"conceptId":"chemistry_acids_bases_salts_bases","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Bases"}', 0),
  (3590, 829, 'Explain why copper(II) oxide is a base when it reacts with hydrochloric acid.', 'text', 1, 'Identify the products of the reaction.', '{"why":"The ability to neutralise an acid is the key property used to identify a base.","sol":"Step 1: Write the reaction between copper(II) oxide and hydrochloric acid.\nStep 2: Identify the salt and water formed.\nStep 3: Connect the reaction to the definition of a base.","steps":["Step 1: Write the reaction between copper(II) oxide and hydrochloric acid.","Step 2: Identify the salt and water formed.","Step 3: Connect the reaction to the definition of a base."],"options":[],"conceptId":"chemistry_acids_bases_salts_bases","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Bases"}', 1),
  (3591, 829, 'Predict the products and write the balanced equation for magnesium oxide reacting with sulfuric acid.', 'text', 1, 'The salt contains magnesium and sulfate.', '{"why":"The equation is balanced: magnesium, sulfur, hydrogen and oxygen atoms are equal on both sides.","sol":"Step 1: Identify magnesium sulfate as the salt.\nStep 2: Add water as the other product.\nStep 3: Check the atoms on both sides.","steps":["Step 1: Identify magnesium sulfate as the salt.","Step 2: Add water as the other product.","Step 3: Check the atoms on both sides."],"options":[],"conceptId":"chemistry_acids_bases_salts_bases","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Bases"}', 2),
  (3592, 829, 'An insoluble metal oxide neutralises an acid. Is it necessarily an alkali? Explain.', 'text', 1, 'Consider the meaning of the word alkali.', '{"why":"Neutralising an acid makes the oxide a base; its lack of solubility means it is not an alkali.","sol":"Step 1: Recall the definition of a base.\nStep 2: Recall the additional condition required for a substance to be an alkali.\nStep 3: Apply that condition to an insoluble oxide.","steps":["Step 1: Recall the definition of a base.","Step 2: Recall the additional condition required for a substance to be an alkali.","Step 3: Apply that condition to an insoluble oxide."],"options":[],"conceptId":"chemistry_acids_bases_salts_bases","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Bases"}', 3),
  (3593, 829, 'State the difference between a base and an alkali.', 'text', 1, 'Think about the relationship between bases and solubility in water.', '{"why":"The term alkali describes the water-soluble bases, not every base.","sol":"Step 1: Define a base.\nStep 2: Define an alkali.\nStep 3: Explain how the two definitions are related.","steps":["Step 1: Define a base.","Step 2: Define an alkali.","Step 3: Explain how the two definitions are related."],"options":[],"conceptId":"chemistry_acids_bases_salts_bases","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q5","subject":"chemistry","chapter":"acids_bases_salts","topic":"Bases"}', 4),
  (3594, 830, 'Define an alkali.', 'text', 1, 'Include both its relationship to bases and its behaviour in water.', '{"why":"The term alkali refers to water-soluble bases that produce alkaline solutions.","sol":"Step 1: Recall what a base does.\nStep 2: Add the requirement that an alkali dissolves in water.\nStep 3: Mention the ions associated with its alkaline solution.","steps":["Step 1: Recall what a base does.","Step 2: Add the requirement that an alkali dissolves in water.","Step 3: Mention the ions associated with its alkaline solution."],"options":[],"conceptId":"chemistry_acids_bases_salts_alkalis","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Alkalis"}', 0),
  (3595, 830, 'Write the ionic equation for sodium hydroxide dissolving in water.', 'text', 1, 'Name the positive and negative ions.', '{"why":"The +1 and −1 charges balance, and the sodium and hydroxide ions account for the formula NaOH.","sol":"Step 1: Identify the sodium ion, Na+.\nStep 2: Identify the hydroxide ion, OH−.\nStep 3: Write the dissociation equation and check the total charge.","steps":["Step 1: Identify the sodium ion, Na+.","Step 2: Identify the hydroxide ion, OH−.","Step 3: Write the dissociation equation and check the total charge."],"options":[],"conceptId":"chemistry_acids_bases_salts_alkalis","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Alkalis"}', 1),
  (3596, 830, 'A solution has a pH of 12. Classify it and explain your reasoning.', 'text', 1, 'Compare 12 with the neutral pH of 7.', '{"why":"Aqueous alkaline solutions have pH values above 7 under the usual school-level conditions.","sol":"Step 1: Recall the usual school-level pH classification.\nStep 2: Compare 12 with 7.\nStep 3: State the classification.","steps":["Step 1: Recall the usual school-level pH classification.","Step 2: Compare 12 with 7.","Step 3: State the classification."],"options":[],"conceptId":"chemistry_acids_bases_salts_alkalis","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Alkalis"}', 2),
  (3597, 830, 'Explain why aqueous potassium hydroxide conducts electricity.', 'text', 1, 'Think about the particles present after it dissolves.', '{"why":"Mobile charged particles allow the solution to conduct electricity.","sol":"Step 1: Identify the ions formed by potassium hydroxide.\nStep 2: State that these ions are mobile in water.\nStep 3: Explain their role in carrying electric current.","steps":["Step 1: Identify the ions formed by potassium hydroxide.","Step 2: State that these ions are mobile in water.","Step 3: Explain their role in carrying electric current."],"options":[],"conceptId":"chemistry_acids_bases_salts_alkalis","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Alkalis"}', 3),
  (3598, 830, 'State two properties of an aqueous alkali and explain each property.', 'text', 1, 'Consider litmus, pH, neutralisation and conductivity.', '{"why":"These observable properties are useful for identifying alkaline solutions.","sol":"Step 1: Choose one characteristic property.\nStep 2: Explain the chemical reason for it.\nStep 3: Choose a second property and explain it.","steps":["Step 1: Choose one characteristic property.","Step 2: Explain the chemical reason for it.","Step 3: Choose a second property and explain it."],"options":[],"conceptId":"chemistry_acids_bases_salts_alkalis","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q5","subject":"chemistry","chapter":"acids_bases_salts","topic":"Alkalis"}', 4),
  (3599, 831, 'What is litmus, and what is it used for?', 'text', 1, 'It is an indicator used to test acidic and alkaline solutions.', '{"why":"Its colour changes in characteristic ways when exposed to acids and alkalis.","sol":"Step 1: Identify litmus as a chemical indicator.\nStep 2: State what property of a solution it helps identify.","steps":["Step 1: Identify litmus as a chemical indicator.","Step 2: State what property of a solution it helps identify."],"options":[],"conceptId":"chemistry_acids_bases_salts_litmus","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Litmus"}', 0),
  (3600, 831, 'Blue litmus paper turns red in a solution. What conclusion can be drawn?', 'text', 1, 'Recall the effect of an acid on blue litmus.', '{"why":"Acids turn blue litmus paper red.","sol":"Step 1: State the observed colour change.\nStep 2: Recall which type of solution causes that change.\nStep 3: Classify the sample.","steps":["Step 1: State the observed colour change.","Step 2: Recall which type of solution causes that change.","Step 3: Classify the sample."],"options":[],"conceptId":"chemistry_acids_bases_salts_litmus","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Litmus"}', 1),
  (3601, 831, 'Red litmus paper turns blue in a sample. Classify the sample and explain why.', 'text', 1, 'Recall the effect of an alkali on red litmus.', '{"why":"The colour change is characteristic of an alkaline solution.","sol":"Step 1: Record the original colour.\nStep 2: Identify the type of solution that causes red litmus to turn blue.\nStep 3: State the classification.","steps":["Step 1: Record the original colour.","Step 2: Identify the type of solution that causes red litmus to turn blue.","Step 3: State the classification."],"options":[],"conceptId":"chemistry_acids_bases_salts_litmus","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Litmus"}', 2),
  (3602, 831, 'Red litmus remains red and blue litmus remains blue in a sample. What does this result suggest, and what can litmus not tell you?', 'text', 1, 'Distinguish broad classification from numerical measurement.', '{"why":"Litmus is a qualitative indicator and does not provide a numerical pH value.","sol":"Step 1: Interpret the absence of colour change with both papers.\nStep 2: State the conclusion that is consistent with the result.\nStep 3: Identify the limitation of litmus.","steps":["Step 1: Interpret the absence of colour change with both papers.","Step 2: State the conclusion that is consistent with the result.","Step 3: Identify the limitation of litmus."],"options":[],"conceptId":"chemistry_acids_bases_salts_litmus","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Litmus"}', 3),
  (3603, 831, 'Explain why litmus alone cannot establish whether one acidic solution is more acidic than another.', 'text', 1, 'Think about the amount of detail shown by litmus colour changes.', '{"why":"A numerical pH measurement or a more detailed indicator test is needed for a finer comparison.","sol":"Step 1: State the broad information litmus provides.\nStep 2: Explain whether it gives a numerical pH value.\nStep 3: Connect this limitation to comparing two acidic solutions.","steps":["Step 1: State the broad information litmus provides.","Step 2: Explain whether it gives a numerical pH value.","Step 3: Connect this limitation to comparing two acidic solutions."],"options":[],"conceptId":"chemistry_acids_bases_salts_litmus","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q5","subject":"chemistry","chapter":"acids_bases_salts","topic":"Litmus"}', 4),
  (3604, 832, 'What is universal indicator, and what information does it provide?', 'text', 1, 'Think about its range of colours.', '{"why":"Its range of colours gives more information about pH than litmus alone.","sol":"Step 1: Define universal indicator.\nStep 2: Explain what its colour changes indicate.\nStep 3: Distinguish this information from the simpler litmus test.","steps":["Step 1: Define universal indicator.","Step 2: Explain what its colour changes indicate.","Step 3: Distinguish this information from the simpler litmus test."],"options":[],"conceptId":"chemistry_acids_bases_salts_universal_indicator","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Universal Indicator"}', 0),
  (3605, 832, 'Universal indicator turns red in a sample. What does this usually suggest?', 'text', 1, 'Recall the colour associated with the strongly acidic region.', '{"why":"Red is typically associated with the low-pH, strongly acidic region.","sol":"Step 1: Compare red with the supplied indicator chart.\nStep 2: Identify the region represented by red.\nStep 3: State the likely classification.","steps":["Step 1: Compare red with the supplied indicator chart.","Step 2: Identify the region represented by red.","Step 3: State the likely classification."],"options":[],"conceptId":"chemistry_acids_bases_salts_universal_indicator","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Universal Indicator"}', 1),
  (3606, 832, 'A sample turns universal indicator green. Interpret the result.', 'text', 1, 'Green is associated with the middle of the usual pH scale.', '{"why":"Green typically represents the neutral region on a universal-indicator chart.","sol":"Step 1: Identify the usual meaning of green on the chart.\nStep 2: Relate the colour to the neutral region.\nStep 3: State the approximate pH region.","steps":["Step 1: Identify the usual meaning of green on the chart.","Step 2: Relate the colour to the neutral region.","Step 3: State the approximate pH region."],"options":[],"conceptId":"chemistry_acids_bases_salts_universal_indicator","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Universal Indicator"}', 2),
  (3607, 832, 'Sample A turns universal indicator yellow and Sample B turns it blue. Which is more alkaline? Explain.', 'text', 1, 'Compare the usual positions of yellow and blue on the colour chart.', '{"why":"The colours correspond to different regions of the pH scale.","sol":"Step 1: Interpret the yellow result.\nStep 2: Interpret the blue result.\nStep 3: Compare the acidity or alkalinity of the two samples.","steps":["Step 1: Interpret the yellow result.","Step 2: Interpret the blue result.","Step 3: Compare the acidity or alkalinity of the two samples."],"options":[],"conceptId":"chemistry_acids_bases_salts_universal_indicator","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Universal Indicator"}', 3),
  (3608, 832, 'Give one limitation of universal indicator and explain why it matters.', 'text', 1, 'Consider colour matching and measurement precision.', '{"why":"Colour-based estimates depend on correct observation and comparison with the appropriate reference chart.","sol":"Step 1: State that universal indicator relies on a colour change.\nStep 2: Identify a limitation of interpreting that colour.\nStep 3: Explain how the limitation affects the result.","steps":["Step 1: State that universal indicator relies on a colour change.","Step 2: Identify a limitation of interpreting that colour.","Step 3: Explain how the limitation affects the result."],"options":[],"conceptId":"chemistry_acids_bases_salts_universal_indicator","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q5","subject":"chemistry","chapter":"acids_bases_salts","topic":"Universal Indicator"}', 4),
  (3609, 833, 'State what pH values below 7, equal to 7 and above 7 indicate under the usual school-level classification.', 'text', 1, 'Use the three main regions of the pH scale.', '{"why":"These three regions provide the standard school-level classification of aqueous solutions by pH.","sol":"Step 1: Identify the acidic region.\nStep 2: Identify the neutral reference value.\nStep 3: Identify the alkaline region.","steps":["Step 1: Identify the acidic region.","Step 2: Identify the neutral reference value.","Step 3: Identify the alkaline region."],"options":[],"conceptId":"chemistry_acids_bases_salts_ph_scale","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"pH Scale"}', 0),
  (3610, 833, 'A solution has pH 2. Classify it and justify your answer.', 'text', 1, 'Compare 2 with the neutral value.', '{"why":"Acidic solutions have pH values below 7 under the usual school-level classification.","sol":"Step 1: Recall that pH 7 is neutral.\nStep 2: Compare pH 2 with 7.\nStep 3: State the classification.","steps":["Step 1: Recall that pH 7 is neutral.","Step 2: Compare pH 2 with 7.","Step 3: State the classification."],"options":[],"conceptId":"chemistry_acids_bases_salts_ph_scale","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"pH Scale"}', 1),
  (3611, 833, 'Which solution is more acidic: pH 3 or pH 5? Calculate the difference in pH units.', 'text', 1, 'The lower pH indicates greater acidity.', '{"why":"Lower pH indicates greater acidity, and the numerical difference is two pH units.","sol":"Step 1: Compare 3 and 5.\nStep 2: Identify the lower pH value.\nStep 3: Subtract the values to find the difference.","steps":["Step 1: Compare 3 and 5.","Step 2: Identify the lower pH value.","Step 3: Subtract the values to find the difference."],"options":[],"conceptId":"chemistry_acids_bases_salts_ph_scale","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"pH Scale"}', 2),
  (3612, 833, 'Explain what a change of one pH unit means in terms of hydrogen-ion activity.', 'text', 1, 'The pH scale is logarithmic, not linear.', '{"why":"The logarithmic nature of pH means equal numerical changes do not represent equal additive changes in acidity.","sol":"Step 1: Recall that the pH scale is logarithmic.\nStep 2: State the change associated with one pH unit.\nStep 3: Distinguish activity from the simplified concentration explanation used at school.","steps":["Step 1: Recall that the pH scale is logarithmic.","Step 2: State the change associated with one pH unit.","Step 3: Distinguish activity from the simplified concentration explanation used at school."],"options":[],"conceptId":"chemistry_acids_bases_salts_ph_scale","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"pH Scale"}', 3),
  (3613, 833, 'Explain why pH alone cannot tell you the total amount of acid present in a sample.', 'text', 1, 'Distinguish acidity per unit volume from the total quantity of substance.', '{"why":"A small volume and a large volume can have the same pH but contain different total amounts of acid.","sol":"Step 1: State what pH describes.\nStep 2: Consider the effect of sample volume.\nStep 3: Explain why two samples with similar pH may contain different total amounts of acid.","steps":["Step 1: State what pH describes.","Step 2: Consider the effect of sample volume.","Step 3: Explain why two samples with similar pH may contain different total amounts of acid."],"options":[],"conceptId":"chemistry_acids_bases_salts_ph_scale","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q5","subject":"chemistry","chapter":"acids_bases_salts","topic":"pH Scale"}', 4),
  (3614, 834, 'Arrange solutions with pH 2, pH 4 and pH 6 from most acidic to least acidic.', 'text', 1, 'The lowest pH represents the greatest acidity.', '{"why":"Lower pH values indicate greater acidity.","sol":"Step 1: Compare the three pH values.\nStep 2: Place the lowest value first.\nStep 3: Continue in increasing order.","steps":["Step 1: Compare the three pH values.","Step 2: Place the lowest value first.","Step 3: Continue in increasing order."],"options":[],"conceptId":"chemistry_acids_bases_salts_interpreting_ph","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Interpreting pH"}', 0),
  (3615, 834, 'Calculate the pH difference between pH 4 and pH 6, then state the approximate hydrogen-ion activity ratio.', 'text', 1, 'Subtract the pH values, then use the tenfold change per unit.', '{"why":"The pH scale is logarithmic, so a two-unit decrease corresponds to a hundredfold increase in hydrogen-ion activity.","sol":"Step 1: Calculate 6 − 4 = 2 pH units.\nStep 2: A difference of one unit corresponds to a factor of 10.\nStep 3: For two units, calculate 10 × 10 = 100.","steps":["Step 1: Calculate 6 − 4 = 2 pH units.","Step 2: A difference of one unit corresponds to a factor of 10.","Step 3: For two units, calculate 10 × 10 = 100."],"options":[],"conceptId":"chemistry_acids_bases_salts_interpreting_ph","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Interpreting pH"}', 1),
  (3616, 834, 'A solution changes from pH 5 to pH 3. Explain what this change indicates.', 'text', 1, 'Compare the two values and remember that lower pH means greater acidity.', '{"why":"A fall in pH indicates increasing acidity, with each pH unit representing a tenfold change in hydrogen-ion activity.","sol":"Step 1: Subtract 3 from 5 to find the change of two units.\nStep 2: Determine whether the pH has risen or fallen.\nStep 3: Interpret the change in acidity.","steps":["Step 1: Subtract 3 from 5 to find the change of two units.","Step 2: Determine whether the pH has risen or fallen.","Step 3: Interpret the change in acidity."],"options":[],"conceptId":"chemistry_acids_bases_salts_interpreting_ph","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Interpreting pH"}', 2),
  (3617, 834, 'Solution A has pH 9 and Solution B has pH 12. Which is more alkaline, and by how many pH units?', 'text', 1, 'The higher pH is more alkaline.', '{"why":"The higher pH indicates greater alkalinity; the difference is 12 − 9 = 3 units.","sol":"Step 1: Compare 9 and 12.\nStep 2: Identify the higher pH value.\nStep 3: Calculate 12 − 9.","steps":["Step 1: Compare 9 and 12.","Step 2: Identify the higher pH value.","Step 3: Calculate 12 − 9."],"options":[],"conceptId":"chemistry_acids_bases_salts_interpreting_ph","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Interpreting pH"}', 3),
  (3618, 834, 'A learner claims that a pH 4 solution contains exactly twice as much acid as a pH 5 solution. Explain why this conclusion is incorrect.', 'text', 1, 'Compare a one-unit pH change with the logarithmic scale.', '{"why":"The pH scale is logarithmic, and pH describes acidity rather than the total quantity of acid in the sample.","sol":"Step 1: Recall that a one-unit pH difference corresponds to a tenfold change in hydrogen-ion activity.\nStep 2: Explain why this is not a twofold change.\nStep 3: Distinguish hydrogen-ion activity from the total amount of acid.","steps":["Step 1: Recall that a one-unit pH difference corresponds to a tenfold change in hydrogen-ion activity.","Step 2: Explain why this is not a twofold change.","Step 3: Distinguish hydrogen-ion activity from the total amount of acid."],"options":[],"conceptId":"chemistry_acids_bases_salts_interpreting_ph","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q5","subject":"chemistry","chapter":"acids_bases_salts","topic":"Interpreting pH"}', 4),
  (3619, 835, 'Define a strong acid in terms of its ionisation in water.', 'text', 1, 'Think about whether most acid molecules ionise or remain un-ionised.', '{"why":"Strong acids produce their ions to a much greater extent than weak acids under comparable conditions.","sol":"Step 1: Recall what acid strength describes.\nStep 2: State the extent of ionisation of a strong acid.","steps":["Step 1: Recall what acid strength describes.","Step 2: State the extent of ionisation of a strong acid."],"options":[],"conceptId":"chemistry_acids_bases_salts_strong_and_weak_acids","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Strong and Weak Acids"}', 0),
  (3620, 835, 'Explain why ethanoic acid is classified as a weak acid.', 'text', 1, 'Consider the extent of ionisation and the meaning of the double arrow.', '{"why":"A weak acid does not ionise completely; a significant proportion of its molecules remain un-ionised.","sol":"Step 1: Write the reversible ionisation of ethanoic acid.\nStep 2: Explain what the double arrow represents.\nStep 3: Connect partial ionisation to the definition of a weak acid.","steps":["Step 1: Write the reversible ionisation of ethanoic acid.","Step 2: Explain what the double arrow represents.","Step 3: Connect partial ionisation to the definition of a weak acid."],"options":[],"conceptId":"chemistry_acids_bases_salts_strong_and_weak_acids","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Strong and Weak Acids"}', 1),
  (3621, 835, 'Write the simplified ionisation equation for hydrochloric acid in water.', 'text', 1, 'Identify the hydrogen ion and chloride ion.', '{"why":"The equation represents the essentially complete ionisation of hydrochloric acid in water using the school-level hydrogen-ion notation.","sol":"Step 1: Write the formula of hydrochloric acid.\nStep 2: Identify the ions formed.\nStep 3: Use a single arrow to represent essentially complete ionisation.","steps":["Step 1: Write the formula of hydrochloric acid.","Step 2: Identify the ions formed.","Step 3: Use a single arrow to represent essentially complete ionisation."],"options":[],"conceptId":"chemistry_acids_bases_salts_strong_and_weak_acids","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Strong and Weak Acids"}', 2),
  (3622, 835, 'Write the ionisation equation for ethanoic acid and explain why it uses a double arrow.', 'text', 1, 'Ethanoic acid has the formula CH3COOH.', '{"why":"Weak acids establish an equilibrium because only a proportion of the acid molecules ionise.","sol":"Step 1: Write CH3COOH on the left.\nStep 2: Write H+ and CH3COO− on the right.\nStep 3: Use a double arrow to show reversible partial ionisation.","steps":["Step 1: Write CH3COOH on the left.","Step 2: Write H+ and CH3COO− on the right.","Step 3: Use a double arrow to show reversible partial ionisation."],"options":[],"conceptId":"chemistry_acids_bases_salts_strong_and_weak_acids","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Strong and Weak Acids"}', 3),
  (3623, 835, 'Explain the difference between a strong acid and a concentrated acid.', 'text', 1, 'One term concerns ionisation; the other concerns amount per unit volume.', '{"why":"A solution may be strong but dilute, or weak but concentrated.","sol":"Step 1: Define acid strength.\nStep 2: Define concentration.\nStep 3: Explain why the terms cannot be used interchangeably.","steps":["Step 1: Define acid strength.","Step 2: Define concentration.","Step 3: Explain why the terms cannot be used interchangeably."],"options":[],"conceptId":"chemistry_acids_bases_salts_strong_and_weak_acids","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q5","subject":"chemistry","chapter":"acids_bases_salts","topic":"Strong and Weak Acids"}', 4),
  (3624, 836, 'Explain what is meant by a strong base using sodium hydroxide as an example.', 'text', 1, 'Consider how sodium hydroxide behaves when dissolved in water.', '{"why":"Strong bases such as sodium hydroxide produce their ions extensively in aqueous solution.","sol":"Step 1: State that sodium hydroxide is a strong base.\nStep 2: Write its dissociation equation.\nStep 3: Explain what the equation says about ion formation.","steps":["Step 1: State that sodium hydroxide is a strong base.","Step 2: Write its dissociation equation.","Step 3: Explain what the equation says about ion formation."],"options":[],"conceptId":"chemistry_acids_bases_salts_strong_and_weak_bases","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Strong and Weak Bases"}', 0),
  (3625, 836, 'Write the equation for aqueous ammonia reacting with water and explain the double arrow.', 'text', 1, 'The products are ammonium ions and hydroxide ions.', '{"why":"Aqueous ammonia is a weak base because only a proportion reacts with water to form ions.","sol":"Step 1: Write NH3 and H2O as the reactants.\nStep 2: Write NH4+ and OH− as the products.\nStep 3: Use a double arrow to show reversible partial reaction.","steps":["Step 1: Write NH3 and H2O as the reactants.","Step 2: Write NH4+ and OH− as the products.","Step 3: Use a double arrow to show reversible partial reaction."],"options":[],"conceptId":"chemistry_acids_bases_salts_strong_and_weak_bases","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Strong and Weak Bases"}', 1),
  (3626, 836, 'Classify sodium hydroxide and aqueous ammonia as strong or weak bases.', 'text', 1, 'Compare their behaviour in water.', '{"why":"Sodium hydroxide dissociates essentially completely, whereas ammonia reacts only partially with water to form ions.","sol":"Step 1: Recall the behaviour of sodium hydroxide in water.\nStep 2: Recall the behaviour of ammonia with water.\nStep 3: Classify each base.","steps":["Step 1: Recall the behaviour of sodium hydroxide in water.","Step 2: Recall the behaviour of ammonia with water.","Step 3: Classify each base."],"options":[],"conceptId":"chemistry_acids_bases_salts_strong_and_weak_bases","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Strong and Weak Bases"}', 2),
  (3627, 836, 'Explain why a dilute sodium hydroxide solution is still described as a solution of a strong base.', 'text', 1, 'Separate concentration from base strength.', '{"why":"Strength and concentration describe different properties; dilution does not turn sodium hydroxide into a weak base.","sol":"Step 1: Define concentration in terms of amount per unit volume.\nStep 2: Recall the behaviour of sodium hydroxide in water.\nStep 3: Explain why dilution does not change its classification as a strong base.","steps":["Step 1: Define concentration in terms of amount per unit volume.","Step 2: Recall the behaviour of sodium hydroxide in water.","Step 3: Explain why dilution does not change its classification as a strong base."],"options":[],"conceptId":"chemistry_acids_bases_salts_strong_and_weak_bases","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Strong and Weak Bases"}', 3),
  (3628, 836, 'Explain why the words strong and concentrated cannot be used interchangeably when describing bases.', 'text', 1, 'One describes behaviour in water, and the other describes amount per volume.', '{"why":"The two terms refer to different chemical properties.","sol":"Step 1: Define base strength.\nStep 2: Define concentration.\nStep 3: Give a reason why a strong base can be dilute.","steps":["Step 1: Define base strength.","Step 2: Define concentration.","Step 3: Give a reason why a strong base can be dilute."],"options":[],"conceptId":"chemistry_acids_bases_salts_strong_and_weak_bases","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q5","subject":"chemistry","chapter":"acids_bases_salts","topic":"Strong and Weak Bases"}', 4),
  (3629, 837, 'Define neutralisation and state the usual products when an acid reacts with a metal hydroxide.', 'text', 1, 'Recall the general word equation.', '{"why":"The acid and base react to form the salt, while hydrogen and hydroxide ions form water in the net ionic equation.","sol":"Step 1: State that neutralisation involves an acid reacting with a base.\nStep 2: Identify the salt formed.\nStep 3: Identify the other product in the usual acid-hydroxide reaction.","steps":["Step 1: State that neutralisation involves an acid reacting with a base.","Step 2: Identify the salt formed.","Step 3: Identify the other product in the usual acid-hydroxide reaction."],"options":[],"conceptId":"chemistry_acids_bases_salts_neutralisation","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Neutralisation"}', 0),
  (3630, 837, 'Write and balance the equation for hydrochloric acid reacting with sodium hydroxide.', 'text', 1, 'The salt formed is sodium chloride.', '{"why":"One sodium, one chlorine, two hydrogen and one oxygen atom occur on each side.","sol":"Step 1: Identify sodium chloride as the salt.\nStep 2: Add water as the other product.\nStep 3: Check that all atoms balance.","steps":["Step 1: Identify sodium chloride as the salt.","Step 2: Add water as the other product.","Step 3: Check that all atoms balance."],"options":[],"conceptId":"chemistry_acids_bases_salts_neutralisation","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Neutralisation"}', 1),
  (3631, 837, 'Write and balance the equation for sulfuric acid reacting completely with potassium hydroxide.', 'text', 1, 'The salt is potassium sulfate, which contains two potassium atoms.', '{"why":"The coefficients balance potassium, sulfur, hydrogen and oxygen atoms.","sol":"Step 1: Write H2SO4 + KOH → K2SO4 + H2O.\nStep 2: Place 2 before KOH to balance potassium.\nStep 3: Place 2 before H2O to balance hydrogen and oxygen.\nStep 4: Check each element on both sides.","steps":["Step 1: Write H2SO4 + KOH → K2SO4 + H2O.","Step 2: Place 2 before KOH to balance potassium.","Step 3: Place 2 before H2O to balance hydrogen and oxygen.","Step 4: Check each element on both sides."],"options":[],"conceptId":"chemistry_acids_bases_salts_neutralisation","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Neutralisation"}', 2),
  (3632, 837, 'Write the net ionic equation for neutralisation between hydrogen ions and hydroxide ions.', 'text', 1, 'The two ions combine to form water.', '{"why":"The +1 and −1 charges cancel, and the atoms form one water molecule.","sol":"Step 1: Write H+ and OH− as the reactants.\nStep 2: Write H2O as the product.\nStep 3: Check that both atoms and total charge balance.","steps":["Step 1: Write H+ and OH− as the reactants.","Step 2: Write H2O as the product.","Step 3: Check that both atoms and total charge balance."],"options":[],"conceptId":"chemistry_acids_bases_salts_neutralisation","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Neutralisation"}', 3),
  (3633, 837, 'Explain why mixing an acid and a base does not always produce a solution with pH exactly 7.', 'text', 1, 'Consider the quantities and strengths of the reacting substances.', '{"why":"Neutralisation occurs through reaction between acidic and basic species, but the mixture is not necessarily neutral unless the conditions give the appropriate balance.","sol":"Step 1: Recall that pH describes the resulting solution.\nStep 2: Consider what happens if excess acid remains.\nStep 3: Consider what happens if excess base remains.\nStep 4: State why the final pH depends on the reaction conditions.","steps":["Step 1: Recall that pH describes the resulting solution.","Step 2: Consider what happens if excess acid remains.","Step 3: Consider what happens if excess base remains.","Step 4: State why the final pH depends on the reaction conditions."],"options":[],"conceptId":"chemistry_acids_bases_salts_neutralisation","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q5","subject":"chemistry","chapter":"acids_bases_salts","topic":"Neutralisation"}', 4),
  (3634, 838, 'What is a salt, and what does it mean for a salt to be soluble?', 'text', 1, 'Define a salt first, then explain what happens when a soluble salt is added to water.', '{"why":"The definition distinguishes the compound itself from its ability to dissolve in water.","sol":"Step 1: State that a salt is an ionic compound containing positive and negative ions.\nStep 2: Explain that a soluble salt dissolves in water to form a solution.","steps":["Step 1: State that a salt is an ionic compound containing positive and negative ions.","Step 2: Explain that a soluble salt dissolves in water to form a solution."],"options":[],"conceptId":"chemistry_acids_bases_salts_soluble_salts","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Soluble Salts"}', 0),
  (3635, 838, 'Name the salt KNO₃ and identify its positive and negative ions.', 'text', 1, 'K represents potassium, while NO₃ is nitrate.', '{"why":"The compound''s name reflects the positive ion followed by the negative ion.","sol":"Step 1: Identify K⁺ as the potassium ion.\nStep 2: Identify NO₃⁻ as the nitrate ion.\nStep 3: Combine the ion names.","steps":["Step 1: Identify K⁺ as the potassium ion.","Step 2: Identify NO₃⁻ as the nitrate ion.","Step 3: Combine the ion names."],"options":[],"conceptId":"chemistry_acids_bases_salts_soluble_salts","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Soluble Salts"}', 1),
  (3636, 838, 'Which acid is associated with copper(II) sulfate? Explain how the salt''s name tells you.', 'text', 1, 'Focus on the word sulfate.', '{"why":"The acid''s anion determines the ending of the salt''s name.","sol":"Step 1: Identify sulfate as the negative ion in the salt.\nStep 2: Recall the acid associated with sulfate salts.","steps":["Step 1: Identify sulfate as the negative ion in the salt.","Step 2: Recall the acid associated with sulfate salts."],"options":[],"conceptId":"chemistry_acids_bases_salts_soluble_salts","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Soluble Salts"}', 2),
  (3637, 838, 'A student calls NaCl potassium chloride. Identify the error and give the correct name.', 'text', 1, 'Read the positive ion at the beginning of the formula.', '{"why":"Correctly identifying each ion is necessary to name a salt.","sol":"Step 1: Identify Na as sodium, not potassium.\nStep 2: Identify Cl as chloride.\nStep 3: Combine the correct names.","steps":["Step 1: Identify Na as sodium, not potassium.","Step 2: Identify Cl as chloride.","Step 3: Combine the correct names."],"options":[],"conceptId":"chemistry_acids_bases_salts_soluble_salts","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Soluble Salts"}', 3),
  (3638, 838, 'A salt dissolves in water. What does this observation tell you about its solubility, and what does it not tell you about every other salt?', 'text', 1, 'Distinguish the observed salt from salts in general.', '{"why":"Different salts have different solubilities.","sol":"Step 1: Use the observation to classify the tested salt as soluble under those conditions.\nStep 2: Avoid generalising the result to every salt.","steps":["Step 1: Use the observation to classify the tested salt as soluble under those conditions.","Step 2: Avoid generalising the result to every salt."],"options":[],"conceptId":"chemistry_acids_bases_salts_soluble_salts","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q5","subject":"chemistry","chapter":"acids_bases_salts","topic":"Soluble Salts"}', 4),
  (3639, 839, 'What is an insoluble salt?', 'text', 1, 'Think about how much of the salt dissolves in water.', '{"why":"Insoluble is a practical description of very low solubility, not necessarily absolute zero solubility.","sol":"Step 1: Consider whether the salt dissolves readily in water.\nStep 2: Describe its very low solubility.","steps":["Step 1: Consider whether the salt dissolves readily in water.","Step 2: Describe its very low solubility."],"options":[],"conceptId":"chemistry_acids_bases_salts_insoluble_salts","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Insoluble Salts"}', 0),
  (3640, 839, 'Name PbI₂ and identify the ions represented in its formula.', 'text', 1, 'Pb is lead and I is iodide in this compound.', '{"why":"The Roman numeral II identifies the charge of the lead ion in this compound.","sol":"Step 1: Identify Pb²⁺ as the lead(II) ion.\nStep 2: Identify I⁻ as the iodide ion.\nStep 3: Combine the names.","steps":["Step 1: Identify Pb²⁺ as the lead(II) ion.","Step 2: Identify I⁻ as the iodide ion.","Step 3: Combine the names."],"options":[],"conceptId":"chemistry_acids_bases_salts_insoluble_salts","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Insoluble Salts"}', 1),
  (3641, 839, 'What is a precipitate?', 'text', 1, 'Describe how the solid appears in a reaction involving solutions.', '{"why":"The term describes the solid product formed from solutions.","sol":"Step 1: Start with substances dissolved in solutions.\nStep 2: Explain that an insoluble solid forms.\nStep 3: Name that solid.","steps":["Step 1: Start with substances dissolved in solutions.","Step 2: Explain that an insoluble solid forms.","Step 3: Name that solid."],"options":[],"conceptId":"chemistry_acids_bases_salts_insoluble_salts","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Insoluble Salts"}', 2),
  (3642, 839, 'A student says that all salts dissolve readily in water. Use one example to correct the statement.', 'text', 1, 'Choose one of the insoluble salts in the notes.', '{"why":"Solubility depends on the particular salt.","sol":"Step 1: State that salt solubilities differ.\nStep 2: Name an example of an insoluble salt.","steps":["Step 1: State that salt solubilities differ.","Step 2: Name an example of an insoluble salt."],"options":[],"conceptId":"chemistry_acids_bases_salts_insoluble_salts","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Insoluble Salts"}', 3),
  (3643, 839, 'Name BaSO₄ and explain how its formula identifies the two parts of the name.', 'text', 1, 'Separate the positive ion from the negative ion.', '{"why":"The names of the ions determine the name of the salt.","sol":"Step 1: Identify Ba as barium.\nStep 2: Identify SO₄ as sulfate.\nStep 3: Combine the names.","steps":["Step 1: Identify Ba as barium.","Step 2: Identify SO₄ as sulfate.","Step 3: Combine the names."],"options":[],"conceptId":"chemistry_acids_bases_salts_insoluble_salts","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q5","subject":"chemistry","chapter":"acids_bases_salts","topic":"Insoluble Salts"}', 4),
  (3644, 840, 'State the general word equation for a suitable reactive metal reacting with a dilute acid.', 'text', 1, 'There are two products: a salt and a gas.', '{"why":"A suitable reactive metal displaces hydrogen from the dilute acid.","sol":"Step 1: Name the reactants: reactive metal and dilute acid.\nStep 2: Name the products: salt and hydrogen gas.","steps":["Step 1: Name the reactants: reactive metal and dilute acid.","Step 2: Name the products: salt and hydrogen gas."],"options":[],"conceptId":"chemistry_acids_bases_salts_preparing_soluble_salts_from_acids_and_metals","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Preparing Soluble Salts from Acids and Metals"}', 0),
  (3645, 840, 'Write and balance the equation for magnesium reacting with dilute hydrochloric acid.', 'text', 1, 'Magnesium chloride contains two chlorine atoms.', '{"why":"Both sides contain one magnesium atom, two hydrogen atoms and two chlorine atoms.","sol":"Step 1: Write Mg + HCl → MgCl₂ + H₂.\nStep 2: Place 2 before HCl to balance chlorine.\nStep 3: Check magnesium, hydrogen and chlorine atoms.","steps":["Step 1: Write Mg + HCl → MgCl₂ + H₂.","Step 2: Place 2 before HCl to balance chlorine.","Step 3: Check magnesium, hydrogen and chlorine atoms."],"options":[],"conceptId":"chemistry_acids_bases_salts_preparing_soluble_salts_from_acids_and_metals","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Preparing Soluble Salts from Acids and Metals"}', 1),
  (3646, 840, 'Why is a little excess metal added, and what must be done with it afterwards?', 'text', 1, 'Think about ensuring that the acid has reacted and how to remove a solid.', '{"why":"The aim is to obtain a salt solution without excess metal or unused acid.","sol":"Step 1: Explain why excess metal helps ensure the acid is used up.\nStep 2: Identify the method used to separate the remaining solid.","steps":["Step 1: Explain why excess metal helps ensure the acid is used up.","Step 2: Identify the method used to separate the remaining solid."],"options":[],"conceptId":"chemistry_acids_bases_salts_preparing_soluble_salts_from_acids_and_metals","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Preparing Soluble Salts from Acids and Metals"}', 2),
  (3647, 840, 'Zinc reacts with dilute sulfuric acid. Name the salt and write the balanced equation.', 'text', 1, 'Sulfuric acid forms sulfate salts.', '{"why":"The zinc supplies the positive ion and sulfuric acid supplies the sulfate ion.","sol":"Step 1: Identify the salt as zinc sulfate.\nStep 2: Add hydrogen gas as the second product.\nStep 3: Balance the equation.","steps":["Step 1: Identify the salt as zinc sulfate.","Step 2: Add hydrogen gas as the second product.","Step 3: Balance the equation."],"options":[],"conceptId":"chemistry_acids_bases_salts_preparing_soluble_salts_from_acids_and_metals","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Preparing Soluble Salts from Acids and Metals"}', 3),
  (3648, 840, 'After filtering off the excess metal, describe how crystals of the soluble salt can be obtained from the filtrate.', 'text', 1, 'The salt is dissolved, so first remove some water without heating the solution to dryness.', '{"why":"Concentrating the solution and then cooling it allows the dissolved salt to crystallise.","sol":"Step 1: Heat the filtrate gently to concentrate the solution.\nStep 2: Stop at the crystallisation point rather than heating to dryness.\nStep 3: Allow the solution to cool and crystals to form.\nStep 4: Separate and dry the crystals.","steps":["Step 1: Heat the filtrate gently to concentrate the solution.","Step 2: Stop at the crystallisation point rather than heating to dryness.","Step 3: Allow the solution to cool and crystals to form.","Step 4: Separate and dry the crystals."],"options":[],"conceptId":"chemistry_acids_bases_salts_preparing_soluble_salts_from_acids_and_metals","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q5","subject":"chemistry","chapter":"acids_bases_salts","topic":"Preparing Soluble Salts from Acids and Metals"}', 4),
  (3649, 841, 'State the general word equation for an insoluble base reacting with an acid.', 'text', 1, 'Name the two products.', '{"why":"The base reacts with the acid to form a salt and water.","sol":"Step 1: Identify the reactants as an insoluble base and an acid.\nStep 2: State the products formed in the reaction.","steps":["Step 1: Identify the reactants as an insoluble base and an acid.","Step 2: State the products formed in the reaction."],"options":[],"conceptId":"chemistry_acids_bases_salts_preparing_soluble_salts_from_insoluble_bases","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Preparing Soluble Salts from Insoluble Bases"}', 0),
  (3650, 841, 'Write the balanced equation for copper(II) oxide reacting with sulfuric acid.', 'text', 1, 'The salt is copper(II) sulfate.', '{"why":"The equation has one copper, one sulfur, two hydrogen and five oxygen atoms on each side.","sol":"Step 1: Write CuO + H₂SO₄ → CuSO₄ + H₂O.\nStep 2: Count Cu, S, H and O atoms on each side.\nStep 3: Confirm that each element has the same number of atoms on both sides.","steps":["Step 1: Write CuO + H₂SO₄ → CuSO₄ + H₂O.","Step 2: Count Cu, S, H and O atoms on each side.","Step 3: Confirm that each element has the same number of atoms on both sides."],"options":[],"conceptId":"chemistry_acids_bases_salts_preparing_soluble_salts_from_insoluble_bases","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Preparing Soluble Salts from Insoluble Bases"}', 1),
  (3651, 841, 'Why is excess insoluble base added during preparation of a soluble salt?', 'text', 1, 'Consider how the method ensures that the acid has been used up.', '{"why":"Using excess insoluble base avoids leaving unused acid in the final salt solution.","sol":"Step 1: Explain that the base reacts with the acid.\nStep 2: Explain why a small amount of base is deliberately left unreacted.","steps":["Step 1: Explain that the base reacts with the acid.","Step 2: Explain why a small amount of base is deliberately left unreacted."],"options":[],"conceptId":"chemistry_acids_bases_salts_preparing_soluble_salts_from_insoluble_bases","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Preparing Soluble Salts from Insoluble Bases"}', 2),
  (3652, 841, 'Magnesium oxide reacts with hydrochloric acid. Name the salt and write the balanced equation.', 'text', 1, 'Hydrochloric acid forms chloride salts.', '{"why":"The equation conserves magnesium, oxygen, hydrogen and chlorine atoms.","sol":"Step 1: Name the salt as magnesium chloride.\nStep 2: Add water as the other product.\nStep 3: Balance chlorine and hydrogen by placing 2 before HCl.","steps":["Step 1: Name the salt as magnesium chloride.","Step 2: Add water as the other product.","Step 3: Balance chlorine and hydrogen by placing 2 before HCl."],"options":[],"conceptId":"chemistry_acids_bases_salts_preparing_soluble_salts_from_insoluble_bases","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Preparing Soluble Salts from Insoluble Bases"}', 3),
  (3653, 841, 'After filtering off the excess base, explain how to obtain crystals from the filtrate.', 'text', 1, 'Describe concentration, cooling and crystal collection in order.', '{"why":"The dissolved salt crystallises as the concentrated solution cools.","sol":"Step 1: Gently heat the filtrate to concentrate it.\nStep 2: Stop at the crystallisation point rather than evaporating to dryness.\nStep 3: Cool the concentrated solution.\nStep 4: Separate and dry the crystals that form.","steps":["Step 1: Gently heat the filtrate to concentrate it.","Step 2: Stop at the crystallisation point rather than evaporating to dryness.","Step 3: Cool the concentrated solution.","Step 4: Separate and dry the crystals that form."],"options":[],"conceptId":"chemistry_acids_bases_salts_preparing_soluble_salts_from_insoluble_bases","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q5","subject":"chemistry","chapter":"acids_bases_salts","topic":"Preparing Soluble Salts from Insoluble Bases"}', 4),
  (3654, 842, 'State the general word equation for a carbonate reacting with an acid.', 'text', 1, 'There are three products.', '{"why":"Carbon dioxide release explains the fizzing observed during the reaction.","sol":"Step 1: Identify the reactants as a carbonate and an acid.\nStep 2: List the salt, water and gas formed.","steps":["Step 1: Identify the reactants as a carbonate and an acid.","Step 2: List the salt, water and gas formed."],"options":[],"conceptId":"chemistry_acids_bases_salts_preparing_soluble_salts_from_acids_and_carbonates","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Preparing Soluble Salts from Acids and Carbonates"}', 0),
  (3655, 842, 'Write the balanced equation for copper(II) carbonate reacting with sulfuric acid.', 'text', 1, 'The salt is copper(II) sulfate.', '{"why":"Each element has the same total number of atoms on both sides.","sol":"Step 1: Write CuCO₃ + H₂SO₄ → CuSO₄ + H₂O + CO₂.\nStep 2: Check copper, sulfur, hydrogen, carbon and oxygen atoms.\nStep 3: Confirm that the equation is balanced.","steps":["Step 1: Write CuCO₃ + H₂SO₄ → CuSO₄ + H₂O + CO₂.","Step 2: Check copper, sulfur, hydrogen, carbon and oxygen atoms.","Step 3: Confirm that the equation is balanced."],"options":[],"conceptId":"chemistry_acids_bases_salts_preparing_soluble_salts_from_acids_and_carbonates","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Preparing Soluble Salts from Acids and Carbonates"}', 1),
  (3656, 842, 'Why does fizzing occur when an insoluble carbonate is added to a suitable dilute acid?', 'text', 1, 'Identify the gaseous product in the general reaction.', '{"why":"Bubbles form as the gaseous product escapes from the reaction mixture.","sol":"Step 1: Recall the products of an acid-carbonate reaction.\nStep 2: Identify which product is a gas.\nStep 3: Connect gas release with the observed bubbles.","steps":["Step 1: Recall the products of an acid-carbonate reaction.","Step 2: Identify which product is a gas.","Step 3: Connect gas release with the observed bubbles."],"options":[],"conceptId":"chemistry_acids_bases_salts_preparing_soluble_salts_from_acids_and_carbonates","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Preparing Soluble Salts from Acids and Carbonates"}', 2),
  (3657, 842, 'Zinc carbonate reacts with hydrochloric acid. Name the salt and write the balanced equation.', 'text', 1, 'Hydrochloric acid forms chloride salts.', '{"why":"The balanced equation accounts for every atom in the reactants and products.","sol":"Step 1: Identify the salt as zinc chloride.\nStep 2: Add water and carbon dioxide as products.\nStep 3: Place 2 before HCl to balance hydrogen and chlorine.","steps":["Step 1: Identify the salt as zinc chloride.","Step 2: Add water and carbon dioxide as products.","Step 3: Place 2 before HCl to balance hydrogen and chlorine."],"options":[],"conceptId":"chemistry_acids_bases_salts_preparing_soluble_salts_from_acids_and_carbonates","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Preparing Soluble Salts from Acids and Carbonates"}', 3),
  (3658, 842, 'Why is excess insoluble carbonate filtered off before the salt solution is concentrated?', 'text', 1, 'Distinguish the undissolved reactant from the dissolved salt.', '{"why":"Removing the unreacted carbonate helps produce a cleaner salt solution for crystallisation.","sol":"Step 1: Explain that some carbonate remains unreacted.\nStep 2: Identify it as an insoluble solid.\nStep 3: Explain that filtration removes this solid from the salt solution.","steps":["Step 1: Explain that some carbonate remains unreacted.","Step 2: Identify it as an insoluble solid.","Step 3: Explain that filtration removes this solid from the salt solution."],"options":[],"conceptId":"chemistry_acids_bases_salts_preparing_soluble_salts_from_acids_and_carbonates","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q5","subject":"chemistry","chapter":"acids_bases_salts","topic":"Preparing Soluble Salts from Acids and Carbonates"}', 4),
  (3659, 843, 'Define titration and state what it is used to determine in an acid-base experiment.', 'text', 1, 'Think about measured volumes and the point at which the reaction reaches its endpoint.', '{"why":"Titration provides a measured volume that can be used to analyse the reaction between the solutions.","sol":"Step 1: Explain that titration involves reacting measured solutions.\nStep 2: State that the volume delivered from one solution is measured.\nStep 3: Explain that the result helps determine the volume required for the reaction.","steps":["Step 1: Explain that titration involves reacting measured solutions.","Step 2: State that the volume delivered from one solution is measured.","Step 3: Explain that the result helps determine the volume required for the reaction."],"options":[],"conceptId":"chemistry_acids_bases_salts_titration","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Titration"}', 0),
  (3660, 843, 'A burette reading is initially 0.85 cm³ and finally 23.40 cm³. Calculate the titre and show your working.', 'text', 1, 'Subtract the initial reading from the final reading.', '{"why":"The titre is the volume delivered, not simply the final burette reading.","sol":"Step 1: Write titre = final reading − initial reading.\nStep 2: Substitute: 23.40 − 0.85.\nStep 3: Calculate the difference.","steps":["Step 1: Write titre = final reading − initial reading.","Step 2: Substitute: 23.40 − 0.85.","Step 3: Calculate the difference."],"options":[],"conceptId":"chemistry_acids_bases_salts_titration","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Titration"}', 1),
  (3661, 843, 'A titration uses 25.00 cm³ of solution measured by pipette. State the function of the pipette and explain why it is used.', 'text', 1, 'Distinguish the pipette from the burette.', '{"why":"Using a fixed measured volume makes the titration procedure consistent.","sol":"Step 1: Identify the pipette as the apparatus used to measure a fixed volume.\nStep 2: Explain that it transfers the measured volume into the flask.","steps":["Step 1: Identify the pipette as the apparatus used to measure a fixed volume.","Step 2: Explain that it transfers the measured volume into the flask."],"options":[],"conceptId":"chemistry_acids_bases_salts_titration","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Titration"}', 2),
  (3662, 843, 'Two closely agreeing titres are 21.60 cm³ and 21.80 cm³. Calculate their mean titre.', 'text', 1, 'Add both values and divide by two.', '{"why":"The mean of two values is their sum divided by two.","sol":"Step 1: Add: 21.60 + 21.80 = 43.40 cm³.\nStep 2: Divide by 2: 43.40 ÷ 2 = 21.70 cm³.","steps":["Step 1: Add: 21.60 + 21.80 = 43.40 cm³.","Step 2: Divide by 2: 43.40 ÷ 2 = 21.70 cm³."],"options":[],"conceptId":"chemistry_acids_bases_salts_titration","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Titration"}', 3),
  (3663, 843, 'Explain the difference between the endpoint and the equivalence point in an acid-base titration.', 'text', 1, 'One is identified by the indicator; the other concerns the reacting amounts.', '{"why":"The colour change is an experimental signal, while the equivalence point is defined by the chemical amounts reacting.","sol":"Step 1: Define the endpoint in terms of the observed indicator colour change.\nStep 2: Define the equivalence point in terms of the stoichiometric proportions in the balanced reaction.\nStep 3: Explain why they are related but not necessarily identical.","steps":["Step 1: Define the endpoint in terms of the observed indicator colour change.","Step 2: Define the equivalence point in terms of the stoichiometric proportions in the balanced reaction.","Step 3: Explain why they are related but not necessarily identical."],"options":[],"conceptId":"chemistry_acids_bases_salts_titration","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q5","subject":"chemistry","chapter":"acids_bases_salts","topic":"Titration"}', 4),
  (3664, 844, 'Define an exothermic reaction and describe the direction of energy transfer.', 'text', 1, 'Identify the reacting system and the surroundings.', '{"why":"The defining feature is the net transfer of energy out of the reacting system.","sol":"Step 1: Recall that the reacting chemicals form the system.\nStep 2: Recall that the surroundings are outside the reacting system.\nStep 3: State the direction in which energy is transferred.","steps":["Step 1: Recall that the reacting chemicals form the system.","Step 2: Recall that the surroundings are outside the reacting system.","Step 3: State the direction in which energy is transferred."],"options":[],"conceptId":"chemistry_energy_rate_reaction_exothermic_reactions","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q1","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Exothermic Reactions"}', 0),
  (3665, 844, 'A reaction mixture rises in temperature from 24°C to 31°C. Calculate the temperature change and explain what the observation suggests.', 'text', 1, 'Subtract the initial temperature from the final temperature.', '{"why":"A rise in temperature is evidence that the surroundings gained energy. Experimental heat exchange must still be considered.","sol":"Step 1: Write: Temperature change = Final temperature − Initial temperature.\nStep 2: Substitute: 31°C − 24°C.\nStep 3: Calculate the difference and interpret the rise.","steps":["Step 1: Write: Temperature change = Final temperature − Initial temperature.","Step 2: Substitute: 31°C − 24°C.","Step 3: Calculate the difference and interpret the rise."],"options":[],"conceptId":"chemistry_energy_rate_reaction_exothermic_reactions","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q2","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Exothermic Reactions"}', 1),
  (3666, 844, 'The reactants have an energy of 420 kJ and the products have an energy of 305 kJ. Calculate the energy change and classify the reaction.', 'text', 1, 'Use energy change = products'' energy − reactants'' energy.', '{"why":"The products have 115 kJ less energy than the reactants, so the difference is released to the surroundings.","sol":"Step 1: Write: Energy change = Energy of products − Energy of reactants.\nStep 2: Substitute: 305 kJ − 420 kJ.\nStep 3: Calculate the signed difference.\nStep 4: Use the sign to classify the reaction.","steps":["Step 1: Write: Energy change = Energy of products − Energy of reactants.","Step 2: Substitute: 305 kJ − 420 kJ.","Step 3: Calculate the signed difference.","Step 4: Use the sign to classify the reaction."],"options":[],"conceptId":"chemistry_energy_rate_reaction_exothermic_reactions","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q3","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Exothermic Reactions"}', 2),
  (3667, 844, 'Explain why an exothermic reaction can require energy to begin even though it releases energy overall.', 'text', 1, 'Distinguish the energy needed to break bonds from the energy released when new bonds form.', '{"why":"The initial energy requirement and the overall energy change describe different parts of the reaction.","sol":"Step 1: State what happens when bonds in the reactants are broken.\nStep 2: State what happens when bonds in the products form.\nStep 3: Compare the two energy amounts.","steps":["Step 1: State what happens when bonds in the reactants are broken.","Step 2: State what happens when bonds in the products form.","Step 3: Compare the two energy amounts."],"options":[],"conceptId":"chemistry_energy_rate_reaction_exothermic_reactions","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q4","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Exothermic Reactions"}', 3),
  (3668, 844, 'A learner says, ''The products of an exothermic reaction contain more energy than the reactants.'' Explain the error.', 'text', 1, 'Compare the energy levels of reactants and products.', '{"why":"If the products had more energy than the reactants, energy would have been absorbed overall rather than released.","sol":"Step 1: Recall that energy is transferred to the surroundings in an exothermic reaction.\nStep 2: Determine whether the products must have more or less energy than the reactants.\nStep 3: Correct the learner''s statement.","steps":["Step 1: Recall that energy is transferred to the surroundings in an exothermic reaction.","Step 2: Determine whether the products must have more or less energy than the reactants.","Step 3: Correct the learner''s statement."],"options":[],"conceptId":"chemistry_energy_rate_reaction_exothermic_reactions","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q5","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Exothermic Reactions"}', 4),
  (3669, 844, 'Describe how you could use a thermometer to investigate whether a reaction in solution is exothermic.', 'text', 1, 'Think about what must be measured before and after mixing.', '{"why":"A thermometer provides evidence of temperature change, which can indicate energy transfer to the surroundings.","sol":"Step 1: Measure and record the initial temperature of the reactants or solutions.\nStep 2: Mix the reactants safely in a suitable container.\nStep 3: Measure the temperature during and after the reaction.\nStep 4: Compare the highest relevant final temperature with the initial temperature.","steps":["Step 1: Measure and record the initial temperature of the reactants or solutions.","Step 2: Mix the reactants safely in a suitable container.","Step 3: Measure the temperature during and after the reaction.","Step 4: Compare the highest relevant final temperature with the initial temperature."],"options":[],"conceptId":"chemistry_energy_rate_reaction_exothermic_reactions","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q6","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Exothermic Reactions"}', 5),
  (3670, 845, 'Define an endothermic reaction and state the direction of energy transfer.', 'text', 1, 'Focus on whether the system gains or loses energy.', '{"why":"Absorption of energy by the reacting system is the defining feature of an endothermic reaction.","sol":"Step 1: Identify the reacting chemicals as the system.\nStep 2: Identify everything outside the system as the surroundings.\nStep 3: State the direction of energy transfer.","steps":["Step 1: Identify the reacting chemicals as the system.","Step 2: Identify everything outside the system as the surroundings.","Step 3: State the direction of energy transfer."],"options":[],"conceptId":"chemistry_energy_rate_reaction_endothermic_reactions","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q1","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Endothermic Reactions"}', 0),
  (3671, 845, 'During a reaction, the temperature falls from 30°C to 21°C. Calculate the temperature change and explain what it suggests.', 'text', 1, 'Subtract the initial temperature from the final temperature.', '{"why":"The surroundings may lose heat to the reacting system, causing the measured temperature to fall.","sol":"Step 1: Write: Temperature change = Final temperature − Initial temperature.\nStep 2: Substitute: 21°C − 30°C.\nStep 3: Calculate the result.\nStep 4: Explain what the negative temperature change suggests.","steps":["Step 1: Write: Temperature change = Final temperature − Initial temperature.","Step 2: Substitute: 21°C − 30°C.","Step 3: Calculate the result.","Step 4: Explain what the negative temperature change suggests."],"options":[],"conceptId":"chemistry_energy_rate_reaction_endothermic_reactions","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q2","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Endothermic Reactions"}', 1),
  (3672, 845, 'The reactants have an energy of 360 kJ and the products have an energy of 415 kJ. Calculate the energy change and classify the reaction.', 'text', 1, 'Subtract the reactants'' energy from the products'' energy.', '{"why":"The products have 55 kJ more energy than the reactants, so energy has been absorbed overall.","sol":"Step 1: Write: Energy change = Energy of products − Energy of reactants.\nStep 2: Substitute: 415 kJ − 360 kJ.\nStep 3: Calculate the difference.\nStep 4: Use the sign to classify the reaction.","steps":["Step 1: Write: Energy change = Energy of products − Energy of reactants.","Step 2: Substitute: 415 kJ − 360 kJ.","Step 3: Calculate the difference.","Step 4: Use the sign to classify the reaction."],"options":[],"conceptId":"chemistry_energy_rate_reaction_endothermic_reactions","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q3","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Endothermic Reactions"}', 2),
  (3673, 845, 'Explain why an endothermic reaction can release some energy during the formation of product bonds and still absorb energy overall.', 'text', 1, 'Compare the energy required for bond breaking with the energy released during bond formation.', '{"why":"The classification depends on the net energy change, not on whether any energy is released at an individual stage.","sol":"Step 1: State that breaking bonds requires energy.\nStep 2: State that forming bonds releases energy.\nStep 3: Compare the amounts for an endothermic reaction.","steps":["Step 1: State that breaking bonds requires energy.","Step 2: State that forming bonds releases energy.","Step 3: Compare the amounts for an endothermic reaction."],"options":[],"conceptId":"chemistry_energy_rate_reaction_endothermic_reactions","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q4","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Endothermic Reactions"}', 3),
  (3674, 845, 'Calcium carbonate decomposes when heated to form calcium oxide and carbon dioxide. Write the balanced equation and explain why heat must be supplied.', 'text', 1, 'Use CaCO₃, CaO and CO₂, then compare the atoms on each side.', '{"why":"The equation is balanced, and the supplied heat provides energy for the decomposition to occur.","sol":"Step 1: Write the reactant: CaCO₃.\nStep 2: Write the products: CaO + CO₂.\nStep 3: Check calcium: one atom on each side.\nStep 4: Check carbon: one atom on each side.\nStep 5: Check oxygen: three atoms on each side.\nStep 6: Explain that the decomposition absorbs energy under the stated conditions.","steps":["Step 1: Write the reactant: CaCO₃.","Step 2: Write the products: CaO + CO₂.","Step 3: Check calcium: one atom on each side.","Step 4: Check carbon: one atom on each side.","Step 5: Check oxygen: three atoms on each side.","Step 6: Explain that the decomposition absorbs energy under the stated conditions."],"options":[],"conceptId":"chemistry_energy_rate_reaction_endothermic_reactions","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q5","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Endothermic Reactions"}', 4),
  (3675, 845, 'A learner claims that every reaction that feels cold must be endothermic. Explain why this conclusion needs evidence.', 'text', 1, 'Consider other possible causes of a temperature decrease.', '{"why":"A reliable classification requires evidence that the reacting system absorbed energy rather than merely observing a temperature decrease.","sol":"Step 1: Recognise that cooling can indicate energy absorption.\nStep 2: Consider whether heat could have been lost to the environment or another process could have caused the temperature change.\nStep 3: Explain what measurements would strengthen the conclusion.","steps":["Step 1: Recognise that cooling can indicate energy absorption.","Step 2: Consider whether heat could have been lost to the environment or another process could have caused the temperature change.","Step 3: Explain what measurements would strengthen the conclusion."],"options":[],"conceptId":"chemistry_energy_rate_reaction_endothermic_reactions","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q6","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Endothermic Reactions"}', 5),
  (3676, 846, 'Describe what the horizontal and vertical axes represent in an energy profile diagram.', 'text', 1, 'One axis shows how far the reaction has progressed; the other shows energy.', '{"why":"The diagram compares energy levels along a reaction pathway rather than showing how energy changes with time.","sol":"Step 1: Identify the horizontal axis.\nStep 2: Identify the vertical axis.\nStep 3: Explain why the horizontal axis is not normally time.","steps":["Step 1: Identify the horizontal axis.","Step 2: Identify the vertical axis.","Step 3: Explain why the horizontal axis is not normally time."],"options":[],"conceptId":"chemistry_energy_rate_reaction_energy_profile_diagrams","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q1","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Energy Profile Diagrams"}', 0),
  (3677, 846, 'An energy profile begins at 340 kJ and ends at 215 kJ. Calculate the overall energy change and classify the reaction.', 'text', 1, 'Use products'' energy minus reactants'' energy.', '{"why":"The products are 125 kJ lower in energy than the reactants, so energy is released overall.","sol":"Step 1: Identify reactants'' energy: 340 kJ.\nStep 2: Identify products'' energy: 215 kJ.\nStep 3: Calculate 215 kJ − 340 kJ.\nStep 4: Interpret the sign.","steps":["Step 1: Identify reactants'' energy: 340 kJ.","Step 2: Identify products'' energy: 215 kJ.","Step 3: Calculate 215 kJ − 340 kJ.","Step 4: Interpret the sign."],"options":[],"conceptId":"chemistry_energy_rate_reaction_energy_profile_diagrams","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q2","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Energy Profile Diagrams"}', 1),
  (3678, 846, 'An energy profile begins at 160 kJ and ends at 235 kJ. Calculate the overall energy change and classify the reaction.', 'text', 1, 'Subtract the starting energy level from the ending energy level.', '{"why":"The products have 75 kJ more energy than the reactants, meaning energy is absorbed overall.","sol":"Step 1: Identify reactants'' energy: 160 kJ.\nStep 2: Identify products'' energy: 235 kJ.\nStep 3: Calculate 235 kJ − 160 kJ.\nStep 4: Use the sign to classify the reaction.","steps":["Step 1: Identify reactants'' energy: 160 kJ.","Step 2: Identify products'' energy: 235 kJ.","Step 3: Calculate 235 kJ − 160 kJ.","Step 4: Use the sign to classify the reaction."],"options":[],"conceptId":"chemistry_energy_rate_reaction_energy_profile_diagrams","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q3","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Energy Profile Diagrams"}', 2),
  (3679, 846, 'The reactants are at 115 kJ and the peak is at 290 kJ. Calculate the activation energy for the forward reaction and explain your calculation.', 'text', 1, 'Activation energy is the vertical energy difference between the reactants and the peak.', '{"why":"The reactants must gain the energy difference between their starting level and the peak to reach the high-energy state on the reaction pathway.","sol":"Step 1: Identify the peak energy: 290 kJ.\nStep 2: Identify the reactants'' energy: 115 kJ.\nStep 3: Subtract: 290 kJ − 115 kJ.\nStep 4: State the activation energy.","steps":["Step 1: Identify the peak energy: 290 kJ.","Step 2: Identify the reactants'' energy: 115 kJ.","Step 3: Subtract: 290 kJ − 115 kJ.","Step 4: State the activation energy."],"options":[],"conceptId":"chemistry_energy_rate_reaction_energy_profile_diagrams","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q4","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Energy Profile Diagrams"}', 3),
  (3680, 846, 'Explain how you can distinguish an exothermic reaction from an endothermic reaction by looking at an energy profile diagram.', 'text', 1, 'Compare the final energy level with the starting energy level.', '{"why":"The relative energy levels show whether the reacting system has lost or gained energy overall.","sol":"Step 1: Locate the reactants'' starting energy level.\nStep 2: Locate the products'' ending energy level.\nStep 3: Compare the two levels.\nStep 4: State the classification for each possible arrangement.","steps":["Step 1: Locate the reactants'' starting energy level.","Step 2: Locate the products'' ending energy level.","Step 3: Compare the two levels.","Step 4: State the classification for each possible arrangement."],"options":[],"conceptId":"chemistry_energy_rate_reaction_energy_profile_diagrams","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q5","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Energy Profile Diagrams"}', 4),
  (3681, 846, 'A learner measures activation energy from the reactants to the products instead of from the reactants to the peak. Explain the mistake and state how activation energy should be measured.', 'text', 1, 'Activation energy describes the barrier that must be overcome along the reaction pathway.', '{"why":"The peak represents the energy barrier, while the difference between reactants and products shows the net energy change.","sol":"Step 1: Identify the highest point of the energy profile.\nStep 2: Locate the reactants'' energy level.\nStep 3: Measure the energy difference between the reactants and the peak.\nStep 4: Distinguish this from the energy difference between reactants and products.","steps":["Step 1: Identify the highest point of the energy profile.","Step 2: Locate the reactants'' energy level.","Step 3: Measure the energy difference between the reactants and the peak.","Step 4: Distinguish this from the energy difference between reactants and products."],"options":[],"conceptId":"chemistry_energy_rate_reaction_energy_profile_diagrams","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q6","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Energy Profile Diagrams"}', 5),
  (3682, 847, 'Define activation energy in the context of a chemical reaction.', 'text', 1, 'Describe the minimum energy needed for reacting particles to react successfully.', '{"why":"The definition describes the energy barrier that must be overcome, not the overall energy change of the reaction.","sol":"Step 1: Recall that particles must overcome an energy barrier.\nStep 2: Identify the energy requirement for a successful reaction.\nStep 3: State the definition.","steps":["Step 1: Recall that particles must overcome an energy barrier.","Step 2: Identify the energy requirement for a successful reaction.","Step 3: State the definition."],"options":[],"conceptId":"chemistry_energy_rate_reaction_activation_energy","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q1","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Activation Energy"}', 0),
  (3683, 847, 'The reactants are at 80 kJ and the peak of the energy profile is at 225 kJ. Calculate the activation energy for the forward reaction.', 'text', 1, 'Subtract the reactants'' energy from the peak energy.', '{"why":"The 145 kJ difference is the energy barrier between the reactants'' level and the peak.","sol":"Step 1: Write: Activation energy = Peak energy − Reactants'' energy.\nStep 2: Substitute: 225 kJ − 80 kJ.\nStep 3: Calculate the difference.","steps":["Step 1: Write: Activation energy = Peak energy − Reactants'' energy.","Step 2: Substitute: 225 kJ − 80 kJ.","Step 3: Calculate the difference."],"options":[],"conceptId":"chemistry_energy_rate_reaction_activation_energy","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q2","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Activation Energy"}', 1),
  (3684, 847, 'Explain why a reaction that releases energy overall may still need energy before it begins.', 'text', 1, 'Separate the initial energy barrier from the final energy difference.', '{"why":"Activation energy describes the barrier at the beginning of the pathway, while the overall energy change compares reactants with products.","sol":"Step 1: Recognise that a reaction may have an activation-energy barrier.\nStep 2: Explain what the reacting particles must overcome.\nStep 3: Explain how the overall energy change can still be negative.","steps":["Step 1: Recognise that a reaction may have an activation-energy barrier.","Step 2: Explain what the reacting particles must overcome.","Step 3: Explain how the overall energy change can still be negative."],"options":[],"conceptId":"chemistry_energy_rate_reaction_activation_energy","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q3","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Activation Energy"}', 2),
  (3685, 847, 'Pathway A has an activation energy of 120 kJ and pathway B has an activation energy of 75 kJ. Calculate the difference and identify the pathway with the lower barrier.', 'text', 1, 'Subtract the smaller activation energy from the larger one.', '{"why":"Pathway B requires a smaller energy barrier to be overcome. For comparable pathways of the same reaction, this can support a faster reaction.","sol":"Step 1: Record pathway A: 120 kJ.\nStep 2: Record pathway B: 75 kJ.\nStep 3: Calculate 120 kJ − 75 kJ.\nStep 4: Identify the pathway with the smaller activation energy.","steps":["Step 1: Record pathway A: 120 kJ.","Step 2: Record pathway B: 75 kJ.","Step 3: Calculate 120 kJ − 75 kJ.","Step 4: Identify the pathway with the smaller activation energy."],"options":[],"conceptId":"chemistry_energy_rate_reaction_activation_energy","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q4","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Activation Energy"}', 3),
  (3686, 847, 'Explain how a catalyst affects activation energy and why this can increase the rate of a reaction.', 'text', 1, 'Think about the alternative pathway and the number of particles able to overcome the barrier.', '{"why":"The catalyst makes successful reactions more likely by reducing the energy barrier; it does not need to change the overall energy difference between reactants and products.","sol":"Step 1: State what kind of pathway a catalyst provides.\nStep 2: Compare the activation energy of the catalysed pathway with the uncatalysed pathway.\nStep 3: Explain how the lower barrier affects successful reactions.","steps":["Step 1: State what kind of pathway a catalyst provides.","Step 2: Compare the activation energy of the catalysed pathway with the uncatalysed pathway.","Step 3: Explain how the lower barrier affects successful reactions."],"options":[],"conceptId":"chemistry_energy_rate_reaction_activation_energy","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q5","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Activation Energy"}', 4),
  (3687, 847, 'A reaction has reactants at 180 kJ, a peak at 265 kJ, and products at 130 kJ. Calculate the activation energy and overall energy change, then classify the reaction.', 'text', 1, 'Use two separate calculations: peak minus reactants, then products minus reactants.', '{"why":"Activation energy measures the rise from the reactants to the peak. The negative overall change means the products have 50 kJ less energy than the reactants.","sol":"Step 1: Calculate activation energy: 265 kJ − 180 kJ.\nStep 2: Calculate overall energy change: 130 kJ − 180 kJ.\nStep 3: Interpret the activation energy as the barrier.\nStep 4: Interpret the sign of the overall energy change.","steps":["Step 1: Calculate activation energy: 265 kJ − 180 kJ.","Step 2: Calculate overall energy change: 130 kJ − 180 kJ.","Step 3: Interpret the activation energy as the barrier.","Step 4: Interpret the sign of the overall energy change."],"options":[],"conceptId":"chemistry_energy_rate_reaction_activation_energy","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q6","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Activation Energy"}', 5),
  (3688, 848, 'Define the rate of reaction and explain what is meant by a high rate.', 'text', 1, 'Think about the amount of reactant consumed or product formed in a given time.', '{"why":"Rate describes how quickly a reaction proceeds, rather than the total amount of product that can form.","sol":"Step 1: Identify a quantity that changes during a reaction.\nStep 2: Relate its change to elapsed time.\nStep 3: Explain what a high rate means.","steps":["Step 1: Identify a quantity that changes during a reaction.","Step 2: Relate its change to elapsed time.","Step 3: Explain what a high rate means."],"options":[],"conceptId":"chemistry_energy_rate_reaction_meaning_of_rate_of_reaction","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q1","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Meaning of Rate of Reaction"}', 0),
  (3689, 848, 'A reaction produces 126 cm³ of gas in 42 seconds. Calculate the average rate of gas production and give its unit.', 'text', 1, 'Divide the total gas volume by the time taken.', '{"why":"Dividing volume by time gives the average volume of gas produced each second.","sol":"Step 1: Write: Average rate = Volume produced ÷ Time.\nStep 2: Substitute: 126 cm³ ÷ 42 s.\nStep 3: Calculate and include the correct unit.","steps":["Step 1: Write: Average rate = Volume produced ÷ Time.","Step 2: Substitute: 126 cm³ ÷ 42 s.","Step 3: Calculate and include the correct unit."],"options":[],"conceptId":"chemistry_energy_rate_reaction_meaning_of_rate_of_reaction","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q2","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Meaning of Rate of Reaction"}', 1),
  (3690, 848, 'Reaction A loses 3.6 g of mass in 60 seconds. Reaction B loses 2.8 g in 35 seconds. Calculate both average rates of mass loss and identify the faster rate of mass loss.', 'text', 1, 'For each reaction, divide its mass loss by its own time.', '{"why":"Reaction B loses more mass per second on average, even though its total mass loss is smaller.","sol":"Step 1: Rate A = 3.6 g ÷ 60 s.\nStep 2: Rate B = 2.8 g ÷ 35 s.\nStep 3: Compare the answers in g/s.","steps":["Step 1: Rate A = 3.6 g ÷ 60 s.","Step 2: Rate B = 2.8 g ÷ 35 s.","Step 3: Compare the answers in g/s."],"options":[],"conceptId":"chemistry_energy_rate_reaction_meaning_of_rate_of_reaction","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q3","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Meaning of Rate of Reaction"}', 2),
  (3691, 848, 'Explain two methods for measuring the rate of a reaction that produces a gas, and state what is measured in each method.', 'text', 1, 'Consider collecting the gas and allowing it to escape from a vessel on a balance.', '{"why":"Both methods track a changing quantity over time, allowing an average rate to be calculated.","sol":"Step 1: Describe how a gas syringe can be used.\nStep 2: State what quantity is recorded with a gas syringe.\nStep 3: Describe how a balance can be used when gas escapes.\nStep 4: State what quantity is recorded with the balance.","steps":["Step 1: Describe how a gas syringe can be used.","Step 2: State what quantity is recorded with a gas syringe.","Step 3: Describe how a balance can be used when gas escapes.","Step 4: State what quantity is recorded with the balance."],"options":[],"conceptId":"chemistry_energy_rate_reaction_meaning_of_rate_of_reaction","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q4","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Meaning of Rate of Reaction"}', 3),
  (3692, 848, 'A learner calculates a reaction rate by dividing the final gas volume by the initial gas volume. Explain why this method is incorrect and give the correct method.', 'text', 1, 'Rate requires a change in quantity and a time interval.', '{"why":"A rate measures how much a quantity changes per unit time; a ratio of two volumes alone does not have the correct meaning or unit.","sol":"Step 1: Recall the definition of rate.\nStep 2: Identify what is missing from the learner''s calculation.\nStep 3: Write the correct formula for average gas-production rate.","steps":["Step 1: Recall the definition of rate.","Step 2: Identify what is missing from the learner''s calculation.","Step 3: Write the correct formula for average gas-production rate."],"options":[],"conceptId":"chemistry_energy_rate_reaction_meaning_of_rate_of_reaction","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q5","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Meaning of Rate of Reaction"}', 4),
  (3693, 848, 'A reaction produces 20 cm³ of gas in the first 5 seconds and a further 10 cm³ in the next 5 seconds. Calculate the average rate in each interval and explain what the results suggest.', 'text', 1, 'Calculate each interval separately using the gas produced during that interval.', '{"why":"The reaction may be slowing as reactants are consumed and effective collisions become less frequent.","sol":"Step 1: First interval rate = 20 cm³ ÷ 5 s.\nStep 2: Second interval rate = 10 cm³ ÷ 5 s.\nStep 3: Compare the two rates.\nStep 4: Explain what the difference may indicate.","steps":["Step 1: First interval rate = 20 cm³ ÷ 5 s.","Step 2: Second interval rate = 10 cm³ ÷ 5 s.","Step 3: Compare the two rates.","Step 4: Explain what the difference may indicate."],"options":[],"conceptId":"chemistry_energy_rate_reaction_meaning_of_rate_of_reaction","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q6","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Meaning of Rate of Reaction"}', 5),
  (3694, 849, 'Explain why increasing temperature generally increases the rate of a chemical reaction.', 'text', 1, 'Discuss kinetic energy, activation energy and successful collisions.', '{"why":"The increase in the proportion of sufficiently energetic collisions is a key reason temperature strongly affects reaction rate.","sol":"Step 1: Explain how particle kinetic energy changes with temperature.\nStep 2: Explain how particle movement and collisions are affected.\nStep 3: Explain how the proportion of particles able to overcome activation energy changes.\nStep 4: Connect these changes to reaction rate.","steps":["Step 1: Explain how particle kinetic energy changes with temperature.","Step 2: Explain how particle movement and collisions are affected.","Step 3: Explain how the proportion of particles able to overcome activation energy changes.","Step 4: Connect these changes to reaction rate."],"options":[],"conceptId":"chemistry_energy_rate_reaction_effect_of_temperature_on_rate","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q1","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Effect of Temperature on Rate"}', 0),
  (3695, 849, 'At 25°C, a reaction produces 36 cm³ of gas in 45 seconds. At 45°C, it produces 72 cm³ in the same time. Calculate both average rates and compare them.', 'text', 1, 'Divide each gas volume by 45 seconds, then compare the answers.', '{"why":"The reaction produced twice as much gas in the same time at 45°C, so its average gas-production rate was twice as high in these measurements.","sol":"Step 1: Rate at 25°C = 36 cm³ ÷ 45 s.\nStep 2: Rate at 45°C = 72 cm³ ÷ 45 s.\nStep 3: Compare the calculated rates and their ratio.","steps":["Step 1: Rate at 25°C = 36 cm³ ÷ 45 s.","Step 2: Rate at 45°C = 72 cm³ ÷ 45 s.","Step 3: Compare the calculated rates and their ratio."],"options":[],"conceptId":"chemistry_energy_rate_reaction_effect_of_temperature_on_rate","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q2","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Effect of Temperature on Rate"}', 1),
  (3696, 849, 'Describe a fair experiment to investigate how temperature affects the rate of magnesium reacting with dilute hydrochloric acid.', 'text', 1, 'Change temperature while keeping the other important conditions constant.', '{"why":"Changing only temperature allows differences in rate to be attributed more confidently to temperature.","sol":"Step 1: Choose and measure a fixed volume and concentration of acid.\nStep 2: Set the acid to a known starting temperature.\nStep 3: Add the same mass and form of magnesium.\nStep 4: Measure the hydrogen volume at regular intervals.\nStep 5: Repeat at another temperature while keeping the other variables constant.\nStep 6: Compare the rates.","steps":["Step 1: Choose and measure a fixed volume and concentration of acid.","Step 2: Set the acid to a known starting temperature.","Step 3: Add the same mass and form of magnesium.","Step 4: Measure the hydrogen volume at regular intervals.","Step 5: Repeat at another temperature while keeping the other variables constant.","Step 6: Compare the rates."],"options":[],"conceptId":"chemistry_energy_rate_reaction_effect_of_temperature_on_rate","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q3","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Effect of Temperature on Rate"}', 2),
  (3697, 849, 'Explain why a greater proportion of particles can react successfully at a higher temperature.', 'text', 1, 'Relate particle energy to the activation-energy threshold.', '{"why":"The reaction rate depends on the number of successful collisions per unit time, not merely on whether particles collide.","sol":"Step 1: Recall that particles have a range of kinetic energies.\nStep 2: Explain what happens to the energy distribution when temperature increases.\nStep 3: Compare the proportion of particles above the activation energy.\nStep 4: Connect the change to successful collisions.","steps":["Step 1: Recall that particles have a range of kinetic energies.","Step 2: Explain what happens to the energy distribution when temperature increases.","Step 3: Compare the proportion of particles above the activation energy.","Step 4: Connect the change to successful collisions."],"options":[],"conceptId":"chemistry_energy_rate_reaction_effect_of_temperature_on_rate","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q4","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Effect of Temperature on Rate"}', 3),
  (3698, 849, 'A learner heats the acid, increases its concentration and uses powdered magnesium instead of a ribbon. Explain why the learner cannot identify the effect of temperature alone.', 'text', 1, 'Identify each variable that can affect the rate.', '{"why":"A fair test controls other factors that could explain the observed change in rate.","sol":"Step 1: Identify the variable being investigated.\nStep 2: Identify the other two changed variables.\nStep 3: Explain how each extra change can affect the rate.\nStep 4: State how the experiment should be improved.","steps":["Step 1: Identify the variable being investigated.","Step 2: Identify the other two changed variables.","Step 3: Explain how each extra change can affect the rate.","Step 4: State how the experiment should be improved."],"options":[],"conceptId":"chemistry_energy_rate_reaction_effect_of_temperature_on_rate","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q5","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Effect of Temperature on Rate"}', 4),
  (3699, 849, 'A reaction takes 80 seconds at a lower temperature and 40 seconds at a higher temperature to reach the same endpoint. Calculate the ratio of their average rates and explain your reasoning.', 'text', 1, 'For the same amount of change, average rate is inversely proportional to the time taken.', '{"why":"When the same amount of change is measured, completing it in half the time corresponds to twice the average rate.","sol":"Step 1: Let the same amount of reaction change be represented by Q.\nStep 2: Write the lower-temperature rate as Q ÷ 80.\nStep 3: Write the higher-temperature rate as Q ÷ 40.\nStep 4: Divide the higher-temperature rate by the lower-temperature rate.","steps":["Step 1: Let the same amount of reaction change be represented by Q.","Step 2: Write the lower-temperature rate as Q ÷ 80.","Step 3: Write the higher-temperature rate as Q ÷ 40.","Step 4: Divide the higher-temperature rate by the lower-temperature rate."],"options":[],"conceptId":"chemistry_energy_rate_reaction_effect_of_temperature_on_rate","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q6","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Effect of Temperature on Rate"}', 5),
  (3700, 850, 'Define concentration and explain why a more concentrated solution generally reacts faster.', 'text', 1, 'Consider the amount of dissolved substance in a fixed volume.', '{"why":"More reactant particles in a given volume provide more opportunities for effective collisions.","sol":"Step 1: Define concentration as amount of solute per unit volume.\nStep 2: Compare the number of reactant particles in equal volumes of concentrated and dilute solutions.\nStep 3: Connect particle availability to collision frequency and reaction rate.","steps":["Step 1: Define concentration as amount of solute per unit volume.","Step 2: Compare the number of reactant particles in equal volumes of concentrated and dilute solutions.","Step 3: Connect particle availability to collision frequency and reaction rate."],"options":[],"conceptId":"chemistry_energy_rate_reaction_effect_of_concentration_on_rate","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q1","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Effect of Concentration on Rate"}', 0),
  (3701, 850, 'Calculate the final concentration when 40 cm³ of a 1.5 mol dm⁻³ solution is diluted with water to a total volume of 120 cm³.', 'text', 1, 'Use C₁V₁ = C₂V₂.', '{"why":"The amount of solute stays constant during dilution while the total volume increases, reducing the concentration.","sol":"Step 1: Write C₁V₁ = C₂V₂.\nStep 2: Substitute: 1.5 × 40 = C₂ × 120.\nStep 3: Rearrange: C₂ = (1.5 × 40) ÷ 120.\nStep 4: Calculate the final concentration.","steps":["Step 1: Write C₁V₁ = C₂V₂.","Step 2: Substitute: 1.5 × 40 = C₂ × 120.","Step 3: Rearrange: C₂ = (1.5 × 40) ÷ 120.","Step 4: Calculate the final concentration."],"options":[],"conceptId":"chemistry_energy_rate_reaction_effect_of_concentration_on_rate","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q2","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Effect of Concentration on Rate"}', 1),
  (3702, 850, 'A reaction produces 42 cm³ of gas in 30 seconds using dilute acid and 63 cm³ in 30 seconds using more concentrated acid. Calculate both average rates and their ratio.', 'text', 1, 'Calculate each volume divided by 30 seconds, then divide the larger rate by the smaller rate.', '{"why":"Under the measured conditions, the concentrated-acid reaction has 1.5 times the average gas-production rate.","sol":"Step 1: Dilute-acid rate = 42 cm³ ÷ 30 s.\nStep 2: Concentrated-acid rate = 63 cm³ ÷ 30 s.\nStep 3: Divide the concentrated-acid rate by the dilute-acid rate.","steps":["Step 1: Dilute-acid rate = 42 cm³ ÷ 30 s.","Step 2: Concentrated-acid rate = 63 cm³ ÷ 30 s.","Step 3: Divide the concentrated-acid rate by the dilute-acid rate."],"options":[],"conceptId":"chemistry_energy_rate_reaction_effect_of_concentration_on_rate","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q3","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Effect of Concentration on Rate"}', 2),
  (3703, 850, 'Describe a fair experiment for investigating the effect of acid concentration on the rate of magnesium reacting with hydrochloric acid.', 'text', 1, 'Change acid concentration only and measure a quantity that changes over time.', '{"why":"Keeping other rate-affecting variables constant allows the effect of acid concentration to be investigated.","sol":"Step 1: Prepare acid solutions of different known concentrations.\nStep 2: Use the same volume of each solution and maintain the same temperature.\nStep 3: Use the same mass and exposed surface area of magnesium.\nStep 4: Measure the volume of hydrogen at regular time intervals.\nStep 5: Compare the rates while controlling other relevant conditions.","steps":["Step 1: Prepare acid solutions of different known concentrations.","Step 2: Use the same volume of each solution and maintain the same temperature.","Step 3: Use the same mass and exposed surface area of magnesium.","Step 4: Measure the volume of hydrogen at regular time intervals.","Step 5: Compare the rates while controlling other relevant conditions."],"options":[],"conceptId":"chemistry_energy_rate_reaction_effect_of_concentration_on_rate","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q4","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Effect of Concentration on Rate"}', 3),
  (3704, 850, 'Explain why doubling the concentration of a reactant does not guarantee that the reaction rate will double.', 'text', 1, 'Distinguish a general collision explanation from an exact mathematical relationship.', '{"why":"Concentration commonly affects collision frequency, but different reactions have different quantitative relationships between concentration and rate.","sol":"Step 1: Explain how increasing concentration affects particle availability.\nStep 2: State the general effect on collision frequency.\nStep 3: Explain why the exact rate relationship depends on the reaction.","steps":["Step 1: Explain how increasing concentration affects particle availability.","Step 2: State the general effect on collision frequency.","Step 3: Explain why the exact rate relationship depends on the reaction."],"options":[],"conceptId":"chemistry_energy_rate_reaction_effect_of_concentration_on_rate","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q5","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Effect of Concentration on Rate"}', 4),
  (3705, 850, 'A learner dilutes 50 cm³ of a 3.0 mol dm⁻³ solution to a total volume of 150 cm³. Calculate the final concentration and explain what happens to the amount of solute.', 'text', 1, 'Use C₁V₁ = C₂V₂ and remember that water adds volume, not solute.', '{"why":"Dilution spreads the same amount of solute through a larger volume.","sol":"Step 1: Write C₁V₁ = C₂V₂.\nStep 2: Substitute: 3.0 × 50 = C₂ × 150.\nStep 3: Calculate C₂ = 150 ÷ 150.\nStep 4: State whether the amount of dissolved solute changes.","steps":["Step 1: Write C₁V₁ = C₂V₂.","Step 2: Substitute: 3.0 × 50 = C₂ × 150.","Step 3: Calculate C₂ = 150 ÷ 150.","Step 4: State whether the amount of dissolved solute changes."],"options":[],"conceptId":"chemistry_energy_rate_reaction_effect_of_concentration_on_rate","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q6","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Effect of Concentration on Rate"}', 5),
  (3706, 851, 'Explain why powdered calcium carbonate generally reacts faster with hydrochloric acid than an equal mass of large calcium carbonate chips.', 'text', 1, 'Compare the exposed surface areas and the number of opportunities for collisions.', '{"why":"The surface-area effect comes from increased contact between the solid reactant and the solution.","sol":"Step 1: Compare the particle sizes of powder and chips.\nStep 2: Explain how particle size affects total exposed surface area.\nStep 3: Connect exposed surface area to contact with acid.\nStep 4: Explain the effect on reaction rate.","steps":["Step 1: Compare the particle sizes of powder and chips.","Step 2: Explain how particle size affects total exposed surface area.","Step 3: Connect exposed surface area to contact with acid.","Step 4: Explain the effect on reaction rate."],"options":[],"conceptId":"chemistry_energy_rate_reaction_effect_of_surface_area_on_rate","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q1","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Effect of Surface Area on Rate"}', 0),
  (3707, 851, 'An equal mass of calcium carbonate chips produces 36 cm³ of carbon dioxide in 60 seconds. Powder produces 54 cm³ in the same time. Calculate both average rates and their ratio.', 'text', 1, 'Divide each gas volume by 60 seconds, then compare the rates.', '{"why":"Under the measured conditions, the powder produces carbon dioxide at 1.5 times the average rate of the chips.","sol":"Step 1: Chip rate = 36 cm³ ÷ 60 s.\nStep 2: Powder rate = 54 cm³ ÷ 60 s.\nStep 3: Divide the powder rate by the chip rate.","steps":["Step 1: Chip rate = 36 cm³ ÷ 60 s.","Step 2: Powder rate = 54 cm³ ÷ 60 s.","Step 3: Divide the powder rate by the chip rate."],"options":[],"conceptId":"chemistry_energy_rate_reaction_effect_of_surface_area_on_rate","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q2","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Effect of Surface Area on Rate"}', 1),
  (3708, 851, 'Describe a fair experiment to investigate how the surface area of calcium carbonate affects its reaction rate with hydrochloric acid.', 'text', 1, 'Use the same reactants and quantities but change the solid''s particle size.', '{"why":"Keeping the other important variables constant makes surface area the main difference between the experiments.","sol":"Step 1: Measure equal masses of calcium carbonate in different particle sizes.\nStep 2: Use equal volumes and the same concentration of hydrochloric acid.\nStep 3: Maintain the same starting temperature.\nStep 4: Measure carbon dioxide volume at regular intervals.\nStep 5: Compare the rates.","steps":["Step 1: Measure equal masses of calcium carbonate in different particle sizes.","Step 2: Use equal volumes and the same concentration of hydrochloric acid.","Step 3: Maintain the same starting temperature.","Step 4: Measure carbon dioxide volume at regular intervals.","Step 5: Compare the rates."],"options":[],"conceptId":"chemistry_energy_rate_reaction_effect_of_surface_area_on_rate","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q3","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Effect of Surface Area on Rate"}', 2),
  (3709, 851, 'A learner doubles the mass of calcium carbonate and changes it from chips to powder. Explain why an increase in reaction rate cannot be attributed to surface area alone.', 'text', 1, 'Consider both the amount of solid and its exposed surface area.', '{"why":"A fair test isolates the variable being investigated.","sol":"Step 1: Identify the change in particle size.\nStep 2: Identify the change in mass.\nStep 3: Explain how each can influence the observed reaction.\nStep 4: State how to make the test fair.","steps":["Step 1: Identify the change in particle size.","Step 2: Identify the change in mass.","Step 3: Explain how each can influence the observed reaction.","Step 4: State how to make the test fair."],"options":[],"conceptId":"chemistry_energy_rate_reaction_effect_of_surface_area_on_rate","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q4","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Effect of Surface Area on Rate"}', 3),
  (3710, 851, 'Calcium carbonate reacts with hydrochloric acid according to the equation CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂. Explain why powdering the same mass of calcium carbonate usually changes the rate but not the theoretical final amount of carbon dioxide when sufficient acid is available.', 'text', 1, 'Distinguish how quickly the solid reacts from the number of moles of solid present.', '{"why":"Surface area affects reaction speed, while the amount of reactant determines the theoretical yield.","sol":"Step 1: Identify what determines the rate at the solid surface.\nStep 2: State whether powdering changes the number of moles in the same mass of calcium carbonate.\nStep 3: Use the reaction equation to relate moles of calcium carbonate to moles of carbon dioxide.\nStep 4: State the effect on final theoretical yield.","steps":["Step 1: Identify what determines the rate at the solid surface.","Step 2: State whether powdering changes the number of moles in the same mass of calcium carbonate.","Step 3: Use the reaction equation to relate moles of calcium carbonate to moles of carbon dioxide.","Step 4: State the effect on final theoretical yield."],"options":[],"conceptId":"chemistry_energy_rate_reaction_effect_of_surface_area_on_rate","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q5","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Effect of Surface Area on Rate"}', 4),
  (3711, 851, 'A reaction produces 18 cm³ of gas in the first 15 seconds and 27 cm³ in the next 15 seconds when powdered solid is used. Calculate the average rate in each interval and explain why these results alone do not prove that surface area caused the rate change.', 'text', 1, 'Use the gas produced during each interval, not the cumulative volume at the end of the interval.', '{"why":"To establish the effect of surface area, different particle sizes must be compared under otherwise equivalent conditions.","sol":"Step 1: First interval rate = 18 cm³ ÷ 15 s.\nStep 2: Second interval rate = 27 cm³ ÷ 15 s.\nStep 3: Compare the interval rates.\nStep 4: Explain why changing rate over time does not by itself isolate the effect of surface area.","steps":["Step 1: First interval rate = 18 cm³ ÷ 15 s.","Step 2: Second interval rate = 27 cm³ ÷ 15 s.","Step 3: Compare the interval rates.","Step 4: Explain why changing rate over time does not by itself isolate the effect of surface area."],"options":[],"conceptId":"chemistry_energy_rate_reaction_effect_of_surface_area_on_rate","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q6","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Effect of Surface Area on Rate"}', 5),
  (3712, 852, 'Define a catalyst and explain how it increases the rate of a chemical reaction.', 'text', 1, 'Include what happens to the reaction pathway and activation energy.', '{"why":"The catalyst lowers the energy barrier for the reaction rather than changing the overall energy difference between reactants and products.","sol":"Step 1: Define a catalyst in terms of its effect on reaction rate.\nStep 2: Explain that it provides an alternative pathway.\nStep 3: State how the activation energy changes.\nStep 4: Connect the lower barrier to successful reactions per second.","steps":["Step 1: Define a catalyst in terms of its effect on reaction rate.","Step 2: Explain that it provides an alternative pathway.","Step 3: State how the activation energy changes.","Step 4: Connect the lower barrier to successful reactions per second."],"options":[],"conceptId":"chemistry_energy_rate_reaction_catalysts","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q1","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Catalysts"}', 0),
  (3713, 852, 'An uncatalysed reaction has an activation energy of 175 kJ. With a catalyst, the activation energy is 105 kJ. Calculate the reduction in activation energy.', 'text', 1, 'Subtract the catalysed activation energy from the uncatalysed value.', '{"why":"The catalysed pathway requires 70 kJ less activation energy on the stated energy scale.","sol":"Step 1: Write: Reduction = Uncatalysed activation energy − Catalysed activation energy.\nStep 2: Substitute: 175 kJ − 105 kJ.\nStep 3: Calculate the difference.","steps":["Step 1: Write: Reduction = Uncatalysed activation energy − Catalysed activation energy.","Step 2: Substitute: 175 kJ − 105 kJ.","Step 3: Calculate the difference."],"options":[],"conceptId":"chemistry_energy_rate_reaction_catalysts","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q2","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Catalysts"}', 1),
  (3714, 852, 'Hydrogen peroxide decomposes according to the equation 2H₂O₂ → 2H₂O + O₂. Explain how manganese(IV) oxide can affect this reaction and state whether it changes the overall chemical equation.', 'text', 1, 'Think about catalytic action and the meaning of an overall balanced equation.', '{"why":"A catalyst changes the pathway and rate of the reaction, not the overall chemical transformation.","sol":"Step 1: Identify the role of manganese(IV) oxide.\nStep 2: Explain how it affects activation energy and reaction rate.\nStep 3: State whether it changes the reactants and products in the overall equation.","steps":["Step 1: Identify the role of manganese(IV) oxide.","Step 2: Explain how it affects activation energy and reaction rate.","Step 3: State whether it changes the reactants and products in the overall equation."],"options":[],"conceptId":"chemistry_energy_rate_reaction_catalysts","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q3","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Catalysts"}', 2),
  (3715, 852, 'The reactants have an energy of 240 kJ and the products have an energy of 165 kJ. A catalyst lowers the activation energy but does not change either energy level. Calculate the overall energy change and explain why it remains unchanged.', 'text', 1, 'Calculate products'' energy minus reactants'' energy.', '{"why":"The overall energy change depends on the difference between the reactants and products, whereas activation energy depends on the pathway''s energy barrier.","sol":"Step 1: Write: Energy change = Energy of products − Energy of reactants.\nStep 2: Substitute: 165 kJ − 240 kJ.\nStep 3: Calculate and classify the reaction.\nStep 4: Explain why changing the pathway does not change the endpoint energy difference.","steps":["Step 1: Write: Energy change = Energy of products − Energy of reactants.","Step 2: Substitute: 165 kJ − 240 kJ.","Step 3: Calculate and classify the reaction.","Step 4: Explain why changing the pathway does not change the endpoint energy difference."],"options":[],"conceptId":"chemistry_energy_rate_reaction_catalysts","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q4","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Catalysts"}', 3),
  (3716, 852, 'Describe a fair experiment to determine whether a catalyst increases the rate of decomposition of hydrogen peroxide.', 'text', 1, 'Compare the reaction with and without the catalyst while controlling the other conditions.', '{"why":"Keeping the other conditions the same allows the effect of the catalyst to be assessed.","sol":"Step 1: Use equal volumes and concentrations of hydrogen peroxide.\nStep 2: Maintain the same starting temperature.\nStep 3: Add a measured amount of catalyst to one experiment and none to the comparison experiment.\nStep 4: Measure oxygen volume at regular time intervals using suitable apparatus.\nStep 5: Compare the rates.","steps":["Step 1: Use equal volumes and concentrations of hydrogen peroxide.","Step 2: Maintain the same starting temperature.","Step 3: Add a measured amount of catalyst to one experiment and none to the comparison experiment.","Step 4: Measure oxygen volume at regular time intervals using suitable apparatus.","Step 5: Compare the rates."],"options":[],"conceptId":"chemistry_energy_rate_reaction_catalysts","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q5","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Catalysts"}', 4),
  (3717, 852, 'A learner claims that adding a catalyst to a reversible reaction increases the equilibrium amount of product because the reaction is faster. Explain why this claim is incorrect.', 'text', 1, 'Distinguish the time taken to reach equilibrium from the equilibrium position.', '{"why":"Reaction rate describes how quickly change occurs; equilibrium position describes the final balance between forward and reverse reactions.","sol":"Step 1: State how a catalyst affects the forward reaction.\nStep 2: State how it affects the reverse reaction.\nStep 3: Explain what happens to the time taken to reach equilibrium.\nStep 4: Distinguish this from the equilibrium composition.","steps":["Step 1: State how a catalyst affects the forward reaction.","Step 2: State how it affects the reverse reaction.","Step 3: Explain what happens to the time taken to reach equilibrium.","Step 4: Distinguish this from the equilibrium composition."],"options":[],"conceptId":"chemistry_energy_rate_reaction_catalysts","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q6","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Catalysts"}', 5),
  (3718, 853, 'Define specific heat capacity and state its SI unit.', 'text', 1, 'State the energy needed for a unit mass and a unit temperature increase.', '{"why":"The definition describes energy required per kilogram per degree of temperature change.","sol":"Step 1: Identify the mass used in the definition.\nStep 2: State the temperature increase.\nStep 3: State the SI unit.","steps":["Step 1: Identify the mass used in the definition.","Step 2: State the temperature increase.","Step 3: State the SI unit."],"options":[],"conceptId":"chemistry_energy_rate_reaction_specific_heat_capacity","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q1","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Specific Heat Capacity"}', 0),
  (3719, 853, 'Calculate the energy required to heat 3 kg of water through 8°C. Use c = 4,200 J kg⁻¹ °C⁻¹.', 'text', 1, 'Use Q = mcΔT.', '{"why":"The formula combines mass, specific heat capacity and temperature change to determine the thermal energy transferred.","sol":"Step 1: Write Q = mcΔT.\nStep 2: Substitute m = 3 kg, c = 4,200 and ΔT = 8°C.\nStep 3: Calculate 3 × 4,200 × 8.\nStep 4: Give the answer in joules.","steps":["Step 1: Write Q = mcΔT.","Step 2: Substitute m = 3 kg, c = 4,200 and ΔT = 8°C.","Step 3: Calculate 3 × 4,200 × 8.","Step 4: Give the answer in joules."],"options":[],"conceptId":"chemistry_energy_rate_reaction_specific_heat_capacity","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q2","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Specific Heat Capacity"}', 1),
  (3720, 853, 'A 0.8 kg metal object absorbs 4,800 J and warms from 20°C to 35°C. Calculate its specific heat capacity.', 'text', 1, 'Find the temperature change first, then rearrange Q = mcΔT.', '{"why":"Specific heat capacity is the energy transferred per kilogram per degree of temperature change.","sol":"Step 1: Calculate ΔT = 35°C − 20°C = 15°C.\nStep 2: Rearrange: c = Q ÷ (mΔT).\nStep 3: Substitute: c = 4,800 ÷ (0.8 × 15).\nStep 4: Calculate and state the unit.","steps":["Step 1: Calculate ΔT = 35°C − 20°C = 15°C.","Step 2: Rearrange: c = Q ÷ (mΔT).","Step 3: Substitute: c = 4,800 ÷ (0.8 × 15).","Step 4: Calculate and state the unit."],"options":[],"conceptId":"chemistry_energy_rate_reaction_specific_heat_capacity","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q3","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Specific Heat Capacity"}', 2),
  (3721, 853, 'A 2 kg block with c = 600 J kg⁻¹ °C⁻¹ is heated from 15°C to 40°C. Calculate the energy absorbed.', 'text', 1, 'Calculate the temperature difference before substituting into the formula.', '{"why":"The block''s mass, specific heat capacity and 25°C temperature rise determine the energy absorbed.","sol":"Step 1: Calculate ΔT = 40°C − 15°C = 25°C.\nStep 2: Write Q = mcΔT.\nStep 3: Substitute Q = 2 × 600 × 25.\nStep 4: Calculate the energy.","steps":["Step 1: Calculate ΔT = 40°C − 15°C = 25°C.","Step 2: Write Q = mcΔT.","Step 3: Substitute Q = 2 × 600 × 25.","Step 4: Calculate the energy."],"options":[],"conceptId":"chemistry_energy_rate_reaction_specific_heat_capacity","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q4","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Specific Heat Capacity"}', 3),
  (3722, 853, 'Explain why equal masses of two different substances may require different amounts of energy to rise by the same temperature.', 'text', 1, 'Compare their specific heat capacities.', '{"why":"Specific heat capacity describes how much energy is needed for each kilogram per degree of temperature change.","sol":"Step 1: Recall what specific heat capacity measures.\nStep 2: Compare substances with high and low specific heat capacities.\nStep 3: Use Q = mcΔT to explain the difference.","steps":["Step 1: Recall what specific heat capacity measures.","Step 2: Compare substances with high and low specific heat capacities.","Step 3: Use Q = mcΔT to explain the difference."],"options":[],"conceptId":"chemistry_energy_rate_reaction_specific_heat_capacity","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q5","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Specific Heat Capacity"}', 4),
  (3723, 853, 'A 1.5 kg substance with c = 800 J kg⁻¹ °C⁻¹ absorbs 24,000 J. Its initial temperature is 12°C. Calculate its temperature increase and final temperature, assuming no heat loss or change of state.', 'text', 1, 'Find ΔT = Q ÷ (mc), then add it to the initial temperature.', '{"why":"The energy transferred produces a 20°C rise under the stated assumptions.","sol":"Step 1: Write ΔT = Q ÷ (mc).\nStep 2: Substitute: ΔT = 24,000 ÷ (1.5 × 800).\nStep 3: Calculate the temperature increase.\nStep 4: Add the increase to 12°C.","steps":["Step 1: Write ΔT = Q ÷ (mc).","Step 2: Substitute: ΔT = 24,000 ÷ (1.5 × 800).","Step 3: Calculate the temperature increase.","Step 4: Add the increase to 12°C."],"options":[],"conceptId":"chemistry_energy_rate_reaction_specific_heat_capacity","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q6","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Specific Heat Capacity"}', 5),
  (3724, 854, 'State the formula used to calculate heat energy transferred when a substance changes temperature without changing state. Define each symbol.', 'text', 1, 'The formula combines mass, specific heat capacity and temperature change.', '{"why":"Each quantity determines the energy needed for a particular mass to undergo a specified temperature change.","sol":"Step 1: Write the formula.\nStep 2: Define Q and its unit.\nStep 3: Define m and its unit.\nStep 4: Define c and its unit.\nStep 5: Define ΔT.","steps":["Step 1: Write the formula.","Step 2: Define Q and its unit.","Step 3: Define m and its unit.","Step 4: Define c and its unit.","Step 5: Define ΔT."],"options":[],"conceptId":"chemistry_energy_rate_reaction_heat_energy_calculations","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q1","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Heat Energy Calculations"}', 0),
  (3725, 854, 'Calculate the energy required to heat 400 g of water from 15°C to 45°C. Use c = 4,200 J kg⁻¹ °C⁻¹.', 'text', 1, 'Convert 400 g to kilograms before using Q = mcΔT.', '{"why":"The formula requires mass in kilograms because the specific heat capacity is given per kilogram.","sol":"Step 1: Convert mass: 400 g = 0.400 kg.\nStep 2: Calculate ΔT = 45°C − 15°C = 30°C.\nStep 3: Substitute: Q = 0.400 × 4,200 × 30.\nStep 4: Calculate and state the answer in joules.","steps":["Step 1: Convert mass: 400 g = 0.400 kg.","Step 2: Calculate ΔT = 45°C − 15°C = 30°C.","Step 3: Substitute: Q = 0.400 × 4,200 × 30.","Step 4: Calculate and state the answer in joules."],"options":[],"conceptId":"chemistry_energy_rate_reaction_heat_energy_calculations","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q2","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Heat Energy Calculations"}', 1),
  (3726, 854, 'A 1.2 kg block with c = 750 J kg⁻¹ °C⁻¹ absorbs 18,000 J. Its initial temperature is 20°C. Calculate its final temperature, assuming no heat loss or change of state.', 'text', 1, 'Calculate ΔT = Q ÷ (mc), then add it to 20°C.', '{"why":"The absorbed energy produces a 20°C increase under the stated assumptions.","sol":"Step 1: Write ΔT = Q ÷ (mc).\nStep 2: Substitute: ΔT = 18,000 ÷ (1.2 × 750).\nStep 3: Calculate ΔT.\nStep 4: Add the temperature increase to 20°C.","steps":["Step 1: Write ΔT = Q ÷ (mc).","Step 2: Substitute: ΔT = 18,000 ÷ (1.2 × 750).","Step 3: Calculate ΔT.","Step 4: Add the temperature increase to 20°C."],"options":[],"conceptId":"chemistry_energy_rate_reaction_heat_energy_calculations","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q3","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Heat Energy Calculations"}', 2),
  (3727, 854, 'A metal block cools from 150°C to 50°C and releases 90,000 J. Its mass is 2 kg. Calculate its specific heat capacity.', 'text', 1, 'Find the temperature decrease and rearrange Q = mcΔT to make c the subject.', '{"why":"The energy released, mass and temperature decrease determine the specific heat capacity.","sol":"Step 1: Calculate the magnitude of the temperature change: 150°C − 50°C = 100°C.\nStep 2: Use c = Q ÷ (mΔT).\nStep 3: Substitute: c = 90,000 ÷ (2 × 100).\nStep 4: Calculate the specific heat capacity.","steps":["Step 1: Calculate the magnitude of the temperature change: 150°C − 50°C = 100°C.","Step 2: Use c = Q ÷ (mΔT).","Step 3: Substitute: c = 90,000 ÷ (2 × 100).","Step 4: Calculate the specific heat capacity."],"options":[],"conceptId":"chemistry_energy_rate_reaction_heat_energy_calculations","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q4","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Heat Energy Calculations"}', 3),
  (3728, 854, 'Explain why a calculation using Q = mcΔT may give a different value from the electrical energy supplied by a heater.', 'text', 1, 'Consider where the supplied energy goes besides the substance being heated.', '{"why":"Energy supplied to the entire apparatus is not necessarily equal to energy transferred into the measured substance.","sol":"Step 1: Identify what Q = mcΔT calculates for the substance.\nStep 2: Consider energy absorbed by the container.\nStep 3: Consider energy transferred to the surroundings.\nStep 4: Explain the difference between energy supplied and energy absorbed by the substance.","steps":["Step 1: Identify what Q = mcΔT calculates for the substance.","Step 2: Consider energy absorbed by the container.","Step 3: Consider energy transferred to the surroundings.","Step 4: Explain the difference between energy supplied and energy absorbed by the substance."],"options":[],"conceptId":"chemistry_energy_rate_reaction_heat_energy_calculations","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q5","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Heat Energy Calculations"}', 4),
  (3729, 854, 'A 0.75 kg substance with c = 400 J kg⁻¹ °C⁻¹ cools from 90°C to 30°C. Calculate the thermal energy released in joules and kilojoules.', 'text', 1, 'Use the magnitude of the temperature decrease in Q = mcΔT.', '{"why":"The magnitude gives the energy released as the substance cools through 60°C.","sol":"Step 1: Calculate the temperature decrease: 90°C − 30°C = 60°C.\nStep 2: Substitute: Q = 0.75 × 400 × 60.\nStep 3: Calculate the energy in joules.\nStep 4: Divide by 1,000 to convert joules to kilojoules.","steps":["Step 1: Calculate the temperature decrease: 90°C − 30°C = 60°C.","Step 2: Substitute: Q = 0.75 × 400 × 60.","Step 3: Calculate the energy in joules.","Step 4: Divide by 1,000 to convert joules to kilojoules."],"options":[],"conceptId":"chemistry_energy_rate_reaction_heat_energy_calculations","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q6","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Heat Energy Calculations"}', 5),
  (3730, 855, 'Define specific latent heat of fusion and state its SI unit.', 'text', 1, 'Include the mass, change of state and temperature condition.', '{"why":"It measures the energy needed per kilogram for melting, not the energy needed to raise the substance''s temperature.","sol":"Step 1: Identify the change from solid to liquid.\nStep 2: State the mass used in the definition.\nStep 3: Explain what happens to temperature during the change of state.\nStep 4: Give the SI unit.","steps":["Step 1: Identify the change from solid to liquid.","Step 2: State the mass used in the definition.","Step 3: Explain what happens to temperature during the change of state.","Step 4: Give the SI unit."],"options":[],"conceptId":"chemistry_energy_rate_reaction_latent_heat_of_fusion","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q1","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Latent Heat of Fusion"}', 0),
  (3731, 855, 'Calculate the energy needed to melt 0.75 kg of ice at its melting point. Use Lf = 334,000 J kg⁻¹.', 'text', 1, 'Use Q = mLf.', '{"why":"Multiplying the mass by the specific latent heat gives the energy needed for the phase change.","sol":"Step 1: Write Q = mLf.\nStep 2: Substitute Q = 0.75 × 334,000.\nStep 3: Calculate the energy in joules.\nStep 4: Convert to kilojoules if required.","steps":["Step 1: Write Q = mLf.","Step 2: Substitute Q = 0.75 × 334,000.","Step 3: Calculate the energy in joules.","Step 4: Convert to kilojoules if required."],"options":[],"conceptId":"chemistry_energy_rate_reaction_latent_heat_of_fusion","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q2","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Latent Heat of Fusion"}', 1),
  (3732, 855, 'A sample of ice absorbs 100,200 J while melting at its melting point. Calculate the mass melted using Lf = 334,000 J kg⁻¹.', 'text', 1, 'Rearrange Q = mLf to make m the subject.', '{"why":"Dividing the absorbed energy by the energy needed to melt one kilogram gives the mass melted.","sol":"Step 1: Write m = Q ÷ Lf.\nStep 2: Substitute: m = 100,200 ÷ 334,000.\nStep 3: Calculate the mass in kilograms.","steps":["Step 1: Write m = Q ÷ Lf.","Step 2: Substitute: m = 100,200 ÷ 334,000.","Step 3: Calculate the mass in kilograms."],"options":[],"conceptId":"chemistry_energy_rate_reaction_latent_heat_of_fusion","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q3","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Latent Heat of Fusion"}', 2),
  (3733, 855, 'A 0.4 kg solid absorbs 120,000 J as it melts completely at a constant temperature. Calculate its specific latent heat of fusion.', 'text', 1, 'Divide the energy transferred by the mass.', '{"why":"Specific latent heat of fusion is the energy transferred per kilogram during melting.","sol":"Step 1: Write Q = mLf.\nStep 2: Rearrange: Lf = Q ÷ m.\nStep 3: Substitute: Lf = 120,000 ÷ 0.4.\nStep 4: Calculate and state the unit.","steps":["Step 1: Write Q = mLf.","Step 2: Rearrange: Lf = Q ÷ m.","Step 3: Substitute: Lf = 120,000 ÷ 0.4.","Step 4: Calculate and state the unit."],"options":[],"conceptId":"chemistry_energy_rate_reaction_latent_heat_of_fusion","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q4","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Latent Heat of Fusion"}', 3),
  (3734, 855, 'Explain why the temperature of pure ice at its melting point remains constant while it melts, even though it absorbs energy.', 'text', 1, 'Distinguish energy used for a state change from energy used to raise temperature.', '{"why":"Temperature remains constant during the phase change because the energy is being used for melting rather than increasing the average kinetic energy of the particles.","sol":"Step 1: State that energy is absorbed during melting.\nStep 2: Explain what the energy does during the phase change.\nStep 3: Explain why temperature does not rise until melting is complete.","steps":["Step 1: State that energy is absorbed during melting.","Step 2: Explain what the energy does during the phase change.","Step 3: Explain why temperature does not rise until melting is complete."],"options":[],"conceptId":"chemistry_energy_rate_reaction_latent_heat_of_fusion","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q5","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Latent Heat of Fusion"}', 4),
  (3735, 855, 'A learner uses Q = mcΔT to calculate the energy required to melt 1 kg of ice at 0°C into water at 0°C. Explain why this method is unsuitable and state the correct calculation method.', 'text', 1, 'Check whether the temperature changes during the process.', '{"why":"Latent heat must be used when energy is transferred during a phase change at constant temperature.","sol":"Step 1: Calculate the temperature difference between the initial and final states.\nStep 2: Explain what Q = mcΔT represents.\nStep 3: Identify the change of state.\nStep 4: State the correct formula.","steps":["Step 1: Calculate the temperature difference between the initial and final states.","Step 2: Explain what Q = mcΔT represents.","Step 3: Identify the change of state.","Step 4: State the correct formula."],"options":[],"conceptId":"chemistry_energy_rate_reaction_latent_heat_of_fusion","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q6","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Latent Heat of Fusion"}', 5),
  (3736, 856, 'Define specific latent heat of vaporisation and state its SI unit.', 'text', 1, 'Describe the energy needed to change a unit mass from liquid to gas without a temperature change.', '{"why":"It measures the energy required per kilogram for vaporisation, rather than for a temperature increase.","sol":"Step 1: Identify the change from liquid to gas.\nStep 2: State the mass used in the definition.\nStep 3: State the temperature condition.\nStep 4: Give the SI unit.","steps":["Step 1: Identify the change from liquid to gas.","Step 2: State the mass used in the definition.","Step 3: State the temperature condition.","Step 4: Give the SI unit."],"options":[],"conceptId":"chemistry_energy_rate_reaction_latent_heat_of_vaporisation","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q1","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Latent Heat of Vaporisation"}', 0),
  (3737, 856, 'Calculate the energy required to vaporise 0.8 kg of water at its boiling point. Use Lv = 2,260,000 J kg⁻¹.', 'text', 1, 'Use Q = mLv.', '{"why":"The energy required for vaporisation is the mass multiplied by the specific latent heat.","sol":"Step 1: Write Q = mLv.\nStep 2: Substitute: Q = 0.8 × 2,260,000.\nStep 3: Calculate the energy in joules.\nStep 4: Convert to kilojoules if required.","steps":["Step 1: Write Q = mLv.","Step 2: Substitute: Q = 0.8 × 2,260,000.","Step 3: Calculate the energy in joules.","Step 4: Convert to kilojoules if required."],"options":[],"conceptId":"chemistry_energy_rate_reaction_latent_heat_of_vaporisation","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q2","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Latent Heat of Vaporisation"}', 1),
  (3738, 856, 'Water at its boiling point absorbs 565,000 J during vaporisation. Calculate the mass vaporised using Lv = 2,260,000 J kg⁻¹.', 'text', 1, 'Rearrange Q = mLv to find mass.', '{"why":"Dividing the energy absorbed by the energy needed to vaporise one kilogram gives the mass vaporised.","sol":"Step 1: Write m = Q ÷ Lv.\nStep 2: Substitute: m = 565,000 ÷ 2,260,000.\nStep 3: Calculate the mass in kilograms.","steps":["Step 1: Write m = Q ÷ Lv.","Step 2: Substitute: m = 565,000 ÷ 2,260,000.","Step 3: Calculate the mass in kilograms."],"options":[],"conceptId":"chemistry_energy_rate_reaction_latent_heat_of_vaporisation","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q3","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Latent Heat of Vaporisation"}', 2),
  (3739, 856, 'A 0.4 kg liquid absorbs 920,000 J as it changes completely into gas at its boiling point. Calculate its specific latent heat of vaporisation.', 'text', 1, 'Divide the energy by the mass.', '{"why":"Specific latent heat of vaporisation is the energy transferred per kilogram during the liquid-to-gas phase change.","sol":"Step 1: Write Q = mLv.\nStep 2: Rearrange: Lv = Q ÷ m.\nStep 3: Substitute: Lv = 920,000 ÷ 0.4.\nStep 4: Calculate and include the unit.","steps":["Step 1: Write Q = mLv.","Step 2: Rearrange: Lv = Q ÷ m.","Step 3: Substitute: Lv = 920,000 ÷ 0.4.","Step 4: Calculate and include the unit."],"options":[],"conceptId":"chemistry_energy_rate_reaction_latent_heat_of_vaporisation","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q4","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Latent Heat of Vaporisation"}', 3),
  (3740, 856, 'Explain why the temperature of boiling water remains constant while it changes into steam, even though heating continues.', 'text', 1, 'Explain the purpose of the supplied energy during the phase change.', '{"why":"The energy is being used for the change of state rather than increasing the average kinetic energy of the particles.","sol":"Step 1: State that energy continues to enter the water.\nStep 2: Explain what happens to the liquid particles during vaporisation.\nStep 3: Explain why the temperature remains constant during the phase change.\nStep 4: State what happens after all the liquid has vaporised.","steps":["Step 1: State that energy continues to enter the water.","Step 2: Explain what happens to the liquid particles during vaporisation.","Step 3: Explain why the temperature remains constant during the phase change.","Step 4: State what happens after all the liquid has vaporised."],"options":[],"conceptId":"chemistry_energy_rate_reaction_latent_heat_of_vaporisation","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q5","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Latent Heat of Vaporisation"}', 4),
  (3741, 856, 'A learner uses Q = mcΔT to calculate the energy required to turn 0.5 kg of water at 100°C into steam at 100°C. Explain why the formula is unsuitable and calculate the required energy using Lv = 2,260,000 J kg⁻¹.', 'text', 1, 'The initial and final temperatures are the same, but the state changes.', '{"why":"The energy is used for vaporisation at constant temperature, so the latent heat formula is required.","sol":"Step 1: Calculate the temperature difference.\nStep 2: Explain why Q = mcΔT does not represent the phase-change energy.\nStep 3: Use Q = mLv.\nStep 4: Substitute m = 0.5 kg and Lv = 2,260,000 J kg⁻¹.","steps":["Step 1: Calculate the temperature difference.","Step 2: Explain why Q = mcΔT does not represent the phase-change energy.","Step 3: Use Q = mLv.","Step 4: Substitute m = 0.5 kg and Lv = 2,260,000 J kg⁻¹."],"options":[],"conceptId":"chemistry_energy_rate_reaction_latent_heat_of_vaporisation","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q6","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Latent Heat of Vaporisation"}', 5),
  (3742, 857, 'Define an electrolyte and state the condition under which it conducts electricity.', 'text', 1, 'Include the particles responsible for carrying charge and when they must be mobile.', '{"why":"The movement of charged ions carries electrical charge through the electrolyte.","sol":"Step 1: Identify an electrolyte as a substance containing ions.\nStep 2: Explain that the ions must be able to move.\nStep 3: State the usual conducting conditions for an ionic electrolyte.","steps":["Step 1: Identify an electrolyte as a substance containing ions.","Step 2: Explain that the ions must be able to move.","Step 3: State the usual conducting conditions for an ionic electrolyte."],"options":[],"conceptId":"chemistry_electrochemistry_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q1","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolytes"}', 0),
  (3743, 857, 'Explain why solid sodium chloride does not conduct electricity effectively, although it contains charged ions.', 'text', 1, 'Distinguish the presence of ions from their ability to move.', '{"why":"Mobile charged particles are necessary for electrical conduction through an electrolyte.","sol":"Step 1: Solid sodium chloride contains Na⁺ and Cl⁻ ions.\nStep 2: The ions occupy fixed positions in a crystal lattice.\nStep 3: They cannot move freely through the solid.\nStep 4: They therefore cannot carry current through the solid.","steps":["Step 1: Solid sodium chloride contains Na⁺ and Cl⁻ ions.","Step 2: The ions occupy fixed positions in a crystal lattice.","Step 3: They cannot move freely through the solid.","Step 4: They therefore cannot carry current through the solid."],"options":[],"conceptId":"chemistry_electrochemistry_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q2","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolytes"}', 1),
  (3744, 857, 'A sample of sodium chloride is heated until it melts. Explain why its electrical conductivity changes.', 'text', 1, 'Consider what happens to the crystal lattice during melting.', '{"why":"Melting makes the ions mobile enough to transport charge through the substance.","sol":"Step 1: Before melting, the ions occupy fixed lattice positions.\nStep 2: Melting breaks down the fixed arrangement.\nStep 3: The ions become free to move.\nStep 4: The mobile ions carry electrical charge.","steps":["Step 1: Before melting, the ions occupy fixed lattice positions.","Step 2: Melting breaks down the fixed arrangement.","Step 3: The ions become free to move.","Step 4: The mobile ions carry electrical charge."],"options":[],"conceptId":"chemistry_electrochemistry_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q3","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolytes"}', 2),
  (3745, 857, 'Explain how sodium chloride solution conducts electricity.', 'text', 1, 'Describe what happens to the ions when sodium chloride dissolves.', '{"why":"In an electrolyte solution, ions carry current through the liquid.","sol":"Step 1: Sodium chloride separates into Na⁺ and Cl⁻ ions in water.\nStep 2: These ions can move through the solution.\nStep 3: The ions move in response to the electric field.\nStep 4: Their movement transports electrical charge.","steps":["Step 1: Sodium chloride separates into Na⁺ and Cl⁻ ions in water.","Step 2: These ions can move through the solution.","Step 3: The ions move in response to the electric field.","Step 4: Their movement transports electrical charge."],"options":[],"conceptId":"chemistry_electrochemistry_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q4","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolytes"}', 3),
  (3746, 857, 'A student claims that any substance containing ions must conduct electricity in every physical state. Explain the error.', 'text', 1, 'Use solid sodium chloride to test the claim.', '{"why":"Electrical conduction requires mobile charge carriers, not just charged particles that are fixed in place.","sol":"Step 1: Solid sodium chloride contains ions.\nStep 2: Those ions are fixed in the crystal lattice.\nStep 3: They cannot move freely through the solid.\nStep 4: Therefore, the presence of ions alone is insufficient.","steps":["Step 1: Solid sodium chloride contains ions.","Step 2: Those ions are fixed in the crystal lattice.","Step 3: They cannot move freely through the solid.","Step 4: Therefore, the presence of ions alone is insufficient."],"options":[],"conceptId":"chemistry_electrochemistry_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q5","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolytes"}', 4),
  (3747, 857, 'Two samples contain the same ionic compound. Sample X is solid and Sample Y is molten. Explain which sample conducts electricity effectively and give the reason.', 'text', 1, 'Compare the mobility of ions in the two samples.', '{"why":"The physical state determines whether the ions can move and carry electrical charge.","sol":"Step 1: Both samples contain the same types of ions.\nStep 2: The ions in the solid sample are fixed in a lattice.\nStep 3: The ions in the molten sample can move freely.\nStep 4: The molten sample therefore conducts electricity effectively.","steps":["Step 1: Both samples contain the same types of ions.","Step 2: The ions in the solid sample are fixed in a lattice.","Step 3: The ions in the molten sample can move freely.","Step 4: The molten sample therefore conducts electricity effectively."],"options":[],"conceptId":"chemistry_electrochemistry_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q6","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolytes"}', 5),
  (3748, 858, 'Define electrolysis.', 'text', 1, 'Mention chemical decomposition, an ionic substance and the passage of electric current.', '{"why":"Electrical energy drives the chemical change in the electrolyte.","sol":"Step 1: Identify the process as chemical decomposition.\nStep 2: State that the substance is ionic and molten or aqueous.\nStep 3: Explain that an electric current causes the decomposition.","steps":["Step 1: Identify the process as chemical decomposition.","Step 2: State that the substance is ionic and molten or aqueous.","Step 3: Explain that an electric current causes the decomposition."],"options":[],"conceptId":"chemistry_electrochemistry_meaning_of_electrolysis","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q1","subject":"chemistry","chapter":"electrochemistry","topic":"Meaning of Electrolysis"}', 0),
  (3749, 858, 'State two conditions needed for electrolysis to take place.', 'text', 1, 'Consider the state of the ionic substance and the source of energy.', '{"why":"Mobile ions carry current through the electrolyte, while the power supply drives the chemical decomposition.","sol":"Step 1: The electrolyte must have mobile ions.\nStep 2: The substance must be molten or in aqueous solution under ordinary electrolysis conditions.\nStep 3: An external power supply must provide electrical energy.","steps":["Step 1: The electrolyte must have mobile ions.","Step 2: The substance must be molten or in aqueous solution under ordinary electrolysis conditions.","Step 3: An external power supply must provide electrical energy."],"options":[],"conceptId":"chemistry_electrochemistry_meaning_of_electrolysis","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q2","subject":"chemistry","chapter":"electrochemistry","topic":"Meaning of Electrolysis"}', 1),
  (3750, 858, 'Write the balanced overall equation for the electrolysis of molten sodium chloride.', 'text', 1, 'Chlorine exists as diatomic molecules, Cl₂.', '{"why":"The balanced equation conserves two sodium atoms and two chlorine atoms on each side.","sol":"Step 1: Sodium chloride decomposes to sodium and chlorine.\nStep 2: Write NaCl → Na + Cl₂.\nStep 3: Balance chlorine by placing 2 before NaCl.\nStep 4: Balance sodium by placing 2 before Na.","steps":["Step 1: Sodium chloride decomposes to sodium and chlorine.","Step 2: Write NaCl → Na + Cl₂.","Step 3: Balance chlorine by placing 2 before NaCl.","Step 4: Balance sodium by placing 2 before Na."],"options":[],"conceptId":"chemistry_electrochemistry_meaning_of_electrolysis","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q3","subject":"chemistry","chapter":"electrochemistry","topic":"Meaning of Electrolysis"}', 2);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (3751, 858, 'Explain what happens to positive and negative ions during electrolysis.', 'text', 1, 'Use the charges of the ions and the charges of the electrodes.', '{"why":"Opposite charges attract, and electron transfer at the electrodes can produce new substances.","sol":"Step 1: Positive ions are attracted towards the negative electrode.\nStep 2: Negative ions are attracted towards the positive electrode.\nStep 3: At the electrodes, ions can gain or lose electrons.","steps":["Step 1: Positive ions are attracted towards the negative electrode.","Step 2: Negative ions are attracted towards the positive electrode.","Step 3: At the electrodes, ions can gain or lose electrons."],"options":[],"conceptId":"chemistry_electrochemistry_meaning_of_electrolysis","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q4","subject":"chemistry","chapter":"electrochemistry","topic":"Meaning of Electrolysis"}', 3),
  (3752, 858, 'A student passes an electric current through solid sodium chloride and expects sodium metal to form. Explain why the experiment is unsuitable under ordinary conditions.', 'text', 1, 'Consider the mobility of ions in solid sodium chloride.', '{"why":"Electrolysis requires mobile ions to carry current through the electrolyte.","sol":"Step 1: Solid sodium chloride contains Na⁺ and Cl⁻ ions.\nStep 2: The ions are fixed in the crystal lattice.\nStep 3: They cannot move freely to the electrodes.\nStep 4: The solid therefore cannot conduct current effectively for electrolysis.","steps":["Step 1: Solid sodium chloride contains Na⁺ and Cl⁻ ions.","Step 2: The ions are fixed in the crystal lattice.","Step 3: They cannot move freely to the electrodes.","Step 4: The solid therefore cannot conduct current effectively for electrolysis."],"options":[],"conceptId":"chemistry_electrochemistry_meaning_of_electrolysis","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q5","subject":"chemistry","chapter":"electrochemistry","topic":"Meaning of Electrolysis"}', 4),
  (3753, 858, 'Explain the difference between the energy change in electrolysis and the energy change in a simple chemical cell.', 'text', 1, 'Identify which form of energy is supplied and which form is produced.', '{"why":"The two processes involve opposite directions of energy conversion.","sol":"Step 1: During electrolysis, an external power supply provides electrical energy.\nStep 2: That energy drives a chemical decomposition.\nStep 3: A simple chemical cell uses a chemical reaction to produce electrical energy.","steps":["Step 1: During electrolysis, an external power supply provides electrical energy.","Step 2: That energy drives a chemical decomposition.","Step 3: A simple chemical cell uses a chemical reaction to produce electrical energy."],"options":[],"conceptId":"chemistry_electrochemistry_meaning_of_electrolysis","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q6","subject":"chemistry","chapter":"electrochemistry","topic":"Meaning of Electrolysis"}', 5),
  (3754, 859, 'Define an electrode and explain its role in an electrolytic cell.', 'text', 1, 'Consider how the external circuit connects to the electrolyte.', '{"why":"Electrodes connect the external circuit to the chemical reactions occurring in the electrolyte.","sol":"Step 1: Identify an electrode as a conductor.\nStep 2: Explain that it connects the external circuit to the electrolyte.\nStep 3: State that electron transfer may occur at its surface.","steps":["Step 1: Identify an electrode as a conductor.","Step 2: Explain that it connects the external circuit to the electrolyte.","Step 3: State that electron transfer may occur at its surface."],"options":[],"conceptId":"chemistry_electrochemistry_electrodes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q1","subject":"chemistry","chapter":"electrochemistry","topic":"Electrodes"}', 0),
  (3755, 859, 'Name the two electrodes used in electrolysis and state the charge of each.', 'text', 1, 'Recall the electrode charges in an electrolytic cell.', '{"why":"The external power supply establishes these electrode charges in an electrolytic cell.","sol":"Step 1: Identify the cathode.\nStep 2: The cathode is negative during electrolysis.\nStep 3: Identify the anode.\nStep 4: The anode is positive during electrolysis.","steps":["Step 1: Identify the cathode.","Step 2: The cathode is negative during electrolysis.","Step 3: Identify the anode.","Step 4: The anode is positive during electrolysis."],"options":[],"conceptId":"chemistry_electrochemistry_electrodes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q2","subject":"chemistry","chapter":"electrochemistry","topic":"Electrodes"}', 1),
  (3756, 859, 'During electrolysis, which electrode attracts Mg²⁺ ions? Explain your answer.', 'text', 1, 'Mg²⁺ is positively charged.', '{"why":"Opposite electrical charges attract.","sol":"Step 1: Mg²⁺ is a cation.\nStep 2: Cations are attracted to the negative electrode.\nStep 3: The negative electrode is the cathode.","steps":["Step 1: Mg²⁺ is a cation.","Step 2: Cations are attracted to the negative electrode.","Step 3: The negative electrode is the cathode."],"options":[],"conceptId":"chemistry_electrochemistry_electrodes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q3","subject":"chemistry","chapter":"electrochemistry","topic":"Electrodes"}', 2),
  (3757, 859, 'During electrolysis, which electrode attracts S²⁻ ions? Explain your answer.', 'text', 1, 'S²⁻ is negatively charged.', '{"why":"Opposite electrical charges attract.","sol":"Step 1: S²⁻ is an anion.\nStep 2: Anions are attracted to the positive electrode.\nStep 3: The positive electrode is the anode.","steps":["Step 1: S²⁻ is an anion.","Step 2: Anions are attracted to the positive electrode.","Step 3: The positive electrode is the anode."],"options":[],"conceptId":"chemistry_electrochemistry_electrodes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q4","subject":"chemistry","chapter":"electrochemistry","topic":"Electrodes"}', 3),
  (3758, 859, 'Explain the difference between the movement of ions in the electrolyte and electrons in the external circuit.', 'text', 1, 'Identify the charge carriers in each part of the circuit.', '{"why":"Electrolytes conduct through mobile ions; metallic wires conduct through moving electrons.","sol":"Step 1: Ions move through the electrolyte.\nStep 2: Electrons move through the external conducting circuit.\nStep 3: Both contribute to electrical conduction in their respective parts of the circuit.","steps":["Step 1: Ions move through the electrolyte.","Step 2: Electrons move through the external conducting circuit.","Step 3: Both contribute to electrical conduction in their respective parts of the circuit."],"options":[],"conceptId":"chemistry_electrochemistry_electrodes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q5","subject":"chemistry","chapter":"electrochemistry","topic":"Electrodes"}', 4),
  (3759, 859, 'A student says that the anode attracts positive ions because it is an electrode. Identify and correct the error.', 'text', 1, 'The word electrode does not determine the charge; consider the charge of the anode during electrolysis.', '{"why":"Ion movement depends on electrical charge: opposite charges attract.","sol":"Step 1: During electrolysis, the anode is positive.\nStep 2: Positive ions are attracted towards the negative electrode.\nStep 3: The negative electrode is the cathode.\nStep 4: Therefore, positive ions move towards the cathode, not the anode.","steps":["Step 1: During electrolysis, the anode is positive.","Step 2: Positive ions are attracted towards the negative electrode.","Step 3: The negative electrode is the cathode.","Step 4: Therefore, positive ions move towards the cathode, not the anode."],"options":[],"conceptId":"chemistry_electrochemistry_electrodes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q6","subject":"chemistry","chapter":"electrochemistry","topic":"Electrodes"}', 5),
  (3760, 860, 'Define the anode in terms of the chemical process that occurs there.', 'text', 1, 'Focus on electron transfer rather than only the electrode''s charge.', '{"why":"The anode is defined by oxidation, which involves the loss of electrons.","sol":"Step 1: Recall that oxidation involves loss of electrons.\nStep 2: Identify the electrode where oxidation occurs.\nStep 3: That electrode is the anode.","steps":["Step 1: Recall that oxidation involves loss of electrons.","Step 2: Identify the electrode where oxidation occurs.","Step 3: That electrode is the anode."],"options":[],"conceptId":"chemistry_electrochemistry_anode","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q1","subject":"chemistry","chapter":"electrochemistry","topic":"Anode"}', 0),
  (3761, 860, 'State the charge of the anode during electrolysis and explain why negative ions move towards it.', 'text', 1, 'Use the charges of the electrode and the ions.', '{"why":"The electric field causes anions to migrate towards the positive electrode.","sol":"Step 1: The anode is positive during electrolysis.\nStep 2: Negative ions are attracted to positive charges.\nStep 3: Therefore, anions move towards the anode.","steps":["Step 1: The anode is positive during electrolysis.","Step 2: Negative ions are attracted to positive charges.","Step 3: Therefore, anions move towards the anode."],"options":[],"conceptId":"chemistry_electrochemistry_anode","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q2","subject":"chemistry","chapter":"electrochemistry","topic":"Anode"}', 1),
  (3762, 860, 'Write the balanced half-equation for the formation of chlorine from chloride ions at the anode.', 'text', 1, 'Chlorine forms Cl₂, and oxidation releases electrons.', '{"why":"Two chloride ions lose two electrons to form one chlorine molecule.","sol":"Step 1: Start with Cl⁻ → Cl₂.\nStep 2: Place 2 before Cl⁻ to balance chlorine atoms.\nStep 3: The left side now has a charge of −2.\nStep 4: Add 2e⁻ to the right side to balance charge.","steps":["Step 1: Start with Cl⁻ → Cl₂.","Step 2: Place 2 before Cl⁻ to balance chlorine atoms.","Step 3: The left side now has a charge of −2.","Step 4: Add 2e⁻ to the right side to balance charge."],"options":[],"conceptId":"chemistry_electrochemistry_anode","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q3","subject":"chemistry","chapter":"electrochemistry","topic":"Anode"}', 2),
  (3763, 860, 'Write the balanced half-equation for the formation of bromine from bromide ions at the anode.', 'text', 1, 'Bromine exists as Br₂.', '{"why":"Bromide ions lose electrons during oxidation at the anode.","sol":"Step 1: Start with Br⁻ → Br₂.\nStep 2: Place 2 before Br⁻ to balance bromine atoms.\nStep 3: Two negative charges are present on the left.\nStep 4: Add 2e⁻ to the right to balance charge.","steps":["Step 1: Start with Br⁻ → Br₂.","Step 2: Place 2 before Br⁻ to balance bromine atoms.","Step 3: Two negative charges are present on the left.","Step 4: Add 2e⁻ to the right to balance charge."],"options":[],"conceptId":"chemistry_electrochemistry_anode","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q4","subject":"chemistry","chapter":"electrochemistry","topic":"Anode"}', 3),
  (3764, 860, 'In the half-equation 2I⁻ → I₂ + 2e⁻, explain why the reaction is oxidation.', 'text', 1, 'Count the electrons on each side of the equation.', '{"why":"Oxidation is defined as loss of electrons.","sol":"Step 1: Two iodide ions are present on the left.\nStep 2: Two electrons appear on the right.\nStep 3: The iodide ions lose these electrons.\nStep 4: Loss of electrons is oxidation.","steps":["Step 1: Two iodide ions are present on the left.","Step 2: Two electrons appear on the right.","Step 3: The iodide ions lose these electrons.","Step 4: Loss of electrons is oxidation."],"options":[],"conceptId":"chemistry_electrochemistry_anode","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q5","subject":"chemistry","chapter":"electrochemistry","topic":"Anode"}', 4),
  (3765, 860, 'A student writes Cl₂ + 2e⁻ → 2Cl⁻ as the anode reaction during electrolysis. Explain why this is incorrect for the formation of chlorine at the anode and give the correct equation.', 'text', 1, 'Check whether electrons are gained or lost in the student''s equation.', '{"why":"Oxidation at the anode requires the ions to lose electrons.","sol":"Step 1: The student''s equation places electrons on the left.\nStep 2: This represents gain of electrons by chlorine, which is reduction.\nStep 3: Formation of chlorine from chloride ions requires loss of electrons.\nStep 4: Reverse the equation.","steps":["Step 1: The student''s equation places electrons on the left.","Step 2: This represents gain of electrons by chlorine, which is reduction.","Step 3: Formation of chlorine from chloride ions requires loss of electrons.","Step 4: Reverse the equation."],"options":[],"conceptId":"chemistry_electrochemistry_anode","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q6","subject":"chemistry","chapter":"electrochemistry","topic":"Anode"}', 5),
  (3766, 861, 'Define the cathode in terms of the chemical process that occurs there.', 'text', 1, 'Focus on whether electrons are gained or lost.', '{"why":"The cathode is defined by the gain of electrons during the electrode reaction.","sol":"Step 1: Recall that reduction involves gain of electrons.\nStep 2: Identify the electrode where reduction occurs.\nStep 3: That electrode is the cathode.","steps":["Step 1: Recall that reduction involves gain of electrons.","Step 2: Identify the electrode where reduction occurs.","Step 3: That electrode is the cathode."],"options":[],"conceptId":"chemistry_electrochemistry_cathode","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q1","subject":"chemistry","chapter":"electrochemistry","topic":"Cathode"}', 0),
  (3767, 861, 'State the charge of the cathode during electrolysis and explain why positive ions move towards it.', 'text', 1, 'Compare the charge of the electrode with the charge of the ions.', '{"why":"The electric field causes cations to migrate towards the negative electrode.","sol":"Step 1: The cathode is negative during electrolysis.\nStep 2: Positive ions are attracted to negative charges.\nStep 3: Therefore, cations move towards the cathode.","steps":["Step 1: The cathode is negative during electrolysis.","Step 2: Positive ions are attracted to negative charges.","Step 3: Therefore, cations move towards the cathode."],"options":[],"conceptId":"chemistry_electrochemistry_cathode","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q2","subject":"chemistry","chapter":"electrochemistry","topic":"Cathode"}', 1),
  (3768, 861, 'Write the half-equation for the formation of sodium from Na⁺ ions at the cathode.', 'text', 1, 'A sodium ion needs one electron to become neutral.', '{"why":"The sodium ion gains one electron and is reduced to a sodium atom.","sol":"Step 1: Write Na⁺ as the reactant.\nStep 2: Add one electron to balance its positive charge.\nStep 3: Write neutral sodium as the product.","steps":["Step 1: Write Na⁺ as the reactant.","Step 2: Add one electron to balance its positive charge.","Step 3: Write neutral sodium as the product."],"options":[],"conceptId":"chemistry_electrochemistry_cathode","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q3","subject":"chemistry","chapter":"electrochemistry","topic":"Cathode"}', 2),
  (3769, 861, 'Write the half-equation for the formation of copper from Cu²⁺ ions at the cathode.', 'text', 1, 'A 2+ ion needs two electrons to become neutral.', '{"why":"Copper(II) ions gain two electrons and are reduced to copper atoms.","sol":"Step 1: Write Cu²⁺ as the reactant.\nStep 2: Add two electrons to balance the +2 charge.\nStep 3: Write neutral copper as the product.\nStep 4: Check that the total charge on both sides is zero.","steps":["Step 1: Write Cu²⁺ as the reactant.","Step 2: Add two electrons to balance the +2 charge.","Step 3: Write neutral copper as the product.","Step 4: Check that the total charge on both sides is zero."],"options":[],"conceptId":"chemistry_electrochemistry_cathode","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q4","subject":"chemistry","chapter":"electrochemistry","topic":"Cathode"}', 3),
  (3770, 861, 'In the equation Ag⁺ + e⁻ → Ag, explain why the reaction is reduction.', 'text', 1, 'Determine what happens to the electron.', '{"why":"Reduction is defined as gain of electrons.","sol":"Step 1: Ag⁺ has a charge of +1.\nStep 2: The silver ion gains one electron.\nStep 3: Its charge becomes zero.\nStep 4: Gain of electrons is reduction.","steps":["Step 1: Ag⁺ has a charge of +1.","Step 2: The silver ion gains one electron.","Step 3: Its charge becomes zero.","Step 4: Gain of electrons is reduction."],"options":[],"conceptId":"chemistry_electrochemistry_cathode","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q5","subject":"chemistry","chapter":"electrochemistry","topic":"Cathode"}', 4),
  (3771, 861, 'A student writes Cu → Cu²⁺ + 2e⁻ as the cathode reaction during the formation of copper metal. Explain the error and write the correct cathode equation for copper deposition.', 'text', 1, 'The student''s equation shows electrons being released. Copper deposition requires the opposite.', '{"why":"Copper(II) ions gain two electrons during reduction at the cathode.","sol":"Step 1: The student''s equation places electrons on the product side.\nStep 2: This means copper loses electrons, which is oxidation.\nStep 3: Copper deposition requires Cu²⁺ ions to gain electrons.\nStep 4: Reverse the equation.","steps":["Step 1: The student''s equation places electrons on the product side.","Step 2: This means copper loses electrons, which is oxidation.","Step 3: Copper deposition requires Cu²⁺ ions to gain electrons.","Step 4: Reverse the equation."],"options":[],"conceptId":"chemistry_electrochemistry_cathode","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q6","subject":"chemistry","chapter":"electrochemistry","topic":"Cathode"}', 5),
  (3772, 862, 'Molten sodium chloride is electrolysed using inert electrodes. State the product at each electrode and write both half-equations.', 'text', 1, 'Na⁺ gains one electron, while Cl⁻ loses electrons and forms Cl₂.', '{"why":"The positive sodium ions are reduced at the cathode, while chloride ions are oxidised at the anode.","sol":"Step 1: Identify Na⁺ as the positive ion and Cl⁻ as the negative ion.\nStep 2: Na⁺ moves to the cathode and gains one electron.\nStep 3: Two Cl⁻ ions move to the anode and lose two electrons in total.\nStep 4: Write the balanced half-equations.","steps":["Step 1: Identify Na⁺ as the positive ion and Cl⁻ as the negative ion.","Step 2: Na⁺ moves to the cathode and gains one electron.","Step 3: Two Cl⁻ ions move to the anode and lose two electrons in total.","Step 4: Write the balanced half-equations."],"options":[],"conceptId":"chemistry_electrochemistry_electrolysis_of_molten_compounds","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q1","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolysis of Molten Compounds"}', 0),
  (3773, 862, 'Molten lead(II) bromide is electrolysed. Write its overall equation and identify the state of each product under the hot electrolysis conditions.', 'text', 1, 'Pb²⁺ forms Pb, while bromide ions form diatomic bromine.', '{"why":"The formula PbBr₂ already contains one Pb atom and two Br atoms, so the overall equation is balanced as written.","sol":"Step 1: Identify the ions as Pb²⁺ and Br⁻.\nStep 2: Pb²⁺ gains two electrons to form lead.\nStep 3: Two Br⁻ ions lose two electrons to form Br₂.\nStep 4: Combine the balanced half-equations.","steps":["Step 1: Identify the ions as Pb²⁺ and Br⁻.","Step 2: Pb²⁺ gains two electrons to form lead.","Step 3: Two Br⁻ ions lose two electrons to form Br₂.","Step 4: Combine the balanced half-equations."],"options":[],"conceptId":"chemistry_electrochemistry_electrolysis_of_molten_compounds","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q2","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolysis of Molten Compounds"}', 1),
  (3774, 862, 'Write the cathode half-equation for the electrolysis of molten magnesium chloride. Explain why two electrons are required.', 'text', 1, 'Magnesium ions have a charge of +2.', '{"why":"Reduction involves gaining electrons, and two electrons neutralise the charge on Mg²⁺.","sol":"Step 1: Write the magnesium ion as Mg²⁺.\nStep 2: A neutral magnesium atom has no net charge.\nStep 3: Mg²⁺ must gain two electrons to cancel its +2 charge.\nStep 4: Write the balanced half-equation.","steps":["Step 1: Write the magnesium ion as Mg²⁺.","Step 2: A neutral magnesium atom has no net charge.","Step 3: Mg²⁺ must gain two electrons to cancel its +2 charge.","Step 4: Write the balanced half-equation."],"options":[],"conceptId":"chemistry_electrochemistry_electrolysis_of_molten_compounds","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q3","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolysis of Molten Compounds"}', 2),
  (3775, 862, 'During electrolysis of molten magnesium chloride, write the anode half-equation and explain why electrons appear on the right-hand side.', 'text', 1, 'Chloride ions are oxidised and chlorine exists as Cl₂.', '{"why":"Oxidation is the loss of electrons and occurs at the anode.","sol":"Step 1: Start with Cl⁻ ions.\nStep 2: Two chloride ions combine to form Cl₂.\nStep 3: Each chloride ion loses one electron.\nStep 4: Place two electrons on the product side.","steps":["Step 1: Start with Cl⁻ ions.","Step 2: Two chloride ions combine to form Cl₂.","Step 3: Each chloride ion loses one electron.","Step 4: Place two electrons on the product side."],"options":[],"conceptId":"chemistry_electrochemistry_electrolysis_of_molten_compounds","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q4","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolysis of Molten Compounds"}', 3),
  (3776, 862, 'A student writes MgCl₂(l) → Mg + 2Cl as the overall electrolysis equation. Identify the error and write the correct equation.', 'text', 1, 'Consider the natural molecular form of chlorine.', '{"why":"The equation must represent the actual elemental product and conserve the number of atoms.","sol":"Step 1: Chlorine forms diatomic molecules, Cl₂, rather than isolated Cl atoms under these conditions.\nStep 2: One formula unit of MgCl₂ contains one Mg atom and two Cl atoms.\nStep 3: Write the products as Mg and Cl₂.\nStep 4: Check that both atoms are balanced.","steps":["Step 1: Chlorine forms diatomic molecules, Cl₂, rather than isolated Cl atoms under these conditions.","Step 2: One formula unit of MgCl₂ contains one Mg atom and two Cl atoms.","Step 3: Write the products as Mg and Cl₂.","Step 4: Check that both atoms are balanced."],"options":[],"conceptId":"chemistry_electrochemistry_electrolysis_of_molten_compounds","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q5","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolysis of Molten Compounds"}', 4),
  (3777, 862, 'Molten sodium chloride produces sodium and chlorine. Combine the half-equations to show the balanced overall equation.', 'text', 1, 'Make the number of electrons lost equal to the number gained.', '{"why":"Electrons are transferred between the electrode reactions and cancel from the overall equation.","sol":"Step 1: Cathode: Na⁺ + e⁻ → Na.\nStep 2: Multiply the cathode equation by 2: 2Na⁺ + 2e⁻ → 2Na.\nStep 3: Anode: 2Cl⁻ → Cl₂ + 2e⁻.\nStep 4: Add the equations and cancel the two electrons.\nStep 5: Combine the ions into the original compound.","steps":["Step 1: Cathode: Na⁺ + e⁻ → Na.","Step 2: Multiply the cathode equation by 2: 2Na⁺ + 2e⁻ → 2Na.","Step 3: Anode: 2Cl⁻ → Cl₂ + 2e⁻.","Step 4: Add the equations and cancel the two electrons.","Step 5: Combine the ions into the original compound."],"options":[],"conceptId":"chemistry_electrochemistry_electrolysis_of_molten_compounds","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q6","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolysis of Molten Compounds"}', 5),
  (3778, 863, 'Explain why electrolysis of an aqueous ionic solution may produce different products from electrolysis of the same compound in its molten state.', 'text', 1, 'Compare the ions available in a molten salt with those present in its aqueous solution.', '{"why":"Water changes the range of species available to react at the electrodes.","sol":"Step 1: A molten ionic compound contains mobile ions from the compound.\nStep 2: An aqueous solution also contains species arising from water.\nStep 3: These additional species may compete for discharge at the electrodes.\nStep 4: Therefore, the electrode products can differ.","steps":["Step 1: A molten ionic compound contains mobile ions from the compound.","Step 2: An aqueous solution also contains species arising from water.","Step 3: These additional species may compete for discharge at the electrodes.","Step 4: Therefore, the electrode products can differ."],"options":[],"conceptId":"chemistry_electrochemistry_electrolysis_of_aqueous_solutions","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q1","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolysis of Aqueous Solutions"}', 0),
  (3779, 863, 'List the four ions commonly considered when analysing electrolysis of aqueous sodium chloride at introductory level.', 'text', 1, 'Include ions from sodium chloride and from water.', '{"why":"The dissolved salt and water contribute species that may be involved in the electrode reactions.","sol":"Step 1: Sodium chloride supplies Na⁺.\nStep 2: Sodium chloride also supplies Cl⁻.\nStep 3: Water is represented as contributing H⁺ and OH⁻ in the introductory analysis.\nStep 4: List all four species.","steps":["Step 1: Sodium chloride supplies Na⁺.","Step 2: Sodium chloride also supplies Cl⁻.","Step 3: Water is represented as contributing H⁺ and OH⁻ in the introductory analysis.","Step 4: List all four species."],"options":[],"conceptId":"chemistry_electrochemistry_electrolysis_of_aqueous_solutions","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q2","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolysis of Aqueous Solutions"}', 1),
  (3780, 863, 'Explain why sodium metal is not normally produced at the cathode during electrolysis of aqueous sodium chloride.', 'text', 1, 'Consider the competition between sodium ions and water for reduction.', '{"why":"Sodium is highly reactive, so its ions are not readily reduced to sodium metal in water under these conditions.","sol":"Step 1: Na⁺ ions move towards the cathode.\nStep 2: Species from water can also be reduced at the cathode.\nStep 3: Under ordinary aqueous conditions, water is reduced preferentially to sodium ions.\nStep 4: Hydrogen gas is formed instead of sodium metal.","steps":["Step 1: Na⁺ ions move towards the cathode.","Step 2: Species from water can also be reduced at the cathode.","Step 3: Under ordinary aqueous conditions, water is reduced preferentially to sodium ions.","Step 4: Hydrogen gas is formed instead of sodium metal."],"options":[],"conceptId":"chemistry_electrochemistry_electrolysis_of_aqueous_solutions","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q3","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolysis of Aqueous Solutions"}', 2),
  (3781, 863, 'Explain how concentration can affect the anode product when an aqueous chloride solution is electrolysed.', 'text', 1, 'Consider the competition between chloride ions and water-derived species.', '{"why":"Different species compete for oxidation at the anode, and concentration influences that competition.","sol":"Step 1: Chloride ions can be oxidised to chlorine.\nStep 2: Water-derived species can also be oxidised to produce oxygen.\nStep 3: In sufficiently concentrated chloride solutions, chlorine formation is generally favoured.\nStep 4: In sufficiently dilute solutions, oxygen formation may be favoured.","steps":["Step 1: Chloride ions can be oxidised to chlorine.","Step 2: Water-derived species can also be oxidised to produce oxygen.","Step 3: In sufficiently concentrated chloride solutions, chlorine formation is generally favoured.","Step 4: In sufficiently dilute solutions, oxygen formation may be favoured."],"options":[],"conceptId":"chemistry_electrochemistry_electrolysis_of_aqueous_solutions","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q4","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolysis of Aqueous Solutions"}', 3),
  (3782, 863, 'A student predicts the products of an aqueous electrolyte by considering only the ions in the dissolved salt. Explain why this method is incomplete.', 'text', 1, 'Identify another source of species in the solution.', '{"why":"Correct product prediction requires considering all relevant species and the conditions of electrolysis.","sol":"Step 1: The dissolved salt supplies its own ions.\nStep 2: Water also contributes species that may participate in electrode reactions.\nStep 3: These species can compete with the salt ions for discharge.\nStep 4: Therefore, both the salt and water must be considered.","steps":["Step 1: The dissolved salt supplies its own ions.","Step 2: Water also contributes species that may participate in electrode reactions.","Step 3: These species can compete with the salt ions for discharge.","Step 4: Therefore, both the salt and water must be considered."],"options":[],"conceptId":"chemistry_electrochemistry_electrolysis_of_aqueous_solutions","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q5","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolysis of Aqueous Solutions"}', 4),
  (3783, 863, 'Before predicting the products of electrolysis of an aqueous solution, state four factors you should consider.', 'text', 1, 'Think about the dissolved substance, the state of the electrolyte, and the electrodes.', '{"why":"These factors determine which species are oxidised or reduced and therefore which products form.","sol":"Step 1: Identify the electrolyte and the ions it provides.\nStep 2: Confirm that the electrolyte is aqueous.\nStep 3: Identify whether the electrodes are inert or active.\nStep 4: Consider concentration and which species are preferentially discharged.","steps":["Step 1: Identify the electrolyte and the ions it provides.","Step 2: Confirm that the electrolyte is aqueous.","Step 3: Identify whether the electrodes are inert or active.","Step 4: Consider concentration and which species are preferentially discharged."],"options":[],"conceptId":"chemistry_electrochemistry_electrolysis_of_aqueous_solutions","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q6","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolysis of Aqueous Solutions"}', 5),
  (3784, 864, 'State the products formed at the cathode and anode during electrolysis of aqueous copper(II) sulphate using inert electrodes.', 'text', 1, 'Identify the reduction product from Cu²⁺ and the oxidation product from water.', '{"why":"Copper(II) ions are reduced at the cathode, while water-derived species are oxidised at the inert anode.","sol":"Step 1: Cu²⁺ ions move towards the cathode.\nStep 2: Cu²⁺ ions gain electrons and form copper metal.\nStep 3: Water-derived species are oxidised at the inert anode.\nStep 4: Oxygen gas is produced at the anode.","steps":["Step 1: Cu²⁺ ions move towards the cathode.","Step 2: Cu²⁺ ions gain electrons and form copper metal.","Step 3: Water-derived species are oxidised at the inert anode.","Step 4: Oxygen gas is produced at the anode."],"options":[],"conceptId":"chemistry_electrochemistry_electrolysis_of_copper_ii_sulphate","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q1","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolysis of Copper(II) Sulphate"}', 0),
  (3785, 864, 'Write the balanced cathode half-equation for electrolysis of aqueous copper(II) sulphate using inert electrodes.', 'text', 1, 'A Cu²⁺ ion needs two electrons to form neutral copper.', '{"why":"Copper(II) ions gain two electrons and are reduced to copper metal.","sol":"Step 1: Write Cu²⁺ as the reactant.\nStep 2: Add two electrons to balance its +2 charge.\nStep 3: Write Cu as the neutral product.\nStep 4: Check that the total charge is zero on both sides.","steps":["Step 1: Write Cu²⁺ as the reactant.","Step 2: Add two electrons to balance its +2 charge.","Step 3: Write Cu as the neutral product.","Step 4: Check that the total charge is zero on both sides."],"options":[],"conceptId":"chemistry_electrochemistry_electrolysis_of_copper_ii_sulphate","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q2","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolysis of Copper(II) Sulphate"}', 1),
  (3786, 864, 'Write the balanced half-equation for oxygen formation at the inert anode using hydroxide ions.', 'text', 1, 'Balance oxygen and hydrogen atoms, then balance the charge with electrons.', '{"why":"The balanced half-equation conserves atoms and charge, with electrons released during oxidation.","sol":"Step 1: Start with OH⁻ as the reactant and O₂ as the gaseous product.\nStep 2: Use 4OH⁻ to provide four oxygen atoms and four hydrogen atoms.\nStep 3: Place 2H₂O on the product side to balance hydrogen.\nStep 4: Place O₂ on the product side and check oxygen atoms.\nStep 5: Add 4e⁻ to the product side to balance the charge.","steps":["Step 1: Start with OH⁻ as the reactant and O₂ as the gaseous product.","Step 2: Use 4OH⁻ to provide four oxygen atoms and four hydrogen atoms.","Step 3: Place 2H₂O on the product side to balance hydrogen.","Step 4: Place O₂ on the product side and check oxygen atoms.","Step 5: Add 4e⁻ to the product side to balance the charge."],"options":[],"conceptId":"chemistry_electrochemistry_electrolysis_of_copper_ii_sulphate","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q3","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolysis of Copper(II) Sulphate"}', 2),
  (3787, 864, 'Explain why copper metal forms at the cathode rather than at the anode.', 'text', 1, 'Determine which process Cu²⁺ must undergo to become copper metal.', '{"why":"Reduction is gain of electrons and occurs at the cathode.","sol":"Step 1: Cu²⁺ ions carry a positive charge.\nStep 2: They move towards the negative cathode.\nStep 3: They gain two electrons at the cathode.\nStep 4: The reduced ions form neutral copper atoms.","steps":["Step 1: Cu²⁺ ions carry a positive charge.","Step 2: They move towards the negative cathode.","Step 3: They gain two electrons at the cathode.","Step 4: The reduced ions form neutral copper atoms."],"options":[],"conceptId":"chemistry_electrochemistry_electrolysis_of_copper_ii_sulphate","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q4","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolysis of Copper(II) Sulphate"}', 3),
  (3788, 864, 'In an electrolysis experiment, 0.20 mol of Cu²⁺ ions are completely reduced. Calculate the mass of copper deposited. Use Cu = 63.5 g mol⁻¹.', 'text', 1, 'The mole ratio of Cu²⁺ to Cu is 1:1.', '{"why":"The 1:1 mole ratio means 0.20 mol of Cu²⁺ forms 0.20 mol of copper, whose mass is 12.7 g.","sol":"Step 1: Write Cu²⁺ + 2e⁻ → Cu.\nStep 2: One mole of Cu²⁺ produces one mole of Cu.\nStep 3: Moles of Cu formed = 0.20 mol.\nStep 4: Mass = moles × molar mass.\nStep 5: Mass = 0.20 × 63.5 = 12.7 g.","steps":["Step 1: Write Cu²⁺ + 2e⁻ → Cu.","Step 2: One mole of Cu²⁺ produces one mole of Cu.","Step 3: Moles of Cu formed = 0.20 mol.","Step 4: Mass = moles × molar mass.","Step 5: Mass = 0.20 × 63.5 = 12.7 g."],"options":[],"conceptId":"chemistry_electrochemistry_electrolysis_of_copper_ii_sulphate","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q5","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolysis of Copper(II) Sulphate"}', 4),
  (3789, 864, 'Explain why the anode reaction changes when copper electrodes are used instead of inert electrodes during electrolysis of aqueous copper(II) sulphate.', 'text', 1, 'Consider whether the copper anode can itself take part in the reaction.', '{"why":"An active copper anode participates in the reaction, whereas an inert anode is not consumed in the same way.","sol":"Step 1: An inert electrode is not intended to be consumed in the electrode reaction.\nStep 2: A copper anode can lose copper atoms to the solution.\nStep 3: Copper atoms form Cu²⁺ ions by losing two electrons.\nStep 4: Write the anode half-equation.","steps":["Step 1: An inert electrode is not intended to be consumed in the electrode reaction.","Step 2: A copper anode can lose copper atoms to the solution.","Step 3: Copper atoms form Cu²⁺ ions by losing two electrons.","Step 4: Write the anode half-equation."],"options":[],"conceptId":"chemistry_electrochemistry_electrolysis_of_copper_ii_sulphate","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q6","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolysis of Copper(II) Sulphate"}', 5),
  (3790, 865, 'A simple cell contains two electrodes, an electrolyte and a wire. State the function of each of these components.', 'text', 1, 'Consider where electrons travel and where ions move.', '{"why":"A working cell requires charge transfer both inside the cell through ions and outside it through the conducting circuit.","sol":"Step 1: Identify the two conducting electrodes.\nStep 2: Explain the role of the electrolyte in carrying charge through mobile ions.\nStep 3: Explain how the wire provides an external path for electron flow.","steps":["Step 1: Identify the two conducting electrodes.","Step 2: Explain the role of the electrolyte in carrying charge through mobile ions.","Step 3: Explain how the wire provides an external path for electron flow."],"options":[],"conceptId":"chemistry_electrochemistry_simple_cells","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q1","subject":"chemistry","chapter":"electrochemistry","topic":"Simple Cells"}', 0),
  (3791, 865, 'Write the half-equation for zinc atoms forming zinc ions.', 'text', 1, 'Zinc forms Zn²⁺, so account for a charge of +2.', '{"why":"Zinc loses two electrons. Loss of electrons is oxidation.","sol":"Step 1: Write Zn → Zn²⁺.\nStep 2: The right side has a charge of +2.\nStep 3: Add two electrons to the right side to balance the charge.","steps":["Step 1: Write Zn → Zn²⁺.","Step 2: The right side has a charge of +2.","Step 3: Add two electrons to the right side to balance the charge."],"options":[],"conceptId":"chemistry_electrochemistry_simple_cells","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q2","subject":"chemistry","chapter":"electrochemistry","topic":"Simple Cells"}', 1),
  (3792, 865, 'Write the half-equation for copper(II) ions gaining electrons to form copper metal.', 'text', 1, 'Cu²⁺ must gain enough electrons to become neutral.', '{"why":"Copper(II) ions gain two electrons. Gain of electrons is reduction.","sol":"Step 1: Start with Cu²⁺ → Cu.\nStep 2: The left side has a charge of +2 while the right side is neutral.\nStep 3: Add two electrons to the left side.","steps":["Step 1: Start with Cu²⁺ → Cu.","Step 2: The left side has a charge of +2 while the right side is neutral.","Step 3: Add two electrons to the left side."],"options":[],"conceptId":"chemistry_electrochemistry_simple_cells","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q3","subject":"chemistry","chapter":"electrochemistry","topic":"Simple Cells"}', 2),
  (3793, 865, 'In the zinc-copper cell described in the notes, state the direction of electron flow in the external wire and explain why.', 'text', 1, 'Find the electrode at which electrons are released.', '{"why":"Electron flow follows the external conducting path from the electrode releasing electrons towards the electrode where reduction occurs.","sol":"Step 1: Zinc undergoes oxidation.\nStep 2: Oxidation releases electrons.\nStep 3: The released electrons travel through the wire towards the copper electrode.","steps":["Step 1: Zinc undergoes oxidation.","Step 2: Oxidation releases electrons.","Step 3: The released electrons travel through the wire towards the copper electrode."],"options":[],"conceptId":"chemistry_electrochemistry_simple_cells","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q4","subject":"chemistry","chapter":"electrochemistry","topic":"Simple Cells"}', 3),
  (3794, 865, 'Explain the difference between electron flow and conventional current in the external wire of a zinc-copper cell.', 'text', 1, 'Conventional current is defined in the direction positive charge would move.', '{"why":"Electrons are negatively charged, whereas conventional current is defined using the direction of positive charge movement.","sol":"Step 1: State the direction of electron movement.\nStep 2: State the defined direction of conventional current.\nStep 3: Compare the two directions.","steps":["Step 1: State the direction of electron movement.","Step 2: State the defined direction of conventional current.","Step 3: Compare the two directions."],"options":[],"conceptId":"chemistry_electrochemistry_simple_cells","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q5","subject":"chemistry","chapter":"electrochemistry","topic":"Simple Cells"}', 4),
  (3795, 865, 'A student connects zinc and copper electrodes to a voltmeter but leaves the circuit otherwise open. Explain what the voltmeter can indicate and why a continuous current may not flow through an external load.', 'text', 1, 'Distinguish a potential difference from a complete conducting path.', '{"why":"A potential difference can exist even when the circuit is open, but sustained current requires a complete conducting path.","sol":"Step 1: Recognise that suitable electrode reactions can establish a potential difference.\nStep 2: Consider whether the external circuit is complete.\nStep 3: Explain the consequence of the open circuit for continuous current.","steps":["Step 1: Recognise that suitable electrode reactions can establish a potential difference.","Step 2: Consider whether the external circuit is complete.","Step 3: Explain the consequence of the open circuit for continuous current."],"options":[],"conceptId":"chemistry_electrochemistry_simple_cells","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q6","subject":"chemistry","chapter":"electrochemistry","topic":"Simple Cells"}', 5),
  (3796, 866, 'A cell transfers 12 J of energy when 3 C of charge passes through it. Calculate the voltage.', 'text', 1, 'Use V = E / Q.', '{"why":"Voltage is energy transferred per unit charge.","sol":"Step 1: Write V = E / Q.\nStep 2: Substitute E = 12 J and Q = 3 C.\nStep 3: Calculate 12 / 3.","steps":["Step 1: Write V = E / Q.","Step 2: Substitute E = 12 J and Q = 3 C.","Step 3: Calculate 12 / 3."],"options":[],"conceptId":"chemistry_electrochemistry_chemical_cell_voltage","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q1","subject":"chemistry","chapter":"electrochemistry","topic":"Chemical Cell Voltage"}', 0),
  (3797, 866, 'A cell operates at 2.0 V while transferring 5 C of charge. Calculate the energy transferred.', 'text', 1, 'Rearrange V = E / Q to make E the subject.', '{"why":"Energy transferred equals potential difference multiplied by charge.","sol":"Step 1: Use E = V × Q.\nStep 2: Substitute V = 2.0 V and Q = 5 C.\nStep 3: Multiply 2.0 by 5.","steps":["Step 1: Use E = V × Q.","Step 2: Substitute V = 2.0 V and Q = 5 C.","Step 3: Multiply 2.0 by 5."],"options":[],"conceptId":"chemistry_electrochemistry_chemical_cell_voltage","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q2","subject":"chemistry","chapter":"electrochemistry","topic":"Chemical Cell Voltage"}', 1),
  (3798, 866, 'A cell transfers 18 J of energy at a voltage of 3 V. Calculate the charge transferred.', 'text', 1, 'Use Q = E / V.', '{"why":"Dividing the energy transferred by the voltage gives the charge transferred.","sol":"Step 1: Write Q = E / V.\nStep 2: Substitute E = 18 J and V = 3 V.\nStep 3: Calculate 18 / 3.","steps":["Step 1: Write Q = E / V.","Step 2: Substitute E = 18 J and V = 3 V.","Step 3: Calculate 18 / 3."],"options":[],"conceptId":"chemistry_electrochemistry_chemical_cell_voltage","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q3","subject":"chemistry","chapter":"electrochemistry","topic":"Chemical Cell Voltage"}', 2),
  (3799, 866, 'A cell transfers 24 J of energy when 4 C of charge passes through it. Calculate its voltage and state the meaning of your answer.', 'text', 1, 'First calculate energy per coulomb.', '{"why":"One volt is one joule per coulomb.","sol":"Step 1: Use V = E / Q.\nStep 2: Substitute V = 24 / 4.\nStep 3: Calculate the voltage.\nStep 4: Interpret the result in joules per coulomb.","steps":["Step 1: Use V = E / Q.","Step 2: Substitute V = 24 / 4.","Step 3: Calculate the voltage.","Step 4: Interpret the result in joules per coulomb."],"options":[],"conceptId":"chemistry_electrochemistry_chemical_cell_voltage","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q4","subject":"chemistry","chapter":"electrochemistry","topic":"Chemical Cell Voltage"}', 3),
  (3800, 866, 'Two ideal 1.5 V cells are connected in series in the same direction. Calculate the total voltage and explain the operation used.', 'text', 1, 'Voltages of cells connected in series in the same direction add.', '{"why":"In an ideal series arrangement with the same orientation, the potential differences add.","sol":"Step 1: Identify the voltage of each cell as 1.5 V.\nStep 2: Add the two voltages.\nStep 3: State the total voltage.","steps":["Step 1: Identify the voltage of each cell as 1.5 V.","Step 2: Add the two voltages.","Step 3: State the total voltage."],"options":[],"conceptId":"chemistry_electrochemistry_chemical_cell_voltage","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q5","subject":"chemistry","chapter":"electrochemistry","topic":"Chemical Cell Voltage"}', 4),
  (3801, 866, 'Two ideal cells of 1.5 V and 1.0 V are connected in opposition. Calculate the net voltage and state which cell determines the direction of the net potential difference.', 'text', 1, 'Subtract the smaller opposing voltage from the larger one.', '{"why":"Opposing potential differences subtract. The larger one determines the net direction when the voltages are unequal.","sol":"Step 1: Write the opposing voltages as 1.5 V and 1.0 V.\nStep 2: Calculate 1.5 − 1.0.\nStep 3: Compare the two values to identify the larger voltage.","steps":["Step 1: Write the opposing voltages as 1.5 V and 1.0 V.","Step 2: Calculate 1.5 − 1.0.","Step 3: Compare the two values to identify the larger voltage."],"options":[],"conceptId":"chemistry_electrochemistry_chemical_cell_voltage","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q6","subject":"chemistry","chapter":"electrochemistry","topic":"Chemical Cell Voltage"}', 5),
  (3802, 867, 'Explain the difference between a primary battery and a secondary battery.', 'text', 1, 'Focus on whether the chemical system is designed to be recharged.', '{"why":"The distinction is based on whether the battery chemistry is designed to be restored by charging.","sol":"Step 1: Define a primary battery.\nStep 2: Define a secondary battery.\nStep 3: Explain the difference in how each is used after discharge.","steps":["Step 1: Define a primary battery.","Step 2: Define a secondary battery.","Step 3: Explain the difference in how each is used after discharge."],"options":[],"conceptId":"chemistry_electrochemistry_batteries","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q1","subject":"chemistry","chapter":"electrochemistry","topic":"Batteries"}', 0),
  (3803, 867, 'A device uses three ideal 1.5 V cells connected in series in the same direction. Calculate the total voltage.', 'text', 1, 'Add the voltages of cells connected in series in the same direction.', '{"why":"The potential differences of ideal cells connected in series in the same direction add.","sol":"Step 1: Write the three cell voltages.\nStep 2: Calculate 1.5 + 1.5 + 1.5.\nStep 3: State the answer in volts.","steps":["Step 1: Write the three cell voltages.","Step 2: Calculate 1.5 + 1.5 + 1.5.","Step 3: State the answer in volts."],"options":[],"conceptId":"chemistry_electrochemistry_batteries","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q2","subject":"chemistry","chapter":"electrochemistry","topic":"Batteries"}', 1),
  (3804, 867, 'Two compatible ideal 1.5 V cells are available. Explain how to connect them to provide approximately 3.0 V and calculate the result.', 'text', 1, 'Choose the arrangement in which the cell voltages add.', '{"why":"A series arrangement adds the voltage of each cell when their orientations agree.","sol":"Step 1: Recognise that the required voltage is 3.0 V.\nStep 2: Connect the cells in series with matching orientation.\nStep 3: Add their voltages.","steps":["Step 1: Recognise that the required voltage is 3.0 V.","Step 2: Connect the cells in series with matching orientation.","Step 3: Add their voltages."],"options":[],"conceptId":"chemistry_electrochemistry_batteries","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q3","subject":"chemistry","chapter":"electrochemistry","topic":"Batteries"}', 2),
  (3805, 867, 'Two compatible ideal cells, each rated at 1.5 V, are connected in parallel with matching polarity. What voltage should the arrangement provide, and how can parallel connection be useful?', 'text', 1, 'Compare the voltage of a parallel arrangement with the voltage of one cell.', '{"why":"Parallel connection does not add the cell voltages; it can allow compatible cells to share the load.","sol":"Step 1: Identify the voltage of one cell as 1.5 V.\nStep 2: Apply the rule for compatible equal-voltage cells in parallel.\nStep 3: State a potential advantage of the arrangement.","steps":["Step 1: Identify the voltage of one cell as 1.5 V.","Step 2: Apply the rule for compatible equal-voltage cells in parallel.","Step 3: State a potential advantage of the arrangement."],"options":[],"conceptId":"chemistry_electrochemistry_batteries","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q4","subject":"chemistry","chapter":"electrochemistry","topic":"Batteries"}', 3),
  (3806, 867, 'A student claims that a rechargeable battery can be recharged forever without losing performance. Explain why this claim is incorrect.', 'text', 1, 'Consider what repeated chemical and physical changes do to a battery.', '{"why":"Rechargeability means the chemical system can be restored repeatedly, not that all components remain unchanged forever.","sol":"Step 1: Recognise that secondary batteries can be recharged.\nStep 2: Consider repeated charge-discharge cycles.\nStep 3: Explain how age, heat or unsuitable charging affects performance.","steps":["Step 1: Recognise that secondary batteries can be recharged.","Step 2: Consider repeated charge-discharge cycles.","Step 3: Explain how age, heat or unsuitable charging affects performance."],"options":[],"conceptId":"chemistry_electrochemistry_batteries","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q5","subject":"chemistry","chapter":"electrochemistry","topic":"Batteries"}', 4),
  (3807, 867, 'A portable device requires a higher voltage than one cell can provide. Explain why connecting compatible cells in series may be appropriate, and state one condition for doing so safely.', 'text', 1, 'Consider how series voltage changes and why cell compatibility matters.', '{"why":"Series connection raises the total voltage, but incorrect cell selection or connection can damage the cells or device.","sol":"Step 1: Identify the need for a higher voltage.\nStep 2: Explain that series cell voltages add when oriented in the same direction.\nStep 3: State a relevant compatibility or safety condition.","steps":["Step 1: Identify the need for a higher voltage.","Step 2: Explain that series cell voltages add when oriented in the same direction.","Step 3: State a relevant compatibility or safety condition."],"options":[],"conceptId":"chemistry_electrochemistry_batteries","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q6","subject":"chemistry","chapter":"electrochemistry","topic":"Batteries"}', 5),
  (3808, 868, 'Explain why an aqueous sodium chloride solution conducts electricity.', 'text', 1, 'Focus on the particles produced when sodium chloride dissolves.', '{"why":"An electrolyte conducts through mobile ions rather than through the unrestricted movement of electrons as in a metal.","sol":"Step 1: Write the ions produced by sodium chloride in water.\nStep 2: State whether the ions are mobile in solution.\nStep 3: Explain how moving ions carry electrical charge.","steps":["Step 1: Write the ions produced by sodium chloride in water.","Step 2: State whether the ions are mobile in solution.","Step 3: Explain how moving ions carry electrical charge."],"options":[],"conceptId":"chemistry_electrochemistry_strong_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q1","subject":"chemistry","chapter":"electrochemistry","topic":"Strong Electrolytes"}', 0),
  (3809, 868, 'Write the equation showing sodium chloride separating into ions in water. Check that both atoms and total charge are balanced.', 'text', 1, 'One formula unit of NaCl produces one sodium ion and one chloride ion.', '{"why":"Dissociation separates the ions already present in the ionic compound.","sol":"Step 1: Write NaCl as the reactant.\nStep 2: Write Na⁺ and Cl⁻ as the products.\nStep 3: Check that there is one sodium atom and one chlorine atom on each side.\nStep 4: Check that the total charge on the products is zero.","steps":["Step 1: Write NaCl as the reactant.","Step 2: Write Na⁺ and Cl⁻ as the products.","Step 3: Check that there is one sodium atom and one chlorine atom on each side.","Step 4: Check that the total charge on the products is zero."],"options":[],"conceptId":"chemistry_electrochemistry_strong_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q2","subject":"chemistry","chapter":"electrochemistry","topic":"Strong Electrolytes"}', 1),
  (3810, 868, 'Write the simplified aqueous ionisation equation for hydrochloric acid.', 'text', 1, 'Hydrochloric acid produces hydrogen ions and chloride ions in water.', '{"why":"The equation represents extensive ionisation of hydrochloric acid in aqueous solution using simplified school-level notation.","sol":"Step 1: Write HCl(aq) on the left.\nStep 2: Write H⁺(aq) and Cl⁻(aq) on the right.\nStep 3: Check the atoms and total electrical charge.","steps":["Step 1: Write HCl(aq) on the left.","Step 2: Write H⁺(aq) and Cl⁻(aq) on the right.","Step 3: Check the atoms and total electrical charge."],"options":[],"conceptId":"chemistry_electrochemistry_strong_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q3","subject":"chemistry","chapter":"electrochemistry","topic":"Strong Electrolytes"}', 2),
  (3811, 868, 'Explain the difference between the strength of an electrolyte and the concentration of its solution.', 'text', 1, 'One describes ion formation; the other describes the amount dissolved per volume.', '{"why":"The extent of ion formation and the amount of substance present are different properties.","sol":"Step 1: Define electrolyte strength in terms of ion formation.\nStep 2: Define concentration in terms of amount of solute and volume.\nStep 3: Explain why the two quantities are not interchangeable.","steps":["Step 1: Define electrolyte strength in terms of ion formation.","Step 2: Define concentration in terms of amount of solute and volume.","Step 3: Explain why the two quantities are not interchangeable."],"options":[],"conceptId":"chemistry_electrochemistry_strong_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q4","subject":"chemistry","chapter":"electrochemistry","topic":"Strong Electrolytes"}', 3),
  (3812, 868, 'A strong electrolyte solution conducts poorly because it is extremely dilute. Explain why this observation does not prove that the electrolyte is weak.', 'text', 1, 'Consider how many mobile ions may be present per unit volume.', '{"why":"Conductivity depends on both ion formation and the concentration and mobility of the ions present.","sol":"Step 1: Recognise that a strong electrolyte forms ions extensively.\nStep 2: Recognise that dilution reduces the number of ions per unit volume.\nStep 3: Relate the lower number of charge carriers to conductivity.","steps":["Step 1: Recognise that a strong electrolyte forms ions extensively.","Step 2: Recognise that dilution reduces the number of ions per unit volume.","Step 3: Relate the lower number of charge carriers to conductivity."],"options":[],"conceptId":"chemistry_electrochemistry_strong_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q5","subject":"chemistry","chapter":"electrochemistry","topic":"Strong Electrolytes"}', 4),
  (3813, 868, 'A student tests aqueous sodium hydroxide and finds that it conducts electricity. Explain the observation and identify the types of ions present.', 'text', 1, 'Consider how sodium hydroxide separates in water.', '{"why":"Sodium hydroxide is a strong electrolyte because it dissociates extensively into mobile ions in water.","sol":"Step 1: Write the dissociation equation for sodium hydroxide.\nStep 2: Identify the positive and negative ions.\nStep 3: Explain how the ions carry charge through the solution.","steps":["Step 1: Write the dissociation equation for sodium hydroxide.","Step 2: Identify the positive and negative ions.","Step 3: Explain how the ions carry charge through the solution."],"options":[],"conceptId":"chemistry_electrochemistry_strong_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q6","subject":"chemistry","chapter":"electrochemistry","topic":"Strong Electrolytes"}', 5),
  (3814, 869, 'Define a weak electrolyte and explain why it contains both ions and un-ionised molecules in solution.', 'text', 1, 'Focus on whether ion formation is complete or partial.', '{"why":"Partial ionisation means not all dissolved particles become ions.","sol":"Step 1: Define a weak electrolyte in terms of ionisation.\nStep 2: Explain that the ionisation reaction is reversible.\nStep 3: Identify the particles present at equilibrium.","steps":["Step 1: Define a weak electrolyte in terms of ionisation.","Step 2: Explain that the ionisation reaction is reversible.","Step 3: Identify the particles present at equilibrium."],"options":[],"conceptId":"chemistry_electrochemistry_weak_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q1","subject":"chemistry","chapter":"electrochemistry","topic":"Weak Electrolytes"}', 0),
  (3815, 869, 'Write the equilibrium equation for ethanoic acid ionising in water using simplified school-level notation.', 'text', 1, 'Ethanoic acid forms hydrogen ions and ethanoate ions.', '{"why":"The reversible arrow represents partial ionisation and the establishment of an equilibrium.","sol":"Step 1: Write CH₃COOH as the reactant.\nStep 2: Write H⁺ and CH₃COO⁻ as the products.\nStep 3: Use a reversible arrow because ionisation is partial.","steps":["Step 1: Write CH₃COOH as the reactant.","Step 2: Write H⁺ and CH₃COO⁻ as the products.","Step 3: Use a reversible arrow because ionisation is partial."],"options":[],"conceptId":"chemistry_electrochemistry_weak_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q2","subject":"chemistry","chapter":"electrochemistry","topic":"Weak Electrolytes"}', 1),
  (3816, 869, 'Write the equation for ammonia reacting with water to form ammonium and hydroxide ions.', 'text', 1, 'Ammonia accepts a hydrogen ion from water.', '{"why":"Ammonia reacts partially with water, producing ammonium and hydroxide ions.","sol":"Step 1: Write NH₃ and H₂O on the left.\nStep 2: Write NH₄⁺ and OH⁻ on the right.\nStep 3: Check that atoms and total charge are balanced.","steps":["Step 1: Write NH₃ and H₂O on the left.","Step 2: Write NH₄⁺ and OH⁻ on the right.","Step 3: Check that atoms and total charge are balanced."],"options":[],"conceptId":"chemistry_electrochemistry_weak_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q3","subject":"chemistry","chapter":"electrochemistry","topic":"Weak Electrolytes"}', 2),
  (3817, 869, 'Explain why a weak electrolyte can conduct electricity even though it ionises only partially.', 'text', 1, 'Complete ionisation is not necessary for a solution to contain charge carriers.', '{"why":"Conductivity requires mobile charge carriers, not complete ionisation of every dissolved particle.","sol":"Step 1: Recognise that partial ionisation produces some ions.\nStep 2: State that these ions are mobile in solution.\nStep 3: Link their movement to electrical conduction.","steps":["Step 1: Recognise that partial ionisation produces some ions.","Step 2: State that these ions are mobile in solution.","Step 3: Link their movement to electrical conduction."],"options":[],"conceptId":"chemistry_electrochemistry_weak_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q4","subject":"chemistry","chapter":"electrochemistry","topic":"Weak Electrolytes"}', 3),
  (3818, 869, 'Two solutions have the same concentration and temperature. One contains a strong electrolyte and the other a weak electrolyte. Explain which would generally have the higher conductivity and why.', 'text', 1, 'Compare the number of mobile ions formed under similar conditions.', '{"why":"At the same concentration, greater ion formation generally increases the number of charge carriers available to conduct.","sol":"Step 1: State the extent of ion formation in the strong electrolyte.\nStep 2: State the extent of ion formation in the weak electrolyte.\nStep 3: Relate the relative number of mobile ions to conductivity.","steps":["Step 1: State the extent of ion formation in the strong electrolyte.","Step 2: State the extent of ion formation in the weak electrolyte.","Step 3: Relate the relative number of mobile ions to conductivity."],"options":[],"conceptId":"chemistry_electrochemistry_weak_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q5","subject":"chemistry","chapter":"electrochemistry","topic":"Weak Electrolytes"}', 4),
  (3819, 869, 'A student calls ethanoic acid a dilute electrolyte because it is weak. Explain the mistake and distinguish the two terms.', 'text', 1, 'One term describes ionisation; the other describes the amount of solute in a volume.', '{"why":"Electrolyte strength and solution concentration describe different properties.","sol":"Step 1: Define weak in terms of partial ionisation.\nStep 2: Define dilute in terms of solute amount per volume.\nStep 3: Explain why one property does not automatically establish the other.","steps":["Step 1: Define weak in terms of partial ionisation.","Step 2: Define dilute in terms of solute amount per volume.","Step 3: Explain why one property does not automatically establish the other."],"options":[],"conceptId":"chemistry_electrochemistry_weak_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q6","subject":"chemistry","chapter":"electrochemistry","topic":"Weak Electrolytes"}', 5),
  (3820, 870, 'Define a non-electrolyte and explain why its aqueous solution conducts electricity very poorly.', 'text', 1, 'Focus on the number of mobile ions produced.', '{"why":"Effective ionic conduction requires mobile charged particles.","sol":"Step 1: Define a non-electrolyte in terms of ion formation.\nStep 2: Explain what happens to its particles when it dissolves.\nStep 3: Relate the scarcity of mobile ions to electrical conduction.","steps":["Step 1: Define a non-electrolyte in terms of ion formation.","Step 2: Explain what happens to its particles when it dissolves.","Step 3: Relate the scarcity of mobile ions to electrical conduction."],"options":[],"conceptId":"chemistry_electrochemistry_non_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q1","subject":"chemistry","chapter":"electrochemistry","topic":"Non-electrolytes"}', 0),
  (3821, 870, 'Sugar dissolves in water, but sugar solution conducts electricity very poorly. Explain this observation.', 'text', 1, 'Consider whether dissolved sucrose molecules become ions.', '{"why":"Dissolving does not necessarily produce ions.","sol":"Step 1: State that sucrose dissolves in water.\nStep 2: Identify the particles present after dissolving.\nStep 3: Explain why these particles do not carry ionic current effectively.","steps":["Step 1: State that sucrose dissolves in water.","Step 2: Identify the particles present after dissolving.","Step 3: Explain why these particles do not carry ionic current effectively."],"options":[],"conceptId":"chemistry_electrochemistry_non_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q2","subject":"chemistry","chapter":"electrochemistry","topic":"Non-electrolytes"}', 1),
  (3822, 870, 'Write a simple equation representing sucrose dissolving in water, and explain why it is not an ionisation equation.', 'text', 1, 'The formula of sucrose is C₁₂H₂₂O₁₁.', '{"why":"The aqueous symbol indicates that sucrose is dissolved; it does not mean that it has ionised.","sol":"Step 1: Write solid sucrose on the left.\nStep 2: Write aqueous sucrose on the right.\nStep 3: Check whether the equation shows charged products.","steps":["Step 1: Write solid sucrose on the left.","Step 2: Write aqueous sucrose on the right.","Step 3: Check whether the equation shows charged products."],"options":[],"conceptId":"chemistry_electrochemistry_non_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q3","subject":"chemistry","chapter":"electrochemistry","topic":"Non-electrolytes"}', 2),
  (3823, 870, 'Explain the difference between dissolving and ionisation using a substance that behaves as a non-electrolyte.', 'text', 1, 'Compare the distribution of particles in water with the formation of charged particles.', '{"why":"A solution can form without producing the mobile ions needed for effective ionic conduction.","sol":"Step 1: Explain what happens during dissolving.\nStep 2: Explain what happens during ionisation.\nStep 3: Use sucrose as an example to distinguish the processes.","steps":["Step 1: Explain what happens during dissolving.","Step 2: Explain what happens during ionisation.","Step 3: Use sucrose as an example to distinguish the processes."],"options":[],"conceptId":"chemistry_electrochemistry_non_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q4","subject":"chemistry","chapter":"electrochemistry","topic":"Non-electrolytes"}', 3),
  (3824, 870, 'Ethanol mixes with water but does not produce a significant concentration of ions. Classify ethanol and explain your answer.', 'text', 1, 'Classify it according to the particles present in the solution.', '{"why":"Electrolyte classification depends on ion formation, not simply on whether a substance mixes with water.","sol":"Step 1: Identify ethanol as a molecular substance.\nStep 2: State that its molecules remain largely neutral in water.\nStep 3: Relate this to the definition of a non-electrolyte.","steps":["Step 1: Identify ethanol as a molecular substance.","Step 2: State that its molecules remain largely neutral in water.","Step 3: Relate this to the definition of a non-electrolyte."],"options":[],"conceptId":"chemistry_electrochemistry_non_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q5","subject":"chemistry","chapter":"electrochemistry","topic":"Non-electrolytes"}', 4),
  (3825, 870, 'Compare a strong electrolyte, a weak electrolyte and a non-electrolyte in terms of ion formation and electrical conduction.', 'text', 1, 'Compare extensive, partial and insignificant ion formation.', '{"why":"The extent to which mobile ions are produced is central to comparing these three types of substances.","sol":"Step 1: Describe ion formation in a strong electrolyte.\nStep 2: Describe ion formation in a weak electrolyte.\nStep 3: Describe ion formation in a non-electrolyte.\nStep 4: Relate the mobile ions present to their typical electrical conduction.","steps":["Step 1: Describe ion formation in a strong electrolyte.","Step 2: Describe ion formation in a weak electrolyte.","Step 3: Describe ion formation in a non-electrolyte.","Step 4: Relate the mobile ions present to their typical electrical conduction."],"options":[],"conceptId":"chemistry_electrochemistry_non_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q6","subject":"chemistry","chapter":"electrochemistry","topic":"Non-electrolytes"}', 5),
  (3826, 871, 'Define organic chemistry.', 'text', 1, 'Think about the branch of chemistry concerned with carbon compounds.', '{"why":"The definition identifies both the subject matter and the central importance of carbon compounds.","sol":"Step 1: Identify the branch of chemistry being described.\nStep 2: State what types of compounds it studies.","steps":["Step 1: Identify the branch of chemistry being described.","Step 2: State what types of compounds it studies."],"options":[],"conceptId":"chemistry_organic_chemistry_introduction_to_organic_chemistry","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Introduction to Organic Chemistry"}', 0),
  (3827, 871, 'Explain why ethanol, C2H5OH, is not a hydrocarbon.', 'text', 1, 'A hydrocarbon contains only two types of elements.', '{"why":"The presence of oxygen means ethanol does not satisfy the definition of a hydrocarbon.","sol":"Step 1: A hydrocarbon contains only carbon and hydrogen.\nStep 2: Inspect the formula C2H5OH.\nStep 3: Notice that the formula also contains oxygen.","steps":["Step 1: A hydrocarbon contains only carbon and hydrogen.","Step 2: Inspect the formula C2H5OH.","Step 3: Notice that the formula also contains oxygen."],"options":[],"conceptId":"chemistry_organic_chemistry_introduction_to_organic_chemistry","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Introduction to Organic Chemistry"}', 1),
  (3828, 871, 'Give two examples of hydrocarbons and write their formulae.', 'text', 1, 'Use the simplest members of the alkane family.', '{"why":"Both compounds contain carbon and hydrogen only.","sol":"Step 1: Choose methane and ethane.\nStep 2: Write methane as CH4.\nStep 3: Write ethane as C2H6.","steps":["Step 1: Choose methane and ethane.","Step 2: Write methane as CH4.","Step 3: Write ethane as C2H6."],"options":[],"conceptId":"chemistry_organic_chemistry_introduction_to_organic_chemistry","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Introduction to Organic Chemistry"}', 2),
  (3829, 871, 'A learner says, ''Every compound containing carbon is an organic compound.'' Explain why this statement is incorrect, using two examples.', 'text', 1, 'Consider carbon dioxide and calcium carbonate.', '{"why":"Carbon content alone is not sufficient to classify every compound as organic.","sol":"Step 1: Recall that organic chemistry studies many, but not all, carbon compounds.\nStep 2: Identify carbon dioxide, CO2, as conventionally inorganic.\nStep 3: Identify calcium carbonate, CaCO3, as conventionally inorganic.\nStep 4: Use these examples to correct the statement.","steps":["Step 1: Recall that organic chemistry studies many, but not all, carbon compounds.","Step 2: Identify carbon dioxide, CO2, as conventionally inorganic.","Step 3: Identify calcium carbonate, CaCO3, as conventionally inorganic.","Step 4: Use these examples to correct the statement."],"options":[],"conceptId":"chemistry_organic_chemistry_introduction_to_organic_chemistry","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Introduction to Organic Chemistry"}', 3),
  (3830, 871, 'Classify each substance as a hydrocarbon or not a hydrocarbon: CH4, C2H5OH and CO2. Give a reason for each.', 'text', 1, 'Check which elements occur in each formula.', '{"why":"A hydrocarbon must contain carbon and hydrogen only. CO2 is also conventionally classified as inorganic.","sol":"Step 1: CH4 contains carbon and hydrogen only, so it is a hydrocarbon.\nStep 2: C2H5OH contains oxygen, so it is not a hydrocarbon.\nStep 3: CO2 contains oxygen and no hydrogen, so it is not a hydrocarbon.","steps":["Step 1: CH4 contains carbon and hydrogen only, so it is a hydrocarbon.","Step 2: C2H5OH contains oxygen, so it is not a hydrocarbon.","Step 3: CO2 contains oxygen and no hydrogen, so it is not a hydrocarbon."],"options":[],"conceptId":"chemistry_organic_chemistry_introduction_to_organic_chemistry","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Introduction to Organic Chemistry"}', 4),
  (3831, 871, 'A compound contains carbon, hydrogen and oxygen. Can it be an organic compound? Explain using an example.', 'text', 1, 'Think about ethanol or glucose.', '{"why":"Only hydrocarbons are restricted to carbon and hydrogen. Many organic compounds contain other elements.","sol":"Step 1: Organic compounds are not restricted to carbon and hydrogen only.\nStep 2: Choose ethanol, C2H5OH, as an example.\nStep 3: Explain that ethanol contains oxygen but is still an organic compound.","steps":["Step 1: Organic compounds are not restricted to carbon and hydrogen only.","Step 2: Choose ethanol, C2H5OH, as an example.","Step 3: Explain that ethanol contains oxygen but is still an organic compound."],"options":[],"conceptId":"chemistry_organic_chemistry_introduction_to_organic_chemistry","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q6","subject":"chemistry","chapter":"organic_chemistry","topic":"Introduction to Organic Chemistry"}', 5),
  (3832, 871, 'Explain the difference between an organic compound and a hydrocarbon.', 'text', 1, 'One category is broader than the other.', '{"why":"Hydrocarbons form one important group within the wider study of organic chemistry.","sol":"Step 1: Define a hydrocarbon as a compound containing only carbon and hydrogen.\nStep 2: Explain that organic chemistry also studies compounds containing carbon and other elements.\nStep 3: Use ethanol as an example of an organic compound that is not a hydrocarbon.","steps":["Step 1: Define a hydrocarbon as a compound containing only carbon and hydrogen.","Step 2: Explain that organic chemistry also studies compounds containing carbon and other elements.","Step 3: Use ethanol as an example of an organic compound that is not a hydrocarbon."],"options":[],"conceptId":"chemistry_organic_chemistry_introduction_to_organic_chemistry","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q7","subject":"chemistry","chapter":"organic_chemistry","topic":"Introduction to Organic Chemistry"}', 6),
  (3833, 871, 'Glucose has the formula C6H12O6. Explain why it belongs to organic chemistry but is not a hydrocarbon.', 'text', 1, 'Compare the elements in glucose with the definition of a hydrocarbon.', '{"why":"The distinction depends on the elements present, not merely on whether carbon is present.","sol":"Step 1: Glucose contains carbon, so it is a carbon compound studied in organic chemistry.\nStep 2: Its formula contains hydrogen and oxygen as well.\nStep 3: A hydrocarbon must contain only carbon and hydrogen.\nStep 4: Therefore, glucose is not a hydrocarbon.","steps":["Step 1: Glucose contains carbon, so it is a carbon compound studied in organic chemistry.","Step 2: Its formula contains hydrogen and oxygen as well.","Step 3: A hydrocarbon must contain only carbon and hydrogen.","Step 4: Therefore, glucose is not a hydrocarbon."],"options":[],"conceptId":"chemistry_organic_chemistry_introduction_to_organic_chemistry","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q8","subject":"chemistry","chapter":"organic_chemistry","topic":"Introduction to Organic Chemistry"}', 7),
  (3834, 872, 'Define tetravalency.', 'text', 1, 'The prefix tetra- means four.', '{"why":"Carbon commonly forms four covalent bonds in its compounds.","sol":"Step 1: Recognise that valency describes an atom''s combining capacity.\nStep 2: Apply the prefix tetra-, meaning four.","steps":["Step 1: Recognise that valency describes an atom''s combining capacity.","Step 2: Apply the prefix tetra-, meaning four."],"options":[],"conceptId":"chemistry_organic_chemistry_tetravalency_of_carbon","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Tetravalency of Carbon"}', 0),
  (3835, 872, 'Explain why methane has the formula CH4.', 'text', 1, 'Consider the number of bonds carbon and hydrogen commonly form.', '{"why":"The formula reflects the bonding capacities of carbon and hydrogen.","sol":"Step 1: Carbon commonly forms four covalent bonds.\nStep 2: Each hydrogen forms one covalent bond.\nStep 3: One carbon atom can form four single bonds with four hydrogen atoms.","steps":["Step 1: Carbon commonly forms four covalent bonds.","Step 2: Each hydrogen forms one covalent bond.","Step 3: One carbon atom can form four single bonds with four hydrogen atoms."],"options":[],"conceptId":"chemistry_organic_chemistry_tetravalency_of_carbon","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Tetravalency of Carbon"}', 1),
  (3836, 872, 'How many C–H covalent bonds are present in one molecule of methane?', 'text', 1, 'Read the subscript attached to hydrogen in CH4.', '{"why":"Every hydrogen atom is connected to the carbon by one single bond.","sol":"Step 1: The formula contains four hydrogen atoms.\nStep 2: Each hydrogen forms one single bond to carbon.\nStep 3: Therefore, there are four C–H bonds.","steps":["Step 1: The formula contains four hydrogen atoms.","Step 2: Each hydrogen forms one single bond to carbon.","Step 3: Therefore, there are four C–H bonds."],"options":[],"conceptId":"chemistry_organic_chemistry_tetravalency_of_carbon","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Tetravalency of Carbon"}', 2),
  (3837, 872, 'Explain how carbon''s tetravalency is demonstrated by methane, CH4.', 'text', 1, 'Describe how the carbon atom is connected to the hydrogen atoms.', '{"why":"The number of covalent bonds formed by carbon is four.","sol":"Step 1: Methane contains one carbon atom.\nStep 2: It also contains four hydrogen atoms.\nStep 3: Carbon forms one single covalent bond with each hydrogen.\nStep 4: The four bonds demonstrate tetravalency.","steps":["Step 1: Methane contains one carbon atom.","Step 2: It also contains four hydrogen atoms.","Step 3: Carbon forms one single covalent bond with each hydrogen.","Step 4: The four bonds demonstrate tetravalency."],"options":[],"conceptId":"chemistry_organic_chemistry_tetravalency_of_carbon","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Tetravalency of Carbon"}', 3),
  (3838, 872, 'A learner draws methane with carbon bonded to only three hydrogen atoms. Explain what is wrong with the structure.', 'text', 1, 'Check the normal bonding capacity of carbon in methane.', '{"why":"The correct methane structure must show carbon bonded to four hydrogen atoms.","sol":"Step 1: Carbon commonly forms four covalent bonds.\nStep 2: Three C–H bonds account for only three bonds around carbon.\nStep 3: One hydrogen atom and one C–H bond are missing.\nStep 4: The correct formula is CH4.","steps":["Step 1: Carbon commonly forms four covalent bonds.","Step 2: Three C–H bonds account for only three bonds around carbon.","Step 3: One hydrogen atom and one C–H bond are missing.","Step 4: The correct formula is CH4."],"options":[],"conceptId":"chemistry_organic_chemistry_tetravalency_of_carbon","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Tetravalency of Carbon"}', 4),
  (3839, 872, 'Carbon dioxide has the structure O=C=O. Explain how carbon forms four covalent bonds in this molecule.', 'text', 1, 'Remember that a double bond contains two shared pairs of electrons.', '{"why":"A double bond contains two shared electron pairs.","sol":"Step 1: Carbon forms a double bond with one oxygen atom.\nStep 2: A double bond counts as two covalent bonds.\nStep 3: Carbon forms another double bond with the second oxygen.\nStep 4: Two double bonds account for four covalent bonds.","steps":["Step 1: Carbon forms a double bond with one oxygen atom.","Step 2: A double bond counts as two covalent bonds.","Step 3: Carbon forms another double bond with the second oxygen.","Step 4: Two double bonds account for four covalent bonds."],"options":[],"conceptId":"chemistry_organic_chemistry_tetravalency_of_carbon","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q6","subject":"chemistry","chapter":"organic_chemistry","topic":"Tetravalency of Carbon"}', 5),
  (3840, 872, 'State the number of covalent bonds normally formed by carbon and explain why this property is important in organic chemistry.', 'text', 1, 'Connect carbon''s bonding capacity with the variety of carbon compounds.', '{"why":"Tetravalency contributes to the structural diversity of organic compounds.","sol":"Step 1: Carbon normally forms four covalent bonds.\nStep 2: These bonds allow it to join to hydrogen and other elements.\nStep 3: Carbon can also bond to other carbon atoms.\nStep 4: This produces many different molecular structures.","steps":["Step 1: Carbon normally forms four covalent bonds.","Step 2: These bonds allow it to join to hydrogen and other elements.","Step 3: Carbon can also bond to other carbon atoms.","Step 4: This produces many different molecular structures."],"options":[],"conceptId":"chemistry_organic_chemistry_tetravalency_of_carbon","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q7","subject":"chemistry","chapter":"organic_chemistry","topic":"Tetravalency of Carbon"}', 6),
  (3841, 872, 'A carbon atom forms one double bond with oxygen and two single bonds with hydrogen. Count its covalent bonds and explain whether it satisfies tetravalency.', 'text', 1, 'Count a double bond as two bonds and each single bond as one.', '{"why":"The total is four when the double bond is counted as two bonds.","sol":"Step 1: The C=O double bond counts as two covalent bonds.\nStep 2: The two C–H single bonds count as two more.\nStep 3: Total bonds = 2 + 1 + 1 = 4.\nStep 4: The carbon satisfies tetravalency.","steps":["Step 1: The C=O double bond counts as two covalent bonds.","Step 2: The two C–H single bonds count as two more.","Step 3: Total bonds = 2 + 1 + 1 = 4.","Step 4: The carbon satisfies tetravalency."],"options":[],"conceptId":"chemistry_organic_chemistry_tetravalency_of_carbon","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q8","subject":"chemistry","chapter":"organic_chemistry","topic":"Tetravalency of Carbon"}', 7),
  (3842, 873, 'Define catenation.', 'text', 1, 'Focus on bonds between atoms of the same element.', '{"why":"Catenation explains how atoms of one element can build connected structures.","sol":"Step 1: Identify that the atoms belong to the same element.\nStep 2: State that they bond to one another to form structures.","steps":["Step 1: Identify that the atoms belong to the same element.","Step 2: State that they bond to one another to form structures."],"options":[],"conceptId":"chemistry_organic_chemistry_catenation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Catenation"}', 0),
  (3843, 873, 'Name three structures that carbon atoms can form through catenation.', 'text', 1, 'Consider open structures and closed structures.', '{"why":"These are three common arrangements of carbon atoms.","sol":"Step 1: Carbon atoms can join in an unbranched sequence.\nStep 2: They can form a chain with side branches.\nStep 3: They can connect to form a closed ring.","steps":["Step 1: Carbon atoms can join in an unbranched sequence.","Step 2: They can form a chain with side branches.","Step 3: They can connect to form a closed ring."],"options":[],"conceptId":"chemistry_organic_chemistry_catenation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Catenation"}', 1),
  (3844, 873, 'Explain why catenation is important in organic chemistry.', 'text', 1, 'Think about how many structures can be formed from carbon atoms.', '{"why":"The ability to form different carbon frameworks creates structural diversity.","sol":"Step 1: Carbon atoms can bond to other carbon atoms.\nStep 2: The chains can differ in length and arrangement.\nStep 3: This produces a large variety of compounds.","steps":["Step 1: Carbon atoms can bond to other carbon atoms.","Step 2: The chains can differ in length and arrangement.","Step 3: This produces a large variety of compounds."],"options":[],"conceptId":"chemistry_organic_chemistry_catenation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Catenation"}', 2),
  (3845, 873, 'Explain how a chain containing six carbon atoms demonstrates catenation.', 'text', 1, 'Focus on the bonds connecting the six carbon atoms.', '{"why":"Catenation concerns bonding between atoms of the same element.","sol":"Step 1: The structure contains six carbon atoms.\nStep 2: The carbon atoms are connected by carbon-carbon bonds.\nStep 3: Bonding between atoms of the same element demonstrates catenation.","steps":["Step 1: The structure contains six carbon atoms.","Step 2: The carbon atoms are connected by carbon-carbon bonds.","Step 3: Bonding between atoms of the same element demonstrates catenation."],"options":[],"conceptId":"chemistry_organic_chemistry_catenation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Catenation"}', 3),
  (3846, 873, 'A compound has a carbon framework that forms a closed ring. Explain why this is an example of catenation.', 'text', 1, 'A ring is formed when the chain closes.', '{"why":"Catenation can produce rings as well as open chains.","sol":"Step 1: Identify the carbon atoms in the ring.\nStep 2: Observe that each carbon is connected to other carbon atoms.\nStep 3: The carbon-carbon bonds create a closed structure.","steps":["Step 1: Identify the carbon atoms in the ring.","Step 2: Observe that each carbon is connected to other carbon atoms.","Step 3: The carbon-carbon bonds create a closed structure."],"options":[],"conceptId":"chemistry_organic_chemistry_catenation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Catenation"}', 4),
  (3847, 873, 'Explain why carbon''s ability to form both straight and branched chains increases the number of possible organic compounds.', 'text', 1, 'Consider how the arrangement changes even when the number of carbon atoms is unchanged.', '{"why":"Different carbon frameworks provide different molecular structures.","sol":"Step 1: Carbon atoms can form chains of different lengths.\nStep 2: A chain can also have branches.\nStep 3: Different arrangements can produce different compounds.\nStep 4: Therefore, more structures are possible.","steps":["Step 1: Carbon atoms can form chains of different lengths.","Step 2: A chain can also have branches.","Step 3: Different arrangements can produce different compounds.","Step 4: Therefore, more structures are possible."],"options":[],"conceptId":"chemistry_organic_chemistry_catenation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q6","subject":"chemistry","chapter":"organic_chemistry","topic":"Catenation"}', 5),
  (3848, 873, 'Is catenation exclusive to carbon? Explain your answer.', 'text', 1, 'Distinguish between extensive catenation and the ability to catenate at all.', '{"why":"Carbon is notable for the extent and variety of its stable structures, not because no other element can catenate.","sol":"Step 1: Catenation means bonding between atoms of the same element.\nStep 2: Carbon shows extensive catenation.\nStep 3: Some other elements can also form bonds with themselves.\nStep 4: Therefore, catenation is not exclusive to carbon.","steps":["Step 1: Catenation means bonding between atoms of the same element.","Step 2: Carbon shows extensive catenation.","Step 3: Some other elements can also form bonds with themselves.","Step 4: Therefore, catenation is not exclusive to carbon."],"options":[],"conceptId":"chemistry_organic_chemistry_catenation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q7","subject":"chemistry","chapter":"organic_chemistry","topic":"Catenation"}', 6),
  (3849, 873, 'Explain the difference between catenation and tetravalency.', 'text', 1, 'One describes self-linking; the other describes the number of bonds.', '{"why":"The terms describe different properties of carbon.","sol":"Step 1: Catenation describes atoms of the same element bonding to one another.\nStep 2: Tetravalency describes the ability of carbon to form four covalent bonds.\nStep 3: A carbon chain illustrates catenation, while methane illustrates tetravalency.","steps":["Step 1: Catenation describes atoms of the same element bonding to one another.","Step 2: Tetravalency describes the ability of carbon to form four covalent bonds.","Step 3: A carbon chain illustrates catenation, while methane illustrates tetravalency."],"options":[],"conceptId":"chemistry_organic_chemistry_catenation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q8","subject":"chemistry","chapter":"organic_chemistry","topic":"Catenation"}', 7),
  (3850, 874, 'Define a hydrocarbon.', 'text', 1, 'State the only two elements it contains.', '{"why":"The presence of any other element means the compound is not a hydrocarbon.","sol":"Step 1: Identify the elements in a hydrocarbon.\nStep 2: State that no other elements are present.","steps":["Step 1: Identify the elements in a hydrocarbon.","Step 2: State that no other elements are present."],"options":[],"conceptId":"chemistry_organic_chemistry_hydrocarbons","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Hydrocarbons"}', 0),
  (3851, 874, 'Classify a hydrocarbon containing only C–C single bonds in an open chain as saturated or unsaturated.', 'text', 1, 'Look for the presence or absence of multiple carbon-carbon bonds.', '{"why":"Saturated hydrocarbons have no carbon-carbon double or triple bonds.","sol":"Step 1: The compound contains only C–C single bonds.\nStep 2: There are no C=C or C≡C bonds.\nStep 3: An open-chain hydrocarbon with only single carbon-carbon bonds is saturated.","steps":["Step 1: The compound contains only C–C single bonds.","Step 2: There are no C=C or C≡C bonds.","Step 3: An open-chain hydrocarbon with only single carbon-carbon bonds is saturated."],"options":[],"conceptId":"chemistry_organic_chemistry_hydrocarbons","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Hydrocarbons"}', 1),
  (3852, 874, 'Name the hydrocarbon group associated with a carbon-carbon triple bond.', 'text', 1, 'Distinguish the double-bond and triple-bond families.', '{"why":"The defining bond in this family is the carbon-carbon triple bond.","sol":"Step 1: A C=C bond is characteristic of the alkene group.\nStep 2: A C≡C bond is characteristic of the alkyne group.\nStep 3: Therefore, the group is alkynes.","steps":["Step 1: A C=C bond is characteristic of the alkene group.","Step 2: A C≡C bond is characteristic of the alkyne group.","Step 3: Therefore, the group is alkynes."],"options":[],"conceptId":"chemistry_organic_chemistry_hydrocarbons","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Hydrocarbons"}', 2),
  (3853, 874, 'A substance has the formula C3H8. Explain why it is a hydrocarbon.', 'text', 1, 'Check which elements are present in the formula.', '{"why":"Hydrocarbons are defined by the elements they contain.","sol":"Step 1: The formula contains carbon, C.\nStep 2: It also contains hydrogen, H.\nStep 3: No other element appears.\nStep 4: Therefore, it satisfies the definition of a hydrocarbon.","steps":["Step 1: The formula contains carbon, C.","Step 2: It also contains hydrogen, H.","Step 3: No other element appears.","Step 4: Therefore, it satisfies the definition of a hydrocarbon."],"options":[],"conceptId":"chemistry_organic_chemistry_hydrocarbons","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Hydrocarbons"}', 3),
  (3854, 874, 'A learner classifies C2H5OH as a hydrocarbon because most of its formula contains carbon and hydrogen. Explain the error.', 'text', 1, 'One atom of another element is enough to disqualify it.', '{"why":"A compound must contain only carbon and hydrogen to be a hydrocarbon.","sol":"Step 1: A hydrocarbon must contain only carbon and hydrogen.\nStep 2: C2H5OH contains oxygen.\nStep 3: Therefore, it is not a hydrocarbon.","steps":["Step 1: A hydrocarbon must contain only carbon and hydrogen.","Step 2: C2H5OH contains oxygen.","Step 3: Therefore, it is not a hydrocarbon."],"options":[],"conceptId":"chemistry_organic_chemistry_hydrocarbons","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Hydrocarbons"}', 4),
  (3855, 874, 'Distinguish between saturated and unsaturated hydrocarbons, giving one example of each.', 'text', 1, 'Compare the carbon-carbon bonds.', '{"why":"The classification depends on the types of carbon-carbon bonds present.","sol":"Step 1: Saturated hydrocarbons have only carbon-carbon single bonds in their carbon framework.\nStep 2: Unsaturated hydrocarbons contain a carbon-carbon double or triple bond.\nStep 3: Ethane, C2H6, is a saturated example.\nStep 4: Ethene, C2H4, is an unsaturated example.","steps":["Step 1: Saturated hydrocarbons have only carbon-carbon single bonds in their carbon framework.","Step 2: Unsaturated hydrocarbons contain a carbon-carbon double or triple bond.","Step 3: Ethane, C2H6, is a saturated example.","Step 4: Ethene, C2H4, is an unsaturated example."],"options":[],"conceptId":"chemistry_organic_chemistry_hydrocarbons","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q6","subject":"chemistry","chapter":"organic_chemistry","topic":"Hydrocarbons"}', 5),
  (3856, 874, 'A hydrocarbon contains a C=C double bond in an open chain and no other carbon-carbon multiple bonds. Name its family and explain why it is unsaturated.', 'text', 1, 'Identify the family defined by the double bond.', '{"why":"The presence of a C=C bond distinguishes an alkene from an alkane.","sol":"Step 1: A carbon-carbon double bond is written C=C.\nStep 2: The introductory hydrocarbon family with this bond is the alkenes.\nStep 3: The double bond means the compound is not saturated with hydrogen relative to the corresponding alkane.","steps":["Step 1: A carbon-carbon double bond is written C=C.","Step 2: The introductory hydrocarbon family with this bond is the alkenes.","Step 3: The double bond means the compound is not saturated with hydrogen relative to the corresponding alkane."],"options":[],"conceptId":"chemistry_organic_chemistry_hydrocarbons","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q7","subject":"chemistry","chapter":"organic_chemistry","topic":"Hydrocarbons"}', 6),
  (3857, 874, 'Explain why the molecular formula C4H8 alone is not enough to prove that a compound is an alkene.', 'text', 1, 'Think of another type of hydrocarbon that can have the same general formula.', '{"why":"Different hydrocarbon structures can share the same molecular formula.","sol":"Step 1: An open-chain alkene with one double bond can have formula CnH2n.\nStep 2: For n = 4, this gives C4H8.\nStep 3: A cycloalkane can also have formula CnH2n.\nStep 4: Therefore, the structure must be considered.","steps":["Step 1: An open-chain alkene with one double bond can have formula CnH2n.","Step 2: For n = 4, this gives C4H8.","Step 3: A cycloalkane can also have formula CnH2n.","Step 4: Therefore, the structure must be considered."],"options":[],"conceptId":"chemistry_organic_chemistry_hydrocarbons","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q8","subject":"chemistry","chapter":"organic_chemistry","topic":"Hydrocarbons"}', 7),
  (3858, 875, 'Define an alkane.', 'text', 1, 'Include both saturation and the type of carbon-carbon bond.', '{"why":"This definition distinguishes alkanes from hydrocarbons with double or triple bonds.","sol":"Step 1: State that alkanes are hydrocarbons.\nStep 2: State that they are saturated.\nStep 3: Specify that open-chain alkanes contain only C–C single bonds.","steps":["Step 1: State that alkanes are hydrocarbons.","Step 2: State that they are saturated.","Step 3: Specify that open-chain alkanes contain only C–C single bonds."],"options":[],"conceptId":"chemistry_organic_chemistry_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkanes"}', 0),
  (3859, 875, 'Name the alkane containing four carbon atoms.', 'text', 1, 'Use the four-carbon prefix and the alkane ending.', '{"why":"The prefix identifies the number of carbon atoms and the suffix identifies the family.","sol":"Step 1: Four carbon atoms use the prefix but-.\nStep 2: The alkane ending is -ane.\nStep 3: Combine them to form butane.","steps":["Step 1: Four carbon atoms use the prefix but-.","Step 2: The alkane ending is -ane.","Step 3: Combine them to form butane."],"options":[],"conceptId":"chemistry_organic_chemistry_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkanes"}', 1),
  (3860, 875, 'Explain why ethane is described as saturated.', 'text', 1, 'Look at the bond joining its carbon atoms.', '{"why":"Saturated hydrocarbons contain only single carbon-carbon bonds.","sol":"Step 1: Ethane has a C–C single bond.\nStep 2: It has no carbon-carbon double or triple bond.\nStep 3: It therefore has the maximum hydrogen count for an open-chain hydrocarbon with two carbon atoms.","steps":["Step 1: Ethane has a C–C single bond.","Step 2: It has no carbon-carbon double or triple bond.","Step 3: It therefore has the maximum hydrogen count for an open-chain hydrocarbon with two carbon atoms."],"options":[],"conceptId":"chemistry_organic_chemistry_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkanes"}', 2),
  (3861, 875, 'A hydrocarbon contains three carbon atoms in an open chain and only C–C single bonds. Identify its family and name the compound.', 'text', 1, 'Use the three-carbon prefix and identify the bond type.', '{"why":"Propane is the three-carbon member of the alkane family.","sol":"Step 1: The compound contains carbon and hydrogen only.\nStep 2: It is an open chain with only C–C single bonds.\nStep 3: This makes it an alkane.\nStep 4: Three carbon atoms use the prefix prop-.\nStep 5: The compound is propane.","steps":["Step 1: The compound contains carbon and hydrogen only.","Step 2: It is an open chain with only C–C single bonds.","Step 3: This makes it an alkane.","Step 4: Three carbon atoms use the prefix prop-.","Step 5: The compound is propane."],"options":[],"conceptId":"chemistry_organic_chemistry_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkanes"}', 3),
  (3862, 875, 'Write the names and molecular formulae of the first three alkanes.', 'text', 1, 'Start with one carbon and increase the carbon count by one each time.', '{"why":"Each successive alkane has one additional carbon atom and two additional hydrogen atoms.","sol":"Step 1: One carbon gives methane, CH4.\nStep 2: Two carbons give ethane, C2H6.\nStep 3: Three carbons give propane, C3H8.","steps":["Step 1: One carbon gives methane, CH4.","Step 2: Two carbons give ethane, C2H6.","Step 3: Three carbons give propane, C3H8."],"options":[],"conceptId":"chemistry_organic_chemistry_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkanes"}', 4),
  (3863, 875, 'A learner says ethene is an alkane because it contains only carbon and hydrogen. Explain why the classification is wrong.', 'text', 1, 'Being a hydrocarbon is not the only requirement for being an alkane.', '{"why":"Alkanes and alkenes are both hydrocarbons, but their carbon-carbon bonds differ.","sol":"Step 1: Ethene is a hydrocarbon because it contains carbon and hydrogen only.\nStep 2: An alkane must have only single carbon-carbon bonds in an open chain.\nStep 3: Ethene contains a C=C double bond.\nStep 4: Therefore, ethene is an alkene.","steps":["Step 1: Ethene is a hydrocarbon because it contains carbon and hydrogen only.","Step 2: An alkane must have only single carbon-carbon bonds in an open chain.","Step 3: Ethene contains a C=C double bond.","Step 4: Therefore, ethene is an alkene."],"options":[],"conceptId":"chemistry_organic_chemistry_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q6","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkanes"}', 5),
  (3864, 875, 'Explain the difference between a saturated alkane and an unsaturated alkene.', 'text', 1, 'Compare the carbon-carbon bonds in each family.', '{"why":"The bond type is the main distinction between these two families.","sol":"Step 1: Alkanes contain only C–C single bonds in an open chain.\nStep 2: Alkenes contain at least one C=C double bond.\nStep 3: Alkanes are saturated, while alkenes are unsaturated.","steps":["Step 1: Alkanes contain only C–C single bonds in an open chain.","Step 2: Alkenes contain at least one C=C double bond.","Step 3: Alkanes are saturated, while alkenes are unsaturated."],"options":[],"conceptId":"chemistry_organic_chemistry_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q7","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkanes"}', 6),
  (3865, 875, 'Name the alkane with five carbon atoms and explain how its name is formed.', 'text', 1, 'Use the five-carbon prefix and the alkane suffix.', '{"why":"Organic names often communicate both the carbon count and the family.","sol":"Step 1: Five carbon atoms use the prefix pent-.\nStep 2: Alkanes use the suffix -ane.\nStep 3: Combine the parts to form pentane.","steps":["Step 1: Five carbon atoms use the prefix pent-.","Step 2: Alkanes use the suffix -ane.","Step 3: Combine the parts to form pentane."],"options":[],"conceptId":"chemistry_organic_chemistry_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q8","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkanes"}', 7),
  (3866, 876, 'Define an alkene.', 'text', 1, 'Focus on the carbon-carbon bond that defines the family.', '{"why":"The C=C bond distinguishes alkenes from alkanes.","sol":"Step 1: State that alkenes are hydrocarbons.\nStep 2: Identify the carbon-carbon double bond.\nStep 3: Describe them as unsaturated.","steps":["Step 1: State that alkenes are hydrocarbons.","Step 2: Identify the carbon-carbon double bond.","Step 3: Describe them as unsaturated."],"options":[],"conceptId":"chemistry_organic_chemistry_alkenes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkenes"}', 0),
  (3867, 876, 'Name the simplest alkene and give its molecular formula.', 'text', 1, 'The smallest possible open-chain alkene must contain a double bond between two carbon atoms.', '{"why":"Ethene is the smallest alkene because a C=C bond needs two carbon atoms.","sol":"Step 1: A carbon-carbon double bond requires two carbon atoms.\nStep 2: The two-carbon prefix is eth-.\nStep 3: The alkene suffix is -ene.\nStep 4: The formula is C2H4.","steps":["Step 1: A carbon-carbon double bond requires two carbon atoms.","Step 2: The two-carbon prefix is eth-.","Step 3: The alkene suffix is -ene.","Step 4: The formula is C2H4."],"options":[],"conceptId":"chemistry_organic_chemistry_alkenes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkenes"}', 1),
  (3868, 876, 'Explain why propene is an unsaturated hydrocarbon.', 'text', 1, 'Consider its carbon-carbon bond.', '{"why":"Unsaturation in this family is associated with the C=C bond.","sol":"Step 1: Propene contains only carbon and hydrogen, so it is a hydrocarbon.\nStep 2: It contains a C=C double bond.\nStep 3: A hydrocarbon with a carbon-carbon double bond is unsaturated.","steps":["Step 1: Propene contains only carbon and hydrogen, so it is a hydrocarbon.","Step 2: It contains a C=C double bond.","Step 3: A hydrocarbon with a carbon-carbon double bond is unsaturated."],"options":[],"conceptId":"chemistry_organic_chemistry_alkenes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkenes"}', 2),
  (3869, 876, 'Explain how the structure of ethene differs from that of ethane.', 'text', 1, 'Compare the bond between their two carbon atoms.', '{"why":"The carbon-carbon bond type distinguishes the two families.","sol":"Step 1: Ethane has a single C–C bond.\nStep 2: Ethene has a double C=C bond.\nStep 3: Ethane is saturated, while ethene is unsaturated.","steps":["Step 1: Ethane has a single C–C bond.","Step 2: Ethene has a double C=C bond.","Step 3: Ethane is saturated, while ethene is unsaturated."],"options":[],"conceptId":"chemistry_organic_chemistry_alkenes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkenes"}', 3),
  (3870, 876, 'Write the names and formulae of the first three open-chain alkenes with one double bond.', 'text', 1, 'Begin at two carbon atoms because a double bond needs two carbons.', '{"why":"For this series, each additional carbon atom adds two hydrogen atoms to the molecular formula.","sol":"Step 1: Two carbons: ethene, C2H4.\nStep 2: Three carbons: propene, C3H6.\nStep 3: Four carbons: butene, C4H8.","steps":["Step 1: Two carbons: ethene, C2H4.","Step 2: Three carbons: propene, C3H6.","Step 3: Four carbons: butene, C4H8."],"options":[],"conceptId":"chemistry_organic_chemistry_alkenes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkenes"}', 4),
  (3871, 876, 'A compound has four carbon atoms and a C=C double bond in an open chain. Give its family name and explain why a more precise name may be necessary.', 'text', 1, 'The double bond can occupy different positions.', '{"why":"Different positions of a double bond can produce different compounds.","sol":"Step 1: Four carbon atoms use the prefix but-.\nStep 2: A C=C bond places the compound in the alkene family.\nStep 3: The double bond can occupy different positions in the chain.\nStep 4: A locant may be needed to identify its position.","steps":["Step 1: Four carbon atoms use the prefix but-.","Step 2: A C=C bond places the compound in the alkene family.","Step 3: The double bond can occupy different positions in the chain.","Step 4: A locant may be needed to identify its position."],"options":[],"conceptId":"chemistry_organic_chemistry_alkenes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q6","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkenes"}', 5),
  (3872, 876, 'Explain why C4H8 does not always identify a compound as an alkene.', 'text', 1, 'Consider cyclic hydrocarbons.', '{"why":"Different structures can share the same molecular formula.","sol":"Step 1: An open-chain alkene with one double bond follows CnH2n.\nStep 2: Substituting n = 4 gives C4H8.\nStep 3: A cycloalkane can also have formula CnH2n.\nStep 4: Therefore, the molecular formula does not uniquely determine the structure.","steps":["Step 1: An open-chain alkene with one double bond follows CnH2n.","Step 2: Substituting n = 4 gives C4H8.","Step 3: A cycloalkane can also have formula CnH2n.","Step 4: Therefore, the molecular formula does not uniquely determine the structure."],"options":[],"conceptId":"chemistry_organic_chemistry_alkenes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q7","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkenes"}', 6),
  (3873, 876, 'A learner says the suffix -ene means that a compound contains a carbon-carbon triple bond. Correct the statement.', 'text', 1, 'Compare the suffixes used for alkenes and alkynes.', '{"why":"The suffix helps identify the type of carbon-carbon bond.","sol":"Step 1: The suffix -ene indicates an alkene.\nStep 2: Alkenes contain a C=C double bond.\nStep 3: The suffix -yne indicates an alkyne with a C≡C triple bond.","steps":["Step 1: The suffix -ene indicates an alkene.","Step 2: Alkenes contain a C=C double bond.","Step 3: The suffix -yne indicates an alkyne with a C≡C triple bond."],"options":[],"conceptId":"chemistry_organic_chemistry_alkenes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q8","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkenes"}', 7),
  (3874, 877, 'Define an alkyne.', 'text', 1, 'Identify the type of carbon-carbon bond.', '{"why":"The C≡C bond distinguishes an alkyne from an alkene.","sol":"Step 1: State that alkynes are hydrocarbons.\nStep 2: Identify the carbon-carbon triple bond.\nStep 3: State that they are unsaturated.","steps":["Step 1: State that alkynes are hydrocarbons.","Step 2: Identify the carbon-carbon triple bond.","Step 3: State that they are unsaturated."],"options":[],"conceptId":"chemistry_organic_chemistry_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkynes"}', 0),
  (3875, 877, 'Name the simplest alkyne and give its formula.', 'text', 1, 'A triple bond needs two carbon atoms.', '{"why":"Ethyne is the simplest alkyne because it contains the minimum two carbon atoms needed for a triple bond.","sol":"Step 1: The molecule has two carbon atoms.\nStep 2: The two-carbon prefix is eth-.\nStep 3: The alkyne suffix is -yne.\nStep 4: The formula is C2H2.","steps":["Step 1: The molecule has two carbon atoms.","Step 2: The two-carbon prefix is eth-.","Step 3: The alkyne suffix is -yne.","Step 4: The formula is C2H2."],"options":[],"conceptId":"chemistry_organic_chemistry_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkynes"}', 1),
  (3876, 877, 'Explain why ethyne is unsaturated.', 'text', 1, 'Look at the bond connecting the two carbon atoms.', '{"why":"The triple bond is the defining feature of an alkyne.","sol":"Step 1: Ethyne contains a C≡C triple bond.\nStep 2: A triple bond is a carbon-carbon multiple bond.\nStep 3: Hydrocarbons with a carbon-carbon multiple bond are unsaturated.","steps":["Step 1: Ethyne contains a C≡C triple bond.","Step 2: A triple bond is a carbon-carbon multiple bond.","Step 3: Hydrocarbons with a carbon-carbon multiple bond are unsaturated."],"options":[],"conceptId":"chemistry_organic_chemistry_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkynes"}', 2),
  (3877, 877, 'Explain how ethyne differs from ethene.', 'text', 1, 'Compare the number of shared electron pairs in their carbon-carbon bonds.', '{"why":"The number of shared electron pairs differs between double and triple bonds.","sol":"Step 1: Ethene contains a C=C double bond.\nStep 2: Ethyne contains a C≡C triple bond.\nStep 3: Ethene belongs to the alkenes; ethyne belongs to the alkynes.","steps":["Step 1: Ethene contains a C=C double bond.","Step 2: Ethyne contains a C≡C triple bond.","Step 3: Ethene belongs to the alkenes; ethyne belongs to the alkynes."],"options":[],"conceptId":"chemistry_organic_chemistry_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkynes"}', 3),
  (3878, 877, 'Write the names and formulae of ethyne, propyne and butyne.', 'text', 1, 'Use the formula for open-chain alkynes with one triple bond.', '{"why":"These are successive members of the open-chain alkyne series.","sol":"Step 1: Ethyne has two carbons: C2H2.\nStep 2: Propyne has three carbons: C3H4.\nStep 3: Butyne has four carbons: C4H6.","steps":["Step 1: Ethyne has two carbons: C2H2.","Step 2: Propyne has three carbons: C3H4.","Step 3: Butyne has four carbons: C4H6."],"options":[],"conceptId":"chemistry_organic_chemistry_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkynes"}', 4),
  (3879, 877, 'A four-carbon open-chain hydrocarbon contains one triple bond. Name its family and explain why its full name may need a number.', 'text', 1, 'The triple bond may begin at different carbon positions.', '{"why":"The position of the triple bond can distinguish structural isomers.","sol":"Step 1: Four carbon atoms use the prefix but-.\nStep 2: A triple bond indicates the alkyne family.\nStep 3: The suffix is -yne.\nStep 4: A number may be needed to indicate the triple-bond position.","steps":["Step 1: Four carbon atoms use the prefix but-.","Step 2: A triple bond indicates the alkyne family.","Step 3: The suffix is -yne.","Step 4: A number may be needed to indicate the triple-bond position."],"options":[],"conceptId":"chemistry_organic_chemistry_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q6","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkynes"}', 5),
  (3880, 877, 'Explain why the suffix -yne is used for ethyne but not ethene.', 'text', 1, 'Each suffix signals a different type of carbon-carbon bond.', '{"why":"The suffix identifies the type of multiple bond.","sol":"Step 1: Ethyne contains a carbon-carbon triple bond.\nStep 2: The suffix -yne identifies the alkyne family.\nStep 3: Ethene contains a double bond and uses -ene.","steps":["Step 1: Ethyne contains a carbon-carbon triple bond.","Step 2: The suffix -yne identifies the alkyne family.","Step 3: Ethene contains a double bond and uses -ene."],"options":[],"conceptId":"chemistry_organic_chemistry_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q7","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkynes"}', 6),
  (3881, 877, 'Explain why C3H4 can fit the formula of an open-chain alkyne with one triple bond, but the formula alone does not fully establish the structure.', 'text', 1, 'Use the general formula, then distinguish a formula from a structural formula.', '{"why":"A structural formula is needed to show the arrangement of atoms and bonds.","sol":"Step 1: The formula for this alkyne family is CnH2n−2.\nStep 2: Substitute n = 3: H = 2(3) − 2 = 4.\nStep 3: This gives C3H4.\nStep 4: A molecular formula gives atom counts but does not always show how atoms are connected.","steps":["Step 1: The formula for this alkyne family is CnH2n−2.","Step 2: Substitute n = 3: H = 2(3) − 2 = 4.","Step 3: This gives C3H4.","Step 4: A molecular formula gives atom counts but does not always show how atoms are connected."],"options":[],"conceptId":"chemistry_organic_chemistry_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q8","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkynes"}', 7),
  (3882, 878, 'Define a homologous series.', 'text', 1, 'Describe a family of related organic compounds.', '{"why":"The regular molecular pattern is a defining feature of a homologous series.","sol":"Step 1: State that it is a family of organic compounds.\nStep 2: Mention a shared functional group where applicable and a common general formula.\nStep 3: Mention the regular difference between successive members.","steps":["Step 1: State that it is a family of organic compounds.","Step 2: Mention a shared functional group where applicable and a common general formula.","Step 3: Mention the regular difference between successive members."],"options":[],"conceptId":"chemistry_organic_chemistry_homologous_series","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Homologous Series"}', 0),
  (3883, 878, 'What is the difference in molecular formula between successive members of a homologous series?', 'text', 1, 'Compare one member with the next.', '{"why":"This repeated difference creates the regular pattern in a homologous series.","sol":"Step 1: The next member has one additional carbon atom.\nStep 2: It also has two additional hydrogen atoms.\nStep 3: The difference is CH2.","steps":["Step 1: The next member has one additional carbon atom.","Step 2: It also has two additional hydrogen atoms.","Step 3: The difference is CH2."],"options":[],"conceptId":"chemistry_organic_chemistry_homologous_series","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Homologous Series"}', 1),
  (3884, 878, 'Show that ethane, C2H6, and propane, C3H8, differ by CH2.', 'text', 1, 'Subtract the atom counts in the smaller formula from those in the larger formula.', '{"why":"The formulae differ by exactly one CH2 unit.","sol":"Step 1: Carbon difference: 3 − 2 = 1.\nStep 2: Hydrogen difference: 8 − 6 = 2.\nStep 3: The difference is one carbon and two hydrogen atoms.","steps":["Step 1: Carbon difference: 3 − 2 = 1.","Step 2: Hydrogen difference: 8 − 6 = 2.","Step 3: The difference is one carbon and two hydrogen atoms."],"options":[],"conceptId":"chemistry_organic_chemistry_homologous_series","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Homologous Series"}', 2),
  (3885, 878, 'Explain why methane, ethane and propane belong to the same homologous series.', 'text', 1, 'Consider their family, formula pattern and successive differences.', '{"why":"The same regular molecular pattern links all members of the series.","sol":"Step 1: Methane, ethane and propane are all alkanes.\nStep 2: They follow the alkane general formula CnH2n+2.\nStep 3: Methane and ethane differ by CH2.\nStep 4: Ethane and propane also differ by CH2.","steps":["Step 1: Methane, ethane and propane are all alkanes.","Step 2: They follow the alkane general formula CnH2n+2.","Step 3: Methane and ethane differ by CH2.","Step 4: Ethane and propane also differ by CH2."],"options":[],"conceptId":"chemistry_organic_chemistry_homologous_series","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Homologous Series"}', 3),
  (3886, 878, 'Determine the next member of the alkane series after butane, C4H10. Give its name and formula.', 'text', 1, 'Add one carbon atom and two hydrogen atoms.', '{"why":"Successive alkanes differ by CH2.","sol":"Step 1: Start with C4H10.\nStep 2: Add CH2 to obtain C5H12.\nStep 3: The five-carbon alkane is pentane.","steps":["Step 1: Start with C4H10.","Step 2: Add CH2 to obtain C5H12.","Step 3: The five-carbon alkane is pentane."],"options":[],"conceptId":"chemistry_organic_chemistry_homologous_series","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Homologous Series"}', 4),
  (3887, 878, 'Explain the meaning of the statement that members of a homologous series have similar chemical properties.', 'text', 1, 'Similar does not mean every physical property or measurement is identical.', '{"why":"The shared structure explains the common chemical behaviour.","sol":"Step 1: Members share the characteristic bonding pattern of the family.\nStep 2: This gives them similar chemical behaviour.\nStep 3: Their reaction rates or physical properties may still vary with structure and conditions.","steps":["Step 1: Members share the characteristic bonding pattern of the family.","Step 2: This gives them similar chemical behaviour.","Step 3: Their reaction rates or physical properties may still vary with structure and conditions."],"options":[],"conceptId":"chemistry_organic_chemistry_homologous_series","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q6","subject":"chemistry","chapter":"organic_chemistry","topic":"Homologous Series"}', 5),
  (3888, 878, 'Ethane is C2H6 and the next member is C3H8. Use the formulae to explain the CH2 pattern.', 'text', 1, 'Compare the change in the number of carbon and hydrogen atoms.', '{"why":"This is the characteristic formula difference in a homologous series.","sol":"Step 1: Carbon increases from 2 to 3, a change of 1.\nStep 2: Hydrogen increases from 6 to 8, a change of 2.\nStep 3: The difference is CH2.","steps":["Step 1: Carbon increases from 2 to 3, a change of 1.","Step 2: Hydrogen increases from 6 to 8, a change of 2.","Step 3: The difference is CH2."],"options":[],"conceptId":"chemistry_organic_chemistry_homologous_series","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q7","subject":"chemistry","chapter":"organic_chemistry","topic":"Homologous Series"}', 6),
  (3889, 878, 'State two characteristics of a homologous series other than the fact that successive members differ by CH2.', 'text', 1, 'Consider the general formula, chemical behaviour and physical trends.', '{"why":"Several related structural and property patterns characterise a homologous series.","sol":"Step 1: Members follow the same general formula.\nStep 2: Members have similar chemical properties.\nStep 3: Physical properties generally change gradually with molecular size.","steps":["Step 1: Members follow the same general formula.","Step 2: Members have similar chemical properties.","Step 3: Physical properties generally change gradually with molecular size."],"options":[],"conceptId":"chemistry_organic_chemistry_homologous_series","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q8","subject":"chemistry","chapter":"organic_chemistry","topic":"Homologous Series"}', 7),
  (3890, 879, 'State the general formula for open-chain alkanes.', 'text', 1, 'The hydrogen subscript depends on the number of carbon atoms.', '{"why":"The formula describes the molecular formula pattern for open-chain alkanes.","sol":"Step 1: Let n represent the number of carbon atoms.\nStep 2: Use 2n + 2 for the hydrogen count.","steps":["Step 1: Let n represent the number of carbon atoms.","Step 2: Use 2n + 2 for the hydrogen count."],"options":[],"conceptId":"chemistry_organic_chemistry_general_formula_of_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"General Formula of Alkanes"}', 0),
  (3891, 879, 'Calculate the molecular formula of an open-chain alkane with five carbon atoms.', 'text', 1, 'Substitute n = 5 into H = 2n + 2.', '{"why":"Five carbon atoms correspond to twelve hydrogen atoms in an open-chain alkane.","sol":"Step 1: n = 5.\nStep 2: H = 2(5) + 2.\nStep 3: H = 10 + 2 = 12.","steps":["Step 1: n = 5.","Step 2: H = 2(5) + 2.","Step 3: H = 10 + 2 = 12."],"options":[],"conceptId":"chemistry_organic_chemistry_general_formula_of_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"General Formula of Alkanes"}', 1),
  (3892, 879, 'Verify whether C3H8 fits the general formula of alkanes.', 'text', 1, 'Substitute n = 3 and compare the calculated hydrogen count.', '{"why":"The calculated hydrogen count matches the formula C3H8.","sol":"Step 1: n = 3.\nStep 2: H = 2(3) + 2 = 8.\nStep 3: The formula predicts eight hydrogen atoms.","steps":["Step 1: n = 3.","Step 2: H = 2(3) + 2 = 8.","Step 3: The formula predicts eight hydrogen atoms."],"options":[],"conceptId":"chemistry_organic_chemistry_general_formula_of_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"General Formula of Alkanes"}', 2),
  (3893, 879, 'Calculate the molecular formula of an open-chain alkane containing eight carbon atoms. Show every step.', 'text', 1, 'Use H = 2n + 2.', '{"why":"The general formula gives eighteen hydrogen atoms for eight carbon atoms.","sol":"Step 1: Write the general formula: CnH2n+2.\nStep 2: Substitute n = 8.\nStep 3: Calculate H = 2(8) + 2.\nStep 4: H = 16 + 2 = 18.\nStep 5: Write the molecular formula.","steps":["Step 1: Write the general formula: CnH2n+2.","Step 2: Substitute n = 8.","Step 3: Calculate H = 2(8) + 2.","Step 4: H = 16 + 2 = 18.","Step 5: Write the molecular formula."],"options":[],"conceptId":"chemistry_organic_chemistry_general_formula_of_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"General Formula of Alkanes"}', 3),
  (3894, 879, 'An open-chain alkane has twelve hydrogen atoms. Determine its number of carbon atoms and write its molecular formula.', 'text', 1, 'Solve 2n + 2 = 12.', '{"why":"Rearranging the general formula allows the carbon count to be found from the hydrogen count.","sol":"Step 1: Start with H = 2n + 2.\nStep 2: Substitute H = 12: 12 = 2n + 2.\nStep 3: Subtract 2 from both sides: 10 = 2n.\nStep 4: Divide by 2: n = 5.\nStep 5: Write the formula as C5H12.","steps":["Step 1: Start with H = 2n + 2.","Step 2: Substitute H = 12: 12 = 2n + 2.","Step 3: Subtract 2 from both sides: 10 = 2n.","Step 4: Divide by 2: n = 5.","Step 5: Write the formula as C5H12."],"options":[],"conceptId":"chemistry_organic_chemistry_general_formula_of_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"General Formula of Alkanes"}', 4),
  (3895, 879, 'A learner claims that C6H12 is an open-chain alkane. Use the general formula to test the claim.', 'text', 1, 'Calculate the expected hydrogen count when n = 6.', '{"why":"C6H12 does not fit the general formula for an open-chain alkane.","sol":"Step 1: For an alkane, H = 2n + 2.\nStep 2: Substitute n = 6.\nStep 3: H = 2(6) + 2 = 14.\nStep 4: The expected formula is C6H14, not C6H12.","steps":["Step 1: For an alkane, H = 2n + 2.","Step 2: Substitute n = 6.","Step 3: H = 2(6) + 2 = 14.","Step 4: The expected formula is C6H14, not C6H12."],"options":[],"conceptId":"chemistry_organic_chemistry_general_formula_of_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q6","subject":"chemistry","chapter":"organic_chemistry","topic":"General Formula of Alkanes"}', 5),
  (3896, 879, 'Verify whether C9H20 fits the general formula of open-chain alkanes.', 'text', 1, 'Calculate 2(9) + 2.', '{"why":"The predicted and given hydrogen counts are equal.","sol":"Step 1: Identify n = 9.\nStep 2: Calculate H = 2(9) + 2.\nStep 3: H = 18 + 2 = 20.\nStep 4: Compare this with the given formula.","steps":["Step 1: Identify n = 9.","Step 2: Calculate H = 2(9) + 2.","Step 3: H = 18 + 2 = 20.","Step 4: Compare this with the given formula."],"options":[],"conceptId":"chemistry_organic_chemistry_general_formula_of_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q7","subject":"chemistry","chapter":"organic_chemistry","topic":"General Formula of Alkanes"}', 6),
  (3897, 879, 'Explain why the general formula CnH2n+2 should not be applied to every saturated hydrocarbon, including cyclic compounds.', 'text', 1, 'Compare an open chain with a ring.', '{"why":"The general formula depends on the structure, not just on the fact that the hydrocarbon is saturated.","sol":"Step 1: The formula CnH2n+2 applies to open-chain alkanes.\nStep 2: A cyclic saturated hydrocarbon forms a ring.\nStep 3: Closing the carbon chain changes the number of hydrogen atoms by two compared with the corresponding open chain.\nStep 4: Therefore, cyclic saturated hydrocarbons do not generally follow CnH2n+2.","steps":["Step 1: The formula CnH2n+2 applies to open-chain alkanes.","Step 2: A cyclic saturated hydrocarbon forms a ring.","Step 3: Closing the carbon chain changes the number of hydrogen atoms by two compared with the corresponding open chain.","Step 4: Therefore, cyclic saturated hydrocarbons do not generally follow CnH2n+2."],"options":[],"conceptId":"chemistry_organic_chemistry_general_formula_of_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q8","subject":"chemistry","chapter":"organic_chemistry","topic":"General Formula of Alkanes"}', 7),
  (3898, 880, 'State the general formula for an open-chain alkene with one double bond and for an open-chain alkyne with one triple bond.', 'text', 1, 'The alkene formula has two n in the hydrogen count; the alkyne has two fewer hydrogen atoms.', '{"why":"These formulae apply to open-chain hydrocarbons with one double or triple bond, respectively.","sol":"Step 1: The alkene formula is CnH2n.\nStep 2: The alkyne formula is CnH2n−2.","steps":["Step 1: The alkene formula is CnH2n.","Step 2: The alkyne formula is CnH2n−2."],"options":[],"conceptId":"chemistry_organic_chemistry_general_formulae_of_alkenes_and_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"General Formulae of Alkenes and Alkynes"}', 0),
  (3899, 880, 'Calculate the formula of an open-chain alkene containing six carbon atoms and one double bond.', 'text', 1, 'Substitute n = 6 into H = 2n.', '{"why":"The alkene formula gives twelve hydrogen atoms for six carbon atoms.","sol":"Step 1: Use CnH2n.\nStep 2: Substitute n = 6.\nStep 3: H = 2(6) = 12.","steps":["Step 1: Use CnH2n.","Step 2: Substitute n = 6.","Step 3: H = 2(6) = 12."],"options":[],"conceptId":"chemistry_organic_chemistry_general_formulae_of_alkenes_and_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"General Formulae of Alkenes and Alkynes"}', 1),
  (3900, 880, 'Calculate the formula of an open-chain alkyne containing three carbon atoms and one triple bond.', 'text', 1, 'Use H = 2n − 2.', '{"why":"The general formula predicts four hydrogen atoms for three carbon atoms.","sol":"Step 1: Use CnH2n−2.\nStep 2: Substitute n = 3.\nStep 3: H = 2(3) − 2 = 4.","steps":["Step 1: Use CnH2n−2.","Step 2: Substitute n = 3.","Step 3: H = 2(3) − 2 = 4."],"options":[],"conceptId":"chemistry_organic_chemistry_general_formulae_of_alkenes_and_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"General Formulae of Alkenes and Alkynes"}', 2),
  (3901, 880, 'Calculate the formula of an open-chain alkene containing seven carbon atoms and one double bond. Show the substitution and calculation.', 'text', 1, 'Use H = 2n.', '{"why":"The general formula for this alkene family gives fourteen hydrogen atoms.","sol":"Step 1: Write the formula: CnH2n.\nStep 2: Substitute n = 7.\nStep 3: Calculate H = 2(7) = 14.\nStep 4: Write the molecular formula.","steps":["Step 1: Write the formula: CnH2n.","Step 2: Substitute n = 7.","Step 3: Calculate H = 2(7) = 14.","Step 4: Write the molecular formula."],"options":[],"conceptId":"chemistry_organic_chemistry_general_formulae_of_alkenes_and_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"General Formulae of Alkenes and Alkynes"}', 3),
  (3902, 880, 'Calculate the formula of an open-chain alkyne containing six carbon atoms and one triple bond.', 'text', 1, 'Use H = 2n − 2.', '{"why":"The general formula gives ten hydrogen atoms for a six-carbon open-chain alkyne with one triple bond.","sol":"Step 1: Write the formula: CnH2n−2.\nStep 2: Substitute n = 6.\nStep 3: Calculate H = 2(6) − 2.\nStep 4: H = 12 − 2 = 10.","steps":["Step 1: Write the formula: CnH2n−2.","Step 2: Substitute n = 6.","Step 3: Calculate H = 2(6) − 2.","Step 4: H = 12 − 2 = 10."],"options":[],"conceptId":"chemistry_organic_chemistry_general_formulae_of_alkenes_and_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"General Formulae of Alkenes and Alkynes"}', 4),
  (3903, 880, 'An open-chain hydrocarbon with one carbon-carbon double bond has formula C5H10. Show that it fits the alkene general formula.', 'text', 1, 'Substitute n = 5 into CnH2n.', '{"why":"The calculated hydrogen count matches the given formula.","sol":"Step 1: The carbon count is n = 5.\nStep 2: For an alkene, H = 2n.\nStep 3: H = 2(5) = 10.\nStep 4: The predicted formula is C5H10.","steps":["Step 1: The carbon count is n = 5.","Step 2: For an alkene, H = 2n.","Step 3: H = 2(5) = 10.","Step 4: The predicted formula is C5H10."],"options":[],"conceptId":"chemistry_organic_chemistry_general_formulae_of_alkenes_and_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q6","subject":"chemistry","chapter":"organic_chemistry","topic":"General Formulae of Alkenes and Alkynes"}', 5),
  (3904, 880, 'Compare an open-chain alkene and an open-chain alkyne, each with four carbon atoms and one multiple bond. Calculate both formulae and state the difference in hydrogen count.', 'text', 1, 'Calculate the hydrogen count separately for each family.', '{"why":"For the same carbon count, the specified alkyne formula contains two fewer hydrogen atoms than the alkene formula.","sol":"Step 1: Alkene: H = 2(4) = 8, giving C4H8.\nStep 2: Alkyne: H = 2(4) − 2 = 6, giving C4H6.\nStep 3: Compare 8 hydrogen atoms with 6 hydrogen atoms.\nStep 4: The difference is 2 hydrogen atoms.","steps":["Step 1: Alkene: H = 2(4) = 8, giving C4H8.","Step 2: Alkyne: H = 2(4) − 2 = 6, giving C4H6.","Step 3: Compare 8 hydrogen atoms with 6 hydrogen atoms.","Step 4: The difference is 2 hydrogen atoms."],"options":[],"conceptId":"chemistry_organic_chemistry_general_formulae_of_alkenes_and_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q7","subject":"chemistry","chapter":"organic_chemistry","topic":"General Formulae of Alkenes and Alkynes"}', 6),
  (3905, 880, 'A learner says that any compound with formula C5H10 must be an alkene. Explain why this conclusion is not always justified.', 'text', 1, 'Think of another hydrocarbon family that can have the formula CnH2n.', '{"why":"A molecular formula gives the numbers of atoms, but different structures can share those numbers.","sol":"Step 1: An open-chain alkene with one double bond can follow CnH2n.\nStep 2: For n = 5, the formula is C5H10.\nStep 3: A cycloalkane can also follow CnH2n.\nStep 4: Therefore, the formula alone does not establish the structure.","steps":["Step 1: An open-chain alkene with one double bond can follow CnH2n.","Step 2: For n = 5, the formula is C5H10.","Step 3: A cycloalkane can also follow CnH2n.","Step 4: Therefore, the formula alone does not establish the structure."],"options":[],"conceptId":"chemistry_organic_chemistry_general_formulae_of_alkenes_and_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q8","subject":"chemistry","chapter":"organic_chemistry","topic":"General Formulae of Alkenes and Alkynes"}', 7),
  (3906, 881, 'Write the structural formula of ethane, C₂H₆, and verify the number of bonds around each carbon.', 'text', 1, 'Focus on the core principle of Structural Formulae.', '{"why":"The formula contains two carbon atoms and six hydrogen atoms, and each carbon has four covalent bonds.","sol":"Step 1: Join the two carbon atoms with a single bond: C–C.\nStep 2: Each carbon has one bond to the other carbon.\nStep 3: Add three hydrogen atoms to each carbon.\nStep 4: Write the formula as CH₃–CH₃.\nStep 5: Each carbon has one C–C bond and three C–H bonds, giving four bonds.","steps":["Step 1: Join the two carbon atoms with a single bond: C–C.","Step 2: Each carbon has one bond to the other carbon.","Step 3: Add three hydrogen atoms to each carbon.","Step 4: Write the formula as CH₃–CH₃.","Step 5: Each carbon has one C–C bond and three C–H bonds, giving four bonds."],"options":[],"conceptId":"chemistry_organic_chemistry_structural_formulae","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Structural Formulae"}', 0),
  (3907, 881, 'Write the structural formula of butane, C₄H₁₀, as a straight chain.', 'text', 1, 'Focus on the core principle of Structural Formulae.', '{"why":"The two end groups contribute six hydrogen atoms and the two middle groups contribute four, giving C₄H₁₀.","sol":"Step 1: Arrange four carbon atoms in a chain: C–C–C–C.\nStep 2: Each terminal carbon has one carbon neighbour and needs three hydrogen atoms.\nStep 3: Each internal carbon has two carbon neighbours and needs two hydrogen atoms.\nStep 4: Combine the groups in order.\nStep 5: The formula is CH₃–CH₂–CH₂–CH₃.","steps":["Step 1: Arrange four carbon atoms in a chain: C–C–C–C.","Step 2: Each terminal carbon has one carbon neighbour and needs three hydrogen atoms.","Step 3: Each internal carbon has two carbon neighbours and needs two hydrogen atoms.","Step 4: Combine the groups in order.","Step 5: The formula is CH₃–CH₂–CH₂–CH₃."],"options":[],"conceptId":"chemistry_organic_chemistry_structural_formulae","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Structural Formulae"}', 1),
  (3908, 881, 'Write the structural formula of but-1-ene, C₄H₈.', 'text', 1, 'Focus on the core principle of Structural Formulae.', '{"why":"The structure has four carbon atoms, eight hydrogen atoms and a double bond beginning at carbon 1.","sol":"Step 1: Arrange four carbon atoms in a chain.\nStep 2: Place the double bond between carbon 1 and carbon 2.\nStep 3: Complete the bonds using hydrogen atoms.\nStep 4: The first carbon is CH₂, the second is CH, the third is CH₂ and the fourth is CH₃.\nStep 5: Write CH₂=CH–CH₂–CH₃.","steps":["Step 1: Arrange four carbon atoms in a chain.","Step 2: Place the double bond between carbon 1 and carbon 2.","Step 3: Complete the bonds using hydrogen atoms.","Step 4: The first carbon is CH₂, the second is CH, the third is CH₂ and the fourth is CH₃.","Step 5: Write CH₂=CH–CH₂–CH₃."],"options":[],"conceptId":"chemistry_organic_chemistry_structural_formulae","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Structural Formulae"}', 2),
  (3909, 881, 'Write the structural formula of pentane as a straight chain.', 'text', 1, 'Start with five carbon atoms connected by single bonds.', '{"why":"The straight-chain structure has five carbon atoms and 3 + 2 + 2 + 2 + 3 = 12 hydrogen atoms.","sol":"Step 1: Arrange five carbon atoms in a row.\nStep 2: Join adjacent carbon atoms with single bonds.\nStep 3: Give each end carbon three hydrogen atoms.\nStep 4: Give each of the three internal carbons two hydrogen atoms.\nStep 5: Write CH₃–CH₂–CH₂–CH₂–CH₃.","steps":["Step 1: Arrange five carbon atoms in a row.","Step 2: Join adjacent carbon atoms with single bonds.","Step 3: Give each end carbon three hydrogen atoms.","Step 4: Give each of the three internal carbons two hydrogen atoms.","Step 5: Write CH₃–CH₂–CH₂–CH₂–CH₃."],"options":[],"conceptId":"chemistry_organic_chemistry_structural_formulae","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Structural Formulae"}', 3),
  (3910, 881, 'Explain why CH₃–CH₂–CH₃ is a valid structural formula for propane.', 'text', 1, 'Count the atoms and check carbon''s four-bond requirement.', '{"why":"A valid structural formula must satisfy both the molecular formula and the usual valency of carbon.","sol":"Step 1: Count three carbon atoms.\nStep 2: Count the hydrogen atoms: 3 + 2 + 3 = 8.\nStep 3: Each end carbon has one carbon bond and three hydrogen bonds.\nStep 4: The middle carbon has two carbon bonds and two hydrogen bonds.\nStep 5: Every carbon has four bonds, so the structure is valid.","steps":["Step 1: Count three carbon atoms.","Step 2: Count the hydrogen atoms: 3 + 2 + 3 = 8.","Step 3: Each end carbon has one carbon bond and three hydrogen bonds.","Step 4: The middle carbon has two carbon bonds and two hydrogen bonds.","Step 5: Every carbon has four bonds, so the structure is valid."],"options":[],"conceptId":"chemistry_organic_chemistry_structural_formulae","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Structural Formulae"}', 4),
  (3911, 881, 'Write a structural formula for ethyne, C₂H₂, and explain the bond between its carbon atoms.', 'text', 1, 'Ethyne is an alkyne, so the carbon atoms are joined by a triple bond.', '{"why":"Each carbon has three bonds to the other carbon and one bond to hydrogen, giving four bonds in total.","sol":"Step 1: Place two carbon atoms together.\nStep 2: Join them with a triple bond: C≡C.\nStep 3: Each carbon now has three bonds to the other carbon.\nStep 4: Add one hydrogen atom to each carbon.\nStep 5: The structural formula is H–C≡C–H.","steps":["Step 1: Place two carbon atoms together.","Step 2: Join them with a triple bond: C≡C.","Step 3: Each carbon now has three bonds to the other carbon.","Step 4: Add one hydrogen atom to each carbon.","Step 5: The structural formula is H–C≡C–H."],"options":[],"conceptId":"chemistry_organic_chemistry_structural_formulae","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q6","subject":"chemistry","chapter":"organic_chemistry","topic":"Structural Formulae"}', 5),
  (3912, 881, 'A learner writes CH₃–CH₃ for a compound with molecular formula C₂H₄. Identify the error.', 'text', 1, 'Count the hydrogen atoms in the proposed structural formula.', '{"why":"The atom count and bond arrangement must agree with the stated molecular formula.","sol":"Step 1: CH₃–CH₃ contains two CH₃ groups.\nStep 2: Its total hydrogen count is 3 + 3 = 6.\nStep 3: The proposed structure therefore represents C₂H₆, not C₂H₄.\nStep 4: One possible structure for C₂H₄ is CH₂=CH₂.","steps":["Step 1: CH₃–CH₃ contains two CH₃ groups.","Step 2: Its total hydrogen count is 3 + 3 = 6.","Step 3: The proposed structure therefore represents C₂H₆, not C₂H₄.","Step 4: One possible structure for C₂H₄ is CH₂=CH₂."],"options":[],"conceptId":"chemistry_organic_chemistry_structural_formulae","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q7","subject":"chemistry","chapter":"organic_chemistry","topic":"Structural Formulae"}', 6),
  (3913, 881, 'Explain the difference between a molecular formula and a structural formula using propane.', 'text', 1, 'One gives the number of atoms; the other shows their connections.', '{"why":"The two formulae communicate different information about the same molecule.","sol":"Step 1: Write propane''s molecular formula: C₃H₈.\nStep 2: This tells us that the molecule contains three carbon atoms and eight hydrogen atoms.\nStep 3: Write its structural formula: CH₃–CH₂–CH₃.\nStep 4: The structural formula shows the carbon chain and how the hydrogen atoms are grouped.","steps":["Step 1: Write propane''s molecular formula: C₃H₈.","Step 2: This tells us that the molecule contains three carbon atoms and eight hydrogen atoms.","Step 3: Write its structural formula: CH₃–CH₂–CH₃.","Step 4: The structural formula shows the carbon chain and how the hydrogen atoms are grouped."],"options":[],"conceptId":"chemistry_organic_chemistry_structural_formulae","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q8","subject":"chemistry","chapter":"organic_chemistry","topic":"Structural Formulae"}', 7),
  (3914, 882, 'Write the condensed structural formula of propane.', 'text', 1, 'Focus on the core principle of Condensed Structural Formulae.', '{"why":"The condensed formula preserves the carbon chain while grouping each carbon with its attached hydrogen atoms.","sol":"Step 1: Propane has three carbon atoms.\nStep 2: The end groups are CH₃.\nStep 3: The middle group is CH₂.\nStep 4: Combine the groups in order.\nStep 5: CH₃CH₂CH₃.","steps":["Step 1: Propane has three carbon atoms.","Step 2: The end groups are CH₃.","Step 3: The middle group is CH₂.","Step 4: Combine the groups in order.","Step 5: CH₃CH₂CH₃."],"options":[],"conceptId":"chemistry_organic_chemistry_condensed_structural_formulae","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Condensed Structural Formulae"}', 0),
  (3915, 882, 'Determine the molecular formula of CH₃CH₂CH₂CH₂CH₃.', 'text', 1, 'Focus on the core principle of Condensed Structural Formulae.', '{"why":"There are five carbon atoms and twelve hydrogen atoms.","sol":"Step 1: Count the carbon groups: five.\nStep 2: Add the hydrogen counts: 3 + 2 + 2 + 2 + 3 = 12.\nStep 3: Write the molecular formula using the total numbers of each atom.","steps":["Step 1: Count the carbon groups: five.","Step 2: Add the hydrogen counts: 3 + 2 + 2 + 2 + 3 = 12.","Step 3: Write the molecular formula using the total numbers of each atom."],"options":[],"conceptId":"chemistry_organic_chemistry_condensed_structural_formulae","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Condensed Structural Formulae"}', 1),
  (3916, 882, 'Write the condensed structural formula of straight-chain hexane.', 'text', 1, 'Focus on the core principle of Condensed Structural Formulae.', '{"why":"Two terminal CH₃ groups and four internal CH₂ groups give C₆H₁₄.","sol":"Step 1: Hexane contains six carbon atoms.\nStep 2: The first and last groups are CH₃.\nStep 3: The four internal groups are CH₂.\nStep 4: Write the groups in sequence.","steps":["Step 1: Hexane contains six carbon atoms.","Step 2: The first and last groups are CH₃.","Step 3: The four internal groups are CH₂.","Step 4: Write the groups in sequence."],"options":[],"conceptId":"chemistry_organic_chemistry_condensed_structural_formulae","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Condensed Structural Formulae"}', 2),
  (3917, 882, 'How many carbon and hydrogen atoms are represented by CH₃CH₂CH₂CH₃?', 'text', 1, 'Count each carbon group and add the hydrogen subscripts.', '{"why":"Each group contains one carbon, and its subscript gives the number of attached hydrogen atoms.","sol":"Step 1: There are four carbon groups, so there are four carbon atoms.\nStep 2: Add the hydrogen counts: 3 + 2 + 2 + 3 = 10.\nStep 3: State the molecular formula.","steps":["Step 1: There are four carbon groups, so there are four carbon atoms.","Step 2: Add the hydrogen counts: 3 + 2 + 2 + 3 = 10.","Step 3: State the molecular formula."],"options":[],"conceptId":"chemistry_organic_chemistry_condensed_structural_formulae","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Condensed Structural Formulae"}', 3),
  (3918, 882, 'Write the condensed structural formula of straight-chain heptane.', 'text', 1, 'Heptane has seven carbon atoms.', '{"why":"The formula has seven carbon atoms and sixteen hydrogen atoms, consistent with C₇H₁₆.","sol":"Step 1: Put seven carbon groups in a chain.\nStep 2: Use CH₃ at each end.\nStep 3: Use CH₂ for the five internal carbons.\nStep 4: Combine the groups.","steps":["Step 1: Put seven carbon groups in a chain.","Step 2: Use CH₃ at each end.","Step 3: Use CH₂ for the five internal carbons.","Step 4: Combine the groups."],"options":[],"conceptId":"chemistry_organic_chemistry_condensed_structural_formulae","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Condensed Structural Formulae"}', 4),
  (3919, 882, 'Explain what the brackets mean in CH₃CH(CH₃)CH₃.', 'text', 1, 'The bracketed group is a branch, not a separate molecule.', '{"why":"Brackets indicate a branch attached to the adjacent carbon in the condensed formula.","sol":"Step 1: Identify the main written sequence: CH₃–CH–CH₃.\nStep 2: The CH₃ inside brackets is attached to the middle CH carbon.\nStep 3: The molecule therefore has a three-carbon main chain and an additional methyl branch.\nStep 4: The structure is 2-methylpropane.","steps":["Step 1: Identify the main written sequence: CH₃–CH–CH₃.","Step 2: The CH₃ inside brackets is attached to the middle CH carbon.","Step 3: The molecule therefore has a three-carbon main chain and an additional methyl branch.","Step 4: The structure is 2-methylpropane."],"options":[],"conceptId":"chemistry_organic_chemistry_condensed_structural_formulae","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q6","subject":"chemistry","chapter":"organic_chemistry","topic":"Condensed Structural Formulae"}', 5),
  (3920, 882, 'A learner says CH₃CH₂CH₃ contains five carbon atoms because the subscripts add to five. Explain the mistake.', 'text', 1, 'The subscripts after H count hydrogen atoms, not carbon atoms.', '{"why":"Carbon counts come from the carbon symbols, while hydrogen counts come from the hydrogen subscripts.","sol":"Step 1: Count the carbon groups: CH₃, CH₂ and CH₃.\nStep 2: Each group contains one carbon atom.\nStep 3: There are three carbon atoms.\nStep 4: The hydrogen count is 3 + 2 + 3 = 8.","steps":["Step 1: Count the carbon groups: CH₃, CH₂ and CH₃.","Step 2: Each group contains one carbon atom.","Step 3: There are three carbon atoms.","Step 4: The hydrogen count is 3 + 2 + 3 = 8."],"options":[],"conceptId":"chemistry_organic_chemistry_condensed_structural_formulae","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q7","subject":"chemistry","chapter":"organic_chemistry","topic":"Condensed Structural Formulae"}', 6),
  (3921, 882, 'Write the condensed structural formula of 2-methylbutane.', 'text', 1, 'Start with a four-carbon chain and attach a CH₃ branch to carbon 2.', '{"why":"The formula shows a four-carbon parent chain with one methyl group attached to carbon 2.","sol":"Step 1: Write the four-carbon parent chain: CH₃–CH₂–CH₂–CH₃.\nStep 2: Number from an end and identify carbon 2.\nStep 3: Replace the CH₂ at carbon 2 with CH(CH₃), because it now has a methyl branch.\nStep 4: Write the result without bond lines.","steps":["Step 1: Write the four-carbon parent chain: CH₃–CH₂–CH₂–CH₃.","Step 2: Number from an end and identify carbon 2.","Step 3: Replace the CH₂ at carbon 2 with CH(CH₃), because it now has a methyl branch.","Step 4: Write the result without bond lines."],"options":[],"conceptId":"chemistry_organic_chemistry_condensed_structural_formulae","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q8","subject":"chemistry","chapter":"organic_chemistry","topic":"Condensed Structural Formulae"}', 7),
  (3922, 883, 'Name CH₃CH₂CH₃.', 'text', 1, 'Focus on the core principle of Naming Straight-Chain Alkanes.', '{"why":"A straight-chain alkane with three carbon atoms is propane.","sol":"Step 1: Count the carbon atoms: three.\nStep 2: The prefix for three carbons is prop-.\nStep 3: The compound has only single carbon-carbon bonds, so use -ane.","steps":["Step 1: Count the carbon atoms: three.","Step 2: The prefix for three carbons is prop-.","Step 3: The compound has only single carbon-carbon bonds, so use -ane."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_straight_chain_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Straight-Chain Alkanes"}', 0),
  (3923, 883, 'Name CH₃CH₂CH₂CH₂CH₃.', 'text', 1, 'Focus on the core principle of Naming Straight-Chain Alkanes.', '{"why":"The unbranched saturated five-carbon hydrocarbon is pentane.","sol":"Step 1: Count five carbon atoms.\nStep 2: The five-carbon prefix is pent-.\nStep 3: Add -ane.","steps":["Step 1: Count five carbon atoms.","Step 2: The five-carbon prefix is pent-.","Step 3: Add -ane."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_straight_chain_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Straight-Chain Alkanes"}', 1),
  (3924, 883, 'Name CH₃CH₂CH₂CH₂CH₂CH₃.', 'text', 1, 'Focus on the core principle of Naming Straight-Chain Alkanes.', '{"why":"The structure contains six carbon atoms in an unbranched saturated chain.","sol":"Step 1: Count six carbon atoms.\nStep 2: The six-carbon prefix is hex-.\nStep 3: Add the suffix -ane.","steps":["Step 1: Count six carbon atoms.","Step 2: The six-carbon prefix is hex-.","Step 3: Add the suffix -ane."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_straight_chain_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Straight-Chain Alkanes"}', 2),
  (3925, 883, 'Name CH₃CH₂CH₂CH₂CH₂CH₂CH₃.', 'text', 1, 'Count the carbon atoms before selecting the prefix.', '{"why":"The compound is an unbranched seven-carbon alkane.","sol":"Step 1: Count seven carbon atoms.\nStep 2: Seven carbons use the prefix hept-.\nStep 3: Add -ane because all carbon-carbon bonds are single.\nStep 4: The name is heptane.","steps":["Step 1: Count seven carbon atoms.","Step 2: Seven carbons use the prefix hept-.","Step 3: Add -ane because all carbon-carbon bonds are single.","Step 4: The name is heptane."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_straight_chain_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Straight-Chain Alkanes"}', 3),
  (3926, 883, 'Name CH₃CH₂CH₂CH₂CH₂CH₂CH₂CH₃.', 'text', 1, 'Eight carbon atoms use the prefix oct-.', '{"why":"Octane is the straight-chain alkane with eight carbon atoms.","sol":"Step 1: Count eight carbon atoms.\nStep 2: Use the prefix oct-.\nStep 3: Add -ane.","steps":["Step 1: Count eight carbon atoms.","Step 2: Use the prefix oct-.","Step 3: Add -ane."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_straight_chain_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Straight-Chain Alkanes"}', 4),
  (3927, 883, 'A straight-chain alkane has nine carbon atoms. Give its name and explain how you obtained it.', 'text', 1, 'The prefix for nine carbon atoms is non-.', '{"why":"The name combines non-, for nine carbons, with -ane, for a saturated alkane.","sol":"Step 1: Identify the carbon count: nine.\nStep 2: Choose the prefix non-.\nStep 3: Add -ane for an alkane.","steps":["Step 1: Identify the carbon count: nine.","Step 2: Choose the prefix non-.","Step 3: Add -ane for an alkane."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_straight_chain_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q6","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Straight-Chain Alkanes"}', 5),
  (3928, 883, 'A learner names a straight-chain four-carbon alkane ''propane''. Identify the error and give the correct name.', 'text', 1, 'Propane has three carbon atoms, not four.', '{"why":"The carbon prefix must match the actual number of carbon atoms.","sol":"Step 1: Count the carbon atoms: four.\nStep 2: Four carbons use the prefix but-.\nStep 3: Add -ane.","steps":["Step 1: Count the carbon atoms: four.","Step 2: Four carbons use the prefix but-.","Step 3: Add -ane."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_straight_chain_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q7","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Straight-Chain Alkanes"}', 6),
  (3929, 883, 'Explain why CH₃CH=CHCH₃ is not named as a straight-chain alkane.', 'text', 1, 'Inspect the bond between the two middle carbon atoms.', '{"why":"The bond type determines whether the compound is an alkane, alkene or alkyne.","sol":"Step 1: Identify the carbon-carbon double bond shown by =.\nStep 2: Alkanes contain only carbon-carbon single bonds.\nStep 3: A compound with a carbon-carbon double bond is an alkene.\nStep 4: The four-carbon compound is named but-2-ene.","steps":["Step 1: Identify the carbon-carbon double bond shown by =.","Step 2: Alkanes contain only carbon-carbon single bonds.","Step 3: A compound with a carbon-carbon double bond is an alkene.","Step 4: The four-carbon compound is named but-2-ene."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_straight_chain_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q8","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Straight-Chain Alkanes"}', 7),
  (3930, 884, 'Name CH₃CH(CH₃)CH₃.', 'text', 1, 'Focus on the core principle of Naming Branched-Chain Alkanes.', '{"why":"The parent chain has three carbon atoms and the methyl substituent is on carbon 2.","sol":"Step 1: Find the longest chain: three carbons, so propane.\nStep 2: Identify the branch: CH₃, a methyl group.\nStep 3: The branch is attached to carbon 2.\nStep 4: Combine the parts as 2-methylpropane.","steps":["Step 1: Find the longest chain: three carbons, so propane.","Step 2: Identify the branch: CH₃, a methyl group.","Step 3: The branch is attached to carbon 2.","Step 4: Combine the parts as 2-methylpropane."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_branched_chain_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Branched-Chain Alkanes"}', 0),
  (3931, 884, 'Name CH₃CH(CH₃)CH₂CH₃.', 'text', 1, 'Focus on the core principle of Naming Branched-Chain Alkanes.', '{"why":"The four-carbon parent chain and carbon-2 methyl branch determine the name.","sol":"Step 1: The longest chain contains four carbon atoms, giving butane.\nStep 2: The branch is a methyl group.\nStep 3: Number from the end nearest the branch.\nStep 4: The branch is on carbon 2.","steps":["Step 1: The longest chain contains four carbon atoms, giving butane.","Step 2: The branch is a methyl group.","Step 3: Number from the end nearest the branch.","Step 4: The branch is on carbon 2."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_branched_chain_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Branched-Chain Alkanes"}', 1),
  (3932, 884, 'Name CH₃CH₂CH(CH₃)CH₂CH₃.', 'text', 1, 'Focus on the core principle of Naming Branched-Chain Alkanes.', '{"why":"The parent chain is pentane and the methyl substituent is on carbon 3.","sol":"Step 1: The longest chain contains five carbons, giving pentane.\nStep 2: The branch is CH₃, a methyl group.\nStep 3: Numbering from either end places the branch on carbon 3.\nStep 4: Write the name as 3-methylpentane.","steps":["Step 1: The longest chain contains five carbons, giving pentane.","Step 2: The branch is CH₃, a methyl group.","Step 3: Numbering from either end places the branch on carbon 3.","Step 4: Write the name as 3-methylpentane."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_branched_chain_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Branched-Chain Alkanes"}', 2),
  (3933, 884, 'Name CH₃CH(CH₃)CH₂CH₂CH₃.', 'text', 1, 'Find the longest chain before numbering it.', '{"why":"The parent chain is pentane and the methyl substituent receives the lowest possible number, 2.","sol":"Step 1: The longest chain has five carbons, so the parent is pentane.\nStep 2: Identify the methyl branch.\nStep 3: Number from the end nearest the branch.\nStep 4: The branch is on carbon 2.\nStep 5: Write the name.","steps":["Step 1: The longest chain has five carbons, so the parent is pentane.","Step 2: Identify the methyl branch.","Step 3: Number from the end nearest the branch.","Step 4: The branch is on carbon 2.","Step 5: Write the name."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_branched_chain_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Branched-Chain Alkanes"}', 3),
  (3934, 884, 'Name CH₃CH₂CH(CH₂CH₃)CH₂CH₃.', 'text', 1, 'Identify the longest continuous chain and then the branch.', '{"why":"A five-carbon parent chain with an ethyl substituent on carbon 3 is 3-ethylpentane.","sol":"Step 1: The longest continuous chain contains five carbon atoms.\nStep 2: The parent name is pentane.\nStep 3: The group attached to carbon 3 is –CH₂CH₃, an ethyl group.\nStep 4: The branch is on carbon 3.\nStep 5: Write the name.","steps":["Step 1: The longest continuous chain contains five carbon atoms.","Step 2: The parent name is pentane.","Step 3: The group attached to carbon 3 is –CH₂CH₃, an ethyl group.","Step 4: The branch is on carbon 3.","Step 5: Write the name."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_branched_chain_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Branched-Chain Alkanes"}', 4),
  (3935, 884, 'Name CH₃C(CH₃)₂CH₃.', 'text', 1, 'The central carbon is connected to four methyl groups; find the longest continuous chain.', '{"why":"The molecule has a three-carbon parent chain and two methyl substituents on carbon 2.","sol":"Step 1: The longest continuous chain contains three carbons, giving propane.\nStep 2: Two methyl groups are attached to the middle carbon.\nStep 3: Both substituents are on carbon 2.\nStep 4: Use the prefix di- for two identical substituents.\nStep 5: Write the name.","steps":["Step 1: The longest continuous chain contains three carbons, giving propane.","Step 2: Two methyl groups are attached to the middle carbon.","Step 3: Both substituents are on carbon 2.","Step 4: Use the prefix di- for two identical substituents.","Step 5: Write the name."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_branched_chain_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q6","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Branched-Chain Alkanes"}', 5),
  (3936, 884, 'Explain why CH₃CH(CH₃)CH₂CH₃ is not named 3-methylbutane.', 'text', 1, 'Try numbering the parent chain from the opposite end.', '{"why":"The parent chain is numbered to give the substituent the lowest possible locant.","sol":"Step 1: The longest chain contains four carbons, so the parent is butane.\nStep 2: Number from the left: the methyl branch is on carbon 2.\nStep 3: Numbering from the right would place it on carbon 3.\nStep 4: The lower locant must be used.","steps":["Step 1: The longest chain contains four carbons, so the parent is butane.","Step 2: Number from the left: the methyl branch is on carbon 2.","Step 3: Numbering from the right would place it on carbon 3.","Step 4: The lower locant must be used."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_branched_chain_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q7","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Branched-Chain Alkanes"}', 6),
  (3937, 884, 'A structure has a five-carbon parent chain and an ethyl group attached to carbon 3. Give the name and explain the parts.', 'text', 1, 'Use the parent-chain name first and the substituent name with its position.', '{"why":"The name identifies both the five-carbon parent chain and the ethyl substituent''s position.","sol":"Step 1: Five carbons give the parent name pentane.\nStep 2: The two-carbon branch is ethyl.\nStep 3: The branch is attached to carbon 3.\nStep 4: Combine the locant, substituent and parent name.","steps":["Step 1: Five carbons give the parent name pentane.","Step 2: The two-carbon branch is ethyl.","Step 3: The branch is attached to carbon 3.","Step 4: Combine the locant, substituent and parent name."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_branched_chain_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q8","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Branched-Chain Alkanes"}', 7),
  (3938, 885, 'Name CH₂=CH₂.', 'text', 1, 'Focus on the core principle of Naming Alkenes.', '{"why":"Ethene is the two-carbon alkene; no position number is needed.","sol":"Step 1: Count two carbon atoms.\nStep 2: The prefix for two carbons is eth-.\nStep 3: The double bond requires the ending -ene.\nStep 4: The name is ethene.","steps":["Step 1: Count two carbon atoms.","Step 2: The prefix for two carbons is eth-.","Step 3: The double bond requires the ending -ene.","Step 4: The name is ethene."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_alkenes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Alkenes"}', 0),
  (3939, 885, 'Name CH₂=CHCH₂CH₃.', 'text', 1, 'Focus on the core principle of Naming Alkenes.', '{"why":"The four-carbon chain has a double bond beginning at carbon 1.","sol":"Step 1: Count four carbon atoms, giving but-.\nStep 2: Number from the end nearest the double bond.\nStep 3: The double bond begins at carbon 1.\nStep 4: Add -ene and the locant.","steps":["Step 1: Count four carbon atoms, giving but-.","Step 2: Number from the end nearest the double bond.","Step 3: The double bond begins at carbon 1.","Step 4: Add -ene and the locant."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_alkenes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Alkenes"}', 1),
  (3940, 885, 'Name CH₃CH=CHCH₃.', 'text', 1, 'Focus on the core principle of Naming Alkenes.', '{"why":"The double bond begins at carbon 2 in a four-carbon chain.","sol":"Step 1: Count four carbon atoms.\nStep 2: The double bond is between carbons 2 and 3.\nStep 3: The lowest locant for the double bond is 2.\nStep 4: Name the compound but-2-ene.","steps":["Step 1: Count four carbon atoms.","Step 2: The double bond is between carbons 2 and 3.","Step 3: The lowest locant for the double bond is 2.","Step 4: Name the compound but-2-ene."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_alkenes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Alkenes"}', 2),
  (3941, 885, 'Name CH₂=CHCH₂CH₂CH₃.', 'text', 1, 'Count the chain and number from the end nearest the double bond.', '{"why":"The compound has five carbon atoms and a double bond beginning at carbon 1.","sol":"Step 1: Count five carbon atoms, giving pent-.\nStep 2: The double bond is at the end of the chain.\nStep 3: It begins at carbon 1.\nStep 4: Add -ene and the locant.","steps":["Step 1: Count five carbon atoms, giving pent-.","Step 2: The double bond is at the end of the chain.","Step 3: It begins at carbon 1.","Step 4: Add -ene and the locant."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_alkenes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Alkenes"}', 3),
  (3942, 885, 'Name CH₃CH₂CH=CHCH₃.', 'text', 1, 'Number from the end that gives the double bond the lower number.', '{"why":"Numbering from the nearer end gives the double bond locant 2 rather than 3.","sol":"Step 1: Count five carbon atoms, giving pent-.\nStep 2: Number from the right-hand end, which is nearer the double bond.\nStep 3: The double bond begins at carbon 2.\nStep 4: Name the compound pent-2-ene.","steps":["Step 1: Count five carbon atoms, giving pent-.","Step 2: Number from the right-hand end, which is nearer the double bond.","Step 3: The double bond begins at carbon 2.","Step 4: Name the compound pent-2-ene."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_alkenes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Alkenes"}', 4),
  (3943, 885, 'Explain why CH₂=CHCH₂CH₃ is not but-3-ene.', 'text', 1, 'The chain can be numbered from either end, but one direction gives a lower locant.', '{"why":"The double bond must receive the lowest possible locant.","sol":"Step 1: The parent chain has four carbon atoms.\nStep 2: From the left, the double bond begins at carbon 1.\nStep 3: From the opposite end, it would begin at carbon 3.\nStep 4: Use the lower locant.","steps":["Step 1: The parent chain has four carbon atoms.","Step 2: From the left, the double bond begins at carbon 1.","Step 3: From the opposite end, it would begin at carbon 3.","Step 4: Use the lower locant."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_alkenes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q6","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Alkenes"}', 5),
  (3944, 885, 'Name CH₃CH₂CH₂CH=CH₂.', 'text', 1, 'Start numbering at the CH₂ end because it is nearest the double bond.', '{"why":"The five-carbon chain has a terminal double bond.","sol":"Step 1: Count five carbon atoms.\nStep 2: Number from the right-hand end.\nStep 3: The double bond begins at carbon 1.\nStep 4: Write the name.","steps":["Step 1: Count five carbon atoms.","Step 2: Number from the right-hand end.","Step 3: The double bond begins at carbon 1.","Step 4: Write the name."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_alkenes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q7","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Alkenes"}', 6),
  (3945, 885, 'A four-carbon alkene has its double bond between carbon 2 and carbon 3. Give its name and explain the locant.', 'text', 1, 'Four carbons use but-; the double bond begins at carbon 2.', '{"why":"The locant identifies the first carbon in the double bond.","sol":"Step 1: Four carbon atoms give the prefix but-.\nStep 2: The double bond is between carbon 2 and carbon 3.\nStep 3: Its locant is the lower-numbered carbon, 2.\nStep 4: Add -ene.","steps":["Step 1: Four carbon atoms give the prefix but-.","Step 2: The double bond is between carbon 2 and carbon 3.","Step 3: Its locant is the lower-numbered carbon, 2.","Step 4: Add -ene."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_alkenes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q8","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Alkenes"}', 7),
  (3946, 886, 'Name HC≡CH.', 'text', 1, 'Focus on the core principle of Naming Alkynes.', '{"why":"Ethyne is the two-carbon alkyne.","sol":"Step 1: Count two carbon atoms.\nStep 2: The prefix is eth-.\nStep 3: The triple bond requires -yne.\nStep 4: The name is ethyne.","steps":["Step 1: Count two carbon atoms.","Step 2: The prefix is eth-.","Step 3: The triple bond requires -yne.","Step 4: The name is ethyne."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Alkynes"}', 0),
  (3947, 886, 'Name HC≡CCH₂CH₃.', 'text', 1, 'Focus on the core principle of Naming Alkynes.', '{"why":"The molecule has a four-carbon chain with a terminal triple bond.","sol":"Step 1: Count four carbon atoms.\nStep 2: Use the prefix but-.\nStep 3: Number from the end nearest the triple bond.\nStep 4: The triple bond begins at carbon 1.\nStep 5: Name the compound but-1-yne.","steps":["Step 1: Count four carbon atoms.","Step 2: Use the prefix but-.","Step 3: Number from the end nearest the triple bond.","Step 4: The triple bond begins at carbon 1.","Step 5: Name the compound but-1-yne."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Alkynes"}', 1),
  (3948, 886, 'Name CH₃C≡CCH₃.', 'text', 1, 'Focus on the core principle of Naming Alkynes.', '{"why":"The triple bond begins at carbon 2 in a four-carbon chain.","sol":"Step 1: Count four carbon atoms.\nStep 2: The triple bond is between carbons 2 and 3.\nStep 3: The triple-bond locant is 2.\nStep 4: Use the ending -yne.","steps":["Step 1: Count four carbon atoms.","Step 2: The triple bond is between carbons 2 and 3.","Step 3: The triple-bond locant is 2.","Step 4: Use the ending -yne."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Alkynes"}', 2),
  (3949, 886, 'Name HC≡CCH₂CH₂CH₃.', 'text', 1, 'Count the carbon atoms and start numbering at the triple-bond end.', '{"why":"The five-carbon chain has a terminal triple bond.","sol":"Step 1: Count five carbon atoms, giving pent-.\nStep 2: Number from the end nearest the triple bond.\nStep 3: The triple bond begins at carbon 1.\nStep 4: Add -yne and the locant.","steps":["Step 1: Count five carbon atoms, giving pent-.","Step 2: Number from the end nearest the triple bond.","Step 3: The triple bond begins at carbon 1.","Step 4: Add -yne and the locant."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Alkynes"}', 3),
  (3950, 886, 'Name CH₃CH₂C≡CCH₃.', 'text', 1, 'Number from the end closest to the triple bond.', '{"why":"The lowest possible locant for the triple bond is 2.","sol":"Step 1: Count five carbon atoms.\nStep 2: Number from the right-hand end.\nStep 3: The triple bond begins at carbon 2.\nStep 4: Write the name.","steps":["Step 1: Count five carbon atoms.","Step 2: Number from the right-hand end.","Step 3: The triple bond begins at carbon 2.","Step 4: Write the name."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Alkynes"}', 4),
  (3951, 886, 'Explain why HC≡CCH₂CH₃ is not but-3-yne.', 'text', 1, 'Compare the locants obtained by numbering from opposite ends.', '{"why":"The triple bond must receive the lowest possible locant.","sol":"Step 1: The chain contains four carbon atoms.\nStep 2: Numbering from the triple-bond end gives locant 1.\nStep 3: Numbering from the other end would give locant 3.\nStep 4: Choose the lower locant.","steps":["Step 1: The chain contains four carbon atoms.","Step 2: Numbering from the triple-bond end gives locant 1.","Step 3: Numbering from the other end would give locant 3.","Step 4: Choose the lower locant."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q6","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Alkynes"}', 5),
  (3952, 886, 'A five-carbon alkyne has its triple bond between carbons 2 and 3. Give its name.', 'text', 1, 'Five carbons use pent- and the triple bond uses -yne.', '{"why":"The locant 2 identifies the first carbon in the triple bond.","sol":"Step 1: Five carbon atoms give the prefix pent-.\nStep 2: The triple bond begins at carbon 2.\nStep 3: Use the ending -yne.\nStep 4: Combine the locant and parent name.","steps":["Step 1: Five carbon atoms give the prefix pent-.","Step 2: The triple bond begins at carbon 2.","Step 3: Use the ending -yne.","Step 4: Combine the locant and parent name."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q7","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Alkynes"}', 6),
  (3953, 886, 'State the difference between but-1-ene and but-1-yne.', 'text', 1, 'Compare the multiple bonds indicated by their endings.', '{"why":"The suffix identifies the type of multiple bond, while the locant identifies its position.","sol":"Step 1: Both names refer to a four-carbon chain.\nStep 2: The ending -ene indicates a carbon-carbon double bond.\nStep 3: The ending -yne indicates a carbon-carbon triple bond.\nStep 4: The locant 1 places the multiple bond at the end in each structure.","steps":["Step 1: Both names refer to a four-carbon chain.","Step 2: The ending -ene indicates a carbon-carbon double bond.","Step 3: The ending -yne indicates a carbon-carbon triple bond.","Step 4: The locant 1 places the multiple bond at the end in each structure."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q8","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Alkynes"}', 7),
  (3954, 887, 'Define structural isomerism.', 'text', 1, 'Focus on the core principle of Structural Isomerism.', '{"why":"Both the same molecular formula and different structural arrangements are required.","sol":"Step 1: State that the compounds have the same molecular formula.\nStep 2: State that their atoms are connected differently.\nStep 3: Combine both conditions into a definition.","steps":["Step 1: State that the compounds have the same molecular formula.","Step 2: State that their atoms are connected differently.","Step 3: Combine both conditions into a definition."],"options":[],"conceptId":"chemistry_organic_chemistry_structural_isomerism","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Structural Isomerism"}', 0),
  (3955, 887, 'Write the names and condensed structural formulae of the two structural isomers of C₄H₁₀.', 'text', 1, 'Focus on the core principle of Structural Isomerism.', '{"why":"Both structures contain C₄H₁₀, but their carbon atoms are connected differently.","sol":"Step 1: Draw the straight four-carbon chain: CH₃CH₂CH₂CH₃.\nStep 2: Name it butane.\nStep 3: Form a branched structure with a three-carbon parent chain and a methyl group on carbon 2.\nStep 4: Write CH₃CH(CH₃)CH₃.\nStep 5: Name it 2-methylpropane.","steps":["Step 1: Draw the straight four-carbon chain: CH₃CH₂CH₂CH₃.","Step 2: Name it butane.","Step 3: Form a branched structure with a three-carbon parent chain and a methyl group on carbon 2.","Step 4: Write CH₃CH(CH₃)CH₃.","Step 5: Name it 2-methylpropane."],"options":[],"conceptId":"chemistry_organic_chemistry_structural_isomerism","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Structural Isomerism"}', 1),
  (3956, 887, 'How many structural isomers does C₅H₁₂ have?', 'text', 1, 'Focus on the core principle of Structural Isomerism.', '{"why":"C₅H₁₂ has three distinct carbon skeletons.","sol":"Step 1: List the unbranched structure: pentane.\nStep 2: List the singly branched structure: 2-methylbutane.\nStep 3: List the structure with a three-carbon parent chain and two methyl branches: 2,2-dimethylpropane.\nStep 4: Check that none of these structures are duplicates when reversed.\nStep 5: Count the distinct structures.","steps":["Step 1: List the unbranched structure: pentane.","Step 2: List the singly branched structure: 2-methylbutane.","Step 3: List the structure with a three-carbon parent chain and two methyl branches: 2,2-dimethylpropane.","Step 4: Check that none of these structures are duplicates when reversed.","Step 5: Count the distinct structures."],"options":[],"conceptId":"chemistry_organic_chemistry_structural_isomerism","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Structural Isomerism"}', 2),
  (3957, 887, 'Are butane and 2-methylpropane structural isomers? Justify your answer.', 'text', 1, 'Compare both their molecular formulae and their carbon skeletons.', '{"why":"Same formula and different connectivity are the defining conditions for structural isomerism.","sol":"Step 1: Butane has molecular formula C₄H₁₀.\nStep 2: 2-methylpropane also has molecular formula C₄H₁₀.\nStep 3: Butane has a straight carbon chain.\nStep 4: 2-methylpropane has a branched carbon skeleton.\nStep 5: Conclude whether both requirements are met.","steps":["Step 1: Butane has molecular formula C₄H₁₀.","Step 2: 2-methylpropane also has molecular formula C₄H₁₀.","Step 3: Butane has a straight carbon chain.","Step 4: 2-methylpropane has a branched carbon skeleton.","Step 5: Conclude whether both requirements are met."],"options":[],"conceptId":"chemistry_organic_chemistry_structural_isomerism","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Structural Isomerism"}', 3),
  (3958, 887, 'Are propane, C₃H₈, and butane, C₄H₁₀, structural isomers?', 'text', 1, 'Start by comparing the molecular formulae.', '{"why":"Structural isomers must have the same molecular formula.","sol":"Step 1: Propane has three carbon atoms and eight hydrogen atoms.\nStep 2: Butane has four carbon atoms and ten hydrogen atoms.\nStep 3: Their molecular formulae are different.\nStep 4: Therefore, they cannot be structural isomers.","steps":["Step 1: Propane has three carbon atoms and eight hydrogen atoms.","Step 2: Butane has four carbon atoms and ten hydrogen atoms.","Step 3: Their molecular formulae are different.","Step 4: Therefore, they cannot be structural isomers."],"options":[],"conceptId":"chemistry_organic_chemistry_structural_isomerism","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Structural Isomerism"}', 4),
  (3959, 887, 'Explain why CH₃CH₂CH₂CH₃ and CH₃CH(CH₃)CH₃ have the same molecular formula.', 'text', 1, 'Count the carbon and hydrogen atoms in each structure.', '{"why":"Changing the carbon skeleton does not necessarily change the total number of atoms.","sol":"Step 1: In CH₃CH₂CH₂CH₃, there are four carbon atoms.\nStep 2: Its hydrogen count is 3 + 2 + 2 + 3 = 10.\nStep 3: In CH₃CH(CH₃)CH₃, there are also four carbon atoms.\nStep 4: Its hydrogen count is 3 + 1 + 3 + 3 = 10.\nStep 5: Both therefore have formula C₄H₁₀.","steps":["Step 1: In CH₃CH₂CH₂CH₃, there are four carbon atoms.","Step 2: Its hydrogen count is 3 + 2 + 2 + 3 = 10.","Step 3: In CH₃CH(CH₃)CH₃, there are also four carbon atoms.","Step 4: Its hydrogen count is 3 + 1 + 3 + 3 = 10.","Step 5: Both therefore have formula C₄H₁₀."],"options":[],"conceptId":"chemistry_organic_chemistry_structural_isomerism","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q6","subject":"chemistry","chapter":"organic_chemistry","topic":"Structural Isomerism"}', 5),
  (3960, 887, 'Name the three structural isomers of C₅H₁₂.', 'text', 1, 'Consider a straight chain, one branch, and two branches.', '{"why":"These are the three distinct carbon skeletons possible for C₅H₁₂.","sol":"Step 1: The straight-chain structure is pentane.\nStep 2: A four-carbon chain with one methyl branch gives 2-methylbutane.\nStep 3: A three-carbon parent chain with two methyl groups on carbon 2 gives 2,2-dimethylpropane.","steps":["Step 1: The straight-chain structure is pentane.","Step 2: A four-carbon chain with one methyl branch gives 2-methylbutane.","Step 3: A three-carbon parent chain with two methyl groups on carbon 2 gives 2,2-dimethylpropane."],"options":[],"conceptId":"chemistry_organic_chemistry_structural_isomerism","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q7","subject":"chemistry","chapter":"organic_chemistry","topic":"Structural Isomerism"}', 6),
  (3961, 887, 'Explain the difference between structural isomers and geometric isomers.', 'text', 1, 'Compare atom connectivity with spatial arrangement.', '{"why":"The two types of isomerism arise from different structural features.","sol":"Step 1: Structural isomers have the same molecular formula but different atom connectivity.\nStep 2: Geometric isomers have the same connectivity.\nStep 3: Geometric isomers differ in the spatial arrangement of groups, commonly around a restricted C=C bond.\nStep 4: State the distinction clearly.","steps":["Step 1: Structural isomers have the same molecular formula but different atom connectivity.","Step 2: Geometric isomers have the same connectivity.","Step 3: Geometric isomers differ in the spatial arrangement of groups, commonly around a restricted C=C bond.","Step 4: State the distinction clearly."],"options":[],"conceptId":"chemistry_organic_chemistry_structural_isomerism","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q8","subject":"chemistry","chapter":"organic_chemistry","topic":"Structural Isomerism"}', 7),
  (3962, 888, 'Define geometric isomerism.', 'text', 1, 'Focus on the core principle of Geometric Isomerism.', '{"why":"The atoms remain connected in the same order; the difference is their arrangement in space.","sol":"Step 1: State that the compounds have the same molecular formula.\nStep 2: State that the atoms have the same connectivity.\nStep 3: Explain that the groups differ in spatial arrangement around a restricted bond.","steps":["Step 1: State that the compounds have the same molecular formula.","Step 2: State that the atoms have the same connectivity.","Step 3: Explain that the groups differ in spatial arrangement around a restricted bond."],"options":[],"conceptId":"chemistry_organic_chemistry_geometric_isomerism","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Geometric Isomerism"}', 0),
  (3963, 888, 'Distinguish between cis-but-2-ene and trans-but-2-ene.', 'text', 1, 'Focus on the core principle of Geometric Isomerism.', '{"why":"The forms differ in the spatial arrangement around the restricted double bond.","sol":"Step 1: Both are forms of but-2-ene and have formula C₄H₈.\nStep 2: In cis-but-2-ene, the methyl groups lie on the same side of the C=C bond.\nStep 3: In trans-but-2-ene, the methyl groups lie on opposite sides.","steps":["Step 1: Both are forms of but-2-ene and have formula C₄H₈.","Step 2: In cis-but-2-ene, the methyl groups lie on the same side of the C=C bond.","Step 3: In trans-but-2-ene, the methyl groups lie on opposite sides."],"options":[],"conceptId":"chemistry_organic_chemistry_geometric_isomerism","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Geometric Isomerism"}', 1),
  (3964, 888, 'Give the two conditions needed for an alkene to show cis-trans geometric isomerism.', 'text', 1, 'Focus on the core principle of Geometric Isomerism.', '{"why":"Both conditions are required for the common cis-trans distinction in alkenes.","sol":"Step 1: Identify the restricted carbon-carbon double bond.\nStep 2: Check the groups attached to the first double-bonded carbon.\nStep 3: Check the groups attached to the second double-bonded carbon.\nStep 4: Each double-bonded carbon must have two different groups attached.","steps":["Step 1: Identify the restricted carbon-carbon double bond.","Step 2: Check the groups attached to the first double-bonded carbon.","Step 3: Check the groups attached to the second double-bonded carbon.","Step 4: Each double-bonded carbon must have two different groups attached."],"options":[],"conceptId":"chemistry_organic_chemistry_geometric_isomerism","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Geometric Isomerism"}', 2),
  (3965, 888, 'Can butane show cis-trans geometric isomerism? Explain your answer.', 'text', 1, 'Inspect the types of carbon-carbon bonds in butane.', '{"why":"The common cis-trans form discussed for alkenes depends on restricted rotation around a double bond.","sol":"Step 1: Butane has only carbon-carbon single bonds.\nStep 2: It has no C=C double bond.\nStep 3: Therefore, it lacks the restricted double bond required for the usual cis-trans alkene isomerism.","steps":["Step 1: Butane has only carbon-carbon single bonds.","Step 2: It has no C=C double bond.","Step 3: Therefore, it lacks the restricted double bond required for the usual cis-trans alkene isomerism."],"options":[],"conceptId":"chemistry_organic_chemistry_geometric_isomerism","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Geometric Isomerism"}', 3),
  (3966, 888, 'Explain why but-2-ene can show geometric isomerism but but-1-ene cannot show cis-trans isomerism.', 'text', 1, 'Check the groups attached to each carbon of the double bond.', '{"why":"Each double-bonded carbon must have two different groups for the usual cis-trans isomerism.","sol":"Step 1: But-2-ene has a C=C bond between carbon 2 and carbon 3.\nStep 2: Each of those carbons has a hydrogen and a methyl group attached.\nStep 3: The two different groups on each carbon allow cis and trans arrangements.\nStep 4: In but-1-ene, the terminal double-bonded carbon is CH₂ and has two identical hydrogen atoms.\nStep 5: Therefore, but-1-ene does not have cis-trans isomerism.","steps":["Step 1: But-2-ene has a C=C bond between carbon 2 and carbon 3.","Step 2: Each of those carbons has a hydrogen and a methyl group attached.","Step 3: The two different groups on each carbon allow cis and trans arrangements.","Step 4: In but-1-ene, the terminal double-bonded carbon is CH₂ and has two identical hydrogen atoms.","Step 5: Therefore, but-1-ene does not have cis-trans isomerism."],"options":[],"conceptId":"chemistry_organic_chemistry_geometric_isomerism","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Geometric Isomerism"}', 4),
  (3967, 888, 'In cis-but-2-ene, where are the two methyl groups positioned relative to the C=C bond?', 'text', 1, 'Recall the meaning of the prefix cis.', '{"why":"Cis describes the same-side arrangement in this pair of geometric isomers.","sol":"Step 1: Identify the two methyl groups attached to the double-bonded carbons.\nStep 2: Apply the meaning of cis: same side.\nStep 3: Place both methyl groups on the same side of the C=C bond.","steps":["Step 1: Identify the two methyl groups attached to the double-bonded carbons.","Step 2: Apply the meaning of cis: same side.","Step 3: Place both methyl groups on the same side of the C=C bond."],"options":[],"conceptId":"chemistry_organic_chemistry_geometric_isomerism","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q6","subject":"chemistry","chapter":"organic_chemistry","topic":"Geometric Isomerism"}', 5),
  (3968, 888, 'Why is rotation around a carbon-carbon double bond restricted?', 'text', 1, 'Consider the two components of a double bond.', '{"why":"The pi bond prevents the free rotation possible around an ordinary carbon-carbon single bond.","sol":"Step 1: A C=C double bond consists of a sigma bond and a pi bond.\nStep 2: The pi bond results from sideways overlap of p orbitals.\nStep 3: Rotation would disrupt that sideways overlap.\nStep 4: Significant rotation therefore requires breaking the pi-bond interaction, so it is restricted under ordinary conditions.","steps":["Step 1: A C=C double bond consists of a sigma bond and a pi bond.","Step 2: The pi bond results from sideways overlap of p orbitals.","Step 3: Rotation would disrupt that sideways overlap.","Step 4: Significant rotation therefore requires breaking the pi-bond interaction, so it is restricted under ordinary conditions."],"options":[],"conceptId":"chemistry_organic_chemistry_geometric_isomerism","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q7","subject":"chemistry","chapter":"organic_chemistry","topic":"Geometric Isomerism"}', 6),
  (3969, 888, 'Explain one difference between structural isomerism and geometric isomerism.', 'text', 1, 'Ask whether the atoms are connected differently or only arranged differently in space.', '{"why":"The distinction is whether the bonding arrangement changes or only the arrangement in space changes.","sol":"Step 1: Structural isomers have the same molecular formula but different atom connectivity.\nStep 2: Geometric isomers have the same molecular formula and the same connectivity.\nStep 3: Their difference is the spatial arrangement around a restricted bond.","steps":["Step 1: Structural isomers have the same molecular formula but different atom connectivity.","Step 2: Geometric isomers have the same molecular formula and the same connectivity.","Step 3: Their difference is the spatial arrangement around a restricted bond."],"options":[],"conceptId":"chemistry_organic_chemistry_geometric_isomerism","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q8","subject":"chemistry","chapter":"organic_chemistry","topic":"Geometric Isomerism"}', 7),
  (3970, 889, 'State the functional group of alcohols.', 'text', 1, 'Focus on the core principle of Alcohols.', '{"why":"The hydroxyl group attached to a saturated carbon atom identifies an alcohol.","sol":"Step 1: Recall the characteristic group of an alcohol.\nStep 2: It consists of one oxygen atom bonded to one hydrogen atom.\nStep 3: It is represented as –OH.","steps":["Step 1: Recall the characteristic group of an alcohol.","Step 2: It consists of one oxygen atom bonded to one hydrogen atom.","Step 3: It is represented as –OH."],"options":[],"conceptId":"chemistry_organic_chemistry_alcohols","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Alcohols"}', 0),
  (3971, 889, 'Classify CH₃CH₂CH₂OH and give a reason.', 'text', 1, 'Focus on the core principle of Alcohols.', '{"why":"The hydroxyl group is the functional group that characterises alcohols.","sol":"Step 1: Examine the displayed formula.\nStep 2: Identify the –OH group.\nStep 3: The –OH group is attached to a three-carbon chain.\nStep 4: Therefore, the compound belongs to the alcohol family.","steps":["Step 1: Examine the displayed formula.","Step 2: Identify the –OH group.","Step 3: The –OH group is attached to a three-carbon chain.","Step 4: Therefore, the compound belongs to the alcohol family."],"options":[],"conceptId":"chemistry_organic_chemistry_alcohols","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Alcohols"}', 1),
  (3972, 889, 'Explain the difference between the functional groups –OH and –COOH.', 'text', 1, 'Focus on the core principle of Alcohols.', '{"why":"The functional group, not simply the presence of oxygen, determines the organic compound family.","sol":"Step 1: –OH contains one oxygen atom and one hydrogen atom.\nStep 2: –OH is the hydroxyl group found in alcohols when attached to a saturated carbon atom.\nStep 3: –COOH contains a carbonyl part, C=O, and a hydroxyl part, –OH.\nStep 4: –COOH is the carboxyl group found in carboxylic acids.","steps":["Step 1: –OH contains one oxygen atom and one hydrogen atom.","Step 2: –OH is the hydroxyl group found in alcohols when attached to a saturated carbon atom.","Step 3: –COOH contains a carbonyl part, C=O, and a hydroxyl part, –OH.","Step 4: –COOH is the carboxyl group found in carboxylic acids."],"options":[],"conceptId":"chemistry_organic_chemistry_alcohols","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Alcohols"}', 2),
  (3973, 889, 'Identify the functional group in CH₃OH.', 'text', 1, 'Look at the group attached to the carbon-containing part.', '{"why":"Methanol is an alcohol because it contains the hydroxyl functional group.","sol":"Step 1: Write the formula as CH₃–OH.\nStep 2: Identify the –OH group.\nStep 3: Name this group.","steps":["Step 1: Write the formula as CH₃–OH.","Step 2: Identify the –OH group.","Step 3: Name this group."],"options":[],"conceptId":"chemistry_organic_chemistry_alcohols","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Alcohols"}', 3),
  (3974, 889, 'Explain why CH₃CH₂OH is classified as an alcohol.', 'text', 1, 'Find the characteristic functional group in the formula.', '{"why":"Alcohols are identified by the hydroxyl functional group attached to a saturated carbon atom.","sol":"Step 1: Examine CH₃CH₂OH.\nStep 2: Locate the –OH group.\nStep 3: Confirm that the group is attached to the carbon chain.\nStep 4: Classify the compound using this functional group.","steps":["Step 1: Examine CH₃CH₂OH.","Step 2: Locate the –OH group.","Step 3: Confirm that the group is attached to the carbon chain.","Step 4: Classify the compound using this functional group."],"options":[],"conceptId":"chemistry_organic_chemistry_alcohols","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Alcohols"}', 4),
  (3975, 889, 'How many carbon atoms are present in CH₃CH₂CH₂OH?', 'text', 1, 'Count each carbon-containing group beginning with C.', '{"why":"The compound is a three-carbon alcohol, propan-1-ol.","sol":"Step 1: The group CH₃ contains one carbon atom.\nStep 2: The first CH₂ contains one carbon atom.\nStep 3: The second CH₂ contains one carbon atom.\nStep 4: Add them: 1 + 1 + 1 = 3.","steps":["Step 1: The group CH₃ contains one carbon atom.","Step 2: The first CH₂ contains one carbon atom.","Step 3: The second CH₂ contains one carbon atom.","Step 4: Add them: 1 + 1 + 1 = 3."],"options":[],"conceptId":"chemistry_organic_chemistry_alcohols","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q6","subject":"chemistry","chapter":"organic_chemistry","topic":"Alcohols"}', 5),
  (3976, 889, 'A learner says that CH₃COOH is an alcohol because it contains –OH. Explain the error.', 'text', 1, 'Look at the complete functional group, not just part of it.', '{"why":"The –OH within a carboxyl group does not make the whole compound an alcohol.","sol":"Step 1: Examine the complete formula CH₃COOH.\nStep 2: The functional group is –COOH.\nStep 3: This group is called the carboxyl group.\nStep 4: Therefore, the compound is a carboxylic acid, not an alcohol.","steps":["Step 1: Examine the complete formula CH₃COOH.","Step 2: The functional group is –COOH.","Step 3: This group is called the carboxyl group.","Step 4: Therefore, the compound is a carboxylic acid, not an alcohol."],"options":[],"conceptId":"chemistry_organic_chemistry_alcohols","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q7","subject":"chemistry","chapter":"organic_chemistry","topic":"Alcohols"}', 6),
  (3977, 889, 'Write the condensed structural formula of a three-carbon alcohol with the –OH group on an end carbon.', 'text', 1, 'Arrange three carbon atoms in a chain and place –OH at the end.', '{"why":"This is propan-1-ol, a three-carbon alcohol with the hydroxyl group on carbon 1.","sol":"Step 1: Three carbon atoms give a three-carbon chain.\nStep 2: Place the hydroxyl group on an end carbon.\nStep 3: Complete the carbon valencies with hydrogen.\nStep 4: The resulting formula is CH₃CH₂CH₂OH.","steps":["Step 1: Three carbon atoms give a three-carbon chain.","Step 2: Place the hydroxyl group on an end carbon.","Step 3: Complete the carbon valencies with hydrogen.","Step 4: The resulting formula is CH₃CH₂CH₂OH."],"options":[],"conceptId":"chemistry_organic_chemistry_alcohols","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q8","subject":"chemistry","chapter":"organic_chemistry","topic":"Alcohols"}', 7),
  (3978, 890, 'Write the molecular formula of ethanol.', 'text', 1, 'Focus on the core principle of Ethanol.', '{"why":"The molecular formula gives the total number of each type of atom in a molecule.","sol":"Step 1: Ethanol can be written as C₂H₅OH.\nStep 2: Count the five hydrogen atoms in C₂H₅.\nStep 3: Add the hydrogen in OH to obtain six hydrogen atoms.\nStep 4: Write the molecular formula using the total number of each atom.","steps":["Step 1: Ethanol can be written as C₂H₅OH.","Step 2: Count the five hydrogen atoms in C₂H₅.","Step 3: Add the hydrogen in OH to obtain six hydrogen atoms.","Step 4: Write the molecular formula using the total number of each atom."],"options":[],"conceptId":"chemistry_organic_chemistry_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Ethanol"}', 0),
  (3979, 890, 'Write the condensed structural formula of ethanol.', 'text', 1, 'Focus on the core principle of Ethanol.', '{"why":"This formula shows the two-carbon chain and the hydroxyl group.","sol":"Step 1: Ethanol has two carbon atoms.\nStep 2: Join the two carbon groups by a single bond.\nStep 3: Attach the hydroxyl group, –OH.\nStep 4: Complete the carbon valencies with hydrogen.","steps":["Step 1: Ethanol has two carbon atoms.","Step 2: Join the two carbon groups by a single bond.","Step 3: Attach the hydroxyl group, –OH.","Step 4: Complete the carbon valencies with hydrogen."],"options":[],"conceptId":"chemistry_organic_chemistry_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Ethanol"}', 1),
  (3980, 890, 'Calculate the relative molecular mass of C₂H₆O using C = 12, H = 1 and O = 16.', 'text', 1, 'Focus on the core principle of Ethanol.', '{"why":"Relative molecular mass is the sum of the relative atomic masses of all atoms in the molecule.","sol":"Step 1: Carbon: 2 × 12 = 24.\nStep 2: Hydrogen: 6 × 1 = 6.\nStep 3: Oxygen: 1 × 16 = 16.\nStep 4: Total = 24 + 6 + 16 = 46.","steps":["Step 1: Carbon: 2 × 12 = 24.","Step 2: Hydrogen: 6 × 1 = 6.","Step 3: Oxygen: 1 × 16 = 16.","Step 4: Total = 24 + 6 + 16 = 46."],"options":[],"conceptId":"chemistry_organic_chemistry_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Ethanol"}', 2),
  (3981, 890, 'How many oxygen atoms are present in one molecule of ethanol?', 'text', 1, 'Examine the O symbol in C₂H₆O.', '{"why":"C₂H₆O contains one oxygen atom.","sol":"Step 1: Locate O in the formula.\nStep 2: No subscript follows O.\nStep 3: An element symbol without a subscript represents one atom.","steps":["Step 1: Locate O in the formula.","Step 2: No subscript follows O.","Step 3: An element symbol without a subscript represents one atom."],"options":[],"conceptId":"chemistry_organic_chemistry_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Ethanol"}', 3),
  (3982, 890, 'Explain why C₂H₅OH and C₂H₆O represent ethanol.', 'text', 1, 'Count all the atoms in C₂H₅OH.', '{"why":"C₂H₅OH highlights the hydroxyl group, while C₂H₆O gives the total atom count.","sol":"Step 1: C₂H₅OH contains two carbon atoms.\nStep 2: It contains five hydrogen atoms in C₂H₅ and one hydrogen in OH.\nStep 3: Its total is six hydrogen atoms and one oxygen atom.\nStep 4: The molecular formula is therefore C₂H₆O.","steps":["Step 1: C₂H₅OH contains two carbon atoms.","Step 2: It contains five hydrogen atoms in C₂H₅ and one hydrogen in OH.","Step 3: Its total is six hydrogen atoms and one oxygen atom.","Step 4: The molecular formula is therefore C₂H₆O."],"options":[],"conceptId":"chemistry_organic_chemistry_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Ethanol"}', 4),
  (3983, 890, 'Calculate the relative molecular mass of ethanol using C = 12, H = 1 and O = 16.', 'text', 1, 'Use 2 carbon atoms, 6 hydrogen atoms and 1 oxygen atom.', '{"why":"The relative molecular mass of ethanol is 46.","sol":"Step 1: Carbon mass = 2 × 12 = 24.\nStep 2: Hydrogen mass = 6 × 1 = 6.\nStep 3: Oxygen mass = 1 × 16 = 16.\nStep 4: Add 24 + 6 + 16.","steps":["Step 1: Carbon mass = 2 × 12 = 24.","Step 2: Hydrogen mass = 6 × 1 = 6.","Step 3: Oxygen mass = 1 × 16 = 16.","Step 4: Add 24 + 6 + 16."],"options":[],"conceptId":"chemistry_organic_chemistry_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q6","subject":"chemistry","chapter":"organic_chemistry","topic":"Ethanol"}', 5),
  (3984, 890, 'How many hydrogen atoms are in one molecule of ethanol, C₂H₅OH?', 'text', 1, 'Do not forget the hydrogen written in the OH group.', '{"why":"The condensed formula separates the hydroxyl group, so its hydrogen must also be counted.","sol":"Step 1: The C₂H₅ part contains five hydrogen atoms.\nStep 2: The OH group contains one hydrogen atom.\nStep 3: Total hydrogen atoms = 5 + 1 = 6.","steps":["Step 1: The C₂H₅ part contains five hydrogen atoms.","Step 2: The OH group contains one hydrogen atom.","Step 3: Total hydrogen atoms = 5 + 1 = 6."],"options":[],"conceptId":"chemistry_organic_chemistry_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q7","subject":"chemistry","chapter":"organic_chemistry","topic":"Ethanol"}', 6),
  (3985, 890, 'Calculate the percentage by mass of carbon in ethanol, C₂H₆O. Use C = 12, H = 1 and O = 16.', 'text', 1, 'First calculate the total relative molecular mass.', '{"why":"Percentage by mass is the mass contributed by the element divided by the total molecular mass, multiplied by 100.","sol":"Step 1: Relative molecular mass = (2 × 12) + (6 × 1) + 16 = 46.\nStep 2: Mass contributed by carbon = 2 × 12 = 24.\nStep 3: Percentage of carbon = (24 ÷ 46) × 100.\nStep 4: Percentage of carbon ≈ 52.2%.","steps":["Step 1: Relative molecular mass = (2 × 12) + (6 × 1) + 16 = 46.","Step 2: Mass contributed by carbon = 2 × 12 = 24.","Step 3: Percentage of carbon = (24 ÷ 46) × 100.","Step 4: Percentage of carbon ≈ 52.2%."],"options":[],"conceptId":"chemistry_organic_chemistry_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q8","subject":"chemistry","chapter":"organic_chemistry","topic":"Ethanol"}', 7),
  (3986, 891, 'State two physical properties of ethanol.', 'text', 1, 'Focus on the core principle of Properties of Ethanol.', '{"why":"These are physical properties because observing them does not itself change ethanol into a new substance.","sol":"Step 1: Recall properties that can be observed without a chemical reaction.\nStep 2: Ethanol is a colourless liquid.\nStep 3: It is volatile and miscible with water.\nStep 4: State any two of these properties.","steps":["Step 1: Recall properties that can be observed without a chemical reaction.","Step 2: Ethanol is a colourless liquid.","Step 3: It is volatile and miscible with water.","Step 4: State any two of these properties."],"options":[],"conceptId":"chemistry_organic_chemistry_properties_of_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Properties of Ethanol"}', 0),
  (3987, 891, 'State the products of complete combustion of ethanol.', 'text', 1, 'Focus on the core principle of Properties of Ethanol.', '{"why":"Complete combustion of an organic compound containing carbon and hydrogen produces carbon dioxide and water.","sol":"Step 1: Complete combustion occurs in sufficient oxygen.\nStep 2: Carbon in ethanol forms carbon dioxide.\nStep 3: Hydrogen in ethanol forms water.","steps":["Step 1: Complete combustion occurs in sufficient oxygen.","Step 2: Carbon in ethanol forms carbon dioxide.","Step 3: Hydrogen in ethanol forms water."],"options":[],"conceptId":"chemistry_organic_chemistry_properties_of_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Properties of Ethanol"}', 1),
  (3988, 891, 'Balance C₂H₅OH + O₂ → CO₂ + H₂O.', 'text', 1, 'Focus on the core principle of Properties of Ethanol.', '{"why":"A balanced equation has the same number of each type of atom on both sides.","sol":"Step 1: Balance carbon by placing 2 before CO₂.\nStep 2: Balance hydrogen by placing 3 before H₂O.\nStep 3: The products now contain 7 oxygen atoms.\nStep 4: Ethanol supplies 1 oxygen atom, so 6 more are needed from 3O₂.","steps":["Step 1: Balance carbon by placing 2 before CO₂.","Step 2: Balance hydrogen by placing 3 before H₂O.","Step 3: The products now contain 7 oxygen atoms.","Step 4: Ethanol supplies 1 oxygen atom, so 6 more are needed from 3O₂."],"options":[],"conceptId":"chemistry_organic_chemistry_properties_of_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Properties of Ethanol"}', 2),
  (3989, 891, 'Explain why ethanol is described as flammable.', 'text', 1, 'Think about its behaviour when ignited in oxygen.', '{"why":"A flammable substance can catch fire and undergo combustion.","sol":"Step 1: Ethanol reacts with oxygen when ignited.\nStep 2: The reaction is combustion.\nStep 3: Combustion releases energy as heat and light.","steps":["Step 1: Ethanol reacts with oxygen when ignited.","Step 2: The reaction is combustion.","Step 3: Combustion releases energy as heat and light."],"options":[],"conceptId":"chemistry_organic_chemistry_properties_of_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Properties of Ethanol"}', 3),
  (3990, 891, 'Explain the meaning of the statement that ethanol is miscible with water.', 'text', 1, 'Think about whether the liquids form separate layers.', '{"why":"Miscible liquids mix completely in all proportions.","sol":"Step 1: Consider mixing ethanol with water.\nStep 2: The two liquids mix completely.\nStep 3: They form one uniform liquid rather than two separate layers.","steps":["Step 1: Consider mixing ethanol with water.","Step 2: The two liquids mix completely.","Step 3: They form one uniform liquid rather than two separate layers."],"options":[],"conceptId":"chemistry_organic_chemistry_properties_of_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Properties of Ethanol"}', 4),
  (3991, 891, 'Balance the complete combustion equation for ethanol: C₂H₅OH + O₂ → CO₂ + H₂O.', 'text', 1, 'Balance carbon, then hydrogen, then oxygen.', '{"why":"The coefficients conserve the number of carbon, hydrogen and oxygen atoms.","sol":"Step 1: Balance 2 carbon atoms by writing 2CO₂.\nStep 2: Balance 6 hydrogen atoms by writing 3H₂O.\nStep 3: Count 7 oxygen atoms among the products.\nStep 4: One oxygen atom comes from ethanol.\nStep 5: The remaining 6 oxygen atoms require 3O₂.","steps":["Step 1: Balance 2 carbon atoms by writing 2CO₂.","Step 2: Balance 6 hydrogen atoms by writing 3H₂O.","Step 3: Count 7 oxygen atoms among the products.","Step 4: One oxygen atom comes from ethanol.","Step 5: The remaining 6 oxygen atoms require 3O₂."],"options":[],"conceptId":"chemistry_organic_chemistry_properties_of_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q6","subject":"chemistry","chapter":"organic_chemistry","topic":"Properties of Ethanol"}', 5),
  (3992, 891, 'Is the flammability of ethanol a physical or chemical property? Explain.', 'text', 1, 'Ask whether burning creates new substances.', '{"why":"Flammability describes a substance''s ability to undergo a chemical reaction.","sol":"Step 1: A physical property can be observed without forming a new substance.\nStep 2: During burning, ethanol reacts with oxygen.\nStep 3: Carbon dioxide and water are formed.\nStep 4: Formation of new substances indicates a chemical change.","steps":["Step 1: A physical property can be observed without forming a new substance.","Step 2: During burning, ethanol reacts with oxygen.","Step 3: Carbon dioxide and water are formed.","Step 4: Formation of new substances indicates a chemical change."],"options":[],"conceptId":"chemistry_organic_chemistry_properties_of_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q7","subject":"chemistry","chapter":"organic_chemistry","topic":"Properties of Ethanol"}', 6),
  (3993, 891, 'Using the balanced equation C₂H₅OH + 3O₂ → 2CO₂ + 3H₂O, how many moles of carbon dioxide form from 4 moles of ethanol in complete combustion?', 'text', 1, 'Use the mole ratio between ethanol and carbon dioxide.', '{"why":"The coefficients in a balanced equation give the mole ratios of reactants and products.","sol":"Step 1: The equation shows 1 mole of ethanol produces 2 moles of CO₂.\nStep 2: The ratio is ethanol:CO₂ = 1:2.\nStep 3: For 4 moles of ethanol, carbon dioxide = 4 × 2.\nStep 4: The result is 8 moles.","steps":["Step 1: The equation shows 1 mole of ethanol produces 2 moles of CO₂.","Step 2: The ratio is ethanol:CO₂ = 1:2.","Step 3: For 4 moles of ethanol, carbon dioxide = 4 × 2.","Step 4: The result is 8 moles."],"options":[],"conceptId":"chemistry_organic_chemistry_properties_of_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q8","subject":"chemistry","chapter":"organic_chemistry","topic":"Properties of Ethanol"}', 7),
  (3994, 892, 'Define alcoholic fermentation.', 'text', 1, 'Focus on the core principle of Fermentation.', '{"why":"Alcoholic fermentation produces ethanol and carbon dioxide when yeast acts on sugar in the absence or near absence of oxygen.","sol":"Step 1: Identify the reactant as a sugar such as glucose.\nStep 2: Identify yeast as the microorganism responsible.\nStep 3: State the products and the oxygen conditions.","steps":["Step 1: Identify the reactant as a sugar such as glucose.","Step 2: Identify yeast as the microorganism responsible.","Step 3: State the products and the oxygen conditions."],"options":[],"conceptId":"chemistry_organic_chemistry_fermentation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Fermentation"}', 0),
  (3995, 892, 'Write the word equation for alcoholic fermentation.', 'text', 1, 'Focus on the core principle of Fermentation.', '{"why":"The word equation summarises the reactant and products of alcoholic fermentation.","sol":"Step 1: Write glucose as the reactant.\nStep 2: Write ethanol and carbon dioxide as the products.\nStep 3: Separate the reactant from the products using an arrow.","steps":["Step 1: Write glucose as the reactant.","Step 2: Write ethanol and carbon dioxide as the products.","Step 3: Separate the reactant from the products using an arrow."],"options":[],"conceptId":"chemistry_organic_chemistry_fermentation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Fermentation"}', 1),
  (3996, 892, 'Balance C₆H₁₂O₆ → C₂H₅OH + CO₂.', 'text', 1, 'Focus on the core principle of Fermentation.', '{"why":"The equation conserves carbon, hydrogen and oxygen atoms.","sol":"Step 1: Place 2 before ethanol to give 4 carbon atoms and 12 hydrogen atoms.\nStep 2: Place 2 before carbon dioxide to give 2 additional carbon atoms.\nStep 3: Check oxygen: 2 + 4 = 6 oxygen atoms on the product side.\nStep 4: All atoms now balance.","steps":["Step 1: Place 2 before ethanol to give 4 carbon atoms and 12 hydrogen atoms.","Step 2: Place 2 before carbon dioxide to give 2 additional carbon atoms.","Step 3: Check oxygen: 2 + 4 = 6 oxygen atoms on the product side.","Step 4: All atoms now balance."],"options":[],"conceptId":"chemistry_organic_chemistry_fermentation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Fermentation"}', 2),
  (3997, 892, 'Why is oxygen kept out during alcoholic fermentation?', 'text', 1, 'Recall what anaerobic means.', '{"why":"The desired production of ethanol by yeast occurs under conditions with little or no oxygen.","sol":"Step 1: Alcoholic fermentation is an anaerobic process.\nStep 2: Anaerobic means occurring without oxygen.\nStep 3: Limiting oxygen allows yeast to convert glucose into ethanol and carbon dioxide.","steps":["Step 1: Alcoholic fermentation is an anaerobic process.","Step 2: Anaerobic means occurring without oxygen.","Step 3: Limiting oxygen allows yeast to convert glucose into ethanol and carbon dioxide."],"options":[],"conceptId":"chemistry_organic_chemistry_fermentation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Fermentation"}', 3),
  (3998, 892, 'State the role of yeast in fermentation.', 'text', 1, 'Think about what yeast provides that makes the reaction occur.', '{"why":"Enzymes increase the rate of the biochemical reactions involved in fermentation.","sol":"Step 1: Yeast is a microorganism.\nStep 2: It contains enzymes that catalyse biochemical reactions.\nStep 3: These enzymes help convert glucose into ethanol and carbon dioxide.","steps":["Step 1: Yeast is a microorganism.","Step 2: It contains enzymes that catalyse biochemical reactions.","Step 3: These enzymes help convert glucose into ethanol and carbon dioxide."],"options":[],"conceptId":"chemistry_organic_chemistry_fermentation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Fermentation"}', 4),
  (3999, 892, 'Balance the equation C₆H₁₂O₆ → C₂H₅OH + CO₂.', 'text', 1, 'Balance the six carbon atoms first.', '{"why":"The coefficients make the atom counts equal on both sides.","sol":"Step 1: Put 2 before ethanol to account for 4 carbon atoms.\nStep 2: Put 2 before CO₂ to account for the remaining 2 carbon atoms.\nStep 3: Check hydrogen: 2 × 6 = 12.\nStep 4: Check oxygen: 2 oxygen atoms in ethanol plus 4 in CO₂ equals 6.","steps":["Step 1: Put 2 before ethanol to account for 4 carbon atoms.","Step 2: Put 2 before CO₂ to account for the remaining 2 carbon atoms.","Step 3: Check hydrogen: 2 × 6 = 12.","Step 4: Check oxygen: 2 oxygen atoms in ethanol plus 4 in CO₂ equals 6."],"options":[],"conceptId":"chemistry_organic_chemistry_fermentation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q6","subject":"chemistry","chapter":"organic_chemistry","topic":"Fermentation"}', 5),
  (4000, 892, 'How many moles of ethanol can theoretically form from 5 moles of glucose according to the balanced equation?', 'text', 1, 'Use the ratio 1 mole of glucose to 2 moles of ethanol.', '{"why":"The balanced equation gives a glucose-to-ethanol mole ratio of 1:2.","sol":"Step 1: The balanced equation shows 1 mole of glucose produces 2 moles of ethanol.\nStep 2: Multiply the ethanol amount by 5.\nStep 3: Ethanol = 5 × 2 = 10 moles.","steps":["Step 1: The balanced equation shows 1 mole of glucose produces 2 moles of ethanol.","Step 2: Multiply the ethanol amount by 5.","Step 3: Ethanol = 5 × 2 = 10 moles."],"options":[],"conceptId":"chemistry_organic_chemistry_fermentation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q7","subject":"chemistry","chapter":"organic_chemistry","topic":"Fermentation"}', 6);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (4001, 892, 'Explain why an excessively high temperature may reduce fermentation.', 'text', 1, 'Consider the enzymes involved in the process.', '{"why":"Fermentation depends on living yeast and enzymes that require suitable conditions.","sol":"Step 1: Yeast enzymes catalyse fermentation.\nStep 2: Enzymes function within suitable temperature ranges.\nStep 3: Excessive heat can denature enzymes and kill yeast cells.\nStep 4: The rate of fermentation can therefore fall or stop.","steps":["Step 1: Yeast enzymes catalyse fermentation.","Step 2: Enzymes function within suitable temperature ranges.","Step 3: Excessive heat can denature enzymes and kill yeast cells.","Step 4: The rate of fermentation can therefore fall or stop."],"options":[],"conceptId":"chemistry_organic_chemistry_fermentation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q8","subject":"chemistry","chapter":"organic_chemistry","topic":"Fermentation"}', 7),
  (4002, 893, 'Name the product formed when ethanol is oxidised fully under suitable conditions.', 'text', 1, 'Focus on the core principle of Oxidation of Ethanol.', '{"why":"Under suitable conditions, ethanol can be oxidised to ethanoic acid.","sol":"Step 1: Identify ethanol as a two-carbon alcohol.\nStep 2: Oxidation can convert it into a carboxylic acid.\nStep 3: The corresponding two-carbon carboxylic acid is ethanoic acid.","steps":["Step 1: Identify ethanol as a two-carbon alcohol.","Step 2: Oxidation can convert it into a carboxylic acid.","Step 3: The corresponding two-carbon carboxylic acid is ethanoic acid."],"options":[],"conceptId":"chemistry_organic_chemistry_oxidation_of_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Oxidation of Ethanol"}', 0),
  (4003, 893, 'Write the equation for oxidation of ethanol by oxygen to form ethanoic acid and water.', 'text', 1, 'Focus on the core principle of Oxidation of Ethanol.', '{"why":"The equation is balanced with equal numbers of each type of atom on both sides.","sol":"Step 1: Write ethanol as C₂H₅OH.\nStep 2: Add O₂ as the oxidising reactant.\nStep 3: Write ethanoic acid as CH₃COOH and water as H₂O.\nStep 4: Check carbon, hydrogen and oxygen atoms on both sides.","steps":["Step 1: Write ethanol as C₂H₅OH.","Step 2: Add O₂ as the oxidising reactant.","Step 3: Write ethanoic acid as CH₃COOH and water as H₂O.","Step 4: Check carbon, hydrogen and oxygen atoms on both sides."],"options":[],"conceptId":"chemistry_organic_chemistry_oxidation_of_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Oxidation of Ethanol"}', 1),
  (4004, 893, 'Which functional group identifies ethanoic acid?', 'text', 1, 'Focus on the core principle of Oxidation of Ethanol.', '{"why":"The carboxyl group characterises carboxylic acids.","sol":"Step 1: Examine the formula CH₃COOH.\nStep 2: Identify the –COOH group.\nStep 3: Name the group.","steps":["Step 1: Examine the formula CH₃COOH.","Step 2: Identify the –COOH group.","Step 3: Name the group."],"options":[],"conceptId":"chemistry_organic_chemistry_oxidation_of_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Oxidation of Ethanol"}', 2),
  (4005, 893, 'Name the two-carbon carboxylic acid produced by oxidation of ethanol.', 'text', 1, 'The name begins with eth- and ends with -oic acid.', '{"why":"Ethanoic acid is formed when ethanol is oxidised under suitable conditions.","sol":"Step 1: Ethanol contains two carbon atoms.\nStep 2: Oxidation produces the corresponding carboxylic acid.\nStep 3: The two-carbon carboxylic acid is ethanoic acid.","steps":["Step 1: Ethanol contains two carbon atoms.","Step 2: Oxidation produces the corresponding carboxylic acid.","Step 3: The two-carbon carboxylic acid is ethanoic acid."],"options":[],"conceptId":"chemistry_organic_chemistry_oxidation_of_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Oxidation of Ethanol"}', 3),
  (4006, 893, 'Balance the equation: C₂H₅OH + O₂ → CH₃COOH + H₂O.', 'text', 1, 'Count carbon, hydrogen and oxygen atoms on each side before changing coefficients.', '{"why":"All atom counts are already equal, so all coefficients are 1.","sol":"Step 1: Left side: 2 carbon, 6 hydrogen and 3 oxygen atoms.\nStep 2: Right side: CH₃COOH contains 2 carbon, 4 hydrogen and 2 oxygen atoms.\nStep 3: Adding H₂O gives 2 more hydrogen atoms and 1 more oxygen atom.\nStep 4: The right side therefore has 2 carbon, 6 hydrogen and 3 oxygen atoms.","steps":["Step 1: Left side: 2 carbon, 6 hydrogen and 3 oxygen atoms.","Step 2: Right side: CH₃COOH contains 2 carbon, 4 hydrogen and 2 oxygen atoms.","Step 3: Adding H₂O gives 2 more hydrogen atoms and 1 more oxygen atom.","Step 4: The right side therefore has 2 carbon, 6 hydrogen and 3 oxygen atoms."],"options":[],"conceptId":"chemistry_organic_chemistry_oxidation_of_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Oxidation of Ethanol"}', 4),
  (4007, 893, 'Explain why CH₃COOH is classified as a carboxylic acid rather than an alcohol.', 'text', 1, 'Identify the complete functional group.', '{"why":"The complete functional group determines the family of the compound.","sol":"Step 1: Examine the end of the formula.\nStep 2: The functional group is –COOH.\nStep 3: This is the carboxyl group.\nStep 4: Therefore, the compound belongs to the carboxylic acid family.","steps":["Step 1: Examine the end of the formula.","Step 2: The functional group is –COOH.","Step 3: This is the carboxyl group.","Step 4: Therefore, the compound belongs to the carboxylic acid family."],"options":[],"conceptId":"chemistry_organic_chemistry_oxidation_of_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q6","subject":"chemistry","chapter":"organic_chemistry","topic":"Oxidation of Ethanol"}', 5),
  (4008, 893, 'State one laboratory oxidising agent that can oxidise ethanol to ethanoic acid under suitable conditions.', 'text', 1, 'Think of a common acidified reagent used in organic chemistry.', '{"why":"Acidified potassium dichromate(VI) is a common laboratory oxidising agent.","sol":"Step 1: Recall a common oxidising agent used in laboratory oxidation reactions.\nStep 2: Acidified potassium dichromate(VI) is one such reagent.\nStep 3: Under suitable conditions, it oxidises ethanol toward ethanoic acid.","steps":["Step 1: Recall a common oxidising agent used in laboratory oxidation reactions.","Step 2: Acidified potassium dichromate(VI) is one such reagent.","Step 3: Under suitable conditions, it oxidises ethanol toward ethanoic acid."],"options":[],"conceptId":"chemistry_organic_chemistry_oxidation_of_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q7","subject":"chemistry","chapter":"organic_chemistry","topic":"Oxidation of Ethanol"}', 6),
  (4009, 893, 'Explain the relationship between ethanol and ethanoic acid in an oxidation reaction.', 'text', 1, 'State the starting compound, the type of change, and the product.', '{"why":"This reaction links the alcohol and carboxylic acid families.","sol":"Step 1: Ethanol is the starting alcohol.\nStep 2: Oxidation changes the alcohol under suitable conditions.\nStep 3: The product is ethanoic acid, a carboxylic acid.","steps":["Step 1: Ethanol is the starting alcohol.","Step 2: Oxidation changes the alcohol under suitable conditions.","Step 3: The product is ethanoic acid, a carboxylic acid."],"options":[],"conceptId":"chemistry_organic_chemistry_oxidation_of_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q8","subject":"chemistry","chapter":"organic_chemistry","topic":"Oxidation of Ethanol"}', 7),
  (4010, 894, 'State the functional group of carboxylic acids.', 'text', 1, 'Focus on the core principle of Carboxylic Acids.', '{"why":"All carboxylic acids contain the carboxyl functional group.","sol":"Step 1: Recall the characteristic group of this family.\nStep 2: It is written as –COOH.\nStep 3: Its name is the carboxyl group.","steps":["Step 1: Recall the characteristic group of this family.","Step 2: It is written as –COOH.","Step 3: Its name is the carboxyl group."],"options":[],"conceptId":"chemistry_organic_chemistry_carboxylic_acids","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Carboxylic Acids"}', 0),
  (4011, 894, 'Name HCOOH.', 'text', 1, 'Focus on the core principle of Carboxylic Acids.', '{"why":"Methanoic acid is the one-carbon member of the carboxylic acid family.","sol":"Step 1: Count the carbon atoms, including the carboxyl carbon: 1.\nStep 2: Use the prefix meth- for one carbon.\nStep 3: Use the ending -oic acid for a carboxylic acid.","steps":["Step 1: Count the carbon atoms, including the carboxyl carbon: 1.","Step 2: Use the prefix meth- for one carbon.","Step 3: Use the ending -oic acid for a carboxylic acid."],"options":[],"conceptId":"chemistry_organic_chemistry_carboxylic_acids","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Carboxylic Acids"}', 1),
  (4012, 894, 'Write the condensed structural formula of propanoic acid.', 'text', 1, 'Focus on the core principle of Carboxylic Acids.', '{"why":"Propanoic acid has three carbon atoms, including the carbon in –COOH.","sol":"Step 1: The prefix prop- indicates three carbon atoms in total.\nStep 2: The carboxyl group contributes one of these carbon atoms.\nStep 3: Two carbon atoms remain in the chain before the carboxyl group.\nStep 4: Write the structure as CH₃CH₂COOH.","steps":["Step 1: The prefix prop- indicates three carbon atoms in total.","Step 2: The carboxyl group contributes one of these carbon atoms.","Step 3: Two carbon atoms remain in the chain before the carboxyl group.","Step 4: Write the structure as CH₃CH₂COOH."],"options":[],"conceptId":"chemistry_organic_chemistry_carboxylic_acids","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Carboxylic Acids"}', 2),
  (4013, 894, 'Write the general structure of a carboxylic acid.', 'text', 1, 'Use R to represent the rest of the carbon-containing part.', '{"why":"The –COOH group is the defining functional group of carboxylic acids.","sol":"Step 1: Identify the carboxyl functional group, –COOH.\nStep 2: Attach it to the carbon-containing group represented by R.\nStep 3: Write the general structure.","steps":["Step 1: Identify the carboxyl functional group, –COOH.","Step 2: Attach it to the carbon-containing group represented by R.","Step 3: Write the general structure."],"options":[],"conceptId":"chemistry_organic_chemistry_carboxylic_acids","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Carboxylic Acids"}', 3),
  (4014, 894, 'Explain why CH₃COOH is a carboxylic acid.', 'text', 1, 'Identify the complete functional group at the end of the formula.', '{"why":"The carboxyl group determines that CH₃COOH belongs to the carboxylic acid family.","sol":"Step 1: Examine CH₃COOH.\nStep 2: Identify the –COOH group.\nStep 3: Name it as the carboxyl group.\nStep 4: Classify the compound.","steps":["Step 1: Examine CH₃COOH.","Step 2: Identify the –COOH group.","Step 3: Name it as the carboxyl group.","Step 4: Classify the compound."],"options":[],"conceptId":"chemistry_organic_chemistry_carboxylic_acids","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Carboxylic Acids"}', 4),
  (4015, 894, 'Name CH₃CH₂COOH and explain how you counted its carbon atoms.', 'text', 1, 'Include the carbon atom within the –COOH group.', '{"why":"The carbon in the carboxyl group must be included when naming a carboxylic acid.","sol":"Step 1: CH₃ contains one carbon atom.\nStep 2: CH₂ contains one carbon atom.\nStep 3: The COOH group contains one carbon atom.\nStep 4: Total carbon atoms = 1 + 1 + 1 = 3.\nStep 5: The three-carbon carboxylic acid is propanoic acid.","steps":["Step 1: CH₃ contains one carbon atom.","Step 2: CH₂ contains one carbon atom.","Step 3: The COOH group contains one carbon atom.","Step 4: Total carbon atoms = 1 + 1 + 1 = 3.","Step 5: The three-carbon carboxylic acid is propanoic acid."],"options":[],"conceptId":"chemistry_organic_chemistry_carboxylic_acids","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q6","subject":"chemistry","chapter":"organic_chemistry","topic":"Carboxylic Acids"}', 5),
  (4016, 894, 'Explain what the term weak acid means when applied to ethanoic acid.', 'text', 1, 'Think about whether all acid molecules ionise in water.', '{"why":"Acid strength depends on the extent of ionisation in water, not simply on the concentration of the acid.","sol":"Step 1: Ethanoic acid dissolves in water.\nStep 2: Only a proportion of its molecules ionise to form ions.\nStep 3: The ionisation is therefore partial and reversible.\nStep 4: This behaviour identifies ethanoic acid as a weak acid.","steps":["Step 1: Ethanoic acid dissolves in water.","Step 2: Only a proportion of its molecules ionise to form ions.","Step 3: The ionisation is therefore partial and reversible.","Step 4: This behaviour identifies ethanoic acid as a weak acid."],"options":[],"conceptId":"chemistry_organic_chemistry_carboxylic_acids","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q7","subject":"chemistry","chapter":"organic_chemistry","topic":"Carboxylic Acids"}', 6),
  (4017, 894, 'Write an equation showing ethanoic acid donating a hydrogen ion to water.', 'text', 1, 'Water accepts H⁺ to form H₃O⁺.', '{"why":"The equation shows the reversible ionisation of ethanoic acid in water.","sol":"Step 1: Write ethanoic acid as CH₃COOH.\nStep 2: Water accepts a hydrogen ion from the acid.\nStep 3: The acid becomes CH₃COO⁻.\nStep 4: Water becomes H₃O⁺.\nStep 5: Use a reversible arrow because ethanoic acid ionises partially.","steps":["Step 1: Write ethanoic acid as CH₃COOH.","Step 2: Water accepts a hydrogen ion from the acid.","Step 3: The acid becomes CH₃COO⁻.","Step 4: Water becomes H₃O⁺.","Step 5: Use a reversible arrow because ethanoic acid ionises partially."],"options":[],"conceptId":"chemistry_organic_chemistry_carboxylic_acids","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q8","subject":"chemistry","chapter":"organic_chemistry","topic":"Carboxylic Acids"}', 7),
  (4018, 895, 'Write the condensed structural formula of ethanoic acid.', 'text', 1, 'Focus on the core principle of Ethanoic Acid.', '{"why":"Ethanoic acid contains a methyl group attached to the carboxyl group.","sol":"Step 1: Ethanoic acid contains two carbon atoms in total.\nStep 2: The carboxyl group is –COOH and contains one carbon atom.\nStep 3: The remaining carbon forms CH₃–.\nStep 4: Join the groups.","steps":["Step 1: Ethanoic acid contains two carbon atoms in total.","Step 2: The carboxyl group is –COOH and contains one carbon atom.","Step 3: The remaining carbon forms CH₃–.","Step 4: Join the groups."],"options":[],"conceptId":"chemistry_organic_chemistry_ethanoic_acid","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Ethanoic Acid"}', 0),
  (4019, 895, 'Calculate the relative molecular mass of C₂H₄O₂ using C = 12, H = 1 and O = 16.', 'text', 1, 'Focus on the core principle of Ethanoic Acid.', '{"why":"The relative molecular mass is the sum of the contributions from all atoms.","sol":"Step 1: Carbon contribution = 2 × 12 = 24.\nStep 2: Hydrogen contribution = 4 × 1 = 4.\nStep 3: Oxygen contribution = 2 × 16 = 32.\nStep 4: Total = 24 + 4 + 32 = 60.","steps":["Step 1: Carbon contribution = 2 × 12 = 24.","Step 2: Hydrogen contribution = 4 × 1 = 4.","Step 3: Oxygen contribution = 2 × 16 = 32.","Step 4: Total = 24 + 4 + 32 = 60."],"options":[],"conceptId":"chemistry_organic_chemistry_ethanoic_acid","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Ethanoic Acid"}', 1),
  (4020, 895, 'State one common household source of dilute ethanoic acid.', 'text', 1, 'Focus on the core principle of Ethanoic Acid.', '{"why":"Vinegar contains ethanoic acid dissolved in water.","sol":"Step 1: Recall a common food product containing dilute ethanoic acid.\nStep 2: Vinegar is an aqueous solution of ethanoic acid.","steps":["Step 1: Recall a common food product containing dilute ethanoic acid.","Step 2: Vinegar is an aqueous solution of ethanoic acid."],"options":[],"conceptId":"chemistry_organic_chemistry_ethanoic_acid","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Ethanoic Acid"}', 2),
  (4021, 895, 'How many carbon atoms are in one molecule of ethanoic acid, C₂H₄O₂?', 'text', 1, 'Read the subscript after C.', '{"why":"The molecular formula C₂H₄O₂ contains two carbon atoms.","sol":"Step 1: Locate C₂ in the formula.\nStep 2: The subscript 2 indicates two carbon atoms.","steps":["Step 1: Locate C₂ in the formula.","Step 2: The subscript 2 indicates two carbon atoms."],"options":[],"conceptId":"chemistry_organic_chemistry_ethanoic_acid","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Ethanoic Acid"}', 3),
  (4022, 895, 'Explain the difference between pure ethanoic acid and vinegar.', 'text', 1, 'Consider whether vinegar contains only ethanoic acid.', '{"why":"A solution contains a solute dissolved in a solvent, while a pure substance is not a mixture.","sol":"Step 1: Pure ethanoic acid is the substance CH₃COOH.\nStep 2: Vinegar is a solution in which ethanoic acid is dissolved in water.\nStep 3: Therefore, vinegar contains ethanoic acid and water rather than being pure ethanoic acid.","steps":["Step 1: Pure ethanoic acid is the substance CH₃COOH.","Step 2: Vinegar is a solution in which ethanoic acid is dissolved in water.","Step 3: Therefore, vinegar contains ethanoic acid and water rather than being pure ethanoic acid."],"options":[],"conceptId":"chemistry_organic_chemistry_ethanoic_acid","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Ethanoic Acid"}', 4),
  (4023, 895, 'Calculate the relative molecular mass of ethanoic acid, C₂H₄O₂.', 'text', 1, 'Use C = 12, H = 1 and O = 16.', '{"why":"The total relative molecular mass of C₂H₄O₂ is 60.","sol":"Step 1: Carbon: 2 × 12 = 24.\nStep 2: Hydrogen: 4 × 1 = 4.\nStep 3: Oxygen: 2 × 16 = 32.\nStep 4: Add the values: 24 + 4 + 32 = 60.","steps":["Step 1: Carbon: 2 × 12 = 24.","Step 2: Hydrogen: 4 × 1 = 4.","Step 3: Oxygen: 2 × 16 = 32.","Step 4: Add the values: 24 + 4 + 32 = 60."],"options":[],"conceptId":"chemistry_organic_chemistry_ethanoic_acid","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q6","subject":"chemistry","chapter":"organic_chemistry","topic":"Ethanoic Acid"}', 5),
  (4024, 895, 'Calculate the percentage by mass of oxygen in ethanoic acid, C₂H₄O₂.', 'text', 1, 'Oxygen contributes 2 × 16 to the total molecular mass.', '{"why":"Percentage by mass is the element''s mass contribution divided by the total molecular mass, multiplied by 100.","sol":"Step 1: Calculate the relative molecular mass: 2(12) + 4(1) + 2(16) = 60.\nStep 2: Calculate oxygen''s contribution: 2 × 16 = 32.\nStep 3: Percentage of oxygen = (32 ÷ 60) × 100.\nStep 4: Percentage of oxygen ≈ 53.3%.","steps":["Step 1: Calculate the relative molecular mass: 2(12) + 4(1) + 2(16) = 60.","Step 2: Calculate oxygen''s contribution: 2 × 16 = 32.","Step 3: Percentage of oxygen = (32 ÷ 60) × 100.","Step 4: Percentage of oxygen ≈ 53.3%."],"options":[],"conceptId":"chemistry_organic_chemistry_ethanoic_acid","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q7","subject":"chemistry","chapter":"organic_chemistry","topic":"Ethanoic Acid"}', 6),
  (4025, 895, 'Explain why ethanoic acid belongs to the carboxylic acid family.', 'text', 1, 'Identify its characteristic functional group.', '{"why":"The carboxyl group is the defining functional group of carboxylic acids.","sol":"Step 1: Examine CH₃COOH.\nStep 2: Identify the –COOH group.\nStep 3: This is the carboxyl functional group.\nStep 4: Therefore, ethanoic acid is a carboxylic acid.","steps":["Step 1: Examine CH₃COOH.","Step 2: Identify the –COOH group.","Step 3: This is the carboxyl functional group.","Step 4: Therefore, ethanoic acid is a carboxylic acid."],"options":[],"conceptId":"chemistry_organic_chemistry_ethanoic_acid","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q8","subject":"chemistry","chapter":"organic_chemistry","topic":"Ethanoic Acid"}', 7),
  (4026, 896, 'State the products formed when ethanoic acid reacts with magnesium.', 'text', 1, 'Focus on the core principle of Reactions of Ethanoic Acid.', '{"why":"Acid-metal reactions produce a salt and hydrogen gas.","sol":"Step 1: Recognise ethanoic acid as an acid.\nStep 2: An acid reacts with a sufficiently reactive metal to produce a salt and hydrogen gas.\nStep 3: The salt formed from magnesium and ethanoic acid is magnesium ethanoate.","steps":["Step 1: Recognise ethanoic acid as an acid.","Step 2: An acid reacts with a sufficiently reactive metal to produce a salt and hydrogen gas.","Step 3: The salt formed from magnesium and ethanoic acid is magnesium ethanoate."],"options":[],"conceptId":"chemistry_organic_chemistry_reactions_of_ethanoic_acid","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Reactions of Ethanoic Acid"}', 0),
  (4027, 896, 'Complete and balance CH₃COOH + NaOH →', 'text', 1, 'Focus on the core principle of Reactions of Ethanoic Acid.', '{"why":"Neutralisation between an acid and an alkali produces a salt and water.","sol":"Step 1: Identify the reaction as acid-alkali neutralisation.\nStep 2: The salt formed is sodium ethanoate, CH₃COONa.\nStep 3: Water is the other product.\nStep 4: Check that the atoms balance with coefficients of 1.","steps":["Step 1: Identify the reaction as acid-alkali neutralisation.","Step 2: The salt formed is sodium ethanoate, CH₃COONa.","Step 3: Water is the other product.","Step 4: Check that the atoms balance with coefficients of 1."],"options":[],"conceptId":"chemistry_organic_chemistry_reactions_of_ethanoic_acid","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Reactions of Ethanoic Acid"}', 1),
  (4028, 896, 'What gas is formed when ethanoic acid reacts with sodium carbonate?', 'text', 1, 'Focus on the core principle of Reactions of Ethanoic Acid.', '{"why":"Carbon dioxide is the gas produced in acid-carbonate reactions.","sol":"Step 1: Identify sodium carbonate as a carbonate.\nStep 2: Acids react with carbonates to form a salt, water and carbon dioxide.\nStep 3: Identify the gaseous product.","steps":["Step 1: Identify sodium carbonate as a carbonate.","Step 2: Acids react with carbonates to form a salt, water and carbon dioxide.","Step 3: Identify the gaseous product."],"options":[],"conceptId":"chemistry_organic_chemistry_reactions_of_ethanoic_acid","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Reactions of Ethanoic Acid"}', 2),
  (4029, 896, 'Balance CH₃COOH + Na₂CO₃ → CH₃COONa + H₂O + CO₂.', 'text', 1, 'Balance sodium first, then balance the ethanoate groups.', '{"why":"The coefficients balance every element without changing the formulas of the compounds.","sol":"Step 1: Na₂CO₃ contains 2 sodium atoms.\nStep 2: Put 2 before CH₃COONa to balance sodium.\nStep 3: Put 2 before CH₃COOH to supply two ethanoate groups.\nStep 4: Keep one H₂O and one CO₂.\nStep 5: Check carbon, hydrogen, oxygen and sodium.","steps":["Step 1: Na₂CO₃ contains 2 sodium atoms.","Step 2: Put 2 before CH₃COONa to balance sodium.","Step 3: Put 2 before CH₃COOH to supply two ethanoate groups.","Step 4: Keep one H₂O and one CO₂.","Step 5: Check carbon, hydrogen, oxygen and sodium."],"options":[],"conceptId":"chemistry_organic_chemistry_reactions_of_ethanoic_acid","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Reactions of Ethanoic Acid"}', 3),
  (4030, 896, 'Write the balanced equation for the reaction between ethanoic acid and magnesium.', 'text', 1, 'Magnesium forms Mg²⁺, so the salt needs two ethanoate ions.', '{"why":"The equation conserves atoms and correctly represents the magnesium ethanoate salt.","sol":"Step 1: Write the products as magnesium ethanoate and hydrogen: Mg(CH₃COO)₂ + H₂.\nStep 2: Two ethanoate groups are needed for each magnesium ion.\nStep 3: Put 2 before CH₃COOH to supply the two ethanoate groups.\nStep 4: Check that hydrogen gas is H₂ and that the remaining atoms balance.","steps":["Step 1: Write the products as magnesium ethanoate and hydrogen: Mg(CH₃COO)₂ + H₂.","Step 2: Two ethanoate groups are needed for each magnesium ion.","Step 3: Put 2 before CH₃COOH to supply the two ethanoate groups.","Step 4: Check that hydrogen gas is H₂ and that the remaining atoms balance."],"options":[],"conceptId":"chemistry_organic_chemistry_reactions_of_ethanoic_acid","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Reactions of Ethanoic Acid"}', 4),
  (4031, 896, 'Explain how carbon dioxide produced in the reaction between ethanoic acid and sodium carbonate can be tested.', 'text', 1, 'Name the solution used in the standard laboratory test.', '{"why":"Carbon dioxide forms insoluble calcium carbonate when it reacts with limewater.","sol":"Step 1: Pass the gas through limewater.\nStep 2: If the gas is carbon dioxide, it reacts with calcium hydroxide in the limewater.\nStep 3: Insoluble calcium carbonate forms.\nStep 4: The limewater turns milky.","steps":["Step 1: Pass the gas through limewater.","Step 2: If the gas is carbon dioxide, it reacts with calcium hydroxide in the limewater.","Step 3: Insoluble calcium carbonate forms.","Step 4: The limewater turns milky."],"options":[],"conceptId":"chemistry_organic_chemistry_reactions_of_ethanoic_acid","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q6","subject":"chemistry","chapter":"organic_chemistry","topic":"Reactions of Ethanoic Acid"}', 5),
  (4032, 896, 'Complete the word equation: ethanoic acid + sodium hydroxide → ______ + ______.', 'text', 1, 'An acid reacts with an alkali in neutralisation.', '{"why":"Neutralisation produces a salt and water.","sol":"Step 1: Recognise the reaction as neutralisation.\nStep 2: The salt contains sodium and the ethanoate ion.\nStep 3: The salt is sodium ethanoate.\nStep 4: Water is the second product.","steps":["Step 1: Recognise the reaction as neutralisation.","Step 2: The salt contains sodium and the ethanoate ion.","Step 3: The salt is sodium ethanoate.","Step 4: Water is the second product."],"options":[],"conceptId":"chemistry_organic_chemistry_reactions_of_ethanoic_acid","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q7","subject":"chemistry","chapter":"organic_chemistry","topic":"Reactions of Ethanoic Acid"}', 6),
  (4033, 896, 'A learner writes CH₃COOH + NaOH → CH₃COONa. Explain why this equation is incomplete and correct it.', 'text', 1, 'Recall the second product of acid-alkali neutralisation.', '{"why":"Water is a required product of the neutralisation reaction and must be included.","sol":"Step 1: Ethanoic acid reacts with sodium hydroxide in neutralisation.\nStep 2: Neutralisation produces a salt and water.\nStep 3: The salt is CH₃COONa.\nStep 4: Add H₂O to the products.\nStep 5: Check the equation: CH₃COOH + NaOH → CH₃COONa + H₂O.","steps":["Step 1: Ethanoic acid reacts with sodium hydroxide in neutralisation.","Step 2: Neutralisation produces a salt and water.","Step 3: The salt is CH₃COONa.","Step 4: Add H₂O to the products.","Step 5: Check the equation: CH₃COOH + NaOH → CH₃COONa + H₂O."],"options":[],"conceptId":"chemistry_organic_chemistry_reactions_of_ethanoic_acid","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q8","subject":"chemistry","chapter":"organic_chemistry","topic":"Reactions of Ethanoic Acid"}', 7),
  (4034, 897, 'Write the balanced equation for the hydrogenation of ethene.', 'text', 1, 'Focus on the core principle of Addition Reactions.', '{"why":"Hydrogenation adds hydrogen across the double bond, converting ethene into ethane.","sol":"Step 1: Write the formula of ethene as C₂H₄.\nStep 2: Write the formula of hydrogen as H₂.\nStep 3: Hydrogen adds across the double bond to form ethane, C₂H₆.\nStep 4: Check that both sides contain two carbon atoms and six hydrogen atoms.","steps":["Step 1: Write the formula of ethene as C₂H₄.","Step 2: Write the formula of hydrogen as H₂.","Step 3: Hydrogen adds across the double bond to form ethane, C₂H₆.","Step 4: Check that both sides contain two carbon atoms and six hydrogen atoms."],"options":[],"conceptId":"chemistry_organic_chemistry_addition_reactions","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Addition Reactions"}', 0),
  (4035, 897, 'Name the product formed when ethene reacts with bromine.', 'text', 1, 'Focus on the core principle of Addition Reactions.', '{"why":"The two bromine atoms attach to the two carbon atoms that originally formed the double bond.","sol":"Step 1: Ethene contains two carbon atoms joined by a double bond.\nStep 2: Bromine adds across the double bond.\nStep 3: Each carbon atom receives one bromine atom.\nStep 4: The product is named 1,2-dibromoethane.","steps":["Step 1: Ethene contains two carbon atoms joined by a double bond.","Step 2: Bromine adds across the double bond.","Step 3: Each carbon atom receives one bromine atom.","Step 4: The product is named 1,2-dibromoethane."],"options":[],"conceptId":"chemistry_organic_chemistry_addition_reactions","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Addition Reactions"}', 1),
  (4036, 897, 'Explain why hydrogenation converts an alkene into an alkane.', 'text', 1, 'Focus on the core principle of Addition Reactions.', '{"why":"Alkanes are saturated hydrocarbons because their carbon atoms are joined by single bonds.","sol":"Step 1: An alkene contains a carbon-carbon double bond.\nStep 2: Hydrogen atoms add across this double bond.\nStep 3: The double bond becomes a single bond.\nStep 4: The product no longer contains the carbon-carbon double bond and is saturated.","steps":["Step 1: An alkene contains a carbon-carbon double bond.","Step 2: Hydrogen atoms add across this double bond.","Step 3: The double bond becomes a single bond.","Step 4: The product no longer contains the carbon-carbon double bond and is saturated."],"options":[],"conceptId":"chemistry_organic_chemistry_addition_reactions","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Addition Reactions"}', 2),
  (4037, 897, 'Propene reacts with hydrogen in the presence of a nickel catalyst. Identify the product and write its formula.', 'text', 1, 'Hydrogenation converts an alkene into the corresponding alkane.', '{"why":"Adding one molecule of hydrogen saturates the double bond in propene.","sol":"Step 1: Propene contains three carbon atoms and has formula C₃H₆.\nStep 2: Add H₂ across the double bond.\nStep 3: The product has three carbon atoms and eight hydrogen atoms.\nStep 4: The product is propane, C₃H₈.\nStep 5: The balanced equation is C₃H₆ + H₂ → C₃H₈.","steps":["Step 1: Propene contains three carbon atoms and has formula C₃H₆.","Step 2: Add H₂ across the double bond.","Step 3: The product has three carbon atoms and eight hydrogen atoms.","Step 4: The product is propane, C₃H₈.","Step 5: The balanced equation is C₃H₆ + H₂ → C₃H₈."],"options":[],"conceptId":"chemistry_organic_chemistry_addition_reactions","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Addition Reactions"}', 3),
  (4038, 897, 'Explain why an alkene decolourises bromine water.', 'text', 1, 'Consider the reaction between bromine and a carbon-carbon double bond.', '{"why":"The decolourisation is a chemical test for unsaturation.","sol":"Step 1: Bromine water is orange-brown.\nStep 2: An alkene contains a carbon-carbon double bond.\nStep 3: Bromine adds across this double bond.\nStep 4: The coloured bromine is used up in the reaction.\nStep 5: The bromine water loses its orange-brown colour.","steps":["Step 1: Bromine water is orange-brown.","Step 2: An alkene contains a carbon-carbon double bond.","Step 3: Bromine adds across this double bond.","Step 4: The coloured bromine is used up in the reaction.","Step 5: The bromine water loses its orange-brown colour."],"options":[],"conceptId":"chemistry_organic_chemistry_addition_reactions","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Addition Reactions"}', 4),
  (4039, 897, 'Complete the equation: C₂H₄ + Br₂ → ? Name the product.', 'text', 1, 'One bromine atom attaches to each carbon of the original double bond.', '{"why":"Bromine adds across the carbon-carbon double bond without removing carbon or hydrogen atoms.","sol":"Step 1: Ethene contains two carbon atoms.\nStep 2: Bromine supplies two bromine atoms.\nStep 3: The product contains two carbon atoms, four hydrogen atoms and two bromine atoms.\nStep 4: Its formula is C₂H₄Br₂.\nStep 5: The structural formula is CH₂BrCH₂Br.","steps":["Step 1: Ethene contains two carbon atoms.","Step 2: Bromine supplies two bromine atoms.","Step 3: The product contains two carbon atoms, four hydrogen atoms and two bromine atoms.","Step 4: Its formula is C₂H₄Br₂.","Step 5: The structural formula is CH₂BrCH₂Br."],"options":[],"conceptId":"chemistry_organic_chemistry_addition_reactions","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q6","subject":"chemistry","chapter":"organic_chemistry","topic":"Addition Reactions"}', 5),
  (4040, 897, 'A student shakes bromine water with an unknown hydrocarbon. The orange-brown colour disappears. What can the student conclude, and what can the student not conclude?', 'text', 1, 'Distinguish evidence of unsaturation from identification of an exact compound.', '{"why":"A chemical test can provide evidence for a type of bonding without uniquely identifying every possible substance.","sol":"Step 1: Bromine water is decolourised by addition to an alkene under suitable test conditions.\nStep 2: The observation suggests the sample contains an unsaturated compound.\nStep 3: It does not establish the exact identity of the hydrocarbon.\nStep 4: Other evidence or tests would be needed to identify the compound.","steps":["Step 1: Bromine water is decolourised by addition to an alkene under suitable test conditions.","Step 2: The observation suggests the sample contains an unsaturated compound.","Step 3: It does not establish the exact identity of the hydrocarbon.","Step 4: Other evidence or tests would be needed to identify the compound."],"options":[],"conceptId":"chemistry_organic_chemistry_addition_reactions","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q7","subject":"chemistry","chapter":"organic_chemistry","topic":"Addition Reactions"}', 6),
  (4041, 897, 'Compare the products formed when ethene reacts separately with hydrogen and bromine.', 'text', 1, 'Identify what is added in each reaction and whether the product remains a hydrocarbon.', '{"why":"The product depends on the atoms added across the original carbon-carbon double bond.","sol":"Step 1: Hydrogenation adds hydrogen to ethene.\nStep 2: The product is ethane, C₂H₆.\nStep 3: Bromine addition adds bromine atoms to ethene.\nStep 4: The product is 1,2-dibromoethane, C₂H₄Br₂.\nStep 5: Ethane is a hydrocarbon, while 1,2-dibromoethane also contains bromine.","steps":["Step 1: Hydrogenation adds hydrogen to ethene.","Step 2: The product is ethane, C₂H₆.","Step 3: Bromine addition adds bromine atoms to ethene.","Step 4: The product is 1,2-dibromoethane, C₂H₄Br₂.","Step 5: Ethane is a hydrocarbon, while 1,2-dibromoethane also contains bromine."],"options":[],"conceptId":"chemistry_organic_chemistry_addition_reactions","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q8","subject":"chemistry","chapter":"organic_chemistry","topic":"Addition Reactions"}', 7),
  (4042, 898, 'Name the reaction between an alcohol and a carboxylic acid that forms an ester.', 'text', 1, 'Focus on the core principle of Ester Formation.', '{"why":"Esterification is the reaction that produces an ester and water from an alcohol and a carboxylic acid.","sol":"Step 1: Identify the reactants: an alcohol and a carboxylic acid.\nStep 2: The products include an ester and water.\nStep 3: This reaction is called esterification.","steps":["Step 1: Identify the reactants: an alcohol and a carboxylic acid.","Step 2: The products include an ester and water.","Step 3: This reaction is called esterification."],"options":[],"conceptId":"chemistry_organic_chemistry_ester_formation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Ester Formation"}', 0),
  (4043, 898, 'Write the equation for ethanol reacting with ethanoic acid.', 'text', 1, 'Focus on the core principle of Ester Formation.', '{"why":"Ethanol and ethanoic acid combine to form ethyl ethanoate and water.","sol":"Step 1: Ethanol is C₂H₅OH.\nStep 2: Ethanoic acid is CH₃COOH.\nStep 3: The ester is ethyl ethanoate, CH₃COOC₂H₅.\nStep 4: Water is the other product.\nStep 5: Use a reversible arrow because the reaction is reversible.","steps":["Step 1: Ethanol is C₂H₅OH.","Step 2: Ethanoic acid is CH₃COOH.","Step 3: The ester is ethyl ethanoate, CH₃COOC₂H₅.","Step 4: Water is the other product.","Step 5: Use a reversible arrow because the reaction is reversible."],"options":[],"conceptId":"chemistry_organic_chemistry_ester_formation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Ester Formation"}', 1),
  (4044, 898, 'State the role of concentrated sulfuric acid in esterification.', 'text', 1, 'Focus on the core principle of Ester Formation.', '{"why":"The acid catalyst increases the rate of esterification; concentrated sulfuric acid can also favour ester formation by removing water.","sol":"Step 1: Esterification is commonly carried out using an acid catalyst.\nStep 2: Concentrated sulfuric acid provides acidic conditions.\nStep 3: It can also help remove water from the reaction mixture.\nStep 4: Its main commonly taught role is to act as an acid catalyst.","steps":["Step 1: Esterification is commonly carried out using an acid catalyst.","Step 2: Concentrated sulfuric acid provides acidic conditions.","Step 3: It can also help remove water from the reaction mixture.","Step 4: Its main commonly taught role is to act as an acid catalyst."],"options":[],"conceptId":"chemistry_organic_chemistry_ester_formation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Ester Formation"}', 2),
  (4045, 898, 'Ethanol reacts with propanoic acid. Name the ester formed and write its formula.', 'text', 1, 'The alcohol determines the first part of the name; the acid determines the second part.', '{"why":"Ester names combine the alcohol-derived alkyl name with the acid-derived alkanoate name.","sol":"Step 1: Ethanol supplies the ethyl part.\nStep 2: Propanoic acid supplies the propanoate part.\nStep 3: The ester is ethyl propanoate.\nStep 4: Its condensed structural formula is CH₃CH₂COOC₂H₅.\nStep 5: Water is also formed during esterification.","steps":["Step 1: Ethanol supplies the ethyl part.","Step 2: Propanoic acid supplies the propanoate part.","Step 3: The ester is ethyl propanoate.","Step 4: Its condensed structural formula is CH₃CH₂COOC₂H₅.","Step 5: Water is also formed during esterification."],"options":[],"conceptId":"chemistry_organic_chemistry_ester_formation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Ester Formation"}', 3),
  (4046, 898, 'Write the balanced equation for methanol reacting with ethanoic acid.', 'text', 1, 'Methanol is CH₃OH and ethanoic acid is CH₃COOH.', '{"why":"One molecule of methanol reacts with one molecule of ethanoic acid to form methyl ethanoate and water.","sol":"Step 1: Write the reactants: CH₃OH and CH₃COOH.\nStep 2: The ester formed is methyl ethanoate, CH₃COOCH₃.\nStep 3: Add water as the other product.\nStep 4: Check that both sides contain 3 carbon atoms, 6 hydrogen atoms and 3 oxygen atoms.","steps":["Step 1: Write the reactants: CH₃OH and CH₃COOH.","Step 2: The ester formed is methyl ethanoate, CH₃COOCH₃.","Step 3: Add water as the other product.","Step 4: Check that both sides contain 3 carbon atoms, 6 hydrogen atoms and 3 oxygen atoms."],"options":[],"conceptId":"chemistry_organic_chemistry_ester_formation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Ester Formation"}', 4),
  (4047, 898, 'Why is esterification represented by a reversible arrow?', 'text', 1, 'Think about whether the products can react to regenerate the starting substances.', '{"why":"A reversible arrow represents a reaction that can proceed in both the forward and reverse directions.","sol":"Step 1: Esterification produces an ester and water.\nStep 2: Under suitable conditions, the ester can react with water.\nStep 3: This reaction can regenerate the alcohol and carboxylic acid.\nStep 4: The reaction can therefore proceed in both directions.","steps":["Step 1: Esterification produces an ester and water.","Step 2: Under suitable conditions, the ester can react with water.","Step 3: This reaction can regenerate the alcohol and carboxylic acid.","Step 4: The reaction can therefore proceed in both directions."],"options":[],"conceptId":"chemistry_organic_chemistry_ester_formation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q6","subject":"chemistry","chapter":"organic_chemistry","topic":"Ester Formation"}', 5),
  (4048, 898, 'An ester is named methyl propanoate. Identify the alcohol and carboxylic acid used to form it.', 'text', 1, 'Methyl comes from methanol; propanoate comes from propanoic acid.', '{"why":"The two parts of an ester name indicate the alcohol-derived and carboxylic-acid-derived parts.","sol":"Step 1: The word methyl identifies the alcohol-derived group.\nStep 2: The corresponding alcohol is methanol.\nStep 3: The word propanoate identifies the acid-derived part.\nStep 4: The corresponding carboxylic acid is propanoic acid.","steps":["Step 1: The word methyl identifies the alcohol-derived group.","Step 2: The corresponding alcohol is methanol.","Step 3: The word propanoate identifies the acid-derived part.","Step 4: The corresponding carboxylic acid is propanoic acid."],"options":[],"conceptId":"chemistry_organic_chemistry_ester_formation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q7","subject":"chemistry","chapter":"organic_chemistry","topic":"Ester Formation"}', 6),
  (4049, 898, 'State two conditions commonly used to prepare an ester in the laboratory and explain their purposes.', 'text', 1, 'Consider the acid added to the mixture and the effect of heating.', '{"why":"These conditions help esterification occur at a useful rate and can favour ester formation.","sol":"Step 1: Concentrated sulfuric acid is commonly added.\nStep 2: It provides an acid catalyst, increasing the reaction rate.\nStep 3: The reactants are heated to help the reaction proceed faster.\nStep 4: Concentrated sulfuric acid can also help remove water.","steps":["Step 1: Concentrated sulfuric acid is commonly added.","Step 2: It provides an acid catalyst, increasing the reaction rate.","Step 3: The reactants are heated to help the reaction proceed faster.","Step 4: Concentrated sulfuric acid can also help remove water."],"options":[],"conceptId":"chemistry_organic_chemistry_ester_formation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q8","subject":"chemistry","chapter":"organic_chemistry","topic":"Ester Formation"}', 7),
  (4050, 899, 'Define a monomer.', 'text', 1, 'Focus on the core principle of Addition Polymerisation.', '{"why":"Monomers are the starting molecules from which polymers are built.","sol":"Step 1: A polymer consists of many repeating units.\nStep 2: The smaller molecules that join to make a polymer are called monomers.\nStep 3: A monomer is therefore a small molecule capable of joining with others to form a polymer.","steps":["Step 1: A polymer consists of many repeating units.","Step 2: The smaller molecules that join to make a polymer are called monomers.","Step 3: A monomer is therefore a small molecule capable of joining with others to form a polymer."],"options":[],"conceptId":"chemistry_organic_chemistry_addition_polymerisation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Addition Polymerisation"}', 0),
  (4051, 899, 'Name the monomer used to make poly(ethene).', 'text', 1, 'Focus on the core principle of Addition Polymerisation.', '{"why":"Ethene molecules undergo addition polymerisation to form poly(ethene).","sol":"Step 1: Identify the polymer name: poly(ethene).\nStep 2: The name identifies the starting alkene as ethene.\nStep 3: Ethene has the structural formula CH₂=CH₂.","steps":["Step 1: Identify the polymer name: poly(ethene).","Step 2: The name identifies the starting alkene as ethene.","Step 3: Ethene has the structural formula CH₂=CH₂."],"options":[],"conceptId":"chemistry_organic_chemistry_addition_polymerisation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Addition Polymerisation"}', 1),
  (4052, 899, 'Explain what happens to the double bond during addition polymerisation.', 'text', 1, 'Focus on the core principle of Addition Polymerisation.', '{"why":"The double bond allows alkene monomers to join through new covalent bonds.","sol":"Step 1: The alkene monomer begins with a C=C double bond.\nStep 2: The double bond opens so the carbon atoms can form additional bonds.\nStep 3: New carbon-carbon single bonds join neighbouring monomers.\nStep 4: Repetition produces a long polymer chain.","steps":["Step 1: The alkene monomer begins with a C=C double bond.","Step 2: The double bond opens so the carbon atoms can form additional bonds.","Step 3: New carbon-carbon single bonds join neighbouring monomers.","Step 4: Repetition produces a long polymer chain."],"options":[],"conceptId":"chemistry_organic_chemistry_addition_polymerisation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Addition Polymerisation"}', 2),
  (4053, 899, 'Write the polymerisation equation for ethene and identify the monomer and repeating unit.', 'text', 1, 'Show many ethene molecules forming a chain enclosed in brackets.', '{"why":"The repeating unit shows the atoms that repeat along the poly(ethene) chain.","sol":"Step 1: Write the monomer as CH₂=CH₂.\nStep 2: During polymerisation, the double bond opens.\nStep 3: The repeating unit becomes –CH₂–CH₂–.\nStep 4: Use n to represent many monomer molecules.\nStep 5: Write nCH₂=CH₂ → [–CH₂–CH₂–]ₙ.","steps":["Step 1: Write the monomer as CH₂=CH₂.","Step 2: During polymerisation, the double bond opens.","Step 3: The repeating unit becomes –CH₂–CH₂–.","Step 4: Use n to represent many monomer molecules.","Step 5: Write nCH₂=CH₂ → [–CH₂–CH₂–]ₙ."],"options":[],"conceptId":"chemistry_organic_chemistry_addition_polymerisation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Addition Polymerisation"}', 3),
  (4054, 899, 'Propene undergoes addition polymerisation. Write its repeating unit.', 'text', 1, 'Propene is CH₂=CHCH₃; the methyl group remains attached to the polymer backbone.', '{"why":"The repeating unit retains all atoms of the propene monomer in the addition polymer.","sol":"Step 1: Identify the two carbon atoms joined by the double bond.\nStep 2: These two carbon atoms become part of the polymer backbone.\nStep 3: The methyl group remains attached to the second backbone carbon.\nStep 4: The repeating unit is –CH₂–CH(CH₃)–.\nStep 5: The polymer is represented as [–CH₂–CH(CH₃)–]ₙ.","steps":["Step 1: Identify the two carbon atoms joined by the double bond.","Step 2: These two carbon atoms become part of the polymer backbone.","Step 3: The methyl group remains attached to the second backbone carbon.","Step 4: The repeating unit is –CH₂–CH(CH₃)–.","Step 5: The polymer is represented as [–CH₂–CH(CH₃)–]ₙ."],"options":[],"conceptId":"chemistry_organic_chemistry_addition_polymerisation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Addition Polymerisation"}', 4),
  (4055, 899, 'A polymer contains 75 repeating units of poly(ethene). How many carbon atoms are represented in those repeating units?', 'text', 1, 'Each poly(ethene) repeating unit contains two carbon atoms.', '{"why":"Each –CH₂–CH₂– unit contains two carbon atoms, so 75 units represent 150 carbon atoms.","sol":"Step 1: Carbon atoms per repeating unit = 2.\nStep 2: Number of repeating units = 75.\nStep 3: Total carbon atoms = 75 × 2.\nStep 4: Total carbon atoms = 150.","steps":["Step 1: Carbon atoms per repeating unit = 2.","Step 2: Number of repeating units = 75.","Step 3: Total carbon atoms = 75 × 2.","Step 4: Total carbon atoms = 150."],"options":[],"conceptId":"chemistry_organic_chemistry_addition_polymerisation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q6","subject":"chemistry","chapter":"organic_chemistry","topic":"Addition Polymerisation"}', 5),
  (4056, 899, 'Explain why addition polymerisation does not produce water as a by-product.', 'text', 1, 'Consider what happens to the atoms in the alkene monomers.', '{"why":"This distinguishes addition polymerisation from condensation polymerisation, which eliminates small molecules.","sol":"Step 1: Addition polymerisation joins unsaturated monomers together.\nStep 2: The double bonds open and new carbon-carbon bonds form.\nStep 3: The monomer atoms become part of the polymer chain.\nStep 4: No small molecule is eliminated in this process.","steps":["Step 1: Addition polymerisation joins unsaturated monomers together.","Step 2: The double bonds open and new carbon-carbon bonds form.","Step 3: The monomer atoms become part of the polymer chain.","Step 4: No small molecule is eliminated in this process."],"options":[],"conceptId":"chemistry_organic_chemistry_addition_polymerisation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q7","subject":"chemistry","chapter":"organic_chemistry","topic":"Addition Polymerisation"}', 6),
  (4057, 899, 'Compare the monomer and polymer in the production of poly(ethene).', 'text', 1, 'Consider their size, structure and the number of repeating units.', '{"why":"Polymerisation changes many small molecules into a long-chain macromolecule.","sol":"Step 1: Ethene is a small molecule with formula CH₂=CH₂.\nStep 2: Many ethene molecules join during polymerisation.\nStep 3: The product is a large molecule containing repeating –CH₂–CH₂– units.\nStep 4: Ethene is the monomer; poly(ethene) is the polymer.","steps":["Step 1: Ethene is a small molecule with formula CH₂=CH₂.","Step 2: Many ethene molecules join during polymerisation.","Step 3: The product is a large molecule containing repeating –CH₂–CH₂– units.","Step 4: Ethene is the monomer; poly(ethene) is the polymer."],"options":[],"conceptId":"chemistry_organic_chemistry_addition_polymerisation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q8","subject":"chemistry","chapter":"organic_chemistry","topic":"Addition Polymerisation"}', 7),
  (4058, 900, 'Define crude oil.', 'text', 1, 'Focus on the core principle of Crude Oil.', '{"why":"Crude oil contains many different hydrocarbons rather than one pure substance.","sol":"Step 1: Crude oil occurs naturally in underground geological formations.\nStep 2: It contains many different compounds made of carbon and hydrogen.\nStep 3: These compounds are hydrocarbons.\nStep 4: Therefore, crude oil is a naturally occurring mixture of hydrocarbons.","steps":["Step 1: Crude oil occurs naturally in underground geological formations.","Step 2: It contains many different compounds made of carbon and hydrogen.","Step 3: These compounds are hydrocarbons.","Step 4: Therefore, crude oil is a naturally occurring mixture of hydrocarbons."],"options":[],"conceptId":"chemistry_organic_chemistry_crude_oil","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Crude Oil"}', 0),
  (4059, 900, 'Why is crude oil described as a mixture rather than a compound?', 'text', 1, 'Focus on the core principle of Crude Oil.', '{"why":"A mixture does not have one fixed chemical formula and its components retain their individual identities.","sol":"Step 1: A compound has a fixed chemical composition.\nStep 2: Crude oil contains many different hydrocarbons in varying proportions.\nStep 3: Its components can be separated physically by fractional distillation.\nStep 4: Therefore, crude oil is a mixture.","steps":["Step 1: A compound has a fixed chemical composition.","Step 2: Crude oil contains many different hydrocarbons in varying proportions.","Step 3: Its components can be separated physically by fractional distillation.","Step 4: Therefore, crude oil is a mixture."],"options":[],"conceptId":"chemistry_organic_chemistry_crude_oil","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Crude Oil"}', 1),
  (4060, 900, 'State the principle used to separate crude oil into fractions.', 'text', 1, 'Focus on the core principle of Crude Oil.', '{"why":"Components vaporise and condense at different temperatures, allowing the mixture to be separated.","sol":"Step 1: Crude oil contains hydrocarbons of different sizes.\nStep 2: These hydrocarbons have different boiling-point ranges.\nStep 3: Fractional distillation uses these differences to separate them.","steps":["Step 1: Crude oil contains hydrocarbons of different sizes.","Step 2: These hydrocarbons have different boiling-point ranges.","Step 3: Fractional distillation uses these differences to separate them."],"options":[],"conceptId":"chemistry_organic_chemistry_crude_oil","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Crude Oil"}', 2),
  (4061, 900, 'Explain why crude oil can be separated by fractional distillation without chemically changing its main components.', 'text', 1, 'Distinguish a physical separation from a chemical reaction.', '{"why":"The process separates existing substances instead of chemically converting them into new substances.","sol":"Step 1: Crude oil contains a mixture of hydrocarbons.\nStep 2: The hydrocarbons have different boiling-point ranges.\nStep 3: Heating vaporises components and cooling causes them to condense at different heights.\nStep 4: The hydrocarbons are collected separately without normally changing their chemical identities.","steps":["Step 1: Crude oil contains a mixture of hydrocarbons.","Step 2: The hydrocarbons have different boiling-point ranges.","Step 3: Heating vaporises components and cooling causes them to condense at different heights.","Step 4: The hydrocarbons are collected separately without normally changing their chemical identities."],"options":[],"conceptId":"chemistry_organic_chemistry_crude_oil","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Crude Oil"}', 3),
  (4062, 900, 'A crude-oil fraction contains relatively small hydrocarbon molecules. State two properties it is likely to have compared with a fraction containing larger molecules.', 'text', 1, 'Think about boiling point, volatility and viscosity.', '{"why":"Molecular size affects the physical properties of hydrocarbon fractions.","sol":"Step 1: Smaller hydrocarbons generally have lower boiling points.\nStep 2: They therefore evaporate more readily and are more volatile.\nStep 3: They also generally have lower viscosity than heavier fractions.\nStep 4: State any two of these trends.","steps":["Step 1: Smaller hydrocarbons generally have lower boiling points.","Step 2: They therefore evaporate more readily and are more volatile.","Step 3: They also generally have lower viscosity than heavier fractions.","Step 4: State any two of these trends."],"options":[],"conceptId":"chemistry_organic_chemistry_crude_oil","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Crude Oil"}', 4),
  (4063, 900, 'Why is crude oil considered a non-renewable resource?', 'text', 1, 'Compare the time taken for crude oil to form with the rate at which people use it.', '{"why":"A resource is non-renewable on human timescales when it cannot be replenished at a comparable rate to consumption.","sol":"Step 1: Crude oil forms from ancient organic material over millions of years.\nStep 2: People extract and use it much more rapidly.\nStep 3: Natural formation cannot replace the consumed supply on a human timescale.","steps":["Step 1: Crude oil forms from ancient organic material over millions of years.","Step 2: People extract and use it much more rapidly.","Step 3: Natural formation cannot replace the consumed supply on a human timescale."],"options":[],"conceptId":"chemistry_organic_chemistry_crude_oil","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q6","subject":"chemistry","chapter":"organic_chemistry","topic":"Crude Oil"}', 5),
  (4064, 900, 'Describe how a fractionating column separates crude oil into different fractions.', 'text', 1, 'Explain heating, the temperature gradient and condensation.', '{"why":"Fractional distillation separates substances using differences in boiling points.","sol":"Step 1: Crude oil is heated so that much of it vaporises.\nStep 2: The vapours enter a column that is hotter at the bottom and cooler at the top.\nStep 3: Vapours cool as they rise.\nStep 4: Different hydrocarbons condense at different heights because they have different boiling-point ranges.\nStep 5: The condensed fractions are collected separately.","steps":["Step 1: Crude oil is heated so that much of it vaporises.","Step 2: The vapours enter a column that is hotter at the bottom and cooler at the top.","Step 3: Vapours cool as they rise.","Step 4: Different hydrocarbons condense at different heights because they have different boiling-point ranges.","Step 5: The condensed fractions are collected separately."],"options":[],"conceptId":"chemistry_organic_chemistry_crude_oil","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q7","subject":"chemistry","chapter":"organic_chemistry","topic":"Crude Oil"}', 6),
  (4065, 901, 'Define cracking.', 'text', 1, 'Focus on the core principle of Cracking.', '{"why":"Cracking converts heavy hydrocarbons into smaller molecules that are often more useful.","sol":"Step 1: Begin with large hydrocarbon molecules.\nStep 2: They are heated under suitable conditions.\nStep 3: Their molecules break into smaller hydrocarbons.\nStep 4: This process is called cracking.","steps":["Step 1: Begin with large hydrocarbon molecules.","Step 2: They are heated under suitable conditions.","Step 3: Their molecules break into smaller hydrocarbons.","Step 4: This process is called cracking."],"options":[],"conceptId":"chemistry_organic_chemistry_cracking","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Cracking"}', 0),
  (4066, 901, 'State two types of hydrocarbons commonly formed during cracking.', 'text', 1, 'Focus on the core principle of Cracking.', '{"why":"Cracking commonly produces a mixture of smaller saturated and unsaturated hydrocarbons.","sol":"Step 1: Cracking produces smaller hydrocarbon molecules.\nStep 2: Some products are saturated hydrocarbons called alkanes.\nStep 3: Other products are unsaturated hydrocarbons, commonly alkenes.","steps":["Step 1: Cracking produces smaller hydrocarbon molecules.","Step 2: Some products are saturated hydrocarbons called alkanes.","Step 3: Other products are unsaturated hydrocarbons, commonly alkenes."],"options":[],"conceptId":"chemistry_organic_chemistry_cracking","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Cracking"}', 1),
  (4067, 901, 'Explain why cracking is economically useful.', 'text', 1, 'Focus on the core principle of Cracking.', '{"why":"Cracking helps refineries match the supply of products to demand and supplies raw materials for chemical manufacture.","sol":"Step 1: Heavy fractions contain large hydrocarbon molecules.\nStep 2: Demand may be greater for smaller hydrocarbons used as fuels.\nStep 3: Cracking converts some large molecules into smaller, more useful ones.\nStep 4: It also produces alkenes used as chemical feedstocks.","steps":["Step 1: Heavy fractions contain large hydrocarbon molecules.","Step 2: Demand may be greater for smaller hydrocarbons used as fuels.","Step 3: Cracking converts some large molecules into smaller, more useful ones.","Step 4: It also produces alkenes used as chemical feedstocks."],"options":[],"conceptId":"chemistry_organic_chemistry_cracking","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Cracking"}', 2),
  (4068, 901, 'Balance and explain the equation: C₁₀H₂₂ → C₈H₁₈ + C₂H₄.', 'text', 1, 'Count carbon and hydrogen atoms separately on the product side.', '{"why":"A chemical equation is balanced when each element has the same number of atoms on both sides.","sol":"Step 1: Count carbon atoms on the left: 10.\nStep 2: Count carbon atoms on the right: 8 + 2 = 10.\nStep 3: Count hydrogen atoms on the left: 22.\nStep 4: Count hydrogen atoms on the right: 18 + 4 = 22.\nStep 5: Both elements balance, so no coefficient changes are required.","steps":["Step 1: Count carbon atoms on the left: 10.","Step 2: Count carbon atoms on the right: 8 + 2 = 10.","Step 3: Count hydrogen atoms on the left: 22.","Step 4: Count hydrogen atoms on the right: 18 + 4 = 22.","Step 5: Both elements balance, so no coefficient changes are required."],"options":[],"conceptId":"chemistry_organic_chemistry_cracking","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Cracking"}', 3),
  (4069, 901, 'A hydrocarbon with formula C₁₄H₃₀ cracks to form C₁₀H₂₂ and one other hydrocarbon. Determine the formula of the other product.', 'text', 1, 'Subtract the atoms in C₁₀H₂₂ from the total atoms in C₁₄H₃₀.', '{"why":"Atoms are conserved during a chemical reaction, so the other product must contain the remaining four carbon atoms and eight hydrogen atoms.","sol":"Step 1: The starting molecule contains 14 carbon atoms.\nStep 2: C₁₀H₂₂ accounts for 10 carbon atoms, leaving 14 − 10 = 4 carbon atoms.\nStep 3: The starting molecule contains 30 hydrogen atoms.\nStep 4: C₁₀H₂₂ accounts for 22 hydrogen atoms, leaving 30 − 22 = 8 hydrogen atoms.\nStep 5: The other product therefore has formula C₄H₈.","steps":["Step 1: The starting molecule contains 14 carbon atoms.","Step 2: C₁₀H₂₂ accounts for 10 carbon atoms, leaving 14 − 10 = 4 carbon atoms.","Step 3: The starting molecule contains 30 hydrogen atoms.","Step 4: C₁₀H₂₂ accounts for 22 hydrogen atoms, leaving 30 − 22 = 8 hydrogen atoms.","Step 5: The other product therefore has formula C₄H₈."],"options":[],"conceptId":"chemistry_organic_chemistry_cracking","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Cracking"}', 4),
  (4070, 901, 'A cracking product has formula C₅H₁₀. Assuming it is an open-chain hydrocarbon containing one carbon-carbon double bond, identify its homologous series and explain your answer.', 'text', 1, 'Use the general formula for open-chain alkenes.', '{"why":"The stated structural assumption allows the formula to be used to identify the homologous series.","sol":"Step 1: The general formula for an open-chain alkene with one double bond is CₙH₂ₙ.\nStep 2: Here n = 5.\nStep 3: Substituting gives C₅H₁₀.\nStep 4: The formula matches the alkene general formula.","steps":["Step 1: The general formula for an open-chain alkene with one double bond is CₙH₂ₙ.","Step 2: Here n = 5.","Step 3: Substituting gives C₅H₁₀.","Step 4: The formula matches the alkene general formula."],"options":[],"conceptId":"chemistry_organic_chemistry_cracking","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q6","subject":"chemistry","chapter":"organic_chemistry","topic":"Cracking"}', 5),
  (4071, 901, 'Explain why cracking often produces both alkanes and alkenes rather than only alkanes.', 'text', 1, 'Consider the hydrogen-to-carbon ratios of the products and the breaking of large molecules.', '{"why":"The reaction can produce molecules with different degrees of saturation while conserving the total number of atoms.","sol":"Step 1: Cracking breaks large hydrocarbon molecules into smaller molecules.\nStep 2: The products must account for the original carbon and hydrogen atoms.\nStep 3: Some smaller products have enough hydrogen to be alkanes.\nStep 4: Other products have fewer hydrogen atoms relative to carbon and contain carbon-carbon double bonds.\nStep 5: These unsaturated products are alkenes.","steps":["Step 1: Cracking breaks large hydrocarbon molecules into smaller molecules.","Step 2: The products must account for the original carbon and hydrogen atoms.","Step 3: Some smaller products have enough hydrogen to be alkanes.","Step 4: Other products have fewer hydrogen atoms relative to carbon and contain carbon-carbon double bonds.","Step 5: These unsaturated products are alkenes."],"options":[],"conceptId":"chemistry_organic_chemistry_cracking","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q7","subject":"chemistry","chapter":"organic_chemistry","topic":"Cracking"}', 6),
  (4072, 901, 'Compare cracking with fractional distillation of crude oil.', 'text', 1, 'One process separates existing substances; the other breaks molecules apart.', '{"why":"The two processes serve different purposes: separation of a mixture versus conversion of molecules.","sol":"Step 1: Fractional distillation separates hydrocarbons according to their boiling-point ranges.\nStep 2: It is a physical separation and does not normally change the hydrocarbons chemically.\nStep 3: Cracking breaks large hydrocarbon molecules into smaller molecules.\nStep 4: Cracking is a chemical change because new substances are formed.","steps":["Step 1: Fractional distillation separates hydrocarbons according to their boiling-point ranges.","Step 2: It is a physical separation and does not normally change the hydrocarbons chemically.","Step 3: Cracking breaks large hydrocarbon molecules into smaller molecules.","Step 4: Cracking is a chemical change because new substances are formed."],"options":[],"conceptId":"chemistry_organic_chemistry_cracking","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q8","subject":"chemistry","chapter":"organic_chemistry","topic":"Cracking"}', 7),
  (4073, 902, 'A solid element is yellow, brittle and insoluble in water. It is also a poor conductor of electricity. Explain how these observations help identify its non-metallic character.', 'text', 1, 'Focus on the core principle of Properties of Sulphur.', '{"why":"Classification should be based on a pattern of properties, not on colour alone.","sol":"Step 1: Identify its physical state and colour.\nStep 2: Explain that brittleness means it breaks rather than being hammered into sheets.\nStep 3: Relate poor electrical conductivity to a typical property of non-metals.\nStep 4: Use the combined properties to classify the element.","steps":["Step 1: Identify its physical state and colour.","Step 2: Explain that brittleness means it breaks rather than being hammered into sheets.","Step 3: Relate poor electrical conductivity to a typical property of non-metals.","Step 4: Use the combined properties to classify the element."],"options":[],"conceptId":"chemistry_nonmetals_compounds_properties_of_sulphur","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q1","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Properties of Sulphur"}', 0),
  (4074, 902, 'Write the word equation and balanced symbol equation for the burning of sulphur in oxygen.', 'text', 1, 'Focus on the core principle of Properties of Sulphur.', '{"why":"One sulphur atom and two oxygen atoms occur on each side, so the equation is balanced.","sol":"Step 1: Identify sulphur and oxygen as the reactants.\nStep 2: Identify sulphur dioxide as the product.\nStep 3: Write the word equation.\nStep 4: Replace the names with their formulae and count the atoms.","steps":["Step 1: Identify sulphur and oxygen as the reactants.","Step 2: Identify sulphur dioxide as the product.","Step 3: Write the word equation.","Step 4: Replace the names with their formulae and count the atoms."],"options":[],"conceptId":"chemistry_nonmetals_compounds_properties_of_sulphur","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q2","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Properties of Sulphur"}', 1),
  (4075, 902, 'A learner says that sulphur conducts electricity because it is a solid. Identify the error and correct the statement.', 'text', 1, 'Focus on the core principle of Properties of Sulphur.', '{"why":"Being solid does not automatically make a substance electrically conductive.","sol":"Step 1: Separate physical state from electrical conductivity.\nStep 2: Recognise that not every solid conducts electricity.\nStep 3: Apply the known property of sulphur.","steps":["Step 1: Separate physical state from electrical conductivity.","Step 2: Recognise that not every solid conducts electricity.","Step 3: Apply the known property of sulphur."],"options":[],"conceptId":"chemistry_nonmetals_compounds_properties_of_sulphur","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q3","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Properties of Sulphur"}', 2),
  (4076, 902, 'Explain why dissolving sulphur in water is not a suitable method for preparing an aqueous solution of sulphur.', 'text', 1, 'Consider whether sulphur dissolves in water.', '{"why":"Solubility determines whether a substance can form a solution with a particular solvent.","sol":"Step 1: Recall the solubility of sulphur in water.\nStep 2: Determine whether enough sulphur dissolves to form a solution.\nStep 3: State the practical consequence.","steps":["Step 1: Recall the solubility of sulphur in water.","Step 2: Determine whether enough sulphur dissolves to form a solution.","Step 3: State the practical consequence."],"options":[],"conceptId":"chemistry_nonmetals_compounds_properties_of_sulphur","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q4","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Properties of Sulphur"}', 3),
  (4077, 902, 'A piece of sulphur is crushed into powder. Has a new chemical substance formed? Explain your answer.', 'text', 1, 'Focus on the core principle of Properties of Sulphur.', '{"why":"A change in size alone does not produce a new chemical substance.","sol":"Step 1: Identify what has changed: the size of the pieces.\nStep 2: Determine whether the chemical identity has changed.\nStep 3: Classify the change.","steps":["Step 1: Identify what has changed: the size of the pieces.","Step 2: Determine whether the chemical identity has changed.","Step 3: Classify the change."],"options":[],"conceptId":"chemistry_nonmetals_compounds_properties_of_sulphur","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q5","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Properties of Sulphur"}', 4),
  (4078, 902, 'Balance the equation for sulphur combustion: S + O₂ → SO₂. Show how you checked your answer.', 'text', 1, 'Focus on the core principle of Properties of Sulphur.', '{"why":"A balanced chemical equation has equal numbers of each type of atom on both sides.","sol":"Step 1: Count sulphur atoms: one on each side.\nStep 2: Count oxygen atoms: two on each side.\nStep 3: Confirm that no coefficients are needed.","steps":["Step 1: Count sulphur atoms: one on each side.","Step 2: Count oxygen atoms: two on each side.","Step 3: Confirm that no coefficients are needed."],"options":[],"conceptId":"chemistry_nonmetals_compounds_properties_of_sulphur","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q6","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Properties of Sulphur"}', 5),
  (4079, 903, 'A molecule of sulphur dioxide has the formula SO₂. Calculate the total number of atoms in one molecule and state how many belong to each element.', 'text', 1, 'Focus on the core principle of Sulphur Dioxide.', '{"why":"A subscript applies to the element symbol immediately before it.","sol":"Step 1: Read S as one sulphur atom.\nStep 2: Read O₂ as two oxygen atoms.\nStep 3: Add the atoms: 1 + 2 = 3.","steps":["Step 1: Read S as one sulphur atom.","Step 2: Read O₂ as two oxygen atoms.","Step 3: Add the atoms: 1 + 2 = 3."],"options":[],"conceptId":"chemistry_nonmetals_compounds_sulphur_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q1","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Sulphur Dioxide"}', 0),
  (4080, 903, 'Write the balanced chemical equation for the formation of sulphur dioxide from its elements.', 'text', 1, 'Focus on the core principle of Sulphur Dioxide.', '{"why":"The equation conserves one sulphur atom and two oxygen atoms.","sol":"Step 1: Identify sulphur as S and oxygen gas as O₂.\nStep 2: Write SO₂ as the product.\nStep 3: Count sulphur and oxygen atoms on both sides.","steps":["Step 1: Identify sulphur as S and oxygen gas as O₂.","Step 2: Write SO₂ as the product.","Step 3: Count sulphur and oxygen atoms on both sides."],"options":[],"conceptId":"chemistry_nonmetals_compounds_sulphur_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q2","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Sulphur Dioxide"}', 1),
  (4081, 903, 'Explain why moist blue litmus can turn red when exposed to sulphur dioxide.', 'text', 1, 'Think about what happens when the gas dissolves in water.', '{"why":"The indicator responds to the acidity of the moist solution.","sol":"Step 1: Moist litmus contains water.\nStep 2: Sulphur dioxide dissolves in that water and forms an acidic solution.\nStep 3: Apply the effect of an acid on blue litmus.","steps":["Step 1: Moist litmus contains water.","Step 2: Sulphur dioxide dissolves in that water and forms an acidic solution.","Step 3: Apply the effect of an acid on blue litmus."],"options":[],"conceptId":"chemistry_nonmetals_compounds_sulphur_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q3","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Sulphur Dioxide"}', 2),
  (4082, 903, 'A student claims that sulphur dioxide is safe because it is colourless. Explain why this conclusion is wrong.', 'text', 1, 'Focus on the core principle of Sulphur Dioxide.', '{"why":"A gas can be dangerous without having a visible colour.","sol":"Step 1: Recognise that colour describes appearance, not toxicity.\nStep 2: State the health hazard of sulphur dioxide.\nStep 3: Draw a safety conclusion.","steps":["Step 1: Recognise that colour describes appearance, not toxicity.","Step 2: State the health hazard of sulphur dioxide.","Step 3: Draw a safety conclusion."],"options":[],"conceptId":"chemistry_nonmetals_compounds_sulphur_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q4","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Sulphur Dioxide"}', 3),
  (4083, 903, 'Describe two ways sulphur dioxide can harm people or the environment.', 'text', 1, 'Focus on the core principle of Sulphur Dioxide.', '{"why":"Sulphur dioxide causes both direct health effects and environmental harm.","sol":"Step 1: Consider direct effects on breathing.\nStep 2: Consider reactions that occur after the gas enters the atmosphere.\nStep 3: Give two distinct effects.","steps":["Step 1: Consider direct effects on breathing.","Step 2: Consider reactions that occur after the gas enters the atmosphere.","Step 3: Give two distinct effects."],"options":[],"conceptId":"chemistry_nonmetals_compounds_sulphur_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q5","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Sulphur Dioxide"}', 4),
  (4084, 903, 'Explain why controlling sulphur dioxide emissions from industries is important.', 'text', 1, 'Focus on the core principle of Sulphur Dioxide.', '{"why":"Reducing the amount released into the atmosphere reduces the potential for harm.","sol":"Step 1: Identify sources of the gas.\nStep 2: State its health and environmental effects.\nStep 3: Link emission controls to reducing those effects.","steps":["Step 1: Identify sources of the gas.","Step 2: State its health and environmental effects.","Step 3: Link emission controls to reducing those effects."],"options":[],"conceptId":"chemistry_nonmetals_compounds_sulphur_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q6","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Sulphur Dioxide"}', 5),
  (4085, 904, 'Write the school-level equation for sulphur dioxide reacting with water, and name the acid represented.', 'text', 1, 'Focus on the core principle of Reactions of Sulphur Dioxide.', '{"why":"This equation represents the acidic solution formed when sulphur dioxide dissolves in water.","sol":"Step 1: Write the reactants SO₂ and H₂O.\nStep 2: Write the represented product H₂SO₃.\nStep 3: Give the correct acid name.","steps":["Step 1: Write the reactants SO₂ and H₂O.","Step 2: Write the represented product H₂SO₃.","Step 3: Give the correct acid name."],"options":[],"conceptId":"chemistry_nonmetals_compounds_reactions_of_sulphur_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q1","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Reactions of Sulphur Dioxide"}', 0),
  (4086, 904, 'Balance the equation SO₂ + O₂ ⇌ SO₃ and show the atom count on both sides.', 'text', 1, 'Focus on the core principle of Reactions of Sulphur Dioxide.', '{"why":"Balancing ensures that atoms are conserved during the reaction.","sol":"Step 1: Put 2 before SO₂ and 2 before SO₃.\nStep 2: Count sulphur: two atoms on each side.\nStep 3: Count oxygen on the left: four from 2SO₂ plus two from O₂, giving six.\nStep 4: Count oxygen on the right: six from 2SO₃.","steps":["Step 1: Put 2 before SO₂ and 2 before SO₃.","Step 2: Count sulphur: two atoms on each side.","Step 3: Count oxygen on the left: four from 2SO₂ plus two from O₂, giving six.","Step 4: Count oxygen on the right: six from 2SO₃."],"options":[],"conceptId":"chemistry_nonmetals_compounds_reactions_of_sulphur_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q2","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Reactions of Sulphur Dioxide"}', 1),
  (4087, 904, 'Sulphur dioxide is changed into sulphur trioxide. Explain what happens chemically and write the equation.', 'text', 1, 'Focus on the core principle of Reactions of Sulphur Dioxide.', '{"why":"Oxidation in this reaction involves the addition of oxygen to sulphur dioxide.","sol":"Step 1: Compare SO₂ and SO₃.\nStep 2: Each SO₃ molecule contains one more oxygen atom than SO₂.\nStep 3: Oxygen reacts with sulphur dioxide.\nStep 4: Balance the equation.","steps":["Step 1: Compare SO₂ and SO₃.","Step 2: Each SO₃ molecule contains one more oxygen atom than SO₂.","Step 3: Oxygen reacts with sulphur dioxide.","Step 4: Balance the equation."],"options":[],"conceptId":"chemistry_nonmetals_compounds_reactions_of_sulphur_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q3","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Reactions of Sulphur Dioxide"}', 2),
  (4088, 904, 'Explain why the equation for the reaction of sulphur dioxide with water is commonly written with a double arrow.', 'text', 1, 'Think about whether the reaction can proceed in both directions.', '{"why":"A double arrow distinguishes a reversible reaction from an equation represented as proceeding in one direction only.","sol":"Step 1: Identify the reactants and represented product.\nStep 2: Recognise that the aqueous reaction is reversible.\nStep 3: Explain what the double arrow communicates.","steps":["Step 1: Identify the reactants and represented product.","Step 2: Recognise that the aqueous reaction is reversible.","Step 3: Explain what the double arrow communicates."],"options":[],"conceptId":"chemistry_nonmetals_compounds_reactions_of_sulphur_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q4","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Reactions of Sulphur Dioxide"}', 3),
  (4089, 904, 'In the Contact Process, why is converting sulphur dioxide into sulphur trioxide an important step?', 'text', 1, 'Focus on the core principle of Reactions of Sulphur Dioxide.', '{"why":"The oxidation of SO₂ provides SO₃, which is needed in the next part of the industrial process.","sol":"Step 1: Identify the product of the oxidation reaction.\nStep 2: Recall the role of sulphur trioxide in making sulphuric acid.\nStep 3: Link the intermediate to the overall industrial process.","steps":["Step 1: Identify the product of the oxidation reaction.","Step 2: Recall the role of sulphur trioxide in making sulphuric acid.","Step 3: Link the intermediate to the overall industrial process."],"options":[],"conceptId":"chemistry_nonmetals_compounds_reactions_of_sulphur_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q5","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Reactions of Sulphur Dioxide"}', 4),
  (4090, 904, 'A learner balances SO₂ + O₂ ⇌ SO₃ as SO₂ + O₂ ⇌ SO₃ and says the equation is balanced. Show why the claim is wrong and correct it.', 'text', 1, 'Focus on the core principle of Reactions of Sulphur Dioxide.', '{"why":"A correct equation must conserve every type of atom, not just sulphur.","sol":"Step 1: Count sulphur atoms: one on each side.\nStep 2: Count oxygen atoms on the left: two plus two, giving four.\nStep 3: Count oxygen atoms on the right: three.\nStep 4: Change the coefficients and recount.","steps":["Step 1: Count sulphur atoms: one on each side.","Step 2: Count oxygen atoms on the left: two plus two, giving four.","Step 3: Count oxygen atoms on the right: three.","Step 4: Change the coefficients and recount."],"options":[],"conceptId":"chemistry_nonmetals_compounds_reactions_of_sulphur_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q6","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Reactions of Sulphur Dioxide"}', 5),
  (4091, 905, 'Calculate the total number of atoms in one molecule of SO₃ and state the number of atoms of each element.', 'text', 1, 'Focus on the core principle of Sulphur Trioxide.', '{"why":"The subscript 3 applies to oxygen only.","sol":"Step 1: S has no subscript, so it represents one sulphur atom.\nStep 2: O₃ represents three oxygen atoms.\nStep 3: Add 1 + 3 = 4 atoms.","steps":["Step 1: S has no subscript, so it represents one sulphur atom.","Step 2: O₃ represents three oxygen atoms.","Step 3: Add 1 + 3 = 4 atoms."],"options":[],"conceptId":"chemistry_nonmetals_compounds_sulphur_trioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q1","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Sulphur Trioxide"}', 0),
  (4092, 905, 'Balance the equation SO₂ + O₂ ⇌ SO₃ and show the number of sulphur and oxygen atoms on each side.', 'text', 1, 'Focus on the core principle of Sulphur Trioxide.', '{"why":"The coefficients make the number of each type of atom equal on both sides.","sol":"Step 1: Put 2 before SO₂ and 2 before SO₃.\nStep 2: Count sulphur: 2 atoms on each side.\nStep 3: Count oxygen on the left: 4 + 2 = 6.\nStep 4: Count oxygen on the right: 6.","steps":["Step 1: Put 2 before SO₂ and 2 before SO₃.","Step 2: Count sulphur: 2 atoms on each side.","Step 3: Count oxygen on the left: 4 + 2 = 6.","Step 4: Count oxygen on the right: 6."],"options":[],"conceptId":"chemistry_nonmetals_compounds_sulphur_trioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q2","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Sulphur Trioxide"}', 1),
  (4093, 905, 'Write the equation for sulphur trioxide reacting with water. Name the product and explain why the reaction requires care.', 'text', 1, 'Focus on the core principle of Sulphur Trioxide.', '{"why":"The strong heat release and acid mist make direct absorption into water difficult to control.","sol":"Step 1: Write SO₃ and H₂O as the reactants.\nStep 2: Write H₂SO₄ as the product.\nStep 3: Check that the equation is balanced.\nStep 4: Recall that the reaction releases considerable heat.","steps":["Step 1: Write SO₃ and H₂O as the reactants.","Step 2: Write H₂SO₄ as the product.","Step 3: Check that the equation is balanced.","Step 4: Recall that the reaction releases considerable heat."],"options":[],"conceptId":"chemistry_nonmetals_compounds_sulphur_trioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q3","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Sulphur Trioxide"}', 2),
  (4094, 905, 'Explain why converting sulphur dioxide into sulphur trioxide is described as oxidation.', 'text', 1, 'Focus on the core principle of Sulphur Trioxide.', '{"why":"At this level, oxidation can be identified as the addition of oxygen.","sol":"Step 1: Compare the formulae SO₂ and SO₃.\nStep 2: Notice that SO₃ contains one more oxygen atom per sulphur atom.\nStep 3: Relate the addition of oxygen to oxidation.","steps":["Step 1: Compare the formulae SO₂ and SO₃.","Step 2: Notice that SO₃ contains one more oxygen atom per sulphur atom.","Step 3: Relate the addition of oxygen to oxidation."],"options":[],"conceptId":"chemistry_nonmetals_compounds_sulphur_trioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q4","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Sulphur Trioxide"}', 3),
  (4095, 905, 'State the role of the vanadium(V) oxide catalyst in forming sulphur trioxide in the Contact Process.', 'text', 1, 'Focus on the core principle of Sulphur Trioxide.', '{"why":"A catalyst provides a faster reaction pathway without changing the equilibrium composition.","sol":"Step 1: Identify the reaction as the oxidation of SO₂ by O₂.\nStep 2: State what a catalyst does to reaction rate.\nStep 3: Explain what the catalyst does not change.","steps":["Step 1: Identify the reaction as the oxidation of SO₂ by O₂.","Step 2: State what a catalyst does to reaction rate.","Step 3: Explain what the catalyst does not change."],"options":[],"conceptId":"chemistry_nonmetals_compounds_sulphur_trioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q5","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Sulphur Trioxide"}', 4),
  (4096, 905, 'Explain why industries absorb sulphur trioxide into concentrated sulphuric acid instead of directly absorbing it into water.', 'text', 1, 'Focus on the core principle of Sulphur Trioxide.', '{"why":"The industrial method allows the reaction and product formation to be controlled more effectively.","sol":"Step 1: Recognise that SO₃ reacts vigorously with water.\nStep 2: Identify the problems caused by heat release and acid mist.\nStep 3: State the industrial alternative.","steps":["Step 1: Recognise that SO₃ reacts vigorously with water.","Step 2: Identify the problems caused by heat release and acid mist.","Step 3: State the industrial alternative."],"options":[],"conceptId":"chemistry_nonmetals_compounds_sulphur_trioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q6","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Sulphur Trioxide"}', 5),
  (4097, 906, 'Determine the total number of atoms in one formula unit of H₂SO₄ and show how you obtained your answer.', 'text', 1, 'Focus on the core principle of Sulphuric Acid.', '{"why":"Subscripts indicate how many atoms of each element are represented.","sol":"Step 1: Count 2 hydrogen atoms.\nStep 2: Count 1 sulphur atom.\nStep 3: Count 4 oxygen atoms.\nStep 4: Add 2 + 1 + 4 = 7.","steps":["Step 1: Count 2 hydrogen atoms.","Step 2: Count 1 sulphur atom.","Step 3: Count 4 oxygen atoms.","Step 4: Add 2 + 1 + 4 = 7."],"options":[],"conceptId":"chemistry_nonmetals_compounds_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q1","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Sulphuric Acid"}', 0),
  (4098, 906, 'Write and balance the equation for complete neutralisation of sulphuric acid by sodium hydroxide.', 'text', 1, 'Focus on the core principle of Sulphuric Acid.', '{"why":"The balanced equation conserves hydrogen, sulphur, oxygen and sodium atoms.","sol":"Step 1: Write the reactants H₂SO₄ and NaOH.\nStep 2: Identify sodium sulphate and water as the products.\nStep 3: Put 2 before NaOH to balance sodium.\nStep 4: Put 2 before H₂O and check every element.","steps":["Step 1: Write the reactants H₂SO₄ and NaOH.","Step 2: Identify sodium sulphate and water as the products.","Step 3: Put 2 before NaOH to balance sodium.","Step 4: Put 2 before H₂O and check every element."],"options":[],"conceptId":"chemistry_nonmetals_compounds_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q2","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Sulphuric Acid"}', 1),
  (4099, 906, 'A student tests an aqueous solution of sulphuric acid with blue litmus. Predict the result and explain it.', 'text', 1, 'Focus on the core principle of Sulphuric Acid.', '{"why":"Acidic solutions change blue litmus to red.","sol":"Step 1: Identify sulphuric acid solution as acidic.\nStep 2: Recall the behaviour of blue litmus in an acid.\nStep 3: State the expected colour change.","steps":["Step 1: Identify sulphuric acid solution as acidic.","Step 2: Recall the behaviour of blue litmus in an acid.","Step 3: State the expected colour change."],"options":[],"conceptId":"chemistry_nonmetals_compounds_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q3","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Sulphuric Acid"}', 2),
  (4100, 906, 'Explain the difference between a strong acid and a concentrated acid. Use sulphuric acid in your explanation.', 'text', 1, 'Focus on the core principle of Sulphuric Acid.', '{"why":"Strength and concentration measure different things and should not be used as synonyms.","sol":"Step 1: Define acid strength in terms of ionisation in water.\nStep 2: Define concentration in terms of amount per volume.\nStep 3: Explain why the terms describe different properties.","steps":["Step 1: Define acid strength in terms of ionisation in water.","Step 2: Define concentration in terms of amount per volume.","Step 3: Explain why the terms describe different properties."],"options":[],"conceptId":"chemistry_nonmetals_compounds_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q4","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Sulphuric Acid"}', 3),
  (4101, 906, 'State the safe procedure for diluting concentrated sulphuric acid and explain the main hazard.', 'text', 1, 'Focus on the core principle of Sulphuric Acid.', '{"why":"The heat released during dilution can cause local boiling and splashes.","sol":"Step 1: Put water in a suitable container.\nStep 2: Add acid slowly to the water while stirring.\nStep 3: Use suitable protective equipment.\nStep 4: Explain that dilution releases considerable heat.","steps":["Step 1: Put water in a suitable container.","Step 2: Add acid slowly to the water while stirring.","Step 3: Use suitable protective equipment.","Step 4: Explain that dilution releases considerable heat."],"options":[],"conceptId":"chemistry_nonmetals_compounds_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q5","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Sulphuric Acid"}', 4),
  (4102, 906, 'Concentrated sulphuric acid can act as a dehydrating agent. Explain what this means.', 'text', 1, 'Focus on the core principle of Sulphuric Acid.', '{"why":"Its dehydrating action is a property distinct from its ability to behave as an acid.","sol":"Step 1: Identify water as the substance removed.\nStep 2: Explain that the acid removes water from some materials.\nStep 3: Distinguish this action from simply being an acidic solution.","steps":["Step 1: Identify water as the substance removed.","Step 2: Explain that the acid removes water from some materials.","Step 3: Distinguish this action from simply being an acidic solution."],"options":[],"conceptId":"chemistry_nonmetals_compounds_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q6","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Sulphuric Acid"}', 5),
  (4103, 907, 'Describe the five main stages of the Contact Process in the correct order.', 'text', 1, 'Focus on the core principle of Manufacture of Sulphuric Acid.', '{"why":"Each stage prepares the material required by the next stage of the industrial process.","sol":"Step 1: Produce sulphur dioxide from sulphur or a suitable sulphide ore.\nStep 2: Purify and dry the gases.\nStep 3: Oxidise SO₂ to SO₃ using a catalyst.\nStep 4: Absorb SO₃ into concentrated sulphuric acid to form oleum.\nStep 5: Dilute oleum carefully to obtain sulphuric acid.","steps":["Step 1: Produce sulphur dioxide from sulphur or a suitable sulphide ore.","Step 2: Purify and dry the gases.","Step 3: Oxidise SO₂ to SO₃ using a catalyst.","Step 4: Absorb SO₃ into concentrated sulphuric acid to form oleum.","Step 5: Dilute oleum carefully to obtain sulphuric acid."],"options":[],"conceptId":"chemistry_nonmetals_compounds_manufacture_of_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q1","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Manufacture of Sulphuric Acid"}', 0),
  (4104, 907, 'Write and balance the equation for converting sulphur dioxide into sulphur trioxide in the Contact Process.', 'text', 1, 'Focus on the core principle of Manufacture of Sulphuric Acid.', '{"why":"Equal numbers of sulphur and oxygen atoms must appear on both sides.","sol":"Step 1: Write SO₂ + O₂ ⇌ SO₃.\nStep 2: Put 2 before SO₂ to give two sulphur atoms.\nStep 3: Put 2 before SO₃ to balance sulphur.\nStep 4: Check oxygen: six atoms on each side.","steps":["Step 1: Write SO₂ + O₂ ⇌ SO₃.","Step 2: Put 2 before SO₂ to give two sulphur atoms.","Step 3: Put 2 before SO₃ to balance sulphur.","Step 4: Check oxygen: six atoms on each side."],"options":[],"conceptId":"chemistry_nonmetals_compounds_manufacture_of_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q2","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Manufacture of Sulphuric Acid"}', 1),
  (4105, 907, 'State the catalyst and approximate operating temperature used for converting sulphur dioxide to sulphur trioxide.', 'text', 1, 'Focus on the core principle of Manufacture of Sulphuric Acid.', '{"why":"These conditions provide a practical balance between reaction rate and equilibrium yield.","sol":"Step 1: Identify the Contact Process conversion stage.\nStep 2: Recall the catalyst used in the industrial reaction.\nStep 3: State the approximate operating temperature.","steps":["Step 1: Identify the Contact Process conversion stage.","Step 2: Recall the catalyst used in the industrial reaction.","Step 3: State the approximate operating temperature."],"options":[],"conceptId":"chemistry_nonmetals_compounds_manufacture_of_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q3","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Manufacture of Sulphuric Acid"}', 2),
  (4106, 907, 'Explain why the gas mixture is purified before it enters the catalytic conversion stage.', 'text', 1, 'Focus on the core principle of Manufacture of Sulphuric Acid.', '{"why":"Clean gas is important for reliable catalytic conversion and industrial operation.","sol":"Step 1: Identify the catalyst as necessary for the conversion reaction.\nStep 2: Recognise that impurities can interfere with the catalyst or equipment.\nStep 3: Explain the benefit of purification.","steps":["Step 1: Identify the catalyst as necessary for the conversion reaction.","Step 2: Recognise that impurities can interfere with the catalyst or equipment.","Step 3: Explain the benefit of purification."],"options":[],"conceptId":"chemistry_nonmetals_compounds_manufacture_of_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q4","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Manufacture of Sulphuric Acid"}', 3),
  (4107, 907, 'Explain why sulphur trioxide is absorbed into concentrated sulphuric acid rather than directly into water in the industrial process.', 'text', 1, 'Focus on the core principle of Manufacture of Sulphuric Acid.', '{"why":"The absorption stage is designed to manage the reaction and produce sulphuric acid more effectively.","sol":"Step 1: Recognise that SO₃ reacts vigorously with water.\nStep 2: Identify the heat release and acid mist as problems.\nStep 3: State how the industrial process avoids these difficulties.","steps":["Step 1: Recognise that SO₃ reacts vigorously with water.","Step 2: Identify the heat release and acid mist as problems.","Step 3: State how the industrial process avoids these difficulties."],"options":[],"conceptId":"chemistry_nonmetals_compounds_manufacture_of_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q5","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Manufacture of Sulphuric Acid"}', 4),
  (4108, 907, 'Write the equation for oleum reacting with water and check whether it is balanced: H₂S₂O₇ + H₂O → 2H₂SO₄.', 'text', 1, 'Focus on the core principle of Manufacture of Sulphuric Acid.', '{"why":"The coefficients conserve all atoms while showing the conversion of oleum to sulphuric acid.","sol":"Step 1: Count hydrogen on the left: 2 + 2 = 4.\nStep 2: Count sulphur on the left: 2.\nStep 3: Count oxygen on the left: 7 + 1 = 8.\nStep 4: Count atoms on the right: 4 hydrogen, 2 sulphur and 8 oxygen.","steps":["Step 1: Count hydrogen on the left: 2 + 2 = 4.","Step 2: Count sulphur on the left: 2.","Step 3: Count oxygen on the left: 7 + 1 = 8.","Step 4: Count atoms on the right: 4 hydrogen, 2 sulphur and 8 oxygen."],"options":[],"conceptId":"chemistry_nonmetals_compounds_manufacture_of_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q6","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Manufacture of Sulphuric Acid"}', 5),
  (4109, 908, 'Write a balanced equation for the reaction between sulphuric acid and ammonia to form ammonium sulphate.', 'text', 1, 'Focus on the core principle of Uses of Sulphuric Acid.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"H₂SO₄ + 2NH₃ → (NH₄)₂SO₄","steps":["Step 1: Identify key concept: Define the required principles for Uses of Sulphuric Acid.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: H2SO4 + 2NH3 → (NH4)2SO4"],"options":[],"conceptId":"chemistry_nonmetals_compounds_uses_of_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q1","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Uses of Sulphuric Acid"}', 0),
  (4110, 908, 'Copper(II) oxide reacts with dilute sulphuric acid. Name the salt formed and write the balanced equation.', 'text', 1, 'Focus on the core principle of Uses of Sulphuric Acid.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"CuO + H₂SO₄ → CuSO₄ + H₂O","steps":["Step 1: Identify key concept: Define the required principles for Uses of Sulphuric Acid.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Copper(II) sulphate; CuO + H2SO4 → CuSO4 + H2O"],"options":[],"conceptId":"chemistry_nonmetals_compounds_uses_of_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q2","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Uses of Sulphuric Acid"}', 1),
  (4111, 908, 'Explain why dilute sulphuric acid is used in a lead-acid battery.', 'text', 1, 'Focus on the core principle of Uses of Sulphuric Acid.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"The acid provides mobile ions that enable the battery''s electrochemical reactions.","steps":["Step 1: Identify key concept: Define the required principles for Uses of Sulphuric Acid.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: It acts as an electrolyte and allows ions to move during charging and discharging."],"options":[],"conceptId":"chemistry_nonmetals_compounds_uses_of_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q3","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Uses of Sulphuric Acid"}', 2),
  (4112, 908, 'State two uses of sulphuric acid in industry.', 'text', 1, 'Think about agricultural chemicals and manufactured products.', '{"why":"Sulphuric acid is a major industrial reagent used in fertiliser production and chemical manufacture.","sol":"Step 1: Identify one use related to agriculture.\nStep 2: Identify another use in chemical or industrial production.","steps":["Step 1: Identify one use related to agriculture.","Step 2: Identify another use in chemical or industrial production."],"options":[],"conceptId":"chemistry_nonmetals_compounds_uses_of_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q4","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Uses of Sulphuric Acid"}', 3),
  (4113, 908, 'Write a balanced equation for the reaction of sulphuric acid with ammonia to produce ammonium sulphate.', 'text', 1, 'The formula of ammonia is NH3 and ammonium sulphate is (NH4)2SO4.', '{"why":"Two ammonia molecules provide the two nitrogen atoms required in ammonium sulphate.","sol":"Step 1: Write H2SO4 + NH3 → (NH4)2SO4.\nStep 2: Count the two NH4 groups in the product.\nStep 3: Place 2 before NH3 and check all atoms.","steps":["Step 1: Write H2SO4 + NH3 → (NH4)2SO4.","Step 2: Count the two NH4 groups in the product.","Step 3: Place 2 before NH3 and check all atoms."],"options":[],"conceptId":"chemistry_nonmetals_compounds_uses_of_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q5","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Uses of Sulphuric Acid"}', 4),
  (4114, 908, 'A student reacts copper(II) oxide with dilute sulphuric acid. Name the salt and the other product.', 'text', 1, 'An acid reacting with a metal oxide produces a salt and water.', '{"why":"The reaction is CuO + H2SO4 → CuSO4 + H2O.","sol":"Step 1: Identify copper(II) oxide as a metal oxide.\nStep 2: Combine the copper ion with the sulphate ion to identify the salt.\nStep 3: State the second product.","steps":["Step 1: Identify copper(II) oxide as a metal oxide.","Step 2: Combine the copper ion with the sulphate ion to identify the salt.","Step 3: State the second product."],"options":[],"conceptId":"chemistry_nonmetals_compounds_uses_of_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q6","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Uses of Sulphuric Acid"}', 5),
  (4115, 908, 'Explain the function of the electrolyte in a lead-acid battery and identify the electrolyte used.', 'text', 1, 'Consider the movement of ions.', '{"why":"An electrolyte enables ionic conduction inside the battery.","sol":"Step 1: Name the electrolyte.\nStep 2: Explain how it supports ionic movement during battery operation.","steps":["Step 1: Name the electrolyte.","Step 2: Explain how it supports ionic movement during battery operation."],"options":[],"conceptId":"chemistry_nonmetals_compounds_uses_of_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q7","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Uses of Sulphuric Acid"}', 6),
  (4116, 908, 'Why must sulphuric acid be handled carefully, and what is the correct procedure for dilution?', 'text', 1, 'Consider corrosiveness and heat released during dilution.', '{"why":"Dilution releases heat, and adding water to concentrated acid can cause violent heating and splashing.","sol":"Step 1: State the danger posed by the acid.\nStep 2: Explain the order in which acid and water should be mixed.","steps":["Step 1: State the danger posed by the acid.","Step 2: Explain the order in which acid and water should be mixed."],"options":[],"conceptId":"chemistry_nonmetals_compounds_uses_of_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q8","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Uses of Sulphuric Acid"}', 7),
  (4117, 908, 'Explain how sulphuric acid helps in the manufacture of fertilisers.', 'text', 1, 'Name a fertiliser that can be formed from ammonia and sulphuric acid.', '{"why":"Ammonium sulphate supplies nitrogen and sulphur to plants.","sol":"Step 1: Name a fertiliser made using sulphuric acid.\nStep 2: Give the reactants involved.\nStep 3: Write the balanced equation.","steps":["Step 1: Name a fertiliser made using sulphuric acid.","Step 2: Give the reactants involved.","Step 3: Write the balanced equation."],"options":[],"conceptId":"chemistry_nonmetals_compounds_uses_of_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q9","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Uses of Sulphuric Acid"}', 8),
  (4118, 909, 'A neutral carbon atom has atomic number 6. Give its electron arrangement and number of outer-shell electrons.', 'text', 1, 'Focus on the core principle of Properties of Carbon.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Six electrons are arranged as two in the first shell and four in the second shell.","steps":["Step 1: Identify key concept: Define the required principles for Properties of Carbon.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: 2,4; four outer-shell electrons."],"options":[],"conceptId":"chemistry_nonmetals_compounds_properties_of_carbon","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q1","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Properties of Carbon"}', 0),
  (4119, 909, 'Explain why carbon is described as tetravalent.', 'text', 1, 'Focus on the core principle of Properties of Carbon.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Carbon has four outer-shell electrons and can share electrons to form four covalent bonds.","steps":["Step 1: Identify key concept: Define the required principles for Properties of Carbon.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: It commonly forms four covalent bonds."],"options":[],"conceptId":"chemistry_nonmetals_compounds_properties_of_carbon","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q2","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Properties of Carbon"}', 1),
  (4120, 909, 'Define catenation and explain why it is important in carbon chemistry.', 'text', 1, 'Focus on the core principle of Properties of Carbon.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Strong carbon-carbon bonds allow carbon atoms to form long chains, branched chains and rings.","steps":["Step 1: Identify key concept: Define the required principles for Properties of Carbon.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Catenation is bonding between atoms of the same element to form chains or rings; carbon catenation allows many different carbon compounds."],"options":[],"conceptId":"chemistry_nonmetals_compounds_properties_of_carbon","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q3","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Properties of Carbon"}', 2),
  (4121, 909, 'Carbon has atomic number 6. Determine its electron arrangement and explain how you obtained it.', 'text', 1, 'A neutral atom has the same number of electrons as its atomic number.', '{"why":"The atomic number gives the number of protons and, in a neutral atom, the number of electrons.","sol":"Step 1: State the total number of electrons in a neutral carbon atom.\nStep 2: Place two electrons in the first shell.\nStep 3: Place the remaining electrons in the second shell.","steps":["Step 1: State the total number of electrons in a neutral carbon atom.","Step 2: Place two electrons in the first shell.","Step 3: Place the remaining electrons in the second shell."],"options":[],"conceptId":"chemistry_nonmetals_compounds_properties_of_carbon","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q4","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Properties of Carbon"}', 3),
  (4122, 909, 'What is tetravalency, and how does the structure of methane demonstrate it?', 'text', 1, 'Consider how many bonds the carbon atom forms in CH4.', '{"why":"The four C–H bonds demonstrate carbon''s ability to share electrons with four hydrogen atoms.","sol":"Step 1: Define tetravalency.\nStep 2: Count the bonds formed by carbon in methane.\nStep 3: Relate the number of bonds to the definition.","steps":["Step 1: Define tetravalency.","Step 2: Count the bonds formed by carbon in methane.","Step 3: Relate the number of bonds to the definition."],"options":[],"conceptId":"chemistry_nonmetals_compounds_properties_of_carbon","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q5","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Properties of Carbon"}', 4),
  (4123, 909, 'Define catenation and give two types of carbon structures it can produce.', 'text', 1, 'Think about how carbon atoms join to other carbon atoms.', '{"why":"Carbon-carbon covalent bonds allow carbon atoms to link in several arrangements.","sol":"Step 1: Define bonding between atoms of the same element.\nStep 2: Name two structures formed by carbon-carbon bonding.","steps":["Step 1: Define bonding between atoms of the same element.","Step 2: Name two structures formed by carbon-carbon bonding."],"options":[],"conceptId":"chemistry_nonmetals_compounds_properties_of_carbon","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q6","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Properties of Carbon"}', 5),
  (4124, 909, 'Write the balanced equation for the complete combustion of carbon and name the product.', 'text', 1, 'Complete combustion occurs in plentiful oxygen.', '{"why":"One carbon atom reacts with one oxygen molecule to form one carbon dioxide molecule.","sol":"Step 1: Write carbon and oxygen as reactants.\nStep 2: Identify carbon dioxide as the product.\nStep 3: Check that carbon and oxygen atoms balance.","steps":["Step 1: Write carbon and oxygen as reactants.","Step 2: Identify carbon dioxide as the product.","Step 3: Check that carbon and oxygen atoms balance."],"options":[],"conceptId":"chemistry_nonmetals_compounds_properties_of_carbon","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q7","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Properties of Carbon"}', 6),
  (4125, 909, 'Write the balanced equation for the formation of carbon monoxide when carbon burns in insufficient oxygen.', 'text', 1, 'The product formula is CO. Balance the oxygen atoms first.', '{"why":"Two carbon atoms combine with one oxygen molecule to form two carbon monoxide molecules.","sol":"Step 1: Write C + O2 → CO.\nStep 2: Place 2 before CO to use both oxygen atoms.\nStep 3: Place 2 before C to balance carbon atoms.","steps":["Step 1: Write C + O2 → CO.","Step 2: Place 2 before CO to use both oxygen atoms.","Step 3: Place 2 before C to balance carbon atoms."],"options":[],"conceptId":"chemistry_nonmetals_compounds_properties_of_carbon","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q8","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Properties of Carbon"}', 7),
  (4126, 909, 'Distinguish between tetravalency and catenation in carbon.', 'text', 1, 'One property describes the number of bonds; the other describes which atoms carbon bonds to.', '{"why":"The terms describe different aspects of carbon bonding.","sol":"Step 1: State what tetravalency describes.\nStep 2: State what catenation describes.","steps":["Step 1: State what tetravalency describes.","Step 2: State what catenation describes."],"options":[],"conceptId":"chemistry_nonmetals_compounds_properties_of_carbon","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q9","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Properties of Carbon"}', 8),
  (4127, 910, 'Write the balanced equation for the reaction between calcium carbonate and dilute hydrochloric acid.', 'text', 1, 'Focus on the core principle of Carbon Dioxide.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂","steps":["Step 1: Identify key concept: Define the required principles for Carbon Dioxide.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: CaCO3 + 2HCl → CaCl2 + H2O + CO2"],"options":[],"conceptId":"chemistry_nonmetals_compounds_carbon_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q1","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Carbon Dioxide"}', 0),
  (4128, 910, 'Describe the test for carbon dioxide using limewater and explain the result.', 'text', 1, 'Focus on the core principle of Carbon Dioxide.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"CO₂ + Ca(OH)₂ → CaCO₃ + H₂O","steps":["Step 1: Identify key concept: Define the required principles for Carbon Dioxide.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Bubble the gas through limewater; it turns milky because calcium carbonate forms."],"options":[],"conceptId":"chemistry_nonmetals_compounds_carbon_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q2","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Carbon Dioxide"}', 1),
  (4129, 910, 'Explain why limewater may become clear when excess carbon dioxide is passed through it.', 'text', 1, 'Focus on the core principle of Carbon Dioxide.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"CaCO₃ + CO₂ + H₂O → Ca(HCO₃)₂","steps":["Step 1: Identify key concept: Define the required principles for Carbon Dioxide.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Insoluble calcium carbonate reacts with excess carbon dioxide and water to form soluble calcium hydrogencarbonate."],"options":[],"conceptId":"chemistry_nonmetals_compounds_carbon_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q3","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Carbon Dioxide"}', 2),
  (4130, 910, 'Write a balanced equation for preparing carbon dioxide from calcium carbonate and dilute hydrochloric acid.', 'text', 1, 'The products are calcium chloride, water and carbon dioxide.', '{"why":"Two hydrochloric acid molecules provide the two chlorine atoms needed for calcium chloride and balance hydrogen.","sol":"Step 1: Write CaCO3 + HCl as the reactants.\nStep 2: Write CaCl2 + H2O + CO2 as the products.\nStep 3: Balance chlorine and hydrogen by placing 2 before HCl.","steps":["Step 1: Write CaCO3 + HCl as the reactants.","Step 2: Write CaCl2 + H2O + CO2 as the products.","Step 3: Balance chlorine and hydrogen by placing 2 before HCl."],"options":[],"conceptId":"chemistry_nonmetals_compounds_carbon_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q4","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Carbon Dioxide"}', 3),
  (4131, 910, 'Describe the laboratory test for carbon dioxide and explain the chemical change responsible for the observation.', 'text', 1, 'Use limewater, which contains calcium hydroxide.', '{"why":"Carbon dioxide reacts with calcium hydroxide to produce insoluble calcium carbonate.","sol":"Step 1: Pass the gas through limewater.\nStep 2: State the visible observation.\nStep 3: Name the insoluble compound formed.","steps":["Step 1: Pass the gas through limewater.","Step 2: State the visible observation.","Step 3: Name the insoluble compound formed."],"options":[],"conceptId":"chemistry_nonmetals_compounds_carbon_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q5","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Carbon Dioxide"}', 4),
  (4132, 910, 'Write the equation for the reaction between carbon dioxide and limewater.', 'text', 1, 'The reactants are CO2 and Ca(OH)2.', '{"why":"The equation represents the formation of a calcium carbonate precipitate.","sol":"Step 1: Write the two reactants.\nStep 2: Identify calcium carbonate and water as products.\nStep 3: Check that all atoms balance.","steps":["Step 1: Write the two reactants.","Step 2: Identify calcium carbonate and water as products.","Step 3: Check that all atoms balance."],"options":[],"conceptId":"chemistry_nonmetals_compounds_carbon_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q6","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Carbon Dioxide"}', 5),
  (4133, 910, 'Explain why limewater can turn milky first and then become clear when excess carbon dioxide is passed through it.', 'text', 1, 'Compare the solubility of calcium carbonate with calcium hydrogencarbonate.', '{"why":"The initial precipitate causes milkiness; its conversion into a soluble substance removes the precipitate.","sol":"Step 1: Explain why calcium carbonate makes the limewater milky.\nStep 2: Consider what happens when more carbon dioxide and water react with that precipitate.\nStep 3: Identify the soluble product.","steps":["Step 1: Explain why calcium carbonate makes the limewater milky.","Step 2: Consider what happens when more carbon dioxide and water react with that precipitate.","Step 3: Identify the soluble product."],"options":[],"conceptId":"chemistry_nonmetals_compounds_carbon_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q7","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Carbon Dioxide"}', 6),
  (4134, 910, 'State two physical properties of carbon dioxide and one chemical property.', 'text', 1, 'Separate observations about the gas itself from its reactions.', '{"why":"Physical properties can be observed without changing the substance; chemical properties describe its reactions.","sol":"Step 1: Give two physical properties.\nStep 2: Give one property involving a chemical reaction.","steps":["Step 1: Give two physical properties.","Step 2: Give one property involving a chemical reaction."],"options":[],"conceptId":"chemistry_nonmetals_compounds_carbon_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q8","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Carbon Dioxide"}', 7),
  (4135, 910, 'Explain why carbon dioxide is used in some fire extinguishers and state one environmental effect of atmospheric carbon dioxide.', 'text', 1, 'Think about combustion and the greenhouse effect.', '{"why":"Carbon dioxide reduces oxygen available to a fire and absorbs outgoing infrared radiation in the atmosphere.","sol":"Step 1: Explain how carbon dioxide affects the oxygen supply around a fire.\nStep 2: State its role in the atmosphere.","steps":["Step 1: Explain how carbon dioxide affects the oxygen supply around a fire.","Step 2: State its role in the atmosphere."],"options":[],"conceptId":"chemistry_nonmetals_compounds_carbon_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q9","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Carbon Dioxide"}', 8),
  (4136, 911, 'Write the balanced equation for preparing ammonia by heating ammonium chloride with calcium hydroxide.', 'text', 1, 'Focus on the core principle of Ammonia.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"2NH₄Cl + Ca(OH)₂ → CaCl₂ + 2H₂O + 2NH₃","steps":["Step 1: Identify key concept: Define the required principles for Ammonia.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: 2NH4Cl + Ca(OH)2 → CaCl2 + 2H2O + 2NH3"],"options":[],"conceptId":"chemistry_nonmetals_compounds_ammonia","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q1","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Ammonia"}', 0),
  (4137, 911, 'State the drying agent and collection method used for ammonia gas, explaining why water is unsuitable for collection.', 'text', 1, 'Focus on the core principle of Ammonia.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"CaO dries ammonia without reacting with it. Ammonia is less dense than air and dissolves readily in water.","steps":["Step 1: Identify key concept: Define the required principles for Ammonia.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Quicklime (calcium oxide); downward displacement of air; ammonia is highly soluble in water."],"options":[],"conceptId":"chemistry_nonmetals_compounds_ammonia","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q2","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Ammonia"}', 1),
  (4138, 911, 'Describe the test for ammonia using damp red litmus paper and explain the result.', 'text', 1, 'Focus on the core principle of Ammonia.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"NH3 + H2O ⇌ NH4+ + OH−. The hydroxide ions make the solution alkaline.","steps":["Step 1: Identify key concept: Define the required principles for Ammonia.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Ammonia turns damp red litmus paper blue because dissolved ammonia produces hydroxide ions."],"options":[],"conceptId":"chemistry_nonmetals_compounds_ammonia","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q3","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Ammonia"}', 2),
  (4139, 911, 'Write a balanced equation for preparing ammonia from ammonium chloride and calcium hydroxide. Explain how you balance it.', 'text', 1, 'The products are calcium chloride, water and ammonia.', '{"why":"Two ammonium chloride units supply two nitrogen atoms and two chlorine atoms, matching the products.","sol":"Step 1: Write NH4Cl + Ca(OH)2 → CaCl2 + H2O + NH3.\nStep 2: Balance chlorine by placing 2 before NH4Cl.\nStep 3: Balance nitrogen by placing 2 before NH3.\nStep 4: Balance hydrogen and oxygen by placing 2 before H2O.\nStep 5: Check that every element has the same number of atoms on both sides.","steps":["Step 1: Write NH4Cl + Ca(OH)2 → CaCl2 + H2O + NH3.","Step 2: Balance chlorine by placing 2 before NH4Cl.","Step 3: Balance nitrogen by placing 2 before NH3.","Step 4: Balance hydrogen and oxygen by placing 2 before H2O.","Step 5: Check that every element has the same number of atoms on both sides."],"options":[],"conceptId":"chemistry_nonmetals_compounds_ammonia","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q4","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Ammonia"}', 3),
  (4140, 911, 'Explain why ammonia is collected by downward displacement of air and not over water.', 'text', 1, 'Compare the density of ammonia with air and consider its solubility.', '{"why":"Water would dissolve a substantial amount of the gas instead of allowing it to collect.","sol":"Step 1: State whether ammonia is more or less dense than air.\nStep 2: Explain how this allows it to displace air.\nStep 3: State what happens when ammonia comes into contact with water.","steps":["Step 1: State whether ammonia is more or less dense than air.","Step 2: Explain how this allows it to displace air.","Step 3: State what happens when ammonia comes into contact with water."],"options":[],"conceptId":"chemistry_nonmetals_compounds_ammonia","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q5","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Ammonia"}', 4),
  (4141, 911, 'A student holds damp red litmus paper in ammonia gas. Predict the observation and explain it using an ionic equation.', 'text', 1, 'Ammonia reacts reversibly with water.', '{"why":"Hydroxide ions make the moist indicator alkaline. Dry ammonia alone does not produce the same indicator change.","sol":"Step 1: State the colour change.\nStep 2: Explain that ammonia dissolves in moisture.\nStep 3: Write the equilibrium equation showing hydroxide ions.","steps":["Step 1: State the colour change.","Step 2: Explain that ammonia dissolves in moisture.","Step 3: Write the equilibrium equation showing hydroxide ions."],"options":[],"conceptId":"chemistry_nonmetals_compounds_ammonia","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q6","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Ammonia"}', 5),
  (4142, 911, 'Write a balanced equation for the reaction between ammonia and hydrogen chloride gas. State the visible observation.', 'text', 1, 'The product is the ammonium salt containing chloride ions.', '{"why":"Ammonia and hydrogen chloride combine to form solid ammonium chloride particles.","sol":"Step 1: Write the formulae NH3 and HCl.\nStep 2: Identify the salt NH4Cl.\nStep 3: Check that the equation is balanced.\nStep 4: State the observation.","steps":["Step 1: Write the formulae NH3 and HCl.","Step 2: Identify the salt NH4Cl.","Step 3: Check that the equation is balanced.","Step 4: State the observation."],"options":[],"conceptId":"chemistry_nonmetals_compounds_ammonia","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q7","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Ammonia"}', 6),
  (4143, 911, 'Write the balanced equation for the catalytic oxidation of ammonia to nitrogen monoxide and water.', 'text', 1, 'The products are NO and H2O. Balance nitrogen first, then hydrogen and oxygen.', '{"why":"The balanced equation contains four nitrogen atoms, twelve hydrogen atoms and ten oxygen atoms on each side.","sol":"Step 1: Write NH3 + O2 → NO + H2O.\nStep 2: Balance nitrogen by placing 4 before NH3 and 4 before NO.\nStep 3: Balance hydrogen by placing 6 before H2O.\nStep 4: Balance oxygen by placing 5 before O2.","steps":["Step 1: Write NH3 + O2 → NO + H2O.","Step 2: Balance nitrogen by placing 4 before NH3 and 4 before NO.","Step 3: Balance hydrogen by placing 6 before H2O.","Step 4: Balance oxygen by placing 5 before O2."],"options":[],"conceptId":"chemistry_nonmetals_compounds_ammonia","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q8","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Ammonia"}', 7),
  (4144, 911, 'Explain why quicklime is suitable for drying ammonia, while concentrated sulphuric acid is unsuitable.', 'text', 1, 'A suitable drying agent removes moisture without consuming the gas.', '{"why":"A drying agent must remove water without removing or chemically changing the gas being dried.","sol":"Step 1: Identify quicklime as calcium oxide.\nStep 2: Explain the requirement for a drying agent.\nStep 3: Explain how concentrated sulphuric acid reacts with ammonia.","steps":["Step 1: Identify quicklime as calcium oxide.","Step 2: Explain the requirement for a drying agent.","Step 3: Explain how concentrated sulphuric acid reacts with ammonia."],"options":[],"conceptId":"chemistry_nonmetals_compounds_ammonia","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q9","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Ammonia"}', 8),
  (4145, 912, 'State the formula and charge of the ammonium ion and the nitrate ion.', 'text', 1, 'Focus on the core principle of Nitrogen Compounds.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"The ammonium ion is NH₄⁺ and the nitrate ion is NO₃⁻.","steps":["Step 1: Identify key concept: Define the required principles for Nitrogen Compounds.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Ammonium: NH4+, charge +1; nitrate: NO3−, charge −1."],"options":[],"conceptId":"chemistry_nonmetals_compounds_nitrogen_compounds","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q1","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Nitrogen Compounds"}', 0),
  (4146, 912, 'Write the formula of calcium nitrate using the charges of calcium and nitrate ions.', 'text', 1, 'Focus on the core principle of Nitrogen Compounds.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Ca²⁺ requires two NO₃⁻ ions to produce a neutral compound: Ca(NO₃)₂.","steps":["Step 1: Identify key concept: Define the required principles for Nitrogen Compounds.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Ca(NO3)2"],"options":[],"conceptId":"chemistry_nonmetals_compounds_nitrogen_compounds","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q2","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Nitrogen Compounds"}', 1),
  (4147, 912, 'Describe the laboratory test for ammonium ions using aqueous sodium hydroxide.', 'text', 1, 'Focus on the core principle of Nitrogen Compounds.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"NH4+ + OH− → NH3 + H2O.","steps":["Step 1: Identify key concept: Define the required principles for Nitrogen Compounds.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Add aqueous sodium hydroxide and warm gently; ammonia is released and turns damp red litmus paper blue."],"options":[],"conceptId":"chemistry_nonmetals_compounds_nitrogen_compounds","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q3","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Nitrogen Compounds"}', 2),
  (4148, 912, 'Write the formula of calcium nitrate and explain how the ionic charges determine the formula.', 'text', 1, 'Calcium forms Ca2+ and nitrate is NO3−.', '{"why":"The total positive charge of +2 balances the total negative charge of −2.","sol":"Step 1: Write the calcium ion and its charge.\nStep 2: Write the nitrate ion and its charge.\nStep 3: Determine how many nitrate ions are needed to balance one calcium ion.\nStep 4: Use brackets around the nitrate ion because it occurs twice.","steps":["Step 1: Write the calcium ion and its charge.","Step 2: Write the nitrate ion and its charge.","Step 3: Determine how many nitrate ions are needed to balance one calcium ion.","Step 4: Use brackets around the nitrate ion because it occurs twice."],"options":[],"conceptId":"chemistry_nonmetals_compounds_nitrogen_compounds","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q4","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Nitrogen Compounds"}', 3),
  (4149, 912, 'Write a balanced equation for the reaction between nitric acid and sodium hydroxide. Name the salt formed.', 'text', 1, 'An acid reacting with an alkali produces a salt and water.', '{"why":"The hydrogen ion from the acid and hydroxide ion from the alkali form water.","sol":"Step 1: Write HNO3 and NaOH as the reactants.\nStep 2: Combine Na+ with NO3− to form sodium nitrate.\nStep 3: Write water as the other product.\nStep 4: Check the number of atoms on both sides.","steps":["Step 1: Write HNO3 and NaOH as the reactants.","Step 2: Combine Na+ with NO3− to form sodium nitrate.","Step 3: Write water as the other product.","Step 4: Check the number of atoms on both sides."],"options":[],"conceptId":"chemistry_nonmetals_compounds_nitrogen_compounds","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q5","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Nitrogen Compounds"}', 4),
  (4150, 912, 'Explain how a student can test a sample for ammonium ions and state the positive result.', 'text', 1, 'Use aqueous sodium hydroxide and test the gas released.', '{"why":"Hydroxide ions react with ammonium ions to produce ammonia and water.","sol":"Step 1: Add aqueous sodium hydroxide to the sample.\nStep 2: Warm gently using safe laboratory technique.\nStep 3: Test the evolved gas with damp red litmus paper.\nStep 4: State the observation indicating a positive result.","steps":["Step 1: Add aqueous sodium hydroxide to the sample.","Step 2: Warm gently using safe laboratory technique.","Step 3: Test the evolved gas with damp red litmus paper.","Step 4: State the observation indicating a positive result."],"options":[],"conceptId":"chemistry_nonmetals_compounds_nitrogen_compounds","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q6","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Nitrogen Compounds"}', 5),
  (4151, 912, 'Write the balanced equation for the reaction of calcium carbonate with nitric acid.', 'text', 1, 'An acid reacting with a carbonate produces a salt, water and carbon dioxide.', '{"why":"Two nitric acid molecules provide the two nitrate groups required by calcium nitrate.","sol":"Step 1: Identify calcium nitrate as the salt.\nStep 2: Write CaCO3 + HNO3 → Ca(NO3)2 + H2O + CO2.\nStep 3: Place 2 before HNO3 to provide two nitrate groups.\nStep 4: Check calcium, carbon, hydrogen, nitrogen and oxygen atoms.","steps":["Step 1: Identify calcium nitrate as the salt.","Step 2: Write CaCO3 + HNO3 → Ca(NO3)2 + H2O + CO2.","Step 3: Place 2 before HNO3 to provide two nitrate groups.","Step 4: Check calcium, carbon, hydrogen, nitrogen and oxygen atoms."],"options":[],"conceptId":"chemistry_nonmetals_compounds_nitrogen_compounds","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q7","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Nitrogen Compounds"}', 6),
  (4152, 912, 'Nitrogen monoxide reacts with oxygen to form nitrogen dioxide. Write the balanced equation and state the colour of nitrogen dioxide.', 'text', 1, 'Nitrogen dioxide has the formula NO2.', '{"why":"Two nitrogen monoxide molecules react with one oxygen molecule to form two nitrogen dioxide molecules.","sol":"Step 1: Write NO + O2 → NO2.\nStep 2: Place 2 before NO and NO2 to balance nitrogen.\nStep 3: Check oxygen atoms.\nStep 4: State the characteristic colour of the product.","steps":["Step 1: Write NO + O2 → NO2.","Step 2: Place 2 before NO and NO2 to balance nitrogen.","Step 3: Check oxygen atoms.","Step 4: State the characteristic colour of the product."],"options":[],"conceptId":"chemistry_nonmetals_compounds_nitrogen_compounds","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q8","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Nitrogen Compounds"}', 7),
  (4153, 912, 'Distinguish between ammonium nitrate and nitric acid by formula and chemical classification.', 'text', 1, 'One is an ionic salt and the other is an acid.', '{"why":"Ammonium nitrate contains ammonium and nitrate ions, while nitric acid is the acid that forms nitrate salts.","sol":"Step 1: Write the formula of ammonium nitrate.\nStep 2: Write the formula of nitric acid.\nStep 3: Identify the classification of each substance.","steps":["Step 1: Write the formula of ammonium nitrate.","Step 2: Write the formula of nitric acid.","Step 3: Identify the classification of each substance."],"options":[],"conceptId":"chemistry_nonmetals_compounds_nitrogen_compounds","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q9","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Nitrogen Compounds"}', 8),
  (4154, 913, 'Why can most plants not use atmospheric nitrogen gas directly, even though it makes up about 78% of the atmosphere?', 'text', 1, 'Focus on the core principle of Nitrogen Cycle.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Most plants absorb nitrogen mainly as nitrate or ammonium ions rather than directly using N2 gas.","steps":["Step 1: Identify key concept: Define the required principles for Nitrogen Cycle.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Atmospheric nitrogen has a strong triple bond and must first be converted into usable nitrogen compounds."],"options":[],"conceptId":"chemistry_nonmetals_compounds_nitrogen_cycle","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q1","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Nitrogen Cycle"}', 0),
  (4155, 913, 'Name the process in which microorganisms convert ammonium compounds into nitrites and nitrates.', 'text', 1, 'Focus on the core principle of Nitrogen Cycle.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Nitrification is the microbial oxidation of ammonium compounds through nitrites to nitrates.","steps":["Step 1: Identify key concept: Define the required principles for Nitrogen Cycle.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Nitrification."],"options":[],"conceptId":"chemistry_nonmetals_compounds_nitrogen_cycle","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q2","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Nitrogen Cycle"}', 1),
  (4156, 913, 'What is denitrification, and under what soil conditions does it commonly occur?', 'text', 1, 'Focus on the core principle of Nitrogen Cycle.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Denitrifying microorganisms return nitrogen from soil nitrates to the atmosphere.","steps":["Step 1: Identify key concept: Define the required principles for Nitrogen Cycle.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: It is the microbial conversion of nitrates into gaseous nitrogen compounds, commonly in oxygen-poor or waterlogged soils."],"options":[],"conceptId":"chemistry_nonmetals_compounds_nitrogen_cycle","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q3","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Nitrogen Cycle"}', 2),
  (4157, 913, 'Explain why atmospheric nitrogen must undergo fixation before most plants can use it.', 'text', 1, 'Consider the strength of the bond in N2 and the forms of nitrogen absorbed by roots.', '{"why":"Nitrogen fixation makes atmospheric nitrogen available to biological and soil processes.","sol":"Step 1: State the approximate percentage of nitrogen in the atmosphere.\nStep 2: Explain why N2 is relatively unreactive.\nStep 3: Identify the nitrogen compounds that plants commonly absorb.","steps":["Step 1: State the approximate percentage of nitrogen in the atmosphere.","Step 2: Explain why N2 is relatively unreactive.","Step 3: Identify the nitrogen compounds that plants commonly absorb."],"options":[],"conceptId":"chemistry_nonmetals_compounds_nitrogen_cycle","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q4","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Nitrogen Cycle"}', 3),
  (4158, 913, 'Describe two ways in which atmospheric nitrogen is fixed and explain how each produces usable nitrogen compounds.', 'text', 1, 'Consider microorganisms, lightning and industrial manufacture.', '{"why":"These processes convert relatively unreactive atmospheric nitrogen into compounds that can be used in biological or agricultural systems.","sol":"Step 1: Describe biological nitrogen fixation by certain bacteria.\nStep 2: Describe atmospheric fixation by lightning or industrial fixation by the Haber process.\nStep 3: Explain how the resulting compounds enter the nitrogen supply.","steps":["Step 1: Describe biological nitrogen fixation by certain bacteria.","Step 2: Describe atmospheric fixation by lightning or industrial fixation by the Haber process.","Step 3: Explain how the resulting compounds enter the nitrogen supply."],"options":[],"conceptId":"chemistry_nonmetals_compounds_nitrogen_cycle","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q5","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Nitrogen Cycle"}', 4),
  (4159, 913, 'Distinguish between nitrification and denitrification, including the starting substances and products.', 'text', 1, 'One process makes soil nitrates; the other removes nitrate nitrogen from the soil.', '{"why":"Nitrification generally increases nitrate availability, whereas denitrification can return nitrogen to the atmosphere.","sol":"Step 1: State the starting substance in nitrification.\nStep 2: Name its main nitrogen-containing products.\nStep 3: State the starting substance in denitrification.\nStep 4: Name the gaseous products and typical soil conditions.","steps":["Step 1: State the starting substance in nitrification.","Step 2: Name its main nitrogen-containing products.","Step 3: State the starting substance in denitrification.","Step 4: Name the gaseous products and typical soil conditions."],"options":[],"conceptId":"chemistry_nonmetals_compounds_nitrogen_cycle","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q6","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Nitrogen Cycle"}', 5),
  (4160, 913, 'Explain how nitrogen moves from the soil into a plant and then into an animal that eats the plant.', 'text', 1, 'Use the terms assimilation and food chain.', '{"why":"Assimilation incorporates inorganic nitrogen into organic molecules, and feeding transfers nitrogen between organisms.","sol":"Step 1: Explain how the plant obtains nitrogen from the soil.\nStep 2: State how nitrogen is incorporated into plant tissues.\nStep 3: Explain how the animal obtains the nitrogen.","steps":["Step 1: Explain how the plant obtains nitrogen from the soil.","Step 2: State how nitrogen is incorporated into plant tissues.","Step 3: Explain how the animal obtains the nitrogen."],"options":[],"conceptId":"chemistry_nonmetals_compounds_nitrogen_cycle","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q7","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Nitrogen Cycle"}', 6),
  (4161, 913, 'A farmer leaves plant remains in a field. Explain how decomposers return nitrogen from those remains to the soil and name the process.', 'text', 1, 'Think about the breakdown of proteins and other nitrogen-containing organic substances.', '{"why":"Ammonification returns organic nitrogen to the soil, where it can undergo further transformations or be absorbed by plants.","sol":"Step 1: Identify the role of bacteria and fungi in decomposition.\nStep 2: Explain what happens to nitrogen-containing organic compounds.\nStep 3: Name the process and identify the nitrogen-containing products.","steps":["Step 1: Identify the role of bacteria and fungi in decomposition.","Step 2: Explain what happens to nitrogen-containing organic compounds.","Step 3: Name the process and identify the nitrogen-containing products."],"options":[],"conceptId":"chemistry_nonmetals_compounds_nitrogen_cycle","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q8","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Nitrogen Cycle"}', 7),
  (4162, 913, 'Explain how the nitrogen cycle maintains nitrogen availability in an ecosystem and give one reason why denitrification can reduce crop productivity.', 'text', 1, 'Connect recycling, plant proteins and the removal of soil nitrates.', '{"why":"The cycle recycles nitrogen, but denitrification can remove plant-available nitrogen from soil and contribute to lower yields when nitrogen becomes limiting.","sol":"Step 1: Explain how fixation introduces usable nitrogen compounds.\nStep 2: Explain how plants and animals incorporate nitrogen into living matter.\nStep 3: Explain how decomposition returns nitrogen to the soil.\nStep 4: State the effect of denitrification on soil nitrates.","steps":["Step 1: Explain how fixation introduces usable nitrogen compounds.","Step 2: Explain how plants and animals incorporate nitrogen into living matter.","Step 3: Explain how decomposition returns nitrogen to the soil.","Step 4: State the effect of denitrification on soil nitrates."],"options":[],"conceptId":"chemistry_nonmetals_compounds_nitrogen_cycle","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q9","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Nitrogen Cycle"}', 8),
  (4163, 914, 'What is air?', 'text', 1, 'Focus on the core principle of Composition of Air.', '{"why":"Its components retain their individual properties and are not chemically combined.","sol":"Step 1: Air contains several different gases.\nStep 2: These gases are not chemically bonded together.\nStep 3: Therefore, air is a mixture of gases.","steps":["Step 1: Air contains several different gases.","Step 2: These gases are not chemically bonded together.","Step 3: Therefore, air is a mixture of gases."],"options":[],"conceptId":"chemistry_air_water_environment_composition_of_air","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q1","subject":"chemistry","chapter":"air_water_environment","topic":"Composition of Air"}', 0),
  (4164, 914, 'Approximately what volume of oxygen is present in 200 dm³ of dry air?', 'text', 1, 'Focus on the core principle of Composition of Air.', '{"why":"Oxygen occupies approximately 21% of dry air.","sol":"Step 1: Oxygen makes up approximately 21% of dry air.\nStep 2: Calculate 21% of 200 dm³.\nStep 3: 21/100 × 200 = 42 dm³.","steps":["Step 1: Oxygen makes up approximately 21% of dry air.","Step 2: Calculate 21% of 200 dm³.","Step 3: 21/100 × 200 = 42 dm³."],"options":[],"conceptId":"chemistry_air_water_environment_composition_of_air","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q2","subject":"chemistry","chapter":"air_water_environment","topic":"Composition of Air"}', 1),
  (4165, 914, 'Which gas is the largest component of air?', 'text', 1, 'Focus on the core principle of Composition of Air.', '{"why":"Nitrogen makes up about 78% of dry air.","sol":"Step 1: Compare the approximate percentages of the major gases.\nStep 2: Nitrogen is about 78%, while oxygen is about 21%.\nStep 3: Therefore, nitrogen is the largest component.","steps":["Step 1: Compare the approximate percentages of the major gases.","Step 2: Nitrogen is about 78%, while oxygen is about 21%.","Step 3: Therefore, nitrogen is the largest component."],"options":[],"conceptId":"chemistry_air_water_environment_composition_of_air","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q3","subject":"chemistry","chapter":"air_water_environment","topic":"Composition of Air"}', 2),
  (4166, 914, 'A student says that air is a compound because it contains oxygen and nitrogen. Is the student correct?', 'text', 1, 'Think about whether the gases are chemically bonded.', '{"why":"The components of a mixture are not chemically bonded.","sol":"Step 1: Air contains several gases.\nStep 2: The gases are not chemically bonded together.\nStep 3: Therefore, air is a mixture.","steps":["Step 1: Air contains several gases.","Step 2: The gases are not chemically bonded together.","Step 3: Therefore, air is a mixture."],"options":[],"conceptId":"chemistry_air_water_environment_composition_of_air","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q4","subject":"chemistry","chapter":"air_water_environment","topic":"Composition of Air"}', 3),
  (4167, 915, 'State two physical properties of oxygen.', 'text', 1, 'Focus on the core principle of Properties of Oxygen.', '{"why":"These are observable physical properties of oxygen.","sol":"Step 1: Consider how oxygen appears and behaves physically.\nStep 2: Oxygen is colourless.\nStep 3: Oxygen is odourless.","steps":["Step 1: Consider how oxygen appears and behaves physically.","Step 2: Oxygen is colourless.","Step 3: Oxygen is odourless."],"options":[],"conceptId":"chemistry_air_water_environment_properties_of_oxygen","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q1","subject":"chemistry","chapter":"air_water_environment","topic":"Properties of Oxygen"}', 0),
  (4168, 915, 'What happens when a glowing splint is introduced into oxygen?', 'text', 1, 'Focus on the core principle of Properties of Oxygen.', '{"why":"Oxygen supports combustion.","sol":"Step 1: Oxygen supports combustion.\nStep 2: A glowing splint needs oxygen to continue burning.\nStep 3: In oxygen, the splint relights.","steps":["Step 1: Oxygen supports combustion.","Step 2: A glowing splint needs oxygen to continue burning.","Step 3: In oxygen, the splint relights."],"options":[],"conceptId":"chemistry_air_water_environment_properties_of_oxygen","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q2","subject":"chemistry","chapter":"air_water_environment","topic":"Properties of Oxygen"}', 1),
  (4169, 915, 'Write the equation for the complete combustion of carbon in oxygen.', 'text', 1, 'Focus on the core principle of Properties of Oxygen.', '{"why":"One carbon atom reacts with one oxygen molecule to form one carbon dioxide molecule.","sol":"Step 1: The reactants are carbon and oxygen.\nStep 2: Carbon combines with oxygen to form carbon dioxide.\nStep 3: Write the balanced equation: C + O₂ → CO₂.","steps":["Step 1: The reactants are carbon and oxygen.","Step 2: Carbon combines with oxygen to form carbon dioxide.","Step 3: Write the balanced equation: C + O₂ → CO₂."],"options":[],"conceptId":"chemistry_air_water_environment_properties_of_oxygen","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q3","subject":"chemistry","chapter":"air_water_environment","topic":"Properties of Oxygen"}', 2),
  (4170, 915, 'A gas relights a glowing splint. Identify the gas.', 'text', 1, 'Think about the gas that supports combustion.', '{"why":"Oxygen supports combustion and relights a glowing splint.","sol":"Step 1: Relighting a glowing splint is the test for oxygen.\nStep 2: Therefore, the gas is oxygen.","steps":["Step 1: Relighting a glowing splint is the test for oxygen.","Step 2: Therefore, the gas is oxygen."],"options":[],"conceptId":"chemistry_air_water_environment_properties_of_oxygen","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q4","subject":"chemistry","chapter":"air_water_environment","topic":"Properties of Oxygen"}', 3),
  (4171, 916, 'Why is oxygen used in hospitals?', 'text', 1, 'Focus on the core principle of Uses of Oxygen.', '{"why":"Oxygen is required for aerobic respiration.","sol":"Step 1: Human cells require oxygen for aerobic respiration.\nStep 2: Some patients cannot obtain enough oxygen through normal breathing.\nStep 3: Oxygen can therefore be supplied to them.","steps":["Step 1: Human cells require oxygen for aerobic respiration.","Step 2: Some patients cannot obtain enough oxygen through normal breathing.","Step 3: Oxygen can therefore be supplied to them."],"options":[],"conceptId":"chemistry_air_water_environment_uses_of_oxygen","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q1","subject":"chemistry","chapter":"air_water_environment","topic":"Uses of Oxygen"}', 0),
  (4172, 916, 'Why is oxygen useful in welding?', 'text', 1, 'Focus on the core principle of Uses of Oxygen.', '{"why":"The high-temperature flame is useful for cutting and welding metals.","sol":"Step 1: Oxygen supports combustion.\nStep 2: A fuel burning in oxygen can produce a very hot flame.\nStep 3: The hot flame can melt or cut metals.","steps":["Step 1: Oxygen supports combustion.","Step 2: A fuel burning in oxygen can produce a very hot flame.","Step 3: The hot flame can melt or cut metals."],"options":[],"conceptId":"chemistry_air_water_environment_uses_of_oxygen","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q2","subject":"chemistry","chapter":"air_water_environment","topic":"Uses of Oxygen"}', 1),
  (4173, 916, 'State two uses of oxygen.', 'text', 1, 'Focus on the core principle of Uses of Oxygen.', '{"why":"Both uses depend on oxygen''s ability to support respiration or combustion.","sol":"Step 1: Oxygen is required for respiration.\nStep 2: Oxygen also supports combustion.\nStep 3: Therefore, examples include medical respiration and welding.","steps":["Step 1: Oxygen is required for respiration.","Step 2: Oxygen also supports combustion.","Step 3: Therefore, examples include medical respiration and welding."],"options":[],"conceptId":"chemistry_air_water_environment_uses_of_oxygen","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q3","subject":"chemistry","chapter":"air_water_environment","topic":"Uses of Oxygen"}', 2),
  (4174, 916, 'Why would oxygen be useful for a patient having difficulty obtaining enough oxygen from air?', 'text', 1, 'Think about the role of oxygen in respiration.', '{"why":"Cells need oxygen to release energy efficiently through aerobic respiration.","sol":"Step 1: Cells require oxygen for aerobic respiration.\nStep 2: Supplying oxygen increases the amount available for respiration.\nStep 3: Therefore, oxygen can support the patient''s respiratory needs.","steps":["Step 1: Cells require oxygen for aerobic respiration.","Step 2: Supplying oxygen increases the amount available for respiration.","Step 3: Therefore, oxygen can support the patient''s respiratory needs."],"options":[],"conceptId":"chemistry_air_water_environment_uses_of_oxygen","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q4","subject":"chemistry","chapter":"air_water_environment","topic":"Uses of Oxygen"}', 3),
  (4175, 917, 'What is the chemical formula of water?', 'text', 1, 'Focus on the core principle of Properties of Water.', '{"why":"Each water molecule contains two hydrogen atoms and one oxygen atom.","sol":"Step 1: Water contains hydrogen and oxygen.\nStep 2: Two hydrogen atoms combine with one oxygen atom.\nStep 3: Therefore, the formula is H₂O.","steps":["Step 1: Water contains hydrogen and oxygen.","Step 2: Two hydrogen atoms combine with one oxygen atom.","Step 3: Therefore, the formula is H₂O."],"options":[],"conceptId":"chemistry_air_water_environment_properties_of_water","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q1","subject":"chemistry","chapter":"air_water_environment","topic":"Properties of Water"}', 0),
  (4176, 917, 'At what temperature does pure water boil at standard atmospheric pressure?', 'text', 1, 'Focus on the core principle of Properties of Water.', '{"why":"100°C is the standard boiling point of pure water at normal atmospheric pressure.","sol":"Step 1: Recall the standard boiling point of water.\nStep 2: Pure water boils at 100°C at standard atmospheric pressure.","steps":["Step 1: Recall the standard boiling point of water.","Step 2: Pure water boils at 100°C at standard atmospheric pressure."],"options":[],"conceptId":"chemistry_air_water_environment_properties_of_water","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q2","subject":"chemistry","chapter":"air_water_environment","topic":"Properties of Water"}', 1),
  (4177, 917, 'At what temperature does pure water freeze at standard atmospheric pressure?', 'text', 1, 'Focus on the core principle of Properties of Water.', '{"why":"0°C is the standard freezing point of pure water.","sol":"Step 1: Recall the standard freezing point of water.\nStep 2: Pure water freezes at 0°C.","steps":["Step 1: Recall the standard freezing point of water.","Step 2: Pure water freezes at 0°C."],"options":[],"conceptId":"chemistry_air_water_environment_properties_of_water","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q3","subject":"chemistry","chapter":"air_water_environment","topic":"Properties of Water"}', 2),
  (4178, 917, 'A learner says water is a mixture because it contains hydrogen and oxygen. Correct the statement.', 'text', 1, 'Ask whether hydrogen and oxygen are chemically bonded.', '{"why":"Compounds contain elements chemically combined in definite proportions.","sol":"Step 1: Hydrogen and oxygen are chemically bonded in water.\nStep 2: They occur in a fixed ratio of 2:1.\nStep 3: Therefore, water is a compound.","steps":["Step 1: Hydrogen and oxygen are chemically bonded in water.","Step 2: They occur in a fixed ratio of 2:1.","Step 3: Therefore, water is a compound."],"options":[],"conceptId":"chemistry_air_water_environment_properties_of_water","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q4","subject":"chemistry","chapter":"air_water_environment","topic":"Properties of Water"}', 3),
  (4179, 918, 'What is a solvent?', 'text', 1, 'Focus on the core principle of Water as a Solvent.', '{"why":"The solvent provides the medium in which the solute dissolves.","sol":"Step 1: A solution contains a solvent and one or more solutes.\nStep 2: The solvent is the substance that dissolves the solute.\nStep 3: Therefore, a solvent is the substance that dissolves a solute.","steps":["Step 1: A solution contains a solvent and one or more solutes.","Step 2: The solvent is the substance that dissolves the solute.","Step 3: Therefore, a solvent is the substance that dissolves a solute."],"options":[],"conceptId":"chemistry_air_water_environment_water_as_a_solvent","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q1","subject":"chemistry","chapter":"air_water_environment","topic":"Water as a Solvent"}', 0),
  (4180, 918, 'What happens when sodium chloride dissolves in water?', 'text', 1, 'Focus on the core principle of Water as a Solvent.', '{"why":"Water can separate ionic particles and keep them dispersed in solution.","sol":"Step 1: Sodium chloride contains Na⁺ and Cl⁻ ions.\nStep 2: Water separates and surrounds the ions.\nStep 3: The ions become dispersed in the water.","steps":["Step 1: Sodium chloride contains Na⁺ and Cl⁻ ions.","Step 2: Water separates and surrounds the ions.","Step 3: The ions become dispersed in the water."],"options":[],"conceptId":"chemistry_air_water_environment_water_as_a_solvent","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q2","subject":"chemistry","chapter":"air_water_environment","topic":"Water as a Solvent"}', 1),
  (4181, 918, 'Why is water important for transporting dissolved substances in living organisms?', 'text', 1, 'Focus on the core principle of Water as a Solvent.', '{"why":"Dissolved particles can move through aqueous fluids.","sol":"Step 1: Water dissolves many substances.\nStep 2: Dissolved substances can move with the water.\nStep 3: Therefore, water can transport substances through organisms.","steps":["Step 1: Water dissolves many substances.","Step 2: Dissolved substances can move with the water.","Step 3: Therefore, water can transport substances through organisms."],"options":[],"conceptId":"chemistry_air_water_environment_water_as_a_solvent","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q3","subject":"chemistry","chapter":"air_water_environment","topic":"Water as a Solvent"}', 2),
  (4182, 918, 'Salt disappears when added to water. Has the salt necessarily been destroyed?', 'text', 1, 'Think about what dissolving means.', '{"why":"Dissolving is a physical process; the substance remains present in the solution.","sol":"Step 1: Salt particles become separated and dispersed in water.\nStep 2: The particles are still present in the solution.\nStep 3: Therefore, the salt has dissolved rather than been destroyed.","steps":["Step 1: Salt particles become separated and dispersed in water.","Step 2: The particles are still present in the solution.","Step 3: Therefore, the salt has dissolved rather than been destroyed."],"options":[],"conceptId":"chemistry_air_water_environment_water_as_a_solvent","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q4","subject":"chemistry","chapter":"air_water_environment","topic":"Water as a Solvent"}', 3),
  (4183, 919, 'What makes water hard?', 'text', 1, 'Focus on the core principle of Hard Water.', '{"why":"These ions cause the characteristic reactions of hard water.","sol":"Step 1: Hard water contains dissolved mineral ions.\nStep 2: The important ions are mainly calcium and magnesium ions.\nStep 3: Therefore, dissolved calcium and magnesium ions cause hardness.","steps":["Step 1: Hard water contains dissolved mineral ions.","Step 2: The important ions are mainly calcium and magnesium ions.","Step 3: Therefore, dissolved calcium and magnesium ions cause hardness."],"options":[],"conceptId":"chemistry_air_water_environment_hard_water","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q1","subject":"chemistry","chapter":"air_water_environment","topic":"Hard Water"}', 0),
  (4184, 919, 'Why does hard water form scum with soap?', 'text', 1, 'Focus on the core principle of Hard Water.', '{"why":"The insoluble calcium or magnesium soap removes soap from solution.","sol":"Step 1: Hard water contains Ca²⁺ and/or Mg²⁺ ions.\nStep 2: These ions react with soap anions.\nStep 3: An insoluble substance called scum is formed.","steps":["Step 1: Hard water contains Ca²⁺ and/or Mg²⁺ ions.","Step 2: These ions react with soap anions.","Step 3: An insoluble substance called scum is formed."],"options":[],"conceptId":"chemistry_air_water_environment_hard_water","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q2","subject":"chemistry","chapter":"air_water_environment","topic":"Hard Water"}', 1),
  (4185, 919, 'Why is more soap needed when washing with hard water?', 'text', 1, 'Focus on the core principle of Hard Water.', '{"why":"The calcium and magnesium ions reduce the amount of soap available to form lather.","sol":"Step 1: Some soap reacts with calcium and magnesium ions.\nStep 2: This produces scum instead of useful lather.\nStep 3: More soap is therefore needed to produce sufficient lather.","steps":["Step 1: Some soap reacts with calcium and magnesium ions.","Step 2: This produces scum instead of useful lather.","Step 3: More soap is therefore needed to produce sufficient lather."],"options":[],"conceptId":"chemistry_air_water_environment_hard_water","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q3","subject":"chemistry","chapter":"air_water_environment","topic":"Hard Water"}', 2),
  (4186, 919, 'A learner adds soap to hard water and obtains little lather. What is the likely reason?', 'text', 1, 'Think about calcium and magnesium ions.', '{"why":"This is the characteristic behaviour of hard water.","sol":"Step 1: Hard water contains calcium and magnesium ions.\nStep 2: These ions react with soap.\nStep 3: The reaction forms scum and reduces lather.","steps":["Step 1: Hard water contains calcium and magnesium ions.","Step 2: These ions react with soap.","Step 3: The reaction forms scum and reduces lather."],"options":[],"conceptId":"chemistry_air_water_environment_hard_water","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q4","subject":"chemistry","chapter":"air_water_environment","topic":"Hard Water"}', 3),
  (4187, 920, 'What is soft water?', 'text', 1, 'Focus on the core principle of Soft Water.', '{"why":"The low concentration of hardness-causing ions means little soap is lost as scum.","sol":"Step 1: Compare its calcium and magnesium ion content with hard water.\nStep 2: Soft water contains little calcium and magnesium ions.\nStep 3: Therefore, it lathers easily with soap.","steps":["Step 1: Compare its calcium and magnesium ion content with hard water.","Step 2: Soft water contains little calcium and magnesium ions.","Step 3: Therefore, it lathers easily with soap."],"options":[],"conceptId":"chemistry_air_water_environment_soft_water","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q1","subject":"chemistry","chapter":"air_water_environment","topic":"Soft Water"}', 0),
  (4188, 920, 'What happens when soap is added to soft water?', 'text', 1, 'Focus on the core principle of Soft Water.', '{"why":"There are few calcium and magnesium ions to react with the soap.","sol":"Step 1: Soft water has little calcium and magnesium.\nStep 2: Little soap is converted into insoluble scum.\nStep 3: Therefore, soap forms lather easily.","steps":["Step 1: Soft water has little calcium and magnesium.","Step 2: Little soap is converted into insoluble scum.","Step 3: Therefore, soap forms lather easily."],"options":[],"conceptId":"chemistry_air_water_environment_soft_water","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q2","subject":"chemistry","chapter":"air_water_environment","topic":"Soft Water"}', 1),
  (4189, 920, 'Which type of water is generally preferred for washing with soap: hard or soft?', 'text', 1, 'Focus on the core principle of Soft Water.', '{"why":"Soft water allows soap to form lather without significant scum formation.","sol":"Step 1: Washing requires soap to produce lather.\nStep 2: Soft water allows soap to lather readily.\nStep 3: Therefore, soft water is preferred.","steps":["Step 1: Washing requires soap to produce lather.","Step 2: Soft water allows soap to lather readily.","Step 3: Therefore, soft water is preferred."],"options":[],"conceptId":"chemistry_air_water_environment_soft_water","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q3","subject":"chemistry","chapter":"air_water_environment","topic":"Soft Water"}', 2),
  (4190, 920, 'Water produces abundant lather with only a small amount of soap. Is it likely to be hard or soft?', 'text', 1, 'Hard water wastes some soap as scum.', '{"why":"Easy lathering with little soap indicates low hardness.","sol":"Step 1: Hard water reacts with soap and forms scum.\nStep 2: Soft water allows soap to lather easily.\nStep 3: Therefore, the water is likely soft.","steps":["Step 1: Hard water reacts with soap and forms scum.","Step 2: Soft water allows soap to lather easily.","Step 3: Therefore, the water is likely soft."],"options":[],"conceptId":"chemistry_air_water_environment_soft_water","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q4","subject":"chemistry","chapter":"air_water_environment","topic":"Soft Water"}', 3),
  (4191, 921, 'What is the purpose of filtration during water purification?', 'text', 1, 'Focus on the core principle of Water Purification.', '{"why":"The filter traps solid particles while water passes through.","sol":"Step 1: Identify the type of impurity filtration removes.\nStep 2: Filtration separates insoluble solid particles from a liquid.\nStep 3: Therefore, filtration removes suspended insoluble particles.","steps":["Step 1: Identify the type of impurity filtration removes.","Step 2: Filtration separates insoluble solid particles from a liquid.","Step 3: Therefore, filtration removes suspended insoluble particles."],"options":[],"conceptId":"chemistry_air_water_environment_water_purification","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q1","subject":"chemistry","chapter":"air_water_environment","topic":"Water Purification"}', 0),
  (4192, 921, 'Why is water boiled during purification?', 'text', 1, 'Focus on the core principle of Water Purification.', '{"why":"High temperature damages and kills many microorganisms.","sol":"Step 1: Contaminated water may contain harmful microorganisms.\nStep 2: Heating water to boiling temperature kills many microorganisms.\nStep 3: Therefore, boiling helps make water safer.","steps":["Step 1: Contaminated water may contain harmful microorganisms.","Step 2: Heating water to boiling temperature kills many microorganisms.","Step 3: Therefore, boiling helps make water safer."],"options":[],"conceptId":"chemistry_air_water_environment_water_purification","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q2","subject":"chemistry","chapter":"air_water_environment","topic":"Water Purification"}', 1),
  (4193, 921, 'What is the main purpose of chlorination?', 'text', 1, 'Focus on the core principle of Water Purification.', '{"why":"Chlorine is an effective water disinfectant.","sol":"Step 1: Chlorine is added to water in controlled amounts.\nStep 2: Chlorine acts as a disinfectant.\nStep 3: It destroys or inactivates many microorganisms.","steps":["Step 1: Chlorine is added to water in controlled amounts.","Step 2: Chlorine acts as a disinfectant.","Step 3: It destroys or inactivates many microorganisms."],"options":[],"conceptId":"chemistry_air_water_environment_water_purification","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q3","subject":"chemistry","chapter":"air_water_environment","topic":"Water Purification"}', 2),
  (4194, 921, 'A water sample contains mud particles. Which purification process should be used first?', 'text', 1, 'Think about separating insoluble solids from a liquid.', '{"why":"Filtration removes suspended insoluble particles such as mud.","sol":"Step 1: Mud is an insoluble solid.\nStep 2: Filtration separates insoluble solids from liquids.\nStep 3: Therefore, filtration is appropriate.","steps":["Step 1: Mud is an insoluble solid.","Step 2: Filtration separates insoluble solids from liquids.","Step 3: Therefore, filtration is appropriate."],"options":[],"conceptId":"chemistry_air_water_environment_water_purification","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q4","subject":"chemistry","chapter":"air_water_environment","topic":"Water Purification"}', 3),
  (4195, 922, 'How is carbon monoxide formed?', 'text', 1, 'Focus on the core principle of Carbon Monoxide as an Air Pollutant.', '{"why":"Insufficient oxygen prevents complete conversion of carbon to carbon dioxide.","sol":"Step 1: Carbon-containing fuels require oxygen for combustion.\nStep 2: If the oxygen supply is insufficient, combustion may be incomplete.\nStep 3: Incomplete combustion can produce carbon monoxide.","steps":["Step 1: Carbon-containing fuels require oxygen for combustion.","Step 2: If the oxygen supply is insufficient, combustion may be incomplete.","Step 3: Incomplete combustion can produce carbon monoxide."],"options":[],"conceptId":"chemistry_air_water_environment_carbon_monoxide_as_an_air_pollutant","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q1","subject":"chemistry","chapter":"air_water_environment","topic":"Carbon Monoxide as an Air Pollutant"}', 0),
  (4196, 922, 'Write an equation showing formation of carbon monoxide from carbon.', 'text', 1, 'Focus on the core principle of Carbon Monoxide as an Air Pollutant.', '{"why":"Two carbon atoms combine with one oxygen molecule to produce two carbon monoxide molecules.","sol":"Step 1: The reactants are carbon and oxygen.\nStep 2: Limited oxygen produces carbon monoxide.\nStep 3: Balance the equation: 2C + O₂ → 2CO.","steps":["Step 1: The reactants are carbon and oxygen.","Step 2: Limited oxygen produces carbon monoxide.","Step 3: Balance the equation: 2C + O₂ → 2CO."],"options":[],"conceptId":"chemistry_air_water_environment_carbon_monoxide_as_an_air_pollutant","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q2","subject":"chemistry","chapter":"air_water_environment","topic":"Carbon Monoxide as an Air Pollutant"}', 1),
  (4197, 922, 'Why is carbon monoxide poisonous?', 'text', 1, 'Focus on the core principle of Carbon Monoxide as an Air Pollutant.', '{"why":"Reduced oxygen transport can deprive body tissues of oxygen.","sol":"Step 1: Carbon monoxide enters the bloodstream through the lungs.\nStep 2: It binds strongly to haemoglobin.\nStep 3: This reduces the blood''s ability to transport oxygen.","steps":["Step 1: Carbon monoxide enters the bloodstream through the lungs.","Step 2: It binds strongly to haemoglobin.","Step 3: This reduces the blood''s ability to transport oxygen."],"options":[],"conceptId":"chemistry_air_water_environment_carbon_monoxide_as_an_air_pollutant","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q3","subject":"chemistry","chapter":"air_water_environment","topic":"Carbon Monoxide as an Air Pollutant"}', 2),
  (4198, 922, 'Why is burning charcoal inside a poorly ventilated room dangerous?', 'text', 1, 'Consider incomplete combustion and the gas produced.', '{"why":"Poor ventilation limits oxygen and prevents CO from being safely dispersed.","sol":"Step 1: Charcoal contains carbon.\nStep 2: Limited oxygen can cause incomplete combustion.\nStep 3: Carbon monoxide can therefore accumulate in the room.","steps":["Step 1: Charcoal contains carbon.","Step 2: Limited oxygen can cause incomplete combustion.","Step 3: Carbon monoxide can therefore accumulate in the room."],"options":[],"conceptId":"chemistry_air_water_environment_carbon_monoxide_as_an_air_pollutant","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q4","subject":"chemistry","chapter":"air_water_environment","topic":"Carbon Monoxide as an Air Pollutant"}', 3),
  (4199, 923, 'How is sulphur dioxide formed during combustion?', 'text', 1, 'Focus on the core principle of Sulphur Dioxide as an Air Pollutant.', '{"why":"Sulphur combines with oxygen during combustion.","sol":"Step 1: Sulphur-containing material is burned.\nStep 2: Sulphur reacts with oxygen.\nStep 3: Sulphur dioxide is produced.","steps":["Step 1: Sulphur-containing material is burned.","Step 2: Sulphur reacts with oxygen.","Step 3: Sulphur dioxide is produced."],"options":[],"conceptId":"chemistry_air_water_environment_sulphur_dioxide_as_an_air_pollutant","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q1","subject":"chemistry","chapter":"air_water_environment","topic":"Sulphur Dioxide as an Air Pollutant"}', 0),
  (4200, 923, 'Write the equation for combustion of sulphur in oxygen.', 'text', 1, 'Focus on the core principle of Sulphur Dioxide as an Air Pollutant.', '{"why":"One sulphur atom combines with one oxygen molecule to form sulphur dioxide.","sol":"Step 1: Sulphur is the reactant.\nStep 2: Oxygen is the other reactant.\nStep 3: The product is sulphur dioxide.","steps":["Step 1: Sulphur is the reactant.","Step 2: Oxygen is the other reactant.","Step 3: The product is sulphur dioxide."],"options":[],"conceptId":"chemistry_air_water_environment_sulphur_dioxide_as_an_air_pollutant","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q2","subject":"chemistry","chapter":"air_water_environment","topic":"Sulphur Dioxide as an Air Pollutant"}', 1),
  (4201, 923, 'State two environmental effects of sulphur dioxide.', 'text', 1, 'Focus on the core principle of Sulphur Dioxide as an Air Pollutant.', '{"why":"Sulphur dioxide is an acidic air pollutant.","sol":"Step 1: SO₂ can react with atmospheric water.\nStep 2: This contributes to acidic precipitation.\nStep 3: SO₂ can also damage vegetation and materials.","steps":["Step 1: SO₂ can react with atmospheric water.","Step 2: This contributes to acidic precipitation.","Step 3: SO₂ can also damage vegetation and materials."],"options":[],"conceptId":"chemistry_air_water_environment_sulphur_dioxide_as_an_air_pollutant","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q3","subject":"chemistry","chapter":"air_water_environment","topic":"Sulphur Dioxide as an Air Pollutant"}', 2),
  (4202, 923, 'A factory burns sulphur-containing fuel and releases SO₂. Name one environmental problem that may result.', 'text', 1, 'Think about acidic precipitation.', '{"why":"Sulphur dioxide is an important contributor to acid rain.","sol":"Step 1: SO₂ enters the atmosphere.\nStep 2: It can participate in reactions that produce acidic substances.\nStep 3: These contribute to acid rain.","steps":["Step 1: SO₂ enters the atmosphere.","Step 2: It can participate in reactions that produce acidic substances.","Step 3: These contribute to acid rain."],"options":[],"conceptId":"chemistry_air_water_environment_sulphur_dioxide_as_an_air_pollutant","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q4","subject":"chemistry","chapter":"air_water_environment","topic":"Sulphur Dioxide as an Air Pollutant"}', 3),
  (4203, 924, 'What are nitrogen oxides?', 'text', 1, 'Focus on the core principle of Nitrogen Oxides as Air Pollutants.', '{"why":"NO and NO₂ are common nitrogen oxides produced during high-temperature combustion.","sol":"Step 1: Nitrogen oxides are compounds containing nitrogen and oxygen.\nStep 2: Common examples include NO and NO₂.\nStep 3: These gases are collectively referred to as NOₓ.","steps":["Step 1: Nitrogen oxides are compounds containing nitrogen and oxygen.","Step 2: Common examples include NO and NO₂.","Step 3: These gases are collectively referred to as NOₓ."],"options":[],"conceptId":"chemistry_air_water_environment_nitrogen_oxides_as_air_pollutants","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q1","subject":"chemistry","chapter":"air_water_environment","topic":"Nitrogen Oxides as Air Pollutants"}', 0),
  (4204, 924, 'Where are nitrogen oxides commonly produced?', 'text', 1, 'Focus on the core principle of Nitrogen Oxides as Air Pollutants.', '{"why":"High temperatures promote reactions between nitrogen and oxygen.","sol":"Step 1: Nitrogen and oxygen can react at very high temperatures.\nStep 2: Vehicle engines reach high temperatures during combustion.\nStep 3: Industrial combustion can also produce these gases.","steps":["Step 1: Nitrogen and oxygen can react at very high temperatures.","Step 2: Vehicle engines reach high temperatures during combustion.","Step 3: Industrial combustion can also produce these gases."],"options":[],"conceptId":"chemistry_air_water_environment_nitrogen_oxides_as_air_pollutants","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q2","subject":"chemistry","chapter":"air_water_environment","topic":"Nitrogen Oxides as Air Pollutants"}', 1),
  (4205, 924, 'State one environmental effect of nitrogen oxides.', 'text', 1, 'Focus on the core principle of Nitrogen Oxides as Air Pollutants.', '{"why":"Nitrogen oxides can form acidic substances in the atmosphere.","sol":"Step 1: Nitrogen oxides can undergo atmospheric reactions.\nStep 2: Some of the products contribute to acidic precipitation.\nStep 3: Therefore, nitrogen oxides contribute to acid rain.","steps":["Step 1: Nitrogen oxides can undergo atmospheric reactions.","Step 2: Some of the products contribute to acidic precipitation.","Step 3: Therefore, nitrogen oxides contribute to acid rain."],"options":[],"conceptId":"chemistry_air_water_environment_nitrogen_oxides_as_air_pollutants","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q3","subject":"chemistry","chapter":"air_water_environment","topic":"Nitrogen Oxides as Air Pollutants"}', 2),
  (4206, 924, 'Why are vehicle engines a source of nitrogen oxides?', 'text', 1, 'Think about the temperature inside an engine.', '{"why":"High-temperature combustion promotes NOₓ formation.","sol":"Step 1: Engines burn fuel at high temperatures.\nStep 2: At high temperatures, nitrogen and oxygen from air can react.\nStep 3: Nitrogen oxides can therefore form.","steps":["Step 1: Engines burn fuel at high temperatures.","Step 2: At high temperatures, nitrogen and oxygen from air can react.","Step 3: Nitrogen oxides can therefore form."],"options":[],"conceptId":"chemistry_air_water_environment_nitrogen_oxides_as_air_pollutants","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q4","subject":"chemistry","chapter":"air_water_environment","topic":"Nitrogen Oxides as Air Pollutants"}', 3),
  (4207, 925, 'What is particulate matter?', 'text', 1, 'Focus on the core principle of Particulate Matter.', '{"why":"Particulate pollution consists of suspended particles rather than gaseous pollutants.","sol":"Step 1: Particulate matter is not a single gas.\nStep 2: It consists of tiny solid particles or liquid droplets.\nStep 3: These particles remain suspended in air.","steps":["Step 1: Particulate matter is not a single gas.","Step 2: It consists of tiny solid particles or liquid droplets.","Step 3: These particles remain suspended in air."],"options":[],"conceptId":"chemistry_air_water_environment_particulate_matter","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q1","subject":"chemistry","chapter":"air_water_environment","topic":"Particulate Matter"}', 0),
  (4208, 925, 'Give two sources of particulate matter.', 'text', 1, 'Focus on the core principle of Particulate Matter.', '{"why":"Combustion processes can release smoke and fine particles.","sol":"Step 1: Consider processes that release tiny particles into air.\nStep 2: Vehicle exhaust can release particles.\nStep 3: Burning biomass or waste can also release particles.","steps":["Step 1: Consider processes that release tiny particles into air.","Step 2: Vehicle exhaust can release particles.","Step 3: Burning biomass or waste can also release particles."],"options":[],"conceptId":"chemistry_air_water_environment_particulate_matter","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q2","subject":"chemistry","chapter":"air_water_environment","topic":"Particulate Matter"}', 1),
  (4209, 925, 'Why can fine particulate matter be harmful to humans?', 'text', 1, 'Focus on the core principle of Particulate Matter.', '{"why":"Small particles can penetrate further into the lungs.","sol":"Step 1: Very small particles can be inhaled.\nStep 2: Some can travel deep into the respiratory system.\nStep 3: This can damage or irritate respiratory tissues.","steps":["Step 1: Very small particles can be inhaled.","Step 2: Some can travel deep into the respiratory system.","Step 3: This can damage or irritate respiratory tissues."],"options":[],"conceptId":"chemistry_air_water_environment_particulate_matter","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q3","subject":"chemistry","chapter":"air_water_environment","topic":"Particulate Matter"}', 2),
  (4210, 925, 'A town experiences heavy smoke from burning waste. Which type of air pollutant is likely to increase?', 'text', 1, 'Think about the tiny particles found in smoke.', '{"why":"Smoke from combustion can contain many fine suspended particles.","sol":"Step 1: Burning waste produces smoke.\nStep 2: Smoke contains suspended particles.\nStep 3: These particles contribute to particulate matter pollution.","steps":["Step 1: Burning waste produces smoke.","Step 2: Smoke contains suspended particles.","Step 3: These particles contribute to particulate matter pollution."],"options":[],"conceptId":"chemistry_air_water_environment_particulate_matter","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q4","subject":"chemistry","chapter":"air_water_environment","topic":"Particulate Matter"}', 3),
  (4211, 926, 'What is acid rain?', 'text', 1, 'Focus on the core principle of Acid Rain.', '{"why":"SO₂ and NOₓ contribute to the formation of acids in atmospheric moisture.","sol":"Step 1: Certain gases enter the atmosphere.\nStep 2: Sulphur dioxide and nitrogen oxides form acidic substances through atmospheric reactions.\nStep 3: These acidic substances dissolve in precipitation.","steps":["Step 1: Certain gases enter the atmosphere.","Step 2: Sulphur dioxide and nitrogen oxides form acidic substances through atmospheric reactions.","Step 3: These acidic substances dissolve in precipitation."],"options":[],"conceptId":"chemistry_air_water_environment_acid_rain","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q1","subject":"chemistry","chapter":"air_water_environment","topic":"Acid Rain"}', 0),
  (4212, 926, 'Name two gases that contribute to acid rain.', 'text', 1, 'Focus on the core principle of Acid Rain.', '{"why":"Both pollutants can form acidic substances in the atmosphere.","sol":"Step 1: Identify the major acidic air pollutants involved.\nStep 2: Sulphur dioxide contributes to acid formation.\nStep 3: Nitrogen oxides also contribute.","steps":["Step 1: Identify the major acidic air pollutants involved.","Step 2: Sulphur dioxide contributes to acid formation.","Step 3: Nitrogen oxides also contribute."],"options":[],"conceptId":"chemistry_air_water_environment_acid_rain","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q2","subject":"chemistry","chapter":"air_water_environment","topic":"Acid Rain"}', 1),
  (4213, 926, 'How can acid rain damage limestone buildings?', 'text', 1, 'Focus on the core principle of Acid Rain.', '{"why":"Acids react with carbonates, causing limestone to wear away.","sol":"Step 1: Limestone contains calcium carbonate.\nStep 2: Acids react with carbonates.\nStep 3: The reaction can dissolve or erode the limestone.","steps":["Step 1: Limestone contains calcium carbonate.","Step 2: Acids react with carbonates.","Step 3: The reaction can dissolve or erode the limestone."],"options":[],"conceptId":"chemistry_air_water_environment_acid_rain","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q3","subject":"chemistry","chapter":"air_water_environment","topic":"Acid Rain"}', 2),
  (4214, 926, 'A power station reduces its SO₂ emissions. How could this help the environment?', 'text', 1, 'Think about one major consequence of SO₂ pollution.', '{"why":"Sulphur dioxide is a major contributor to acid rain.","sol":"Step 1: SO₂ contributes to acid rain.\nStep 2: Reducing SO₂ reduces the amount available for atmospheric acid formation.\nStep 3: Therefore, acid rain can be reduced.","steps":["Step 1: SO₂ contributes to acid rain.","Step 2: Reducing SO₂ reduces the amount available for atmospheric acid formation.","Step 3: Therefore, acid rain can be reduced."],"options":[],"conceptId":"chemistry_air_water_environment_acid_rain","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q4","subject":"chemistry","chapter":"air_water_environment","topic":"Acid Rain"}', 3),
  (4215, 927, 'What is the greenhouse effect?', 'text', 1, 'Focus on the core principle of Greenhouse Effect.', '{"why":"Greenhouse gases reduce the rate at which some heat escapes to space.","sol":"Step 1: The Earth''s surface absorbs energy from the Sun.\nStep 2: The surface emits infrared radiation.\nStep 3: Greenhouse gases absorb and re-emit some of this radiation.\nStep 4: This contributes to warming of the lower atmosphere and surface.","steps":["Step 1: The Earth''s surface absorbs energy from the Sun.","Step 2: The surface emits infrared radiation.","Step 3: Greenhouse gases absorb and re-emit some of this radiation.","Step 4: This contributes to warming of the lower atmosphere and surface."],"options":[],"conceptId":"chemistry_air_water_environment_greenhouse_effect","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q1","subject":"chemistry","chapter":"air_water_environment","topic":"Greenhouse Effect"}', 0),
  (4216, 927, 'Name two greenhouse gases.', 'text', 1, 'Focus on the core principle of Greenhouse Effect.', '{"why":"Both gases contribute to the greenhouse effect.","sol":"Step 1: Recall gases that absorb infrared radiation.\nStep 2: Carbon dioxide is a greenhouse gas.\nStep 3: Methane is also a greenhouse gas.","steps":["Step 1: Recall gases that absorb infrared radiation.","Step 2: Carbon dioxide is a greenhouse gas.","Step 3: Methane is also a greenhouse gas."],"options":[],"conceptId":"chemistry_air_water_environment_greenhouse_effect","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q2","subject":"chemistry","chapter":"air_water_environment","topic":"Greenhouse Effect"}', 1),
  (4217, 927, 'Why can burning fossil fuels increase the greenhouse effect?', 'text', 1, 'Focus on the core principle of Greenhouse Effect.', '{"why":"Carbon dioxide absorbs infrared radiation and contributes to the greenhouse effect.","sol":"Step 1: Fossil fuels contain carbon.\nStep 2: Complete combustion produces carbon dioxide.\nStep 3: Increased atmospheric CO₂ strengthens the greenhouse effect.","steps":["Step 1: Fossil fuels contain carbon.","Step 2: Complete combustion produces carbon dioxide.","Step 3: Increased atmospheric CO₂ strengthens the greenhouse effect."],"options":[],"conceptId":"chemistry_air_water_environment_greenhouse_effect","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q3","subject":"chemistry","chapter":"air_water_environment","topic":"Greenhouse Effect"}', 2),
  (4218, 927, 'A country increases its use of coal for electricity generation. What greenhouse gas is likely to increase significantly?', 'text', 1, 'Think about the product of complete combustion of carbon.', '{"why":"Combustion of carbon-containing fossil fuels releases carbon dioxide.","sol":"Step 1: Coal contains carbon.\nStep 2: Carbon burns in oxygen to produce carbon dioxide.\nStep 3: Therefore, burning more coal can increase CO₂ emissions.","steps":["Step 1: Coal contains carbon.","Step 2: Carbon burns in oxygen to produce carbon dioxide.","Step 3: Therefore, burning more coal can increase CO₂ emissions."],"options":[],"conceptId":"chemistry_air_water_environment_greenhouse_effect","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q4","subject":"chemistry","chapter":"air_water_environment","topic":"Greenhouse Effect"}', 3),
  (4219, 928, 'State two methods of reducing air pollution.', 'text', 1, 'Focus on the core principle of Pollution Control.', '{"why":"Both measures reduce the amount of pollutants released into the air.","sol":"Step 1: Air pollution is reduced by preventing pollutants from entering the atmosphere.\nStep 2: Cleaner fuels can reduce some emissions.\nStep 3: Reducing open burning can reduce smoke and particulate matter.","steps":["Step 1: Air pollution is reduced by preventing pollutants from entering the atmosphere.","Step 2: Cleaner fuels can reduce some emissions.","Step 3: Reducing open burning can reduce smoke and particulate matter."],"options":[],"conceptId":"chemistry_air_water_environment_pollution_control","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q1","subject":"chemistry","chapter":"air_water_environment","topic":"Pollution Control"}', 0),
  (4220, 928, 'Why should sewage be treated before being discharged into rivers?', 'text', 1, 'Focus on the core principle of Pollution Control.', '{"why":"Untreated sewage can cause water pollution and harm aquatic ecosystems and human health.","sol":"Step 1: Untreated sewage can contain microorganisms and organic waste.\nStep 2: Discharging it directly can contaminate water.\nStep 3: Treatment removes or reduces harmful contaminants before discharge.","steps":["Step 1: Untreated sewage can contain microorganisms and organic waste.","Step 2: Discharging it directly can contaminate water.","Step 3: Treatment removes or reduces harmful contaminants before discharge."],"options":[],"conceptId":"chemistry_air_water_environment_pollution_control","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q2","subject":"chemistry","chapter":"air_water_environment","topic":"Pollution Control"}', 1),
  (4221, 928, 'What does sustainable use of resources mean?', 'text', 1, 'Focus on the core principle of Pollution Control.', '{"why":"Sustainability balances present use with long-term environmental protection.","sol":"Step 1: Natural resources are limited or can be damaged by excessive use.\nStep 2: Resources should therefore be used efficiently.\nStep 3: The aim is to meet present needs while protecting resources for the future.","steps":["Step 1: Natural resources are limited or can be damaged by excessive use.","Step 2: Resources should therefore be used efficiently.","Step 3: The aim is to meet present needs while protecting resources for the future."],"options":[],"conceptId":"chemistry_air_water_environment_pollution_control","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q3","subject":"chemistry","chapter":"air_water_environment","topic":"Pollution Control"}', 2),
  (4222, 928, 'A factory releases untreated wastewater directly into a river. Give one action that could reduce the pollution.', 'text', 1, 'Think about what should happen to wastewater before discharge.', '{"why":"Wastewater treatment reduces pollutants entering water bodies.","sol":"Step 1: The wastewater contains pollutants.\nStep 2: It should be treated before entering the river.\nStep 3: Treatment removes or reduces harmful substances.","steps":["Step 1: The wastewater contains pollutants.","Step 2: It should be treated before entering the river.","Step 3: Treatment removes or reduces harmful substances."],"options":[],"conceptId":"chemistry_air_water_environment_pollution_control","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q4","subject":"chemistry","chapter":"air_water_environment","topic":"Pollution Control"}', 3),
  (4223, 929, 'Which ion is being tested for when ammonia gas is produced after warming a sample with sodium hydroxide?', 'text', 1, 'Focus on the core principle of Test for Ammonium Ions.', '{"why":"Ammonium ions react with hydroxide ions to release ammonia gas.","sol":"Step 1: Ammonia is NH₃.\nStep 2: Ammonia can be produced from ammonium ions when an alkali is added.\nStep 3: Therefore, the ion being tested is NH₄⁺.","steps":["Step 1: Ammonia is NH₃.","Step 2: Ammonia can be produced from ammonium ions when an alkali is added.","Step 3: Therefore, the ion being tested is NH₄⁺."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_ammonium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Ammonium Ions"}', 0),
  (4224, 929, 'What happens to damp red litmus paper in the presence of ammonia gas?', 'text', 1, 'Focus on the core principle of Test for Ammonium Ions.', '{"why":"Ammonia produces an alkaline solution in water.","sol":"Step 1: Ammonia dissolves in the moisture on the litmus paper.\nStep 2: The resulting solution is alkaline.\nStep 3: Alkaline substances turn red litmus blue.","steps":["Step 1: Ammonia dissolves in the moisture on the litmus paper.","Step 2: The resulting solution is alkaline.","Step 3: Alkaline substances turn red litmus blue."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_ammonium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Ammonium Ions"}', 1),
  (4225, 929, 'Write the ionic equation for the reaction between ammonium ions and hydroxide ions.', 'text', 1, 'Focus on the core principle of Test for Ammonium Ions.', '{"why":"The reaction releases ammonia gas from ammonium ions.","sol":"Step 1: The reactants are NH₄⁺ and OH⁻.\nStep 2: Ammonium ions react with hydroxide ions.\nStep 3: The products are ammonia and water.","steps":["Step 1: The reactants are NH₄⁺ and OH⁻.","Step 2: Ammonium ions react with hydroxide ions.","Step 3: The products are ammonia and water."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_ammonium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Ammonium Ions"}', 2),
  (4226, 929, 'A sample gives off ammonia when warmed with sodium hydroxide. What ion is present?', 'text', 1, 'The gas is produced from ammonium ions.', '{"why":"The sodium hydroxide test is a standard test for ammonium ions.","sol":"Step 1: Identify the gas as ammonia.\nStep 2: Ammonia is released from ammonium ions in this test.\nStep 3: Therefore, the sample contains NH₄⁺.","steps":["Step 1: Identify the gas as ammonia.","Step 2: Ammonia is released from ammonium ions in this test.","Step 3: Therefore, the sample contains NH₄⁺."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_ammonium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Ammonium Ions"}', 3),
  (4227, 930, 'What colour precipitate is produced when sodium hydroxide is added to a solution containing Cu²⁺ ions?', 'text', 1, 'Focus on the core principle of Test for Copper(II) Ions.', '{"why":"Cu²⁺ forms blue copper(II) hydroxide with hydroxide ions.","sol":"Step 1: Cu²⁺ reacts with OH⁻ ions.\nStep 2: Copper(II) hydroxide is formed.\nStep 3: Copper(II) hydroxide is blue.","steps":["Step 1: Cu²⁺ reacts with OH⁻ ions.","Step 2: Copper(II) hydroxide is formed.","Step 3: Copper(II) hydroxide is blue."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_copper_ii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Copper(II) Ions"}', 0),
  (4228, 930, 'Write the ionic equation for the test for Cu²⁺ ions.', 'text', 1, 'Focus on the core principle of Test for Copper(II) Ions.', '{"why":"The charges and atoms are balanced in the precipitation reaction.","sol":"Step 1: Identify the ions reacting: Cu²⁺ and OH⁻.\nStep 2: Two hydroxide ions are required to balance the +2 charge.\nStep 3: The solid product is Cu(OH)₂.","steps":["Step 1: Identify the ions reacting: Cu²⁺ and OH⁻.","Step 2: Two hydroxide ions are required to balance the +2 charge.","Step 3: The solid product is Cu(OH)₂."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_copper_ii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Copper(II) Ions"}', 1),
  (4229, 930, 'What observation indicates the presence of copper(II) ions?', 'text', 1, 'Focus on the core principle of Test for Copper(II) Ions.', '{"why":"Copper(II) hydroxide has a characteristic blue colour.","sol":"Step 1: Add sodium hydroxide solution.\nStep 2: Observe whether a precipitate forms.\nStep 3: A blue precipitate indicates Cu²⁺.","steps":["Step 1: Add sodium hydroxide solution.","Step 2: Observe whether a precipitate forms.","Step 3: A blue precipitate indicates Cu²⁺."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_copper_ii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Copper(II) Ions"}', 2),
  (4230, 930, 'A colourless solution produces a blue precipitate when sodium hydroxide is added. Which common ion could be present?', 'text', 1, 'Think of the metal ion that forms blue copper(II) hydroxide.', '{"why":"Copper(II) hydroxide is a blue precipitate.","sol":"Step 1: A blue precipitate is observed.\nStep 2: Cu²⁺ reacts with OH⁻ to form blue Cu(OH)₂.\nStep 3: Therefore, Cu²⁺ may be present.","steps":["Step 1: A blue precipitate is observed.","Step 2: Cu²⁺ reacts with OH⁻ to form blue Cu(OH)₂.","Step 3: Therefore, Cu²⁺ may be present."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_copper_ii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Copper(II) Ions"}', 3),
  (4231, 931, 'What colour precipitate is formed when Fe²⁺ ions react with sodium hydroxide?', 'text', 1, 'Focus on the core principle of Test for Iron(II) Ions.', '{"why":"Fe(OH)₂ is characteristically green.","sol":"Step 1: Fe²⁺ reacts with OH⁻.\nStep 2: Iron(II) hydroxide forms.\nStep 3: Iron(II) hydroxide is green.","steps":["Step 1: Fe²⁺ reacts with OH⁻.","Step 2: Iron(II) hydroxide forms.","Step 3: Iron(II) hydroxide is green."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_iron_ii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Iron(II) Ions"}', 0),
  (4232, 931, 'Write the ionic equation for the formation of iron(II) hydroxide.', 'text', 1, 'Focus on the core principle of Test for Iron(II) Ions.', '{"why":"The reaction forms an insoluble hydroxide precipitate.","sol":"Step 1: Start with Fe²⁺.\nStep 2: Two OH⁻ ions are needed to balance the charge.\nStep 3: The insoluble product is Fe(OH)₂.","steps":["Step 1: Start with Fe²⁺.","Step 2: Two OH⁻ ions are needed to balance the charge.","Step 3: The insoluble product is Fe(OH)₂."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_iron_ii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Iron(II) Ions"}', 1),
  (4233, 931, 'How can Fe²⁺ ions be distinguished from Cu²⁺ ions using sodium hydroxide?', 'text', 1, 'Focus on the core principle of Test for Iron(II) Ions.', '{"why":"The hydroxides have different characteristic colours.","sol":"Step 1: Add sodium hydroxide to each sample.\nStep 2: Fe²⁺ produces a green precipitate.\nStep 3: Cu²⁺ produces a blue precipitate.","steps":["Step 1: Add sodium hydroxide to each sample.","Step 2: Fe²⁺ produces a green precipitate.","Step 3: Cu²⁺ produces a blue precipitate."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_iron_ii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Iron(II) Ions"}', 2),
  (4234, 931, 'A sample produces a green precipitate with sodium hydroxide. Which ion could be responsible?', 'text', 1, 'Compare the characteristic hydroxide colours.', '{"why":"Fe²⁺ produces green Fe(OH)₂ with hydroxide ions.","sol":"Step 1: Identify the precipitate colour as green.\nStep 2: Iron(II) hydroxide is green.\nStep 3: Therefore, Fe²⁺ may be present.","steps":["Step 1: Identify the precipitate colour as green.","Step 2: Iron(II) hydroxide is green.","Step 3: Therefore, Fe²⁺ may be present."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_iron_ii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Iron(II) Ions"}', 3),
  (4235, 932, 'What colour precipitate is formed when Fe³⁺ reacts with sodium hydroxide?', 'text', 1, 'Focus on the core principle of Test for Iron(III) Ions.', '{"why":"Iron(III) hydroxide has a characteristic red-brown colour.","sol":"Step 1: Fe³⁺ reacts with OH⁻ ions.\nStep 2: Iron(III) hydroxide forms.\nStep 3: The precipitate is red-brown.","steps":["Step 1: Fe³⁺ reacts with OH⁻ ions.","Step 2: Iron(III) hydroxide forms.","Step 3: The precipitate is red-brown."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_iron_iii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Iron(III) Ions"}', 0),
  (4236, 932, 'Write the ionic equation for the reaction of Fe³⁺ with hydroxide ions.', 'text', 1, 'Focus on the core principle of Test for Iron(III) Ions.', '{"why":"Three hydroxide ions balance the +3 charge on Fe³⁺.","sol":"Step 1: The iron ion has a +3 charge.\nStep 2: Three OH⁻ ions are needed to balance the charge.\nStep 3: Iron(III) hydroxide forms as a precipitate.","steps":["Step 1: The iron ion has a +3 charge.","Step 2: Three OH⁻ ions are needed to balance the charge.","Step 3: Iron(III) hydroxide forms as a precipitate."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_iron_iii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Iron(III) Ions"}', 1),
  (4237, 932, 'How can Fe³⁺ be distinguished from Fe²⁺ using sodium hydroxide?', 'text', 1, 'Focus on the core principle of Test for Iron(III) Ions.', '{"why":"The two iron hydroxides have different characteristic colours.","sol":"Step 1: Add sodium hydroxide to both samples.\nStep 2: Fe²⁺ gives a green precipitate.\nStep 3: Fe³⁺ gives a red-brown precipitate.","steps":["Step 1: Add sodium hydroxide to both samples.","Step 2: Fe²⁺ gives a green precipitate.","Step 3: Fe³⁺ gives a red-brown precipitate."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_iron_iii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Iron(III) Ions"}', 2),
  (4238, 932, 'A solution gives a red-brown precipitate when sodium hydroxide is added. Which ion is indicated?', 'text', 1, 'Think about the colour of iron(III) hydroxide.', '{"why":"Fe³⁺ forms red-brown Fe(OH)₃.","sol":"Step 1: Identify the precipitate as red-brown.\nStep 2: Fe(OH)₃ is red-brown.\nStep 3: Therefore, Fe³⁺ is indicated.","steps":["Step 1: Identify the precipitate as red-brown.","Step 2: Fe(OH)₃ is red-brown.","Step 3: Therefore, Fe³⁺ is indicated."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_iron_iii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Iron(III) Ions"}', 3),
  (4239, 933, 'What reagent is used to test for chloride ions after acidification?', 'text', 1, 'Focus on the core principle of Test for Chloride Ions.', '{"why":"Silver ions react with chloride ions to form insoluble silver chloride.","sol":"Step 1: Acidify the sample with dilute nitric acid.\nStep 2: Add aqueous silver nitrate.\nStep 3: Observe whether a precipitate forms.","steps":["Step 1: Acidify the sample with dilute nitric acid.","Step 2: Add aqueous silver nitrate.","Step 3: Observe whether a precipitate forms."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_chloride_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Chloride Ions"}', 0),
  (4240, 933, 'What colour precipitate indicates chloride ions?', 'text', 1, 'Focus on the core principle of Test for Chloride Ions.', '{"why":"AgCl is a white insoluble precipitate.","sol":"Step 1: Silver ions react with chloride ions.\nStep 2: Silver chloride is produced.\nStep 3: Silver chloride is white.","steps":["Step 1: Silver ions react with chloride ions.","Step 2: Silver chloride is produced.","Step 3: Silver chloride is white."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_chloride_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Chloride Ions"}', 1),
  (4241, 933, 'Write the ionic equation for the chloride ion test.', 'text', 1, 'Focus on the core principle of Test for Chloride Ions.', '{"why":"Silver chloride precipitates from solution.","sol":"Step 1: Identify the reacting ions: Ag⁺ and Cl⁻.\nStep 2: Combine them in a 1:1 ratio.\nStep 3: Write the insoluble product.","steps":["Step 1: Identify the reacting ions: Ag⁺ and Cl⁻.","Step 2: Combine them in a 1:1 ratio.","Step 3: Write the insoluble product."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_chloride_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Chloride Ions"}', 2),
  (4242, 933, 'A sample produces a white precipitate when acidified and treated with silver nitrate. Which ion is indicated?', 'text', 1, 'Silver chloride is white.', '{"why":"Ag⁺ + Cl⁻ → AgCl(s), a white precipitate.","sol":"Step 1: Silver nitrate supplies Ag⁺ ions.\nStep 2: A white precipitate of AgCl forms if Cl⁻ is present.\nStep 3: Therefore, chloride ions are indicated.","steps":["Step 1: Silver nitrate supplies Ag⁺ ions.","Step 2: A white precipitate of AgCl forms if Cl⁻ is present.","Step 3: Therefore, chloride ions are indicated."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_chloride_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Chloride Ions"}', 3),
  (4243, 934, 'What ion is being tested for when barium ions produce a white precipitate?', 'text', 1, 'Focus on the core principle of Test for Sulphate Ions.', '{"why":"Barium sulphate is an insoluble white solid.","sol":"Step 1: Barium ions react with sulphate ions.\nStep 2: Insoluble barium sulphate forms.\nStep 3: Therefore, the ion being tested is SO₄²⁻.","steps":["Step 1: Barium ions react with sulphate ions.","Step 2: Insoluble barium sulphate forms.","Step 3: Therefore, the ion being tested is SO₄²⁻."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_sulphate_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Sulphate Ions"}', 0),
  (4244, 934, 'Write the ionic equation for the sulphate ion test.', 'text', 1, 'Focus on the core principle of Test for Sulphate Ions.', '{"why":"Barium sulphate forms a white precipitate.","sol":"Step 1: Identify Ba²⁺ and SO₄²⁻.\nStep 2: Their charges balance in a 1:1 ratio.\nStep 3: The product is insoluble BaSO₄.","steps":["Step 1: Identify Ba²⁺ and SO₄²⁻.","Step 2: Their charges balance in a 1:1 ratio.","Step 3: The product is insoluble BaSO₄."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_sulphate_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Sulphate Ions"}', 1),
  (4245, 934, 'What observation confirms the presence of sulphate ions?', 'text', 1, 'Focus on the core principle of Test for Sulphate Ions.', '{"why":"BaSO₄ is insoluble and appears as a white precipitate.","sol":"Step 1: Acidify the sample.\nStep 2: Add a soluble barium salt.\nStep 3: Look for a white precipitate.","steps":["Step 1: Acidify the sample.","Step 2: Add a soluble barium salt.","Step 3: Look for a white precipitate."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_sulphate_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Sulphate Ions"}', 2),
  (4246, 934, 'A sample gives a white precipitate after acidification and addition of barium ions. Which ion may be present?', 'text', 1, 'Think of the insoluble barium salt used in qualitative analysis.', '{"why":"Ba²⁺ + SO₄²⁻ → BaSO₄(s).","sol":"Step 1: Barium ions form an insoluble salt with sulphate ions.\nStep 2: Barium sulphate is white.\nStep 3: Therefore, SO₄²⁻ may be present.","steps":["Step 1: Barium ions form an insoluble salt with sulphate ions.","Step 2: Barium sulphate is white.","Step 3: Therefore, SO₄²⁻ may be present."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_sulphate_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Sulphate Ions"}', 3),
  (4247, 935, 'What gas is produced when a carbonate reacts with a dilute acid?', 'text', 1, 'Focus on the core principle of Test for Carbonate Ions.', '{"why":"Carbonate ions release CO₂ when treated with an acid.","sol":"Step 1: Carbonates contain CO₃²⁻ ions.\nStep 2: Carbonate ions react with H⁺ ions.\nStep 3: Carbon dioxide gas and water are formed.","steps":["Step 1: Carbonates contain CO₃²⁻ ions.","Step 2: Carbonate ions react with H⁺ ions.","Step 3: Carbon dioxide gas and water are formed."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_carbonate_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Carbonate Ions"}', 0),
  (4248, 935, 'What happens to limewater when carbon dioxide is passed through it?', 'text', 1, 'Focus on the core principle of Test for Carbonate Ions.', '{"why":"Insoluble calcium carbonate forms.","sol":"Step 1: Carbon dioxide reacts with calcium hydroxide in limewater.\nStep 2: Calcium carbonate is formed.\nStep 3: Calcium carbonate is insoluble and makes the solution milky.","steps":["Step 1: Carbon dioxide reacts with calcium hydroxide in limewater.","Step 2: Calcium carbonate is formed.","Step 3: Calcium carbonate is insoluble and makes the solution milky."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_carbonate_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Carbonate Ions"}', 1),
  (4249, 935, 'Write the ionic equation for the reaction of carbonate ions with acid.', 'text', 1, 'Focus on the core principle of Test for Carbonate Ions.', '{"why":"This reaction explains the effervescence observed when an acid is added to a carbonate.","sol":"Step 1: Carbonate ion is CO₃²⁻.\nStep 2: Two H⁺ ions are required to balance the charge.\nStep 3: The products are CO₂ and H₂O.","steps":["Step 1: Carbonate ion is CO₃²⁻.","Step 2: Two H⁺ ions are required to balance the charge.","Step 3: The products are CO₂ and H₂O."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_carbonate_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Carbonate Ions"}', 2),
  (4250, 935, 'A solid fizzes when dilute hydrochloric acid is added and the gas turns limewater milky. Which ion is present?', 'text', 1, 'The gas is carbon dioxide.', '{"why":"Carbonates react with acids to release carbon dioxide.","sol":"Step 1: Fizzing indicates gas production.\nStep 2: Limewater turning milky identifies the gas as CO₂.\nStep 3: Carbonates produce CO₂ with acids.","steps":["Step 1: Fizzing indicates gas production.","Step 2: Limewater turning milky identifies the gas as CO₂.","Step 3: Carbonates produce CO₂ with acids."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_carbonate_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Carbonate Ions"}', 3);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (4251, 936, 'Which gas is produced in the aluminium and sodium hydroxide test for nitrate ions?', 'text', 1, 'Focus on the core principle of Test for Nitrate Ions.', '{"why":"The nitrate test produces ammonia when nitrate ions are reduced under the test conditions.","sol":"Step 1: Nitrate ions are reduced during the test.\nStep 2: Ammonia is produced.\nStep 3: The ammonia can be identified using damp red litmus paper.","steps":["Step 1: Nitrate ions are reduced during the test.","Step 2: Ammonia is produced.","Step 3: The ammonia can be identified using damp red litmus paper."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_nitrate_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Nitrate Ions"}', 0),
  (4252, 936, 'What observation confirms that the gas produced in the nitrate test is ammonia?', 'text', 1, 'Focus on the core principle of Test for Nitrate Ions.', '{"why":"Ammonia is alkaline in water.","sol":"Step 1: Collect or expose damp red litmus paper to the gas.\nStep 2: Ammonia dissolves in the moisture on the paper.\nStep 3: The resulting alkaline solution turns red litmus blue.","steps":["Step 1: Collect or expose damp red litmus paper to the gas.","Step 2: Ammonia dissolves in the moisture on the paper.","Step 3: The resulting alkaline solution turns red litmus blue."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_nitrate_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Nitrate Ions"}', 1),
  (4253, 936, 'What ion is indicated if the nitrate test produces ammonia?', 'text', 1, 'Focus on the core principle of Test for Nitrate Ions.', '{"why":"The formation of ammonia is the positive result for nitrate in this test.","sol":"Step 1: Identify the gas as ammonia.\nStep 2: In this test, ammonia is produced from nitrate ions.\nStep 3: Therefore, nitrate ions are indicated.","steps":["Step 1: Identify the gas as ammonia.","Step 2: In this test, ammonia is produced from nitrate ions.","Step 3: Therefore, nitrate ions are indicated."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_nitrate_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Nitrate Ions"}', 2),
  (4254, 936, 'A sample produces ammonia when tested with aluminium and sodium hydroxide. Which anion could be present?', 'text', 1, 'Think of the anion identified by this test.', '{"why":"The test detects nitrate through the formation of ammonia.","sol":"Step 1: Ammonia is produced.\nStep 2: The aluminium/sodium hydroxide test is used for nitrate ions.\nStep 3: Therefore, NO₃⁻ may be present.","steps":["Step 1: Ammonia is produced.","Step 2: The aluminium/sodium hydroxide test is used for nitrate ions.","Step 3: Therefore, NO₃⁻ may be present."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_nitrate_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Nitrate Ions"}', 3),
  (4255, 937, 'What flame colour indicates sodium ions?', 'text', 1, 'Focus on the core principle of Flame Test for Sodium Ions.', '{"why":"Excited sodium atoms emit characteristic yellow light.","sol":"Step 1: Place the sample in the flame.\nStep 2: Observe the characteristic emission colour.\nStep 3: Sodium produces a yellow flame.","steps":["Step 1: Place the sample in the flame.","Step 2: Observe the characteristic emission colour.","Step 3: Sodium produces a yellow flame."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_sodium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Sodium Ions"}', 0),
  (4256, 937, 'Which ion gives a yellow flame in a flame test?', 'text', 1, 'Focus on the core principle of Flame Test for Sodium Ions.', '{"why":"Sodium has a characteristic yellow flame.","sol":"Step 1: Recall the characteristic sodium flame colour.\nStep 2: Sodium produces yellow.\nStep 3: Therefore, the ion is Na⁺.","steps":["Step 1: Recall the characteristic sodium flame colour.","Step 2: Sodium produces yellow.","Step 3: Therefore, the ion is Na⁺."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_sodium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Sodium Ions"}', 1),
  (4257, 937, 'Why must the wire loop be cleaned before another flame test?', 'text', 1, 'Focus on the core principle of Flame Test for Sodium Ions.', '{"why":"A clean loop improves the reliability of the flame test.","sol":"Step 1: Residue from a previous sample may remain on the wire.\nStep 2: The residue may produce its own flame colour.\nStep 3: This could interfere with the new observation.","steps":["Step 1: Residue from a previous sample may remain on the wire.","Step 2: The residue may produce its own flame colour.","Step 3: This could interfere with the new observation."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_sodium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Sodium Ions"}', 2),
  (4258, 937, 'A sample gives a bright yellow flame. Which common metal ion is indicated?', 'text', 1, 'Recall the characteristic flame colour of sodium.', '{"why":"Sodium gives a characteristic yellow flame.","sol":"Step 1: Identify the flame colour as yellow.\nStep 2: Sodium produces a yellow flame.\nStep 3: Therefore, Na⁺ may be present.","steps":["Step 1: Identify the flame colour as yellow.","Step 2: Sodium produces a yellow flame.","Step 3: Therefore, Na⁺ may be present."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_sodium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Sodium Ions"}', 3),
  (4259, 938, 'What flame colour is produced by potassium ions?', 'text', 1, 'Focus on the core principle of Flame Test for Potassium Ions.', '{"why":"Potassium has a characteristic lilac flame.","sol":"Step 1: Place the potassium compound in the flame.\nStep 2: Observe the characteristic emission colour.\nStep 3: Potassium produces a lilac flame.","steps":["Step 1: Place the potassium compound in the flame.","Step 2: Observe the characteristic emission colour.","Step 3: Potassium produces a lilac flame."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_potassium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Potassium Ions"}', 0),
  (4260, 938, 'Which ion gives a lilac flame?', 'text', 1, 'Focus on the core principle of Flame Test for Potassium Ions.', '{"why":"K⁺ produces a lilac flame.","sol":"Step 1: Identify the flame as lilac.\nStep 2: Potassium is associated with this flame colour.\nStep 3: Therefore, the ion is K⁺.","steps":["Step 1: Identify the flame as lilac.","Step 2: Potassium is associated with this flame colour.","Step 3: Therefore, the ion is K⁺."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_potassium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Potassium Ions"}', 1),
  (4261, 938, 'Why can sodium contamination make the potassium flame test difficult to observe?', 'text', 1, 'Focus on the core principle of Flame Test for Potassium Ions.', '{"why":"Sodium emission is intense and can interfere with observation.","sol":"Step 1: Sodium produces a strong yellow flame.\nStep 2: Potassium produces a lilac flame.\nStep 3: The strong sodium yellow can mask the weaker lilac colour.","steps":["Step 1: Sodium produces a strong yellow flame.","Step 2: Potassium produces a lilac flame.","Step 3: The strong sodium yellow can mask the weaker lilac colour."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_potassium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Potassium Ions"}', 2),
  (4262, 938, 'A sample produces a lilac flame. Which ion is indicated?', 'text', 1, 'Recall the flame colour of potassium.', '{"why":"Potassium has a characteristic lilac flame.","sol":"Step 1: Identify the flame colour as lilac.\nStep 2: Potassium produces a lilac flame.\nStep 3: Therefore, K⁺ is indicated.","steps":["Step 1: Identify the flame colour as lilac.","Step 2: Potassium produces a lilac flame.","Step 3: Therefore, K⁺ is indicated."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_potassium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Potassium Ions"}', 3),
  (4263, 939, 'What flame colour is associated with calcium ions?', 'text', 1, 'Focus on the core principle of Flame Test for Calcium Ions.', '{"why":"Calcium produces a characteristic red-orange flame.","sol":"Step 1: Place the calcium compound in the flame.\nStep 2: Observe the emission colour.\nStep 3: Calcium gives a brick-red or orange-red flame.","steps":["Step 1: Place the calcium compound in the flame.","Step 2: Observe the emission colour.","Step 3: Calcium gives a brick-red or orange-red flame."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_calcium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Calcium Ions"}', 0),
  (4264, 939, 'Which ion can produce a brick-red flame?', 'text', 1, 'Focus on the core principle of Flame Test for Calcium Ions.', '{"why":"Ca²⁺ compounds produce a brick-red flame.","sol":"Step 1: Identify the characteristic colour.\nStep 2: Calcium produces a brick-red flame.\nStep 3: Therefore, Ca²⁺ may be present.","steps":["Step 1: Identify the characteristic colour.","Step 2: Calcium produces a brick-red flame.","Step 3: Therefore, Ca²⁺ may be present."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_calcium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Calcium Ions"}', 1),
  (4265, 939, 'Why is the flame test useful in qualitative analysis?', 'text', 1, 'Focus on the core principle of Flame Test for Calcium Ions.', '{"why":"The colours arise from characteristic electronic transitions in the atoms.","sol":"Step 1: Different metal ions emit different characteristic wavelengths of light.\nStep 2: These wavelengths appear as characteristic flame colours.\nStep 3: The colour can therefore help identify the metal ion.","steps":["Step 1: Different metal ions emit different characteristic wavelengths of light.","Step 2: These wavelengths appear as characteristic flame colours.","Step 3: The colour can therefore help identify the metal ion."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_calcium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Calcium Ions"}', 2),
  (4266, 939, 'A compound gives an orange-red flame. Which ion could be present?', 'text', 1, 'Recall the flame colour associated with calcium.', '{"why":"Calcium gives a characteristic orange-red/brick-red flame.","sol":"Step 1: Identify the flame as orange-red.\nStep 2: Calcium compounds produce an orange-red or brick-red flame.\nStep 3: Therefore, Ca²⁺ may be present.","steps":["Step 1: Identify the flame as orange-red.","Step 2: Calcium compounds produce an orange-red or brick-red flame.","Step 3: Therefore, Ca²⁺ may be present."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_calcium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Calcium Ions"}', 3),
  (4267, 940, 'What flame colour is associated with copper compounds?', 'text', 1, 'Focus on the core principle of Flame Test for Copper(II) Ions.', '{"why":"Copper compounds produce characteristic green/blue-green flame colours.","sol":"Step 1: Place the copper compound in the flame.\nStep 2: Observe the emitted light.\nStep 3: Copper compounds commonly produce a blue-green or green flame.","steps":["Step 1: Place the copper compound in the flame.","Step 2: Observe the emitted light.","Step 3: Copper compounds commonly produce a blue-green or green flame."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_copper_ii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Copper(II) Ions"}', 0),
  (4268, 940, 'Which common metal ion can give a blue-green flame?', 'text', 1, 'Focus on the core principle of Flame Test for Copper(II) Ions.', '{"why":"Copper compounds have characteristic blue-green/green flame emissions.","sol":"Step 1: Identify the characteristic flame colour.\nStep 2: Copper compounds produce blue-green or green flames.\nStep 3: Therefore, Cu²⁺ may be present.","steps":["Step 1: Identify the characteristic flame colour.","Step 2: Copper compounds produce blue-green or green flames.","Step 3: Therefore, Cu²⁺ may be present."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_copper_ii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Copper(II) Ions"}', 1),
  (4269, 940, 'Why should flame colour be used together with other observations when identifying an unknown?', 'text', 1, 'Focus on the core principle of Flame Test for Copper(II) Ions.', '{"why":"Qualitative identification is more reliable when multiple consistent observations are used.","sol":"Step 1: Some flame colours can be affected by contamination.\nStep 2: Some colours may be difficult to distinguish.\nStep 3: Additional chemical tests provide stronger evidence.","steps":["Step 1: Some flame colours can be affected by contamination.","Step 2: Some colours may be difficult to distinguish.","Step 3: Additional chemical tests provide stronger evidence."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_copper_ii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Copper(II) Ions"}', 2),
  (4270, 940, 'An unknown compound produces a blue-green flame. Which metal ion could be present?', 'text', 1, 'Think about copper''s flame colour.', '{"why":"Copper compounds commonly give blue-green/green flame colours.","sol":"Step 1: Identify the flame as blue-green.\nStep 2: Copper compounds can produce a blue-green flame.\nStep 3: Therefore, Cu²⁺ could be present.","steps":["Step 1: Identify the flame as blue-green.","Step 2: Copper compounds can produce a blue-green flame.","Step 3: Therefore, Cu²⁺ could be present."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_copper_ii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Copper(II) Ions"}', 3),
  (4271, 941, 'What is the test for hydrogen gas?', 'text', 1, 'Focus on the core principle of Test for Hydrogen.', '{"why":"Hydrogen reacts rapidly with oxygen and burns.","sol":"Step 1: Collect the gas safely.\nStep 2: Bring a lighted splint to the gas.\nStep 3: Listen for the characteristic popping sound.","steps":["Step 1: Collect the gas safely.","Step 2: Bring a lighted splint to the gas.","Step 3: Listen for the characteristic popping sound."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_hydrogen","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Hydrogen"}', 0),
  (4272, 941, 'Write the balanced equation for combustion of hydrogen.', 'text', 1, 'Focus on the core principle of Test for Hydrogen.', '{"why":"Two hydrogen molecules react with one oxygen molecule to form two water molecules.","sol":"Step 1: Hydrogen reacts with oxygen.\nStep 2: The product is water.\nStep 3: Balance hydrogen and oxygen atoms.","steps":["Step 1: Hydrogen reacts with oxygen.","Step 2: The product is water.","Step 3: Balance hydrogen and oxygen atoms."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_hydrogen","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Hydrogen"}', 1),
  (4273, 941, 'Why does hydrogen produce a popping sound during the test?', 'text', 1, 'Focus on the core principle of Test for Hydrogen.', '{"why":"Rapid combustion of hydrogen causes a sudden expansion of hot gases.","sol":"Step 1: Hydrogen mixes with oxygen.\nStep 2: The mixture can burn rapidly when ignited.\nStep 3: Rapid combustion produces the characteristic sound.","steps":["Step 1: Hydrogen mixes with oxygen.","Step 2: The mixture can burn rapidly when ignited.","Step 3: Rapid combustion produces the characteristic sound."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_hydrogen","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Hydrogen"}', 2),
  (4274, 941, 'A gas produces a squeaky pop when tested with a lighted splint. Identify the gas.', 'text', 1, 'This is the classic test for a common combustible gas.', '{"why":"Hydrogen burns rapidly with oxygen and gives a characteristic pop.","sol":"Step 1: Observe the squeaky pop.\nStep 2: This is characteristic of hydrogen.\nStep 3: Therefore, the gas is H₂.","steps":["Step 1: Observe the squeaky pop.","Step 2: This is characteristic of hydrogen.","Step 3: Therefore, the gas is H₂."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_hydrogen","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Hydrogen"}', 3),
  (4275, 942, 'What is the test for oxygen?', 'text', 1, 'Focus on the core principle of Test for Oxygen.', '{"why":"Oxygen supports combustion.","sol":"Step 1: Prepare a glowing splint.\nStep 2: Insert it into the gas sample.\nStep 3: Observe whether the splint relights.","steps":["Step 1: Prepare a glowing splint.","Step 2: Insert it into the gas sample.","Step 3: Observe whether the splint relights."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_oxygen","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Oxygen"}', 0),
  (4276, 942, 'Why does a glowing splint relight in oxygen?', 'text', 1, 'Focus on the core principle of Test for Oxygen.', '{"why":"Oxygen allows combustion to continue more readily.","sol":"Step 1: The splint contains hot material that is already glowing.\nStep 2: Oxygen supports combustion.\nStep 3: The increased oxygen supply allows the splint to burn again.","steps":["Step 1: The splint contains hot material that is already glowing.","Step 2: Oxygen supports combustion.","Step 3: The increased oxygen supply allows the splint to burn again."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_oxygen","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Oxygen"}', 1),
  (4277, 942, 'Does oxygen itself burn during the glowing splint test?', 'text', 1, 'Focus on the core principle of Test for Oxygen.', '{"why":"Oxygen acts as an oxidising gas in combustion.","sol":"Step 1: Oxygen supports the burning of other substances.\nStep 2: It is not the fuel in the test.\nStep 3: Therefore, oxygen supports combustion rather than burning itself.","steps":["Step 1: Oxygen supports the burning of other substances.","Step 2: It is not the fuel in the test.","Step 3: Therefore, oxygen supports combustion rather than burning itself."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_oxygen","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Oxygen"}', 2),
  (4278, 942, 'A glowing splint relights when placed in a gas. Identify the gas.', 'text', 1, 'Think of the gas that supports combustion.', '{"why":"Oxygen relights a glowing splint.","sol":"Step 1: Relighting a glowing splint is the characteristic test.\nStep 2: Oxygen supports combustion.\nStep 3: Therefore, the gas is oxygen.","steps":["Step 1: Relighting a glowing splint is the characteristic test.","Step 2: Oxygen supports combustion.","Step 3: Therefore, the gas is oxygen."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_oxygen","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Oxygen"}', 3),
  (4279, 943, 'What is the test for carbon dioxide?', 'text', 1, 'Focus on the core principle of Test for Carbon Dioxide.', '{"why":"Carbon dioxide reacts with limewater to form insoluble calcium carbonate.","sol":"Step 1: Pass the gas into limewater.\nStep 2: Observe the appearance of the limewater.\nStep 3: A milky appearance indicates carbon dioxide.","steps":["Step 1: Pass the gas into limewater.","Step 2: Observe the appearance of the limewater.","Step 3: A milky appearance indicates carbon dioxide."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_carbon_dioxide","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Carbon Dioxide"}', 0),
  (4280, 943, 'Why does limewater turn milky when carbon dioxide is passed through it?', 'text', 1, 'Focus on the core principle of Test for Carbon Dioxide.', '{"why":"The suspended calcium carbonate makes the limewater appear milky.","sol":"Step 1: Carbon dioxide reacts with calcium hydroxide.\nStep 2: Calcium carbonate is formed.\nStep 3: Calcium carbonate is insoluble and appears as a suspension.","steps":["Step 1: Carbon dioxide reacts with calcium hydroxide.","Step 2: Calcium carbonate is formed.","Step 3: Calcium carbonate is insoluble and appears as a suspension."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_carbon_dioxide","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Carbon Dioxide"}', 1),
  (4281, 943, 'Write the equation for the reaction of carbon dioxide with limewater.', 'text', 1, 'Focus on the core principle of Test for Carbon Dioxide.', '{"why":"The reaction produces insoluble calcium carbonate.","sol":"Step 1: Carbon dioxide reacts with calcium hydroxide.\nStep 2: Calcium carbonate and water are formed.\nStep 3: Write the balanced equation.","steps":["Step 1: Carbon dioxide reacts with calcium hydroxide.","Step 2: Calcium carbonate and water are formed.","Step 3: Write the balanced equation."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_carbon_dioxide","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Carbon Dioxide"}', 2),
  (4282, 943, 'An unknown gas turns limewater milky. Identify the gas.', 'text', 1, 'Think of the gas that forms calcium carbonate with limewater.', '{"why":"CO₂ gives the characteristic limewater test.","sol":"Step 1: Limewater contains calcium hydroxide.\nStep 2: Carbon dioxide reacts with it to form calcium carbonate.\nStep 3: Therefore, the gas is CO₂.","steps":["Step 1: Limewater contains calcium hydroxide.","Step 2: Carbon dioxide reacts with it to form calcium carbonate.","Step 3: Therefore, the gas is CO₂."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_carbon_dioxide","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Carbon Dioxide"}', 3),
  (4283, 944, 'What happens when ammonia is brought into contact with damp red litmus paper?', 'text', 1, 'Focus on the core principle of Test for Ammonia.', '{"why":"Ammonia produces an alkaline solution in water.","sol":"Step 1: Ammonia dissolves in the moisture on the paper.\nStep 2: The resulting solution is alkaline.\nStep 3: Alkaline solutions turn red litmus blue.","steps":["Step 1: Ammonia dissolves in the moisture on the paper.","Step 2: The resulting solution is alkaline.","Step 3: Alkaline solutions turn red litmus blue."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_ammonia","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Ammonia"}', 0),
  (4284, 944, 'Why must the litmus paper be damp when testing for ammonia?', 'text', 1, 'Focus on the core principle of Test for Ammonia.', '{"why":"The indicator requires an aqueous environment to show the alkaline property clearly.","sol":"Step 1: Ammonia is highly soluble in water.\nStep 2: The moisture allows ammonia to dissolve.\nStep 3: The resulting alkaline solution changes the indicator colour.","steps":["Step 1: Ammonia is highly soluble in water.","Step 2: The moisture allows ammonia to dissolve.","Step 3: The resulting alkaline solution changes the indicator colour."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_ammonia","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Ammonia"}', 1),
  (4285, 944, 'What type of substance is ammonia when dissolved in water?', 'text', 1, 'Focus on the core principle of Test for Ammonia.', '{"why":"Ammonia reacts with water to produce hydroxide ions.","sol":"Step 1: Ammonia dissolves in water.\nStep 2: It produces an alkaline solution.\nStep 3: Therefore, ammonia behaves as a weak alkali in water.","steps":["Step 1: Ammonia dissolves in water.","Step 2: It produces an alkaline solution.","Step 3: Therefore, ammonia behaves as a weak alkali in water."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_ammonia","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Ammonia"}', 2),
  (4286, 944, 'A colourless gas turns damp red litmus paper blue. Which gas could it be?', 'text', 1, 'Think of a common alkaline gas.', '{"why":"Ammonia turns damp red litmus paper blue.","sol":"Step 1: The gas produces an alkaline solution with moisture.\nStep 2: Ammonia is a common alkaline gas.\nStep 3: Therefore, the gas could be NH₃.","steps":["Step 1: The gas produces an alkaline solution with moisture.","Step 2: Ammonia is a common alkaline gas.","Step 3: Therefore, the gas could be NH₃."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_ammonia","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Ammonia"}', 3),
  (4287, 945, 'What happens to damp blue litmus paper in chlorine gas?', 'text', 1, 'Focus on the core principle of Test for Chlorine.', '{"why":"Chlorine reacts with water and has a bleaching action in the presence of moisture.","sol":"Step 1: Chlorine reacts with water on the damp paper.\nStep 2: The acidic products can initially turn blue litmus red.\nStep 3: Chlorine''s bleaching action then removes the colour.","steps":["Step 1: Chlorine reacts with water on the damp paper.","Step 2: The acidic products can initially turn blue litmus red.","Step 3: Chlorine''s bleaching action then removes the colour."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_chlorine","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Chlorine"}', 0),
  (4288, 945, 'Why must the litmus paper be damp when testing for chlorine?', 'text', 1, 'Focus on the core principle of Test for Chlorine.', '{"why":"Dry chlorine does not show the same bleaching behaviour as readily as moist chlorine.","sol":"Step 1: Chlorine reacts with water.\nStep 2: The moisture allows the relevant reactions to occur.\nStep 3: The bleaching effect can then be observed.","steps":["Step 1: Chlorine reacts with water.","Step 2: The moisture allows the relevant reactions to occur.","Step 3: The bleaching effect can then be observed."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_chlorine","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Chlorine"}', 1),
  (4289, 945, 'State two observable properties that can help identify chlorine gas.', 'text', 1, 'Focus on the core principle of Test for Chlorine.', '{"why":"Both observations are characteristic of chlorine.","sol":"Step 1: Chlorine has a characteristic colour.\nStep 2: It also has a characteristic effect on damp litmus.\nStep 3: These observations can support identification.","steps":["Step 1: Chlorine has a characteristic colour.","Step 2: It also has a characteristic effect on damp litmus.","Step 3: These observations can support identification."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_chlorine","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Chlorine"}', 2),
  (4290, 945, 'A greenish-yellow gas turns damp blue litmus red and then bleaches it. Identify the gas.', 'text', 1, 'Think of the halogen gas with bleaching properties.', '{"why":"Chlorine is a greenish-yellow gas that bleaches damp litmus.","sol":"Step 1: The gas is greenish-yellow.\nStep 2: It bleaches damp litmus.\nStep 3: These observations identify chlorine.","steps":["Step 1: The gas is greenish-yellow.","Step 2: It bleaches damp litmus.","Step 3: These observations identify chlorine."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_chlorine","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Chlorine"}', 3),
  (4291, 946, 'Define a reversible chemical reaction.', 'text', 1, 'Focus on the core principle of Reversible Reactions.', '{"why":"The defining feature is that the original chemical change can proceed in both directions.","sol":"Step 1: Identify key concept: Define the required principles for Reversible Reactions.\nStep 2: Apply governing rule: The defining feature is that the original chemical change can proceed in both directions.\nStep 3: State the final conclusion: A chemical reaction in which the products can react to reform the original reactants under suitable conditions.","steps":["Step 1: Identify key concept: Define the required principles for Reversible Reactions.","Step 2: Apply governing rule: The defining feature is that the original chemical change can proceed in both directions.","Step 3: State the final conclusion: A chemical reaction in which the products can react to reform the original reactants under suitable conditions."],"options":[],"conceptId":"chemistry_reversible_equilibrium_reversible_reactions","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q1","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Reversible Reactions"}', 0),
  (4292, 946, 'What does the symbol ⇌ mean in a chemical equation?', 'text', 1, 'Focus on the core principle of Reversible Reactions.', '{"why":"The double arrow represents two possible directions of the same reversible chemical change.","sol":"Step 1: Identify key concept: Define the required principles for Reversible Reactions.\nStep 2: Apply governing rule: The double arrow represents two possible directions of the same reversible chemical change.\nStep 3: State the final conclusion: It indicates that the reaction can proceed in both the forward and reverse directions.","steps":["Step 1: Identify key concept: Define the required principles for Reversible Reactions.","Step 2: Apply governing rule: The double arrow represents two possible directions of the same reversible chemical change.","Step 3: State the final conclusion: It indicates that the reaction can proceed in both the forward and reverse directions."],"options":[],"conceptId":"chemistry_reversible_equilibrium_reversible_reactions","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q2","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Reversible Reactions"}', 1),
  (4293, 946, 'Hydrated copper(II) sulfate can form anhydrous copper(II) sulfate on heating, and the hydrated compound can form again when water is added. What does this demonstrate?', 'text', 1, 'Focus on the core principle of Reversible Reactions.', '{"why":"The process connects the hydrated and anhydrous forms through opposite chemical changes.","sol":"Step 1: Identify key concept: Define the required principles for Reversible Reactions.\nStep 2: Apply governing rule: The process connects the hydrated and anhydrous forms through opposite chemical changes.\nStep 3: State the final conclusion: It demonstrates a reversible chemical change because the original hydrated compound can be regenerated.","steps":["Step 1: Identify key concept: Define the required principles for Reversible Reactions.","Step 2: Apply governing rule: The process connects the hydrated and anhydrous forms through opposite chemical changes.","Step 3: State the final conclusion: It demonstrates a reversible chemical change because the original hydrated compound can be regenerated."],"options":[],"conceptId":"chemistry_reversible_equilibrium_reversible_reactions","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q3","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Reversible Reactions"}', 2),
  (4294, 946, 'A learner says that A + B ⇌ C + D means only A and B can react, while C and D are permanent products. Identify the error.', 'text', 1, 'Interpret both directions of the arrow.', '{"why":"A double arrow represents a reversible reaction, not a one-way reaction with permanent products.","sol":"Step 1: Read the left-to-right direction: A and B form C and D.\nStep 2: Read the right-to-left direction: C and D can reform A and B.\nStep 3: Explain what the double arrow represents.","steps":["Step 1: Read the left-to-right direction: A and B form C and D.","Step 2: Read the right-to-left direction: C and D can reform A and B.","Step 3: Explain what the double arrow represents."],"options":[],"conceptId":"chemistry_reversible_equilibrium_reversible_reactions","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q4","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Reversible Reactions"}', 3),
  (4295, 946, 'Which equation represents a reversible reaction: (i) P + Q → R, or (ii) P + Q ⇌ R? Explain what the symbol tells you.', 'text', 1, 'Compare the arrow symbols, not just the letters.', '{"why":"The double arrow indicates forward and reverse directions. A single arrow conventionally represents a reaction written in one direction.","sol":"Step 1: Identify the arrow in equation (i).\nStep 2: Identify the arrow in equation (ii).\nStep 3: Determine which equation explicitly represents both reaction directions.","steps":["Step 1: Identify the arrow in equation (i).","Step 2: Identify the arrow in equation (ii).","Step 3: Determine which equation explicitly represents both reaction directions."],"options":[],"conceptId":"chemistry_reversible_equilibrium_reversible_reactions","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q5","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Reversible Reactions"}', 4),
  (4296, 946, 'A substance changes into product X. In a separate process, X reacts with another substance to produce a different compound Y, but the original reactants are not regenerated. Does this alone prove that the first reaction is reversible?', 'text', 1, 'Ask whether the original reactants return.', '{"why":"A different reaction involving a product is not necessarily the reverse of the original reaction.","sol":"Step 1: Recall the defining feature of a reversible reaction.\nStep 2: Compare that feature with the stated formation of Y.\nStep 3: Decide whether the original reactants are regenerated.","steps":["Step 1: Recall the defining feature of a reversible reaction.","Step 2: Compare that feature with the stated formation of Y.","Step 3: Decide whether the original reactants are regenerated."],"options":[],"conceptId":"chemistry_reversible_equilibrium_reversible_reactions","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q6","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Reversible Reactions"}', 5),
  (4297, 946, 'Heating hydrated copper(II) sulfate produces white anhydrous copper(II) sulfate. Adding water can regenerate the blue hydrated compound. Explain the evidence for reversibility.', 'text', 1, 'Identify the original compound and what happens when water is added.', '{"why":"The same chemical forms are connected by changes in opposite directions.","sol":"Step 1: State what heating does to the hydrated compound.\nStep 2: State what adding water does to the anhydrous compound.\nStep 3: Connect the two observations.","steps":["Step 1: State what heating does to the hydrated compound.","Step 2: State what adding water does to the anhydrous compound.","Step 3: Connect the two observations."],"options":[],"conceptId":"chemistry_reversible_equilibrium_reversible_reactions","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q7","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Reversible Reactions"}', 6),
  (4298, 946, 'A student claims that the symbol ⇌ proves that both directions occur at exactly the same rate. Is the claim correct?', 'text', 1, 'Separate the meaning of a reaction arrow from the meaning of reaction rate.', '{"why":"The relative rates depend on the reaction conditions and composition of the reacting mixture.","sol":"Step 1: State what ⇌ represents.\nStep 2: Identify whether it gives a numerical or comparative rate.\nStep 3: Decide whether equal rates follow from the symbol alone.","steps":["Step 1: State what ⇌ represents.","Step 2: Identify whether it gives a numerical or comparative rate.","Step 3: Decide whether equal rates follow from the symbol alone."],"options":[],"conceptId":"chemistry_reversible_equilibrium_reversible_reactions","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q8","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Reversible Reactions"}', 7),
  (4299, 946, 'Magnesium burns in oxygen to form magnesium oxide. Why is this normally treated as an effectively irreversible reaction under ordinary classroom conditions?', 'text', 1, 'Consider whether magnesium oxide simply regenerates magnesium and oxygen under the same conditions.', '{"why":"Some chemical changes are strongly favoured in one direction under the conditions used. This does not mean that reversal is impossible under every conceivable condition.","sol":"Step 1: Write the reaction: 2Mg + O₂ → 2MgO.\nStep 2: Consider whether the product readily decomposes back into the original reactants under ordinary conditions.\nStep 3: Distinguish an effectively one-way reaction from a reversible reaction.","steps":["Step 1: Write the reaction: 2Mg + O₂ → 2MgO.","Step 2: Consider whether the product readily decomposes back into the original reactants under ordinary conditions.","Step 3: Distinguish an effectively one-way reaction from a reversible reaction."],"options":[],"conceptId":"chemistry_reversible_equilibrium_reversible_reactions","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q9","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Reversible Reactions"}', 8),
  (4300, 947, 'For A + B ⇌ C + D, write the forward reaction in words.', 'text', 1, 'Focus on the core principle of Forward and Reverse Reactions.', '{"why":"The forward direction proceeds from left to right in the equation.","sol":"Step 1: Identify key concept: Define the required principles for Forward and Reverse Reactions.\nStep 2: Apply governing rule: The forward direction proceeds from left to right in the equation.\nStep 3: State the final conclusion: A reacts with B to form C and D.","steps":["Step 1: Identify key concept: Define the required principles for Forward and Reverse Reactions.","Step 2: Apply governing rule: The forward direction proceeds from left to right in the equation.","Step 3: State the final conclusion: A reacts with B to form C and D."],"options":[],"conceptId":"chemistry_reversible_equilibrium_forward_and_reverse_reactions","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q1","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Forward and Reverse Reactions"}', 0),
  (4301, 947, 'For H₂ + I₂ ⇌ 2HI, write the reverse reaction as a balanced equation.', 'text', 1, 'Focus on the core principle of Forward and Reverse Reactions.', '{"why":"Reversing the reaction exchanges the two sides while preserving the atom balance.","sol":"Step 1: Identify key concept: Define the required principles for Forward and Reverse Reactions.\nStep 2: Apply governing rule: Reversing the reaction exchanges the two sides while preserving the atom balance.\nStep 3: State the final conclusion: 2HI → H₂ + I₂","steps":["Step 1: Identify key concept: Define the required principles for Forward and Reverse Reactions.","Step 2: Apply governing rule: Reversing the reaction exchanges the two sides while preserving the atom balance.","Step 3: State the final conclusion: 2HI → H₂ + I₂"],"options":[],"conceptId":"chemistry_reversible_equilibrium_forward_and_reverse_reactions","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q2","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Forward and Reverse Reactions"}', 1),
  (4302, 947, 'In A + B ⇌ C + D, which substances are the reactants in the reverse direction?', 'text', 1, 'Focus on the core principle of Forward and Reverse Reactions.', '{"why":"The reverse reaction proceeds from right to left, so C and D are consumed to form A and B.","sol":"Step 1: Identify key concept: Define the required principles for Forward and Reverse Reactions.\nStep 2: Apply governing rule: The reverse reaction proceeds from right to left, so C and D are consumed to form A and B.\nStep 3: State the final conclusion: C and D.","steps":["Step 1: Identify key concept: Define the required principles for Forward and Reverse Reactions.","Step 2: Apply governing rule: The reverse reaction proceeds from right to left, so C and D are consumed to form A and B.","Step 3: State the final conclusion: C and D."],"options":[],"conceptId":"chemistry_reversible_equilibrium_forward_and_reverse_reactions","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q3","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Forward and Reverse Reactions"}', 2),
  (4303, 947, 'For X + Y ⇌ Z, identify the forward and reverse reactions in words.', 'text', 1, 'Read the equation from left to right, then from right to left.', '{"why":"The two directions describe the same chemical change proceeding in opposite directions.","sol":"Step 1: Start with X and Y on the left.\nStep 2: Follow the arrow to identify the products of the forward reaction.\nStep 3: Start with Z on the right to describe the reverse reaction.","steps":["Step 1: Start with X and Y on the left.","Step 2: Follow the arrow to identify the products of the forward reaction.","Step 3: Start with Z on the right to describe the reverse reaction."],"options":[],"conceptId":"chemistry_reversible_equilibrium_forward_and_reverse_reactions","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q4","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Forward and Reverse Reactions"}', 3),
  (4304, 947, 'For H₂ + I₂ ⇌ 2HI, a learner writes the reverse reaction as HI → H₂ + I₂. Explain the error and give the balanced reverse equation.', 'text', 1, 'Check both the number of hydrogen atoms and the number of iodine atoms.', '{"why":"A reversed equation must still conserve every type of atom. Two HI molecules are needed to supply two hydrogen atoms and two iodine atoms.","sol":"Step 1: Reverse the sides of the original equation.\nStep 2: Retain the coefficient 2 before HI.\nStep 3: Count hydrogen and iodine atoms on both sides.","steps":["Step 1: Reverse the sides of the original equation.","Step 2: Retain the coefficient 2 before HI.","Step 3: Count hydrogen and iodine atoms on both sides."],"options":[],"conceptId":"chemistry_reversible_equilibrium_forward_and_reverse_reactions","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q5","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Forward and Reverse Reactions"}', 4),
  (4305, 947, 'For N₂ + 3H₂ ⇌ 2NH₃, identify the reactants and products in the reverse direction.', 'text', 1, 'In the reverse direction, begin with the substances originally on the right.', '{"why":"Reactant and product roles are determined by the direction of the reaction being described.","sol":"Step 1: Identify the right-hand side of the original equation.\nStep 2: Make that side the starting side of the reverse reaction.\nStep 3: Identify the substances formed on the other side.","steps":["Step 1: Identify the right-hand side of the original equation.","Step 2: Make that side the starting side of the reverse reaction.","Step 3: Identify the substances formed on the other side."],"options":[],"conceptId":"chemistry_reversible_equilibrium_forward_and_reverse_reactions","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q6","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Forward and Reverse Reactions"}', 5),
  (4306, 947, 'A learner says that C and D in A + B ⇌ C + D can never be called reactants because they are written on the right. Is this correct?', 'text', 1, 'Think about which direction consumes C and D.', '{"why":"The left and right positions describe the equation''s written direction; they do not make a substance permanently a reactant or product.","sol":"Step 1: Identify the forward direction.\nStep 2: Identify the reverse direction.\nStep 3: Determine which substances are consumed in the reverse reaction.","steps":["Step 1: Identify the forward direction.","Step 2: Identify the reverse direction.","Step 3: Determine which substances are consumed in the reverse reaction."],"options":[],"conceptId":"chemistry_reversible_equilibrium_forward_and_reverse_reactions","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q7","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Forward and Reverse Reactions"}', 6),
  (4307, 947, 'A learner correctly identifies the forward reaction but says that it must be faster than the reverse reaction because it is called forward. Explain why this reasoning is wrong.', 'text', 1, 'Separate the meaning of direction from the meaning of rate.', '{"why":"Reaction direction and reaction speed are different properties.","sol":"Step 1: Define what forward means.\nStep 2: Define what reaction rate means.\nStep 3: Decide whether the word forward specifies speed.","steps":["Step 1: Define what forward means.","Step 2: Define what reaction rate means.","Step 3: Decide whether the word forward specifies speed."],"options":[],"conceptId":"chemistry_reversible_equilibrium_forward_and_reverse_reactions","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q8","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Forward and Reverse Reactions"}', 7),
  (4308, 947, 'For the reversible equation P + 2Q ⇌ R, a learner writes the reverse reaction as R → P + Q. Correct the equation and explain why the correction is necessary.', 'text', 1, 'Reverse the sides and preserve the coefficient of Q.', '{"why":"Reversing an equation changes the direction, not the chemical formulae or stoichiometric coefficients.","sol":"Step 1: Write the original left-hand side as the products of the reverse reaction.\nStep 2: Write the original right-hand side as the reactant of the reverse reaction.\nStep 3: Check that the coefficient 2 remains before Q.","steps":["Step 1: Write the original left-hand side as the products of the reverse reaction.","Step 2: Write the original right-hand side as the reactant of the reverse reaction.","Step 3: Check that the coefficient 2 remains before Q."],"options":[],"conceptId":"chemistry_reversible_equilibrium_forward_and_reverse_reactions","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q9","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Forward and Reverse Reactions"}', 8),
  (4309, 948, 'Define dynamic chemical equilibrium.', 'text', 1, 'Focus on the core principle of Dynamic Equilibrium.', '{"why":"Equilibrium involves ongoing opposing reactions whose rates balance, producing no net change in concentration.","sol":"Step 1: Identify key concept: Define the required principles for Dynamic Equilibrium.\nStep 2: Apply governing rule: Equilibrium involves ongoing opposing reactions whose rates balance, producing no net change in concentration.\nStep 3: State the final conclusion: A state in a closed system where the forward and reverse reactions continue at equal rates and the concentrations of reactants and products remain constant at a given temperature.","steps":["Step 1: Identify key concept: Define the required principles for Dynamic Equilibrium.","Step 2: Apply governing rule: Equilibrium involves ongoing opposing reactions whose rates balance, producing no net change in concentration.","Step 3: State the final conclusion: A state in a closed system where the forward and reverse reactions continue at equal rates and the concentrations of reactants and products remain constant at a given temperature."],"options":[],"conceptId":"chemistry_reversible_equilibrium_dynamic_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q1","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Dynamic Equilibrium"}', 0),
  (4310, 948, 'At equilibrium, the forward reaction rate is 15 units per second. What is the reverse reaction rate?', 'text', 1, 'Focus on the core principle of Dynamic Equilibrium.', '{"why":"The forward and reverse rates are equal at dynamic equilibrium.","sol":"Step 1: Identify key concept: Define the required principles for Dynamic Equilibrium.\nStep 2: Apply governing rule: The forward and reverse rates are equal at dynamic equilibrium.\nStep 3: State the final conclusion: 15 units per second.","steps":["Step 1: Identify key concept: Define the required principles for Dynamic Equilibrium.","Step 2: Apply governing rule: The forward and reverse rates are equal at dynamic equilibrium.","Step 3: State the final conclusion: 15 units per second."],"options":[],"conceptId":"chemistry_reversible_equilibrium_dynamic_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q2","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Dynamic Equilibrium"}', 1),
  (4311, 948, 'Why can the concentrations of reactants and products be different at equilibrium?', 'text', 1, 'Focus on the core principle of Dynamic Equilibrium.', '{"why":"Concentration measures the amount of a substance per unit volume, while reaction rate measures how quickly a reaction occurs.","sol":"Step 1: Identify key concept: Define the required principles for Dynamic Equilibrium.\nStep 2: Apply governing rule: Concentration measures the amount of a substance per unit volume, while reaction rate measures how quickly a reaction occurs.\nStep 3: State the final conclusion: Because equilibrium requires equal forward and reverse reaction rates, not equal concentrations.","steps":["Step 1: Identify key concept: Define the required principles for Dynamic Equilibrium.","Step 2: Apply governing rule: Concentration measures the amount of a substance per unit volume, while reaction rate measures how quickly a reaction occurs.","Step 3: State the final conclusion: Because equilibrium requires equal forward and reverse reaction rates, not equal concentrations."],"options":[],"conceptId":"chemistry_reversible_equilibrium_dynamic_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q3","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Dynamic Equilibrium"}', 2),
  (4312, 948, 'A sealed reaction vessel has a forward rate of 6 mol/dm³/s and a reverse rate of 4 mol/dm³/s. Is it at dynamic equilibrium? Explain.', 'text', 1, 'Compare the two rates directly.', '{"why":"Dynamic equilibrium requires the forward and reverse reaction rates to be equal, even when the system is closed.","sol":"Step 1: State the forward reaction rate.\nStep 2: State the reverse reaction rate.\nStep 3: Compare the values with the equal-rate requirement.","steps":["Step 1: State the forward reaction rate.","Step 2: State the reverse reaction rate.","Step 3: Compare the values with the equal-rate requirement."],"options":[],"conceptId":"chemistry_reversible_equilibrium_dynamic_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q4","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Dynamic Equilibrium"}', 3),
  (4313, 948, 'A learner says, ''At equilibrium, the forward reaction stops because the concentrations are no longer changing.'' Correct the statement.', 'text', 1, 'Think about what the reverse reaction is doing at the same time.', '{"why":"Equilibrium is dynamic: the reactions continue even though the overall composition does not change.","sol":"Step 1: Identify what constant concentrations tell you.\nStep 2: Recall whether the forward reaction continues at equilibrium.\nStep 3: Explain how the reverse reaction balances the forward reaction.","steps":["Step 1: Identify what constant concentrations tell you.","Step 2: Recall whether the forward reaction continues at equilibrium.","Step 3: Explain how the reverse reaction balances the forward reaction."],"options":[],"conceptId":"chemistry_reversible_equilibrium_dynamic_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q5","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Dynamic Equilibrium"}', 4),
  (4314, 948, 'At equilibrium, a mixture contains 0.60 mol/dm³ of A and 1.40 mol/dm³ of B. Does the concentration difference prove that the system is not at equilibrium?', 'text', 1, 'Identify whether equilibrium requires equal amounts or equal rates.', '{"why":"Equilibrium does not require equal concentrations or equal amounts of reactants and products.","sol":"Step 1: Compare the stated concentrations.\nStep 2: Recall the defining rate condition for equilibrium.\nStep 3: Decide whether unequal concentrations violate that condition.","steps":["Step 1: Compare the stated concentrations.","Step 2: Recall the defining rate condition for equilibrium.","Step 3: Decide whether unequal concentrations violate that condition."],"options":[],"conceptId":"chemistry_reversible_equilibrium_dynamic_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q6","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Dynamic Equilibrium"}', 5),
  (4315, 948, 'Why is a closed system important when establishing ordinary chemical equilibrium?', 'text', 1, 'Consider what could happen if a gaseous product escaped continuously.', '{"why":"Continuous loss or addition of substances can disturb the composition and prevent the ordinary closed-system equilibrium from being maintained.","sol":"Step 1: Consider what happens if a reactant enters or a product escapes.\nStep 2: Explain how this affects the amounts of substances available for reaction.\nStep 3: Relate the answer to maintaining a stable equilibrium composition.","steps":["Step 1: Consider what happens if a reactant enters or a product escapes.","Step 2: Explain how this affects the amounts of substances available for reaction.","Step 3: Relate the answer to maintaining a stable equilibrium composition."],"options":[],"conceptId":"chemistry_reversible_equilibrium_dynamic_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q7","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Dynamic Equilibrium"}', 6),
  (4316, 948, 'A student observes constant concentrations in a container and immediately concludes that dynamic equilibrium has been proved. Why is this evidence alone insufficient?', 'text', 1, 'Consider whether a reaction could stop without its forward and reverse rates balancing.', '{"why":"A static or exhausted system may show no concentration change without having dynamic equilibrium.","sol":"Step 1: State what constant concentrations show.\nStep 2: Consider a reaction that has stopped because a necessary reactant has been exhausted.\nStep 3: Identify the additional conditions needed for dynamic equilibrium.","steps":["Step 1: State what constant concentrations show.","Step 2: Consider a reaction that has stopped because a necessary reactant has been exhausted.","Step 3: Identify the additional conditions needed for dynamic equilibrium."],"options":[],"conceptId":"chemistry_reversible_equilibrium_dynamic_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q8","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Dynamic Equilibrium"}', 7),
  (4317, 948, 'At equilibrium, the forward reaction converts 20 units of substance per second. The reverse reaction also converts 20 units per second. Explain what happens to the overall concentrations and why.', 'text', 1, 'Compare the amount produced with the amount consumed in each direction.', '{"why":"Equal opposing reaction rates balance the overall changes while both reactions continue.","sol":"Step 1: Identify the forward rate.\nStep 2: Identify the reverse rate.\nStep 3: Compare the production and consumption rates.\nStep 4: State the net effect on the concentrations.","steps":["Step 1: Identify the forward rate.","Step 2: Identify the reverse rate.","Step 3: Compare the production and consumption rates.","Step 4: State the net effect on the concentrations."],"options":[],"conceptId":"chemistry_reversible_equilibrium_dynamic_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q9","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Dynamic Equilibrium"}', 8),
  (4318, 949, 'A reversible reaction begins with reactants only. If no products are initially present, what is the initial reverse reaction rate?', 'text', 1, 'Focus on the core principle of Establishing Equilibrium.', '{"why":"Without the necessary products, the reverse reaction cannot initially proceed.","sol":"Step 1: Identify key concept: Define the required principles for Establishing Equilibrium.\nStep 2: Apply governing rule: Without the necessary products, the reverse reaction cannot initially proceed.\nStep 3: State the final conclusion: The initial reverse reaction rate is zero, assuming the reverse reaction requires the products that are initially absent.","steps":["Step 1: Identify key concept: Define the required principles for Establishing Equilibrium.","Step 2: Apply governing rule: Without the necessary products, the reverse reaction cannot initially proceed.","Step 3: State the final conclusion: The initial reverse reaction rate is zero, assuming the reverse reaction requires the products that are initially absent."],"options":[],"conceptId":"chemistry_reversible_equilibrium_establishing_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q1","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Establishing Equilibrium"}', 0),
  (4319, 949, 'As products accumulate in a reversible reaction that begins with reactants only, what commonly happens to the forward and reverse rates?', 'text', 1, 'Focus on the core principle of Establishing Equilibrium.', '{"why":"The changing concentrations commonly alter the rates of the opposing reactions as the system approaches equilibrium.","sol":"Step 1: Identify key concept: Define the required principles for Establishing Equilibrium.\nStep 2: Apply governing rule: The changing concentrations commonly alter the rates of the opposing reactions as the system approaches equilibrium.\nStep 3: State the final conclusion: The forward rate commonly decreases as reactants are consumed, while the reverse rate increases as products accumulate.","steps":["Step 1: Identify key concept: Define the required principles for Establishing Equilibrium.","Step 2: Apply governing rule: The changing concentrations commonly alter the rates of the opposing reactions as the system approaches equilibrium.","Step 3: State the final conclusion: The forward rate commonly decreases as reactants are consumed, while the reverse rate increases as products accumulate."],"options":[],"conceptId":"chemistry_reversible_equilibrium_establishing_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q2","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Establishing Equilibrium"}', 1),
  (4320, 949, 'A reaction has a forward rate of 5 units/s and a reverse rate of 5 units/s in a closed vessel at constant temperature. What does this indicate?', 'text', 1, 'Focus on the core principle of Establishing Equilibrium.', '{"why":"At dynamic equilibrium, the forward and reverse rates are equal and both reactions continue.","sol":"Step 1: Identify key concept: Define the required principles for Establishing Equilibrium.\nStep 2: Apply governing rule: At dynamic equilibrium, the forward and reverse rates are equal and both reactions continue.\nStep 3: State the final conclusion: The reaction rates satisfy the condition for dynamic equilibrium.","steps":["Step 1: Identify key concept: Define the required principles for Establishing Equilibrium.","Step 2: Apply governing rule: At dynamic equilibrium, the forward and reverse rates are equal and both reactions continue.","Step 3: State the final conclusion: The reaction rates satisfy the condition for dynamic equilibrium."],"options":[],"conceptId":"chemistry_reversible_equilibrium_establishing_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q3","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Establishing Equilibrium"}', 2),
  (4321, 949, 'A reversible reaction starts with reactants only. Explain why the reverse rate is initially zero if none of the products is present.', 'text', 1, 'Identify which substances are required for the reverse reaction.', '{"why":"The reverse reaction cannot proceed until its required products have formed in the mixture.","sol":"Step 1: Identify the products of the forward reaction.\nStep 2: Recognise that these products are the reactants for the reverse direction.\nStep 3: Determine what happens when the required products are absent.","steps":["Step 1: Identify the products of the forward reaction.","Step 2: Recognise that these products are the reactants for the reverse direction.","Step 3: Determine what happens when the required products are absent."],"options":[],"conceptId":"chemistry_reversible_equilibrium_establishing_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q4","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Establishing Equilibrium"}', 3),
  (4322, 949, 'As a reversible reaction approaches equilibrium, the forward rate falls from 12 to 6 units/s. Over the same period, the reverse rate rises from 1 to 6 units/s. What can you conclude when both rates reach 6 units/s?', 'text', 1, 'Compare the two rates and apply the definition of dynamic equilibrium.', '{"why":"The forward and reverse rates are equal at 6 units/s, so there is no net change in the concentrations.","sol":"Step 1: Record the forward rate at the final time.\nStep 2: Record the reverse rate at the final time.\nStep 3: Check whether the rates are equal.\nStep 4: State what equality means in the closed system.","steps":["Step 1: Record the forward rate at the final time.","Step 2: Record the reverse rate at the final time.","Step 3: Check whether the rates are equal.","Step 4: State what equality means in the closed system."],"options":[],"conceptId":"chemistry_reversible_equilibrium_establishing_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q5","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Establishing Equilibrium"}', 4),
  (4323, 949, 'A student says, ''The forward reaction slows down because the reverse reaction has started.'' Explain why this is an incomplete explanation.', 'text', 1, 'Consider what happens to the reactant concentrations during the forward reaction.', '{"why":"The two rates respond to the changing composition of the reacting mixture.","sol":"Step 1: Identify what the forward reaction consumes.\nStep 2: Explain how consuming reactants commonly affects the forward rate.\nStep 3: Explain separately how accumulating products affect the reverse rate.","steps":["Step 1: Identify what the forward reaction consumes.","Step 2: Explain how consuming reactants commonly affects the forward rate.","Step 3: Explain separately how accumulating products affect the reverse rate."],"options":[],"conceptId":"chemistry_reversible_equilibrium_establishing_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q6","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Establishing Equilibrium"}', 5),
  (4324, 949, 'A learner believes that all reactants must be used up before equilibrium is established. Correct this misconception.', 'text', 1, 'Recall what happens to the two reaction rates at equilibrium.', '{"why":"Equilibrium is determined by the balance of opposing reaction rates, not by the complete disappearance of reactants.","sol":"Step 1: State the rate condition for equilibrium.\nStep 2: Consider whether both reaction directions can continue.\nStep 3: Determine whether reactants must be completely consumed.","steps":["Step 1: State the rate condition for equilibrium.","Step 2: Consider whether both reaction directions can continue.","Step 3: Determine whether reactants must be completely consumed."],"options":[],"conceptId":"chemistry_reversible_equilibrium_establishing_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q7","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Establishing Equilibrium"}', 6),
  (4325, 949, 'At a particular time, the forward rate is 9 units/s and the reverse rate is 3 units/s. Has equilibrium been established? Explain what the rate difference tells you.', 'text', 1, 'Subtract the reverse rate from the forward rate.', '{"why":"The defining rate condition for equilibrium has not yet been satisfied.","sol":"Step 1: Compare the forward and reverse rates.\nStep 2: Calculate their difference.\nStep 3: Explain whether the opposing rates balance.","steps":["Step 1: Compare the forward and reverse rates.","Step 2: Calculate their difference.","Step 3: Explain whether the opposing rates balance."],"options":[],"conceptId":"chemistry_reversible_equilibrium_establishing_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q8","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Establishing Equilibrium"}', 7),
  (4326, 949, 'At equilibrium, a forward reaction produces 25 units of product per minute and the reverse reaction consumes 25 units per minute. Calculate the net change in product per minute and explain whether the reactions have stopped.', 'text', 1, 'Net change equals amount formed minus amount consumed.', '{"why":"Equal production and consumption rates cause no net concentration change, even though the opposing reactions remain active.","sol":"Step 1: Write the expression for net change.\nStep 2: Substitute the two rates.\nStep 3: Calculate the net change.\nStep 4: Interpret the result in terms of reaction activity.","steps":["Step 1: Write the expression for net change.","Step 2: Substitute the two rates.","Step 3: Calculate the net change.","Step 4: Interpret the result in terms of reaction activity."],"options":[],"conceptId":"chemistry_reversible_equilibrium_establishing_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q9","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Establishing Equilibrium"}', 8),
  (4327, 950, 'For H₂(g) + I₂(g) ⇌ 2HI(g), what happens to the equilibrium position when hydrogen is added at constant temperature?', 'text', 1, 'Focus on the core principle of Effect of Concentration on Equilibrium.', '{"why":"The forward reaction consumes some of the added hydrogen and produces hydrogen iodide.","sol":"Step 1: Identify key concept: Define the required principles for Effect of Concentration on Equilibrium.\nStep 2: Apply governing rule: The forward reaction consumes some of the added hydrogen and produces hydrogen iodide.\nStep 3: State the final conclusion: The equilibrium shifts to the right, favouring the formation of HI.","steps":["Step 1: Identify key concept: Define the required principles for Effect of Concentration on Equilibrium.","Step 2: Apply governing rule: The forward reaction consumes some of the added hydrogen and produces hydrogen iodide.","Step 3: State the final conclusion: The equilibrium shifts to the right, favouring the formation of HI."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_concentration_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q1","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Concentration on Equilibrium"}', 0),
  (4328, 950, 'For N₂(g) + 3H₂(g) ⇌ 2NH₃(g), what is the expected shift when ammonia is removed?', 'text', 1, 'Focus on the core principle of Effect of Concentration on Equilibrium.', '{"why":"Removing a product tends to favour the direction that regenerates some of that product.","sol":"Step 1: Identify key concept: Define the required principles for Effect of Concentration on Equilibrium.\nStep 2: Apply governing rule: Removing a product tends to favour the direction that regenerates some of that product.\nStep 3: State the final conclusion: The equilibrium shifts to the right, towards the formation of ammonia.","steps":["Step 1: Identify key concept: Define the required principles for Effect of Concentration on Equilibrium.","Step 2: Apply governing rule: Removing a product tends to favour the direction that regenerates some of that product.","Step 3: State the final conclusion: The equilibrium shifts to the right, towards the formation of ammonia."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_concentration_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q2","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Concentration on Equilibrium"}', 1),
  (4329, 950, 'At constant temperature, does adding a reactant change the equilibrium constant?', 'text', 1, 'Focus on the core principle of Effect of Concentration on Equilibrium.', '{"why":"The equilibrium constant for a given reaction depends on temperature, not on a temporary change in concentration.","sol":"Step 1: Identify key concept: Define the required principles for Effect of Concentration on Equilibrium.\nStep 2: Apply governing rule: The equilibrium constant for a given reaction depends on temperature, not on a temporary change in concentration.\nStep 3: State the final conclusion: No. It can change the equilibrium position, but the equilibrium constant remains unchanged at the same temperature.","steps":["Step 1: Identify key concept: Define the required principles for Effect of Concentration on Equilibrium.","Step 2: Apply governing rule: The equilibrium constant for a given reaction depends on temperature, not on a temporary change in concentration.","Step 3: State the final conclusion: No. It can change the equilibrium position, but the equilibrium constant remains unchanged at the same temperature."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_concentration_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q3","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Concentration on Equilibrium"}', 2),
  (4330, 950, 'For A + B ⇌ C + D, substance A is added to a mixture at equilibrium. Predict the shift and explain the response.', 'text', 1, 'Identify whether A is a reactant or product and which direction consumes it.', '{"why":"The system responds to the increased reactant concentration by favouring the direction that uses some of that reactant.","sol":"Step 1: Identify A as a reactant.\nStep 2: Recognise that adding A increases its concentration.\nStep 3: Determine which reaction direction consumes A.\nStep 4: State the direction of the net shift.","steps":["Step 1: Identify A as a reactant.","Step 2: Recognise that adding A increases its concentration.","Step 3: Determine which reaction direction consumes A.","Step 4: State the direction of the net shift."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_concentration_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q4","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Concentration on Equilibrium"}', 3),
  (4331, 950, 'For N₂(g) + 3H₂(g) ⇌ 2NH₃(g), nitrogen is removed. Predict the shift and identify which reaction helps replace the nitrogen.', 'text', 1, 'Determine which side of the equation contains nitrogen and which direction produces it.', '{"why":"Removing a reactant favours the direction that tends to replace some of the removed reactant.","sol":"Step 1: Identify nitrogen as a reactant.\nStep 2: Recognise that its concentration decreases when it is removed.\nStep 3: Identify the direction that forms nitrogen.\nStep 4: State the equilibrium shift.","steps":["Step 1: Identify nitrogen as a reactant.","Step 2: Recognise that its concentration decreases when it is removed.","Step 3: Identify the direction that forms nitrogen.","Step 4: State the equilibrium shift."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_concentration_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q5","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Concentration on Equilibrium"}', 4),
  (4332, 950, 'For H₂(g) + I₂(g) ⇌ 2HI(g), hydrogen iodide is removed. A student predicts a shift to the left because a product has been removed. Correct the reasoning.', 'text', 1, 'Ask which direction would produce more HI.', '{"why":"Removing a product favours the direction that forms that product, rather than the direction that consumes it.","sol":"Step 1: Identify HI as a product.\nStep 2: Recognise that its concentration has decreased.\nStep 3: Determine which direction produces HI.\nStep 4: State why that direction is favoured.","steps":["Step 1: Identify HI as a product.","Step 2: Recognise that its concentration has decreased.","Step 3: Determine which direction produces HI.","Step 4: State why that direction is favoured."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_concentration_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q6","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Concentration on Equilibrium"}', 5),
  (4333, 950, 'For A + B ⇌ C + D, product C is added. Explain what happens to the equilibrium position and why.', 'text', 1, 'Consider which direction consumes C.', '{"why":"Adding a product tends to favour the direction that consumes some of that product.","sol":"Step 1: Identify C as a product in the forward direction.\nStep 2: Recognise that adding C increases its concentration.\nStep 3: Identify the reverse direction as the direction that consumes C.\nStep 4: State the expected shift.","steps":["Step 1: Identify C as a product in the forward direction.","Step 2: Recognise that adding C increases its concentration.","Step 3: Identify the reverse direction as the direction that consumes C.","Step 4: State the expected shift."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_concentration_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q7","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Concentration on Equilibrium"}', 6),
  (4334, 950, 'A student adds a reactant to a system at equilibrium and claims that all the added reactant must be consumed before equilibrium can return. Explain why this claim is incorrect.', 'text', 1, 'Distinguish opposing a change from completely undoing it.', '{"why":"An equilibrium shift opposes a disturbance; it does not guarantee that the disturbed concentration returns to its original value.","sol":"Step 1: Identify how the added reactant initially changes its concentration.\nStep 2: Explain the direction favoured by the system.\nStep 3: Consider whether the definition of an equilibrium shift guarantees complete consumption.\nStep 4: State what happens when the new equilibrium is reached.","steps":["Step 1: Identify how the added reactant initially changes its concentration.","Step 2: Explain the direction favoured by the system.","Step 3: Consider whether the definition of an equilibrium shift guarantees complete consumption.","Step 4: State what happens when the new equilibrium is reached."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_concentration_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q8","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Concentration on Equilibrium"}', 7),
  (4335, 950, 'A reaction is at equilibrium at a fixed temperature. A learner adds more reactant and claims that the equilibrium constant must increase because more product will form. Explain the error.', 'text', 1, 'Separate the position of equilibrium from the equilibrium constant.', '{"why":"The equilibrium constant is determined by temperature for a given reaction. A concentration change alters the mixture''s composition and equilibrium position, not the constant.","sol":"Step 1: Identify the change imposed on the mixture.\nStep 2: State how the equilibrium position responds.\nStep 3: Recall what determines the equilibrium constant.\nStep 4: State the correct conclusion at constant temperature.","steps":["Step 1: Identify the change imposed on the mixture.","Step 2: State how the equilibrium position responds.","Step 3: Recall what determines the equilibrium constant.","Step 4: State the correct conclusion at constant temperature."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_concentration_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q9","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Concentration on Equilibrium"}', 8),
  (4336, 951, 'For A + B ⇌ C + D + heat, what happens to the equilibrium position when temperature is increased?', 'text', 1, 'Focus on the core principle of Effect of Temperature on Equilibrium.', '{"why":"The forward reaction is exothermic, so the reverse reaction is the heat-absorbing direction favoured by increasing temperature.","sol":"Step 1: Identify key concept: Define the required principles for Effect of Temperature on Equilibrium.\nStep 2: Apply governing rule: The forward reaction is exothermic, so the reverse reaction is the heat-absorbing direction favoured by increasing temperature.\nStep 3: State the final conclusion: The equilibrium shifts to the left, towards A and B.","steps":["Step 1: Identify key concept: Define the required principles for Effect of Temperature on Equilibrium.","Step 2: Apply governing rule: The forward reaction is exothermic, so the reverse reaction is the heat-absorbing direction favoured by increasing temperature.","Step 3: State the final conclusion: The equilibrium shifts to the left, towards A and B."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_temperature_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q1","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Temperature on Equilibrium"}', 0),
  (4337, 951, 'For A + B + heat ⇌ C + D, what happens when temperature is decreased?', 'text', 1, 'Focus on the core principle of Effect of Temperature on Equilibrium.', '{"why":"The forward reaction is endothermic, so the reverse reaction is exothermic and is favoured by cooling.","sol":"Step 1: Identify key concept: Define the required principles for Effect of Temperature on Equilibrium.\nStep 2: Apply governing rule: The forward reaction is endothermic, so the reverse reaction is exothermic and is favoured by cooling.\nStep 3: State the final conclusion: The equilibrium shifts to the left, towards A and B.","steps":["Step 1: Identify key concept: Define the required principles for Effect of Temperature on Equilibrium.","Step 2: Apply governing rule: The forward reaction is endothermic, so the reverse reaction is exothermic and is favoured by cooling.","Step 3: State the final conclusion: The equilibrium shifts to the left, towards A and B."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_temperature_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q2","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Temperature on Equilibrium"}', 1),
  (4338, 951, 'The forward Haber reaction is exothermic. How does increasing temperature affect the equilibrium yield of ammonia?', 'text', 1, 'Focus on the core principle of Effect of Temperature on Equilibrium.', '{"why":"Increasing temperature favours the endothermic reverse reaction.","sol":"Step 1: Identify key concept: Define the required principles for Effect of Temperature on Equilibrium.\nStep 2: Apply governing rule: Increasing temperature favours the endothermic reverse reaction.\nStep 3: State the final conclusion: It shifts equilibrium towards nitrogen and hydrogen and reduces the equilibrium yield of ammonia.","steps":["Step 1: Identify key concept: Define the required principles for Effect of Temperature on Equilibrium.","Step 2: Apply governing rule: Increasing temperature favours the endothermic reverse reaction.","Step 3: State the final conclusion: It shifts equilibrium towards nitrogen and hydrogen and reduces the equilibrium yield of ammonia."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_temperature_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q3","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Temperature on Equilibrium"}', 2),
  (4339, 951, 'For A + B ⇌ C + D + heat, predict the shift when the temperature is decreased. Explain your reasoning.', 'text', 1, 'Identify which direction releases heat.', '{"why":"Cooling favours the exothermic direction, which in this equation is the forward reaction.","sol":"Step 1: Identify the forward reaction as exothermic because heat is on the product side.\nStep 2: Recall that decreasing temperature favours the heat-releasing direction.\nStep 3: Identify that direction as the forward reaction.\nStep 4: State the equilibrium shift.","steps":["Step 1: Identify the forward reaction as exothermic because heat is on the product side.","Step 2: Recall that decreasing temperature favours the heat-releasing direction.","Step 3: Identify that direction as the forward reaction.","Step 4: State the equilibrium shift."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_temperature_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q4","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Temperature on Equilibrium"}', 3),
  (4340, 951, 'For A + B + heat ⇌ C + D, predict the shift when temperature is increased.', 'text', 1, 'The direction that absorbs heat is the endothermic direction.', '{"why":"Increasing temperature favours the endothermic forward reaction.","sol":"Step 1: Identify the forward reaction as endothermic.\nStep 2: Recognise that increasing temperature favours the heat-absorbing direction.\nStep 3: Identify the forward direction as the direction that absorbs heat.\nStep 4: State the shift.","steps":["Step 1: Identify the forward reaction as endothermic.","Step 2: Recognise that increasing temperature favours the heat-absorbing direction.","Step 3: Identify the forward direction as the direction that absorbs heat.","Step 4: State the shift."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_temperature_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q5","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Temperature on Equilibrium"}', 4),
  (4341, 951, 'A learner says, ''The forward reaction is exothermic, so increasing temperature must shift equilibrium forwards because particles move faster.'' Correct the explanation.', 'text', 1, 'Separate the effect of temperature on reaction rate from its effect on equilibrium position.', '{"why":"A higher reaction rate does not imply a greater equilibrium yield of products. Temperature affects reaction rates and equilibrium position in different ways.","sol":"Step 1: State what increasing temperature generally does to reaction rates.\nStep 2: Identify the heat effect of the forward reaction.\nStep 3: Identify which direction absorbs heat.\nStep 4: Predict the equilibrium shift.","steps":["Step 1: State what increasing temperature generally does to reaction rates.","Step 2: Identify the heat effect of the forward reaction.","Step 3: Identify which direction absorbs heat.","Step 4: Predict the equilibrium shift."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_temperature_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q6","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Temperature on Equilibrium"}', 5),
  (4342, 951, 'The forward reaction in an equilibrium is endothermic. A student predicts that cooling will favour products. Explain the mistake and give the correct prediction.', 'text', 1, 'Determine whether the forward reaction releases or absorbs heat.', '{"why":"The system favours the direction that releases heat when temperature is decreased.","sol":"Step 1: Identify the forward reaction as heat-absorbing.\nStep 2: Recall that cooling favours the heat-releasing direction.\nStep 3: Identify the reverse reaction as exothermic.\nStep 4: State the expected shift.","steps":["Step 1: Identify the forward reaction as heat-absorbing.","Step 2: Recall that cooling favours the heat-releasing direction.","Step 3: Identify the reverse reaction as exothermic.","Step 4: State the expected shift."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_temperature_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q7","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Temperature on Equilibrium"}', 6),
  (4343, 951, 'The forward reaction in a reversible system has ΔH < 0. Predict how increasing and decreasing temperature affect the equilibrium position.', 'text', 1, 'A negative enthalpy change indicates an exothermic forward reaction.', '{"why":"Heating favours the endothermic reverse direction, while cooling favours the exothermic forward direction.","sol":"Step 1: Interpret ΔH < 0 as an exothermic forward reaction.\nStep 2: Identify the reverse reaction as endothermic.\nStep 3: Predict the shift when temperature increases.\nStep 4: Predict the shift when temperature decreases.","steps":["Step 1: Interpret ΔH < 0 as an exothermic forward reaction.","Step 2: Identify the reverse reaction as endothermic.","Step 3: Predict the shift when temperature increases.","Step 4: Predict the shift when temperature decreases."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_temperature_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q8","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Temperature on Equilibrium"}', 7),
  (4344, 951, 'Why can increasing temperature speed up the reactions in a mixture but reduce the equilibrium yield of a product?', 'text', 1, 'Consider the difference between reaction speed and the direction favoured at equilibrium.', '{"why":"Reaction rate describes how quickly change occurs, whereas equilibrium position describes the composition established under the specified conditions.","sol":"Step 1: Explain the general effect of temperature on reaction rates.\nStep 2: Identify whether forming the product is exothermic or endothermic.\nStep 3: Determine which direction is favoured by heating.\nStep 4: Distinguish the rate effect from the equilibrium-yield effect.","steps":["Step 1: Explain the general effect of temperature on reaction rates.","Step 2: Identify whether forming the product is exothermic or endothermic.","Step 3: Determine which direction is favoured by heating.","Step 4: Distinguish the rate effect from the equilibrium-yield effect."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_temperature_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q9","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Temperature on Equilibrium"}', 8),
  (4345, 952, 'For N₂(g) + 3H₂(g) ⇌ 2NH₃(g), predict the effect of increasing pressure at constant temperature.', 'text', 1, 'Focus on the core principle of Effect of Pressure on Equilibrium.', '{"why":"The right-hand side has 2 gaseous moles compared with 4 on the left.","sol":"Step 1: Count the gaseous coefficients on the left: 1 + 3 = 4.\nStep 2: Count the gaseous coefficients on the right: 2.\nStep 3: Identify the side with fewer gaseous moles: the right.\nStep 4: Increasing pressure favours the side with fewer gaseous moles.","steps":["Step 1: Count the gaseous coefficients on the left: 1 + 3 = 4.","Step 2: Count the gaseous coefficients on the right: 2.","Step 3: Identify the side with fewer gaseous moles: the right.","Step 4: Increasing pressure favours the side with fewer gaseous moles."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_pressure_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q1","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Pressure on Equilibrium"}', 0),
  (4346, 952, 'For H₂(g) + I₂(g) ⇌ 2HI(g), explain what happens to the equilibrium position when pressure is decreased at constant temperature.', 'text', 1, 'Focus on the core principle of Effect of Pressure on Equilibrium.', '{"why":"The total number of gaseous moles is equal on both sides.","sol":"Step 1: Count the gaseous moles on the left: 1 + 1 = 2.\nStep 2: Count the gaseous moles on the right: 2.\nStep 3: Compare the totals: both sides have 2 gaseous moles.\nStep 4: A pressure change does not favour either direction through the gaseous mole-count rule.","steps":["Step 1: Count the gaseous moles on the left: 1 + 1 = 2.","Step 2: Count the gaseous moles on the right: 2.","Step 3: Compare the totals: both sides have 2 gaseous moles.","Step 4: A pressure change does not favour either direction through the gaseous mole-count rule."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_pressure_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q2","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Pressure on Equilibrium"}', 1),
  (4347, 952, 'For CaCO₃(s) ⇌ CaO(s) + CO₂(g), explain why increasing pressure favours calcium carbonate.', 'text', 1, 'Focus on the core principle of Effect of Pressure on Equilibrium.', '{"why":"The left side contains fewer gaseous moles; solids do not count in the gas comparison.","sol":"Step 1: Ignore CaCO₃ and CaO because they are solids.\nStep 2: Count the gaseous moles on the left: 0.\nStep 3: Count the gaseous moles on the right: 1 from CO₂.\nStep 4: Increasing pressure favours the side with fewer gaseous moles.","steps":["Step 1: Ignore CaCO₃ and CaO because they are solids.","Step 2: Count the gaseous moles on the left: 0.","Step 3: Count the gaseous moles on the right: 1 from CO₂.","Step 4: Increasing pressure favours the side with fewer gaseous moles."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_pressure_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q3","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Pressure on Equilibrium"}', 2),
  (4348, 952, 'A learner says increasing pressure always shifts equilibrium to the right. Is this correct? Use N₂(g) + 3H₂(g) ⇌ 2NH₃(g) to explain.', 'text', 1, 'The direction depends on gaseous mole totals, not on whether a substance is written on the right.', '{"why":"Pressure favours the side with fewer gaseous moles. That side happens to be the right here, but it is not always the right.","sol":"Step 1: Count the left-hand gaseous moles: 1 + 3 = 4.\nStep 2: Count the right-hand gaseous moles: 2.\nStep 3: Increasing pressure favours the side with fewer gaseous moles.\nStep 4: Identify the side with fewer gaseous moles.","steps":["Step 1: Count the left-hand gaseous moles: 1 + 3 = 4.","Step 2: Count the right-hand gaseous moles: 2.","Step 3: Increasing pressure favours the side with fewer gaseous moles.","Step 4: Identify the side with fewer gaseous moles."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_pressure_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q4","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Pressure on Equilibrium"}', 3),
  (4349, 952, 'For 2SO₂(g) + O₂(g) ⇌ 2SO₃(g), calculate the total gaseous moles on each side and predict the effect of increasing pressure.', 'text', 1, 'Add the coefficients of the gaseous substances on each side.', '{"why":"The product side has fewer gaseous moles than the reactant side.","sol":"Step 1: Left-hand total = 2 + 1 = 3 gaseous moles.\nStep 2: Right-hand total = 2 gaseous moles.\nStep 3: The right-hand side has fewer gaseous moles.\nStep 4: Increasing pressure favours the right-hand side.","steps":["Step 1: Left-hand total = 2 + 1 = 3 gaseous moles.","Step 2: Right-hand total = 2 gaseous moles.","Step 3: The right-hand side has fewer gaseous moles.","Step 4: Increasing pressure favours the right-hand side."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_pressure_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q5","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Pressure on Equilibrium"}', 4),
  (4350, 952, 'For H₂(g) + I₂(g) ⇌ 2HI(g), a student counts four gaseous moles on the left because H₂ and I₂ each contain two atoms. Identify the error and give the correct totals.', 'text', 1, 'Count molecules represented by coefficients, not individual atoms represented by subscripts.', '{"why":"Coefficients give the relative mole amounts in the equation. Subscripts show the atoms within each molecule.","sol":"Step 1: H₂ has coefficient 1, so it contributes 1 mole of gas.\nStep 2: I₂ has coefficient 1, so it contributes 1 mole of gas.\nStep 3: The left total is 1 + 1 = 2.\nStep 4: HI has coefficient 2, so the right total is 2.","steps":["Step 1: H₂ has coefficient 1, so it contributes 1 mole of gas.","Step 2: I₂ has coefficient 1, so it contributes 1 mole of gas.","Step 3: The left total is 1 + 1 = 2.","Step 4: HI has coefficient 2, so the right total is 2."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_pressure_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q6","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Pressure on Equilibrium"}', 5),
  (4351, 952, 'For CaCO₃(s) ⇌ CaO(s) + CO₂(g), predict the effect of decreasing pressure. Explain why the solids are excluded from the calculation.', 'text', 1, 'First count only substances labelled (g). Decreasing pressure favours the side with more gaseous moles.', '{"why":"The right side has one gaseous mole compared with none on the left.","sol":"Step 1: The left side has no gases, so its total is 0.\nStep 2: The right side contains 1 gaseous mole of CO₂.\nStep 3: The right side has more gaseous moles.\nStep 4: Decreasing pressure favours the side with more gaseous moles.","steps":["Step 1: The left side has no gases, so its total is 0.","Step 2: The right side contains 1 gaseous mole of CO₂.","Step 3: The right side has more gaseous moles.","Step 4: Decreasing pressure favours the side with more gaseous moles."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_pressure_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q7","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Pressure on Equilibrium"}', 6),
  (4352, 952, 'A gaseous equilibrium has 3 total gaseous moles on the left and 5 on the right. Predict the effect of decreasing pressure and justify your answer.', 'text', 1, 'Decreasing pressure favours the side with more gaseous moles.', '{"why":"The right-hand side has the greater total number of gaseous moles.","sol":"Step 1: Identify the left-hand total: 3 gaseous moles.\nStep 2: Identify the right-hand total: 5 gaseous moles.\nStep 3: The right side has more gaseous moles.\nStep 4: Decreasing pressure favours the right side.","steps":["Step 1: Identify the left-hand total: 3 gaseous moles.","Step 2: Identify the right-hand total: 5 gaseous moles.","Step 3: The right side has more gaseous moles.","Step 4: Decreasing pressure favours the right side."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_pressure_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q8","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Pressure on Equilibrium"}', 7),
  (4353, 952, 'When the volume of a reaction vessel is reduced at constant temperature, a learner claims that the equilibrium must shift even if both sides contain equal gaseous mole totals. Correct the claim.', 'text', 1, 'Separate the immediate physical effect of reducing volume from a shift in equilibrium position.', '{"why":"A physical pressure change does not necessarily cause a change in equilibrium composition. Equal gaseous mole totals mean neither direction is favoured by the pressure rule.","sol":"Step 1: Reducing volume increases the pressure of the gases immediately.\nStep 2: Compare the total gaseous mole coefficients on both sides.\nStep 3: If the totals are equal, neither direction is favoured by the pressure rule.\nStep 4: State the distinction between a pressure change and a shift in equilibrium.","steps":["Step 1: Reducing volume increases the pressure of the gases immediately.","Step 2: Compare the total gaseous mole coefficients on both sides.","Step 3: If the totals are equal, neither direction is favoured by the pressure rule.","Step 4: State the distinction between a pressure change and a shift in equilibrium."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_pressure_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q9","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Pressure on Equilibrium"}', 8),
  (4354, 953, 'Write the balanced equation for the Haber process and explain why increasing pressure favours ammonia formation.', 'text', 1, 'Focus on the core principle of Industrial Equilibrium.', '{"why":"The reactant side contains 4 gaseous moles and the product side contains 2.","sol":"Step 1: Write the balanced equation: N₂(g) + 3H₂(g) ⇌ 2NH₃(g).\nStep 2: Count gaseous moles on the left: 1 + 3 = 4.\nStep 3: Count gaseous moles on the right: 2.\nStep 4: Increasing pressure favours the side with fewer gaseous moles.","steps":["Step 1: Write the balanced equation: N₂(g) + 3H₂(g) ⇌ 2NH₃(g).","Step 2: Count gaseous moles on the left: 1 + 3 = 4.","Step 3: Count gaseous moles on the right: 2.","Step 4: Increasing pressure favours the side with fewer gaseous moles."],"options":[],"conceptId":"chemistry_reversible_equilibrium_industrial_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q1","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Industrial Equilibrium"}', 0),
  (4355, 953, 'Why is a temperature around 450°C commonly used in the Haber process instead of a very low temperature?', 'text', 1, 'Focus on the core principle of Industrial Equilibrium.', '{"why":"The lowest temperature is not necessarily the most economical choice because the reaction may proceed too slowly.","sol":"Step 1: Identify the forward reaction as exothermic.\nStep 2: Recognise that lower temperature favours ammonia at equilibrium.\nStep 3: Recognise that a very low temperature produces a slow reaction rate.\nStep 4: Explain the need to balance yield and rate.","steps":["Step 1: Identify the forward reaction as exothermic.","Step 2: Recognise that lower temperature favours ammonia at equilibrium.","Step 3: Recognise that a very low temperature produces a slow reaction rate.","Step 4: Explain the need to balance yield and rate."],"options":[],"conceptId":"chemistry_reversible_equilibrium_industrial_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q2","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Industrial Equilibrium"}', 1),
  (4356, 953, 'State the role of the iron catalyst in the Haber process and explain whether it changes the equilibrium yield.', 'text', 1, 'Focus on the core principle of Industrial Equilibrium.', '{"why":"A catalyst changes reaction rates, not the equilibrium composition.","sol":"Step 1: Identify iron as the catalyst.\nStep 2: Explain that a catalyst speeds up the forward reaction.\nStep 3: Explain that it also speeds up the reverse reaction.\nStep 4: State whether the equilibrium position changes.","steps":["Step 1: Identify iron as the catalyst.","Step 2: Explain that a catalyst speeds up the forward reaction.","Step 3: Explain that it also speeds up the reverse reaction.","Step 4: State whether the equilibrium position changes."],"options":[],"conceptId":"chemistry_reversible_equilibrium_industrial_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q3","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Industrial Equilibrium"}', 2),
  (4357, 953, 'For the Haber process, a manager proposes lowering the temperature to increase ammonia yield. Explain both the benefit and the disadvantage.', 'text', 1, 'Use the exothermic nature of the forward reaction, then distinguish equilibrium yield from reaction rate.', '{"why":"Maximising equilibrium yield alone may lead to an uneconomically slow production rate.","sol":"Step 1: The forward Haber reaction is exothermic.\nStep 2: Lower temperature favours the forward direction at equilibrium.\nStep 3: Lower temperature also slows the reaction rate.\nStep 4: Explain why industry must balance yield and production speed.","steps":["Step 1: The forward Haber reaction is exothermic.","Step 2: Lower temperature favours the forward direction at equilibrium.","Step 3: Lower temperature also slows the reaction rate.","Step 4: Explain why industry must balance yield and production speed."],"options":[],"conceptId":"chemistry_reversible_equilibrium_industrial_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q4","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Industrial Equilibrium"}', 3),
  (4358, 953, 'In the Contact process, 2SO₂(g) + O₂(g) ⇌ 2SO₃(g), calculate the gaseous mole totals and predict the effect of increasing pressure.', 'text', 1, 'Add the gaseous coefficients on each side before applying Le Chatelier''s principle.', '{"why":"The product side contains fewer gaseous moles, although the practical benefit of very high pressure must be weighed against cost.","sol":"Step 1: Left-hand total = 2 + 1 = 3 gaseous moles.\nStep 2: Right-hand total = 2 gaseous moles.\nStep 3: Increasing pressure favours the side with fewer gaseous moles.\nStep 4: Identify the product favoured by this shift.","steps":["Step 1: Left-hand total = 2 + 1 = 3 gaseous moles.","Step 2: Right-hand total = 2 gaseous moles.","Step 3: Increasing pressure favours the side with fewer gaseous moles.","Step 4: Identify the product favoured by this shift."],"options":[],"conceptId":"chemistry_reversible_equilibrium_industrial_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q5","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Industrial Equilibrium"}', 4),
  (4359, 953, 'Why is vanadium(V) oxide used in the Contact process, and why does it not increase the equilibrium yield of SO₃ at a fixed temperature?', 'text', 1, 'Separate the effect of a catalyst on reaction rate from its effect on equilibrium composition.', '{"why":"A catalyst provides a faster route to equilibrium but does not favour one direction over the other.","sol":"Step 1: Identify V₂O₅ as the catalyst.\nStep 2: State that it increases the rates of the forward and reverse reactions.\nStep 3: Explain that both reactions are accelerated.\nStep 4: Conclude whether the equilibrium position changes.","steps":["Step 1: Identify V₂O₅ as the catalyst.","Step 2: State that it increases the rates of the forward and reverse reactions.","Step 3: Explain that both reactions are accelerated.","Step 4: Conclude whether the equilibrium position changes."],"options":[],"conceptId":"chemistry_reversible_equilibrium_industrial_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q6","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Industrial Equilibrium"}', 5),
  (4360, 953, 'A student argues that the Contact process should operate at the lowest possible temperature because its forward reaction is exothermic. Explain why this is not the complete industrial answer.', 'text', 1, 'Think about what happens to the reaction rate as temperature decreases.', '{"why":"Industrial decisions must account for both equilibrium composition and production rate.","sol":"Step 1: An exothermic forward reaction is favoured by lower temperature at equilibrium.\nStep 2: A lower temperature generally reduces the reaction rate.\nStep 3: Very slow production is undesirable in an industrial plant.\nStep 4: State the compromise used in practice.","steps":["Step 1: An exothermic forward reaction is favoured by lower temperature at equilibrium.","Step 2: A lower temperature generally reduces the reaction rate.","Step 3: Very slow production is undesirable in an industrial plant.","Step 4: State the compromise used in practice."],"options":[],"conceptId":"chemistry_reversible_equilibrium_industrial_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q7","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Industrial Equilibrium"}', 6),
  (4361, 953, 'Compare the pressure effect in the Haber process and Contact process. Explain why increasing pressure favours the desired product in both.', 'text', 1, 'Compare the gaseous mole totals on the reactant and product sides of each balanced equation.', '{"why":"Both equilibria shift towards the side with fewer gaseous particles when pressure increases at constant temperature.","sol":"Step 1: For Haber, count 4 gaseous moles on the left and 2 on the right.\nStep 2: For Contact, count 3 gaseous moles on the left and 2 on the right.\nStep 3: In both processes, the product side has fewer gaseous moles.\nStep 4: Apply the rule for increasing pressure to both reactions.","steps":["Step 1: For Haber, count 4 gaseous moles on the left and 2 on the right.","Step 2: For Contact, count 3 gaseous moles on the left and 2 on the right.","Step 3: In both processes, the product side has fewer gaseous moles.","Step 4: Apply the rule for increasing pressure to both reactions."],"options":[],"conceptId":"chemistry_reversible_equilibrium_industrial_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q8","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Industrial Equilibrium"}', 7),
  (4362, 953, 'A factory removes ammonia as it forms in the Haber process. Explain how this can increase further ammonia production, and distinguish this from the effect of a catalyst.', 'text', 1, 'Removing a product and adding a catalyst are two different disturbances; explain what each changes.', '{"why":"Product removal changes the system''s composition; a catalyst changes reaction rates rather than equilibrium composition.","sol":"Step 1: Removing ammonia lowers the amount of product in the reacting system.\nStep 2: The equilibrium responds by favouring the forward reaction to replace some of the removed ammonia.\nStep 3: A catalyst speeds up both forward and reverse reactions.\nStep 4: State which action shifts equilibrium and which action only speeds up attainment of equilibrium.","steps":["Step 1: Removing ammonia lowers the amount of product in the reacting system.","Step 2: The equilibrium responds by favouring the forward reaction to replace some of the removed ammonia.","Step 3: A catalyst speeds up both forward and reverse reactions.","Step 4: State which action shifts equilibrium and which action only speeds up attainment of equilibrium."],"options":[],"conceptId":"chemistry_reversible_equilibrium_industrial_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q9","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Industrial Equilibrium"}', 8),
  (4363, 954, 'What does collision theory state about chemical reactions?', 'text', 1, 'Focus on the core principle of Collision Theory.', '{"why":"Collision theory explains that reactions occur when particles make suitable collisions.","sol":"Step 1: Chemical particles must collide for a reaction to occur.\nStep 2: The particles must have sufficient energy.\nStep 3: The particles must collide in a suitable orientation.\nStep 4: Therefore, only suitable collisions can produce a chemical reaction.","steps":["Step 1: Chemical particles must collide for a reaction to occur.","Step 2: The particles must have sufficient energy.","Step 3: The particles must collide in a suitable orientation.","Step 4: Therefore, only suitable collisions can produce a chemical reaction."],"options":[],"conceptId":"chemistry_rate_reactions_collision_theory","skillId":"chemistry_rate_reactions","subskillId":"chemistry_rate_reactions_q1","subject":"chemistry","chapter":"rate_reactions","topic":"Collision Theory"}', 0),
  (4364, 954, 'Why does every collision between reacting particles not produce a reaction?', 'text', 1, 'Focus on the core principle of Collision Theory.', '{"why":"Only collisions satisfying the required energy and orientation conditions can produce products.","sol":"Step 1: A collision must provide enough energy to overcome the reaction barrier.\nStep 2: The particles must also have a suitable orientation.\nStep 3: A collision lacking either requirement is unsuccessful.","steps":["Step 1: A collision must provide enough energy to overcome the reaction barrier.","Step 2: The particles must also have a suitable orientation.","Step 3: A collision lacking either requirement is unsuccessful."],"options":[],"conceptId":"chemistry_rate_reactions_collision_theory","skillId":"chemistry_rate_reactions","subskillId":"chemistry_rate_reactions_q2","subject":"chemistry","chapter":"rate_reactions","topic":"Collision Theory"}', 1),
  (4365, 954, 'What happens to the rate of reaction when the number of effective collisions per second increases?', 'text', 1, 'Focus on the core principle of Collision Theory.', '{"why":"Reaction rate depends on how frequently effective collisions occur.","sol":"Step 1: Effective collisions produce chemical reactions.\nStep 2: More effective collisions occur in the same amount of time.\nStep 3: More reactant particles are converted into products per second.","steps":["Step 1: Effective collisions produce chemical reactions.","Step 2: More effective collisions occur in the same amount of time.","Step 3: More reactant particles are converted into products per second."],"options":[],"conceptId":"chemistry_rate_reactions_collision_theory","skillId":"chemistry_rate_reactions","subskillId":"chemistry_rate_reactions_q3","subject":"chemistry","chapter":"rate_reactions","topic":"Collision Theory"}', 2),
  (4366, 954, 'A reaction mixture contains particles that collide frequently, but most collisions do not result in products. Give two possible reasons.', 'text', 1, 'Think about the two requirements for an effective collision.', '{"why":"Both sufficient energy and suitable orientation are required for an effective collision.","sol":"Step 1: Check whether the particles have sufficient energy.\nStep 2: Check whether they collide in a suitable orientation.\nStep 3: If either requirement is missing, the collision will not be effective.","steps":["Step 1: Check whether the particles have sufficient energy.","Step 2: Check whether they collide in a suitable orientation.","Step 3: If either requirement is missing, the collision will not be effective."],"options":[],"conceptId":"chemistry_rate_reactions_collision_theory","skillId":"chemistry_rate_reactions","subskillId":"chemistry_rate_reactions_q4","subject":"chemistry","chapter":"rate_reactions","topic":"Collision Theory"}', 3),
  (4367, 955, 'What is activation energy?', 'text', 1, 'Focus on the core principle of Activation Energy.', '{"why":"Particles with energy below the activation energy cannot undergo a successful reaction during the collision.","sol":"Step 1: Particles need a minimum amount of energy for a reaction to occur.\nStep 2: This minimum energy is called activation energy.\nStep 3: It is represented by Eₐ.","steps":["Step 1: Particles need a minimum amount of energy for a reaction to occur.","Step 2: This minimum energy is called activation energy.","Step 3: It is represented by Eₐ."],"options":[],"conceptId":"chemistry_rate_reactions_activation_energy","skillId":"chemistry_rate_reactions","subskillId":"chemistry_rate_reactions_q1","subject":"chemistry","chapter":"rate_reactions","topic":"Activation Energy"}', 0),
  (4368, 955, 'A reacting particle has 45 kJ of energy while the activation energy is 60 kJ. Can this particle produce a successful collision based on energy alone?', 'text', 1, 'Focus on the core principle of Activation Energy.', '{"why":"The particle must have at least the activation energy for a successful collision.","sol":"Step 1: Particle energy = 45 kJ.\nStep 2: Activation energy = 60 kJ.\nStep 3: Compare the two values: 45 kJ < 60 kJ.\nStep 4: The particle does not have enough energy.","steps":["Step 1: Particle energy = 45 kJ.","Step 2: Activation energy = 60 kJ.","Step 3: Compare the two values: 45 kJ < 60 kJ.","Step 4: The particle does not have enough energy."],"options":[],"conceptId":"chemistry_rate_reactions_activation_energy","skillId":"chemistry_rate_reactions","subskillId":"chemistry_rate_reactions_q2","subject":"chemistry","chapter":"rate_reactions","topic":"Activation Energy"}', 1),
  (4369, 955, 'The activation energy of a reaction is 80 kJ. A particle has 95 kJ of energy. Is the particle energetic enough to overcome the activation energy?', 'text', 1, 'Focus on the core principle of Activation Energy.', '{"why":"95 kJ is greater than the required 80 kJ.","sol":"Step 1: Particle energy = 95 kJ.\nStep 2: Activation energy = 80 kJ.\nStep 3: Compare: 95 kJ > 80 kJ.\nStep 4: The particle has enough energy to overcome the activation energy.","steps":["Step 1: Particle energy = 95 kJ.","Step 2: Activation energy = 80 kJ.","Step 3: Compare: 95 kJ > 80 kJ.","Step 4: The particle has enough energy to overcome the activation energy."],"options":[],"conceptId":"chemistry_rate_reactions_activation_energy","skillId":"chemistry_rate_reactions","subskillId":"chemistry_rate_reactions_q3","subject":"chemistry","chapter":"rate_reactions","topic":"Activation Energy"}', 2),
  (4370, 955, 'A reaction has an activation energy of 75 kJ. A particle has 70 kJ of energy. How much additional energy does it need to reach the activation energy?', 'text', 1, 'Subtract the particle''s energy from the activation energy.', '{"why":"The particle is 5 kJ below the activation energy.","sol":"Step 1: Activation energy = 75 kJ.\nStep 2: Particle energy = 70 kJ.\nStep 3: Additional energy = 75 − 70.\nStep 4: Additional energy = 5 kJ.","steps":["Step 1: Activation energy = 75 kJ.","Step 2: Particle energy = 70 kJ.","Step 3: Additional energy = 75 − 70.","Step 4: Additional energy = 5 kJ."],"options":[],"conceptId":"chemistry_rate_reactions_activation_energy","skillId":"chemistry_rate_reactions","subskillId":"chemistry_rate_reactions_q4","subject":"chemistry","chapter":"rate_reactions","topic":"Activation Energy"}', 3),
  (4371, 956, 'What is an effective collision?', 'text', 1, 'Focus on the core principle of Effective Collisions.', '{"why":"Only collisions satisfying the necessary energy and orientation conditions can form products.","sol":"Step 1: Reacting particles collide.\nStep 2: The particles must have sufficient energy.\nStep 3: The particles must have suitable orientation.\nStep 4: If these conditions result in reaction, the collision is effective.","steps":["Step 1: Reacting particles collide.","Step 2: The particles must have sufficient energy.","Step 3: The particles must have suitable orientation.","Step 4: If these conditions result in reaction, the collision is effective."],"options":[],"conceptId":"chemistry_rate_reactions_effective_collisions","skillId":"chemistry_rate_reactions","subskillId":"chemistry_rate_reactions_q1","subject":"chemistry","chapter":"rate_reactions","topic":"Effective Collisions"}', 0),
  (4372, 956, 'Why does increasing temperature usually increase the rate of a chemical reaction?', 'text', 1, 'Focus on the core principle of Effective Collisions.', '{"why":"More particles have sufficient energy to overcome the activation energy.","sol":"Step 1: Increasing temperature gives particles more kinetic energy.\nStep 2: Particles move faster and collide more frequently.\nStep 3: A greater fraction of particles have energy equal to or greater than the activation energy.\nStep 4: The number of effective collisions per second increases.","steps":["Step 1: Increasing temperature gives particles more kinetic energy.","Step 2: Particles move faster and collide more frequently.","Step 3: A greater fraction of particles have energy equal to or greater than the activation energy.","Step 4: The number of effective collisions per second increases."],"options":[],"conceptId":"chemistry_rate_reactions_effective_collisions","skillId":"chemistry_rate_reactions","subskillId":"chemistry_rate_reactions_q2","subject":"chemistry","chapter":"rate_reactions","topic":"Effective Collisions"}', 1),
  (4373, 956, 'How does a catalyst increase the rate of a reaction?', 'text', 1, 'Focus on the core principle of Effective Collisions.', '{"why":"Lower activation energy allows more collisions to become effective.","sol":"Step 1: A catalyst provides an alternative reaction pathway.\nStep 2: The alternative pathway has a lower activation energy.\nStep 3: More particles can reach the required energy.\nStep 4: The number of effective collisions increases.","steps":["Step 1: A catalyst provides an alternative reaction pathway.","Step 2: The alternative pathway has a lower activation energy.","Step 3: More particles can reach the required energy.","Step 4: The number of effective collisions increases."],"options":[],"conceptId":"chemistry_rate_reactions_effective_collisions","skillId":"chemistry_rate_reactions","subskillId":"chemistry_rate_reactions_q3","subject":"chemistry","chapter":"rate_reactions","topic":"Effective Collisions"}', 2),
  (4374, 956, 'A reaction is slow because only a small fraction of collisions have enough energy to react. What change could increase the number of effective collisions without changing the reactants?', 'text', 1, 'Think about a factor that lowers the energy barrier.', '{"why":"A catalyst lowers the activation energy and increases the proportion of effective collisions.","sol":"Step 1: The problem is that too few particles have enough energy to react.\nStep 2: A catalyst provides an alternative pathway.\nStep 3: The alternative pathway has lower activation energy.\nStep 4: More collisions can therefore become effective.","steps":["Step 1: The problem is that too few particles have enough energy to react.","Step 2: A catalyst provides an alternative pathway.","Step 3: The alternative pathway has lower activation energy.","Step 4: More collisions can therefore become effective."],"options":[],"conceptId":"chemistry_rate_reactions_effective_collisions","skillId":"chemistry_rate_reactions","subskillId":"chemistry_rate_reactions_q4","subject":"chemistry","chapter":"rate_reactions","topic":"Effective Collisions"}', 3),
  (4375, 957, 'Explain why breaking a covalent bond requires energy.', 'text', 1, 'Focus on the core principle of Breaking Bonds.', '{"why":"The energy input is needed to overcome the attractive interaction associated with the bond.","sol":"Step 1: A covalent bond holds atoms together through an attractive interaction.\nStep 2: The bonded atoms must be separated when the bond breaks.\nStep 3: Energy must be supplied to overcome the interaction holding them together.\nStep 4: Therefore, bond breaking absorbs energy.","steps":["Step 1: A covalent bond holds atoms together through an attractive interaction.","Step 2: The bonded atoms must be separated when the bond breaks.","Step 3: Energy must be supplied to overcome the interaction holding them together.","Step 4: Therefore, bond breaking absorbs energy."],"options":[],"conceptId":"chemistry_chemical_energetics_breaking_bonds","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q1","subject":"chemistry","chapter":"chemical_energetics","topic":"Breaking Bonds"}', 0),
  (4376, 957, 'An H–H bond has a bond energy of 436 kJ/mol. What does this value mean?', 'text', 1, 'Focus on the core principle of Breaking Bonds.', '{"why":"Bond energy is expressed per mole of the specified bonds, rather than per entire reaction.","sol":"Step 1: Identify the unit: kJ/mol means kilojoules per mole.\nStep 2: Identify the specified bond: H–H.\nStep 3: Interpret the value as the energy required to break one mole of H–H bonds in gaseous hydrogen molecules.","steps":["Step 1: Identify the unit: kJ/mol means kilojoules per mole.","Step 2: Identify the specified bond: H–H.","Step 3: Interpret the value as the energy required to break one mole of H–H bonds in gaseous hydrogen molecules."],"options":[],"conceptId":"chemistry_chemical_energetics_breaking_bonds","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q2","subject":"chemistry","chapter":"chemical_energetics","topic":"Breaking Bonds"}', 1),
  (4377, 957, 'Bond A has a bond energy of 350 kJ/mol and bond B has a bond energy of 600 kJ/mol. Which requires more energy to break one mole of bonds, and by how much?', 'text', 1, 'Focus on the core principle of Breaking Bonds.', '{"why":"The higher bond energy indicates that more energy is required to break the specified bonds.","sol":"Step 1: Compare the two bond energies: 600 kJ/mol and 350 kJ/mol.\nStep 2: Bond B has the higher bond energy.\nStep 3: Calculate the difference: 600 − 350 = 250 kJ/mol.","steps":["Step 1: Compare the two bond energies: 600 kJ/mol and 350 kJ/mol.","Step 2: Bond B has the higher bond energy.","Step 3: Calculate the difference: 600 − 350 = 250 kJ/mol."],"options":[],"conceptId":"chemistry_chemical_energetics_breaking_bonds","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q3","subject":"chemistry","chapter":"chemical_energetics","topic":"Breaking Bonds"}', 2),
  (4378, 957, 'Calculate the energy required to break 2 mol of bonds if the bond energy is 410 kJ/mol.', 'text', 1, 'Multiply the amount of bonds by the bond energy.', '{"why":"Each mole requires 410 kJ, so breaking 2 mol requires 2 × 410 = 820 kJ.","sol":"Step 1: Write the formula: E = n × BE.\nStep 2: Substitute: E = 2 × 410.\nStep 3: Calculate: E = 820 kJ.\nStep 4: State the direction of energy transfer.","steps":["Step 1: Write the formula: E = n × BE.","Step 2: Substitute: E = 2 × 410.","Step 3: Calculate: E = 820 kJ.","Step 4: State the direction of energy transfer."],"options":[],"conceptId":"chemistry_chemical_energetics_breaking_bonds","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q4","subject":"chemistry","chapter":"chemical_energetics","topic":"Breaking Bonds"}', 3),
  (4379, 957, 'A learner says that a bond energy of 520 kJ/mol means 520 kJ is needed to break one bond. Correct the statement.', 'text', 1, 'Pay attention to the words represented by the unit kJ/mol.', '{"why":"The denominator mol indicates that the energy value applies to a mole of bonds.","sol":"Step 1: Recognise that kJ/mol means energy per mole.\nStep 2: Identify the specified quantity as one mole of bonds.\nStep 3: Explain that the value is not the energy for a single bond.","steps":["Step 1: Recognise that kJ/mol means energy per mole.","Step 2: Identify the specified quantity as one mole of bonds.","Step 3: Explain that the value is not the energy for a single bond."],"options":[],"conceptId":"chemistry_chemical_energetics_breaking_bonds","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q5","subject":"chemistry","chapter":"chemical_energetics","topic":"Breaking Bonds"}', 4),
  (4380, 957, 'Calculate the energy required to break 0.5 mol of bonds with a bond energy of 600 kJ/mol.', 'text', 1, 'Use E = n × BE, remembering that 0.5 mol is half a mole.', '{"why":"Half a mole requires half the energy needed to break one mole of the same bonds.","sol":"Step 1: Bond energy = 600 kJ/mol.\nStep 2: Amount of bonds = 0.5 mol.\nStep 3: Energy = 0.5 × 600.\nStep 4: Energy = 300 kJ.","steps":["Step 1: Bond energy = 600 kJ/mol.","Step 2: Amount of bonds = 0.5 mol.","Step 3: Energy = 0.5 × 600.","Step 4: Energy = 300 kJ."],"options":[],"conceptId":"chemistry_chemical_energetics_breaking_bonds","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q6","subject":"chemistry","chapter":"chemical_energetics","topic":"Breaking Bonds"}', 5),
  (4381, 957, 'A reaction step requires 720 kJ to break 2 mol of identical bonds. Calculate the bond energy per mole.', 'text', 1, 'Rearrange E = n × BE to make BE the subject.', '{"why":"The total energy is divided by the number of moles of bonds to obtain energy per mole.","sol":"Step 1: Write E = n × BE.\nStep 2: Rearrange: BE = E ÷ n.\nStep 3: Substitute: BE = 720 ÷ 2.\nStep 4: Calculate: BE = 360 kJ/mol.","steps":["Step 1: Write E = n × BE.","Step 2: Rearrange: BE = E ÷ n.","Step 3: Substitute: BE = 720 ÷ 2.","Step 4: Calculate: BE = 360 kJ/mol."],"options":[],"conceptId":"chemistry_chemical_energetics_breaking_bonds","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q7","subject":"chemistry","chapter":"chemical_energetics","topic":"Breaking Bonds"}', 6),
  (4382, 957, 'A learner claims that breaking a stronger bond releases more energy because the bond contains more energy. Explain why the claim is incorrect.', 'text', 1, 'Focus on the energy transfer required to separate bonded atoms.', '{"why":"Bond energy describes the energy required for bond breaking, not energy released during bond breaking.","sol":"Step 1: A higher bond energy means more energy is required to break the bond.\nStep 2: Breaking a bond requires energy to be supplied.\nStep 3: Therefore, breaking a stronger bond absorbs more energy rather than releasing it.","steps":["Step 1: A higher bond energy means more energy is required to break the bond.","Step 2: Breaking a bond requires energy to be supplied.","Step 3: Therefore, breaking a stronger bond absorbs more energy rather than releasing it."],"options":[],"conceptId":"chemistry_chemical_energetics_breaking_bonds","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q8","subject":"chemistry","chapter":"chemical_energetics","topic":"Breaking Bonds"}', 7),
  (4383, 957, 'How much energy is required to break 4 mol of bonds if breaking 1 mol requires 275 kJ? Show your calculation and state whether energy is absorbed or released.', 'text', 1, 'Multiply 275 kJ/mol by 4 mol and identify the direction of energy transfer.', '{"why":"Four moles require four times the energy required for one mole of the same bonds.","sol":"Step 1: Bond energy = 275 kJ/mol.\nStep 2: Amount of bonds = 4 mol.\nStep 3: Energy = 4 × 275.\nStep 4: Energy = 1100 kJ.\nStep 5: Bond breaking absorbs energy.","steps":["Step 1: Bond energy = 275 kJ/mol.","Step 2: Amount of bonds = 4 mol.","Step 3: Energy = 4 × 275.","Step 4: Energy = 1100 kJ.","Step 5: Bond breaking absorbs energy."],"options":[],"conceptId":"chemistry_chemical_energetics_breaking_bonds","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q9","subject":"chemistry","chapter":"chemical_energetics","topic":"Breaking Bonds"}', 8),
  (4384, 958, 'What happens to energy when two separate hydrogen atoms form an H–H bond?', 'text', 1, 'Focus on the core principle of Making Bonds.', '{"why":"Bond formation produces a lower-energy bonded arrangement, releasing the energy difference.","sol":"Step 1: Two separate gaseous hydrogen atoms approach one another.\nStep 2: An H–H covalent bond forms.\nStep 3: The bonded molecule has a lower energy than the separated atoms.\nStep 4: The energy difference is released to the surroundings.","steps":["Step 1: Two separate gaseous hydrogen atoms approach one another.","Step 2: An H–H covalent bond forms.","Step 3: The bonded molecule has a lower energy than the separated atoms.","Step 4: The energy difference is released to the surroundings."],"options":[],"conceptId":"chemistry_chemical_energetics_making_bonds","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q1","subject":"chemistry","chapter":"chemical_energetics","topic":"Making Bonds"}', 0),
  (4385, 958, 'A specified bond has a bond energy of 500 kJ/mol. Approximately how much energy is released when 1 mol of these bonds forms?', 'text', 1, 'Focus on the core principle of Making Bonds.', '{"why":"For the corresponding bond-formation process, the magnitude of the energy released is approximately equal to the bond energy.","sol":"Step 1: Bond energy = 500 kJ/mol.\nStep 2: Amount of bonds formed = 1 mol.\nStep 3: Energy released = 1 × 500.\nStep 4: Energy released = 500 kJ.","steps":["Step 1: Bond energy = 500 kJ/mol.","Step 2: Amount of bonds formed = 1 mol.","Step 3: Energy released = 1 × 500.","Step 4: Energy released = 500 kJ."],"options":[],"conceptId":"chemistry_chemical_energetics_making_bonds","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q2","subject":"chemistry","chapter":"chemical_energetics","topic":"Making Bonds"}', 1),
  (4386, 958, 'Explain why the energy change associated with forming a bond is opposite in direction to that associated with breaking the same bond.', 'text', 1, 'Focus on the core principle of Making Bonds.', '{"why":"The two processes are opposite changes between the separated and bonded arrangements.","sol":"Step 1: Breaking a bond requires energy to separate the bonded atoms.\nStep 2: Forming the corresponding bond brings the atoms into a lower-energy bonded arrangement.\nStep 3: The energy absorbed during breaking is therefore released during the reverse formation process, for the same corresponding states.","steps":["Step 1: Breaking a bond requires energy to separate the bonded atoms.","Step 2: Forming the corresponding bond brings the atoms into a lower-energy bonded arrangement.","Step 3: The energy absorbed during breaking is therefore released during the reverse formation process, for the same corresponding states."],"options":[],"conceptId":"chemistry_chemical_energetics_making_bonds","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q3","subject":"chemistry","chapter":"chemical_energetics","topic":"Making Bonds"}', 2),
  (4387, 958, 'Forming 4 mol of a specified type of bond releases 300 kJ/mol. Calculate the total energy released.', 'text', 1, 'Multiply the amount of bonds formed by the energy released per mole.', '{"why":"Each mole releases 300 kJ, so four moles release 4 × 300 = 1200 kJ.","sol":"Step 1: Amount of bonds formed = 4 mol.\nStep 2: Energy released per mole = 300 kJ/mol.\nStep 3: Total energy released = 4 × 300.\nStep 4: Total energy released = 1200 kJ.","steps":["Step 1: Amount of bonds formed = 4 mol.","Step 2: Energy released per mole = 300 kJ/mol.","Step 3: Total energy released = 4 × 300.","Step 4: Total energy released = 1200 kJ."],"options":[],"conceptId":"chemistry_chemical_energetics_making_bonds","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q4","subject":"chemistry","chapter":"chemical_energetics","topic":"Making Bonds"}', 3),
  (4388, 958, 'A learner says, ''A bond energy of 420 kJ/mol means that forming one mole of the bonds absorbs 420 kJ.'' Correct the statement.', 'text', 1, 'Distinguish the direction of energy transfer during bond breaking from that during bond formation.', '{"why":"Bond formation releases energy because the bonded arrangement has a lower energy than the separated atoms.","sol":"Step 1: Bond energy conventionally represents the energy required to break a specified bond.\nStep 2: Breaking one mole of these bonds absorbs approximately 420 kJ.\nStep 3: Forming the corresponding bonds reverses the process.\nStep 4: Therefore, forming one mole releases approximately 420 kJ.","steps":["Step 1: Bond energy conventionally represents the energy required to break a specified bond.","Step 2: Breaking one mole of these bonds absorbs approximately 420 kJ.","Step 3: Forming the corresponding bonds reverses the process.","Step 4: Therefore, forming one mole releases approximately 420 kJ."],"options":[],"conceptId":"chemistry_chemical_energetics_making_bonds","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q5","subject":"chemistry","chapter":"chemical_energetics","topic":"Making Bonds"}', 4),
  (4389, 958, 'Bond A has a bond energy of 350 kJ/mol and bond B has a bond energy of 600 kJ/mol. Which releases more energy per mole when formed, and what is the difference?', 'text', 1, 'For corresponding bond-formation processes, compare the magnitudes of the bond energies.', '{"why":"The higher bond energy corresponds to a greater energy release when the corresponding bonds form.","sol":"Step 1: Bond A releases approximately 350 kJ/mol when formed.\nStep 2: Bond B releases approximately 600 kJ/mol when formed.\nStep 3: Difference = 600 − 350.\nStep 4: Difference = 250 kJ/mol.","steps":["Step 1: Bond A releases approximately 350 kJ/mol when formed.","Step 2: Bond B releases approximately 600 kJ/mol when formed.","Step 3: Difference = 600 − 350.","Step 4: Difference = 250 kJ/mol."],"options":[],"conceptId":"chemistry_chemical_energetics_making_bonds","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q6","subject":"chemistry","chapter":"chemical_energetics","topic":"Making Bonds"}', 5),
  (4390, 958, 'A reaction forms 2 mol of a specified bond, releasing 180 kJ/mol. Calculate the total energy released and explain why the result is positive as an amount of energy released.', 'text', 1, 'Calculate the magnitude first, then state the direction of energy transfer.', '{"why":"The calculated amount is the magnitude of the energy released. If expressed as the enthalpy change of the bond-formation process, the sign would be negative for the corresponding states.","sol":"Step 1: Amount of bonds formed = 2 mol.\nStep 2: Energy released per mole = 180 kJ/mol.\nStep 3: Total released = 2 × 180 = 360 kJ.\nStep 4: State that the energy leaves the reacting system and is transferred to the surroundings.","steps":["Step 1: Amount of bonds formed = 2 mol.","Step 2: Energy released per mole = 180 kJ/mol.","Step 3: Total released = 2 × 180 = 360 kJ.","Step 4: State that the energy leaves the reacting system and is transferred to the surroundings."],"options":[],"conceptId":"chemistry_chemical_energetics_making_bonds","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q7","subject":"chemistry","chapter":"chemical_energetics","topic":"Making Bonds"}', 6),
  (4391, 958, 'A learner claims that because a reaction forms new bonds, the reaction must release energy overall. Explain why this conclusion is not justified.', 'text', 1, 'Consider the energy required to break reactant bonds as well as the energy released when product bonds form.', '{"why":"Most reactions involve both bond breaking and bond formation, so the overall energy change depends on their balance.","sol":"Step 1: Breaking bonds in the reactants absorbs energy.\nStep 2: Forming bonds in the products releases energy.\nStep 3: Compare the total energy absorbed with the total energy released.\nStep 4: The overall result depends on which total is greater.","steps":["Step 1: Breaking bonds in the reactants absorbs energy.","Step 2: Forming bonds in the products releases energy.","Step 3: Compare the total energy absorbed with the total energy released.","Step 4: The overall result depends on which total is greater."],"options":[],"conceptId":"chemistry_chemical_energetics_making_bonds","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q8","subject":"chemistry","chapter":"chemical_energetics","topic":"Making Bonds"}', 7),
  (4392, 958, 'Forming 0.5 mol of a specified bond releases 720 kJ per mole of bonds formed. Calculate the energy released and state what happens if the same amount of bonds is broken instead.', 'text', 1, 'First calculate 0.5 × 720. Then reverse the direction of energy transfer for bond breaking.', '{"why":"The corresponding bond-formation and bond-breaking processes have opposite energy-transfer directions.","sol":"Step 1: Energy released = amount of bonds × energy per mole.\nStep 2: Energy released = 0.5 × 720 = 360 kJ.\nStep 3: Bond formation releases 360 kJ.\nStep 4: Breaking the same amount of corresponding bonds requires 360 kJ to be absorbed, under the same convention.","steps":["Step 1: Energy released = amount of bonds × energy per mole.","Step 2: Energy released = 0.5 × 720 = 360 kJ.","Step 3: Bond formation releases 360 kJ.","Step 4: Breaking the same amount of corresponding bonds requires 360 kJ to be absorbed, under the same convention."],"options":[],"conceptId":"chemistry_chemical_energetics_making_bonds","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q9","subject":"chemistry","chapter":"chemical_energetics","topic":"Making Bonds"}', 8),
  (4393, 959, 'State the formula used to estimate a reaction''s enthalpy change from bond energies.', 'text', 1, 'Focus on the core principle of Bond Energy Calculations.', '{"why":"Breaking bonds absorbs energy, while forming bonds releases energy.","sol":"Step 1: Identify the total energy absorbed breaking reactant bonds.\nStep 2: Identify the total energy released forming product bonds.\nStep 3: Subtract the second total from the first.","steps":["Step 1: Identify the total energy absorbed breaking reactant bonds.","Step 2: Identify the total energy released forming product bonds.","Step 3: Subtract the second total from the first."],"options":[],"conceptId":"chemistry_chemical_energetics_bond_energy_calculations","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q1","subject":"chemistry","chapter":"chemical_energetics","topic":"Bond Energy Calculations"}', 0),
  (4394, 959, 'A reaction absorbs 750 kJ breaking bonds and releases 950 kJ forming bonds. Calculate ΔH and classify the reaction.', 'text', 1, 'Focus on the core principle of Bond Energy Calculations.', '{"why":"More energy is released during bond formation than is absorbed during bond breaking.","sol":"Step 1: Energy absorbed = 750 kJ.\nStep 2: Energy released = 950 kJ.\nStep 3: ΔH ≈ 750 − 950.\nStep 4: ΔH ≈ −200 kJ.","steps":["Step 1: Energy absorbed = 750 kJ.","Step 2: Energy released = 950 kJ.","Step 3: ΔH ≈ 750 − 950.","Step 4: ΔH ≈ −200 kJ."],"options":[],"conceptId":"chemistry_chemical_energetics_bond_energy_calculations","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q2","subject":"chemistry","chapter":"chemical_energetics","topic":"Bond Energy Calculations"}', 1),
  (4395, 959, 'For H₂(g) + Cl₂(g) → 2HCl(g), use H–H = 436 kJ/mol, Cl–Cl = 243 kJ/mol and H–Cl = 431 kJ/mol to estimate ΔH.', 'text', 1, 'Focus on the core principle of Bond Energy Calculations.', '{"why":"The reaction is exothermic because the energy released forming two H–Cl bonds exceeds the energy absorbed breaking the reactant bonds.","sol":"Step 1: Bonds broken: one H–H and one Cl–Cl.\nStep 2: Energy absorbed = 436 + 243 = 679 kJ.\nStep 3: Bonds formed: two H–Cl bonds.\nStep 4: Energy released = 2 × 431 = 862 kJ.\nStep 5: ΔH ≈ 679 − 862 = −183 kJ.","steps":["Step 1: Bonds broken: one H–H and one Cl–Cl.","Step 2: Energy absorbed = 436 + 243 = 679 kJ.","Step 3: Bonds formed: two H–Cl bonds.","Step 4: Energy released = 2 × 431 = 862 kJ.","Step 5: ΔH ≈ 679 − 862 = −183 kJ."],"options":[],"conceptId":"chemistry_chemical_energetics_bond_energy_calculations","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q3","subject":"chemistry","chapter":"chemical_energetics","topic":"Bond Energy Calculations"}', 2),
  (4396, 959, 'The energy of bonds broken is 1650 kJ and the energy of bonds formed is 1900 kJ. Calculate ΔH and state the reaction type.', 'text', 1, 'Subtract the total for bonds formed from the total for bonds broken.', '{"why":"The energy released forming bonds exceeds the energy absorbed breaking bonds.","sol":"Step 1: Write ΔH ≈ bonds broken − bonds formed.\nStep 2: Substitute: ΔH ≈ 1650 − 1900.\nStep 3: Calculate: ΔH ≈ −250 kJ.\nStep 4: A negative ΔH indicates an exothermic reaction.","steps":["Step 1: Write ΔH ≈ bonds broken − bonds formed.","Step 2: Substitute: ΔH ≈ 1650 − 1900.","Step 3: Calculate: ΔH ≈ −250 kJ.","Step 4: A negative ΔH indicates an exothermic reaction."],"options":[],"conceptId":"chemistry_chemical_energetics_bond_energy_calculations","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q4","subject":"chemistry","chapter":"chemical_energetics","topic":"Bond Energy Calculations"}', 3),
  (4397, 959, 'A reaction absorbs 2200 kJ breaking bonds and releases 1800 kJ forming bonds. Calculate ΔH and explain its sign.', 'text', 1, 'Use the stated subtraction order, then compare the result with zero.', '{"why":"More energy is absorbed breaking bonds than is released forming bonds.","sol":"Step 1: ΔH ≈ 2200 − 1800.\nStep 2: ΔH ≈ +400 kJ.\nStep 3: The positive sign means energy is absorbed overall.","steps":["Step 1: ΔH ≈ 2200 − 1800.","Step 2: ΔH ≈ +400 kJ.","Step 3: The positive sign means energy is absorbed overall."],"options":[],"conceptId":"chemistry_chemical_energetics_bond_energy_calculations","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q5","subject":"chemistry","chapter":"chemical_energetics","topic":"Bond Energy Calculations"}', 4),
  (4398, 959, 'Estimate ΔH for H₂(g) + Cl₂(g) → 2HCl(g) using H–H = 436 kJ/mol, Cl–Cl = 243 kJ/mol and H–Cl = 431 kJ/mol.', 'text', 1, 'There are two H–Cl bonds in the products because the coefficient of HCl is 2.', '{"why":"The products'' bond formation releases more energy than reactant bond breaking absorbs.","sol":"Step 1: Bonds broken: one H–H and one Cl–Cl.\nStep 2: Energy absorbed = 436 + 243 = 679 kJ.\nStep 3: Energy released = 2 × 431 = 862 kJ.\nStep 4: ΔH ≈ 679 − 862 = −183 kJ.","steps":["Step 1: Bonds broken: one H–H and one Cl–Cl.","Step 2: Energy absorbed = 436 + 243 = 679 kJ.","Step 3: Energy released = 2 × 431 = 862 kJ.","Step 4: ΔH ≈ 679 − 862 = −183 kJ."],"options":[],"conceptId":"chemistry_chemical_energetics_bond_energy_calculations","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q6","subject":"chemistry","chapter":"chemical_energetics","topic":"Bond Energy Calculations"}', 5),
  (4399, 959, 'For N₂(g) + 3H₂(g) → 2NH₃(g), use N≡N = 945 kJ/mol, H–H = 436 kJ/mol and N–H = 391 kJ/mol to estimate ΔH.', 'text', 1, 'Count one N≡N bond, three H–H bonds and six N–H bonds.', '{"why":"All six N–H bonds must be counted because each NH₃ molecule contains three N–H bonds.","sol":"Step 1: Energy absorbed = 945 + (3 × 436).\nStep 2: Energy absorbed = 945 + 1308 = 2253 kJ.\nStep 3: Two NH₃ molecules form six N–H bonds.\nStep 4: Energy released = 6 × 391 = 2346 kJ.\nStep 5: ΔH ≈ 2253 − 2346 = −93 kJ.","steps":["Step 1: Energy absorbed = 945 + (3 × 436).","Step 2: Energy absorbed = 945 + 1308 = 2253 kJ.","Step 3: Two NH₃ molecules form six N–H bonds.","Step 4: Energy released = 6 × 391 = 2346 kJ.","Step 5: ΔH ≈ 2253 − 2346 = −93 kJ."],"options":[],"conceptId":"chemistry_chemical_energetics_bond_energy_calculations","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q7","subject":"chemistry","chapter":"chemical_energetics","topic":"Bond Energy Calculations"}', 6),
  (4400, 959, 'A learner calculates ΔH by subtracting the energy of bonds broken from the energy of bonds formed. Explain the error and write the correct formula.', 'text', 1, 'Recall which process absorbs energy and which releases it.', '{"why":"The formula compares the energy input needed to break bonds with the energy released when product bonds form.","sol":"Step 1: Breaking bonds absorbs energy.\nStep 2: Forming bonds releases energy.\nStep 3: The total absorbed energy must come first in the subtraction.\nStep 4: Write the correct relationship.","steps":["Step 1: Breaking bonds absorbs energy.","Step 2: Forming bonds releases energy.","Step 3: The total absorbed energy must come first in the subtraction.","Step 4: Write the correct relationship."],"options":[],"conceptId":"chemistry_chemical_energetics_bond_energy_calculations","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q8","subject":"chemistry","chapter":"chemical_energetics","topic":"Bond Energy Calculations"}', 7),
  (4401, 959, 'A reaction breaks 4 mol of A–B bonds, each with a bond energy of 300 kJ/mol, and forms 2 mol of C–D bonds, each with a bond energy of 500 kJ/mol. Estimate ΔH and classify the reaction.', 'text', 1, 'Calculate both totals separately before subtracting.', '{"why":"The total energy absorbed breaking bonds is 200 kJ greater than the total energy released forming bonds.","sol":"Step 1: Energy absorbed = 4 × 300 = 1200 kJ.\nStep 2: Energy released = 2 × 500 = 1000 kJ.\nStep 3: ΔH ≈ 1200 − 1000 = +200 kJ.\nStep 4: A positive ΔH indicates an endothermic reaction.","steps":["Step 1: Energy absorbed = 4 × 300 = 1200 kJ.","Step 2: Energy released = 2 × 500 = 1000 kJ.","Step 3: ΔH ≈ 1200 − 1000 = +200 kJ.","Step 4: A positive ΔH indicates an endothermic reaction."],"options":[],"conceptId":"chemistry_chemical_energetics_bond_energy_calculations","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q9","subject":"chemistry","chapter":"chemical_energetics","topic":"Bond Energy Calculations"}', 8),
  (4402, 960, 'Define complete combustion of a hydrocarbon and name its products.', 'text', 1, 'Focus on the core principle of Combustion of Fuels.', '{"why":"Sufficient oxygen allows the carbon and hydrogen in the hydrocarbon to be fully oxidised to these products.","sol":"Step 1: A hydrocarbon contains carbon and hydrogen.\nStep 2: Complete combustion occurs when sufficient oxygen is available.\nStep 3: Carbon forms carbon dioxide.\nStep 4: Hydrogen forms water.","steps":["Step 1: A hydrocarbon contains carbon and hydrogen.","Step 2: Complete combustion occurs when sufficient oxygen is available.","Step 3: Carbon forms carbon dioxide.","Step 4: Hydrogen forms water."],"options":[],"conceptId":"chemistry_chemical_energetics_combustion_of_fuels","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q1","subject":"chemistry","chapter":"chemical_energetics","topic":"Combustion of Fuels"}', 0),
  (4403, 960, 'Balance the complete combustion equation for methane: CH₄ + O₂ → CO₂ + H₂O.', 'text', 1, 'Focus on the core principle of Combustion of Fuels.', '{"why":"Both sides contain one carbon atom, four hydrogen atoms and four oxygen atoms.","sol":"Step 1: Carbon is already balanced: one C on each side.\nStep 2: Four hydrogen atoms require 2H₂O.\nStep 3: The products now contain four oxygen atoms.\nStep 4: Place coefficient 2 before O₂.","steps":["Step 1: Carbon is already balanced: one C on each side.","Step 2: Four hydrogen atoms require 2H₂O.","Step 3: The products now contain four oxygen atoms.","Step 4: Place coefficient 2 before O₂."],"options":[],"conceptId":"chemistry_chemical_energetics_combustion_of_fuels","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q2","subject":"chemistry","chapter":"chemical_energetics","topic":"Combustion of Fuels"}', 1),
  (4404, 960, 'Name one poisonous product that may form during incomplete combustion of a hydrocarbon and explain why it is dangerous.', 'text', 1, 'Focus on the core principle of Combustion of Fuels.', '{"why":"Carbon monoxide interferes with oxygen transport in the blood.","sol":"Step 1: Insufficient oxygen can cause incomplete combustion.\nStep 2: Carbon monoxide may form.\nStep 3: Carbon monoxide binds strongly to haemoglobin.\nStep 4: This reduces the blood''s ability to transport oxygen.","steps":["Step 1: Insufficient oxygen can cause incomplete combustion.","Step 2: Carbon monoxide may form.","Step 3: Carbon monoxide binds strongly to haemoglobin.","Step 4: This reduces the blood''s ability to transport oxygen."],"options":[],"conceptId":"chemistry_chemical_energetics_combustion_of_fuels","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q3","subject":"chemistry","chapter":"chemical_energetics","topic":"Combustion of Fuels"}', 2),
  (4405, 960, 'Balance the complete combustion equation for propane: C₃H₈ + O₂ → CO₂ + H₂O.', 'text', 1, 'Balance carbon first, then hydrogen, and oxygen last.', '{"why":"Both sides contain three carbon atoms, eight hydrogen atoms and ten oxygen atoms.","sol":"Step 1: Three carbon atoms require 3CO₂.\nStep 2: Eight hydrogen atoms require 4H₂O.\nStep 3: The products contain 6 + 4 = 10 oxygen atoms.\nStep 4: Five O₂ molecules supply 10 oxygen atoms.","steps":["Step 1: Three carbon atoms require 3CO₂.","Step 2: Eight hydrogen atoms require 4H₂O.","Step 3: The products contain 6 + 4 = 10 oxygen atoms.","Step 4: Five O₂ molecules supply 10 oxygen atoms."],"options":[],"conceptId":"chemistry_chemical_energetics_combustion_of_fuels","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q4","subject":"chemistry","chapter":"chemical_energetics","topic":"Combustion of Fuels"}', 3),
  (4406, 960, 'A methane burner has insufficient oxygen and produces carbon monoxide and water. Balance: CH₄ + O₂ → CO + H₂O.', 'text', 1, 'Balance carbon and hydrogen first. Use coefficients that give whole-number oxygen molecules.', '{"why":"Both sides contain two carbon atoms, eight hydrogen atoms and six oxygen atoms.","sol":"Step 1: Use 2CH₄ to give 2 carbon atoms and 8 hydrogen atoms.\nStep 2: Place 2 before CO and 4 before H₂O.\nStep 3: The products now contain 6 oxygen atoms.\nStep 4: Place 3 before O₂.","steps":["Step 1: Use 2CH₄ to give 2 carbon atoms and 8 hydrogen atoms.","Step 2: Place 2 before CO and 4 before H₂O.","Step 3: The products now contain 6 oxygen atoms.","Step 4: Place 3 before O₂."],"options":[],"conceptId":"chemistry_chemical_energetics_combustion_of_fuels","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q5","subject":"chemistry","chapter":"chemical_energetics","topic":"Combustion of Fuels"}', 4),
  (4407, 960, 'Explain two differences between complete and incomplete combustion of hydrocarbons.', 'text', 1, 'Compare the oxygen supply and the carbon-containing products.', '{"why":"The availability of oxygen affects how fully the carbon in the fuel is oxidised.","sol":"Step 1: Complete combustion occurs with sufficient oxygen.\nStep 2: Incomplete combustion occurs when oxygen is insufficient.\nStep 3: Complete combustion produces CO₂ and H₂O.\nStep 4: Incomplete combustion may produce CO and/or carbon, together with water.","steps":["Step 1: Complete combustion occurs with sufficient oxygen.","Step 2: Incomplete combustion occurs when oxygen is insufficient.","Step 3: Complete combustion produces CO₂ and H₂O.","Step 4: Incomplete combustion may produce CO and/or carbon, together with water."],"options":[],"conceptId":"chemistry_chemical_energetics_combustion_of_fuels","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q6","subject":"chemistry","chapter":"chemical_energetics","topic":"Combustion of Fuels"}', 5),
  (4408, 960, 'Write a balanced equation for incomplete combustion of carbon to carbon monoxide and explain the safety concern associated with the product.', 'text', 1, 'Carbon monoxide contains one oxygen atom per molecule. Balance the oxygen atoms as well as carbon.', '{"why":"The balanced equation conserves atoms, and the carbon monoxide product is a serious inhalation hazard.","sol":"Step 1: Start with C + O₂ → CO.\nStep 2: Use 2CO to balance the two oxygen atoms from O₂.\nStep 3: Place 2C on the left to balance carbon.\nStep 4: Identify the hazard of CO.","steps":["Step 1: Start with C + O₂ → CO.","Step 2: Use 2CO to balance the two oxygen atoms from O₂.","Step 3: Place 2C on the left to balance carbon.","Step 4: Identify the hazard of CO."],"options":[],"conceptId":"chemistry_chemical_energetics_combustion_of_fuels","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q7","subject":"chemistry","chapter":"chemical_energetics","topic":"Combustion of Fuels"}', 6),
  (4409, 960, 'A learner says that complete combustion of methane produces carbon monoxide because methane contains carbon. Correct the claim and give the balanced equation.', 'text', 1, 'Complete combustion requires sufficient oxygen. Distinguish carbon dioxide from carbon monoxide.', '{"why":"Carbon monoxide may form during incomplete combustion, while sufficient oxygen allows carbon to form carbon dioxide.","sol":"Step 1: Methane is a hydrocarbon containing carbon and hydrogen.\nStep 2: Complete combustion in sufficient oxygen produces CO₂ and H₂O.\nStep 3: Balance hydrogen by placing 2 before H₂O.\nStep 4: Balance oxygen by placing 2 before O₂.","steps":["Step 1: Methane is a hydrocarbon containing carbon and hydrogen.","Step 2: Complete combustion in sufficient oxygen produces CO₂ and H₂O.","Step 3: Balance hydrogen by placing 2 before H₂O.","Step 4: Balance oxygen by placing 2 before O₂."],"options":[],"conceptId":"chemistry_chemical_energetics_combustion_of_fuels","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q8","subject":"chemistry","chapter":"chemical_energetics","topic":"Combustion of Fuels"}', 7),
  (4410, 960, 'Why can incomplete combustion be dangerous even when a fuel is releasing heat? Give two reasons.', 'text', 1, 'Think about poisonous gases and particles that can form when oxygen is insufficient.', '{"why":"The release of useful heat does not mean combustion products are harmless.","sol":"Step 1: Incomplete combustion can produce carbon monoxide.\nStep 2: Carbon monoxide is poisonous and interferes with oxygen transport in the blood.\nStep 3: Incomplete combustion may also produce soot or carbon particles.\nStep 4: These particles contribute to air pollution and can affect health.","steps":["Step 1: Incomplete combustion can produce carbon monoxide.","Step 2: Carbon monoxide is poisonous and interferes with oxygen transport in the blood.","Step 3: Incomplete combustion may also produce soot or carbon particles.","Step 4: These particles contribute to air pollution and can affect health."],"options":[],"conceptId":"chemistry_chemical_energetics_combustion_of_fuels","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q9","subject":"chemistry","chapter":"chemical_energetics","topic":"Combustion of Fuels"}', 8),
  (4411, 961, 'Define calorific value.', 'text', 1, 'Focus on the core principle of Calorific Value.', '{"why":"Calorific value measures energy released per unit mass of fuel.","sol":"Step 1: Identify key concept: Define the required principles for Calorific Value.\nStep 2: Apply governing rule: Calorific value measures energy released per unit mass of fuel.\nStep 3: State the final conclusion: The energy released when a unit mass of fuel undergoes complete combustion in sufficient oxygen.","steps":["Step 1: Identify key concept: Define the required principles for Calorific Value.","Step 2: Apply governing rule: Calorific value measures energy released per unit mass of fuel.","Step 3: State the final conclusion: The energy released when a unit mass of fuel undergoes complete combustion in sufficient oxygen."],"options":[],"conceptId":"chemistry_chemical_energetics_calorific_value","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q1","subject":"chemistry","chapter":"chemical_energetics","topic":"Calorific Value"}', 0),
  (4412, 961, 'Calculate the energy released when 15 g of a fuel with a calorific value of 32 kJ/g burns completely.', 'text', 1, 'Focus on the core principle of Calorific Value.', '{"why":"Energy = mass × calorific value = 15 × 32 = 480 kJ.","sol":"Step 1: Identify key concept: Define the required principles for Calorific Value.\nStep 2: Apply governing rule: Energy = mass × calorific value = 15 × 32 = 480 kJ.\nStep 3: State the final conclusion: 480 kJ","steps":["Step 1: Identify key concept: Define the required principles for Calorific Value.","Step 2: Apply governing rule: Energy = mass × calorific value = 15 × 32 = 480 kJ.","Step 3: State the final conclusion: 480 kJ"],"options":[],"conceptId":"chemistry_chemical_energetics_calorific_value","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q2","subject":"chemistry","chapter":"chemical_energetics","topic":"Calorific Value"}', 1),
  (4413, 961, 'A fuel releases 3,600 kJ when 90 g burns completely. Calculate its calorific value.', 'text', 1, 'Focus on the core principle of Calorific Value.', '{"why":"Calorific value = energy ÷ mass = 3,600 ÷ 90 = 40 kJ/g.","sol":"Step 1: Identify key concept: Define the required principles for Calorific Value.\nStep 2: Apply governing rule: Calorific value = energy ÷ mass = 3,600 ÷ 90 = 40 kJ/g.\nStep 3: State the final conclusion: 40 kJ/g","steps":["Step 1: Identify key concept: Define the required principles for Calorific Value.","Step 2: Apply governing rule: Calorific value = energy ÷ mass = 3,600 ÷ 90 = 40 kJ/g.","Step 3: State the final conclusion: 40 kJ/g"],"options":[],"conceptId":"chemistry_chemical_energetics_calorific_value","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q3","subject":"chemistry","chapter":"chemical_energetics","topic":"Calorific Value"}', 2),
  (4414, 961, 'A fuel has a calorific value of 35 kJ/g. Calculate the energy released by 12 g of the fuel during complete combustion.', 'text', 1, 'Multiply the mass burned by the energy released per gram.', '{"why":"Each gram releases 35 kJ, so 12 g releases 12 × 35 = 420 kJ.","sol":"Step 1: Write the formula: E = m × CV.\nStep 2: Substitute m = 12 g and CV = 35 kJ/g.\nStep 3: Calculate 12 × 35 = 420.\nStep 4: State the energy in kJ.","steps":["Step 1: Write the formula: E = m × CV.","Step 2: Substitute m = 12 g and CV = 35 kJ/g.","Step 3: Calculate 12 × 35 = 420.","Step 4: State the energy in kJ."],"options":[],"conceptId":"chemistry_chemical_energetics_calorific_value","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q4","subject":"chemistry","chapter":"chemical_energetics","topic":"Calorific Value"}', 3),
  (4415, 961, 'Complete combustion of 80 g of a fuel releases 3,200 kJ. Calculate the calorific value.', 'text', 1, 'Divide the total energy by the mass of fuel burned.', '{"why":"The fuel releases 40 kJ for every gram burned.","sol":"Step 1: Write CV = E ÷ m.\nStep 2: Substitute E = 3,200 kJ and m = 80 g.\nStep 3: Calculate 3,200 ÷ 80 = 40.\nStep 4: Include the unit kJ/g.","steps":["Step 1: Write CV = E ÷ m.","Step 2: Substitute E = 3,200 kJ and m = 80 g.","Step 3: Calculate 3,200 ÷ 80 = 40.","Step 4: Include the unit kJ/g."],"options":[],"conceptId":"chemistry_chemical_energetics_calorific_value","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q5","subject":"chemistry","chapter":"chemical_energetics","topic":"Calorific Value"}', 4),
  (4416, 961, 'How many grams of a fuel with a calorific value of 25 kJ/g are required to release 1,000 kJ?', 'text', 1, 'Rearrange the energy formula to make mass the subject.', '{"why":"Forty grams release 40 × 25 = 1,000 kJ.","sol":"Step 1: Write E = m × CV.\nStep 2: Rearrange: m = E ÷ CV.\nStep 3: Substitute m = 1,000 ÷ 25.\nStep 4: Calculate the result and state it in grams.","steps":["Step 1: Write E = m × CV.","Step 2: Rearrange: m = E ÷ CV.","Step 3: Substitute m = 1,000 ÷ 25.","Step 4: Calculate the result and state it in grams."],"options":[],"conceptId":"chemistry_chemical_energetics_calorific_value","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q6","subject":"chemistry","chapter":"chemical_energetics","topic":"Calorific Value"}', 5),
  (4417, 961, 'A fuel has a calorific value of 42 MJ/kg. Express this value in kJ/g.', 'text', 1, 'Convert megajoules to kilojoules and kilograms to grams.', '{"why":"The factors of 1,000 in the energy and mass conversions cancel, so the numerical value remains 42.","sol":"Step 1: Recall that 1 MJ = 1,000 kJ.\nStep 2: Recall that 1 kg = 1,000 g.\nStep 3: Convert 42 MJ/kg to 42,000 kJ per 1,000 g.\nStep 4: Divide 42,000 by 1,000.","steps":["Step 1: Recall that 1 MJ = 1,000 kJ.","Step 2: Recall that 1 kg = 1,000 g.","Step 3: Convert 42 MJ/kg to 42,000 kJ per 1,000 g.","Step 4: Divide 42,000 by 1,000."],"options":[],"conceptId":"chemistry_chemical_energetics_calorific_value","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q7","subject":"chemistry","chapter":"chemical_energetics","topic":"Calorific Value"}', 6),
  (4418, 961, 'Fuel A has a calorific value of 50 kJ/g while fuel B has a calorific value of 30 kJ/g. How much more energy does 10 g of A release than 10 g of B, assuming complete combustion?', 'text', 1, 'Calculate the energy from each fuel separately, then subtract.', '{"why":"Fuel A releases 500 kJ and fuel B releases 300 kJ, giving a difference of 200 kJ.","sol":"Step 1: Calculate A: E = 10 × 50 = 500 kJ.\nStep 2: Calculate B: E = 10 × 30 = 300 kJ.\nStep 3: Subtract B''s energy from A''s energy.\nStep 4: State the difference in kJ.","steps":["Step 1: Calculate A: E = 10 × 50 = 500 kJ.","Step 2: Calculate B: E = 10 × 30 = 300 kJ.","Step 3: Subtract B''s energy from A''s energy.","Step 4: State the difference in kJ."],"options":[],"conceptId":"chemistry_chemical_energetics_calorific_value","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q8","subject":"chemistry","chapter":"chemical_energetics","topic":"Calorific Value"}', 7),
  (4419, 961, 'A learner says, ''A 100 g sample of a fuel with a calorific value of 20 kJ/g has a calorific value of 2,000 kJ.'' Identify the error and give the correct values.', 'text', 1, 'Distinguish energy per gram from the total energy released by the sample.', '{"why":"Calorific value is energy per unit mass. Multiplying it by the mass gives the total energy released.","sol":"Step 1: Identify the given calorific value: 20 kJ/g.\nStep 2: Recognise that multiplying by 100 g gives total energy, not calorific value.\nStep 3: Calculate total energy = 100 × 20 = 2,000 kJ.\nStep 4: State both the calorific value and the total energy.","steps":["Step 1: Identify the given calorific value: 20 kJ/g.","Step 2: Recognise that multiplying by 100 g gives total energy, not calorific value.","Step 3: Calculate total energy = 100 × 20 = 2,000 kJ.","Step 4: State both the calorific value and the total energy."],"options":[],"conceptId":"chemistry_chemical_energetics_calorific_value","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q9","subject":"chemistry","chapter":"chemical_energetics","topic":"Calorific Value"}', 8),
  (4420, 962, 'State four factors that should be considered when comparing fuels.', 'text', 1, 'Focus on the core principle of Comparing Fuels.', '{"why":"A fuel must be evaluated by its energy output as well as its economic, environmental, and practical effects.","sol":"Step 1: Identify key concept: Define the required principles for Comparing Fuels.\nStep 2: Apply governing rule: A fuel must be evaluated by its energy output as well as its economic, environmental, and practical effects.\nStep 3: State the final conclusion: Calorific value, cost per unit of energy, environmental effects, and availability. Other valid factors include safety, storage, transport, and renewability.","steps":["Step 1: Identify key concept: Define the required principles for Comparing Fuels.","Step 2: Apply governing rule: A fuel must be evaluated by its energy output as well as its economic, environmental, and practical effects.","Step 3: State the final conclusion: Calorific value, cost per unit of energy, environmental effects, and availability. Other valid factors include safety, storage, transport, and renewability."],"options":[],"conceptId":"chemistry_chemical_energetics_comparing_fuels","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q1","subject":"chemistry","chapter":"chemical_energetics","topic":"Comparing Fuels"}', 0),
  (4421, 962, 'Fuel A has a calorific value of 45 kJ/g and fuel B has a calorific value of 30 kJ/g. Calculate the energy released by 8 g of each fuel.', 'text', 1, 'Focus on the core principle of Comparing Fuels.', '{"why":"Energy = mass × calorific value. Therefore, A releases 8 × 45 = 360 kJ and B releases 8 × 30 = 240 kJ.","sol":"Step 1: Identify key concept: Define the required principles for Comparing Fuels.\nStep 2: Apply governing rule: Energy = mass × calorific value. Therefore, A releases 8 × 45 = 360 kJ and B releases 8 × 30 = 240 kJ.\nStep 3: State the final conclusion: Fuel A: 360 kJ; Fuel B: 240 kJ.","steps":["Step 1: Identify key concept: Define the required principles for Comparing Fuels.","Step 2: Apply governing rule: Energy = mass × calorific value. Therefore, A releases 8 × 45 = 360 kJ and B releases 8 × 30 = 240 kJ.","Step 3: State the final conclusion: Fuel A: 360 kJ; Fuel B: 240 kJ."],"options":[],"conceptId":"chemistry_chemical_energetics_comparing_fuels","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q2","subject":"chemistry","chapter":"chemical_energetics","topic":"Comparing Fuels"}', 1),
  (4422, 962, 'Explain why a fuel with the highest calorific value is not necessarily the best fuel.', 'text', 1, 'Focus on the core principle of Comparing Fuels.', '{"why":"Calorific value measures energy per unit mass, but fuel selection involves other economic, environmental, and practical factors.","sol":"Step 1: Identify key concept: Define the required principles for Comparing Fuels.\nStep 2: Apply governing rule: Calorific value measures energy per unit mass, but fuel selection involves other economic, environmental, and practical factors.\nStep 3: State the final conclusion: It may be too expensive, polluting, difficult to obtain, unsafe to store, or unsuitable for the equipment being used.","steps":["Step 1: Identify key concept: Define the required principles for Comparing Fuels.","Step 2: Apply governing rule: Calorific value measures energy per unit mass, but fuel selection involves other economic, environmental, and practical factors.","Step 3: State the final conclusion: It may be too expensive, polluting, difficult to obtain, unsafe to store, or unsuitable for the equipment being used."],"options":[],"conceptId":"chemistry_chemical_energetics_comparing_fuels","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q3","subject":"chemistry","chapter":"chemical_energetics","topic":"Comparing Fuels"}', 2),
  (4423, 962, 'Fuel X has a calorific value of 42 kJ/g. Calculate the energy released when 20 g burns completely.', 'text', 1, 'Multiply the mass of fuel by its calorific value.', '{"why":"Twenty grams of fuel X release 20 × 42 = 840 kJ under complete-combustion conditions.","sol":"Step 1: Write E = m × CV.\nStep 2: Substitute m = 20 g and CV = 42 kJ/g.\nStep 3: Calculate 20 × 42 = 840.\nStep 4: State the answer in kJ.","steps":["Step 1: Write E = m × CV.","Step 2: Substitute m = 20 g and CV = 42 kJ/g.","Step 3: Calculate 20 × 42 = 840.","Step 4: State the answer in kJ."],"options":[],"conceptId":"chemistry_chemical_energetics_comparing_fuels","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q4","subject":"chemistry","chapter":"chemical_energetics","topic":"Comparing Fuels"}', 3),
  (4424, 962, 'Fuel P has a calorific value of 36 kJ/g and fuel Q has a calorific value of 24 kJ/g. How much more energy does 5 g of P release than 5 g of Q?', 'text', 1, 'Calculate the energy from each equal mass, then find the difference.', '{"why":"Fuel P releases 180 kJ and fuel Q releases 120 kJ, so the difference is 60 kJ.","sol":"Step 1: Calculate P: 5 × 36 = 180 kJ.\nStep 2: Calculate Q: 5 × 24 = 120 kJ.\nStep 3: Subtract 120 kJ from 180 kJ.\nStep 4: State the difference.","steps":["Step 1: Calculate P: 5 × 36 = 180 kJ.","Step 2: Calculate Q: 5 × 24 = 120 kJ.","Step 3: Subtract 120 kJ from 180 kJ.","Step 4: State the difference."],"options":[],"conceptId":"chemistry_chemical_energetics_comparing_fuels","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q5","subject":"chemistry","chapter":"chemical_energetics","topic":"Comparing Fuels"}', 4),
  (4425, 962, 'A task requires 1,500 kJ. Fuel A has a calorific value of 50 kJ/g and fuel B has a calorific value of 30 kJ/g. Calculate the mass of each fuel required, assuming complete combustion and no energy losses.', 'text', 1, 'Divide the required energy by each fuel''s calorific value.', '{"why":"Fuel A provides more energy per gram, so a smaller mass is needed to supply the same energy.","sol":"Step 1: Write m = E ÷ CV.\nStep 2: For A: m = 1,500 ÷ 50 = 30 g.\nStep 3: For B: m = 1,500 ÷ 30 = 50 g.\nStep 4: Compare the two masses.","steps":["Step 1: Write m = E ÷ CV.","Step 2: For A: m = 1,500 ÷ 50 = 30 g.","Step 3: For B: m = 1,500 ÷ 30 = 50 g.","Step 4: Compare the two masses."],"options":[],"conceptId":"chemistry_chemical_energetics_comparing_fuels","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q6","subject":"chemistry","chapter":"chemical_energetics","topic":"Comparing Fuels"}', 5),
  (4426, 962, 'Fuel A costs KSh 150 for a quantity that releases 5,000 kJ. Fuel B costs KSh 100 for a quantity that releases 2,500 kJ. Calculate the cost per kJ for each and identify the cheaper source of energy.', 'text', 1, 'Divide each price by the energy released by that quantity.', '{"why":"Although fuel B has the lower purchase price, its energy costs more per kilojoule.","sol":"Step 1: For A: 150 ÷ 5,000 = KSh 0.03/kJ.\nStep 2: For B: 100 ÷ 2,500 = KSh 0.04/kJ.\nStep 3: Compare the two unit costs.\nStep 4: Identify the lower cost per kJ.","steps":["Step 1: For A: 150 ÷ 5,000 = KSh 0.03/kJ.","Step 2: For B: 100 ÷ 2,500 = KSh 0.04/kJ.","Step 3: Compare the two unit costs.","Step 4: Identify the lower cost per kJ."],"options":[],"conceptId":"chemistry_chemical_energetics_comparing_fuels","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q7","subject":"chemistry","chapter":"chemical_energetics","topic":"Comparing Fuels"}', 6),
  (4427, 962, 'A learner chooses a fuel solely because it has the highest calorific value. Give three other factors the learner should investigate before making the final choice.', 'text', 1, 'Think about money, pollution, practical access, and safe use.', '{"why":"A high calorific value does not guarantee affordability, low pollution, reliable supply, or safe use.","sol":"Step 1: Consider the total cost of obtaining useful energy.\nStep 2: Consider emissions and effects on human health and the environment.\nStep 3: Consider availability, storage, transport, or safety.\nStep 4: Explain briefly why these factors affect the decision.","steps":["Step 1: Consider the total cost of obtaining useful energy.","Step 2: Consider emissions and effects on human health and the environment.","Step 3: Consider availability, storage, transport, or safety.","Step 4: Explain briefly why these factors affect the decision."],"options":[],"conceptId":"chemistry_chemical_energetics_comparing_fuels","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q8","subject":"chemistry","chapter":"chemical_energetics","topic":"Comparing Fuels"}', 7),
  (4428, 962, 'Fuel M is renewable and locally available but has a lower calorific value. Fuel N has a higher calorific value but is expensive and difficult to obtain. Explain why M could still be the better choice for a household.', 'text', 1, 'Distinguish energy per gram from overall suitability and affordability.', '{"why":"The highest calorific value is only one criterion. Overall suitability depends on cost, supply, safety, environmental effects, and the intended use.","sol":"Step 1: Acknowledge that N provides more energy per unit mass.\nStep 2: Consider the price and cost of obtaining useful energy from each fuel.\nStep 3: Consider M''s local availability and potentially more reliable supply.\nStep 4: Mention that safety and environmental impacts must also be assessed.","steps":["Step 1: Acknowledge that N provides more energy per unit mass.","Step 2: Consider the price and cost of obtaining useful energy from each fuel.","Step 3: Consider M''s local availability and potentially more reliable supply.","Step 4: Mention that safety and environmental impacts must also be assessed."],"options":[],"conceptId":"chemistry_chemical_energetics_comparing_fuels","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q9","subject":"chemistry","chapter":"chemical_energetics","topic":"Comparing Fuels"}', 8),
  (4429, 963, 'What is meant by a physical property?', 'text', 1, 'Consider whether a new substance must form when the property is observed.', '{"why":"Physical properties describe substances without requiring a chemical reaction.","sol":"Step 1: A physical property describes a characteristic of a substance.\nStep 2: Observing or measuring it does not require changing the substance into a different substance.","steps":["Step 1: A physical property describes a characteristic of a substance.","Step 2: Observing or measuring it does not require changing the substance into a different substance."],"options":[],"conceptId":"chemistry_metals_physical_properties_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q1","subject":"chemistry","chapter":"metals","topic":"Physical Properties of Metals"}', 0),
  (4430, 963, 'A metal has a mass of 84 g and a volume of 12 cm³. Calculate its density.', 'text', 1, 'Density = mass ÷ volume.', '{"why":"Density is the mass contained in each unit of volume.","sol":"Step 1: Write density = mass ÷ volume.\nStep 2: Substitute 84 g and 12 cm³.\nStep 3: Calculate 84 ÷ 12 = 7.","steps":["Step 1: Write density = mass ÷ volume.","Step 2: Substitute 84 g and 12 cm³.","Step 3: Calculate 84 ÷ 12 = 7."],"options":[],"conceptId":"chemistry_metals_physical_properties_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q2","subject":"chemistry","chapter":"metals","topic":"Physical Properties of Metals"}', 1),
  (4431, 963, 'Name two physical properties that make metals useful for cooking utensils.', 'text', 1, 'Consider how the material transfers heat and withstands use.', '{"why":"Thermal conductivity helps transfer heat, while strength helps the utensil withstand use.","sol":"Step 1: A cooking utensil should transfer heat from the heat source to the food.\nStep 2: It should also withstand handling and use.\nStep 3: Thermal conductivity and strength are useful properties.","steps":["Step 1: A cooking utensil should transfer heat from the heat source to the food.","Step 2: It should also withstand handling and use.","Step 3: Thermal conductivity and strength are useful properties."],"options":[],"conceptId":"chemistry_metals_physical_properties_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q3","subject":"chemistry","chapter":"metals","topic":"Physical Properties of Metals"}', 2),
  (4432, 963, 'A student claims that all metals are hard because iron is hard. Explain why this conclusion is incorrect.', 'text', 1, 'A property observed in one metal cannot automatically be applied to every metal.', '{"why":"The physical properties of metals vary from one metal to another.","sol":"Step 1: Iron is one example of a metal.\nStep 2: Different metals have different physical properties.\nStep 3: Sodium, for example, is soft and can be cut with a knife under suitable safe conditions.\nStep 4: Therefore, hardness is not identical in all metals.","steps":["Step 1: Iron is one example of a metal.","Step 2: Different metals have different physical properties.","Step 3: Sodium, for example, is soft and can be cut with a knife under suitable safe conditions.","Step 4: Therefore, hardness is not identical in all metals."],"options":[],"conceptId":"chemistry_metals_physical_properties_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q4","subject":"chemistry","chapter":"metals","topic":"Physical Properties of Metals"}', 3),
  (4433, 963, 'A metal block has a mass of 156 g and a volume of 20 cm³. Calculate its density and show the units.', 'text', 1, 'Divide the mass by the volume, keeping the units.', '{"why":"Dividing grams by cubic centimetres gives density in g/cm³.","sol":"Step 1: Density = mass ÷ volume.\nStep 2: Density = 156 g ÷ 20 cm³.\nStep 3: Density = 7.8 g/cm³.","steps":["Step 1: Density = mass ÷ volume.","Step 2: Density = 156 g ÷ 20 cm³.","Step 3: Density = 7.8 g/cm³."],"options":[],"conceptId":"chemistry_metals_physical_properties_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q5","subject":"chemistry","chapter":"metals","topic":"Physical Properties of Metals"}', 4),
  (4434, 963, 'Two samples have equal volumes. Sample X has a mass of 40 g, while sample Y has a mass of 65 g. Which sample has the greater density? Explain.', 'text', 1, 'Density compares mass with volume. The volumes are equal.', '{"why":"At equal volumes, the sample with greater mass has greater density.","sol":"Step 1: Density = mass ÷ volume.\nStep 2: Both samples have the same volume.\nStep 3: The sample with greater mass therefore has greater density.\nStep 4: Sample Y has a mass of 65 g, greater than 40 g.","steps":["Step 1: Density = mass ÷ volume.","Step 2: Both samples have the same volume.","Step 3: The sample with greater mass therefore has greater density.","Step 4: Sample Y has a mass of 65 g, greater than 40 g."],"options":[],"conceptId":"chemistry_metals_physical_properties_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q6","subject":"chemistry","chapter":"metals","topic":"Physical Properties of Metals"}', 5),
  (4435, 963, 'A student says that a shiny metal surface must remain shiny forever. Explain why the statement is incorrect.', 'text', 1, 'Think about what may happen when a metal reacts with air or moisture.', '{"why":"Surface reactions can form coatings that change a metal''s appearance.","sol":"Step 1: A freshly polished metal may have a shiny surface.\nStep 2: Some metals react with substances in their surroundings.\nStep 3: The products formed on the surface may make it dull.","steps":["Step 1: A freshly polished metal may have a shiny surface.","Step 2: Some metals react with substances in their surroundings.","Step 3: The products formed on the surface may make it dull."],"options":[],"conceptId":"chemistry_metals_physical_properties_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q7","subject":"chemistry","chapter":"metals","topic":"Physical Properties of Metals"}', 6),
  (4436, 963, 'A metal has a density of 8 g/cm³ and a volume of 6 cm³. Calculate its mass.', 'text', 1, 'Rearrange density = mass ÷ volume to make mass the subject.', '{"why":"Multiplying density by volume gives mass.","sol":"Step 1: Density = mass ÷ volume.\nStep 2: Rearrange: mass = density × volume.\nStep 3: Mass = 8 × 6.\nStep 4: Mass = 48 g.","steps":["Step 1: Density = mass ÷ volume.","Step 2: Rearrange: mass = density × volume.","Step 3: Mass = 8 × 6.","Step 4: Mass = 48 g."],"options":[],"conceptId":"chemistry_metals_physical_properties_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q8","subject":"chemistry","chapter":"metals","topic":"Physical Properties of Metals"}', 7),
  (4437, 963, 'Why should a scientist distinguish hardness from strength when describing a metal?', 'text', 1, 'Think about scratching compared with resisting a large applied force.', '{"why":"They measure different properties and should not be treated as interchangeable terms.","sol":"Step 1: Hardness describes resistance to scratching or indentation.\nStep 2: Strength describes the ability to withstand applied forces without failure.\nStep 3: These are different types of mechanical behaviour.\nStep 4: A description of one does not automatically establish the other.","steps":["Step 1: Hardness describes resistance to scratching or indentation.","Step 2: Strength describes the ability to withstand applied forces without failure.","Step 3: These are different types of mechanical behaviour.","Step 4: A description of one does not automatically establish the other."],"options":[],"conceptId":"chemistry_metals_physical_properties_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q9","subject":"chemistry","chapter":"metals","topic":"Physical Properties of Metals"}', 8),
  (4438, 964, 'Which particles mainly carry electric current through a metal?', 'text', 1, 'These particles are mobile and are not confined to individual metal atoms.', '{"why":"Mobile delocalised electrons are responsible for electrical conduction in metals.","sol":"Step 1: Metal ions form a lattice.\nStep 2: Delocalised electrons can move through the lattice.\nStep 3: Their movement carries electric charge.","steps":["Step 1: Metal ions form a lattice.","Step 2: Delocalised electrons can move through the lattice.","Step 3: Their movement carries electric charge."],"options":[],"conceptId":"chemistry_metals_electrical_conductivity","skillId":"chemistry_metals","subskillId":"chemistry_metals_q1","subject":"chemistry","chapter":"metals","topic":"Electrical Conductivity"}', 0),
  (4439, 964, 'Why is copper suitable for making electrical wires?', 'text', 1, 'Consider both the flow of electric charge and the ability to form a wire.', '{"why":"Its conductivity and ductility make copper useful for electrical wiring.","sol":"Step 1: Electrical wires need to conduct current efficiently.\nStep 2: Copper has high electrical conductivity.\nStep 3: Copper is ductile and can be drawn into wires.","steps":["Step 1: Electrical wires need to conduct current efficiently.","Step 2: Copper has high electrical conductivity.","Step 3: Copper is ductile and can be drawn into wires."],"options":[],"conceptId":"chemistry_metals_electrical_conductivity","skillId":"chemistry_metals","subskillId":"chemistry_metals_q2","subject":"chemistry","chapter":"metals","topic":"Electrical Conductivity"}', 1),
  (4440, 964, 'A wire has resistance 4 Ω. If its length is doubled while material, temperature and cross-sectional area remain unchanged, what is its new resistance?', 'text', 1, 'For a uniform wire, resistance is directly proportional to length when the other factors stay constant.', '{"why":"For the same material and cross-sectional area at the same temperature, R is proportional to length.","sol":"Step 1: Original resistance = 4 Ω.\nStep 2: Doubling the length doubles the resistance.\nStep 3: New resistance = 2 × 4 = 8 Ω.","steps":["Step 1: Original resistance = 4 Ω.","Step 2: Doubling the length doubles the resistance.","Step 3: New resistance = 2 × 4 = 8 Ω."],"options":[],"conceptId":"chemistry_metals_electrical_conductivity","skillId":"chemistry_metals","subskillId":"chemistry_metals_q3","subject":"chemistry","chapter":"metals","topic":"Electrical Conductivity"}', 2),
  (4441, 964, 'Explain why electrons can move through a metal even though its positive ions remain arranged in a lattice.', 'text', 1, 'Consider the difference between delocalised electrons and the positive metal ions.', '{"why":"The mobile electrons provide the charge carriers needed for electrical conduction.","sol":"Step 1: Positive metal ions occupy positions in a lattice.\nStep 2: Metallic bonding includes delocalised electrons that are not tied to one atom.\nStep 3: These electrons can move through the lattice when a potential difference is applied.\nStep 4: Their movement produces electric current.","steps":["Step 1: Positive metal ions occupy positions in a lattice.","Step 2: Metallic bonding includes delocalised electrons that are not tied to one atom.","Step 3: These electrons can move through the lattice when a potential difference is applied.","Step 4: Their movement produces electric current."],"options":[],"conceptId":"chemistry_metals_electrical_conductivity","skillId":"chemistry_metals","subskillId":"chemistry_metals_q4","subject":"chemistry","chapter":"metals","topic":"Electrical Conductivity"}', 3),
  (4442, 964, 'A wire has resistivity 3 × 10⁻⁸ Ω m, length 2 m and cross-sectional area 3 × 10⁻⁶ m². Calculate its resistance using R = ρL/A.', 'text', 1, 'Multiply resistivity by length, then divide by the cross-sectional area.', '{"why":"Substitution into R = ρL/A gives a resistance of 0.02 Ω.","sol":"Step 1: R = ρL/A.\nStep 2: R = (3 × 10⁻⁸ × 2) ÷ (3 × 10⁻⁶).\nStep 3: Numerator = 6 × 10⁻⁸.\nStep 4: R = (6 × 10⁻⁸) ÷ (3 × 10⁻⁶) = 2 × 10⁻² Ω.","steps":["Step 1: R = ρL/A.","Step 2: R = (3 × 10⁻⁸ × 2) ÷ (3 × 10⁻⁶).","Step 3: Numerator = 6 × 10⁻⁸.","Step 4: R = (6 × 10⁻⁸) ÷ (3 × 10⁻⁶) = 2 × 10⁻² Ω."],"options":[],"conceptId":"chemistry_metals_electrical_conductivity","skillId":"chemistry_metals","subskillId":"chemistry_metals_q5","subject":"chemistry","chapter":"metals","topic":"Electrical Conductivity"}', 4),
  (4443, 964, 'Two wires have the same material, length and temperature. Wire X has twice the cross-sectional area of wire Y. Compare their resistances.', 'text', 1, 'Resistance is inversely proportional to cross-sectional area when the other quantities are constant.', '{"why":"A larger cross-sectional area provides more space for charge flow and reduces resistance.","sol":"Step 1: Use R = ρL/A.\nStep 2: The resistivity and length are the same for both wires.\nStep 3: Doubling the area halves the resistance.\nStep 4: Therefore, resistance of X is half that of Y.","steps":["Step 1: Use R = ρL/A.","Step 2: The resistivity and length are the same for both wires.","Step 3: Doubling the area halves the resistance.","Step 4: Therefore, resistance of X is half that of Y."],"options":[],"conceptId":"chemistry_metals_electrical_conductivity","skillId":"chemistry_metals","subskillId":"chemistry_metals_q6","subject":"chemistry","chapter":"metals","topic":"Electrical Conductivity"}', 5),
  (4444, 964, 'A student says that metal ions flow from one end of a copper wire to the other when current flows. Correct the statement.', 'text', 1, 'Identify which charged particles are mobile in a metal lattice.', '{"why":"Electrical conduction in a metal is primarily due to mobile electrons, not the movement of the lattice ions along the wire.","sol":"Step 1: The positive copper ions remain arranged in the metallic lattice during ordinary conduction.\nStep 2: Delocalised electrons can move through the lattice.\nStep 3: These electrons carry the current.","steps":["Step 1: The positive copper ions remain arranged in the metallic lattice during ordinary conduction.","Step 2: Delocalised electrons can move through the lattice.","Step 3: These electrons carry the current."],"options":[],"conceptId":"chemistry_metals_electrical_conductivity","skillId":"chemistry_metals","subskillId":"chemistry_metals_q7","subject":"chemistry","chapter":"metals","topic":"Electrical Conductivity"}', 6),
  (4445, 964, 'Why can a long, thin wire have greater resistance than a short, thick wire made from the same material at the same temperature?', 'text', 1, 'Consider the effects of both length and cross-sectional area in R = ρL/A.', '{"why":"For a uniform wire, R = ρL/A.","sol":"Step 1: Resistance increases with length.\nStep 2: Resistance decreases as cross-sectional area increases.\nStep 3: A long wire has a greater length, while a thin wire has a smaller area.\nStep 4: Both factors tend to increase its resistance.","steps":["Step 1: Resistance increases with length.","Step 2: Resistance decreases as cross-sectional area increases.","Step 3: A long wire has a greater length, while a thin wire has a smaller area.","Step 4: Both factors tend to increase its resistance."],"options":[],"conceptId":"chemistry_metals_electrical_conductivity","skillId":"chemistry_metals","subskillId":"chemistry_metals_q8","subject":"chemistry","chapter":"metals","topic":"Electrical Conductivity"}', 7),
  (4446, 964, 'Distinguish electrical conductivity from thermal conductivity.', 'text', 1, 'One concerns electric charge; the other concerns the transfer of heat.', '{"why":"Electric current and heat transfer are different processes, so the properties must not be confused.","sol":"Step 1: Electrical conductivity describes how readily a material allows electric charge to flow.\nStep 2: Thermal conductivity describes how readily a material transfers heat.\nStep 3: Both are common properties of metals, but they describe different processes.","steps":["Step 1: Electrical conductivity describes how readily a material allows electric charge to flow.","Step 2: Thermal conductivity describes how readily a material transfers heat.","Step 3: Both are common properties of metals, but they describe different processes."],"options":[],"conceptId":"chemistry_metals_electrical_conductivity","skillId":"chemistry_metals","subskillId":"chemistry_metals_q9","subject":"chemistry","chapter":"metals","topic":"Electrical Conductivity"}', 8),
  (4447, 965, 'Define malleability.', 'text', 1, 'Think about what happens when a metal is hammered.', '{"why":"The defining feature is the formation of sheets through permanent deformation without the material breaking easily.","sol":"Step 1: Identify the action applied to the metal.\nStep 2: Identify the shape the metal can take.\nStep 3: Include the fact that it does not break easily.","steps":["Step 1: Identify the action applied to the metal.","Step 2: Identify the shape the metal can take.","Step 3: Include the fact that it does not break easily."],"options":[],"conceptId":"chemistry_metals_malleability","skillId":"chemistry_metals","subskillId":"chemistry_metals_q1","subject":"chemistry","chapter":"metals","topic":"Malleability"}', 0),
  (4448, 965, 'Name one metal that can be rolled into thin sheets and state one use of the sheets.', 'text', 1, 'Consider the metal used to make kitchen foil.', '{"why":"Aluminium is sufficiently malleable to be rolled into thin foil.","sol":"Step 1: Identify a metal that can be rolled into thin sheets.\nStep 2: Give a practical use for those sheets.","steps":["Step 1: Identify a metal that can be rolled into thin sheets.","Step 2: Give a practical use for those sheets."],"options":[],"conceptId":"chemistry_metals_malleability","skillId":"chemistry_metals","subskillId":"chemistry_metals_q2","subject":"chemistry","chapter":"metals","topic":"Malleability"}', 1),
  (4449, 965, 'Explain how the structure of a metal allows it to be hammered into a new shape.', 'text', 1, 'Consider layers of ions and delocalised electrons.', '{"why":"The ability of the layers to move without the metallic bonding being lost explains why many metals can be shaped.","sol":"Step 1: State that metals contain layers of positive ions.\nStep 2: Explain that the layers can slide when force is applied.\nStep 3: Explain how delocalised electrons help maintain metallic bonding.","steps":["Step 1: State that metals contain layers of positive ions.","Step 2: Explain that the layers can slide when force is applied.","Step 3: Explain how delocalised electrons help maintain metallic bonding."],"options":[],"conceptId":"chemistry_metals_malleability","skillId":"chemistry_metals","subskillId":"chemistry_metals_q3","subject":"chemistry","chapter":"metals","topic":"Malleability"}', 2),
  (4450, 965, 'A learner hammers a piece of gold into a thin decorative sheet. Which property is demonstrated?', 'text', 1, 'Focus on the formation of a sheet, not a wire.', '{"why":"Malleability is the ability to form thin sheets under pressure without breaking easily.","sol":"Step 1: Identify the action: hammering.\nStep 2: Identify the result: a thin sheet.\nStep 3: Match this to the relevant physical property.","steps":["Step 1: Identify the action: hammering.","Step 2: Identify the result: a thin sheet.","Step 3: Match this to the relevant physical property."],"options":[],"conceptId":"chemistry_metals_malleability","skillId":"chemistry_metals","subskillId":"chemistry_metals_q4","subject":"chemistry","chapter":"metals","topic":"Malleability"}', 3),
  (4451, 965, 'A metal rod is hammered repeatedly but cracks instead of flattening. What does this observation suggest about its behaviour under the conditions used?', 'text', 1, 'Compare permanent shaping with breaking.', '{"why":"A brittle material tends to crack or break rather than undergo substantial plastic deformation. The observation alone does not establish that every sample of the metal behaves this way under all conditions.","sol":"Step 1: Observe whether the rod changes shape successfully.\nStep 2: Identify what happens when force is applied.\nStep 3: Describe its behaviour using the term brittle.","steps":["Step 1: Observe whether the rod changes shape successfully.","Step 2: Identify what happens when force is applied.","Step 3: Describe its behaviour using the term brittle."],"options":[],"conceptId":"chemistry_metals_malleability","skillId":"chemistry_metals","subskillId":"chemistry_metals_q5","subject":"chemistry","chapter":"metals","topic":"Malleability"}', 4),
  (4452, 965, 'Explain why aluminium is suitable for making thin packaging foil.', 'text', 1, 'Link the required shape to a physical property.', '{"why":"Malleability allows aluminium to be shaped into foil for packaging.","sol":"Step 1: Identify the required shape: a very thin sheet.\nStep 2: Name the property that allows a metal to form sheets.\nStep 3: Connect the property to aluminium''s use.","steps":["Step 1: Identify the required shape: a very thin sheet.","Step 2: Name the property that allows a metal to form sheets.","Step 3: Connect the property to aluminium''s use."],"options":[],"conceptId":"chemistry_metals_malleability","skillId":"chemistry_metals","subskillId":"chemistry_metals_q6","subject":"chemistry","chapter":"metals","topic":"Malleability"}', 5),
  (4453, 965, 'During hammering, layers of positive ions in a metal move past one another. What helps maintain the bonding between the layers?', 'text', 1, 'Consider the mobile electrons in metallic bonding.', '{"why":"The delocalised electrons are not attached to one particular ion and help hold the metal structure together as layers shift.","sol":"Step 1: Identify the particles that move in layers.\nStep 2: Recall that metals contain delocalised electrons.\nStep 3: State the attraction responsible for metallic bonding.","steps":["Step 1: Identify the particles that move in layers.","Step 2: Recall that metals contain delocalised electrons.","Step 3: State the attraction responsible for metallic bonding."],"options":[],"conceptId":"chemistry_metals_malleability","skillId":"chemistry_metals","subskillId":"chemistry_metals_q7","subject":"chemistry","chapter":"metals","topic":"Malleability"}', 6),
  (4454, 965, 'A student says, ''Malleability means a metal can be stretched into a wire.'' Identify the error and give the correct definition.', 'text', 1, 'Distinguish making sheets from making wires.', '{"why":"Malleability concerns sheet formation; ductility concerns drawing a material into wires.","sol":"Step 1: Identify the shape mentioned in the student''s statement.\nStep 2: Recall the property associated with drawing wires.\nStep 3: Give the correct definition of malleability.","steps":["Step 1: Identify the shape mentioned in the student''s statement.","Step 2: Recall the property associated with drawing wires.","Step 3: Give the correct definition of malleability."],"options":[],"conceptId":"chemistry_metals_malleability","skillId":"chemistry_metals","subskillId":"chemistry_metals_q8","subject":"chemistry","chapter":"metals","topic":"Malleability"}', 7),
  (4455, 965, 'A manufacturer must choose between two metals. Metal A can be rolled into sheets without cracking, while Metal B cracks under the same processing conditions. Which metal is more suitable for sheet production, and why?', 'text', 1, 'Use the observed behaviour rather than guessing from the names.', '{"why":"A suitable sheet metal must undergo substantial deformation without breaking under the manufacturing conditions.","sol":"Step 1: Identify which metal successfully forms sheets.\nStep 2: Relate this behaviour to malleability.\nStep 3: Use the comparison to justify the choice.","steps":["Step 1: Identify which metal successfully forms sheets.","Step 2: Relate this behaviour to malleability.","Step 3: Use the comparison to justify the choice."],"options":[],"conceptId":"chemistry_metals_malleability","skillId":"chemistry_metals","subskillId":"chemistry_metals_q9","subject":"chemistry","chapter":"metals","topic":"Malleability"}', 8),
  (4456, 966, 'Define ductility.', 'text', 1, 'Think about how a metal is shaped when making wire.', '{"why":"Ductility describes a material''s ability to undergo the deformation needed to form wires.","sol":"Step 1: Identify the shaping process.\nStep 2: Identify the product formed.\nStep 3: Include that the material does not break easily during the process.","steps":["Step 1: Identify the shaping process.","Step 2: Identify the product formed.","Step 3: Include that the material does not break easily during the process."],"options":[],"conceptId":"chemistry_metals_ductility","skillId":"chemistry_metals","subskillId":"chemistry_metals_q1","subject":"chemistry","chapter":"metals","topic":"Ductility"}', 0),
  (4457, 966, 'Name one ductile metal commonly used to make electrical wires.', 'text', 1, 'Consider the reddish-brown metal used in many electrical cables.', '{"why":"Copper is ductile, allowing it to be drawn into wires, and it is also a good electrical conductor.","sol":"Step 1: Identify a metal commonly used in electrical wiring.\nStep 2: Check that it can be drawn into thin strands.","steps":["Step 1: Identify a metal commonly used in electrical wiring.","Step 2: Check that it can be drawn into thin strands."],"options":[],"conceptId":"chemistry_metals_ductility","skillId":"chemistry_metals","subskillId":"chemistry_metals_q2","subject":"chemistry","chapter":"metals","topic":"Ductility"}', 1),
  (4458, 966, 'State the difference between ductility and malleability.', 'text', 1, 'Compare wires with sheets.', '{"why":"The two properties describe different ways a material can be permanently shaped.","sol":"Step 1: State what ductility allows a material to form.\nStep 2: State what malleability allows a material to form.\nStep 3: Contrast the two products.","steps":["Step 1: State what ductility allows a material to form.","Step 2: State what malleability allows a material to form.","Step 3: Contrast the two products."],"options":[],"conceptId":"chemistry_metals_ductility","skillId":"chemistry_metals","subskillId":"chemistry_metals_q3","subject":"chemistry","chapter":"metals","topic":"Ductility"}', 2),
  (4459, 966, 'A metal is drawn into a long, thin wire without breaking. Which physical property does this demonstrate?', 'text', 1, 'Look for the property associated with wire formation.', '{"why":"Ductility is the ability to be drawn into wires without breaking.","sol":"Step 1: Identify the final shape.\nStep 2: Recall the property associated with drawing wires.\nStep 3: State the property.","steps":["Step 1: Identify the final shape.","Step 2: Recall the property associated with drawing wires.","Step 3: State the property."],"options":[],"conceptId":"chemistry_metals_ductility","skillId":"chemistry_metals","subskillId":"chemistry_metals_q4","subject":"chemistry","chapter":"metals","topic":"Ductility"}', 3),
  (4460, 966, 'Explain why copper is suitable for making electrical cables.', 'text', 1, 'Consider both the shaping process and the movement of charge.', '{"why":"Electrical cables require a material that can be formed into wires and conduct electric current effectively.","sol":"Step 1: State the property that allows copper to be drawn into wires.\nStep 2: State the property that allows it to carry electric current.\nStep 3: Connect both properties to its use in cables.","steps":["Step 1: State the property that allows copper to be drawn into wires.","Step 2: State the property that allows it to carry electric current.","Step 3: Connect both properties to its use in cables."],"options":[],"conceptId":"chemistry_metals_ductility","skillId":"chemistry_metals","subskillId":"chemistry_metals_q5","subject":"chemistry","chapter":"metals","topic":"Ductility"}', 4),
  (4461, 966, 'A learner claims that a metal''s ability to form sheets proves that it is ductile. Explain why this conclusion is incorrect.', 'text', 1, 'Identify the property that specifically describes sheet formation.', '{"why":"The two properties are related forms of deformation but are defined by different shaping outcomes.","sol":"Step 1: Identify the shape produced.\nStep 2: Match sheet formation to the correct property.\nStep 3: State what ductility actually describes.","steps":["Step 1: Identify the shape produced.","Step 2: Match sheet formation to the correct property.","Step 3: State what ductility actually describes."],"options":[],"conceptId":"chemistry_metals_ductility","skillId":"chemistry_metals","subskillId":"chemistry_metals_q6","subject":"chemistry","chapter":"metals","topic":"Ductility"}', 5),
  (4462, 966, 'A manufacturer needs a metal for making long, thin wires. What property should the metal possess, and what should happen during wire drawing?', 'text', 1, 'Consider the desired shape and whether the metal must remain intact.', '{"why":"Ductility allows a metal to undergo the deformation required for wire production.","sol":"Step 1: Identify the required product.\nStep 2: Name the property associated with producing that product.\nStep 3: Describe the expected behaviour during drawing.","steps":["Step 1: Identify the required product.","Step 2: Name the property associated with producing that product.","Step 3: Describe the expected behaviour during drawing."],"options":[],"conceptId":"chemistry_metals_ductility","skillId":"chemistry_metals","subskillId":"chemistry_metals_q7","subject":"chemistry","chapter":"metals","topic":"Ductility"}', 6),
  (4463, 966, 'A metal wire breaks when pulled slightly during manufacturing. Does this observation show high ductility under those conditions? Explain.', 'text', 1, 'Compare the observed behaviour with the definition of ductility.', '{"why":"A ductile material should withstand the deformation required for drawing into wire without breaking easily. The result can depend on the metal and processing conditions.","sol":"Step 1: Recall what a ductile material can do.\nStep 2: Compare the definition with the wire''s behaviour.\nStep 3: State the conclusion limited to the conditions tested.","steps":["Step 1: Recall what a ductile material can do.","Step 2: Compare the definition with the wire''s behaviour.","Step 3: State the conclusion limited to the conditions tested."],"options":[],"conceptId":"chemistry_metals_ductility","skillId":"chemistry_metals","subskillId":"chemistry_metals_q8","subject":"chemistry","chapter":"metals","topic":"Ductility"}', 7),
  (4464, 966, 'Metal A can be drawn into a continuous wire, while Metal B breaks before a wire can be formed. Which metal is more ductile under the tested conditions? Explain.', 'text', 1, 'Use the ability to form a wire as the evidence.', '{"why":"The ability to withstand deformation during wire drawing is the defining feature of ductility.","sol":"Step 1: Identify which metal forms a continuous wire.\nStep 2: Relate that behaviour to ductility.\nStep 3: Compare it with the metal that breaks.","steps":["Step 1: Identify which metal forms a continuous wire.","Step 2: Relate that behaviour to ductility.","Step 3: Compare it with the metal that breaks."],"options":[],"conceptId":"chemistry_metals_ductility","skillId":"chemistry_metals","subskillId":"chemistry_metals_q9","subject":"chemistry","chapter":"metals","topic":"Ductility"}', 8),
  (4465, 967, 'State the general word equation for the reaction of a metal with oxygen.', 'text', 1, 'The product is a compound containing the metal and oxygen.', '{"why":"Many metals combine chemically with oxygen to form metal oxides.","sol":"Step 1: Identify the two reactants.\nStep 2: Identify the compound formed.\nStep 3: Write the word equation.","steps":["Step 1: Identify the two reactants.","Step 2: Identify the compound formed.","Step 3: Write the word equation."],"options":[],"conceptId":"chemistry_metals_chemical_properties_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q1","subject":"chemistry","chapter":"metals","topic":"Chemical Properties of Metals"}', 0),
  (4466, 967, 'Write a balanced chemical equation for the reaction between zinc and dilute hydrochloric acid.', 'text', 1, 'The products are zinc chloride and hydrogen gas.', '{"why":"Two HCl molecules supply the two chlorine atoms needed for zinc chloride and the two hydrogen atoms needed for hydrogen gas.","sol":"Step 1: Write Zn + HCl → ZnCl₂ + H₂.\nStep 2: Balance chlorine by placing 2 before HCl.\nStep 3: Check that zinc, hydrogen and chlorine atoms balance.","steps":["Step 1: Write Zn + HCl → ZnCl₂ + H₂.","Step 2: Balance chlorine by placing 2 before HCl.","Step 3: Check that zinc, hydrogen and chlorine atoms balance."],"options":[],"conceptId":"chemistry_metals_chemical_properties_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q2","subject":"chemistry","chapter":"metals","topic":"Chemical Properties of Metals"}', 1),
  (4467, 967, 'Describe the test for hydrogen gas.', 'text', 1, 'Use a lighted splint and state the observation.', '{"why":"The squeaky-pop test is the standard laboratory test for hydrogen, using a small sample and suitable safety precautions.","sol":"Step 1: Bring a lighted splint to a small sample of the gas using safe laboratory practice.\nStep 2: State the characteristic sound if hydrogen is present.","steps":["Step 1: Bring a lighted splint to a small sample of the gas using safe laboratory practice.","Step 2: State the characteristic sound if hydrogen is present."],"options":[],"conceptId":"chemistry_metals_chemical_properties_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q3","subject":"chemistry","chapter":"metals","topic":"Chemical Properties of Metals"}', 2),
  (4468, 967, 'A student burns magnesium in oxygen and obtains a white powder. Identify the product and write its balanced equation.', 'text', 1, 'Magnesium forms an oxide when it reacts with oxygen.', '{"why":"Two magnesium atoms react with one oxygen molecule to produce two formula units of magnesium oxide.","sol":"Step 1: Identify the metal and the gas reacting.\nStep 2: Write the formula of magnesium oxide as MgO.\nStep 3: Balance the oxygen molecule, O₂.\nStep 4: Balance the magnesium atoms.","steps":["Step 1: Identify the metal and the gas reacting.","Step 2: Write the formula of magnesium oxide as MgO.","Step 3: Balance the oxygen molecule, O₂.","Step 4: Balance the magnesium atoms."],"options":[],"conceptId":"chemistry_metals_chemical_properties_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q4","subject":"chemistry","chapter":"metals","topic":"Chemical Properties of Metals"}', 3),
  (4469, 967, 'Write a balanced equation for sodium reacting with cold water.', 'text', 1, 'The products are sodium hydroxide and hydrogen gas.', '{"why":"The balanced equation conserves two sodium atoms, four hydrogen atoms and two oxygen atoms on each side.","sol":"Step 1: Write Na + H₂O → NaOH + H₂.\nStep 2: Balance sodium by placing 2 before Na and NaOH.\nStep 3: Balance hydrogen and oxygen by placing 2 before H₂O.","steps":["Step 1: Write Na + H₂O → NaOH + H₂.","Step 2: Balance sodium by placing 2 before Na and NaOH.","Step 3: Balance hydrogen and oxygen by placing 2 before H₂O."],"options":[],"conceptId":"chemistry_metals_chemical_properties_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q5","subject":"chemistry","chapter":"metals","topic":"Chemical Properties of Metals"}', 4),
  (4470, 967, 'Zinc reacts with dilute hydrochloric acid and produces bubbles. Name the gas and explain how you would confirm its identity.', 'text', 1, 'Think of the gas produced when a reactive metal reacts with a dilute acid.', '{"why":"Many metals above hydrogen in the reactivity series release hydrogen gas from dilute hydrochloric acid.","sol":"Step 1: Recall the general reaction of a metal with a suitable dilute acid.\nStep 2: Identify the gas produced.\nStep 3: State the test and its positive observation.","steps":["Step 1: Recall the general reaction of a metal with a suitable dilute acid.","Step 2: Identify the gas produced.","Step 3: State the test and its positive observation."],"options":[],"conceptId":"chemistry_metals_chemical_properties_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q6","subject":"chemistry","chapter":"metals","topic":"Chemical Properties of Metals"}', 5),
  (4471, 967, 'Copper is placed in dilute hydrochloric acid, but no hydrogen bubbles appear. Explain the observation using the reactivity series.', 'text', 1, 'Compare copper with hydrogen in the series.', '{"why":"A metal must be more reactive than hydrogen to release hydrogen from a typical dilute, non-oxidising acid.","sol":"Step 1: Locate copper relative to hydrogen in the reactivity series.\nStep 2: Recall which metals can displace hydrogen from dilute acids.\nStep 3: Use this comparison to explain the observation.","steps":["Step 1: Locate copper relative to hydrogen in the reactivity series.","Step 2: Recall which metals can displace hydrogen from dilute acids.","Step 3: Use this comparison to explain the observation."],"options":[],"conceptId":"chemistry_metals_chemical_properties_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q7","subject":"chemistry","chapter":"metals","topic":"Chemical Properties of Metals"}', 6),
  (4472, 967, 'A learner writes the equation Mg + O₂ → MgO. Identify the problem and correct the equation.', 'text', 1, 'Count oxygen atoms on each side before adjusting magnesium.', '{"why":"A balanced equation must have the same number of atoms of each element on both sides.","sol":"Step 1: Count the oxygen atoms on each side.\nStep 2: Place 2 before MgO to balance oxygen.\nStep 3: Place 2 before Mg to balance magnesium.","steps":["Step 1: Count the oxygen atoms on each side.","Step 2: Place 2 before MgO to balance oxygen.","Step 3: Place 2 before Mg to balance magnesium."],"options":[],"conceptId":"chemistry_metals_chemical_properties_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q8","subject":"chemistry","chapter":"metals","topic":"Chemical Properties of Metals"}', 7),
  (4473, 967, 'Magnesium and zinc are separately reacted with equal volumes and concentrations of dilute hydrochloric acid under comparable conditions. Which metal would generally react more vigorously, and why?', 'text', 1, 'Compare their positions in the reactivity series.', '{"why":"Under comparable conditions, the more reactive metal generally reacts faster. The observed rate also depends on factors such as surface area and temperature.","sol":"Step 1: Locate magnesium and zinc in the reactivity series.\nStep 2: Identify which metal is higher in the series.\nStep 3: Connect its greater reactivity to the expected reaction rate.","steps":["Step 1: Locate magnesium and zinc in the reactivity series.","Step 2: Identify which metal is higher in the series.","Step 3: Connect its greater reactivity to the expected reaction rate."],"options":[],"conceptId":"chemistry_metals_chemical_properties_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q9","subject":"chemistry","chapter":"metals","topic":"Chemical Properties of Metals"}', 8),
  (4474, 968, 'What is the reactivity series?', 'text', 1, 'It arranges metals according to how readily they react.', '{"why":"The series compares the tendency of metals to react and helps predict chemical reactions.","sol":"Step 1: Identify what is being compared.\nStep 2: State that the metals are arranged in order.\nStep 3: Specify the direction of decreasing reactivity.","steps":["Step 1: Identify what is being compared.","Step 2: State that the metals are arranged in order.","Step 3: Specify the direction of decreasing reactivity."],"options":[],"conceptId":"chemistry_metals_reactivity_series","skillId":"chemistry_metals","subskillId":"chemistry_metals_q1","subject":"chemistry","chapter":"metals","topic":"Reactivity Series"}', 0),
  (4475, 968, 'Which is more reactive: zinc or copper?', 'text', 1, 'Find both metals in the reactivity series.', '{"why":"Zinc is higher than copper in the commonly used reactivity series.","sol":"Step 1: Locate zinc in the series.\nStep 2: Locate copper in the series.\nStep 3: Compare their positions.","steps":["Step 1: Locate zinc in the series.","Step 2: Locate copper in the series.","Step 3: Compare their positions."],"options":[],"conceptId":"chemistry_metals_reactivity_series","skillId":"chemistry_metals","subskillId":"chemistry_metals_q2","subject":"chemistry","chapter":"metals","topic":"Reactivity Series"}', 1),
  (4476, 968, 'Can copper displace zinc from zinc sulfate solution? Explain.', 'text', 1, 'A metal displaces another metal only if it is more reactive.', '{"why":"A less reactive metal cannot displace a more reactive metal from its salt solution.","sol":"Step 1: Compare copper and zinc in the series.\nStep 2: Identify which metal is more reactive.\nStep 3: Apply the rule for displacement.","steps":["Step 1: Compare copper and zinc in the series.","Step 2: Identify which metal is more reactive.","Step 3: Apply the rule for displacement."],"options":[],"conceptId":"chemistry_metals_reactivity_series","skillId":"chemistry_metals","subskillId":"chemistry_metals_q3","subject":"chemistry","chapter":"metals","topic":"Reactivity Series"}', 2),
  (4477, 968, 'Arrange magnesium, iron and silver in order of decreasing reactivity.', 'text', 1, 'Decreasing reactivity means most reactive first.', '{"why":"Magnesium is above iron, and iron is above silver in the commonly used reactivity series.","sol":"Step 1: Locate magnesium in the series.\nStep 2: Locate iron and silver.\nStep 3: List the metals from highest to lowest reactivity.","steps":["Step 1: Locate magnesium in the series.","Step 2: Locate iron and silver.","Step 3: List the metals from highest to lowest reactivity."],"options":[],"conceptId":"chemistry_metals_reactivity_series","skillId":"chemistry_metals","subskillId":"chemistry_metals_q4","subject":"chemistry","chapter":"metals","topic":"Reactivity Series"}', 3),
  (4478, 968, 'Explain why zinc produces hydrogen with dilute hydrochloric acid but copper does not normally do so.', 'text', 1, 'Use hydrogen as the reference point in the series.', '{"why":"Metals above hydrogen generally release hydrogen from suitable dilute acids; metals below hydrogen do not.","sol":"Step 1: Locate zinc relative to hydrogen.\nStep 2: Locate copper relative to hydrogen.\nStep 3: Apply the rule for displacement of hydrogen from dilute acids.","steps":["Step 1: Locate zinc relative to hydrogen.","Step 2: Locate copper relative to hydrogen.","Step 3: Apply the rule for displacement of hydrogen from dilute acids."],"options":[],"conceptId":"chemistry_metals_reactivity_series","skillId":"chemistry_metals","subskillId":"chemistry_metals_q5","subject":"chemistry","chapter":"metals","topic":"Reactivity Series"}', 4),
  (4479, 968, 'A strip of magnesium is placed in copper(II) sulfate solution. Predict whether a displacement reaction occurs and name the products.', 'text', 1, 'Magnesium is above copper in the reactivity series.', '{"why":"Magnesium is more reactive than copper and displaces copper from copper(II) sulfate solution.","sol":"Step 1: Compare magnesium with copper.\nStep 2: Determine whether magnesium can displace copper.\nStep 3: Write the products formed.","steps":["Step 1: Compare magnesium with copper.","Step 2: Determine whether magnesium can displace copper.","Step 3: Write the products formed."],"options":[],"conceptId":"chemistry_metals_reactivity_series","skillId":"chemistry_metals","subskillId":"chemistry_metals_q6","subject":"chemistry","chapter":"metals","topic":"Reactivity Series"}', 5),
  (4480, 968, 'A learner places iron in zinc sulfate solution and predicts that zinc will be deposited. Explain why this prediction is incorrect.', 'text', 1, 'Compare iron and zinc in the reactivity series.', '{"why":"A less reactive metal cannot displace a more reactive metal from its salt solution.","sol":"Step 1: Locate zinc and iron in the series.\nStep 2: Identify which metal is more reactive.\nStep 3: Apply the displacement rule.","steps":["Step 1: Locate zinc and iron in the series.","Step 2: Identify which metal is more reactive.","Step 3: Apply the displacement rule."],"options":[],"conceptId":"chemistry_metals_reactivity_series","skillId":"chemistry_metals","subskillId":"chemistry_metals_q7","subject":"chemistry","chapter":"metals","topic":"Reactivity Series"}', 6),
  (4481, 968, 'Three metals P, Q and R are tested. P displaces Q from Q''s salt solution, and Q displaces R from R''s salt solution. Arrange the three metals in decreasing reactivity.', 'text', 1, 'A metal that displaces another metal is more reactive than the displaced metal.', '{"why":"P is more reactive than Q, and Q is more reactive than R.","sol":"Step 1: Use the first observation to compare P and Q.\nStep 2: Use the second observation to compare Q and R.\nStep 3: Combine the two comparisons.","steps":["Step 1: Use the first observation to compare P and Q.","Step 2: Use the second observation to compare Q and R.","Step 3: Combine the two comparisons."],"options":[],"conceptId":"chemistry_metals_reactivity_series","skillId":"chemistry_metals","subskillId":"chemistry_metals_q8","subject":"chemistry","chapter":"metals","topic":"Reactivity Series"}', 7),
  (4482, 968, 'A student concludes that every metal higher in the reactivity series must react vigorously with cold water. Explain why this is incorrect.', 'text', 1, 'Consider the different behaviour of magnesium and iron with water.', '{"why":"The reactivity series helps predict trends, but it does not mean that every metal reacts vigorously with every reactant under the same conditions.","sol":"Step 1: Recall that the series compares general chemical reactivity.\nStep 2: Consider metals whose reactions with water require heating or steam.\nStep 3: Explain why the reaction depends on the metal and conditions.","steps":["Step 1: Recall that the series compares general chemical reactivity.","Step 2: Consider metals whose reactions with water require heating or steam.","Step 3: Explain why the reaction depends on the metal and conditions."],"options":[],"conceptId":"chemistry_metals_reactivity_series","skillId":"chemistry_metals","subskillId":"chemistry_metals_q9","subject":"chemistry","chapter":"metals","topic":"Reactivity Series"}', 8),
  (4483, 969, 'Define a metal displacement reaction.', 'text', 1, 'Compare the reactivity of the metal added with the metal in the compound.', '{"why":"The more reactive metal forms ions while the less reactive metal is produced as the free metal.","sol":"Step 1: Identify the two metals involved.\nStep 2: Compare their reactivities.\nStep 3: State what the more reactive metal does.","steps":["Step 1: Identify the two metals involved.","Step 2: Compare their reactivities.","Step 3: State what the more reactive metal does."],"options":[],"conceptId":"chemistry_metals_displacement_reactions","skillId":"chemistry_metals","subskillId":"chemistry_metals_q1","subject":"chemistry","chapter":"metals","topic":"Displacement Reactions"}', 0),
  (4484, 969, 'Write a balanced equation for zinc reacting with copper(II) sulfate solution.', 'text', 1, 'Zinc sulfate and copper are the products.', '{"why":"The equation is balanced, and zinc displaces the less reactive copper.","sol":"Step 1: Write zinc and copper(II) sulfate as the reactants.\nStep 2: Write zinc sulfate and copper as the products.\nStep 3: Check the number of atoms on both sides.","steps":["Step 1: Write zinc and copper(II) sulfate as the reactants.","Step 2: Write zinc sulfate and copper as the products.","Step 3: Check the number of atoms on both sides."],"options":[],"conceptId":"chemistry_metals_displacement_reactions","skillId":"chemistry_metals","subskillId":"chemistry_metals_q2","subject":"chemistry","chapter":"metals","topic":"Displacement Reactions"}', 1),
  (4485, 969, 'Why does copper not displace zinc from zinc sulfate solution?', 'text', 1, 'Compare copper and zinc in the reactivity series.', '{"why":"Only a more reactive metal can displace a less reactive metal from its compound.","sol":"Step 1: Identify which metal is more reactive.\nStep 2: Recall the rule for displacement.\nStep 3: Apply the rule to copper and zinc sulfate.","steps":["Step 1: Identify which metal is more reactive.","Step 2: Recall the rule for displacement.","Step 3: Apply the rule to copper and zinc sulfate."],"options":[],"conceptId":"chemistry_metals_displacement_reactions","skillId":"chemistry_metals","subskillId":"chemistry_metals_q3","subject":"chemistry","chapter":"metals","topic":"Displacement Reactions"}', 2),
  (4486, 969, 'Magnesium is added to copper(II) sulfate solution. Predict the products and write a balanced equation.', 'text', 1, 'Magnesium is more reactive than copper.', '{"why":"Magnesium displaces copper because magnesium is more reactive.","sol":"Step 1: Compare magnesium and copper in the reactivity series.\nStep 2: Identify the metal that will be displaced.\nStep 3: Write the salt formed by magnesium and the sulfate ion.\nStep 4: Write and check the equation.","steps":["Step 1: Compare magnesium and copper in the reactivity series.","Step 2: Identify the metal that will be displaced.","Step 3: Write the salt formed by magnesium and the sulfate ion.","Step 4: Write and check the equation."],"options":[],"conceptId":"chemistry_metals_displacement_reactions","skillId":"chemistry_metals","subskillId":"chemistry_metals_q4","subject":"chemistry","chapter":"metals","topic":"Displacement Reactions"}', 3),
  (4487, 969, 'A student places copper in silver nitrate solution. Predict whether a reaction occurs and write the balanced equation if it does.', 'text', 1, 'Copper is more reactive than silver.', '{"why":"Copper displaces silver because copper is more reactive. Two silver ions are needed for each copper atom that forms a copper(II) ion.","sol":"Step 1: Compare copper and silver in the reactivity series.\nStep 2: Determine whether copper can displace silver.\nStep 3: Write the products and balance the equation.","steps":["Step 1: Compare copper and silver in the reactivity series.","Step 2: Determine whether copper can displace silver.","Step 3: Write the products and balance the equation."],"options":[],"conceptId":"chemistry_metals_displacement_reactions","skillId":"chemistry_metals","subskillId":"chemistry_metals_q5","subject":"chemistry","chapter":"metals","topic":"Displacement Reactions"}', 4),
  (4488, 969, 'An iron nail is placed in blue copper(II) sulfate solution. State two expected observations and explain the chemical change.', 'text', 1, 'Think about the solid formed and the ions remaining in solution.', '{"why":"Copper metal is deposited while iron enters the solution as iron(II) ions.","sol":"Step 1: Determine whether iron can displace copper.\nStep 2: Identify the solid deposited on the nail.\nStep 3: Identify the iron salt formed in solution.\nStep 4: Connect these products to the observations.","steps":["Step 1: Determine whether iron can displace copper.","Step 2: Identify the solid deposited on the nail.","Step 3: Identify the iron salt formed in solution.","Step 4: Connect these products to the observations."],"options":[],"conceptId":"chemistry_metals_displacement_reactions","skillId":"chemistry_metals","subskillId":"chemistry_metals_q6","subject":"chemistry","chapter":"metals","topic":"Displacement Reactions"}', 5),
  (4489, 969, 'A student writes: Cu + ZnSO₄ → CuSO₄ + Zn. Explain the error.', 'text', 1, 'Check which metal is higher in the reactivity series.', '{"why":"The proposed equation predicts a reaction that is not supported by the relative reactivities of copper and zinc.","sol":"Step 1: Compare copper and zinc.\nStep 2: Identify the more reactive metal.\nStep 3: Apply the displacement rule to the proposed equation.","steps":["Step 1: Compare copper and zinc.","Step 2: Identify the more reactive metal.","Step 3: Apply the displacement rule to the proposed equation."],"options":[],"conceptId":"chemistry_metals_displacement_reactions","skillId":"chemistry_metals","subskillId":"chemistry_metals_q7","subject":"chemistry","chapter":"metals","topic":"Displacement Reactions"}', 6),
  (4490, 969, 'In the reaction Zn + CuSO₄ → ZnSO₄ + Cu, identify which metal loses electrons and which ions gain electrons.', 'text', 1, 'Oxidation is electron loss; reduction is electron gain.', '{"why":"Zinc is oxidised and copper(II) ions are reduced, so the displacement reaction is also a redox reaction.","sol":"Step 1: Identify the metal that becomes ions.\nStep 2: Write the electron-loss process.\nStep 3: Identify the metal ions that become solid atoms.\nStep 4: Write the electron-gain process.","steps":["Step 1: Identify the metal that becomes ions.","Step 2: Write the electron-loss process.","Step 3: Identify the metal ions that become solid atoms.","Step 4: Write the electron-gain process."],"options":[],"conceptId":"chemistry_metals_displacement_reactions","skillId":"chemistry_metals","subskillId":"chemistry_metals_q8","subject":"chemistry","chapter":"metals","topic":"Displacement Reactions"}', 7),
  (4491, 969, 'Metal P displaces metal Q from Q''s salt solution, but Q cannot displace P from P''s salt solution. What can you conclude about their relative reactivities?', 'text', 1, 'Successful displacement identifies the more reactive metal.', '{"why":"A more reactive metal can displace a less reactive metal from its compound, but not the other way around.","sol":"Step 1: Interpret what it means for P to displace Q.\nStep 2: Use the second observation to check the relationship.\nStep 3: State the relative order.","steps":["Step 1: Interpret what it means for P to displace Q.","Step 2: Use the second observation to check the relationship.","Step 3: State the relative order."],"options":[],"conceptId":"chemistry_metals_displacement_reactions","skillId":"chemistry_metals","subskillId":"chemistry_metals_q9","subject":"chemistry","chapter":"metals","topic":"Displacement Reactions"}', 8),
  (4492, 970, 'Define an ore.', 'text', 1, 'Include both the presence of a useful metal compound and the practicality of extraction.', '{"why":"The presence of a metal alone does not make a material a useful ore; extraction must be economically worthwhile.","sol":"Step 1: State that an ore is a naturally occurring material.\nStep 2: Identify what useful substance it contains.\nStep 3: Include the economic practicality of extracting the metal.","steps":["Step 1: State that an ore is a naturally occurring material.","Step 2: Identify what useful substance it contains.","Step 3: Include the economic practicality of extracting the metal."],"options":[],"conceptId":"chemistry_metals_ores","skillId":"chemistry_metals","subskillId":"chemistry_metals_q1","subject":"chemistry","chapter":"metals","topic":"Ores"}', 0),
  (4493, 970, 'Name the main metal obtained from haematite.', 'text', 1, 'Haematite is mainly iron(III) oxide, Fe₂O₃.', '{"why":"Haematite is an important ore of iron.","sol":"Step 1: Identify the formula of the useful compound.\nStep 2: Identify the metal in the formula.","steps":["Step 1: Identify the formula of the useful compound.","Step 2: Identify the metal in the formula."],"options":[],"conceptId":"chemistry_metals_ores","skillId":"chemistry_metals","subskillId":"chemistry_metals_q2","subject":"chemistry","chapter":"metals","topic":"Ores"}', 1),
  (4494, 970, 'What is gangue?', 'text', 1, 'It is the unwanted rocky material mixed with an ore.', '{"why":"Gangue does not provide the desired metal and is generally separated during ore processing.","sol":"Step 1: Identify the valuable mineral in an ore.\nStep 2: Identify the unwanted material surrounding or mixed with it.\nStep 3: Name that unwanted material.","steps":["Step 1: Identify the valuable mineral in an ore.","Step 2: Identify the unwanted material surrounding or mixed with it.","Step 3: Name that unwanted material."],"options":[],"conceptId":"chemistry_metals_ores","skillId":"chemistry_metals","subskillId":"chemistry_metals_q3","subject":"chemistry","chapter":"metals","topic":"Ores"}', 2),
  (4495, 970, 'A rock contains copper compounds, but extracting the copper costs more than the value of the copper recovered using available technology. Would it necessarily be classified as an economically workable ore? Explain.', 'text', 1, 'An ore must be practical to extract economically.', '{"why":"Ore classification depends not only on metal content but also on whether extraction is economically practical.","sol":"Step 1: Identify whether the rock contains a useful metal compound.\nStep 2: Compare the cost of extraction with the economic value recovered.\nStep 3: Decide whether the material meets the economic requirement.","steps":["Step 1: Identify whether the rock contains a useful metal compound.","Step 2: Compare the cost of extraction with the economic value recovered.","Step 3: Decide whether the material meets the economic requirement."],"options":[],"conceptId":"chemistry_metals_ores","skillId":"chemistry_metals","subskillId":"chemistry_metals_q4","subject":"chemistry","chapter":"metals","topic":"Ores"}', 3),
  (4496, 970, 'A student claims that haematite is pure iron. Correct the statement.', 'text', 1, 'Recall the chemical formula of haematite.', '{"why":"Iron in haematite is chemically combined with oxygen; processing is needed to obtain metallic iron.","sol":"Step 1: Identify the main compound in haematite.\nStep 2: Distinguish a metal compound from the pure metal.\nStep 3: Correct the statement.","steps":["Step 1: Identify the main compound in haematite.","Step 2: Distinguish a metal compound from the pure metal.","Step 3: Correct the statement."],"options":[],"conceptId":"chemistry_metals_ores","skillId":"chemistry_metals","subskillId":"chemistry_metals_q5","subject":"chemistry","chapter":"metals","topic":"Ores"}', 4),
  (4497, 970, 'Match each ore to its principal metal: bauxite, zinc blende and galena.', 'text', 1, 'Bauxite contains aluminium-bearing minerals; the other two are sulfide ores.', '{"why":"These are important natural sources of aluminium, zinc and lead, respectively.","sol":"Step 1: Recall the metal associated with bauxite.\nStep 2: Recall the formula ZnS for zinc blende.\nStep 3: Recall the formula PbS for galena.","steps":["Step 1: Recall the metal associated with bauxite.","Step 2: Recall the formula ZnS for zinc blende.","Step 3: Recall the formula PbS for galena."],"options":[],"conceptId":"chemistry_metals_ores","skillId":"chemistry_metals","subskillId":"chemistry_metals_q6","subject":"chemistry","chapter":"metals","topic":"Ores"}', 5),
  (4498, 970, 'A sample of ore contains copper-bearing minerals and sand. Identify the useful component and the gangue.', 'text', 1, 'One component contains the desired metal; the other is unwanted material.', '{"why":"Gangue is the unwanted rocky or earthy material mixed with the valuable mineral.","sol":"Step 1: Identify which component contains copper.\nStep 2: Identify the unwanted sand.\nStep 3: Apply the term gangue to the unwanted material.","steps":["Step 1: Identify which component contains copper.","Step 2: Identify the unwanted sand.","Step 3: Apply the term gangue to the unwanted material."],"options":[],"conceptId":"chemistry_metals_ores","skillId":"chemistry_metals","subskillId":"chemistry_metals_q7","subject":"chemistry","chapter":"metals","topic":"Ores"}', 6),
  (4499, 970, 'Why is it incorrect to say that every rock containing a trace of metal is an ore?', 'text', 1, 'Consider the amount of metal and the cost of extraction.', '{"why":"An ore must contain a useful metal or metal compound in a concentration that makes extraction worthwhile.","sol":"Step 1: Recognise that a trace of metal may be present in many rocks.\nStep 2: Consider whether enough useful material can be recovered.\nStep 3: Apply the economic requirement in the definition of an ore.","steps":["Step 1: Recognise that a trace of metal may be present in many rocks.","Step 2: Consider whether enough useful material can be recovered.","Step 3: Apply the economic requirement in the definition of an ore."],"options":[],"conceptId":"chemistry_metals_ores","skillId":"chemistry_metals","subskillId":"chemistry_metals_q8","subject":"chemistry","chapter":"metals","topic":"Ores"}', 7),
  (4500, 970, 'A mineral contains a valuable metal compound and unwanted rocky material. Explain why the mineral-bearing material must be processed before the pure metal can be obtained.', 'text', 1, 'Distinguish separating unwanted material from chemically extracting the metal.', '{"why":"Ores are naturally occurring materials, not necessarily pure metals. The specific processing method depends on the ore and the metal''s chemical reactivity.","sol":"Step 1: Identify the valuable metal compound.\nStep 2: Identify the unwanted gangue.\nStep 3: Explain that unwanted material may need separating and the compound must then be processed to obtain the metal.","steps":["Step 1: Identify the valuable metal compound.","Step 2: Identify the unwanted gangue.","Step 3: Explain that unwanted material may need separating and the compound must then be processed to obtain the metal."],"options":[],"conceptId":"chemistry_metals_ores","skillId":"chemistry_metals","subskillId":"chemistry_metals_q9","subject":"chemistry","chapter":"metals","topic":"Ores"}', 8);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (4501, 971, 'Define concentration of an ore.', 'text', 1, 'Consider what is removed from the ore before extraction.', '{"why":"Removing unwanted material enriches the ore before further extraction.","sol":"Step 1: Identify the unwanted material in an ore.\nStep 2: State what the concentration process removes.\nStep 3: Explain how the valuable mineral proportion changes.","steps":["Step 1: Identify the unwanted material in an ore.","Step 2: State what the concentration process removes.","Step 3: Explain how the valuable mineral proportion changes."],"options":[],"conceptId":"chemistry_metals_concentration_of_ores","skillId":"chemistry_metals","subskillId":"chemistry_metals_q1","subject":"chemistry","chapter":"metals","topic":"Concentration of Ores"}', 0),
  (4502, 971, 'Name the concentration method that uses a magnet to separate suitable magnetic minerals from non-magnetic gangue.', 'text', 1, 'The method depends on magnetic properties.', '{"why":"A magnetic separator attracts magnetic particles while non-magnetic material is separated.","sol":"Step 1: Identify the property used for separation.\nStep 2: Name the method that uses that property.","steps":["Step 1: Identify the property used for separation.","Step 2: Name the method that uses that property."],"options":[],"conceptId":"chemistry_metals_concentration_of_ores","skillId":"chemistry_metals","subskillId":"chemistry_metals_q2","subject":"chemistry","chapter":"metals","topic":"Concentration of Ores"}', 1),
  (4503, 971, 'Why is froth flotation used to concentrate many sulfide ores?', 'text', 1, 'Think about mineral particles attaching to air bubbles.', '{"why":"Froth flotation uses differences in surface properties to concentrate suitable minerals.","sol":"Step 1: Identify the role of the bubbles.\nStep 2: Explain where the valuable particles collect.\nStep 3: State what is achieved by collecting the froth.","steps":["Step 1: Identify the role of the bubbles.","Step 2: Explain where the valuable particles collect.","Step 3: State what is achieved by collecting the froth."],"options":[],"conceptId":"chemistry_metals_concentration_of_ores","skillId":"chemistry_metals","subskillId":"chemistry_metals_q3","subject":"chemistry","chapter":"metals","topic":"Concentration of Ores"}', 2),
  (4504, 971, 'A sample contains a valuable mineral and large amounts of sand. Explain why the ore may be concentrated before metal extraction.', 'text', 1, 'Consider the effects of processing unnecessary material.', '{"why":"Concentration enriches an ore and can improve the efficiency of subsequent extraction stages.","sol":"Step 1: Identify the sand as unwanted material.\nStep 2: State what concentration removes.\nStep 3: Explain the benefit for later processing.","steps":["Step 1: Identify the sand as unwanted material.","Step 2: State what concentration removes.","Step 3: Explain the benefit for later processing."],"options":[],"conceptId":"chemistry_metals_concentration_of_ores","skillId":"chemistry_metals","subskillId":"chemistry_metals_q4","subject":"chemistry","chapter":"metals","topic":"Concentration of Ores"}', 3),
  (4505, 971, 'An ore mineral is magnetic while the gangue is non-magnetic. Describe a suitable method and the principle involved.', 'text', 1, 'Use the difference in magnetic behaviour.', '{"why":"The method relies on a difference in magnetic properties between the valuable mineral and gangue.","sol":"Step 1: Select the appropriate concentration method.\nStep 2: Explain what the separator attracts.\nStep 3: Explain how the gangue is separated.","steps":["Step 1: Select the appropriate concentration method.","Step 2: Explain what the separator attracts.","Step 3: Explain how the gangue is separated."],"options":[],"conceptId":"chemistry_metals_concentration_of_ores","skillId":"chemistry_metals","subskillId":"chemistry_metals_q5","subject":"chemistry","chapter":"metals","topic":"Concentration of Ores"}', 4),
  (4506, 971, 'A learner proposes gravity separation for an ore whose valuable mineral and gangue have very similar densities. Explain why the method may be ineffective.', 'text', 1, 'The method relies on a particular physical difference.', '{"why":"Gravity separation works best when density differences allow the particles to behave differently.","sol":"Step 1: State the property used in gravity separation.\nStep 2: Compare the densities of the two materials.\nStep 3: Explain how their similar densities affect separation.","steps":["Step 1: State the property used in gravity separation.","Step 2: Compare the densities of the two materials.","Step 3: Explain how their similar densities affect separation."],"options":[],"conceptId":"chemistry_metals_concentration_of_ores","skillId":"chemistry_metals","subskillId":"chemistry_metals_q6","subject":"chemistry","chapter":"metals","topic":"Concentration of Ores"}', 5),
  (4507, 971, 'Describe how froth flotation can separate suitable sulfide mineral particles from gangue.', 'text', 1, 'Include grinding, water, air bubbles and froth collection.', '{"why":"Froth flotation separates particles through differences in surface properties.","sol":"Step 1: Explain that the ore is finely ground and mixed with water and suitable reagents.\nStep 2: State what happens when air is introduced.\nStep 3: Explain where the valuable particles collect.\nStep 4: State how the concentrate is recovered.","steps":["Step 1: Explain that the ore is finely ground and mixed with water and suitable reagents.","Step 2: State what happens when air is introduced.","Step 3: Explain where the valuable particles collect.","Step 4: State how the concentrate is recovered."],"options":[],"conceptId":"chemistry_metals_concentration_of_ores","skillId":"chemistry_metals","subskillId":"chemistry_metals_q7","subject":"chemistry","chapter":"metals","topic":"Concentration of Ores"}', 6),
  (4508, 971, 'Does concentrating an ore mean that pure metal has already been obtained? Explain.', 'text', 1, 'Distinguish separating a mineral from extracting a metal from its compound.', '{"why":"Concentration is a physical separation stage, while obtaining a metal from its compound generally requires further processing.","sol":"Step 1: State the purpose of concentration.\nStep 2: Identify what the valuable mineral may still contain.\nStep 3: Explain why further processing is needed.","steps":["Step 1: State the purpose of concentration.","Step 2: Identify what the valuable mineral may still contain.","Step 3: Explain why further processing is needed."],"options":[],"conceptId":"chemistry_metals_concentration_of_ores","skillId":"chemistry_metals","subskillId":"chemistry_metals_q8","subject":"chemistry","chapter":"metals","topic":"Concentration of Ores"}', 7),
  (4509, 971, 'A mineral-processing plant has three ores: Ore A has a useful density difference, Ore B has a magnetic mineral and non-magnetic gangue, and Ore C is a suitable sulfide ore for which surface properties allow bubble attachment. Match each ore to a likely concentration method.', 'text', 1, 'Match the property described to the method that uses it.', '{"why":"Each method exploits a different physical property, and suitability depends on the actual ore and gangue.","sol":"Step 1: Match density differences to a separation method.\nStep 2: Match magnetic behaviour to a separation method.\nStep 3: Match bubble attachment and surface properties to a separation method.","steps":["Step 1: Match density differences to a separation method.","Step 2: Match magnetic behaviour to a separation method.","Step 3: Match bubble attachment and surface properties to a separation method."],"options":[],"conceptId":"chemistry_metals_concentration_of_ores","skillId":"chemistry_metals","subskillId":"chemistry_metals_q9","subject":"chemistry","chapter":"metals","topic":"Concentration of Ores"}', 8),
  (4510, 972, 'Define reduction in the context of extracting a metal from its oxide.', 'text', 1, 'Consider what happens to the oxygen in the metal oxide.', '{"why":"Removing oxygen from a metal oxide is a common form of reduction in metal extraction.","sol":"Step 1: Identify the starting material as a metal oxide.\nStep 2: State what happens to its oxygen.\nStep 3: Connect the change to the metal produced.","steps":["Step 1: Identify the starting material as a metal oxide.","Step 2: State what happens to its oxygen.","Step 3: Connect the change to the metal produced."],"options":[],"conceptId":"chemistry_metals_reduction","skillId":"chemistry_metals","subskillId":"chemistry_metals_q1","subject":"chemistry","chapter":"metals","topic":"Reduction"}', 0),
  (4511, 972, 'Write a balanced equation for the reduction of iron(III) oxide by carbon monoxide.', 'text', 1, 'The products are iron and carbon dioxide.', '{"why":"The equation contains two iron atoms, three carbon atoms and six oxygen atoms on each side.","sol":"Step 1: Write Fe₂O₃ + CO → Fe + CO₂.\nStep 2: Balance iron by placing 2 before Fe.\nStep 3: Balance carbon and oxygen by placing 3 before CO and CO₂.","steps":["Step 1: Write Fe₂O₃ + CO → Fe + CO₂.","Step 2: Balance iron by placing 2 before Fe.","Step 3: Balance carbon and oxygen by placing 3 before CO and CO₂."],"options":[],"conceptId":"chemistry_metals_reduction","skillId":"chemistry_metals","subskillId":"chemistry_metals_q2","subject":"chemistry","chapter":"metals","topic":"Reduction"}', 1),
  (4512, 972, 'Why is aluminium extracted by electrolysis rather than ordinary reduction with carbon?', 'text', 1, 'Compare aluminium''s reactivity with carbon.', '{"why":"Very reactive metals generally require electrolysis rather than ordinary carbon reduction.","sol":"Step 1: Identify aluminium as highly reactive.\nStep 2: Recall that its oxide is very stable.\nStep 3: State the method used to extract aluminium.","steps":["Step 1: Identify aluminium as highly reactive.","Step 2: Recall that its oxide is very stable.","Step 3: State the method used to extract aluminium."],"options":[],"conceptId":"chemistry_metals_reduction","skillId":"chemistry_metals","subskillId":"chemistry_metals_q3","subject":"chemistry","chapter":"metals","topic":"Reduction"}', 2),
  (4513, 972, 'In the reaction ZnO + C → Zn + CO, explain why zinc oxide is reduced.', 'text', 1, 'Compare the oxygen in zinc oxide with the zinc product.', '{"why":"Removal of oxygen from a metal oxide is reduction.","sol":"Step 1: Identify zinc oxide as the starting compound.\nStep 2: Identify where its oxygen goes.\nStep 3: State how this change defines reduction.","steps":["Step 1: Identify zinc oxide as the starting compound.","Step 2: Identify where its oxygen goes.","Step 3: State how this change defines reduction."],"options":[],"conceptId":"chemistry_metals_reduction","skillId":"chemistry_metals","subskillId":"chemistry_metals_q4","subject":"chemistry","chapter":"metals","topic":"Reduction"}', 3),
  (4514, 972, 'Balance this equation: Fe₂O₃ + CO → Fe + CO₂.', 'text', 1, 'Start by balancing iron, then carbon and oxygen.', '{"why":"The balanced equation conserves all iron, carbon and oxygen atoms.","sol":"Step 1: Place 2 before Fe to balance iron.\nStep 2: Place 3 before CO₂ to balance carbon dioxide.\nStep 3: Place 3 before CO to balance carbon and oxygen.","steps":["Step 1: Place 2 before Fe to balance iron.","Step 2: Place 3 before CO₂ to balance carbon dioxide.","Step 3: Place 3 before CO to balance carbon and oxygen."],"options":[],"conceptId":"chemistry_metals_reduction","skillId":"chemistry_metals","subskillId":"chemistry_metals_q5","subject":"chemistry","chapter":"metals","topic":"Reduction"}', 4),
  (4515, 972, 'In Fe₂O₃ + 3CO → 2Fe + 3CO₂, identify the substance reduced and the substance oxidised.', 'text', 1, 'Reduction removes oxygen; oxidation adds oxygen.', '{"why":"Iron(III) oxide loses oxygen, and carbon monoxide gains oxygen. Both changes occur in the same redox reaction.","sol":"Step 1: Identify which reactant loses oxygen.\nStep 2: Identify which reactant gains oxygen.\nStep 3: Name the substance undergoing each change.","steps":["Step 1: Identify which reactant loses oxygen.","Step 2: Identify which reactant gains oxygen.","Step 3: Name the substance undergoing each change."],"options":[],"conceptId":"chemistry_metals_reduction","skillId":"chemistry_metals","subskillId":"chemistry_metals_q6","subject":"chemistry","chapter":"metals","topic":"Reduction"}', 5),
  (4516, 972, 'A learner states that concentrating an ore and reducing a metal oxide are the same process. Explain the difference.', 'text', 1, 'One process is physical separation; the other is a chemical change.', '{"why":"Concentration prepares the ore; reduction converts a suitable metal compound into the metal.","sol":"Step 1: State what concentration removes.\nStep 2: State what reduction changes.\nStep 3: Explain why their purposes differ.","steps":["Step 1: State what concentration removes.","Step 2: State what reduction changes.","Step 3: Explain why their purposes differ."],"options":[],"conceptId":"chemistry_metals_reduction","skillId":"chemistry_metals","subskillId":"chemistry_metals_q7","subject":"chemistry","chapter":"metals","topic":"Reduction"}', 6),
  (4517, 972, 'Why can carbon reduce some metal oxides but not normally aluminium oxide?', 'text', 1, 'Compare the metals'' reactivities with carbon.', '{"why":"The suitable extraction method depends on the reactivity of the metal and the stability of its compound.","sol":"Step 1: Recognise that carbon can remove oxygen from some metal oxides.\nStep 2: Compare aluminium''s reactivity with carbon.\nStep 3: Identify the usual extraction method for aluminium.","steps":["Step 1: Recognise that carbon can remove oxygen from some metal oxides.","Step 2: Compare aluminium''s reactivity with carbon.","Step 3: Identify the usual extraction method for aluminium."],"options":[],"conceptId":"chemistry_metals_reduction","skillId":"chemistry_metals","subskillId":"chemistry_metals_q8","subject":"chemistry","chapter":"metals","topic":"Reduction"}', 7),
  (4518, 972, 'In a reduction process, a metal oxide loses oxygen while another substance gains that oxygen. Explain why this is a redox reaction.', 'text', 1, 'Use the definitions of reduction and oxidation together.', '{"why":"Reduction and oxidation occur together as oxygen is transferred between substances.","sol":"Step 1: Identify the substance losing oxygen.\nStep 2: Identify the substance gaining oxygen.\nStep 3: Apply the definitions of reduction and oxidation.","steps":["Step 1: Identify the substance losing oxygen.","Step 2: Identify the substance gaining oxygen.","Step 3: Apply the definitions of reduction and oxidation."],"options":[],"conceptId":"chemistry_metals_reduction","skillId":"chemistry_metals","subskillId":"chemistry_metals_q9","subject":"chemistry","chapter":"metals","topic":"Reduction"}', 8),
  (4519, 973, 'Name the iron ore commonly used in the blast furnace and give its formula.', 'text', 1, 'It contains iron(III) oxide.', '{"why":"Haematite contains iron(III) oxide, which is reduced to iron in the blast furnace.","sol":"Step 1: Recall the common ore used for extracting iron.\nStep 2: State its chemical formula.","steps":["Step 1: Recall the common ore used for extracting iron.","Step 2: State its chemical formula."],"options":[],"conceptId":"chemistry_metals_extraction_of_iron","skillId":"chemistry_metals","subskillId":"chemistry_metals_q1","subject":"chemistry","chapter":"metals","topic":"Extraction of Iron"}', 0),
  (4520, 973, 'Write the balanced equation for the reduction of iron(III) oxide by carbon monoxide.', 'text', 1, 'The products are iron and carbon dioxide.', '{"why":"The balanced equation has 2 iron atoms, 3 carbon atoms, and 6 oxygen atoms on each side.","sol":"Step 1: Write Fe₂O₃ + CO → Fe + CO₂.\nStep 2: Balance iron: place 2 before Fe.\nStep 3: Balance oxygen and carbon by placing 3 before CO and 3 before CO₂.","steps":["Step 1: Write Fe₂O₃ + CO → Fe + CO₂.","Step 2: Balance iron: place 2 before Fe.","Step 3: Balance oxygen and carbon by placing 3 before CO and 3 before CO₂."],"options":[],"conceptId":"chemistry_metals_extraction_of_iron","skillId":"chemistry_metals","subskillId":"chemistry_metals_q2","subject":"chemistry","chapter":"metals","topic":"Extraction of Iron"}', 1),
  (4521, 973, 'Explain how limestone helps remove silicon dioxide impurity from iron ore.', 'text', 1, 'Limestone forms calcium oxide when heated.', '{"why":"The slag separates from the molten iron and helps remove the unwanted impurity.","sol":"Step 1: State what limestone produces on heating.\nStep 2: Explain what calcium oxide reacts with.\nStep 3: Name the product.","steps":["Step 1: State what limestone produces on heating.","Step 2: Explain what calcium oxide reacts with.","Step 3: Name the product."],"options":[],"conceptId":"chemistry_metals_extraction_of_iron","skillId":"chemistry_metals","subskillId":"chemistry_metals_q3","subject":"chemistry","chapter":"metals","topic":"Extraction of Iron"}', 2),
  (4522, 973, 'A learner says that carbon monoxide oxidises iron(III) oxide to iron. Identify the error and correct the statement.', 'text', 1, 'Check whether oxygen is being removed or added.', '{"why":"Reduction involves oxygen removal. CO gains oxygen and is converted into CO₂.","sol":"Step 1: Compare Fe₂O₃ with the iron product.\nStep 2: Notice that oxygen is removed from Fe₂O₃.\nStep 3: Name the process and identify the role of CO.","steps":["Step 1: Compare Fe₂O₃ with the iron product.","Step 2: Notice that oxygen is removed from Fe₂O₃.","Step 3: Name the process and identify the role of CO."],"options":[],"conceptId":"chemistry_metals_extraction_of_iron","skillId":"chemistry_metals","subskillId":"chemistry_metals_q4","subject":"chemistry","chapter":"metals","topic":"Extraction of Iron"}', 3),
  (4523, 973, 'Why is a continuous supply of hot air introduced into a blast furnace?', 'text', 1, 'Consider what the oxygen does to coke.', '{"why":"The furnace needs high temperatures for the reactions and for the iron to melt.","sol":"Step 1: Identify the gas supplied by air that supports combustion.\nStep 2: Explain what happens when coke burns.\nStep 3: State why the heat is useful.","steps":["Step 1: Identify the gas supplied by air that supports combustion.","Step 2: Explain what happens when coke burns.","Step 3: State why the heat is useful."],"options":[],"conceptId":"chemistry_metals_extraction_of_iron","skillId":"chemistry_metals","subskillId":"chemistry_metals_q5","subject":"chemistry","chapter":"metals","topic":"Extraction of Iron"}', 4),
  (4524, 973, 'How many moles of iron can theoretically form from 3 moles of Fe₂O₃ if carbon monoxide is in excess?', 'text', 1, 'Use the ratio from the balanced equation.', '{"why":"The ratio of Fe₂O₃ to Fe is 1:2, so 3 × 2 = 6 moles.","sol":"Step 1: Write Fe₂O₃ + 3CO → 2Fe + 3CO₂.\nStep 2: Read the mole ratio: 1 mole Fe₂O₃ produces 2 moles Fe.\nStep 3: Multiply 3 moles Fe₂O₃ by 2.","steps":["Step 1: Write Fe₂O₃ + 3CO → 2Fe + 3CO₂.","Step 2: Read the mole ratio: 1 mole Fe₂O₃ produces 2 moles Fe.","Step 3: Multiply 3 moles Fe₂O₃ by 2."],"options":[],"conceptId":"chemistry_metals_extraction_of_iron","skillId":"chemistry_metals","subskillId":"chemistry_metals_q6","subject":"chemistry","chapter":"metals","topic":"Extraction of Iron"}', 5),
  (4525, 973, 'Write the equation for the decomposition of limestone and identify the solid product.', 'text', 1, 'Calcium carbonate forms calcium oxide and carbon dioxide.', '{"why":"Calcium oxide reacts with acidic silicon dioxide impurity to form slag.","sol":"Step 1: Write the formula of calcium carbonate.\nStep 2: Write the two products formed on heating.\nStep 3: Check that calcium, carbon, and oxygen atoms balance.","steps":["Step 1: Write the formula of calcium carbonate.","Step 2: Write the two products formed on heating.","Step 3: Check that calcium, carbon, and oxygen atoms balance."],"options":[],"conceptId":"chemistry_metals_extraction_of_iron","skillId":"chemistry_metals","subskillId":"chemistry_metals_q7","subject":"chemistry","chapter":"metals","topic":"Extraction of Iron"}', 6),
  (4526, 973, 'A furnace produces calcium oxide, but the ore contains silicon dioxide. Write the reaction that removes this impurity and name the product.', 'text', 1, 'Calcium oxide combines with silicon dioxide.', '{"why":"The reaction converts the unwanted silica into slag that can be separated from the molten iron.","sol":"Step 1: Write the reactants: CaO and SiO₂.\nStep 2: Combine them to form calcium silicate.\nStep 3: Check the number of atoms on each side.","steps":["Step 1: Write the reactants: CaO and SiO₂.","Step 2: Combine them to form calcium silicate.","Step 3: Check the number of atoms on each side."],"options":[],"conceptId":"chemistry_metals_extraction_of_iron","skillId":"chemistry_metals","subskillId":"chemistry_metals_q8","subject":"chemistry","chapter":"metals","topic":"Extraction of Iron"}', 7),
  (4527, 973, 'Explain the difference between the reducing agent and the flux in iron extraction.', 'text', 1, 'One removes oxygen from iron oxide; the other helps remove impurities.', '{"why":"Reduction produces iron from iron oxide, while slag formation removes unwanted impurities.","sol":"Step 1: Identify the reducing agent in the furnace.\nStep 2: Identify the material used as the flux source.\nStep 3: State the different jobs they perform.","steps":["Step 1: Identify the reducing agent in the furnace.","Step 2: Identify the material used as the flux source.","Step 3: State the different jobs they perform."],"options":[],"conceptId":"chemistry_metals_extraction_of_iron","skillId":"chemistry_metals","subskillId":"chemistry_metals_q9","subject":"chemistry","chapter":"metals","topic":"Extraction of Iron"}', 8),
  (4528, 974, 'Give two properties of copper that make it suitable for electrical wiring.', 'text', 1, 'Consider electricity and the ability to form wires.', '{"why":"Copper conducts current efficiently and can be drawn into long, thin wires.","sol":"Step 1: Identify the property that allows current to pass easily.\nStep 2: Identify the property that allows copper to be drawn into thin wires.","steps":["Step 1: Identify the property that allows current to pass easily.","Step 2: Identify the property that allows copper to be drawn into thin wires."],"options":[],"conceptId":"chemistry_metals_uses_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q1","subject":"chemistry","chapter":"metals","topic":"Uses of Metals"}', 0),
  (4529, 974, 'Explain why aluminium alloys are suitable for aircraft structures.', 'text', 1, 'Think about mass and strength.', '{"why":"Reducing aircraft mass can reduce the energy required for flight.","sol":"Step 1: State the density-related advantage of aluminium alloys.\nStep 2: Explain why useful strength is also important.\nStep 3: Connect both properties to aircraft design.","steps":["Step 1: State the density-related advantage of aluminium alloys.","Step 2: Explain why useful strength is also important.","Step 3: Connect both properties to aircraft design."],"options":[],"conceptId":"chemistry_metals_uses_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q2","subject":"chemistry","chapter":"metals","topic":"Uses of Metals"}', 1),
  (4530, 974, 'What is galvanising, and how does it help protect iron or steel?', 'text', 1, 'A layer of zinc is applied to the surface.', '{"why":"The coating reduces the exposure of iron to conditions that cause corrosion.","sol":"Step 1: Name the coating process.\nStep 2: Identify the metal coating.\nStep 3: Explain barrier protection and, where applicable, sacrificial protection.","steps":["Step 1: Name the coating process.","Step 2: Identify the metal coating.","Step 3: Explain barrier protection and, where applicable, sacrificial protection."],"options":[],"conceptId":"chemistry_metals_uses_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q3","subject":"chemistry","chapter":"metals","topic":"Uses of Metals"}', 2),
  (4531, 974, 'A student suggests using copper for a saucepan because copper is ductile. Explain why this is not the strongest reason for that use.', 'text', 1, 'Consider the function of a saucepan.', '{"why":"A property''s relevance depends on the function being explained.","sol":"Step 1: Identify the main job of a saucepan.\nStep 2: Select the property most directly related to that job.\nStep 3: Explain the relevance of ductility.","steps":["Step 1: Identify the main job of a saucepan.","Step 2: Select the property most directly related to that job.","Step 3: Explain the relevance of ductility."],"options":[],"conceptId":"chemistry_metals_uses_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q4","subject":"chemistry","chapter":"metals","topic":"Uses of Metals"}', 3),
  (4532, 974, 'A manufacturer must choose between copper and aluminium for a long overhead electricity cable. State one advantage of aluminium and one design consideration.', 'text', 1, 'Compare density and electrical resistance.', '{"why":"Material choice depends on both mass and electrical performance, not on a single property.","sol":"Step 1: Recall that aluminium has lower density than copper.\nStep 2: Explain why lower mass matters for a long cable.\nStep 3: Remember that conductivity and cable dimensions also affect performance.","steps":["Step 1: Recall that aluminium has lower density than copper.","Step 2: Explain why lower mass matters for a long cable.","Step 3: Remember that conductivity and cable dimensions also affect performance."],"options":[],"conceptId":"chemistry_metals_uses_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q5","subject":"chemistry","chapter":"metals","topic":"Uses of Metals"}', 4),
  (4533, 974, 'Why is steel commonly used in bridges rather than pure iron?', 'text', 1, 'Compare the mechanical properties of steel and pure iron.', '{"why":"The exact properties depend on the composition and treatment of the steel.","sol":"Step 1: Identify the need for a bridge material to support heavy loads.\nStep 2: Recall that steel is an alloy of iron with carbon and sometimes other elements.\nStep 3: Explain the useful mechanical properties of appropriately selected steel.","steps":["Step 1: Identify the need for a bridge material to support heavy loads.","Step 2: Recall that steel is an alloy of iron with carbon and sometimes other elements.","Step 3: Explain the useful mechanical properties of appropriately selected steel."],"options":[],"conceptId":"chemistry_metals_uses_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q6","subject":"chemistry","chapter":"metals","topic":"Uses of Metals"}', 5),
  (4534, 974, 'A steel gate is left outdoors and begins to rust. Explain why painting it can slow rusting and state one limitation of this method.', 'text', 1, 'Think about what must reach the iron surface.', '{"why":"Barrier protection works only while the coating adequately covers the surface.","sol":"Step 1: Identify the conditions required for rusting.\nStep 2: Explain how paint separates the iron from its surroundings.\nStep 3: Consider what happens when the paint cracks or peels.","steps":["Step 1: Identify the conditions required for rusting.","Step 2: Explain how paint separates the iron from its surroundings.","Step 3: Consider what happens when the paint cracks or peels."],"options":[],"conceptId":"chemistry_metals_uses_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q7","subject":"chemistry","chapter":"metals","topic":"Uses of Metals"}', 6),
  (4535, 974, 'Gold and iron are both metals, but gold is preferred for jewellery that must resist corrosion. Explain why.', 'text', 1, 'Compare their chemical reactivity.', '{"why":"Iron can react with oxygen and water to form rust, while gold is far less likely to corrode.","sol":"Step 1: Recall the relative positions of gold and iron in the reactivity series.\nStep 2: Explain which metal reacts less readily under ordinary conditions.\nStep 3: Connect this difference to appearance and durability.","steps":["Step 1: Recall the relative positions of gold and iron in the reactivity series.","Step 2: Explain which metal reacts less readily under ordinary conditions.","Step 3: Connect this difference to appearance and durability."],"options":[],"conceptId":"chemistry_metals_uses_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q8","subject":"chemistry","chapter":"metals","topic":"Uses of Metals"}', 7),
  (4536, 974, 'Lead can shield against some ionising radiation. Explain why its use must still be controlled.', 'text', 1, 'Consider a hazard that is unrelated to its shielding ability.', '{"why":"A useful physical property does not remove a material''s chemical or health hazards.","sol":"Step 1: State the useful property of lead for shielding.\nStep 2: Identify the health hazard associated with lead.\nStep 3: Explain the need for safe handling and disposal.","steps":["Step 1: State the useful property of lead for shielding.","Step 2: Identify the health hazard associated with lead.","Step 3: Explain the need for safe handling and disposal."],"options":[],"conceptId":"chemistry_metals_uses_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q9","subject":"chemistry","chapter":"metals","topic":"Uses of Metals"}', 8),
  (4537, 975, 'Define rusting and name the substance formed.', 'text', 1, 'Include iron, oxygen, water and the name of rust.', '{"why":"Rust is commonly represented as Fe₂O₃·xH₂O.","sol":"Step 1: State that rusting is a form of corrosion of iron.\nStep 2: Identify the two essential environmental substances.\nStep 3: Name the product formed.","steps":["Step 1: State that rusting is a form of corrosion of iron.","Step 2: Identify the two essential environmental substances.","Step 3: Name the product formed."],"options":[],"conceptId":"chemistry_metals_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q1","subject":"chemistry","chapter":"metals","topic":"Rusting"}', 0),
  (4538, 975, 'What happens to iron in the half-equation Fe → Fe²⁺ + 2e⁻?', 'text', 1, 'Check whether electrons are gained or lost.', '{"why":"Oxidation is the loss of electrons.","sol":"Step 1: Observe that two electrons appear among the products.\nStep 2: Recognise that the iron atom loses electrons.\nStep 3: Name the process.","steps":["Step 1: Observe that two electrons appear among the products.","Step 2: Recognise that the iron atom loses electrons.","Step 3: Name the process."],"options":[],"conceptId":"chemistry_metals_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q2","subject":"chemistry","chapter":"metals","topic":"Rusting"}', 1),
  (4539, 975, 'Explain why rusting can weaken an iron structure over time.', 'text', 1, 'Think about the metal being converted into a flaky corrosion product.', '{"why":"Rust does not reliably protect the iron beneath it from further corrosion.","sol":"Step 1: Explain what happens to the iron during corrosion.\nStep 2: Describe the nature of ordinary rust.\nStep 3: Connect continued corrosion to the structure''s strength.","steps":["Step 1: Explain what happens to the iron during corrosion.","Step 2: Describe the nature of ordinary rust.","Step 3: Connect continued corrosion to the structure''s strength."],"options":[],"conceptId":"chemistry_metals_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q3","subject":"chemistry","chapter":"metals","topic":"Rusting"}', 2),
  (4540, 975, 'A learner describes rust as pure iron oxide with a fixed formula Fe₂O₃. Correct the learner''s statement.', 'text', 1, 'Consider the meaning of the word hydrated.', '{"why":"Rust is not accurately described by assuming every sample has the same fixed water content.","sol":"Step 1: Recall the accepted school-level name for rust.\nStep 2: Explain what hydrated indicates.\nStep 3: Write the usual representation.","steps":["Step 1: Recall the accepted school-level name for rust.","Step 2: Explain what hydrated indicates.","Step 3: Write the usual representation."],"options":[],"conceptId":"chemistry_metals_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q4","subject":"chemistry","chapter":"metals","topic":"Rusting"}', 3),
  (4541, 975, 'Explain why the half-equation Fe → Fe²⁺ + 2e⁻ represents oxidation even though oxygen is not shown.', 'text', 1, 'Use the electron definition of oxidation.', '{"why":"Electron transfer provides a general definition of oxidation and reduction.","sol":"Step 1: Identify the electrons on the right-hand side.\nStep 2: Determine whether iron loses or gains electrons.\nStep 3: Apply the definition of oxidation.","steps":["Step 1: Identify the electrons on the right-hand side.","Step 2: Determine whether iron loses or gains electrons.","Step 3: Apply the definition of oxidation."],"options":[],"conceptId":"chemistry_metals_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q5","subject":"chemistry","chapter":"metals","topic":"Rusting"}', 4),
  (4542, 975, 'An iron nail has a reddish-brown coating, while an aluminium object has a thin, dull oxide coating. Why should the two coatings not automatically be treated as equally protective?', 'text', 1, 'Compare flaky rust with the oxide layer on aluminium.', '{"why":"The protective effect of a corrosion product depends on its physical structure and adherence.","sol":"Step 1: Identify the substance formed on iron.\nStep 2: Recall the protective behaviour of aluminium oxide.\nStep 3: Explain how the nature of each coating affects further corrosion.","steps":["Step 1: Identify the substance formed on iron.","Step 2: Recall the protective behaviour of aluminium oxide.","Step 3: Explain how the nature of each coating affects further corrosion."],"options":[],"conceptId":"chemistry_metals_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q6","subject":"chemistry","chapter":"metals","topic":"Rusting"}', 5),
  (4543, 975, 'A steel bridge support develops rust, and engineers discover that its cross-section has decreased. Explain the connection.', 'text', 1, 'The iron is being consumed during corrosion.', '{"why":"A reduced cross-section can increase the stress carried by the remaining metal.","sol":"Step 1: State what happens to iron as it rusts.\nStep 2: Explain why the amount of sound metal can decrease.\nStep 3: Connect the decrease to the ability to carry a load.","steps":["Step 1: State what happens to iron as it rusts.","Step 2: Explain why the amount of sound metal can decrease.","Step 3: Connect the decrease to the ability to carry a load."],"options":[],"conceptId":"chemistry_metals_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q7","subject":"chemistry","chapter":"metals","topic":"Rusting"}', 6),
  (4544, 975, 'Distinguish between rusting and corrosion using one example of each.', 'text', 1, 'One term is specific to iron; the other is broader.', '{"why":"Rusting is one type of corrosion, but not all corrosion produces rust.","sol":"Step 1: Define corrosion generally.\nStep 2: Define rusting specifically.\nStep 3: Give an example involving iron and another metal.","steps":["Step 1: Define corrosion generally.","Step 2: Define rusting specifically.","Step 3: Give an example involving iron and another metal."],"options":[],"conceptId":"chemistry_metals_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q8","subject":"chemistry","chapter":"metals","topic":"Rusting"}', 7),
  (4545, 975, 'Why is the word equation for rusting not enough to specify one exact, balanced chemical equation for every rust sample?', 'text', 1, 'Think about the composition of hydrated rust.', '{"why":"The word equation communicates the overall substances involved without claiming a universal fixed composition.","sol":"Step 1: Recall the formula Fe₂O₃·xH₂O.\nStep 2: Explain what x represents.\nStep 3: Relate the variable water content to the overall product.","steps":["Step 1: Recall the formula Fe₂O₃·xH₂O.","Step 2: Explain what x represents.","Step 3: Relate the variable water content to the overall product."],"options":[],"conceptId":"chemistry_metals_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q9","subject":"chemistry","chapter":"metals","topic":"Rusting"}', 8),
  (4546, 976, 'State the two essential conditions for ordinary rusting of iron.', 'text', 1, 'One comes from air and the other from moisture.', '{"why":"Both must be available for ordinary rusting of iron to occur.","sol":"Step 1: Identify the gas involved in rusting.\nStep 2: Identify the liquid needed for the process.","steps":["Step 1: Identify the gas involved in rusting.","Step 2: Identify the liquid needed for the process."],"options":[],"conceptId":"chemistry_metals_conditions_for_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q1","subject":"chemistry","chapter":"metals","topic":"Conditions for Rusting"}', 0),
  (4547, 976, 'Why is an iron nail in dry air expected to show little or no rust?', 'text', 1, 'One of the essential conditions has been removed.', '{"why":"Oxygen alone is insufficient for ordinary rusting.","sol":"Step 1: Identify the condition supplied by air.\nStep 2: Determine whether water is present.\nStep 3: Apply the two-condition rule.","steps":["Step 1: Identify the condition supplied by air.","Step 2: Determine whether water is present.","Step 3: Apply the two-condition rule."],"options":[],"conceptId":"chemistry_metals_conditions_for_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q2","subject":"chemistry","chapter":"metals","topic":"Conditions for Rusting"}', 1),
  (4548, 976, 'Explain why anhydrous calcium chloride is placed in the test tube containing a nail and dry air.', 'text', 1, 'It removes something from the air.', '{"why":"The experiment tests whether iron rusts when oxygen is available but water is excluded.","sol":"Step 1: Identify the substance absorbed by anhydrous calcium chloride.\nStep 2: Explain what happens to the moisture in the tube.\nStep 3: Connect this to rusting.","steps":["Step 1: Identify the substance absorbed by anhydrous calcium chloride.","Step 2: Explain what happens to the moisture in the tube.","Step 3: Connect this to rusting."],"options":[],"conceptId":"chemistry_metals_conditions_for_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q3","subject":"chemistry","chapter":"metals","topic":"Conditions for Rusting"}', 2),
  (4549, 976, 'Three nails are placed in separate tubes: A contains air and water, B contains boiled water covered with oil, and C contains dry air. Predict which nail should rust and explain why.', 'text', 1, 'Check whether oxygen and water are both available in each tube.', '{"why":"Only tube A provides both essential conditions.","sol":"Step 1: Identify the conditions in tube A.\nStep 2: Identify which condition is excluded in tube B.\nStep 3: Identify which condition is excluded in tube C.\nStep 4: Apply the rule that both oxygen and water are required.","steps":["Step 1: Identify the conditions in tube A.","Step 2: Identify which condition is excluded in tube B.","Step 3: Identify which condition is excluded in tube C.","Step 4: Apply the rule that both oxygen and water are required."],"options":[],"conceptId":"chemistry_metals_conditions_for_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q4","subject":"chemistry","chapter":"metals","topic":"Conditions for Rusting"}', 3),
  (4550, 976, 'Why must boiled water be covered with oil in the experiment investigating rusting?', 'text', 1, 'Boiling removes dissolved oxygen, but the water can absorb oxygen again.', '{"why":"Without the oil layer, the experiment would not reliably exclude oxygen.","sol":"Step 1: State what boiling does to dissolved gases.\nStep 2: Explain what could happen when the water contacts air again.\nStep 3: State the function of the oil layer.","steps":["Step 1: State what boiling does to dissolved gases.","Step 2: Explain what could happen when the water contacts air again.","Step 3: State the function of the oil layer."],"options":[],"conceptId":"chemistry_metals_conditions_for_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q5","subject":"chemistry","chapter":"metals","topic":"Conditions for Rusting"}', 4),
  (4551, 976, 'A student uses anhydrous calcium chloride in a tube but leaves the tube open in a humid laboratory. Explain why the experiment may fail.', 'text', 1, 'Consider the moisture entering from the surroundings.', '{"why":"A valid test requires the dry condition to be maintained throughout the experiment.","sol":"Step 1: Identify the purpose of the calcium chloride.\nStep 2: Consider what humid air introduces.\nStep 3: Explain how the test condition could change.","steps":["Step 1: Identify the purpose of the calcium chloride.","Step 2: Consider what humid air introduces.","Step 3: Explain how the test condition could change."],"options":[],"conceptId":"chemistry_metals_conditions_for_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q6","subject":"chemistry","chapter":"metals","topic":"Conditions for Rusting"}', 5),
  (4552, 976, 'A nail rusts faster in salt water than in fresh water. Does this prove that salt is essential for rusting? Explain.', 'text', 1, 'Compare what is necessary with what changes the speed.', '{"why":"Iron can rust in ordinary water exposed to oxygen even when no salt has been added.","sol":"Step 1: Recall the two essential conditions.\nStep 2: Identify the effect of dissolved salt.\nStep 3: Distinguish the occurrence of rusting from its rate.","steps":["Step 1: Recall the two essential conditions.","Step 2: Identify the effect of dissolved salt.","Step 3: Distinguish the occurrence of rusting from its rate."],"options":[],"conceptId":"chemistry_metals_conditions_for_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q7","subject":"chemistry","chapter":"metals","topic":"Conditions for Rusting"}', 6),
  (4553, 976, 'Why should the nails in the three test tubes be cleaned and made as similar as possible before the experiment?', 'text', 1, 'Think about making a fair comparison.', '{"why":"Controlling other variables makes the conclusion more reliable.","sol":"Step 1: Identify the variable being investigated.\nStep 2: Consider how existing rust or different nail sizes could affect observations.\nStep 3: Explain why other conditions should be kept similar.","steps":["Step 1: Identify the variable being investigated.","Step 2: Consider how existing rust or different nail sizes could affect observations.","Step 3: Explain why other conditions should be kept similar."],"options":[],"conceptId":"chemistry_metals_conditions_for_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q8","subject":"chemistry","chapter":"metals","topic":"Conditions for Rusting"}', 7),
  (4554, 976, 'A learner concludes that oxygen is unnecessary because a nail in water still contains oxygen atoms in its H₂O molecules. Explain the error.', 'text', 1, 'Distinguish water molecules from oxygen gas.', '{"why":"The presence of oxygen atoms within water molecules does not mean that oxygen gas is available for the rusting process.","sol":"Step 1: Identify the two conditions being tested.\nStep 2: Distinguish oxygen gas from oxygen chemically bonded in water.\nStep 3: Explain what the experiment is designed to establish.","steps":["Step 1: Identify the two conditions being tested.","Step 2: Distinguish oxygen gas from oxygen chemically bonded in water.","Step 3: Explain what the experiment is designed to establish."],"options":[],"conceptId":"chemistry_metals_conditions_for_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q9","subject":"chemistry","chapter":"metals","topic":"Conditions for Rusting"}', 8),
  (4555, 977, 'Explain how painting prevents rusting of iron.', 'text', 1, 'Consider what an intact paint layer keeps away from iron.', '{"why":"Painting protects iron while the barrier remains intact.","sol":"Step 1: Identify the substances needed for ordinary rusting.\nStep 2: Explain how paint separates the iron from the environment.\nStep 3: State one limitation.","steps":["Step 1: Identify the substances needed for ordinary rusting.","Step 2: Explain how paint separates the iron from the environment.","Step 3: State one limitation."],"options":[],"conceptId":"chemistry_metals_prevention_of_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q1","subject":"chemistry","chapter":"metals","topic":"Prevention of Rusting"}', 0),
  (4556, 977, 'Define galvanising and state the metal used.', 'text', 1, 'The coating is more reactive than iron.', '{"why":"Zinc is more reactive than iron and can corrode preferentially.","sol":"Step 1: Name the coating process.\nStep 2: Identify the coating metal.\nStep 3: State how the coating protects iron.","steps":["Step 1: Name the coating process.","Step 2: Identify the coating metal.","Step 3: State how the coating protects iron."],"options":[],"conceptId":"chemistry_metals_prevention_of_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q2","subject":"chemistry","chapter":"metals","topic":"Prevention of Rusting"}', 1),
  (4557, 977, 'What is sacrificial protection?', 'text', 1, 'A more reactive metal is allowed to corrode instead of the iron.', '{"why":"The sacrificial metal supplies the oxidation process that would otherwise damage the protected iron.","sol":"Step 1: Identify the metal being protected.\nStep 2: Identify the role of the more reactive metal.\nStep 3: Explain which metal corrodes preferentially.","steps":["Step 1: Identify the metal being protected.","Step 2: Identify the role of the more reactive metal.","Step 3: Explain which metal corrodes preferentially."],"options":[],"conceptId":"chemistry_metals_prevention_of_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q3","subject":"chemistry","chapter":"metals","topic":"Prevention of Rusting"}', 2),
  (4558, 977, 'A painted steel gate begins to rust at a deep scratch. Explain why the paint protected the surrounding surface but not the scratched area.', 'text', 1, 'The paint barrier is no longer continuous at the scratch.', '{"why":"Barrier protection depends on the coating covering the metal adequately.","sol":"Step 1: State the function of the paint.\nStep 2: Identify what happens at the scratch.\nStep 3: Explain why rusting can occur there.","steps":["Step 1: State the function of the paint.","Step 2: Identify what happens at the scratch.","Step 3: Explain why rusting can occur there."],"options":[],"conceptId":"chemistry_metals_prevention_of_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q4","subject":"chemistry","chapter":"metals","topic":"Prevention of Rusting"}', 3),
  (4559, 977, 'A learner says zinc protects iron only by forming a barrier. Explain the additional protection zinc can provide.', 'text', 1, 'Compare the reactivity of zinc with iron.', '{"why":"Sacrificial protection can continue even when a small area of iron is exposed.","sol":"Step 1: State which metal is more reactive.\nStep 2: Explain which metal can oxidise preferentially.\nStep 3: Name the type of protection.","steps":["Step 1: State which metal is more reactive.","Step 2: Explain which metal can oxidise preferentially.","Step 3: Name the type of protection."],"options":[],"conceptId":"chemistry_metals_prevention_of_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q5","subject":"chemistry","chapter":"metals","topic":"Prevention of Rusting"}', 4),
  (4560, 977, 'Why might oiling be more suitable for a machine part than for a large outdoor bridge?', 'text', 1, 'Consider movement, maintenance and how long the coating remains in place.', '{"why":"A protection method should suit the shape, use and environment of the object.","sol":"Step 1: State how oil protects a metal.\nStep 2: Consider what moving parts do to an oil film.\nStep 3: Compare the maintenance demands of machine parts and a large structure.","steps":["Step 1: State how oil protects a metal.","Step 2: Consider what moving parts do to an oil film.","Step 3: Compare the maintenance demands of machine parts and a large structure."],"options":[],"conceptId":"chemistry_metals_prevention_of_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q6","subject":"chemistry","chapter":"metals","topic":"Prevention of Rusting"}', 5),
  (4561, 977, 'A steel water pipe is buried underground in a corrosive environment. Explain how attaching a suitable magnesium block may protect the pipe.', 'text', 1, 'Magnesium is more reactive than iron.', '{"why":"Sacrificial protection depends on the electrochemical connection and continued availability of the sacrificial metal.","sol":"Step 1: Compare the reactivity of magnesium and iron.\nStep 2: Identify which metal oxidises preferentially.\nStep 3: Explain why the magnesium block must remain suitably connected and be checked.","steps":["Step 1: Compare the reactivity of magnesium and iron.","Step 2: Identify which metal oxidises preferentially.","Step 3: Explain why the magnesium block must remain suitably connected and be checked."],"options":[],"conceptId":"chemistry_metals_prevention_of_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q7","subject":"chemistry","chapter":"metals","topic":"Prevention of Rusting"}', 6),
  (4562, 977, 'A steel object is electroplated with a less reactive metal. Explain why damage to the coating may allow local corrosion.', 'text', 1, 'The coating may no longer cover the underlying steel, and different metals can behave differently when in contact.', '{"why":"Electroplating is not automatically equivalent to galvanising; the electrochemical behaviour of the coating matters.","sol":"Step 1: Explain the barrier function of an intact coating.\nStep 2: State what happens when the coating is damaged.\nStep 3: Avoid assuming every metal coating protects exposed iron sacrificially.","steps":["Step 1: Explain the barrier function of an intact coating.","Step 2: State what happens when the coating is damaged.","Step 3: Avoid assuming every metal coating protects exposed iron sacrificially."],"options":[],"conceptId":"chemistry_metals_prevention_of_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q8","subject":"chemistry","chapter":"metals","topic":"Prevention of Rusting"}', 7),
  (4563, 977, 'Why can stainless steel resist corrosion better than ordinary carbon steel, and why is it incorrect to say it can never corrode?', 'text', 1, 'Consider the role of chromium and its protective oxide layer.', '{"why":"Corrosion resistance depends on the alloy composition and the environment.","sol":"Step 1: Identify an important element in stainless steel.\nStep 2: Explain the protective surface film it helps form.\nStep 3: State why environmental conditions still matter.","steps":["Step 1: Identify an important element in stainless steel.","Step 2: Explain the protective surface film it helps form.","Step 3: State why environmental conditions still matter."],"options":[],"conceptId":"chemistry_metals_prevention_of_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q9","subject":"chemistry","chapter":"metals","topic":"Prevention of Rusting"}', 8),
  (4564, 978, 'Define an alloy and give one example.', 'text', 1, 'It contains a metal mixed with one or more other elements.', '{"why":"Alloys combine elements to produce materials with useful properties.","sol":"Step 1: State that an alloy is a mixture.\nStep 2: Mention the metal and other element or elements.\nStep 3: Give a valid example.","steps":["Step 1: State that an alloy is a mixture.","Step 2: Mention the metal and other element or elements.","Step 3: Give a valid example."],"options":[],"conceptId":"chemistry_metals_alloys","skillId":"chemistry_metals","subskillId":"chemistry_metals_q1","subject":"chemistry","chapter":"metals","topic":"Alloys"}', 0),
  (4565, 978, 'Explain why many alloys are harder than their pure metals.', 'text', 1, 'Think about the movement of layers of atoms.', '{"why":"This can increase hardness, although the effect depends on the alloy''s composition and treatment.","sol":"Step 1: Describe the arrangement of atoms in a pure metal.\nStep 2: Explain how different-sized atoms affect the arrangement.\nStep 3: Connect the disturbance to the movement of layers.","steps":["Step 1: Describe the arrangement of atoms in a pure metal.","Step 2: Explain how different-sized atoms affect the arrangement.","Step 3: Connect the disturbance to the movement of layers."],"options":[],"conceptId":"chemistry_metals_alloys","skillId":"chemistry_metals","subskillId":"chemistry_metals_q2","subject":"chemistry","chapter":"metals","topic":"Alloys"}', 1),
  (4566, 978, 'Name the main elements in brass and bronze.', 'text', 1, 'Both are copper-based alloys, but their second main elements differ.', '{"why":"The names distinguish two different copper-based alloy families.","sol":"Step 1: Recall the composition of brass.\nStep 2: Recall the composition of traditional bronze.","steps":["Step 1: Recall the composition of brass.","Step 2: Recall the composition of traditional bronze."],"options":[],"conceptId":"chemistry_metals_alloys","skillId":"chemistry_metals","subskillId":"chemistry_metals_q3","subject":"chemistry","chapter":"metals","topic":"Alloys"}', 2),
  (4567, 978, 'A learner states that an alloy is always a compound with a fixed chemical formula. Correct the statement.', 'text', 1, 'Consider whether alloy compositions can vary.', '{"why":"Alloys are generally described by their constituent elements and composition rather than one universal molecular formula.","sol":"Step 1: Recall the definition of an alloy.\nStep 2: Distinguish a mixture from a pure compound.\nStep 3: Explain whether the proportions must always be fixed.","steps":["Step 1: Recall the definition of an alloy.","Step 2: Distinguish a mixture from a pure compound.","Step 3: Explain whether the proportions must always be fixed."],"options":[],"conceptId":"chemistry_metals_alloys","skillId":"chemistry_metals","subskillId":"chemistry_metals_q4","subject":"chemistry","chapter":"metals","topic":"Alloys"}', 3),
  (4568, 978, 'A student argues that adding another element must always make a metal harder. Explain why this conclusion is incorrect.', 'text', 1, 'Alloy properties depend on composition and processing.', '{"why":"The effect of alloying is not identical for every metal-element combination.","sol":"Step 1: Explain why different-sized atoms can increase hardness in many alloys.\nStep 2: Recognise that different alloying elements have different effects.\nStep 3: Consider composition and heat treatment.","steps":["Step 1: Explain why different-sized atoms can increase hardness in many alloys.","Step 2: Recognise that different alloying elements have different effects.","Step 3: Consider composition and heat treatment."],"options":[],"conceptId":"chemistry_metals_alloys","skillId":"chemistry_metals","subskillId":"chemistry_metals_q5","subject":"chemistry","chapter":"metals","topic":"Alloys"}', 4),
  (4569, 978, 'A workshop needs a copper-based alloy for decorative door fittings. Explain why brass may be suitable and identify its main elements.', 'text', 1, 'Consider appearance, workability and composition.', '{"why":"Material choice depends on the properties required for the component.","sol":"Step 1: Identify the main elements in brass.\nStep 2: State one useful property of brass for decorative fittings.\nStep 3: Connect the property to the intended use.","steps":["Step 1: Identify the main elements in brass.","Step 2: State one useful property of brass for decorative fittings.","Step 3: Connect the property to the intended use."],"options":[],"conceptId":"chemistry_metals_alloys","skillId":"chemistry_metals","subskillId":"chemistry_metals_q6","subject":"chemistry","chapter":"metals","topic":"Alloys"}', 5),
  (4570, 978, 'Explain how chromium improves the corrosion resistance of suitable stainless-steel grades.', 'text', 1, 'It helps form a thin protective oxide layer.', '{"why":"The protective film separates the metal from the environment under suitable conditions.","sol":"Step 1: Identify chromium as an alloying element.\nStep 2: Describe the protective surface film.\nStep 3: Explain how the film affects further corrosion.","steps":["Step 1: Identify chromium as an alloying element.","Step 2: Describe the protective surface film.","Step 3: Explain how the film affects further corrosion."],"options":[],"conceptId":"chemistry_metals_alloys","skillId":"chemistry_metals","subskillId":"chemistry_metals_q7","subject":"chemistry","chapter":"metals","topic":"Alloys"}', 6),
  (4571, 978, 'A designer must choose between ordinary steel and a suitable aluminium alloy for a lightweight structural component. Explain one reason to choose the aluminium alloy and one consideration before deciding.', 'text', 1, 'Compare density with the strength and operating requirements.', '{"why":"A low-density material is not automatically the best choice; it must meet the structural requirements.","sol":"Step 1: Compare the density of aluminium alloys and steel.\nStep 2: Explain the benefit of lower mass.\nStep 3: Identify a performance or cost factor that still needs checking.","steps":["Step 1: Compare the density of aluminium alloys and steel.","Step 2: Explain the benefit of lower mass.","Step 3: Identify a performance or cost factor that still needs checking."],"options":[],"conceptId":"chemistry_metals_alloys","skillId":"chemistry_metals","subskillId":"chemistry_metals_q8","subject":"chemistry","chapter":"metals","topic":"Alloys"}', 7),
  (4572, 978, 'A learner says stainless steel cannot corrode because it contains chromium. Explain why this is an overstatement.', 'text', 1, 'Protective oxide layers work under suitable conditions, not every possible condition.', '{"why":"The alloy grade, surface condition and environment affect corrosion behaviour.","sol":"Step 1: Explain the role of chromium.\nStep 2: Recognise that corrosion resistance is not the same as complete immunity.\nStep 3: Give an example of a challenging environment.","steps":["Step 1: Explain the role of chromium.","Step 2: Recognise that corrosion resistance is not the same as complete immunity.","Step 3: Give an example of a challenging environment."],"options":[],"conceptId":"chemistry_metals_alloys","skillId":"chemistry_metals","subskillId":"chemistry_metals_q9","subject":"chemistry","chapter":"metals","topic":"Alloys"}', 8),
  (4573, 979, 'What is bauxite?', 'text', 1, 'Focus on the core principle of Bauxite.', '{"why":"Bauxite contains aluminium compounds that can be processed to obtain aluminium oxide.","sol":"Step 1: Aluminium occurs naturally combined with other elements.\nStep 2: The main ore containing aluminium compounds is bauxite.\nStep 3: Therefore, bauxite is the main ore used to obtain aluminium.","steps":["Step 1: Aluminium occurs naturally combined with other elements.","Step 2: The main ore containing aluminium compounds is bauxite.","Step 3: Therefore, bauxite is the main ore used to obtain aluminium."],"options":[],"conceptId":"chemistry_metals_bauxite","skillId":"chemistry_metals","subskillId":"chemistry_metals_q1","subject":"chemistry","chapter":"metals","topic":"Bauxite"}', 0),
  (4574, 979, 'Why is aluminium not extracted from its ore by heating it with carbon?', 'text', 1, 'Focus on the core principle of Bauxite.', '{"why":"The high reactivity of aluminium makes electrolysis necessary for its extraction.","sol":"Step 1: Aluminium is a very reactive metal.\nStep 2: Aluminium has a stronger attraction to oxygen than carbon can overcome under ordinary extraction conditions.\nStep 3: Therefore, carbon cannot effectively reduce aluminium oxide to aluminium.\nStep 4: Aluminium is instead extracted by electrolysis.","steps":["Step 1: Aluminium is a very reactive metal.","Step 2: Aluminium has a stronger attraction to oxygen than carbon can overcome under ordinary extraction conditions.","Step 3: Therefore, carbon cannot effectively reduce aluminium oxide to aluminium.","Step 4: Aluminium is instead extracted by electrolysis."],"options":[],"conceptId":"chemistry_metals_bauxite","skillId":"chemistry_metals","subskillId":"chemistry_metals_q2","subject":"chemistry","chapter":"metals","topic":"Bauxite"}', 1),
  (4575, 979, 'State the main ore used in the extraction of aluminium.', 'text', 1, 'Focus on the core principle of Bauxite.', '{"why":"Bauxite is the principal ore used as the source of aluminium.","sol":"Step 1: Identify the principal naturally occurring aluminium ore.\nStep 2: The ore is bauxite.","steps":["Step 1: Identify the principal naturally occurring aluminium ore.","Step 2: The ore is bauxite."],"options":[],"conceptId":"chemistry_metals_bauxite","skillId":"chemistry_metals","subskillId":"chemistry_metals_q3","subject":"chemistry","chapter":"metals","topic":"Bauxite"}', 2),
  (4576, 979, 'An ore contains aluminium compounds mixed with several impurities. What is the first major processing step before aluminium can be extracted by electrolysis?', 'text', 1, 'The aluminium compound must first be separated from the impurities.', '{"why":"Impurities must be removed before aluminium oxide is subjected to electrolysis.","sol":"Step 1: The ore is bauxite.\nStep 2: Bauxite contains aluminium compounds and impurities.\nStep 3: The ore must therefore be purified.\nStep 4: Purification produces aluminium oxide suitable for the extraction process.","steps":["Step 1: The ore is bauxite.","Step 2: Bauxite contains aluminium compounds and impurities.","Step 3: The ore must therefore be purified.","Step 4: Purification produces aluminium oxide suitable for the extraction process."],"options":[],"conceptId":"chemistry_metals_bauxite","skillId":"chemistry_metals","subskillId":"chemistry_metals_q4","subject":"chemistry","chapter":"metals","topic":"Bauxite"}', 3),
  (4577, 980, 'What is the main product obtained when bauxite is purified for aluminium extraction?', 'text', 1, 'Focus on the core principle of Purification of Bauxite.', '{"why":"Aluminium oxide is the compound used in the electrolytic extraction of aluminium.","sol":"Step 1: Bauxite contains aluminium compounds and impurities.\nStep 2: The unwanted impurities are removed.\nStep 3: The aluminium-containing material is processed to obtain aluminium oxide.","steps":["Step 1: Bauxite contains aluminium compounds and impurities.","Step 2: The unwanted impurities are removed.","Step 3: The aluminium-containing material is processed to obtain aluminium oxide."],"options":[],"conceptId":"chemistry_metals_purification_of_bauxite","skillId":"chemistry_metals","subskillId":"chemistry_metals_q1","subject":"chemistry","chapter":"metals","topic":"Purification of Bauxite"}', 0),
  (4578, 980, 'Why must bauxite be purified before electrolysis?', 'text', 1, 'Focus on the core principle of Purification of Bauxite.', '{"why":"The extraction stage requires aluminium oxide rather than untreated ore containing unwanted materials.","sol":"Step 1: Raw bauxite contains impurities.\nStep 2: The desired aluminium compound is aluminium oxide.\nStep 3: Removing impurities gives a more suitable material for the electrolytic process.","steps":["Step 1: Raw bauxite contains impurities.","Step 2: The desired aluminium compound is aluminium oxide.","Step 3: Removing impurities gives a more suitable material for the electrolytic process."],"options":[],"conceptId":"chemistry_metals_purification_of_bauxite","skillId":"chemistry_metals","subskillId":"chemistry_metals_q2","subject":"chemistry","chapter":"metals","topic":"Purification of Bauxite"}', 1),
  (4579, 980, 'Write the chemical formula of aluminium oxide.', 'text', 1, 'Focus on the core principle of Purification of Bauxite.', '{"why":"Two aluminium ions and three oxide ions give an overall neutral compound.","sol":"Step 1: Aluminium forms Al³⁺ ions.\nStep 2: Oxygen forms O²⁻ ions.\nStep 3: The charges must balance.\nStep 4: Two Al³⁺ ions give +6 and three O²⁻ ions give −6.\nStep 5: Therefore, the formula is Al₂O₃.","steps":["Step 1: Aluminium forms Al³⁺ ions.","Step 2: Oxygen forms O²⁻ ions.","Step 3: The charges must balance.","Step 4: Two Al³⁺ ions give +6 and three O²⁻ ions give −6.","Step 5: Therefore, the formula is Al₂O₃."],"options":[],"conceptId":"chemistry_metals_purification_of_bauxite","skillId":"chemistry_metals","subskillId":"chemistry_metals_q3","subject":"chemistry","chapter":"metals","topic":"Purification of Bauxite"}', 2),
  (4580, 980, 'A sample of bauxite contains aluminium oxide and unwanted impurities. What should happen to the impurities before electrolysis?', 'text', 1, 'Think about what purification means.', '{"why":"Purification separates the aluminium-containing material from unwanted substances.","sol":"Step 1: Identify the desired substance: aluminium oxide.\nStep 2: The remaining substances are impurities.\nStep 3: Purification removes the unwanted substances.\nStep 4: The aluminium oxide is then used in the extraction stage.","steps":["Step 1: Identify the desired substance: aluminium oxide.","Step 2: The remaining substances are impurities.","Step 3: Purification removes the unwanted substances.","Step 4: The aluminium oxide is then used in the extraction stage."],"options":[],"conceptId":"chemistry_metals_purification_of_bauxite","skillId":"chemistry_metals","subskillId":"chemistry_metals_q4","subject":"chemistry","chapter":"metals","topic":"Purification of Bauxite"}', 3),
  (4581, 981, 'Why is aluminium extracted by electrolysis rather than reduction with carbon?', 'text', 1, 'Focus on the core principle of Electrolysis of Aluminium Oxide.', '{"why":"Electrolysis provides the energy needed to reduce Al³⁺ ions to aluminium metal.","sol":"Step 1: Aluminium is very reactive.\nStep 2: Aluminium oxide is too stable to be effectively reduced by carbon.\nStep 3: Electrolysis supplies electrical energy to reduce aluminium ions.\nStep 4: Aluminium metal is therefore obtained at the cathode.","steps":["Step 1: Aluminium is very reactive.","Step 2: Aluminium oxide is too stable to be effectively reduced by carbon.","Step 3: Electrolysis supplies electrical energy to reduce aluminium ions.","Step 4: Aluminium metal is therefore obtained at the cathode."],"options":[],"conceptId":"chemistry_metals_electrolysis_of_aluminium_oxide","skillId":"chemistry_metals","subskillId":"chemistry_metals_q1","subject":"chemistry","chapter":"metals","topic":"Electrolysis of Aluminium Oxide"}', 0),
  (4582, 981, 'Write the half-equation for the formation of aluminium at the cathode.', 'text', 1, 'Focus on the core principle of Electrolysis of Aluminium Oxide.', '{"why":"Aluminium ions gain three electrons to become neutral aluminium atoms.","sol":"Step 1: Aluminium ions are Al³⁺.\nStep 2: The cathode is where reduction occurs.\nStep 3: Reduction involves gaining electrons.\nStep 4: Each Al³⁺ ion requires three electrons.\nStep 5: Therefore, Al³⁺ + 3e⁻ → Al.","steps":["Step 1: Aluminium ions are Al³⁺.","Step 2: The cathode is where reduction occurs.","Step 3: Reduction involves gaining electrons.","Step 4: Each Al³⁺ ion requires three electrons.","Step 5: Therefore, Al³⁺ + 3e⁻ → Al."],"options":[],"conceptId":"chemistry_metals_electrolysis_of_aluminium_oxide","skillId":"chemistry_metals","subskillId":"chemistry_metals_q2","subject":"chemistry","chapter":"metals","topic":"Electrolysis of Aluminium Oxide"}', 1),
  (4583, 981, 'What happens to oxide ions at the anode during the electrolysis of aluminium oxide?', 'text', 1, 'Focus on the core principle of Electrolysis of Aluminium Oxide.', '{"why":"Oxide ions lose electrons at the positive anode.","sol":"Step 1: Oxide ions are O²⁻.\nStep 2: The anode is where oxidation occurs.\nStep 3: Oxide ions lose electrons.\nStep 4: The oxide ions form oxygen.","steps":["Step 1: Oxide ions are O²⁻.","Step 2: The anode is where oxidation occurs.","Step 3: Oxide ions lose electrons.","Step 4: The oxide ions form oxygen."],"options":[],"conceptId":"chemistry_metals_electrolysis_of_aluminium_oxide","skillId":"chemistry_metals","subskillId":"chemistry_metals_q3","subject":"chemistry","chapter":"metals","topic":"Electrolysis of Aluminium Oxide"}', 2),
  (4584, 981, 'During aluminium extraction, a student writes the cathode reaction as Al³⁺ → Al + 3e⁻. What is wrong with this equation?', 'text', 1, 'Reduction at the cathode involves gaining electrons, not losing them.', '{"why":"Aluminium ions are reduced at the cathode by gaining three electrons.","sol":"Step 1: The cathode is the site of reduction.\nStep 2: Reduction means gain of electrons.\nStep 3: Al³⁺ must gain three electrons.\nStep 4: The correct equation is Al³⁺ + 3e⁻ → Al.","steps":["Step 1: The cathode is the site of reduction.","Step 2: Reduction means gain of electrons.","Step 3: Al³⁺ must gain three electrons.","Step 4: The correct equation is Al³⁺ + 3e⁻ → Al."],"options":[],"conceptId":"chemistry_metals_electrolysis_of_aluminium_oxide","skillId":"chemistry_metals","subskillId":"chemistry_metals_q4","subject":"chemistry","chapter":"metals","topic":"Electrolysis of Aluminium Oxide"}', 3),
  (4585, 981, 'Why do the carbon anodes used in aluminium extraction gradually become smaller?', 'text', 1, 'Consider what happens to oxide ions at the anode.', '{"why":"The carbon anodes are oxidised by the oxygen formed during electrolysis.","sol":"Step 1: Oxide ions are discharged at the anode.\nStep 2: Oxygen is produced.\nStep 3: The oxygen reacts with the carbon anode.\nStep 4: Carbon is converted into carbon oxides and the anode is gradually consumed.","steps":["Step 1: Oxide ions are discharged at the anode.","Step 2: Oxygen is produced.","Step 3: The oxygen reacts with the carbon anode.","Step 4: Carbon is converted into carbon oxides and the anode is gradually consumed."],"options":[],"conceptId":"chemistry_metals_electrolysis_of_aluminium_oxide","skillId":"chemistry_metals","subskillId":"chemistry_metals_q5","subject":"chemistry","chapter":"metals","topic":"Electrolysis of Aluminium Oxide"}', 4),
  (4586, 982, 'What is water pollution?', 'text', 1, 'Focus on the core principle of Water Pollution.', '{"why":"Pollutants change the quality of water and can cause harm to living organisms.","sol":"Step 1: Water can become contaminated by unwanted substances.\nStep 2: These substances can make the water harmful or unsuitable for organisms.\nStep 3: This contamination is called water pollution.","steps":["Step 1: Water can become contaminated by unwanted substances.","Step 2: These substances can make the water harmful or unsuitable for organisms.","Step 3: This contamination is called water pollution."],"options":[],"conceptId":"chemistry_environment_water_pollution","skillId":"chemistry_environment","subskillId":"chemistry_environment_q1","subject":"chemistry","chapter":"environment","topic":"Water Pollution"}', 0),
  (4587, 982, 'How can excessive fertiliser use cause water pollution?', 'text', 1, 'Focus on the core principle of Water Pollution.', '{"why":"Excess nutrients can cause eutrophication, which may reduce oxygen available to aquatic organisms.","sol":"Step 1: Fertilisers can contain nitrates and phosphates.\nStep 2: Rainwater can carry these substances into rivers and lakes.\nStep 3: The nutrients can cause excessive growth of algae.\nStep 4: When the algae die, microorganisms decompose them and use dissolved oxygen.\nStep 5: The reduced oxygen concentration can harm or kill aquatic organisms.","steps":["Step 1: Fertilisers can contain nitrates and phosphates.","Step 2: Rainwater can carry these substances into rivers and lakes.","Step 3: The nutrients can cause excessive growth of algae.","Step 4: When the algae die, microorganisms decompose them and use dissolved oxygen.","Step 5: The reduced oxygen concentration can harm or kill aquatic organisms."],"options":[],"conceptId":"chemistry_environment_water_pollution","skillId":"chemistry_environment","subskillId":"chemistry_environment_q2","subject":"chemistry","chapter":"environment","topic":"Water Pollution"}', 1),
  (4588, 982, 'State two ways of controlling water pollution.', 'text', 1, 'Focus on the core principle of Water Pollution.', '{"why":"Treatment removes or reduces harmful substances before wastewater enters natural water sources.","sol":"Step 1: Identify major sources of pollutants.\nStep 2: Prevent sewage and industrial waste from entering water untreated.\nStep 3: Reduce the amount of agricultural chemicals reaching water sources.","steps":["Step 1: Identify major sources of pollutants.","Step 2: Prevent sewage and industrial waste from entering water untreated.","Step 3: Reduce the amount of agricultural chemicals reaching water sources."],"options":[],"conceptId":"chemistry_environment_water_pollution","skillId":"chemistry_environment","subskillId":"chemistry_environment_q3","subject":"chemistry","chapter":"environment","topic":"Water Pollution"}', 2),
  (4589, 982, 'A lake receives large amounts of fertiliser runoff. After some time, many fish begin dying. Explain how the fertiliser could have caused this.', 'text', 1, 'Think about nutrients, algae and dissolved oxygen.', '{"why":"This is a form of eutrophication in which excess nutrients indirectly cause oxygen depletion.","sol":"Step 1: Fertiliser runoff adds nutrients such as nitrates and phosphates to the lake.\nStep 2: The excess nutrients encourage rapid algal growth.\nStep 3: The algae eventually die and are decomposed by microorganisms.\nStep 4: The microorganisms use dissolved oxygen during decomposition.\nStep 5: The oxygen concentration falls.\nStep 6: Fish and other aquatic organisms may die because there is insufficient dissolved oxygen.","steps":["Step 1: Fertiliser runoff adds nutrients such as nitrates and phosphates to the lake.","Step 2: The excess nutrients encourage rapid algal growth.","Step 3: The algae eventually die and are decomposed by microorganisms.","Step 4: The microorganisms use dissolved oxygen during decomposition.","Step 5: The oxygen concentration falls.","Step 6: Fish and other aquatic organisms may die because there is insufficient dissolved oxygen."],"options":[],"conceptId":"chemistry_environment_water_pollution","skillId":"chemistry_environment","subskillId":"chemistry_environment_q4","subject":"chemistry","chapter":"environment","topic":"Water Pollution"}', 3),
  (4590, 982, 'Why should sewage be treated before it is released into a river?', 'text', 1, 'Consider disease-causing organisms and substances in untreated sewage.', '{"why":"Sewage treatment reduces contamination and protects water quality and aquatic ecosystems.","sol":"Step 1: Untreated sewage can contain microorganisms that cause disease.\nStep 2: It can also contain organic matter and other pollutants.\nStep 3: Releasing it directly into a river can contaminate the water.\nStep 4: Treatment reduces harmful microorganisms and pollutants before discharge.","steps":["Step 1: Untreated sewage can contain microorganisms that cause disease.","Step 2: It can also contain organic matter and other pollutants.","Step 3: Releasing it directly into a river can contaminate the water.","Step 4: Treatment reduces harmful microorganisms and pollutants before discharge."],"options":[],"conceptId":"chemistry_environment_water_pollution","skillId":"chemistry_environment","subskillId":"chemistry_environment_q5","subject":"chemistry","chapter":"environment","topic":"Water Pollution"}', 4),
  (4591, 983, 'What is the ozone layer?', 'text', 1, 'Focus on the core principle of Ozone Layer.', '{"why":"Stratospheric ozone forms a region that absorbs much of the Sun''s harmful ultraviolet radiation.","sol":"Step 1: Ozone is O₃.\nStep 2: A relatively high concentration of ozone occurs in part of the stratosphere.\nStep 3: This region is commonly called the ozone layer.","steps":["Step 1: Ozone is O₃.","Step 2: A relatively high concentration of ozone occurs in part of the stratosphere.","Step 3: This region is commonly called the ozone layer."],"options":[],"conceptId":"chemistry_environment_ozone_layer","skillId":"chemistry_environment","subskillId":"chemistry_environment_q1","subject":"chemistry","chapter":"environment","topic":"Ozone Layer"}', 0),
  (4592, 983, 'How is ozone formed from oxygen in the stratosphere?', 'text', 1, 'Focus on the core principle of Ozone Layer.', '{"why":"Ultraviolet radiation drives the reactions that form ozone from oxygen.","sol":"Step 1: Ultraviolet radiation splits oxygen molecules into oxygen atoms.\nStep 2: An oxygen atom combines with an oxygen molecule.\nStep 3: Ozone is formed.\nStep 4: The equations are O₂ → 2O and O + O₂ → O₃.","steps":["Step 1: Ultraviolet radiation splits oxygen molecules into oxygen atoms.","Step 2: An oxygen atom combines with an oxygen molecule.","Step 3: Ozone is formed.","Step 4: The equations are O₂ → 2O and O + O₂ → O₃."],"options":[],"conceptId":"chemistry_environment_ozone_layer","skillId":"chemistry_environment","subskillId":"chemistry_environment_q2","subject":"chemistry","chapter":"environment","topic":"Ozone Layer"}', 1),
  (4593, 983, 'Why is the ozone layer important to living organisms?', 'text', 1, 'Focus on the core principle of Ozone Layer.', '{"why":"Ozone reduces the amount of harmful ultraviolet radiation reaching Earth''s surface.","sol":"Step 1: The Sun produces ultraviolet radiation.\nStep 2: Excessive ultraviolet radiation can damage living cells.\nStep 3: Stratospheric ozone absorbs much of this radiation.\nStep 4: Therefore, the ozone layer provides important protection for living organisms.","steps":["Step 1: The Sun produces ultraviolet radiation.","Step 2: Excessive ultraviolet radiation can damage living cells.","Step 3: Stratospheric ozone absorbs much of this radiation.","Step 4: Therefore, the ozone layer provides important protection for living organisms."],"options":[],"conceptId":"chemistry_environment_ozone_layer","skillId":"chemistry_environment","subskillId":"chemistry_environment_q3","subject":"chemistry","chapter":"environment","topic":"Ozone Layer"}', 2),
  (4594, 983, 'What would happen if much less ultraviolet radiation were absorbed by the ozone layer?', 'text', 1, 'Think about what excessive ultraviolet radiation can do to living cells.', '{"why":"The ozone layer acts as a protective barrier against much of the Sun''s harmful ultraviolet radiation.","sol":"Step 1: Less ozone absorption would allow more ultraviolet radiation to reach Earth''s surface.\nStep 2: Living organisms would therefore receive greater exposure.\nStep 3: Excessive ultraviolet radiation can damage cells and tissues.\nStep 4: Therefore, risks associated with ultraviolet exposure would increase.","steps":["Step 1: Less ozone absorption would allow more ultraviolet radiation to reach Earth''s surface.","Step 2: Living organisms would therefore receive greater exposure.","Step 3: Excessive ultraviolet radiation can damage cells and tissues.","Step 4: Therefore, risks associated with ultraviolet exposure would increase."],"options":[],"conceptId":"chemistry_environment_ozone_layer","skillId":"chemistry_environment","subskillId":"chemistry_environment_q4","subject":"chemistry","chapter":"environment","topic":"Ozone Layer"}', 3),
  (4595, 983, 'Why does the ozone layer contain O₃ rather than O₂?', 'text', 1, 'Identify the chemical formula of ozone.', '{"why":"Ozone is an allotrope of oxygen with three oxygen atoms per molecule.","sol":"Step 1: Oxygen gas normally exists as O₂.\nStep 2: Ozone is a different form of oxygen.\nStep 3: An ozone molecule contains three oxygen atoms.\nStep 4: Therefore, its formula is O₃.","steps":["Step 1: Oxygen gas normally exists as O₂.","Step 2: Ozone is a different form of oxygen.","Step 3: An ozone molecule contains three oxygen atoms.","Step 4: Therefore, its formula is O₃."],"options":[],"conceptId":"chemistry_environment_ozone_layer","skillId":"chemistry_environment","subskillId":"chemistry_environment_q5","subject":"chemistry","chapter":"environment","topic":"Ozone Layer"}', 4),
  (4596, 984, 'What is ozone depletion?', 'text', 1, 'Focus on the core principle of Ozone Depletion.', '{"why":"Ozone depletion occurs when chemical processes destroy stratospheric ozone.","sol":"Step 1: The ozone layer contains ozone, O₃.\nStep 2: Certain chemical substances can cause ozone molecules to be destroyed.\nStep 3: The concentration of ozone in the stratosphere therefore decreases.\nStep 4: This reduction is called ozone depletion.","steps":["Step 1: The ozone layer contains ozone, O₃.","Step 2: Certain chemical substances can cause ozone molecules to be destroyed.","Step 3: The concentration of ozone in the stratosphere therefore decreases.","Step 4: This reduction is called ozone depletion."],"options":[],"conceptId":"chemistry_environment_ozone_depletion","skillId":"chemistry_environment","subskillId":"chemistry_environment_q1","subject":"chemistry","chapter":"environment","topic":"Ozone Depletion"}', 0),
  (4597, 984, 'How can CFCs contribute to ozone depletion?', 'text', 1, 'Focus on the core principle of Ozone Depletion.', '{"why":"Chlorine released from ozone-depleting substances can catalyse the destruction of ozone.","sol":"Step 1: CFCs can reach the stratosphere.\nStep 2: Ultraviolet radiation breaks down CFC molecules.\nStep 3: Chlorine atoms can be released.\nStep 4: The chlorine reacts with ozone and contributes to its destruction.","steps":["Step 1: CFCs can reach the stratosphere.","Step 2: Ultraviolet radiation breaks down CFC molecules.","Step 3: Chlorine atoms can be released.","Step 4: The chlorine reacts with ozone and contributes to its destruction."],"options":[],"conceptId":"chemistry_environment_ozone_depletion","skillId":"chemistry_environment","subskillId":"chemistry_environment_q2","subject":"chemistry","chapter":"environment","topic":"Ozone Depletion"}', 1),
  (4598, 984, 'Why is ozone depletion harmful to humans?', 'text', 1, 'Focus on the core principle of Ozone Depletion.', '{"why":"A thinner ozone layer provides less protection from ultraviolet radiation.","sol":"Step 1: Stratospheric ozone absorbs much of the Sun''s harmful ultraviolet radiation.\nStep 2: Ozone depletion reduces this protection.\nStep 3: More ultraviolet radiation can reach Earth''s surface.\nStep 4: Excessive ultraviolet exposure can damage human cells and tissues.","steps":["Step 1: Stratospheric ozone absorbs much of the Sun''s harmful ultraviolet radiation.","Step 2: Ozone depletion reduces this protection.","Step 3: More ultraviolet radiation can reach Earth''s surface.","Step 4: Excessive ultraviolet exposure can damage human cells and tissues."],"options":[],"conceptId":"chemistry_environment_ozone_depletion","skillId":"chemistry_environment","subskillId":"chemistry_environment_q3","subject":"chemistry","chapter":"environment","topic":"Ozone Depletion"}', 2),
  (4599, 984, 'A chemical released into the atmosphere eventually reaches the stratosphere and releases chlorine atoms when exposed to ultraviolet radiation. How could this affect ozone?', 'text', 1, 'Consider what chlorine atoms can do to ozone molecules.', '{"why":"Reactive chlorine can participate in catalytic reactions that destroy ozone.","sol":"Step 1: Ultraviolet radiation releases chlorine atoms from the chemical.\nStep 2: The chlorine atoms react with ozone molecules.\nStep 3: These reactions destroy ozone.\nStep 4: Therefore, the concentration of stratospheric ozone can decrease.","steps":["Step 1: Ultraviolet radiation releases chlorine atoms from the chemical.","Step 2: The chlorine atoms react with ozone molecules.","Step 3: These reactions destroy ozone.","Step 4: Therefore, the concentration of stratospheric ozone can decrease."],"options":[],"conceptId":"chemistry_environment_ozone_depletion","skillId":"chemistry_environment","subskillId":"chemistry_environment_q4","subject":"chemistry","chapter":"environment","topic":"Ozone Depletion"}', 3),
  (4600, 984, 'Suggest one way of reducing ozone depletion.', 'text', 1, 'Think about the substances responsible for releasing chlorine or bromine in the stratosphere.', '{"why":"Controlling ozone-depleting substances reduces the chemical reactions responsible for ozone destruction.","sol":"Step 1: Identify substances that contribute to ozone depletion.\nStep 2: Reduce their production and use.\nStep 3: Replace them with safer alternatives where possible.","steps":["Step 1: Identify substances that contribute to ozone depletion.","Step 2: Reduce their production and use.","Step 3: Replace them with safer alternatives where possible."],"options":[],"conceptId":"chemistry_environment_ozone_depletion","skillId":"chemistry_environment","subskillId":"chemistry_environment_q5","subject":"chemistry","chapter":"environment","topic":"Ozone Depletion"}', 4),
  (4601, 985, 'What is sustainable chemistry?', 'text', 1, 'Focus on the core principle of Sustainable Chemistry.', '{"why":"The aim is to prevent pollution and reduce the environmental impact of chemistry.","sol":"Step 1: Chemical processes can consume resources and produce waste.\nStep 2: Sustainable chemistry aims to reduce these negative effects.\nStep 3: It promotes safer, more efficient and less wasteful chemical processes.","steps":["Step 1: Chemical processes can consume resources and produce waste.","Step 2: Sustainable chemistry aims to reduce these negative effects.","Step 3: It promotes safer, more efficient and less wasteful chemical processes."],"options":[],"conceptId":"chemistry_environment_sustainable_chemistry","skillId":"chemistry_environment","subskillId":"chemistry_environment_q1","subject":"chemistry","chapter":"environment","topic":"Sustainable Chemistry"}', 0),
  (4602, 985, 'Why is reducing waste at the source better than producing waste and treating it afterwards?', 'text', 1, 'Focus on the core principle of Sustainable Chemistry.', '{"why":"Preventing pollution at its source is generally more efficient than dealing with pollution after it has been produced.","sol":"Step 1: Producing waste creates a material that must be collected and treated or disposed of.\nStep 2: Treatment and disposal can require additional energy and resources.\nStep 3: Preventing the waste from being produced avoids these additional requirements.\nStep 4: Therefore, waste prevention can reduce environmental impact.","steps":["Step 1: Producing waste creates a material that must be collected and treated or disposed of.","Step 2: Treatment and disposal can require additional energy and resources.","Step 3: Preventing the waste from being produced avoids these additional requirements.","Step 4: Therefore, waste prevention can reduce environmental impact."],"options":[],"conceptId":"chemistry_environment_sustainable_chemistry","skillId":"chemistry_environment","subskillId":"chemistry_environment_q2","subject":"chemistry","chapter":"environment","topic":"Sustainable Chemistry"}', 1),
  (4603, 985, 'Why can using a chemical process that requires less energy be more sustainable?', 'text', 1, 'Focus on the core principle of Sustainable Chemistry.', '{"why":"Using less energy can conserve resources and reduce environmental impacts associated with energy production.","sol":"Step 1: Energy is required to operate many chemical processes.\nStep 2: Lower energy requirements mean less energy needs to be supplied.\nStep 3: If the energy comes from fossil fuels, lower energy use can also reduce associated emissions.\nStep 4: Therefore, an energy-efficient process can reduce environmental impact.","steps":["Step 1: Energy is required to operate many chemical processes.","Step 2: Lower energy requirements mean less energy needs to be supplied.","Step 3: If the energy comes from fossil fuels, lower energy use can also reduce associated emissions.","Step 4: Therefore, an energy-efficient process can reduce environmental impact."],"options":[],"conceptId":"chemistry_environment_sustainable_chemistry","skillId":"chemistry_environment","subskillId":"chemistry_environment_q3","subject":"chemistry","chapter":"environment","topic":"Sustainable Chemistry"}', 2),
  (4604, 985, 'A factory changes its manufacturing process so that it produces the same amount of product using less raw material and producing less waste. Why is this an example of sustainable chemistry?', 'text', 1, 'Consider resource use and waste production.', '{"why":"Efficient resource use and waste prevention are important principles of sustainable chemistry.","sol":"Step 1: The new process uses less raw material.\nStep 2: It also produces less waste.\nStep 3: This reduces resource consumption and waste generation.\nStep 4: Therefore, the process has a lower environmental impact.","steps":["Step 1: The new process uses less raw material.","Step 2: It also produces less waste.","Step 3: This reduces resource consumption and waste generation.","Step 4: Therefore, the process has a lower environmental impact."],"options":[],"conceptId":"chemistry_environment_sustainable_chemistry","skillId":"chemistry_environment","subskillId":"chemistry_environment_q4","subject":"chemistry","chapter":"environment","topic":"Sustainable Chemistry"}', 3),
  (4605, 985, 'A chemical product can be made using either a highly toxic substance or a less harmful alternative. Which option is more consistent with sustainable chemistry?', 'text', 1, 'Sustainable chemistry seeks to reduce hazards where possible.', '{"why":"Using safer substances can reduce risks to human health and the environment.","sol":"Step 1: Compare the hazards of the two substances.\nStep 2: The less harmful alternative presents a lower risk to people and the environment.\nStep 3: Therefore, it is the preferred option when it performs the required function effectively.","steps":["Step 1: Compare the hazards of the two substances.","Step 2: The less harmful alternative presents a lower risk to people and the environment.","Step 3: Therefore, it is the preferred option when it performs the required function effectively."],"options":[],"conceptId":"chemistry_environment_sustainable_chemistry","skillId":"chemistry_environment","subskillId":"chemistry_environment_q5","subject":"chemistry","chapter":"environment","topic":"Sustainable Chemistry"}', 4),
  (4606, 986, 'What is waste management?', 'text', 1, 'Focus on the core principle of Waste Management.', '{"why":"Proper waste management reduces pollution, health risks and unnecessary loss of useful materials.","sol":"Step 1: Waste can harm people and the environment if it is handled improperly.\nStep 2: Waste therefore needs to be controlled, treated, recovered or disposed of safely.\nStep 3: The organised handling of waste is called waste management.","steps":["Step 1: Waste can harm people and the environment if it is handled improperly.","Step 2: Waste therefore needs to be controlled, treated, recovered or disposed of safely.","Step 3: The organised handling of waste is called waste management."],"options":[],"conceptId":"chemistry_environment_waste_management","skillId":"chemistry_environment","subskillId":"chemistry_environment_q1","subject":"chemistry","chapter":"environment","topic":"Waste Management"}', 0),
  (4607, 986, 'What does reducing waste mean?', 'text', 1, 'Focus on the core principle of Waste Management.', '{"why":"Preventing waste at its source reduces the materials and resources that must later be treated or disposed of.","sol":"Step 1: Waste reduction focuses on preventing unnecessary waste from being produced.\nStep 2: This can be achieved by using fewer materials or avoiding unnecessary consumption.\nStep 3: Therefore, reducing waste means producing less waste at the source.","steps":["Step 1: Waste reduction focuses on preventing unnecessary waste from being produced.","Step 2: This can be achieved by using fewer materials or avoiding unnecessary consumption.","Step 3: Therefore, reducing waste means producing less waste at the source."],"options":[],"conceptId":"chemistry_environment_waste_management","skillId":"chemistry_environment","subskillId":"chemistry_environment_q2","subject":"chemistry","chapter":"environment","topic":"Waste Management"}', 1),
  (4608, 986, 'What is the difference between reusing and recycling?', 'text', 1, 'Focus on the core principle of Waste Management.', '{"why":"Both reduce waste, but recycling involves processing the material whereas reuse does not necessarily require processing.","sol":"Step 1: Reusing means using an item again without necessarily changing it into a new material.\nStep 2: Recycling involves collecting and processing waste materials to make new products.\nStep 3: Therefore, reuse keeps an item in use, while recycling processes the material into another product.","steps":["Step 1: Reusing means using an item again without necessarily changing it into a new material.","Step 2: Recycling involves collecting and processing waste materials to make new products.","Step 3: Therefore, reuse keeps an item in use, while recycling processes the material into another product."],"options":[],"conceptId":"chemistry_environment_waste_management","skillId":"chemistry_environment","subskillId":"chemistry_environment_q3","subject":"chemistry","chapter":"environment","topic":"Waste Management"}', 2),
  (4609, 986, 'A laboratory produces unused chemical solution after an experiment. Why should it not simply be poured into a drain?', 'text', 1, 'Consider what the chemical could do to water and organisms.', '{"why":"Chemical waste requires appropriate handling and disposal to prevent pollution and exposure.","sol":"Step 1: The solution may contain substances that are harmful or toxic.\nStep 2: Pouring it into a drain can introduce these substances into wastewater and eventually the environment.\nStep 3: The substances could contaminate water or harm organisms.\nStep 4: Therefore, the chemical waste should be handled according to appropriate waste-disposal procedures.","steps":["Step 1: The solution may contain substances that are harmful or toxic.","Step 2: Pouring it into a drain can introduce these substances into wastewater and eventually the environment.","Step 3: The substances could contaminate water or harm organisms.","Step 4: Therefore, the chemical waste should be handled according to appropriate waste-disposal procedures."],"options":[],"conceptId":"chemistry_environment_waste_management","skillId":"chemistry_environment","subskillId":"chemistry_environment_q4","subject":"chemistry","chapter":"environment","topic":"Waste Management"}', 3),
  (4610, 986, 'A school replaces disposable plastic containers with reusable containers. Which waste-management principle is being applied?', 'text', 1, 'The same container is used repeatedly instead of being discarded after one use.', '{"why":"Using an item repeatedly instead of discarding it after one use reduces waste.","sol":"Step 1: The containers are used more than once.\nStep 2: Fewer disposable containers are therefore thrown away.\nStep 3: This is the principle of reuse.","steps":["Step 1: The containers are used more than once.","Step 2: Fewer disposable containers are therefore thrown away.","Step 3: This is the principle of reuse."],"options":[],"conceptId":"chemistry_environment_waste_management","skillId":"chemistry_environment","subskillId":"chemistry_environment_q5","subject":"chemistry","chapter":"environment","topic":"Waste Management"}', 4),
  (4611, 987, 'What is a cell?', 'mcq', 1, 'Focus on the core principle of What Is a Cell.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for What Is a Cell.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: A cell is the smallest unit of a living organism that can carry out the processes needed for life.","steps":["Step 1: Identify key concept: Define the required principles for What Is a Cell.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: A cell is the smallest unit of a living organism that can carry out the processes needed for life."],"options":[{"text":"The smallest living unit of an organism","is_correct":false},{"text":"A group of organs","is_correct":false},{"text":"A chemical found only in plants","is_correct":false},{"text":"A non-living part of an organism","is_correct":false},{"text":"A cell is the smallest unit of a living organism that can carry out the processes needed for life.","is_correct":true}],"conceptId":"biology_cell_biology_what_is_a_cell","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q1","subject":"biology","chapter":"cell_biology","topic":"What Is a Cell"}', 0),
  (4612, 987, 'Why is a cell called a unit of life?', 'mcq', 1, 'Focus on the core principle of What Is a Cell.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for What Is a Cell.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Because it can carry out the processes necessary for life.","steps":["Step 1: Identify key concept: Define the required principles for What Is a Cell.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Because it can carry out the processes necessary for life."],"options":[{"text":"Because it is always visible to the naked eye","is_correct":false},{"text":"Because it can carry out processes necessary for life","is_correct":false},{"text":"Because every cell is the same size","is_correct":false},{"text":"Because cells are made only of water","is_correct":false},{"text":"Because it can carry out the processes necessary for life.","is_correct":true}],"conceptId":"biology_cell_biology_what_is_a_cell","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q2","subject":"biology","chapter":"cell_biology","topic":"What Is a Cell"}', 1),
  (4613, 987, 'What unit is commonly used to measure the size of cells?', 'mcq', 1, 'Focus on the core principle of What Is a Cell.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for What Is a Cell.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Micrometre","steps":["Step 1: Identify key concept: Define the required principles for What Is a Cell.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Micrometre"],"options":[{"text":"Kilometre","is_correct":false},{"text":"Metre","is_correct":false},{"text":"Micrometre","is_correct":true},{"text":"Litre","is_correct":false}],"conceptId":"biology_cell_biology_what_is_a_cell","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q3","subject":"biology","chapter":"cell_biology","topic":"What Is a Cell"}', 2),
  (4614, 988, 'Why are cells called the basic units of life?', 'mcq', 1, 'Focus on the core principle of Why Cells Are the Basic Units of Life.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Why Cells Are the Basic Units of Life.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Because living processes are carried out by cells.","steps":["Step 1: Identify key concept: Define the required principles for Why Cells Are the Basic Units of Life.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Because living processes are carried out by cells."],"options":[{"text":"Because cells are always microscopic","is_correct":false},{"text":"Because living processes are carried out by cells","is_correct":false},{"text":"Because cells are all identical","is_correct":false},{"text":"Because cells only occur in animals","is_correct":false},{"text":"Because living processes are carried out by cells.","is_correct":true}],"conceptId":"biology_cell_biology_why_cells_are_the_basic_units_of_life","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q1","subject":"biology","chapter":"cell_biology","topic":"Why Cells Are the Basic Units of Life"}', 0),
  (4615, 988, 'Which statement best explains why the heart is not the basic unit of life?', 'mcq', 1, 'Focus on the core principle of Why Cells Are the Basic Units of Life.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Why Cells Are the Basic Units of Life.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: The heart is an organ made from tissues and cells.","steps":["Step 1: Identify key concept: Define the required principles for Why Cells Are the Basic Units of Life.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: The heart is an organ made from tissues and cells."],"options":[{"text":"The heart is not made of cells","is_correct":false},{"text":"The heart is an organ made from tissues and cells","is_correct":false},{"text":"The heart is not part of a living organism","is_correct":false},{"text":"The heart is smaller than a cell","is_correct":false},{"text":"The heart is an organ made from tissues and cells.","is_correct":true}],"conceptId":"biology_cell_biology_why_cells_are_the_basic_units_of_life","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q2","subject":"biology","chapter":"cell_biology","topic":"Why Cells Are the Basic Units of Life"}', 1),
  (4616, 988, 'Give one life process carried out by cells.', 'mcq', 1, 'Focus on the core principle of Why Cells Are the Basic Units of Life.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Why Cells Are the Basic Units of Life.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Any valid example such as respiration, growth, waste removal, response, or reproduction.","steps":["Step 1: Identify key concept: Define the required principles for Why Cells Are the Basic Units of Life.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Any valid example such as respiration, growth, waste removal, response, or reproduction."],"options":[{"text":"Respiration","is_correct":false},{"text":"Rusting","is_correct":false},{"text":"Melting","is_correct":false},{"text":"Evaporation","is_correct":false},{"text":"Any valid example such as respiration, growth, waste removal, response, or reproduction.","is_correct":true}],"conceptId":"biology_cell_biology_why_cells_are_the_basic_units_of_life","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q3","subject":"biology","chapter":"cell_biology","topic":"Why Cells Are the Basic Units of Life"}', 2),
  (4617, 989, 'What is the main function of the cell membrane?', 'mcq', 1, 'Focus on the core principle of Cell Membrane.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Cell Membrane.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: To control the movement of substances into and out of the cell.","steps":["Step 1: Identify key concept: Define the required principles for Cell Membrane.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: To control the movement of substances into and out of the cell."],"options":[{"text":"To release energy","is_correct":false},{"text":"To control movement of substances into and out of the cell","is_correct":false},{"text":"To make the cell green","is_correct":false},{"text":"To store urine","is_correct":false},{"text":"To control the movement of substances into and out of the cell.","is_correct":true}],"conceptId":"biology_cell_biology_cell_membrane","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q1","subject":"biology","chapter":"cell_biology","topic":"Cell Membrane"}', 0),
  (4618, 989, 'What does selectively permeable mean in relation to the cell membrane?', 'mcq', 1, 'Focus on the core principle of Cell Membrane.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Cell Membrane.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: The membrane controls which substances can cross it and how they cross.","steps":["Step 1: Identify key concept: Define the required principles for Cell Membrane.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: The membrane controls which substances can cross it and how they cross."],"options":[{"text":"Everything crosses the membrane freely","is_correct":false},{"text":"Nothing can cross the membrane","is_correct":false},{"text":"The membrane controls movement of substances across it","is_correct":false},{"text":"Only water can cross","is_correct":false},{"text":"The membrane controls which substances can cross it and how they cross.","is_correct":true}],"conceptId":"biology_cell_biology_cell_membrane","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q2","subject":"biology","chapter":"cell_biology","topic":"Cell Membrane"}', 1),
  (4619, 989, 'Why must a cell control what enters and leaves?', 'mcq', 1, 'Focus on the core principle of Cell Membrane.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Cell Membrane.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: To maintain suitable internal conditions for the cell to function.","steps":["Step 1: Identify key concept: Define the required principles for Cell Membrane.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: To maintain suitable internal conditions for the cell to function."],"options":[{"text":"To make the cell larger","is_correct":false},{"text":"To maintain suitable internal conditions","is_correct":false},{"text":"To stop all substances entering","is_correct":false},{"text":"To prevent respiration","is_correct":false},{"text":"To maintain suitable internal conditions for the cell to function.","is_correct":true}],"conceptId":"biology_cell_biology_cell_membrane","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q3","subject":"biology","chapter":"cell_biology","topic":"Cell Membrane"}', 2),
  (4620, 990, 'What is the cytoplasm?', 'mcq', 1, 'Focus on the core principle of Cytoplasm.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Cytoplasm.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: The living material inside the cell membrane where many chemical reactions occur.","steps":["Step 1: Identify key concept: Define the required principles for Cytoplasm.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: The living material inside the cell membrane where many chemical reactions occur."],"options":[{"text":"The outer boundary of the cell","is_correct":false},{"text":"The living material inside the cell membrane","is_correct":false},{"text":"The genetic material only","is_correct":false},{"text":"The rigid wall around a plant cell","is_correct":false},{"text":"The living material inside the cell membrane where many chemical reactions occur.","is_correct":true}],"conceptId":"biology_cell_biology_cytoplasm","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q1","subject":"biology","chapter":"cell_biology","topic":"Cytoplasm"}', 0),
  (4621, 990, 'Why is the cytoplasm important?', 'mcq', 1, 'Focus on the core principle of Cytoplasm.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Cytoplasm.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Many chemical reactions needed by the cell occur there.","steps":["Step 1: Identify key concept: Define the required principles for Cytoplasm.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Many chemical reactions needed by the cell occur there."],"options":[{"text":"It controls the organism''s behaviour","is_correct":false},{"text":"Many cellular chemical reactions occur there","is_correct":false},{"text":"It surrounds the entire organism","is_correct":false},{"text":"It prevents all substances from entering","is_correct":false},{"text":"Many chemical reactions needed by the cell occur there.","is_correct":true}],"conceptId":"biology_cell_biology_cytoplasm","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q2","subject":"biology","chapter":"cell_biology","topic":"Cytoplasm"}', 1),
