  (5811, 1379, 'A pond contains 80 frogs of the same species. What is the population size?', 'mcq', 1, 'Focus on the core principle of Population.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Population.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: 80","steps":["Step 1: Identify key concept: Define the required principles for Population.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: 80"],"options":[{"text":"8","is_correct":false},{"text":"40","is_correct":false},{"text":"80","is_correct":true},{"text":"160","is_correct":false}],"conceptId":"biology_ecology_population","skillId":"biology_ecology","subskillId":"biology_ecology_q2","subject":"biology","chapter":"ecology","topic":"Population"}', 1),
  (5812, 1379, 'What is the main difference between a population and a community?', 'mcq', 1, 'Focus on the core principle of Population.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Population.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: A population contains one species while a community contains different populations","steps":["Step 1: Identify key concept: Define the required principles for Population.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: A population contains one species while a community contains different populations"],"options":[{"text":"A population contains one species while a community contains different populations","is_correct":true},{"text":"A population contains only plants","is_correct":false},{"text":"A community contains only one organism","is_correct":false},{"text":"A community contains no living organisms","is_correct":false}],"conceptId":"biology_ecology_population","skillId":"biology_ecology","subskillId":"biology_ecology_q3","subject":"biology","chapter":"ecology","topic":"Population"}', 2),
