  (8160, 2111, 'Give one use of cookies', 'text', 1, 'Think login', '{"why":"Cookies help improve user experience.","sol":"Step 1: Identify key concept: Define the required principles for Cookies and Tracking.\nStep 2: Apply governing rule: Cookies help improve user experience.\nStep 3: State the final conclusion: Remembering login details","steps":["Step 1: Identify key concept: Define the required principles for Cookies and Tracking.","Step 2: Apply governing rule: Cookies help improve user experience.","Step 3: State the final conclusion: Remembering login details"],"options":[],"conceptId":"computer_internet_web_cookies_and_tracking","skillId":"computer_internet_web","subskillId":"computer_internet_web_q3","subject":"computer","chapter":"internet_web","topic":"Cookies and Tracking"}', 2),
  (8161, 2111, 'What is tracking in computing?', 'text', 1, 'Think monitoring', '{"why":"It is often done using cookies.","sol":"Step 1: Identify key concept: Define the required principles for Cookies and Tracking.\nStep 2: Apply governing rule: It is often done using cookies.\nStep 3: State the final conclusion: Monitoring user activity online","steps":["Step 1: Identify key concept: Define the required principles for Cookies and Tracking.","Step 2: Apply governing rule: It is often done using cookies.","Step 3: State the final conclusion: Monitoring user activity online"],"options":[],"conceptId":"computer_internet_web_cookies_and_tracking","skillId":"computer_internet_web","subskillId":"computer_internet_web_q4","subject":"computer","chapter":"internet_web","topic":"Cookies and Tracking"}', 3),
  (8162, 2111, 'State one advantage of cookies', 'text', 1, 'Think convenience', '{"why":"They save preferences and time.","sol":"Step 1: Identify key concept: Define the required principles for Cookies and Tracking.\nStep 2: Apply governing rule: They save preferences and time.\nStep 3: State the final conclusion: They improve user experience","steps":["Step 1: Identify key concept: Define the required principles for Cookies and Tracking.","Step 2: Apply governing rule: They save preferences and time.","Step 3: State the final conclusion: They improve user experience"],"options":[],"conceptId":"computer_internet_web_cookies_and_tracking","skillId":"computer_internet_web","subskillId":"computer_internet_web_q5","subject":"computer","chapter":"internet_web","topic":"Cookies and Tracking"}', 4),
  (8163, 2111, 'State one risk of cookies', 'text', 1, 'Think privacy', '{"why":"Cookies can track user behavior.","sol":"Step 1: Identify key concept: Define the required principles for Cookies and Tracking.\nStep 2: Apply governing rule: Cookies can track user behavior.\nStep 3: State the final conclusion: Privacy concerns","steps":["Step 1: Identify key concept: Define the required principles for Cookies and Tracking.","Step 2: Apply governing rule: Cookies can track user behavior.","Step 3: State the final conclusion: Privacy concerns"],"options":[],"conceptId":"computer_internet_web_cookies_and_tracking","skillId":"computer_internet_web","subskillId":"computer_internet_web_q6","subject":"computer","chapter":"internet_web","topic":"Cookies and Tracking"}', 5),
