  (4103, 3053, 'It remains fluorine and forms F+ with relative charge +1.', TRUE),
  (4104, 3054, 'A neutron is an uncharged nuclear particle with relative mass approximately 1.', TRUE),
  (4105, 3055, '12 neutrons.', TRUE),
