  (4120, 3070, 'The statement is incorrect. Sodium remains sodium because it still has 11 protons; losing one electron forms Na+.', TRUE),
  (4121, 3071, '29 protons; copper.', TRUE),
  (4122, 3072, 'Atomic number is the number of protons in the nucleus; its symbol is Z.', TRUE),
  (4123, 3073, '8 protons; oxygen.', TRUE),
