  (4127, 3077, '12 protons; magnesium.', TRUE),
  (4128, 3078, 'They cannot be isotopes because their atomic numbers and proton numbers differ.', TRUE),
  (4129, 3079, 'Sulfur; 18 electrons; charge -2 (S2-).', TRUE),
  (4130, 3080, 'The atomic number is 11. The value 23 is the mass number, not the atomic number.', TRUE),
  (4131, 3081, 'Mass number is the total number of protons and neutrons in the nucleus. A = Z + n.', TRUE),
  (4132, 3082, '23.', TRUE),
