  (4616, 3566, 'The solution is acidic because its pH of 4 is below 7.', TRUE),
  (4617, 3567, 'Aqueous hydrochloric acid conducts electricity because it contains mobile ions that carry electric charge.', TRUE),
  (4618, 3568, 'An aqueous acid turns blue litmus red because of its acidic nature. It has a pH below 7 under the usual school-level conditions. It also conducts electricity because it contains mobile ions.', TRUE),
  (4619, 3569, 'Metal + Acid → Salt + Hydrogen', TRUE),
  (4620, 3570, 'Mg + 2HCl → MgCl2 + H2', TRUE),
  (4621, 3571, 'Zn + H2SO4 → ZnSO4 + H2', TRUE),
